## 3) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var title: String
    var detail: String
    var createdAt: Date
    var tintHex: String

    @Attribute(.transformable)
    var completionDates: [Date]

    init(title: String, detail: String = "", tintHex: String = "#4F46E5") {
        self.title = title
        self.detail = detail
        self.createdAt = Date()
        self.tintHex = tintHex
        self.completionDates = []
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var current = first
        var count = 1

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: current),
               calendar.isDate(date, inSameDayAs: expected) {
                current = date
                count += 1
            } else if calendar.isDate(date, inSameDayAs: current) {
                continue
            } else {
                break
            }
        }

        return count
    }

    var didCompleteToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }

    func markCompletedToday() {
        let today = Calendar.current.startOfDay(for: Date())
        if !didCompleteToday {
            completionDates.append(today)
        }
    }
}
```

