import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @Bindable var habit: Habit

    var body: some View {
        VStack(spacing: 24) {
            Text(habit.title)
                .font(.largeTitle.bold())
                .multilineTextAlignment(.center)

            if !habit.detail.isEmpty {
                Text(habit.detail)
                    .foregroundStyle(.secondary)
                    .multilineTextAlignment(.center)
            }

            VStack(spacing: 12) {
                Text("Current Streak")
                    .font(.headline)
                    .foregroundStyle(.secondary)

                Text("\(habit.streak)")
                    .font(.system(size: 54, weight: .bold))
                    .foregroundStyle(Color(hex: habit.tintHex))
            }
            .frame(maxWidth: .infinity)
            .padding()
            .background(Color(.secondarySystemBackground))
            .clipShape(RoundedRectangle(cornerRadius: 20))

            Button {
                habit.markCompletedToday()
                try? modelContext.save()
            } label: {
                Label(
                    habit.didCompleteToday ? "Completed Today" : "Mark Complete",
                    systemImage: "checkmark.circle.fill"
                )
                .frame(maxWidth: .infinity)
                .padding()
                .background(habit.didCompleteToday ? Color.green.opacity(0.2) : Color(hex: habit.tintHex))
                .foregroundStyle(habit.didCompleteToday ? .green : .white)
                .clipShape(RoundedRectangle(cornerRadius: 16))
            }
            .disabled(habit.didCompleteToday)

            Spacer()
        }
        .padding()
        .navigationTitle("Habit")
        .navigationBarTitleDisplayMode(.inline)
    }
}
