## 1) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    var id: UUID = UUID()
    var name: String
    var notes: String = ""
    var colorHex: String = "4F46E5"
    var createdAt: Date = Date()
    var completedDates: [Date] = []

    var streak: Int {
        let calendar = Calendar.current
        let dates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        var streakCount = 1
        var currentDate = dates[0]

        for date in dates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streakCount += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streakCount
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        return completedDates.contains(where: { calendar.isDate($0, inSameDayAs: today) })
    }

    mutating func toggleCompletedToday() {
        let calendar = Calendar.current
        if let index = completedDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: Date()) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(Date())
        }
    }
}
```

