## 2) Habit model

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var detail: String
    var createdAt: Date
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \Completion.habit)
    var completions: [Completion] = []

    init(name: String, detail: String = "", createdAt: Date = .now, colorHex: String = "#4F46E5") {
        self.name = name
        self.detail = detail
        self.createdAt = createdAt
        self.colorHex = colorHex
    }

    var streak: Int {
        let dates = Set(completions.map { Calendar.current.startOfDay(for: $0.date) })
            .sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        let calendar = Calendar.current
        var currentStreak = 1
        var previousDate = dates[0]

        for date in dates.dropFirst() {
            guard let expected = calendar.date(byAdding: .day, value: -1, to: previousDate),
                  calendar.isDate(date, inSameDayAs: expected) else {
                break
            }
            currentStreak += 1
            previousDate = date
        }

        return currentStreak
    }

    func completed(on date: Date) -> Bool {
        let target = Calendar.current.startOfDay(for: date)
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: target) }
    }
}
```

