## 3) `HabitStore.swift`

```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            saveHabits()
        }
    }

    private let storageKey = "habit_tracker_habits"

    init() {
        loadHabits()
    }

    // MARK: - CRUD

    func addHabit(name: String, symbol: String, colorHex: String) {
        let habit = Habit(name: name, symbol: symbol, colorHex: colorHex)
        habits.insert(habit, at: 0)
    }

    func updateHabit(_ habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index] = habit
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    // MARK: - Completion

    func toggleCompletion(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }

        let today = Calendar.current.startOfDay(for: Date())
        let completionDates = habits[index].completedDates.map { Calendar.current.startOfDay(for: $0) }

        if let existingIndex = completionDates.firstIndex(of: today) {
            habits[index].completedDates.remove(at: existingIndex)
        } else {
            habits[index].completedDates.append(today)
        }
    }

    func isCompletedToday(_ habit: Habit) -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return habit.completedDates.contains { Calendar.current.startOfDay(for: $0) == today }
    }

    func streak(for habit: Habit) -> Int {
        let sortedDates = habit.completedDates
            .map { Calendar.current.startOfDay(for: $0) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        let calendar = Calendar.current
        var streak = 1
        var currentDate = sortedDates[0]

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else {
                break
            }
        }

        return streak
    }

    // MARK: - Persistence

    private func saveHabits() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: storageKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func loadHabits() {
        guard let data = UserDefaults.standard.data(forKey: storageKey) else { return }
        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
        }
    }
}
```

