import SwiftUI

struct AddEditHabitView: View {
    enum Mode {
        case add
        case edit(Habit)
    }

    @Environment(\.dismiss) private var dismiss
    @EnvironmentObject var store: HabitStore

    let mode: Mode

    @State private var name: String = ""
    @State private var symbol: String = "checkmark.circle"
    @State private var colorHex: String = "#4CAF50"

    private var isEditMode: Bool {
        if case .edit = mode { return true }
        return false
    }

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit Details") {
                    TextField("Habit Name", text: $name)
                    TextField("SF Symbol", text: $symbol)
                    TextField("Color Hex", text: $colorHex)
                }

                Section("Preview") {
                    HStack {
                        Image(systemName: symbol)
                            .foregroundStyle(Color(hex: colorHex))
                        Text(name.isEmpty ? "Habit Name" : name)
                    }
                }
            }
            .navigationTitle(isEditMode ? "Edit Habit" : "Add Habit")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }

                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        save()
                        dismiss()
                    }
                    .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
            .onAppear {
                if case .edit(let habit) = mode {
                    name = habit.name
                    symbol = habit.symbol
                    colorHex = habit.colorHex
                }
            }
        }
    }

    private func save() {
        switch mode {
        case .add:
            store.addHabit(name: name, symbol: symbol, colorHex: colorHex)
        case .edit(let habit):
            var updated = habit
            updated.name = name
            updated.symbol = symbol
            updated.colorHex = colorHex
            store.updateHabit(updated)
        }
    }
