```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetPerDay: Int
    var isArchived: Bool

    @Attribute(.transformable)
    var completions: [Date]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetPerDay: Int = 1
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerDay = targetPerDay
        self.isArchived = false
        self.completions = []
    }

    var completionCount: Int {
        completions.count
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        return completions.contains { calendar.isDateInToday($0) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completions.sorted(by: >)

        guard let latest = sortedDates.first else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: latest)

        for date in sortedDates {
            let day = calendar.startOfDay(for: date)
            if day == currentDate {
                streak += 1
                if let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) {
                    currentDate = previousDay
                }
            } else if day < currentDate {
                break
            }
        }

        return streak
    }

    func markComplete() {
        completions.append(Date())
    }

    func removeTodayCompletion() {
        let calendar = Calendar.current
        completions.removeAll { calendar.isDateInToday($0) }
    }
}
