```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetDaysPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitLog.habit)
    var logs: [HabitLog] = []

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7,
        createdAt: Date = .now
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.colorHex = colorHex
        self.targetDaysPerWeek = targetDaysPerWeek
        self.createdAt = createdAt
    }

    var completedToday: Bool {
        Calendar.current.isDateInToday(logs.first(where: { Calendar.current.isDateInToday($0.date) })?.date ?? .distantPast)
    }

    var totalCompletions: Int {
        logs.count
    }

    var streak: Int {
        let sortedDates = logs.map { Calendar.current.startOfDay(for: $0.date) }.sorted(by: >)
        guard !sortedDates.isEmpty else { return 0 }

        let calendar = Calendar.current
        var streakCount = 0
        var currentDate = calendar.startOfDay(for: .now)

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: currentDate) {
                streakCount += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate)!
            } else if date < currentDate {
                break
            }
        }
        return streakCount
    }

    func isCompleted(on date: Date) -> Bool {
        let day = Calendar.current.startOfDay(for: date)
        return logs.contains(where: { Calendar.current.isDate($0.date, inSameDayAs: day) })
    }
}

@Model
final class HabitLog {
    var id: UUID
    var date: Date
    var habit: Habit?

    init(date: Date = .now, habit: Habit? = nil) {
        self.id = UUID()
        self.date = date
        self.habit = habit
    }
}
