### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var colorHex: String
    var createdAt: Date

    @Relationship(deleteRule: .cascade, inverse: \HabitLog.habit)
    var logs: [HabitLog] = []

    init(name: String, habitDescription: String = "", colorHex: String = "#4F46E5") {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.colorHex = colorHex
        self.createdAt = Date()
    }

    var completionCount: Int {
        logs.count
    }

    var currentStreak: Int {
        let sortedDates = logs.map { Calendar.current.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        let calendar = Calendar.current
        var streak = 1
        var currentDate = sortedDates[0]

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }

    var longestStreak: Int {
        let dates = Set(logs.map { Calendar.current.startOfDay(for: $0.date) }).sorted()
        guard !dates.isEmpty else { return 0 }

        let calendar = Calendar.current
        var best = 1
        var current = 1

        for i in 1..<dates.count {
            if let expected = calendar.date(byAdding: .day, value: 1, to: dates[i - 1]),
               calendar.isDate(dates[i], inSameDayAs: expected) {
                current += 1
            } else {
                best = max(best, current)
                current = 1
            }
        }

        return max(best, current)
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let day = Calendar.current.startOfDay(for: date)
        return logs.contains { Calendar.current.isDate($0.date, inSameDayAs: day) }
    }
}
