## 2) Models

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var title: String
    var habitDescription: String
    var createdAt: Date
    var targetPerWeek: Int
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        title: String,
        habitDescription: String = "",
        targetPerWeek: Int = 7,
        createdAt: Date = Date(),
        isArchived: Bool = false
    ) {
        self.id = UUID()
        self.title = title
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.targetPerWeek = targetPerWeek
        self.isArchived = isArchived
        self.completions = []
    }

    var sortedCompletions: [HabitCompletion] {
        completions.sorted { $0.date > $1.date }
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let calendar = Calendar.current
        return completions.contains {
            calendar.isDate($0.date, inSameDayAs: date)
        }
    }

    func toggleCompletion(for date: Date = Date(), context: ModelContext) {
        let calendar = Calendar.current
        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            context.delete(existing)
        } else {
            let completion = HabitCompletion(date: date, habit: self)
            context.insert(completion)
            completions.append(completion)
        }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let dates = Set(completions.map { calendar.startOfDay(for: $0.date) })
        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while dates.contains(day) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previous
        }

        return streak
    }

    func completionsInLast7Days() -> Int {
        let calendar = Calendar.current
        let start = calendar.date(byAdding: .day, value: -6, to: calendar.startOfDay(for: Date()))!
        return completions.filter { $0.date >= start }.count
    }
}
