### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var targetDaysPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(name: String, details: String = "", targetDaysPerWeek: Int = 7) {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.targetDaysPerWeek = targetDaysPerWeek
    }

    var completedDates: [Date] {
        completions.map { $0.date }.sorted()
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completions.contains { calendar.isDate($0.date, inSameDayAs: date) }
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDays = completions
            .map { calendar.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sortedDays.isEmpty else { return 0 }

        var streakCount = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for day in sortedDays {
            if calendar.isDate(day, inSameDayAs: expectedDate) {
                streakCount += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expectedDate)!
            } else if day < expectedDate {
                break
            }
        }

        return streakCount
    }
}
```

