                }

                HStack {
                    Text("Target")
                    Spacer()
                    Text("\(habit.targetDaysPerWeek) days/week")
                        .foregroundStyle(.secondary)
                }
            }

            Section("Today") {
                Button {
                    toggleTodayCompletion()
                } label: {
                    HStack {
                        Text(habit.isCompleted(on: Date()) ? "Mark as incomplete" : "Mark as complete")
                        Spacer()
                        Image(systemName: habit.isCompleted(on: Date()) ? "checkmark.circle.fill" : "circle")
                    }
                }
            }

            Section("History") {
                if habit.completions.isEmpty {
                    Text("No completions yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(habit.completions.sorted(by: { $0.date > $1.date })) { completion in
                        HStack {
                            Text(completion.date, style: .date)
                            Spacer()
                            Text(completion.date, style: .time)
                                .foregroundStyle(.secondary)
                        }
                    }
                }
