### `Models/Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var colorHex: String
    var targetCountPerDay: Int
    var archived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        details: String = "",
        colorHex: String = "#4F46E5",
        targetCountPerDay: Int = 1,
        archived: Bool = false
    ) {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetCountPerDay = targetCountPerDay
        self.archived = archived
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completions
            .map(\.completedAt)
            .sorted(by: >)

        guard let latest = sortedDates.first else { return 0 }

        var count = 0
        var currentDate = calendar.startOfDay(for: latest)

        while true {
            let hasCompletionOnDay = sortedDates.contains {
                calendar.isDate($0, inSameDayAs: currentDate)
            }

            if hasCompletionOnDay {
                count += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
                currentDate = previousDay
            } else {
                break
            }
        }

        return count
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        return completions.contains { completion in
            calendar.isDateInToday(completion.completedAt)
        }
    }

    func completionCount(for date: Date = Date()) -> Int {
        let calendar = Calendar.current
        return completions.filter { calendar.isDate($0.completedAt, inSameDayAs: date) }.count
    }

    func canMarkCompleteToday() -> Bool {
        completionCount() < targetCountPerDay
    }
}
```

