## 3) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var lastCompletedAt: Date?
    var streak: Int
    var timesCompleted: Int

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        createdAt: Date = .now,
        lastCompletedAt: Date? = nil,
        streak: Int = 0,
        timesCompleted: Int = 0
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.lastCompletedAt = lastCompletedAt
        self.streak = streak
        self.timesCompleted = timesCompleted
    }

    var isCompletedToday: Bool {
        guard let lastCompletedAt else { return false }
        return Calendar.current.isDateInToday(lastCompletedAt)
    }

    func markCompleted() {
        let now = Date()

        if let lastCompletedAt {
            if Calendar.current.isDate(lastCompletedAt, inSameDayAs: now) {
                return
            }

            if let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: now),
               Calendar.current.isDate(lastCompletedAt, inSameDayAs: yesterday) {
                streak += 1
            } else {
                streak = 1
            }
        } else {
            streak = 1
        }

        self.lastCompletedAt = now
        timesCompleted += 1
    }

    func resetCompletion() {
        lastCompletedAt = nil
        streak = 0
    }
}
```

