## 2) `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var habitDescription: String
    var createdAt: Date
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \Completion.habit)
    var completions: [Completion]

    init(name: String, habitDescription: String = "", createdAt: Date = .now, isArchived: Bool = false) {
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completions = []
    }

    var streak: Int {
        let sorted = completions.map { $0.date }.sorted(by: >)
        guard let mostRecent = sorted.first else { return 0 }

        let calendar = Calendar.current
        var streakCount = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for date in sorted {
            let normalized = calendar.startOfDay(for: date)
            if normalized == expectedDate {
                streakCount += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: expectedDate) else { break }
                expectedDate = previousDay
            } else if normalized < expectedDate {
                continue
            } else {
                break
            }
        }

        // If the most recent completion isn't today or yesterday, streak should be 0
        let today = calendar.startOfDay(for: Date())
        let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!
        let mostRecentDay = calendar.startOfDay(for: mostRecent)
        if mostRecentDay != today && mostRecentDay != yesterday {
            return 0
        }

        return streakCount
    }

    func completedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.startOfDay(for: $0.date) == today }
    }
}
```

