@Observable
final class HabitViewModel {
    var name: String = ""
    var description: String = ""

    func addHabit(context: ModelContext) {
        let habit = Habit(name: name, habitDescription: description)
        context.insert(habit)
        name = ""
        description = ""
        try? context.save()
    }

    func toggleCompletion(for habit: Habit, context: ModelContext) {
        let today = Calendar.current.startOfDay(for: Date())

        if let existing = habit.completions.first(where: { Calendar.current.startOfDay(for: $0.date) == today }) {
            context.delete(existing)
        } else {
            let completion = Completion(date: .now, habit: habit)
            habit.completions.append(completion)
            context.insert(completion)
        }

        try? context.save()
    }

    func deleteHabit(_ habit: Habit, context: ModelContext) {
        context.delete(habit)
        try? context.save()
    }
}
