## 2) SwiftData Models

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(name: String, details: String = "") {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.isArchived = false
        self.completions = []
    }

    var streak: Int {
        let sortedDates = completions
            .map { Calendar.current.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 1
        var current = sortedDates[0]

        for date in sortedDates.dropFirst() {
            guard let expected = Calendar.current.date(byAdding: .day, value: -1, to: current),
                  Calendar.current.isDate(date, inSameDayAs: expected) else {
                break
            }
            streak += 1
            current = date
        }

        return streak
    }

    func completedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: today) }
    }
}

@Model
final class HabitCompletion {
    var id: UUID
    var date: Date
    var habit: Habit?

    init(date: Date = Date(), habit: Habit? = nil) {
        self.id = UUID()
        self.date = date
        self.habit = habit
    }
}
```

