        colorHex: String = "#4F46E5",
        createdAt: Date = .now,
        isArchived: Bool = false
    ) {
        self.id = UUID()
        self.title = title
        self.habitDescription = habitDescription
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completions = []
    }

    var streak: Int {
        let dates = completions
            .map { Calendar.current.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        var streakCount = 1
        var currentDate = dates[0]

        for i in 1..<dates.count {
            let previous = dates[i]
            if Calendar.current.date(byAdding: .day, value: -1, to: currentDate) == previous {
                streakCount += 1
                currentDate = previous
            } else if currentDate != previous {
                break
            }
        }

        return streakCount
    }

    func isCompleted(on date: Date = .now) -> Bool {
        let day = Calendar.current.startOfDay(for: date)
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: day) }
    }

    func completionCount(in days: Int = 30) -> Int {
        let start = Calendar.current.date(byAdding: .day, value: -days, to: .now) ?? .distantPast
        return completions.filter { $0.date >= start }.count
    }
}
