## 2) Data Model

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var isArchived: Bool

    // Dates the habit was completed
    @Attribute(.externalStorage)
    var completionDatesData: Data?

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        isArchived: Bool = false,
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completionDatesData = try? JSONEncoder().encode(completionDates)
    }

    var completionDates: [Date] {
        get {
            guard let completionDatesData,
                  let decoded = try? JSONDecoder().decode([Date].self, from: completionDatesData) else {
                return []
            }
            return decoded
        }
        set {
            completionDatesData = try? JSONEncoder().encode(newValue)
        }
    }

    var currentStreak: Int {
        let dates = Set(completionDates.map { Calendar.current.startOfDay(for: $0) })
        var streak = 0
        var day = Calendar.current.startOfDay(for: Date())

        while dates.contains(day) {
            streak += 1
            guard let previous = Calendar.current.date(byAdding: .day, value: -1, to: day) else { break }
            day = previous
        }
        return streak
    }

    var completedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completionDates.contains { Calendar.current.startOfDay(for: $0) == today }
    }

    func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())
        var dates = completionDates.map { Calendar.current.startOfDay(for: $0) }

        if let index = dates.firstIndex(of: today) {
            dates.remove(at: index)
        } else {
            dates.append(today)
        }

        completionDates = dates
    }
}
```

