### `HabitStore.swift`
```swift
import Foundation

enum HabitStore {
    static func normalizeDates(_ dates: [Date]) -> [Date] {
        let calendar = Calendar.current
        let normalized = dates.map { calendar.startOfDay(for: $0) }
        return Array(Set(normalized)).sorted()
    }

    static func isCompletedToday(_ habit: Habit) -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return normalizeDates(habit.completionDates).contains(today)
    }

    static func toggleToday(_ habit: Habit) {
        let today = Calendar.current.startOfDay(for: Date())
        var dates = normalizeDates(habit.completionDates)

        if let index = dates.firstIndex(of: today) {
            dates.remove(at: index)
        } else {
            dates.append(today)
        }

        habit.completionDates = dates
    }

    static func currentStreak(_ habit: Habit) -> Int {
        let dates = Set(normalizeDates(habit.completionDates))
        var streak = 0
        var day = Calendar.current.startOfDay(for: Date())

        while dates.contains(day) {
            streak += 1
            guard let previous = Calendar.current.date(byAdding: .day, value: -1, to: day) else { break }
            day = previous
        }
        return streak
    }
}
