### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var tintHex: String

    @Relationship(deleteRule: .cascade)
    var completions: [HabitCompletion] = []

    init(name: String, details: String = "", tintHex: String = "#4F46E5") {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.tintHex = tintHex
    }

    var completedDates: [Date] {
        completions.map { $0.date }.sorted()
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let calendar = Calendar.current
        return completions.contains { calendar.isDate($0.date, inSameDayAs: date) }
    }

    func toggleCompletion(on date: Date = Date()) {
        let calendar = Calendar.current

        if let existing = completions.first(where: { calendar.isDate($0.date, inSameDayAs: date) }) {
            completions.removeAll { $0.id == existing.id }
        } else {
            completions.append(HabitCompletion(date: date, habit: self))
        }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let days = Set(completions.map { calendar.startOfDay(for: $0.date) }).sorted()
        guard !days.isEmpty else { return 0 }

        var streak = 0
        var cursor = calendar.startOfDay(for: Date())

        while days.contains(cursor) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: cursor) else { break }
            cursor = previous
        }

        return streak
    }
