## 4) Streak + check-in logic: `HabitLogic.swift`

```swift
import Foundation

struct HabitLogic {
    static func checkedInToday(_ habit: Habit) -> Bool {
        Calendar.current.isDateInToday(habit.checkIns.sorted(by: { $0.date < $1.date }).last?.date ?? .distantPast)
    }

    static func streakCount(_ habit: Habit) -> Int {
        let calendar = Calendar.current
        let dates = habit.checkIns
            .map { calendar.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        var streak = 1
        var current = dates[0]

        for date in dates.dropFirst() {
            guard let expected = calendar.date(byAdding: .day, value: -1, to: current) else { break }
            if calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                current = date
            } else if !calendar.isDate(date, inSameDayAs: current) {
                break
            }
        }

        return streak
    }

    static func totalCheckIns(_ habit: Habit) -> Int {
        habit.checkIns.count
    }

    static func markTodayCheckIn(_ habit: Habit) {
        let today = Calendar.current.startOfDay(for: Date())
        let alreadyCheckedIn = habit.checkIns.contains {
            Calendar.current.isDate($0.date, inSameDayAs: today)
        }

        guard !alreadyCheckedIn else { return }

        habit.checkIns.append(HabitCheckIn(date: Date()))
    }
}
