            .navigationTitle(title)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        save()
                    }
                    .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
            .onAppear(perform: loadIfNeeded)
        }
    }

    private var title: String {
        switch mode {
        case .add: return "New Habit"
        case .edit: return "Edit Habit"
        }
    }

    private func loadIfNeeded() {
        guard case .edit(let habit) = mode else { return }
        name = habit.name
        notes = habit.notes
        targetPerWeek = habit.targetPerWeek
        colorHex = habit.colorHex
    }

    private func save() {
        switch mode {
        case .add:
            let habit = Habit(name: name, notes: notes, targetPerWeek: targetPerWeek, colorHex: colorHex)
            modelContext.insert(habit)
        case .edit(let habit):
            habit.name = name
            habit.notes = notes
            habit.targetPerWeek = targetPerWeek
            habit.colorHex = colorHex
        }
        dismiss()
    }
}
