# 2) Data Models

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var colorHex: String
    var targetPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCheckIn.habit)
    var checkIns: [HabitCheckIn]

    init(
        name: String,
        details: String = "",
        colorHex: String = "#4F46E5",
        targetPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerWeek = targetPerWeek
        self.checkIns = []
    }

    var streak: Int {
        let sortedDates = checkIns.map { $0.date }.sorted(by: >)
        guard !sortedDates.isEmpty else { return 0 }

        var streakCount = 0
        var currentDate = Calendar.current.startOfDay(for: Date())

        for date in sortedDates {
            let normalized = Calendar.current.startOfDay(for: date)
            if normalized == currentDate {
                streakCount += 1
                currentDate = Calendar.current.date(byAdding: .day, value: -1, to: currentDate)!
            } else if normalized < currentDate {
                break
            }
        }

        return streakCount
    }

    var completedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return checkIns.contains {
            Calendar.current.startOfDay(for: $0.date) == today
        }
    }

    var totalCompletions: Int {
        checkIns.count
    }

    func toggleTodayCompletion() {
        let today = Calendar.current.startOfDay(for: Date())

        if let existing = checkIns.first(where: {
            Calendar.current.startOfDay(for: $0.date) == today
        }) {
            checkIns.removeAll { $0.id == existing.id }
        } else {
            checkIns.append(HabitCheckIn(date: Date()))
        }
    }
}
