## 3) Model

### `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var colorHex: String
    var createdAt: Date
    var isArchived: Bool

    @Attribute(.transformable)
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        colorHex: String = "#4F46E5",
        createdAt: Date = Date(),
        isArchived: Bool = false,
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completionDates = completionDates
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: previousDay) {
                streakCount += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streakCount
    }

    var completedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }

    func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }

    var totalCompletions: Int {
        completionDates.count
    }
}
```

