```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var reminderTime: Date?
    var targetPerDay: Int
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        reminderTime: Date? = nil,
        targetPerDay: Int = 1,
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.reminderTime = reminderTime
        self.targetPerDay = targetPerDay
        self.completions = completions
    }

    var totalCompletions: Int {
        completions.count
    }

    var todayCompletions: Int {
        completions.filter { Calendar.current.isDateInToday($0.date) }.count
    }

    var isCompletedToday: Bool {
        todayCompletions >= targetPerDay
    }

    var currentStreak: Int {
        let grouped = Dictionary(grouping: completions) { completion in
            Calendar.current.startOfDay(for: completion.date)
        }

        var streak = 0
        var currentDate = Calendar.current.startOfDay(for: Date())

        while let completionsForDay = grouped[currentDate], completionsForDay.count >= targetPerDay {
            streak += 1
            guard let previousDate = Calendar.current.date(byAdding: .day, value: -1, to: currentDate) else {
                break
            }
            currentDate = previousDate
        }

        return streak
    }
}
