## 2) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var note: String
    var colorHex: String
    var createdAt: Date
    var lastCompletedAt: Date?
    var currentStreak: Int
    var bestStreak: Int

    init(
        name: String,
        note: String = "",
        colorHex: String = "#4F46E5",
        createdAt: Date = .now,
        lastCompletedAt: Date? = nil,
        currentStreak: Int = 0,
        bestStreak: Int = 0
    ) {
        self.id = UUID()
        self.name = name
        self.note = note
        self.colorHex = colorHex
        self.createdAt = createdAt
        self.lastCompletedAt = lastCompletedAt
        self.currentStreak = currentStreak
        self.bestStreak = bestStreak
    }

    func markCompleted() {
        let calendar = Calendar.current
        let now = Date()

        if let lastCompletedAt {
            if calendar.isDateInToday(lastCompletedAt) {
                return
            } else if calendar.isDateInYesterday(lastCompletedAt) {
                currentStreak += 1
            } else {
                currentStreak = 1
            }
        } else {
            currentStreak = 1
        }

        lastCompletedAt = now
        bestStreak = max(bestStreak, currentStreak)
    }

    func resetCompletion() {
        if let lastCompletedAt, Calendar.current.isDateInToday(lastCompletedAt) {
            self.lastCompletedAt = nil
            self.currentStreak = max(0, self.currentStreak - 1)
        }
    }

    var isCompletedToday: Bool {
        guard let lastCompletedAt else { return false }
        return Calendar.current.isDateInToday(lastCompletedAt)
    }
}
