## 2) Models

### `Models/Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        isArchived: Bool = false,
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completions = completions
    }

    var completionCount: Int {
        completions.count
    }

    func isCompleted(on date: Date = .now) -> Bool {
        let day = date.startOfDay
        return completions.contains { $0.date.startOfDay == day }
    }

    func streakCount() -> Int {
        let sorted = completions
            .map { $0.date.startOfDay }
            .sorted(by: >)

        guard !sorted.isEmpty else { return 0 }

        var streak = 0
        var currentDay = Date().startOfDay

        while sorted.contains(currentDay) {
            streak += 1
            guard let previous = Calendar.current.date(byAdding: .day, value: -1, to: currentDay) else {
                break
            }
            currentDay = previous
        }

        return streak
    }
}
```

