## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String, details: String = "") {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.completedDates = []
    }

    var todayCompleted: Bool {
        completedDates.contains(where: { $0.isSameDay(as: Date()) })
    }

    var streak: Int {
        let calendar = Calendar.current
        let dates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        var count = 1
        var currentDate = dates[0]

        for date in dates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                count += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return count
    }

    func toggleCompletionForToday() {
        let today = Date()

        if let index = completedDates.firstIndex(where: { $0.isSameDay(as: today) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }
}
