## 2) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var details: String
    var isDaily: Bool
    var creationDate: Date
    var completionDates: Set<DateValue>

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        isDaily: Bool = true,
        creationDate: Date = Date(),
        completionDates: Set<DateValue> = []
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.isDaily = isDaily
        self.creationDate = creationDate
        self.completionDates = completionDates
    }

    func isCompleted(on date: Date, calendar: Calendar = .current) -> Bool {
        completionDates.contains(DateValue(date: date, calendar: calendar))
    }

    mutating func toggleCompletion(on date: Date, calendar: Calendar = .current) {
        let value = DateValue(date: date, calendar: calendar)
        if completionDates.contains(value) {
            completionDates.remove(value)
        } else {
            completionDates.insert(value)
        }
    }
}

struct DateValue: Hashable, Codable {
    let year: Int
    let month: Int
    let day: Int

    init(date: Date, calendar: Calendar = .current) {
        let comps = calendar.dateComponents([.year, .month, .day], from: date)
        self.year = comps.year ?? 0
        self.month = comps.month ?? 0
        self.day = comps.day ?? 0
    }
}
```

