## 3) `HabitStore.swift`

```swift
import Foundation
import SwiftUI

final class HabitStore: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            save()
        }
    }

    private let storageKey = "stored_habits"

    init() {
        load()
    }

    func addHabit(name: String, details: String, isDaily: Bool) {
        let habit = Habit(name: name, details: details, isDaily: isDaily)
        habits.insert(habit, at: 0)
    }

    func updateHabit(_ habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index] = habit
    }

    func deleteHabits(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func toggleHabitCompletion(_ habit: Habit, on date: Date = Date()) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index].toggleCompletion(on: date)
    }

    func completionCount(for habit: Habit) -> Int {
        habit.completionDates.count
    }

    func todayProgress() -> Double {
        guard !habits.isEmpty else { return 0 }
        let completedToday = habits.filter { $0.isCompleted(on: Date()) }.count
        return Double(completedToday) / Double(habits.count)
    }

    private func save() {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: storageKey)
        } catch {
            print("Failed to save habits: \(error)")
        }
    }

    private func load() {
        guard let data = UserDefaults.standard.data(forKey: storageKey) else { return }
        do {
            habits = try JSONDecoder().decode([Habit].self, from: data)
        } catch {
            print("Failed to load habits: \(error)")
        }
    }
}
```

