import SwiftUI

struct HabitEditorView: View {
    enum Mode {
        case add
        case edit(Habit)
    }

    @EnvironmentObject var store: HabitStore
    @Environment(\.dismiss) private var dismiss

    let mode: Mode

    @State private var name: String = ""
    @State private var details: String = ""
    @State private var isDaily: Bool = true

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit Details") {
                    TextField("Habit name", text: $name)
                    TextField("Details", text: $details, axis: .vertical)
                        .lineLimit(3...6)

                    Toggle("Daily habit", isOn: $isDaily)
                }
            }
            .navigationTitle(modeTitle)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") {
                        dismiss()
                    }
                }

                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        save()
                    }
                    .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
            .onAppear {
                loadIfNeeded()
            }
        }
    }

    private var modeTitle: String {
        switch mode {
        case .add:
            return "New Habit"
        case .edit:
            return "Edit Habit"
        }
    }

    private func loadIfNeeded() {
        guard case .edit(let habit) = mode else { return }
        name = habit.name
        details = habit.details
        isDaily = habit.isDaily
    }

    private func save() {
        switch mode {
        case .add:
            store.addHabit(
                name: name.trimmingCharacters(in: .whitespacesAndNewlines),
                details: details.trimmingCharacters(in: .whitespacesAndNewlines),
                isDaily: isDaily
            )
        case .edit(let habit):
            var updated = habit
            updated.name = name.trimmingCharacters(in: .whitespacesAndNewlines)
            updated.details = details.trimmingCharacters(in: .whitespacesAndNewlines)
            updated.isDaily = isDaily
            store.updateHabit(updated)
        }
        dismiss()
    }
}
