    var colorHex: String

    // Store dates when habit was completed
    @Attribute(.transformable)
    var completionDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5"
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.isArchived = false
        self.colorHex = colorHex
        self.completionDates = []
    }

    func markCompleted(on date: Date = Date()) {
        let normalized = Calendar.current.startOfDay(for: date)
        if !completionDates.contains(normalized) {
            completionDates.append(normalized)
        }
    }

    func unmarkCompleted(on date: Date = Date()) {
        let normalized = Calendar.current.startOfDay(for: date)
        completionDates.removeAll { Calendar.current.isDate($0, inSameDayAs: normalized) }
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let normalized = Calendar.current.startOfDay(for: date)
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: normalized) }
    }

    func streakCount(asOf date: Date = Date()) -> Int {
        let calendar = Calendar.current
        let sorted = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let latest = sorted.first else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: date)

        // If not completed today, streak still can count if yesterday was last completion
        if !calendar.isDate(latest, inSameDayAs: currentDate) {
            currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
        }

        for completedDate in sorted {
            if calendar.isDate(completedDate, inSameDayAs: currentDate) {
                streak += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
            } else if completedDate < currentDate {
                break
            }
        }
        return streak
    }
}
