import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var checkIns: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        checkIns: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.checkIns = checkIns
    }

    var completionCount: Int {
        checkIns.count
    }

    func didCheckInToday() -> Bool {
        Calendar.current.isDateInToday(checkIns.last ?? .distantPast)
    }

    func toggleTodayCheckIn() {
        if didCheckInToday() {
            if let last = checkIns.last, Calendar.current.isDateInToday(last) {
                checkIns.removeLast()
            }
        } else {
            checkIns.append(Date())
        }
    }
}
