## 5) Example enhancement: streak calculation

You can add this to `Habit.swift`:

```swift
var currentStreak: Int {
    let sortedDates = checkIns.sorted()
    guard !sortedDates.isEmpty else { return 0 }

    var streak = 1
    var currentDate = Calendar.current.startOfDay(for: sortedDates.last!)

    for index in stride(from: sortedDates.count - 2, through: 0, by: -1) {
        let previous = Calendar.current.startOfDay(for: sortedDates[index])
        if let expected = Calendar.current.date(byAdding: .day, value: -1, to: currentDate),
           previous == expected {
            streak += 1
            currentDate = previous
        } else {
            break
        }
    }
    return streak
}
```

