```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var colorHex: String
    var targetDaysPerWeek: Int

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        details: String = "",
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetDaysPerWeek = targetDaysPerWeek
    }

    var streak: Int {
        let days = Set(completions.map { Calendar.current.startOfDay(for: $0.date) })
        let sortedDays = days.sorted(by: >)

        var currentStreak = 0
        var expectedDate = Calendar.current.startOfDay(for: Date())

        while sortedDays.contains(expectedDate) {
            currentStreak += 1
            guard let previous = Calendar.current.date(byAdding: .day, value: -1, to: expectedDate) else {
                break
            }
            expectedDate = previous
        }

        return currentStreak
    }

    var completionCount: Int {
        completions.count
    }

    var isCompletedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.startOfDay(for: $0.date) == today }
    }
}
