### `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#007AFF"
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.completions = []
    }

    var streakCount: Int {
        let sorted = completions.sorted { $0.date > $1.date }
        guard !sorted.isEmpty else { return 0 }

        let calendar = Calendar.current
        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for completion in sorted {
            let completionDay = calendar.startOfDay(for: completion.date)
            if completionDay == expectedDate {
                streak += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expectedDate)!
            } else if completionDay < expectedDate {
                break
            }
        }

        return streak
    }

    func isCompletedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.startOfDay(for: $0.date) == today }
    }
}
```

