### `Models/Habit.swift`
```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var notes: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        notes: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.notes = notes
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    var completionCount: Int {
        completedDates.count
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        return completedDates.contains { calendar.isDate($0, inSameDayAs: Date()) }
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: expectedDate) {
                streak += 1
                if let previousDay = calendar.date(byAdding: .day, value: -1, to: expectedDate) {
                    expectedDate = previousDay
                }
            } else if date < expectedDate {
                // Only break if we’ve gone past the expected sequence
                break
            }
        }

        return streak
    }

    mutating func toggleCompletionForToday() {
        let calendar = Calendar.current
        if let index = completedDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: Date()) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(Date())
        }
    }
}
```

