### `ViewModels/HabitViewModel.swift`
```swift
import Foundation
import SwiftUI

final class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet {
            store.saveHabits(habits)
        }
    }

    private let store = HabitStore()

    init() {
        habits = store.loadHabits()
    }

    func addHabit(name: String, notes: String) {
        let habit = Habit(name: name, notes: notes)
        habits.insert(habit, at: 0)
    }

    func updateHabit(_ habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index] = habit
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }

    func toggleCompletion(for habit: Habit) {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else { return }
        habits[index].toggleCompletionForToday()
    }

    func habitBinding(for habit: Habit) -> Binding<Habit> {
        guard let index = habits.firstIndex(where: { $0.id == habit.id }) else {
            fatalError("Habit not found")
        }
        return $habits[index]
    }

    var totalCompletedToday: Int {
        habits.filter { $0.isCompletedToday }.count
    }
}
