## 2) Models

### `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var note: String
    var createdAt: Date
    var targetPerDay: Int
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        note: String = "",
        targetPerDay: Int = 1,
        isArchived: Bool = false
    ) {
        self.id = UUID()
        self.name = name
        self.note = note
        self.createdAt = Date()
        self.targetPerDay = targetPerDay
        self.isArchived = isArchived
    }

    var totalCompletions: Int {
        completions.count
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completions
            .map { calendar.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }

    var longestStreak: Int {
        let calendar = Calendar.current
        let uniqueDates = Array(Set(completions.map { calendar.startOfDay(for: $0.date) }))
            .sorted()

        guard !uniqueDates.isEmpty else { return 0 }

        var longest = 1
        var current = 1

        for i in 1..<uniqueDates.count {
            if let expected = calendar.date(byAdding: .day, value: 1, to: uniqueDates[i - 1]),
               calendar.isDate(uniqueDates[i], inSameDayAs: expected) {
                current += 1
                longest = max(longest, current)
            } else {
                current = 1
            }
        }

        return longest
    }
}
```

