import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var context
    let habit: Habit

    private var isCompletedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return habit.completions.contains {
            Calendar.current.isDate($0.date, inSameDayAs: today)
        }
    }

    var body: some View {
        Form {
            Section("Overview") {
                LabeledContent("Name", value: habit.name)
                LabeledContent("Note", value: habit.note.isEmpty ? "—" : habit.note)
                LabeledContent("Target / Day", value: "\(habit.targetPerDay)")
                LabeledContent("Total Completions", value: "\(habit.totalCompletions)")
                LabeledContent("Current Streak", value: "\(habit.currentStreak)")
                LabeledContent("Longest Streak", value: "\(habit.longestStreak)")
            }

            Section("Today") {
                Button {
                    toggleCompletionToday()
                } label: {
                    HStack {
                        Image(systemName: isCompletedToday ? "checkmark.circle.fill" : "circle")
                            .foregroundStyle(isCompletedToday ? .green : .secondary)
                        Text(isCompletedToday ? "Completed Today" : "Mark as Completed")
                    }
                }
            }

            if !habit.completions.isEmpty {
                Section("History") {
                    ForEach(habit.completions.sorted { $0.date > $1.date }, id: \.id) { completion in
                        Text(completion.date.formattedShort())
                    }
                }
            }
        }
        .navigationTitle(habit.name)
    }

    private func toggleCompletionToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let existing = habit.completions.first(where: {
            Calendar.current.isDate($0.date, inSameDayAs: today)
        }) {
            context.delete(existing)
        } else {
            let completion = HabitCompletion(date: Date(), habit: habit)
            context.insert(completion)
            habit.completions.append(completion)
        }
    }
}
