```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetPerDay: Int

    // Store completion dates as midnight-normalized dates
    @Attribute(.transformable)
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        colorHex: String = "#4F46E5",
        targetPerDay: Int = 1,
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.targetPerDay = targetPerDay
        self.completionDates = completionDates
    }

    func isCompleted(on date: Date = .now) -> Bool {
        let day = date.startOfDay
        return completionDates.contains(where: { $0.startOfDay == day })
    }

    func markCompleted(on date: Date = .now) {
        let day = date.startOfDay
        if !completionDates.contains(where: { $0.startOfDay == day }) {
            completionDates.append(day)
        }
    }

    func unmarkCompleted(on date: Date = .now) {
        let day = date.startOfDay
        completionDates.removeAll { $0.startOfDay == day }
    }

    var streak: Int {
        let completedDays = Set(completionDates.map { $0.startOfDay })
        var count = 0
        var current = Date().startOfDay

        while completedDays.contains(current) {
            count += 1
            guard let previous = Calendar.current.date(byAdding: .day, value: -1, to: current) else { break }
            current = previous
        }

        return count
    }

    var totalCompletions: Int {
        completionDates.count
    }
}
