    private func saveHabit() {
        if let habitToEdit {
            habitToEdit.name = name
            habitToEdit.habitDescription = descriptionText
            habitToEdit.colorHex = selectedColorHex
        } else {
            let habit = Habit(
                name: name,
                habitDescription: descriptionText,
                colorHex: selectedColorHex
