```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var colorHex: String

    // Store completion dates as normalized start-of-day values
    @Attribute(.transformable)
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        createdAt: Date = .now,
        colorHex: String = "#4F46E5",
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.completedDates = completedDates
    }

    func isCompleted(on date: Date = .now) -> Bool {
        let normalized = Calendar.current.startOfDay(for: date)
        return completedDates.contains(normalized)
    }

    func toggleCompletion(for date: Date = .now) {
        let normalized = Calendar.current.startOfDay(for: date)
        if let index = completedDates.firstIndex(of: normalized) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(normalized)
            completedDates.sort()
        }
    }

    var streak: Int {
        let calendar = Calendar.current
        let sorted = completedDates.map { calendar.startOfDay(for: $0) }.sorted(by: >)

        guard let first = sorted.first else { return 0 }

        var streakCount = 1
        var current = first

        for date in sorted.dropFirst() {
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: current) else { break }
            if calendar.isDate(date, inSameDayAs: previousDay) {
                streakCount += 1
                current = date
            } else {
                break
            }
        }
        return streakCount
    }

    var completionCount: Int {
        completedDates.count
    }
}
