## 4) Habit statistics helper

### `ViewModels/HabitStats.swift`

```swift
import Foundation

struct HabitStats {
    static func completionsForToday(_ habit: Habit) -> Int {
        let today = Date()
        return habit.completionDates.filter { $0.isSameDay(as: today) }.count
    }

    static func hasCompletedToday(_ habit: Habit) -> Bool {
        completionsForToday(habit) >= habit.targetCountPerDay
    }

    static func currentStreak(_ habit: Habit) -> Int {
        let calendar = Calendar.current
        let groupedByDay = Dictionary(grouping: habit.completionDates.map { $0.startOfDay }, by: { $0 })

        var streak = 0
        var day = Date().startOfDay

        while true {
            if groupedByDay[day] != nil {
                streak += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: day) else { break }
                day = previousDay
            } else {
                break
            }
        }

        return streak
    }

    static func totalCompletions(_ habit: Habit) -> Int {
        habit.completionDates.count
    }
}
