# 1) Data Models

## `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var creationDate: Date
    var targetDaysPerWeek: Int
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        creationDate: Date = .now,
        targetDaysPerWeek: Int = 7,
        colorHex: String = "#4F46E5",
        completions: [HabitCompletion] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.creationDate = creationDate
        self.targetDaysPerWeek = targetDaysPerWeek
        self.colorHex = colorHex
        self.completions = completions
    }

    var totalCompletions: Int {
        completions.count
    }

    var currentStreak: Int {
        let days = Set(completions.map { Calendar.current.startOfDay(for: $0.date) })
        var streak = 0
        var currentDay = Calendar.current.startOfDay(for: .now)

        while days.contains(currentDay) {
            streak += 1
            guard let previousDay = Calendar.current.date(byAdding: .day, value: -1, to: currentDay) else { break }
            currentDay = previousDay
        }

        return streak
    }

    func isCompleted(on date: Date = .now) -> Bool {
        let day = Calendar.current.startOfDay(for: date)
        return completions.contains { Calendar.current.startOfDay(for: $0.date) == day }
    }
}
```

