## 3) Habit Model

### `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var title: String
    var habitDescription: String
    var createdAt: Date
    var lastCompletedAt: Date?
    var streak: Int
    var colorHex: String

    init(
        title: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        lastCompletedAt: Date? = nil,
        streak: Int = 0,
        colorHex: String = "#4F46E5"
    ) {
        self.title = title
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.lastCompletedAt = lastCompletedAt
        self.streak = streak
        self.colorHex = colorHex
    }

    var isCompletedToday: Bool {
        guard let lastCompletedAt else { return false }
        return Calendar.current.isDateInToday(lastCompletedAt)
    }

    func markCompleted() {
        let now = Date()

        if let lastCompletedAt {
            if Calendar.current.isDateInToday(lastCompletedAt) {
                return
            }

            if Calendar.current.isDate(lastCompletedAt, inSameDayAs: Calendar.current.date(byAdding: .day, value: -1, to: now) ?? now) {
                streak += 1
            } else {
                streak = 1
            }
        } else {
            streak = 1
        }

        self.lastCompletedAt = now
    }

    func resetCompletionIfNeeded() {
        if let lastCompletedAt, !Calendar.current.isDateInToday(lastCompletedAt) {
            // No-op for now, but useful for future scheduling/rollover logic
        }
    }
}
```

