```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var title: String
    var detail: String
    var createdAt: Date
    var isArchived: Bool

    // Store completion days as normalized dates (start of day)
    @Attribute(.transformable)
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        title: String,
        detail: String = "",
        createdAt: Date = Date(),
        isArchived: Bool = false,
        completionDates: [Date] = []
    ) {
        self.id = id
        self.title = title
        self.detail = detail
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completionDates = completionDates
    }

    func normalized(date: Date) -> Date {
        Calendar.current.startOfDay(for: date)
    }

    func hasCompleted(on date: Date = Date()) -> Bool {
        let target = normalized(date: date)
        return completionDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: target) })
    }

    func toggleCompletion(for date: Date = Date()) {
        let target = normalized(date: date)

        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: target) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(target)
            completionDates.sort()
        }
    }
}
```

