## 3) Streak calculator

### `Services/HabitStreakCalculator.swift`
```swift
import Foundation

struct HabitStreakCalculator {
    static func currentStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let sortedDates = habit.completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let latest = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = latest

        for date in sortedDates.dropFirst() {
            guard let expected = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
            if calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else if calendar.isDate(date, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }

        return streak
    }

    static func bestStreak(for habit: Habit) -> Int {
        let calendar = Calendar.current
        let dates = Array(Set(habit.completionDates.map { calendar.startOfDay(for: $0) }))
            .sorted()

        guard !dates.isEmpty else { return 0 }

        var best = 1
        var current = 1

        for i in 1..<dates.count {
            if let expected = calendar.date(byAdding: .day, value: 1, to: dates[i - 1]),
               calendar.isDate(dates[i], inSameDayAs: expected) {
                current += 1
                best = max(best, current)
            } else {
                current = 1
            }
        }

        return best
    }
}
```

