## 2) Data Models

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var note: String
    var createdAt: Date
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(name: String, note: String = "") {
        self.id = UUID()
        self.name = name
        self.note = note
        self.createdAt = Date()
        self.isArchived = false
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completions
            .map { calendar.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: expectedDate) {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: expectedDate) else { break }
                expectedDate = previous
            } else if date < expectedDate {
                // streak broken
                break
            }
        }

        return streak
    }

    var completedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: today) }
    }
}
```

