## 2) Habit model

### `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var lastCompletedAt: Date?
    var completionDatesData: Data

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        lastCompletedAt: Date? = nil,
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.lastCompletedAt = lastCompletedAt
        self.completionDatesData = (try? JSONEncoder().encode(completionDates)) ?? Data()
    }

    var completionDates: [Date] {
        get {
            (try? JSONDecoder().decode([Date].self, from: completionDatesData)) ?? []
        }
        set {
            completionDatesData = (try? JSONEncoder().encode(newValue)) ?? Data()
        }
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let dates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        var streak = 1
        var currentDate = dates[0]

        for date in dates.dropFirst() {
            if let expectedYesterday = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expectedYesterday) {
                streak += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDateInToday($0) }
    }

    func markCompleted() {
        let today = Date()
        let calendar = Calendar.current

        if !completionDates.contains(where: { calendar.isDateInToday($0) }) {
            completionDates.append(today)
            lastCompletedAt = today
        }
    }

    func removeCompletion(for date: Date) {
        let calendar = Calendar.current
        completionDates.removeAll { calendar.isDate($0, inSameDayAs: date) }
        if let last = completionDates.sorted().last {
            lastCompletedAt = last
        } else {
            lastCompletedAt = nil
        }
    }
}
```

