```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completions: [Date]

    init(name: String, createdAt: Date = .now, completions: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completions = completions
    }

    func markCompletedToday() {
        let today = Calendar.current.startOfDay(for: Date())
        if !completions.contains(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completions.append(Date())
        }
    }

    func isCompletedToday() -> Bool {
        let today = Date()
        return completions.contains(where: { Calendar.current.isDate($0, inSameDayAs: today) })
    }

    func completionCount() -> Int {
        completions.count
    }
}
```

