### `Habit.swift`
```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completions: [String]   // stored as "yyyy-MM-dd"

    init(id: UUID = UUID(), name: String, completions: [String] = []) {
        self.id = id
        self.name = name
        self.completions = completions
    }

    mutating func markCompletedToday() {
        let today = Habit.dateKey(for: Date())
        if !completions.contains(today) {
            completions.append(today)
        }
    }

    func isCompletedToday() -> Bool {
        completions.contains(Habit.dateKey(for: Date()))
    }

    var totalCompletions: Int {
        completions.count
    }

    var currentStreak: Int {
        let dates = Set(completions)
        var streak = 0
        var date = Calendar.current.startOfDay(for: Date())

        while true {
            let key = Habit.dateKey(for: date)
            if dates.contains(key) {
                streak += 1
                guard let previous = Calendar.current.date(byAdding: .day, value: -1, to: date) else { break }
                date = previous
            } else {
                break
            }
        }
        return streak
    }

    static func dateKey(for date: Date) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale.current
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }
}
```

