## 2) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable {
    var id = UUID()
    var name: String
    var createdAt: Date = Date()
    var completedDates: [Date] = []

    func isCompletedToday() -> Bool {
        completedDates.contains { Calendar.current.isDateInToday($0) }
    }

    mutating func markCompletedToday() {
        if !isCompletedToday() {
            completedDates.append(Date())
        }
    }

    var streak: Int {
        let calendar = Calendar.current
        let dates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard !dates.isEmpty else { return 0 }

        var streakCount = 1
        var currentDate = dates[0]

        for date in dates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streakCount += 1
                currentDate = date
            } else {
                break
            }
        }

        return streakCount
    }
}
```

