import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completions: [String] // ISO date strings: "yyyy-MM-dd"

    init(id: UUID = UUID(), name: String, completions: [String] = []) {
        self.id = id
        self.name = name
        self.completions = completions
    }

    var streak: Int {
        let dates = Set(completions)
        var count = 0
        var current = Date()
        let formatter = HabitStore.dateFormatter

        while true {
            let dayString = formatter.string(from: current)
            if dates.contains(dayString) {
                count += 1
                current = Calendar.current.date(byAdding: .day, value: -1, to: current) ?? current
            } else {
                break
            }
        }
        return count
    }

    func isCompletedToday() -> Bool {
        let today = HabitStore.dateFormatter.string(from: Date())
        return completions.contains(today)
    }
}
