import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String, createdAt: Date = .now, completedDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompletedToday() -> Bool {
        Calendar.current.isDateInToday(completedDates.last ?? .distantPast)
    }

    func toggleTodayCompletion() {
        let calendar = Calendar.current
        if let last = completedDates.last, calendar.isDateInToday(last) {
            completedDates.removeLast()
        } else {
            completedDates.append(Date())
        }
    }
}
```

