import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var createdAt: Date
    var checkIns: [Date]

    init(id: UUID = UUID(), name: String, createdAt: Date = Date(), checkIns: [Date] = []) {
        self.id = id
        self.name = name
        self.createdAt = createdAt
        self.checkIns = checkIns
    }

    var totalCheckIns: Int {
        checkIns.count
    }

    var didCheckInToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return checkIns.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }
}
