## 4) Repository

**data/BankRepository.kt**
```kotlin
package com.example.bankapp.data

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import java.util.UUID

class BankRepository {

    private val _accounts = MutableStateFlow(
        listOf(
            Account("1", "Everyday Checking", "Checking", 2450.75),
            Account("2", "Savings Vault", "Savings", 12840.20)
        )
    )
    val accounts: StateFlow<List<Account>> = _accounts

    private val _transactions = MutableStateFlow(
        listOf(
            Transaction("1", "Salary Deposit", 4200.00, "2026-06-01", "1"),
            Transaction("2", "Electric Bill", -120.55, "2026-06-03", "1"),
            Transaction("3", "Transfer from Checking", 500.00, "2026-06-04", "2")
        )
    )
    val transactions: StateFlow<List<Transaction>> = _transactions

    fun transfer(fromAccountId: String, toAccountId: String, amount: Double): Boolean {
        if (amount <= 0) return false

        val currentAccounts = _accounts.value.toMutableList()
        val fromIndex = currentAccounts.indexOfFirst { it.id == fromAccountId }
        val toIndex = currentAccounts.indexOfFirst { it.id == toAccountId }

        if (fromIndex == -1 || toIndex == -1 || fromIndex == toIndex) return false
        if (currentAccounts[fromIndex].balance < amount) return false

        currentAccounts[fromIndex] = currentAccounts[fromIndex].copy(
            balance = currentAccounts[fromIndex].balance - amount
        )
        currentAccounts[toIndex] = currentAccounts[toIndex].copy(
            balance = currentAccounts[toIndex].balance + amount
        )

        _accounts.value = currentAccounts

        val newTx = listOf(
            Transaction(UUID.randomUUID().toString(), "Transfer to ${currentAccounts[toIndex].name}", -amount, "2026-06-11", fromAccountId),
            Transaction(UUID.randomUUID().toString(), "Transfer from ${currentAccounts[fromIndex].name}", amount, "2026-06-11", toAccountId)
        )
        _transactions.value = newTx + _transactions.value

        return true
    }
}
```

