## 4) ViewModel

### `viewmodel/BankViewModel.kt`

```kotlin
package com.example.bankapp.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.bankapp.data.Account
import com.example.bankapp.data.Transaction
import java.util.UUID

class BankViewModel : ViewModel() {

    var isLoggedIn by mutableStateOf(false)
        private set

    var account by mutableStateOf(
        Account(
            accountNumber = "1234567890",
            holderName = "John Doe",
            balance = 12580.75
        )
    )
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction(
                id = "1",
                title = "Salary Deposit",
                subtitle = "ACME Corp",
                amount = 5000.00,
                date = "2026-06-01"
            ),
            Transaction(
                id = "2",
                title = "Electric Bill",
                subtitle = "Utilities",
                amount = -120.50,
                date = "2026-06-03"
            ),
            Transaction(
                id = "3",
                title = "Grocery Store",
                subtitle = "SuperMart",
                amount = -78.25,
                date = "2026-06-05"
            )
        )
        private set

    fun login(username: String, password: String): Boolean {
        // Demo-only authentication
        return if (username.isNotBlank() && password.isNotBlank()) {
            isLoggedIn = true
            true
        } else {
            false
        }
    }

    fun logout() {
        isLoggedIn = false
    }

    fun transferMoney(recipient: String, amount: Double) {
        if (amount <= 0 || amount > account.balance) return

        account = account.copy(balance = account.balance - amount)

        val newTransaction = Transaction(
            id = UUID.randomUUID().toString(),
            title = "Transfer to $recipient",
            subtitle = "Outgoing transfer",
            amount = -amount,
            date = "2026-06-11"
        )

        transactions = listOf(newTransaction) + transactions
    }
}
