package com.example.bankingapp.data.repository

import com.example.bankingapp.data.api.BankingApi
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.AuthRequest
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.secure.TokenStore
import javax.inject.Inject

class BankingRepository @Inject constructor(
    private val api: BankingApi,
    private val tokenStore: TokenStore
) {
    suspend fun login(username: String, password: String): Boolean {
        val response = api.login(AuthRequest(username, password))
        tokenStore.saveAccessToken(response.accessToken)
        return true
    }

    suspend fun getAccounts(): List<Account> = api.getAccounts()

    suspend fun getTransactions(accountId: String): List<Transaction> =
        api.getTransactions(accountId)

    fun logout() {
        tokenStore.clear()
    }
}
