### `BankingViewModel.kt`
```kotlin
package com.example.bankapp.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.model.TransferRequest
import com.example.bankapp.data.repository.BankingRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

data class BankingUiState(
    val isLoading: Boolean = false,
    val accounts: List<Account> = emptyList(),
    val transactions: List<Transaction> = emptyList(),
    val error: String? = null,
    val transferSuccess: Boolean = false
)

class BankingViewModel(
    private val repository: BankingRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(BankingUiState())
    val uiState: StateFlow<BankingUiState> = _uiState

    fun loadDashboard() {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, error = null)
            try {
                val accounts = repository.getAccounts()
                val tx = if (accounts.isNotEmpty()) repository.getTransactions(accounts.first().id) else emptyList()
                _uiState.value = BankingUiState(accounts = accounts, transactions = tx)
            } catch (e: Exception) {
                _uiState.value = BankingUiState(error = e.message ?: "Failed to load data")
            }
        }
    }

    fun transferFunds(fromAccountId: String, toAccountNumber: String, amount: Double, reference: String) {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(isLoading = true, error = null, transferSuccess = false)
            val result = repository.transferFunds(
                TransferRequest(fromAccountId, toAccountNumber, amount, reference)
            )
            _uiState.value = if (result.isSuccess) {
                _uiState.value.copy(isLoading = false, transferSuccess = true)
            } else {
                _uiState.value.copy(
                    isLoading = false,
                    error = result.exceptionOrNull()?.message ?: "Transfer failed"
                )
            }
        }
    }
}
