## 5) Navigation

### `AppNavGraph.kt`
```kotlin
package com.example.bankapp.ui

import androidx.compose.runtime.*
import androidx.navigation.compose.*
import com.example.bankapp.ui.screens.HomeScreen
import com.example.bankapp.ui.screens.LoginScreen
import com.example.bankapp.ui.screens.TransferScreen
import com.example.bankapp.viewmodel.AuthViewModel
import com.example.bankapp.viewmodel.BankingViewModel

@Composable
fun AppNavGraph(
    authViewModel: AuthViewModel,
    bankingViewModel: BankingViewModel
) {
    val navController = rememberNavController()
    val authState by authViewModel.uiState.collectAsState()
    val bankingState by bankingViewModel.uiState.collectAsState()

    NavHost(navController = navController, startDestination = "login") {
        composable("login") {
            LoginScreen(
                isLoading = authState.isLoading,
                error = authState.error,
                onLogin = { u, p ->
                    authViewModel.login(u, p)
                }
            )

            LaunchedEffect(authState.isLoggedIn) {
                if (authState.isLoggedIn) {
                    bankingViewModel.loadDashboard()
                    navController.navigate("home") {
                        popUpTo("login") { inclusive = true }
                    }
                }
            }
        }

        composable("home") {
            HomeScreen(
                accounts = bankingState.accounts,
                transactions = bankingState.transactions,
                onTransferClick = { navController.navigate("transfer") }
            )
        }

        composable("transfer") {
            TransferScreen(
                isLoading = bankingState.isLoading,
                error = bankingState.error,
                success = bankingState.transferSuccess,
                onTransfer = { fromId, toAcc, amount, ref ->
                    bankingViewModel.transferFunds(fromId, toAcc, amount, ref)
                }
            )
        }
    }
}
