## 6) Fake repository

### `data/repository/BankRepository.kt`
```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.model.User
import kotlinx.coroutines.delay
import java.time.LocalDateTime
import java.util.UUID
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class BankRepository @Inject constructor() {

    private var currentUser: User? = null

    private val accounts = mutableListOf(
        Account(id = "1", type = "Checking", balance = 3250.45),
        Account(id = "2", type = "Savings", balance = 12500.00)
    )

    private val transactions = mutableListOf(
        Transaction(
            id = UUID.randomUUID().toString(),
            title = "Salary Deposit",
            amount = 4200.00,
            date = LocalDateTime.now().minusDays(1),
            isDebit = false
        ),
        Transaction(
            id = UUID.randomUUID().toString(),
            title = "Electric Bill",
            amount = 120.32,
            date = LocalDateTime.now().minusDays(2),
            isDebit = true
        )
    )

    suspend fun login(email: String, password: String): User {
        delay(800)
        if (email.isBlank() || password.length < 4) {
            throw IllegalArgumentException("Invalid credentials")
        }
        return User(
            id = "user_1",
            fullName = "Jane Doe",
            email = email
        ).also { currentUser = it }
    }

    fun getCurrentUser(): User? = currentUser

    suspend fun getAccounts(): List<Account> {
        delay(400)
        return accounts.toList()
    }

    suspend fun getTransactions(): List<Transaction> {
        delay(400)
        return transactions.toList()
    }

    suspend fun transfer(amount: Double, toAccount: String): Transaction {
        delay(700)
        if (amount <= 0) throw IllegalArgumentException("Amount must be positive")
        val checkingIndex = accounts.indexOfFirst { it.type == "Checking" }
        if (checkingIndex == -1) throw IllegalStateException("Checking account not found")
        if (accounts[checkingIndex].balance < amount) throw IllegalArgumentException("Insufficient funds")

        accounts[checkingIndex] = accounts[checkingIndex].copy(balance = accounts[checkingIndex].balance - amount)

        val tx = Transaction(
            id = UUID.randomUUID().toString(),
            title = "Transfer to $toAccount",
            amount = amount,
            date = LocalDateTime.now(),
            isDebit = true
        )
        transactions.add(0, tx)
        return tx
    }
}
```

