@Composable
fun HomeScreen(
    onOpenTransactions: (String) -> Unit,
    viewModel: HomeViewModel = hiltViewModel()
) {
    val state by viewModel.uiState.collectAsState()
    val currencyFormatter = remember { NumberFormat.getCurrencyInstance(Locale.US) }

    when (val accountsState = state.accounts) {
        is ResultState.Loading -> LoadingView()
        is ResultState.Error -> {
            Column(Modifier.padding(16.dp)) {
                Text(accountsState.message)
                Spacer(Modifier.height(12.dp))
                Button(onClick = { viewModel.loadAccounts() }) { Text("Retry") }
            }
        }
        is ResultState.Success -> {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(16.dp)
            ) {
                Text("Accounts", style = MaterialTheme.typography.headlineMedium)
                Spacer(Modifier.height(16.dp))

                accountsState.data.forEach { account ->
                    BankingCard(
                        title = account.type,
                        subtitle = account.accountNumberMasked,
                        balance = currencyFormatter.format(account.balance),
                        onClick = { onOpenTransactions(account.id) }
                    )
                }
            }
        }
        else -> Unit
    }
}
