package com.bank.app.ui.screens.transactions

import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.hilt.navigation.compose.hiltViewModel
import com.bank.app.ui.components.LoadingView
import com.bank.app.util.ResultState
import java.text.NumberFormat
import java.util.Locale

@Composable
fun TransactionsScreen(
    accountId: String,
    viewModel: TransactionsViewModel = hiltViewModel()
) {
    val state by viewModel.uiState.collectAsState()
    val currencyFormatter = remember { NumberFormat.getCurrencyInstance(Locale.US) }

    LaunchedEffect(accountId) {
        viewModel.load(accountId)
    }

    when (val txnState = state.transactions) {
        is ResultState.Loading -> LoadingView()
        is ResultState.Error -> Text(txnState.message, modifier = Modifier.padding(16.dp))
        is ResultState.Success -> {
            Column(Modifier.fillMaxSize().padding(16.dp)) {
                Text("Transactions", style = MaterialTheme.typography.headlineMedium)
                Spacer(Modifier.height(16.dp))

                txnState.data.forEach { txn ->
                    Card(Modifier.fillMaxWidth().padding(vertical = 6.dp)) {
                        Column(Modifier.padding(16.dp)) {
                            Text(txn.title, style = MaterialTheme.typography.titleMedium)
                            Text(txn.description, style = MaterialTheme.typography.bodyMedium)
                            Spacer(Modifier.height(8.dp))
                            Text(
                                text = (if (txn.isDebit) "-" else "+") + currencyFormatter.format(txn.amount),
                                color = if (txn.isDebit) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary
                            )
                        }
                    }
                }
            }
        }
        else -> Unit
    }
}
