        composable(Route.Home.path) {
            HomeScreen(onTransferClick = { navController.navigate(Route.Transfer.path) })
        }
        composable(Route.Transfer.path) {
            TransferScreen(onDone = { navController.popBackStack() })
        }
    }
}
