## 9) Repository layer

### `AuthRepository.kt`

```kotlin
class AuthRepository @Inject constructor(
    private val api: ApiService,
    private val dataStore: DataStore<Preferences>
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return runCatching {
            val response = api.login(LoginRequestDto(username, password))
            dataStore.edit { prefs ->
                prefs[stringPreferencesKey("auth_token")] = response.token
                prefs[stringPreferencesKey("user_id")] = response.userId
            }
        }
    }
}
```

### `BankingRepository.kt`

```kotlin
class BankingRepository @Inject constructor(
    private val api: ApiService,
    private val db: AppDatabase
) {
    fun observeAccounts(): Flow<List<Account>> =
        db.accountDao().observeAccounts().map { entities ->
            entities.map { it.toDomain() }
        }

    fun observeTransactions(): Flow<List<Transaction>> =
        db.transactionDao().observeTransactions().map { entities ->
            entities.map { it.toDomain() }
        }

    suspend fun refreshAccounts() {
        val remote = api.getAccounts()
        db.accountDao().upsertAccounts(remote.map { it.toEntity() })
    }

    suspend fun refreshTransactions() {
        val remote = api.getTransactions()
        db.transactionDao().upsertTransactions(remote.map { it.toEntity() })
    }

    suspend fun transfer(fromAccountId: String, toAccountId: String, amount: Double, note: String?) =
        api.transfer(TransferRequestDto(fromAccountId, toAccountId, amount, note))
}
```

