## `data/repository/BankingRepository.kt`
```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.local.TokenPreferences
import com.example.bankingapp.data.model.Account
import com.example.bankingapp.data.model.AuthToken
import com.example.bankingapp.data.model.LoginRequest
import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.network.BankingApi
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class BankingRepository(
    private val api: BankingApi,
    private val tokenPreferences: TokenPreferences
) {
    suspend fun login(username: String, password: String): Result<AuthToken> = withContext(Dispatchers.IO) {
        runCatching {
            val token = api.login(LoginRequest(username, password))
            tokenPreferences.saveAccessToken(token.accessToken)
            token
        }
    }

    suspend fun getAccounts(): Result<List<Account>> = withContext(Dispatchers.IO) {
        runCatching { api.getAccounts() }
    }

    suspend fun getTransactions(): Result<List<Transaction>> = withContext(Dispatchers.IO) {
        runCatching { api.getTransactions() }
    }
}
