@Module
@InstallIn(SingletonComponent::class)
object AppModule {

    @Provides
    @Singleton
    fun provideBankingApi(): BankingApi = ApiClient.api

    @Provides
    @Singleton
    fun provideTokenPreferences(@ApplicationContext context: Context): TokenPreferences =
        TokenPreferences(context)

    @Provides
    @Singleton
    fun provideDatabase(@ApplicationContext context: Context): BankingDatabase =
        Room.databaseBuilder(context, BankingDatabase::class.java, "banking.db").build()

    @Provides
    @Singleton
    fun provideRepository(
        api: BankingApi,
        tokenPreferences: TokenPreferences
    ): BankingRepository = BankingRepository(api, tokenPreferences)
}
