```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.repository.BankingRepository
import com.example.bankingapp.ui.state.AuthUiState
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class AuthViewModel @Inject constructor(
    private val repository: BankingRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(AuthUiState())
    val uiState: StateFlow<AuthUiState> = asStateFlow(_uiState)

    fun updateUsername(value: String) {
        _uiState.value = _uiState.value.copy(username = value)
    }

    fun updatePassword(value: String) {
        _uiState.value = _uiState.value.copy(password = value)
    }

    fun login() {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(loading = true, error = null)
            val state = _uiState.value
            repository.login(state.username, state.password)
                .onSuccess {
                    _uiState.value = _uiState.value.copy(loading = false, isLoggedIn = true)
                }
                .onFailure {
                    _uiState.value = _uiState.value.copy(
                        loading = false,
                        error = it.message ?: "Login failed"
                    )
                }
        }
    }
}
```

## `ui/viewmodel/DashboardViewModel.kt`
```kotlin
package com.example.bankingapp.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.bankingapp.data.repository.BankingRepository
import com.example.bankingapp.ui.state.DashboardUiState
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.async
import kotlinx.coroutines.launch
import javax.inject.Inject

@HiltViewModel
class DashboardViewModel @Inject constructor(
    private val repository: BankingRepository
) : ViewModel() {

    private val _uiState = kotlinx.coroutines.flow.MutableStateFlow(DashboardUiState())
    val uiState = _uiState.asStateFlow()

    fun loadDashboard() {
        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(loading = true, error = null)

            val accountsDeferred = async { repository.getAccounts() }
            val transactionsDeferred = async { repository.getTransactions() }

            val accountsResult = accountsDeferred.await()
            val transactionsResult = transactionsDeferred.await()

            _uiState.value = when {
                accountsResult.isSuccess && transactionsResult.isSuccess -> DashboardUiState(
                    loading = false,
                    accounts = accountsResult.getOrDefault(emptyList()),
                    transactions = transactionsResult.getOrDefault(emptyList())
                )
                else -> DashboardUiState(
                    loading = false,
                    error = accountsResult.exceptionOrNull()?.message
                        ?: transactionsResult.exceptionOrNull()?.message
                        ?: "Failed to load dashboard"
                )
            }
        }
    }
}
