import androidx.compose.runtime.collectAsState
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.example.bankingapp.ui.viewmodel.DashboardViewModel

@Composable
fun DashboardScreen(viewModel: DashboardViewModel) {
    val state = viewModel.uiState.collectAsState().value

    when {
        state.loading -> Box(Modifier.fillMaxSize()) {
            CircularProgressIndicator(modifier = Modifier.padding(24.dp))
        }

        state.error != null -> Box(Modifier.fillMaxSize()) {
            Text(
                text = state.error!!,
                color = MaterialTheme.colorScheme.error,
                modifier = Modifier.padding(24.dp)
            )
        }

        else -> LazyColumn(
            modifier = Modifier.fillMaxSize(),
            contentPadding = PaddingValues(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            item {
                Text("Accounts", style = MaterialTheme.typography.headlineSmall)
            }

            items(state.accounts) { account ->
                Card(modifier = Modifier.fillMaxWidth()) {
                    Column(Modifier.padding(16.dp)) {
                        Text(account.type, style = MaterialTheme.typography.titleMedium)
                        Text(account.accountNumberMasked)
                        Text("${account.currency} ${account.balance}")
                    }
                }
            }

            item {
                Spacer(Modifier.height(8.dp))
                Text("Recent Transactions", style = MaterialTheme.typography.headlineSmall)
            }

            items(state.transactions) { tx ->
                Card(modifier = Modifier.fillMaxWidth()) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column {
                            Text(tx.title, style = MaterialTheme.typography.titleMedium)
                            Text(tx.date, style = MaterialTheme.typography.bodyMedium)
                        }
                        Text(
                            text = "${tx.currency} ${tx.amount}",
                            color = if (tx.type == "debit") MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary
                        )
                    }
                }
            }
        }
    }
}
