import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import kotlin.math.abs

data class Transaction(
    val id: Int,
    val title: String,
    val amount: Double,
    val type: String
)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MiniBankApp()
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MiniBankApp() {
    val navController = rememberNavController()

    var loggedIn by remember { mutableStateOf(false) }
    var balance by remember { mutableStateOf(2450.75) }
    var transactions by remember {
        mutableStateOf(
            listOf(
                Transaction(1, "Salary", 3200.00, "Credit"),
                Transaction(2, "Groceries", -84.30, "Debit"),
                Transaction(3, "Electricity Bill", -120.00, "Debit")
            )
        )
    }

    NavHost(
        navController = navController,
        startDestination = "login"
    ) {
        composable("login") {
            LoginScreen(
                onLogin = {
                    loggedIn = true
                    navController.navigate("home") {
                        popUpTo("login") { inclusive = true }
                    }
                }
            )
        }

        composable("home") {
            if (!loggedIn) {
                navController.navigate("login")
                return@composable
            }

            HomeScreen(
                balance = balance,
                transactions = transactions,
                onTransfer = { recipient, amount ->
                    if (amount > 0 && amount <= balance) {
                        balance -= amount
                        transactions = listOf(
                            Transaction(
                                id = transactions.size + 1,
                                title = "Transfer to $recipient",
                                amount = -amount,
                                type = "Debit"
                            )
                        ) + transactions
                    }
                }
            )
        }
    }
}

@Composable
fun LoginScreen(onLogin: () -> Unit) {
    var username by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }

    Scaffold(
        topBar = { TopAppBar(title = { Text("MiniBank Login") }) }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(24.dp),
            verticalArrangement = Arrangement.Center
        ) {
            OutlinedTextField(
                value = username,
                onValueChange = { username = it },
                label = { Text("Username") },
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(12.dp))

            OutlinedTextField(
                value = password,
                onValueChange = { password = it },
                label = { Text("Password") },
                visualTransformation = PasswordVisualTransformation(),
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(20.dp))

            Button(
                onClick = onLogin,
                modifier = Modifier.fillMaxWidth(),
                enabled = username.isNotBlank() && password.isNotBlank()
            ) {
                Text("Login")
            }

            Spacer(modifier = Modifier.height(8.dp))
            Text("Demo credentials work with any non-empty input.")
        }
    }
}

@Composable
fun HomeScreen(
    balance: Double,
    transactions: List<Transaction>,
    onTransfer: (recipient: String, amount: Double) -> Unit
) {
    var recipient by remember { mutableStateOf("") }
    var amountText by remember { mutableStateOf("") }

    Scaffold(
        topBar = { TopAppBar(title = { Text("MiniBank Dashboard") }) }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(16.dp)
        ) {
            Card(modifier = Modifier.fillMaxWidth()) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text("Available Balance", style = MaterialTheme.typography.titleMedium)
                    Text(
                        text = "$${"%.2f".format(balance)}",
                        style = MaterialTheme.typography.headlineMedium
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            Text("Transfer Money", style = MaterialTheme.typography.titleMedium)

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = recipient,
                onValueChange = { recipient = it },
                label = { Text("Recipient") },
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(8.dp))

            OutlinedTextField(
                value = amountText,
                onValueChange = { amountText = it },
                label = { Text("Amount") },
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(modifier = Modifier.height(8.dp))

            Button(
                onClick = {
                    val amount = amountText.toDoubleOrNull() ?: 0.0
                    onTransfer(recipient, amount)
                    recipient = ""
                    amountText = ""
                },
                modifier = Modifier.fillMaxWidth(),
                enabled = recipient.isNotBlank() && (amountText.toDoubleOrNull() ?: 0.0) > 0
            ) {
                Text("Send")
            }

            Spacer(modifier = Modifier.height(20.dp))

            Text("Recent Transactions", style = MaterialTheme.typography.titleMedium)

            Spacer(modifier = Modifier.height(8.dp))

            LazyColumn(
                verticalArrangement = Arrangement.spacedBy(8.dp),
                modifier = Modifier.fillMaxSize()
            ) {
                items(transactions) { tx ->
                    Card(modifier = Modifier.fillMaxWidth()) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(16.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column {
                                Text(tx.title)
                                Text(tx.type, style = MaterialTheme.typography.bodySmall)
                            }
                            Text(
                                text = if (tx.amount >= 0) "+$${"%.2f".format(tx.amount)}"
                                else "-$${"%.2f".format(abs(tx.amount))}"
                            )
                        }
                    }
                }
            }
        }
    }
