# 4) Survey local service

## `src/services/surveyService.ts`

```ts
import { getDb } from '../db/db';
import { Survey } from '../types/survey';
import { v4 as uuidv4 } from 'uuid';

function nowIso() {
  return new Date().toISOString();
}

export async function createSurvey(input: Omit<Survey, 'id' | 'version' | 'createdAt' | 'updatedAt' | 'status'>) {
  const db = await getDb();
  const id = uuidv4();
  const timestamp = nowIso();

  const survey: Survey = {
    id,
    title: input.title,
    notes: input.notes,
    latitude: input.latitude,
    longitude: input.longitude,
    status: 'draft',
    version: 1,
    createdAt: timestamp,
    updatedAt: timestamp,
  };

  await db.executeSql(
    `INSERT INTO surveys (id, title, notes, latitude, longitude, status, version, createdAt, updatedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.notes,
      survey.latitude,
      survey.longitude,
      survey.status,
      survey.version,
      survey.createdAt,
      survey.updatedAt,
    ]
  );

  return survey;
}

export async function updateSurvey(id: string, patch: Partial<Survey>) {
  const db = await getDb();
  const current = await getSurveyById(id);
  if (!current) throw new Error('Survey not found');

  const updated: Survey = {
    ...current,
    ...patch,
    version: current.version + 1,
    updatedAt: nowIso(),
  };

  await db.executeSql(
    `UPDATE surveys
     SET title = ?, notes = ?, latitude = ?, longitude = ?, status = ?, version = ?, updatedAt = ?
     WHERE id = ?`,
    [
      updated.title,
      updated.notes,
      updated.latitude,
      updated.longitude,
      updated.status,
      updated.version,
      updated.updatedAt,
      updated.id,
    ]
  );

  return updated;
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);

  if (result.rows.length === 0) return null;
  return result.rows.item(0) as Survey;
}

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM surveys ORDER BY updatedAt DESC`);

  const surveys: Survey[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    surveys.push(result.rows.item(i) as Survey);
  }
  return surveys;
}

export async function markSurveySynced(id: string, serverId: string) {
  const db = await getDb();
  await db.executeSql(
    `UPDATE surveys SET serverId = ?, status = 'synced' WHERE id = ?`,
    [serverId, id]
  );
}
```

