# 5) Sync queue service

## `src/services/syncService.ts`

```ts
import { getDb } from '../db/db';
import { api } from './api';
import { Survey } from '../types/survey';
import { getAllSurveys, markSurveySynced } from './surveyService';

function nowIso() {
  return new Date().toISOString();
}

export async function enqueueSurveyAction(
  action: 'create' | 'update' | 'delete',
  survey: Survey
) {
  const db = await getDb();

  await db.executeSql(
    `INSERT INTO sync_queue (entityType, entityId, action, payload, attempts, createdAt)
     VALUES (?, ?, ?, ?, 0, ?)`,
    [
      'survey',
      survey.id,
      action,
      JSON.stringify(survey),
      nowIso(),
    ]
  );
}

export async function getPendingQueue() {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );

  const items: any[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function removeQueueItem(id: number) {
  const db = await getDb();
  await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export async function incrementQueueAttempt(id: number, err: string) {
  const db = await getDb();
  await db.executeSql(
    `UPDATE sync_queue
     SET attempts = attempts + 1, lastError = ?
     WHERE id = ?`,
    [err, id]
  );
}

export async function syncNow() {
  const queue = await getPendingQueue();

  for (const item of queue) {
    try {
      const survey = JSON.parse(item.payload) as Survey;

      if (item.action === 'create') {
        const response = await api.post('/surveys', survey);
        await markSurveySynced(survey.id, response.data.id);
      } else if (item.action === 'update') {
        await api.put(`/surveys/${survey.serverId ?? survey.id}`, survey);
      } else if (item.action === 'delete') {
        await api.delete(`/surveys/${survey.serverId ?? survey.id}`);
      }

      await removeQueueItem(item.id);
    } catch (err: any) {
      await incrementQueueAttempt(item.id, err?.message || 'Sync error');
      // stop on first failure so we retry later in correct order
      break;
    }
  }

  // Optionally pull remote changes after push
  await pullRemoteSurveys();
}

export async function pullRemoteSurveys() {
  const response = await api.get('/surveys');
  const remoteSurveys = response.data as Survey[];

  // naive upsert
  const db = await getDb();

  for (const survey of remoteSurveys) {
    await db.executeSql(
      `INSERT INTO surveys
       (id, serverId, title, notes, latitude, longitude, status, version, createdAt, updatedAt)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         serverId = excluded.serverId,
         title = excluded.title,
         notes = excluded.notes,
         latitude = excluded.latitude,
         longitude = excluded.longitude,
         status = excluded.status,
         version = excluded.version,
         createdAt = excluded.createdAt,
         updatedAt = excluded.updatedAt`,
      [
        survey.id,
        survey.serverId ?? survey.id,
        survey.title,
        survey.notes,
        survey.latitude,
        survey.longitude,
        survey.status,
        survey.version,
        survey.createdAt,
        survey.updatedAt,
      ]
    );
  }
}
```

