# 10) App bootstrap

## `App.tsx`

```tsx
import React, { useEffect, useState } from 'react';
import { SafeAreaView, View } from 'react-native';
import { runMigrations } from './src/db/migrations';
import { startNetworkSyncListener } from './src/services/network';
import NetInfo from '@react-native-community/netinfo';
import { OfflineBanner } from './src/components/OfflineBanner';
import { SurveyFormScreen } from './src/screens/SurveyFormScreen';
import { SurveyListScreen } from './src/screens/SurveyListScreen';

export default function App() {
  const [offline, setOffline] = useState(false);

  useEffect(() => {
    runMigrations().catch(console.error);

    const unsubscribe = startNetworkSyncListener();

    const netUnsub = NetInfo.addEventListener((state) => {
      setOffline(!(state.isConnected && state.isInternetReachable));
    });

    return () => {
      unsubscribe();
      netUnsub();
    };
  }, []);

  return (
    <SafeAreaView style={{ flex: 1 }}>
      <OfflineBanner offline={offline} />
      <View style={{ flex: 1 }}>
        <SurveyFormScreen />
        <SurveyListScreen />
      </View>
    </SafeAreaView>
  );
}
