# 11) Example backend endpoints

Your server should support:
- `POST /surveys`
- `PUT /surveys/:id`
- `DELETE /surveys/:id`
- `GET /surveys`

A simple Node/Express example:

```ts
import express from 'express';

const app = express();
app.use(express.json());

let surveys: any[] = [];

app.get('/surveys', (req, res) => {
  res.json(surveys);
});

app.post('/surveys', (req, res) => {
  const serverId = String(Date.now());
  const survey = { ...req.body, id: serverId, serverId };
  surveys.push(survey);
  res.status(201).json(survey);
});

app.put('/surveys/:id', (req, res) => {
  const id = req.params.id;
  surveys = surveys.map(s => (s.id === id ? { ...s, ...req.body } : s));
  res.json({ ok: true });
});

app.delete('/surveys/:id', (req, res) => {
  const id = req.params.id;
  surveys = surveys.filter(s => s.id !== id);
  res.json({ ok: true });
});

app.listen(3000);
```

