## 4) `surveyRepository.ts`

Handles local data operations.

```ts
import { getDb } from './db';

export type Survey = {
  id: string;
  name: string;
  latitude?: number | null;
  longitude?: number | null;
  notes?: string | null;
  created_at: number;
  updated_at: number;
  synced: number;
};

export async function getAllSurveys(): Promise<Survey[]> {
  const db = getDb();
  const result = db.getAllSync<Survey>('SELECT * FROM surveys ORDER BY updated_at DESC');
  return result;
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = getDb();
  const result = db.getFirstSync<Survey>('SELECT * FROM surveys WHERE id = ?', [id]);
  return result ?? null;
}

export async function upsertSurvey(survey: Survey) {
  const db = getDb();
  db.runSync(
    `INSERT INTO surveys (id, name, latitude, longitude, notes, created_at, updated_at, synced)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT(id) DO UPDATE SET
       name = excluded.name,
       latitude = excluded.latitude,
       longitude = excluded.longitude,
       notes = excluded.notes,
       updated_at = excluded.updated_at,
       synced = excluded.synced`,
    [
      survey.id,
      survey.name,
      survey.latitude ?? null,
      survey.longitude ?? null,
      survey.notes ?? null,
      survey.created_at,
      survey.updated_at,
      survey.synced,
    ]
  );
}

export async function deleteSurvey(id: string) {
  const db = getDb();
  db.runSync('DELETE FROM surveys WHERE id = ?', [id]);
}
```

