## 5) `syncQueueRepository.ts`

Stores pending operations.

```ts
import { getDb } from './db';

export type QueueOperation = 'CREATE' | 'UPDATE' | 'DELETE';

export async function enqueueOperation(
  entityType: string,
  entityId: string,
  operation: QueueOperation,
  payload: object
) {
  const db = getDb();
  db.runSync(
    `INSERT INTO sync_queue (entity_type, entity_id, operation, payload, created_at)
     VALUES (?, ?, ?, ?, ?)`,
    [
      entityType,
      entityId,
      operation,
      JSON.stringify(payload),
      Date.now(),
    ]
  );
}

export async function getPendingOperations() {
  const db = getDb();
  return db.getAllSync<{
    id: number;
    entity_type: string;
    entity_id: string;
    operation: QueueOperation;
    payload: string;
    created_at: number;
  }>('SELECT * FROM sync_queue ORDER BY created_at ASC');
}

export async function removeQueueItem(id: number) {
  const db = getDb();
  db.runSync('DELETE FROM sync_queue WHERE id = ?', [id]);
}

export async function clearQueue() {
  const db = getDb();
  db.runSync('DELETE FROM sync_queue');
}
```

