## 6) `syncService.ts`

Syncs local queue to server when back online.

```ts
import axios from 'axios';
import { getPendingOperations, removeQueueItem } from './syncQueueRepository';
import { upsertSurvey, deleteSurvey } from './surveyRepository';

const API_BASE_URL = 'https://your-api.example.com';

export async function syncPendingChanges() {
  const pending = await getPendingOperations();

  for (const item of pending) {
    const payload = JSON.parse(item.payload);

    try {
      if (item.entity_type === 'survey') {
        if (item.operation === 'CREATE') {
          const res = await axios.post(`${API_BASE_URL}/surveys`, payload);
          await upsertSurvey({ ...payload, synced: 1, id: res.data.id });
        }

        if (item.operation === 'UPDATE') {
          await axios.put(`${API_BASE_URL}/surveys/${item.entity_id}`, payload);
          await upsertSurvey({ ...payload, synced: 1 });
        }

        if (item.operation === 'DELETE') {
          await axios.delete(`${API_BASE_URL}/surveys/${item.entity_id}`);
          await deleteSurvey(item.entity_id);
        }
      }

      await removeQueueItem(item.id);
    } catch (error) {
      console.error('Sync failed for queue item:', item.id, error);
      // Stop syncing if one fails to retry later
      break;
    }
  }
}
```

