## 2. Local database helper

**`db.js`**

```javascript
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export const initDb = () => {
  db.transaction((tx) => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        title TEXT,
        notes TEXT,
        latitude REAL,
        longitude REAL,
        created_at TEXT,
        synced INTEGER DEFAULT 0
      );`
    );
  });
};

export const insertSurvey = (survey) => {
  const {
    id,
    title,
    notes,
    latitude,
    longitude,
    created_at,
    synced = 0,
  } = survey;

  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `INSERT INTO surveys (id, title, notes, latitude, longitude, created_at, synced)
         VALUES (?, ?, ?, ?, ?, ?, ?);`,
        [id, title, notes, latitude, longitude, created_at, synced],
        (_, result) => resolve(result),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY created_at DESC;`,
        [],
        (_, { rows }) => resolve(rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const getUnsyncedSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE synced = 0 ORDER BY created_at ASC;`,
        [],
        (_, { rows }) => resolve(rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const markSurveySynced = (id) => {
  return new Promise((resolve, reject) => {
    db.transaction((tx) => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1 WHERE id = ?;`,
        [id],
        (_, result) => resolve(result),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};
```

