## 2) IndexedDB storage

### `src/db/indexedDb.ts`
```ts
export type SurveyStatus = "pending" | "synced" | "failed";

export interface Survey {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  createdAt: string;
  updatedAt: string;
  status: SurveyStatus;
}

const DB_NAME = "field-survey-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";
const QUEUE_NAME = "syncQueue";

let dbPromise: Promise<IDBDatabase> | null = null;

function openDb(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;

  dbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
        store.createIndex("status", "status", { unique: false });
        store.createIndex("updatedAt", "updatedAt", { unique: false });
      }

      if (!db.objectStoreNames.contains(QUEUE_NAME)) {
        db.createObjectStore(QUEUE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });

  return dbPromise;
}

async function withStore<T>(
  storeName: string,
  mode: IDBTransactionMode,
  fn: (store: IDBObjectStore) => T | Promise<T>
): Promise<T> {
  const db = await openDb();
  const tx = db.transaction(storeName, mode);
  const store = tx.objectStore(storeName);
  const result = await fn(store);

  return new Promise<T>((resolve, reject) => {
    tx.oncomplete = () => resolve(result);
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
}

export async function upsertSurvey(survey: Survey): Promise<void> {
  return withStore(STORE_NAME, "readwrite", store => {
    store.put(survey);
  });
}

export async function getAllSurveys(): Promise<Survey[]> {
  return withStore(STORE_NAME, "readonly", store => {
    return new Promise<Survey[]>((resolve, reject) => {
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result as Survey[]);
      req.onerror = () => reject(req.error);
    });
  });
}

export async function deleteSurvey(id: string): Promise<void> {
  return withStore(STORE_NAME, "readwrite", store => {
    store.delete(id);
  });
}

export async function getSurvey(id: string): Promise<Survey | undefined> {
  return withStore(STORE_NAME, "readonly", store => {
    return new Promise<Survey | undefined>((resolve, reject) => {
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result as Survey | undefined);
      req.onerror = () => reject(req.error);
    });
  });
}

export async function queueChange(item: { id: string; type: "upsert" | "delete" }): Promise<void> {
  return withStore(QUEUE_NAME, "readwrite", store => {
    store.put(item);
  });
}

export async function getQueuedChanges(): Promise<Array<{ id: string; type: "upsert" | "delete" }>> {
  return withStore(QUEUE_NAME, "readonly", store => {
    return new Promise((resolve, reject) => {
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  });
}

export async function removeQueuedChange(id: string): Promise<void> {
  return withStore(QUEUE_NAME, "readwrite", store => {
    store.delete(id);
  });
}
```

