## 5) Survey store hook with local-first writes and syncing

### `src/hooks/useSurveyStore.ts`
```ts
import { useCallback, useEffect, useState } from "react";
import {
  Survey,
  deleteSurvey,
  getAllSurveys,
  queueChange,
  removeQueuedChange,
  upsertSurvey,
  getQueuedChanges,
} from "../db/indexedDb";
import { pushDelete, pushSurvey } from "../api/sync";

function uid() {
  return crypto.randomUUID();
}

export function useSurveyStore(isOnline: boolean) {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [syncing, setSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    const data = await getAllSurveys();
    setSurveys(data.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)));
  }, []);

  const syncQueuedChanges = useCallback(async () => {
    if (!isOnline) return;
    setSyncing(true);
    setError(null);

    try {
      const queue = await getQueuedChanges();

      for (const item of queue) {
        if (item.type === "upsert") {
          const survey = surveys.find(s => s.id === item.id);
          if (survey) {
            await pushSurvey(survey);
            await upsertSurvey({ ...survey, status: "synced" });
          }
        } else {
          await pushDelete(item.id);
          await deleteSurvey(item.id);
        }
        await removeQueuedChange(item.id);
      }

      await refresh();
    } catch (e: any) {
      setError(e?.message ?? "Sync failed");
      await refresh();
    } finally {
      setSyncing(false);
    }
  }, [isOnline, refresh, surveys]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  useEffect(() => {
    if (isOnline) {
      syncQueuedChanges();
    }
  }, [isOnline, syncQueuedChanges]);

  const addSurvey = useCallback(
    async (input: Omit<Survey, "id" | "createdAt" | "updatedAt" | "status">) => {
      const now = new Date().toISOString();
      const survey: Survey = {
        id: uid(),
        createdAt: now,
        updatedAt: now,
        status: isOnline ? "synced" : "pending",
        ...input,
      };

      await upsertSurvey(survey);

      if (isOnline) {
        try {
          await pushSurvey(survey);
          await upsertSurvey({ ...survey, status: "synced" });
        } catch {
          await upsertSurvey({ ...survey, status: "failed" });
          await queueChange({ id: survey.id, type: "upsert" });
        }
      } else {
        await queueChange({ id: survey.id, type: "upsert" });
      }

      await refresh();
    },
    [isOnline, refresh]
  );

  const remove = useCallback(
    async (id: string) => {
      if (isOnline) {
        try {
          await pushDelete(id);
          await deleteSurvey(id);
        } catch {
          await queueChange({ id, type: "delete" });
        }
      } else {
        await queueChange({ id, type: "delete" });
        await deleteSurvey(id);
      }
      await refresh();
    },
    [isOnline, refresh]
  );

  return {
    surveys,
    syncing,
    error,
    addSurvey,
    removeSurvey: remove,
    refresh,
    syncQueuedChanges,
  };
}
```

