# 4) Local repository

## Survey repository functions
```ts
// surveyRepository.ts
import { db } from "./db";
import { Survey } from "./types";

function runSql(sql: string, params: any[] = []): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

function querySql<T>(sql: string, params: any[] = []): Promise<T[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        (_, result) => {
          const items: T[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            items.push(result.rows.item(i));
          }
          resolve(items);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function getSurveys(): Promise<Survey[]> {
  return querySql<Survey>(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const rows = await querySql<Survey>(`SELECT * FROM surveys WHERE id = ? LIMIT 1`, [id]);
  return rows[0] ?? null;
}

export async function upsertSurvey(survey: Survey): Promise<void> {
  await runSql(
    `INSERT OR REPLACE INTO surveys
    (id, serverId, title, notes, latitude, longitude, createdAt, updatedAt, deletedAt, syncStatus, version)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.serverId ?? null,
      survey.title,
      survey.notes ?? null,
      survey.latitude,
      survey.longitude,
      survey.createdAt,
      survey.updatedAt,
      survey.deletedAt ?? null,
      survey.syncStatus,
      survey.version,
    ]
  );
}

export async function markSurveyDeleted(id: string, updatedAt: string): Promise<void> {
  await runSql(
    `UPDATE surveys SET deletedAt = ?, updatedAt = ?, syncStatus = ? WHERE id = ?`,
    [updatedAt, updatedAt, "pending_delete", id]
  );
}
```

