// syncQueue.ts
import { db } from "./db";
import { SyncQueueItem } from "./types";

function runSql(sql: string, params: any[] = []): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

function querySql<T>(sql: string, params: any[] = []): Promise<T[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        (_, result) => {
          const items: T[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            items.push(result.rows.item(i));
          }
          resolve(items);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function enqueue(item: SyncQueueItem): Promise<void> {
  await runSql(
    `INSERT INTO sync_queue (id, entityType, entityId, operation, payload, createdAt, attempts)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [
      item.id,
      item.entityType,
      item.entityId,
      item.operation,
      item.payload,
      item.createdAt,
      item.attempts,
    ]
  );
}

export async function getQueue(): Promise<SyncQueueItem[]> {
  return querySql<SyncQueueItem>(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );
}

export async function removeQueueItem(id: string): Promise<void> {
  await runSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export async function incrementAttempts(id: string): Promise<void> {
  await runSql(
    `UPDATE sync_queue SET attempts = attempts + 1 WHERE id = ?`,
    [id]
  );
}
