# 6) Survey CRUD with offline support

## Create/update locally and queue sync
```ts
// surveyService.ts
import { v4 as uuidv4 } from "uuid";
import { Survey } from "./types";
import { upsertSurvey } from "./surveyRepository";
import { enqueue } from "./syncQueue";

export async function createSurveyOffline(input: {
  title: string;
  notes?: string;
  latitude: number;
  longitude: number;
}): Promise<Survey> {
  const now = new Date().toISOString();
  const survey: Survey = {
    id: uuidv4(),
    serverId: null,
    title: input.title,
    notes: input.notes ?? null,
    latitude: input.latitude,
    longitude: input.longitude,
    createdAt: now,
    updatedAt: now,
    deletedAt: null,
    syncStatus: "pending_create",
    version: 1,
  };

  await upsertSurvey(survey);
  await enqueue({
    id: uuidv4(),
    entityType: "survey",
    entityId: survey.id,
    operation: "create",
    payload: JSON.stringify(survey),
    createdAt: now,
    attempts: 0,
  });

  return survey;
}

export async function updateSurveyOffline(
  survey: Survey,
  patch: Partial<Pick<Survey, "title" | "notes" | "latitude" | "longitude">>
): Promise<Survey> {
  const now = new Date().toISOString();
  const updated: Survey = {
    ...survey,
    ...patch,
    updatedAt: now,
    version: survey.version + 1,
    syncStatus: survey.syncStatus === "pending_create" ? "pending_create" : "pending_update",
  };

  await upsertSurvey(updated);
  await enqueue({
    id: uuidv4(),
    entityType: "survey",
    entityId: updated.id,
    operation: "update",
    payload: JSON.stringify(updated),
    createdAt: now,
    attempts: 0,
  });

  return updated;
}

export async function deleteSurveyOffline(survey: Survey): Promise<void> {
  const now = new Date().toISOString();
  const deleted: Survey = {
    ...survey,
    deletedAt: now,
    updatedAt: now,
    version: survey.version + 1,
    syncStatus: "pending_delete",
  };

  await upsertSurvey(deleted);
  await enqueue({
    id: uuidv4(),
    entityType: "survey",
    entityId: deleted.id,
    operation: "delete",
    payload: JSON.stringify(deleted),
    createdAt: now,
    attempts: 0,
  });
}
