## Sync processor
```ts
// syncEngine.ts
import { getQueue, removeQueueItem, incrementAttempts } from "./syncQueue";
import { apiCreateSurvey, apiUpdateSurvey, apiDeleteSurvey, apiFetchChanges } from "./api";
import { getSurveyById, upsertSurvey } from "./surveyRepository";
import { SyncQueueItem, Survey } from "./types";

let lastSyncAt = new Date(0).toISOString();

export async function syncNow(): Promise<void> {
  const queue = await getQueue();

  for (const item of queue) {
    try {
      await processQueueItem(item);
      await removeQueueItem(item.id);
    } catch (err) {
      await incrementAttempts(item.id);
    }
  }

  await pullChanges();
  lastSyncAt = new Date().toISOString();
}

async function processQueueItem(item: SyncQueueItem): Promise<void> {
  const survey = JSON.parse(item.payload) as Survey;

  if (item.operation === "create") {
    const created = await apiCreateSurvey({
      localId: survey.id,
      title: survey.title,
      notes: survey.notes,
      latitude: survey.latitude,
      longitude: survey.longitude,
      createdAt: survey.createdAt,
      updatedAt: survey.updatedAt,
    });

    const updatedLocal: Survey = {
      ...survey,
      serverId: created.id,
      syncStatus: "synced",
    };
    await upsertSurvey(updatedLocal);
    return;
  }

  if (item.operation === "update") {
    if (!survey.serverId) throw new Error("Cannot update without serverId");
    const updated = await apiUpdateSurvey(survey.serverId, {
      title: survey.title,
      notes: survey.notes,
      latitude: survey.latitude,
      longitude: survey.longitude,
      updatedAt: survey.updatedAt,
      version: survey.version,
      localId: survey.id,
    });

    const updatedLocal: Survey = {
      ...survey,
      serverId: updated.id,
      syncStatus: "synced",
    };
    await upsertSurvey(updatedLocal);
    return;
  }

  if (item.operation === "delete") {
    if (!survey.serverId) {
      // If never synced to server, just mark locally deleted
      return;
    }
    await apiDeleteSurvey(survey.serverId);
    return;
  }
}

async function pullChanges(): Promise<void> {
  const changes = await apiFetchChanges(lastSyncAt);

  for (const remote of changes.surveys as Survey[]) {
    const local = await getSurveyById(remote.id);

    if (!local) {
      await upsertSurvey({
        ...remote,
        syncStatus: "synced",
      });
      continue;
    }

    // Simple conflict handling:
    // if local has pending changes and remote updated more recently, mark conflict
    if (local.syncStatus !== "synced" && local.updatedAt !== remote.updatedAt) {
      await upsertSurvey({
        ...local,
        syncStatus: "conflict",
      });
      continue;
    }

    await upsertSurvey({
      ...remote,
      syncStatus: "synced",
    });
  }
}
```

