# 10) Backend example

Here’s a simple Node/Express backend structure.

```ts
// server.ts
import express from "express";

const app = express();
app.use(express.json());

const surveys: any[] = [];
const changes: any[] = [];

app.post("/surveys", (req, res) => {
  const id = String(Date.now());
  const survey = { id, ...req.body };
  surveys.push(survey);
  changes.push({ type: "create", survey, updatedAt: new Date().toISOString() });
  res.json(survey);
});

app.put("/surveys/:id", (req, res) => {
  const idx = surveys.findIndex(s => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: "Not found" });

  surveys[idx] = { ...surveys[idx], ...req.body };
  changes.push({ type: "update", survey: surveys[idx], updatedAt: new Date().toISOString() });
  res.json(surveys[idx]);
});

app.delete("/surveys/:id", (req, res) => {
  const idx = surveys.findIndex(s => s.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: "Not found" });

  const deleted = surveys.splice(idx, 1)[0];
  changes.push({ type: "delete", survey: deleted, updatedAt: new Date().toISOString() });
  res.json({ success: true });
});

app.get("/sync/surveys", (req, res) => {
  const since = String(req.query.since ?? "1970-01-01T00:00:00.000Z");
  const filtered = changes.filter(c => c.updatedAt > since);

  res.json({
    surveys: filtered
      .filter(c => c.type !== "delete")
      .map(c => c.survey),
    deleted: filtered
      .filter(c => c.type === "delete")
      .map(c => c.survey.id),
  });
});

app.listen(3000, () => console.log("Server running on 3000"));
```

