## `backend/src/db.ts`

This is a simple in-memory “database” for demo purposes. Swap this with PostgreSQL, SQLite, or MongoDB in production.

```ts
export type SurveyRecord = {
  id: string;
  clientId: string; // id generated on device, used for offline create/update
  title: string;
  notes: string;
  latitude: number;
  longitude: number;
  updatedAt: string; // ISO timestamp
  deleted?: boolean;
};

const surveys = new Map<string, SurveyRecord>();

export function listSurveys(): SurveyRecord[] {
  return [...surveys.values()].filter(s => !s.deleted);
}

export function getSurvey(id: string): SurveyRecord | undefined {
  return surveys.get(id);
}

export function upsertSurvey(record: SurveyRecord): SurveyRecord {
  const existing = surveys.get(record.id);
  if (!existing || new Date(record.updatedAt) >= new Date(existing.updatedAt)) {
    surveys.set(record.id, record);
  }
  return surveys.get(record.id)!;
}

export function deleteSurvey(id: string, updatedAt: string): SurveyRecord {
  const existing = surveys.get(id);

  if (!existing || new Date(updatedAt) >= new Date(existing.updatedAt)) {
    const deletedRecord: SurveyRecord = {
      ...(existing ?? {
        id,
        clientId: id,
        title: "",
        notes: "",
        latitude: 0,
        longitude: 0
      }),
      deleted: true,
      updatedAt
    };
    surveys.set(id, deletedRecord);
  }

  return surveys.get(id)!;
}
```

