  if (!body.id || !body.clientId) {
    return res.status(400).json({ error: "Missing id/clientId" });
  }

  const saved = upsertSurvey({
    ...body,
    updatedAt: body.updatedAt ?? new Date().toISOString()
  });

  res.json({ data: saved });
});

routes.put("/surveys/:id", (req, res) => {
  const body = req.body as Partial<SurveyRecord>;

  if (!req.params.id) {
    return res.status(400).json({ error: "Missing id" });
  }

  const existing = getSurvey(req.params.id);
  const record: SurveyRecord = {
    id: req.params.id,
    clientId: body.clientId ?? existing?.clientId ?? req.params.id,
    title: body.title ?? existing?.title ?? "",
    notes: body.notes ?? existing?.notes ?? "",
    latitude: body.latitude ?? existing?.latitude ?? 0,
    longitude: body.longitude ?? existing?.longitude ?? 0,
    updatedAt: body.updatedAt ?? new Date().toISOString(),
    deleted: body.deleted ?? false
  };

  const saved = upsertSurvey(record);
  res.json({ data: saved });
});

routes.delete("/surveys/:id", (req, res) => {
  const updatedAt = typeof req.body?.updatedAt === "string"
    ? req.body.updatedAt
    : new Date().toISOString();

  const saved = deleteSurvey(req.params.id, updatedAt);
  res.json({ data: saved });
});
