## `frontend/src/db.ts`

Local persistence for surveys and pending mutations.

```ts
import { openDB } from "idb";

export type SurveyRecord = {
  id: string;
  clientId: string;
  title: string;
  notes: string;
  latitude: number;
  longitude: number;
  updatedAt: string;
  deleted?: boolean;
};

export type PendingMutation =
  | { type: "upsert"; survey: SurveyRecord }
  | { type: "delete"; id: string; updatedAt: string };

const DB_NAME = "survey-app";
const DB_VERSION = 1;

const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains("surveys")) {
      db.createObjectStore("surveys", { keyPath: "id" });
    }
    if (!db.objectStoreNames.contains("pending")) {
      db.createObjectStore("pending", { keyPath: "key", autoIncrement: true });
    }
  }
});

export async function saveSurveyLocal(survey: SurveyRecord) {
  const db = await dbPromise;
  await db.put("surveys", survey);
}

export async function getAllSurveysLocal(): Promise<SurveyRecord[]> {
  const db = await dbPromise;
  return (await db.getAll("surveys")) as SurveyRecord[];
}

export async function deleteSurveyLocal(id: string) {
  const db = await dbPromise;
  await db.delete("surveys", id);
}

export async function queueMutation(mutation: PendingMutation) {
  const db = await dbPromise;
  await db.add("pending", {
    ...mutation,
    createdAt: Date.now()
  });
}

export async function getPendingMutations(): Promise<any[]> {
  const db = await dbPromise;
  return await db.getAll("pending");
}

export async function clearPendingMutations() {
  const db = await dbPromise;
  const tx = db.transaction("pending", "readwrite");
  await tx.objectStore("pending").clear();
  await tx.done;
}
```

