## `frontend/src/sync.ts`

This syncs pending operations when the connection returns.

```ts
import {
  getPendingMutations,
  clearPendingMutations,
  saveSurveyLocal,
  deleteSurveyLocal
} from "./db";
import { saveSurveyRemote, deleteSurveyRemote } from "./api";

export async function syncPendingMutations() {
  if (!navigator.onLine) return;

  const pending = await getPendingMutations();
  if (!pending.length) return;

  for (const mutation of pending) {
    try {
      if (mutation.type === "upsert") {
        const result = await saveSurveyRemote(mutation.survey);
        await saveSurveyLocal(result.data);
      }

      if (mutation.type === "delete") {
        await deleteSurveyRemote(mutation.id, mutation.updatedAt);
        await deleteSurveyLocal(mutation.id);
      }
    } catch (err) {
      console.error("Sync error:", err);
      return; // stop so we try again later
    }
  }

  await clearPendingMutations();
}
```

