import { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import {
  getAllSurveysLocal,
  saveSurveyLocal,
  queueMutation,
  deleteSurveyLocal,
  SurveyRecord
} from "./db";
import { fetchSurveys } from "./api";
import { syncPendingMutations } from "./sync";

export default function App() {
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [title, setTitle] = useState("");
  const [notes, setNotes] = useState("");
  const [latitude, setLatitude] = useState(0);
  const [longitude, setLongitude] = useState(0);

  async function loadData() {
    const local = await getAllSurveysLocal();
    setSurveys(local);
  }

  async function refreshFromServerIfOnline() {
    if (!navigator.onLine) {
      await loadData();
      return;
    }

    try {
      const remote = await fetchSurveys();
      const items = remote.data as SurveyRecord[];

      for (const item of items) {
        await saveSurveyLocal(item);
      }

      await syncPendingMutations();
      await loadData();
    } catch {
      await loadData();
    }
  }

  useEffect(() => {
    refreshFromServerIfOnline();

    const onOnline = () => syncPendingMutations().then(refreshFromServerIfOnline);
    window.addEventListener("online", onOnline);

    return () => window.removeEventListener("online", onOnline);
  }, []);

  async function handleCreate() {
    const survey: SurveyRecord = {
      id: uuidv4(),
      clientId: uuidv4(),
      title,
      notes,
      latitude,
      longitude,
      updatedAt: new Date().toISOString()
    };

    await saveSurveyLocal(survey);
    await queueMutation({ type: "upsert", survey });

    setTitle("");
    setNotes("");
    setLatitude(0);
    setLongitude(0);

    await loadData();
  }

  async function handleDelete(id: string) {
    const updatedAt = new Date().toISOString();

    await queueMutation({ type: "delete", id, updatedAt });
    await deleteSurveyLocal(id);

    await loadData();
  }

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h1>Field Survey App</h1>
      <p>
        Status: {navigator.onLine ? "Online" : "Offline"}
      </p>

      <div style={{ display: "grid", gap: 8, maxWidth: 400 }}>
        <input
          placeholder="Survey title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <input
          type="number"
          placeholder="Latitude"
          value={latitude}
          onChange={(e) => setLatitude(Number(e.target.value))}
        />
        <input
          type="number"
          placeholder="Longitude"
          value={longitude}
          onChange={(e) => setLongitude(Number(e.target.value))}
        />
        <button onClick={handleCreate}>Save Survey</button>
      </div>

      <hr />

      <button onClick={refreshFromServerIfOnline}>Refresh / Sync</button>

      <h2>Surveys</h2>
      {surveys.length === 0 ? (
        <p>No surveys available.</p>
      ) : (
        <ul>
          {surveys.map((s) => (
            <li key={s.id} style={{ marginBottom: 12 }}>
              <strong>{s.title}</strong>
              <div>{s.notes}</div>
              <div>
                Lat: {s.latitude}, Lng: {s.longitude}
              </div>
              <small>Updated: {s.updatedAt}</small>
              <br />
              <button onClick={() => handleDelete(s.id)}>Delete</button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
