# 3) Local repository

```ts
// surveyRepository.ts
import { getDb } from './db';
import { Survey, PendingAction } from './types';
import { v4 as uuidv4 } from 'uuid';

const db = getDb();

export const saveSurveyLocal = (survey: Survey) => {
  db.transaction(tx => {
    tx.executeSql(
      `INSERT OR REPLACE INTO surveys 
       (id, title, locationName, latitude, longitude, notes, updatedAt, deletedAt)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        survey.id,
        survey.title,
        survey.locationName,
        survey.latitude,
        survey.longitude,
        survey.notes ?? null,
        survey.updatedAt,
        survey.deletedAt ?? null,
      ]
    );
  });
};

export const getAllSurveysLocal = (): Promise<Survey[]> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`,
        [],
        (_, result) => {
          const rows = result.rows._array as Survey[];
          resolve(rows);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const markSurveyDeletedLocal = (id: string) => {
  const now = new Date().toISOString();
  db.transaction(tx => {
    tx.executeSql(
      `UPDATE surveys SET deletedAt = ?, updatedAt = ? WHERE id = ?`,
      [now, now, id]
    );
  });
};

export const queueAction = (action: Omit<PendingAction, 'id' | 'createdAt'>) => {
  const record: PendingAction = {
    id: uuidv4(),
    createdAt: new Date().toISOString(),
    ...action,
  };

  db.transaction(tx => {
    tx.executeSql(
      `INSERT INTO pending_actions (id, entityId, type, payload, createdAt)
       VALUES (?, ?, ?, ?, ?)`,
      [record.id, record.entityId, record.type, record.payload, record.createdAt]
    );
  });
};

export const getPendingActions = (): Promise<PendingAction[]> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM pending_actions ORDER BY createdAt ASC`,
        [],
        (_, result) => resolve(result.rows._array as PendingAction[]),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const clearPendingAction = (actionId: string) => {
  db.transaction(tx => {
    tx.executeSql(`DELETE FROM pending_actions WHERE id = ?`, [actionId]);
  });
};

export const setSyncMeta = (key: string, value: string) => {
  db.transaction(tx => {
    tx.executeSql(
      `INSERT OR REPLACE INTO sync_meta (key, value) VALUES (?, ?)`,
      [key, value]
    );
  });
};

export const getSyncMeta = (key: string): Promise<string | null> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT value FROM sync_meta WHERE key = ?`,
        [key],
        (_, result) => {
          if (result.rows.length === 0) resolve(null);
          else resolve(result.rows.item(0).value);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};
```

