# 5) Sync service

This is the core offline-first logic.

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import { api, SyncPayload, SyncResponse, ServerSurvey } from './api';
import {
  getPendingActions,
  clearPendingAction,
  getSyncMeta,
  setSyncMeta,
  saveSurveyLocal,
} from './surveyRepository';
import { Survey } from './types';

const SERVER_TIME_KEY = 'lastSyncAt';

const applyServerSurveyToLocal = (serverSurvey: ServerSurvey) => {
  const local: Survey = {
    ...serverSurvey,
  };
  saveSurveyLocal(local);
};

export const syncNow = async () => {
  const netState = await NetInfo.fetch();
  if (!netState.isConnected) return;

  const pendingActions = await getPendingActions();
  const lastSyncAt = await getSyncMeta(SERVER_TIME_KEY);

  const payload: SyncPayload = {
    actions: pendingActions,
    lastSyncAt,
  };

  const res = await api.post<SyncResponse>('/sync', payload);
  const { appliedActionIds, surveys, serverTime } = res.data;

  // Clear successfully applied actions
  for (const actionId of appliedActionIds) {
    await clearPendingAction(actionId);
  }

  // Merge pulled server state into local DB
  for (const survey of surveys) {
    applyServerSurveyToLocal(survey);
  }

  await setSyncMeta(SERVER_TIME_KEY, serverTime);
};
```

