# 9) Server sync endpoint example

Here is a simple Node.js/Express backend for syncing.

```ts
// server.ts
import express from 'express';

const app = express();
app.use(express.json());

let surveys: any[] = [];

app.post('/sync', (req, res) => {
  const { actions, lastSyncAt } = req.body;

  const appliedActionIds: string[] = [];

  for (const action of actions) {
    const payload = JSON.parse(action.payload);

    if (action.type === 'CREATE') {
      surveys = surveys.filter(s => s.id !== payload.id);
      surveys.push(payload);
    }

    if (action.type === 'UPDATE') {
      surveys = surveys.map(s => (s.id === payload.id ? payload : s));
    }

    if (action.type === 'DELETE') {
      surveys = surveys.map(s =>
        s.id === payload.id ? { ...s, deletedAt: new Date().toISOString() } : s
      );
    }

    appliedActionIds.push(action.id);
  }

  const serverTime = new Date().toISOString();

  const changedSinceLastSync = lastSyncAt
    ? surveys.filter(s => s.updatedAt > lastSyncAt)
    : surveys;

  res.json({
    appliedActionIds,
    surveys: changedSinceLastSync,
    serverTime,
  });
});

app.listen(3000, () => console.log('Sync server running on port 3000'));
```

