## 4) Local repository

### `surveyRepository.ts`

```ts
import { run, getAll, getOne } from './db';

export type SurveyPoint = {
  id: string;
  projectId: string;
  latitude: number;
  longitude: number;
  notes?: string;
  photos?: string[];
  updatedAt: string;
  deleted?: boolean;
  syncStatus: 'synced' | 'pending' | 'failed';
};

function rowToSurveyPoint(row: any): SurveyPoint {
  return {
    id: row.id,
    projectId: row.project_id,
    latitude: row.latitude,
    longitude: row.longitude,
    notes: row.notes ?? undefined,
    photos: row.photos ? JSON.parse(row.photos) : [],
    updatedAt: row.updated_at,
    deleted: !!row.deleted,
    syncStatus: row.sync_status,
  };
}

export function upsertSurveyPoint(point: SurveyPoint) {
  run(
    `
    INSERT INTO survey_points
      (id, project_id, latitude, longitude, notes, photos, updated_at, deleted, sync_status)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      project_id=excluded.project_id,
      latitude=excluded.latitude,
      longitude=excluded.longitude,
      notes=excluded.notes,
      photos=excluded.photos,
      updated_at=excluded.updated_at,
      deleted=excluded.deleted,
      sync_status=excluded.sync_status
    `,
    [
      point.id,
      point.projectId,
      point.latitude,
      point.longitude,
      point.notes ?? null,
      JSON.stringify(point.photos ?? []),
      point.updatedAt,
      point.deleted ? 1 : 0,
      point.syncStatus,
    ]
  );
}

export function deleteSurveyPoint(id: string) {
  run(`UPDATE survey_points SET deleted = 1, sync_status = 'pending' WHERE id = ?`, [id]);
}

export function getSurveyPoints(): SurveyPoint[] {
  return getAll<any>(`SELECT * FROM survey_points WHERE deleted = 0 ORDER BY updated_at DESC`).map(
    rowToSurveyPoint
  );
}

export function getSurveyPointById(id: string): SurveyPoint | null {
  const row = getOne<any>(`SELECT * FROM survey_points WHERE id = ?`, [id]);
  return row ? rowToSurveyPoint(row) : null;
}

export function markSyncStatus(id: string, status: SurveyPoint['syncStatus']) {
  run(`UPDATE survey_points SET sync_status = ? WHERE id = ?`, [status, id]);
}
