## 5) Sync queue repository

### `syncQueue.ts`

```ts
import { run, getAll } from './db';

export type QueueItem = {
  id: number;
  entity_type: string;
  entity_id: string;
  operation: 'upsert' | 'delete';
  payload: string;
  created_at: string;
  attempts: number;
  last_error?: string | null;
};

export function enqueue(item: Omit<QueueItem, 'id' | 'attempts' | 'last_error'>) {
  run(
    `
    INSERT INTO sync_queue
      (entity_type, entity_id, operation, payload, created_at, attempts, last_error)
    VALUES (?, ?, ?, ?, ?, 0, NULL)
    `,
    [item.entity_type, item.entity_id, item.operation, item.payload, item.created_at]
  );
}

export function getPendingQueue(): QueueItem[] {
  return getAll<any>(`SELECT * FROM sync_queue ORDER BY id ASC`) as QueueItem[];
}

export function removeQueueItem(id: number) {
  run(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export function incrementAttempt(id: number, error: string) {
  run(
    `UPDATE sync_queue SET attempts = attempts + 1, last_error = ? WHERE id = ?`,
    [error, id]
  );
}
```

