## 7) Sync service

This is the heart of offline-first behavior.

### `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import { fetchSurveyPoints, upsertSurveyPoint as apiUpsert, deleteSurveyPoint as apiDelete } from './api';
import { getPendingQueue, removeQueueItem, incrementAttempt } from './syncQueue';
import { getSurveyPoints, upsertSurveyPoint, markSyncStatus } from './surveyRepository';

let syncing = false;

export async function syncNow() {
  if (syncing) return;
  syncing = true;

  try {
    const state = await NetInfo.fetch();
    if (!state.isConnected) return;

    // 1) Push local queued changes
    const pending = getPendingQueue();

    for (const item of pending) {
      try {
        const payload = JSON.parse(item.payload);

        if (item.operation === 'upsert') {
          await apiUpsert(payload);
        } else if (item.operation === 'delete') {
          await apiDelete(item.entity_id);
        }

        removeQueueItem(item.id);
        markSyncStatus(item.entity_id, 'synced');
      } catch (e: any) {
        incrementAttempt(item.id, e.message || 'Sync failed');
        markSyncStatus(item.entity_id, 'failed');
      }
    }

    // 2) Pull server changes and merge locally
    const remotePoints = await fetchSurveyPoints();
    for (const remote of remotePoints) {
      const local = getSurveyPoints().find((p) => p.id === remote.id);

      // Simple last-write-wins conflict resolution
      if (!local || new Date(remote.updatedAt) >= new Date(local.updatedAt)) {
        upsertSurveyPoint({
          id: remote.id,
          projectId: remote.projectId,
          latitude: remote.latitude,
          longitude: remote.longitude,
          notes: remote.notes,
          photos: remote.photos,
          updatedAt: remote.updatedAt,
          deleted: !!remote.deleted,
          syncStatus: 'synced',
        });
      }
    }
  } finally {
    syncing = false;
  }
}

export function startAutoSync() {
  NetInfo.addEventListener((state) => {
    if (state.isConnected) {
      syncNow().catch(console.error);
    }
  });
}
```

