import { upsertSurveyPoint } from './surveyRepository';
import { enqueue } from './syncQueue';

export function saveSurveyPoint(point: {
  id: string;
  projectId: string;
  latitude: number;
  longitude: number;
  notes?: string;
  photos?: string[];
}) {
  const record = {
    ...point,
    updatedAt: new Date().toISOString(),
    deleted: false,
    syncStatus: 'pending' as const,
  };

  // Save locally right away
  upsertSurveyPoint(record);

  // Queue for sync
  enqueue({
    entity_type: 'survey_point',
    entity_id: record.id,
    operation: 'upsert',
    payload: JSON.stringify(record),
    created_at: record.updatedAt,
  });

  return record;
}
