## 4) Local repository

```ts
// surveyRepository.ts
import { getDB } from './db';
import { Survey, SyncQueueItem } from './types';
import { v4 as uuidv4 } from 'uuid';

export async function upsertSurveyLocal(survey: Survey) {
  const db = getDB();
  await db.executeSql(
    `
    INSERT OR REPLACE INTO surveys
    (id, projectId, name, latitude, longitude, notes, updatedAt, version, deleted)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `,
    [
      survey.id,
      survey.projectId,
      survey.name,
      survey.latitude,
      survey.longitude,
      survey.notes ?? null,
      survey.updatedAt,
      survey.version,
      survey.deleted ? 1 : 0,
    ]
  );
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = getDB();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (result.rows.length === 0) return null;

  const row = result.rows.item(0);
  return {
    id: row.id,
    projectId: row.projectId,
    name: row.name,
    latitude: row.latitude,
    longitude: row.longitude,
    notes: row.notes ?? undefined,
    updatedAt: row.updatedAt,
    version: row.version,
    deleted: row.deleted === 1,
  };
}

export async function listSurveys(): Promise<Survey[]> {
  const db = getDB();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`);

  const items: Survey[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    const row = result.rows.item(i);
    items.push({
      id: row.id,
      projectId: row.projectId,
      name: row.name,
      latitude: row.latitude,
      longitude: row.longitude,
      notes: row.notes ?? undefined,
      updatedAt: row.updatedAt,
      version: row.version,
      deleted: row.deleted === 1,
    });
  }
  return items;
}

export async function createSurveyOffline(data: Omit<Survey, 'id' | 'updatedAt' | 'version'>) {
  const now = new Date().toISOString();
  const survey: Survey = {
    ...data,
    id: uuidv4(),
    updatedAt: now,
    version: 1,
    deleted: false,
  };

  await upsertSurveyLocal(survey);
  await enqueueChange('CREATE', survey.id, survey);
  return survey;
}

export async function updateSurveyOffline(id: string, patch: Partial<Omit<Survey, 'id'>>) {
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const updated: Survey = {
    ...existing,
    ...patch,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  await upsertSurveyLocal(updated);
  await enqueueChange('UPDATE', updated.id, updated);
  return updated;
}

export async function deleteSurveyOffline(id: string) {
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const deleted: Survey = {
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  await upsertSurveyLocal(deleted);
  await enqueueChange('DELETE', deleted.id, deleted);
  return deleted;
}

async function enqueueChange(action: 'CREATE' | 'UPDATE' | 'DELETE', entityId: string, payload: Survey) {
  const db = getDB();
  const item: SyncQueueItem = {
    id: uuidv4(),
    entityId,
    action,
    payload: JSON.stringify(payload),
    createdAt: new Date().toISOString(),
    retryCount: 0,
  };

  await db.executeSql(
    `
    INSERT INTO sync_queue (id, entityId, action, payload, createdAt, retryCount, lastError)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    `,
    [item.id, item.entityId, item.action, item.payload, item.createdAt, item.retryCount, null]
  );
}
```

