## 5) Sync service

This service:
- reads pending queue items
- sends them to the server
- removes successful items
- retries failed ones

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import { getDB } from './db';
import { Survey } from './types';

const API_BASE = 'https://your-api.example.com';

export async function isOnline(): Promise<boolean> {
  const state = await NetInfo.fetch();
  return Boolean(state.isConnected && state.isInternetReachable);
}

export async function syncPendingChanges() {
  if (!(await isOnline())) return;

  const db = getDB();
  const [queueResult] = await db.executeSql(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );

  for (let i = 0; i < queueResult.rows.length; i++) {
    const item = queueResult.rows.item(i);
    const payload: Survey = JSON.parse(item.payload);

    try {
      const res = await fetch(`${API_BASE}/sync`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: item.action,
          survey: payload,
        }),
      });

      if (!res.ok) {
        throw new Error(`Sync failed with status ${res.status}`);
      }

      const data = await res.json();

      // Update local record with server version if needed
      if (data.survey) {
        await db.executeSql(
          `
          UPDATE surveys
          SET updatedAt = ?, version = ?, deleted = ?
          WHERE id = ?
          `,
          [
            data.survey.updatedAt,
            data.survey.version,
            data.survey.deleted ? 1 : 0,
            data.survey.id,
          ]
        );
      }

      // Remove from queue on success
      await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [item.id]);
    } catch (error: any) {
      await db.executeSql(
        `
        UPDATE sync_queue
        SET retryCount = retryCount + 1, lastError = ?
        WHERE id = ?
        `,
        [String(error?.message ?? error), item.id]
      );
    }
  }
}
```

