## 9) Example backend sync endpoint

Here’s a simple Node/Express endpoint for syncing:

```ts
// server.ts
import express from 'express';

const app = express();
app.use(express.json());

type Survey = {
  id: string;
  projectId: string;
  name: string;
  latitude: number;
  longitude: number;
  notes?: string;
  updatedAt: string;
  version: number;
  deleted?: boolean;
};

const store = new Map<string, Survey>();

app.post('/sync', (req, res) => {
  const { action, survey } = req.body as { action: string; survey: Survey };

  const existing = store.get(survey.id);

  // Simple conflict detection
  if (
    existing &&
    existing.version > survey.version &&
    existing.updatedAt > survey.updatedAt
  ) {
    return res.status(409).json({
      conflict: true,
      serverSurvey: existing,
    });
  }

  if (action === 'DELETE') {
    store.set(survey.id, { ...survey, deleted: true, version: survey.version });
  } else {
    store.set(survey.id, { ...survey });
  }

  res.json({
    ok: true,
    survey: store.get(survey.id),
  });
});

app.listen(3000, () => {
  console.log('Sync server running on port 3000');
});
```

