# 4) Repository for local writes

## `surveyRepository.ts`
```ts
import { getDb } from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id?: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos?: string[];
};

export async function createSurvey(data: Survey) {
  const db = await getDb();
  const id = data.id || uuidv4();
  const now = new Date().toISOString();
  const photosJson = JSON.stringify(data.photos || []);

  await db.transaction(async tx => {
    await tx.executeSql(
      `INSERT INTO surveys
       (id, siteName, latitude, longitude, notes, photos, createdAt, updatedAt, isDeleted, syncStatus, version)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, 'pending', 1)`,
      [id, data.siteName, data.latitude, data.longitude, data.notes, photosJson, now, now]
    );

    await tx.executeSql(
      `INSERT INTO sync_queue (entityType, entityId, action, payload, createdAt, processed)
       VALUES (?, ?, ?, ?, ?, 0)`,
      [
        'survey',
        id,
        'create',
        JSON.stringify({ id, ...data, photos: data.photos || [], createdAt: now, updatedAt: now }),
        now,
      ]
    );
  });

  return id;
}

export async function updateSurvey(id: string, data: Partial<Survey>) {
  const db = await getDb();
  const now = new Date().toISOString();

  const existing = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  const row = existing[0].rows.item(0);

  if (!row) throw new Error('Survey not found');

  const merged = {
    ...row,
    ...data,
    photos: data.photos ?? JSON.parse(row.photos || '[]'),
    updatedAt: now,
    version: row.version + 1,
  };

  await db.transaction(async tx => {
    await tx.executeSql(
      `UPDATE surveys
       SET siteName = ?, latitude = ?, longitude = ?, notes = ?, photos = ?, updatedAt = ?, syncStatus = 'pending', version = ?
       WHERE id = ?`,
      [
        merged.siteName,
        merged.latitude,
        merged.longitude,
        merged.notes,
        JSON.stringify(merged.photos),
        now,
        merged.version,
        id,
      ]
    );

    await tx.executeSql(
      `INSERT INTO sync_queue (entityType, entityId, action, payload, createdAt, processed)
       VALUES (?, ?, ?, ?, ?, 0)`,
      [
        'survey',
        id,
        'update',
        JSON.stringify(merged),
        now,
      ]
    );
  });
}

export async function deleteSurvey(id: string) {
  const db = await getDb();
  const now = new Date().toISOString();

  await db.transaction(async tx => {
    await tx.executeSql(
      `UPDATE surveys
       SET isDeleted = 1, syncStatus = 'pending', updatedAt = ?
       WHERE id = ?`,
      [now, id]
    );

    await tx.executeSql(
      `INSERT INTO sync_queue (entityType, entityId, action, payload, createdAt, processed)
       VALUES (?, ?, ?, ?, ?, 0)`,
      [
        'survey',
        id,
        'delete',
        JSON.stringify({ id, deletedAt: now }),
        now,
      ]
    );
  });
}

export async function listSurveys() {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE isDeleted = 0 ORDER BY updatedAt DESC`
  );

  const items = [];
  for (let i = 0; i < result.rows.length; i++) {
    const row = result.rows.item(i);
    items.push({
      ...row,
      photos: JSON.parse(row.photos || '[]'),
    });
  }
  return items;
}
```

