import NetInfo from '@react-native-community/netinfo';
import { getDb } from './db';

const API_BASE = 'https://your-api.example.com';

async function fetchQueue() {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM sync_queue WHERE processed = 0 ORDER BY createdAt ASC`
  );

  const queue = [];
  for (let i = 0; i < result.rows.length; i++) {
    queue.push(result.rows.item(i));
  }
  return queue;
}

async function markProcessed(queueId: number) {
  const db = await getDb();
  await db.executeSql(`UPDATE sync_queue SET processed = 1 WHERE id = ?`, [queueId]);
}

async function markSurveySynced(id: string, version?: number) {
  const db = await getDb();
  await db.executeSql(
    `UPDATE surveys SET syncStatus = 'synced', version = COALESCE(?, version) WHERE id = ?`,
    [version ?? null, id]
  );
}

async function markSurveyFailed(id: string) {
  const db = await getDb();
  await db.executeSql(
    `UPDATE surveys SET syncStatus = 'failed' WHERE id = ?`,
    [id]
  );
}

export async function syncNow() {
  const state = await NetInfo.fetch();
  if (!state.isConnected) return { success: false, reason: 'offline' };

  const queue = await fetchQueue();

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      let response: Response;

      if (item.action === 'create') {
        response = await fetch(`${API_BASE}/surveys`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.action === 'update') {
        response = await fetch(`${API_BASE}/surveys/${item.entityId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.action === 'delete') {
        response = await fetch(`${API_BASE}/surveys/${item.entityId}`, {
          method: 'DELETE',
          headers: { 'Content-Type': 'application/json' },
        });
      } else {
        continue;
      }

      if (!response.ok) {
        throw new Error(`Sync failed: ${response.status}`);
      }

      const result = await response.json().catch(() => ({}));

      await markProcessed(item.id);

      if (item.action === 'delete') {
        // optionally keep tombstone until full reconciliation
      } else {
        await markSurveySynced(item.entityId, result.version);
      }
    } catch (err) {
      await markSurveyFailed(item.entityId);
      // stop on error if you want strict ordering
      // break;
    }
  }

  return { success: true };
}

export function startAutoSync(onSynced?: () => void) {
  return NetInfo.addEventListener(async state => {
    if (state.isConnected) {
      await syncNow();
      onSynced?.();
    }
  });
}
