# 8) Backend API example

Here’s a minimal Node/Express backend that supports sync.

## Install
```bash
npm install express cors body-parser uuid
```

## `server.ts`
```ts
import express from 'express';
import cors from 'cors';
import bodyParser from 'body-parser';
import { v4 as uuidv4 } from 'uuid';

const app = express();
app.use(cors());
app.use(bodyParser.json());

type Survey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos: string[];
  updatedAt: string;
  version: number;
  isDeleted: boolean;
};

const surveys = new Map<string, Survey>();

app.post('/surveys', (req, res) => {
  const id = req.body.id || uuidv4();

  const survey: Survey = {
    id,
    siteName: req.body.siteName,
    latitude: req.body.latitude,
    longitude: req.body.longitude,
    notes: req.body.notes,
    photos: req.body.photos || [],
    updatedAt: new Date().toISOString(),
    version: 1,
    isDeleted: false,
  };

  surveys.set(id, survey);
  res.json(survey);
});

app.put('/surveys/:id', (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).json({ error: 'Not found' });

  const survey: Survey = {
    ...existing,
    ...req.body,
    id: req.params.id,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  surveys.set(req.params.id, survey);
  res.json(survey);
});

app.delete('/surveys/:id', (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).json({ error: 'Not found' });

  existing.isDeleted = true;
  existing.updatedAt = new Date().toISOString();
  existing.version += 1;

  surveys.set(req.params.id, existing);
  res.json({ success: true, id: req.params.id, version: existing.version });
});

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()).filter(s => !s.isDeleted));
});

app.listen(3000, () => {
  console.log('Server listening on port 3000');
});
```

