# 2) Local SQLite storage

This example uses generic SQLite-style APIs. In React Native, you can adapt this to:
- `expo-sqlite`
- `react-native-sqlite-storage`
- WatermelonDB / Realm / Drizzle

## `db.ts`
```ts
import * as SQLite from 'expo-sqlite';
import { Survey, SyncQueueItem } from './types';

const db = SQLite.openDatabaseSync('survey_app.db');

export function initDb() {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY NOT NULL,
      title TEXT NOT NULL,
      notes TEXT,
      latitude REAL,
      longitude REAL,
      clientUpdatedAt INTEGER NOT NULL,
      serverUpdatedAt INTEGER,
      deleted INTEGER NOT NULL DEFAULT 0,
      syncStatus TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS sync_queue (
      id TEXT PRIMARY KEY NOT NULL,
      entityType TEXT NOT NULL,
      entityId TEXT NOT NULL,
      operation TEXT NOT NULL,
      payload TEXT NOT NULL,
      createdAt INTEGER NOT NULL,
      retries INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS sync_state (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      lastSyncAt INTEGER NOT NULL
    );

    INSERT OR IGNORE INTO sync_state (id, lastSyncAt) VALUES (1, 0);
  `);
}

export function upsertSurvey(survey: Survey) {
  db.runSync(
    `INSERT OR REPLACE INTO surveys
      (id, title, notes, latitude, longitude, clientUpdatedAt, serverUpdatedAt, deleted, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.notes ?? null,
      survey.latitude ?? null,
      survey.longitude ?? null,
      survey.clientUpdatedAt,
      survey.serverUpdatedAt ?? null,
      survey.deleted ? 1 : 0,
      survey.syncStatus,
    ]
  );
}

export function getSurvey(id: string): Survey | null {
  const result = db.getFirstSync<any>(
    `SELECT * FROM surveys WHERE id = ?`,
    [id]
  );

  if (!result) return null;

  return {
    id: result.id,
    title: result.title,
    notes: result.notes ?? undefined,
    latitude: result.latitude ?? undefined,
    longitude: result.longitude ?? undefined,
    clientUpdatedAt: result.clientUpdatedAt,
    serverUpdatedAt: result.serverUpdatedAt ?? undefined,
    deleted: !!result.deleted,
    syncStatus: result.syncStatus,
  };
}

export function getAllSurveys(): Survey[] {
  const rows = db.getAllSync<any>(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY clientUpdatedAt DESC`
  );

  return rows.map(row => ({
    id: row.id,
    title: row.title,
    notes: row.notes ?? undefined,
    latitude: row.latitude ?? undefined,
    longitude: row.longitude ?? undefined,
    clientUpdatedAt: row.clientUpdatedAt,
    serverUpdatedAt: row.serverUpdatedAt ?? undefined,
    deleted: !!row.deleted,
    syncStatus: row.syncStatus,
  }));
}

export function enqueueSync(item: SyncQueueItem) {
  db.runSync(
    `INSERT INTO sync_queue
      (id, entityType, entityId, operation, payload, createdAt, retries, status)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      item.id,
      item.entityType,
      item.entityId,
      item.operation,
      item.payload,
      item.createdAt,
      item.retries,
      item.status,
    ]
  );
}

export function getPendingQueue(): SyncQueueItem[] {
  const rows = db.getAllSync<any>(
    `SELECT * FROM sync_queue WHERE status = 'pending' ORDER BY createdAt ASC`
  );

  return rows.map(row => ({
    id: row.id,
    entityType: row.entityType,
    entityId: row.entityId,
    operation: row.operation,
    payload: row.payload,
    createdAt: row.createdAt,
    retries: row.retries,
    status: row.status,
  }));
}

export function markQueueSent(id: string) {
  db.runSync(`UPDATE sync_queue SET status = 'sent' WHERE id = ?`, [id]);
}

export function markQueueFailed(id: string, retries: number) {
  db.runSync(
    `UPDATE sync_queue SET status = 'failed', retries = ? WHERE id = ?`,
    [retries, id]
  );
}

export function updateSyncStatus(id: string, syncStatus: 'pending' | 'synced' | 'failed') {
  db.runSync(`UPDATE surveys SET syncStatus = ? WHERE id = ?`, [syncStatus, id]);
}

export function setLastSyncAt(ts: number) {
  db.runSync(`UPDATE sync_state SET lastSyncAt = ? WHERE id = 1`, [ts]);
}

export function getLastSyncAt(): number {
  const row = db.getFirstSync<any>(`SELECT lastSyncAt FROM sync_state WHERE id = 1`);
  return row?.lastSyncAt ?? 0;
}
```

