# 3) Survey CRUD with offline-first behavior

## `surveyService.ts`
```ts
import { v4 as uuidv4 } from 'uuid';
import { enqueueSync, getAllSurveys, getSurvey, upsertSurvey, updateSyncStatus } from './db';
import { Survey } from './types';

export function createSurvey(input: { title: string; notes?: string; latitude?: number; longitude?: number }) {
  const now = Date.now();
  const id = uuidv4();

  const survey: Survey = {
    id,
    title: input.title,
    notes: input.notes,
    latitude: input.latitude,
    longitude: input.longitude,
    clientUpdatedAt: now,
    deleted: false,
    syncStatus: 'pending',
  };

  upsertSurvey(survey);
  updateSyncStatus(id, 'pending');

  enqueueSync({
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'create',
    payload: JSON.stringify(survey),
    createdAt: now,
    retries: 0,
    status: 'pending',
  });

  return survey;
}

export function updateSurvey(id: string, changes: Partial<Pick<Survey, 'title' | 'notes' | 'latitude' | 'longitude'>>) {
  const existing = getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  const now = Date.now();
  const updated: Survey = {
    ...existing,
    ...changes,
    clientUpdatedAt: now,
    syncStatus: 'pending',
  };

  upsertSurvey(updated);
  updateSyncStatus(id, 'pending');

  enqueueSync({
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: JSON.stringify(changes),
    createdAt: now,
    retries: 0,
    status: 'pending',
  });

  return updated;
}

export function deleteSurvey(id: string) {
  const existing = getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  const now = Date.now();
  const deleted: Survey = {
    ...existing,
    deleted: true,
    clientUpdatedAt: now,
    syncStatus: 'pending',
  };

  upsertSurvey(deleted);
  updateSyncStatus(id, 'pending');

  enqueueSync({
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: JSON.stringify({ deleted: true }),
    createdAt: now,
    retries: 0,
    status: 'pending',
  });

  return deleted;
}

export function listSurveys() {
  return getAllSurveys();
}
