# 4) Sync engine

This:
- sends queued operations in order
- fetches server changes since last sync
- updates local DB

## `syncEngine.ts`
```ts
import { getLastSyncAt, getPendingQueue, markQueueFailed, markQueueSent, setLastSyncAt, upsertSurvey } from './db';

const API_BASE = 'https://your-api.example.com';

async function apiPost(path: string, body: any) {
  const res = await fetch(`${API_BASE}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    throw new Error(`API error ${res.status}`);
  }

  return res.json();
}

async function apiGet(path: string) {
  const res = await fetch(`${API_BASE}${path}`);
  if (!res.ok) throw new Error(`API error ${res.status}`);
  return res.json();
}

export async function syncNow() {
  const queue = getPendingQueue();

  // Push local changes
  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      await apiPost('/sync/operations', {
        operationId: item.id,
        entityType: item.entityType,
        entityId: item.entityId,
        operation: item.operation,
        payload,
      });

      markQueueSent(item.id);
    } catch (err) {
      markQueueFailed(item.id, item.retries + 1);
      // stop early or continue based on your strategy
      continue;
    }
  }

  // Pull remote changes
  const lastSyncAt = getLastSyncAt();
  const remote = await apiGet(`/sync/changes?since=${lastSyncAt}`);

  if (remote?.surveys?.length) {
    for (const survey of remote.surveys) {
      upsertSurvey({
        id: survey.id,
        title: survey.title,
        notes: survey.notes,
        latitude: survey.latitude,
        longitude: survey.longitude,
        clientUpdatedAt: survey.clientUpdatedAt ?? Date.now(),
        serverUpdatedAt: survey.serverUpdatedAt,
        deleted: !!survey.deleted,
        syncStatus: 'synced',
      });
    }
  }

  setLastSyncAt(Date.now());
}
```

