# 7) Backend sync API

Here’s a minimal Express server.

## `server.ts`
```ts
import express from 'express';

const app = express();
app.use(express.json());

type Survey = {
  id: string;
  title: string;
  notes?: string;
  latitude?: number;
  longitude?: number;
  deleted?: boolean;
  clientUpdatedAt?: number;
  serverUpdatedAt: number;
};

const surveys = new Map<string, Survey>();
const operations: any[] = [];

app.post('/sync/operations', (req, res) => {
  const { operationId, entityId, operation, payload } = req.body;

  operations.push({ operationId, entityId, operation, payload, receivedAt: Date.now() });

  const existing = surveys.get(entityId);

  if (operation === 'create') {
    surveys.set(entityId, {
      ...payload,
      id: entityId,
      serverUpdatedAt: Date.now(),
    });
  }

  if (operation === 'update' && existing) {
    surveys.set(entityId, {
      ...existing,
      ...payload,
      serverUpdatedAt: Date.now(),
    });
  }

  if (operation === 'delete' && existing) {
    surveys.set(entityId, {
      ...existing,
      deleted: true,
      serverUpdatedAt: Date.now(),
    });
  }

  res.json({ ok: true });
});

app.get('/sync/changes', (req, res) => {
  const since = Number(req.query.since || 0);
  const changed = Array.from(surveys.values()).filter(s => s.serverUpdatedAt > since);

  res.json({ surveys: changed });
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

