## 2) IndexedDB storage layer

Using the `idb` library makes this much simpler.

### Install
```bash
npm install idb
```

### `db.ts`
```ts
import { openDB } from "idb";
import type { SurveyRecord } from "./types";

const DB_NAME = "field-survey-app";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains(STORE_NAME)) {
      const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
      store.createIndex("syncStatus", "syncStatus", { unique: false });
      store.createIndex("updatedAt", "updatedAt", { unique: false });
    }
  },
});

export async function saveSurvey(record: SurveyRecord) {
  const db = await dbPromise;
  await db.put(STORE_NAME, record);
}

export async function getSurvey(id: string) {
  const db = await dbPromise;
  return db.get(STORE_NAME, id) as Promise<SurveyRecord | undefined>;
}

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll(STORE_NAME) as Promise<SurveyRecord[]>;
}

export async function getPendingSurveys() {
  const db = await dbPromise;
  const tx = db.transaction(STORE_NAME, "readonly");
  const index = tx.store.index("syncStatus");
  const pending = await index.getAll("pending");
  await tx.done;
  return pending as SurveyRecord[];
}

export async function updateSurvey(record: SurveyRecord) {
  const db = await dbPromise;
  await db.put(STORE_NAME, record);
}

export async function deleteSurvey(id: string) {
  const db = await dbPromise;
  await db.delete(STORE_NAME, id);
}
```

