## 4) Sync manager

This sends pending records when online and marks them synced.

### `sync.ts`
```ts
import { getPendingSurveys, updateSurvey } from "./db";
import { uploadSurvey } from "./api";

export async function syncPendingSurveys() {
  const pending = await getPendingSurveys();

  for (const record of pending) {
    try {
      const result = await uploadSurvey(record);

      await updateSurvey({
        ...record,
        remoteId: result.remoteId,
        syncStatus: "synced",
        updatedAt: new Date().toISOString(),
      });
    } catch (err) {
      console.error("Failed to sync survey:", record.id, err);

      await updateSurvey({
        ...record,
        syncStatus: "failed",
      });
    }
  }
}
```

