## 5) Connectivity detection

Run sync when network returns.

### `useOnlineSync.ts`
```ts
import { useEffect } from "react";
import { syncPendingSurveys } from "./sync";

export function useOnlineSync() {
  useEffect(() => {
    const handleOnline = () => {
      syncPendingSurveys();
    };

    window.addEventListener("online", handleOnline);

    if (navigator.onLine) {
      syncPendingSurveys();
    }

    return () => {
      window.removeEventListener("online", handleOnline);
    };
  }, []);
}
```

