## 6) Local repository

```ts
// surveyRepository.ts
import { getDb } from './db';

export type Survey = {
  id: string;
  title: string;
  notes: string;
  latitude: number;
  longitude: number;
  updatedAt: string;
  deleted: number;
};

export async function saveSurveyLocal(survey: Survey) {
  const db = await getDb();

  await db.executeSql(
    `INSERT OR REPLACE INTO surveys
     (id, title, notes, latitude, longitude, updatedAt, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.notes,
      survey.latitude,
      survey.longitude,
      survey.updatedAt,
      survey.deleted,
    ]
  );

  await db.executeSql(
    `INSERT INTO outbox (entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [
      'survey',
      survey.id,
      'upsert',
      JSON.stringify(survey),
      new Date().toISOString(),
    ]
  );
}

export async function deleteSurveyLocal(id: string) {
  const db = await getDb();
  const now = new Date().toISOString();

  await db.executeSql(
    `UPDATE surveys SET deleted = 1, updatedAt = ? WHERE id = ?`,
    [now, id]
  );

  await db.executeSql(
    `INSERT INTO outbox (entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [
      'survey',
      id,
      'delete',
      JSON.stringify({ id, updatedAt: now }),
      now,
    ]
  );
}

export async function getAllLocalSurveys(): Promise<Survey[]> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );

  const items: Survey[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function getOutboxItems() {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM outbox ORDER BY id ASC`
  );

  const items: any[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function clearOutboxItem(id: number) {
  const db = await getDb();
  await db.executeSql(`DELETE FROM outbox WHERE id = ?`, [id]);
}

export async function getSyncState(key: string): Promise<string | null> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT value FROM sync_state WHERE key = ?`,
    [key]
  );

  if (result.rows.length === 0) return null;
  return result.rows.item(0).value;
}

export async function setSyncState(key: string, value: string) {
  const db = await getDb();
  await db.executeSql(
    `INSERT OR REPLACE INTO sync_state (key, value) VALUES (?, ?)`,
    [key, value]
  );
}
```

