## 7) Sync service

This assumes a backend API with:

- `POST /sync/push` to upload local changes
- `GET /sync/pull?since=<timestamp>` to fetch server changes

### Sync service code

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import {
  getOutboxItems,
  clearOutboxItem,
  getSyncState,
  setSyncState,
  saveSurveyLocal,
} from './surveyRepository';

const API_BASE = 'https://your-api.example.com';

async function pushOutbox() {
  const items = await getOutboxItems();
  if (items.length === 0) return;

  const payload = items.map((item) => ({
    entityType: item.entityType,
    entityId: item.entityId,
    operation: item.operation,
    payload: JSON.parse(item.payload),
    createdAt: item.createdAt,
  }));

  const res = await fetch(`${API_BASE}/sync/push`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ changes: payload }),
  });

  if (!res.ok) throw new Error('Push failed');

  const result = await res.json();

  for (const ackId of result.acknowledgedOutboxIds) {
    await clearOutboxItem(ackId);
  }
}

async function pullRemoteChanges() {
  const lastSync = await getSyncState('lastSyncAt');
  const since = lastSync ?? new Date(0).toISOString();

  const res = await fetch(`${API_BASE}/sync/pull?since=${encodeURIComponent(since)}`);
  if (!res.ok) throw new Error('Pull failed');

  const result = await res.json();
  const changes = result.changes || [];

  for (const change of changes) {
    if (change.entityType === 'survey') {
      await saveSurveyLocal({
        ...change.payload,
        deleted: change.operation === 'delete' ? 1 : 0,
      });
    }
  }

  await setSyncState('lastSyncAt', new Date().toISOString());
}

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  await pushOutbox();
  await pullRemoteChanges();
}
```

