## 11) Simple backend sync example

Here’s a minimal Node.js/Express backend shape.

```ts
import express from 'express';

const app = express();
app.use(express.json());

// Pretend persistent storage
const surveys: any[] = [];
const changesLog: any[] = [];

app.post('/sync/push', (req, res) => {
  const { changes } = req.body;

  const acknowledgedOutboxIds: number[] = [];

  for (const change of changes) {
    if (change.entityType !== 'survey') continue;

    if (change.operation === 'upsert') {
      const item = change.payload;
      const idx = surveys.findIndex((s) => s.id === item.id);
      if (idx >= 0) surveys[idx] = item;
      else surveys.push(item);
      changesLog.push({
        entityType: 'survey',
        operation: 'upsert',
        payload: item,
        updatedAt: item.updatedAt,
      });
    } else if (change.operation === 'delete') {
      const idx = surveys.findIndex((s) => s.id === change.payload.id);
      if (idx >= 0) surveys.splice(idx, 1);
      changesLog.push({
        entityType: 'survey',
        operation: 'delete',
        payload: change.payload,
        updatedAt: change.payload.updatedAt,
      });
    }

    acknowledgedOutboxIds.push(change.id);
  }

  res.json({ acknowledgedOutboxIds });
});

app.get('/sync/pull', (req, res) => {
  const since = String(req.query.since || new Date(0).toISOString());

  const changes = changesLog.filter((c) => c.updatedAt > since);
  res.json({ changes });
});

app.listen(3000, () => console.log('Server running on 3000'));
```

