  updatedAt: string;
  syncStatus: 'synced' | 'pending' | 'failed';
  deleted?: boolean;
}

export interface SyncQueueItem {
  id?: number;
  entityId: string;
  action: 'create' | 'update' | 'delete';
  payload: SurveyRecord;
  createdAt: string;
}

class SurveyDB extends Dexie {
  surveys!: Table<SurveyRecord, string>;
  syncQueue!: Table<SyncQueueItem, number>;

  constructor() {
    super('survey-app-db');

    this.version(1).stores({
      surveys: 'id, updatedAt, syncStatus, deleted',
      syncQueue: '++id, entityId, action, createdAt',
    });
  }
}

export const db = new SurveyDB();
