# 4) Sync service

This handles:
- saving locally
- queueing changes
- syncing when online

## `sync.ts`

```ts
import { db, SurveyRecord, SyncQueueItem } from './db';
import { fetchRemoteSurveys, pushSurvey, deleteRemoteSurvey } from './api';

export async function createSurvey(data: Omit<SurveyRecord, 'id' | 'createdAt' | 'updatedAt' | 'syncStatus'>) {
  const now = new Date().toISOString();
  const record: SurveyRecord = {
    id: crypto.randomUUID(),
    ...data,
    createdAt: now,
    updatedAt: now,
    syncStatus: navigator.onLine ? 'synced' : 'pending',
  };

  await db.surveys.put(record);

  if (!navigator.onLine) {
    await db.syncQueue.add({
      entityId: record.id,
      action: 'create',
      payload: record,
      createdAt: now,
    });
    return record;
  }

  try {
    const saved = await pushSurvey(record);
    await db.surveys.put({ ...saved, syncStatus: 'synced' });
    return saved;
  } catch (err) {
    record.syncStatus = 'failed';
    await db.surveys.put(record);
    await db.syncQueue.add({
      entityId: record.id,
      action: 'create',
      payload: record,
      createdAt: now,
    });
    return record;
  }
}

export async function updateSurvey(id: string, changes: Partial<SurveyRecord>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const updated: SurveyRecord = {
    ...existing,
    ...changes,
    id,
    updatedAt: new Date().toISOString(),
    syncStatus: navigator.onLine ? 'synced' : 'pending',
  };

  await db.surveys.put(updated);

  if (!navigator.onLine) {
    await db.syncQueue.add({
      entityId: id,
      action: 'update',
      payload: updated,
      createdAt: updated.updatedAt,
    });
    return updated;
  }

  try {
    const saved = await pushSurvey(updated);
    await db.surveys.put({ ...saved, syncStatus: 'synced' });
    return saved;
  } catch {
    updated.syncStatus = 'failed';
    await db.surveys.put(updated);
    await db.syncQueue.add({
      entityId: id,
      action: 'update',
      payload: updated,
      createdAt: updated.updatedAt,
    });
    return updated;
  }
}

export async function removeSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const deletedRecord: SurveyRecord = {
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
    syncStatus: navigator.onLine ? 'synced' : 'pending',
  };

  await db.surveys.put(deletedRecord);

  if (!navigator.onLine) {
    await db.syncQueue.add({
      entityId: id,
      action: 'delete',
      payload: deletedRecord,
      createdAt: deletedRecord.updatedAt,
    });
    return;
  }

  try {
    await deleteRemoteSurvey(id);
    await db.surveys.delete(id);
  } catch {
    deletedRecord.syncStatus = 'failed';
    await db.surveys.put(deletedRecord);
    await db.syncQueue.add({
      entityId: id,
      action: 'delete',
      payload: deletedRecord,
      createdAt: deletedRecord.updatedAt,
    });
  }
}

export async function syncPendingChanges() {
  if (!navigator.onLine) return;

  const queue = await db.syncQueue.orderBy('createdAt').toArray();

  for (const item of queue) {
    try {
      if (item.action === 'create' || item.action === 'update') {
        const saved = await pushSurvey(item.payload);
        await db.surveys.put({ ...saved, syncStatus: 'synced' });
      } else if (item.action === 'delete') {
        await deleteRemoteSurvey(item.entityId);
        await db.surveys.delete(item.entityId);
      }

      if (item.id) {
        await db.syncQueue.delete(item.id);
      }
    } catch (err) {
      console.error('Sync failed for item:', item, err);
      const local = await db.surveys.get(item.entityId);
      if (local) {
        await db.surveys.put({ ...local, syncStatus: 'failed' });
      }
    }
  }

  await pullRemoteUpdates();
}

export async function pullRemoteUpdates() {
  if (!navigator.onLine) return;

  const remote = await fetchRemoteSurveys();
  const local = await db.surveys.toArray();

  const localMap = new Map(local.map((r) => [r.id, r]));

  for (const remoteRecord of remote) {
    const localRecord = localMap.get(remoteRecord.id);

    if (!localRecord) {
      await db.surveys.put({ ...remoteRecord, syncStatus: 'synced' });
      continue;
    }

    if (new Date(remoteRecord.updatedAt) > new Date(localRecord.updatedAt)) {
      await db.surveys.put({ ...remoteRecord, syncStatus: 'synced' });
    }
  }
}
```

