## 3) Local storage + sync queue

### `lib/services/local_store.dart`

```dart
import 'package:hive/hive.dart';
import '../models/survey.dart';

class LocalStore {
  static const surveysBoxName = 'surveys_box';
  static const queueBoxName = 'sync_queue_box';

  late Box surveysBox;
  late Box queueBox;

  Future<void> init() async {
    surveysBox = await Hive.openBox(surveysBoxName);
    queueBox = await Hive.openBox(queueBoxName);
  }

  List<Survey> getAllSurveys() {
    return surveysBox.values
        .map((e) => Survey.fromMap(Map<String, dynamic>.from(e)))
        .toList()
      ..sort((a, b) => b.updatedAt.compareTo(a.updatedAt));
  }

  Survey? getSurvey(String id) {
    final raw = surveysBox.get(id);
    if (raw == null) return null;
    return Survey.fromMap(Map<String, dynamic>.from(raw));
  }

  Future<void> saveSurvey(Survey survey) async {
    await surveysBox.put(survey.id, survey.toMap());
  }

  Future<void> deleteSurvey(String id) async {
    await surveysBox.delete(id);
  }

  Future<void> enqueueAction(Map<String, dynamic> action) async {
    final key = DateTime.now().microsecondsSinceEpoch.toString();
    await queueBox.put(key, action);
  }

  List<Map<String, dynamic>> getQueuedActions() {
    return queueBox.values
        .map((e) => Map<String, dynamic>.from(e))
        .toList()
      ..sort((a, b) => (a['timestamp'] as int).compareTo(b['timestamp'] as int));
  }

  Future<void> removeQueuedAction(String key) async {
    await queueBox.delete(key);
  }

  Future<void> clearQueue() async {
    await queueBox.clear();
  }
}
