## 4) API client for sync

### `lib/services/api_client.dart`

```dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import '../models/survey.dart';

class ApiClient {
  final String baseUrl;

  ApiClient({required this.baseUrl});

  Future<List<Survey>> fetchSurveys() async {
    final res = await http.get(Uri.parse('$baseUrl/surveys'));
    if (res.statusCode != 200) {
      throw Exception('Failed to fetch surveys');
    }

    final body = jsonDecode(res.body) as List<dynamic>;
    return body
        .map((e) => Survey.fromMap(Map<String, dynamic>.from(e)))
        .toList();
  }

  Future<void> upsertSurvey(Survey survey) async {
    final res = await http.put(
      Uri.parse('$baseUrl/surveys/${survey.id}'),
      headers: {'Content-Type': 'application/json'},
      body: survey.toJson(),
    );

    if (res.statusCode != 200 && res.statusCode != 201) {
      throw Exception('Failed to sync survey ${survey.id}');
    }
  }

  Future<void> deleteSurvey(String id) async {
    final res = await http.delete(Uri.parse('$baseUrl/surveys/$id'));
    if (res.statusCode != 200 && res.statusCode != 204) {
      throw Exception('Failed to delete survey $id');
    }
  }
}
