## 5) Sync service

### `lib/services/sync_service.dart`

```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import '../models/survey.dart';
import 'api_client.dart';
import 'local_store.dart';

class SyncService {
  final LocalStore localStore;
  final ApiClient apiClient;

  SyncService({
    required this.localStore,
    required this.apiClient,
  });

  Future<void> syncIfOnline() async {
    final connectivity = await Connectivity().checkConnectivity();
    if (connectivity == ConnectivityResult.none) return;

    await syncLocalQueue();
    await pullRemoteSurveys();
  }

  Future<void> syncLocalQueue() async {
    final queued = localStore.getQueuedActions();

    for (final action in queued) {
      final type = action['type'];
      final data = Map<String, dynamic>.from(action['data']);
      final key = action['key'] as String?;

      try {
        switch (type) {
          case 'upsert':
            final survey = Survey.fromMap(data);
            await apiClient.upsertSurvey(survey);
            await localStore.saveSurvey(survey.copyWith(synced: true));
            break;
          case 'delete':
            await apiClient.deleteSurvey(data['id']);
            await localStore.deleteSurvey(data['id']);
            break;
        }

        if (key != null) {
          await localStore.queueBox.delete(key);
        }
      } catch (_) {
        // Stop on first failure to avoid partial inconsistency.
        break;
      }
    }
  }

  Future<void> pullRemoteSurveys() async {
    final remoteSurveys = await apiClient.fetchSurveys();
    final localSurveys = localStore.getAllSurveys();
    final localMap = {for (final s in localSurveys) s.id: s};

    for (final remote in remoteSurveys) {
      final local = localMap[remote.id];

      if (local == null || remote.updatedAt.isAfter(local.updatedAt)) {
        await localStore.saveSurvey(remote.copyWith(synced: true));
      }
    }
  }
}
```

