import 'package:uuid/uuid.dart';
import '../models/survey.dart';
import 'local_store.dart';
import 'sync_service.dart';

class SurveyRepository {
  final LocalStore localStore;
  final SyncService syncService;
  final _uuid = const Uuid();

  SurveyRepository({
    required this.localStore,
    required this.syncService,
  });

  List<Survey> listSurveys() => localStore.getAllSurveys();

  Survey? getSurvey(String id) => localStore.getSurvey(id);

  Future<void> saveSurvey({
    String? id,
    required String title,
    required String notes,
    double? latitude,
    double? longitude,
  }) async {
    final survey = Survey(
      id: id ?? _uuid.v4(),
      title: title,
      notes: notes,
      latitude: latitude,
      longitude: longitude,
      updatedAt: DateTime.now().toUtc(),
      synced: false,
      version: (getSurvey(id ?? '')?.version ?? 0) + 1,
    );

    await localStore.saveSurvey(survey);

    await localStore.enqueueAction({
      'key': survey.id,
      'type': 'upsert',
      'timestamp': DateTime.now().millisecondsSinceEpoch,
      'data': survey.toMap(),
    });
  }

  Future<void> deleteSurvey(String id) async {
    await localStore.saveSurvey(
      (getSurvey(id) ?? Survey(
        id: id,
        title: '',
        notes: '',
        updatedAt: DateTime.now().toUtc(),
      )).copyWith(sync: false),
    );

    await localStore.enqueueAction({
      'key': id,
      'type': 'delete',
      'timestamp': DateTime.now().millisecondsSinceEpoch,
      'data': {'id': id},
    });

    await localStore.deleteSurvey(id);
  }

  Future<void> syncNow() => syncService.syncIfOnline();
}
