  }

  void _watchConnectivity() {
    _sub = Connectivity().onConnectivityChanged.listen((result) async {
      final wasOnline = online;
      online = result != ConnectivityResult.none;

      if (!wasOnline && online) {
        await widget.repository.syncNow();
        await _refresh();
      }

      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _sub?.cancel();
    super.dispose();
  }

  Future<void> _openForm([Survey? survey]) async {
    await Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => SurveyFormPage(repository: widget.repository, survey: survey),
      ),
    );
    await _refresh();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Field Surveys'),
        actions: [
          IconButton(
            icon: Icon(online ? Icons.cloud_done : Icons.cloud_off),
            onPressed: () async {
              await widget.repository.syncNow();
              await _refresh();
            },
          )
        ],
      ),
      body: ListView.builder(
        itemCount: surveys.length,
        itemBuilder: (context, i) {
          final s = surveys[i];
          return ListTile(
            title: Text(s.title),
            subtitle: Text(
              '${s.notes}\n${s.synced ? "Synced" : "Pending sync"}',
            ),
            isThreeLine: true,
            onTap: () => _openForm(s),
          );
        },
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () => _openForm(),
        child: const Icon(Icons.add),
      ),
    );
  }
}
