## 4) Sync service

This processes queued changes when the app is online.

```ts
// sync.ts
import { db } from "./db";
import { apiDeleteSurvey, apiUpsertSurvey } from "./api";

export async function enqueueSurveyUpsert(entityId: string) {
  await db.syncQueue.add({
    entityType: "survey",
    entityId,
    operation: "upsert",
    createdAt: Date.now(),
    attempts: 0,
  });
}

export async function enqueueSurveyDelete(entityId: string) {
  await db.syncQueue.add({
    entityType: "survey",
    entityId,
    operation: "delete",
    createdAt: Date.now(),
    attempts: 0,
  });
}

export async function syncPendingChanges() {
  if (!navigator.onLine) return;

  const items = await db.syncQueue.orderBy("createdAt").toArray();

  for (const item of items) {
    try {
      const record = await db.surveys.get(item.entityId);

      if (item.operation === "upsert" && record && !record.deleted) {
        const res = await apiUpsertSurvey(record);
        await db.surveys.update(record.id, {
          remoteId: res.remoteId,
          syncedAt: Date.now(),
          updatedAt: res.updatedAt,
        });
      }

      if (item.operation === "delete") {
        if (record?.remoteId) {
          await apiDeleteSurvey(record.remoteId);
        }
        await db.surveys.delete(item.entityId);
      }

      if (item.id != null) {
        await db.syncQueue.delete(item.id);
      }
    } catch (err) {
      // increment attempt count, keep queued
      if (item.id != null) {
        await db.syncQueue.update(item.id, {
          attempts: item.attempts + 1,
        });
      }
    }
  }
}
```

