### `src/db.ts` — IndexedDB storage

```ts
import { openDB, DBSchema } from 'idb';

export interface SurveyRecord {
  id: string;
  title: string;
  location: string;
  notes: string;
  createdAt: string;
  updatedAt: string;
  version: number;
  deleted?: boolean;
}

export interface PendingMutation {
  id: string;
  type: 'create' | 'update' | 'delete';
  entity: 'survey';
  entityId: string;
  payload: Partial<SurveyRecord>;
  timestamp: string;
  retries: number;
}

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: SurveyRecord;
    indexes: { 'by-updatedAt': string };
  };
  mutations: {
    key: string;
    value: PendingMutation;
    indexes: { 'by-timestamp': string };
  };
}

const dbPromise = openDB<SurveyDB>('field-survey-db', 1, {
  upgrade(db) {
    const surveyStore = db.createObjectStore('surveys', { keyPath: 'id' });
    surveyStore.createIndex('by-updatedAt', 'updatedAt');

    const mutationStore = db.createObjectStore('mutations', { keyPath: 'id' });
    mutationStore.createIndex('by-timestamp', 'timestamp');
  },
});

export async function getDB() {
  return dbPromise;
}

export async function getAllSurveys(): Promise<SurveyRecord[]> {
  const db = await getDB();
  return db.getAll('surveys');
}

export async function getSurvey(id: string): Promise<SurveyRecord | undefined> {
  const db = await getDB();
  return db.get('surveys', id);
}

export async function saveSurveyLocal(survey: SurveyRecord) {
  const db = await getDB();
  await db.put('surveys', survey);
}

export async function deleteSurveyLocal(id: string) {
  const db = await getDB();
  await db.delete('surveys', id);
}

export async function addMutation(mutation: PendingMutation) {
  const db = await getDB();
  await db.put('mutations', mutation);
}

export async function getAllMutations(): Promise<PendingMutation[]> {
  const db = await getDB();
  const mutations = await db.getAll('mutations');
  return mutations.sort((a, b) => a.timestamp.localeCompare(b.timestamp));
}

export async function removeMutation(id: string) {
  const db = await getDB();
  await db.delete('mutations', id);
}
```

