### `src/sync.ts` — offline queue sync logic

```ts
import {
  getAllMutations,
  removeMutation,
  saveSurveyLocal,
  getAllSurveys,
  PendingMutation,
  SurveyRecord,
} from './db';
import { syncMutations } from './api';

function applyLocalMutation(survey: SurveyRecord, mutation: PendingMutation): SurveyRecord {
  switch (mutation.type) {
    case 'create':
      return { ...survey, ...mutation.payload } as SurveyRecord;
    case 'update':
      return { ...survey, ...mutation.payload, version: survey.version + 1, updatedAt: new Date().toISOString() };
    case 'delete':
      return { ...survey, deleted: true, version: survey.version + 1, updatedAt: new Date().toISOString() };
    default:
      return survey;
  }
}

export async function syncPendingChanges() {
  if (!navigator.onLine) return;

  const mutations = await getAllMutations();
  if (mutations.length === 0) return;

  try {
    const result = await syncMutations(mutations);

    // Server accepted some/all mutations
    for (const acceptedId of result.acceptedMutationIds as string[]) {
      await removeMutation(acceptedId);
    }

    // Optional: refresh local store with server truth
    if (result.surveys) {
      for (const survey of result.surveys as SurveyRecord[]) {
        await saveSurveyLocal(survey);
      }
    }
  } catch (err) {
    console.error('Sync failed', err);
  }
}

export async function hydrateLocalFromServer() {
  if (!navigator.onLine) return;
  const serverSurveys = await fetch('/api/surveys').then(r => r.json());
  for (const survey of serverSurveys) {
    await saveSurveyLocal(survey);
  }
}
```

