### `src/surveyService.ts` — CRUD with offline queue

```ts
import { v4 as uuidv4 } from 'uuid';
import {
  SurveyRecord,
  PendingMutation,
  getAllSurveys,
  getSurvey,
  saveSurveyLocal,
  deleteSurveyLocal,
  addMutation,
} from './db';

export async function listSurveys() {
  return getAllSurveys();
}

export async function createSurvey(input: Omit<SurveyRecord, 'id' | 'createdAt' | 'updatedAt' | 'version'>) {
  const now = new Date().toISOString();
  const survey: SurveyRecord = {
    id: uuidv4(),
    title: input.title,
    location: input.location,
    notes: input.notes,
    createdAt: now,
    updatedAt: now,
    version: 1,
  };

  await saveSurveyLocal(survey);

  const mutation: PendingMutation = {
    id: uuidv4(),
    type: 'create',
    entity: 'survey',
    entityId: survey.id,
    payload: survey,
    timestamp: now,
    retries: 0,
  };

  await addMutation(mutation);
  return survey;
}

export async function updateSurvey(id: string, patch: Partial<SurveyRecord>) {
  const existing = await getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  const updated: SurveyRecord = {
    ...existing,
    ...patch,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  await saveSurveyLocal(updated);

  const mutation: PendingMutation = {
    id: uuidv4(),
    type: 'update',
    entity: 'survey',
    entityId: id,
    payload: patch,
    timestamp: updated.updatedAt,
    retries: 0,
  };

  await addMutation(mutation);
  return updated;
}

export async function removeSurvey(id: string) {
  const existing = await getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  await deleteSurveyLocal(id);

  const mutation: PendingMutation = {
    id: uuidv4(),
    type: 'delete',
    entity: 'survey',
    entityId: id,
    payload: {},
    timestamp: new Date().toISOString(),
    retries: 0,
  };

  await addMutation(mutation);
}
