    await createSurvey({ title, location, notes });
    setTitle('');
    setLocation('');
    setNotes('');
    refresh();
  }

  async function handleToggleDelete(id: string) {
    await removeSurvey(id);
    refresh();
  }

  async function handleQuickEdit(id: string) {
    await updateSurvey(id, { notes: `Updated at ${new Date().toLocaleString()}` });
    refresh();
  }

  return (
    <div style={{ padding: 20, fontFamily: 'sans-serif' }}>
      <h1>Field Survey App</h1>
      <p>Status: {online ? 'Online' : 'Offline'} {syncing ? '(syncing...)' : ''}</p>

      <div style={{ display: 'grid', gap: 8, maxWidth: 400 }}>
        <input placeholder="Title" value={title} onChange={e => setTitle(e.target.value)} />
        <input placeholder="Location" value={location} onChange={e => setLocation(e.target.value)} />
        <textarea placeholder="Notes" value={notes} onChange={e => setNotes(e.target.value)} />
        <button onClick={handleCreate}>Save Survey</button>
      </div>

      <hr />

      <h2>Saved Surveys</h2>
      {surveys.map(s => (
        <div key={s.id} style={{ border: '1px solid #ccc', padding: 10, marginBottom: 10 }}>
          <strong>{s.title}</strong>
          <div>{s.location}</div>
          <div>{s.notes}</div>
          <div>Version: {s.version}</div>
          <button onClick={() => handleQuickEdit(s.id)}>Edit Notes</button>
          <button onClick={() => handleToggleDelete(s.id)}>Delete</button>
        </div>
      ))}
    </div>
  );
}
