## 3) Backend code

This backend accepts queued mutations and applies them.

### Install deps

```bash
npm install express cors sqlite3 sqlite body-parser
```

---

### `server.js`

```js
const express = require('express');
const cors = require('cors');
const sqlite3 = require('sqlite3').verbose();
const { open } = require('sqlite');

async function main() {
  const db = await open({
    filename: './surveys.db',
    driver: sqlite3.Database,
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      location TEXT NOT NULL,
      notes TEXT NOT NULL,
      createdAt TEXT NOT NULL,
      updatedAt TEXT NOT NULL,
      version INTEGER NOT NULL,
      deleted INTEGER DEFAULT 0
    );
  `);

  const app = express();
  app.use(cors());
  app.use(express.json());

  app.get('/api/surveys', async (req, res) => {
    const rows = await db.all('SELECT * FROM surveys WHERE deleted = 0');
    res.json(rows);
  });

  app.post('/api/sync', async (req, res) => {
    const { mutations } = req.body;

    const acceptedMutationIds = [];
    const surveysToReturn = [];

    for (const m of mutations) {
      if (m.entity !== 'survey') continue;

      if (m.type === 'create') {
        const existing = await db.get('SELECT * FROM surveys WHERE id = ?', m.entityId);
        if (!existing) {
          const s = m.payload;
          await db.run(
            `INSERT INTO surveys (id, title, location, notes, createdAt, updatedAt, version, deleted)
             VALUES (?, ?, ?, ?, ?, ?, ?, 0)`,
            s.id, s.title, s.location, s.notes, s.createdAt, s.updatedAt, s.version
          );
          acceptedMutationIds.push(m.id);
        }
      }

      if (m.type === 'update') {
        const existing = await db.get('SELECT * FROM surveys WHERE id = ?', m.entityId);
        if (existing) {
          const updatedVersion = existing.version + 1;
          const next = { ...existing, ...m.payload, version: updatedVersion, updatedAt: new Date().toISOString() };

          await db.run(
            `UPDATE surveys
             SET title = ?, location = ?, notes = ?, updatedAt = ?, version = ?
             WHERE id = ?`,
            next.title, next.location, next.notes, next.updatedAt, next.version, next.id
          );

          acceptedMutationIds.push(m.id);
          surveysToReturn.push(next);
        }
      }

      if (m.type === 'delete') {
        const existing = await db.get('SELECT * FROM surveys WHERE id = ?', m.entityId);
        if (existing) {
          await db.run(`UPDATE surveys SET deleted = 1, updatedAt = ?, version = ? WHERE id = ?`, new Date().toISOString(), existing.version + 1, m.entityId);
          acceptedMutationIds.push(m.id);
        }
      }
    }

    const allSurveys = await db.all('SELECT * FROM surveys WHERE deleted = 0');
    res.json({ acceptedMutationIds, surveys: allSurveys });
  });

  app.listen(3001, () => {
    console.log('Server running on http://localhost:3001');
  });
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
```

