import { getDb } from './db';
import { Survey } from '../types';

export function saveSurvey(survey: Survey) {
  const db = getDb();
  db.runSync(
    `INSERT OR REPLACE INTO surveys
      (id, title, location, notes, latitude, longitude, createdAt, updatedAt, syncStatus, serverId)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.location,
      survey.notes ?? null,
      survey.latitude ?? null,
      survey.longitude ?? null,
      survey.createdAt,
      survey.updatedAt,
      survey.syncStatus,
      survey.serverId ?? null,
    ]
  );
}

export function getAllSurveys(): Survey[] {
  const db = getDb();
  const rows = db.getAllSync<any>(`SELECT * FROM surveys ORDER BY updatedAt DESC`);
  return rows.map((r) => ({
    id: r.id,
    title: r.title,
    location: r.location,
    notes: r.notes ?? undefined,
    latitude: r.latitude ?? undefined,
    longitude: r.longitude ?? undefined,
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
    syncStatus: r.syncStatus,
    serverId: r.serverId ?? null,
  }));
}

export function getPendingSurveys(): Survey[] {
  const db = getDb();
  const rows = db.getAllSync<any>(
    `SELECT * FROM surveys WHERE syncStatus != 'synced' ORDER BY updatedAt ASC`
  );
  return rows.map((r) => ({
    id: r.id,
    title: r.title,
    location: r.location,
    notes: r.notes ?? undefined,
    latitude: r.latitude ?? undefined,
    longitude: r.longitude ?? undefined,
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
    syncStatus: r.syncStatus,
    serverId: r.serverId ?? null,
  }));
}

export function markSurveySynced(id: string, serverId: string) {
  const db = getDb();
  db.runSync(
    `UPDATE surveys SET syncStatus = 'synced', serverId = ? WHERE id = ?`,
    [serverId, id]
  );
}

export function markSurveyFailed(id: string) {
  const db = getDb();
  db.runSync(
    `UPDATE surveys SET syncStatus = 'failed' WHERE id = ?`,
    [id]
  );
}
