# 8) Sync service

## `src/services/syncService.ts`
```ts
import { getPendingSurveys, markSurveyFailed, markSurveySynced } from '../db/surveyRepo';
import { createSurveyOnServer } from './api';

export async function syncPendingSurveys() {
  const pending = getPendingSurveys();

  for (const survey of pending) {
    try {
      const payload = {
        localId: survey.id,
        title: survey.title,
        location: survey.location,
        notes: survey.notes,
        latitude: survey.latitude,
        longitude: survey.longitude,
        createdAt: survey.createdAt,
        updatedAt: survey.updatedAt,
      };

      const result = await createSurveyOnServer(payload);

      markSurveySynced(survey.id, result.id ?? result.serverId ?? survey.id);
    } catch (error) {
      console.warn('Sync failed for survey', survey.id, error);
      markSurveyFailed(survey.id);
    }
  }
}
