// src/api.ts
import { Survey } from './types';

const API_URL = 'https://your-api.example.com';

export async function pushSurveyChanges(changes: any[]) {
  const res = await fetch(`${API_URL}/sync`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ changes }),
  });

  if (!res.ok) {
    throw new Error('Failed to sync changes');
  }

  return res.json();
}

export async function fetchRemoteSurveys(since?: number): Promise<Survey[]> {
  const url = since
    ? `${API_URL}/surveys?since=${since}`
    : `${API_URL}/surveys`;

  const res = await fetch(url);
  if (!res.ok) throw new Error('Failed to fetch surveys');
  return res.json();
}
