## 4) Sync engine

The sync engine:
- pushes queued changes from outbox
- pulls remote surveys
- updates local cache
- clears outbox on success

```ts
// src/sync.ts
import { db } from './db';
import { pushSurveyChanges, fetchRemoteSurveys } from './api';
import { Survey } from './types';

let syncing = false;

export async function syncNow() {
  if (syncing) return;
  syncing = true;

  try {
    // 1. Push local pending changes
    const pending = await db.outbox.orderBy('createdAt').toArray();
    if (pending.length > 0) {
      await pushSurveyChanges(pending);
      await db.outbox.clear();

      // Mark all surveys in outbox as synced
      for (const item of pending) {
        const survey = await db.surveys.get(item.entityId);
        if (survey) {
          await db.surveys.update(survey.id, { syncStatus: 'synced' });
        }
      }
    }

    // 2. Pull remote changes
    const lastSync = localStorage.getItem('lastSyncAt');
    const since = lastSync ? Number(lastSync) : undefined;
    const remoteSurveys = await fetchRemoteSurveys(since);

    for (const remote of remoteSurveys) {
      const local = await db.surveys.get(remote.id);

      // Simple resolution: latest updatedAt wins
      if (!local || remote.updatedAt > local.updatedAt) {
        await db.surveys.put({
          ...remote,
          syncStatus: 'synced',
        });
      }
    }

    localStorage.setItem('lastSyncAt', String(Date.now()));
  } finally {
    syncing = false;
  }
}

export function startAutoSync() {
  window.addEventListener('online', () => {
    syncNow().catch(console.error);
  });

  // periodic retry while app is open
  setInterval(() => {
    if (navigator.onLine) {
      syncNow().catch(console.error);
    }
  }, 30_000);
}
```

