    const survey: Survey = {
      id: uuidv4(),
      title,
      notes,
      latitude,
      longitude,
      updatedAt: Date.now(),
      syncStatus: 'pending',
    };

    await db.surveys.put(survey);
    await db.outbox.add({
      entityType: 'survey',
      entityId: survey.id,
      operation: 'create',
      payload: survey,
      createdAt: Date.now(),
    });

    // attempt immediate sync if online
    if (navigator.onLine) {
      await syncNow().catch(console.error);
    }

    setTitle('');
    setNotes('');
    setLatitude(0);
    setLongitude(0);
  };

  return (
    <div>
