## 8) Simple backend sync endpoint

Here’s a very basic Node.js + Express backend.

```ts
// server/index.ts
import express from 'express';

const app = express();
app.use(express.json());

type Survey = {
  id: string;
  serverId?: string;
  title: string;
  notes: string;
  latitude: number;
  longitude: number;
  updatedAt: number;
  deleted?: boolean;
};

const surveys = new Map<string, Survey>();

app.post('/sync', (req, res) => {
  const { changes } = req.body;

  for (const change of changes) {
    const payload: Survey = change.payload;

    if (change.operation === 'delete') {
      surveys.delete(payload.id);
      continue;
    }

    const existing = surveys.get(payload.id);
    if (!existing || payload.updatedAt >= existing.updatedAt) {
      surveys.set(payload.id, payload);
    }
  }

  res.json({
    ok: true,
    serverTime: Date.now(),
  });
});

app.get('/surveys', (req, res) => {
  const since = Number(req.query.since || 0);
  const result = [...surveys.values()].filter((s) => s.updatedAt > since);
  res.json(result);
});

app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

