## 2) IndexedDB helper (`src/lib/db.ts`)

```ts
// src/lib/db.ts
const DB_NAME = "field-survey-db";
const DB_VERSION = 1;

export type SurveyRecord = {
  id: string;
  title: string;
  notes: string;
  latitude?: number;
  longitude?: number;
  createdAt: string;
  updatedAt: string;
  synced: boolean;
};

type SyncQueueItem = {
  id: string;
  type: "CREATE" | "UPDATE" | "DELETE";
  payload: any;
  createdAt: string;
};

let dbPromise: Promise<IDBDatabase> | null = null;

function openDB(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;

  dbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains("surveys")) {
        db.createObjectStore("surveys", { keyPath: "id" });
      }

      if (!db.objectStoreNames.contains("syncQueue")) {
        db.createObjectStore("syncQueue", { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });

  return dbPromise;
}

async function tx<T>(
  storeName: string,
  mode: IDBTransactionMode,
  fn: (store: IDBObjectStore) => IDBRequest<T>
): Promise<T> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(storeName, mode);
    const store = transaction.objectStore(storeName);
    const req = fn(store);

    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);

    transaction.onabort = () => reject(transaction.error);
  });
}

export async function getAllSurveys(): Promise<SurveyRecord[]> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("surveys", "readonly");
    const store = tx.objectStore("surveys");
    const req = store.getAll();

    req.onsuccess = () => resolve(req.result as SurveyRecord[]);
    req.onerror = () => reject(req.error);
  });
}

export async function getSurvey(id: string): Promise<SurveyRecord | undefined> {
  return tx("surveys", "readonly", (store) => store.get(id));
}

export async function saveSurvey(survey: SurveyRecord): Promise<void> {
  await tx("surveys", "readwrite", (store) => store.put(survey));
}

export async function deleteSurvey(id: string): Promise<void> {
  await tx("surveys", "readwrite", (store) => store.delete(id));
}

export async function enqueueSync(item: SyncQueueItem): Promise<void> {
  await tx("syncQueue", "readwrite", (store) => store.put(item));
}

export async function getSyncQueue(): Promise<SyncQueueItem[]> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("syncQueue", "readonly");
    const store = tx.objectStore("syncQueue");
    const req = store.getAll();

    req.onsuccess = () => resolve(req.result as SyncQueueItem[]);
    req.onerror = () => reject(req.error);
  });
}

export async function removeSyncQueueItem(id: string): Promise<void> {
  await tx("syncQueue", "readwrite", (store) => store.delete(id));
}

export async function clearSyncQueue(): Promise<void> {
  const items = await getSyncQueue();
  await Promise.all(items.map((item) => removeSyncQueueItem(item.id)));
}
```

