## 4) Sync logic (`src/lib/sync.ts`)

```ts
// src/lib/sync.ts
import { getSyncQueue, removeSyncQueueItem, saveSurvey } from "./db";
import { postSurvey } from "./api";

export async function syncPendingSurveys(): Promise<void> {
  if (!navigator.onLine) return;

  const queue = await getSyncQueue();

  for (const item of queue) {
    try {
      if (item.type === "CREATE" || item.type === "UPDATE") {
        const saved = await postSurvey(item.payload);
        await saveSurvey({ ...saved, synced: true });
      }

      // DELETE handling could be added here if needed
      await removeSyncQueueItem(item.id);
    } catch (err) {
      console.error("Sync failed for item:", item.id, err);
      // stop on first failure to retry later
      return;
    }
  }
}
```

