import Dexie, { Table } from "dexie";

export type Survey = {
  id: string;
  projectId: string;
  title: string;
  notes?: string;
  latitude?: number;
  longitude?: number;
  status: "draft" | "submitted" | "approved";
  createdAt: string;
  updatedAt: string;
  deletedAt?: string | null;
  revision: number;
  dirty: boolean;
};

export type OutboxItem = {
  id: string;
  entityType: "survey";
  entityId: string;
  action: "create" | "update" | "delete";
  payload: Partial<Survey> | null;
  createdAt: string;
  retries: number;
};

class SurveyDB extends Dexie {
  surveys!: Table<Survey, string>;
  outbox!: Table<OutboxItem, string>;

  constructor() {
    super("survey-db");
    this.version(1).stores({
      surveys: "id, projectId, updatedAt, dirty, deletedAt",
      outbox: "id, entityType, entityId, createdAt, retries",
    });
  }
}

export const db = new SurveyDB();
