## 5) Sync engine

This is the heart of the offline-first app.

### `sync.ts`

```ts
import { db, OutboxItem, Survey } from "./db";
import { api } from "./api";

let syncing = false;
let lastSyncAt: string | null = null;

function isOnline() {
  return navigator.onLine;
}

export async function queueCreateSurvey(survey: Survey) {
  await db.surveys.put(survey);
  await db.outbox.add({
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: survey.id,
    action: "create",
    payload: survey,
    createdAt: new Date().toISOString(),
    retries: 0,
  });
}

export async function queueUpdateSurvey(survey: Survey) {
  const updated = { ...survey, dirty: true, updatedAt: new Date().toISOString() };
  await db.surveys.put(updated);
  await db.outbox.add({
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: survey.id,
    action: "update",
    payload: updated,
    createdAt: new Date().toISOString(),
    retries: 0,
  });
}

export async function queueDeleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const deleted = {
    ...existing,
    deletedAt: new Date().toISOString(),
    dirty: true,
    updatedAt: new Date().toISOString(),
  };
  await db.surveys.put(deleted);

  await db.outbox.add({
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: id,
    action: "delete",
    payload: null,
    createdAt: new Date().toISOString(),
    retries: 0,
  });
}

async function processOutboxItem(item: OutboxItem) {
  if (item.entityType !== "survey") return;

  switch (item.action) {
    case "create":
    case "update": {
      const survey = item.payload as Survey;
      const result = await api.upsertSurvey(survey);
      await db.surveys.put({ ...result.survey, dirty: false });
      break;
    }
    case "delete": {
      const local = await db.surveys.get(item.entityId);
      const revision = local?.revision ?? 0;
      await api.deleteSurvey(item.entityId, revision);
      await db.surveys.delete(item.entityId);
      break;
    }
  }
}

export async function syncNow() {
  if (syncing || !isOnline()) return;
  syncing = true;

  try {
    const outboxItems = await db.outbox.orderBy("createdAt").toArray();

    // 1) Push local changes
    for (const item of outboxItems) {
      try {
        await processOutboxItem(item);
        await db.outbox.delete(item.id);
      } catch (err) {
        console.error("Sync push failed:", item, err);
        await db.outbox.update(item.id, { retries: item.retries + 1 });
      }
    }

    // 2) Pull latest changes
    const { surveys, serverTime } = await api.listSurveys(lastSyncAt ?? undefined);

    for (const remote of surveys) {
      const local = await db.surveys.get(remote.id);

      if (!local) {
        await db.surveys.put({ ...remote, dirty: false });
        continue;
      }

      // Simple conflict strategy:
      // if local is dirty, keep local and trigger conflict handling later
      if (local.dirty) continue;

      if (new Date(remote.updatedAt) > new Date(local.updatedAt)) {
        await db.surveys.put({ ...remote, dirty: false });
      }
    }

    lastSyncAt = serverTime;
  } finally {
    syncing = false;
  }
}

export function startSyncListeners() {
  window.addEventListener("online", () => syncNow());
  setInterval(() => {
    if (navigator.onLine) syncNow();
  }, 30_000);
}
```

