import { queueCreateSurvey, queueUpdateSurvey, queueDeleteSurvey, syncNow, startSyncListeners } from "./sync";

function newSurvey(): Survey {
  const now = new Date().toISOString();
  return {
    id: crypto.randomUUID(),
    projectId: "project-1",
    title: "",
    notes: "",
    status: "draft",
    createdAt: now,
    updatedAt: now,
    revision: 0,
    dirty: true,
  };
}

export default function App() {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [selected, setSelected] = useState<Survey | null>(null);
  const [online, setOnline] = useState(navigator.onLine);

  async function refresh() {
    const all = await db.surveys.orderBy("updatedAt").reverse().toArray();
    setSurveys(all.filter((s) => !s.deletedAt));
  }

  useEffect(() => {
    refresh();
    startSyncListeners();
    syncNow();

    const onOnline = () => setOnline(true);
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    const interval = setInterval(refresh, 2000);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
      clearInterval(interval);
    };
  }, []);

  async function createSurvey() {
    const s = newSurvey();
    await queueCreateSurvey(s);
    await refresh();
    setSelected(s);
  }

  async function saveSurvey(s: Survey) {
    await queueUpdateSurvey(s);
    await refresh();
    setSelected(s);
  }

  async function deleteSurvey(id: string) {
    await queueDeleteSurvey(id);
    await refresh();
    setSelected(null);
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <div style={{ width: 300, borderRight: "1px solid #ddd", padding: 16 }}>
        <h2>Surveying App</h2>
        <p>Status: {online ? "Online" : "Offline"}</p>
        <button onClick={createSurvey}>New Survey</button>
        <button onClick={syncNow} style={{ marginLeft: 8 }}>
          Sync Now
        </button>

        <ul>
          {surveys.map((s) => (
            <li key={s.id}>
              <button onClick={() => setSelected(s)}>{s.title || "(untitled)"}</button>
            </li>
          ))}
        </ul>
      </div>

      <div style={{ flex: 1, padding: 16 }}>
        {selected ? (
          <SurveyEditor
            survey={selected}
            onChange={setSelected}
            onSave={saveSurvey}
            onDelete={deleteSurvey}
          />
        ) : (
          <p>Select a survey</p>
        )}
      </div>
    </div>
  );
}

function SurveyEditor({
  survey,
  onChange,
  onSave,
  onDelete,
}: {
  survey: Survey;
  onChange: (s: Survey) => void;
  onSave: (s: Survey) => void;
  onDelete: (id: string) => void;
}) {
  return (
    <div>
      <h2>Edit Survey</h2>

      <label>
        Title
        <input
          value={survey.title}
          onChange={(e) => onChange({ ...survey, title: e.target.value, dirty: true, updatedAt: new Date().toISOString() })}
        />
      </label>

      <br />

      <label>
        Notes
        <textarea
          value={survey.notes || ""}
          onChange={(e) => onChange({ ...survey, notes: e.target.value, dirty: true, updatedAt: new Date().toISOString() })}
        />
      </label>

      <br />

      <label>
        Status
        <select
          value={survey.status}
          onChange={(e) => onChange({ ...survey, status: e.target.value as Survey["status"], dirty: true, updatedAt: new Date().toISOString() })}
        >
          <option value="draft">draft</option>
          <option value="submitted">submitted</option>
          <option value="approved">approved</option>
        </select>
      </label>

      <br />

      <button onClick={() => onSave(survey)}>Save</button>
      <button onClick={() => onDelete(survey.id)} style={{ marginLeft: 8 }}>
        Delete
      </button>

      {survey.dirty && <p style={{ color: "orange" }}>Pending sync</p>}
    </div>
  );
}
