```ts
// db.ts
import Dexie, { Table } from 'dexie';

export type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  collectedAt: string;
  updatedAt: string;
  deleted?: boolean;
  syncStatus: 'synced' | 'pending' | 'error';
};

export type PendingMutation = {
  id: string;
  recordId: string;
  operation: 'create' | 'update' | 'delete';
  payload: Partial<SurveyRecord>;
  createdAt: string;
  retryCount: number;
  lastError?: string;
};

class SurveyDB extends Dexie {
  surveys!: Table<SurveyRecord, string>;
  pendingMutations!: Table<PendingMutation, string>;

  constructor() {
    super('SurveyDB');
    this.version(1).stores({
      surveys: 'id, updatedAt, syncStatus, deleted',
      pendingMutations: 'id, recordId, operation, createdAt, retryCount',
    });
  }
}

export const db = new SurveyDB();
