```ts
// api.ts
import type { SurveyRecord } from './db';

const BASE_URL = '/api';

export async function fetchSurveys(): Promise<SurveyRecord[]> {
  const res = await fetch(`${BASE_URL}/surveys`);
  if (!res.ok) throw new Error('Failed to fetch surveys');
  return res.json();
}

export async function pushSurveyMutation(
  operation: 'create' | 'update' | 'delete',
  record: SurveyRecord
): Promise<SurveyRecord> {
  const res = await fetch(`${BASE_URL}/surveys/${record.id}`, {
    method:
      operation === 'create' ? 'POST' : operation === 'update' ? 'PUT' : 'DELETE',
    headers: { 'Content-Type': 'application/json' },
    body: operation === 'delete' ? undefined : JSON.stringify(record),
  });

  if (!res.ok) {
    throw new Error(`Sync failed for ${record.id}`);
  }

  return operation === 'delete' ? record : res.json();
}
```

