# 5) Offline-first service layer

This layer makes all local changes immediately, then queues them for sync.

```ts
// surveyService.ts
import { db, SurveyRecord, PendingMutation } from './db';
import { pushSurveyMutation, fetchSurveys } from './api';

const now = () => new Date().toISOString();

export async function loadInitialData() {
  // Optional: pull server data if online
  if (navigator.onLine) {
    try {
      const remoteSurveys = await fetchSurveys();
      await db.transaction('rw', db.surveys, async () => {
        for (const survey of remoteSurveys) {
          await db.surveys.put({ ...survey, syncStatus: 'synced' });
        }
      });
    } catch {
      // No-op: keep local data
    }
  }

  return db.surveys.toArray();
}

export async function createSurvey(input: Omit<SurveyRecord, 'id' | 'updatedAt' | 'syncStatus'>) {
  const record: SurveyRecord = {
    ...input,
    id: crypto.randomUUID(),
    updatedAt: now(),
    syncStatus: navigator.onLine ? 'pending' : 'pending',
  };

  await db.transaction('rw', db.surveys, db.pendingMutations, async () => {
    await db.surveys.put(record);
    await db.pendingMutations.add({
      id: crypto.randomUUID(),
      recordId: record.id,
      operation: 'create',
      payload: record,
      createdAt: now(),
      retryCount: 0,
    });
  });

  return record;
}

export async function updateSurvey(id: string, updates: Partial<SurveyRecord>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Record not found');

  const updated: SurveyRecord = {
    ...existing,
    ...updates,
    updatedAt: now(),
    syncStatus: 'pending',
  };

  await db.transaction('rw', db.surveys, db.pendingMutations, async () => {
    await db.surveys.put(updated);
    await db.pendingMutations.add({
      id: crypto.randomUUID(),
      recordId: id,
      operation: 'update',
      payload: updates,
      createdAt: now(),
      retryCount: 0,
    });
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  await db.transaction('rw', db.surveys, db.pendingMutations, async () => {
    await db.surveys.put({
      ...existing,
      deleted: true,
      syncStatus: 'pending',
      updatedAt: now(),
    });

    await db.pendingMutations.add({
      id: crypto.randomUUID(),
      recordId: id,
      operation: 'delete',
      payload: {},
      createdAt: now(),
      retryCount: 0,
    });
  });
}
```

