# 6) Sync engine

This processes queued mutations when online.

```ts
// syncEngine.ts
import { db } from './db';
import { pushSurveyMutation } from './api';

export async function syncPendingMutations() {
  if (!navigator.onLine) return;

  const pending = await db.pendingMutations.orderBy('createdAt').toArray();

  for (const mutation of pending) {
    try {
      const record = await db.surveys.get(mutation.recordId);
      if (!record) {
        await db.pendingMutations.delete(mutation.id);
        continue;
      }

      if (mutation.operation === 'delete') {
        await pushSurveyMutation('delete', record);
        await db.surveys.delete(record.id);
      } else {
        const synced = await pushSurveyMutation(mutation.operation, record);
        await db.surveys.put({ ...synced, syncStatus: 'synced' });
      }

      await db.pendingMutations.delete(mutation.id);
    } catch (err: any) {
      await db.pendingMutations.update(mutation.id, {
        retryCount: mutation.retryCount + 1,
        lastError: err?.message ?? 'Unknown sync error',
      });

      const record = await db.surveys.get(mutation.recordId);
      if (record) {
        await db.surveys.update(record.id, { syncStatus: 'error' });
      }
    }
  }
}
```

