## 4) Initial IndexedDB implementation

### `src/db.ts`
```ts
import { openDB, DBSchema } from 'idb';
import { SurveyRecord } from './types';

interface SurveyDB extends DBSchema {
  records: {
    key: string;
    value: SurveyRecord;
    indexes: { 'by-syncStatus': string; 'by-updatedAt': string };
  };
  outbox: {
    key: string;
    value: {
      id: string;
      recordId: string;
      action: 'create' | 'update' | 'delete';
      payload: any;
      createdAt: string;
      attempts: number;
    };
  };
}

const dbPromise = openDB<SurveyDB>('field-survey-db', 1, {
  upgrade(db) {
    const records = db.createObjectStore('records', { keyPath: 'id' });
    records.createIndex('by-syncStatus', 'syncStatus');
    records.createIndex('by-updatedAt', 'updatedAt');

    db.createObjectStore('outbox', { keyPath: 'id' });
  },
});

export const db = {
  async upsertRecord(record: SurveyRecord) {
    const db = await dbPromise;
    await db.put('records', record);
  },

  async getRecord(id: string) {
    const db = await dbPromise;
    return db.get('records', id);
  },

  async listRecords() {
    const db = await dbPromise;
    return db.getAll('records');
  },

  async listPendingRecords() {
    const db = await dbPromise;
    return db.getAllFromIndex('records', 'by-syncStatus', 'pending');
  },

  async addOutboxItem(item: {
    id: string;
    recordId: string;
    action: 'create' | 'update' | 'delete';
    payload: any;
    createdAt: string;
    attempts: number;
  }) {
    const db = await dbPromise;
    await db.put('outbox', item);
  },

  async listOutboxItems() {
    const db = await dbPromise;
    return db.getAll('outbox');
  },

  async removeOutboxItem(id: string) {
    const db = await dbPromise;
    await db.delete('outbox', id);
  },
};
```

