```ts
import { db } from './db';
import { createOrUpdateRecord } from './api';

export async function syncOutbox() {
  const items = await db.listOutboxItems();

  for (const item of items) {
    try {
      if (item.action === 'create' || item.action === 'update') {
        const syncedRecord = await createOrUpdateRecord(item.payload);
        await db.upsertRecord({
          ...syncedRecord,
          syncStatus: 'synced',
        });
      }

      if (item.action === 'delete') {
        // example delete endpoint
        await fetch(`https://your-api.example.com/records/${item.recordId}`, {
          method: 'DELETE',
        });
      }

      await db.removeOutboxItem(item.id);
    } catch (err) {
      console.error('Sync item failed', item.id, err);
      // Optionally increment attempts and mark failed after retries
    }
  }

  // Mark remaining pending items if needed
}
