import { v4 as uuidv4 } from 'uuid';
import { db } from './db';
import { SurveyRecord } from './types';

export async function createSurveyRecord(input: Omit<SurveyRecord, 'id' | 'createdAt' | 'updatedAt' | 'syncStatus' | 'version'>) {
  const now = new Date().toISOString();

  const record: SurveyRecord = {
    id: uuidv4(),
    ...input,
    createdAt: now,
    updatedAt: now,
    syncStatus: navigator.onLine ? 'synced' : 'pending',
    version: 1,
  };

  await db.upsertRecord(record);

  if (!navigator.onLine) {
    await db.addOutboxItem({
      id: uuidv4(),
      recordId: record.id,
      action: 'create',
      payload: record,
      createdAt: now,
      attempts: 0,
    });
  } else {
    // optionally send immediately
    // if sync succeeds, keep synced
  }

  return record;
}
```

