import { openDB } from "idb";

const DB_NAME = "field-survey-db";
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    if (!db.objectStoreNames.contains("surveys")) {
      db.createObjectStore("surveys", { keyPath: "id" });
    }
    if (!db.objectStoreNames.contains("outbox")) {
      db.createObjectStore("outbox", { keyPath: "id" });
    }
  },
});

export async function saveSurvey(survey: any) {
  const db = await dbPromise;
  await db.put("surveys", survey);
}

export async function getSurveys() {
  const db = await dbPromise;
  return db.getAll("surveys");
}

export async function getSurvey(id: string) {
  const db = await dbPromise;
  return db.get("surveys", id);
}

export async function saveOutboxOperation(op: any) {
  const db = await dbPromise;
  await db.put("outbox", op);
}

export async function getOutboxOperations() {
  const db = await dbPromise;
  return db.getAll("outbox");
}

export async function deleteOutboxOperation(id: string) {
  const db = await dbPromise;
