## Sync manager

**`src/sync/syncManager.ts`**
```ts
import { getOutboxOperations, deleteOutboxOperation, saveSurvey } from "../db";
import { syncSurvey } from "../api/client";

export async function flushOutbox() {
  const ops = await getOutboxOperations();

  for (const op of ops) {
    try {
      const result = await syncSurvey(op);

      if (result?.survey) {
        await saveSurvey({
          ...result.survey,
          syncStatus: "synced",
        });
      }

      await deleteOutboxOperation(op.id);
    } catch (error) {
      console.error("Failed to sync operation", op.id, error);
      // keep in outbox for retry
    }
  }
}
```

