## Express app

**`src/app.ts`**
```ts
import express from "express";
import cors from "cors";

const app = express();

app.use(cors());
app.use(express.json());

const surveys = new Map<string, any>();

app.post("/sync", (req, res) => {
  const op = req.body;

  if (op.type === "CREATE_SURVEY") {
    const survey = {
      ...op.payload,
      remoteId: `srv_${op.entityId}`,
      version: 1,
      syncStatus: "synced",
    };

    surveys.set(survey.remoteId, survey);
    return res.json({ survey });
  }

  if (op.type === "UPDATE_SURVEY") {
    const entityId = op.entityId;
    const existing = surveys.get(entityId);

    if (!existing) {
      return res.status(404).json({ error: "Survey not found" });
    }

    const updated = {
      ...existing,
      ...op.payload,
      version: existing.version + 1,
      syncStatus: "synced",
    };

    surveys.set(entityId, updated);
    return res.json({ survey: updated });
  }

  return res.status(400).json({ error: "Unsupported operation" });
});

app.get("/surveys", (_req, res) => {
  res.json(Array.from(surveys.values()));
});

export default app;
```

