# 4) Offline-first data access layer

All writes go to IndexedDB first, then queue the change for sync.

## `surveyService.ts`

```ts
import { db, SurveyRecord, SyncQueueItem } from "./db";

const generateId = () => crypto.randomUUID();

export async function saveSurveyOffline(
  survey: Omit<SurveyRecord, "id" | "syncState" | "version" | "localUpdatedAt">
): Promise<SurveyRecord> {
  const now = new Date().toISOString();
  const record: SurveyRecord = {
    ...survey,
    id: generateId(),
    syncState: "pending",
    version: 0,
    localUpdatedAt: now,
  };

  await db.transaction("rw", db.surveys, db.syncQueue, async () => {
    await db.surveys.put(record);

    const queueItem: SyncQueueItem = {
      id: generateId(),
      entityType: "survey",
      entityId: record.id,
      operation: "create",
      payload: record,
      createdAt: now,
      attempts: 0,
    };

    await db.syncQueue.put(queueItem);
  });

  return record;
}

export async function updateSurveyOffline(
  id: string,
  updates: Partial<SurveyRecord>
): Promise<void> {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found");

  const now = new Date().toISOString();
  const updated: SurveyRecord = {
    ...existing,
    ...updates,
    syncState: "pending",
    localUpdatedAt: now,
  };

  await db.transaction("rw", db.surveys, db.syncQueue, async () => {
    await db.surveys.put(updated);

    const queueItem: SyncQueueItem = {
      id: generateId(),
      entityType: "survey",
      entityId: id,
      operation: "update",
      payload: updates,
      createdAt: now,
      attempts: 0,
    };

    await db.syncQueue.put(queueItem);
  });
}

export async function deleteSurveyOffline(id: string): Promise<void> {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const now = new Date().toISOString();

  await db.transaction("rw", db.surveys, db.syncQueue, async () => {
    await db.surveys.delete(id);

    const queueItem: SyncQueueItem = {
      id: generateId(),
      entityType: "survey",
      entityId: id,
      operation: "delete",
      payload: null,
      createdAt: now,
      attempts: 0,
    };

    await db.syncQueue.put(queueItem);
  });
}
```

