# 5) Sync engine

This processes pending queue items whenever connectivity is restored.

## `syncService.ts`

```ts
import { db } from "./db";

const API_BASE = "https://api.example.com";

async function apiRequest(path: string, options: RequestInit) {
  const res = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
  });

  if (!res.ok) {
    throw new Error(`API error: ${res.status}`);
  }

  return res.json();
}

export async function syncPendingSurveys(): Promise<void> {
  const queueItems = await db.syncQueue.orderBy("createdAt").toArray();

  for (const item of queueItems) {
    try {
      if (item.entityType !== "survey") continue;

      if (item.operation === "create") {
        const created = await apiRequest("/surveys", {
          method: "POST",
          body: JSON.stringify(item.payload),
        });

        await db.surveys.update(item.entityId, {
          syncState: "synced",
          version: created.version ?? 1,
          serverUpdatedAt: created.updatedAt ?? new Date().toISOString(),
        });
      }

      if (item.operation === "update") {
        const local = await db.surveys.get(item.entityId);
        if (!local) continue;

        const updated = await apiRequest(`/surveys/${item.entityId}`, {
          method: "PUT",
          body: JSON.stringify({
            ...local,
            ...item.payload,
          }),
        });

        await db.surveys.update(item.entityId, {
          syncState: "synced",
          version: updated.version ?? local.version + 1,
          serverUpdatedAt: updated.updatedAt ?? new Date().toISOString(),
        });
      }

      if (item.operation === "delete") {
        await apiRequest(`/surveys/${item.entityId}`, {
          method: "DELETE",
        });
      }

      await db.syncQueue.delete(item.id);
    } catch (err: any) {
      const attempts = (item.attempts || 0) + 1;
      await db.syncQueue.update(item.id, {
        attempts,
        lastError: err.message,
      });

      if (attempts >= 3) {
        await db.surveys.update(item.entityId, {
          syncState: "failed",
        });
      }
    }
  }
}
```

