# 8) Backend API example

A minimal Express backend.

## `server.ts`

```ts
import express from "express";

const app = express();
app.use(express.json());

const surveys = new Map<string, any>();

app.post("/surveys", (req, res) => {
  const id = req.body.id || crypto.randomUUID();
  const record = {
    ...req.body,
    id,
    version: 1,
    updatedAt: new Date().toISOString(),
  };

  surveys.set(id, record);
  res.status(201).json(record);
});

app.put("/surveys/:id", (req, res) => {
  const id = req.params.id;
  const existing = surveys.get(id);

  if (!existing) {
    return res.status(404).json({ error: "Not found" });
  }

  const record = {
    ...existing,
    ...req.body,
    version: (existing.version || 1) + 1,
    updatedAt: new Date().toISOString(),
  };

  surveys.set(id, record);
  res.json(record);
});

app.delete("/surveys/:id", (req, res) => {
  surveys.delete(req.params.id);
  res.status(204).send();
});

app.get("/surveys", (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.listen(3000, () => {
  console.log("API running on http://localhost:3000");
});
