### `src/sync.ts`
```ts
import { db, OutboxAction, Survey } from './db';
import { pushActions, pullChanges } from './api';

const LAST_SYNC_KEY = 'lastSyncAt';

export async function syncNow() {
  if (!navigator.onLine) return;

  const lastSync = (await db.meta.get(LAST_SYNC_KEY))?.value ?? null;
  const outbox = await db.outbox.orderBy('createdAt').toArray();

  // Push local changes
  if (outbox.length > 0) {
    const response = await pushActions(outbox);

    // Apply server acknowledgements
    await Promise.all(
      response.ackedIds.map((id: string) => db.outbox.delete(id))
    );
  }

  // Pull remote changes
  const changes = await pullChanges(lastSync);

  for (const item of changes.surveys as Survey[]) {
    const local = await db.surveys.get(item.id);

    if (!local || item.version >= local.version) {
      await db.surveys.put({
        ...item,
        syncedAt: new Date().toISOString(),
      });
    }
  }

  await db.meta.put({
    key: LAST_SYNC_KEY,
    value: new Date().toISOString(),
  });
}
```

