### `src/surveyService.ts`
```ts
import { v4 as uuidv4 } from 'uuid';
import { db, Survey, OutboxAction } from './db';

function nowIso() {
  return new Date().toISOString();
}

export async function createSurvey(input: {
  projectId: string;
  title: string;
  latitude: number;
  longitude: number;
  notes?: string;
}) {
  const survey: Survey = {
    id: uuidv4(),
    ...input,
    createdAt: nowIso(),
    updatedAt: nowIso(),
    syncedAt: null,
    deleted: false,
    version: 1,
  };

  const action: OutboxAction = {
    id: uuidv4(),
    type: 'CREATE_SURVEY',
    payload: survey,
    createdAt: nowIso(),
    retries: 0,
  };

  await db.surveys.put(survey);
  await db.outbox.put(action);

  return survey;
}

export async function updateSurvey(id: string, patch: Partial<Survey>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const updated: Survey = {
    ...existing,
    ...patch,
    updatedAt: nowIso(),
    syncedAt: null,
    version: existing.version + 1,
  };

  const action: OutboxAction = {
    id: uuidv4(),
    type: 'UPDATE_SURVEY',
    payload: { id, patch: updated },
    createdAt: nowIso(),
    retries: 0,
  };

  await db.surveys.put(updated);
  await db.outbox.put(action);

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const deleted: Survey = {
    ...existing,
    deleted: true,
    updatedAt: nowIso(),
    syncedAt: null,
    version: existing.version + 1,
  };

  const action: OutboxAction = {
    id: uuidv4(),
    type: 'DELETE_SURVEY',
    payload: { id },
    createdAt: nowIso(),
    retries: 0,
  };

  await db.surveys.put(deleted);
  await db.outbox.put(action);
}
