import db from "./db";
import { randomUUID } from "expo-crypto";

export function enqueueOperation(
  entityType: "survey" | "answer" | "attachment",
  entityId: string,
  action: "create" | "update" | "delete" | "upload",
  payload: unknown
) {
  db.runSync(
    `INSERT INTO sync_queue (id, entityType, entityId, action, payload, createdAt, retryCount)
     VALUES (?, ?, ?, ?, ?, ?, 0)`,
    [
      randomUUID(),
      entityType,
      entityId,
      action,
      JSON.stringify(payload),
      new Date().toISOString()
    ]
  );
}

export function getQueuedOperations() {
  return db.getAllSync(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );
}

export function removeQueuedOperation(id: string) {
  db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}
```

