```ts
import db from "./db";
import { enqueueOperation } from "./syncQueue";
import { randomUUID } from "expo-crypto";

export type Survey = {
  id: string;
  siteId: string;
  inspectorId: string;
  status: "draft" | "submitted" | "synced";
  latitude?: number;
  longitude?: number;
  notes?: string;
  createdAt: string;
  updatedAt: string;
  version: number;
  deletedAt?: string | null;
};

export function createSurvey(input: Omit<Survey, "id" | "createdAt" | "updatedAt" | "version">) {
  const now = new Date().toISOString();
  const survey: Survey = {
    id: randomUUID(),
    ...input,
    createdAt: now,
    updatedAt: now,
    version: 1
  };

  db.runSync(
    `INSERT INTO surveys (id, siteId, inspectorId, status, latitude, longitude, notes, createdAt, updatedAt, version, deletedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.siteId,
      survey.inspectorId,
      survey.status,
      survey.latitude ?? null,
      survey.longitude ?? null,
      survey.notes ?? null,
      survey.createdAt,
      survey.updatedAt,
      survey.version,
      survey.deletedAt ?? null
    ]
  );

  enqueueOperation("survey", survey.id, "create", survey);
  return survey;
}

export function updateSurvey(id: string, patch: Partial<Survey>) {
  const current = db.getFirstSync<Survey>(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (!current) throw new Error("Survey not found");

  const updated: Survey = {
    ...current,
    ...patch,
    updatedAt: new Date().toISOString(),
    version: current.version + 1
  };

  db.runSync(
    `UPDATE surveys
     SET siteId = ?, inspectorId = ?, status = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, version = ?, deletedAt = ?
     WHERE id = ?`,
    [
      updated.siteId,
      updated.inspectorId,
      updated.status,
      updated.latitude ?? null,
      updated.longitude ?? null,
      updated.notes ?? null,
      updated.updatedAt,
      updated.version,
      updated.deletedAt ?? null,
      id
    ]
  );

  enqueueOperation("survey", id, "update", patch);
  return updated;
}

export function listSurveys() {
  return db.getAllSync(`SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`);
}
