## 8) Sync engine

## `syncService.ts`
```ts
import db from "./db";
import { getQueuedOperations, removeQueuedOperation } from "./syncQueue";

const API_BASE = "https://api.example.com";

function getSyncToken(): string | null {
  const row = db.getFirstSync<{ value: string }>(
    `SELECT value FROM sync_meta WHERE key = 'syncToken'`
  );
  return row?.value ?? null;
}

function setSyncToken(token: string) {
  db.runSync(
    `INSERT INTO sync_meta (key, value) VALUES ('syncToken', ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [token]
  );
}

export async function syncNow(authToken: string) {
  const queued = getQueuedOperations();

  // 1. Push local changes
  for (const op of queued) {
    const res = await fetch(`${API_BASE}/sync/push`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${authToken}`
      },
      body: JSON.stringify({
        entityType: op.entityType,
        entityId: op.entityId,
        action: op.action,
        payload: JSON.parse(op.payload),
        clientOpId: op.id
      })
    });

    if (!res.ok) {
      const errText = await res.text();
      db.runSync(
        `UPDATE sync_queue SET retryCount = retryCount + 1, lastError = ? WHERE id = ?`,
        [errText, op.id]
      );
      continue;
    }

    removeQueuedOperation(op.id);
  }

  // 2. Pull server changes
  const token = getSyncToken();
  const pullRes = await fetch(`${API_BASE}/sync/pull?since=${encodeURIComponent(token ?? "")}`, {
    headers: {
      "Authorization": `Bearer ${authToken}`
    }
  });

  if (!pullRes.ok) return;

  const data = await pullRes.json();
  // data: { changes: [...], nextSyncToken: string }

  for (const change of data.changes ?? []) {
    // Apply changes locally; start with survey entity support
    if (change.entityType === "survey") {
      db.runSync(
        `INSERT INTO surveys (id, siteId, inspectorId, status, latitude, longitude, notes, createdAt, updatedAt, version, deletedAt)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET
           siteId = excluded.siteId,
           inspectorId = excluded.inspectorId,
           status = excluded.status,
           latitude = excluded.latitude,
           longitude = excluded.longitude,
           notes = excluded.notes,
           createdAt = excluded.createdAt,
           updatedAt = excluded.updatedAt,
           version = excluded.version,
           deletedAt = excluded.deletedAt`,
        [
          change.data.id,
          change.data.siteId,
          change.data.inspectorId,
          change.data.status,
          change.data.latitude ?? null,
          change.data.longitude ?? null,
          change.data.notes ?? null,
          change.data.createdAt,
          change.data.updatedAt,
          change.data.version,
          change.data.deletedAt ?? null
        ]
      );
    }
  }

  if (data.nextSyncToken) setSyncToken(data.nextSyncToken);
}
```

