## `src/sync.ts`

```ts
import { db, OutboxItem, Survey } from "./db";
import { syncOutbox } from "./api";

export async function queueCreateSurvey(survey: Survey) {
  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(survey);
    await db.outbox.add({
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: survey.id,
      operation: "create",
      payload: survey,
      baseVersion: 0,
      createdAt: new Date().toISOString(),
      retries: 0,
    });
  });
}

export async function queueUpdateSurvey(survey: Survey) {
  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(survey);
    await db.outbox.add({
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: survey.id,
      operation: "update",
      payload: survey,
      baseVersion: survey.version,
      createdAt: new Date().toISOString(),
      retries: 0,
    });
  });
}

export async function queueDeleteSurvey(surveyId: string) {
  const survey = await db.surveys.get(surveyId);
  if (!survey) return;

  const updated: Survey = {
    ...survey,
    deletedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    version: survey.version,
  };

  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(updated);
    await db.outbox.add({
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: surveyId,
      operation: "delete",
      payload: { id: surveyId, deletedAt: updated.deletedAt },
      baseVersion: survey.version,
      createdAt: new Date().toISOString(),
      retries: 0,
    });
  });
}

export async function syncNow() {
  if (!navigator.onLine) return;

  const items = await db.outbox.orderBy("createdAt").toArray();
  if (items.length === 0) return;

  try {
    const result = await syncOutbox(items);

    await db.transaction("rw", db.surveys, db.outbox, async () => {
      for (const applied of result.applied) {
        await db.surveys.put(applied);
      }
      await db.outbox.clear();
    });
  } catch (err: any) {
    await db.outbox.toCollection().modify((item: OutboxItem) => {
      item.retries += 1;
      item.lastError = err.message || "Unknown sync error";
    });

    console.error("Sync failed:", err);
  }
}
```

