import React, { useEffect, useState } from "react";
import { db, Survey } from "./db";
import { queueCreateSurvey, queueUpdateSurvey, syncNow } from "./sync";
import { useConnectivity } from "./useConnectivity";
import { v4 as uuidv4 } from "uuid";

export default function App() {
  const online = useConnectivity();
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [name, setName] = useState("");
  const [notes, setNotes] = useState("");

  const loadSurveys = async () => {
    const items = await db.surveys.orderBy("updatedAt").reverse().toArray();
    setSurveys(items.filter(s => !s.deletedAt));
  };

  useEffect(() => {
    loadSurveys();
  }, []);

  const createSurvey = async () => {
    const now = new Date().toISOString();
    const survey: Survey = {
      id: uuidv4(),
      clientId: uuidv4(),
      name,
      location: { lat: 0, lng: 0 },
      notes,
      status: "draft",
      version: 0,
      createdAt: now,
      updatedAt: now,
      deletedAt: null,
    };

    await queueCreateSurvey(survey);
    setName("");
    setNotes("");
    await loadSurveys();
  };

  const markSubmitted = async (survey: Survey) => {
    const updated: Survey = {
      ...survey,
      status: "submitted",
      updatedAt: new Date().toISOString(),
      version: survey.version + 1,
    };

    await queueUpdateSurvey(updated);
    await loadSurveys();
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Field Survey App</h1>
      <p>Status: {online ? "Online" : "Offline"}</p>

      <button onClick={syncNow} disabled={!online}>
        Sync now
      </button>

      <div style={{ marginTop: 20 }}>
        <h2>Create Survey</h2>
        <input
          placeholder="Survey name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <br />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <br />
        <button onClick={createSurvey} disabled={!name.trim()}>
          Save offline
        </button>
      </div>

      <div style={{ marginTop: 20 }}>
        <h2>Surveys</h2>
        {surveys.map((s) => (
          <div key={s.id} style={{ border: "1px solid #ccc", marginBottom: 10, padding: 10 }}>
            <strong>{s.name}</strong>
            <p>{s.notes}</p>
            <p>Status: {s.status}</p>
            <p>Version: {s.version}</p>
            <button onClick={() => markSubmitted(s)} disabled={s.status === "submitted"}>
              Mark submitted
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
