```ts
import express from "express";
import cors from "cors";
import { v4 as uuidv4 } from "uuid";

const app = express();
app.use(cors());
app.use(express.json());

type Survey = {
  id: string;
  clientId: string;
  name: string;
  location: { lat: number; lng: number };
  notes: string;
  status: "draft" | "submitted";
  version: number;
  createdAt: string;
  updatedAt: string;
  deletedAt?: string | null;
};

const surveys = new Map<string, Survey>();

app.get("/api/surveys", (_req, res) => {
  res.json([...surveys.values()].filter(s => !s.deletedAt));
});

app.post("/api/sync", (req, res) => {
  const { items } = req.body as { items: any[] };

  const applied: Survey[] = [];

  for (const item of items) {
    const { operation, payload } = item;

    if (operation === "create") {
      const existing = surveys.get(payload.id);
      if (!existing) {
        const created: Survey = {
          ...payload,
          version: 1,
          updatedAt: new Date().toISOString(),
          createdAt: payload.createdAt || new Date().toISOString(),
        };
        surveys.set(created.id, created);
        applied.push(created);
      } else {
        applied.push(existing);
      }
    }

    if (operation === "update") {
      const existing = surveys.get(payload.id);
      if (!existing) continue;

      // Simple conflict strategy: last write wins
      const updated: Survey = {
        ...existing,
        ...payload,
        version: existing.version + 1,
        updatedAt: new Date().toISOString(),
      };

      surveys.set(updated.id, updated);
      applied.push(updated);
    }

    if (operation === "delete") {
      const existing = surveys.get(payload.id);
      if (!existing) continue;

      const deleted: Survey = {
        ...existing,
        deletedAt: new Date().toISOString(),
        version: existing.version + 1,
        updatedAt: new Date().toISOString(),
      };

      surveys.set(deleted.id, deleted);
      applied.push(deleted);
    }
  }

  res.json({ applied });
});

app.listen(3000, () => {
  console.log("API listening on http://localhost:3000");
});
```

