```ts
import db from './db';
import { v4 as uuidv4 } from 'uuid';

type Survey = {
  id: string;
  title: string;
  notes?: string;
  latitude?: number;
  longitude?: number;
  observed_at?: string;
};

export function createSurveyLocal(input: Survey) {
  const id = input.id || uuidv4();
  const now = new Date().toISOString();

  db.runSync(
    `INSERT INTO surveys (id, title, notes, latitude, longitude, observed_at, created_at, updated_at, sync_status, version, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending', 0, 0)`,
    [
      id,
      input.title,
      input.notes ?? null,
      input.latitude ?? null,
      input.longitude ?? null,
      input.observed_at ?? null,
      now,
      now,
    ]
  );

  db.runSync(
    `INSERT INTO sync_queue (id, entity_type, entity_id, operation, payload, status, retry_count, created_at)
     VALUES (?, 'survey', ?, 'create', ?, 'pending', 0, ?)`,
    [
      uuidv4(),
      id,
      JSON.stringify({ ...input, id, version: 0 }),
      now,
    ]
  );

  return id;
}

export function listSurveysLocal() {
  return db.getAllSync(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updated_at DESC`
  );
}
