## `syncService.ts`
```ts
import db from './db';

const API_URL = 'https://api.example.com';

async function getToken(): Promise<string | null> {
  const row = db.getFirstSync(`SELECT value FROM metadata WHERE key = 'auth_token'`);
  return row?.value ?? null;
}

export async function syncNow() {
  const token = await getToken();
  if (!token) return;

  const queue = db.getAllSync(
    `SELECT * FROM sync_queue WHERE status = 'pending' ORDER BY created_at ASC`
  );

  if (queue.length === 0) {
    await pullRemoteChanges(token);
    return;
  }

  const operations = queue.map((item: any) => ({
    opId: item.id,
    type: item.operation,
    entityType: item.entity_type,
    entityId: item.entity_id,
    payload: JSON.parse(item.payload),
  }));

  const pushRes = await fetch(`${API_URL}/sync/batch`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      operations,
      lastSyncAt: getLastSyncAt(),
    }),
  });

  const pushJson = await pushRes.json();

  for (const result of pushJson.results ?? []) {
    if (result.status === 'ok') {
      db.runSync(`UPDATE sync_queue SET status = 'sent' WHERE id = ?`, [result.opId]);
    } else {
      db.runSync(
        `UPDATE sync_queue SET status = 'failed', retry_count = retry_count + 1 WHERE id = ?`,
        [result.opId]
      );
    }
  }

  await pullRemoteChanges(token);
  setLastSyncAt(pushJson.serverTime || new Date().toISOString());
}

async function pullRemoteChanges(token: string) {
  const since = getLastSyncAt();
  const res = await fetch(`${API_URL}/surveys?updatedSince=${encodeURIComponent(since)}`, {
    headers: { Authorization: `Bearer ${token}` },
  });

  const json = await res.json();

  const items = json.items ?? [];
  for (const item of items) {
    const existing = db.getFirstSync(`SELECT id, version FROM surveys WHERE remote_id = ?`, [item.id]);

    if (!existing) {
      db.runSync(
        `INSERT INTO surveys (id, remote_id, title, notes, latitude, longitude, observed_at, created_at, updated_at, sync_status, version, deleted)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'synced', ?, ?)`,
        [
          item.id,
          item.id,
          item.title,
          item.notes ?? null,
          item.latitude ?? null,
          item.longitude ?? null,
          item.observed_at ?? null,
          item.created_at,
          item.updated_at,
          item.version ?? 1,
          item.deleted_at ? 1 : 0,
        ]
      );
    } else {
      db.runSync(
        `UPDATE surveys
         SET title = ?, notes = ?, latitude = ?, longitude = ?, observed_at = ?, updated_at = ?, sync_status = 'synced', version = ?, deleted = ?
         WHERE remote_id = ?`,
        [
          item.title,
          item.notes ?? null,
          item.latitude ?? null,
          item.longitude ?? null,
          item.observed_at ?? null,
          item.updated_at,
          item.version ?? 1,
          item.deleted_at ? 1 : 0,
          item.id,
        ]
      );
    }
  }
}

function getLastSyncAt() {
  const row = db.getFirstSync(`SELECT value FROM metadata WHERE key = 'last_sync_at'`);
  return row?.value ?? '1970-01-01T00:00:00Z';
}

function setLastSyncAt(value: string) {
  db.runSync(
    `INSERT INTO metadata (key, value) VALUES ('last_sync_at', ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [value]
  );
}
```

