const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret';

function auth(req: any, res: any, next: any) {
  const header = req.headers.authorization || '';
  const token = header.replace('Bearer ', '');
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: 'Unauthorized' });
  }
}

app.post('/auth/login', async (req, res) => {
  // Initial stub; replace with real verification
  const user = { id: 'user-1', email: req.body.email };
  const token = jwt.sign(user, JWT_SECRET, { expiresIn: '7d' });
  res.json({ token, user });
});

app.get('/surveys', auth, async (req: any, res) => {
  const updatedSince = req.query.updatedSince || '1970-01-01T00:00:00Z';
  const { rows } = await pool.query(
    `SELECT * FROM surveys
     WHERE user_id = $1 AND updated_at > $2
     ORDER BY updated_at ASC`,
    [req.user.id, updatedSince]
  );

  res.json({ items: rows });
});

app.post('/sync/batch', auth, async (req: any, res) => {
  const ops = req.body.operations || [];
  const results = [];

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    for (const op of ops) {
      if (op.entityType === 'survey') {
        if (op.type === 'create') {
          const id = crypto.randomUUID();
          const p = op.payload;

          const r = await client.query(
            `INSERT INTO surveys (id, user_id, title, notes, latitude, longitude, observed_at, version)
             VALUES ($1, $2, $3, $4, $5, $6, $7, 1)
             RETURNING version`,
            [id, req.user.id, p.title, p.notes, p.latitude, p.longitude, p.observed_at]
          );

          results.push({ opId: op.opId, status: 'ok', remoteId: id, version: r.rows[0].version });
        }
      }
    }

    await client.query('COMMIT');
    res.json({ results, serverTime: new Date().toISOString() });
  } catch (e) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Sync failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('API running on :3000'));
```

