import { openDB, DBSchema } from 'idb';

export interface Survey {
  id: string;
  title: string;
  notes?: string;
  latitude: number;
  longitude: number;
  surveyedAt: string;
  updatedAt: string;
  version: number;
  deleted?: boolean;
}

export interface PendingMutation {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: Partial<Survey>;
  createdAt: string;
  retries: number;
}

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
  };
  pendingMutations: {
    key: string;
    value: PendingMutation;
  };
  meta: {
    key: string;
    value: { key: string; value: string };
  };
}

const dbPromise = openDB<SurveyDB>('field-survey-db', 1, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      db.createObjectStore('surveys', { keyPath: 'id' });
    }
    if (!db.objectStoreNames.contains('pendingMutations')) {
      db.createObjectStore('pendingMutations', { keyPath: 'id' });
    }
    if (!db.objectStoreNames.contains('meta')) {
      db.createObjectStore('meta', { keyPath: 'key' });
    }
  },
});

export async function saveSurvey(survey: Survey) {
  const db = await dbPromise;
  await db.put('surveys', survey);
}

export async function getSurvey(id: string) {
  const db = await dbPromise;
  return db.get('surveys', id);
}

export async function getAllSurveys() {
  const db = await dbPromise;
  const all = await db.getAll('surveys');
  return all.filter(s => !s.deleted);
}

export async function savePendingMutation(mutation: PendingMutation) {
  const db = await dbPromise;
  await db.put('pendingMutations', mutation);
}

export async function getPendingMutations() {
  const db = await dbPromise;
  return db.getAll('pendingMutations');
}

export async function deletePendingMutation(id: string) {
  const db = await dbPromise;
  await db.delete('pendingMutations', id);
}

export async function setMeta(key: string, value: string) {
  const db = await dbPromise;
  await db.put('meta', { key, value });
}

export async function getMeta(key: string) {
  const db = await dbPromise;
  const res = await db.get('meta', key);
  return res?.value;
}
