## 3.3 Survey service

This service writes locally first and queues mutations.

### `src/services/surveyService.ts`

```ts
import { v4 as uuidv4 } from 'uuid';
import {
  Survey,
  PendingMutation,
  saveSurvey,
  getSurvey,
  getAllSurveys,
  savePendingMutation,
  getPendingMutations,
  deletePendingMutation,
  setMeta,
  getMeta,
} from '../storage/db';

const API_BASE = 'http://localhost:4000/api';

function now() {
  return new Date().toISOString();
}

export async function createSurvey(input: Omit<Survey, 'id' | 'updatedAt' | 'version'>) {
  const survey: Survey = {
    ...input,
    id: uuidv4(),
    updatedAt: now(),
    version: 1,
  };

  await saveSurvey(survey);

  const mutation: PendingMutation = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: survey.id,
    operation: 'create',
    payload: survey,
    createdAt: now(),
    retries: 0,
  };

  await savePendingMutation(mutation);
  return survey;
}

export async function updateSurvey(id: string, changes: Partial<Survey>) {
  const existing = await getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  const updated: Survey = {
    ...existing,
    ...changes,
    updatedAt: now(),
    version: existing.version + 1,
  };

  await saveSurvey(updated);

  const mutation: PendingMutation = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: updated,
    createdAt: now(),
    retries: 0,
  };

  await savePendingMutation(mutation);
  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  const deleted: Survey = {
    ...existing,
    deleted: true,
    updatedAt: now(),
    version: existing.version + 1,
  };

  await saveSurvey(deleted);

  const mutation: PendingMutation = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { id, deleted: true, updatedAt: deleted.updatedAt, version: deleted.version },
    createdAt: now(),
    retries: 0,
  };

  await savePendingMutation(mutation);
  return deleted;
}

export async function listSurveys() {
  return getAllSurveys();
}
