## 3.4 Sync engine

This sync engine:

- checks network status
- pushes pending mutations
- pulls server changes since last sync
- updates local store

### `src/services/syncService.ts`

```ts
import {
  getPendingMutations,
  deletePendingMutation,
  saveSurvey,
  setMeta,
  getMeta,
  Survey,
  PendingMutation,
} from '../storage/db';

const API_BASE = 'http://localhost:4000/api';

async function apiFetch(path: string, options?: RequestInit) {
  const res = await fetch(`${API_BASE}${path}`, {
    headers: {
      'Content-Type': 'application/json',
      ...(options?.headers || {}),
    },
    ...options,
  });

  if (!res.ok) throw new Error(`API error ${res.status}`);
  return res.json();
}

export async function syncNow() {
  if (!navigator.onLine) return { ok: false, reason: 'offline' };

  // 1. Push mutations
  const mutations = await getPendingMutations();
  for (const mutation of mutations) {
    try {
      await apiFetch('/sync/mutation', {
        method: 'POST',
        body: JSON.stringify(mutation),
      });
      await deletePendingMutation(mutation.id);
    } catch {
      // leave in queue; retry later
    }
  }

  // 2. Pull remote changes
  const lastSync = (await getMeta('lastSync')) || '1970-01-01T00:00:00.000Z';
  const result = await apiFetch(`/surveys/changes?since=${encodeURIComponent(lastSync)}`);

  const changedSurveys: Survey[] = result.items || [];
  for (const survey of changedSurveys) {
    await saveSurvey(survey);
  }

  await setMeta('lastSync', new Date().toISOString());
  return { ok: true };
}

export function startAutoSync() {
  const trySync = () => {
    if (navigator.onLine) {
      syncNow().catch(console.error);
    }
  };

  window.addEventListener('online', trySync);
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') trySync();
  });

  // initial attempt
  trySync();

  return () => {
    window.removeEventListener('online', trySync);
  };
}
```

