# 5. Backend implementation

This backend accepts mutations and returns changed records since a timestamp.

## 5.1 Server setup

### `server/index.js`

```js
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const surveys = new Map(); // replace with DB in production
const mutationLog = [];     // for change tracking

function now() {
  return new Date().toISOString();
}

app.post('/api/sync/mutation', (req, res) => {
  const mutation = req.body;

  if (!mutation || !mutation.entityId) {
    return res.status(400).json({ error: 'Invalid mutation' });
  }

  const existing = surveys.get(mutation.entityId);

  if (mutation.operation === 'create' || mutation.operation === 'update') {
    const incoming = mutation.payload;
    const currentVersion = existing?.version || 0;

    // last-write-wins if version is newer
    if (!existing || (incoming.version || 0) >= currentVersion) {
      surveys.set(mutation.entityId, {
        ...incoming,
        updatedAt: now(),
      });
    }
  } else if (mutation.operation === 'delete') {
    if (existing) {
      surveys.set(mutation.entityId, {
        ...existing,
        deleted: true,
        updatedAt: now(),
        version: (existing.version || 0) + 1,
      });
    }
  }

  mutationLog.push({ ...mutation, receivedAt: now() });
  res.json({ ok: true });
});

app.get('/api/surveys/changes', (req, res) => {
  const since = req.query.since || '1970-01-01T00:00:00.000Z';
  const items = [...surveys.values()].filter(s => s.updatedAt > since);
  res.json({ items });
});

app.post('/api/surveys', (req, res) => {
  const survey = req.body;
  const id = survey.id || uuidv4();

  const stored = {
    ...survey,
    id,
    updatedAt: survey.updatedAt || now(),
    version: survey.version || 1,
  };

  surveys.set(id, stored);
  res.json(stored);
});

app.listen(4000, () => {
  console.log('API listening on http://localhost:4000');
});
```

