# 9) Survey repository

```ts
// src/db/surveyRepo.ts
import { db } from './index';
import { SurveyRecord, SurveyPayload } from '../types/survey';

export function upsertSurvey(record: SurveyRecord) {
  db.runSync(
    `INSERT INTO surveys (
      local_id, remote_id, version, status, created_at, updated_at,
      payload, pending, last_synced_at, sync_error
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(local_id) DO UPDATE SET
      remote_id=excluded.remote_id,
      version=excluded.version,
      status=excluded.status,
      updated_at=excluded.updated_at,
      payload=excluded.payload,
      pending=excluded.pending,
      last_synced_at=excluded.last_synced_at,
      sync_error=excluded.sync_error`,
    [
      record.localId,
      record.remoteId ?? null,
      record.version,
      record.status,
      record.createdAt,
      record.updatedAt,
      JSON.stringify(record.payload),
      record.pending ? 1 : 0,
      record.lastSyncedAt ?? null,
      record.syncError ?? null,
    ]
  );
}

export function getAllSurveys(): SurveyRecord[] {
  const result = db.getAllSync<any>(`SELECT * FROM surveys ORDER BY updated_at DESC`);
  return result.map((row) => ({
    localId: row.local_id,
    remoteId: row.remote_id,
    version: row.version,
    status: row.status,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    payload: JSON.parse(row.payload),
    pending: row.pending === 1,
    lastSyncedAt: row.last_synced_at,
    syncError: row.sync_error,
  }));
}

export function getSurveyByLocalId(localId: string): SurveyRecord | null {
  const row = db.getFirstSync<any>(
    `SELECT * FROM surveys WHERE local_id = ?`,
    [localId]
  );
  if (!row) return null;
  return {
    localId: row.local_id,
    remoteId: row.remote_id,
    version: row.version,
    status: row.status,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    payload: JSON.parse(row.payload),
    pending: row.pending === 1,
    lastSyncedAt: row.last_synced_at,
    syncError: row.sync_error,
  };
}
