# 10) Queue repository

```ts
// src/db/queueRepo.ts
import { db } from './index';

export function enqueueOperation(args: {
  entityType: string;
  entityLocalId: string;
  operation: string;
  payload: any;
}) {
  db.runSync(
    `INSERT INTO sync_queue (
      entity_type, entity_local_id, operation, payload, created_at
    ) VALUES (?, ?, ?, ?, datetime('now'))`,
    [
      args.entityType,
      args.entityLocalId,
      args.operation,
      JSON.stringify(args.payload),
    ]
  );
}

export function getPendingQueueItems() {
  return db.getAllSync<any>(
    `SELECT * FROM sync_queue ORDER BY id ASC`
  );
}

export function removeQueueItem(id: number) {
  db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export function markQueueItemFailed(id: number, error: string) {
  db.runSync(
    `UPDATE sync_queue SET attempts = attempts + 1, last_error = ? WHERE id = ?`,
    [error, id]
  );
}
```

