# 12) Sync service

```ts
// src/api/sync.ts
import { apiFetch } from './client';
import { getPendingQueueItems, removeQueueItem, markQueueItemFailed } from '../db/queueRepo';
import { getAllSurveys, upsertSurvey } from '../db/surveyRepo';

export async function syncNow(token: string, lastSyncAt?: string) {
  // PUSH
  const queue = getPendingQueueItems();

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      if (item.operation === 'CREATE') {
        const result = await apiFetch(
          '/surveys',
          {
            method: 'POST',
            body: JSON.stringify(payload),
          },
          token
        );

        // Update local survey with remote ID/version
        // (for simplicity, we assume payload includes localId)
        const local = getAllSurveys().find(s => s.localId === item.entity_local_id);
        if (local) {
          upsertSurvey({
            ...local,
            remoteId: result.id,
            version: result.version,
            pending: false,
            lastSyncedAt: new Date().toISOString(),
            syncError: undefined,
          });
        }

        removeQueueItem(item.id);
      } else if (item.operation === 'UPDATE') {
        await apiFetch(
          `/surveys/${payload.remoteId}`,
          {
            method: 'PUT',
            body: JSON.stringify(payload),
          },
          token
        );

        removeQueueItem(item.id);
      } else if (item.operation === 'DELETE') {
        await apiFetch(
          `/surveys/${payload.remoteId}`,
          { method: 'DELETE' },
          token
        );

        removeQueueItem(item.id);
      }
    } catch (err: any) {
      markQueueItemFailed(item.id, err.message);
    }
  }

  // PULL
  const remoteUpdates = await apiFetch(
    `/surveys/changes?since=${encodeURIComponent(lastSyncAt ?? '')}`,
    {},
    token
  );

  for (const remote of remoteUpdates.items) {
    // Basic merge: overwrite local if remote is newer and local isn't pending
    upsertSurvey({
      localId: remote.localId ?? remote.id, // fallback
      remoteId: remote.id,
      version: remote.version,
      status: remote.conflict ? 'conflict' : 'synced',
      createdAt: remote.createdAt,
      updatedAt: remote.updatedAt,
      payload: remote.payload,
      pending: false,
      lastSyncedAt: new Date().toISOString(),
    });
  }

  return {
    syncedAt: new Date().toISOString(),
  };
}
```

