# 15) Create/edit survey flow

When the user saves a survey:

1. Save it locally
2. Mark as pending
3. Add create/update operation to queue
4. Attempt sync if online

```ts
// Example save handler
import { v4 as uuidv4 } from 'uuid';
import { upsertSurvey } from '../db/surveyRepo';
import { enqueueOperation } from '../db/queueRepo';

export function saveNewSurvey(payload: any) {
  const now = new Date().toISOString();
  const localId = uuidv4();

  upsertSurvey({
    localId,
    version: 1,
    status: 'draft',
    createdAt: now,
    updatedAt: now,
    payload,
    pending: true,
  });

  enqueueOperation({
    entityType: 'survey',
    entityLocalId: localId,
    operation: 'CREATE',
    payload: { localId, payload },
  });

  return localId;
}
