## 7) Survey CRUD with offline persistence

### `src/hooks/useSurveys.ts`
```ts
import { useEffect, useState } from 'react';
import { db } from '../db';
import { Survey } from '../db/schema';
import { apiFetch } from '../api/client';

export function useSurveys() {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadLocal = async () => {
      const localSurveys = await db.surveys.orderBy('updatedAt').reverse().toArray();
      setSurveys(localSurveys);
      setLoading(false);
    };
    loadLocal();
  }, []);

  const refreshFromServer = async () => {
    const serverSurveys = await apiFetch('/surveys');
    await db.transaction('rw', db.surveys, async () => {
      for (const s of serverSurveys) {
        await db.surveys.put({
          ...s,
          syncStatus: 'synced',
        });
      }
    });

    const localSurveys = await db.surveys.orderBy('updatedAt').reverse().toArray();
    setSurveys(localSurveys);
  };

  const createSurvey = async (survey: Omit<Survey, 'id' | 'updatedAt' | 'version' | 'syncStatus'>) => {
    const newSurvey: Survey = {
      id: crypto.randomUUID(),
      ...survey,
      updatedAt: new Date().toISOString(),
      version: 0,
      syncStatus: 'pending',
    };

    await db.surveys.put(newSurvey);
    await db.pendingMutations.add({
      id: crypto.randomUUID(),
      entityType: 'survey',
      entityId: newSurvey.id,
      operation: 'create',
      payload: newSurvey,
      createdAt: new Date().toISOString(),
      retryCount: 0,
    });

    setSurveys(await db.surveys.orderBy('updatedAt').reverse().toArray());
    return newSurvey;
  };

  const updateSurvey = async (id: string, changes: Partial<Survey>) => {
    const existing = await db.surveys.get(id);
    if (!existing) throw new Error('Survey not found');

    const updatedSurvey: Survey = {
      ...existing,
      ...changes,
      updatedAt: new Date().toISOString(),
      syncStatus: 'pending',
    };

    await db.surveys.put(updatedSurvey);
    await db.pendingMutations.add({
      id: crypto.randomUUID(),
      entityType: 'survey',
      entityId: id,
      operation: 'update',
      payload: changes,
      createdAt: new Date().toISOString(),
      retryCount: 0,
    });

    setSurveys(await db.surveys.orderBy('updatedAt').reverse().toArray());
  };

  const deleteSurvey = async (id: string) => {
    const existing = await db.surveys.get(id);
    if (!existing) return;

    await db.surveys.delete(id);
    await db.pendingMutations.add({
      id: crypto.randomUUID(),
      entityType: 'survey',
      entityId: id,
      operation: 'delete',
      payload: null,
      createdAt: new Date().toISOString(),
      retryCount: 0,
    });

    setSurveys(await db.surveys.orderBy('updatedAt').reverse().toArray());
  };

  return {
    surveys,
    loading,
    refreshFromServer,
    createSurvey,
    updateSurvey,
    deleteSurvey,
  };
}
```

