## 8) Sync engine

This is the heart of offline-first support.

### `src/api/sync.ts`
```ts
import { db } from '../db';
import { apiFetch } from './client';

export async function syncPendingMutations() {
  const mutations = await db.pendingMutations.orderBy('createdAt').toArray();

  for (const mutation of mutations) {
    try {
      switch (mutation.operation) {
        case 'create':
          await apiFetch('/surveys', {
            method: 'POST',
            body: JSON.stringify(mutation.payload),
          });
          break;

        case 'update':
          await apiFetch(`/surveys/${mutation.entityId}`, {
            method: 'PUT',
            body: JSON.stringify(mutation.payload),
          });
          break;

        case 'delete':
          await apiFetch(`/surveys/${mutation.entityId}`, {
            method: 'DELETE',
          });
          break;
      }

      await db.pendingMutations.delete(mutation.id);

      const survey = await db.surveys.get(mutation.entityId);
      if (survey && mutation.operation !== 'delete') {
        await db.surveys.put({
          ...survey,
          syncStatus: 'synced',
          updatedAt: new Date().toISOString(),
        });
      }
    } catch (err) {
      await db.pendingMutations.update(mutation.id, {
        retryCount: mutation.retryCount + 1,
      });

      await db.surveys.update(mutation.entityId, {
        syncStatus: 'failed',
      });

      // Stop on first failure to avoid cascading issues
      break;
    }
  }
}
```

