## 13) Minimal backend sketch

If needed, here’s a tiny Express-style server idea:

```ts
import express from 'express';
const app = express();
app.use(express.json());

const surveys = new Map<string, any>();

app.get('/surveys', (req, res) => {
  res.json(Array.from(surveys.values()));
});

app.post('/surveys', (req, res) => {
  const survey = { ...req.body, version: 1, updatedAt: new Date().toISOString() };
  surveys.set(survey.id, survey);
  res.json(survey);
});

app.put('/surveys/:id', (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).json({ error: 'Not found' });

  if (req.body.version !== existing.version) {
    return res.status(409).json({ error: 'Conflict', server: existing });
  }

  const updated = {
    ...existing,
    ...req.body,
    version: existing.version + 1,
    updatedAt: new Date().toISOString(),
  };

  surveys.set(req.params.id, updated);
  res.json(updated);
});

app.delete('/surveys/:id', (req, res) => {
  surveys.delete(req.params.id);
  res.status(204).send();
});

app.listen(3000);
```

