## 7. Client sync service

### `syncService.ts`

```ts
import { db } from './db';

const API_BASE = '/api';

export async function syncNow() {
  const pending = await db.outbox
    .where('status')
    .equals('pending')
    .sortBy('createdAt');

  if (pending.length === 0) return;

  const lastSyncToken = (await db.meta.get('lastSyncToken'))?.value ?? null;

  const response = await fetch(`${API_BASE}/sync`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      mutations: pending,
      lastSyncToken,
    }),
  });

  if (!response.ok) {
    throw new Error(`Sync failed: ${response.status}`);
  }

  const result = await response.json();

  // Apply server ack
  await db.transaction('rw', db.outbox, db.surveys, db.meta, async () => {
    for (const ack of result.acknowledgedMutations) {
      await db.outbox.update(ack.id, { status: 'synced' });
    }

    for (const record of result.updatedRecords) {
      await db.surveys.put(record);
    }

    await db.meta.put({ key: 'lastSyncToken', value: result.syncToken });
  });
}
```

