## 9. Mutation helpers

```ts
import { db, SurveyRecord, OutboxMutation } from './db';
import { v4 as uuidv4 } from 'uuid';

export async function saveSurveyDraft(input: Omit<SurveyRecord, 'id' | 'updatedAt' | 'version'> & { id?: string }) {
  const id = input.id ?? uuidv4();
  const now = new Date().toISOString();

  const record: SurveyRecord = {
    ...input,
    id,
    updatedAt: now,
    version: 0,
  };

  const mutation: OutboxMutation = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'create',
    payload: record,
    createdAt: now,
    retryCount: 0,
    status: 'pending',
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.put(record);
    await db.outbox.put(mutation);
  });

  return record;
}
```

