import * as SQLite from 'expo-sqlite';

export const db = SQLite.openDatabaseSync('field_survey.db');

export function runSql(sql: string, params: any[] = []): Promise<void> {
  return new Promise((resolve, reject) => {
    try {
      db.runSync(sql, params);
      resolve();
    } catch (error) {
      reject(error);
    }
  });
}

export function getAll<T = any>(sql: string, params: any[] = []): Promise<T[]> {
  return new Promise((resolve, reject) => {
    try {
      const result = db.getAllSync(sql, params);
      resolve(result as T[]);
    } catch (error) {
      reject(error);
    }
  });
}

export function getOne<T = any>(sql: string, params: any[] = []): Promise<T | null> {
  return new Promise((resolve, reject) => {
    try {
      const result = db.getFirstSync(sql, params);
      resolve((result as T) ?? null);
    } catch (error) {
      reject(error);
    }
  });
}
