## D. Survey service

### `src/services/surveyService.ts`
```ts
import { runSql, getAll, getOne } from '../db';
import { Survey } from '../types/models';
import { queueMutation } from './outboxService';
import { randomUUID } from 'expo-crypto';

export async function listSurveys(): Promise<Survey[]> {
  return getAll<Survey>(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );
}

export async function getSurvey(id: string): Promise<Survey | null> {
  return getOne<Survey>(`SELECT * FROM surveys WHERE id = ?`, [id]);
}

export async function saveSurvey(input: Partial<Survey> & { siteId: string; inspectorName: string }) {
  const now = new Date().toISOString();
  const existing = input.id ? await getSurvey(input.id) : null;

  const survey: Survey = {
    id: input.id ?? randomUUID(),
    siteId: input.siteId,
    inspectorName: input.inspectorName,
    latitude: input.latitude,
    longitude: input.longitude,
    notes: input.notes,
    status: input.status ?? 'draft',
    version: existing ? existing.version + 1 : 1,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
    deletedAt: null
  };

  await runSql(
    `
    INSERT INTO surveys (id, siteId, inspectorName, latitude, longitude, notes, status, version, createdAt, updatedAt, deletedAt)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      siteId = excluded.siteId,
      inspectorName = excluded.inspectorName,
      latitude = excluded.latitude,
      longitude = excluded.longitude,
      notes = excluded.notes,
      status = excluded.status,
      version = excluded.version,
      updatedAt = excluded.updatedAt,
      deletedAt = excluded.deletedAt
    `,
    [
      survey.id,
      survey.siteId,
      survey.inspectorName,
      survey.latitude ?? null,
      survey.longitude ?? null,
      survey.notes ?? null,
      survey.status,
      survey.version,
      survey.createdAt,
      survey.updatedAt,
      survey.deletedAt
    ]
  );

  await queueMutation({
    entityType: 'survey',
    entityId: survey.id,
    operation: existing ? 'update' : 'create',
    payload: survey
  });

  return survey;
}

export async function deleteSurvey(id: string) {
  const existing = await getSurvey(id);
  if (!existing) return;

  const now = new Date().toISOString();

  await runSql(
    `UPDATE surveys SET deletedAt = ?, updatedAt = ?, version = version + 1 WHERE id = ?`,
    [now, now, id]
  );

  await queueMutation({
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { id, deletedAt: now, version: existing.version + 1 }
  });
}
```

