## E. Outbox service

### `src/services/outboxService.ts`
```ts
import { runSql, getAll } from '../db';
import { randomUUID } from 'expo-crypto';

type QueueInput = {
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
};

export async function queueMutation(input: QueueInput) {
  const now = new Date().toISOString();
  await runSql(
    `
    INSERT INTO outbox (id, entityType, entityId, operation, payload, status, retries, createdAt)
    VALUES (?, ?, ?, ?, ?, 'pending', 0, ?)
    `,
    [
      randomUUID(),
      input.entityType,
      input.entityId,
      input.operation,
      JSON.stringify(input.payload),
      now
    ]
  );
}

export async function getPendingMutations() {
  return getAll<any>(
    `SELECT * FROM outbox WHERE status IN ('pending', 'failed') ORDER BY createdAt ASC`
  );
}

export async function markOutboxDone(id: string) {
  await runSql(`UPDATE outbox SET status = 'done', lastError = NULL WHERE id = ?`, [id]);
}

export async function markOutboxFailed(id: string, error: string) {
  await runSql(
    `UPDATE outbox SET status = 'failed', retries = retries + 1, lastError = ? WHERE id = ?`,
    [error, id]
  );
}
```

