## G. Sync engine

### `src/api/sync.ts`
```ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingMutations, markOutboxDone, markOutboxFailed } from '../services/outboxService';
import { apiRequest } from './client';
import { runSql, getOne } from '../db';

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return { ok: false, reason: 'offline' };

  const mutations = await getPendingMutations();

  for (const item of mutations) {
    try {
      const payload = JSON.parse(item.payload);

      await apiRequest('/sync/mutation', {
        method: 'POST',
        body: JSON.stringify({
          entityType: item.entityType,
          entityId: item.entityId,
          operation: item.operation,
          payload
        })
      });

      await markOutboxDone(item.id);
    } catch (error: any) {
      await markOutboxFailed(item.id, error.message);
    }
  }

  await pullUpdates();

  return { ok: true };
}

async function pullUpdates() {
  const cursorRow = await getOne<{ value: string }>(
    `SELECT value FROM sync_state WHERE key = 'lastSyncAt'`
  );

  const since = cursorRow?.value ?? '1970-01-01T00:00:00.000Z';
  const response = await apiRequest(`/sync/changes?since=${encodeURIComponent(since)}`);

  if (response?.surveys?.length) {
    for (const survey of response.surveys) {
      await runSql(
        `
        INSERT INTO surveys (id, siteId, inspectorName, latitude, longitude, notes, status, version, createdAt, updatedAt, deletedAt)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          siteId = excluded.siteId,
          inspectorName = excluded.inspectorName,
          latitude = excluded.latitude,
          longitude = excluded.longitude,
          notes = excluded.notes,
          status = excluded.status,
          version = excluded.version,
          createdAt = excluded.createdAt,
          updatedAt = excluded.updatedAt,
          deletedAt = excluded.deletedAt
        `,
        [
          survey.id,
          survey.siteId,
          survey.inspectorName,
          survey.latitude ?? null,
          survey.longitude ?? null,
          survey.notes ?? null,
          survey.status,
          survey.version,
          survey.createdAt,
          survey.updatedAt,
          survey.deletedAt ?? null
        ]
      );
    }
  }

  const now = new Date().toISOString();
  await runSql(
    `
    INSERT INTO sync_state (key, value)
    VALUES ('lastSyncAt', ?)
    ON CONFLICT(key) DO UPDATE SET value = excluded.value
    `,
    [now]
  );
}
```

