import { v4 as uuidv4 } from 'uuid';
import { db, Survey, OutboxItem } from './db';

export async function createSurvey(input: Omit<Survey, 'id' | 'updatedAt'>) {
  const now = new Date().toISOString();
  const survey: Survey = {
    ...input,
    id: uuidv4(),
    updatedAt: now,
  };

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: survey.id,
    operation: 'create',
    payload: survey,
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.put(survey);
    await db.outbox.put(outboxItem);
  });

  return survey;
}

export async function updateSurvey(id: string, changes: Partial<Survey>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const updated: Survey = {
    ...existing,
    ...changes,
    id,
    updatedAt: now,
  };

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: changes,
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.put(updated);
    await db.outbox.put(outboxItem);
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { deleted: true, updatedAt: now },
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.delete(id);
    await db.outbox.put(outboxItem);
  });
}

export async function getLocalSurveys() {
  return db.surveys.orderBy('updatedAt').reverse().toArray();
}
