## `src/syncService.ts`
```ts
import { db, OutboxItem, Survey } from './db';
import { api } from './api';

function isOnline() {
  return navigator.onLine;
}

export async function syncNow() {
  if (!isOnline()) return { ok: false, reason: 'offline' };

  const outboxItems = await db.outbox.orderBy('createdAt').toArray();
  if (outboxItems.length === 0) {
    await pullChanges();
    return { ok: true, pushed: 0, pulled: true };
  }

  try {
    const { data: pushResult } = await api.post('/sync/push', {
      mutations: outboxItems,
    });

    await db.transaction('rw', db.outbox, db.syncState, async () => {
      await db.outbox.bulkDelete(outboxItems.map((x) => x.id));
      await db.syncState.put({ key: 'lastSyncAt', value: new Date().toISOString() });
    });

    await pullChanges();

    return { ok: true, pushed: pushResult.applied?.length ?? outboxItems.length };
  } catch (error) {
    return { ok: false, reason: 'sync_failed', error };
  }
}

async function pullChanges() {
  const lastSync = await db.syncState.get('lastSyncAt');
  const since = lastSync?.value ?? '1970-01-01T00:00:00.000Z';

  const { data } = await api.get('/sync/pull', { params: { since } });

  const surveys: Survey[] = data.surveys ?? [];

  await db.transaction('rw', db.surveys, db.syncState, async () => {
    for (const survey of surveys) {
      if (survey.deleted) {
        await db.surveys.delete(survey.id);
      } else {
        await db.surveys.put(survey);
      }
    }
    await db.syncState.put({ key: 'lastSyncAt', value: data.serverTime });
  });
}

export function startAutoSync() {
  window.addEventListener('online', () => syncNow());
  window.addEventListener('focus', () => syncNow());

  setInterval(() => {
    if (navigator.onLine) syncNow();
  }, 30000);
}
```

