  async function mutateFirst() {
    if (!surveys[0]) return;
    await updateSurvey(surveys[0].id, { notes: `Updated at ${new Date().toISOString()}` });
    await refresh();
  }

  async function removeFirst() {
    if (!surveys[0]) return;
    await deleteSurvey(surveys[0].id);
    await refresh();
  }

  return (
    <div style={{ padding: 24 }}>
      <h1>Field Survey App</h1>
      <p>Status: {online ? 'Online' : 'Offline'}</p>

      <button onClick={addDemoSurvey}>Add Survey</button>
      <button onClick={mutateFirst} style={{ marginLeft: 8 }}>Update First</button>
      <button onClick={removeFirst} style={{ marginLeft: 8 }}>Delete First</button>
      <button onClick={() => syncNow().then(refresh)} style={{ marginLeft: 8 }}>Sync Now</button>

      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.plotId}</strong> by {s.observerName} - {s.notes}
          </li>
        ))}
      </ul>
    </div>
  );
}
