import { getDb } from "./index";
import { SurveyPoint } from "../types/survey";

export async function upsertSurveyPoint(point: SurveyPoint) {
  const db = await getDb();

  await db.executeSql(
    `
    INSERT INTO survey_points (
      id, server_id, title, description, latitude, longitude,
      status, updated_at, created_at, deleted_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      server_id=excluded.server_id,
      title=excluded.title,
      description=excluded.description,
      latitude=excluded.latitude,
      longitude=excluded.longitude,
      status=excluded.status,
      updated_at=excluded.updated_at,
      created_at=excluded.created_at,
      deleted_at=excluded.deleted_at
    `,
    [
      point.id,
      point.serverId ?? null,
      point.title,
      point.description ?? null,
      point.latitude,
      point.longitude,
      point.status,
      point.updatedAt,
      point.createdAt,
      point.deletedAt ?? null,
    ]
  );
}

export async function getAllSurveyPoints(): Promise<SurveyPoint[]> {
  const db = await getDb();
  const [result] = await db.executeSql(`
    SELECT * FROM survey_points
    WHERE deleted_at IS NULL
    ORDER BY updated_at DESC
  `);

  const items: SurveyPoint[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    const row = result.rows.item(i);
    items.push({
      id: row.id,
      serverId: row.server_id,
      title: row.title,
      description: row.description,
      latitude: row.latitude,
      longitude: row.longitude,
      status: row.status,
      updatedAt: row.updated_at,
      createdAt: row.created_at,
      deletedAt: row.deleted_at,
    });
  }
  return items;
}

export async function getSurveyPointById(id: string): Promise<SurveyPoint | null> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM survey_points WHERE id = ?`, [id]);

  if (result.rows.length === 0) return null;
  const row = result.rows.item(0);

  return {
    id: row.id,
    serverId: row.server_id,
    title: row.title,
    description: row.description,
    latitude: row.latitude,
    longitude: row.longitude,
    status: row.status,
    updatedAt: row.updated_at,
    createdAt: row.created_at,
    deletedAt: row.deleted_at,
  };
}
