import { getDb } from "./index";
import { SyncQueueItem } from "../types/survey";

export async function addQueueItem(item: SyncQueueItem) {
  const db = await getDb();
  await db.executeSql(
    `
    INSERT INTO sync_queue (
      id, entity_type, entity_id, operation, payload, status,
      retry_count, created_at, last_attempt_at, error_message
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `,
    [
      item.id,
      item.entityType,
      item.entityId,
      item.operation,
      item.payload,
      item.status,
      item.retryCount,
      item.createdAt,
      item.lastAttemptAt ?? null,
      item.errorMessage ?? null,
    ]
  );
}

export async function getPendingQueueItems(): Promise<SyncQueueItem[]> {
  const db = await getDb();
  const [result] = await db.executeSql(`
    SELECT * FROM sync_queue
    WHERE status IN ('pending', 'failed')
    ORDER BY created_at ASC
  `);

  const items: SyncQueueItem[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    const row = result.rows.item(i);
    items.push({
      id: row.id,
      entityType: row.entity_type,
      entityId: row.entity_id,
      operation: row.operation,
      payload: row.payload,
      status: row.status,
      retryCount: row.retry_count,
      createdAt: row.created_at,
      lastAttemptAt: row.last_attempt_at,
      errorMessage: row.error_message,
    });
  }
  return items;
}

export async function markQueueItemDone(id: string) {
  const db = await getDb();
  await db.executeSql(`UPDATE sync_queue SET status = 'done' WHERE id = ?`, [id]);
}

export async function markQueueItemFailed(id: string, errorMessage: string) {
  const db = await getDb();
  await db.executeSql(
    `
    UPDATE sync_queue
    SET status = 'failed',
        retry_count = retry_count + 1,
        last_attempt_at = datetime('now'),
        error_message = ?
    WHERE id = ?
    `,
    [errorMessage, id]
  );
}
