# 10. Sync service

## `src/network/syncService.ts`

```ts
import { getPendingQueueItems, markQueueItemDone, markQueueItemFailed } from "../db/syncQueueRepo";
import { apiPost, apiGet } from "./api";
import { upsertSurveyPoint } from "../db/surveyRepo";
import { SurveyPoint } from "../types/survey";

export async function syncOfflineData() {
  const queueItems = await getPendingQueueItems();

  for (const item of queueItems) {
    try {
      const payload = JSON.parse(item.payload);

      if (item.entityType === "survey_point") {
        if (item.operation === "create") {
          const res = await apiPost("/survey-points", payload);

          const updatedPoint: SurveyPoint = {
            ...payload,
            serverId: res.id,
            status: "synced",
            updatedAt: new Date().toISOString(),
          };

          await upsertSurveyPoint(updatedPoint);
        }

        if (item.operation === "update") {
          await apiPost(`/survey-points/${payload.serverId || payload.id}`, payload);
        }

        if (item.operation === "delete") {
          await apiPost(`/survey-points/${payload.serverId || payload.id}/delete`, {});
        }
      }

      await markQueueItemDone(item.id);
    } catch (error: any) {
      await markQueueItemFailed(item.id, error.message ?? "Sync failed");
    }
  }

  // Optional: pull latest remote changes
  await pullRemoteUpdates();
}

async function pullRemoteUpdates() {
  const remotePoints = await apiGet("/survey-points");
  for (const p of remotePoints) {
    const point: SurveyPoint = {
      id: p.localId ?? p.id,
      serverId: p.id,
      title: p.title,
      description: p.description,
      latitude: p.latitude,
      longitude: p.longitude,
      status: "synced",
      createdAt: p.createdAt,
      updatedAt: p.updatedAt,
      deletedAt: null,
    };

    await upsertSurveyPoint(point);
  }
}
```

