import React, { useState } from "react";
import { View, TextInput, Button, Text } from "react-native";
import { createId } from "../utils/ids";
import { nowIso } from "../utils/timestamps";
import { upsertSurveyPoint } from "../db/surveyRepo";
import { addQueueItem } from "../db/syncQueueRepo";
import { SurveyPoint } from "../types/survey";

export function SurveyFormScreen() {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [latitude, setLatitude] = useState("0");
  const [longitude, setLongitude] = useState("0");
  const [message, setMessage] = useState("");

  const saveSurvey = async () => {
    const id = createId();
    const createdAt = nowIso();

    const point: SurveyPoint = {
      id,
      title,
      description,
      latitude: parseFloat(latitude),
      longitude: parseFloat(longitude),
      status: "new",
      createdAt,
      updatedAt: createdAt,
      deletedAt: null,
    };

    await upsertSurveyPoint(point);

    await addQueueItem({
      id: createId(),
      entityType: "survey_point",
      entityId: id,
      operation: "create",
      payload: JSON.stringify(point),
      status: "pending",
      retryCount: 0,
      createdAt: nowIso(),
      lastAttemptAt: null,
      errorMessage: null,
    });

    setMessage("Survey saved locally and queued for sync.");
    setTitle("");
    setDescription("");
    setLatitude("0");
    setLongitude("0");
  };

  return (
    <View style={{ padding: 16 }}>
      <Text>Title</Text>
      <TextInput value={title} onChangeText={setTitle} style={{ borderWidth: 1, marginBottom: 8 }} />

      <Text>Description</Text>
      <TextInput value={description} onChangeText={setDescription} style={{ borderWidth: 1, marginBottom: 8 }} />

      <Text>Latitude</Text>
      <TextInput value={latitude} onChangeText={setLatitude} keyboardType="numeric" style={{ borderWidth: 1, marginBottom: 8 }} />

      <Text>Longitude</Text>
      <TextInput value={longitude} onChangeText={setLongitude} keyboardType="numeric" style={{ borderWidth: 1, marginBottom: 8 }} />

      <Button title="Save Survey Locally" onPress={saveSurvey} />
      {message ? <Text style={{ marginTop: 12 }}>{message}</Text> : null}
    </View>
  );
}
