### 7.4 Local save with queueing

**`src/sync/queueProcessor.ts`**
```ts
import { db } from '../db';
import { api } from '../services/api';

export async function saveSurveyLocally(survey: any) {
  const now = new Date().toISOString();

  await db.surveys.put({
    ...survey,
    updatedAt: now
  });

  await db.queue.add({
    id: crypto.randomUUID(),
    entityType: 'survey',
    entityId: survey.id,
    action: survey.version ? 'update' : 'create',
    payload: survey,
    createdAt: now,
    retries: 0
  });
}
```

