### 7.6 Auto-sync on reconnect

**`src/app/App.tsx`**
```tsx
import React, { useEffect, useState } from 'react';
import { onConnectivityChange, isOnline } from '../services/connectivity';
import { syncPendingChanges } from '../sync/syncManager';
import { db } from '../db';

export default function App() {
  const [online, setOnline] = useState(isOnline());

  useEffect(() => {
    const unsubscribe = onConnectivityChange(async (nextOnline) => {
      setOnline(nextOnline);
      if (nextOnline) {
        await syncPendingChanges();
      }
    });

    return unsubscribe;
  }, []);

  return (
    <div>
      <header>
        <h1>Field Survey App</h1>
        <p>Status: {online ? 'Online' : 'Offline'}</p>
      </header>

      <main>
        <button
          onClick={async () => {
            await syncPendingChanges();
          }}
          disabled={!online && false}
        >
          Sync Now
        </button>
      </main>
    </div>
  );
}
