# Local storage service

## `lib/services/local_store.dart`

```dart
import 'package:hive/hive.dart';
import '../models/survey_entry.dart';

class LocalStore {
  static const String boxName = 'survey_entries';
  late final Box box;

  Future<void> init() async {
    box = await Hive.openBox(boxName);
  }

  List<SurveyEntry> getAll() {
    return box.values
        .map((e) => SurveyEntry.fromMap(Map<String, dynamic>.from(e)))
        .toList()
      ..sort((a, b) => b.updatedAt.compareTo(a.updatedAt));
  }

  Future<void> save(SurveyEntry entry) async {
    await box.put(entry.id, entry.toMap());
  }

  Future<void> delete(String id) async {
    final existing = box.get(id);
    if (existing != null) {
      final entry = SurveyEntry.fromMap(Map<String, dynamic>.from(existing));
      await save(entry.copyWith(
        deleted: true,
        updatedAt: DateTime.now(),
        syncStatus: SyncStatus.pending,
      ));
    }
  }

  List<SurveyEntry> pendingSync() {
    return getAll()
        .where((e) => e.syncStatus != SyncStatus.synced || e.deleted)
        .toList();
  }
}
```

