# Sync service

## `lib/services/sync_service.dart`

```dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import '../models/survey_entry.dart';
import 'local_store.dart';

class SyncService {
  final LocalStore store;
  final String baseUrl;

  SyncService({
    required this.store,
    required this.baseUrl,
  });

  Future<void> syncPending() async {
    final pending = store.pendingSync();

    for (final entry in pending) {
      try {
        if (entry.deleted) {
          await _deleteRemote(entry.id);
        } else {
          await _upsertRemote(entry);
        }

        await store.save(entry.copyWith(syncStatus: SyncStatus.synced));
      } catch (_) {
        await store.save(entry.copyWith(syncStatus: SyncStatus.failed));
      }
    }
  }

  Future<void> _upsertRemote(SurveyEntry entry) async {
    final response = await http.post(
      Uri.parse('$baseUrl/surveys'),
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode(entry.toMap()),
    );

    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw Exception('Sync failed');
    }
  }

  Future<void> _deleteRemote(String id) async {
    final response = await http.delete(
      Uri.parse('$baseUrl/surveys/$id'),
    );

    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw Exception('Delete sync failed');
    }
  }
}
```

