import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import '../models/survey_entry.dart';

class SurveyFormScreen extends StatefulWidget {
  final SurveyEntry? existing;

  const SurveyFormScreen({
    super.key,
    required this.existing,
  });

  @override
  State<SurveyFormScreen> createState() => _SurveyFormScreenState();
}

class _SurveyFormScreenState extends State<SurveyFormScreen> {
  final _formKey = GlobalKey<FormState>();
  final _uuid = const Uuid();

  late final TextEditingController _titleController;
  late final TextEditingController _notesController;

  @override
  void initState() {
    super.initState();
    _titleController = TextEditingController(text: widget.existing?.title ?? '');
    _notesController = TextEditingController(text: widget.existing?.notes ?? '');
  }

  @override
  void dispose() {
    _titleController.dispose();
    _notesController.dispose();
    super.dispose();
  }

  void _save() {
    if (!_formKey.currentState!.validate()) return;

    final now = DateTime.now();
    final entry = widget.existing ?? SurveyEntry(
      id: _uuid.v4(),
      title: '',
      notes: '',
      createdAt: now,
      updatedAt: now,
      syncStatus: SyncStatus.pending,
    );

    final updated = entry.copyWith(
      title: _titleController.text,
      notes: _notesController.text,
      updatedAt: now,
      syncStatus: SyncStatus.pending,
    );

    Navigator.pop(context, updated);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.existing == null ? 'New Survey' : 'Edit Survey'),
        actions: [
          TextButton(
            onPressed: _save,
            child: const Text('SAVE'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              TextFormField(
                controller: _titleController,
                decoration: const InputDecoration(labelText: 'Title'),
                validator: (value) =>
                    value == null || value.isEmpty ? 'Required' : null,
              ),
              const SizedBox(height: 12),
              TextFormField(
                controller: _notesController,
                decoration: const InputDecoration(labelText: 'Notes'),
                maxLines: 5,
              ),
            ],
          ),
        ),
      ),
    );
  }
}
