# 3) Backend: Express API

## `server.js`
```js
const express = require("express");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

let surveys = []; // minimal demo storage

// Get all surveys
app.get("/api/surveys", (req, res) => {
  res.json(surveys);
});

// Bulk upsert surveys
app.post("/api/sync", (req, res) => {
  const incoming = req.body.surveys || [];

  incoming.forEach((item) => {
    const idx = surveys.findIndex((s) => s.id === item.id);

    if (idx >= 0) {
      // last-write-wins
      if (new Date(item.updatedAt) > new Date(surveys[idx].updatedAt)) {
        surveys[idx] = item;
      }
    } else {
      surveys.push(item);
    }
  });

  res.json({ ok: true, surveys });
});

app.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

