## `src/App.jsx`
```jsx
import { useEffect, useState } from "react";
import { db } from "./db";

const API_URL = "http://localhost:3001";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [siteName, setSiteName] = useState("");
  const [lat, setLat] = useState("");
  const [lng, setLng] = useState("");
  const [notes, setNotes] = useState("");
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState("");

  const loadLocal = async () => {
    const items = await db.surveys.orderBy("updatedAt").reverse().toArray();
    setSurveys(items);
  };

  const sync = async () => {
    try {
      setStatus("Syncing...");
      const pending = await db.surveys.where("synced").equals(0).toArray();

      if (pending.length > 0) {
        await fetch(`${API_URL}/api/sync`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ surveys: pending })
        });

        await db.surveys.bulkUpdate(
          pending.map((s) => ({ id: s.id, synced: 1 }))
        );
      }

      const res = await fetch(`${API_URL}/api/surveys`);
      const serverData = await res.json();

      // Merge server data into local store
      for (const item of serverData) {
        const local = await db.surveys.get(item.id);
        if (!local || new Date(item.updatedAt) > new Date(local.updatedAt)) {
          await db.surveys.put({ ...item, synced: 1 });
        }
      }

      await loadLocal();
      setStatus("Synced");
    } catch (e) {
      console.error(e);
      setStatus("Sync failed");
    }
  };

  useEffect(() => {
    loadLocal();
    if (navigator.onLine) sync();

    const goOnline = () => {
      setOnline(true);
      sync();
    };
    const goOffline = () => setOnline(false);

    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);

    return () => {
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, []);

  const addSurvey = async (e) => {
    e.preventDefault();

    const item = {
      id: uuid(),
      siteName,
      lat: Number(lat),
      lng: Number(lng),
      notes,
      updatedAt: new Date().toISOString(),
      synced: 0
    };

    await db.surveys.put(item);
    await loadLocal();

    setSiteName("");
    setLat("");
    setLng("");
    setNotes("");
    setStatus("Saved locally");

    if (navigator.onLine) {
      await sync();
    }
  };

  const clearAll = async () => {
    await db.surveys.clear();
    await loadLocal();
  };

  return (
    <div style={{ fontFamily: "sans-serif", padding: 20, maxWidth: 800 }}>
      <h1>Offline Survey App</h1>
      <p>
        Status: <strong>{online ? "Online" : "Offline"}</strong> | {status}
      </p>

      <form onSubmit={addSurvey} style={{ display: "grid", gap: 8, marginBottom: 20 }}>
        <input
          placeholder="Site name"
          value={siteName}
          onChange={(e) => setSiteName(e.target.value)}
          required
        />
        <input
          placeholder="Latitude"
          value={lat}
          onChange={(e) => setLat(e.target.value)}
          required
        />
        <input
          placeholder="Longitude"
          value={lng}
          onChange={(e) => setLng(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <button type="submit">Save Survey</button>
      </form>

      <button onClick={sync} style={{ marginRight: 8 }}>
        Sync Now
      </button>
      <button onClick={clearAll}>Clear Local Data</button>

      <h2 style={{ marginTop: 24 }}>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.siteName}</strong> ({s.lat}, {s.lng}) — {s.notes}{" "}
            <em>{s.synced ? "[synced]" : "[pending]"}</em>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

