import { addSurvey, getAllSurveys, updateSurvey } from "./db.js";

const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const connStatus = document.getElementById("connStatus");

function setStatus() {
  connStatus.textContent = navigator.onLine ? "online" : "offline";
  connStatus.className = navigator.onLine ? "synced" : "pending";
}

async function renderSurveys() {
  const surveys = await getAllSurveys();
  surveyList.innerHTML = "";

  surveys.forEach((s) => {
    const li = document.createElement("li");
    li.textContent = `${s.siteName} (${s.lat}, ${s.lng}) - ${s.notes || ""} [${s.synced ? "synced" : "pending"}]`;
    li.className = s.synced ? "synced" : "pending";
    surveyList.appendChild(li);
  });
}

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllSurveys();
  const pending = surveys.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const resp = await fetch("http://localhost:3000/api/surveys", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (resp.ok) {
        survey.synced = true;
        await updateSurvey(survey);
      }
    } catch (err) {
      console.error("Sync failed:", err);
    }
  }

  await renderSurveys();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    siteName: document.getElementById("siteName").value,
    lat: parseFloat(document.getElementById("lat").value),
    lng: parseFloat(document.getElementById("lng").value),
    notes: document.getElementById("notes").value,
    synced: false,
    createdAt: new Date().toISOString()
  };

  await addSurvey(survey);
  form.reset();
  await renderSurveys();
  await syncSurveys();
});

window.addEventListener("online", async () => {
  setStatus();
  await syncSurveys();
});

window.addEventListener("offline", setStatus);

if ("serviceWorker" in navigator) {
  navigator.serviceWorker.register("/sw.js");
}

setStatus();
renderSurveys();
syncSurveys();
