### `server/index.js`
```js
import express from "express";
import cors from "cors";

const app = express();
app.use(cors());
app.use(express.json());

/**
 * Minimal in-memory store:
 * id -> record
 */
const records = new Map();
let serverClock = Date.now();

app.get("/health", (req, res) => {
  res.json({ ok: true });
});

/**
 * POST /sync
 * Body:
 * {
 *   deviceId: string,
 *   changes: [record],
 *   lastSyncAt: number
 * }
 *
 * Response:
 * {
 *   serverTime: number,
 *   changes: [record]
 * }
 */
app.post("/sync", (req, res) => {
  const { changes = [], lastSyncAt = 0 } = req.body;

  // Apply incoming changes using last-write-wins
  for (const incoming of changes) {
    const existing = records.get(incoming.id);
    if (!existing || incoming.updatedAt >= existing.updatedAt) {
      records.set(incoming.id, { ...incoming });
    }
  }

  // Return records updated since lastSyncAt
  const changedSince = [];
  for (const record of records.values()) {
    if (record.updatedAt > lastSyncAt) {
      changedSince.push(record);
    }
  }

  serverClock = Math.max(serverClock + 1, Date.now());

  res.json({
    serverTime: serverClock,
    changes: changedSince
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Sync server running on http://localhost:${PORT}`);
});
```

