## 6) Minimal app code

### `App.js`
```js
import React, { useEffect, useState } from "react";
import { View, Text, TextInput, Button, FlatList, TouchableOpacity, Alert } from "react-native";
import NetInfo from "@react-native-community/netinfo";
import SQLite from "react-native-sqlite-storage";
import { v4 as uuidv4 } from "uuid";

SQLite.enablePromise(true);

const DB_NAME = "survey_app.db";
const SERVER_URL = "http://localhost:3000"; // change to your machine IP on device

export default function App() {
  const [db, setDb] = useState(null);
  const [online, setOnline] = useState(false);
  const [surveys, setSurveys] = useState([]);
  const [name, setName] = useState("");
  const [notes, setNotes] = useState("");

  useEffect(() => {
    init();
    const unsub = NetInfo.addEventListener(state => {
      setOnline(!!state.isConnected && !!state.isInternetReachable);
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    if (online && db) {
      syncNow();
    }
  }, [online, db]);

  async function init() {
    const database = await SQLite.openDatabase({ name: DB_NAME, location: "default" });
    setDb(database);

    await database.executeSql(`
      CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        latitude REAL,
        longitude REAL,
        notes TEXT,
        updatedAt INTEGER NOT NULL,
        deleted INTEGER DEFAULT 0,
        dirty INTEGER DEFAULT 1
      );
    `);

    await database.executeSql(`
      CREATE TABLE IF NOT EXISTS meta (
        key TEXT PRIMARY KEY,
        value TEXT
      );
    `);

    const rows = await loadSurveys(database);
    setSurveys(rows);
  }

  async function loadSurveys(database = db) {
    const [result] = await database.executeSql(
      "SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC"
    );
    const items = [];
    for (let i = 0; i < result.rows.length; i++) {
      items.push(result.rows.item(i));
    }
    return items;
  }

  async function getMeta(key, defaultValue = "0") {
    const [result] = await db.executeSql("SELECT value FROM meta WHERE key = ?", [key]);
    if (result.rows.length === 0) return defaultValue;
    return result.rows.item(0).value;
  }

  async function setMeta(key, value) {
    await db.executeSql(
      "INSERT INTO meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
      [key, String(value)]
    );
  }

  async function addSurvey() {
    if (!name.trim()) {
      Alert.alert("Validation", "Name is required");
      return;
    }

    const now = Date.now();
    const id = uuidv4();

    await db.executeSql(
      `INSERT INTO surveys (id, name, latitude, longitude, notes, updatedAt, deleted, dirty)
       VALUES (?, ?, ?, ?, ?, ?, 0, 1)`,
      [id, name.trim(), null, null, notes.trim(), now]
    );

    setName("");
    setNotes("");
    setSurveys(await loadSurveys());
  }

  async function markDeleted(id) {
    const now = Date.now();
    await db.executeSql(
      `UPDATE surveys SET deleted = 1, updatedAt = ?, dirty = 1 WHERE id = ?`,
      [now, id]
    );
    setSurveys(await loadSurveys());
    if (online) syncNow();
  }

  async function syncNow() {
    if (!db) return;

    try {
      const lastSyncAt = parseInt(await getMeta("lastSyncAt", "0"), 10);

      // Pull dirty local rows
      const [dirtyResult] = await db.executeSql(
        "SELECT * FROM surveys WHERE dirty = 1"
      );

      const changes = [];
      for (let i = 0; i < dirtyResult.rows.length; i++) {
        changes.push(dirtyResult.rows.item(i));
      }

      const response = await fetch(`${SERVER_URL}/sync`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          deviceId: "demo-device",
          lastSyncAt,
          changes
        })
      });

      if (!response.ok) throw new Error("Sync failed");

      const data = await response.json();

      // Apply server changes
      for (const record of data.changes) {
        const [existingResult] = await db.executeSql(
          "SELECT updatedAt FROM surveys WHERE id = ?",
          [record.id]
        );

        const localUpdatedAt = existingResult.rows.length
          ? existingResult.rows.item(0).updatedAt
          : 0;

        if (record.updatedAt >= localUpdatedAt) {
          await db.executeSql(
            `INSERT INTO surveys (id, name, latitude, longitude, notes, updatedAt, deleted, dirty)
             VALUES (?, ?, ?, ?, ?, ?, ?, 0)
             ON CONFLICT(id) DO UPDATE SET
               name = excluded.name,
               latitude = excluded.latitude,
               longitude = excluded.longitude,
               notes = excluded.notes,
               updatedAt = excluded.updatedAt,
               deleted = excluded.deleted,
               dirty = 0`,
            [
              record.id,
              record.name,
              record.latitude,
              record.longitude,
              record.notes,
              record.updatedAt,
              record.deleted
            ]
          );
        }
      }

      // Mark local dirty rows as clean after push
      await db.executeSql("UPDATE surveys SET dirty = 0 WHERE dirty = 1");

      await setMeta("lastSyncAt", data.serverTime);
      setSurveys(await loadSurveys());
    } catch (err) {
      console.log("Sync error:", err.message);
    }
  }

  return (
    <View style={{ flex: 1, padding: 20, marginTop: 50 }}>
      <Text style={{ fontSize: 20, fontWeight: "bold" }}>Field Survey App</Text>
      <Text style={{ marginVertical: 8 }}>
        Status: {online ? "Online" : "Offline"}
      </Text>

      <TextInput
        placeholder="Survey name"
        value={name}
        onChangeText={setName}
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />

      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={{ borderWidth: 1, marginBottom: 8, padding: 8 }}
      />

      <Button title="Add Survey" onPress={addSurvey} />

      <View style={{ height: 12 }} />

      <Button title="Sync Now" onPress={syncNow} />

      <FlatList
        style={{ marginTop: 20 }}
        data={surveys}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <TouchableOpacity
            onLongPress={() =>
              Alert.alert("Delete survey?", item.name, [
                { text: "Cancel", style: "cancel" },
                { text: "Delete", style: "destructive", onPress: () => markDeleted(item.id) }
              ])
            }
            style={{
              padding: 12,
              borderBottomWidth: 1,
              borderColor: "#ddd"
            }}
          >
            <Text style={{ fontWeight: "bold" }}>{item.name}</Text>
            <Text>{item.notes}</Text>
            <Text style={{ color: "#666" }}>
              Updated: {new Date(item.updatedAt).toLocaleString()}
              {" | "}
              {item.dirty ? "Unsynced" : "Synced"}
            </Text>
          </TouchableOpacity>
        )}
      />
    </View>
  );
}
```

