## `server/index.js`
```js
import express from "express";
import cors from "cors";
import fs from "fs/promises";

const app = express();
const PORT = 3001;
const DATA_FILE = "./data.json";

app.use(cors());
app.use(express.json());

async function readData() {
  const raw = await fs.readFile(DATA_FILE, "utf-8");
  return JSON.parse(raw);
}

async function writeData(data) {
  await fs.writeFile(DATA_FILE, JSON.stringify(data, null, 2));
}

app.get("/surveys", async (req, res) => {
  const data = await readData();
  res.json(data.surveys);
});

app.post("/surveys/bulk", async (req, res) => {
  const { surveys } = req.body;
  if (!Array.isArray(surveys)) {
    return res.status(400).json({ error: "surveys must be an array" });
  }

  const data = await readData();
  const map = new Map(data.surveys.map(s => [s.id, s]));

  for (const survey of surveys) {
    map.set(survey.id, survey);
  }

  data.surveys = Array.from(map.values());
  await writeData(data);

  res.json({ ok: true, count: surveys.length });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

This is intentionally simple:
- `GET /surveys` returns all surveys.
- `POST /surveys/bulk` accepts an array and upserts by `id`.

