# 5) Main app

## `client/src/App.jsx`
```jsx
import React, { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import { db } from "./db";
import { fetchSurveys, pushSurveys } from "./api";

export default function App() {
  const [siteName, setSiteName] = useState("");
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState("Loading...");

  async function loadLocal() {
    const local = await db.surveys.orderBy("updatedAt").reverse().toArray();
    setSurveys(local);
  }

  async function sync() {
    if (!navigator.onLine) {
      setStatus("Offline - changes saved locally");
      return;
    }

    try {
      const pending = await db.surveys.where("synced").equals(0).or("synced").equals(false).toArray();

      if (pending.length > 0) {
        await pushSurveys(pending.map(({ synced, ...rest }) => rest));
        await db.surveys.bulkPut(
          pending.map(s => ({ ...s, synced: true }))
        );
      }

      const remote = await fetchSurveys();
      const local = await db.surveys.toArray();
      const localIds = new Set(local.map(s => s.id));

      const missingLocally = remote.filter(r => !localIds.has(r.id));
      if (missingLocally.length > 0) {
        await db.surveys.bulkPut(missingLocally.map(s => ({ ...s, synced: true })));
      }

      await loadLocal();
      setStatus("Synced");
    } catch (err) {
      console.error(err);
      setStatus("Sync failed - working offline");
    }
  }

  async function saveSurvey(e) {
    e.preventDefault();

    const item = {
      id: uuidv4(),
      siteName,
      latitude: parseFloat(latitude),
      longitude: parseFloat(longitude),
      notes,
      updatedAt: Date.now(),
      synced: false
    };

    await db.surveys.add(item);
    await loadLocal();

    setSiteName("");
    setLatitude("");
    setLongitude("");
    setNotes("");

    setStatus("Saved locally");
    if (navigator.onLine) {
      await sync();
    }
  }

  useEffect(() => {
    loadLocal();
    sync();

    const onOnline = () => sync();
    window.addEventListener("online", onOnline);

    return () => window.removeEventListener("online", onOnline);
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 800, margin: "40px auto", padding: 16 }}>
      <h1>Field Survey App</h1>
      <p><strong>Status:</strong> {status}</p>
      <p><strong>Connectivity:</strong> {navigator.onLine ? "Online" : "Offline"}</p>

      <form onSubmit={saveSurvey} style={{ display: "grid", gap: 8, marginBottom: 24 }}>
        <input placeholder="Site name" value={siteName} onChange={e => setSiteName(e.target.value)} required />
        <input placeholder="Latitude" value={latitude} onChange={e => setLatitude(e.target.value)} required />
        <input placeholder="Longitude" value={longitude} onChange={e => setLongitude(e.target.value)} required />
        <textarea placeholder="Notes" value={notes} onChange={e => setNotes(e.target.value)} />
        <button type="submit">Save Survey</button>
      </form>

      <button onClick={sync} style={{ marginBottom: 16 }}>Sync Now</button>

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map(s => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <div><strong>{s.siteName}</strong></div>
            <div>{s.latitude}, {s.longitude}</div>
            <div>{s.notes}</div>
            <small>{new Date(s.updatedAt).toLocaleString()} {s.synced ? "(synced)" : "(pending)"}</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

