const app = express();
app.use(cors());
app.use(express.json());

const db = new Database("surveys.db");

// Init DB
db.exec(`
CREATE TABLE IF NOT EXISTS surveys (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  location TEXT NOT NULL,
  notes TEXT NOT NULL,
  updatedAt TEXT NOT NULL,
  deleted INTEGER DEFAULT 0
);
`);

app.get("/api/surveys", (req, res) => {
  const since = req.query.since || "1970-01-01T00:00:00.000Z";
  const rows = db.prepare(
    "SELECT * FROM surveys WHERE updatedAt > ?"
  ).all(since);

  res.json(rows.map(r => ({
    ...r,
    deleted: !!r.deleted
  })));
});

app.post("/api/sync", (req, res) => {
  const { changes, since } = req.body;

  const upsert = db.prepare(`
    INSERT INTO surveys (id, title, location, notes, updatedAt, deleted)
    VALUES (@id, @title, @location, @notes, @updatedAt, @deleted)
    ON CONFLICT(id) DO UPDATE SET
      title=excluded.title,
      location=excluded.location,
      notes=excluded.notes,
      updatedAt=excluded.updatedAt,
      deleted=excluded.deleted
    WHERE excluded.updatedAt > surveys.updatedAt
  `);

  const transaction = db.transaction((changes) => {
    for (const item of changes) {
      upsert.run({
        id: item.id,
        title: item.title || "",
        location: item.location || "",
        notes: item.notes || "",
        updatedAt: item.updatedAt,
        deleted: item.deleted ? 1 : 0
      });
    }
  });

  transaction(changes || []);

  const serverChanges = db.prepare(
    "SELECT * FROM surveys WHERE updatedAt > ?"
  ).all(since || "1970-01-01T00:00:00.000Z");

  res.json({
    ok: true,
    serverChanges: serverChanges.map(r => ({
      ...r,
      deleted: !!r.deleted
    })),
    serverTime: new Date().toISOString()
  });
});

const PORT = 3001;
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

