## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from 'react';
import { db } from './db';
import { syncChanges } from './api';

function uuid() {
  return crypto.randomUUID();
}

async function getMeta(key, fallback = '') {
  const row = await db.meta.get(key);
  return row ? row.value : fallback;
}

async function setMeta(key, value) {
  await db.meta.put({ key, value });
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [form, setForm] = useState({
    title: '',
    location: '',
    notes: ''
  });

  async function loadLocal() {
    const items = await db.surveys.where('deleted').equals(0).toArray();
    setSurveys(items.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)));
  }

  async function addSurvey() {
    const now = new Date().toISOString();
    const survey = {
      id: uuid(),
      title: form.title,
      location: form.location,
      notes: form.notes,
      updatedAt: now,
      deleted: 0
    };

    await db.surveys.put(survey);

    const pending = JSON.parse(await getMeta('pendingChanges', '[]'));
    pending.push(survey);
    await setMeta('pendingChanges', JSON.stringify(pending));

    setForm({ title: '', location: '', notes: '' });
    await loadLocal();
  }

  async function doSync() {
    if (!navigator.onLine) return;

    const pending = JSON.parse(await getMeta('pendingChanges', '[]'));
    const lastSyncAt = await getMeta('lastSyncAt', '1970-01-01T00:00:00.000Z');

    const result = await syncChanges({
      changes: pending,
      since: lastSyncAt
    });

    // Apply server changes locally
    for (const item of result.serverChanges) {
      await db.surveys.put({
        ...item,
        deleted: item.deleted ? 1 : 0
      });
    }

    await setMeta('pendingChanges', '[]');
    await setMeta('lastSyncAt', result.serverTime);

    await loadLocal();
  }

  useEffect(() => {
    loadLocal();

    const onOnline = async () => {
      setOnline(true);
      try {
        await doSync();
      } catch (e) {
        console.error(e);
      }
    };

    const onOffline = () => setOnline(false);

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    const interval = setInterval(() => {
      if (navigator.onLine) doSync().catch(() => {});
    }, 10000);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
      clearInterval(interval);
    };
  }, []);

  return (
    <div style={{ fontFamily: 'sans-serif', padding: 20, maxWidth: 800 }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Status: <strong>{online ? 'Online' : 'Offline'}</strong>
      </p>

      <div style={{ display: 'grid', gap: 8, marginBottom: 20 }}>
        <input
          placeholder="Title"
          value={form.title}
          onChange={(e) => setForm({ ...form, title: e.target.value })}
        />
        <input
          placeholder="Location"
          value={form.location}
          onChange={(e) => setForm({ ...form, location: e.target.value })}
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button onClick={addSurvey}>Save Locally</button>
        <button onClick={doSync} disabled={!online}>Sync Now</button>
      </div>

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.title}</strong> — {s.location}
            <br />
            <small>{s.notes}</small>
            <br />
            <small>{s.updatedAt}</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
