## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { fetchSurveys, postSurvey } from "./api";
import {
  getAllSurveys,
  saveSurvey,
  saveQueueItem,
  getQueueItems,
  deleteQueueItem,
  clearSurveys
} from "./db";

export default function App() {
  const [name, setName] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState("");

  useEffect(() => {
    loadLocal();

    const onOnline = async () => {
      setOnline(true);
      setStatus("Back online. Syncing...");
      await syncQueue();
      await refreshFromServer();
      setStatus("Synced.");
    };

    const onOffline = () => {
      setOnline(false);
      setStatus("Offline mode.");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function loadLocal() {
    const local = await getAllSurveys();
    setSurveys(local);
  }

  async function refreshFromServer() {
    const remote = await fetchSurveys();
    await clearSurveys();
    for (const survey of remote) {
      await saveSurvey(survey);
    }
    setSurveys(remote);
  }

  async function syncQueue() {
    const queue = await getQueueItems();
    for (const item of queue) {
      const saved = await postSurvey(item.data);
      await saveSurvey(saved);
      await deleteQueueItem(item.id);
    }
  }

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: crypto.randomUUID(),
      name,
      notes,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    await saveSurvey(survey);
    setSurveys(prev => [survey, ...prev]);

    if (navigator.onLine) {
      try {
        const saved = await postSurvey(survey);
        await saveSurvey(saved);
        setSurveys(prev =>
          prev.map(s => (s.id === survey.id ? saved : s))
        );
        setStatus("Saved and synced.");
      } catch {
        await saveQueueItem({ id: survey.id, data: survey });
        setStatus("Saved locally. Will sync later.");
      }
    } else {
      await saveQueueItem({ id: survey.id, data: survey });
      setStatus("Saved locally offline.");
    }

    setName("");
    setNotes("");
  }

  return (
    <div className="app">
      <h1>Field Survey App</h1>
      <p>Status: {online ? "Online" : "Offline"}</p>
      <p>{status}</p>

      <form onSubmit={handleSubmit} className="form">
        <input
          type="text"
          placeholder="Survey name"
          value={name}
          onChange={e => setName(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={e => setNotes(e.target.value)}
        />
        <button type="submit">Save Survey</button>
      </form>

      <h2>Local Surveys</h2>
      <ul>
        {surveys.map(s => (
          <li key={s.id}>
            <strong>{s.name}</strong> — {s.notes}
          </li>
        ))}
      </ul>
    </div>
  );
}
