### `client/app.js`
```js
import {
  saveObservation,
  getAllObservations,
  getPendingObservations,
  markSynced
} from "./db.js";

const API_URL = "http://localhost:3000";

const form = document.getElementById("surveyForm");
const list = document.getElementById("list");
const statusEl = document.getElementById("status");
const syncBtn = document.getElementById("syncBtn");

function clientId() {
  return crypto.randomUUID();
}

function updateStatus() {
  statusEl.textContent = navigator.onLine
    ? "Status: Online"
    : "Status: Offline";
}

async function renderList() {
  const records = await getAllObservations();
  list.innerHTML = records
    .map(
      (r) => `<li>
        <strong>${r.name}</strong> (${r.latitude}, ${r.longitude})
        <br/>
        ${r.notes || ""}
        <br/>
        <small>${r.synced ? "Synced" : "Pending sync"}</small>
      </li>`
    )
    .join("");
}

async function syncPending() {
  if (!navigator.onLine) {
    alert("You are offline. Sync will happen when reconnected.");
    return;
  }

  const pending = await getPendingObservations();
  if (pending.length === 0) {
    alert("No pending records.");
    return;
  }

  try {
    const res = await fetch(`${API_URL}/sync`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ records: pending })
    });

    if (!res.ok) throw new Error("Sync failed");

    const data = await res.json();
    for (const record of data.synced) {
      await markSynced(record.clientId);
    }

    await renderList();
    alert(`Synced ${data.synced.length} records.`);
  } catch (err) {
    console.error(err);
    alert("Sync error. Will retry later.");
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const record = {
    clientId: clientId(),
    name: document.getElementById("name").value,
    latitude: parseFloat(document.getElementById("latitude").value),
    longitude: parseFloat(document.getElementById("longitude").value),
    notes: document.getElementById("notes").value,
    timestamp: new Date().toISOString(),
    synced: false
  };

  await saveObservation(record);
  form.reset();
  await renderList();

  if (navigator.onLine) {
    await syncPending();
  }
});

syncBtn.addEventListener("click", syncPending);

window.addEventListener("online", async () => {
  updateStatus();
  await syncPending();
});

window.addEventListener("offline", updateStatus);

updateStatus();
renderList();
```

