const form = document.getElementById("surveyForm");
const locationInput = document.getElementById("location");
const notesInput = document.getElementById("notes");
const list = document.getElementById("list");
const statusEl = document.getElementById("status");
const syncBtn = document.getElementById("syncBtn");

function uuid() {
  return crypto.randomUUID();
}

function setStatus() {
  const online = navigator.onLine;
  statusEl.textContent = online ? "Online - ready to sync" : "Offline - saving locally";
  statusEl.className = online ? "status online" : "status offline";
}

async function render() {
  const surveys = await getAllSurveys();
  list.innerHTML = surveys.length
    ? surveys.map(item => `
      <div class="card">
        <strong>${item.location}</strong><br />
        <span>${item.notes}</span><br />
        <small>${new Date(item.createdAt).toLocaleString()} | ${item.synced ? "Synced" : "Pending sync"}</small>
      </div>
    `).join("")
    : "<p>No survey records yet.</p>";
}

async function syncPending() {
  if (!navigator.onLine) return;

  const surveys = await getAllSurveys();
  const pending = surveys.filter(s => !s.synced);

  if (!pending.length) return;

  try {
    const res = await fetch("/api/sync", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(pending)
    });

    if (!res.ok) throw new Error("Sync failed");

    for (const item of pending) {
      item.synced = true;
      await saveSurvey(item);
    }

    await render();
    setStatus();
  } catch (err) {
