## `server/index.js`

```js
import express from "express";
import cors from "cors";
import sqlite3 from "sqlite3";

const app = express();
const db = new sqlite3.Database("./surveys.db");

app.use(cors());
app.use(express.json());

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY,
      siteName TEXT NOT NULL,
      observer TEXT NOT NULL,
      notes TEXT,
      timestamp TEXT NOT NULL,
      createdAt TEXT NOT NULL
    )
  `);
});

app.get("/api/surveys", (req, res) => {
  db.all("SELECT * FROM surveys ORDER BY createdAt DESC", [], (err, rows) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json(rows);
  });
});

app.post("/api/surveys", (req, res) => {
  const { id, siteName, observer, notes, timestamp } = req.body;

  if (!id || !siteName || !observer || !timestamp) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const createdAt = new Date().toISOString();

  db.run(
    `INSERT OR IGNORE INTO surveys (id, siteName, observer, notes, timestamp, createdAt)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [id, siteName, observer, notes || "", timestamp, createdAt],
    function (err) {
      if (err) return res.status(500).json({ error: err.message });
      res.json({ success: true, inserted: this.changes === 1 });
    }
  );
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

