const API_URL = "http://localhost:3000/api/surveys";
const DB_NAME = "survey-app-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const localList = document.getElementById("localList");
const serverList = document.getElementById("serverList");
const refreshBtn = document.getElementById("refreshBtn");

let db;

function setStatus() {
  const online = navigator.onLine;
  statusEl.textContent = online ? "Online" : "Offline - changes will sync later";
  statusEl.className = `status ${online ? "online" : "offline"}`;
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
      store.createIndex("synced", "synced");
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function id() {
  return crypto.randomUUID();
}

function getAllLocal() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const req = store.getAll();

    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function saveLocal(record) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const req = store.put(record);

    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

function updateLocal(record) {
  return saveLocal(record);
}

function renderLocal(records) {
  localList.innerHTML = "";
  records.forEach((r) => {
    const li = document.createElement("li");
    li.textContent = `${r.siteName} | ${r.observer} | ${r.synced ? "Synced" : "Pending"}`;
    localList.appendChild(li);
  });
}

async function fetchServerRecords() {
  const res = await fetch(API_URL);
  const data = await res.json();
  renderServer(data);
}

function renderServer(records) {
  serverList.innerHTML = "";
  records.forEach((r) => {
    const li = document.createElement("li");
    li.textContent = `${r.siteName} | ${r.observer} | ${new Date(r.timestamp).toLocaleString()}`;
    serverList.appendChild(li);
  });
}

async function syncPending() {
  if (!navigator.onLine) return;

  const records = await getAllLocal();
  const pending = records.filter((r) => !r.synced);

  for (const record of pending) {
    try {
      await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(record)
      });

      record.synced = true;
      await updateLocal(record);
    } catch (err) {
      console.error("Sync failed:", err);
      return;
    }
  }

  await refreshUI();
}

async function refreshUI() {
  const localRecords = await getAllLocal();
  renderLocal(localRecords);

  if (navigator.onLine) {
    try {
      await fetchServerRecords();
    } catch {
      serverList.innerHTML = "<li>Unable to load server records</li>";
    }
  } else {
    serverList.innerHTML = "<li>Offline</li>";
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const record = {
    id: id(),
    siteName: document.getElementById("siteName").value.trim(),
    observer: document.getElementById("observer").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    timestamp: new Date().toISOString(),
    synced: false
  };

