  form.reset();
  await refreshUI();

  if (navigator.onLine) {
    await syncPending();
  }
});

refreshBtn.addEventListener("click", async () => {
  await refreshUI();
});

window.addEventListener("online", async () => {
  setStatus();
  await syncPending();
});

window.addEventListener("offline", setStatus);

(async function init() {
  db = await openDB();
  setStatus();
  await refreshUI();
  if (navigator.onLine) await syncPending();
})();
