```ts
import { openDB } from "idb";

const DB_NAME = "survey-app";
const DB_VERSION = 1;

export type SurveyRecord = {
  id: string;
  plotName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: number;
};

export type PendingMutation = {
  id: string;
  type: "UPSERT" | "DELETE";
  record?: SurveyRecord;
  createdAt: number;
};

export async function getDb() {
  return openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains("records")) {
        db.createObjectStore("records", { keyPath: "id" });
      }
      if (!db.objectStoreNames.contains("pending")) {
        db.createObjectStore("pending", { keyPath: "id" });
      }
      if (!db.objectStoreNames.contains("meta")) {
        db.createObjectStore("meta");
      }
    },
  });
}

export async function getAllRecords() {
  const db = await getDb();
  return db.getAll("records");
}

export async function saveRecordLocally(record: SurveyRecord) {
  const db = await getDb();
  await db.put("records", record);
}

export async function deleteRecordLocally(id: string) {
  const db = await getDb();
  await db.delete("records", id);
}

export async function addPendingMutation(mutation: PendingMutation) {
  const db = await getDb();
  await db.put("pending", mutation);
}

export async function getPendingMutations() {
  const db = await getDb();
  return db.getAll("pending");
}

export async function clearPendingMutation(id: string) {
  const db = await getDb();
  await db.delete("pending", id);
}

export async function getLastSyncTime() {
  const db = await getDb();
  return (await db.get("meta", "lastSyncTime")) ?? 0;
}

export async function setLastSyncTime(ts: number) {
  const db = await getDb();
  await db.put("meta", ts, "lastSyncTime");
}
```

