### `src/sync.ts`

```ts
import {
  getPendingMutations,
  clearPendingMutation,
  getLastSyncTime,
  setLastSyncTime,
  saveRecordLocally,
  deleteRecordLocally,
} from "./db";

const API_URL = "http://localhost:4000";

export async function syncNow() {
  const pending = await getPendingMutations();
  const lastSyncTime = await getLastSyncTime();

  if (pending.length > 0) {
    const res = await fetch(`${API_URL}/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ mutations: pending, lastSyncTime }),
    });

    if (!res.ok) throw new Error("Sync failed");

    const data = await res.json();

    for (const m of pending) {
      await clearPendingMutation(m.id);
    }

    for (const record of data.remoteChanges || []) {
      if (record.deleted) {
        await deleteRecordLocally(record.id);
      } else {
        await saveRecordLocally(record);
      }
    }

    await setLastSyncTime(data.serverTime);
  } else {
    const res = await fetch(`${API_URL}/changes?since=${lastSyncTime}`);
    if (!res.ok) throw new Error("Fetch changes failed");

    const data = await res.json();
    for (const record of data.records || []) {
      if (record.deleted) {
        await deleteRecordLocally(record.id);
      } else {
        await saveRecordLocally(record);
      }
    }
    await setLastSyncTime(data.serverTime);
  }
}
```

