### `server/index.js`

```js
const express = require("express");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

let records = []; // in-memory store
let serverTime = Date.now();

app.post("/sync", (req, res) => {
  const { mutations } = req.body;

  for (const m of mutations) {
    if (m.type === "UPSERT" && m.record) {
      const idx = records.findIndex((r) => r.id === m.record.id);
      if (idx >= 0) records[idx] = m.record;
      else records.push(m.record);
    }
    if (m.type === "DELETE" && m.record?.id) {
      records = records.filter((r) => r.id !== m.record.id);
    }
  }

  serverTime = Date.now();

  res.json({
    ok: true,
    remoteChanges: [],
    serverTime,
  });
});

app.get("/changes", (req, res) => {
  res.json({
    records,
    serverTime,
  });
});

app.listen(4000, () => {
  console.log("Sync server running on http://localhost:4000");
});
```

Run it:

```bash
node index.js
```

