## `server/index.js`

```js
import express from "express";
import cors from "cors";
import { initDB } from "./db.js";

const app = express();
app.use(cors());
app.use(express.json());

const db = await initDB();

// Get all surveys
app.get("/api/surveys", async (req, res) => {
  const rows = await db.all("SELECT * FROM surveys ORDER BY updated_at DESC");
  res.json(rows);
});

// Upsert survey
app.post("/api/surveys", async (req, res) => {
  const { id, site_name, notes, latitude, longitude, created_at, updated_at } = req.body;

  if (!id || !site_name || !created_at || !updated_at) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  await db.run(
    `
    INSERT INTO surveys (id, site_name, notes, latitude, longitude, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      site_name = excluded.site_name,
      notes = excluded.notes,
      latitude = excluded.latitude,
      longitude = excluded.longitude,
      updated_at = excluded.updated_at
    `,
    [id, site_name, notes ?? null, latitude ?? null, longitude ?? null, created_at, updated_at]
  );

  res.json({ ok: true });
});

app.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
