import { getQueue, clearQueueItem, getLocalSurveys } from "./db";

export async function syncQueue() {
  if (!navigator.onLine) return false;

  const queue = await getQueue();

  for (const item of queue) {
    try {
      await fetch("http://localhost:3001/api/surveys", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(item.payload)
      });

      await clearQueueItem(item.queueId);
    } catch (err) {
      console.error("Sync failed:", err);
      return false;
    }
  }

  return true;
}

export async function fetchRemoteSurveys() {
  const res = await fetch("http://localhost:3001/api/surveys");
  return await res.json();
}
