```jsx
import React, { useEffect, useState } from "react";
import { addToQueue, getLocalSurveys, saveSurveyLocal } from "./db";
import { syncQueue, fetchRemoteSurveys } from "./sync";

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [siteName, setSiteName] = useState("");
  const [notes, setNotes] = useState("");
  const [status, setStatus] = useState(navigator.onLine ? "Online" : "Offline");

  async function refreshLocal() {
    const local = await getLocalSurveys();
    setSurveys(local.sort((a, b) => b.updated_at.localeCompare(a.updated_at)));
  }

  async function loadData() {
    await refreshLocal();
  }

  async function createSurvey(e) {
    e.preventDefault();

    const now = new Date().toISOString();
    const survey = {
      id: crypto.randomUUID(),
      site_name: siteName,
      notes,
      latitude: null,
      longitude: null,
      created_at: now,
      updated_at: now
    };

    await saveSurveyLocal(survey);
    await addToQueue({ type: "UPSERT_SURVEY", payload: survey });

    setSiteName("");
    setNotes("");
    await refreshLocal();
  }

  async function handleSync() {
    if (!navigator.onLine) {
      setStatus("Offline");
      return;
    }

    setStatus("Syncing...");
    await syncQueue();
    const remote = await fetchRemoteSurveys();

    // Replace local view with server view after sync
    for (const survey of remote) {
      await saveSurveyLocal(survey);
    }

    await refreshLocal();
    setStatus("Online");
  }

  useEffect(() => {
    loadData();

    const onOnline = async () => {
      setStatus("Online");
      await handleSync();
    };

    const onOffline = () => setStatus("Offline");

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div className="app">
      <h1>Field Survey App</h1>
      <p>Status: <strong>{status}</strong></p>

      <form onSubmit={createSurvey} className="form">
        <input
          type="text"
          placeholder="Site name"
          value={siteName}
          onChange={(e) => setSiteName(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <button type="submit">Save Survey</button>
      </form>

      <button onClick={handleSync}>Sync Now</button>

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.site_name}</strong>
            <div>{s.notes}</div>
            <small>{s.updated_at}</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
