## 2) Backend: `server.js`

```js
const express = require("express");
const cors = require("cors");

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());
app.use(express.static("public"));

// In-memory server store
let surveys = [];
let nextId = 1;

// Return all surveys
app.get("/api/surveys", (req, res) => {
  res.json(surveys);
});

// Create or upsert a survey record
app.post("/api/surveys", (req, res) => {
  const incoming = req.body;

  // If client sent serverId, update existing
  if (incoming.serverId) {
    const idx = surveys.findIndex(s => s.serverId === incoming.serverId);
    if (idx >= 0) {
      surveys[idx] = {
        ...surveys[idx],
        ...incoming,
        updatedAt: new Date().toISOString(),
      };
      return res.json(surveys[idx]);
    }
  }

  const record = {
    serverId: String(nextId++),
    ...incoming,
    updatedAt: new Date().toISOString(),
  };

  surveys.push(record);
  res.status(201).json(record);
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

