## 4) Frontend logic: `public/app.js`

```js
const API_URL = "http://localhost:3000/api/surveys";
const DB_NAME = "surveyDB";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

let db;

// ---------- IndexedDB helpers ----------
function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const database = request.result;
      if (!database.objectStoreNames.contains(STORE_NAME)) {
        const store = database.createObjectStore(STORE_NAME, { keyPath: "localId" });
        store.createIndex("synced", "synced", { unique: false });
      }
    };

    request.onsuccess = () => {
      db = request.result;
      resolve(db);
    };

    request.onerror = () => reject(request.error);
  });
}

function addLocalSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function getLocalSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const req = store.getAll();

    req.onsuccess = () => resolve(req.result || []);
    req.onerror = () => reject(req.error);
  });
}

function updateLocalSurvey(survey) {
  return addLocalSurvey(survey);
}

// ---------- UI ----------
const statusEl = document.getElementById("status");
const surveyListEl = document.getElementById("surveyList");
const form = document.getElementById("surveyForm");
const syncBtn = document.getElementById("syncBtn");

function setStatus(online) {
  statusEl.textContent = online ? "Online" : "Offline";
  statusEl.className = `status ${online ? "online" : "offline"}`;
}

function renderSurveys(surveys) {
  surveyListEl.innerHTML = "";
  surveys.sort((a, b) => (b.createdAt || "").localeCompare(a.createdAt || ""));

  for (const s of surveys) {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${s.siteName}</strong><br/>
      Lat: ${s.lat}, Lng: ${s.lng}<br/>
      ${s.notes ? `<em>${s.notes}</em><br/>` : ""}
      <small>${s.synced ? "Synced" : "Pending sync"} | ${s.createdAt}</small>
    `;
    surveyListEl.appendChild(li);
  }
}

async function refreshLocalList() {
  const surveys = await getLocalSurveys();
  renderSurveys(surveys);
}

// ---------- Sync ----------
async function syncPendingSurveys() {
  if (!navigator.onLine) {
    setStatus(false);
    return;
  }

  const localSurveys = await getLocalSurveys();
  const pending = localSurveys.filter(s => !s.synced);

  for (const survey of pending) {
    try {
      const response = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey),
      });

      if (!response.ok) throw new Error("Sync failed");

      const saved = await response.json();
      await updateLocalSurvey({
        ...survey,
        synced: true,
        serverId: saved.serverId,
        updatedAt: saved.updatedAt,
      });
    } catch (err) {
      console.error("Failed to sync survey:", err);
    }
  }

  await refreshLocalList();
}

async function pullServerSurveys() {
  if (!navigator.onLine) return;

  try {
    const response = await fetch(API_URL);
    if (!response.ok) throw new Error("Fetch failed");

    const serverSurveys = await response.json();
    const localSurveys = await getLocalSurveys();
    const localByServerId = new Map(
      localSurveys.filter(s => s.serverId).map(s => [s.serverId, s])
    );

    for (const serverSurvey of serverSurveys) {
      const existing = localByServerId.get(serverSurvey.serverId);
      if (!existing) {
        await addLocalSurvey({
          ...serverSurvey,
          localId: crypto.randomUUID(),
          synced: true,
        });
      }
    }
  } catch (err) {
    console.error("Failed to pull surveys:", err);
  }

  await refreshLocalList();
}

// ---------- Form submit ----------
form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    localId: crypto.randomUUID(),
    serverId: null,
    siteName: document.getElementById("siteName").value.trim(),
    lat: Number(document.getElementById("lat").value),
    lng: Number(document.getElementById("lng").value),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    synced: false,
  };

  await addLocalSurvey(survey);
  form.reset();
  await refreshLocalList();

  if (navigator.onLine) {
    await syncPendingSurveys();
  }
});

syncBtn.addEventListener("click", syncPendingSurveys);

window.addEventListener("online", async () => {
  setStatus(true);
  await syncPendingSurveys();
  await pullServerSurveys();
});

window.addEventListener("offline", () => setStatus(false));

// ---------- Init ----------
(async function init() {
  await openDB();
  setStatus(navigator.onLine);
  await refreshLocalList();
  if (navigator.onLine) {
    await pullServerSurveys();
    await syncPendingSurveys();
  }
})();
```

