## `server/db.js`

```js
import sqlite3 from "sqlite3";

const db = new sqlite3.Database("./survey.db");

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY,
      siteName TEXT NOT NULL,
      observerName TEXT NOT NULL,
      notes TEXT,
      createdAt TEXT NOT NULL,
      updatedAt TEXT NOT NULL
    )
  `);
});

export function upsertSurvey(survey) {
  return new Promise((resolve, reject) => {
    const stmt = db.prepare(`
      INSERT INTO surveys (id, siteName, observerName, notes, createdAt, updatedAt)
      VALUES (?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        siteName=excluded.siteName,
        observerName=excluded.observerName,
        notes=excluded.notes,
        createdAt=excluded.createdAt,
        updatedAt=excluded.updatedAt
    `);

    stmt.run(
      survey.id,
      survey.siteName,
      survey.observerName,
      survey.notes || "",
      survey.createdAt,
      survey.updatedAt,
      function (err) {
        if (err) reject(err);
        else resolve({ ok: true, id: survey.id });
      }
    );

    stmt.finalize();
  });
}

export function getAllSurveys() {
  return new Promise((resolve, reject) => {
    db.all("SELECT * FROM surveys ORDER BY createdAt DESC", [], (err, rows) => {
      if (err) reject(err);
      else resolve(rows);
    });
  });
}
```

