```js
import localforage from "localforage";

const surveysStore = localforage.createInstance({
  name: "surveyApp",
  storeName: "surveys"
});

const queueStore = localforage.createInstance({
  name: "surveyApp",
  storeName: "queue"
});

export async function saveSurveyLocal(survey) {
  await surveysStore.setItem(survey.id, survey);
}

export async function getAllLocalSurveys() {
  const items = [];
  await surveysStore.iterate((value) => {
    items.push(value);
  });
  return items.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
}

export async function enqueueMutation(survey) {
  const queue = (await queueStore.getItem("pending")) || [];
  queue.push(survey);
  await queueStore.setItem("pending", queue);
}

export async function getPendingMutations() {
  return (await queueStore.getItem("pending")) || [];
}

export async function clearPendingMutations() {
  await queueStore.setItem("pending", []);
}
```

