## `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import {
  saveSurveyLocal,
  getAllLocalSurveys,
  enqueueMutation,
  getPendingMutations,
  clearPendingMutations
} from "./db";
import { syncSurveys, healthCheck } from "./api";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [siteName, setSiteName] = useState("");
  const [observerName, setObserverName] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [pendingCount, setPendingCount] = useState(0);
  const [online, setOnline] = useState(navigator.onLine);
  const [message, setMessage] = useState("");

  async function refreshData() {
    const localSurveys = await getAllLocalSurveys();
    const pending = await getPendingMutations();
    setSurveys(localSurveys);
    setPendingCount(pending.length);
  }

  async function trySync() {
    const pending = await getPendingMutations();
    if (pending.length === 0) return;

    try {
      await syncSurveys(pending);
      await clearPendingMutations();
      setMessage(`Synced ${pending.length} record(s).`);
    } catch {
      setMessage("Sync deferred: still offline or server unavailable.");
    }

    await refreshData();
  }

  async function handleSave(e) {
    e.preventDefault();

    const survey = {
      id: uuid(),
      siteName,
      observerName,
      notes,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    await saveSurveyLocal(survey);
    await enqueueMutation(survey);

    setSiteName("");
    setObserverName("");
    setNotes("");

    setMessage("Saved locally. Will sync when online.");
    await refreshData();

    if (navigator.onLine) {
      await trySync();
    }
  }

  useEffect(() => {
    refreshData();

    const onOnline = async () => {
      setOnline(true);
      setMessage("Back online. Syncing...");
      const canReachServer = await healthCheck().catch(() => false);
      if (canReachServer) await trySync();
      await refreshData();
    };

    const onOffline = () => {
      setOnline(false);
      setMessage("Offline mode enabled.");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 720, margin: "2rem auto" }}>
      <h1>Offline Field Survey App</h1>
      <p>Status: {online ? "Online" : "Offline"}</p>
      <p>Pending sync: {pendingCount}</p>
      {message && <p><strong>{message}</strong></p>}

      <form onSubmit={handleSave} style={{ display: "grid", gap: "0.75rem" }}>
        <input
          value={siteName}
          onChange={(e) => setSiteName(e.target.value)}
          placeholder="Site name"
          required
        />
        <input
          value={observerName}
          onChange={(e) => setObserverName(e.target.value)}
          placeholder="Observer name"
          required
        />
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Notes"
          rows={4}
        />
        <button type="submit">Save Survey</button>
      </form>

      <hr />

      <h2>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.siteName}</strong> — {s.observerName}
            <br />
            <small>{s.createdAt}</small>
            <br />
            <span>{s.notes}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

