```js
import { saveSurvey, getAllSurveys, getPendingSurveys, markSynced } from "./db.js";

const statusEl = document.getElementById("status");
const listEl = document.getElementById("surveyList");
const saveBtn = document.getElementById("saveBtn");
const syncBtn = document.getElementById("syncBtn");

function setStatus() {
  statusEl.textContent = navigator.onLine
    ? "Online"
    : "Offline: changes will be stored locally and synced later";
}

function renderSurveys(surveys) {
  listEl.innerHTML = "";
  for (const s of surveys) {
    const li = document.createElement("li");
    li.textContent = `${s.siteName} - ${s.notes} ${s.synced ? "(synced)" : "(pending)"}`;
    listEl.appendChild(li);
  }
}

async function refresh() {
  const surveys = await getAllSurveys();
  renderSurveys(surveys);
  setStatus();
}

async function syncPending() {
  if (!navigator.onLine) return;

  const pending = await getPendingSurveys();
  if (!pending.length) return;

  const response = await fetch("/api/surveys/sync", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ records: pending })
  });

  if (response.ok) {
    for (const record of pending) {
      await markSynced(record.clientId);
    }
    await refresh();
  }
}

saveBtn.addEventListener("click", async () => {
  const siteName = document.getElementById("siteName").value.trim();
  const notes = document.getElementById("notes").value.trim();

  if (!siteName) return;

  const survey = {
    clientId: crypto.randomUUID(),
    siteName,
    notes,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurvey(survey);
  document.getElementById("siteName").value = "";
  document.getElementById("notes").value = "";
  await refresh();

  if (navigator.onLine) {
    await syncPending();
  }
});

syncBtn.addEventListener("click", syncPending);

window.addEventListener("online", syncPending);
window.addEventListener("offline", setStatus);

if ("serviceWorker" in navigator) {
  navigator.serviceWorker.register("./sw.js");
}

refresh();
