## `public/app.js`

```js
const API_URL = ""; // same origin

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const pendingList = document.getElementById("pendingList");
const syncedList = document.getElementById("syncedList");
const syncBtn = document.getElementById("syncBtn");

const DB_NAME = "survey-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function getAllSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const req = store.getAll();
    req.onsuccess = () => resolve(req.result || []);
    req.onerror = () => reject(req.error);
  });
}

async function saveSurvey(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const req = store.put(survey);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

async function deleteSurvey(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const req = store.delete(id);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

function setStatus() {
  if (navigator.onLine) {
    statusEl.textContent = "Online: ready to sync";
    statusEl.className = "status online";
  } else {
    statusEl.textContent = "Offline: entries will be saved locally";
    statusEl.className = "status offline";
  }
}

function renderSurveyLists(all) {
  const pending = all.filter((s) => !s.synced);
  const synced = all.filter((s) => s.synced);

  pendingList.innerHTML = pending.length
    ? pending.map(item => `<li><strong>${item.name}</strong> — ${item.notes || ""}</li>`).join("")
    : "<li>No pending surveys</li>";

  syncedList.innerHTML = synced.length
    ? synced.map(item =>
        `<li><strong>${item.name}</strong> — ${item.notes || ""} <small>(synced)</small></li>`
      ).join("")
    : "<li>No synced surveys</li>";
}

async function refreshUI() {
  const all = await getAllSurveys();
  renderSurveyLists(all);
  setStatus();
}

async function syncPending() {
  if (!navigator.onLine) {
    setStatus();
    return;
  }

  const all = await getAllSurveys();
  const pending = all.filter((s) => !s.synced);

  for (const survey of pending) {
    try {
      const res = await fetch(`${API_URL}/api/surveys`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await deleteSurvey(survey.id);
        await saveSurvey({ ...survey, synced: true, syncedAt: new Date().toISOString() });
        await deleteSurvey(survey.id);
        await saveSurvey({ ...survey, synced: true, syncedAt: new Date().toISOString() });
      }
    } catch (e) {
      // stop syncing if network fails again
      break;
    }
  }

  await refreshUI();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    latitude: document.getElementById("lat").value ? Number(document.getElementById("lat").value) : null,
    longitude: document.getElementById("lng").value ? Number(document.getElementById("lng").value) : null,
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveSurvey(survey);
  form.reset();
  await refreshUI();

  if (navigator.onLine) {
    await syncPending();
  }
});

syncBtn.addEventListener("click", syncPending);

window.addEventListener("online", syncPending);
window.addEventListener("offline", setStatus);

(async function init() {
  await refreshUI();
  if (navigator.onLine) {
    await syncPending();
  }
})();
```

