### `client/db.js`

```js
const DB_NAME = "survey-app";
const DB_VERSION = 1;
const SURVEYS_STORE = "surveys";
const OUTBOX_STORE = "outbox";
const META_STORE = "meta";

export function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains(SURVEYS_STORE)) {
        db.createObjectStore(SURVEYS_STORE, { keyPath: "localId" });
      }

      if (!db.objectStoreNames.contains(OUTBOX_STORE)) {
        db.createObjectStore(OUTBOX_STORE, { keyPath: "id" });
      }

      if (!db.objectStoreNames.contains(META_STORE)) {
        db.createObjectStore(META_STORE, { keyPath: "key" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function tx(db, storeName, mode = "readonly") {
  return db.transaction(storeName, mode).objectStore(storeName);
}

export async function getAllSurveys(db) {
  return new Promise((resolve, reject) => {
    const req = tx(db, SURVEYS_STORE).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export async function saveSurveyLocal(db, survey) {
  return new Promise((resolve, reject) => {
    const req = tx(db, SURVEYS_STORE, "readwrite").put(survey);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

export async function addToOutbox(db, item) {
  return new Promise((resolve, reject) => {
    const req = tx(db, OUTBOX_STORE, "readwrite").put(item);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

export async function getOutbox(db) {
  return new Promise((resolve, reject) => {
    const req = tx(db, OUTBOX_STORE).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

export async function removeFromOutbox(db, id) {
  return new Promise((resolve, reject) => {
    const req = tx(db, OUTBOX_STORE, "readwrite").delete(id);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

export async function getMeta(db, key) {
  return new Promise((resolve, reject) => {
    const req = tx(db, META_STORE).get(key);
    req.onsuccess = () => resolve(req.result?.value ?? null);
    req.onerror = () => reject(req.error);
  });
}

export async function setMeta(db, key, value) {
  return new Promise((resolve, reject) => {
    const req = tx(db, META_STORE, "readwrite").put({ key, value });
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}
```

