      const li = document.createElement("li");
      li.textContent = `${item.fieldName}: ${item.value} ${
        item.synced ? "(synced)" : "(pending)"
      }`;
      surveyList.appendChild(li);
    });
}

async function refreshLocalView() {
  const surveys = await getAllSurveys(db);
  render(surveys);
}

async function syncOutbox() {
  if (!navigator.onLine) return;

  const outbox = await getOutbox(db);

  for (const item of outbox) {
    try {
      const res = await fetch(`${API_BASE}/surveys`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(item.payload)
      });

      if (!res.ok) throw new Error("Failed to sync item");

      const saved = await res.json();

      await saveSurveyLocal(db, {
        localId: item.payload.clientId,
        ...item.payload,
        synced: true,
        serverId: saved.id,
        createdAt: item.createdAt
      });

      await removeFromOutbox(db, item.id);
    } catch (err) {
      console.error("Sync error:", err);
      break;
    }
  }

  await setMeta(db, "lastSync", Date.now());
  updateStatus();
  await refreshLocalView();
}

async function pullFromServer() {
  if (!navigator.onLine) return;

  const since = (await getMeta(db, "serverLastUpdated")) || 0;
  const res = await fetch(`${API_BASE}/surveys?since=${since}`);
  if (!res.ok) return;

  const data = await res.json();

  for (const s of data.surveys) {
    await saveSurveyLocal(db, {
      localId: s.clientId,
      ...s,
      synced: true,
      createdAt: s.updatedAt
    });
  }

  await setMeta(db, "serverLastUpdated", data.lastUpdated || since);
  await refreshLocalView();
}

async function syncAll() {
  await syncOutbox();
  await pullFromServer();
}

function updateStatus() {
  netStatus.textContent = navigator.onLine ? "Online" : "Offline";
  getMeta(db, "lastSync").then(ts => {
    lastSync.textContent = ts ? new Date(ts).toLocaleString() : "Never";
  });
}

surveyForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const payload = {
    clientId: uuid(),
    fieldName: document.getElementById("fieldName").value.trim(),
    value: document.getElementById("value").value.trim(),
    latitude: null,
    longitude: null
  };

  const localRecord = {
    localId: payload.clientId,
    ...payload,
    synced: false,
    createdAt: Date.now()
  };

  await saveSurveyLocal(db, localRecord);
  await addToOutbox(db, {
    id: payload.clientId,
    payload,
    createdAt: localRecord.createdAt
  });

  surveyForm.reset();
  await refreshLocalView();
  await syncAll();
});

window.addEventListener("online", () => {
  updateStatus();
  syncAll();
});

window.addEventListener("offline", updateStatus);

(async function init() {
  db = await openDB();
  updateStatus();
  await refreshLocalView();

  if (navigator.onLine) {
    await syncAll();
  }
})();
```

