```js
import express from "express";
import cors from "cors";
import fs from "fs/promises";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DB_FILE = path.join(__dirname, "db.json");

const app = express();
app.use(cors());
app.use(express.json());

async function readDB() {
  const raw = await fs.readFile(DB_FILE, "utf-8");
  return JSON.parse(raw);
}

async function writeDB(data) {
  await fs.writeFile(DB_FILE, JSON.stringify(data, null, 2));
}

app.get("/api/surveys", async (req, res) => {
  const db = await readDB();
  res.json(db.surveys);
});

app.post("/api/surveys/sync", async (req, res) => {
  const { changes } = req.body; // array of upserts

  const db = await readDB();
  const map = new Map(db.surveys.map(s => [s.id, s]));

  for (const item of changes) {
    map.set(item.id, item);
  }

  db.surveys = Array.from(map.values());
  await writeDB(db);

  res.json({
    ok: true,
    synced: changes.length,
    surveys: db.surveys
  });
});

const PORT = process.env.PORT || 3001;
app.listen(PORT, () => {
  console.log(`Survey API running on http://localhost:${PORT}`);
});
```

