```js
import { openDB } from "idb";

const DB_NAME = "survey-offline-db";
const DB_VERSION = 1;

export const dbPromise = openDB(DB_NAME, DB_VERSION, {
  upgrade(db) {
    db.createObjectStore("surveys", { keyPath: "id" });
    db.createObjectStore("outbox", { keyPath: "id", autoIncrement: true });
  }
});

export async function getAllSurveys() {
  return (await dbPromise).getAll("surveys");
}

export async function saveSurvey(survey) {
  return (await dbPromise).put("surveys", survey);
}

export async function addToOutbox(change) {
  return (await dbPromise).add("outbox", change);
}

export async function getOutbox() {
  return (await dbPromise).getAll("outbox");
}

export async function clearOutbox() {
  const db = await dbPromise;
  const tx = db.transaction("outbox", "readwrite");
  await tx.store.clear();
  await tx.done;
}
```

## `client/src/sync.js`
```js
import { getOutbox, clearOutbox } from "./db";

const API = "http://localhost:3001/api";

export async function syncNow() {
  if (!navigator.onLine) return { ok: false, reason: "offline" };

  const changes = await getOutbox();
  if (changes.length === 0) return { ok: true, synced: 0 };

  const res = await fetch(`${API}/surveys/sync`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ changes: changes.map(c => c.survey) })
  });

  if (!res.ok) throw new Error("Sync failed");

  await clearOutbox();
  return res.json();
}
```

