```js
import express from "express";
import cors from "cors";

const app = express();
app.use(cors());
app.use(express.json());

let surveys = []; // in-memory for minimal demo

app.get("/surveys", (req, res) => {
  res.json(surveys);
});

app.post("/sync", (req, res) => {
  const incoming = req.body.records || [];

  for (const record of incoming) {
    const idx = surveys.findIndex((s) => s.id === record.id);

    if (idx === -1) {
      surveys.push(record);
    } else {
      // last-write-wins based on updatedAt
      if (new Date(record.updatedAt) > new Date(surveys[idx].updatedAt)) {
        surveys[idx] = record;
      }
    }
  }

  res.json({ ok: true, count: incoming.length });
});

app.listen(3001, () => {
  console.log("Survey server listening on http://localhost:3001");
});
