## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { surveyStore } from "./db";
import { fetchSurveys, syncSurveys } from "./api";

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [serverStatus, setServerStatus] = useState("unknown");
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");

  async function loadLocal() {
    const items = [];
    await surveyStore.iterate((value) => items.push(value));
    setSurveys(items.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt)));
  }

  async function loadRemoteAndMerge() {
    if (!navigator.onLine) {
      setServerStatus("offline");
      return;
    }
    try {
      const remote = await fetchSurveys();
      setServerStatus("online");

      // Merge remote into local if newer or missing
      for (const r of remote) {
        const local = await surveyStore.getItem(r.id);
        if (!local || new Date(r.updatedAt) > new Date(local.updatedAt)) {
          await surveyStore.setItem(r.id, r);
        }
      }
      await loadLocal();
    } catch {
      setServerStatus("offline");
    }
  }

  async function saveSurvey() {
    const record = {
      id: crypto.randomUUID(),
      name,
      location,
      updatedAt: new Date().toISOString(),
      synced: false,
    };

    await surveyStore.setItem(record.id, record);
    setName("");
    setLocation("");
    await loadLocal();
  }

  async function syncLocalUnsynced() {
    if (!navigator.onLine) return;

    const unsynced = [];
    await surveyStore.iterate((value) => {
      if (!value.synced) unsynced.push(value);
    });

    if (unsynced.length === 0) return;

    await syncSurveys(unsynced);

    for (const item of unsynced) {
      await surveyStore.setItem(item.id, { ...item, synced: true });
    }

    await loadLocal();
  }

  useEffect(() => {
    loadLocal();
    loadRemoteAndMerge();
  }, []);

  useEffect(() => {
    function handleOnline() {
      setServerStatus("online");
      loadRemoteAndMerge().then(syncLocalUnsynced);
    }

    function handleOffline() {
      setServerStatus("offline");
    }

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  async function handleManualSync() {
    await loadRemoteAndMerge();
    await syncLocalUnsynced();
  }

  return (
    <div style={{ fontFamily: "sans-serif", padding: 20, maxWidth: 700 }}>
      <h1>Offline Survey App</h1>
      <p>Status: <b>{serverStatus}</b></p>

      <div style={{ marginBottom: 16 }}>
        <input
          placeholder="Survey name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          style={{ marginRight: 8 }}
        />
        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          style={{ marginRight: 8 }}
        />
        <button onClick={saveSurvey}>Save offline</button>
      </div>

      <button onClick={handleManualSync}>Sync now</button>

      <h2>Saved surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <b>{s.name}</b> — {s.location}{" "}
            <small>
              ({s.synced ? "synced" : "pending"} | {s.updatedAt})
            </small>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

