## 3. Mobile app

### `app/db.js`
Local SQLite storage.

```js
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export function initDb() {
  db.transaction(tx => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id TEXT PRIMARY KEY NOT NULL,
        name TEXT,
        notes TEXT,
        latitude REAL,
        longitude REAL,
        createdAt TEXT,
        synced INTEGER DEFAULT 0
      );`
    );
  });
}

export function insertSurvey(survey) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (id, name, notes, latitude, longitude, createdAt, synced)
         VALUES (?, ?, ?, ?, ?, ?, ?);`,
        [
          survey.id,
          survey.name,
          survey.notes,
          survey.latitude,
          survey.longitude,
          survey.createdAt,
          survey.synced ? 1 : 0,
        ],
        (_, result) => resolve(result),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getPendingSurveys() {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE synced = 0;`,
        [],
        (_, { rows }) => resolve(rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function markSurveySynced(id) {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys SET synced = 1 WHERE id = ?;`,
        [id],
        (_, result) => resolve(result),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getAllSurveys() {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys ORDER BY createdAt DESC;`,
        [],
        (_, { rows }) => resolve(rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
```

