    await insertSurvey(survey);
    setName('');
    setNotes('');
    await loadSurveys();
  }

  useEffect(() => {
    initDb();
    loadSurveys();
    startSyncListener();
  }, []);

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Offline Field Survey</Text>

