```js
import express from "express";
import cors from "cors";
import fs from "fs";

const app = express();
const PORT = 4000;
const DB_FILE = "./db.json";

app.use(cors());
app.use(express.json());

function readDB() {
  return JSON.parse(fs.readFileSync(DB_FILE, "utf-8"));
}

function writeDB(data) {
  fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));
}

// Get all surveys
app.get("/surveys", (req, res) => {
  const db = readDB();
  res.json(db.surveys);
});

// Upsert a survey
app.post("/surveys", (req, res) => {
  const incoming = req.body;
  const db = readDB();

  const idx = db.surveys.findIndex((s) => s.id === incoming.id);

  if (idx === -1) {
    db.surveys.push(incoming);
    writeDB(db);
    return res.status(201).json(incoming);
  }

  // conflict handling: prefer latest updatedAt
  const existing = db.surveys[idx];
  if (new Date(incoming.updatedAt) > new Date(existing.updatedAt)) {
    db.surveys[idx] = incoming;
    writeDB(db);
    return res.json(incoming);
  }

  return res.status(409).json({
    message: "Conflict: server has newer data",
    serverRecord: existing
  });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

