## `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import { fetchSurveys, postSurvey } from "./api";
import { getLocalSurveys, saveLocalSurveys } from "./db";

function makeSurvey({ location, notes }) {
  return {
    id: crypto.randomUUID(),
    location,
    notes,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    synced: false
  };
}

export default function App() {
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState("");

  useEffect(() => {
    const updateOnline = () => setOnline(navigator.onLine);
    window.addEventListener("online", updateOnline);
    window.addEventListener("offline", updateOnline);

    loadAll();

    return () => {
      window.removeEventListener("online", updateOnline);
      window.removeEventListener("offline", updateOnline);
    };
  }, []);

  async function loadAll() {
    const local = await getLocalSurveys();
    setSurveys(local);
  }

  async function handleAdd() {
    if (!location.trim()) return;

    const survey = makeSurvey({ location, notes });
    const updated = [...surveys, survey];
    setSurveys(updated);
    await saveLocalSurveys(updated);
    setLocation("");
    setNotes("");
    setStatus("Saved offline");
  }

  async function syncNow() {
    try {
      const local = await getLocalSurveys();
      let merged = [...local];

      for (let i = 0; i < merged.length; i++) {
        const item = merged[i];
        if (item.synced) continue;

        const result = await postSurvey(item);

        if (result.status === 201 || result.status === 200) {
          merged[i] = { ...item, synced: true };
        } else if (result.status === 409) {
          merged[i] = result.data.serverRecord;
        }
      }

      await saveLocalSurveys(merged);
      setSurveys(merged);

      if (online) {
        const serverSurveys = await fetchSurveys();
        setStatus(`Synced. Server has ${serverSurveys.length} records.`);
      } else {
        setStatus("Offline: sync skipped");
      }
    } catch (err) {
      setStatus(`Sync failed: ${err.message}`);
    }
  }

  useEffect(() => {
    if (online) syncNow();
  }, [online]);

  return (
    <div style={{ maxWidth: 700, margin: "2rem auto", fontFamily: "sans-serif" }}>
      <h1>Field Survey App</h1>
      <p>
        Status: <strong>{online ? "Online" : "Offline"}</strong>
      </p>

      <div style={{ display: "grid", gap: "0.75rem", marginBottom: "1rem" }}>
        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
        />
        <textarea
          placeholder="Survey notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <button onClick={handleAdd}>Save Survey Offline</button>
        <button onClick={syncNow}>Sync Now</button>
      </div>

      <p>{status}</p>

      <h2>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.location}</strong> — {s.notes}{" "}
            {s.synced ? "(synced)" : "(pending)"}
          </li>
        ))}
      </ul>
    </div>
  );
}
```

