## `backend/src/socket.js`

```js
import jwt from "jsonwebtoken";
import { prisma } from "./server.js";

export function setupSocket(io) {
  io.use(async (socket, next) => {
    try {
      const token = socket.handshake.auth?.token;
      if (!token) return next(new Error("No token"));
      const payload = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = payload;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", async (socket) => {
    const userId = socket.user.id;

    await prisma.socketSession.create({
      data: { userId, socketId: socket.id }
    });

    socket.join(`user:${userId}`);

    socket.on("message:send", async ({ recipientId, content }) => {
      const message = await prisma.message.create({
        data: {
          content,
          senderId: userId,
          recipientId
        }
      });

      const notification = await prisma.notification.create({
        data: {
          userId: recipientId,
          type: "message",
          title: "New message",
          body: content.slice(0, 100)
        }
      });

      io.to(`user:${recipientId}`).emit("message:received", message);
      io.to(`user:${recipientId}`).emit("notification:new", notification);
      socket.emit("message:sent", message);
    });

    socket.on("disconnect", async () => {
      await prisma.socketSession.deleteMany({
        where: { socketId: socket.id }
      });
    });
  });
}
```

