import { useEffect, useState } from "react";
import { fetchMessages } from "../api.js";

export default function Chat({ socket, token, recipientId }) {
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    fetchMessages(token, recipientId).then(setMessages);

    socket.on("message:received", (msg) => {
      if (msg.senderId === recipientId) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => socket.off("message:received");
  }, [socket, token, recipientId]);

  const sendMessage = () => {
    socket.emit("message:send", { recipientId, content: text });
    setText("");
  };

  return (
    <div>
      <div style={{ height: 300, overflow: "auto", border: "1px solid #ccc" }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.senderId === recipientId ? "Them" : "You"}:</strong> {m.content}
          </div>
        ))}
      </div>

      <input value={text} onChange={(e) => setText(e.target.value)} />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
