## 6) Stripe webhook example

If you want subscription state to update automatically:

### Add to `server/src/index.js`

```js
import express from 'express';
import { stripe } from './config/stripe.js';
import { markUserPremium } from './services/billingService.js';

app.post('/api/billing/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];

  let event;
  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const userId = session.metadata.userId;

    await markUserPremium(userId, session.customer, session.subscription);
  }

  res.json({ received: true });
});
```

