## `server/src/routes/chat.routes.js`

```js
import express from "express";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";
import User from "../models/User.js";
import { authMiddleware } from "../middleware/auth.js";

export default function chatRoutes(io) {
  const router = express.Router();

  router.get("/conversations/:userId", authMiddleware, async (req, res) => {
    const me = req.user.id;
    const other = req.params.userId;

    const messages = await Message.find({
      $or: [
        { fromUser: me, toUser: other },
        { fromUser: other, toUser: me }
      ]
    }).sort({ createdAt: 1 });

    res.json(messages);
  });

  router.post("/send", authMiddleware, async (req, res) => {
    const { toUserId, text } = req.body;

    const msg = await Message.create({
      fromUser: req.user.id,
      toUser: toUserId,
      text
    });

    const notification = await Notification.create({
      user: toUserId,
      type: "message",
      title: "New message",
      body: text.slice(0, 80)
    });

    io.to(toUserId).emit("new_message", msg);
    io.to(toUserId).emit("new_notification", notification);

    res.json(msg);
  });

  router.get("/users", authMiddleware, async (req, res) => {
    const users = await User.find({ _id: { $ne: req.user.id } }).select("username email isPremium");
    res.json(users);
  });

  return router;
}
```

