        price_data: {
          currency: "usd",
          product_data: { name: "Premium Membership" },
          unit_amount: 999
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/chat?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/chat?canceled=1`,
    metadata: { userId }
  });

