## `server/src/socket.ts`

```ts
import { Server } from "socket.io";
import jwt from "jsonwebtoken";

export function setupSocket(server: any) {
  const io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_URL,
      methods: ["GET", "POST"]
    }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const user = jwt.verify(token, process.env.JWT_SECRET!) as any;
      (socket as any).user = user;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const user = (socket as any).user;
    socket.join(user.id);

    socket.on("message:send", (payload) => {
      io.to(payload.receiverId).emit("message:new", payload);
      io.to(payload.receiverId).emit("notification:new", {
        type: "MESSAGE",
        title: "New message",
        body: `${user.username} sent you a message`
      });
    });

    socket.on("monetization:purchase", (payload) => {
      io.to(user.id).emit("notification:new", {
        type: "PURCHASE",
        title: "Purchase successful",
        body: `You purchased ${payload.itemName}`
      });
    });
  });

  return io;
}
```

