import { useEffect, useState } from "react";
import { api } from "../api";
import { createSocket } from "../socket";

export default function ChatWindow() {
  const [receiverId, setReceiverId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState<any[]>([]);
  const user = JSON.parse(localStorage.getItem("user") || "{}");

  useEffect(() => {
    const socket = createSocket();

    socket.on("message:new", (msg) => {
      setMessages(prev => [...prev, msg]);
    });

    socket.on("notification:new", (n) => {
      alert(`${n.title}: ${n.body}`);
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  const loadMessages = async () => {
    const data = await api(`/messages/${receiverId}`);
    setMessages(data);
  };

  const send = async () => {
    const payload = { receiverId, content };
    await api("/messages", {
      method: "POST",
      body: JSON.stringify(payload)
    });
    setMessages(prev => [...prev, { ...payload, senderId: user.id }]);
    setContent("");
  };

  return (
    <div>
      <h3>Chat</h3>
      <input
        placeholder="receiver user id"
        value={receiverId}
        onChange={e => setReceiverId(e.target.value)}
      />
      <button onClick={loadMessages}>Load</button>

      <div style={{ minHeight: 200, border: "1px solid #ddd", marginTop: 12 }}>
        {messages.map((m, i) => (
          <div key={i}>
            <strong>{m.senderId === user.id ? "Me" : "Them"}:</strong> {m.content}
          </div>
        ))}
      </div>

      <input value={content} onChange={e => setContent(e.target.value)} placeholder="message..." />
      <button onClick={send}>Send</button>
    </div>
  );
}
