# 7) Real-time Socket.IO server

> In production, run this as a separate server or integrate with a custom server. For demo purposes, this is the socket layer.

## `server/socket-server.ts`

```ts
import { Server } from "socket.io";
import { prisma } from "@/lib/db";

export function initSocket(httpServer: any) {
  const io = new Server(httpServer, {
    cors: {
      origin: process.env.NEXT_PUBLIC_APP_URL,
      credentials: true
    }
  });

  io.on("connection", (socket) => {
    console.log("socket connected:", socket.id);

    socket.on("join", (userId: string) => {
      socket.join(userId);
    });

    socket.on("send_message", async (data) => {
      const { senderId, receiverId, content } = data;

      const message = await prisma.message.create({
        data: { senderId, receiverId, content }
      });

      await prisma.notification.create({
        data: {
          userId: receiverId,
          type: "MESSAGE",
          content: `New message from ${senderId}`
        }
      });

      io.to(receiverId).emit("new_message", message);
      io.to(receiverId).emit("new_notification", {
        type: "MESSAGE",
        content: `New message from ${senderId}`
      });
    });

    socket.on("tip_user", async (data) => {
      const { senderId, receiverId, amount } = data; // cents

      const senderWallet = await prisma.wallet.findUnique({
        where: { userId: senderId }
      });

      if (!senderWallet || senderWallet.balance < amount) {
        socket.emit("tip_error", { message: "Insufficient balance" });
        return;
      }

      await prisma.$transaction([
        prisma.wallet.update({
          where: { userId: senderId },
          data: { balance: { decrement: amount } }
        }),
        prisma.wallet.update({
          where: { userId: receiverId },
          data: { balance: { increment: amount } }
        }),
        prisma.transaction.create({
          data: {
            walletId: senderWallet.id,
            amount,
            type: "DEBIT",
            reference: `tip:${receiverId}`
          }
        })
      ]);

      await prisma.notification.create({
        data: {
          userId: receiverId,
          type: "TIP",
          content: `You received a tip of $${(amount / 100).toFixed(2)}`
        }
      });

      io.to(receiverId).emit("new_notification", {
        type: "TIP",
        content: `You received a tip of $${(amount / 100).toFixed(2)}`
      });
    });

    socket.on("disconnect", () => {
      console.log("socket disconnected:", socket.id);
    });
  });

  return io;
}
```

