## 2) Backend: Prisma schema

**`server/prisma/schema.prisma`**
```prisma
datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model User {
  id              String         @id @default(cuid())
  email           String         @unique
  passwordHash    String
  displayName     String
  createdAt       DateTime       @default(now())
  updatedAt       DateTime       @updatedAt
  messages        Message[]
  notifications   Notification[]
  subscriptions   Subscription[]
  sentPayments    Payment[]      @relation("sentPayments")
  receivedPayments Payment[]     @relation("receivedPayments")
}

model Conversation {
  id          String    @id @default(cuid())
  createdAt    DateTime  @default(now())
  updatedAt    DateTime  @updatedAt
  participants ConversationParticipant[]
  messages     Message[]
}

model ConversationParticipant {
  id             String       @id @default(cuid())
  conversationId String
  userId         String
  conversation   Conversation  @relation(fields: [conversationId], references: [id])
  user           User          @relation(fields: [userId], references: [id])

  @@unique([conversationId, userId])
}

model Message {
  id             String      @id @default(cuid())
  conversationId String
  senderId       String
  content        String
  createdAt      DateTime    @default(now())
  readAt         DateTime?
  conversation   Conversation @relation(fields: [conversationId], references: [id])
  sender         User         @relation(fields: [senderId], references: [id])
}

model Notification {
  id        String   @id @default(cuid())
  userId    String
  type      String
  title     String
  body      String
  read      Boolean  @default(false)
  createdAt DateTime @default(now())
  user      User     @relation(fields: [userId], references: [id])
}

model Subscription {
  id              String   @id @default(cuid())
  userId          String
  stripeCustomerId String?
  stripeSubId      String?
  status          String
  plan            String
  createdAt       DateTime @default(now())
  updatedAt       DateTime @updatedAt
  user            User    @relation(fields: [userId], references: [id])
}

model Payment {
  id              String   @id @default(cuid())
  senderId        String
  receiverId      String
  amountCents     Int
  currency        String   @default("usd")
  stripePaymentId String?
  status          String
  createdAt       DateTime @default(now())

  sender          User     @relation("sentPayments", fields: [senderId], references: [id])
  receiver        User     @relation("receivedPayments", fields: [receiverId], references: [id])
}
