## 5) Backend: Socket.IO for real-time messaging

**`server/src/socket.ts`**
```ts
import { Server } from "socket.io";
import { Server as HttpServer } from "http";

let io: Server;

export function initSocket(server: HttpServer) {
  io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_URL,
      credentials: true,
    },
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("join:user", (userId: string) => {
      socket.join(`user:${userId}`);
    });

    socket.on("join:conversation", (conversationId: string) => {
      socket.join(`conversation:${conversationId}`);
    });

    socket.on("message:send", async (payload) => {
      // payload example:
      // { conversationId, senderId, content, recipientIds: [] }
      io.to(`conversation:${payload.conversationId}`).emit("message:new", payload);
      payload.recipientIds?.forEach((uid: string) => {
        io.to(`user:${uid}`).emit("notification:new", {
          type: "message",
          title: "New message",
          body: payload.content.slice(0, 80),
        });
      });
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected:", socket.id);
    });
  });
}

export function getIO() {
  if (!io) throw new Error("Socket.io not initialized");
  return io;
}
```

