import { useEffect, useState } from "react";
import { socket } from "../socket";
import { fetchMessages, sendMessage } from "../api";

type Message = {
  id: string;
  content: string;
  createdAt: string;
  sender?: { displayName: string };
};

export default function ChatWindow({
  conversationId,
  userId,
  recipientIds,
}: {
  conversationId: string;
  userId: string;
  recipientIds: string[];
}) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [text, setText] = useState("");

  useEffect(() => {
    socket.emit("join:conversation", conversationId);

    fetchMessages(conversationId).then(setMessages);

    const handleNewMessage = (msg: any) => {
      if (msg.conversationId === conversationId) {
        setMessages((prev) => [...prev, msg]);
      }
    };

    socket.on("message:new", handleNewMessage);

    return () => {
      socket.off("message:new", handleNewMessage);
    };
  }, [conversationId]);

  const handleSend = async () => {
    const payload = { conversationId, senderId: userId, content: text };
    const saved = await sendMessage(payload);

    socket.emit("message:send", {
      ...saved,
      recipientIds,
    });

    setText("");
  };

  return (
    <div>
      <div style={{ border: "1px solid #ddd", padding: 12, minHeight: 300 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.sender?.displayName ?? "User"}:</strong> {m.content}
          </div>
        ))}
      </div>

      <div style={{ marginTop: 12 }}>
        <input
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Type a message"
        />
        <button onClick={handleSend}>Send</button>
      </div>
    </div>
  );
}
```

