import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import dotenv from "dotenv";
import { prisma } from "./prisma";
import { authRouter } from "./routes/auth.routes";
import { chatRouter } from "./routes/chat.routes";
import { notificationsRouter } from "./routes/notifications.routes";
import { paymentsRouter, creditUser } from "./routes/payments.routes";
import { requireAuth, AuthRequest } from "./auth";
import { setupSocket } from "./socket";

dotenv.config();

const app = express();
app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

app.use("/auth", authRouter);
app.use("/chat", chatRouter);
app.use("/notifications", notificationsRouter);
app.use("/payments", paymentsRouter);

app.post("/chat/send", requireAuth, async (req: AuthRequest, res) => {
  const { conversationId, content } = req.body;
  const senderId = req.user!.id;

  const wallet = await prisma.wallet.findUnique({ where: { userId: senderId } });
  if ((wallet?.balance ?? 0) <= 0) {
    return res.status(402).json({ error: "Not enough credits" });
  }

  const message = await prisma.message.create({
    data: { conversationId, senderId, content }
  });

  await prisma.wallet.update({
    where: { userId: senderId },
    data: { balance: { decrement: 1 } }
  });

  const members = await prisma.conversationMember.findMany({
    where: { conversationId },
    select: { userId: true }
  });

  const recipientIds = members.map(m => m.userId).filter(id => id !== senderId);

  await prisma.notification.createMany({
    data: recipientIds.map(id => ({
      userId: id,
      type: "message",
      title: "New message",
      body: "You received a new message"
    }))
  });

  io.to(`conv:${conversationId}`).emit("newMessage", message);
  recipientIds.forEach(id => io.to(`user:${id}`).emit("notification", { type: "message", title: "New message" }));

  res.json(message);
});

const server = http.createServer(app);
const io = setupSocket(new Server(server, {
  cors: { origin: process.env.CLIENT_URL }
}));

app.post("/debug/credit", requireAuth, async (req: AuthRequest, res) => {
  const { credits } = req.body;
  await creditUser(req.user!.id, credits);
  res.json({ ok: true });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => console.log(`Server running on ${PORT}`));
