import React, { useEffect, useState } from "react";
import { api } from "../api";

export function Chat({ token, conversationId, socket }: any) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    api(`/chat/conversation/${conversationId}/messages`, "GET", undefined, token).then(setMessages);
    socket.emit("joinConversation", conversationId);

    socket.on("newMessage", (message: any) => {
      setMessages((prev) => [...prev, message]);
    });

    return () => socket.off("newMessage");
  }, [conversationId]);

  const send = async () => {
    const msg = await api("/chat/send", "POST", { conversationId, content }, token);
    setContent("");
    setMessages((prev) => [...prev, msg]);
  };

  return (
    <div>
      <div style={{ border: "1px solid #ccc", height: 300, overflow: "auto" }}>
        {messages.map((m) => (
          <div key={m.id}>{m.content}</div>
        ))}
      </div>

      <input value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={send}>Send (1 credit)</button>
    </div>
  );
}
