## 7) Real-time notifications with Socket.IO

### `server/src/sockets/index.js`

```js
import Message from "../models/Message.js";

export function setupSocket(io) {
  io.on("connection", (socket) => {
    console.log("Connected:", socket.id);

    socket.on("join", (userId) => {
      socket.join(userId);
    });

    socket.on("send_message", async ({ sender, recipient, content }) => {
      try {
        const message = await Message.create({ sender, recipient, content });

        io.to(recipient).emit("new_message", message);
        io.to(recipient).emit("notification", {
          type: "message",
          title: "New message",
          body: content.slice(0, 60)
        });

        socket.emit("message_sent", message);
      } catch (err) {
        socket.emit("error", { error: "Message send failed" });
      }
    });

    socket.on("disconnect", () => {
      console.log("Disconnected:", socket.id);
    });
  });
}
```

