### `server/src/controllers/paymentController.js`

```js
import Stripe from "stripe";
import User from "../models/User.js";
import Notification from "../models/Notification.js";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

export const createCheckoutSession = async (req, res) => {
  const { credits } = req.body;
  const user = await User.findById(req.user.id);

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    customer_email: user.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${credits} Credits Pack` },
          unit_amount: credits * 50
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/wallet?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/wallet?canceled=1`,
    metadata: {
      userId: req.user.id,
      credits: String(credits)
    }
  });

  res.json({ url: session.url });
};

export const stripeWebhook = async (req, res) => {
  const sig = req.headers["stripe-signature"];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const credits = Number(session.metadata.credits || 0);

    const user = await User.findByIdAndUpdate(
      userId,
      { $inc: { credits } },
      { new: true }
    );

    await Notification.create({
      user: userId,
      type: "payment",
      title: "Purchase successful",
      body: `Added ${credits} credits to your wallet.`,
      meta: { credits }
    });

    req.io?.to(userId).emit("credits-updated", { credits: user.credits });
  }

  res.json({ received: true });
};
