import { pool } from "../db.js";

export async function ensureWallet(userId) {
  await pool.query(
    `INSERT INTO wallets (user_id, balance)
     VALUES ($1, 0)
     ON CONFLICT (user_id) DO NOTHING`,
    [userId]
  );
}

export async function addCredits(userId, amount) {
  await ensureWallet(userId);
  await pool.query(`UPDATE wallets SET balance = balance + $1 WHERE user_id = $2`, [
    amount,
    userId
  ]);
}

export async function subtractCredits(userId, amount) {
  await ensureWallet(userId);
  const result = await pool.query(
    `UPDATE wallets
     SET balance = balance - $1
     WHERE user_id = $2 AND balance >= $1
     RETURNING balance`,
    [amount, userId]
  );
  if (result.rowCount === 0) throw new Error("Insufficient credits");
  return result.rows[0];
}

export async function getBalance(userId) {
  await ensureWallet(userId);
  const result = await pool.query(`SELECT balance FROM wallets WHERE user_id = $1`, [
    userId
  ]);
  return result.rows[0]?.balance ?? 0;
}
