### `server/src/routes/messages.js`

```js
import express from "express";
import { pool } from "../db.js";
import { authMiddleware } from "../middleware/auth.js";
import { createNotification } from "../services/notifications.js";

export function messagesRouter(io) {
  const router = express.Router();

  router.get("/conversations/:id/messages", authMiddleware, async (req, res) => {
    const { id } = req.params;

    const result = await pool.query(
      `SELECT m.*, u.username, u.display_name
       FROM messages m
       JOIN users u ON u.id = m.sender_id
       WHERE conversation_id = $1
       ORDER BY created_at ASC`,
      [id]
    );

    res.json(result.rows);
  });

  router.post("/conversations/:id/messages", authMiddleware, async (req, res) => {
    const { id } = req.params;
    const { content } = req.body;

    if (!content) return res.status(400).json({ error: "content required" });

    const result = await pool.query(
      `INSERT INTO messages (conversation_id, sender_id, content)
       VALUES ($1, $2, $3)
       RETURNING *`,
      [id, req.user.id, content]
    );

    const message = result.rows[0];

    const members = await pool.query(
      `SELECT user_id FROM conversation_members WHERE conversation_id = $1 AND user_id <> $2`,
      [id, req.user.id]
    );

    for (const member of members.rows) {
      const notification = await createNotification(member.user_id, "new_message", {
        conversationId: Number(id),
        messageId: message.id,
        senderId: req.user.id
      });

      io.to(`user:${member.user_id}`).emit("notification", notification);
    }

    io.to(`conversation:${id}`).emit("message", message);
    res.json(message);
  });

  return router;
}
```

