import express from "express";
import Stripe from "stripe";
import { config } from "../config.js";
import { authMiddleware } from "../middleware/auth.js";
import { addCredits, getBalance } from "../services/wallet.js";
import { pool } from "../db.js";

const stripe = new Stripe(config.stripeSecretKey);
export const monetizationRouter = express.Router();

monetizationRouter.get("/wallet", authMiddleware, async (req, res) => {
  const balance = await getBalance(req.user.id);
  res.json({ balance });
});

// Buy credits: 100 credits = $1.00 in this example
monetizationRouter.post("/buy-credits", authMiddleware, async (req, res) => {
  const { credits } = req.body;
  const amountCents = Math.round((credits / 100) * 100);

  const paymentIntent = await stripe.paymentIntents.create({
    amount: amountCents,
    currency: "usd",
    metadata: {
      userId: String(req.user.id),
      credits: String(credits)
    }
  });

  await pool.query(
    `INSERT INTO payments (user_id, stripe_payment_intent_id, amount_cents, credits_added, status)
     VALUES ($1, $2, $3, $4, $5)`,
    [req.user.id, paymentIntent.id, amountCents, credits, "pending"]
  );

  res.json({ clientSecret: paymentIntent.client_secret });
});

// Example premium action (e.g., "boost" message/visibility)
monetizationRouter.post("/premium-action", authMiddleware, async (req, res) => {
  const { cost } = req.body;

  try {
    const balance = await getBalance(req.user.id);
    if (balance < cost) return res.status(400).json({ error: "Insufficient credits" });

    await pool.query("BEGIN");
    await pool.query(`UPDATE wallets SET balance = balance - $1 WHERE user_id = $2`, [
      cost,
      req.user.id
    ]);

    await pool.query(
      `INSERT INTO payments (user_id, amount_cents, credits_added, status)
       VALUES ($1, $2, $3, $4)`,
      [req.user.id, 0, -cost, "redeemed"]
    );
    await pool.query("COMMIT");

    res.json({ success: true });
  } catch (err) {
    await pool.query("ROLLBACK");
    res.status(500).json({ error: "Premium action failed" });
  }
});
