import { useEffect, useState } from "react";
import { apiFetch } from "../api.js";

export default function Chat({ token, socket, conversationId, user }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    async function load() {
      const data = await apiFetch(`/messages/conversations/${conversationId}/messages`, "GET", null, token);
      setMessages(data);
    }
    load();

    socket.emit("joinConversation", conversationId);

    socket.on("message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => {
      socket.off("message");
    };
  }, [conversationId, socket, token]);

  async function sendMessage() {
    if (!content.trim()) return;
    const msg = await apiFetch(
      `/messages/conversations/${conversationId}/messages`,
      "POST",
      { content },
      token
    );
    setContent("");
    setMessages((prev) => [...prev, msg]);
  }

  return (
    <div>
      <h2>Conversation {conversationId}</h2>
      <div style={{ border: "1px solid #ccc", height: 300, overflow: "auto" }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.sender_id === user.id ? "You" : m.username}:</strong> {m.content}
          </div>
        ))}
      </div>

      <input value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
