## 4) Stripe webhook for real monetization

To actually confirm payments and add credits, add a webhook route. This is essential for production.

### Example webhook route

```js
import express from "express";
import Stripe from "stripe";
import { config } from "../config.js";
import { pool } from "../db.js";
import { addCredits } from "../services/wallet.js";

const stripe = new Stripe(config.stripeSecretKey);
export const webhookRouter = express.Router();

webhookRouter.post(
  "/stripe",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"];
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        config.stripeWebhookSecret
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "payment_intent.succeeded") {
      const intent = event.data.object;
      const userId = Number(intent.metadata.userId);
      const credits = Number(intent.metadata.credits);

      await addCredits(userId, credits);

      await pool.query(
        `UPDATE payments SET status = $1 WHERE stripe_payment_intent_id = $2`,
        ["succeeded", intent.id]
      );
    }

    res.json({ received: true });
  }
);
```

