import { PrismaClient } from "@prisma/client";
import { stripe } from "../stripe.js";

const prisma = new PrismaClient();

export async function getWallet(req, res) {
  const wallet = await prisma.wallet.findUnique({
    where: { userId: req.user.id },
  });
  res.json(wallet);
}

export async function createCheckoutSession(req, res) {
  const { plan } = req.body;

  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${plan} plan` },
          unit_amount: plan === "pro" ? 999 : 1999,
          recurring: { interval: "month" },
        },
        quantity: 1,
      },
    ],
    success_url: `${process.env.CLIENT_URL}/billing?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/billing?canceled=1`,
    metadata: { userId: req.user.id, plan },
  });

  res.json({ url: session.url });
}

export async function buyBoost(req, res) {
  const { cost = 100 } = req.body;

  const wallet = await prisma.wallet.findUnique({
    where: { userId: req.user.id },
  });

  if (!wallet || wallet.balance < cost) {
    return res.status(400).json({ error: "Insufficient balance" });
  }

  const updated = await prisma.wallet.update({
    where: { userId: req.user.id },
    data: { balance: { decrement: cost } },
  });

  res.json({ ok: true, wallet: updated });
}

