    setText("");
  }

  return (
    <div style={{ display: "flex", gap: 20 }}>
      <div style={{ width: 300 }}>
        <h3>Conversations</h3>
        {conversations.map((c) => (
          <button key={c.id} onClick={() => openConversation(c)}>
            {c.id}
          </button>
