export function initFCM() {
  if (initialized) return;

  if (admin.apps.length === 0) {
    admin.initializeApp({
      credential: admin.credential.applicationDefault()
    });
  }

  initialized = true;
}

export async function sendPushNotification(tokens: string[], title: string, body: string) {
