## `backend/src/sockets/index.ts`

```ts
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { prisma } from "../prisma";
import { sendPushNotification } from "../services/notificationService";

export function setupSockets(httpServer: any) {
  const io = new Server(httpServer, {
    cors: { origin: "*" }
  });

  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth.token;
      const payload = jwt.verify(token, process.env.JWT_SECRET!) as any;
      socket.data.user = { id: payload.id, email: payload.email };
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", async (socket) => {
    const userId = socket.data.user.id;

    socket.join(userId);

    socket.on("send_message", async ({ conversationId, content }) => {
      const message = await prisma.message.create({
        data: { conversationId, content, senderId: userId }
      });

      const participants = await prisma.conversationParticipant.findMany({
        where: { conversationId },
        include: { user: { include: { deviceTokens: true } } }
      });

      const recipientTokens = participants
        .filter(p => p.userId !== userId)
        .flatMap(p => p.user.deviceTokens.map(t => t.token));

      await sendPushNotification(recipientTokens, "New message", content);

      io.to(conversationId).emit("new_message", message);
    });

    socket.on("join_conversation", (conversationId) => {
      socket.join(conversationId);
    });
  });

  return io;
}
```

