## 12) routes/messages.js

```js
const express = require("express");
const Conversation = require("../models/Conversation");
const Message = require("../models/Message");
const Notification = require("../models/Notification");
const User = require("../models/User");
const auth = require("../middleware/auth");

module.exports = function (io, onlineUsers) {
  const router = express.Router();

  // Create or find conversation
  router.post("/conversation", auth, async (req, res) => {
    try {
      const { participantId } = req.body;
      const me = req.user.id;

      let convo = await Conversation.findOne({
        participants: { $all: [me, participantId], $size: 2 }
      });

      if (!convo) {
        convo = await Conversation.create({ participants: [me, participantId] });
      }

      res.json(convo);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  // Get messages
  router.get("/:conversationId", auth, async (req, res) => {
    try {
      const messages = await Message.find({ conversationId: req.params.conversationId })
        .sort({ createdAt: 1 })
        .populate("senderId", "username avatarUrl");
      res.json(messages);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  // Send message with optional monetization
  router.post("/", auth, async (req, res) => {
    try {
      const { conversationId, text, monetizationType = "standard", cost = 0 } = req.body;
      const senderId = req.user.id;

      const convo = await Conversation.findById(conversationId);
      if (!convo) return res.status(404).json({ message: "Conversation not found" });

      // Handle monetization charge
      const sender = await User.findById(senderId);
      if (cost > 0) {
        if (sender.walletBalance < cost) {
          return res.status(400).json({ message: "Insufficient wallet balance" });
        }
        sender.walletBalance -= cost;
        await sender.save();
      }

      const message = await Message.create({
        conversationId,
        senderId,
        text,
        monetizationType,
        cost,
        paid: cost > 0
      });

      convo.lastMessageAt = new Date();
      await convo.save();

      const populatedMessage = await Message.findById(message._id).populate(
        "senderId",
        "username avatarUrl"
      );

      // notify other participants
      const receivers = convo.participants.filter((id) => id.toString() !== senderId);
      for (const receiverId of receivers) {
        await Notification.create({
          userId: receiverId,
          type: "message",
          title: "New Message",
          body: `${req.user.username} sent you a message`,
          metadata: { conversationId, messageId: message._id }
        });

        const socketId = onlineUsers.get(receiverId.toString());
        if (socketId) {
          io.to(socketId).emit("notification:new", {
            type: "message",
            title: "New Message",
            body: `${req.user.username} sent you a message`,
            metadata: { conversationId, messageId: message._id }
          });
        }
      }

      // emit message to conversation channel
      io.to(conversationId).emit("message:new", populatedMessage);

      res.status(201).json(populatedMessage);
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  return router;
};
```

