```js
const express = require("express");
const User = require("../models/User");
const WalletTransaction = require("../models/WalletTransaction");
const Notification = require("../models/Notification");
const auth = require("../middleware/auth");

module.exports = function (io, onlineUsers) {
  const router = express.Router();

  // Deposit funds
  router.post("/deposit", auth, async (req, res) => {
    try {
      const { amount, reference = "manual-deposit" } = req.body;
      if (amount <= 0) return res.status(400).json({ message: "Invalid amount" });

      const user = await User.findById(req.user.id);
      user.walletBalance += amount;
      await user.save();

      await WalletTransaction.create({
        userId: req.user.id,
        type: "deposit",
        amount,
        reference
      });

      res.json({ walletBalance: user.walletBalance });
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  // Tip another user
  router.post("/tip", auth, async (req, res) => {
    try {
      const { recipientId, amount } = req.body;
      if (amount <= 0) return res.status(400).json({ message: "Invalid amount" });

      const sender = await User.findById(req.user.id);
      const recipient = await User.findById(recipientId);

      if (!recipient) return res.status(404).json({ message: "Recipient not found" });
      if (sender.walletBalance < amount) {
        return res.status(400).json({ message: "Insufficient wallet balance" });
      }

      sender.walletBalance -= amount;
      recipient.walletBalance += amount;

      await sender.save();
      await recipient.save();

      await WalletTransaction.create({
        userId: req.user.id,
        type: "tip",
        amount,
        reference: recipientId
      });

      await Notification.create({
        userId: recipientId,
        type: "tip",
        title: "You received a tip",
        body: `${req.user.username} tipped you $${amount}`,
        metadata: { senderId: req.user.id, amount }
      });

      const socketId = onlineUsers.get(recipientId.toString());
      if (socketId) {
        io.to(socketId).emit("notification:new", {
          type: "tip",
          title: "You received a tip",
          body: `${req.user.username} tipped you $${amount}`,
          metadata: { senderId: req.user.id, amount }
        });
      }

      res.json({
        senderBalance: sender.walletBalance,
        recipientBalance: recipient.walletBalance
      });
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  return router;
};
