### `server/src/routes/messages.js`
```js
import express from "express";
import { Conversation } from "../models/Conversation.js";
import { Message } from "../models/Message.js";
import { User } from "../models/User.js";
import { createNotification } from "../services/notificationService.js";

export default function messagesRouter(io) {
  const router = express.Router();

  // Get messages for a conversation
  router.get("/:conversationId", async (req, res) => {
    const messages = await Message.find({ conversationId: req.params.conversationId }).sort({ createdAt: 1 });
    res.json(messages);
  });

  // Send message
  router.post("/", async (req, res) => {
    try {
      const { conversationId, senderId, text, monetized = false, costCredits = 0 } = req.body;

      const sender = await User.findById(senderId);
      if (!sender) return res.status(404).json({ error: "Sender not found" });

      if (monetized) {
        if ((sender.credits || 0) < costCredits) {
          return res.status(402).json({ error: "Insufficient credits" });
        }
        sender.credits -= costCredits;
        await sender.save();
      }

      const conversation = await Conversation.findById(conversationId).populate("participants");
      if (!conversation) return res.status(404).json({ error: "Conversation not found" });

      const message = await Message.create({
        conversationId,
        senderId,
        text,
        monetized,
        costCredits,
        readBy: [senderId]
      });

      conversation.lastMessage = text;
      await conversation.save();

      const recipientIds = conversation.participants
        .map((p) => p._id.toString())
        .filter((id) => id !== senderId);

      // Create notifications + emit realtime events
      for (const recipientId of recipientIds) {
        const note = await createNotification({
          userId: recipientId,
          type: "message",
          title: "New message",
          body: `${sender.username}: ${text}`,
          meta: { conversationId, messageId: message._id }
        });

        io.to(recipientId).emit("notification", note);
        io.to(recipientId).emit("message:new", message);
      }

      io.to(senderId).emit("message:new", message);

      res.json(message);
    } catch (err) {
      res.status(400).json({ error: err.message });
    }
  });

  return router;
}
```

