import express from "express";
import Stripe from "stripe";
import { User } from "../models/User.js";
import { createNotification } from "../services/notificationService.js";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

// Create checkout session for credits package
router.post("/checkout-session", async (req, res) => {
  try {
    const { userId, packageId } = req.body;

    const packages = {
      starter: { name: "Starter Credits", amount: 500, price: 499 },   // $4.99
      plus: { name: "Plus Credits", amount: 1500, price: 999 },         // $9.99
      pro: { name: "Pro Credits", amount: 5000, price: 1999 }           // $19.99
    };

    const selected = packages[packageId];
    if (!selected) return res.status(400).json({ error: "Invalid package" });

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
