    if (!user) return res.status(404).json({ error: "User not found" });

    user.credits += amount;
    await user.save();

    await createNotification({
      userId,
      type: "payment",
      title: "Credits added",
      body: `${amount} credits have been added to your account.`,
      meta: { amount }
    });

    res.json({ credits: user.credits });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

