## 6) Chat routes

### `server/src/routes/chat.js`

```js
import express from "express";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";
import User from "../models/User.js";
import { authMiddleware } from "../middleware/authMiddleware.js";

const router = express.Router();

router.get("/messages/:otherUserId", authMiddleware, async (req, res) => {
  const userId = req.user.userId;
  const { otherUserId } = req.params;

  const messages = await Message.find({
    $or: [
      { senderId: userId, receiverId: otherUserId },
      { senderId: otherUserId, receiverId: userId }
    ]
  }).sort({ createdAt: 1 });

  res.json(messages);
});

router.post("/send", authMiddleware, async (req, res) => {
  try {
    const senderId = req.user.userId;
    const { receiverId, content, isPremium } = req.body;

    const sender = await User.findById(senderId);
    const receiver = await User.findById(receiverId);

    if (!receiver) return res.status(404).json({ message: "Receiver not found" });

    if (isPremium && !sender.premium) {
      return res.status(403).json({ message: "Premium messaging requires premium subscription" });
    }

    const message = await Message.create({
      senderId,
      receiverId,
      content,
      isPremium: !!isPremium
    });

    const notification = await Notification.create({
      userId: receiverId,
      type: "message",
      title: "New message",
      body: `${sender.username} sent you a message`
    });

    const io = req.app.get("io");
    io.to(receiverId.toString()).emit("new-message", message);
    io.to(receiverId.toString()).emit("new-notification", notification);

    res.json(message);
  } catch (err) {
    res.status(500).json({ message: "Send failed", error: err.message });
  }
});

export default router;
```

