## 7) Monetization routes

This example uses a **credits system**:
- user buys credits
- sending premium messages can cost credits
- upgrade to premium unlocks premium messaging

### `server/src/routes/monetization.js`

```js
import express from "express";
import User from "../models/User.js";
import Transaction from "../models/Transaction.js";
import Notification from "../models/Notification.js";
import { authMiddleware } from "../middleware/authMiddleware.js";

const router = express.Router();

router.post("/buy-credits", authMiddleware, async (req, res) => {
  try {
    const { credits } = req.body;
    const userId = req.user.userId;

    if (!credits || credits <= 0) {
      return res.status(400).json({ message: "Invalid credit amount" });
    }

    const user = await User.findByIdAndUpdate(
      userId,
      { $inc: { credits } },
      { new: true }
    );

    await Transaction.create({
      userId,
      kind: "purchase",
      credits,
      meta: { source: "manual-topup" }
    });

    const notification = await Notification.create({
      userId,
      type: "credit",
      title: "Credits purchased",
      body: `You purchased ${credits} credits`
    });

    const io = req.app.get("io");
    io.to(userId.toString()).emit("wallet-updated", { credits: user.credits });
    io.to(userId.toString()).emit("new-notification", notification);

    res.json({ credits: user.credits, premium: user.premium });
  } catch (err) {
    res.status(500).json({ message: "Purchase failed", error: err.message });
  }
});

router.post("/upgrade-premium", authMiddleware, async (req, res) => {
  try {
    const userId = req.user.userId;
    const cost = 100;

    const user = await User.findById(userId);
    if (!user) return res.status(404).json({ message: "User not found" });

    if (user.credits < cost) {
      return res.status(400).json({ message: "Not enough credits" });
    }

    user.credits -= cost;
    user.premium = true;
    await user.save();

    await Transaction.create({
      userId,
      kind: "spend",
      credits: cost,
      meta: { action: "premium-upgrade" }
    });

    const notification = await Notification.create({
      userId,
      type: "premium",
      title: "Premium activated",
      body: "You are now a premium user"
    });

    const io = req.app.get("io");
    io.to(userId.toString()).emit("wallet-updated", { credits: user.credits, premium: user.premium });
    io.to(userId.toString()).emit("new-notification", notification);

    res.json({ credits: user.credits, premium: user.premium });
  } catch (err) {
    res.status(500).json({ message: "Upgrade failed", error: err.message });
  }
});

export default router;
```

