## 8) Socket.IO real-time layer

### `server/src/socket/socket.js`

```js
import jwt from "jsonwebtoken";
import User from "../models/User.js";

export function registerSocketHandlers(io) {
  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("authenticate", async (token) => {
      try {
        const decoded = jwt.verify(token, process.env.JWT_SECRET);
        socket.userId = decoded.userId;

        await User.findByIdAndUpdate(decoded.userId, { socketId: socket.id });
        socket.join(decoded.userId.toString());

        socket.emit("authenticated", { userId: decoded.userId });
      } catch (err) {
        socket.emit("auth-error", { message: "Invalid token" });
      }
    });

    socket.on("disconnect", async () => {
      if (socket.userId) {
        await User.findByIdAndUpdate(socket.userId, { socketId: null });
      }
      console.log("Socket disconnected:", socket.id);
    });
  });
}
```

**Important:** attach `io` to app in `index.js`:

Add this before `server.listen(...)`:

```js
app.set("io", io);
```

