import Login from "./components/Login";
import Chat from "./components/Chat";
import Notifications from "./components/Notifications";
import Wallet from "./components/Wallet";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (token) {
      socket.connect();
      socket.emit("authenticate", token);

      socket.on("new-notification", (notif) => {
        setNotifications((prev) => [notif, ...prev]);
      });

      socket.on("wallet-updated", (wallet) => {
        setUser((prev) => ({ ...prev, ...wallet }));
        localStorage.setItem("user", JSON.stringify({ ...user, ...wallet }));
      });
    }

    return () => {
      socket.off("new-notification");
      socket.off("wallet-updated");
    };
  }, [token]);

  const handleAuth = ({ token, user }) => {
    setToken(token);
    setUser(user);
    localStorage.setItem("token", token);
    localStorage.setItem("user", JSON.stringify(user));
  };

  const logout = () => {
    setToken("");
    setUser(null);
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    socket.disconnect();
  };

  if (!token) return <Login onAuth={handleAuth} />;

  return (
    <div style={{ padding: 20 }}>
      <h2>Social Messaging App</h2>
      <button onClick={logout}>Logout</button>
      <Wallet token={token} user={user} setUser={setUser} />
      <Notifications notifications={notifications} />
      <Chat token={token} user={user} />
    </div>
  );
}
```

