```js
import express from "express";
import Stripe from "stripe";
import User from "../models/User.js";
import { authMiddleware } from "../middleware/authMiddleware.js";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/create-checkout-session", authMiddleware, async (req, res) => {
  try {
    const { tier } = req.body;

    const priceMap = {
      pro: 499,
      premium: 999
    };

    if (!priceMap[tier]) {
      return res.status(400).json({ message: "Invalid tier" });
    }

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ["card"],
      mode: "payment",
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: `${tier.toUpperCase()} subscription`
            },
            unit_amount: priceMap[tier]
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/success?tier=${tier}`,
      cancel_url: `${process.env.CLIENT_URL}/billing`
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ message: "Stripe checkout failed", error: err.message });
  }
});

router.post("/add-coins", authMiddleware, async (req, res) => {
  try {
    const { coins } = req.body;
    await User.findByIdAndUpdate(req.user.id, { $inc: { coins } });
    res.json({ message: "Coins added" });
  } catch (err) {
    res.status(500).json({ message: "Failed to add coins", error: err.message });
  }
});

export default router;
```

