```js
import React, { useEffect, useState } from "react";
import api from "./api";
import { createSocket } from "./socket";

function App() {
  const [auth, setAuth] = useState({ email: "", password: "", username: "" });
  const [token, setToken] = useState(localStorage.getItem("token"));
  const [roomId, setRoomId] = useState("general");
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notice, setNotice] = useState("");
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    if (!token) return;
    const s = createSocket();
    setSocket(s);

    s.on("receive_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    s.on("notification", (n) => {
      setNotice(n.text);
      setTimeout(() => setNotice(""), 3000);
    });

    return () => s.close();
  }, [token]);

  useEffect(() => {
    if (!token) return;
    api.get(`/messages/${roomId}`).then((res) => setMessages(res.data));
    socket?.emit("join_room", roomId);
  }, [roomId, socket, token]);

  const register = async () => {
    const res = await api.post("/auth/register", auth);
    localStorage.setItem("token", res.data.token);
    setToken(res.data.token);
  };

  const login = async () => {
    const res = await api.post("/auth/login", {
      email: auth.email,
      password: auth.password
    });
    localStorage.setItem("token", res.data.token);
    setToken(res.data.token);
  };

  const sendMessage = async () => {
    const res = await api.post(`/messages/${roomId}`, { text });
    socket.emit("send_message", { roomId, message: res.data });
    setText("");
  };

  const buyPro = async () => {
    const res = await api.post("/monetization/create-checkout-session", { tier: "pro" });
    window.location.href = res.data.url;
  };

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Social App Auth</h2>
        <input placeholder="Username" value={auth.username}
          onChange={(e) => setAuth({ ...auth, username: e.target.value })} />
        <br />
        <input placeholder="Email" value={auth.email}
          onChange={(e) => setAuth({ ...auth, email: e.target.value })} />
        <br />
        <input placeholder="Password" type="password" value={auth.password}
          onChange={(e) => setAuth({ ...auth, password: e.target.value })} />
        <br />
        <button onClick={register}>Register</button>
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ padding: 20 }}>
      <h2>Messaging App</h2>
      {notice && <div style={{ background: "#dff0d8", padding: 10 }}>{notice}</div>}

      <button onClick={buyPro}>Upgrade to Pro</button>

      <div>
        <label>Room: </label>
        <input value={roomId} onChange={(e) => setRoomId(e.target.value)} />
      </div>

      <div style={{ border: "1px solid #ccc", padding: 10, marginTop: 20 }}>
        {messages.map((m) => (
          <div key={m._id}>
            <strong>{m.senderId?.username || "Unknown"}:</strong> {m.text}
          </div>
        ))}
      </div>

      <input
        style={{ width: "70%" }}
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Type a message"
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}

export default App;
```

