## 7) Socket.IO for real-time messages/notifications

### `server/src/socket.js`

```js
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();
let io;

export function initSocket(httpServer) {
  io = new Server(httpServer, {
    cors: {
      origin: process.env.CLIENT_URL,
      credentials: true
    }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = payload;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", async (socket) => {
    const userId = socket.user.userId;

    await prisma.socketConnection.create({
      data: { userId, socketId: socket.id }
    });

    socket.join(`user:${userId}`);

    socket.on("message:send", async ({ conversationId, content }) => {
      const message = await prisma.message.create({
        data: {
          conversationId,
          senderId: userId,
          content
        }
      });

      const participants = await prisma.conversationParticipant.findMany({
        where: { conversationId }
      });

      for (const p of participants) {
        io.to(`user:${p.userId}`).emit("message:new", message);

        if (p.userId !== userId) {
          const notif = await prisma.notification.create({
            data: {
              userId: p.userId,
              type: "message",
              title: "New message",
              body: content.slice(0, 100),
              data: { conversationId, messageId: message.id }
            }
          });

          io.to(`user:${p.userId}`).emit("notification:new", notif);
        }
      }
    });

    socket.on("notification:read", async ({ notificationId }) => {
      const notif = await prisma.notification.update({
        where: { id: notificationId },
        data: { readAt: new Date() }
      });

      socket.emit("notification:updated", notif);
    });

    socket.on("disconnect", async () => {
      await prisma.socketConnection.deleteMany({
        where: { socketId: socket.id }
      });
    });
  });

  return io;
}

export function getIO() {
  return io;
}
```

