```js
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";
import User from "../models/User.js";

export async function getConversation(req, res) {
  try {
    const userId = req.user.id;
    const otherUserId = req.params.userId;

    const messages = await Message.find({
      $or: [
        { sender: userId, recipient: otherUserId },
        { sender: otherUserId, recipient: userId }
      ]
    })
      .sort({ createdAt: 1 })
      .populate("sender", "username avatarUrl")
      .populate("recipient", "username avatarUrl");

    res.json(messages);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
}

export async function sendMessage(req, res) {
  try {
    const senderId = req.user.id;
    const { recipientId, content } = req.body;

    const message = await Message.create({
      sender: senderId,
      recipient: recipientId,
      content
    });

    const populated = await Message.findById(message._id)
      .populate("sender", "username avatarUrl")
      .populate("recipient", "username avatarUrl");

    const recipient = await User.findById(recipientId);

    const notification = await Notification.create({
      user: recipientId,
      type: "message",
      title: "New message",
      body: `You received a message from ${populated.sender.username}`,
      data: { messageId: message._id.toString(), senderId }
    });

    req.io.to(recipient?.socketId || "").emit("newMessage", populated);
    req.io.to(recipient?.socketId || "").emit("newNotification", notification);

    res.json(populated);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
}
```

