```jsx
import React, { useEffect, useState } from "react";
import { api, setAuthToken } from "./services/api";
import { socket } from "./services/socket";

export default function App() {
  const [token, setTokenState] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [recipientId, setRecipientId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    setAuthToken(token);

    if (token && user) {
      socket.connect();
      socket.emit("register", { userId: user.id });

      socket.on("newMessage", (msg) => {
        setMessages((prev) => [...prev, msg]);
      });

      socket.on("newNotification", (n) => {
        setNotifications((prev) => [n, ...prev]);
      });
    }

    return () => {
      socket.off("newMessage");
      socket.off("newNotification");
      socket.disconnect();
    };
  }, [token, user]);

  async function register() {
    const res = await api.post("/auth/register", {
      username: email.split("@")[0],
      email,
      password
    });
    saveAuth(res.data);
  }

  async function login() {
    const res = await api.post("/auth/login", { email, password });
    saveAuth(res.data);
  }

  function saveAuth(data) {
    localStorage.setItem("token", data.token);
    localStorage.setItem("user", JSON.stringify(data.user));
    setTokenState(data.token);
    setUser(data.user);
  }

  async function sendMessage() {
    const res = await api.post("/messages", {
      recipientId,
      content
    });
    setMessages((prev) => [...prev, res.data]);
    setContent("");
  }

  async function fetchNotifications() {
    const res = await api.get("/notifications");
    setNotifications(res.data);
  }

  async function upgradeToPremium() {
    const res = await api.post("/payments/checkout");
    window.location.href = res.data.url;
  }

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h1>Social Messaging App</h1>
        <input placeholder="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <input
          placeholder="password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <button onClick={register}>Register</button>
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h1>Welcome, {user.username}</h1>
      <p>Status: {user.premium ? "Premium" : "Free"}</p>

      <button onClick={fetchNotifications}>Load Notifications</button>
      <button onClick={upgradeToPremium}>Upgrade to Premium</button>

      <hr />

      <h2>Send Message</h2>
      <input
        placeholder="Recipient User ID"
        value={recipientId}
        onChange={(e) => setRecipientId(e.target.value)}
      />
      <input
        placeholder="Message"
        value={content}
        onChange={(e) => setContent(e.target.value)}
      />
      <button onClick={sendMessage}>Send</button>

      <h3>Messages</h3>
      <ul>
        {messages.map((m) => (
          <li key={m._id}>
            <strong>{m.sender?.username || "you"}:</strong> {m.content}
          </li>
        ))}
      </ul>

      <h3>Notifications</h3>
      <ul>
        {notifications.map((n) => (
          <li key={n._id}>
            <strong>{n.title}</strong> - {n.body} {n.read ? "(read)" : ""}
          </li>
        ))}
      </ul>
    </div>
  );
}
