## `server/src/index.js`

```js
require("dotenv").config();

const express = require("express");
const cors = require("cors");
const http = require("http");
const jwt = require("jsonwebtoken");
const bcrypt = require("bcrypt");
const { Server } = require("socket.io");
const { PrismaClient } = require("@prisma/client");
const Stripe = require("stripe");

const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    credentials: true,
  },
});

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.replace("Bearer ", "");
  if (!token) return res.status(401).json({ error: "No token" });

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

function createToken(user) {
  return jwt.sign(
    { id: user.id, email: user.email, name: user.name },
    process.env.JWT_SECRET,
    { expiresIn: "7d" }
  );
}

const onlineUsers = new Map(); // userId -> socketId

io.use((socket, next) => {
  try {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    socket.user = payload;
    next();
  } catch (err) {
    next(new Error("Unauthorized"));
  }
});

io.on("connection", (socket) => {
  const userId = socket.user.id;
  onlineUsers.set(userId, socket.id);

  socket.join(userId);

  socket.on("joinConversation", (conversationId) => {
    socket.join(conversationId);
  });

  socket.on("sendMessage", async ({ conversationId, content }) => {
    const message = await prisma.message.create({
      data: {
        conversationId,
        senderId: userId,
        content,
      },
      include: { sender: true },
    });

    const members = await prisma.conversationMember.findMany({
      where: { conversationId },
    });

    const otherMembers = members.filter((m) => m.userId !== userId);

    for (const member of otherMembers) {
      const notification = await prisma.notification.create({
        data: {
          type: "message",
          title: "New message",
          body: `${message.sender.name}: ${content.slice(0, 80)}`,
          receiverId: member.userId,
          senderId: userId,
          data: { conversationId, messageId: message.id },
        },
      });

      io.to(member.userId).emit("notification", notification);
    }

    io.to(conversationId).emit("newMessage", message);
  });

  socket.on("disconnect", () => {
    onlineUsers.delete(userId);
  });
});

// AUTH
app.post("/api/auth/register", async (req, res) => {
  const { email, password, name } = req.body;

  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) return res.status(400).json({ error: "Email already in use" });

  const hashed = await bcrypt.hash(password, 10);
  const user = await prisma.user.create({
    data: { email, password: hashed, name },
  });

  res.json({ token: createToken(user), user });
});

app.post("/api/auth/login", async (req, res) => {
  const { email, password } = req.body;

  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({ token: createToken(user), user });
});

app.get("/api/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user.id },
    select: { id: true, email: true, name: true, avatarUrl: true, createdAt: true },
  });
  res.json(user);
});

// CONVERSATIONS
app.get("/api/conversations", authMiddleware, async (req, res) => {
  const conversations = await prisma.conversation.findMany({
    where: {
      members: { some: { userId: req.user.id } },
    },
    include: {
      members: { include: { user: true } },
      messages: { orderBy: { createdAt: "desc" }, take: 1 },
    },
    orderBy: { updatedAt: "desc" },
  });

  res.json(conversations);
});

app.post("/api/conversations", authMiddleware, async (req, res) => {
  const { memberIds } = req.body; // array of userIds

  const conversation = await prisma.conversation.create({
    data: {
      members: {
        create: [req.user.id, ...memberIds].map((id) => ({ userId: id })),
      },
    },
    include: { members: true },
  });

  res.json(conversation);
});

app.get("/api/conversations/:id/messages", authMiddleware, async (req, res) => {
  const { id } = req.params;

  const isMember = await prisma.conversationMember.findFirst({
    where: { conversationId: id, userId: req.user.id },
  });

  if (!isMember) return res.status(403).json({ error: "Forbidden" });

  const messages = await prisma.message.findMany({
    where: { conversationId: id },
    include: { sender: true },
    orderBy: { createdAt: "asc" },
  });

  res.json(messages);
});

// NOTIFICATIONS
app.get("/api/notifications", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { receiverId: req.user.id },
    orderBy: { createdAt: "desc" },
  });
  res.json(notifications);
});

app.post("/api/notifications/:id/read", authMiddleware, async (req, res) => {
  const { id } = req.params;
  const notification = await prisma.notification.update({
    where: { id },
    data: { readAt: new Date() },
  });
  res.json(notification);
});

// MONETIZATION: Create Stripe Checkout session
app.post("/api/stripe/create-checkout-session", authMiddleware, async (req, res) => {
  const { mode = "subscription" } = req.body;

  // Example price IDs from Stripe dashboard
  const priceId =
    mode === "subscription"
      ? "price_subscription_example"
      : "price_boost_example";

  const session = await stripe.checkout.sessions.create({
    mode,
    payment_method_types: ["card"],
    line_items: [{ price: priceId, quantity: 1 }],
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    client_reference_id: req.user.id,
    metadata: { userId: req.user.id },
  });

  res.json({ url: session.url });
});

// STRIPE WEBHOOK
app.post(
  "/api/stripe/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"];

    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;

      await prisma.subscription.upsert({
        where: { userId },
        update: {
          status: "ACTIVE",
        },
        create: {
          userId,
          status: "ACTIVE",
        },
      });

      io.to(userId).emit("monetizationUpdate", {
        success: true,
        message: "Subscription activated",
      });
    }

    res.json({ received: true });
  }
);

server.listen(process.env.PORT, () => {
  console.log(`Server running on port ${process.env.PORT}`);
});
