import { useEffect, useState } from "react";
import api from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [user, setUser] = useState(null);
  const [socket, setSocket] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [conversations, setConversations] = useState([]);
  const [activeConversation, setActiveConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const init = async () => {
      const token = localStorage.getItem("token");
      if (!token) return;

      const me = await api.get("/me");
      setUser(me.data);

      const s = createSocket(token);
      setSocket(s);

      s.on("notification", (notification) => {
        setNotifications((prev) => [notification, ...prev]);
      });

      s.on("newMessage", (msg) => {
        setMessages((prev) => [...prev, msg]);
      });

      return () => s.close();
    };

    init();
  }, []);

  useEffect(() => {
    if (!user) return;

    api.get("/conversations").then((res) => setConversations(res.data));
    api.get("/notifications").then((res) => setNotifications(res.data));
  }, [user]);

  async function loginDemo() {
    const res = await api.post("/auth/login", {
      email: "demo@example.com",
      password: "password123",
    });
    localStorage.setItem("token", res.data.token);
    window.location.reload();
  }

  async function registerDemo() {
    const res = await api.post("/auth/register", {
      email: "demo@example.com",
      password: "password123",
      name: "Demo User",
    });
    localStorage.setItem("token", res.data.token);
    window.location.reload();
  }

  async function openConversation(conv) {
    setActiveConversation(conv);
    const res = await api.get(`/conversations/${conv.id}/messages`);
    setMessages(res.data);
    socket?.emit("joinConversation", conv.id);
  }

  async function sendMessage() {
    if (!activeConversation || !message.trim()) return;
    socket.emit("sendMessage", {
      conversationId: activeConversation.id,
      content: message,
    });
    setMessage("");
  }

  async function startSubscription() {
    const res = await api.post("/stripe/create-checkout-session", {
      mode: "subscription",
    });
    window.location.href = res.data.url;
  }

  if (!user) {
    return (
      <div style={{ padding: 24 }}>
        <h1>Messaging App</h1>
        <button onClick={registerDemo}>Register Demo</button>
        <button onClick={loginDemo} style={{ marginLeft: 8 }}>
          Login Demo
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <aside style={{ width: 320, borderRight: "1px solid #ddd", padding: 16 }}>
        <h2>Chats</h2>
        {conversations.map((conv) => (
          <div
            key={conv.id}
            onClick={() => openConversation(conv)}
            style={{ padding: 12, cursor: "pointer", borderBottom: "1px solid #eee" }}
          >
            Conversation {conv.id.slice(0, 6)}
          </div>
        ))}

        <h2 style={{ marginTop: 24 }}>Notifications</h2>
        {notifications.map((n) => (
          <div key={n.id} style={{ padding: 8, borderBottom: "1px solid #eee" }}>
            <strong>{n.title}</strong>
            <div>{n.body}</div>
          </div>
        ))}

        <button onClick={startSubscription} style={{ marginTop: 24 }}>
          Go Premium
        </button>
      </aside>

      <main style={{ flex: 1, padding: 16 }}>
        <h1>{activeConversation ? "Conversation" : "Select a chat"}</h1>

        <div style={{ height: "70vh", overflowY: "auto", border: "1px solid #ddd", padding: 12 }}>
          {messages.map((m) => (
            <div key={m.id} style={{ marginBottom: 10 }}>
              <strong>{m.sender?.name || "User"}:</strong> {m.content}
