# 7) Socket service for real-time messaging and notifications

## `src/services/socket.service.js`
```js
const jwt = require('jsonwebtoken');
const { createNotification } = require('./notification.service');

let ioInstance;

function initSocket(io) {
  ioInstance = io;

  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth?.token;
      if (!token) return next(new Error('Unauthorized'));

      const payload = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = payload;
      next();
    } catch (err) {
      next(new Error('Unauthorized'));
    }
  });

  io.on('connection', (socket) => {
    console.log(`User connected: ${socket.user.id}`);

    socket.join(`user:${socket.user.id}`);

    socket.on('message:send', async (payload, ack) => {
      try {
        // Minimal example: persist message in DB in real implementation
        const message = {
          id: Date.now().toString(),
          conversationId: payload.conversationId,
          senderId: socket.user.id,
          content: payload.content,
          createdAt: new Date().toISOString()
        };

        // Emit to conversation participants
        io.to(`conversation:${payload.conversationId}`).emit('message:new', message);

        // Create notification for recipients
        if (payload.recipientIds?.length) {
          for (const recipientId of payload.recipientIds) {
            const notification = await createNotification({
              userId: recipientId,
              type: 'new_message',
              title: 'New message',
              body: payload.content.slice(0, 80),
              data: { conversationId: payload.conversationId, messageId: message.id }
            });

            io.to(`user:${recipientId}`).emit('notification:new', notification);
          }
        }

        if (ack) ack({ ok: true, message });
      } catch (error) {
        if (ack) ack({ ok: false, error: error.message });
      }
    });

    socket.on('conversation:join', ({ conversationId }) => {
      socket.join(`conversation:${conversationId}`);
    });

    socket.on('typing:start', ({ conversationId }) => {
      socket.to(`conversation:${conversationId}`).emit('typing:update', {
        conversationId,
        userId: socket.user.id,
        isTyping: true
      });
    });

    socket.on('typing:stop', ({ conversationId }) => {
      socket.to(`conversation:${conversationId}`).emit('typing:update', {
        conversationId,
        userId: socket.user.id,
        isTyping: false
      });
    });

    socket.on('disconnect', () => {
      console.log(`User disconnected: ${socket.user.id}`);
    });
  });
}

function getIo() {
  if (!ioInstance) throw new Error('Socket.IO not initialized');
  return ioInstance;
}

module.exports = { initSocket, getIo };
```

