## 7) Real-time Socket.IO

`src/realtime/socket.ts`
```ts
import { Server } from "http";
import { Server as SocketServer, Socket } from "socket.io";
import jwt from "jsonwebtoken";
import { prisma } from "../lib/prisma";

let io: SocketServer;

export function initSocket(server: Server) {
  io = new SocketServer(server, {
    cors: { origin: true, credentials: true },
  });

  io.use((socket: Socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET!) as {
        userId: string;
        email: string;
      };
      socket.data.user = payload;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.data.user.userId;
    socket.join(`user:${userId}`);

    socket.on("conversation:join", (conversationId: string) => {
      socket.join(`conversation:${conversationId}`);
    });

    socket.on("message:send", async (payload: { conversationId: string; content: string }) => {
      const message = await prisma.message.create({
        data: {
          conversationId: payload.conversationId,
          senderId: userId,
          content: payload.content,
        },
      });

      io.to(`conversation:${payload.conversationId}`).emit("message:new", message);

      const participants = await prisma.conversationParticipant.findMany({
        where: { conversationId: payload.conversationId },
        select: { userId: true },
      });

      const recipientIds = participants
        .map((p) => p.userId)
        .filter((id) => id !== userId);

      for (const recipientId of recipientIds) {
        await prisma.notification.create({
          data: {
            userId: recipientId,
            type: "MESSAGE",
            title: "New message",
            body: "You received a new message.",
            metadata: { conversationId: payload.conversationId, messageId: message.id },
          },
        });

        io.to(`user:${recipientId}`).emit("notification:new", {
          type: "MESSAGE",
          title: "New message",
          body: "You received a new message.",
          metadata: { conversationId: payload.conversationId, messageId: message.id },
        });
      }
    });

    socket.on("disconnect", () => {});
  });

  return io;
}

export function getIO() {
  if (!io) throw new Error("Socket.IO not initialized");
  return io;
}
```

