`src/routes/billing.ts`
```ts
import { Router } from "express";
import Stripe from "stripe";
import { prisma } from "../lib/prisma";
import { requireAuth, AuthRequest } from "../middleware/auth";

const router = Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: "2025-02-24.acacia",
});

router.post("/checkout", requireAuth, async (req: AuthRequest, res) => {
  const { priceId } = req.body;
  const userId = req.user!.userId;

  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    line_items: [{ price: priceId, quantity: 1 }],
    success_url: `${process.env.CLIENT_URL}/billing/success`,
    cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
    metadata: { userId },
  });

  res.json({ url: session.url });
});

router.post("/webhook", async (req, res) => {
  // In production: verify Stripe signature using raw body
  res.sendStatus(200);
});

router.get("/status", requireAuth, async (req: AuthRequest, res) => {
  const subscription = await prisma.subscription.findUnique({
    where: { userId: req.user!.userId },
  });

  res.json(subscription);
});

export default router;
```

### Billing service idea
When Stripe webhook confirms payment:
- create or update `Subscription`
- set `status = ACTIVE`
- add credits if purchase was a one-time product
- create payment notification
- emit `notification:new`

