```js
import express from 'express';
import { pool } from '../config/db.js';
import { authMiddleware } from '../middleware/auth.js';
import { v4 as uuidv4 } from 'uuid';

export function messagesRouter(io) {
  const router = express.Router();

  router.post('/conversations/:id/messages', authMiddleware, async (req, res) => {
    const { id: conversationId } = req.params;
    const { content } = req.body;

    const messageId = uuidv4();

    const result = await pool.query(
      `INSERT INTO messages (id, conversation_id, sender_id, content, message_type)
       VALUES ($1, $2, $3, $4, 'text')
       RETURNING *`,
      [messageId, conversationId, req.user.sub, content]
    );

    const message = result.rows[0];

    io.to(`conversation:${conversationId}`).emit('message:new', message);

    // Create in-app notifications for participants except sender
    const participants = await pool.query(
      `SELECT user_id FROM conversation_participants WHERE conversation_id = $1 AND user_id != $2`,
      [conversationId, req.user.sub]
    );

    for (const p of participants.rows) {
      await pool.query(
        `INSERT INTO notifications (id, user_id, type, title, body, data)
         VALUES ($1, $2, 'message', 'New message', $3, $4)`,
        [
          uuidv4(),
          p.user_id,
          `You received a new message`,
          JSON.stringify({ conversationId, messageId }),
        ]
      );

      io.to(`user:${p.user_id}`).emit('notification:new', {
        type: 'message',
        title: 'New message',
        body: 'You received a new message',
        data: { conversationId, messageId },
      });
    }

    res.status(201).json(message);
  });

  router.get('/conversations/:id/messages', authMiddleware, async (req, res) => {
    const { id: conversationId } = req.params;

    const result = await pool.query(
      `SELECT * FROM messages
       WHERE conversation_id = $1
       ORDER BY created_at DESC
       LIMIT 50`,
      [conversationId]
    );

    res.json(result.rows);
  });

  return router;
}
