```js
import express from 'express';
import { stripe } from '../config/stripe.js';
import { pool } from '../config/db.js';
import { authMiddleware } from '../middleware/auth.js';
import { v4 as uuidv4 } from 'uuid';

export function billingRouter(io) {
  const router = express.Router();

  router.post('/billing/checkout-session', authMiddleware, async (req, res) => {
    const { priceId } = req.body;

    const session = await stripe.checkout.sessions.create({
      mode: 'subscription',
      payment_method_types: ['card'],
      line_items: [{ price: priceId, quantity: 1 }],
      success_url: `${process.env.APP_URL}/billing/success`,
      cancel_url: `${process.env.APP_URL}/billing/cancel`,
      client_reference_id: req.user.sub,
    });

    res.json({ url: session.url });
  });

  router.post('/billing/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
    const sig = req.headers['stripe-signature'];
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object;

      await pool.query(
        `INSERT INTO subscriptions (id, user_id, provider, provider_subscription_id, status, plan)
         VALUES ($1, $2, 'stripe', $3, 'active', 'premium')
         ON CONFLICT DO NOTHING`,
        [uuidv4(), session.client_reference_id, session.subscription]
      );

      io.to(`user:${session.client_reference_id}`).emit('payment:updated', {
        status: 'active',
        plan: 'premium',
      });
    }

    res.json({ received: true });
  });

  return router;
}
