## 8) Message Creation Flow

### REST endpoint example
```ts
app.post("/conversations/:id/messages", authMiddleware, async (req, res) => {
  const userId = req.user.id;
  const conversationId = req.params.id;
  const { content, contentType = "text" } = req.body;

  const participant = await prisma.conversationParticipant.findUnique({
    where: {
      conversationId_userId: {
        conversationId,
        userId
      }
    }
  });

  if (!participant) {
    return res.status(403).json({ error: "Not a participant" });
  }

  const message = await prisma.message.create({
    data: {
      conversationId,
      senderId: userId,
      content,
      contentType
    }
  });

  const conversation = await prisma.conversationParticipant.findMany({
    where: { conversationId },
    select: { userId: true }
  });

  // real-time emit to all participants
  conversation.forEach(({ userId: participantId }) => {
    io.to(`user:${participantId}`).emit("message:new", message);
  });

  // create notification for offline users
  // send push via FCM

  res.json(message);
});
```

