## 8) Real-time socket setup

### `server/src/sockets/index.ts`

```ts
import { Server } from "socket.io";
import { Server as HttpServer } from "http";
import jwt from "jsonwebtoken";
import { prisma } from "../lib/prisma";

let io: Server;

export function initSockets(server: HttpServer) {
  io = new Server(server, {
    cors: { origin: true, credentials: true }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET!) as {
        id: string;
        email: string;
      };
      (socket as any).user = payload;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const user = (socket as any).user;
    socket.join(`user:${user.id}`);

    socket.on("message:send", async (data) => {
      const { recipientId, content, conversationId, isPaid } = data;

      const message = await prisma.message.create({
        data: {
          conversationId,
          senderId: user.id,
          recipientId,
          content,
          isPaid: !!isPaid
        }
      });

      const notification = await prisma.notification.create({
        data: {
          userId: recipientId,
          type: "MESSAGE",
          title: "New message",
          body: content.slice(0, 80),
          metadata: { messageId: message.id, conversationId }
        }
      });

      io.to(`user:${recipientId}`).emit("message:received", message);
      io.to(`user:${recipientId}`).emit("notification:new", notification);
    });

    socket.on("notification:read", async ({ notificationId }) => {
      await prisma.notification.update({
        where: { id: notificationId },
        data: { readAt: new Date() }
      });
    });
  });

  return io;
}

export function getIO() {
  if (!io) throw new Error("Socket.io not initialized");
  return io;
}
```

