## 15) Basic chat component

### `client/src/components/Chat.tsx`

```tsx
import { useEffect, useState } from "react";
import { createSocket } from "../socket";
import { apiFetch } from "../services/api";

type Message = {
  id: string;
  senderId: string;
  recipientId: string;
  content: string;
  createdAt: string;
};

export function Chat({ conversationId, recipientId }: { conversationId: string; recipientId: string }) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [content, setContent] = useState("");
  const [socket, setSocket] = useState<any>(null);

  useEffect(() => {
    (async () => {
      const msgs = await apiFetch(`/messages/conversation/${conversationId}`);
      setMessages(msgs);
    })();

    const token = localStorage.getItem("token")!;
    const s = createSocket(token);

    s.on("message:received", (msg: Message) => {
      if (msg.conversationId === conversationId) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    setSocket(s);
    return () => s.disconnect();
  }, [conversationId]);

  const send = () => {
    socket.emit("message:send", {
      conversationId,
      recipientId,
      content
    });

    setContent("");
  };

  return (
    <div>
      <div style={{ maxHeight: 400, overflow: "auto" }}>
        {messages.map((m) => (
          <div key={m.id}>{m.content}</div>
        ))}
      </div>

      <input value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={send}>Send</button>
    </div>
  );
}
```

