```tsx
import { useEffect, useState } from "react";
import { apiFetch } from "../services/api";
import { createSocket } from "../socket";

type Notification = {
  id: string;
  title: string;
  body: string;
  readAt?: string | null;
};

export function Notifications() {
  const [items, setItems] = useState<Notification[]>([]);

  useEffect(() => {
    (async () => {
      const existing = await apiFetch("/notifications");
      setItems(existing);
    })();

    const s = createSocket(localStorage.getItem("token")!);
    s.on("notification:new", (n: Notification) => {
      setItems((prev) => [n, ...prev]);
    });

    return () => s.disconnect();
  }, []);

  const markRead = async (id: string) => {
    await apiFetch(`/notifications/${id}/read`, { method: "POST" });
    setItems((prev) => prev.map((n) => (n.id === id ? { ...n, readAt: new Date().toISOString() } : n)));
  };

  return (
    <div>
      {items.map((n) => (
        <div key={n.id} style={{ fontWeight: n.readAt ? "normal" : "bold" }}>
          <div>{n.title}</div>
          <div>{n.body}</div>
          {!n.readAt && <button onClick={() => markRead(n.id)}>Mark read</button>}
        </div>
      ))}
    </div>
  );
}
```

