import { Router } from "express";
import { requireAuth, AuthRequest } from "../middleware/auth";
import { stripe } from "../lib/stripe";
import { prisma } from "../lib/prisma";

const router = Router();

router.post("/checkout", requireAuth, async (req: AuthRequest, res) => {
  try {
    const { mode, priceId } = req.body; // mode: "subscription" | "payment"

    const session = await stripe.checkout.sessions.create({
      mode,
      line_items: [{ price: priceId, quantity: 1 }],
      success_url: `${process.env.CLIENT_URL}/billing/success`,
      cancel_url: `${process.env.CLIENT_URL}/billing/cancel`,
      metadata: { userId: req.user!.id },
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: "Failed to create checkout session" });
  }
});

router.get("/wallet", requireAuth, async (req: AuthRequest, res) => {
  const wallet = await prisma.wallet.findUnique({
    where: { userId: req.user!.id },
  });

  res.json({ balance: wallet?.balance ?? 0 });
});

