# 2) Database Schema (Prisma)

`backend/prisma/schema.prisma`

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum NotificationType {
  MESSAGE
  PAYMENT
  SYSTEM
  FOLLOW
  LIKE
}

enum PaymentStatus {
  PENDING
  COMPLETED
  FAILED
}

model User {
  id              String         @id @default(cuid())
  email           String         @unique
  username        String         @unique
  passwordHash    String
  displayName     String?
  bio             String?
  avatarUrl       String?
  balanceCents    Int            @default(0)
  createdAt       DateTime       @default(now())
  updatedAt       DateTime       @updatedAt

  messages        Message[]
  notifications   Notification[]
  sentPayments    Payment[]      @relation("SentPayments")
  receivedPayments Payment[]     @relation("ReceivedPayments")
  conversations   ConversationParticipant[]
}

model Conversation {
  id              String                  @id @default(cuid())
  createdAt       DateTime                @default(now())
  updatedAt       DateTime                @updatedAt
  participants   ConversationParticipant[]
  messages        Message[]
}

model ConversationParticipant {
  id              String         @id @default(cuid())
  userId          String
  conversationId  String
  user            User           @relation(fields: [userId], references: [id], onDelete: Cascade)
  conversation    Conversation   @relation(fields: [conversationId], references: [id], onDelete: Cascade)

  @@unique([userId, conversationId])
}

model Message {
  id              String       @id @default(cuid())
  conversationId  String
  senderId        String
  content         String
  createdAt       DateTime     @default(now())
  updatedAt       DateTime     @updatedAt
  conversation    Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)
  sender          User         @relation(fields: [senderId], references: [id], onDelete: Cascade)
}

model Notification {
  id              String            @id @default(cuid())
  userId          String
  type            NotificationType
  title           String
  body            String
  isRead          Boolean           @default(false)
  metadata        Json?
  createdAt       DateTime          @default(now())
  user            User              @relation(fields: [userId], references: [id], onDelete: Cascade)
}

model Payment {
  id              String         @id @default(cuid())
  senderId        String
  recipientId     String
  amountCents     Int
  currency        String         @default("usd")
  status          PaymentStatus  @default(PENDING)
  stripePaymentIntentId String?
  createdAt       DateTime      @default(now())
  updatedAt       DateTime      @updatedAt

  sender          User          @relation("SentPayments", fields: [senderId], references: [id], onDelete: Cascade)
  recipient      User           @relation("ReceivedPayments", fields: [recipientId], references: [id], onDelete: Cascade)
}
```

