## `backend/src/services/payment.service.ts`

```ts
import { PrismaClient, PaymentStatus } from "@prisma/client";
import Stripe from "stripe";
import { env } from "../config/env";
import { createNotification } from "./notification.service";

const prisma = new PrismaClient();
const stripe = new Stripe(env.stripeSecretKey);

export async function createPaymentIntent(senderId: string, recipientId: string, amountCents: number) {
  const payment = await prisma.payment.create({
    data: { senderId, recipientId, amountCents, status: PaymentStatus.PENDING }
  });

  const intent = await stripe.paymentIntents.create({
    amount: amountCents,
    currency: "usd",
    metadata: {
      paymentId: payment.id,
      senderId,
      recipientId
    }
  });

  await prisma.payment.update({
    where: { id: payment.id },
    data: { stripePaymentIntentId: intent.id }
  });

  return { clientSecret: intent.client_secret, paymentId: payment.id };
}

export async function finalizePayment(paymentIntentId: string) {
  const intent = await stripe.paymentIntents.retrieve(paymentIntentId);
  const paymentId = intent.metadata.paymentId;

  const payment = await prisma.payment.findUnique({ where: { id: paymentId } });
  if (!payment) throw new Error("Payment not found");

  if (intent.status === "succeeded") {
    const updated = await prisma.payment.update({
      where: { id: payment.id },
      data: { status: PaymentStatus.COMPLETED }
    });

    await prisma.user.update({
      where: { id: updated.recipientId },
      data: { balanceCents: { increment: updated.amountCents } }
    });

    await createNotification(
      updated.recipientId,
      "PAYMENT",
      "You've received a payment",
      `You received $${(updated.amountCents / 100).toFixed(2)}`
    );

    return updated;
  }

  return prisma.payment.update({
    where: { id: payment.id },
    data: { status: PaymentStatus.FAILED }
  });
}
```

## `backend/src/services/socket.service.ts`

```ts
import { Server } from "socket.io";
import { verifyToken } from "../utils/jwt";
import { sendMessage } from "./chat.service";
import { createNotification } from "./notification.service";

let io: Server;

export function initSocket(server: any) {
  io = new Server(server, {
    cors: {
      origin: "*",
      methods: ["GET", "POST"]
    }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth.token;
    if (!token) return next(new Error("Unauthorized"));
    try {
      const decoded = verifyToken(token);
      (socket as any).userId = decoded.userId;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = (socket as any).userId;

    socket.join(userId);

    socket.on("message:send", async ({ conversationId, content, recipientId }) => {
      const message = await sendMessage(conversationId, userId, content);

      io.to(userId).emit("message:new", message);
      io.to(recipientId).emit("message:new", message);

      await createNotification(
        recipientId,
        "MESSAGE",
        "New message",
        content.length > 80 ? content.slice(0, 80) + "..." : content,
        { conversationId, messageId: message.id }
      );

      io.to(recipientId).emit("notification:new", {
        type: "MESSAGE",
        title: "New message",
        body: content
      });
    });
  });

  return io;
}

export function getIO() {
  return io;
}
```

