## `frontend/app.js`

```js
const API = "http://localhost:4000";
let token = localStorage.getItem("token");
let socket = null;
let currentConversationId = null;

function logEvent(data) {
  const el = document.getElementById("events");
  el.textContent = JSON.stringify(data, null, 2) + "\n" + el.textContent;
}

async function register() {
  const email = document.getElementById("email").value;
  const username = document.getElementById("username").value;
  const password = document.getElementById("password").value;

  const res = await fetch(`${API}/auth/register`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, username, password })
  });

  const data = await res.json();
  token = data.token;
  localStorage.setItem("token", token);
  connectSocket();
  showApp(data.user);
}

async function login() {
  const identifier = document.getElementById("identifier").value;
  const password = document.getElementById("password").value;

  const res = await fetch(`${API}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ identifier, password })
  });

  const data = await res.json();
  token = data.token;
  localStorage.setItem("token", token);
  connectSocket();
  showApp(data.user);
}

function showApp(user) {
  document.getElementById("auth").classList.add("hidden");
  document.getElementById("app").classList.remove("hidden");
  document.getElementById("status").textContent = `Logged in as ${user.username}`;
}

function connectSocket() {
  socket = io(API, { auth: { token } });

  socket.on("connect", () => logEvent({ type: "socket_connected" }));
  socket.on("message:new", (msg) => logEvent({ type: "message:new", msg }));
  socket.on("notification:new", (n) => logEvent({ type: "notification:new", n }));
}

async function openConversation() {
  const otherUserId = document.getElementById("otherUserId").value;
  const res = await fetch(`${API}/chat/conversation`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`
    },
    body: JSON.stringify({ otherUserId })
  });

  const data = await res.json();
  currentConversationId = data.id;
  document.getElementById("conversationId").textContent = `Conversation ID: ${data.id}`;
  logEvent({ type: "conversation_opened", data });
}

async function sendMessage() {
  const recipientId = document.getElementById("recipientId").value;
  const content = document.getElementById("message").value;

  socket.emit("message:send", {
    conversationId: currentConversationId,
    recipientId,
    content
  });

  logEvent({ type: "message:sent", content });
}

async function loadNotifications() {
  const res = await fetch(`${API}/notifications`, {
    headers: { Authorization: `Bearer ${token}` }
  });
  const data = await res.json();
  document.getElementById("notifications").textContent = JSON.stringify(data, null, 2);
}

async function createPayment() {
  const recipientId = document.getElementById("payRecipientId").value;
  const amountCents = Number(document.getElementById("amountCents").value);

  const res = await fetch(`${API}/payments/create-intent`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`
    },
    body: JSON.stringify({ recipientId, amountCents })
  });

  const data = await res.json();
  document.getElementById("paymentResult").textContent = JSON.stringify(data, null, 2);
  logEvent({ type: "payment_intent_created", data });
}

if (token) {
  connectSocket();
  document.getElementById("auth").classList.add("hidden");
  document.getElementById("app").classList.remove("hidden");
}
