# 13) Chat screen example

## `mobile/src/screens/ChatScreen.js`
```js
import React, { useEffect, useState } from "react";
import { View, Text, TextInput, Pressable, FlatList } from "react-native";
import client from "../api/client";
import { getSocket } from "../utils/socket";

export default function ChatScreen({ route }) {
  const { conversationId } = route.params;
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    async function load() {
      const res = await client.get(`/messages/${conversationId}`);
      setMessages(res.data);
    }
    load();

    const socket = getSocket();
    socket?.emit("join_conversation", conversationId);

    socket?.on("new_message", (message) => {
      if (message.conversationId === conversationId) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => {
      socket?.off("new_message");
    };
  }, [conversationId]);

  const send = async () => {
    if (!text.trim()) return;

    await client.post("/messages", {
      conversationId,
      content: text,
    });

    setText("");
  };

  return (
    <View style={{ flex: 1, padding: 16 }}>
      <FlatList
        data={messages}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <Text style={{ paddingVertical: 8 }}>
            {item.content}
          </Text>
        )}
      />

      <TextInput
        value={text}
        onChangeText={setText}
        placeholder="Type a message"
        style={{ borderWidth: 1, padding: 12, marginVertical: 12 }}
      />
      <Pressable onPress={send} style={{ padding: 12, backgroundColor: "black" }}>
        <Text style={{ color: "white", textAlign: "center" }}>Send</Text>
      </Pressable>
    </View>
  );
}
```

