### `src/routes/chat.routes.ts`
```ts
import { Router } from "express";
import { authMiddleware, AuthRequest } from "../auth";
import { pool } from "../db";
import { createNotification } from "../services/notification.service";

const router = Router();

router.use(authMiddleware);

router.post("/conversations", async (req: AuthRequest, res) => {
  const { memberIds, type = "direct" } = req.body;
  const creatorId = req.user!.id;

  const conv = await pool.query(
    `INSERT INTO conversations (type, created_by) VALUES ($1, $2) RETURNING *`,
    [type, creatorId]
  );

  const conversation = conv.rows[0];
  const members = [...new Set([creatorId, ...(memberIds || [])])];

  for (const userId of members) {
    await pool.query(
      `INSERT INTO conversation_members (conversation_id, user_id) VALUES ($1, $2)`,
      [conversation.id, userId]
    );
  }

  res.json({ conversation });
});

router.get("/conversations/:id/messages", async (req: AuthRequest, res) => {
  const { id } = req.params;

  const messages = await pool.query(
    `SELECT * FROM messages WHERE conversation_id = $1 ORDER BY created_at DESC LIMIT 50`,
    [id]
  );

  res.json({ messages: messages.rows.reverse() });
});

router.post("/conversations/:id/messages", async (req: AuthRequest, res) => {
  const { id } = req.params;
  const { content } = req.body;
  const senderId = req.user!.id;

  const result = await pool.query(
    `INSERT INTO messages (conversation_id, sender_id, content)
     VALUES ($1, $2, $3)
     RETURNING *`,
    [id, senderId, content]
  );

  const message = result.rows[0];

  const members = await pool.query(
    `SELECT user_id FROM conversation_members WHERE conversation_id = $1 AND user_id <> $2`,
    [id, senderId]
  );

  for (const row of members.rows) {
    await createNotification({
      userId: row.user_id,
      type: "new_message",
      title: "New message",
      body: content.slice(0, 80),
      metadata: { conversationId: id, messageId: message.id }
    });
  }

  res.json({ message });
});

export default router;
```

