## Socket setup

`server/src/sockets/index.ts`

```ts
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { prisma } from "../config/db";
import { createNotification } from "../services/notification.service";

export function initSockets(io: Server) {
  io.use((socket, next) => {
    const token = socket.handshake.auth.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET!) as { userId: string; email: string };
      socket.data.user = decoded;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const { userId } = socket.data.user;
    socket.join(userId);

    socket.on("message:send", async ({ conversationId, text, recipientId }) => {
      const message = await prisma.message.create({
        data: {
          conversationId,
          text,
          senderId: userId
        }
      });

      io.to(recipientId).emit("message:new", message);

      const notification = await createNotification(
        recipientId,
        "New message",
        `You received a message: ${text.slice(0, 40)}`,
        "MESSAGE"
      );

      io.to(recipientId).emit("notification:new", notification);
      socket.emit("message:sent", message);
    });

    socket.on("wallet:purchase", async ({ userId: targetUserId, amount }) => {
      // In production, this should be Stripe webhook verified.
      const { addCoins } = await import("../services/wallet.service");
      const wallet = await addCoins(targetUserId, amount);

      const notification = await createNotification(
        targetUserId,
        "Coins added",
        `Your wallet was credited with ${amount} coins.`,
        "PAYMENT"
      );

      io.to(targetUserId).emit("wallet:update", wallet);
      io.to(targetUserId).emit("notification:new", notification);
    });
  });
}
```

> Note: the `wallet:purchase` socket event is useful for a prototype, but production monetization should use **Stripe checkout + webhook verification**.

