import { Router } from "express";
import { authMiddleware } from "../middleware/auth";
import { getWallet } from "../controllers/wallet.controller";
import { stripe } from "../services/payment.service";

const router = Router();

router.get("/", authMiddleware, getWallet);

router.post("/checkout", authMiddleware, async (req, res) => {
  const { coins } = req.body;
  const priceMap: Record<number, number> = {
    100: 199,
    500: 799,
    1000: 1299
  };

  const amount = priceMap[coins];
  if (!amount) return res.status(400).json({ message: "Invalid coin package" });

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${coins} Coins` },
          unit_amount: amount
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/wallet/success`,
    cancel_url: `${process.env.CLIENT_URL}/wallet/cancel`,
    metadata: {
      userId: req.user!.userId,
      coins: String(coins)
    }
  });

  res.json({ url: session.url });
});

export default router;
```

> For real production crediting, listen to Stripe webhooks and only add coins after payment success is verified.

