import { useEffect, useState } from "react";
import { socket } from "../socket";
import { api } from "../api/client";

export default function ChatWindow({ conversationId, recipientId }: { conversationId: string; recipientId: string }) {
  const [messages, setMessages] = useState<any[]>([]);
  const [text, setText] = useState("");

  useEffect(() => {
    api.get(`/chat/conversations/${conversationId}/messages`)
      .then(r => setMessages(r.data));

    socket.on("message:new", (message) => {
      setMessages(prev => [...prev, message]);
    });

    return () => {
      socket.off("message:new");
    };
  }, [conversationId]);

  const send = () => {
    socket.emit("message:send", { conversationId, text, recipientId });
    setText("");
  };

  return (
    <div>
      <div style={{ minHeight: 300, border: "1px solid #ddd", padding: 12 }}>
        {messages.map(m => (
          <div key={m.id}><strong>{m.senderId}:</strong> {m.text}</div>
        ))}
      </div>

      <input value={text} onChange={e => setText(e.target.value)} />
      <button onClick={send}>Send</button>
    </div>
  );
}
```

