## 6) Real-time server + API

### `server/src/index.js`
```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import bcrypt from "bcryptjs";
import http from "http";
import { Server } from "socket.io";
import Stripe from "stripe";

import { prisma } from "./prisma.js";
import { signToken, requireAuth } from "./auth.js";

dotenv.config();

const app = express();
app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

const onlineUsers = new Map();

io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    onlineUsers.set(userId, socket.id);
    socket.userId = userId;
  });

  socket.on("disconnect", () => {
    if (socket.userId) onlineUsers.delete(socket.userId);
  });
});

function emitToUser(userId, event, payload) {
  const socketId = onlineUsers.get(userId);
  if (socketId) io.to(socketId).emit(event, payload);
}

app.post("/api/register", async (req, res) => {
  const { email, password, name } = req.body;
  const passwordHash = await bcrypt.hash(password, 10);

  const user = await prisma.user.create({
    data: { email, passwordHash, name }
  });

  res.json({ token: signToken(user), user });
});

app.post("/api/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({ token: signToken(user), user });
});

app.get("/api/me", requireAuth, async (req, res) => {
  const user = await prisma.user.findUnique({ where: { id: req.userId } });
  res.json(user);
});

app.get("/api/users", requireAuth, async (req, res) => {
  const users = await prisma.user.findMany({
    select: { id: true, name: true, bio: true, premium: true }
  });
  res.json(users);
});

app.get("/api/messages/:otherUserId", requireAuth, async (req, res) => {
  const me = req.userId;
  const other = req.params.otherUserId;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: other },
        { senderId: other, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.post("/api/messages", requireAuth, async (req, res) => {
  const { receiverId, text } = req.body;

  const message = await prisma.message.create({
    data: { senderId: req.userId, receiverId, text }
  });

  const notification = await prisma.notification.create({
    data: {
      userId: receiverId,
      type: "message",
      text: "You received a new message"
    }
  });

  emitToUser(receiverId, "notification", notification);
  emitToUser(receiverId, "message", message);

  res.json(message);
});

app.get("/api/notifications", requireAuth, async (req, res) => {
  const items = await prisma.notification.findMany({
