```jsx
import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { api } from "../api";
import { socket } from "../socket";

export default function Chat({ user }) {
  const { otherUserId } = useParams();
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    api.get(`/api/messages/${otherUserId}`).then(r => setMessages(r.data));
    const onMessage = (msg) => {
      if (
        (msg.senderId === user.id && msg.receiverId === otherUserId) ||
        (msg.senderId === otherUserId && msg.receiverId === user.id)
      ) {
        setMessages(prev => [...prev, msg]);
      }
    };
    socket.on("message", onMessage);
    return () => socket.off("message", onMessage);
  }, [otherUserId, user.id]);

  const send = async () => {
    await api.post("/api/messages", { receiverId: otherUserId, text });
    setText("");
  };

  return (
    <div>
      <h2>Chat</h2>
      {messages.map(m => <div key={m.id}>{m.text}</div>)}
      <input value={text} onChange={e => setText(e.target.value)} />
      <button onClick={send}>Send</button>
    </div>
  );
}
