## 6) Server `server.js`

```js
require('dotenv').config();

const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const Stripe = require('stripe');
const db = require('./db');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

app.use(express.json());
app.use(express.static('public'));

const PORT = process.env.PORT || 3000;

function createToken(user) {
  return jwt.sign(
    { id: user.id, username: user.username, is_premium: user.is_premium },
    process.env.JWT_SECRET,
    { expiresIn: '7d' }
  );
}

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Missing token' });

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// ----- AUTH -----
app.post('/api/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing fields' });

  const hash = bcrypt.hashSync(password, 10);
  try {
    const stmt = db.prepare('INSERT INTO users (username, password_hash) VALUES (?, ?)');
    const result = stmt.run(username, hash);
    const user = db.prepare('SELECT id, username, is_premium FROM users WHERE id = ?').get(result.lastInsertRowid);
    return res.json({ token: createToken(user), user });
  } catch {
    return res.status(400).json({ error: 'Username already exists' });
  }
});

app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  const user = db.prepare('SELECT * FROM users WHERE username = ?').get(username);
  if (!user || !bcrypt.compareSync(password, user.password_hash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  return res.json({
    token: createToken(user),
    user: { id: user.id, username: user.username, is_premium: user.is_premium }
  });
});

app.get('/api/me', authMiddleware, (req, res) => {
  const user = db.prepare('SELECT id, username, is_premium FROM users WHERE id = ?').get(req.user.id);
  res.json(user);
});

// ----- USERS -----
app.get('/api/users', authMiddleware, (req, res) => {
  const users = db.prepare('SELECT id, username, is_premium FROM users WHERE id != ?').all(req.user.id);
  res.json(users);
});

// ----- MESSAGES -----
app.get('/api/messages/:otherId', authMiddleware, (req, res) => {
  const otherId = Number(req.params.otherId);
  const messages = db.prepare(`
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
  `).all(req.user.id, otherId, otherId, req.user.id);

  res.json(messages);
});

app.post('/api/messages', authMiddleware, (req, res) => {
  const { receiverId, content } = req.body;
  if (!receiverId || !content) return res.status(400).json({ error: 'Missing fields' });

  const insert = db.prepare('INSERT INTO messages (sender_id, receiver_id, content) VALUES (?, ?, ?)');
  const result = insert.run(req.user.id, receiverId, content);

  const message = db.prepare('SELECT * FROM messages WHERE id = ?').get(result.lastInsertRowid);

  // Store notification
  db.prepare('INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)')
    .run(receiverId, 'message', `New message from ${req.user.username}`);

  // Real-time emit to receiver if connected
  io.to(`user_${receiverId}`).emit('new_message', message);
  io.to(`user_${receiverId}`).emit('notification', {
    type: 'message',
    content: `New message from ${req.user.username}`
  });

  res.json(message);
});

// ----- NOTIFICATIONS -----
app.get('/api/notifications', authMiddleware, (req, res) => {
  const notifications = db.prepare(`
    SELECT * FROM notifications
    WHERE user_id = ?
    ORDER BY created_at DESC
    LIMIT 50
  `).all(req.user.id);

  res.json(notifications);
});

app.post('/api/notifications/mark-read', authMiddleware, (req, res) => {
  db.prepare('UPDATE notifications SET read = 1 WHERE user_id = ?').run(req.user.id);
  res.json({ success: true });
});

// ----- MONETIZATION -----
// Create a checkout session
app.post('/api/create-checkout-session', authMiddleware, async (req, res) => {
  try {
    const session = await stripe.checkout.sessions.create({
      mode: 'subscription',
      payment_method_types: ['card'],
      line_items: [
        {
          price_data: {
            currency: 'usd',
            product_data: { name: 'Premium Subscription' },
            recurring: { interval: 'month' },
            unit_amount: 999
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.APP_URL}/?success=1`,
      cancel_url: `${process.env.APP_URL}/?canceled=1`,
      metadata: { userId: String(req.user.id) }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Stripe webhook (minimal placeholder)
app.post('/api/stripe-webhook', express.raw({ type: 'application/json' }), (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const userId = Number(session.metadata.userId);

    db.prepare('UPDATE users SET is_premium = 1 WHERE id = ?').run(userId);
  }

  res.json({ received: true });
});

// ----- SOCKET.IO -----
io.on('connection', (socket) => {
  socket.on('auth', (token) => {
    try {
      const user = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = user;
      socket.join(`user_${user.id}`);
      socket.emit('auth_success', user);
    } catch {
      socket.emit('auth_error', 'Invalid token');
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

