## 8) Frontend logic `public/app.js`

```js
const socket = io();
let token = localStorage.getItem('token');
let currentUser = null;
let selectedUser = null;

async function api(path, method = 'GET', body) {
  const res = await fetch(path, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {})
    },
    body: body ? JSON.stringify(body) : undefined
  });
  return res.json();
}

function showApp() {
  document.getElementById('auth').classList.add('hidden');
  document.getElementById('app').classList.remove('hidden');
}

function renderUsers(users) {
  const ul = document.getElementById('users');
  ul.innerHTML = '';
  users.forEach(u => {
    const li = document.createElement('li');
    li.textContent = `${u.username}${u.is_premium ? ' ⭐' : ''}`;
    li.onclick = () => {
      selectedUser = u;
      loadMessages();
    };
    ul.appendChild(li);
  });
}

function renderNotifications(items) {
  const ul = document.getElementById('notifications');
  ul.innerHTML = '';
  items.forEach(n => {
    const li = document.createElement('li');
    li.textContent = `${n.read ? '' : '• '} ${n.content}`;
    ul.appendChild(li);
  });
}

async function loadUsers() {
  const users = await api('/api/users');
  renderUsers(users);
}

async function loadMessages() {
  if (!selectedUser) return;
  const messages = await api(`/api/messages/${selectedUser.id}`);
  const chatBox = document.getElementById('chatBox');
  chatBox.innerHTML = messages.map(m => `<div><b>${m.sender_id === currentUser.id ? 'Me' : selectedUser.username}:</b> ${m.content}</div>`).join('');
}

async function loadNotifications() {
  const items = await api('/api/notifications');
  renderNotifications(items);
}

async function register() {
  const username = document.getElementById('username').value;
  const password = document.getElementById('password').value;
  const data = await api('/api/register', 'POST', { username, password });
  if (data.token) {
    token = data.token;
    localStorage.setItem('token', token);
    currentUser = data.user;
    afterLogin();
  } else alert(data.error);
}

async function login() {
  const username = document.getElementById('username').value;
  const password = document.getElementById('password').value;
  const data = await api('/api/login', 'POST', { username, password });
  if (data.token) {
    token = data.token;
    localStorage.setItem('token', token);
    currentUser = data.user;
    afterLogin();
  } else alert(data.error);
}

async function afterLogin() {
  const me = await api('/api/me');
  currentUser = me;
  document.getElementById('me').textContent = `${me.username}${me.is_premium ? ' ⭐ Premium' : ''}`;
  showApp();

  socket.emit('auth', token);
  socket.on('new_message', () => {
    if (selectedUser) loadMessages();
  });
  socket.on('notification', () => {
    loadNotifications();
  });

  await loadUsers();
  await loadNotifications();
}

async function sendMessage() {
  if (!selectedUser) return alert('Select a user first');
  const content = document.getElementById('msgInput').value;
  if (!content) return;

  await api('/api/messages', 'POST', {
    receiverId: selectedUser.id,
    content
  });

  document.getElementById('msgInput').value = '';
  loadMessages();
  loadNotifications();
}

async function startPremium() {
  const data = await api('/api/create-checkout-session', 'POST', {});
  if (data.url) window.location.href = data.url;
  else alert(data.error || 'Unable to start checkout');
}

// Auto-login if token exists
if (token) {
  api('/api/me').then(me => {
    currentUser = me;
    document.getElementById('me').textContent = `${me.username}${me.is_premium ? ' ⭐ Premium' : ''}`;
    showApp();
    socket.emit('auth', token);
    loadUsers();
    loadNotifications();
  }).catch(() => localStorage.removeItem('token'));
}
```

