## `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import bcrypt from "bcryptjs";
import { createServer } from "http";
import { Server } from "socket.io";
import Stripe from "stripe";

import { prisma } from "./prisma.js";
import { signToken, requireAuth } from "./auth.js";
import { initSocket, getIO } from "./socket.js";

dotenv.config();

const app = express();
const server = createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true },
});
initSocket(io);

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const PORT = process.env.PORT || 4000;

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

// Socket connections
io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    socket.join(userId);
  });
});

// Auth
app.post("/api/register", async (req, res) => {
  const { email, password, name } = req.body;
  const hash = await bcrypt.hash(password, 10);

  try {
    const user = await prisma.user.create({
      data: { email, password: hash, name },
    });
    res.json({ token: signToken(user), user });
  } catch (e) {
    res.status(400).json({ error: "User already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  res.json({ token: signToken(user), user });
});

// Users list
app.get("/api/users", requireAuth, async (req, res) => {
  const users = await prisma.user.findMany({
    where: { id: { not: req.user.id } },
    select: { id: true, name: true, email: true, premium: true },
  });
  res.json(users);
});

// Messages
app.get("/api/messages/:userId", requireAuth, async (req, res) => {
  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: req.user.id, receiverId: req.params.userId },
        { senderId: req.params.userId, receiverId: req.user.id },
      ],
    },
    orderBy: { createdAt: "asc" },
  });
  res.json(messages);
});

app.post("/api/messages", requireAuth, async (req, res) => {
  const { receiverId, text } = req.body;

  const message = await prisma.message.create({
    data: {
      senderId: req.user.id,
      receiverId,
      text,
    },
  });

  // notification for receiver
  const notification = await prisma.notification.create({
    data: {
      userId: receiverId,
      type: "message",
      content: `New message from user ${req.user.id}`,
    },
  });

  getIO().to(receiverId).emit("notification", notification);
  getIO().to(receiverId).emit("message", message);

  res.json(message);
});

// Notifications
app.get("/api/notifications", requireAuth, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.id },
    orderBy: { createdAt: "desc" },
  });
  res.json(notifications);
});

app.post("/api/notifications/read", requireAuth, async (req, res) => {
  await prisma.notification.updateMany({
    where: { userId: req.user.id, read: false },
    data: { read: true },
  });
  res.json({ ok: true });
});

// Stripe checkout
app.post("/api/create-checkout-session", requireAuth, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    customer_email: req.body.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Premium Boost" },
          unit_amount: 499,
        },
        quantity: 1,
      },
    ],
    success_url: `${process.env.CLIENT_URL}/premium?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/premium?canceled=1`,
    metadata: { userId: req.user.id },
  });

  await prisma.payment.create({
    data: {
      userId: req.user.id,
      stripeSession: session.id,
      amount: 499,
      status: "pending",
    },
  });

  res.json({ url: session.url });
});

// Stripe webhook
app.post(
  "/api/stripe/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const sig = req.headers["stripe-signature"];
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;

      await prisma.user.update({
        where: { id: userId },
        data: { premium: true },
      });

      await prisma.payment.update({
        where: { stripeSession: session.id },
        data: { status: "paid" },
      });

      const notification = await prisma.notification.create({
        data: {
          userId,
          type: "payment",
          content: "Your premium boost is active now!",
        },
      });

      getIO().to(userId).emit("notification", notification);
    }

    res.json({ received: true });
  }
);

server.listen(PORT, () => {
  console.log(`Server running on ${PORT}`);
});
```

