## `client/components/ChatBox.jsx`

```jsx
"use client";

import { useEffect, useState } from "react";
import { api } from "../lib/api";
import { socket } from "../lib/socket";

export default function ChatBox() {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  const token = localStorage.getItem("token");
  const user = JSON.parse(localStorage.getItem("user") || "{}");

  useEffect(() => {
    if (!token) return;
    api("/api/users", "GET", null, token).then(setUsers);

    socket.connect();
    socket.emit("join", user.id);

    socket.on("message", (msg) => {
      if (
        (msg.senderId === user.id && msg.receiverId === selectedUser?.id) ||
        (msg.senderId === selectedUser?.id && msg.receiverId === user.id)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => {
      socket.off("message");
      socket.disconnect();
    };
  }, [selectedUser]);

  const loadMessages = async (u) => {
    setSelectedUser(u);
    const data = await api(`/api/messages/${u.id}`, "GET", null, token);
    setMessages(data);
  };

  const send = async () => {
    const msg = await api("/api/messages", "POST", {
      receiverId: selectedUser.id,
      text,
    }, token);
    setMessages((prev) => [...prev, msg]);
    setText("");
  };

  return (
    <div style={{ display: "flex", gap: 20 }}>
      <div>
        <h3>Users</h3>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => loadMessages(u)}>
              {u.name} {u.premium ? "⭐" : ""}
            </button>
          </div>
        ))}
      </div>

      <div>
        <h3>Chat</h3>
        <div style={{ minHeight: 200, border: "1px solid #ccc", padding: 10 }}>
          {messages.map((m) => (
            <div key={m.id}>{m.text}</div>
          ))}
        </div>
        <input value={text} onChange={(e) => setText(e.target.value)} />
        <button onClick={send} disabled={!selectedUser}>Send</button>
      </div>
    </div>
  );
}
```

