## `server/src/socket.js`
```js
export function setupSocket(io, prisma) {
  io.on("connection", (socket) => {
    socket.on("join", async ({ username }) => {
      socket.data.username = username;
      socket.join(username);
    });

    socket.on("message:send", async ({ room, content, username }) => {
      const user = await prisma.user.findUnique({ where: { username } });
      if (!user) return;

      const message = await prisma.message.create({
        data: { room, content, userId: user.id },
        include: { user: true }
      });

      io.to(room).emit("message:new", {
        id: message.id,
        room: message.room,
        content: message.content,
        username: message.user.username,
        createdAt: message.createdAt
      });

      // Simple notification logic:
      // notify all users except sender who are "in the room" conceptually
      const users = await prisma.user.findMany({ where: { username: { not: username } } });
      for (const u of users) {
        const notif = await prisma.notification.create({
          data: {
            userId: u.id,
            type: "message",
            text: `${username} posted in ${room}: ${content.slice(0, 40)}`
          }
        });

        io.to(u.username).emit("notification:new", notif);
      }
    });

    socket.on("typing", ({ room, username }) => {
      socket.to(room).emit("typing", { room, username });
    });
  });
}
```

