import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import { Server } from "socket.io";
import { PrismaClient } from "@prisma/client";
import { stripe } from "./stripe.js";
import { setupSocket } from "./socket.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

const prisma = new PrismaClient();

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

setupSocket(io, prisma);

// Minimal auth/register
app.post("/api/auth", async (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "username required" });

  const user = await prisma.user.upsert({
    where: { username },
    update: {},
    create: { username }
  });

  res.json(user);
});

app.get("/api/me/:username", async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { username: req.params.username },
    include: {
      notifications: { orderBy: { createdAt: "desc" }, take: 20 }
    }
  });

  if (!user) return res.status(404).json({ error: "not found" });
  res.json(user);
});

app.get("/api/messages/:room", async (req, res) => {
  const messages = await prisma.message.findMany({
    where: { room: req.params.room },
    include: { user: true },
    orderBy: { createdAt: "asc" }
  });
  res.json(messages);
});

app.get("/api/notifications/:username", async (req, res) => {
  const user = await prisma.user.findUnique({ where: { username: req.params.username } });
  if (!user) return res.status(404).json({ error: "not found" });

  const notifications = await prisma.notification.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" }
  });

  res.json(notifications);
});

// mark read
app.post("/api/notifications/:id/read", async (req, res) => {
  const notif = await prisma.notification.update({
    where: { id: req.params.id },
    data: { read: true }
  });
  res.json(notif);
});

// Stripe checkout for premium
app.post("/api/billing/checkout", async (req, res) => {
  const { username } = req.body;
  const user = await prisma.user.findUnique({ where: { username } });
  if (!user) return res.status(404).json({ error: "not found" });

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: `${process.env.CLIENT_URL}?success=1`,
    cancel_url: `${process.env.CLIENT_URL}?canceled=1`,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Premium Membership" },
          unit_amount: 499
        },
        quantity: 1
      }
    ],
    metadata: { username }
  });

  res.json({ url: session.url });
});

// Stripe webhook to unlock premium
app.post("/api/billing/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  const sig = req.headers["stripe-signature"];

  try {
    const event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const username = session.metadata.username;

      await prisma.user.update({
        where: { username },
        data: { premium: true }
      });
    }

    res.json({ received: true });
  } catch (err) {
    res.status(400).send(`Webhook Error: ${err.message}`);
  }
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on http://localhost:${process.env.PORT || 4000}`);
});
