## `client/src/App.jsx`
```jsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { getMe, getMessages, getNotifications, register, startCheckout } from "./api";

const socket = io("http://localhost:4000");

export default function App() {
  const [username, setUsername] = useState("");
  const [input, setInput] = useState("");
  const [room, setRoom] = useState("general");
  const [message, setMessage] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [me, setMe] = useState(null);
  const [typingUser, setTypingUser] = useState("");

  const isLoggedIn = !!me;

  useEffect(() => {
    socket.on("message:new", (msg) => {
      if (msg.room === room) setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification:new", (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    });

    socket.on("typing", ({ username }) => {
      setTypingUser(username);
      setTimeout(() => setTypingUser(""), 1000);
    });

    return () => {
      socket.off("message:new");
      socket.off("notification:new");
      socket.off("typing");
    };
  }, [room]);

  async function handleLogin() {
    const user = await register(username);
    setMe(user);
    socket.emit("join", { username: user.username });

    const existingMessages = await getMessages(room);
    setMessages(existingMessages);

    const notifs = await getNotifications(user.username);
    setNotifications(notifs);
  }

  function joinRoom(nextRoom) {
    setRoom(nextRoom);
    setMessages([]);
    socket.emit("join", { username: me.username });
    getMessages(nextRoom).then(setMessages);
  }

  function sendMessage() {
    if (!message.trim()) return;
    socket.emit("message:send", {
      room,
      content: message,
      username: me.username
    });
    setMessage("");
  }

  async function upgrade() {
    const { url } = await startCheckout(me.username);
    window.location.href = url;
  }

  if (!isLoggedIn) {
    return (
      <div style={{ padding: 24, fontFamily: "sans-serif" }}>
        <h1>Social Messaging App</h1>
        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Choose username"
        />
        <button onClick={handleLogin}>Enter</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <aside style={{ width: 250, borderRight: "1px solid #ddd", padding: 16 }}>
        <h2>
          {me.username} {me.premium ? "⭐ Premium" : ""}
        </h2>
        <button onClick={upgrade} disabled={me.premium}>
          {me.premium ? "Premium Active" : "Upgrade to Premium"}
        </button>

        <h3>Rooms</h3>
        <button onClick={() => joinRoom("general")}>general</button>
        <button onClick={() => joinRoom("random")}>random</button>
        {me.premium && <button onClick={() => joinRoom("private")}>private</button>}

        <h3>Notifications</h3>
        <div style={{ maxHeight: 300, overflow: "auto" }}>
          {notifications.map((n) => (
            <div key={n.id} style={{ marginBottom: 8, padding: 8, background: n.read ? "#eee" : "#ffe58f" }}>
              {n.text}
            </div>
          ))}
        </div>
      </aside>

      <main style={{ flex: 1, padding: 16 }}>
        <h2>Room: {room}</h2>
        {typingUser && <p>{typingUser} is typing...</p>}

        <div style={{ border: "1px solid #ddd", height: "70vh", overflow: "auto", padding: 12 }}>
          {messages.map((m) => (
            <div key={m.id} style={{ marginBottom: 10 }}>
              <b>{m.username}:</b> {m.content}
            </div>
          ))}
        </div>

        <div style={{ marginTop: 12 }}>
          <input
            value={message}
            onChange={(e) => {
              setMessage(e.target.value);
              socket.emit("typing", { room, username: me.username });
            }}
            placeholder="Type a message"
            style={{ width: "70%" }}
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </main>
    </div>
  );
}
