```js
import Database from "better-sqlite3";

export const db = new Database("app.db");

db.exec(`
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  password TEXT NOT NULL,
  coins INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sender_id INTEGER NOT NULL,
  receiver_id INTEGER NOT NULL,
  text TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS notifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  type TEXT NOT NULL,
  text TEXT NOT NULL,
  read INTEGER NOT NULL DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
`);

export function createUser(username, password) {
  const stmt = db.prepare(`INSERT INTO users (username, password) VALUES (?, ?)`);
  const info = stmt.run(username, password);
  return info.lastInsertRowid;
}

export function findUserByUsername(username) {
  return db.prepare(`SELECT * FROM users WHERE username = ?`).get(username);
}

export function findUserById(id) {
  return db.prepare(`SELECT id, username, coins FROM users WHERE id = ?`).get(id);
}

export function saveMessage(senderId, receiverId, text) {
  const info = db
    .prepare(`INSERT INTO messages (sender_id, receiver_id, text) VALUES (?, ?, ?)`)
    .run(senderId, receiverId, text);
  return info.lastInsertRowid;
}

export function getConversation(userA, userB) {
  return db.prepare(`
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
  `).all(userA, userB, userB, userA);
}

export function addNotification(userId, type, text) {
  const info = db
    .prepare(`INSERT INTO notifications (user_id, type, text) VALUES (?, ?, ?)`)
    .run(userId, type, text);
  return info.lastInsertRowid;
}

export function getNotifications(userId) {
  return db.prepare(`
    SELECT * FROM notifications
    WHERE user_id = ?
    ORDER BY created_at DESC
  `).all(userId);
}

export function markNotificationsRead(userId) {
  db.prepare(`UPDATE notifications SET read = 1 WHERE user_id = ?`).run(userId);
}

export function addCoins(userId, amount) {
  db.prepare(`UPDATE users SET coins = coins + ? WHERE id = ?`).run(amount, userId);
}

export function spendCoins(userId, amount) {
  db.prepare(`UPDATE users SET coins = coins - ? WHERE id = ? AND coins >= ?`).run(amount, userId, amount);
}

export function listUsers() {
  return db.prepare(`SELECT id, username, coins FROM users ORDER BY username ASC`).all();
}
