## `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

import {
  createUser,
  findUserByUsername,
  findUserById,
  saveMessage,
  getConversation,
  addNotification,
  getNotifications,
  markNotificationsRead,
  addCoins,
  spendCoins,
  listUsers
} from "./db.js";

import { signToken, authMiddleware } from "./auth.js";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const onlineUsers = new Map(); // userId -> socketId

io.on("connection", (socket) => {
  socket.on("register", (userId) => {
    onlineUsers.set(String(userId), socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

app.post("/auth/register", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing credentials" });

  try {
    const id = createUser(username, password);
    const user = findUserById(id);
    const token = signToken(user);
    res.json({ token, user });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/auth/login", (req, res) => {
  const { username, password } = req.body;
  const user = findUserByUsername(username);
  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }
  const token = signToken(user);
  res.json({ token, user: findUserById(user.id) });
});

app.get("/users", authMiddleware, (req, res) => {
  res.json(listUsers());
});

app.get("/messages/:userId", authMiddleware, (req, res) => {
  res.json(getConversation(req.user.id, Number(req.params.userId)));
});

app.post("/messages", authMiddleware, (req, res) => {
  const { receiverId, text } = req.body;
  if (!receiverId || !text) return res.status(400).json({ error: "Missing message data" });

  const messageId = saveMessage(req.user.id, receiverId, text);
  const notificationId = addNotification(receiverId, "message", `New message from ${req.user.username}`);

  const payload = {
    id: messageId,
    sender_id: req.user.id,
    receiver_id: receiverId,
    text,
    created_at: new Date().toISOString()
  };

  const socketId = onlineUsers.get(String(receiverId));
  if (socketId) {
    io.to(socketId).emit("new_message", payload);
    io.to(socketId).emit("notification", {
      id: notificationId,
      type: "message",
      text: `New message from ${req.user.username}`
    });
  }

  res.json({ ok: true, message: payload });
});

app.get("/notifications", authMiddleware, (req, res) => {
  res.json(getNotifications(req.user.id));
});

app.post("/notifications/read", authMiddleware, (req, res) => {
  markNotificationsRead(req.user.id);
  res.json({ ok: true });
});

// Monetization: mock coin purchase
app.post("/wallet/buy-coins", authMiddleware, (req, res) => {
  const { amount } = req.body;
  if (![10, 50, 100].includes(amount)) {
    return res.status(400).json({ error: "Invalid amount" });
  }

  addCoins(req.user.id, amount);

  const updatedUser = findUserById(req.user.id);
  res.json({
    ok: true,
    user: updatedUser,
    note: `Purchased ${amount} coins`
  });
});

// Monetization: spend coins to send "priority message"
app.post("/wallet/priority-message", authMiddleware, (req, res) => {
  const { receiverId, text } = req.body;
  if (!receiverId || !text) return res.status(400).json({ error: "Missing data" });

  const user = findUserById(req.user.id);
  if (user.coins < 1) return res.status(402).json({ error: "Not enough coins" });

  spendCoins(req.user.id, 1);
  const msgId = saveMessage(req.user.id, receiverId, `[PRIORITY] ${text}`);
  addNotification(receiverId, "priority_message", `Priority message from ${req.user.username}`);

  const updated = findUserById(req.user.id);

  res.json({
    ok: true,
    messageId: msgId,
    user: updated
  });
});

app.get("/me", authMiddleware, (req, res) => {
  res.json(findUserById(req.user.id));
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

