```jsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [text, setText] = useState("");

  useEffect(() => {
    if (!token) return;
    api("/me", "GET", null, token).then(setUser);
    api("/users", "GET", null, token).then(setUsers);
    api("/notifications", "GET", null, token).then(setNotifications);
    socket.emit("register", user?.id);
  }, [token]);

  useEffect(() => {
    socket.on("new_message", (msg) => {
      if (selectedUser && Number(msg.sender_id) === Number(selectedUser.id)) {
        setMessages((m) => [...m, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => {
      socket.off("new_message");
      socket.off("notification");
    };
  }, [selectedUser]);

  async function login(path) {
    const data = await api(path, "POST", { username, password });
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    } else {
      alert(data.error);
    }
  }

  async function loadConversation(u) {
    setSelectedUser(u);
    const data = await api(`/messages/${u.id}`, "GET", null, token);
    setMessages(data);
  }

  async function sendMessage() {
    if (!selectedUser || !text) return;
    const data = await api(
      "/messages",
      "POST",
      { receiverId: selectedUser.id, text },
      token
    );
    if (data.ok) {
      setMessages((m) => [...m, data.message]);
      setText("");
    }
  }

  async function buyCoins(amount) {
    const data = await api("/wallet/buy-coins", "POST", { amount }, token);
    if (data.ok) setUser(data.user);
  }

  async function sendPriorityMessage() {
    if (!selectedUser || !text) return;
    const data = await api(
      "/wallet/priority-message",
      "POST",
      { receiverId: selectedUser.id, text },
      token
    );
    if (data.ok) {
      setUser(data.user);
      setText("");
      alert("Priority message sent");
    } else {
      alert(data.error);
    }
  }

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Social Messaging App</h2>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <button onClick={() => login("/auth/login")}>Login</button>
        <button onClick={() => login("/auth/register")}>Register</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", gap: 20, padding: 20 }}>
      <div style={{ width: 220 }}>
        <h3>Me</h3>
        <div>{user?.username}</div>
        <div>Coins: {user?.coins ?? 0}</div>

        <h3>Users</h3>
        {users.filter((u) => u.id !== user?.id).map((u) => (
          <div key={u.id}>
            <button onClick={() => loadConversation(u)}>{u.username}</button>
          </div>
        ))}

        <h3>Coins</h3>
        <button onClick={() => buyCoins(10)}>Buy 10</button>
        <button onClick={() => buyCoins(50)}>Buy 50</button>
      </div>

      <div style={{ flex: 1 }}>
        <h3>Chat {selectedUser ? `with ${selectedUser.username}` : ""}</h3>
        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 10 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{Number(m.sender_id) === Number(user?.id) ? "You" : selectedUser?.username}:</b>{" "}
              {m.text}
            </div>
          ))}
        </div>

        <input
          style={{ width: "80%" }}
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Type a message"
        />
        <button onClick={sendMessage}>Send</button>
        <button onClick={sendPriorityMessage}>Send Priority (1 coin)</button>

        <h3>Notifications</h3>
        <div style={{ border: "1px solid #ccc", padding: 10, minHeight: 100 }}>
          {notifications.map((n) => (
            <div key={n.id || Math.random()}>{n.text}</div>
          ))}
        </div>
      </div>
    </div>
  );
}
```

