# 10) Messages API

## `app/api/messages/route.ts`

```ts
import { prisma } from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { NextRequest, NextResponse } from "next/server";
import { io } from "@/lib/socket";

export async function GET() {
  const session = await getServerSession(authOptions);
  if (!session?.user?.email) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const user = await prisma.user.findUnique({ where: { email: session.user.email } });
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const messages = await prisma.message.findMany({
    where: {
      OR: [{ senderId: user.id }, { receiverId: user.id }]
    },
    orderBy: { createdAt: "asc" },
    include: { sender: true, receiver: true }
  });

  return NextResponse.json({ messages });
}

export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.email) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const body = await req.json();
  const { content, receiverEmail } = body;

  if (!content || !receiverEmail) {
    return NextResponse.json({ error: "Missing fields" }, { status: 400 });
  }

  const sender = await prisma.user.findUnique({ where: { email: session.user.email } });
  const receiver = await prisma.user.findUnique({ where: { email: receiverEmail } });

  if (!sender || !receiver) {
    return NextResponse.json({ error: "User not found" }, { status: 404 });
  }

  const message = await prisma.message.create({
    data: {
      content,
      senderId: sender.id,
      receiverId: receiver.id
    },
    include: { sender: true, receiver: true }
  });

  io?.emit(`message:${receiver.id}`, message);
  io?.emit(`notification:${receiver.id}`, {
    type: "new_message",
    message: `New message from ${sender.name || sender.email}`
  });

  return NextResponse.json({ message });
}
```

