# 11) Socket.io singleton

## `lib/socket.ts`

```ts
import { Server } from "socket.io";

declare global {
  var io: Server | undefined;
}

export const io = global.io || undefined;

export function initSocket(server: any) {
  if (!global.io) {
    global.io = new Server(server, {
      path: "/api/socketio",
      addTrailingSlash: false,
    });

    global.io.on("connection", (socket) => {
      socket.on("join", (userId) => {
        socket.join(userId);
      });
    });
  }
  return global.io;
}
```

> For a truly minimal deployment, you may later want to run Socket.io in a custom server. For local dev, this structure is enough to demonstrate the pattern.

