        quantity: 1
      }
    ],
    success_url: `${process.env.NEXTAUTH_URL}/chat?premium=success`,
    cancel_url: `${process.env.NEXTAUTH_URL}/chat?premium=cancel`,
    metadata: {
      email: session.user.email
    }
  });

  return NextResponse.json({ url: checkoutSession.url });
}
