"use client";

import { useEffect, useState } from "react";
import { signOut, useSession } from "next-auth/react";
import { io as clientIO } from "socket.io-client";

let socket: any;

export default function ChatPage() {
  const { data: session, status } = useSession();
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");
  const [receiverEmail, setReceiverEmail] = useState("");
  const [notifications, setNotifications] = useState<string[]>([]);

  useEffect(() => {
    if (!session?.user?.id) return;

    socket = clientIO({
      path: "/api/socketio"
    });

    socket.emit("join", session.user.id);

    socket.on(`message:${session.user.id}`, (msg: any) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on(`notification:${session.user.id}`, (notif: any) => {
      setNotifications((prev) => [notif.message, ...prev]);
    });

    return () => {
      socket.disconnect();
    };
  }, [session]);

  useEffect(() => {
    fetch("/api/messages")
      .then((r) => r.json())
      .then((data) => setMessages(data.messages || []));
  }, []);

  const sendMessage = async () => {
    await fetch("/api/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ content, receiverEmail })
    });
    setContent("");
  };

  const buyPremium = async () => {
    const res = await fetch("/api/stripe/checkout", { method: "POST" });
    const data = await res.json();
    if (data.url) window.location.href = data.url;
  };

  if (status === "loading") return <div>Loading...</div>;

  return (
    <div style={{ padding: 24 }}>
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <h1>Chat</h1>
        <div>
          {session?.user?.isPremium ? "Premium User" : "Free User"}
          <button onClick={() => signOut()}>Logout</button>
        </div>
      </div>

      <button onClick={buyPremium}>Upgrade to Premium</button>

      <h3>Notifications</h3>
      <ul>
        {notifications.map((n, i) => <li key={i}>{n}</li>)}
      </ul>

      <h3>Send Message</h3>
      <input
        placeholder="Receiver email"
        value={receiverEmail}
        onChange={(e) => setReceiverEmail(e.target.value)}
      />
      <br />
      <textarea
        placeholder="Message"
        value={content}
        onChange={(e) => setContent(e.target.value)}
      />
      <br />
      <button onClick={sendMessage}>Send</button>

      <h3>Messages</h3>
      <ul>
        {messages.map((m) => (
          <li key={m.id}>
            <b>{m.sender?.email}</b> → <b>{m.receiver?.email}</b>: {m.content}
          </li>
        ))}
      </ul>
    </div>
  );
}
