import jwt from "jsonwebtoken";

const JWT_SECRET = "dev_secret_change_me";

export function signToken(user) {
  return jwt.sign(
    { id: user.id, username: user.username },
    JWT_SECRET,
    { expiresIn: "7d" }
  );
}

export function requireAuth(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: "Missing token" });

  const token = auth.replace("Bearer ", "");
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}
```

## `server/index.js`

```js
import express from "express";
import cors from "cors";
import bcrypt from "bcryptjs";
import { createServer } from "http";
import { Server } from "socket.io";
import { initDB } from "./db.js";
import { requireAuth, signToken } from "./auth.js";

const app = express();
const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: { origin: "http://localhost:5173", credentials: true }
});

app.use(cors({ origin: "http://localhost:5173", credentials: true }));
app.use(express.json());

const db = await initDB();

const onlineUsers = new Map(); // userId -> socketId

function notifyUser(userId, notification) {
  const socketId = onlineUsers.get(String(userId));
  if (socketId) {
    io.to(socketId).emit("notification", notification);
  }
}

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  const passwordHash = await bcrypt.hash(password, 10);

  try {
    const result = await db.run(
      "INSERT INTO users (username, password_hash, credits) VALUES (?, ?, ?)",
      [username, passwordHash, 0]
    );

    const user = { id: result.lastID, username };
    res.json({ token: signToken(user), user });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;

  const user = await db.get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  res.json({
    token: signToken(user),
    user: { id: user.id, username: user.username }
  });
});

app.get("/api/me", requireAuth, async (req, res) => {
  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

app.get("/api/users", requireAuth, async (req, res) => {
  const users = await db.all("SELECT id, username, credits FROM users WHERE id != ?", [req.user.id]);
  res.json(users);
});

app.get("/api/messages/:userId", requireAuth, async (req, res) => {
  const otherId = req.params.userId;
  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (from_user_id = ? AND to_user_id = ?)
        OR (from_user_id = ? AND to_user_id = ?)
     ORDER BY created_at ASC`,
    [req.user.id, otherId, otherId, req.user.id]
  );
  res.json(messages);
});

app.get("/api/notifications", requireAuth, async (req, res) => {
  const notifications = await db.all(
    "SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC LIMIT 20",
    [req.user.id]
  );
  res.json(notifications);
});

app.post("/api/send-message", requireAuth, async (req, res) => {
  const { toUserId, content } = req.body;
  if (!toUserId || !content) return res.status(400).json({ error: "Missing fields" });

  const sender = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);
  if (sender.credits <= 0) {
    return res.status(402).json({ error: "Not enough credits. Buy more to send messages." });
  }

  const msg = await db.run(
    "INSERT INTO messages (from_user_id, to_user_id, content) VALUES (?, ?, ?)",
    [sender.id, toUserId, content]
  );

  await db.run("UPDATE users SET credits = credits - 1 WHERE id = ?", [sender.id]);

  const notificationText = `New message from ${sender.username}: ${content.substring(0, 40)}`;
  const notif = await db.run(
    "INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)",
    [toUserId, "message", notificationText]
  );

  const messagePayload = {
    id: msg.lastID,
    from_user_id: sender.id,
    to_user_id: Number(toUserId),
    content,
    created_at: new Date().toISOString()
  };

  notifyUser(toUserId, {
    id: notif.lastID,
    type: "message",
    content: notificationText
  });

  io.emit("new-message", messagePayload);

  res.json({ ok: true, message: messagePayload });
});

app.post("/api/buy-credits", requireAuth, async (req, res) => {
  const { pack } = req.body; // "small", "medium", "large"
  const packs = {
    small: 10,
    medium: 50,
    large: 120
  };

  const credits = packs[pack];
  if (!credits) return res.status(400).json({ error: "Invalid pack" });

  await db.run("UPDATE users SET credits = credits + ? WHERE id = ?", [credits, req.user.id]);

  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);

  await db.run(
    "INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)",
    [req.user.id, "purchase", `You bought ${credits} credits.`]
  );

  notifyUser(req.user.id, {
    type: "purchase",
    content: `You bought ${credits} credits.`
  });

  res.json({ ok: true, user });
});

io.on("connection", (socket) => {
  socket.on("register", ({ userId }) => {
    onlineUsers.set(String(userId), socket.id);
  });

  socket.on("disconnect", () => {
    for (const [uid, sid] of onlineUsers.entries()) {
      if (sid === socket.id) onlineUsers.delete(uid);
    }
  });
});

httpServer.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

