```jsx
import React, { useEffect, useState } from "react";
import { api, setToken } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setLocalToken] = useState(localStorage.getItem("token") || "");
  const [me, setMe] = useState(null);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;
    setToken(token);
    api.get("/me").then(r => setMe(r.data));
    api.get("/users").then(r => setUsers(r.data));
    api.get("/notifications").then(r => setNotifications(r.data));

    socket.connect();
    socket.on("notification", (n) => setNotifications(prev => [n, ...prev]));
    socket.on("new-message", (msg) => {
      if (
        selectedUser &&
        ((msg.from_user_id === selectedUser.id && msg.to_user_id === me?.id) ||
         (msg.from_user_id === me?.id && msg.to_user_id === selectedUser.id))
      ) {
        setMessages(prev => [...prev, msg]);
      }
    });

    return () => {
      socket.off("notification");
      socket.off("new-message");
      socket.disconnect();
    };
  }, [token, selectedUser, me?.id]);

  useEffect(() => {
    if (me?.id) socket.emit("register", { userId: me.id });
  }, [me]);

  useEffect(() => {
    if (selectedUser) {
      api.get(`/messages/${selectedUser.id}`).then(r => setMessages(r.data));
    }
  }, [selectedUser]);

  async function loginOrRegister(endpoint) {
    const r = await api.post(`/${endpoint}`, { username, password });
    localStorage.setItem("token", r.data.token);
    setLocalToken(r.data.token);
    setMe(r.data.user);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    await api.post("/send-message", { toUserId: selectedUser.id, content });
    setContent("");
    const r = await api.get(`/messages/${selectedUser.id}`);
    setMessages(r.data);
    const meRes = await api.get("/me");
    setMe(meRes.data);
  }

  async function buyCredits(pack) {
    const r = await api.post("/buy-credits", { pack });
    setMe(r.data.user);
  }

  if (!token || !me) {
    return (
      <div className="container">
        <h1>Social Messenger</h1>
        <input placeholder="username" value={username} onChange={e => setUsername(e.target.value)} />
        <input placeholder="password" type="password" value={password} onChange={e => setPassword(e.target.value)} />
        <div className="row">
          <button onClick={() => loginOrRegister("login")}>Login</button>
          <button onClick={() => loginOrRegister("register")}>Register</button>
        </div>
      </div>
    );
  }

  return (
    <div className="app">
      <aside className="sidebar">
        <h2>{me.username}</h2>
        <p>Credits: {me.credits}</p>

        <div className="row">
          <button onClick={() => buyCredits("small")}>Buy 10</button>
          <button onClick={() => buyCredits("medium")}>Buy 50</button>
        </div>

        <h3>Users</h3>
        {users.map(u => (
          <div
            key={u.id}
            className={`user ${selectedUser?.id === u.id ? "active" : ""}`}
            onClick={() => setSelectedUser(u)}
          >
            {u.username}
          </div>
        ))}

        <h3>Notifications</h3>
        <div className="notifList">
          {notifications.map((n, i) => (
            <div key={i} className="notif">{n.content}</div>
          ))}
        </div>
      </aside>

      <main className="chat">
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.username}</h2>
            <div className="messages">
              {messages.map(m => (
                <div key={m.id} className={m.from_user_id === me.id ? "msg me" : "msg"}>
                  {m.content}
                </div>
              ))}
            </div>

            <div className="composer">
              <input value={content} onChange={e => setContent(e.target.value)} placeholder="Type a message..." />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <h2>Select a user to start chatting</h2>
        )}
      </main>
    </div>
  );
}
```

