## `server/src/routes/monetization.js`

```js
import express from "express";
import Stripe from "stripe";
import { auth } from "../middleware/auth.js";
import User from "../models/User.js";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/checkout", auth, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "100 Coins" },
          unit_amount: 499
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/paywall?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/paywall?canceled=1`,
    metadata: {
      userId: req.user.id
    }
  });

  res.json({ url: session.url });
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  const sig = req.headers["stripe-signature"];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    await User.findByIdAndUpdate(userId, { $inc: { coins: 100 } });
  }

  res.json({ received: true });
});

export default router;
```

