import React, { useEffect, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Chat from "./pages/Chat";
import Paywall from "./pages/Paywall";

export default function App() {
  const [page, setPage] = useState("login");
  const [user, setUser] = useState(null);
  const [socket, setSocket] = useState(null);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const saved = localStorage.getItem("user");
    if (saved) {
      setUser(JSON.parse(saved));
      setSocket(createSocket());
      setPage("chat");
    }
  }, []);

  useEffect(() => {
    if (!socket) return;

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => socket.disconnect();
  }, [socket]);

  async function refreshNotifications() {
    const res = await api.get("/chat/notifications");
    setNotifications(res.data);
  }

  if (page === "login") return <Login onLogin={(u) => { setUser(u); setSocket(createSocket()); setPage("chat"); }} onGoRegister={() => setPage("register")} />;
  if (page === "register") return <Register onRegister={(u) => { setUser(u); setSocket(createSocket()); setPage("chat"); }} onGoLogin={() => setPage("login")} />;
  if (page === "paywall") return <Paywall onBack={() => setPage("chat")} />;

  return (
    <Chat
      user={user}
      socket={socket}
      notifications={notifications}
      refreshNotifications={refreshNotifications}
      onPaywall={() => setPage("paywall")}
      onLogout={() => {
        localStorage.removeItem("token");
        localStorage.removeItem("user");
        setUser(null);
        setSocket(null);
        setPage("login");
      }}
    />
  );
}
