```jsx
import React, { useEffect, useState } from "react";
import { api } from "../api";

export default function Chat({ user, socket, notifications, refreshNotifications, onPaywall, onLogout }) {
  const [peerId, setPeerId] = useState("");
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");

  useEffect(() => {
    if (!socket) return;

    socket.on("new_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => socket.off("new_message");
  }, [socket]);

  async function loadThread() {
    const res = await api.get(`/chat/threads/${peerId}`);
    setMessages(res.data);
  }

  function send() {
    socket.emit("send_message", { to: peerId, text });
    setText("");
  }

  return (
    <div>
      <h2>Welcome, {user.displayName}</h2>
      <p>Coins: {user.coins}</p>

      <button onClick={refreshNotifications}>Refresh notifications</button>
      <button onClick={onPaywall}>Buy coins</button>
      <button onClick={onLogout}>Logout</button>

      <div>
        <h3>Notifications</h3>
        {notifications.map((n, i) => (
          <div key={i}>{n.type}: {n.payload?.text || "New event"}</div>
        ))}
      </div>

      <hr />

      <input value={peerId} onChange={(e) => setPeerId(e.target.value)} placeholder="Peer userId" />
      <button onClick={loadThread}>Load chat</button>

      <div style={{ border: "1px solid #ccc", minHeight: 200, marginTop: 10 }}>
        {messages.map((m) => (
          <div key={m._id || m.createdAt}>
            <b>{String(m.from)}</b>: {m.text}
          </div>
        ))}
      </div>

      <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Message" />
      <button onClick={send}>Send</button>
    </div>
  );
}
