```js
import sqlite3 from "sqlite3";
import { open } from "sqlite";

export async function initDb() {
  const db = await open({
    filename: "./app.db",
    driver: sqlite3.Database
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      credits INTEGER NOT NULL DEFAULT 0
    );

    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      senderId INTEGER NOT NULL,
      recipientId INTEGER NOT NULL,
      content TEXT NOT NULL,
      createdAt TEXT NOT NULL,
      FOREIGN KEY(senderId) REFERENCES users(id),
      FOREIGN KEY(recipientId) REFERENCES users(id)
    );

    CREATE TABLE IF NOT EXISTS notifications (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      userId INTEGER NOT NULL,
      type TEXT NOT NULL,
      payload TEXT NOT NULL,
      read INTEGER NOT NULL DEFAULT 0,
      createdAt TEXT NOT NULL,
      FOREIGN KEY(userId) REFERENCES users(id)
    );
  `);

  return db;
}
```

### `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { initDb } from "./db.js";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const db = await initDb();

// In-memory socket mapping: userId -> socketId
const onlineUsers = new Map();

app.post("/api/register", async (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "username required" });

  try {
    const result = await db.run(
      "INSERT INTO users (username, credits) VALUES (?, ?)",
      [username, 0]
    );
    res.json({ id: result.lastID, username, credits: 0 });
  } catch (e) {
    res.status(400).json({ error: "username already exists" });
  }
});

app.get("/api/users", async (_req, res) => {
  const users = await db.all("SELECT id, username, credits FROM users ORDER BY id DESC");
  res.json(users);
});

app.get("/api/messages/:userId", async (req, res) => {
  const userId = Number(req.params.userId);
  const messages = await db.all(
    `
    SELECT m.*, u1.username AS senderUsername, u2.username AS recipientUsername
    FROM messages m
    JOIN users u1 ON u1.id = m.senderId
    JOIN users u2 ON u2.id = m.recipientId
    WHERE m.senderId = ? OR m.recipientId = ?
    ORDER BY m.createdAt ASC
    `,
    [userId, userId]
  );
  res.json(messages);
});

app.get("/api/notifications/:userId", async (req, res) => {
  const userId = Number(req.params.userId);
  const notifications = await db.all(
    "SELECT * FROM notifications WHERE userId = ? ORDER BY createdAt DESC",
    [userId]
  );
  res.json(notifications);
});

// Minimal monetization: buy credits
app.post("/api/buy-credits", async (req, res) => {
  const { userId, amount } = req.body;
  if (!userId || !amount) {
    return res.status(400).json({ error: "userId and amount required" });
  }

  const creditsToAdd = Number(amount);
  if (creditsToAdd <= 0) return res.status(400).json({ error: "invalid amount" });

  await db.run("UPDATE users SET credits = credits + ? WHERE id = ?", [
    creditsToAdd,
    userId
  ]);

  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [userId]);

  // Notify user
  const createdAt = new Date().toISOString();
  await db.run(
    "INSERT INTO notifications (userId, type, payload, read, createdAt) VALUES (?, ?, ?, ?, ?)",
    [userId, "credits_purchase", JSON.stringify({ amount: creditsToAdd }), 0, createdAt]
  );

  const socketId = onlineUsers.get(String(userId));
  if (socketId) {
    io.to(socketId).emit("notification", {
      type: "credits_purchase",
      payload: { amount: creditsToAdd },
      createdAt
    });
  }

  res.json(user);
});

io.on("connection", (socket) => {
  socket.on("identify", async ({ userId }) => {
    if (!userId) return;
    onlineUsers.set(String(userId), socket.id);
    socket.userId = String(userId);
  });

  socket.on("send_message", async ({ senderId, recipientId, content }) => {
    if (!senderId || !recipientId || !content) return;

    const createdAt = new Date().toISOString();
    const result = await db.run(
      "INSERT INTO messages (senderId, recipientId, content, createdAt) VALUES (?, ?, ?, ?)",
      [senderId, recipientId, content, createdAt]
    );

    const sender = await db.get("SELECT username FROM users WHERE id = ?", [senderId]);
    const recipient = await db.get("SELECT username FROM users WHERE id = ?", [recipientId]);

    const message = {
      id: result.lastID,
      senderId,
      recipientId,
      content,
      createdAt,
      senderUsername: sender?.username,
      recipientUsername: recipient?.username
    };

    // Real-time message to recipient and sender
    const recipientSocketId = onlineUsers.get(String(recipientId));
    const senderSocketId = onlineUsers.get(String(senderId));

    if (recipientSocketId) io.to(recipientSocketId).emit("new_message", message);
    if (senderSocketId) io.to(senderSocketId).emit("new_message", message);

    // Store notification for recipient
    await db.run(
      "INSERT INTO notifications (userId, type, payload, read, createdAt) VALUES (?, ?, ?, ?, ?)",
      [
        recipientId,
        "new_message",
        JSON.stringify({ from: sender?.username, content }),
        0,
        createdAt
      ]
    );

    if (recipientSocketId) {
      io.to(recipientSocketId).emit("notification", {
        type: "new_message",
        payload: { from: sender?.username, content },
        createdAt
      });
    }
  });

  socket.on("disconnect", () => {
    if (socket.userId) onlineUsers.delete(socket.userId);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

> Note: `db.js` uses `sqlite` package’s `open()` helper. Add it to dependencies if you use this file exactly:
```bash
npm install sqlite
```

