import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { buyCredits, getMessages, getNotifications, getUsers, register } from "./api";

const socket = io("http://localhost:3001");

export default function App() {
  const [me, setMe] = useState(null);
  const [username, setUsername] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState("");
  const [message, setMessage] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [creditAmount, setCreditAmount] = useState(10);

  useEffect(() => {
    getUsers().then(setUsers);
  }, []);

  useEffect(() => {
    socket.on("new_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification", (notif) => {
      setNotifications((prev) => [notif, ...prev]);
      alert(`Notification: ${notif.type}`);
    });

    return () => {
      socket.off("new_message");
      socket.off("notification");
    };
  }, []);

  useEffect(() => {
    if (me?.id) {
      socket.emit("identify", { userId: me.id });
      getMessages(me.id).then(setMessages);
      getNotifications(me.id).then(setNotifications);
    }
  }, [me]);

  const selectedUser = useMemo(
    () => users.find((u) => String(u.id) === String(selectedUserId)),
    [users, selectedUserId]
  );

  async function handleRegister() {
    const result = await register(username);
    if (result.error) return alert(result.error);
    setMe(result);
    const freshUsers = await getUsers();
    setUsers(freshUsers);
  }

  function sendMessage() {
    if (!selectedUser || !message.trim()) return;
    socket.emit("send_message", {
      senderId: me.id,
      recipientId: selectedUser.id,
      content: message.trim()
    });
    setMessage("");
  }

  async function handleBuyCredits() {
    const result = await buyCredits(me.id, creditAmount);
    if (result.error) return alert(result.error);
    setMe(result);
    const freshUsers = await getUsers();
    setUsers(freshUsers);
  }

  if (!me) {
    return (
      <div style={{ padding: 24, fontFamily: "sans-serif" }}>
        <h1>Social Messenger</h1>
        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Choose a username"
        />
        <button onClick={handleRegister}>Register</button>
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, padding: 24 }}>
      <div>
        <h1>Social Messenger</h1>
        <p>
          Logged in as <b>{me.username}</b> | Credits: <b>{me.credits}</b>
        </p>

        <div style={{ marginBottom: 12 }}>
          <h3>Buy Credits</h3>
          <input
            type="number"
            value={creditAmount}
            onChange={(e) => setCreditAmount(Number(e.target.value))}
          />
          <button onClick={handleBuyCredits}>Buy</button>
        </div>

        <div style={{ marginBottom: 12 }}>
          <h3>Users</h3>
          <select
            value={selectedUserId}
            onChange={(e) => setSelectedUserId(e.target.value)}
          >
            <option value="">Select user</option>
            {users
              .filter((u) => u.id !== me.id)
              .map((u) => (
                <option key={u.id} value={u.id}>
                  {u.username} ({u.credits} credits)
                </option>
              ))}
          </select>
        </div>

        <div>
          <h3>Send Message</h3>
          <input
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder="Type a message"
          />
          <button onClick={sendMessage}>Send</button>
        </div>

        <div style={{ marginTop: 20 }}>
          <h3>Messages</h3>
          <div style={{ maxHeight: 300, overflow: "auto", border: "1px solid #ccc", padding: 8 }}>
            {messages.map((m) => (
              <div key={m.id}>
                <b>{m.senderUsername}</b> → <b>{m.recipientUsername}</b>: {m.content}
              </div>
            ))}
          </div>
        </div>
      </div>

      <div>
        <h3>Notifications</h3>
        <div style={{ maxHeight: 500, overflow: "auto", border: "1px solid #ccc", padding: 8 }}>
          {notifications.map((n) => (
            <div key={n.id || n.createdAt}>
              <b>{n.type}</b> - {JSON.stringify(n.payload)}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
```

