## `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import { Server } from "socket.io";
import { db, initDB } from "./db.js";

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const JWT_SECRET = "dev_secret_change_me";

app.use(cors());
app.use(express.json());

await initDB();

function auth(req, res, next) {
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) return res.status(401).json({ error: "No token" });
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

function makeToken(user) {
  return jwt.sign({ id: user.id, email: user.email }, JWT_SECRET, { expiresIn: "7d" });
}

function notifyUser(userId, payload) {
  io.to(`user:${userId}`).emit("notification", payload);
}

io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    socket.join(`user:${userId}`);
  });
});

// Register
app.post("/api/register", async (req, res) => {
  const { email, password, name } = req.body;
  const existing = db.data.users.find((u) => u.email === email);
  if (existing) return res.status(400).json({ error: "User exists" });

  const hashed = await bcrypt.hash(password, 10);
  const user = {
    id: crypto.randomUUID(),
    email,
    name,
    password: hashed,
    credits: 10
  };

  db.data.users.push(user);
  await db.write();

  res.json({ token: makeToken(user), user: { id: user.id, email, name, credits: user.credits } });
});

// Login
app.post("/api/login", async (req, res) => {
  const { email, password } = req.body;
  const user = db.data.users.find((u) => u.email === email);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({ token: makeToken(user), user: { id: user.id, email, name: user.name, credits: user.credits } });
});

// Get users
app.get("/api/users", auth, (req, res) => {
  res.json(
    db.data.users.map((u) => ({
      id: u.id,
      name: u.name,
      email: u.email,
      credits: u.credits
    }))
  );
});

// Send message
app.post("/api/messages", auth, async (req, res) => {
  const { toUserId, content, priority } = req.body;
  const fromUserId = req.user.id;

  const sender = db.data.users.find((u) => u.id === fromUserId);
  const receiver = db.data.users.find((u) => u.id === toUserId);
  if (!sender || !receiver) return res.status(404).json({ error: "User not found" });

  let cost = priority ? 3 : 0;
  if (sender.credits < cost) return res.status(400).json({ error: "Not enough credits" });

  sender.credits -= cost;

  const message = {
    id: crypto.randomUUID(),
    fromUserId,
    toUserId,
    content,
    priority: !!priority,
    createdAt: new Date().toISOString()
  };

  db.data.messages.push(message);

  if (priority) {
    const note = {
      id: crypto.randomUUID(),
      userId: toUserId,
      type: "priority_message",
      text: `You received a priority message from ${sender.name}`
    };
    db.data.notifications.push(note);
    notifyUser(toUserId, note);
  } else {
    const note = {
      id: crypto.randomUUID(),
      userId: toUserId,
      type: "message",
      text: `New message from ${sender.name}`
    };
    db.data.notifications.push(note);
    notifyUser(toUserId, note);
  }

  await db.write();
  res.json({ message, credits: sender.credits });
});

// Get conversation
app.get("/api/messages/:userId", auth, (req, res) => {
  const me = req.user.id;
  const other = req.params.userId;

  const msgs = db.data.messages.filter(
    (m) =>
      (m.fromUserId === me && m.toUserId === other) ||
      (m.fromUserId === other && m.toUserId === me)
  );

  res.json(msgs);
});

// Buy credits (mock monetization)
app.post("/api/credits/buy", auth, async (req, res) => {
  const { amount } = req.body;
  const user = db.data.users.find((u) => u.id === req.user.id);
  if (!user) return res.status(404).json({ error: "User not found" });

  const creditsToAdd = Number(amount || 0);
  if (creditsToAdd <= 0) return res.status(400).json({ error: "Invalid amount" });

  user.credits += creditsToAdd;
  await db.write();

  notifyUser(user.id, {
    id: crypto.randomUUID(),
    userId: user.id,
    type: "purchase",
    text: `You purchased ${creditsToAdd} credits`
  });

  res.json({ credits: user.credits });
});

server.listen(4000, () => console.log("Server running on http://localhost:4000"));
```

