```jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import { io } from "socket.io-client";

const API = "http://localhost:4000/api";
const socket = io("http://localhost:4000");

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [mode, setMode] = useState("login");
  const [form, setForm] = useState({ email: "", password: "", name: "" });
  const [users, setUsers] = useState([]);
  const [selected, setSelected] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [priority, setPriority] = useState(false);
  const [notifications, setNotifications] = useState([]);

  const authHeaders = { Authorization: `Bearer ${token}` };

  useEffect(() => {
    if (user) {
      socket.emit("join", user.id);
      loadUsers();
    }
  }, [user]);

  useEffect(() => {
    socket.on("notification", (note) => {
      setNotifications((n) => [note, ...n]);
      alert(note.text);
    });
    return () => socket.off("notification");
  }, []);

  async function loadUsers() {
    const res = await axios.get(`${API}/users`, { headers: authHeaders });
    setUsers(res.data.filter((u) => u.id !== user.id));
  }

  async function loadMessages(otherId) {
    const res = await axios.get(`${API}/messages/${otherId}`, { headers: authHeaders });
    setMessages(res.data);
  }

  async function submitAuth(e) {
    e.preventDefault();
    const url = mode === "login" ? "/login" : "/register";
    const payload = mode === "login" ? { email: form.email, password: form.password } : form;

    const res = await axios.post(`${API}${url}`, payload);
    localStorage.setItem("token", res.data.token);
    localStorage.setItem("user", JSON.stringify(res.data.user));
    setToken(res.data.token);
    setUser(res.data.user);
  }

  async function sendMessage() {
    const res = await axios.post(
      `${API}/messages`,
      { toUserId: selected.id, content, priority },
      { headers: authHeaders }
    );
    setMessages((m) => [...m, res.data.message]);
    setUser((u) => ({ ...u, credits: res.data.credits }));
    setContent("");
    setPriority(false);
  }

  async function buyCredits() {
    const amount = prompt("How many credits?");
    if (!amount) return;
    const res = await axios.post(
      `${API}/credits/buy`,
      { amount: Number(amount) },
      { headers: authHeaders }
    );
    setUser((u) => ({ ...u, credits: res.data.credits }));
  }

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h2>{mode === "login" ? "Login" : "Register"}</h2>
        <form onSubmit={submitAuth}>
          {mode === "register" && (
            <input
              placeholder="Name"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
            />
          )}
          <input
            placeholder="Email"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
          />
          <input
            placeholder="Password"
            type="password"
            value={form.password}
            onChange={(e) => setForm({ ...form, password: e.target.value })}
          />
          <button type="submit">{mode}</button>
        </form>
        <button onClick={() => setMode(mode === "login" ? "register" : "login")}>
          Switch to {mode === "login" ? "register" : "login"}
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", gap: 20, padding: 20 }}>
      <div style={{ width: 250 }}>
        <h3>{user.name}</h3>
        <p>Credits: {user.credits}</p>
        <button onClick={buyCredits}>Buy Credits</button>
        <h4>People</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button
              onClick={async () => {
                setSelected(u);
                await loadMessages(u.id);
              }}
            >
              {u.name} ({u.credits} cr)
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>Chat {selected ? `with ${selected.name}` : ""}</h3>
        <div style={{ border: "1px solid #ccc", padding: 10, minHeight: 200 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.fromUserId === user.id ? "Me" : selected?.name}:</b> {m.content}
              {m.priority ? " ⚡" : ""}
            </div>
          ))}
        </div>

        {selected && (
          <div style={{ marginTop: 10 }}>
            <input
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Message..."
            />
            <label style={{ marginLeft: 10 }}>
              <input
                type="checkbox"
                checked={priority}
                onChange={(e) => setPriority(e.target.checked)}
              />
              Priority message (3 credits)
            </label>
            <button onClick={sendMessage}>Send</button>
          </div>
        )}

        <h4>Notifications</h4>
        {notifications.map((n) => (
          <div key={n.id}>{n.text}</div>
        ))}
      </div>
    </div>
  );
}
```

