const JWT_SECRET = 'supersecret';

// In-memory demo storage
const users = [];
const conversations = [];
const messages = [];
const notifications = [];

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

app.post('/auth/register', (req, res) => {
  const { email, password, username } = req.body;
  const user = {
    id: String(users.length + 1),
    email,
    password,
    username
  };
  users.push(user);
  res.json({ success: true });
});

app.post('/auth/login', (req, res) => {
  const { email, password } = req.body;
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const token = jwt.sign({ id: user.id, email: user.email }, JWT_SECRET);
  res.json({ token });
});

app.get('/notifications', authMiddleware, (req, res) => {
  const userNotifications = notifications.filter(n => n.user_id === req.user.id);
  res.json(userNotifications);
});

app.post('/messages', authMiddleware, (req, res) => {
  const { conversation_id, content, recipient_id } = req.body;

  const message = {
    id: String(messages.length + 1),
    conversation_id,
    sender_id: req.user.id,
    content,
    created_at: new Date().toISOString()
  };
  messages.push(message);

  const notification = {
    id: String(notifications.length + 1),
    user_id: recipient_id,
    type: 'message',
    title: 'New message',
    body: content,
    is_read: false,
    created_at: new Date().toISOString()
  };
  notifications.push(notification);

  io.to(`user:${recipient_id}`).emit('message:new', message);
  io.to(`user:${recipient_id}`).emit('notification:new', notification);

  res.json(message);
});

app.post('/billing/create-checkout-session', authMiddleware, async (req, res) => {
  // Minimal stub for Stripe Checkout session creation
  res.json({
    url: 'https://stripe.com/checkout-demo'
  });
});

io.on('connection', (socket) => {
  socket.on('auth', (token) => {
    try {
      const decoded = jwt.verify(token, JWT_SECRET);
      socket.join(`user:${decoded.id}`);
    } catch (err) {
      console.error('Socket auth failed');
    }
  });

  socket.on('message:send', (data) => {
    // For MVP, reuse HTTP endpoint logic in real code
    console.log('Incoming message', data);
  });
});

server.listen(3000, () => {
