## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const path = require("path");
const fs = require("fs");
const Database = require("better-sqlite3");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

const db = new Database(path.join(__dirname, "app.db"));

// --- Init DB ---
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    credits INTEGER NOT NULL DEFAULT 5
  );

  CREATE TABLE IF NOT EXISTS messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sender_id INTEGER NOT NULL,
    recipient_id INTEGER NOT NULL,
    body TEXT NOT NULL,
    premium INTEGER NOT NULL DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(sender_id) REFERENCES users(id),
    FOREIGN KEY(recipient_id) REFERENCES users(id)
  );
`);

function getUserByUsername(username) {
  return db.prepare("SELECT * FROM users WHERE username = ?").get(username);
}

function createUser(username) {
  const stmt = db.prepare("INSERT INTO users (username, credits) VALUES (?, ?)");
  const info = stmt.run(username, 5);
  return db.prepare("SELECT * FROM users WHERE id = ?").get(info.lastInsertRowid);
}

function ensureUser(username) {
  let user = getUserByUsername(username);
  if (!user) user = createUser(username);
  return user;
}

// --- API: login / bootstrap ---
app.post("/api/login", (req, res) => {
  const { username } = req.body || {};
  if (!username || username.trim().length < 2) {
    return res.status(400).json({ error: "Username must be at least 2 characters" });
  }

  const user = ensureUser(username.trim());
  res.json({ user });
});

app.get("/api/users", (req, res) => {
  const users = db.prepare("SELECT id, username, credits FROM users ORDER BY username").all();
  res.json({ users });
});

app.get("/api/messages/:userId", (req, res) => {
  const userId = Number(req.params.userId);

  const messages = db.prepare(`
    SELECT m.*, 
           su.username AS senderName, 
           ru.username AS recipientName
    FROM messages m
    JOIN users su ON su.id = m.sender_id
    JOIN users ru ON ru.id = m.recipient_id
    WHERE m.sender_id = ? OR m.recipient_id = ?
    ORDER BY m.created_at ASC, m.id ASC
  `).all(userId, userId);

  res.json({ messages });
});

// --- Send message ---
// Premium message costs 1 credit from sender
app.post("/api/messages", (req, res) => {
  const { senderId, recipientId, body, premium } = req.body || {};
  const sender = db.prepare("SELECT * FROM users WHERE id = ?").get(senderId);
  const recipient = db.prepare("SELECT * FROM users WHERE id = ?").get(recipientId);

  if (!sender || !recipient) return res.status(400).json({ error: "Invalid users" });
  if (!body || body.trim().length < 1) return res.status(400).json({ error: "Message body required" });

  const isPremium = premium ? 1 : 0;

  if (isPremium && sender.credits < 1) {
    return res.status(402).json({ error: "Not enough credits for premium message" });
  }

  const tx = db.transaction(() => {
    if (isPremium) {
      db.prepare("UPDATE users SET credits = credits - 1 WHERE id = ?").run(senderId);
    }

    const info = db.prepare(`
      INSERT INTO messages (sender_id, recipient_id, body, premium)
      VALUES (?, ?, ?, ?)
    `).run(senderId, recipientId, body.trim(), isPremium);

    const message = db.prepare(`
      SELECT m.*, su.username AS senderName, ru.username AS recipientName
      FROM messages m
      JOIN users su ON su.id = m.sender_id
      JOIN users ru ON ru.id = m.recipient_id
      WHERE m.id = ?
    `).get(info.lastInsertRowid);

    return message;
  });

  const message = tx();

  // Real-time notification to recipient if online
  io.to(`user_${recipientId}`).emit("notification", {
    type: "new_message",
    title: `New message from ${sender.username}`,
    body: body.trim(),
    message
  });

  // Message event to both users
  io.to(`user_${senderId}`).emit("message", message);
  io.to(`user_${recipientId}`).emit("message", message);

  // Balance update for sender
  const updatedSender = db.prepare("SELECT id, username, credits FROM users WHERE id = ?").get(senderId);
  io.to(`user_${senderId}`).emit("credits", updatedSender);

  res.json({ message, sender: updatedSender });
});

// --- Monetization: buy credits ---
// Minimal mock purchase: just add credits locally
app.post("/api/buy-credits", (req, res) => {
  const { userId, amount } = req.body || {};
  const add = Math.max(1, Math.min(100, Number(amount) || 1));

  const user = db.prepare("SELECT * FROM users WHERE id = ?").get(userId);
  if (!user) return res.status(400).json({ error: "Invalid user" });

  db.prepare("UPDATE users SET credits = credits + ? WHERE id = ?").run(add, userId);
  const updated = db.prepare("SELECT id, username, credits FROM users WHERE id = ?").get(userId);

  io.to(`user_${userId}`).emit("credits", updated);
  io.to(`user_${userId}`).emit("notification", {
    type: "purchase",
    title: "Credits added",
    body: `You purchased ${add} credits.`
  });

  res.json({ user: updated });
});

// --- Socket.IO ---
io.on("connection", (socket) => {
  socket.on("register", (userId) => {
    if (!userId) return;
    socket.join(`user_${userId}`);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

