## 5) `public/app.js`

```js
const socket = io();

let me = null;
let selectedUser = null;
let users = [];

const authEl = document.getElementById("auth");
const dashboardEl = document.getElementById("dashboard");
const usernameEl = document.getElementById("username");
const loginBtn = document.getElementById("loginBtn");
const usersEl = document.getElementById("users");
const messagesEl = document.getElementById("messages");
const notificationsEl = document.getElementById("notifications");
const meNameEl = document.getElementById("meName");
const creditsEl = document.getElementById("credits");
const chatHeaderEl = document.getElementById("chatHeader");
const messageBodyEl = document.getElementById("messageBody");
const premiumToggleEl = document.getElementById("premiumToggle");
const sendBtn = document.getElementById("sendBtn");
const buyCreditsBtn = document.getElementById("buyCreditsBtn");

function showNotification(title, body) {
  const div = document.createElement("div");
  div.className = "notification";
  div.innerHTML = `<strong>${title}</strong><div>${body}</div>`;
  notificationsEl.prepend(div);
}

function renderUsers() {
  usersEl.innerHTML = "";
  users
    .filter(u => !me || u.id !== me.id)
    .forEach(u => {
      const btn = document.createElement("button");
      btn.className = "userBtn" + (selectedUser && selectedUser.id === u.id ? " active" : "");
      btn.textContent = `${u.username} (${u.credits} cr)`;
      btn.onclick = () => {
        selectedUser = u;
        chatHeaderEl.textContent = `Chat with ${u.username}`;
        renderUsers();
        loadMessages();
      };
      usersEl.appendChild(btn);
    });
}

function renderMessages(messages) {
  messagesEl.innerHTML = "";
  messages
    .filter(m => m.sender_id === me.id || m.recipient_id === me.id)
    .filter(m => !selectedUser || (
      (m.sender_id === selectedUser.id && m.recipient_id === me.id) ||
      (m.sender_id === me.id && m.recipient_id === selectedUser.id)
    ))
    .forEach(m => {
      const row = document.createElement("div");
      row.className = "message " + (m.sender_id === me.id ? "mine" : "theirs");
      row.innerHTML = `
        <div><strong>${m.senderName}</strong> ${m.premium ? "<span class='badge'>Premium</span>" : ""}</div>
        <div>${m.body}</div>
        <small>${new Date(m.created_at).toLocaleString()}</small>
      `;
      messagesEl.appendChild(row);
    });
  messagesEl.scrollTop = messagesEl.scrollHeight;
}

async function loadUsers() {
  const res = await fetch("/api/users");
  const data = await res.json();
  users = data.users;
  renderUsers();
}

async function loadMessages() {
  if (!me) return;
  const res = await fetch(`/api/messages/${me.id}`);
  const data = await res.json();
  renderMessages(data.messages);
}

async function updateCredits() {
  const res = await fetch("/api/users");
  const data = await res.json();
  users = data.users;
  const updatedMe = users.find(u => u.id === me.id);
  if (updatedMe) {
    me.credits = updatedMe.credits;
    creditsEl.textContent = me.credits;
  }
  renderUsers();
}

loginBtn.onclick = async () => {
  const username = usernameEl.value.trim();
  const res = await fetch("/api/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username })
  });
  const data = await res.json();
  if (data.error) return alert(data.error);

  me = data.user;
  authEl.classList.add("hidden");
  dashboardEl.classList.remove("hidden");
  meNameEl.textContent = me.username;
  creditsEl.textContent = me.credits;

  socket.emit("register", me.id);

  await loadUsers();
  await loadMessages();
};

sendBtn.onclick = async () => {
  if (!me || !selectedUser) return alert("Select a user");
  const body = messageBodyEl.value.trim();
  if (!body) return;

  const res = await fetch("/api/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      senderId: me.id,
      recipientId: selectedUser.id,
      body,
      premium: premiumToggleEl.checked
    })
  });

  const data = await res.json();
  if (data.error) return alert(data.error);

  messageBodyEl.value = "";
  premiumToggleEl.checked = false;
  await loadMessages();
  await updateCredits();
};

buyCreditsBtn.onclick = async () => {
  const res = await fetch("/api/buy-credits", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ userId: me.id, amount: 5 })
  });
  const data = await res.json();
  if (data.error) return alert(data.error);
  me.credits = data.user.credits;
  creditsEl.textContent = me.credits;
  await loadUsers();
};

socket.on("notification", (n) => {
  showNotification(n.title, n.body);
  if (n.type === "new_message") loadMessages();
});

socket.on("message", () => {
  loadMessages();
});

socket.on("credits", (updatedUser) => {
  if (me && updatedUser.id === me.id) {
    me.credits = updatedUser.credits;
    creditsEl.textContent = me.credits;
    loadUsers();
  }
});
```

