## `server/src/routes/messages.js`

```js
import express from "express";
import Message from "../models/Message.js";
import User from "../models/User.js";
import { auth } from "../middleware/auth.js";

export default function messagesRouter(io) {
  const router = express.Router();

  router.get("/", auth, async (req, res) => {
    const myId = req.user.id;
    const messages = await Message.find({
      $or: [{ from: myId }, { to: myId }]
    })
      .sort({ createdAt: -1 })
      .limit(50)
      .populate("from", "name")
      .populate("to", "name");

    res.json(messages);
  });

  router.post("/", auth, async (req, res) => {
    const { to, text, isPriority = false } = req.body;

    const sender = await User.findById(req.user.id);
    if (!sender) return res.status(404).json({ error: "Sender not found" });

    if (isPriority && !sender.premium) {
      return res.status(403).json({ error: "Priority messages require premium" });
    }

    const message = await Message.create({
      from: req.user.id,
      to,
      text,
      isPriority
    });

    const populated = await Message.findById(message._id)
      .populate("from", "name")
      .populate("to", "name");

    io.to(String(to)).emit("message:new", populated);
    io.to(String(to)).emit("notification", {
      type: "message",
      text: `New message from ${sender.name}`
    });

    res.json(populated);
  });

  return router;
}
```

