import React, { useEffect, useState } from "react";
import { api, setAuthToken } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [me, setMe] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [users, setUsers] = useState([]);
  const [to, setTo] = useState("");
  const [text, setText] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (token) {
      setAuthToken(token);
      socket.auth = { token };
      socket.connect();
      socket.emit("join", me?.id);
    }
  }, [token]);

  useEffect(() => {
    socket.on("message:new", (msg) => setMessages((m) => [msg, ...m]));
    socket.on("notification", (n) => setNotifications((x) => [n, ...x]));
    return () => {
      socket.off("message:new");
      socket.off("notification");
    };
  }, []);

  const register = async () => {
    const res = await api.post("/auth/register", { name, email, password });
    loginSuccess(res.data);
  };

  const login = async () => {
    const res = await api.post("/auth/login", { email, password });
    loginSuccess(res.data);
  };

  const loginSuccess = ({ token, user }) => {
    localStorage.setItem("token", token);
    localStorage.setItem("user", JSON.stringify(user));
    setToken(token);
    setMe(user);
    setAuthToken(token);
    socket.emit("join", user.id);
  };

  const loadMessages = async () => {
    const res = await api.get("/messages");
    setMessages(res.data);
  };

  const sendMessage = async () => {
    await api.post("/messages", { to, text });
    setText("");
    loadMessages();
  };

  const buyPremium = async () => {
    const res = await api.post("/billing/create-checkout-session");
    window.location.href = res.data.url;
  };

  if (!me) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Social Messaging App</h2>
        <input placeholder="Name" value={name} onChange={(e) => setName(e.target.value)} />
        <br />
        <input placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <br />
