# 6) Socket server helper

`lib/socket.ts`

```ts
import { Server as IOServer } from "socket.io";
import type { Server as HTTPServer } from "http";

declare global {
  // eslint-disable-next-line no-var
  var io: IOServer | undefined;
}

export function initSocket(server: HTTPServer) {
  if (global.io) return global.io;

  const io = new IOServer(server, {
    cors: {
      origin: "*",
      methods: ["GET", "POST"]
    }
  });

  io.on("connection", (socket) => {
    socket.on("join", (username: string) => {
      socket.join(username);
    });

    socket.on("sendMessage", async (payload) => {
      // payload: { from, to, text }
      io.to(payload.to).emit("newMessage", payload);
      io.to(payload.to).emit("newNotification", {
        type: "message",
        text: `New message from ${payload.from}`
      });
    });

    socket.on("purchaseCompleted", (payload) => {
      io.to(payload.username).emit("newNotification", {
        type: "purchase",
        text: `Thanks for supporting! Your purchase was successful.`
      });
    });
  });

  global.io = io;
  return io;
}
```

