# 15) Chat component

`components/Chat.tsx`

```tsx
"use client";

import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io();

export default function Chat() {
  const [me, setMe] = useState<any>(null);
  const [toUsername, setToUsername] = useState("");
  const [text, setText] = useState("");
  const [messages, setMessages] = useState<any[]>([]);

  useEffect(() => {
    fetch("/api/auth/me").then(r => r.json()).then(data => {
      setMe(data.user);
      if (data.user?.username) socket.emit("join", data.user.username);
    });
  }, []);

  useEffect(() => {
    socket.on("newMessage", (msg) => {
      if (msg.to === me?.username) setMessages((prev) => [msg, ...prev]);
    });

    return () => {
      socket.off("newMessage");
    };
  }, [me]);

  async function send() {
    if (!toUsername || !text) return;

    await fetch("/api/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ toUsername, text })
    });

    socket.emit("sendMessage", {
      from: me.username,
      to: toUsername,
      text
    });

    setText("");
  }

  async function loadMessages() {
    const res = await fetch("/api/messages");
    const data = await res.json();
    setMessages(data.messages || []);
  }

  useEffect(() => {
    if (me) loadMessages();
  }, [me]);

  return (
    <div>
      <h2>Chat</h2>
      <p>Logged in as: {me?.username || "..."}</p>

      <input
        placeholder="to username"
        value={toUsername}
        onChange={(e) => setToUsername(e.target.value)}
      />
      <input
        placeholder="message"
        value={text}
        onChange={(e) => setText(e.target.value)}
      />
      <button onClick={send}>Send</button>

      <h3>Inbox</h3>
      <ul>
        {messages.map((m) => (
          <li key={m.id}>
            {m.text} <small>({new Date(m.createdAt).toLocaleString()})</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

