## `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import bcrypt from "bcryptjs";
import http from "http";
import { Server } from "socket.io";
import { initDb, run, get, all } from "./db.js";
import { signToken, authMiddleware } from "./auth.js";
import { stripe } from "./stripe.js";

dotenv.config();
initDb();

const app = express();
app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL }
});

const onlineUsers = new Map(); // userId -> socket.id

io.on("connection", (socket) => {
  socket.on("register", (userId) => {
    onlineUsers.set(String(userId), socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, sid] of onlineUsers.entries()) {
      if (sid === socket.id) onlineUsers.delete(userId);
    }
  });
});

// Auth
app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  try {
    const hash = await bcrypt.hash(password, 10);
    const result = await run(
      "INSERT INTO users (username, password) VALUES (?, ?)",
      [username, hash]
    );
    const user = await get("SELECT id, username, premium FROM users WHERE id = ?", [result.lastID]);
    res.json({ token: signToken(user), user });
  } catch (e) {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({
    token: signToken(user),
    user: { id: user.id, username: user.username, premium: user.premium }
  });
});

app.get("/api/me", authMiddleware, async (req, res) => {
  const user = await get("SELECT id, username, premium FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

// Users
app.get("/api/users", authMiddleware, async (req, res) => {
  const users = await all("SELECT id, username, premium FROM users WHERE id != ?", [req.user.id]);
  res.json(users);
});

// Messages
app.get("/api/messages/:userId", authMiddleware, async (req, res) => {
  const me = req.user.id;
  const other = Number(req.params.userId);

  const messages = await all(
    `SELECT * FROM messages
     WHERE (senderId = ? AND receiverId = ?)
        OR (senderId = ? AND receiverId = ?)
     ORDER BY createdAt ASC`,
    [me, other, other, me]
  );

  res.json(messages);
});

app.post("/api/messages", authMiddleware, async (req, res) => {
  const { receiverId, content } = req.body;
  if (!receiverId || !content) return res.status(400).json({ error: "Missing fields" });

  // Monetization rule: premium users can send long messages (simple example)
  if (!req.user.premium && content.length > 280) {
    return res.status(403).json({ error: "Upgrade to premium for long messages" });
  }

  const result = await run(
    "INSERT INTO messages (senderId, receiverId, content) VALUES (?, ?, ?)",
    [req.user.id, receiverId, content]
  );

  const message = await get("SELECT * FROM messages WHERE id = ?", [result.lastID]);

  // Real-time delivery
  const receiverSocketId = onlineUsers.get(String(receiverId));
  if (receiverSocketId) {
    io.to(receiverSocketId).emit("message", message);
    io.to(receiverSocketId).emit("notification", {
      type: "message",
      title: "New message",
      body: `${req.user.username}: ${content.slice(0, 80)}`
    });
  }

  res.json(message);
});

// Stripe checkout session
app.post("/api/create-checkout-session", authMiddleware, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    payment_method_types: ["card"],
    line_items: [{ price: process.env.STRIPE_PRICE_ID, quantity: 1 }],
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    metadata: { userId: String(req.user.id) }
  });

  res.json({ url: session.url });
});

// Stripe webhook (minimal placeholder)
app.post("/api/stripe-webhook", express.raw({ type: "application/json" }), async (req, res) => {
  // In production, verify signature here.
  res.sendStatus(200);
});

// Simulate premium upgrade endpoint for MVP/testing
app.post("/api/mock-upgrade", authMiddleware, async (req, res) => {
  await run("UPDATE users SET premium = 1 WHERE id = ?", [req.user.id]);
  res.json({ ok: true });
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on ${process.env.PORT || 4000}`);
});
```

