import React, { useEffect, useState } from "react";
import { api, setAuthToken } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [activeChat, setActiveChat] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [authForm, setAuthForm] = useState({ username: "", password: "" });
  const [mode, setMode] = useState("login");
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;
    setAuthToken(token);
    api.get("/me").then(({ data }) => setUser(data));
    api.get("/users").then(({ data }) => setUsers(data));
  }, [token]);

  useEffect(() => {
    if (!user) return;
    socket.connect();
    socket.emit("register", user.id);

    socket.on("message", (msg) => {
      if (activeChat && Number(activeChat.id) === msg.senderId) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
      if (Notification.permission === "granted") {
        new Notification(n.title, { body: n.body });
      }
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, [user, activeChat]);

  async function authSubmit() {
    const path = mode === "login" ? "/login" : "/register";
    const { data } = await api.post(path, authForm);
    localStorage.setItem("token", data.token);
    setToken(data.token);
    setUser(data.user);
  }

  async function openChat(u) {
    setActiveChat(u);
    const { data } = await api.get(`/messages/${u.id}`);
    setMessages(data);
  }

  async function sendMessage() {
    if (!activeChat) return;
    const { data } = await api.post("/messages", {
      receiverId: activeChat.id,
      content
    });
    setMessages((prev) => [...prev, data]);
    setContent("");
  }

  async function upgrade() {
    // MVP shortcut; replace with Stripe redirect in production
    await api.post("/mock-upgrade");
    const me = await api.get("/me");
    setUser(me.data);
  }

  async function askNotificationPermission() {
    await Notification.requestPermission();
  }

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h2>{mode === "login" ? "Login" : "Register"}</h2>
        <input
          placeholder="username"
          value={authForm.username}
          onChange={(e) => setAuthForm({ ...authForm, username: e.target.value })}
        />
        <input
          placeholder="password"
          type="password"
          value={authForm.password}
          onChange={(e) => setAuthForm({ ...authForm, password: e.target.value })}
        />
        <button onClick={authSubmit}>{mode}</button>
        <button onClick={() => setMode(mode === "login" ? "register" : "login")}>
          switch to {mode === "login" ? "register" : "login"}
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <div style={{ width: 250, borderRight: "1px solid #ddd", padding: 12 }}>
        <h3>{user.username}{user.premium ? " ⭐" : ""}</h3>
        <button onClick={askNotificationPermission}>Enable notifications</button>
        {!user.premium && <button onClick={upgrade}>Upgrade to Premium</button>}
        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>
              {u.username} {u.premium ? "⭐" : ""}
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1, padding: 12, display: "flex", flexDirection: "column" }}>
        <h3>Chat with {activeChat ? activeChat.username : "select a user"}</h3>

        <div style={{ flex: 1, overflow: "auto", border: "1px solid #ddd", padding: 10 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.senderId === user.id ? "Me" : activeChat?.username}</b>: {m.content}
            </div>
          ))}
        </div>

        <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
          <input
            style={{ flex: 1 }}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder={user.premium ? "Type message..." : "Max 280 chars for free users"}
          />
          <button onClick={sendMessage}>Send</button>
        </div>

        <div style={{ marginTop: 20 }}>
          <h4>Notifications</h4>
          {notifications.slice(0, 5).map((n, i) => (
            <div key={i}>{n.title}: {n.body}</div>
          ))}
        </div>
      </div>
    </div>
  );
}
