## `server/src/socket.js`

```js
import { Server } from "socket.io";
import jwt from "jsonwebtoken";

export function createSocket(server, prisma) {
  const io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_ORIGIN,
      methods: ["GET", "POST"]
    }
  });

  io.use((socket, next) => {
    try {
      const token = socket.handshake.auth?.token;
      if (!token) return next(new Error("No token"));
      const user = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = user;
      next();
    } catch {
      next(new Error("Auth failed"));
    }
  });

  io.on("connection", (socket) => {
    socket.join(socket.user.id);

    socket.on("message:send", async ({ receiverId, text }) => {
      if (!receiverId || !text) return;

      const senderId = socket.user.id;

      const sender = await prisma.user.findUnique({ where: { id: senderId } });
      if (!sender) return;

      // MVP monetization rule: if not premium, consume 1 credit per message
      if (!sender.premium) {
        if (sender.credits <= 0) {
          socket.emit("billing:required", { error: "No credits left" });
          return;
        }
        await prisma.user.update({
          where: { id: senderId },
          data: { credits: { decrement: 1 } }
        });
      }

      const message = await prisma.message.create({
        data: { senderId, receiverId, text }
      });

      const payload = {
        id: message.id,
        text: message.text,
        createdAt: message.createdAt,
        senderId,
        receiverId
      };

      io.to(senderId).emit("message:sent", payload);
      io.to(receiverId).emit("message:received", payload);
      io.to(receiverId).emit("notification", {
        type: "message",
        text: `${socket.user.name} sent you a message`
      });

      io.to(senderId).emit("credits:update", {
        credits: (await prisma.user.findUnique({ where: { id: senderId } })).credits
      });
    });

    socket.on("disconnect", () => {});
  });

  return io;
}
```

