```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import { PrismaClient } from "@prisma/client";
import { authRouter } from "./auth.js";
import { authRequired } from "./middleware.js";
import { createSocket } from "./socket.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const prisma = new PrismaClient();

createSocket(server, prisma);

app.use(cors({ origin: process.env.CLIENT_ORIGIN }));
app.use(express.json());

app.use("/auth", authRouter);

app.get("/me", authRequired, async (req, res) => {
  const user = await prisma.user.findUnique({ where: { id: req.user.id } });
  res.json({
    id: user.id,
    email: user.email,
    name: user.name,
    premium: user.premium,
    credits: user.credits
  });
});

app.get("/users", authRequired, async (req, res) => {
  const users = await prisma.user.findMany({
    where: { id: { not: req.user.id } },
    select: { id: true, name: true, email: true, premium: true, credits: true }
  });
  res.json(users);
});

app.get("/messages/:userId", authRequired, async (req, res) => {
  const me = req.user.id;
  const other = req.params.userId;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: other },
        { senderId: other, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.post("/billing/purchase", authRequired, async (req, res) => {
  const { product } = req.body;

  let update = {};
  if (product === "premium") update = { premium: true };
  if (product === "credits10") update = { credits: { increment: 10 } };

  if (Object.keys(update).length === 0) {
    return res.status(400).json({ error: "Invalid product" });
  }

  const user = await prisma.user.update({
    where: { id: req.user.id },
    data: update
  });

  res.json({
    ok: true,
    user: {
      id: user.id,
      premium: user.premium,
      credits: user.credits
    }
  });
});

const port = process.env.PORT || 4000;
server.listen(port, () => console.log(`Server running on http://localhost:${port}`));
