import React, { useEffect, useMemo, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");

  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => (token ? createSocket(token) : null), [token]);

  useEffect(() => {
    async function load() {
      if (!token) return;
      try {
        const me = await api("/me", "GET", token);
        setUser(me);

        const allUsers = await api("/users", "GET", token);
        setUsers(allUsers);
      } catch {
        logout();
      }
    }
    load();
  }, [token]);

  useEffect(() => {
    if (!socket) return;

    socket.on("message:received", (msg) => {
      if (selectedUser?.id === msg.senderId) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("message:sent", (msg) => {
      if (selectedUser?.id === msg.receiverId) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev].slice(0, 5));
    });

    socket.on("billing:required", (data) => {
      setNotifications((prev) => [{ type: "billing", text: data.error }, ...prev].slice(0, 5));
    });

    socket.on("credits:update", async ({ credits }) => {
      setUser((u) => ({ ...u, credits }));
    });

    return () => {
      socket.disconnect();
    };
  }, [socket, selectedUser]);

  async function handleAuth(e) {
    e.preventDefault();
    const path = authMode === "login" ? "/auth/login" : "/auth/register";
    const body = authMode === "login" ? { email, password } : { email, password, name };
    const data = await api(path, "POST", null, body);
    localStorage.setItem("token", data.token);
    setToken(data.token);
    setUser(data.user);
  }

  function logout() {
    localStorage.removeItem("token");
    setToken("");
    setUser(null);
    setUsers([]);
    setSelectedUser(null);
    setMessages([]);
  }

  async function selectUser(u) {
    setSelectedUser(u);
    const msgs = await api(`/messages/${u.id}`, "GET", token);
    setMessages(msgs);
  }

  function sendMessage() {
    if (!socket || !selectedUser || !text.trim()) return;
    socket.emit("message:send", { receiverId: selectedUser.id, text });
    setText("");
  }

  async function purchase(product) {
    const data = await api("/billing/purchase", "POST", token, { product });
    setUser((u) => ({ ...u, premium: data.user.premium, credits: data.user.credits }));
    setNotifications((prev) => [{ type: "billing", text: `Purchased ${product}` }, ...prev].slice(0, 5));
  }

  if (!user) {
    return (
      <div className="container">
        <h1>Social Messaging MVP</h1>

        <div className="card">
          <button onClick={() => setAuthMode("login")}>Login</button>
          <button onClick={() => setAuthMode("register")}>Register</button>

          <form onSubmit={handleAuth} className="form">
            {authMode === "register" && (
              <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Name" />
            )}
            <input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Email" />
            <input value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Password" type="password" />
            <button type="submit">{authMode}</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="container app">
      <header className="topbar">
        <h2>Welcome, {user.name}</h2>
        <div>
          <span className={user.premium ? "badge premium" : "badge"}>{user.premium ? "Premium" : "Standard"}</span>
          <span className="badge">Credits: {user.credits}</span>
          <button onClick={() => purchase("premium")}>Buy Premium</button>
          <button onClick={() => purchase("credits10")}>Buy 10 Credits</button>
          <button onClick={logout}>Logout</button>
        </div>
      </header>

      <div className="layout">
        <aside className="sidebar">
          <h3>Users</h3>
          {users.map((u) => (
            <div
              key={u.id}
              className={`user ${selectedUser?.id === u.id ? "active" : ""}`}
              onClick={() => selectUser(u)}
            >
              {u.name} {u.premium ? "⭐" : ""}
            </div>
          ))}
        </aside>

        <main className="chat">
          <div className="notifications">
            {notifications.map((n, i) => (
              <div key={i} className="notification">
                {n.text}
              </div>
            ))}
          </div>

          {selectedUser ? (
            <>
              <h3>Chat with {selectedUser.name}</h3>
              <div className="messages">
                {messages.map((m) => (
                  <div
                    key={m.id}
                    className={m.senderId === user.id ? "message me" : "message"}
                  >
                    {m.text}
                  </div>
                ))}
              </div>

              <div className="composer">
                <input
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                  placeholder={user.premium ? "Type a message..." : "Uses 1 credit per message"}
                  onKeyDown={(e) => e.key === "Enter" && sendMessage()}
                />
                <button onClick={sendMessage}>Send</button>
              </div>
            </>
          ) : (
            <p>Select a user to start chatting.</p>
          )}
        </main>
      </div>
    </div>
  );
}
```

