# 8) Express app

## `server/src/index.js`

```js
import dotenv from "dotenv";
dotenv.config();

import express from "express";
import cors from "cors";
import http from "http";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import Stripe from "stripe";

import { prisma } from "./prisma.js";
import { auth } from "./auth.js";
import { initSocket } from "./socket.js";

const app = express();
app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const server = http.createServer(app);
const io = initSocket(server);
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

// Auth
app.post("/api/auth/register", async (req, res) => {
  const { email, password, name } = req.body;
  const hash = await bcrypt.hash(password, 10);

  try {
    const user = await prisma.user.create({
      data: { email, passwordHash: hash, name }
    });

    const token = jwt.sign({ id: user.id, email: user.email }, process.env.JWT_SECRET);
    res.json({ token, user: { id: user.id, email: user.email, name: user.name, credits: user.credits } });
  } catch (e) {
    res.status(400).json({ error: "User already exists or invalid data" });
  }
});

app.post("/api/auth/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  const token = jwt.sign({ id: user.id, email: user.email }, process.env.JWT_SECRET);
  res.json({ token, user: { id: user.id, email: user.email, name: user.name, credits: user.credits } });
});

// Get current user
app.get("/api/me", auth, async (req, res) => {
  const user = await prisma.user.findUnique({ where: { id: req.user.id } });
  res.json({ id: user.id, email: user.email, name: user.name, credits: user.credits });
});

// Users list
app.get("/api/users", auth, async (req, res) => {
  const users = await prisma.user.findMany({
    where: { id: { not: req.user.id } },
    select: { id: true, name: true, email: true, credits: true }
  });
  res.json(users);
});

// Messages
app.get("/api/messages/:userId", auth, async (req, res) => {
  const otherId = req.params.userId;
  const userId = req.user.id;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: userId, receiverId: otherId },
        { senderId: otherId, receiverId: userId }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.post("/api/messages", auth, async (req, res) => {
  const { receiverId, text } = req.body;
  const message = await prisma.message.create({
    data: {
      senderId: req.user.id,
      receiverId,
      text
    }
  });

  await prisma.notification.create({
    data: {
      userId: receiverId,
      type: "message",
      text: `New message from ${req.user.email}`
    }
  });

  io.to(receiverId).emit("message", message);
  io.to(receiverId).emit("notification", {
    type: "message",
    text: `New message from ${req.user.email}`
  });

  res.json(message);
});

// Notifications
app.get("/api/notifications", auth, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.id },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

app.post("/api/notifications/:id/read", auth, async (req, res) => {
  const n = await prisma.notification.update({
    where: { id: req.params.id },
    data: { read: true }
  });
  res.json(n);
});

// Billing: create checkout
app.post("/api/billing/create-checkout-session", auth, async (req, res) => {
  const { credits } = req.body; // e.g. 100 credits
  const price = credits === 100 ? 499 : 999; // minimal fixed pricing

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: `${process.env.CLIENT_URL}/billing?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/billing?canceled=1`,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${credits} Credits` },
          unit_amount: price
        },
        quantity: 1
      }
    ],
    metadata: {
      userId: req.user.id,
      credits: String(credits)
    }
  });

  await prisma.purchase.create({
    data: {
      userId: req.user.id,
      stripeSessionId: session.id,
      amount: price,
      status: "pending"
    }
  });

  res.json({ url: session.url });
});

// Stripe webhook
app.post("/api/billing/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  let event = req.body;

  try {
    const sig = req.headers["stripe-signature"];
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.STRIPE_WEBHOOK_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const credits = parseInt(session.metadata.credits, 10);

    await prisma.user.update({
      where: { id: userId },
      data: { credits: { increment: credits } }
    });

    await prisma.purchase.update({
      where: { stripeSessionId: session.id },
      data: { status: "paid" }
    });

    await prisma.notification.create({
      data: {
        userId,
        type: "billing",
        text: `Payment successful. ${credits} credits added.`
      }
    });

    io.to(userId).emit("notification", {
      type: "billing",
      text: `Payment successful. ${credits} credits added.`
    });
  }

  res.json({ received: true });
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
```

