```jsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [text, setText] = useState("");
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      api.get("/me").then(({ data }) => {
        setUser(data);
        const s = createSocket(data.id);
        setSocket(s);

        s.on("message", (msg) => {
          if (
            selectedUser &&
            ((msg.senderId === selectedUser.id && msg.receiverId === data.id) ||
              (msg.senderId === data.id && msg.receiverId === selectedUser.id))
          ) {
            setMessages((prev) => [...prev, msg]);
          }
        });

        s.on("notification", (n) => {
          setNotifications((prev) => [{ id: crypto.randomUUID(), ...n, read: false }, ...prev]);
        });
      });

      api.get("/users").then(({ data }) => setUsers(data));
      api.get("/notifications").then(({ data }) => setNotifications(data));
    }
  }, [selectedUser]);

  const login = async () => {
    const email = prompt("Email");
    const password = prompt("Password");
    const { data } = await api.post("/auth/login", { email, password });
    localStorage.setItem("token", data.token);
    window.location.reload();
  };

  const register = async () => {
    const email = prompt("Email");
    const password = prompt("Password");
    const name = prompt("Name");
    const { data } = await api.post("/auth/register", { email, password, name });
    localStorage.setItem("token", data.token);
    window.location.reload();
  };

  const openChat = async (u) => {
    setSelectedUser(u);
    const { data } = await api.get(`/messages/${u.id}`);
    setMessages(data);
  };

  const send = async () => {
    if (!selectedUser || !text.trim()) return;
    const { data } = await api.post("/messages", {
      receiverId: selectedUser.id,
      text
    });
    setMessages((prev) => [...prev, data]);
    setText("");
  };

  const buyCredits = async () => {
    const { data } = await api.post("/billing/create-checkout-session", { credits: 100 });
    window.location.href = data.url;
  };

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h1>Social Messaging App</h1>
        <button onClick={login}>Login</button>
        <button onClick={register}>Register</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <aside style={{ width: 280, borderRight: "1px solid #ccc", padding: 16 }}>
        <h2>{user.name}</h2>
        <p>Credits: {user.credits}</p>
        <button onClick={buyCredits}>Buy 100 Credits</button>

        <h3>Users</h3>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>
              {u.name} ({u.credits} cr)
            </button>
          </div>
        ))}

        <h3>Notifications</h3>
        {notifications.map((n) => (
          <div key={n.id} style={{ fontSize: 13, marginBottom: 6 }}>
            {n.text}
          </div>
        ))}
      </aside>

      <main style={{ flex: 1, padding: 16 }}>
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.name}</h2>
            <div style={{ height: 400, overflow: "auto", border: "1px solid #ddd", padding: 12 }}>
              {messages.map((m) => (
                <div key={m.id}>
                  <b>{m.senderId === user.id ? "You" : selectedUser.name}:</b> {m.text}
                </div>
              ))}
            </div>

            <div style={{ marginTop: 12 }}>
              <input
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="Type a message"
                style={{ width: "70%" }}
              />
              <button onClick={send}>Send</button>
            </div>
          </>
        ) : (
          <p>Select a user to start chatting.</p>
        )}
      </main>
    </div>
  );
}
