## `server/db.js`
```js
import sqlite3 from "sqlite3";
import { open } from "sqlite";

export const db = await open({
  filename: "./data.sqlite",
  driver: sqlite3.Database
});

export async function initDb() {
  await db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      coins INTEGER DEFAULT 0
    );

    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sender_id INTEGER NOT NULL,
      receiver_id INTEGER NOT NULL,
      body TEXT NOT NULL,
      is_boosted INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
  `);
}
```

> If you want, you can keep `sqlite` package out and use `sqlite3` callbacks, but this version uses `open()` from `sqlite`.  
> Install it with: `npm i sqlite`

So add `sqlite` to dependencies:
```json
"sqlite": "^5.1.1"
```

## `server/index.js`
```js
import dotenv from "dotenv";
dotenv.config();

import express from "express";
import cors from "cors";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import http from "http";
import { Server } from "socket.io";
import { db, initDb } from "./db.js";

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: { origin: "*" }
});

const PORT = process.env.PORT || 4000;
const JWT_SECRET = process.env.JWT_SECRET || "supersecretkey";

app.use(cors());
app.use(express.json());

await initDb();

function makeToken(user) {
  return jwt.sign({ id: user.id, username: user.username }, JWT_SECRET, {
    expiresIn: "7d"
  });
}

function auth(req, res, next) {
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) return res.status(401).json({ error: "Missing token" });

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  const hash = await bcrypt.hash(password, 10);
  try {
    const result = await db.run(
      "INSERT INTO users (username, password_hash) VALUES (?, ?)",
      [username, hash]
    );
    const user = { id: result.lastID, username };
    res.json({ token: makeToken(user), user: { ...user, coins: 0 } });
  } catch (e) {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({
    token: makeToken(user),
    user: { id: user.id, username: user.username, coins: user.coins }
  });
});

app.get("/api/me", auth, async (req, res) => {
  const user = await db.get("SELECT id, username, coins FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

app.get("/api/users", auth, async (req, res) => {
  const users = await db.all("SELECT id, username, coins FROM users WHERE id != ?", [req.user.id]);
  res.json(users);
});

app.get("/api/messages/:otherUserId", auth, async (req, res) => {
  const me = req.user.id;
  const other = Number(req.params.otherUserId);

  const messages = await db.all(
    `
    SELECT * FROM messages
    WHERE (sender_id = ? AND receiver_id = ?)
       OR (sender_id = ? AND receiver_id = ?)
    ORDER BY created_at ASC
    `,
    [me, other, other, me]
  );

  res.json(messages);
});

app.post("/api/send", auth, async (req, res) => {
  const { receiverId, body, boosted = false } = req.body;
  if (!receiverId || !body) return res.status(400).json({ error: "Missing fields" });

  const sender = await db.get("SELECT * FROM users WHERE id = ?", [req.user.id]);

  const boostCost = 5;
  if (boosted && sender.coins < boostCost) {
    return res.status(400).json({ error: "Not enough coins" });
  }

  await db.run("BEGIN TRANSACTION");
  try {
    if (boosted) {
      await db.run("UPDATE users SET coins = coins - ? WHERE id = ?", [boostCost, sender.id]);
    }

    const result = await db.run(
      "INSERT INTO messages (sender_id, receiver_id, body, is_boosted) VALUES (?, ?, ?, ?)",
      [sender.id, receiverId, body, boosted ? 1 : 0]
    );

    const message = await db.get("SELECT * FROM messages WHERE id = ?", [result.lastID]);
    const updatedSender = await db.get("SELECT id, username, coins FROM users WHERE id = ?", [sender.id]);

    await db.run("COMMIT");

    io.to(String(receiverId)).emit("notification", {
      type: "message",
      message: `New message from ${sender.username}`
    });

    io.to(String(receiverId)).emit("message", message);
    io.to(String(sender.id)).emit("message", message);

    res.json({ message, sender: updatedSender });
  } catch (e) {
    await db.run("ROLLBACK");
    res.status(500).json({ error: "Failed to send message" });
  }
});

app.post("/api/purchase-coins", auth, async (req, res) => {
  const { amount = 20 } = req.body;

  // Demo-only: in production, verify payment webhook/receipt here.
  await db.run("UPDATE users SET coins = coins + ? WHERE id = ?", [amount, req.user.id]);
  const user = await db.get("SELECT id, username, coins FROM users WHERE id = ?", [req.user.id]);

  io.to(String(req.user.id)).emit("notification", {
    type: "purchase",
    message: `You purchased ${amount} coins`
  });

  res.json(user);
});

io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    socket.join(String(userId));
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

