```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { api } from "./api";

const SOCKET_URL = "http://localhost:4000";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [activeUser, setActiveUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [body, setBody] = useState("");
  const [boosted, setBoosted] = useState(false);
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => io(SOCKET_URL, { autoConnect: false }), []);

  useEffect(() => {
    if (!token) return;
    api(token).get("/me").then(({ data }) => setUser(data));
  }, [token]);

  useEffect(() => {
    if (!user) return;
    socket.connect();
    socket.emit("join", user.id);

    socket.on("message", (msg) => {
      if (
        activeUser &&
        ((msg.sender_id === user.id && msg.receiver_id === activeUser.id) ||
          (msg.sender_id === activeUser.id && msg.receiver_id === user.id))
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => {
      socket.disconnect();
      socket.off();
    };
  }, [user, activeUser, socket]);

  useEffect(() => {
    if (!token || !user) return;
    api(token).get("/users").then(({ data }) => setUsers(data));
  }, [token, user]);

  useEffect(() => {
    if (!token || !activeUser) return;
    api(token).get(`/messages/${activeUser.id}`).then(({ data }) => setMessages(data));
  }, [token, activeUser]);

  async function handleAuth() {
    const endpoint = authMode === "login" ? "/login" : "/register";
    const { data } = await api().post(endpoint, { username, password });
    localStorage.setItem("token", data.token);
    setToken(data.token);
    setUser(data.user);
  }

  async function sendMessage() {
    const { data } = await api(token).post("/send", {
      receiverId: activeUser.id,
      body,
      boosted
    });

    setMessages((prev) => [...prev, data.message]);
    setUser(data.sender);
    setBody("");
    setBoosted(false);
  }

  async function purchaseCoins() {
    const { data } = await api(token).post("/purchase-coins", { amount: 20 });
    setUser(data);
    setNotifications((prev) => [
      { type: "purchase", message: "Purchased 20 coins" },
      ...prev
    ]);
  }

  if (!user) {
    return (
      <div style={{ padding: 20, fontFamily: "sans-serif" }}>
        <h2>{authMode === "login" ? "Login" : "Register"}</h2>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <br />
        <input
          placeholder="password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <br />
        <button onClick={handleAuth}>{authMode}</button>
        <button onClick={() => setAuthMode(authMode === "login" ? "register" : "login")}>
          switch to {authMode === "login" ? "register" : "login"}
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", fontFamily: "sans-serif", height: "100vh" }}>
      <div style={{ width: 260, borderRight: "1px solid #ddd", padding: 16 }}>
        <h3>{user.username}</h3>
        <p>Coins: {user.coins}</p>
        <button onClick={purchaseCoins}>Buy 20 Coins</button>

        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => setActiveUser(u)}>
              {u.username} {u.coins !== undefined ? `(coins: ${u.coins})` : ""}
            </button>
          </div>
        ))}

        <h4>Notifications</h4>
        <div style={{ fontSize: 12 }}>
          {notifications.slice(0, 5).map((n, i) => (
            <div key={i}>• {n.message}</div>
          ))}
        </div>
      </div>

      <div style={{ flex: 1, padding: 16 }}>
        <h3>Chat {activeUser ? `with ${activeUser.username}` : ""}</h3>

        {!activeUser ? (
          <p>Select a user to start messaging.</p>
        ) : (
          <>
            <div style={{ border: "1px solid #ddd", height: 400, overflow: "auto", padding: 8 }}>
              {messages.map((m) => (
                <div key={m.id} style={{ marginBottom: 8 }}>
                  <b>{m.sender_id === user.id ? "You" : activeUser.username}:</b> {m.body}
                  {m.is_boosted ? " ⭐" : ""}
                </div>
              ))}
            </div>

            <div style={{ marginTop: 12 }}>
              <input
                style={{ width: "60%" }}
                value={body}
                onChange={(e) => setBody(e.target.value)}
                placeholder="Type a message"
              />
              <label style={{ marginLeft: 8 }}>
                <input
                  checked={boosted}
                  onChange={(e) => setBoosted(e.target.checked)}
                  type="checkbox"
                />
                Boosted message (costs 5 coins)
              </label>
              <button onClick={sendMessage} disabled={!body}>
                Send
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
```

