## `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import bcrypt from "bcryptjs";
import { createServer } from "http";
import { Server } from "socket.io";
import { initDB } from "./db.js";
import { signToken, requireAuth } from "./auth.js";
import { makeStripe } from "./stripe.js";

dotenv.config();

const app = express();
app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: { origin: process.env.CLIENT_URL }
});

const db = await initDB();
const stripe = makeStripe(process.env.STRIPE_SECRET_KEY);

const auth = requireAuth(process.env.JWT_SECRET);

const onlineUsers = new Map(); // userId -> socketId

io.on("connection", (socket) => {
  socket.on("join", ({ userId }) => {
    onlineUsers.set(String(userId), socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  const hashed = await bcrypt.hash(password, 10);

  try {
    const result = await db.run(
      "INSERT INTO users (username, password) VALUES (?, ?)",
      [username, hashed]
    );
    const user = { id: result.lastID, username, premium: 0 };
    const token = signToken(user, process.env.JWT_SECRET);
    res.json({ token, user });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const token = signToken(user, process.env.JWT_SECRET);
  res.json({
    token,
    user: { id: user.id, username: user.username, premium: user.premium }
  });
});

app.get("/api/me", auth, async (req, res) => {
  const user = await db.get("SELECT id, username, premium FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

app.get("/api/messages/:room", auth, async (req, res) => {
  const messages = await db.all(
    "SELECT * FROM messages WHERE room = ? ORDER BY id DESC LIMIT 50",
    [req.params.room]
  );
  res.json(messages.reverse());
});

app.post("/api/messages", auth, async (req, res) => {
  const { room, content } = req.body;

  const result = await db.run(
    "INSERT INTO messages (userId, username, room, content) VALUES (?, ?, ?, ?)",
    [req.user.id, req.user.username, room, content]
  );

  const message = {
    id: result.lastID,
    userId: req.user.id,
    username: req.user.username,
    room,
    content,
    createdAt: new Date().toISOString()
  };

  io.emit("message:new", message);
  io.emit("notification", {
    type: "message",
    text: `New message in ${room} from ${req.user.username}`
  });

  res.json(message);
});

app.post("/api/checkout", auth, async (req, res) => {
  const { product } = req.body;

  const priceMap = {
    premium_badge: 500,
    credits_pack: 1000
  };

  const amount = priceMap[product];
  if (!amount) return res.status(400).json({ error: "Invalid product" });

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: product },
          unit_amount: amount
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}?success=1`,
    cancel_url: `${process.env.CLIENT_URL}?canceled=1`,
    metadata: {
      userId: String(req.user.id),
      product
    }
  });

  res.json({ url: session.url });
});

app.post("/api/stripe/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  // Minimal stub: in production verify signature
  // After payment success, update premium or credits in DB.
  res.json({ ok: true });
});

httpServer.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
```

