## `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import { api, setToken } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setLocalToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authForm, setAuthForm] = useState({ username: "", password: "" });
  const [room, setRoom] = useState("general");
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;
    setToken(token);
    api.get("/me").then((res) => setUser(res.data));
    socket.connect();
    socket.on("message:new", (msg) => {
      if (msg.room === room) setMessages((m) => [...m, msg]);
    });
    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev].slice(0, 5));
    });
    socket.emit("join", { userId: user?.id });
    return () => {
      socket.off("message:new");
      socket.off("notification");
      socket.disconnect();
    };
  }, [token, room]);

  useEffect(() => {
    if (user?.id) socket.emit("join", { userId: user.id });
  }, [user]);

  useEffect(() => {
    if (!token) return;
    api.get(`/messages/${room}`).then((res) => setMessages(res.data));
  }, [room, token]);

  async function auth(path) {
    const res = await api.post(path, authForm);
    localStorage.setItem("token", res.data.token);
    setLocalToken(res.data.token);
    setUser(res.data.user);
  }

  async function sendMessage() {
    if (!content.trim()) return;
    await api.post("/messages", { room, content });
    setContent("");
  }

  async function buy(product) {
    const res = await api.post("/checkout", { product });
    window.location.href = res.data.url;
  }

  if (!token) {
    return (
      <div style={{ padding: 24 }}>
        <h1>Social App</h1>
        <input
          placeholder="username"
          value={authForm.username}
          onChange={(e) => setAuthForm({ ...authForm, username: e.target.value })}
        />
        <input
          placeholder="password"
          type="password"
          value={authForm.password}
          onChange={(e) => setAuthForm({ ...authForm, password: e.target.value })}
        />
        <div>
          <button onClick={() => auth("/register")}>Register</button>
          <button onClick={() => auth("/login")}>Login</button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 24, padding: 24 }}>
      <div>
        <h2>Room: {room}</h2>
        <select value={room} onChange={(e) => setRoom(e.target.value)}>
          <option value="general">general</option>
          <option value="sports">sports</option>
          <option value="music">music</option>
        </select>

        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 12, marginTop: 12 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.username}: </b>
              <span>{m.content}</span>
            </div>
          ))}
        </div>

        <div style={{ marginTop: 12 }}>
          <input
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Write a message..."
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </div>

      <div>
        <h3>
          Notifications
          {user?.premium ? " ⭐ Premium" : ""}
        </h3>
        {notifications.map((n, i) => (
          <div key={i} style={{ padding: 8, borderBottom: "1px solid #ddd" }}>
            {n.text}
          </div>
        ))}

        <h3 style={{ marginTop: 24 }}>Monetization</h3>
        <button onClick={() => buy("premium_badge")}>Buy Premium Badge ($5)</button>
        <button onClick={() => buy("credits_pack")}>Buy Credits Pack ($10)</button>
      </div>
    </div>
  );
}
```

