        <div class="kpi-change positive">Real-time calculated</div>
      </div>
      <div class="card">
        <div class="kpi-label">Last Update</div>
        <div class="kpi-value" id="kpiTime">--:--:--</div>
        <div class="kpi-change">Auto-refresh every second</div>
      </div>
    </section>

    <section class="grid">
      <div class="card">
        <div class="panel-title">
          <h2>Real-Time Activity</h2>
          <span class="subtext">Live simulated metrics</span>
        </div>
        <div class="chart-wrap">
          <canvas id="chart" width="1100" height="280"></canvas>
        </div>

        <div class="table-controls">
          <input type="text" id="searchInput" placeholder="Search events..." />
          <select id="filterStatus">
            <option value="">All statuses</option>
            <option value="success">Success</option>
            <option value="warning">Warning</option>
            <option value="danger">Critical</option>
          </select>
        </div>

        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Event</th>
              <th>Status</th>
              <th>Load</th>
            </tr>
          </thead>
          <tbody id="eventTable"></tbody>
        </table>

        <div class="footer-note">Tip: Use the form on the right to manually add new events to the dashboard.</div>
      </div>

      <aside class="card">
        <div class="panel-title">
          <h2>Add Event</h2>
          <span class="subtext">Form handling demo</span>
        </div>

        <form id="eventForm">
          <div>
            <label for="eventName">Event Name</label>
            <input id="eventName" type="text" placeholder="e.g. New order received" required />
          </div>

          <div>
            <label for="eventLoad">Load Percentage</label>
            <input id="eventLoad" type="number" min="0" max="100" placeholder="0-100" required />
          </div>

          <div>
            <label for="eventStatus">Status</label>
            <select id="eventStatus" required>
              <option value="success">Success</option>
              <option value="warning">Warning</option>
              <option value="danger">Critical</option>
            </select>
          </div>

          <button type="submit">Add Event</button>
        </form>
      </aside>
    </section>
  </main>

  <script>
    const chart = document.getElementById('chart');
    const ctx = chart.getContext('2d');

    const kpiEvents = document.getElementById('kpiEvents');
    const kpiLoad = document.getElementById('kpiLoad');
    const kpiSuccess = document.getElementById('kpiSuccess');
    const kpiTime = document.getElementById('kpiTime');
    const eventsChange = document.getElementById('eventsChange');
    const loadChange = document.getElementById('loadChange');

    const eventTable = document.getElementById('eventTable');
    const eventForm = document.getElementById('eventForm');
    const eventName = document.getElementById('eventName');
    const eventLoad = document.getElementById('eventLoad');
    const eventStatus = document.getElementById('eventStatus');
    const searchInput = document.getElementById('searchInput');
    const filterStatus = document.getElementById('filterStatus');

    let events = [];
    let history = Array.from({ length: 30 }, () => Math.floor(Math.random() * 100));
    let lastEventCount = 0;
    let lastAvgLoad = 0;

    function nowTime() {
      return new Date().toLocaleTimeString();
    }

    function badgeClass(status) {
      return status;
    }

    function drawChart() {
      const width = chart.width;
      const height = chart.height;
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = 'rgba(255,255,255,0.06)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      // Plot line
      const maxVal = 100;
      const stepX = width / (history.length - 1);

      // Gradient line
      const gradient = ctx.createLinearGradient(0, 0, width, 0);
      gradient.addColorStop(0, '#38bdf8');
      gradient.addColorStop(1, '#22c55e');

      ctx.beginPath();
      history.forEach((val, i) => {
        const x = i * stepX;
        const y = height - (val / maxVal) * (height - 20) - 10;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = gradient;
      ctx.lineWidth = 3;
      ctx.stroke();

      // Fill area
      ctx.lineTo(width, height);
      ctx.lineTo(0, height);
      ctx.closePath();
      const fill = ctx.createLinearGradient(0, 0, 0, height);
      fill.addColorStop(0, 'rgba(56,189,248,0.25)');
      fill.addColorStop(1, 'rgba(56,189,248,0.02)');
      ctx.fillStyle = fill;
      ctx.fill();

      // Point markers
      history.forEach((val, i) => {
        if (i % 5 !== 0) return;
        const x = i * stepX;
        const y = height - (val / maxVal) * (height - 20) - 10;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#e5e7eb';
        ctx.fill();
      });
    }

    function updateKPIs() {
      const total = events.length;
      const avgLoad = total
        ? Math.round(events.reduce((sum, e) => sum + e.load, 0) / total)
        : 0;
      const successCount = events.filter(e => e.status === 'success').length;
      const successRate = total ? Math.round((successCount / total) * 100) : 0;

      kpiEvents.textContent = total;
      kpiLoad.textContent = `${avgLoad}%`;
      kpiSuccess.textContent = `${successRate}%`;
      kpiTime.textContent = nowTime();

      const eventDelta = total - lastEventCount;
      const loadDelta = avgLoad - lastAvgLoad;

      eventsChange.textContent = `${eventDelta >= 0 ? '+' : ''}${eventDelta}${eventDelta === 1 ? ' event' : ' events'} vs last minute`;
      loadChange.textContent = `${loadDelta >= 0 ? '+' : ''}${loadDelta}% vs previous average`;

      eventsChange.className = `kpi-change ${eventDelta >= 0 ? 'positive' : 'negative'}`;
      loadChange.className = `kpi-change ${loadDelta >= 0 ? 'positive' : 'negative'}`;

      lastEventCount = total;
      lastAvgLoad = avgLoad;
    }

    function renderTable() {
      const searchTerm = searchInput.value.toLowerCase();
      const statusFilter = filterStatus.value;

      const filtered = events.filter(e => {
        const matchesSearch = e.name.toLowerCase().includes(searchTerm);
        const matchesStatus = !statusFilter || e.status === statusFilter;
        return matchesSearch && matchesStatus;
      });

      eventTable.innerHTML = filtered.slice().reverse().map(event => `
        <tr>
          <td>${event.time}</td>
          <td>${event.name}</td>
          <td><span class="badge ${badgeClass(event.status)}">${event.status}</span></td>
          <td>${event.load}%</td>
        </tr>
      `).join('');
    }

    function addEvent(name, load, status) {
      const event = {
        time: nowTime(),
        name,
        load: Number(load),
        status
      };

      events.push(event);
      if (events.length > 100) events.shift();

      history.push(Number(load));
      if (history.length > 30) history.shift();

      drawChart();
      updateKPIs();
      renderTable();
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const name = eventName.value.trim();
      const load = parseInt(eventLoad.value, 10);
      const status = eventStatus.value;

      if (!name || Number.isNaN(load) || load < 0 || load > 100) {
        alert('Please enter a valid event name and load between 0 and 100.');
        return;
      }

      addEvent(name, load, status);

      eventForm.reset();
      eventName.focus();
    });

    searchInput.addEventListener('input', renderTable);
    filterStatus.addEventListener('change', renderTable);

    // Simulated real-time updates
    setInterval(() => {
      const simulatedLoad = Math.max(0, Math.min(100, Math.round(50 + (Math.random() * 40 - 20))));
      const status = simulatedLoad > 80 ? 'danger' : simulatedLoad > 60 ? 'warning' : 'success';
      const labels = {
        success: 'Background sync completed',
        warning: 'API latency increased',
        danger: 'High resource usage detected'
      };

      addEvent(labels[status], simulatedLoad, status);
    }, 1000);

    // Initial seed events
    [
      { name: 'Server boot complete', load: 24, status: 'success' },
      { name: 'New user signup', load: 48, status: 'success' },
      { name: 'Queue delay detected', load: 71, status: 'warning' }
    ].forEach(e => addEvent(e.name, e.load, e.status));

    drawChart();
    updateKPIs();
    renderTable();
  </script>
</body>
</html>
```

