  <script>
    // --- Chart setup ---
    const ctx = document.getElementById("trafficChart").getContext("2d");
    const labels = Array.from({ length: 12 }, (_, i) => `${i * 5}s`);
    const dataPoints = [32, 38, 35, 42, 50, 47, 55, 61, 58, 63, 69, 72];

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [
          {
            label: "Traffic",
            data: dataPoints,
            borderColor: "#38bdf8",
            backgroundColor: "rgba(56, 189, 248, 0.15)",
            tension: 0.35,
            fill: true,
            pointRadius: 3,
            pointBackgroundColor: "#38bdf8"
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.05)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.05)" }
          }
        }
      }
    });

    // --- Metric + chart updates ---
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const latencyEl = document.getElementById("latency");

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function updateMetrics() {
      const activeUsers = randomInt(1220, 1350);
      const req = randomInt(820, 940);
      const error = (Math.random() * 1.2 + 0.8).toFixed(1);
      const latency = randomInt(180, 280);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = req.toLocaleString();
      errorRateEl.textContent = `${error}%`;
      latencyEl.textContent = `${latency}ms`;
    }

    function updateChart() {
      const next = randomInt(30, 90);
      chart.data.datasets[0].data.push(next);
      chart.data.datasets[0].data.shift();

      const now = new Date();
      const label = now.toLocaleTimeString([], { minute: "2-digit", second: "2-digit" });
      chart.data.labels.push(label);
      chart.data.labels.shift();

      chart.update();
    }

    function logEvent(message) {
      const log = document.getElementById("eventLog");
      const li = document.createElement("li");
      li.innerHTML = `<span class="timestamp">[${new Date().toLocaleTimeString()}]</span> ${message}`;
      log.prepend(li);
    }

    setInterval(() => {
      updateMetrics();
      updateChart();
      logEvent("Live data refreshed.");
    }, 1000);

    // --- Form handling ---
    const form = document.getElementById("dashboardForm");
    const successEl = document.getElementById("formSuccess");

    function setError(id, msg) {
      document.getElementById(id).textContent = msg;
    }

    function clearErrors() {
      ["nameError", "emailError", "priorityError", "messageError"].forEach(id => setError(id, ""));
      successEl.textContent = "";
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      const name = document.getElementById("name").value.trim();
      const email = document.getElementById("email").value.trim();
      const priority = document.getElementById("priority").value;
      const message = document.getElementById("message").value.trim();

      let valid = true;

      if (name.length < 2) {
        setError("nameError", "Name must be at least 2 characters.");
        valid = false;
      }

      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        setError("emailError", "Please enter a valid email address.");
        valid = false;
      }

      if (!priority) {
        setError("priorityError", "Please select a priority.");
        valid = false;
      }

      if (message.length < 10) {
        setError("messageError", "Message must be at least 10 characters.");
        valid = false;
      }

      if (!valid) {
        logEvent("Form submission failed validation.");
        return;
      }

      successEl.textContent = "Form submitted successfully!";
      logEvent(`New action submitted by ${name} (${priority} priority).`);

      form.reset();
    });

    // Initial log
    logEvent("Dashboard loaded successfully.");
  </script>
</body>
</html>
