  <script>
    const ctx = document.getElementById("trafficChart").getContext("2d");
    const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
    const dataPoints = labels.map(() => Math.floor(Math.random() * 80) + 20);

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          fill: true,
          tension: 0.35,
          pointRadius: 3,
          pointBackgroundColor: "#7dd3fc"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          }
        }
      }
    });

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const successRateEl = document.getElementById("successRate");
    const avgResponseEl = document.getElementById("avgResponse");
    const activityFeedEl = document.getElementById("activityFeed");
    const healthFeedEl = document.getElementById("healthFeed");
    const activityCountEl = document.getElementById("activityCount");

    const samples = [
      "User signed in",
      "Request processed",
      "New ticket created",
      "Cache refreshed",
      "API endpoint pinged",
      "Background job completed"
    ];

    function addFeedItem(container, title, desc) {
      const now = new Date().toLocaleTimeString();
      const item = document.createElement("div");
      item.className = "feed-item";
      item.innerHTML = `
        <div class="time">${now}</div>
        <div class="title">${title}</div>
        <div class="desc">${desc}</div>
      `;
      container.prepend(item);

      while (container.children.length > 8) {
        container.removeChild(container.lastChild);
      }
    }

    function updateMetrics() {
      const activeUsers = Math.floor(120 + Math.random() * 80);
      const requestsPerMin = Math.floor(40 + Math.random() * 30);
      const successRate = (96 + Math.random() * 3).toFixed(1);
      const avgResponse = Math.floor(120 + Math.random() * 180);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      successRateEl.textContent = `${successRate}%`;
      avgResponseEl.textContent = `${avgResponse} ms`;

      const nextValue = Math.floor(20 + Math.random() * 80);
      trafficChart.data.labels.push("Now");
      trafficChart.data.datasets[0].data.push(nextValue);
      trafficChart.data.labels.shift();
      trafficChart.data.datasets[0].data.shift();
      trafficChart.update();

      const sample = samples[Math.floor(Math.random() * samples.length)];
      addFeedItem(activityFeedEl, sample, `Automated event with status: OK`);
      activityCountEl.textContent = `${Math.floor(Math.random() * 5) + 1} new`;
    }

    function updateHealth() {
      const healthItems = [
        ["Database", "Healthy", "#22c55e"],
        ["API Gateway", "Healthy", "#22c55e"],
        ["Workers", "Degraded", "#f59e0b"],
        ["Cache", "Healthy", "#22c55e"],
        ["Auth Service", "Healthy", "#22c55e"]
      ];

      healthFeedEl.innerHTML = "";
      healthItems.forEach(([name, state, color]) => {
        const item = document.createElement("div");
        item.className = "feed-item";
        item.innerHTML = `
          <div class="title">${name}</div>
          <div class="desc"><span style="color:${color}; font-weight:700;">${state}</span></div>
        `;
        healthFeedEl.appendChild(item);
      });
    }

    const form = document.getElementById("requestForm");
    const nameInput = document.getElementById("name");
    const emailInput = document.getElementById("email");
    const messageInput = document.getElementById("message");
    const priorityInput = document.getElementById("priority");

    const nameError = document.getElementById("nameError");
    const emailError = document.getElementById("emailError");
    const messageError = document.getElementById("messageError");
    const formStatus = document.getElementById("formStatus");

    function validateForm() {
      let valid = true;
      nameError.textContent = "";
      emailError.textContent = "";
      messageError.textContent = "";
      formStatus.textContent = "";

      if (nameInput.value.trim().length < 2) {
        nameError.textContent = "Please enter a valid name.";
        valid = false;
      }

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(emailInput.value.trim())) {
        emailError.textContent = "Please enter a valid email.";
        valid = false;
      }

      if (messageInput.value.trim().length < 10) {
        messageError.textContent = "Message must be at least 10 characters.";
        valid = false;
      }

      return valid;
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      if (!validateForm()) return;

      const priority = priorityInput.value;
      addFeedItem(
        activityFeedEl,
        "Form Submitted",
        `${nameInput.value.trim()} sent a ${priority} priority request.`
      );

      formStatus.textContent = "Request submitted successfully.";
      form.reset();
    });

    updateMetrics();
    updateHealth();
    setInterval(updateMetrics, 3000);
    setInterval(updateHealth, 10000);
  </script>
</body>
</html>
