          fill: true
        }
      ]
    };

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: chartData,
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          }
        }
      }
    });

    function formatCurrency(value) {
      return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: "USD",
        maximumFractionDigits: 0
      }).format(value);
    }

    function updateMetrics() {
      const userDelta = Math.floor(Math.random() * 40 - 10);
      const revenueDelta = Math.floor(Math.random() * 700 + 100);
      const ordersDelta = Math.floor(Math.random() * 8 - 2);
      const latencyDelta = Math.floor(Math.random() * 10 - 5);

      metrics.activeUsers += userDelta;
      metrics.revenue += revenueDelta;
      metrics.orders += ordersDelta;
      metrics.latency = Math.max(10, metrics.latency + latencyDelta);

      activeUsersEl.textContent = metrics.activeUsers.toLocaleString();
      revenueEl.textContent = formatCurrency(metrics.revenue);
      ordersEl.textContent = metrics.orders.toLocaleString();
      latencyEl.textContent = `${metrics.latency}ms`;

      usersChangeEl.textContent = `${userDelta >= 0 ? "+" : ""}${userDelta}`;
      revenueChangeEl.textContent = `+${revenueDelta}`;
      ordersChangeEl.textContent = `${ordersDelta >= 0 ? "+" : ""}${ordersDelta}`;
      latencyChangeEl.textContent = latencyDelta <= 0 ? "Improving" : "Stable";

      usersChangeEl.className = `metric-change ${userDelta >= 0 ? "positive" : "negative"}`;
      revenueChangeEl.className = "metric-change positive";
      ordersChangeEl.className = `metric-change ${ordersDelta >= 0 ? "positive" : "negative"}`;
      latencyChangeEl.className = `metric-change ${latencyDelta <= 0 ? "positive" : "negative"}`;

      const newValue = Math.floor(Math.random() * 20 + 15);
      trafficChart.data.datasets[0].data.push(newValue);
      trafficChart.data.datasets[0].data.shift();
      trafficChart.update();

      const now = new Date().toTimeString().split(" ")[0];
      addEventRow({
        time: now,
        name: "Auto Metric Update",
        type: "info",
        notes: `Traffic: ${newValue} req/min`
      }, false);
    }

    function addEventRow(event, prepend = true) {
      events.unshift(event);
      renderEvents();
      if (prepend) showToast(`Event added: ${event.name}`);
    }

    function renderEvents() {
      const filter = typeFilter.value;
      const filtered = filter === "all"
        ? events
        : events.filter(e => e.type === filter);

      eventsTable.innerHTML = filtered.map(e => `
        <tr>
          <td>${e.time}</td>
          <td>${e.name}</td>
          <td>${e.type}</td>
          <td>${e.notes || ""}</td>
        </tr>
      `).join("");
    }

    function showToast(message) {
      toast.textContent = message;
      toast.style.display = "block";
      clearTimeout(toast._timer);
      toast._timer = setTimeout(() => {
        toast.style.display = "none";
      }, 2500);
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const now = new Date().toTimeString().split(" ")[0];
      addEventRow({
        time: now,
        name: eventName.value.trim(),
        type: eventType.value,
        notes: eventNotes.value.trim()
      });
      eventForm.reset();
    });

    typeFilter.addEventListener("change", renderEvents);

    function updateClock() {
      clock.textContent = new Date().toLocaleString();
    }

    setInterval(() => {
      updateMetrics();
      updateClock();
    }, 3000);

    updateMetrics();
    updateClock();
    renderEvents();
  </script>
</body>
</html>
