        <div class="value" id="systemLoad">0%</div>
        <div class="delta" id="loadBadgeText">Nominal</div>
      </div>
      <div class="card">
        <h3>Errors</h3>
        <div class="value" id="errorCount">0</div>
        <div class="delta" id="errorStatus">No issues detected</div>
      </div>
    </section>

    <section class="grid">
      <div class="panel">
        <h2>Live Traffic</h2>
        <canvas id="trafficChart"></canvas>
      </div>

      <div class="panel">
        <h2>Control Panel</h2>

        <div class="controls">
          <div>
            <label for="timeRange">Time Range</label>
            <select id="timeRange">
              <option value="10">Last 10 points</option>
              <option value="20" selected>Last 20 points</option>
              <option value="50">Last 50 points</option>
            </select>
          </div>
          <div>
            <label for="updateSpeed">Update Speed (ms)</label>
            <input type="number" id="updateSpeed" min="250" step="250" value="1000" />
          </div>
        </div>

