  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const activeDeltaEl = document.getElementById("activeDelta");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const systemLoadEl = document.getElementById("systemLoad");
    const loadBadgeTextEl = document.getElementById("loadBadgeText");
    const errorCountEl = document.getElementById("errorCount");
    const errorStatusEl = document.getElementById("errorStatus");
    const formStatusEl = document.getElementById("formStatus");
    const eventLogEl = document.getElementById("eventLog");

    const timeRangeEl = document.getElementById("timeRange");
    const updateSpeedEl = document.getElementById("updateSpeed");
    const thresholdEl = document.getElementById("threshold");
    const categoryEl = document.getElementById("category");

    const nameEl = document.getElementById("name");
    const emailEl = document.getElementById("email");
    const notesEl = document.getElementById("notes");
    const submitBtn = document.getElementById("submitBtn");

    let timeRange = parseInt(timeRangeEl.value, 10);
    let updateSpeed = parseInt(updateSpeedEl.value, 10);
    let threshold = parseInt(thresholdEl.value, 10);
    let dataPoints = [];

    const labels = [];
    for (let i = 0; i < 50; i++) labels.push("");

    const chartCtx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(chartCtx, {
      type: "line",
      data: {
        labels: labels,
        datasets: [
          {
            label: "Traffic",
            data: [],
            borderColor: "#38bdf8",
            backgroundColor: "rgba(56, 189, 248, 0.15)",
            tension: 0.35,
            fill: true,
            pointRadius: 2
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    function logEvent(message, detail = "") {
      const item = document.createElement("div");
      item.className = "log-item";
      item.innerHTML = `
        ${message}
        <small>${detail || new Date().toLocaleTimeString()}</small>
      `;
      eventLogEl.prepend(item);
    }

    function updateBadge(load) {
      if (load < 50) {
        loadBadgeTextEl.innerHTML = `<span class="badge good">Nominal</span>`;
      } else if (load < 80) {
        loadBadgeTextEl.innerHTML = `<span class="badge warn">Elevated</span>`;
      } else {
        loadBadgeTextEl.innerHTML = `<span class="badge bad">Critical</span>`;
      }
    }

    function renderChart() {
      const visible = dataPoints.slice(-timeRange);
      trafficChart.data.labels = visible.map((_, i) => `t-${visible.length - i - 1}`);
      trafficChart.data.datasets[0].data = visible;
      trafficChart.update();
    }

    function generateData() {
      const activeUsers = Math.floor(120 + Math.random() * 140);
      const requests = Math.floor(50 + Math.random() * 250);
      const load = Math.floor(20 + Math.random() * 90);
      const errors = Math.random() < 0.2 ? Math.floor(Math.random() * 5) : 0;

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requests;
      systemLoadEl.textContent = `${load}%`;
      errorCountEl.textContent = errors;

      activeDeltaEl.textContent = activeUsers > 200 ? "+ high activity" : "- stable";
      errorStatusEl.textContent = errors > 0 ? `${errors} error(s) detected` : "No issues detected";

      updateBadge(load);

      dataPoints.push(requests);
      if (dataPoints.length > 50) dataPoints.shift();
      renderChart();

      if (load >= threshold) {
        logEvent("High load alert", `Load is ${load}% and exceeds threshold ${threshold}%`);
      } else if (errors > 0) {
        logEvent("Error spike detected", `${errors} error(s) reported`);
      }
    }

    let intervalId = setInterval(generateData, updateSpeed);

    timeRangeEl.addEventListener("change", () => {
      timeRange = parseInt(timeRangeEl.value, 10);
      renderChart();
      logEvent("Time range updated", `Showing last ${timeRange} points`);
    });

    updateSpeedEl.addEventListener("change", () => {
      updateSpeed = parseInt(updateSpeedEl.value, 10);
      clearInterval(intervalId);
      intervalId = setInterval(generateData, updateSpeed);
      logEvent("Update speed changed", `New interval: ${updateSpeed} ms`);
    });

    thresholdEl.addEventListener("change", () => {
      threshold = parseInt(thresholdEl.value, 10);
      logEvent("Threshold updated", `Alert threshold set to ${threshold}%`);
    });

    categoryEl.addEventListener("change", () => {
      logEvent("Metric category changed", `Now filtering: ${categoryEl.value}`);
    });

    submitBtn.addEventListener("click", (e) => {
      e.preventDefault();

      const name = nameEl.value.trim();
      const email = emailEl.value.trim();
      const notes = notesEl.value.trim();

      if (!name || !email) {
        formStatusEl.textContent = "Please enter both name and email.";
        formStatusEl.style.background = "rgba(239, 68, 68, 0.12)";
        formStatusEl.style.borderColor = "rgba(239, 68, 68, 0.35)";
        return;
      }

      const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      if (!emailValid) {
        formStatusEl.textContent = "Please enter a valid email address.";
        formStatusEl.style.background = "rgba(239, 68, 68, 0.12)";
        formStatusEl.style.borderColor = "rgba(239, 68, 68, 0.35)";
        return;
      }

      formStatusEl.textContent = `Form submitted successfully by ${name}.`;
      formStatusEl.style.background = "rgba(34, 197, 94, 0.12)";
      formStatusEl.style.borderColor = "rgba(34, 197, 94, 0.35)";

      logEvent("Form submitted", `Name: ${name} | Email: ${email} | Notes: ${notes || "None"}`);

      nameEl.value = "";
      emailEl.value = "";
      notesEl.value = "";
    });

    generateData();
  </script>
</body>
</html>
