<body>
  <header>
    <h1>Real-Time Operations Dashboard</h1>
    <p>Live chart updates, metrics, and form-based event submission</p>
  </header>

  <div class="container">
    <div class="grid">
      <div class="stats">
        <div class="stat">
          <div class="label">Active Users</div>
          <div class="value" id="activeUsers">0</div>
        </div>
        <div class="stat">
          <div class="label">Requests / min</div>
          <div class="value" id="requestsPerMin">0</div>
        </div>
        <div class="stat">
          <div class="label">Error Rate</div>
          <div class="value" id="errorRate">0%</div>
        </div>
        <div class="stat">
          <div class="label">System Status</div>
          <div class="value" id="systemStatus">OK</div>
        </div>
      </div>

      <div class="card chart-card">
        <h2 style="margin-top: 0;">Live Traffic</h2>
        <canvas id="trafficChart"></canvas>
      </div>

      <div class="card form-card">
        <h2 style="margin-top: 0;">Submit Event</h2>
        <form id="eventForm">
          <div>
            <label for="name">Event Name</label>
            <input id="name" name="name" type="text" placeholder="e.g. Server Alert" required />
          </div>

          <div>
            <label for="severity">Severity</label>
            <select id="severity" name="severity" required>
              <option value="info">Info</option>
              <option value="warning">Warning</option>
              <option value="critical">Critical</option>
            </select>
          </div>

          <div>
            <label for="details">Details</label>
            <textarea id="details" name="details" placeholder="Describe the event..." required></textarea>
          </div>

          <button type="submit">Add Event</button>
        </form>
        <div class="status" id="formStatus">No events submitted yet.</div>
      </div>

      <div class="card table-card">
        <h2 style="margin-top: 0;">Recent Events</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Event</th>
              <th>Severity</th>
              <th>Details</th>
            </tr>
          </thead>
          <tbody id="eventsTable"></tbody>
        </table>
      </div>
    </div>
  </div>

  <script>
    // ------- State -------
    const MAX_POINTS = 20;
    const labels = Array.from({ length: MAX_POINTS }, (_, i) => `${i + 1}`);
    const dataPoints = labels.map(() => Math.floor(Math.random() * 100));

    const state = {
      activeUsers: 128,
      requestsPerMin: 312,
      errorRate: 2.1,
      systemStatus: "OK",
      events: []
    };

    // ------- Chart -------
    const ctx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.2)",
          tension: 0.35,
          fill: true,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(55,65,81,0.4)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(55,65,81,0.4)" }
          }
        }
      }
    });

    // ------- DOM refs -------
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const systemStatusEl = document.getElementById("systemStatus");
    const formStatusEl = document.getElementById("formStatus");
    const eventsTableEl = document.getElementById("eventsTable");
    const eventForm = document.getElementById("eventForm");

    function updateStats() {
      activeUsersEl.textContent = state.activeUsers.toLocaleString();
      requestsPerMinEl.textContent = state.requestsPerMin.toLocaleString();
      errorRateEl.textContent = `${state.errorRate.toFixed(1)}%`;
      systemStatusEl.textContent = state.systemStatus;

      if (state.systemStatus === "OK") {
        systemStatusEl.style.color = "#22c55e";
      } else if (state.systemStatus === "WARN") {
        systemStatusEl.style.color = "#f59e0b";
      } else {
        systemStatusEl.style.color = "#ef4444";
      }
    }

    function getSeverityClass(severity) {
      if (severity === "critical") return "bad";
      if (severity === "warning") return "warn";
      return "good";
    }

    function renderEvents() {
      eventsTableEl.innerHTML = "";
      state.events.slice().reverse().forEach(event => {
        const row = document.createElement("tr");
        row.innerHTML = `
          <td>${event.time}</td>
          <td>${event.name}</td>
          <td><span class="pill ${getSeverityClass(event.severity)}">${event.severity}</span></td>
          <td>${event.details}</td>
        `;
        eventsTableEl.appendChild(row);
      });
    }

    function addEvent(event) {
      state.events.push(event);
      if (state.events.length > 10) state.events.shift();
      renderEvents();
    }

    // ------- Form handling -------
    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const severity = document.getElementById("severity").value;
      const details = document.getElementById("details").value.trim();

      if (!name || !details) {
        formStatusEl.textContent = "Please fill in all fields.";
        return;
      }

      const newEvent = {
        time: new Date().toLocaleTimeString(),
        name,
        severity,
        details
      };

      addEvent(newEvent);
      formStatusEl.textContent = `Event "${name}" added successfully.`;

      eventForm.reset();
    });

    // ------- Simulated real-time updates -------
    function simulateRealtimeData() {
      const newValue = Math.floor(50 + Math.random() * 150);
      trafficChart.data.labels.push("");
      trafficChart.data.datasets[0].data.push(newValue);

      if (trafficChart.data.labels.length > MAX_POINTS) {
        trafficChart.data.labels.shift();
        trafficChart.data.datasets[0].data.shift();
      }

      trafficChart.update();

      state.activeUsers = Math.max(50, state.activeUsers + Math.floor(Math.random() * 10 - 4));
      state.requestsPerMin = Math.max(100, newValue + Math.floor(Math.random() * 20));
      state.errorRate = Math.max(0, Math.min(15, state.errorRate + (Math.random() * 2 - 1)));

      if (state.errorRate < 3) {
        state.systemStatus = "OK";
      } else if (state.errorRate < 7) {
        state.systemStatus = "WARN";
      } else {
        state.systemStatus = "ALERT";
      }

      updateStats();
    }

    // Initial render
    updateStats();
    renderEvents();

    // Seed sample events
    addEvent({
      time: new Date().toLocaleTimeString(),
      name: "System Boot",
      severity: "info",
      details: "Dashboard initialized successfully."
    });

    addEvent({
      time: new Date().toLocaleTimeString(),
      name: "API Latency",
      severity: "warning",
      details: "Average API latency exceeded 250ms."
    });

    // Update every 2 seconds
    setInterval(simulateRealtimeData, 2000);
  </script>
</body>
</html>
