  <script>
    const records = [
      { name: "Alpha", category: "sales", value: 120, status: "success", time: new Date() },
      { name: "Beta", category: "support", value: 80, status: "warning", time: new Date() },
      { name: "Gamma", category: "ops", value: 150, status: "success", time: new Date() },
    ];

    const searchInput = document.getElementById("searchInput");
    const categoryFilter = document.getElementById("categoryFilter");
    const resetBtn = document.getElementById("resetBtn");
    const recordForm = document.getElementById("recordForm");

    const totalRecordsEl = document.getElementById("totalRecords");
    const activeUsersEl = document.getElementById("activeUsers");
    const successRateEl = document.getElementById("successRate");
    const avgValueEl = document.getElementById("avgValue");
    const recordsBody = document.getElementById("recordsBody");
    const lastUpdatedEl = document.getElementById("lastUpdated");

    const ctx = document.getElementById("liveChart").getContext("2d");
    const labels = ["Now-5", "Now-4", "Now-3", "Now-2", "Now-1", "Now"];
    const dataPoints = [30, 45, 38, 52, 49, 61];

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Live Metric",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#38bdf8"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    function formatTime(date) {
      return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    }

    function renderTable() {
      const search = searchInput.value.toLowerCase();
      const category = categoryFilter.value;

      const filtered = records.filter(record => {
        const matchesSearch = record.name.toLowerCase().includes(search);
        const matchesCategory = category === "all" || record.category === category;
        return matchesSearch && matchesCategory;
      });

      recordsBody.innerHTML = filtered.map(record => `
        <tr>
          <td>${record.name}</td>
          <td><span class="badge">${record.category}</span></td>
          <td>$${record.value}</td>
          <td><span class="badge ${record.status}">${record.status}</span></td>
          <td>${formatTime(record.time)}</td>
        </tr>
      `).join("") || `
        <tr>
          <td colspan="5" class="muted">No records found.</td>
        </tr>
      `;
    }

    function updateMetrics() {
      totalRecordsEl.textContent = records.length;

      const successCount = records.filter(r => r.status === "success").length;
      const successRate = records.length ? Math.round((successCount / records.length) * 100) : 0;
      successRateEl.textContent = `${successRate}%`;

      const avg = records.length
        ? Math.round(records.reduce((sum, r) => sum + r.value, 0) / records.length)
        : 0;
      avgValueEl.textContent = `$${avg}`;

      activeUsersEl.textContent = Math.floor(20 + Math.random() * 80);
      lastUpdatedEl.textContent = `Last updated: ${formatTime(new Date())}`;
    }

    function updateChart() {
      dataPoints.push(Math.floor(20 + Math.random() * 80));
      labels.push(`Now-${labels.length - 4}`);

      if (dataPoints.length > 8) {
        dataPoints.shift();
        labels.shift();
      }

      chart.update();
    }

    function refreshDashboard() {
      updateMetrics();
      renderTable();
    }

    searchInput.addEventListener("input", renderTable);
    categoryFilter.addEventListener("change", renderTable);

    resetBtn.addEventListener("click", () => {
      searchInput.value = "";
      categoryFilter.value = "all";
      renderTable();
    });

    recordForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const category = document.getElementById("category").value;
      const value = Number(document.getElementById("value").value);
      const status = document.getElementById("status").value;

      records.unshift({
        name,
        category,
        value,
        status,
        time: new Date()
      });

      recordForm.reset();
      refreshDashboard();
    });

    // Simulated real-time updates
    setInterval(() => {
      const categories = ["sales", "support", "ops"];
      const statuses = ["success", "warning", "danger"];
      const randomName = ["Delta", "Epsilon", "Zeta", "Theta", "Kappa"][Math.floor(Math.random() * 5)];

      records.unshift({
        name: `${randomName}-${Math.floor(Math.random() * 100)}`,
        category: categories[Math.floor(Math.random() * categories.length)],
        value: Math.floor(50 + Math.random() * 250),
        status: statuses[Math.floor(Math.random() * statuses.length)],
        time: new Date()
      });

      if (records.length > 20) records.pop();
      updateChart();
      refreshDashboard();
    }, 3000);

    refreshDashboard();
  </script>
</body>
</html>
