        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          }
        }
      }
    });

    const requestsValue = document.getElementById('requestsValue');
    const usersValue = document.getElementById('usersValue');
    const errorsValue = document.getElementById('errorsValue');
    const healthValue = document.getElementById('healthValue');

    const requestsTrend = document.getElementById('requestsTrend');
    const usersTrend = document.getElementById('usersTrend');
    const errorsTrend = document.getElementById('errorsTrend');
    const healthTrend = document.getElementById('healthTrend');

    const activityLog = document.getElementById('activityLog');
    const eventForm = document.getElementById('eventForm');

    function addLogEntry(text, type = 'info') {
      const entry = document.createElement('div');
      entry.className = 'log-entry';
      const time = new Date().toLocaleTimeString();
      entry.innerHTML = `<strong>[${time}]</strong> <span class="status-${type}">${text}</span>`;
      activityLog.prepend(entry);
    }

    function updateStats() {
      const requests = Math.floor(Math.random() * 80) + 20;
      const users = Math.floor(Math.random() * 500) + 120;
      const errors = Math.floor(Math.random() * 10);
      const health = Math.max(70, 100 - errors * 3 - Math.floor(Math.random() * 8));

      requestsValue.textContent = requests;
      usersValue.textContent = users;
      errorsValue.textContent = `${errors}%`;
      healthValue.textContent = `${health}%`;

      requestsTrend.textContent = `+${Math.floor(Math.random() * 20)}%`;
      usersTrend.textContent = `+${Math.floor(Math.random() * 10)}%`;

      if (errors < 3) {
        errorsTrend.textContent = 'Stable';
        errorsTrend.className = 'trend status-ok';
      } else if (errors < 6) {
        errorsTrend.textContent = 'Elevated';
        errorsTrend.className = 'trend status-warn';
      } else {
        errorsTrend.textContent = 'High';
        errorsTrend.className = 'trend status-bad';
      }

      if (health > 92) {
        healthTrend.textContent = 'Excellent';
        healthTrend.className = 'trend status-ok';
      } else if (health > 80) {
        healthTrend.textContent = 'Good';
        healthTrend.className = 'trend status-warn';
      } else {
        healthTrend.textContent = 'Monitor';
        healthTrend.className = 'trend status-bad';
      }

      dataPoints.push(requests);
      if (dataPoints.length > 12) dataPoints.shift();
      trafficChart.data.labels.push(`T-${Math.floor(Math.random() * 100)}`);
      if (trafficChart.data.labels.length > 12) trafficChart.data.labels.shift();
      trafficChart.data.datasets[0].data = dataPoints;
      trafficChart.update();

      addLogEntry(`Auto-update: ${requests} req/s, ${users} users, ${errors}% errors`, errors < 3 ? 'ok' : (errors < 6 ? 'warn' : 'bad'));
    }

    eventForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(eventForm);
      const name = formData.get('name');
      const type = formData.get('type');
      const message = formData.get('message');

      addLogEntry(`${name} submitted a ${type.toUpperCase()} event: ${message}`, 
        type === 'info' ? 'ok' : type === 'warning' ? 'warn' : 'bad');

      eventForm.reset();
    });

    addLogEntry('Dashboard initialized.', 'ok');
    updateStats();
    setInterval(updateStats, 2000);
  </script>
</body>
