  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    const labels = [];
    const trafficData = [];

    for (let i = 0; i < 20; i++) {
      labels.push('');
      trafficData.push(Math.floor(Math.random() * 100) + 50);
    }

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Requests',
          data: trafficData,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 0,
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          }
        }
      }
    });

    const feedList = document.getElementById('feedList');
    const summaryTable = document.getElementById('summaryTable');
    const feedSearch = document.getElementById('feedSearch');

    let events = [
      { time: new Date().toLocaleTimeString(), title: 'System initialized', type: 'info', desc: 'Dashboard loaded successfully.' },
      { time: new Date().toLocaleTimeString(), title: 'API connected', type: 'info', desc: 'Connected to live simulation stream.' }
    ];

    function badgeClass(type) {
      return type === 'warn' ? 'warn' : type === 'err' ? 'err' : 'ok';
    }

    function renderFeed() {
      const query = feedSearch.value.toLowerCase().trim();
      feedList.innerHTML = '';

      events
        .filter(e =>
          e.title.toLowerCase().includes(query) ||
          e.desc.toLowerCase().includes(query) ||
          e.type.toLowerCase().includes(query)
        )
        .slice()
        .reverse()
        .forEach(event => {
          const div = document.createElement('div');
          div.className = 'feed-item';
          div.innerHTML = `
            <strong>${event.title}</strong>
            <small>${event.time} • <span class="badge ${badgeClass(event.type)}">${event.type.toUpperCase()}</span></small>
            <p>${event.desc}</p>
          `;
          feedList.appendChild(div);
        });
    }

    function renderSummary() {
      summaryTable.innerHTML = '';
      events.slice().reverse().slice(0, 6).forEach(event => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${event.time}</td>
          <td>${event.title}</td>
          <td>${event.type.toUpperCase()}</td>
          <td><span class="badge ${badgeClass(event.type)}">Recorded</span></td>
        `;
        summaryTable.appendChild(row);
      });
    }

    function updateMetrics() {
      const activeUsers = Math.floor(100 + Math.random() * 900);
      const requests = Math.floor(500 + Math.random() * 4500);
      const errorRate = (Math.random() * 5).toFixed(1);
      const responseTime = Math.floor(80 + Math.random() * 220);

      document.getElementById('activeUsers').textContent = activeUsers;
      document.getElementById('requests').textContent = requests;
      document.getElementById('errorRate').textContent = `${errorRate}%`;
      document.getElementById('responseTime').textContent = `${responseTime} ms`;

      document.getElementById('usersChange').textContent = `+${(Math.random() * 20).toFixed(1)}% from last minute`;
      document.getElementById('requestsChange').textContent = `+${(Math.random() * 25).toFixed(1)}% from last minute`;
      document.getElementById('errorChange').textContent = errorRate < 2 ? 'Healthy' : 'Monitoring';
      document.getElementById('responseChange').textContent = responseTime < 150 ? 'Fast' : 'Needs review';

      trafficData.push(requests);
      labels.push(new Date().toLocaleTimeString());
      if (trafficData.length > 20) {
        trafficData.shift();
        labels.shift();
      }
      chart.update();

      events.push({
        time: new Date().toLocaleTimeString(),
        title: 'System metrics refreshed',
        type: 'info',
        desc: `Users: ${activeUsers}, Requests: ${requests}, Error rate: ${errorRate}%`
      });

      if (events.length > 100) events.shift();

      renderFeed();
      renderSummary();
    }

    document.getElementById('eventForm').addEventListener('submit', function (e) {
      e.preventDefault();

      const title = document.getElementById('eventTitle').value.trim();
      const type = document.getElementById('eventType').value;
      const desc = document.getElementById('eventDesc').value.trim();

      if (!title || !desc) return;

      events.push({
        time: new Date().toLocaleTimeString(),
        title,
        type,
        desc
      });

      this.reset();
      renderFeed();
      renderSummary();
    });

    feedSearch.addEventListener('input', renderFeed);

    renderFeed();
    renderSummary();
    updateMetrics();
    setInterval(updateMetrics, 1000);
  </script>
</body>
</html>
