  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const conversionRateEl = document.getElementById("conversionRate");
    const revenueEl = document.getElementById("revenue");
    const lastRefreshEl = document.getElementById("lastRefresh");
    const activityFeedEl = document.getElementById("activityFeed");
    const toastEl = document.getElementById("toast");
    const form = document.getElementById("eventForm");

    const canvas = document.getElementById("trafficChart");
    const ctx = canvas.getContext("2d");

    let trafficData = Array.from({ length: 30 }, () => 50 + Math.random() * 60);
    let activityItems = [];

    function resizeCanvas() {
      const rect = canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    function drawChart() {
      const rect = canvas.getBoundingClientRect();
      const w = rect.width;
      const h = rect.height;
      ctx.clearRect(0, 0, w, h);

      const padding = 30;
      const chartW = w - padding * 2;
      const chartH = h - padding * 2;
      const maxVal = Math.max(...trafficData, 100);
      const minVal = 0;

      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 4; i++) {
        const y = padding + (chartH / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(w - padding, y);
        ctx.stroke();
      }

      ctx.beginPath();
      trafficData.forEach((value, index) => {
        const x = padding + (chartW / (trafficData.length - 1)) * index;
        const y = padding + chartH - ((value - minVal) / (maxVal - minVal)) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.lineTo(w - padding, h - padding);
      ctx.lineTo(padding, h - padding);
      ctx.closePath();
      const gradient = ctx.createLinearGradient(0, padding, 0, h - padding);
      gradient.addColorStop(0, "rgba(56, 189, 248, 0.35)");
      gradient.addColorStop(1, "rgba(56, 189, 248, 0)");
      ctx.fillStyle = gradient;
      ctx.fill();

      trafficData.forEach((value, index) => {
        const x = padding + (chartW / (trafficData.length - 1)) * index;
        const y = padding + chartH - ((value - minVal) / (maxVal - minVal)) * chartH;
        ctx.beginPath();
        ctx.arc(x, y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = "#22c55e";
        ctx.fill();
      });
    }

    function updateMetrics() {
      const activeUsers = Math.floor(900 + Math.random() * 800);
      const requestsPerMin = Math.floor(1200 + Math.random() * 1500);
      const conversionRate = (1.5 + Math.random() * 3.5).toFixed(2);
      const revenue = Math.floor(8000 + Math.random() * 4000);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
      conversionRateEl.textContent = conversionRate + "%";
      revenueEl.textContent = "$" + revenue.toLocaleString();

      lastRefreshEl.textContent = new Date().toLocaleTimeString();
    }

    function pushTrafficPoint() {
      const next = Math.max(20, Math.min(120, trafficData[trafficData.length - 1] + (Math.random() * 20 - 10)));
      trafficData.push(next);
      trafficData.shift();
      drawChart();
    }

    function addActivity(message) {
      const item = {
        message,
        time: new Date().toLocaleTimeString()
      };

      activityItems.unshift(item);
      activityItems = activityItems.slice(0, 8);

      renderActivityFeed();
      showToast(message);
    }

    function renderActivityFeed() {
      activityFeedEl.innerHTML = activityItems.map(item => `
        <li>
          ${item.message}
          <small>${item.time}</small>
        </li>
      `).join("");
    }

    function showToast(message) {
      toastEl.textContent = message;
      toastEl.classList.add("show");
      clearTimeout(showToast._timer);
      showToast._timer = setTimeout(() => {
        toastEl.classList.remove("show");
      }, 2500);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const type = document.getElementById("type").value;
      const priority = document.getElementById("priority").value;
      const message = document.getElementById("message").value.trim();

      if (!name || !message) return;

      addActivity(`${name} created a ${priority} priority ${type} event: ${message}`);

      form.reset();
      document.getElementById("priority").value = "Medium";
    });

    // Initial render
    resizeCanvas();
    updateMetrics();
    addActivity("Dashboard initialized successfully.");

    // Simulated real-time updates
    setInterval(() => {
      updateMetrics();
      pushTrafficPoint();

      if (Math.random() > 0.7) {
        const sampleNames = ["Ava", "Noah", "Mia", "Liam", "Sophia"];
        const sampleTypes = ["Signup", "Purchase", "Lead", "Support"];
        const name = sampleNames[Math.floor(Math.random() * sampleNames.length)];
        const type = sampleTypes[Math.floor(Math.random() * sampleTypes.length)];
        addActivity(`${name} triggered a ${type} event`);
      }
    }, 2000);

    window.addEventListener("resize", resizeCanvas);
  </script>
</body>
</html>
