        <div class="metric-value" id="activeUsers">0</div>
        <div class="metric-trend">+<span id="activeTrend">0</span>% vs last minute</div>
      </div>
      <div class="card">
        <div class="metric-label">Requests / Min</div>
        <div class="metric-value" id="requestsPerMin">0</div>
        <div class="metric-trend">Stable</div>
      </div>
      <div class="card">
        <div class="metric-label">Error Rate</div>
        <div class="metric-value" id="errorRate">0%</div>
        <div class="metric-trend" style="color: var(--danger);">Monitor closely</div>
      </div>
      <div class="card">
        <div class="metric-label">Avg. Response</div>
        <div class="metric-value" id="avgResponse">0ms</div>
        <div class="metric-trend">Healthy</div>
      </div>
    </section>

    <section class="main-grid">
      <div class="card chart-panel">
        <div class="panel-title">
          <h2>Real-Time Traffic</h2>
          <div class="controls">
            <select id="chartType">
              <option value="line">Line</option>
              <option value="bar">Bar</option>
            </select>
            <select id="timeRange">
              <option value="20">Last 20 points</option>
              <option value="50">Last 50 points</option>
              <option value="100">Last 100 points</option>
            </select>
            <button id="pauseBtn">Pause</button>
          </div>
        </div>
        <canvas id="trafficChart"></canvas>
      </div>

      <div class="stack">
        <div class="card">
          <div class="panel-title">
            <h2>Submit Event</h2>
          </div>
          <form id="eventForm">
            <div class="form-group">
              <label for="eventName">Event Name</label>
              <input type="text" id="eventName" placeholder="e.g. Purchase Completed" />
              <div class="error" id="nameError"></div>
            </div>

            <div class="form-group">
              <label for="eventValue">Event Value</label>
              <input type="number" id="eventValue" placeholder="e.g. 42" min="1" />
              <div class="error" id="valueError"></div>
            </div>

            <div class="form-group">
              <label for="eventType">Category</label>
              <select id="eventType">
                <option value="info">Info</option>
                <option value="success">Success</option>
                <option value="warning">Warning</option>
              </select>
            </div>

            <button type="submit">Submit</button>
            <div class="success" id="formMessage"></div>
          </form>
        </div>

        <div class="card">
          <div class="panel-title">
            <h2>Recent Activity</h2>
          </div>
          <ul class="activity-list" id="activityList"></ul>
          <p class="small" style="margin-top: 12px;">New submissions and simulated live events will appear here.</p>
        </div>
      </div>
