  <script>
    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = Array.from({ length: 20 }, (_, i) => `T-${19 - i}`);
    let trafficData = labels.map(() => Math.floor(Math.random() * 100) + 20);

    let currentChartType = "line";
    let paused = false;
    let maxPoints = 20;

    const chart = new Chart(ctx, {
      type: currentChartType,
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.2)",
          pointRadius: 3,
          tension: 0.35,
          fill: true
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    const activeUsersEl = document.getElementById("activeUsers");
    const activeTrendEl = document.getElementById("activeTrend");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const avgResponseEl = document.getElementById("avgResponse");
    const activityList = document.getElementById("activityList");

    const chartTypeSelect = document.getElementById("chartType");
    const timeRangeSelect = document.getElementById("timeRange");
    const pauseBtn = document.getElementById("pauseBtn");

    const eventForm = document.getElementById("eventForm");
    const eventName = document.getElementById("eventName");
    const eventValue = document.getElementById("eventValue");
    const eventType = document.getElementById("eventType");

    const nameError = document.getElementById("nameError");
    const valueError = document.getElementById("valueError");
    const formMessage = document.getElementById("formMessage");

    function pushActivity(message) {
      const li = document.createElement("li");
      li.textContent = `${new Date().toLocaleTimeString()}: ${message}`;
      activityList.prepend(li);

      while (activityList.children.length > 8) {
        activityList.removeChild(activityList.lastChild);
      }
    }

    function updateMetrics() {
      const activeUsers = Math.floor(400 + Math.random() * 800);
      const requestsPerMin = Math.floor(80 + Math.random() * 220);
      const errorRate = (Math.random() * 4).toFixed(1);
      const avgResponse = Math.floor(80 + Math.random() * 180);
      const trend = (Math.random() * 20).toFixed(0);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;
      avgResponseEl.textContent = `${avgResponse}ms`;
      activeTrendEl.textContent = trend;
    }

    function updateChart() {
      if (paused) return;

      const nextValue = Math.floor(Math.random() * 100) + 20;
      trafficData.push(nextValue);
      labels.push(`T-${labels.length}`);

      while (trafficData.length > maxPoints) trafficData.shift();
      while (labels.length > maxPoints) labels.shift();

      chart.data.labels = [...labels];
      chart.data.datasets[0].data = [...trafficData];
      chart.update();

      requestsPerMinEl.textContent = nextValue;
      pushActivity(`Incoming traffic spike: ${nextValue} requests/min`);
    }

    function simulateLiveDashboard() {
      updateMetrics();
      updateChart();
    }

    chartTypeSelect.addEventListener("change", () => {
      currentChartType = chartTypeSelect.value;
      chart.config.type = currentChartType;
      chart.update();
    });

    timeRangeSelect.addEventListener("change", () => {
      maxPoints = Number(timeRangeSelect.value);

      while (trafficData.length > maxPoints) trafficData.shift();
      while (labels.length > maxPoints) labels.shift();

      chart.data.labels = [...labels];
      chart.data.datasets[0].data = [...trafficData];
      chart.update();
    });

    pauseBtn.addEventListener("click", () => {
      paused = !paused;
      pauseBtn.textContent = paused ? "Resume" : "Pause";
      pushActivity(paused ? "Live updates paused" : "Live updates resumed");
    });

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      nameError.textContent = "";
      valueError.textContent = "";
      formMessage.textContent = "";

      const name = eventName.value.trim();
      const value = Number(eventValue.value);

      let valid = true;

      if (!name) {
        nameError.textContent = "Event name is required.";
        valid = false;
      }

      if (!value || value <= 0) {
        valueError.textContent = "Enter a valid value greater than 0.";
        valid = false;
      }

      if (!valid) return;

      const type = eventType.value;
      const label = type.toUpperCase();

      formMessage.textContent = "Event submitted successfully!";
      pushActivity(`${label}: ${name} (${value})`);

      // Use submitted value to affect chart briefly
      trafficData.push(value);
      labels.push(`F-${labels.length}`);

      while (trafficData.length > maxPoints) trafficData.shift();
      while (labels.length > maxPoints) labels.shift();

      chart.data.labels = [...labels];
      chart.data.datasets[0].data = [...trafficData];
      chart.update();

      eventForm.reset();
    });

    // Initial load
    updateMetrics();
    pushActivity("Dashboard initialized");

    // Real-time simulation every 2 seconds
    setInterval(simulateLiveDashboard, 2000);
  </script>
</body>
</html>
