  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const transactionsEl = document.getElementById("transactions");
    const conversionRateEl = document.getElementById("conversionRate");
    const revenueEl = document.getElementById("revenue");

    const metricSelect = document.getElementById("metricSelect");
    const pauseBtn = document.getElementById("pauseBtn");
    const resetBtn = document.getElementById("resetBtn");

    const searchInput = document.getElementById("searchInput");
    const filterType = document.getElementById("filterType");
    const eventsTable = document.getElementById("eventsTable");

    const form = document.getElementById("eventForm");
    const formMessage = document.getElementById("formMessage");

    const chartCtx = document.getElementById("liveChart").getContext("2d");

    let isRunning = true;
    let timeLabels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
    let usersData = Array(10).fill(0);
    let transactionsData = Array(10).fill(0);
    let revenueData = Array(10).fill(0);

    const events = [];

    const chart = new Chart(chartCtx, {
      type: "line",
      data: {
        labels: timeLabels,
        datasets: [{
          label: "Users",
          data: usersData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          fill: true,
          tension: 0.35
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: { labels: { color: "#e5e7eb" } }
        },
        scales: {
          x: { ticks: { color: "#94a3b8" }, grid: { color: "#334155" } },
          y: { ticks: { color: "#94a3b8" }, grid: { color: "#334155" } }
        }
      }
    });

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function updateMetrics() {
      const users = randomInt(120, 1000);
      const transactions = randomInt(20, 180);
      const conversion = (Math.random() * 15 + 1).toFixed(1);
      const revenue = randomInt(500, 12000);

      activeUsersEl.textContent = users.toLocaleString();
      transactionsEl.textContent = transactions.toLocaleString();
      conversionRateEl.textContent = `${conversion}%`;
      revenueEl.textContent = `$${revenue.toLocaleString()}`;

      usersData.push(users); usersData.shift();
      transactionsData.push(transactions); transactionsData.shift();
      revenueData.push(revenue); revenueData.shift();

      chart.data.labels.push(new Date().toLocaleTimeString());
      chart.data.labels.shift();

      const selected = metricSelect.value;
      chart.data.datasets[0].label =
        selected === "users" ? "Users" :
        selected === "transactions" ? "Transactions" : "Revenue";

      chart.data.datasets[0].data =
        selected === "users" ? usersData :
        selected === "transactions" ? transactionsData : revenueData;

      chart.update();
    }

    function addEvent(name, type, value) {
      const entry = {
        time: new Date().toLocaleTimeString(),
        name,
        type,
        value
      };
      events.unshift(entry);
      renderEvents();
    }

    function statusClass(type) {
      if (type === "info") return "ok";
      if (type === "warning") return "warn";
      return "bad";
    }

    function renderEvents() {
      const search = searchInput.value.toLowerCase();
      const filter = filterType.value;

      const filtered = events.filter(e => {
        const matchesSearch =
          e.name.toLowerCase().includes(search) ||
          e.type.toLowerCase().includes(search) ||
          String(e.value).includes(search);
        const matchesType = filter === "all" || e.type === filter;
        return matchesSearch && matchesType;
      });

      eventsTable.innerHTML = filtered.map(e => `
        <tr>
          <td>${e.time}</td>
          <td>${e.name}</td>
          <td><span class="status ${statusClass(e.type)}">${e.type}</span></td>
          <td>${e.value}</td>
        </tr>
      `).join("") || `<tr><td colspan="4">No matching events found.</td></tr>`;
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("eventName").value.trim();
      const type = document.getElementById("eventType").value;
      const value = parseInt(document.getElementById("eventValue").value, 10);

      if (!name || !type || !value) {
        formMessage.textContent = "Please fill in all fields correctly.";
        formMessage.style.color = "var(--danger)";
        return;
      }

      addEvent(name, type, value);
      form.reset();
      formMessage.textContent = `Event "${name}" submitted successfully.`;
      formMessage.style.color = "var(--accent-2)";
    });

    searchInput.addEventListener("input", renderEvents);
    filterType.addEventListener("change", renderEvents);

    metricSelect.addEventListener("change", () => {
      chart.data.datasets[0].label =
        metricSelect.value === "users" ? "Users" :
        metricSelect.value === "transactions" ? "Transactions" : "Revenue";
      chart.data.datasets[0].data =
        metricSelect.value === "users" ? usersData :
        metricSelect.value === "transactions" ? transactionsData : revenueData;
      chart.update();
    });

    pauseBtn.addEventListener("click", () => {
      isRunning = !isRunning;
      pauseBtn.textContent = isRunning ? "Pause Stream" : "Resume Stream";
    });

    resetBtn.addEventListener("click", () => {
      usersData = Array(10).fill(0);
      transactionsData = Array(10).fill(0);
      revenueData = Array(10).fill(0);
      events.length = 0;
      renderEvents();
      chart.data.labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
      chart.update();
      formMessage.textContent = "Dashboard data reset.";
      formMessage.style.color = "var(--accent-2)";
    });

    setInterval(() => {
      if (isRunning) {
        updateMetrics();
      }
    }, 2000);

    // Seed some demo events
    addEvent("Login", "info", 1);
    addEvent("CPU Spike", "warning", 76);
    addEvent("Payment Failure", "critical", 1);
    updateMetrics();
  </script>
</body>
</html>
