  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const ordersPerMinEl = document.getElementById("ordersPerMin");
    const conversionRateEl = document.getElementById("conversionRate");
    const latencyEl = document.getElementById("latency");
    const activityFeedEl = document.getElementById("activityFeed");

    const labels = Array.from({ length: 20 }, (_, i) => `-${19 - i}s`);
    const dataPoints = Array.from({ length: 20 }, () => Math.floor(Math.random() * 100) + 50);

    const ctx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56,189,248,0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 2,
          pointHoverRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(255,255,255,0.05)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(255,255,255,0.05)" }
          }
        }
      }
    });

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function updateMetrics() {
      activeUsersEl.textContent = randomInt(1200, 1800);
      ordersPerMinEl.textContent = randomInt(80, 160);
      conversionRateEl.textContent = (Math.random() * 5 + 1).toFixed(2) + "%";
      latencyEl.textContent = randomInt(40, 120) + "ms";
    }

    function addActivity(message) {
      const item = document.createElement("li");
      const time = new Date().toLocaleTimeString();
      item.innerHTML = `${message} <span class="meta">${time}</span>`;
      activityFeedEl.prepend(item);

      while (activityFeedEl.children.length > 5) {
        activityFeedEl.removeChild(activityFeedEl.lastChild);
      }
    }

    function updateChart() {
      trafficChart.data.labels.push("");
      trafficChart.data.datasets[0].data.push(randomInt(40, 160));

      if (trafficChart.data.labels.length > 20) {
        trafficChart.data.labels.shift();
        trafficChart.data.datasets[0].data.shift();
      }

      trafficChart.update();
    }

    function simulateLiveUpdate() {
      updateMetrics();
      updateChart();

      const messages = [
        "New user signed up",
        "Order completed",
        "Support ticket updated",
        "API response received",
        "Payment processed",
        "New feedback submitted"
      ];

      if (Math.random() > 0.55) {
        addActivity(messages[randomInt(0, messages.length - 1)]);
      }
    }

    document.getElementById("reportForm").addEventListener("submit", function (e) {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const email = document.getElementById("email").value.trim();
      const category = document.getElementById("category").value;
      const message = document.getElementById("message").value.trim();

      let valid = true;

      document.querySelectorAll(".error").forEach(el => el.style.display = "none");
      document.getElementById("formSuccess").style.display = "none";

      if (!name) {
        document.getElementById("nameError").style.display = "block";
        valid = false;
      }

      if (!email || !/^\S+@\S+\.\S+$/.test(email)) {
        document.getElementById("emailError").style.display = "block";
        valid = false;
      }

      if (!category) {
        document.getElementById("categoryError").style.display = "block";
        valid = false;
      }

      if (message.length < 10) {
        document.getElementById("messageError").style.display = "block";
        valid = false;
      }

      if (valid) {
        document.getElementById("formSuccess").style.display = "block";
        addActivity(`Report submitted by ${name} (${category})`);
        this.reset();
      }
    });

    updateMetrics();
    addActivity("Dashboard initialized");
    addActivity("Connected to live data feed");
    setInterval(simulateLiveUpdate, 2000);
  </script>
</body>
