  <script>
    const ctx = document.getElementById('trafficChart').getContext('2d');
    const trafficData = {
      labels: Array.from({ length: 20 }, (_, i) => i + 1),
      values: Array.from({ length: 20 }, () => Math.floor(Math.random() * 100) + 20)
    };

    const state = {
      feedRunning: true,
      records: [
        { name: "Alice", category: "Sales", value: 120, notes: "Handled Q2 lead", time: new Date().toLocaleTimeString() },
        { name: "Bob", category: "Support", value: 80, notes: "Resolved ticket #4821", time: new Date().toLocaleTimeString() }
      ]
    };

    function drawChart() {
      const width = ctx.canvas.width;
      const height = ctx.canvas.height;
      ctx.clearRect(0, 0, width, height);

      const padding = 40;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      const maxVal = Math.max(...trafficData.values, 100);
      const minVal = Math.min(...trafficData.values, 0);

      // grid
      ctx.strokeStyle = 'rgba(255,255,255,0.07)';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 4; i++) {
        const y = padding + (chartHeight / 4) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
      }

      // line
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 3;
      ctx.beginPath();

      trafficData.values.forEach((val, i) => {
        const x = padding + (chartWidth / (trafficData.values.length - 1)) * i;
        const y = padding + chartHeight - ((val - minVal) / (maxVal - minVal || 1)) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // points
      ctx.fillStyle = '#22c55e';
      trafficData.values.forEach((val, i) => {
        const x = padding + (chartWidth / (trafficData.values.length - 1)) * i;
        const y = padding + chartHeight - ((val - minVal) / (maxVal - minVal || 1)) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });

      // labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px sans-serif';
      ctx.fillText('Low', 8, height - 12);
      ctx.fillText('High', 8, 14);
    }

    function updateMetrics() {
      const latest = trafficData.values[trafficData.values.length - 1];
      document.getElementById('activeUsers').textContent = latest + 120;
      document.getElementById('requestsPerMin').textContent = latest * 3;
      document.getElementById('conversionRate').textContent = (Math.random() * 5 + 1).toFixed(1) + '%';
      document.getElementById('systemHealth').textContent = Math.max(90, 100 - Math.floor(Math.random() * 10)) + '%';
    }

    function renderRecords() {
      const search = document.getElementById('search').value.toLowerCase();
      const categoryFilter = document.getElementById('categoryFilter').value;

      const filtered = state.records.filter(record => {
        const matchesSearch =
          record.name.toLowerCase().includes(search) ||
          record.category.toLowerCase().includes(search) ||
          record.notes.toLowerCase().includes(search);

        const matchesCategory = !categoryFilter || record.category === categoryFilter;
        return matchesSearch && matchesCategory;
      });

      const list = document.getElementById('recordList');
      list.innerHTML = '';

      filtered.forEach(record => {
        const item = document.createElement('div');
        item.className = 'item';
        item.innerHTML = `
          <p class="item-title">${record.name}</p>
          <div class="item-meta">
            <span>${record.category}</span>
            <span>${record.value}</span>
            <span>${record.time}</span>
          </div>
          <p style="margin:10px 0 0;color:var(--muted);">${record.notes || 'No notes provided.'}</p>
        `;
        list.appendChild(item);
      });

      document.getElementById('recordCount').textContent = `${filtered.length} items`;
    }

    document.getElementById('recordForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('name').value.trim();
      const category = document.getElementById('category').value;
      const value = Number(document.getElementById('value').value);
      const notes = document.getElementById('notes').value.trim();

      state.records.unshift({
        name,
        category,
        value,
        notes,
        time: new Date().toLocaleTimeString()
      });

      e.target.reset();
      renderRecords();
    });

    document.getElementById('search').addEventListener('input', renderRecords);
    document.getElementById('categoryFilter').addEventListener('change', renderRecords);

    document.getElementById('toggleFeedBtn').addEventListener('click', (e) => {
      state.feedRunning = !state.feedRunning;
      e.target.textContent = state.feedRunning ? 'Pause Feed' : 'Resume Feed';
    });

    function tick() {
      if (state.feedRunning) {
        const last = trafficData.values[trafficData.values.length - 1];
        const next = Math.max(10, Math.min(180, last + Math.floor(Math.random() * 31) - 15));
        trafficData.values.push(next);
        trafficData.values.shift();
        drawChart();
        updateMetrics();
      }
    }

    drawChart();
    updateMetrics();
    renderRecords();
    setInterval(tick, 1000);
  </script>
</body>
</html>
