<body>
  <header>
    <h1>Real-Time Analytics Dashboard</h1>
    <p>Live visualization + form handling + interactive controls</p>
  </header>

  <main class="dashboard">
    <!-- Left side: chart and stats -->
    <section class="card">
      <h2>Live Metrics</h2>

      <div class="stats">
        <div class="stat">
          <div class="label">Current Value</div>
          <div class="value" id="currentValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Average</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Updates</div>
          <div class="value" id="updateCount">0</div>
        </div>
      </div>

      <div class="controls">
        <button id="startBtn">Start Live Feed</button>
        <button id="stopBtn" class="secondary">Stop Feed</button>
        <button id="resetBtn" class="secondary">Reset Data</button>
      </div>

      <canvas id="liveChart"></canvas>
    </section>

    <!-- Right side: form + activity feed -->
    <section class="grid">
      <section class="card">
        <h2>Data Submission Form</h2>
        <form id="dataForm">
          <div>
            <label for="name">Name</label>
            <input type="text" id="name" placeholder="Enter your name" />
            <div class="error" id="nameError"></div>
          </div>

          <div>
            <label for="email">Email</label>
            <input type="email" id="email" placeholder="Enter your email" />
            <div class="error" id="emailError"></div>
          </div>

          <div>
            <label for="category">Category</label>
            <select id="category">
              <option value="">Select a category</option>
              <option value="Sales">Sales</option>
              <option value="Support">Support</option>
              <option value="Marketing">Marketing</option>
            </select>
            <div class="error" id="categoryError"></div>
          </div>

          <div>
            <label for="notes">Notes</label>
            <textarea id="notes" rows="4" placeholder="Optional notes"></textarea>
          </div>

          <button type="submit">Submit</button>
          <div id="formMessage"></div>
        </form>
      </section>

      <section class="card">
        <h2>Activity Feed</h2>
        <div class="feed" id="feed"></div>
      </section>
    </section>
  </main>

  <script>
    // =========================
    // Chart setup
    // =========================
    const ctx = document.getElementById("liveChart").getContext("2d");

    const labels = Array.from({ length: 10 }, (_, i) => i + 1);
    const dataPoints = Array.from({ length: 10 }, () => Math.floor(Math.random() * 50) + 10);

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Live Data",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          fill: true,
          tension: 0.35,
          pointRadius: 4,
          pointBackgroundColor: "#e5e7eb"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.3)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.3)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    // =========================
    // Live data simulation
    // =========================
    let liveInterval = null;
    let updateCount = 0;

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const updateCountEl = document.getElementById("updateCount");
    const feedEl = document.getElementById("feed");

    function updateStats() {
      const values = chart.data.datasets[0].data;
      const current = values[values.length - 1];
      const avg = (values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(1);

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      updateCountEl.textContent = updateCount;
    }

    function addFeedMessage(message) {
      const item = document.createElement("div");
      item.className = "feed-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      feedEl.prepend(item);
    }

    function pushNewData() {
      const newValue = Math.floor(Math.random() * 100);
      chart.data.labels.push(chart.data.labels.length + 1);
      chart.data.datasets[0].data.push(newValue);

      if (chart.data.labels.length > 10) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }

      chart.update();
      updateCount++;
      updateStats();
      addFeedMessage(`New data point received: ${newValue}`);
    }

    document.getElementById("startBtn").addEventListener("click", () => {
      if (liveInterval) return;
      liveInterval = setInterval(pushNewData, 1500);
      addFeedMessage("Live feed started.");
    });

    document.getElementById("stopBtn").addEventListener("click", () => {
      clearInterval(liveInterval);
      liveInterval = null;
      addFeedMessage("Live feed stopped.");
    });

    document.getElementById("resetBtn").addEventListener("click", () => {
      clearInterval(liveInterval);
      liveInterval = null;
      updateCount = 0;

      chart.data.labels = Array.from({ length: 10 }, (_, i) => i + 1);
      chart.data.datasets[0].data = Array.from({ length: 10 }, () => Math.floor(Math.random() * 50) + 10);
      chart.update();

      updateStats();
      feedEl.innerHTML = "";
      addFeedMessage("Dashboard data reset.");
    });

    updateStats();
    addFeedMessage("Dashboard initialized.");

    // =========================
    // Form handling
    // =========================
    const form = document.getElementById("dataForm");
    const nameInput = document.getElementById("name");
    const emailInput = document.getElementById("email");
    const categoryInput = document.getElementById("category");
    const notesInput = document.getElementById("notes");
    const formMessage = document.getElementById("formMessage");

    function clearErrors() {
      document.getElementById("nameError").textContent = "";
      document.getElementById("emailError").textContent = "";
      document.getElementById("categoryError").textContent = "";
      formMessage.textContent = "";
      formMessage.className = "";
    }

    function validateForm() {
      let valid = true;
      clearErrors();

      if (!nameInput.value.trim()) {
        document.getElementById("nameError").textContent = "Name is required.";
        valid = false;
      }

      if (!emailInput.value.trim() || !/^\S+@\S+\.\S+$/.test(emailInput.value)) {
        document.getElementById("emailError").textContent = "Enter a valid email.";
        valid = false;
      }

      if (!categoryInput.value) {
        document.getElementById("categoryError").textContent = "Please select a category.";
        valid = false;
      }

      return valid;
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      if (!validateForm()) return;

      const record = {
        name: nameInput.value.trim(),
        email: emailInput.value.trim(),
        category: categoryInput.value,
        notes: notesInput.value.trim(),
        submittedAt: new Date().toLocaleString()
      };

      formMessage.textContent = "Form submitted successfully!";
      formMessage.className = "success";

      addFeedMessage(
        `Form submitted by ${record.name} (${record.category}) at ${record.submittedAt}`
      );

      form.reset();
    });
  </script>
</body>
</html>
