          <button type="submit">Add to Dashboard</button>
        </form>

        <button class="secondary" id="resetBtn" type="button">Reset Events</button>

        <div class="small">
          Records added here will appear in the table below and affect summary stats.
        </div>
      </div>
    </div>

    <div class="panel" style="margin-top: 20px;">
      <h2>Event Log</h2>

      <div class="controls">
        <input id="searchInput" type="text" placeholder="Search events..." />
        <select id="filterType">
          <option value="All">All Types</option>
          <option value="Open">Open</option>
          <option value="Closed">Closed</option>
        </select>
      </div>

      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Type</th>
              <th>Value</th>
              <th>Timestamp</th>
            </tr>
          </thead>
          <tbody id="eventTable"></tbody>
        </table>
      </div>
    </div>
  </div>

  <script>
    const ctx = document.getElementById('trafficChart').getContext('2d');

    const trafficChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Traffic',
          data: [],
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: '#38bdf8'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          }
        }
      }
    });

    const state = {
      events: [
        { name: 'API Sync', type: 'Open', value: 42, timestamp: new Date().toLocaleTimeString() },
        { name: 'Cache Refresh', type: 'Closed', value: 77, timestamp: new Date().toLocaleTimeString() }
      ],
      traffic: Array.from({ length: 10 }, () => Math.floor(Math.random() * 100) + 20)
    };

    const activeSessionsEl = document.getElementById('activeSessions');
    const requestsPerMinEl = document.getElementById('requestsPerMin');
    const errorRateEl = document.getElementById('errorRate');
    const throughputEl = document.getElementById('throughput');
    const lastUpdatedEl = document.getElementById('lastUpdated');
    const eventTableEl = document.getElementById('eventTable');
    const searchInput = document.getElementById('searchInput');
    const filterType = document.getElementById('filterType');

    function renderMetrics() {
      const openCount = state.events.filter(e => e.type === 'Open').length;
      const closedCount = state.events.filter(e => e.type === 'Closed').length;
      const totalValue = state.events.reduce((sum, e) => sum + Number(e.value), 0);
      const errorRate = state.events.length ? Math.round((closedCount / state.events.length) * 100) : 0;

      activeSessionsEl.textContent = 120 + openCount * 8;
      requestsPerMinEl.textContent = 300 + totalValue;
      errorRateEl.textContent = errorRate + '%';
      throughputEl.textContent = 1000 + totalValue * 2;
      lastUpdatedEl.textContent = new Date().toLocaleTimeString();
    }

    function renderChart() {
      trafficChart.data.labels = state.traffic.map((_, i) => `T-${state.traffic.length - i}`);
      trafficChart.data.datasets[0].data = state.traffic;
      trafficChart.update();
    }

    function renderTable() {
      const search = searchInput.value.toLowerCase();
      const filter = filterType.value;

      const filtered = state.events.filter(event => {
        const matchesSearch =
          event.name.toLowerCase().includes(search) ||
          event.type.toLowerCase().includes(search) ||
          String(event.value).includes(search);

        const matchesFilter = filter === 'All' || event.type === filter;

        return matchesSearch && matchesFilter;
      });

      eventTableEl.innerHTML = filtered.map(event => `
        <tr>
          <td>${event.name}</td>
          <td><span class="badge ${event.type === 'Open' ? 'open' : 'closed'}">${event.type}</span></td>
          <td>${event.value}</td>
          <td>${event.timestamp}</td>
        </tr>
      `).join('');
    }

    function updateDashboard() {
      renderMetrics();
      renderChart();
      renderTable();
    }

    document.getElementById('eventForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('name').value.trim();
      const type = document.getElementById('type').value;
      const value = Number(document.getElementById('value').value);

      if (!name || Number.isNaN(value)) return;

      state.events.unshift({
        name,
        type,
        value,
        timestamp: new Date().toLocaleTimeString()
      });

      // Update live traffic with new input-driven value
      state.traffic.push(value);
      if (state.traffic.length > 20) state.traffic.shift();

      e.target.reset();
      updateDashboard();
    });

    document.getElementById('resetBtn').addEventListener('click', () => {
      state.events = [];
      state.traffic = Array.from({ length: 10 }, () => Math.floor(Math.random() * 100) + 20);
      updateDashboard();
    });

    searchInput.addEventListener('input', renderTable);
    filterType.addEventListener('change', renderTable);

    // Simulated real-time updates
    setInterval(() => {
      const nextValue = Math.floor(Math.random() * 100) + 20;
      state.traffic.push(nextValue);
      if (state.traffic.length > 20) state.traffic.shift();

      if (Math.random() > 0.6) {
        state.events.unshift({
          name: `Auto Event ${Math.floor(Math.random() * 1000)}`,
          type: Math.random() > 0.5 ? 'Open' : 'Closed',
          value: nextValue,
          timestamp: new Date().toLocaleTimeString()
        });
        if (state.events.length > 25) state.events.pop();
      }

      updateDashboard();
    }, 3000);

    updateDashboard();
  </script>
</body>
</html>
