          <label for="value">Value</label>
          <input type="number" id="value" placeholder="e.g. 42" required />
        </div>

        <div class="field">
          <label for="category">Category</label>
          <select id="category">
            <option value="manual">Manual Entry</option>
            <option value="api">API Feed</option>
            <option value="sensor">Sensor Feed</option>
          </select>
        </div>

        <div class="button-row">
          <button type="submit">Add Entry</button>
          <button type="button" class="secondary" id="toggleFeedBtn">Pause Live Feed</button>
        </div>
      </form>

      <p class="message" id="message"></p>

      <div style="margin-top: 18px; color: var(--muted); font-size: 0.92rem; line-height: 1.5;">
        <strong>Live feed:</strong> Random values are generated every 2 seconds to simulate incoming data.
