  <script>
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const dataTable = document.getElementById('dataTable');
    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const totalEntriesEl = document.getElementById('totalEntries');
    const messageEl = document.getElementById('message');
    const form = document.getElementById('dataForm');
    const toggleFeedBtn = document.getElementById('toggleFeedBtn');

    const labels = [];
    const values = [];
    const records = [];

    let feedRunning = true;
    let liveInterval;

    function getStatusClass(value) {
      if (value < 30) return 'low';
      if (value < 70) return 'ok';
      return '';
    }

    function updateStats() {
      const total = values.length;
      const current = total ? values[total - 1] : 0;
      const average = total
        ? (values.reduce((sum, v) => sum + v, 0) / total).toFixed(2)
        : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = average;
      totalEntriesEl.textContent = total;
    }

    function renderTable() {
      dataTable.innerHTML = records
        .slice()
        .reverse()
        .map(record => `
          <tr>
            <td>${record.timestamp}</td>
            <td>${record.source}</td>
            <td>${record.value}</td>
            <td><span class="status ${record.statusClass}">${record.status}</span></td>
          </tr>
        `)
        .join('');
    }

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Value',
          data: values,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.12)',
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6,
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          },
          y: {
            beginAtZero: true,
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    function addRecord(source, value, category) {
      const timestamp = new Date().toLocaleTimeString();
      const statusClass = getStatusClass(value);
      const status = value < 30 ? 'Low' : value < 70 ? 'Normal' : 'High';

      labels.push(timestamp);
      values.push(value);
      records.push({ timestamp, source, value, category, status, statusClass });

      if (labels.length > 20) {
        labels.shift();
        values.shift();
      }

      chart.update();
      renderTable();
      updateStats();
      currentValueEl.style.color = statusClass === 'low' ? 'var(--danger)' : statusClass === 'ok' ? 'var(--success)' : 'var(--text)';
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const source = document.getElementById('source').value.trim();
      const value = Number(document.getElementById('value').value);
      const category = document.getElementById('category').value;

      if (!source || Number.isNaN(value)) {
        messageEl.textContent = 'Please provide a valid source and numeric value.';
        messageEl.style.color = 'var(--danger)';
        return;
      }

      addRecord(source, value, category);
      messageEl.textContent = `Added ${category} entry from "${source}".`;
      messageEl.style.color = 'var(--success)';
      form.reset();
    });

    toggleFeedBtn.addEventListener('click', () => {
      feedRunning = !feedRunning;

      if (feedRunning) {
        startLiveFeed();
        toggleFeedBtn.textContent = 'Pause Live Feed';
        messageEl.textContent = 'Live feed resumed.';
      } else {
        clearInterval(liveInterval);
        toggleFeedBtn.textContent = 'Resume Live Feed';
        messageEl.textContent = 'Live feed paused.';
      }
    });

    function startLiveFeed() {
      clearInterval(liveInterval);
      liveInterval = setInterval(() => {
        if (!feedRunning) return;

        const value = Math.floor(Math.random() * 100);
        const source = ['Sensor A', 'Sensor B', 'API Feed'][Math.floor(Math.random() * 3)];
        addRecord(source, value, 'sensor');
      }, 2000);
    }

    // Seed with initial values
    ['Sensor A', 'Sensor B', 'API Feed'].forEach((src, i) => {
      addRecord(src, Math.floor(Math.random() * 100), 'sensor');
    });

    startLiveFeed();
  </script>
</body>
</html>
