    .pill.warn { background: rgba(245, 158, 11, 0.15); color: #fcd34d; }
    .pill.bad { background: rgba(239, 68, 68, 0.15); color: #fca5a5; }

    @media (max-width: 980px) {
      .layout {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Interactive Real-Time Dashboard</h1>
    <p>Live visualization, form submission, and dynamic data updates.</p>
  </header>

  <main class="container">
    <section class="grid metrics">
      <div class="card">
        <div class="metric-title">Active Users</div>
        <div id="activeUsers" class="metric-value">0</div>
        <div class="metric-sub">Updated every second</div>
      </div>
      <div class="card">
        <div class="metric-title">Requests / Min</div>
        <div id="requestsPerMin" class="metric-value">0</div>
        <div class="metric-sub">Simulated real-time load</div>
      </div>
      <div class="card">
        <div class="metric-title">Error Rate</div>
        <div id="errorRate" class="metric-value">0%</div>
        <div class="metric-sub">Rolling average</div>
      </div>
      <div class="card">
        <div class="metric-title">System Health</div>
        <div id="healthStatus" class="metric-value">Good</div>
        <div class="metric-sub">Based on current metrics</div>
      </div>
    </section>

    <section class="grid layout">
      <div class="card chart-wrap">
        <h2 class="section-title">Real-Time Traffic</h2>
        <div class="controls">
          <button id="pauseBtn">Pause</button>
          <button id="resetBtn" class="secondary">Reset</button>
        </div>
        <canvas id="trafficChart" width="900" height="340"></canvas>
      </div>

      <div class="card">
        <h2 class="section-title">Report Form</h2>
        <form id="reportForm" class="form-grid">
          <div class="form-group">
            <label for="name">Name</label>
            <input id="name" name="name" type="text" placeholder="Your name" required />
          </div>

          <div class="form-group">
            <label for="category">Category</label>
            <select id="category" name="category" required>
              <option value="">Select one</option>
              <option value="performance">Performance</option>
              <option value="bug">Bug</option>
              <option value="feature">Feature Request</option>
            </select>
          </div>

          <div class="form-group">
            <label for="value">Metric Value</label>
            <input id="value" name="value" type="number" min="0" max="100" placeholder="0-100" required />
          </div>

          <button type="submit">Submit Report</button>
          <div id="formStatus" class="status"></div>
        </form>
      </div>
    </section>

    <section class="card">
      <h2 class="section-title">Recent Submissions</h2>
      <table>
        <thead>
          <tr>
            <th>Time</th>
            <th>Name</th>
            <th>Category</th>
            <th>Value</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody id="submissionsTable">
          <tr>
            <td colspan="5" style="color: var(--muted);">No submissions yet</td>
          </tr>
        </tbody>
      </table>
    </section>
  </main>

  <script>
    // --- State ---
    let running = true;
    let activeUsers = 120;
    let requestsPerMin = 450;
    let errorRate = 2.5;

    const maxPoints = 40;
    const trafficData = Array.from({ length: maxPoints }, () => 300 + Math.random() * 160);

    const canvas = document.getElementById("trafficChart");
    const ctx = canvas.getContext("2d");

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const healthStatusEl = document.getElementById("healthStatus");
    const formStatusEl = document.getElementById("formStatus");
    const submissionsTable = document.getElementById("submissionsTable");
    const pauseBtn = document.getElementById("pauseBtn");
    const resetBtn = document.getElementById("resetBtn");
    const reportForm = document.getElementById("reportForm");

    const submissions = [];

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    }

    function clamp(n, min, max) {
      return Math.max(min, Math.min(max, n));
    }

    function getHealthLabel() {
      if (errorRate < 3) return { text: "Good", cls: "good" };
      if (errorRate < 6) return { text: "Warning", cls: "warn" };
      return { text: "Critical", cls: "bad" };
    }

    function updateMetrics() {
      activeUsers += Math.floor(Math.random() * 11 - 5);
      requestsPerMin += Math.floor(Math.random() * 31 - 15);
      errorRate += (Math.random() - 0.5) * 0.8;

      activeUsers = clamp(activeUsers, 50, 500);
      requestsPerMin = clamp(requestsPerMin, 100, 1200);
      errorRate = clamp(errorRate, 0, 12);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
      errorRateEl.textContent = `${errorRate.toFixed(1)}%`;

      const health = getHealthLabel();
      healthStatusEl.textContent = health.text;
      healthStatusEl.className = `metric-value ${health.cls}`;
    }

    function updateChartData() {
      const last = trafficData[trafficData.length - 1];
      const next = clamp(last + (Math.random() - 0.5) * 45, 80, 520);
      trafficData.push(next);
      trafficData.shift();
    }

    function drawGrid() {
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;

      const stepY = canvas.height / 5;
      for (let y = stepY; y < canvas.height; y += stepY) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background
      const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
      gradient.addColorStop(0, "rgba(56, 189, 248, 0.14)");
      gradient.addColorStop(1, "rgba(56, 189, 248, 0.02)");
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      drawGrid();

      const padding = 24;
      const minVal = 0;
      const maxVal = 600;
      const plotWidth = canvas.width - padding * 2;
      const plotHeight = canvas.height - padding * 2;

      const xStep = plotWidth / (trafficData.length - 1);
      const points = trafficData.map((v, i) => ({
        x: padding + i * xStep,
        y: padding + plotHeight - ((v - minVal) / (maxVal - minVal)) * plotHeight
      }));

      // Line
      ctx.beginPath();
      points.forEach((p, i) => {
        if (i === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      });
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.stroke();

      // Area
      ctx.lineTo(padding + plotWidth, padding + plotHeight);
      ctx.lineTo(padding, padding + plotHeight);
      ctx.closePath();
      ctx.fillStyle = "rgba(56, 189, 248, 0.18)";
      ctx.fill();

      // Points
      points.forEach((p) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = "#e0f2fe";
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = "rgba(255,255,255,0.65)";
      ctx.font = "12px sans-serif";
      ctx.fillText("600", 6, 18);
      ctx.fillText("0", 12, canvas.height - 8);
      ctx.fillText("Traffic / sec", 24, 18);
    }

    function renderSubmissions() {
      if (submissions.length === 0) {
        submissionsTable.innerHTML = `<tr><td colspan="5" style="color: var(--muted);">No submissions yet</td></tr>`;
        return;
      }

      submissionsTable.innerHTML = submissions.map(item => {
        return `
          <tr>
            <td>${item.time}</td>
            <td>${item.name}</td>
            <td>${item.category}</td>
            <td>${item.value}</td>
            <td><span class="pill ${item.statusClass}">${item.status}</span></td>
          </tr>
        `;
      }).join("");
    }

    function getSubmissionStatus(value) {
      if (value < 40) return { text: "Low", cls: "good" };
      if (value < 75) return { text: "Moderate", cls: "warn" };
      return { text: "High", cls: "bad" };
    }

    reportForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const category = document.getElementById("category").value;
      const value = Number(document.getElementById("value").value);

      if (!name || !category || Number.isNaN(value)) {
        formStatusEl.textContent = "Please complete all fields.";
        formStatusEl.className = "status error";
        return;
      }

      const status = getSubmissionStatus(value);

      submissions.unshift({
        time: formatTime(),
        name,
        category: category[0].toUpperCase() + category.slice(1),
        value,
        status: status.text,
        statusClass: status.cls
      });

      submissions.splice(10); // keep only latest 10
      renderSubmissions();

      formStatusEl.textContent = "Report submitted successfully.";
      formStatusEl.className = "status success";
      reportForm.reset();
    });

    pauseBtn.addEventListener("click", () => {
      running = !running;
      pauseBtn.textContent = running ? "Pause" : "Resume";
    });

    resetBtn.addEventListener("click", () => {
      activeUsers = 120;
      requestsPerMin = 450;
      errorRate = 2.5;
      trafficData.length = 0;
      for (let i = 0; i < maxPoints; i++) {
        trafficData.push(300 + Math.random() * 160);
      }
      submissions.length = 0;
      renderSubmissions();
      formStatusEl.textContent = "Dashboard reset.";
      formStatusEl.className = "status";
      updateMetrics();
      drawChart();
    });

    function tick() {
      if (running) {
        updateMetrics();
        updateChartData();
        drawChart();
      }
    }

    // Initial render
    updateMetrics();
    drawChart();
    renderSubmissions();

    // Real-time interval
    setInterval(tick, 1000);

    // Resize handling for crisp canvas on HiDPI screens
    function resizeCanvasForDPR() {
      const dpr = window.devicePixelRatio || 1;
      const displayWidth = canvas.clientWidth;
      const displayHeight = 340;
      canvas.width = Math.floor(displayWidth * dpr);
      canvas.height = Math.floor(displayHeight * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      drawChart();
    }

    window.addEventListener("resize", resizeCanvasForDPR);
    resizeCanvasForDPR();
  </script>
</body>
</html>
