<body>
  <header>
    <h1>Real-Time Interactive Dashboard</h1>
    <p>Live metrics, chart updates, and form-based record management</p>
  </header>

  <main class="dashboard">
    <section class="panel">
      <h2>Live Analytics</h2>

      <div class="stats">
        <div class="stat">
          <div class="label">Visitors</div>
          <div class="value" id="visitorsValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Conversions</div>
          <div class="value" id="conversionsValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Revenue</div>
          <div class="value" id="revenueValue">$0</div>
        </div>
      </div>

      <div class="controls">
        <button class="btn-primary" id="toggleLiveBtn">Pause Live Updates</button>
        <button id="addRandomBtn">Add Random Record</button>
        <select id="timeRange">
          <option value="10">Last 10 points</option>
          <option value="20" selected>Last 20 points</option>
          <option value="30">Last 30 points</option>
        </select>
      </div>

      <canvas id="liveChart"></canvas>
    </section>

    <section class="panel">
      <h2>Record Form</h2>
      <form id="recordForm">
        <div class="form-grid">
          <div class="full">
            <input type="hidden" id="recordId" />
          </div>

          <div>
            <input type="text" id="name" placeholder="Name" required />
          </div>
          <div>
            <select id="category" required>
              <option value="">Select category</option>
              <option>Sales</option>
              <option>Support</option>
              <option>Marketing</option>
            </select>
          </div>
          <div>
            <input type="number" id="amount" placeholder="Amount" min="0" step="1" required />
          </div>
          <div>
            <select id="status" required>
              <option value="">Select status</option>
              <option value="ok">OK</option>
              <option value="warn">Warning</option>
              <option value="bad">Critical</option>
            </select>
          </div>

          <div class="full">
            <input type="text" id="notes" placeholder="Notes" />
          </div>

          <div class="full">
            <button type="submit" class="btn-primary">Save Record</button>
            <button type="button" id="resetBtn">Reset</button>
          </div>
        </div>
      </form>

      <div class="controls" style="margin-top:18px;">
        <input type="text" id="search" placeholder="Search records..." />
        <select id="filterCategory">
          <option value="">All categories</option>
          <option>Sales</option>
          <option>Support</option>
          <option>Marketing</option>
        </select>
      </div>

      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Category</th>
              <th>Amount</th>
              <th>Status</th>
              <th>Notes</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody id="recordsTable"></tbody>
        </table>
      </div>
    </section>
  </main>

  <script>
    const ctx = document.getElementById("liveChart").getContext("2d");

    const chartData = {
      labels: Array.from({ length: 20 }, (_, i) => `T-${19 - i}`),
      values: Array.from({ length: 20 }, () => Math.floor(Math.random() * 100) + 20)
    };

    const liveChart = new Chart(ctx, {
      type: "line",
      data: {
        labels: chartData.labels,
        datasets: [{
          label: "Live Metric",
          data: chartData.values,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#7dd3fc"
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(55, 65, 81, 0.4)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(55, 65, 81, 0.4)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    let live = true;
    let recordIdCounter = 1;
    let records = [
      { id: 1, name: "Alpha", category: "Sales", amount: 1200, status: "ok", notes: "Closed deal" },
      { id: 2, name: "Beta", category: "Support", amount: 300, status: "warn", notes: "Pending follow-up" },
      { id: 3, name: "Gamma", category: "Marketing", amount: 850, status: "bad", notes: "Campaign delayed" }
    ];
    recordIdCounter = 4;

    function updateStats() {
      const visitors = chartData.values.reduce((a, b) => a + b, 0);
      const conversions = Math.round(visitors * 0.18);
      const revenue = conversions * 42;

      document.getElementById("visitorsValue").textContent = visitors;
      document.getElementById("conversionsValue").textContent = conversions;
      document.getElementById("revenueValue").textContent = `$${revenue.toLocaleString()}`;
    }

    function addLivePoint() {
      if (!live) return;
      const nextValue = Math.floor(Math.random() * 100) + 20;
      const nextLabel = new Date().toLocaleTimeString();

      chartData.values.push(nextValue);
      chartData.labels.push(nextLabel);

      const range = parseInt(document.getElementById("timeRange").value, 10);
      if (chartData.values.length > range) {
        chartData.values.shift();
        chartData.labels.shift();
      }

      liveChart.data.labels = chartData.labels;
      liveChart.data.datasets[0].data = chartData.values;
      liveChart.update();

      updateStats();
    }

    function renderRecords() {
      const tbody = document.getElementById("recordsTable");
      const search = document.getElementById("search").value.toLowerCase();
      const filterCategory = document.getElementById("filterCategory").value;

      tbody.innerHTML = "";

      records
        .filter(record => {
          const matchesSearch =
            record.name.toLowerCase().includes(search) ||
            record.category.toLowerCase().includes(search) ||
            record.notes.toLowerCase().includes(search);

          const matchesCategory = !filterCategory || record.category === filterCategory;
          return matchesSearch && matchesCategory;
        })
        .forEach(record => {
          const tr = document.createElement("tr");
          tr.innerHTML = `
            <td>${record.name}</td>
            <td>${record.category}</td>
            <td>$${Number(record.amount).toLocaleString()}</td>
            <td><span class="status ${record.status}">${record.status.toUpperCase()}</span></td>
            <td>${record.notes || "-"}</td>
            <td>
              <div class="actions">
                <button onclick="editRecord(${record.id})">Edit</button>
                <button class="btn-danger" onclick="deleteRecord(${record.id})">Delete</button>
              </div>
            </td>
          `;
          tbody.appendChild(tr);
        });
    }

    function resetForm() {
      document.getElementById("recordId").value = "";
      document.getElementById("recordForm").reset();
    }

    function editRecord(id) {
      const record = records.find(r => r.id === id);
      if (!record) return;

      document.getElementById("recordId").value = record.id;
      document.getElementById("name").value = record.name;
      document.getElementById("category").value = record.category;
      document.getElementById("amount").value = record.amount;
      document.getElementById("status").value = record.status;
      document.getElementById("notes").value = record.notes;
    }

    function deleteRecord(id) {
      records = records.filter(r => r.id !== id);
      renderRecords();
    }

    document.getElementById("recordForm").addEventListener("submit", function (e) {
      e.preventDefault();

      const id = document.getElementById("recordId").value;
      const record = {
        id: id ? Number(id) : recordIdCounter++,
        name: document.getElementById("name").value.trim(),
        category: document.getElementById("category").value,
        amount: Number(document.getElementById("amount").value),
        status: document.getElementById("status").value,
        notes: document.getElementById("notes").value.trim()
      };

      if (id) {
        records = records.map(r => (r.id === Number(id) ? record : r));
      } else {
        records.unshift(record);
      }

      renderRecords();
      resetForm();
    });

    document.getElementById("resetBtn").addEventListener("click", resetForm);
    document.getElementById("toggleLiveBtn").addEventListener("click", function () {
      live = !live;
      this.textContent = live ? "Pause Live Updates" : "Resume Live Updates";
    });

    document.getElementById("addRandomBtn").addEventListener("click", () => {
      const categories = ["Sales", "Support", "Marketing"];
      const statuses = ["ok", "warn", "bad"];
      const record = {
        id: recordIdCounter++,
        name: `Item ${recordIdCounter}`,
        category: categories[Math.floor(Math.random() * categories.length)],
        amount: Math.floor(Math.random() * 5000) + 100,
        status: statuses[Math.floor(Math.random() * statuses.length)],
        notes: "Auto-generated record"
      };

      records.unshift(record);
      renderRecords();
    });

    document.getElementById("search").addEventListener("input", renderRecords);
    document.getElementById("filterCategory").addEventListener("change", renderRecords);
    document.getElementById("timeRange").addEventListener("change", () => {
      const range = parseInt(document.getElementById("timeRange").value, 10);
      while (chartData.values.length > range) {
        chartData.values.shift();
        chartData.labels.shift();
      }
      liveChart.data.labels = chartData.labels;
      liveChart.data.datasets[0].data = chartData.values;
      liveChart.update();
      updateStats();
    });

    window.editRecord = editRecord;
    window.deleteRecord = deleteRecord;

    setInterval(addLivePoint, 2000);

    renderRecords();
    updateStats();
  </script>
</body>
