  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
    const dataPoints = Array.from({ length: 10 }, () => Math.floor(Math.random() * 100));

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Value',
          data: dataPoints,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            beginAtZero: true,
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    const incomingCountEl = document.getElementById('incomingCount');
    const successRateEl = document.getElementById('successRate');
    const currentLoadEl = document.getElementById('currentLoad');
    const formMessageEl = document.getElementById('formMessage');
    const submissionLogEl = document.getElementById('submissionLog');

    let eventCount = 0;
    let successfulEvents = 0;
    let autoUpdate = true;

    function updateStats(success = true, loadValue = null) {
      eventCount++;
      if (success) successfulEvents++;

      const successRate = eventCount === 0 ? 100 : Math.round((successfulEvents / eventCount) * 100);
      incomingCountEl.textContent = eventCount;
      successRateEl.textContent = `${successRate}%`;
      currentLoadEl.textContent = loadValue ?? dataPoints[dataPoints.length - 1];

      successRateEl.className = 'value ' + (successRate >= 80 ? 'good' : 'bad');
    }

    function addRandomData() {
      const nextValue = Math.floor(Math.random() * 100);
      dataPoints.push(nextValue);
      labels.push(`T-${Date.now().toString().slice(-4)}`);

      if (dataPoints.length > 10) dataPoints.shift();
      if (labels.length > 10) labels.shift();

      chart.data.labels = [...labels];
      chart.data.datasets[0].data = [...dataPoints];
      chart.update();

      updateStats(true, nextValue);
    }

    document.getElementById('addDataBtn').addEventListener('click', addRandomData);

    document.getElementById('toggleAutoBtn').addEventListener('click', (e) => {
      autoUpdate = !autoUpdate;
      e.target.textContent = autoUpdate ? 'Pause Auto Update' : 'Resume Auto Update';
    });

    document.getElementById('resetBtn').addEventListener('click', () => {
      dataPoints.splice(0, dataPoints.length, ...Array.from({ length: 10 }, () => Math.floor(Math.random() * 100)));
      labels.splice(0, labels.length, ...Array.from({ length: 10 }, (_, i) => `T-${9 - i}`));

      chart.data.labels = [...labels];
      chart.data.datasets[0].data = [...dataPoints];
      chart.update();

      eventCount = 0;
      successfulEvents = 0;
      incomingCountEl.textContent = '0';
      successRateEl.textContent = '100%';
      successRateEl.className = 'value good';
      currentLoadEl.textContent = dataPoints[dataPoints.length - 1];
    });

    setInterval(() => {
      if (autoUpdate) addRandomData();
    }, 2000);

    const form = document.getElementById('feedbackForm');

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      formMessageEl.textContent = '';
      formMessageEl.className = 'message';

      const name = document.getElementById('name').value.trim();
      const email = document.getElementById('email').value.trim();
      const priority = document.getElementById('priority').value;
      const messageText = document.getElementById('messageText').value.trim();

      if (!name || !email || !priority || messageText.length < 10) {
        formMessageEl.textContent = 'Please complete all fields correctly.';
        formMessageEl.classList.add('error');
        updateStats(false, dataPoints[dataPoints.length - 1]);
        return;
      }

      formMessageEl.textContent = 'Form submitted successfully!';
      formMessageEl.classList.add('success');

      const entry = document.createElement('div');
      entry.className = 'log-item';
      entry.innerHTML = `
        <strong>${name}</strong> (${priority})<br/>
        <span>${email}</span><br/>
        <span>${messageText}</span>
      `;
      submissionLogEl.prepend(entry);

      form.reset();
      updateStats(true, dataPoints[dataPoints.length - 1]);
    });

    // Initialize stats
    updateStats(true, dataPoints[dataPoints.length - 1]);
  </script>
</body>
</html>
