## 4) `app.js`

```javascript
const metricSelect = document.getElementById("metricSelect");
const eventForm = document.getElementById("eventForm");
const activityLog = document.getElementById("activityLog");
const clearLogBtn = document.getElementById("clearLogBtn");
const latestValueEl = document.getElementById("latestValue");
const averageValueEl = document.getElementById("averageValue");
const eventCountEl = document.getElementById("eventCount");
const connectionStatus = document.getElementById("connectionStatus");

const ctx = document.getElementById("liveChart").getContext("2d");

let currentMetric = metricSelect.value;
let values = [];
let labels = [];
let eventCount = 0;

const metricConfig = {
  cpu: { label: "CPU Usage (%)", min: 20, max: 95, color: "#38bdf8" },
  memory: { label: "Memory Usage (%)", min: 30, max: 90, color: "#22c55e" },
  requests: { label: "Requests/sec", min: 60, max: 200, color: "#f59e0b" },
};

function generateLiveValue(metric) {
  const { min, max } = metricConfig[metric];
  return Math.round(min + Math.random() * (max - min));
}

function updateStats() {
  const latest = values.length ? values[values.length - 1] : null;
  const avg = values.length
    ? (values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(1)
    : "--";

  latestValueEl.textContent = latest ?? "--";
  averageValueEl.textContent = avg;
  eventCountEl.textContent = eventCount;
}

function addLogEntry(message, subtext = "") {
  const li = document.createElement("li");
  li.innerHTML = `<strong>${message}</strong>${subtext ? `<small>${subtext}</small>` : ""}`;
  activityLog.prepend(li);
}

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: metricConfig[currentMetric].label,
        data: values,
        borderColor: metricConfig[currentMetric].color,
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        beginAtZero: true,
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function pushLiveData() {
  const now = new Date();
  const label = now.toLocaleTimeString();
  const value = generateLiveValue(currentMetric);

  labels.push(label);
  values.push(value);

  if (labels.length > 20) {
    labels.shift();
    values.shift();
  }

  chart.data.labels = labels;
  chart.data.datasets[0].data = values;
  chart.data.datasets[0].label = metricConfig[currentMetric].label;
  chart.data.datasets[0].borderColor = metricConfig[currentMetric].color;
  chart.update();

  updateStats();
}

metricSelect.addEventListener("change", () => {
  currentMetric = metricSelect.value;
  values = [];
  labels = [];
  chart.data.labels = labels;
  chart.data.datasets[0].data = values;
  chart.data.datasets[0].label = metricConfig[currentMetric].label;
  chart.data.datasets[0].borderColor = metricConfig[currentMetric].color;
  chart.update();
  addLogEntry(`Metric changed to ${metricConfig[currentMetric].label}`);
  updateStats();
});

eventForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const formData = new FormData(eventForm);
  const eventName = formData.get("eventName");
  const eventType = formData.get("eventType");
  const eventValue = formData.get("eventValue");

  eventCount += 1;
  updateStats();

  addLogEntry(
    `Submitted ${eventType}: ${eventName} (${eventValue})`,
    `Event #${eventCount} recorded at ${new Date().toLocaleTimeString()}`
  );

  eventForm.reset();
});

clearLogBtn.addEventListener("click", () => {
  activityLog.innerHTML = "";
  addLogEntry("Log cleared");
});

setInterval(() => {
  pushLiveData();
}, 2000);

addLogEntry("Dashboard initialized");
pushLiveData();
updateStats();
```

