  <script>
    // Chart setup
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
    const dataPoints = [45, 52, 49, 61, 58, 67, 72, 69, 75, 80];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Activity Score',
          data: dataPoints,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.12)',
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointBackgroundColor: '#38bdf8'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(148, 163, 184, 0.12)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(148, 163, 184, 0.12)' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    // Real-time simulation
    const activeUsersEl = document.getElementById('activeUsers');
    const requestsEl = document.getElementById('requestsPerMin');
    const errorRateEl = document.getElementById('errorRate');
    const usersDeltaEl = document.getElementById('usersDelta');
    const requestsDeltaEl = document.getElementById('requestsDelta');
    const errorDeltaEl = document.getElementById('errorDelta');

    function updateMetrics() {
      const activeUsers = 1100 + Math.floor(Math.random() * 400);
      const requests = 780 + Math.floor(Math.random() * 180);
      const errors = (1.2 + Math.random() * 1.2).toFixed(1);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsEl.textContent = requests.toLocaleString();
      errorRateEl.textContent = `${errors}%`;

      const userChange = (Math.random() * 20 - 5).toFixed(1);
      const reqChange = (Math.random() * 10 - 2).toFixed(1);
      const errChange = (Math.random() * 0.8 - 0.1).toFixed(1);

      usersDeltaEl.textContent = `${userChange >= 0 ? '+' : ''}${userChange}% vs last hour`;
      requestsDeltaEl.textContent = `${reqChange >= 0 ? '+' : ''}${reqChange}% vs last hour`;
      errorDeltaEl.textContent = `${errChange >= 0 ? '+' : ''}${errChange}% vs last hour`;

      usersDeltaEl.className = `delta ${userChange >= 0 ? 'good' : 'bad'}`;
      requestsDeltaEl.className = `delta ${reqChange >= 0 ? 'good' : 'bad'}`;
      errorDeltaEl.className = `delta ${errChange >= 0 ? 'bad' : 'good'}`;
    }

    function updateChart() {
      const newValue = Math.floor(45 + Math.random() * 45);
      chart.data.labels.push(`T+${Date.now() % 1000}`);
      chart.data.datasets[0].data.push(newValue);

      if (chart.data.labels.length > 10) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }

      chart.update();
    }

    setInterval(() => {
      updateMetrics();
      updateChart();
    }, 3000);

    // Form handling
    const form = document.getElementById('eventForm');
    const formLog = document.getElementById('formLog');

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const formData = new FormData(form);
      const payload = Object.fromEntries(formData.entries());

      const ts = new Date().toLocaleString();
      formLog.innerHTML = `
        <strong>Event submitted at ${ts}</strong><br/>
        Name: ${payload.name}<br/>
        Category: ${payload.category}<br/>
        Priority: ${payload.priority}<br/>
        Value: ${payload.value}<br/>
        Notes: ${payload.notes || '—'}
      `;

      // Example: feed submission into chart / metrics
      const submittedValue = parseInt(payload.value, 10) || 0;
      chart.data.datasets[0].data.push(submittedValue);
      chart.data.labels.push('Form');
      if (chart.data.labels.length > 10) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }
      chart.update();

      form.reset();
      document.getElementById('priority').value = 'Medium';
    });
  </script>
</body>
