## 4) `app.js`

```javascript
const ctx = document.getElementById("realtimeChart").getContext("2d");

const visitorsValue = document.getElementById("visitorsValue");
const ordersValue = document.getElementById("ordersValue");
const conversionValue = document.getElementById("conversionValue");
const revenueValue = document.getElementById("revenueValue");
const eventsTableBody = document.getElementById("eventsTableBody");
const eventForm = document.getElementById("eventForm");
const rangeSelect = document.getElementById("rangeSelect");
const connectionStatus = document.getElementById("connectionStatus");

let events = [];
let chartLabels = [];
let chartData = [];

const MAX_POINTS = 100;

function formatTime(date = new Date()) {
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

function formatCurrency(value) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0
  }).format(value);
}

function updateMetrics() {
  const visitors = events.reduce((sum, e) => sum + (e.type === "view" ? e.value : 0), 0);
  const orders = events.reduce((sum, e) => sum + (e.type === "purchase" ? e.value : 0), 0);
  const revenue = events.reduce((sum, e) => sum + (e.type === "purchase" ? e.value * 25 : 0), 0);
  const conversion = visitors > 0 ? ((orders / visitors) * 100).toFixed(1) : "0.0";

  visitorsValue.textContent = visitors;
  ordersValue.textContent = orders;
  conversionValue.textContent = `${conversion}%`;
  revenueValue.textContent = formatCurrency(revenue);
}

function renderEventsTable() {
  eventsTableBody.innerHTML = "";

  const recent = [...events].slice(-10).reverse();

  recent.forEach((event) => {
    const row = document.createElement("tr");
    row.innerHTML = `
      <td>${event.time}</td>
      <td>${event.name}</td>
      <td>${event.type}</td>
      <td>${event.value}</td>
    `;
    eventsTableBody.appendChild(row);
  });
}

function addEvent(name, type, value) {
  const event = {
    time: formatTime(),
    name,
    type,
    value: Number(value)
  };

  events.push(event);

  if (events.length > 200) {
    events.shift();
  }

  const chartValue = type === "purchase" ? value * 25 : value;

  chartLabels.push(event.time);
  chartData.push(chartValue);

  if (chartLabels.length > MAX_POINTS) {
    chartLabels.shift();
    chartData.shift();
  }

  updateMetrics();
  renderEventsTable();
  updateChart();
}

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels: chartLabels,
    datasets: [
      {
        label: "Event Value",
        data: chartData,
        borderColor: "#4f8cff",
        backgroundColor: "rgba(79, 140, 255, 0.15)",
        fill: true,
        tension: 0.35,
        pointRadius: 2
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5eefc"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#93a4c3" },
        grid: { color: "rgba(147, 164, 195, 0.12)" }
      },
      y: {
        ticks: { color: "#93a4c3" },
        grid: { color: "rgba(147, 164, 195, 0.12)" }
      }
    }
  }
});

function updateChart() {
  const range = Number(rangeSelect.value);
  const slicedLabels = chartLabels.slice(-range);
  const slicedData = chartData.slice(-range);

  chart.data.labels = slicedLabels;
  chart.data.datasets[0].data = slicedData;
  chart.update("none");
}

rangeSelect.addEventListener("change", updateChart);

eventForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const name = document.getElementById("eventName").value.trim();
  const type = document.getElementById("eventType").value;
  const value = document.getElementById("eventValue").value;

  if (!name || !value) return;

  addEvent(name, type, Number(value));
  eventForm.reset();
  document.getElementById("eventValue").value = 1;
});

// Simulated real-time incoming data
function simulateIncomingEvent() {
  const types = ["view", "click", "purchase", "signup"];
  const prefixes = {
    view: "Page View",
    click: "Button Click",
    purchase: "Order",
    signup: "Signup"
  };

  const type = types[Math.floor(Math.random() * types.length)];
  const value = type === "purchase" ? Math.ceil(Math.random() * 3) : Math.ceil(Math.random() * 20);

  addEvent(`${prefixes[type]} #${Math.floor(Math.random() * 1000)}`, type, value);
}

function setConnection(isConnected) {
  connectionStatus.textContent = isConnected ? "● Connected" : "● Disconnected";
  connectionStatus.style.color = isConnected ? "#23c483" : "#f56565";
  connectionStatus.style.borderColor = isConnected ? "rgba(35, 196, 131, 0.3)" : "rgba(245, 101, 101, 0.3)";
  connectionStatus.style.background = isConnected ? "rgba(35, 196, 131, 0.12)" : "rgba(245, 101, 101, 0.12)";
}

setConnection(true);

// Seed initial demo data
for (let i = 0; i < 12; i++) {
  simulateIncomingEvent();
}

// Real-time updates every 2 seconds
setInterval(() => {
  const online = Math.random() > 0.08;
  setConnection(online);

  if (online) {
    simulateIncomingEvent();
  }
}, 2000);
```

