      const nextValue = Math.floor(Math.random() * 100);
      chart.data.datasets[0].data.shift();
      chart.data.datasets[0].data.push(nextValue);
      chart.update();
    }

    setInterval(updateRealtimeMetrics, 2000);
    updateRealtimeMetrics();

    function addFeedItem({ name, category, message }) {
      const item = document.createElement("div");
      item.className = "feed-item";
      item.innerHTML = `
        <strong>${escapeHtml(name)}</strong> — ${escapeHtml(category)}
        <div>${escapeHtml(message)}</div>
        <small>${new Date().toLocaleString()}</small>
      `;
      feedEl.prepend(item);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const formData = new FormData(form);
      const entry = {
        name: formData.get("name"),
        category: formData.get("category"),
        message: formData.get("message")
      };

      addFeedItem(entry);
      form.reset();
    });

    function escapeHtml(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }
