    for (let i = 0; i < 12; i++) {
      labels.push(`-${11 - i}m`);
      dataPoints.push(700 + Math.round(Math.random() * 120));
    }

    const ctx = document.getElementById("realtimeChart").getContext("2d");

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests / Min",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#38bdf8"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.05)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.05)" }
          }
        }
      }
    });

    function renderMetrics() {
      activeUsersEl.textContent = state.activeUsers.toFixed(0);
      requestsPerMinEl.textContent = state.requestsPerMin.toFixed(0);
      errorRateEl.textContent = state.errorRate.toFixed(1) + "%";

      activeUsersTrendEl.textContent = `+${Math.floor(Math.random() * 10)} in last minute`;
      requestsTrendEl.textContent = `+${Math.floor(Math.random() * 8)}%`;
      errorTrendEl.textContent = `-${(Math.random() * 0.5).toFixed(1)}%`;
    }

    function addActivity(message) {
      const li = document.createElement("li");
      const time = new Date().toLocaleTimeString();
      li.innerHTML = `${message}<small>${time}</small>`;
      activityListEl.prepend(li);

      while (activityListEl.children.length > 5) {
        activityListEl.removeChild(activityListEl.lastChild);
      }
    }

    function simulateRealtimeUpdate() {
      const variation = Math.round((Math.random() - 0.5) * 40);
      state.requestsPerMin = Math.max(300, state.requestsPerMin + variation);
      state.activeUsers = Math.max(0, state.activeUsers + Math.round((Math.random() - 0.45) * 8));
      state.errorRate = Math.max(0, Math.min(10, state.errorRate + (Math.random() - 0.5) * 0.3));

      dataPoints.push(state.requestsPerMin);
      labels.push("now");
      if (dataPoints.length > 12) {
        dataPoints.shift();
        labels.shift();
      }

      chart.update();
      renderMetrics();
    }

    document.getElementById("inputForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const metricName = document.getElementById("metricName").value;
      const metricValue = parseFloat(document.getElementById("metricValue").value);
      const note = document.getElementById("note").value.trim();

      if (Number.isNaN(metricValue)) {
        formStatusEl.textContent = "Please enter a valid number.";
        return;
      }

      if (metricName === "errorRate") {
        state.errorRate = metricValue;
      } else {
        state[metricName] = metricValue;
      }

      if (metricName === "requestsPerMin") {
        dataPoints[dataPoints.length - 1] = metricValue;
        chart.update();
      }

      renderMetrics();

      const labelMap = {
        activeUsers: "Active Users",
        requestsPerMin: "Requests / Min",
        errorRate: "Error Rate"
      };

      addActivity(
        `Updated ${labelMap[metricName]} to ${metricValue}${note ? ` — ${note}` : ""}`
      );

      formStatusEl.textContent = `Updated ${labelMap[metricName]} successfully.`;
      e.target.reset();
    });

    renderMetrics();
    addActivity("Dashboard initialized.");

    setInterval(simulateRealtimeUpdate, 3000);
  </script>
</body>
</html>
