  <script>
    const ctx = document.getElementById("trafficChart");

    const labels = ["12:00", "12:02", "12:04", "12:06", "12:08", "12:10", "12:12", "12:14"];
    const allData = {
      all:    [120, 145, 132, 160, 178, 170, 190, 205],
      web:    [70, 88, 75, 96, 110, 104, 120, 132],
      mobile: [30, 34, 36, 42, 48, 50, 54, 58],
      api:    [20, 23, 21, 22, 20, 16, 16, 15]
    };

    let currentFilter = "all";

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: allData[currentFilter],
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(55, 65, 81, 0.5)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(55, 65, 81, 0.5)" }
          }
        }
      }
    });

    const liveUsersEl = document.getElementById("liveUsers");
    const conversionRateEl = document.getElementById("conversionRate");
    const openIssuesEl = document.getElementById("openIssues");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const eventLog = document.getElementById("eventLog");

    function addLog(message) {
      const li = document.createElement("li");
      li.textContent = `${new Date().toLocaleTimeString()}: ${message}`;
      eventLog.prepend(li);
    }

    function updateMetrics() {
      const liveUsers = 1100 + Math.floor(Math.random() * 250);
      const conversion = (3.5 + Math.random() * 2.5).toFixed(1);
      const issues = 8 + Math.floor(Math.random() * 10);
      const rpm = 290 + Math.floor(Math.random() * 60);

      liveUsersEl.textContent = liveUsers.toLocaleString();
      conversionRateEl.textContent = `${conversion}%`;
      openIssuesEl.textContent = issues;
      requestsPerMinEl.textContent = rpm;

      const newPoint = Math.max(50, Math.floor(rpm / 2 + Math.random() * 25));
      labels.shift();
      labels.push(new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }));

      allData.all.shift();
      allData.all.push(newPoint);
      allData.web.shift();
      allData.web.push(Math.floor(newPoint * 0.6));
      allData.mobile.shift();
      allData.mobile.push(Math.floor(newPoint * 0.25));
      allData.api.shift();
      allData.api.push(Math.floor(newPoint * 0.15));

      chart.data.labels = labels;
      chart.data.datasets[0].data = allData[currentFilter];
      chart.update();

      addLog(`Metrics refreshed — users: ${liveUsers}, RPM: ${rpm}`);
    }

    document.querySelectorAll("[data-filter]").forEach(btn => {
      btn.addEventListener("click", () => {
        document.querySelectorAll("[data-filter]").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        currentFilter = btn.dataset.filter;
        chart.data.datasets[0].label = `Traffic (${currentFilter})`;
        chart.data.datasets[0].data = allData[currentFilter];
        chart.update();
        addLog(`Filter changed to "${currentFilter}"`);
      });
    });

    const form = document.getElementById("entryForm");
    const nameInput = document.getElementById("name");
    const emailInput = document.getElementById("email");
    const typeInput = document.getElementById("type");
    const notesInput = document.getElementById("notes");
    const formSuccess = document.getElementById("formSuccess");

    function setError(el, message) {
      el.textContent = message;
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      let valid = true;
      formSuccess.textContent = "";

      setError(document.getElementById("nameError"), "");
      setError(document.getElementById("emailError"), "");
      setError(document.getElementById("typeError"), "");

      if (nameInput.value.trim().length < 2) {
        setError(document.getElementById("nameError"), "Name must be at least 2 characters.");
        valid = false;
      }

      if (!/^\S+@\S+\.\S+$/.test(emailInput.value.trim())) {
        setError(document.getElementById("emailError"), "Please enter a valid email address.");
        valid = false;
      }

      if (!typeInput.value) {
        setError(document.getElementById("typeError"), "Please select a type.");
        valid = false;
      }

      if (!valid) {
        addLog("Form validation failed");
        return;
      }

      const entry = {
        name: nameInput.value.trim(),
        email: emailInput.value.trim(),
        type: typeInput.value,
        notes: notesInput.value.trim()
      };

      formSuccess.textContent = `Submitted successfully: ${entry.name} (${entry.type})`;
      addLog(`New entry submitted by ${entry.name} for ${entry.type}`);

      form.reset();
    });

    addLog("Dashboard loaded");

    updateMetrics();
    setInterval(updateMetrics, 2000);
  </script>
</body>
