          <input type="number" id="value" name="value" placeholder="e.g. 42" required />
        </div>

        <div class="field">
          <label for="category">Category</label>
          <select id="category" name="category">
            <option value="info">Info</option>
            <option value="warning">Warning</option>
            <option value="success">Success</option>
          </select>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
          <button type="button" id="resetBtn" class="secondary">Reset Data</button>
        </div>
      </form>
    </section>

    <section class="card">
      <h2>Event Log</h2>
      <p class="muted">Latest submitted points appear below.</p>
      <ul id="eventLog"></ul>
    </section>
  </main>

  <script>
    const chart = document.getElementById("chart");
    const ctx = chart.getContext("2d");

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const systemHealthEl = document.getElementById("systemHealth");
    const eventLogEl = document.getElementById("eventLog");

    const dataPoints = Array.from({ length: 20 }, () => Math.floor(Math.random() * 100));
    const labels = Array.from({ length: 20 }, (_, i) => `T-${19 - i}`);

    let liveInterval = null;

    function updateMetrics() {
      const activeUsers = 120 + Math.floor(Math.random() * 80);
      const rps = 300 + Math.floor(Math.random() * 150);
      const healthy = Math.random() > 0.1;

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = rps;
      systemHealthEl.textContent = healthy ? "Good" : "Degraded";
      systemHealthEl.style.color = healthy ? "#22c55e" : "#ef4444";
    }

    function drawChart() {
      const w = chart.width;
      const h = chart.height;
      ctx.clearRect(0, 0, w, h);

      // background grid
      ctx.strokeStyle = "#1f2937";
      ctx.lineWidth = 1;

      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      const maxVal = Math.max(...dataPoints, 100);
      const padding = 30;
      const plotW = w - padding * 2;
      const plotH = h - padding * 2;
      const stepX = plotW / (dataPoints.length - 1);

      // line
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      dataPoints.forEach((val, i) => {
        const x = padding + i * stepX;
        const y = padding + plotH - (val / maxVal) * plotH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // points
      ctx.fillStyle = "#22c55e";
      dataPoints.forEach((val, i) => {
        const x = padding + i * stepX;
        const y = padding + plotH - (val / maxVal) * plotH;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });

      // labels
      ctx.fillStyle = "#94a3b8";
      ctx.font = "12px sans-serif";
      ctx.textAlign = "center";
      labels.forEach((label, i) => {
        if (i % 2 === 0) {
          const x = padding + i * stepX;
          ctx.fillText(label, x, h - 8);
        }
      });
    }

    function pushLiveData() {
      dataPoints.push(Math.floor(Math.random() * 100));
      labels.push(`T+${labels.length}`);
      if (dataPoints.length > 20) dataPoints.shift();
      if (labels.length > 20) labels.shift();
      updateMetrics();
      drawChart();
    }

    function addEventLogItem(label, value, category) {
      const li = document.createElement("li");
      const time = new Date().toLocaleTimeString();

      li.innerHTML = `
        <div>
          <strong>${label}</strong>
          <div class="muted">${time} · ${category}</div>
        </div>
        <div class="status">${value}</div>
      `;

      eventLogEl.prepend(li);

      while (eventLogEl.children.length > 10) {
        eventLogEl.removeChild(eventLogEl.lastChild);
      }
    }

    document.getElementById("dataForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const formData = new FormData(e.target);

      const label = formData.get("label").trim();
      const value = Number(formData.get("value"));
      const category = formData.get("category");

      if (!label || Number.isNaN(value)) return;

      dataPoints.push(value);
      labels.push(label);
      if (dataPoints.length > 20) dataPoints.shift();
      if (labels.length > 20) labels.shift();

      addEventLogItem(label, value, category);
      drawChart();
      e.target.reset();
    });

    document.getElementById("resetBtn").addEventListener("click", () => {
      dataPoints.splice(0, dataPoints.length, ...Array.from({ length: 20 }, () => Math.floor(Math.random() * 100)));
      labels.splice(0, labels.length, ...Array.from({ length: 20 }, (_, i) => `T-${19 - i}`));
      eventLogEl.innerHTML = "";
      drawChart();
    });

    // Initial render
    updateMetrics();
    drawChart();

    // Simulate real-time updates every 2 seconds
    liveInterval = setInterval(pushLiveData, 2000);

    // Cleanup if needed
    window.addEventListener("beforeunload", () => {
      if (liveInterval) clearInterval(liveInterval);
    });
  </script>
</body>
</html>
```

