## 4) `app.js`

```javascript
const totalEventsEl = document.getElementById("totalEvents");
const activeUsersEl = document.getElementById("activeUsers");
const avgResponseTimeEl = document.getElementById("avgResponseTime");
const eventListEl = document.getElementById("eventList");
const settingsOutputEl = document.getElementById("settingsOutput");
const dashboardForm = document.getElementById("dashboardForm");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const connectionStatusEl = document.getElementById("connectionStatus");

const metricNameInput = document.getElementById("metricName");
const thresholdInput = document.getElementById("threshold");
const updateFrequencyInput = document.getElementById("updateFrequency");
const alertEnabledInput = document.getElementById("alertEnabled");

let isStreaming = true;
let streamInterval = null;
let updateFrequency = 1000;

let state = {
  totalEvents: 0,
  activeUsers: 0,
  avgResponseTime: 0,
  metricName: "default",
  threshold: 100,
  alertEnabled: false,
};

const ctx = document.getElementById("liveChart").getContext("2d");

const liveChart = new Chart(ctx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Events",
        data: [],
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
      },
      {
        label: "Active Users",
        data: [],
        borderColor: "#22c55e",
        backgroundColor: "rgba(34, 197, 94, 0.12)",
        tension: 0.35,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb",
        },
      },
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
    },
  },
});

function addEvent(message, type = "info") {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  if (type === "alert") {
    li.style.borderColor = "rgba(239, 68, 68, 0.35)";
  }
  eventListEl.prepend(li);

  while (eventListEl.children.length > 6) {
    eventListEl.removeChild(eventListEl.lastChild);
  }
}

function updateDashboard() {
  state.totalEvents += Math.floor(Math.random() * 20) + 5;
  state.activeUsers = Math.max(0, Math.floor(Math.random() * 500));
  state.avgResponseTime = Math.floor(Math.random() * 250) + 50;

  totalEventsEl.textContent = state.totalEvents.toLocaleString();
  activeUsersEl.textContent = state.activeUsers.toLocaleString();
  avgResponseTimeEl.textContent = `${state.avgResponseTime} ms`;

  const timeLabel = new Date().toLocaleTimeString();

  liveChart.data.labels.push(timeLabel);
  liveChart.data.datasets[0].data.push(state.totalEvents % 1000);
  liveChart.data.datasets[1].data.push(state.activeUsers);

  if (liveChart.data.labels.length > 12) {
    liveChart.data.labels.shift();
    liveChart.data.datasets[0].data.shift();
    liveChart.data.datasets[1].data.shift();
  }

  liveChart.update();

  addEvent(
    `${state.metricName} updated: events=${state.totalEvents}, users=${state.activeUsers}, avg=${state.avgResponseTime}ms`
  );

  if (state.alertEnabled && state.totalEvents > state.threshold) {
    addEvent(`Alert: ${state.metricName} exceeded threshold (${state.threshold})`, "alert");
  }
}

function startStream() {
  clearInterval(streamInterval);
  streamInterval = setInterval(updateDashboard, updateFrequency);
  isStreaming = true;
  connectionStatusEl.textContent = "Connected";
  toggleStreamBtn.textContent = "Pause Stream";
  addEvent("Live stream started");
}

function stopStream() {
  clearInterval(streamInterval);
  isStreaming = false;
  connectionStatusEl.textContent = "Paused";
  toggleStreamBtn.textContent = "Resume Stream";
  addEvent("Live stream paused");
}

dashboardForm.addEventListener("submit", (e) => {
  e.preventDefault();

  state.metricName = metricNameInput.value.trim();
  state.threshold = Number(thresholdInput.value);
  updateFrequency = Number(updateFrequencyInput.value);
  state.alertEnabled = alertEnabledInput.checked;

  settingsOutputEl.textContent = JSON.stringify(
    {
      metricName: state.metricName,
      threshold: state.threshold,
      updateFrequency: `${updateFrequency / 1000}s`,
      alertEnabled: state.alertEnabled,
    },
    null,
    2
  );

  addEvent(`Settings applied for "${state.metricName}"`);

  if (isStreaming) {
    startStream();
  }
});

toggleStreamBtn.addEventListener("click", () => {
  if (isStreaming) {
    stopStream();
  } else {
    startStream();
  }
});

// Initialize with default data
metricNameInput.value = state.metricName;
thresholdInput.value = state.threshold;
updateFrequencyInput.value = updateFrequency;
alertEnabledInput.checked = state.alertEnabled;

settingsOutputEl.textContent = JSON.stringify(
  {
    metricName: state.metricName,
    threshold: state.threshold,
    updateFrequency: `${updateFrequency / 1000}s`,
    alertEnabled: state.alertEnabled,
  },
  null,
  2
);

startStream();
```

