## 3) File: `app.js`

```javascript
const ctx = document.getElementById("trafficChart");

const trafficChart = new Chart(ctx, {
  type: "line",
  data: {
    labels: ["-9", "-8", "-7", "-6", "-5", "-4", "-3", "-2", "-1", "Now"],
    datasets: [
      {
        label: "Requests / sec",
        data: [52, 58, 54, 62, 67, 70, 74, 73, 79, 82],
        borderColor: "#3b82f6",
        backgroundColor: "rgba(59, 130, 246, 0.2)",
        fill: true,
        tension: 0.35,
        pointRadius: 3,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb",
        },
      },
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
    },
  },
});

let liveUpdates = true;
let updateInterval = null;

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function updateMetrics() {
  document.getElementById("activeUsers").textContent = randomInt(1200, 1600).toLocaleString();
  document.getElementById("ordersPerMin").textContent = randomInt(70, 120).toLocaleString();
  document.getElementById("cpuLoad").textContent = `${randomInt(20, 75)}%`;
  document.getElementById("revenue").textContent = `$${randomInt(16000, 22000).toLocaleString()}`;

  const chartData = trafficChart.data.datasets[0].data;
  chartData.push(randomInt(50, 100));
  chartData.shift();

  trafficChart.data.labels.push("Now");
  trafficChart.data.labels.shift();
  trafficChart.update();
}

function startUpdates() {
  if (updateInterval) clearInterval(updateInterval);
  updateInterval = setInterval(() => {
    if (liveUpdates) updateMetrics();
  }, 2000);
}

document.getElementById("toggleUpdates").addEventListener("click", () => {
  liveUpdates = !liveUpdates;
  document.getElementById("toggleUpdates").textContent = liveUpdates ? "Pause Updates" : "Resume Updates";
  document.getElementById("connectionStatus").textContent = liveUpdates ? "● Live" : "● Paused";
  document.getElementById("connectionStatus").style.background = liveUpdates
    ? "rgba(16, 185, 129, 0.15)"
    : "rgba(245, 158, 11, 0.15)";
  document.getElementById("connectionStatus").style.color = liveUpdates ? "#6ee7b7" : "#fbbf24";
});

document.getElementById("alertForm").addEventListener("submit", (e) => {
  e.preventDefault();

  const form = e.target;
  const formData = new FormData(form);

  const alertName = formData.get("alertName");
  const threshold = formData.get("threshold");
  const priority = formData.get("priority");

  const tbody = document.getElementById("alertsTable");
  const row = document.createElement("tr");

  let badgeClass = "warning";
  let statusText = "Pending";

  if (priority === "high") {
    badgeClass = "success";
    statusText = "Active";
  }

  row.innerHTML = `
    <td>${alertName}</td>
    <td>${threshold}%</td>
    <td>${priority.charAt(0).toUpperCase() + priority.slice(1)}</td>
    <td><span class="badge ${badgeClass}">${statusText}</span></td>
  `;

  tbody.prepend(row);
  document.getElementById("formFeedback").textContent = `Alert "${alertName}" saved successfully.`;
  form.reset();
});

startUpdates();
```

