<body>
  <header>
    <h1>Real-Time Analytics Dashboard</h1>
    <p>Interactive browser-based dashboard with live chart updates and form-driven controls.</p>
  </header>

  <main class="container">
    <!-- Left panel: form -->
    <section class="panel">
      <h2>Controls</h2>

      <form id="controlForm">
        <div class="form-group">
          <label for="metricName">Metric Name</label>
          <input type="text" id="metricName" value="Requests" required />
        </div>

        <div class="form-group">
          <label for="initialValue">Initial Value</label>
          <input type="number" id="initialValue" value="50" min="0" required />
        </div>

        <div class="form-group">
          <label for="trendType">Trend Type</label>
          <select id="trendType">
            <option value="random">Random</option>
            <option value="up">Upward</option>
            <option value="down">Downward</option>
          </select>
        </div>

        <div class="form-group">
          <label for="updateSpeed">Update Speed (ms)</label>
          <input type="number" id="updateSpeed" value="1000" min="250" step="250" />
        </div>

        <div class="toolbar">
          <button type="submit" class="primary">Apply</button>
          <button type="button" id="toggleUpdates" class="secondary">Pause</button>
        </div>
      </form>

      <p class="small-note">
        Tip: change the form values to update the live chart behavior in real time.
      </p>
    </section>

    <!-- Right panel: dashboard -->
    <section class="panel">
      <h2>Overview</h2>

      <div class="stats">
        <div class="stat-card">
          <div class="label">Current Metric</div>
          <div class="value" id="currentMetricValue">50</div>
          <div class="trend" id="trendDisplay green">Stable</div>
        </div>
        <div class="stat-card">
          <div class="label">Max</div>
          <div class="value" id="maxValue">50</div>
          <div class="trend">All-time peak</div>
        </div>
        <div class="stat-card">
          <div class="label">Min</div>
          <div class="value" id="minValue">50</div>
          <div class="trend">All-time low</div>
        </div>
      </div>

      <div class="charts">
        <div class="panel" style="margin:0;">
          <h2>Live Line Chart</h2>
          <div class="chart-wrap">
            <canvas id="lineChart"></canvas>
          </div>
        </div>

        <div class="panel" style="margin:0;">
          <h2>Distribution</h2>
          <div class="chart-wrap">
            <canvas id="barChart"></canvas>
          </div>
        </div>
      </div>

      <div class="panel" style="margin:0;">
        <h2>Recent Events</h2>
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Time</th>
                <th>Metric</th>
                <th>Value</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody id="eventsTable">
              <tr>
                <td colspan="4">No events yet.</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </section>
  </main>

  <script>
    const controlForm = document.getElementById("controlForm");
    const toggleUpdatesBtn = document.getElementById("toggleUpdates");

    const metricNameInput = document.getElementById("metricName");
    const initialValueInput = document.getElementById("initialValue");
    const trendTypeInput = document.getElementById("trendType");
    const updateSpeedInput = document.getElementById("updateSpeed");

    const currentMetricValueEl = document.getElementById("currentMetricValue");
    const maxValueEl = document.getElementById("maxValue");
    const minValueEl = document.getElementById("minValue");
    const trendDisplayEl = document.getElementById("trendDisplay");
    const eventsTable = document.getElementById("eventsTable");

    let metricName = "Requests";
    let currentValue = 50;
    let maxValue = 50;
    let minValue = 50;
    let trendType = "random";
    let updateSpeed = 1000;
    let intervalId = null;
    let isRunning = true;
    let previousValue = currentValue;

    const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
    const dataPoints = Array(10).fill(currentValue);

    const lineCtx = document.getElementById("lineChart").getContext("2d");
    const barCtx = document.getElementById("barChart").getContext("2d");

    const lineChart = new Chart(lineCtx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: metricName,
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.4,
          fill: true,
          pointRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    const barChart = new Chart(barCtx, {
      type: "bar",
      data: {
        labels: ["Min", "Avg", "Current", "Max"],
        datasets: [{
          label: "Values",
          data: [minValue, currentValue, currentValue, maxValue],
          backgroundColor: [
            "#ef4444",
            "#f59e0b",
            "#38bdf8",
            "#22c55e"
          ]
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    function updateStats() {
      currentMetricValueEl.textContent = currentValue.toFixed(0);
      maxValueEl.textContent = maxValue.toFixed(0);
      minValueEl.textContent = minValue.toFixed(0);

      const diff = currentValue - previousValue;
      trendDisplayEl.textContent =
        diff > 0 ? `+${diff.toFixed(0)} up` :
        diff < 0 ? `${diff.toFixed(0)} down` :
        "Stable";

      trendDisplayEl.className = "trend " + (diff >= 0 ? "green" : "red");
    }

    function updateCharts() {
      lineChart.data.datasets[0].label = metricName;
      lineChart.data.datasets[0].data = [...dataPoints];
      lineChart.update();

      const avg = dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length;
      barChart.data.datasets[0].data = [minValue, avg, currentValue, maxValue];
      barChart.update();
    }

    function addEventRow(value) {
      const now = new Date().toLocaleTimeString();

      if (eventsTable.children.length === 1 && eventsTable.children[0].children.length === 1) {
        eventsTable.innerHTML = "";
      }

      const status = value > previousValue ? "Increase" : value < previousValue ? "Decrease" : "No Change";
      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${now}</td>
        <td>${metricName}</td>
        <td>${value.toFixed(0)}</td>
        <td><span class="status">${status}</span></td>
      `;
      eventsTable.prepend(row);

      while (eventsTable.children.length > 5) {
        eventsTable.removeChild(eventsTable.lastChild);
      }
    }

    function generateNextValue() {
      previousValue = currentValue;

      let delta = 0;
      if (trendType === "random") {
        delta = Math.random() * 20 - 10;
      } else if (trendType === "up") {
        delta = Math.random() * 12;
      } else if (trendType === "down") {
        delta = -(Math.random() * 12);
      }

      currentValue = Math.max(0, currentValue + delta);
      maxValue = Math.max(maxValue, currentValue);
      minValue = Math.min(minValue, currentValue);

      dataPoints.push(currentValue);
      dataPoints.shift();

      updateStats();
      updateCharts();
      addEventRow(currentValue);
    }

    function startUpdates() {
      stopUpdates();
      intervalId = setInterval(generateNextValue, updateSpeed);
      isRunning = true;
      toggleUpdatesBtn.textContent = "Pause";
    }

    function stopUpdates() {
      if (intervalId) clearInterval(intervalId);
      intervalId = null;
      isRunning = false;
      toggleUpdatesBtn.textContent = "Resume";
    }

    controlForm.addEventListener("submit", (e) => {
      e.preventDefault();

      metricName = metricNameInput.value.trim() || "Metric";
      currentValue = Number(initialValueInput.value) || 0;
      previousValue = currentValue;
      trendType = trendTypeInput.value;
      updateSpeed = Number(updateSpeedInput.value) || 1000;

      maxValue = currentValue;
      minValue = currentValue;

      dataPoints.splice(0, dataPoints.length, ...Array(10).fill(currentValue));

      updateStats();
      updateCharts();

      if (isRunning) startUpdates();
    });

    toggleUpdatesBtn.addEventListener("click", () => {
      if (isRunning) stopUpdates();
      else startUpdates();
    });

    // Initialize
    updateStats();
    updateCharts();
    startUpdates();
  </script>
</body>
</html>
