        <div class="value" id="dataPoints">0</div>
      </div>
      <div class="card">
        <div class="label">Status</div>
        <div class="value" id="statusText">Idle</div>
      </div>
    </section>

    <section class="grid">
      <div class="panel">
        <h2>Live Visualization</h2>
        <div class="controls">
          <button class="primary" id="toggleLive">Start Live Updates</button>
          <button class="secondary" id="addRandom">Add Random Point</button>
          <button class="danger" id="clearData">Clear Data</button>
        </div>
        <div class="chart-wrap">
          <canvas id="liveChart"></canvas>
        </div>
      </div>

      <div class="panel">
        <h2>Add Data Manually</h2>
        <form id="dataForm">
