            Value
            <input type="number" id="valueInput" placeholder="e.g. 42" required />
          </label>

          <label>
            Category
            <select id="categoryInput">
              <option value="manual">Manual</option>
              <option value="sensor-a">Sensor A</option>
              <option value="sensor-b">Sensor B</option>
            </select>
          </label>

          <button class="primary" type="submit">Add Point</button>
          <div class="message" id="formMessage"></div>
        </form>

        <div class="data-list" id="dataList"></div>
      </div>
    </section>
  </main>

  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    const labels = [];
    const values = [];
    const categories = [];

    const maxPoints = 20;
    let liveInterval = null;
    let liveRunning = false;

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const dataPointsEl = document.getElementById('dataPoints');
    const statusTextEl = document.getElementById('statusText');
    const toggleLiveBtn = document.getElementById('toggleLive');
    const addRandomBtn = document.getElementById('addRandom');
    const clearDataBtn = document.getElementById('clearData');
    const dataForm = document.getElementById('dataForm');
    const labelInput = document.getElementById('labelInput');
    const valueInput = document.getElementById('valueInput');
    const categoryInput = document.getElementById('categoryInput');
    const formMessage = document.getElementById('formMessage');
    const dataList = document.getElementById('dataList');

    function formatTime() {
      return new Date().toLocaleTimeString([], { hour12: false });
    }

    function randomValue() {
      return Math.floor(Math.random() * 100);
    }

    function addPoint(label, value, category = 'manual') {
      labels.push(label);
      values.push(value);
      categories.push(category);

      if (labels.length > maxPoints) {
        labels.shift();
        values.shift();
        categories.shift();
      }

      updateChart();
      refreshDashboard();
      renderDataList();
    }

    function updateChart() {
      chart.data.labels = labels;
      chart.data.datasets[0].data = values;
      chart.update();
    }

    function refreshDashboard() {
      const current = values.length ? values[values.length - 1] : 0;
      const avg = values.length
        ? (values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(1)
        : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      dataPointsEl.textContent = values.length;
      statusTextEl.textContent = liveRunning ? 'Live' : 'Idle';
    }

    function renderDataList() {
      dataList.innerHTML = '';
      labels.forEach((label, index) => {
        const item = document.createElement('div');
        item.className = 'data-item';
        item.innerHTML = `
          <span>${label} (${categories[index]})</span>
          <strong>${values[index]}</strong>
        `;
        dataList.appendChild(item);
      });
    }

    function showMessage(text, type = '') {
      formMessage.textContent = text;
      formMessage.className = `message ${type}`.trim();
    }

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Metric',
          data: values,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          borderWidth: 2,
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 300 },
        plugins: {
          legend: {
            labels: {
              color: '#e5e7eb'
            }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            beginAtZero: true,
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        }
      }
    });

    function startLiveUpdates() {
      if (liveRunning) return;
      liveRunning = true;
      toggleLiveBtn.textContent = 'Stop Live Updates';
      statusTextEl.textContent = 'Live';

      liveInterval = setInterval(() => {
        addPoint(formatTime(), randomValue(), 'live');
      }, 1500);
    }

    function stopLiveUpdates() {
      liveRunning = false;
      toggleLiveBtn.textContent = 'Start Live Updates';
      statusTextEl.textContent = 'Idle';

      if (liveInterval) {
        clearInterval(liveInterval);
        liveInterval = null;
      }
    }

    toggleLiveBtn.addEventListener('click', () => {
      if (liveRunning) stopLiveUpdates();
      else startLiveUpdates();
    });

    addRandomBtn.addEventListener('click', () => {
      addPoint(formatTime(), randomValue(), 'random');
      showMessage('Random data point added.', 'success');
    });

    clearDataBtn.addEventListener('click', () => {
      labels.length = 0;
      values.length = 0;
      categories.length = 0;
      updateChart();
      refreshDashboard();
      renderDataList();
      showMessage('All data cleared.', 'success');
    });

    dataForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = Number(valueInput.value);
      const category = categoryInput.value;

      if (!label) {
        showMessage('Please provide a label.', 'error');
        return;
      }

      if (Number.isNaN(value)) {
        showMessage('Please enter a valid number.', 'error');
        return;
      }

      addPoint(label, value, category);
      showMessage('Data point added successfully.', 'success');
      dataForm.reset();
      labelInput.focus();
    });

    // Seed initial data
    for (let i = 0; i < 5; i++) {
      addPoint(`Init ${i + 1}`, randomValue(), 'seed');
    }
    showMessage('Dashboard ready.', 'success');
  </script>
</body>
</html>
```

