```javascript
const activeUsersEl = document.getElementById("activeUsers");
const conversionsEl = document.getElementById("conversions");
const revenueEl = document.getElementById("revenue");
const connectionStatusEl = document.getElementById("connectionStatus");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const submissionOutput = document.getElementById("submissionOutput");

const form = document.getElementById("dashboardForm");
const metricNameInput = document.getElementById("metricName");
const metricValueInput = document.getElementById("metricValue");
const metricCategoryInput = document.getElementById("metricCategory");

const ctx = document.getElementById("activityChart").getContext("2d");

let isStreaming = true;
let streamInterval = null;

let activeUsers = 120;
let conversions = 18;
let revenue = 5400;

const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
const dataPoints = Array.from({ length: 10 }, () => Math.floor(Math.random() * 100));

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Activity",
        data: dataPoints,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.2)",
        tension: 0.35,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      y: {
        beginAtZero: true,
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function renderStats() {
  activeUsersEl.textContent = activeUsers.toLocaleString();
  conversionsEl.textContent = conversions.toLocaleString();
  revenueEl.textContent = `$${revenue.toLocaleString()}`;
}

function pushLiveData() {
  const newValue = Math.floor(Math.random() * 100);
  chart.data.labels.shift();
  chart.data.labels.push(new Date().toLocaleTimeString());
  chart.data.datasets[0].data.shift();
  chart.data.datasets[0].data.push(newValue);
  chart.update();

  activeUsers += Math.floor(Math.random() * 8) - 2;
  conversions += Math.floor(Math.random() * 3);
  revenue += Math.floor(Math.random() * 250);

  renderStats();
}

function startStream() {
  if (streamInterval) clearInterval(streamInterval);
  streamInterval = setInterval(pushLiveData, 2000);
  connectionStatusEl.textContent = "Live";
  toggleStreamBtn.textContent = "Pause Stream";
  isStreaming = true;
}

function stopStream() {
  clearInterval(streamInterval);
  streamInterval = null;
  connectionStatusEl.textContent = "Paused";
  toggleStreamBtn.textContent = "Resume Stream";
  isStreaming = false;
}

toggleStreamBtn.addEventListener("click", () => {
  if (isStreaming) stopStream();
  else startStream();
});

form.addEventListener("submit", (e) => {
  e.preventDefault();

  const metricName = metricNameInput.value.trim();
  const metricValue = Number(metricValueInput.value);
  const metricCategory = metricCategoryInput.value;

  const submission = {
    metricName,
    metricValue,
    metricCategory,
    timestamp: new Date().toISOString(),
  };

  submissionOutput.textContent = JSON.stringify(submission, null, 2);

  // Example form-driven state update
  if (metricCategory === "users") {
    activeUsers = metricValue;
  } else if (metricCategory === "sales") {
    conversions = metricValue;
  } else if (metricCategory === "traffic") {
    revenue = metricValue;
  }

  renderStats();
  form.reset();
});

renderStats();
startStream();
```

