## 4) `app.js`

```javascript
const usersOnlineEl = document.getElementById("usersOnline");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const formMessageEl = document.getElementById("formMessage");

const settingsForm = document.getElementById("settingsForm");
const refreshRateInput = document.getElementById("refreshRate");
const alertThresholdInput = document.getElementById("alertThreshold");
const enableAlertsInput = document.getElementById("enableAlerts");

let refreshIntervalMs = 2000;
let alertThreshold = 75;
let alertsEnabled = true;
let updateTimer = null;

const trafficCtx = document.getElementById("trafficChart").getContext("2d");
const healthCtx = document.getElementById("healthChart").getContext("2d");

const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
const trafficData = Array.from({ length: 10 }, () => randomInt(40, 120));
const healthData = Array.from({ length: 10 }, () => randomInt(70, 100));

const trafficChart = new Chart(trafficCtx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Requests/min",
        data: trafficData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.12)",
        fill: true,
        tension: 0.35
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: { ticks: { color: "#9ca3af" }, grid: { color: "#243041" } },
      y: { ticks: { color: "#9ca3af" }, grid: { color: "#243041" } }
    },
    plugins: {
      legend: { labels: { color: "#e5e7eb" } }
    }
  }
});

const healthChart = new Chart(healthCtx, {
  type: "bar",
  data: {
    labels: ["CPU", "Memory", "Disk", "Network"],
    datasets: [
      {
        label: "Health %",
        data: [92, 84, 76, 95],
        backgroundColor: ["#22c55e", "#38bdf8", "#f59e0b", "#8b5cf6"]
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: { ticks: { color: "#9ca3af" }, grid: { color: "#243041" } },
      y: {
        min: 0,
        max: 100,
        ticks: { color: "#9ca3af" },
        grid: { color: "#243041" }
      }
    },
    plugins: {
      legend: { labels: { color: "#e5e7eb" } }
    }
  }
});

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function updateMetrics() {
  const usersOnline = randomInt(120, 1200);
  const requestsPerMin = randomInt(50, 200);
  const errorRate = randomInt(0, 12);

  usersOnlineEl.textContent = usersOnline.toLocaleString();
  requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
  errorRateEl.textContent = `${errorRate}%`;

  trafficData.shift();
  trafficData.push(requestsPerMin);

  healthData.shift();
  healthData.push(randomInt(70, 100));

  trafficChart.update();
  healthChart.data.datasets[0].data = [
    randomInt(80, 100),
    randomInt(70, 95),
    randomInt(60, 98),
    randomInt(75, 100)
  ];
  healthChart.update();

  if (alertsEnabled && errorRate > alertThreshold) {
    formMessageEl.textContent = `Alert: error rate (${errorRate}%) exceeded threshold (${alertThreshold}%).`;
    formMessageEl.style.color = "#f59e0b";
  } else {
    formMessageEl.textContent = "Dashboard updated successfully.";
    formMessageEl.style.color = "#9ca3af";
  }
}

function startLiveUpdates() {
  if (updateTimer) clearInterval(updateTimer);
  updateTimer = setInterval(updateMetrics, refreshIntervalMs);
}

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  refreshIntervalMs = Number(refreshRateInput.value) || 2000;
  alertThreshold = Number(alertThresholdInput.value) || 75;
  alertsEnabled = enableAlertsInput.checked;

  if (refreshIntervalMs < 500) refreshIntervalMs = 500;
  if (alertThreshold < 0) alertThreshold = 0;
  if (alertThreshold > 100) alertThreshold = 100;

  refreshRateInput.value = refreshIntervalMs;
  alertThresholdInput.value = alertThreshold;

  formMessageEl.textContent = "Settings applied.";
  formMessageEl.style.color = "#22c55e";

  startLiveUpdates();
});

updateMetrics();
startLiveUpdates();
```

