## 4) `app.js`

```javascript
const visitorsCountEl = document.getElementById("visitorsCount");
const salesCountEl = document.getElementById("salesCount");
const conversionRateEl = document.getElementById("conversionRate");
const form = document.getElementById("updateForm");
const nameInput = document.getElementById("nameInput");
const metricInput = document.getElementById("metricInput");
const commentInput = document.getElementById("commentInput");
const formMessage = document.getElementById("formMessage");
const activityLog = document.getElementById("activityLog");

let visitors = 120;
let sales = 18;
let chartLabels = [];
let chartData = [];

function updateStats() {
  const conversionRate = visitors > 0 ? ((sales / visitors) * 100).toFixed(1) : "0.0";

  visitorsCountEl.textContent = visitors;
  salesCountEl.textContent = sales;
  conversionRateEl.textContent = `${conversionRate}%`;
}

function addLogEntry(text) {
  const item = document.createElement("li");
  item.textContent = text;
  activityLog.prepend(item);

  // keep log short
  while (activityLog.children.length > 8) {
    activityLog.removeChild(activityLog.lastChild);
  }
}

const ctx = document.getElementById("liveChart").getContext("2d");
const liveChart = new Chart(ctx, {
  type: "line",
  data: {
    labels: chartLabels,
    datasets: [
      {
        label: "Live Metric",
        data: chartData,
        borderColor: "#2563eb",
        backgroundColor: "rgba(37, 99, 235, 0.15)",
        fill: true,
        tension: 0.35,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    scales: {
      y: {
        beginAtZero: true,
      },
    },
  },
});

function pushChartPoint(value) {
  const now = new Date();
  const label = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });

  chartLabels.push(label);
  chartData.push(value);

  if (chartLabels.length > 10) {
    chartLabels.shift();
    chartData.shift();
  }

  liveChart.update();
}

// Simulated real-time updates
setInterval(() => {
  visitors += Math.floor(Math.random() * 5) + 1;
  sales += Math.random() > 0.75 ? 1 : 0;

  updateStats();
  pushChartPoint(visitors);

  addLogEntry(`Live update: visitors=${visitors}, sales=${sales}`);
}, 3000);

// Form handling
form.addEventListener("submit", (e) => {
  e.preventDefault();

  const name = nameInput.value.trim();
  const metric = Number(metricInput.value);
  const comment = commentInput.value.trim();

  if (!name) {
    showMessage("Please enter your name.", "error");
    return;
  }

  if (Number.isNaN(metric) || metric < 0) {
    showMessage("Please enter a valid metric value.", "error");
    return;
  }

  // Example interaction with dashboard state
  visitors += Math.floor(metric);
  sales += metric > 25 ? 1 : 0;

  updateStats();
  pushChartPoint(visitors);

  const logText = `${name} submitted metric ${metric}${comment ? ` — ${comment}` : ""}`;
  addLogEntry(logText);

  showMessage("Form submitted successfully.", "success");
  form.reset();
});

function showMessage(text, type) {
  formMessage.textContent = text;
  formMessage.className = `message ${type}`;

  setTimeout(() => {
    formMessage.textContent = "";
    formMessage.className = "message";
  }, 3000);
}

// Initial render
updateStats();
pushChartPoint(visitors);
addLogEntry("Dashboard initialized.");
```

