## 4) `app.js`

```javascript
const connectionStatus = document.getElementById("connectionStatus");
const totalEventsEl = document.getElementById("totalEvents");
const activeUsersEl = document.getElementById("activeUsers");
const avgLatencyEl = document.getElementById("avgLatency");
const errorCountEl = document.getElementById("errorCount");
const activityLog = document.getElementById("activityLog");
const formMessage = document.getElementById("formMessage");

const refreshRateInput = document.getElementById("refreshRate");
const eventMultiplierInput = document.getElementById("eventMultiplier");
const eventMultiplierValue = document.getElementById("eventMultiplierValue");
const thresholdInput = document.getElementById("threshold");
const enableSimulationInput = document.getElementById("enableSimulation");
const settingsForm = document.getElementById("settingsForm");

let settings = {
  refreshRate: 1000,
  eventMultiplier: 3,
  threshold: 8,
  enableSimulation: true,
};

let totalEvents = 0;
let activeUsers = 12;
let avgLatency = 120;
let errorCount = 0;
let timerId = null;

const chartCtx = document.getElementById("realtimeChart").getContext("2d");

const realtimeChart = new Chart(chartCtx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Events",
        data: [],
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
      },
      {
        label: "Latency",
        data: [],
        borderColor: "#f59e0b",
        backgroundColor: "rgba(245, 158, 11, 0.12)",
        tension: 0.35,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#334155" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "#334155" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function updateMetrics() {
  totalEventsEl.textContent = totalEvents;
  activeUsersEl.textContent = activeUsers;
  avgLatencyEl.textContent = `${Math.round(avgLatency)} ms`;
  errorCountEl.textContent = errorCount;
}

function addLog(message, type = "info") {
  const li = document.createElement("li");
  const time = new Date().toLocaleTimeString();

  li.innerHTML = `
    <strong>[${type.toUpperCase()}]</strong> ${message}
    <span class="meta">${time}</span>
  `;

  activityLog.prepend(li);

  while (activityLog.children.length > 20) {
    activityLog.removeChild(activityLog.lastChild);
  }
}

function simulateIncomingData() {
  if (!settings.enableSimulation) return;

  const multiplier = settings.eventMultiplier;
  const newEvents = Math.floor(Math.random() * multiplier) + 1;
  const newLatency = 80 + Math.random() * 180;
  const errorOccurred = Math.random() < 0.15;
  const userDelta = Math.floor(Math.random() * 3) - 1;

  totalEvents += newEvents;
  avgLatency = avgLatency * 0.85 + newLatency * 0.15;
  activeUsers = Math.max(0, activeUsers + userDelta);

  if (errorOccurred) {
    errorCount += 1;
    addLog("Error detected in incoming stream.", "error");
  } else {
    addLog(`Processed ${newEvents} new event(s).`, "info");
  }

  const nowLabel = new Date().toLocaleTimeString();
  realtimeChart.data.labels.push(nowLabel);
  realtimeChart.data.datasets[0].data.push(newEvents);
  realtimeChart.data.datasets[1].data.push(Math.round(newLatency));

  if (realtimeChart.data.labels.length > 15) {
    realtimeChart.data.labels.shift();
    realtimeChart.data.datasets[0].data.shift();
    realtimeChart.data.datasets[1].data.shift();
  }

  if (newEvents >= settings.threshold) {
    formMessage.textContent = `Alert: event count (${newEvents}) reached or exceeded threshold (${settings.threshold}).`;
    addLog(`Threshold alert triggered at ${newEvents}.`, "warn");
  } else {
    formMessage.textContent = "Settings active and stream running.";
  }

  updateMetrics();
  realtimeChart.update();
}

function startSimulation() {
  if (timerId) clearInterval(timerId);

  connectionStatus.textContent = settings.enableSimulation ? "Live" : "Paused";
  connectionStatus.style.color = settings.enableSimulation ? "#22c55e" : "#f59e0b";

  if (settings.enableSimulation) {
    timerId = setInterval(simulateIncomingData, settings.refreshRate);
  }
}

eventMultiplierInput.addEventListener("input", () => {
  eventMultiplierValue.textContent = eventMultiplierInput.value;
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  settings.refreshRate = Math.max(500, parseInt(refreshRateInput.value, 10) || 1000);
  settings.eventMultiplier = parseInt(eventMultiplierInput.value, 10) || 3;
  settings.threshold = parseInt(thresholdInput.value, 10) || 8;
  settings.enableSimulation = enableSimulationInput.checked;

  refreshRateInput.value = settings.refreshRate;
  eventMultiplierInput.value = settings.eventMultiplier;
  eventMultiplierValue.textContent = settings.eventMultiplier;
  thresholdInput.value = settings.threshold;

  formMessage.textContent = "Settings applied successfully.";
  addLog("Updated dashboard settings.", "info");

  startSimulation();
});

refreshRateInput.value = settings.refreshRate;
eventMultiplierInput.value = settings.eventMultiplier;
eventMultiplierValue.textContent = settings.eventMultiplier;
thresholdInput.value = settings.threshold;

updateMetrics();
addLog("Dashboard initialized.", "info");
startSimulation();
```

