## 4) `script.js`

```javascript
const configOutput = document.getElementById("configOutput");
const activityFeed = document.getElementById("activityFeed");

const visitorsCount = document.getElementById("visitorsCount");
const ordersCount = document.getElementById("ordersCount");
const revenueCount = document.getElementById("revenueCount");
const conversionRate = document.getElementById("conversionRate");

const dashboardForm = document.getElementById("dashboardForm");
const pauseBtn = document.getElementById("pauseBtn");
const resetBtn = document.getElementById("resetBtn");
const liveStatus = document.getElementById("liveStatus");

const ctx = document.getElementById("trafficChart").getContext("2d");

let isPaused = false;
let updateIntervalMs = 2000;
let intervalId = null;

let config = {
  targetName: "Global",
  interval: 2,
  autoScale: true,
};

let visitors = 120;
let orders = 18;
let revenue = 5400;
let conversion = 3.2;

const labels = [];
const dataPoints = [];

const trafficChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Active Users",
        data: dataPoints,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        fill: true,
        tension: 0.35,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(255,255,255,0.05)" },
        beginAtZero: true,
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function renderMetrics() {
  visitorsCount.textContent = visitors.toLocaleString();
  ordersCount.textContent = orders.toLocaleString();
  revenueCount.textContent = `$${revenue.toLocaleString()}`;
  conversionRate.textContent = `${conversion.toFixed(1)}%`;
}

function addActivity(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  activityFeed.prepend(li);

  while (activityFeed.children.length > 8) {
    activityFeed.removeChild(activityFeed.lastChild);
  }
}

function updateLiveData() {
  if (isPaused) return;

  const activeUsers = Math.max(10, Math.round(visitors + (Math.random() * 40 - 20)));
  visitors = Math.max(0, visitors + Math.floor(Math.random() * 12 - 4));
  orders = Math.max(0, orders + Math.floor(Math.random() * 4));
  revenue = Math.max(0, revenue + Math.floor(Math.random() * 350));
  conversion = Math.max(0, Math.min(100, conversion + (Math.random() * 0.5 - 0.2)));

  const timeLabel = new Date().toLocaleTimeString();

  labels.push(timeLabel);
  dataPoints.push(activeUsers);

  if (labels.length > 20) {
    labels.shift();
    dataPoints.shift();
  }

  if (!config.autoScale) {
    trafficChart.options.scales.y.max = 250;
  } else {
    trafficChart.options.scales.y.max = undefined;
  }

  trafficChart.update();
  renderMetrics();
  addActivity(`Live metrics updated for ${config.targetName}`);
}

function startUpdates() {
  clearInterval(intervalId);
  intervalId = setInterval(updateLiveData, updateIntervalMs);
}

dashboardForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const formData = new FormData(dashboardForm);
  config = {
    targetName: formData.get("targetName"),
    interval: Number(formData.get("interval")),
    autoScale: formData.get("autoScale") === "on",
  };

  updateIntervalMs = config.interval * 1000;
  configOutput.textContent = JSON.stringify(config, null, 2);

  addActivity(`Settings applied for ${config.targetName}`);
  startUpdates();
});

pauseBtn.addEventListener("click", () => {
  isPaused = !isPaused;
  pauseBtn.textContent = isPaused ? "Resume" : "Pause";
  liveStatus.textContent = isPaused ? "Paused" : "Connected";
  addActivity(isPaused ? "Live updates paused" : "Live updates resumed");
});

resetBtn.addEventListener("click", () => {
  visitors = 120;
  orders = 18;
  revenue = 5400;
  conversion = 3.2;

  labels.length = 0;
  dataPoints.length = 0;
  trafficChart.update();
  renderMetrics();
  addActivity("Dashboard reset to default state");
});

configOutput.textContent = JSON.stringify(config, null, 2);
renderMetrics();
startUpdates();
addActivity("Dashboard initialized");
