    const ctx = document.getElementById('trafficChart').getContext('2d');
    const labels = [];
    const dataPoints = [];

    for (let i = 9; i >= 0; i--) {
      labels.push(`${10 - i}s ago`);
      dataPoints.push(Math.floor(Math.random() * 100) + 50);
    }

    const trafficChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Traffic',
          data: dataPoints,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          fill: true,
          tension: 0.35,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.12)' }
          },
          y: {
            ticks: { color: '#94a3b8' },
            grid: { color: 'rgba(148, 163, 184, 0.12)' }
          }
        }
      }
    });

    const activityLog = document.getElementById('activityLog');
    const activityCount = document.getElementById('activityCount');
    const filterCategory = document.getElementById('filterCategory');
    const entries = [];

    function renderLog() {
      const filter = filterCategory.value;
      activityLog.innerHTML = '';

      const filtered = entries.filter(entry => filter === 'All' || entry.category === filter);

      activityCount.textContent = `${filtered.length} entr${filtered.length === 1 ? 'y' : 'ies'}`;

      filtered.slice().reverse().forEach(entry => {
        const div = document.createElement('div');
        div.className = 'log-item';
        div.innerHTML = `
          <div class="tag">${entry.category}</div>
          <div><strong>${entry.name}</strong></div>
          <div class="muted" style="margin-top: 6px;">${entry.message}</div>
          <div class="muted" style="margin-top: 8px; font-size: 12px;">${entry.time}</div>
        `;
        activityLog.appendChild(div);
      });
    }

    document.getElementById('entryForm').addEventListener('submit', function (e) {
      e.preventDefault();

      const name = document.getElementById('name').value.trim();
      const category = document.getElementById('category').value;
      const message = document.getElementById('message').value.trim();

      if (!name || !message) return;

      entries.push({
        name,
        category,
        message,
        time: new Date().toLocaleTimeString()
      });

      this.reset();
      renderLog();
    });

    filterCategory.addEventListener('change', renderLog);

    function updateStats() {
      const activeUsers = document.getElementById('activeUsers');
      const requestsPerMin = document.getElementById('requestsPerMin');
      const errorCount = document.getElementById('errorCount');
      const conversionRate = document.getElementById('conversionRate');

      let users = parseInt(activeUsers.textContent, 10);
      let requests = parseInt(requestsPerMin.textContent, 10);
      let errors = parseInt(errorCount.textContent, 10);
      let conversion = parseFloat(conversionRate.textContent);

      users += Math.floor(Math.random() * 7) - 3;
      requests += Math.floor(Math.random() * 25) - 10;
      errors += Math.random() > 0.85 ? 1 : (Math.random() > 0.95 ? -1 : 0);
      conversion += (Math.random() - 0.5) * 0.2;

      users = Math.max(0, users);
      requests = Math.max(0, requests);
      errors = Math.max(0, errors);
      conversion = Math.max(0, conversion);

      activeUsers.textContent = users;
      requestsPerMin.textContent = requests;
      errorCount.textContent = errors;
      conversionRate.textContent = conversion.toFixed(1) + '%';
    }

    function updateChart() {
      const next = Math.floor(Math.random() * 100) + 50;
      dataPoints.push(next);
      dataPoints.shift();

      labels.push('now');
      labels.shift();

      trafficChart.update();
    }

    // Seed initial entries
    entries.push(
      {
        name: 'System',
        category: 'Ops',
        message: 'Dashboard initialized successfully.',
        time: new Date().toLocaleTimeString()
      },
      {
        name: 'Alex',
        category: 'Support',
        message: 'Resolved 2 support tickets.',
        time: new Date().toLocaleTimeString()
      }
    );

    renderLog();
    setInterval(() => {
      updateStats();
      updateChart();
    }, 1000);
  </script>
