        source
      };

      state.data.push(point);
      if (state.data.length > state.maxPoints * 3) {
        state.data.shift();
      }

      updateUI();
    }

    function getVisibleData() {
      return state.filter === 'all'
        ? state.data
        : state.data.filter(d => d.category === state.filter);
    }

    function updateMetrics(visible) {
      dom.totalEvents.textContent = visible.length;
      const avg = visible.length
        ? visible.reduce((sum, d) => sum + d.value, 0) / visible.length
        : 0;
      dom.avgValue.textContent = avg.toFixed(1);

      const latest = visible[visible.length - 1];
      if (latest) {
        dom.latestValue.textContent = latest.value;
        dom.latestCategory.textContent = `Category: ${latest.category}`;
      } else {
        dom.latestValue.textContent = '0';
        dom.latestCategory.textContent = 'Category: —';
      }
    }

    function updateLog() {
      const visible = getVisibleData().slice(-8).reverse();
      dom.logList.innerHTML = visible.map(d => `
        <li>
          <strong>${d.category.toUpperCase()}</strong> — ${d.value}
          ${d.note ? `<div>${escapeHtml(d.note)}</div>` : ''}
          <small>${d.source} · ${d.time.toLocaleTimeString()}</small>
        </li>
      `).join('');
    }

    function drawChart() {
      const visible = getVisibleData().slice(-state.maxPoints);

      const width = dom.chart.width;
      const height = dom.chart.height;
      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, width, height);

      // Grid
      ctx.strokeStyle = '#1f2937';
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(40, y);
        ctx.lineTo(width - 10, y);
        ctx.stroke();
      }

      // Axes labels
      ctx.fillStyle = '#9ca3af';
      ctx.font = '12px sans-serif';
      ctx.fillText('100', 8, 16);
      ctx.fillText('0', 14, height - 10);

      if (!visible.length) {
        ctx.fillStyle = '#9ca3af';
        ctx.fillText('No data available', width / 2 - 50, height / 2);
        return;
      }

      const padLeft = 40;
      const padRight = 20;
      const plotWidth = width - padLeft - padRight;
      const plotHeight = height - 20;
      const maxVal = Math.max(...visible.map(d => d.value), 100);

      const colors = {
        alpha: '#38bdf8',
        beta: '#22c55e',
        gamma: '#f59e0b'
      };

      visible.forEach((d, i) => {
        const x = padLeft + (i / Math.max(1, visible.length - 1)) * plotWidth;
        const y = plotHeight - (d.value / maxVal) * plotHeight + 10;

        // line point
        ctx.fillStyle = colors[d.category] || '#e5e7eb';
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fill();

        // line
        if (i > 0) {
          const prev = visible[i - 1];
          const px = padLeft + ((i - 1) / Math.max(1, visible.length - 1)) * plotWidth;
          const py = plotHeight - (prev.value / maxVal) * plotHeight + 10;
          ctx.strokeStyle = colors[d.category] || '#e5e7eb';
          ctx.beginPath();
          ctx.moveTo(px, py);
          ctx.lineTo(x, y);
          ctx.stroke();
        }
      });
    }

    function updateStatus() {
      dom.streamStatus.textContent = state.running ? '● Streaming' : '● Paused';
      dom.streamStatus.style.background = state.running ? 'rgba(34, 197, 94, 0.15)' : 'rgba(239, 68, 68, 0.15)';
      dom.streamStatus.style.color = state.running ? '#22c55e' : '#ef4444';
      dom.toggleStreamBtn.textContent = state.running ? 'Pause Stream' : 'Resume Stream';
    }

    function updateUI() {
      const visible = getVisibleData();
      updateMetrics(visible);
      updateLog();
      drawChart();
      updateStatus();
    }

    function escapeHtml(str) {
      return str
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    dom.dataForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const value = Number(dom.valueInput.value);
      const category = dom.categoryInput.value;
      const note = dom.noteInput.value.trim();

      if (Number.isNaN(value) || value < 0) return;

      addDataPoint('manual', { value, category, note });
      dom.dataForm.reset();
      dom.valueInput.focus();
    });

    dom.toggleStreamBtn.addEventListener('click', () => {
      state.running = !state.running;
      updateStatus();
    });

    dom.clearDataBtn.addEventListener('click', () => {
      state.data = [];
      updateUI();
    });

    dom.filterSelect.addEventListener('change', (e) => {
      state.filter = e.target.value;
      updateUI();
    });

    function tick() {
      if (state.running) {
        addDataPoint('stream');
      }
    }

    // initial sample data
    for (let i = 0; i < 8; i++) {
      addDataPoint('seed', {
        value: Math.floor(20 + Math.random() * 70),
        category: state.categories[i % state.categories.length],
        note: `Seed point ${i + 1}`
      });
    }

    updateUI();
    setInterval(tick, 1000);
    window.addEventListener('resize', drawChart);
  </script>
</body>
</html>
```

