## 3) `app.js`

```javascript
const ctx = document.getElementById("liveChart").getContext("2d");

const currentValueEl = document.getElementById("currentValue");
const averageValueEl = document.getElementById("averageValue");
const totalPointsEl = document.getElementById("totalPoints");
const form = document.getElementById("dataForm");
const labelInput = document.getElementById("labelInput");
const valueInput = document.getElementById("valueInput");
const formMessage = document.getElementById("formMessage");
const pauseButton = document.getElementById("pauseButton");
const connectionStatus = document.getElementById("connectionStatus");

let isPaused = false;
let dataPoints = [12, 18, 15, 22, 19, 28];
let labels = ["T-5", "T-4", "T-3", "T-2", "T-1", "Now"];

const liveChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Metric",
        data: dataPoints,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 4,
        pointHoverRadius: 6,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: "#e2e8f0",
        },
      },
    },
    scales: {
      x: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(148, 163, 184, 0.15)" },
      },
      y: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(148, 163, 184, 0.15)" },
      },
    },
  },
});

function updateSummary() {
  const current = dataPoints[dataPoints.length - 1];
  const average = dataPoints.reduce((sum, value) => sum + value, 0) / dataPoints.length;

  currentValueEl.textContent = current.toFixed(1);
  averageValueEl.textContent = average.toFixed(1);
  totalPointsEl.textContent = dataPoints.length;
}

function pushDataPoint(label, value) {
  labels.push(label);
  dataPoints.push(value);

  if (labels.length > 12) {
    labels.shift();
    dataPoints.shift();
  }

  liveChart.update();
  updateSummary();
}

function simulateRealTimeUpdate() {
  if (isPaused) return;

  const lastValue = dataPoints[dataPoints.length - 1];
  const nextValue = Math.max(0, lastValue + (Math.random() * 8 - 4));
  const timeLabel = new Date().toLocaleTimeString();

  pushDataPoint(timeLabel, Number(nextValue.toFixed(1)));
}

form.addEventListener("submit", (e) => {
  e.preventDefault();

  const label = labelInput.value.trim();
  const value = Number(valueInput.value);

  if (!label || Number.isNaN(value)) {
    formMessage.textContent = "Please enter a valid label and numeric value.";
    formMessage.style.color = "#fca5a5";
    return;
  }

  pushDataPoint(label, value);
  formMessage.textContent = `Added "${label}" with value ${value}.`;
  formMessage.style.color = "#86efac";

  form.reset();
  labelInput.focus();
});

pauseButton.addEventListener("click", () => {
  isPaused = !isPaused;
  pauseButton.textContent = isPaused ? "Resume" : "Pause";
  connectionStatus.textContent = isPaused ? "Paused" : "Live";
  connectionStatus.style.background = isPaused ? "#f59e0b" : "#16a34a";
});

updateSummary();
setInterval(simulateRealTimeUpdate, 1000);
```

