```jsx
import React, { useEffect, useMemo, useState } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  BarChart,
  Bar,
  Legend,
} from "recharts";

const COLORS = ["#2563eb", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6"];

function generatePoint(prevValue) {
  const delta = Math.floor(Math.random() * 21) - 10;
  const next = Math.max(0, prevValue + delta);
  return next;
}

export default function App() {
  const [metrics, setMetrics] = useState([
    { time: "10:00", value: 40 },
    { time: "10:01", value: 45 },
    { time: "10:02", value: 43 },
    { time: "10:03", value: 50 },
    { time: "10:04", value: 48 },
  ]);

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    threshold: "",
    notify: true,
    category: "Sales",
  });

  const [submitted, setSubmitted] = useState(null);
  const [status, setStatus] = useState("Live");

  // Simulated real-time updates
  useEffect(() => {
    const interval = setInterval(() => {
      setMetrics((prev) => {
        const last = prev[prev.length - 1]?.value ?? 50;
        const nextValue = generatePoint(last);
        const now = new Date();
        const time = now.toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
        });

        const updated = [...prev, { time, value: nextValue }];
        return updated.slice(-12);
      });
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  const pieData = useMemo(
    () => [
      { name: "Sales", value: 35 },
      { name: "Marketing", value: 25 },
      { name: "Support", value: 20 },
      { name: "Ops", value: 20 },
    ],
    []
  );

  const barData = useMemo(
    () => [
      { name: "Mon", users: 120 },
      { name: "Tue", users: 165 },
      { name: "Wed", users: 140 },
      { name: "Thu", users: 180 },
      { name: "Fri", users: 210 },
    ],
    []
  );

  const latestValue = metrics[metrics.length - 1]?.value ?? 0;

  const handleChange = (e) => {
    const { name, type, checked, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted({
      ...formData,
      threshold: Number(formData.threshold),
      timestamp: new Date().toLocaleString(),
    });
    setStatus("Settings saved");
  };

  return (
    <div className="dashboard">
      <header className="topbar">
        <div>
          <h1>Real-Time Dashboard</h1>
          <p>Interactive browser-based analytics and form handling</p>
        </div>
        <div className="status-pill">{status}</div>
      </header>

      <section className="kpis">
        <div className="card kpi">
          <span>Current Metric</span>
          <strong>{latestValue}</strong>
        </div>
        <div className="card kpi">
          <span>Data Points</span>
          <strong>{metrics.length}</strong>
        </div>
        <div className="card kpi">
          <span>Live Mode</span>
          <strong>{status === "Live" ? "On" : "Updating"}</strong>
        </div>
      </section>

      <section className="grid">
        <div className="card chart-card chart-wide">
          <div className="card-header">
            <h2>Live Line Chart</h2>
            <span>Updates every 2 seconds</span>
          </div>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={metrics}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="time" />
              <YAxis />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="value"
                stroke="#2563eb"
                strokeWidth={3}
                dot={false}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>

        <div className="card chart-card">
          <div className="card-header">
            <h2>Department Split</h2>
          </div>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={pieData}
                dataKey="value"
                nameKey="name"
                outerRadius={100}
                label
              >
                {pieData.map((entry, index) => (
                  <Cell key={entry.name} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="card chart-card">
          <div className="card-header">
            <h2>Weekly Users</h2>
          </div>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={barData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="users" fill="#10b981" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="card form-card">
          <div className="card-header">
            <h2>Dashboard Settings</h2>
            <span>Form handling demo</span>
          </div>

          <form onSubmit={handleSubmit} className="form">
            <label>
              Name
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                placeholder="Enter your name"
                required
              />
            </label>

            <label>
              Email
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="Enter your email"
                required
              />
            </label>

            <label>
              Threshold
              <input
                type="number"
                name="threshold"
                value={formData.threshold}
                onChange={handleChange}
                placeholder="e.g. 75"
                min="0"
                max="100"
                required
              />
            </label>

            <label>
              Category
              <select name="category" value={formData.category} onChange={handleChange}>
                <option>Sales</option>
                <option>Marketing</option>
                <option>Support</option>
                <option>Operations</option>
              </select>
            </label>

            <label className="checkbox">
              <input
                type="checkbox"
                name="notify"
                checked={formData.notify}
                onChange={handleChange}
              />
              Enable notifications
            </label>

            <button type="submit">Save Settings</button>
          </form>

          {submitted && (
            <div className="submitted">
              <h3>Last Submission</h3>
              <pre>{JSON.stringify(submitted, null, 2)}</pre>
            </div>
          )}
        </div>
      </section>
    </div>
  );
}
