    }

    label {
      display: block;
      margin-bottom: 6px;
      font-weight: bold;
    }

    form {
      display: grid;
      gap: 10px;
    }

    .metric-list {
      margin-top: 12px;
      font-size: 14px;
      line-height: 1.6;
    }

    canvas {
      width: 100%;
      height: 280px;
      background: #fff;
      border: 1px solid #e5e7eb;
      border-radius: 8px;
    }

    .status {
      margin-top: 10px;
      font-size: 14px;
      color: #555;
    }

    @media (max-width: 800px) {
      .grid {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <div class="app">
    <h1>Real-Time Dashboard</h1>
    <p>Live-updating chart + form input, built with plain JavaScript.</p>

    <div class="controls">
      <button id="toggleBtn">Pause</button>
      <button id="resetBtn" class="secondary">Reset</button>
    </div>

    <div class="grid">
      <div class="card">
        <h2>Live Chart</h2>
        <canvas id="chart" width="900" height="280"></canvas>
        <div class="status" id="status">Streaming data...</div>
      </div>

      <div class="card">
        <h2>Add Data Point</h2>
        <form id="dataForm">
          <div>
            <label for="valueInput">Value</label>
            <input id="valueInput" type="number" step="0.1" placeholder="Enter a number" required />
          </div>
          <button type="submit">Add Point</button>
        </form>

        <div class="metric-list" id="metrics">
          <strong>Latest value:</strong> <span id="latestValue">--</span><br />
          <strong>Total points:</strong> <span id="pointCount">0</span>
        </div>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");
    const toggleBtn = document.getElementById("toggleBtn");
    const resetBtn = document.getElementById("resetBtn");
    const form = document.getElementById("dataForm");
    const valueInput = document.getElementById("valueInput");
    const latestValue = document.getElementById("latestValue");
    const pointCount = document.getElementById("pointCount");
    const status = document.getElementById("status");

    let data = [];
    let running = true;
    const maxPoints = 30;

    function randomValue() {
      return Math.round((Math.random() * 100) * 10) / 10;
    }

    function addPoint(value) {
      data.push(value);
      if (data.length > maxPoints) data.shift();
      latestValue.textContent = value;
      pointCount.textContent = data.length;
      drawChart();
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background grid
      ctx.strokeStyle = "#e5e7eb";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (canvas.height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const maxVal = Math.max(...data, 100);
      const minVal = Math.min(...data, 0);
      const padding = 30;
      const plotWidth = canvas.width - padding * 2;
      const plotHeight = canvas.height - padding * 2;

      ctx.strokeStyle = "#2563eb";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((val, i) => {
        const x = padding + (i / (maxPoints - 1)) * plotWidth;
        const y = padding + (1 - (val - minVal) / (maxVal - minVal || 1)) * plotHeight;

        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#dc2626";
      data.forEach((val, i) => {
        const x = padding + (i / (maxPoints - 1)) * plotWidth;
        const y = padding + (1 - (val - minVal) / (maxVal - minVal || 1)) * plotHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function resetDashboard() {
      data = [];
      latestValue.textContent = "--";
      pointCount.textContent = "0";
      status.textContent = running ? "Streaming data..." : "Paused.";
      drawChart();
    }

    toggleBtn.addEventListener("click", () => {
      running = !running;
      toggleBtn.textContent = running ? "Pause" : "Resume";
      status.textContent = running ? "Streaming data..." : "Paused.";
    });

    resetBtn.addEventListener("click", resetDashboard);

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const value = parseFloat(valueInput.value);
      if (!Number.isNaN(value)) {
        addPoint(value);
        valueInput.value = "";
        valueInput.focus();
      }
    });

    // Simulated real-time updates
    setInterval(() => {
      if (running) {
        addPoint(randomValue());
      }
    }, 1000);

    drawChart();
  </script>
</body>
</html>
```

