      <div class="metrics">
        <div class="metric">
          <label>Current Value</label>
          <strong id="currentValue">0</strong>
        </div>
        <div class="metric">
          <label>Average</label>
          <strong id="averageValue">0</strong>
        </div>
        <div class="metric">
          <label>Status</label>
          <strong id="statusValue">Stable</strong>
        </div>
      </div>

      <canvas id="chart" width="900" height="280"></canvas>
    </section>

    <aside class="card">
      <h2 style="margin-top:0;">Submit Data</h2>
      <form id="dataForm">
        <input type="text" id="name" placeholder="Enter label" required />
        <input type="number" id="value" placeholder="Enter value" required />
        <select id="type">
          <option value="info">Info</option>
          <option value="warning">Warning</option>
          <option value="critical">Critical</option>
        </select>
        <button type="submit">Add Entry</button>
      </form>

      <ul class="list" id="entries"></ul>
    </aside>
  </main>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const statusValueEl = document.getElementById("statusValue");
    const entriesEl = document.getElementById("entries");

    const dataPoints = Array.from({ length: 20 }, () => Math.floor(Math.random() * 100));
    const entries = [];

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const max = 100;
      const pad = 30;
      const w = canvas.width - pad * 2;
      const h = canvas.height - pad * 2;

      // background grid
      ctx.strokeStyle = "#1f2937";
      for (let i = 0; i <= 5; i++) {
        const y = pad + (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(pad, y);
        ctx.lineTo(canvas.width - pad, y);
        ctx.stroke();
      }

      // line chart
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      dataPoints.forEach((v, i) => {
        const x = pad + (w / (dataPoints.length - 1)) * i;
        const y = pad + h - (v / max) * h;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // points
      ctx.fillStyle = "#e5e7eb";
      dataPoints.forEach((v, i) => {
        const x = pad + (w / (dataPoints.length - 1)) * i;
        const y = pad + h - (v / max) * h;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });

      const current = dataPoints[dataPoints.length - 1];
      const avg = Math.round(dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length);

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      statusValueEl.textContent = current > 70 ? "High" : current < 30 ? "Low" : "Stable";
      statusValueEl.className =
        current > 70 ? "status-bad" : current < 30 ? "status-good" : "";
    }

    function updateRealTimeData() {
      dataPoints.push(Math.floor(Math.random() * 100));
      dataPoints.shift();
      drawChart();
    }

    function renderEntries() {
      entriesEl.innerHTML = entries.map(entry => `
        <li>
          <span><strong>${entry.name}</strong> — ${entry.value}</span>
          <span>${entry.type}</span>
        </li>
      `).join("");
    }

    document.getElementById("dataForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const value = Number(document.getElementById("value").value);
      const type = document.getElementById("type").value;

      entries.unshift({ name, value, type });
      if (entries.length > 5) entries.pop();

      renderEntries();
      e.target.reset();

      // also feed submitted value into real-time chart
      dataPoints.push(Math.max(0, Math.min(100, value)));
      dataPoints.shift();
      drawChart();
    });

    drawChart();
    renderEntries();
    setInterval(updateRealTimeData, 2000);
  </script>
</body>
</html>
