    const eventLogEl = document.getElementById("eventLog");
    const toggleBtn = document.getElementById("toggleBtn");
    const statusText = document.getElementById("statusText");

    const form = document.getElementById("dataForm");
    const labelInput = document.getElementById("labelInput");
    const valueInput = document.getElementById("valueInput");

    let running = true;
    let data = [];
    let labels = [];
    let updates = 0;

    function log(message) {
      const entry = document.createElement("div");
      entry.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLogEl.prepend(entry);
    }

    function updateMetrics(value) {
      currentValueEl.textContent = value.toFixed(2);
      const avg = data.reduce((a, b) => a + b, 0) / data.length;
      averageValueEl.textContent = data.length ? avg.toFixed(2) : "0";
      updateCountEl.textContent = updates;
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background grid
      ctx.strokeStyle = "#1f2937";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (canvas.height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const max = Math.max(...data);
      const min = Math.min(...data);
      const range = max - min || 1;

      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((val, index) => {
        const x = (canvas.width / (data.length - 1)) * index;
        const y = canvas.height - ((val - min) / range) * (canvas.height - 20) - 10;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // نقاط
      ctx.fillStyle = "#22c55e";
      data.forEach((val, index) => {
        const x = (canvas.width / (data.length - 1)) * index;
        const y = canvas.height - ((val - min) / range) * (canvas.height - 20) - 10;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function addDataPoint(label, value) {
      labels.push(label);
      data.push(value);

      if (data.length > 20) {
        data.shift();
        labels.shift();
      }

      updates++;
      updateMetrics(value);
      drawChart();
      log(`Added ${label}: ${value}`);
    }

    function randomUpdate() {
      const value = Math.random() * 100;
      addDataPoint("Auto", value);
    }

    toggleBtn.addEventListener("click", () => {
      running = !running;
      toggleBtn.textContent = running ? "Pause" : "Resume";
      statusText.textContent = running ? "Live" : "Paused";
      statusText.style.color = running ? "#22c55e" : "#ef4444";
      log(running ? "Streaming resumed" : "Streaming paused");
    });

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const label = labelInput.value.trim();
      const value = parseFloat(valueInput.value);

      if (!label || Number.isNaN(value)) return;

      addDataPoint(label, value);

      labelInput.value = "";
      valueInput.value = "";
    });

    // Initial data
    for (let i = 0; i < 5; i++) {
      addDataPoint(`Init ${i + 1}`, Math.random() * 100);
    }

    setInterval(() => {
      if (running) randomUpdate();
    }, 1000);

    drawChart();
  </script>
</body>
</html>
```

