      background: #2563eb;
      border: none;
      color: white;
      cursor: pointer;
      border-radius: 6px;
    }

    button:hover {
      background: #1d4ed8;
    }

    table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 1rem;
    }

    th, td {
      padding: 0.75rem;
      border-bottom: 1px solid #e5e7eb;
      text-align: left;
    }

    @media (max-width: 800px) {
      main {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Interactive Real-Time Dashboard</h1>
  </header>

  <main>
    <section class="card">
      <h2>Live Data Chart</h2>
      <canvas id="liveChart" height="140"></canvas>
    </section>

    <section class="card">
      <h2>Add Data Point</h2>
      <form id="dataForm">
        <input type="text" id="label" placeholder="Label (e.g. Task A)" required />
        <input type="number" id="value" placeholder="Value (e.g. 42)" required />
        <button type="submit">Add</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>Label</th>
            <th>Value</th>
          </tr>
        </thead>
        <tbody id="dataTable"></tbody>
      </table>
    </section>
  </main>

  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');
    const labels = ['A', 'B', 'C', 'D', 'E'];
    const values = [12, 19, 8, 15, 10];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [{
          label: 'Live Metric',
          data: values,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.15)',
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    const tableBody = document.getElementById('dataTable');
    const dataForm = document.getElementById('dataForm');
    const labelInput = document.getElementById('label');
    const valueInput = document.getElementById('value');

    function renderTable() {
      tableBody.innerHTML = '';
      chart.data.labels.forEach((label, index) => {
        const row = document.createElement('tr');
        row.innerHTML = `<td>${label}</td><td>${chart.data.datasets[0].data[index]}</td>`;
        tableBody.appendChild(row);
      });
      chart.update();
    }

    dataForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const label = labelInput.value.trim();
      const value = Number(valueInput.value);

      if (!label || Number.isNaN(value)) return;

      chart.data.labels.push(label);
      chart.data.datasets[0].data.push(value);

      labelInput.value = '';
      valueInput.value = '';
      renderTable();
    });

    // Simulated real-time updates
    setInterval(() => {
      const newValue = Math.floor(Math.random() * 30) + 5;
      const newLabel = `T${chart.data.labels.length + 1}`;

      chart.data.labels.push(newLabel);
      chart.data.datasets[0].data.push(newValue);

      // Keep only last 10 points
      if (chart.data.labels.length > 10) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }

      renderTable();
    }, 3000);

    renderTable();
  </script>
</body>
</html>
```

