        <input type="number" id="valueInput" placeholder="Value" min="0" required />
        <button type="submit">Add</button>
      </form>
    </section>

    <section class="card">
      <h2>Stats</h2>
      <div class="stats">
        <div class="stat">
          <div class="label">Total Points</div>
          <div class="value" id="totalPoints">0</div>
        </div>
        <div class="stat">
          <div class="label">Average Value</div>
          <div class="value" id="avgValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Latest Value</div>
          <div class="value" id="latestValue">0</div>
        </div>
      </div>
    </section>
