  <script>
    const chart = document.getElementById("chart");
    const dataForm = document.getElementById("dataForm");
    const labelInput = document.getElementById("labelInput");
    const valueInput = document.getElementById("valueInput");
    const toggleBtn = document.getElementById("toggleBtn");
    const resetBtn = document.getElementById("resetBtn");

    const totalPointsEl = document.getElementById("totalPoints");
    const avgValueEl = document.getElementById("avgValue");
    const latestValueEl = document.getElementById("latestValue");

    let data = [
      { label: "A", value: 30 },
      { label: "B", value: 60 },
      { label: "C", value: 45 }
    ];

    let liveUpdating = true;

    function renderChart() {
      chart.innerHTML = "";

      const maxValue = Math.max(...data.map(d => d.value), 100);

      data.forEach(item => {
        const bar = document.createElement("div");
        bar.className = "bar";
        bar.style.height = `${(item.value / maxValue) * 100}%`;
        bar.title = `${item.label}: ${item.value}`;
        bar.textContent = item.label;
        chart.appendChild(bar);
      });

      updateStats();
    }

    function updateStats() {
      const totalPoints = data.length;
      const avg = totalPoints
        ? (data.reduce((sum, item) => sum + item.value, 0) / totalPoints).toFixed(1)
        : 0;
      const latest = totalPoints ? data[data.length - 1].value : 0;

      totalPointsEl.textContent = totalPoints;
      avgValueEl.textContent = avg;
      latestValueEl.textContent = latest;
    }

    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = Number(valueInput.value);

      if (!label || Number.isNaN(value)) return;

      data.push({ label, value });
      renderChart();

      dataForm.reset();
      labelInput.focus();
    });

    toggleBtn.addEventListener("click", () => {
      liveUpdating = !liveUpdating;
      toggleBtn.textContent = liveUpdating ? "Pause Live Updates" : "Resume Live Updates";
    });

    resetBtn.addEventListener("click", () => {
      data = [];
      renderChart();
    });

    // Simulated real-time updates
    setInterval(() => {
      if (!liveUpdating) return;

      const value = Math.floor(Math.random() * 100) + 1;
      const label = `R${data.length + 1}`;
      data.push({ label, value });

      if (data.length > 12) data.shift(); // keep it minimal
      renderChart();
    }, 2000);

    renderChart();
  </script>
</body>
