          <div class="value" id="currentValue">0</div>
        </div>
        <div class="metric">
          <div class="label">Average</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="metric">
          <div class="label">Updates</div>
          <div class="value" id="updateCount">0</div>
        </div>
      </div>

      <canvas id="chart" width="900" height="280"></canvas>
      <div class="status">Real-time data updates every second.</div>
    </section>

