      <h2 style="margin-top:0;">Add Event</h2>
      <form id="eventForm">
        <input type="text" id="eventName" placeholder="Event name" required />
        <input type="number" id="eventValue" placeholder="Value" required />
        <button type="submit">Add to Feed</button>
      </form>

