  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const updateCountEl = document.getElementById("updateCount");
    const feedEl = document.getElementById("feed");

    const values = [];
    const maxPoints = 30;

    function randomValue() {
      return Math.floor(20 + Math.random() * 80);
    }

    function updateDashboard() {
      const value = randomValue();
      values.push(value);
      if (values.length > maxPoints) values.shift();

      const sum = values.reduce((a, b) => a + b, 0);
      const avg = sum / values.length;

      currentValueEl.textContent = value;
      averageValueEl.textContent = avg.toFixed(1);
      updateCountEl.textContent = values.length;

      drawChart();
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Axes
      ctx.strokeStyle = "#374151";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(40, 10);
      ctx.lineTo(40, 250);
      ctx.lineTo(880, 250);
      ctx.stroke();

      if (values.length < 2) return;

      // Line chart
      const paddingLeft = 40;
      const paddingBottom = 30;
      const chartWidth = 840;
      const chartHeight = 230;
      const maxVal = 100;

      ctx.strokeStyle = "#22c55e";
      ctx.lineWidth = 3;
      ctx.beginPath();

      values.forEach((v, i) => {
        const x = paddingLeft + (i / (maxPoints - 1)) * chartWidth;
        const y = 250 - (v / maxVal) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#3b82f6";
      values.forEach((v, i) => {
        const x = paddingLeft + (i / (maxPoints - 1)) * chartWidth;
        const y = 250 - (v / maxVal) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    document.getElementById("eventForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("eventName").value.trim();
      const value = document.getElementById("eventValue").value.trim();

      if (!name || value === "") return;

      const item = document.createElement("li");
      item.textContent = `${name}: ${value}`;
      feedEl.prepend(item);

      e.target.reset();
    });

    // Start real-time updates
    updateDashboard();
    setInterval(updateDashboard, 1000);
  </script>
