  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Mini Real-Time Dashboard</title>
  <style>
    :root {
      --bg: #0f172a;
      --panel: #111827;
      --text: #e5e7eb;
      --muted: #94a3b8;
      --accent: #38bdf8;
      --danger: #f87171;
      --ok: #4ade80;
      --border: #22304a;
    }

    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: linear-gradient(180deg, #0b1220, #111827);
      color: var(--text);
    }

    .dashboard {
      display: grid;
      grid-template-columns: 1fr;
      gap: 16px;
      padding: 16px;
      max-width: 1100px;
      margin: 0 auto;
    }

    .header, .panel {
      background: rgba(17, 24, 39, 0.95);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 16px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.2);
    }

    .header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
    }

    .header h1 {
      margin: 0;
      font-size: 1.2rem;
    }

    .status {
      color: var(--ok);
      font-size: 0.9rem;
    }

    .grid {
      display: grid;
      grid-template-columns: 1.5fr 1fr;
      gap: 16px;
    }

    canvas {
      width: 100%;
      height: 300px;
      background: #0b1220;
      border: 1px solid var(--border);
      border-radius: 10px;
      display: block;
    }

    .cards {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-bottom: 16px;
