      display: grid;
      gap: 10px;
    }

    input, button {
      padding: 10px 12px;
      border-radius: 8px;
      border: 1px solid var(--border);
      background: #0b1220;
      color: var(--text);
      font: inherit;
    }

    button {
      background: var(--accent);
      color: #00111a;
      font-weight: bold;
      cursor: pointer;
    }

