<body>
  <div class="dashboard">
    <div class="header">
      <h1>Real-Time Browser Dashboard</h1>
      <div class="status">● Live updating</div>
    </div>

    <div class="panel">
      <div class="cards">
        <div class="card">
          <div class="label">Current Value</div>
          <div class="value" id="currentValue">0</div>
        </div>
        <div class="card">
          <div class="label">Average</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="card">
          <div class="label">Entries</div>
          <div class="value" id="entryCount">0</div>
        </div>
      </div>
      <canvas id="chart" width="1000" height="300"></canvas>
      <p class="small">Real-time line chart updated every second.</p>
    </div>

    <div class="grid">
      <div class="panel">
        <h2 style="margin-top:0;">Add Data Point</h2>
        <form id="dataForm">
          <input type="number" id="dataInput" placeholder="Enter a number" required />
          <button type="submit">Add Point</button>
        </form>

        <h2>Submitted Values</h2>
        <ul id="valueList"></ul>
      </div>

      <div class="panel">
        <h2 style="margin-top:0;">Activity Feed</h2>
        <p class="small">System logs and form submissions will appear here.</p>
        <ul id="activityFeed"></ul>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const entryCountEl = document.getElementById("entryCount");
    const valueListEl = document.getElementById("valueList");
    const activityFeedEl = document.getElementById("activityFeed");

    const data = [];
    const maxPoints = 20;

    function addLog(message) {
      const li = document.createElement("li");
      li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      activityFeedEl.prepend(li);
    }

    function updateStats() {
      const current = data[data.length - 1] ?? 0;
      const avg = data.length
        ? (data.reduce((sum, val) => sum + val, 0) / data.length)
        : 0;

      currentValueEl.textContent = current.toFixed(2);
      averageValueEl.textContent = avg.toFixed(2);
      entryCountEl.textContent = data.length;
    }

    function renderList() {
      valueListEl.innerHTML = "";
      data.slice().reverse().forEach((val, index) => {
        const li = document.createElement("li");
        li.textContent = `Point ${data.length - index}: ${val.toFixed(2)}`;
        valueListEl.appendChild(li);
      });
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background grid
      ctx.strokeStyle = "#1f2937";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 10; i++) {
        const y = (canvas.height / 10) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const maxVal = Math.max(...data, 100);
      const minVal = Math.min(...data, 0);
      const padding = 30;
      const chartWidth = canvas.width - padding * 2;
      const chartHeight = canvas.height - padding * 2;

      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((val, i) => {
        const x = padding + (i / (maxPoints - 1)) * chartWidth;
        const y = padding + chartHeight - ((val - minVal) / (maxVal - minVal || 1)) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      ctx.fillStyle = "#38bdf8";
      data.forEach((val, i) => {
        const x = padding + (i / (maxPoints - 1)) * chartWidth;
        const y = padding + chartHeight - ((val - minVal) / (maxVal - minVal || 1)) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function addDataPoint(value) {
      data.push(value);
      if (data.length > maxPoints) data.shift();
      updateStats();
      renderList();
      drawChart();
      addLog(`Added data point: ${value.toFixed(2)}`);
    }

    // Form handling
    document.getElementById("dataForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const input = document.getElementById("dataInput");
      const value = parseFloat(input.value);

      if (!Number.isNaN(value)) {
        addDataPoint(value);
        input.value = "";
      }
    });

    // Real-time updates: simulate incoming data once per second
    setInterval(() => {
      const simulatedValue = Math.random() * 100;
      addDataPoint(simulatedValue);
    }, 1000);

    // Initial data
    for (let i = 0; i < 5; i++) {
      addDataPoint(Math.random() * 100);
    }
  </script>
</body>
</html>
```

### What it does
- Automatically generates a new random value every second
- Plots those values on a live line graph
- Lets users manually add values through a form
- Updates summary statistics and logs in real time

