<body>
  <div class="container">
    <h1>Real-Time Dashboard</h1>

    <div class="grid">
      <div class="card">
        <h3>Total Events</h3>
        <div class="value" id="totalEvents">0</div>
      </div>
      <div class="card">
        <h3>Latest Input</h3>
        <div class="value" id="latestInput">—</div>
      </div>
      <div class="card">
        <h3>Live Metric</h3>
        <div class="value" id="liveMetric">0</div>
      </div>
    </div>

    <div class="panel">
      <h2>Submit Data</h2>
      <form id="dataForm">
        <input type="text" id="nameInput" placeholder="Enter a label" required />
        <input type="number" id="valueInput" placeholder="Enter a value" required />
        <button type="submit">Add to Chart</button>
      </form>
      <div class="log" id="formLog">No submissions yet.</div>
    </div>

    <div class="panel">
      <h2>Real-Time Chart</h2>
      <canvas id="liveChart"></canvas>
    </div>
  </div>

  <script>
    const totalEventsEl = document.getElementById("totalEvents");
    const latestInputEl = document.getElementById("latestInput");
    const liveMetricEl = document.getElementById("liveMetric");
    const formLogEl = document.getElementById("formLog");
    const dataForm = document.getElementById("dataForm");
    const nameInput = document.getElementById("nameInput");
    const valueInput = document.getElementById("valueInput");
    const ctx = document.getElementById("liveChart").getContext("2d");

    let labels = ["A", "B", "C", "D", "E"];
    let data = [12, 19, 7, 15, 10];
    let totalEvents = 0;

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Live Value",
          data,
          borderColor: "#2563eb",
          backgroundColor: "rgba(37, 99, 235, 0.15)",
          tension: 0.3,
          fill: true,
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });

    function updateDashboard(metric) {
      liveMetricEl.textContent = metric;
      totalEventsEl.textContent = totalEvents;
    }

    // Handle form submission
    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const label = nameInput.value.trim();
      const value = Number(valueInput.value);

      if (!label || Number.isNaN(value)) return;

      labels.push(label);
      data.push(value);

      // keep only last 10 points
      if (labels.length > 10) {
        labels.shift();
        data.shift();
      }

      chart.update();

      totalEvents++;
      latestInputEl.textContent = `${label}: ${value}`;
      formLogEl.textContent = `Added "${label}" with value ${value}.`;
      updateDashboard(value);

      dataForm.reset();
      nameInput.focus();
    });

    // Simulated real-time updates
    setInterval(() => {
      const randomValue = Math.floor(Math.random() * 100);
      const timestamp = new Date().toLocaleTimeString().slice(0, 8);

      labels.push(timestamp);
      data.push(randomValue);

      if (labels.length > 10) {
        labels.shift();
        data.shift();
      }

      chart.update();

      totalEvents++;
      liveMetricEl.textContent = randomValue;
      totalEventsEl.textContent = totalEvents;
    }, 3000);
  </script>
</body>
