            <option value="normal">Normal</option>
            <option value="boost">Boost</option>
            <option value="eco">Eco</option>
          </select>
        </div>

        <div>
          <label for="threshold">Threshold</label>
          <input id="threshold" type="number" value="50" min="0" max="100" />
        </div>

        <button type="submit">Submit</button>
      </form>
      <div id="message"></div>
    </section>
  </main>

  <script>
    const ctx = document.getElementById('chart').getContext('2d');
    const labels = [];
    const data = [];

    const maxPoints = 20;
    let updateCount = 0;

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Value',
          data,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.15)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });

    function updateDashboard() {
      const value = Math.floor(Math.random() * 100);
      const time = new Date().toLocaleTimeString();

      labels.push(time);
      data.push(value);

      if (labels.length > maxPoints) {
        labels.shift();
        data.shift();
      }

      updateCount++;
      const avg = Math.round(data.reduce((a, b) => a + b, 0) / data.length);

      document.getElementById('currentValue').textContent = value;
      document.getElementById('averageValue').textContent = avg;
      document.getElementById('updateCount').textContent = updateCount;

      chart.update();
    }

    setInterval(updateDashboard, 1000);
    updateDashboard();

    document.getElementById('controlForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('name').value;
      const mode = document.getElementById('mode').value;
      const threshold = document.getElementById('threshold').value;

      document.getElementById('message').textContent =
        `Saved: ${name}, Mode: ${mode}, Threshold: ${threshold}`;
    });
  </script>
</body>
</html>
