          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });

    function render() {
      const filter = categoryFilter.value;
      selectedCategoryEl.textContent = filter === 'all' ? 'All' : filter;

      const filtered = filter === 'all'
        ? dataPoints
        : dataPoints.filter(p => p.category === filter);

      chart.data.labels = filtered.map(p => p.label);
      chart.data.datasets[0].data = filtered.map(p => p.value);
      chart.update();

      totalPointsEl.textContent = filtered.length;
      latestValueEl.textContent = filtered.length ? filtered[filtered.length - 1].value : 0;
    }

    dataForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const label = document.getElementById('labelInput').value.trim();
      const value = Number(document.getElementById('valueInput').value);
      const category = document.getElementById('categoryInput').value;

      dataPoints.push({ label, value, category });
      dataForm.reset();
      render();
    });

    categoryFilter.addEventListener('change', render);

    resetBtn.addEventListener('click', () => {
      dataPoints = [...initialData];
      categoryFilter.value = 'all';
      render();
    });

    function addRandomPoint() {
      const categories = ['Sales', 'Marketing', 'Support'];
      const category = categories[Math.floor(Math.random() * categories.length)];
      const value = Math.floor(Math.random() * 30) + 1;
      const label = `P${dataPoints.length + 1}`;

      dataPoints.push({ label, value, category });
      render();
    }

    render();
    setInterval(addRandomPoint, 2000);
  </script>
</body>
</html>
```

