## `content.js`

This script removes suspicious script elements and prevents some late-injected trackers from loading.

```js
(() => {
  "use strict";

  const TRACKER_PATTERNS = [
    /googletagmanager\.com/i,
    /google-analytics\.com/i,
    /analytics\.google\.com/i,
    /doubleclick\.net/i,
    /facebook\.net/i,
    /connect\.facebook\.net/i,
    /hotjar\.com/i,
    /segment\.com/i,
    /mixpanel\.com/i
  ];

  function isTrackerUrl(url) {
    return TRACKER_PATTERNS.some((re) => re.test(url));
  }

  function removeTrackingScripts(root = document) {
    const scripts = root.querySelectorAll("script[src], iframe[src], img[src], link[href]");
    for (const el of scripts) {
      const url = el.src || el.href || "";
      if (url && isTrackerUrl(url)) {
        el.remove();
      }
    }
  }

  // Remove existing tracking elements early
  removeTrackingScripts();

  // Watch for newly added elements
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (!(node instanceof Element)) continue;

        const tag = node.tagName.toUpperCase();
        const url = node.src || node.href || "";

        if (url && isTrackerUrl(url)) {
          node.remove();
          continue;
        }

        // If a container is inserted, scan inside it
        if (tag !== "SCRIPT" && tag !== "IFRAME" && tag !== "IMG" && tag !== "LINK") {
          removeTrackingScripts(node);
        }
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

