## `service_worker.js`

This script removes tracking parameters from navigations and can be extended for dynamic rules.

```javascript
const TRACKING_PARAMS = [
  "fbclid",
  "gclid",
  "msclkid",
  "igshid",
  "mc_cid",
  "mc_eid"
];

// Strip utm_* along with known params from URLs before final navigation.
chrome.webNavigation.onBeforeNavigate.addListener((details) => {
  if (details.frameId !== 0) return;

  try {
    const url = new URL(details.url);
    let changed = false;

    // Remove known tracking params
    for (const param of TRACKING_PARAMS) {
      if (url.searchParams.has(param)) {
        url.searchParams.delete(param);
        changed = true;
      }
    }

    // Remove all utm_* parameters
    for (const key of [...url.searchParams.keys()]) {
      if (key.toLowerCase().startsWith("utm_")) {
        url.searchParams.delete(key);
        changed = true;
      }
    }

    if (changed) {
      chrome.tabs.update(details.tabId, { url: url.toString() });
    }
  } catch (e) {
    // Ignore invalid URLs
  }
});
```

