## Important note
This example **defines rules**, but to fully enable/disable them at runtime, you should dynamically update DNR rules using `chrome.declarativeNetRequest.updateEnabledRulesets()` or `updateDynamicRules()`.

Here is a more complete `background.js` that actually toggles the ruleset:

```javascript
const DEFAULT_STATE = {
  enabled: true
};

async function applyRules(enabled) {
  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? ["tracker_rules"] : [],
    disableRulesetIds: enabled ? [] : ["tracker_rules"]
  });
}

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.local.get(DEFAULT_STATE);
  if (typeof data.enabled === "undefined") {
    await chrome.storage.local.set(DEFAULT_STATE);
  }
  await applyRules((await chrome.storage.local.get(DEFAULT_STATE)).enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const { enabled } = await chrome.storage.local.get(DEFAULT_STATE);
  await applyRules(enabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getState") {
    chrome.storage.local.get(DEFAULT_STATE).then(sendResponse);
    return true;
  }

  if (message.type === "setEnabled") {
    chrome.storage.local.set({ enabled: message.enabled }).then(async () => {
      await applyRules(message.enabled);
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

