## `background.js`

This service worker tracks the enabled/disabled state and block count.

```javascript
const STORAGE_KEYS = {
  enabled: "privacyShieldEnabled",
  blockedCount: "privacyShieldBlockedCount"
};

async function getState() {
  const result = await chrome.storage.local.get([STORAGE_KEYS.enabled, STORAGE_KEYS.blockedCount]);
  return {
    enabled: result[STORAGE_KEYS.enabled] ?? true,
    blockedCount: result[STORAGE_KEYS.blockedCount] ?? 0
  };
}

async function setEnabled(enabled) {
  await chrome.storage.local.set({ [STORAGE_KEYS.enabled]: enabled });

  if (!enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      disableRulesetIds: ["tracker_rules"]
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const state = await getState();
  await setEnabled(state.enabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "getState") {
    getState().then(sendResponse);
    return true;
  }

  if (message.type === "setEnabled") {
    setEnabled(message.enabled).then(() => sendResponse({ ok: true }));
    return true;
  }

  if (message.type === "incrementBlockedCount") {
    chrome.storage.local.get([STORAGE_KEYS.blockedCount], (result) => {
      const current = result[STORAGE_KEYS.blockedCount] ?? 0;
      chrome.storage.local.set({ [STORAGE_KEYS.blockedCount]: current + 1 }, () => {
        sendResponse({ ok: true, blockedCount: current + 1 });
      });
    });
    return true;
  }
});
```

