## `content.js`

This script runs early and removes some obvious tracking script tags from the page, plus prevents a few common trackers from loading if they appear dynamically.

```javascript
(() => {
  const TRACKER_PATTERNS = [
    "google-analytics.com",
    "googletagmanager.com",
    "doubleclick.net",
    "facebook.net",
    "hotjar.com",
    "mixpanel.com",
    "segment.com"
  ];

  function isTrackerUrl(url) {
    return TRACKER_PATTERNS.some(pattern => url.includes(pattern));
  }

  function removeTrackerScripts() {
    const scripts = document.querySelectorAll("script[src]");
    for (const script of scripts) {
      const src = script.src || "";
      if (isTrackerUrl(src)) {
        script.remove();
      }
    }
  }

  function interceptScriptInsertion() {
    const originalAppendChild = Element.prototype.appendChild;
    const originalInsertBefore = Element.prototype.insertBefore;

    Element.prototype.appendChild = function(node) {
      try {
        if (node && node.tagName === "SCRIPT") {
          const src = node.src || "";
          if (src && isTrackerUrl(src)) {
            return node;
          }
        }
      } catch (e) {}
      return originalAppendChild.call(this, node);
    };

    Element.prototype.insertBefore = function(node, refNode) {
      try {
        if (node && node.tagName === "SCRIPT") {
          const src = node.src || "";
          if (src && isTrackerUrl(src)) {
            return node;
          }
        }
      } catch (e) {}
      return originalInsertBefore.call(this, node, refNode);
    };
  }

  const observer = new MutationObserver(() => {
    removeTrackerScripts();
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });

  removeTrackerScripts();
  interceptScriptInsertion();
})();
```

