## `background.js`

This stores a simple enabled/disabled flag and updates the dynamic rules if needed.

```javascript
const STORAGE_KEY = "blockerEnabled";

chrome.runtime.onInstalled.addListener(async () => {
  const stored = await chrome.storage.sync.get([STORAGE_KEY]);
  if (stored[STORAGE_KEY] === undefined) {
    await chrome.storage.sync.set({ [STORAGE_KEY]: true });
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "getStatus") {
    chrome.storage.sync.get([STORAGE_KEY]).then((data) => {
      sendResponse({ enabled: data[STORAGE_KEY] !== false });
    });
    return true;
  }

  if (message?.type === "setStatus") {
    const enabled = !!message.enabled;
    chrome.storage.sync.set({ [STORAGE_KEY]: enabled }).then(() => {
      sendResponse({ ok: true, enabled });
    });
    return true;
  }
});
```

