## `background.js`

This script removes common tracking parameters like `utm_*`, `fbclid`, and `gclid` when navigation happens.

```javascript
const TRACKING_PARAMS = [
  "fbclid",
  "gclid",
  "dclid",
  "msclkid",
  "igshid",
  "mc_cid",
  "mc_eid"
];

function isTrackingParam(key) {
  return (
    TRACKING_PARAMS.includes(key) ||
    key.toLowerCase().startsWith("utm_")
  );
}

function cleanUrl(urlString) {
  try {
    const url = new URL(urlString);
    let changed = false;

    for (const key of [...url.searchParams.keys()]) {
      if (isTrackingParam(key)) {
        url.searchParams.delete(key);
        changed = true;
      }
    }

    return changed ? url.toString() : null;
  } catch {
    return null;
  }
}

chrome.webNavigation.onBeforeNavigate.addListener((details) => {
  if (details.frameId !== 0) return;

  const cleaned = cleanUrl(details.url);
  if (!cleaned || cleaned === details.url) return;

  chrome.tabs.update(details.tabId, { url: cleaned });
});
```

---

## How it works

- **`declarativeNetRequest`** blocks requests to known tracking domains.
- **`webNavigation.onBeforeNavigate`** detects navigations and strips tracking parameters from the URL.
- This helps reduce tracking without needing invasive page access.

