## `background.js`

This script manages the enabled/disabled state and updates the extension icon/title.

```js
const ENABLED_KEY = "privacy_blocker_enabled";

async function getEnabled() {
  const result = await chrome.storage.sync.get({ [ENABLED_KEY]: true });
  return result[ENABLED_KEY];
}

async function setEnabled(enabled) {
  await chrome.storage.sync.set({ [ENABLED_KEY]: enabled });
  await updateActionState(enabled);
}

async function updateActionState(enabled) {
  if (enabled) {
    chrome.action.setBadgeText({ text: "ON" });
    chrome.action.setBadgeBackgroundColor({ color: "#2e7d32" });
    chrome.action.setTitle({ title: "Privacy Blocker: Enabled" });
  } else {
    chrome.action.setBadgeText({ text: "OFF" });
    chrome.action.setBadgeBackgroundColor({ color: "#666666" });
    chrome.action.setTitle({ title: "Privacy Blocker: Disabled" });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const enabled = await getEnabled();
  await updateActionState(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const enabled = await getEnabled();
  await updateActionState(enabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_ENABLED") {
    getEnabled().then((enabled) => sendResponse({ enabled }));
    return true;
  }

  if (message?.type === "SET_ENABLED") {
    setEnabled(Boolean(message.enabled)).then(() => sendResponse({ ok: true }));
    return true;
  }
});
```

