```js
const toggleBtn = document.getElementById("toggle");
const statusEl = document.getElementById("status");

function render(enabled) {
  toggleBtn.textContent = enabled ? "Disable" : "Enable";
  toggleBtn.className = enabled ? "enabled" : "disabled";
  statusEl.textContent = enabled
    ? "Tracking protection is currently enabled."
    : "Tracking protection is currently disabled.";
}

async function getEnabled() {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage({ type: "GET_ENABLED" }, (response) => {
      resolve(Boolean(response?.enabled));
    });
  });
}

async function setEnabled(enabled) {
  return new Promise((resolve) => {
    chrome.runtime.sendMessage(
      { type: "SET_ENABLED", enabled },
      () => resolve()
    );
  });
}

toggleBtn.addEventListener("click", async () => {
  const enabled = await getEnabled();
  await setEnabled(!enabled);
  render(!enabled);
});

(async () => {
  const enabled = await getEnabled();
  render(enabled);
})();
```

