## `content.js`

This script removes common tracking-related iframe/script elements and prevents some inline tracker injections.

```js
(() => {
  const removeTrackerElements = () => {
    const selectors = [
      'script[src*="googletagmanager"]',
      'script[src*="google-analytics"]',
      'script[src*="doubleclick"]',
      'iframe[src*="doubleclick"]',
      'iframe[src*="facebook"]',
      'img[src*="google-analytics"]',
      'img[src*="doubleclick"]'
    ];

    document.querySelectorAll(selectors.join(",")).forEach((el) => {
      el.remove();
    });
  };

  // Run immediately if DOM is available
  if (document.documentElement) {
    removeTrackerElements();
  }

  // Observe DOM changes for late-injected trackers
  const observer = new MutationObserver(() => {
    removeTrackerElements();
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
```

