## 5) `popup.js`

```js
const statusEl = document.getElementById("status");
const toggleBtn = document.getElementById("toggleBtn");

function render(enabled) {
  statusEl.textContent = enabled ? "Blocking is ON" : "Blocking is OFF";
  toggleBtn.textContent = enabled ? "Disable Blocking" : "Enable Blocking";
  toggleBtn.className = enabled ? "off" : "on";
}

chrome.storage.local.get(["blockingEnabled"], (result) => {
  const enabled = result.blockingEnabled !== false;
  render(enabled);
});

toggleBtn.addEventListener("click", async () => {
  const result = await chrome.storage.local.get(["blockingEnabled"]);
  const enabled = result.blockingEnabled !== false;
  const next = !enabled;

  await chrome.storage.local.set({ blockingEnabled: next });

  // Enable/disable the static ruleset
  if (next) {
    chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["default_rules"],
      disableRulesetIds: []
    });
  } else {
    chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["default_rules"]
    });
  }

  render(next);
});
```

