## 6) Important note about toggling

If you want the popup toggle to work reliably, update `background.js` to sync ruleset state on install/startup too.

Replace `background.js` with:

```js
async function syncBlockingState() {
  const result = await chrome.storage.local.get(["blockingEnabled"]);
  const enabled = result.blockingEnabled !== false;

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? ["default_rules"] : [],
    disableRulesetIds: enabled ? [] : ["default_rules"]
  });
}

chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.local.get(["blockingEnabled"], (result) => {
    if (typeof result.blockingEnabled === "undefined") {
      chrome.storage.local.set({ blockingEnabled: true }, () => {
        syncBlockingState();
      });
    } else {
      syncBlockingState();
    }
  });
});

chrome.runtime.onStartup.addListener(() => {
  syncBlockingState();
});
```

