This registers dynamic rules for known tracking endpoints and can be expanded with user-defined rules.

```js
const DEFAULT_TRACKING_DOMAINS = [
  "google-analytics.com",
  "www.google-analytics.com",
  "googletagmanager.com",
  "www.googletagmanager.com",
  "doubleclick.net",
  "www.doubleclick.net",
  "facebook.net",
  "connect.facebook.net",
  "scorecardresearch.com",
  "adservice.google.com",
  "adsystem.com",
  "cdn.taboola.com",
  "static.hotjar.com",
  "script.hotjar.com",
  "clarity.ms",
  "bat.bing.com",
  "mixpanel.com",
  "api.mixpanel.com",
  "segment.com",
  "cdn.segment.com",
  "rncdn1.com",
  "fullstory.com",
  "js-agent.newrelic.com"
];

function buildRules() {
  return DEFAULT_TRACKING_DOMAINS.map((domain, index) => ({
    id: index + 1,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: domain,
      resourceTypes: [
        "script",
        "image",
        "xmlhttprequest",
        "sub_frame",
        "font",
        "stylesheet",
        "ping",
        "media",
        "websocket",
        "other"
      ]
    }
  }));
}

async function updateRules() {
  try {
    const rules = buildRules();

    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: rules.map(r => r.id),
      addRules: rules
    });

    console.log("Tracker Blocker: rules updated");
  } catch (err) {
    console.error("Tracker Blocker: failed to update rules", err);
  }
}

chrome.runtime.onInstalled.addListener(() => {
  updateRules();
});

chrome.runtime.onStartup.addListener(() => {
  updateRules();
});
```

