## `content.js`

This attempts to stop common inline tracker injections and removes suspicious script tags early.

```js
(() => {
  const TRACKER_PATTERNS = [
    /google-analytics/i,
    /googletagmanager/i,
    /doubleclick/i,
    /facebook\.net/i,
    /scorecardresearch/i,
    /hotjar/i,
    /clarity\.ms/i,
    /mixpanel/i,
    /segment/i,
    /fullstory/i,
    /newrelic/i,
    /taboola/i,
    /outbrain/i
  ];

  function looksLikeTracker(src = "") {
    return TRACKER_PATTERNS.some((re) => re.test(src));
  }

  function removeBadScripts(root = document) {
    const scripts = root.querySelectorAll("script[src], script");
    for (const script of scripts) {
      const src = script.src || script.textContent || "";
      if (looksLikeTracker(src)) {
        script.remove();
      }
    }
  }

  // Remove existing scripts ASAP
  removeBadScripts();

  // Watch for scripts added dynamically
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (!node || node.nodeType !== Node.ELEMENT_NODE) continue;

        if (node.tagName === "SCRIPT") {
          const src = node.src || node.textContent || "";
          if (looksLikeTracker(src)) {
            node.remove();
            continue;
          }
        }

        removeBadScripts(node);
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });

  // Prevent common analytics globals from initializing
  try {
    Object.defineProperty(window, "ga", {
      configurable: true,
      get() {
        return undefined;
      },
      set() {}
    });
  } catch {}

  try {
    Object.defineProperty(window, "dataLayer", {
      configurable: true,
      get() {
        return [];
      },
      set() {}
    });
  } catch {}

  // Block fetch/XMLHttpRequest to some tracker endpoints by monkey-patching
  const blockedSubstrings = [
    "google-analytics.com",
    "googletagmanager.com",
    "doubleclick.net",
    "facebook.net",
    "mixpanel.com",
    "segment.com",
    "hotjar.com",
    "clarity.ms",
    "fullstory.com"
  ];

  const originalFetch = window.fetch;
  if (typeof originalFetch === "function") {
    window.fetch = function(resource, init) {
      const url = typeof resource === "string" ? resource : resource?.url || "";
      if (blockedSubstrings.some((s) => url.includes(s))) {
        return Promise.reject(new Error("Blocked by Privacy Tracker Blocker"));
      }
      return originalFetch.apply(this, arguments);
    };
  }

  const originalXHROpen = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function(method, url) {
    if (blockedSubstrings.some((s) => String(url).includes(s))) {
      throw new Error("Blocked by Privacy Tracker Blocker");
    }
    return originalXHROpen.apply(this, arguments);
  };
})();
```

