## `content.js`

This removes well-known tracking elements and watches for dynamically injected trackers.

```js
(() => {
  const TRACKER_SELECTORS = [
    'script[src*="google-analytics.com"]',
    'script[src*="googletagmanager.com"]',
    'script[src*="doubleclick.net"]',
    'script[src*="facebook.net"]',
    'iframe[src*="doubleclick.net"]',
    'iframe[src*="googletagmanager.com"]',
    'img[src*="google-analytics.com"]',
    'img[src*="doubleclick.net"]',
    '[data-analytics]',
    '[data-tracking]'
  ];

  function removeTrackers(root = document) {
    TRACKER_SELECTORS.forEach((selector) => {
      root.querySelectorAll(selector).forEach((el) => {
        el.remove();
      });
    });
  }

  // Remove trackers on initial load
  removeTrackers();

  // Watch for dynamically inserted trackers
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (!(node instanceof Element)) continue;

        if (TRACKER_SELECTORS.some((selector) => node.matches?.(selector))) {
          node.remove();
          continue;
        }

        removeTrackers(node);
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });

  // Optional: stop common tracking beacon APIs
  const originalSendBeacon = navigator.sendBeacon?.bind(navigator);
  if (originalSendBeacon) {
    navigator.sendBeacon = function (url, data) {
      if (
        typeof url === "string" &&
        /google-analytics\.com|doubleclick\.net|facebook\.com|hotjar\.com/i.test(url)
      ) {
        return true; // Pretend it succeeded, but do not send
      }
      return originalSendBeacon(url, data);
    };
  }
})();
```

