## 3) `background.js`

This handles enable/disable state and can later be expanded to dynamically manage rules.

```js
const DEFAULT_ENABLED = true;

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.local.get({ enabled: DEFAULT_ENABLED });
  if (typeof data.enabled !== "boolean") {
    await chrome.storage.local.set({ enabled: DEFAULT_ENABLED });
  }
});

async function updateBlockingState(enabled) {
  // For a more advanced version, you can enable/disable rules here dynamically.
  // This initial version keeps rules loaded and uses a lightweight toggle state.
  await chrome.storage.local.set({ enabled });
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "SET_ENABLED") {
    updateBlockingState(Boolean(message.enabled)).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }

  if (message?.type === "GET_ENABLED") {
    chrome.storage.local.get({ enabled: DEFAULT_ENABLED }).then((result) => {
      sendResponse({ enabled: result.enabled });
    });
    return true;
  }
});
```

