## Important note: current toggle doesn’t yet actually enable/disable rules

Right now, the popup only stores a preference. To truly toggle blocking on/off, you should dynamically enable/disable the DNR ruleset from the service worker.

Here’s the improved `background.js` that actually controls the rules:

### Replace `background.js` with this

```js
const RULESET_ID = "default_rules";

async function setBlockingEnabled(enabled) {
  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });

  await chrome.storage.sync.set({ enabled });
}

chrome.runtime.onInstalled.addListener(async () => {
  const defaults = { enabled: true };
  const { enabled } = await chrome.storage.sync.get(defaults);

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATUS") {
    chrome.storage.sync.get({ enabled: true }).then((result) => {
      sendResponse({ enabled: result.enabled });
    });
    return true;
  }

  if (message?.type === "SET_STATUS") {
    setBlockingEnabled(!!message.enabled).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
