## 3) `background.js`

This service worker loads blocking rules and allows user settings such as enabling/disabling the blocker.

```js
const STORAGE_KEYS = {
  enabled: "privacy_guard_enabled"
};

async function loadRules() {
  const response = await fetch(chrome.runtime.getURL("rules/tracker-rules.json"));
  const rules = await response.json();
  return rules;
}

async function applyRules() {
  const enabled = await getEnabledState();

  if (!enabled) {
    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: [1, 2, 3, 4, 5]
    });
    return;
  }

  const rules = await loadRules();
  const ruleIds = rules.map(r => r.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: ruleIds,
    addRules: rules
  });
}

async function getEnabledState() {
  const result = await chrome.storage.sync.get([STORAGE_KEYS.enabled]);
  return result[STORAGE_KEYS.enabled] ?? true;
}

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.sync.get([STORAGE_KEYS.enabled]);
  if (current[STORAGE_KEYS.enabled] === undefined) {
    await chrome.storage.sync.set({ [STORAGE_KEYS.enabled]: true });
  }
  await applyRules();
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes[STORAGE_KEYS.enabled]) {
    await applyRules();
  }
});

// Optional: show basic blocked request telemetry in console for debugging
chrome.declarativeNetRequest.onRuleMatchedDebug?.addListener((info) => {
  console.debug("Blocked or matched rule:", info);
});
```

