const STORAGE_KEY = "privacy_guard_enabled";

async function loadState() {
  const result = await chrome.storage.sync.get([STORAGE_KEY]);
  const enabled = result[STORAGE_KEY] ?? true;

  const toggle = document.getElementById("enabledToggle");
  const statusText = document.getElementById("statusText");
  const indicator = document.getElementById("statusIndicator");

  toggle.checked = enabled;
  statusText.textContent = enabled ? "Blocking enabled" : "Blocking disabled";
  indicator.className = `indicator ${enabled ? "on" : "off"}`;
}

async function setEnabled(enabled) {
  await chrome.storage.sync.set({ [STORAGE_KEY]: enabled });
  loadState();
}

document.addEventListener("DOMContentLoaded", async () => {
  await loadState();

  document.getElementById("enabledToggle").addEventListener("change", (e) => {
    setEnabled(e.target.checked);
  });

  document.getElementById("openOptions").addEventListener("click", () => {
