## `content.js`

This script removes obvious tracker script tags from the DOM.

```js
const trackerPatterns = [
  /doubleclick\.net/i,
  /google-analytics\.com/i,
  /googletagmanager\.com/i,
  /facebook\.net/i,
  /connect\.facebook\.net/i,
  /analytics\.twitter\.com/i
];

function isTrackerScript(src) {
  return trackerPatterns.some((pattern) => pattern.test(src));
}

function removeTrackerScripts() {
  const scripts = document.querySelectorAll("script[src]");
  scripts.forEach((script) => {
    const src = script.getAttribute("src") || "";
    if (isTrackerScript(src)) {
      script.remove();
    }
  });
}

function observeMutations() {
  const observer = new MutationObserver(() => {
    removeTrackerScripts();
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
}

removeTrackerScripts();
observeMutations();
```

