# `background.js`

This service worker stores simple stats and manages per-site allowlisting.

```js
const STORAGE_KEYS = {
  blockedCountPrefix: "blockedCount:",
  siteExceptions: "siteExceptions"
};

chrome.runtime.onInstalled.addListener(async () => {
  const { siteExceptions = {} } = await chrome.storage.local.get([STORAGE_KEYS.siteExceptions]);
  if (!siteExceptions) {
    await chrome.storage.local.set({ [STORAGE_KEYS.siteExceptions]: {} });
  }
});

function getHostname(url) {
  try {
    return new URL(url).hostname;
  } catch {
    return null;
  }
}

async function isSiteDisabled(hostname) {
  if (!hostname) return false;
  const { siteExceptions = {} } = await chrome.storage.local.get([STORAGE_KEYS.siteExceptions]);
  return Boolean(siteExceptions[hostname]);
}

chrome.webRequest = chrome.webRequest || {};

chrome.webRequest.onBeforeRequest?.addListener(
  async (details) => {
    const hostname = getHostname(details.initiator || details.documentUrl || details.url);
    const targetHost = getHostname(details.url);

    if (!targetHost) return;

    // If current site is allowlisted, don't count/block here.
    if (await isSiteDisabled(hostname)) return;

    // This listener is only for stats; actual blocking happens via DNR.
    const key = `${STORAGE_KEYS.blockedCountPrefix}${hostname || "unknown"}`;
    const data = await chrome.storage.local.get([key]);
    const current = data[key] || 0;

    await chrome.storage.local.set({ [key]: current + 1 });
  },
  { urls: ["<all_urls>"] },
  []
);

// Messages from popup/options
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  (async () => {
    if (message.type === "GET_STATUS") {
      const { tabUrl } = message;
      const hostname = getHostname(tabUrl);
      const { siteExceptions = {} } = await chrome.storage.local.get([STORAGE_KEYS.siteExceptions]);
      const disabled = hostname ? Boolean(siteExceptions[hostname]) : false;
      const blockedKey = `${STORAGE_KEYS.blockedCountPrefix}${hostname || "unknown"}`;
      const blockedData = await chrome.storage.local.get([blockedKey]);

      sendResponse({
        hostname,
        disabled,
        blockedCount: blockedData[blockedKey] || 0
      });
      return;
    }

    if (message.type === "TOGGLE_SITE") {
      const { tabUrl, disabled } = message;
      const hostname = getHostname(tabUrl);
      if (!hostname) {
        sendResponse({ ok: false });
        return;
      }

      const { siteExceptions = {} } = await chrome.storage.local.get([STORAGE_KEYS.siteExceptions]);
      siteExceptions[hostname] = disabled;
      await chrome.storage.local.set({ [STORAGE_KEYS.siteExceptions]: siteExceptions });

      sendResponse({ ok: true, hostname, disabled });
      return;
    }

    sendResponse({ ok: false });
  })();

  return true;
});
```

> Note: In MV3, `webRequest` is limited and not ideal for blocking. It’s used here only as a simple stats hook. The real blocking is handled by `declarativeNetRequest`.

