# `popup.js`

```js
async function getActiveTab() {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  return tab;
}

async function refresh() {
  const tab = await getActiveTab();
  if (!tab?.url) return;

  chrome.runtime.sendMessage(
    { type: "GET_STATUS", tabUrl: tab.url },
    (response) => {
      if (!response) return;

      document.getElementById("hostname").textContent = response.hostname || "Unknown";
      document.getElementById("blockedCount").textContent = String(response.blockedCount || 0);

      const btn = document.getElementById("toggleBtn");
      if (response.disabled) {
        btn.textContent = "Enable on this site";
        btn.className = "enabled";
      } else {
        btn.textContent = "Disable on this site";
        btn.className = "disabled";
      }
    }
  );
}

document.getElementById("toggleBtn").addEventListener("click", async () => {
  const tab = await getActiveTab();
  if (!tab?.url) return;

  chrome.runtime.sendMessage({ type: "GET_STATUS", tabUrl: tab.url }, (response) => {
    if (!response) return;

    chrome.runtime.sendMessage(
      {
        type: "TOGGLE_SITE",
        tabUrl: tab.url,
        disabled: !response.disabled
      },
      () => refresh()
    );
  });
});

document.getElementById("optionsBtn").addEventListener("click", () => {
  chrome.runtime.openOptionsPage();
});

refresh();
```

