const STORAGE_KEYS = {
  siteExceptions: "siteExceptions"
};

async function loadSites() {
  const { siteExceptions = {} } = await chrome.storage.local.get([STORAGE_KEYS.siteExceptions]);
  const siteList = document.getElementById("siteList");
  siteList.innerHTML = "";

  const entries = Object.entries(siteExceptions);
  if (entries.length === 0) {
    siteList.textContent = "No site exceptions set.";
    return;
