## 3) `service_worker.js`

This keeps track of extension state and badge updates.

```js
const DEFAULT_STATE = {
  enabled: true,
  blockedCount: 0
};

async function loadState() {
  const data = await chrome.storage.local.get(DEFAULT_STATE);
  return {
    enabled: data.enabled ?? true,
    blockedCount: data.blockedCount ?? 0
  };
}

async function saveState(state) {
  await chrome.storage.local.set(state);
}

async function updateBadge() {
  const { enabled, blockedCount } = await loadState();

  if (!enabled) {
    await chrome.action.setBadgeText({ text: "OFF" });
    await chrome.action.setBadgeBackgroundColor({ color: "#888888" });
    return;
  }

  await chrome.action.setBadgeText({ text: blockedCount > 0 ? String(blockedCount) : "" });
  await chrome.action.setBadgeBackgroundColor({ color: "#0f9d58" });
}

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.local.get(DEFAULT_STATE);
  await chrome.storage.local.set({
    enabled: current.enabled ?? true,
    blockedCount: current.blockedCount ?? 0
  });

  await updateBadge();
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "local" && (changes.enabled || changes.blockedCount)) {
    await updateBadge();
  }
});

// Optional: simple counter hook for future logging/telemetry
chrome.webNavigation.onCompleted.addListener(async () => {
  const state = await loadState();
  if (!state.enabled) return;
});

// Message handling from popup
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  (async () => {
    const state = await loadState();

    if (message?.type === "GET_STATE") {
      sendResponse(state);
      return;
    }

    if (message?.type === "SET_ENABLED") {
      await saveState({ ...state, enabled: Boolean(message.enabled) });
      sendResponse({ ok: true });
      return;
    }

    if (message?.type === "RESET_COUNTER") {
      await saveState({ ...state, blockedCount: 0 });
      sendResponse({ ok: true });
      return;
    }

    sendResponse({ ok: false, error: "Unknown message type" });
  })();

  return true;
});
```

> Important: `declarativeNetRequest` blocks requests automatically; to count blocked requests accurately, you’d typically use `onRuleMatchedDebug` which requires the `"declarativeNetRequestFeedback"` permission in development. If you want, I can add that next.

