function sendMessage(message) {
  return chrome.runtime.sendMessage(message);
}

async function loadState() {
  return await sendMessage({ type: "GET_STATE" });
}

async function init() {
  const toggle = document.getElementById("enabledToggle");
  const blockedCountEl = document.getElementById("blockedCount");
  const resetBtn = document.getElementById("resetBtn");

  const state = await loadState();
  toggle.checked = Boolean(state.enabled);
  blockedCountEl.textContent = String(state.blockedCount ?? 0);

  toggle.addEventListener("change", async () => {
    await sendMessage({ type: "SET_ENABLED", enabled: toggle.checked });
  });

  resetBtn.addEventListener("click", async () => {
    await sendMessage({ type: "RESET_COUNTER" });
    const updated = await loadState();
    blockedCountEl.textContent = String(updated.blockedCount ?? 0);
  });
}

document.addEventListener("DOMContentLoaded", init);
```

