## 9) Example dynamic-rule upgrade for `background.js`

If you want the next step now, here’s a starter version that syncs custom list entries into dynamic DNR rules:

```javascript
const BASE_DYNAMIC_RULE_START_ID = 1000;

function buildRulesFromCustomList(list) {
  return list.map((entry, index) => ({
    id: BASE_DYNAMIC_RULE_START_ID + index,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: entry,
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame", "ping"]
    }
  }));
}

async function syncCustomRules() {
  const { customList = [] } = await chrome.storage.sync.get(["customList"]);

  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const removeRuleIds = existingRules.map((rule) => rule.id);

  const addRules = buildRulesFromCustomList(customList);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds,
    addRules
  });
}

chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.sync.get(["enabled"], (result) => {
    if (typeof result.enabled !== "boolean") {
      chrome.storage.sync.set({ enabled: true });
    }
  });

  syncCustomRules();
});

chrome.storage.onChanged.addListener((changes, area) => {
  if (area === "sync" && changes.customList) {
    syncCustomRules();
  }
});
```

