## 4) `background.js`

This handles extension state and can be expanded later for dynamic rules.

```js
const DEFAULT_SETTINGS = {
  enabled: true,
  cleanUrlParams: true,
  blockThirdPartyScripts: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  await chrome.storage.sync.set({ ...DEFAULT_SETTINGS, ...current });
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_SETTINGS") {
    chrome.storage.sync.get(DEFAULT_SETTINGS).then((settings) => {
      sendResponse(settings);
    });
    return true;
  }

  if (message?.type === "SET_ENABLED") {
    chrome.storage.sync.set({ enabled: !!message.enabled }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

