## 5) `content.js`

This script runs on pages and:
- removes common tracking query params from the URL
- blocks some tracking-related DOM insertions
- optionally stops third-party scripts if you want to extend it

```js
const TRACKING_PARAMS = [
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "utm_id",
  "gclid",
  "fbclid",
  "msclkid",
  "mc_cid",
  "mc_eid"
];

function getSettings() {
  return chrome.runtime.sendMessage({ type: "GET_SETTINGS" });
}

function cleanTrackingParams() {
  const url = new URL(window.location.href);
  let changed = false;

  for (const param of TRACKING_PARAMS) {
    if (url.searchParams.has(param)) {
      url.searchParams.delete(param);
      changed = true;
    }
  }

  if (changed) {
    history.replaceState(null, "", url.toString());
  }
}

function blockKnownTrackersInDOM() {
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (node.nodeType !== Node.ELEMENT_NODE) continue;

        const el = node;
        const src = el.src || el.dataset?.src || "";

        if (
          el.tagName === "SCRIPT" &&
          /google-analytics\.com|googletagmanager\.com|doubleclick\.net|facebook\.net|analytics\.twitter\.com/i.test(src)
        ) {
          el.remove();
          continue;
        }

        if (el.tagName === "IFRAME" &&
          /doubleclick\.net|facebook\.com|googletagmanager\.com/i.test(src)
        ) {
          el.remove();
        }
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });
}

(async function init() {
  const settings = await getSettings();
  if (!settings.enabled) return;

  if (settings.cleanUrlParams) {
    cleanTrackingParams();
  }

  blockKnownTrackersInDOM();
})();
```

