## 5) `content.js`

This content script detects suspicious script tags and can optionally remove them if they match known tracking domains.

```js
function isTrackingUrl(url) {
  if (!url) return false;

  const trackingPatterns = [
    "doubleclick.net",
    "googletagmanager.com",
    "google-analytics.com",
    "analytics.twitter.com",
    "facebook.net",
    "stats.g.doubleclick.net"
  ];

  return trackingPatterns.some((pattern) => url.includes(pattern));
}

function removeTrackingScripts() {
  const scripts = document.querySelectorAll("script[src]");
  scripts.forEach((script) => {
    const src = script.src;
    if (isTrackingUrl(src)) {
      console.debug("[Privacy Shield] Removing tracking script:", src);
      script.remove();
    }
  });
}

// Run once early
removeTrackingScripts();

// Observe dynamic additions
const observer = new MutationObserver((mutations) => {
  for (const mutation of mutations) {
    for (const node of mutation.addedNodes) {
      if (node.nodeType !== Node.ELEMENT_NODE) continue;

      if (node.tagName === "SCRIPT" && node.src && isTrackingUrl(node.src)) {
        console.debug("[Privacy Shield] Blocking dynamically added tracking script:", node.src);
        node.remove();
      }

      const nestedScripts = node.querySelectorAll ? node.querySelectorAll("script[src]") : [];
      nestedScripts.forEach((script) => {
        if (isTrackingUrl(script.src)) {
          console.debug("[Privacy Shield] Blocking nested tracking script:", script.src);
          script.remove();
        }
      });
    }
  }
});

observer.observe(document.documentElement, {
  childList: true,
  subtree: true
});
```

