## 8) Add permission-aware behavior

Right now, the blocking rules run by default. If you want the toggle to actually enable/disable blocking, you should update dynamic rules through `declarativeNetRequest.updateEnabledRulesets`.

Here’s a simple pattern for that.

### Replace `service_worker.js` with:

```js
const RULESET_ID = "tracking_rules";

async function applyRulesetState(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [RULESET_ID]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const { enabled } = await chrome.storage.sync.get(["enabled"]);
  const state = enabled !== false;
  await chrome.storage.sync.set({ enabled: state });
  await applyRulesetState(state);
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes.enabled) {
    await applyRulesetState(changes.enabled.newValue !== false);
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "GET_STATUS") {
    chrome.storage.sync.get(["enabled"]).then((result) => {
      sendResponse({ enabled: result.enabled !== false });
    });
    return true;
  }
});
```

