## `background.js`

This keeps track of whether blocking is enabled and allows the popup to toggle it.

```js
const DEFAULT_ENABLED = true;

async function getEnabledState() {
  const result = await chrome.storage.sync.get({ trackingBlockingEnabled: DEFAULT_ENABLED });
  return result.trackingBlockingEnabled;
}

async function setEnabledState(enabled) {
  await chrome.storage.sync.set({ trackingBlockingEnabled: enabled });

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracking_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracking_rules"]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const enabled = await getEnabledState();
  await setEnabledState(enabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATE") {
    getEnabledState().then((enabled) => sendResponse({ enabled }));
    return true;
  }

  if (message?.type === "SET_STATE") {
    setEnabledState(Boolean(message.enabled)).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

