```js
const STORAGE_KEY = "customBlockedDomains";

document.addEventListener("DOMContentLoaded", async () => {
  const textarea = document.getElementById("customDomains");
  const saveBtn = document.getElementById("saveBtn");
  const saveMsg = document.getElementById("saveMsg");

  const data = await chrome.storage.sync.get(STORAGE_KEY);
  textarea.value = (data[STORAGE_KEY] || []).join("\n");

  saveBtn.addEventListener("click", async () => {
    const domains = textarea.value
      .split("\n")
      .map(s => s.trim())
      .filter(Boolean);

    await chrome.storage.sync.set({ [STORAGE_KEY]: domains });
    saveMsg.textContent = "Saved.";
    saveMsg.style.color = "green";

    // Future enhancement:
    // Convert these domains into dynamic DNR rules and apply them.
  });
});
```

