## 2) `background.js`

This registers a few static blocking rules on install/startup.

```js
const TRACKING_DOMAINS = [
  "doubleclick.net",
  "googletagmanager.com",
  "google-analytics.com",
  "analytics.google.com",
  "facebook.net",
  "connect.facebook.net",
  "adsystem.amazon.com",
  "scorecardresearch.com",
  "hotjar.com",
  "mixpanel.com",
  "segment.com"
];

function buildRules() {
  return TRACKING_DOMAINS.map((domain, index) => ({
    id: index + 1,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      requestDomains: [domain],
      resourceTypes: [
        "script",
        "xmlhttprequest",
        "sub_frame",
        "image",
        "ping",
        "websocket",
        "other"
      ]
    }
  }));
}

async function registerRules() {
  const rules = buildRules();

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: rules.map(rule => rule.id),
    addRules: rules
  });

  console.log("Privacy Blocker rules registered:", rules.length);
}

chrome.runtime.onInstalled.addListener(() => {
  registerRules();
});

chrome.runtime.onStartup.addListener(() => {
  registerRules();
});
```

