## `background.js`

This uses a small dynamic blocklist to block common tracking/script delivery domains.

```js
const DEFAULT_ENABLED = true;

const TRACKING_DOMAINS = [
  "doubleclick.net",
  "googlesyndication.com",
  "google-analytics.com",
  "googletagmanager.com",
  "googletagservices.com",
  "adservice.google.com",
  "facebook.net",
  "connect.facebook.net",
  "static.hotjar.com",
  "script.hotjar.com",
  "clarity.ms",
  "bat.bing.com",
  "snap.licdn.com",
  "googleadservices.com",
  "scorecardresearch.com",
  "segment.com",
  "cdn.segment.com",
  "mixpanel.com",
  "fullstory.com",
  "optimizely.com",
  "newrelic.com",
  "nr-data.net",
  "amplitude.com",
  "cdn.amplitude.com",
  "intercom.io",
  "js.intercomcdn.com",
  "livechatinc.com",
  "mouseflow.com",
  "yieldmanager.com",
  "taboola.com",
  "outbrain.com"
];

function domainToRule(domain, id) {
  return {
    id,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: domain,
      resourceTypes: [
        "script",
        "xmlhttprequest",
        "sub_frame",
        "image",
        "beacon",
        "ping",
        "font",
        "stylesheet",
        "media",
        "other"
      ]
    }
  };
}

async function applyBlockingRules(enabled) {
  const existing = await chrome.declarativeNetRequest.getDynamicRules();

  const removeRuleIds = existing.map(rule => rule.id);

  if (!enabled) {
    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds,
      addRules: []
    });
    return;
  }

  const addRules = TRACKING_DOMAINS.map((domain, index) =>
    domainToRule(domain, index + 1)
  );

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds,
    addRules
  });
}

async function init() {
  const { enabled } = await chrome.storage.sync.get({ enabled: DEFAULT_ENABLED });
  await applyBlockingRules(enabled);
}

chrome.runtime.onInstalled.addListener(init);
chrome.runtime.onStartup?.addListener(init);

// Listen for settings changes
chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "sync" && changes.enabled) {
    await applyBlockingRules(changes.enabled.newValue);
  }
});
```

