const STORAGE_KEY = "blockEnabled";

async function setBlocking(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["default_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["default_rules"]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.sync.get({ [STORAGE_KEY]: true });
  await setBlocking(data[STORAGE_KEY]);
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes[STORAGE_KEY]) {
    await setBlocking(changes[STORAGE_KEY].newValue);
  }
});
