## 4) `content.js`

This removes common tracker-like script elements that are inserted inline or dynamically.

```js
function removeKnownTrackers(root = document) {
  const selectors = [
    'script[src*="google-analytics.com"]',
    'script[src*="googletagmanager.com"]',
    'script[src*="doubleclick.net"]',
    'script[src*="facebook.net"]',
    'script[src*="hotjar.com"]'
  ];

  for (const selector of selectors) {
    root.querySelectorAll(selector).forEach(node => node.remove());
  }
}

removeKnownTrackers();

const observer = new MutationObserver(mutations => {
  for (const mutation of mutations) {
    for (const node of mutation.addedNodes) {
      if (node.nodeType !== Node.ELEMENT_NODE) continue;

      if (node.tagName === "SCRIPT" && node.src) {
        const src = node.src;
        if (
          src.includes("google-analytics.com") ||
          src.includes("googletagmanager.com") ||
          src.includes("doubleclick.net") ||
          src.includes("facebook.net") ||
          src.includes("hotjar.com")
        ) {
          node.remove();
          continue;
        }
      }

      removeKnownTrackers(node);
    }
  }
});

observer.observe(document.documentElement, {
  childList: true,
  subtree: true
});
```

