## Optional: expand with dynamic blocking

If you want a more flexible initial approach, you can use a dynamic rule generator in `background.js` instead of a static JSON-only file. Example:

```javascript
const TRACKING_DOMAINS = [
  "google-analytics.com",
  "googletagmanager.com",
  "doubleclick.net",
  "facebook.net",
  "analytics.google.com"
];

async function updateRules() {
  const rules = TRACKING_DOMAINS.map((domain, index) => ({
    id: index + 1,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: `||${domain}^`,
      resourceTypes: ["script", "xmlhttprequest", "sub_frame", "image", "other"]
    }
  }));

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: rules.map(r => r.id),
    addRules: rules
  });
}

chrome.runtime.onInstalled.addListener(async () => {
  await updateRules();
  chrome.action.setBadgeText({ text: "ON" });
  chrome.action.setBadgeBackgroundColor({ color: "#1e8e3e" });
});
```

