## `service_worker.js`

```js
const rules = [
  {
    id: 1,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "doubleclick.net",
      resourceTypes: ["script", "image", "xmlhttprequest", "sub_frame", "other"]
    }
  },
  {
    id: 2,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "googletagmanager.com",
      resourceTypes: ["script", "xmlhttprequest", "sub_frame", "other"]
    }
  },
  {
    id: 3,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "google-analytics.com",
      resourceTypes: ["script", "xmlhttprequest", "other"]
    }
  },
  {
    id: 4,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "facebook.net",
      resourceTypes: ["script", "xmlhttprequest", "other"]
    }
  },
  {
    id: 5,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "analytics",
      resourceTypes: ["script", "xmlhttprequest", "other"]
    }
  }
];

async function enableBlocking() {
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: rules.map((r) => r.id),
    addRules: rules
  });
}

async function disableBlocking() {
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: rules.map((r) => r.id)
  });
}

chrome.runtime.onInstalled.addListener(async () => {
  const { enabled = true } = await chrome.storage.local.get("enabled");
  if (enabled) await enableBlocking();
});

chrome.storage.onChanged.addListener(async (changes, namespace) => {
  if (namespace !== "local" || !changes.enabled) return;

  if (changes.enabled.newValue) {
    await enableBlocking();
  } else {
    await disableBlocking();
  }
});
```

