## `background.js`

This stores the enabled state and updates the static ruleset accordingly.

```javascript
const STORAGE_KEY = 'enabled';

chrome.runtime.onInstalled.addListener(async () => {
  const data = await chrome.storage.local.get(STORAGE_KEY);
  if (typeof data[STORAGE_KEY] === 'undefined') {
    await chrome.storage.local.set({ [STORAGE_KEY]: true });
  }

  const { enabled } = await chrome.storage.local.get(STORAGE_KEY);
  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? ['trackers'] : [],
    disableRulesetIds: enabled ? [] : ['trackers']
  });
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area !== 'local' || !changes[STORAGE_KEY]) return;

  const enabled = changes[STORAGE_KEY].newValue;
  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? ['trackers'] : [],
    disableRulesetIds: enabled ? [] : ['trackers']
  });
});
```

