<script>
(() => {
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const viewport = document.getElementById('viewport');
  const tooltip = document.getElementById('tooltip');
  const statusEl = document.getElementById('status');
  const universeEl = document.getElementById('universe');
  const speedEl = document.getElementById('speed');
  const resetBtn = document.getElementById('reset');
  const toggleBtn = document.getElementById('toggle');

  const state = {
    symbols: [],
    gridCols: 10,
    gridRows: 10,
    cellBase: 110,
    gap: 8,
    pxPerCell: 118,
    viewX: 0,
    viewY: 0,
    zoom: 1,
    minZoom: 0.4,
    maxZoom: 4,
    dragging: false,
    lastX: 0,
    lastY: 0,
    paused: false,
    speed: 700,
    hovered: null,
    lastUpdate: 0,
  };

  const colors = {
    neg: [209, 73, 91],
    mid: [17, 20, 29],
    pos: [43, 182, 115],
  };

  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function lerp(a, b, t) { return a + (b - a) * t; }

  function mixColor(value) {
    const t = clamp((value + 8) / 16, 0, 1);
    const c1 = t < 0.5 ? colors.neg : colors.mid;
    const c2 = t < 0.5 ? colors.mid : colors.pos;
    const tt = t < 0.5 ? t / 0.5 : (t - 0.5) / 0.5;
    const r = Math.round(lerp(c1[0], c2[0], tt));
    const g = Math.round(lerp(c1[1], c2[1], tt));
    const b = Math.round(lerp(c1[2], c2[2], tt));
    return `rgb(${r},${g},${b})`;
  }

  function makeSymbols(n) {
    const out = [];
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    for (let i = 0; i < n; i++) {
      let sym = '';
      const len = i % 2 === 0 ? 3 : 4;
      for (let j = 0; j < len; j++) sym += letters[(i * 7 + j * 11) % letters.length];
      out.push({
        symbol: sym + (i % 5 === 0 ? '' : ''),
        price: 50 + Math.random() * 450,
        changePct: (Math.random() * 8 - 4),
        volume: Math.floor(50_000 + Math.random() * 2_500_000),
        marketCap: Math.floor(1_000_000_000 + Math.random() * 700_000_000_000),
      });
    }
    return out;
  }

  function layoutSymbols() {
    const n = state.symbols.length;
    state.gridCols = Math.ceil(Math.sqrt(n));
    state.gridRows = Math.ceil(n / state.gridCols);
    state.pxPerCell = state.cellBase + state.gap;
  }

  function resizeCanvas() {
    const dpr = window.devicePixelRatio || 1;
    const rect = viewport.getBoundingClientRect();
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    draw();
  }

  function worldToScreen(wx, wy) {
    const rect = viewport.getBoundingClientRect();
    return {
      x: (wx - state.viewX) * state.zoom,
      y: (wy - state.viewY) * state.zoom,
      w: rect.width,
      h: rect.height
    };
  }

  function screenToWorld(sx, sy) {
    return {
      x: sx / state.zoom + state.viewX,
      y: sy / state.zoom + state.viewY
    };
  }

  function drawGridBackground(rect) {
    ctx.fillStyle = '#0b1020';
    ctx.fillRect(0, 0, rect.width, rect.height);

    const gridSize = 40 * state.zoom;
    if (gridSize < 16) return;
    ctx.strokeStyle = 'rgba(255,255,255,0.035)';
    ctx.lineWidth = 1;

    const startX = -((state.viewX * state.zoom) % gridSize);
    const startY = -((state.viewY * state.zoom) % gridSize);

    for (let x = startX; x < rect.width; x += gridSize) {
      ctx.beginPath();
      ctx.moveTo(x + 0.5, 0);
      ctx.lineTo(x + 0.5, rect.height);
      ctx.stroke();
    }
    for (let y = startY; y < rect.height; y += gridSize) {
      ctx.beginPath();
      ctx.moveTo(0, y + 0.5);
      ctx.lineTo(rect.width, y + 0.5);
      ctx.stroke();
    }
  }

  function draw() {
    const rect = viewport.getBoundingClientRect();
    drawGridBackground(rect);

    const items = state.symbols;

    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      const col = i % state.gridCols;
      const row = Math.floor(i / state.gridCols);

      const wx = col * state.pxPerCell;
      const wy = row * state.pxPerCell;

      const sx = (wx - state.viewX) * state.zoom;
      const sy = (wy - state.viewY) * state.zoom;
      const cell = state.cellBase * state.zoom;
      const gap = state.gap * state.zoom;

      if (sx + cell < 0 || sy + cell < 0 || sx > rect.width || sy > rect.height) continue;

      const isHover = state.hovered && state.hovered.index === i;

      ctx.fillStyle = mixColor(item.changePct);
      ctx.fillRect(sx + gap * 0.5, sy + gap * 0.5, cell, cell);

      ctx.fillStyle = 'rgba(255,255,255,0.08)';
      ctx.fillRect(sx + gap * 0.5, sy + cell - 22 * state.zoom, cell, 22 * state.zoom);

      if (isHover) {
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.strokeRect(sx + gap * 0.5 + 1, sy + gap * 0.5 + 1, cell - 2, cell - 2);
      }

      ctx.fillStyle = '#ffffff';
      ctx.font = `${Math.max(10, 13 * state.zoom)}px Inter, sans-serif`;
      ctx.textBaseline = 'top';
      ctx.fillText(item.symbol, sx + 10 * state.zoom, sy + 10 * state.zoom);

      ctx.font = `600 ${Math.max(11, 15 * state.zoom)}px Inter, sans-serif`;
      const priceText = `$${item.price.toFixed(2)}`;
      ctx.fillText(priceText, sx + 10 * state.zoom, sy + 32 * state.zoom);

      ctx.fillStyle = item.changePct >= 0 ? '#9ef2c2' : '#ffb2bc';
      ctx.font = `600 ${Math.max(10, 12 * state.zoom)}px Inter, sans-serif`;
      ctx.fillText((item.changePct >= 0 ? '+' : '') + item.changePct.toFixed(2) + '%',
        sx + 10 * state.zoom, sy + 55 * state.zoom);
    }
  }

  function updateStatus() {
    const n = state.symbols.length;
    statusEl.textContent = `${n} symbols | zoom ${state.zoom.toFixed(2)}x | ${state.paused ? 'paused' : 'live'}`;
  }

  function setUniverse(n) {
    state.symbols = makeSymbols(n);
    layoutSymbols();
    resetView();
    draw();
    updateStatus();
  }

  function resetView() {
    const rect = viewport.getBoundingClientRect();
    const contentW = state.gridCols * state.pxPerCell;
    const contentH = state.gridRows * state.pxPerCell;
    const fitZoom = Math.min(rect.width / (contentW + 40), rect.height / (contentH + 40));
    state.zoom = clamp(fitZoom, state.minZoom, 1.2);
    state.viewX = Math.max(0, (contentW - rect.width / state.zoom) / 2);
    state.viewY = Math.max(0, (contentH - rect.height / state.zoom) / 2);
    draw();
  }

  function simulateTick() {
    if (state.paused) return;
    const now = performance.now();
    if (now - state.lastUpdate < state.speed) return;
    state.lastUpdate = now;

    for (const item of state.symbols) {
      const drift = (Math.random() - 0.5) * 0.9;
      item.changePct = clamp(item.changePct * 0.86 + drift, -8, 8);
      item.price = Math.max(0.5, item.price * (1 + item.changePct / 1000));
      item.volume = Math.max(0, Math.round(item.volume * (0.995 + Math.random() * 0.015)));
    }
    draw();
    updateStatus();
  }

  function pointerEventPos(e) {
    const r = viewport.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  viewport.addEventListener('pointerdown', (e) => {
    viewport.setPointerCapture(e.pointerId);
    state.dragging = true;
    const p = pointerEventPos(e);
    state.lastX = p.x;
    state.lastY = p.y;
    tooltip.style.display = 'none';
  });

  viewport.addEventListener('pointermove', (e) => {
    const p = pointerEventPos(e);

    if (state.dragging) {
      const dx = (p.x - state.lastX) / state.zoom;
      const dy = (p.y - state.lastY) / state.zoom;
      state.viewX -= dx;
      state.viewY -= dy;
      state.lastX = p.x;
      state.lastY = p.y;
      draw();
      return;
    }

    const world = screenToWorld(p.x, p.y);
    const idx = hitTest(world.x, world.y);
    if (idx != null) {
      const item = state.symbols[idx];
      state.hovered = { index: idx };
      tooltip.style.display = 'block';
      tooltip.style.left = p.x + 'px';
      tooltip.style.top = p.y + 'px';
      tooltip.innerHTML = `
        <div class="sym">${item.symbol}</div>
        <div class="row"><span class="muted">Price</span><span>$${item.price.toFixed(2)}</span></div>
        <div class="row"><span class="muted">Change</span><span style="color:${item.changePct >= 0 ? '#9ef2c2' : '#ffb2bc'}">${item.changePct >= 0 ? '+' : ''}${item.changePct.toFixed(2)}%</span></div>
        <div class="row"><span class="muted">Volume</span><span>${item.volume.toLocaleString()}</span></div>
      `;
    } else {
      state.hovered = null;
      tooltip.style.display = 'none';
    }
    draw();
  });

  viewport.addEventListener('pointerup', () => {
    state.dragging = false;
  });

  viewport.addEventListener('wheel', (e) => {
    e.preventDefault();
    const rect = viewport.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    const before = screenToWorld(mx, my);

    const zoomFactor = Math.exp(-e.deltaY * 0.001);
    const nextZoom = clamp(state.zoom * zoomFactor, state.minZoom, state.maxZoom);

    state.zoom = nextZoom;
    const after = screenToWorld(mx, my);

    state.viewX += before.x - after.x;
    state.viewY += before.y - after.y;

    draw();
    updateStatus();
  }, { passive: false });

  function hitTest(wx, wy) {
    const col = Math.floor(wx / state.pxPerCell);
    const row = Math.floor(wy / state.pxPerCell);
    if (col < 0 || row < 0 || col >= state.gridCols || row >= state.gridRows) return null;
    const idx = row * state.gridCols + col;
    if (idx < 0 || idx >= state.symbols.length) return null;

    const cellX = col * state.pxPerCell;
    const cellY = row * state.pxPerCell;
    const within = wx >= cellX && wx <= cellX + state.cellBase && wy >= cellY && wy <= cellY + state.cellBase;
    return within ? idx : null;
  }

  resetBtn.addEventListener('click', () => { resetView(); updateStatus(); });
  toggleBtn.addEventListener('click', () => {
    state.paused = !state.paused;
    toggleBtn.textContent = state.paused ? 'Resume' : 'Pause';
    updateStatus();
  });

  universeEl.addEventListener('change', () => setUniverse(parseInt(universeEl.value, 10)));
  speedEl.addEventListener('input', () => {
    state.speed = parseInt(speedEl.value, 10);
    updateStatus();
  });

  window.addEventListener('resize', () => {
    resizeCanvas();
    resetView();
  });

  setUniverse(parseInt(universeEl.value, 10));
  state.speed = parseInt(speedEl.value, 10);
  resizeCanvas();
  requestAnimationFrame(function loop() {
    simulateTick();
    requestAnimationFrame(loop);
  });
})();
</script>
</body>
</html>
```

