<body>
  <div class="app">
    <div class="header">
      <div class="title">
        <h1>Interactive Stock Price Heatmap</h1>
        <p>Client-side, real-time updates, zoom/pan, hover details</p>
      </div>

      <div class="controls">
        <div class="legend">
          <span>Change %</span>
          <div class="gradient"></div>
        </div>
        <button id="resetZoom">Reset Zoom</button>
        <button id="pauseBtn">Pause Stream</button>
        <div class="status" id="status">Live: updating...</div>
      </div>
    </div>

    <div class="main" id="chart"></div>
    <div class="tooltip" id="tooltip"></div>
  </div>

  <script>
    // ----------------------------
    // Data setup
    // ----------------------------
    const stocks = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX",
      "AMD","INTC","ORCL","CRM","ADBE","UBER","DIS","BAC",
      "JPM","V","MA","PYPL","QCOM","CSCO","IBM","PFE"
    ];

    const cols = 6;
    const rows = Math.ceil(stocks.length / cols);

    const data = stocks.map((symbol, i) => ({
      symbol,
      row: Math.floor(i / cols),
      col: i % cols,
      price: 100 + Math.random() * 500,
      prevPrice: 100 + Math.random() * 500,
      volume: Math.floor(100000 + Math.random() * 5000000),
      sector: ["Tech","Finance","Health","Retail"][i % 4]
    }));

    // ----------------------------
    // Chart setup
    // ----------------------------
    const container = document.getElementById("chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const svg = d3.select(container)
      .append("svg")
      .attr("aria-label", "Stock heatmap");

    const gRoot = svg.append("g");
    const gMap = gRoot.append("g").attr("class", "map");
    const gLabels = gRoot.append("g").attr("class", "labels");

    const padding = 22;
    const gap = 10;
    let width = 0, height = 0;
    let cellSize = 0;

    const color = d3.scaleSequential()
      .domain([-8, 8])
      .interpolator(d3.interpolateRdYlGn);

    const zoom = d3.zoom()
      .scaleExtent([0.6, 8])
      .on("zoom", (event) => {
        gRoot.attr("transform", event.transform);
      });

    svg.call(zoom);

    function resize() {
      width = container.clientWidth;
      height = container.clientHeight;
      svg.attr("viewBox", `0 0 ${width} ${height}`);

      const availableW = width - padding * 2;
      const availableH = height - padding * 2;
      cellSize = Math.min(
        (availableW - gap * (cols - 1)) / cols,
        (availableH - gap * (rows - 1)) / rows
      );

      render();
    }

    // ----------------------------
    // Rendering
    // ----------------------------
    function pctChange(d) {
      return ((d.price - d.prevPrice) / d.prevPrice) * 100;
    }

    function render() {
      const x0 = padding;
      const y0 = padding;

      const cells = gMap.selectAll(".cell-group")
        .data(data, d => d.symbol);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "cell-group")
        .style("cursor", "pointer")
        .on("mousemove", (event, d) => showTooltip(event, d))
        .on("mouseleave", hideTooltip)
        .on("click", (_, d) => {
          alert(`${d.symbol}\nPrice: $${d.price.toFixed(2)}\nChange: ${pctChange(d).toFixed(2)}%`);
        });

      cellsEnter.append("rect")
        .attr("class", "cell");

      cellsEnter.append("text")
        .attr("class", "label")
        .attr("dy", "-0.3em");

      cellsEnter.append("text")
        .attr("class", "label")
        .attr("dy", "1.0em")
        .style("font-size", "10px")
        .attr("opacity", 0.9);

      const merged = cellsEnter.merge(cells);

      merged.attr("transform", d => {
        const x = x0 + d.col * (cellSize + gap);
        const y = y0 + d.row * (cellSize + gap);
        return `translate(${x},${y})`;
      });

      merged.select("rect")
        .attr("width", cellSize)
        .attr("height", cellSize)
        .attr("fill", d => color(pctChange(d)));

      merged.selectAll(".label").remove();

      merged.append("text")
        .attr("class", "label")
        .attr("x", cellSize / 2)
        .attr("y", cellSize / 2 - 8)
        .text(d => d.symbol);

      merged.append("text")
        .attr("class", "label")
        .attr("x", cellSize / 2)
        .attr("y", cellSize / 2 + 10)
        .style("font-size", "10px")
        .text(d => `${pctChange(d).toFixed(2)}%`);

      cells.exit().remove();

      // Axis labels (simple row/column indicators)
      const rowLabels = gLabels.selectAll(".row-label")
        .data(d3.range(rows));

      rowLabels.enter()
        .append("text")
        .attr("class", "axis-label row-label")
        .merge(rowLabels)
        .attr("x", 4)
        .attr("y", r => y0 + r * (cellSize + gap) + cellSize / 2)
        .attr("dominant-baseline", "middle")
        .text(r => `Row ${r + 1}`);

      rowLabels.exit().remove();
    }

    // ----------------------------
    // Tooltip
    // ----------------------------
    function showTooltip(event, d) {
      const change = pctChange(d);
      tooltip.style.opacity = 1;
      tooltip.innerHTML = `
        <div style="font-weight:700; font-size:13px; margin-bottom:6px;">${d.symbol}</div>
        <div>Price: <b>$${d.price.toFixed(2)}</b></div>
        <div>Prev: $${d.prevPrice.toFixed(2)}</div>
        <div>Change: <b style="color:${change >= 0 ? '#22c55e' : '#ef4444'}">${change.toFixed(2)}%</b></div>
        <div>Volume: ${d.volume.toLocaleString()}</div>
        <div>Sector: ${d.sector}</div>
      `;

      const rect = container.getBoundingClientRect();
      tooltip.style.left = `${event.clientX - rect.left}px`;
      tooltip.style.top = `${event.clientY - rect.top}px`;
    }

    function hideTooltip() {
      tooltip.style.opacity = 0;
    }

    // ----------------------------
    // Real-time mock stream
    // ----------------------------
    let live = true;
    let interval = null;

    function tick() {
      if (!live) return;

      data.forEach(d => {
        d.prevPrice = d.price;
        const drift = (Math.random() - 0.5) * 10; // random move
        d.price = Math.max(1, d.price + drift);
        d.volume = Math.max(0, d.volume + Math.floor((Math.random() - 0.4) * 25000));
      });

      render();
      statusEl.textContent = `Live: updated ${new Date().toLocaleTimeString()}`;
    }

    interval = setInterval(tick, 1200);

    // ----------------------------
    // Controls
    // ----------------------------
    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      live = !live;
      e.target.textContent = live ? "Pause Stream" : "Resume Stream";
      statusEl.textContent = live ? "Live: updating..." : "Paused";
    });

    // ----------------------------
    // Init + responsive
    // ----------------------------
    window.addEventListener("resize", resize);
    resize();

    // Optional: use wheel zoom centered on pointer naturally via d3.zoom
    // Optional: replace setInterval with WebSocket updates for real market data
  </script>
</body>
