      price: 50 + Math.random() * 450,
      prevPrice: null,
      volume: Math.floor(100000 + Math.random() * 900000),
      sector: ["Tech", "Finance", "Health", "Energy", "Consumer"][i % 5]
    }));

    let scale = 1;
    let panX = 0;
    let panY = 0;
    let isDragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let startPanX = 0;
    let startPanY = 0;
    let liveUpdates = true;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function performanceColor(deltaPct) {
      // Map performance to red -> yellow -> green
      const d = clamp(deltaPct, -5, 5);
      if (d < 0) {
        const t = (d + 5) / 5; // 0..1
        const r = 198;
        const g = Math.round(40 + t * 140);
        const b = Math.round(40 + t * 30);
        return `rgb(${r}, ${g}, ${b})`;
      } else {
        const t = d / 5;
        const r = Math.round(255 - t * 110);
        const g = Math.round(179 + t * 48);
        const b = Math.round(48 - t * 20);
        return `rgb(${r}, ${g}, ${b})`;
      }
    }

    function renderGrid() {
      grid.innerHTML = '';
      stocks.forEach(stock => {
        const deltaPct = stock.prevPrice == null
          ? 0
          : ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;

        const tile = document.createElement('div');
        tile.className = 'tile';
        tile.style.background = performanceColor(deltaPct);

        const deltaSign = deltaPct >= 0 ? '+' : '';
        tile.innerHTML = `
          <div class="symbol">${stock.symbol}</div>
          <div>
            <div class="price-row">
              <span>$${stock.price.toFixed(2)}</span>
              <span class="delta">${deltaSign}${deltaPct.toFixed(2)}%</span>
            </div>
            <div class="price-row">
              <span class="muted">Vol</span>
              <span>${stock.volume.toLocaleString()}</span>
            </div>
          </div>
        `;

        tile.addEventListener('mousemove', (e) => {
          tooltip.style.display = 'block';
          tooltip.style.left = (e.clientX + 14) + 'px';
          tooltip.style.top = (e.clientY + 14) + 'px';
          tooltip.innerHTML = `
            <div><strong>${stock.symbol}</strong> <span class="muted">(${stock.sector})</span></div>
            <div>Price: $${stock.price.toFixed(2)}</div>
            <div>Change: <span style="color:${deltaPct >= 0 ? '#75e08a' : '#ff7b7b'}">
              ${deltaSign}${deltaPct.toFixed(2)}%
            </span></div>
            <div>Volume: ${stock.volume.toLocaleString()}</div>
          `;
        });

        tile.addEventListener('mouseleave', () => {
          tooltip.style.display = 'none';
        });

        grid.appendChild(tile);
      });
    }

    function updatePrices() {
      if (!liveUpdates) return;

      stocks.forEach(stock => {
        stock.prevPrice = stock.price;
        const jump = (Math.random() - 0.5) * 0.08; // +/- 4%
        stock.price = Math.max(1, stock.price * (1 + jump));
        stock.volume = Math.max(1000, Math.floor(stock.volume * (0.98 + Math.random() * 0.04)));
      });

      renderGrid();
      statusEl.textContent = `Live updates: ON | ${new Date().toLocaleTimeString()}`;
    }

    function applyTransform() {
      world.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const nextScale = clamp(scale * zoomFactor, 0.5, 3);

      // Zoom around pointer
      panX = mouseX - ((mouseX - panX) * (nextScale / scale));
      panY = mouseY - ((mouseY - panY) * (nextScale / scale));
      scale = nextScale;

      applyTransform();
    }, { passive: false });

    viewport.addEventListener('mousedown', (e) => {
      isDragging = true;
      viewport.classList.add('dragging');
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      panX = startPanX + (e.clientX - dragStartX);
      panY = startPanY + (e.clientY - dragStartY);
      applyTransform();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      viewport.classList.remove('dragging');
    });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      panX = 0;
      panY = 0;
      applyTransform();
    });

    pauseBtn.addEventListener('click', () => {
      liveUpdates = !liveUpdates;
      pauseBtn.textContent = liveUpdates ? 'Pause Live Updates' : 'Resume Live Updates';
      statusEl.textContent = liveUpdates ? 'Live updates: ON' : 'Live updates: PAUSED';
    });

    // Initial render
    renderGrid();
    applyTransform();

    // Real-time updates
    setInterval(updatePrices, 1200);

    // Keep tooltip inside screen a bit better
    window.addEventListener('mousemove', (e) => {
      if (tooltip.style.display === 'none') return;
      const pad = 16;
      const rect = tooltip.getBoundingClientRect();
      let x = e.clientX + 14;
      let y = e.clientY + 14;
      if (x + rect.width > window.innerWidth - pad) x = e.clientX - rect.width - 14;
      if (y + rect.height > window.innerHeight - pad) y = e.clientY - rect.height - 14;
      tooltip.style.left = x + 'px';
      tooltip.style.top = y + 'px';
    });
  </script>
</body>
</html>
```

