    const svg = d3.select("#chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const toggleStreamBtn = document.getElementById("toggleStreamBtn");
    const resetViewBtn = document.getElementById("resetViewBtn");

    const width = () => document.querySelector(".chart-wrap").clientWidth;
    const height = () => document.querySelector(".chart-wrap").clientHeight;

    const margin = { top: 30, right: 30, bottom: 30, left: 70 };

    const sectors = ["Technology", "Finance", "Healthcare", "Energy", "Consumer", "Industrials"];
    const stocksPerSector = 12;

    // Generate mock stock data
    let data = [];
    for (const sector of sectors) {
      for (let i = 0; i < stocksPerSector; i++) {
        const ticker = `${sector.slice(0, 3).toUpperCase()}${i + 1}`;
        const base = 20 + Math.random() * 180;
        const prev = base * (1 + (Math.random() - 0.5) * 0.04);
        const changePct = ((base - prev) / prev) * 100;
        data.push({
          sector,
          ticker,
          price: base,
          prevClose: prev,
          changePct
        });
      }
    }

    const xDomain = data.map(d => d.ticker);
    const yDomain = sectors;

    const xScale = d3.scaleBand().domain(xDomain).padding(0.08);
    const yScale = d3.scaleBand().domain(yDomain).padding(0.12);

    const colorScale = d3.scaleDiverging()
      .domain([-8, 0, 8])
      .interpolator(d3.interpolateRdYlGn);

    const root = svg.append("g").attr("class", "root");
    const grid = root.append("g").attr("class", "grid");
    const gx = root.append("g").attr("class", "axis axis-x");
    const gy = root.append("g").attr("class", "axis axis-y");

    let streaming = true;
    let currentTransform = d3.zoomIdentity;

    function render() {
      const w = width();
      const h = height();
      svg.attr("viewBox", `0 0 ${w} ${h}`);

      xScale.range([margin.left, w - margin.right]);
      yScale.range([margin.top, h - margin.bottom]);

      gx.attr("transform", `translate(0, ${h - margin.bottom})`)
        .call(d3.axisBottom(xScale).tickValues(xDomain.filter((_, i) => i % 2 === 0)))
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

      gy.attr("transform", `translate(${margin.left}, 0)`)
        .call(d3.axisLeft(yScale));

      const cells = grid.selectAll("rect.cell")
        .data(data, d => d.ticker);

      cells.enter()
        .append("rect")
        .attr("class", "cell")
        .merge(cells)
        .attr("x", d => xScale(d.ticker))
        .attr("y", d => yScale(d.sector))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.changePct))
        .on("mousemove", (event, d) => {
          const [x, y] = d3.pointer(event, document.querySelector(".chart-wrap"));
          tooltip.style.left = `${x}px`;
          tooltip.style.top = `${y}px`;
          tooltip.style.opacity = 1;
          tooltip.innerHTML = `
            <strong>${d.ticker}</strong><br/>
            Sector: ${d.sector}<br/>
            Price: $${d.price.toFixed(2)}<br/>
            Prev Close: $${d.prevClose.toFixed(2)}<br/>
            Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
          `;
        })
        .on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });

      cells.exit().remove();

      // Apply existing zoom transform
      root.attr("transform", currentTransform);
    }

    function updatePrices() {
      data = data.map(d => {
        const drift = (Math.random() - 0.5) * 0.025; // up/down movement
        const newPrice = Math.max(1, d.price * (1 + drift));
        const changePct = ((newPrice - d.prevClose) / d.prevClose) * 100;

        return {
          ...d,
          price: newPrice,
          changePct
        };
      });

      grid.selectAll("rect.cell")
        .data(data, d => d.ticker)
        .transition()
        .duration(350)
        .attr("fill", d => colorScale(d.changePct));

      const avg = d3.mean(data, d => d.changePct);
      statusEl.textContent = streaming
        ? `Streaming live price changes… Avg change: ${avg >= 0 ? "+" : ""}${avg.toFixed(2)}%`
        : `Paused. Avg change: ${avg >= 0 ? "+" : ""}${avg.toFixed(2)}%`;
    }

    const zoom = d3.zoom()
      .scaleExtent([1, 8])
      .translateExtent([[0, 0], [width(), height()]])
      .extent([[0, 0], [width(), height()]])
      .on("zoom", (event) => {
        currentTransform = event.transform;
        root.attr("transform", currentTransform);
      });

    svg.call(zoom);

    resetViewBtn.addEventListener("click", () => {
      svg.transition().duration(400).call(zoom.transform, d3.zoomIdentity);
    });

    toggleStreamBtn.addEventListener("click", () => {
      streaming = !streaming;
      toggleStreamBtn.textContent = streaming ? "Pause Updates" : "Resume Updates";
      statusEl.textContent = streaming ? "Streaming live price changes…" : "Updates paused.";
    });

    // Responsive redraw
    const ro = new ResizeObserver(() => {
      render();
      svg.call(zoom).call(zoom.transform, currentTransform);
    });
    ro.observe(document.querySelector(".chart-wrap"));

    render();

    // Simulate real-time updates
    setInterval(() => {
      if (streaming) updatePrices();
    }, 1000);
  </script>
