          prevPrice: prev,
          price,
          volume: Math.max(1000, d.volume + Math.round((Math.random() - 0.5) * 200000))
        };
      });
      render();
    }

    function render() {
      const innerW = width - margin.left - margin.right;
      const innerH = height - margin.top - margin.bottom;

      const { cols, rows, cellW, cellH } = getGridLayout(data.length, innerW, innerH);

      const nodes = zoomLayer
        .selectAll(".stock-node")
        .data(data, d => d.symbol);

      const nodesEnter = nodes.enter()
        .append("g")
        .attr("class", "stock-node");

      nodesEnter.append("rect")
        .attr("class", "cell")
        .attr("rx", 12)
        .attr("ry", 12)
        .on("mousemove", function(event, d) {
          const changePct = ((d.price - d.prevPrice) / d.prevPrice) * 100;
          tooltip
            .style("opacity", 1)
            .style("left", `${event.offsetX}px`)
            .style("top", `${event.offsetY}px`)
            .html(`
              <strong>${d.symbol}</strong><br/>
              Price: ${formatCurrency(d.price)}<br/>
              Change: ${formatPct(changePct)}%<br/>
              Volume: ${formatVolume(d.volume)}<br/>
              Sector: ${d.sector}
            `);
        })
        .on("mouseleave", () => tooltip.style("opacity", 0));

      nodesEnter.append("text")
        .attr("class", "cell-label");

      nodesEnter.append("text")
        .attr("class", "cell-price")
        .attr("dy", "1.4em");

      const merged = nodesEnter.merge(nodes);

      merged.each(function(d, i) {
        const col = i % cols;
        const row = Math.floor(i / cols);

        const x = margin.left + col * cellW + 8;
        const y = margin.top + row * cellH + 8;
        const w = Math.max(0, cellW - 16);
        const h = Math.max(0, cellH - 16);

        const changePct = ((d.price - d.prevPrice) / d.prevPrice) * 100;
        const bg = colorScale(Math.max(-5, Math.min(5, changePct)));

        d3.select(this)
          .attr("transform", `translate(${x},${y})`);

        d3.select(this).select("rect")
          .attr("width", w)
          .attr("height", h)
          .attr("fill", bg);

        d3.select(this).select(".cell-label")
          .attr("x", w / 2)
          .attr("y", h / 2 - 8)
          .text(d.symbol);

        d3.select(this).select(".cell-price")
          .attr("x", w / 2)
          .attr("y", h / 2 + 10)
          .text(`${formatCurrency(d.price)} (${formatPct(changePct)}%)`);
      });

      nodes.exit().remove();
    }

    function tick() {
      if (live) {
        updatePrices();
        statusEl.textContent = "Live updates: on";
      } else {
        statusEl.textContent = "Live updates: paused";
      }
    }

    document.getElementById("resetZoom").addEventListener("click", () => {
      svg.transition().duration(400).call(zoom.transform, d3.zoomIdentity);
    });

    document.getElementById("toggleLive").addEventListener("click", (e) => {
      live = !live;
      e.target.textContent = live ? "Pause" : "Resume";
      statusEl.textContent = live ? "Live updates: on" : "Live updates: paused";
    });

    window.addEventListener("resize", resize);

    resize();
    render();
    setInterval(tick, 1500);
  </script>
</body>
</html>
```

