<body>
  <div class="app">
    <header>
      <h1>Real-Time Stock Heatmap</h1>
      <div class="controls">
        <button id="resetBtn">Reset View</button>
        <span>Wheel: zoom • Drag: pan • Hover: details</span>
      </div>
    </header>

    <div class="main">
      <div id="viewport" class="viewport">
        <div id="heatmap" class="heatmap"></div>
      </div>
      <div id="tooltip" class="tooltip"></div>
    </div>

    <div class="footer">
      <div class="legend">
        <span>Performance</span>
        <div class="gradient"></div>
        <span>Loss → Gain</span>
      </div>
      <div id="status">Streaming simulated prices...</div>
    </div>
  </div>

  <script>
    // ----- Data setup -----
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","META","NVDA","TSLA","NFLX","AMD","INTC",
      "ORCL","CRM","UBER","ABNB","QCOM","ADBE","IBM","PYPL","SHOP","SNOW",
      "BA","JPM","V","MA","UNH","XOM","CVX","KO","PEP","DIS",
      "NKE","MCD","COST","WMT","T","VZ","SBUX","CSCO","BMY","PFE"
    ];

    const cols = 5;
    const cellW = 95;
    const cellH = 75;

    const state = {
      prices: new Map(),
      basePrices: new Map(),
      changes: new Map(),
      scale: 1,
      offsetX: 20,
      offsetY: 20,
      drag: false,
      dragStartX: 0,
      dragStartY: 0,
      panStartX: 0,
      panStartY: 0,
    };

    const heatmap = document.getElementById("heatmap");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const resetBtn = document.getElementById("resetBtn");

    // Initialize prices
    symbols.forEach((sym, i) => {
      const base = 50 + Math.random() * 450;
      state.basePrices.set(sym, base);
      state.prices.set(sym, base);
      state.changes.set(sym, 0);
    });

    // ----- Rendering -----
    function getColor(percent) {
      // percent in range approx [-10, 10]
      const clamped = Math.max(-10, Math.min(10, percent));
      const t = (clamped + 10) / 20; // 0..1
      const red = [217, 75, 75];
      const mid = [38, 42, 68];
      const green = [75, 217, 125];

      let a, b, localT;
      if (t < 0.5) {
        a = red; b = mid; localT = t / 0.5;
      } else {
        a = mid; b = green; localT = (t - 0.5) / 0.5;
      }

      const r = Math.round(a[0] + (b[0] - a[0]) * localT);
      const g = Math.round(a[1] + (b[1] - a[1]) * localT);
      const b2 = Math.round(a[2] + (b[2] - a[2]) * localT);
      return `rgb(${r}, ${g}, ${b2})`;
    }

    function renderHeatmap() {
      const rows = Math.ceil(symbols.length / cols);
      heatmap.style.gridTemplateColumns = `repeat(${cols}, ${cellW}px)`;
      heatmap.style.gridAutoRows = `${cellH}px`;

      heatmap.style.width = `${cols * cellW + 12}px`;
      heatmap.style.height = `${rows * cellH + 12}px`;

      heatmap.innerHTML = "";

      symbols.forEach((sym, idx) => {
        const price = state.prices.get(sym);
        const base = state.basePrices.get(sym);
        const change = ((price - base) / base) * 100;

        const cell = document.createElement("div");
        cell.className = "cell";
        cell.style.background = getColor(change);
        cell.dataset.symbol = sym;

        const changeColor = change >= 0 ? "#b9ffd0" : "#ffd0d0";
        cell.innerHTML = `
          <div class="symbol">${sym}</div>
          <div class="price">$${price.toFixed(2)}</div>
          <div class="change" style="color:${changeColor}">
            ${change >= 0 ? "+" : ""}${change.toFixed(2)}%
          </div>
        `;

        cell.addEventListener("mouseenter", (e) => showTooltip(e, sym));
        cell.addEventListener("mousemove", (e) => showTooltip(e, sym));
        cell.addEventListener("mouseleave", hideTooltip);

        heatmap.appendChild(cell);
      });

      applyTransform();
    }

    function applyTransform() {
      heatmap.style.transform = `translate(${state.offsetX}px, ${state.offsetY}px) scale(${state.scale})`;
    }

    // ----- Tooltip -----
    function showTooltip(e, sym) {
      const price = state.prices.get(sym);
      const base = state.basePrices.get(sym);
      const change = ((price - base) / base) * 100;

      tooltip.style.opacity = "1";
      tooltip.innerHTML = `
        <strong>${sym}</strong><br/>
        Price: $${price.toFixed(2)}<br/>
        Base: $${base.toFixed(2)}<br/>
        Change: ${change >= 0 ? "+" : ""}${change.toFixed(2)}%<br/>
        Updated: ${new Date().toLocaleTimeString()}
      `;

      const margin = 16;
      const x = Math.min(window.innerWidth - 220, e.clientX + margin);
      const y = Math.min(window.innerHeight - 120, e.clientY + margin);
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.style.opacity = "0";
    }

    // ----- Simulated real-time updates -----
    function updatePrices() {
      symbols.forEach(sym => {
        const current = state.prices.get(sym);
        const drift = (Math.random() - 0.5) * 2.2;        // random walk
        const shock = Math.random() < 0.02 ? (Math.random() - 0.5) * 25 : 0;
        const next = Math.max(1, current + drift + shock);
        state.prices.set(sym, next);
      });

      // Update visual state without rebuilding event listeners from scratch if desired,
      // but for simplicity here we rerender.
      renderHeatmap();

      const first = symbols[0];
      statusEl.textContent = `Last update: ${new Date().toLocaleTimeString()} • ${first}: $${state.prices.get(first).toFixed(2)}`;
    }

    // ----- Zoom & pan -----
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomIntensity = 0.0015;
      const oldScale = state.scale;
      const delta = -e.deltaY;
      const newScale = Math.min(4, Math.max(0.4, oldScale * (1 + delta * zoomIntensity)));

      // Zoom around cursor
      const rect = viewport.getBoundingClientRect();
      const cursorX = e.clientX - rect.left;
      const cursorY = e.clientY - rect.top;

      const worldX = (cursorX - state.offsetX) / oldScale;
      const worldY = (cursorY - state.offsetY) / oldScale;

      state.scale = newScale;
      state.offsetX = cursorX - worldX * newScale;
      state.offsetY = cursorY - worldY * newScale;

      applyTransform();
    }, { passive: false });

    viewport.addEventListener("pointerdown", (e) => {
      state.drag = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.panStartX = state.offsetX;
      state.panStartY = state.offsetY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener("pointermove", (e) => {
      if (!state.drag) return;
      state.offsetX = state.panStartX + (e.clientX - state.dragStartX);
      state.offsetY = state.panStartY + (e.clientY - state.dragStartY);
      applyTransform();
    });

    viewport.addEventListener("pointerup", () => {
      state.drag = false;
    });

    viewport.addEventListener("pointercancel", () => {
      state.drag = false;
    });

    resetBtn.addEventListener("click", () => {
      state.scale = 1;
      state.offsetX = 20;
      state.offsetY = 20;
      applyTransform();
    });

    // ----- Initial render + streaming -----
    renderHeatmap();
    setInterval(updatePrices, 1000);

    // Keep tooltip hidden on resize and maintain visibility.
    window.addEventListener("resize", hideTooltip);
  </script>
</body>
