        const t = clamp((v + maxAbs) / (2 * maxAbs), 0, 1); // 0 blue, 0.5 neutral, 1 red
        let r, g, b;

        if (t < 0.5) {
          const k = t / 0.5;
          r = Math.round(lerp(28, 38, k));
          g = Math.round(lerp(82, 224, k));
          b = Math.round(lerp(197, 65, k));
        } else {
          const k = (t - 0.5) / 0.5;
          r = Math.round(lerp(38, 239, k));
          g = Math.round(lerp(224, 68, k));
          b = Math.round(lerp(65, 68, k));
        }
        return `rgb(${r},${g},${b})`;
      }

      function drawRoundedRect(x, y, w, h, r) {
        const radius = Math.min(r, w / 2, h / 2);
        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.arcTo(x + w, y, x + w, y + h, radius);
        ctx.arcTo(x + w, y + h, x, y + h, radius);
        ctx.arcTo(x, y + h, x, y, radius);
        ctx.arcTo(x, y, x + w, y, radius);
        ctx.closePath();
      }

      function screenToWorld(sx, sy) {
        const x = (sx - state.view.offsetX) / state.view.scale;
        const y = (sy - state.view.offsetY) / state.view.scale;
        return { x, y };
      }

      function worldToScreen(wx, wy) {
        return {
          x: wx * state.view.scale + state.view.offsetX,
          y: wy * state.view.scale + state.view.offsetY
        };
      }

      function render() {
        const w = canvas.width;
        const h = canvas.height;

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, w, h);

        // Background
        ctx.fillStyle = '#081022';
        ctx.fillRect(0, 0, w, h);

        // Apply zoom/pan transform
        ctx.setTransform(state.view.scale * state.dpr, 0, 0, state.view.scale * state.dpr, state.view.offsetX * state.dpr, state.view.offsetY * state.dpr);

        const cellW = 72;
        const cellH = 34;
        const gap = 4;
        const padLeft = 120;
        const padTop = 34;

        // Grid + labels
        ctx.font = '12px Inter, system-ui, sans-serif';
        ctx.textBaseline = 'middle';

        // Time labels
        ctx.fillStyle = 'rgba(215,225,255,0.8)';
        for (let c = 0; c < cols; c++) {
          const x = padLeft + c * (cellW + gap) + cellW / 2;
          ctx.save();
          ctx.translate(x, 16);
          ctx.rotate(-Math.PI / 6);
          ctx.fillText(times[c], 0, 0);
          ctx.restore();
        }

        // Draw cells
        for (let r = 0; r < rows; r++) {
          const y = padTop + r * (cellH + gap);

          // row label
          ctx.fillStyle = 'rgba(215,225,255,0.92)';
          ctx.font = '12px Inter, system-ui, sans-serif';
          ctx.fillText(tickers[r], 16, y + cellH / 2);

          for (let c = 0; c < cols; c++) {
            const x = padLeft + c * (cellW + gap);
            const cell = data[r][c];

            drawRoundedRect(x, y, cellW, cellH, 8);
            ctx.fillStyle = valueToColor(cell.value);
            ctx.fill();

            // subtle overlay for better contrast
            ctx.fillStyle = 'rgba(0,0,0,0.10)';
            ctx.fill();

            // value text
            ctx.fillStyle = Math.abs(cell.value) > 2.3 ? '#fff' : '#071122';
            ctx.font = '12px Inter, system-ui, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText((cell.value >= 0 ? '+' : '') + cell.value.toFixed(2) + '%', x + cellW / 2, y + cellH / 2);
          }
        }

        // Highlight hovered cell
        if (state.hover.x != null && state.hover.y != null) {
          const { x, y } = state.hover;
          if (x >= 0 && x < cols && y >= 0 && y < rows) {
            const hx = padLeft + x * (cellW + gap);
            const hy = padTop + y * (cellH + gap);
            ctx.strokeStyle = 'rgba(255,255,255,0.9)';
            ctx.lineWidth = 2;
            drawRoundedRect(hx - 1, hy - 1, cellW + 2, cellH + 2, 9);
            ctx.stroke();
          }
        }
      }

      function updateTooltip(clientX, clientY) {
        const rect = wrap.getBoundingClientRect();
        const sx = (clientX - rect.left) * state.dpr;
        const sy = (clientY - rect.top) * state.dpr;
        const world = screenToWorld(sx, sy);

        const cellW = 72;
        const cellH = 34;
        const gap = 4;
        const padLeft = 120;
        const padTop = 34;

        const col = Math.floor((world.x - padLeft) / (cellW + gap));
        const row = Math.floor((world.y - padTop) / (cellH + gap));

        if (row >= 0 && row < rows && col >= 0 && col < cols) {
          const xIn = world.x - (padLeft + col * (cellW + gap));
          const yIn = world.y - (padTop + row * (cellH + gap));
          if (xIn >= 0 && xIn <= cellW && yIn >= 0 && yIn <= cellH) {
            const cell = data[row][col];
            state.hover.x = col;
            state.hover.y = row;

            tooltip.style.display = 'block';
            tooltip.style.left = `${clientX - rect.left}px`;
            tooltip.style.top = `${clientY - rect.top}px`;
            tooltip.innerHTML = `
              <div><strong>${cell.ticker}</strong> @ ${cell.time}</div>
              <div>Change: <strong style="color:${cell.value >= 0 ? '#58d68d' : '#ff6b6b'}">${cell.value >= 0 ? '+' : ''}${cell.value.toFixed(2)}%</strong></div>
              <div>Volume: ${cell.volume.toLocaleString()}</div>
            `;
            render();
            return;
          }
        }

        hideTooltip();
      }

      function hideTooltip() {
        state.hover.x = null;
        state.hover.y = null;
        tooltip.style.display = 'none';
        render();
      }

      wrap.addEventListener('pointerdown', (e) => {
        state.drag.active = true;
        state.drag.lastX = e.clientX;
        state.drag.lastY = e.clientY;
        canvas.setPointerCapture(e.pointerId);
      });

      wrap.addEventListener('pointermove', (e) => {
        if (state.drag.active) {
          const dx = (e.clientX - state.drag.lastX) * state.dpr;
          const dy = (e.clientY - state.drag.lastY) * state.dpr;
          state.view.offsetX += dx;
          state.view.offsetY += dy;
          state.drag.lastX = e.clientX;
          state.drag.lastY = e.clientY;
          render();
        } else {
          updateTooltip(e.clientX, e.clientY);
        }
      });

      wrap.addEventListener('pointerup', () => {
        state.drag.active = false;
      });

      wrap.addEventListener('pointerleave', () => {
        state.drag.active = false;
        hideTooltip();
      });

      wrap.addEventListener('wheel', (e) => {
        e.preventDefault();

        const rect = wrap.getBoundingClientRect();
        const mx = (e.clientX - rect.left) * state.dpr;
        const my = (e.clientY - rect.top) * state.dpr;

        const zoomFactor = Math.exp(-e.deltaY * 0.0015);
        const oldScale = state.view.scale;
        const newScale = clamp(oldScale * zoomFactor, 0.45, 3.5);

        const worldX = (mx - state.view.offsetX) / oldScale;
        const worldY = (my - state.view.offsetY) / oldScale;

        state.view.scale = newScale;
        state.view.offsetX = mx - worldX * newScale;
        state.view.offsetY = my - worldY * newScale;

        render();
      }, { passive: false });

      resetBtn.addEventListener('click', () => {
        state.view.scale = 1;
        state.view.offsetX = 0;
        state.view.offsetY = 0;
        render();
      });

      pauseBtn.addEventListener('click', () => {
        state.paused = !state.paused;
        pauseBtn.textContent = state.paused ? 'Resume' : 'Pause';
        statusEl.textContent = state.paused
          ? 'Streaming: paused'
          : 'Streaming: simulated real-time updates';
      });

      // Simulated real-time updates
      function streamingTick() {
        if (!state.paused) {
          for (let i = 0; i < 10; i++) {
            const r = Math.floor(Math.random() * rows);
            const c = Math.floor(Math.random() * cols);
            const cell = data[r][c];
            cell.value = clamp(cell.value + (Math.random() - 0.5) * 0.9, -6, 6);
            cell.volume = Math.max(100, Math.floor(cell.volume * (0.85 + Math.random() * 0.3)));
          }
          render();
        }
        requestAnimationFrame(() => setTimeout(streamingTick, 700));
      }

      // init
      resize();
      render();
      streamingTick();
    })();
  </script>
</body>
</html>
```

---

### How it works
- **Canvas rendering** is used for performance and smooth zoom/pan.
- The heatmap is a 2D grid of fake stock cells with values representing percent change.
- **Zoom** is centered on the cursor using wheel interpolation.
- **Pan** is done by dragging.
- Real-time updates are simulated by periodically mutating cell values/volume.

---

### If you want to connect real market data
Replace the simulated `streamingTick()` section with a WebSocket, SSE, or polling call to a backend endpoint, then update `data[r][c].value` from live quotes.

