        radial-gradient(circle at 20% 20%, rgba(77,163,255,0.06), transparent 30%),
        radial-gradient(circle at 80% 70%, rgba(110,255,190,0.05), transparent 28%),
        var(--bg);
      cursor: grab;
    }

