      background: rgba(255,255,255,0.02);
      border-top: 1px solid rgba(255,255,255,0.06);
    }

    .footer code {
      color: #b9d4ff;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Live Stock Heatmap</h1>
      <div class="badge">Market: <strong>Simulated real-time feed</strong></div>
      <div class="badge">Zoom: <strong>Mouse wheel / Trackpad</strong></div>
      <div class="badge">Pan: <strong>Drag</strong></div>
      <div class="spacer"></div>
      <div class="controls">
        <button id="resetView">Reset View</button>
        <button id="shuffleData">Re-randomize</button>
      </div>
    </div>

    <div class="canvas-wrap" id="wrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="footer">
      Hover a cell to inspect the stock. Click to pin via alert. 
      Real-time updates are simulated client-side; replace the generator with <code>WebSocket</code> or <code>fetch</code> polling for live market data.
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const wrap = document.getElementById("wrap");
    const tooltip = document.getElementById("tooltip");
    const resetViewBtn = document.getElementById("resetView");
    const shuffleBtn = document.getElementById("shuffleData");
    const ctx = canvas.getContext("2d");

    // ----- Data model -----
    const rows = 18;
    const cols = 32;
    let stocks = [];

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function generateStocks() {
      const baseNames = [
        "AAPL","MSFT","NVDA","AMZN","META","TSLA","GOOG","NFLX","AMD","INTC",
        "ORCL","IBM","CRM","UBER","SHOP","SNOW","SQ","BABA","PLTR","DIS"
      ];
      const names = [];
      for (let i = 0; i < rows * cols; i++) {
        names.push(baseNames[i % baseNames.length] + "-" + String(i).padStart(3, "0"));
      }

      stocks = names.map((symbol, i) => {
        const price = rand(12, 800);
        const changePct = rand(-8, 8);
        return {
          symbol,
          price,
          changePct,
          volume: Math.floor(rand(100_000, 5_000_000)),
          row: Math.floor(i / cols),
          col: i % cols
        };
      });
    }

    // ----- View transform -----
    let view = {
      scale: 1,
      offsetX: 30,
      offsetY: 20
    };

    let dragging = false;
    let dragStart = { x: 0, y: 0 };
    let offsetStart = { x: 0, y: 0 };

    // ----- Canvas sizing -----
    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = wrap.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      render();
    }

    window.addEventListener("resize", resizeCanvas);

    // ----- Color mapping -----
    function valueToColor(changePct) {
      // Negative -> red, Positive -> green
      const t = clamp((changePct + 10) / 20, 0, 1);
      const hue = 120 * t; // 0 red to 120 green
      const light = 38 + t * 18;
      return `hsl(${hue}, 82%, ${light}%)`;
    }

    function glowColor(changePct) {
      return changePct >= 0 ? "rgba(51, 255, 153, 0.18)" : "rgba(255, 75, 75, 0.18)";
    }

    // ----- Rendering -----
    function render() {
      const w = wrap.clientWidth;
      const h = wrap.clientHeight;
      ctx.clearRect(0, 0, w, h);

      const cellW = 130;
      const cellH = 78;
      const gap = 8;

      ctx.save();
      ctx.translate(view.offsetX, view.offsetY);
      ctx.scale(view.scale, view.scale);

      // Grid background
      const totalW = cols * (cellW + gap);
      const totalH = rows * (cellH + gap);

      // Draw cells
      for (const stock of stocks) {
        const x = stock.col * (cellW + gap);
        const y = stock.row * (cellH + gap);

        const fill = valueToColor(stock.changePct);
        const radius = 14;

        // Outer glow
        ctx.shadowColor = stock.changePct >= 0 ? "rgba(68,255,170,0.18)" : "rgba(255,80,80,0.18)";
        ctx.shadowBlur = 18;

        roundRect(ctx, x, y, cellW, cellH, radius);
        ctx.fillStyle = fill;
        ctx.fill();

        ctx.shadowBlur = 0;
        ctx.strokeStyle = "rgba(255,255,255,0.08)";
        ctx.lineWidth = 1;
        ctx.stroke();

        // Text
        ctx.fillStyle = "rgba(255,255,255,0.96)";
        ctx.font = "700 14px Inter, sans-serif";
        ctx.fillText(stock.symbol, x + 12, y + 23);

        ctx.font = "12px Inter, sans-serif";
        ctx.fillStyle = "rgba(255,255,255,0.9)";
        ctx.fillText(`$${stock.price.toFixed(2)}`, x + 12, y + 43);

        const ch = stock.changePct >= 0 ? `+${stock.changePct.toFixed(2)}%` : `${stock.changePct.toFixed(2)}%`;
        ctx.fillStyle = "rgba(255,255,255,0.95)";
        ctx.font = "700 13px Inter, sans-serif";
        ctx.fillText(ch, x + 12, y + 62);

        // tiny volume bar
        const barW = 52;
        const vol = clamp(stock.volume / 5_000_000, 0, 1);
        ctx.fillStyle = "rgba(255,255,255,0.14)";
        ctx.fillRect(x + cellW - 64, y + cellH - 16, barW, 5);
        ctx.fillStyle = stock.changePct >= 0 ? "rgba(110,255,190,0.92)" : "rgba(255,110,110,0.92)";
        ctx.fillRect(x + cellW - 64, y + cellH - 16, barW * vol, 5);
      }

      ctx.restore();
    }

    function roundRect(ctx, x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    // ----- Hit testing -----
    function screenToWorld(clientX, clientY) {
      const rect = wrap.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      return {
        x: (x - view.offsetX) / view.scale,
        y: (y - view.offsetY) / view.scale
      };
    }

    function getCellAt(clientX, clientY) {
      const world = screenToWorld(clientX, clientY);
      const cellW = 130;
      const cellH = 78;
      const gap = 8;
      const stepX = cellW + gap;
      const stepY = cellH + gap;

      const col = Math.floor(world.x / stepX);
      const row = Math.floor(world.y / stepY);

      if (col < 0 || col >= cols || row < 0 || row >= rows) return null;

      const stock = stocks.find(s => s.row === row && s.col === col);
      if (!stock) return null;

      const x = col * stepX;
      const y = row * stepY;
      if (world.x >= x && world.x <= x + cellW && world.y >= y && world.y <= y + cellH) {
        return { stock, x, y, cellW, cellH };
      }
      return null;
    }

    // ----- Tooltip -----
    function showTooltip(e, hit) {
      const { stock } = hit;
      tooltip.style.display = "block";
      tooltip.innerHTML = `
        <div><strong>${stock.symbol}</strong></div>
        <div>Price: $${stock.price.toFixed(2)}</div>
        <div>Change: ${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%</div>
        <div>Volume: ${stock.volume.toLocaleString()}</div>
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const rect = wrap.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.style.display = "none";
    }

    // ----- Interaction -----
    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      dragStart = { x: e.clientX, y: e.clientY };
      offsetStart = { x: view.offsetX, y: view.offsetY };
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      if (dragging) {
        view.offsetX = offsetStart.x + (e.clientX - dragStart.x);
        view.offsetY = offsetStart.y + (e.clientY - dragStart.y);
        render();
      }

      const hit = getCellAt(e.clientX, e.clientY);
      if (hit) {
        showTooltip(e, hit);
      } else {
        hideTooltip();
      }

      if (tooltip.style.display === "block") {
        moveTooltip(e);
      }
    });

    canvas.addEventListener("mouseleave", hideTooltip);

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = wrap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = clamp(view.scale * zoomFactor, 0.4, 3.5);

      // Zoom around cursor
      const worldX = (mouseX - view.offsetX) / view.scale;
      const worldY = (mouseY - view.offsetY) / view.scale;

      view.offsetX = mouseX - worldX * nextScale;
      view.offsetY = mouseY - worldY * nextScale;
      view.scale = nextScale;

      render();
    }, { passive: false });

    canvas.addEventListener("click", (e) => {
      const hit = getCellAt(e.clientX, e.clientY);
      if (hit) {
        const { stock } = hit;
        alert(
          `${stock.symbol}\n` +
          `Price: $${stock.price.toFixed(2)}\n` +
          `Change: ${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%\n` +
          `Volume: ${stock.volume.toLocaleString()}`
        );
      }
    });

    // ----- Simulated real-time updates -----
    function updatePrices() {
      for (const stock of stocks) {
        const drift = rand(-0.35, 0.35);
        const shock = Math.random() < 0.05 ? rand(-2.5, 2.5) : 0;
        const delta = drift + shock;

        stock.price = Math.max(0.01, stock.price + delta);
        stock.changePct = clamp(stock.changePct + rand(-0.18, 0.18) + shock * 0.18, -15, 15);
        stock.volume = Math.max(1000, Math.floor(stock.volume * rand(0.998, 1.004)));
      }
      render();
    }

    // Optional: hook this up to a real WebSocket later
    // const ws = new WebSocket("wss://your-feed");
    // ws.onmessage = (event) => {
    //   const data = JSON.parse(event.data);
    //   // update stocks here
    //   render();
    // };

    // ----- Controls -----
    resetViewBtn.addEventListener("click", () => {
      view = { scale: 1, offsetX: 30, offsetY: 20 };
      render();
    });

    shuffleBtn.addEventListener("click", () => {
      generateStocks();
      render();
    });

    // ----- Init -----
    generateStocks();
    resizeCanvas();
    render();

    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
```

