  <script>
    const tickers = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX",
      "AMD","INTC","ORCL","CRM","ADBE","QCOM","AVGO","CSCO",
      "SHOP","UBER","SNOW","SPOT","SQ","PYPL","BABA","PDD",
      "JPM","BAC","WFC","GS","MS","C","BRK.B","V",
      "MA","AXP","DIS","SONY","SBUX","NKE","COST","TGT"
    ];

    const grid = document.getElementById("grid");
    const canvas = document.getElementById("canvas");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const state = {
      scale: 1,
      x: 0,
      y: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      panStartX: 0,
      panStartY: 0,
      paused: false,
      data: []
    };

    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatPrice(p) {
      return `$${p.toFixed(2)}`;
    }

    function percent(v) {
      return `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`;
    }

    function generateData() {
      return tickers.map((symbol) => {
        const base = randomBetween(20, 1200);
        const changePct = randomBetween(-6, 6);
        return {
          symbol,
          price: base,
          prevPrice: base / (1 + changePct / 100),
          volume: Math.floor(randomBetween(500000, 50000000))
        };
      });
    }

    function updateDataWithTick() {
      state.data = state.data.map(stock => {
        const drift = randomBetween(-1.5, 1.5);
        const volatility = randomBetween(-0.8, 0.8);
        const nextPrice = Math.max(1, stock.price * (1 + (drift + volatility) / 100));

        return {
          ...stock,
          prevPrice: stock.price,
          price: nextPrice,
          volume: Math.max(1000, Math.floor(stock.volume * (1 + randomBetween(-0.03, 0.03))))
        };
      });

      render();
    }

    function getChangePct(stock) {
      return ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;
    }

    function colorForChange(changePct) {
      const c = clamp(changePct, -6, 6);
      const t = (c + 6) / 12;
      const red = { r: 220, g: 38, b: 38 };
      const yellow = { r: 245, g: 158, b: 11 };
      const green = { r: 34, g: 197, b: 94 };

      let a, b, mix;
      if (t < 0.5) {
        a = red; b = yellow; mix = t / 0.5;
      } else {
        a = yellow; b = green; mix = (t - 0.5) / 0.5;
      }

      const r = Math.round(a.r + (b.r - a.r) * mix);
      const g = Math.round(a.g + (b.g - a.g) * mix);
      const bl = Math.round(a.b + (b.b - a.b) * mix);
      return `rgb(${r} ${g} ${bl})`;
    }

    function textColorForBg(changePct) {
      return Math.abs(changePct) > 3.5 ? "white" : "white";
    }

    function render() {
      grid.innerHTML = "";

      state.data.forEach((stock, i) => {
        const changePct = getChangePct(stock);
        const cell = document.createElement("div");
        cell.className = "cell";
        cell.style.background = colorForChange(changePct);
        cell.style.color = textColorForBg(changePct);

        cell.dataset.symbol = stock.symbol;
        cell.dataset.price = stock.price.toFixed(2);
        cell.dataset.change = changePct.toFixed(2);
        cell.dataset.volume = stock.volume;

        cell.innerHTML = `
          <div class="ticker">
            <span>${stock.symbol}</span>
            <span>${changePct >= 0 ? "▲" : "▼"}</span>
          </div>
          <div class="price">${formatPrice(stock.price)}</div>
          <div class="change">${percent(changePct)}</div>
          <div class="sub">Vol: ${stock.volume.toLocaleString()}</div>
        `;

        cell.addEventListener("mousemove", (e) => {
          tooltip.style.display = "block";
          tooltip.style.left = `${e.clientX + 14}px`;
          tooltip.style.top = `${e.clientY + 14}px`;
          tooltip.innerHTML = `
            <strong>${stock.symbol}</strong>
            Price: ${formatPrice(stock.price)}<br/>
            Change: ${percent(changePct)}<br/>
            Volume: ${stock.volume.toLocaleString()}
          `;
        });

        cell.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        cell.addEventListener("click", () => {
          alert(
            `${stock.symbol}\n\nPrice: ${formatPrice(stock.price)}\nChange: ${percent(changePct)}\nVolume: ${stock.volume.toLocaleString()}`
          );
        });

        grid.appendChild(cell);
      });

      applyTransform();
    }

    function applyTransform() {
      canvas.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
    }

    function resetView() {
      state.scale = 1;
      state.x = 0;
      state.y = 0;
      applyTransform();
    }

    viewport.addEventListener("mousedown", (e) => {
      state.dragging = true;
      viewport.classList.add("dragging");
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.panStartX = state.x;
      state.panStartY = state.y;
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.dragging) return;
      state.x = state.panStartX + (e.clientX - state.dragStartX);
      state.y = state.panStartY + (e.clientY - state.dragStartY);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const prevScale = state.scale;
      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      state.scale = clamp(state.scale * zoomFactor, 0.5, 3);

      const worldX = (mouseX - state.x) / prevScale;
      const worldY = (mouseY - state.y) / prevScale;

      state.x = mouseX - worldX * state.scale;
      state.y = mouseY - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    document.getElementById("resetBtn").addEventListener("click", resetView);

    document.getElementById("toggleBtn").addEventListener("click", (e) => {
      state.paused = !state.paused;
      e.target.textContent = state.paused ? "Resume" : "Pause";
      statusEl.textContent = state.paused ? "Paused" : "Live";
    });

    // Initialize data
    state.data = generateData();
    render();

    // Real-time update loop
    setInterval(() => {
      if (!state.paused) updateDataWithTick();
    }, 1200);

    // Keep tooltip aligned if window scroll/resize changes layout
    window.addEventListener("resize", () => applyTransform());
  </script>
</body>
