  <script>
    (() => {
      const canvas = document.getElementById("heatmap");
      const wrap = document.getElementById("canvasWrap");
      const tooltip = document.getElementById("tooltip");
      const resetBtn = document.getElementById("resetBtn");
      const toggleStreamBtn = document.getElementById("toggleStreamBtn");
      const ctx = canvas.getContext("2d");

      const state = {
        dpr: Math.max(1, window.devicePixelRatio || 1),
        width: 0,
        height: 0,
        cols: 28,
        rows: 18,
        padding: 24,
        cellGap: 4,
        zoom: 1,
        panX: 0,
        panY: 0,
        dragging: false,
        lastX: 0,
        lastY: 0,
        streamRunning: true,
        hoverCell: null,
        cells: [],
        lastTick: performance.now()
      };

      function rand(min, max) {
        return min + Math.random() * (max - min);
      }

      function clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      function generateCells() {
        const symbols = [
          "AAPL","MSFT","GOOGL","AMZN","META","TSLA","NVDA","AMD","INTC","NFLX",
          "JPM","V","MA","BAC","C","GS","WMT","COST","DIS","PFE",
          "KO","PEP","XOM","CVX","T","VZ","UNH","HD","BA","SBUX",
          "IBM","ORCL","ADBE","CRM","QCOM","AVGO","NKE","MCD","LLY","MRK",
          "CSCO","PYPL","SHOP","UBER","SQ","SNOW","PLTR","SPOT","NOW","PANW"
        ];

        const total = state.cols * state.rows;
        state.cells = Array.from({ length: total }, (_, i) => {
          const base = rand(20, 500);
          const symbol = symbols[i % symbols.length];
          return {
            symbol,
            price: base,
            prevPrice: base,
            volume: Math.floor(rand(100000, 50000000)),
            changePct: 0
          };
        });
      }

      function resize() {
        const rect = wrap.getBoundingClientRect();
        state.width = rect.width;
        state.height = rect.height;
        canvas.width = Math.floor(rect.width * state.dpr);
        canvas.height = Math.floor(rect.height * state.dpr);
        canvas.style.width = rect.width + "px";
        canvas.style.height = rect.height + "px";
        ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
        render();
      }

      function resetView() {
        state.zoom = 1;
        state.panX = 0;
        state.panY = 0;
        render();
      }

      function colorForChange(changePct) {
        const t = clamp((changePct + 10) / 20, 0, 1);
        const r1 = [214, 64, 69];
        const r2 = [243, 244, 246];
        const r3 = [45, 212, 191];

        let c1, c2, tt;
        if (t < 0.5) {
          c1 = r1;
          c2 = r2;
          tt = t / 0.5;
        } else {
          c1 = r2;
          c2 = r3;
          tt = (t - 0.5) / 0.5;
        }

        const r = Math.round(c1[0] + (c2[0] - c1[0]) * tt);
        const g = Math.round(c1[1] + (c2[1] - c1[1]) * tt);
        const b = Math.round(c1[2] + (c2[2] - c1[2]) * tt);
        return `rgb(${r},${g},${b})`;
      }

      function updatePrices() {
        if (!state.streamRunning) return;

        for (const cell of state.cells) {
          cell.prevPrice = cell.price;
          const drift = rand(-0.012, 0.012);
          cell.price = Math.max(0.5, cell.price * (1 + drift));
          cell.changePct = ((cell.price - cell.prevPrice) / cell.prevPrice) * 100;
          cell.volume = Math.max(0, Math.floor(cell.volume * (1 + rand(-0.03, 0.03))));
        }

        render();
      }

      function worldToScreen(x, y, cellW, cellH) {
        return {
          x: (x * cellW + state.panX) * state.zoom,
          y: (y * cellH + state.panY) * state.zoom
        };
      }

      function screenToWorld(px, py, cellW, cellH) {
        return {
          x: (px / state.zoom - state.panX) / cellW,
          y: (py / state.zoom - state.panY) / cellH
        };
      }

      function render() {
        const w = state.width;
        const h = state.height;
        ctx.clearRect(0, 0, w, h);

        ctx.fillStyle = "#0b1020";
        ctx.fillRect(0, 0, w, h);

        const cols = state.cols;
        const rows = state.rows;
        const gap = state.cellGap;
        const ox = state.padding;
        const oy = state.padding;

        const innerW = w - ox * 2;
        const innerH = h - oy * 2;
        const cellW = (innerW - (cols - 1) * gap) / cols;
        const cellH = (innerH - (rows - 1) * gap) / rows;

        ctx.save();
        ctx.translate(0, 0);
        ctx.scale(state.zoom, state.zoom);
        ctx.translate(state.panX, state.panY);

        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const idx = r * cols + c;
            const cell = state.cells[idx];
            if (!cell) continue;

            const x = ox + c * (cellW + gap);
            const y = oy + r * (cellH + gap);

            const fill = colorForChange(cell.changePct);
            ctx.fillStyle = fill;
            roundRect(ctx, x, y, cellW, cellH, 8);
            ctx.fill();

            if (state.hoverCell && state.hoverCell.idx === idx) {
              ctx.strokeStyle = "#4cc9f0";
              ctx.lineWidth = 2;
              roundRect(ctx, x + 1, y + 1, cellW - 2, cellH - 2, 7);
              ctx.stroke();
            }

            ctx.fillStyle = cell.changePct >= 0 ? "#07111a" : "#ffffff";
            ctx.font = `600 ${Math.max(10, Math.min(14, cellW * 0.18))}px system-ui, sans-serif`;
            ctx.fillText(cell.symbol, x + 10, y + 18);

            ctx.font = `500 ${Math.max(9, Math.min(12, cellW * 0.15))}px system-ui, sans-serif`;
            ctx.fillText(`$${cell.price.toFixed(2)}`, x + 10, y + cellH - 12);

            const pct = cell.changePct >= 0 ? `+${cell.changePct.toFixed(2)}%` : `${cell.changePct.toFixed(2)}%`;
            ctx.fillText(pct, x + cellW - 10 - ctx.measureText(pct).width, y + cellH - 12);
          }
        }

        ctx.restore();
      }

      function roundRect(ctx, x, y, w, h, r) {
        const radius = Math.min(r, w / 2, h / 2);
        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.arcTo(x + w, y, x + w, y + h, radius);
        ctx.arcTo(x + w, y + h, x, y + h, radius);
        ctx.arcTo(x, y + h, x, y, radius);
        ctx.arcTo(x, y, x + w, y, radius);
        ctx.closePath();
      }

      function getCellAt(clientX, clientY) {
        const rect = wrap.getBoundingClientRect();
        const x = clientX - rect.left;
        const y = clientY - rect.top;

        const cols = state.cols;
        const rows = state.rows;
        const gap = state.cellGap;
        const ox = state.padding;
        const oy = state.padding;
        const innerW = state.width - ox * 2;
        const innerH = state.height - oy * 2;
        const cellW = (innerW - (cols - 1) * gap) / cols;
        const cellH = (innerH - (rows - 1) * gap) / rows;

        const wx = (x / state.zoom - state.panX);
        const wy = (y / state.zoom - state.panY);

        if (wx < ox || wy < oy) return null;

        const c = Math.floor((wx - ox) / (cellW + gap));
        const r = Math.floor((wy - oy) / (cellH + gap));
        if (c < 0 || c >= cols || r < 0 || r >= rows) return null;

        const localX = (wx - ox) - c * (cellW + gap);
        const localY = (wy - oy) - r * (cellH + gap);
        if (localX < 0 || localY < 0 || localX > cellW || localY > cellH) return null;

        const idx = r * cols + c;
        return { idx, cell: state.cells[idx], x, y };
      }

      wrap.addEventListener("wheel", (e) => {
        e.preventDefault();

        const rect = wrap.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;

        const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
        const nextZoom = clamp(state.zoom * zoomFactor, 0.6, 4);

        const worldX = mx / state.zoom - state.panX;
        const worldY = my / state.zoom - state.panY;

        state.panX = mx / nextZoom - worldX;
        state.panY = my / nextZoom - worldY;
        state.zoom = nextZoom;

        render();
      }, { passive: false });

      wrap.addEventListener("pointerdown", (e) => {
        state.dragging = true;
        state.lastX = e.clientX;
        state.lastY = e.clientY;
        wrap.setPointerCapture(e.pointerId);
      });

      wrap.addEventListener("pointermove", (e) => {
        const hit = getCellAt(e.clientX, e.clientY);
        if (hit) {
          state.hoverCell = { idx: hit.idx };
          const c = hit.cell;
          tooltip.style.display = "block";
          tooltip.style.left = `${hit.x}px`;
          tooltip.style.top = `${hit.y}px`;
          tooltip.innerHTML = `
            <strong>${c.symbol}</strong><br/>
            Price: $${c.price.toFixed(2)}<br/>
            Change: ${c.changePct >= 0 ? "+" : ""}${c.changePct.toFixed(2)}%<br/>
            Volume: ${c.volume.toLocaleString()}
          `;
        } else {
          state.hoverCell = null;
          tooltip.style.display = "none";
        }

        if (!state.dragging) {
          render();
          return;
        }

        const dx = e.clientX - state.lastX;
        const dy = e.clientY - state.lastY;
        state.lastX = e.clientX;
        state.lastY = e.clientY;
        state.panX += dx / state.zoom;
        state.panY += dy / state.zoom;
        render();
      });

      wrap.addEventListener("pointerup", () => {
        state.dragging = false;
      });

      wrap.addEventListener("pointercancel", () => {
        state.dragging = false;
      });

      resetBtn.addEventListener("click", resetView);

      toggleStreamBtn.addEventListener("click", () => {
        state.streamRunning = !state.streamRunning;
        toggleStreamBtn.textContent = state.streamRunning ? "Pause Updates" : "Resume Updates";
      });

      window.addEventListener("resize", resize);

      generateCells();
      resize();
      setInterval(updatePrices, 800);
    })();
  </script>
</body>
</html>
```

### How it works
- Each stock is rendered as a colored cell.
- Color shifts from **red → neutral → green** based on price change.
- Mouse wheel zooms toward the pointer.
- Dragging pans the view.
- A tooltip shows live price and percent change.
- A timer updates prices every 800ms.

### Notes
- This uses **simulated data**. To connect real-time data, replace `updatePrices()` with a WebSocket or API polling layer.
- For large datasets, consider:
  - virtualization
  - WebGL rendering
  - batching updates
  - requestAnimationFrame rendering

