<body>
  <div class="app">
    <div class="toolbar">
      <div class="title">Stock Heatmap</div>
      <div class="chip" id="marketStatus">Market: Live updates simulated</div>
      <div class="spacer"></div>
      <button class="btn" id="resetBtn">Reset View</button>
      <button class="btn" id="pauseBtn">Pause</button>
    </div>

    <div class="viewport" id="viewport">
      <div class="scene" id="scene">
        <div class="grid" id="grid"></div>
      </div>

      <div class="hint">
        Wheel: zoom • Drag: pan • Click tile: pin details
      </div>

      <div class="details" id="details">
        <h3 id="dSymbol">—</h3>
        <div class="row"><span>Sector</span><strong id="dSector">—</strong></div>
        <div class="row"><span>Price</span><strong id="dPrice">—</strong></div>
        <div class="row"><span>Change</span><strong id="dChange">—</strong></div>
        <div class="row"><span>Volume</span><strong id="dVolume">—</strong></div>
        <div class="row"><span>Updated</span><strong id="dUpdated">—</strong></div>
      </div>
    </div>
  </div>

  <div class="tooltip" id="tooltip"></div>

  <script>
    const symbols = [
      ["AAPL","Tech"],["MSFT","Tech"],["NVDA","Tech"],["AMZN","Consumer"],["GOOGL","Tech"],
      ["META","Tech"],["TSLA","Automotive"],["JPM","Financial"],["V","Financial"],["MA","Financial"],
      ["XOM","Energy"],["CVX","Energy"],["LLY","Healthcare"],["UNH","Healthcare"],["AVGO","Tech"],
      ["ORCL","Software"],["AMD","Tech"],["NFLX","Entertainment"],["WMT","Retail"],["COST","Retail"],
      ["KO","Consumer"],["PEP","Consumer"],["BAC","Financial"],["GS","Financial"],["NKE","Retail"],
      ["DIS","Entertainment"],["INTC","Tech"],["CSCO","Tech"],["QCOM","Tech"],["TM","Automotive"]
    ];

    const grid = document.getElementById("grid");
    const scene = document.getElementById("scene");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const details = document.getElementById("details");

    const dSymbol = document.getElementById("dSymbol");
    const dSector = document.getElementById("dSector");
    const dPrice = document.getElementById("dPrice");
    const dChange = document.getElementById("dChange");
    const dVolume = document.getElementById("dVolume");
    const dUpdated = document.getElementById("dUpdated");

    const state = {
      scale: 1,
      tx: 0,
      ty: 0,
      dragging: false,
      lastX: 0,
      lastY: 0,
      paused: false,
      pinned: null,
      tiles: [],
      data: new Map()
    };

    function fmtPrice(p) { return `$${p.toFixed(2)}`; }
    function fmtPct(v) { return `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`; }
    function clamp(n, min, max) { return Math.max(min, Math.min(max, n)); }

    function colorClass(changePct) {
      if (changePct > 0.3) return "pos";
      if (changePct < -0.3) return "neg";
      return "flat";
    }

    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    // Create tiles
    grid.style.gridTemplateColumns = "repeat(5, 160px)";
    symbols.forEach(([symbol, sector]) => {
      const base = randomBetween(40, 400);
      const changePct = randomBetween(-3.5, 3.5);
      const volume = Math.floor(randomBetween(1_000_000, 120_000_000));

      const obj = {
        symbol,
        sector,
        price: base,
        prevClose: base / (1 + changePct / 100),
        changePct,
        volume,
        lastUpdated: new Date()
      };
      state.data.set(symbol, obj);

      const tile = document.createElement("div");
      tile.className = `tile ${colorClass(changePct)}`;
      tile.innerHTML = `
        <div class="spark"></div>
        <div class="name">${symbol}</div>
        <div class="sector">${sector}</div>
        <div class="price">${fmtPrice(obj.price)}</div>
        <div class="change">${fmtPct(changePct)}</div>
      `;

      tile.addEventListener("pointerenter", (e) => showTooltip(e, obj));
      tile.addEventListener("pointermove", (e) => moveTooltip(e, obj));
      tile.addEventListener("pointerleave", hideTooltip);
      tile.addEventListener("click", () => pinDetails(obj));

      grid.appendChild(tile);
      state.tiles.push({ el: tile, symbol });
    });

    function updateTile(symbol) {
      const obj = state.data.get(symbol);
      const tile = state.tiles.find(t => t.symbol === symbol).el;
      tile.className = `tile ${colorClass(obj.changePct)}`;
      tile.querySelector(".price").textContent = fmtPrice(obj.price);
      tile.querySelector(".change").textContent = fmtPct(obj.changePct);

      // subtle intensity with absolute percent change
      const intensity = clamp(Math.abs(obj.changePct) / 8, 0.08, 0.42);
      tile.style.boxShadow = `0 12px 20px rgba(0,0,0,0.18), inset 0 0 0 1px rgba(255,255,255,${intensity * 0.25})`;

      if (state.pinned === symbol) pinDetails(obj);
    }

    function tickUpdates() {
      if (state.paused) return;

      symbols.forEach(([symbol]) => {
        const obj = state.data.get(symbol);

        const drift = randomBetween(-0.9, 0.9);
        const shock = randomBetween(-0.35, 0.35);
        const pctMove = (drift + shock) * 0.12;

        obj.price = Math.max(1, obj.price * (1 + pctMove / 100));
        obj.changePct = ((obj.price - obj.prevClose) / obj.prevClose) * 100;
        obj.volume += Math.floor(randomBetween(5_000, 150_000));
        obj.lastUpdated = new Date();

        updateTile(symbol);
      });
    }

    setInterval(tickUpdates, 900);

    function showTooltip(e, obj) {
      tooltip.style.display = "block";
      tooltip.innerHTML = `
        <strong>${obj.symbol}</strong> · ${obj.sector}<br/>
        Price: ${fmtPrice(obj.price)}<br/>
        Change: ${fmtPct(obj.changePct)}<br/>
        Volume: ${obj.volume.toLocaleString()}
      `;
      moveTooltip(e, obj);
    }

    function moveTooltip(e) {
      const pad = 14;
      tooltip.style.left = `${clamp(e.clientX + 14, pad, window.innerWidth - 300)}px`;
      tooltip.style.top = `${clamp(e.clientY + 14, pad, window.innerHeight - 120)}px`;
    }

    function hideTooltip() {
      tooltip.style.display = "none";
    }

    function pinDetails(obj) {
      state.pinned = obj.symbol;
      dSymbol.textContent = obj.symbol;
      dSector.textContent = obj.sector;
      dPrice.textContent = fmtPrice(obj.price);
      dChange.textContent = fmtPct(obj.changePct);
      dVolume.textContent = obj.volume.toLocaleString();
      dUpdated.textContent = obj.lastUpdated.toLocaleTimeString();
    }

    pinDetails(state.data.get("AAPL"));

    // Zoom and pan
    function applyTransform() {
      scene.style.transform = `translate(${state.tx}px, ${state.ty}px) scale(${state.scale})`;
    }

    viewport.addEventListener("pointerdown", (e) => {
      if (e.target.closest(".tile")) return;
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener("pointermove", (e) => {
      if (!state.dragging) return;
      const dx = e.clientX - state.lastX;
      const dy = e.clientY - state.lastY;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      state.tx += dx;
      state.ty += dy;
      applyTransform();
    });

    viewport.addEventListener("pointerup", (e) => {
      state.dragging = false;
      try { viewport.releasePointerCapture(e.pointerId); } catch {}
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const prevScale = state.scale;
      const zoom = Math.exp(-e.deltaY * 0.001);
      state.scale = clamp(state.scale * zoom, 0.45, 3.0);

      // Zoom toward cursor
      const worldX = (mouseX - state.tx) / prevScale;
      const worldY = (mouseY - state.ty) / prevScale;
      state.tx = mouseX - worldX * state.scale;
      state.ty = mouseY - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    document.getElementById("resetBtn").addEventListener("click", () => {
      state.scale = 1;
      state.tx = 0;
      state.ty = 0;
      applyTransform();
    });

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      state.paused = !state.paused;
      e.target.textContent = state.paused ? "Resume" : "Pause";
      document.getElementById("marketStatus").textContent =
        state.paused ? "Market: Paused" : "Market: Live updates simulated";
    });

    applyTransform();
  </script>
</body>
</html>
