      transform: translate(12px, 12px);
      background: rgba(10, 15, 30, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      color: white;
      padding: 10px 12px;
      font-size: 12px;
      border-radius: 10px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.35);
      opacity: 0;
      transition: opacity 0.08s linear;
      white-space: nowrap;
      z-index: 5;
    }

    .tooltip strong {
      display: block;
      font-size: 13px;
      margin-bottom: 4px;
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 10px;
      min-width: 260px;
    }

    .bar {
      height: 10px;
      flex: 1;
      border-radius: 999px;
      background: linear-gradient(90deg, #d73027, #fee08b, #1a9850);
      border: 1px solid rgba(255,255,255,0.10);
    }

    .small {
      font-size: 12px;
      color: var(--muted);
    }
  </style>
</head>
<body>
<div id="app">
  <header>
    <div class="title">Interactive Stock Price Heatmap</div>
    <div class="controls">
      <div class="chip">Wheel: zoom</div>
      <div class="chip">Drag: pan</div>
      <div class="chip">Hover: details</div>
      <div class="chip">Click: select</div>
      <div class="legend">
        <span class="small">Loss</span>
        <div class="bar"></div>
        <span class="small">Gain</span>
      </div>
    </div>
  </header>

  <div id="canvasWrap">
    <canvas id="heatmap"></canvas>
    <div id="tooltip" class="tooltip"></div>
  </div>
</div>

<script>
(() => {
  const canvas = document.getElementById('heatmap');
  const wrap = document.getElementById('canvasWrap');
  const tooltip = document.getElementById('tooltip');
  const ctx = canvas.getContext('2d');

  // ----- Data model -----
  const rows = 12;
  const cols = 36;

  const stocks = Array.from({ length: rows }, (_, i) => ({
    symbol: `STK${String(i + 1).padStart(2, '0')}`,
    sector: ['Tech', 'Finance', 'Energy', 'Retail'][i % 4],
    base: 50 + Math.random() * 150,
    price: 50 + Math.random() * 150,
    changePct: 0
  }));

  const cells = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      cells.push({
        row: r,
        col: c,
        price: 50 + Math.random() * 200,
        changePct: (Math.random() - 0.5) * 10,
        volume: Math.floor(50000 + Math.random() * 950000),
        selected: false
      });
    }
  }

  // ----- View transform -----
  let DPR = Math.max(1, window.devicePixelRatio || 1);
  let view = {
    scale: 1,
    offsetX: 40,
    offsetY: 40
  };

  let dragging = false;
  let dragStart = null;
  let lastPointer = null;

  let hovered = null;
  let selected = null;

  // ----- Resize -----
  function resize() {
    const rect = wrap.getBoundingClientRect();
    canvas.width = Math.floor(rect.width * DPR);
    canvas.height = Math.floor(rect.height * DPR);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    render();
  }
  window.addEventListener('resize', resize);

  // ----- Utility -----
  function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
  }

  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  function colorForChange(changePct) {
    const t = clamp((changePct + 10) / 20, 0, 1); // map [-10,10] -> [0,1]
    // red -> yellow -> green
    let r, g, b;
    if (t < 0.5) {
      const u = t / 0.5;
      r = lerp(215, 254, u);
      g = lerp(48, 224, u);
      b = lerp(39, 139, u);
    } else {
      const u = (t - 0.5) / 0.5;
      r = lerp(254, 26, u);
      g = lerp(224, 152, u);
      b = lerp(139, 80, u);
    }
    return `rgb(${r|0}, ${g|0}, ${b|0})`;
  }

  function worldToScreen(x, y) {
    return {
      x: x * view.scale + view.offsetX,
      y: y * view.scale + view.offsetY
    };
  }

  function screenToWorld(x, y) {
    return {
      x: (x - view.offsetX) / view.scale,
      y: (y - view.offsetY) / view.scale
    };
  }

  // ----- Interaction -----
  canvas.addEventListener('mousedown', (e) => {
    dragging = true;
    canvas.classList.add('dragging');
    dragStart = { x: e.clientX, y: e.clientY, ox: view.offsetX, oy: view.offsetY };
  });

  window.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const sx = e.clientX - rect.left;
    const sy = e.clientY - rect.top;

    if (dragging && dragStart) {
      const dx = e.clientX - dragStart.x;
      const dy = e.clientY - dragStart.y;
      view.offsetX = dragStart.ox + dx;
      view.offsetY = dragStart.oy + dy;
      render();
      return;
    }

    lastPointer = { x: sx, y: sy };
    hovered = pickCell(sx, sy);
    updateTooltip(e.clientX, e.clientY);
    render();
  });

  window.addEventListener('mouseup', () => {
    dragging = false;
    canvas.classList.remove('dragging');
    dragStart = null;
  });

  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();

    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    const zoomFactor = Math.exp(-e.deltaY * 0.0015);
    const newScale = clamp(view.scale * zoomFactor, 0.4, 8);

    // zoom around pointer
    const before = screenToWorld(mx, my);
    view.scale = newScale;
    const after = screenToWorld(mx, my);

    view.offsetX += (after.x - before.x) * view.scale;
    view.offsetY += (after.y - before.y) * view.scale;

    render();
  }, { passive: false });

  canvas.addEventListener('click', () => {
    if (hovered) {
      selected = hovered;
      render();
      console.log('Selected cell:', selected);
    }
  });

  function pickCell(sx, sy) {
    const cellSize = 32;
    const gap = 3;

    const world = screenToWorld(sx, sy);
    const x = world.x;
    const y = world.y;

    for (const cell of cells) {
      const wx = cell.col * (cellSize + gap);
      const wy = cell.row * (cellSize + gap);
      if (x >= wx && x <= wx + cellSize && y >= wy && y <= wy + cellSize) {
        return cell;
      }
    }
    return null;
  }

  function updateTooltip(clientX, clientY) {
    if (!hovered) {
      tooltip.style.opacity = '0';
      return;
    }

    const stock = stocks[hovered.row];
    tooltip.style.left = clientX + 'px';
    tooltip.style.top = clientY + 'px';
    tooltip.innerHTML = `
      <strong>${stock.symbol}</strong>
      Sector: ${stock.sector}<br/>
      Price: $${hovered.price.toFixed(2)}<br/>
      Change: ${hovered.changePct.toFixed(2)}%<br/>
      Volume: ${hovered.volume.toLocaleString()}
    `;
    tooltip.style.opacity = '1';
  }

  // ----- Simulation / real-time updates -----
  function tick() {
    for (const cell of cells) {
      const drift = (Math.random() - 0.5) * 1.2;
      cell.changePct = clamp(cell.changePct + drift, -12, 12);

      const delta = cell.price * (Math.random() - 0.5) * 0.01;
      cell.price = Math.max(1, cell.price + delta);
      cell.volume = Math.max(0, cell.volume + Math.floor((Math.random() - 0.5) * 20000));
    }

    for (const s of stocks) {
      const delta = (Math.random() - 0.5) * 2.0;
      s.price = Math.max(1, s.price + delta);
      s.changePct = ((s.price - s.base) / s.base) * 100;
    }

    render();
  }

  setInterval(tick, 1200);

  // ----- Rendering -----
  function render() {
    const rect = wrap.getBoundingClientRect();
    const w = rect.width;
    const h = rect.height;

    ctx.clearRect(0, 0, w, h);

    // background
    const grd = ctx.createLinearGradient(0, 0, 0, h);
    grd.addColorStop(0, '#0b1020');
    grd.addColorStop(1, '#08101b');
    ctx.fillStyle = grd;
    ctx.fillRect(0, 0, w, h);

    // visible grid
    const cellSize = 32;
    const gap = 3;
    const totalW = cols * (cellSize + gap) - gap;
    const totalH = rows * (cellSize + gap) - gap;

    // transformed drawing
    ctx.save();
    ctx.translate(view.offsetX, view.offsetY);
    ctx.scale(view.scale, view.scale);

    // grid cells
    for (const cell of cells) {
      const x = cell.col * (cellSize + gap);
      const y = cell.row * (cellSize + gap);

      // cell fill
      ctx.fillStyle = colorForChange(cell.changePct);
      roundRect(ctx, x, y, cellSize, cellSize, 6);
      ctx.fill();

      // subtle outline
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.lineWidth = 1 / view.scale;
      ctx.stroke();

      // selection / hover highlight
      if (selected === cell) {
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2 / view.scale;
        roundRect(ctx, x - 1, y - 1, cellSize + 2, cellSize + 2, 7);
        ctx.stroke();
      } else if (hovered === cell) {
        ctx.strokeStyle = '#4da3ff';
        ctx.lineWidth = 2 / view.scale;
        roundRect(ctx, x - 1, y - 1, cellSize + 2, cellSize + 2, 7);
        ctx.stroke();
      }

      // label
      if (view.scale >= 1.0) {
        ctx.fillStyle = 'rgba(255,255,255,0.95)';
        ctx.font = `${10 / view.scale}px sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(stocks[cell.row].symbol.slice(-2), x + cellSize / 2, y + cellSize / 2);
      }
    }

    // draw row labels
    ctx.fillStyle = 'rgba(215, 225, 255, 0.85)';
    ctx.font = `12px sans-serif`;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    for (let r = 0; r < rows; r++) {
      const y = r * (cellSize + gap) + cellSize / 2;
      ctx.fillText(stocks[r].symbol, totalW + 12, y);
    }

    ctx.restore();

    // status
    ctx.fillStyle = 'rgba(143, 163, 209, 0.9)';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.fillText(`Zoom: ${view.scale.toFixed(2)}x`, 14, 14);
  }

  function roundRect(ctx, x, y, width, height, radius) {
    const r = Math.min(radius, width / 2, height / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + width, y, x + width, y + height, r);
    ctx.arcTo(x + width, y + height, x, y + height, r);
    ctx.arcTo(x, y + height, x, y, r);
    ctx.arcTo(x, y, x + width, y, r);
    ctx.closePath();
  }

  // initial setup
  resize();
  render();
})();
</script>
</body>
</html>
```

## Notes
- This uses **simulated real-time data** in `tick()`. Replace that with a WebSocket or SSE feed for actual market data.
- The layout is a grid of stock cells; each cell changes color based on percent change.
- Zoom/pan are handled via canvas transforms and pointer events.

