</head>
<body>
<div class="app">
  <div class="toolbar">
    <div class="title">Stock Heatmap</div>
    <div class="meta">
      <span id="statusDot" class="status-dot"></span>
      <span id="statusText">Connecting...</span>
    </div>

    <div class="group">
      <button id="zoomIn">Zoom +</button>
      <button id="zoomOut">Zoom −</button>
