    <div class="group meta">
      <span>Scale: <strong id="scaleLabel">1.00x</strong></span>
      <span>Visible: <strong id="visibleLabel">0</strong></span>
    </div>

    <div class="group meta">
      <span>Realtime: <strong>ON</strong></span>
    </div>
  </div>

  <div id="viewport" class="viewport">
    <div id="world" class="world">
      <div id="grid" class="grid"></div>
    </div>
    <div class="hint">Drag to pan • Mouse wheel / buttons to zoom • Hover for details • Click to lock selection</div>
  </div>
