<div id="tooltip" class="tooltip"></div>

<script>
(() => {
  const viewport = document.getElementById('viewport');
  const world = document.getElementById('world');
  const grid = document.getElementById('grid');
  const tooltip = document.getElementById('tooltip');
  const statusDot = document.getElementById('statusDot');
  const statusText = document.getElementById('statusText');
  const scaleLabel = document.getElementById('scaleLabel');
  const visibleLabel = document.getElementById('visibleLabel');

  const zoomInBtn = document.getElementById('zoomIn');
  const zoomOutBtn = document.getElementById('zoomOut');
  const resetBtn = document.getElementById('reset');

  const rows = 80;
  const cols = 50;
  const cellW = 84;
  const cellH = 56;

  let scale = 1;
  let panX = 24;
  let panY = 24;
  let dragging = false;
  let dragStart = null;
  let selectedId = null;
  let hoverId = null;

  const stocks = [];
  const byId = new Map();

  function rand(min, max) { return min + Math.random() * (max - min); }
  function pick(arr) { return arr[(Math.random() * arr.length) | 0]; }

  const sectors = ['TECH', 'FIN', 'HEALTH', 'ENERGY', 'INDUSTRIAL', 'RETAIL', 'AUTO', 'MEDIA'];
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';

  function makeSymbol(i) {
    const a = letters[i % 26];
    const b = letters[(i * 7) % 26];
    const c = letters[(i * 13) % 26];
    return `${a}${b}${c}${(i % 10)}`;
  }

  function initData() {
    const count = rows * cols;
    for (let i = 0; i < count; i++) {
      const price = rand(8, 920);
      const prev = price * rand(0.97, 1.03);
      const pct = ((price - prev) / prev) * 100;
      const stock = {
        id: i,
        symbol: makeSymbol(i),
        sector: pick(sectors),
        price,
        prevClose: prev,
        pct,
        volume: Math.floor(rand(1e5, 2e7)),
        high: price * rand(1.01, 1.03),
        low: price * rand(0.97, 0.99),
        updatedAt: Date.now()
      };
      stocks.push(stock);
      byId.set(i, stock);
    }
  }

  function pctToColor(pct) {
    const clamp = Math.max(-8, Math.min(8, pct));
    const abs = Math.abs(clamp) / 8;
    const intensity = 28 + abs * 72;
    if (clamp > 0) {
      return `hsl(158, 80%, ${intensity}%)`;
    } else if (clamp < 0) {
      return `hsl(352, 85%, ${intensity}%)`;
    }
    return `hsl(225, 16%, ${intensity}%)`;
  }

  function buildGrid() {
    grid.style.gridTemplateColumns = `repeat(${cols}, ${cellW}px)`;
    grid.style.gridAutoRows = `${cellH}px`;
    grid.style.width = `${cols * cellW + 2}px`;
    grid.style.height = `${rows * cellH + 2}px`;

    const frag = document.createDocumentFragment();
    for (const s of stocks) {
      const el = document.createElement('div');
      el.className = 'cell';
      el.dataset.id = s.id;
      el.innerHTML = `
        <div class="sym">${s.symbol}</div>
        <div class="px"></div>
        <div class="chg"></div>
      `;
      frag.appendChild(el);
    }
    grid.appendChild(frag);
  }

  function renderCells() {
    const threshold = 0.22;
    let visible = 0;

    const vpRect = viewport.getBoundingClientRect();
    const left = -panX / scale;
    const top = -panY / scale;
    const right = (vpRect.width - panX) / scale;
    const bottom = (vpRect.height - panY) / scale;

    const startCol = Math.max(0, Math.floor(left / cellW) - 1);
    const endCol = Math.min(cols - 1, Math.ceil(right / cellW) + 1);
    const startRow = Math.max(0, Math.floor(top / cellH) - 1);
    const endRow = Math.min(rows - 1, Math.ceil(bottom / cellH) + 1);

    for (const el of grid.children) {
      const id = +el.dataset.id;
      const r = Math.floor(id / cols);
      const c = id % cols;
      const onScreen = r >= startRow && r <= endRow && c >= startCol && c <= endCol;
      el.style.visibility = onScreen ? 'visible' : 'hidden';
      if (onScreen) visible++;
    }

    visibleLabel.textContent = visible;
  }

  function updateCell(stock) {
    const el = grid.querySelector(`[data-id="${stock.id}"]`);
    if (!el) return;
    const chg = stock.pct;
    el.style.background = pctToColor(chg);
    el.querySelector('.px').textContent = `$${stock.price.toFixed(stock.price < 20 ? 2 : 2)}`;
    el.querySelector('.chg').textContent = `${chg >= 0 ? '+' : ''}${chg.toFixed(2)}%`;
    el.querySelector('.chg').style.color = chg >= 0 ? 'rgba(7, 25, 18, 0.9)' : 'rgba(32, 5, 10, 0.9)';
    if (selectedId === stock.id) el.classList.add('selected');
  }

  function renderAll() {
    for (const s of stocks) updateCell(s);
    renderTransform();
    renderCells();
  }

  function renderTransform() {
    world.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    scaleLabel.textContent = `${scale.toFixed(2)}x`;
  }

  function clampPan() {
    const vp = viewport.getBoundingClientRect();
    const contentW = cols * cellW * scale;
    const contentH = rows * cellH * scale;
    const minX = Math.min(24, vp.width - contentW - 24);
    const minY = Math.min(24, vp.height - contentH - 24);
    panX = Math.max(minX, Math.min(24, panX));
    panY = Math.max(minY, Math.min(24, panY));
  }

  function zoomAt(clientX, clientY, nextScale) {
    const rect = viewport.getBoundingClientRect();
    const x = clientX - rect.left;
    const y = clientY - rect.top;
    const worldX = (x - panX) / scale;
    const worldY = (y - panY) / scale;

    scale = Math.max(0.35, Math.min(4, nextScale));
    panX = x - worldX * scale;
    panY = y - worldY * scale;
    clampPan();
    renderTransform();
    renderCells();
  }

  function findCellFromEvent(e) {
    const target = e.target.closest('.cell');
    return target ? byId.get(+target.dataset.id) : null;
  }

  function showTooltip(stock, x, y) {
    tooltip.style.display = 'block';
    tooltip.style.left = `${x + 14}px`;
    tooltip.style.top = `${y + 14}px`;
    tooltip.innerHTML = `
      <div class="t1">${stock.symbol} <span style="color:${stock.pct >= 0 ? 'var(--up)' : 'var(--down)'}">${stock.pct >= 0 ? '+' : ''}${stock.pct.toFixed(2)}%</span></div>
      <div class="t2">Price: <strong>$${stock.price.toFixed(2)}</strong></div>
      <div class="t2">Prev Close: $${stock.prevClose.toFixed(2)}</div>
      <div class="t2">Volume: ${stock.volume.toLocaleString()}</div>
      <div class="t3">Sector: ${stock.sector}</div>
    `;
  }

  function hideTooltip() {
    if (selectedId == null) tooltip.style.display = 'none';
  }

  viewport.addEventListener('pointerdown', (e) => {
    dragging = true;
    dragStart = { x: e.clientX, y: e.clientY, panX, panY };
    viewport.setPointerCapture(e.pointerId);
  });

  viewport.addEventListener('pointermove', (e) => {
    const stock = findCellFromEvent(e);
    if (!dragging) {
      if (stock) {
        hoverId = stock.id;
        showTooltip(stock, e.clientX, e.clientY);
      } else if (selectedId == null) {
        hideTooltip();
      }
      return;
    }
    panX = dragStart.panX + (e.clientX - dragStart.x);
    panY = dragStart.panY + (e.clientY - dragStart.y);
    clampPan();
    renderTransform();
    renderCells();
  });

  viewport.addEventListener('pointerup', (e) => {
    dragging = false;
    viewport.releasePointerCapture(e.pointerId);
  });

  viewport.addEventListener('click', (e) => {
    const stock = findCellFromEvent(e);
    if (!stock) {
      selectedId = null;
      for (const el of grid.children) el.classList.remove('selected');
      hideTooltip();
      return;
    }
    selectedId = stock.id;
    for (const el of grid.children) el.classList.toggle('selected', +el.dataset.id === selectedId);
    showTooltip(stock, e.clientX, e.clientY);
  });

  viewport.addEventListener('wheel', (e) => {
    e.preventDefault();
    const delta = -e.deltaY;
    const factor = delta > 0 ? 1.08 : 0.92;
    zoomAt(e.clientX, e.clientY, scale * factor);
  }, { passive: false });

  zoomInBtn.addEventListener('click', () => {
    const rect = viewport.getBoundingClientRect();
    zoomAt(rect.left + rect.width / 2, rect.top + rect.height / 2, scale * 1.15);
  });

  zoomOutBtn.addEventListener('click', () => {
    const rect = viewport.getBoundingClientRect();
    zoomAt(rect.left + rect.width / 2, rect.top + rect.height / 2, scale * 0.87);
  });

  resetBtn.addEventListener('click', () => {
    scale = 1;
    panX = 24;
    panY = 24;
    clampPan();
    renderTransform();
    renderCells();
  });

  window.addEventListener('resize', () => {
    clampPan();
    renderTransform();
    renderCells();
  });

  function applyUpdate(tick) {
    for (const item of tick) {
      const stock = byId.get(item.id);
      if (!stock) continue;
      stock.prevClose = stock.prevClose ?? stock.price;
      stock.price = item.price;
      stock.pct = ((stock.price - stock.prevClose) / stock.prevClose) * 100;
      stock.volume = item.volume ?? stock.volume;
      stock.updatedAt = Date.now();
      updateCell(stock);
    }
  }

  let ws = null;
  let simulationTimer = null;

  function startSimulation() {
    statusDot.className = 'status-dot sim';
    statusText.textContent = 'Simulated live feed';
    simulationTimer = setInterval(() => {
      const tick = [];
      for (let i = 0; i < 18; i++) {
        const id = (Math.random() * stocks.length) | 0;
        const s = byId.get(id);
        const drift = rand(-0.012, 0.012);
        const next = Math.max(0.5, s.price * (1 + drift));
        tick.push({
          id,
          price: next,
          volume: Math.floor(s.volume * rand(0.98, 1.05))
        });
      }
      applyUpdate(tick);
    }, 350);
  }

  function connectLiveFeed() {
    try {
      ws = new WebSocket('wss://example.com/stock-feed'); // replace with your data source

      ws.onopen = () => {
        statusDot.className = 'status-dot live';
        statusText.textContent = 'Connected to live feed';
        if (simulationTimer) clearInterval(simulationTimer);
      };

      ws.onmessage = (evt) => {
        try {
          const msg = JSON.parse(evt.data);

          // Expected formats:
          // { type: "tick", data: [{ id, price, volume }] }
          // or direct array: [{ id, price, volume }]
          const tick = Array.isArray(msg) ? msg : msg.data;
          if (Array.isArray(tick)) applyUpdate(tick);
        } catch {
          // ignore malformed messages
        }
      };

      ws.onerror = () => {
        if (!simulationTimer) startSimulation();
      };

      ws.onclose = () => {
        if (!simulationTimer) startSimulation();
      };
    } catch {
      startSimulation();
    }
  }

  // Initial render
  initData();
  buildGrid();
  renderAll();
  connectLiveFeed();

  // Auto re-render transform smoothly when animations or layout change
  renderTransform();
  renderCells();
})();
</script>
</body>
</html>
```

