<body>
  <div class="app">
    <div class="toolbar">
      <div class="controls">
        <button id="zoomIn">Zoom In</button>
        <button id="zoomOut">Zoom Out</button>
        <button id="resetView">Reset</button>
        <button id="toggleUpdates">Pause Updates</button>
      </div>
      <div class="legend">
        <span>Loss</span>
        <div class="bar"></div>
        <span>Gain</span>
      </div>
    </div>

    <div id="viewport" class="viewport">
      <div id="content" class="content">
        <div id="heatmap" class="heatmap"></div>
      </div>
      <div id="tooltip" class="tooltip"></div>
    </div>

    <div class="footer">
      Mouse wheel: zoom • Drag: pan • Hover cells for details
    </div>
  </div>

  <script>
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","META","NVDA","TSLA","BRK.B","JPM","V",
      "XOM","UNH","HD","PG","MA","LLY","AVGO","COST","PEP","KO",
      "ADBE","CSCO","CRM","NFLX","AMD","INTC","QCOM","MCD","WMT","BAC",
      "ABT","TXN","UPS","ORCL","LIN","NKE","TMO","PM","IBM","GE"
    ];

    const heatmapEl = document.getElementById("heatmap");
    const viewportEl = document.getElementById("viewport");
    const contentEl = document.getElementById("content");
    const tooltipEl = document.getElementById("tooltip");

    const zoomInBtn = document.getElementById("zoomIn");
    const zoomOutBtn = document.getElementById("zoomOut");
    const resetViewBtn = document.getElementById("resetView");
    const toggleUpdatesBtn = document.getElementById("toggleUpdates");

    const state = {
      scale: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      panStartX: 0,
      panStartY: 0,
      updatesRunning: true,
      stocks: []
    };

    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatCurrency(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatPct(v) {
      return `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`;
    }

    function performanceToColor(pct) {
      // pct range roughly -5..+5 mapped red->yellow->green
      const t = clamp((pct + 5) / 10, 0, 1);
      const hue = 120 * t; // 0 = red, 120 = green
      const light = 28 + 18 * Math.abs(t - 0.5) * 2;
      return `hsl(${hue}, 75%, ${light}%)`;
    }

    function initStocks() {
      state.stocks = symbols.map(symbol => {
        const price = randomBetween(20, 500);
        const prevClose = price / (1 + randomBetween(-0.03, 0.03));
        const pct = ((price - prevClose) / prevClose) * 100;
        return { symbol, price, prevClose, pct };
      });
    }

    function renderHeatmap() {
      heatmapEl.innerHTML = "";
      state.stocks.forEach((s, index) => {
        const cell = document.createElement("div");
        cell.className = "cell";
        cell.dataset.index = index;
        cell.style.background = performanceToColor(s.pct);

        cell.innerHTML = `
          <div class="symbol">${s.symbol}</div>
          <div class="price">${formatCurrency(s.price)}</div>
          <div class="change">${formatPct(s.pct)}</div>
        `;

        cell.addEventListener("mousemove", (e) => {
          tooltipEl.style.opacity = "1";
          tooltipEl.style.left = e.clientX + "px";
          tooltipEl.style.top = e.clientY + "px";
          tooltipEl.innerHTML = `
            <strong>${s.symbol}</strong><br>
            Price: ${formatCurrency(s.price)}<br>
            Prev Close: ${formatCurrency(s.prevClose)}<br>
            Change: ${formatPct(s.pct)}
          `;
        });

        cell.addEventListener("mouseleave", () => {
          tooltipEl.style.opacity = "0";
        });

        heatmapEl.appendChild(cell);
      });
    }

    function updateHeatmap() {
      state.stocks.forEach((s, index) => {
        // Simulate real-time movement
        const drift = randomBetween(-0.8, 0.8);
        const volatility = randomBetween(-1.8, 1.8);

        s.price = Math.max(1, s.price + drift + volatility);
        s.pct = ((s.price - s.prevClose) / s.prevClose) * 100;

        const cell = heatmapEl.children[index];
        if (cell) {
          cell.style.background = performanceToColor(s.pct);
          cell.querySelector(".price").textContent = formatCurrency(s.price);
          cell.querySelector(".change").textContent = formatPct(s.pct);
        }
      });
    }

    function applyTransform() {
      contentEl.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.scale})`;
    }

    function setScale(newScale, centerX = viewportEl.clientWidth / 2, centerY = viewportEl.clientHeight / 2) {
      const oldScale = state.scale;
      const scale = clamp(newScale, 0.5, 3);

      // Zoom around cursor or center point
      const rect = viewportEl.getBoundingClientRect();
      const x = centerX - rect.left;
      const y = centerY - rect.top;

      const worldX = (x - state.panX) / oldScale;
      const worldY = (y - state.panY) / oldScale;

      state.scale = scale;
      state.panX = x - worldX * scale;
      state.panY = y - worldY * scale;

      applyTransform();
    }

    viewportEl.addEventListener("mousedown", (e) => {
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.panStartX = state.panX;
      state.panStartY = state.panY;
      viewportEl.style.cursor = "grabbing";
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.dragging) return;
      state.panX = state.panStartX + (e.clientX - state.dragStartX);
      state.panY = state.panStartY + (e.clientY - state.dragStartY);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      viewportEl.style.cursor = "default";
    });

    viewportEl.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      setScale(state.scale * zoomFactor, e.clientX, e.clientY);
    }, { passive: false });

    zoomInBtn.addEventListener("click", () => {
      setScale(state.scale * 1.15);
    });

    zoomOutBtn.addEventListener("click", () => {
      setScale(state.scale / 1.15);
    });

    resetViewBtn.addEventListener("click", () => {
      state.scale = 1;
      state.panX = 0;
      state.panY = 0;
      applyTransform();
    });

    toggleUpdatesBtn.addEventListener("click", () => {
      state.updatesRunning = !state.updatesRunning;
      toggleUpdatesBtn.textContent = state.updatesRunning ? "Pause Updates" : "Resume Updates";
    });

    // Basic resize handling: keep content centered-ish if needed
    window.addEventListener("resize", () => {
      applyTransform();
    });

    initStocks();
    renderHeatmap();
    applyTransform();

    setInterval(() => {
      if (state.updatesRunning) updateHeatmap();
    }, 1000);
  </script>
</body>
</html>
