      display: none;
      z-index: 10;
      min-width: 180px;
    }

    footer {
      padding: 10px 18px;
      font-size: 12px;
      color: var(--muted);
      background: rgba(15, 17, 21, 0.88);
      border-top: 1px solid rgba(255, 255, 255, 0.06);
    }

    .hint {
      opacity: 0.9;
    }
  </style>
</head>
<body>
  <div class="app">
    <header>
      <h1>Live Stock Heatmap</h1>
      <div class="controls">
        <div class="legend">
          <span>Loss</span>
          <div class="legend-bar"></div>
          <span>Gain</span>
        </div>
        <button id="resetBtn">Reset View</button>
        <button id="toggleUpdatesBtn">Pause Updates</button>
      </div>
    </header>

    <div class="viewport" id="viewport">
      <div class="heatmap" id="heatmap"></div>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <footer>
      <span class="hint">Scroll to zoom. Drag to pan. Hover tiles for details. Updates are simulated client-side.</span>
    </footer>
  </div>

  <script>
    const viewport = document.getElementById("viewport");
    const heatmap = document.getElementById("heatmap");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");
    const toggleUpdatesBtn = document.getElementById("toggleUpdatesBtn");

    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","META","GOOGL","GOOG","TSLA",
      "NFLX","AMD","INTC","ORCL","CRM","ADBE","QCOM","AVGO",
      "UBER","SHOP","DIS","BAC","JPM","V","MA","COST",
      "PEP","KO","WMT","T","TMUS","XOM","CVX","SBUX"
    ];

    const rows = 4;
    const cols = 8;

    let state = symbols.map((symbol, i) => {
      const base = 50 + Math.random() * 450;
      const change = (Math.random() - 0.5) * 8;
      return {
        symbol,
        price: base,
        prevPrice: base,
        changePct: change,
        volume: Math.floor(500_000 + Math.random() * 8_000_000),
        row: Math.floor(i / cols),
        col: i % cols
      };
    });

    let scale = 1;
    let panX = 0;
    let panY = 0;
    let isDragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let startPanX = 0;
    let startPanY = 0;
    let updating = true;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(pct) {
      const maxAbs = 6;
      const v = clamp(pct, -maxAbs, maxAbs);

      if (v < 0) {
        const t = (v + maxAbs) / maxAbs; // 0..1
        const r = Math.round(220 * (1 - t) + 31 * t);
        const g = Math.round(38 * (1 - t) + 41 * t);
        const b = Math.round(38 * (1 - t) + 55 * t);
        return `rgb(${r}, ${g}, ${b})`;
      } else {
        const t = v / maxAbs; // 0..1
        const r = Math.round(17 * (1 - t) + 22 * t);
        const g = Math.round(24 * (1 - t) + 163 * t);
        const b = Math.round(39 * (1 - t) + 74 * t);
        return `rgb(${r}, ${g}, ${b})`;
      }
    }

    function textColorForBg(changePct) {
      return Math.abs(changePct) > 3 ? "#ffffff" : "#f8fafc";
    }

    function render() {
      heatmap.innerHTML = "";

      heatmap.style.gridTemplateColumns = `repeat(${cols, 140px)`;
      heatmap.style.gridTemplateRows = `repeat(${rows, 96px)`;
      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;

      state.forEach(stock => {
        const tile = document.createElement("div");
        tile.className = "tile";
        tile.style.background = colorForChange(stock.changePct);
        tile.style.color = textColorForBg(stock.changePct);

        tile.innerHTML = `
          <div class="symbol">${stock.symbol}</div>
          <div class="price">$${stock.price.toFixed(2)}</div>
          <div class="change">${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%</div>
          <div class="volume">
            <span>Vol</span>
            <span>${stock.volume.toLocaleString()}</span>
          </div>
        `;

        tile.addEventListener("mousemove", (e) => {
          tooltip.style.display = "block";
          tooltip.style.left = `${e.clientX}px`;
          tooltip.style.top = `${e.clientY}px`;
          tooltip.innerHTML = `
            <strong>${stock.symbol}</strong><br/>
            Price: $${stock.price.toFixed(2)}<br/>
            Change: ${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%<br/>
            Volume: ${stock.volume.toLocaleString()}
          `;
        });

        tile.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        heatmap.appendChild(tile);
      });
    }

    function updateData() {
      state = state.map(stock => {
        const volatility = Math.max(0.15, Math.abs(stock.changePct) / 8 + 0.25);
        const deltaPct = (Math.random() - 0.5) * volatility * 2.2;

        const prevPrice = stock.price;
        const nextPrice = Math.max(1, prevPrice * (1 + deltaPct / 100));
        const changePct = ((nextPrice - prevPrice) / prevPrice) * 100;

        return {
          ...stock,
          prevPrice,
          price: nextPrice,
          changePct,
          volume: Math.max(1000, stock.volume + Math.floor((Math.random() - 0.5) * 50000))
        };
      });

      render();
    }

    function resetView() {
      scale = 1;
      panX = 0;
      panY = 0;
      render();
    }

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomIntensity = 0.0015;
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const newScale = clamp(scale * Math.exp(-e.deltaY * zoomIntensity), 0.5, 3.5);

      panX = mouseX - (mouseX - panX) * (newScale / scale);
      panY = mouseY - (mouseY - panY) * (newScale / scale);
      scale = newScale;

      render();
    }, { passive: false });

    viewport.addEventListener("mousedown", (e) => {
      isDragging = true;
      viewport.classList.add("dragging");
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      panX = startPanX + (e.clientX - dragStartX);
      panY = startPanY + (e.clientY - dragStartY);
      render();
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      viewport.classList.remove("dragging");
    });

    resetBtn.addEventListener("click", resetView);

    toggleUpdatesBtn.addEventListener("click", () => {
      updating = !updating;
      toggleUpdatesBtn.textContent = updating ? "Pause Updates" : "Resume Updates";
    });

    // Initial render
    render();

    // Simulated real-time updates
    setInterval(() => {
      if (updating) updateData();
    }, 1200);

    // Keep tooltip positioned if viewport scroll state changes (not much here)
    window.addEventListener("resize", () => render());
  </script>
</body>
</html>
```

