</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <button id="zoomIn">Zoom In</button>
      <button id="zoomOut">Zoom Out</button>
      <button id="resetView">Reset</button>
      <div class="meta" id="status">Live updates: connected</div>
    </div>

    <div class="viewport" id="viewport">
      <div class="world" id="world"></div>
      <div class="tooltip" id="tooltip"></div>
      <div class="hint">Drag to pan • Mouse wheel to zoom • Hover for details</div>
    </div>
  </div>

  <script>
    // ---------- Demo data ----------
    const tickers = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","TSLA","META","NFLX","AMD","INTC",
      "ORCL","CRM","UBER","SHOP","ADBE","QCOM","CSCO","IBM","BABA","SONY",
      "BA","JPM","V","MA","DIS","KO","PEP","NKE","PFE","MRNA",
      "XOM","CVX","WMT","HD","COST","T","VZ","SNAP","PLTR","SQ"
    ];

    const cols = 5;
    const cellW = 170;
    const cellH = 88;
    const gap = 12;

    const state = {
      zoom: 1,
      panX: 40,
      panY: 40,
      isPanning: false,
      dragStartX: 0,
      dragStartY: 0,
      startPanX: 0,
      startPanY: 0,
      stocks: []
    };

    // Initialize stock data
    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function initStocks() {
      state.stocks = tickers.map((ticker, i) => {
        const base = randomBetween(30, 600);
        const changePct = randomBetween(-4, 4);
        return {
          ticker,
          price: base,
          prevPrice: base,
          changePct,
          x: (i % cols) * (cellW + gap),
          y: Math.floor(i / cols) * (cellH + gap)
        };
      });
    }

    // ---------- Rendering ----------
    const viewport = document.getElementById("viewport");
    const world = document.getElementById("world");
    const tooltip = document.getElementById("tooltip");
    const status = document.getElementById("status");

    function heatColor(changePct) {
      // Map -10%..10% to red/gray/green
      const clamped = Math.max(-10, Math.min(10, changePct));
      const t = Math.abs(clamped) / 10;

      if (clamped > 0.25) {
        // green intensity
        const g = Math.round(70 + 140 * t);
        return `rgb(${Math.round(25 + 20 * t)}, ${g}, ${Math.round(50 + 30 * t)})`;
      } else if (clamped < -0.25) {
        // red intensity
        const r = Math.round(70 + 160 * t);
        return `rgb(${r}, ${Math.round(35 + 25 * t)}, ${Math.round(35 + 20 * t)})`;
      } else {
        return `var(--neutral)`;
      }
    }

    function textColorForBg(changePct) {
      return Math.abs(changePct) < 0.5 ? "#e8ecff" : "#ffffff";
    }

    function render() {
      world.innerHTML = "";

      const totalWidth = cols * cellW + (cols - 1) * gap;
      const rows = Math.ceil(state.stocks.length / cols);
      const totalHeight = rows * cellH + (rows - 1) * gap;

      world.style.width = totalWidth + "px";
      world.style.height = totalHeight + "px";
      world.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;

      state.stocks.forEach((s, idx) => {
        const cell = document.createElement("div");
        cell.className = "cell";
        cell.style.left = s.x + "px";
        cell.style.top = s.y + "px";
        cell.style.width = cellW + "px";
        cell.style.height = cellH + "px";
        cell.style.background = heatColor(s.changePct);
        cell.style.color = textColorForBg(s.changePct);

        cell.dataset.index = idx;

        cell.innerHTML = `
          <div class="ticker">${s.ticker}</div>
          <div class="price">$${s.price.toFixed(2)}</div>
          <div class="change">${s.changePct >= 0 ? "▲" : "▼"} ${s.changePct.toFixed(2)}%</div>
        `;

        cell.addEventListener("mouseenter", (e) => showTooltip(e, s));
        cell.addEventListener("mousemove", (e) => moveTooltip(e));
        cell.addEventListener("mouseleave", hideTooltip);

        world.appendChild(cell);
      });
    }

    // ---------- Real-time updates ----------
    function simulateLiveUpdate() {
      // Update a few random stocks every tick
      const updates = Math.max(2, Math.floor(Math.random() * 6));

      for (let i = 0; i < updates; i++) {
        const idx = Math.floor(Math.random() * state.stocks.length);
        const s = state.stocks[idx];

        const delta = randomBetween(-2.2, 2.2);
        const newPrice = Math.max(1, s.price + delta);
        s.prevPrice = s.price;
        s.price = newPrice;
        s.changePct = ((s.price - s.prevPrice) / s.prevPrice) * 100 + (s.changePct * 0.92);
        s.changePct = Math.max(-12, Math.min(12, s.changePct));
      }

      // Re-render only (simple approach for demo)
      render();
      status.textContent = `Live updates: connected • ${new Date().toLocaleTimeString()}`;
    }

    // ---------- Tooltip ----------
    function showTooltip(e, s) {
      tooltip.style.opacity = 1;
      tooltip.innerHTML = `
        <strong>${s.ticker}</strong><br>
        Price: $${s.price.toFixed(2)}<br>
        Change: ${s.changePct >= 0 ? "+" : ""}${s.changePct.toFixed(2)}%
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const rect = viewport.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      tooltip.style.left = x + "px";
      tooltip.style.top = y + "px";
    }

    function hideTooltip() {
      tooltip.style.opacity = 0;
    }

    // ---------- Pan / Zoom ----------
    function setZoom(nextZoom, focalX = viewport.clientWidth / 2, focalY = viewport.clientHeight / 2) {
      const oldZoom = state.zoom;
      const minZoom = 0.5;
      const maxZoom = 3;
      nextZoom = Math.max(minZoom, Math.min(maxZoom, nextZoom));

      // Keep focal point stable
      const worldX = (focalX - state.panX) / oldZoom;
      const worldY = (focalY - state.panY) / oldZoom;

      state.zoom = nextZoom;
      state.panX = focalX - worldX * nextZoom;
      state.panY = focalY - worldY * nextZoom;

      render();
    }

    viewport.addEventListener("mousedown", (e) => {
      if (e.target.closest(".cell")) return; // don't start pan when clicking cell
      state.isPanning = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
      viewport.style.cursor = "grabbing";
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.isPanning) return;
      state.panX = state.startPanX + (e.clientX - state.dragStartX);
      state.panY = state.startPanY + (e.clientY - state.dragStartY);
      render();
    });

    window.addEventListener("mouseup", () => {
      state.isPanning = false;
      viewport.style.cursor = "default";
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const rect = viewport.getBoundingClientRect();
      const focalX = e.clientX - rect.left;
      const focalY = e.clientY - rect.top;
      const delta = -e.deltaY * 0.0015;
      setZoom(state.zoom * (1 + delta), focalX, focalY);
    }, { passive: false });

    document.getElementById("zoomIn").addEventListener("click", () => {
      setZoom(state.zoom * 1.2);
    });

    document.getElementById("zoomOut").addEventListener("click", () => {
      setZoom(state.zoom / 1.2);
    });

    document.getElementById("resetView").addEventListener("click", () => {
      state.zoom = 1;
      state.panX = 40;
      state.panY = 40;
      render();
    });

    // ---------- Start ----------
    initStocks();
    render();
    setInterval(simulateLiveUpdate, 1200);
  </script>
</body>
</html>
