    }

    .status {
      font-size: 12px;
      color: var(--muted);
    }

    .viewport {
      position: relative;
      overflow: hidden;
      user-select: none;
      touch-action: none;
    }

    svg {
      width: 100%;
      height: 100%;
      display: block;
      background:
        linear-gradient(to right, transparent 49.5%, var(--grid) 50%, transparent 50.5%),
        linear-gradient(to bottom, transparent 49.5%, var(--grid) 50%, transparent 50.5%);
      background-size: 24px 24px;
