    }

    .tooltip.visible {
      opacity: 1;
    }

    .tooltip .name {
      font-weight: 700;
      margin-bottom: 4px;
    }

    .tooltip .row {
      display: flex;
      justify-content: space-between;
      gap: 10px;
      margin-top: 4px;
    }

