      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, #d94f4f, #f2d34f, #4cd97d);
      border: 1px solid rgba(255,255,255,0.12);
    }
  </style>
</head>
<body>
<div class="app">
  <div class="toolbar">
    <div class="title">
      <h1>Stock Price Heatmap</h1>
      <div class="subtitle">Real-time updates • Mouse wheel to zoom • Drag to pan • Hover for details</div>
    </div>

    <div class="controls">
      <div class="legend">
        <div class="legend-bar"></div>
        <span>Red = down, Green = up</span>
      </div>
      <button id="resetBtn">Reset View</button>
      <div class="status" id="status">Streaming updates: on</div>
    </div>
  </div>

  <div class="viewport" id="viewport">
    <svg id="svg" xmlns="http://www.w3.org/2000/svg">
      <g id="scene"></g>
    </svg>
    <div class="tooltip" id="tooltip"></div>
  </div>
</div>

<script>
(() => {
  const svg = document.getElementById('svg');
  const scene = document.getElementById('scene');
  const viewport = document.getElementById('viewport');
  const tooltip = document.getElementById('tooltip');
  const resetBtn = document.getElementById('resetBtn');

  const rows = 12;
  const cols = 18;
  const cellW = 78;
  const cellH = 52;
  const padding = 18;

  const stocks = [];
  const sectorNames = [
    "Tech", "Finance", "Energy", "Healthcare", "Retail", "Industrial"
  ];

  function rand(min, max) {
    return Math.random() * (max - min) + min;
  }

  function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
  }

  function formatPrice(v) {
    return `$${v.toFixed(2)}`;
  }

  function formatPct(v) {
    return `${v >= 0 ? '+' : ''}${v.toFixed(2)}%`;
  }

  // Generate fake stock universe
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const base = rand(12, 450);
      const change = rand(-4.5, 4.5);
      stocks.push({
        id: `S${r}-${c}`,
        symbol: `STK${String(r * cols + c + 1).padStart(3, '0')}`,
        name: `${sectorNames[(r + c) % sectorNames.length]} Co. ${r * cols + c + 1}`,
        sector: sectorNames[(r + c) % sectorNames.length],
        price: base,
        prevClose: base / (1 + change / 100),
        changePct: change,
        volume: Math.floor(rand(100_000, 8_000_000)),
        row: r,
        col: c
      });
    }
  }

  // View transform state
  let scale = 1;
  let tx = 0;
  let ty = 0;
  const minScale = 0.6;
  const maxScale = 4;

  let isPanning = false;
  let panStart = { x: 0, y: 0, tx: 0, ty: 0 };

  // Render cells
  function getColor(changePct) {
    // Map changePct to color from red -> yellow -> green
    const t = clamp((changePct + 5) / 10, 0, 1); // -5% to +5%
    const r1 = { r: 217, g: 79, b: 79 };
    const r2 = { r: 242, g: 211, b: 79 };
    const r3 = { r: 76, g: 217, b: 125 };

    let a, b, localT;
    if (t < 0.5) {
      a = r1; b = r2; localT = t / 0.5;
    } else {
      a = r2; b = r3; localT = (t - 0.5) / 0.5;
    }

    const mix = (x, y) => Math.round(x + (y - x) * localT);
    return `rgb(${mix(a.r, b.r)}, ${mix(a.g, b.g)}, ${mix(a.b, b.b)})`;
  }

  function render() {
    scene.innerHTML = '';

    const minX = padding;
    const minY = padding;
    const width = cols * cellW;
    const height = rows * cellH;

    stocks.forEach((s) => {
      const x = minX + s.col * cellW;
      const y = minY + s.row * cellH;

      const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      g.setAttribute('transform', `translate(${x}, ${y})`);

      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('class', 'cell');
      rect.setAttribute('width', cellW - 8);
      rect.setAttribute('height', cellH - 8);
      rect.setAttribute('x', 4);
      rect.setAttribute('y', 4);
      rect.setAttribute('fill', getColor(s.changePct));
      rect.dataset.id = s.id;

      const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      label.setAttribute('class', 'label');
      label.setAttribute('x', (cellW - 8) / 2 + 4);
      label.setAttribute('y', 22);
      label.textContent = s.symbol;

      const price = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      price.setAttribute('class', 'subLabel');
      price.setAttribute('x', (cellW - 8) / 2 + 4);
      price.setAttribute('y', 37);
      price.textContent = formatPrice(s.price);

      g.appendChild(rect);
      g.appendChild(label);
      g.appendChild(price);
      scene.appendChild(g);

      rect.addEventListener('mouseenter', (e) => showTooltip(e, s));
      rect.addEventListener('mousemove', (e) => moveTooltip(e));
      rect.addEventListener('mouseleave', hideTooltip);
    });

    // Fit initial scene size
    scene.setAttribute('transform', `translate(${tx}, ${ty}) scale(${scale})`);
    svg.setAttribute('viewBox', `0 0 ${width + padding * 2} ${height + padding * 2}`);
  }

  function updateColorsAndPrices() {
    // Efficient update: only update text/fill without full rerender
    const svgs = scene.querySelectorAll('g');
    svgs.forEach((g, i) => {
      const s = stocks[i];
      const rect = g.querySelector('rect');
      const priceText = g.querySelector('.subLabel');
      rect.setAttribute('fill', getColor(s.changePct));
      priceText.textContent = formatPrice(s.price);
    });
    scene.setAttribute('transform', `translate(${tx}, ${ty}) scale(${scale})`);
  }

  function applyTransform() {
    scene.setAttribute('transform', `translate(${tx}, ${ty}) scale(${scale})`);
  }

  function showTooltip(e, s) {
    tooltip.classList.add('visible');
    tooltip.innerHTML = `
      <div class="name">${s.symbol} — ${s.name}</div>
      <div class="row"><span>Sector</span><span>${s.sector}</span></div>
      <div class="row"><span>Price</span><span>${formatPrice(s.price)}</span></div>
      <div class="row"><span>Change</span><span style="color:${s.changePct >= 0 ? '#5fe08a' : '#ff7a7a'}">${formatPct(s.changePct)}</span></div>
      <div class="row"><span>Volume</span><span>${s.volume.toLocaleString()}</span></div>
    `;
    moveTooltip(e);
  }

  function moveTooltip(e) {
    const rect = viewport.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    tooltip.style.left = `${x}px`;
    tooltip.style.top = `${y}px`;
  }

  function hideTooltip() {
    tooltip.classList.remove('visible');
  }

  // Zoom around cursor
  svg.addEventListener('wheel', (e) => {
    e.preventDefault();

    const rect = svg.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const delta = -e.deltaY;
    const zoomFactor = delta > 0 ? 1.08 : 0.92;

    const newScale = clamp(scale * zoomFactor, minScale, maxScale);
    const scaleRatio = newScale / scale;

    // Adjust transform so point under cursor stays fixed
    tx = mouseX - (mouseX - tx) * scaleRatio;
    ty = mouseY - (mouseY - ty) * scaleRatio;
    scale = newScale;

    applyTransform();
  }, { passive: false });

  // Pan interactions
  svg.addEventListener('mousedown', (e) => {
    isPanning = true;
    panStart = { x: e.clientX, y: e.clientY, tx, ty };
    svg.style.cursor = 'grabbing';
  });

  window.addEventListener('mousemove', (e) => {
    if (!isPanning) return;
    tx = panStart.tx + (e.clientX - panStart.x);
    ty = panStart.ty + (e.clientY - panStart.y);
    applyTransform();
  });

  window.addEventListener('mouseup', () => {
    isPanning = false;
    svg.style.cursor = 'default';
  });

  // Touch drag support
  let touchStart = null;
  svg.addEventListener('touchstart', (e) => {
    if (e.touches.length === 1) {
      const t = e.touches[0];
      touchStart = { x: t.clientX, y: t.clientY, tx, ty };
    }
  }, { passive: true });

  svg.addEventListener('touchmove', (e) => {
    if (!touchStart || e.touches.length !== 1) return;
    e.preventDefault();
    const t = e.touches[0];
    tx = touchStart.tx + (t.clientX - touchStart.x);
    ty = touchStart.ty + (t.clientY - touchStart.y);
    applyTransform();
  }, { passive: false });

  svg.addEventListener('touchend', () => {
    touchStart = null;
  });

  resetBtn.addEventListener('click', () => {
    scale = 1;
    tx = 0;
    ty = 0;
    applyTransform();
  });

  // Simulated real-time updates
  function tick() {
    // Update a subset of stocks every interval
    const updates = Math.ceil(stocks.length * 0.15);
    for (let i = 0; i < updates; i++) {
      const s = stocks[Math.floor(Math.random() * stocks.length)];
      const drift = rand(-0.8, 0.8);
      const shock = rand(-1.6, 1.6);

      const oldPrice = s.price;
      const newPrice = Math.max(0.5, oldPrice * (1 + (drift + shock) / 100));
      s.price = newPrice;
      s.changePct = ((newPrice - s.prevClose) / s.prevClose) * 100;
      s.volume += Math.floor(rand(500, 20_000));
    }

    updateColorsAndPrices();
  }

  // Optional: pause/resume streaming
  let streaming = true;
  const statusEl = document.getElementById('status');

  setInterval(() => {
    if (streaming) tick();
  }, 1000);

  // Render and initialize
  render();
  applyTransform();

  // Example hook if you want to replace simulated data with API updates:
  // socket.onmessage = (msg) => {
  //   const update = JSON.parse(msg.data);
  //   const s = stocks.find(x => x.symbol === update.symbol);
  //   if (s) {
  //     s.price = update.price;
  //     s.changePct = update.changePct;
  //     s.volume = update.volume;
  //     updateColorsAndPrices();
  //   }
  // };
})();
</script>
</body>
</html>
```

---

## How it works
- **SVG** is used to draw each stock tile.
- Each tile color is derived from `changePct`:
  - negative = red
  - neutral = yellow
  - positive = green
- A timer simulates a live feed and periodically updates prices.
- Zoom works by adjusting the scene’s scale and translation so the cursor position stays anchored.
- Pan works by dragging the visualization.

---

## To use real stock data
Replace the simulated `tick()` logic with:
- a WebSocket feed
- polling a REST API
- server-sent events

Then update the relevant stock objects and call `updateColorsAndPrices()`.

Example integration point:
```js
function applyStockUpdate(update) {
  const s = stocks.find(x => x.symbol === update.symbol);
  if (!s) return;
  s.price = update.price;
  s.changePct = update.changePct;
  s.volume = update.volume;
  updateColorsAndPrices();
}
```

---

