<script>
(() => {
  const gridEl = document.getElementById('grid');
  const viewport = document.getElementById('viewport');
  const statusEl = document.getElementById('status');
  const searchEl = document.getElementById('search');
  const resetBtn = document.getElementById('reset');
  const randomizeBtn = document.getElementById('randomize');

  const stocks = [
    ["AAPL","Apple"],["MSFT","Microsoft"],["NVDA","NVIDIA"],["AMZN","Amazon"],["GOOGL","Alphabet"],
    ["META","Meta"],["TSLA","Tesla"],["AMD","AMD"],["NFLX","Netflix"],["INTC","Intel"],
    ["ORCL","Oracle"],["CRM","Salesforce"],["ADBE","Adobe"],["PYPL","PayPal"],["UBER","Uber"],
    ["DIS","Disney"],["COST","Costco"],["WMT","Walmart"],["JNJ","Johnson & Johnson"],["JPM","JPMorgan"],
    ["V","Visa"],["MA","Mastercard"],["BAC","Bank of America"],["XOM","Exxon Mobil"],["CVX","Chevron"],
    ["KO","Coca-Cola"],["PEP","PepsiCo"],["NKE","Nike"],["MCD","McDonald's"],["SBUX","Starbucks"]
  ];

  const state = stocks.map(([symbol, company]) => {
    const price = +(50 + Math.random() * 450).toFixed(2);
    return {
      symbol,
      company,
      price,
      prev: price,
      changePct: 0,
      history: Array.from({length: 12}, () => price)
    };
  });

  let filter = "";
  let scale = 1;
  let tx = 0, ty = 0;
  let dragging = false;
  let lastX = 0, lastY = 0;

  function colorFor(changePct) {
    const maxAbs = 6;
    const t = Math.max(-1, Math.min(1, changePct / maxAbs));
    if (Math.abs(t) < 0.02) return getComputedStyle(document.documentElement).getPropertyValue('--flat').trim();
    const hue = t > 0 ? 135 : 0;
    const sat = 72;
    const light = 34 + Math.abs(t) * 18;
    return `hsl(${hue} ${sat}% ${light}%)`;
  }

  function fmtPrice(v) {
    return v >= 100 ? v.toFixed(2) : v.toFixed(2);
  }

  function render() {
    const visible = state.filter(s =>
      !filter || s.symbol.toLowerCase().includes(filter) || s.company.toLowerCase().includes(filter)
    );

    const cols = Math.max(1, Math.floor(Math.sqrt(visible.length)));
    gridEl.style.gridTemplateColumns = `repeat(${cols}, 140px)`;
    gridEl.innerHTML = "";

    visible.forEach((s) => {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.style.background = colorFor(s.changePct);

      const sparkPath = buildSparkPath(s.history);
      cell.innerHTML = `
        <div class="ticker">${s.symbol}</div>
        <div class="company">${s.company}</div>
        <div class="price-row">
          <div>$${fmtPrice(s.price)}</div>
          <div class="change">${s.changePct >= 0 ? '+' : ''}${s.changePct.toFixed(2)}%</div>
        </div>
        <svg class="spark" viewBox="0 0 100 18" preserveAspectRatio="none" aria-hidden="true">
          <path d="${sparkPath}" fill="none" stroke="rgba(255,255,255,.85)" stroke-width="2" />
        </svg>
      `;
      gridEl.appendChild(cell);
    });

    applyTransform();
  }

  function buildSparkPath(values) {
    const min = Math.min(...values);
    const max = Math.max(...values);
    const span = Math.max(1e-9, max - min);
    return values.map((v, i) => {
      const x = (i / (values.length - 1)) * 100;
      const y = 18 - ((v - min) / span) * 14 - 2;
      return `${i === 0 ? 'M' : 'L'} ${x.toFixed(2)} ${y.toFixed(2)}`;
    }).join(' ');
  }

  function applyTransform() {
    gridEl.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
  }

  function resetView() {
    scale = 1;
    tx = 0;
    ty = 0;
    applyTransform();
  }

  function updateFeed() {
    state.forEach(s => {
      const drift = (Math.random() - 0.5) * 0.012;
      const shock = (Math.random() - 0.5) * 0.06;
      const next = Math.max(1, s.price * (1 + drift + shock * 0.2));
      s.prev = s.price;
      s.price = +next.toFixed(2);
      s.changePct = ((s.price - s.prev) / s.prev) * 100;
      s.history.push(s.price);
      if (s.history.length > 24) s.history.shift();
    });
    render();
    statusEl.textContent = `Updated ${new Date().toLocaleTimeString()} · ${state.length} symbols`;
  }

  let feedTimer = null;
  function startFeed() {
    if (feedTimer) clearInterval(feedTimer);
    feedTimer = setInterval(updateFeed, 1200);
    statusEl.textContent = "Live simulation running";
  }

  viewport.addEventListener('pointerdown', (e) => {
    dragging = true;
    viewport.classList.add('dragging');
    lastX = e.clientX;
    lastY = e.clientY;
    viewport.setPointerCapture(e.pointerId);
  });

  viewport.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    tx += e.clientX - lastX;
    ty += e.clientY - lastY;
    lastX = e.clientX;
    lastY = e.clientY;
    applyTransform();
  });

  viewport.addEventListener('pointerup', () => {
    dragging = false;
    viewport.classList.remove('dragging');
  });

  viewport.addEventListener('wheel', (e) => {
    e.preventDefault();
    const rect = viewport.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    const zoom = Math.exp(-e.deltaY * 0.001);
    const nextScale = Math.min(3, Math.max(0.5, scale * zoom));
    const k = nextScale / scale;
    tx = mx - (mx - tx) * k;
    ty = my - (my - ty) * k;
    scale = nextScale;
    applyTransform();
  }, { passive: false });

  viewport.addEventListener('dblclick', (e) => {
    const rect = viewport.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    tx = rect.width / 2 - mx;
    ty = rect.height / 2 - my;
    scale = 1.2;
    applyTransform();
  });

  searchEl.addEventListener('input', () => {
    filter = searchEl.value.trim().toLowerCase();
    render();
  });

  resetBtn.addEventListener('click', resetView);
  randomizeBtn.addEventListener('click', () => {
    updateFeed();
    startFeed();
  });

  render();
  startFeed();
})();
</script>
</body>
</html>
