  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');

    const state = {
      width: 0,
      height: 0,
      dpr: Math.min(window.devicePixelRatio || 1, 2),
      scale: 1,
      offsetX: 40,
      offsetY: 40,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      lastOffsetX: 0,
      lastOffsetY: 0,
      cells: [],
      hoveredCell: null,
      tick: 0
    };

    const sectors = [
      'Technology', 'Finance', 'Healthcare', 'Energy',
      'Consumer', 'Industrials', 'Utilities', 'Materials'
    ];

    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','ORCL',
      'JPM','BAC','WFC','GS','MS','C','V','MA',
      'UNH','JNJ','PFE','MRK','LLY','ABBV','TMO','DHR',
      'XOM','CVX','COP','SLB','EOG','PSX','MPC','OXY',
      'KO','PEP','MCD','SBUX','COST','WMT','TGT','NKE',
      'CAT','BA','GE','HON','RTX','LMT','DE','UPS',
      'NEE','DUK','SO','EXC','AEP','XEL','ED','SRE',
      'LIN','APD','DD','NEM','FCX','ALB','SHW','ECL'
    ];

    function resize() {
      state.width = window.innerWidth;
      state.height = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      canvas.style.width = state.width + 'px';
      canvas.style.height = state.height + 'px';
      draw();
    }

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function buildData() {
      state.cells = symbols.map((symbol, i) => {
        const price = rand(12, 950);
        const change = rand(-10, 10);
        const volume = Math.floor(rand(100000, 50000000));
        return {
          symbol,
          sector: sectors[i % sectors.length],
          price,
          change,
          volume,
          x: 0,
          y: 0,
          w: 0,
          h: 0
        };
      });
    }

    function updateData() {
      for (const cell of state.cells) {
        const drift = rand(-1.4, 1.4);
        cell.change = clamp(cell.change + drift * 0.25, -15, 15);
        cell.price = Math.max(0.5, cell.price * (1 + drift / 250));
        cell.volume = Math.max(1000, Math.floor(cell.volume * rand(0.98, 1.02)));
      }
      state.tick++;
      draw();
    }

    function colorForChange(change) {
      const t = clamp((change + 10) / 20, 0, 1);
      const hue = t < 0.5
        ? 0 + (120 * t)
        : 120;
      const light = 24 + Math.abs(change) * 1.2;
      if (change < 0) {
        return `hsl(0, ${60 + Math.abs(change) * 2}%, ${light}%)`;
      } else if (change > 0) {
        return `hsl(135, ${45 + change * 2}%, ${light}%)`;
      }
      return '#111827';
    }

    function layoutCells() {
      const margin = 30;
      const gap = 10;
      const cols = Math.max(4, Math.floor(Math.sqrt(state.cells.length)));
      const cellW = 150;
      const cellH = 95;

      state.cells.forEach((cell, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;
        cell.x = margin + col * (cellW + gap);
        cell.y = margin + row * (cellH + gap);
        cell.w = cellW;
        cell.h = cellH;
      });
    }

    function screenToWorld(x, y) {
      return {
        x: (x - state.offsetX) / state.scale,
        y: (y - state.offsetY) / state.scale
      };
    }

    function worldToScreen(x, y) {
      return {
        x: x * state.scale + state.offsetX,
        y: y * state.scale + state.offsetY
      };
    }

    function getCellAtScreen(x, y) {
      const p = screenToWorld(x, y);
      return state.cells.find(cell =>
        p.x >= cell.x && p.x <= cell.x + cell.w &&
        p.y >= cell.y && p.y <= cell.y + cell.h
      ) || null;
    }

    function drawRoundedRect(x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function draw() {
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      ctx.clearRect(0, 0, state.width, state.height);

      // Background grid
      ctx.save();
      ctx.globalAlpha = 0.15;
      ctx.strokeStyle = '#94a3b8';
      ctx.lineWidth = 1;
      const step = 50;
      for (let x = 0; x < state.width; x += step) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, state.height);
        ctx.stroke();
      }
      for (let y = 0; y < state.height; y += step) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(state.width, y);
        ctx.stroke();
      }
      ctx.restore();

      ctx.save();
      ctx.translate(state.offsetX, state.offsetY);
      ctx.scale(state.scale, state.scale);

      for (const cell of state.cells) {
        const isHovered = state.hoveredCell === cell;
        const pad = isHovered ? 3 : 0;

        ctx.fillStyle = colorForChange(cell.change);
        drawRoundedRect(cell.x + pad, cell.y + pad, cell.w - pad * 2, cell.h - pad * 2, 14);
        ctx.fill();

        ctx.strokeStyle = isHovered ? 'rgba(255,255,255,0.85)' : 'rgba(255,255,255,0.12)';
        ctx.lineWidth = isHovered ? 3 : 1;
        ctx.stroke();

        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 18px system-ui, sans-serif';
        ctx.fillText(cell.symbol, cell.x + 14, cell.y + 28);

        ctx.font = '12px system-ui, sans-serif';
        ctx.fillStyle = 'rgba(255,255,255,0.88)';
        ctx.fillText(cell.sector, cell.x + 14, cell.y + 48);

        ctx.font = 'bold 14px system-ui, sans-serif';
        const changeText = `${cell.change >= 0 ? '+' : ''}${cell.change.toFixed(2)}%`;
        ctx.fillStyle = cell.change >= 0 ? '#dcfce7' : '#fee2e2';
        ctx.fillText(changeText, cell.x + 14, cell.y + 72);

        ctx.font = '11px system-ui, sans-serif';
        ctx.fillStyle = 'rgba(255,255,255,0.8)';
        ctx.fillText(`$${cell.price.toFixed(2)}`, cell.x + cell.w - 54, cell.y + 28);
      }

      ctx.restore();
    }

    function showTooltip(cell, x, y) {
      tooltip.style.display = 'block';
      tooltip.style.left = x + 'px';
      tooltip.style.top = y + 'px';
      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong> <span style="color:#94a3b8">(${cell.sector})</span></div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: <span style="color:${cell.change >= 0 ? '#86efac' : '#fca5a5'}">${cell.change >= 0 ? '+' : ''}${cell.change.toFixed(2)}%</span></div>
        <div>Volume: ${cell.volume.toLocaleString()}</div>
      `;
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    canvas.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.lastOffsetX = state.offsetX;
      state.lastOffsetY = state.offsetY;
    });

    window.addEventListener('mousemove', (e) => {
      if (state.dragging) {
        state.offsetX = state.lastOffsetX + (e.clientX - state.dragStartX);
        state.offsetY = state.lastOffsetY + (e.clientY - state.dragStartY);
        draw();
        return;
      }

      const cell = getCellAtScreen(e.clientX, e.clientY);
      state.hoveredCell = cell;
      if (cell) {
        showTooltip(cell, e.clientX, e.clientY);
      } else {
        hideTooltip();
      }
      draw();
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomIntensity = 0.0015;
      const delta = -e.deltaY;
      const zoom = Math.exp(delta * zoomIntensity);

      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const before = screenToWorld(mouseX, mouseY);
      state.scale = clamp(state.scale * zoom, 0.4, 4);
      const after = screenToWorld(mouseX, mouseY);

      state.offsetX += (after.x - before.x) * state.scale;
      state.offsetY += (after.y - before.y) * state.scale;

      draw();
    }, { passive: false });

    canvas.addEventListener('click', (e) => {
      const cell = getCellAtScreen(e.clientX, e.clientY);
      if (cell) {
        console.log('Clicked stock:', cell);
      }
    });

    window.addEventListener('resize', resize);

    buildData();
    layoutCells();
    resize();
    setInterval(updateData, 1000);
  </script>
