    // Generate sample stocks
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","AVGO","COST","NFLX",
      "AMD","INTC","QCOM","ADBE","CRM","ORCL","CSCO","TXN","IBM","SAP",
      "PYPL","UBER","DIS","BKNG","SBUX","MCD","JPM","BAC","WMT","V",
      "MA","HD","LOW","XOM","CVX","PFE","MRK","JNJ","UNH","TMO",
      "LLY","NKE","SONY","SPOT","SHOP","SQ","BA","GE","CAT","RTX",
      "PLTR","SNOW","PANW","ZS","OKTA","NET","CRWD","DELL","HPQ","SMCI"
    ];

    const stocks = symbols.map((symbol, i) => {
      const base = 50 + Math.random() * 450;
      return {
        symbol,
        price: base,
        prev: base,
        changePct: 0,
        volume: Math.floor(1e6 + Math.random() * 20e6),
        sector: ["Tech", "Finance", "Retail", "Energy", "Healthcare"][i % 5]
      };
    });

    function resize() {
      state.dpr = Math.max(1, window.devicePixelRatio || 1);
      state.width = Math.floor(window.innerWidth);
      state.height = Math.floor(window.innerHeight);

      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      canvas.style.width = state.width + "px";
      canvas.style.height = state.height + "px";

      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function formatPrice(v) {
      return "$" + v.toFixed(2);
    }

    function formatPct(v) {
      return (v >= 0 ? "+" : "") + v.toFixed(2) + "%";
    }

    function colorForChange(pct) {
      const abs = Math.min(1, Math.abs(pct) / 5);
      if (pct > 0) {
        // red -> green-ish is not used; brighten green
        return `rgba(${Math.round(30 + 35 * abs)}, ${Math.round(120 + 110 * abs)}, ${Math.round(50 + 30 * abs)}, 1)`;
      } else if (pct < 0) {
        return `rgba(${Math.round(130 + 110 * abs)}, ${Math.round(35 + 25 * abs)}, ${Math.round(35 + 20 * abs)}, 1)`;
      }
      return "rgba(120, 120, 120, 1)";
    }

    function updateStocks() {
      // Simulate real-time update
      for (const s of stocks) {
        s.prev = s.price;
        const drift = (Math.random() - 0.5) * 0.8;
        const shock = (Math.random() - 0.5) * 2.2;
        const move = (drift + shock) * (0.2 + s.price / 500);
        s.price = Math.max(1, s.price + move);
        s.changePct = ((s.price - s.prev) / s.prev) * 100;

        // small volume fluctuations
        const volChange = 1 + (Math.random() - 0.5) * 0.05;
        s.volume = Math.max(1000, Math.floor(s.volume * volChange));
      }
      state.tickCount++;
      statusEl.textContent = `Updated ${new Date().toLocaleTimeString()} • ${state.tickCount} ticks`;
    }

    function getLayout() {
      const cols = Math.max(1, Math.floor(Math.sqrt(stocks.length)));
      const rows = Math.ceil(stocks.length / cols);
      return { cols, rows };
    }

    function transformPoint(x, y) {
      return {
        x: (x + state.panX) * state.zoom,
        y: (y + state.panY) * state.zoom
      };
    }

    function inverseTransformPoint(x, y) {
      return {
        x: x / state.zoom - state.panX,
        y: y / state.zoom - state.panY
      };
    }

    function drawRoundedRect(x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    function draw() {
      ctx.clearRect(0, 0, state.width, state.height);

      // background
      const bg = ctx.createLinearGradient(0, 0, 0, state.height);
      bg.addColorStop(0, '#0b1020');
      bg.addColorStop(1, '#111827');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, state.width, state.height);

      const { cols, rows } = getLayout();
      const margin = 18;
      const gap = 8;
      const cellW = 120 * state.zoom;
      const cellH = 72 * state.zoom;

      const totalW = cols * cellW + (cols - 1) * gap * state.zoom;
      const totalH = rows * cellH + (rows - 1) * gap * state.zoom;

      // Center viewport with pan applied
      const startX = (state.width - totalW) / 2 + state.panX * state.zoom;
      const startY = (state.height - totalH) / 2 + state.panY * state.zoom;

      let index = 0;
      state.hovered = null;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          if (index >= stocks.length) break;
          const s = stocks[index];

          const x = startX + c * (cellW + gap * state.zoom);
          const y = startY + r * (cellH + gap * state.zoom);

          // Determine if mouse is over cell
          if (mouseX !== null && mouseY !== null) {
            const mx = mouseX, my = mouseY;
            if (mx >= x && mx <= x + cellW && my >= y && my <= y + cellH) {
              state.hoverIndex = index;
              state.hovered = { stock: s, x, y, w: cellW, h: cellH };
            }
          }

          // cell fill
          const fill = colorForChange(s.changePct);
          ctx.fillStyle = fill;
          drawRoundedRect(x, y, cellW, cellH, 12 * state.zoom);
          ctx.fill();

          // overlay gradient
          const overlay = ctx.createLinearGradient(x, y, x + cellW, y + cellH);
          overlay.addColorStop(0, 'rgba(255,255,255,0.08)');
          overlay.addColorStop(1, 'rgba(0,0,0,0.12)');
          ctx.fillStyle = overlay;
          drawRoundedRect(x, y, cellW, cellH, 12 * state.zoom);
          ctx.fill();

          // selection outline
          if (state.hoverIndex === index || state.pinnedIndex === index) {
            ctx.lineWidth = 3;
            ctx.strokeStyle = state.pinnedIndex === index
              ? 'rgba(255,255,255,0.95)'
              : 'rgba(255,255,255,0.55)';
            drawRoundedRect(x + 1.5, y + 1.5, cellW - 3, cellH - 3, 11 * state.zoom);
            ctx.stroke();
          }

          // text
          ctx.fillStyle = 'rgba(255,255,255,0.96)';
          ctx.font = `${Math.max(11, 14 * state.zoom)}px system-ui, sans-serif`;
          ctx.fillText(s.symbol, x + 12 * state.zoom, y + 24 * state.zoom);

          ctx.font = `${Math.max(10, 12 * state.zoom)}px system-ui, sans-serif`;
          ctx.fillStyle = 'rgba(255,255,255,0.92)';
          ctx.fillText(formatPrice(s.price), x + 12 * state.zoom, y + 44 * state.zoom);

          ctx.fillStyle = 'rgba(255,255,255,0.85)';
          ctx.fillText(formatPct(s.changePct), x + 12 * state.zoom, y + 60 * state.zoom);

          index++;
        }
      }

      // tooltip
      if (state.hovered) {
        tooltip.style.display = 'block';
        tooltip.innerHTML = `
          <strong>${state.hovered.stock.symbol}</strong><br/>
          Price: ${formatPrice(state.hovered.stock.price)}<br/>
          Change: ${formatPct(state.hovered.stock.changePct)}<br/>
          Volume: ${state.hovered.stock.volume.toLocaleString()}<br/>
          Sector: ${state.hovered.stock.sector}
        `;
        tooltip.style.left = mouseX + 'px';
        tooltip.style.top = mouseY + 'px';
      } else {
        tooltip.style.display = 'none';
      }

      if (state.animating) requestAnimationFrame(draw);
    }

    let mouseX = null;
    let mouseY = null;

    app.addEventListener('mousemove', (e) => {
      mouseX = e.clientX;
      mouseY = e.clientY;

      if (state.dragging) {
        const dx = (e.clientX - state.lastX) / state.zoom;
        const dy = (e.clientY - state.lastY) / state.zoom;
        state.panX += dx;
        state.panY += dy;
        state.lastX = e.clientX;
        state.lastY = e.clientY;
      }
    });

    app.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
    });

    app.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const nextZoom = clamp(state.zoom * zoomFactor, state.minZoom, state.maxZoom);

      // Zoom around mouse cursor
      const worldBefore = inverseTransformPoint(mx, my);
      state.zoom = nextZoom;
      const worldAfter = inverseTransformPoint(mx, my);

      state.panX += worldAfter.x - worldBefore.x;
      state.panY += worldAfter.y - worldBefore.y;
    }, { passive: false });

    app.addEventListener('click', (e) => {
      if (state.hoverIndex >= 0) {
        state.pinnedIndex = state.pinnedIndex === state.hoverIndex ? -1 : state.hoverIndex;
      }
    });

    resetBtn.addEventListener('click', () => {
      state.zoom = 1;
      state.panX = 0;
      state.panY = 0;
      state.pinnedIndex = -1;
    });

    window.addEventListener('resize', resize);

    // Initial render/update loop
    resize();
    updateStocks();
    setInterval(updateStocks, 1000);

    // Start animation loop
    requestAnimationFrame(draw);
  </script>
</body>
</html>
