<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="meta" id="status">Connecting…</div>
      <button id="resetZoom">Reset Zoom</button>
      <div class="legend">
        <span>Change</span>
        <div class="legend-bar"></div>
        <span>−5% to +5%</span>
