  <script>
    const svg = d3.select("#chart");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const resetZoomBtn = document.getElementById("resetZoom");

    const width = () => document.querySelector(".chart-wrap").clientWidth;
    const height = () => document.querySelector(".chart-wrap").clientHeight;

    // Sample stock universe
    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","NFLX","AMD","INTC",
      "JPM","BAC","XOM","CVX","WMT","COST","KO","PEP","DIS","ADBE",
      "CRM","ORCL","QCOM","AVGO","MCD","BA","IBM","GE","NKE","PYPL"
    ];

    // Data model: one tile per symbol
    const data = symbols.map((symbol, i) => ({
      symbol,
      price: 50 + Math.random() * 450,
      prevClose: 50 + Math.random() * 450,
      volume: Math.floor(1e6 + Math.random() * 2e7),
      sector: ["Tech","Finance","Energy","Consumer","Industrial"][i % 5]
    }));

    const cols = 6;
    const rows = Math.ceil(data.length / cols);

    const margin = { top: 20, right: 20, bottom: 20, left: 20 };

    const gRoot = svg.append("g").attr("class", "root");
    const gGrid = gRoot.append("g").attr("class", "grid");
    const gLabels = gRoot.append("g").attr("class", "labels");

    // Zoom behavior
    const zoom = d3.zoom()
      .scaleExtent([0.8, 10])
      .on("zoom", (event) => {
        gRoot.attr("transform", event.transform);
      });

    svg.call(zoom);

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(350).call(zoom.transform, d3.zoomIdentity);
    });

    function colorForChange(changePct) {
      // Diverging palette centered at 0
      const scale = d3.scaleLinear()
        .domain([-5, -2.5, 0, 2.5, 5])
        .range(["#b91c1c", "#f97316", "#334155", "#22c55e", "#15803d"])
        .clamp(true);
      return scale(changePct);
    }

    function render() {
      const w = width();
      const h = height();

      svg.attr("viewBox", `0 0 ${w} ${h}`);

      const cellW = (w - margin.left - margin.right) / cols;
      const cellH = (h - margin.top - margin.bottom) / rows;
      const size = Math.min(cellW, cellH);

      // Center grid
      const gridW = cols * size;
      const gridH = rows * size;
      const offsetX = (w - gridW) / 2;
      const offsetY = (h - gridH) / 2;

      const join = gGrid.selectAll("g.cell-group")
        .data(data, d => d.symbol);

      const enter = join.enter()
        .append("g")
        .attr("class", "cell-group")
        .style("cursor", "pointer")
        .on("mousemove", (event, d) => {
          const change = ((d.price - d.prevClose) / d.prevClose) * 100;
          tooltip.innerHTML = `
            <strong>${d.symbol}</strong><br/>
            Price: $${d.price.toFixed(2)}<br/>
            Prev Close: $${d.prevClose.toFixed(2)}<br/>
            Change: ${change >= 0 ? "+" : ""}${change.toFixed(2)}%<br/>
            Volume: ${d.volume.toLocaleString()}<br/>
            Sector: ${d.sector}
          `;
          tooltip.style.opacity = 1;
          tooltip.style.left = `${event.offsetX}px`;
          tooltip.style.top = `${event.offsetY}px`;
        })
        .on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });

      enter.append("rect")
        .attr("class", "cell");

      enter.append("text")
        .attr("class", "label")
        .text(d => d.symbol);

      const merged = enter.merge(join);

      merged.transition().duration(250)
        .attr("transform", (d, i) => {
          const col = i % cols;
          const row = Math.floor(i / cols);
          return `translate(${offsetX + col * size}, ${offsetY + row * size})`;
        });

      merged.select("rect")
        .transition().duration(250)
        .attr("width", size - 6)
        .attr("height", size - 6)
        .attr("x", 3)
        .attr("y", 3)
        .attr("fill", d => {
          const change = ((d.price - d.prevClose) / d.prevClose) * 100;
          return colorForChange(change);
        });

      merged.select("text")
        .attr("x", size / 2)
        .attr("y", size / 2 - 6)
        .style("font-size", `${Math.max(10, size / 7)}px`);

      // Add price text
      const priceJoin = merged.selectAll("text.price")
        .data(d => [d]);

      priceJoin.enter()
        .append("text")
        .attr("class", "label price")
        .merge(priceJoin)
        .attr("x", size / 2)
        .attr("y", size / 2 + 10)
        .style("font-size", `${Math.max(9, size / 8)}px`)
        .text(d => `$${d.price.toFixed(0)}`);

      priceJoin.exit().remove();

      join.exit().remove();

      statusEl.textContent = `Live updates every 1s • ${data.length} symbols • Zoom and pan enabled`;
    }

    // Simulated real-time updates
    function tick() {
      data.forEach(d => {
        // Random walk with mild volatility
        const drift = (Math.random() - 0.5) * 0.02;
        const shock = (Math.random() - 0.5) * 0.01;
        const next = d.price * (1 + drift + shock);

        d.prevClose = d.prevClose * (1 + (Math.random() - 0.5) * 0.001);
        d.price = Math.max(1, next);
        d.volume = Math.max(0, d.volume + Math.floor((Math.random() - 0.5) * 100000));
      });

      render();
    }

    // Initial render + updates
    render();
    window.addEventListener("resize", render);

    statusEl.textContent = "Connected • Live updates every 1s • Zoom and pan enabled";
    setInterval(tick, 1000);

    // Keep tooltip within viewport on mouse move
    document.querySelector(".chart-wrap").addEventListener("mousemove", (e) => {
      const pad = 16;
      const rect = tooltip.getBoundingClientRect();
      let x = e.offsetX + 12;
      let y = e.offsetY + 12;

      if (x + rect.width > e.currentTarget.clientWidth - pad) {
        x = e.offsetX - rect.width - 12;
      }
      if (y + rect.height > e.currentTarget.clientHeight - pad) {
        y = e.offsetY - rect.height - 12;
      }

      tooltip.style.left = `${Math.max(pad, x)}px`;
      tooltip.style.top = `${Math.max(pad, y)}px`;
    });
  </script>
