        <div>-5% → 0 → +5%</div>
      </div>
      <div id="status" style="margin-top:8px;">Initializing...</div>
    </div>
    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    (() => {
      const canvas = document.getElementById('heatmap');
      const ctx = canvas.getContext('2d');
      const tooltip = document.getElementById('tooltip');
      const statusEl = document.getElementById('status');

      const state = {
        dpr: Math.max(1, window.devicePixelRatio || 1),
        width: 0,
        height: 0,
        zoom: 1,
        minZoom: 0.5,
        maxZoom: 5,
        panX: 40,
        panY: 40,
        dragging: false,
        dragStartX: 0,
        dragStartY: 0,
        panStartX: 0,
        panStartY: 0,
        hoveredCell: null,
        lastMouseX: 0,
        lastMouseY: 0,
        cells: [],
        cols: 14,
        rows: 10,
        cellSize: 64,
        gap: 10,
        sourcePriceBase: 100,
        lastUpdateAt: performance.now()
      };

      const symbols = [
        'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','INTC','NFLX',
        'ORCL','CRM','UBER','JPM','BAC','XOM','CVX','KO','PEP','DIS',
        'ADBE','QCOM','AVGO','CSCO','SHOP','SNOW','PLTR','SQ','PYPL','BA',
        'GE','NKE','MCD','WMT','TGT','COST','ABBV','PFE','MRNA','LLY',
        'T','VZ','TMUS','UNH','HD','LOW','SPOT','BABA','SONY','SAP',
        'ASML','ARM','DASH','PANW','ZS','NET','CRWD','OKTA','F','GM'
      ];

      function resize() {
        state.dpr = Math.max(1, window.devicePixelRatio || 1);
        state.width = window.innerWidth;
        state.height = window.innerHeight;
        canvas.width = Math.floor(state.width * state.dpr);
        canvas.height = Math.floor(state.height * state.dpr);
        canvas.style.width = state.width + 'px';
        canvas.style.height = state.height + 'px';
        ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
        render();
      }

      function initCells() {
        const total = state.cols * state.rows;
        const count = Math.min(total, symbols.length);
        state.cells = [];

        for (let i = 0; i < count; i++) {
          const symbol = symbols[i];
          const base = state.sourcePriceBase + Math.random() * 250;
          const changePct = (Math.random() * 10 - 5);
          const price = base * (1 + changePct / 100);
          state.cells.push({
            symbol,
            base,
            price,
            changePct,
            x: i % state.cols,
            y: Math.floor(i / state.cols)
          });
        }
      }

      function updatePrices() {
        for (const cell of state.cells) {
          // Random walk with mild mean reversion
          const drift = (Math.random() - 0.5) * 1.2;
          const meanRevert = -(cell.changePct * 0.02);
          const deltaPct = drift + meanRevert;

          cell.price *= (1 + deltaPct / 100);
          cell.changePct = ((cell.price - cell.base) / cell.base) * 100;
        }
        state.lastUpdateAt = performance.now();
        statusEl.textContent = `Live updates: ${new Date().toLocaleTimeString()}`;
        render();
      }

      function getCellRect(cell) {
        const size = state.cellSize * state.zoom;
        const gap = state.gap * state.zoom;
        const x = state.panX + cell.x * (size + gap);
        const y = state.panY + cell.y * (size + gap);
        return { x, y, size };
      }

      function clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      function changeToColor(pct) {
        const clamped = clamp(pct, -5, 5);
        const t = (clamped + 5) / 10; // 0..1
        // Red -> dark -> green
        const r1 = [239, 68, 68];
        const r2 = [17, 24, 39];
        const g1 = [34, 197, 94];

        let c;
        if (t < 0.5) {
          const u = t / 0.5;
          c = r1.map((v, i) => Math.round(v + (r2[i] - v) * u));
        } else {
          const u = (t - 0.5) / 0.5;
          c = r2.map((v, i) => Math.round(v + (g1[i] - v) * u));
        }
        return `rgb(${c[0]},${c[1]},${c[2]})`;
      }

      function drawText(cell, rect) {
        const isSmall = rect.size < 38;
        ctx.fillStyle = '#fff';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        ctx.font = `${Math.max(10, rect.size * 0.22)}px system-ui, sans-serif`;
        ctx.fillText(cell.symbol, rect.x + rect.size / 2, rect.y + rect.size * 0.36);

        if (!isSmall) {
          ctx.font = `${Math.max(9, rect.size * 0.16)}px system-ui, sans-serif`;
          ctx.fillStyle = 'rgba(255,255,255,0.85)';
          ctx.fillText(`$${cell.price.toFixed(2)}`, rect.x + rect.size / 2, rect.y + rect.size * 0.58);

          ctx.fillStyle = cell.changePct >= 0 ? '#86efac' : '#fca5a5';
          const sign = cell.changePct >= 0 ? '+' : '';
          ctx.fillText(`${sign}${cell.changePct.toFixed(2)}%`, rect.x + rect.size / 2, rect.y + rect.size * 0.76);
        }
      }

      function render() {
        ctx.clearRect(0, 0, state.width, state.height);

        // Background grid glow
        const grad = ctx.createRadialGradient(
          state.width / 2, state.height / 2, 0,
          state.width / 2, state.height / 2, Math.max(state.width, state.height)
        );
        grad.addColorStop(0, 'rgba(59, 130, 246, 0.08)');
        grad.addColorStop(1, 'rgba(11, 16, 32, 0)');
        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, state.width, state.height);
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, state.width, state.height);

        for (const cell of state.cells) {
          const rect = getCellRect(cell);

          if (rect.x + rect.size < 0 || rect.y + rect.size < 0 || rect.x > state.width || rect.y > state.height) {
            continue;
          }

          ctx.fillStyle = changeToColor(cell.changePct);
          ctx.strokeStyle = 'rgba(255,255,255,0.12)';
          ctx.lineWidth = 1;

          roundRect(ctx, rect.x, rect.y, rect.size, rect.size, 10 * state.zoom);
          ctx.fill();
          ctx.stroke();

          // subtle highlight
          ctx.fillStyle = 'rgba(255,255,255,0.05)';
          roundRect(ctx, rect.x + 1, rect.y + 1, rect.size - 2, rect.size * 0.35, 9 * state.zoom);
          ctx.fill();

          drawText(cell, rect);

          if (state.hoveredCell === cell) {
            ctx.strokeStyle = 'rgba(255,255,255,0.95)';
            ctx.lineWidth = 2;
            roundRect(ctx, rect.x + 1, rect.y + 1, rect.size - 2, rect.size - 2, 10 * state.zoom);
            ctx.stroke();
          }
        }
      }

      function roundRect(ctx, x, y, w, h, r) {
        r = Math.max(0, Math.min(r, Math.min(w, h) / 2));
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.arcTo(x + w, y, x + w, y + h, r);
        ctx.arcTo(x + w, y + h, x, y + h, r);
        ctx.arcTo(x, y + h, x, y, r);
        ctx.arcTo(x, y, x + w, y, r);
        ctx.closePath();
      }

      function screenToWorld(mx, my) {
        return {
          x: (mx - state.panX),
          y: (my - state.panY)
        };
      }

      function hitTest(mx, my) {
        for (const cell of state.cells) {
          const rect = getCellRect(cell);
          if (mx >= rect.x && mx <= rect.x + rect.size && my >= rect.y && my <= rect.y + rect.size) {
            return { cell, rect };
          }
        }
        return null;
      }

      canvas.addEventListener('mousedown', (e) => {
        state.dragging = true;
        state.dragStartX = e.clientX;
        state.dragStartY = e.clientY;
        state.panStartX = state.panX;
        state.panStartY = state.panY;
      });

      window.addEventListener('mouseup', () => {
        state.dragging = false;
      });

      window.addEventListener('mousemove', (e) => {
        state.lastMouseX = e.clientX;
        state.lastMouseY = e.clientY;

        if (state.dragging) {
          state.panX = state.panStartX + (e.clientX - state.dragStartX);
          state.panY = state.panStartY + (e.clientY - state.dragStartY);
          render();
          return;
        }

        const hit = hitTest(e.clientX, e.clientY);
        state.hoveredCell = hit ? hit.cell : null;

        if (hit) {
          tooltip.style.display = 'block';
          tooltip.style.left = (e.clientX + 12) + 'px';
          tooltip.style.top = (e.clientY + 12) + 'px';
          const sign = hit.cell.changePct >= 0 ? '+' : '';
          tooltip.innerHTML = `
            <div><strong>${hit.cell.symbol}</strong></div>
            <div>Price: $${hit.cell.price.toFixed(2)}</div>
            <div>Change: ${sign}${hit.cell.changePct.toFixed(2)}%</div>
          `;
        } else {
          tooltip.style.display = 'none';
        }
        render();
      });

      canvas.addEventListener('wheel', (e) => {
        e.preventDefault();

        const zoomFactor = Math.exp(-e.deltaY * 0.001);
        const oldZoom = state.zoom;
        const newZoom = clamp(oldZoom * zoomFactor, state.minZoom, state.maxZoom);

        const mx = e.clientX;
        const my = e.clientY;

        // Keep cursor point stable while zooming
        const worldX = (mx - state.panX) / oldZoom;
        const worldY = (my - state.panY) / oldZoom;

        state.zoom = newZoom;
        state.panX = mx - worldX * newZoom;
        state.panY = my - worldY * newZoom;

        render();
      }, { passive: false });

      window.addEventListener('resize', resize);

      // Simple live update feed
      setInterval(updatePrices, 1000);

      // Optional: smoother refresh loop for subtle animations
      function animate() {
        render();
        requestAnimationFrame(animate);
      }

      initCells();
      resize();
      updatePrices();
      animate();
    })();
  </script>
</body>
</html>
```

