## Example implementation

### `StockHeatmap.tsx`

```tsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import * as d3 from "d3";

type StockPoint = {
  symbol: string;
  timestamp: number;
  price: number;
  prevPrice: number;
};

type HeatmapCell = StockPoint & {
  changePct: number;
};

const SYMBOLS = [
  "AAPL", "MSFT", "NVDA", "AMZN", "GOOGL",
  "META", "TSLA", "AMD", "NFLX", "INTC",
  "ORCL", "CRM", "ADBE", "QCOM", "AVGO"
];

const ROW_HEIGHT = 34;
const COL_WIDTH = 42;
const LEFT_MARGIN = 90;
const TOP_MARGIN = 40;

function generateInitialData(): StockPoint[] {
  const now = Date.now();
  return SYMBOLS.flatMap((symbol, row) => {
    const base = 100 + Math.random() * 200;
    return Array.from({ length: 48 }, (_, i) => {
      const price = base + Math.sin(i / 4 + row) * 7 + (Math.random() - 0.5) * 5;
      const prevPrice = i === 0 ? price : base + Math.sin((i - 1) / 4 + row) * 7;
      return {
        symbol,
        timestamp: now - (47 - i) * 30_000,
        price,
        prevPrice
      };
    });
  });
}

function toCell(d: StockPoint): HeatmapCell {
  const changePct = d.prevPrice === 0 ? 0 : ((d.price - d.prevPrice) / d.prevPrice) * 100;
  return { ...d, changePct };
}

function colorScale(changePct: number) {
  const scale = d3.scaleLinear<string>()
    .domain([-5, 0, 5])
    .range(["#b91c1c", "#f3f4f6", "#15803d"])
    .clamp(true);

  return scale(changePct);
}

export default function StockHeatmap() {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const [data, setData] = useState<StockPoint[]>(generateInitialData());
  const [hovered, setHovered] = useState<HeatmapCell | null>(null);
  const [dimensions, setDimensions] = useState({ width: 1200, height: 700 });
  const [transform, setTransform] = useState(d3.zoomIdentity);

  const symbols = useMemo(() => SYMBOLS, []);
  const timeBuckets = useMemo(() => {
    const timestamps = Array.from(new Set(data.map(d => d.timestamp))).sort((a, b) => a - b);
    return timestamps;
  }, [data]);

  const cells = useMemo(() => data.map(toCell), [data]);

  useEffect(() => {
    const resize = () => {
      const width = window.innerWidth - 32;
      const height = window.innerHeight - 32;
      setDimensions({ width, height });
    };
    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, []);

  useEffect(() => {
    // Mock real-time updates
    const interval = setInterval(() => {
      setData(prev => {
        const latestTimestamp = Math.max(...prev.map(d => d.timestamp));
        const nextTimestamp = latestTimestamp + 30_000;

        const next = SYMBOLS.map((symbol, idx) => {
          const latest = [...prev].reverse().find(d => d.symbol === symbol);
          const base = latest?.price ?? (100 + Math.random() * 100);
          const delta = (Math.random() - 0.5) * 4;
          const price = Math.max(1, base + delta);

          return {
            symbol,
            timestamp: nextTimestamp,
            price,
            prevPrice: base
          };
        });

        const combined = [...prev, ...next];

        // keep a sliding window
        return combined.filter(d => d.timestamp >= nextTimestamp - 48 * 30_000);
      });
    }, 2000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!svgRef.current) return;

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    const width = dimensions.width;
    const height = dimensions.height;

    svg
      .attr("viewBox", `0 0 ${width} ${height}`)
      .attr("width", width)
      .attr("height", height)
      .style("background", "#111827")
      .style("cursor", "grab");

    const innerWidth = width - LEFT_MARGIN - 20;
    const innerHeight = height - TOP_MARGIN - 20;

    const xScale = d3.scaleBand<string>()
      .domain(timeBuckets.map(String))
      .range([0, innerWidth])
      .padding(0.08);

    const yScale = d3.scaleBand<string>()
      .domain(symbols)
      .range([0, innerHeight])
      .padding(0.12);

    const plot = svg.append("g")
      .attr("transform", `translate(${LEFT_MARGIN},${TOP_MARGIN})`);

    const zoomLayer = plot.append("g")
      .attr("class", "zoom-layer")
      .attr("transform", transform.toString());

    // Background
    plot.append("rect")
      .attr("width", innerWidth)
      .attr("height", innerHeight)
      .attr("fill", "transparent");

    // Grid / cells
    zoomLayer.selectAll("rect.cell")
      .data(cells)
      .join("rect")
      .attr("class", "cell")
      .attr("x", d => xScale(String(d.timestamp)) ?? 0)
      .attr("y", d => yScale(d.symbol) ?? 0)
      .attr("width", xScale.bandwidth())
      .attr("height", yScale.bandwidth())
      .attr("rx", 4)
      .attr("fill", d => colorScale(d.changePct))
      .attr("stroke", "#1f2937")
      .attr("stroke-width", 1)
      .on("mouseenter", (_, d) => setHovered(d))
      .on("mouseleave", () => setHovered(null));

    // Symbol labels
    plot.append("g")
      .selectAll("text.symbol")
      .data(symbols)
      .join("text")
      .attr("class", "symbol")
      .attr("x", -10)
      .attr("y", d => (yScale(d) ?? 0) + yScale.bandwidth() / 2 + 5)
      .attr("text-anchor", "end")
      .attr("fill", "#e5e7eb")
      .attr("font-size", 12)
      .attr("font-family", "sans-serif")
      .text(d => d);

    // Time labels
    const tickEvery = Math.max(1, Math.floor(timeBuckets.length / 8));
    plot.append("g")
      .selectAll("text.time")
      .data(timeBuckets.filter((_, i) => i % tickEvery === 0))
      .join("text")
      .attr("class", "time")
      .attr("x", d => (xScale(String(d)) ?? 0) + xScale.bandwidth() / 2)
      .attr("y", -10)
      .attr("text-anchor", "middle")
      .attr("fill", "#9ca3af")
      .attr("font-size", 11)
      .attr("font-family", "sans-serif")
      .text(d => new Date(d).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }));

    // Axes-like border
    plot.append("rect")
      .attr("width", innerWidth)
      .attr("height", innerHeight)
      .attr("fill", "none")
      .attr("stroke", "#374151")
      .attr("stroke-width", 1);

    // Zoom behavior
    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.5, 8])
      .translateExtent([[0, 0], [width, height]])
      .extent([[0, 0], [width, height]])
      .on("zoom", (event) => {
        setTransform(event.transform);
      });

    svg.call(zoom as any);

    // Drag to pan should feel natural with zoom
    svg.on("dblclick.zoom", null);

    return () => {
      svg.on(".zoom", null);
    };
  }, [cells, dimensions, symbols, timeBuckets, transform]);

  return (
    <div style={{ width: "100vw", height: "100vh", background: "#111827", overflow: "hidden" }}>
      <div style={{ position: "absolute", top: 12, left: 12, zIndex: 10, color: "#e5e7eb", fontFamily: "sans-serif" }}>
        <div style={{ fontSize: 18, fontWeight: 700 }}>Stock Heatmap</div>
        <div style={{ fontSize: 12, color: "#9ca3af" }}>
          Zoom with scroll, pan by dragging, hover for details
        </div>
      </div>

      <svg ref={svgRef} />

      {hovered && (
        <div
          style={{
            position: "fixed",
            left: 16,
            bottom: 16,
            background: "rgba(17,24,39,0.95)",
            color: "#f9fafb",
            border: "1px solid #374151",
            borderRadius: 8,
            padding: 12,
            fontFamily: "sans-serif",
            fontSize: 13,
            minWidth: 220,
            boxShadow: "0 10px 25px rgba(0,0,0,0.35)"
          }}
        >
          <div><strong>{hovered.symbol}</strong></div>
          <div>Time: {new Date(hovered.timestamp).toLocaleString()}</div>
          <div>Price: ${hovered.price.toFixed(2)}</div>
          <div>Prev: ${hovered.prevPrice.toFixed(2)}</div>
          <div>Change: {hovered.changePct >= 0 ? "+" : ""}{hovered.changePct.toFixed(2)}%</div>
        </div>
      )}
    </div>
  );
}
```

