```jsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import * as d3 from "d3";

const SYMBOLS = [
  "AAPL", "MSFT", "GOOGL", "AMZN", "META", "NVDA", "TSLA", "NFLX",
  "BRK.B", "JPM", "V", "MA", "UNH", "XOM", "COST", "PG",
  "HD", "LLY", "AVGO", "C", "KO", "PEP", "ADBE", "CRM"
];

const mockInitialData = SYMBOLS.map((symbol, i) => ({
  symbol,
  price: 100 + i * 10,
  prevClose: 100 + i * 10,
  changePct: 0,
  volume: Math.round(1e6 + Math.random() * 9e6)
}));

function getHeatColor(changePct) {
  // Red for negative, green for positive
  const scale = d3.scaleLinear()
    .domain([-5, 0, 5])
    .range(["#d73027", "#f7f7f7", "#1a9850"])
    .clamp(true);

  return scale(changePct);
}

export default function StockHeatmap() {
  const svgRef = useRef(null);
  const tooltipRef = useRef(null);
  const [data, setData] = useState(mockInitialData);
  const [connected, setConnected] = useState(false);

  // Real-time updates
  useEffect(() => {
    let ws;
    let fallbackTimer;

    try {
      ws = new WebSocket("ws://localhost:8080");

      ws.onopen = () => {
        setConnected(true);
      };

      ws.onmessage = (event) => {
        const msg = JSON.parse(event.data);

        // Expected message shape:
        // { symbol: "AAPL", price: 123.45, volume: 1234567 }
        if (msg?.symbol) {
          setData((prev) =>
            prev.map((item) => {
              if (item.symbol !== msg.symbol) return item;
              const price = Number(msg.price ?? item.price);
              const prevClose = item.prevClose ?? price;
              const changePct = ((price - prevClose) / prevClose) * 100;
              return {
                ...item,
                price,
                volume: msg.volume ?? item.volume,
                changePct
              };
            })
          );
        }
      };

      ws.onerror = () => {
        setConnected(false);
      };

      ws.onclose = () => {
        setConnected(false);
      };
    } catch {
      // ignore
    }

    // Mock fallback updates when no socket is present
    fallbackTimer = window.setInterval(() => {
      setData((prev) =>
        prev.map((item) => {
          const drift = (Math.random() - 0.5) * 1.5;
          const nextPrice = Math.max(1, item.price + drift);
          const changePct = ((nextPrice - item.prevClose) / item.prevClose) * 100;
          return {
            ...item,
            price: nextPrice,
            changePct,
            volume: item.volume + Math.round(Math.random() * 5000)
          };
        })
      );
    }, 1500);

    return () => {
      if (ws) ws.close();
      if (fallbackTimer) clearInterval(fallbackTimer);
    };
  }, []);

  const nodes = useMemo(() => {
    return data.map((d) => ({
      ...d,
      label: `${d.symbol}\n$${d.price.toFixed(2)}`
    }));
  }, [data]);

  // D3 render + zoom/pan
  useEffect(() => {
    const width = 1100;
    const height = 700;
    const cols = 6;
    const gap = 10;
    const padding = 20;

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove();

    svg
      .attr("viewBox", `0 0 ${width} ${height}`)
      .attr("width", "100%")
      .attr("height", "100%")
      .style("display", "block")
      .style("background", "#0f172a")
      .style("borderRadius", "12px")
      .style("overflow", "hidden");

    const g = svg.append("g").attr("class", "zoom-layer");

    const cellWidth = (width - padding * 2 - gap * (cols - 1)) / cols;
    const rows = Math.ceil(nodes.length / cols);
    const cellHeight = (height - padding * 2 - gap * (rows - 1)) / rows;

    const tooltip = d3.select(tooltipRef.current);

    const cell = g
      .selectAll("g.cell")
      .data(nodes, (d) => d.symbol)
      .join("g")
      .attr("class", "cell")
      .attr("transform", (d, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = padding + col * (cellWidth + gap);
        const y = padding + row * (cellHeight + gap);
        return `translate(${x},${y})`;
      });

    cell
      .append("rect")
      .attr("rx", 10)
      .attr("ry", 10)
      .attr("width", cellWidth)
      .attr("height", cellHeight)
      .attr("fill", (d) => getHeatColor(d.changePct))
      .attr("stroke", "rgba(255,255,255,0.08)")
      .attr("stroke-width", 1);

    cell
      .append("text")
      .attr("x", cellWidth / 2)
      .attr("y", cellHeight / 2 - 8)
      .attr("text-anchor", "middle")
      .attr("fill", "#0b1220")
      .attr("font-size", Math.max(12, Math.min(22, cellWidth / 8)))
      .attr("font-weight", 700)
      .attr("pointer-events", "none")
      .text((d) => d.symbol);

    cell
      .append("text")
      .attr("x", cellWidth / 2)
      .attr("y", cellHeight / 2 + 16)
      .attr("text-anchor", "middle")
      .attr("fill", "#0b1220")
      .attr("font-size", Math.max(10, Math.min(18, cellWidth / 10)))
      .attr("pointer-events", "none")
      .text((d) => `$${d.price.toFixed(2)}`);

    cell
      .on("mouseenter", function (event, d) {
        d3.select(this).select("rect").attr("stroke", "#fff").attr("stroke-width", 2);
        tooltip
          .style("opacity", 1)
          .html(`
            <div><strong>${d.symbol}</strong></div>
            <div>Price: $${d.price.toFixed(2)}</div>
            <div>Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%</div>
            <div>Volume: ${d.volume.toLocaleString()}</div>
          `);
      })
      .on("mousemove", function (event) {
        tooltip
          .style("left", `${event.pageX + 12}px`)
          .style("top", `${event.pageY + 12}px`);
      })
      .on("mouseleave", function () {
        d3.select(this).select("rect").attr("stroke", "rgba(255,255,255,0.08)").attr("stroke-width", 1);
        tooltip.style("opacity", 0);
      });

    const zoom = d3.zoom()
      .scaleExtent([0.7, 4])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
      });

    svg.call(zoom);

    // Optional reset on double-click
    svg.on("dblclick.zoom", null);

    return () => {
      svg.on(".zoom", null);
    };
  }, [nodes]);

  return (
    <div style={{ position: "relative", width: "100%", height: "100%", minHeight: 700 }}>
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 12,
          color: "#e2e8f0",
          fontFamily: "system-ui, sans-serif"
        }}
      >
        <div>
          <strong>Stock Heatmap</strong>{" "}
          <span style={{ opacity: 0.75, fontSize: 14 }}>
            {connected ? "• live" : "• fallback/mock updates"}
          </span>
        </div>
        <div style={{ opacity: 0.7, fontSize: 13 }}>
          Scroll to zoom, drag to pan, hover for details
        </div>
      </div>

      <svg ref={svgRef} />

      <div
        ref={tooltipRef}
        style={{
          position: "absolute",
          pointerEvents: "none",
          opacity: 0,
          transition: "opacity 0.12s ease",
          background: "rgba(15, 23, 42, 0.95)",
          color: "#e2e8f0",
          border: "1px solid rgba(255,255,255,0.12)",
          padding: "10px 12px",
          borderRadius: 10,
          fontSize: 13,
          boxShadow: "0 10px 30px rgba(0,0,0,0.35)",
          zIndex: 10,
          whiteSpace: "nowrap"
        }}
      />
    </div>
  );
}
