<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetBtn">Reset View</button>
      <button id="pauseBtn">Pause Stream</button>
      <div class="meta" id="statusText">Connected • streaming updates...</div>
      <div class="legend">
        <span>Return</span>
        <div class="bar"></div>
        <span>High</span>
      </div>
    </div>

    <div class="canvas-wrap" id="wrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const wrap = document.getElementById('wrap');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');
    const pauseBtn = document.getElementById('pauseBtn');
    const statusText = document.getElementById('statusText');
    const ctx = canvas.getContext('2d');

    // Data model: stock tickers x time buckets
    const tickers = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD',
      'NFLX','INTC','ORCL','IBM','CRM','AVGO','QCOM','ADBE',
      'PYPL','CSCO','SNOW','UBER'
    ];

    const timeBuckets = 40; // columns
    const rows = tickers.length;

    // Heat values are normalized returns in range [-1, 1]
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: timeBuckets }, () => 0)
    );

    // Simulated time labels
    const times = Array.from({ length: timeBuckets }, (_, i) => {
      const d = new Date();
      d.setMinutes(d.getMinutes() - (timeBuckets - i - 1));
      return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    });

    const state = {
      zoom: 1,
      offsetX: 0,
      offsetY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startOffsetX: 0,
      startOffsetY: 0,
      paused: false,
      hovered: null,
      dpr: window.devicePixelRatio || 1
    };

    function resize() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * state.dpr);
      canvas.height = Math.floor(rect.height * state.dpr);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      draw();
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForValue(v) {
      // Map [-1,1] to red-yellow-green
      const x = (v + 1) / 2; // 0..1
      let r, g, b;
      if (x < 0.5) {
        const t = x / 0.5;
        // red -> yellow
        r = 215;
        g = Math.round(48 + 190 * t);
        b = 39;
      } else {
        const t = (x - 0.5) / 0.5;
        // yellow -> green
        r = Math.round(254 - 237 * t);
        g = Math.round(224 - 72 * t);
        b = Math.round(139 - 39 * t);
      }
      return `rgb(${r},${g},${b})`;
    }

    function updateTimes() {
      times.shift();
      const d = new Date();
      times.push(d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }

    function ingestRandomTick() {
      // Shift columns to left and append a new time bucket with random walk
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < timeBuckets - 1; c++) {
          data[r][c] = data[r][c + 1];
        }

        const prev = data[r][timeBuckets - 2] || 0;
        const delta = (Math.random() - 0.5) * 0.35;
        const meanRevert = -prev * 0.08;
        const next = clamp(prev + delta + meanRevert, -1, 1);
        data[r][timeBuckets - 1] = next;
      }
      updateTimes();
      draw();
    }

    function draw() {
      const width = canvas.width;
      const height = canvas.height;
      const scale = state.zoom;

      ctx.clearRect(0, 0, width, height);

      // Apply viewport transform
      ctx.save();
      ctx.translate(state.offsetX * state.dpr, state.offsetY * state.dpr);
      ctx.scale(scale, scale);

      const padLeft = 90;
      const padTop = 30;
      const cellW = 32;
      const cellH = 24;
      const x0 = padLeft;
      const y0 = padTop;

      // Background panel
      ctx.fillStyle = '#0f1630';
      ctx.fillRect(0, 0, width / state.dpr / scale, height / state.dpr / scale);

      // Draw column labels
      ctx.fillStyle = 'rgba(232,238,252,0.75)';
      ctx.font = '12px Inter, sans-serif';
      ctx.textAlign = 'center';
      for (let c = 0; c < timeBuckets; c++) {
        const x = x0 + c * cellW + cellW / 2;
        if (x > x0 - cellW && x < (width / state.dpr / scale)) {
          ctx.fillText(times[c], x, 18);
        }
      }

      // Draw rows and cells
      ctx.textAlign = 'right';
      ctx.font = '12px Inter, sans-serif';

      for (let r = 0; r < rows; r++) {
        const y = y0 + r * cellH;
        ctx.fillStyle = 'rgba(232,238,252,0.82)';
        ctx.fillText(tickers[r], x0 - 10, y + cellH * 0.68);

        for (let c = 0; c < timeBuckets; c++) {
          const x = x0 + c * cellW;
          const v = data[r][c];
          ctx.fillStyle = colorForValue(v);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // subtle overlay grid
          ctx.strokeStyle = 'rgba(255,255,255,0.08)';
          ctx.strokeRect(x, y, cellW - 1, cellH - 1);
        }
      }

      // Hover highlight
      if (state.hovered) {
        const { row, col } = state.hovered;
        const x = x0 + col * cellW;
        const y = y0 + row * cellH;
        ctx.strokeStyle = 'rgba(76,201,240,0.95)';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, cellW - 3, cellH - 3);
      }

      ctx.restore();
    }

    function canvasToDataCoords(clientX, clientY) {
      const rect = wrap.getBoundingClientRect();
      const x = (clientX - rect.left - state.offsetX) / state.zoom;
      const y = (clientY - rect.top - state.offsetY) / state.zoom;
      return { x, y };
    }

    function findCell(clientX, clientY) {
      const { x, y } = canvasToDataCoords(clientX, clientY);
      const padLeft = 90;
      const padTop = 30;
      const cellW = 32;
      const cellH = 24;

      const col = Math.floor((x - padLeft) / cellW);
      const row = Math.floor((y - padTop) / cellH);

      if (row >= 0 && row < rows && col >= 0 && col < timeBuckets) {
        const cellX = padLeft + col * cellW;
        const cellY = padTop + row * cellH;
        return { row, col, cellX, cellY };
      }
      return null;
    }

    wrap.addEventListener('mousedown', (e) => {
      state.dragging = true;
      wrap.classList.add('dragging');
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startOffsetX = state.offsetX;
      state.startOffsetY = state.offsetY;
    });

    window.addEventListener('mousemove', (e) => {
      if (state.dragging) {
        state.offsetX = state.startOffsetX + (e.clientX - state.dragStartX);
        state.offsetY = state.startOffsetY + (e.clientY - state.dragStartY);
        draw();
      }

      const cell = findCell(e.clientX, e.clientY);
      state.hovered = cell ? { row: cell.row, col: cell.col } : null;

      if (cell) {
        const v = data[cell.row][cell.col];
        tooltip.style.display = 'block';
        tooltip.style.left = e.clientX + 'px';
        tooltip.style.top = e.clientY + 'px';
        tooltip.innerHTML = `
          <div><strong>${tickers[cell.row]}</strong></div>
          <div>Time: ${times[cell.col]}</div>
          <div>Return: ${(v * 100).toFixed(2)}%</div>
        `;
      } else {
        tooltip.style.display = 'none';
      }
      draw();
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      wrap.classList.remove('dragging');
    });

    wrap.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY > 0 ? 0.9 : 1.1;
      const prevZoom = state.zoom;
      const nextZoom = clamp(prevZoom * zoomFactor, 0.7, 3);

      const rect = wrap.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      // Zoom toward cursor
      state.offsetX = mx - ((mx - state.offsetX) / prevZoom) * nextZoom;
      state.offsetY = my - ((my - state.offsetY) / prevZoom) * nextZoom;
      state.zoom = nextZoom;

      draw();
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      state.zoom = 1;
      state.offsetX = 0;
      state.offsetY = 0;
      draw();
    });

    pauseBtn.addEventListener('click', () => {
      state.paused = !state.paused;
      pauseBtn.textContent = state.paused ? 'Resume Stream' : 'Pause Stream';
      statusText.textContent = state.paused ? 'Stream paused' : 'Connected • streaming updates...';
    });

    window.addEventListener('resize', resize);

    // Seed with initial random data
    for (let r = 0; r < rows; r++) {
      let v = (Math.random() - 0.5) * 0.4;
      for (let c = 0; c < timeBuckets; c++) {
        v = clamp(v + (Math.random() - 0.5) * 0.2, -1, 1);
        data[r][c] = v;
      }
    }

    resize();
    draw();

    // Simulated real-time stream
    setInterval(() => {
      if (!state.paused) ingestRandomTick();
    }, 1000);
  </script>
</body>
</html>
