        x: (x - offsetX) / (cellW * scale),
        y: (y - offsetY) / (cellH * scale)
      };
    }

    // --- Interaction: zoom ---
    container.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = container.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const before = screenToWorld(mx, my);

      const zoomFactor = e.deltaY < 0 ? 1.12 : 0.89;
      scale = clamp(scale * zoomFactor, 0.4, 6);

      const after = worldToScreen(before.x, before.y);

      // keep pointer position stable
      offsetX += mx - after.x;
      offsetY += my - after.y;

      render();
    }, { passive: false });

    // --- Interaction: pan ---
    container.addEventListener("mousedown", (e) => {
      isDragging = true;
      container.classList.add("dragging");
      dragStart = { x: e.clientX, y: e.clientY };
      dragOffsetStart = { x: offsetX, y: offsetY };
    });

    window.addEventListener("mousemove", (e) => {
      const rect = container.getBoundingClientRect();
      mousePos = { x: e.clientX - rect.left, y: e.clientY - rect.top };

      if (isDragging) {
        offsetX = dragOffsetStart.x + (e.clientX - dragStart.x);
        offsetY = dragOffsetStart.y + (e.clientY - dragStart.y);
        render();
      } else {
        updateHover();
      }
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      container.classList.remove("dragging");
    });

    container.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
      hoveredCell = null;
    });

    function updateHover() {
      const wp = screenToWorld(mousePos.x, mousePos.y);
      const col = Math.floor(wp.x);
      const row = Math.floor(wp.y);

      if (row >= 0 && row < stocks.length && col >= 0 && col < timeBuckets) {
        hoveredCell = { row, col };
        const cell = data[row][col];
        tooltip.style.display = "block";
        tooltip.style.left = mousePos.x + "px";
        tooltip.style.top = mousePos.y + "px";
        tooltip.innerHTML = `
          <div><strong>${stocks[row]}</strong></div>
          <div>Time bucket: ${col}</div>
          <div>Price: $${cell.price.toFixed(2)}</div>
          <div>Change: ${cell.change >= 0 ? "+" : ""}${cell.change.toFixed(2)}</div>
        `;
        render();
      } else {
        hoveredCell = null;
        tooltip.style.display = "none";
        render();
      }
    }

    // --- Real-time simulated updates ---
    function pushUpdate() {
      // shift left, append latest values
      for (let r = 0; r < stocks.length; r++) {
        data[r].shift();

        const prev = data[r][data[r].length - 1];
        const change = (Math.random() - 0.5) * 2.4; // -1.2 to +1.2
        const price = Math.max(1, prev.price + change);

        data[r].push({ price, change });
      }

      render();
    }

    let updateTimer = setInterval(pushUpdate, 700);

    // --- Rendering ---
    function render() {
      const rect = container.getBoundingClientRect();
      ctx.clearRect(0, 0, rect.width, rect.height);

      // background grid
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, rect.width, rect.height);

      const startCol = Math.max(0, Math.floor((-offsetX) / (cellW * scale)) - 1);
      const endCol = Math.min(timeBuckets - 1, Math.ceil((rect.width - offsetX) / (cellW * scale)) + 1);
      const startRow = Math.max(0, Math.floor((-offsetY) / (cellH * scale)) - 1);
      const endRow = Math.min(stocks.length - 1, Math.ceil((rect.height - offsetY) / (cellH * scale)) + 1);

      // draw cells
      for (let r = startRow; r <= endRow; r++) {
        for (let c = startCol; c <= endCol; c++) {
          const cell = data[r][c];
          const x = offsetX + c * cellW * scale;
          const y = offsetY + r * cellH * scale;
          const w = cellW * scale;
          const h = cellH * scale;

          ctx.fillStyle = getColor(cell.change);
          ctx.fillRect(x, y, w - 1, h - 1);

          if (hoveredCell && hoveredCell.row === r && hoveredCell.col === c) {
            ctx.strokeStyle = "#f9fafb";
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, w - 3, h - 3);
          }
        }
      }

      // draw labels on left when zoomed in enough
      if (scale > 0.8) {
        ctx.fillStyle = "#cbd5e1";
        ctx.font = "11px system-ui";
        ctx.textBaseline = "middle";
        for (let r = startRow; r <= endRow; r++) {
          const y = offsetY + r * cellH * scale + (cellH * scale) / 2;
          if (y > 0 && y < rect.height) ctx.fillText(stocks[r], 6, y);
        }
      }

      // axes hint
      ctx.fillStyle = "rgba(255,255,255,0.45)";
      ctx.font = "12px system-ui";
      ctx.fillText(`Zoom: ${scale.toFixed(2)}x`, 12, 18);
    }

    // --- Init ---
    resize();
    render();

    // Optional: expose controls for debugging
    window.heatmap = {
      data,
      setLiveUpdates(on) {
        clearInterval(updateTimer);
        if (on) updateTimer = setInterval(pushUpdate, 700);
        status.textContent = `Live updates: ${on ? "ON" : "OFF"}`;
      },
      resetView() {
        scale = 1;
        offsetX = 0;
        offsetY = 0;
        render();
      }
    };
  </script>
</body>
</html>
```

