<body>
  <div id="app">
    <div class="toolbar">
      <h1>Interactive Stock Price Heatmap</h1>
      <div class="status" id="status">Loading...</div>
      <div class="spacer"></div>
      <div class="legend">
        <span>-%</span>
        <div class="legend-bar"></div>
        <span>+%</span>
      </div>
      <button id="resetBtn">Reset View</button>
    </div>

    <div class="main" id="main">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const main = document.getElementById('main');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');

    // ---------- Data model ----------
    const symbols = [
      'AAPL', 'MSFT', 'NVDA', 'AMZN', 'GOOGL',
      'META', 'TSLA', 'AMD', 'INTC', 'NFLX',
      'JPM', 'BAC', 'XOM', 'CVX', 'KO',
      'PEP', 'WMT', 'COST', 'DIS', 'UBER'
    ];

    const state = {
      // Each row = stock, each column = time bucket
      data: [], // [{symbol, prices: [{t, price, changePct}]}]
      maxColumns: 120,
      timeStepMs: 1000,
      cellBaseSize: 18,
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      panStartX: 0,
      panStartY: 0,
      hoverCell: null,
      lastTick: Date.now()
    };

    const basePrices = new Map();
    symbols.forEach(sym => basePrices.set(sym, 100 + Math.random() * 200));

    function initData() {
      state.data = symbols.map(symbol => ({
        symbol,
        prices: []
      }));

      const now = Date.now();
      for (let i = state.maxColumns - 1; i >= 0; i--) {
        const t = now - i * state.timeStepMs;
        symbols.forEach((symbol, rowIdx) => {
          const series = state.data[rowIdx].prices;
          const prevPrice = series.length
            ? series[series.length - 1].price
            : basePrices.get(symbol);

          const nextPrice = simulatePrice(prevPrice, symbol);
          const changePct = ((nextPrice - prevPrice) / prevPrice) * 100;
          series.push({ t, price: nextPrice, changePct });
        });
      }
    }

    function simulatePrice(prev, symbol) {
      const drift = (Math.random() - 0.5) * 1.5;
      const volatility = Math.random() * 2.2;
      const direction = Math.random() < 0.5 ? -1 : 1;
      let next = prev + drift + direction * volatility * 0.6;
      next = Math.max(1, next);
      return next;
    }

    function addTick() {
      const t = Date.now();
      state.data.forEach((row, i) => {
        const prev = row.prices[row.prices.length - 1].price;
        const next = simulatePrice(prev, row.symbol);
        const changePct = ((next - prev) / prev) * 100;
        row.prices.push({ t, price: next, changePct });
        if (row.prices.length > state.maxColumns) row.prices.shift();
      });
      state.lastTick = t;
      statusEl.textContent = `Live updates: ${new Date(t).toLocaleTimeString()}`;
    }

    // ---------- Canvas sizing ----------
    function resize() {
      const dpr = window.devicePixelRatio || 1;
      const rect = main.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      render();
    }

    window.addEventListener('resize', resize);

    // ---------- Rendering ----------
    function changeToColor(changePct) {
      // Clamp to reasonable range
      const maxAbs = 4.0;
      const x = Math.max(-maxAbs, Math.min(maxAbs, changePct)) / maxAbs; // -1..1

      // Red -> White -> Green
      if (x < 0) {
        const t = x + 1; // 0..1
        return lerpColor([215, 48, 39], [247, 247, 247], t);
      } else {
        const t = x;
        return lerpColor([247, 247, 247], [26, 152, 80], t);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r}, ${g}, ${b2})`;
    }

    function render() {
      const width = main.clientWidth;
      const height = main.clientHeight;
      ctx.clearRect(0, 0, width, height);

      const rows = state.data.length;
      const cols = state.maxColumns;
      const baseSize = state.cellBaseSize * state.zoom;
      const cellW = baseSize;
      const cellH = baseSize;

      // Content dimensions
      const contentW = cols * cellW;
      const contentH = rows * cellH;

      // Clamp pan so some content stays visible
      const minPanX = Math.min(0, width - contentW - 100);
      const minPanY = Math.min(0, height - contentH - 100);
      state.panX = Math.max(minPanX, Math.min(100, state.panX));
      state.panY = Math.max(minPanY, Math.min(100, state.panY));

      // Background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);

      // Draw grid
      ctx.save();
      ctx.translate(state.panX, state.panY);

      for (let r = 0; r < rows; r++) {
        const row = state.data[r];
        for (let c = 0; c < row.prices.length; c++) {
          const cell = row.prices[c];
          const x = c * cellW;
          const y = r * cellH;

          if (x + cellW < 0 || y + cellH < 0 || x > width || y > height) continue;

          ctx.fillStyle = changeToColor(cell.changePct);
          ctx.fillRect(x, y, cellW, cellH);

          // subtle borders
          ctx.strokeStyle = 'rgba(255,255,255,0.06)';
          ctx.strokeRect(x, y, cellW, cellH);
        }
      }

      // Row labels
      ctx.fillStyle = '#d8e1ff';
      ctx.font = `${Math.max(10, 11 * state.zoom)}px system-ui`;
      ctx.textBaseline = 'middle';

      for (let r = 0; r < rows; r++) {
        const y = r * cellH + cellH / 2;
        if (y < -20 || y > height + 20) continue;
        ctx.fillText(state.data[r].symbol, 8, y);
      }

      ctx.restore();

      // Hover highlight
      if (state.hoverCell) {
        const { row, col } = state.hoverCell;
        const x = state.panX + col * cellW;
        const y = state.panY + row * cellH;

        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, cellW - 2, cellH - 2);
      }

      requestAnimationFrame(() => {});
    }

    // ---------- Interaction ----------
    function getCellFromPointer(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left - state.panX;
      const y = clientY - rect.top - state.panY;

      const cellSize = state.cellBaseSize * state.zoom;
      const col = Math.floor(x / cellSize);
      const row = Math.floor(y / cellSize);

      if (row < 0 || row >= state.data.length) return null;
      if (col < 0 || col >= state.maxColumns) return null;
      const rowData = state.data[row];
      if (col >= rowData.prices.length) return null;

      return { row, col, cellSize };
    }

    canvas.addEventListener('pointerdown', (e) => {
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.panStartX = state.panX;
      state.panStartY = state.panY;
      canvas.setPointerCapture(e.pointerId);
    });

    canvas.addEventListener('pointermove', (e) => {
      const cell = getCellFromPointer(e.clientX, e.clientY);

      if (state.dragging) {
        const dx = e.clientX - state.dragStartX;
        const dy = e.clientY - state.dragStartY;
        state.panX = state.panStartX + dx;
        state.panY = state.panStartY + dy;
        render();
        tooltip.classList.remove('visible');
        return;
      }

      state.hoverCell = cell;
      if (cell) {
        const row = state.data[cell.row];
        const item = row.prices[cell.col];
        tooltip.innerHTML = `
          <strong>${row.symbol}</strong><br/>
          Time: ${new Date(item.t).toLocaleTimeString()}<br/>
          Price: $${item.price.toFixed(2)}<br/>
          Change: <span style="color:${item.changePct >= 0 ? '#1a9850' : '#d73027'}">
            ${item.changePct >= 0 ? '+' : ''}${item.changePct.toFixed(2)}%
          </span>
        `;
        tooltip.style.left = `${e.clientX}px`;
        tooltip.style.top = `${e.clientY}px`;
        tooltip.classList.add('visible');
      } else {
        tooltip.classList.remove('visible');
      }
      render();
    });

    canvas.addEventListener('pointerup', (e) => {
      state.dragging = false;
      try { canvas.releasePointerCapture(e.pointerId); } catch {}
    });

    canvas.addEventListener('pointerleave', () => {
      state.hoverCell = null;
      tooltip.classList.remove('visible');
      render();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY > 0 ? 0.92 : 1.08;
      const oldZoom = state.zoom;
      const newZoom = Math.max(0.5, Math.min(3.0, state.zoom * zoomFactor));

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Zoom around cursor
      const worldX = (mouseX - state.panX) / oldZoom;
      const worldY = (mouseY - state.panY) / oldZoom;

      state.zoom = newZoom;
      state.panX = mouseX - worldX * newZoom;
      state.panY = mouseY - worldY * newZoom;

      render();
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      state.zoom = 1;
      state.panX = 0;
      state.panY = 0;
      render();
    });

    // ---------- Start ----------
    initData();
    resize();
    statusEl.textContent = `Live updates enabled: ${new Date().toLocaleTimeString()}`;
    render();
    setInterval(() => {
      addTick();
      render();
    }, state.timeStepMs);
  </script>
</body>
</html>
