      border: 1px solid #2a3558;
    }

    .viewport {
      position: relative;
      flex: 1;
      overflow: hidden;
      touch-action: none;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    canvas.grabbing {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(8, 12, 24, 0.95);
      color: var(--text);
      border: 1px solid #2a3558;
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      line-height: 1.35;
      box-shadow: 0 10px 30px rgba(0,0,0,0.35);
      transform: translate(12px, 12px);
      white-space: nowrap;
      display: none;
    }

    .tooltip b {
      color: white;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="status" id="status">Connecting to stream…</div>
      <div class="legend">
        <span>Down</span>
        <div class="legend-bar"></div>
        <span>Up</span>
      </div>
    </div>
    <div class="viewport" id="viewport">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const viewport = document.getElementById('viewport');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    // ---------- Data model ----------
    const STOCKS = [
      'AAPL', 'MSFT', 'NVDA', 'AMZN', 'GOOGL', 'META', 'TSLA', 'AMD',
      'NFLX', 'INTC', 'CRM', 'ORCL', 'UBER', 'SHOP', 'COST', 'JPM'
    ];
    const TIME_BUCKETS = 180; // horizontal samples
    const VISIBLE_STOCKS = STOCKS.length;

    // Each cell is a normalized price change from -1 to 1.
    const data = Array.from({ length: VISIBLE_STOCKS }, () =>
      Array.from({ length: TIME_BUCKETS }, () => (Math.random() - 0.5) * 0.2)
    );

    // Simulated base price for each stock.
    const basePrices = Object.fromEntries(
      STOCKS.map(s => [s, 50 + Math.random() * 400])
    );

    // ---------- View state ----------
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    const minScale = 0.8;
    const maxScale = 8;

    let dpr = Math.max(1, window.devicePixelRatio || 1);
    let width = 0, height = 0;

    // ---------- Interaction state ----------
    let dragging = false;
    let lastX = 0, lastY = 0;

    // ---------- Utility ----------
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function resizeCanvas() {
      const rect = viewport.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';
      render();
    }

    // Map heat value to color.
    function valueToColor(v) {
      // v is expected roughly in [-1, 1]
      const clamped = clamp(v, -1, 1);
      const t = Math.abs(clamped);
      const alpha = 0.25 + 0.75 * t;

      if (clamped > 0) {
        // green
        const g = Math.round(120 + 100 * t);
        return `rgba(54, 179, 126, ${alpha})`;
      } else if (clamped < 0) {
        // red
        const r = Math.round(180 + 55 * t);
        return `rgba(196, 69, 69, ${alpha})`;
      }
      return `rgba(120, 130, 150, 0.15)`;
    }

    function drawGridLines(cellW, cellH, startCol, endCol, startRow, endRow) {
      ctx.strokeStyle = '#1f2a4d';
      ctx.lineWidth = 1;

      ctx.beginPath();
      for (let c = startCol; c <= endCol; c++) {
        const x = c * cellW;
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
      }
      for (let r = startRow; r <= endRow; r++) {
        const y = r * cellH;
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
      }
      ctx.stroke();
    }

    function render() {
      const logicalW = canvas.width / dpr;
      const logicalH = canvas.height / dpr;

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, logicalW, logicalH);

      // Background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, logicalW, logicalH);

      const cellW = 24 * scale;
      const cellH = 24 * scale;

      const colsVisible = Math.ceil(width / cellW) + 2;
      const rowsVisible = Math.ceil(height / cellH) + 2;

      const startCol = clamp(Math.floor(-offsetX / cellW), 0, TIME_BUCKETS - 1);
      const startRow = clamp(Math.floor(-offsetY / cellH), 0, VISIBLE_STOCKS - 1);

      const endCol = clamp(startCol + colsVisible, 0, TIME_BUCKETS - 1);
      const endRow = clamp(startRow + rowsVisible, 0, VISIBLE_STOCKS - 1);

      for (let r = startRow; r <= endRow; r++) {
        for (let c = startCol; c <= endCol; c++) {
          const x = offsetX + c * cellW;
          const y = offsetY + r * cellH;
          const v = data[r][c];

          ctx.fillStyle = valueToColor(v);
          ctx.fillRect(x, y, cellW, cellH);
        }
      }

      // Draw labels when zoomed enough
      if (scale >= 1.2) {
        ctx.fillStyle = '#dbe4ff';
        ctx.font = `${12 * scale}px system-ui, sans-serif`;
        ctx.textBaseline = 'middle';

        for (let r = startRow; r <= endRow; r++) {
          const y = offsetY + r * cellH + cellH / 2;
          if (y < -20 || y > height + 20) continue;
          ctx.fillText(STOCKS[r], 8, y);
        }
      }

      // Grid
      drawGridLines(cellW, cellH, startCol, endCol, startRow, endRow);
    }

    // ---------- Real-time updates ----------
    function pushUpdate() {
      for (let r = 0; r < VISIBLE_STOCKS; r++) {
        // shift left
        data[r].shift();

        // random walk update based on previous value
        const prev = data[r][data[r].length - 1];
        const noise = (Math.random() - 0.5) * 0.22;
        const drift = (Math.random() - 0.5) * 0.04;
        let next = prev * 0.85 + noise + drift;
        next = clamp(next, -1, 1);

        data[r].push(next);
      }

      const avg = data.flat().reduce((a, b) => a + b, 0) / (VISIBLE_STOCKS * TIME_BUCKETS);
      statusEl.textContent = `Live stream active • Avg sentiment: ${avg.toFixed(3)}`;
      render();
    }

    // ---------- Pointer interactions ----------
    function screenToCell(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left - offsetX;
      const y = clientY - rect.top - offsetY;
      const cellW = 24 * scale;
      const cellH = 24 * scale;
      const c = Math.floor(x / cellW);
      const r = Math.floor(y / cellH);
      return { c, r, cellW, cellH };
    }

    canvas.addEventListener('pointerdown', (e) => {
      dragging = true;
      canvas.classList.add('grabbing');
      lastX = e.clientX;
      lastY = e.clientY;
      canvas.setPointerCapture(e.pointerId);
    });

    canvas.addEventListener('pointermove', (e) => {
      if (dragging) {
        const dx = e.clientX - lastX;
        const dy = e.clientY - lastY;
        lastX = e.clientX;
        lastY = e.clientY;
        offsetX += dx;
        offsetY += dy;
        render();
        return;
      }

      const { c, r, cellW, cellH } = screenToCell(e.clientX, e.clientY);
      if (r >= 0 && r < VISIBLE_STOCKS && c >= 0 && c < TIME_BUCKETS) {
        const rect = canvas.getBoundingClientRect();
        const x = offsetX + c * cellW;
        const y = offsetY + r * cellH;
        const v = data[r][c];

        tooltip.style.display = 'block';
        tooltip.style.left = `${e.clientX - rect.left}px`;
        tooltip.style.top = `${e.clientY - rect.top}px`;
        tooltip.innerHTML = `
          <b>${STOCKS[r]}</b><br/>
          Bucket: ${c}<br/>
          Value: ${v.toFixed(3)}
        `;
      } else {
        tooltip.style.display = 'none';
      }
    });

    canvas.addEventListener('pointerup', (e) => {
      dragging = false;
      canvas.classList.remove('grabbing');
      try { canvas.releasePointerCapture(e.pointerId); } catch {}
    });

    canvas.addEventListener('pointerleave', () => {
      tooltip.style.display = 'none';
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = Math.exp(-e.deltaY * 0.0015);
      const newScale = clamp(scale * zoomFactor, minScale, maxScale);

      // zoom around cursor
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const worldX = (mx - offsetX) / scale;
      const worldY = (my - offsetY) / scale;

      scale = newScale;
      offsetX = mx - worldX * scale;
      offsetY = my - worldY * scale;

      render();
    }, { passive: false });

    // ---------- Simulated stream ----------
    statusEl.textContent = 'Live stream active';
    setInterval(pushUpdate, 1000);

    // ---------- Resize ----------
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    // Initial render
    render();

    // Optional: basic keyboard panning/zooming
    window.addEventListener('keydown', (e) => {
      const panStep = 40;
      if (e.key === 'ArrowLeft') offsetX += panStep;
      if (e.key === 'ArrowRight') offsetX -= panStep;
      if (e.key === 'ArrowUp') offsetY += panStep;
      if (e.key === 'ArrowDown') offsetY -= panStep;
      if (e.key === '+' || e.key === '=') scale = clamp(scale * 1.15, minScale, maxScale);
      if (e.key === '-') scale = clamp(scale / 1.15, minScale, maxScale);
      render();
    });
  </script>
</body>
</html>
```

