</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="controls">
        <button id="resetBtn">Reset View</button>
        <button id="randomizeBtn">Randomize Baseline</button>
        <div class="legend">
          <span>Loss</span>
          <div class="legendBar"></div>
          <span>Gain</span>
        </div>
      </div>
      <div class="status" id="status">Streaming: simulated realtime updates</div>
    </div>

    <div class="viewport" id="viewport">
      <svg id="svg" xmlns="http://www.w3.org/2000/svg"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = document.getElementById("svg");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const resetBtn = document.getElementById("resetBtn");
    const randomizeBtn = document.getElementById("randomizeBtn");

    const stocks = [
      "AAPL","MSFT","NVDA","AMD","TSLA","AMZN","GOOGL","META",
      "NFLX","ORCL","CRM","INTC","QCOM","IBM","ADBE","AVGO",
      "BA","JPM","BAC","GS","V","MA","XOM","CVX","PFE","JNJ",
      "LLY","UNH","WMT","TGT","HD","COST","DIS","UBER","LYFT","SNAP"
    ];

    const cols = 6;
    const rows = Math.ceil(stocks.length / cols);
    const tileW = 140;
    const tileH = 86;
    const gap = 10;
    const pad = 18;

    let view = { x: 0, y: 0, scale: 1 };
    let isDragging = false;
    let dragStart = { x: 0, y: 0, vx: 0, vy: 0 };
    let hoveredSymbol = null;

    const data = stocks.map((symbol, i) => ({
      symbol,
      price: +(50 + Math.random() * 450).toFixed(2),
      prevClose: null,
      changePct: 0,
      volume: Math.floor(1e6 + Math.random() * 25e6),
      row: Math.floor(i / cols),
      col: i % cols
    }));

    data.forEach(d => d.prevClose = d.price / (1 + (Math.random() * 0.06 - 0.03)));

    function layoutSize() {
      return {
        width: pad * 2 + cols * tileW + (cols - 1) * gap,
        height: pad * 2 + rows * tileH + (rows - 1) * gap
      };
    }

    function colorForChange(pct) {
      const max = 5;
      const t = Math.max(-max, Math.min(max, pct)) / max;
      if (t === 0) return "#d8dde8";

      if (t > 0) {
        const g = Math.round(165 + t * 70);
        return `rgb(${Math.round(30 + t * 40)}, ${g}, ${Math.round(70 + t * 20)})`;
      } else {
        const a = Math.abs(t);
        return `rgb(${Math.round(215 - a * 50)}, ${Math.round(90 - a * 10)}, ${Math.round(90 - a * 35)})`;
      }
    }

    function formatMoney(n) {
      return `$${n.toFixed(2)}`;
    }

    function formatPct(n) {
      const sign = n >= 0 ? "+" : "";
      return `${sign}${n.toFixed(2)}%`;
    }

    function render() {
      const { width, height } = layoutSize();
      svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
      svg.innerHTML = "";

      const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
      g.setAttribute("id", "world");
      g.setAttribute("transform", `translate(${view.x},${view.y}) scale(${view.scale})`);
      svg.appendChild(g);

      data.forEach((d, idx) => {
        const x = pad + d.col * (tileW + gap);
        const y = pad + d.row * (tileH + gap);

        const cell = document.createElementNS("http://www.w3.org/2000/svg", "g");
        cell.setAttribute("class", "cell");
        cell.setAttribute("transform", `translate(${x},${y})`);
        cell.dataset.symbol = d.symbol;

        const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        rect.setAttribute("class", "tile");
        rect.setAttribute("width", tileW);
        rect.setAttribute("height", tileH);
        rect.setAttribute("fill", colorForChange(d.changePct));

        const symbol = document.createElementNS("http://www.w3.org/2000/svg", "text");
        symbol.setAttribute("class", "label");
        symbol.setAttribute("x", tileW / 2);
        symbol.setAttribute("y", 33);
        symbol.textContent = d.symbol;

        const price = document.createElementNS("http://www.w3.org/2000/svg", "text");
        price.setAttribute("class", "subLabel");
        price.setAttribute("x", tileW / 2);
        price.setAttribute("y", 54);
        price.textContent = formatMoney(d.price);

        const pct = document.createElementNS("http://www.w3.org/2000/svg", "text");
        pct.setAttribute("class", "subLabel");
        pct.setAttribute("x", tileW / 2);
        pct.setAttribute("y", 70);
        pct.textContent = formatPct(d.changePct);

        cell.appendChild(rect);
        cell.appendChild(symbol);
        cell.appendChild(price);
        cell.appendChild(pct);
        g.appendChild(cell);

        cell.addEventListener("mouseenter", (e) => showTooltip(e, d, x, y));
        cell.addEventListener("mousemove", (e) => moveTooltip(e));
        cell.addEventListener("mouseleave", hideTooltip);
      });

      updateStatus();
    }

    function updateStatus() {
      const avg = data.reduce((sum, d) => sum + d.changePct, 0) / data.length;
      statusEl.textContent = `Streaming: simulated realtime updates • Avg change: ${formatPct(avg)}`;
    }

    function showTooltip(e, d) {
      hoveredSymbol = d.symbol;
      tooltip.innerHTML = `
        <strong>${d.symbol}</strong>
        <div>Price: ${formatMoney(d.price)}</div>
        <div>Change: ${formatPct(d.changePct)}</div>
        <div>Volume: ${d.volume.toLocaleString()}</div>
      `;
      tooltip.style.opacity = "1";
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const rect = viewport.getBoundingClientRect();
      tooltip.style.left = `${e.clientX - rect.left}px`;
      tooltip.style.top = `${e.clientY - rect.top}px`;
    }

    function hideTooltip() {
      hoveredSymbol = null;
      tooltip.style.opacity = "0";
    }

    function updatePrices() {
      data.forEach(d => {
        const drift = (Math.random() - 0.48) * 0.012;
        const shock = (Math.random() - 0.5) * 0.03;
        const pctMove = drift + shock;
        d.price = Math.max(1, d.price * (1 + pctMove));
        d.changePct = ((d.price - d.prevClose) / d.prevClose) * 100;
        d.volume += Math.floor(Math.random() * 25000);

        const cell = [...svg.querySelectorAll(".cell")].find(el => el.dataset.symbol === d.symbol);
        if (cell) {
          const rect = cell.querySelector(".tile");
          const price = cell.querySelectorAll(".subLabel")[0];
          const pct = cell.querySelectorAll(".subLabel")[1];
          rect.setAttribute("fill", colorForChange(d.changePct));
          price.textContent = formatMoney(d.price);
          pct.textContent = formatPct(d.changePct);
        }
      });

      if (hoveredSymbol) {
        const d = data.find(x => x.symbol === hoveredSymbol);
        if (d) {
          tooltip.innerHTML = `
            <strong>${d.symbol}</strong>
            <div>Price: ${formatMoney(d.price)}</div>
            <div>Change: ${formatPct(d.changePct)}</div>
            <div>Volume: ${d.volume.toLocaleString()}</div>
          `;
        }
      }
      updateStatus();
    }

    function resetView() {
      view = { x: 0, y: 0, scale: 1 };
      applyView();
    }

    function applyView() {
      const world = svg.querySelector("#world");
      if (world) {
        world.setAttribute("transform", `translate(${view.x},${view.y}) scale(${view.scale})`);
      }
    }

    // Zoom with mouse wheel centered at pointer
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const oldScale = view.scale;
      const newScale = Math.min(3, Math.max(0.5, oldScale * zoomFactor));

      // Keep pointer anchored
      const worldX = (mx - view.x) / oldScale;
      const worldY = (my - view.y) / oldScale;
      view.x = mx - worldX * newScale;
      view.y = my - worldY * newScale;
      view.scale = newScale;

      applyView();
    }, { passive: false });

    // Pan
    viewport.addEventListener("pointerdown", (e) => {
      if (e.button !== 0) return;
      isDragging = true;
      viewport.classList.add("dragging");
      dragStart.x = e.clientX;
      dragStart.y = e.clientY;
      dragStart.vx = view.x;
      dragStart.vy = view.y;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener("pointermove", (e) => {
      if (!isDragging) return;
      view.x = dragStart.vx + (e.clientX - dragStart.x);
      view.y = dragStart.vy + (e.clientY - dragStart.y);
      applyView();
    });

    viewport.addEventListener("pointerup", () => {
      isDragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("pointerleave", hideTooltip);

    resetBtn.addEventListener("click", resetView);

    randomizeBtn.addEventListener("click", () => {
      data.forEach(d => {
        d.prevClose = d.price;
        d.price = +(d.price * (0.96 + Math.random() * 0.08)).toFixed(2);
        d.changePct = ((d.price - d.prevClose) / d.prevClose) * 100;
      });
      render();
    });

    render();
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
```

