<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Heatmap</h1>
      <div class="hint">Wheel = zoom · Drag = pan · Hover = details</div>
      <button id="resetBtn">Reset View</button>
      <div class="status" id="status">Connecting to feed...</div>
    </div>

    <div class="viewport" id="viewport">
      <div class="heatmap" id="heatmap">
        <div class="grid" id="grid"></div>
      </div>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');

    // Example dataset
    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","AMD","INTC","ORCL",
      "CRM","UBER","NFLX","ADBE","QCOM","AVGO","BABA","SHOP","PYPL","SNOW",
      "MCD","KO","PEP","JPM","V","MA","XOM","CVX","BA","DIS",
      "PFE","MRNA","UNH","LLY","COST","WMT","T","CSCO","IBM","BKNG"
    ];

    const state = {
      scale: 1,
      panX: 0,
      panY: 0,
      isPanning: false,
      startX: 0,
      startY: 0,
      startPanX: 0,
      startPanY: 0,
      stocks: []
    };

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function pctToColor(pct) {
      // pct in range approx [-10, +10]
      const t = clamp((pct + 10) / 20, 0, 1); // 0 = red, 1 = green
      const r = Math.round(234 + (22 - 234) * t);
      const g = Math.round(57 + (199 - 57) * t);
      const b = Math.round(67 + (132 - 67) * t);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function formatCurrency(n) {
      return `$${n.toFixed(2)}`;
    }

    function formatPct(n) {
      return `${n >= 0 ? "+" : ""}${n.toFixed(2)}%`;
    }

    function initStocks() {
      state.stocks = symbols.map(sym => {
        const base = rand(20, 1000);
        const change = rand(-8, 8);
        return {
          symbol: sym,
          price: base,
          prevPrice: base,
          changePct: change
        };
      });
    }

    function renderGrid() {
      grid.innerHTML = '';
      const cols = 5;
      grid.style.gridTemplateColumns = `repeat(${cols}, 120px)`;

      state.stocks.forEach((stock, i) => {
        const tile = document.createElement('div');
        tile.className = 'tile';
        tile.dataset.symbol = stock.symbol;
        tile.innerHTML = `
          <div class="symbol">${stock.symbol}</div>
          <div class="price" id="price-${stock.symbol}">${formatCurrency(stock.price)}</div>
          <div class="change" id="change-${stock.symbol}">${formatPct(stock.changePct)}</div>
        `;
        tile.style.background = pctToColor(stock.changePct);

        tile.addEventListener('mousemove', (e) => showTooltip(e, stock));
        tile.addEventListener('mouseleave', hideTooltip);

        grid.appendChild(tile);
      });
    }

    function updateTiles() {
      state.stocks.forEach(stock => {
        // simple random walk
        stock.prevPrice = stock.price;
        const delta = rand(-1.2, 1.2) + rand(-0.5, 0.5);
        stock.price = Math.max(1, stock.price + delta);
        stock.changePct = ((stock.price - state.prevClose(stock)) / state.prevClose(stock)) * 100;
      });

      state.stocks.forEach(stock => {
        const tile = grid.querySelector(`.tile[data-symbol="${stock.symbol}"]`);
        if (!tile) return;
        const priceEl = document.getElementById(`price-${stock.symbol}`);
        const changeEl = document.getElementById(`change-${stock.symbol}`);
        tile.style.background = pctToColor(stock.changePct);
        priceEl.textContent = formatCurrency(stock.price);
        changeEl.textContent = formatPct(stock.changePct);
      });

      statusEl.textContent = `Live updates · ${new Date().toLocaleTimeString()}`;
    }

    // For initial implementation, use initial price as "previous close"
    const prevCloseMap = new Map();
    state.prevClose = (stock) => {
      if (!prevCloseMap.has(stock.symbol)) prevCloseMap.set(stock.symbol, stock.prevPrice);
      return prevCloseMap.get(stock.symbol);
    };

    function applyTransform() {
      heatmap.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.scale})`;
    }

    function resetView() {
      state.scale = 1;
      state.panX = 0;
      state.panY = 0;
      applyTransform();
    }

    function showTooltip(e, stock) {
      tooltip.style.display = 'block';
      tooltip.innerHTML = `
        <strong>${stock.symbol}</strong><br/>
        Price: ${formatCurrency(stock.price)}<br/>
        Change: ${formatPct(stock.changePct)}
      `;

      const x = e.clientX;
      const y = e.clientY;
      tooltip.style.left = x + 'px';
      tooltip.style.top = y + 'px';
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    viewport.addEventListener('pointerdown', (e) => {
      state.isPanning = true;
      state.startX = e.clientX;
      state.startY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener('pointermove', (e) => {
      if (state.isPanning) {
        state.panX = state.startPanX + (e.clientX - state.startX);
        state.panY = state.startPanY + (e.clientY - state.startY);
        applyTransform();
      }
    });

    viewport.addEventListener('pointerup', (e) => {
      state.isPanning = false;
      try { viewport.releasePointerCapture(e.pointerId); } catch {}
    });

    viewport.addEventListener('pointercancel', () => {
      state.isPanning = false;
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY > 0 ? 0.95 : 1.05;
      const newScale = clamp(state.scale * zoomFactor, 0.5, 3);

      // zoom around cursor
      const rect = viewport.getBoundingClientRect();
      const cx = e.clientX - rect.left;
      const cy = e.clientY - rect.top;

      const worldX = (cx - state.panX) / state.scale;
      const worldY = (cy - state.panY) / state.scale;

      state.scale = newScale;
      state.panX = cx - worldX * state.scale;
      state.panY = cy - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    resetBtn.addEventListener('click', resetView);

    // Initialize
    initStocks();
    renderGrid();
    applyTransform();
    statusEl.textContent = 'Live updates · connected';

    // Simulated real-time feed
    setInterval(updateTiles, 700);
  </script>
</body>
</html>
