  <div id="app">
    <div id="topbar">
      <h1>Stock Price Heatmap</h1>
      <div id="legend">
        <span>Loss</span>
        <div class="swatch" style="background:#8b1e2d;"></div>
        <div class="swatch" style="background:#2c2f3a;"></div>
        <div class="swatch" style="background:#1f7a3a;"></div>
        <span>Gain</span>
        <span class="hint">Wheel = zoom • Drag = pan • Hover = details</span>
      </div>
    </div>

    <div id="viewport">
      <div id="heatmap"></div>
      <div id="tooltip"></div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');

    // --- Configuration ---
    const COLS = 8;
    const ROWS = 6;
    const CELL_COUNT = COLS * ROWS;

    // --- State ---
    const state = {
      scale: 1,
      x: 0,
      y: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      panStartX: 0,
      panStartY: 0,
      cells: [],
      timers: []
    };

    // --- Utilities ---
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function formatPrice(v) {
      return '$' + v.toFixed(2);
    }

    function formatChange(v) {
      return (v >= 0 ? '+' : '') + v.toFixed(2) + '%';
    }

    // Map percent change to RGB:
    // negative -> red, positive -> green, neutral -> dark gray
    function colorForChange(changePct) {
      const maxAbs = 5; // +/-5% saturates color
      const t = clamp(Math.abs(changePct) / maxAbs, 0, 1);

      if (Math.abs(changePct) < 0.05) {
        return 'rgb(44, 47, 58)';
      }

      if (changePct > 0) {
        const r = Math.round(lerp(44, 31, t));
        const g = Math.round(lerp(47, 122, t));
        const b = Math.round(lerp(58, 58, t));
        return `rgb(${r}, ${g}, ${b})`;
      } else {
        const r = Math.round(lerp(44, 139, t));
        const g = Math.round(lerp(47, 30, t));
        const b = Math.round(lerp(58, 45, t));
        return `rgb(${r}, ${g}, ${b})`;
      }
    }

    function applyTransform() {
      heatmap.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
    }

    function updateTooltipPosition(e) {
      const pad = 14;
      tooltip.style.left = `${e.clientX + pad}px`;
      tooltip.style.top = `${e.clientY + pad}px`;
    }

    // --- Data generation ---
    const tickers = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','BRK.B',
      'JPM','V','UNH','XOM','LLY','AVGO','MA','COST',
      'PG','HD','MRK','KO','PEP','ADBE','NFLX','CRM',
      'CSCO','TMO','WMT','ORCL','INTC','QCOM','AMD','BA',
      'GE','DIS','NKE','IBM','MCD','PFE','ABT','LIN',
      'CAT','TXN','SBUX','UPS','CVX','SPGI','GS','AXP'
    ];

    function makeStock(ticker) {
      const base = 50 + Math.random() * 450;
      const changePct = (Math.random() - 0.5) * 4;
      return {
        ticker,
        price: base,
        prevPrice: base,
        changePct,
        volume: Math.floor(100000 + Math.random() * 900000),
        sector: ['Tech','Finance','Healthcare','Energy','Consumer','Industrial'][Math.floor(Math.random() * 6)]
      };
    }

    // --- Rendering ---
    function renderGrid() {
      heatmap.style.gridTemplateColumns = `repeat(${COLS}, 140px)`;
      heatmap.style.gridTemplateRows = `repeat(${ROWS}, 92px)`;

      const total = CELL_COUNT;
      const stocks = tickers.slice(0, total).map(makeStock);
      state.cells = stocks;

      heatmap.innerHTML = '';

      for (let i = 0; i < total; i++) {
        const stock = stocks[i];
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.index = i;

        cell.innerHTML = `
          <div class="ticker">${stock.ticker}</div>
          <div class="price" data-role="price">${formatPrice(stock.price)}</div>
          <div class="change" data-role="change">${formatChange(stock.changePct)}</div>
          <div class="sub" data-role="sub">${stock.sector} • Vol ${stock.volume.toLocaleString()}</div>
        `;

        cell.style.background = colorForChange(stock.changePct);

        cell.addEventListener('mouseenter', () => {
          const s = state.cells[i];
          tooltip.innerHTML = `
            <strong>${s.ticker}</strong><br/>
            Price: ${formatPrice(s.price)}<br/>
            Change: ${formatChange(s.changePct)}<br/>
            Volume: ${s.volume.toLocaleString()}<br/>
            Sector: ${s.sector}
          `;
          tooltip.style.opacity = '1';
        });

        cell.addEventListener('mousemove', updateTooltipPosition);
        cell.addEventListener('mouseleave', () => {
          tooltip.style.opacity = '0';
        });

        heatmap.appendChild(cell);
      }

      applyTransform();
    }

    // --- Real-time updates (simulated stream) ---
    function startRealtimeUpdates() {
      state.timers.push(setInterval(() => {
        for (let i = 0; i < state.cells.length; i++) {
          const s = state.cells[i];
          const prev = s.price;

          // Random walk with mild mean reversion
          const drift = (Math.random() - 0.5) * 1.8;
          const shock = (Math.random() - 0.5) * 1.2;
          const next = Math.max(1, prev + drift + shock);

          s.prevPrice = prev;
          s.price = next;
          s.changePct = ((s.price - (s.prevPrice || s.price)) / s.prevPrice) * 100;

          const cell = heatmap.children[i];
          if (!cell) continue;

          cell.style.background = colorForChange(s.changePct);

          const priceEl = cell.querySelector('[data-role="price"]');
          const changeEl = cell.querySelector('[data-role="change"]');
          priceEl.textContent = formatPrice(s.price);
          changeEl.textContent = formatChange(s.changePct);

          // Update tooltip if hovered
          if (tooltip.style.opacity === '1' && cell.matches(':hover')) {
            tooltip.innerHTML = `
              <strong>${s.ticker}</strong><br/>
              Price: ${formatPrice(s.price)}<br/>
              Change: ${formatChange(s.changePct)}<br/>
              Volume: ${s.volume.toLocaleString()}<br/>
              Sector: ${s.sector}
            `;
          }
        }
      }, 1000));
    }

    // --- Zoom & pan interactions ---
    viewport.addEventListener('mousedown', (e) => {
      state.dragging = true;
      viewport.classList.add('dragging');
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.panStartX = state.x;
      state.panStartY = state.y;
    });

    window.addEventListener('mousemove', (e) => {
      if (!state.dragging) {
        if (tooltip.style.opacity === '1') updateTooltipPosition(e);
        return;
      }
      const dx = e.clientX - state.dragStartX;
      const dy = e.clientY - state.dragStartY;
      state.x = state.panStartX + dx;
      state.y = state.panStartY + dy;
      applyTransform();
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      viewport.classList.remove('dragging');
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomIntensity = 0.0015;
      const factor = Math.exp(-e.deltaY * zoomIntensity);

      const newScale = clamp(state.scale * factor, 0.5, 3);

      // Zoom around cursor
      const worldX = (mouseX - state.x) / state.scale;
      const worldY = (mouseY - state.y) / state.scale;

      state.x = mouseX - worldX * newScale;
      state.y = mouseY - worldY * newScale;
      state.scale = newScale;

      applyTransform();
    }, { passive: false });

    // Touch support: basic pinch-zoom/pan placeholder for future enhancement
    // Initial version keeps mouse interactions simple.

    // --- Init ---
    renderGrid();
    startRealtimeUpdates();
    applyTransform();

    // Keep heatmap positioned in view initially
    state.x = 20;
    state.y = 20;
    applyTransform();
  </script>
</body>
</html>
```

