<body>
  <div id="app">
    <div class="header">
      <h1>Stock Price Heatmap</h1>
      <p>Mouse wheel to zoom • Drag to pan • Hover for details</p>
    </div>

    <div class="controls">
      <button id="resetView">Reset View</button>
    </div>

    <div class="legend">
      <div><strong>Return %</strong></div>
      <div class="legend-bar"></div>
      <div>-5% &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0% &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; +5%</div>
    </div>

    <canvas id="heatmap"></canvas>
    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetView');

    const stocks = [
      'AAPL', 'MSFT', 'NVDA', 'AMZN', 'GOOGL', 'META',
      'TSLA', 'NFLX', 'AMD', 'INTC', 'CRM', 'ORCL'
    ];

    const timeWindow = 120; // number of cells across
    const cellWidth = 28;
    const cellHeight = 24;
    const rowGap = 4;
    const colGap = 2;

    // State
    let dpr = Math.max(1, window.devicePixelRatio || 1);
    let view = {
      scale: 1,
      offsetX: 160,
      offsetY: 60
    };

    let dragging = false;
    let lastMouse = { x: 0, y: 0 };

    // Simulated data: each stock has a rolling time series of returns
    const data = stocks.map(symbol => ({
      symbol,
      basePrice: 100 + Math.random() * 900,
      prices: Array.from({ length: timeWindow }, () => 0),
      returns: Array.from({ length: timeWindow }, () => 0),
      latestPrice: 0
    }));

    function resizeCanvas() {
      const rect = canvas.getBoundingClientRect();
      dpr = Math.max(1, window.devicePixelRatio || 1);
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      render();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function returnToColor(ret) {
      // Clamp to [-5%, +5%]
      const v = clamp(ret, -5, 5) / 5;

      if (v < 0) {
        // red -> neutral
        const t = v + 1; // [-1,0] => [0,1]
        return `rgb(${Math.round(185 + (17 - 185) * t)}, ${Math.round(28 + (24 - 28) * t)}, ${Math.round(28 + (39 - 28) * t)})`;
      } else {
        // neutral -> green
        const t = v; // [0,1]
        return `rgb(${Math.round(17 + (34 - 17) * t)}, ${Math.round(24 + (197 - 24) * t)}, ${Math.round(39 + (94 - 39) * t)})`;
      }
    }

    function simulateUpdate() {
      for (const row of data) {
        const prevPrice = row.latestPrice || row.basePrice;
        const drift = (Math.random() - 0.5) * 1.5;
        const shock = (Math.random() - 0.5) * 3.5;
        const changePct = drift + shock * 0.25; // rough movement
        const newPrice = Math.max(1, prevPrice * (1 + changePct / 100));
        const ret = ((newPrice - row.basePrice) / row.basePrice) * 100;

        row.latestPrice = newPrice;
        row.prices.push(newPrice);
        row.returns.push(ret);

        if (row.prices.length > timeWindow) row.prices.shift();
        if (row.returns.length > timeWindow) row.returns.shift();
      }
      render();
    }

    function drawGrid() {
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;

      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(view.offsetX, view.offsetY);
      ctx.scale(view.scale, view.scale);

      // Draw cells
      for (let r = 0; r < data.length; r++) {
        const row = data[r];
        for (let c = 0; c < timeWindow; c++) {
          const x = c * (cellWidth + colGap);
          const y = r * (cellHeight + rowGap);

          const ret = row.returns[c] ?? 0;
          const color = returnToColor(ret);

          ctx.fillStyle = color;
          ctx.fillRect(x, y, cellWidth, cellHeight);

          // subtle border
          ctx.strokeStyle = 'rgba(255,255,255,0.06)';
          ctx.strokeRect(x, y, cellWidth, cellHeight);
        }
      }

      // Labels
      ctx.fillStyle = '#cbd5e1';
      ctx.font = '12px system-ui, sans-serif';
      ctx.textBaseline = 'middle';

      for (let r = 0; r < data.length; r++) {
        const y = r * (cellHeight + rowGap) + cellHeight / 2;
        ctx.fillText(data[r].symbol, -54, y);
      }

      ctx.restore();

      // Axis-style overlay
      ctx.fillStyle = '#94a3b8';
      ctx.font = '12px system-ui, sans-serif';
      ctx.fillText('Latest →', 170, 24);
    }

    function render() {
      drawGrid();
    }

    function screenToWorld(x, y) {
      return {
        x: (x - view.offsetX) / view.scale,
        y: (y - view.offsetY) / view.scale
      };
    }

    function getCellAtMouse(x, y) {
      const world = screenToWorld(x, y);

      const rowPitch = cellHeight + rowGap;
      const colPitch = cellWidth + colGap;

      const r = Math.floor(world.y / rowPitch);
      const c = Math.floor(world.x / colPitch);

      if (r < 0 || r >= data.length || c < 0 || c >= timeWindow) return null;

      const localX = world.x - c * colPitch;
      const localY = world.y - r * rowPitch;

      if (localX < 0 || localX > cellWidth || localY < 0 || localY > cellHeight) return null;

      return { r, c };
    }

    function showTooltip(e, cell) {
      const row = data[cell.r];
      const ret = row.returns[cell.c] ?? 0;
      const price = row.prices[cell.c] ?? row.latestPrice;

      tooltip.style.display = 'block';
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
      tooltip.innerHTML = `
        <div><strong>${row.symbol}</strong></div>
        <div>Index: ${cell.c}</div>
        <div>Price: $${price.toFixed(2)}</div>
        <div>Return: ${ret.toFixed(2)}%</div>
      `;
    }

    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      lastMouse = { x: e.clientX, y: e.clientY };
      canvas.classList.add('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (dragging) {
        const dx = e.clientX - lastMouse.x;
        const dy = e.clientY - lastMouse.y;
        view.offsetX += dx;
        view.offsetY += dy;
        lastMouse = { x: e.clientX, y: e.clientY };
        render();
      } else {
        const cell = getCellAtMouse(e.clientX, e.clientY);
        if (cell) showTooltip(e, cell);
        else tooltip.style.display = 'none';
      }
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      canvas.classList.remove('dragging');
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const before = screenToWorld(mouseX, mouseY);

      view.scale = clamp(view.scale * zoomFactor, 0.5, 4);

      const after = screenToWorld(mouseX, mouseY);
      view.offsetX += (after.x - before.x) * view.scale;
      view.offsetY += (after.y - before.y) * view.scale;

      render();
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      view = { scale: 1, offsetX: 160, offsetY: 60 };
      render();
    });

    window.addEventListener('resize', resizeCanvas);

    // Initial render
    resizeCanvas();
    render();

    // Simulated live updates
    setInterval(simulateUpdate, 1000);
  </script>
</body>
</html>
