      'AAPL','MSFT','NVDA','META','GOOG','AMZN','ORCL','CRM',
      'JNJ','PFE','MRK','UNH','ABBV','TMO','BMY','ISRG',
      'JPM','BAC','GS','MS','C','WFC','AXP','SCHW',
      'XOM','CVX','COP','SLB','EOG','PSX','OXY','VLO',
      'WMT','COST','HD','MCD','KO','PEP','NKE','SBUX',
      'CAT','BA','GE','HON','MMM','DE','LMT','RTX',
      'NEE','DUK','SO','AEP','EXC','XEL','ED','SRE',
      'LIN','APD','ECL','FCX','NEM','DOW','ALB','PPG'
    ];

    const state = {
      scale: 1,
      tx: 0,
      ty: 0,
      isDragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startTx: 0,
      startTy: 0,
      pinned: null,
      cells: []
    };

    function randomBetween(min, max) {
      return min + Math.random() * (max - min);
    }

    function clamp(n, min, max) {
      return Math.max(min, Math.min(max, n));
    }

    function colorForChange(change) {
      // change is in percent, roughly [-5, 5]
      const min = -5, max = 5;
      const t = clamp((change - min) / (max - min), 0, 1);

      // red -> yellow -> green
      let r, g, b;
      if (t < 0.5) {
        const u = t / 0.5;
        r = Math.round(192 + (241 - 192) * u);
        g = Math.round(57 + (196 - 57) * u);
        b = Math.round(43 + (15 - 43) * u);
      } else {
        const u = (t - 0.5) / 0.5;
        r = Math.round(241 + (39 - 241) * u);
        g = Math.round(196 + (174 - 196) * u);
        b = Math.round(15 + (96 - 15) * u);
      }
      return `rgb(${r}, ${g}, ${b})`;
    }

    function textColorForBg(change) {
      return Math.abs(change) < 1 ? '#0b1020' : '#ffffff';
    }

    function createData() {
      return tickers.map((ticker, i) => {
        const sector = sectors[i % sectors.length];
        const price = randomBetween(20, 900);
        const change = randomBetween(-4.5, 4.5);
        const marketCap = randomBetween(5, 250).toFixed(1);
        return {
          id: ticker,
          ticker,
          sector,
          price,
          change,
          marketCap: `${marketCap}B`,
          volume: Math.floor(randomBetween(1e6, 2e8)),
          updatedAt: Date.now()
        };
      });
    }

    let data = createData();

    function formatPrice(n) {
      return n >= 1000 ? `$${n.toFixed(0)}` : `$${n.toFixed(2)}`;
    }

    function formatChange(n) {
      const sign = n >= 0 ? '+' : '';
      return `${sign}${n.toFixed(2)}%`;
    }

    function formatVolume(v) {
      if (v >= 1e9) return (v / 1e9).toFixed(1) + 'B';
      if (v >= 1e6) return (v / 1e6).toFixed(1) + 'M';
      return v.toString();
    }

    function render() {
      heatmap.innerHTML = '';
      state.cells = [];

      data.forEach((item) => {
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.ticker = item.ticker;

        const bg = colorForChange(item.change);
        cell.style.background = bg;
        cell.style.color = textColorForBg(item.change);

        cell.innerHTML = `
          <div>
            <div class="ticker">${item.ticker}</div>
            <div class="sector">${item.sector}</div>
          </div>
          <div class="price-row">
            <div>
              <div class="price">${formatPrice(item.price)}</div>
              <div class="mini">Vol ${formatVolume(item.volume)}</div>
            </div>
            <div class="change">${formatChange(item.change)}</div>
          </div>
          <div class="sparkline"></div>
        `;

        cell.addEventListener('mouseenter', (e) => showTooltip(e, item));
        cell.addEventListener('mousemove', (e) => moveTooltip(e));
        cell.addEventListener('mouseleave', hideTooltip);
        cell.addEventListener('click', () => {
          state.pinned = item.id;
          updatePinned();
        });

        heatmap.appendChild(cell);
        state.cells.push(cell);
      });

      updatePinned();
      applyTransform();
    }

    function updatePinned() {
      for (const cell of state.cells) {
        cell.classList.toggle('active', cell.dataset.ticker === state.pinned);
      }
    }

    function showTooltip(e, item) {
      tooltip.classList.add('visible');
      tooltip.innerHTML = `
        <strong>${item.ticker}</strong> <span style="color:#9fb0d0;">${item.sector}</span>
        <div class="row"><span>Price</span><span>${formatPrice(item.price)}</span></div>
        <div class="row"><span>Change</span><span>${formatChange(item.change)}</span></div>
        <div class="row"><span>Market Cap</span><span>${item.marketCap}</span></div>
        <div class="row"><span>Volume</span><span>${formatVolume(item.volume)}</span></div>
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const pad = 16;
      const x = Math.min(window.innerWidth - 280, e.clientX + 14);
      const y = Math.min(window.innerHeight - 140, e.clientY + 14);
      tooltip.style.left = `${Math.max(pad, x)}px`;
      tooltip.style.top = `${Math.max(pad, y)}px`;
    }

    function hideTooltip() {
      if (!state.pinned) tooltip.classList.remove('visible');
    }

    function applyTransform() {
      heatmap.style.transform = `translate(${state.tx}px, ${state.ty}px) scale(${state.scale})`;
    }

    function updateData() {
      data = data.map(item => {
        // gentle random walk, preserve realism
        const delta = randomBetween(-0.35, 0.35);
        const change = clamp(item.change + delta, -5, 5);
        const priceMove = item.price * (delta / 100);
        const volumeJitter = Math.floor(randomBetween(-2e6, 4e6));

        return {
          ...item,
          price: Math.max(1, item.price + priceMove),
          change,
          volume: Math.max(1000, item.volume + volumeJitter),
          updatedAt: Date.now()
        };
      });

      // Update only existing cells for smoother animation
      data.forEach((item, i) => {
        const cell = state.cells[i];
        if (!cell) return;
        cell.style.background = colorForChange(item.change);
        cell.style.color = textColorForBg(item.change);
        cell.querySelector('.price').textContent = formatPrice(item.price);
        cell.querySelector('.change').textContent = formatChange(item.change);
        cell.querySelector('.mini').textContent = `Vol ${formatVolume(item.volume)}`;
      });
    }

    // Zoom centered on cursor
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = clamp(state.scale * zoomFactor, 0.5, 3);

      // world point under cursor before zoom
      const worldX = (mouseX - state.tx) / state.scale;
      const worldY = (mouseY - state.ty) / state.scale;

      state.scale = nextScale;
      state.tx = mouseX - worldX * state.scale;
      state.ty = mouseY - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    viewport.addEventListener('pointerdown', (e) => {
      state.isDragging = true;
      viewport.classList.add('dragging');
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startTx = state.tx;
      state.startTy = state.ty;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener('pointermove', (e) => {
      if (state.isDragging) {
        state.tx = state.startTx + (e.clientX - state.dragStartX);
        state.ty = state.startTy + (e.clientY - state.dragStartY);
        applyTransform();
      }
    });

    viewport.addEventListener('pointerup', () => {
      state.isDragging = false;
      viewport.classList.remove('dragging');
    });

    viewport.addEventListener('pointercancel', () => {
      state.isDragging = false;
      viewport.classList.remove('dragging');
    });

    // Click empty space to unpin
    viewport.addEventListener('click', (e) => {
      if (e.target === viewport) {
        state.pinned = null;
        updatePinned();
        hideTooltip();
      }
    });

    // Keep tooltip visible for pinned item when hovering elsewhere
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        state.pinned = null;
        updatePinned();
        hideTooltip();
      }
      if (e.key === 'r') {
        state.scale = 1;
        state.tx = 0;
        state.ty = 0;
        applyTransform();
      }
    });

    // Simulated real-time updates
    render();
    setInterval(updateData, 1000);

    // Keep tile layout responsive-ish by adjusting scale on resize if needed
    window.addEventListener('resize', () => {
      if (!tooltip.classList.contains('visible')) return;
    });
  </script>
</body>
</html>
```

