<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      overflow: hidden;
      background: #0b1020;
      color: #e5e7eb;
      font-family: Inter, system-ui, sans-serif;
    }

    #app {
      position: relative;
      width: 100vw;
      height: 100vh;
      user-select: none;
    }

    #heatmap {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    #heatmap:active {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(17, 24, 39, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      line-height: 1.4;
      box-shadow: 0 8px 24px rgba(0,0,0,0.25);
      display: none;
      white-space: nowrap;
    }

    .legend {
      position: absolute;
      left: 12px;
      bottom: 12px;
      background: rgba(17, 24, 39, 0.85);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
    }

    .legend-bar {
      width: 220px;
      height: 12px;
      border-radius: 999px;
      background: linear-gradient(90deg, #7f1d1d, #ef4444, #111827, #22c55e, #14532d);
      margin-top: 6px;
    }

    .status {
      position: absolute;
      top: 12px;
      left: 12px;
      background: rgba(17, 24, 39, 0.85);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="heatmap"></canvas>
    <div class="tooltip" id="tooltip"></div>
    <div class="legend">
      <div>Price change %</div>
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between; margin-top:4px;">
        <span>-10%</span><span>0%</span><span>+10%</span>
      </div>
    </div>
    <div class="status" id="status">Initializing...</div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const state = {
      dpr: window.devicePixelRatio || 1,
      width: 0,
      height: 0,

      rows: 30,
      cols: 120,
      cellSize: 18,
      baseCellSize: 18,

      panX: 0,
      panY: 0,
      zoom: 1,

      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      panStartX: 0,
      panStartY: 0,

      stocks: [],
      data: [],
      visibleCols: 120,

      hovered: null,
      lastUpdate: Date.now()
    };

    const symbols = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "META", "NVDA", "TSLA", "NFLX", "AMD", "INTC",
      "CRM", "ORCL", "IBM", "ADBE", "QCOM", "AVGO", "SAP", "UBER", "SNOW", "SHOP",
      "PYPL", "SQ", "DIS", "BAC", "JPM", "GS", "C", "WMT", "COST", "HD"
    ];

    function initData() {
      state.stocks = symbols.slice(0, state.rows);
      state.data = Array.from({ length: state.rows }, (_, r) =>
        Array.from({ length: state.cols }, (_, c) => simulateValue(r, c))
      );
    }

    function simulateValue(r, c) {
      // Random-ish but visually coherent price change between -10 and +10
      const base = Math.sin((r + 1) * 0.55 + c * 0.08) * 3.8;
      const noise = (Math.random() - 0.5) * 4.5;
      return Math.max(-10, Math.min(10, base + noise));
    }

    function resize() {
      state.width = canvas.clientWidth = window.innerWidth;
      state.height = canvas.clientHeight = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      render();
    }

    function valueToColor(value) {
      // Map -10..10 to red -> black -> green
      const t = (value + 10) / 20;
      let r, g, b;

      if (t < 0.5) {
        const k = t / 0.5;
        r = lerp(127, 17, k);
        g = lerp(29, 24, k);
        b = lerp(29, 39, k);
      } else {
        const k = (t - 0.5) / 0.5;
        r = lerp(17, 34, k);
        g = lerp(24, 197, k);
        b = lerp(39, 94, k);
      }

      return `rgb(${Math.round(r)}, ${Math.round(g)}, ${Math.round(b)})`;
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function render() {
      ctx.clearRect(0, 0, state.width, state.height);

      const cellW = state.baseCellSize * state.zoom;
      const cellH = state.baseCellSize * state.zoom;

      const startCol = Math.max(0, Math.floor(-state.panX / cellW));
      const startRow = Math.max(0, Math.floor(-state.panY / cellH));
      const endCol = Math.min(state.cols, Math.ceil((state.width - state.panX) / cellW));
      const endRow = Math.min(state.rows, Math.ceil((state.height - state.panY) / cellH));

      // Background grid
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, state.width, state.height);

      for (let r = startRow; r < endRow; r++) {
        for (let c = startCol; c < endCol; c++) {
          const x = state.panX + c * cellW;
          const y = state.panY + r * cellH;
          const value = state.data[r][c];

          ctx.fillStyle = valueToColor(value);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // Hover highlight
          if (state.hovered && state.hovered.row === r && state.hovered.col === c) {
            ctx.strokeStyle = "#ffffff";
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, cellW - 2, cellH - 2);
          }
        }
      }

      // Labels along left side and top
      ctx.fillStyle = "#cbd5e1";
      ctx.font = `${Math.max(10, 12 * state.zoom)}px system-ui, sans-serif`;

      for (let r = startRow; r < endRow; r++) {
        const y = state.panY + r * cellH + cellH * 0.7;
        if (y >= 0 && y <= state.height) {
          ctx.fillText(state.stocks[r], 6, y);
        }
      }

      // Top axis labels
      ctx.fillStyle = "#94a3b8";
      for (let c = startCol; c < endCol; c += Math.max(1, Math.floor(8 / state.zoom))) {
        const x = state.panX + c * cellW + 2;
        if (x >= 0 && x <= state.width) {
          ctx.fillText(String(c), x, 14);
        }
      }

      statusEl.textContent = `Updated: ${new Date(state.lastUpdate).toLocaleTimeString()} | Zoom: ${state.zoom.toFixed(2)}x`;
    }

    function updateData() {
      // Shift left, append new values
      for (let r = 0; r < state.rows; r++) {
        state.data[r].shift();
        state.data[r].push(simulateValue(r, state.cols - 1));
      }
      state.lastUpdate = Date.now();
      render();
    }

    function getCellFromMouse(x, y) {
      const cellW = state.baseCellSize * state.zoom;
      const cellH = state.baseCellSize * state.zoom;
      const col = Math.floor((x - state.panX) / cellW);
      const row = Math.floor((y - state.panY) / cellH);

      if (row < 0 || row >= state.rows || col < 0 || col >= state.cols) return null;
      return { row, col, value: state.data[row][col] };
    }

    canvas.addEventListener("mousedown", (e) => {
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.panStartX = state.panX;
      state.panStartY = state.panY;
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      if (state.dragging) {
        state.panX = state.panStartX + (e.clientX - state.dragStartX);
        state.panY = state.panStartY + (e.clientY - state.dragStartY);
        render();
        return;
      }

      const cell = getCellFromMouse(e.clientX, e.clientY);
      if (cell) {
        state.hovered = cell;
        tooltip.style.display = "block";
        tooltip.style.left = `${e.clientX + 12}px`;
        tooltip.style.top = `${e.clientY + 12}px`;
        tooltip.innerHTML = `
          <div><strong>${state.stocks[cell.row]}</strong></div>
          <div>Bucket: ${cell.col}</div>
          <div>Change: ${cell.value.toFixed(2)}%</div>
        `;
        render();
      } else {
        state.hovered = null;
        tooltip.style.display = "none";
        render();
      }
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const mouseX = e.clientX;
      const mouseY = e.clientY;
      const oldZoom = state.zoom;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      state.zoom = Math.min(4, Math.max(0.5, state.zoom * zoomFactor));

      // Zoom toward cursor
      const worldX = (mouseX - state.panX) / oldZoom;
      const worldY = (mouseY - state.panY) / oldZoom;
      state.panX = mouseX - worldX * state.zoom;
      state.panY = mouseY - worldY * state.zoom;

      render();
    }, { passive: false });

    window.addEventListener("resize", resize);

    // Simple real-time simulation
    setInterval(updateData, 1000);

    initData();
    resize();
    statusEl.textContent = "Live heatmap ready";
  </script>
</body>
</html>
