    }

    svg.dragging {
      cursor: grabbing;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(10, 14, 26, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      color: var(--text);
      border-radius: 8px;
      padding: 10px 12px;
      font-size: 12px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      display: none;
      z-index: 10;
      min-width: 180px;
    }

    .legend {
      display: flex;
      gap: 10px;
      align-items: center;
      font-size: 12px;
      color: var(--muted);
      margin-top: 8px;
    }

    .swatch {
      width: 120px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, #b91c1c, #f3f4f6, #15803d);
      border: 1px solid rgba(255,255,255,0.1);
    }

    .axis-label {
      fill: #8ea0c2;
      font-size: 11px;
    }

    .axis-title {
      fill: #dce8ff;
      font-size: 12px;
      font-weight: 600;
    }

    .grid-line {
      stroke: rgba(255,255,255,0.08);
      stroke-width: 1;
      shape-rendering: crispEdges;
    }

    .cell {
      stroke: rgba(255,255,255,0.06);
      stroke-width: 1;
      shape-rendering: crispEdges;
    }

    .cell:hover {
      stroke: rgba(255,255,255,0.45);
      stroke-width: 1.5;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="header">
      <h1>Stock Price Heatmap</h1>
      <p>Real-time client-side heatmap. Use mouse wheel to zoom, drag to pan, and hover to inspect values.</p>
      <div class="controls">
        <button id="resetBtn">Reset View</button>
        <button id="toggleLiveBtn">Pause Live Updates</button>
        <button id="randomizeBtn">Randomize Data</button>
      </div>
      <div class="legend">
        <span>Negative</span>
        <div class="swatch"></div>
        <span>Positive</span>
      </div>
    </div>

    <div class="viewport-wrap" id="viewportWrap">
      <svg id="heatmap" aria-label="Stock heatmap"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="footer" id="status">
      Status: Initializing...
    </div>
  </div>

  <script>
    const svg = document.getElementById('heatmap');
    const wrap = document.getElementById('viewportWrap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');
    const toggleLiveBtn = document.getElementById('toggleLiveBtn');
    const randomizeBtn = document.getElementById('randomizeBtn');

    const symbols = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
      'TSLA', 'META', 'AMD', 'NFLX', 'INTC',
      'ORCL', 'ADBE', 'CRM', 'UBER', 'SHOP'
    ];

    const timeCount = 60; // recent time buckets
    const cellW = 28;
    const cellH = 22;
    const margin = { top: 30, right: 20, bottom: 30, left: 70 };

    let data = [];
    let liveUpdates = true;

    // View transform state
    let view = {
      scale: 1,
      offsetX: 0,
      offsetY: 0
    };

    let isDragging = false;
    let dragStart = { x: 0, y: 0, ox: 0, oy: 0 };
    let svgBounds = null;

    function randBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function generateInitialData() {
      data = symbols.map((symbol) => {
        const base = randBetween(90, 350);
        const points = [];
        for (let i = 0; i < timeCount; i++) {
          const prev = i === 0 ? base : points[i - 1].price;
          const changePct = randBetween(-1.8, 1.8);
          const price = Math.max(1, prev * (1 + changePct / 100));
          points.push({
            t: i,
            price,
            changePct,
          });
        }
        return { symbol, points };
      });
    }

    function colorForChange(changePct) {
      // Map -5%..+5% to red/white/green
      const clamped = Math.max(-5, Math.min(5, changePct));
      const ratio = (clamped + 5) / 10; // 0..1
      if (ratio < 0.5) {
        const k = ratio / 0.5;
        return interpolateColor([185, 28, 28], [243, 244, 246], k);
      } else {
        const k = (ratio - 0.5) / 0.5;
        return interpolateColor([243, 244, 246], [21, 128, 61], k);
      }
    }

    function interpolateColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const bl = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r},${g},${bl})`;
    }

    function buildSVG() {
      const width = wrap.clientWidth;
      const height = wrap.clientHeight;
      svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
      svg.innerHTML = '';

      const chartW = width - margin.left - margin.right;
      const chartH = height - margin.top - margin.bottom;
      const totalW = timeCount * cellW;
      const totalH = symbols.length * cellH;

      const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      g.setAttribute('transform', `translate(${margin.left},${margin.top}) scale(${view.scale}) translate(${view.offsetX},${view.offsetY})`);
      svg.appendChild(g);

      // Background panel
      const bg = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      bg.setAttribute('x', -20);
      bg.setAttribute('y', -20);
      bg.setAttribute('width', totalW + 40);
      bg.setAttribute('height', totalH + 40);
      bg.setAttribute('fill', 'rgba(255,255,255,0.02)');
      bg.setAttribute('rx', 12);
      g.appendChild(bg);

      // Grid lines
      for (let i = 0; i <= timeCount; i += 5) {
        const x = i * cellW;
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', x);
        line.setAttribute('y1', 0);
        line.setAttribute('x2', x);
        line.setAttribute('y2', totalH);
        line.setAttribute('class', 'grid-line');
        g.appendChild(line);
      }

      for (let j = 0; j <= symbols.length; j++) {
        const y = j * cellH;
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', 0);
        line.setAttribute('y1', y);
        line.setAttribute('x2', totalW);
        line.setAttribute('y2', y);
        line.setAttribute('class', 'grid-line');
        g.appendChild(line);
      }

      // Cells
      data.forEach((row, rowIndex) => {
        row.points.forEach((pt, colIndex) => {
          const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
          rect.setAttribute('x', colIndex * cellW);
          rect.setAttribute('y', rowIndex * cellH);
          rect.setAttribute('width', cellW);
          rect.setAttribute('height', cellH);
          rect.setAttribute('fill', colorForChange(pt.changePct));
          rect.setAttribute('class', 'cell');
          rect.dataset.symbol = row.symbol;
          rect.dataset.price = pt.price.toFixed(2);
          rect.dataset.changePct = pt.changePct.toFixed(2);
          rect.dataset.timeIndex = colIndex;
          rect.addEventListener('mousemove', onCellHover);
          rect.addEventListener('mouseleave', hideTooltip);
          g.appendChild(rect);
        });
      });

      // Axis labels: Y-axis symbol labels
      data.forEach((row, idx) => {
        const txt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        txt.setAttribute('x', -10);
        txt.setAttribute('y', idx * cellH + cellH * 0.72);
        txt.setAttribute('text-anchor', 'end');
        txt.setAttribute('class', 'axis-label');
        txt.textContent = row.symbol;
        g.appendChild(txt);
      });

      // X-axis labels every 10 buckets
      for (let i = 0; i < timeCount; i += 10) {
        const txt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        txt.setAttribute('x', i * cellW + 2);
        txt.setAttribute('y', totalH + 18);
        txt.setAttribute('class', 'axis-label');
        txt.textContent = `T-${timeCount - i}`;
        g.appendChild(txt);
      }

      // Titles
      const yTitle = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      yTitle.setAttribute('x', -55);
      yTitle.setAttribute('y', -8);
      yTitle.setAttribute('class', 'axis-title');
      yTitle.textContent = 'Symbol';
      g.appendChild(yTitle);

      const xTitle = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      xTitle.setAttribute('x', totalW / 2 - 30);
      xTitle.setAttribute('y', totalH + 42);
      xTitle.setAttribute('class', 'axis-title');
      xTitle.textContent = 'Time';
      g.appendChild(xTitle);

      statusEl.textContent = `Status: Live updates ${liveUpdates ? 'enabled' : 'paused'} | Zoom ${(view.scale * 100).toFixed(0)}%`;
    }

    function onCellHover(evt) {
      const rect = evt.target.getBoundingClientRect();
      const wrapRect = wrap.getBoundingClientRect();
      tooltip.style.display = 'block';
      tooltip.innerHTML = `
        <div><strong>${evt.target.dataset.symbol}</strong></div>
        <div>Price: $${evt.target.dataset.price}</div>
        <div>Change: ${Number(evt.target.dataset.changePct).toFixed(2)}%</div>
        <div>Bucket: ${evt.target.dataset.timeIndex}</div>
      `;
      const x = evt.clientX - wrapRect.left + 14;
      const y = evt.clientY - wrapRect.top + 14;
      tooltip.style.left = `${Math.min(x, wrapRect.width - 200)}px`;
      tooltip.style.top = `${Math.min(y, wrapRect.height - 100)}px`;
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    function resetView() {
      view.scale = 1;
      view.offsetX = 0;
      view.offsetY = 0;
      buildSVG();
    }

    function clampView() {
      const totalW = timeCount * cellW;
      const totalH = symbols.length * cellH;
      const width = wrap.clientWidth;
      const height = wrap.clientHeight;

      const maxOffsetX = 0;
      const maxOffsetY = 0;
      const minOffsetX = Math.min(0, (width - margin.left - margin.right) / view.scale - totalW);
      const minOffsetY = Math.min(0, (height - margin.top - margin.bottom) / view.scale - totalH);

      view.offsetX = Math.max(minOffsetX, Math.min(maxOffsetX, view.offsetX));
      view.offsetY = Math.max(minOffsetY, Math.min(maxOffsetY, view.offsetY));
    }

    wrap.addEventListener('wheel', (e) => {
      e.preventDefault();
      const delta = -e.deltaY;
      const zoomFactor = delta > 0 ? 1.08 : 0.92;
      const rect = svg.getBoundingClientRect();
      const mouseX = e.clientX - rect.left - margin.left;
      const mouseY = e.clientY - rect.top - margin.top;

      const prevScale = view.scale;
      const nextScale = Math.max(0.6, Math.min(4, view.scale * zoomFactor));

      // Zoom around cursor
      view.offsetX = (view.offsetX + mouseX / prevScale) - (mouseX / nextScale);
      view.offsetY = (view.offsetY + mouseY / prevScale) - (mouseY / nextScale);
      view.scale = nextScale;
      clampView();
      buildSVG();
    }, { passive: false });

    svg.addEventListener('mousedown', (e) => {
      isDragging = true;
      svg.classList.add('dragging');
      dragStart = { x: e.clientX, y: e.clientY, ox: view.offsetX, oy: view.offsetY };
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      svg.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      const dx = (e.clientX - dragStart.x) / view.scale;
      const dy = (e.clientY - dragStart.y) / view.scale;
      view.offsetX = dragStart.ox + dx;
      view.offsetY = dragStart.oy + dy;
      clampView();
      buildSVG();
    });

    window.addEventListener('resize', () => buildSVG());

    function pushLiveUpdate() {
      if (!liveUpdates) return;

      data.forEach((row) => {
        const last = row.points[row.points.length - 1];
        const changePct = randBetween(-1.5, 1.5);
        const price = Math.max(1, last.price * (1 + changePct / 100));

        row.points.push({
          t: Date.now(),
          price,
          changePct,
        });

        if (row.points.length > timeCount) {
          row.points.shift();
        }
      });

      buildSVG();
    }

    function randomizeData() {
      generateInitialData();
      buildSVG();
    }

    resetBtn.addEventListener('click', resetView);
    toggleLiveBtn.addEventListener('click', () => {
      liveUpdates = !liveUpdates;
      toggleLiveBtn.textContent = liveUpdates ? 'Pause Live Updates' : 'Resume Live Updates';
      statusEl.textContent = `Status: Live updates ${liveUpdates ? 'enabled' : 'paused'} | Zoom ${(view.scale * 100).toFixed(0)}%`;
    });
    randomizeBtn.addEventListener('click', randomizeData);

    // Init
    generateInitialData();
    buildSVG();
    setInterval(pushLiveUpdate, 1000);
  </script>
</body>
</html>
```

---

## Notes on the implementation

### 1) Real-time updates
This version uses simulated data updates every second. To connect real market data later, replace `pushLiveUpdate()` with a WebSocket, SSE, or polling data source.

### 2) Zoom/pan
- **Mouse wheel** zooms centered around cursor
- **Click and drag** pans the viewport
- The current implementation uses an SVG transform for performance and simplicity

### 3) Heat color mapping
Change percentage is mapped:
- Red = negative
- White = neutral
- Green = positive

