  </style>
</head>
<body>
  <div class="app">
    <div class="header">
      <div>
        <h1>Interactive Stock Price Heatmap</h1>
        <div class="meta">Live updates simulated every 1s · Wheel to zoom · Drag to pan</div>
      </div>
      <div class="controls">
        <div class="legend">
          <span>Bear</span>
          <div class="legend-bar"></div>
          <span>Bull</span>
        </div>
        <button id="resetBtn">Reset View</button>
      </div>
    </div>

    <div id="chartWrap">
      <svg id="chart"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    // --- Setup ---
    const svg = d3.select("#chart");
    const tooltip = document.getElementById("tooltip");
    const chartWrap = document.getElementById("chartWrap");

    const width = () => chartWrap.clientWidth;
    const height = () => chartWrap.clientHeight;

    // Simple stock universe
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","META","NVDA","TSLA","AMD","NFLX","INTC",
      "ORCL","CRM","ADBE","QCOM","AVGO","SHOP","UBER","PYPL","SNOW","PLTR",
      "COST","WMT","TGT","KO","PEP","NKE","DIS","BA","JPM","GS",
      "XOM","CVX","BAC","WFC","C","UNH","PFE","MRK","LLY","ABBV"
    ];

    // Initial generated data
    let data = symbols.map((symbol) => ({
      symbol,
      price: +(50 + Math.random() * 450).toFixed(2),
      change: +(Math.random() * 10 - 5).toFixed(2), // percent change
      volume: Math.floor(1e6 + Math.random() * 15e6)
    }));

    // Layout config
    const cols = 8;
    const cellGap = 12;
    const baseCellW = 140;
    const baseCellH = 90;
    const rows = Math.ceil(data.length / cols);

    // Zoom/container group
    const g = svg.append("g").attr("class", "viewport");
    const cellGroup = g.append("g").attr("class", "cells");

    // Scales
    const color = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#ef4444", "#f59e0b", "#22c55e"]);

    // Zoom behavior
    const zoom = d3.zoom()
      .scaleExtent([0.5, 4])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
      });

    svg.call(zoom);

    function computeLayout() {
      const w = width();
      const h = height();

      svg.attr("viewBox", `0 0 ${w} ${h}`);

      const totalCellW = baseCellW + cellGap;
      const totalCellH = baseCellH + cellGap;

      const contentW = cols * totalCellW - cellGap;
      const contentH = rows * totalCellH - cellGap;

      const startX = Math.max(20, (w - contentW) / 2);
      const startY = Math.max(20, (h - contentH) / 2);

      return { startX, startY, totalCellW, totalCellH };
    }

    function render() {
      const { startX, startY, totalCellW, totalCellH } = computeLayout();

      const cells = cellGroup.selectAll(".cell")
        .data(data, d => d.symbol);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "cell")
        .style("cursor", "pointer")
        .on("mousemove", (event, d) => {
          const rect = chartWrap.getBoundingClientRect();
          tooltip.style.left = `${event.clientX - rect.left}px`;
          tooltip.style.top = `${event.clientY - rect.top}px`;
          tooltip.innerHTML = `
            <strong>${d.symbol}</strong><br/>
            Price: $${d.price.toFixed(2)}<br/>
            Change: <span style="color:${d.change >= 0 ? '#22c55e' : '#ef4444'}">${d.change.toFixed(2)}%</span><br/>
            Volume: ${d.volume.toLocaleString()}
          `;
          tooltip.style.opacity = 1;
        })
        .on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });

      cellsEnter.append("rect");
      cellsEnter.append("text");

      cells.merge(cellsEnter)
        .attr("transform", (d, i) => {
          const col = i % cols;
          const row = Math.floor(i / cols);
          const x = startX + col * totalCellW;
          const y = startY + row * totalCellH;
          return `translate(${x},${y})`;
        })
        .each(function(d) {
          const sel = d3.select(this);
          sel.select("rect")
            .attr("width", baseCellW)
            .attr("height", baseCellH)
            .attr("fill", color(d.change));

          sel.select("text")
            .attr("x", baseCellW / 2)
            .attr("y", baseCellH / 2)
            .text(`${d.symbol}\n$${d.price.toFixed(0)}`);
        });

      cells.exit().remove();
    }

    function updateData() {
      data = data.map(d => {
        // Simulate price movement
        const deltaPct = (Math.random() - 0.5) * 1.2;
        const newChange = Math.max(-8, Math.min(8, d.change + deltaPct));
        const newPrice = Math.max(1, d.price * (1 + deltaPct / 100));
        return {
          ...d,
          price: +newPrice.toFixed(2),
          change: +newChange.toFixed(2),
          volume: Math.max(1000, d.volume + Math.floor((Math.random() - 0.48) * 250000))
        };
      });

      render();
    }

    // Initial render
    render();

    // Real-time update loop
    const interval = setInterval(updateData, 1000);

    // Reset view
    document.getElementById("resetBtn").addEventListener("click", () => {
      svg.transition().duration(300).call(
        zoom.transform,
        d3.zoomIdentity
      );
    });

    // Responsive redraw
    const ro = new ResizeObserver(() => render());
    ro.observe(chartWrap);

    // Optional cleanup hook if embedded in SPA
    window.addEventListener("beforeunload", () => clearInterval(interval));
  </script>
</body>
</html>
```

