      stroke: rgba(255,255,255,0.06);
      stroke-width: 1;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="header">
      <div>
        <div class="title">Interactive Stock Price Heatmap</div>
        <div class="status" id="status">Connecting...</div>
      </div>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <svg id="chart"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = d3.select("#chart");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const stocks = [
      "AAPL","MSFT","GOOG","AMZN","TSLA",
      "NVDA","META","NFLX","AMD","INTC"
    ];

    const maxTimeBins = 60;
    const cellPadding = 1;

    let width = 0;
    let height = 0;

    let margin = { top: 20, right: 20, bottom: 30, left: 70 };
    let innerWidth = 0;
    let innerHeight = 0;

    // time bins with stock prices
    // each entry: { t: Date, values: { AAPL: { price, changePct } ... } }
    const timeSeries = [];

    const xScale = d3.scaleBand().paddingInner(0.08).paddingOuter(0.02);
    const yScale = d3.scaleBand().paddingInner(0.08).paddingOuter(0.08);
    const colorScale = d3.scaleSequential()
      .domain([-5, 5])
      .interpolator(d3.interpolateRgbBasis(["#ef4444", "#111827", "#22c55e"]));

    const root = svg.append("g").attr("class", "root");
    const plot = root.append("g").attr("class", "plot");
    const xAxisG = root.append("g").attr("class", "axis x-axis");
    const yAxisG = root.append("g").attr("class", "axis y-axis");

    // zoom/pan
    const zoom = d3.zoom()
      .scaleExtent([1, 12])
      .on("zoom", (event) => {
        plot.attr("transform", event.transform);
        xAxisG.attr("transform", event.transform);
        updateVisibleAxes(event.transform);
      });

    svg.call(zoom);

    function resize() {
      width = wrap.clientWidth;
      height = wrap.clientHeight;

      svg.attr("viewBox", `0 0 ${width} ${height}`);

      innerWidth = width - margin.left - margin.right;
      innerHeight = height - margin.top - margin.bottom;

      xScale.range([0, innerWidth]);
      yScale.range([0, innerHeight]).domain(stocks);

      root.attr("transform", `translate(${margin.left},${margin.top})`);

      render();
    }

    function initData() {
      const now = new Date();
      for (let i = maxTimeBins - 1; i >= 0; i--) {
        const t = new Date(now.getTime() - i * 1000);
        timeSeries.push({
          t,
          values: generateSnapshot()
        });
      }
    }

    function generateSnapshot(prevSnapshot = null) {
      const values = {};
      stocks.forEach(stock => {
        const base = prevSnapshot?.values?.[stock]?.price ?? (100 + Math.random() * 400);
        const drift = (Math.random() - 0.48) * 2.5;
        const price = Math.max(1, base + drift);
        const changePct = prevSnapshot
          ? ((price - prevSnapshot.values[stock].price) / prevSnapshot.values[stock].price) * 100
          : (Math.random() - 0.5) * 6;
        values[stock] = { price, changePct };
      });
      return values;
    }

    function tick() {
      const prev = timeSeries[timeSeries.length - 1];
      timeSeries.push({
        t: new Date(),
        values: generateSnapshot(prev)
      });

      if (timeSeries.length > maxTimeBins) timeSeries.shift();

      statusEl.textContent = `Live updates · ${new Date().toLocaleTimeString()}`;
      render();
    }

    function render() {
      xScale.domain(timeSeries.map(d => d.t));

      // Axes
      const xAxis = d3.axisBottom(xScale)
        .tickFormat(d => d3.timeFormat("%H:%M:%S")(d))
        .tickValues(xScale.domain().filter((d, i) => i % 8 === 0));

      const yAxis = d3.axisLeft(yScale);

      xAxisG
        .attr("transform", `translate(${margin.left},${margin.top + innerHeight})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-30)")
        .style("text-anchor", "end");

      yAxisG
        .attr("transform", `translate(${margin.left},${margin.top})`)
        .call(yAxis);

      // Cells
      const cellsData = [];
      timeSeries.forEach((bin, xIndex) => {
        stocks.forEach(stock => {
          cellsData.push({
            time: bin.t,
            stock,
            ...bin.values[stock],
            xIndex
          });
        });
      });

      const cells = plot.selectAll(".cell-group")
        .data(cellsData, d => `${d.stock}-${d.time.getTime()}`);

      const cellsEnter = cells.enter()
        .append("rect")
        .attr("class", "cell")
        .attr("rx", 2)
        .attr("ry", 2)
        .on("mousemove", (event, d) => {
          tooltip.style.opacity = 1;
          tooltip.innerHTML = `
            <strong>${d.stock}</strong><br/>
            Time: ${d3.timeFormat("%Y-%m-%d %H:%M:%S")(d.time)}<br/>
            Price: $${d.price.toFixed(2)}<br/>
            Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
          `;
          const [mx, my] = d3.pointer(event, wrap);
          tooltip.style.left = `${mx + 12}px`;
          tooltip.style.top = `${my + 12}px`;
        })
        .on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });

      cells.merge(cellsEnter)
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(Math.max(-5, Math.min(5, d.changePct))));

      cells.exit().remove();

      // Preserve visible zoom transform after rerender by re-applied from svg's __zoom
      const transform = d3.zoomTransform(svg.node());
      plot.attr("transform", transform);
      updateVisibleAxes(transform);
    }

    function updateVisibleAxes(transform) {
      // Keep y axis static, x axis adjusted for zoom/pan
      const tx = transform.rescaleX(xScale);

      const visibleTicks = tx.domain().filter((d, i) => i % Math.max(1, Math.floor(timeSeries.length / 8)) === 0);
      const xAxis = d3.axisBottom(tx)
        .tickFormat(d => d3.timeFormat("%H:%M:%S")(d))
        .tickValues(visibleTicks);

      xAxisG
        .attr("transform", `translate(${margin.left},${margin.top + innerHeight})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-30)")
        .style("text-anchor", "end");
    }

    // Basic pan/zoom background
    svg.append("rect")
      .attr("x", 0).attr("y", 0)
      .attr("width", "100%").attr("height", "100%")
      .attr("fill", "transparent")
      .lower();

    window.addEventListener("resize", resize);

    initData();
    resize();
    statusEl.textContent = "Live updates enabled";

    setInterval(tick, 1000);
  </script>
</body>
</html>
