<body>
  <div id="app">
    <div id="toolbar">
      <button id="resetBtn">Reset View</button>
      <button id="randomizeBtn">Randomize</button>
      <div id="legend">
        <span>Down</span>
        <div class="swatch" style="background:#ef4444"></div>
        <div class="swatch" style="background:#111827; border:1px solid #374151"></div>
        <div class="swatch" style="background:#22c55e"></div>
        <span>Up</span>
      </div>
      <div id="status">Connecting...</div>
    </div>

    <div id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const wrap = document.getElementById('canvasWrap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    const resetBtn = document.getElementById('resetBtn');
    const randomizeBtn = document.getElementById('randomizeBtn');

    const stocks = [
      'AAPL', 'MSFT', 'NVDA', 'AMZN', 'GOOGL',
      'META', 'TSLA', 'AMD', 'NFLX', 'INTC',
      'ORCL', 'CRM', 'ADBE', 'QCOM', 'AVGO'
    ];

    const state = {
      rows: stocks.length,
      cols: 60, // time buckets
      cellSize: 20,
      gap: 2,
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      lastMouseX: 0,
      lastMouseY: 0,
      dpr: window.devicePixelRatio || 1,
      data: [],
      hoverCell: null,
      lastUpdate: Date.now()
    };

    function initData() {
      state.data = Array.from({ length: state.rows }, (_, r) => {
        const base = 100 + Math.random() * 50;
        return Array.from({ length: state.cols }, (_, c) => {
          const trend = Math.sin(c / 7 + r * 0.35) * 1.5;
          const noise = (Math.random() - 0.5) * 6;
          return base + trend + noise;
        });
      });
    }

    function resizeCanvas() {
      const rect = wrap.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * state.dpr);
      canvas.height = Math.floor(rect.height * state.dpr);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function priceToColor(v, min, max) {
      const t = (v - min) / (max - min || 1);
      // blue -> dark -> red style
      const r = t < 0.5 ? Math.round(20 + t * 2 * 25) : Math.round(45 + (t - 0.5) * 2 * 210);
      const g = t < 0.5 ? Math.round(40 + t * 2 * 35) : Math.round(70 - (t - 0.5) * 2 * 40);
      const b = t < 0.5 ? Math.round(180 + t * 2 * 40) : Math.round(70 - (t - 0.5) * 2 * 50);
      return `rgb(${clamp(r,0,255)}, ${clamp(g,0,255)}, ${clamp(b,0,255)})`;
    }

    function getVisibleGrid() {
      const rect = wrap.getBoundingClientRect();
      const cell = (state.cellSize + state.gap) * state.zoom;
      return {
        cell,
        offsetX: state.panX,
        offsetY: state.panY,
        width: rect.width,
        height: rect.height
      };
    }

    function drawGridLines(cell, ox, oy, width, height) {
      ctx.strokeStyle = '#1f2937';
      ctx.lineWidth = 1 * state.dpr;

      // draw vertical lines
      ctx.beginPath();
      for (let c = 0; c <= state.cols; c++) {
        const x = ox + c * cell;
        if (x < -cell || x > width + cell) continue;
        ctx.moveTo(x, oy);
        ctx.lineTo(x, oy + state.rows * cell);
      }
      // draw horizontal lines
      for (let r = 0; r <= state.rows; r++) {
        const y = oy + r * cell;
        if (y < -cell || y > height + cell) continue;
        ctx.moveTo(ox, y);
        ctx.lineTo(ox + state.cols * cell, y);
      }
      ctx.stroke();
    }

    function draw() {
      const rect = wrap.getBoundingClientRect();
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      ctx.clearRect(0, 0, rect.width, rect.height);

      // background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, rect.width, rect.height);

      const { cell, offsetX, offsetY, width, height } = getVisibleGrid();

      const flattened = state.data.flat();
      const min = Math.min(...flattened);
      const max = Math.max(...flattened);

      // draw cells
      for (let r = 0; r < state.rows; r++) {
        for (let c = 0; c < state.cols; c++) {
          const x = offsetX + c * cell;
          const y = offsetY + r * cell;

          if (x > width || y > height || x + cell < 0 || y + cell < 0) continue;

          const v = state.data[r][c];
          ctx.fillStyle = priceToColor(v, min, max);
          ctx.fillRect(x, y, cell - state.gap * state.zoom, cell - state.gap * state.zoom);

          if (state.hoverCell && state.hoverCell.r === r && state.hoverCell.c === c) {
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2 * state.dpr;
            ctx.strokeRect(x + 1, y + 1, cell - 2, cell - 2);
          }
        }
      }

      drawGridLines(cell, offsetX, offsetY, width, height);

      // row labels
      ctx.fillStyle = '#cbd5e1';
      ctx.font = `${12 * state.dpr}px Arial`;
      ctx.textBaseline = 'middle';
      for (let r = 0; r < state.rows; r++) {
        const y = offsetY + r * cell + cell / 2;
        if (y < 0 || y > height) continue;
        ctx.fillText(stocks[r], 8, y);
      }
    }

    function screenToCell(clientX, clientY) {
      const rect = wrap.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const cell = (state.cellSize + state.gap) * state.zoom;
      const c = Math.floor((x - state.panX) / cell);
      const r = Math.floor((y - state.panY) / cell);
      return { r, c, x, y, cell };
    }

    function updateTooltip(e, cellInfo) {
      if (!cellInfo || cellInfo.r < 0 || cellInfo.c < 0 || cellInfo.r >= state.rows || cellInfo.c >= state.cols) {
        tooltip.style.display = 'none';
        return;
      }

      const val = state.data[cellInfo.r][cellInfo.c];
      tooltip.innerHTML = `
        <strong>${stocks[cellInfo.r]}</strong><br/>
        Bucket: ${cellInfo.c}<br/>
        Price: $${val.toFixed(2)}
      `;
      tooltip.style.left = e.clientX + 'px';
      tooltip.style.top = e.clientY + 'px';
      tooltip.style.display = 'block';
    }

    wrap.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastMouseX = e.clientX;
      state.lastMouseY = e.clientY;
      wrap.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      wrap.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      const cellInfo = screenToCell(e.clientX, e.clientY);

      if (state.dragging) {
        const dx = e.clientX - state.lastMouseX;
        const dy = e.clientY - state.lastMouseY;
        state.panX += dx;
        state.panY += dy;
        state.lastMouseX = e.clientX;
        state.lastMouseY = e.clientY;
        draw();
      }

      if (cellInfo.r >= 0 && cellInfo.c >= 0 && cellInfo.r < state.rows && cellInfo.c < state.cols) {
        state.hoverCell = { r: cellInfo.r, c: cellInfo.c };
      } else {
        state.hoverCell = null;
      }

      updateTooltip(e, cellInfo);
      draw();
    });

    wrap.addEventListener('mouseleave', () => {
      state.hoverCell = null;
      tooltip.style.display = 'none';
      draw();
    });

    wrap.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const oldZoom = state.zoom;
      const newZoom = clamp(state.zoom * zoomFactor, 0.5, 4);

      const rect = wrap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Zoom around cursor
      const beforeX = (mouseX - state.panX) / oldZoom;
      const beforeY = (mouseY - state.panY) / oldZoom;

      state.zoom = newZoom;
      state.panX = mouseX - beforeX * newZoom;
      state.panY = mouseY - beforeY * newZoom;

      draw();
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      state.zoom = 1;
      state.panX = 80;
      state.panY = 40;
      draw();
    });

    randomizeBtn.addEventListener('click', () => {
      initData();
      draw();
    });

    function tick() {
      // simulate real-time updates
      for (let r = 0; r < state.rows; r++) {
        const row = state.data[r];
        const last = row[row.length - 1];
        const next = last + (Math.random() - 0.5) * 2.5 + Math.sin(Date.now() / 1000 + r) * 0.2;
        row.shift();
        row.push(next);
      }

      state.lastUpdate = Date.now();
      statusEl.textContent = `Updated ${new Date(state.lastUpdate).toLocaleTimeString()}`;
      draw();
    }

    // init
    initData();
    state.panX = 80;
    state.panY = 40;
    resizeCanvas();
    draw();
    statusEl.textContent = 'Live updates enabled';

    window.addEventListener('resize', resizeCanvas);
    setInterval(tick, 1000);
  </script>
</body>
</html>
```

