<script>
(() => {
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const viewport = document.getElementById('viewport');
  const tooltip = document.getElementById('tooltip');
  const resetBtn = document.getElementById('resetBtn');
  const toggleStreamBtn = document.getElementById('toggleStreamBtn');
  const statusEl = document.getElementById('status');

  const dpr = Math.max(1, window.devicePixelRatio || 1);

  // ----- Data model -----
  const rows = 18;
  const cols = 28;
  const tileBaseSize = 36;

  const stocks = [];
  const sectors = ['Tech', 'Finance', 'Health', 'Energy', 'Retail', 'Industrial'];

  function symbolFor(i) {
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    const a = letters[i % 26];
    const b = letters[Math.floor(i / 26) % 26];
    return (a + b + (i % 10)).slice(0, 4);
  }

  for (let i = 0; i < rows * cols; i++) {
    stocks.push({
      symbol: symbolFor(i),
      sector: sectors[i % sectors.length],
      price: 20 + Math.random() * 380,
      changePct: (Math.random() - 0.5) * 8,
      volume: Math.floor(100000 + Math.random() * 900000)
    });
  }

  // ----- View transform -----
  let scale = 1;
  let offsetX = 20;
  let offsetY = 20;

  function resetView() {
    scale = 1;
    offsetX = 20;
    offsetY = 20;
    render();
  }

  // ----- Canvas sizing -----
  function resize() {
    const rect = viewport.getBoundingClientRect();
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    render();
  }

  window.addEventListener('resize', resize);

  // ----- Color mapping -----
  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
  }

  function rgb(r, g, b) {
    return `rgb(${r|0},${g|0},${b|0})`;
  }

  // Red -> dark -> green
  function colorForChange(pct) {
    const t = clamp((pct + 8) / 16, 0, 1);
    const red = [214, 69, 69];
    const mid = [34, 42, 82];
    const green = [63, 191, 127];

    let c;
    if (t < 0.5) {
      const u = t / 0.5;
      c = [
        lerp(red[0], mid[0], u),
        lerp(red[1], mid[1], u),
        lerp(red[2], mid[2], u)
      ];
    } else {
      const u = (t - 0.5) / 0.5;
      c = [
        lerp(mid[0], green[0], u),
        lerp(mid[1], green[1], u),
        lerp(mid[2], green[2], u)
      ];
    }
    return rgb(c[0], c[1], c[2]);
  }

  function textColorForBg(pct) {
    return Math.abs(pct) > 3.5 ? '#ffffff' : '#e7ecff';
  }

  // ----- Interaction: pan/zoom -----
  let dragging = false;
  let dragStart = { x: 0, y: 0, ox: 0, oy: 0 };

  function screenToWorld(x, y) {
    return {
      x: (x - offsetX) / scale,
      y: (y - offsetY) / scale
    };
  }

  canvas.addEventListener('pointerdown', (e) => {
    dragging = true;
    canvas.classList.add('dragging');
    canvas.setPointerCapture(e.pointerId);
    dragStart = { x: e.clientX, y: e.clientY, ox: offsetX, oy: offsetY };
  });

  canvas.addEventListener('pointermove', (e) => {
    if (dragging) {
      offsetX = dragStart.ox + (e.clientX - dragStart.x);
      offsetY = dragStart.oy + (e.clientY - dragStart.y);
      render();
      return;
    }

    const hit = hitTest(e.clientX, e.clientY);
    if (hit) {
      const s = stocks[hit.index];
      tooltip.style.display = 'block';
      tooltip.style.left = e.clientX + 'px';
      tooltip.style.top = e.clientY + 'px';
      tooltip.innerHTML = `
        <strong>${s.symbol}</strong> <span style="color:${textColorForBg(s.changePct)}">(${s.sector})</span><br/>
        Price: $${s.price.toFixed(2)}<br/>
        Change: <span style="color:${s.changePct >= 0 ? '#6ee7a8' : '#ff8d8d'}">${s.changePct.toFixed(2)}%</span><br/>
        Volume: ${s.volume.toLocaleString()}
      `;
    } else {
      tooltip.style.display = 'none';
    }
  });

  canvas.addEventListener('pointerup', (e) => {
    dragging = false;
    canvas.classList.remove('dragging');
    try { canvas.releasePointerCapture(e.pointerId); } catch {}
  });

  canvas.addEventListener('pointerleave', () => {
    tooltip.style.display = 'none';
    dragging = false;
    canvas.classList.remove('dragging');
  });

  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();

    const rect = canvas.getBoundingClientRect();
    const mouseX = (e.clientX - rect.left) * dpr;
    const mouseY = (e.clientY - rect.top) * dpr;

    const zoomFactor = Math.exp(-e.deltaY * 0.0012);
    const newScale = clamp(scale * zoomFactor, 0.5, 4);

    const worldBefore = {
      x: (mouseX - offsetX) / scale,
      y: (mouseY - offsetY) / scale
    };

    scale = newScale;

    offsetX = mouseX - worldBefore.x * scale;
    offsetY = mouseY - worldBefore.y * scale;

    render();
  }, { passive: false });

  resetBtn.addEventListener('click', resetView);

  // ----- Hit testing -----
  function hitTest(clientX, clientY) {
    const rect = canvas.getBoundingClientRect();
    const x = (clientX - rect.left) * dpr;
    const y = (clientY - rect.top) * dpr;

    const world = screenToWorld(x, y);
    const cellSize = tileBaseSize;
    const col = Math.floor(world.x / cellSize);
    const row = Math.floor(world.y / cellSize);

    if (row < 0 || row >= rows || col < 0 || col >= cols) return null;

    const index = row * cols + col;
    return { index, row, col };
  }

  // ----- Rendering -----
  function render() {
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    ctx.save();
    ctx.translate(offsetX, offsetY);
    ctx.scale(scale, scale);

    const cellSize = tileBaseSize;
    const pad = 2;

    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        const idx = row * cols + col;
        const s = stocks[idx];
        const x = col * cellSize;
        const y = row * cellSize;

        ctx.fillStyle = colorForChange(s.changePct);
        ctx.fillRect(x + pad, y + pad, cellSize - pad * 2, cellSize - pad * 2);

        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.lineWidth = 1;
        ctx.strokeRect(x + pad, y + pad, cellSize - pad * 2, cellSize - pad * 2);

        // label
        ctx.fillStyle = textColorForBg(s.changePct);
        ctx.font = '12px system-ui, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(s.symbol, x + cellSize / 2, y + cellSize / 2 - 5);

        ctx.font = '10px system-ui, sans-serif';
        const pct = `${s.changePct >= 0 ? '+' : ''}${s.changePct.toFixed(1)}%`;
        ctx.fillText(pct, x + cellSize / 2, y + cellSize / 2 + 8);
      }
    }

    ctx.restore();

    statusEl.textContent = `Connected: simulated feed | ${rows * cols} stocks | zoom: ${scale.toFixed(2)}x`;
  }

  // ----- Real-time updates (simulated)
  let streaming = true;
  function updateMarket() {
    if (streaming) {
      for (const s of stocks) {
        const jitter = (Math.random() - 0.5) * 0.35;
        const drift = Math.sin(Date.now() / 5000 + s.price * 0.01) * 0.03;

        s.changePct = clamp(s.changePct + jitter + drift, -12, 12);
        s.price = Math.max(0.5, s.price * (1 + (jitter + drift) / 100));

        s.volume = Math.max(1, Math.round(s.volume * (0.95 + Math.random() * 0.1)));
      }
      render();
    }
  }

  const streamTimer = setInterval(updateMarket, 1000);

  toggleStreamBtn.addEventListener('click', () => {
    streaming = !streaming;
    toggleStreamBtn.textContent = streaming ? 'Pause Stream' : 'Resume Stream';
    statusEl.textContent = streaming ? 'Connected: simulated feed' : 'Stream paused';
  });

  // Initial setup
  resize();
  resetView();
})();
</script>
</body>
</html>
