      { symbol: 'UNH', name: 'UnitedHealth', sector: 'Health', price: 489.20, change: -0.31 },
      { symbol: 'COST', name: 'Costco', sector: 'Consumer', price: 811.75, change: 0.52 },
      { symbol: 'WMT', name: 'Walmart', sector: 'Consumer', price: 67.41, change: 0.12 },
      { symbol: 'ORCL', name: 'Oracle', sector: 'Tech', price: 137.22, change: -0.47 },
      { symbol: 'ADBE', name: 'Adobe', sector: 'Tech', price: 498.08, change: 0.88 },
      { symbol: 'KO', name: 'Coca-Cola', sector: 'Consumer', price: 62.14, change: -0.09 },
      { symbol: 'PEP', name: 'PepsiCo', sector: 'Consumer', price: 172.66, change: 0.21 }
    ];

    function initCells() {
      const cellW = 170;
      const cellH = 90;
      state.gridRows = Math.ceil(stocks.length / state.gridCols);

      state.cells = stocks.map((s, i) => {
        const col = i % state.gridCols;
        const row = Math.floor(i / state.gridCols);
        return {
          ...s,
          x: col * (cellW + 12),
          y: row * (cellH + 12),
          w: cellW,
          h: cellH
        };
      });
    }

    function resize() {
      state.width = canvas.clientWidth = window.innerWidth;
      state.height = canvas.clientHeight = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      render();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function changeToColor(change) {
      // Map percentage change to a red-green gradient.
      // clamp range around +/- 5%
      const t = clamp((change + 5) / 10, 0, 1);
      const r = Math.round(255 * (1 - t));
      const g = Math.round(255 * t);
      const b = 70;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function colorText(change) {
      return change >= 0 ? '#dcfce7' : '#fee2e2';
    }

    function drawRoundRect(x, y, w, h, r) {
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + w, y, x + w, y + h, r);
      ctx.arcTo(x + w, y + h, x, y + h, r);
      ctx.arcTo(x, y + h, x, y, r);
      ctx.arcTo(x, y, x + w, y, r);
      ctx.closePath();
    }

    function worldToScreen(x, y) {
      return {
        x: x * state.scale + state.panX,
        y: y * state.scale + state.panY
      };
    }

    function screenToWorld(x, y) {
      return {
        x: (x - state.panX) / state.scale,
        y: (y - state.panY) / state.scale
      };
    }

    function getCellAtMouse(mx, my) {
      const p = screenToWorld(mx, my);
      return state.cells.find(cell =>
        p.x >= cell.x && p.x <= cell.x + cell.w &&
        p.y >= cell.y && p.y <= cell.y + cell.h
      ) || null;
    }

    function render() {
      ctx.clearRect(0, 0, state.width, state.height);

      // Background
      ctx.fillStyle = '#0f1115';
      ctx.fillRect(0, 0, state.width, state.height);

      // Apply world transform
      ctx.save();
      ctx.translate(state.panX, state.panY);
      ctx.scale(state.scale, state.scale);

      // Draw cells
      for (const cell of state.cells) {
        const isHover = state.hoverCell && state.hoverCell.symbol === cell.symbol;
        const fill = changeToColor(cell.change);

        ctx.fillStyle = fill;
        ctx.globalAlpha = isHover ? 0.95 : 0.8;
        drawRoundRect(cell.x, cell.y, cell.w, cell.h, 12);
        ctx.fill();

        ctx.globalAlpha = 1;
        ctx.strokeStyle = isHover ? 'rgba(255,255,255,0.85)' : 'rgba(255,255,255,0.08)';
        ctx.lineWidth = isHover ? 2 : 1;
        ctx.stroke();

        // Text
        ctx.fillStyle = '#0b1220';
        ctx.font = 'bold 16px system-ui, sans-serif';
        ctx.fillText(cell.symbol, cell.x + 12, cell.y + 24);

        ctx.font = '12px system-ui, sans-serif';
        ctx.fillStyle = 'rgba(11,18,32,0.85)';
        ctx.fillText(cell.name, cell.x + 12, cell.y + 42);

        ctx.font = 'bold 14px system-ui, sans-serif';
        ctx.fillStyle = colorText(cell.change);
        ctx.fillText(`$${cell.price.toFixed(2)}`, cell.x + 12, cell.y + 63);

        const ch = `${cell.change >= 0 ? '+' : ''}${cell.change.toFixed(2)}%`;
        ctx.fillStyle = colorText(cell.change);
        ctx.fillText(ch, cell.x + cell.w - 56, cell.y + 63);
      }

      ctx.restore();

      requestAnimationFrame(render);
    }

    function updateTooltip(mx, my, cell) {
      if (!cell) {
        tooltip.style.display = 'none';
        return;
      }

      tooltip.style.display = 'block';
      tooltip.style.left = `${mx}px`;
      tooltip.style.top = `${my}px`;
      tooltip.innerHTML = `
        <strong>${cell.symbol} — ${cell.name}</strong><br/>
        Sector: ${cell.sector}<br/>
        Price: $${cell.price.toFixed(2)}<br/>
        Change: <span style="color:${cell.change >= 0 ? '#4ade80' : '#f87171'}">
          ${cell.change >= 0 ? '+' : ''}${cell.change.toFixed(2)}%
        </span>
      `;
    }

    // Real-time updates simulation
    function tickPrices() {
      for (const s of state.cells) {
        const volatility = 0.35;
        const delta = (Math.random() - 0.5) * volatility;

        s.change = clamp(s.change + delta, -9.99, 9.99);
        s.price = Math.max(0.01, s.price * (1 + delta / 100));
      }
    }

    // Interaction
    app.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      app.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      app.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      const cell = getCellAtMouse(e.clientX, e.clientY);
      state.hoverCell = cell;
      updateTooltip(e.clientX, e.clientY, cell);

      if (state.dragging) {
        const dx = e.clientX - state.lastX;
        const dy = e.clientY - state.lastY;
        state.panX += dx;
        state.panY += dy;
        state.lastX = e.clientX;
        state.lastY = e.clientY;
      }
    });

    app.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const before = screenToWorld(mouseX, mouseY);

      state.scale = clamp(state.scale * zoomFactor, 0.5, 3);

      const after = screenToWorld(mouseX, mouseY);

      state.panX += (after.x - before.x) * state.scale;
      state.panY += (after.y - before.y) * state.scale;
    }, { passive: false });

    window.addEventListener('resize', resize);

    initCells();
    resize();
    setInterval(tickPrices, 1000);
  </script>
</body>
</html>
```

