      <span class="swatch" style="background:#b91c1c"></span><span>Down</span>
      <span class="swatch" style="background:#1f2937"></span><span>Flat</span>
      <span class="swatch" style="background:#15803d"></span><span>Up</span>
    </div>
  </div>
  <div id="tooltip"></div>
  <canvas id="c"></canvas>
</div>

<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const tooltip = document.getElementById('tooltip');
  const app = document.getElementById('app');

  // Demo "stocks"
  const symbols = Array.from({ length: 120 }, (_, i) => `STK${String(i + 1).padStart(3, '0')}`);
  const prices = Object.fromEntries(symbols.map(s => [s, 50 + Math.random() * 150]));
  const prevPrices = Object.fromEntries(symbols.map(s => [s, prices[s]]));

  // Grid layout (fixed for minimal example)
  const cols = 12;
  const rows = Math.ceil(symbols.length / cols);

  // View transforms
  let scale = 1;
  let offsetX = 0;
  let offsetY = 0;

  let dragging = false;
  let lastX = 0;
  let lastY = 0;

  let dpr = Math.max(1, window.devicePixelRatio || 1);

  function resize() {
    const rect = app.getBoundingClientRect();
    dpr = Math.max(1, window.devicePixelRatio || 1);
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    draw();
  }

  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }

  function lerp(a, b, t) { return a + (b - a) * t; }

  function priceToColor(changePct) {
    // -5% => red, 0 => dark, +5% => green
    const t = clamp((changePct + 5) / 10, 0, 1);
    const r = Math.round(lerp(185, 21, t));
    const g = Math.round(lerp(28, 128, t));
    const b = Math.round(lerp(28, 61, t));
    return `rgb(${r},${g},${b})`;
  }

  function draw() {
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // Background
    ctx.fillStyle = '#0b1020';
    ctx.fillRect(0, 0, w, h);

    // World transform
    ctx.save();
    ctx.scale(scale * dpr, scale * dpr);
    ctx.translate(offsetX, offsetY);

    const cellW = 120;
    const cellH = 70;
    const gap = 8;
    const pad = 16;

    // Draw each stock cell
    symbols.forEach((sym, i) => {
      const row = Math.floor(i / cols);
      const col = i % cols;
      const x = pad + col * (cellW + gap);
      const y = pad + row * (cellH + gap);

      const p = prices[sym];
      const pp = prevPrices[sym];
      const changePct = ((p - pp) / pp) * 100;

      ctx.fillStyle = priceToColor(changePct);
      roundRect(ctx, x, y, cellW, cellH, 10);
      ctx.fill();

      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.stroke();

      ctx.fillStyle = '#fff';
      ctx.font = 'bold 14px system-ui, sans-serif';
      ctx.fillText(sym, x + 10, y + 24);

      ctx.font = '12px system-ui, sans-serif';
      ctx.fillStyle = 'rgba(255,255,255,0.9)';
      ctx.fillText(`$${p.toFixed(2)}`, x + 10, y + 44);

      ctx.fillStyle = changePct >= 0 ? '#86efac' : '#fca5a5';
      ctx.fillText(`${changePct >= 0 ? '▲' : '▼'} ${Math.abs(changePct).toFixed(2)}%`, x + 10, y + 60);
    });

    ctx.restore();
  }

  function roundRect(ctx, x, y, w, h, r) {
    const min = Math.min(w, h) / 2;
    r = Math.min(r, min);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function toWorld(clientX, clientY) {
    const rect = canvas.getBoundingClientRect();
    const x = (clientX - rect.left) / scale - offsetX;
    const y = (clientY - rect.top) / scale - offsetY;
    return { x, y };
  }

  function hitTest(x, y) {
    const cellW = 120, cellH = 70, gap = 8, pad = 16;
    for (let i = 0; i < symbols.length; i++) {
      const row = Math.floor(i / cols);
      const col = i % cols;
      const cx = pad + col * (cellW + gap);
      const cy = pad + row * (cellH + gap);
      if (x >= cx && x <= cx + cellW && y >= cy && y <= cy + cellH) return { i, x: cx, y: cy };
    }
    return null;
  }

  // Zoom centered on cursor
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const rect = canvas.getBoundingClientRect();
    const mx = (e.clientX - rect.left) / dpr;
    const my = (e.clientY - rect.top) / dpr;

    const worldX = mx / scale - offsetX;
    const worldY = my / scale - offsetY;

    const zoomFactor = e.deltaY > 0 ? 0.9 : 1.1;
    const nextScale = clamp(scale * zoomFactor, 0.5, 4);

    offsetX = mx / nextScale - worldX;
    offsetY = my / nextScale - worldY;
    scale = nextScale;
    draw();
  }, { passive: false });

  canvas.addEventListener('pointerdown', (e) => {
    dragging = true;
    lastX = e.clientX;
    lastY = e.clientY;
    canvas.setPointerCapture(e.pointerId);
  });

  canvas.addEventListener('pointermove', (e) => {
    if (dragging) {
      const dx = (e.clientX - lastX) / scale;
      const dy = (e.clientY - lastY) / scale;
      offsetX += dx / dpr;
      offsetY += dy / dpr;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
      return;
    }

    const rect = canvas.getBoundingClientRect();
    const px = (e.clientX - rect.left) * dpr;
    const py = (e.clientY - rect.top) * dpr;
    const world = {
      x: px / (scale * dpr) - offsetX,
      y: py / (scale * dpr) - offsetY
    };
    const hit = hitTest(world.x, world.y);
    if (hit) {
      const sym = symbols[hit.i];
      const p = prices[sym];
      const pp = prevPrices[sym];
      const ch = ((p - pp) / pp) * 100;
      tooltip.style.display = 'block';
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
      tooltip.innerHTML = `<strong>${sym}</strong><br>$${p.toFixed(2)} (${ch >= 0 ? '+' : ''}${ch.toFixed(2)}%)`;
    } else {
      tooltip.style.display = 'none';
    }
  });

  canvas.addEventListener('pointerup', (e) => {
    dragging = false;
    try { canvas.releasePointerCapture(e.pointerId); } catch {}
  });

  canvas.addEventListener('pointerleave', () => {
    tooltip.style.display = 'none';
  });

  // Simulate live updates every 500ms
  setInterval(() => {
    symbols.forEach(sym => {
      prevPrices[sym] = prices[sym];
      const drift = (Math.random() - 0.5) * 1.5;
      prices[sym] = Math.max(1, prices[sym] * (1 + drift / 100));
    });
    draw();
  }, 500);

  window.addEventListener('resize', resize);
  resize();

  // Initial zoom/pan to fit better
  scale = 0.9;
  offsetX = 0.05;
  offsetY = 0.05;
  draw();
})();
</script>
</body>
</html>
