  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');
    const app = document.getElementById('app');

    const symbols = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AVGO','AMD','NFLX',
      'INTC','ORCL','CRM','ADBE','NOW','QCOM','IBM','SAP','UBER','SNOW',
      'JPM','BAC','WFC','GS','MS','AXP','C','V','MA','PYPL'
    ];

    let data = symbols.map((s, i) => ({
      symbol: s,
      price: 50 + Math.random() * 450,
      change: (Math.random() - 0.5) * 8,
      volume: Math.floor(1e6 + Math.random() * 9e6)
    }));

    // View state
    let scale = 1;
    let offsetX = 20;
    let offsetY = 20;

    // Grid layout
    const cellW = 120;
    const cellH = 70;
    const cols = 5;

    // Drag state
    let dragging = false;
    let dragStart = { x: 0, y: 0 };
    let offsetStart = { x: 0, y: 0 };

    let hoveredIndex = -1;

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(canvas.clientWidth * dpr);
      canvas.height = Math.floor(canvas.clientHeight * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    window.addEventListener('resize', resize);

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(chg) {
      // red -> gray -> green
      const t = clamp((chg + 8) / 16, 0, 1);
      const r = Math.round(220 * (1 - t) + 30 * t);
      const g = Math.round(40 + 170 * t);
      const b = Math.round(60 * (1 - t) + 40 * t);
      return `rgb(${r},${g},${b})`;
    }

    function draw() {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      ctx.clearRect(0, 0, w, h);

      // background
      const bg = ctx.createLinearGradient(0, 0, 0, h);
      bg.addColorStop(0, '#0b1020');
      bg.addColorStop(1, '#101a33');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);

      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      hoveredIndex = -1;

      data.forEach((item, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = col * (cellW + 10);
        const y = row * (cellH + 10);

        const fill = colorForChange(item.change);
        ctx.fillStyle = fill;
        ctx.fillRect(x, y, cellW, cellH);

        // border
        ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, cellW, cellH);

        // text
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 14px system-ui';
        ctx.fillText(item.symbol, x + 10, y + 22);

        ctx.font = '12px system-ui';
        ctx.fillText(`$${item.price.toFixed(2)}`, x + 10, y + 42);

        const ch = item.change >= 0 ? `+${item.change.toFixed(2)}%` : `${item.change.toFixed(2)}%`;
        ctx.fillText(ch, x + 10, y + 58);
      });

      ctx.restore();
    }

    function screenToWorld(px, py) {
      return {
        x: (px - offsetX) / scale,
        y: (py - offsetY) / scale
      };
    }

    function hitTest(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const p = screenToWorld(x, y);

      for (let i = 0; i < data.length; i++) {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const cx = col * (cellW + 10);
        const cy = row * (cellH + 10);
        if (p.x >= cx && p.x <= cx + cellW && p.y >= cy && p.y <= cy + cellH) {
          return { index: i, x: cx, y: cy, screenX: x, screenY: y };
        }
      }
      return null;
    }

    canvas.addEventListener('mousemove', (e) => {
      if (dragging) {
        offsetX = offsetStart.x + (e.clientX - dragStart.x);
        offsetY = offsetStart.y + (e.clientY - dragStart.y);
        draw();
        return;
      }

      const hit = hitTest(e.clientX, e.clientY);
      if (hit) {
        hoveredIndex = hit.index;
        const item = data[hit.index];
        tooltip.style.display = 'block';
        tooltip.style.left = (e.clientX + 12) + 'px';
        tooltip.style.top = (e.clientY + 12) + 'px';
        tooltip.innerHTML = `
          <strong>${item.symbol}</strong><br>
          Price: $${item.price.toFixed(2)}<br>
          Change: ${item.change >= 0 ? '+' : ''}${item.change.toFixed(2)}%<br>
          Volume: ${item.volume.toLocaleString()}
        `;
      } else {
        tooltip.style.display = 'none';
      }
    });

    canvas.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
    });

    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      dragStart = { x: e.clientX, y: e.clientY };
      offsetStart = { x: offsetX, y: offsetY };
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const worldBefore = screenToWorld(mx, my);

      scale = clamp(scale * zoomFactor, 0.5, 3);

      offsetX = mx - worldBefore.x * scale;
      offsetY = my - worldBefore.y * scale;

      draw();
    }, { passive: false });

    // Simulated real-time updates
    setInterval(() => {
      data = data.map(item => {
        const drift = (Math.random() - 0.5) * 1.8;
        const price = Math.max(1, item.price + drift);
        const change = Math.max(-8, Math.min(8, item.change + (Math.random() - 0.5) * 0.6));
        const volume = item.volume + Math.floor(Math.random() * 5000);
        return { ...item, price, change, volume };
      });
      draw();
    }, 1000);

    resize();
  </script>
