      color: white;
    }

    #toolbar {
      position: fixed;
      top: 10px;
      left: 10px;
      z-index: 10;
      background: rgba(17, 24, 39, 0.9);
      padding: 10px 12px;
      border-radius: 8px;
      font-size: 14px;
      backdrop-filter: blur(6px);
    }

    #heatmap {
      width: 100vw;
      height: 100vh;
      position: relative;
      overflow: hidden;
      cursor: grab;
      user-select: none;
    }

    #heatmap:active {
      cursor: grabbing;
    }

    #grid {
      position: absolute;
      left: 0;
      top: 0;
      transform-origin: 0 0;
      will-change: transform;
    }

    .tile {
      position: absolute;
      box-sizing: border-box;
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 8px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 8px;
      color: white;
      overflow: hidden;
      transition: background-color 0.25s linear;
    }

    .symbol {
      font-weight: bold;
      font-size: 14px;
    }

    .price, .change {
      font-size: 12px;
      opacity: 0.9;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <div><b>Stock Heatmap</b></div>
    <div>Wheel: Zoom</div>
    <div>Drag: Pan</div>
    <div>Realtime: Simulated</div>
  </div>

  <div id="heatmap">
    <div id="grid"></div>
  </div>

  <script>
    const heatmap = document.getElementById('heatmap');
    const grid = document.getElementById('grid');

    // Sample stocks
    const symbols = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD',
      'NFLX','INTC','ORCL','ADBE','CRM','UBER','SHOP','QCOM'
    ];

    const tiles = [];
    const cols = 4;
    const tileW = 180;
    const tileH = 110;
    const gap = 12;

    // View transform
    let scale = 1;
    let panX = 40;
    let panY = 80;
    let isPanning = false;
    let startX = 0;
    let startY = 0;

    // Generate mock data
    const stocks = symbols.map((symbol, i) => {
      const base = 50 + Math.random() * 450;
      return {
        symbol,
        price: base,
        prev: base,
        change: 0
      };
    });

    function getColor(change) {
      // Red for negative, green for positive
      const abs = Math.min(Math.abs(change), 5);
      const intensity = Math.floor(80 + abs * 35);
      if (change >= 0) {
        return `rgb(20, ${Math.min(180, intensity)}, 60)`;
      } else {
        return `rgb(${Math.min(180, intensity)}, 40, 45)`;
      }
    }

    function renderGrid() {
      grid.innerHTML = '';
      stocks.forEach((stock, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;

        const tile = document.createElement('div');
        tile.className = 'tile';
        tile.style.left = `${col * (tileW + gap)}px`;
        tile.style.top = `${row * (tileH + gap)}px`;
        tile.style.width = `${tileW}px`;
        tile.style.height = `${tileH}px`;
        tile.style.background = getColor(stock.change);

        tile.innerHTML = `
          <div class="symbol">${stock.symbol}</div>
          <div class="price">$${stock.price.toFixed(2)}</div>
          <div class="change">${stock.change >= 0 ? '+' : ''}${stock.change.toFixed(2)}%</div>
        `;

        grid.appendChild(tile);
        tiles.push(tile);
      });

      const rows = Math.ceil(stocks.length / cols);
      grid.style.width = `${cols * tileW + (cols - 1) * gap}px`;
      grid.style.height = `${rows * tileH + (rows - 1) * gap}px`;
    }

    function updatePrices() {
      stocks.forEach((stock, i) => {
        stock.prev = stock.price;
        const movement = (Math.random() - 0.5) * 4; // random change
        stock.price = Math.max(1, stock.price + movement);
        stock.change = ((stock.price - stock.prev) / stock.prev) * 100;
      });

      // Update DOM
      const tileEls = grid.querySelectorAll('.tile');
      stocks.forEach((stock, i) => {
        const tile = tileEls[i];
        tile.style.background = getColor(stock.change);
        tile.querySelector('.price').textContent = `$${stock.price.toFixed(2)}`;
        tile.querySelector('.change').textContent = `${stock.change >= 0 ? '+' : ''}${stock.change.toFixed(2)}%`;
      });
    }

    function applyTransform() {
      grid.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    // Zoom with wheel
    heatmap.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const rect = heatmap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      scale *= zoomFactor;
      scale = Math.min(Math.max(scale, 0.5), 3);

      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      applyTransform();
    }, { passive: false });

    // Pan with drag
    heatmap.addEventListener('mousedown', (e) => {
      isPanning = true;
      startX = e.clientX - panX;
      startY = e.clientY - panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!isPanning) return;
      panX = e.clientX - startX;
      panY = e.clientY - startY;
      applyTransform();
    });

    window.addEventListener('mouseup', () => {
      isPanning = false;
    });

    // Init
    renderGrid();
    applyTransform();
    updatePrices();
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
```

