      "SQ","BX","ETSY","LULU","NOW","TEAM","PANW","DDOG","CRWD","ZS"
    ];

    // Create data
    const cells = [];
    let idx = 0;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        cells.push({
          symbol: symbols[idx % symbols.length],
          row: r,
          col: c,
          price: 100 + Math.random() * 100,
          change: (Math.random() - 0.5) * 10
        });
        idx++;
      }
    }

    const state = {
      scale: 1,
      offsetX: 0,
      offsetY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startOffsetX: 0,
      startOffsetY: 0
    };

    function getColor(change) {
      // Red for negative, green for positive
      const maxAbs = 10;
      const t = Math.max(-1, Math.min(1, change / maxAbs));
      if (t >= 0) {
        const g = Math.floor(80 + t * 175);
        return `rgb(20, ${g}, 60)`;
      } else {
        const r = Math.floor(80 + (-t) * 175);
        return `rgb(${r}, 40, 40)`;
      }
    }

    function render() {
      heatmap.innerHTML = '';
      const w = heatmap.clientWidth;
      const h = heatmap.clientHeight;
      const cellW = w / cols;
      const cellH = h / rows;

      cells.forEach(cell => {
        const el = document.createElement('div');
        el.className = 'cell';
        el.style.width = `${cellW * state.scale}px`;
        el.style.height = `${cellH * state.scale}px`;
        el.style.left = `${cell.col * cellW * state.scale + state.offsetX}px`;
        el.style.top = `${cell.row * cellH * state.scale + state.offsetY}px`;
        el.style.background = getColor(cell.change);
        el.innerHTML = `
          <div class="label">
            <div><b>${cell.symbol}</b></div>
            <div>$${cell.price.toFixed(2)}</div>
            <div>${cell.change >= 0 ? '+' : ''}${cell.change.toFixed(2)}%</div>
