    // Zoom around mouse pointer
    heatmap.addEventListener('wheel', (e) => {
      e.preventDefault();
      const rect = heatmap.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.min(4, Math.max(0.5, state.scale * zoomFactor));

      // Keep mouse position anchored while zooming
      state.offsetX = mx - (mx - state.offsetX) * (newScale / state.scale);
      state.offsetY = my - (my - state.offsetY) * (newScale / state.scale);
      state.scale = newScale;

      render();
    }, { passive: false });

    // Pan
