      font-size: 12px;
    }

    #legend-bar {
      width: 180px;
      height: 12px;
      margin-top: 6px;
      border-radius: 6px;
      background: linear-gradient(90deg, #b91c1c, #f59e0b, #111827, #22c55e, #15803d);
      border: 1px solid rgba(255,255,255,0.15);
    }

    #instructions {
      position: absolute;
      top: 12px;
      left: 12px;
      padding: 8px 10px;
      background: rgba(17, 24, 39, 0.85);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: 8px;
      font-size: 12px;
      line-height: 1.5;
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="canvas"></canvas>
    <div id="tooltip"></div>
    <div id="instructions">
      <div><strong>Controls</strong></div>
      <div>Wheel: zoom</div>
      <div>Drag: pan</div>
      <div>Move mouse: inspect</div>
    </div>
    <div id="legend">
      <div>Return color</div>
      <div id="legend-bar"></div>
      <div>Red ← negative | neutral | positive → Green</div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const app = document.getElementById('app');
    const tooltip = document.getElementById('tooltip');

    let dpr = window.devicePixelRatio || 1;
    let width = 0, height = 0;

    // Simulated stocks
    const stocks = Array.from({ length: 120 }, (_, i) => ({
      symbol: `STK${String(i + 1).padStart(3, '0')}`,
      price: 50 + Math.random() * 150,
      prev: 50 + Math.random() * 150,
      volume: 100000 + Math.random() * 900000,
      x: 0,
      y: 0
    }));

    // Layout
    const gridCols = 12;
    const cellW = 120;
    const cellH = 80;
    const gap = 8;

    // View transform
    let scale = 1;
    let offsetX = 20;
    let offsetY = 20;

    // Pointer state
    let dragging = false;
    let lastX = 0;
    let lastY = 0;
    let pointerX = 0;
    let pointerY = 0;

    function resize() {
      dpr = window.devicePixelRatio || 1;
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }

    function updateLayout() {
      stocks.forEach((s, i) => {
        const col = i % gridCols;
        const row = Math.floor(i / gridCols);
        s.x = col * (cellW + gap);
        s.y = row * (cellH + gap);
      });
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function returnPct(stock) {
      return ((stock.price - stock.prev) / stock.prev) * 100;
    }

    function colorForReturn(pct) {
      // Map roughly from -5%..+5%
      const t = clamp((pct + 5) / 10, 0, 1);
      if (t < 0.5) {
        const k = t / 0.5;
        return lerpColor([185, 28, 28], [17, 24, 39], k);
      } else {
        const k = (t - 0.5) / 0.5;
        return lerpColor([17, 24, 39], [34, 197, 94], k);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r},${g},${b2})`;
    }

    function worldToScreen(x, y) {
      return {
        x: x * scale + offsetX,
        y: y * scale + offsetY
      };
    }

    function screenToWorld(x, y) {
      return {
        x: (x - offsetX) / scale,
        y: (y - offsetY) / scale
      };
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = '#0b1220';
      ctx.fillRect(0, 0, width, height);

      // Draw cells
      const hovered = getHoveredStock();
      stocks.forEach(stock => {
        const sx = stock.x * scale + offsetX;
        const sy = stock.y * scale + offsetY;
        const sw = cellW * scale;
        const sh = cellH * scale;

        if (sx + sw < 0 || sy + sh < 0 || sx > width || sy > height) return;

        const pct = returnPct(stock);
        ctx.fillStyle = colorForReturn(pct);
        ctx.fillRect(sx, sy, sw, sh);

        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.strokeRect(sx, sy, sw, sh);

        if (hovered === stock) {
          ctx.strokeStyle = 'rgba(255,255,255,0.9)';
          ctx.lineWidth = 2;
          ctx.strokeRect(sx + 1, sy + 1, sw - 2, sh - 2);
          ctx.lineWidth = 1;
        }

        if (sw > 45 && sh > 30) {
          ctx.fillStyle = '#f9fafb';
          ctx.font = `${Math.max(10, 12 * scale)}px system-ui, sans-serif`;
          ctx.fillText(stock.symbol, sx + 8, sy + 18);
          ctx.fillStyle = 'rgba(255,255,255,0.9)';
          ctx.fillText(`${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%`, sx + 8, sy + 36);
        }
      });

      requestAnimationFrame(draw);
    }

    function getHoveredStock() {
      const world = screenToWorld(pointerX, pointerY);
      return stocks.find(s =>
        world.x >= s.x &&
        world.x <= s.x + cellW &&
        world.y >= s.y &&
        world.y <= s.y + cellH
      ) || null;
    }

    function updateTooltip() {
      const hovered = getHoveredStock();
      if (!hovered) {
        tooltip.style.display = 'none';
        return;
      }

      const pct = returnPct(hovered);
      tooltip.style.display = 'block';
      tooltip.style.left = (pointerX + 14) + 'px';
      tooltip.style.top = (pointerY + 14) + 'px';
      tooltip.innerHTML = `
        <div><strong>${hovered.symbol}</strong></div>
        <div>Price: $${hovered.price.toFixed(2)}</div>
        <div>Prev: $${hovered.prev.toFixed(2)}</div>
        <div>Return: ${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%</div>
      `;
    }

    function zoomAt(screenX, screenY, zoomFactor) {
      const before = screenToWorld(screenX, screenY);
      scale = clamp(scale * zoomFactor, 0.4, 4);
      const after = worldToScreen(before.x, before.y);
      offsetX += screenX - after.x;
      offsetY += screenY - after.y;
    }

    app.addEventListener('pointerdown', (e) => {
      dragging = true;
      app.classList.add('dragging');
      lastX = e.clientX;
      lastY = e.clientY;
      app.setPointerCapture(e.pointerId);
    });

    app.addEventListener('pointermove', (e) => {
      pointerX = e.clientX;
      pointerY = e.clientY;
      updateTooltip();

      if (!dragging) return;
      const dx = e.clientX - lastX;
      const dy = e.clientY - lastY;
      offsetX += dx;
      offsetY += dy;
      lastX = e.clientX;
      lastY = e.clientY;
    });

    app.addEventListener('pointerup', (e) => {
      dragging = false;
      app.classList.remove('dragging');
      try { app.releasePointerCapture(e.pointerId); } catch {}
    });

    app.addEventListener('pointerleave', () => {
      tooltip.style.display = 'none';
    });

    app.addEventListener('wheel', (e) => {
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.1 : 0.9;
      zoomAt(e.clientX, e.clientY, factor);
    }, { passive: false });

    // Simulate real-time market updates
    setInterval(() => {
      stocks.forEach(stock => {
        stock.prev = stock.price;
        const drift = (Math.random() - 0.5) * 2.0;
        stock.price = Math.max(1, stock.price * (1 + drift / 100));
        stock.volume = Math.max(1000, stock.volume * (0.95 + Math.random() * 0.1));
      });
    }, 1000);

    // Initial setup
    window.addEventListener('resize', resize);
    resize();
    updateLayout();

    // Center content initially
    const totalCols = gridCols;
    const totalRows = Math.ceil(stocks.length / gridCols);
    const contentW = totalCols * cellW + (totalCols - 1) * gap;
    const contentH = totalRows * cellH + (totalRows - 1) * gap;
    offsetX = Math.max(20, (width - contentW) / 2);
    offsetY = Math.max(20, (height - contentH) / 2);

    draw();
  </script>
</body>
</html>
```

