</head>
<body>
  <div id="toolbar">
    <button id="resetBtn">Reset View</button>
    <button id="pauseBtn">Pause</button>
    <span id="info">Wheel: zoom • Drag: pan • Hover: inspect</span>
  </div>
  <canvas id="heatmap"></canvas>
  <div id="tooltip"></div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");
    const pauseBtn = document.getElementById("pauseBtn");

    let dpr = Math.max(1, window.devicePixelRatio || 1);
    let width = 0, height = 0;

    const symbols = Array.from({ length: 180 }, (_, i) => `STK${String(i + 1).padStart(3, "0")}`);
    const stocks = symbols.map((symbol) => ({
      symbol,
      price: 50 + Math.random() * 200,
      prev: 50 + Math.random() * 200,
    }));

    const cols = 15;
    const cellW = 110;
    const cellH = 70;
    const gap = 8;
    const margin = 20;

    let panX = 0;
    let panY = 0;
    let zoom = 1;

    let dragging = false;
    let dragStart = { x: 0, y: 0, panX: 0, panY: 0 };

    let paused = false;
    let mouse = { x: 0, y: 0 };

    function resize() {
      dpr = Math.max(1, window.devicePixelRatio || 1);
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + "px";
      canvas.style.height = height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function priceChange(stock) {
      return ((stock.price - stock.prev) / stock.prev) * 100;
    }

    function colorForChange(change) {
      // Red for negative, green for positive, gray near zero
      const intensity = Math.min(1, Math.abs(change) / 5);
      if (change >= 0) {
        const g = Math.floor(90 + 140 * intensity);
        return `rgb(${30},${g},${60})`;
      } else {
        const r = Math.floor(90 + 140 * intensity);
        return `rgb(${r},${40},${40})`;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = "#0f1115";
      ctx.fillRect(0, 0, width, height);

      ctx.save();
      ctx.translate(panX, panY);
      ctx.scale(zoom, zoom);

      stocks.forEach((stock, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;

        const x = margin + col * (cellW + gap);
        const y = margin + row * (cellH + gap);
        const pct = priceChange(stock);
        const fill = colorForChange(pct);

        ctx.fillStyle = fill;
        ctx.fillRect(x, y, cellW, cellH);

        ctx.strokeStyle = "rgba(255,255,255,0.08)";
        ctx.strokeRect(x, y, cellW, cellH);

        ctx.fillStyle = "#fff";
        ctx.font = "bold 14px system-ui, sans-serif";
        ctx.fillText(stock.symbol, x + 10, y + 24);

        ctx.font = "12px system-ui, sans-serif";
        ctx.fillText(stock.price.toFixed(2), x + 10, y + 44);

        ctx.fillStyle = pct >= 0 ? "#d8ffe0" : "#ffd6d6";
        ctx.fillText((pct >= 0 ? "+" : "") + pct.toFixed(2) + "%", x + 10, y + 60);
      });

      ctx.restore();
    }

    function screenToWorld(px, py) {
      return {
        x: (px - panX) / zoom,
        y: (py - panY) / zoom
      };
    }

    function stockAtMouse() {
      const p = screenToWorld(mouse.x, mouse.y);

      for (let i = 0; i < stocks.length; i++) {
        const row = Math.floor(i / cols);
        const col = i % cols;
        const x = margin + col * (cellW + gap);
        const y = margin + row * (cellH + gap);

        if (p.x >= x && p.x <= x + cellW && p.y >= y && p.y <= y + cellH) {
          return { stock: stocks[i], x, y };
        }
      }
      return null;
    }

    function showTooltip(hit) {
      if (!hit) {
        tooltip.style.display = "none";
        return;
      }
      const { stock } = hit;
      const pct = priceChange(stock);
      tooltip.style.display = "block";
      tooltip.style.left = (mouse.x + 12) + "px";
      tooltip.style.top = (mouse.y + 12) + "px";
      tooltip.innerHTML = `
        <div><strong>${stock.symbol}</strong></div>
        <div>Price: ${stock.price.toFixed(2)}</div>
        <div>Change: ${(pct >= 0 ? "+" : "") + pct.toFixed(2)}%</div>
      `;
    }

    function updatePrices() {
      if (!paused) {
        stocks.forEach((s) => {
          s.prev = s.price;
          const drift = (Math.random() - 0.5) * 2.2;
          s.price = Math.max(1, s.price + drift);
        });
        draw();
      }
      requestAnimationFrame(updatePrices);
    }

    canvas.addEventListener("mousemove", (e) => {
      mouse.x = e.clientX;
      mouse.y = e.clientY;

      if (dragging) {
        panX = dragStart.panX + (e.clientX - dragStart.x);
        panY = dragStart.panY + (e.clientY - dragStart.y);
        draw();
      }

      showTooltip(stockAtMouse());
    });

    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      dragStart = { x: e.clientX, y: e.clientY, panX, panY };
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
    });

    canvas.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newZoom = Math.min(3, Math.max(0.4, zoom * zoomFactor));

      const mx = e.clientX;
      const my = e.clientY;

      // Zoom around mouse position
      const worldBefore = screenToWorld(mx, my);
      zoom = newZoom;
      panX = mx - worldBefore.x * zoom;
      panY = my - worldBefore.y * zoom;

      draw();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      panX = 0;
      panY = 0;
      zoom = 1;
      draw();
    });

    pauseBtn.addEventListener("click", () => {
      paused = !paused;
      pauseBtn.textContent = paused ? "Resume" : "Pause";
    });

    window.addEventListener("resize", resize);

    resize();
    updatePrices();
  </script>
</body>
</html>
