      Volume: ${s.volume.toLocaleString()}
    `;
    tooltip.style.left = (e.clientX + 14) + "px";
    tooltip.style.top = (e.clientY + 14) + "px";
  }

  function hideTooltip() {
    tooltip.style.display = "none";
  }

  function selectStock(s) {
    selectionText.innerHTML = `
      <strong>${s.ticker}</strong><br/>
      Price: $${s.price.toFixed(2)}<br/>
      Change: ${s.change >= 0 ? "+" : ""}${s.change.toFixed(2)}%<br/>
      Volume: ${s.volume.toLocaleString()}
    `;
  }

  // Real-time synthetic updates
  setInterval(() => {
    if (paused) return;

    stocks.forEach(s => {
      const drift = (Math.random() - 0.5) * 0.6;
      s.change = Math.max(-8, Math.min(8, s.change + drift));
      s.price = Math.max(1, s.price * (1 + (Math.random() - 0.5) * 0.01));
      s.volume += Math.floor(Math.random() * 5000);
    });

    stocks.forEach((s, i) => {
      const cell = cells.get(i);
      if (!cell) return;
      cell.style.background = heatColor(s.change);
      cell.querySelector(".price").textContent = `$${s.price.toFixed(2)}`;
      cell.querySelectorAll("div")[2].textContent = `${s.change >= 0 ? "+" : ""}${s.change.toFixed(2)}%`;
    });

    status.textContent = paused ? "Live updates: paused" : "Live updates: on";
  }, 1000);

  // Zoom with wheel
  mapWrap.addEventListener("wheel", (e) => {
    e.preventDefault();

    const zoomIntensity = 0.0015;
    const rect = mapWrap.getBoundingClientRect();

    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    const delta = -e.deltaY;
    const prevScale = scale;
    scale = Math.max(0.5, Math.min(4, scale * (1 + delta * zoomIntensity)));

    // Zoom toward pointer
    const worldX = (mx - offsetX) / prevScale;
    const worldY = (my - offsetY) / prevScale;
    offsetX = mx - worldX * scale;
    offsetY = my - worldY * scale;

    updateTransform();
  }, { passive: false });

  // Pan with drag
  mapWrap.addEventListener("mousedown", (e) => {
    dragging = true;
    mapWrap.classList.add("dragging");
    dragStart.x = e.clientX - offsetX;
    dragStart.y = e.clientY - offsetY;
  });

  window.addEventListener("mousemove", (e) => {
    if (!dragging) return;
    offsetX = e.clientX - dragStart.x;
    offsetY = e.clientY - dragStart.y;
    updateTransform();
  });

  window.addEventListener("mouseup", () => {
    dragging = false;
    mapWrap.classList.remove("dragging");
  });

  resetBtn.addEventListener("click", () => {
    scale = 1;
    offsetX = 20;
    offsetY = 20;
    updateTransform();
  });

  pauseBtn.addEventListener("click", () => {
    paused = !paused;
    pauseBtn.textContent = paused ? "Resume Updates" : "Pause Updates";
    status.textContent = paused ? "Live updates: paused" : "Live updates: on";
  });

  render();
})();
</script>
</body>
</html>
```

