    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function priceToColor(changePct) {
      // red for negative, green for positive
      const t = clamp((changePct + 5) / 10, 0, 1); // -5%..+5%
      const r = Math.round(220 * (1 - t));
      const g = Math.round(180 * t + 20);
      const b = 70;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function render() {
      viewport.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
      statusEl.textContent = `Scale: ${state.scale.toFixed(2)} | Pan: (${Math.round(state.x)}, ${Math.round(state.y)})`;

      document.querySelectorAll(".cell").forEach(el => {
        const sym = el.dataset.sym;
        const price = state.prices[sym];
        const prev = el._prevPrice ?? price;
        const changePct = ((price - prev) / prev) * 100;
        el.style.background = priceToColor(changePct);
        el.querySelector(".price").textContent = `$${price.toFixed(2)}  ${changePct >= 0 ? "+" : ""}${changePct.toFixed(2)}%`;
        el._prevPrice = price;
      });
    }

    // ====== Zoom ======
    wrap.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = wrap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const oldScale = state.scale;
      const newScale = clamp(oldScale * zoomFactor, 0.5, 4);

      // Keep mouse position stable
      const worldX = (mouseX - state.x) / oldScale;
      const worldY = (mouseY - state.y) / oldScale;

      state.scale = newScale;
      state.x = mouseX - worldX * newScale;
      state.y = mouseY - worldY * newScale;

      render();
    }, { passive: false });

    // ====== Pan ======
    wrap.addEventListener("mousedown", (e) => {
      state.dragging = true;
      wrap.classList.add("dragging");
      state.startX = e.clientX;
      state.startY = e.clientY;
      state.dragX = state.x;
      state.dragY = state.y;
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.dragging) return;
      state.x = state.dragX + (e.clientX - state.startX);
      state.y = state.dragY + (e.clientY - state.startY);
      render();
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      wrap.classList.remove("dragging");
    });

    // ====== Tooltip ======
    viewport.addEventListener("mousemove", (e) => {
      const cell = e.target.closest(".cell");
      if (!cell) {
        tooltip.style.display = "none";
        return;
      }
