      "NKE","PYPL","ADBE","SNOW","SHOP","UBER","SONY","SAP","INTU","SBUX",
      "HD","LOW","TMO","ABBV","MRK","PFE","BAC","GS","CAT","RTN"
    ];

    const data = stocks.slice(0, rows * cols).map((symbol, i) => ({
      symbol,
      price: 50 + Math.random() * 450,
      change: (Math.random() - 0.5) * 8
    }));

    function colorFor(changePct) {
      const t = Math.max(-1, Math.min(1, changePct / 5));
      if (t < 0) {
        const k = -t;
        const r = Math.round(20 + 170 * k);
        const g = Math.round(30 + 60 * (1 - k));
        const b = Math.round(40 + 40 * (1 - k));
        return `rgb(${r},${g},${b})`;
      } else {
        const k = t;
        const r = Math.round(20 + 40 * (1 - k));
        const g = Math.round(80 + 110 * k);
        const b = Math.round(40 + 30 * (1 - k));
        return `rgb(${r},${g},${b})`;
      }
    }

