        const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
        rect.setAttribute("class", "cell");
        rect.setAttribute("x", x);
        rect.setAttribute("y", y);
        rect.setAttribute("width", cellW);
        rect.setAttribute("height", cellH);
        rect.setAttribute("fill", colorFor(d.change));
        g.appendChild(rect);

        const t1 = document.createElementNS("http://www.w3.org/2000/svg", "text");
        t1.setAttribute("class", "label");
        t1.setAttribute("x", x + cellW / 2);
        t1.setAttribute("y", y + cellH / 2 - 10);
        t1.textContent = d.symbol;
        g.appendChild(t1);

        const t2 = document.createElementNS("http://www.w3.org/2000/svg", "text");
        t2.setAttribute("class", "label small");
        t2.setAttribute("x", x + cellW / 2);
        t2.setAttribute("y", y + cellH / 2 + 12);
        t2.textContent = `${d.price.toFixed(2)}  ${d.change >= 0 ? "+" : ""}${d.change.toFixed(2)}%`;
        g.appendChild(t2);

        scene.appendChild(g);
      });
    }

    render();

    // Zoom/pan
    let view = { x: 0, y: 0, w: W, h: H };
    let dragging = false;
    let last = { x: 0, y: 0 };

    function applyView() {
      svg.setAttribute("viewBox", `${view.x} ${view.y} ${view.w} ${view.h}`);
    }

    function resetView() {
      view = { x: 0, y: 0, w: W, h: H };
      applyView();
    }

    resetBtn.onclick = resetView;

    wrap.addEventListener("pointerdown", (e) => {
      dragging = true;
      wrap.classList.add("dragging");
      last = { x: e.clientX, y: e.clientY };
      wrap.setPointerCapture(e.pointerId);
    });

    wrap.addEventListener("pointermove", (e) => {
      if (!dragging) return;
      const dx = e.clientX - last.x;
      const dy = e.clientY - last.y;
      last = { x: e.clientX, y: e.clientY };

      const sx = view.w / wrap.clientWidth;
      const sy = view.h / wrap.clientHeight;
      view.x -= dx * sx;
      view.y -= dy * sy;
      applyView();
    });

    wrap.addEventListener("pointerup", () => {
      dragging = false;
      wrap.classList.remove("dragging");
    });
    wrap.addEventListener("pointercancel", () => {
      dragging = false;
      wrap.classList.remove("dragging");
    });

    wrap.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY > 0 ? 1.1 : 0.9;
      const rect = svg.getBoundingClientRect();
      const mx = ((e.clientX - rect.left) / rect.width) * view.w + view.x;
      const my = ((e.clientY - rect.top) / rect.height) * view.h + view.y;

      const newW = view.w * zoomFactor;
      const newH = view.h * zoomFactor;

      view.x = mx - ((mx - view.x) / view.w) * newW;
      view.y = my - ((my - view.y) / view.h) * newH;
      view.w = newW;
      view.h = newH;
      applyView();
    }, { passive: false });

    // Real-time simulated updates
    setInterval(() => {
      data.forEach(d => {
        d.change += (Math.random() - 0.5) * 0.8;
        d.change = Math.max(-8, Math.min(8, d.change));

        d.price *= (1 + (d.change / 1000) + (Math.random() - 0.5) * 0.002);
        d.price = Math.max(1, d.price);
      });
      render();
    }, 1000);

    // Keep interactive state usable after rerender
    applyView();
  </script>
