    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');

    const state = {
      cols: 20,
      rows: 12,
      zoom: 1,
      panX: 0,
      panY: 0,
      isDragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startPanX: 0,
      startPanY: 0,
      cellSize: 60,
      data: [],
      hover: null
    };

    // Generate sample stocks
    const symbols = Array.from({ length: state.cols * state.rows }, (_, i) => {
      return 'STK' + String(i + 1).padStart(3, '0');
    });

    function randomInitialData() {
      state.data = symbols.map((symbol, i) => ({
        symbol,
        price: 100 + Math.random() * 50,
        change: (Math.random() - 0.5) * 10
      }));
    }

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(canvas.clientWidth * dpr);
      canvas.height = Math.floor(canvas.clientHeight * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      const t = clamp((change + 10) / 20, 0, 1); // map -10..10 to 0..1
      const r = Math.round(255 * (1 - t));
      const g = Math.round(255 * t);
      return `rgb(${r}, ${g}, 80)`;
    }

    function getGridMetrics() {
      const size = state.cellSize * state.zoom;
      const totalW = state.cols * size;
      const totalH = state.rows * size;
      return { size, totalW, totalH };
    }

    function screenToWorld(x, y) {
      const { size } = getGridMetrics();
      return {
        x: (x - state.panX) / size,
        y: (y - state.panY) / size
      };
    }

    function draw() {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      ctx.clearRect(0, 0, w, h);

      // background
      ctx.fillStyle = '#0f1115';
      ctx.fillRect(0, 0, w, h);

      const { size } = getGridMetrics();

      for (let row = 0; row < state.rows; row++) {
        for (let col = 0; col < state.cols; col++) {
          const i = row * state.cols + col;
          const item = state.data[i];
          if (!item) continue;

          const x = state.panX + col * size;
          const y = state.panY + row * size;

          // skip offscreen
          if (x + size < 0 || y + size < 0 || x > w || y > h) continue;

          ctx.fillStyle = colorForChange(item.change);
          ctx.fillRect(x, y, size - 2, size - 2);

          // highlight hover
          if (state.hover && state.hover.i === i) {
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2;
            ctx.strokeRect(x + 1, y + 1, size - 4, size - 4);
          }

          // label
          if (size >= 35) {
            ctx.fillStyle = '#111';
            ctx.font = `${Math.max(10, size * 0.18)}px system-ui, sans-serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(item.symbol, x + size / 2, y + size / 2 - 8);
            ctx.fillText(item.price.toFixed(2), x + size / 2, y + size / 2 + 8);
          }
        }
      }
    }

    function updateRandomPrices() {
      for (const item of state.data) {
        const delta = (Math.random() - 0.5) * 1.2;
        item.price = Math.max(1, item.price + delta);
        item.change = Math.max(-10, Math.min(10, item.change + delta * 0.8));
      }
      draw();
    }

    function hitTest(mouseX, mouseY) {
      const { size } = getGridMetrics();
      const world = screenToWorld(mouseX, mouseY);
      const col = Math.floor(world.x);
      const row = Math.floor(world.y);

      if (col < 0 || row < 0 || col >= state.cols || row >= state.rows) return null;

      const i = row * state.cols + col;
      const item = state.data[i];
      if (!item) return null;

      const x = state.panX + col * size;
      const y = state.panY + row * size;

      return { i, item, x, y, size };
    }

    canvas.addEventListener('mousedown', (e) => {
      state.isDragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (state.isDragging) {
        state.panX = state.startPanX + (e.clientX - state.dragStartX);
        state.panY = state.startPanY + (e.clientY - state.dragStartY);
        draw();
      }

      const hit = hitTest(e.clientX, e.clientY);
      state.hover = hit;

      if (hit) {
        tooltip.style.display = 'block';
        tooltip.style.left = e.clientX + 'px';
        tooltip.style.top = e.clientY + 'px';
        tooltip.innerHTML = `
          <b>${hit.item.symbol}</b><br>
          Price: $${hit.item.price.toFixed(2)}<br>
          Change: ${hit.item.change.toFixed(2)}
        `;
      } else {
        tooltip.style.display = 'none';
      }

      if (!state.isDragging) draw();
    });

    window.addEventListener('mouseup', () => {
      state.isDragging = false;
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const oldZoom = state.zoom;
      const newZoom = clamp(oldZoom * zoomFactor, 0.5, 4);

      const mouseX = e.clientX;
      const mouseY = e.clientY;

      // zoom around mouse position
      const worldBeforeX = (mouseX - state.panX) / (state.cellSize * oldZoom);
      const worldBeforeY = (mouseY - state.panY) / (state.cellSize * oldZoom);

      state.zoom = newZoom;

      state.panX = mouseX - worldBeforeX * state.cellSize * newZoom;
      state.panY = mouseY - worldBeforeY * state.cellSize * newZoom;

      draw();
    }, { passive: false });

    window.addEventListener('resize', resize);

    randomInitialData();
    resize();
    setInterval(updateRandomPrices, 1000);
  </script>
</body>
</html>
```

