            Price: $${s.price.toFixed(2)}<br>
            Change: ${s.change >= 0 ? "+" : ""}${s.change.toFixed(2)}
          `;
        });

        cell.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        grid.appendChild(cell);
      });
    }

    render();

    // Simulated real-time updates
    setInterval(() => {
      state = state.map(s => {
        const delta = (Math.random() - 0.5) * 4;
        const newPrice = Math.max(1, s.price + delta);
        const change = newPrice - 100; // simple reference point
        return { ...s, price: newPrice, change };
      });
      render();
      applyTransform();
    }, 1000);

    // Zoom/pan
    let scale = 1;
    let tx = 0;
    let ty = 0;
    let isPanning = false;
    let startX = 0;
    let startY = 0;

    function applyTransform() {
      content.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
    }
    applyTransform();

    viewport.addEventListener("mousedown", (e) => {
      isPanning = true;
      startX = e.clientX - tx;
      startY = e.clientY - ty;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isPanning) return;
      tx = e.clientX - startX;
      ty = e.clientY - startY;
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      isPanning = false;
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const oldScale = scale;
      scale = Math.min(3, Math.max(0.5, scale * zoomFactor));

      // Zoom around mouse position
      tx = mx - (mx - tx) * (scale / oldScale);
      ty = my - (my - ty) * (scale / oldScale);

      applyTransform();
    }, { passive: false });

    document.getElementById("zoomIn").onclick = () => {
      scale = Math.min(3, scale * 1.1);
      applyTransform();
    };

    document.getElementById("zoomOut").onclick = () => {
      scale = Math.max(0.5, scale / 1.1);
      applyTransform();
    };

    document.getElementById("reset").onclick = () => {
      scale = 1;
      tx = 0;
      ty = 0;
      applyTransform();
    };
  </script>
