    }

    #status {
      font-size: 12px;
      color: #9ca3af;
    }

    #chart {
      width: 100vw;
      height: calc(100vh - 48px);
      touch-action: none;
      cursor: grab;
    }

    #chart:active {
      cursor: grabbing;
    }

    .cell rect {
      stroke: #111827;
      stroke-width: 1;
      rx: 4;
      ry: 4;
    }

    .label {
      pointer-events: none;
      font-size: 11px;
      fill: white;
      text-anchor: middle;
      dominant-baseline: middle;
      user-select: none;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(17, 24, 39, 0.95);
      border: 1px solid #374151;
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 12px;
      color: #f9fafb;
      box-shadow: 0 8px 24px rgba(0,0,0,0.35);
      opacity: 0;
      transition: opacity 0.15s ease;
    }
  </style>
</head>
<body>
  <div id="topbar">
    <div><strong>Stock Heatmap</strong></div>
    <div id="status">Connecting...</div>
  </div>

  <div id="chart"></div>
  <div class="tooltip" id="tooltip"></div>

  <script>
    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","NFLX",
      "AMD","INTC","ORCL","CRM","UBER","SNAP","SHOP","SQ"
    ];

    // Minimal fake live data
    const data = symbols.map((s, i) => ({
      symbol: s,
      price: 100 + Math.random() * 300,
      change: (Math.random() - 0.5) * 6,
      x: (i % 4) * 1,
      y: Math.floor(i / 4) * 1
    }));

    const width = window.innerWidth;
    const height = window.innerHeight - 48;
    const cellW = 140;
    const cellH = 90;
    const padding = 14;

    const svg = d3.select("#chart")
      .append("svg")
      .attr("width", width)
      .attr("height", height);

    const g = svg.append("g");

    const tooltip = d3.select("#tooltip");
    const status = document.getElementById("status");

    const color = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#dc2626", "#1f2937", "#16a34a"]);

    const zoom = d3.zoom()
      .scaleExtent([0.6, 8])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
      });

    svg.call(zoom);

    function render() {
      const cells = g.selectAll(".cell")
        .data(data, d => d.symbol);

      const enter = cells.enter()
        .append("g")
        .attr("class", "cell")
        .style("cursor", "pointer")
        .on("mousemove", (event, d) => {
          tooltip
            .style("opacity", 1)
            .html(`
              <strong>${d.symbol}</strong><br/>
              Price: $${d.price.toFixed(2)}<br/>
              Change: ${d.change >= 0 ? "+" : ""}${d.change.toFixed(2)}%
            `)
            .style("left", (event.pageX + 12) + "px")
            .style("top", (event.pageY + 12) + "px");
        })
        .on("mouseleave", () => {
          tooltip.style("opacity", 0);
        });

      enter.append("rect");
      enter.append("text").attr("class", "label");

      const merged = enter.merge(cells);

      merged.attr("transform", d => {
        const x = padding + d.x * cellW;
        const y = padding + d.y * cellH;
        return `translate(${x},${y})`;
      });

      merged.select("rect")
        .attr("width", cellW - 10)
        .attr("height", cellH - 10)
        .attr("fill", d => color(d.change));

      merged.select("text")
        .attr("x", (cellW - 10) / 2)
        .attr("y", (cellH - 10) / 2)
        .text(d => `${d.symbol}\n$${d.price.toFixed(0)}`);

      cells.exit().remove();
    }

    function updatePrices() {
      data.forEach(d => {
        const delta = (Math.random() - 0.5) * 2;
        d.price = Math.max(1, d.price + delta);
        d.change = Math.max(-5, Math.min(5, d.change + (Math.random() - 0.5) * 0.6));
      });

      render();
      status.textContent = `Live updates at ${new Date().toLocaleTimeString()}`;
    }

    render();
    status.textContent = "Live (simulated)";

    // Simulate real-time updates every second
    setInterval(updatePrices, 1000);

    // Resize support
    window.addEventListener("resize", () => {
      location.reload();
    });
  </script>
</body>
</html>
