    const viewport = document.getElementById('viewport');
    const world = document.getElementById('world');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');

    const rows = 8;
    const cols = 10;
    const tileSize = 90;
    const gap = 6;

    let scale = 1;
    let panX = 40;
    let panY = 60;

    const stocks = [];
    let selectedTile = null;

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function pctColor(change) {
      // red for negative, green for positive
      const maxAbs = 5;
      const t = clamp((change + maxAbs) / (2 * maxAbs), 0, 1); // 0..1
      const r = Math.round(220 * (1 - t));
      const g = Math.round(220 * t);
      const b = 70;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function createTiles() {
      world.innerHTML = '';
      stocks.length = 0;

      const names = [
        'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','AMD','INTC','ORCL',
        'CRM','ADBE','IBM','QCOM','AVGO','NFLX','SHOP','UBER','SNOW','PLTR',
        'JPM','BAC','GS','MS','AXP','C','WFC','BLK','SCHW','BK',
        'XOM','CVX','COP','SLB','OXY','PXD','EOG','PSX','KMI','HES',
        'PFE','JNJ','MRK','LLY','ABBV','TMO','UNH','DHR','BMY','GILD',
        'KO','PEP','PG','WMT','COST','TGT','HD','LOW','NKE','SBUX',
        'DIS','CMCSA','VZ','T','TMUS','PARA','CHTR','EA','TTWO','RBLX',
        'BA','CAT','DE','GE','RTX','LMT','NOC','HON','UPS','FDX'
      ];

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const i = r * cols + c;
          const el = document.createElement('div');
          el.className = 'tile';
          el.style.left = `${c * (tileSize + gap)}px`;
          el.style.top = `${r * (tileSize + gap)}px`;
          el.style.width = `${tileSize}px`;
          el.style.height = `${tileSize}px`;

          const stock = {
            el,
            name: names[i] || `STK${i + 1}`,
            price: rand(20, 500),
            change: rand(-4, 4),
            volume: Math.floor(rand(1e5, 5e6))
          };

          el.addEventListener('mouseenter', (e) => showTooltip(e, stock));
          el.addEventListener('mousemove', (e) => showTooltip(e, stock));
          el.addEventListener('mouseleave', hideTooltip);
          el.addEventListener('click', () => {
            if (selectedTile) selectedTile.el.classList.remove('selected');
            selectedTile = stock;
            selectedTile.el.classList.add('selected');
          });

          stocks.push(stock);
          world.appendChild(el);
          updateTile(stock);
        }
      }

      updateWorldSize();
    }

    function updateTile(stock) {
      const ch = stock.change;
      stock.el.style.background = pctColor(ch);
      stock.el.innerHTML = `
        <div><strong>${stock.name}</strong></div>
        <div>$${stock.price.toFixed(2)}</div>
        <div>${ch >= 0 ? '+' : ''}${ch.toFixed(2)}%</div>
      `;
    }

    function updateWorldSize() {
      const w = cols * tileSize + (cols - 1) * gap;
      const h = rows * tileSize + (rows - 1) * gap;
      world.style.width = `${w}px`;
      world.style.height = `${h}px`;
    }

    function setTransform() {
      world.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    function showTooltip(e, stock) {
      tooltip.style.display = 'block';
      tooltip.style.left = `${e.clientX + 12}px`;
      tooltip.style.top = `${e.clientY + 12}px`;
      tooltip.innerHTML = `
        <div><strong>${stock.name}</strong></div>
        <div>Price: $${stock.price.toFixed(2)}</div>
        <div>Change: ${stock.change >= 0 ? '+' : ''}${stock.change.toFixed(2)}%</div>
        <div>Volume: ${stock.volume.toLocaleString()}</div>
      `;
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    // Real-time updates (simulated)
    function tick() {
      for (const stock of stocks) {
        stock.price *= (1 + rand(-0.003, 0.003));
        stock.change = clamp(stock.change + rand(-0.25, 0.25), -9.9, 9.9);
        stock.volume += Math.floor(rand(0, 5000));
        updateTile(stock);
      }
    }

    // Zoom around cursor
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = clamp(scale * zoomFactor, 0.4, 4);

      panX = mouseX - worldX * nextScale;
      panY = mouseY - worldY * nextScale;
      scale = nextScale;
      setTransform();
    }, { passive: false });

    // Pan with drag
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let startPanX = 0;
    let startPanY = 0;

    viewport.addEventListener('pointerdown', (e) => {
      if (e.target !== viewport && e.target !== world) return;
      dragging = true;
      viewport.setPointerCapture(e.pointerId);
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    viewport.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      setTransform();
    });

    viewport.addEventListener('pointerup', (e) => {
      dragging = false;
      try { viewport.releasePointerCapture(e.pointerId); } catch {}
    });

    viewport.addEventListener('pointercancel', () => {
      dragging = false;
    });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      panX = 40;
      panY = 60;
      setTransform();
    });

    createTiles();
    setTransform();
    tick();
    setInterval(tick, 1000);
  </script>
</body>
</html>
```

