        });

      tilesEnter.append("rect")
        .attr("class", "tile");

      tilesEnter.append("text")
        .attr("class", "label")
        .text(d => d.symbol);

      tiles.merge(tilesEnter)
        .attr("transform", d => {
          const x = gap + d.x * (tileW + gap);
          const y = gap + d.y * (tileH + gap);
          return `translate(${x},${y})`;
        })
        .select("rect")
        .attr("width", tileW)
        .attr("height", tileH)
        .attr("rx", 10)
        .attr("fill", d => color(d.change));

      tiles.merge(tilesEnter)
        .select("text")
        .attr("x", tileW / 2)
        .attr("y", tileH / 2)
        .style("font-size", `${Math.max(10, Math.min(tileW, tileH) * 0.14)}px`);

      tiles.exit().remove();
    }

    // Simulated real-time updates
    function tick() {
