      return { symbol: s, price, prev: price, changePct: 0 };
    });

    function colorForChange(pct) {
      const t = Math.max(-1, Math.min(1, pct / 5)); // clamp around +/-5%
      if (t >= 0) {
        const g = Math.round(60 + 120 * t);
        return `rgba(35, 197, 94, ${0.18 + 0.55 * t})`;
