            Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%
          `;
        });

        cell.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        grid.appendChild(cell);
      });

      stats.textContent = `${symbols.length} symbols`;
    }

    // Real-time mock updates
    setInterval(() => {
      data.forEach((d) => {
        d.prev = d.price;
        const delta = (Math.random() - 0.5) * d.price * 0.01; // +/-0.5%
        d.price = Math.max(1, d.price + delta);
        d.changePct = ((d.price - d.prev) / d.prev) * 100;
      });
      render();
    }, 1000);

    // Zoom/pan
    let scale = 1;
    let panX = 0;
    let panY = 0;
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let originX = 0;
    let originY = 0;

    function updateTransform() {
      world.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoom = Math.exp(-e.deltaY * 0.001);
      const nextScale = Math.min(3, Math.max(0.5, scale * zoom));

      panX = mouseX - (mouseX - panX) * (nextScale / scale);
      panY = mouseY - (mouseY - panY) * (nextScale / scale);
      scale = nextScale;
      updateTransform();
    }, { passive: false });

    viewport.addEventListener("mousedown", (e) => {
      dragging = true;
      viewport.classList.add("dragging");
      startX = e.clientX;
      startY = e.clientY;
      originX = panX;
      originY = panY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      panX = originX + (e.clientX - startX);
      panY = originY + (e.clientY - startY);
      updateTransform();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    render();
    updateTransform();
