      background: rgba(15, 23, 42, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 12px;
      transform: translate(12px, 12px);
      opacity: 0;
      z-index: 20;
      white-space: nowrap;
    }

    .muted { color: #94a3b8; }
    button {
      background: #1f2937;
      color: #e5e7eb;
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 6px;
      padding: 6px 10px;
      cursor: pointer;
    }
    button:hover { background: #273244; }
  </style>
</head>
<body>
  <div id="toolbar">
    <strong>Stock Heatmap</strong>
    <span class="muted">Wheel: zoom · Drag: pan · Hover: details</span>
    <button id="reset">Reset view</button>
    <span id="status" class="muted"></span>
  </div>

  <div id="wrap">
    <div id="scene"></div>
  </div>

  <div id="tooltip"></div>

  <script>
    const wrap = document.getElementById('wrap');
    const scene = document.getElementById('scene');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    // Minimal 'stocks' dataset
    const stocks = Array.from({ length: 120 }, (_, i) => ({
      symbol: `STK${String(i + 1).padStart(3, '0')}`,
      price: 50 + Math.random() * 150,
      change: (Math.random() - 0.5) * 8
    }));

    const cols = 12;
    const cellW = 110;
    const cellH = 70;
    const gap = 6;
    const margin = 12;
    const sceneW = cols * (cellW + gap) + margin * 2;
    const rows = Math.ceil(stocks.length / cols);
    const sceneH = rows * (cellH + gap) + margin * 2;

    scene.style.width = sceneW + 'px';
    scene.style.height = sceneH + 'px';

    function colorForChange(change) {
      // Red for negative, green for positive, neutral near zero
      const max = 8;
      const t = Math.max(-1, Math.min(1, change / max));
      if (t >= 0) {
        const g = Math.floor(80 + 150 * t);
        const r = Math.floor(28 + 50 * (1 - t));
        return `rgb(${r}, ${g}, 70)`;
      } else {
        const a = Math.abs(t);
        const r = Math.floor(90 + 150 * a);
        const g = Math.floor(50 + 40 * (1 - a));
        return `rgb(${r}, ${g}, 65)`;
      }
    }

    // Render cells
    const cellEls = [];
    stocks.forEach((s, i) => {
      const x = margin + (i % cols) * (cellW + gap);
      const y = margin + Math.floor(i / cols) * (cellH + gap);

      const el = document.createElement('div');
      el.className = 'cell';
      el.style.left = x + 'px';
      el.style.top = y + 'px';
      el.style.width = cellW + 'px';
      el.style.height = cellH + 'px';
      el.dataset.index = i;

      function updateCell() {
        el.style.background = colorForChange(s.change);
        el.textContent = s.symbol + '\n' + s.change.toFixed(2) + '%';
      }
      updateCell();
      s._updateCell = updateCell;

      el.addEventListener('mouseenter', (e) => {
        tooltip.style.opacity = '1';
        tooltip.textContent = `${s.symbol} | Price: $${s.price.toFixed(2)} | Change: ${s.change.toFixed(2)}%`;
      });

      el.addEventListener('mousemove', (e) => {
        tooltip.style.left = e.clientX + 'px';
        tooltip.style.top = e.clientY + 'px';
      });

      el.addEventListener('mouseleave', () => {
        tooltip.style.opacity = '0';
      });

      scene.appendChild(el);
      cellEls.push(el);
    });

    // View transform state
    let scale = 1;
    let panX = 20;
    let panY = 20;

    function applyTransform() {
      scene.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }
    applyTransform();

    // Zoom around mouse pointer
    wrap.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = wrap.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const worldX = (mx - panX) / scale;
      const worldY = (my - panY) / scale;

      const zoom = Math.exp(-e.deltaY * 0.001);
      const nextScale = Math.min(4, Math.max(0.4, scale * zoom));

      panX = mx - worldX * nextScale;
      panY = my - worldY * nextScale;
      scale = nextScale;

      applyTransform();
    }, { passive: false });

    // Pan with drag
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    wrap.addEventListener('pointerdown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      wrap.setPointerCapture(e.pointerId);
    });

    wrap.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      panX += e.clientX - lastX;
      panY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      applyTransform();
    });

    wrap.addEventListener('pointerup', () => {
      dragging = false;
    });

    wrap.addEventListener('pointercancel', () => {
      dragging = false;
    });

    document.getElementById('reset').addEventListener('click', () => {
      scale = 1;
      panX = 20;
      panY = 20;
      applyTransform();
    });

    // Simulate live updates
    function tick() {
      // Randomly update a handful of stocks
      for (let k = 0; k < 8; k++) {
        const s = stocks[(Math.random() * stocks.length) | 0];
        s.price = Math.max(1, s.price + (Math.random() - 0.5) * 3);
        s.change = Math.max(-8, Math.min(8, s.change + (Math.random() - 0.5) * 0.8));
        s._updateCell();
      }

      const avg = stocks.reduce((a, s) => a + s.change, 0) / stocks.length;
      statusEl.textContent = `Live avg change: ${avg.toFixed(2)}%`;

      requestAnimationFrame(() => setTimeout(tick, 300));
    }

    tick();

    // Keep tooltip from leaving viewport
    document.addEventListener('mousemove', (e) => {
      const pad = 20;
      const tw = tooltip.offsetWidth || 140;
      const th = tooltip.offsetHeight || 40;
      const x = Math.min(window.innerWidth - tw - pad, e.clientX);
      const y = Math.min(window.innerHeight - th - pad, e.clientY);
      tooltip.style.left = x + 'px';
      tooltip.style.top = y + 'px';
    });
  </script>
</body>
</html>
```

