  <script>
    const rows = 40;
    const cols = 80;
    const cellSize = 14;

    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');

    // Sample stock symbols
    const symbols = Array.from({ length: rows }, (_, i) =>
      `STK${String(i + 1).padStart(2, '0')}`
    );

    // State: prices and daily change %
    const data = Array.from({ length: rows }, (_, r) =>
      Array.from({ length: cols }, (_, c) => ({
        symbol: symbols[r],
        price: 50 + Math.random() * 150,
        change: (Math.random() - 0.5) * 10
      }))
    );

    // Transform state
    let scale = 1;
    let tx = 20;
    let ty = 20;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function changeToColor(change) {
      // red for negative, green for positive, gray near zero
      const t = clamp((change + 10) / 20, 0, 1);
      const r = Math.round(255 * (1 - t));
      const g = Math.round(255 * t);
      const b = 60;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function render() {
      heatmap.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;

      const grid = document.createElement('div');
      grid.className = 'grid';
      grid.style.gridTemplateColumns = `repeat(${cols}, ${cellSize}px)`;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const cell = document.createElement('div');
          cell.className = 'cell';
          const item = data[r][c];
          cell.style.background = changeToColor(item.change);
          cell.textContent = ''; // keep minimal; could show price/change here
          cell.dataset.row = r;
          cell.dataset.col = c;
          cell.title = `${item.symbol} | $${item.price.toFixed(2)} | ${item.change.toFixed(2)}%`;
          grid.appendChild(cell);
        }
      }

      heatmap.innerHTML = '';
      heatmap.appendChild(grid);
    }

    // Real-time updates (simulated)
    setInterval(() => {
      for (let i = 0; i < 20; i++) {
        const r = Math.floor(Math.random() * rows);
        const c = Math.floor(Math.random() * cols);
        const item = data[r][c];
        const delta = (Math.random() - 0.5) * 2.5;
        item.price = Math.max(1, item.price + delta);
        item.change = clamp(item.change + (Math.random() - 0.5) * 0.8, -10, 10);
      }
      render();
    }, 300);

    // Hover tooltip
    viewport.addEventListener('mousemove', (e) => {
      const target = e.target.closest('.cell');
      if (!target) {
        tooltip.style.display = 'none';
        return;
      }
      const r = +target.dataset.row;
      const c = +target.dataset.col;
      const item = data[r][c];

      tooltip.style.display = 'block';
      tooltip.style.left = e.clientX + 'px';
      tooltip.style.top = e.clientY + 'px';
      tooltip.innerHTML = `
        <div><strong>${item.symbol}</strong></div>
        <div>Price: $${item.price.toFixed(2)}</div>
        <div>Change: ${item.change.toFixed(2)}%</div>
      `;
    });

    viewport.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
    });

    // Pan via drag
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let startTx = 0;
    let startTy = 0;

    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      startX = e.clientX;
      startY = e.clientY;
      startTx = tx;
      startTy = ty;
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      tx = startTx + (e.clientX - startX);
      ty = startTy + (e.clientY - startY);
      heatmap.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
    });

    // Zoom via mouse wheel centered on cursor
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const cx = e.clientX - rect.left;
      const cy = e.clientY - rect.top;

      const worldX = (cx - tx) / scale;
      const worldY = (cy - ty) / scale;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = clamp(scale * zoomFactor, 0.4, 4);

      tx = cx - worldX * nextScale;
      ty = cy - worldY * nextScale;
      scale = nextScale;

      heatmap.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
    }, { passive: false });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      tx = 20;
      ty = 20;
      heatmap.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
    });

    render();
  </script>
</body>
