  <div id="topbar">
    <div><strong>Stock Heatmap</strong></div>
    <div id="hint">Wheel: zoom • Drag: pan</div>
  </div>
  <div id="viewport">
    <div id="map"></div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const map = document.getElementById('map');

    // Minimal sample stock universe
    const stocks = [
      { t: 'AAPL', p: 210 }, { t: 'MSFT', p: 430 }, { t: 'GOOGL', p: 175 },
      { t: 'AMZN', p: 190 }, { t: 'NVDA', p: 125 }, { t: 'META', p: 485 },
      { t: 'TSLA', p: 185 }, { t: 'NFLX', p: 640 }, { t: 'AMD', p: 165 },
      { t: 'INTC', p: 32 }, { t: 'ORCL', p: 128 }, { t: 'CRM', p: 280 },
      { t: 'UBER', p: 70 }, { t: 'SHOP', p: 65 }, { t: 'SNOW', p: 150 },
      { t: 'PLTR', p: 25 }, { t: 'SQ', p: 68 }, { t: 'PYPL', p: 61 }
    ].map(s => ({
      ...s,
      prev: s.p,
      chg: 0,
      el: null
    }));

    // Layout: simple grid
    const cols = 6;
    const tileW = 170;
    const tileH = 110;
    const gap = 8;

    function colorForChange(chg) {
      // chg as percentage
      const max = 5;
      const clamped = Math.max(-max, Math.min(max, chg));
      const intensity = Math.abs(clamped) / max;
      const base = clamped >= 0 ? [30, 160, 70] : [180, 50, 50];
      const bg = `rgba(${base[0]}, ${base[1]}, ${base[2]}, ${0.15 + 0.75 * intensity})`;
      const border = `rgba(255,255,255,${0.08 + 0.18 * intensity})`;
      return { bg, border };
    }

    function render() {
      map.innerHTML = '';
      stocks.forEach((s, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;
        const x = col * (tileW + gap);
        const y = row * (tileH + gap);

        const tile = document.createElement('div');
        tile.className = 'tile';
        tile.style.left = x + 'px';
        tile.style.top = y + 'px';
        tile.style.width = tileW + 'px';
        tile.style.height = tileH + 'px';

        const c = colorForChange(s.chg);
        tile.style.background = c.bg;
        tile.style.borderColor = c.border;

        tile.innerHTML = `
          <div class="ticker">${s.t}</div>
          <div class="price">$${s.p.toFixed(2)}</div>
          <div class="change">${s.chg >= 0 ? '+' : ''}${s.chg.toFixed(2)}%</div>
        `;

        map.appendChild(tile);
        s.el = tile;
      });

      const rows = Math.ceil(stocks.length / cols);
      map.style.width = (cols * tileW + (cols - 1) * gap) + 'px';
      map.style.height = (rows * tileH + (rows - 1) * gap) + 'px';
    }

    // View transform
    let scale = 1;
    let panX = 40;
    let panY = 30;

    function applyTransform() {
      map.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    // Zoom around mouse pointer
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.max(0.4, Math.min(4, scale * zoomFactor));

      // keep point under cursor stable
      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      panX = mouseX - worldX * newScale;
      panY = mouseY - worldY * newScale;
      scale = newScale;

      applyTransform();
    }, { passive: false });

    // Drag pan
    let dragging = false;
    let lastX = 0, lastY = 0;

    viewport.addEventListener('pointerdown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      panX += e.clientX - lastX;
      panY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      applyTransform();
    });

    viewport.addEventListener('pointerup', () => dragging = false);
    viewport.addEventListener('pointercancel', () => dragging = false);

    // Real-time simulated updates
    function tick() {
      stocks.forEach(s => {
        s.prev = s.p;
        const drift = (Math.random() - 0.5) * 2.5;
        s.p = Math.max(1, s.p + drift);
        s.chg = ((s.p - s.prev) / s.prev) * 100;

        if (s.el) {
          const c = colorForChange(s.chg);
          s.el.style.background = c.bg;
          s.el.style.borderColor = c.border;
          s.el.querySelector('.price').textContent = '$' + s.p.toFixed(2);
          s.el.querySelector('.change').textContent =
            `${s.chg >= 0 ? '+' : ''}${s.chg.toFixed(2)}%`;
        }
      });
    }

    // Init
    render();
    applyTransform();
    setInterval(tick, 1000);
  </script>
