### Minimal working example

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Stock Heatmap</title>
  <style>
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #0f1115;
      color: #e5e7eb;
      overflow: hidden;
    }

    .toolbar {
      position: fixed;
      top: 10px;
      left: 10px;
      z-index: 10;
      display: flex;
      gap: 8px;
      background: rgba(20, 24, 32, 0.9);
      padding: 10px;
      border-radius: 10px;
      box-shadow: 0 4px 16px rgba(0,0,0,0.3);
    }

    .toolbar button {
      background: #1f2937;
      color: white;
      border: 1px solid #374151;
      padding: 6px 10px;
      border-radius: 6px;
      cursor: pointer;
    }

    .toolbar button:hover {
      background: #374151;
    }

    #viewport {
      position: absolute;
      inset: 0;
      overflow: hidden;
      cursor: grab;
      user-select: none;
    }

    #viewport.dragging {
      cursor: grabbing;
    }

    #canvas {
      position: absolute;
      left: 0;
      top: 0;
      transform-origin: 0 0;
      will-change: transform;
    }

    .tile {
      position: absolute;
      width: 120px;
      height: 80px;
      border: 1px solid rgba(255,255,255,0.08);
      box-sizing: border-box;
      border-radius: 8px;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      font-size: 14px;
      transition: background-color 0.15s linear, transform 0.1s ease;
      color: #fff;
      overflow: hidden;
    }

    .tile .symbol {
      font-weight: bold;
      font-size: 16px;
    }

    .tile .price {
      font-size: 13px;
      margin-top: 4px;
    }

    .tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(17, 24, 39, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      color: #fff;
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 13px;
      display: none;
      z-index: 20;
      white-space: nowrap;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="zoomIn">Zoom In</button>
    <button id="zoomOut">Zoom Out</button>
    <button id="reset">Reset</button>
  </div>

  <div id="viewport">
    <div id="canvas"></div>
  </div>

  <div id="tooltip" class="tooltip"></div>

  <script>
    const viewport = document.getElementById('viewport');
    const canvas = document.getElementById('canvas');
    const tooltip = document.getElementById('tooltip');

    const stocks = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','BRK.A',
      'JPM','V','UNH','XOM','LLY','AVGO','MA','COST','AMD','NFLX'
    ];

    const cols = 4;
    const tileW = 120;
    const tileH = 80;
    const gap = 12;

    let zoom = 1;
    let panX = 30;
    let panY = 80;

    const state = stocks.map((symbol, i) => {
      const base = 100 + Math.random() * 900;
      return {
        symbol,
        price: base,
        prev: base,
        changePct: 0,
        x: (i % cols) * (tileW + gap),
        y: Math.floor(i / cols) * (tileH + gap)
      };
    });

    function updateCanvasTransform() {
      canvas.style.transform = `translate(${panX}px, ${panY}px) scale(${zoom})`;
    }

    function pctToColor(pct) {
      // red for negative, green for positive
      const clamped = Math.max(-5, Math.min(5, pct));
      const t = Math.abs(clamped) / 5;
      if (clamped >= 0) {
        const g = Math.floor(60 + 180 * t);
        return `rgb(20, ${g}, 60)`;
      } else {
        const r = Math.floor(60 + 180 * t);
        return `rgb(${r}, 40, 40)`;
      }
    }

    function render() {
      canvas.innerHTML = '';
      state.forEach(stock => {
        const tile = document.createElement('div');
        tile.className = 'tile';
        tile.style.left = `${stock.x}px`;
        tile.style.top = `${stock.y}px`;
        tile.style.background = pctToColor(stock.changePct);

        tile.innerHTML = `
          <div class="symbol">${stock.symbol}</div>
          <div class="price">$${stock.price.toFixed(2)}</div>
          <div>${stock.changePct >= 0 ? '+' : ''}${stock.changePct.toFixed(2)}%</div>
        `;

        tile.addEventListener('mousemove', (e) => {
          tooltip.style.display = 'block';
          tooltip.style.left = `${e.clientX + 12}px`;
          tooltip.style.top = `${e.clientY + 12}px`;
          tooltip.innerHTML = `
            <strong>${stock.symbol}</strong><br/>
            Price: $${stock.price.toFixed(2)}<br/>
            Change: ${stock.changePct >= 0 ? '+' : ''}${stock.changePct.toFixed(2)}%
          `;
        });

        tile.addEventListener('mouseleave', () => {
          tooltip.style.display = 'none';
        });

        canvas.appendChild(tile);
      });

      canvas.style.width = `${cols * tileW + (cols - 1) * gap}px`;
      canvas.style.height = `${Math.ceil(stocks.length / cols) * tileH + Math.ceil(stocks.length / cols - 1) * gap}px`;

      updateCanvasTransform();
    }

    function randomUpdate() {
      state.forEach(stock => {
        stock.prev = stock.price;
        const change = (Math.random() - 0.5) * stock.price * 0.01; // +/-0.5%
        stock.price = Math.max(1, stock.price + change);
        stock.changePct = ((stock.price - stock.prev) / stock.prev) * 100;
      });
      render();
    }

    // Zoom controls
    document.getElementById('zoomIn').onclick = () => {
      zoom = Math.min(4, zoom * 1.2);
      updateCanvasTransform();
    };
    document.getElementById('zoomOut').onclick = () => {
      zoom = Math.max(0.5, zoom / 1.2);
      updateCanvasTransform();
    };
    document.getElementById('reset').onclick = () => {
      zoom = 1;
      panX = 30;
      panY = 80;
      updateCanvasTransform();
    };

    // Mouse wheel zoom
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.1 : 0.9;
      zoom = Math.max(0.5, Math.min(4, zoom * factor));
      updateCanvasTransform();
    }, { passive: false });

    // Pan
    let dragging = false;
    let startX = 0;
    let startY = 0;

    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      startX = e.clientX - panX;
      startY = e.clientY - panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      panX = e.clientX - startX;
      panY = e.clientY - startY;
      updateCanvasTransform();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    // Initial render
    render();

    // Simulated real-time updates every 1s
    setInterval(randomUpdate, 1000);
  </script>
</body>
</html>
```

