## `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors({ origin: "*" }));
app.use(express.json());

const io = new Server(server, {
  cors: { origin: "*" }
});

// In-memory store
let boardState = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["t1", "t2"] },
    { id: "doing", title: "In Progress", taskIds: ["t3"] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    t1: { id: "t1", title: "Design app layout", description: "Create wireframes", assignee: "Ava" },
    t2: { id: "t2", title: "Implement auth", description: "Login and signup flow", assignee: "Noah" },
    t3: { id: "t3", title: "Set up websocket sync", description: "Realtime board updates", assignee: "Mia" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board/task", (req, res) => {
  const { columnId, task } = req.body;

  if (!columnId || !task?.id) {
    return res.status(400).json({ error: "columnId and task.id are required" });
  }

  boardState.tasks[task.id] = task;
  const col = boardState.columns.find(c => c.id === columnId);
  if (!col) return res.status(404).json({ error: "Column not found" });

  col.taskIds.push(task.id);

  io.emit("board:update", boardState);
  res.json({ ok: true });
});

app.put("/api/board/move", (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  const sourceCol = boardState.columns.find(c => c.id === sourceColumnId);
  const destCol = boardState.columns.find(c => c.id === destinationColumnId);

  if (!sourceCol || !destCol) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceCol.taskIds.splice(sourceIndex, 1);
  destCol.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("board:update", boardState);
  res.json({ ok: true });
});

app.put("/api/board/task/:id", (req, res) => {
  const { id } = req.params;
  if (!boardState.tasks[id]) return res.status(404).json({ error: "Task not found" });

  boardState.tasks[id] = { ...boardState.tasks[id], ...req.body };
  io.emit("board:update", boardState);
  res.json(boardState.tasks[id]);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("board:move", (payload) => {
    const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = payload;

    const sourceCol = boardState.columns.find(c => c.id === sourceColumnId);
    const destCol = boardState.columns.find(c => c.id === destinationColumnId);

    if (!sourceCol || !destCol) return;

    sourceCol.taskIds.splice(sourceIndex, 1);
    destCol.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", boardState);
  });

  socket.on("task:update", (payload) => {
    const { id, ...updates } = payload;
    if (!boardState.tasks[id]) return;

    boardState.tasks[id] = { ...boardState.tasks[id], ...updates };
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
```

