import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import Column from "./components/Column";

const socket = io("http://localhost:4000");

export default function App() {
  const [board, setBoard] = useState(null);

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:update");
    };
  }, []);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    board.columns.forEach((col) => {
      result[col.id] = col.taskIds.map((id) => board.tasks[id]);
    });
    return result;
  }, [board]);

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (!active || !over || !board) return;

    const fromColumnId = active.data.current?.columnId;
    const toColumnId = over.data.current?.columnId;

    if (!fromColumnId || !toColumnId) return;

    const sourceColumn = board.columns.find((c) => c.id === fromColumnId);
    const destColumn = board.columns.find((c) => c.id === toColumnId);

    if (!sourceColumn || !destColumn) return;

    const taskId = active.id;
    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
    let destinationIndex = destColumn.taskIds.indexOf(over.id);

    if (destinationIndex === -1) {
      destinationIndex = destColumn.taskIds.length;
    }

    socket.emit("board:move", {
      sourceColumnId: fromColumnId,
      destinationColumnId: toColumnId,
      sourceIndex,
      destinationIndex,
      taskId
    });
  };

  if (!board) return <div className="app-loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Board</h1>
        <span className="status">Live collaboration enabled</span>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={tasksByColumn[column.id]}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}
```

