    "task-2": { id: "task-2", title: "Set up auth", description: "Implement login flow", assignee: "Bob" },
    "task-3": { id: "task-3", title: "Create API", description: "Build REST endpoints", assignee: "Cara" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, title, description, assignee } = req.body;

  if (!columnId || !title) {
    return res.status(400).json({ error: "columnId and title are required" });
  }

  const id = `task-${Date.now()}`;
  const newTask = {
    id,
    title,
    description: description || "",
    assignee: assignee || ""
  };

  board.tasks[id] = newTask;
  const column = board.columns.find(c => c.id === columnId);
  if (!column) return res.status(404).json({ error: "Column not found" });

  column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(newTask);
});

app.post("/api/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

  const updatedIndex =
    typeof destinationIndex === "number" ? destinationIndex : destinationColumn.taskIds.length;

  destinationColumn.taskIds.splice(updatedIndex, 0, taskId);

  io.emit("board:update", board);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", ({ columnId, title, description, assignee }) => {
    const id = `task-${Date.now()}`;
    const newTask = {
      id,
      title,
      description: description || "",
      assignee: assignee || ""
    };

    board.tasks[id] = newTask;
    const column = board.columns.find(c => c.id === columnId);
    if (!column) return;

    column.taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);

    const updatedIndex =
      typeof destinationIndex === "number" ? destinationIndex : destinationColumn.taskIds.length;

    destinationColumn.taskIds.splice(updatedIndex, 0, taskId);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
