import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:4000");

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskColumn, setNewTaskColumn] = useState("todo");
  const [form, setForm] = useState({
    title: "",
    description: "",
    assignee: ""
  });

  useEffect(() => {
    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const handleDragStart = (e, taskId, sourceColumnId) => {
    e.dataTransfer.setData("taskId", taskId);
    e.dataTransfer.setData("sourceColumnId", sourceColumnId);
  };

  const handleDrop = (e, destinationColumnId, destinationIndex) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData("taskId");
    const sourceColumnId = e.dataTransfer.getData("sourceColumnId");

    socket.emit("task:move", {
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    });
  };

  const allowDrop = (e) => e.preventDefault();

  const handleCreateTask = (e) => {
    e.preventDefault();
    socket.emit("task:create", {
      columnId: newTaskColumn,
      ...form
    });
    setForm({ title: "", description: "", assignee: "" });
  };

  const columns = useMemo(() => board?.columns || [], [board]);

  if (!board) {
    return <div className="loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag and drop tasks. Changes sync in real time.</p>
      </header>

      <section className="creator">
        <h2>Create Task</h2>
        <form onSubmit={handleCreateTask} className="create-form">
          <input
            type="text"
            placeholder="Task title"
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            required
          />
          <input
            type="text"
            placeholder="Description"
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          <input
            type="text"
            placeholder="Assignee"
            value={form.assignee}
            onChange={(e) => setForm({ ...form, assignee: e.target.value })}
          />
          <select value={newTaskColumn} onChange={(e) => setNewTaskColumn(e.target.value)}>
            {columns.map((col) => (
              <option key={col.id} value={col.id}>
                {col.title}
              </option>
            ))}
          </select>
          <button type="submit">Add Task</button>
        </form>
      </section>

      <main className="board">
        {columns.map((column) => (
          <div
            key={column.id}
            className="column"
            onDragOver={allowDrop}
            onDrop={(e) => handleDrop(e, column.id, column.taskIds.length)}
          >
            <h2>{column.title}</h2>
            <div className="task-list">
              {column.taskIds.map((taskId, index) => {
                const task = board.tasks[taskId];
                if (!task) return null;

                return (
                  <div
                    key={task.id}
                    className="task"
                    draggable
                    onDragStart={(e) => handleDragStart(e, task.id, column.id)}
                    onDragOver={allowDrop}
                    onDrop={(e) => handleDrop(e, column.id, index)}
                  >
                    <h3>{task.title}</h3>
                    {task.description && <p>{task.description}</p>}
                    {task.assignee && <span className="assignee">Assigned to {task.assignee}</span>}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </main>
    </div>
  );
}
