import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory data store
let boards = [
  {
    id: "board-1",
    title: "Website Redesign",
    columns: [
      {
        id: "todo",
        title: "To Do",
        taskIds: ["task-1", "task-2"]
      },
      {
        id: "inprogress",
        title: "In Progress",
        taskIds: ["task-3"]
      },
      {
        id: "done",
        title: "Done",
        taskIds: []
      }
    ],
    tasks: {
      "task-1": { id: "task-1", title: "Create wireframes", description: "Homepage and dashboard wireframes" },
      "task-2": { id: "task-2", title: "Set up color palette", description: "Choose accessible brand colors" },
      "task-3": { id: "task-3", title: "Build navbar", description: "Responsive top navigation" }
    }
  }
];

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.post("/api/boards", (req, res) => {
  const { title } = req.body;
  const newBoard = {
    id: `board-${Date.now()}`,
    title: title || "Untitled Board",
    columns: [
      { id: "todo", title: "To Do", taskIds: [] },
      { id: "inprogress", title: "In Progress", taskIds: [] },
      { id: "done", title: "Done", taskIds: [] }
    ],
    tasks: {}
  };

  boards.push(newBoard);
  io.emit("boards:update", boards);
  res.status(201).json(newBoard);
});

app.post("/api/boards/:boardId/tasks", (req, res) => {
  const { boardId } = req.params;
  const { title, description, columnId = "todo" } = req.body;

  const board = boards.find((b) => b.id === boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const taskId = `task-${Date.now()}`;
  const task = {
    id: taskId,
    title: title || "New Task",
    description: description || ""
  };

  board.tasks[taskId] = task;
  const column = board.columns.find((c) => c.id === columnId);
  if (column) column.taskIds.push(taskId);

  io.emit("boards:update", boards);
  res.status(201).json(task);
});

// Move task endpoint (optional for non-socket clients)
app.post("/api/boards/:boardId/move-task", (req, res) => {
  const { boardId } = req.params;
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const board = boards.find((b) => b.id === boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid columns" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

  const insertIndex = Math.max(0, Math.min(destinationIndex ?? destinationColumn.taskIds.length, destinationColumn.taskIds.length));
  destinationColumn.taskIds.splice(insertIndex, 0, taskId);

  io.emit("boards:update", boards);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("boards:update", boards);

  socket.on("task:move", (payload) => {
    const { boardId, taskId, sourceColumnId, destinationColumnId, destinationIndex } = payload;

    const board = boards.find((b) => b.id === boardId);
    if (!board) return;

    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    const insertIndex = Math.max(0, Math.min(destinationIndex ?? destinationColumn.taskIds.length, destinationColumn.taskIds.length));
    destinationColumn.taskIds.splice(insertIndex, 0, taskId);

    io.emit("boards:update", boards);
  });

  socket.on("task:create", (payload) => {
    const { boardId, title, description, columnId = "todo" } = payload;

    const board = boards.find((b) => b.id === boardId);
    if (!board) return;

    const taskId = `task-${Date.now()}`;
    const task = {
      id: taskId,
      title: title || "New Task",
      description: description || ""
    };

    board.tasks[taskId] = task;
    const column = board.columns.find((c) => c.id === columnId);
    if (column) column.taskIds.push(taskId);

    io.emit("boards:update", boards);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
