## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay,
  useDroppable,
  useDraggable
} from "@dnd-kit/core";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:3001");

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task.id,
    data: { task }
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...listeners} {...attributes}>
      <h4>{task.title}</h4>
      {task.description && <p>{task.description}</p>}
    </div>
  );
}

function Column({ column, tasks, children }) {
  const { setNodeRef, isOver } = useDroppable({
    id: column.id
  });

  return (
    <div ref={setNodeRef} className={`column ${isOver ? "column-over" : ""}`}>
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{column.taskIds.length}</span>
      </div>
      <div className="column-body">{children}</div>
    </div>
  );
}

export default function App() {
  const [boards, setBoards] = useState([]);
  const [selectedBoardId, setSelectedBoardId] = useState(null);
  const [activeTask, setActiveTask] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    socket.on("boards:update", (updatedBoards) => {
      setBoards(updatedBoards);
      if (!selectedBoardId && updatedBoards.length > 0) {
        setSelectedBoardId(updatedBoards[0].id);
      }
    });

    return () => {
      socket.off("boards:update");
    };
  }, [selectedBoardId]);

  const board = useMemo(
    () => boards.find((b) => b.id === selectedBoardId),
    [boards, selectedBoardId]
  );

  const tasksById = board?.tasks || {};

  const handleDragStart = (event) => {
    const task = tasksById[event.active.id];
    setActiveTask(task || null);
  };

  const handleDragEnd = (event) => {
    setActiveTask(null);

    const { active, over } = event;
    if (!over || !board) return;

    const taskId = active.id;
    const destinationColumnId = over.id;

    const sourceColumn = board.columns.find((column) =>
      column.taskIds.includes(taskId)
    );

    if (!sourceColumn) return;

    const destinationColumn = board.columns.find((column) => column.id === destinationColumnId);
    if (!destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
    const destinationIndex = destinationColumn.taskIds.length;

    socket.emit("task:move", {
      boardId: board.id,
      taskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId: destinationColumn.id,
      destinationIndex: sourceColumn.id === destinationColumn.id ? sourceIndex : destinationIndex
    });
  };

  const createTask = () => {
    if (!newTaskTitle.trim() || !board) return;

    socket.emit("task:create", {
      boardId: board.id,
      title: newTaskTitle.trim(),
      description: ""
    });

    setNewTaskTitle("");
  };

  const createBoard = async () => {
    const title = prompt("Board title?");
    if (!title) return;

    await fetch("http://localhost:3001/api/boards", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title })
    });
  };

  if (!board) {
    return (
      <div className="app">
        <header className="topbar">
          <h1>Project Manager</h1>
          <button onClick={createBoard}>New Board</button>
        </header>
        <main className="empty-state">Loading boards...</main>
      </div>
    );
  }

  return (
    <div className="app">
      <header className="topbar">
        <div>
          <h1>Project Manager</h1>
          <p>Real-time task board collaboration</p>
        </div>
        <div className="board-actions">
          <select
            value={selectedBoardId}
            onChange={(e) => setSelectedBoardId(e.target.value)}
          >
            {boards.map((b) => (
              <option key={b.id} value={b.id}>
                {b.title}
              </option>
            ))}
          </select>
          <button onClick={createBoard}>New Board</button>
        </div>
      </header>

      <section className="task-creator">
        <input
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          placeholder="Add a task..."
          onKeyDown={(e) => e.key === "Enter" && createTask()}
        />
        <button onClick={createTask}>Add Task</button>
      </section>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <main className="board">
          {board.columns.map((column) => (
            <Column key={column.id} column={column}>
              {column.taskIds.map((taskId) => (
                <TaskCard key={taskId} task={tasksById[taskId]} />
              ))}
            </Column>
          ))}
        </main>

        <DragOverlay>
          {activeTask ? (
            <div className="task-card task-card-overlay">
              <h4>{activeTask.title}</h4>
              {activeTask.description && <p>{activeTask.description}</p>}
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

