## 3) Backend: `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

app.use(cors());
app.use(express.json());

app.use(express.static("../client"));

let board = {
  todo: [
    { id: "1", title: "Design project layout", assignee: "Alex" },
    { id: "2", title: "Set up auth flow", assignee: "Priya" }
  ],
  doing: [
    { id: "3", title: "Build drag-and-drop UI", assignee: "Sam" }
  ],
  done: [
    { id: "4", title: "Create wireframes", assignee: "Mia" }
  ]
};

function emitBoardUpdate() {
  io.emit("board:update", board);
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:add", (task) => {
    const newTask = {
      id: crypto.randomUUID(),
      title: task.title || "Untitled Task",
      assignee: task.assignee || ""
    };
    board.todo.unshift(newTask);
    emitBoardUpdate();
  });

  socket.on("task:update", ({ taskId, fromColumn, toColumn, index }) => {
    if (!board[fromColumn] || !board[toColumn]) return;

    const fromList = board[fromColumn];
    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    board[toColumn].splice(index, 0, task);
    emitBoardUpdate();
  });

  socket.on("task:move", ({ taskId, fromColumn, toColumn }) => {
    if (!board[fromColumn] || !board[toColumn]) return;

    const fromList = board[fromColumn];
    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    board[toColumn].unshift(task);
    emitBoardUpdate();
  });

  socket.on("task:delete", ({ taskId, column }) => {
    if (!board[column]) return;
    board[column] = board[column].filter((t) => t.id !== taskId);
    emitBoardUpdate();
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

app.get("/api/board", (req, res) => {
  res.json(board);
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

> Note: `crypto.randomUUID()` works in modern Node versions. If needed, replace it with another ID generator.

