## 6) Frontend logic: `client/app.js`

```js
const socket = io("http://localhost:3000");

const taskForm = document.getElementById("task-form");
const taskTitleInput = document.getElementById("task-title");
const taskAssigneeInput = document.getElementById("task-assignee");

const columns = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

let currentBoard = {};
let draggedTask = null;

function renderBoard(board) {
  currentBoard = board;

  Object.keys(columns).forEach((column) => {
    const list = columns[column];
    list.innerHTML = "";

    board[column].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;
      taskEl.dataset.column = column;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <div class="task-title">${escapeHtml(task.title)}</div>
        <div class="task-meta">
          <span>${escapeHtml(task.assignee || "Unassigned")}</span>
          <span>#${task.id.slice(0, 6)}</span>
        </div>
        <div class="task-actions">
          <button data-delete="${task.id}">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: column
        };
      });

      taskEl.addEventListener("dragend", () => {
        draggedTask = null;
      });

      taskEl.querySelector("[data-delete]").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, column });
      });

      list.appendChild(taskEl);
    });
  });
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

Object.entries(columns).forEach(([columnName, listEl]) => {
  listEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    listEl.classList.add("drag-over");
  });

  listEl.addEventListener("dragleave", () => {
    listEl.classList.remove("drag-over");
  });

  listEl.addEventListener("drop", (e) => {
    e.preventDefault();
    listEl.classList.remove("drag-over");

    if (!draggedTask) return;

    const toColumn = columnName;
    const fromColumn = draggedTask.fromColumn;

    if (fromColumn === toColumn) {
      // Optional: reorder within same column
      socket.emit("task:move", {
        taskId: draggedTask.taskId,
        fromColumn,
        toColumn
      });
    } else {
      socket.emit("task:move", {
        taskId: draggedTask.taskId,
        fromColumn,
        toColumn
      });
    }
  });
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = taskTitleInput.value.trim();
  const assignee = taskAssigneeInput.value.trim();

  if (!title) return;

  socket.emit("task:add", { title, assignee });

  taskTitleInput.value = "";
  taskAssigneeInput.value = "";
});

socket.on("board:update", (board) => {
  renderBoard(board);
});
```

