## `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for demo purposes
let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Set up project", description: "Initialize app structure" },
        { id: "t2", title: "Design UI", description: "Build kanban layout" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Drag and drop", description: "Implement board interactions" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body;
  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current state on connect
  socket.emit("board:update", boardState);

  socket.on("board:update", (newState) => {
    boardState = newState;
    socket.broadcast.emit("board:update", boardState);
  });

  socket.on("task:add", ({ columnId, task }) => {
    const col = boardState.columns.find((c) => c.id === columnId);
    if (!col) return;

    col.tasks.push(task);
    io.emit("board:update", boardState);
  });

  socket.on("task:move", ({ sourceColumnId, destinationColumnId, sourceIndex, destinationIndex }) => {
    const sourceCol = boardState.columns.find((c) => c.id === sourceColumnId);
    const destCol = boardState.columns.find((c) => c.id === destinationColumnId);
    if (!sourceCol || !destCol) return;

    const [movedTask] = sourceCol.tasks.splice(sourceIndex, 1);
    if (!movedTask) return;

    destCol.tasks.splice(destinationIndex, 0, movedTask);
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

