const taskForm = document.getElementById("taskForm");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");
const taskColumn = document.getElementById("taskColumn");
const cancelTaskBtn = document.getElementById("cancelTaskBtn");

let boardState = null;

function uuid() {
  return crypto.randomUUID();
}

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  // Update select options
  taskColumn.innerHTML = boardState.columns
    .map((column) => `<option value="${column.id}">${column.title}</option>`)
    .join("");

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <div class="column-header">
        <h2>${column.title}</h2>
      </div>
      <div class="task-list" data-column-id="${column.id}"></div>
    `;

    const taskListEl = columnEl.querySelector(".task-list");

    column.tasks.forEach((task, index) => {
      const card = document.createElement("article");
      card.className = "task-card";
      card.draggable = true;
      card.dataset.taskId = task.id;
      card.dataset.columnId = column.id;
      card.dataset.index = index;

      card.innerHTML = `
        <h3>${task.title}</h3>
        <p>${task.description || ""}</p>
      `;

      card.addEventListener("dragstart", onDragStart);
      card.addEventListener("dragend", onDragEnd);

      taskListEl.appendChild(card);
    });

    taskListEl.addEventListener("dragover", onDragOver);
    taskListEl.addEventListener("dragleave", onDragLeave);
    taskListEl.addEventListener("drop", onDrop);

    boardEl.appendChild(columnEl);
  });
}

let draggedTaskMeta = null;

function onDragStart(e) {
  const taskCard = e.currentTarget;
  draggedTaskMeta = {
    taskId: taskCard.dataset.taskId,
    sourceColumnId: taskCard.dataset.columnId,
    sourceIndex: Number(taskCard.dataset.index)
  };

  e.dataTransfer.effectAllowed = "move";
  e.dataTransfer.setData("text/plain", JSON.stringify(draggedTaskMeta));
  setTimeout(() => taskCard.style.opacity = "0.4", 0);
}

function onDragEnd(e) {
  e.currentTarget.style.opacity = "1";
  draggedTaskMeta = null;
  document.querySelectorAll(".task-list").forEach((list) => list.classList.remove("drop-target"));
}

function onDragOver(e) {
  e.preventDefault();
  e.currentTarget.classList.add("drop-target");
  e.dataTransfer.dropEffect = "move";
}

function onDragLeave(e) {
  e.currentTarget.classList.remove("drop-target");
}

function onDrop(e) {
  e.preventDefault();
  e.currentTarget.classList.remove("drop-target");

  const destinationColumnId = e.currentTarget.dataset.columnId;
  const destinationList = e.currentTarget;

  const payload = draggedTaskMeta || JSON.parse(e.dataTransfer.getData("text/plain"));
  if (!payload) return;

  const destinationTasks = [...destinationList.querySelectorAll(".task-card")];
  const destinationIndex = destinationTasks.length;

  socket.emit("task:move", {
    sourceColumnId: payload.sourceColumnId,
    destinationColumnId,
    sourceIndex: payload.sourceIndex,
    destinationIndex
  });
}

addTaskBtn.addEventListener("click", () => {
  taskDialog.showModal();
});

cancelTaskBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const newTask = {
    id: uuid(),
    title: taskTitle.value.trim(),
    description: taskDescription.value.trim()
  };

  socket.emit("task:add", {
    columnId: taskColumn.value,
    task: newTask
  });

  taskForm.reset();
  taskDialog.close();
});

socket.on("board:update", (newBoardState) => {
  boardState = newBoardState;
  renderBoard();
});

socket.on("connect", () => {
  console.log("Connected to server:", socket.id);
});
