## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Design app layout", description: "Create wireframes and UI structure" },
        { id: "task-2", title: "Set up backend", description: "Initialize Node.js server and API" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Implement drag and drop", description: "Allow moving tasks between columns" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", title: "Create project repo", description: "Initialize repository and folder structure" }
      ]
    }
  ]
};

function broadcast() {
  const message = JSON.stringify({
    type: "state",
    payload: state
  });

  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on("connection", ws => {
  ws.send(JSON.stringify({ type: "state", payload: state }));

  ws.on("message", raw => {
    try {
      const message = JSON.parse(raw.toString());

      if (message.type === "move-task") {
        const { taskId, fromBoardId, toBoardId, toIndex } = message.payload;

        let task = null;
        const fromBoard = state.boards.find(b => b.id === fromBoardId);
        const toBoard = state.boards.find(b => b.id === toBoardId);

        if (!fromBoard || !toBoard) return;

        const taskIndex = fromBoard.tasks.findIndex(t => t.id === taskId);
        if (taskIndex === -1) return;

        task = fromBoard.tasks.splice(taskIndex, 1)[0];

        const insertIndex = Math.max(0, Math.min(toIndex, toBoard.tasks.length));
        toBoard.tasks.splice(insertIndex, 0, task);

        broadcast();
      }

      if (message.type === "create-task") {
        const { boardId, title, description } = message.payload;
        const board = state.boards.find(b => b.id === boardId);
        if (!board) return;

        board.tasks.unshift({
          id: `task-${Date.now()}`,
          title,
          description
        });

        broadcast();
      }
    } catch (err) {
      console.error("Invalid websocket message:", err);
    }
  });
});

app.get("/api/state", (req, res) => {
  res.json(state);
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

