## 5) `public/app.js`

```js
const boardsEl = document.getElementById("boards");
const boardTemplate = document.getElementById("boardTemplate");
const taskTemplate = document.getElementById("taskTemplate");
const connectionStatus = document.getElementById("connectionStatus");
const taskForm = document.getElementById("taskForm");
const boardSelect = document.getElementById("boardSelect");

let appState = null;
let draggedTask = null;

const ws = new WebSocket(`ws://${window.location.host}`);

ws.addEventListener("open", () => {
  connectionStatus.textContent = "Connected";
  connectionStatus.style.background = "#059669";
});

ws.addEventListener("close", () => {
  connectionStatus.textContent = "Disconnected";
  connectionStatus.style.background = "#b91c1c";
});

ws.addEventListener("message", event => {
  const message = JSON.parse(event.data);

  if (message.type === "state") {
    appState = message.payload;
    render();
  }
});

function render() {
  if (!appState) return;

  boardsEl.innerHTML = "";
  boardSelect.innerHTML = "";

  appState.boards.forEach(board => {
    const option = document.createElement("option");
    option.value = board.id;
    option.textContent = board.title;
    boardSelect.appendChild(option);

    const boardNode = boardTemplate.content.cloneNode(true);
    const boardEl = boardNode.querySelector(".board");
    const titleEl = boardNode.querySelector("h3");
    const taskListEl = boardNode.querySelector(".task-list");

    titleEl.textContent = board.title;
    taskListEl.dataset.boardId = board.id;

    taskListEl.addEventListener("dragover", e => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", e => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTask) return;

      const toBoardId = taskListEl.dataset.boardId;
      const toIndex = Array.from(taskListEl.children).indexOf(e.target.closest(".task"));
      const normalizedIndex = toIndex === -1 ? taskListEl.children.length : toIndex;

      ws.send(JSON.stringify({
        type: "move-task",
        payload: {
          taskId: draggedTask.taskId,
          fromBoardId: draggedTask.boardId,
          toBoardId,
          toIndex: normalizedIndex
        }
      }));

      draggedTask = null;
    });

    board.tasks.forEach(task => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      const titleEl = taskNode.querySelector(".task-title");
      const descEl = taskNode.querySelector(".task-description");

      titleEl.textContent = task.title;
      descEl.textContent = task.description || "";

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.boardId = board.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          boardId: board.id
        };
      });

      taskEl.addEventListener("dragend", () => {
        draggedTask = null;
      });

      taskListEl.appendChild(taskNode);
    });

    boardEl.appendChild(taskNodeFromFragment(boardNode));
    boardsEl.appendChild(boardEl);
  });
}

function taskNodeFromFragment(fragment) {
  const wrapper = document.createElement("div");
  wrapper.appendChild(fragment);
  return wrapper.firstElementChild;
}

taskForm.addEventListener("submit", e => {
  e.preventDefault();

  const boardId = boardSelect.value;
  const title = document.getElementById("taskTitle").value.trim();
  const description = document.getElementById("taskDescription").value.trim();

  if (!title) return;

  ws.send(JSON.stringify({
    type: "create-task",
    payload: {
      boardId,
      title,
      description
    }
  }));

  taskForm.reset();
});

fetch("/api/state")
  .then(res => res.json())
  .then(state => {
    appState = state;
    render();
  });
```

