## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Design wireframes", description: "Create initial UI mockups" },
        { id: "t2", title: "Set up project", description: "Initialize repo and tooling" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Build drag-and-drop", description: "Implement task movement" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "t4", title: "Requirements gathering", description: "Talk to stakeholders" }
      ]
    }
  ]
};

function findTask(taskId) {
  for (const board of state.boards) {
    const idx = board.tasks.findIndex((t) => t.id === taskId);
    if (idx !== -1) {
      return { board, idx, task: board.tasks[idx] };
    }
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("state:init", state);

  socket.on("task:move", ({ taskId, toBoardId, toIndex }) => {
    const found = findTask(taskId);
    if (!found) return;

    const fromBoard = found.board;
    const task = found.task;

    fromBoard.tasks.splice(found.idx, 1);

    const toBoard = state.boards.find((b) => b.id === toBoardId);
    if (!toBoard) return;

    const insertIndex = Math.max(0, Math.min(toIndex, toBoard.tasks.length));
    toBoard.tasks.splice(insertIndex, 0, task);

    io.emit("state:update", state);
  });

  socket.on("task:create", ({ boardId, title, description }) => {
    const board = state.boards.find((b) => b.id === boardId);
    if (!board) return;

    const task = {
      id: `t_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
      title,
      description
    };

    board.tasks.unshift(task);
    io.emit("state:update", state);
  });

  socket.on("task:delete", ({ taskId }) => {
    const found = findTask(taskId);
    if (!found) return;

    found.board.tasks.splice(found.idx, 1);
    io.emit("state:update", state);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

