## 6) `public/app.js`

```js
const socket = io();

const boardsEl = document.getElementById("boards");
const taskForm = document.getElementById("taskForm");
const boardSelect = document.getElementById("boardSelect");
const titleInput = document.getElementById("titleInput");
const descInput = document.getElementById("descInput");
const taskTemplate = document.getElementById("taskTemplate");

let appState = null;
let draggedTaskId = null;

socket.on("state:init", (state) => {
  appState = state;
  render();
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const boardId = boardSelect.value;
  const title = titleInput.value.trim();
  const description = descInput.value.trim();

  if (!title) return;

  socket.emit("task:create", { boardId, title, description });
  titleInput.value = "";
  descInput.value = "";
});

function render() {
  if (!appState) return;

  boardSelect.innerHTML = "";
  boardsEl.innerHTML = "";

  appState.boards.forEach((board) => {
    const option = document.createElement("option");
    option.value = board.id;
    option.textContent = board.title;
    boardSelect.appendChild(option);

    const boardEl = document.createElement("section");
    boardEl.className = "board";
    boardEl.innerHTML = `<h2>${board.title}</h2>`;

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.boardId = board.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      const taskId = draggedTaskId;
      if (!taskId) return;

      const toBoardId = board.id;
      const toIndex = board.tasks.length;

      socket.emit("task:move", { taskId, toBoardId, toIndex });
      draggedTaskId = null;
    });

    board.tasks.forEach((task, index) => {
      const taskEl = createTaskElement(task, board.id, index);
      taskList.appendChild(taskEl);
    });

    boardEl.appendChild(taskList);
    boardsEl.appendChild(boardEl);
  });
}

function createTaskElement(task, boardId, index) {
  const node = taskTemplate.content.cloneNode(true);
  const taskEl = node.querySelector(".task");
  const titleEl = node.querySelector(".task-title");
  const descEl = node.querySelector(".task-desc");
  const deleteBtn = node.querySelector(".delete-btn");

  titleEl.textContent = task.title;
  descEl.textContent = task.description || "";

  taskEl.dataset.taskId = task.id;
  taskEl.draggable = true;

  taskEl.addEventListener("dragstart", () => {
    draggedTaskId = task.id;
    taskEl.classList.add("dragging");
  });

  taskEl.addEventListener("dragend", () => {
    draggedTaskId = null;
    taskEl.classList.remove("dragging");
  });

  taskEl.addEventListener("dragover", (e) => e.preventDefault());

  taskEl.addEventListener("drop", (e) => {
    e.preventDefault();
    e.stopPropagation();

    const taskId = draggedTaskId;
    if (!taskId || taskId === task.id) return;

    socket.emit("task:move", {
      taskId,
      toBoardId: boardId,
      toIndex: index
    });

    draggedTaskId = null;
  });

  deleteBtn.addEventListener("click", () => {
    socket.emit("task:delete", { taskId: task.id });
  });

  return taskEl;
}
```

