### `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { store, Task, TaskStatus } from "./store.js";

const app = express();
app.use(cors({ origin: true }));
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: true, methods: ["GET", "POST", "PUT", "DELETE"] }
});

app.get("/api/tasks", (_req, res) => {
  res.json(store.tasks);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, status, assignee } = req.body as Partial<Task>;
  if (!title || !status) {
    return res.status(400).json({ error: "title and status are required" });
  }

  const task: Task = {
    id: crypto.randomUUID(),
    title,
    description,
    status: status as TaskStatus,
    assignee,
    updatedAt: new Date().toISOString()
  };

  store.tasks.push(task);
  io.emit("tasks:updated", store.tasks);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const index = store.tasks.findIndex((t) => t.id === id);
  if (index === -1) return res.status(404).json({ error: "Task not found" });

  const existing = store.tasks[index];
  const updated: Task = {
    ...existing,
    ...req.body,
    updatedAt: new Date().toISOString()
  };

  store.tasks[index] = updated;
  io.emit("tasks:updated", store.tasks);
  res.json(updated);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const before = store.tasks.length;
  store.tasks = store.tasks.filter((t) => t.id !== id);

  if (store.tasks.length === before) {
    return res.status(404).json({ error: "Task not found" });
  }

  io.emit("tasks:updated", store.tasks);
  res.status(204).send();
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("tasks:updated", store.tasks);

  socket.on("task:move", (payload: { id: string; status: TaskStatus }) => {
    const task = store.tasks.find((t) => t.id === payload.id);
    if (!task) return;

    task.status = payload.status;
    task.updatedAt = new Date().toISOString();
    io.emit("tasks:updated", store.tasks);
  });

  socket.on("task:create", (payload: Partial<Task>) => {
    if (!payload.title || !payload.status) return;

    const task: Task = {
      id: crypto.randomUUID(),
      title: payload.title,
      description: payload.description,
      status: payload.status,
      assignee: payload.assignee,
      updatedAt: new Date().toISOString()
    };

    store.tasks.push(task);
    io.emit("tasks:updated", store.tasks);
  });

  socket.on("task:update", (payload: { id: string; patch: Partial<Task> }) => {
    const task = store.tasks.find((t) => t.id === payload.id);
    if (!task) return;

    Object.assign(task, payload.patch, { updatedAt: new Date().toISOString() });
    io.emit("tasks:updated", store.tasks);
  });

  socket.on("task:delete", (payload: { id: string }) => {
    const before = store.tasks.length;
    store.tasks = store.tasks.filter((t) => t.id !== payload.id);
    if (store.tasks.length !== before) {
      io.emit("tasks:updated", store.tasks);
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

