### `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import { io } from "socket.io-client";

type TaskStatus = "todo" | "doing" | "done";

type Task = {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  assignee?: string;
  updatedAt: string;
};

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

const columns: { id: TaskStatus; title: string }[] = [
  { id: "todo", title: "To Do" },
  { id: "doing", title: "Doing" },
  { id: "done", title: "Done" },
];

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [activeTask, setActiveTask] = useState<Task | null>(null);
  const [newTitle, setNewTitle] = useState("");
  const [newDescription, setNewDescription] = useState("");

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } })
  );

  useEffect(() => {
    fetch(`${API_URL}/api/tasks`)
      .then((r) => r.json())
      .then(setTasks);

    socket.on("tasks:updated", setTasks);

    return () => {
      socket.off("tasks:updated");
    };
  }, []);

  const grouped = useMemo(() => {
    return {
      todo: tasks.filter((t) => t.status === "todo"),
      doing: tasks.filter((t) => t.status === "doing"),
      done: tasks.filter((t) => t.status === "done"),
    };
  }, [tasks]);

  function handleDragStart(event: any) {
    const task = tasks.find((t) => t.id === event.active.id) || null;
    setActiveTask(task);
  }

  function handleDragEnd(event: DragEndEvent) {
    setActiveTask(null);

    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const targetStatus = over.id as TaskStatus;

    const task = tasks.find((t) => t.id === taskId);
    if (!task || task.status === targetStatus) return;

    socket.emit("task:move", { id: taskId, status: targetStatus });
  }

  function createTask(e: React.FormEvent) {
    e.preventDefault();
    if (!newTitle.trim()) return;

    socket.emit("task:create", {
      title: newTitle.trim(),
      description: newDescription.trim(),
      status: "todo",
    });

    setNewTitle("");
    setNewDescription("");
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <form className="task-form" onSubmit={createTask}>
        <input
          value={newTitle}
          onChange={(e) => setNewTitle(e.target.value)}
          placeholder="Task title"
        />
        <input
          value={newDescription}
          onChange={(e) => setNewDescription(e.target.value)}
          placeholder="Description"
        />
        <button type="submit">Add Task</button>
      </form>

      <DndContext sensors={sensors} onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((col) => (
            <Column
              key={col.id}
              id={col.id}
              title={col.title}
              tasks={grouped[col.id]}
            />
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} dragging /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}

function Column({
  id,
  title,
  tasks,
}: {
  id: TaskStatus;
  title: string;
  tasks: Task[];
}) {
  const { setNodeRef } = useDroppableColumn(id);

  return (
    <section className="column" ref={setNodeRef}>
      <h2>
        {title} <span>{tasks.length}</span>
      </h2>
      <div className="column-body">
        {tasks.map((task) => (
          <TaskCard key={task.id} task={task} />
        ))}
      </div>
    </section>
  );
}

import { useDroppable } from "@dnd-kit/core";
import { useDraggable } from "@dnd-kit/core";
import { CSS } from "@dnd-kit/utilities";

function useDroppableColumn(id: TaskStatus) {
  return useDroppable({ id });
}

function TaskCard({ task, dragging = false }: { task: Task; dragging?: boolean }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task.id,
  });

  const style = {
    transform: CSS.Translate.toString(transform),
    opacity: isDragging || dragging ? 0.4 : 1,
  };

  return (
    <article
      ref={setNodeRef}
      className={`task-card ${dragging ? "dragging" : ""}`}
      style={style}
      {...listeners}
      {...attributes}
    >
      <strong>{task.title}</strong>
      {task.description ? <p>{task.description}</p> : null}
      <small>Updated {new Date(task.updatedAt).toLocaleTimeString()}</small>
    </article>
  );
}
```

