## 3) `server.js`  
A tiny Express server plus WebSocket broadcast for collaboration.

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Set up project", description: "Initialize app structure", assignee: "Alex" },
      { id: "t2", title: "Design UI", description: "Create board layout", assignee: "Sam" }
    ],
    doing: [
      { id: "t3", title: "Build drag-and-drop", description: "Implement task movement", assignee: "Taylor" }
    ],
    done: []
  }
};

function broadcast(payload) {
  const message = JSON.stringify(payload);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "init", state }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw);

      if (msg.type === "updateState" && msg.state) {
        state = msg.state;
        broadcast({ type: "state", state });
      }
    } catch (err) {
      console.error("Bad message:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

