## 6) `public/app.js`

```js
const ws = new WebSocket(`ws://${location.host}`);
const connectionStatus = document.getElementById("connectionStatus");
const board = document.getElementById("board");
const taskTemplate = document.getElementById("taskTemplate");

const addTaskBtn = document.getElementById("addTaskBtn");
const taskTitle = document.getElementById("taskTitle");
const taskDesc = document.getElementById("taskDesc");
const taskAssignee = document.getElementById("taskAssignee");

let state = {
  columns: {
    todo: [],
    doing: [],
    done: []
  }
};

let draggedTask = null;

function uuid() {
  return "xxxxxxx-xxxx".replace(/[x]/g, () =>
    Math.floor(Math.random() * 16).toString(16)
  );
}

function sendState() {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify({ type: "updateState", state }));
  }
}

function render() {
  ["todo", "doing", "done"].forEach((columnName) => {
    const container = document.getElementById(columnName);
    container.innerHTML = "";

    state.columns[columnName].forEach((task) => {
      const node = taskTemplate.content.cloneNode(true);
      const article = node.querySelector(".task");
      const title = node.querySelector(".task-title");
      const desc = node.querySelector(".task-desc");
      const assignee = node.querySelector(".task-assignee");
      const deleteBtn = node.querySelector(".delete-btn");

      article.dataset.id = task.id;
      article.draggable = true;

      title.textContent = task.title;
      desc.textContent = task.description || "";
      assignee.textContent = task.assignee ? `Assigned to: ${task.assignee}` : "Unassigned";

      article.addEventListener("dragstart", () => {
        draggedTask = { ...task, from: columnName };
        article.classList.add("dragging");
      });

      article.addEventListener("dragend", () => {
        article.classList.remove("dragging");
        draggedTask = null;
      });

      deleteBtn.addEventListener("click", () => {
        state.columns[columnName] = state.columns[columnName].filter((t) => t.id !== task.id);
        render();
        sendState();
      });

      container.appendChild(node);
    });
  });
}

function moveTask(taskId, fromColumn, toColumn) {
  const taskIndex = state.columns[fromColumn].findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return;

  const [task] = state.columns[fromColumn].splice(taskIndex, 1);
  state.columns[toColumn].push(task);
  render();
  sendState();
}

function addTask() {
  const title = taskTitle.value.trim();
  if (!title) return;

  const newTask = {
    id: uuid(),
    title,
    description: taskDesc.value.trim(),
    assignee: taskAssignee.value.trim()
  };

  state.columns.todo.push(newTask);
  taskTitle.value = "";
  taskDesc.value = "";
  taskAssignee.value = "";
  render();
  sendState();
}

addTaskBtn.addEventListener("click", addTask);

document.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && document.activeElement.tagName === "INPUT") {
    addTask();
  }
});

document.querySelectorAll(".column, .task-list").forEach((el) => {
  el.addEventListener("dragover", (e) => {
    e.preventDefault();
    el.classList.add("drag-over");
  });

  el.addEventListener("dragleave", () => {
    el.classList.remove("drag-over");
  });

  el.addEventListener("drop", (e) => {
    e.preventDefault();
    el.classList.remove("drag-over");

    if (!draggedTask) return;

    const column = el.closest(".column")?.dataset.column || el.id;
    if (!column || column === draggedTask.from) return;

    moveTask(draggedTask.id, draggedTask.from, column);
  });
});

ws.addEventListener("open", () => {
  connectionStatus.textContent = "Connected";
  connectionStatus.style.color = "#34d399";
});

ws.addEventListener("close", () => {
  connectionStatus.textContent = "Disconnected";
  connectionStatus.style.color = "#f87171";
});

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);

  if (msg.type === "init") {
    state = msg.state;
    render();
  }

  if (msg.type === "state") {
    state = msg.state;
    render();
  }
});

render();
```

