const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory data store
let boardState = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", content: "Design the project homepage" },
    "task-2": { id: "task-2", content: "Set up auth flow" },
    "task-3": { id: "task-3", content: "Implement drag-and-drop board" }
  },
  columnOrder: ["todo", "inprogress", "done"]
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body;
  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current state to new client
  socket.emit("board:update", boardState);

  socket.on("board:update", (newState) => {
    boardState = newState;
    socket.broadcast.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
