### `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { socket } from "./socket";

const initialBoard = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {},
  columnOrder: ["todo", "inprogress", "done"]
};

export default function App() {
  const [board, setBoard] = useState(initialBoard);
  const [newTaskText, setNewTaskText] = useState("");

  useEffect(() => {
    socket.on("board:update", (data) => {
      setBoard(data);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const emitBoardUpdate = (updatedBoard) => {
    setBoard(updatedBoard);
    socket.emit("board:update", updatedBoard);
  };

  const addTask = () => {
    const text = newTaskText.trim();
    if (!text) return;

    const id = `task-${Date.now()}`;
    const updatedBoard = structuredClone(board);
    updatedBoard.tasks[id] = { id, content: text };
    updatedBoard.columns.todo.taskIds.unshift(id);

    emitBoardUpdate(updatedBoard);
    setNewTaskText("");
  };

  const onDragStart = (e, taskId, sourceColumnId) => {
    e.dataTransfer.setData(
      "application/json",
      JSON.stringify({ taskId, sourceColumnId })
    );
  };

  const onDragOver = (e) => {
    e.preventDefault();
  };

  const onDrop = (e, destinationColumnId) => {
    e.preventDefault();

    const payload = JSON.parse(e.dataTransfer.getData("application/json"));
    const { taskId, sourceColumnId } = payload;

    if (!taskId || !sourceColumnId) return;
    if (sourceColumnId === destinationColumnId) return;

    const updatedBoard = structuredClone(board);

    const sourceColumn = updatedBoard.columns[sourceColumnId];
    const destinationColumn = updatedBoard.columns[destinationColumnId];

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);
    destinationColumn.taskIds.unshift(taskId);

    emitBoardUpdate(updatedBoard);
  };

  const columnList = useMemo(
    () => board.columnOrder.map((colId) => board.columns[colId]),
    [board]
  );

  return (
    <div className="app">
      <header className="header">
        <h1>Project Board</h1>
        <div className="new-task">
          <input
            value={newTaskText}
            onChange={(e) => setNewTaskText(e.target.value)}
            placeholder="Add a new task..."
          />
          <button onClick={addTask}>Add Task</button>
        </div>
      </header>

      <main className="board">
        {columnList.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={onDragOver}
            onDrop={(e) => onDrop(e, column.id)}
          >
            <div className="column-header">
              <h2>{column.title}</h2>
              <span>{column.taskIds.length}</span>
            </div>

            <div className="task-list">
              {column.taskIds.map((taskId) => {
                const task = board.tasks[taskId];
                return (
                  <div
                    key={taskId}
                    className="task-card"
                    draggable
                    onDragStart={(e) => onDragStart(e, taskId, column.id)}
                  >
                    {task.content}
                  </div>
                );
              })}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

