### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { BoardState, initialState, Task } from "./state";
import { randomUUID } from "crypto";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let board: BoardState = structuredClone(initialState);

app.get("/api/board", (_req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, assignee, columnId } = req.body as {
    title: string;
    description?: string;
    assignee?: string;
    columnId: string;
  };

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const id = randomUUID();
  const now = Date.now();

  const task: Task = {
    id,
    title,
    description,
    assignee,
    createdAt: now,
    updatedAt: now
  };

  board.tasks[id] = task;
  board.columns[columnId]?.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:create", (payload: {
    title: string;
    description?: string;
    assignee?: string;
    columnId: string;
  }) => {
    const { title, description, assignee, columnId } = payload;
    if (!title || !columnId || !board.columns[columnId]) return;

    const id = randomUUID();
    const now = Date.now();

    const task: Task = {
      id,
      title,
      description,
      assignee,
      createdAt: now,
      updatedAt: now
    };

    board.tasks[id] = task;
    board.columns[columnId].taskIds.push(id);

    io.emit("board:update", board);
  });

  socket.on("task:update", (payload: {
    id: string;
    title?: string;
    description?: string;
    assignee?: string;
  }) => {
    const task = board.tasks[payload.id];
    if (!task) return;

    board.tasks[payload.id] = {
      ...task,
      ...payload,
      updatedAt: Date.now()
    };

    io.emit("board:update", board);
  });

  socket.on("task:delete", (payload: { id: string }) => {
    const task = board.tasks[payload.id];
    if (!task) return;

    for (const column of Object.values(board.columns)) {
      column.taskIds = column.taskIds.filter((id) => id !== payload.id);
    }

    delete board.tasks[payload.id];
    io.emit("board:update", board);
  });

  socket.on("task:move", (payload: {
    taskId: string;
    fromColumnId: string;
    toColumnId: string;
    toIndex: number;
  }) => {
    const { taskId, fromColumnId, toColumnId, toIndex } = payload;
    const fromColumn = board.columns[fromColumnId];
    const toColumn = board.columns[toColumnId];
    if (!fromColumn || !toColumn) return;

    fromColumn.taskIds = fromColumn.taskIds.filter((id) => id !== taskId);

    const safeIndex = Math.max(0, Math.min(toIndex, toColumn.taskIds.length));
    toColumn.taskIds.splice(safeIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    // Optional: presence tracking here
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});
