### `client/src/App.tsx`
```tsx
import React, { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners,
  DragStartEvent
} from "@dnd-kit/core";

type Task = {
  id: string;
  title: string;
  description?: string;
  assignee?: string;
  createdAt: number;
  updatedAt: number;
};

type BoardColumn = {
  id: string;
  title: string;
  taskIds: string[];
};

type BoardState = {
  tasks: Record<string, Task>;
  columns: Record<string, BoardColumn>;
  columnOrder: string[];
};

const API_URL = "http://localhost:3001";

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [board, setBoard] = useState<BoardState | null>(null);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [assignee, setAssignee] = useState("");
  const [targetColumn, setTargetColumn] = useState("column-todo");

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    const s = io(API_URL);
    setSocket(s);

    s.on("board:update", (next: BoardState) => {
      setBoard(structuredClone(next));
    });

    return () => {
      s.disconnect();
    };
  }, []);

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then((r) => r.json())
      .then((data) => setBoard(data));
  }, []);

  const activeTask = useMemo(() => {
    if (!board || !activeTaskId) return null;
    return board.tasks[activeTaskId] ?? null;
  }, [board, activeTaskId]);

  const getColumnIdForTask = (taskId: string) => {
    if (!board) return null;
    return Object.values(board.columns).find((c) => c.taskIds.includes(taskId))?.id ?? null;
  };

  const handleDragStart = (event: DragStartEvent) => {
    setActiveTaskId(String(event.active.id));
  };

  const handleDragEnd = (event: DragEndEvent) => {
    setActiveTaskId(null);
    if (!socket || !board) return;

    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);

    const fromColumnId = getColumnIdForTask(taskId);
    if (!fromColumnId) return;

    let toColumnId = String(over.id);
    let toIndex = 0;

    // If dropped over another task, place relative to that task in its column
    if (board.tasks[toColumnId]) {
      const columnId = getColumnIdForTask(toColumnId);
      if (!columnId) return;
      toColumnId = columnId;
      toIndex = board.columns[toColumnId].taskIds.indexOf(toColumnId);
      const overTaskIndex = board.columns[toColumnId].taskIds.indexOf(String(over.id));
      toIndex = overTaskIndex >= 0 ? overTaskIndex : board.columns[toColumnId].taskIds.length;
    } else {
      // Dropped over a column
      toIndex = board.columns[toColumnId]?.taskIds.length ?? 0;
    }

    if (!board.columns[toColumnId]) return;

    socket.emit("task:move", {
      taskId,
      fromColumnId,
      toColumnId,
      toIndex
    });
  };

  const createTask = () => {
    if (!socket || !title.trim()) return;

    socket.emit("task:create", {
      title: title.trim(),
      description: description.trim() || undefined,
      assignee: assignee.trim() || undefined,
      columnId: targetColumn
    });

    setTitle("");
    setDescription("");
    setAssignee("");
  };

  const updateTask = (task: Task, patch: Partial<Task>) => {
    if (!socket) return;
    socket.emit("task:update", { id: task.id, ...patch });
  };

  const deleteTask = (taskId: string) => {
    if (!socket) return;
    socket.emit("task:delete", { id: taskId });
  };

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <div>
          <h1>Project Manager</h1>
          <p>Drag tasks, edit cards, and sync in real time.</p>
        </div>

        <div className="new-task">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Task title"
          />
          <input
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Description"
          />
          <input
            value={assignee}
            onChange={(e) => setAssignee(e.target.value)}
            placeholder="Assignee"
          />
          <select value={targetColumn} onChange={(e) => setTargetColumn(e.target.value)}>
            {board.columnOrder.map((id) => (
              <option key={id} value={id}>
                {board.columns[id].title}
              </option>
            ))}
          </select>
          <button onClick={createTask}>Add Task</button>
        </div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <main className="board">
          {board.columnOrder.map((columnId) => {
            const column = board.columns[columnId];
            return (
              <Column
                key={column.id}
                column={column}
                tasks={column.taskIds.map((id) => board.tasks[id]).filter(Boolean)}
                onUpdateTask={updateTask}
                onDeleteTask={deleteTask}
              />
            );
          })}
        </main>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} overlay /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}

function Column({
  column,
  tasks,
  onUpdateTask,
  onDeleteTask
}: {
  column: BoardColumn;
  tasks: Task[];
  onUpdateTask: (task: Task, patch: Partial<Task>) => void;
  onDeleteTask: (taskId: string) => void;
}) {
  return (
    <div className="column" id={column.id}>
      <div className="column-header">
        <h2>{column.title}</h2>
        <span>{tasks.length}</span>
      </div>

      <div className="column-body" id={column.id}>
        {tasks.map((task) => (
          <TaskCard
            key={task.id}
            task={task}
            onUpdateTask={onUpdateTask}
            onDeleteTask={onDeleteTask}
          />
        ))}
      </div>
    </div>
  );
}

import { useDraggable } from "@dnd-kit/core";

function TaskCard({
  task,
  overlay = false,
  onUpdateTask,
  onDeleteTask
}: {
  task: Task;
  overlay?: boolean;
  onUpdateTask?: (task: Task, patch: Partial<Task>) => void;
  onDeleteTask?: (taskId: string) => void;
}) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task.id
  });

  const style: React.CSSProperties = overlay
    ? { transform: "rotate(3deg)", opacity: 0.95 }
    : {
        transform: transform
          ? `translate3d(${transform.x}px, ${transform.y}px, 0)`
          : undefined,
        opacity: isDragging ? 0.5 : 1
      };

  return (
    <div ref={setNodeRef} className="task" style={style} {...listeners} {...attributes}>
      <div className="task-top">
        <input
          className="task-title"
          value={task.title}
          onChange={(e) => onUpdateTask?.(task, { title: e.target.value })}
        />
        <button className="icon-btn" onClick={() => onDeleteTask?.(task.id)}>
          ×
        </button>
      </div>

      <textarea
        className="task-desc"
        value={task.description ?? ""}
        onChange={(e) => onUpdateTask?.(task, { description: e.target.value })}
        placeholder="Description"
      />

      <input
        className="task-assignee"
        value={task.assignee ?? ""}
        onChange={(e) => onUpdateTask?.(task, { assignee: e.target.value })}
        placeholder="Assignee"
      />
    </div>
  );
}
```

