```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory board state
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Set up project", description: "Initialize repo and app structure" },
    "task-2": { id: "task-2", title: "Design UI", description: "Create board layout" },
    "task-3": { id: "task-3", title: "Implement sockets", description: "Enable live sync" }
  },
  columnOrder: ["todo", "doing", "done"]
};

// REST endpoint for initial load
app.get("/api/board", (req, res) => {
  res.json(board);
});

// REST endpoint to create a new task
app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;
  const id = `task-${Date.now()}`;

  const newTask = { id, title, description };
  board.tasks[id] = newTask;
  board.columns[columnId].taskIds.unshift(id);

  io.emit("board:update", board);
  res.status(201).json(newTask);
});

// REST endpoint to update board state directly
app.put("/api/board", (req, res) => {
  board = req.body;
  io.emit("board:update", board);
  res.json({ success: true });
});

// Socket.IO connection
io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current board to newly connected client
  socket.emit("board:update", board);

  // Receive updates from client and broadcast to others
  socket.on("board:update", (newBoard) => {
    board = newBoard;
    socket.broadcast.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

