## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

function SortableTask({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <h3>{column.title}</h3>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <SortableTask key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 8 }
    })
  );

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (newBoard) => {
      setBoard(newBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    for (const colId of board.columnOrder) {
      result[colId] = board.columns[colId].taskIds.map((taskId) => board.tasks[taskId]);
    }
    return result;
  }, [board]);

  function findColumnByTaskId(taskId) {
    for (const colId of board.columnOrder) {
      if (board.columns[colId].taskIds.includes(taskId)) return colId;
    }
    return null;
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over || active.id === over.id) return;

    const activeColumnId = findColumnByTaskId(active.id);
    const overColumnId = findColumnByTaskId(over.id);

    if (!activeColumnId || !overColumnId) return;

    const newBoard = structuredClone(board);

    // Same-column reorder
    if (activeColumnId === overColumnId) {
      const ids = newBoard.columns[activeColumnId].taskIds;
      const oldIndex = ids.indexOf(active.id);
      const newIndex = ids.indexOf(over.id);
      newBoard.columns[activeColumnId].taskIds = arrayMove(ids, oldIndex, newIndex);
    } else {
      // Move between columns
      const sourceIds = newBoard.columns[activeColumnId].taskIds;
      const targetIds = newBoard.columns[overColumnId].taskIds;

      sourceIds.splice(sourceIds.indexOf(active.id), 1);
      const overIndex = targetIds.indexOf(over.id);
      targetIds.splice(overIndex >= 0 ? overIndex : targetIds.length, 0, active.id);
    }

    setBoard(newBoard);
    socket.emit("board:update", newBoard);
  }

  async function addTask(e) {
    e.preventDefault();
    if (!title.trim()) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, description, columnId: "todo" })
    });

    setTitle("");
    setDescription("");
  }

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>

        <form className="task-form" onSubmit={addTask}>
          <input
            placeholder="Task title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <input
            placeholder="Description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {board.columnOrder.map((columnId) => (
            <Column
              key={columnId}
              column={board.columns[columnId]}
              tasks={tasksByColumn[columnId] || []}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}
