          <header>
            <h3>In Progress</h3>
            <span class="count" id="count-doing">0</span>
          </header>
          <div class="cards" data-drop="doing"></div>
        </div>

        <div class="column" data-status="done">
          <header>
            <h3>Done</h3>
            <span class="count" id="count-done">0</span>
          </header>
          <div class="cards" data-drop="done"></div>
        </div>
      </div>
    </section>
  </main>

  <script>
    // --- State ---
    const state = {
      userId: crypto.randomUUID(),
      boardId: new URLSearchParams(location.search).get("board") || "demo-board",
      tasks: [],
      users: new Map(),
      ws: null
    };

    const els = {
      board: document.getElementById("board"),
      activity: document.getElementById("activity"),
      presenceList: document.getElementById("presenceList"),
      connectionStatus: document.getElementById("connectionStatus"),
      taskForm: document.getElementById("taskForm"),
      taskTitle: document.getElementById("taskTitle"),
      taskDesc: document.getElementById("taskDesc"),
      taskPriority: document.getElementById("taskPriority"),
      seedDemo: document.getElementById("seedDemo"),
      shareBoard: document.getElementById("shareBoard"),
      counts: {
        todo: document.getElementById("count-todo"),
        doing: document.getElementById("count-doing"),
        done: document.getElementById("count-done")
      }
    };

    const demoTasks = [
      { id: crypto.randomUUID(), title: "Design task board UI", desc: "Create responsive kanban layout", priority: "High", status: "doing", updatedAt: Date.now() },
      { id: crypto.randomUUID(), title: "Set up WebSocket server", desc: "Sync board state in real time", priority: "High", status: "todo", updatedAt: Date.now() },
      { id: crypto.randomUUID(), title: "Write task persistence layer", desc: "Store tasks in database", priority: "Medium", status: "done", updatedAt: Date.now() }
    ];

    function addActivity(message) {
      const item = document.createElement("div");
      item.className = "activity-item";
      item.textContent = `${new Date().toLocaleTimeString()} — ${message}`;
      els.activity.prepend(item);
    }

    function renderPresence() {
      els.presenceList.innerHTML = "";
      [...state.users.values()].forEach(u => {
        const li = document.createElement("li");
        li.textContent = `${u.name}${u.id === state.userId ? " (you)" : ""}`;
        els.presenceList.appendChild(li);
      });
    }

    function renderCounts() {
      const counts = { todo: 0, doing: 0, done: 0 };
      state.tasks.forEach(t => counts[t.status]++);
      els.counts.todo.textContent = counts.todo;
      els.counts.doing.textContent = counts.doing;
      els.counts.done.textContent = counts.done;
    }

    function taskCard(task) {
      const card = document.createElement("article");
      card.className = "card";
      card.draggable = true;
      card.dataset.id = task.id;

      card.innerHTML = `
        <strong>${escapeHtml(task.title)}</strong>
        <div class="small" style="margin-top:8px;">${escapeHtml(task.desc || "")}</div>
        <div class="meta">
          <span class="badge">${task.priority}</span>
          <span>${new Date(task.updatedAt).toLocaleTimeString()}</span>
        </div>
      `;

      card.addEventListener("dragstart", e => {
        card.classList.add("dragging");
        e.dataTransfer.setData("text/plain", task.id);
      });
      card.addEventListener("dragend", () => card.classList.remove("dragging"));
      return card;
    }

    function renderBoard() {
      document.querySelectorAll(".cards").forEach(zone => zone.innerHTML = "");
      ["todo", "doing", "done"].forEach(status => {
        const list = document.querySelector(`[data-drop="${status}"]`);
        state.tasks.filter(t => t.status === status).forEach(task => list.appendChild(taskCard(task)));
      });
      renderCounts();
    }

    function upsertTask(task) {
      const idx = state.tasks.findIndex(t => t.id === task.id);
      if (idx >= 0) state.tasks[idx] = { ...state.tasks[idx], ...task };
      else state.tasks.unshift(task);
      renderBoard();
    }

    function moveTask(id, status) {
      const task = state.tasks.find(t => t.id === id);
      if (!task || task.status === status) return;
      task.status = status;
      task.updatedAt = Date.now();
      renderBoard();
      broadcast({ type: "task:update", task });
      addActivity(`Moved "${task.title}" to ${labelStatus(status)}.`);
    }

    function labelStatus(s) {
      return { todo: "To Do", doing: "In Progress", done: "Done" }[s] || s;
    }

    function broadcast(payload) {
      if (state.ws && state.ws.readyState === WebSocket.OPEN) {
        state.ws.send(JSON.stringify({ boardId: state.boardId, userId: state.userId, ...payload }));
      } else {
        // Local fallback for demo use.
        handleMessage({ data: JSON.stringify({ boardId: state.boardId, userId: state.userId, ...payload }) });
      }
    }

    function connect() {
      // Replace with your server endpoint, e.g. wss://your-domain.com/ws
      const url = `ws://localhost:8080/ws?board=${encodeURIComponent(state.boardId)}&user=${encodeURIComponent(state.userId)}`;
      try {
        state.ws = new WebSocket(url);

        state.ws.addEventListener("open", () => {
          els.connectionStatus.textContent = "Connected";
          addActivity("Connected to collaboration server.");
          broadcast({
            type: "presence:join",
            user: { id: state.userId, name: "User " + state.userId.slice(0, 6) }
          });
        });

        state.ws.addEventListener("message", handleMessage);
        state.ws.addEventListener("close", () => {
          els.connectionStatus.textContent = "Disconnected";
          addActivity("Connection lost. Retrying in 3s...");
          setTimeout(connect, 3000);
        });
        state.ws.addEventListener("error", () => {
          els.connectionStatus.textContent = "Connection error";
        });
      } catch {
        els.connectionStatus.textContent = "Offline mode";
      }
    }

    function handleMessage(event) {
      const msg = typeof event.data === "string" ? JSON.parse(event.data) : JSON.parse(event.data);
      if (msg.boardId && msg.boardId !== state.boardId) return;

      switch (msg.type) {
        case "board:state":
          state.tasks = msg.tasks || [];
          state.users = new Map((msg.users || []).map(u => [u.id, u]));
          renderBoard();
          renderPresence();
          addActivity("Board state synchronized.");
          break;

        case "task:create":
          if (msg.userId !== state.userId) addActivity(`Task created: "${msg.task.title}"`);
          upsertTask(msg.task);
          break;

        case "task:update":
          if (msg.userId !== state.userId) addActivity(`Task updated: "${msg.task.title}"`);
          upsertTask(msg.task);
          break;

        case "task:delete":
          state.tasks = state.tasks.filter(t => t.id !== msg.id);
          renderBoard();
          addActivity("Task deleted.");
          break;

        case "presence:join":
          state.users.set(msg.user.id, msg.user);
          renderPresence();
          addActivity(`${msg.user.name} joined the board.`);
          break;

        case "presence:leave":
          state.users.delete(msg.userId);
          renderPresence();
          addActivity(`${msg.userName || "A user"} left the board.`);
          break;
      }
    }

    // --- Events ---
    els.taskForm.addEventListener("submit", e => {
      e.preventDefault();
      const task = {
        id: crypto.randomUUID(),
        title: els.taskTitle.value.trim(),
        desc: els.taskDesc.value.trim(),
        priority: els.taskPriority.value,
        status: "todo",
        updatedAt: Date.now()
      };
      if (!task.title) return;

      state.tasks.unshift(task);
      renderBoard();
      broadcast({ type: "task:create", task });
      addActivity(`Created task: "${task.title}"`);

      e.target.reset();
      els.taskPriority.value = "Medium";
    });

    els.seedDemo.addEventListener("click", () => {
      state.tasks = [...demoTasks];
      renderBoard();
      broadcast({ type: "board:state", tasks: state.tasks, users: [...state.users.values()] });
      addActivity("Loaded demo tasks.");
    });

    els.shareBoard.addEventListener("click", async () => {
      const url = new URL(location.href);
      url.searchParams.set("board", state.boardId);
      await navigator.clipboard.writeText(url.toString());
      addActivity("Invite link copied to clipboard.");
    });

    // Drag and drop zones
    document.querySelectorAll(".cards").forEach(zone => {
      zone.addEventListener("dragover", e => {
        e.preventDefault();
        zone.classList.add("dropzone");
      });

      zone.addEventListener("dragleave", () => zone.classList.remove("dropzone"));

      zone.addEventListener("drop", e => {
        e.preventDefault();
        zone.classList.remove("dropzone");
        const taskId = e.dataTransfer.getData("text/plain");
        const newStatus = zone.dataset.drop;
        moveTask(taskId, newStatus);
      });
    });

    window.addEventListener("beforeunload", () => {
      broadcast({
        type: "presence:leave",
        userId: state.userId,
        userName: "User " + state.userId.slice(0, 6)
      });
      state.ws?.close();
    });

    function escapeHtml(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    // Initial local state
    state.users.set(state.userId, { id: state.userId, name: "User " + state.userId.slice(0, 6) });
    renderPresence();
    renderBoard();
    addActivity("Board initialized.");

    // Connect to realtime backend
    connect();
  </script>
</body>
</html>
