## 2) Backend: `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

let boards = {
  todo: [
    { id: "task-1", title: "Design login screen", description: "Create initial wireframe" },
    { id: "task-2", title: "Set up database", description: "Choose schema and models" }
  ],
  doing: [
    { id: "task-3", title: "Implement API", description: "Build auth endpoints" }
  ],
  done: [
    { id: "task-4", title: "Project setup", description: "Initialize repo and tooling" }
  ]
};

function findAndRemoveTask(taskId) {
  for (const column of Object.keys(boards)) {
    const index = boards[column].findIndex((task) => task.id === taskId);
    if (index !== -1) {
      const [task] = boards[column].splice(index, 1);
      return { task, fromColumn: column };
    }
  }
  return null;
}

function moveTask(taskId, toColumn, toIndex = null) {
  const removed = findAndRemoveTask(taskId);
  if (!removed) return null;

  const task = removed.task;
  if (!boards[toColumn]) return null;

  if (toIndex === null || toIndex < 0 || toIndex > boards[toColumn].length) {
    boards[toColumn].push(task);
  } else {
    boards[toColumn].splice(toIndex, 0, task);
  }

  return { task, fromColumn: removed.fromColumn, toColumn };
}

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("board:init", boards);

  socket.on("task:create", (taskData) => {
    const task = {
      id: `task-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      title: taskData.title || "Untitled Task",
      description: taskData.description || ""
    };

    boards.todo.unshift(task);
    io.emit("board:update", boards);
  });

  socket.on("task:move", ({ taskId, toColumn, toIndex }) => {
    const result = moveTask(taskId, toColumn, toIndex);
    if (result) {
      io.emit("board:update", boards);
    }
  });

  socket.on("task:delete", ({ taskId }) => {
    const removed = findAndRemoveTask(taskId);
    if (removed) {
      io.emit("board:update", boards);
    }
  });

  socket.on("task:update", ({ taskId, updates }) => {
    for (const column of Object.keys(boards)) {
      const task = boards[column].find((t) => t.id === taskId);
      if (task) {
        Object.assign(task, updates);
        io.emit("board:update", boards);
        break;
      }
    }
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
