## 5) Frontend JS: `public/app.js`

```js
const socket = io();

let boards = {};
let draggedTaskId = null;

const taskLists = {
  todo: document.getElementById("todo-list"),
  doing: document.getElementById("doing-list"),
  done: document.getElementById("done-list")
};

const form = document.getElementById("new-task-form");
const titleInput = document.getElementById("task-title");
const descriptionInput = document.getElementById("task-description");

socket.on("board:init", (initialBoards) => {
  boards = initialBoards;
  renderBoards();
});

socket.on("board:update", (updatedBoards) => {
  boards = updatedBoards;
  renderBoards();
});

form.addEventListener("submit", (e) => {
  e.preventDefault();

  socket.emit("task:create", {
    title: titleInput.value.trim(),
    description: descriptionInput.value.trim()
  });

  titleInput.value = "";
  descriptionInput.value = "";
});

function renderBoards() {
  for (const column of Object.keys(taskLists)) {
    const list = taskLists[column];
    list.innerHTML = "";

    boards[column].forEach((task, index) => {
      const card = document.createElement("div");
      card.className = "task-card";
      card.draggable = true;
      card.dataset.taskId = task.id;
      card.dataset.column = column;
      card.dataset.index = index;

      card.innerHTML = `
        <div class="task-title">${escapeHtml(task.title)}</div>
        <div class="task-description">${escapeHtml(task.description || "")}</div>
        <div class="task-actions">
          <button class="edit-btn">Edit</button>
          <button class="delete-btn">Delete</button>
        </div>
      `;

      card.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        card.classList.add("dragging");
      });

      card.addEventListener("dragend", () => {
        draggedTaskId = null;
        card.classList.remove("dragging");
      });

      card.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      card.querySelector(".edit-btn").addEventListener("click", () => {
        const newTitle = prompt("Edit task title:", task.title);
        if (newTitle === null) return;

        const newDescription = prompt("Edit task description:", task.description || "");
        if (newDescription === null) return;

        socket.emit("task:update", {
          taskId: task.id,
          updates: {
            title: newTitle.trim() || task.title,
            description: newDescription.trim()
          }
        });
      });

      list.appendChild(card);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      if (!draggedTaskId) return;

      const targetColumn = list.id.replace("-list", "");
      const dropIndex = getDropIndex(list, e.clientY);

      socket.emit("task:move", {
        taskId: draggedTaskId,
        toColumn: targetColumn,
        toIndex: dropIndex
      });
    });
  }
}

function getDropIndex(list, mouseY) {
  const cards = [...list.querySelectorAll(".task-card:not(.dragging)")];

  for (let i = 0; i < cards.length; i++) {
    const rect = cards[i].getBoundingClientRect();
    const midpoint = rect.top + rect.height / 2;
    if (mouseY < midpoint) return i;
  }

  return cards.length;
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}
```

