## `server/index.js`

```js
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";

const app = express();
const server = createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

const PORT = process.env.PORT || 4000;

// In-memory state for demo purposes
let boards = [
  {
    id: "board-1",
    name: "Default Board",
    columns: [
      {
        id: "todo",
        title: "To Do",
        tasks: [
          { id: "t1", title: "Design wireframes", description: "Create initial UI mockups" },
          { id: "t2", title: "Set up auth", description: "Add login and registration flow" }
        ]
      },
      {
        id: "progress",
        title: "In Progress",
        tasks: [{ id: "t3", title: "Build API", description: "Create REST endpoints" }]
      },
      {
        id: "done",
        title: "Done",
        tasks: [{ id: "t4", title: "Project setup", description: "Initialize repo and tooling" }]
      }
    ]
  }
];

function findBoard(boardId) {
  return boards.find((b) => b.id === boardId);
}

function broadcastState() {
  io.emit("boards:update", boards);
}

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.post("/api/boards", (req, res) => {
  const { name } = req.body;
  const newBoard = {
    id: `board-${Date.now()}`,
    name: name || "Untitled Board",
    columns: [
      { id: "todo", title: "To Do", tasks: [] },
      { id: "progress", title: "In Progress", tasks: [] },
      { id: "done", title: "Done", tasks: [] }
    ]
  };
  boards.push(newBoard);
  broadcastState();
  res.status(201).json(newBoard);
});

app.post("/api/boards/:boardId/tasks", (req, res) => {
  const board = findBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const { columnId, title, description } = req.body;
  const column = board.columns.find((c) => c.id === columnId);
  if (!column) return res.status(404).json({ error: "Column not found" });

  const task = {
    id: `task-${Date.now()}`,
    title,
    description: description || ""
  };

  column.tasks.push(task);
  broadcastState();
  res.status(201).json(task);
});

app.put("/api/boards/:boardId/tasks/move", (req, res) => {
  const board = findBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const { taskId, fromColumnId, toColumnId, toIndex } = req.body;

  const fromColumn = board.columns.find((c) => c.id === fromColumnId);
  const toColumn = board.columns.find((c) => c.id === toColumnId);
  if (!fromColumn || !toColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const [task] = fromColumn.tasks.splice(taskIndex, 1);
  const insertIndex = Math.max(0, Math.min(toIndex ?? toColumn.tasks.length, toColumn.tasks.length));
  toColumn.tasks.splice(insertIndex, 0, task);

  broadcastState();
  res.json({ ok: true });
});

app.delete("/api/boards/:boardId/tasks/:taskId", (req, res) => {
  const board = findBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  for (const column of board.columns) {
    const idx = column.tasks.findIndex((t) => t.id === req.params.taskId);
    if (idx !== -1) {
      column.tasks.splice(idx, 1);
      broadcastState();
      return res.json({ ok: true });
    }
  }

  res.status(404).json({ error: "Task not found" });
});

io.on("connection", (socket) => {
  socket.emit("boards:update", boards);

  socket.on("task:create", ({ boardId, columnId, title, description }) => {
    const board = findBoard(boardId);
    if (!board) return;

    const column = board.columns.find((c) => c.id === columnId);
    if (!column) return;

    const task = {
      id: `task-${Date.now()}`,
      title,
      description: description || ""
    };

    column.tasks.push(task);
    broadcastState();
  });

  socket.on("task:move", ({ boardId, taskId, fromColumnId, toColumnId, toIndex }) => {
    const board = findBoard(boardId);
    if (!board) return;

    const fromColumn = board.columns.find((c) => c.id === fromColumnId);
    const toColumn = board.columns.find((c) => c.id === toColumnId);
    if (!fromColumn || !toColumn) return;

    const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromColumn.tasks.splice(taskIndex, 1);
    const insertIndex = Math.max(0, Math.min(toIndex ?? toColumn.tasks.length, toColumn.tasks.length));
    toColumn.tasks.splice(insertIndex, 0, task);

    broadcastState();
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

