## `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const SOCKET_URL = "http://localhost:4000";

function TaskCard({ task, isOverlay = false }) {
  return (
    <div className={`task-card ${isOverlay ? "overlay" : ""}`}>
      <div className="task-title">{task.title}</div>
      {task.description ? <div className="task-desc">{task.description}</div> : null}
    </div>
  );
}

function SortableTask({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners}>
      <TaskCard task={task} />
    </div>
  );
}

function Column({ column, allTaskIds }) {
  return (
    <div className="column">
      <div className="column-header">
        <h2>{column.title}</h2>
        <span>{column.tasks.length}</span>
      </div>

      <SortableContext items={allTaskIds} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {column.tasks.map((task) => (
            <SortableTask key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [boards, setBoards] = useState([]);
  const [activeTask, setActiveTask] = useState(null);
  const [activeMeta, setActiveMeta] = useState(null);
  const [selectedBoardId, setSelectedBoardId] = useState(null);

  const socket = useMemo(() => io(SOCKET_URL), []);

  useEffect(() => {
    socket.on("boards:update", (data) => {
      setBoards(data);
      if (!selectedBoardId && data.length > 0) setSelectedBoardId(data[0].id);
    });

    return () => {
      socket.disconnect();
    };
  }, [socket, selectedBoardId]);

  const selectedBoard = boards.find((b) => b.id === selectedBoardId);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 6 }
    })
  );

  function getTaskLocation(taskId) {
    if (!selectedBoard) return null;
    for (const column of selectedBoard.columns) {
      const index = column.tasks.findIndex((t) => t.id === taskId);
      if (index !== -1) return { columnId: column.id, index };
    }
    return null;
  }

  function handleDragStart(event) {
    const taskId = event.active.id;
    const location = getTaskLocation(taskId);
    if (!location) return;
    const task = selectedBoard.columns
      .find((c) => c.id === location.columnId)
      .tasks[location.index];

    setActiveTask(task);
    setActiveMeta(location);
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    setActiveTask(null);

    if (!over || !selectedBoard) return;

    const activeId = active.id;
    const overId = over.id;

    const fromLocation = getTaskLocation(activeId);
    const overLocation = getTaskLocation(overId);

    if (!fromLocation) return;

    let toColumnId = fromLocation.columnId;
    let toIndex = fromLocation.index;

    if (overLocation) {
      toColumnId = overLocation.columnId;
      toIndex = overLocation.index;
    } else {
      const columnId = over.data.current?.columnId;
      if (columnId) {
        toColumnId = columnId;
        toIndex = selectedBoard.columns.find((c) => c.id === columnId).tasks.length;
      }
    }

    if (
      fromLocation.columnId === toColumnId &&
      fromLocation.index === toIndex
    ) {
      return;
    }

    socket.emit("task:move", {
      boardId: selectedBoard.id,
      taskId: activeId,
      fromColumnId: fromLocation.columnId,
      toColumnId,
      toIndex
    });
  }

  function addBoard() {
    const name = prompt("Board name?");
    if (!name) return;

    fetch("http://localhost:4000/api/boards", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name })
    });
  }

  function addTask(columnId) {
    if (!selectedBoard) return;
    const title = prompt("Task title?");
    if (!title) return;
    const description = prompt("Task description?") || "";

    socket.emit("task:create", {
      boardId: selectedBoard.id,
      columnId,
      title,
      description
    });
  }

  if (!selectedBoard) {
    return (
      <div className="app">
        <header className="topbar">
          <h1>Project Manager</h1>
          <button onClick={addBoard}>New Board</button>
        </header>
        <div className="empty-state">Loading boards...</div>
      </div>
    );
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <div className="board-actions">
          <select
            value={selectedBoardId}
            onChange={(e) => setSelectedBoardId(e.target.value)}
          >
            {boards.map((board) => (
              <option key={board.id} value={board.id}>
                {board.name}
              </option>
            ))}
          </select>
          <button onClick={addBoard}>New Board</button>
        </div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <main className="board">
          {selectedBoard.columns.map((column) => (
            <div key={column.id} data-column-id={column.id}>
              <div
                className="drop-zone"
                data-column-id={column.id}
                onDoubleClick={() => addTask(column.id)}
              >
                <Column
                  column={column}
                  allTaskIds={column.tasks.map((task) => task.id)}
                />
              </div>
            </div>
          ))}
        </main>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} isOverlay /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
