## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Design app layout", description: "Create the main UI shell" },
        { id: "t2", title: "Add authentication", description: "Login and team access" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Build drag-and-drop", description: "Support moving cards" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "t4", title: "Create project scaffold", description: "Set up server and client" }
      ]
    }
  ]
};

function findTaskAndBoard(taskId) {
  for (const board of state.boards) {
    const taskIndex = board.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex !== -1) {
      return { board, taskIndex, task: board.tasks[taskIndex] };
    }
  }
  return null;
}

io.on("connection", (socket) => {
  socket.emit("state:init", state);

  socket.on("task:add", ({ boardId, task }) => {
    const board = state.boards.find((b) => b.id === boardId);
    if (!board) return;

    const newTask = {
      id: `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      title: task.title?.trim() || "Untitled Task",
      description: task.description?.trim() || ""
    };

    board.tasks.push(newTask);
    io.emit("state:update", state);
  });

  socket.on("task:move", ({ taskId, toBoardId, toIndex }) => {
    const source = findTaskAndBoard(taskId);
    const targetBoard = state.boards.find((b) => b.id === toBoardId);
    if (!source || !targetBoard) return;

    const [task] = source.board.tasks.splice(source.taskIndex, 1);

    const insertIndex =
      typeof toIndex === "number" && toIndex >= 0
        ? Math.min(toIndex, targetBoard.tasks.length)
        : targetBoard.tasks.length;

    targetBoard.tasks.splice(insertIndex, 0, task);
    io.emit("state:update", state);
  });

  socket.on("task:update", ({ taskId, changes }) => {
    const found = findTaskAndBoard(taskId);
    if (!found) return;

    Object.assign(found.task, changes);
    io.emit("state:update", state);
  });

  socket.on("task:delete", ({ taskId }) => {
    const found = findTaskAndBoard(taskId);
    if (!found) return;

    found.board.tasks.splice(found.taskIndex, 1);
    io.emit("state:update", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

