## 5) `public/app.js`

```js
const socket = io();

const boardsEl = document.getElementById("boards");
const statusEl = document.getElementById("connectionStatus");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const cancelTaskBtn = document.getElementById("cancelTaskBtn");
const taskBoardSelect = document.getElementById("taskBoard");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");

let appState = null;
let draggedTaskId = null;

socket.on("connect", () => {
  statusEl.textContent = "Connected";
});

socket.on("disconnect", () => {
  statusEl.textContent = "Disconnected";
});

socket.on("state:init", (state) => {
  appState = state;
  render();
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});

function render() {
  if (!appState) return;

  boardsEl.innerHTML = "";
  taskBoardSelect.innerHTML = "";

  appState.boards.forEach((board) => {
    const option = document.createElement("option");
    option.value = board.id;
    option.textContent = board.title;
    taskBoardSelect.appendChild(option);

    const boardEl = document.createElement("section");
    boardEl.className = "board";
    boardEl.dataset.boardId = board.id;

    boardEl.innerHTML = `
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}"></div>
    `;

    const listEl = boardEl.querySelector(".task-list");

    board.tasks.forEach((task, index) => {
      const taskEl = document.createElement("article");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button class="delete-btn" data-task-id="${task.id}">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      listEl.appendChild(taskEl);
    });

    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      listEl.classList.add("drop-hover");
    });

    listEl.addEventListener("dragleave", () => {
      listEl.classList.remove("drop-hover");
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      listEl.classList.remove("drop-hover");

      if (!draggedTaskId) return;

      const rect = listEl.getBoundingClientRect();
      const offsetY = e.clientY - rect.top;
      const tasks = [...listEl.querySelectorAll(".task")];

      let toIndex = tasks.findIndex((el) => {
        const r = el.getBoundingClientRect();
        return offsetY < r.top - rect.top + r.height / 2;
      });

      if (toIndex === -1) toIndex = tasks.length;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        toBoardId: board.id,
        toIndex
      });

      draggedTaskId = null;
    });

    boardsEl.appendChild(boardEl);
  });
}

addTaskBtn.addEventListener("click", () => {
  taskDialog.showModal();
});

cancelTaskBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  socket.emit("task:add", {
    boardId: taskBoardSelect.value,
    task: {
      title: taskTitleInput.value,
      description: taskDescriptionInput.value
    }
  });

  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
  taskDialog.close();
});

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

