## 2) `server.js`

This serves the frontend and syncs board state across connected clients.

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Serve static frontend
app.use(express.static(path.join(__dirname, "public")));

// In-memory board state
let state = {
  columns: [
    { id: "todo", title: "To Do", tasks: [] },
    { id: "doing", title: "In Progress", tasks: [] },
    { id: "done", title: "Done", tasks: [] }
  ]
};

function broadcast(message) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

function generateId() {
  return Math.random().toString(36).slice(2, 10);
}

wss.on("connection", (ws) => {
  // Send initial state
  ws.send(JSON.stringify({ type: "INIT", payload: state }));

  ws.on("message", (raw) => {
    let msg;
    try {
      msg = JSON.parse(raw);
    } catch {
      return;
    }

    switch (msg.type) {
      case "ADD_TASK": {
        const { columnId, text } = msg.payload;
        const column = state.columns.find((c) => c.id === columnId);
        if (!column || !text?.trim()) return;

        const task = {
          id: generateId(),
          text: text.trim(),
          createdAt: Date.now()
        };

        column.tasks.push(task);
        broadcast({ type: "STATE_UPDATE", payload: state });
        break;
      }

      case "MOVE_TASK": {
        const { taskId, fromColumnId, toColumnId, toIndex } = msg.payload;

        const fromColumn = state.columns.find((c) => c.id === fromColumnId);
        const toColumn = state.columns.find((c) => c.id === toColumnId);
        if (!fromColumn || !toColumn) return;

        const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromColumn.tasks.splice(taskIndex, 1);

        const insertIndex =
          typeof toIndex === "number" && toIndex >= 0
            ? Math.min(toIndex, toColumn.tasks.length)
            : toColumn.tasks.length;

        toColumn.tasks.splice(insertIndex, 0, task);
        broadcast({ type: "STATE_UPDATE", payload: state });
        break;
      }

      case "DELETE_TASK": {
        const { taskId, columnId } = msg.payload;
        const column = state.columns.find((c) => c.id === columnId);
        if (!column) return;

        column.tasks = column.tasks.filter((t) => t.id !== taskId);
        broadcast({ type: "STATE_UPDATE", payload: state });
        break;
      }

      case "RESET_BOARD": {
        state = {
          columns: [
            { id: "todo", title: "To Do", tasks: [] },
            { id: "doing", title: "In Progress", tasks: [] },
            { id: "done", title: "Done", tasks: [] }
          ]
        };
        broadcast({ type: "STATE_UPDATE", payload: state });
        break;
      }

      default:
        break;
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

