## 5) `public/app.js`

This handles rendering, drag-and-drop, and WebSocket collaboration.

```js
const boardEl = document.getElementById("board");
const taskInput = document.getElementById("taskInput");
const columnSelect = document.getElementById("columnSelect");
const addTaskBtn = document.getElementById("addTaskBtn");
const resetBtn = document.getElementById("resetBtn");
const statusEl = document.getElementById("status");

const columnTemplate = document.getElementById("columnTemplate");
const taskTemplate = document.getElementById("taskTemplate");

let state = null;
let ws = null;
let draggedTask = null;

const columnOrder = ["todo", "doing", "done"];

function setStatus(online) {
  statusEl.textContent = online ? "Connected" : "Disconnected";
  statusEl.classList.toggle("online", online);
  statusEl.classList.toggle("offline", !online);
}

function connect() {
  ws = new WebSocket(`${location.origin.replace("http", "ws")}`);

  ws.addEventListener("open", () => setStatus(true));
  ws.addEventListener("close", () => setStatus(false));
  ws.addEventListener("error", () => setStatus(false));

  ws.addEventListener("message", (event) => {
    const msg = JSON.parse(event.data);

    if (msg.type === "INIT" || msg.type === "STATE_UPDATE") {
      state = msg.payload;
      render();
    }
  });
}

function send(type, payload) {
  if (ws && ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify({ type, payload }));
  }
}

function render() {
  boardEl.innerHTML = "";

  const columnsById = new Map(state.columns.map((c) => [c.id, c]));

  columnOrder.forEach((columnId) => {
    const column = columnsById.get(columnId);
    if (!column) return;

    const columnNode = columnTemplate.content.cloneNode(true);
    const columnEl = columnNode.querySelector(".column");
    const titleEl = columnNode.querySelector("h2");
    const countEl = columnNode.querySelector(".task-count");
    const taskListEl = columnNode.querySelector(".task-list");

    titleEl.textContent = column.title;
    countEl.textContent = `${column.tasks.length} task(s)`;

    taskListEl.dataset.columnId = column.id;

    column.tasks.forEach((task) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      const textEl = taskNode.querySelector(".task-text");
      const deleteBtn = taskNode.querySelector(".delete-btn");

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;
      textEl.textContent = task.text;

      taskEl.addEventListener("dragstart", (e) => {
        draggedTask = {
          taskId: task.id,
          fromColumnId: column.id
        };
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("text/plain", task.id);
      });

      deleteBtn.addEventListener("click", () => {
        send("DELETE_TASK", { taskId: task.id, columnId: column.id });
      });

      taskListEl.appendChild(taskNode);
    });

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumnId = column.id;
      const children = [...taskListEl.querySelectorAll(".task")];
      const targetTask = e.target.closest(".task");

      let toIndex = column.tasks.length;
      if (targetTask) {
        toIndex = children.indexOf(targetTask);
      }

      send("MOVE_TASK", {
        taskId: draggedTask.taskId,
        fromColumnId: draggedTask.fromColumnId,
        toColumnId,
        toIndex
      });

      draggedTask = null;
    });

    boardEl.appendChild(columnNode);
  });
}

addTaskBtn.addEventListener("click", () => {
  const text = taskInput.value.trim();
  const columnId = columnSelect.value;

  if (!text) return;

  send("ADD_TASK", { columnId, text });
  taskInput.value = "";
  taskInput.focus();
});

taskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

resetBtn.addEventListener("click", () => {
  send("RESET_BOARD", {});
});

connect();
```

