## `server/index.js`

```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory project board state
let boardState = {
  tasks: [
    {
      id: "task-1",
      title: "Design login screen",
      description: "Create wireframes and final UI mockups.",
      status: "todo",
      assignee: "Ava",
      priority: "high"
    },
    {
      id: "task-2",
      title: "Build auth API",
      description: "Implement signup and login endpoints.",
      status: "inprogress",
      assignee: "Noah",
      priority: "medium"
    },
    {
      id: "task-3",
      title: "Deploy staging app",
      description: "Set up CI/CD for staging deployment.",
      status: "done",
      assignee: "Mia",
      priority: "low"
    }
  ]
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board/reset", (req, res) => {
  boardState = {
    tasks: []
  };
  io.emit("board:update", boardState);
  res.json({ ok: true });
});

function findTaskIndex(taskId) {
  return boardState.tasks.findIndex((t) => t.id === taskId);
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", (task) => {
    const newTask = {
      id: `task-${crypto.randomUUID()}`,
      title: task.title || "Untitled task",
      description: task.description || "",
      status: task.status || "todo",
      assignee: task.assignee || "",
      priority: task.priority || "medium"
    };

    boardState.tasks.push(newTask);
    io.emit("board:update", boardState);
  });

  socket.on("task:update", (updatedTask) => {
    const idx = findTaskIndex(updatedTask.id);
    if (idx !== -1) {
      boardState.tasks[idx] = {
        ...boardState.tasks[idx],
        ...updatedTask
      };
      io.emit("board:update", boardState);
    }
  });

  socket.on("task:move", ({ taskId, newStatus, newIndex }) => {
    const idx = findTaskIndex(taskId);
    if (idx === -1) return;

    const [task] = boardState.tasks.splice(idx, 1);
    task.status = newStatus;

    const tasksInColumn = boardState.tasks.filter((t) => t.status === newStatus);
    const insertAt = Math.min(
      Math.max(newIndex, 0),
      tasksInColumn.length
    );

    let positionalIndex = 0;
    let globalInsertIndex = boardState.tasks.length;

    for (let i = 0; i < boardState.tasks.length; i++) {
      if (boardState.tasks[i].status === newStatus) {
        if (positionalIndex === insertAt) {
          globalInsertIndex = i;
          break;
        }
        positionalIndex++;
      }
    }

    if (globalInsertIndex === boardState.tasks.length) {
      boardState.tasks.push(task);
    } else {
      boardState.tasks.splice(globalInsertIndex, 0, task);
    }

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", (taskId) => {
    boardState.tasks = boardState.tasks.filter((t) => t.id !== taskId);
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

