## `client/app.js`

```js
const socket = io("http://localhost:3001");

let boardState = { tasks: [] };
let draggedTaskId = null;

const columns = {
  todo: document.getElementById("todoList"),
  inprogress: document.getElementById("inprogressList"),
  done: document.getElementById("doneList")
};

const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const dialogTitle = document.getElementById("dialogTitle");

const taskIdInput = document.getElementById("taskId");
const titleInput = document.getElementById("titleInput");
const descriptionInput = document.getElementById("descriptionInput");
const assigneeInput = document.getElementById("assigneeInput");
const priorityInput = document.getElementById("priorityInput");
const statusInput = document.getElementById("statusInput");

document.getElementById("newTaskBtn").addEventListener("click", () => {
  openTaskDialog();
});

document.getElementById("cancelBtn").addEventListener("click", () => {
  taskDialog.close();
});

document.getElementById("resetBtn").addEventListener("click", async () => {
  await fetch("http://localhost:3001/api/board/reset", { method: "POST" });
});

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const task = {
    id: taskIdInput.value || undefined,
    title: titleInput.value,
    description: descriptionInput.value,
    assignee: assigneeInput.value,
    priority: priorityInput.value,
    status: statusInput.value
  };

  if (task.id) {
    socket.emit("task:update", task);
  } else {
    socket.emit("task:create", task);
  }

  taskDialog.close();
  taskForm.reset();
  taskIdInput.value = "";
});

function openTaskDialog(task = null) {
  if (task) {
    dialogTitle.textContent = "Edit Task";
    taskIdInput.value = task.id;
    titleInput.value = task.title;
    descriptionInput.value = task.description;
    assigneeInput.value = task.assignee;
    priorityInput.value = task.priority;
    statusInput.value = task.status;
  } else {
    dialogTitle.textContent = "New Task";
    taskForm.reset();
    taskIdInput.value = "";
    statusInput.value = "todo";
    priorityInput.value = "medium";
  }
  taskDialog.showModal();
}

function renderBoard() {
  Object.values(columns).forEach((col) => (col.innerHTML = ""));

  const grouped = {
    todo: [],
    inprogress: [],
    done: []
  };

  for (const task of boardState.tasks) {
    grouped[task.status].push(task);
  }

  for (const status of Object.keys(grouped)) {
    grouped[status].forEach((task, index) => {
      columns[status].appendChild(createTaskElement(task, index));
    });
  }

  attachDropZones();
}

function createTaskElement(task, index) {
  const el = document.createElement("article");
  el.className = "task";
  el.draggable = true;
  el.dataset.id = task.id;

  el.addEventListener("dragstart", () => {
    draggedTaskId = task.id;
    el.classList.add("dragging");
  });

  el.addEventListener("dragend", () => {
    draggedTaskId = null;
    el.classList.remove("dragging");
  });

  el.innerHTML = `
    <div class="task-header">
      <h3 class="task-title">${escapeHtml(task.title)}</h3>
    </div>
    <div class="meta">${escapeHtml(task.description || "")}</div>
    <div class="meta">Assignee: ${escapeHtml(task.assignee || "Unassigned")}</div>
    <span class="tag ${task.priority}">${task.priority.toUpperCase()}</span>
    <div class="task-actions">
      <button class="edit-btn" type="button">Edit</button>
      <button class="delete-btn secondary" type="button">Delete</button>
    </div>
  `;

  el.querySelector(".edit-btn").addEventListener("click", () => openTaskDialog(task));
  el.querySelector(".delete-btn").addEventListener("click", () => {
    socket.emit("task:delete", task.id);
  });

  return el;
}

function attachDropZones() {
  document.querySelectorAll(".column").forEach((column) => {
    const status = column.dataset.status;

    column.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    column.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTaskId) return;

      const tasksInColumn = boardState.tasks.filter((t) => t.status === status);
      socket.emit("task:move", {
        taskId: draggedTaskId,
        newStatus: status,
        newIndex: tasksInColumn.length
      });
    });
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

