## 3) Backend: `server/data.js`

```js
const boards = {
  todo: [
    { id: "task-1", title: "Design wireframes", description: "Create initial UI mockups" },
    { id: "task-2", title: "Set up auth", description: "Implement login and signup" }
  ],
  doing: [
    { id: "task-3", title: "Build task API", description: "REST endpoints for tasks" }
  ],
  done: [
    { id: "task-4", title: "Project setup", description: "Initialize repo and tooling" }
  ]
};

function getBoards() {
  return boards;
}

function moveTask(taskId, fromColumn, toColumn, toIndex) {
  const fromTasks = boards[fromColumn];
  const toTasks = boards[toColumn];

  const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return null;

  const [task] = fromTasks.splice(taskIndex, 1);

  if (typeof toIndex !== "number" || toIndex < 0 || toIndex > toTasks.length) {
    toTasks.push(task);
  } else {
    toTasks.splice(toIndex, 0, task);
  }

  return { task, fromColumn, toColumn, toIndex };
}

function addTask(column, task) {
  if (!boards[column]) return null;
  boards[column].push(task);
  return task;
}

module.exports = {
  getBoards,
  moveTask,
  addTask
};
```

