## 4) Backend: `server/index.js`

```js
const express = require("express");
const http = require("http");
const path = require("path");
const { Server } = require("socket.io");
const { getBoards, moveTask, addTask } = require("./data");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "..", "client")));

app.get("/api/boards", (req, res) => {
  res.json(getBoards());
});

app.post("/api/tasks", (req, res) => {
  const { column, title, description } = req.body;
  if (!column || !title) {
    return res.status(400).json({ error: "column and title are required" });
  }

  const task = {
    id: `task-${Date.now()}`,
    title,
    description: description || ""
  };

  const created = addTask(column, task);
  if (!created) {
    return res.status(400).json({ error: "Invalid column" });
  }

  io.emit("task-created", { column, task: created });
  res.status(201).json(created);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.on("task-move", (payload) => {
    const { taskId, fromColumn, toColumn, toIndex } = payload;
    const result = moveTask(taskId, fromColumn, toColumn, toIndex);

    if (!result) {
      socket.emit("error-message", { message: "Task move failed" });
      return;
    }

    io.emit("task-moved", result);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

