## 7) Frontend: `client/app.js`

```js
const socket = io();

let state = {
  todo: [],
  doing: [],
  done: []
};

const taskLists = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

async function loadBoards() {
  const res = await fetch("/api/boards");
  state = await res.json();
  renderBoards();
}

function createTaskElement(task, column) {
  const div = document.createElement("div");
  div.className = "task";
  div.draggable = true;
  div.dataset.taskId = task.id;
  div.dataset.column = column;

  div.innerHTML = `
    <h3>${escapeHtml(task.title)}</h3>
    <p>${escapeHtml(task.description || "")}</p>
  `;

  div.addEventListener("dragstart", (e) => {
    e.dataTransfer.setData("text/plain", JSON.stringify({
      taskId: task.id,
      fromColumn: column
    }));
  });

  return div;
}

function renderBoards() {
  Object.keys(taskLists).forEach((column) => {
    taskLists[column].innerHTML = "";
    state[column].forEach((task) => {
      taskLists[column].appendChild(createTaskElement(task, column));
    });
  });
}

function setupDragAndDrop() {
  Object.entries(taskLists).forEach(([columnName, listEl]) => {
    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      listEl.classList.add("drag-over");
    });

    listEl.addEventListener("dragleave", () => {
      listEl.classList.remove("drag-over");
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      listEl.classList.remove("drag-over");

      const data = JSON.parse(e.dataTransfer.getData("text/plain"));
      const { taskId, fromColumn } = data;

      const tasks = state[columnName];
      const toIndex = tasks.length;

      socket.emit("task-move", {
        taskId,
        fromColumn,
        toColumn: columnName,
        toIndex
      });
    });
  });
}

document.getElementById("newTaskForm").addEventListener("submit", async (e) => {
  e.preventDefault();

  const title = document.getElementById("taskTitle").value.trim();
  const description = document.getElementById("taskDescription").value.trim();
  const column = document.getElementById("taskColumn").value;

  const res = await fetch("/api/tasks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description, column })
  });

  if (res.ok) {
    e.target.reset();
  } else {
    alert("Failed to create task");
  }
});

socket.on("task-created", ({ column, task }) => {
  state[column].push(task);
  renderBoards();
});

socket.on("task-moved", ({ task, fromColumn, toColumn }) => {
  const fromTasks = state[fromColumn];
  const index = fromTasks.findIndex((t) => t.id === task.id);
  if (index !== -1) fromTasks.splice(index, 1);

  state[toColumn].push(task);
  renderBoards();
});

socket.on("error-message", ({ message }) => {
  alert(message);
});

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

setupDragAndDrop();
loadBoards();
```

