## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

const PORT = process.env.PORT || 3000;

// In-memory store for demo purposes
let boardState = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Design login page", description: "Create initial UI mockups" },
        { id: "t2", title: "Set up database schema", description: "Define tables and relationships" }
      ]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Build task editor", description: "Inline editing for tasks" }
      ]
    },
    done: {
      id: "done",
      title: "Done",
      tasks: [
        { id: "t4", title: "Initialize repo", description: "Set up project structure" }
      ]
    }
  }
};

io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  // Send current board state to the newly connected client
  socket.emit("board:state", boardState);

  // Broadcast task updates from one client to all others
  socket.on("board:update", (newState) => {
    boardState = newState;
    socket.broadcast.emit("board:state", boardState);
  });

  // Add a task
  socket.on("task:add", ({ columnId, task }) => {
    boardState.columns[columnId].tasks.push(task);
    io.emit("board:state", boardState);
  });

  // Update a task
  socket.on("task:update", ({ columnId, taskId, updates }) => {
    const task = boardState.columns[columnId].tasks.find((t) => t.id === taskId);
    if (task) {
      Object.assign(task, updates);
      io.emit("board:state", boardState);
    }
  });

  // Delete a task
  socket.on("task:delete", ({ columnId, taskId }) => {
    boardState.columns[columnId].tasks = boardState.columns[columnId].tasks.filter(
      (t) => t.id !== taskId
    );
    io.emit("board:state", boardState);
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

