## 6) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const columnTemplate = document.getElementById("columnTemplate");
const taskTemplate = document.getElementById("taskTemplate");
const addTaskBtn = document.getElementById("addTaskBtn");
const newTaskTitle = document.getElementById("newTaskTitle");
const newTaskColumn = document.getElementById("newTaskColumn");

let boardState = null;
let draggedTask = null;

function renderBoard(state) {
  boardEl.innerHTML = "";

  Object.values(state.columns).forEach((column) => {
    const columnNode = columnTemplate.content.cloneNode(true);
    const section = columnNode.querySelector(".column");
    const title = columnNode.querySelector(".column-title");
    const taskList = columnNode.querySelector(".task-list");

    title.textContent = column.title;

    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTask) return;

      moveTask(draggedTask.taskId, draggedTask.fromColumnId, column.id);
      draggedTask = null;
    });

    column.tasks.forEach((task) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      const titleEl = taskNode.querySelector(".task-title");
      const descEl = taskNode.querySelector(".task-desc");
      const deleteBtn = taskNode.querySelector(".delete-btn");

      titleEl.textContent = task.title;
      descEl.textContent = task.description || "";

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;
      taskEl.draggable = true;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = { taskId: task.id, fromColumnId: column.id };
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { columnId: column.id, taskId: task.id });
      });

      taskList.appendChild(taskNode);
    });

    boardEl.appendChild(columnNode);
  });
}

function moveTask(taskId, fromColumnId, toColumnId) {
  const fromTasks = boardState.columns[fromColumnId].tasks;
  const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return;

  const [task] = fromTasks.splice(taskIndex, 1);
  boardState.columns[toColumnId].tasks.push(task);

  socket.emit("board:update", boardState);
}

addTaskBtn.addEventListener("click", () => {
  const title = newTaskTitle.value.trim();
  const columnId = newTaskColumn.value;

  if (!title) return;

  const task = {
    id: `task_${Date.now()}`,
    title,
    description: "New task"
  };

  socket.emit("task:add", { columnId, task });
  newTaskTitle.value = "";
  newTaskTitle.focus();
});

socket.on("board:state", (state) => {
  boardState = state;
  renderBoard(boardState);
});
```

