```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { state } from "./store.js";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

const PORT = 4000;

app.get("/api/boards", (req, res) => {
  res.json(state.boards);
});

app.get("/api/boards/:boardId", (req, res) => {
  const board = state.boards.find((b) => b.id === req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });
  res.json(board);
});

app.post("/api/boards/:boardId/tasks", (req, res) => {
  const board = state.boards.find((b) => b.id === req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const { title, description = "", assignee = "" } = req.body;
  const id = `task-${crypto.randomUUID()}`;

  board.tasks[id] = {
    id,
    title,
    description,
    assignee,
    updatedAt: Date.now()
  };

  board.columns[0].taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(board.tasks[id]);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.on("board:join", (boardId) => {
    socket.join(boardId);
    const board = state.boards.find((b) => b.id === boardId);
    if (board) socket.emit("board:update", board);
  });

  socket.on("task:move", ({ boardId, taskId, fromColumnId, toColumnId, toIndex }) => {
    const board = state.boards.find((b) => b.id === boardId);
    if (!board) return;

    const fromColumn = board.columns.find((c) => c.id === fromColumnId);
    const toColumn = board.columns.find((c) => c.id === toColumnId);
    if (!fromColumn || !toColumn) return;

    const fromIndex = fromColumn.taskIds.indexOf(taskId);
    if (fromIndex === -1) return;

    fromColumn.taskIds.splice(fromIndex, 1);
    toColumn.taskIds.splice(toIndex, 0, taskId);

    board.tasks[taskId].updatedAt = Date.now();

    io.to(boardId).emit("board:update", board);
  });

  socket.on("task:update", ({ boardId, taskId, updates }) => {
    const board = state.boards.find((b) => b.id === boardId);
    if (!board || !board.tasks[taskId]) return;

    board.tasks[taskId] = {
      ...board.tasks[taskId],
      ...updates,
      updatedAt: Date.now()
    };

    io.to(boardId).emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

