```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  closestCorners,
  DragOverlay,
  useDroppable,
  useDraggable
} from "@dnd-kit/core";
import { fetchBoard, API_URL } from "./api";

const socket = io(API_URL);

function TaskCard({ task, isOverlay = false }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task.id
  });

  const style = {
    transform: transform
      ? `translate3d(${transform.x}px, ${transform.y}px, 0)`
      : undefined,
    opacity: isDragging && !isOverlay ? 0.4 : 1
  };

  return (
    <div ref={setNodeRef} className="task-card" style={style} {...listeners} {...attributes}>
      <div className="task-title">{task.title}</div>
      <div className="task-meta">
        {task.assignee ? `Assignee: ${task.assignee}` : "Unassigned"}
      </div>
      {task.description && <div className="task-desc">{task.description}</div>}
    </div>
  );
}

function Column({ column, tasks }) {
  const { setNodeRef, isOver } = useDroppable({ id: column.id });

  return (
    <div className={`column ${isOver ? "column-over" : ""}`} ref={setNodeRef}>
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{column.taskIds.length}</span>
      </div>
      <div className="column-body">
        {tasks.map((task) => (
          <TaskCard key={task.id} task={task} />
        ))}
      </div>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [activeTask, setActiveTask] = useState(null);

  const boardId = "board-1";

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  useEffect(() => {
    fetchBoard(boardId).then(setBoard);

    socket.emit("board:join", boardId);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const tasksById = useMemo(() => {
    const out = {};
    if (!board) return out;
    for (const [id, task] of Object.entries(board.tasks)) out[id] = task;
    return out;
  }, [board]);

  function findColumnByTaskId(taskId) {
    if (!board) return null;
    return board.columns.find((col) => col.taskIds.includes(taskId));
  }

  function handleDragStart(event) {
    const taskId = event.active.id;
    setActiveTask(board?.tasks[taskId] || null);
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    setActiveTask(null);
    if (!board || !over) return;

    const taskId = active.id;

    const fromColumn = findColumnByTaskId(taskId);
    const toColumn = board.columns.find((c) => c.id === over.id) || findColumnByTaskId(over.id);

    if (!fromColumn || !toColumn) return;

    const fromColumnId = fromColumn.id;
    const toColumnId = toColumn.id;

    if (fromColumnId === toColumnId && over.id === taskId) return;

    let toIndex = toColumn.taskIds.length;

    // Drop over column container
    if (board.columns.some((c) => c.id === over.id)) {
      toIndex = toColumn.taskIds.length;
    } else {
      const overTaskId = over.id;
      toIndex = toColumn.taskIds.indexOf(overTaskId);
      if (toIndex < 0) toIndex = toColumn.taskIds.length;
    }

    socket.emit("task:move", {
      boardId,
      taskId,
      fromColumnId,
      toColumnId,
      toIndex
    });
  }

  if (!board) return <div className="loading">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <div>
          <h1>{board.name}</h1>
          <p>Real-time task board collaboration</p>
        </div>
        <button
          className="btn"
          onClick={() => {
            const title = prompt("Task title?");
            if (!title) return;

            socket.emit("task:update", {
              boardId,
              taskId: null,
              updates: {}
            });
          }}
          disabled
        >
          Add Task
        </button>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={column.taskIds.map((id) => tasksById[id]).filter(Boolean)}
            />
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} isOverlay /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

