```ts
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";
import { initialBoardState } from "./store.js";
import { BoardState, CreateTaskPayload, MoveTaskPayload } from "./types.js";

const app = express();
app.use(cors());
app.use(express.json());

let boardState: BoardState = structuredClone(initialBoardState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

const httpServer = createServer(app);

const io = new Server(httpServer, {
  cors: {
    origin: "*"
  }
});

function emitBoardUpdate() {
  io.emit("board:update", boardState);
}

function moveTask(payload: MoveTaskPayload) {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = payload;

  const sourceColumn = boardState.columns[sourceColumnId];
  const destinationColumn = boardState.columns[destinationColumnId];
  const task = boardState.tasks[taskId];

  if (!sourceColumn || !destinationColumn || !task) return;

  const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
  if (sourceIndex === -1) return;

  sourceColumn.taskIds.splice(sourceIndex, 1);

  const adjustedIndex =
    sourceColumnId === destinationColumnId && sourceIndex < destinationIndex
      ? destinationIndex - 1
      : destinationIndex;

  destinationColumn.taskIds.splice(adjustedIndex, 0, taskId);
  task.status = destinationColumnId;
}

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("task:create", (payload: CreateTaskPayload) => {
    const id = `task-${crypto.randomUUID()}`;

    const newTask = {
      id,
      title: payload.title,
      description: payload.description,
      status: payload.columnId,
      createdAt: Date.now()
    };

    boardState.tasks[id] = newTask;
    boardState.columns[payload.columnId].taskIds.unshift(id);

    emitBoardUpdate();
  });

  socket.on("task:move", (payload: MoveTaskPayload) => {
    moveTask(payload);
    emitBoardUpdate();
  });

  socket.on("board:reset", () => {
    boardState = structuredClone(initialBoardState);
    emitBoardUpdate();
  });
});

const port = Number(process.env.PORT || 4000);
httpServer.listen(port, () => {
  console.log(`Server listening on http://localhost:${port}`);
});
```

