  id: string;
  title: string;
  description?: string;
  status: ColumnId;
  createdAt: number;
};

type Column = {
  id: ColumnId;
  title: string;
  taskIds: string[];
};

type BoardState = {
  tasks: Record<string, Task>;
  columns: Record<ColumnId, Column>;
  columnOrder: ColumnId[];
};

const SERVER_URL = "http://localhost:4000";

function TaskCard({ task }: { task: Task }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.4 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      {task.description ? <p>{task.description}</p> : null}
    </div>
  );
}

function ColumnView({
  column,
  tasks
}: {
  column: Column;
  tasks: Task[];
}) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{tasks.length}</span>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [board, setBoard] = useState<BoardState | null>(null);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  useEffect(() => {
    const s = io(SERVER_URL);
    setSocket(s);

    s.on("board:update", (nextBoard: BoardState) => {
      setBoard(nextBoard);
    });

    return () => {
      s.disconnect();
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return null;

    return board.columnOrder.map((columnId) => {
      const column = board.columns[columnId];
      const tasks = column.taskIds.map((id) => board.tasks[id]).filter(Boolean);
      return { column, tasks };
    });
  }, [board]);

  function handleDragStart(event: DragStartEvent) {
    setActiveTaskId(String(event.active.id));
  }

  function handleDragEnd(event: DragEndEvent) {
    setActiveTaskId(null);

    if (!board || !socket) return;

    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const sourceColumnId = board.columnOrder.find((colId) =>
      board.columns[colId].taskIds.includes(taskId)
    );

    if (!sourceColumnId) return;

    let destinationColumnId: ColumnId = sourceColumnId;
    let destinationIndex = 0;

    const overTask = Object.values(board.tasks).find((t) => t.id === overId);
    if (overTask) {
      destinationColumnId = overTask.status;
      destinationIndex = board.columns[destinationColumnId].taskIds.indexOf(overTask.id);
    } else if (board.columns[overId as ColumnId]) {
      destinationColumnId = overId as ColumnId;
      destinationIndex = 0;
    } else {
      return;
    }

    socket.emit("task:move", {
      taskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    });
  }

  function createTask() {
    if (!socket) return;
    const title = prompt("Task title?");
    if (!title) return;

    socket.emit("task:create", {
      title,
      columnId: "todo"
    });
  }

  function resetBoard() {
    socket?.emit("board:reset");
  }

  if (!board || !tasksByColumn) {
    return <div className="app-shell">Loading board...</div>;
  }

  const activeTask = activeTaskId ? board.tasks[activeTaskId] : null;

  return (
    <div className="app-shell">
      <header className="topbar">
        <div>
          <h1>Project Board</h1>
          <p>Drag tasks across columns. Updates sync in real time.</p>
        </div>
        <div className="actions">
          <button onClick={createTask}>New Task</button>
          <button onClick={resetBoard} className="secondary">
            Reset Board
          </button>
        </div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {tasksByColumn.map(({ column, tasks }) => (
            <ColumnView key={column.id} column={column} tasks={tasks} />
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <div className="task-card dragging">{activeTask.title}</div> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

