## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { WebSocketServer } from "ws";
import { initialState, BoardState, ColumnId, Task } from "./state.js";

const app = express();
app.use(cors());
app.use(express.json());

let boardState: BoardState = structuredClone(initialState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/board/move", (req, res) => {
  const { taskId, fromColumn, toColumn, toIndex } = req.body as {
    taskId: string;
    fromColumn: ColumnId;
    toColumn: ColumnId;
    toIndex: number;
  };

  const sourceList = boardState.columns[fromColumn];
  const targetList = boardState.columns[toColumn];

  const taskIndex = sourceList.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const [task] = sourceList.splice(taskIndex, 1);
  targetList.splice(toIndex, 0, task);

  broadcast({
    type: "board:update",
    payload: boardState
  });

  res.json({ ok: true, boardState });
});

app.post("/api/board/task", (req, res) => {
  const { columnId, title, description } = req.body as {
    columnId: ColumnId;
    title: string;
    description?: string;
  };

  const task: Task = {
    id: `task-${crypto.randomUUID()}`,
    title,
    description
  };

  boardState.columns[columnId].unshift(task);

  broadcast({
    type: "board:update",
    payload: boardState
  });

  res.json({ ok: true, task });
});

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

function broadcast(message: unknown) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === 1) client.send(data);
  });
}

wss.on("connection", (ws) => {
  ws.send(
    JSON.stringify({
      type: "board:update",
      payload: boardState
    })
  );

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === "board:reset") {
        boardState = structuredClone(initialState);
        broadcast({ type: "board:update", payload: boardState });
      }
    } catch {
      // ignore
    }
  });
});

const PORT = process.env.PORT || 4000;

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

