## `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  PointerSensor,
  closestCorners,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { BoardState, ColumnId, Task, columns } from "./types";

const API_URL = "http://localhost:4000";

function findColumnOfTask(board: BoardState, taskId: string): ColumnId | null {
  for (const col of columns) {
    if (board.columns[col.id].some((t) => t.id === taskId)) return col.id;
  }
  return null;
}

function moveTask(
  board: BoardState,
  taskId: string,
  fromColumn: ColumnId,
  toColumn: ColumnId,
  toIndex: number
): BoardState {
  const next: BoardState = {
    columns: {
      todo: [...board.columns.todo],
      inProgress: [...board.columns.inProgress],
      review: [...board.columns.review],
      done: [...board.columns.done]
    }
  };

  const fromList = next.columns[fromColumn];
  const toList = next.columns[toColumn];
  const index = fromList.findIndex((t) => t.id === taskId);
  if (index === -1) return board;

  const [task] = fromList.splice(index, 1);
  toList.splice(toIndex, 0, task);

  return next;
}

export default function App() {
  const [board, setBoard] = useState<BoardState | null>(null);
  const [activeTask, setActiveTask] = useState<Task | null>(null);
  const [connected, setConnected] = useState(false);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then((r) => r.json())
      .then(setBoard)
      .catch(console.error);
  }, []);

  useEffect(() => {
    const ws = new WebSocket(API_URL.replace("http", "ws"));

    ws.onopen = () => setConnected(true);
    ws.onclose = () => setConnected(false);
    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.type === "board:update") {
        setBoard(msg.payload);
      }
    };

    return () => ws.close();
  }, []);

  const boardColumns = useMemo(() => columns, []);

  async function syncMove(taskId: string, fromColumn: ColumnId, toColumn: ColumnId, toIndex: number) {
    await fetch(`${API_URL}/api/board/move`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ taskId, fromColumn, toColumn, toIndex })
    });
  }

  function onDragStart(event: DragStartEvent) {
    const taskId = String(event.active.id);
    if (!board) return;
    const col = findColumnOfTask(board, taskId);
    if (!col) return;
    const task = board.columns[col].find((t) => t.id === taskId) ?? null;
    setActiveTask(task);
  }

  function onDragOver(_event: DragOverEvent) {
    // reserved for live preview in future
  }

  async function onDragEnd(event: DragEndEvent) {
    setActiveTask(null);
    if (!board) return;

    const taskId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!overId) return;

    const fromColumn = findColumnOfTask(board, taskId);
    if (!fromColumn) return;

    const toColumn = (columns.some((c) => c.id === overId) ? overId : findColumnOfTask(board, overId)) as
      | ColumnId
      | null;

    if (!toColumn) return;

    const targetTasks = board.columns[toColumn];
    const overTaskIndex = targetTasks.findIndex((t) => t.id === overId);
    const toIndex = overTaskIndex >= 0 ? overTaskIndex : targetTasks.length;

    const next = moveTask(board, taskId, fromColumn, toColumn, toIndex);
    setBoard(next);
    await syncMove(taskId, fromColumn, toColumn, toIndex);
  }

  async function addTask(columnId: ColumnId) {
    const title = prompt("Task title?");
    if (!title) return;

    await fetch(`${API_URL}/api/board/task`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ columnId, title })
    });
  }

  async function resetBoard() {
    const ws = new WebSocket(API_URL.replace("http", "ws"));
    ws.onopen = () => {
      ws.send(JSON.stringify({ type: "board:reset" }));
      ws.close();
    };
  }

  if (!board) return <div className="app">Loading board…</div>;

  return (
    <div className="app">
      <header className="topbar">
        <div>
          <h1>Project Manager</h1>
          <p className={connected ? "status ok" : "status bad"}>
            {connected ? "Connected" : "Disconnected"}
          </p>
        </div>
        <button onClick={resetBoard}>Reset Board</button>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragStart={onDragStart} onDragOver={onDragOver} onDragEnd={onDragEnd}>
        <main className="board">
          {boardColumns.map((column) => (
            <section className="column" key={column.id} id={column.id}>
              <div className="column-header">
                <h2>{column.title}</h2>
                <button onClick={() => addTask(column.id)}>+ Add</button>
              </div>

              <div className="task-list" id={column.id}>
                {board.columns[column.id].map((task) => (
                  <TaskCard key={task.id} task={task} />
                ))}
              </div>
            </section>
          ))}
        </main>
      </DndContext>

      {activeTask && (
        <div className="drag-preview">
          <strong>{activeTask.title}</strong>
        </div>
      )}
    </div>
  );
}

function TaskCard({ task }: { task: Task }) {
  return (
    <div className="task-card" data-task-id={task.id}>
      <strong>{task.title}</strong>
      {task.description ? <p>{task.description}</p> : null}
    </div>
  );
}
```

