```tsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  DragOverEvent,
  DragStartEvent,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { SortableContext, arrayMove, useSortable, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { AppState, Task, Board } from "./types";

const socket = io("http://localhost:4000");

const createId = () => Math.random().toString(36).slice(2, 10);

function findBoardIndex(state: AppState, taskId: string) {
  return state.boards.findIndex((board) => board.taskIds.includes(taskId));
}

function moveTask(state: AppState, taskId: string, overId: string): AppState {
  const activeBoardIndex = findBoardIndex(state, taskId);
  const overBoardIndex = state.boards.findIndex((board) => board.id === overId || board.taskIds.includes(overId));

  if (activeBoardIndex === -1 || overBoardIndex === -1) return state;

  const nextBoards = structuredClone(state.boards);
  const sourceBoard = nextBoards[activeBoardIndex];
  const targetBoard = nextBoards[overBoardIndex];

  sourceBoard.taskIds = sourceBoard.taskIds.filter((id) => id !== taskId);

  const overTaskIndex = targetBoard.taskIds.findIndex((id) => id === overId);
  if (overTaskIndex >= 0 && overId !== targetBoard.id) {
    targetBoard.taskIds.splice(overTaskIndex, 0, taskId);
  } else {
    targetBoard.taskIds.push(taskId);
  }

  return { ...state, boards: nextBoards };
}

function BoardColumn({
  board,
  tasks,
  onAddTask
}: {
  board: Board;
  tasks: Task[];
  onAddTask: (boardId: string) => void;
}) {
  return (
    <div className="board">
      <div className="board-header">
        <h2>{board.title}</h2>
        <button onClick={() => onAddTask(board.id)}>+ Task</button>
      </div>

      <div className="task-list">
        <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </SortableContext>
      </div>
    </div>
  );
}

function TaskCard({ task }: { task: Task }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <strong>{task.title}</strong>
      {task.description ? <p>{task.description}</p> : null}
    </div>
  );
}

export default function App() {
  const [state, setState] = useState<AppState | null>(null);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  useEffect(() => {
    socket.on("state:init", (initial: AppState) => setState(initial));
    socket.on("state:updated", (next: AppState) => setState(next));

    return () => {
      socket.off("state:init");
      socket.off("state:updated");
    };
  }, []);

  const activeTask = useMemo(() => {
    if (!state || !activeTaskId) return null;
    return state.tasks[activeTaskId] ?? null;
  }, [state, activeTaskId]);

  const updateState = (next: AppState) => {
    setState(next);
    socket.emit("state:update", next);
  };

  const onDragStart = (event: DragStartEvent) => {
    setActiveTaskId(String(event.active.id));
  };

  const onDragOver = (event: DragOverEvent) => {
    if (!state) return;
    const { active, over } = event;
    if (!over) return;

    const activeId = String(active.id);
    const overId = String(over.id);
    if (activeId === overId) return;

    const activeBoardIndex = findBoardIndex(state, activeId);
    const overBoardIndex = state.boards.findIndex(
      (board) => board.id === overId || board.taskIds.includes(overId)
    );

    if (activeBoardIndex === -1 || overBoardIndex === -1 || activeBoardIndex === overBoardIndex) return;

    const next = structuredClone(state);
    next.boards[activeBoardIndex].taskIds = next.boards[activeBoardIndex].taskIds.filter((id) => id !== activeId);
    next.boards[overBoardIndex].taskIds.push(activeId);
    updateState(next);
  };

  const onDragEnd = (event: DragEndEvent) => {
    if (!state) return;
    const { active, over } = event;
    setActiveTaskId(null);
    if (!over) return;

    const activeId = String(active.id);
    const overId = String(over.id);
    if (activeId === overId) return;

    const next = moveTask(state, activeId, overId);
    updateState(next);
  };

  const onAddTask = (boardId: string) => {
    if (!state) return;
    const newTaskId = `task-${createId()}`;
    const newTask: Task = {
      id: newTaskId,
      title: "New task",
      description: "Click to edit later"
    };

    const next: AppState = {
      ...state,
      tasks: { ...state.tasks, [newTaskId]: newTask },
      boards: state.boards.map((board) =>
        board.id === boardId ? { ...board, taskIds: [...board.taskIds, newTaskId] } : board
      )
    };

    updateState(next);
  };

  if (!state) return <div className="app-shell">Loading...</div>;

  return (
    <div className="app-shell">
      <header className="topbar">
        <h1>Project Management</h1>
        <span className="connection">Real-time sync enabled</span>
      </header>

      <DndContext sensors={sensors} onDragStart={onDragStart} onDragOver={onDragOver} onDragEnd={onDragEnd}>
        <div className="boards">
          {state.boards.map((board) => (
            <BoardColumn
              key={board.id}
              board={board}
              tasks={board.taskIds.map((id) => state.tasks[id]).filter(Boolean)}
              onAddTask={onAddTask}
            />
          ))}
        </div>

        <DragOverlay>
          {activeTask ? (
            <div className="task-card dragging">
              <strong>{activeTask.title}</strong>
              {activeTask.description ? <p>{activeTask.description}</p> : null}
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

