### `server/src/types.ts`

```ts
export type Task = {
  id: string;
  title: string;
  description?: string;
  columnId: string;
  order: number;
  createdAt: string;
  updatedAt: string;
};

export type Column = {
  id: string;
  title: string;
  order: number;
};

export type BoardState = {
  columns: Column[];
  tasks: Task[];
};

export type MoveTaskPayload = {
  taskId: string;
  fromColumnId: string;
  toColumnId: string;
  toIndex: number;
};

export type CreateTaskPayload = {
  title: string;
  description?: string;
  columnId: string;
};
