### `server/src/store.ts`

```ts
import { randomUUID } from "crypto";
import { BoardState, CreateTaskPayload, MoveTaskPayload, Task, Column } from "./types";

let state: BoardState = {
  columns: [
    { id: randomUUID(), title: "Backlog", order: 0 },
    { id: randomUUID(), title: "In Progress", order: 1 },
    { id: randomUUID(), title: "Done", order: 2 }
  ],
  tasks: [
    {
      id: randomUUID(),
      title: "Set up project",
      description: "Initialize frontend and backend",
      columnId: "", // assigned below
      order: 0,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    }
  ]
};

state.tasks[0].columnId = state.columns[0].id;

export function getBoardState() {
  return state;
}

export function createTask(payload: CreateTaskPayload): Task {
  const now = new Date().toISOString();
  const tasksInColumn = state.tasks
    .filter(t => t.columnId === payload.columnId)
    .sort((a, b) => a.order - b.order);

  const task: Task = {
    id: randomUUID(),
    title: payload.title,
    description: payload.description,
    columnId: payload.columnId,
    order: tasksInColumn.length,
    createdAt: now,
    updatedAt: now
  };

  state.tasks.push(task);
  return task;
}

export function moveTask(payload: MoveTaskPayload) {
  const task = state.tasks.find(t => t.id === payload.taskId);
  if (!task) throw new Error("Task not found");

  task.columnId = payload.toColumnId;
  task.updatedAt = new Date().toISOString();

  const targetTasks = state.tasks
    .filter(t => t.columnId === payload.toColumnId && t.id !== task.id)
    .sort((a, b) => a.order - b.order);

  targetTasks.splice(payload.toIndex, 0, task);

  targetTasks.forEach((t, index) => {
    t.order = index;
  });

  const sourceColumnTasks = state.tasks
    .filter(t => t.columnId === payload.fromColumnId && t.id !== task.id)
    .sort((a, b) => a.order - b.order);

  sourceColumnTasks.forEach((t, index) => {
    t.order = index;
  });
}

export function addColumn(title: string): Column {
  const column: Column = {
    id: randomUUID(),
    title,
    order: state.columns.length
  };
  state.columns.push(column);
  return column;
}
```

### `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { addColumn, createTask, getBoardState, moveTask } from "./store";

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST"]
  }
});

app.use(cors());
app.use(express.json());

app.get("/api/board", (_req, res) => {
  res.json(getBoardState());
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId } = req.body;
  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const task = createTask({ title, description, columnId });
  io.emit("board:updated", getBoardState());
  res.status(201).json(task);
});

app.post("/api/columns", (req, res) => {
  const { title } = req.body;
  if (!title) {
    return res.status(400).json({ error: "title is required" });
  }

  const column = addColumn(title);
  io.emit("board:updated", getBoardState());
  res.status(201).json(column);
});

app.post("/api/tasks/move", (req, res) => {
  try {
    moveTask(req.body);
    io.emit("board:updated", getBoardState());
    res.json({ ok: true });
  } catch (error: any) {
    res.status(400).json({ error: error.message });
  }
});

io.on("connection", (socket) => {
  socket.emit("board:updated", getBoardState());

  socket.on("board:request", () => {
    socket.emit("board:updated", getBoardState());
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
