          .sort((a, b) => a.order - b.order)
          .map((task, index) => (
            <div
              key={task.id}
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => {
                e.preventDefault();
                if (draggedTask) {
                  onDropTask(draggedTask.taskId, draggedTask.columnId, id, index);
