### `client/src/App.tsx`

```tsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { socket } from "./socket";
import { Board } from "./components/Board";
import "./styles.css";

type Column = {
  id: string;
  title: string;
  order: number;
};

type Task = {
  id: string;
  title: string;
  description?: string;
  columnId: string;
  order: number;
};

type BoardState = {
  columns: Column[];
  tasks: Task[];
};

export default function App() {
  const [board, setBoard] = useState<BoardState>({ columns: [], tasks: [] });
  const [draggedTask, setDraggedTask] = useState<{ taskId: string; columnId: string } | null>(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");

  useEffect(() => {
    api.get("/board").then((res) => setBoard(res.data));
    socket.on("board:updated", (data) => setBoard(data));
    return () => {
      socket.off("board:updated");
    };
  }, []);

  const handleDropTask = async (
    taskId: string,
    fromColumnId: string,
    toColumnId: string,
    toIndex: number
  ) => {
    await api.post("/tasks/move", { taskId, fromColumnId, toColumnId, toIndex });
    setDraggedTask(null);
  };

  const handleCreateTask = async () => {
    const firstColumn = board.columns[0];
    if (!firstColumn || !newTaskTitle.trim()) return;

    await api.post("/tasks", {
      title: newTaskTitle,
      columnId: firstColumn.id
    });

    setNewTaskTitle("");
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <div className="controls">
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <button onClick={handleCreateTask}>Add Task</button>
        </div>
      </header>

      <Board
        columns={board.columns}
        tasks={board.tasks}
        draggedTask={draggedTask}
        onDragStart={(taskId, columnId) => setDraggedTask({ taskId, columnId })}
        onDropTask={handleDropTask}
      />
    </div>
  );
}
```

