### `client/src/store/boardStore.ts`
```ts
import { create } from "zustand";

export type Task = {
  id: string;
  title: string;
  description?: string;
};

export type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

type BoardState = {
  tasks: Record<string, Task>;
  columns: Record<string, Column>;
  columnOrder: string[];
  setBoard: (board: Pick<BoardState, "tasks" | "columns" | "columnOrder">) => void;
  moveTask: (taskId: string, sourceColumnId: string, destColumnId: string, destIndex: number) => void;
  addTask: (columnId: string, title: string) => void;
  updateTask: (taskId: string, updates: Partial<Task>) => void;
  deleteTask: (taskId: string) => void;
};

export const useBoardStore = create<BoardState>((set, get) => ({
  tasks: {},
  columns: {},
  columnOrder: [],

  setBoard: ({ tasks, columns, columnOrder }) => set({ tasks, columns, columnOrder }),

  moveTask: (taskId, sourceColumnId, destColumnId, destIndex) =>
    set((state) => {
      const source = state.columns[sourceColumnId];
      const dest = state.columns[destColumnId];
      if (!source || !dest) return state;

      const sourceTaskIds = [...source.taskIds].filter((id) => id !== taskId);
      const destTaskIds = [...dest.taskIds];

      destTaskIds.splice(destIndex, 0, taskId);

      return {
        columns: {
          ...state.columns,
          [sourceColumnId]: { ...source, taskIds: sourceTaskIds },
          [destColumnId]: { ...dest, taskIds: destTaskIds },
        },
      };
    }),

  addTask: (columnId, title) =>
    set((state) => {
      const id = crypto.randomUUID();
      const column = state.columns[columnId];
      if (!column) return state;

      return {
        tasks: {
          ...state.tasks,
          [id]: { id, title },
        },
        columns: {
          ...state.columns,
          [columnId]: {
            ...column,
            taskIds: [...column.taskIds, id],
          },
        },
      };
    }),

  updateTask: (taskId, updates) =>
    set((state) => ({
      tasks: {
        ...state.tasks,
        [taskId]: {
          ...state.tasks[taskId],
          ...updates,
        },
      },
    })),

  deleteTask: (taskId) =>
    set((state) => {
      const newTasks = { ...state.tasks };
      delete newTasks[taskId];

      const newColumns = Object.fromEntries(
        Object.entries(state.columns).map(([colId, col]) => [
          colId,
          { ...col, taskIds: col.taskIds.filter((id) => id !== taskId) },
        ])
      );

      return { tasks: newTasks, columns: newColumns };
    }),
}));
```

