import { DndContext, DragEndEvent, closestCorners } from "@dnd-kit/core";
import { useBoardStore } from "../store/boardStore";
import { Column } from "./Column";

export function Board() {
  const { tasks, columns, columnOrder, moveTask } = useBoardStore();

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const destColumnId = String(over.id);

    const sourceColumnId = Object.values(columns).find((col) =>
      col.taskIds.includes(taskId)
    )?.id;

    if (!sourceColumnId) return;

    const destIndex = columns[destColumnId]?.taskIds.length ?? 0;
    moveTask(taskId, sourceColumnId, destColumnId, destIndex);
  };

  return (
    <DndContext collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
      <div style={{ display: "flex", gap: 16, padding: 16, overflowX: "auto" }}>
        {columnOrder.map((columnId) => {
          const column = columns[columnId];
          return (
            <Column
              key={columnId}
              column={column}
              tasks={column.taskIds.map((id) => tasks[id]).filter(Boolean)}
            />
          );
        })}
      </div>
    </DndContext>
  );
}
