import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
app.use(cors({ origin: "*" }));
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: { origin: "*" },
});

type Board = {
  tasks: Record<string, { id: string; title: string; description?: string }>;
  columns: Record<string, { id: string; title: string; taskIds: string[] }>;
  columnOrder: string[];
};

const boards: Record<string, Board> = {
  "demo-board": {
    tasks: {
      "task-1": { id: "task-1", title: "Set up project" },
      "task-2": { id: "task-2", title: "Build task board" },
    },
    columns: {
      todo: { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
      doing: { id: "doing", title: "In Progress", taskIds: [] },
      done: { id: "done", title: "Done", taskIds: [] },
    },
    columnOrder: ["todo", "doing", "done"],
  },
};

io.on("connection", (socket) => {
  socket.on("board:join", ({ boardId }) => {
    socket.join(boardId);
    socket.emit("board:init", boards[boardId]);
  });

  socket.on("board:moveTask", ({ boardId, board }) => {
    boards[boardId] = board;
    io.to(boardId).emit("board:update", board);
  });
});

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

server.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
```

