import { BoardState, Task, TaskStatus } from "./types";

class InMemoryStore {
  private state: BoardState = {
    tasks: [
      {
        id: "1",
        title: "Set up project",
        description: "Initialize frontend and backend",
        status: "todo",
        order: 0,
        updatedAt: Date.now(),
      },
      {
        id: "2",
        title: "Create task board",
        description: "Build draggable kanban columns",
        status: "inprogress",
        order: 0,
        updatedAt: Date.now(),
      },
      {
        id: "3",
        title: "Add realtime sync",
        description: "Broadcast updates with Socket.IO",
        status: "done",
        order: 0,
        updatedAt: Date.now(),
      },
    ],
  };

  getState(): BoardState {
    return this.state;
  }

  addTask(task: Omit<Task, "id" | "updatedAt">): Task {
    const newTask: Task = {
      ...task,
      id: crypto.randomUUID(),
      updatedAt: Date.now(),
    };
    this.state.tasks.push(newTask);
    return newTask;
  }

  updateTask(taskId: string, updates: Partial<Task>): Task | null {
    const task = this.state.tasks.find((t) => t.id === taskId);
    if (!task) return null;

    Object.assign(task, updates);
    task.updatedAt = Date.now();
    return task;
  }

  moveTask(taskId: string, status: TaskStatus, order: number): Task | null {
    const task = this.state.tasks.find((t) => t.id === taskId);
    if (!task) return null;

    task.status = status;
    task.order = order;
    task.updatedAt = Date.now();
    return task;
  }
}

export const store = new InMemoryStore();
```

### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { store } from "./store";
import { TaskStatus } from "./types";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PATCH"],
  },
});

app.get("/api/board", (_req, res) => {
  res.json(store.getState());
});

app.post("/api/tasks", (req, res) => {
  const { title, description, status = "todo" } = req.body;

  if (!title) {
    return res.status(400).json({ error: "Task title is required" });
  }

  const task = store.addTask({
    title,
    description,
    status,
    order: 0,
  });

  io.emit("task:created", task);
  res.status(201).json(task);
});

app.patch("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const updated = store.updateTask(id, req.body);

  if (!updated) {
    return res.status(404).json({ error: "Task not found" });
  }

  io.emit("task:updated", updated);
  res.json(updated);
});

app.post("/api/tasks/:id/move", (req, res) => {
  const { id } = req.params;
  const { status, order } = req.body as { status: TaskStatus; order: number };

  if (!status && status !== "todo") {
    return res.status(400).json({ error: "status is required" });
  }

  const updated = store.moveTask(id, status, order ?? 0);

  if (!updated) {
    return res.status(404).json({ error: "Task not found" });
  }

  io.emit("task:moved", updated);
  res.json(updated);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:state", store.getState());

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

