### `client/src/App.tsx`
```tsx
import { useEffect, useMemo, useState } from "react";
import { DragEndEvent } from "@dnd-kit/core";
import { Board } from "./components/Board";
import { BoardState, Task, TaskStatus } from "./types";
import { fetchBoard, createTask, moveTask } from "./api";
import { socket } from "./socket";

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [title, setTitle] = useState("");

  useEffect(() => {
    fetchBoard().then((state: BoardState) => setTasks(state.tasks));
  }, []);

  useEffect(() => {
    socket.on("board:state", (state: BoardState) => setTasks(state.tasks));
    socket.on("task:created", (task: Task) => setTasks((prev) => [...prev, task]));
    socket.on("task:updated", (task: Task) =>
      setTasks((prev) => prev.map((t) => (t.id === task.id ? task : t)))
    );
    socket.on("task:moved", (task: Task) =>
      setTasks((prev) => prev.map((t) => (t.id === task.id ? task : t)))
    );

    return () => {
      socket.off("board:state");
      socket.off("task:created");
      socket.off("task:updated");
      socket.off("task:moved");
    };
  }, []);

  const groupedTasks = useMemo(() => tasks, [tasks]);

  const handleAddTask = async () => {
    if (!title.trim()) return;
    await createTask({ title, status: "todo" });
    setTitle("");
  };

  const handleDragEnd = async (event: DragEndEvent) => {
    const taskId = String(event.active.id);
    const overId = event.over?.id as TaskStatus | undefined;
    if (!overId) return;

    await moveTask(taskId, overId, 0);
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Management Board</h1>
        <div className="new-task">
          <input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="New task title"
          />
          <button onClick={handleAddTask}>Add Task</button>
        </div>
      </header>

      <Board tasks={groupedTasks} onDragEnd={handleDragEnd} />
    </div>
  );
}
```

