import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for initial implementation
let boards = {
  "board-1": {
    id: "board-1",
    name: "Main Board",
    columns: [
      { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
      { id: "doing", title: "In Progress", taskIds: ["task-3"] },
      { id: "done", title: "Done", taskIds: [] }
    ],
    tasks: {
      "task-1": { id: "task-1", title: "Design app layout", description: "Create wireframes and structure." },
      "task-2": { id: "task-2", title: "Set up backend", description: "Initialize Express and Socket.IO." },
      "task-3": { id: "task-3", title: "Build drag and drop", description: "Implement task movement." }
    }
  }
};

app.get("/api/boards/:boardId", (req, res) => {
  const board = boards[req.params.boardId];
  if (!board) return res.status(404).json({ error: "Board not found" });
  res.json(board);
});

app.post("/api/boards/:boardId/tasks", (req, res) => {
  const board = boards[req.params.boardId];
  if (!board) return res.status(404).json({ error: "Board not found" });

  const { title, description = "", columnId = "todo" } = req.body;
  const taskId = `task-${Date.now()}`;

  const task = { id: taskId, title, description };
  board.tasks[taskId] = task;
  const column = board.columns.find(c => c.id === columnId);
  if (!column) return res.status(400).json({ error: "Invalid column" });

  column.taskIds.push(taskId);

  io.emit("boardUpdated", board);
  res.status(201).json(task);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.on("joinBoard", (boardId) => {
    socket.join(boardId);
    const board = boards[boardId];
    if (board) socket.emit("boardUpdated", board);
  });

  socket.on("moveTask", ({ boardId, taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const board = boards[boardId];
    if (!board) return;

    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = board.columns.find(c => c.id === destinationColumnId);
    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.to(boardId).emit("boardUpdated", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

