## `server/index.js`

```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory initial data
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Design project layout", description: "Create initial UI structure" },
        { id: "task-2", title: "Set up database", description: "Pick persistence layer" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Implement drag-and-drop", description: "Use HTML5 drag events" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", title: "Initialize repository", description: "Create project skeleton" }
      ]
    }
  ]
};

function findTask(taskId) {
  for (const column of board.columns) {
    const index = column.tasks.findIndex(task => task.id === taskId);
    if (index !== -1) {
      return { column, index, task: column.tasks[index] };
    }
  }
  return null;
}

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, title, description } = req.body;

  const column = board.columns.find(c => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const task = {
    id: `task-${Date.now()}`,
    title: title || "Untitled Task",
    description: description || ""
  };

  column.tasks.push(task);
  io.emit("board:update", board);
  res.status(201).json(task);
});

app.post("/api/tasks/move", (req, res) => {
  const { taskId, toColumnId, toIndex } = req.body;

  const source = findTask(taskId);
  const destinationColumn = board.columns.find(c => c.id === toColumnId);

  if (!source || !destinationColumn) {
    return res.status(404).json({ error: "Task or destination column not found" });
  }

  source.column.tasks.splice(source.index, 1);

  const insertIndex = typeof toIndex === "number"
    ? Math.max(0, Math.min(toIndex, destinationColumn.tasks.length))
    : destinationColumn.tasks.length;

  destinationColumn.tasks.splice(insertIndex, 0, source.task);

  io.emit("board:update", board);
  res.json({ success: true });
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const source = findTask(taskId);

  if (!source) {
    return res.status(404).json({ error: "Task not found" });
  }

  source.column.tasks.splice(source.index, 1);
  io.emit("board:update", board);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("board:moveTask", ({ taskId, toColumnId, toIndex }) => {
    const source = findTask(taskId);
    const destinationColumn = board.columns.find(c => c.id === toColumnId);

    if (!source || !destinationColumn) return;

    source.column.tasks.splice(source.index, 1);

    const insertIndex = typeof toIndex === "number"
      ? Math.max(0, Math.min(toIndex, destinationColumn.tasks.length))
      : destinationColumn.tasks.length;

    destinationColumn.tasks.splice(insertIndex, 0, source.task);

    io.emit("board:update", board);
  });

  socket.on("board:addTask", ({ columnId, title, description }) => {
    const column = board.columns.find(c => c.id === columnId);
    if (!column) return;

    const task = {
      id: `task-${Date.now()}`,
      title: title || "Untitled Task",
      description: description || ""
    };

    column.tasks.push(task);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

