## `client/app.js`

```js
const API_BASE = "http://localhost:3001";
const socket = io(API_BASE);

const boardEl = document.getElementById("board");
const taskTemplate = document.getElementById("taskTemplate");
const columnSelect = document.getElementById("columnSelect");
const addTaskButton = document.getElementById("addTaskButton");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");

let currentBoard = null;
let draggedTaskId = null;

async function loadBoard() {
  const res = await fetch(`${API_BASE}/api/board`);
  currentBoard = await res.json();
  renderBoard(currentBoard);
}

function renderBoard(board) {
  boardEl.innerHTML = "";
  columnSelect.innerHTML = "";

  board.columns.forEach((column) => {
    // Render select options for adding tasks
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    columnSelect.appendChild(option);

    // Column container
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const header = document.createElement("div");
    header.className = "column__header";

    const title = document.createElement("h2");
    title.className = "column__title";
    title.textContent = column.title;

    const count = document.createElement("span");
    count.className = "column__count";
    count.textContent = `${column.tasks.length} tasks`;

    header.appendChild(title);
    header.appendChild(count);

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTaskId) return;

      const toIndex = getDropIndex(taskList, e.clientY);
      socket.emit("board:moveTask", {
        taskId: draggedTaskId,
        toColumnId: column.id,
        toIndex
      });

      draggedTaskId = null;
    });

    column.tasks.forEach((task) => {
      const taskNode = createTaskNode(task, column.id);
      taskList.appendChild(taskNode);
    });

    columnEl.appendChild(header);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

function createTaskNode(task, columnId) {
  const node = taskTemplate.content.cloneNode(true);
  const taskCard = node.querySelector(".task-card");
  const title = node.querySelector(".task-card__title");
  const description = node.querySelector(".task-card__description");
  const deleteButton = node.querySelector(".task-card__delete");

  taskCard.dataset.taskId = task.id;
  taskCard.draggable = true;

  title.textContent = task.title;
  description.textContent = task.description;

  taskCard.addEventListener("dragstart", () => {
    draggedTaskId = task.id;
    taskCard.classList.add("dragging");
  });

  taskCard.addEventListener("dragend", () => {
    taskCard.classList.remove("dragging");
    draggedTaskId = null;
  });

  deleteButton.addEventListener("click", async () => {
    await fetch(`${API_BASE}/api/tasks/${task.id}`, {
      method: "DELETE"
    });
  });

  return taskCard;
}

function getDropIndex(taskList, clientY) {
  const cards = [...taskList.querySelectorAll(".task-card:not(.dragging)")];

  let closest = { offset: Number.NEGATIVE_INFINITY, index: cards.length };

  cards.forEach((card, index) => {
    const rect = card.getBoundingClientRect();
    const offset = clientY - rect.top - rect.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

addTaskButton.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = columnSelect.value;

  if (!columnId) return;

  socket.emit("board:addTask", {
    columnId,
    title,
    description
  });

  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
});

socket.on("board:update", (board) => {
  currentBoard = board;
  renderBoard(board);
});

loadBoard().catch(console.error);
```

