## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");
const crypto = require("crypto");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

let board = [
  {
    id: "todo",
    title: "To Do",
    tasks: [
      { id: crypto.randomUUID(), title: "Set up project", description: "Initialize app structure", assignee: "Alex" },
      { id: crypto.randomUUID(), title: "Design board UI", description: "Create initial layout", assignee: "Sam" }
    ]
  },
  {
    id: "inprogress",
    title: "In Progress",
    tasks: [
      { id: crypto.randomUUID(), title: "Implement drag-and-drop", description: "Move cards across columns", assignee: "Taylor" }
    ]
  },
  {
    id: "done",
    title: "Done",
    tasks: [
      { id: crypto.randomUUID(), title: "Create repository", description: "Project repo created", assignee: "Jordan" }
    ]
  }
];

function broadcast(message) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

// REST endpoint for initial state
app.get("/api/board", (req, res) => {
  res.json(board);
});

// Add task
app.post("/api/tasks", (req, res) => {
  const { columnId, title, description, assignee } = req.body;
  if (!columnId || !title) {
    return res.status(400).json({ error: "columnId and title are required" });
  }

  const column = board.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  const task = {
    id: crypto.randomUUID(),
    title,
    description: description || "",
    assignee: assignee || ""
  };

  column.tasks.push(task);
  broadcast({ type: "task-created", payload: { columnId, task } });

  res.status(201).json(task);
});

// Move task
app.post("/api/move-task", (req, res) => {
  const { taskId, fromColumnId, toColumnId, toIndex } = req.body;

  const fromColumn = board.find((c) => c.id === fromColumnId);
  const toColumn = board.find((c) => c.id === toColumnId);

  if (!fromColumn || !toColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) {
    return res.status(404).json({ error: "Task not found" });
  }

  const [task] = fromColumn.tasks.splice(taskIndex, 1);
  const insertIndex = Number.isInteger(toIndex) ? toIndex : toColumn.tasks.length;
  toColumn.tasks.splice(insertIndex, 0, task);

  broadcast({
    type: "task-moved",
    payload: { taskId, fromColumnId, toColumnId, toIndex: insertIndex }
  });

  res.json({ success: true });
});

wss.on("connection", (ws) => {
  // Send current board state to new clients
  ws.send(JSON.stringify({ type: "board-state", payload: board }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      // Example: live cursor/typing/selection messages can be handled here later
      if (data.type === "ping") {
        ws.send(JSON.stringify({ type: "pong" }));
      }
    } catch (err) {
      console.error("WebSocket message error:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

