## 5) `public/app.js`

```js
let boardData = [];
let draggedTask = null;
let draggedFromColumnId = null;

const boardEl = document.getElementById("board");
const columnSelect = document.getElementById("columnSelect");
const taskForm = document.getElementById("taskForm");
const connectionStatus = document.getElementById("connectionStatus");

const columnTemplate = document.getElementById("columnTemplate");
const taskTemplate = document.getElementById("taskTemplate");

function renderBoard() {
  boardEl.innerHTML = "";
  columnSelect.innerHTML = "";

  boardData.forEach((column) => {
    const columnNode = columnTemplate.content.cloneNode(true);
    const columnEl = columnNode.querySelector(".column");
    const titleEl = columnNode.querySelector("h3");
    const countEl = columnNode.querySelector(".task-count");
    const taskListEl = columnNode.querySelector(".task-list");

    columnEl.dataset.columnId = column.id;
    titleEl.textContent = column.title;
    countEl.textContent = `${column.tasks.length} tasks`;

    column.tasks.forEach((task, index) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;
      taskEl.dataset.index = index;

      taskNode.querySelector(".task-title").textContent = task.title;
      taskNode.querySelector(".task-description").textContent = task.description || "";
      taskNode.querySelector(".task-meta").textContent = task.assignee ? `Assignee: ${task.assignee}` : "Unassigned";

      taskEl.addEventListener("dragstart", onDragStart);
      taskEl.addEventListener("dragend", onDragEnd);

      taskListEl.appendChild(taskNode);
    });

    taskListEl.addEventListener("dragover", onDragOver);
    taskListEl.addEventListener("drop", onDrop);
    columnEl.addEventListener("dragenter", () => columnEl.classList.add("drag-over"));
    columnEl.addEventListener("dragleave", () => columnEl.classList.remove("drag-over"));
    columnEl.addEventListener("drop", () => columnEl.classList.remove("drag-over"));

    boardEl.appendChild(columnNode);

    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    columnSelect.appendChild(option);
  });
}

function onDragStart(e) {
  draggedTask = {
    taskId: e.currentTarget.dataset.taskId,
    fromColumnId: e.currentTarget.dataset.columnId
  };
  e.currentTarget.classList.add("dragging");
  e.dataTransfer.setData("text/plain", JSON.stringify(draggedTask));
}

function onDragEnd(e) {
  e.currentTarget.classList.remove("dragging");
  document.querySelectorAll(".column").forEach((c) => c.classList.remove("drag-over"));
}

function onDragOver(e) {
  e.preventDefault();
}

async function onDrop(e) {
  e.preventDefault();

  const columnEl = e.currentTarget.closest(".column");
  const toColumnId = columnEl.dataset.columnId;
  const toColumn = boardData.find((c) => c.id === toColumnId);

  if (!draggedTask) return;

  const data = JSON.parse(e.dataTransfer.getData("text/plain") || "{}");
  const taskId = data.taskId || draggedTask.taskId;
  const fromColumnId = data.fromColumnId || draggedTask.fromColumnId;

  // Determine index based on current board state
  const taskList = Array.from(e.currentTarget.querySelectorAll(".task"));
  const targetTaskEl = e.target.closest(".task");

  let toIndex = toColumn.tasks.length;
  if (targetTaskEl) {
    const targetTaskId = targetTaskEl.dataset.taskId;
    const targetIndex = toColumn.tasks.findIndex((t) => t.id === targetTaskId);
    if (targetIndex !== -1) toIndex = targetIndex;
  } else if (taskList.length > 0) {
    toIndex = toColumn.tasks.length;
  }

  await fetch("/api/move-task", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ taskId, fromColumnId, toColumnId, toIndex })
  });

  draggedTask = null;
}

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const title = document.getElementById("taskTitle").value.trim();
  const description = document.getElementById("taskDescription").value.trim();
  const assignee = document.getElementById("taskAssignee").value.trim();
  const columnId = columnSelect.value;

  if (!title || !columnId) return;

  await fetch("/api/tasks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ title, description, assignee, columnId })
  });

  taskForm.reset();
  columnSelect.value = columnId;
});

async function loadBoard() {
  const res = await fetch("/api/board");
  boardData = await res.json();
  renderBoard();
}

function connectWebSocket() {
  const wsProtocol = window.location.protocol === "https:" ? "wss" : "ws";
  const ws = new WebSocket(`${wsProtocol}://${window.location.host}`);

  ws.addEventListener("open", () => {
    connectionStatus.textContent = "Connected";
  });

  ws.addEventListener("close", () => {
    connectionStatus.textContent = "Disconnected. Reconnecting...";
    setTimeout(connectWebSocket, 1500);
  });

  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);

    if (message.type === "board-state") {
      boardData = message.payload;
      renderBoard();
    }

    if (message.type === "task-created") {
      loadBoard();
    }

    if (message.type === "task-moved") {
      loadBoard();
    }
  });
}

loadBoard();
connectWebSocket();
```

