## `server/index.js`

```js
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";

const app = express();
const httpServer = createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(httpServer, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for initial implementation
const boards = {
  default: {
    id: "default",
    name: "Team Board",
    columns: [
      {
        id: "todo",
        title: "To Do",
        tasks: [
          { id: "task-1", title: "Design landing page", description: "Wireframe the homepage", updatedAt: Date.now() },
          { id: "task-2", title: "Set up auth", description: "Implement login flow", updatedAt: Date.now() }
        ]
      },
      {
        id: "doing",
        title: "In Progress",
        tasks: [
          { id: "task-3", title: "Build API", description: "Create REST endpoints", updatedAt: Date.now() }
        ]
      },
      {
        id: "done",
        title: "Done",
        tasks: []
      }
    ]
  }
};

function getBoard(boardId = "default") {
  return boards[boardId];
}

app.get("/api/boards/:boardId", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });
  res.json(board);
});

app.post("/api/boards/:boardId/tasks", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const { columnId, title, description = "" } = req.body;
  const column = board.columns.find((c) => c.id === columnId);
  if (!column) return res.status(400).json({ error: "Invalid column" });

  const task = {
    id: `task-${crypto.randomUUID()}`,
    title,
    description,
    updatedAt: Date.now()
  };

  column.tasks.push(task);
  io.emit("board:updated", board);
  res.status(201).json(task);
});

io.on("connection", (socket) => {
  socket.on("board:join", (boardId) => {
    socket.join(boardId);
    const board = getBoard(boardId);
    if (board) socket.emit("board:init", board);
  });

  socket.on("task:moved", ({ boardId, taskId, fromColumnId, toColumnId, toIndex }) => {
    const board = getBoard(boardId);
    if (!board) return;

    const fromColumn = board.columns.find((c) => c.id === fromColumnId);
    const toColumn = board.columns.find((c) => c.id === toColumnId);
    if (!fromColumn || !toColumn) return;

    const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromColumn.tasks.splice(taskIndex, 1);
    task.updatedAt = Date.now();

    const insertIndex = typeof toIndex === "number" ? toIndex : toColumn.tasks.length;
    toColumn.tasks.splice(insertIndex, 0, task);

    io.to(boardId).emit("board:updated", board);
  });

  socket.on("task:created", ({ boardId, columnId, title, description }) => {
    const board = getBoard(boardId);
    if (!board) return;

    const column = board.columns.find((c) => c.id === columnId);
    if (!column) return;

    const task = {
      id: `task-${crypto.randomUUID()}`,
      title,
      description: description || "",
      updatedAt: Date.now()
    };

    column.tasks.push(task);
    io.to(boardId).emit("board:updated", board);
  });

  socket.on("task:deleted", ({ boardId, taskId }) => {
    const board = getBoard(boardId);
    if (!board) return;

    for (const column of board.columns) {
      const idx = column.tasks.findIndex((t) => t.id === taskId);
      if (idx !== -1) {
        column.tasks.splice(idx, 1);
        io.to(boardId).emit("board:updated", board);
        return;
      }
    }
  });
});

const PORT = process.env.PORT || 3001;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

