# 5) Frontend: JavaScript

## `client/app.js`

```js
const socket = io("http://localhost:3001");
const boardId = "default";

const boardEl = document.getElementById("board");
const columnTemplate = document.getElementById("columnTemplate");
const taskTemplate = document.getElementById("taskTemplate");
const newTaskTitleEl = document.getElementById("newTaskTitle");
const addTaskBtn = document.getElementById("addTaskBtn");

let currentBoard = null;
let dragState = {
  taskId: null,
  fromColumnId: null
};

function renderBoard(board) {
  currentBoard = board;
  boardEl.innerHTML = "";

  board.columns.forEach((column) => {
    const columnNode = columnTemplate.content.cloneNode(true);
    const section = columnNode.querySelector(".column");
    const title = columnNode.querySelector(".column-title");
    const taskList = columnNode.querySelector(".task-list");

    title.textContent = column.title;
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      const toColumnId = taskList.dataset.columnId;
      const toIndex = column.tasks.length;

      if (dragState.taskId && dragState.fromColumnId && toColumnId) {
        socket.emit("task:moved", {
          boardId,
          taskId: dragState.taskId,
          fromColumnId: dragState.fromColumnId,
          toColumnId,
          toIndex
        });
      }

      dragState.taskId = null;
      dragState.fromColumnId = null;
    });

    column.tasks.forEach((task) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      const titleEl = taskNode.querySelector(".task-title");
      const descEl = taskNode.querySelector(".task-desc");
      const deleteBtn = taskNode.querySelector(".delete-task-btn");

      titleEl.textContent = task.title;
      descEl.textContent = task.description;

      taskEl.dataset.taskId = task.id;
      taskEl.addEventListener("dragstart", () => {
        dragState.taskId = task.id;
        dragState.fromColumnId = column.id;
      });

      deleteBtn.addEventListener("click", () => {
        socket.emit("task:deleted", { boardId, taskId: task.id });
      });

      taskList.appendChild(taskNode);
    });

    boardEl.appendChild(columnNode);
  });
}

addTaskBtn.addEventListener("click", () => {
  const title = newTaskTitleEl.value.trim();
  if (!title) return;

  socket.emit("task:created", {
    boardId,
    columnId: "todo",
    title,
    description: ""
  });

  newTaskTitleEl.value = "";
});

socket.on("connect", () => {
  socket.emit("board:join", boardId);
});

socket.on("board:init", (board) => {
  renderBoard(board);
});

socket.on("board:updated", (board) => {
  renderBoard(board);
});

// Fallback initial fetch
fetch(`http://localhost:3001/api/boards/${boardId}`)
  .then((res) => res.json())
  .then((board) => renderBoard(board))
  .catch((err) => console.error("Failed to fetch board:", err));
```

