      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Define requirements", description: "Collect stakeholder needs" },
    "task-2": { id: "task-2", title: "Set up project", description: "Initialize repo and tooling" },
    "task-3": { id: "task-3", title: "Build UI mockups", description: "Create basic wireframes" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board/reset", (req, res) => {
  boardState = {
    columns: [
      { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
      { id: "doing", title: "In Progress", taskIds: ["task-3"] },
      { id: "done", title: "Done", taskIds: [] }
    ],
    tasks: {
      "task-1": { id: "task-1", title: "Define requirements", description: "Collect stakeholder needs" },
      "task-2": { id: "task-2", title: "Set up project", description: "Initialize repo and tooling" },
      "task-3": { id: "task-3", title: "Build UI mockups", description: "Create basic wireframes" }
    }
  };

  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current board state to new client
  socket.emit("board:update", boardState);

  socket.on("task:moved", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = boardState.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = boardState.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;
    if (!boardState.tasks[taskId]) return;

    const sourceTaskIndex = sourceColumn.taskIds.indexOf(taskId);
    if (sourceTaskIndex === -1) return;

    // Remove from source
    sourceColumn.taskIds.splice(sourceTaskIndex, 1);

    // Insert into destination
    const insertIndex = Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length));
    destinationColumn.taskIds.splice(insertIndex, 0, taskId);

    // Broadcast updated board to all clients
    io.emit("board:update", boardState);
  });

  socket.on("task:created", ({ title, description }) => {
    const id = `task-${Date.now()}`;
    boardState.tasks[id] = { id, title, description };
    const todoColumn = boardState.columns.find((c) => c.id === "todo");
    todoColumn.taskIds.unshift(id);

    io.emit("board:update", boardState);
  });

  socket.on("task:updated", ({ taskId, title, description }) => {
    if (!boardState.tasks[taskId]) return;
    boardState.tasks[taskId] = { ...boardState.tasks[taskId], title, description };
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
