```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:4000");

function App() {
  const [board, setBoard] = useState(null);
  const [draggedTaskId, setDraggedTaskId] = useState(null);
  const [newTask, setNewTask] = useState({ title: "", description: "" });

  useEffect(() => {
    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    board.columns.forEach((column) => {
      result[column.id] = column.taskIds.map((taskId) => board.tasks[taskId]);
    });
    return result;
  }, [board]);

  const handleDragStart = (taskId) => {
    setDraggedTaskId(taskId);
  };

  const handleDrop = (destinationColumnId, destinationIndex) => {
    if (!draggedTaskId || !board) return;

    const sourceColumn = board.columns.find((column) =>
      column.taskIds.includes(draggedTaskId)
    );

    if (!sourceColumn) return;

    socket.emit("task:moved", {
      taskId: draggedTaskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId,
      destinationIndex
    });

    setDraggedTaskId(null);
  };

  const handleCreateTask = (e) => {
    e.preventDefault();
    if (!newTask.title.trim()) return;

    socket.emit("task:created", {
      title: newTask.title,
      description: newTask.description
    });

    setNewTask({ title: "", description: "" });
  };

  if (!board) {
    return <div className="app loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <form className="new-task-form" onSubmit={handleCreateTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTask.title}
            onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
          />
          <input
            type="text"
            placeholder="Description"
            value={newTask.description}
            onChange={(e) => setNewTask({ ...newTask, description: e.target.value })}
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {board.columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(column.id, column.taskIds.length)}
          >
            <h2>{column.title}</h2>

            <div className="task-list">
              {tasksByColumn[column.id].map((task, index) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={() => handleDragStart(task.id)}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={() => handleDrop(column.id, index)}
                >
                  <h3>{task.title}</h3>
                  <p>{task.description}</p>
                </div>
              ))}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}

export default App;
```

