### `client/src/App.tsx`
```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import {
  DndContext,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
} from "@dnd-kit/sortable";
import { BoardState, Task } from "./types";

const SOCKET_URL = "http://localhost:4000";

function moveTask(board: BoardState, taskId: string, fromColumnId: string, toColumnId: string, toIndex: number) {
  const source = board.columns[fromColumnId];
  const target = board.columns[toColumnId];

  const nextSourceTaskIds = [...source.taskIds];
  nextSourceTaskIds.splice(nextSourceTaskIds.indexOf(taskId), 1);

  const nextTargetTaskIds =
    fromColumnId === toColumnId
      ? arrayMove(target.taskIds, target.taskIds.indexOf(taskId), toIndex)
      : (() => {
          const ids = [...target.taskIds];
          ids.splice(toIndex, 0, taskId);
          return ids;
        })();

  return {
    ...board,
    columns: {
      ...board.columns,
      [fromColumnId]: {
        ...source,
        taskIds: fromColumnId === toColumnId ? nextTargetTaskIds : nextSourceTaskIds,
      },
      [toColumnId]: {
        ...target,
        taskIds: nextTargetTaskIds,
      },
    },
  };
}

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [board, setBoard] = useState<BoardState | null>(null);
  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    const s = io(SOCKET_URL);
    setSocket(s);

    s.on("board:init", (initialBoard: BoardState) => {
      setBoard(initialBoard);
    });

    s.on("board:updated", (nextBoard: BoardState) => {
      setBoard(nextBoard);
    });

    return () => {
      s.disconnect();
    };
  }, []);

  const columnIds = useMemo(() => board?.columnOrder ?? [], [board]);

  function handleDragEnd(event: DragEndEvent) {
    if (!board) return;

    const { active, over } = event;
    if (!over) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const fromColumnId = Object.values(board.columns).find((col) => col.taskIds.includes(taskId))?.id;
    const toColumnId = Object.values(board.columns).find((col) => col.taskIds.includes(overId))?.id || overId;

    if (!fromColumnId || !toColumnId) return;
    if (!board.tasks[taskId]) return;

    const targetColumn = board.columns[toColumnId];
    const toIndex = targetColumn.taskIds.indexOf(overId) >= 0 ? targetColumn.taskIds.indexOf(overId) : targetColumn.taskIds.length;

    const nextBoard = moveTask(board, taskId, fromColumnId, toColumnId, toIndex);

    setBoard(nextBoard);
    socket?.emit("board:update", nextBoard);
  }

  if (!board) {
    return <div className="app loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <div className="status">Updated: {new Date(board.updatedAt).toLocaleTimeString()}</div>
      </header>

      <DndContext sensors={sensors} onDragEnd={handleDragEnd}>
        <div className="board">
          <SortableContext items={columnIds} strategy={verticalListSortingStrategy}>
            {board.columnOrder.map((columnId) => {
              const column = board.columns[columnId];
              return (
                <ColumnView key={columnId} column={column} board={board} />
              );
            })}
          </SortableContext>
        </div>
      </DndContext>
    </div>
  );
}

function ColumnView({ column, board }: { column: NonNullable<BoardState["columns"][string]>; board: BoardState }) {
  return (
    <div className="column" id={column.id}>
      <div className="column-header">
        <h2>{column.title}</h2>
        <span>{column.taskIds.length}</span>
      </div>

      <div className="task-list" id={column.id}>
        {column.taskIds.map((taskId) => {
          const task = board.tasks[taskId];
          return <TaskCard key={taskId} task={task} />;
        })}
      </div>
    </div>
  );
}

function TaskCard({ task }: { task: Task }) {
  return (
    <div className="task-card" id={task.id}>
      <div className="task-title">{task.title}</div>
      {task.description ? <div className="task-description">{task.description}</div> : null}
    </div>
  );
}
```

