```ts
import { BoardState, RoomState, Task } from "./types.js";

const rooms = new Map<string, RoomState>();

function createInitialBoard(): BoardState {
  const todoId = "todo";
  const inProgressId = "in-progress";
  const doneId = "done";

  return {
    columns: {
      [todoId]: { id: todoId, title: "To Do", taskIds: [] },
      [inProgressId]: { id: inProgressId, title: "In Progress", taskIds: [] },
      [doneId]: { id: doneId, title: "Done", taskIds: [] }
    },
    tasks: {},
    columnOrder: [todoId, inProgressId, doneId]
  };
}

export function getRoom(roomId: string): RoomState {
  let room = rooms.get(roomId);
  if (!room) {
    room = { roomId, board: createInitialBoard() };
    rooms.set(roomId, room);
  }
  return room;
}

export function updateRoomBoard(roomId: string, board: BoardState) {
  const room = getRoom(roomId);
  room.board = board;
  rooms.set(roomId, room);
}

export function addTask(roomId: string, title: string, description = "") {
  const room = getRoom(roomId);
  const task: Task = {
    id: crypto.randomUUID(),
    title,
    description,
    status: "todo",
    createdAt: Date.now()
  };
  room.board.tasks[task.id] = task;
  room.board.columns["todo"].taskIds.unshift(task.id);
  return room.board;
}
```

## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { addTask, getRoom, updateRoomBoard } from "./store.js";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

app.get("/rooms/:roomId", (req, res) => {
  const { roomId } = req.params;
  const room = getRoom(roomId);
  res.json(room.board);
});

app.post("/rooms/:roomId/tasks", (req, res) => {
  const { roomId } = req.params;
  const { title, description } = req.body ?? {};

  if (!title || typeof title !== "string") {
    return res.status(400).json({ error: "title is required" });
  }

  const board = addTask(roomId, title, description || "");
  io.to(roomId).emit("board:updated", board);
  res.status(201).json(board);
});

io.on("connection", (socket) => {
  socket.on("room:join", (roomId: string) => {
    socket.join(roomId);
    const room = getRoom(roomId);
    socket.emit("board:state", room.board);
  });

  socket.on("board:update", ({ roomId, board }) => {
    updateRoomBoard(roomId, board);
    socket.to(roomId).emit("board:updated", board);
  });

  socket.on("task:create", ({ roomId, title, description }) => {
    const board = addTask(roomId, title, description);
    io.to(roomId).emit("board:updated", board);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

