### `server/src/store.ts`
```ts
import { BoardState, Task } from "./types";

const initialState: BoardState = {
  columns: {
    todo: [
      {
        id: "task-1",
        title: "Set up project",
        description: "Initialize frontend and backend",
        status: "todo",
        updatedAt: Date.now(),
      },
    ],
    doing: [],
    done: [],
  },
};

let state: BoardState = initialState;

export function getState() {
  return state;
}

export function setState(next: BoardState) {
  state = next;
}

export function moveTask(taskId: string, source: string, destination: string, task: Task) {
  const next = structuredClone(state);

  next.columns[source] = next.columns[source].filter((t) => t.id !== taskId);
  next.columns[destination].unshift({
    ...task,
    status: destination,
    updatedAt: Date.now(),
  });

  state = next;
  return state;
}
```

