import { useEffect, useState } from "react";
import { BoardState, Task } from "./lib/types";
import { socket } from "./lib/socket";
import { DndContext, DragEndEvent } from "@dnd-kit/core";
import Board from "./board/Board";

const defaultState: BoardState = {
  columns: {
    todo: [],
    doing: [],
    done: [],
  },
};

export default function App() {
  const [board, setBoard] = useState<BoardState>(defaultState);

  useEffect(() => {
    socket.on("board:state", (nextState: BoardState) => {
      setBoard(nextState);
    });

    return () => {
      socket.off("board:state");
    };
  }, []);

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;

    const task = active.data.current?.task as Task | undefined;
    const source = active.data.current?.column as string | undefined;
    const destination = over.data.current?.column as string | undefined;

    if (!task || !source || !destination || source === destination) return;

    socket.emit("task:move", {
      taskId: task.id,
      source,
      destination,
      task,
    });
  };

  return (
    <DndContext onDragEnd={handleDragEnd}>
      <div style={{ padding: 24, fontFamily: "sans-serif" }}>
        <h1>Project Manager</h1>
        <Board board={board} />
      </div>
    </DndContext>
  );
}
```

