### `server/index.js`
```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory demo data
let boards = [
  {
    id: "board-1",
    name: "Main Board",
    columns: [
      {
        id: "todo",
        title: "To Do",
        tasks: [
          { id: "t1", title: "Design app shell", description: "Create layout and navigation", updatedAt: Date.now() },
          { id: "t2", title: "Set up drag and drop", description: "Implement DnD for tasks", updatedAt: Date.now() }
        ]
      },
      {
        id: "doing",
        title: "In Progress",
        tasks: [
          { id: "t3", title: "Add real-time sync", description: "Socket.IO updates", updatedAt: Date.now() }
        ]
      },
      {
        id: "done",
        title: "Done",
        tasks: []
      }
    ]
  }
];

function getBoard(boardId) {
  return boards.find((b) => b.id === boardId);
}

function moveTask(boardId, taskId, sourceColumnId, destinationColumnId, destinationIndex) {
  const board = getBoard(boardId);
  if (!board) return null;

  const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
  const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);
  if (!sourceColumn || !destinationColumn) return null;

  const taskIndex = sourceColumn.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return null;

  const [task] = sourceColumn.tasks.splice(taskIndex, 1);
  task.updatedAt = Date.now();

  const insertAt = Math.max(0, Math.min(destinationIndex, destinationColumn.tasks.length));
  destinationColumn.tasks.splice(insertAt, 0, task);

  return board;
}

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.get("/api/boards/:boardId", (req, res) => {
  const board = getBoard(req.params.boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });
  res.json(board);
});

app.post("/api/boards/:boardId/tasks/move", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;
  const board = moveTask(req.params.boardId, taskId, sourceColumnId, destinationColumnId, destinationIndex);

  if (!board) return res.status(400).json({ error: "Invalid move" });

  io.emit("board-updated", board);
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.on("join-board", (boardId) => {
    socket.join(boardId);
    const board = getBoard(boardId);
    if (board) socket.emit("board-updated", board);
  });

  socket.on("move-task", ({ boardId, taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const board = moveTask(boardId, taskId, sourceColumnId, destinationColumnId, destinationIndex);
    if (board) {
      io.to(boardId).emit("board-updated", board);
      io.emit("board-updated", board);
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(3001, () => {
  console.log("Server listening on http://localhost:3001");
});
```

