### `client/src/App.jsx`
```jsx
import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay
} from "@dnd-kit/core";
import { SortableContext, verticalListSortingStrategy, arrayMove } from "@dnd-kit/sortable";

const API_URL = "http://localhost:3001";
const socket = io(API_URL);

function TaskCard({ task, isDragging = false }) {
  return (
    <div className={`task-card ${isDragging ? "dragging" : ""}`}>
      <div className="task-title">{task.title}</div>
      {task.description && <div className="task-desc">{task.description}</div>}
    </div>
  );
}

function Column({ column, tasks, children }) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{tasks.length}</span>
      </div>
      <div className="column-body">{children}</div>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [activeTask, setActiveTask] = useState(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 8 }
    })
  );

  useEffect(() => {
    const load = async () => {
      const res = await axios.get(`${API_URL}/api/boards`);
      const firstBoard = res.data[0];
      setBoard(firstBoard);
      socket.emit("join-board", firstBoard.id);
    };

    load();

    socket.on("board-updated", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board-updated");
    };
  }, []);

  const tasksById = useMemo(() => {
    const map = new Map();
    if (!board) return map;
    for (const column of board.columns) {
      for (const task of column.tasks) {
        map.set(task.id, { task, columnId: column.id });
      }
    }
    return map;
  }, [board]);

  const handleDragStart = (event) => {
    const taskId = event.active.id;
    const found = tasksById.get(taskId);
    if (found) setActiveTask(found.task);
  };

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    setActiveTask(null);

    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    const activeInfo = tasksById.get(activeId);
    if (!activeInfo) return;

    const sourceColumnId = activeInfo.columnId;

    // Find destination column and index
    let destinationColumnId = sourceColumnId;
    let destinationIndex = 0;

    for (const column of board.columns) {
      const taskIndex = column.tasks.findIndex((t) => t.id === overId);
      if (taskIndex !== -1) {
        destinationColumnId = column.id;
        destinationIndex = taskIndex;
        break;
      }
      if (column.id === overId) {
        destinationColumnId = column.id;
        destinationIndex = column.tasks.length;
        break;
      }
    }

    if (activeId === overId) return;

    try {
      await socket.emit("move-task", {
        boardId: board.id,
        taskId: activeId,
        sourceColumnId,
        destinationColumnId,
        destinationIndex
      });
    } catch (e) {
      console.error("Move failed:", e);
    }
  };

  if (!board) {
    return <div className="app-shell">Loading board...</div>;
  }

  return (
    <div className="app-shell">
      <header className="topbar">
        <div>
          <h1>Project Board</h1>
          <p>Real-time collaborative task management</p>
        </div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columns.map((column) => (
            <Column key={column.id} column={column} tasks={column.tasks}>
              <SortableContext items={column.tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
                <div className="task-list" data-column-id={column.id}>
                  {column.tasks.map((task) => (
                    <div key={task.id} className="task-wrapper" id={task.id}>
                      <TaskCard task={task} />
                    </div>
                  ))}
                </div>
              </SortableContext>
            </Column>
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} isDragging /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

