```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory state for initial implementation
let tasks = [
  { id: "1", title: "Define MVP scope", status: "todo" },
  { id: "2", title: "Design board UI", status: "inprogress" },
  { id: "3", title: "Set up auth flow", status: "done" }
];

app.get("/api/tasks", (req, res) => {
  res.json(tasks);
});

app.post("/api/tasks", (req, res) => {
  const { title, status = "todo" } = req.body;
  const task = {
    id: crypto.randomUUID(),
    title,
    status
  };
  tasks.push(task);
  io.emit("tasks:update", tasks);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, status } = req.body;

  tasks = tasks.map((task) =>
    task.id === id
      ? {
          ...task,
          ...(title !== undefined ? { title } : {}),
          ...(status !== undefined ? { status } : {})
        }
      : task
  );

  io.emit("tasks:update", tasks);
  res.json({ ok: true });
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  tasks = tasks.filter((task) => task.id !== id);
  io.emit("tasks:update", tasks);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  socket.emit("tasks:update", tasks);

  socket.on("task:create", (payload) => {
    const task = {
      id: crypto.randomUUID(),
      title: payload.title,
      status: payload.status || "todo"
    };
    tasks.push(task);
    io.emit("tasks:update", tasks);
  });

  socket.on("task:update", ({ id, title, status }) => {
    tasks = tasks.map((task) =>
      task.id === id
        ? {
            ...task,
            ...(title !== undefined ? { title } : {}),
            ...(status !== undefined ? { status } : {})
          }
        : task
    );
    io.emit("tasks:update", tasks);
  });

  socket.on("task:delete", ({ id }) => {
    tasks = tasks.filter((task) => task.id !== id);
    io.emit("tasks:update", tasks);
  });
});

server.listen(4000, () => {
  console.log("Server listening on http://localhost:4000");
});
```

