## `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// Initial in-memory board state
let board = {
  id: "board-1",
  title: "Project Board",
  columns: [
    {
      id: "backlog",
      title: "Backlog",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "in-progress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Set up project", description: "Initialize repo and tooling" },
    "task-2": { id: "task-2", title: "Design UI", description: "Create board layout" },
    "task-3": { id: "task-3", title: "Implement realtime sync", description: "Set up Socket.IO" }
  }
};

let connectedUsers = 0;

app.get("/api/board", (req, res) => {
  res.json({ board, connectedUsers });
});

app.post("/api/task", (req, res) => {
  const { title, description, columnId } = req.body;

  if (!title || !columnId) {
    return res.status(400).json({ error: "title and columnId are required" });
  }

  const id = `task-${Date.now()}`;
  const newTask = { id, title, description: description || "" };

  board.tasks[id] = newTask;
  const column = board.columns.find(c => c.id === columnId);

  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json({ task: newTask, board });
});

io.on("connection", (socket) => {
  connectedUsers++;
  io.emit("presence:update", { connectedUsers });

  socket.emit("board:update", board);

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:create", ({ title, description, columnId }) => {
    if (!title || !columnId) return;

    const id = `task-${Date.now()}`;
    const newTask = { id, title, description: description || "" };

    board.tasks[id] = newTask;
    const column = board.columns.find(c => c.id === columnId);

    if (!column) return;

    column.taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    connectedUsers--;
    io.emit("presence:update", { connectedUsers });
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

