```jsx
import React, { useEffect, useState } from "react";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { socket } from "./socket";

function Column({ column, tasks, onCreateTask }) {
  return (
    <div className="column">
      <div className="column-header">
        <h2>{column.title}</h2>
      </div>

      <div className="task-list">
        {tasks.map((task) => (
          <TaskCard key={task.id} task={task} />
        ))}
      </div>

      <TaskForm onCreateTask={(title, description) => onCreateTask(column.id, title, description)} />
    </div>
  );
}

function TaskCard({ task }) {
  return (
    <div className="task-card" data-taskid={task.id}>
      <strong>{task.title}</strong>
      <p>{task.description}</p>
    </div>
  );
}

function TaskForm({ onCreateTask }) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  const submit = (e) => {
    e.preventDefault();
    if (!title.trim()) return;
    onCreateTask(title, description);
    setTitle("");
    setDescription("");
  };

  return (
    <form className="task-form" onSubmit={submit}>
      <input
        placeholder="Task title"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
      />
      <input
        placeholder="Description"
        value={description}
        onChange={(e) => setDescription(e.target.value)}
      />
      <button type="submit">Add Task</button>
    </form>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [connectedUsers, setConnectedUsers] = useState(0);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  useEffect(() => {
    fetch("http://localhost:3001/api/board")
      .then((res) => res.json())
      .then((data) => {
        setBoard(data.board);
        setConnectedUsers(data.connectedUsers);
      });

    socket.on("board:update", (updatedBoard) => {
      setBoard({ ...updatedBoard });
    });

    socket.on("presence:update", ({ connectedUsers }) => {
      setConnectedUsers(connectedUsers);
    });

    return () => {
      socket.off("board:update");
      socket.off("presence:update");
    };
  }, []);

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (!active || !over || !board) return;

    const taskId = active.id;
    const sourceColumn = board.columns.find((c) => c.taskIds.includes(taskId));
    const destinationColumn = board.columns.find((c) => c.id === over.id || c.taskIds.includes(over.id));

    if (!sourceColumn || !destinationColumn) return;

    if (sourceColumn.id === destinationColumn.id) return;

    const destinationIndex = destinationColumn.taskIds.length;

    socket.emit("task:move", {
      taskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId: destinationColumn.id,
      destinationIndex
    });
  };

  const createTask = (columnId, title, description) => {
    socket.emit("task:create", { columnId, title, description });
  };

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>{board.title}</h1>
        <div className="presence">
          Connected users: <strong>{connectedUsers}</strong>
        </div>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <div className="board">
          {board.columns.map((column) => {
            const tasks = column.taskIds.map((id) => board.tasks[id]).filter(Boolean);
            return (
              <div key={column.id} id={column.id} className="column-dropzone">
                <Column column={column} tasks={tasks} onCreateTask={createTask} />
              </div>
            );
          })}
        </div>
      </DndContext>
    </div>
  );
}
```

