### `server/src/state.ts`

```ts
import { BoardState } from "./types";

export const initialState: BoardState = {
  tasks: [
    {
      id: "1",
      title: "Design app layout",
      description: "Create the main board layout and task cards",
      status: "todo",
      order: 0,
      updatedAt: new Date().toISOString()
    },
    {
      id: "2",
      title: "Set up real-time sync",
      description: "Use Socket.IO to broadcast board updates",
      status: "inprogress",
      order: 0,
      updatedAt: new Date().toISOString()
    },
    {
      id: "3",
      title: "Add task editing",
      status: "done",
      order: 0,
      updatedAt: new Date().toISOString()
    }
  ]
};

export function sortTasks(state: BoardState): BoardState {
  return {
    tasks: [...state.tasks].sort((a, b) => {
      if (a.status !== b.status) return a.status.localeCompare(b.status);
      return a.order - b.order;
    })
  };
}
