### `server/src/index.ts`

```ts
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";
import { initialState, sortTasks } from "./state";
import { BoardState, Task, TaskStatus } from "./types";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let boardState: BoardState = sortTasks(initialState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

function normalizeOrders(tasks: Task[]): Task[] {
  const groups: Record<TaskStatus, Task[]> = {
    todo: [],
    inprogress: [],
    done: []
  };

  tasks.forEach((task) => groups[task.status].push(task));

  (Object.keys(groups) as TaskStatus[]).forEach((status) => {
    groups[status].sort((a, b) => a.order - b.order);
    groups[status].forEach((task, index) => {
      task.order = index;
      task.updatedAt = new Date().toISOString();
    });
  });

  return [...groups.todo, ...groups.inprogress, ...groups.done];
}

app.post("/api/tasks", (req, res) => {
  const { title, description, status } = req.body as {
    title: string;
    description?: string;
    status?: TaskStatus;
  };

  if (!title) {
    return res.status(400).json({ error: "title is required" });
  }

  const newTask: Task = {
    id: crypto.randomUUID(),
    title,
    description,
    status: status ?? "todo",
    order: boardState.tasks.filter((t) => t.status === (status ?? "todo")).length,
    updatedAt: new Date().toISOString()
  };

  boardState = {
    tasks: normalizeOrders([...boardState.tasks, newTask])
  };

  io.emit("board:update", boardState);
  res.status(201).json(newTask);
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("task:move", (payload: { taskId: string; status: TaskStatus; index: number }) => {
    const { taskId, status, index } = payload;

    const tasks = boardState.tasks.map((t) => ({ ...t }));
    const task = tasks.find((t) => t.id === taskId);
    if (!task) return;

    task.status = status;
    task.updatedAt = new Date().toISOString();

    const targetGroup = tasks.filter((t) => t.id !== taskId && t.status === status);
    const movingTask = task;

    targetGroup.splice(index, 0, movingTask);

    const sameStatusOtherTasks = tasks.filter((t) => t.id !== taskId && t.status !== status);
    const merged = [...sameStatusOtherTasks, ...targetGroup.map((t, i) => ({ ...t, order: i }))];

    boardState = {
      tasks: sortTasks({
        tasks: normalizeOrders(merged as Task[])
      })
    };

    io.emit("board:update", boardState);
  });

  socket.on("task:create", (payload: { title: string; description?: string; status?: TaskStatus }) => {
    const newTask: Task = {
      id: crypto.randomUUID(),
      title: payload.title,
      description: payload.description,
      status: payload.status ?? "todo",
      order: boardState.tasks.filter((t) => t.status === (payload.status ?? "todo")).length,
      updatedAt: new Date().toISOString()
    };

    boardState = {
      tasks: normalizeOrders([...boardState.tasks, newTask])
    };

    io.emit("board:update", boardState);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

