import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import Board from "./components/Board";

type TaskStatus = "todo" | "inprogress" | "done";

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  order: number;
  updatedAt: string;
}

interface BoardState {
  tasks: Task[];
}

const SERVER_URL = "http://localhost:4000";

export default function App() {
  const [board, setBoard] = useState<BoardState>({ tasks: [] });
  const [socket, setSocket] = useState<Socket | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    const s = io(SERVER_URL);
    setSocket(s);

    s.on("board:update", (state: BoardState) => {
      setBoard(state);
    });

    return () => {
      s.disconnect();
    };
  }, []);

  const grouped = useMemo(() => {
    const groups: Record<TaskStatus, Task[]> = {
      todo: [],
      inprogress: [],
      done: []
    };

    [...board.tasks]
      .sort((a, b) => a.order - b.order)
      .forEach((task) => groups[task.status].push(task));

    return groups;
  }, [board.tasks]);

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    if (!over || !socket) return;

    const taskId = String(active.id);
    const overId = String(over.id);

    const task = board.tasks.find((t) => t.id === taskId);
    if (!task) return;

    const statuses: TaskStatus[] = ["todo", "inprogress", "done"];
    const targetStatus: TaskStatus = statuses.includes(overId as TaskStatus)
      ? (overId as TaskStatus)
      : (board.tasks.find((t) => t.id === overId)?.status ?? task.status);

    const targetTasks = grouped[targetStatus];
    const index = statuses.includes(overId as TaskStatus)
      ? targetTasks.length
      : Math.max(0, targetTasks.findIndex((t) => t.id === overId));

    socket.emit("task:move", {
      taskId,
      status: targetStatus,
      index
    });
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <p>Drag tasks across boards. Updates sync in real time.</p>
      </header>

      <DndContext sensors={sensors} onDragEnd={handleDragEnd}>
        <Board grouped={grouped} />
      </DndContext>
    </div>
  );
}
```

