import { useDroppable } from "@dnd-kit/core";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import TaskCard from "./TaskCard";
import type { Task } from "../App";

type TaskStatus = "todo" | "inprogress" | "done";

function Column({
  id,
  title,
  tasks
}: {
  id: TaskStatus;
  title: string;
  tasks: Task[];
}) {
  const { setNodeRef, isOver } = useDroppable({ id });

  return (
    <div className={`column ${isOver ? "column--over" : ""}`} ref={setNodeRef}>
      <h2>{title}</h2>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function Board({
  grouped
}: {
  grouped: Record<TaskStatus, Task[]>;
}) {
  return (
    <main className="board">
      <Column id="todo" title="To Do" tasks={grouped.todo} />
      <Column id="inprogress" title="In Progress" tasks={grouped.inprogress} />
      <Column id="done" title="Done" tasks={grouped.done} />
    </main>
  );
}
