## `server/index.js`

```js
import express from "express";
import http from "http";
import { Server } from "socket.io";
import path from "path";
import { fileURLToPath } from "url";
import { initialState } from "./data.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "..", "public")));

let state = structuredClone(initialState);

function findTask(boardId, taskId) {
  const board = state.boards.find(b => b.id === boardId);
  if (!board) return null;

  for (const column of board.columns) {
    const taskIndex = column.tasks.findIndex(t => t.id === taskId);
    if (taskIndex !== -1) {
      return { board, column, taskIndex };
    }
  }
  return null;
}

function getBoard(boardId) {
  return state.boards.find(b => b.id === boardId) || null;
}

app.get("/api/state", (req, res) => {
  res.json(state);
});

app.post("/api/tasks", (req, res) => {
  const { boardId, columnId, title, description = "" } = req.body;
  const board = getBoard(boardId);

  if (!board) return res.status(404).json({ error: "Board not found" });

  const column = board.columns.find(c => c.id === columnId);
  if (!column) return res.status(404).json({ error: "Column not found" });

  const task = {
    id: `task-${Date.now()}`,
    title,
    description
  };

  column.tasks.push(task);
  io.emit("state:update", state);

  res.status(201).json(task);
});

app.put("/api/tasks/:taskId/move", (req, res) => {
  const { taskId } = req.params;
  const { boardId, columnId, position } = req.body;

  const located = findTask(boardId, taskId);
  if (!located) return res.status(404).json({ error: "Task not found" });

  const { board, column: sourceColumn, taskIndex } = located;
  const [task] = sourceColumn.tasks.splice(taskIndex, 1);

  const targetColumn = board.columns.find(c => c.id === columnId);
  if (!targetColumn) return res.status(404).json({ error: "Target column not found" });

  const insertAt = Math.max(0, Math.min(position ?? targetColumn.tasks.length, targetColumn.tasks.length));
  targetColumn.tasks.splice(insertAt, 0, task);

  io.emit("state:update", state);
  res.json({ ok: true });
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { boardId, title, description } = req.body;

  const located = findTask(boardId, taskId);
  if (!located) return res.status(404).json({ error: "Task not found" });

  const { column, taskIndex } = located;
  column.tasks[taskIndex] = {
    ...column.tasks[taskIndex],
    title: title ?? column.tasks[taskIndex].title,
    description: description ?? column.tasks[taskIndex].description
  };

  io.emit("state:update", state);
  res.json(column.tasks[taskIndex]);
});

io.on("connection", socket => {
  socket.emit("state:update", state);

  socket.on("task:move", ({ taskId, boardId, columnId, position }) => {
    const located = findTask(boardId, taskId);
    if (!located) return;

    const { board, column: sourceColumn, taskIndex } = located;
    const [task] = sourceColumn.tasks.splice(taskIndex, 1);

    const targetColumn = board.columns.find(c => c.id === columnId);
    if (!targetColumn) return;

    const insertAt = Math.max(0, Math.min(position ?? targetColumn.tasks.length, targetColumn.tasks.length));
    targetColumn.tasks.splice(insertAt, 0, task);

    io.emit("state:update", state);
  });

  socket.on("task:create", ({ boardId, columnId, title, description = "" }) => {
    const board = getBoard(boardId);
    if (!board) return;

    const column = board.columns.find(c => c.id === columnId);
    if (!column) return;

    column.tasks.push({
      id: `task-${Date.now()}`,
      title,
      description
    });

    io.emit("state:update", state);
  });

  socket.on("task:update", ({ boardId, taskId, title, description }) => {
    const located = findTask(boardId, taskId);
    if (!located) return;

    const { column, taskIndex } = located;
    column.tasks[taskIndex] = {
      ...column.tasks[taskIndex],
      title: title ?? column.tasks[taskIndex].title,
      description: description ?? column.tasks[taskIndex].description
    };

    io.emit("state:update", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

