## `public/app.js`

```js
const socket = io();

let state = null;
let selectedBoardId = null;
let draggedTask = null;

const boardsEl = document.getElementById("boards");
const statusEl = document.getElementById("status");

const dialog = document.getElementById("taskDialog");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskForm = document.getElementById("taskForm");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");
const taskColumn = document.getElementById("taskColumn");

socket.on("connect", () => {
  statusEl.textContent = "Connected";
});

socket.on("disconnect", () => {
  statusEl.textContent = "Disconnected";
});

socket.on("state:update", (newState) => {
  state = newState;
  selectedBoardId = selectedBoardId || state.boards[0]?.id || null;
  render();
});

function render() {
  if (!state) return;

  const board = state.boards.find(b => b.id === selectedBoardId) || state.boards[0];
  if (!board) {
    boardsEl.innerHTML = "<p>No boards available.</p>";
    return;
  }

  taskColumn.innerHTML = board.columns
    .map(col => `<option value="${col.id}">${col.name}</option>`)
    .join("");

  boardsEl.innerHTML = `
    <section class="board">
      <h2>${board.name}</h2>
      <div class="columns">
        ${board.columns.map(column => `
          <div class="column" data-column-id="${column.id}">
            <h2>${column.name}</h2>
            <div class="task-list" data-column-id="${column.id}">
              ${column.tasks.map(task => `
                <article class="task" draggable="true" data-task-id="${task.id}" data-board-id="${board.id}">
                  <h3>${escapeHtml(task.title)}</h3>
                  <p>${escapeHtml(task.description || "")}</p>
                </article>
              `).join("")}
            </div>
          </div>
        `).join("")}
      </div>
    </section>
  `;

  attachDnDHandlers(board.id);
}

function attachDnDHandlers(boardId) {
  document.querySelectorAll(".task").forEach(taskEl => {
    taskEl.addEventListener("dragstart", () => {
      draggedTask = {
        taskId: taskEl.dataset.taskId,
        boardId: taskEl.dataset.boardId
      };
      taskEl.classList.add("dragging");
    });

    taskEl.addEventListener("dragend", () => {
      taskEl.classList.remove("dragging");
      draggedTask = null;
    });
  });

  document.querySelectorAll(".task-list").forEach(listEl => {
    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTask) return;

      const targetColumnId = listEl.dataset.columnId;
      const tasks = Array.from(listEl.querySelectorAll(".task"));
      const position = tasks.length;

      socket.emit("task:move", {
        taskId: draggedTask.taskId,
        boardId,
        columnId: targetColumnId,
        position
      });
    });
  });
}

addTaskBtn.addEventListener("click", () => {
  if (!state) return;
  const board = state.boards.find(b => b.id === selectedBoardId) || state.boards[0];
  if (!board) return;

  taskColumn.value = board.columns[0]?.id || "";
  taskTitle.value = "";
  taskDescription.value = "";
  dialog.showModal();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const board = state.boards.find(b => b.id === selectedBoardId) || state.boards[0];
  if (!board) return;

  socket.emit("task:create", {
    boardId: board.id,
    columnId: taskColumn.value,
    title: taskTitle.value.trim(),
    description: taskDescription.value.trim()
  });

  dialog.close();
});

function escapeHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

