## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

// Simple in-memory state
let boardState = {
  todo: [
    { id: "1", title: "Set up project", description: "Initialize repo and structure" },
    { id: "2", title: "Design UI", description: "Create minimal board layout" }
  ],
  doing: [
    { id: "3", title: "Implement drag-and-drop", description: "Allow moving cards" }
  ],
  done: []
};

io.on("connection", (socket) => {
  // Send current state to new client
  socket.emit("board:update", boardState);

  // Move task between columns
  socket.on("task:move", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const fromList = boardState[fromColumn];
    const toList = boardState[toColumn];
    if (!fromList || !toList) return;

    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    toList.splice(toIndex, 0, task);

    io.emit("board:update", boardState);
  });

  // Add task
  socket.on("task:add", ({ column, task }) => {
    if (!boardState[column]) return;
    boardState[column].unshift(task);
    io.emit("board:update", boardState);
  });

  // Optional: reset board
  socket.on("board:reset", () => {
    boardState = {
      todo: [
        { id: "1", title: "Set up project", description: "Initialize repo and structure" },
        { id: "2", title: "Design UI", description: "Create minimal board layout" }
      ],
      doing: [
        { id: "3", title: "Implement drag-and-drop", description: "Allow moving cards" }
      ],
      done: []
    };
    io.emit("board:update", boardState);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

