## 6) `public/app.js`

```js
const socket = io();

let boardState = {};

const todoEl = document.getElementById("todo");
const doingEl = document.getElementById("doing");
const doneEl = document.getElementById("done");

const titleInput = document.getElementById("newTaskTitle");
const descInput = document.getElementById("newTaskDesc");
const columnSelect = document.getElementById("newTaskColumn");
const addTaskBtn = document.getElementById("addTaskBtn");
const resetBtn = document.getElementById("resetBtn");

let draggedTaskId = null;
let draggedFromColumn = null;

function renderBoard(state) {
  boardState = state;
  todoEl.innerHTML = "";
  doingEl.innerHTML = "";
  doneEl.innerHTML = "";

  ["todo", "doing", "done"].forEach((column) => {
    const list = document.getElementById(column);
    state[column].forEach((task) => {
      const card = document.createElement("div");
      card.className = "task";
      card.draggable = true;
      card.dataset.taskId = task.id;
      card.dataset.column = column;

      card.innerHTML = `
        <div class="task-title">${escapeHtml(task.title)}</div>
        <div class="task-desc">${escapeHtml(task.description || "")}</div>
      `;

      card.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumn = column;
        card.classList.add("dragging");
      });

      card.addEventListener("dragend", () => {
        card.classList.remove("dragging");
      });

      list.appendChild(card);
    });
  });
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function getDropIndex(listEl, y) {
  const cards = [...listEl.querySelectorAll(".task:not(.dragging)")];
  let closest = { offset: Number.NEGATIVE_INFINITY, index: 0 };

  cards.forEach((card, index) => {
    const box = card.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

["todo", "doing", "done"].forEach((column) => {
  const list = document.getElementById(column);

  list.addEventListener("dragover", (e) => {
    e.preventDefault();
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    if (!draggedTaskId || !draggedFromColumn) return;

    const toIndex = getDropIndex(list, e.clientY);
    socket.emit("task:move", {
      taskId: draggedTaskId,
      fromColumn: draggedFromColumn,
      toColumn: column,
      toIndex
    });

    draggedTaskId = null;
    draggedFromColumn = null;
  });
});

addTaskBtn.addEventListener("click", () => {
  const title = titleInput.value.trim();
  const description = descInput.value.trim();
  const column = columnSelect.value;

  if (!title) return;

  const task = {
    id: crypto.randomUUID(),
    title,
    description
  };

  socket.emit("task:add", { column, task });

  titleInput.value = "";
  descInput.value = "";
});

resetBtn.addEventListener("click", () => {
  socket.emit("board:reset");
});

socket.on("board:update", (state) => {
  renderBoard(state);
});
```

