## 6) `public/app.js`

```js
const socket = io();

const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");

const columns = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

let currentState = { tasks: [] };

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;

  const task = {
    id: Date.now().toString(),
    title,
    status: "todo"
  };

  socket.emit("createTask", task);
  taskInput.value = "";
});

socket.on("init", (state) => {
  currentState = state;
  render();
});

socket.on("state:update", (state) => {
  currentState = state;
  render();
});

function render() {
  Object.values(columns).forEach((col) => (col.innerHTML = ""));

  currentState.tasks.forEach((task) => {
    const taskEl = document.createElement("div");
    taskEl.className = "task";
    taskEl.draggable = true;
    taskEl.dataset.id = task.id;

    taskEl.innerHTML = `
      <span>${escapeHtml(task.title)}</span>
      <button class="delete-btn" data-delete="${task.id}">X</button>
    `;

    taskEl.addEventListener("dragstart", (e) => {
      e.dataTransfer.setData("text/plain", task.id);
    });

    taskEl.querySelector("[data-delete]").addEventListener("click", () => {
      socket.emit("deleteTask", task.id);
    });

    columns[task.status].appendChild(taskEl);
  });

  setupDropZones();
}

function setupDropZones() {
  document.querySelectorAll(".column").forEach((col) => {
    col.addEventListener("dragover", (e) => {
      e.preventDefault();
      col.classList.add("drag-over");
    });

    col.addEventListener("dragleave", () => {
      col.classList.remove("drag-over");
    });

    col.addEventListener("drop", (e) => {
      e.preventDefault();
      col.classList.remove("drag-over");
      const id = e.dataTransfer.getData("text/plain");
      const status = col.dataset.status;
      socket.emit("moveTask", { id, status });
    });
  });
}

function escapeHtml(text) {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

