```js
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static('public'));

let boards = {
  todo: [
    { id: '1', text: 'Set up project', board: 'todo' },
    { id: '2', text: 'Design UI', board: 'todo' }
  ],
  doing: [
    { id: '3', text: 'Build drag-and-drop', board: 'doing' }
  ],
  done: []
};

io.on('connection', (socket) => {
  socket.emit('init', boards);

  socket.on('move-task', ({ taskId, fromBoard, toBoard, index }) => {
    const task = boards[fromBoard].find(t => t.id === taskId);
    if (!task) return;

    boards[fromBoard] = boards[fromBoard].filter(t => t.id !== taskId);
    task.board = toBoard;

    if (index >= boards[toBoard].length) {
      boards[toBoard].push(task);
    } else {
      boards[toBoard].splice(index, 0, task);
    }

    io.emit('boards-updated', boards);
  });

  socket.on('add-task', ({ text }) => {
    const task = {
      id: String(Date.now()),
      text,
      board: 'todo'
    };
    boards.todo.push(task);
    io.emit('boards-updated', boards);
  });
});

server.listen(3000, () => {
  console.log('Server running at http://localhost:3000');
});
```

