const socket = io();

let boards = {};

const taskForm = document.getElementById('taskForm');
const taskInput = document.getElementById('taskInput');

const boardElements = {
  todo: document.getElementById('todo'),
  doing: document.getElementById('doing'),
  done: document.getElementById('done')
};

let draggedTaskId = null;
let draggedFromBoard = null;

function renderBoards() {
  Object.keys(boardElements).forEach(boardName => {
    const list = boardElements[boardName];
    list.innerHTML = '';

    (boards[boardName] || []).forEach(task => {
      const div = document.createElement('div');
      div.className = 'task';
      div.textContent = task.text;
      div.draggable = true;
      div.dataset.id = task.id;
      div.dataset.board = boardName;

      div.addEventListener('dragstart', () => {
        draggedTaskId = task.id;
        draggedFromBoard = boardName;
        div.classList.add('dragging');
      });

      div.addEventListener('dragend', () => {
        div.classList.remove('dragging');
      });

      list.appendChild(div);
    });
  });
}

socket.on('init', (initialBoards) => {
  boards = initialBoards;
  renderBoards();
});

socket.on('boards-updated', (updatedBoards) => {
  boards = updatedBoards;
  renderBoards();
});

taskForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const text = taskInput.value.trim();
  if (!text) return;

  socket.emit('add-task', { text });
  taskInput.value = '';
});

Object.keys(boardElements).forEach(boardName => {
  const list = boardElements[boardName];

  list.addEventListener('dragover', (e) => {
    e.preventDefault();
    list.classList.add('drag-over');
  });

  list.addEventListener('dragleave', () => {
    list.classList.remove('drag-over');
  });

  list.addEventListener('drop', (e) => {
    e.preventDefault();
    list.classList.remove('drag-over');

    if (!draggedTaskId || !draggedFromBoard) return;

    const tasksInBoard = boards[boardName] || [];
    const index = tasksInBoard.length;

    socket.emit('move-task', {
      taskId: draggedTaskId,
      fromBoard: draggedFromBoard,
      toBoard: boardName,
      index
    });

    draggedTaskId = null;
    draggedFromBoard = null;
  });
});
