```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let boards = [
  {
    id: "todo",
    title: "Todo",
    cards: [
      { id: "1", text: "Set up project" },
      { id: "2", text: "Build drag-and-drop boards" }
    ]
  },
  {
    id: "doing",
    title: "Doing",
    cards: [
      { id: "3", text: "Add real-time sync" }
    ]
  },
  {
    id: "done",
    title: "Done",
    cards: []
  }
];

function broadcastState() {
  io.emit("state:update", boards);
}

io.on("connection", (socket) => {
  socket.emit("state:update", boards);

  socket.on("card:add", ({ boardId, text }) => {
    const board = boards.find((b) => b.id === boardId);
    if (!board || !text.trim()) return;

    board.cards.push({
      id: String(Date.now()) + Math.random().toString(16).slice(2),
      text: text.trim()
    });

    broadcastState();
  });

  socket.on("card:move", ({ fromBoardId, toBoardId, cardId, toIndex }) => {
    const fromBoard = boards.find((b) => b.id === fromBoardId);
    const toBoard = boards.find((b) => b.id === toBoardId);
    if (!fromBoard || !toBoard) return;

    const cardIndex = fromBoard.cards.findIndex((c) => c.id === cardId);
    if (cardIndex === -1) return;

    const [card] = fromBoard.cards.splice(cardIndex, 1);
    const insertIndex = Math.max(0, Math.min(toIndex ?? toBoard.cards.length, toBoard.cards.length));
    toBoard.cards.splice(insertIndex, 0, card);

    broadcastState();
  });
});

server.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
```

