## 6) `public/app.js`

```js
const socket = io();

const boardsEl = document.getElementById("boards");
const newTaskText = document.getElementById("newTaskText");
const newTaskBoard = document.getElementById("newTaskBoard");
const addTaskBtn = document.getElementById("addTaskBtn");

let state = [];
let dragData = null;

socket.on("state:update", (boards) => {
  state = boards;
  render();
});

addTaskBtn.addEventListener("click", () => {
  const text = newTaskText.value.trim();
  const boardId = newTaskBoard.value;
  if (!text) return;

  socket.emit("card:add", { boardId, text });
  newTaskText.value = "";
  newTaskText.focus();
});

newTaskText.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

function render() {
  boardsEl.innerHTML = "";

  state.forEach((board) => {
    const boardEl = document.createElement("section");
    boardEl.className = "board";
    boardEl.dataset.boardId = board.id;

    const title = document.createElement("h2");
    title.textContent = board.title;

    const list = document.createElement("div");
    list.className = "card-list";
    list.dataset.boardId = board.id;

    board.cards.forEach((card, index) => {
      const cardEl = document.createElement("div");
      cardEl.className = "card";
      cardEl.draggable = true;
      cardEl.textContent = card.text;
      cardEl.dataset.cardId = card.id;
      cardEl.dataset.boardId = board.id;
      cardEl.dataset.index = index;

      cardEl.addEventListener("dragstart", () => {
        dragData = { cardId: card.id, fromBoardId: board.id };
        cardEl.classList.add("dragging");
      });

      cardEl.addEventListener("dragend", () => {
        dragData = null;
        cardEl.classList.remove("dragging");
        document.querySelectorAll(".drop-target").forEach((el) => el.classList.remove("drop-target"));
      });

      list.appendChild(cardEl);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drop-target");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drop-target");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drop-target");

      if (!dragData) return;

      const targetCards = [...list.querySelectorAll(".card")];
      const toIndex = targetCards.length;

      socket.emit("card:move", {
        fromBoardId: dragData.fromBoardId,
        toBoardId: board.id,
        cardId: dragData.cardId,
        toIndex
      });
    });

    boardEl.appendChild(title);
    boardEl.appendChild(list);
    boardsEl.appendChild(boardEl);
  });
}
