const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

// In-memory state (resets on server restart)
let boardState = {
  todo: [
    { id: "1", title: "Design homepage" },
    { id: "2", title: "Set up auth" }
  ],
  doing: [
    { id: "3", title: "Build drag and drop" }
  ],
  done: [
    { id: "4", title: "Create project scaffold" }
  ]
};

io.on("connection", (socket) => {
  // Send current board state to newly connected client
  socket.emit("state:init", boardState);

  // Receive updates from one client and broadcast to all others
  socket.on("task:moved", (newState) => {
    boardState = newState;
    io.emit("state:update", boardState);
  });

  socket.on("task:created", (newState) => {
    boardState = newState;
    io.emit("state:update", boardState);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
