## 6) `public/app.js`

```js
const socket = io();

let state = {
  todo: [],
  doing: [],
  done: []
};

const lists = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

const form = document.getElementById("newTaskForm");
const titleInput = document.getElementById("newTaskTitle");

function render() {
  Object.keys(lists).forEach((status) => {
    lists[status].innerHTML = "";
    state[status].forEach((task) => {
      const el = document.createElement("div");
      el.className = "task";
      el.draggable = true;
      el.dataset.id = task.id;
      el.dataset.status = status;
      el.textContent = task.title;

      el.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/plain", JSON.stringify({
          id: task.id,
          from: status
        }));
      });

      lists[status].appendChild(el);
    });
  });
}

function updateServer() {
  socket.emit("task:moved", state);
}

function moveTask(taskId, fromStatus, toStatus) {
  if (fromStatus === toStatus) return;

  const taskIndex = state[fromStatus].findIndex(t => t.id === taskId);
  if (taskIndex === -1) return;

  const [task] = state[fromStatus].splice(taskIndex, 1);
  state[toStatus].push(task);
  render();
  updateServer();
}

Object.keys(lists).forEach((status) => {
  const column = document.querySelector(`.column[data-status="${status}"]`);

  column.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.classList.add("drag-over");
  });

  column.addEventListener("dragleave", () => {
    column.classList.remove("drag-over");
  });

  column.addEventListener("drop", (e) => {
    e.preventDefault();
    column.classList.remove("drag-over");

    const data = JSON.parse(e.dataTransfer.getData("text/plain"));
    moveTask(data.id, data.from, status);
  });
});

socket.on("state:init", (newState) => {
  state = newState;
  render();
});

socket.on("state:update", (newState) => {
  state = newState;
  render();
});

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = titleInput.value.trim();
  if (!title) return;

  const newTask = {
    id: Date.now().toString(),
    title
  };

  state.todo.push(newTask);
  titleInput.value = "";
  render();
  socket.emit("task:created", state);
});
```

