const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", text: "Design app layout" },
        { id: "t2", text: "Set up database" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", text: "Build drag-and-drop" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "t4", text: "Create project scaffold" }
      ]
    }
  ]
};

io.on("connection", (socket) => {
  socket.emit("init", state);

  socket.on("move-task", ({ taskId, fromBoardId, toBoardId, toIndex }) => {
    const fromBoard = state.boards.find((b) => b.id === fromBoardId);
    const toBoard = state.boards.find((b) => b.id === toBoardId);
    if (!fromBoard || !toBoard) return;

    const taskIndex = fromBoard.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromBoard.tasks.splice(taskIndex, 1);

    const insertIndex =
      typeof toIndex === "number" && toIndex >= 0
        ? Math.min(toIndex, toBoard.tasks.length)
        : toBoard.tasks.length;

    toBoard.tasks.splice(insertIndex, 0, task);

    io.emit("state-updated", state);
  });

  socket.on("add-task", ({ boardId, text }) => {
    const board = state.boards.find((b) => b.id === boardId);
    if (!board || !text.trim()) return;

    board.tasks.push({
      id: "t" + Date.now() + Math.random().toString(16).slice(2),
      text: text.trim()
    });

    io.emit("state-updated", state);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
