```js
const socket = io();

const boardsEl = document.getElementById("boards");
const boardTemplate = document.getElementById("board-template");
const taskTemplate = document.getElementById("task-template");

let currentState = null;
let draggedTask = null;

socket.on("init", (state) => {
  currentState = state;
  render();
});

socket.on("state-updated", (state) => {
  currentState = state;
  render();
});

function render() {
  boardsEl.innerHTML = "";

  currentState.boards.forEach((board) => {
    const boardNode = boardTemplate.content.cloneNode(true);
    const section = boardNode.querySelector(".board");
    const title = boardNode.querySelector(".board-title");
    const list = boardNode.querySelector(".task-list");
    const form = boardNode.querySelector(".add-task-form");
    const input = form.querySelector("input");

    title.textContent = board.title;
    list.dataset.boardId = board.id;

    board.tasks.forEach((task, index) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      taskEl.textContent = task.text;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.boardId = board.id;
      taskEl.dataset.index = index;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromBoardId: board.id
        };
      });

      list.appendChild(taskNode);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      if (!draggedTask) return;

      const children = [...list.querySelectorAll(".task")];
      let toIndex = children.length;

      const targetTask = e.target.closest(".task");
      if (targetTask && targetTask.dataset.boardId === board.id) {
        toIndex = children.indexOf(targetTask);
      }

      socket.emit("move-task", {
        ...draggedTask,
        toBoardId: board.id,
        toIndex
      });

      draggedTask = null;
    });

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      socket.emit("add-task", {
        boardId: board.id,
        text: input.value
      });
      input.value = "";
    });

    boardsEl.appendChild(boardNode);
  });
}
```

