## 3) `server.js`

```js
import express from "express";
import { createServer } from "http";
import { Server } from "socket.io";

const app = express();
const server = createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let boards = {
  todo: [
    { id: "1", title: "Plan sprint" },
    { id: "2", title: "Set up repo" }
  ],
  doing: [
    { id: "3", title: "Build UI" }
  ],
  done: []
};

io.on("connection", (socket) => {
  // Send current state to new client
  socket.emit("init", boards);

  // Create task
  socket.on("create-task", (task) => {
    boards.todo.push(task);
    io.emit("state", boards);
  });

  // Move task
  socket.on("move-task", ({ taskId, from, to, index }) => {
    const taskIndex = boards[from].findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = boards[from].splice(taskIndex, 1);
    boards[to].splice(index, 0, task);

    io.emit("state", boards);
  });

  // Delete task
  socket.on("delete-task", ({ taskId, column }) => {
    boards[column] = boards[column].filter((t) => t.id !== taskId);
    io.emit("state", boards);
  });
});

server.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
```

