## 6) `public/app.js`

```js
const socket = io();

let boards = {
  todo: [],
  doing: [],
  done: []
};

const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");

socket.on("init", (state) => {
  boards = state;
  render();
});

socket.on("state", (state) => {
  boards = state;
  render();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;

  const task = {
    id: Date.now().toString(),
    title
  };

  socket.emit("create-task", task);
  taskInput.value = "";
});

function render() {
  ["todo", "doing", "done"].forEach((column) => {
    const list = document.getElementById(column);
    list.innerHTML = "";

    boards[column].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;
      taskEl.dataset.column = column;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <span>${task.title}</span>
        <button class="delete-btn">Delete</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", (e) => {
        e.stopPropagation();
        socket.emit("delete-task", { taskId: task.id, column });
      });

      list.appendChild(taskEl);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      const dragging = document.querySelector(".dragging");
      if (!dragging) return;

      const taskEls = [...list.querySelectorAll(".task:not(.dragging)")];
      const afterElement = getDragAfterElement(list, e.clientY);
      if (afterElement == null) {
        list.appendChild(dragging);
      } else {
        list.insertBefore(dragging, afterElement);
      }
    });

    list.addEventListener("drop", () => {
      const dragging = document.querySelector(".dragging");
      if (!dragging) return;

      const taskId = dragging.dataset.id;
      const from = dragging.dataset.column;
      const to = column;
      const index = [...list.querySelectorAll(".task")].indexOf(dragging);

      socket.emit("move-task", { taskId, from, to, index });
    });
  });
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY, element: null }
  ).element;
}
