## 3) server.js

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// Serve frontend
app.use(express.static(path.join(__dirname, "public")));

// In-memory app state
let state = {
  columns: [
    { id: "todo", title: "To Do", tasks: [
      { id: "task-1", title: "Set up project" },
      { id: "task-2", title: "Design UI" }
    ]},
    { id: "doing", title: "Doing", tasks: [
      { id: "task-3", title: "Build drag-and-drop" }
    ]},
    { id: "done", title: "Done", tasks: [
      { id: "task-4", title: "Create repo" }
    ]}
  ]
};

function broadcastState() {
  const payload = JSON.stringify({ type: "state", state });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(payload);
    }
  });
}

wss.on("connection", (ws) => {
  // Send current state on connect
  ws.send(JSON.stringify({ type: "state", state }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "move-task") {
        const { taskId, fromColumnId, toColumnId, toIndex } = data;

        const fromColumn = state.columns.find(c => c.id === fromColumnId);
        const toColumn = state.columns.find(c => c.id === toColumnId);
        if (!fromColumn || !toColumn) return;

        const taskIndex = fromColumn.tasks.findIndex(t => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromColumn.tasks.splice(taskIndex, 1);
        toColumn.tasks.splice(toIndex, 0, task);

        broadcastState();
      }

      if (data.type === "add-task") {
        const { columnId, title } = data;
        const column = state.columns.find(c => c.id === columnId);
        if (!column || !title) return;

        const newTask = {
          id: `task-${Date.now()}`,
          title
        };

        column.tasks.push(newTask);
        broadcastState();
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
