## 6) public/app.js

```js
const board = document.getElementById("board");
const statusEl = document.getElementById("status");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

let currentState = null;
let draggedTask = null;

const wsProtocol = location.protocol === "https:" ? "wss" : "ws";
const ws = new WebSocket(`${wsProtocol}://${location.host}`);

ws.addEventListener("open", () => {
  statusEl.textContent = "Connected";
});

ws.addEventListener("close", () => {
  statusEl.textContent = "Disconnected";
});

ws.addEventListener("message", (event) => {
  const data = JSON.parse(event.data);
  if (data.type === "state") {
    currentState = data.state;
    renderBoard();
  }
});

function renderBoard() {
  board.innerHTML = "";

  currentState.columns.forEach((column) => {
    const columnNode = columnTemplate.content.cloneNode(true);
    const columnEl = columnNode.querySelector(".column");
    const titleEl = columnNode.querySelector("h2");
    const taskListEl = columnNode.querySelector(".task-list");
    const formEl = columnNode.querySelector(".add-task-form");
    const inputEl = columnNode.querySelector("input");

    titleEl.textContent = `${column.title} (${column.tasks.length})`;

    column.tasks.forEach((task) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      const taskTitleEl = taskNode.querySelector(".task-title");

      taskTitleEl.textContent = task.title;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumnId: column.id
        };
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
        draggedTask = null;
      });

      taskListEl.appendChild(taskNode);
    });

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTask) return;

      const tasks = [...taskListEl.querySelectorAll(".task")];
      const toIndex = tasks.length;
      sendMoveTask(draggedTask.taskId, draggedTask.fromColumnId, column.id, toIndex);
    });

    formEl.addEventListener("submit", (e) => {
      e.preventDefault();
      const title = inputEl.value.trim();
      if (!title) return;
      ws.send(JSON.stringify({
        type: "add-task",
        columnId: column.id,
        title
      }));
      inputEl.value = "";
    });

    columnEl.appendChild(columnNode);
    board.appendChild(columnEl);
  });
}

function sendMoveTask(taskId, fromColumnId, toColumnId, toIndex) {
  ws.send(JSON.stringify({
    type: "move-task",
    taskId,
    fromColumnId,
    toColumnId,
    toIndex
  }));
}
```

