## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Plan sprint", description: "Define tasks for this week" },
      { id: "t2", title: "Design UI", description: "Create wireframes" }
    ],
    doing: [
      { id: "t3", title: "Build backend", description: "Set up API endpoints" }
    ],
    done: []
  }
};

function emitState() {
  io.emit("state:update", state);
}

io.on("connection", (socket) => {
  socket.emit("state:update", state);

  socket.on("task:move", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const source = state.columns[fromColumn];
    const target = state.columns[toColumn];
    if (!source || !target) return;

    const taskIndex = source.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = source.splice(taskIndex, 1);
    target.splice(toIndex, 0, task);

    emitState();
  });

  socket.on("task:add", ({ title, description }) => {
    const task = {
      id: `t_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      title,
      description
    };
    state.columns.todo.unshift(task);
    emitState();
  });

  socket.on("task:delete", ({ taskId }) => {
    for (const col of Object.keys(state.columns)) {
      const index = state.columns[col].findIndex((t) => t.id === taskId);
      if (index !== -1) {
        state.columns[col].splice(index, 1);
        emitState();
        return;
      }
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

