## 5) `public/app.js`

```js
const socket = io();

let currentState = null;
let draggedTask = null;

const board = document.getElementById("board");
const form = document.getElementById("newTaskForm");
const titleInput = document.getElementById("taskTitle");
const descriptionInput = document.getElementById("taskDescription");

const lists = {
  todo: document.getElementById("todoList"),
  doing: document.getElementById("doingList"),
  done: document.getElementById("doneList")
};

function render(state) {
  currentState = state;

  for (const column of Object.keys(lists)) {
    const list = lists[column];
    list.innerHTML = "";

    state.columns[column].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.column = column;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <button data-delete="${task.id}">Delete</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: column
        };
      });

      taskEl.querySelector("[data-delete]").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      list.appendChild(taskEl);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumn = column;
      const tasks = currentState.columns[toColumn];

      let toIndex = tasks.length;

      const afterElement = getDragAfterElement(list, e.clientY);
      if (afterElement) {
        toIndex = Number(afterElement.dataset.index);
      }

      socket.emit("task:move", {
        taskId: draggedTask.taskId,
        fromColumn: draggedTask.fromColumn,
        toColumn,
        toIndex
      });

      draggedTask = null;
    });
  }
}

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;

      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY, element: null }
  ).element;
}

form.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = titleInput.value.trim();
  const description = descriptionInput.value.trim();

  if (!title) return;

  socket.emit("task:add", { title, description });
  form.reset();
});

socket.on("state:update", (state) => {
  render(state);
});

function escapeHtml(text) {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

