const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let board = {
  todo: [
    { id: "1", title: "Set up project" },
    { id: "2", title: "Design UI" }
  ],
  doing: [
    { id: "3", title: "Build drag-and-drop" }
  ],
  done: [
    { id: "4", title: "Create repo" }
  ]
};

io.on("connection", (socket) => {
  socket.emit("board:init", board);

  socket.on("task:add", (task) => {
    board.todo.push(task);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, from, to, index }) => {
    const source = board[from];
    const target = board[to];
    if (!source || !target) return;

    const taskIndex = source.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = source.splice(taskIndex, 1);
    target.splice(index, 0, task);

    io.emit("board:update", board);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
