});

socket.on("board:update", (data) => {
  board = data;
  renderBoard();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;

  socket.emit("task:add", {
    id: Date.now().toString(),
