## 2) `server.js`

```js
const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const path = require('path');
const { randomUUID } = require('crypto');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, 'public')));

const initialState = {
  columns: [
    { id: 'todo', title: 'To Do', tasks: [] },
    { id: 'doing', title: 'In Progress', tasks: [] },
    { id: 'done', title: 'Done', tasks: [] }
  ]
};

let state = JSON.parse(JSON.stringify(initialState));

function broadcast() {
  const payload = JSON.stringify({ type: 'state', state });
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(payload);
    }
  });
}

wss.on('connection', ws => {
  ws.send(JSON.stringify({ type: 'state', state }));

  ws.on('message', message => {
    let data;
    try {
      data = JSON.parse(message.toString());
    } catch {
      return;
    }

    switch (data.type) {
      case 'addTask': {
        const { columnId, title } = data;
        const column = state.columns.find(c => c.id === columnId);
        if (!column || !title?.trim()) return;

        column.tasks.push({
          id: randomUUID(),
          title: title.trim()
        });

        broadcast();
        break;
      }

      case 'updateTask': {
        const { taskId, title } = data;
        if (!title?.trim()) return;

        for (const column of state.columns) {
          const task = column.tasks.find(t => t.id === taskId);
          if (task) {
            task.title = title.trim();
            broadcast();
            return;
          }
        }
        break;
      }

      case 'deleteTask': {
        const { taskId } = data;
        for (const column of state.columns) {
          const idx = column.tasks.findIndex(t => t.id === taskId);
          if (idx !== -1) {
            column.tasks.splice(idx, 1);
            broadcast();
            return;
          }
        }
        break;
      }

      case 'moveTask': {
        const { taskId, fromColumnId, toColumnId, toIndex } = data;
        const fromColumn = state.columns.find(c => c.id === fromColumnId);
        const toColumn = state.columns.find(c => c.id === toColumnId);
        if (!fromColumn || !toColumn) return;

        const fromIndex = fromColumn.tasks.findIndex(t => t.id === taskId);
        if (fromIndex === -1) return;

        const [task] = fromColumn.tasks.splice(fromIndex, 1);
        const insertIndex = Math.max(0, Math.min(toIndex ?? toColumn.tasks.length, toColumn.tasks.length));
        toColumn.tasks.splice(insertIndex, 0, task);

        broadcast();
        break;
      }

      case 'reset': {
        state = JSON.parse(JSON.stringify(initialState));
        broadcast();
        break;
      }
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Running on http://localhost:${PORT}`);
});
```

