## 5) `public/app.js`

```js
const boardEl = document.getElementById('board');
const columnTemplate = document.getElementById('columnTemplate');
const taskTemplate = document.getElementById('taskTemplate');

const newTaskTitle = document.getElementById('newTaskTitle');
const newTaskColumn = document.getElementById('newTaskColumn');
const addTaskBtn = document.getElementById('addTaskBtn');
const resetBtn = document.getElementById('resetBtn');

const ws = new WebSocket(`ws://${location.host}`);

let currentState = null;
let draggingTask = null;

ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.type === 'state') {
    currentState = msg.state;
    renderBoard();
  }
};

function send(message) {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(message));
  } else {
    ws.addEventListener('open', () => ws.send(JSON.stringify(message)), { once: true });
  }
}

function renderBoard() {
  if (!currentState) return;
  boardEl.innerHTML = '';

  currentState.columns.forEach(column => {
    const columnNode = columnTemplate.content.firstElementChild.cloneNode(true);
    columnNode.dataset.columnId = column.id;
    columnNode.querySelector('h2').textContent = column.title;

    const taskList = columnNode.querySelector('.task-list');

    column.tasks.forEach((task, index) => {
      const taskNode = taskTemplate.content.firstElementChild.cloneNode(true);
      taskNode.dataset.taskId = task.id;
      taskNode.dataset.columnId = column.id;
      taskNode.dataset.index = index;

      const input = taskNode.querySelector('.task-title');
      input.value = task.title;

      taskNode.addEventListener('dragstart', () => {
        draggingTask = {
          taskId: task.id,
          fromColumnId: column.id,
          fromIndex: index
        };
        taskNode.classList.add('dragging');
      });

      taskNode.addEventListener('dragend', () => {
        draggingTask = null;
        taskNode.classList.remove('dragging');
        document.querySelectorAll('.column').forEach(c => c.classList.remove('drag-over'));
      });

      taskNode.querySelector('.save-btn').addEventListener('click', () => {
        send({
          type: 'updateTask',
          taskId: task.id,
          title: input.value
        });
      });

      taskNode.querySelector('.delete-btn').addEventListener('click', () => {
        send({
          type: 'deleteTask',
          taskId: task.id
        });
      });

      taskList.appendChild(taskNode);
    });

    columnNode.addEventListener('dragover', e => {
      e.preventDefault();
      columnNode.classList.add('drag-over');
    });

    columnNode.addEventListener('dragleave', () => {
      columnNode.classList.remove('drag-over');
    });

    columnNode.addEventListener('drop', e => {
      e.preventDefault();
      columnNode.classList.remove('drag-over');
      if (!draggingTask) return;

      const tasks = [...columnNode.querySelectorAll('.task')];
      const target = e.target.closest('.task');
      const toIndex = target ? tasks.indexOf(target) : tasks.length;

      send({
        type: 'moveTask',
        taskId: draggingTask.taskId,
        fromColumnId: draggingTask.fromColumnId,
        toColumnId: column.id,
        toIndex
      });
    });

    boardEl.appendChild(columnNode);
  });
}

addTaskBtn.addEventListener('click', () => {
  const title = newTaskTitle.value.trim();
  const columnId = newTaskColumn.value;
  if (!title) return;

  send({
    type: 'addTask',
    columnId,
    title
  });

  newTaskTitle.value = '';
  newTaskTitle.focus();
});

newTaskTitle.addEventListener('keydown', e => {
  if (e.key === 'Enter') addTaskBtn.click();
});

resetBtn.addEventListener('click', () => {
  send({ type: 'reset' });
});
