```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  tasks: [
    { id: "1", title: "Create project plan", status: "todo" },
    { id: "2", title: "Set up authentication", status: "doing" },
    { id: "3", title: "Deploy app", status: "done" }
  ]
};

function broadcast() {
  const message = JSON.stringify({ type: "state", payload: state });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", payload: state }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw);

      if (msg.type === "updateTask") {
        const { id, updates } = msg.payload;
        state.tasks = state.tasks.map((task) =>
          task.id === id ? { ...task, ...updates } : task
        );
        broadcast();
      }

      if (msg.type === "addTask") {
        const { title, status } = msg.payload;
        const newTask = {
          id: String(Date.now()),
          title,
          status: status || "todo"
        };
        state.tasks.push(newTask);
        broadcast();
      }

      if (msg.type === "deleteTask") {
        const { id } = msg.payload;
        state.tasks = state.tasks.filter((task) => task.id !== id);
        broadcast();
      }
    } catch (e) {
      console.error("Invalid message:", e);
    }
  });
});

server.listen(3000, () => {
  console.log("App running at http://localhost:3000");
});
```

