# 6) Frontend: `public/app.js`

```js
const socket = new WebSocket(`ws://${location.host}`);

let tasks = [];

const todo = document.getElementById("todo");
const doing = document.getElementById("doing");
const done = document.getElementById("done");
const form = document.getElementById("newTaskForm");
const input = document.getElementById("newTaskInput");

function render() {
  todo.innerHTML = "";
  doing.innerHTML = "";
  done.innerHTML = "";

  tasks.forEach((task) => {
    const el = document.createElement("div");
    el.className = "task";
    el.draggable = true;
    el.dataset.id = task.id;
    el.textContent = task.title;

    const del = document.createElement("button");
    del.className = "delete-btn";
    del.textContent = "X";
    del.onclick = (e) => {
      e.stopPropagation();
      socket.send(JSON.stringify({ type: "deleteTask", payload: { id: task.id } }));
    };

    el.appendChild(del);

    el.addEventListener("dragstart", () => {
      el.classList.add("dragging");
      el.dataset.dragging = "true";
      window.draggedTaskId = task.id;
    });

    el.addEventListener("dragend", () => {
      el.classList.remove("dragging");
      window.draggedTaskId = null;
    });

    if (task.status === "todo") todo.appendChild(el);
    if (task.status === "doing") doing.appendChild(el);
    if (task.status === "done") done.appendChild(el);
  });
}

socket.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.type === "state") {
    tasks = msg.payload.tasks;
    render();
  }
});

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = input.value.trim();
  if (!title) return;

  socket.send(JSON.stringify({
    type: "addTask",
    payload: { title, status: "todo" }
  }));

  input.value = "";
});

document.querySelectorAll(".column").forEach((column) => {
  column.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.classList.add("drag-over");
  });

  column.addEventListener("dragleave", () => {
    column.classList.remove("drag-over");
  });

  column.addEventListener("drop", (e) => {
    e.preventDefault();
    column.classList.remove("drag-over");

    const id = window.draggedTaskId;
    const status = column.dataset.status;

    if (id && status) {
      socket.send(JSON.stringify({
        type: "updateTask",
        payload: { id, updates: { status } }
      }));
    }
  });
});
