```js
const socket = new WebSocket(`ws://${location.host}`);

let state = { tasks: [] };

const todo = document.getElementById("todo");
const doing = document.getElementById("doing");
const done = document.getElementById("done");
const taskInput = document.getElementById("taskInput");
const addTaskBtn = document.getElementById("addTaskBtn");

function render() {
  todo.innerHTML = "";
  doing.innerHTML = "";
  done.innerHTML = "";

  state.tasks.forEach((task) => {
    const el = document.createElement("div");
    el.className = "task";
    el.draggable = true;
    el.dataset.id = task.id;
    el.textContent = task.title;

    el.addEventListener("dragstart", () => {
      el.classList.add("dragging");
      socket._dragTaskId = task.id;
    });

    el.addEventListener("dragend", () => {
      el.classList.remove("dragging");
    });

    const target = document.getElementById(task.status);
    target.appendChild(el);
  });
}

socket.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.type === "state") {
    state = msg.payload;
    render();
  }
});

addTaskBtn.addEventListener("click", () => {
  const title = taskInput.value.trim();
  if (!title) return;
  socket.send(JSON.stringify({ type: "add-task", title }));
  taskInput.value = "";
});

taskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

document.querySelectorAll(".column").forEach((column) => {
  column.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.classList.add("drag-over");
  });

  column.addEventListener("dragleave", () => {
    column.classList.remove("drag-over");
  });

  column.addEventListener("drop", (e) => {
    e.preventDefault();
    column.classList.remove("drag-over");
    const status = column.dataset.status;
    const taskId = socket._dragTaskId;
    if (taskId) {
      socket.send(JSON.stringify({ type: "move-task", taskId, status }));
    }
  });
});
```

