## 3) `server.js`

```js
const express = require('express');
const http = require('http');
const { Server } = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static('public'));

let boardState = {
  todo: [
    { id: '1', title: 'Set up project', description: '' },
    { id: '2', title: 'Design UI', description: '' }
  ],
  doing: [
    { id: '3', title: 'Build drag-and-drop', description: '' }
  ],
  done: []
};

io.on('connection', (socket) => {
  socket.emit('board-state', boardState);

  socket.on('add-task', (task) => {
    boardState[task.status].push(task);
    io.emit('board-state', boardState);
  });

  socket.on('move-task', ({ taskId, from, to, toIndex }) => {
    const taskIndex = boardState[from].findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = boardState[from].splice(taskIndex, 1);
    boardState[to].splice(toIndex, 0, task);

    io.emit('board-state', boardState);
  });

  socket.on('delete-task', ({ taskId, status }) => {
    boardState[status] = boardState[status].filter((t) => t.id !== taskId);
    io.emit('board-state', boardState);
  });

  socket.on('reset-board', () => {
    boardState = { todo: [], doing: [], done: [] };
    io.emit('board-state', boardState);
  });
});

server.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});
```

