## 6) `public/app.js`

```js
const socket = io();

const taskTitleInput = document.getElementById('taskTitle');
const taskStatusSelect = document.getElementById('taskStatus');
const addTaskBtn = document.getElementById('addTaskBtn');
const resetBtn = document.getElementById('resetBtn');

const columns = {
  todo: document.getElementById('todo'),
  doing: document.getElementById('doing'),
  done: document.getElementById('done')
};

let boardState = {};

function renderBoard(state) {
  boardState = state;

  Object.keys(columns).forEach((status) => {
    const container = columns[status];
    container.innerHTML = '';

    state[status].forEach((task, index) => {
      const taskEl = document.createElement('div');
      taskEl.className = 'task';
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;
      taskEl.dataset.status = status;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <div class="title">${escapeHtml(task.title)}</div>
        <div class="actions">
          <button class="delete">Delete</button>
        </div>
      `;

      taskEl.addEventListener('dragstart', (e) => {
        taskEl.classList.add('dragging');
        e.dataTransfer.setData('text/plain', JSON.stringify({
          taskId: task.id,
          from: status
        }));
      });

      taskEl.addEventListener('dragend', () => {
        taskEl.classList.remove('dragging');
      });

      taskEl.querySelector('.delete').addEventListener('click', () => {
        socket.emit('delete-task', { taskId: task.id, status });
      });

      container.appendChild(taskEl);
    });
  });
}

function escapeHtml(str) {
  return str.replace(/[&<>"']/g, (m) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;'
  }[m]));
}

function createTask() {
  const title = taskTitleInput.value.trim();
  const status = taskStatusSelect.value;

  if (!title) return;

  const task = {
    id: crypto.randomUUID(),
    title,
    description: '',
    status
  };

  socket.emit('add-task', task);
  taskTitleInput.value = '';
}

addTaskBtn.addEventListener('click', createTask);

taskTitleInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') createTask();
});

resetBtn.addEventListener('click', () => {
  socket.emit('reset-board');
});

Object.values(columns).forEach((container) => {
  container.addEventListener('dragover', (e) => {
    e.preventDefault();
    container.classList.add('drag-over');
  });

  container.addEventListener('dragleave', () => {
    container.classList.remove('drag-over');
  });

  container.addEventListener('drop', (e) => {
    e.preventDefault();
    container.classList.remove('drag-over');

    const data = JSON.parse(e.dataTransfer.getData('text/plain'));
    const toStatus = container.id;
    const toIndex = boardState[toStatus].length;

    if (data.from === toStatus) return;

    socket.emit('move-task', {
      taskId: data.taskId,
      from: data.from,
      to: toStatus,
      toIndex
    });
  });
});

socket.on('board-state', (state) => {
  renderBoard(state);
});
```

