## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

// Minimal in-memory board state
let board = {
  todo: [
    { id: "t1", title: "Set up project" },
    { id: "t2", title: "Create task board UI" }
  ],
  doing: [
    { id: "t3", title: "Add drag and drop" }
  ],
  done: [
    { id: "t4", title: "Initial planning" }
  ]
};

io.on("connection", (socket) => {
  // Send current board state to new client
  socket.emit("board:update", board);

  // Update from any client and broadcast to all clients
  socket.on("task:moved", ({ taskId, from, to, newIndex }) => {
    const fromList = board[from];
    const toList = board[to];
    if (!fromList || !toList) return;

    const idx = fromList.findIndex((t) => t.id === taskId);
    if (idx === -1) return;

    const [task] = fromList.splice(idx, 1);
    if (typeof newIndex !== "number" || newIndex < 0 || newIndex > toList.length) {
      newIndex = toList.length;
    }
    toList.splice(newIndex, 0, task);

    io.emit("board:update", board);
  });

  socket.on("task:add", ({ column, title }) => {
    if (!board[column]) return;
    const task = { id: `t${Date.now()}`, title };
    board[column].push(task);
    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId }) => {
    for (const col of Object.keys(board)) {
      const idx = board[col].findIndex((t) => t.id === taskId);
      if (idx !== -1) {
        board[col].splice(idx, 1);
        io.emit("board:update", board);
        break;
      }
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

