## 6) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const addForm = document.getElementById("addForm");
const taskTitle = document.getElementById("taskTitle");
const taskColumn = document.getElementById("taskColumn");

let currentBoard = {};

socket.on("board:update", (board) => {
  currentBoard = board;
  renderBoard(board);
});

addForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskTitle.value.trim();
  const column = taskColumn.value;
  if (!title) return;

  socket.emit("task:add", { column, title });
  taskTitle.value = "";
});

function renderBoard(board) {
  ["todo", "doing", "done"].forEach((col) => {
    const list = document.getElementById(col);
    list.innerHTML = "";

    board[col].forEach((task, index) => {
      const div = document.createElement("div");
      div.className = "task";
      div.draggable = true;
      div.dataset.id = task.id;
      div.dataset.column = col;
      div.dataset.index = index;

      div.innerHTML = `
        <span>${escapeHtml(task.title)}</span>
        <button title="Delete">×</button>
      `;

      div.addEventListener("dragstart", onDragStart);
      div.querySelector("button").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      list.appendChild(div);
    });

    list.addEventListener("dragover", onDragOver);
    list.addEventListener("dragleave", onDragLeave);
    list.addEventListener("drop", onDrop);
  });
}

let draggedTask = null;

function onDragStart(e) {
  draggedTask = {
    taskId: e.currentTarget.dataset.id,
    from: e.currentTarget.dataset.column
  };
}

function onDragOver(e) {
  e.preventDefault();
  e.currentTarget.classList.add("drag-over");
}

function onDragLeave(e) {
  e.currentTarget.classList.remove("drag-over");
}

function onDrop(e) {
  e.preventDefault();
  const to = e.currentTarget.id;
  e.currentTarget.classList.remove("drag-over");

  if (!draggedTask || draggedTask.from === to) {
    draggedTask = null;
    return;
  }

  const newIndex = currentBoard[to] ? currentBoard[to].length : 0;
  socket.emit("task:moved", {
    taskId: draggedTask.taskId,
    from: draggedTask.from,
    to,
    newIndex
  });

  draggedTask = null;
}

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}
