## 3) `server.js`

```js
import express from "express";
import { createServer } from "http";
import { WebSocketServer } from "ws";

const app = express();
const server = createServer(app);
const wss = new WebSocketServer({ server });

app.use(express.static("public"));

const initialState = {
  columns: {
    todo: [
      { id: "task-1", title: "Set up project", description: "Initialize app" },
      { id: "task-2", title: "Design UI", description: "Create board layout" }
    ],
    doing: [
      { id: "task-3", title: "Implement drag-and-drop", description: "Move cards between columns" }
    ],
    done: []
  }
};

let boardState = structuredClone(initialState);

function broadcastState() {
  const message = JSON.stringify({
    type: "state",
    state: boardState
  });

  wss.clients.forEach((client) => {
    if (client.readyState === 1) client.send(message);
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", state: boardState }));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === "move-task") {
        const { taskId, fromColumn, toColumn, toIndex } = msg;

        const fromTasks = boardState.columns[fromColumn];
        const toTasks = boardState.columns[toColumn];
        if (!fromTasks || !toTasks) return;

        const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromTasks.splice(taskIndex, 1);
        toTasks.splice(toIndex, 0, task);

        broadcastState();
      }

      if (msg.type === "add-task") {
        const { columnId, title } = msg;
        if (!boardState.columns[columnId]) return;

        boardState.columns[columnId].push({
          id: `task-${Date.now()}`,
          title: title || "New Task",
          description: ""
        });

        broadcastState();
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

server.listen(3000, () => {
  console.log("Project board running on http://localhost:3000");
});
```

