## 6) `public/app.js`

```js
const boardEl = document.getElementById("board");
const statusEl = document.getElementById("status");

let state = null;
let draggedTask = null;

const ws = new WebSocket(`ws://${location.host}`);

ws.onopen = () => {
  statusEl.textContent = "Connected";
};

ws.onclose = () => {
  statusEl.textContent = "Disconnected";
};

ws.onerror = () => {
  statusEl.textContent = "Connection error";
};

ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);

  if (msg.type === "state") {
    state = msg.state;
    render();
  }
};

function send(message) {
  ws.send(JSON.stringify(message));
}

function render() {
  if (!state) return;

  boardEl.innerHTML = "";

  const columns = [
    { id: "todo", title: "To Do" },
    { id: "doing", title: "Doing" },
    { id: "done", title: "Done" }
  ];

  for (const column of columns) {
    const colEl = document.createElement("section");
    colEl.className = "column";
    colEl.dataset.columnId = column.id;

    const heading = document.createElement("h2");
    heading.textContent = column.title;

    const list = document.createElement("div");
    list.className = "task-list";
    list.dataset.columnId = column.id;

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drop-target");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drop-target");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drop-target");

      if (!draggedTask) return;

      const tasks = state.columns[column.id];
      const toIndex = tasks.length;

      send({
        type: "move-task",
        taskId: draggedTask.taskId,
        fromColumn: draggedTask.fromColumn,
        toColumn: column.id,
        toIndex
      });

      draggedTask = null;
    });

    for (const task of state.columns[column.id]) {
      const taskEl = document.createElement("article");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = { taskId: task.id, fromColumn: column.id };
      });

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
      `;

      list.appendChild(taskEl);
    }

    const form = document.createElement("div");
    form.className = "add-task";
    form.innerHTML = `
      <input type="text" placeholder="Add task..." />
      <button>Add</button>
    `;

    const input = form.querySelector("input");
    const button = form.querySelector("button");

    button.addEventListener("click", () => {
      if (!input.value.trim()) return;
      send({
        type: "add-task",
        columnId: column.id,
        title: input.value.trim()
      });
      input.value = "";
    });

    colEl.appendChild(heading);
    colEl.appendChild(list);
    colEl.appendChild(form);
    boardEl.appendChild(colEl);
  }
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

