## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

/**
 * In-memory board state.
 * For a real app, persist this to a DB.
 */
let board = {
  columns: {
    todo: [
      { id: "task-1", title: "Set up project", description: "Initialize app" },
      { id: "task-2", title: "Design board", description: "Create basic layout" }
    ],
    doing: [
      { id: "task-3", title: "Implement drag-and-drop", description: "Use HTML5 DnD" }
    ],
    done: []
  }
};

io.on("connection", (socket) => {
  // Send current board state to newly connected user
  socket.emit("board:init", board);

  // When a task is moved, update state and broadcast to everyone
  socket.on("task:move", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const fromTasks = board.columns[fromColumn];
    const toTasks = board.columns[toColumn];

    const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromTasks.splice(taskIndex, 1);

    // insert at specific index or push to end
    if (typeof toIndex === "number" && toIndex >= 0 && toIndex <= toTasks.length) {
      toTasks.splice(toIndex, 0, task);
    } else {
      toTasks.push(task);
    }

    io.emit("board:update", board);
  });

  // Add a new task
  socket.on("task:add", ({ columnId, title, description }) => {
    const newTask = {
      id: `task-${Date.now()}`,
      title,
      description
    };
    board.columns[columnId].push(newTask);
    io.emit("board:update", board);
  });

  // Delete a task
  socket.on("task:delete", ({ taskId, columnId }) => {
    board.columns[columnId] = board.columns[columnId].filter((t) => t.id !== taskId);
    io.emit("board:update", board);
  });

  // Reset board (optional quick dev feature)
  socket.on("board:reset", () => {
    board = {
      columns: {
        todo: [],
        doing: [],
        done: []
      }
    };
    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

