## 5) `public/app.js`

```js
const socket = io();

let boardState = null;
let draggedTask = null;

const columns = ["todo", "doing", "done"];

const addTaskBtn = document.getElementById("addTaskBtn");
const resetBtn = document.getElementById("resetBtn");
const taskTitle = document.getElementById("taskTitle");
const taskDesc = document.getElementById("taskDesc");
const taskColumn = document.getElementById("taskColumn");

function renderBoard(board) {
  boardState = board;

  columns.forEach((columnId) => {
    const listEl = document.getElementById(columnId);
    listEl.innerHTML = "";

    const tasks = board.columns[columnId];

    tasks.forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="task-actions">
          <button class="delete-btn">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", (e) => {
        draggedTask = {
          taskId: task.id,
          fromColumn: columnId
        };
        e.dataTransfer.setData("text/plain", task.id);
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId });
      });

      listEl.appendChild(taskEl);
    });

    addDropHandlers(listEl, columnId);
  });
}

function addDropHandlers(listEl, columnId) {
  listEl.ondragover = (e) => {
    e.preventDefault();
    listEl.classList.add("drag-over");
  };

  listEl.ondragleave = () => {
    listEl.classList.remove("drag-over");
  };

  listEl.ondrop = (e) => {
    e.preventDefault();
    listEl.classList.remove("drag-over");

    if (!draggedTask) return;

    const targetIndex = Array.from(listEl.children).length;
    socket.emit("task:move", {
      taskId: draggedTask.taskId,
      fromColumn: draggedTask.fromColumn,
      toColumn: columnId,
      toIndex: targetIndex
    });

    draggedTask = null;
  };
}

addTaskBtn.addEventListener("click", () => {
  const title = taskTitle.value.trim();
  const description = taskDesc.value.trim();
  const columnId = taskColumn.value;

  if (!title) return;

  socket.emit("task:add", { columnId, title, description });

  taskTitle.value = "";
  taskDesc.value = "";
  taskTitle.focus();
});

resetBtn.addEventListener("click", () => {
  socket.emit("board:reset");
});

socket.on("board:init", (board) => {
  renderBoard(board);
});

socket.on("board:update", (board) => {
  renderBoard(board);
});

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
