const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      cards: [
        { id: "1", title: "Design app layout" },
        { id: "2", title: "Set up backend" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      cards: [
        { id: "3", title: "Build drag-and-drop" }
      ]
    },
    {
      id: "done",
      title: "Done",
      cards: []
    }
  ]
};

io.on("connection", (socket) => {
  // Send current state to new client
  socket.emit("boardState", boardState);

  // Receive updates from any client and broadcast to all
  socket.on("moveCard", ({ cardId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = boardState.columns.find(c => c.id === fromColumnId);
    const toColumn = boardState.columns.find(c => c.id === toColumnId);

    if (!fromColumn || !toColumn) return;

    const cardIndex = fromColumn.cards.findIndex(card => card.id === cardId);
    if (cardIndex === -1) return;

    const [card] = fromColumn.cards.splice(cardIndex, 1);
    toColumn.cards.splice(toIndex, 0, card);

    io.emit("boardState", boardState);
  });

  socket.on("addCard", ({ columnId, title }) => {
    const column = boardState.columns.find(c => c.id === columnId);
    if (!column || !title.trim()) return;

    const newCard = {
      id: Date.now().toString(),
      title: title.trim()
    };

    column.cards.push(newCard);
    io.emit("boardState", boardState);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
