```js
const socket = io();
const boardEl = document.getElementById("board");

let boardState = null;
let draggedCard = null;

socket.on("boardState", (state) => {
  boardState = state;
  renderBoard();
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <div class="column-header">${column.title}</div>
      <div class="cards" data-column-id="${column.id}"></div>
      <form class="add-card" data-column-id="${column.id}">
        <input type="text" placeholder="New task..." />
        <button type="submit">Add</button>
      </form>
    `;

    const cardsEl = columnEl.querySelector(".cards");

    column.cards.forEach((card) => {
      const cardEl = document.createElement("div");
      cardEl.className = "card";
      cardEl.draggable = true;
      cardEl.dataset.cardId = card.id;
      cardEl.dataset.columnId = column.id;
      cardEl.textContent = card.title;

      cardEl.addEventListener("dragstart", (e) => {
        draggedCard = {
          cardId: card.id,
          fromColumnId: column.id
        };
        e.dataTransfer.setData("text/plain", card.id);
      });

      cardsEl.appendChild(cardEl);
    });

    cardsEl.addEventListener("dragover", (e) => e.preventDefault());

    cardsEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedCard) return;

      const targetCards = [...cardsEl.querySelectorAll(".card")];
      const dropIndex = targetCards.length;

      socket.emit("moveCard", {
        cardId: draggedCard.cardId,
        fromColumnId: draggedCard.fromColumnId,
        toColumnId: column.id,
        toIndex: dropIndex
      });

      draggedCard = null;
    });

    cardsEl.addEventListener("dragenter", () => {
      cardsEl.classList.add("drop-zone");
    });

    cardsEl.addEventListener("dragleave", () => {
      cardsEl.classList.remove("drop-zone");
    });

    cardsEl.addEventListener("dragend", () => {
      cardsEl.classList.remove("drop-zone");
    });

    const form = columnEl.querySelector(".add-card");
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const input = form.querySelector("input");
      const title = input.value;
      if (!title.trim()) return;

      socket.emit("addCard", {
        columnId: column.id,
        title
      });

      input.value = "";
    });

    boardEl.appendChild(columnEl);
  });
}
```

