## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let boards = [
  {
    id: "todo",
    title: "To Do",
    tasks: [
      { id: "t1", text: "Design UI" },
      { id: "t2", text: "Set up backend" }
    ]
  },
  {
    id: "doing",
    title: "In Progress",
    tasks: [
      { id: "t3", text: "Implement drag-and-drop" }
    ]
  },
  {
    id: "done",
    title: "Done",
    tasks: [
      { id: "t4", text: "Create project repo" }
    ]
  }
];

io.on("connection", (socket) => {
  socket.emit("init", boards);

  socket.on("addTask", ({ boardId, text }) => {
    const board = boards.find((b) => b.id === boardId);
    if (!board) return;

    board.tasks.push({
      id: `task-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      text
    });

    io.emit("boardsUpdated", boards);
  });

  socket.on("moveTask", ({ taskId, fromBoardId, toBoardId, toIndex }) => {
    const fromBoard = boards.find((b) => b.id === fromBoardId);
    const toBoard = boards.find((b) => b.id === toBoardId);
    if (!fromBoard || !toBoard) return;

    const taskIndex = fromBoard.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromBoard.tasks.splice(taskIndex, 1);
    toBoard.tasks.splice(toIndex, 0, task);

    io.emit("boardsUpdated", boards);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected");
  });
});

server.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
```

