## 6) `public/app.js`

```js
const socket = io();

const boardsEl = document.getElementById("boards");
const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");
const boardSelect = document.getElementById("boardSelect");

let boards = [];

socket.on("init", (initialBoards) => {
  boards = initialBoards;
  renderBoards();
});

socket.on("boardsUpdated", (updatedBoards) => {
  boards = updatedBoards;
  renderBoards();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const text = taskInput.value.trim();
  const boardId = boardSelect.value;

  if (!text) return;

  socket.emit("addTask", { boardId, text });
  taskInput.value = "";
});

function renderBoards() {
  boardsEl.innerHTML = "";

  boards.forEach((board) => {
    const boardDiv = document.createElement("section");
    boardDiv.className = "board";
    boardDiv.innerHTML = `<h2>${board.title}</h2>`;

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.boardId = board.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();

      const taskId = e.dataTransfer.getData("text/task-id");
      const fromBoardId = e.dataTransfer.getData("text/from-board");
      const toBoardId = board.id;

      const targetTasks = board.tasks;
      const toIndex = targetTasks.length;

      socket.emit("moveTask", {
        taskId,
        fromBoardId,
        toBoardId,
        toIndex
      });
    });

    board.tasks.forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.textContent = task.text;

      taskEl.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/task-id", task.id);
        e.dataTransfer.setData("text/from-board", board.id);
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskList.appendChild(taskEl);
    });

    boardDiv.appendChild(taskList);
    boardsEl.appendChild(boardDiv);
  });
}
