# 6) Event bus

For now, we use a cheap in-process bus. Later you can swap this for Kafka/NATS.

## `src/bus.rs`

```rust
use tokio::sync::mpsc;

pub struct Bus<T> {
    sender: mpsc::Sender<T>,
}

pub struct BusReceiver<T> {
    receiver: mpsc::Receiver<T>,
}

impl<T> Bus<T> {
    pub fn new(buffer: usize) -> (Self, BusReceiver<T>) {
        let (tx, rx) = mpsc::channel(buffer);
        (Self { sender: tx }, BusReceiver { receiver: rx })
    }

    pub fn sender(&self) -> mpsc::Sender<T> {
        self.sender.clone()
    }
}

impl<T> BusReceiver<T> {
    pub async fn recv(&mut self) -> Option<T> {
        self.receiver.recv().await
    }
}
```

