pub async fn run_market_data_publisher(tx: mpsc::Sender<MarketTick>) {
    let symbols = vec!["AAPL", "MSFT", "NVDA", "TSLA"];

    loop {
        for sym in symbols.iter() {
            let tick = MarketTick {
                symbol: sym.to_string(),
                price: 100.0 + rand_price_jitter(),
                qty: 100.0,
                ts_nanos: now_nanos(),
            };

            if tx.send(tick).await.is_err() {
                return;
            }
        }

        sleep(Duration::from_millis(10)).await;
    }
}

fn rand_price_jitter() -> f64 {
