# 9) Risk engine

Pre-trade checks: max qty, notional limits, symbol restrictions.

## `src/risk.rs`

```rust
use crate::types::{OrderRequest, OrderStatus};
use std::collections::HashMap;
use tokio::sync::mpsc;

#[derive(Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

pub async fn run_risk_engine(
    mut rx: mpsc::Receiver<OrderRequest>,
    tx: mpsc::Sender<(OrderRequest, OrderStatus)>,
    limits: RiskLimits,
) {
    while let Some(order) = rx.recv().await {
        let status = check_order(&order, &limits);
        let _ = tx.send((order, status)).await;
    }
}

fn check_order(order: &OrderRequest, limits: &RiskLimits) -> OrderStatus {
    if order.qty <= 0.0 {
        return OrderStatus::Rejected("qty must be positive".into());
    }

    if order.qty > limits.max_order_qty {
        return OrderStatus::Rejected(format!("qty exceeds limit {}", limits.max_order_qty));
    }

    let notional = match &order.order_type {
        crate::types::OrderType::Market => 100.0 * order.qty, // placeholder
        crate::types::OrderType::Limit { price } => price * order.qty,
    };

    if notional > limits.max_notional {
        return OrderStatus::Rejected(format!("notional exceeds limit {}", limits.max_notional));
    }

    OrderStatus::Accepted
}
```

