# 10) OMS: order management

Tracks order lifecycle; forwards accepted orders to execution.

## `src/oms.rs`

```rust
use crate::types::{OrderEvent, OrderRequest, OrderStatus};
use dashmap::DashMap;
use tokio::sync::mpsc;
use uuid::Uuid;

#[derive(Clone)]
pub struct OrderStore {
    pub statuses: DashMap<Uuid, OrderStatus>,
}

impl OrderStore {
    pub fn new() -> Self {
        Self {
            statuses: DashMap::new(),
        }
    }

    pub fn update(&self, order_id: Uuid, status: OrderStatus) {
        self.statuses.insert(order_id, status);
    }
}

pub async fn run_oms(
    mut rx: mpsc::Receiver<(OrderRequest, OrderStatus)>,
    tx_exec: mpsc::Sender<OrderRequest>,
    store: OrderStore,
    event_tx: mpsc::Sender<OrderEvent>,
) {
    while let Some((order, status)) = rx.recv().await {
        store.update(order.id, status.clone());

        let evt = OrderEvent {
            order_id: order.id,
            status: status.clone(),
            ts_nanos: now_nanos(),
        };
        let _ = event_tx.send(evt).await;

        if matches!(status, OrderStatus::Accepted) {
            store.update(order.id, OrderStatus::Sent);
            let _ = tx_exec.send(order).await;
        }
    }
}

fn now_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
```

