use crate::types::{OrderEvent, OrderRequest, OrderStatus};
use tokio::sync::mpsc;

pub async fn run_execution_gateway(
    mut rx: mpsc::Receiver<OrderRequest>,
    event_tx: mpsc::Sender<OrderEvent>,
) {
    while let Some(order) = rx.recv().await {
        // Simulate exchange latency
        tokio::time::sleep(std::time::Duration::from_millis(5)).await;

        let fill_event = OrderEvent {
            order_id: order.id,
            status: OrderStatus::Filled {
                avg_price: 100.0,
                filled_qty: order.qty,
            },
            ts_nanos: now_nanos(),
        };

        let _ = event_tx.send(fill_event).await;
    }
}

fn now_nanos() -> u128 {
