use tracing::info;

pub async fn run_metrics(mut rx: mpsc::Receiver<OrderEvent>) {
    let mut count = 0u64;

    while let Some(evt) = rx.recv().await {
        count += 1;
        info!("order_event count={} event={:?}", count, evt);
    }
}
