mod types;

use crate::oms::OrderStore;
use crate::risk::RiskLimits;
use crate::types::{MarketTick, OrderEvent, OrderRequest, OrderType, Signal};
use tokio::sync::mpsc;
use tracing_subscriber::EnvFilter;
use uuid::Uuid;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let (md_tx, md_rx) = mpsc::channel::<MarketTick>(2048);
    let (sig_tx, mut sig_rx) = mpsc::channel::<Signal>(1024);
    let (risk_tx, risk_rx) = mpsc::channel::<OrderRequest>(1024);
    let (oms_exec_tx, oms_exec_rx) = mpsc::channel::<OrderRequest>(1024);
    let (risk_result_tx, risk_result_rx) = mpsc::channel::<(OrderRequest, crate::types::OrderStatus)>(1024);
    let (event_tx, event_rx) = mpsc::channel::<OrderEvent>(4096);

    let store = OrderStore::new();
    let limits = RiskLimits {
        max_order_qty: 1000.0,
        max_notional: 100_000.0,
    };

    tokio::spawn(market_data::run_market_data_publisher(md_tx));
    tokio::spawn(strategy::run_strategy(md_rx, sig_tx));
    tokio::spawn(async move {
        while let Some(sig) = sig_rx.recv().await {
            let order = OrderRequest {
                id: Uuid::new_v4(),
                symbol: sig.symbol,
                side: sig.side,
                qty: sig.qty,
                order_type: OrderType::Market,
                ts_nanos: now_nanos(),
            };

            let _ = risk_tx.send(order).await;
        }
    });

    tokio::spawn(risk::run_risk_engine(risk_rx, risk_result_tx, limits));
    tokio::spawn(oms::run_oms(risk_result_rx, oms_exec_tx, store.clone(), event_tx.clone()));
    tokio::spawn(execution::run_execution_gateway(oms_exec_rx, event_tx));
    tokio::spawn(metrics::run_metrics(event_rx));

    // Keep the process alive
    tokio::signal::ctrl_c().await.unwrap();
}

fn now_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
