# Fast in-memory bus

This is a minimal pub/sub bus. For production scaling, replace with Kafka/NATS/Redis Streams depending on latency vs durability requirements.

```go
// internal/bus/bus.go
package bus

import (
	"sync"
)

type Topic[T any] struct {
	mu   sync.RWMutex
	subs []chan T
}

func NewTopic[T any]() *Topic[T] {
	return &Topic[T]{subs: make([]chan T, 0, 16)}
}

func (t *Topic[T]) Subscribe(buffer int) <-chan T {
	ch := make(chan T, buffer)

	t.mu.Lock()
	t.subs = append(t.subs, ch)
	t.mu.Unlock()

	return ch
}

func (t *Topic[T]) Publish(msg T) {
	t.mu.RLock()
	subs := make([]chan T, len(t.subs))
	copy(subs, t.subs)
	t.mu.RUnlock()

	for _, ch := range subs {
		select {
		case ch <- msg:
		default:
			// Drop or route to overflow handling depending on policy
		}
	}
}
```

