# Risk checks

Keep risk checks extremely fast and deterministic.

```go
// internal/risk/risk.go
package risk

import (
	"fmt"
	"sync"
	"trading-platform/internal/types"
)

type Limits struct {
	MaxOrderQty   float64
	MaxNotional   float64
	MaxPosition   float64
	MaxOrdersPerSec int
}

type Engine struct {
	limits Limits
	mu     sync.RWMutex
	pos    map[string]float64
}

func NewEngine(l Limits) *Engine {
	return &Engine{
		limits: l,
		pos:    make(map[string]float64),
	}
}

func (e *Engine) Check(order types.Order, referencePrice float64) error {
	if order.Qty <= 0 {
		return fmt.Errorf("invalid qty")
	}
	if order.Qty > e.limits.MaxOrderQty {
		return fmt.Errorf("order qty exceeds limit")
	}

	notional := order.Qty * referencePrice
	if notional > e.limits.MaxNotional {
		return fmt.Errorf("notional exceeds limit")
	}

	e.mu.RLock()
	currentPos := e.pos[order.Symbol]
	e.mu.RUnlock()

	projPos := currentPos
	if order.Side == types.Buy {
		projPos += order.Qty
	} else {
		projPos -= order.Qty
	}

	if projPos > e.limits.MaxPosition || projPos < -e.limits.MaxPosition {
		return fmt.Errorf("position limit exceeded")
	}

	return nil
}

func (e *Engine) ApplyFill(trade types.Trade) {
	e.mu.Lock()
	defer e.mu.Unlock()

	if trade.Side == types.Buy {
		e.pos[trade.Symbol] += trade.Qty
	} else {
		e.pos[trade.Symbol] -= trade.Qty
	}
}
```

