// internal/execution/order_manager.go
package execution

import (
	"context"
	"sync"
	"trading-platform/internal/types"
)

type OrderManager struct {
	venue Venue
	mu    sync.RWMutex
	orders map[string]types.Order
}

func NewOrderManager(v Venue) *OrderManager {
	return &OrderManager{
		venue:  v,
		orders: make(map[string]types.Order),
	}
}

func (om *OrderManager) Submit(ctx context.Context, order types.Order) (types.OrderAck, error) {
	ack, err := om.venue.PlaceOrder(ctx, order)
	if err != nil {
		return types.OrderAck{}, err
	}

	om.mu.Lock()
	om.orders[order.ID] = order
	om.mu.Unlock()

	return ack, nil
}
