# Simple strategy engine

```go
// internal/strategy/strategy.go
package strategy

import (
	"fmt"
	"time"
	"trading-platform/internal/types"
)

type Engine struct {
	threshold float64
}

func NewEngine(threshold float64) *Engine {
	return &Engine{threshold: threshold}
}

// Very simple mean-reversion-ish example.
func (e *Engine) OnTick(tick types.MarketTick) *types.Order {
	mid := (tick.Bid + tick.Ask) / 2
	spread := tick.Ask - tick.Bid

	if spread <= 0 {
		return nil
	}

	// If spread is large enough, place a passive order.
	if spread/mid > e.threshold {
		return &types.Order{
			ID:        fmt.Sprintf("%s-%d", tick.Symbol, time.Now().UnixNano()),
			Symbol:    tick.Symbol,
			Side:      types.Buy,
			Type:      types.LimitOrder,
			Price:     tick.Bid,
			Qty:       1,
			Timestamp: time.Now(),
		}
	}

	return nil
}
