		MaxPosition:     500,
		MaxOrdersPerSec: 1000,
	})

	venue := execution.NewMockVenue()
	orderMgr := execution.NewOrderManager(venue)
	strat := strategy.NewEngine(0.001)

	ticks := make(chan types.MarketTick, 1024)

	// Market data simulator
	go func() {
		for i := 0; i < 10; i++ {
			ticks <- types.MarketTick{
				Symbol:    "AAPL",
				Bid:       100.00,
				Ask:       100.20,
				BidSize:   1000,
				AskSize:   1000,
				Last:      100.10,
				Timestamp: time.Now(),
			}
			time.Sleep(10 * time.Millisecond)
		}
		close(ticks)
	}()

	for tick := range ticks {
		order := strat.OnTick(tick)
		if order == nil {
			continue
		}

		if err := riskEngine.Check(*order, tick.Ask); err != nil {
			log.Printf("risk reject: %v", err)
			continue
		}

		ack, err := orderMgr.Submit(ctx, *order)
		if err != nil {
			log.Printf("order submit error: %v", err)
			continue
		}

		log.Printf("order ack: %+v", ack)
	}

