# src/risk.rs

```rust
use std::collections::HashMap;
use uuid::Uuid;
use crate::types::{Order, OrderType, Side};

#[derive(Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

pub struct RiskEngine {
    pub limits: RiskLimits,
    pub positions: HashMap<String, f64>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: HashMap::new(),
        }
    }

    pub fn validate(&self, order: &Order, market_price: f64) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }

        if order.qty > self.limits.max_order_qty {
            return Err(format!("qty exceeds max_order_qty {}", self.limits.max_order_qty));
        }

        let notional = order.qty * market_price;
        if notional > self.limits.max_notional {
            return Err(format!("notional exceeds max_notional {}", self.limits.max_notional));
        }

        match &order.order_type {
            OrderType::Market => {}
            OrderType::Limit { price } => {
                if *price <= 0.0 {
                    return Err("limit price must be positive".into());
                }
            }
        }

        Ok(())
    }

    pub fn apply_fill(&mut self, symbol: &str, side: &Side, qty: f64) {
        let pos = self.positions.entry(symbol.to_string()).or_insert(0.0);
        match side {
            Side::Buy => *pos += qty,
            Side::Sell => *pos -= qty,
        }
    }

    pub fn position(&self, symbol: &str) -> f64 {
        *self.positions.get(symbol).unwrap_or(&0.0)
    }
}
