        Self { spread_threshold, qty }
    }

    pub fn on_tick(&self, tick: &MarketTick) -> Option<Order> {
        let spread = tick.ask - tick.bid;
        if spread <= self.spread_threshold {
            Some(Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.qty,
                order_type: OrderType::Market,
                ts_nanos: tick.ts_nanos,
            })
        } else {
            None
        }
    }
}
