mod bus;
mod execution;
mod market_data;
mod risk;
mod strategy;
mod types;

use bus::{Event, EventBus};
use execution::ExecutionEngine;
use market_data::MarketDataFeed;
use risk::{RiskEngine, RiskLimits};
use strategy::MeanReversionStrategy;
use tracing::{info, error};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let bus = EventBus::new(1024);

    let md_bus = bus.clone();
    tokio::spawn(async move {
        let feed = MarketDataFeed::new("AAPL");
        feed.run(md_bus).await;
    });

    let strategy = MeanReversionStrategy::new(0.05, 10.0);
    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 100.0,
        max_notional: 20_000.0,
    });
    let execution = ExecutionEngine::new();

    let mut rx = bus.subscribe();

    loop {
        match rx.recv().await {
            Ok(Event::Tick(tick)) => {
                if let Some(order) = strategy.on_tick(&tick) {
                    match risk.validate(&order, tick.last) {
                        Ok(_) => {
                            let report = execution.execute(&order).await;
                            info!("order filled: {:?}", report);
                        }
                        Err(reason) => {
                            error!("risk rejected order: {}", reason);
                        }
                    }
                }
            }
            Ok(Event::Order(_)) => {}
            Ok(Event::Report(_)) => {}
            Err(e) => {
                error!("event bus error: {:?}", e);
            }
        }
    }
}
