# 4) In-memory low-latency event bus

This is a simple version. In production you’d likely replace this with:
- LMAX Disruptor
- Aeron
- Chronicle Queue
- Kafka for cross-service durability, not inner-loop matching

## `InMemoryEventBus.java`
```java
package com.example.trading.infra;

import com.example.trading.core.*;

import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

public class InMemoryEventBus implements EventBus {

    private final Map<EventType, List<EventHandler<? extends Event>>> handlers = new ConcurrentHashMap<>();

    @Override
    public void publish(Event event) {
        List<EventHandler<? extends Event>> list = handlers.get(event.type());
        if (list == null) return;

        for (EventHandler<? extends Event> handler : list) {
            dispatch(handler, event);
        }
    }

    @SuppressWarnings("unchecked")
    private <T extends Event> void dispatch(EventHandler<? extends Event> handler, Event event) {
        ((EventHandler<T>) handler).onEvent((T) event);
    }

    @Override
    public void register(EventType type, EventHandler<? extends Event> handler) {
        handlers.computeIfAbsent(type, k -> new CopyOnWriteArrayList<>()).add(handler);
    }
}
```

