```java
package com.example.trading.strategy;

import com.example.trading.core.EventBus;
import com.example.trading.order.Order;
import com.example.trading.order.OrderSide;
import com.example.trading.core.EventType;
import com.example.trading.marketdata.MarketDataTick;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class MeanReversionStrategy implements Strategy {

    private final EventBus bus;
    private final Map<String, Double> avgPrice = new ConcurrentHashMap<>();
    private final Map<String, Integer> count = new ConcurrentHashMap<>();

    private final double threshold;

    public MeanReversionStrategy(EventBus bus, double threshold) {
        this.bus = bus;
        this.threshold = threshold;
    }

    @Override
    public void onTick(MarketDataTick tick) {
        String symbol = tick.symbol();
        double price = tick.last();

        int c = count.merge(symbol, 1, Integer::sum);
        double avg = avgPrice.merge(symbol, price, (oldV, newV) -> oldV + (newV - oldV) / c);

        double diff = price - avg;

        if (diff > threshold) {
            bus.publish(new Order(
                    symbol,
                    OrderSide.SELL,
                    100,
                    price,
                    System.nanoTime()
            ));
        } else if (diff < -threshold) {
            bus.publish(new Order(
                    symbol,
                    OrderSide.BUY,
                    100,
                    price,
                    System.nanoTime()
            ));
        }
    }
}
```

