package com.example.trading.risk;

import com.example.trading.core.EventBus;
import com.example.trading.core.EventType;
import com.example.trading.order.Order;
import com.example.trading.core.EventHandler;
import com.example.trading.core.Event;
import com.example.trading.order.OrderSide;

public class RiskEngine implements EventHandler<Order> {

    private final EventBus bus;
    private final RiskLimits limits;

    public RiskEngine(EventBus bus, RiskLimits limits) {
        this.bus = bus;
        this.limits = limits;
    }

    @Override
    public void onEvent(Order order) {
        if (order.quantity() > limits.maxOrderQty()) {
            bus.publish(new RiskReject(order, "Quantity limit exceeded"));
            return;
        }

        double notional = order.quantity() * order.price();
        if (notional > limits.maxNotional()) {
            bus.publish(new RiskReject(order, "Notional limit exceeded"));
            return;
        }

        bus.publish(order);
    }

    private static class RiskReject implements Event {
        private final Order order;
        private final String reason;

        public RiskReject(Order order, String reason) {
            this.order = order;
            this.reason = reason;
        }

        public Order order() { return order; }
        public String reason() { return reason; }

        @Override
        public EventType type() {
            return EventType.RISK_REJECT;
        }

        @Override
        public long timestampNanos() {
            return System.nanoTime();
        }
    }
}
