## risk.rs

```rust
use std::collections::HashMap;

use crate::model::{Order, Side};

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_position_qty: f64,
    pub max_notional: f64,
}

#[derive(Debug)]
pub struct RiskEngine {
    limits: RiskLimits,
    positions: HashMap<String, f64>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: HashMap::new(),
        }
    }

    pub fn check_order(&self, order: &Order, last_price: f64) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }
        if order.qty > self.limits.max_order_qty {
            return Err("order qty exceeds limit".into());
        }

        let notional = order.qty * last_price;
        if notional > self.limits.max_notional {
            return Err("notional exceeds limit".into());
        }

        let current_pos = self.positions.get(&order.symbol).copied().unwrap_or(0.0);
        let projected_pos = match order.side {
            Side::Buy => current_pos + order.qty,
            Side::Sell => current_pos - order.qty,
        };

        if projected_pos.abs() > self.limits.max_position_qty {
            return Err("projected position exceeds limit".into());
        }

        Ok(())
    }

    pub fn on_fill(&mut self, symbol: &str, qty: f64, side: &Side) {
        let pos = self.positions.entry(symbol.to_string()).or_insert(0.0);
        match side {
            Side::Buy => *pos += qty,
            Side::Sell => *pos -= qty,
        }
    }
}
