use std::collections::HashMap;

use uuid::Uuid;

use crate::{
    bus::{Event, EventSender},
    model::Order,
    risk::RiskEngine,
};

#[derive(Debug, Clone)]
pub enum OrderState {
    New,
    Acked,
    Rejected(String),
    Filled,
}

pub struct OrderManager {
    orders: HashMap<Uuid, (Order, OrderState)>,
    risk: RiskEngine,
    tx: EventSender,
}

impl OrderManager {
    pub fn new(risk: RiskEngine, tx: EventSender) -> Self {
        Self {
            orders: HashMap::new(),
            risk,
            tx,
        }
    }

    pub async fn handle_new_order(&mut self, order: Order, last_price: f64) {
        let order_id = order.id;

        match self.risk.check_order(&order, last_price) {
            Ok(_) => {
                self.orders.insert(order_id, (order.clone(), OrderState::New));
                let _ = self.tx.send(Event::OrderAck { order_id }).await;
                self.orders.insert(order_id, (order, OrderState::Acked));
            }
            Err(reason) => {
                self.orders
                    .insert(order_id, (order.clone(), OrderState::Rejected(reason.clone())));
                let _ = self
                    .tx
                    .send(Event::OrderReject { order_id, reason })
                    .await;
            }
        }
    }
}
