use uuid::Uuid;

use crate::{
    bus::{Event, EventSender},
    model::{Order, OrderType, Side, Tick},
};

pub struct MeanReversionStrategy {
    symbol: String,
    threshold: f64,
    tx: EventSender,
}

impl MeanReversionStrategy {
    pub fn new(symbol: String, threshold: f64, tx: EventSender) -> Self {
        Self {
            symbol,
            threshold,
            tx,
        }
    }

    pub async fn on_tick(&self, tick: Tick) {
        if tick.symbol != self.symbol {
            return;
        }

        let mid = (tick.bid + tick.ask) / 2.0;
        let last = tick.last;

        if last < mid - self.threshold {
            let order = Order {
                id: Uuid::new_v4(),
                strategy_id: "mean_reversion".to_string(),
                symbol: tick.symbol,
                side: Side::Buy,
                qty: 1.0,
                order_type: OrderType::Market,
                ts_nanos: now_nanos(),
            };
            let _ = self.tx.send(Event::NewOrder(order)).await;
        } else if last > mid + self.threshold {
            let order = Order {
                id: Uuid::new_v4(),
                strategy_id: "mean_reversion".to_string(),
                symbol: tick.symbol,
                side: Side::Sell,
                qty: 1.0,
                order_type: OrderType::Market,
                ts_nanos: now_nanos(),
            };
            let _ = self.tx.send(Event::NewOrder(order)).await;
        }
    }
}

fn now_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
