use strategy::MeanReversionStrategy;
use execution::ExecutionGateway;
use md::MarketDataHandler;
use oms::OrderManager;
use tracing::{info, error};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (tx, mut rx) = channel(10_000);

    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 100.0,
        max_position_qty: 1_000.0,
        max_notional: 100_000.0,
    });

    let mut oms = OrderManager::new(risk, tx.clone());
    let exec = ExecutionGateway::new(tx.clone());
    let strat = MeanReversionStrategy::new("AAPL".to_string(), 0.25, tx.clone());
    let md = MarketDataHandler::new(tx.clone());

    tokio::spawn(async move {
        while let Some(event) = rx.recv().await {
            match event {
                Event::MarketData(tick) => {
                    strat.on_tick(tick).await;
                }
                Event::NewOrder(order) => {
                    let last_price = 100.0;
                    oms.handle_new_order(order.clone(), last_price).await;
                    exec.submit_order(order).await;
                }
                Event::OrderAck { order_id } => {
                    info!("order ack: {}", order_id);
                }
                Event::OrderReject { order_id, reason } => {
                    info!("order reject: {} reason={}", order_id, reason);
                }
                Event::Fill(fill) => {
                    info!("fill: {:?}", fill);
                }
            }
        }
    });

    for i in 0..100 {
        let tick = Tick {
            symbol: "AAPL".to_string(),
            bid: 100.0 + (i as f64 * 0.01),
            ask: 100.1 + (i as f64 * 0.01),
            last: if i % 2 == 0 { 99.7 } else { 100.6 },
            ts_nanos: now_nanos(),
        };
        md.on_tick(tick).await;
    }

    tokio::time::sleep(std::time::Duration::from_secs(1)).await;
    Ok(())
