package com.trading.strategy;

import com.trading.core.MarketTick;
import com.trading.core.OrderRequest;
import com.trading.core.Side;

import java.util.Optional;
import java.util.UUID;

public class SimpleSpreadStrategy implements Strategy {
    private final String strategyId;
    private final String symbol;
    private final double threshold;

    public SimpleSpreadStrategy(String strategyId, String symbol, double threshold) {
        this.strategyId = strategyId;
        this.symbol = symbol;
        this.threshold = threshold;
    }

    @Override
    public Optional<OrderRequest> onTick(MarketTick tick) {
        if (!tick.symbol().equals(symbol)) {
            return Optional.empty();
        }

        double spread = tick.ask() - tick.bid();
        if (spread > threshold) {
            // Example signal only — real logic would be more sophisticated
            return Optional.of(new OrderRequest(
                    UUID.randomUUID().toString(),
                    symbol,
                    Side.BUY,
                    100,
                    tick.bid(),
                    strategyId
            ));
        }

        return Optional.empty();
    }

    @Override
    public String id() {
        return strategyId;
    }
}
