### Basic risk implementation

```java
package com.trading.risk;

import com.trading.core.OrderRequest;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class BasicRiskEngine implements RiskEngine {
    private final long maxOrderQty;
    private final long maxNetPosition;
    private final ConcurrentHashMap<String, AtomicLong> positions = new ConcurrentHashMap<>();

    public BasicRiskEngine(long maxOrderQty, long maxNetPosition) {
        this.maxOrderQty = maxOrderQty;
        this.maxNetPosition = maxNetPosition;
    }

    @Override
    public RiskResult validate(OrderRequest order) {
        if (order.quantity() <= 0) {
            return RiskResult.rejected("Quantity must be positive");
        }
        if (order.quantity() > maxOrderQty) {
            return RiskResult.rejected("Order quantity exceeds max limit");
        }

        long signedQty = order.side() == com.trading.core.Side.BUY ? order.quantity() : -order.quantity();
        long currentPos = positions.computeIfAbsent(order.symbol(), k -> new AtomicLong(0)).get();
        long projected = currentPos + signedQty;

        if (Math.abs(projected) > maxNetPosition) {
            return RiskResult.rejected("Projected position exceeds max net position");
        }

        return RiskResult.allowed();
    }

    public void onFill(String symbol, long signedQty) {
        positions.computeIfAbsent(symbol, k -> new AtomicLong(0)).addAndGet(signedQty);
    }
}
