public class OrderManager {
    private final Map<String, OrderStatus> orders = new ConcurrentHashMap<>();

    public void onNewOrder(OrderRequest order) {
        orders.put(order.orderId(), OrderStatus.NEW);
    }

    public void onOrderUpdate(OrderUpdate update) {
        orders.put(update.orderId(), update.status());
    }

    public OrderStatus status(String orderId) {
        return orders.get(orderId);
