## 7) Strategy engine wiring

This ties ticks to strategies to risk and then to execution.

```java
package com.trading.engine;

import com.trading.bus.EventBus;
import com.trading.core.MarketTick;
import com.trading.core.OrderRequest;
import com.trading.execution.ExecutionGateway;
import com.trading.risk.RiskEngine;
import com.trading.risk.RiskResult;
import com.trading.strategy.Strategy;

import java.util.List;

public class StrategyEngine {
    private final List<Strategy> strategies;
    private final RiskEngine riskEngine;
    private final ExecutionGateway executionGateway;

    public StrategyEngine(List<Strategy> strategies,
                          RiskEngine riskEngine,
                          ExecutionGateway executionGateway) {
        this.strategies = strategies;
        this.riskEngine = riskEngine;
        this.executionGateway = executionGateway;
    }

    public void onMarketTick(MarketTick tick) {
        for (Strategy strategy : strategies) {
            strategy.onTick(tick).ifPresent(order -> processOrder(order));
        }
    }

    private void processOrder(OrderRequest order) {
        RiskResult result = riskEngine.validate(order);
        if (!result.allowed()) {
            System.out.println("Order rejected: " + result.reason());
            return;
        }
        executionGateway.sendOrder(order);
    }
}
```

