    let risk = RiskEngine::new(10_000.0, 100_000.0); // max position, max notional
    let gateway = OrderGateway::new();
    let engine = TradingEngine::new(risk, gateway, bus.clone());

    engine.start();

    // Simulated market data stream
    let events = vec![
        MarketEvent::trade("AAPL", 189.10, 100),
        MarketEvent::trade("AAPL", 189.20, 100),
        MarketEvent::trade("AAPL", 189.00, 100),
        MarketEvent::trade("AAPL", 188.70, 200),
    ];

    for ev in events {
        if let Err(e) = bus.publish_market(ev) {
            error!("failed to publish market event: {e}");
        }
    }

    tokio::time::sleep(std::time::Duration::from_secs(1)).await;

    info!("Platform stopped");
}
