use crate::types::{Order, OrderSide, OrderType};

#[derive(Debug, Clone)]
pub struct RiskEngine {
    max_position: f64,
    max_notional: f64,
}

#[derive(Debug, thiserror::Error)]
pub enum RiskError {
    #[error("order exceeds risk limits")]
    Rejected,
}

impl RiskEngine {
    pub fn new(max_position: f64, max_notional: f64) -> Self {
        Self {
            max_position,
            max_notional,
        }
    }

    pub fn check_order(&self, order: &Order, current_position: f64) -> Result<(), RiskError> {
        let signed_qty = match order.side {
            OrderSide::Buy => order.qty as f64,
            OrderSide::Sell => -(order.qty as f64),
        };

        let projected_position = current_position + signed_qty;

        if projected_position.abs() > self.max_position {
            return Err(RiskError::Rejected);
        }

        match order.order_type {
            OrderType::Market => {
                // simple placeholder notional check
                if order.qty as f64 * 200.0 > self.max_notional {
                    return Err(RiskError::Rejected);
                }
            }
            OrderType::Limit { price } => {
                if order.qty as f64 * price > self.max_notional {
                    return Err(RiskError::Rejected);
                }
            }
        }

        Ok(())
    }
}
