## src/engine.rs

```rust
use crate::{
    bus::EventBus,
    gateway::OrderGateway,
    risk::RiskEngine,
    types::{ExecutionReport, MarketEvent, Order, OrderSide},
};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use tracing::{info, warn};

#[derive(Clone)]
pub struct TradingEngine {
    risk: RiskEngine,
    gateway: OrderGateway,
    bus: EventBus,
    positions: Arc<Mutex<HashMap<String, f64>>>,
}

impl TradingEngine {
    pub fn new(risk: RiskEngine, gateway: OrderGateway, bus: EventBus) -> Self {
        Self {
            risk,
            gateway,
            bus,
            positions: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn start(&self) {
        let rx = self.bus.subscribe_market();
        let risk = self.risk.clone();
        let gateway = self.gateway.clone();
        let positions = self.positions.clone();

        thread::spawn(move || {
            while let Ok(event) = rx.recv() {
                if let MarketEvent::Trade { symbol, price, .. } = event {
                    let current_pos = {
                        let pos = positions.lock().unwrap();
                        *pos.get(&symbol).unwrap_or(&0.0)
                    };

                    // Example strategy: mean reversion placeholder
                    let order = if price < 189.0 {
                        Some(Order::market(&symbol, OrderSide::Buy, 10))
                    } else if price > 189.15 {
                        Some(Order::market(&symbol, OrderSide::Sell, 10))
                    } else {
                        None
                    };

                    if let Some(order) = order {
                        match risk.check_order(&order, current_pos) {
                            Ok(_) => {
                                let report = gateway.send(&order);
                                apply_report(&positions, &symbol, &order, &report);
                                info!("execution report: {:?}", report);
                            }
                            Err(_) => {
                                warn!("order rejected by risk: {:?}", order.id);
                            }
                        }
                    }
                }
            }
        });
    }
}

fn apply_report(
    positions: &Arc<Mutex<HashMap<String, f64>>>,
    symbol: &str,
    order: &Order,
    report: &ExecutionReport,
) {
    if let ExecutionReport::Filled { qty, .. } = report {
        let mut pos = positions.lock().unwrap();
        let entry = pos.entry(symbol.to_string()).or_insert(0.0);

        match order.side {
            OrderSide::Buy => *entry += *qty as f64,
            OrderSide::Sell => *entry -= *qty as f64,
        }
    }
}
```

