### `src/risk.rs`
```rust
use anyhow::{anyhow, Result};
use dashmap::DashMap;
use crate::types::{NewOrder, Symbol, Quantity};

pub struct RiskManager {
    max_order_qty: Quantity,
    max_notional_per_symbol: Quantity,
    position_limits: DashMap<Symbol, Quantity>,
}

impl RiskManager {
    pub fn new(max_order_qty: Quantity, max_notional_per_symbol: Quantity) -> Self {
        Self {
            max_order_qty,
            max_notional_per_symbol,
            position_limits: DashMap::new(),
        }
    }

    pub fn validate_order(&self, order: &NewOrder, market_price: f64) -> Result<()> {
        if order.qty <= 0.0 {
            return Err(anyhow!("quantity must be positive"));
        }
        if order.qty > self.max_order_qty {
            return Err(anyhow!("order quantity exceeds limit"));
        }

        let notional = order.qty * market_price;
        if notional > self.max_notional_per_symbol {
            return Err(anyhow!("notional exceeds limit"));
        }

        Ok(())
    }

    pub fn update_position(&self, symbol: &str, delta: Quantity) {
        self.position_limits
            .entry(symbol.to_string())
            .and_modify(|v| *v += delta)
            .or_insert(delta);
    }
}
