## 7) Strategy engine example

A simple strategy: buy when spread is tight and bid/ask conditions are favorable.

### `src/strategy.rs`
```rust
use uuid::Uuid;
use crate::types::{EngineEvent, NewOrder, OrderType, Side, MarketTick};

pub struct StrategyEngine {
    symbol: String,
    threshold_spread: f64,
}

impl StrategyEngine {
    pub fn new(symbol: impl Into<String>, threshold_spread: f64) -> Self {
        Self {
            symbol: symbol.into(),
            threshold_spread,
        }
    }

    pub fn on_market_tick(&self, tick: &MarketTick) -> Option<NewOrder> {
        if tick.symbol != self.symbol {
            return None;
        }

        let spread = tick.ask - tick.bid;
        if spread <= self.threshold_spread {
            Some(NewOrder {
                client_order_id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 1.0,
                order_type: OrderType::Limit { price: tick.bid },
            })
        } else {
            None
        }
    }

    pub fn handle_event(&self, event: &EngineEvent) -> Option<NewOrder> {
        match event {
            EngineEvent::Market(tick) => self.on_market_tick(tick),
            _ => None,
        }
    }
}
