### `src/main.rs`
```rust
mod bus;
mod config;
mod execution;
mod journal;
mod market_data;
mod order_manager;
mod risk;
mod strategy;
mod types;

use anyhow::Result;
use tracing::{info, error};
use crate::bus::EventBus;
use crate::execution::ExecutionGateway;
use crate::journal::Journal;
use crate::order_manager::OrderManager;
use crate::risk::RiskManager;
use crate::strategy::StrategyEngine;
use crate::types::EngineEvent;

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let bus = EventBus::new(1024);
    let journal = Journal::new("events.log");
    let risk = RiskManager::new(10.0, 100_000.0);
    let strategy = StrategyEngine::new("AAPL", 0.05);
    let order_manager = OrderManager::new();
    let execution = ExecutionGateway::new(bus.clone());

    // Market data publisher task
    tokio::spawn(market_data::run_market_data_publisher(bus.clone(), "AAPL".to_string()));

    // Event loop
    let mut rx = bus.subscribe();
    loop {
        let event = match rx.recv().await {
            Ok(e) => e,
            Err(e) => {
                error!("event bus receive error: {:?}", e);
                continue;
            }
        };

        if let Err(e) = journal.append(&event) {
            error!("journal write failed: {:?}", e);
        }

        match &event {
            EngineEvent::Market(tick) => {
                if let Some(order) = strategy.handle_event(&event) {
                    if let Err(e) = risk.validate_order(&order, tick.ask) {
                        info!("order rejected by risk: {:?}", e);
                        continue;
                    }

                    order_manager.register_order(&order);
                    let exec = execution.send_order(order);
                    tokio::spawn(async move {
                        let _ = exec.await;
                    });
                }
            }
            EngineEvent::OrderUpdate(update) => {
                order_manager.on_order_event(update);
                info!("order update: {:?}", update);
            }
            EngineEvent::NewOrder(_) => {}
        }
    }
}
```

