mod bus;
mod domain;
mod risk;
mod strategy;
mod execution;

use anyhow::Result;
use bus::EventBus;
use execution::{ExchangeAdapter, SimulatedExchange};
use risk::RiskEngine;
use strategy::{MeanReversionStrategy, StrategyEngine};
use tracing::{info, Level};

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_max_level(Level::INFO)
        .init();

    let bus = EventBus::new(1024);
    let risk = RiskEngine::new(100_000.0, 0.02); // max capital, max order notional fraction
    let exchange = SimulatedExchange::new();
    let strategy = MeanReversionStrategy::new(20, 2.0);

    let strategy_engine = StrategyEngine::new(strategy, bus.clone());
    let feed_bus = bus.clone();

    info!("Starting trading platform...");

    // Strategy loop
    tokio::spawn(async move {
        strategy_engine.run().await;
    });

    // Simulated market data feed
    tokio::spawn(async move {
        use domain::{MarketData, Symbol};
        let symbol = Symbol("AAPL".into());
        let mut px = 100.0;

        loop {
            px += (rand_delta() * 0.2);
            let md = MarketData {
                symbol: symbol.clone(),
                bid: px - 0.01,
                ask: px + 0.01,
                last: px,
                ts_ns: now_ns(),
            };
            feed_bus.publish(domain::Event::MarketData(md)).await;
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
    });

    // Order routing loop
    let mut rx = bus.subscribe().await;
    while let Some(event) = rx.recv().await {
        match event {
            domain::Event::NewOrder(order) => {
                if risk.check_order(&order) {
                    let fill = exchange.place_order(order).await?;
                    bus.publish(domain::Event::OrderFill(fill)).await;
                } else {
                    info!("Order rejected by risk");
                }
            }
            domain::Event::OrderFill(fill) => {
                info!("Fill: {:?}", fill);
            }
            _ => {}
        }
    }

    Ok(())
}

fn now_ns() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}

fn rand_delta() -> f64 {
    (rand::random::<f64>() - 0.5) * 2.0
}
```

