use crate::domain::{Order, OrderType, Side};

pub struct RiskEngine {
    max_capital: f64,
    max_order_fraction: f64,
}

impl RiskEngine {
    pub fn new(max_capital: f64, max_order_fraction: f64) -> Self {
        Self {
            max_capital,
            max_order_fraction,
        }
    }

    pub fn check_order(&self, order: &Order) -> bool {
        if order.qty <= 0.0 {
            return false;
        }

        let est_price = match order.order_type {
            OrderType::Market => 100.0, // replace with latest mid-price in production
            OrderType::Limit { price } => price,
        };

        let notional = order.qty * est_price;
        if notional > self.max_capital * self.max_order_fraction {
            return false;
        }

        match order.side {
            Side::Buy | Side::Sell => true,
        }
    }
}
