```rust
use crate::bus::EventBus;
use crate::domain::{Event, MarketData, Order, OrderType, Side, Symbol};
use async_trait::async_trait;
use std::collections::{HashMap, VecDeque};
use uuid::Uuid;

pub struct StrategyEngine<S: Strategy + Send + Sync + 'static> {
    strategy: S,
    bus: EventBus,
}

impl<S: Strategy + Send + Sync + 'static> StrategyEngine<S> {
    pub fn new(strategy: S, bus: EventBus) -> Self {
        Self { strategy, bus }
    }

    pub async fn run(self) {
        let mut rx = self.bus.subscribe().await;

        while let Ok(event) = rx.recv().await {
            if let Event::MarketData(md) = event {
                if let Some(order) = self.strategy.on_market_data(&md) {
                    self.bus.publish(Event::NewOrder(order)).await;
                }
            }
        }
    }
}

#[async_trait]
pub trait Strategy {
    fn on_market_data(&self, md: &MarketData) -> Option<Order>;
}

pub struct MeanReversionStrategy {
    window: usize,
    threshold: f64,
    state: std::sync::Mutex<HashMap<String, VecDeque<f64>>>,
}

impl MeanReversionStrategy {
    pub fn new(window: usize, threshold: f64) -> Self {
        Self {
            window,
            threshold,
            state: std::sync::Mutex::new(HashMap::new()),
        }
    }
}

#[async_trait]
impl Strategy for MeanReversionStrategy {
    fn on_market_data(&self, md: &MarketData) -> Option<Order> {
        let mut state = self.state.lock().unwrap();
        let entry = state
            .entry(md.symbol.0.clone())
            .or_insert_with(VecDeque::new);

        entry.push_back(md.last);
        if entry.len() > self.window {
            entry.pop_front();
        }

        if entry.len() < self.window {
            return None;
        }

        let mean: f64 = entry.iter().sum::<f64>() / entry.len() as f64;
        let diff = (md.last - mean) / mean;

        if diff.abs() < self.threshold / 100.0 {
            return None;
        }

        let side = if md.last > mean { Side::Sell } else { Side::Buy };

        Some(Order {
            id: Uuid::new_v4(),
            symbol: Symbol(md.symbol.0.clone()),
            side,
            qty: 10.0,
            order_type: OrderType::Market,
            ts_ns: md.ts_ns,
        })
    }
}
