package com.example.trading.strategy;

import com.example.trading.marketdata.MarketDataEvent;
import com.example.trading.order.Order;
import com.example.trading.order.OrderSide;

public final class MomentumStrategy implements Strategy {
    private final String symbol;
    private final double threshold;

    public MomentumStrategy(String symbol, double threshold) {
        this.symbol = symbol;
        this.threshold = threshold;
    }

    @Override
    public Order onMarketData(MarketDataEvent md) {
        if (!symbol.equals(md.symbol())) return null;

        double mid = (md.bid() + md.ask()) / 2.0;
        if (md.last() > mid + threshold) {
            return new Order(0, md.timestampNanos(), md.symbol(), OrderSide.BUY, 100, md.ask());
        } else if (md.last() < mid - threshold) {
            return new Order(0, md.timestampNanos(), md.symbol(), OrderSide.SELL, 100, md.bid());
        }
        return null;
    }
}
```

