import java.util.List;

public final class RiskManager {
    private final List<RiskCheck> checks;

    public RiskManager(List<RiskCheck> checks) {
        this.checks = List.copyOf(checks);
    }

    public RiskResult validate(Order order) {
        for (RiskCheck check : checks) {
            RiskResult result = check.validate(order);
            if (!result.approved()) {
                return result;
            }
        }
        return RiskResult.ok();
    }
}
