package com.example.trading.state;

public final class Position {
    private int quantity;
    private double avgPrice;

    public int quantity() {
        return quantity;
    }

    public double avgPrice() {
        return avgPrice;
    }

    public void applyFill(int fillQty, double fillPrice, boolean buy) {
        int signedQty = buy ? fillQty : -fillQty;
        int newQty = quantity + signedQty;

        if (quantity == 0) {
            avgPrice = fillPrice;
        } else if ((quantity > 0 && buy) || (quantity < 0 && !buy)) {
            avgPrice = ((Math.abs(quantity) * avgPrice) + (fillQty * fillPrice)) / (Math.abs(quantity) + fillQty);
        } else if (newQty == 0) {
            avgPrice = 0.0;
        }

        quantity = newQty;
    }
}
