package com.example.trading.app;

import com.example.trading.bus.EventBus;
import com.example.trading.bus.RingBufferEventBus;
import com.example.trading.common.Event;
import com.example.trading.marketdata.MarketDataEvent;
import com.example.trading.observability.Metrics;
import com.example.trading.order.Order;
import com.example.trading.execution.ExecutionGateway;
import com.example.trading.execution.SimulatedExecutionGateway;
import com.example.trading.risk.RiskManager;
import com.example.trading.risk.RiskResult;
import com.example.trading.strategy.MomentumStrategy;
import com.example.trading.strategy.Strategy;

import java.util.List;

public final class TradingApplication {
    public static void main(String[] args) {
        EventBus bus = new RingBufferEventBus(1024);
        Metrics metrics = new Metrics();
        Strategy strategy = new MomentumStrategy("AAPL", 0.02);
        RiskManager riskManager = new RiskManager(List.of(
                order -> order.quantity() > 1000
                        ? RiskResult.reject("Quantity too large")
                        : RiskResult.ok()
        ));
        ExecutionGateway gateway = new SimulatedExecutionGateway();

        bus.subscribe(event -> {
            metrics.incEvents();

            if (event instanceof MarketDataEvent md) {
                Order order = strategy.onMarketData(md);
                if (order != null) {
                    metrics.incOrders();
                    RiskResult result = riskManager.validate(order);
                    if (result.approved()) {
                        gateway.send(order);
                    } else {
                        metrics.incRejects();
                        System.out.println("RISK REJECT: " + result.reason());
                    }
                }
            }
        });

        // Simulate market data stream
        long seq = 1;
        for (int i = 0; i < 10; i++) {
            MarketDataEvent md = new MarketDataEvent(
                    seq++,
                    System.nanoTime(),
                    "AAPL",
                    100.00 + i * 0.01,
                    100.02 + i * 0.01,
                    100.03 + i * 0.01
            );
            bus.publish(md);
        }

        System.out.println("Events: " + metrics.events());
        System.out.println("Orders: " + metrics.orders());
        System.out.println("Rejects: " + metrics.rejects());
    }
}
```

