# 5. Order book: `order_book.rs`

This is a simple in-memory book. In production, you’d tune it heavily.

```rust
use std::collections::{BTreeMap, VecDeque};
use crate::types::{Order, Side};

pub struct OrderBook {
    pub bids: BTreeMap<u64, VecDeque<Order>>, // price -> orders
    pub asks: BTreeMap<u64, VecDeque<Order>>,
}

impl OrderBook {
    pub fn new() -> Self {
        Self {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    pub fn add_order(&mut self, order: Order) {
        match order.side {
            Side::Buy => {
                self.bids.entry(order.price.unwrap()).or_default().push_back(order);
            }
            Side::Sell => {
                self.asks.entry(order.price.unwrap()).or_default().push_back(order);
            }
        }
    }

    pub fn best_bid(&self) -> Option<u64> {
        self.bids.keys().next_back().copied()
    }

    pub fn best_ask(&self) -> Option<u64> {
        self.asks.keys().next().copied()
    }
}
