# 6. Matching engine: `matching_engine.rs`

```rust
use crate::order_book::OrderBook;
use crate::types::{Order, OrderType, Side, Trade};
use uuid::Uuid;

pub struct MatchingEngine {
    pub symbol: String,
    pub book: OrderBook,
}

impl MatchingEngine {
    pub fn new(symbol: impl Into<String>) -> Self {
        Self {
            symbol: symbol.into(),
            book: OrderBook::new(),
        }
    }

    pub fn process_order(&mut self, mut order: Order) -> Vec<Trade> {
        let mut trades = Vec::new();

        match order.side {
            Side::Buy => {
                while order.qty > 0 {
                    let best_ask = match self.book.best_ask() {
                        Some(p) => p,
                        None => break,
                    };

                    let limit_ok = match order.order_type {
                        OrderType::Market => true,
                        OrderType::Limit => order.price.map(|p| p >= best_ask).unwrap_or(false),
                    };

                    if !limit_ok {
                        break;
                    }

                    let mut remove_price_level = false;
                    if let Some(queue) = self.book.asks.get_mut(&best_ask) {
                        if let Some(mut resting) = queue.pop_front() {
                            let exec_qty = order.qty.min(resting.qty);
                            order.qty -= exec_qty;
                            resting.qty -= exec_qty;

                            trades.push(Trade {
                                trade_id: Uuid::new_v4().to_string(),
                                symbol: self.symbol.clone(),
                                buy_order_id: order.id.clone(),
                                sell_order_id: resting.id.clone(),
                                price: best_ask,
                                qty: exec_qty,
                                ts_nanos: now_nanos(),
                            });

                            if resting.qty > 0 {
                                queue.push_front(resting);
                            }
                            if queue.is_empty() {
                                remove_price_level = true;
                            }
                        }
                    }
                    if remove_price_level {
                        self.book.asks.remove(&best_ask);
                    }
                }

                if order.qty > 0 && matches!(order.order_type, OrderType::Limit) {
                    self.book.add_order(order);
                }
            }
            Side::Sell => {
                while order.qty > 0 {
                    let best_bid = match self.book.best_bid() {
                        Some(p) => p,
                        None => break,
                    };

                    let limit_ok = match order.order_type {
                        OrderType::Market => true,
                        OrderType::Limit => order.price.map(|p| p <= best_bid).unwrap_or(false),
                    };

                    if !limit_ok {
                        break;
                    }

                    let mut remove_price_level = false;
                    if let Some(queue) = self.book.bids.get_mut(&best_bid) {
                        if let Some(mut resting) = queue.pop_front() {
                            let exec_qty = order.qty.min(resting.qty);
                            order.qty -= exec_qty;
                            resting.qty -= exec_qty;

                            trades.push(Trade {
                                trade_id: Uuid::new_v4().to_string(),
                                symbol: self.symbol.clone(),
                                buy_order_id: resting.id.clone(),
                                sell_order_id: order.id.clone(),
                                price: best_bid,
                                qty: exec_qty,
                                ts_nanos: now_nanos(),
                            });

                            if resting.qty > 0 {
                                queue.push_front(resting);
                            }
                            if queue.is_empty() {
                                remove_price_level = true;
                            }
                        }
                    }
                    if remove_price_level {
                        self.book.bids.remove(&best_bid);
                    }
                }

                if order.qty > 0 && matches!(order.order_type, OrderType::Limit) {
                    self.book.add_order(order);
                }
            }
        }

        trades
    }
}

fn now_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
```

