use std::fs::OpenOptions;
use std::io::Write;
use crate::types::EngineEvent;

pub struct AuditLog {
    file: std::fs::File,
}

impl AuditLog {
    pub fn new(path: &str) -> std::io::Result<Self> {
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)?;
        Ok(Self { file })
    }

    pub fn append(&mut self, event: &EngineEvent) -> std::io::Result<()> {
        let line = serde_json::to_string(event).unwrap();
        writeln!(self.file, "{}", line)?;
        self.file.flush()?;
        Ok(())
    }
}
