This is an async entry point that wires validation, matching, and logging.

```rust
mod types;
mod order_book;
mod matching_engine;
mod risk;
mod persistence;

use crate::matching_engine::MatchingEngine;
use crate::persistence::AuditLog;
use crate::risk::RiskEngine;
use crate::types::{EngineEvent, Order, OrderType, Side};
use tracing::{error, info};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt::init();

    let risk = RiskEngine::new(1_000_000);
    let mut engine = MatchingEngine::new("AAPL");
    let mut audit = AuditLog::new("audit.log").expect("open audit log");

    let order1 = Order {
        id: "o1".into(),
        symbol: "AAPL".into(),
        side: Side::Buy,
        order_type: OrderType::Limit,
        price: Some(15000),
        qty: 100,
        ts_nanos: now_nanos(),
    };

    let order2 = Order {
        id: "o2".into(),
        symbol: "AAPL".into(),
        side: Side::Sell,
        order_type: OrderType::Limit,
        price: Some(14900),
        qty: 100,
        ts_nanos: now_nanos(),
    };

    for order in [order1, order2] {
        if let Err(reason) = risk.validate(&order) {
            let evt = EngineEvent::Rejected {
                order_id: order.id.clone(),
                reason,
            };
            let _ = audit.append(&evt);
            error!("rejected order {}", order.id);
            continue;
        }

        let trades = engine.process_order(order.clone());
        let _ = audit.append(&EngineEvent::NewOrder(order));

        for trade in trades {
            info!("trade executed: {:?}", trade);
            let _ = audit.append(&EngineEvent::TradeExecuted(trade));
        }
    }

    info!("best bid: {:?}", engine.book.best_bid());
    info!("best ask: {:?}", engine.book.best_ask());
}

fn now_nanos() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}
