## Risk engine

Keep this fast and deterministic. Use in-memory limits and avoid blocking calls.

### `src/risk.rs`
```rust
use crate::types::*;
use dashmap::DashMap;
use std::sync::Arc;

#[derive(Clone)]
pub struct RiskEngine {
    max_order_qty: f64,
    max_position_qty: f64,
    positions: Arc<DashMap<(ClientId, InstrumentId), f64>>,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_position_qty: f64) -> Self {
        Self {
            max_order_qty,
            max_position_qty,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn validate_order(&self, req: &OrderRequest) -> Result<(), String> {
        if req.qty <= 0.0 {
            return Err("qty must be positive".into());
        }
        if req.qty > self.max_order_qty {
            return Err(format!("order qty exceeds max_order_qty={}", self.max_order_qty));
        }
        Ok(())
    }

    pub fn on_fill(&self, client_id: ClientId, instrument: InstrumentId, side: &Side, qty: f64) {
        let signed = match side {
            Side::Buy => qty,
            Side::Sell => -qty,
        };

        let key = (client_id, instrument);
        self.positions
            .entry(key)
            .and_modify(|pos| *pos += signed)
            .or_insert(signed);
    }

    pub fn check_position_limit(&self, client_id: ClientId, instrument: &str, delta_qty: f64) -> Result<(), String> {
        let key = (client_id, instrument.to_string());
        let current = self.positions.get(&key).map(|v| *v).unwrap_or(0.0);
        let projected = current + delta_qty;

        if projected.abs() > self.max_position_qty {
            Err(format!(
                "position limit breached: current={}, projected={}, max={}",
                current, projected, self.max_position_qty
            ))
        } else {
            Ok(())
        }
    }
}
```

