use crate::types::*;
use tokio::sync::mpsc;

pub struct StrategyEngine {
    tx_orders: mpsc::Sender<OrderRequest>,
}

impl StrategyEngine {
    pub fn new(tx_orders: mpsc::Sender<OrderRequest>) -> Self {
        Self { tx_orders }
    }

    pub async fn on_tick(&self, tick: MarketTick) {
        let mid = (tick.bid + tick.ask) / 2.0;
        let spread = tick.ask - tick.bid;

        if spread > 0.01 {
            let buy = OrderRequest {
                client_id: uuid::Uuid::new_v4(),
                instrument: tick.instrument.clone(),
                side: Side::Buy,
                qty: 1.0,
                order_type: OrderType::Limit { price: mid - 0.01 },
            };

            let sell = OrderRequest {
                client_id: uuid::Uuid::new_v4(),
                instrument: tick.instrument,
                side: Side::Sell,
                qty: 1.0,
                order_type: OrderType::Limit { price: mid + 0.01 },
            };

            let _ = self.tx_orders.send(buy).await;
            let _ = self.tx_orders.send(sell).await;
        }
    }
}
