## Order gateway / orchestrator

This is the main flow controller.

### `src/gateway.rs`
```rust
use crate::risk::RiskEngine;
use crate::types::*;
use anyhow::Result;
use tokio::sync::mpsc;
use uuid::Uuid;
use tracing::{info, warn};

pub struct OrderGateway {
    risk: RiskEngine,
    tx_events: mpsc::Sender<Event>,
}

impl OrderGateway {
    pub fn new(risk: RiskEngine, tx_events: mpsc::Sender<Event>) -> Self {
        Self { risk, tx_events }
    }

    pub async fn handle_order(&self, req: OrderRequest) -> Result<()> {
        if let Err(reason) = self.risk.validate_order(&req) {
            let _ = self
                .tx_events
                .send(Event::OrderRejected {
                    order_id: Uuid::new_v4(),
                    reason: reason.clone(),
                })
                .await;
            warn!(%reason, "order rejected");
            return Ok(());
        }

        let order = Order {
            id: Uuid::new_v4(),
            request: req.clone(),
            status: OrderStatus::Accepted,
        };

        self.tx_events.send(Event::OrderAccepted(order.clone())).await?;
        info!(order_id = %order.id, "order accepted");

        // In a real system, route to execution adapter here.
        // Simulated fill:
        self.simulate_fill(order).await?;

        Ok(())
    }

    async fn simulate_fill(&self, order: Order) -> Result<()> {
        let fill_qty = order.request.qty;
        let price = match order.request.order_type {
            OrderType::Limit { price } => price,
            OrderType::Market => 100.0,
        };

        self.risk.on_fill(
            order.request.client_id,
            order.request.instrument.clone(),
            &order.request.side,
            fill_qty,
        );

        self.tx_events
            .send(Event::OrderFill {
                order_id: order.id,
                qty: fill_qty,
                price,
            })
            .await?;

        Ok(())
    }
}
```

