        .finish();
    tracing::subscriber::set_global_default(subscriber).expect("setting default subscriber failed");

    let (tx_orders, mut rx_orders) = mpsc::channel::<OrderRequest>(1024);
    let (tx_ticks, mut rx_ticks) = mpsc::channel::<MarketTick>(1024);
    let (tx_events, mut rx_events) = mpsc::channel::<Event>(4096);

    let risk = RiskEngine::new(10_000.0, 100_000.0);
    let gateway = OrderGateway::new(risk.clone(), tx_events.clone());
    let strategy = StrategyEngine::new(tx_orders.clone());

    tokio::spawn(async move {
        while let Some(tick) = rx_ticks.recv().await {
            strategy.on_tick(tick).await;
        }
    });

    tokio::spawn(async move {
        while let Some(order) = rx_orders.recv().await {
            let _ = gateway.handle_order(order).await;
        }
    });

    tokio::spawn(async move {
        while let Some(event) = rx_events.recv().await {
            info!(?event, "event");
        }
    });

    // Simulated market data feed
    let tx_ticks_clone = tx_ticks.clone();
    tokio::spawn(async move {
        let mut price = 100.0;
        loop {
            let tick = MarketTick {
                instrument: "AAPL".to_string(),
                bid: price - 0.02,
                ask: price + 0.02,
                ts_nanos: current_time_nanos(),
            };

            if tx_ticks_clone.send(tick).await.is_err() {
                break;
            }

            price += 0.01;
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
    });

    tokio::signal::ctrl_c().await.expect("failed to listen for ctrl-c");
}

fn current_time_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
