## `src/risk.rs`

```rust
use crate::types::{Order, OrderType, Side};
use dashmap::DashMap;
use std::sync::Arc;

#[derive(Clone)]
pub struct RiskEngine {
    max_order_qty: f64,
    max_notional: f64,
    max_position: f64,
    positions: Arc<DashMap<String, f64>>,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64, max_position: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
            max_position,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn validate_order(&self, order: &Order, market_price: f64) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("quantity must be positive".into());
        }

        if order.qty > self.max_order_qty {
            return Err(format!("order qty exceeds max_order_qty={}", self.max_order_qty));
        }

        let notional = match order.order_type {
            OrderType::Market => order.qty * market_price,
            OrderType::Limit { price } => order.qty * price,
        };

        if notional > self.max_notional {
            return Err(format!("notional exceeds max_notional={}", self.max_notional));
        }

        let current_pos = self
            .positions
            .get(&order.symbol)
            .map(|v| *v)
            .unwrap_or(0.0);

        let projected = match order.side {
            Side::Buy => current_pos + order.qty,
            Side::Sell => current_pos - order.qty,
        };

        if projected.abs() > self.max_position {
            return Err(format!("projected position exceeds max_position={}", self.max_position));
        }

        Ok(())
    }

    pub fn apply_fill(&self, symbol: &str, side: &Side, qty: f64) {
        let mut entry = self.positions.entry(symbol.to_string()).or_insert(0.0);
        match side {
            Side::Buy => *entry += qty,
            Side::Sell => *entry -= qty,
        }
    }

    pub fn position(&self, symbol: &str) -> f64 {
        self.positions.get(symbol).map(|v| *v).unwrap_or(0.0)
    }
}
