use crate::types::{MarketTick, Order, OrderType, Side};
use uuid::Uuid;

pub trait Strategy: Send + Sync {
    fn on_tick(&self, tick: &MarketTick) -> Option<Order>;
}

pub struct SimpleMeanReversionStrategy {
    pub symbol: String,
    pub threshold: f64,
    pub qty: f64,
}

impl Strategy for SimpleMeanReversionStrategy {
    fn on_tick(&self, tick: &MarketTick) -> Option<Order> {
        if tick.symbol != self.symbol {
            return None;
        }

        let mid = (tick.bid + tick.ask) / 2.0;

        if tick.last > mid + self.threshold {
            Some(Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: self.qty,
                order_type: OrderType::Market,
                strategy_id: "mean_reversion".into(),
            })
        } else if tick.last < mid - self.threshold {
            Some(Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.qty,
                order_type: OrderType::Market,
                strategy_id: "mean_reversion".into(),
            })
        } else {
            None
        }
    }
}
