```rust
use crate::{
    execution::ExecutionGateway,
    risk::RiskEngine,
    types::{ExecutionReport, MarketTick, Order, OrderStatus},
};
use tokio::sync::mpsc;
use tracing::{info, warn};

pub struct OrderManagementSystem {
    risk: RiskEngine,
    exec: ExecutionGateway,
    order_rx: mpsc::Receiver<Order>,
    tick_rx: mpsc::Receiver<MarketTick>,
    report_tx: mpsc::Sender<ExecutionReport>,
}

impl OrderManagementSystem {
    pub fn new(
        risk: RiskEngine,
        exec: ExecutionGateway,
        order_rx: mpsc::Receiver<Order>,
        tick_rx: mpsc::Receiver<MarketTick>,
        report_tx: mpsc::Sender<ExecutionReport>,
    ) -> Self {
        Self {
            risk,
            exec,
            order_rx,
            tick_rx,
            report_tx,
        }
    }

    pub async fn run(mut self) {
        loop {
            tokio::select! {
                Some(order) = self.order_rx.recv() => {
                    let market_price = 100.0;

                    match self.risk.validate_order(&order, market_price) {
                        Ok(_) => {
                            info!(order_id = %order.id, symbol = %order.symbol, "order accepted");
                            let report = self.exec.send_order(&order).await;
                            if let OrderStatus::Filled { qty, price } = &report.status {
                                self.risk.apply_fill(&order.symbol, &order.side, *qty);
                                info!(order_id = %order.id, qty = *qty, price = *price, "order filled");
                            }
                            let _ = self.report_tx.send(report).await;
                        }
                        Err(reason) => {
                            warn!(order_id = %order.id, reason = %reason, "order rejected");
                            let report = ExecutionReport {
                                order_id: order.id,
                                status: OrderStatus::Rejected(reason),
                            };
                            let _ = self.report_tx.send(report).await;
                        }
                    }
                }

                Some(_tick) = self.tick_rx.recv() => {
                    // In a real system, ticks would update in-memory price state
                    // and could trigger strategies or internal risk marks.
                }

                else => break,
            }
        }
    }
}
