# 6. Low-latency strategy engine example

This example uses a simple moving-average crossover style signal generator.

## `strategy/src/main.rs`

```rust
use common::bus::EventBus;
use common::types::{MarketTick, Order, OrderType, Side};
use std::collections::VecDeque;
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::time::{sleep, Duration};

fn now_nanos() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

fn sma(values: &VecDeque<f64>) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    values.iter().sum::<f64>() / values.len() as f64
}

#[tokio::main]
async fn main() {
    let market_bus: EventBus<MarketTick> = EventBus::new(1024);
    let order_bus: EventBus<Order> = EventBus::new(1024);

    let mut tick_rx = market_bus.subscribe();
    let order_bus_clone = order_bus.clone();

    tokio::spawn(async move {
        let mut short_window: VecDeque<f64> = VecDeque::with_capacity(10);
        let mut long_window: VecDeque<f64> = VecDeque::with_capacity(50);

        let mut last_signal: Option<Side> = None;

        while let Ok(tick) = tick_rx.recv().await {
            let mid = (tick.bid + tick.ask) / 2.0;

            if short_window.len() == 10 {
                short_window.pop_front();
            }
            if long_window.len() == 50 {
                long_window.pop_front();
            }

            short_window.push_back(mid);
            long_window.push_back(mid);

            if short_window.len() < 10 || long_window.len() < 50 {
                continue;
            }

            let short_sma = sma(&short_window);
            let long_sma = sma(&long_window);

            let signal = if short_sma > long_sma {
                Some(Side::Buy)
            } else if short_sma < long_sma {
                Some(Side::Sell)
            } else {
                None
            };

            if signal != last_signal {
                if let Some(side) = signal {
                    let order = Order {
                        id: rand::random::<u64>(),
                        symbol: tick.symbol.clone(),
                        side,
                        qty: 1.0,
                        price: Some(mid),
                        order_type: OrderType::Limit,
                        strategy_id: "sma-cross".to_string(),
                        ts_nanos: now_nanos(),
                    };

                    order_bus_clone.publish(order);
                    last_signal = signal;
                }
            }
        }
    });

    // Demo tick generator
    let mut price = 100.0;
    loop {
        price += (rand::random::<f64>() - 0.5) * 0.2;

        let tick = MarketTick {
            symbol: "AAPL".to_string(),
            bid: price - 0.01,
            ask: price + 0.01,
            last: price,
            ts_nanos: now_nanos(),
        };

        market_bus.publish(tick);
        sleep(Duration::from_millis(10)).await;
    }
}
