# 7. Risk service

Pre-trade risk should be fast and deterministic.

## `risk/src/main.rs`

```rust
use common::types::{Order, OrderStatus};
use std::collections::HashMap;
use tokio::sync::mpsc;

#[derive(Debug)]
struct RiskLimits {
    max_order_qty: f64,
    max_notional: f64,
}

#[tokio::main]
async fn main() {
    let (order_tx, mut order_rx) = mpsc::channel::<Order>(1024);
    let (risk_result_tx, mut risk_result_rx) = mpsc::channel::<(u64, OrderStatus)>(1024);

    let limits = RiskLimits {
        max_order_qty: 1000.0,
        max_notional: 100000.0,
    };

    tokio::spawn(async move {
        let mut positions: HashMap<String, f64> = HashMap::new();

        while let Some(order) = order_rx.recv().await {
            let notional = order.qty * order.price.unwrap_or(0.0);

            let allowed = order.qty > 0.0
                && order.qty <= limits.max_order_qty
                && notional <= limits.max_notional;

            let status = if allowed {
                *positions.entry(order.symbol.clone()).or_insert(0.0) += order.qty;
                OrderStatus::Accepted
            } else {
                OrderStatus::Rejected
            };

            let _ = risk_result_tx.send((order.id, status)).await;
        }
    });

    println!("Risk service running.");

    while let Some((order_id, status)) = risk_result_rx.recv().await {
        println!("Order {} -> {:?}", order_id, status);
    }
}
```

