# 8. OMS skeleton

OMS tracks order states and coordinates risk + execution.

## `oms/src/main.rs`

```rust
use common::types::{Order, OrderStatus};
use std::collections::HashMap;
use tokio::sync::mpsc;

#[derive(Debug, Clone)]
struct OrderState {
    order: Order,
    status: OrderStatus,
}

#[tokio::main]
async fn main() {
    let (new_order_tx, mut new_order_rx) = mpsc::channel::<Order>(1024);
    let (status_tx, mut status_rx) = mpsc::channel::<(u64, OrderStatus)>(1024);

    let mut book: HashMap<u64, OrderState> = HashMap::new();

    tokio::spawn(async move {
        while let Some(order) = new_order_rx.recv().await {
            book.insert(
                order.id,
                OrderState {
                    order: order.clone(),
                    status: OrderStatus::New,
                },
            );

            println!("OMS received order {}", order.id);

            // In production: send to risk service, then execution gateway
            let _ = status_tx.send((order.id, OrderStatus::Accepted)).await;
        }
    });

    while let Some((order_id, status)) = status_rx.recv().await {
        if let Some(state) = book.get_mut(&order_id) {
            state.status = status;
            println!("Order {} status updated to {:?}", order_id, status);
        }
    }
}
```

