# 9. Execution gateway skeleton

This is where exchange connectivity lives. Keep it isolated.

## `execution/src/main.rs`

```rust
use common::types::{Fill, Order, OrderStatus};
use tokio::sync::mpsc;
use tokio::time::{sleep, Duration};

#[tokio::main]
async fn main() {
    let (order_tx, mut order_rx) = mpsc::channel::<Order>(1024);
    let (fill_tx, mut fill_rx) = mpsc::channel::<Fill>(1024);

    tokio::spawn(async move {
        while let Some(order) = order_rx.recv().await {
            println!("Sending order {} to exchange...", order.id);

            sleep(Duration::from_millis(2)).await;

            let fill = Fill {
                order_id: order.id,
                filled_qty: order.qty,
                avg_price: order.price.unwrap_or(0.0),
                ts_nanos: 0,
            };

            let _ = fill_tx.send(fill).await;
        }
    });

    while let Some(fill) = fill_rx.recv().await {
        println!("Received fill: {:?}", fill);
    }
}
```

