# src/risk/risk_engine.rs

```rust
use anyhow::Result;
use crate::common::types::Order;

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_order_notional: f64,
}

pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn check(&self, order: &Order) -> Result<()> {
        if order.quantity <= 0.0 {
            anyhow::bail!("quantity must be positive");
        }

        if order.quantity > self.limits.max_order_qty {
            anyhow::bail!("order quantity exceeds max limit");
        }

        let notional = order.quantity * order.price;
        if notional > self.limits.max_order_notional {
            anyhow::bail!("order notional exceeds max limit");
        }

        Ok(())
    }
}
```

