```rust
use crate::common::types::{MarketTick, Order, Side};
use uuid::Uuid;

pub trait Strategy: Send + Sync {
    fn on_tick(&self, tick: &MarketTick) -> Option<Order>;
}

pub struct SimpleSpreadStrategy {
    pub symbol: String,
    pub threshold: f64,
    pub order_size: f64,
}

impl Strategy for SimpleSpreadStrategy {
    fn on_tick(&self, tick: &MarketTick) -> Option<Order> {
        if tick.symbol != self.symbol {
            return None;
        }

        let spread = tick.ask - tick.bid;
        if spread > self.threshold {
            Some(Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                quantity: self.order_size,
                price: tick.bid,
            })
        } else {
            None
        }
    }
}
