use std::sync::Arc;
use anyhow::Result;
use tracing::{info, warn};

use crate::{
    bus::event_bus::EventBus,
    common::{events::Event, types::Order},
    execution::gateway::ExecutionGateway,
    risk::risk_engine::RiskEngine,
};

pub struct OMS<G: ExecutionGateway> {
    risk: Arc<RiskEngine>,
    gateway: Arc<G>,
    bus: EventBus,
}

impl<G: ExecutionGateway> OMS<G> {
    pub fn new(risk: Arc<RiskEngine>, gateway: Arc<G>, bus: EventBus) -> Self {
        Self { risk, gateway, bus }
    }

    pub async fn submit(&self, order: Order) -> Result<()> {
        if let Err(err) = self.risk.check(&order) {
            warn!("Risk rejected order {}: {}", order.id, err);
            self.bus.publish(Event::OrderRejected {
                order_id: order.id,
                reason: err.to_string(),
            });
            return Ok(());
        }

        info!("Order accepted: {}", order.id);
        self.bus.publish(Event::OrderAccepted(order.clone()));
        self.gateway.submit_order(order).await?;
        Ok(())
    }
}
```

