mod bus;
mod common;
mod execution;
mod market_data;
mod oms;
mod risk;
mod strategy;

use std::sync::Arc;
use tracing::{info, error};
use tracing_subscriber::EnvFilter;

use bus::event_bus::EventBus;
use common::events::Event;
use execution::mock_gateway::MockGateway;
use market_data::feed_handler::FeedHandler;
use oms::oms::OMS;
use risk::risk_engine::{RiskEngine, RiskLimits};
use strategy::strategy::{SimpleSpreadStrategy, Strategy};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let bus = EventBus::new(1024);

    let risk = Arc::new(RiskEngine::new(RiskLimits {
        max_order_qty: 100.0,
        max_order_notional: 10_000_000.0,
    }));

    let gateway = Arc::new(MockGateway);
    let oms = Arc::new(OMS::new(risk.clone(), gateway, bus.clone()));

    let strategy = Arc::new(SimpleSpreadStrategy {
        symbol: "BTC-USD".to_string(),
        threshold: 0.2,
        order_size: 0.01,
    });

    let feed = Arc::new(FeedHandler::new(bus.clone()));

    // Strategy event loop
    {
        let mut rx = bus.subscribe();
        let oms_clone = oms.clone();
        let strategy_clone = strategy.clone();

        tokio::spawn(async move {
            loop {
                match rx.recv().await {
                    Ok(Event::MarketTick(tick)) => {
                        if let Some(order) = strategy_clone.on_tick(&tick) {
                            if let Err(err) = oms_clone.submit(order).await {
                                error!("OMS submit error: {:?}", err);
                            }
                        }
                    }
                    Ok(_) => {}
                    Err(err) => {
                        error!("bus recv error: {:?}", err);
                        break;
                    }
                }
            }
        });
    }

    // Market data loop
    tokio::spawn(feed.run());

    info!("Trading platform started");
    loop {
        tokio::time::sleep(std::time::Duration::from_secs(60)).await;
    }
}
