# 9) Risk engine

Keep it fast and deterministic:

- max order size
- max position per symbol
- max notional per order
- daily loss limit
- order rate limits
- instrument whitelist

```rust
// crates/risk/src/engine.rs
use std::collections::HashMap;
use common::types::*;

pub struct RiskEngine {
    max_order_qty: i64,
    max_position_per_symbol: i64,
    positions: HashMap<SymbolId, i64>,
}

impl RiskEngine {
    pub fn new(max_order_qty: i64, max_position_per_symbol: i64) -> Self {
        Self {
            max_order_qty,
            max_position_per_symbol,
            positions: HashMap::new(),
        }
    }

    pub fn validate_new_order(&self, order: &OrderRequest) -> Result<(), String> {
        if order.quantity.0 <= 0 {
            return Err("quantity must be positive".into());
        }
        if order.quantity.0 > self.max_order_qty {
            return Err("order quantity exceeds limit".into());
        }
        Ok(())
    }

    pub fn on_fill(&mut self, symbol: SymbolId, side: Side, qty: Quantity) {
        let pos = self.positions.entry(symbol).or_insert(0);
        match side {
            Side::Buy => *pos += qty.0,
            Side::Sell => *pos -= qty.0,
        }
    }
}
```

