# 10) OMS state machine

The OMS should own order lifecycle transitions.

```rust
// crates/oms/src/state.rs
use std::collections::HashMap;
use common::types::*;

#[derive(Debug)]
pub struct OrderRecord {
    pub request: OrderRequest,
    pub state: OrderState,
    pub exchange_order_id: Option<OrderId>,
    pub filled_qty: i64,
}

pub struct OrderManager {
    orders: HashMap<ClientOrderId, OrderRecord>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
        }
    }

    pub fn on_new_order(&mut self, request: OrderRequest) {
        self.orders.insert(
            request.client_order_id,
            OrderRecord {
                request,
                state: OrderState::New,
                exchange_order_id: None,
                filled_qty: 0,
            },
        );
    }

    pub fn on_ack(&mut self, client_order_id: ClientOrderId, order_id: OrderId) {
        if let Some(order) = self.orders.get_mut(&client_order_id) {
            order.state = OrderState::Acked;
            order.exchange_order_id = Some(order_id);
        }
    }

    pub fn on_fill(&mut self, client_order_id: ClientOrderId, qty: Quantity) {
        if let Some(order) = self.orders.get_mut(&client_order_id) {
            order.filled_qty += qty.0;
            if order.filled_qty >= order.request.quantity.0 {
                order.state = OrderState::Filled;
            } else {
                order.state = OrderState::PartiallyFilled;
            }
        }
    }
}
```

