# 12) Execution adapter

A venue adapter should be isolated behind a trait.

```rust
// crates/execution/src/adapter.rs
use common::types::*;

pub trait ExecutionAdapter: Send + Sync {
    fn send_new_order(&self, order: &OrderRequest) -> Result<OrderId, String>;
    fn cancel_order(&self, client_order_id: ClientOrderId) -> Result<(), String>;
}

pub struct SimulatedAdapter {
    next_id: std::sync::atomic::AtomicU64,
}

impl SimulatedAdapter {
    pub fn new() -> Self {
        Self {
            next_id: std::sync::atomic::AtomicU64::new(1),
        }
    }
}

impl ExecutionAdapter for SimulatedAdapter {
    fn send_new_order(&self, _order: &OrderRequest) -> Result<OrderId, String> {
        let id = self.next_id.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        Ok(OrderId(id))
    }

    fn cancel_order(&self, _client_order_id: ClientOrderId) -> Result<(), String> {
        Ok(())
    }
}
```

