# 13) Main application wiring

A single process can wire everything together for the first version.

```rust
// crates/app/src/main.rs
use common::events::*;
use common::types::*;
use crossbeam_channel::{bounded, Receiver, Sender};

fn main() {
    let (market_tx, market_rx): (Sender<StrategyEvent>, Receiver<StrategyEvent>) = bounded(1024);
    let (order_tx, order_rx): (Sender<OrderCommand>, Receiver<OrderCommand>) = bounded(1024);

    let strategy = strategy::simple_strategy::SimpleStrategy::new(100);
    let mut risk = risk::engine::RiskEngine::new(1000, 10000);
    let mut oms = oms::state::OrderManager::new();
    let adapter = execution::adapter::SimulatedAdapter::new();

    // Example market event
    let tick = MarketTick {
        symbol: SymbolId(1),
        bid: Price(98),
        ask: Price(99),
        bid_qty: Quantity(10),
        ask_qty: Quantity(10),
        sequence: 1,
    };

    market_tx.send(StrategyEvent::MarketTick(tick)).unwrap();

    while let Ok(event) = market_rx.recv() {
        if let Some(cmd) = strategy.on_event(&event) {
            order_tx.send(cmd).unwrap();
        }

        while let Ok(cmd) = order_rx.try_recv() {
            match cmd {
                OrderCommand::New(order) => {
                    if risk.validate_new_order(&order).is_ok() {
                        oms.on_new_order(order.clone());
                        let order_id = adapter.send_new_order(&order).unwrap();
                        oms.on_ack(order.client_order_id, order_id);
                    }
                }
                OrderCommand::Cancel { client_order_id } => {
                    adapter.cancel_order(client_order_id).unwrap();
                }
            }
        }
    }
}
```

