## `src/risk/limits.rs`

```rust
use crate::event::{OrderIntent, RiskDecision};

pub struct RiskEngine {
    pub max_order_qty: f64,
    pub kill_switch: bool,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64) -> Self {
        Self {
            max_order_qty,
            kill_switch: false,
        }
    }

    pub fn evaluate(&self, intent: &OrderIntent) -> RiskDecision {
        if self.kill_switch {
            return RiskDecision {
                meta: intent.meta.clone(),
                approved: false,
                reason: Some("Kill switch active".to_string()),
            };
        }

        if intent.qty > self.max_order_qty {
            return RiskDecision {
                meta: intent.meta.clone(),
                approved: false,
                reason: Some(format!(
                    "Order qty {} exceeds max {}",
                    intent.qty, self.max_order_qty
                )),
            };
        }

        RiskDecision {
            meta: intent.meta.clone(),
            approved: true,
            reason: None,
        }
    }

    pub fn set_kill_switch(&mut self, enabled: bool) {
        self.kill_switch = enabled;
    }
}
