## `src/app.rs`

```rust
use std::thread;

use uuid::Uuid;

use crate::{
    bus::EventBus,
    event::{
        ControlCommand, ControlEvent, Event, EventMeta, MarketDataEvent, OrderEvent, OrderStatus,
        SignalEvent,
    },
    execution::mock_gateway::MockGateway,
    oms::state::OmsState,
    risk::limits::RiskEngine,
    strategy::simple_momentum::SimpleMomentumStrategy,
};

pub struct TradingApp {
    bus: EventBus,
    strategy: SimpleMomentumStrategy,
    risk: RiskEngine,
    oms: OmsState,
    gateway: MockGateway,
}

impl TradingApp {
    pub fn new(bus: EventBus) -> Self {
        Self {
            bus,
            strategy: SimpleMomentumStrategy::new(0.5),
            risk: RiskEngine::new(100.0),
            oms: OmsState::new(),
            gateway: MockGateway::new(),
        }
    }

    pub fn run(mut self, rx: crossbeam::channel::Receiver<Event>) {
        for event in rx.iter() {
            match event {
                Event::MarketData(md) => {
                    let signal_strength = if md.last > md.ask { 1.0 } else if md.last < md.bid { -1.0 } else { 0.0 };

                    let signal = SignalEvent {
                        meta: md.meta.clone(),
                        symbol: md.symbol.clone(),
                        signal_strength,
                    };

                    if let Some(intent) = self.strategy.on_signal(&signal) {
                        let decision = self.risk.evaluate(&intent);
                        if decision.approved {
                            let order = OrderEvent {
                                meta: EventMeta {
                                    event_id: Uuid::new_v4(),
                                    timestamp_ns: intent.meta.timestamp_ns + 1_000,
                                    correlation_id: intent.meta.correlation_id,
                                    source: "oms".to_string(),
                                },
                                order_id: Uuid::new_v4(),
                                symbol: intent.symbol.clone(),
                                side: intent.side.clone(),
                                qty: intent.qty,
                                status: OrderStatus::New,
                            };

                            self.oms.apply_order(order.clone());
                            let fills = self.gateway.send_order(&order);

                            self.oms.update_status(order.order_id, OrderStatus::Filled);
                            for fill in fills {
                                self.bus.publish(Event::Fill(fill));
                            }

                            self.bus.publish(Event::Order(order));
                        }
                    }
                }
                Event::Control(ControlEvent { command, .. }) => match command {
                    ControlCommand::KillSwitch(enabled) => self.risk.set_kill_switch(enabled),
                    ControlCommand::SetMaxOrderQty(qty) => self.risk.max_order_qty = qty,
                },
                _ => {}
            }
        }
    }
}
```

