## `strategy.rs`

```rust
use crate::types::{MarketTick, OrderIntent, OrderType, Side, TradingEvent};
use tokio::sync::broadcast;

pub struct Strategy {
    pub strategy_id: String,
    pub symbol: String,
    pub threshold: f64,
}

impl Strategy {
    pub fn new(strategy_id: impl Into<String>, symbol: impl Into<String>, threshold: f64) -> Self {
        Self {
            strategy_id: strategy_id.into(),
            symbol: symbol.into(),
            threshold,
        }
    }

    pub async fn run(
        self,
        mut rx: broadcast::Receiver<TradingEvent>,
        tx: broadcast::Sender<TradingEvent>,
    ) {
        while let Ok(event) = rx.recv().await {
            if let TradingEvent::MarketTick(tick) = event {
                if tick.symbol != self.symbol {
                    continue;
                }

                // Example: trivial mean-reversion-like signal
                let mid = (tick.bid + tick.ask) / 2.0;
                let deviation = (tick.last - mid).abs() / mid;

                if deviation > self.threshold {
                    let side = if tick.last < mid { Side::Buy } else { Side::Sell };

                    let intent = OrderIntent {
                        strategy_id: self.strategy_id.clone(),
                        symbol: tick.symbol.clone(),
                        side,
                        qty: 1.0,
                        price: Some(tick.last),
                        order_type: OrderType::Limit,
                    };

                    let _ = tx.send(TradingEvent::OrderIntent(intent));
                }
            }
        }
    }
}
```

