use crate::types::{Order, OrderIntent, TradingEvent};
use tokio::sync::broadcast;

pub struct RiskManager {
    pub max_order_qty: f64,
}

impl RiskManager {
    pub fn new(max_order_qty: f64) -> Self {
        Self { max_order_qty }
    }

    pub async fn run(
        self,
        mut rx: broadcast::Receiver<TradingEvent>,
        tx: broadcast::Sender<TradingEvent>,
    ) {
        while let Ok(event) = rx.recv().await {
            if let TradingEvent::OrderIntent(intent) = event {
                if intent.qty <= 0.0 || intent.qty > self.max_order_qty {
                    continue;
                }

                let order = Order {
                    id: uuid::Uuid::new_v4(),
                    strategy_id: intent.strategy_id,
                    symbol: intent.symbol,
                    side: intent.side,
                    qty: intent.qty,
                    price: intent.price,
                    order_type: intent.order_type,
                };

                let _ = tx.send(TradingEvent::Order(order));
            }
        }
    }
}
