        while let Ok(event) = rx.recv().await {
            if let TradingEvent::Order(order) = event {
                info!("Submitting order: {:?}", order);

                let accepted = OrderEvent {
                    order_id: order.id,
                    status: OrderStatus::Accepted,
                    ts_ns: Utc::now().timestamp_nanos_opt().unwrap_or_default() as i128,
