        Self {
            positions: DashMap::new(),
        }
    }

    pub async fn run(self, mut rx: broadcast::Receiver<TradingEvent>) {
        while let Ok(event) = rx.recv().await {
            if let TradingEvent::OrderEvent(order_event) = event {
                if let OrderStatus::Filled { qty, .. } = order_event.status {
                    info!("Fill received: {:?}", order_event);
                    let entry = self.positions.entry("UNKNOWN".to_string()).or_insert(0.0);
                    *entry += qty;
                }
            }
        }
    }
}
