use crate::types::TradingEvent;
use std::fs::OpenOptions;
use std::io::Write;
use std::sync::Mutex;

pub struct EventStore {
    file: Mutex<std::fs::File>,
}

impl EventStore {
    pub fn new(path: &str) -> anyhow::Result<Self> {
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)?;
        Ok(Self {
            file: Mutex::new(file),
        })
    }

    pub fn append(&self, event: &TradingEvent) -> anyhow::Result<()> {
        let mut file = self.file.lock().unwrap();
        let line = serde_json::to_string(event)?;
        writeln!(file, "{line}")?;
        Ok(())
    }
}
