use crate::domain::market_event::MarketTick;
use crate::domain::order::{Order, OrderStatus, OrderType, Side};

pub struct StrategyEngine {
    pub threshold: f64,
}

impl StrategyEngine {
    pub fn on_tick(&self, tick: &MarketTick) -> Option<Order> {
        let mid = (tick.bid + tick.ask) / 2.0;

        if tick.last > mid + self.threshold {
            Some(Order {
                client_order_id: format!("buy-{}", tick.timestamp_ns),
                instrument: tick.instrument.clone(),
                side: Side::Buy,
                quantity: 1.0,
                order_type: OrderType::Market,
                status: OrderStatus::New,
            })
        } else if tick.last < mid - self.threshold {
            Some(Order {
                client_order_id: format!("sell-{}", tick.timestamp_ns),
                instrument: tick.instrument.clone(),
                side: Side::Sell,
                quantity: 1.0,
                order_type: OrderType::Market,
                status: OrderStatus::New,
            })
        } else {
            None
        }
    }
}
