use std::sync::Arc;
use tokio::sync::mpsc;

pub struct InMemoryBus<T> {
    tx: mpsc::Sender<T>,
}

impl<T: Send + 'static> InMemoryBus<T> {
    pub fn new(buffer: usize) -> (Self, mpsc::Receiver<T>) {
        let (tx, rx) = mpsc::channel(buffer);
        (Self { tx }, rx)
    }

    pub async fn publish(&self, item: T) -> Result<(), mpsc::error::SendError<T>> {
        self.tx.send(item).await
    }

    pub fn clone_sender(&self) -> mpsc::Sender<T> {
        self.tx.clone()
    }
}
