use crate::domain::events::{OrderIntent, OrderType};

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
    pub enabled: bool,
}

impl Default for RiskLimits {
    fn default() -> Self {
        Self {
            max_order_qty: 1000.0,
            max_notional: 1_000_000.0,
            enabled: true,
        }
    }
}

pub fn validate(intent: &OrderIntent, limits: &RiskLimits, last_price: f64) -> Result<(), String> {
    if !limits.enabled {
        return Err("risk disabled".to_string());
    }

    if intent.qty <= 0.0 {
        return Err("qty must be positive".to_string());
    }

    if intent.qty > limits.max_order_qty {
        return Err(format!("qty exceeds max_order_qty: {}", intent.qty));
    }

    let reference_price = match intent.order_type {
        OrderType::Market => last_price,
        OrderType::Limit { price } => price,
    };

    if intent.qty * reference_price > limits.max_notional {
        return Err("notional exceeds max_notional".to_string());
    }

    Ok(())
}
```

