```rust
use std::collections::HashMap;
use crate::domain::events::{ExecutionEvent, OrderIntent};

#[derive(Debug, Clone)]
pub enum OrderState {
    New,
    Accepted,
    Filled,
    Rejected(String),
    Canceled,
}

pub struct OrderManager {
    orders: HashMap<String, (OrderIntent, OrderState)>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
        }
    }

    pub fn submit(&mut self, intent: OrderIntent) {
        self.orders.insert(intent.client_order_id.clone(), (intent, OrderState::New));
    }

    pub fn on_execution_event(&mut self, evt: ExecutionEvent) {
        match evt {
            ExecutionEvent::NewOrderAccepted { client_order_id, .. } => {
                if let Some((_intent, state)) = self.orders.get_mut(&client_order_id) {
                    *state = OrderState::Accepted;
                }
            }
            ExecutionEvent::OrderFilled { client_order_id, .. } => {
                if let Some((_intent, state)) = self.orders.get_mut(&client_order_id) {
                    *state = OrderState::Filled;
                }
            }
            ExecutionEvent::OrderRejected { client_order_id, reason } => {
                if let Some((_intent, state)) = self.orders.get_mut(&client_order_id) {
                    *state = OrderState::Rejected(reason);
                }
            }
            ExecutionEvent::OrderCanceled { client_order_id } => {
                if let Some((_intent, state)) = self.orders.get_mut(&client_order_id) {
                    *state = OrderState::Canceled;
                }
            }
        }
    }
}
