    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (exec_tx, mut exec_rx) = mpsc::channel::<ExecutionEvent>(1024);
    let gateway = ExecutionGateway::new(exec_tx.clone());

    let strategy = ExampleStrategy {
        strategy_id: "strategy-1".to_string(),
        symbol: "AAPL".to_string(),
        threshold: 100.0,
    };

    let limits = RiskLimits::default();
    let mut oms = OrderManager::new();

    // Execution event consumer
    tokio::spawn(async move {
        while let Some(evt) = exec_rx.recv().await {
            info!("execution event: {:?}", evt);
            oms.on_execution_event(evt);
        }
