```go
package main

import (
	"context"
	"fmt"
	"math/rand"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a high-frequency message.
// SentAt is used for end-to-end latency measurement.
type Message struct {
	ID      uint64
	RouteID uint32
	Payload []byte
	SentAt  int64 // unix nanos
}

// Metrics holds atomic counters and latency observations.
type Metrics struct {
	Enqueued   uint64
	Processed  uint64
	Dropped    uint64
	TotalNanos uint64
}

// LatencyHistogram is a simple fixed-bucket histogram for nanosecond latencies.
type LatencyHistogram struct {
	buckets []uint64
	upperNs []uint64
}

func NewLatencyHistogram() *LatencyHistogram {
	// Buckets roughly from 1us to 100ms
	upper := []uint64{
		1_000, 2_000, 5_000, 10_000, 20_000, 50_000, 100_000,
		200_000, 500_000, 1_000_000, 2_000_000, 5_000_000,
		10_000_000, 20_000_000, 50_000_000, 100_000_000,
	}
	return &LatencyHistogram{
		buckets: make([]uint64, len(upper)+1),
		upperNs: upper,
	}
}

func (h *LatencyHistogram) Observe(nanos uint64) {
	i := 0
	for i < len(h.upperNs) && nanos > h.upperNs[i] {
		i++
	}
	atomic.AddUint64(&h.buckets[i], 1)
}

func (h *LatencyHistogram) Snapshot() []uint64 {
	out := make([]uint64, len(h.buckets))
	for i := range out {
		out[i] = atomic.LoadUint64(&h.buckets[i])
	}
	return out
}

// Worker handles messages for a route shard.
type Worker struct {
	id       int
	ch       chan Message
	metrics  *Metrics
	hist     *LatencyHistogram
	stopOnce sync.Once
	stopCh   chan struct{}
}

func NewWorker(id int, queueSize int, metrics *Metrics, hist *LatencyHistogram) *Worker {
	return &Worker{
		id:      id,
		ch:      make(chan Message, queueSize),
		metrics: metrics,
		hist:    hist,
		stopCh:  make(chan struct{}),
	}
}

func (w *Worker) Start(ctx context.Context, wg *sync.WaitGroup) {
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-ctx.Done():
				return
			case <-w.stopCh:
				return
			case msg := <-w.ch:
				// Simulate actual work; replace with real handler.
				_ = msg.Payload

				now := time.Now().UnixNano()
				latency := uint64(now - msg.SentAt)

				atomic.AddUint64(&w.metrics.Processed, 1)
				atomic.AddUint64(&w.metrics.TotalNanos, latency)
				w.hist.Observe(latency)
			}
		}
	}()
}

func (w *Worker) Stop() {
	w.stopOnce.Do(func() {
		close(w.stopCh)
	})
}

func (w *Worker) TryEnqueue(msg Message) bool {
	select {
	case w.ch <- msg:
		atomic.AddUint64(&w.metrics.Enqueued, 1)
		return true
	default:
		atomic.AddUint64(&w.metrics.Dropped, 1)
		return false
	}
}

// Router maps messages to workers using route ID sharding.
type Router struct {
	workers []*Worker
	mask    uint32
}

func NewRouter(numWorkers int, queueSize int, metrics *Metrics, hist *LatencyHistogram) *Router {
	// Prefer power-of-two workers for fast masking.
	n := 1
	for n < numWorkers {
		n <<= 1
	}

	workers := make([]*Worker, n)
	for i := 0; i < n; i++ {
		workers[i] = NewWorker(i, queueSize, metrics, hist)
	}

	return &Router{
		workers: workers,
		mask:    uint32(n - 1),
	}
}

func (r *Router) Start(ctx context.Context, wg *sync.WaitGroup) {
	for _, w := range r.workers {
		w.Start(ctx, wg)
	}
}

func (r *Router) Stop() {
	for _, w := range r.workers {
		w.Stop()
	}
}

func (r *Router) Route(msg Message) bool {
	idx := msg.RouteID & r.mask
	return r.workers[idx].TryEnqueue(msg)
}

// Producer generates messages at high rate.
func Producer(ctx context.Context, router *Router, id int, ratePerSec int, payloadSize int) {
	interval := time.Second / time.Duration(ratePerSec)
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	payload := make([]byte, payloadSize)
	rng := rand.New(rand.NewSource(time.Now().UnixNano() + int64(id)))

	var seq uint64
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			seq++
			for i := range payload {
				payload[i] = byte(rng.Intn(256))
			}

			msg := Message{
				ID:      seq,
				RouteID: uint32(rng.Int()),
				Payload: append([]byte(nil), payload...),
				SentAt:  time.Now().UnixNano(),
			}

			router.Route(msg)
		}
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	var wg sync.WaitGroup
	metrics := &Metrics{}
	hist := NewLatencyHistogram()

	router := NewRouter(
		// number of shards/workers
		16,
		// queue size per worker
		65536,
		metrics,
		hist,
	)

	router.Start(ctx, &wg)

	// Start producers.
	producerCount := 8
	for i := 0; i < producerCount; i++ {
		go Producer(ctx, router, i, 200_000, 128)
	}

	// Monitoring loop.
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	start := time.Now()
	for i := 0; i < 15; i++ {
		<-ticker.C

		enq := atomic.LoadUint64(&metrics.Enqueued)
		proc := atomic.LoadUint64(&metrics.Processed)
		drop := atomic.LoadUint64(&metrics.Dropped)
		totalNs := atomic.LoadUint64(&metrics.TotalNanos)

		avgLatency := time.Duration(0)
		if proc > 0 {
			avgLatency = time.Duration(totalNs / proc)
		}

		elapsed := time.Since(start).Seconds()
		fmt.Printf(
			"t=%.0fs enqueued=%d processed=%d dropped=%d avgLatency=%s throughput=%.0f msg/s\n",
			elapsed,
			enq,
			proc,
			drop,
			avgLatency,
			float64(proc)/elapsed,
		)
	}

	cancel()
	router.Stop()
	wg.Wait()

	fmt.Println("Final histogram:")
	snap := hist.Snapshot()
	for i, v := range snap {
		fmt.Printf("bucket[%d]=%d\n", i, v)
	}
}
