```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Key       string
	Payload   []byte
	CreatedAt time.Time
}

type Subscriber struct {
	ID   string
	C    chan Message
	done chan struct{}
}

func NewSubscriber(id string, buffer int) *Subscriber {
	return &Subscriber{
		ID:   id,
		C:    make(chan Message, buffer),
		done: make(chan struct{}),
	}
}

func (s *Subscriber) Close() {
	close(s.done)
	close(s.C)
}

type Metrics struct {
	Published      atomic.Uint64
	Routed         atomic.Uint64
	Dropped        atomic.Uint64
	Delivered      atomic.Uint64
	TotalLatencyNs  atomic.Uint64
	MaxLatencyNs    atomic.Uint64
	CurrentInQueue  atomic.Int64
	Subscriptions   atomic.Uint64
	Unsubscriptions atomic.Uint64
}

func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	m.TotalLatencyNs.Add(ns)
	for {
		old := m.MaxLatencyNs.Load()
		if ns <= old {
			break
		}
		if m.MaxLatencyNs.CompareAndSwap(old, ns) {
			break
		}
	}
}

func (m *Metrics) Snapshot() string {
	delivered := m.Delivered.Load()
	avg := time.Duration(0)
	if delivered > 0 {
		avg = time.Duration(m.TotalLatencyNs.Load() / delivered)
	}
	return fmt.Sprintf(
		"published=%d routed=%d delivered=%d dropped=%d avg_latency=%s max_latency=%s in_queue=%d subs=%d unsubs=%d",
		m.Published.Load(),
		m.Routed.Load(),
		delivered,
		m.Dropped.Load(),
		avg,
		time.Duration(m.MaxLatencyNs.Load()),
		m.CurrentInQueue.Load(),
		m.Subscriptions.Load(),
		m.Unsubscriptions.Load(),
	)
}

type Shard struct {
	mu          sync.RWMutex
	subscribers map[string]*Subscriber
	in          chan Message
	metrics     *Metrics
}

func NewShard(queueSize int, metrics *Metrics) *Shard {
	return &Shard{
		subscribers: make(map[string]*Subscriber),
		in:          make(chan Message, queueSize),
		metrics:     metrics,
	}
}

func (s *Shard) AddSubscriber(sub *Subscriber) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.subscribers[sub.ID] = sub
	s.metrics.Subscriptions.Add(1)
}

func (s *Shard) RemoveSubscriber(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if sub, ok := s.subscribers[id]; ok {
		delete(s.subscribers, id)
		s.metrics.Unsubscriptions.Add(1)
		sub.Close()
	}
}

func (s *Shard) Publish(msg Message) bool {
	select {
	case s.in <- msg:
		s.metrics.Published.Add(1)
		s.metrics.CurrentInQueue.Add(1)
		return true
	default:
		s.metrics.Dropped.Add(1)
		return false
	}
}

func (s *Shard) Run(ctx context.Context) {
	for {
		select {
		case <-ctx.Done():
			return
		case msg := <-s.in:
			s.metrics.CurrentInQueue.Add(-1)
			s.metrics.Routed.Add(1)

			latency := time.Since(msg.CreatedAt)
			s.metrics.ObserveLatency(latency)

			s.mu.RLock()
			for _, sub := range s.subscribers {
				select {
				case sub.C <- msg:
					s.metrics.Delivered.Add(1)
				default:
					// subscriber slow, drop to protect throughput
					s.metrics.Dropped.Add(1)
				}
			}
			s.mu.RUnlock()
		}
	}
}

type Router struct {
	shards  []*Shard
	mask    uint32
	metrics *Metrics
}

func NewRouter(numShards int, queueSize int) *Router {
	// numShards should ideally be a power of two for fast masking
	metrics := &Metrics{}
	shards := make([]*Shard, numShards)
	for i := range shards {
		shards[i] = NewShard(queueSize, metrics)
	}
	return &Router{
		shards:  shards,
		mask:    uint32(numShards - 1),
		metrics: metrics,
	}
}

func (r *Router) shardFor(key string) *Shard {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	idx := h.Sum32() & r.mask
	return r.shards[idx]
}

func (r *Router) Publish(msg Message) bool {
	shard := r.shardFor(msg.Key)
	return shard.Publish(msg)
}

func (r *Router) Subscribe(key string, sub *Subscriber) {
	shard := r.shardFor(key)
	shard.AddSubscriber(sub)
}

func (r *Router) Unsubscribe(key, id string) {
	shard := r.shardFor(key)
	shard.RemoveSubscriber(id)
}

func (r *Router) Run(ctx context.Context) {
	for _, shard := range r.shards {
		go shard.Run(ctx)
	}
}

func (r *Router) Metrics() *Metrics {
	return r.metrics
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// 8 shards, each with a bounded incoming queue.
	router := NewRouter(8, 4096)
	router.Run(ctx)

	// Metrics reporter
	go func() {
		t := time.NewTicker(2 * time.Second)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				log.Println(router.Metrics().Snapshot())
			}
		}
	}()

	// Subscriber
	sub := NewSubscriber("sub-1", 1024)
	go func() {
		for msg := range sub.C {
			_ = msg
			// handle message
		}
	}()

	// Subscribe to a topic/key
	router.Subscribe("orders", sub)

	// Producer loop
	go func() {
		ticker := time.NewTicker(100 * time.Microsecond) // high-rate example
		defer ticker.Stop()

		i := 0
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				msg := Message{
					Topic:     "trade-events",
					Key:       "orders",
					Payload:   []byte(fmt.Sprintf("msg-%d", i)),
					CreatedAt: time.Now(),
				}
				_ = router.Publish(msg)
				i++
			}
		}
	}()

	// Simulate running
	time.Sleep(5 * time.Second)
}
