## Go implementation

```go
package main

import (
	"fmt"
	"log"
	"math/rand"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt  int64 // unix nano
	EnqueuedAt int64 // unix nano
}

type Subscriber struct {
	ID      string
	Ch      chan Message
	alive   atomic.Bool
	latency LatencyStats
}

type LatencyStats struct {
	Count      uint64
	SumNanos   uint64
	MaxNanos   uint64
	MinNanos   uint64
	LastNanos  uint64
}

func (s *LatencyStats) Observe(ns uint64) {
	atomic.AddUint64(&s.Count, 1)
	atomic.AddUint64(&s.SumNanos, ns)
	atomic.StoreUint64(&s.LastNanos, ns)

	for {
		oldMax := atomic.LoadUint64(&s.MaxNanos)
		if ns <= oldMax {
			break
		}
		if atomic.CompareAndSwapUint64(&s.MaxNanos, oldMax, ns) {
			break
		}
	}

	for {
		oldMin := atomic.LoadUint64(&s.MinNanos)
		if oldMin != 0 && ns >= oldMin {
			break
		}
		if atomic.CompareAndSwapUint64(&s.MinNanos, oldMin, ns) {
			break
		}
	}
}

type Router struct {
	mu          sync.RWMutex
	subscribers map[string][]*Subscriber
	nextID      uint64

	// routing / ingest metrics
	ingested    uint64
	routed      uint64
	dropped     uint64
	processed   uint64
	totalLagNs  uint64
	maxLagNs    uint64

	// bounded queue for routing work
	queue chan Message
	stop  chan struct{}
	wg    sync.WaitGroup
}

func NewRouter(queueSize int, workers int) *Router {
	r := &Router{
		subscribers: make(map[string][]*Subscriber),
		queue:       make(chan Message, queueSize),
		stop:        make(chan struct{}),
	}
	for i := 0; i < workers; i++ {
		r.wg.Add(1)
		go r.worker()
	}
	return r
}

func (r *Router) Subscribe(topic string, buffer int) *Subscriber {
	sub := &Subscriber{
		ID: fmt.Sprintf("sub-%d", atomic.AddUint64(&r.nextID, 1)),
		Ch: make(chan Message, buffer),
	}
	sub.alive.Store(true)

	r.mu.Lock()
	r.subscribers[topic] = append(r.subscribers[topic], sub)
	r.mu.Unlock()

	return sub
}

func (r *Router) Unsubscribe(topic string, sub *Subscriber) {
	r.mu.Lock()
	defer r.mu.Unlock()

	subs := r.subscribers[topic]
	dst := subs[:0]
	for _, s := range subs {
		if s != sub {
			dst = append(dst, s)
		}
	}
	if len(dst) == 0 {
		delete(r.subscribers, topic)
	} else {
		r.subscribers[topic] = dst
	}
	sub.alive.Store(false)
	close(sub.Ch)
}

func (r *Router) Publish(msg Message) bool {
	atomic.AddUint64(&r.ingested, 1)
	msg.EnqueuedAt = time.Now().UnixNano()

	select {
	case r.queue <- msg:
		return true
	default:
		atomic.AddUint64(&r.dropped, 1)
		return false
	}
}

func (r *Router) worker() {
	defer r.wg.Done()

	for {
		select {
		case msg := <-r.queue:
			r.route(msg)
		case <-r.stop:
			return
		}
	}
}

func (r *Router) route(msg Message) {
	r.mu.RLock()
	subs := append([]*Subscriber(nil), r.subscribers[msg.Topic]...)
	r.mu.RUnlock()

	atomic.AddUint64(&r.routed, 1)

	for _, sub := range subs {
		if !sub.alive.Load() {
			continue
		}

		// Non-blocking subscriber delivery
		select {
		case sub.Ch <- msg:
		default:
			// slow consumer: drop per-subscriber to protect latency
		}
	}

	// latency monitoring
	lag := uint64(time.Now().UnixNano() - msg.CreatedAt)
	atomic.AddUint64(&r.totalLagNs, lag)
	for {
		old := atomic.LoadUint64(&r.maxLagNs)
		if lag <= old {
			break
		}
		if atomic.CompareAndSwapUint64(&r.maxLagNs, old, lag) {
			break
		}
	}

	atomic.AddUint64(&r.processed, 1)
}

func (r *Router) Metrics() map[string]uint64 {
	ing := atomic.LoadUint64(&r.ingested)
	route := atomic.LoadUint64(&r.routed)
	drop := atomic.LoadUint64(&r.dropped)
	proc := atomic.LoadUint64(&r.processed)
	totalLag := atomic.LoadUint64(&r.totalLagNs)
	maxLag := atomic.LoadUint64(&r.maxLagNs)

	var avgLag uint64
	if proc > 0 {
		avgLag = totalLag / proc
	}

	return map[string]uint64{
		"ingested":  ing,
		"routed":    route,
		"dropped":   drop,
		"processed": proc,
		"avg_lag_ns": avgLag,
		"max_lag_ns": maxLag,
		"queue_len":  uint64(len(r.queue)),
	}
}

func (r *Router) Stop() {
	close(r.stop)
	r.wg.Wait()
}

func producer(r *Router, topic string, rate int, stop <-chan struct{}) {
	ticker := time.NewTicker(time.Second / time.Duration(rate))
	defer ticker.Stop()

	var id uint64
	for {
		select {
		case <-ticker.C:
			id++
			msg := Message{
				ID:       id,
				Topic:    topic,
				Payload:  []byte("example-payload"),
				CreatedAt: time.Now().UnixNano(),
			}
			r.Publish(msg)
		case <-stop:
			return
		}
	}
}

func consumer(sub *Subscriber, name string, done chan<- string) {
	for msg := range sub.Ch {
		_ = msg
		// process message here
	}
	done <- name
}

func main() {
	router := NewRouter(queueSize: 100000, workers: 8)

	// Subscribers
	subA := router.Subscribe("orders", 4096)
	subB := router.Subscribe("orders", 4096)
	subC := router.Subscribe("trades", 4096)

	done := make(chan string, 3)
	go consumer(subA, "A", done)
	go consumer(subB, "B", done)
	go consumer(subC, "C", done)

	stop := make(chan struct{})
	go producer(router, "orders", 200000, stop) // 200k msgs/sec example
	go producer(router, "trades", 100000, stop)

	// Metrics printer
	go func() {
		t := time.NewTicker(2 * time.Second)
		defer t.Stop()
		for range t.C {
			m := router.Metrics()
			log.Printf(
				"ingested=%d routed=%d processed=%d dropped=%d queue=%d avgLag=%dns maxLag=%dns",
				m["ingested"], m["routed"], m["processed"], m["dropped"], m["queue_len"], m["avg_lag_ns"], m["max_lag_ns"],
			)
		}
	}()

	time.Sleep(10 * time.Second)
	close(stop)

	router.Unsubscribe("orders", subA)
	router.Unsubscribe("orders", subB)
	router.Unsubscribe("trades", subC)

	router.Stop()
	close(done)
}
