#include <algorithm>

// -----------------------------
// Utility: fast timestamp
// -----------------------------
static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

// -----------------------------
// Message
// -----------------------------
struct Message {
    uint64_t id;
    uint64_t key;
    uint64_t created_ns;
    uint32_t payload_size;
    char payload[64]; // fixed-size to avoid allocations

    Message() : id(0), key(0), created_ns(0), payload_size(0) {
        std::memset(payload, 0, sizeof(payload));
    }
};

// -----------------------------
// SPSC Ring Buffer
//   Single Producer / Single Consumer
// -----------------------------
template <typename T, size_t CapacityPow2>
class SpscRing {
    static_assert((CapacityPow2 & (CapacityPow2 - 1)) == 0, "Capacity must be power of 2");

public:
    SpscRing() : head_(0), tail_(0) {}

    bool push(const T& item) {
        const size_t head = head_.load(std::memory_order_relaxed);
        const size_t next = (head + 1) & mask_;
        if (next == tail_.load(std::memory_order_acquire)) {
            return false; // full
        }
        buffer_[head] = item;
        head_.store(next, std::memory_order_release);
        return true;
    }

    bool pop(T& out) {
        const size_t tail = tail_.load(std::memory_order_relaxed);
        if (tail == head_.load(std::memory_order_acquire)) {
            return false; // empty
        }
        out = buffer_[tail];
        tail_.store((tail + 1) & mask_, std::memory_order_release);
        return true;
    }

    bool empty() const {
        return head_.load(std::memory_order_acquire) == tail_.load(std::memory_order_acquire);
    }

private:
    static constexpr size_t mask_ = CapacityPow2 - 1;
    std::array<T, CapacityPow2> buffer_;
    alignas(64) std::atomic<size_t> head_;
    alignas(64) std::atomic<size_t> tail_;
};

// -----------------------------
// Latency histogram
//   Simple log2 buckets in nanoseconds
// -----------------------------
class LatencyHistogram {
public:
    void record(uint64_t latency_ns) {
        size_t bucket = 0;
        if (latency_ns > 0) {
            bucket = 63 - __builtin_clzll(latency_ns);
        }
        bucket = std::min(bucket, buckets_.size() - 1);
        buckets_[bucket].fetch_add(1, std::memory_order_relaxed);
    }

    void print() const {
        std::cout << "\nLatency histogram (log2 buckets, ns):\n";
        for (size_t i = 0; i < buckets_.size(); ++i) {
            uint64_t count = buckets_[i].load(std::memory_order_relaxed);
            if (count == 0) continue;

            uint64_t low = (i == 0) ? 0 : (1ULL << i);
            uint64_t high = (1ULL << (i + 1)) - 1;

            std::cout << "[" << std::setw(10) << low
                      << " - " << std::setw(10) << high
                      << "] : " << count << "\n";
        }
    }

private:
    static constexpr size_t kBuckets = 64;
    std::array<std::atomic<uint64_t>, kBuckets> buckets_{};
};

// -----------------------------
// Shard worker
// -----------------------------
class ShardWorker {
public:
    static constexpr size_t kQueueSize = 1 << 16; // 65536

    ShardWorker() : running_(false), processed_(0) {}

    void start() {
        running_.store(true, std::memory_order_release);
        thread_ = std::thread([this] { run(); });
    }

    void stop() {
        running_.store(false, std::memory_order_release);
        if (thread_.joinable()) thread_.join();
    }

    bool enqueue(const Message& msg) {
        return queue_.push(msg);
    }

    uint64_t processed() const {
        return processed_.load(std::memory_order_relaxed);
    }

    LatencyHistogram& histogram() { return histogram_; }

private:
    void run() {
        Message msg;
        std::vector<Message> batch;
        batch.reserve(1024);

        while (running_.load(std::memory_order_acquire) || !queue_.empty()) {
            batch.clear();

            // Batch drain
            for (size_t i = 0; i < 1024; ++i) {
                if (!queue_.pop(msg)) break;
                batch.push_back(msg);
            }

            if (batch.empty()) {
                std::this_thread::yield();
                continue;
            }

            // Process batch
            const uint64_t now = now_ns();
            for (auto& m : batch) {
                // Simulated processing
                volatile uint64_t sink = m.id ^ m.key ^ m.payload_size;
                (void)sink;

                uint64_t latency = now - m.created_ns;
                histogram_.record(latency);
                processed_.fetch_add(1, std::memory_order_relaxed);
            }
        }
    }

    SpscRing<Message, kQueueSize> queue_;
    std::atomic<bool> running_;
    std::thread thread_;
    std::atomic<uint64_t> processed_;
    LatencyHistogram histogram_;
};

// -----------------------------
// Router
// -----------------------------
class Router {
public:
    explicit Router(size_t shards) : shards_(shards) {}

    void start() {
        for (auto& s : shards_) s.start();
    }

    void stop() {
        for (auto& s : shards_) s.stop();
    }

    bool route(const Message& msg) {
        size_t idx = shard_for(msg.key);
        return shards_[idx].enqueue(msg);
    }

    void print_stats() const {
        uint64_t total = 0;
        for (size_t i = 0; i < shards_.size(); ++i) {
            uint64_t p = shards_[i].processed();
            total += p;
            std::cout << "Shard " << i << " processed: " << p << "\n";
        }
        std::cout << "Total processed: " << total << "\n";
    }

    void print_latencies() const {
        for (size_t i = 0; i < shards_.size(); ++i) {
            std::cout << "\n=== Shard " << i << " ===\n";
            shards_[i].histogram().print();
        }
    }

private:
    size_t shard_for(uint64_t key) const {
        // simple fast hash; replace with better hash if needed
        key ^= key >> 33;
        key *= 0xff51afd7ed558ccdULL;
        key ^= key >> 33;
        key *= 0xc4ceb9fe1a85ec53ULL;
        key ^= key >> 33;
        return key % shards_.size();
    }

    std::vector<ShardWorker> shards_;
};

// -----------------------------
// Main benchmark / demo
// -----------------------------
int main() {
    constexpr size_t kShards = 8;
    constexpr size_t kMessages = 5'000'000;

    Router router(kShards);
    router.start();

    uint64_t start = now_ns();

    size_t dropped = 0;
    for (size_t i = 0; i < kMessages; ++i) {
        Message msg;
        msg.id = i;
        msg.key = i * 2654435761ULL;
        msg.created_ns = now_ns();
        msg.payload_size = 16;
        std::snprintf(msg.payload, sizeof(msg.payload), "msg-%zu", i);

        while (!router.route(msg)) {
            // Backpressure: in a real system you may drop, retry, or block.
            ++dropped;
            std::this_thread::yield();
        }
    }

    router.stop();

    uint64_t end = now_ns();
    double secs = (end - start) / 1e9;
    double throughput = kMessages / secs;

    std::cout << "Sent: " << kMessages << "\n";
    std::cout << "Dropped/retried: " << dropped << "\n";
    std::cout << "Elapsed: " << secs << " sec\n";
    std::cout << "Throughput: " << throughput << " msg/sec\n";

    router.print_stats();
    router.print_latencies();

    return 0;
}
