```go
package main

import (
	"fmt"
	"hash/fnv"
	"math"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Key       string
	Payload   []byte
	CreatedAt time.Time
}

type RouteFunc func(msg *Message) uint32
type HandlerFunc func(msg *Message)

type Metrics struct {
	Enqueued      uint64
	Routed        uint64
	Processed     uint64
	Dropped       uint64
	QueueFullDrop uint64

	// latency in nanoseconds
	LatencyCount uint64
	LatencySum   uint64
	LatencyMin   uint64
	LatencyMax   uint64
}

func NewMetrics() *Metrics {
	m := &Metrics{}
	atomic.StoreUint64(&m.LatencyMin, math.MaxUint64)
	return m
}

func (m *Metrics) RecordLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())

	atomic.AddUint64(&m.LatencyCount, 1)
	atomic.AddUint64(&m.LatencySum, ns)

	for {
		old := atomic.LoadUint64(&m.LatencyMin)
		if ns >= old {
			break
		}
		if atomic.CompareAndSwapUint64(&m.LatencyMin, old, ns) {
			break
		}
	}

	for {
		old := atomic.LoadUint64(&m.LatencyMax)
		if ns <= old {
			break
		}
		if atomic.CompareAndSwapUint64(&m.LatencyMax, old, ns) {
			break
		}
	}
}

func (m *Metrics) Snapshot() Metrics {
	return Metrics{
		Enqueued:      atomic.LoadUint64(&m.Enqueued),
		Routed:        atomic.LoadUint64(&m.Routed),
		Processed:     atomic.LoadUint64(&m.Processed),
		Dropped:       atomic.LoadUint64(&m.Dropped),
		QueueFullDrop: atomic.LoadUint64(&m.QueueFullDrop),
		LatencyCount:  atomic.LoadUint64(&m.LatencyCount),
		LatencySum:    atomic.LoadUint64(&m.LatencySum),
		LatencyMin:    atomic.LoadUint64(&m.LatencyMin),
		LatencyMax:    atomic.LoadUint64(&m.LatencyMax),
	}
}

type Router struct {
	shards  []chan *Message
	handlers []HandlerFunc
	metrics *Metrics
	route   RouteFunc
}

func NewRouter(numShards, queueSize int, route RouteFunc, handler HandlerFunc, metrics *Metrics) *Router {
	r := &Router{
		shards:   make([]chan *Message, numShards),
		handlers: make([]HandlerFunc, numShards),
		metrics:  metrics,
		route:    route,
	}
	for i := 0; i < numShards; i++ {
		r.shards[i] = make(chan *Message, queueSize)
		r.handlers[i] = handler
		go r.runShard(i)
	}
	return r
}

func (r *Router) runShard(i int) {
	q := r.shards[i]
	h := r.handlers[i]

	for msg := range q {
		h(msg)
		atomic.AddUint64(&r.metrics.Processed, 1)

		latency := time.Since(msg.CreatedAt)
		r.metrics.RecordLatency(latency)
	}
}

func (r *Router) Enqueue(msg *Message) bool {
	atomic.AddUint64(&r.metrics.Enqueued, 1)

	shard := r.route(msg) % uint32(len(r.shards))
	atomic.AddUint64(&r.metrics.Routed, 1)

	select {
	case r.shards[shard] <- msg:
		return true
	default:
		atomic.AddUint64(&r.metrics.Dropped, 1)
		atomic.AddUint64(&r.metrics.QueueFullDrop, 1)
		return false
	}
}

func HashRoute(msg *Message) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(msg.Key))
	return h.Sum32()
}

// Example handler simulates ultra-fast processing.
// Keep this function as lean as possible in real deployment.
func ProcessMessage(msg *Message) {
	// Do minimal work here.
	// In production: forward to network, disk, or downstream system.
	_ = len(msg.Payload)
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	metrics := NewMetrics()
	numShards := runtime.NumCPU() * 2
	queueSize := 64 * 1024

	router := NewRouter(numShards, queueSize, HashRoute, ProcessMessage, metrics)

	// Producer simulation
	stop := time.After(5 * time.Second)
	var id uint64

	go func() {
		ticker := time.NewTicker(1 * time.Millisecond)
		defer ticker.Stop()

		for {
			select {
			case <-ticker.C:
				// burst of messages
				for i := 0; i < 10000; i++ {
					n := atomic.AddUint64(&id, 1)
					msg := &Message{
						ID:        n,
						Key:       fmt.Sprintf("user-%d", n%1000),
						Payload:   []byte("hello-world"),
						CreatedAt: time.Now(),
					}
					router.Enqueue(msg)
				}
			}
		}
	}()

	// Metrics reporter
	go func() {
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()

		for range ticker.C {
			s := metrics.Snapshot()
			avg := time.Duration(0)
			if s.LatencyCount > 0 {
				avg = time.Duration(s.LatencySum / s.LatencyCount)
			}
			fmt.Printf(
				"enqueued=%d routed=%d processed=%d dropped=%d avg_latency=%s min=%s max=%s\n",
				s.Enqueued, s.Routed, s.Processed, s.Dropped,
				avg, time.Duration(s.LatencyMin), time.Duration(s.LatencyMax),
			)
		}
	}()

	<-stop
	fmt.Println("shutting down")
}
