import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.LockSupport;
import java.util.function.Consumer;

/**
 * High-frequency messaging system demo.
 * Focus:
 * - low allocation
 * - partitioned routing
 * - per-route latency tracking
 * - backpressure
 */
public class HighFrequencyMessagingSystem {

    // ===== Message =====
    public static final class Message {
        public final long id;
        public final int routeKey;
        public final long createdNanos;
        public final byte[] payload; // keep payload as-is; in production use pooled buffers / off-heap

        public Message(long id, int routeKey, byte[] payload) {
            this.id = id;
            this.routeKey = routeKey;
            this.createdNanos = System.nanoTime();
            this.payload = payload;
        }
    }

    // ===== Metrics =====
    public static final class Metrics {
        private final LongAdder totalReceived = new LongAdder();
        private final LongAdder totalRouted = new LongAdder();
        private final LongAdder totalProcessed = new LongAdder();
        private final LongAdder totalDropped = new LongAdder();
        private final LongAdder totalLatencyNanos = new LongAdder();
        private final AtomicLong maxLatencyNanos = new AtomicLong();

        public void incReceived() { totalReceived.increment(); }
        public void incRouted() { totalRouted.increment(); }
        public void incProcessed() { totalProcessed.increment(); }
        public void incDropped() { totalDropped.increment(); }

        public void recordLatency(long nanos) {
            totalLatencyNanos.add(nanos);
            maxLatencyNanos.accumulateAndGet(nanos, Math::max);
        }

        public String snapshot() {
            long processed = totalProcessed.sum();
            long avg = processed == 0 ? 0 : totalLatencyNanos.sum() / processed;
            return "Metrics{" +
                    "received=" + totalReceived.sum() +
                    ", routed=" + totalRouted.sum() +
                    ", processed=" + processed +
                    ", dropped=" + totalDropped.sum() +
                    ", avgLatencyMicros=" + (avg / 1_000.0) +
                    ", maxLatencyMicros=" + (maxLatencyNanos.get() / 1_000.0) +
                    '}';
        }
    }

    // ===== Latency monitor =====
    public static final class LatencyMonitor {
        private final Metrics metrics;

        public LatencyMonitor(Metrics metrics) {
            this.metrics = metrics;
        }

        public void record(Message msg) {
            long latency = System.nanoTime() - msg.createdNanos;
            metrics.recordLatency(latency);
        }
    }

    // ===== Fixed-size queue =====
    // MPSC-ish bounded queue for routing. Simple and fast enough for a starter design.
    public static final class RingBufferQueue<E> {
        private final AtomicReferenceArray<E> buffer;
        private final int mask;
        private final AtomicLong tail = new AtomicLong(0);
        private volatile long head = 0;

        public RingBufferQueue(int capacityPow2) {
            if (Integer.bitCount(capacityPow2) != 1) {
                throw new IllegalArgumentException("Capacity must be a power of 2");
            }
            this.buffer = new AtomicReferenceArray<>(capacityPow2);
            this.mask = capacityPow2 - 1;
        }

        public boolean offer(E e) {
            while (true) {
                long currentTail = tail.get();
                long currentHead = head;
                if (currentTail - currentHead >= buffer.length()) {
                    return false; // full
                }
                if (tail.compareAndSet(currentTail, currentTail + 1)) {
                    int idx = (int) currentTail & mask;
                    buffer.lazySet(idx, e);
                    return true;
                }
            }
        }

        public E poll() {
            long currentHead = head;
            int idx = (int) currentHead & mask;
            E e = buffer.get(idx);
            if (e == null) {
                return null;
            }
            buffer.lazySet(idx, null);
            head = currentHead + 1;
            return e;
        }

        public int size() {
            return (int) (tail.get() - head);
        }
    }

    // ===== Worker =====
    public static final class Worker implements Runnable {
        private final int id;
        private final RingBufferQueue<Message> queue;
        private final LatencyMonitor latencyMonitor;
        private final Metrics metrics;
        private final Consumer<Message> processor;
        private final AtomicBoolean running = new AtomicBoolean(true);

        public Worker(int id,
                      RingBufferQueue<Message> queue,
                      LatencyMonitor latencyMonitor,
                      Metrics metrics,
                      Consumer<Message> processor) {
            this.id = id;
            this.queue = queue;
            this.latencyMonitor = latencyMonitor;
            this.metrics = metrics;
            this.processor = processor;
        }

        public void shutdown() {
            running.set(false);
        }

        @Override
        public void run() {
            while (running.get() || queue.size() > 0) {
                Message msg = queue.poll();
                if (msg == null) {
                    // reduce CPU burn; tune based on latency goals
                    LockSupport.parkNanos(1_000);
                    continue;
                }

                try {
                    processor.accept(msg);
                } catch (Throwable t) {
                    // In production: log to async logger, dead-letter, circuit breaker, etc.
                } finally {
                    latencyMonitor.record(msg);
                    metrics.incProcessed();
                }
            }
        }

        @Override
        public String toString() {
            return "Worker-" + id;
        }
    }

    // ===== Router =====
    public static final class Router {
        private final RingBufferQueue<Message>[] partitions;
        private final Metrics metrics;

        @SuppressWarnings("unchecked")
        public Router(int partitionsCount, int queueCapacityPow2, Metrics metrics) {
            if (Integer.bitCount(partitionsCount) != 1) {
                throw new IllegalArgumentException("Partitions must be a power of 2 for fast masking");
            }
            this.metrics = metrics;
            this.partitions = new RingBufferQueue[partitionsCount];
            for (int i = 0; i < partitionsCount; i++) {
                partitions[i] = new RingBufferQueue<>(queueCapacityPow2);
            }
        }

        public boolean route(Message msg) {
            metrics.incReceived();
            int idx = spreadHash(msg.routeKey) & (partitions.length - 1);
            boolean ok = partitions[idx].offer(msg);
            if (ok) metrics.incRouted();
            else metrics.incDropped();
            return ok;
        }

        public RingBufferQueue<Message> queueFor(int partition) {
            return partitions[partition];
        }

        public int partitions() {
            return partitions.length;
        }

        // Better distribution for integer keys
        private static int spreadHash(int h) {
            h ^= (h >>> 16);
            h *= 0x7feb352d;
            h ^= (h >>> 15);
            h *= 0x846ca68b;
            h ^= (h >>> 16);
            return h;
        }
    }

    // ===== System =====
    public static final class MessagingSystem implements AutoCloseable {
        private final Metrics metrics = new Metrics();
        private final LatencyMonitor latencyMonitor = new LatencyMonitor(metrics);
        private final Router router;
        private final ExecutorService executor;
        private final Worker[] workers;

        public MessagingSystem(int workerCountPow2, int queueCapacityPow2, Consumer<Message> processor) {
            this.router = new Router(workerCountPow2, queueCapacityPow2, metrics);
            this.executor = Executors.newFixedThreadPool(workerCountPow2);
            this.workers = new Worker[workerCountPow2];

            for (int i = 0; i < workerCountPow2; i++) {
                workers[i] = new Worker(i, router.queueFor(i), latencyMonitor, metrics, processor);
                executor.submit(workers[i]);
            }
        }

        public boolean send(Message msg) {
            return router.route(msg);
        }

        public Metrics metrics() {
            return metrics;
        }

        public void close() {
            for (Worker w : workers) {
                w.shutdown();
            }
            executor.shutdown();
            try {
                executor.awaitTermination(10, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    // ===== Demo =====
    public static void main(String[] args) throws Exception {
        int workers = 8;            // power of 2
        int queueCapacity = 1 << 16; // power of 2

        Consumer<Message> processor = msg -> {
            // Simulate very fast processing; replace with real logic.
            // Avoid allocations here for HFT-style paths.
            if ((msg.id & 1023) == 0) {
                // occasional branch
            }
        };

        try (MessagingSystem system = new MessagingSystem(workers, queueCapacity, processor)) {
            // Producer threads
            int producerThreads = 4;
            ExecutorService producers = Executors.newFixedThreadPool(producerThreads);
            AtomicLong idGen = new AtomicLong();

            for (int p = 0; p < producerThreads; p++) {
                producers.submit(() -> {
                    ThreadLocalRandom rnd = ThreadLocalRandom.current();
                    while (!Thread.currentThread().isInterrupted()) {
