## Rust implementation

```rust
use crossbeam_queue::ArrayQueue;
use crossbeam_utils::CachePadded;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 16;
const QUEUE_CAPACITY: usize = 1 << 20; // ~1M per shard
const BATCH_SIZE: usize = 1024;

#[derive(Clone, Debug)]
struct Message {
    id: u64,
    topic: u32,
    created_ns: u64,
    payload: [u8; 32], // fixed payload for cache-friendly hot path
}

impl Message {
    fn new(id: u64, topic: u32) -> Self {
        Self {
            id,
            topic,
            created_ns: now_ns(),
            payload: [0u8; 32],
        }
    }
}

#[derive(Default)]
struct LatencyStats {
    count: AtomicU64,
    total_ns: AtomicU64,
    max_ns: AtomicU64,
}

impl LatencyStats {
    fn record(&self, latency_ns: u64) {
        self.count.fetch_add(1, Ordering::Relaxed);
        self.total_ns.fetch_add(latency_ns, Ordering::Relaxed);

        // simple max update
        let mut current = self.max_ns.load(Ordering::Relaxed);
        while latency_ns > current {
            match self.max_ns.compare_exchange_weak(
                current,
                latency_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(v) => current = v,
            }
        }
    }

    fn snapshot(&self) -> (u64, u64, u64) {
        let count = self.count.load(Ordering::Relaxed);
        let total = self.total_ns.load(Ordering::Relaxed);
        let max = self.max_ns.load(Ordering::Relaxed);
        (count, total, max)
    }
}

struct Shard {
    queue: Arc<ArrayQueue<Message>>,
    lag_stats: Arc<LatencyStats>,
}

impl Shard {
    fn new() -> Self {
        Self {
            queue: Arc::new(ArrayQueue::new(QUEUE_CAPACITY)),
            lag_stats: Arc::new(LatencyStats::default()),
        }
    }
}

struct Router {
    shards: Vec<Shard>,
    running: AtomicBool,
}

impl Router {
    fn new() -> Arc<Self> {
        let mut shards = Vec::with_capacity(NUM_SHARDS);
        for _ in 0..NUM_SHARDS {
            shards.push(Shard::new());
        }

        Arc::new(Self {
            shards,
            running: AtomicBool::new(true),
        })
    }

    #[inline]
    fn shard_for(&self, topic: u32) -> usize {
        (topic as usize) & (NUM_SHARDS - 1)
    }

    fn publish(&self, msg: Message) -> bool {
        let shard_idx = self.shard_for(msg.topic);
        self.shards[shard_idx].queue.push(msg).is_ok()
    }

    fn start_workers(self: &Arc<Self>) -> Vec<thread::JoinHandle<()>> {
        let mut handles = Vec::new();

        for shard_idx in 0..NUM_SHARDS {
            let router = Arc::clone(self);
            let queue = Arc::clone(&self.shards[shard_idx].queue);
            let stats = Arc::clone(&self.shards[shard_idx].lag_stats);

            let handle = thread::spawn(move || {
                let mut batch = Vec::with_capacity(BATCH_SIZE);

                while router.running.load(Ordering::Relaxed) {
                    batch.clear();

                    // Drain up to BATCH_SIZE messages
                    for _ in 0..BATCH_SIZE {
                        match queue.pop() {
                            Some(msg) => batch.push(msg),
                            None => break,
                        }
                    }

                    if batch.is_empty() {
                        thread::yield_now();
                        continue;
                    }

                    // Process batch
                    for msg in &batch {
                        let latency = now_ns().saturating_sub(msg.created_ns);
                        stats.record(latency);

                        // Simulated routing/dispatch work
                        route_message(msg);
                    }
                }

                // Drain remaining messages on shutdown
                while let Some(msg) = queue.pop() {
                    let latency = now_ns().saturating_sub(msg.created_ns);
                    stats.record(latency);
                    route_message(&msg);
                }
            });

            handles.push(handle);
        }

        handles
    }

    fn stop(&self) {
        self.running.store(false, Ordering::Relaxed);
    }

    fn print_metrics(&self) {
        let mut total_count = 0u64;
        let mut total_ns = 0u64;
        let mut max_ns = 0u64;

        for shard in &self.shards {
            let (count, sum, max) = shard.lag_stats.snapshot();
            total_count += count;
            total_ns += sum;
            max_ns = max_ns.max(max);
        }

        let avg_ns = if total_count > 0 {
            total_ns / total_count
        } else {
            0
        };

        println!(
            "messages={}, avg_latency_ns={}, max_latency_ns={}",
            total_count, avg_ns, max_ns
        );
    }
}

#[inline]
fn route_message(msg: &Message) {
    // Replace this with your real fan-out, matching, persistence, or downstream send.
    // Keep it extremely lightweight in the hot path.
    let _ = msg.id;
    let _ = msg.payload[0];
}

#[inline]
fn now_ns() -> u64 {
    Instant::now()
        .duration_since(Instant::now() - Duration::from_nanos(1))
        .as_nanos() as u64
}

fn main() {
    let router = Router::new();
    let workers = router.start_workers();

    // Producer threads
    let producer_router = Arc::clone(&router);
    let producer = thread::spawn(move || {
        let mut id = 0u64;

        loop {
            for i in 0..100_000 {
                let msg = Message::new(id, (i as u32) % 64);
                while !producer_router.publish(msg.clone()) {
                    // backpressure: queue full
                    thread::yield_now();
                }
                id += 1;
            }

            thread::sleep(Duration::from_millis(1));
            if id > 5_000_000 {
                break;
            }
        }
    });

    // Metrics thread
    let metrics_router = Arc::clone(&router);
    let metrics = thread::spawn(move || {
        for _ in 0..10 {
            thread::sleep(Duration::from_secs(1));
            metrics_router.print_metrics();
        }
    });

    producer.join().unwrap();
    metrics.join().unwrap();

    router.stop();

    for h in workers {
        h.join().unwrap();
    }

    router.print_metrics();
}
