## Go code

### `main.go`

```go
package main

import (
	"context"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

type Message struct {
	ID         uint64
	RoutingKey  uint64
	Payload     []byte
	IngressTS   int64 // unix nanos
	EnqueueTS   int64
	DispatchTS  int64
	EgressTS    int64
}

type Router struct {
	shards      []*Shard
	shardMask   uint64
	metrics     *Metrics
	randPool    sync.Pool
}

type Shard struct {
	id         int
	in         chan *Message
	stop       chan struct{}
	wg         sync.WaitGroup
	metrics    *Metrics
	downstream func(*Message) error
}

type Metrics struct {
	totalIn        uint64
	totalOut       uint64
	totalDropped   uint64
	totalErrors    uint64

	// latency in nanoseconds
	sumLatencyNS   uint64
	maxLatencyNS   uint64

	// Simple buckets for latency histogram.
	// Buckets: <10us, <50us, <100us, <250us, <500us, <1ms, <5ms, <10ms, >=10ms
	buckets [9]uint64
}

func NewMetrics() *Metrics {
	return &Metrics{}
}

func (m *Metrics) IncIn() { atomic.AddUint64(&m.totalIn, 1) }
func (m *Metrics) IncOut() { atomic.AddUint64(&m.totalOut, 1) }
func (m *Metrics) IncDropped() { atomic.AddUint64(&m.totalDropped, 1) }
func (m *Metrics) IncErrors() { atomic.AddUint64(&m.totalErrors, 1) }

func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.sumLatencyNS, ns)

	for {
		old := atomic.LoadUint64(&m.maxLatencyNS)
		if ns <= old || atomic.CompareAndSwapUint64(&m.maxLatencyNS, old, ns) {
			break
		}
	}

	switch {
	case ns < 10_000:
		atomic.AddUint64(&m.buckets[0], 1)
	case ns < 50_000:
		atomic.AddUint64(&m.buckets[1], 1)
	case ns < 100_000:
		atomic.AddUint64(&m.buckets[2], 1)
	case ns < 250_000:
		atomic.AddUint64(&m.buckets[3], 1)
	case ns < 500_000:
		atomic.AddUint64(&m.buckets[4], 1)
	case ns < 1_000_000:
		atomic.AddUint64(&m.buckets[5], 1)
	case ns < 5_000_000:
		atomic.AddUint64(&m.buckets[6], 1)
	case ns < 10_000_000:
		atomic.AddUint64(&m.buckets[7], 1)
	default:
		atomic.AddUint64(&m.buckets[8], 1)
	}
}

func NewRouter(numShards int, queueSize int, downstream func(*Message) error, metrics *Metrics) *Router {
	// numShards should be a power of 2 for masking
	shards := make([]*Shard, numShards)
	for i := 0; i < numShards; i++ {
		shards[i] = &Shard{
			id:         i,
			in:         make(chan *Message, queueSize),
			stop:       make(chan struct{}),
			metrics:    metrics,
			downstream: downstream,
		}
	}
	return &Router{
		shards:    shards,
		shardMask: uint64(numShards - 1),
		metrics:   metrics,
		randPool: sync.Pool{
			New: func() any {
				return rand.New(rand.NewSource(time.Now().UnixNano()))
			},
		},
	}
}

func (r *Router) Start(ctx context.Context) {
	for _, s := range r.shards {
		s.wg.Add(1)
		go s.run(ctx)
	}
}

func (r *Router) Stop() {
	for _, s := range r.shards {
		close(s.stop)
	}
	for _, s := range r.shards {
		s.wg.Wait()
	}
}

func (r *Router) Route(msg *Message) bool {
	msg.EnqueueTS = time.Now().UnixNano()
	shardID := int(msg.RoutingKey & r.shardMask)
	select {
	case r.shards[shardID].in <- msg:
		return true
	default:
		// backpressure: queue full
		r.metrics.IncDropped()
		return false
	}
}

func (s *Shard) run(ctx context.Context) {
	defer s.wg.Done()

	// batching loop
	batch := make([]*Message, 0, 256)
	flushTimer := time.NewTimer(100 * time.Microsecond)
	defer flushTimer.Stop()

	flush := func() {
		if len(batch) == 0 {
			return
		}
		for _, msg := range batch {
			msg.DispatchTS = time.Now().UnixNano()
			err := s.downstream(msg)
			msg.EgressTS = time.Now().UnixNano()

			if err != nil {
				s.metrics.IncErrors()
				continue
			}
			s.metrics.IncOut()
			if msg.IngressTS != 0 {
				s.metrics.ObserveLatency(time.Duration(msg.EgressTS - msg.IngressTS))
			}
		}
		batch = batch[:0]
	}

	for {
		select {
		case <-ctx.Done():
			flush()
			return
		case <-s.stop:
			flush()
			return
		case msg := <-s.in:
			if msg == nil {
				continue
			}
			batch = append(batch, msg)
			if len(batch) >= cap(batch) {
				flush()
				if !flushTimer.Stop() {
					select {
					case <-flushTimer.C:
					default:
					}
				}
				flushTimer.Reset(100 * time.Microsecond)
			}
		case <-flushTimer.C:
			flush()
			flushTimer.Reset(100 * time.Microsecond)
		}
	}
}

func (m *Metrics) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	totalIn := atomic.LoadUint64(&m.totalIn)
	totalOut := atomic.LoadUint64(&m.totalOut)
	totalDropped := atomic.LoadUint64(&m.totalDropped)
	totalErrors := atomic.LoadUint64(&m.totalErrors)
	sumLatency := atomic.LoadUint64(&m.sumLatencyNS)
	maxLatency := atomic.LoadUint64(&m.maxLatencyNS)

	avgLatency := uint64(0)
	if totalOut > 0 {
		avgLatency = sumLatency / totalOut
	}

	w.Header().Set("Content-Type", "text/plain; version=0.0.4")
	fmt.Fprintf(w, "messages_in %d\n", totalIn)
	fmt.Fprintf(w, "messages_out %d\n", totalOut)
	fmt.Fprintf(w, "messages_dropped %d\n", totalDropped)
	fmt.Fprintf(w, "messages_errors %d\n", totalErrors)
	fmt.Fprintf(w, "latency_avg_ns %d\n", avgLatency)
	fmt.Fprintf(w, "latency_max_ns %d\n", maxLatency)

	bucketNames := []string{
		"lt_10us", "lt_50us", "lt_100us", "lt_250us", "lt_500us",
		"lt_1ms", "lt_5ms", "lt_10ms", "gte_10ms",
	}
	for i, name := range bucketNames {
		fmt.Fprintf(w, "latency_bucket_%s %d\n", name, atomic.LoadUint64(&m.buckets[i]))
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	metrics := NewMetrics()

	// Simulated downstream sink: replace with real broker, socket writer, matching engine, etc.
	downstream := func(msg *Message) error {
		// Simulate very fast work
