		}
	}()

	// Simulated producer at high rate
	go func() {
		var id uint64
		ticker := time.NewTicker(1 * time.Microsecond)
		defer ticker.Stop()

		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				msg := &Message{
					ID:        atomic.AddUint64(&id, 1),
					RoutingKey: uint64(rand.Int()),
					Payload:   []byte("hello"),
					IngressTS: time.Now().UnixNano(),
				}
				metrics.IncIn()
				router.Route(msg)
			}
		}
	}()

	// Graceful shutdown on SIGINT/SIGTERM
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh

	log.Println("shutting down...")
	cancel()
	router.Stop()
}
```

