## Go code

```go
package main

import (
	"fmt"
	"hash/fnv"
	"log"
	"math"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	RouteKey  string
	Payload   []byte
	CreatedAt time.Time
}

type Handler func(msg Message)

type Metrics struct {
	totalReceived uint64
	totalDropped   uint64
	totalHandled   uint64

	// Approx latency buckets in microseconds:
	// [<10, <50, <100, <250, <500, <1000, <2500, <5000, <10000, >=10000]
	latencyBuckets [10]uint64

	// Per-route counts
	mu        sync.RWMutex
	routeHits  map[string]uint64
	routeError map[string]uint64
}

func NewMetrics() *Metrics {
	return &Metrics{
		routeHits:  make(map[string]uint64),
		routeError: make(map[string]uint64),
	}
}

func (m *Metrics) IncReceived() { atomic.AddUint64(&m.totalReceived, 1) }
func (m *Metrics) IncDropped()   { atomic.AddUint64(&m.totalDropped, 1) }
func (m *Metrics) IncHandled()   { atomic.AddUint64(&m.totalHandled, 1) }

func (m *Metrics) AddLatency(d time.Duration) {
	us := float64(d.Microseconds())
	var idx int
	switch {
	case us < 10:
		idx = 0
	case us < 50:
		idx = 1
	case us < 100:
		idx = 2
	case us < 250:
		idx = 3
	case us < 500:
		idx = 4
	case us < 1000:
		idx = 5
	case us < 2500:
		idx = 6
	case us < 5000:
		idx = 7
	case us < 10000:
		idx = 8
	default:
		idx = 9
	}
	atomic.AddUint64(&m.latencyBuckets[idx], 1)
}

func (m *Metrics) IncRouteHit(route string) {
	m.mu.Lock()
	m.routeHits[route]++
	m.mu.Unlock()
}

func (m *Metrics) Snapshot() (received, dropped, handled uint64, buckets [10]uint64, routeHits map[string]uint64) {
	received = atomic.LoadUint64(&m.totalReceived)
	dropped = atomic.LoadUint64(&m.totalDropped)
	handled = atomic.LoadUint64(&m.totalHandled)
	for i := range buckets {
		buckets[i] = atomic.LoadUint64(&m.latencyBuckets[i])
	}
	m.mu.RLock()
	routeHits = make(map[string]uint64, len(m.routeHits))
	for k, v := range m.routeHits {
		routeHits[k] = v
	}
	m.mu.RUnlock()
	return
}

type Shard struct {
	id      int
	ch      chan Message
	handler Handler
	metrics *Metrics
	stop    chan struct{}
	wg      sync.WaitGroup
}

func NewShard(id int, buffer int, handler Handler, metrics *Metrics) *Shard {
	return &Shard{
		id:      id,
		ch:      make(chan Message, buffer),
		handler: handler,
		metrics: metrics,
		stop:    make(chan struct{}),
	}
}

func (s *Shard) Start() {
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()
		for {
			select {
			case msg := <-s.ch:
				start := time.Now()
				s.handler(msg)
				s.metrics.IncHandled()
				s.metrics.IncRouteHit(msg.RouteKey)
				s.metrics.AddLatency(time.Since(start))
			case <-s.stop:
				return
			}
		}
	}()
}

func (s *Shard) TryPush(msg Message) bool {
	select {
	case s.ch <- msg:
		return true
	default:
		return false
	}
}

func (s *Shard) Stop() {
	close(s.stop)
	s.wg.Wait()
}

type Router struct {
	shards  []*Shard
	metrics *Metrics
	n       uint32
}

func NewRouter(numShards int, shardBuffer int, handler Handler, metrics *Metrics) *Router {
	r := &Router{
		shards:  make([]*Shard, numShards),
		metrics: metrics,
		n:       uint32(numShards),
	}
	for i := 0; i < numShards; i++ {
		s := NewShard(i, shardBuffer, handler, metrics)
		s.Start()
		r.shards[i] = s
	}
	return r
}

func (r *Router) shardForKey(key string) *Shard {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	idx := h.Sum32() % r.n
	return r.shards[idx]
}

func (r *Router) Submit(msg Message) bool {
	r.metrics.IncReceived()
	shard := r.shardForKey(msg.RouteKey)
	if ok := shard.TryPush(msg); !ok {
		r.metrics.IncDropped()
		return false
	}
	return true
}

func (r *Router) Stop() {
	for _, s := range r.shards {
		s.Stop()
	}
}

func percentileFromBuckets(b [10]uint64, p float64) string {
	total := uint64(0)
	for _, v := range b {
		total += v
	}
	if total == 0 {
		return "n/a"
	}

	target := uint64(math.Ceil(float64(total) * p))
	if target == 0 {
		target = 1
	}

	labels := []string{
		"<10us", "<50us", "<100us", "<250us", "<500us",
		"<1ms", "<2.5ms", "<5ms", "<10ms", ">=10ms",
	}

	var cum uint64
	for i, v := range b {
		cum += v
		if cum >= target {
			return labels[i]
		}
	}
	return ">=10ms"
}

func monitor(metrics *Metrics, interval time.Duration, stop <-chan struct{}) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	var lastReceived uint64
	var lastHandled uint64
	var lastDropped uint64
	last := time.Now()

	for {
		select {
		case <-ticker.C:
			now := time.Now()
			sec := now.Sub(last).Seconds()
			received, dropped, handled, buckets, routeHits := metrics.Snapshot()

			inRate := float64(received-lastReceived) / sec
			outRate := float64(handled-lastHandled) / sec
			dropRate := float64(dropped-lastDropped) / sec

			fmt.Printf("\n--- Metrics ---\n")
			fmt.Printf("Ingress: %.0f msg/s, Egress: %.0f msg/s, Dropped: %.0f msg/s\n", inRate, outRate, dropRate)
			fmt.Printf("Total Received: %d, Handled: %d, Dropped: %d\n", received, handled, dropped)
			fmt.Printf("Latency p50: %s, p95: %s, p99: %s\n",
				percentileFromBuckets(buckets, 0.50),
				percentileFromBuckets(buckets, 0.95),
				percentileFromBuckets(buckets, 0.99),
			)

			fmt.Printf("Top routes:\n")
			for route, count := range routeHits {
				fmt.Printf("  %s => %d\n", route, count)
			}

			lastReceived = received
			lastHandled = handled
			lastDropped = dropped
			last = now

		case <-stop:
			return
		}
	}
}

func fastHandler(msg Message) {
	// Simulate very small processing cost.
	// In real systems, keep handler allocation-free and avoid logging here.
	_ = msg.Payload
}

func main() {
	metrics := NewMetrics()
	router := NewRouter(
		64,     // shards
		8192,   // per-shard buffer
		fastHandler,
		metrics,
	)

	stopMon := make(chan struct{})
	go monitor(metrics, 2*time.Second, stopMon)

	// Simulate burst traffic
	const total = 1_000_000
	routes := []string{"A", "B", "C", "D", "E", "F"}

	start := time.Now()
	for i := 0; i < total; i++ {
		msg := Message{
			ID:        uint64(i),
			RouteKey:  routes[i%len(routes)],
			Payload:   []byte("hello"),
			CreatedAt: time.Now(),
		}
		_ = router.Submit(msg)
	}
	elapsed := time.Since(start)

	log.Printf("Submitted %d messages in %s (%.0f msg/s)",
		total, elapsed, float64(total)/elapsed.Seconds())

	time.Sleep(5 * time.Second)
	close(stopMon)
	router.Stop()
}
