## Implementation

### `main.go`

```go
package main

import (
	"context"
	"fmt"
	"log"
	"math"
	"net/http"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a routed message.
// Keep it small and immutable for better performance.
type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt time.Time
}

// Handler receives messages.
type Handler func(msg Message)

// Router routes messages to topic subscribers.
type Router struct {
	mu    sync.RWMutex
	subs  map[string][]Handler
	total uint64
}

func NewRouter() *Router {
	return &Router{
		subs: make(map[string][]Handler),
	}
}

func (r *Router) Subscribe(topic string, h Handler) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.subs[topic] = append(r.subs[topic], h)
}

func (r *Router) Route(msg Message) {
	r.mu.RLock()
	handlers := r.subs[msg.Topic]
	r.mu.RUnlock()

	atomic.AddUint64(&r.total, 1)

	// Fan-out to all handlers for the topic.
	// In a production system, consider async delivery or lock-free snapshots.
	for _, h := range handlers {
		h(msg)
	}
}

func (r *Router) TotalRouted() uint64 {
	return atomic.LoadUint64(&r.total)
}

// LatencyMonitor tracks message latency and computes summaries.
type LatencyMonitor struct {
	mu      sync.Mutex
	samples []float64 // store microseconds
	count   uint64
	sum     float64
	min     float64
	max     float64
}

func NewLatencyMonitor() *LatencyMonitor {
	return &LatencyMonitor{
		min: math.MaxFloat64,
	}
}

func (lm *LatencyMonitor) Observe(d time.Duration) {
	us := float64(d.Microseconds())

	lm.mu.Lock()
	defer lm.mu.Unlock()

	lm.samples = append(lm.samples, us)
	lm.count++
	lm.sum += us
	if us < lm.min {
		lm.min = us
	}
	if us > lm.max {
		lm.max = us
	}
}

func (lm *LatencyMonitor) Snapshot() map[string]float64 {
	lm.mu.Lock()
	defer lm.mu.Unlock()

	samples := make([]float64, len(lm.samples))
	copy(samples, lm.samples)
	sort.Float64s(samples)

	p50 := percentile(samples, 50)
	p90 := percentile(samples, 90)
	p99 := percentile(samples, 99)

	avg := 0.0
	if lm.count > 0 {
		avg = lm.sum / float64(lm.count)
	}

	return map[string]float64{
		"count": float64(lm.count),
		"min_us": lm.min,
		"max_us": lm.max,
		"avg_us": avg,
		"p50_us": p50,
		"p90_us": p90,
		"p99_us": p99,
	}
}

func percentile(sorted []float64, p float64) float64 {
	if len(sorted) == 0 {
		return 0
	}
	if p <= 0 {
		return sorted[0]
	}
	if p >= 100 {
		return sorted[len(sorted)-1]
	}

	rank := (p / 100.0) * float64(len(sorted)-1)
	l := int(math.Floor(rank))
	u := int(math.Ceil(rank))
	if l == u {
		return sorted[l]
	}
	frac := rank - float64(l)
	return sorted[l]*(1-frac) + sorted[u]*frac
}

// Metrics collects routing and processing stats.
type Metrics struct {
	routed   uint64
	processed uint64
	dropped  uint64
}

func (m *Metrics) IncRouted()   { atomic.AddUint64(&m.routed, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.processed, 1) }
func (m *Metrics) IncDropped()  { atomic.AddUint64(&m.dropped, 1) }

func (m *Metrics) Snapshot() map[string]uint64 {
	return map[string]uint64{
		"routed":    atomic.LoadUint64(&m.routed),
		"processed": atomic.LoadUint64(&m.processed),
		"dropped":   atomic.LoadUint64(&m.dropped),
	}
}

// Broker ties ingestion, routing, and observability together.
type Broker struct {
	router   *Router
	latency  *LatencyMonitor
	metrics  *Metrics
	in       chan Message
	wg       sync.WaitGroup
	ctx      context.Context
	cancel   context.CancelFunc
}

func NewBroker(buffer int) *Broker {
	ctx, cancel := context.WithCancel(context.Background())
	return &Broker{
		router:  NewRouter(),
		latency: NewLatencyMonitor(),
		metrics: &Metrics{},
		in:      make(chan Message, buffer),
		ctx:     ctx,
		cancel:  cancel,
	}
}

func (b *Broker) Subscribe(topic string, h Handler) {
	b.router.Subscribe(topic, h)
}

func (b *Broker) Start(workers int) {
	for i := 0; i < workers; i++ {
		b.wg.Add(1)
		go func(id int) {
			defer b.wg.Done()
			for {
				select {
				case <-b.ctx.Done():
					return
				case msg := <-b.in:
					start := time.Now()
					b.router.Route(msg)
					b.latency.Observe(time.Since(start))
					b.metrics.IncProcessed()
				}
			}
		}(i)
	}
}

func (b *Broker) Publish(msg Message) bool {
	select {
	case b.in <- msg:
		b.metrics.IncRouted()
		return true
	default:
		b.metrics.IncDropped()
		return false
	}
}

func (b *Broker) Stop() {
	b.cancel()
	b.wg.Wait()
}

func (b *Broker) Metrics() map[string]uint64 {
	return b.metrics.Snapshot()
}

func (b *Broker) Latency() map[string]float64 {
	return b.latency.Snapshot()
}

func main() {
	broker := NewBroker(1_000_000)
	defer broker.Stop()

	// Sample subscriptions
	broker.Subscribe("orders", func(msg Message) {
		// Simulate lightweight processing
		_ = len(msg.Payload)
	})

	broker.Subscribe("orders", func(msg Message) {
		// Another consumer
		_ = strings.ToUpper(string(msg.Payload))
	})

	broker.Subscribe("trades", func(msg Message) {
		_ = msg.Topic
	})

	workerCount := 8
	broker.Start(workerCount)

	// Metrics server
	http.HandleFunc("/metrics", func(w http.ResponseWriter, r *http.Request) {
		m := broker.Metrics()
		l := broker.Latency()

		fmt.Fprintf(w, "routed %d\nprocessed %d\ndropped %d\n",
			m["routed"], m["processed"], m["dropped"])

		fmt.Fprintf(w, "latency_count %.0f\nmin_us %.2f\nmax_us %.2f\navg_us %.2f\np50_us %.2f\np90_us %.2f\np99_us %.2f\n",
			l["count"], l["min_us"], l["max_us"], l["avg_us"], l["p50_us"], l["p90_us"], l["p99_us"])
	})

	go func() {
		log.Println("metrics listening on :8080")
		log.Println(http.ListenAndServe(":8080", nil))
	}()

	// Simulated load
	for i := 0; i < 1_000_000; i++ {
		msg := Message{
			Topic:     "orders",
			Payload:   []byte("hello"),
			CreatedAt: time.Now(),
		}
		ok := broker.Publish(msg)
		if !ok {
			// Backpressure / overload path
		}
	}

	// Allow drain
	time.Sleep(2 * time.Second)

	fmt.Println("Final metrics:", broker.Metrics())
	fmt.Println("Latency summary:", broker.Latency())
}
