}

type LatencyMonitor struct {
	count      atomic.Uint64
	totalNanos atomic.Uint64
	maxNanos   atomic.Uint64
	minNanos   atomic.Uint64
	drops      atomic.Uint64
}

func NewLatencyMonitor() *LatencyMonitor {
	m := &LatencyMonitor{}
	m.minNanos.Store(^uint64(0))
	return m
}

func (m *LatencyMonitor) Record(start int64) {
	latency := uint64(time.Now().UnixNano() - start)
	m.count.Add(1)
	m.totalNanos.Add(latency)

	for {
		old := m.maxNanos.Load()
		if latency <= old {
			break
		}
		if m.maxNanos.CompareAndSwap(old, latency) {
			break
		}
	}

	for {
		old := m.minNanos.Load()
		if latency >= old {
			break
		}
		if m.minNanos.CompareAndSwap(old, latency) {
			break
		}
	}
}

func (m *LatencyMonitor) RecordDrop() {
	m.drops.Add(1)
}

func (m *LatencyMonitor) Snapshot() LatencyStats {
	count := m.count.Load()
	total := m.totalNanos.Load()
	max := m.maxNanos.Load()
	min := m.minNanos.Load()
	if min == ^uint64(0) {
		min = 0
	}
	return LatencyStats{
		Count:      count,
		TotalNanos: total,
		MaxNanos:   max,
		MinNanos:   min,
		DropCount:  m.drops.Load(),
	}
}

type Shard struct {
	id          int
	subscribers map[string][]*Subscriber
	mu          sync.RWMutex
	inbox       chan Message
	monitor     *LatencyMonitor
	wg          sync.WaitGroup
}

func NewShard(id int, inboxSize int, monitor *LatencyMonitor) *Shard {
	s := &Shard{
		id:          id,
		subscribers: make(map[string][]*Subscriber),
		inbox:       make(chan Message, inboxSize),
		monitor:     monitor,
	}
	go s.run()
	return s
}

func (s *Shard) run() {
	for msg := range s.inbox {
		s.mu.RLock()
		subs := s.subscribers[msg.Topic]
		s.mu.RUnlock()

		for _, sub := range subs {
			select {
			case sub.Ch <- msg:
			default:
				// subscriber is slow, drop message
				s.monitor.RecordDrop()
			}
		}
		s.monitor.Record(msg.CreatedAt)
	}
}

func (s *Shard) Subscribe(topic string, sub *Subscriber) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.subscribers[topic] = append(s.subscribers[topic], sub)
}

func (s *Shard) Publish(msg Message) bool {
	select {
	case s.inbox <- msg:
		return true
	default:
		s.monitor.RecordDrop()
		return false
	}
}

type Broker struct {
	shards  []*Shard
	mask    uint64
	monitor *LatencyMonitor
	seq     atomic.Uint64
}

func NewBroker(numShards int, inboxSize int) *Broker {
	monitor := NewLatencyMonitor()
	shards := make([]*Shard, numShards)
	for i := 0; i < numShards; i++ {
		shards[i] = NewShard(i, inboxSize, monitor)
	}
	return &Broker{
		shards:  shards,
		mask:    uint64(numShards - 1),
		monitor: monitor,
	}
}

func (b *Broker) shardFor(topic string) *Shard {
	h := fnv.New64a()
	_, _ = h.Write([]byte(topic))
	idx := h.Sum64() & b.mask
	return b.shards[idx]
}

func (b *Broker) Subscribe(topic string, buffer int) *Subscriber {
	sub := &Subscriber{
		ID:   b.seq.Add(1),
		Ch:   make(chan Message, buffer),
		done: make(chan struct{}),
	}
	b.shardFor(topic).Subscribe(topic, sub)
	return sub
}

func (b *Broker) Publish(topic string, payload []byte) bool {
	msg := Message{
		ID:        b.seq.Add(1),
		Topic:     topic,
		CreatedAt: time.Now().UnixNano(),
		Payload:   payload,
	}
	return b.shardFor(topic).Publish(msg)
}

func (b *Broker) Stats() LatencyStats {
	return b.monitor.Snapshot()
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	broker := NewBroker(16, 65536)

	// Example subscribers
	sub1 := broker.Subscribe("orders", 1024)
	sub2 := broker.Subscribe("orders", 1024)

	go func() {
		for msg := range sub1.Ch {
			_ = msg
			// process message
		}
	}()

	go func() {
		for msg := range sub2.Ch {
			_ = msg
			// process message
		}
	}()

	// Simulate high-rate publishing
	payload := []byte("hello")
	for i := 0; i < 1_000_000; i++ {
		ok := broker.Publish("orders", payload)
		if !ok {
			// dropped due to backpressure
		}
	}

	time.Sleep(2 * time.Second)

	stats := broker.Stats()
	avg := float64(stats.TotalNanos) / float64(stats.Count)
	fmt.Printf("messages=%d drops=%d avg_latency_ns=%.2f max_ns=%d min_ns=%d\n",
		stats.Count, stats.DropCount, avg, stats.MaxNanos, stats.MinNanos)
}
