```go
package main

import (
	"context"
	"fmt"
	"log"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a high-frequency event.
type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt time.Time
}

// Metrics holds atomic counters and latency stats.
type Metrics struct {
	Published      atomic.Uint64
	Routed         atomic.Uint64
	Delivered      atomic.Uint64
	Dropped        atomic.Uint64
	Subscribers    atomic.Uint64
	RouteLatencyNs  atomic.Uint64
	DeliverLatencyNs atomic.Uint64
}

// LatencySnapshot is a simple reporting structure.
type LatencySnapshot struct {
	Published       uint64
	Routed          uint64
	Delivered       uint64
	Dropped         uint64
	Subscribers     uint64
	AvgRouteLatency  time.Duration
	AvgDeliverLatency time.Duration
}

// Router handles topic-based dispatch.
type Router struct {
	mu          sync.RWMutex
	subscribers map[string]map[chan Message]struct{}
	inbox       chan Message
	metrics     *Metrics
	stopCh      chan struct{}
	wg          sync.WaitGroup
	bufferSize  int
}

// NewRouter initializes the message router.
func NewRouter(bufferSize int, metrics *Metrics) *Router {
	return &Router{
		subscribers: make(map[string]map[chan Message]struct{}),
		inbox:       make(chan Message, bufferSize),
		metrics:     metrics,
		stopCh:      make(chan struct{}),
		bufferSize:  bufferSize,
	}
}

// Start launches the routing loop.
func (r *Router) Start() {
	r.wg.Add(1)
	go func() {
		defer r.wg.Done()
		for {
			select {
			case msg := <-r.inbox:
				start := time.Now()
				r.route(msg)
				r.metrics.Routed.Add(1)
				routeLatency := time.Since(start).Nanoseconds()
				r.metrics.RouteLatencyNs.Add(uint64(routeLatency))
			case <-r.stopCh:
				return
			}
		}
	}()
}

// Stop gracefully stops the router.
func (r *Router) Stop() {
	close(r.stopCh)
	r.wg.Wait()
}

// Publish attempts to enqueue a message.
// If the inbox is full, the message is dropped.
func (r *Router) Publish(msg Message) bool {
	msg.CreatedAt = time.Now()
	r.metrics.Published.Add(1)

	select {
	case r.inbox <- msg:
		return true
	default:
		r.metrics.Dropped.Add(1)
		return false
	}
}

// Subscribe registers a subscriber for a topic.
func (r *Router) Subscribe(topic string) <-chan Message {
	ch := make(chan Message, 1024)

	r.mu.Lock()
	defer r.mu.Unlock()

	if _, ok := r.subscribers[topic]; !ok {
		r.subscribers[topic] = make(map[chan Message]struct{})
	}
	r.subscribers[topic][ch] = struct{}{}
	r.metrics.Subscribers.Add(1)

	return ch
}

// Unsubscribe removes a subscriber.
func (r *Router) Unsubscribe(topic string, ch <-chan Message) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if subs, ok := r.subscribers[topic]; ok {
		// Convert receive-only channel to matching key using type assertion workaround is not possible directly.
		// So this method is provided as a placeholder design point.
		_ = subs
	}
}

// route sends a message to all subscribers for a topic.
func (r *Router) route(msg Message) {
	r.mu.RLock()
	subs := r.subscribers[msg.Topic]
	r.mu.RUnlock()

	for ch := range subs {
		select {
		case ch <- msg:
			deliverLatency := time.Since(msg.CreatedAt).Nanoseconds()
			r.metrics.Delivered.Add(1)
			r.metrics.DeliverLatencyNs.Add(uint64(deliverLatency))
		default:
			// subscriber is slow, drop to prevent global slowdown
			r.metrics.Dropped.Add(1)
		}
	}
}

// Snapshot returns a metrics snapshot.
func (m *Metrics) Snapshot() LatencySnapshot {
	published := m.Published.Load()
	routed := m.Routed.Load()
	delivered := m.Delivered.Load()
	dropped := m.Dropped.Load()
	subscribers := m.Subscribers.Load()

	var avgRoute, avgDeliver time.Duration
	if routed > 0 {
		avgRoute = time.Duration(m.RouteLatencyNs.Load() / routed)
	}
	if delivered > 0 {
		avgDeliver = time.Duration(m.DeliverLatencyNs.Load() / delivered)
	}

	return LatencySnapshot{
		Published:        published,
		Routed:           routed,
		Delivered:        delivered,
		Dropped:          dropped,
		Subscribers:      subscribers,
		AvgRouteLatency:  avgRoute,
		AvgDeliverLatency: avgDeliver,
	}
}

func main() {
	metrics := &Metrics{}
	router := NewRouter(100000, metrics)
	router.Start()
	defer router.Stop()

	// Example subscribers
	subA := router.Subscribe("orders")
	subB := router.Subscribe("orders")
	subC := router.Subscribe("payments")

	// Consumer goroutines
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	consume := func(name string, ch <-chan Message) {
		go func() {
			for {
				select {
				case msg := <-ch:
					_ = msg
					// Process message here
				case <-ctx.Done():
					return
				}
			}
		}()
	}

	consume("A", subA)
	consume("B", subB)
	consume("C", subC)

	// Simulate high-frequency publishing
	go func() {
		ticker := time.NewTicker(1 * time.Microsecond)
		defer ticker.Stop()

		for i := 0; i < 1000000; i++ {
			msg := Message{
				Topic:   "orders",
				Payload: []byte(fmt.Sprintf("order-%d", i)),
			}
			router.Publish(msg)
			<-ticker.C
		}
	}()

	// Periodic metrics reporting
	reportTicker := time.NewTicker(2 * time.Second)
	defer reportTicker.Stop()

	timeout := time.After(10 * time.Second)
	for {
		select {
		case <-reportTicker.C:
			s := metrics.Snapshot()
			log.Printf(
				"published=%d routed=%d delivered=%d dropped=%d subs=%d avg_route=%s avg_deliver=%s",
				s.Published, s.Routed, s.Delivered, s.Dropped, s.Subscribers, s.AvgRouteLatency, s.AvgDeliverLatency,
			)
		case <-timeout:
			log.Println("shutting down")
			return
		}
	}
}
