# `metrics.go`

```go
package main

import (
	"sync/atomic"
	"time"
)

type Metrics struct {
	Enqueued       uint64
	Dequeued       uint64
	Processed      uint64
	Dropped        uint64
	Errors         uint64
	TotalLatencyNs uint64
	MaxLatencyNs   uint64
}

func (m *Metrics) IncEnqueued()  { atomic.AddUint64(&m.Enqueued, 1) }
func (m *Metrics) IncDequeued()  { atomic.AddUint64(&m.Dequeued, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.Processed, 1) }
func (m *Metrics) IncDropped()   { atomic.AddUint64(&m.Dropped, 1) }
func (m *Metrics) IncErrors()    { atomic.AddUint64(&m.Errors, 1) }

func (m *Metrics) ObserveLatency(startNs int64) {
	latency := uint64(time.Now().UnixNano() - startNs)
	atomic.AddUint64(&m.TotalLatencyNs, latency)

	for {
		current := atomic.LoadUint64(&m.MaxLatencyNs)
		if latency <= current {
			break
		}
		if atomic.CompareAndSwapUint64(&m.MaxLatencyNs, current, latency) {
			break
		}
	}
}

func (m *Metrics) Snapshot() Metrics {
	return Metrics{
		Enqueued:       atomic.LoadUint64(&m.Enqueued),
		Dequeued:       atomic.LoadUint64(&m.Dequeued),
		Processed:      atomic.LoadUint64(&m.Processed),
		Dropped:        atomic.LoadUint64(&m.Dropped),
		Errors:         atomic.LoadUint64(&m.Errors),
		TotalLatencyNs: atomic.LoadUint64(&m.TotalLatencyNs),
		MaxLatencyNs:   atomic.LoadUint64(&m.MaxLatencyNs),
	}
}

func (m *Metrics) AvgLatencyNs() uint64 {
	processed := atomic.LoadUint64(&m.Processed)
	if processed == 0 {
		return 0
	}
	return atomic.LoadUint64(&m.TotalLatencyNs) / processed
}
