package main

import (
	"sync"
)

type Handler func(Message) error

type Route struct {
	Key     uint32
	Handler Handler
}

type Router struct {
	mu     sync.RWMutex
	routes map[uint32]Handler
}

func NewRouter() *Router {
	return &Router{
		routes: make(map[uint32]Handler),
	}
}

func (r *Router) Register(key uint32, h Handler) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.routes[key] = h
}

func (r *Router) Get(key uint32) (Handler, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	h, ok := r.routes[key]
	return h, ok
}
