# `worker.go`

```go
package main

import (
	"log"
)

type WorkerPool struct {
	router  *Router
	metrics *Metrics
	jobs    chan Message
}

func NewWorkerPool(router *Router, metrics *Metrics, bufferSize int) *WorkerPool {
	return &WorkerPool{
		router:  router,
		metrics: metrics,
		jobs:    make(chan Message, bufferSize),
	}
}

func (wp *WorkerPool) Start(workers int) {
	for i := 0; i < workers; i++ {
		go func(id int) {
			for msg := range wp.jobs {
				wp.metrics.IncDequeued()

				handler, ok := wp.router.Get(msg.RoutingKey)
				if !ok {
					wp.metrics.IncDropped()
					continue
				}

				if err := handler(msg); err != nil {
					wp.metrics.IncErrors()
					log.Printf("worker=%d msg=%d error=%v", id, msg.ID, err)
				}

				wp.metrics.IncProcessed()
				wp.metrics.ObserveLatency(msg.CreatedAt)
			}
		}(i)
	}
}

func (wp *WorkerPool) Submit(msg Message) bool {
	select {
	case wp.jobs <- msg:
		wp.metrics.IncEnqueued()
		return true
	default:
		wp.metrics.IncDropped()
		return false
	}
}

func (wp *WorkerPool) Stop() {
	close(wp.jobs)
}
```

