use crossbeam_channel::{bounded, Receiver, Sender, TrySendError};
use dashmap::DashMap;
use parking_lot::RwLock;
use std::{
    collections::HashMap,
    hash::{Hash, Hasher},
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    thread,
    time::{Duration, Instant},
};

#[derive(Clone, Debug)]
pub struct Message {
    pub topic: String,
    pub key: Option<String>,
    pub payload: Vec<u8>,
    pub created_at: Instant,
}

impl Message {
    pub fn new(topic: impl Into<String>, key: Option<String>, payload: Vec<u8>) -> Self {
        Self {
            topic: topic.into(),
            key,
            payload,
            created_at: Instant::now(),
        }
    }
}

pub type Handler = Arc<dyn Fn(Message) + Send + Sync + 'static>;

#[derive(Default)]
pub struct LatencyMetrics {
    total_messages: AtomicU64,
    total_latency_ns: AtomicU64,
    dropped_messages: AtomicU64,

    // Buckets in nanoseconds:
    // <1us, <10us, <100us, <1ms, <10ms, <100ms, >=100ms
    buckets: [AtomicU64; 7],
}

impl LatencyMetrics {
    pub fn record(&self, latency: Duration) {
        let ns = latency.as_nanos() as u64;
        self.total_messages.fetch_add(1, Ordering::Relaxed);
        self.total_latency_ns.fetch_add(ns, Ordering::Relaxed);

        let idx = if ns < 1_000 {
            0
        } else if ns < 10_000 {
            1
        } else if ns < 100_000 {
            2
        } else if ns < 1_000_000 {
            3
        } else if ns < 10_000_000 {
            4
        } else if ns < 100_000_000 {
            5
        } else {
            6
        };

        self.buckets[idx].fetch_add(1, Ordering::Relaxed);
    }

    pub fn drop_message(&self) {
        self.dropped_messages.fetch_add(1, Ordering::Relaxed);
    }

    pub fn snapshot(&self) -> MetricsSnapshot {
        let total = self.total_messages.load(Ordering::Relaxed);
        let latency = self.total_latency_ns.load(Ordering::Relaxed);
        let dropped = self.dropped_messages.load(Ordering::Relaxed);

        let mut buckets = [0u64; 7];
        for i in 0..7 {
            buckets[i] = self.buckets[i].load(Ordering::Relaxed);
        }

        MetricsSnapshot {
            total_messages: total,
            avg_latency_ns: if total > 0 { latency / total } else { 0 },
            dropped_messages: dropped,
            buckets,
        }
    }
}

pub struct MetricsSnapshot {
    pub total_messages: u64,
    pub avg_latency_ns: u64,
    pub dropped_messages: u64,
    pub buckets: [u64; 7],
}

pub struct Router {
    handlers: DashMap<String, Handler>,
    worker_tx: Sender<Message>,
    worker_rx: Receiver<Message>,
    metrics: Arc<LatencyMetrics>,
}

impl Router {
    pub fn new(queue_size: usize) -> Self {
        let (tx, rx) = bounded(queue_size);
        Self {
            handlers: DashMap::new(),
            worker_tx: tx,
            worker_rx: rx,
            metrics: Arc::new(LatencyMetrics::default()),
        }
    }

    pub fn metrics(&self) -> Arc<LatencyMetrics> {
        self.metrics.clone()
    }

    pub fn register_handler<F>(&self, topic: impl Into<String>, handler: F)
    where
        F: Fn(Message) + Send + Sync + 'static,
    {
        self.handlers.insert(topic.into(), Arc::new(handler));
    }

    pub fn start_workers(&self, num_workers: usize) {
        let rx = self.worker_rx.clone();
        let handlers = self.handlers.clone();
        let metrics = self.metrics.clone();

        for _ in 0..num_workers {
            let rx = rx.clone();
            let handlers = handlers.clone();
            let metrics = metrics.clone();

            thread::spawn(move || {
                while let Ok(msg) = rx.recv() {
                    let dispatch_start = Instant::now();

                    if let Some(handler) = handlers.get(&msg.topic) {
                        (handler)(msg);
                    } else {
                        // No handler found; silently drop or log in real systems
                    }

                    metrics.record(dispatch_start.elapsed());
                }
            });
        }
    }

    pub fn publish(&self, msg: Message) -> Result<(), Message> {
        match self.worker_tx.try_send(msg) {
            Ok(_) => Ok(()),
            Err(TrySendError::Full(msg)) => {
                self.metrics.drop_message();
                Err(msg)
            }
            Err(TrySendError::Disconnected(msg)) => Err(msg),
        }
    }
}

pub struct MessageRouter {
    routers: Vec<Router>,
}

impl MessageRouter {
    pub fn new(partitions: usize, queue_size: usize) -> Self {
        let routers = (0..partitions)
            .map(|_| Router::new(queue_size))
            .collect::<Vec<_>>();

        Self { routers }
    }

    pub fn register_handler<F>(&self, topic: impl Into<String>, handler: F)
    where
        F: Fn(Message) + Send + Sync + 'static + Clone,
    {
        let topic = topic.into();
        for router in &self.routers {
            router.register_handler(topic.clone(), handler.clone());
        }
    }

    pub fn start(&self, workers_per_partition: usize) {
        for router in &self.routers {
            router.start_workers(workers_per_partition);
        }
    }

    pub fn publish(&self, msg: Message) -> Result<(), Message> {
        let idx = self.partition_for(&msg);
        self.routers[idx].publish(msg)
    }

    fn partition_for(&self, msg: &Message) -> usize {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        msg.topic.hash(&mut hasher);
        if let Some(key) = &msg.key {
            key.hash(&mut hasher);
        }
        (hasher.finish() as usize) % self.routers.len()
    }

    pub fn metrics(&self) -> Vec<MetricsSnapshot> {
        self.routers.iter().map(|r| r.metrics.snapshot()).collect()
    }
}

fn main() {
    let system = MessageRouter::new(4, 100_000);

    system.register_handler("orders", |msg| {
        // Simulate work
        let _ = msg.payload.len();
    });

    system.register_handler("quotes", |msg| {
        let _ = msg.payload.len();
    });

    system.start(2);

    // Producer loop
    for i in 0..1_000_000 {
        let topic = if i % 2 == 0 { "orders" } else { "quotes" };
        let msg = Message::new(topic, Some(format!("key-{}", i % 1024)), vec![1, 2, 3, 4]);

        let _ = system.publish(msg);
    }

    thread::sleep(Duration::from_secs(2));

    let snapshots = system.metrics();
    for (i, s) in snapshots.iter().enumerate() {
        println!(
            "partition={} total={} avg_latency_ns={} dropped={}",
            i, s.total_messages, s.avg_latency_ns, s.dropped_messages
        );
        println!("buckets={:?}", s.buckets);
    }
}
