### 2) Latency monitor

Uses `LongAdder` for low-contention aggregation.

```java
package hfmsg;

import java.util.concurrent.atomic.LongAdder;

public final class LatencyMonitor {
    private final LongAdder count = new LongAdder();
    private final LongAdder totalNanos = new LongAdder();
    private final LongAdder maxNanos = new LongAdder();

    public void record(long latencyNanos) {
        count.increment();
        totalNanos.add(latencyNanos);

        long currentMax;
        do {
            currentMax = maxNanos.sum();
            if (latencyNanos <= currentMax) return;
        } while (!compareAndSetMax(currentMax, latencyNanos));
    }

    private synchronized boolean compareAndSetMax(long expected, long update) {
        long current = maxNanos.sum();
        if (current == expected) {
            // LongAdder has no CAS, so we use synchronization for max update only.
            // This is acceptable for an initial implementation.
            maxNanos.reset();
            maxNanos.add(update);
            return true;
        }
        return false;
    }

    public MetricsSnapshot snapshot() {
        long c = count.sum();
        long total = totalNanos.sum();
        long max = maxNanos.sum();
        double avgMicros = c == 0 ? 0.0 : (total / 1000.0) / c;
        return new MetricsSnapshot(c, total, max, avgMicros);
    }
}
```

