### 5) Topic partition

Uses a bounded `ArrayBlockingQueue` for a first implementation. For lower latency, this can later be replaced with a ring buffer or Disruptor-style queue.

```java
package hfmsg;

import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

public final class TopicPartition {
    private final BlockingQueue<Message> queue;
    private final Thread worker;
    private final MessageHandler handler;
    private final LatencyMonitor latencyMonitor;
    private volatile boolean running = true;

    public TopicPartition(int capacity, MessageHandler handler, LatencyMonitor latencyMonitor, String name) {
        this.queue = new ArrayBlockingQueue<>(capacity);
        this.handler = handler;
        this.latencyMonitor = latencyMonitor;
        this.worker = new Thread(this::runLoop, "tp-" + name);
        this.worker.setDaemon(true);
        this.worker.start();
    }

    public boolean offer(Message message) {
        return queue.offer(message);
    }

    private void runLoop() {
        while (running || !queue.isEmpty()) {
            try {
                Message msg = queue.poll();
                if (msg == null) {
                    Thread.onSpinWait();
                    continue;
                }

                long start = System.nanoTime();
                handler.onMessage(msg);
                long latency = System.nanoTime() - msg.createdNanos();
                latencyMonitor.record(latency);
            } catch (Throwable t) {
                // In production, route to error handling / dead-letter queue / logging.
                t.printStackTrace();
            }
        }
    }

    public void shutdown() {
        running = false;
        try {
            worker.join(1000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
```

