### 6) Broker

Routes by topic and partitions.

```java
package hfmsg;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public final class Broker {
    private final ConcurrentHashMap<String, Topic> topics = new ConcurrentHashMap<>();

    public Topic createTopic(String name, int partitions, int queueCapacityPerPartition, MessageHandler handler) {
        Topic topic = new Topic(name, partitions, queueCapacityPerPartition, handler);
        topics.put(name, topic);
        return topic;
    }

    public boolean publish(Message message) {
        Topic topic = topics.get(message.topic());
        if (topic == null) {
            return false;
        }
        return topic.publish(message);
    }

    public void shutdown() {
        topics.values().forEach(Topic::shutdown);
    }
}
```

