### 7) Topic with round-robin partitioning

```java
package hfmsg;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public final class Topic {
    private final String name;
    private final List<TopicPartition> partitions;
    private final AtomicInteger rr = new AtomicInteger(0);

    public Topic(String name, int partitionCount, int queueCapacityPerPartition, MessageHandler handler) {
        this.name = name;
        this.partitions = new ArrayList<>(partitionCount);
        LatencyMonitor latencyMonitor = new LatencyMonitor();

        for (int i = 0; i < partitionCount; i++) {
            partitions.add(new TopicPartition(queueCapacityPerPartition, handler, latencyMonitor, name + "-" + i));
        }

        this.latencyMonitor = latencyMonitor;
    }

    private final LatencyMonitor latencyMonitor;

    public boolean publish(Message message) {
        int idx = Math.floorMod(rr.getAndIncrement(), partitions.size());
        return partitions.get(idx).offer(message);
    }

    public MetricsSnapshot metrics() {
        return latencyMonitor.snapshot();
    }

    public void shutdown() {
        partitions.forEach(TopicPartition::shutdown);
    }

    public String name() {
        return name;
    }
}
```

