## Go implementation

```go
package main

import (
	"fmt"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a high-frequency routed message.
type Message struct {
	Topic     uint32
	Key       uint64
	Payload   []byte
	EnqueueNs int64
}

// Subscriber processes messages.
type Subscriber interface {
	Handle(msg Message)
}

// Metrics tracks throughput and latency.
type Metrics struct {
	Received uint64
	Processed uint64
	Dropped   uint64

	LatencyNsTotal uint64
	LatencyNsCount  uint64
	LatencyNsMax    uint64
}

func (m *Metrics) RecordReceived() {
	atomic.AddUint64(&m.Received, 1)
}

func (m *Metrics) RecordProcessed(latency time.Duration) {
	atomic.AddUint64(&m.Processed, 1)

	ns := uint64(latency.Nanoseconds())
	atomic.AddUint64(&m.LatencyNsTotal, ns)
	atomic.AddUint64(&m.LatencyNsCount, 1)

	for {
		old := atomic.LoadUint64(&m.LatencyNsMax)
		if ns <= old {
			break
		}
		if atomic.CompareAndSwapUint64(&m.LatencyNsMax, old, ns) {
			break
		}
	}
}

func (m *Metrics) RecordDropped() {
	atomic.AddUint64(&m.Dropped, 1)
}

func (m *Metrics) Snapshot() Metrics {
	return Metrics{
		Received:       atomic.LoadUint64(&m.Received),
		Processed:      atomic.LoadUint64(&m.Processed),
		Dropped:        atomic.LoadUint64(&m.Dropped),
		LatencyNsTotal: atomic.LoadUint64(&m.LatencyNsTotal),
		LatencyNsCount: atomic.LoadUint64(&m.LatencyNsCount),
		LatencyNsMax:   atomic.LoadUint64(&m.LatencyNsMax),
	}
}

func (m Metrics) AvgLatency() time.Duration {
	if m.LatencyNsCount == 0 {
		return 0
	}
	return time.Duration(m.LatencyNsTotal / m.LatencyNsCount)
}

// Router routes messages by topic to registered subscribers.
type Router struct {
	subscribers map[uint32][]Subscriber
	inbound     chan Message
	metrics     *Metrics
	quit        chan struct{}
	wg          sync.WaitGroup
}

// NewRouter creates a router with a bounded inbound queue.
func NewRouter(queueSize int, metrics *Metrics) *Router {
	return &Router{
		subscribers: make(map[uint32][]Subscriber),
		inbound:     make(chan Message, queueSize),
		metrics:     metrics,
		quit:        make(chan struct{}),
	}
}

// Subscribe registers a subscriber for a topic.
func (r *Router) Subscribe(topic uint32, sub Subscriber) {
	r.subscribers[topic] = append(r.subscribers[topic], sub)
}

// Start launches the router dispatch loop.
func (r *Router) Start() {
	r.wg.Add(1)
	go func() {
		defer r.wg.Done()
		for {
			select {
			case msg := <-r.inbound:
				subs := r.subscribers[msg.Topic]
				for _, sub := range subs {
					// Fan out to subscribers in separate goroutine for simplicity.
					// For ultra-low latency, replace with worker pools or per-subscriber queues.
					sub := sub
					r.wg.Add(1)
					go func() {
						defer r.wg.Done()
						start := time.Now()
						sub.Handle(msg)
						r.metrics.RecordProcessed(time.Since(start))
					}()
				}
			case <-r.quit:
				return
			}
		}
	}()
}

// Stop stops the router and waits for completion.
func (r *Router) Stop() {
	close(r.quit)
	r.wg.Wait()
}

// Publish submits a message without blocking if queue is full.
func (r *Router) Publish(msg Message) bool {
	r.metrics.RecordReceived()

	msg.EnqueueNs = time.Now().UnixNano()

	select {
	case r.inbound <- msg:
		return true
	default:
		r.metrics.RecordDropped()
		return false
	}
}

// Example subscriber.
type PrintSubscriber struct {
	id string
}

func (p *PrintSubscriber) Handle(msg Message) {
	// Simulate work
	_ = msg.Payload
	_ = msg.Key
}

// LatencySubscriber records end-to-end queue latency.
type LatencySubscriber struct {
	metrics *Metrics
}

func (l *LatencySubscriber) Handle(msg Message) {
	enqueue := time.Unix(0, msg.EnqueueNs)
	latency := time.Since(enqueue)
	l.metrics.RecordProcessed(latency)
}

// FastWorkerPool is a simple consumer pool for one topic.
type FastWorkerPool struct {
	topic   uint32
	input   chan Message
	metrics *Metrics
	quit    chan struct{}
	wg      sync.WaitGroup
	handler func(Message)
}

func NewFastWorkerPool(topic uint32, workers, queueSize int, handler func(Message), metrics *Metrics) *FastWorkerPool {
	p := &FastWorkerPool{
		topic:   topic,
		input:   make(chan Message, queueSize),
		metrics: metrics,
		quit:    make(chan struct{}),
		handler: handler,
	}
	p.wg.Add(workers)
	for i := 0; i < workers; i++ {
		go func() {
			defer p.wg.Done()
			for {
				select {
				case msg := <-p.input:
					start := time.Now()
					handler(msg)
					metrics.RecordProcessed(time.Since(start))
				case <-p.quit:
					return
				}
			}
		}()
	}
	return p
}

func (p *FastWorkerPool) Handle(msg Message) {
	select {
	case p.input <- msg:
	default:
		p.metrics.RecordDropped()
	}
}

func (p *FastWorkerPool) Stop() {
	close(p.quit)
	p.wg.Wait()
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	metrics := &Metrics{}
	router := NewRouter(1_000_000, metrics)

	// Example topic handler pool.
	pool := NewFastWorkerPool(
		1,
		8,
		100_000,
		func(msg Message) {
			// Simulate processing logic
			_ = msg.Payload
		},
		metrics,
	)

	router.Subscribe(1, pool)
	router.Start()

	// Simulate a high-rate publisher
	var published uint64
	start := time.Now()

	for i := 0; i < 5_000_000; i++ {
		msg := Message{
			Topic:   1,
			Key:     uint64(i),
			Payload: []byte("hello"),
		}
		if router.Publish(msg) {
			published++
		}
	}

	// Let processing drain briefly
	time.Sleep(2 * time.Second)

	router.Stop()
	pool.Stop()

	s := metrics.Snapshot()
	elapsed := time.Since(start)

	fmt.Printf("Published: %d\n", published)
	fmt.Printf("Received:  %d\n", s.Received)
	fmt.Printf("Processed: %d\n", s.Processed)
	fmt.Printf("Dropped:   %d\n", s.Dropped)
	fmt.Printf("Avg latency: %s\n", s.AvgLatency())
	fmt.Printf("Max latency: %s\n", time.Duration(s.LatencyNsMax))
	fmt.Printf("Throughput: %.2f msgs/sec\n", float64(published)/elapsed.Seconds())
}
