package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Key       string
	Payload   []byte
	CreatedAt  time.Time
	TraceID    uint64
}

type Subscriber struct {
	ID   string
	Out  chan *Message
}

type Metrics struct {
	Received     uint64
	Routed       uint64
	Dropped      uint64
	Delivered    uint64
	QueueDepth   int64
	TotalLatency int64 // nanoseconds
	MaxLatency   int64 // nanoseconds
}

func (m *Metrics) AddLatency(d time.Duration) {
	ns := d.Nanoseconds()
	atomic.AddInt64(&m.TotalLatency, ns)

	for {
		old := atomic.LoadInt64(&m.MaxLatency)
		if ns <= old {
			break
		}
		if atomic.CompareAndSwapInt64(&m.MaxLatency, old, ns) {
			break
		}
	}
}

func (m *Metrics) Snapshot(received, routed, dropped, delivered uint64) string {
	totalLatency := atomic.LoadInt64(&m.TotalLatency)
	maxLatency := atomic.LoadInt64(&m.MaxLatency)

	avg := int64(0)
	if delivered > 0 {
		avg = totalLatency / int64(delivered)
	}

	return fmt.Sprintf(
		"received=%d routed=%d dropped=%d delivered=%d avg_latency_ns=%d max_latency_ns=%d queue_depth=%d",
		received, routed, dropped, delivered, avg, maxLatency, atomic.LoadInt64(&m.QueueDepth),
	)
}

type Router struct {
	partitions []chan *Message
	subsMu     sync.RWMutex
	subs       map[string][]*Subscriber
	metrics    *Metrics
}

func NewRouter(numPartitions int, partitionQueueSize int, metrics *Metrics) *Router {
	r := &Router{
		partitions: make([]chan *Message, numPartitions),
		subs:       make(map[string][]*Subscriber),
		metrics:    metrics,
	}
	for i := 0; i < numPartitions; i++ {
		r.partitions[i] = make(chan *Message, partitionQueueSize)
	}
	return r
}

func (r *Router) Start(ctx context.Context) {
	for i := range r.partitions {
		go r.partitionWorker(ctx, i, r.partitions[i])
	}
}

func (r *Router) partitionWorker(ctx context.Context, id int, ch <-chan *Message) {
	for {
		select {
		case <-ctx.Done():
			return
		case msg := <-ch:
			if msg == nil {
				continue
			}
			r.route(msg)
		}
	}
}

func (r *Router) route(msg *Message) {
	atomic.AddUint64(&r.metrics.Routed, 1)

	start := time.Now()

	r.subsMu.RLock()
	subs := r.subs[msg.Topic]
	r.subsMu.RUnlock()

	for _, sub := range subs {
		select {
		case sub.Out <- msg:
			atomic.AddUint64(&r.metrics.Delivered, 1)
		default:
			atomic.AddUint64(&r.metrics.Dropped, 1)
		}
	}

	r.metrics.AddLatency(time.Since(start))
}

func (r *Router) hashPartition(key string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return int(h.Sum32()) % len(r.partitions)
}

func (r *Router) Publish(msg *Message) {
	atomic.AddUint64(&r.metrics.Received, 1)

	idx := r.hashPartition(msg.Key)

	select {
	case r.partitions[idx] <- msg:
		atomic.AddInt64(&r.metrics.QueueDepth, 1)
	default:
		atomic.AddUint64(&r.metrics.Dropped, 1)
	}
}

func (r *Router) Subscribe(topic string, sub *Subscriber) {
	r.subsMu.Lock()
	defer r.subsMu.Unlock()
	r.subs[topic] = append(r.subs[topic], sub)
}

func startLatencyExporter(metrics *Metrics) {
	http.HandleFunc("/metrics", func(w http.ResponseWriter, _ *http.Request) {
		received := atomic.LoadUint64(&metrics.Received)
		routed := atomic.LoadUint64(&metrics.Routed)
		dropped := atomic.LoadUint64(&metrics.Dropped)
		delivered := atomic.LoadUint64(&metrics.Delivered)

		fmt.Fprintln(w, metrics.Snapshot(received, routed, dropped, delivered))
	})

	go func() {
		log.Println("metrics exporter listening on :8080")
		if err := http.ListenAndServe(":8080", nil); err != nil {
			log.Printf("metrics exporter error: %v", err)
		}
	}()
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	metrics := &Metrics{}
	router := NewRouter(64, 4096, metrics)
	router.Start(ctx)
	startLatencyExporter(metrics)

	// Example subscriptions
	s1 := &Subscriber{ID: "sub-1", Out: make(chan *Message, 1024)}
	s2 := &Subscriber{ID: "sub-2", Out: make(chan *Message, 1024)}
	router.Subscribe("orders", s1)
	router.Subscribe("orders", s2)

	// Subscriber consumers
	go func() {
		for msg := range s1.Out {
			_ = msg
		}
	}()
	go func() {
		for msg := range s2.Out {
			_ = msg
		}
	}()

	// Simulated high-rate ingest
	go func() {
		ticker := time.NewTicker(time.Microsecond)
		defer ticker.Stop()

		var trace uint64
		for {
			trace++
			router.Publish(&Message{
				Topic:    "orders",
				Key:      fmt.Sprintf("key-%d", trace%1024),
				Payload:  []byte("hello"),
				CreatedAt: time.Now(),
				TraceID:  trace,
			})
			<-ticker.C
		}
	}()

	log.Println("system running")
	select {}
}
