package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a unit of work.
type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt time.Time
}

// Metrics holds atomic counters and latency observations.
type Metrics struct {
	ingested    uint64
	routed      uint64
	processed   uint64
	dropped     uint64
	totalLatencyNs uint64
	maxLatencyNs    uint64
}

func (m *Metrics) IncIngested()  { atomic.AddUint64(&m.ingested, 1) }
func (m *Metrics) IncRouted()    { atomic.AddUint64(&m.routed, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.processed, 1) }
func (m *Metrics) IncDropped()   { atomic.AddUint64(&m.dropped, 1) }

func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.totalLatencyNs, ns)
	for {
		old := atomic.LoadUint64(&m.maxLatencyNs)
		if ns <= old {
			break
		}
		if atomic.CompareAndSwapUint64(&m.maxLatencyNs, old, ns) {
			break
		}
	}
}

func (m *Metrics) Snapshot() string {
	ingested := atomic.LoadUint64(&m.ingested)
	routed := atomic.LoadUint64(&m.routed)
	processed := atomic.LoadUint64(&m.processed)
	dropped := atomic.LoadUint64(&m.dropped)
	totalNs := atomic.LoadUint64(&m.totalLatencyNs)
	maxNs := atomic.LoadUint64(&m.maxLatencyNs)

	var avg time.Duration
	if processed > 0 {
		avg = time.Duration(totalNs / processed)
	}

	return fmt.Sprintf(
		"ingested=%d routed=%d processed=%d dropped=%d avg_latency=%s max_latency=%s",
		ingested, routed, processed, dropped, avg, time.Duration(maxNs),
	)
}

// Router pushes messages to shard workers.
type Router struct {
	shards  []chan Message
	metrics *Metrics
}

func NewRouter(numShards int, queueSize int, metrics *Metrics) *Router {
	shards := make([]chan Message, numShards)
	for i := range shards {
		shards[i] = make(chan Message, queueSize)
	}
	return &Router{
		shards:  shards,
		metrics: metrics,
	}
}

func (r *Router) route(msg Message) bool {
	shard := int(hashTopic(msg.Topic) % uint32(len(r.shards)))
	select {
	case r.shards[shard] <- msg:
		r.metrics.IncRouted()
		return true
	default:
		// Drop if shard queue is full.
		r.metrics.IncDropped()
		return false
	}
}

func hashTopic(topic string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	return h.Sum32()
}

// Worker processes messages from a shard queue.
func Worker(ctx context.Context, shardID int, ch <-chan Message, metrics *Metrics, wg *sync.WaitGroup) {
	defer wg.Done()

	for {
		select {
		case <-ctx.Done():
			return
		case msg := <-ch:
			// Simulate processing.
			now := time.Now()
			latency := now.Sub(msg.CreatedAt)

			metrics.IncProcessed()
			metrics.ObserveLatency(latency)

			// In a real system, do actual work here.
			_ = msg
		}
	}
}

// Producer simulates high-rate message ingestion.
func Producer(ctx context.Context, id int, router *Router, metrics *Metrics, ratePerSec int, topics []string, wg *sync.WaitGroup) {
	defer wg.Done()

	ticker := time.NewTicker(time.Second / time.Duration(ratePerSec))
	defer ticker.Stop()

	var msgID uint64

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			msg := Message{
				ID:        atomic.AddUint64(&msgID, 1),
				Topic:     topics[msgID%uint64(len(topics))],
				Payload:   []byte("hello world"),
				CreatedAt: time.Now(),
			}
			metrics.IncIngested()
			_ = router.route(msg)
		}
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	metrics := &Metrics{}
	numShards := runtime.NumCPU() * 2
	queueSize := 4096

	router := NewRouter(numShards, queueSize, metrics)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	var wg sync.WaitGroup

	// Start workers.
	for i := 0; i < numShards; i++ {
		wg.Add(1)
		go Worker(ctx, i, router.shards[i], metrics, &wg)
	}

	// Start producers.
	topics := []string{"orders", "quotes", "trades", "alerts"}
	numProducers := runtime.NumCPU()

	for i := 0; i < numProducers; i++ {
		wg.Add(1)
		go Producer(ctx, i, router, metrics, 100000, topics, &wg)
	}

	// Metrics reporter.
	go func() {
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				log.Println(metrics.Snapshot())
			}
		}
	}()

	// Run for 10 seconds.
	time.Sleep(10 * time.Second)
	cancel()
	wg.Wait()

	log.Println("shutdown complete")
	log.Println(metrics.Snapshot())
}
