        Message(long id, int topic, byte[] payload) {
            this.id = id;
            this.topic = topic;
            this.payload = payload;
            this.createdNanos = System.nanoTime();
        }
    }

    // -------- Metrics --------
    static final class LatencyMetrics {
        private final LongAdder count = new LongAdder();
        private final LongAdder totalLatencyNanos = new LongAdder();
        private final AtomicLong minLatencyNanos = new AtomicLong(Long.MAX_VALUE);
        private final AtomicLong maxLatencyNanos = new AtomicLong(Long.MIN_VALUE);

        void record(long latencyNanos) {
            count.increment();
            totalLatencyNanos.add(latencyNanos);

            minLatencyNanos.accumulateAndGet(latencyNanos, Math::min);
            maxLatencyNanos.accumulateAndGet(latencyNanos, Math::max);
        }

        long count() {
            return count.sum();
        }

        double avgMicros() {
            long c = count();
            return c == 0 ? 0.0 : (totalLatencyNanos.sum() / (double) c) / 1_000.0;
        }

        double minMicros() {
            long v = minLatencyNanos.get();
            return v == Long.MAX_VALUE ? 0.0 : v / 1_000.0;
        }

        double maxMicros() {
            long v = maxLatencyNanos.get();
            return v == Long.MIN_VALUE ? 0.0 : v / 1_000.0;
        }
    }

    // -------- Subscriber --------
    interface Subscriber {
        void onMessage(Message msg);
    }

    static final class LatencyTrackingSubscriber implements Subscriber {
        private final LatencyMetrics metrics;

        LatencyTrackingSubscriber(LatencyMetrics metrics) {
            this.metrics = metrics;
        }

        @Override
        public void onMessage(Message msg) {
            long latency = System.nanoTime() - msg.createdNanos;
            metrics.record(latency);
        }
    }

    // -------- Router --------
    static final class Router {
        private final ConcurrentHashMap<Integer, CopyOnWriteArrayList<Subscriber>> subscribers = new ConcurrentHashMap<>();

        public void subscribe(int topic, Subscriber subscriber) {
            subscribers.computeIfAbsent(topic, k -> new CopyOnWriteArrayList<>()).add(subscriber);
        }

        public void route(Message msg) {
            List<Subscriber> subs = subscribers.get(msg.topic);
            if (subs == null) return;

            for (Subscriber s : subs) {
                s.onMessage(msg);
            }
        }
    }

    // -------- Producer --------
    static final class Producer implements Runnable {
        private final Router router;
        private final int topicCount;
        private final long messageTarget;
        private final int payloadSize;
        private final AtomicLong idGen = new AtomicLong();

        Producer(Router router, int topicCount, long messageTarget, int payloadSize) {
            this.router = router;
            this.topicCount = topicCount;
            this.messageTarget = messageTarget;
            this.payloadSize = payloadSize;
        }

        @Override
        public void run() {
            byte[] payload = new byte[payloadSize];
            long sent = 0;

            while (sent < messageTarget) {
                long id = idGen.incrementAndGet();
                int topic = (int) (id % topicCount);
                Message msg = new Message(id, topic, payload);
                router.route(msg);
                sent++;
            }
        }
    }

    // -------- Main --------
    public static void main(String[] args) throws Exception {
        int topics = 8;
        int subscribersPerTopic = 2;
        int producerThreads = 4;
        long messagesPerProducer = 500_000;
        int payloadSize = 64;

        Router router = new Router();
        LatencyMetrics metrics = new LatencyMetrics();

        for (int t = 0; t < topics; t++) {
            for (int i = 0; i < subscribersPerTopic; i++) {
                router.subscribe(t, new LatencyTrackingSubscriber(metrics));
            }
        }

        ExecutorService executor = Executors.newFixedThreadPool(producerThreads);

        long start = System.nanoTime();

        for (int i = 0; i < producerThreads; i++) {
            executor.submit(new Producer(router, topics, messagesPerProducer, payloadSize));
        }

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.MINUTES);

        long elapsedNanos = System.nanoTime() - start;
        long totalMessages = producerThreads * messagesPerProducer;

        double seconds = elapsedNanos / 1_000_000_000.0;
        double msgsPerSec = totalMessages / seconds;

        System.out.println("Total produced messages: " + totalMessages);
        System.out.println("Elapsed seconds: " + seconds);
        System.out.println("Throughput msgs/sec: " + msgsPerSec);
        System.out.println("Consumed messages: " + metrics.count());
        System.out.println("Avg latency (µs): " + metrics.avgMicros());
        System.out.println("Min latency (µs): " + metrics.minMicros());
        System.out.println("Max latency (µs): " + metrics.maxMicros());
    }
}
```

