### `HighFrequencyMessagingSystem.java`

```java
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.*;
import java.util.function.Consumer;

public class HighFrequencyMessagingSystem {

    // Message model
    static class Message {
        final long id;
        final long createdNanos;
        final String topic;
        final byte[] payload;

        Message(long id, String topic, byte[] payload) {
            this.id = id;
            this.topic = topic;
            this.payload = payload;
            this.createdNanos = System.nanoTime();
        }
    }

    // Metrics collector
    static class Metrics {
        private final LongAdder processed = new LongAdder();
        private final LongAdder totalLatencyNanos = new LongAdder();
        private final ConcurrentLinkedQueue<Long> latencySamples = new ConcurrentLinkedQueue<>();
        private final int sampleRate;

        Metrics(int sampleRate) {
            this.sampleRate = sampleRate;
        }

        void record(long latencyNanos) {
            processed.increment();
            totalLatencyNanos.add(latencyNanos);

            // Sample every N messages for percentile approximation
            if (processed.sum() % sampleRate == 0) {
                latencySamples.add(latencyNanos);
                if (latencySamples.size() > 100_000) {
                    latencySamples.poll();
                }
            }
        }

        long processed() {
            return processed.sum();
        }

        double avgLatencyMicros() {
            long p = processed.sum();
            return p == 0 ? 0.0 : (totalLatencyNanos.sum() / 1000.0) / p;
        }

        List<Long> snapshotSamples() {
            return new ArrayList<>(latencySamples);
        }
    }

    // Router
    static class Router {
        private final Map<String, Consumer<Message>> handlers = new ConcurrentHashMap<>();

        void register(String topic, Consumer<Message> handler) {
            handlers.put(topic, handler);
        }

        void route(Message msg) {
            Consumer<Message> handler = handlers.get(msg.topic);
            if (handler != null) {
                handler.accept(msg);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        final int producerThreads = 4;
        final int messagesPerProducer = 500_000; // total = 2M messages
        final int queueCapacity = 1 << 20;

        BlockingQueue<Message> queue = new ArrayBlockingQueue<>(queueCapacity);
        Metrics metrics = new Metrics(1000);
        Router router = new Router();

        // Example handler
        router.register("orders", msg -> {
            // Simulate light processing
            // In real systems, avoid allocations and heavy work here
        });

        AtomicBoolean running = new AtomicBoolean(true);
        ExecutorService producers = Executors.newFixedThreadPool(producerThreads);
        ExecutorService consumers = Executors.newFixedThreadPool(1);

        // Consumer loop
        consumers.submit(() -> {
            try {
                while (running.get() || !queue.isEmpty()) {
                    Message msg = queue.poll(1, TimeUnit.MILLISECONDS);
                    if (msg != null) {
                        router.route(msg);
                        long latency = System.nanoTime() - msg.createdNanos;
                        metrics.record(latency);
                    }
                }
            } catch (InterruptedException ignored) {
            }
        });

        // Periodic metrics printer
        ScheduledExecutorService monitor = Executors.newSingleThreadScheduledExecutor();
        AtomicLong lastProcessed = new AtomicLong(0);
        long startTime = System.nanoTime();

        monitor.scheduleAtFixedRate(() -> {
            long current = metrics.processed();
            long prev = lastProcessed.getAndSet(current);
            long throughput = current - prev;

            List<Long> samples = metrics.snapshotSamples();
            Collections.sort(samples);

            long p50 = percentile(samples, 50);
            long p95 = percentile(samples, 95);
            long p99 = percentile(samples, 99);

            System.out.printf(
                "processed=%d throughput=%d msg/s avg=%.2f us p50=%d ns p95=%d ns p99=%d ns queue=%d%n",
                current,
                throughput,
                metrics.avgLatencyMicros(),
                p50,
                p95,
                p99,
                queue.size()
            );
        }, 1, 1, TimeUnit.SECONDS);

        // Start producers
        for (int t = 0; t < producerThreads; t++) {
            final int producerId = t;
            producers.submit(() -> {
                for (int i = 0; i < messagesPerProducer; i++) {
                    try {
                        Message msg = new Message(
                            ((long) producerId << 32) | i,
                            "orders",
                            new byte[128]
                        );
                        queue.put(msg);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        break;
                    }
                }
            });
        }

        producers.shutdown();
        producers.awaitTermination(10, TimeUnit.MINUTES);

        running.set(false);
        consumers.shutdown();
        consumers.awaitTermination(10, TimeUnit.MINUTES);

        monitor.shutdownNow();

        long elapsedNanos = System.nanoTime() - startTime;
        double elapsedSeconds = elapsedNanos / 1_000_000_000.0;

        System.out.println("\n=== Final Stats ===");
        System.out.printf("Total processed: %d%n", metrics.processed());
        System.out.printf("Avg latency: %.2f us%n", metrics.avgLatencyMicros());
        System.out.printf("Overall throughput: %.2f msg/s%n", metrics.processed() / elapsedSeconds);
    }

    static long percentile(List<Long> samples, int p) {
        if (samples.isEmpty()) return 0;
        int index = (int) Math.ceil((p / 100.0) * samples.size()) - 1;
        index = Math.max(0, Math.min(index, samples.size() - 1));
        return samples.get(index);
    }
}
