## Go implementation

### `main.go`

```go
package main

import (
	"fmt"
	"hash/fnv"
	"math/rand"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Key      uint64
	CreatedN int64
	Payload  [32]byte // fixed payload to avoid allocations
}

type Metrics struct {
	count     atomic.Uint64
	totalNS    atomic.Uint64
	minNS      atomic.Uint64
	maxNS      atomic.Uint64
	latencies  chan uint64
	stop       chan struct{}
	wg         sync.WaitGroup
	histMutex  sync.Mutex
	hist       []uint64
}

func NewMetrics(histSize int) *Metrics {
	m := &Metrics{
		latencies: make(chan uint64, 1<<20),
		stop:      make(chan struct{}),
		hist:      make([]uint64, 0, histSize),
	}
	m.minNS.Store(^uint64(0))
	m.wg.Add(1)
	go m.run()
	return m
}

func (m *Metrics) run() {
	defer m.wg.Done()
	for {
		select {
		case v := <-m.latencies:
			m.count.Add(1)
			m.totalNS.Add(v)
			for {
				old := m.minNS.Load()
				if v >= old || m.minNS.CompareAndSwap(old, v) {
					break
				}
			}
			for {
				old := m.maxNS.Load()
				if v <= old || m.maxNS.CompareAndSwap(old, v) {
					break
				}
			}
			m.histMutex.Lock()
			m.hist = append(m.hist, v)
			m.histMutex.Unlock()
		case <-m.stop:
			return
		}
	}
}

func (m *Metrics) Observe(latency time.Duration) {
	select {
	case m.latencies <- uint64(latency.Nanoseconds()):
	default:
		// drop metrics if overwhelmed to keep pipeline fast
	}
}

func (m *Metrics) Close() {
	close(m.stop)
	m.wg.Wait()
}

func (m *Metrics) Summary() {
	m.histMutex.Lock()
	defer m.histMutex.Unlock()

	if len(m.hist) == 0 {
		fmt.Println("no samples")
		return
	}

	// copy/sort for percentiles
	s := make([]uint64, len(m.hist))
	copy(s, m.hist)

	// simple quicksort via standard library-less approach is unnecessary;
	// use built-in sort in real code. Keeping minimal:
	// Here we do a tiny insertion sort for the benchmark window.
	for i := 1; i < len(s); i++ {
		x := s[i]
		j := i - 1
		for j >= 0 && s[j] > x {
			s[j+1] = s[j]
			j--
		}
		s[j+1] = x
	}

	pct := func(p float64) uint64 {
		idx := int(float64(len(s)-1) * p)
		return s[idx]
	}

	count := m.count.Load()
	total := m.totalNS.Load()
	avg := float64(total) / float64(count)

	fmt.Printf("messages: %d\n", count)
	fmt.Printf("latency ns: min=%d p50=%d p95=%d p99=%d max=%d avg=%.2f\n",
		m.minNS.Load(),
		pct(0.50),
		pct(0.95),
		pct(0.99),
		m.maxNS.Load(),
		avg,
	)
}

type Shard struct {
	inbox   chan Message
	metrics *Metrics
}

type System struct {
	shards []Shard
	n      int
}

func NewSystem(numShards int, queueSize int, metrics *Metrics) *System {
	s := &System{
		shards: make([]Shard, numShards),
		n:      numShards,
	}
	for i := range s.shards {
		s.shards[i] = Shard{
			inbox:   make(chan Message, queueSize),
			metrics: metrics,
		}
	}
	return s
}

func (s *System) Start() {
	for i := range s.shards {
		shard := &s.shards[i]
		go func() {
			for msg := range shard.inbox {
				// Simulate tiny processing cost
				_ = msg.Payload[0]

				lat := time.Since(time.Unix(0, msg.CreatedN))
				shard.metrics.Observe(lat)
			}
		}()
	}
}

func (s *System) Route(msg Message) {
	idx := int(msg.Key % uint64(s.n))
	s.shards[idx].inbox <- msg
}

func (s *System) Close() {
	for i := range s.shards {
		close(s.shards[i].inbox)
	}
}

func hashKey(x uint64) uint64 {
	h := fnv.New64a()
	var b [8]byte
	for i := 0; i < 8; i++ {
		b[i] = byte(x >> (8 * i))
	}
	_, _ = h.Write(b[:])
	return h.Sum64()
}

func producer(id int, sys *System, duration time.Duration, rate int, done chan<- struct{}) {
	defer func() { done <- struct{}{} }()
	ticker := time.NewTicker(time.Second / time.Duration(rate))
	defer ticker.Stop()

	r := rand.New(rand.NewSource(time.Now().UnixNano() + int64(id)))
	deadline := time.Now().Add(duration)

	for time.Now().Before(deadline) {
		<-ticker.C
		k := uint64(r.Int63())
		msg := Message{
			Key:      hashKey(k),
			CreatedN: time.Now().UnixNano(),
		}
		msg.Payload[0] = byte(k)
		sys.Route(msg)
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	metrics := NewMetrics(100000)
	defer metrics.Close()

	numShards := runtime.NumCPU() * 2
	queueSize := 1 << 14

	sys := NewSystem(numShards, queueSize, metrics)
	sys.Start()

	duration := 5 * time.Second
	producers := runtime.NumCPU()
	ratePerProducer := 20000 // tune upward as your machine allows

	done := make(chan struct{}, producers)
	start := time.Now()

	for i := 0; i < producers; i++ {
		go producer(i, sys, duration, ratePerProducer, done)
	}

	for i := 0; i < producers; i++ {
		<-done
	}

	sys.Close()
	time.Sleep(500 * time.Millisecond) // let consumers drain

	elapsed := time.Since(start)
	fmt.Printf("run time: %v\n", elapsed)
	metrics.Summary()
}
