use std::net::Ipv4Addr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Instant;

#[derive(Clone, Copy, Debug)]
pub enum Action {
    Drop,
    Forward(u16), // output port
    Pass,
}

#[derive(Default)]
pub struct Stats {
    pub rx_packets: AtomicU64,
    pub forwarded_packets: AtomicU64,
    pub dropped_packets: AtomicU64,
    pub passthrough_packets: AtomicU64,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct EthernetHeader {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct Ipv4Header {
    ver_ihl: u8,
    dscp_ecn: u8,
    total_length: u16,
    identification: u16,
    flags_fragment: u16,
    ttl: u8,
    protocol: u8,
    checksum: u16,
    src: u32,
    dst: u32,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct TcpHeader {
    src_port: u16,
    dst_port: u16,
    seq: u32,
    ack: u32,
    data_offset_reserved_flags: u16,
    window: u16,
    checksum: u16,
    urgent_ptr: u16,
}

fn be16(x: u16) -> u16 { u16::from_be(x) }
fn be32(x: u32) -> u32 { u32::from_be(x) }

pub struct PacketFilter {
    allow_dst_ports: Vec<u16>,
    block_src_ips: Vec<Ipv4Addr>,
}

impl PacketFilter {
    pub fn new(allow_dst_ports: Vec<u16>, block_src_ips: Vec<Ipv4Addr>) -> Self {
        Self {
            allow_dst_ports,
            block_src_ips,
        }
    }

    #[inline(always)]
    pub fn classify(&self, pkt: &[u8]) -> Action {
        // Ethernet
        if pkt.len() < std::mem::size_of::<EthernetHeader>() {
            return Action::Drop;
        }

        let eth = unsafe { &*(pkt.as_ptr() as *const EthernetHeader) };
        let ethertype = be16(eth.ethertype);

        // IPv4 only
        if ethertype != 0x0800 {
            return Action::Pass;
        }

        let ip_off = std::mem::size_of::<EthernetHeader>();
        if pkt.len() < ip_off + std::mem::size_of::<Ipv4Header>() {
            return Action::Drop;
        }

        let ip = unsafe { &*(pkt[ip_off..].as_ptr() as *const Ipv4Header) };
        let version = ip.ver_ihl >> 4;
        let ihl = (ip.ver_ihl & 0x0f) as usize * 4;

        if version != 4 || ihl < 20 || pkt.len() < ip_off + ihl {
            return Action::Drop;
        }

        let src_ip = Ipv4Addr::from(be32(ip.src));
        if self.block_src_ips.iter().any(|x| *x == src_ip) {
            return Action::Drop;
        }

        // TCP/UDP port filtering
        let proto = ip.protocol;
        let l4_off = ip_off + ihl;
        match proto {
            6 => {
                // TCP
                if pkt.len() < l4_off + std::mem::size_of::<TcpHeader>() {
                    return Action::Drop;
                }
                let tcp = unsafe { &*(pkt[l4_off..].as_ptr() as *const TcpHeader) };
                let dst_port = be16(tcp.dst_port);

                if self.allow_dst_ports.contains(&dst_port) {
                    Action::Forward(1)
                } else {
                    Action::Drop
                }
            }
            17 => {
                // UDP: minimal header
                if pkt.len() < l4_off + 8 {
                    return Action::Drop;
                }
                let dst_port = u16::from_be_bytes([pkt[l4_off + 2], pkt[l4_off + 3]]);

                if self.allow_dst_ports.contains(&dst_port) {
                    Action::Forward(1)
                } else {
                    Action::Drop
                }
            }
            _ => Action::Pass,
        }
    }
}

pub struct PacketEngine {
    filter: PacketFilter,
    stats: Stats,
}

impl PacketEngine {
    pub fn new(filter: PacketFilter) -> Self {
        Self {
            filter,
            stats: Stats::default(),
        }
    }

    pub fn process_batch(&self, packets: &[&[u8]]) {
        for pkt in packets {
            self.stats.rx_packets.fetch_add(1, Ordering::Relaxed);

            match self.filter.classify(pkt) {
                Action::Drop => {
                    self.stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
                }
                Action::Forward(_port) => {
                    // Replace with NIC TX queue enqueue
                    self.stats.forwarded_packets.fetch_add(1, Ordering::Relaxed);
                }
                Action::Pass => {
                    self.stats.passthrough_packets.fetch_add(1, Ordering::Relaxed);
                }
            }
        }
    }

    pub fn print_stats(&self) {
        println!(
            "rx={} fwd={} drop={} pass={}",
            self.stats.rx_packets.load(Ordering::Relaxed),
            self.stats.forwarded_packets.load(Ordering::Relaxed),
            self.stats.dropped_packets.load(Ordering::Relaxed),
            self.stats.passthrough_packets.load(Ordering::Relaxed),
        );
    }
}

fn main() {
    let filter = PacketFilter::new(
        vec![80, 443, 8080],
        vec![Ipv4Addr::new(10, 0, 0, 66)],
    );

    let engine = PacketEngine::new(filter);

