}

struct Engine {
    rules: Vec<Rule>,
}

impl Engine {
    fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    fn classify(&self, pkt: &Packet) -> Action {
        if pkt.data.len() < 34 {
            return Action::Drop;
        }

        // Minimal IPv4 + TCP/UDP parsing
        let ethertype = u16::from_be_bytes([pkt.data[12], pkt.data[13]]);
        if ethertype != 0x0800 {
            return Action::Pass;
        }

        let ip = &pkt.data[14..];
        let ihl = (ip[0] & 0x0f) as usize * 4;
        if ip.len() < ihl + 8 {
            return Action::Drop;
        }

        let proto = ip[9];
        let src_ip = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
        let dst_ip = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

        let (src_port, dst_port) = match proto {
            6 | 17 => {
                let l4 = &ip[ihl..];
                if l4.len() < 4 {
                    return Action::Drop;
                }
                (
                    u16::from_be_bytes([l4[0], l4[1]]),
                    u16::from_be_bytes([l4[2], l4[3]]),
                )
            }
            _ => (0, 0),
        };

        for rule in &self.rules {
            let src_ok = rule.src_ip.map_or(true, |x| x == src_ip);
            let dst_ok = rule.dst_ip.map_or(true, |x| x == dst_ip);
            let proto_ok = rule.proto.map_or(true, |x| x == proto);
            let port_ok = rule.dst_port.map_or(true, |x| x == dst_port);

            if src_ok && dst_ok && proto_ok && port_ok {
                return rule.action;
            }
        }

        Action::Pass
    }
}

