use std::net::Ipv4Addr;
use std::sync::Arc;
use std::sync::atomic::{AtomicPtr, Ordering};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Action {
    Drop,
    Forward,
    Accept,
}

#[derive(Clone, Copy, Debug)]
pub struct PacketMeta {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8, // 6 = TCP, 17 = UDP
}

pub struct Packet<'a> {
    pub bytes: &'a [u8],
}

pub trait Backend {
    fn recv(&mut self, out: &mut [u8]) -> Option<usize>;
    fn send(&mut self, bytes: &[u8]) -> bool;
}

#[derive(Clone, Debug)]
pub enum Rule {
    AllowAll,
    DropAll,
    AllowIpv4Src { ip: Ipv4Addr },
    DropIpv4Src { ip: Ipv4Addr },
    AllowTcpDstPort { port: u16 },
    DropTcpDstPort { port: u16 },
    AllowUdpDstPort { port: u16 },
    DropUdpDstPort { port: u16 },
    ForwardIpv4SrcTo { ip: Ipv4Addr, next_hop: Ipv4Addr },
}

#[derive(Debug)]
pub struct CompiledRules {
    rules: Vec<Rule>,
}

impl CompiledRules {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    #[inline(always)]
    pub fn evaluate(&self, meta: &PacketMeta) -> Action {
        for rule in &self.rules {
            match *rule {
                Rule::AllowAll => return Action::Forward,
                Rule::DropAll => return Action::Drop,
                Rule::AllowIpv4Src { ip } => {
                    if meta.src_ip == ip {
                        return Action::Forward;
                    }
                }
                Rule::DropIpv4Src { ip } => {
                    if meta.src_ip == ip {
                        return Action::Drop;
                    }
                }
                Rule::AllowTcpDstPort { port } => {
                    if meta.proto == 6 && meta.dst_port == port {
                        return Action::Forward;
                    }
                }
                Rule::DropTcpDstPort { port } => {
                    if meta.proto == 6 && meta.dst_port == port {
                        return Action::Drop;
                    }
                }
                Rule::AllowUdpDstPort { port } => {
                    if meta.proto == 17 && meta.dst_port == port {
                        return Action::Forward;
                    }
                }
                Rule::DropUdpDstPort { port } => {
                    if meta.proto == 17 && meta.dst_port == port {
                        return Action::Drop;
                    }
                }
                Rule::ForwardIpv4SrcTo { ip, .. } => {
                    if meta.src_ip == ip {
                        return Action::Forward;
                    }
                }
            }
        }
        Action::Drop
    }
}

pub struct RuleTable {
    ptr: AtomicPtr<CompiledRules>,
}

impl RuleTable {
    pub fn new(initial: CompiledRules) -> Self {
        let boxed = Box::new(initial);
        Self {
            ptr: AtomicPtr::new(Box::into_raw(boxed)),
        }
    }

    #[inline(always)]
    pub fn snapshot(&self) -> &CompiledRules {
        let ptr = self.ptr.load(Ordering::Acquire);
        unsafe { &*ptr }
    }

    pub fn update(&self, new_rules: CompiledRules) {
        let boxed = Box::new(new_rules);
        let new_ptr = Box::into_raw(boxed);
        let old_ptr = self.ptr.swap(new_ptr, Ordering::AcqRel);
        unsafe {
            drop(Box::from_raw(old_ptr));
        }
    }
}

#[inline(always)]
fn parse_ipv4_packet(bytes: &[u8]) -> Option<PacketMeta> {
    if bytes.len() < 34 {
        return None;
    }

    let ethertype = u16::from_be_bytes([bytes[12], bytes[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ihl = (bytes[14] & 0x0F) as usize * 4;
    if bytes.len() < 14 + ihl + 8 {
        return None;
    }

    let proto = bytes[23];
    let src_ip = Ipv4Addr::new(bytes[26], bytes[27], bytes[28], bytes[29]);
    let dst_ip = Ipv4Addr::new(bytes[30], bytes[31], bytes[32], bytes[33]);

    let l4 = 14 + ihl;
    let src_port = u16::from_be_bytes([bytes[l4], bytes[l4 + 1]]);
    let dst_port = u16::from_be_bytes([bytes[l4 + 2], bytes[l4 + 3]]);

    Some(PacketMeta {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}

pub struct Service<B: Backend> {
    backend: B,
    rules: Arc<RuleTable>,
    rx_buf: Vec<u8>,
}

impl<B: Backend> Service<B> {
    pub fn new(backend: B, rules: Arc<RuleTable>) -> Self {
        Self {
            backend,
            rules,
            rx_buf: vec![0u8; 2048],
        }
    }

    #[inline(always)]
    pub fn process_one(&mut self) {
        if let Some(n) = self.backend.recv(&mut self.rx_buf) {
            let pkt = Packet {
                bytes: &self.rx_buf[..n],
            };

            if let Some(meta) = parse_ipv4_packet(pkt.bytes) {
                let decision = self.rules.snapshot().evaluate(&meta);

                match decision {
                    Action::Drop => {
                        // drop on the fast path
                    }
                    Action::Forward | Action::Accept => {
                        let _ = self.backend.send(pkt.bytes);
                    }
                }
            }
        }
    }

    pub fn run_forever(&mut self) -> ! {
        loop {
            self.process_one();
            std::hint::spin_loop();
        }
    }
}

