### Example: packet filter + forwarder in Rust (safe skeleton)
This example is a **user-space UDP forwarding service** with packet-level filtering logic. It’s not raw packet interception; it processes traffic received on a bound socket and forwards allowed packets to an upstream.

```rust
use std::collections::HashSet;
use std::net::{SocketAddr, UdpSocket};
use std::time::Duration;

#[derive(Debug, Clone)]
struct Packet {
    src: SocketAddr,
    dst: SocketAddr,
    payload: Vec<u8>,
}

#[derive(Default)]
struct FilterPolicy {
    allowed_sources: HashSet<SocketAddr>,
    max_payload_len: usize,
}

impl FilterPolicy {
    fn allow(&self, pkt: &Packet) -> bool {
        if !self.allowed_sources.is_empty() && !self.allowed_sources.contains(&pkt.src) {
            return false;
        }
        if pkt.payload.len() > self.max_payload_len {
            return false;
        }
        true
    }
}

fn main() -> std::io::Result<()> {
    let listen_addr: SocketAddr = "0.0.0.0:9000".parse().unwrap();
    let upstream_addr: SocketAddr = "127.0.0.1:9100".parse().unwrap();

    let socket = UdpSocket::bind(listen_addr)?;
    socket.set_nonblocking(true)?;
    socket.set_read_timeout(Some(Duration::from_millis(1)))?;

    let upstream = UdpSocket::bind("0.0.0.0:0")?;
    upstream.set_nonblocking(true)?;

    let mut policy = FilterPolicy {
        allowed_sources: HashSet::new(),
        max_payload_len: 1400, // typical MTU-safe UDP payload budget
    };

    // Example allowlist
    policy.allowed_sources.insert("127.0.0.1:5000".parse().unwrap());

    let mut buf = [0u8; 2048];

    loop {
        match socket.recv_from(&mut buf) {
            Ok((n, src)) => {
                let payload = buf[..n].to_vec();
                let pkt = Packet {
                    src,
                    dst: listen_addr,
                    payload,
                };

                if policy.allow(&pkt) {
                    // Forward as-is to upstream service
                    let _ = upstream.send_to(&pkt.payload, upstream_addr);
                } else {
                    // Drop silently or log
                    eprintln!("Dropped packet from {}", pkt.src);
                }
            }
            Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                // Very tight polling loop; in real systems use epoll/kqueue/io_uring
                std::thread::yield_now();
            }
            Err(e) => return Err(e),
        }
    }
}
```

