## Rust example: UDP filter + forwarder

```rust
use std::net::SocketAddr;
use std::sync::Arc;
use tokio::net::UdpSocket;
use tokio::sync::RwLock;

#[derive(Clone, Debug)]
struct FilterRule {
    allow_prefix: Option<Vec<u8>>,
    block_prefix: Option<Vec<u8>>,
}

impl FilterRule {
    fn allows(&self, packet: &[u8]) -> bool {
        if let Some(block) = &self.block_prefix {
            if packet.starts_with(block) {
                return false;
            }
        }
        if let Some(allow) = &self.allow_prefix {
            return packet.starts_with(allow);
        }
        true
    }
}

#[derive(Clone)]
struct PacketForwarder {
    listen_addr: SocketAddr,
    backend_addr: SocketAddr,
    filter: Arc<RwLock<FilterRule>>,
}

impl PacketForwarder {
    async fn run(self) -> std::io::Result<()> {
        let listener = UdpSocket::bind(self.listen_addr).await?;
        let backend = UdpSocket::bind("0.0.0.0:0").await?;
        backend.connect(self.backend_addr).await?;

        let mut buf = vec![0u8; 2048];

        loop {
            let (len, src) = listener.recv_from(&mut buf).await?;
            let packet = &buf[..len];

            let filter = self.filter.read().await;
            if !filter.allows(packet) {
                continue;
            }
            drop(filter);

            // Forward packet to backend
            backend.send(packet).await?;

            println!("Forwarded {} bytes from {}", len, src);
        }
    }
}

#[tokio::main]
async fn main() -> std::io::Result<()> {
    let service = PacketForwarder {
        listen_addr: "0.0.0.0:9000".parse().unwrap(),
        backend_addr: "127.0.0.1:9001".parse().unwrap(),
        filter: Arc::new(RwLock::new(FilterRule {
            allow_prefix: None,
            block_prefix: Some(b"DROP".to_vec()),
        })),
    };

    service.run().await
}
```

