## 1) eBPF XDP program (`xdp_filter.bpf.c`)

```c
// xdp_filter.bpf.c
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct flow_key {
    __u32 src_ip;
    __u32 dst_ip;
    __u8  proto;
    __u8  pad[3];
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 65536);
    __type(key, struct flow_key);
    __type(value, __u8); // 1 = allow, 0 = deny
} policy_map SEC(".maps");

struct {
    __uint(type, BPF_MAP_TYPE_PERCPU_HASH);
    __uint(max_entries, 65536);
    __type(key, struct flow_key);
    __type(value, __u64);
} counters SEC(".maps");

static __always_inline int parse_ipv4(void *data, void *data_end, struct flow_key *k) {
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) return -1;
    if (bpf_ntohs(eth->h_proto) != ETH_P_IP) return -1;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end) return -1;

    k->src_ip = ip->saddr;
    k->dst_ip = ip->daddr;
    k->proto = ip->protocol;
    return 0;
}

SEC("xdp")
int xdp_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct flow_key k = {};
    if (parse_ipv4(data, data_end, &k) < 0) {
        return XDP_PASS;
    }

    __u8 *decision = bpf_map_lookup_elem(&policy_map, &k);
    if (decision && *decision == 0) {
        return XDP_DROP;
    }

    __u64 *cnt = bpf_map_lookup_elem(&counters, &k);
    if (cnt) {
        __sync_fetch_and_add(cnt, 1);
    } else {
        __u64 init = 1;
        bpf_map_update_elem(&counters, &k, &init, BPF_ANY);
    }

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
