use aya::maps::HashMap;
use aya::programs::Xdp;
use clap::Parser;
use anyhow::Result;
use std::net::Ipv4Addr;
use std::convert::TryInto;

#[derive(Parser)]
struct Opts {
    /// Network interface to attach XDP to
    iface: String,
}

#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    proto: u8,
    pad: [u8; 3],
}

fn ipv4_to_u32(ip: Ipv4Addr) -> u32 {
    u32::from_be_bytes(ip.octets())
}

fn main() -> Result<()> {
    let opts = Opts::parse();

    let mut bpf = Bpf::load(include_bytes_aligned!(
        "../../target/bpfel-unknown-none/release/xdp_filter"
    ))?;

    let program: &mut Xdp = bpf.program_mut("xdp_filter")?.try_into()?;
    program.load()?;
    program.attach(&opts.iface, aya::programs::XdpFlags::default())?;

    let mut policy_map: HashMap<_, FlowKey, u8> = HashMap::try_from(bpf.map_mut("policy_map")?)?;

    // Example policy: deny one specific flow
    let deny_key = FlowKey {
        src_ip: ipv4_to_u32("10.0.0.10".parse()?),
        dst_ip: ipv4_to_u32("10.0.0.20".parse()?),
        proto: 6, // TCP
        pad: [0; 3],
    };
    policy_map.insert(deny_key, 0, 0)?;

    // Example policy: explicitly allow another flow
    let allow_key = FlowKey {
        src_ip: ipv4_to_u32("10.0.0.11".parse()?),
        dst_ip: ipv4_to_u32("10.0.0.21".parse()?),
        proto: 17, // UDP
        pad: [0; 3],
    };
    policy_map.insert(allow_key, 1, 0)?;

    println!("XDP filter attached on {}", opts.iface);
    println!("Policies loaded");
    Ok(())
}
