use std::net::Ipv4Addr;
use std::time::Instant;

#[derive(Debug, Clone, Copy)]
enum Action {
    Drop,
    Forward,
}

#[derive(Debug, Clone, Copy)]
struct PacketView<'a> {
    data: &'a [u8],
}

impl<'a> PacketView<'a> {
    fn ethertype(&self) -> Option<u16> {
        if self.data.len() < 14 {
            return None;
        }
        Some(u16::from_be_bytes([self.data[12], self.data[13]]))
    }

    fn ipv4_header_start(&self) -> Option<usize> {
        match self.ethertype()? {
            0x0800 => Some(14),
            _ => None,
        }
    }

    fn ipv4_src_dst(&self) -> Option<(Ipv4Addr, Ipv4Addr, u8)> {
        let start = self.ipv4_header_start()?;
        if self.data.len() < start + 20 {
            return None;
        }

        let ihl = (self.data[start] & 0x0f) as usize * 4;
        if ihl < 20 || self.data.len() < start + ihl {
            return None;
        }

        let proto = self.data[start + 9];
        let src = Ipv4Addr::new(
            self.data[start + 12],
            self.data[start + 13],
            self.data[start + 14],
            self.data[start + 15],
        );
        let dst = Ipv4Addr::new(
            self.data[start + 16],
            self.data[start + 17],
            self.data[start + 18],
            self.data[start + 19],
        );

        Some((src, dst, proto))
    }

    fn l4_ports(&self) -> Option<(u16, u16)> {
        let start = self.ipv4_header_start()?;
        if self.data.len() < start + 20 {
            return None;
        }

        let ihl = (self.data[start] & 0x0f) as usize * 4;
        let proto = self.data[start + 9];
        let l4 = start + ihl;

        match proto {
            6 | 17 => {
                if self.data.len() < l4 + 4 {
                    return None;
                }
                let src = u16::from_be_bytes([self.data[l4], self.data[l4 + 1]]);
                let dst = u16::from_be_bytes([self.data[l4 + 2], self.data[l4 + 3]]);
                Some((src, dst))
            }
            _ => None,
        }
    }
}

#[derive(Debug)]
struct RuleSet {
    blocked_src: Vec<Ipv4Addr>,
    blocked_dst_ports: Vec<u16>,
}

impl RuleSet {
    fn decide(&self, pkt: &PacketView<'_>) -> Action {
        if let Some((src, _dst, _proto)) = pkt.ipv4_src_dst() {
            if self.blocked_src.contains(&src) {
                return Action::Drop;
            }
        }

        if let Some((_src_port, dst_port)) = pkt.l4_ports() {
            if self.blocked_dst_ports.contains(&dst_port) {
                return Action::Drop;
            }
        }

        Action::Forward
    }
}

