## Minimal safe C skeleton: packet filter + forward decision
This is a **framework** using Linux raw sockets for demonstration. For production low latency, replace socket I/O with `AF_XDP` or DPDK.

```c
// packet_forwarder.c
// Build: gcc -O3 -march=native -Wall -Wextra packet_forwarder.c -o packet_forwarder
// Note: demonstration only; use AF_XDP/DPDK for true low latency.

#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <linux/tcp.h>
#include <net/if.h>
#include <pthread.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#define MAX_PACKET_SIZE 2048
#define RING_SIZE 1024

static volatile sig_atomic_t g_running = 1;

typedef enum {
    ACTION_DROP = 0,
    ACTION_FORWARD = 1,
    ACTION_ALLOW = 2
} action_t;

typedef struct {
    uint8_t proto;          // IP protocol
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
} flow_key_t;

typedef struct {
    uint32_t src_ip;
    uint32_t src_mask;
    uint32_t dst_ip;
    uint32_t dst_mask;
    uint8_t proto;          // 0 = wildcard
    uint16_t src_pmin, src_pmax;
    uint16_t dst_pmin, dst_pmax;
    action_t action;
} rule_t;

typedef struct {
    int rx_sock;
    int tx_sock;
    int ifindex_in;
    int ifindex_out;
    unsigned char mac_out[6];
    rule_t *rules;
    size_t rule_count;
} ctx_t;

static void on_sigint(int signo) {
    (void)signo;
    g_running = 0;
}

static int get_ifindex(const char *ifname) {
    return if_nametoindex(ifname);
}

static int get_if_mac(const char *ifname, unsigned char mac[6]) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return -1;

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    int rc = ioctl(fd, SIOCGIFHWADDR, &ifr);
    close(fd);
    if (rc < 0) return -1;

    memcpy(mac, ifr.ifr_hwaddr.sa_data, 6);
    return 0;
}

static action_t match_rule(const rule_t *r, const flow_key_t *k) {
    if (r->proto != 0 && r->proto != k->proto) return ACTION_DROP;

    if (((k->src_ip ^ r->src_ip) & r->src_mask) != 0) return ACTION_DROP;
    if (((k->dst_ip ^ r->dst_ip) & r->dst_mask) != 0) return ACTION_DROP;

    if (r->src_pmin && (k->src_port < r->src_pmin || k->src_port > r->src_pmax)) return ACTION_DROP;
    if (r->dst_pmin && (k->dst_port < r->dst_pmin || k->dst_port > r->dst_pmax)) return ACTION_DROP;

    return r->action;
}

static action_t classify_packet(const uint8_t *buf, size_t len, const rule_t *rules, size_t rule_count) {
    if (len < sizeof(struct ethhdr)) return ACTION_DROP;

    const struct ethhdr *eth = (const struct ethhdr *)buf;
    if (ntohs(eth->h_proto) != ETH_P_IP) return ACTION_DROP;

    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr)) return ACTION_DROP;
    const struct iphdr *ip = (const struct iphdr *)(buf + sizeof(struct ethhdr));

    size_t ip_hlen = ip->ihl * 4;
    if (ip_hlen < sizeof(struct iphdr)) return ACTION_DROP;
    if (len < sizeof(struct ethhdr) + ip_hlen) return ACTION_DROP;

    flow_key_t k = {
        .proto = ip->protocol,
        .src_ip = ip->saddr,
        .dst_ip = ip->daddr,
        .src_port = 0,
        .dst_port = 0
    };

    const uint8_t *l4 = buf + sizeof(struct ethhdr) + ip_hlen;
    size_t l4_len = len - sizeof(struct ethhdr) - ip_hlen;

    if (ip->protocol == IPPROTO_TCP && l4_len >= sizeof(struct tcphdr)) {
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        k.src_port = ntohs(tcp->source);
        k.dst_port = ntohs(tcp->dest);
    } else if (ip->protocol == IPPROTO_UDP && l4_len >= sizeof(struct udphdr)) {
        const struct udphdr *udp = (const struct udphdr *)l4;
        k.src_port = ntohs(udp->source);
        k.dst_port = ntohs(udp->dest);
    }

    // First-match policy
    for (size_t i = 0; i < rule_count; i++) {
        action_t a = match_rule(&rules[i], &k);
        if (a != ACTION_DROP) return a;
    }

    return ACTION_DROP;
}

static int send_packet(int sock, int ifindex, const unsigned char dst_mac[6],
                       const uint8_t *pkt, size_t len) {
    struct sockaddr_ll sll = {
        .sll_family = AF_PACKET,
        .sll_ifindex = ifindex,
        .sll_halen = ETH_ALEN
    };
    memcpy(sll.sll_addr, dst_mac, ETH_ALEN);

    ssize_t n = sendto(sock, pkt, len, 0, (struct sockaddr *)&sll, sizeof(sll));
    return (n == (ssize_t)len) ? 0 : -1;
}

static void *rx_loop(void *arg) {
    ctx_t *ctx = (ctx_t *)arg;
    uint8_t buf[MAX_PACKET_SIZE];

    while (g_running) {
        ssize_t n = recv(ctx->rx_sock, buf, sizeof(buf), 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            break;
        }

        action_t a = classify_packet(buf, (size_t)n, ctx->rules, ctx->rule_count);
        if (a == ACTION_FORWARD || a == ACTION_ALLOW) {
            // For demo, forward as-is.
            // In a real forwarder, rewrite L2/L3 headers and recompute checksums.
            if (send_packet(ctx->tx_sock, ctx->ifindex_out, ctx->mac_out, buf, (size_t)n) < 0) {
                perror("sendto");
            }
        }
    }

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <in_if> <out_if>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    ctx_t ctx;
    memset(&ctx, 0, sizeof(ctx));

    ctx.ifindex_in = get_ifindex(argv[1]);
    ctx.ifindex_out = get_ifindex(argv[2]);
    if (!ctx.ifindex_in || !ctx.ifindex_out) {
        fprintf(stderr, "Invalid interface name(s)\n");
        return 1;
    }

    if (get_if_mac(argv[2], ctx.mac_out) < 0) {
        perror("get_if_mac");
        return 1;
    }

    ctx.rx_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    ctx.tx_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (ctx.rx_sock < 0 || ctx.tx_sock < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_ll addr_in = {
        .sll_family = AF_PACKET,
        .sll_protocol = htons(ETH_P_ALL),
        .sll_ifindex = ctx.ifindex_in
    };

    if (bind(ctx.rx_sock, (struct sockaddr *)&addr_in, sizeof(addr_in)) < 0) {
        perror("bind");
        return 1;
    }

    // Example rule set: allow TCP/443, drop everything else
    rule_t rules[] = {
        {
            .src_ip = 0, .src_mask = 0,
            .dst_ip = 0, .dst_mask = 0,
            .proto = IPPROTO_TCP,
            .src_pmin = 0, .src_pmax = 0,
            .dst_pmin = 443, .dst_pmax = 443,
            .action = ACTION_FORWARD
        }
    };
    ctx.rules = rules;
    ctx.rule_count = sizeof(rules) / sizeof(rules[0]);

    pthread_t th;
    if (pthread_create(&th, NULL, rx_loop, &ctx) != 0) {
        perror("pthread_create");
        return 1;
    }

    pthread_join(th, NULL);
    close(ctx.rx_sock);
    close(ctx.tx_sock);
    return 0;
}
