- drops packets that don’t match a simple allowlist policy
- passes allowed packets onward at line rate

### xdp_filter.c
```c
// SPDX-License-Identifier: GPL-2.0
#include <linux/bpf.h>
#include <linux/ipv6.h>
#include <linux/ip.h>
#include <linux/if_ether.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __u32);   // IPv4 src address (network byte order)
    __type(value, __u8);  // dummy
} allowlist SEC(".maps");

static __always_inline int parse_ethernet(void *data, void *data_end, __u16 *eth_proto, void **l3_hdr)
{
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return -1;

    *eth_proto = bpf_ntohs(eth->h_proto);
    *l3_hdr = (void *)(eth + 1);
    return 0;
}

SEC("xdp")
int xdp_filter_prog(struct xdp_md *ctx)
{
    void *data_end = (void *)(long)ctx->data_end;
    void *data     = (void *)(long)ctx->data;
    __u16 eth_proto;
    void *l3;
    __u8 *allowed;

    if (parse_ethernet(data, data_end, &eth_proto, &l3) < 0)
        return XDP_DROP;

    if (eth_proto != ETH_P_IP)
        return XDP_PASS;

    struct iphdr *iph = l3;
    if ((void *)(iph + 1) > data_end)
        return XDP_DROP;

    if (iph->protocol != IPPROTO_UDP)
        return XDP_PASS; // only filter UDP here; adjust as needed

    if (iph->ihl < 5)
        return XDP_DROP;

    // Check source IP against allowlist
    allowed = bpf_map_lookup_elem(&allowlist, &iph->saddr);
    if (!allowed)
        return XDP_DROP;

    // Ensure UDP header exists
    void *udp_hdr = (void *)iph + (iph->ihl * 4);
    if (udp_hdr + sizeof(struct udphdr) > data_end)
        return XDP_DROP;

    return XDP_PASS;
}

char LICENSE[] SEC("license") = "GPL";
