## Rust example: packet filter + forwarder skeleton

```rust
use std::sync::Arc;
use std::time::Instant;

/// Minimal packet representation.
/// In a real system this would wrap a DMA-backed mbuf / frame.
#[derive(Clone)]
pub struct Packet {
    pub data: Vec<u8>,
    pub len: usize,
}

impl Packet {
    pub fn new(data: Vec<u8>) -> Self {
        let len = data.len();
        Self { data, len }
    }

    #[inline(always)]
    pub fn as_slice(&self) -> &[u8] {
        &self.data[..self.len]
    }
}

/// Fast filter decision.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum Action {
    Allow,
    Drop,
}

/// Packet filter trait.
pub trait PacketFilter: Send + Sync {
    fn evaluate(&self, pkt: &Packet) -> Action;
}

/// Example rule-based filter:
/// - Drop empty frames
/// - Allow only IPv4 TCP/UDP packets
/// - Optional port-based allowlist
pub struct BasicFilter {
    pub allowed_ports: [bool; 65536],
}

impl BasicFilter {
    pub fn new() -> Self {
        Self {
            allowed_ports: [false; 65536],
        }
    }

    pub fn allow_port(&mut self, port: u16) {
        self.allowed_ports[port as usize] = true;
    }

    #[inline(always)]
    fn parse_ipv4_l4_ports(&self, packet: &[u8]) -> Option<(u16, u16)> {
        // Very small parser for Ethernet + IPv4 + TCP/UDP.
        // Assumes no VLAN tags and minimal validation for performance.
        if packet.len() < 14 + 20 {
            return None;
        }

        let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
        if ethertype != 0x0800 {
            return None; // not IPv4
        }

        let ip_start = 14;
        let ver_ihl = packet[ip_start];
        let ihl = (ver_ihl & 0x0f) as usize * 4;
        let version = ver_ihl >> 4;
        if version != 4 || ihl < 20 || packet.len() < ip_start + ihl + 4 {
            return None;
        }

        let proto = packet[ip_start + 9];
        let l4_start = ip_start + ihl;

        // TCP=6, UDP=17
        match proto {
            6 | 17 => {
                if packet.len() < l4_start + 4 {
                    return None;
                }
                let src = u16::from_be_bytes([packet[l4_start], packet[l4_start + 1]]);
                let dst = u16::from_be_bytes([packet[l4_start + 2], packet[l4_start + 3]]);
                Some((src, dst))
            }
            _ => None,
        }
    }
}

impl PacketFilter for BasicFilter {
    #[inline(always)]
    fn evaluate(&self, pkt: &Packet) -> Action {
        let bytes = pkt.as_slice();

        if bytes.is_empty() {
            return Action::Drop;
        }

        if let Some((src_port, dst_port)) = self.parse_ipv4_l4_ports(bytes) {
            if self.allowed_ports[src_port as usize] || self.allowed_ports[dst_port as usize] {
                Action::Allow
            } else {
                Action::Drop
            }
        } else {
            Action::Drop
        }
    }
}

/// NIC abstraction.
pub trait NicDevice {
    fn rx_batch(&mut self, out: &mut Vec<Packet>, max: usize) -> usize;
    fn tx_batch(&mut self, packets: &[Packet]) -> usize;
}

/// Simple in-memory mock NIC for testing.
pub struct MockNic {
    rx_queue: Vec<Packet>,
    tx_queue: Vec<Packet>,
}

impl MockNic {
    pub fn new() -> Self {
        Self {
            rx_queue: Vec::new(),
            tx_queue: Vec::new(),
        }
    }

    pub fn inject(&mut self, pkt: Packet) {
        self.rx_queue.push(pkt);
    }

    pub fn transmitted(&self) -> &[Packet] {
        &self.tx_queue
    }
}

impl NicDevice for MockNic {
    fn rx_batch(&mut self, out: &mut Vec<Packet>, max: usize) -> usize {
        let n = max.min(self.rx_queue.len());
        out.extend(self.rx_queue.drain(0..n));
        n
    }

    fn tx_batch(&mut self, packets: &[Packet]) -> usize {
        self.tx_queue.extend_from_slice(packets);
        packets.len()
    }
}

/// Packet processor: filter, then forward allowed packets.
pub struct PacketProcessor<F: PacketFilter, N: NicDevice> {
    filter: Arc<F>,
    nic: N,
    rx_buf: Vec<Packet>,
    tx_buf: Vec<Packet>,
    batch_size: usize,
}

impl<F: PacketFilter, N: NicDevice> PacketProcessor<F, N> {
    pub fn new(filter: Arc<F>, nic: N, batch_size: usize) -> Self {
        Self {
            filter,
            nic,
            rx_buf: Vec::with_capacity(batch_size),
            tx_buf: Vec::with_capacity(batch_size),
            batch_size,
        }
    }

    pub fn run_once(&mut self) -> (usize, usize) {
        self.rx_buf.clear();
        self.tx_buf.clear();

        let received = self.nic.rx_batch(&mut self.rx_buf, self.batch_size);

        for pkt in &self.rx_buf {
            if self.filter.evaluate(pkt) == Action::Allow {
                self.tx_buf.push(pkt.clone());
            }
        }

        let forwarded = self.nic.tx_batch(&self.tx_buf);
        (received, forwarded)
    }
}

fn build_test_ipv4_udp_packet(src_port: u16, dst_port: u16) -> Packet {
    // Ethernet(14) + IPv4(20) + UDP(8)
    let mut buf = vec![0u8; 42];

    // Ethernet header
    buf[12] = 0x08;
    buf[13] = 0x00; // IPv4

    // IPv4 header
    buf[14] = 0x45; // version=4 IHL=5
    buf[23] = 17;   // UDP
    // src/dst IPs left zeroed

    // UDP header
    let udp = 34;
    buf[udp..udp + 2].copy_from_slice(&src_port.to_be_bytes());
    buf[udp + 2..udp + 4].copy_from_slice(&dst_port.to_be_bytes());

    Packet::new(buf)
}

fn main() {
    let mut filter = BasicFilter::new();
    filter.allow_port(443);
    filter.allow_port(53);

    let filter = Arc::new(filter);

    let mut nic = MockNic::new();
