// Cargo.toml dependencies:
// mio = "0.8"

use mio::net::UdpSocket;
use mio::{Events, Interest, Poll, Token};
use std::io;
use std::net::SocketAddr;
use std::time::Duration;

const CLIENT: Token = Token(0);
const UPSTREAM: Token = Token(1);

fn parse_addr(s: &str) -> io::Result<SocketAddr> {
    s.parse::<SocketAddr>()
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))
}

fn main() -> io::Result<()> {
    let listen_addr = parse_addr("0.0.0.0:9000")?;
    let upstream_addr = parse_addr("127.0.0.1:9001")?;

    let mut poll = Poll::new()?;
    let mut events = Events::with_capacity(1024);

    let mut client_socket = UdpSocket::bind(listen_addr)?;
    let mut upstream_socket = UdpSocket::bind(parse_addr("0.0.0.0:0")?)?;

    poll.registry()
        .register(&mut client_socket, CLIENT, Interest::READABLE)?;
    poll.registry()
        .register(&mut upstream_socket, UPSTREAM, Interest::READABLE)?;

    let mut buf = [0u8; 2048];
    let mut last_client: Option<SocketAddr> = None;

    loop {
        poll.poll(&mut events, Some(Duration::from_millis(100)))?;

        for event in events.iter() {
            match event.token() {
                CLIENT => {
                    if event.is_readable() {
                        loop {
                            match client_socket.recv_from(&mut buf) {
                                Ok((n, src)) => {
                                    last_client = Some(src);
                                    let _ = upstream_socket.send_to(&buf[..n], upstream_addr);
                                }
                                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => break,
                                Err(e) => return Err(e),
                            }
                        }
                    }
                }
                UPSTREAM => {
                    if event.is_readable() {
                        loop {
                            match upstream_socket.recv_from(&mut buf) {
                                Ok((n, _src)) => {
                                    if let Some(client) = last_client {
                                        let _ = client_socket.send_to(&buf[..n], client);
                                    }
                                }
                                Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => break,
                                Err(e) => return Err(e),
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }
}
```

