    #[inline(always)]
    fn parse_ipv4_dst(pkt: &Packet) -> Option<[u8; 4]> {
        // Minimal IPv4 header parsing assuming Ethernet + IPv4
        if pkt.data.len() < 34 {
            return None;
        }
        // Ethernet type at bytes 12..14
        let ethertype = u16::from_be_bytes([pkt.data[12], pkt.data[13]]);
        if ethertype != 0x0800 {
            return None;
        }
        // IPv4 dst at offset 30..34 for standard 14-byte Ethernet header
        Some([pkt.data[30], pkt.data[31], pkt.data[32], pkt.data[33]])
    }

    #[inline(always)]
    fn parse_l4_dst_port(pkt: &Packet) -> Option<u16> {
        if pkt.data.len() < 38 {
            return None;
        }
        let ethertype = u16::from_be_bytes([pkt.data[12], pkt.data[13]]);
        if ethertype != 0x0800 {
            return None;
        }

        let ihl = (pkt.data[14] & 0x0f) as usize * 4;
        let l4_offset = 14 + ihl;
        if pkt.data.len() < l4_offset + 4 {
            return None;
        }

        Some(u16::from_be_bytes([
            pkt.data[l4_offset + 2],
            pkt.data[l4_offset + 3],
        ]))
    }
}

