use std::net::IpAddr;
use std::time::Instant;

#[derive(Clone, Debug)]
pub struct Packet {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8, // e.g. 6=TCP, 17=UDP
    pub payload: Vec<u8>,
    pub timestamp_ns: u64,
}

#[derive(Clone, Debug)]
pub struct FilterRule {
    pub allow: bool,
    pub src_ip: Option<IpAddr>,
    pub dst_ip: Option<IpAddr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub protocol: Option<u8>,
}

impl FilterRule {
    pub fn matches(&self, p: &Packet) -> bool {
        self.src_ip.map_or(true, |v| v == p.src_ip)
            && self.dst_ip.map_or(true, |v| v == p.dst_ip)
            && self.src_port.map_or(true, |v| v == p.src_port)
            && self.dst_port.map_or(true, |v| v == p.dst_port)
            && self.protocol.map_or(true, |v| v == p.protocol)
    }
}

pub trait PacketSource {
    fn recv_batch(&mut self, max: usize) -> Vec<Packet>;
}

pub trait PacketSink {
    fn send_batch(&mut self, packets: &[Packet]) -> usize;
}

pub struct PacketProcessor {
    rules: Vec<FilterRule>,
    default_allow: bool,
}

impl PacketProcessor {
    pub fn new(rules: Vec<FilterRule>, default_allow: bool) -> Self {
        Self { rules, default_allow }
    }

    pub fn classify(&self, p: &Packet) -> bool {
        for rule in &self.rules {
            if rule.matches(p) {
                return rule.allow;
            }
        }
        self.default_allow
    }

    pub fn process_batch<P: PacketSource, S: PacketSink>(
        &self,
        source: &mut P,
        sink: &mut S,
        batch_size: usize,
    ) -> (usize, usize) {
        let packets = source.recv_batch(batch_size);
        let mut forwarded = Vec::with_capacity(packets.len());

        for pkt in packets {
            if self.classify(&pkt) {
                forwarded.push(pkt);
            }
        }

        let sent = sink.send_batch(&forwarded);
        (forwarded.len(), sent)
    }
}

// Example in-memory source/sink for testing
pub struct MemorySource {
    pub queue: Vec<Packet>,
}

impl PacketSource for MemorySource {
    fn recv_batch(&mut self, max: usize) -> Vec<Packet> {
        let n = max.min(self.queue.len());
        self.queue.drain(0..n).collect()
    }
}

pub struct MemorySink {
    pub received: Vec<Packet>,
}

impl PacketSink for MemorySink {
    fn send_batch(&mut self, packets: &[Packet]) -> usize {
        self.received.extend_from_slice(packets);
        packets.len()
    }
}

