        .dst_port = 0,
        .proto = 6, // TCP
        .action = ACTION_DROP
    };

    if (add_rule(deny_example) != 0) {
        fprintf(stderr, "Failed to add rule\n");
        return 1;
    }

    pthread_t tid;
    if (pthread_create(&tid, NULL, worker_thread, NULL) != 0) {
        fprintf(stderr, "Failed to start worker thread\n");
        return 1;
    }

    pthread_join(tid, NULL);
    return 0;
}
