## `src/packet.rs`

A very lightweight packet parser for Ethernet + IPv4 + TCP/UDP.

```rust
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy)]
pub struct EthernetHeader {
    pub ethertype: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct Ipv4Header {
    pub src: Ipv4Addr,
    pub dst: Ipv4Addr,
    pub protocol: u8,
    pub header_len: usize,
}

#[derive(Debug, Clone, Copy)]
pub struct TcpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct UdpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

pub struct Packet<'a> {
    pub data: &'a [u8],
}

impl<'a> Packet<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Self { data }
    }

    pub fn ethernet(&self) -> Option<EthernetHeader> {
        if self.data.len() < 14 {
            return None;
        }
        let ethertype = u16::from_be_bytes([self.data[12], self.data[13]]);
        Some(EthernetHeader { ethertype })
    }

    pub fn ipv4(&self) -> Option<Ipv4Header> {
        if self.data.len() < 34 {
            return None;
        }
        let eth = self.ethernet()?;
        if eth.ethertype != 0x0800 {
            return None;
        }

        let ihl = (self.data[14] & 0x0f) as usize * 4;
        if self.data.len() < 14 + ihl {
            return None;
        }

        let protocol = self.data[23];
        let src = Ipv4Addr::new(self.data[26], self.data[27], self.data[28], self.data[29]);
        let dst = Ipv4Addr::new(self.data[30], self.data[31], self.data[32], self.data[33]);

        Some(Ipv4Header {
            src,
            dst,
            protocol,
            header_len: ihl,
        })
    }

    pub fn tcp(&self) -> Option<TcpHeader> {
        let ip = self.ipv4()?;
        if ip.protocol != 6 {
            return None;
        }
        let offset = 14 + ip.header_len;
        if self.data.len() < offset + 4 {
            return None;
        }
        let src_port = u16::from_be_bytes([self.data[offset], self.data[offset + 1]]);
        let dst_port = u16::from_be_bytes([self.data[offset + 2], self.data[offset + 3]]);
        Some(TcpHeader { src_port, dst_port })
    }

    pub fn udp(&self) -> Option<UdpHeader> {
        let ip = self.ipv4()?;
        if ip.protocol != 17 {
            return None;
        }
        let offset = 14 + ip.header_len;
        if self.data.len() < offset + 4 {
            return None;
        }
        let src_port = u16::from_be_bytes([self.data[offset], self.data[offset + 1]]);
        let dst_port = u16::from_be_bytes([self.data[offset + 2], self.data[offset + 3]]);
        Some(UdpHeader { src_port, dst_port })
    }
}
```

