## `src/filter.rs`

A simple low-overhead rule engine.

```rust
use crate::packet::Packet;
use std::net::Ipv4Addr;

#[derive(Debug, Clone)]
pub enum FilterAction {
    Allow,
    Drop,
}

#[derive(Debug, Clone)]
pub enum Rule {
    AllowAll,
    DropAll,
    AllowIp { src: Option<Ipv4Addr>, dst: Option<Ipv4Addr> },
    AllowTcpPort { port: u16 },
    DropTcpPort { port: u16 },
    AllowUdpPort { port: u16 },
    DropUdpPort { port: u16 },
}

#[derive(Default)]
pub struct FilterEngine {
    pub rules: Vec<Rule>,
}

impl FilterEngine {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    pub fn evaluate(&self, packet: &Packet<'_>) -> FilterAction {
        for rule in &self.rules {
            match rule {
                Rule::AllowAll => return FilterAction::Allow,
                Rule::DropAll => return FilterAction::Drop,
                Rule::AllowIp { src, dst } => {
                    if let Some(ipv4) = packet.ipv4() {
                        let src_ok = src.map_or(true, |s| s == ipv4.src);
                        let dst_ok = dst.map_or(true, |d| d == ipv4.dst);
                        if src_ok && dst_ok {
                            return FilterAction::Allow;
                        }
                    }
                }
                Rule::AllowTcpPort { port } => {
                    if let Some(tcp) = packet.tcp() {
                        if tcp.src_port == *port || tcp.dst_port == *port {
                            return FilterAction::Allow;
                        }
                    }
                }
                Rule::DropTcpPort { port } => {
                    if let Some(tcp) = packet.tcp() {
                        if tcp.src_port == *port || tcp.dst_port == *port {
                            return FilterAction::Drop;
                        }
                    }
                }
                Rule::AllowUdpPort { port } => {
                    if let Some(udp) = packet.udp() {
                        if udp.src_port == *port || udp.dst_port == *port {
                            return FilterAction::Allow;
                        }
                    }
                }
                Rule::DropUdpPort { port } => {
                    if let Some(udp) = packet.udp() {
                        if udp.src_port == *port || udp.dst_port == *port {
                            return FilterAction::Drop;
                        }
                    }
                }
            }
        }

        FilterAction::Drop
    }
}
```

