## `src/forwarder.rs`

Minimal forwarding using raw sockets on Linux. This is a starting point and may need elevated privileges.

```rust
use anyhow::{Context, Result};
use libc::{c_void, sockaddr_ll, socklen_t};
use std::ffi::CString;
use std::io;
use std::mem;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};
use std::ptr;

pub struct RawSocket {
    fd: OwnedFd,
}

impl RawSocket {
    pub fn open(interface: &str) -> Result<Self> {
        unsafe {
            let proto = u16::to_be(0x0003); // ETH_P_ALL
            let fd = libc::socket(libc::AF_PACKET, libc::SOCK_RAW, proto as i32);
            if fd < 0 {
                return Err(io::Error::last_os_error()).context("failed to open raw socket");
            }

            let fd = OwnedFd::from_raw_fd(fd);

            let ifname = CString::new(interface)?;
            let ifindex = libc::if_nametoindex(ifname.as_ptr());
            if ifindex == 0 {
                return Err(io::Error::last_os_error()).context("failed to resolve interface index");
            }

            let mut addr: sockaddr_ll = mem::zeroed();
            addr.sll_family = libc::AF_PACKET as u16;
            addr.sll_ifindex = ifindex as i32;
            addr.sll_protocol = proto;

            let rc = libc::bind(
                fd.as_raw_fd(),
                &addr as *const sockaddr_ll as *const libc::sockaddr,
                mem::size_of::<sockaddr_ll>() as socklen_t,
            );
            if rc < 0 {
                return Err(io::Error::last_os_error()).context("failed to bind raw socket");
            }

            Ok(Self { fd })
        }
    }

    pub fn recv(&self, buf: &mut [u8]) -> Result<usize> {
        let n = unsafe {
            libc::recv(
                self.fd.as_raw_fd(),
                buf.as_mut_ptr() as *mut c_void,
                buf.len(),
                0,
            )
        };
        if n < 0 {
            return Err(io::Error::last_os_error()).context("recv failed");
        }
        Ok(n as usize)
    }

    pub fn send(&self, buf: &[u8]) -> Result<usize> {
        let n = unsafe {
            libc::send(
                self.fd.as_raw_fd(),
                buf.as_ptr() as *const c_void,
                buf.len(),
                0,
            )
        };
        if n < 0 {
            return Err(io::Error::last_os_error()).context("send failed");
        }
        Ok(n as usize)
    }
}
```

