## `src/main.rs`

The main event loop.

```rust
mod filter;
mod forwarder;
mod metrics;
mod packet;

use anyhow::Result;
use filter::{FilterAction, FilterEngine, Rule};
use forwarder::RawSocket;
use metrics::Metrics;
use packet::Packet;
use std::sync::Arc;

fn main() -> Result<()> {
    // Example rules: allow TCP 443, drop UDP 53, then default drop
    let filter = FilterEngine::new(vec![
        Rule::AllowTcpPort { port: 443 },
        Rule::DropUdpPort { port: 53 },
    ]);

    let rx = RawSocket::open("eth0")?;
    let tx = RawSocket::open("eth1")?;

    let metrics = Arc::new(Metrics::new());
    let mut buf = vec![0u8; 2048];

    loop {
        let n = rx.recv(&mut buf)?;
        metrics.inc_received();

        let pkt = Packet::new(&buf[..n]);

        match filter.evaluate(&pkt) {
            FilterAction::Allow => {
                metrics.inc_allowed();
                let sent = tx.send(&buf[..n])?;
                if sent == n {
                    metrics.inc_forwarded();
                }
            }
            FilterAction::Drop => {
                metrics.inc_dropped();
            }
        }
    }
}
```

