# filter.go

```go
package main

import (
	"net"

	"github.com/google/gopacket"
	"github.com/google/gopacket/layers"
)

type Decision int

const (
	DecisionDrop Decision = iota
	DecisionPass
	DecisionForward
)

type PacketMeta struct {
	Proto     string
	SrcIP     net.IP
	DstIP     net.IP
	SrcPort   uint16
	DstPort   uint16
	Payload   []byte
	HasL4     bool
	IsIPv4    bool
	IsIPv6    bool
}

func ExtractMeta(packet gopacket.Packet) PacketMeta {
	meta := PacketMeta{}

	if netLayer := packet.NetworkLayer(); netLayer != nil {
		switch n := netLayer.(type) {
		case *layers.IPv4:
			meta.IsIPv4 = true
			meta.SrcIP = n.SrcIP
			meta.DstIP = n.DstIP
		case *layers.IPv6:
			meta.IsIPv6 = true
			meta.SrcIP = n.SrcIP
			meta.DstIP = n.DstIP
		}
	}

	if transport := packet.TransportLayer(); transport != nil {
		meta.HasL4 = true
		switch t := transport.(type) {
		case *layers.TCP:
			meta.Proto = "tcp"
			meta.SrcPort = uint16(t.SrcPort)
			meta.DstPort = uint16(t.DstPort)
		case *layers.UDP:
			meta.Proto = "udp"
			meta.SrcPort = uint16(t.SrcPort)
			meta.DstPort = uint16(t.DstPort)
		case *layers.ICMPv4:
			meta.Proto = "icmp"
		case *layers.ICMPv6:
			meta.Proto = "icmp"
		}
	}

	if app := packet.ApplicationLayer(); app != nil {
		meta.Payload = app.Payload()
	}

	return meta
}

func MatchRule(meta PacketMeta, rule FilterRule) bool {
	if rule.Protocol != "" && rule.Protocol != meta.Proto {
		return false
	}
	if rule.SrcIP != "" && (meta.SrcIP == nil || meta.SrcIP.String() != rule.SrcIP) {
		return false
	}
	if rule.DstIP != "" && (meta.DstIP == nil || meta.DstIP.String() != rule.DstIP) {
		return false
	}
	if rule.SrcPort != 0 && meta.SrcPort != rule.SrcPort {
		return false
	}
	if rule.DstPort != 0 && meta.DstPort != rule.DstPort {
		return false
	}
	if rule.Contains != "" {
		if len(meta.Payload) == 0 {
			return false
		}
		if !containsBytes(meta.Payload, []byte(rule.Contains)) {
			return false
		}
	}
	return true
}

func containsBytes(haystack, needle []byte) bool {
	if len(needle) == 0 {
		return true
	}
	if len(needle) > len(haystack) {
		return false
	}
	for i := 0; i <= len(haystack)-len(needle); i++ {
		match := true
		for j := range needle {
			if haystack[i+j] != needle[j] {
				match = false
				break
			}
		}
		if match {
			return true
		}
	}
	return false
}

func Decide(meta PacketMeta, rules []FilterRule) Decision {
	for _, rule := range rules {
		if MatchRule(meta, rule) {
			switch rule.Action {
			case "drop":
				return DecisionDrop
			case "forward":
				return DecisionForward
			default:
				return DecisionPass
			}
		}
	}
	return DecisionPass
}
