package main

import (
	"log"

	"github.com/google/gopacket"
	"github.com/google/gopacket/pcap"
)

type Service struct {
	cfg       Config
	handle    *pcap.Handle
	forwarder *Forwarder
}

func NewService(cfg Config) (*Service, error) {
	handle, err := pcap.OpenLive(cfg.InterfaceName, cfg.SnapLen, cfg.Promiscuous, cfg.Timeout)
	if err != nil {
		return nil, err
	}

	return &Service{
		cfg:       cfg,
		handle:    handle,
		forwarder: NewForwarder(cfg.ForwardEnabled),
	}, nil
}

func (s *Service) Close() {
	if s.handle != nil {
		s.handle.Close()
	}
}

func (s *Service) Run() error {
	packetSource := gopacket.NewPacketSource(s.handle, s.handle.LinkType())
	packetSource.NoCopy = true

	log.Printf("service started on interface=%s", s.cfg.InterfaceName)

	for packet := range packetSource.Packets() {
		meta := ExtractMeta(packet)
		decision := Decide(meta, s.cfg.Rules)

		switch decision {
		case DecisionDrop:
			continue
		case DecisionForward:
			if err := s.forwarder.Forward(packet); err != nil {
				log.Printf("forward error: %v", err)
			}
		case DecisionPass:
			// Pass-through or future processing
		}
	}

	return nil
}
