use std::net::IpAddr;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};

#[derive(Clone, Debug)]
pub enum Decision {
    Allow,
    Deny,
}

#[derive(Clone, Debug)]
pub struct PacketMeta {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Clone, Debug)]
pub struct Rule {
    pub src_ip: Option<IpAddr>,
    pub dst_ip: Option<IpAddr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub protocol: Option<u8>,
    pub decision: Decision,
}

impl Rule {
    pub fn matches(&self, pkt: &PacketMeta) -> bool {
        self.src_ip.map_or(true, |ip| ip == pkt.src_ip)
            && self.dst_ip.map_or(true, |ip| ip == pkt.dst_ip)
            && self.src_port.map_or(true, |p| p == pkt.src_port)
            && self.dst_port.map_or(true, |p| p == pkt.dst_port)
            && self.protocol.map_or(true, |p| p == pkt.protocol)
    }
}

pub struct PolicyEngine {
    rules: Arc<Vec<Rule>>,
}

impl PolicyEngine {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules: Arc::new(rules),
        }
    }

    pub fn decide(&self, pkt: &PacketMeta) -> Decision {
        for rule in self.rules.iter() {
            if rule.matches(pkt) {
                return rule.decision.clone();
            }
        }
        Decision::Deny
    }
}

pub struct Metrics {
    pub allowed: AtomicU64,
    pub denied: AtomicU64,
    pub forwarded: AtomicU64,
    pub dropped: AtomicU64,
}

impl Metrics {
    pub fn new() -> Self {
        Self {
            allowed: AtomicU64::new(0),
            denied: AtomicU64::new(0),
            forwarded: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
        }
    }
}

pub struct Forwarder;

impl Forwarder {
    pub fn forward(&self, _pkt: &PacketMeta) -> Result<(), &'static str> {
        // Integrate with your approved egress mechanism here:
        // DPDK tx queue, AF_XDP tx, or a controlled UDP/TCP sender.
        Ok(())
    }
}

pub struct PacketService {
    engine: PolicyEngine,
    forwarder: Forwarder,
    metrics: Metrics,
}

impl PacketService {
    pub fn new(engine: PolicyEngine) -> Self {
        Self {
            engine,
            forwarder: Forwarder,
            metrics: Metrics::new(),
        }
    }

    pub fn handle_packet(&self, pkt: &PacketMeta) {
        match self.engine.decide(pkt) {
            Decision::Allow => {
                self.metrics.allowed.fetch_add(1, Ordering::Relaxed);
                if self.forwarder.forward(pkt).is_ok() {
                    self.metrics.forwarded.fetch_add(1, Ordering::Relaxed);
                } else {
                    self.metrics.dropped.fetch_add(1, Ordering::Relaxed);
                }
            }
            Decision::Deny => {
                self.metrics.denied.fetch_add(1, Ordering::Relaxed);
            }
        }
    }
}
