### Example: async TCP filtering proxy in Rust

```rust
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use std::net::SocketAddr;
use std::sync::Arc;

#[derive(Clone)]
struct Policy {
    allowed_prefixes: Vec<String>,
    upstream: SocketAddr,
}

impl Policy {
    fn allow(&self, first_bytes: &[u8]) -> bool {
        let s = match std::str::from_utf8(first_bytes) {
            Ok(v) => v,
            Err(_) => return false,
        };

        // Simple example: allow only HTTP methods / prefixes
        self.allowed_prefixes.iter().any(|p| s.starts_with(p))
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let listener = TcpListener::bind("0.0.0.0:8080").await?;

    let policy = Arc::new(Policy {
        allowed_prefixes: vec![
            "GET ".to_string(),
            "POST ".to_string(),
            "HEAD ".to_string(),
        ],
        upstream: "127.0.0.1:9000".parse()?,
    });

    loop {
        let (client, peer) = listener.accept().await?;
        let policy = policy.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_connection(client, peer, policy).await {
                eprintln!("connection error from {peer}: {e}");
            }
        });
    }
}

async fn handle_connection(
    mut client: TcpStream,
    peer: SocketAddr,
    policy: Arc<Policy>,
) -> anyhow::Result<()> {
    let mut buf = vec![0u8; 1024];
    let n = client.peek(&mut buf).await?;
    let inspected = &buf[..n];

    if !policy.allow(inspected) {
        eprintln!("blocked {peer}");
        client.write_all(b"HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\n\r\n").await?;
        return Ok(());
    }

    eprintln!("allowed {peer}");

    let mut upstream = TcpStream::connect(policy.upstream).await?;

    // Bidirectional relay
    let (mut cr, mut cw) = client.into_split();
    let (mut ur, mut uw) = upstream.into_split();

    let c2u = tokio::spawn(async move { tokio::io::copy(&mut cr, &mut uw).await });
    let u2c = tokio::spawn(async move { tokio::io::copy(&mut ur, &mut cw).await });

    let _ = tokio::try_join!(c2u, u2c);
    Ok(())
}
```

