```rust
use anyhow::{Context, Result};
use clap::Parser;
use crossbeam_channel::{bounded, Receiver, Sender};
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc,
};
use std::thread;
use std::time::Duration;

#[derive(Parser, Debug)]
#[command(name = "ultra_low_latency_net")]
struct Args {
    #[arg(long)]
    in_iface: String,

    #[arg(long)]
    out_iface: String,

    #[arg(long)]
    allow_src_ip: Option<Ipv4Addr>,

    #[arg(long)]
    allow_dst_ip: Option<Ipv4Addr>,

    #[arg(long)]
    allow_src_port: Option<u16>,

    #[arg(long)]
    allow_dst_port: Option<u16>,

    #[arg(long, default_value_t = false)]
    allow_tcp: bool,

    #[arg(long, default_value_t = false)]
    allow_udp: bool,
}

#[derive(Clone, Debug)]
struct FilterRule {
    allow_src_ip: Option<Ipv4Addr>,
    allow_dst_ip: Option<Ipv4Addr>,
    allow_src_port: Option<u16>,
    allow_dst_port: Option<u16>,
    allow_tcp: bool,
    allow_udp: bool,
}

impl FilterRule {
    fn matches(&self, packet: &[u8]) -> bool {
        let eth = match EthernetPacket::new(packet) {
            Some(p) => p,
            None => return false,
        };

        match eth.get_ethertype() {
            EtherTypes::Ipv4 => {}
            _ => return false,
        }

        let ip = match Ipv4Packet::new(eth.payload()) {
            Some(p) => p,
            None => return false,
        };

        if let Some(src) = self.allow_src_ip {
            if ip.get_source() != src {
                return false;
            }
        }

        if let Some(dst) = self.allow_dst_ip {
            if ip.get_destination() != dst {
                return false;
            }
        }

        match ip.get_next_level_protocol() {
            IpNextHeaderProtocols::Tcp => {
                if !self.allow_tcp && self.allow_udp {
                    return false;
                }
                if let Some(tcp) = TcpPacket::new(ip.payload()) {
                    if let Some(src_port) = self.allow_src_port {
                        if tcp.get_source() != src_port {
                            return false;
                        }
                    }
                    if let Some(dst_port) = self.allow_dst_port {
                        if tcp.get_destination() != dst_port {
                            return false;
                        }
                    }
                    true
                } else {
                    false
                }
            }
            IpNextHeaderProtocols::Udp => {
                if !self.allow_udp && self.allow_tcp {
                    return false;
                }
                if let Some(udp) = UdpPacket::new(ip.payload()) {
                    if let Some(src_port) = self.allow_src_port {
                        if udp.get_source() != src_port {
                            return false;
                        }
                    }
                    if let Some(dst_port) = self.allow_dst_port {
                        if udp.get_destination() != dst_port {
                            return false;
                        }
                    }
                    true
                } else {
                    false
                }
            }
            _ => false,
        }
    }
}

struct Stats {
    received: AtomicU64,
    forwarded: AtomicU64,
    dropped: AtomicU64,
}

impl Stats {
    fn new() -> Self {
        Self {
            received: AtomicU64::new(0),
            forwarded: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
        }
    }
}

fn open_interface(name: &str) -> Result<datalink::NetworkInterface> {
    let interfaces = datalink::interfaces();
    interfaces
        .into_iter()
        .find(|iface| iface.name == name)
        .context(format!("interface '{}' not found", name))
}

fn open_channel(
    iface: &datalink::NetworkInterface,
) -> Result<(Box<dyn DataLinkSender>, Box<dyn DataLinkReceiver>)> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(1));
    config.write_buffer_size = 2048;
    config.read_buffer_size = 2048;

    match datalink::channel(iface, config)? {
        Channel::Ethernet(tx, rx) => Ok((tx, rx)),
        _ => anyhow::bail!("unsupported channel type"),
    }
}

fn capture_loop(
    mut rx: Box<dyn DataLinkReceiver>,
    tx_packets: Sender<Vec<u8>>,
    stats: Arc<Stats>,
) {
    loop {
        match rx.next() {
            Ok(packet) => {
                stats.received.fetch_add(1, Ordering::Relaxed);
                let buf = packet.to_vec();
                if tx_packets.try_send(buf).is_err() {
                    stats.dropped.fetch_add(1, Ordering::Relaxed);
                }
            }
            Err(_) => {
                // idle / timeout; continue polling
                continue;
            }
        }
    }
}

fn forward_loop(
    mut tx: Box<dyn DataLinkSender>,
    rx_packets: Receiver<Vec<u8>>,
    rule: FilterRule,
    stats: Arc<Stats>,
) {
    while let Ok(packet) = rx_packets.recv() {
        if rule.matches(&packet) {
            let sent = tx.send_to(&packet, None);
            if sent.is_some() {
                stats.forwarded.fetch_add(1, Ordering::Relaxed);
            } else {
                stats.dropped.fetch_add(1, Ordering::Relaxed);
            }
        } else {
            stats.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn stats_loop(stats: Arc<Stats>) {
    loop {
        thread::sleep(Duration::from_secs(1));
        let received = stats.received.load(Ordering::Relaxed);
        let forwarded = stats.forwarded.load(Ordering::Relaxed);
        let dropped = stats.dropped.load(Ordering::Relaxed);

        eprintln!(
            "stats: received={}, forwarded={}, dropped={}",
            received, forwarded, dropped
        );
    }
}

fn main() -> Result<()> {
    let args = Args::parse();

    let rule = FilterRule {
        allow_src_ip: args.allow_src_ip,
        allow_dst_ip: args.allow_dst_ip,
        allow_src_port: args.allow_src_port,
        allow_dst_port: args.allow_dst_port,
        allow_tcp: args.allow_tcp,
        allow_udp: args.allow_udp,
    };

    let in_iface = open_interface(&args.in_iface)?;
    let out_iface = open_interface(&args.out_iface)?;

    let (tx_out, rx_out) = bounded::<Vec<u8>>(1024);

    let stats = Arc::new(Stats::new());

    let (_, in_rx) = open_channel(&in_iface)?;
    let (out_tx, _) = open_channel(&out_iface)?;

    let stats_for_capture = stats.clone();
    let capture_thread = thread::spawn(move || capture_loop(in_rx, tx_out, stats_for_capture));

    let stats_for_forward = stats.clone();
    let forward_thread = thread::spawn(move || forward_loop(out_tx, rx_out, rule, stats_for_forward));

    let stats_for_stats = stats.clone();
    let stats_thread = thread::spawn(move || stats_loop(stats_for_stats));

    capture_thread.join().ok();
    forward_thread.join().ok();
    stats_thread.join().ok();

    Ok(())
}
```

