## `src/filter.rs`

```rust
use std::net::Ipv4Addr;

use pnet::packet::{
    ethernet::{EtherTypes, EthernetPacket},
    ip::IpNextHeaderProtocols,
    ipv4::Ipv4Packet,
    tcp::TcpPacket,
    udp::UdpPacket,
    Packet,
};

#[derive(Clone, Debug)]
pub struct PacketFilter {
    allowed_src_ips: Vec<Ipv4Addr>,
    allowed_dst_ports: Vec<u16>,
    drop_non_ipv4: bool,
}

impl PacketFilter {
    pub fn new(allowed_src_ips: Vec<Ipv4Addr>, allowed_dst_ports: Vec<u16>, drop_non_ipv4: bool) -> Self {
        Self {
            allowed_src_ips,
            allowed_dst_ports,
            drop_non_ipv4,
        }
    }

    pub fn should_forward(&self, frame: &[u8]) -> bool {
        let eth = match EthernetPacket::new(frame) {
            Some(pkt) => pkt,
            None => return false,
        };

        if eth.get_ethertype() != EtherTypes::Ipv4 {
            return !self.drop_non_ipv4;
        }

        let ipv4 = match Ipv4Packet::new(eth.payload()) {
            Some(pkt) => pkt,
            None => return false,
        };

        let src_ip = ipv4.get_source();
        if !self.allowed_src_ips.is_empty() && !self.allowed_src_ips.contains(&src_ip) {
            return false;
        }

        match ipv4.get_next_level_protocol() {
            IpNextHeaderProtocols::Tcp => {
                let tcp = match TcpPacket::new(ipv4.payload()) {
                    Some(pkt) => pkt,
                    None => return false,
                };
                let dst_port = tcp.get_destination();
                self.port_allowed(dst_port)
            }
            IpNextHeaderProtocols::Udp => {
                let udp = match UdpPacket::new(ipv4.payload()) {
                    Some(pkt) => pkt,
                    None => return false,
                };
                let dst_port = udp.get_destination();
                self.port_allowed(dst_port)
            }
            _ => false,
        }
    }

    fn port_allowed(&self, port: u16) -> bool {
        if self.allowed_dst_ports.is_empty() {
            true
        } else {
            self.allowed_dst_ports.contains(&port)
        }
    }
}
```

