use anyhow::{Context, Result};
use pnet::datalink::{self, Channel, DataLinkSender, NetworkInterface};

pub struct Forwarder {
    tx: Box<dyn DataLinkSender>,
}

impl Forwarder {
    pub fn new(iface_name: &str) -> Result<Self> {
        let iface = datalink::interfaces()
            .into_iter()
            .find(|i| i.name == iface_name)
            .context("egress interface not found")?;

        let (tx, _rx) = match datalink::channel(&iface, Default::default())
            .context("failed to open datalink channel")?
        {
            Channel::Ethernet(tx, rx) => (tx, rx),
            _ => anyhow::bail!("unsupported channel type"),
        };

        Ok(Self { tx })
    }

    pub fn send(&mut self, frame: &[u8]) -> Result<()> {
        match self.tx.send_to(frame, None) {
            Some(Ok(())) => Ok(()),
            Some(Err(e)) => Err(e.into()),
            None => anyhow::bail!("failed to send packet"),
        }
    }
}
