## `src/service.rs`

```rust
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc,
};

use anyhow::{Context, Result};
use crossbeam_channel::{bounded, Receiver, Sender};
use log::{debug, error, info};
use pnet::datalink::{self, Channel, DataLinkReceiver, NetworkInterface};

use crate::{config::Config, filter::PacketFilter, forward::Forwarder};

pub struct PacketService {
    config: Config,
    filter: PacketFilter,
    shutdown: Arc<AtomicBool>,
    forwarded: Arc<AtomicU64>,
    dropped: Arc<AtomicU64>,
}

impl PacketService {
    pub fn new(config: Config) -> Self {
        let filter = PacketFilter::new(
            config.allowed_src_ips.clone(),
            config.allowed_dst_ports.clone(),
            config.drop_non_ipv4,
        );

        Self {
            config,
            filter,
            shutdown: Arc::new(AtomicBool::new(false)),
            forwarded: Arc::new(AtomicU64::new(0)),
            dropped: Arc::new(AtomicU64::new(0)),
        }
    }

    pub fn run(&self) -> Result<()> {
        let ingress = self.open_ingress(&self.config.ingress_iface)?;
        let mut forwarder = Forwarder::new(&self.config.egress_iface)?;

        let (tx, rx) = bounded::<Vec<u8>>(4096);

        let shutdown = self.shutdown.clone();
        let stats_fwd = self.forwarded.clone();
        let stats_drop = self.dropped.clone();
        let filter = self.filter.clone();

        let worker = std::thread::spawn(move || {
            while !shutdown.load(Ordering::Relaxed) {
                match rx.recv() {
                    Ok(frame) => {
                        if filter.should_forward(&frame) {
                            if let Err(e) = forwarder.send(&frame) {
                                error!("send error: {e}");
                                stats_drop.fetch_add(1, Ordering::Relaxed);
                            } else {
                                stats_fwd.fetch_add(1, Ordering::Relaxed);
                            }
                        } else {
                            stats_drop.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                    Err(_) => break,
                }
            }
        });

        self.capture_loop(ingress, tx)?;

        let _ = worker.join();
        Ok(())
    }

    fn open_ingress(&self, iface_name: &str) -> Result<Box<dyn DataLinkReceiver>> {
        let iface = datalink::interfaces()
            .into_iter()
            .find(|i| i.name == iface_name)
            .context("ingress interface not found")?;

        let (_tx, rx) = match datalink::channel(&iface, Default::default())
            .context("failed to open ingress channel")?
        {
            Channel::Ethernet(tx, rx) => (tx, rx),
            _ => anyhow::bail!("unsupported channel type"),
        };

        Ok(rx)
    }

    fn capture_loop(&self, mut rx: Box<dyn DataLinkReceiver>, tx: Sender<Vec<u8>>) -> Result<()> {
        info!(
            "starting packet service ingress={} egress={}",
            self.config.ingress_iface, self.config.egress_iface
        );

        loop {
            match rx.next() {
                Ok(frame) => {
                    let mut buf = Vec::with_capacity(frame.len());
                    buf.extend_from_slice(frame);

                    if tx.try_send(buf).is_err() {
                        self.dropped.fetch_add(1, Ordering::Relaxed);
                    }
                }
                Err(e) => {
                    debug!("capture error: {e}");
                }
            }
        }
    }

    pub fn stats(&self) -> (u64, u64) {
        (
            self.forwarded.load(Ordering::Relaxed),
            self.dropped.load(Ordering::Relaxed),
        )
    }
}
