```rust
use crate::config::Config;

pub fn parse_mac(s: &str) -> anyhow::Result<[u8; 6]> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() != 6 {
        anyhow::bail!("invalid MAC address: {s}");
    }

    let mut mac = [0u8; 6];
    for (i, p) in parts.iter().enumerate() {
        mac[i] = u8::from_str_radix(p, 16)?;
    }
    Ok(mac)
}

#[inline(always)]
pub fn ethertype(frame: &[u8]) -> Option<u16> {
    if frame.len() < 14 {
        return None;
    }
    Some(u16::from_be_bytes([frame[12], frame[13]]))
}

#[inline(always)]
pub fn dst_mac(frame: &[u8]) -> Option<[u8; 6]> {
    if frame.len() < 6 {
        return None;
    }
    let mut mac = [0u8; 6];
    mac.copy_from_slice(&frame[0..6]);
    Some(mac)
}

#[inline(always)]
pub fn should_forward(cfg: &Config, frame: &[u8]) -> bool {
    if frame.len() < 14 {
        return false;
    }

    if let Some(dst) = dst_mac(frame) {
        for m in &cfg.drop_dst_macs {
            if let Ok(drop_mac) = parse_mac(m) {
                if dst == drop_mac {
                    return false;
                }
            }
        }
    }

    if !cfg.allow_ethertypes.is_empty() {
        if let Some(et) = ethertype(frame) {
            if !cfg.allow_ethertypes.contains(&et) {
                return false;
            }
        } else {
            return false;
        }
    }

    true
}

#[inline(always)]
pub fn rewrite_dst_mac(frame: &mut [u8], new_mac: [u8; 6]) -> bool {
    if frame.len() < 6 {
        return false;
    }
    frame[0..6].copy_from_slice(&new_mac);
    true
}
