## `src/forward.rs`

```rust
use anyhow::Context;
use nix::sys::socket::{
    AddressFamily, MsgFlags, SockFlag, SockProtocol, SockType, recv, send,
    socket,
};
use nix::unistd::close;
use std::os::fd::RawFd;

pub struct RawIface {
    fd: RawFd,
    pub ifname: String,
}

impl RawIface {
    pub fn open(ifname: &str) -> anyhow::Result<Self> {
        // AF_PACKET raw socket, ETH_P_ALL
        let fd = socket(
            AddressFamily::Packet,
            SockType::Raw,
            SockFlag::empty(),
            SockProtocol::EthAll,
        )
        .context("socket(AF_PACKET, SOCK_RAW)")?;

        // In a real implementation, bind to interface index here.
        // This initial version assumes the host/network setup routes appropriately.

        Ok(Self {
            fd,
            ifname: ifname.to_string(),
        })
    }

    pub fn recv_frame(&self, buf: &mut [u8]) -> anyhow::Result<usize> {
        let n = recv(self.fd, buf, MsgFlags::MSG_DONTWAIT)?;
        Ok(n)
    }

    pub fn send_frame(&self, buf: &[u8]) -> anyhow::Result<usize> {
        let n = send(self.fd, buf, MsgFlags::MSG_DONTWAIT)?;
        Ok(n)
    }
}

impl Drop for RawIface {
    fn drop(&mut self) {
        let _ = close(self.fd);
    }
}
