## `src/main.rs`

```rust
mod config;
mod filter;
mod forward;
mod stats;

use anyhow::Context;
use config::Config;
use filter::{parse_mac, rewrite_dst_mac, should_forward};
use forward::RawIface;
use stats::Stats;
use std::sync::Arc;
use std::sync::atomic::Ordering;
use std::thread;
use std::time::Duration;

fn main() -> anyhow::Result<()> {
    let cfg = Config::load("config.toml").context("loading config")?;
    let stats = Arc::new(Stats::default());

    let ingress = RawIface::open(&cfg.ingress_if)?;
    let egress = RawIface::open(&cfg.egress_if)?;

    let rewrite_mac = match &cfg.rewrite_dst_mac {
        Some(m) => Some(parse_mac(m)?),
        None => None,
    };

    let stats_thread = {
        let stats = stats.clone();
        thread::spawn(move || loop {
            thread::sleep(Duration::from_secs(1));
            let (rxp, txp, dp, rxb, txb) = stats.snapshot();
            eprintln!(
                "stats: rx_pkts={} tx_pkts={} dropped_pkts={} rx_bytes={} tx_bytes={}",
                rxp, txp, dp, rxb, txb
            );
        })
    };

    let mut rx_buf = vec![0u8; 2048];
    let mut tx_buf = vec![0u8; 2048];

    loop {
        match ingress.recv_frame(&mut rx_buf) {
            Ok(n) if n > 0 => {
                stats.rx_pkts.fetch_add(1, Ordering::Relaxed);
                stats.rx_bytes.fetch_add(n as u64, Ordering::Relaxed);

                let frame = &rx_buf[..n];

                if !should_forward(&cfg, frame) {
                    stats.dropped_pkts.fetch_add(1, Ordering::Relaxed);
                    continue;
                }

                tx_buf[..n].copy_from_slice(frame);
                let mut tx_frame = &mut tx_buf[..n];

                if let Some(mac) = rewrite_mac {
                    let _ = rewrite_dst_mac(&mut tx_frame, mac);
                }

                match egress.send_frame(tx_frame) {
                    Ok(sent) if sent > 0 => {
                        stats.tx_pkts.fetch_add(1, Ordering::Relaxed);
                        stats.tx_bytes.fetch_add(sent as u64, Ordering::Relaxed);
                    }
                    _ => {
                        stats.dropped_pkts.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
            Ok(_) => {}
            Err(_) => {
                // Non-blocking socket: backoff very slightly
                std::hint::spin_loop();
            }
        }
    }

    #[allow(unreachable_code)]
    {
        let _ = stats_thread.join();
        Ok(())
    }
}
```

