## `src/packet.rs`

```rust
#[derive(Clone, Copy, Debug)]
pub struct EthernetHeader {
    pub ethertype: u16,
}

#[derive(Clone, Copy, Debug)]
pub struct Ipv4Header {
    pub protocol: u8,
    pub src: [u8; 4],
    pub dst: [u8; 4],
    pub header_len: usize,
}

#[derive(Clone, Copy, Debug)]
pub struct TcpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

#[derive(Clone, Copy, Debug)]
pub struct UdpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

pub const ETHERTYPE_IPV4: u16 = 0x0800;
pub const IPPROTO_TCP: u8 = 6;
pub const IPPROTO_UDP: u8 = 17;

pub fn parse_ethernet(pkt: &[u8]) -> Option<EthernetHeader> {
    if pkt.len() < 14 {
        return None;
    }
    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    Some(EthernetHeader { ethertype })
}

pub fn parse_ipv4(pkt: &[u8]) -> Option<Ipv4Header> {
    if pkt.len() < 34 {
        return None;
    }
    let ihl = (pkt[14] & 0x0f) as usize * 4;
    if pkt.len() < 14 + ihl || ihl < 20 {
        return None;
    }

    Some(Ipv4Header {
        protocol: pkt[23],
        src: [pkt[26], pkt[27], pkt[28], pkt[29]],
        dst: [pkt[30], pkt[31], pkt[32], pkt[33]],
        header_len: ihl,
    })
}

pub fn parse_tcp(pkt: &[u8], ip_header_len: usize) -> Option<TcpHeader> {
    let offset = 14 + ip_header_len;
    if pkt.len() < offset + 20 {
        return None;
    }
    Some(TcpHeader {
        src_port: u16::from_be_bytes([pkt[offset], pkt[offset + 1]]),
        dst_port: u16::from_be_bytes([pkt[offset + 2], pkt[offset + 3]]),
    })
}

pub fn parse_udp(pkt: &[u8], ip_header_len: usize) -> Option<UdpHeader> {
    let offset = 14 + ip_header_len;
    if pkt.len() < offset + 8 {
        return None;
    }
    Some(UdpHeader {
        src_port: u16::from_be_bytes([pkt[offset], pkt[offset + 1]]),
        dst_port: u16::from_be_bytes([pkt[offset + 2], pkt[offset + 3]]),
    })
}
