## `src/filter.rs`

```rust
use crate::config::Config;
use crate::packet::{parse_ethernet, parse_ipv4, parse_tcp, parse_udp, ETHERTYPE_IPV4, IPPROTO_TCP, IPPROTO_UDP};

#[derive(Debug, Clone)]
pub struct FilterEngine {
    udp_port: Option<u16>,
    tcp_port: Option<u16>,
}

impl FilterEngine {
    pub fn new(cfg: &Config) -> Self {
        Self {
            udp_port: cfg.udp_port,
            tcp_port: cfg.tcp_port,
        }
    }

    pub fn matches(&self, pkt: &[u8]) -> bool {
        let eth = match parse_ethernet(pkt) {
            Some(e) => e,
            None => return false,
        };

        if eth.ethertype != ETHERTYPE_IPV4 {
            return false;
        }

        let ip = match parse_ipv4(pkt) {
            Some(h) => h,
            None => return false,
        };

        match ip.protocol {
            IPPROTO_UDP => {
                if let Some(port) = self.udp_port {
                    if let Some(udp) = parse_udp(pkt, ip.header_len) {
                        return udp.dst_port == port;
                    }
                }
                false
            }
            IPPROTO_TCP => {
                if let Some(port) = self.tcp_port {
                    if let Some(tcp) = parse_tcp(pkt, ip.header_len) {
                        return tcp.dst_port == port;
                    }
                }
                false
            }
            _ => false,
        }
    }
}
