## `src/forward.rs`

```rust
use anyhow::{Context, Result};
use libc::{c_int, sockaddr_ll, AF_PACKET, ETH_P_ALL, SOCK_RAW};
use std::ffi::CString;
use std::mem::size_of;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};

pub struct PacketSocket {
    fd: OwnedFd,
}

impl PacketSocket {
    pub fn open(interface: &str) -> Result<Self> {
        unsafe {
            let fd = libc::socket(AF_PACKET, SOCK_RAW, (ETH_P_ALL as u16).to_be() as c_int);
            if fd < 0 {
                return Err(std::io::Error::last_os_error()).context("socket(AF_PACKET) failed");
            }

            let sock = OwnedFd::from_raw_fd(fd);

            let ifname = CString::new(interface)?;
            let ifindex = libc::if_nametoindex(ifname.as_ptr());
            if ifindex == 0 {
                return Err(std::io::Error::last_os_error())
                    .context(format!("if_nametoindex({interface}) failed"));
            }

            let mut sll: sockaddr_ll = std::mem::zeroed();
            sll.sll_family = AF_PACKET as u16;
            sll.sll_protocol = (ETH_P_ALL as u16).to_be();
            sll.sll_ifindex = ifindex as i32;

            let ret = libc::bind(
                sock.as_raw_fd(),
                &sll as *const sockaddr_ll as *const libc::sockaddr,
                size_of::<sockaddr_ll>() as u32,
            );
            if ret < 0 {
                return Err(std::io::Error::last_os_error()).context("bind(AF_PACKET) failed");
            }

            Ok(Self { fd: sock })
        }
    }

    pub fn send(&self, pkt: &[u8]) -> Result<usize> {
        let ret = unsafe {
            libc::send(
                self.fd.as_raw_fd(),
                pkt.as_ptr() as *const libc::c_void,
                pkt.len(),
                0,
            )
        };
        if ret < 0 {
            Err(std::io::Error::last_os_error()).context("send failed")
        } else {
            Ok(ret as usize)
        }
    }

    pub fn recv_into(&self, buf: &mut [u8]) -> Result<usize> {
        let ret = unsafe {
            libc::recv(
                self.fd.as_raw_fd(),
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
                0,
            )
        };
        if ret < 0 {
            Err(std::io::Error::last_os_error()).context("recv failed")
        } else {
            Ok(ret as usize)
        }
    }
}
```

