## `src/main.rs`

```rust
mod config;
mod filter;
mod forward;
mod packet;
mod stats;

use anyhow::Result;
use clap::Parser;
use config::Config;
use filter::FilterEngine;
use forward::PacketSocket;
use stats::Stats;
use std::sync::Arc;
use std::time::Duration;

fn main() -> Result<()> {
    let cfg = Config::parse();

    let filter = FilterEngine::new(&cfg);
    let ingress = PacketSocket::open(&cfg.ingress)?;
    let egress = PacketSocket::open(&cfg.egress)?;
    let stats = Arc::new(Stats::default());

    if cfg.verbose {
        eprintln!("Starting fastnet with config: {:?}", cfg);
    }

    let mut buf = vec![0u8; 2048];

    loop {
        let n = match ingress.recv_into(&mut buf) {
            Ok(n) => n,
            Err(e) => {
                eprintln!("recv error: {e:?}");
                stats.inc_dropped();
                continue;
            }
        };

        stats.inc_captured();

        let pkt = &buf[..n];
        if filter.matches(pkt) {
            stats.inc_matched();
            match egress.send(pkt) {
                Ok(_) => stats.inc_forwarded(),
                Err(e) => {
                    eprintln!("forward error: {e:?}");
                    stats.inc_dropped();
                }
            }
        } else {
            stats.inc_dropped();
        }
    }
}
