```rust
use libc::{
    bind, close, if_nametoindex, recv, send, socket, sockaddr, sockaddr_ll, AF_PACKET, ETH_P_ALL,
    MSG_DONTWAIT, PACKET_HOST, SOCK_RAW,
};
use std::cmp::min;
use std::ffi::CString;
use std::io;
use std::mem::{size_of, zeroed};
use std::os::unix::io::RawFd;
use std::ptr;

const MAX_PACKET_SIZE: usize = 2048;
const ETH_HDR_LEN: usize = 14;
const IPV4_HDR_MIN_LEN: usize = 20;
const TCP_HDR_MIN_LEN: usize = 20;
const UDP_HDR_LEN: usize = 8;

#[derive(Clone, Copy, Debug)]
enum Action {
    Drop,
    Forward(u32), // output interface index
    Pass,
}

#[derive(Clone, Copy, Debug)]
struct Rule {
    ethertype: Option<u16>,
    ipv4_proto: Option<u8>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    action: Action,
}

impl Rule {
    fn matches(&self, pkt: &PacketView) -> bool {
        if let Some(ethertype) = self.ethertype {
            if pkt.ethertype != Some(ethertype) {
                return false;
            }
        }
        if let Some(proto) = self.ipv4_proto {
            if pkt.ip_proto != Some(proto) {
                return false;
            }
        }
        if let Some(src_port) = self.src_port {
            if pkt.src_port != Some(src_port) {
                return false;
            }
        }
        if let Some(dst_port) = self.dst_port {
            if pkt.dst_port != Some(dst_port) {
                return false;
            }
        }
        true
    }
}

#[derive(Clone, Copy, Debug, Default)]
struct PacketView {
    ethertype: Option<u16>,
    ip_proto: Option<u8>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
}

struct Dataplane {
    input_fd: RawFd,
    output_fd: RawFd,
    input_ifindex: u32,
    output_ifindex: u32,
    rules: Vec<Rule>,
}

impl Dataplane {
    fn new(input_iface: &str, output_iface: &str, rules: Vec<Rule>) -> io::Result<Self> {
        let input_ifindex = iface_index(input_iface)?;
        let output_ifindex = iface_index(output_iface)?;

        let input_fd = make_socket()?;
        let output_fd = make_socket()?;

        bind_socket(input_fd, input_ifindex)?;
        bind_socket(output_fd, output_ifindex)?;

        Ok(Self {
            input_fd,
            output_fd,
            input_ifindex,
            output_ifindex,
            rules,
        })
    }

    fn run(&self) -> io::Result<()> {
        let mut buf = [0u8; MAX_PACKET_SIZE];

        loop {
            let n = unsafe {
                recv(
                    self.input_fd,
                    buf.as_mut_ptr() as *mut _,
                    buf.len(),
                    MSG_DONTWAIT,
                )
            };

            if n < 0 {
                let err = io::Error::last_os_error();
                if err.kind() == io::ErrorKind::WouldBlock {
                    continue;
                }
                return Err(err);
            }

            if n == 0 {
                continue;
            }

            let n = n as usize;
            let pkt = parse_packet(&buf[..n]);

            let mut action = Action::Drop;

            for rule in &self.rules {
                if rule.matches(&pkt) {
                    action = rule.action;
                    break;
                }
            }

            match action {
                Action::Drop => {
                    // intentionally drop
                }
                Action::Pass => {
                    // forward on same interface by default
                    self.forward_packet(&buf[..n], &self.output_fd)?;
                }
                Action::Forward(_) => {
                    self.forward_packet(&buf[..n], &self.output_fd)?;
                }
            }
        }
    }

    fn forward_packet(&self, pkt: &[u8], fd: &RawFd) -> io::Result<()> {
        let sent = unsafe { send(*fd, pkt.as_ptr() as *const _, min(pkt.len(), MAX_PACKET_SIZE), 0) };
        if sent < 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(())
    }
}

fn make_socket() -> io::Result<RawFd> {
    let proto = (ETH_P_ALL as u16).to_be() as i32;
    let fd = unsafe { socket(AF_PACKET, SOCK_RAW, proto) };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(fd)
}

fn iface_index(name: &str) -> io::Result<u32> {
    let cstr = CString::new(name).unwrap();
    let idx = unsafe { if_nametoindex(cstr.as_ptr()) };
    if idx == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(idx)
}

fn bind_socket(fd: RawFd, ifindex: u32) -> io::Result<()> {
    let mut addr: sockaddr_ll = unsafe { zeroed() };
    addr.sll_family = AF_PACKET as u16;
    addr.sll_protocol = (ETH_P_ALL as u16).to_be();
    addr.sll_ifindex = ifindex as i32;

    let ret = unsafe {
        bind(
            fd,
            &addr as *const sockaddr_ll as *const sockaddr,
            size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn parse_packet(pkt: &[u8]) -> PacketView {
    if pkt.len() < ETH_HDR_LEN {
        return PacketView::default();
    }

    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    let mut view = PacketView {
        ethertype: Some(ethertype),
        ..Default::default()
    };

    // IPv4
    if ethertype == 0x0800 && pkt.len() >= ETH_HDR_LEN + IPV4_HDR_MIN_LEN {
        let ihl = (pkt[14] & 0x0f) as usize * 4;
        if pkt.len() < ETH_HDR_LEN + ihl {
            return view;
        }

        let ip_proto = pkt[23];
        view.ip_proto = Some(ip_proto);

        let l4_offset = ETH_HDR_LEN + ihl;

        match ip_proto {
            6 => {
                // TCP
                if pkt.len() >= l4_offset + TCP_HDR_MIN_LEN {
                    view.src_port =
                        Some(u16::from_be_bytes([pkt[l4_offset], pkt[l4_offset + 1]]));
                    view.dst_port =
                        Some(u16::from_be_bytes([pkt[l4_offset + 2], pkt[l4_offset + 3]]));
                }
            }
            17 => {
                // UDP
                if pkt.len() >= l4_offset + UDP_HDR_LEN {
                    view.src_port =
                        Some(u16::from_be_bytes([pkt[l4_offset], pkt[l4_offset + 1]]));
                    view.dst_port =
                        Some(u16::from_be_bytes([pkt[l4_offset + 2], pkt[l4_offset + 3]]));
                }
            }
            _ => {}
        }
    }

    view
}

impl Drop for Dataplane {
    fn drop(&mut self) {
        unsafe {
            close(self.input_fd);
            close(self.output_fd);
        }
    }
}

fn main() -> io::Result<()> {
    // Example rules:
    // - Drop TCP port 22
    // - Forward UDP port 53
    // - Pass everything else
    let rules = vec![
        Rule {
            ethertype: Some(0x0800),
            ipv4_proto: Some(6),
            src_port: None,
            dst_port: Some(22),
            action: Action::Drop,
        },
        Rule {
            ethertype: Some(0x0800),
            ipv4_proto: Some(17),
            src_port: None,
            dst_port: Some(53),
            action: Action::Pass,
        },
        Rule {
            ethertype: None,
            ipv4_proto: None,
            src_port: None,
            dst_port: None,
            action: Action::Pass,
        },
    ];

    let input_iface = "eth0";
    let output_iface = "eth1";

    let dp = Dataplane::new(input_iface, output_iface, rules)?;
    println!("Running dataplane from {} to {}", input_iface, output_iface);
    dp.run()
}
```

