use anyhow::{Context, Result};
use bytes::BytesMut;
use crossbeam_channel::{bounded, Receiver, Sender};
use parking_lot::RwLock;
use serde::Deserialize;
use std::{
    fs,
    net::{SocketAddr, UdpSocket},
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc,
    },
    thread,
    time::{Duration, Instant},
};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    listen_addr: String,
    forward_addrs: Vec<String>,
    max_packet_size: usize,
    worker_threads: usize,
    rules: Vec<RuleConfig>,
}

#[derive(Debug, Deserialize, Clone)]
struct RuleConfig {
    action: String, // "allow" or "drop"
    src_ip: Option<String>,
    dst_ip: Option<String>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    protocol: Option<String>, // "udp" for this initial implementation
}

#[derive(Clone)]
enum Action {
    Allow,
    Drop,
}

#[derive(Clone)]
struct Rule {
    action: Action,
    src_ip: Option<String>,
    dst_ip: Option<String>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    protocol: Option<String>,
}

impl From<RuleConfig> for Rule {
    fn from(cfg: RuleConfig) -> Self {
        let action = match cfg.action.to_lowercase().as_str() {
            "allow" => Action::Allow,
            _ => Action::Drop,
        };
        Self {
            action,
            src_ip: cfg.src_ip,
            dst_ip: cfg.dst_ip,
            src_port: cfg.src_port,
            dst_port: cfg.dst_port,
            protocol: cfg.protocol,
        }
    }
}

#[derive(Default)]
struct Metrics {
    received: AtomicU64,
    allowed: AtomicU64,
    dropped: AtomicU64,
    forwarded: AtomicU64,
    errors: AtomicU64,
}

struct Packet {
    data: BytesMut,
    src: SocketAddr,
    dst: SocketAddr,
}

struct FilterEngine {
    rules: Vec<Rule>,
}

impl FilterEngine {
    fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    fn evaluate(&self, pkt: &Packet) -> bool {
        // Initial semantics:
        // - first matching rule wins
        // - default deny if no rule matches
        for rule in &self.rules {
            if self.matches(rule, pkt) {
                return matches!(rule.action, Action::Allow);
            }
        }
        false
    }

    fn matches(&self, rule: &Rule, pkt: &Packet) -> bool {
        if let Some(ref src_ip) = rule.src_ip {
            if pkt.src.ip().to_string() != *src_ip {
                return false;
            }
        }
        if let Some(ref dst_ip) = rule.dst_ip {
            if pkt.dst.ip().to_string() != *dst_ip {
                return false;
            }
        }
        if let Some(src_port) = rule.src_port {
            if pkt.src.port() != src_port {
                return false;
            }
        }
        if let Some(dst_port) = rule.dst_port {
            if pkt.dst.port() != dst_port {
                return false;
            }
        }
        if let Some(ref proto) = rule.protocol {
            if proto.to_lowercase() != "udp" {
                return false;
            }
        }
        true
    }
}

fn load_config(path: &str) -> Result<Config> {
    let raw = fs::read_to_string(path).context("failed to read config")?;
    let cfg: Config = toml::from_str(&raw).context("failed to parse config")?;
    Ok(cfg)
}

fn packet_receiver(
    listen: SocketAddr,
    tx: Sender<Packet>,
    max_packet_size: usize,
    metrics: Arc<Metrics>,
) -> Result<()> {
    let socket = UdpSocket::bind(listen).context("failed to bind listen socket")?;
    socket
        .set_nonblocking(false)
        .context("failed to set blocking mode")?;

    loop {
        let mut buf = BytesMut::with_capacity(max_packet_size);
        buf.resize(max_packet_size, 0);

        let (size, src) = socket.recv_from(&mut buf).context("recv_from failed")?;
        let dst = socket.local_addr().context("local_addr failed")?;

        buf.truncate(size);

        metrics.received.fetch_add(1, Ordering::Relaxed);

        let pkt = Packet { data: buf, src, dst };

        if tx.send(pkt).is_err() {
            metrics.errors.fetch_add(1, Ordering::Relaxed);
            break;
        }
    }

    Ok(())
}

fn worker_loop(
    rx: Receiver<Packet>,
    engine: Arc<RwLock<FilterEngine>>,
    forwarders: Arc<Vec<UdpSocket>>,
    metrics: Arc<Metrics>,
) {
    while let Ok(pkt) = rx.recv() {
        let allowed = engine.read().evaluate(&pkt);

        if allowed {
            metrics.allowed.fetch_add(1, Ordering::Relaxed);

            for sock in forwarders.iter() {
                if let Err(_) = sock.send(&pkt.data) {
                    metrics.errors.fetch_add(1, Ordering::Relaxed);
                } else {
                    metrics.forwarded.fetch_add(1, Ordering::Relaxed);
                }
            }
        } else {
            metrics.dropped.fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn main() -> Result<()> {
    let cfg = load_config("config.toml")?;

    let rules = cfg.rules.into_iter().map(Rule::from).collect::<Vec<_>>();
    let engine = Arc::new(RwLock::new(FilterEngine::new(rules)));
    let metrics = Arc::new(Metrics::default());

    let listen_addr: SocketAddr = cfg.listen_addr.parse().context("invalid listen_addr")?;

    let (tx, rx) = bounded::<Packet>(1024);

    let mut forward_sockets = Vec::new();
    for fwd in &cfg.forward_addrs {
        let addr: SocketAddr = fwd.parse().context("invalid forward address")?;
        let sock = UdpSocket::bind("0.0.0.0:0").context("failed to bind forward socket")?;
        sock.connect(addr).context("failed to connect forward socket")?;
        forward_sockets.push(sock);
    }
    let forwarders = Arc::new(forward_sockets);

    {
        let tx_clone = tx.clone();
        let metrics_clone = metrics.clone();
        let max_packet_size = cfg.max_packet_size;
        thread::spawn(move || {
            if let Err(e) = packet_receiver(listen_addr, tx_clone, max_packet_size, metrics_clone) {
                eprintln!("receiver error: {e:#}");
            }
        });
    }

    for _ in 0..cfg.worker_threads.max(1) {
        let rx_clone = rx.clone();
        let engine_clone = engine.clone();
        let forwarders_clone = forwarders.clone();
        let metrics_clone = metrics.clone();

        thread::spawn(move || {
            worker_loop(rx_clone, engine_clone, forwarders_clone, metrics_clone);
        });
    }

    let metrics_clone = metrics.clone();
    let start = Instant::now();

    loop {
        thread::sleep(Duration::from_secs(5));
        let elapsed = start.elapsed().as_secs_f64();

        let received = metrics_clone.received.load(Ordering::Relaxed);
        let allowed = metrics_clone.allowed.load(Ordering::Relaxed);
        let dropped = metrics_clone.dropped.load(Ordering::Relaxed);
        let forwarded = metrics_clone.forwarded.load(Ordering::Relaxed);
        let errors = metrics_clone.errors.load(Ordering::Relaxed);

        println!(
            "uptime={:.1}s received={} allowed={} dropped={} forwarded={} errors={}",
            elapsed, received, allowed, dropped, forwarded, errors
        );
    }
}
