use bytes::BytesMut;
use crossbeam::queue::ArrayQueue;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

const MAX_PACKET_SIZE: usize = 2048;
const QUEUE_SIZE: usize = 8192;

#[derive(Clone, Debug)]
pub struct Packet {
    pub data: BytesMut,
}

impl Packet {
    pub fn from_bytes(bytes: &[u8]) -> Self {
        let mut data = BytesMut::with_capacity(bytes.len());
        data.extend_from_slice(bytes);
        Self { data }
    }

    pub fn len(&self) -> usize {
        self.data.len()
    }
}

#[derive(Clone, Copy, Debug)]
pub enum Action {
    Drop,
    Accept,
    Forward(u16), // output port
}

#[derive(Clone, Debug)]
pub struct FilterRule {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub proto: Option<u8>, // e.g. 6 TCP, 17 UDP
    pub action: Action,
}

impl FilterRule {
    pub fn matches(&self, packet: &Packet) -> bool {
        let hdr = match ParsedHeaders::parse(&packet.data) {
            Some(h) => h,
            None => return false,
        };

        if let Some(ip) = self.src_ip {
            if hdr.src_ip != Some(ip) {
                return false;
            }
        }
        if let Some(ip) = self.dst_ip {
            if hdr.dst_ip != Some(ip) {
                return false;
            }
        }
        if let Some(port) = self.src_port {
            if hdr.src_port != Some(port) {
                return false;
            }
        }
        if let Some(port) = self.dst_port {
            if hdr.dst_port != Some(port) {
                return false;
            }
        }
        if let Some(proto) = self.proto {
            if hdr.proto != Some(proto) {
                return false;
            }
        }

        true
    }
}

#[derive(Default, Debug)]
pub struct ParsedHeaders {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub proto: Option<u8>,
}

impl ParsedHeaders {
    pub fn parse(packet: &[u8]) -> Option<Self> {
        // Minimal Ethernet + IPv4 + TCP/UDP parsing
        if packet.len() < 14 + 20 {
            return None;
        }

        let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
        if ethertype != 0x0800 {
            return None; // only IPv4 supported in this starter
        }

        let ip_offset = 14;
        let ihl = (packet[ip_offset] & 0x0f) as usize * 4;
        if packet.len() < ip_offset + ihl + 8 {
            return None;
        }

        let proto = packet[ip_offset + 9];
        let src_ip = Ipv4Addr::new(
            packet[ip_offset + 12],
            packet[ip_offset + 13],
            packet[ip_offset + 14],
            packet[ip_offset + 15],
        );
        let dst_ip = Ipv4Addr::new(
            packet[ip_offset + 16],
            packet[ip_offset + 17],
            packet[ip_offset + 18],
            packet[ip_offset + 19],
        );

        let l4_offset = ip_offset + ihl;
        let (src_port, dst_port) = match proto {
            6 | 17 => {
                if packet.len() < l4_offset + 4 {
                    return None;
                }
                let sp = u16::from_be_bytes([packet[l4_offset], packet[l4_offset + 1]]);
                let dp = u16::from_be_bytes([packet[l4_offset + 2], packet[l4_offset + 3]]);
                (Some(sp), Some(dp))
            }
            _ => (None, None),
        };

        Some(Self {
            src_ip: Some(src_ip),
            dst_ip: Some(dst_ip),
            src_port,
            dst_port,
            proto: Some(proto),
        })
    }
}

pub struct PacketFilter {
    rules: Vec<FilterRule>,
}

impl PacketFilter {
    pub fn new(rules: Vec<FilterRule>) -> Self {
        Self { rules }
    }

    pub fn evaluate(&self, packet: &Packet) -> Action {
        for rule in &self.rules {
            if rule.matches(packet) {
                return rule.action;
            }
        }
        Action::Drop
    }
}

pub struct Forwarder {
    pub default_port: u16,
}

impl Forwarder {
    pub fn decide(&self, action: Action) -> Option<u16> {
        match action {
            Action::Drop => None,
            Action::Accept => Some(self.default_port),
            Action::Forward(port) => Some(port),
        }
    }
}

pub struct NetworkService {
    rx_queue: Arc<ArrayQueue<Packet>>,
    tx_queue: Arc<ArrayQueue<Packet>>,
    filter: PacketFilter,
    forwarder: Forwarder,
}

impl NetworkService {
    pub fn new(rules: Vec<FilterRule>, default_port: u16) -> Self {
        Self {
            rx_queue: Arc::new(ArrayQueue::new(QUEUE_SIZE)),
            tx_queue: Arc::new(ArrayQueue::new(QUEUE_SIZE)),
            filter: PacketFilter::new(rules),
            forwarder: Forwarder { default_port },
        }
    }

    pub fn rx_handle(&self) -> Arc<ArrayQueue<Packet>> {
        self.rx_queue.clone()
    }

    pub fn tx_handle(&self) -> Arc<ArrayQueue<Packet>> {
        self.tx_queue.clone()
    }

    pub fn run(&self) {
        loop {
            while let Some(packet) = self.rx_queue.pop() {
                let action = self.filter.evaluate(&packet);
                if let Some(_port) = self.forwarder.decide(action) {
                    // In a real implementation, send to proper NIC port/queue here.
                    // For now, push to tx_queue.
                    let _ = self.tx_queue.push(packet);
                }
            }

            // Keep latency low; in production you’d likely poll busy-loop or use
            // a tuned hybrid strategy depending on hardware and load.
            thread::yield_now();
        }
    }
}

fn main() {
    let rules = vec![
        FilterRule {
            src_ip: Some(Ipv4Addr::new(10, 0, 0, 1)),
            dst_ip: None,
            src_port: None,
            dst_port: Some(443),
            proto: Some(6),
            action: Action::Forward(1),
        },
        FilterRule {
            src_ip: Some(Ipv4Addr::new(192, 168, 1, 10)),
            dst_ip: None,
            src_port: None,
            dst_port: None,
            proto: None,
            action: Action::Drop,
        },
    ];

    let service = NetworkService::new(rules, 0);

    let rx = service.rx_handle();
    let tx = service.tx_handle();

    // Simulated packet producer
    let producer = thread::spawn(move || {
        loop {
            let fake_packet = make_fake_ipv4_tcp_packet();
            let _ = rx.push(Packet::from_bytes(&fake_packet));
            thread::sleep(Duration::from_micros(50));
        }
    });

    // Simulated consumer
    let consumer = thread::spawn(move || {
        loop {
            if let Some(pkt) = tx.pop() {
                println!("Forwarded packet: {} bytes", pkt.len());
            } else {
                thread::yield_now();
            }
        }
    });

    service.run();

    let _ = producer.join();
    let _ = consumer.join();
}

fn make_fake_ipv4_tcp_packet() -> Vec<u8> {
    // Minimal synthetic Ethernet + IPv4 + TCP packet
    let mut pkt = vec![0u8; 14 + 20 + 20];

    // Ethernet type = IPv4
    pkt[12] = 0x08;
    pkt[13] = 0x00;

    // IPv4 header
    pkt[14] = 0x45; // version + IHL
    pkt[23] = 6;    // TCP
    pkt[26] = 10;
    pkt[27] = 0;
    pkt[28] = 0;
    pkt[29] = 1;    // src 10.0.0.1
    pkt[30] = 93;
    pkt[31] = 184;
    pkt[32] = 216;
    pkt[33] = 34;   // dst 93.184.216.34

    // TCP ports
    let l4 = 14 + 20;
    pkt[l4] = 12345u16.to_be_bytes()[0];
    pkt[l4 + 1] = 12345u16.to_be_bytes()[1];
    pkt[l4 + 2] = 443u16.to_be_bytes()[0];
    pkt[l4 + 3] = 443u16.to_be_bytes()[1];

    pkt
}
