use std::collections::HashSet;
use std::net::IpAddr;

use crate::config::Config;

#[derive(Debug, Clone)]
pub struct Policy {
    allowed_src_ips: HashSet<IpAddr>,
    allowed_dst_ips: HashSet<IpAddr>,
    allowed_l4_ports: HashSet<u16>,
}

impl Policy {
    pub fn from_config(cfg: &Config) -> Result<Self, String> {
        let mut allowed_src_ips = HashSet::new();
        for s in &cfg.allowed_src_ips {
            allowed_src_ips.insert(s.parse().map_err(|e| format!("bad src ip {s}: {e}"))?);
        }

        let mut allowed_dst_ips = HashSet::new();
        for s in &cfg.allowed_dst_ips {
            allowed_dst_ips.insert(s.parse().map_err(|e| format!("bad dst ip {s}: {e}"))?);
        }

        let allowed_l4_ports = cfg.allowed_l4_ports.iter().copied().collect();

        Ok(Self {
            allowed_src_ips,
            allowed_dst_ips,
            allowed_l4_ports,
        })
    }

    pub fn permits(
        &self,
        src_ip: Option<IpAddr>,
        dst_ip: Option<IpAddr>,
        l4_port: Option<u16>,
    ) -> bool {
        if let Some(ip) = src_ip {
            if !self.allowed_src_ips.contains(&ip) {
                return false;
            }
        } else {
            return false;
        }

        if let Some(ip) = dst_ip {
            if !self.allowed_dst_ips.contains(&ip) {
                return false;
            }
        } else {
            return false;
        }

        if let Some(port) = l4_port {
            if !self.allowed_l4_ports.contains(&port) {
                return false;
            }
        } else {
            return false;
        }

        true
    }
}
