        metrics.received.fetch_add(1, std::sync::atomic::Ordering::Relaxed);

        let parsed = match parse_packet(&frame) {
            Some(p) => p,
            None => {
                metrics.parse_failed.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                metrics.dropped.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                warn!("parse failed; dropping");
                continue;
            }
        };

        if policy.permits(parsed.src_ip, parsed.dst_ip, parsed.l4_port) {
            metrics.allowed.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            forwarder.forward(&frame)?;
            metrics.forwarded.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        } else {
            metrics.dropped.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        }
    }

    let snap = metrics.snapshot();
    info!("metrics: {:?}", snap);

    Ok(())
}
```

