# Initial C/DPDK Skeleton

This is a simplified starting point, not production-complete, but enough to build from.

```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>
#include <arpa/inet.h>
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_malloc.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

enum action_type {
    ACTION_DROP = 0,
    ACTION_FORWARD = 1
};

struct filter_rule {
    enum action_type action;
    uint8_t proto;          // 6 = TCP, 17 = UDP, 0 = any
    uint32_t src_ip;
    uint32_t src_mask;
    uint32_t dst_ip;
    uint32_t dst_mask;
    uint16_t src_port;      // 0 = any
    uint16_t dst_port;      // 0 = any
    uint16_t out_port;
    int priority;
};

static struct filter_rule rules[128];
static int num_rules = 0;

static inline bool ip_match(uint32_t ip, uint32_t rule_ip, uint32_t mask) {
    return (ip & mask) == (rule_ip & mask);
}

static inline bool rule_matches(struct filter_rule *r,
                                uint8_t proto,
                                uint32_t src_ip,
                                uint32_t dst_ip,
                                uint16_t src_port,
                                uint16_t dst_port) {
    if (r->proto != 0 && r->proto != proto) return false;
    if (r->src_mask && !ip_match(src_ip, r->src_ip, r->src_mask)) return false;
    if (r->dst_mask && !ip_match(dst_ip, r->dst_ip, r->dst_mask)) return false;
    if (r->src_port != 0 && r->src_port != src_port) return false;
    if (r->dst_port != 0 && r->dst_port != dst_port) return false;
    return true;
}

static uint16_t process_packet(struct rte_mbuf *mbuf) {
    uint8_t *data = rte_pktmbuf_mtod(mbuf, uint8_t *);
    struct rte_ether_hdr *eth = (struct rte_ether_hdr *)data;

    if (rte_be_to_cpu_16(eth->ether_type) != RTE_ETHER_TYPE_IPV4)
        return UINT16_MAX;

    struct rte_ipv4_hdr *ipv4 = (struct rte_ipv4_hdr *)(eth + 1);
    uint8_t proto = ipv4->next_proto_id;
    uint32_t src_ip = rte_be_to_cpu_32(ipv4->src_addr);
    uint32_t dst_ip = rte_be_to_cpu_32(ipv4->dst_addr);

    uint16_t src_port = 0, dst_port = 0;
    uint8_t *l4 = (uint8_t *)ipv4 + ((ipv4->version_ihl & 0x0F) * 4);

    if (proto == IPPROTO_TCP) {
        struct rte_tcp_hdr *tcp = (struct rte_tcp_hdr *)l4;
        src_port = rte_be_to_cpu_16(tcp->src_port);
        dst_port = rte_be_to_cpu_16(tcp->dst_port);
    } else if (proto == IPPROTO_UDP) {
        struct rte_udp_hdr *udp = (struct rte_udp_hdr *)l4;
        src_port = rte_be_to_cpu_16(udp->src_port);
        dst_port = rte_be_to_cpu_16(udp->dst_port);
    }

    for (int i = 0; i < num_rules; i++) {
        if (rule_matches(&rules[i], proto, src_ip, dst_ip, src_port, dst_port)) {
            if (rules[i].action == ACTION_FORWARD)
                return rules[i].out_port;
            return UINT16_MAX;
        }
    }

    return UINT16_MAX; // default drop
}

int main(int argc, char **argv) {
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) {
        rte_exit(EXIT_FAILURE, "Failed to initialize DPDK EAL\n");
    }

    // TODO: Initialize ports, mempools, queues, and rules

    return 0;
}
```

