## `src/main.rs`

```rust
use anyhow::{Context, Result};
use clap::Parser;
use libc::{c_void, sockaddr_ll};
use nix::net::if_::if_nametoindex;
use nix::sys::socket::{
    bind, recvfrom, sendto, socket, AddressFamily, SockFlag, SockProtocol, SockType,
};
use nix::unistd::close;
use pnet_packet::ethernet::{EtherTypes, EthernetPacket};
use pnet_packet::ip::IpNextHeaderProtocols;
use pnet_packet::ipv4::Ipv4Packet;
use pnet_packet::tcp::TcpPacket;
use pnet_packet::udp::UdpPacket;
use std::mem;
use std::net::Ipv4Addr;
use std::os::unix::io::RawFd;
use std::sync::atomic::{AtomicU64, Ordering};

#[derive(Parser, Debug)]
struct Args {
    /// Input interface
    #[arg(long)]
    input: String,

    /// Output interface
    #[arg(long)]
    output: String,

    /// Optional allowlist IPv4 prefix, e.g. 10.0.0.0/8
    #[arg(long)]
    allow_cidr: Option<String>,

    /// Optional deny port list, comma-separated, e.g. 22,23,3389
    #[arg(long)]
    deny_ports: Option<String>,
}

#[derive(Default)]
struct Stats {
    rx_packets: AtomicU64,
    tx_packets: AtomicU64,
    dropped_packets: AtomicU64,
}

#[derive(Clone, Debug)]
struct FilterConfig {
    allow_net: Option<(Ipv4Addr, u8)>,
    deny_ports: Vec<u16>,
}

fn parse_cidr(s: &str) -> Result<(Ipv4Addr, u8)> {
    let (ip, prefix) = s
        .split_once('/')
        .context("CIDR must be in a.b.c.d/prefix format")?;
    let addr: Ipv4Addr = ip.parse().context("invalid IPv4 address")?;
    let prefix: u8 = prefix.parse().context("invalid prefix")?;
    if prefix > 32 {
        anyhow::bail!("prefix must be <= 32");
    }
    Ok((addr, prefix))
}

fn ip_in_cidr(ip: Ipv4Addr, network: Ipv4Addr, prefix: u8) -> bool {
    let ip_u32 = u32::from(ip);
    let net_u32 = u32::from(network);
    let mask = if prefix == 0 { 0 } else { u32::MAX << (32 - prefix) };
    (ip_u32 & mask) == (net_u32 & mask)
}

fn parse_port_list(s: &str) -> Result<Vec<u16>> {
    s.split(',')
        .filter(|x| !x.trim().is_empty())
        .map(|x| x.trim().parse().context("invalid port"))
        .collect()
}

fn open_raw_socket(iface: &str) -> Result<RawFd> {
    let fd = socket(
        AddressFamily::Packet,
        SockType::Raw,
        SockFlag::empty(),
        SockProtocol::EthAll,
    )
    .context("failed to open raw packet socket")?;

    let ifindex = if_nametoindex(iface).context("failed to resolve interface index")? as i32;

    let mut sll: sockaddr_ll = unsafe { mem::zeroed() };
    sll.sll_family = libc::AF_PACKET as u16;
    sll.sll_protocol = u16::to_be(libc::ETH_P_ALL as u16);
    sll.sll_ifindex = ifindex;

    let ret = unsafe {
        bind(
            fd,
            &*(&sll as *const sockaddr_ll as *const nix::sys::socket::SockAddr),
        )
    };

    if let Err(e) = ret {
        let _ = close(fd);
        return Err(e).context("failed to bind raw socket");
    }

    Ok(fd)
}

fn extract_flow_info(pkt: &[u8]) -> Option<(Ipv4Addr, Ipv4Addr, u16, u16, u8)> {
    let eth = EthernetPacket::new(pkt)?;
    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return None;
    }

    let ipv4 = Ipv4Packet::new(eth.payload())?;
    let src = ipv4.get_source();
    let dst = ipv4.get_destination();
    let proto = ipv4.get_next_level_protocol().0;

    let (src_port, dst_port) = match ipv4.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            let tcp = TcpPacket::new(ipv4.payload())?;
            (tcp.get_source(), tcp.get_destination())
        }
        IpNextHeaderProtocols::Udp => {
            let udp = UdpPacket::new(ipv4.payload())?;
            (udp.get_source(), udp.get_destination())
        }
        _ => (0, 0),
    };

    Some((src, dst, src_port, dst_port, proto))
}

fn should_forward(pkt: &[u8], cfg: &FilterConfig) -> bool {
    let eth = match EthernetPacket::new(pkt) {
        Some(e) => e,
        None => return false,
    };

    if eth.get_ethertype() != EtherTypes::Ipv4 {
        return false;
    }

    let ipv4 = match Ipv4Packet::new(eth.payload()) {
        Some(ip) => ip,
        None => return false,
    };

    if let Some((network, prefix)) = cfg.allow_net {
        if !ip_in_cidr(ipv4.get_source(), network, prefix) {
            return false;
        }
    }

    match ipv4.get_next_level_protocol() {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                if cfg.deny_ports.contains(&tcp.get_destination())
                    || cfg.deny_ports.contains(&tcp.get_source())
                {
                    return false;
                }
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                if cfg.deny_ports.contains(&udp.get_destination())
                    || cfg.deny_ports.contains(&udp.get_source())
                {
                    return false;
                }
            }
        }
        _ => {}
    }

    true
}

fn forward_packet(tx_fd: RawFd, pkt: &[u8]) -> Result<()> {
    // In real use, you’ll generally want the `sockaddr_ll` for the egress interface
    // and possibly ARP resolution / L2 rewrite.
    let sent = unsafe {
        sendto(
            tx_fd,
            pkt.as_ptr() as *const c_void,
            pkt.len(),
            0,
            std::ptr::null(),
            0,
        )
    };

    if sent < 0 {
        anyhow::bail!("sendto failed");
    }

    Ok(())
}

fn main() -> Result<()> {
    let args = Args::parse();

    let allow_net = if let Some(cidr) = args.allow_cidr.as_deref() {
        Some(parse_cidr(cidr)?)
    } else {
        None
    };

    let deny_ports = if let Some(ports) = args.deny_ports.as_deref() {
        parse_port_list(ports)?
    } else {
        Vec::new()
    };

    let cfg = FilterConfig { allow_net, deny_ports };
    let stats = Stats::default();

    let rx_fd = open_raw_socket(&args.input)?;
    let tx_fd = open_raw_socket(&args.output)?;

    println!("Listening on {} and forwarding to {}", args.input, args.output);
    println!("Filter config: {:?}", cfg);

    let mut buf = vec![0u8; 65536];

    loop {
        match recvfrom(rx_fd, &mut buf) {
            Ok((size, _addr)) => {
                if size == 0 {
                    continue;
                }

                stats.rx_packets.fetch_add(1, Ordering::Relaxed);

                let pkt = &buf[..size];
                if should_forward(pkt, &cfg) {
                    if let Err(e) = forward_packet(tx_fd, pkt) {
                        eprintln!("forward error: {e:?}");
                        stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
                    } else {
                        stats.tx_packets.fetch_add(1, Ordering::Relaxed);
                    }
                } else {
                    stats.dropped_packets.fetch_add(1, Ordering::Relaxed);
                }
            }
            Err(e) => {
                eprintln!("recv error: {e:?}");
            }
        }
    }
}
```

