## Implementation

### `main.go`
```go
package main

import (
	"flag"
	"log"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/google/gopacket"
	"github.com/google/gopacket/layers"
	"github.com/google/gopacket/pcap"
)

type PacketFilter func(pkt gopacket.Packet) bool

type Forwarder struct {
	inDev   string
	outDev  string
	handle  *pcap.Handle
	outHdl  *pcap.Handle
	filter  PacketFilter
	stopCh  chan struct{}
	errCh   chan error
}

func NewForwarder(inDev, outDev string, filter PacketFilter) (*Forwarder, error) {
	inHandle, err := pcap.OpenLive(inDev, 65535, true, pcap.BlockForever)
	if err != nil {
		return nil, err
	}

	outHandle, err := pcap.OpenLive(outDev, 65535, true, pcap.BlockForever)
	if err != nil {
		inHandle.Close()
		return nil, err
	}

	return &Forwarder{
		inDev:  inDev,
		outDev: outDev,
		handle: inHandle,
		outHdl: outHandle,
		filter: filter,
		stopCh: make(chan struct{}),
		errCh:  make(chan error, 1),
	}, nil
}

func (f *Forwarder) Run() {
	packetSource := gopacket.NewPacketSource(f.handle, f.handle.LinkType())
	packetSource.NoCopy = true

	go func() {
		defer close(f.errCh)
		for {
			select {
			case <-f.stopCh:
				return
			case pkt, ok := <-packetSource.Packets():
				if !ok {
					return
				}

				if f.filter != nil && !f.filter(pkt) {
					continue
				}

				if err := f.outHdl.WritePacketData(pkt.Data()); err != nil {
					f.errCh <- err
					return
				}
			}
		}
	}()
}

func (f *Forwarder) Stop() {
	close(f.stopCh)
	if f.handle != nil {
		f.handle.Close()
	}
	if f.outHdl != nil {
		f.outHdl.Close()
	}
}

func defaultFilter(pkt gopacket.Packet) bool {
	// Example filter:
	// Drop non-IPv4 packets and drop TCP port 22.
	network := pkt.NetworkLayer()
	if network == nil {
		return false
	}

	ip4, ok := network.(*layers.IPv4)
	if !ok {
		return false
	}

	if pkt.TransportLayer() != nil {
		if tcp, ok := pkt.TransportLayer().(*layers.TCP); ok {
			if tcp.SrcPort == 22 || tcp.DstPort == 22 {
				return false
			}
		}
	}

	_ = ip4
	return true
}

func main() {
	inDev := flag.String("in", "", "input network interface")
	outDev := flag.String("out", "", "output network interface")
	flag.Parse()

	if *inDev == "" || *outDev == "" {
		log.Fatal("both -in and -out are required")
	}

	fwd, err := NewForwarder(*inDev, *outDev, defaultFilter)
	if err != nil {
		log.Fatalf("failed to create forwarder: %v", err)
	}
	defer fwd.Stop()

	fwd.Run()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	select {
	case sig := <-sigCh:
		log.Printf("received signal: %v", sig)
	case err := <-fwd.errCh:
		if err != nil {
			log.Printf("forwarder error: %v", err)
		}
	}

	time.Sleep(200 * time.Millisecond)
}
```

