## Example filters you can add

### Allow only TCP traffic to a specific port
```go
func allowPort(port layers.TCPPort) PacketFilter {
	return func(pkt gopacket.Packet) bool {
		tl := pkt.TransportLayer()
		tcp, ok := tl.(*layers.TCP)
		if !ok {
			return false
		}
		return tcp.SrcPort == port || tcp.DstPort == port
	}
}
```

### Drop all broadcast packets
```go
func dropBroadcast(pkt gopacket.Packet) bool {
	if ethLayer := pkt.Layer(layers.LayerTypeEthernet); ethLayer != nil {
		eth := ethLayer.(*layers.Ethernet)
		return eth.DstMAC.String() != "ff:ff:ff:ff:ff:ff"
	}
	return false
}
