## Minimal source: `fastfw.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <netinet/ip.h>
#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <unistd.h>

#define RX_RING_SIZE  1024
#define BUF_SIZE      2048

static volatile sig_atomic_t running = 1;

struct iface {
    int fd;
    int ifindex;
    unsigned char mac[6];
    char name[IFNAMSIZ];
};

struct packet {
    unsigned char data[BUF_SIZE];
    int len;
};

static void on_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int get_ifindex(int fd, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);
    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) return -1;
    return ifr.ifr_ifindex;
}

static int get_ifmac(int fd, const char *ifname, unsigned char mac[6]) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);
    if (ioctl(fd, SIOCGIFHWADDR, &ifr) < 0) return -1;
    memcpy(mac, ifr.ifr_hwaddr.sa_data, 6);
    return 0;
}

static int open_raw_iface(struct iface *ifc, const char *ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return -1;
    }

    int ifindex = get_ifindex(fd, ifname);
    if (ifindex < 0) {
        perror("SIOCGIFINDEX");
        close(fd);
        return -1;
    }

    if (get_ifmac(fd, ifname, ifc->mac) < 0) {
        perror("SIOCGIFHWADDR");
        close(fd);
        return -1;
    }

    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family   = AF_PACKET;
    sll.sll_ifindex  = ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(fd);
        return -1;
    }

    ifc->fd = fd;
    ifc->ifindex = ifindex;
    strncpy(ifc->name, ifname, IFNAMSIZ - 1);
    ifc->name[IFNAMSIZ - 1] = '\0';
    return 0;
}

/* Minimal filter:
   - accept IPv4 only
   - forward only TCP/UDP
   - drop everything else
*/
static int should_forward(const unsigned char *pkt, int len) {
    if (len < (int)sizeof(struct ethhdr)) return 0;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP) return 0;

    if (len < (int)(sizeof(struct ethhdr) + sizeof(struct iphdr))) return 0;
    const struct iphdr *ip = (const struct iphdr *)(pkt + sizeof(struct ethhdr));

    if (ip->version != 4) return 0;
    if (ip->ihl < 5) return 0;

    if (ip->protocol != IPPROTO_TCP && ip->protocol != IPPROTO_UDP) return 0;

    return 1;
}

static void rewrite_l2(unsigned char *pkt,
                       const unsigned char src_mac[6],
                       const unsigned char dst_mac[6]) {
    struct ethhdr *eth = (struct ethhdr *)pkt;
    memcpy(eth->h_source, src_mac, 6);
    memcpy(eth->h_dest, dst_mac, 6);
}

struct worker_args {
    struct iface *rx;
    struct iface *tx;
};

static void *worker(void *arg) {
    struct worker_args *wa = (struct worker_args *)arg;
    unsigned char buf[BUF_SIZE];

    while (running) {
        ssize_t n = recv(wa->rx->fd, buf, sizeof(buf), 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            break;
        }

        if (!should_forward(buf, (int)n))
            continue;

        /* Minimal forwarding:
           - rewrite Ethernet src to TX MAC
           - rewrite Ethernet dst to broadcast as a simple default
           For real use, replace with proper next-hop MAC resolution.
        */
        unsigned char dst_mac[6] = {0xff,0xff,0xff,0xff,0xff,0xff};
        rewrite_l2(buf, wa->tx->mac, dst_mac);

        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family   = AF_PACKET;
        sll.sll_ifindex  = wa->tx->ifindex;
        sll.sll_halen    = 6;
        memcpy(sll.sll_addr, dst_mac, 6);

        ssize_t sent = sendto(wa->tx->fd, buf, (size_t)n, 0,
                              (struct sockaddr *)&sll, sizeof(sll));
        if (sent < 0) {
            if (errno == EINTR) continue;
            perror("sendto");
        }
    }

    return NULL;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s <rx-iface> <tx-iface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    struct iface rx = {0}, tx = {0};

    if (open_raw_iface(&rx, argv[1]) < 0) return 1;
    if (open_raw_iface(&tx, argv[2]) < 0) return 1;

    pthread_t tid;
    struct worker_args wa = { .rx = &rx, .tx = &tx };

    if (pthread_create(&tid, NULL, worker, &wa) != 0) {
        perror("pthread_create");
        return 1;
    }

    pthread_join(tid, NULL);

    close(rx.fd);
    close(tx.fd);
    return 0;
}
```

