## Optional: tiny rule extension

If you want packet filtering by TCP port, add a basic parser:

```c
static int tcp_dst_port(const unsigned char *pkt, int len) {
    if (len < (int)(sizeof(struct ethhdr) + sizeof(struct iphdr))) return -1;
    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP) return -1;

    const struct iphdr *ip = (const struct iphdr *)(pkt + sizeof(struct ethhdr));
    if (ip->protocol != IPPROTO_TCP) return -1;

    int iphdr_len = ip->ihl * 4;
    if (len < (int)(sizeof(struct ethhdr) + iphdr_len + 4)) return -1;

    const unsigned char *tcp = pkt + sizeof(struct ethhdr) + iphdr_len;
    return (tcp[2] << 8) | tcp[3];
}
```

Then in `should_forward()`:

```c
if (tcp_dst_port(pkt, len) != 443) return 0;
```

