use libc::*;
use std::ffi::CString;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::fd::RawFd;
use std::ptr;
use std::slice;

const ETH_P_ALL: u16 = 0x0003;
const TPACKET_V3: i32 = 3;

const BLOCK_SIZE: u32 = 1 << 20; // 1 MiB
const FRAME_SIZE: u32 = 2048;
const BLOCK_NR: u32 = 64;
const FRAME_NR: u32 = (BLOCK_SIZE / FRAME_SIZE) * BLOCK_NR;

#[repr(C)]
#[derive(Debug, Clone, Copy)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
struct Ipv4Hdr {
    ver_ihl: u8,
    tos: u8,
    len: u16,
    id: u16,
    frag_off: u16,
    ttl: u8,
    proto: u8,
    checksum: u16,
    src: u32,
    dst: u32,
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
struct TcpHdr {
    src_port: u16,
    dst_port: u16,
    seq: u32,
    ack: u32,
    offset_reserved_flags: u16,
    window: u16,
    checksum: u16,
    urgent_ptr: u16,
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn ifindex(sock: RawFd, ifname: &str) -> io::Result<i32> {
    let c = CString::new(ifname).unwrap();
    let mut ifr: ifreq = unsafe { mem::zeroed() };
    let bytes = c.as_bytes_with_nul();
    unsafe {
        ptr::copy_nonoverlapping(
            bytes.as_ptr() as *const i8,
            ifr.ifr_ifrn.ifrn_name.as_mut_ptr(),
            bytes.len().min(ifr.ifr_ifrn.ifrn_name.len()),
        );
        if ioctl(sock, SIOCGIFINDEX, &mut ifr) < 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(ifr.ifr_ifru.ifru_ifindex)
    }
}

fn create_rx_socket(iface: &str) -> io::Result<RawFd> {
    let fd = unsafe { socket(AF_PACKET, SOCK_RAW, i32::from(htons(ETH_P_ALL))) };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }

    let idx = ifindex(fd, iface)?;
    let sll = sockaddr_ll {
        sll_family: AF_PACKET as u16,
        sll_protocol: htons(ETH_P_ALL),
        sll_ifindex: idx,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        bind(
            fd,
            &sll as *const _ as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }

    let version: c_int = TPACKET_V3;
    let ret = unsafe {
        setsockopt(
            fd,
            SOL_PACKET,
            PACKET_VERSION,
            &version as *const _ as *const c_void,
            mem::size_of_val(&version) as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }

    let req = tpacket_req3 {
        tp_block_size: BLOCK_SIZE,
        tp_block_nr: BLOCK_NR,
        tp_frame_size: FRAME_SIZE,
        tp_frame_nr: FRAME_NR,
        tp_retire_blk_tov: 20, // ms
        tp_sizeof_priv: 0,
        tp_feature_req_word: 0,
    };

    let ret = unsafe {
        setsockopt(
            fd,
            SOL_PACKET,
            PACKET_RX_RING,
            &req as *const _ as *const c_void,
            mem::size_of_val(&req) as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }

    Ok(fd)
}

fn create_tx_socket() -> io::Result<RawFd> {
    let fd = unsafe { socket(AF_INET, SOCK_RAW, IPPROTO_RAW) };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }

    let on: c_int = 1;
    let ret = unsafe {
        setsockopt(
            fd,
            IPPROTO_IP,
            IP_HDRINCL,
            &on as *const _ as *const c_void,
            mem::size_of_val(&on) as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }

    Ok(fd)
}

fn parse_eth(pkt: &[u8]) -> Option<(EthHdr, &[u8])> {
    if pkt.len() < 14 {
        return None;
    }
    let eth = EthHdr {
        dst: pkt[0..6].try_into().ok()?,
        src: pkt[6..12].try_into().ok()?,
        ethertype: u16::from_be_bytes(pkt[12..14].try_into().ok()?),
    };
    Some((eth, &pkt[14..]))
}

fn parse_ipv4(pkt: &[u8]) -> Option<(Ipv4Hdr, &[u8])> {
    if pkt.len() < 20 {
        return None;
    }
    let ver_ihl = pkt[0];
    let ihl = (ver_ihl & 0x0f) as usize * 4;
    if pkt.len() < ihl || ihl < 20 {
        return None;
    }
    let ip = Ipv4Hdr {
        ver_ihl,
        tos: pkt[1],
        len: u16::from_be_bytes(pkt[2..4].try_into().ok()?),
        id: u16::from_be_bytes(pkt[4..6].try_into().ok()?),
        frag_off: u16::from_be_bytes(pkt[6..8].try_into().ok()?),
        ttl: pkt[8],
        proto: pkt[9],
        checksum: u16::from_be_bytes(pkt[10..12].try_into().ok()?),
        src: u32::from_be_bytes(pkt[12..16].try_into().ok()?),
        dst: u32::from_be_bytes(pkt[16..20].try_into().ok()?),
    };
    Some((ip, &pkt[ihl..]))
}

fn parse_tcp(pkt: &[u8]) -> Option<(TcpHdr, &[u8])> {
    if pkt.len() < 20 {
        return None;
    }
    let off = ((u16::from_be_bytes([pkt[12], pkt[13]]) >> 12) * 4) as usize;
    if pkt.len() < off || off < 20 {
        return None;
    }
    let tcp = TcpHdr {
        src_port: u16::from_be_bytes(pkt[0..2].try_into().ok()?),
        dst_port: u16::from_be_bytes(pkt[2..4].try_into().ok()?),
        seq: u32::from_be_bytes(pkt[4..8].try_into().ok()?),
        ack: u32::from_be_bytes(pkt[8..12].try_into().ok()?),
        offset_reserved_flags: u16::from_be_bytes(pkt[12..14].try_into().ok()?),
        window: u16::from_be_bytes(pkt[14..16].try_into().ok()?),
        checksum: u16::from_be_bytes(pkt[16..18].try_into().ok()?),
        urgent_ptr: u16::from_be_bytes(pkt[18..20].try_into().ok()?),
    };
    Some((tcp, &pkt[off..]))
}

// Simple filter: only IPv4 TCP dport 443
fn allow_packet(pkt: &[u8]) -> bool {
    let (_, rest) = match parse_eth(pkt) {
        Some(v) => v,
        None => return false,
    };

    let (ip, rest) = match parse_ipv4(rest) {
        Some(v) => v,
        None => return false,
    };

    if ip.proto != IPPROTO_TCP as u8 {
        return false;
    }

    let (tcp, _) = match parse_tcp(rest) {
        Some(v) => v,
        None => return false,
    };

    tcp.dst_port == 443
}

fn forward_packet(tx_fd: RawFd, pkt: &[u8], dst_ip: Ipv4Addr) -> io::Result<()> {
    let mut buf = pkt.to_vec();

    // Rewrite L3 destination only as a minimal example.
    // In real forwarding you'd also recompute checksums and update L2 headers.
    if buf.len() < 34 {
        return Ok(());
    }

    // Ethernet header assumed present; IPv4 header starts at offset 14
    let ip_off = 14;
    buf[ip_off + 16..ip_off + 20].copy_from_slice(&dst_ip.octets());

    // Zero IPv4 checksum and pretend "good enough" for minimal demo
    buf[ip_off + 10] = 0;
    buf[ip_off + 11] = 0;

    let dst = sockaddr_in {
        sin_family: AF_INET as u16,
        sin_port: 0,
        sin_addr: in_addr {
            s_addr: u32::from_be_bytes(dst_ip.octets()),
        },
        sin_zero: [0; 8],
    };

    let ret = unsafe {
        sendto(
            tx_fd,
            buf.as_ptr() as *const c_void,
            buf.len(),
            0,
            &dst as *const _ as *const sockaddr,
            mem::size_of::<sockaddr_in>() as u32,
        )
    };

    if ret < 0 {
        return Err(io::Error::last_os_error());
    }

    Ok(())
}

fn main() -> io::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 4 {
        eprintln!("usage: {} <in_iface> <out_iface_unused> <dst_ip>", args[0]);
        eprintln!("note: this minimal example uses AF_PACKET rx and raw ip tx");
        std::process::exit(1);
    }

    let in_iface = &args[1];
    let _out_iface = &args[2];
    let dst_ip: Ipv4Addr = args[3].parse().expect("invalid dst_ip");

    let rx_fd = create_rx_socket(in_iface)?;
    let tx_fd = create_tx_socket()?;

    let mmap_len = (BLOCK_SIZE * BLOCK_NR) as usize;
    let ring = unsafe {
        mmap(
            ptr::null_mut(),
            mmap_len,
            PROT_READ | PROT_WRITE,
            MAP_SHARED | MAP_LOCKED,
            rx_fd,
            0,
        )
    };
    if ring == MAP_FAILED {
        return Err(io::Error::last_os_error());
    }

    println!("running: filter TCP dport 443 and forward to {}", dst_ip);

    let mut block_idx = 0usize;
    let block_size = BLOCK_SIZE as usize;

    loop {
        let block_offset = block_idx * block_size;
        let hdr = unsafe { ring.add(block_offset) as *mut tpacket_block_desc };
        let status = unsafe { (*hdr).hdr.bh1.block_status };

        if status & TP_STATUS_USER as u32 == 0 {
            block_idx = (block_idx + 1) % (BLOCK_NR as usize);
            continue;
        }

        let num_pkts = unsafe { (*hdr).hdr.bh1.num_pkts };
        let first_pkt_off = unsafe { (*hdr).hdr.bh1.offset_to_first_pkt as usize };
        let mut pkt_off = first_pkt_off;

        for _ in 0..num_pkts {
            let tphdr = unsafe { (hdr as *mut u8).add(pkt_off) as *const tpacket3_hdr };
            let tp_snaplen = unsafe { (*tphdr).tp_snaplen as usize };
            let tp_mac = unsafe { (*tphdr).tp_mac as usize };
            let tp_next_offset = unsafe { (*tphdr).tp_next_offset as usize };

            let pkt_start = unsafe { (tphdr as *const u8).add(tp_mac) };
            let pkt = unsafe { slice::from_raw_parts(pkt_start, tp_snaplen) };

            if allow_packet(pkt) {
                let _ = forward_packet(tx_fd, pkt, dst_ip);
            }

            if tp_next_offset == 0 {
                break;
            }
            pkt_off += tp_next_offset;
        }

        unsafe {
            (*hdr).hdr.bh1.block_status = TP_STATUS_KERNEL as u32;
        }

        block_idx = (block_idx + 1) % (BLOCK_NR as usize);
    }
}
