## Minimal implementation

```go
package main

import (
	"flag"
	"log"
	"net"
	"os"
	"os/signal"
	"syscall"

	"github.com/google/gopacket"
	"github.com/google/gopacket/layers"
	"github.com/google/gopacket/pcap"
	"github.com/google/gopacket/afpacket"
)

func main() {
	inIf := flag.String("in", "eth0", "input interface")
	outIf := flag.String("out", "eth1", "output interface")
	bpf := flag.String("bpf", "tcp or udp", "BPF filter")
	flag.Parse()

	// Capture packets from the input interface.
	handle, err := pcap.OpenLive(*inIf, 65535, true, pcap.BlockForever)
	if err != nil {
		log.Fatalf("pcap open: %v", err)
	}
	defer handle.Close()

	if err := handle.SetBPFFilter(*bpf); err != nil {
		log.Fatalf("set bpf: %v", err)
	}

	// Open a packet transmitter on the output interface.
	tp, err := afpacket.NewTPacket(
		afpacket.OptInterface(*outIf),
		afpacket.OptFrameSize(1<<12),
		afpacket.OptBlockSize(1<<20),
		afpacket.OptNumBlocks(64),
	)
	if err != nil {
		log.Fatalf("afpacket open: %v", err)
	}
	defer tp.Close()

	src := gopacket.NewPacketSource(handle, handle.LinkType())
	pktChan := src.Packets()

	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGINT, syscall.SIGTERM)

	log.Printf("forwarding packets from %s to %s with filter: %s", *inIf, *outIf, *bpf)

	for {
		select {
		case packet := <-pktChan:
			if packet == nil {
				continue
			}

			// Example packet-level filter: only forward packets with IPv4 + TCP destination port 443.
			if !shouldForward(packet) {
				continue
			}

			raw := packet.Data()

			// Send raw packet bytes out the target interface.
			if err := tp.WritePacketData(raw); err != nil {
				log.Printf("write packet: %v", err)
			}

		case <-sig:
			log.Println("shutting down")
			return
		}
	}
}

func shouldForward(packet gopacket.Packet) bool {
	ip4Layer := packet.Layer(layers.LayerTypeIPv4)
	if ip4Layer == nil {
		return false
	}

	tcpLayer := packet.Layer(layers.LayerTypeTCP)
	if tcpLayer == nil {
		return false
	}

	tcp := tcpLayer.(*layers.TCP)
	return tcp.DstPort == 443 || tcp.SrcPort == 443
}

// Optional helper if you want to rewrite Ethernet src/dst MACs before forwarding.
func rewriteEthernet(packet gopacket.Packet, outIf string) []byte {
	ethLayer := packet.Layer(layers.LayerTypeEthernet)
	if ethLayer == nil {
		return packet.Data()
	}

	iface, err := net.InterfaceByName(outIf)
	if err != nil {
		return packet.Data()
	}

	eth := ethLayer.(*layers.Ethernet)
	eth.SrcMAC = iface.HardwareAddr

	serialized := gopacket.NewSerializeBuffer()
	opts := gopacket.SerializeOptions{FixLengths: true, ComputeChecksums: true}

	// This example only serializes Ethernet + original payload as-is.
	// For real L2 forwarding, you’d decode and reserialize all layers.
	err = gopacket.SerializeLayers(serialized, opts, eth, gopacket.Payload(packet.ApplicationLayer().Payload()))
	if err != nil {
		return packet.Data()
	}

	return serialized.Bytes()
}
```

