## Simple version without pcap

If you want **fewer dependencies and lower overhead**, use raw packet capture/forwarding with `afpacket` only. This is closer to an ultralow-latency datapath.

```go
package main

import (
	"flag"
	"log"
	"os"
	"os/signal"
	"syscall"

	"github.com/google/gopacket"
	"github.com/google/gopacket/layers"
	"github.com/google/gopacket/afpacket"
	"github.com/google/gopacket/pcap"
)

func main() {
	inIf := flag.String("in", "eth0", "input interface")
	outIf := flag.String("out", "eth1", "output interface")
	flag.Parse()

	in, err := afpacket.NewTPacket(
		afpacket.OptInterface(*inIf),
		afpacket.OptFrameSize(1<<12),
		afpacket.OptBlockSize(1<<20),
		afpacket.OptNumBlocks(64),
	)
	if err != nil {
		log.Fatalf("input afpacket: %v", err)
	}
	defer in.Close()

	out, err := afpacket.NewTPacket(
		afpacket.OptInterface(*outIf),
		afpacket.OptFrameSize(1<<12),
		afpacket.OptBlockSize(1<<20),
		afpacket.OptNumBlocks(64),
	)
	if err != nil {
		log.Fatalf("output afpacket: %v", err)
	}
	defer out.Close()

	handle, err := pcap.OpenLive(*inIf, 65535, true, pcap.BlockForever)
	if err != nil {
		log.Fatalf("pcap: %v", err)
	}
	defer handle.Close()

	src := gopacket.NewPacketSource(handle, handle.LinkType())
	packets := src.Packets()

	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGINT, syscall.SIGTERM)

	for {
		select {
		case p := <-packets:
			if p == nil {
				continue
			}
			if p.Layer(layers.LayerTypeTCP) == nil {
				continue
			}
			if err := out.WritePacketData(p.Data()); err != nil {
				log.Printf("forward: %v", err)
			}
		case <-sig:
			return
		}
	}
}
