## 1) Minimal C forwarder

Save as `fw.c`:

```c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <netpacket/packet.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <arpa/inet.h>

#define MAX_PKT 2048

static volatile sig_atomic_t running = 1;

static void on_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int open_raw_socket(const char *ifname, int *ifindex_out, uint8_t mac_out[6]) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket(AF_PACKET)");
        return -1;
    }

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    if (ioctl(fd, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl(SIOCGIFINDEX)");
        close(fd);
        return -1;
    }
    *ifindex_out = ifr.ifr_ifindex;

    if (ioctl(fd, SIOCGIFHWADDR, &ifr) < 0) {
        perror("ioctl(SIOCGIFHWADDR)");
        close(fd);
        return -1;
    }
    memcpy(mac_out, ifr.ifr_hwaddr.sa_data, 6);

    struct sockaddr_ll sll = {0};
    sll.sll_family   = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex  = *ifindex_out;

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind(AF_PACKET)");
        close(fd);
        return -1;
    }

    return fd;
}

static int should_forward(const uint8_t *pkt, ssize_t len) {
    if (len < (ssize_t)sizeof(struct ethhdr)) return 0;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    uint16_t ethertype = ntohs(eth->h_proto);

    /* Example filter:
       forward only IPv4 packets with TCP destination port 443 or UDP destination port 53 */
    if (ethertype == ETH_P_IP) {
        if (len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) return 0;

        const struct iphdr *ip = (const struct iphdr *)(pkt + sizeof(struct ethhdr));
        int iphdr_len = ip->ihl * 4;
        if (iphdr_len < (int)sizeof(struct iphdr)) return 0;
        if (len < (ssize_t)(sizeof(struct ethhdr) + iphdr_len)) return 0;

        if (ip->protocol == IPPROTO_TCP) {
            if (len < (ssize_t)(sizeof(struct ethhdr) + iphdr_len + 4)) return 0;
            const uint8_t *l4 = pkt + sizeof(struct ethhdr) + iphdr_len;
            uint16_t dport = (l4[2] << 8) | l4[3];
            return dport == 443;
        } else if (ip->protocol == IPPROTO_UDP) {
            if (len < (ssize_t)(sizeof(struct ethhdr) + iphdr_len + 4)) return 0;
            const uint8_t *l4 = pkt + sizeof(struct ethhdr) + iphdr_len;
            uint16_t dport = (l4[2] << 8) | l4[3];
            return dport == 53;
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <in-iface> <out-iface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    int in_ifidx = 0, out_ifidx = 0;
    uint8_t in_mac[6], out_mac[6];

    int in_fd = open_raw_socket(argv[1], &in_ifidx, in_mac);
    if (in_fd < 0) return 1;

    int out_fd = open_raw_socket(argv[2], &out_ifidx, out_mac);
    if (out_fd < 0) {
        close(in_fd);
        return 1;
    }

    fprintf(stderr, "Forwarding filtered packets from %s to %s\n", argv[1], argv[2]);

    uint8_t buf[MAX_PKT];
    struct sockaddr_ll src_addr;
    socklen_t src_len = sizeof(src_addr);

    while (running) {
        ssize_t n = recvfrom(in_fd, buf, sizeof(buf), 0,
                             (struct sockaddr *)&src_addr, &src_len);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        if (!should_forward(buf, n))
            continue;

        struct sockaddr_ll dst = {0};
        dst.sll_family   = AF_PACKET;
        dst.sll_ifindex  = out_ifidx;
        dst.sll_halen    = ETH_ALEN;
        memcpy(dst.sll_addr, out_mac, 6);   /* simplistic L2 rewrite */

        ssize_t sent = sendto(out_fd, buf, n, 0, (struct sockaddr *)&dst, sizeof(dst));
        if (sent < 0) {
            perror("sendto");
            continue;
        }
    }

    close(in_fd);
    close(out_fd);
    return 0;
}
```

