## Example: packet forwarder with simple filtering

### `pktfw.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/if.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#define MAX_FRAME 65536

static volatile sig_atomic_t running = 1;

static void on_signal(int sig) {
    (void)sig;
    running = 0;
}

static int iface_index(int sock, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    if (ioctl(sock, SIOCGIFINDEX, &ifr) == -1) {
        perror("ioctl(SIOCGIFINDEX)");
        return -1;
    }
    return ifr.ifr_ifindex;
}

static int bind_socket_to_ifindex(int sock, int ifindex) {
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family   = AF_PACKET;
    sll.sll_ifindex   = ifindex;
    sll.sll_protocol  = htons(ETH_P_ALL);

    if (bind(sock, (struct sockaddr *)&sll, sizeof(sll)) == -1) {
        perror("bind(AF_PACKET)");
        return -1;
    }
    return 0;
}

/* Example filter:
   - allow only IPv4 packets
   - block TCP port 22
   - allow everything else IPv4
*/
static int allow_frame(const unsigned char *frame, ssize_t len) {
    if (len < (ssize_t)sizeof(struct ethhdr)) return 0;

    const struct ethhdr *eth = (const struct ethhdr *)frame;
    if (ntohs(eth->h_proto) != ETH_P_IP) {
        return 0; // ignore non-IPv4
    }

    if (len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr))) return 0;

    const struct iphdr *ip = (const struct iphdr *)(frame + sizeof(struct ethhdr));
    size_t iphdr_len = ip->ihl * 4;
    if (iphdr_len < sizeof(struct iphdr)) return 0;
    if (len < (ssize_t)(sizeof(struct ethhdr) + iphdr_len)) return 0;

    if (ip->protocol == IPPROTO_TCP) {
        const unsigned char *l4 = frame + sizeof(struct ethhdr) + iphdr_len;
        if (len < (ssize_t)(sizeof(struct ethhdr) + iphdr_len + 4)) return 0;

        uint16_t src_port, dst_port;
        memcpy(&src_port, l4, 2);
        memcpy(&dst_port, l4 + 2, 2);
        src_port = ntohs(src_port);
        dst_port = ntohs(dst_port);

        if (src_port == 22 || dst_port == 22) {
            return 0; // block SSH
        }
    }

    return 1;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <ingress-iface> <egress-iface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    const char *in_if = argv[1];
    const char *out_if = argv[2];

    int rx = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (rx < 0) {
        perror("socket(rx)");
        return 1;
    }

    int tx = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx < 0) {
        perror("socket(tx)");
        close(rx);
        return 1;
    }

    int in_index = iface_index(rx, in_if);
    int out_index = iface_index(tx, out_if);
    if (in_index < 0 || out_index < 0) {
        close(rx);
        close(tx);
        return 1;
    }

    if (bind_socket_to_ifindex(rx, in_index) < 0 ||
        bind_socket_to_ifindex(tx, out_index) < 0) {
        close(rx);
        close(tx);
        return 1;
    }

    unsigned char buf[MAX_FRAME];

    fprintf(stderr, "Forwarding from %s to %s\n", in_if, out_if);

    while (running) {
        ssize_t n = recv(rx, buf, sizeof(buf), 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            break;
        }

        if (!allow_frame(buf, n)) {
            continue;
        }

        ssize_t sent = send(tx, buf, n, 0);
        if (sent < 0) {
            perror("send");
            continue;
        }
    }

    close(rx);
    close(tx);
    fprintf(stderr, "Stopped.\n");
    return 0;
}
```

