use anyhow::{Context, Result};
use libc;
use std::env;
use std::ffi::CString;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::fd::RawFd;
use std::ptr;

const BUF_SIZE: usize = 2048;
const ETH_P_ALL: u16 = 0x0003;
const ETH_P_IP: u16 = 0x0800;

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct Ipv4Hdr {
    ver_ihl: u8,
    tos: u8,
    total_len: u16,
    id: u16,
    frag_off: u16,
    ttl: u8,
    proto: u8,
    checksum: u16,
    src: u32,
    dst: u32,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct UdpHdr {
    src_port: u16,
    dst_port: u16,
    len: u16,
    checksum: u16,
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn ntohs(v: u16) -> u16 {
    u16::from_be(v)
}

fn ifindex(name: &str) -> Result<i32> {
    let c = CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        Err(io::Error::last_os_error()).context("if_nametoindex failed")
    } else {
        Ok(idx as i32)
    }
}

fn open_packet_socket(iface: &str) -> Result<RawFd> {
    let fd = unsafe {
        libc::socket(
            libc::AF_PACKET,
            libc::SOCK_RAW,
            htons(ETH_P_ALL) as i32,
        )
    };
    if fd < 0 {
        return Err(io::Error::last_os_error()).context("socket(AF_PACKET) failed");
    }

    let idx = ifindex(iface)?;
    let mut saddr: libc::sockaddr_ll = unsafe { mem::zeroed() };
    saddr.sll_family = libc::AF_PACKET as u16;
    saddr.sll_protocol = htons(ETH_P_ALL);
    saddr.sll_ifindex = idx;

    let ret = unsafe {
        libc::bind(
            fd,
            &saddr as *const _ as *const libc::sockaddr,
            mem::size_of::<libc::sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        let e = io::Error::last_os_error();
        unsafe { libc::close(fd) };
        return Err(e).context("bind(AF_PACKET) failed");
    }

    Ok(fd)
}

fn open_tx_socket(iface: &str) -> Result<RawFd> {
    // For sending with sendto on AF_PACKET socket
    open_packet_socket(iface)
}

fn parse_eth(buf: &[u8]) -> Option<(EthHdr, &[u8])> {
    if buf.len() < mem::size_of::<EthHdr>() {
        return None;
    }
    let hdr = unsafe { ptr::read_unaligned(buf.as_ptr() as *const EthHdr) };
    Some((hdr, &buf[mem::size_of::<EthHdr>()..]))
}

fn parse_ipv4(buf: &[u8]) -> Option<(Ipv4Hdr, usize, &[u8])> {
    if buf.len() < mem::size_of::<Ipv4Hdr>() {
        return None;
    }
    let hdr = unsafe { ptr::read_unaligned(buf.as_ptr() as *const Ipv4Hdr) };
    let ihl = (hdr.ver_ihl & 0x0f) as usize * 4;
    if ihl < 20 || buf.len() < ihl {
        return None;
    }
    Some((hdr, ihl, &buf[ihl..]))
}

fn parse_udp(buf: &[u8]) -> Option<UdpHdr> {
    if buf.len() < mem::size_of::<UdpHdr>() {
        return None;
    }
    Some(unsafe { ptr::read_unaligned(buf.as_ptr() as *const UdpHdr) })
}

fn forward_packet(tx_fd: RawFd, iface: &str, packet: &[u8]) -> Result<()> {
    let idx = ifindex(iface)?;
    let mut saddr: libc::sockaddr_ll = unsafe { mem::zeroed() };
    saddr.sll_family = libc::AF_PACKET as u16;
    saddr.sll_protocol = htons(ETH_P_ALL);
    saddr.sll_ifindex = idx;
    saddr.sll_halen = 6;

    let ret = unsafe {
        libc::sendto(
            tx_fd,
            packet.as_ptr() as *const libc::c_void,
            packet.len(),
            0,
            &saddr as *const _ as *const libc::sockaddr,
            mem::size_of::<libc::sockaddr_ll>() as u32,
        )
    };

    if ret < 0 {
        Err(io::Error::last_os_error()).context("sendto failed")
    } else {
        Ok(())
    }
}

fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!(
            "Usage: {} <input_if> <output_if> [udp_dst_port]",
            args[0]
        );
        std::process::exit(1);
    }

    let input_if = &args[1];
    let output_if = &args[2];
    let udp_filter_port = if args.len() > 3 {
        Some(args[3].parse::<u16>().context("invalid UDP port")?)
    } else {
        None
    };

    let rx_fd = open_packet_socket(input_if)?;
    let tx_fd = open_tx_socket(output_if)?;

    let mut buf = [0u8; BUF_SIZE];

    loop {
        let n = unsafe {
            libc::recv(
                rx_fd,
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            eprintln!("recv error: {err}");
            break;
        }

        let n = n as usize;
        let packet = &buf[..n];

        let (eth, payload) = match parse_eth(packet) {
            Some(v) => v,
            None => continue,
        };

        let ethertype = ntohs(eth.ethertype);

        // Example fast path filter:
        // - forward IPv4 only
        // - if port provided, only forward UDP packets to that destination port
        let forward = if ethertype == ETH_P_IP {
            if let Some((ip, ihl, l4)) = parse_ipv4(payload) {
                match ip.proto {
                    17 => {
                        if let Some(filter_port) = udp_filter_port {
                            if let Some(udp) = parse_udp(l4) {
                                ntohs(udp.dst_port) == filter_port
                            } else {
                                false
                            }
                        } else {
                            true
                        }
                    }
                    _ => udp_filter_port.is_none(),
                }
            } else {
                false
            }
        } else {
            false
        };

        if forward {
            if let Err(e) = forward_packet(tx_fd, output_if, packet) {
                eprintln!("forward error: {e:?}");
            }
        }
    }

    unsafe {
        libc::close(rx_fd);
        libc::close(tx_fd);
    }

    Ok(())
}
```

