## Code: `packet_fwd.c`
```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <net/if.h>
#include <netinet/in.h>

#define SNAP_LEN 65535
#define ETHER_HDR_LEN 14

static int out_sock = -1;
static struct sockaddr_ll out_addr;
static unsigned char out_mac[6];
static int out_ifindex = -1;

static int setup_raw_tx(const char *ifname, const unsigned char *dst_mac) {
    out_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (out_sock < 0) {
        perror("socket(AF_PACKET)");
        return -1;
    }

    out_ifindex = if_nametoindex(ifname);
    if (out_ifindex == 0) {
        perror("if_nametoindex");
        return -1;
    }

    memset(&out_addr, 0, sizeof(out_addr));
    out_addr.sll_family = AF_PACKET;
    out_addr.sll_ifindex = out_ifindex;
    out_addr.sll_halen = ETH_ALEN;
    memcpy(out_addr.sll_addr, dst_mac, 6);

    memcpy(out_mac, dst_mac, 6);
    return 0;
}

static int should_forward(const struct pcap_pkthdr *hdr, const u_char *pkt) {
    if (hdr->caplen < ETHER_HDR_LEN + sizeof(struct ip)) return 0;

    const struct ether_header *eth = (const struct ether_header *)pkt;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return 0;

    const struct ip *ip = (const struct ip *)(pkt + ETHER_HDR_LEN);

    // Example filter: forward only TCP/UDP packets to port 443 or 53
    if (ip->ip_p == IPPROTO_TCP) {
        int ip_hl = ip->ip_hl * 4;
        if (hdr->caplen < ETHER_HDR_LEN + ip_hl + sizeof(struct tcphdr)) return 0;
        const struct tcphdr *tcp = (const struct tcphdr *)(pkt + ETHER_HDR_LEN + ip_hl);
        uint16_t sport = ntohs(tcp->source);
        uint16_t dport = ntohs(tcp->dest);
        return (sport == 443 || dport == 443);
    } else if (ip->ip_p == IPPROTO_UDP) {
        int ip_hl = ip->ip_hl * 4;
        if (hdr->caplen < ETHER_HDR_LEN + ip_hl + sizeof(struct udphdr)) return 0;
        const struct udphdr *udp = (const struct udphdr *)(pkt + ETHER_HDR_LEN + ip_hl);
        uint16_t sport = ntohs(udp->source);
        uint16_t dport = ntohs(udp->dest);
        return (sport == 53 || dport == 53);
    }

    return 0;
}

static void pcap_handler_cb(u_char *user, const struct pcap_pkthdr *hdr, const u_char *pkt) {
    (void)user;
    if (!should_forward(hdr, pkt)) return;

    ssize_t sent = sendto(out_sock, pkt, hdr->caplen, 0,
                          (struct sockaddr *)&out_addr, sizeof(out_addr));
    if (sent < 0) {
        perror("sendto");
    }
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <in_if> <out_if> <out_mac>\n", argv[0]);
        fprintf(stderr, "Example: %s eth0 eth1 aa:bb:cc:dd:ee:ff\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];

    unsigned int mac[6];
    if (sscanf(argv[3], "%x:%x:%x:%x:%x:%x",
               &mac[0], &mac[1], &mac[2], &mac[3], &mac[4], &mac[5]) != 6) {
        fprintf(stderr, "Invalid MAC address\n");
        return 1;
    }
    unsigned char dst_mac[6];
    for (int i = 0; i < 6; i++) dst_mac[i] = (unsigned char)mac[i];

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live(in_if, SNAP_LEN, 1, 1, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live: %s\n", errbuf);
        return 1;
    }

    // BPF prefilter: only IPv4 TCP/UDP
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "pcap_compile: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter: %s\n", pcap_geterr(handle));
        pcap_freecode(&fp);
        pcap_close(handle);
        return 1;
    }
    pcap_freecode(&fp);

    if (setup_raw_tx(out_if, dst_mac) != 0) {
        pcap_close(handle);
        return 1;
    }

    printf("Forwarding packets from %s to %s\n", in_if, out_if);
    pcap_loop(handle, -1, pcap_handler_cb, NULL);

    pcap_close(handle);
    close(out_sock);
    return 0;
}
```

