use nix::sys::socket::{
    recv, send, socket, AddressFamily, MsgFlags, SockFlag, SockProtocol, SockType,
};
use nix::unistd::close;
use std::env;
use std::ffi::CString;
use std::io;
use std::mem;
use std::os::unix::io::RawFd;
use std::ptr;

#[repr(C)]
#[derive(Clone, Copy)]
struct SockAddrLl {
    sll_family: u16,
    sll_protocol: u16,
    sll_ifindex: i32,
    sll_hatype: u16,
    sll_pkttype: u8,
    sll_halen: u8,
    sll_addr: [u8; 8],
}

fn htons(u: u16) -> u16 {
    u.to_be()
}

fn ifindex(name: &str) -> io::Result<i32> {
    let c = CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(idx as i32)
    }
}

fn create_raw_socket(protocol: u16) -> io::Result<RawFd> {
    let fd = socket(
        AddressFamily::Packet,
        SockType::Raw,
        SockFlag::empty(),
        SockProtocol::from(protocol as i32),
    )
    .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
    Ok(fd)
}

fn bind_to_if(fd: RawFd, ifindex: i32, protocol: u16) -> io::Result<()> {
    let addr = SockAddrLl {
        sll_family: libc::AF_PACKET as u16,
        sll_protocol: htons(protocol),
        sll_ifindex: ifindex,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            fd,
            &addr as *const SockAddrLl as *const libc::sockaddr,
            mem::size_of::<SockAddrLl>() as libc::socklen_t,
        )
    };

    if ret < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn packet_filter(frame: &[u8]) -> bool {
    // Minimal Ethernet filtering example:
    // - require Ethernet II frame
    // - allow IPv4 (0x0800) and ARP (0x0806)
    // - drop everything else
    if frame.len() < 14 {
        return false;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    matches!(ethertype, 0x0800 | 0x0806)
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <input-iface> <output-iface>", args[0]);
        std::process::exit(1);
    }

    let in_if = &args[1];
    let out_if = &args[2];

    let in_idx = ifindex(in_if)?;
    let out_idx = ifindex(out_if)?;

    let eth_p_all = 0x0003; // ETH_P_ALL
    let rx = create_raw_socket(eth_p_all)?;
    let tx = create_raw_socket(eth_p_all)?;

    bind_to_if(rx, in_idx, eth_p_all)?;
    bind_to_if(tx, out_idx, eth_p_all)?;

    // Optional: set nonblocking or busy-poll tuning here for lower latency.
    // Keeping minimal for now.

    let mut buf = [0u8; 2048];

    loop {
        let n = match recv(rx, &mut buf, MsgFlags::empty()) {
            Ok(n) => n,
            Err(e) => {
                eprintln!("recv error: {}", e);
                continue;
            }
        };

        let frame = &buf[..n];

        if !packet_filter(frame) {
            continue;
        }

        if let Err(e) = send(tx, frame, MsgFlags::empty()) {
            eprintln!("send error: {}", e);
        }
    }

    #[allow(unreachable_code)]
    {
        let _ = close(rx);
        let _ = close(tx);
        Ok(())
    }
}
