## Example: filter by destination UDP port 53

Replace `packet_filter` with this:

```rust
fn packet_filter(frame: &[u8]) -> bool {
    if frame.len() < 14 {
        return false;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return false;
    }

    // IPv4 header starts at offset 14
    if frame.len() < 34 {
        return false;
    }

    let ihl = (frame[14] & 0x0f) as usize * 4;
    if frame.len() < 14 + ihl + 8 {
        return false;
    }

    let protocol = frame[23];
    if protocol != 17 {
        return false; // UDP only
    }

    let udp_offset = 14 + ihl;
    let dst_port = u16::from_be_bytes([frame[udp_offset + 2], frame[udp_offset + 3]]);
    dst_port == 53
}
```

