Below is a **minimal working example** of a low-latency packet filter/forwarder in **Go**, using **raw Ethernet frames via AF_PACKET** on Linux.

It:
- binds to one interface,
- reads packets directly from a packet socket,
- filters packets using a simple rule,
- forwards matching packets out another interface,
- avoids copies where practical with a small buffer pool.

This is intentionally minimal and suitable as a starting point.

---

## Assumptions

- Linux only
- Requires root or `CAP_NET_RAW`
- Two interfaces available, e.g.:
  - `eth0` = ingress
  - `eth1` = egress
- Example filter: forward only IPv4 packets with destination port 443

---

## `main.go`

```go
package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"net"
	"os"
	"sync"
	"syscall"
	"unsafe"
)

const (
	ETH_P_ALL = 0x0003
	ETH_P_IP   = 0x0800

	// Linux sockaddr_ll
	AF_PACKET = 17
)

type sockaddrLL struct {
	Family   uint16
	Protocol uint16
	Ifindex  int32
	Hatype   uint16
	Pkttype  uint8
	Halen    uint8
	Addr     [8]byte
}

type Packet struct {
	B []byte
	N int
}

var pktPool = sync.Pool{
	New: func() any {
		b := make([]byte, 2048)
		return &Packet{B: b}
	},
}

func htons(v uint16) uint16 {
	return (v<<8)&0xff00 | v>>8
}

func parseEthernet(b []byte) (ethertype uint16, ok bool) {
	if len(b) < 14 {
		return 0, false
	}
	return binary.BigEndian.Uint16(b[12:14]), true
}

func parseIPv4Proto(b []byte) (proto byte, ihl int, ok bool) {
	if len(b) < 14+20 {
		return 0, 0, false
	}
	if (b[14]>>4) != 4 {
		return 0, 0, false
	}
	ihl = int((b[14] & 0x0f) * 4)
	if len(b) < 14+ihl {
		return 0, 0, false
	}
	proto = b[23]
	return proto, ihl, true
}

func parseTCPDstPort(b []byte, ipHeaderLen int) (port uint16, ok bool) {
	tcpStart := 14 + ipHeaderLen
	if len(b) < tcpStart+4 {
		return 0, false
	}
	return binary.BigEndian.Uint16(b[tcpStart+2 : tcpStart+4]), true
}

func openRawSocket(iface string) (fd int, ifindex int, err error) {
	ifaceObj, err := net.InterfaceByName(iface)
	if err != nil {
		return -1, 0, err
	}
	ifindex = ifaceObj.Index

	fd, err = syscall.Socket(AF_PACKET, syscall.SOCK_RAW, int(htons(ETH_P_ALL)))
	if err != nil {
		return -1, 0, err
	}

	sa := &sockaddrLL{
		Family:   AF_PACKET,
		Protocol: htons(ETH_P_ALL),
		Ifindex:  int32(ifindex),
	}
	_, _, errno := syscall.Syscall(
		syscall.SYS_BIND,
		uintptr(fd),
		uintptr(unsafe.Pointer(sa)),
		uintptr(unsafe.Sizeof(*sa)),
	)
	if errno != 0 {
		syscall.Close(fd)
		return -1, 0, errno
	}

	return fd, ifindex, nil
}

func sendPacket(fd int, ifindex int, b []byte, n int) error {
	sa := &sockaddrLL{
		Family:   AF_PACKET,
		Protocol: htons(ETH_P_ALL),
		Ifindex:  int32(ifindex),
	}
	_, _, errno := syscall.Syscall6(
		syscall.SYS_SENDTO,
		uintptr(fd),
		uintptr(unsafe.Pointer(&b[0])),
		uintptr(n),
		0,
		uintptr(unsafe.Pointer(sa)),
		uintptr(unsafe.Sizeof(*sa)),
	)
	if errno != 0 {
		return errno
	}
	return nil
}

// Minimal filter: forward only IPv4 TCP packets destined to port 443.
func shouldForward(pkt []byte) bool {
	ethertype, ok := parseEthernet(pkt)
	if !ok || ethertype != ETH_P_IP {
		return false
	}

	proto, ihl, ok := parseIPv4Proto(pkt)
	if !ok || proto != 6 {
		return false
	}

	dstPort, ok := parseTCPDstPort(pkt, ihl)
	if !ok {
		return false
	}

	return dstPort == 443
}

func main() {
	if len(os.Args) != 3 {
		fmt.Fprintf(os.Stderr, "usage: %s <ingress-iface> <egress-iface>\n", os.Args[0])
		os.Exit(1)
	}

	ingress := os.Args[1]
	egress := os.Args[2]

	inFD, _, err := openRawSocket(ingress)
	if err != nil {
		log.Fatalf("open ingress socket: %v", err)
	}
	defer syscall.Close(inFD)

	outFD, outIfIndex, err := openRawSocket(egress)
	if err != nil {
		log.Fatalf("open egress socket: %v", err)
	}
	defer syscall.Close(outFD)

	log.Printf("forwarding from %s -> %s", ingress, egress)

	buf := make([]byte, 65536)

	for {
		n, err := syscall.Read(inFD, buf)
		if err != nil {
			if err == syscall.EINTR {
				continue
			}
			log.Fatalf("read: %v", err)
		}

		if n <= 0 {
			continue
		}

		if shouldForward(buf[:n]) {
			if err := sendPacket(outFD, outIfIndex, buf, n); err != nil {
				log.Printf("send: %v", err)
			}
		}
	}
}
```

