## `src/main.rs`

```rust
use anyhow::{Context, Result};
use clap::Parser;
use libc::{c_int, if_nametoindex, sockaddr, sockaddr_ll, socket, bind, recv, sendto, close,
           AF_PACKET, ETH_P_ALL, PACKET_HOST, SOCK_RAW};
use std::ffi::CString;
use std::mem::{size_of, zeroed};
use std::net::Ipv4Addr;

#[derive(Parser, Debug)]
struct Args {
    /// Input interface
    #[arg(long)]
    input: String,

    /// Output interface
    #[arg(long)]
    output: String,

    /// UDP destination port to match
    #[arg(long, default_value_t = 9000)]
    port: u16,
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn parse_mac(buf: &[u8]) -> [u8; 6] {
    [buf[0], buf[1], buf[2], buf[3], buf[4], buf[5]]
}

fn main() -> Result<()> {
    let args = Args::parse();

    unsafe {
        // Create raw packet socket
        let fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL as u16) as c_int);
        if fd < 0 {
            return Err(std::io::Error::last_os_error()).context("socket(AF_PACKET) failed");
        }

        // Bind to input interface
        let ifname = CString::new(args.input.clone())?;
        let ifindex = if_nametoindex(ifname.as_ptr());
        if ifindex == 0 {
            close(fd);
            return Err(std::io::Error::last_os_error()).context("if_nametoindex(input) failed");
        }

        let mut sll: sockaddr_ll = zeroed();
        sll.sll_family = AF_PACKET as u16;
        sll.sll_protocol = htons(ETH_P_ALL as u16);
        sll.sll_ifindex = ifindex as i32;

        let ret = bind(
            fd,
            &sll as *const sockaddr_ll as *const sockaddr,
            size_of::<sockaddr_ll>() as u32,
        );
        if ret < 0 {
            close(fd);
            return Err(std::io::Error::last_os_error()).context("bind(input) failed");
        }

        // Resolve output interface index
        let out_ifname = CString::new(args.output.clone())?;
        let out_ifindex = if_nametoindex(out_ifname.as_ptr());
        if out_ifindex == 0 {
            close(fd);
            return Err(std::io::Error::last_os_error()).context("if_nametoindex(output) failed");
        }

        let mut buf = [0u8; 2048];

        loop {
            let n = recv(fd, buf.as_mut_ptr() as *mut _, buf.len(), 0);
            if n < 0 {
                eprintln!("recv error: {}", std::io::Error::last_os_error());
                continue;
            }

            let n = n as usize;
            if n < 14 + 20 {
                continue;
            }

            // Ethernet header
            let ethertype = u16::from_be_bytes([buf[12], buf[13]]);
            if ethertype != 0x0800 {
                continue; // IPv4 only
            }

            // IPv4 header
            let ip_off = 14;
            let ver_ihl = buf[ip_off];
            let version = ver_ihl >> 4;
            let ihl = (ver_ihl & 0x0f) as usize * 4;
            if version != 4 || n < 14 + ihl + 8 {
                continue;
            }

            let proto = buf[ip_off + 9];
            if proto != 17 {
                continue; // UDP only
            }

            let dst_ip = Ipv4Addr::new(
                buf[ip_off + 16],
                buf[ip_off + 17],
                buf[ip_off + 18],
                buf[ip_off + 19],
            );

            let udp_off = ip_off + ihl;
            let dst_port = u16::from_be_bytes([buf[udp_off + 2], buf[udp_off + 3]]);
            if dst_port != args.port {
                continue;
            }

            // Packet-level forwarding decision made here.
            // Rewrite Ethernet header to send out the other interface.
            // For minimal demo: preserve frame, set dummy MACs.
            // In a real forwarder, you’d learn next-hop MACs via ARP/ND.
            let src_mac = parse_mac(&buf[6..12]);
            let dst_mac = parse_mac(&buf[0..6]);

            buf[0..6].copy_from_slice(&src_mac);
            buf[6..12].copy_from_slice(&dst_mac);

            // Send out on output interface
            let mut out_sll: sockaddr_ll = zeroed();
            out_sll.sll_family = AF_PACKET as u16;
            out_sll.sll_ifindex = out_ifindex as i32;
            out_sll.sll_halen = 6;
            out_sll.sll_addr[..6].copy_from_slice(&buf[0..6]);

            let sent = sendto(
                fd,
                buf.as_ptr() as *const _,
                n,
                0,
                &out_sll as *const sockaddr_ll as *const sockaddr,
                size_of::<sockaddr_ll>() as u32,
            );

            if sent < 0 {
                eprintln!(
                    "sendto error for {}:{} -> {}",
                    dst_ip,
                    dst_port,
                    std::io::Error::last_os_error()
                );
            }
        }
    }
}
```

