## Go implementation

```go
package main

import (
	"bufio"
	"compress/gzip"
	"context"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"
)

type Config struct {
	LogPath        string
	RotateBytes    int64
	RotateInterval  time.Duration
	Keep           int
	Compress       bool
	PollInterval   time.Duration
	TruncateSource bool
}

type Rotator struct {
	cfg      Config
	mu       sync.Mutex
	lastRotate time.Time
}

func main() {
	var cfg Config

	flag.StringVar(&cfg.LogPath, "log", "/var/log/app.log", "path to log file")
	flag.Int64Var(&cfg.RotateBytes, "max-bytes", 100<<20, "rotate after file exceeds this size")
	flag.DurationVar(&cfg.RotateInterval, "max-age", 24*time.Hour, "rotate after this age")
	flag.IntVar(&cfg.Keep, "keep", 7, "number of rotated logs to keep")
	flag.BoolVar(&cfg.Compress, "compress", true, "gzip rotated logs")
	flag.DurationVar(&cfg.PollInterval, "poll", 2*time.Second, "poll interval")
	flag.BoolVar(&cfg.TruncateSource, "truncate", true, "truncate original file after rotation")
	flag.Parse()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	r := &Rotator{
		cfg:        cfg,
		lastRotate: time.Now(),
	}

	log.Printf("starting log rotator for %s", cfg.LogPath)

	ticker := time.NewTicker(cfg.PollInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			if err := r.MaybeRotate(); err != nil {
				log.Printf("rotate error: %v", err)
			}
		}
	}
}

func (r *Rotator) MaybeRotate() error {
	r.mu.Lock()
	defer r.mu.Unlock()

	st, err := os.Stat(r.cfg.LogPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	shouldRotate := false
	if st.Size() >= r.cfg.RotateBytes {
		shouldRotate = true
	}
	if time.Since(r.lastRotate) >= r.cfg.RotateInterval {
		shouldRotate = true
	}
	if !shouldRotate {
		return nil
	}

	return r.rotate()
}

func (r *Rotator) rotate() error {
	src := r.cfg.LogPath
	ts := time.Now().Format("20060102-150405")
	dst := fmt.Sprintf("%s.%s", src, ts)
	if r.cfg.Compress {
		dst += ".gz"
	}

	// Open source for streaming copy.
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	tmpDst := dst + ".tmp"
	out, err := os.Create(tmpDst)
	if err != nil {
		return err
	}

	var writer io.WriteCloser = out
	if r.cfg.Compress {
		gz := gzip.NewWriter(out)
		writer = gz
	}

	// Stream copy with small fixed buffer.
	buf := make([]byte, 32*1024)
	if _, err := io.CopyBuffer(writer, in, buf); err != nil {
		writer.Close()
		out.Close()
		os.Remove(tmpDst)
		return err
	}

	if err := writer.Close(); err != nil {
		out.Close()
		os.Remove(tmpDst)
		return err
	}
	if err := out.Close(); err != nil {
		os.Remove(tmpDst)
		return err
	}

	if err := os.Rename(tmpDst, dst); err != nil {
		os.Remove(tmpDst)
		return err
	}

	if r.cfg.TruncateSource {
		if err := truncateFile(src); err != nil {
			return err
		}
	} else {
		// If not truncating, move source aside and recreate.
		backup := src + ".old"
		if err := os.Rename(src, backup); err != nil {
			return err
		}
		newf, err := os.Create(src)
		if err != nil {
			return err
		}
		newf.Close()
		os.Remove(backup)
	}

	r.lastRotate = time.Now()
	if err := r.cleanupOld(); err != nil {
		return err
	}

	log.Printf("rotated %s -> %s", src, dst)
	return nil
}

func truncateFile(path string) error {
	f, err := os.OpenFile(path, os.O_WRONLY, 0)
	if err != nil {
		return err
	}
	defer f.Close()
	return f.Truncate(0)
}

func (r *Rotator) cleanupOld() error {
	dir := filepath.Dir(r.cfg.LogPath)
	base := filepath.Base(r.cfg.LogPath)

	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}

	type candidate struct {
		name string
		mod  time.Time
	}
	var cands []candidate

	for _, e := range entries {
		n := e.Name()
		if !strings.HasPrefix(n, base+".") {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		cands = append(cands, candidate{name: filepath.Join(dir, n), mod: info.ModTime()})
	}

	if len(cands) <= r.cfg.Keep {
		return nil
	}

	// Simple in-place sort with low memory overhead.
	for i := 0; i < len(cands); i++ {
		for j := i + 1; j < len(cands); j++ {
			if cands[j].mod.Before(cands[i].mod) {
				cands[i], cands[j] = cands[j], cands[i]
			}
		}
	}

	for i := 0; i < len(cands)-r.cfg.Keep; i++ {
		_ = os.Remove(cands[i].name)
	}
	return nil
}

// Optional helper: parse sizes like "100MB"
func parseBytes(s string) (int64, error) {
	s = strings.TrimSpace(strings.ToUpper(s))
	mult := int64(1)
	switch {
	case strings.HasSuffix(s, "KB"):
		mult = 1 << 10
		s = strings.TrimSuffix(s, "KB")
	case strings.HasSuffix(s, "MB"):
		mult = 1 << 20
		s = strings.TrimSuffix(s, "MB")
	case strings.HasSuffix(s, "GB"):
		mult = 1 << 30
		s = strings.TrimSuffix(s, "GB")
	}
	v, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil {
		return 0, err
	}
	return v * mult, nil
}

// Example line-tail like reader with bounded memory, if needed.
func streamFile(ctx context.Context, path string, out io.Writer) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	r := bufio.NewReaderSize(f, 32*1024)
	buf := make([]byte, 32*1024)

	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}
		n, err := r.Read(buf)
		if n > 0 {
			if _, werr := out.Write(buf[:n]); werr != nil {
				return werr
			}
		}
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return err
		}
	}
}

// Needed on some systems when truncating active logs with writers holding FDs.
func _ = syscall.O_CLOEXEC
```

