use std::env;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::thread;
use std::time::{Duration, SystemTime};

const COPY_BUF_SIZE: usize = 8 * 1024; // 8 KiB
const DEFAULT_MAX_BYTES: u64 = 10 * 1024 * 1024; // 10 MiB
const DEFAULT_CHECK_INTERVAL_SECS: u64 = 5;
const DEFAULT_MAX_FILES: usize = 5;

#[derive(Debug, Clone)]
struct Config {
    log_path: PathBuf,
    max_bytes: u64,
    check_interval: Duration,
    max_files: usize,
    compress: bool,
}

fn main() -> io::Result<()> {
    let config = parse_args()?;
    run_daemon(config)
}

fn parse_args() -> io::Result<Config> {
    let mut args = env::args().skip(1);

    let log_path = args
        .next()
        .map(PathBuf::from)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "missing log path"))?;

    let max_bytes = args
        .next()
        .map(|s| s.parse::<u64>())
        .transpose()
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid max_bytes"))?
        .unwrap_or(DEFAULT_MAX_BYTES);

    let max_files = args
        .next()
        .map(|s| s.parse::<usize>())
        .transpose()
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "invalid max_files"))?
        .unwrap_or(DEFAULT_MAX_FILES);

    let compress = args
        .next()
        .map(|s| matches!(s.as_str(), "1" | "true" | "yes" | "on"))
        .unwrap_or(true);

    Ok(Config {
        log_path,
        max_bytes,
        check_interval: Duration::from_secs(DEFAULT_CHECK_INTERVAL_SECS),
        max_files,
        compress,
    })
}

fn run_daemon(config: Config) -> io::Result<()> {
    loop {
        if let Err(e) = maybe_rotate(&config) {
            eprintln!("rotation error: {e}");
        }
        thread::sleep(config.check_interval);
    }
}

fn maybe_rotate(config: &Config) -> io::Result<()> {
    let metadata = match fs::metadata(&config.log_path) {
        Ok(m) => m,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(()),
        Err(e) => return Err(e),
    };

    if metadata.len() < config.max_bytes {
        return Ok(());
    }

    rotate(config)
}

fn rotate(config: &Config) -> io::Result<()> {
    // Close/open semantics are app-specific.
    // This daemon rotates by renaming the active file and creating a new one.
    let timestamp = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let rotated_name = format!(
        "{}.{}",
        config.log_path.to_string_lossy(),
        timestamp
    );
    let rotated_path = PathBuf::from(rotated_name);

    // If the file is actively written by another process, that process should reopen
    // its log file after rotation. This daemon only manages filesystem state.
    fs::rename(&config.log_path, &rotated_path)?;

    // Recreate the original empty log file.
    let _new_log = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(&config.log_path)?;

    if config.compress {
        compress_file_streaming(&rotated_path)?;
    }

    prune_old_rotations(&config.log_path, config.max_files)?;
    Ok(())
}

fn compress_file_streaming(path: &Path) -> io::Result<()> {
    // Use external gzip for streaming compression, avoiding in-memory compression buffers.
    let input = File::open(path)?;

    let output_path = PathBuf::from(format!("{}.gz", path.to_string_lossy()));
    let output = File::create(&output_path)?;

    let mut child = Command::new("gzip")
        .arg("-c")
        .stdin(Stdio::from(input))
        .stdout(Stdio::from(output))
        .stderr(Stdio::null())
        .spawn()?;

    let status = child.wait()?;
    if !status.success() {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "gzip failed",
        ));
    }

    fs::remove_file(path)?;
    Ok(())
}

fn prune_old_rotations(base_log: &Path, max_files: usize) -> io::Result<()> {
    let parent = base_log.parent().unwrap_or_else(|| Path::new("."));
    let base_name = base_log
        .file_name()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "invalid log path"))?
        .to_string_lossy()
        .to_string();

    let mut rotated: Vec<PathBuf> = Vec::new();

    for entry in fs::read_dir(parent)? {
        let entry = entry?;
        let p = entry.path();
        let name = match p.file_name() {
            Some(n) => n.to_string_lossy(),
            None => continue,
        };

        if name.starts_with(&base_name) && name != base_name {
            rotated.push(p);
        }
    }

    // Keep memory bounded by only a small list of filenames.
    rotated.sort();

    if rotated.len() <= max_files {
        return Ok(());
    }

    for old in rotated.iter().take(rotated.len() - max_files) {
        let _ = fs::remove_file(old);
    }

    Ok(())
}
