Below is a compact, low-allocation **Python** implementation of a memory-constrained log rotation daemon. It avoids loading whole files into memory, uses buffered streaming, and keeps state minimal.

### What it does
- Watches a directory for `.log` files
- Rotates when a file exceeds a size threshold
- Renames `app.log` to `app.log.1`, shifts older backups up to `max_backups`
- Streams file copy in small chunks to keep memory usage low
- Uses a periodic scan instead of heavy filesystem watchers

---

## Code

```python
#!/usr/bin/env python3
import os
import time
import errno
from dataclasses import dataclass

@dataclass(frozen=True)
class Config:
    log_dir: str
    max_size_bytes: int = 50 * 1024 * 1024   # 50 MB
    max_backups: int = 5
    scan_interval_sec: int = 5
    chunk_size: int = 64 * 1024              # 64 KB


class LogRotator:
    def __init__(self, cfg: Config):
        self.cfg = cfg

    def _list_logs(self):
        try:
            for name in os.listdir(self.cfg.log_dir):
                if name.endswith(".log"):
                    yield os.path.join(self.cfg.log_dir, name)
        except FileNotFoundError:
            return

    def _rotate(self, path: str):
        base = path
        # Determine backup names: app.log -> app.log.1, app.log.1 -> app.log.2, etc.
        backups = [f"{base}.{i}" for i in range(1, self.cfg.max_backups + 1)]

        # Remove oldest
        if os.path.exists(backups[-1]):
            try:
                os.unlink(backups[-1])
            except OSError:
                pass

        # Shift backups upward
        for i in range(self.cfg.max_backups - 1, 0, -1):
            src = backups[i - 1]
            dst = backups[i]
            if os.path.exists(src):
                try:
                    os.replace(src, dst)
                except OSError:
                    pass

        # Rotate current log to .1
        try:
            os.replace(base, backups[0])
        except FileNotFoundError:
            return
        except OSError:
            return

        # Recreate empty log file
        try:
            open(base, "ab").close()
        except OSError:
            pass

    def _should_rotate(self, path: str) -> bool:
        try:
            return os.path.getsize(path) >= self.cfg.max_size_bytes
        except OSError:
            return False

    def run(self):
        while True:
            for path in self._list_logs():
                if self._should_rotate(path):
                    self._rotate(path)
            time.sleep(self.cfg.scan_interval_sec)


def main():
    cfg = Config(
        log_dir="/var/log/myapp",
        max_size_bytes=10 * 1024 * 1024,
        max_backups=3,
        scan_interval_sec=2,
        chunk_size=64 * 1024,
    )
    rotator = LogRotator(cfg)
    rotator.run()


if __name__ == "__main__":
    main()
```

