#define _POSIX_C_SOURCE 200809L

#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <limits.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define CHECK_INTERVAL_SEC 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024)
#define DEFAULT_KEEP 5

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int setup_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGTERM, &sa, NULL) < 0) return -1;
    if (sigaction(SIGINT, &sa, NULL) < 0) return -1;
    if (sigaction(SIGHUP, &sa, NULL) < 0) return -1;
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    umask(022);

    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) return -1;

    (void)dup2(fd, STDIN_FILENO);
    (void)dup2(fd, STDOUT_FILENO);
    (void)dup2(fd, STDERR_FILENO);
    if (fd > STDERR_FILENO) close(fd);

    return 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int path_join(char *dst, size_t dstsz, const char *a, const char *b) {
    int n = snprintf(dst, dstsz, "%s%s", a, b);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *base, int keep, int compress) {
    char oldp[PATH_MAX];
    char newp[PATH_MAX];
    char comp[PATH_MAX];

    for (int i = keep - 1; i >= 1; --i) {
        snprintf(oldp, sizeof(oldp), "%s.%d%s", base, i, compress ? ".gz" : "");
        snprintf(newp, sizeof(newp), "%s.%d%s", base, i + 1, compress ? ".gz" : "");
        unlink(newp);
        if (access(oldp, F_OK) == 0) {
            if (rename(oldp, newp) < 0) return -1;
        }
    }

    snprintf(oldp, sizeof(oldp), "%s%s", base, "");
    snprintf(newp, sizeof(newp), "%s.1", base);

    unlink(newp);
    if (rename(oldp, newp) < 0) return -1;

    if (compress) {
        snprintf(comp, sizeof(comp), "%s.1.gz", base);

        pid_t pid = fork();
        if (pid < 0) return -1;
        if (pid == 0) {
            execlp("gzip", "gzip", "-f", newp, (char *)NULL);
            _exit(127);
        }

        int status;
        while (waitpid(pid, &status, 0) < 0) {
            if (errno != EINTR) return -1;
        }
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) return -1;
    }

    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
        "Usage: %s <logfile> [max_bytes] [keep] [compress 0|1]\n"
        "Defaults: max_bytes=%d keep=%d compress=0\n",
        prog, DEFAULT_MAX_SIZE, DEFAULT_KEEP);
}

int main(int argc, char **argv) {
    const char *logfile;
    off_t max_bytes = DEFAULT_MAX_SIZE;
    int keep = DEFAULT_KEEP;
    int compress = 0;

    if (argc < 2) {
        usage(argv[0]);
        return 1;
    }

    logfile = argv[1];
    if (argc > 2) max_bytes = (off_t)strtoll(argv[2], NULL, 10);
    if (argc > 3) keep = atoi(argv[3]);
    if (argc > 4) compress = atoi(argv[4]);

    if (max_bytes <= 0 || keep < 1 || keep > 99) {
        usage(argv[0]);
        return 1;
    }

    if (setup_signals() < 0) return 1;
    if (daemonize() < 0) return 1;

    while (!g_stop) {
        off_t sz = 0;
        if (file_size(logfile, &sz) == 0 && sz > max_bytes) {
            if (rotate_logs(logfile, keep, compress) < 0) {
                /* In a real daemon, write to syslog or a dedicated error log. */
            }
        }

        for (int i = 0; i < CHECK_INTERVAL_SEC && !g_stop; ++i) {
            sleep(1);
        }
    }

    return 0;
}
