/*
 * memory_constrained_logrot.c
 *
 * Minimal log rotation daemon with fixed memory usage.
 *
 * Build:
 *   cc -O2 -Wall -Wextra -pedantic -std=c11 -o logrot memory_constrained_logrot.c
 *
 * Example:
 *   ./logrot --file /var/log/app.log --max-size 10485760 --max-age 86400 --keep 5
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef MAX_FILES
#define MAX_FILES 8
#endif

#ifndef PATH_MAX_LOCAL
#define PATH_MAX_LOCAL 512
#endif

#ifndef NAME_MAX_LOCAL
#define NAME_MAX_LOCAL 256
#endif

typedef struct {
    char path[PATH_MAX_LOCAL];
    off_t max_size;
    time_t max_age_sec;
    int keep;
    bool copytruncate;
    time_t last_rotated;
} log_cfg_t;

typedef struct {
    int fd;
    dev_t dev;
    ino_t ino;
} log_state_t;

static volatile sig_atomic_t g_running = 1;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void safe_strncpy(char *dst, const char *src, size_t n) {
    if (n == 0) return;
    strncpy(dst, src, n - 1);
    dst[n - 1] = '\0';
}

static int open_log(const char *path) {
    int fd = open(path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    return fd;
}

static int stat_fd(int fd, struct stat *st) {
    return fstat(fd, st);
}

static bool should_rotate(const log_cfg_t *cfg, int fd) {
    struct stat st;
    if (stat_fd(fd, &st) != 0) return false;

    if (cfg->max_size > 0 && st.st_size >= cfg->max_size) {
        return true;
    }

    if (cfg->max_age_sec > 0) {
        time_t now = time(NULL);
        if (now != (time_t)-1 && cfg->last_rotated > 0) {
            if ((now - cfg->last_rotated) >= cfg->max_age_sec) {
                return true;
            }
        }
    }

    return false;
}

static void build_rotated_path(char *out, size_t out_sz, const char *base, int idx) {
    snprintf(out, out_sz, "%s.%d", base, idx);
    out[out_sz - 1] = '\0';
}

static int rotate_logs(const log_cfg_t *cfg) {
    char old_path[PATH_MAX_LOCAL];
    char new_path[PATH_MAX_LOCAL];

    for (int i = cfg->keep - 1; i >= 1; --i) {
        build_rotated_path(old_path, sizeof(old_path), cfg->path, i);
        build_rotated_path(new_path, sizeof(new_path), cfg->path, i + 1);
        rename(old_path, new_path); /* ignore errors if file doesn't exist */
    }

    build_rotated_path(new_path, sizeof(new_path), cfg->path, 1);
    if (rename(cfg->path, new_path) != 0) {
        if (errno != ENOENT) return -1;
    }

    return 0;
}

static int reopen_log(log_state_t *st, const log_cfg_t *cfg) {
    if (st->fd >= 0) {
        close(st->fd);
        st->fd = -1;
    }

    st->fd = open_log(cfg->path);
    if (st->fd < 0) return -1;

    struct stat sb;
    if (fstat(st->fd, &sb) == 0) {
        st->dev = sb.st_dev;
        st->ino = sb.st_ino;
    }

    return 0;
}

static int copytruncate_file(const char *path) {
    int in_fd = open(path, O_RDONLY);
    if (in_fd < 0) return -1;

    char tmp_path[PATH_MAX_LOCAL];
    snprintf(tmp_path, sizeof(tmp_path), "%s.tmp", path);
    tmp_path[sizeof(tmp_path) - 1] = '\0';

    int out_fd = open(tmp_path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    char buf[4096];
    ssize_t r;
    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in_fd);
                close(out_fd);
                unlink(tmp_path);
                return -1;
            }
            off += w;
        }
    }

    close(in_fd);
    close(out_fd);

    if (r < 0) {
        unlink(tmp_path);
        return -1;
    }

    if (truncate(path, 0) != 0) {
        unlink(tmp_path);
        return -1;
    }

    unlink(tmp_path);
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) exit(EXIT_SUCCESS);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) exit(EXIT_SUCCESS);

    umask(022);
    if (chdir("/") != 0) return -1;

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_WRONLY);
    open("/dev/null", O_WRONLY);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s --file PATH --max-size BYTES --max-age SEC --keep N [--copytruncate] [--foreground]\n",
        prog);
    exit(EXIT_FAILURE);
}

int main(int argc, char **argv) {
    log_cfg_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.keep = 5;
    cfg.max_size = 10 * 1024 * 1024;
    cfg.max_age_sec = 86400;
    cfg.copytruncate = false;
    cfg.last_rotated = time(NULL);

    bool foreground = false;
    safe_strncpy(cfg.path, "/var/log/app.log", sizeof(cfg.path));

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--file") == 0 && i + 1 < argc) {
            safe_strncpy(cfg.path, argv[++i], sizeof(cfg.path));
        } else if (strcmp(argv[i], "--max-size") == 0 && i + 1 < argc) {
            cfg.max_size = (off_t)strtoll(argv[++i], NULL, 10);
        } else if (strcmp(argv[i], "--max-age") == 0 && i + 1 < argc) {
            cfg.max_age_sec = (time_t)strtoll(argv[++i], NULL, 10);
        } else if (strcmp(argv[i], "--keep") == 0 && i + 1 < argc) {
            cfg.keep = atoi(argv[++i]);
            if (cfg.keep < 1) cfg.keep = 1;
            if (cfg.keep > 99) cfg.keep = 99;
        } else if (strcmp(argv[i], "--copytruncate") == 0) {
            cfg.copytruncate = true;
        } else if (strcmp(argv[i], "--foreground") == 0) {
            foreground = true;
        } else {
            usage(argv[0]);
        }
    }

    if (!foreground && daemonize() != 0) die("daemonize");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_state_t st;
    memset(&st, 0, sizeof(st));
    st.fd = -1;

    if (reopen_log(&st, &cfg) != 0) die("open_log");

    while (g_running) {
        if (should_rotate(&cfg, st.fd)) {
            if (cfg.copytruncate) {
                if (copytruncate_file(cfg.path) != 0) {
                    /* ignore for robustness; retry loop continues */
                }
            } else {
                if (rotate_logs(&cfg) != 0) {
                    /* ignore errors on missing files */
                }
            }

            cfg.last_rotated = time(NULL);
            if (reopen_log(&st, &cfg) != 0) {
                sleep(1);
                continue;
            }
        }

        /* Poll interval; lower for responsiveness, higher for low CPU/memory impact */
        sleep(5);
    }

    if (st.fd >= 0) close(st.fd);
    return 0;
}
