#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef MAX_PATH_LEN
#define MAX_PATH_LEN 256
#endif

#ifndef MAX_ROTATIONS
#define MAX_ROTATIONS 5
#endif

#ifndef CHECK_INTERVAL_SEC
#define CHECK_INTERVAL_SEC 5
#endif

#ifndef ROTATE_THRESHOLD_BYTES
#define ROTATE_THRESHOLD_BYTES (10 * 1024 * 1024)  // 10 MB
#endif

typedef struct {
    const char *log_path;
    size_t threshold_bytes;
    int max_rotations;
    volatile sig_atomic_t stop;
} config_t;

static void on_signal(int sig) {
    (void)sig;
    // Only async-signal-safe operation: set flag
    // Accessed as volatile sig_atomic_t
}

static size_t safe_strlen(const char *s) {
    size_t n = 0;
    if (!s) return 0;
    while (s[n] != '\0') n++;
    return n;
}

static int build_path(char *dst, size_t dst_sz, const char *base, int idx) {
    int n;
    if (idx == 0) {
        n = snprintf(dst, dst_sz, "%s", base);
    } else {
        n = snprintf(dst, dst_sz, "%s.%d", base, idx);
    }
    if (n < 0 || (size_t)n >= dst_sz) {
        return -1;
    }
    return 0;
}

static int rotate_logs(const config_t *cfg) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    // Delete oldest
    if (cfg->max_rotations > 0) {
        if (build_path(old_path, sizeof(old_path), cfg->log_path, cfg->max_rotations) != 0) {
            return -1;
        }
        unlink(old_path);
    }

    // Shift rotations: N-1 -> N
    for (int i = cfg->max_rotations - 1; i >= 1; --i) {
        if (build_path(old_path, sizeof(old_path), cfg->log_path, i) != 0) return -1;
        if (build_path(new_path, sizeof(new_path), cfg->log_path, i + 1) != 0) return -1;
        rename(old_path, new_path);
    }

    // Current -> .1
    if (build_path(old_path, sizeof(old_path), cfg->log_path, 0) != 0) return -1;
    if (build_path(new_path, sizeof(new_path), cfg->log_path, 1) != 0) return -1;
    if (rename(old_path, new_path) != 0) {
        // If file doesn't exist, it's not fatal
        if (errno != ENOENT) return -1;
    }

    return 0;
}

static off_t get_file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int reopen_log(FILE **fp, const char *path) {
    if (*fp) {
        fclose(*fp);
        *fp = NULL;
    }
    *fp = fopen(path, "a");
    return (*fp) ? 0 : -1;
}

int main(int argc, char **argv) {
    config_t cfg = {
        .log_path = "/var/log/myapp.log",
        .threshold_bytes = ROTATE_THRESHOLD_BYTES,
        .max_rotations = MAX_ROTATIONS,
        .stop = 0
    };

    if (argc >= 2) {
        cfg.log_path = argv[1];
    }
    if (argc >= 3) {
        cfg.threshold_bytes = (size_t)strtoull(argv[2], NULL, 10);
    }
    if (argc >= 4) {
        cfg.max_rotations = atoi(argv[3]);
        if (cfg.max_rotations < 1) cfg.max_rotations = 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *logf = NULL;
    if (reopen_log(&logf, cfg.log_path) != 0) {
        perror("open log");
        return 1;
    }

    while (!cfg.stop) {
        off_t size = get_file_size(cfg.log_path);
        if (size < 0) {
            perror("stat");
            sleep(CHECK_INTERVAL_SEC);
            continue;
        }

        if ((size_t)size >= cfg.threshold_bytes) {
            if (fclose(logf) != 0) {
                perror("fclose");
                return 1;
            }
            logf = NULL;

            if (rotate_logs(&cfg) != 0) {
                perror("rotate");
                return 1;
            }

            if (reopen_log(&logf, cfg.log_path) != 0) {
                perror("reopen");
                return 1;
            }
        }

        // Example heartbeat write
        fprintf(logf, "daemon alive\n");
        fflush(logf);

        sleep(CHECK_INTERVAL_SEC);
    }

    if (logf) fclose(logf);
    return 0;
}
