## `logrotated.c`

```c
#define _GNU_SOURCE
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/inotify.h>
#include <sys/wait.h>
#include <sys/file.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <limits.h>
#include <time.h>

#define MAX_PATH        4096
#define EVENT_BUF_SIZE   4096
#define LOCK_FILE_PATH   "/tmp/logrotated.lock"

static volatile sig_atomic_t g_stop = 0;

typedef struct {
    char log_path[MAX_PATH];
    char rotated_base[MAX_PATH];
    size_t max_bytes;
    int keep;
    int compress;
    int daemonize;
} config_t;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_copy(char *dst, const char *src, size_t n) {
    if (!n) return;
    strncpy(dst, src, n - 1);
    dst[n - 1] = '\0';
}

static int file_size(const char *path, off_t *sz) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    *sz = st.st_size;
    return 0;
}

static int rotate_files(const config_t *cfg) {
    char oldp[MAX_PATH];
    char newp[MAX_PATH];
    int i;

    for (i = cfg->keep - 1; i >= 1; --i) {
        snprintf(oldp, sizeof(oldp), "%s.%d%s", cfg->rotated_base, i,
                 cfg->compress ? ".gz" : "");
        snprintf(newp, sizeof(newp), "%s.%d%s", cfg->rotated_base, i + 1,
                 cfg->compress ? ".gz" : "");
        unlink(newp);
        if (access(oldp, F_OK) == 0) {
            if (rename(oldp, newp) < 0) return -1;
        }
    }

    snprintf(newp, sizeof(newp), "%s.1", cfg->rotated_base);
    unlink(newp);
    if (rename(cfg->log_path, newp) < 0) return -1;

    if (cfg->compress) {
        pid_t pid = fork();
        if (pid < 0) return -1;
        if (pid == 0) {
            execlp("gzip", "gzip", "-f", newp, (char *)NULL);
            _exit(127);
        }
        if (waitpid(pid, NULL, 0) < 0) return -1;
    }

    int fd = open(cfg->log_path, O_CREAT | O_WRONLY | O_TRUNC, 0640);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int daemonize_process(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    umask(022);
    chdir("/");

    int fd = open("/dev/null", O_RDWR);
    if (fd >= 0) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        if (fd > 2) close(fd);
    }
    return 0;
}

static int acquire_lock(void) {
    int fd = open(LOCK_FILE_PATH, O_CREAT | O_RDWR, 0644);
    if (fd < 0) return -1;
    if (flock(fd, LOCK_EX | LOCK_NB) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

static int setup_inotify(const char *path) {
    int fd = inotify_init1(IN_NONBLOCK | IN_CLOEXEC);
    if (fd < 0) return -1;

    int wd = inotify_add_watch(fd, path, IN_MODIFY | IN_MOVE_SELF | IN_ATTRIB | IN_DELETE_SELF);
    if (wd < 0) {
        close(fd);
        return -1;
    }

    return fd;
}

static int should_rotate(const config_t *cfg) {
    off_t sz;
    if (file_size(cfg->log_path, &sz) < 0) return 0;
    return (size_t)sz >= cfg->max_bytes;
}

int main(int argc, char **argv) {
    config_t cfg;
    int lockfd = -1;
    int inofd = -1;
    char event_buf[EVENT_BUF_SIZE];

    if (argc < 4) {
        fprintf(stderr, "Usage: %s <log_path> <max_bytes> <keep> [compress] [daemon]\n", argv[0]);
        return 1;
    }

    memset(&cfg, 0, sizeof(cfg));
    safe_copy(cfg.log_path, argv[1], sizeof(cfg.log_path));
    safe_copy(cfg.rotated_base, argv[1], sizeof(cfg.rotated_base));
    cfg.max_bytes = (size_t)strtoull(argv[2], NULL, 10);
    cfg.keep = atoi(argv[3]);
    cfg.compress = (argc > 4) ? atoi(argv[4]) : 0;
    cfg.daemonize = (argc > 5) ? atoi(argv[5]) : 0;

    if (cfg.keep < 1 || cfg.keep > 99 || cfg.max_bytes == 0) {
        fprintf(stderr, "Invalid arguments\n");
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    lockfd = acquire_lock();
    if (lockfd < 0) {
        fprintf(stderr, "Another instance is running\n");
        return 1;
    }

    if (cfg.daemonize) {
        if (daemonize_process() < 0) {
            fprintf(stderr, "Failed to daemonize\n");
            close(lockfd);
            return 1;
        }
    }

    inofd = setup_inotify(cfg.log_path);
    if (inofd < 0) {
        fprintf(stderr, "Failed to set up inotify\n");
        close(lockfd);
        return 1;
    }

    while (!g_stop) {
        fd_set rfds;
        struct timeval tv;
        int rc;

        FD_ZERO(&rfds);
        FD_SET(inofd, &rfds);
        tv.tv_sec = 1;
        tv.tv_usec = 0;

        rc = select(inofd + 1, &rfds, NULL, NULL, &tv);
        if (rc < 0) {
            if (errno == EINTR) continue;
            break;
        }

        if (should_rotate(&cfg)) {
            if (rotate_files(&cfg) < 0) {
                fprintf(stderr, "Rotation failed: %s\n", strerror(errno));
            } else {
                inotify_rm_watch(inofd, 1);
                close(inofd);
                inofd = setup_inotify(cfg.log_path);
                if (inofd < 0) break;
            }
        }

        if (rc > 0 && FD_ISSET(inofd, &rfds)) {
            ssize_t n = read(inofd, event_buf, sizeof(event_buf));
            (void)n; // drain events
        }
    }

    if (inofd >= 0) close(inofd);
    if (lockfd >= 0) close(lockfd);
    return 0;
}
