## C code

```c
// logrotate_daemon.c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef MAX_LOG_PATH
#define MAX_LOG_PATH 256
#endif

#ifndef MAX_BACKUPS
#define MAX_BACKUPS 9
#endif

#ifndef POLL_INTERVAL_SEC
#define POLL_INTERVAL_SEC 5
#endif

#ifndef IO_BUF_SIZE
#define IO_BUF_SIZE 4096
#endif

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_write_str(int fd, const char *s) {
    if (!s) return;
    size_t len = strlen(s);
    while (len > 0) {
        ssize_t n = write(fd, s, len);
        if (n < 0) {
            if (errno == EINTR) continue;
            return;
        }
        s += (size_t)n;
        len -= (size_t)n;
    }
}

static int parse_size(const char *s, uint64_t *out) {
    if (!s || !*s || !out) return -1;
    char *end = NULL;
    errno = 0;
    unsigned long long v = strtoull(s, &end, 10);
    if (errno != 0 || end == s) return -1;

    uint64_t mult = 1;
    if (*end != '\0') {
        if (strcmp(end, "K") == 0 || strcmp(end, "k") == 0) mult = 1024ULL;
        else if (strcmp(end, "M") == 0 || strcmp(end, "m") == 0) mult = 1024ULL * 1024ULL;
        else if (strcmp(end, "G") == 0 || strcmp(end, "g") == 0) mult = 1024ULL * 1024ULL * 1024ULL;
        else return -1;
    }
    *out = (uint64_t)v * mult;
    return 0;
}

static int path_join(char *dst, size_t dstsz, const char *base, int idx) {
    int n;
    if (idx == 0) {
        n = snprintf(dst, dstsz, "%s", base);
    } else {
        n = snprintf(dst, dstsz, "%s.%d", base, idx);
    }
    if (n < 0 || (size_t)n >= dstsz) return -1;
    return 0;
}

static int copy_file(const char *src, const char *dst) {
    int in = -1, out = -1;
    char buf[IO_BUF_SIZE];
    int rc = -1;

    in = open(src, O_RDONLY | O_CLOEXEC);
    if (in < 0) return -1;

    out = open(dst, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
    if (out < 0) goto done;

    for (;;) {
        ssize_t r = read(in, buf, sizeof(buf));
        if (r < 0) {
            if (errno == EINTR) continue;
            goto done;
        }
        if (r == 0) {
            rc = 0;
            break;
        }

        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out, buf + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                goto done;
            }
            off += w;
        }
    }

done:
    if (in >= 0) close(in);
    if (out >= 0) close(out);
    return rc;
}

static int rotate_logs(const char *base, int max_backups) {
    char src[MAX_LOG_PATH];
    char dst[MAX_LOG_PATH];

    if (max_backups < 1) return -1;
    if (path_join(src, sizeof(src), base, max_backups) < 0) return -1;
    (void)unlink(src);

    for (int i = max_backups - 1; i >= 1; --i) {
        if (path_join(src, sizeof(src), base, i) < 0) return -1;
        if (path_join(dst, sizeof(dst), base, i + 1) < 0) return -1;

        if (access(src, F_OK) == 0) {
            (void)unlink(dst);
            if (rename(src, dst) != 0) {
                return -1;
            }
        }
    }

    if (path_join(src, sizeof(src), base, 0) < 0) return -1;
    if (path_join(dst, sizeof(dst), base, 1) < 0) return -1;

    if (access(src, F_OK) == 0) {
        (void)unlink(dst);
        if (rename(src, dst) != 0) {
            return -1;
        }
    }

    return 0;
}

static uint64_t get_file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return 0;
    if (!S_ISREG(st.st_mode)) return 0;
    return (uint64_t)st.st_size;
}

static int truncate_active_log(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

int main(int argc, char **argv) {
    const char *log_path = NULL;
    uint64_t threshold = 0;
    int max_backups = MAX_BACKUPS;

    if (argc < 3) {
        fprintf(stderr, "Usage: %s <logfile> <threshold>[K|M|G] [backups]\n", argv[0]);
        return 2;
    }

    log_path = argv[1];
    if (strlen(log_path) >= MAX_LOG_PATH) {
        fprintf(stderr, "Log path too long (max %d)\n", MAX_LOG_PATH - 1);
        return 2;
    }

    if (parse_size(argv[2], &threshold) != 0 || threshold == 0) {
        fprintf(stderr, "Invalid threshold: %s\n", argv[2]);
        return 2;
    }

    if (argc >= 4) {
        max_backups = atoi(argv[3]);
        if (max_backups < 1 || max_backups > 99) {
            fprintf(stderr, "Invalid backups count\n");
            return 2;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    safe_write_str(STDERR_FILENO, "logrotate daemon started\n");

    while (!g_stop) {
        uint64_t sz = get_file_size(log_path);

        if (sz >= threshold) {
            if (rotate_logs(log_path, max_backups) == 0) {
                if (truncate_active_log(log_path) != 0) {
                    safe_write_str(STDERR_FILENO, "Failed to recreate active log\n");
                } else {
                    safe_write_str(STDERR_FILENO, "Log rotated\n");
                }
            } else {
                safe_write_str(STDERR_FILENO, "Rotation failed\n");
            }
        }

        struct timespec ts;
        ts.tv_sec = POLL_INTERVAL_SEC;
        ts.tv_nsec = 0;

        while (nanosleep(&ts, &ts) != 0) {
            if (errno == EINTR && g_stop) break;
            if (errno != EINTR) break;
        }
    }

    safe_write_str(STDERR_FILENO, "logrotate daemon exiting\n");
    return 0;
}
