#define _POSIX_C_SOURCE 200809L

#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LOGS       8
#define PATH_MAX_LEN   256
#define BUF_SIZE       4096

typedef struct {
    char path[PATH_MAX_LEN];
    size_t max_size;
    int backups;   // e.g. 3 => .1, .2, .3
} log_cfg_t;

static volatile sig_atomic_t g_running = 1;

static void on_signal(int sig) {
    (void)sig;
    g_running = 0;
}

static int safe_snprintf(char *dst, size_t dst_sz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dst_sz, fmt, ap);
    va_end(ap);
    return (n >= 0 && (size_t)n < dst_sz) ? 0 : -1;
}

static int file_size(const char *path, off_t *sz) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *sz = st.st_size;
    return 0;
}

static int ensure_parent_dir_exists(const char *path) {
    (void)path;
    return 0; // intentionally omitted for simplicity
}

static int rotate_one(const log_cfg_t *cfg) {
    char oldp[PATH_MAX_LEN];
    char newp[PATH_MAX_LEN];
    int i;

    if (cfg->backups < 1) return 0;

    // Delete oldest
    if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->path, cfg->backups) != 0)
        return -1;
    unlink(oldp);

    // Shift backups down
    for (i = cfg->backups - 1; i >= 1; --i) {
        if (safe_snprintf(oldp, sizeof(oldp), "%s.%d", cfg->path, i) != 0)
            return -1;
        if (safe_snprintf(newp, sizeof(newp), "%s.%d", cfg->path, i + 1) != 0)
            return -1;
        rename(oldp, newp);
    }

    // Move current to .1
    if (safe_snprintf(newp, sizeof(newp), "%s.1", cfg->path) != 0)
        return -1;
    if (rename(cfg->path, newp) != 0) {
        if (errno == ENOENT) return 0; // file absent, nothing to do
        return -1;
    }

    // Create fresh log file
    int fd = open(cfg->path, O_CREAT | O_WRONLY | O_TRUNC | O_CLOEXEC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int check_and_rotate(const log_cfg_t *cfg) {
    off_t sz;
    if (file_size(cfg->path, &sz) != 0) {
        if (errno == ENOENT) return 0; // missing file is OK
        return -1;
    }
    if ((size_t)sz >= cfg->max_size) {
        return rotate_one(cfg);
    }
    return 0;
}

static void sleep_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!g_running) return;
    }
}

int main(int argc, char **argv) {
    log_cfg_t logs[MAX_LOGS];
    int log_count = 0;
    int interval_ms = 1000;
    int i;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <logfile:maxbytes:backups> [..]\n", argv[0]);
        fprintf(stderr, "Example: %s /var/log/app.log:1048576:5\n", argv[0]);
        return 1;
    }

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    for (i = 1; i < argc && log_count < MAX_LOGS; ++i) {
        char *spec = argv[i];
        char *p1 = strchr(spec, ':');
        char *p2 = p1 ? strchr(p1 + 1, ':') : NULL;
        if (!p1 || !p2) {
            fprintf(stderr, "Bad spec: %s\n", spec);
            return 1;
        }

        size_t path_len = (size_t)(p1 - spec);
        if (path_len == 0 || path_len >= PATH_MAX_LEN) {
            fprintf(stderr, "Path too long: %s\n", spec);
            return 1;
        }

        memset(&logs[log_count], 0, sizeof(logs[log_count]));
        memcpy(logs[log_count].path, spec, path_len);
        logs[log_count].path[path_len] = '\0';
        logs[log_count].max_size = (size_t)strtoull(p1 + 1, NULL, 10);
        logs[log_count].backups  = atoi(p2 + 1);

        if (logs[log_count].max_size == 0 || logs[log_count].backups < 0) {
            fprintf(stderr, "Invalid limits: %s\n", spec);
            return 1;
        }

        ++log_count;
    }

    if (log_count == 0) {
        fprintf(stderr, "No valid logs configured\n");
        return 1;
    }

    while (g_running) {
        for (i = 0; i < log_count; ++i) {
            if (check_and_rotate(&logs[i]) != 0) {
                // Keep daemon alive on errors; log to stderr
                fprintf(stderr, "Rotation failed for %s: %s\n",
                        logs[i].path, strerror(errno));
            }
        }
        sleep_ms(interval_ms);
    }

    return 0;
}
