```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_ROTATIONS 5
#define CHECK_INTERVAL_SEC 1
#define BUF_SIZE 4096

typedef struct {
    char log_path[PATH_MAX];
    size_t max_size;
    int rotations;
    bool running;
    int current_fd;
} Config;

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void safe_perror(const char *msg) {
    write(STDERR_FILENO, msg, strlen(msg));
    write(STDERR_FILENO, ": ", 2);
    write(STDERR_FILENO, strerror(errno), strlen(strerror(errno)));
    write(STDERR_FILENO, "\n", 1);
}

static off_t file_size_fd(int fd) {
    struct stat st;
    if (fstat(fd, &st) != 0) return -1;
    return st.st_size;
}

static int open_log_file(const char *path) {
    int fd = open(path, O_WRONLY | O_APPEND | O_CREAT, 0644);
    return fd;
}

static int close_fd(int *fd) {
    if (*fd >= 0) {
        if (close(*fd) != 0) return -1;
        *fd = -1;
    }
    return 0;
}

static int rotate_logs(const Config *cfg) {
    char old_path[PATH_MAX];
    char new_path[PATH_MAX];

    // Remove oldest
    if (cfg->rotations > 0) {
        snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, cfg->rotations);
        unlink(old_path);
    }

    // Shift rotated files upward: .n -> .n+1
    for (int i = cfg->rotations - 1; i >= 1; --i) {
        snprintf(old_path, sizeof(old_path), "%s.%d", cfg->log_path, i);
        snprintf(new_path, sizeof(new_path), "%s.%d", cfg->log_path, i + 1);

        if (rename(old_path, new_path) != 0) {
            if (errno != ENOENT) return -1;
        }
    }

    // Current -> .1
    snprintf(old_path, sizeof(old_path), "%s", cfg->log_path);
    snprintf(new_path, sizeof(new_path), "%s.1", cfg->log_path);

    if (rename(old_path, new_path) != 0) {
        if (errno != ENOENT) return -1;
    }

    return 0;
}

static int maybe_rotate(Config *cfg) {
    off_t sz = file_size_fd(cfg->current_fd);
    if (sz < 0) return -1;
    if ((size_t)sz < cfg->max_size) return 0;

    if (close_fd(&cfg->current_fd) != 0) return -1;

    if (rotate_logs(cfg) != 0) return -1;

    cfg->current_fd = open_log_file(cfg->log_path);
    if (cfg->current_fd < 0) return -1;

    return 0;
}

static int daemon_loop(Config *cfg) {
    while (!g_stop) {
        if (maybe_rotate(cfg) != 0) {
            safe_perror("rotation failed");
            // Keep trying, but do not crash
        }
        sleep(CHECK_INTERVAL_SEC);
    }
    return 0;
}

static void usage(const char *prog) {
    dprintf(STDERR_FILENO,
            "Usage: %s <logfile> <max_size_bytes> [rotations]\n"
            "Example: %s /var/log/app.log 10485760 5\n",
            prog, prog);
}

int main(int argc, char **argv) {
    Config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.current_fd = -1;
    cfg.running = true;
    cfg.rotations = MAX_ROTATIONS;

    if (argc < 3) {
        usage(argv[0]);
        return 1;
    }

    if (strlen(argv[1]) >= sizeof(cfg.log_path)) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }
    strncpy(cfg.log_path, argv[1], sizeof(cfg.log_path) - 1);

    errno = 0;
    unsigned long long max_size = strtoull(argv[2], NULL, 10);
    if (errno != 0 || max_size == 0) {
        fprintf(stderr, "invalid max size\n");
        return 1;
    }
    cfg.max_size = (size_t)max_size;

    if (argc >= 4) {
        int r = atoi(argv[3]);
        if (r < 1 || r > 1000) {
            fprintf(stderr, "invalid rotations count\n");
            return 1;
        }
        cfg.rotations = r;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    cfg.current_fd = open_log_file(cfg.log_path);
    if (cfg.current_fd < 0) {
        perror("open_log_file");
        return 1;
    }

    int rc = daemon_loop(&cfg);

    close_fd(&cfg.current_fd);
    return rc;
}
