```c
// logd.c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_LOGS 64

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void dlog(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}

static int safe_rename(const char *oldp, const char *newp) {
    if (rename(oldp, newp) == 0) return 0;
    return -1;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int rotate_chain(const char *base, int keep) {
    char src[PATH_MAX];
    char dst[PATH_MAX];

    if (keep < 1 || keep > MAX_LOGS) {
        errno = EINVAL;
        return -1;
    }

    // Delete oldest if present: base.keep
    snprintf(src, sizeof(src), "%s.%d", base, keep);
    unlink(src);

    // Shift: base.(keep-1) -> base.keep ... base.1 -> base.2
    for (int i = keep - 1; i >= 1; --i) {
        snprintf(src, sizeof(src), "%s.%d", base, i);
        snprintf(dst, sizeof(dst), "%s.%d", base, i + 1);
        if (file_exists(src)) {
            if (safe_rename(src, dst) != 0) {
                perror("rename");
                return -1;
            }
        }
    }

    // base -> base.1
    snprintf(dst, sizeof(dst), "%s.1", base);
    if (file_exists(base)) {
        if (safe_rename(base, dst) != 0) {
            perror("rename base");
            return -1;
        }
    }

    return 0;
}

static int reopen_truncate(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open truncate");
        return -1;
    }
    close(fd);
    return 0;
}

static off_t get_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int rotate_log(const char *path, int keep, bool recreate) {
    if (rotate_chain(path, keep) != 0) return -1;
    if (recreate) {
        if (reopen_truncate(path) != 0) return -1;
    } else {
        // Create empty file if missing
        int fd = open(path, O_WRONLY | O_CREAT, 0644);
        if (fd < 0) {
            perror("open recreate");
            return -1;
        }
        close(fd);
    }
    return 0;
}

// Optional compression of rotated logs using gzip.
// This does not buffer file data in memory.
static int compress_file(const char *path) {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    }

    if (pid == 0) {
        // Child: gzip -f path
        execlp("gzip", "gzip", "-f", path, (char *)NULL);
        _exit(127);
    }

    int status;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) continue;
        perror("waitpid");
        return -1;
    }

    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        dlog("gzip failed for %s", path);
        return -1;
    }
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
            "Usage: %s <logfile> <max_bytes> <keep> <poll_sec> [--compress]\n",
            prog);
}

int main(int argc, char **argv) {
    if (argc < 5) {
        usage(argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    long long max_bytes = atoll(argv[2]);
    int keep = atoi(argv[3]);
    int poll_sec = atoi(argv[4]);
    bool compress = false;

    if (argc >= 6 && strcmp(argv[5], "--compress") == 0) {
        compress = true;
    }

    if (max_bytes <= 0 || keep <= 0 || poll_sec <= 0) {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Ensure log exists.
    int fd = open(logfile, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        perror("open logfile");
        return 1;
    }
    close(fd);

    dlog("logd started for %s", logfile);

    while (!g_stop) {
        off_t sz = get_size(logfile);
        if (sz < 0) {
            perror("stat logfile");
        } else if (sz >= (off_t)max_bytes) {
            dlog("rotating %s at size %lld", logfile, (long long)sz);

            if (rotate_log(logfile, keep, true) == 0) {
                if (compress) {
                    char rotated[PATH_MAX];
                    snprintf(rotated, sizeof(rotated), "%s.1", logfile);
                    if (compress_file(rotated) != 0) {
                        dlog("compression failed");
                    }
                }
            }
        }

        // Sleep in an interruptible way.
        for (int i = 0; i < poll_sec && !g_stop; ++i) {
            sleep(1);
        }
    }

    dlog("logd stopping");
    return 0;
}
