## Rust implementation

```rust
use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::thread;
use std::time::{Duration, SystemTime};

#[derive(Clone, Debug)]
pub struct RotationConfig {
    pub log_path: PathBuf,
    pub max_bytes: u64,
    pub keep_files: usize,
    pub poll_interval: Duration,
    pub buffer_size: usize,
}

impl RotationConfig {
    pub fn validate(&self) -> io::Result<()> {
        if self.max_bytes == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "max_bytes must be > 0",
            ));
        }
        if self.keep_files == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "keep_files must be > 0",
            ));
        }
        if self.buffer_size == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "buffer_size must be > 0",
            ));
        }
        Ok(())
    }
}

pub struct LogRotationDaemon {
    config: RotationConfig,
}

impl LogRotationDaemon {
    pub fn new(config: RotationConfig) -> io::Result<Self> {
        config.validate()?;
        Ok(Self { config })
    }

    pub fn run(&self) -> io::Result<()> {
        let mut buffer = vec![0u8; self.config.buffer_size];

        loop {
            if self.should_rotate()? {
                self.rotate_with_buffer(&mut buffer)?;
            }
            thread::sleep(self.config.poll_interval);
        }
    }

    fn should_rotate(&self) -> io::Result<bool> {
        match fs::metadata(&self.config.log_path) {
            Ok(meta) => Ok(meta.len() >= self.config.max_bytes),
            Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(false),
            Err(e) => Err(e),
        }
    }

    fn rotate_with_buffer(&self, buffer: &mut [u8]) -> io::Result<()> {
        // Remove oldest file if we exceed retention
        self.prune_oldest()?;

        // Shift existing rotated files upward:
        // app.log.3 -> app.log.4, app.log.2 -> app.log.3, etc.
        for i in (1..self.config.keep_files).rev() {
            let src = self.rotated_path(i);
            let dst = self.rotated_path(i + 1);
            if src.exists() {
                // Best-effort rename; if destination exists, remove it first.
                if dst.exists() {
                    fs::remove_file(&dst)?;
                }
                fs::rename(&src, &dst)?;
            }
        }

        // Move current log to .1
        if self.config.log_path.exists() {
            let first_rotated = self.rotated_path(1);
            if first_rotated.exists() {
                fs::remove_file(&first_rotated)?;
            }
            fs::rename(&self.config.log_path, &first_rotated)?;
        }

        // Recreate empty current log file
        let _ = OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&self.config.log_path)?;

        // Optional: nothing else to do here, but this is where you would
        // compress or post-process using the fixed buffer.
        let _ = buffer;

        Ok(())
    }

    fn prune_oldest(&self) -> io::Result<()> {
        let oldest = self.rotated_path(self.config.keep_files + 1);
        if oldest.exists() {
            fs::remove_file(oldest)?;
        }
        Ok(())
    }

    fn rotated_path(&self, idx: usize) -> PathBuf {
        let base = self.config.log_path.to_string_lossy().to_string();
        PathBuf::from(format!("{}.{}", base, idx))
    }
}

fn main() -> io::Result<()> {
    let config = RotationConfig {
        log_path: PathBuf::from("/var/log/myapp.log"),
        max_bytes: 10 * 1024 * 1024, // 10 MiB
        keep_files: 5,
        poll_interval: Duration::from_secs(2),
        buffer_size: 8 * 1024, // 8 KiB fixed buffer
    };

    let daemon = LogRotationDaemon::new(config)?;
    daemon.run()
}
```

