## 1) Minimal working C daemon

This version:

- Watches a single log file
- Rotates when it exceeds a size threshold
- Keeps a fixed number of rotated copies
- Uses **bounded memory** only
- Runs as a simple daemon loop with `sleep()`

### `minlogrot.c`

```c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#define BUF_SIZE 4096

static int copy_file(const char *src, const char *dst) {
    int in = open(src, O_RDONLY);
    if (in < 0) return -1;

    int out = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out < 0) {
        close(in);
        return -1;
    }

    char buf[BUF_SIZE];
    ssize_t r;
    while ((r = read(in, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(in);
                close(out);
                return -1;
            }
            off += w;
        }
    }

    close(in);
    close(out);
    return (r < 0) ? -1 : 0;
}

static int rotate_logs(const char *logfile, int keep) {
    char oldname[512];
    char newname[512];

    // Shift: logfile.(keep-1) -> logfile.keep ... logfile.1 -> logfile.2
    for (int i = keep - 1; i >= 1; --i) {
        snprintf(oldname, sizeof(oldname), "%s.%d", logfile, i);
        snprintf(newname, sizeof(newname), "%s.%d", logfile, i + 1);
        if (access(oldname, F_OK) == 0) {
            if (rename(oldname, newname) != 0) return -1;
        }
    }

    // Move current logfile -> logfile.1
    snprintf(newname, sizeof(newname), "%s.1", logfile);
    if (access(logfile, F_OK) == 0) {
        if (rename(logfile, newname) != 0) return -1;
    }

    // Create fresh logfile
    int fd = open(logfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static off_t get_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static void daemonize_simple(void) {
    pid_t pid = fork();
    if (pid < 0) exit(1);
    if (pid > 0) exit(0);

    if (setsid() < 0) exit(1);

    pid = fork();
    if (pid < 0) exit(1);
    if (pid > 0) exit(0);

    chdir("/");
    umask(027);

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <logfile> <max_bytes> <keep> [interval_sec]\n", argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    off_t max_bytes = (off_t)atoll(argv[2]);
    int keep = atoi(argv[3]);
    int interval = (argc >= 5) ? atoi(argv[4]) : 5;

    if (max_bytes <= 0 || keep < 1 || interval < 1) {
        fprintf(stderr, "Invalid arguments\n");
        return 1;
    }

    daemonize_simple();

    for (;;) {
        off_t sz = get_size(logfile);
        if (sz >= 0 && sz > max_bytes) {
            (void)rotate_logs(logfile, keep);
        }
        sleep((unsigned int)interval);
    }

    return 0;
}
```

