```c
#define _GNU_SOURCE
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/inotify.h>
#include <sys/select.h>
#include <fcntl.h>
#include <unistd.h>
#include <dirent.h>
#include <signal.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_PATH        256
#define MAX_NAME        128
#define MAX_BACKUPS     3
#define ROTATE_SIZE     (1024 * 1024)   /* 1 MiB */
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void on_signal(int sig) {
    (void)sig;
    running = 0;
}

static int ends_with(const char *s, const char *suffix) {
    size_t sl = strlen(s), su = strlen(suffix);
    return sl >= su && memcmp(s + sl - su, suffix, su) == 0;
}

static int rotate_file(const char *dir, const char *name) {
    char oldpath[MAX_PATH];
    char newpath[MAX_PATH];

    /* Shift backups: .2 -> .3, .1 -> .2 ... */
    for (int i = MAX_BACKUPS; i >= 1; --i) {
        snprintf(oldpath, sizeof(oldpath), "%s/%s.%d", dir, name, i);
        snprintf(newpath, sizeof(newpath), "%s/%s.%d", dir, name, i + 1);
        if (access(oldpath, F_OK) == 0) {
            rename(oldpath, newpath);
        }
    }

    /* Current log -> .1 */
    snprintf(oldpath, sizeof(oldpath), "%s/%s", dir, name);
    snprintf(newpath, sizeof(newpath), "%s/%s.1", dir, name);
    if (rename(oldpath, newpath) != 0) {
        return -1;
    }

    /* Recreate empty active log */
    int fd = open(oldpath, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void scan_and_rotate(const char *dir) {
    DIR *d = opendir(dir);
    if (!d) return;

    struct dirent *ent;
    char path[MAX_PATH];
    struct stat st;

    while ((ent = readdir(d)) != NULL) {
        if (ent->d_name[0] == '.') continue;
        if (!ends_with(ent->d_name, ".log")) continue;

        snprintf(path, sizeof(path), "%s/%s", dir, ent->d_name);
        if (stat(path, &st) == 0 && st.st_size >= ROTATE_SIZE) {
            rotate_file(dir, ent->d_name);
        }
    }

    closedir(d);
}

int main(int argc, char **argv) {
    const char *watch_dir = (argc > 1) ? argv[1] : "./logs";

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);

    while (running) {
        scan_and_rotate(watch_dir);
        sleep(POLL_INTERVAL_S);
    }

    return 0;
}
```

