## `logrotate_min.c`

```c
/*
 * Minimal memory-constrained log rotation daemon
 *
 * Features:
 * - Monitors a single log file
 * - Rotates when file size exceeds threshold
 * - Copies data in small fixed-size chunks
 * - Keeps memory usage low
 *
 * Build:
 *   cc -O2 -Wall -Wextra -o logrotate_min logrotate_min.c
 *
 * Usage:
 *   ./logrotate_min /var/log/myapp.log 10485760 5
 *
 * Args:
 *   argv[1] = path to log file
 *   argv[2] = rotate size in bytes
 *   argv[3] = number of backups to keep
 */

#define _XOPEN_SOURCE 700
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define BUF_SIZE 4096

static void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    return st.st_size;
}

static int copy_file(const char *src, const char *dst) {
    int in = -1, out = -1;
    char buf[BUF_SIZE];
    ssize_t r;

    in = open(src, O_RDONLY);
    if (in < 0) return -1;

    out = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out < 0) {
        close(in);
        return -1;
    }

    while ((r = read(in, buf, sizeof(buf))) > 0) {
        char *p = buf;
        while (r > 0) {
            ssize_t w = write(out, p, (size_t)r);
            if (w < 0) {
                if (errno == EINTR) continue;
                close(in);
                close(out);
                return -1;
            }
            p += w;
            r -= w;
        }
    }

    if (r < 0) {
        close(in);
        close(out);
        return -1;
    }

    if (fsync(out) < 0) {
        close(in);
        close(out);
        return -1;
    }

    close(in);
    close(out);
    return 0;
}

static int rotate_logs(const char *path, int backups) {
    char oldname[PATH_MAX];
    char newname[PATH_MAX];

    if (backups < 1) return 0;

    for (int i = backups - 1; i >= 1; --i) {
        snprintf(oldname, sizeof(oldname), "%s.%d", path, i);
        snprintf(newname, sizeof(newname), "%s.%d", path, i + 1);
        rename(oldname, newname);
    }

    snprintf(newname, sizeof(newname), "%s.1", path);
    if (rename(path, newname) < 0) {
        return -1;
    }

    /* Recreate empty log file */
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <logfile> <rotate_size_bytes> <backups>\n", prog);
    exit(EXIT_FAILURE);
}

int main(int argc, char **argv) {
    if (argc != 4) usage(argv[0]);

    const char *logfile = argv[1];
    off_t rotate_size = (off_t)strtoll(argv[2], NULL, 10);
    int backups = atoi(argv[3]);

    if (rotate_size <= 0 || backups < 0) usage(argv[0]);

    /* Ensure logfile exists */
    int fd = open(logfile, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) die("open logfile");
    close(fd);

    /* Minimal polling loop */
    for (;;) {
        off_t sz = file_size(logfile);
        if (sz < 0) {
            sleep(1);
            continue;
        }

        if (sz >= rotate_size) {
            if (rotate_logs(logfile, backups) < 0) {
                fprintf(stderr, "rotation failed: %s\n", strerror(errno));
            }
        }

        sleep(1);
    }

    return 0;
}
