#define _POSIX_C_SOURCE 200809L

#include <sys/types.h>
#include <sys/stat.h>
#include <sys/inotify.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <signal.h>
#include <time.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_BACKUPS 9
#define BUF_SIZE 4096

static volatile sig_atomic_t running = 1;

static void on_signal(int sig) {
    (void)sig;
    running = 0;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *size_out = st.st_size;
    return 0;
}

static int rotate_logs(const char *path, int backups) {
    char src[PATH_MAX];
    char dst[PATH_MAX];

    if (backups < 1) backups = 1;
    if (backups > MAX_BACKUPS) backups = MAX_BACKUPS;

    for (int i = backups - 1; i >= 1; --i) {
        snprintf(src, sizeof(src), "%s.%d", path, i);
        snprintf(dst, sizeof(dst), "%s.%d", path, i + 1);

        if (access(src, F_OK) == 0) {
            if (rename(src, dst) != 0 && errno != ENOENT) {
                return -1;
            }
        }
    }

    snprintf(dst, sizeof(dst), "%s.1", path);
    if (access(path, F_OK) == 0) {
        if (rename(path, dst) != 0) {
            return -1;
        }
    }

    return 0;
}

static int reopen_log(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;
    return fd;
}

static int watch_file(const char *path, off_t max_bytes, int backups) {
    int inotify_fd = -1;
    int watch_fd = -1;
    int log_fd = -1;
    char buf[BUF_SIZE];
    char logpath[PATH_MAX];

    strncpy(logpath, path, sizeof(logpath) - 1);
    logpath[sizeof(logpath) - 1] = '\0';

    log_fd = reopen_log(logpath);
    if (log_fd < 0) return -1;

    inotify_fd = inotify_init1(IN_NONBLOCK);
    if (inotify_fd < 0) {
        close(log_fd);
        return -1;
    }

    watch_fd = inotify_add_watch(inotify_fd, logpath, IN_MODIFY | IN_ATTRIB | IN_MOVE_SELF | IN_DELETE_SELF);
    if (watch_fd < 0) {
        close(inotify_fd);
        close(log_fd);
        return -1;
    }

    while (running) {
        ssize_t n = read(inotify_fd, buf, sizeof(buf));
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                off_t sz = 0;
                if (file_size(logpath, &sz) == 0 && sz >= max_bytes) {
                    close(log_fd);
                    if (rotate_logs(logpath, backups) != 0) {
                        return -1;
                    }
                    log_fd = reopen_log(logpath);
                    if (log_fd < 0) return -1;

                    inotify_rm_watch(inotify_fd, watch_fd);
                    watch_fd = inotify_add_watch(inotify_fd, logpath,
                                                 IN_MODIFY | IN_ATTRIB | IN_MOVE_SELF | IN_DELETE_SELF);
                    if (watch_fd < 0) return -1;
                }

                struct timespec ts = { .tv_sec = 1, .tv_nsec = 0 };
                nanosleep(&ts, NULL);
                continue;
            }
            break;
        }

        if (n == 0) continue;

        // Drain events; we only need to re-check size.
        off_t sz = 0;
        if (file_size(logpath, &sz) == 0 && sz >= max_bytes) {
            close(log_fd);
            if (rotate_logs(logpath, backups) != 0) {
                return -1;
            }
            log_fd = reopen_log(logpath);
            if (log_fd < 0) return -1;

            inotify_rm_watch(inotify_fd, watch_fd);
            watch_fd = inotify_add_watch(inotify_fd, logpath,
                                         IN_MODIFY | IN_ATTRIB | IN_MOVE_SELF | IN_DELETE_SELF);
            if (watch_fd < 0) return -1;
        }
    }

    if (watch_fd >= 0) inotify_rm_watch(inotify_fd, watch_fd);
    if (inotify_fd >= 0) close(inotify_fd);
    if (log_fd >= 0) close(log_fd);

    return 0;
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "usage: %s <logfile> <max_bytes> <backups>\n", argv[0]);
        return 1;
    }

    const char *path = argv[1];
    off_t max_bytes = (off_t)strtoll(argv[2], NULL, 10);
    int backups = atoi(argv[3]);

    if (max_bytes <= 0 || backups <= 0) {
        fprintf(stderr, "invalid arguments\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0) return 1;
    if (sigaction(SIGTERM, &sa, NULL) != 0) return 1;

    if (watch_file(path, max_bytes, backups) != 0) {
        perror("logrotated");
        return 1;
    }

    return 0;
}
