#define _GNU_SOURCE
#include <sys/inotify.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/sendfile.h>
#include <sys/time.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <stdint.h>

#define MAX_PATH_LEN   256
#define MAX_EVENT_BUF   4096
#define MAX_BACKUPS     3
#define ROTATE_LIMIT    (1024 * 1024)   // 1 MiB
#define POLL_USEC       200000          // 200 ms

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int open_log(const char *path) {
    return open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    return st.st_size;
}

static int rotate_logs(const char *path) {
    char oldp[MAX_PATH_LEN];
    char newp[MAX_PATH_LEN];

    // Shift backups: log.2 -> log.3, log.1 -> log.2, log -> log.1
    for (int i = MAX_BACKUPS - 1; i >= 1; --i) {
        snprintf(oldp, sizeof(oldp), "%s.%d", path, i);
        snprintf(newp, sizeof(newp), "%s.%d", path, i + 1);
        (void)rename(oldp, newp); // ignore missing files
    }

    snprintf(newp, sizeof(newp), "%s.1", path);
    if (rename(path, newp) < 0) {
        if (errno != ENOENT) return -1;
    }
    return 0;
}

int main(int argc, char **argv) {
    const char *log_path;
    int fd = -1, infd = -1, wd = -1;
    char evbuf[MAX_EVENT_BUF];

    if (argc != 2) {
        fprintf(stderr, "usage: %s /path/to/logfile\n", argv[0]);
        return 1;
    }
    log_path = argv[1];

    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal;

    // Ensure log file exists
    fd = open_log(log_path);
    if (fd < 0) {
        perror("open");
        return 1;
    }
    close(fd);

    infd = inotify_init1(IN_NONBLOCK);
    if (infd < 0) {
        perror("inotify_init1");
        return 1;
    }

    wd = inotify_add_watch(infd, log_path, IN_MODIFY | IN_CLOSE_WRITE | IN_MOVE_SELF | IN_DELETE_SELF);
    if (wd < 0) {
        perror("inotify_add_watch");
        close(infd);
        return 1;
    }

    while (!g_stop) {
        ssize_t len = read(infd, evbuf, sizeof(evbuf));
        if (len < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(POLL_USEC);
                continue;
            }
            perror("read(inotify)");
            break;
        }

        // Check current size after activity
        off_t sz = file_size(log_path);
        if (sz < 0) {
            // File may have been moved/deleted; try to recreate later
            usleep(POLL_USEC);
            continue;
        }

        if (sz >= ROTATE_LIMIT) {
            // Rotate current file
            close(fd);
            if (rotate_logs(log_path) < 0) {
                perror("rotate_logs");
                break;
            }

            fd = open_log(log_path);
            if (fd < 0) {
                perror("reopen log");
                break;
            }

            // Re-add watch because file was renamed
            inotify_rm_watch(infd, wd);
            wd = inotify_add_watch(infd, log_path, IN_MODIFY | IN_CLOSE_WRITE | IN_MOVE_SELF | IN_DELETE_SELF);
            if (wd < 0) {
                perror("inotify_add_watch(reopen)");
                break;
            }
        }
    }

    if (wd >= 0) inotify_rm_watch(infd, wd);
    if (fd >= 0) close(fd);
    if (infd >= 0) close(infd);

    return 0;
}
