#define _GNU_SOURCE
#include <sys/inotify.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/sendfile.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <stdlib.h>

#define BUF_SIZE 4096
#define MAX_PATH 256
#define MAX_COPIES 5

static int copy_file(const char *src, const char *dst) {
    int in = -1, out = -1;
    struct stat st;
    off_t offset = 0;
    ssize_t n;

    in = open(src, O_RDONLY);
    if (in < 0) return -1;

    if (fstat(in, &st) < 0) {
        close(in);
        return -1;
    }

    out = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out < 0) {
        close(in);
        return -1;
    }

    while (offset < st.st_size) {
        n = sendfile(out, in, &offset, st.st_size - offset);
        if (n < 0) {
            if (errno == EINTR) continue;
            close(in);
            close(out);
            return -1;
        }
        if (n == 0) break;
    }

    close(in);
    close(out);
    return 0;
}

static int rotate_logs(const char *path) {
    char oldname[MAX_PATH];
    char newname[MAX_PATH];
    int i;

    for (i = MAX_COPIES - 1; i >= 1; --i) {
        snprintf(oldname, sizeof(oldname), "%s.%d", path, i);
        snprintf(newname, sizeof(newname), "%s.%d", path, i + 1);
        unlink(newname);
        rename(oldname, newname);
    }

    snprintf(newname, sizeof(newname), "%s.1", path);
    unlink(newname);
    if (rename(path, newname) < 0) return -1;

    return 0;
}

static off_t get_size(const char *path) {
    struct stat st;
    if (stat(path, &st) < 0) return -1;
    return st.st_size;
}

int main(int argc, char **argv) {
    const char *logpath;
    off_t max_size;
    int inofd, wd;
    char buf[BUF_SIZE];

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <logfile> <max_size_bytes>\n", argv[0]);
        return 1;
    }

    logpath = argv[1];
    max_size = atoll(argv[2]);
    if (max_size <= 0) {
        fprintf(stderr, "Invalid max size\n");
        return 1;
    }

    inofd = inotify_init1(IN_NONBLOCK);
    if (inofd < 0) {
        perror("inotify_init1");
        return 1;
    }

    wd = inotify_add_watch(inofd, logpath, IN_MODIFY | IN_MOVE_SELF | IN_DELETE_SELF);
    if (wd < 0) {
        perror("inotify_add_watch");
        close(inofd);
        return 1;
    }

    while (1) {
        ssize_t len = read(inofd, buf, sizeof(buf));
        if (len < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                usleep(500000);
                if (get_size(logpath) > max_size) {
                    if (rotate_logs(logpath) == 0) {
                        int fd = open(logpath, O_CREAT | O_WRONLY | O_TRUNC, 0644);
                        if (fd >= 0) close(fd);
                        inotify_rm_watch(inofd, wd);
                        wd = inotify_add_watch(inofd, logpath, IN_MODIFY | IN_MOVE_SELF | IN_DELETE_SELF);
                    }
                }
                continue;
            }
            perror("read");
            break;
        }

        if (get_size(logpath) > max_size) {
            if (rotate_logs(logpath) == 0) {
                int fd = open(logpath, O_CREAT | O_WRONLY | O_TRUNC, 0644);
                if (fd >= 0) close(fd);
                inotify_rm_watch(inofd, wd);
                wd = inotify_add_watch(inofd, logpath, IN_MODIFY | IN_MOVE_SELF | IN_DELETE_SELF);
            }
        }
    }

    close(inofd);
    return 0;
}
