## `logrotated.c`

```c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>

#define MAX_PATH_LEN 256
#define COPY_BUF_SIZE 4096
#define ROTATE_BACKUPS 5

typedef struct {
    char log_path[MAX_PATH_LEN];
    size_t max_size;
    int interval_sec;
} Config;

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int rename_rotation(const char *base, int idx) {
    char src[MAX_PATH_LEN];
    char dst[MAX_PATH_LEN];

    if (snprintf(src, sizeof(src), "%s.%d", base, idx) >= (int)sizeof(src)) return -1;
    if (snprintf(dst, sizeof(dst), "%s.%d", base, idx + 1) >= (int)sizeof(dst)) return -1;

    if (access(src, F_OK) == 0) {
        if (rename(src, dst) != 0) return -1;
    }
    return 0;
}

static int rotate_log(const char *path) {
    char rotated[MAX_PATH_LEN];
    char src[MAX_PATH_LEN];
    char dst[MAX_PATH_LEN];

    // Remove oldest backup
    if (snprintf(rotated, sizeof(rotated), "%s.%d", path, ROTATE_BACKUPS) >= (int)sizeof(rotated))
        return -1;
    unlink(rotated);

    // Shift backups: .4 -> .5, .3 -> .4, ...
    for (int i = ROTATE_BACKUPS - 1; i >= 1; --i) {
        if (rename_rotation(path, i) != 0) {
            // Continue best-effort; ignore missing files
        }
    }

    // Rename current log to .1
    if (snprintf(src, sizeof(src), "%s", path) >= (int)sizeof(src)) return -1;
    if (snprintf(dst, sizeof(dst), "%s.1", path) >= (int)sizeof(dst)) return -1;

    if (access(src, F_OK) == 0) {
        if (rename(src, dst) != 0) return -1;
    }

    // Recreate empty log file
    int fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int copy_file(const char *src_path, const char *dst_path) {
    int src = open(src_path, O_RDONLY);
    if (src < 0) return -1;

    int dst = open(dst_path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (dst < 0) {
        close(src);
        return -1;
    }

    char buf[COPY_BUF_SIZE];
    ssize_t n;
    while ((n = read(src, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < n) {
            ssize_t w = write(dst, buf + off, (size_t)(n - off));
            if (w < 0) {
                close(src);
                close(dst);
                return -1;
            }
            off += w;
        }
    }

    close(src);
    close(dst);
    return (n < 0) ? -1 : 0;
}

static int usage(const char *prog) {
    fprintf(stderr, "Usage: %s <logfile> <max_size_bytes> <interval_sec>\n", prog);
    return 1;
}

int main(int argc, char **argv) {
    if (argc != 4) return usage(argv[0]);

    Config cfg;
    memset(&cfg, 0, sizeof(cfg));

    if (strlen(argv[1]) >= MAX_PATH_LEN) {
        fprintf(stderr, "Path too long\n");
        return 1;
    }

    strncpy(cfg.log_path, argv[1], MAX_PATH_LEN - 1);
    cfg.max_size = (size_t)strtoull(argv[2], NULL, 10);
    cfg.interval_sec = atoi(argv[3]);

    if (cfg.max_size == 0 || cfg.interval_sec <= 0) {
        fprintf(stderr, "Invalid max size or interval\n");
        return 1;
    }

    // Ensure log file exists
    int fd = open(cfg.log_path, O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }
    close(fd);

    for (;;) {
        off_t sz = file_size(cfg.log_path);
        if (sz < 0) {
            // If file disappeared, recreate it
            fd = open(cfg.log_path, O_CREAT | O_WRONLY, 0644);
            if (fd >= 0) close(fd);
        } else if ((size_t)sz >= cfg.max_size) {
            if (rotate_log(cfg.log_path) != 0) {
                perror("rotate_log");
                // Best effort; keep running
            }
        }

        sleep((unsigned int)cfg.interval_sec);
    }

    return 0;
}
