```go
package main

import (
	"bufio"
	"compress/gzip"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"time"
)

type Config struct {
	LogPath       string
	MaxSizeBytes   int64
	Keep          int
	Compress      bool
	PollInterval  time.Duration
	BufferSize    int
}

func main() {
	var cfg Config

	flag.StringVar(&cfg.LogPath, "log", "/var/log/app.log", "path to the active log file")
	flag.Int64Var(&cfg.MaxSizeBytes, "max-size", 10*1024*1024, "rotate when file exceeds this size")
	flag.IntVar(&cfg.Keep, "keep", 5, "number of rotated logs to keep")
	flag.BoolVar(&cfg.Compress, "compress", false, "gzip old rotated logs")
	flag.DurationVar(&cfg.PollInterval, "poll", 1*time.Second, "poll interval")
	flag.IntVar(&cfg.BufferSize, "buf", 32*1024, "I/O buffer size")
	flag.Parse()

	// Keep runtime memory behavior simple and predictable.
	runtime.GOMAXPROCS(1)
	debugSetMemoryLimits()

	if err := run(cfg); err != nil {
		log.Fatal(err)
	}
}

func debugSetMemoryLimits() {
	// No-op placeholder: in production, enforce memory via cgroups/container limits.
	// This code intentionally avoids runtime heap growth patterns.
}

func run(cfg Config) error {
	if cfg.Keep < 1 {
		cfg.Keep = 1
	}
	if cfg.BufferSize < 4*1024 {
		cfg.BufferSize = 4 * 1024
	}

	dir := filepath.Dir(cfg.LogPath)
	base := filepath.Base(cfg.LogPath)

	for {
		if err := rotateIfNeeded(cfg, dir, base); err != nil {
			return err
		}
		time.Sleep(cfg.PollInterval)
	}
}

func rotateIfNeeded(cfg Config, dir, base string) error {
	fi, err := os.Stat(cfg.LogPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	if fi.Size() < cfg.MaxSizeBytes {
		return nil
	}

	ts := time.Now().UTC().Format("20060102T150405Z")
	rotated := filepath.Join(dir, fmt.Sprintf("%s.%s", base, ts))

	// Rename active log away. Writers should reopen externally if needed.
	if err := os.Rename(cfg.LogPath, rotated); err != nil {
		return err
	}

	// Recreate empty active log.
	f, err := os.OpenFile(cfg.LogPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
	if err != nil {
		return err
	}
	f.Close()

	if cfg.Compress {
		if err := gzipFile(rotated, rotated+".gz", cfg.BufferSize); err != nil {
			return err
		}
		_ = os.Remove(rotated)
	}

	if err := cleanupOld(dir, base, cfg.Keep, cfg.Compress); err != nil {
		return err
	}

	return nil
}

func gzipFile(src, dst string, bufSize int) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()

	gz := gzip.NewWriter(out)
	defer gz.Close()

	buf := make([]byte, bufSize)
	_, err = io.CopyBuffer(gz, in, buf)
	return err
}

func cleanupOld(dir, base string, keep int, compressed bool) error {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}

	type item struct {
		name string
		ts   string
	}
	var matches []item

	prefix := base + "."
	for _, e := range entries {
		name := e.Name()
		if !strings.HasPrefix(name, prefix) {
			continue
		}
		if compressed {
			if !strings.HasSuffix(name, ".gz") {
				continue
			}
		} else {
			if strings.HasSuffix(name, ".gz") {
				continue
			}
		}
		ts := strings.TrimSuffix(strings.TrimPrefix(name, prefix), ".gz")
		matches = append(matches, item{name: name, ts: ts})
	}

	// Simple lexicographic sort by timestamp string.
	for i := 0; i < len(matches); i++ {
		for j := i + 1; j < len(matches); j++ {
			if matches[j].ts < matches[i].ts {
				matches[i], matches[j] = matches[j], matches[i]
			}
		}
	}

	if len(matches) <= keep {
		return nil
	}

	for _, m := range matches[:len(matches)-keep] {
		_ = os.Remove(filepath.Join(dir, m.name))
	}

	return nil
}

// Optional helper for line-based log copying if you want to extend this daemon.
func streamLines(r io.Reader, w io.Writer, bufSize int) error {
	br := bufio.NewReaderSize(r, bufSize)
	bw := bufio.NewWriterSize(w, bufSize)
	defer bw.Flush()

	for {
		line, err := br.ReadString('\n')
		if len(line) > 0 {
			if _, werr := bw.WriteString(line); werr != nil {
				return werr
			}
		}
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return err
		}
	}
}

// Parse helper if you want size args like "10M", "512K".
func parseSize(s string) (int64, error) {
	s = strings.TrimSpace(strings.ToUpper(s))
	mult := int64(1)
	switch {
	case strings.HasSuffix(s, "K"):
		mult = 1024
		s = strings.TrimSuffix(s, "K")
	case strings.HasSuffix(s, "M"):
		mult = 1024 * 1024
		s = strings.TrimSuffix(s, "M")
	case strings.HasSuffix(s, "G"):
		mult = 1024 * 1024 * 1024
		s = strings.TrimSuffix(s, "G")
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, err
	}
	return v * mult, nil
}
