```rust
use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use parking_lot::RwLock;
use serde::Serialize;
use std::convert::Infallible;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{Duration, Instant};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, RefreshKind, System};
use tokio::net::TcpListener;
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Clone)]
struct Thresholds {
    cpu_warn: f32,
    mem_warn: f32,
    disk_warn: f32,
    load_warn: f32,
}

#[derive(Default, Clone, Serialize)]
struct Metrics {
    timestamp_ms: u128,
    cpu_usage: f32,
    memory_used_percent: f32,
    disk_used_percent: f32,
    load_avg_1m: f32,
}

struct SharedState {
    metrics: RwLock<Metrics>,
    thresholds: Thresholds,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let thresholds = Thresholds {
        cpu_warn: 85.0,
        mem_warn: 90.0,
        disk_warn: 90.0,
        load_warn: 4.0,
    };

    let state = Arc::new(SharedState {
        metrics: RwLock::new(Metrics::default()),
        thresholds,
    });

    let monitor_state = state.clone();
    tokio::spawn(async move {
        monitor_loop(monitor_state).await;
    });

    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    run_http_server(addr, state).await?;
    Ok(())
}

async fn monitor_loop(state: Arc<SharedState>) {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything()),
    );

    let mut ticker = interval(Duration::from_secs(2));

    loop {
        ticker.tick().await;

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_disks_list();
        sys.refresh_disks();

        let cpu_usage = sys.global_cpu_usage();

        let total_mem = sys.total_memory() as f32;
        let used_mem = sys.used_memory() as f32;
        let memory_used_percent = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let mut disk_total = 0u128;
        let mut disk_used = 0u128;
        for disk in sys.disks() {
            let total = disk.total_space() as u128;
            let avail = disk.available_space() as u128;
            disk_total += total;
            disk_used += total.saturating_sub(avail);
        }
        let disk_used_percent = if disk_total > 0 {
            (disk_used as f32 / disk_total as f32) * 100.0
        } else {
            0.0
        };

        let load_avg_1m = match sysinfo::System::load_average() {
            load => load.one as f32,
        };

        let metrics = Metrics {
            timestamp_ms: Instant::now().elapsed().as_millis(),
            cpu_usage,
            memory_used_percent,
            disk_used_percent,
            load_avg_1m,
        };

        {
            let mut guard = state.metrics.write();
            *guard = metrics.clone();
        }

        if cpu_usage >= state.thresholds.cpu_warn {
            warn!("CPU usage high: {:.1}%", cpu_usage);
        }
        if memory_used_percent >= state.thresholds.mem_warn {
            warn!("Memory usage high: {:.1}%", memory_used_percent);
        }
        if disk_used_percent >= state.thresholds.disk_warn {
            warn!("Disk usage high: {:.1}%", disk_used_percent);
        }
        if load_avg_1m >= state.thresholds.load_warn {
            warn!("Load average high: {:.2}", load_avg_1m);
        }

        info!(
            "metrics: cpu={:.1}% mem={:.1}% disk={:.1}% load1={:.2}",
            cpu_usage, memory_used_percent, disk_used_percent, load_avg_1m
        );
    }
}

async fn run_http_server(addr: SocketAddr, state: Arc<SharedState>) -> anyhow::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    info!("HTTP server listening on http://{}", addr);

    loop {
        let (stream, _) = listener.accept().await?;
        let io = TokioIo::new(stream);
        let st = state.clone();

        tokio::spawn(async move {
            let svc = service_fn(move |req| {
                let st2 = st.clone();
                async move { handle_request(req, st2).await }
            });

            if let Err(err) = hyper::server::conn::http1::Builder::new()
                .serve_connection(io, svc)
                .await
            {
                tracing::warn!("connection error: {}", err);
            }
        });
    }
}

async fn handle_request(
    req: Request<Incoming>,
    state: Arc<SharedState>,
) -> Result<Response<Full<Bytes>>, Infallible> {
    match (req.method(), req.uri().path()) {
        (&Method::GET, "/health") => Ok(text_response("ok\n")),
        (&Method::GET, "/metrics") => {
            let metrics = state.metrics.read().clone();
            match serde_json::to_string_pretty(&metrics) {
                Ok(json) => Ok(json_response(json)),
                Err(_) => Ok(internal_error()),
            }
        }
        _ => Ok(not_found()),
    }
}

fn text_response(body: &str) -> Response<Full<Bytes>> {
    Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from(body.to_string())))
        .unwrap()
}

fn json_response(body: String) -> Response<Full<Bytes>> {
    Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "application/json")
        .body(Full::new(Bytes::from(body)))
        .unwrap()
}

fn not_found() -> Response<Full<Bytes>> {
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .body(Full::new(Bytes::from("not found\n")))
        .unwrap()
}

fn internal_error() -> Response<Full<Bytes>> {
    Response::builder()
        .status(StatusCode::INTERNAL_SERVER_ERROR)
        .body(Full::new(Bytes::from("internal error\n")))
        .unwrap()
}
