```rust
use anyhow::Result;
use parking_lot::RwLock;
use serde::Serialize;
use std::{
    convert::Infallible,
    net::SocketAddr,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::{signal, task, time};
use tracing::{error, info, warn};
use warp::Filter;

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    timestamp_ms: u128,
    uptime_secs: u64,
    cpu_usage_percent: f32,
    total_memory_kb: u64,
    used_memory_kb: u64,
    total_swap_kb: u64,
    used_swap_kb: u64,
    disks: Vec<DiskMetrics>,
    top_processes: Vec<ProcessMetrics>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskMetrics {
    name: String,
    mount_point: String,
    total_space_bytes: u64,
    available_space_bytes: u64,
    file_system: String,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessMetrics {
    pid: i32,
    name: String,
    cpu_usage_percent: f32,
    memory_kb: u64,
}

#[derive(Clone)]
struct SharedState {
    metrics: Arc<RwLock<Option<Metrics>>>,
}

impl SharedState {
    fn new() -> Self {
        Self {
            metrics: Arc::new(RwLock::new(None)),
        }
    }
}

struct Monitor {
    system: System,
    start: Instant,
}

impl Monitor {
    fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self {
            system,
            start: Instant::now(),
        }
    }

    fn collect(&mut self) -> Metrics {
        // Refresh only what we need for lower overhead
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.system.refresh_processes();

        let cpu_usage_percent = self.system.global_cpu_info().cpu_usage();
        let total_memory_kb = self.system.total_memory();
        let used_memory_kb = self.system.used_memory();
        let total_swap_kb = self.system.total_swap();
        let used_swap_kb = self.system.used_swap();
        let uptime_secs = self.start.elapsed().as_secs();

        let disks = self
            .system
            .disks()
            .iter()
            .map(|d| DiskMetrics {
                name: d.name().to_string_lossy().to_string(),
                mount_point: d.mount_point().to_string_lossy().to_string(),
                total_space_bytes: d.total_space(),
                available_space_bytes: d.available_space(),
                file_system: String::from_utf8_lossy(d.file_system()).to_string(),
            })
            .collect::<Vec<_>>();

        // Keep top N processes by CPU usage to avoid large responses
        let mut processes = self
            .system
            .processes()
            .iter()
            .map(|(pid, p)| ProcessMetrics {
                pid: pid.as_u32() as i32,
                name: p.name().to_string(),
                cpu_usage_percent: p.cpu_usage(),
                memory_kb: p.memory(),
            })
            .collect::<Vec<_>>();

        processes.sort_by(|a, b| {
            b.cpu_usage_percent
                .partial_cmp(&a.cpu_usage_percent)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        processes.truncate(10);

        Metrics {
            timestamp_ms: self.start.elapsed().as_millis(),
            uptime_secs,
            cpu_usage_percent,
            total_memory_kb,
            used_memory_kb,
            total_swap_kb,
            used_swap_kb,
            disks,
            top_processes: processes,
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let addr: SocketAddr = "127.0.0.1:8080".parse()?;
    let poll_interval = Duration::from_secs(2);
    let shared = SharedState::new();

    let monitor_shared = shared.clone();
    let monitor_task = task::spawn(async move {
        let mut monitor = Monitor::new();
        let mut ticker = time::interval(poll_interval);

        loop {
            ticker.tick().await;
            let metrics = monitor.collect();

            if metrics.cpu_usage_percent > 90.0 {
                warn!(
                    "high CPU usage detected: {:.2}%",
                    metrics.cpu_usage_percent
                );
            }

            if metrics.used_memory_kb > (metrics.total_memory_kb as f32 * 0.90) as u64 {
                warn!(
                    "high memory usage detected: {}/{} KB",
                    metrics.used_memory_kb, metrics.total_memory_kb
                );
            }

            *monitor_shared.metrics.write() = Some(metrics);
        }
    });

    let metrics_route = {
        let shared = shared.clone();
        warp::path("metrics")
            .and(warp::get())
            .and_then(move || {
                let shared = shared.clone();
                async move {
                    let guard = shared.metrics.read();
                    let reply = if let Some(metrics) = &*guard {
                        warp::reply::json(metrics)
                    } else {
                        warp::reply::json(&serde_json::json!({
                            "status": "starting",
                            "message": "metrics not yet available"
                        }))
                    };
                    Ok::<_, Infallible>(reply)
                }
            })
    };

    let health_route = warp::path("health")
        .and(warp::get())
        .map(|| warp::reply::json(&serde_json::json!({ "ok": true })));

    let routes = metrics_route.or(health_route);

    info!("starting daemon on http://{}", addr);

    let server = warp::serve(routes).run(addr);

    tokio::select! {
        _ = server => {},
        _ = monitor_task => {
            error!("monitor task exited unexpectedly");
        }
        _ = wait_for_shutdown() => {
            info!("shutdown requested");
        }
    }

    Ok(())
}

async fn wait_for_shutdown() {
    #[cfg(unix)]
    {
        let mut sigterm = signal::unix::signal(signal::unix::SignalKind::terminate())
            .expect("failed to install SIGTERM handler");
        tokio::select! {
            _ = signal::ctrl_c() => {},
            _ = sigterm.recv() => {},
        }
    }

    #[cfg(not(unix))]
    {
        let _ = signal::ctrl_c().await;
    }
}
```

