use anyhow::{Context, Result};
use serde::Serialize;
use std::{
    collections::HashMap,
    fs,
    io::{self, Read},
    path::Path,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tokio::time::interval;
use tracing::{error, info, warn};

#[derive(Debug, Clone)]
struct Config {
    poll_interval: Duration,
    cpu_high_watermark: f32,
    mem_high_watermark: f32,
    disk_high_watermark: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval: Duration::from_secs(5),
            cpu_high_watermark: 0.90,
            mem_high_watermark: 0.90,
            disk_high_watermark: 0.90,
        }
    }
}

#[derive(Debug, Serialize)]
struct Telemetry {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    memory_total_kb: u64,
    memory_available_kb: u64,
    memory_used_percent: f32,
    load1: f32,
    load5: f32,
    load15: f32,
    disk_root_used_percent: f32,
    net_rx_bytes: u64,
    net_tx_bytes: u64,
}

#[derive(Debug, Clone)]
struct CpuSnapshot {
    total: u64,
    idle: u64,
}

#[derive(Debug)]
struct ResourceMonitor {
    prev_cpu: Option<CpuSnapshot>,
}

impl ResourceMonitor {
    fn new() -> Self {
        Self { prev_cpu: None }
    }

    fn collect(&mut self) -> Result<Telemetry> {
        let timestamp_unix_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();

        let cpu_usage_percent = self.cpu_usage_percent()?;
        let (memory_total_kb, memory_available_kb) = self.meminfo()?;
        let memory_used_percent = if memory_total_kb == 0 {
            0.0
        } else {
            1.0 - (memory_available_kb as f32 / memory_total_kb as f32)
        };

        let (load1, load5, load15) = self.loadavg()?;
        let disk_root_used_percent = self.disk_used_percent(Path::new("/"))?;
        let (net_rx_bytes, net_tx_bytes) = self.net_counters()?;

        Ok(Telemetry {
            timestamp_unix_ms,
            cpu_usage_percent,
            memory_total_kb,
            memory_available_kb,
            memory_used_percent,
            load1,
            load5,
            load15,
            disk_root_used_percent,
            net_rx_bytes,
            net_tx_bytes,
        })
    }

    fn cpu_usage_percent(&mut self) -> Result<f32> {
        let snap = self.read_cpu_snapshot()?;
        let usage = if let Some(prev) = &self.prev_cpu {
            let total_delta = snap.total.saturating_sub(prev.total);
            let idle_delta = snap.idle.saturating_sub(prev.idle);
            if total_delta == 0 {
                0.0
            } else {
                let busy = total_delta.saturating_sub(idle_delta);
                (busy as f32 / total_delta as f32) * 100.0
            }
        } else {
            0.0
        };
        self.prev_cpu = Some(snap);
        Ok(usage)
    }

    fn read_cpu_snapshot(&self) -> Result<CpuSnapshot> {
        let content = fs::read_to_string("/proc/stat").context("reading /proc/stat")?;
        let line = content
            .lines()
            .find(|l| l.starts_with("cpu "))
            .context("missing aggregate cpu line")?;

        let mut parts = line.split_whitespace();
        parts.next(); // "cpu"

        let mut values = Vec::new();
        for p in parts {
            values.push(p.parse::<u64>().context("parsing cpu field")?);
        }

        let idle = values.get(3).copied().unwrap_or(0) + values.get(4).copied().unwrap_or(0);
        let total: u64 = values.iter().sum();

        Ok(CpuSnapshot { total, idle })
    }

    fn meminfo(&self) -> Result<(u64, u64)> {
        let content = fs::read_to_string("/proc/meminfo").context("reading /proc/meminfo")?;
        let mut total = None;
        let mut available = None;

        for line in content.lines() {
            if let Some(rest) = line.strip_prefix("MemTotal:") {
                total = Some(parse_kb_line(rest)?);
            } else if let Some(rest) = line.strip_prefix("MemAvailable:") {
                available = Some(parse_kb_line(rest)?);
            }
        }

        Ok((
            total.context("MemTotal missing")?,
            available.context("MemAvailable missing")?,
        ))
    }

    fn loadavg(&self) -> Result<(f32, f32, f32)> {
        let content = fs::read_to_string("/proc/loadavg").context("reading /proc/loadavg")?;
        let mut parts = content.split_whitespace();
        let l1 = parts.next().context("load1 missing")?.parse()?;
        let l5 = parts.next().context("load5 missing")?.parse()?;
        let l15 = parts.next().context("load15 missing")?.parse()?;
        Ok((l1, l5, l15))
    }

    fn disk_used_percent(&self, path: &Path) -> Result<f32> {
        let stat = nix::sys::statvfs::statvfs(path).context("statvfs failed")?;
        let total = stat.blocks();
        let free = stat.blocks_free();
        if total == 0 {
            return Ok(0.0);
        }
        let used = total.saturating_sub(free);
        Ok((used as f32 / total as f32) * 100.0)
    }

    fn net_counters(&self) -> Result<(u64, u64)> {
        let content = fs::read_to_string("/proc/net/dev").context("reading /proc/net/dev")?;
        let mut rx = 0u64;
        let mut tx = 0u64;

        for line in content.lines().skip(2) {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let mut parts = line.split(':');
            let _iface = parts.next();
            let data = parts.next().unwrap_or("").split_whitespace().collect::<Vec<_>>();
            if data.len() >= 16 {
                rx += data[0].parse::<u64>().unwrap_or(0);
                tx += data[8].parse::<u64>().unwrap_or(0);
            }
        }

        Ok((rx, tx))
    }
}

fn parse_kb_line(s: &str) -> Result<u64> {
    let v = s.split_whitespace().next().context("missing numeric value")?;
    Ok(v.parse::<u64>()?)
}

#[derive(Debug)]
struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    fn new(config: Config) -> Self {
        Self { config }
    }

    fn evaluate(&self, t: &Telemetry) {
        if t.cpu_usage_percent / 100.0 > self.config.cpu_high_watermark {
            warn!(
                cpu_usage_percent = t.cpu_usage_percent,
                "CPU usage above threshold"
            );
            self.handle_high_cpu(t);
        }

        if t.memory_used_percent > self.config.mem_high_watermark {
            warn!(
                memory_used_percent = t.memory_used_percent,
                "Memory usage above threshold"
            );
            self.handle_high_memory(t);
        }

        if t.disk_root_used_percent > self.config.disk_high_watermark * 100.0 {
            warn!(
                disk_root_used_percent = t.disk_root_used_percent,
                "Disk usage above threshold"
            );
            self.handle_high_disk(t);
        }
    }

    fn handle_high_cpu(&self, _t: &Telemetry) {
        // Example action: log only.
        // Production: isolate process, adjust niceness, send signal, or trigger autoscaling.
        info!("High CPU policy triggered");
    }

    fn handle_high_memory(&self, _t: &Telemetry) {
        info!("High memory policy triggered");
    }

    fn handle_high_disk(&self, _t: &Telemetry) {
        info!("High disk policy triggered");
    }
}

fn init_logging() {
    let filter = tracing_subscriber::EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| "info".into());

    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .json()
        .with_current_span(false)
        .with_span_list(false)
        .init();
}

#[tokio::main(flavor = "multi_thread", worker_threads = 2)]
async fn main() -> Result<()> {
    init_logging();

    let config = Config::default();
    let mut monitor = ResourceMonitor::new();
    let policy = PolicyEngine::new(config.clone());

    info!("daemon starting");

    let mut tick = interval(config.poll_interval);

    loop {
        tokio::select! {
            _ = tokio::signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
            _ = tick.tick() => {
                match monitor.collect() {
                    Ok(t) => {
                        log_telemetry(&t);
                        policy.evaluate(&t);
                    }
                    Err(e) => error!(error = %e, "telemetry collection failed"),
                }
            }
        }
    }

    info!("daemon exiting");
    Ok(())
}

fn log_telemetry(t: &Telemetry) {
    match serde_json::to_string(t) {
        Ok(s) => info!(telemetry = %s, "resource snapshot"),
        Err(e) => error!(error = %e, "failed to serialize telemetry"),
    }
}
