## Go daemon example

```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"sync"
	"sync/atomic"
	"syscall"
	"time"

	"github.com/shirou/gopsutil/v3/cpu"
	"github.com/shirou/gopsutil/v3/disk"
	"github.com/shirou/gopsutil/v3/mem"
	"github.com/shirou/gopsutil/v3/process"
)

type Snapshot struct {
	Timestamp     time.Time `json:"timestamp"`
	CPUPercent    float64   `json:"cpu_percent"`
	MemPercent    float64   `json:"mem_percent"`
	MemUsedBytes  uint64    `json:"mem_used_bytes"`
	MemTotalBytes uint64    `json:"mem_total_bytes"`
	DiskPercent   float64   `json:"disk_percent"`
	DiskUsedBytes uint64    `json:"disk_used_bytes"`
	DiskTotalBytes uint64    `json:"disk_total_bytes"`
	ProcsRunning  int       `json:"proz_running"`
	GoRoutines    int       `json:"go_routines"`
}

type RingBuffer struct {
	mu    sync.RWMutex
	data  []Snapshot
	head  int
	count int
}

func NewRingBuffer(size int) *RingBuffer {
	return &RingBuffer{
		data: make([]Snapshot, size),
	}
}

func (r *RingBuffer) Add(s Snapshot) {
	r.mu.Lock()
	defer r.mu.Unlock()

	r.data[r.head] = s
	r.head = (r.head + 1) % len(r.data)
	if r.count < len(r.data) {
		r.count++
	}
}

func (r *RingBuffer) List() []Snapshot {
	r.mu.RLock()
	defer r.mu.RUnlock()

	out := make([]Snapshot, 0, r.count)
	start := (r.head - r.count + len(r.data)) % len(r.data)
	for i := 0; i < r.count; i++ {
		idx := (start + i) % len(r.data)
		out = append(out, r.data[idx])
	}
	return out
}

type Daemon struct {
	ring       *RingBuffer
	latest     atomic.Value
	interval   time.Duration
	stop       chan struct{}
	httpServer *http.Server
}

func NewDaemon(interval time.Duration, historySize int) *Daemon {
	d := &Daemon{
		ring:     NewRingBuffer(historySize),
		interval: interval,
		stop:     make(chan struct{}),
	}
	d.latest.Store(Snapshot{})
	return d
}

func (d *Daemon) collectOnce() Snapshot {
	var s Snapshot
	s.Timestamp = time.Now().UTC()
	s.GoRoutines = runtime.NumGoroutine()

	if p, err := cpu.Percent(0, false); err == nil && len(p) > 0 {
		s.CPUPercent = p[0]
	}

	if vm, err := mem.VirtualMemory(); err == nil {
		s.MemPercent = vm.UsedPercent
		s.MemUsedBytes = vm.Used
		s.MemTotalBytes = vm.Total
	}

	if usage, err := disk.Usage("/"); err == nil {
		s.DiskPercent = usage.UsedPercent
		s.DiskUsedBytes = usage.Used
		s.DiskTotalBytes = usage.Total
	}

	if procs, err := process.Processes(); err == nil {
		s.ProcsRunning = len(procs)
	}

	return s
}

func (d *Daemon) runCollector() {
	ticker := time.NewTicker(d.interval)
	defer ticker.Stop()

	// collect immediately
	s := d.collectOnce()
	d.latest.Store(s)
	d.ring.Add(s)

	for {
		select {
		case <-ticker.C:
			s := d.collectOnce()
			d.latest.Store(s)
			d.ring.Add(s)
		case <-d.stop:
			return
		}
	}
}

func (d *Daemon) handleLatest(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(d.latest.Load().(Snapshot))
}

func (d *Daemon) handleHistory(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(d.ring.List())
}

func (d *Daemon) StartHTTP(addr string) {
	mux := http.NewServeMux()
	mux.HandleFunc("/latest", d.handleLatest)
	mux.HandleFunc("/history", d.handleHistory)

	d.httpServer = &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 2 * time.Second,
	}

	go func() {
		if err := d.httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Printf("http server error: %v", err)
		}
	}()
}

func (d *Daemon) Stop() {
	close(d.stop)
	if d.httpServer != nil {
		_ = d.httpServer.Close()
	}
}

func main() {
	d := NewDaemon(2*time.Second, 120)
	go d.runCollector()
	d.StartHTTP("127.0.0.1:9090")

	log.Println("resource monitor daemon started on 127.0.0.1:9090")

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh

	log.Println("shutting down")
	d.Stop()
}
