use anyhow::Result;
use parking_lot::RwLock;
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, NetworkExt, NetworksExt, System, SystemExt};
use tokio::{signal, time};
use warp::Filter;

#[derive(Debug, Clone, Serialize, Default)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage_percent: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    total_swap_kib: u64,
    used_swap_kib: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disks_used_bytes: u64,
    disks_total_bytes: u64,
    network_rx_bytes: u64,
    network_tx_bytes: u64,
}

impl ResourceSnapshot {
    fn to_text(&self) -> String {
        format!(
            concat!(
                "timestamp_ms {}\n",
                "cpu_usage_percent {}\n",
                "total_memory_kib {}\n",
                "used_memory_kib {}\n",
                "total_swap_kib {}\n",
                "used_swap_kib {}\n",
                "load_avg_one {}\n",
                "load_avg_five {}\n",
                "load_avg_fifteen {}\n",
                "disks_used_bytes {}\n",
                "disks_total_bytes {}\n",
                "network_rx_bytes {}\n",
                "network_tx_bytes {}\n"
            ),
            self.timestamp_ms,
            self.cpu_usage_percent,
            self.total_memory_kib,
            self.used_memory_kib,
            self.total_swap_kib,
            self.used_swap_kib,
            self.load_avg_one,
            self.load_avg_five,
            self.load_avg_fifteen,
            self.disks_used_bytes,
            self.disks_total_bytes,
            self.network_rx_bytes,
            self.network_tx_bytes
        )
    }
}

struct Monitor {
    system: System,
    last_net_rx: u64,
    last_net_tx: u64,
}

impl Monitor {
    fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        Self {
            system,
            last_net_rx: 0,
            last_net_tx: 0,
        }
    }

    fn collect(&mut self, start: Instant) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.system.refresh_networks_list();
        self.system.refresh_networks();

        let cpu_usage_percent = self.system.global_cpu_info().cpu_usage();

        let total_memory_kib = self.system.total_memory();
        let used_memory_kib = self.system.used_memory();
        let total_swap_kib = self.system.total_swap();
        let used_swap_kib = self.system.used_swap();

        let load = System::load_average();

        let mut disks_total_bytes = 0u64;
        let mut disks_used_bytes = 0u64;

        for disk in self.system.disks() {
            let total = disk.total_space();
            let avail = disk.available_space();
            disks_total_bytes += total;
            disks_used_bytes += total.saturating_sub(avail);
        }

        let mut network_rx_bytes = 0u64;
        let mut network_tx_bytes = 0u64;

        for (_name, data) in self.system.networks() {
            network_rx_bytes += data.received();
            network_tx_bytes += data.transmitted();
        }

        self.last_net_rx = network_rx_bytes;
        self.last_net_tx = network_tx_bytes;

        ResourceSnapshot {
            timestamp_ms: start.elapsed().as_millis(),
            cpu_usage_percent,
            total_memory_kib,
            used_memory_kib,
            total_swap_kib,
            used_swap_kib,
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            disks_used_bytes,
            disks_total_bytes,
            network_rx_bytes,
            network_tx_bytes,
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let addr: SocketAddr = "127.0.0.1:8080".parse()?;
    let poll_interval = Duration::from_secs(2);

    let snapshot = Arc::new(RwLock::new(ResourceSnapshot::default()));
    let shared = snapshot.clone();

    tokio::spawn(async move {
        let mut monitor = Monitor::new();
        let start = Instant::now();
        let mut ticker = time::interval(poll_interval);

        loop {
            ticker.tick().await;
            let data = monitor.collect(start);
            *shared.write() = data;
        }
    });

    let metrics_route = {
        let snapshot = snapshot.clone();
        warp::path("metrics").and(warp::get()).map(move || {
            let data = snapshot.read().clone();
            warp::reply::with_header(data.to_text(), "Content-Type", "text/plain; charset=utf-8")
        })
    };

    let json_route = {
        let snapshot = snapshot.clone();
        warp::path("json").and(warp::get()).map(move || {
            let data = snapshot.read().clone();
            warp::reply::json(&data)
        })
    };

    let routes = metrics_route.or(json_route);

    println!("sysmon-daemon listening on http://{}", addr);
    println!("metrics: http://{}/metrics", addr);
    println!("json:    http://{}/json", addr);

    let server = warp::serve(routes).run(addr);

    tokio::select! {
        _ = server => {},
        _ = signal::ctrl_c() => {
            println!("shutdown requested");
        }
    }

    Ok(())
}
