use anyhow::Context;
use parking_lot::RwLock;
use serde::Serialize;
use std::{
    convert::Infallible,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::{signal, time};
use tracing::{error, info, warn};
use warp::Filter;

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    hostname: String,
    cpu_usage_percent: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    total_swap_kib: u64,
    used_swap_kib: u64,
    total_disk_bytes: u64,
    used_disk_bytes: u64,
    load_average_one: f64,
    load_average_five: f64,
    load_average_fifteen: f64,
}

impl ResourceSnapshot {
    fn empty(hostname: String) -> Self {
        Self {
            timestamp_unix_ms: now_unix_ms(),
            hostname,
            cpu_usage_percent: 0.0,
            total_memory_kib: 0,
            used_memory_kib: 0,
            total_swap_kib: 0,
            used_swap_kib: 0,
            total_disk_bytes: 0,
            used_disk_bytes: 0,
            load_average_one: 0.0,
            load_average_five: 0.0,
            load_average_fifteen: 0.0,
        }
    }
}

#[derive(Debug)]
struct SharedState {
    latest: RwLock<ResourceSnapshot>,
}

impl SharedState {
    fn new(initial: ResourceSnapshot) -> Self {
        Self {
            latest: RwLock::new(initial),
        }
    }

    fn update(&self, snapshot: ResourceSnapshot) {
        *self.latest.write() = snapshot;
    }

    fn get(&self) -> ResourceSnapshot {
        self.latest.read().clone()
    }
}

fn now_unix_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

fn build_snapshot(system: &mut System) -> ResourceSnapshot {
    system.refresh_cpu();
    system.refresh_memory();
    system.refresh_disks_list();
    system.refresh_disks();

    let hostname = hostname::get()
        .ok()
        .and_then(|h| h.into_string().ok())
        .unwrap_or_else(|| "unknown".to_string());

    let cpu_usage_percent = {
        let cpus = system.cpus();
        if cpus.is_empty() {
            0.0
        } else {
            let sum: f32 = cpus.iter().map(|c| c.cpu_usage()).sum();
            sum / cpus.len() as f32
        }
    };

    let (total_disk_bytes, used_disk_bytes) = {
        let mut total = 0u64;
        let mut used = 0u64;
        for disk in system.disks() {
            let t = disk.total_space();
            let a = disk.available_space();
            total += t;
            used += t.saturating_sub(a);
        }
        (total, used)
    };

    let load = System::load_average();

    ResourceSnapshot {
        timestamp_unix_ms: now_unix_ms(),
        hostname,
        cpu_usage_percent,
        total_memory_kib: system.total_memory(),
        used_memory_kib: system.used_memory(),
        total_swap_kib: system.total_swap(),
        used_swap_kib: system.used_swap(),
        total_disk_bytes,
        used_disk_bytes,
        load_average_one: load.one,
        load_average_five: load.five,
        load_average_fifteen: load.fifteen,
    }
}

fn with_state(
    state: Arc<SharedState>,
) -> impl Filter<Extract = (Arc<SharedState>,), Error = Infallible> + Clone {
    warp::any().map(move || state.clone())
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let mut system = System::new_all();
    system.refresh_all();

    let hostname = hostname::get()
        .ok()
        .and_then(|h| h.into_string().ok())
        .unwrap_or_else(|| "unknown".to_string());

    let initial = ResourceSnapshot::empty(hostname);
    let shared = Arc::new(SharedState::new(initial));

    let monitor_state = shared.clone();
    tokio::spawn(async move {
        let mut sys = system;
        let interval = Duration::from_secs(1);

        loop {
            let snapshot = build_snapshot(&mut sys);
            if snapshot.cpu_usage_percent > 90.0 {
                warn!(
                    cpu = snapshot.cpu_usage_percent,
                    "high CPU usage detected"
                );
            }

            monitor_state.update(snapshot);
            time::sleep(interval).await;
        }
    });

    let health_route = warp::path!("health").map(|| warp::reply::json(&serde_json::json!({
        "status": "ok"
    })));

    let metrics_route = warp::path!("metrics")
        .and(with_state(shared.clone()))
        .map(|state: Arc<SharedState>| {
            let snapshot = state.get();
            warp::reply::json(&snapshot)
        });

    let routes = health_route.or(metrics_route);

    let server = warp::serve(routes).run(([0, 0, 0, 0], 8080));

    info!("resource daemon started on 0.0.0.0:8080");

    tokio::select! {
        _ = server => {},
        _ = shutdown_signal() => {
            info!("shutdown signal received");
        }
    }

    Ok(())
}

async fn shutdown_signal() {
    if let Err(e) = signal::ctrl_c().await {
        error!(error = ?e, "failed to listen for shutdown signal");
    }
}
