use anyhow::Result;
use serde::Serialize;
use std::{
    path::PathBuf,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};
use sysinfo::{DiskExt, LoadAvg, PidExt, ProcessExt, System, SystemExt};
use tokio::{
    signal,
    sync::mpsc,
    task,
    time::{self, MissedTickBehavior},
};
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone)]
struct Config {
    poll_interval: Duration,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    disk_warn_threshold: f32,
    enable_disk_checks: bool,
    enable_process_checks: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval: Duration::from_secs(2),
            cpu_warn_threshold: 85.0,
            mem_warn_threshold: 85.0,
            disk_warn_threshold: 90.0,
            enable_disk_checks: true,
            enable_process_checks: true,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    memory_usage_pct: f32,
    total_swap: u64,
    used_swap: u64,
    disk_usage_pct: f32,
    load_avg_1m: f64,
    load_avg_5m: f64,
    load_avg_15m: f64,
    process_count: usize,
}

#[derive(Debug)]
enum Event {
    Snapshot(ResourceSnapshot),
    Alert(String),
    Shutdown,
}

struct ResourceMonitor {
    system: System,
    config: Config,
}

impl ResourceMonitor {
    fn new(config: Config) -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system, config }
    }

    fn sample(&mut self) -> ResourceSnapshot {
        // Refresh selectively to keep overhead down
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();

        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let memory_usage_pct = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let total_swap = self.system.total_swap();
        let used_swap = self.system.used_swap();

        let disk_usage_pct = self.aggregate_disk_usage_pct();

        let LoadAvg {
            one,
            five,
            fifteen,
        } = System::load_average();

        let process_count = self.system.processes().len();

        ResourceSnapshot {
            timestamp_ms: Instant::now().elapsed().as_millis(),
            cpu_usage,
            total_memory,
            used_memory,
            memory_usage_pct,
            total_swap,
            used_swap,
            disk_usage_pct,
            load_avg_1m: one,
            load_avg_5m: five,
            load_avg_15m: fifteen,
            process_count,
        }
    }

    fn aggregate_disk_usage_pct(&self) -> f32 {
        let mut total_space = 0u64;
        let mut used_space = 0u64;

        for disk in self.system.disks() {
            let total = disk.total_space();
            let avail = disk.available_space();
            let used = total.saturating_sub(avail);

            total_space = total_space.saturating_add(total);
            used_space = used_space.saturating_add(used);
        }

        if total_space == 0 {
            0.0
        } else {
            (used_space as f32 / total_space as f32) * 100.0
        }
    }

    fn evaluate_policy(&self, snapshot: &ResourceSnapshot) -> Vec<Event> {
        let mut events = Vec::with_capacity(4);

        if snapshot.cpu_usage >= self.config.cpu_warn_threshold {
            events.push(Event::Alert(format!(
                "High CPU usage: {:.2}%",
                snapshot.cpu_usage
            )));
        }

        if snapshot.memory_usage_pct >= self.config.mem_warn_threshold {
            events.push(Event::Alert(format!(
                "High memory usage: {:.2}%",
                snapshot.memory_usage_pct
            )));
        }

        if self.config.enable_disk_checks && snapshot.disk_usage_pct >= self.config.disk_warn_threshold {
            events.push(Event::Alert(format!(
                "High disk usage: {:.2}%",
                snapshot.disk_usage_pct
            )));
        }

        if self.config.enable_process_checks && snapshot.process_count > 10_000 {
            events.push(Event::Alert(format!(
                "Suspiciously high process count: {}",
                snapshot.process_count
            )));
        }

        events
    }
}

async fn monitoring_loop(
    mut monitor: ResourceMonitor,
    tx: mpsc::Sender<Event>,
    shutdown: Arc<AtomicBool>,
) {
    let mut interval = time::interval(monitor.config.poll_interval);
    interval.set_missed_tick_behavior(MissedTickBehavior::Skip);

    loop {
        tokio::select! {
            _ = interval.tick() => {
                let started = Instant::now();

                let snapshot = task::spawn_blocking({
                    let mut monitor = monitor.system.clone();
                    move || {
                        // In a real design, keep this inside the owned monitor and avoid cloning.
                        // This placeholder keeps the example compact.
                        let mut sys = monitor;
                        sys.refresh_cpu();
                        sys.refresh_memory();
                        sys.refresh_processes();

                        let cpu_usage = sys.global_cpu_info().cpu_usage();
                        let total_memory = sys.total_memory();
                        let used_memory = sys.used_memory();
                        let memory_usage_pct = if total_memory > 0 {
                            (used_memory as f32 / total_memory as f32) * 100.0
                        } else {
                            0.0
                        };
                        let total_swap = sys.total_swap();
                        let used_swap = sys.used_swap();
                        let load = System::load_average();
                        let process_count = sys.processes().len();

                        ResourceSnapshot {
                            timestamp_ms: Instant::now().elapsed().as_millis(),
                            cpu_usage,
                            total_memory,
                            used_memory,
                            memory_usage_pct,
                            total_swap,
                            used_swap,
                            disk_usage_pct: 0.0,
                            load_avg_1m: load.one,
                            load_avg_5m: load.five,
                            load_avg_15m: load.fifteen,
                            process_count,
                        }
                    }
                }).await;

                match snapshot {
                    Ok(snapshot) => {
                        let elapsed = started.elapsed();
                        debug!("sampled resources in {:?}", elapsed);

                        if tx.send(Event::Snapshot(snapshot.clone())).await.is_err() {
                            break;
                        }

                        for event in monitor.evaluate_policy(&snapshot) {
                            if tx.send(event).await.is_err() {
                                break;
                            }
                        }
                    }
                    Err(e) => {
                        let _ = tx.send(Event::Alert(format!("sampling failed: {e}"))).await;
                    }
                }
            }
            _ = async {
                while !shutdown.load(Ordering::Relaxed) {
                    time::sleep(Duration::from_millis(100)).await;
                }
            } => {
                let _ = tx.send(Event::Shutdown).await;
                break;
            }
        }
    }
}

async fn event_loop(mut rx: mpsc::Receiver<Event>) {
    while let Some(event) = rx.recv().await {
        match event {
            Event::Snapshot(snapshot) => {
                match serde_json::to_string(&snapshot) {
                    Ok(json) => info!(%json, "resource snapshot"),
                    Err(e) => warn!("failed to serialize snapshot: {}", e),
                }
            }
            Event::Alert(msg) => {
                warn!("{}", msg);
                // Hook for management actions:
                // - notify systemd/journald
                // - raise metrics
                // - trigger process mitigation
                // - send to external controller
            }
            Event::Shutdown => {
                info!("shutdown event received");
                break;
            }
        }
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    info!("starting resource daemon");

    let config = Config::default();
    let monitor = ResourceMonitor::new(config);

    let (tx, rx) = mpsc::channel::<Event>(1024);
    let shutdown = Arc::new(AtomicBool::new(false));

    let shutdown_flag = shutdown.clone();
    let monitor_task = tokio::spawn(monitoring_loop(monitor, tx.clone(), shutdown_flag));
    let event_task = tokio::spawn(event_loop(rx));

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("ctrl-c received");
        }
    }

    shutdown.store(true, Ordering::Relaxed);

    let _ = tx.send(Event::Shutdown).await;

    if let Err(e) = monitor_task.await {
        error!("monitoring task failed: {}", e);
    }
    if let Err(e) = event_task.await {
        error!("event task failed: {}", e);
    }

    info!("daemon stopped");
    Ok(())
}
