        load_five: five,
        load_fifteen: fifteen,
        disk_used_pct,
        uptime_secs: System::uptime(),
    }
}

fn calculate_disk_usage(sys: &System) -> f32 {
    let mut total_bytes = 0u64;
    let mut used_bytes = 0u64;

    for disk in sys.disks() {
        let total = disk.total_space();
        let available = disk.available_space();
        let used = total.saturating_sub(available);

        total_bytes += total;
        used_bytes += used;
    }

    if total_bytes > 0 {
        (used_bytes as f32 / total_bytes as f32) * 100.0
    } else {
        0.0
    }
}

fn evaluate_thresholds(snapshot: &ResourceSnapshot, thresholds: &Thresholds) {
    if snapshot.cpu_usage > thresholds.cpu_warn {
        warn!(
            cpu = snapshot.cpu_usage,
            threshold = thresholds.cpu_warn,
            "high CPU usage"
        );
        // Placeholder for action:
        // - notify
        // - throttle service
        // - capture diagnostics
    }

    if snapshot.memory_usage_pct > thresholds.memory_warn {
        warn!(
            mem_pct = snapshot.memory_usage_pct,
            threshold = thresholds.memory_warn,
            "high memory usage"
        );
        // Placeholder for action:
        // - trigger cleanup
        // - restart memory-heavy worker
    }

    if snapshot.disk_used_pct > thresholds.disk_warn {
        warn!(
            disk_pct = snapshot.disk_used_pct,
            threshold = thresholds.disk_warn,
            "high disk usage"
        );
        // Placeholder for action:
        // - remove temp data
        // - rotate logs
        // - alert admin
    }
}

async fn health() -> impl IntoResponse {
    StatusCode::OK
}

async fn status(State(state): State<SharedState>) -> impl IntoResponse {
    let snapshot = state.latest.read().unwrap().clone();
    match snapshot {
        Some(s) => (StatusCode::OK, Json(s)).into_response(),
        None => (StatusCode::SERVICE_UNAVAILABLE, "no data yet").into_response(),
    }
}
