use anyhow::Result;
use parking_lot::RwLock;
use serde::Serialize;
use std::{
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    total_memory_kib: u64,
    used_memory_kib: u64,
    total_swap_kib: u64,
    used_swap_kib: u64,
    cpu_usage_percent: f32,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    total_processes: usize,
    disk_used_percent: f32,
}

#[derive(Debug, Clone)]
struct Thresholds {
    cpu_warn: f32,
    memory_warn_percent: f32,
    disk_warn_percent: f32,
    process_warn: usize,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_warn: 85.0,
            memory_warn_percent: 90.0,
            disk_warn_percent: 90.0,
            process_warn: 1000,
        }
    }
}

struct Monitor {
    system: System,
    thresholds: Thresholds,
    last_snapshot: Option<ResourceSnapshot>,
}

impl Monitor {
    fn new(thresholds: Thresholds) -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self {
            system,
            thresholds,
            last_snapshot: None,
        }
    }

    fn collect_snapshot(&mut self) -> ResourceSnapshot {
        // Refresh only what we need for lower overhead.
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let load = System::load_average();

        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let total_swap = self.system.total_swap();
        let used_swap = self.system.used_swap();
        let total_processes = self.system.processes().len();

        // Aggregate disk usage across mounted disks.
        let mut disk_total = 0u64;
        let mut disk_used = 0u64;
        for disk in self.system.disks() {
            let total = disk.total_space();
            let avail = disk.available_space();
            let used = total.saturating_sub(avail);
            disk_total += total;
            disk_used += used;
        }

        let disk_used_percent = if disk_total > 0 {
            (disk_used as f32 / disk_total as f32) * 100.0
        } else {
            0.0
        };

        let timestamp_unix_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();

        ResourceSnapshot {
            timestamp_unix_ms,
            total_memory_kib: total_memory,
            used_memory_kib: used_memory,
            total_swap_kib: total_swap,
            used_swap_kib: used_swap,
            cpu_usage_percent: cpu_usage,
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            total_processes,
            disk_used_percent,
        }
    }

    fn evaluate_policy(&self, snapshot: &ResourceSnapshot) -> Vec<String> {
        let mut alerts = Vec::new();

        let mem_percent = if snapshot.total_memory_kib > 0 {
            (snapshot.used_memory_kib as f32 / snapshot.total_memory_kib as f32) * 100.0
        } else {
            0.0
        };

        if snapshot.cpu_usage_percent >= self.thresholds.cpu_warn {
            alerts.push(format!(
                "High CPU usage: {:.1}% >= {:.1}%",
                snapshot.cpu_usage_percent, self.thresholds.cpu_warn
            ));
        }

        if mem_percent >= self.thresholds.memory_warn_percent {
            alerts.push(format!(
                "High memory usage: {:.1}% >= {:.1}%",
                mem_percent, self.thresholds.memory_warn_percent
            ));
        }

        if snapshot.disk_used_percent >= self.thresholds.disk_warn_percent {
            alerts.push(format!(
                "High disk usage: {:.1}% >= {:.1}%",
                snapshot.disk_used_percent, self.thresholds.disk_warn_percent
            ));
        }

        if snapshot.total_processes >= self.thresholds.process_warn {
            alerts.push(format!(
                "High process count: {} >= {}",
                snapshot.total_processes, self.thresholds.process_warn
            ));
        }

        alerts
    }

    fn apply_actions(&self, alerts: &[String]) {
        for alert in alerts {
            warn!(%alert, "resource threshold exceeded");

            // Extend here with actual management actions:
            // - raise systemd notifications
            // - write to journal
            // - send to metrics/alerting pipeline
            // - throttle workloads
            // - trigger cgroup adjustments
            // - kill runaway processes after policy validation
        }
    }

    fn update_state(&mut self, snapshot: ResourceSnapshot) {
        self.last_snapshot = Some(snapshot);
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .json()
        .init();

    let monitor = Arc::new(RwLock::new(Monitor::new(Thresholds::default())));
    let mut tick = interval(Duration::from_secs(2));

    info!("resource daemon starting");

    loop {
        tokio::select! {
            _ = tick.tick() => {
                let mut guard = monitor.write();
                let snapshot = guard.collect_snapshot();
                let alerts = guard.evaluate_policy(&snapshot);

                info!(snapshot = ?snapshot, "resource snapshot collected");
                if !alerts.is_empty() {
                    guard.apply_actions(&alerts);
                }
                guard.update_state(snapshot);
            }

            _ = tokio::signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("resource daemon stopped");
    Ok(())
}
