// daemon.cpp
// Build: g++ -O2 -std=c++20 -Wall -Wextra -pedantic daemon.cpp -o resmon_daemon
// Run:   ./resmon_daemon /tmp/resmon.sock

#include <sys/epoll.h>
#include <sys/timerfd.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <sys/statvfs.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <unistd.h>

#include <cerrno>
#include <cstdio>
#include <cstdlib>
#include <cstring>

#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <unordered_map>
#include <optional>
#include <iostream>
#include <algorithm>

static constexpr int MAX_EVENTS = 16;
static constexpr int SAMPLE_INTERVAL_SEC = 1;

static int set_nonblocking(int fd) {
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0) return -1;
    return fcntl(fd, F_SETFL, flags | O_NONBLOCK);
}

static std::string read_file(const std::string& path) {
    std::ifstream f(path);
    if (!f) return {};
    std::stringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

struct CpuTimes {
    unsigned long long user = 0, nice = 0, system = 0, idle = 0, iowait = 0, irq = 0, softirq = 0, steal = 0;
};

static std::optional<CpuTimes> read_cpu_times() {
    std::ifstream f("/proc/stat");
    if (!f) return std::nullopt;

    std::string cpu;
    CpuTimes t;
    f >> cpu >> t.user >> t.nice >> t.system >> t.idle >> t.iowait >> t.irq >> t.softirq >> t.steal;
    if (cpu != "cpu") return std::nullopt;
    return t;
}

struct Metrics {
    double cpu_usage = 0.0;
    unsigned long mem_total_kb = 0;
    unsigned long mem_available_kb = 0;
    double mem_used_pct = 0.0;
    double load1 = 0.0;
    double load5 = 0.0;
    double load15 = 0.0;
    unsigned long uptime_sec = 0;
    long process_count = 0;
    unsigned long root_total_mb = 0;
    unsigned long root_free_mb = 0;
    double root_used_pct = 0.0;
};

class ResourceMonitor {
public:
    void update() {
        update_cpu();
        update_memory();
        update_load();
        update_uptime();
        update_process_count();
        update_disk_usage();
    }

    const Metrics& metrics() const { return m_; }

private:
    Metrics m_;
    std::optional<CpuTimes> prev_cpu_;

    void update_cpu() {
        auto now = read_cpu_times();
        if (!now) return;

        if (prev_cpu_) {
            auto prev = *prev_cpu_;
            auto cur = *now;

            unsigned long long prev_idle = prev.idle + prev.iowait;
            unsigned long long cur_idle  = cur.idle + cur.iowait;

            unsigned long long prev_total = prev.user + prev.nice + prev.system + prev.idle + prev.iowait + prev.irq + prev.softirq + prev.steal;
            unsigned long long cur_total  = cur.user + cur.nice + cur.system + cur.idle + cur.iowait + cur.irq + cur.softirq + cur.steal;

            auto total_delta = cur_total - prev_total;
            auto idle_delta = cur_idle - prev_idle;

            if (total_delta > 0) {
                m_.cpu_usage = 100.0 * (double)(total_delta - idle_delta) / (double)total_delta;
            }
        }

        prev_cpu_ = now;
    }

    void update_memory() {
        std::ifstream f("/proc/meminfo");
        if (!f) return;

        unsigned long total = 0, available = 0;
        std::string key, unit;
        unsigned long value;

        while (f >> key >> value >> unit) {
            if (key == "MemTotal:") total = value;
            else if (key == "MemAvailable:") available = value;
            if (total && available) break;
        }

        if (total) {
            m_.mem_total_kb = total;
            m_.mem_available_kb = available;
            m_.mem_used_pct = 100.0 * (double)(total - available) / (double)total;
        }
    }

    void update_load() {
        std::ifstream f("/proc/loadavg");
        if (!f) return;
        f >> m_.load1 >> m_.load5 >> m_.load15;
    }

    void update_uptime() {
        std::ifstream f("/proc/uptime");
        if (!f) return;
        double up = 0.0, idle = 0.0;
        f >> up >> idle;
        m_.uptime_sec = (unsigned long)up;
    }

    void update_process_count() {
        long count = 0;
        DIR* dir = opendir("/proc");
        if (!dir) return;

        while (auto* ent = readdir(dir)) {
            if (ent->d_type == DT_DIR) {
                char* end = nullptr;
                long pid = std::strtol(ent->d_name, &end, 10);
                if (end && *end == '\0' && pid > 0) count++;
            }
        }
        closedir(dir);
        m_.process_count = count;
    }

    void update_disk_usage() {
        struct statvfs vfs {};
        if (statvfs("/", &vfs) != 0) return;

        unsigned long total = vfs.f_blocks * vfs.f_frsize;
        unsigned long freeb = vfs.f_bavail * vfs.f_frsize;
        if (total > 0) {
            m_.root_total_mb = total / (1024 * 1024);
            m_.root_free_mb = freeb / (1024 * 1024);
            m_.root_used_pct = 100.0 * (double)(total - freeb) / (double)total;
        }
    }
};

class Daemon {
public:
    explicit Daemon(std::string socket_path)
        : socket_path_(std::move(socket_path)) {}

    bool init() {
        epoll_fd_ = epoll_create1(EPOLL_CLOEXEC);
        if (epoll_fd_ < 0) {
            perror("epoll_create1");
            return false;
        }

        timer_fd_ = timerfd_create(CLOCK_MONOTONIC, TFD_CLOEXEC | TFD_NONBLOCK);
        if (timer_fd_ < 0) {
            perror("timerfd_create");
            return false;
        }

        itimerspec ts {};
        ts.it_interval.tv_sec = SAMPLE_INTERVAL_SEC;
        ts.it_value.tv_sec = SAMPLE_INTERVAL_SEC;
        if (timerfd_settime(timer_fd_, 0, &ts, nullptr) != 0) {
            perror("timerfd_settime");
            return false;
        }

        server_fd_ = create_unix_server(socket_path_);
        if (server_fd_ < 0) return false;

        add_fd(timer_fd_);
        add_fd(server_fd_);

        monitor_.update();
        return true;
    }

    void run() {
        std::cout << "resource monitor daemon running on " << socket_path_ << "\n";

        while (true) {
            epoll_event events[MAX_EVENTS];
            int n = epoll_wait(epoll_fd_, events, MAX_EVENTS, -1);
            if (n < 0) {
                if (errno == EINTR) continue;
                perror("epoll_wait");
                break;
            }

            for (int i = 0; i < n; ++i) {
                int fd = events[i].data.fd;
                if (fd == timer_fd_) {
                    handle_timer();
                } else if (fd == server_fd_) {
                    handle_accept();
                } else {
                    handle_client(fd);
                }
            }
        }
    }

    ~Daemon() {
        if (server_fd_ >= 0) {
            close(server_fd_);
            unlink(socket_path_.c_str());
        }
        if (timer_fd_ >= 0) close(timer_fd_);
        if (epoll_fd_ >= 0) close(epoll_fd_);
    }

private:
    std::string socket_path_;
    int epoll_fd_ = -1;
    int timer_fd_ = -1;
    int server_fd_ = -1;
    ResourceMonitor monitor_;

    static int create_unix_server(const std::string& path) {
        unlink(path.c_str());

        int fd = socket(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
        if (fd < 0) {
            perror("socket");
            return -1;
        }

        sockaddr_un addr {};
        addr.sun_family = AF_UNIX;
        std::snprintf(addr.sun_path, sizeof(addr.sun_path), "%s", path.c_str());

        if (bind(fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) != 0) {
            perror("bind");
            close(fd);
            return -1;
        }

        if (listen(fd, 64) != 0) {
            perror("listen");
            close(fd);
            return -1;
        }

        if (set_nonblocking(fd) != 0) {
            perror("nonblocking");
            close(fd);
            return -1;
        }

        return fd;
    }

    void add_fd(int fd) {
        epoll_event ev {};
        ev.events = EPOLLIN;
        ev.data.fd = fd;
        if (epoll_ctl(epoll_fd_, EPOLL_CTL_ADD, fd, &ev) != 0) {
            perror("epoll_ctl");
        }
    }

    void handle_timer() {
        uint64_t expirations = 0;
        (void)read(timer_fd_, &expirations, sizeof(expirations));
        monitor_.update();
    }

    void handle_accept() {
        while (true) {
            int cfd = accept4(server_fd_, nullptr, nullptr, SOCK_CLOEXEC | SOCK_NONBLOCK);
            if (cfd < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) break;
                perror("accept4");
                break;
            }
            add_client(cfd);
        }
    }

    void add_client(int fd) {
        epoll_event ev {};
        ev.events = EPOLLIN | EPOLLRDHUP | EPOLLHUP;
        ev.data.fd = fd;
        if (epoll_ctl(epoll_fd_, EPOLL_CTL_ADD, fd, &ev) != 0) {
            perror("epoll_ctl client");
            close(fd);
        }
    }

    void handle_client(int fd) {
        char buf[1024];
        ssize_t n = read(fd, buf, sizeof(buf) - 1);

        if (n <= 0) {
            close_client(fd);
            return;
        }

        buf[n] = '\0';
        std::string cmd(buf);

        if (cmd.find("GET") != std::string::npos || cmd.find("metrics") != std::string::npos) {
            std::string out = format_metrics();
            (void)write(fd, out.data(), out.size());
        } else if (cmd.find("help") != std::string::npos) {
            std::string out = "commands: metrics, help\n";
            (void)write(fd, out.data(), out.size());
        } else {
            std::string out = "unknown command\n";
            (void)write(fd, out.data(), out.size());
        }

        close_client(fd);
    }

    std::string format_metrics() const {
        const auto& m = monitor_.metrics();
        std::ostringstream os;
        os
            << "{\n"
            << "  \"cpu_usage_pct\": " << m.cpu_usage << ",\n"
            << "  \"mem_total_kb\": " << m.mem_total_kb << ",\n"
            << "  \"mem_available_kb\": " << m.mem_available_kb << ",\n"
            << "  \"mem_used_pct\": " << m.mem_used_pct << ",\n"
            << "  \"load1\": " << m.load1 << ",\n"
            << "  \"load5\": " << m.load5 << ",\n"
            << "  \"load15\": " << m.load15 << ",\n"
            << "  \"uptime_sec\": " << m.uptime_sec << ",\n"
            << "  \"process_count\": " << m.process_count << ",\n"
            << "  \"root_total_mb\": " << m.root_total_mb << ",\n"
            << "  \"root_free_mb\": " << m.root_free_mb << ",\n"
            << "  \"root_used_pct\": " << m.root_used_pct << "\n"
            << "}\n";
        return os.str();
    }

    void close_client(int fd) {
        epoll_ctl(epoll_fd_, EPOLL_CTL_DEL, fd, nullptr);
        close(fd);
    }
};

int main(int argc, char* argv[]) {
    std::string sock = "/tmp/resmon.sock";
    if (argc > 1) sock = argv[1];

    Daemon d(sock);
    if (!d.init()) return 1;
    d.run();
    return 0;
}
