use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::Path,
    process::Command,
    time::Duration,
};
use sysinfo::{CpuExt, System, SystemExt};
use tokio::{signal, time};
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    load_warn_threshold: f64,
    max_processes: usize,

    #[serde(default)]
    actions: Actions,
}

#[derive(Debug, Clone, Deserialize)]
struct Actions {
    #[serde(default)]
    log_only: bool,

    /// Optional command executed when CPU threshold is exceeded.
    /// Example: "/usr/local/bin/throttle_cpu.sh"
    #[serde(default)]
    cpu_action_cmd: Option<String>,

    /// Optional command executed when memory threshold is exceeded.
    #[serde(default)]
    mem_action_cmd: Option<String>,

    /// Optional command executed when load threshold is exceeded.
    #[serde(default)]
    load_action_cmd: Option<String>,
}

impl Default for Actions {
    fn default() -> Self {
        Self {
            log_only: true,
            cpu_action_cmd: None,
            mem_action_cmd: None,
            load_action_cmd: None,
        }
    }
}

#[derive(Debug, Clone)]
struct Metrics {
    cpu_usage: f32,
    memory_used_pct: f32,
    load_avg_1m: f64,
    process_count: usize,
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let config = load_config("config.toml")?;
    info!("starting resource daemon");

    let mut sys = System::new_all();
    sys.refresh_all();

    let mut interval = time::interval(Duration::from_millis(config.sample_interval_ms));
    interval.set_missed_tick_behavior(time::MissedTickBehavior::Delay);

    loop {
        tokio::select! {
            _ = interval.tick() => {
                if let Err(e) = sample_and_manage(&mut sys, &config).await {
                    error!(error = ?e, "monitor loop error");
                }
            }
            _ = signal::ctrl_c() => {
                info!("shutdown requested");
                break;
            }
        }
    }

    info!("resource daemon stopped");
    Ok(())
}

fn load_config<P: AsRef<Path>>(path: P) -> Result<Config> {
    let contents = fs::read_to_string(&path)
        .with_context(|| format!("failed to read config file {:?}", path.as_ref()))?;
    let cfg: Config = toml::from_str(&contents).context("invalid config TOML")?;
    Ok(cfg)
}

async fn sample_and_manage(sys: &mut System, config: &Config) -> Result<()> {
    // Refresh metrics with minimal necessary work.
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_processes();

    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let memory_used = sys.used_memory();
    let memory_total = sys.total_memory();
    let memory_used_pct = if memory_total > 0 {
        (memory_used as f32 / memory_total as f32) * 100.0
    } else {
        0.0
    };

    let load_avg = System::load_average();
    let process_count = sys.processes().len();

    let metrics = Metrics {
        cpu_usage,
        memory_used_pct,
        load_avg_1m: load_avg.one,
        process_count,
    };

    report_metrics(&metrics);

    apply_policies(sys, config, &metrics).await?;

    Ok(())
}

fn report_metrics(m: &Metrics) {
    info!(
        cpu_usage = format!("{:.2}", m.cpu_usage),
        memory_used_pct = format!("{:.2}", m.memory_used_pct),
        load_avg_1m = format!("{:.2}", m.load_avg_1m),
        process_count = m.process_count,
        "resource metrics"
    );
}

async fn apply_policies(sys: &System, config: &Config, m: &Metrics) -> Result<()> {
    if m.cpu_usage > config.cpu_warn_threshold {
        warn!(
            cpu = m.cpu_usage,
            threshold = config.cpu_warn_threshold,
            "cpu usage exceeded threshold"
        );
        run_action(
            "cpu",
            config.actions.log_only,
            config.actions.cpu_action_cmd.as_deref(),
        ).await?;
    }

    if m.memory_used_pct > config.mem_warn_threshold {
        warn!(
            memory = m.memory_used_pct,
            threshold = config.mem_warn_threshold,
            "memory usage exceeded threshold"
        );
        run_action(
            "memory",
            config.actions.log_only,
            config.actions.mem_action_cmd.as_deref(),
        ).await?;
    }

    if m.load_avg_1m > config.load_warn_threshold {
        warn!(
            load = m.load_avg_1m,
            threshold = config.load_warn_threshold,
            "load average exceeded threshold"
        );
        run_action(
            "load",
            config.actions.log_only,
            config.actions.load_action_cmd.as_deref(),
        ).await?;
    }

    if m.process_count > config.max_processes {
        warn!(
            process_count = m.process_count,
            max_processes = config.max_processes,
            "process count exceeded threshold"
        );

        // Example management action: identify highest CPU process and log it.
        if let Some(proc_) = sys
            .processes()
            .values()
            .max_by(|a, b| a.cpu_usage().partial_cmp(&b.cpu_usage()).unwrap())
        {
            warn!(
                pid = proc_.pid().as_u32(),
                name = proc_.name(),
                cpu = proc_.cpu_usage(),
                memory = proc_.memory(),
                "top offender process"
            );
        }
    }

    Ok(())
}

async fn run_action(kind: &str, log_only: bool, cmd: Option<&str>) -> Result<()> {
    if log_only {
        debug!(kind, "log_only enabled; no action executed");
        return Ok(());
    }

    if let Some(command) = cmd {
        let command = command.to_owned();
        let kind = kind.to_owned();

        tokio::task::spawn_blocking(move || -> Result<()> {
            info!(kind = %kind, cmd = %command, "executing mitigation action");
            let status = if cfg!(target_os = "windows") {
                Command::new("cmd").args(["/C", &command]).status()?
            } else {
                Command::new("sh").args(["-c", &command]).status()?
            };

            if !status.success() {
                warn!(kind = %kind, status = ?status, "action command returned non-zero");
            }

            Ok(())
        })
        .await??;
    } else {
        debug!(kind, "no action command configured");
    }

    Ok(())
}
