use anyhow::Result;
use log::{error, info, warn};
use serde::Serialize;
use std::{
    collections::VecDeque,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::process::Command;
use warp::Filter;

#[derive(Clone, Debug, Serialize)]
struct Metrics {
    timestamp_ms: u128,
    cpu_usage_pct: f32,
    memory_used_mb: u64,
    memory_total_mb: u64,
    swap_used_mb: u64,
    swap_total_mb: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disk_used_pct: f32,
}

#[derive(Clone)]
struct Config {
    sample_interval: Duration,
    cpu_threshold: f32,
    mem_threshold_pct: f32,
    disk_threshold_pct: f32,
    restart_service: Option<String>,
    min_restart_interval: Duration,
}

struct State {
    metrics: Mutex<Metrics>,
    last_restart: Mutex<Instant>,
    recent_alerts: Mutex<VecDeque<String>>,
}

impl State {
    fn new() -> Self {
        Self {
            metrics: Mutex::new(Metrics {
                timestamp_ms: 0,
                cpu_usage_pct: 0.0,
                memory_used_mb: 0,
                memory_total_mb: 0,
                swap_used_mb: 0,
                swap_total_mb: 0,
                load_avg_one: 0.0,
                load_avg_five: 0.0,
                load_avg_fifteen: 0.0,
                disk_used_pct: 0.0,
            }),
            last_restart: Mutex::new(Instant::now() - Duration::from_secs(3600)),
            recent_alerts: Mutex::new(VecDeque::with_capacity(32)),
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    env_logger::init();

    let cfg = Config {
        sample_interval: Duration::from_secs(2),
        cpu_threshold: 90.0,
        mem_threshold_pct: 90.0,
        disk_threshold_pct: 90.0,
        restart_service: Some("nginx".to_string()),
        min_restart_interval: Duration::from_secs(300),
    };

    let state = Arc::new(State::new());

    let monitor_state = state.clone();
    let monitor_cfg = cfg.clone();
    tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_cfg).await {
            error!("monitor loop failed: {e:?}");
        }
    });

    let metrics_state = state.clone();
    let metrics_route = warp::path("metrics").and(warp::get()).map(move || {
        let m = metrics_state.metrics.lock().unwrap().clone();
        warp::reply::json(&m)
    });

    let alerts_state = state.clone();
    let alerts_route = warp::path("alerts").and(warp::get()).map(move || {
        let alerts = alerts_state.recent_alerts.lock().unwrap().clone();
        warp::reply::json(&alerts.into_iter().collect::<Vec<_>>())
    });

    let routes = metrics_route.or(alerts_route);

    info!("daemon started on 127.0.0.1:8080");
    warp::serve(routes).run(([127, 0, 0, 1], 8080)).await;

    Ok(())
}

async fn monitor_loop(state: Arc<State>, cfg: Config) -> Result<()> {
    let mut system = System::new_all();

    loop {
        let now = Instant::now();
        system.refresh_all();

        let cpu_usage = system.global_cpu_info().cpu_usage();

        let mem_total = system.total_memory() / 1024;
        let mem_used = system.used_memory() / 1024;
        let swap_total = system.total_swap() / 1024;
        let swap_used = system.used_swap() / 1024;

        let load = sysinfo::System::load_average();

        let disk_used_pct = calculate_disk_usage_pct(&system);

        {
            let mut m = state.metrics.lock().unwrap();
            m.timestamp_ms = now.elapsed().as_millis();
            m.cpu_usage_pct = cpu_usage;
            m.memory_used_mb = mem_used;
            m.memory_total_mb = mem_total;
            m.swap_used_mb = swap_used;
            m.swap_total_mb = swap_total;
            m.load_avg_one = load.one;
            m.load_avg_five = load.five;
            m.load_avg_fifteen = load.fifteen;
            m.disk_used_pct = disk_used_pct;
        }

        let mem_pct = if mem_total > 0 {
            (mem_used as f32 / mem_total as f32) * 100.0
        } else {
            0.0
        };

        if cpu_usage > cfg.cpu_threshold {
            push_alert(&state, format!("high CPU usage: {:.1}%", cpu_usage));
        }
        if mem_pct > cfg.mem_threshold_pct {
            push_alert(&state, format!("high memory usage: {:.1}%", mem_pct));
        }
        if disk_used_pct > cfg.disk_threshold_pct {
            push_alert(&state, format!("high disk usage: {:.1}%", disk_used_pct));
        }

        if let Some(service) = &cfg.restart_service {
            let should_restart = cpu_usage > cfg.cpu_threshold || mem_pct > cfg.mem_threshold_pct;
            if should_restart {
                maybe_restart_service(state.clone(), service.clone(), cfg.min_restart_interval).await?;
            }
        }

        tokio::time::sleep(cfg.sample_interval).await;
    }
}

fn calculate_disk_usage_pct(system: &System) -> f32 {
    let mut total_space = 0u64;
    let mut available_space = 0u64;

    for disk in system.disks() {
        total_space += disk.total_space();
        available_space += disk.available_space();
    }

    if total_space == 0 {
        0.0
    } else {
        ((total_space - available_space) as f32 / total_space as f32) * 100.0
    }
}

fn push_alert(state: &Arc<State>, msg: String) {
    warn!("{msg}");
    let mut alerts = state.recent_alerts.lock().unwrap();
    if alerts.len() == 32 {
        alerts.pop_front();
    }
    alerts.push_back(msg);
}

async fn maybe_restart_service(
    state: Arc<State>,
    service: String,
    min_interval: Duration,
) -> Result<()> {
    let mut last_restart = state.last_restart.lock().unwrap();
    if last_restart.elapsed() < min_interval {
        return Ok(());
    }

    *last_restart = Instant::now();
    drop(last_restart);

    info!("restarting service: {service}");

    let output = Command::new("systemctl")
        .arg("restart")
        .arg(&service)
        .output()
        .await?;

    if output.status.success() {
        info!("service restarted successfully: {service}");
    } else {
        warn!(
            "service restart failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    Ok(())
}
```

