use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::Path,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, Disks, Networks, RefreshKind, System};
use tokio::{signal, time};
use tracing::{debug, error, info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    sample_interval_ms: u64,
    cpu: ThresholdConfigPercent,
    memory: ThresholdConfigPercent,
    disk: ThresholdConfigPercent,
    network: ThresholdConfigBytes,
}

#[derive(Debug, Deserialize, Clone)]
struct ThresholdConfigPercent {
    warn_percent: f32,
    critical_percent: f32,
}

#[derive(Debug, Deserialize, Clone)]
struct ThresholdConfigBytes {
    warn_bytes_per_sec: u64,
    critical_bytes_per_sec: u64,
}

#[derive(Debug, Default, Clone)]
struct ResourceSnapshot {
    cpu_percent: f32,
    mem_percent: f32,
    disk_percent: f32,
    net_rx_bps: u64,
    net_tx_bps: u64,
}

struct ResourceDaemon {
    system: System,
    disks: Disks,
    networks: Networks,
    config: Config,
    last_net_rx: u64,
    last_net_tx: u64,
    last_sample: Option<Instant>,
}

impl ResourceDaemon {
    fn new(config: Config) -> Self {
        let refresh = RefreshKind::new().with_cpu(CpuRefreshKind::everything());
        let mut system = System::new_with_specifics(refresh);
        system.refresh_cpu();

        let disks = Disks::new_with_refreshed_list();
        let networks = Networks::new_with_refreshed_list();

        Self {
            system,
            disks,
            networks,
            config,
            last_net_rx: 0,
            last_net_tx: 0,
            last_sample: None,
        }
    }

    fn sample(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.disks.refresh(true);
        self.networks.refresh(true);

        let cpu_percent = self.system.global_cpu_usage();
        let mem_total = self.system.total_memory();
        let mem_used = self.system.used_memory();
        let mem_percent = if mem_total > 0 {
            (mem_used as f32 / mem_total as f32) * 100.0
        } else {
            0.0
        };

        let disk_percent = self.disk_usage_percent();

        let (net_rx_bps, net_tx_bps) = self.network_bandwidth_bps();

        ResourceSnapshot {
            cpu_percent,
            mem_percent,
            disk_percent,
            net_rx_bps,
            net_tx_bps,
        }
    }

    fn disk_usage_percent(&self) -> f32 {
        let mut total_used = 0u64;
        let mut total_space = 0u64;

        for disk in self.disks.list() {
            total_space += disk.total_space();
            total_used += disk.total_space().saturating_sub(disk.available_space());
        }

        if total_space > 0 {
            (total_used as f32 / total_space as f32) * 100.0
        } else {
            0.0
        }
    }

    fn network_bandwidth_bps(&mut self) -> (u64, u64) {
        let mut rx = 0u64;
        let mut tx = 0u64;

        for (_, data) in self.networks.iter() {
            rx = rx.saturating_add(data.total_received());
            tx = tx.saturating_add(data.total_transmitted());
        }

        let now = Instant::now();
        let dt = self
            .last_sample
            .map(|prev| now.duration_since(prev).as_secs_f64())
            .unwrap_or(0.0);

        let result = if dt > 0.0 {
            let rx_delta = rx.saturating_sub(self.last_net_rx);
            let tx_delta = tx.saturating_sub(self.last_net_tx);
            (
                (rx_delta as f64 / dt) as u64,
                (tx_delta as f64 / dt) as u64,
            )
        } else {
            (0, 0)
        };

        self.last_net_rx = rx;
        self.last_net_tx = tx;
        self.last_sample = Some(now);

        result
    }

    fn evaluate(&self, s: &ResourceSnapshot) {
        self.check_percent("CPU", s.cpu_percent, &self.config.cpu);
        self.check_percent("Memory", s.mem_percent, &self.config.memory);
        self.check_percent("Disk", s.disk_percent, &self.config.disk);
        self.check_bytes("Network RX", s.net_rx_bps, &self.config.network);
        self.check_bytes("Network TX", s.net_tx_bps, &self.config.network);
    }

    fn check_percent(&self, name: &str, value: f32, cfg: &ThresholdConfigPercent) {
        if value >= cfg.critical_percent {
            warn!(resource = name, value = value, "critical threshold exceeded");
        } else if value >= cfg.warn_percent {
            warn!(resource = name, value = value, "warning threshold exceeded");
        } else {
            debug!(resource = name, value = value, "within limits");
        }
    }

    fn check_bytes(&self, name: &str, value: u64, cfg: &ThresholdConfigBytes) {
        if value >= cfg.critical_bytes_per_sec {
            warn!(resource = name, value = value, "critical threshold exceeded");
        } else if value >= cfg.warn_bytes_per_sec {
            warn!(resource = name, value = value, "warning threshold exceeded");
        } else {
            debug!(resource = name, value = value, "within limits");
        }
    }

    fn manage(&self, s: &ResourceSnapshot) {
        // Example actions. Replace with your real policy:
        // - throttle background jobs
        // - send alerts
        // - trigger cleanup
        // - adjust priorities
        if s.mem_percent >= self.config.memory.critical_percent {
            self.emit_action("memory pressure: recommend cleanup / page cache reclaim");
        }

        if s.cpu_percent >= self.config.cpu.critical_percent {
            self.emit_action("cpu pressure: consider reducing low-priority workloads");
        }

        if s.disk_percent >= self.config.disk.critical_percent {
            self.emit_action("disk pressure: cleanup temporary files / rotate logs");
        }
    }

    fn emit_action(&self, msg: &str) {
        warn!("{msg}");
    }
}

fn load_config(path: impl AsRef<Path>) -> Result<Config> {
    let content = fs::read_to_string(&path)
        .with_context(|| format!("failed to read config file {:?}", path.as_ref()))?;
    let cfg: Config = toml::from_str(&content).context("failed to parse config")?;
    Ok(cfg)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            std::env::var("RUST_LOG").unwrap_or_else(|_| "info,resource_daemon=debug".into()),
        )
        .init();

    let config = load_config("config.toml")?;
    info!(?config, "starting resource daemon");

    let running = Arc::new(AtomicBool::new(true));
    let daemon_running = running.clone();

    let mut daemon = ResourceDaemon::new(config.clone());
    let interval = Duration::from_millis(config.sample_interval_ms);

    let mut ticker = time::interval(interval);
    ticker.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    let main_loop = async move {
        while daemon_running.load(Ordering::Relaxed) {
            ticker.tick().await;

            let snapshot = daemon.sample();
            info!(
                cpu = snapshot.cpu_percent,
                memory = snapshot.mem_percent,
                disk = snapshot.disk_percent,
                net_rx_bps = snapshot.net_rx_bps,
                net_tx_bps = snapshot.net_tx_bps,
                "resource snapshot"
            );

            daemon.evaluate(&snapshot);
            daemon.manage(&snapshot);
        }
    };

    tokio::select! {
        res = main_loop => {
            if let Err(e) = res {
                error!(error = %e, "daemon loop failed");
            }
        }
        _ = shutdown_signal() => {
            info!("shutdown signal received");
            running.store(false, Ordering::Relaxed);
        }
    }

    info!("daemon stopped");
    Ok(())
}

async fn shutdown_signal() {
    #[cfg(unix)]
    {
        use tokio::signal::unix::{signal as unix_signal, SignalKind};

        let mut sigterm = unix_signal(SignalKind::terminate()).expect("failed to register SIGTERM");
        tokio::select! {
            _ = signal::ctrl_c() => {}
            _ = sigterm.recv() => {}
        }
    }

    #[cfg(not(unix))]
    {
        let _ = signal::ctrl_c().await;
    }
}
