use anyhow::Result;
use parking_lot::RwLock;
use serde::Serialize;
use std::{
    collections::VecDeque,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{DiskExt, ProcessExt, System, SystemExt};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{UnixListener, UnixStream},
    time::interval,
};
use tracing::{error, info, warn};
use tracing_subscriber::EnvFilter;

const SOCKET_PATH: &str = "/tmp/resource_daemon.sock";
const SAMPLE_HISTORY: usize = 60;
const SAMPLE_INTERVAL_SECS: u64 = 5;

#[derive(Debug, Clone, Serialize)]
struct Sample {
    timestamp_unix: u64,
    cpu_usage: f32,
    memory_used_mb: u64,
    memory_total_mb: u64,
    memory_percent: f32,
    disk_used_gb: u64,
    disk_total_gb: u64,
    disk_percent: f32,
    top_processes: Vec<ProcessSample>,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSample {
    pid: i32,
    name: String,
    cpu_usage: f32,
    memory_mb: u64,
}

#[derive(Debug, Default, Serialize)]
struct DaemonState {
    latest: Option<Sample>,
    history_len: usize,
}

struct SharedState {
    latest: Option<Sample>,
    history: VecDeque<Sample>,
}

impl SharedState {
    fn new() -> Self {
        Self {
            latest: None,
            history: VecDeque::with_capacity(SAMPLE_HISTORY),
        }
    }

    fn update(&mut self, sample: Sample) {
        self.latest = Some(sample.clone());
        if self.history.len() == SAMPLE_HISTORY {
            self.history.pop_front();
        }
        self.history.push_back(sample);
    }

    fn snapshot(&self) -> DaemonState {
        DaemonState {
            latest: self.latest.clone(),
            history_len: self.history.len(),
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    info!("resource daemon starting");

    // Remove stale socket if present
    let _ = std::fs::remove_file(SOCKET_PATH);

    let state = Arc::new(RwLock::new(SharedState::new()));

    let monitor_state = state.clone();
    let server_state = state.clone();

    let monitor_task = tokio::spawn(async move {
        monitor_loop(monitor_state).await;
    });

    let server_task = tokio::spawn(async move {
        if let Err(e) = serve_socket(server_state).await {
            error!("socket server error: {e:?}");
        }
    });

    tokio::signal::ctrl_c().await?;
    info!("shutdown requested");

    let _ = std::fs::remove_file(SOCKET_PATH);

    monitor_task.abort();
    server_task.abort();

    Ok(())
}

async fn monitor_loop(state: Arc<RwLock<SharedState>>) {
    let mut ticker = interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));
    let mut sys = System::new_all();

    loop {
        ticker.tick().await;

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_disks_list();
        sys.refresh_disks();
        sys.refresh_processes();

        let cpu_usage = sys.global_cpu_info().cpu_usage();

        let memory_total_mb = sys.total_memory() / 1024;
        let memory_used_mb = sys.used_memory() / 1024;
        let memory_percent = if memory_total_mb == 0 {
            0.0
        } else {
            (memory_used_mb as f32 / memory_total_mb as f32) * 100.0
        };

        let mut disk_total_bytes = 0u64;
        let mut disk_used_bytes = 0u64;
        for disk in sys.disks() {
            let total = disk.total_space();
            let available = disk.available_space();
            disk_total_bytes += total;
            disk_used_bytes += total.saturating_sub(available);
        }

        let disk_total_gb = disk_total_bytes / (1024 * 1024 * 1024);
        let disk_used_gb = disk_used_bytes / (1024 * 1024 * 1024);
        let disk_percent = if disk_total_bytes == 0 {
            0.0
        } else {
            (disk_used_bytes as f32 / disk_total_bytes as f32) * 100.0
        };

        let mut processes: Vec<ProcessSample> = sys
            .processes()
            .iter()
            .map(|(pid, proc_)| ProcessSample {
                pid: pid.as_u32() as i32,
                name: proc_.name().to_string(),
                cpu_usage: proc_.cpu_usage(),
                memory_mb: proc_.memory() / 1024,
            })
            .collect();

        processes.sort_by(|a, b| {
            b.cpu_usage
                .partial_cmp(&a.cpu_usage)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        processes.truncate(5);

        let sample = Sample {
            timestamp_unix: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
            cpu_usage,
            memory_used_mb,
            memory_total_mb,
            memory_percent,
            disk_used_gb,
            disk_total_gb,
            disk_percent,
            top_processes: processes,
        };

        {
            let mut guard = state.write();
            guard.update(sample.clone());
        }

        if sample.cpu_usage > 90.0 {
            warn!("high CPU usage: {:.1}%", sample.cpu_usage);
        }
        if sample.memory_percent > 90.0 {
            warn!("high memory usage: {:.1}%", sample.memory_percent);
        }
        if sample.disk_percent > 90.0 {
            warn!("high disk usage: {:.1}%", sample.disk_percent);
        }

        info!(
            "sample cpu={:.1}% mem={:.1}% disk={:.1}%",
            sample.cpu_usage, sample.memory_percent, sample.disk_percent
        );
    }
}

async fn serve_socket(state: Arc<RwLock<SharedState>>) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)?;
    info!("listening on {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state).await {
                error!("client error: {e:?}");
            }
        });
    }
}

async fn handle_client(mut stream: UnixStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let mut buf = [0u8; 1024];
    let n = stream.read(&mut buf).await?;
    let req = String::from_utf8_lossy(&buf[..n]).trim().to_string();

    match req.as_str() {
        "status" => {
            let snapshot = state.read().snapshot();
            let body = serde_json::to_string_pretty(&snapshot)?;
            stream.write_all(body.as_bytes()).await?;
        }
        "help" => {
            let body = b"Commands: status | help\n";
            stream.write_all(body).await?;
        }
        _ => {
            stream.write_all(b"Unknown command. Try: help\n").await?;
        }
    }

    Ok(())
}
