use anyhow::Result;
use axum::{
    extract::State,
    response::IntoResponse,
    routing::get,
    Json, Router,
};
use parking_lot::RwLock;
use serde::Serialize;
use std::{
    net::SocketAddr,
    sync::Arc,
    time::Duration,
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::{signal, task, time};
use tracing::{info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Clone)]
struct AppState {
    metrics: Arc<RwLock<MetricsSnapshot>>,
    config: Arc<RwLock<DaemonConfig>>,
}

#[derive(Debug, Clone)]
struct DaemonConfig {
    cpu_warn_pct: f32,
    mem_warn_pct: f32,
    disk_warn_pct: f32,
    sample_interval_ms: u64,
}

impl Default for DaemonConfig {
    fn default() -> Self {
        Self {
            cpu_warn_pct: 85.0,
            mem_warn_pct: 85.0,
            disk_warn_pct: 90.0,
            sample_interval_ms: 1000,
        }
    }
}

#[derive(Debug, Clone, Serialize, Default)]
struct MetricsSnapshot {
    cpu_usage_pct: f32,
    memory_total_mb: u64,
    memory_used_mb: u64,
    memory_usage_pct: f32,
    disk_total_gb: u64,
    disk_used_gb: u64,
    disk_usage_pct: f32,
    load_avg_1m: f64,
    load_avg_5m: f64,
    load_avg_15m: f64,
    process_count: usize,
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse()?))
        .init();

    let state = AppState {
        metrics: Arc::new(RwLock::new(MetricsSnapshot::default())),
        config: Arc::new(RwLock::new(DaemonConfig::default())),
    };

    let sampler_state = state.clone();
    task::spawn(async move {
        sampler_loop(sampler_state).await;
    });

    let app = Router::new()
        .route("/metrics", get(metrics_handler))
        .route("/health", get(health_handler))
        .with_state(state.clone());

    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    info!("daemon listening on {}", addr);

    let server = axum::serve(tokio::net::TcpListener::bind(addr).await?, app);

    tokio::select! {
        res = server => {
            if let Err(e) = res {
                warn!("server error: {e}");
            }
        }
        _ = shutdown_signal() => {
            info!("shutdown signal received");
        }
    }

    Ok(())
}

async fn sampler_loop(state: AppState) {
    let mut system = System::new_all();

    loop {
        let interval_ms = {
            let cfg = state.config.read();
            cfg.sample_interval_ms
        };

        system.refresh_all();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let total_mem_mb = system.total_memory() / 1024;
        let used_mem_mb = system.used_memory() / 1024;
        let mem_pct = if total_mem_mb > 0 {
            (used_mem_mb as f32 / total_mem_mb as f32) * 100.0
        } else {
            0.0
        };

        let mut disk_total_gb = 0u64;
        let mut disk_used_gb = 0u64;
        for disk in system.disks() {
            let total = disk.total_space() / (1024 * 1024 * 1024);
            let used = (disk.total_space() - disk.available_space()) / (1024 * 1024 * 1024);
            disk_total_gb += total;
            disk_used_gb += used;
        }
        let disk_pct = if disk_total_gb > 0 {
            (disk_used_gb as f32 / disk_total_gb as f32) * 100.0
        } else {
            0.0
        };

        let load_avg = System::load_average();
        let process_count = system.processes().len();

        let snapshot = MetricsSnapshot {
            cpu_usage_pct: cpu_usage,
            memory_total_mb: total_mem_mb,
            memory_used_mb: used_mem_mb,
            memory_usage_pct: mem_pct,
            disk_total_gb,
            disk_used_gb,
            disk_usage_pct: disk_pct,
            load_avg_1m: load_avg.one,
            load_avg_5m: load_avg.five,
            load_avg_15m: load_avg.fifteen,
            process_count,
        };

        {
            let mut metrics = state.metrics.write();
            *metrics = snapshot.clone();
        }

        evaluate_thresholds(&state, &snapshot);

        time::sleep(Duration::from_millis(interval_ms)).await;
    }
}

fn evaluate_thresholds(state: &AppState, snapshot: &MetricsSnapshot) {
    let cfg = state.config.read();

    if snapshot.cpu_usage_pct >= cfg.cpu_warn_pct {
        warn!("high CPU usage: {:.2}%", snapshot.cpu_usage_pct);
    }

    if snapshot.memory_usage_pct >= cfg.mem_warn_pct {
        warn!("high memory usage: {:.2}%", snapshot.memory_usage_pct);
    }

    if snapshot.disk_usage_pct >= cfg.disk_warn_pct {
        warn!("high disk usage: {:.2}%", snapshot.disk_usage_pct);
    }
}

async fn metrics_handler(State(state): State<AppState>) -> impl IntoResponse {
    let snapshot = state.metrics.read().clone();
    Json(snapshot)
}

async fn health_handler() -> impl IntoResponse {
    "ok"
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c().await.expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};
        let mut sigterm = signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}
