use hyper::{Body, Request, Response, Server, StatusCode};
use once_cell::sync::Lazy;
use parking_lot::RwLock;
use serde::Serialize;
use std::convert::Infallible;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::{Duration, Instant};
use sysinfo::{CpuExt, DiskExt, NetworkExt, ProcessExt, System, SystemExt};
use tokio::signal;
use tokio::time;
use tracing::{error, info, warn};

static METRICS: Lazy<Arc<RwLock<SystemSnapshot>>> = Lazy::new(|| {
    Arc::new(RwLock::new(SystemSnapshot::default()))
});

#[derive(Debug, Clone, Serialize)]
struct SystemSnapshot {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    total_swap_kib: u64,
    used_swap_kib: u64,
    disk_total_bytes: u64,
    disk_available_bytes: u64,
    net_received_bytes: u64,
    net_transmitted_bytes: u64,
    process_count: usize,
}

impl Default for SystemSnapshot {
    fn default() -> Self {
        Self {
            timestamp_unix_ms: 0,
            cpu_usage_percent: 0.0,
            total_memory_kib: 0,
            used_memory_kib: 0,
            total_swap_kib: 0,
            used_swap_kib: 0,
            disk_total_bytes: 0,
            disk_available_bytes: 0,
            net_received_bytes: 0,
            net_transmitted_bytes: 0,
            process_count: 0,
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(std::env::var("RUST_LOG").unwrap_or_else(|_| "info".into()))
        .init();

    let addr: SocketAddr = std::env::var("SYSGUARDD_BIND")
        .unwrap_or_else(|_| "127.0.0.1:8080".into())
        .parse()?;

    info!("starting sysguardd on {}", addr);

    let monitor_handle = tokio::spawn(metric_loop(Duration::from_secs(1)));
    let server_handle = tokio::spawn(run_http_server(addr));

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown requested");
        }
        res = monitor_handle => {
            if let Err(e) = res {
                error!("monitor task failed: {}", e);
            }
        }
        res = server_handle => {
            if let Err(e) = res {
                error!("server task failed: {}", e);
            }
        }
    }

    info!("sysguardd stopped");
    Ok(())
}

async fn metric_loop(period: Duration) {
    let mut sys = System::new_all();
    let mut ticker = time::interval(period);

    loop {
        ticker.tick().await;
        let started = Instant::now();

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_disks_list();
        sys.refresh_disks();
        sys.refresh_networks_list();
        sys.refresh_networks();
        sys.refresh_processes();

        let cpu_usage = sys.global_cpu_info().cpu_usage();
        let memory_total = sys.total_memory();
        let memory_used = sys.used_memory();
        let swap_total = sys.total_swap();
        let swap_used = sys.used_swap();

        let mut disk_total = 0u64;
        let mut disk_available = 0u64;
        for d in sys.disks() {
            disk_total += d.total_space();
            disk_available += d.available_space();
        }

        let mut net_rx = 0u64;
        let mut net_tx = 0u64;
        for (_, data) in sys.networks() {
            net_rx += data.received();
            net_tx += data.transmitted();
        }

        let process_count = sys.processes().len();

        let snapshot = SystemSnapshot {
            timestamp_unix_ms: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis(),
            cpu_usage_percent: cpu_usage,
            total_memory_kib: memory_total,
            used_memory_kib: memory_used,
            total_swap_kib: swap_total,
            used_swap_kib: swap_used,
            disk_total_bytes: disk_total,
            disk_available_bytes: disk_available,
            net_received_bytes: net_rx,
            net_transmitted_bytes: net_tx,
            process_count,
        };

        {
            let mut guard = METRICS.write();
            *guard = snapshot;
        }

        // Simple policy hook example: log when memory usage is high.
        let mem_pct = if memory_total > 0 {
            (memory_used as f64 / memory_total as f64) * 100.0
        } else {
            0.0
        };

        if mem_pct > 90.0 {
            warn!("high memory usage detected: {:.1}%", mem_pct);
            // Future: trigger remediation, notify, throttle, or isolate workloads.
        }

        tracing::debug!("metrics refresh took {:?}", started.elapsed());
    }
}

async fn run_http_server(addr: SocketAddr) -> Result<()> {
    let make_svc = make_service_fn(|_conn| async {
        Ok::<_, Infallible>(service_fn(handle_request))
    });

    let server = Server::bind(&addr).serve(make_svc);

    info!("http status endpoint listening on http://{}", addr);

    server.await?;
    Ok(())
}

async fn handle_request(req: Request<Body>) -> Result<Response<Body>, Infallible> {
    match (req.method(), req.uri().path()) {
        (&hyper::Method::GET, "/health") => Ok(json_response(serde_json::json!({
            "status": "ok"
        }))),
        (&hyper::Method::GET, "/metrics") => {
            let snapshot = METRICS.read().clone();
            Ok(json_response(snapshot))
        }
        _ => Ok(response_with_status(
            StatusCode::NOT_FOUND,
            Body::from("not found"),
        )),
    }
}

fn json_response<T: Serialize>(value: T) -> Response<Body> {
    match serde_json::to_vec(&value) {
        Ok(body) => Response::builder()
            .status(StatusCode::OK)
            .header("content-type", "application/json")
            .body(Body::from(body))
            .unwrap(),
        Err(_) => response_with_status(
            StatusCode::INTERNAL_SERVER_ERROR,
            Body::from("serialization error"),
        ),
    }
}

fn response_with_status(status: StatusCode, body: Body) -> Response<Body> {
    Response::builder()
        .status(status)
        .body(body)
        .unwrap()
}
