```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::VecDeque,
    fs,
    path::Path,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::RwLock,
    task,
    time,
};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage_percent: f32,
    total_memory_kb: u64,
    used_memory_kb: u64,
    total_swap_kb: u64,
    used_swap_kb: u64,
    load_avg_1m: f64,
    load_avg_5m: f64,
    load_avg_15m: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ControlCommand {
    GetStatus,
    SetSamplingInterval { millis: u64 },
    GetHistory,
    Shutdown,
}

#[derive(Debug, Clone, Serialize)]
struct StatusResponse {
    ok: bool,
    sampling_interval_ms: u64,
    latest: Option<ResourceSnapshot>,
    history_len: usize,
}

#[derive(Debug, Clone, Serialize)]
struct CommandResponse {
    ok: bool,
    message: String,
    status: Option<StatusResponse>,
    history: Option<Vec<ResourceSnapshot>>,
}

struct DaemonState {
    sampling_interval: RwLock<Duration>,
    latest: RwLock<Option<ResourceSnapshot>>,
    history: RwLock<VecDeque<ResourceSnapshot>>,
    shutdown: AtomicBool,
}

impl DaemonState {
    fn new(initial_interval: Duration, history_capacity: usize) -> Self {
        Self {
            sampling_interval: RwLock::new(initial_interval),
            latest: RwLock::new(None),
            history: RwLock::new(VecDeque::with_capacity(history_capacity)),
            shutdown: AtomicBool::new(false),
        }
    }

    async fn push_snapshot(&self, snapshot: ResourceSnapshot, history_capacity: usize) {
        {
            let mut latest = self.latest.write().await;
            *latest = Some(snapshot.clone());
        }

        {
            let mut history = self.history.write().await;
            if history.len() == history_capacity {
                history.pop_front();
            }
            history.push_back(snapshot);
        }
    }

    async fn status(&self) -> StatusResponse {
        let sampling_interval_ms = self.sampling_interval.read().await.as_millis() as u64;
        let latest = self.latest.read().await.clone();
        let history_len = self.history.read().await.len();

        StatusResponse {
            ok: true,
            sampling_interval_ms,
            latest,
            history_len,
        }
    }
}

fn collect_snapshot(sys: &mut System) -> ResourceSnapshot {
    sys.refresh_cpu();
    sys.refresh_memory();

    let load = sys.load_average();
    let cpu = sys.global_cpu_info().cpu_usage();

    ResourceSnapshot {
        timestamp_ms: Instant::now().elapsed().as_millis(),
        cpu_usage_percent: cpu,
        total_memory_kb: sys.total_memory(),
        used_memory_kb: sys.used_memory(),
        total_swap_kb: sys.total_swap(),
        used_swap_kb: sys.used_swap(),
        load_avg_1m: load.one,
        load_avg_5m: load.five,
        load_avg_15m: load.fifteen,
    }
}

async fn monitoring_loop(state: Arc<DaemonState>, history_capacity: usize) -> Result<()> {
    let mut sys = System::new_all();

    loop {
        if state.shutdown.load(Ordering::Relaxed) {
            break;
        }

        let interval = *state.sampling_interval.read().await;
        let snapshot = collect_snapshot(&mut sys);
        state.push_snapshot(snapshot, history_capacity).await;

        time::sleep(interval).await;
    }

    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<DaemonState>,
    history_capacity: usize,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    while let Some(line) = lines.next_line().await? {
        let cmd: Result<ControlCommand, _> = serde_json::from_str(&line).map_err(Into::into);

        let response = match cmd {
            Ok(ControlCommand::GetStatus) => {
                let status = state.status().await;
                CommandResponse {
                    ok: true,
                    message: "status_ok".to_string(),
                    status: Some(status),
                    history: None,
                }
            }
            Ok(ControlCommand::SetSamplingInterval { millis }) => {
                if millis < 100 {
                    CommandResponse {
                        ok: false,
                        message: "sampling interval too low; minimum is 100ms".to_string(),
                        status: None,
                        history: None,
                    }
                } else {
                    *state.sampling_interval.write().await = Duration::from_millis(millis);
                    CommandResponse {
                        ok: true,
                        message: format!("sampling interval set to {}ms", millis),
                        status: Some(state.status().await),
                        history: None,
                    }
                }
            }
            Ok(ControlCommand::GetHistory) => {
                let history = state.history.read().await.iter().cloned().collect::<Vec<_>>();
                CommandResponse {
                    ok: true,
                    message: "history_ok".to_string(),
                    status: None,
                    history: Some(history),
                }
            }
            Ok(ControlCommand::Shutdown) => {
                state.shutdown.store(true, Ordering::SeqCst);
                CommandResponse {
                    ok: true,
                    message: "shutdown requested".to_string(),
                    status: Some(state.status().await),
                    history: None,
                }
            }
            Err(e) => CommandResponse {
                ok: false,
                message: format!("invalid command: {}", e),
                status: None,
                history: None,
            },
        };

        let json = serde_json::to_string(&response)?;
        writer.write_all(json.as_bytes()).await?;
        writer.write_all(b"\n").await?;

        if state.shutdown.load(Ordering::Relaxed) {
            break;
        }
    }

    let _ = history_capacity; // reserved for future per-client policy
    Ok(())
}

async fn control_server(
    socket_path: &str,
    state: Arc<DaemonState>,
    history_capacity: usize,
) -> Result<()> {
    if Path::new(socket_path).exists() {
        fs::remove_file(socket_path).with_context(|| format!("removing stale socket {socket_path}"))?;
    }

    let listener = UnixListener::bind(socket_path)
        .with_context(|| format!("binding unix socket at {socket_path}"))?;

    info!("control socket listening at {}", socket_path);

    loop {
        if state.shutdown.load(Ordering::Relaxed) {
            break;
        }

        let accept = listener.accept();
        tokio::select! {
            res = accept => {
                match res {
                    Ok((stream, _addr)) => {
                        let state = state.clone();
                        task::spawn(async move {
                            if let Err(e) = handle_client(stream, state, history_capacity).await {
                                error!("client handler error: {e:?}");
                            }
                        });
                    }
                    Err(e) => {
                        warn!("accept error: {e:?}");
                        time::sleep(Duration::from_millis(100)).await;
                    }
                }
            }
            _ = time::sleep(Duration::from_millis(200)) => {}
        }
    }

    if Path::new(socket_path).exists() {
        let _ = fs::remove_file(socket_path);
    }

    Ok(())
}

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    let socket_path = "/tmp/osd.sock";
    let initial_interval = Duration::from_millis(1000);
    let history_capacity = 256;

    let state = Arc::new(DaemonState::new(initial_interval, history_capacity));

    let monitor = {
        let state = state.clone();
        task::spawn(async move {
            if let Err(e) = monitoring_loop(state, history_capacity).await {
                error!("monitoring loop error: {e:?}");
            }
        })
    };

    let control = {
        let state = state.clone();
        task::spawn(async move {
            if let Err(e) = control_server(socket_path, state, history_capacity).await {
                error!("control server error: {e:?}");
            }
        })
    };

    info!("daemon started");

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("termination signal received");
            state.shutdown.store(true, Ordering::SeqCst);
        }
    }

    let _ = monitor.await;
    let _ = control.await;

    info!("daemon stopped");
    Ok(())
}
```

