        Self {
            interval_ms: 1000,
            cpu_threshold: 85.0,
            memory_threshold: 90.0,
            disk_threshold: 90.0,
            processes_to_watch: vec![],
            actions: ActionsConfig {
                enable_kill: false,
                enable_alert: true,
            },
        }
    }
}

impl Config {
    pub fn load(path: Option<&str>) -> anyhow::Result<Self> {
        if let Some(path) = path {
            let content = fs::read_to_string(path)?;
            let cfg: Self = toml::from_str(&content)?;
            Ok(cfg)
        } else {
            Ok(Self::default())
        }
    }
}
