## src/metrics.rs

```rust
use sysinfo::{DiskExt, ProcessExt, ProcessorExt, System, SystemExt};

#[derive(Debug, Clone)]
pub struct MetricsSnapshot {
    pub cpu_usage: f32,
    pub memory_used_percent: f32,
    pub disk_used_percent: f32,
    pub top_processes: Vec<ProcessMetric>,
}

#[derive(Debug, Clone)]
pub struct ProcessMetric {
    pub pid: i32,
    pub name: String,
    pub cpu_usage: f32,
    pub memory_kb: u64,
}

pub struct MetricsCollector {
    system: System,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn collect(&mut self) -> MetricsSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_processor_info().cpu_usage();
        let total_memory = self.system.total_memory() as f32;
        let used_memory = self.system.used_memory() as f32;
        let memory_used_percent = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut total_disk = 0u64;
        let mut used_disk = 0u64;
        for disk in self.system.disks() {
            let total = disk.total_space();
            let avail = disk.available_space();
            total_disk += total;
            used_disk += total.saturating_sub(avail);
        }

        let disk_used_percent = if total_disk > 0 {
            (used_disk as f32 / total_disk as f32) * 100.0
        } else {
            0.0
        };

        let mut procs: Vec<ProcessMetric> = self
            .system
            .processes()
            .iter()
            .map(|(pid, p)| ProcessMetric {
                pid: pid.as_u32() as i32,
                name: p.name().to_string(),
                cpu_usage: p.cpu_usage(),
                memory_kb: p.memory(),
            })
            .collect();

        procs.sort_by(|a, b| b.cpu_usage.total_cmp(&a.cpu_usage));
        procs.truncate(10);

        MetricsSnapshot {
            cpu_usage,
            memory_used_percent,
            disk_used_percent,
            top_processes: procs,
        }
    }
}
```

