use crate::config::Config;
use crate::metrics::{MetricsSnapshot, ProcessMetric};

#[derive(Debug, Clone)]
pub enum PolicyEvent {
    HighCpu(f32),
    HighMemory(f32),
    HighDisk(f32),
    WatchedProcess(String, i32),
}

#[derive(Debug, Clone)]
pub struct PolicyDecision {
    pub events: Vec<PolicyEvent>,
}

pub struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, snapshot: &MetricsSnapshot) -> PolicyDecision {
        let mut events = Vec::new();

        if snapshot.cpu_usage >= self.config.cpu_threshold {
            events.push(PolicyEvent::HighCpu(snapshot.cpu_usage));
        }

        if snapshot.memory_used_percent >= self.config.memory_threshold {
            events.push(PolicyEvent::HighMemory(snapshot.memory_used_percent));
        }

        if snapshot.disk_used_percent >= self.config.disk_threshold {
            events.push(PolicyEvent::HighDisk(snapshot.disk_used_percent));
        }

        if !self.config.processes_to_watch.is_empty() {
            for p in &snapshot.top_processes {
                if self.config.processes_to_watch.iter().any(|w| w == &p.name) {
                    events.push(PolicyEvent::WatchedProcess(p.name.clone(), p.pid));
                }
            }
        }

        PolicyDecision { events }
    }
}
