        match event {
            PolicyEvent::HighCpu(v) => {
                warn!("High CPU usage detected: {:.2}%", v);
                if self.config.actions.enable_alert {
                    info!("ALERT: CPU threshold exceeded");
                }
            }
            PolicyEvent::HighMemory(v) => {
                warn!("High memory usage detected: {:.2}%", v);
                if self.config.actions.enable_alert {
                    info!("ALERT: Memory threshold exceeded");
                }
            }
            PolicyEvent::HighDisk(v) => {
                warn!("High disk usage detected: {:.2}%", v);
                if self.config.actions.enable_alert {
                    info!("ALERT: Disk threshold exceeded");
                }
            }
            PolicyEvent::WatchedProcess(name, pid) => {
                warn!("Watched process detected: {} (pid={})", name, pid);
                if self.config.actions.enable_kill {
                    warn!("Kill action enabled, but not implemented in this initial version");
                }
            }
        }
    }
}
