use crate::actions::ActionExecutor;
use crate::config::Config;
use crate::metrics::MetricsCollector;
use crate::policy::PolicyEngine;
use tokio::time::{self, Duration};
use tracing::info;

pub struct Daemon {
    config: Config,
    metrics: MetricsCollector,
    policy: PolicyEngine,
    actions: ActionExecutor,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self {
            metrics: MetricsCollector::new(),
            policy: PolicyEngine::new(config.clone()),
            actions: ActionExecutor::new(config.clone()),
            config,
        }
    }

    pub async fn run(&mut self) -> anyhow::Result<()> {
        let mut interval = time::interval(Duration::from_millis(self.config.interval_ms));

        loop {
            tokio::select! {
                _ = interval.tick() => {
                    let snapshot = self.metrics.collect();
                    info!(
                        "cpu={:.2}% mem={:.2}% disk={:.2}% top_proc_count={}",
                        snapshot.cpu_usage,
                        snapshot.memory_used_percent,
                        snapshot.disk_used_percent,
                        snapshot.top_processes.len()
                    );

                    let decision = self.policy.evaluate(&snapshot);
                    for event in &decision.events {
                        self.actions.execute(event);
                    }
                }

                _ = tokio::signal::ctrl_c() => {
                    info!("Shutdown signal received");
                    break;
                }
            }
        }

        Ok(())
    }
}
