```rust
use anyhow::{Context, Result};
use clap::Parser;
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::PathBuf,
    sync::Arc,
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    sync::{mpsc, RwLock},
    time,
};
use tracing::{error, info, warn};

use sysinfo::{CpuRefreshKind, DiskRefreshKind, MemoryRefreshKind, RefreshKind, System};

#[derive(Parser, Debug)]
#[command(name = "sysd")]
struct Args {
    /// Unix socket path for control plane
    #[arg(long, default_value = "/run/sysd.sock")]
    socket: PathBuf,

    /// Sampling interval in milliseconds
    #[arg(long, default_value_t = 1000)]
    interval_ms: u64,

    /// Enable verbose logs
    #[arg(long, default_value_t = false)]
    verbose: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    ts_unix_ms: u128,
    hostname: Option<String>,
    cpu_usage_percent: f32,
    mem_total_kib: u64,
    mem_used_kib: u64,
    mem_used_percent: f32,
    swap_total_kib: u64,
    swap_used_kib: u64,
    load_avg_1: f64,
    load_avg_5: f64,
    load_avg_15: f64,
    disks: Vec<DiskSnapshot>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_bytes: u64,
    available_bytes: u64,
    used_percent: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct DaemonState {
    snapshot: ResourceSnapshot,
    thresholds: Thresholds,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Thresholds {
    cpu_warn_percent: f32,
    mem_warn_percent: f32,
    disk_warn_percent: f32,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_warn_percent: 85.0,
            mem_warn_percent: 90.0,
            disk_warn_percent: 90.0,
        }
    }
}

#[derive(Debug)]
enum ControlRequest {
    Status,
    SetThresholds(Thresholds),
    Shutdown,
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", content = "data")]
enum ControlResponse {
    Ok,
    Status(DaemonState),
    Error(String),
}

#[derive(Debug)]
enum Event {
    Control(ControlRequest),
    Tick,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    let env_filter = if args.verbose {
        "debug"
    } else {
        "info"
    };
    tracing_subscriber::fmt()
        .with_env_filter(env_filter)
        .compact()
        .init();

    let state = Arc::new(RwLock::new(init_state()));
    let (tx, mut rx) = mpsc::unbounded_channel::<Event>();

    if args.socket.exists() {
        std::fs::remove_file(&args.socket)
            .with_context(|| format!("failed to remove stale socket at {:?}", args.socket))?;
    }

    let listener = UnixListener::bind(&args.socket)
        .with_context(|| format!("failed to bind socket at {:?}", args.socket))?;

    info!("sysd listening on {:?}", args.socket);

    let tx_tick = tx.clone();
    tokio::spawn(async move {
        let mut interval = time::interval(Duration::from_millis(args.interval_ms));
        loop {
            interval.tick().await;
            let _ = tx_tick.send(Event::Tick);
        }
    });

    let tx_accept = tx.clone();
    let accept_handle = tokio::spawn(async move {
        loop {
            match listener.accept().await {
                Ok((stream, _addr)) => {
                    let tx_conn = tx_accept.clone();
                    tokio::spawn(async move {
                        if let Err(e) = handle_client(stream, tx_conn).await {
                            warn!("client handler error: {e:#}");
                        }
                    });
                }
                Err(e) => {
                    error!("accept failed: {e:#}");
                    break;
                }
            }
        }
    });

    // Main event loop
    let mut shutting_down = false;
    while let Some(event) = rx.recv().await {
        match event {
            Event::Tick => {
                let mut guard = state.write().await;
                refresh_state(&mut guard.snapshot);

                enforce_policies(&guard.snapshot, &guard.thresholds);
            }
            Event::Control(req) => match req {
                ControlRequest::Status => {
                    // handled in client connection via shared state
                }
                ControlRequest::SetThresholds(new_thresholds) => {
                    let mut guard = state.write().await;
                    guard.thresholds = new_thresholds;
                    info!("thresholds updated");
                }
                ControlRequest::Shutdown => {
                    info!("shutdown requested");
                    shutting_down = true;
                    break;
                }
            },
        }
    }

    if shutting_down {
        accept_handle.abort();
        let _ = std::fs::remove_file(&args.socket);
        info!("sysd exited cleanly");
    }

    Ok(())
}

fn init_state() -> DaemonState {
    DaemonState {
        snapshot: collect_snapshot(),
        thresholds: Thresholds::default(),
    }
}

fn collect_snapshot() -> ResourceSnapshot {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    sys.refresh_all();

    let hostname = sysinfo::System::host_name();
    let load = sysinfo::System::load_average();

    let mem_total_kib = sys.total_memory();
    let mem_used_kib = sys.used_memory();
    let mem_used_percent = if mem_total_kib > 0 {
        (mem_used_kib as f32 * 100.0) / mem_total_kib as f32
    } else {
        0.0
    };

    let swap_total_kib = sys.total_swap();
    let swap_used_kib = sys.used_swap();

    let cpu_usage_percent = if sys.cpus().is_empty() {
        0.0
    } else {
        sys.cpus().iter().map(|c| c.cpu_usage()).sum::<f32>() / sys.cpus().len() as f32
    };

    let disks = sys
        .disks()
        .iter()
        .map(|d| {
            let total_bytes = d.total_space();
            let available_bytes = d.available_space();
            let used_bytes = total_bytes.saturating_sub(available_bytes);
            let used_percent = if total_bytes > 0 {
                (used_bytes as f32 * 100.0) / total_bytes as f32
            } else {
                0.0
            };

            DiskSnapshot {
                name: d.name().to_string_lossy().into_owned(),
                mount_point: d.mount_point().to_string_lossy().into_owned(),
                total_bytes,
                available_bytes,
                used_percent,
            }
        })
        .collect();

    ResourceSnapshot {
        ts_unix_ms: now_unix_ms(),
        hostname,
        cpu_usage_percent,
        mem_total_kib,
        mem_used_kib,
        mem_used_percent,
        swap_total_kib,
        swap_used_kib,
        load_avg_1: load.one,
        load_avg_5: load.five,
        load_avg_15: load.fifteen,
        disks,
    }
}

fn refresh_state(snapshot: &mut ResourceSnapshot) {
    // For initial implementation, collect a fresh snapshot.
    // Later this can be optimized into incremental refreshes.
    *snapshot = collect_snapshot();
}

fn enforce_policies(snapshot: &ResourceSnapshot, thresholds: &Thresholds) {
    if snapshot.cpu_usage_percent >= thresholds.cpu_warn_percent {
        warn!(
            "high CPU usage: {:.1}% >= {:.1}%",
            snapshot.cpu_usage_percent, thresholds.cpu_warn_percent
        );
    }
    if snapshot.mem_used_percent >= thresholds.mem_warn_percent {
        warn!(
            "high memory usage: {:.1}% >= {:.1}%",
            snapshot.mem_used_percent, thresholds.mem_warn_percent
        );
    }

    for disk in &snapshot.disks {
        if disk.used_percent >= thresholds.disk_warn_percent {
            warn!(
                "high disk usage on {}: {:.1}% >= {:.1}%",
                disk.mount_point, disk.used_percent, thresholds.disk_warn_percent
            );
        }
    }
}

async fn handle_client(mut stream: UnixStream, tx: mpsc::UnboundedSender<Event>) -> Result<()> {
    let peer = stream.peer_addr().ok();

    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    reader
        .read_line(&mut line)
        .await
        .context("failed to read request")?;

    let req = line.trim();
    let request = parse_request(req)?;

    let response = match request {
        ControlRequest::Status => {
            // We respond directly with fresh snapshot, using a local collection for now.
            let state = init_state();
            ControlResponse::Status(state)
        }
        ControlRequest::SetThresholds(_) => {
            tx.send(Event::Control(request))
                .map_err(|_| anyhow::anyhow!("control channel closed"))?;
            ControlResponse::Ok
        }
        ControlRequest::Shutdown => {
            tx.send(Event::Control(ControlRequest::Shutdown))
                .map_err(|_| anyhow::anyhow!("control channel closed"))?;
            ControlResponse::Ok
        }
    };

    let mut stream = reader.into_inner();
    let json = serde_json::to_vec(&response)?;
    stream.write_all(&json).await?;
    stream.write_all(b"\n").await?;
    stream.flush().await?;

    if peer.is_some() {
        info!("handled client request");
    }

    Ok(())
}

fn parse_request(s: &str) -> Result<ControlRequest> {
    // Simple line-based protocol:
    //   status
    //   shutdown
    //   set cpu=85 mem=90 disk=90
    let parts: Vec<&str> = s.split_whitespace().collect();
    if parts.is_empty() {
        anyhow::bail!("empty request");
    }

    match parts[0].to_lowercase().as_str() {
        "status" => Ok(ControlRequest::Status),
        "shutdown" => Ok(ControlRequest::Shutdown),
        "set" => {
            let mut vals: HashMap<String, f32> = HashMap::new();
            for p in &parts[1..] {
                let mut kv = p.splitn(2, '=');
                let k = kv.next().unwrap_or("").to_lowercase();
                let v = kv
                    .next()
                    .ok_or_else(|| anyhow::anyhow!("invalid pair: {p}"))?
                    .parse::<f32>()
                    .with_context(|| format!("invalid number in pair: {p}"))?;
                vals.insert(k, v);
            }

            let thresholds = Thresholds {
                cpu_warn_percent: *vals.get("cpu").unwrap_or(&85.0),
                mem_warn_percent: *vals.get("mem").unwrap_or(&90.0),
                disk_warn_percent: *vals.get("disk").unwrap_or(&90.0),
            };

            Ok(ControlRequest::SetThresholds(thresholds))
        }
        _ => anyhow::bail!("unknown command"),
    }
}

fn now_unix_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}
