## `src/monitor.rs`

```rust
use crate::{config::Config, metrics::Metrics};
use std::{
    sync::{Arc, RwLock},
    time::{SystemTime, UNIX_EPOCH},
};
use sysinfo::{Disks, System};

pub struct Monitor {
    system: System,
    disks: Disks,
    metrics: Arc<RwLock<Metrics>>,
    config: Config,
}

impl Monitor {
    pub fn new(config: Config, metrics: Arc<RwLock<Metrics>>) -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let mut disks = Disks::new_with_refreshed_list();
        disks.refresh();

        Self {
            system,
            disks,
            metrics,
            config,
        }
    }

    pub fn poll(&mut self) {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();

        self.disks.refresh();

        let cpu_usage_pct = self.system.global_cpu_info().cpu_usage();
        let memory_total_kib = self.system.total_memory();
        let memory_used_kib = self.system.used_memory();
        let memory_usage_pct = if memory_total_kib > 0 {
            (memory_used_kib as f32 / memory_total_kib as f32) * 100.0
        } else {
            0.0
        };

        let mut disk_total_bytes = 0u64;
        let mut disk_used_bytes = 0u64;

        for disk in self.disks.list() {
            let total = disk.total_space();
            let avail = disk.available_space();
            disk_total_bytes += total;
            disk_used_bytes += total.saturating_sub(avail);
        }

        let disk_usage_pct = if disk_total_bytes > 0 {
            (disk_used_bytes as f32 / disk_total_bytes as f32) * 100.0
        } else {
            0.0
        };

        let process_count = self.system.processes().len();
        let timestamp_unix_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_millis())
            .unwrap_or(0);

        let new_metrics = Metrics {
            cpu_usage_pct,
            memory_total_kib,
            memory_used_kib,
            memory_usage_pct,
            disk_total_bytes,
            disk_used_bytes,
            disk_usage_pct,
            process_count,
            timestamp_unix_ms,
        };

        {
            let mut guard = self.metrics.write().expect("metrics lock poisoned");
            *guard = new_metrics;
        }

        self.evaluate_thresholds();
    }

    fn evaluate_thresholds(&self) {
        let metrics = self.metrics.read().expect("metrics lock poisoned");

        if metrics.cpu_usage_pct >= self.config.cpu_warn_pct {
            tracing::warn!(
                "CPU usage high: {:.1}% >= {:.1}%",
                metrics.cpu_usage_pct,
                self.config.cpu_warn_pct
            );
        }

        if metrics.memory_usage_pct >= self.config.mem_warn_pct {
            tracing::warn!(
                "Memory usage high: {:.1}% >= {:.1}%",
                metrics.memory_usage_pct,
                self.config.mem_warn_pct
            );
        }

        if metrics.disk_usage_pct >= self.config.disk_warn_pct {
            tracing::warn!(
                "Disk usage high: {:.1}% >= {:.1}%",
                metrics.disk_usage_pct,
                self.config.disk_warn_pct
            );
        }
    }
}
