use crate::metrics::Metrics;
use std::sync::{Arc, RwLock};
use warp::Filter;

pub async fn serve(metrics: Arc<RwLock<Metrics>>, bind: String) {
    let metrics_filter = warp::any().map(move || metrics.clone());

    let health = warp::path("health")
        .and(warp::get())
        .map(|| warp::reply::json(&serde_json::json!({ "status": "ok" })));

    let status = warp::path("status")
        .and(warp::get())
        .and(metrics_filter)
        .map(|metrics: Arc<RwLock<Metrics>>| {
            let snapshot = metrics.read().expect("metrics lock poisoned").clone();
            warp::reply::json(&snapshot)
        });

    let routes = health.or(status);

    let addr: std::net::SocketAddr = bind.parse().expect("invalid bind address");
    warp::serve(routes).run(addr).await;
}
