```rust
mod config;
mod metrics;
mod monitor;
mod server;

use anyhow::Result;
use config::Config;
use metrics::Metrics;
use monitor::Monitor;
use std::{
    sync::{Arc, RwLock},
    time::Duration,
};
use tokio::signal;
use tracing_subscriber::EnvFilter;

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let config = Config::default();
    let metrics = Arc::new(RwLock::new(Metrics::default()));

    let server_metrics = metrics.clone();
    let server_bind = config.http_bind.clone();

    tokio::spawn(async move {
        server::serve(server_metrics, server_bind).await;
    });

    let poll_metrics = metrics.clone();
    let poll_config = config.clone();

    let mut monitor = Monitor::new(poll_config.clone(), poll_metrics);

    let mut interval = tokio::time::interval(Duration::from_secs(poll_config.interval_secs));
    tracing::info!("sysd started");

    loop {
        tokio::select! {
            _ = interval.tick() => {
                monitor.poll();
            }
            _ = signal::ctrl_c() => {
                tracing::info!("shutdown signal received");
                break;
            }
        }
    }

    Ok(())
}
```

