use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};

#[derive(Debug)]
pub struct DaemonState {
    pub running: AtomicBool,
    pub last_cpu_percent: AtomicU64,
    pub last_memory_percent: AtomicU64,
    pub last_disk_percent: AtomicU64,
}

impl DaemonState {
    pub fn new() -> Self {
        Self {
            running: AtomicBool::new(true),
            last_cpu_percent: AtomicU64::new(0),
            last_memory_percent: AtomicU64::new(0),
            last_disk_percent: AtomicU64::new(0),
        }
    }

    pub fn set_f64(atom: &AtomicU64, value: f64) {
        atom.store(value.to_bits(), Ordering::Relaxed);
    }

    pub fn get_f64(atom: &AtomicU64) -> f64 {
        f64::from_bits(atom.load(Ordering::Relaxed))
    }
}
