## `src/monitor.rs`

```rust
use crate::{config::Config, state::DaemonState};
use std::sync::Arc;
use sysinfo::{CpuRefreshKind, DiskRefreshKind, RefreshKind, System};
use tokio::time::{sleep, Duration};
use tracing::{info, warn};

pub async fn monitor_loop(config: Config, state: Arc<DaemonState>) {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks_list()
            .with_disks(DiskRefreshKind::everything()),
    );

    loop {
        if !state.running.load(std::sync::atomic::Ordering::Relaxed) {
            break;
        }

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_disks();

        let cpu = system.global_cpu_info().cpu_usage() as f64;
        let total_mem = system.total_memory() as f64;
        let used_mem = system.used_memory() as f64;
        let mem_pct = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let total_disk: u64 = system.disks().iter().map(|d| d.total_space()).sum();
        let used_disk: u64 = system
            .disks()
            .iter()
            .map(|d| d.total_space().saturating_sub(d.available_space()))
            .sum();

        let disk_pct = if total_disk > 0 {
            (used_disk as f64 / total_disk as f64) * 100.0
        } else {
            0.0
        };

        DaemonState::set_f64(&state.last_cpu_percent, cpu);
        DaemonState::set_f64(&state.last_memory_percent, mem_pct);
        DaemonState::set_f64(&state.last_disk_percent, disk_pct);

        info!(
            cpu = cpu,
            memory_percent = mem_pct,
            disk_percent = disk_pct,
            "resource snapshot"
        );

        if cpu > config.cpu_threshold_percent as f64 {
            warn!(cpu = cpu, threshold = config.cpu_threshold_percent, "high CPU usage");
        }
        if mem_pct > config.memory_threshold_percent as f64 {
            warn!(memory = mem_pct, threshold = config.memory_threshold_percent, "high memory usage");
        }
        if disk_pct > config.disk_threshold_percent as f64 {
            warn!(disk = disk_pct, threshold = config.disk_threshold_percent, "high disk usage");
        }

        sleep(Duration::from_millis(config.interval_ms)).await;
    }
}
```

