## `src/control.rs`

```rust
use crate::state::DaemonState;
use std::{path::Path, sync::Arc};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
};
use tracing::{info, warn};

pub async fn control_server(socket_path: String, state: Arc<DaemonState>) -> anyhow::Result<()> {
    if Path::new(&socket_path).exists() {
        let _ = std::fs::remove_file(&socket_path);
    }

    let listener = UnixListener::bind(&socket_path)?;
    info!(%socket_path, "control socket listening");

    loop {
        let (stream, _) = listener.accept().await?;
        let st = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, st).await {
                warn!(error = %e, "control client error");
            }
        });
    }
}

async fn handle_client(stream: UnixStream, state: Arc<DaemonState>) -> anyhow::Result<()> {
    let (read_half, mut write_half) = stream.into_split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    write_half.write_all(b"resource_daemon ready\n").await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();

        match cmd {
            "status" => {
                let cpu = DaemonState::get_f64(&state.last_cpu_percent);
                let mem = DaemonState::get_f64(&state.last_memory_percent);
                let disk = DaemonState::get_f64(&state.last_disk_percent);

                let resp = format!(
                    "cpu={:.2} memory={:.2} disk={:.2}\n",
                    cpu, mem, disk
                );
                write_half.write_all(resp.as_bytes()).await?;
            }
            "stop" => {
                state.running.store(false, std::sync::atomic::Ordering::Relaxed);
                write_half.write_all(b"stopping\n").await?;
                break;
            }
            _ => {
                write_half.write_all(b"unknown command\n").await?;
            }
        }
    }

    Ok(())
}
```

