use crate::{config::Config, control::control_server, monitor::monitor_loop, state::DaemonState};
use std::sync::Arc;
use tracing::info;

pub async fn run(config: Config) -> anyhow::Result<()> {
    let state = Arc::new(DaemonState::new());

    info!("starting daemon");

    let monitor_task = tokio::spawn(monitor_loop(config.clone(), state.clone()));
    let control_task = tokio::spawn(control_server(config.socket_path.clone(), state.clone()));

    let _ = tokio::join!(monitor_task, control_task);

    info!("daemon stopped");
    Ok(())
}
