type ResourceMetrics struct {
	Timestamp    time.Time
	CPUPercent   float64
	MemUsedBytes float64
	MemTotalBytes float64
	DiskUsedPct  float64
	Load1        float64
	Load5        float64
	Load15       float64
}

type MetricsStore struct {
	mu   sync.RWMutex
	data ResourceMetrics
}

func NewMetricsStore() *MetricsStore {
	return &MetricsStore{
		data: ResourceMetrics{
			Timestamp: time.Now(),
		},
	}
}

func (m *MetricsStore) Update(data ResourceMetrics) {
	m.mu.Lock()
	m.data = data
	m.mu.Unlock()
}

func (m *MetricsStore) Snapshot() ResourceMetrics {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.data
}

