# `monitor.go`

This uses `/proc` and standard library hooks for a lightweight initial Linux-focused implementation.

```go
package main

import (
	"bufio"
	"errors"
	"os"
	"runtime"
	"strconv"
	"strings"
	"time"
)

type Monitor struct {
	prevIdle  uint64
	prevTotal uint64
	hasPrev   bool
}

func NewMonitor() *Monitor {
	return &Monitor{}
}

func (m *Monitor) Sample() (ResourceMetrics, error) {
	var rm ResourceMetrics
	rm.Timestamp = time.Now()

	cpu, err := m.cpuPercent()
	if err != nil {
		return rm, err
	}
	rm.CPUPercent = cpu

	memUsed, memTotal, err := readMemInfo()
	if err != nil {
		return rm, err
	}
	rm.MemUsedBytes = memUsed
	rm.MemTotalBytes = memTotal

	diskPct, err := readDiskUsage("/")
	if err != nil {
		return rm, err
	}
	rm.DiskUsedPct = diskPct

	l1, l5, l15, err := readLoadAvg()
	if err != nil {
		// Load avg may not exist on all platforms; fail soft.
		if !errors.Is(err, os.ErrNotExist) && runtime.GOOS != "windows" {
			return rm, err
		}
	}
	rm.Load1 = l1
	rm.Load5 = l5
	rm.Load15 = l15

	return rm, nil
}

func (m *Monitor) cpuPercent() (float64, error) {
	f, err := os.Open("/proc/stat")
	if err != nil {
		return 0, err
	}
	defer f.Close()

	sc := bufio.NewScanner(f)
	if !sc.Scan() {
		return 0, sc.Err()
	}

	fields := strings.Fields(sc.Text())
	if len(fields) < 5 || fields[0] != "cpu" {
		return 0, errors.New("invalid /proc/stat format")
	}

	var idle, total uint64
	for i := 1; i < len(fields); i++ {
		v, err := strconv.ParseUint(fields[i], 10, 64)
		if err != nil {
			return 0, err
		}
		total += v
		if i == 4 {
			idle = v
		}
	}

	if !m.hasPrev {
		m.prevIdle = idle
		m.prevTotal = total
		m.hasPrev = true
		return 0, nil
	}

	deltaIdle := idle - m.prevIdle
	deltaTotal := total - m.prevTotal
	m.prevIdle = idle
	m.prevTotal = total

	if deltaTotal == 0 {
		return 0, nil
	}

	busy := float64(deltaTotal-deltaIdle) / float64(deltaTotal) * 100.0
	return busy, nil
}

func readMemInfo() (usedBytes float64, totalBytes float64, err error) {
	f, err := os.Open("/proc/meminfo")
	if err != nil {
		return 0, 0, err
	}
	defer f.Close()

	var memTotal, memAvailable uint64
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if strings.HasPrefix(line, "MemTotal:") {
			memTotal = parseMeminfoKB(line)
		} else if strings.HasPrefix(line, "MemAvailable:") {
			memAvailable = parseMeminfoKB(line)
		}
	}
	if err := sc.Err(); err != nil {
		return 0, 0, err
	}
	if memTotal == 0 {
		return 0, 0, errors.New("MemTotal not found")
	}
	used := memTotal - memAvailable
	return float64(used * 1024), float64(memTotal * 1024), nil
}

func parseMeminfoKB(line string) uint64 {
	fields := strings.Fields(line)
	if len(fields) < 2 {
		return 0
	}
	v, _ := strconv.ParseUint(fields[1], 10, 64)
	return v
}

func readDiskUsage(path string) (float64, error) {
	var statfs syscallStatfs
	if err := statfsCall(path, &statfs); err != nil {
		return 0, err
	}
	total := statfs.Blocks * uint64(statfs.Bsize)
	free := statfs.Bavail * uint64(statfs.Bsize)
	if total == 0 {
		return 0, errors.New("disk total is zero")
	}
	usedPct := 100.0 * float64(total-free) / float64(total)
	return usedPct, nil
}

func readLoadAvg() (float64, float64, float64, error) {
	f, err := os.Open("/proc/loadavg")
	if err != nil {
		return 0, 0, 0, err
	}
	defer f.Close()

	var l1, l5, l15 float64
	_, err = fmtFscanf(f, "%f %f %f", &l1, &l5, &l15)
	return l1, l5, l15, err
}
