)

type Daemon struct {
	cfg     Config
	log     *slog.Logger
	mon     *Monitor
	metrics *MetricsStore
	mgr     *Manager

	server *http.Server
	wg     sync.WaitGroup
}

func NewDaemon(cfg Config, log *slog.Logger) *Daemon {
	d := &Daemon{
		cfg:     cfg,
		log:     log,
		mon:     NewMonitor(),
		metrics: NewMetricsStore(),
		mgr:     NewManager(log, cfg.ManageEnabled),
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", d.handleHealthz)
	mux.HandleFunc("/metrics", d.handleMetrics)

	d.server = &http.Server{
		Addr:    cfg.ListenAddr,
		Handler: mux,
	}

	return d
}

func (d *Daemon) Start(ctx context.Context) error {
	d.wg.Add(2)

	go func() {
		defer d.wg.Done()
		d.pollLoop(ctx)
	}()

	go func() {
		defer d.wg.Done()
		d.log.Info("http server starting", "addr", d.cfg.ListenAddr)
		if err := d.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			d.log.Error("http server failed", "err", err)
		}
	}()

	<-ctx.Done()
	return d.Stop(context.Background())
}

func (d *Daemon) Stop(ctx context.Context) error {
	d.log.Info("shutting down daemon")

	shutdownCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	if err := d.server.Shutdown(shutdownCtx); err != nil {
		d.log.Error("http shutdown failed", "err", err)
	}

	d.wg.Wait()
	return nil
}

func (d *Daemon) pollLoop(ctx context.Context) {
	t := time.NewTicker(d.cfg.PollInterval)
	defer t.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			snapshot, err := d.mon.Sample()
			if err != nil {
				d.log.Warn("sample failed", "err", err)
				continue
			}
			d.metrics.Update(snapshot)
			d.mgr.Reconcile(snapshot)
		}
	}
}

func (d *Daemon) handleHealthz(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

func (d *Daemon) handleMetrics(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/plain; version=0.0.4")
	_, _ = w.Write([]byte(d.metrics.PrometheusText()))
}
