use anyhow::{Context, Result};
use clap::Parser;
use config::Config;
use serde::Deserialize;
use signal_hook::consts::{SIGINT, SIGTERM};
use signal_hook::flag;
use std::path::PathBuf;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::Duration;
use sysinfo::{CpuRefreshKind, DiskExt, Disks, LoadAvg, MemoryRefreshKind, RefreshKind, System};
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Parser, Debug)]
#[command(name = "osd", about = "High-performance OS resource monitoring daemon")]
struct Args {
    /// Path to config file
    #[arg(short, long, default_value = "/etc/osd/config.toml")]
    config: PathBuf,

    /// Run in foreground (do not daemonize)
    #[arg(long, default_value_t = true)]
    foreground: bool,
}

#[derive(Debug, Deserialize, Clone)]
struct AppConfig {
    interval_ms: u64,
    cpu_warn_percent: f32,
    mem_warn_percent: f32,
    disk_warn_percent: f32,
    load_warn_1m: f64,
    log_level: String,
}

impl Default for AppConfig {
    fn default() -> Self {
        Self {
            interval_ms: 1000,
            cpu_warn_percent: 80.0,
            mem_warn_percent: 80.0,
            disk_warn_percent: 85.0,
            load_warn_1m: 4.0,
            log_level: "info".to_string(),
        }
    }
}

#[derive(Debug)]
struct ResourceSnapshot {
    cpu_usage: f32,
    memory_usage: f32,
    load_avg_1m: f64,
    disk_usage: f32,
}

struct Daemon {
    sys: System,
    config: AppConfig,
}

impl Daemon {
    fn new(config: AppConfig) -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::new().with_cpu_usage())
            .with_memory(MemoryRefreshKind::new().with_ram().with_swap());

        let sys = System::new_with_specifics(refresh);

        Self { sys, config }
    }

    fn collect(&mut self) -> ResourceSnapshot {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();
        self.sys.refresh_load();
        let disks = Disks::new_with_refreshed_list();

        let cpu_usage = self.sys.global_cpu_info().cpu_usage();
        let total_mem = self.sys.total_memory() as f32;
        let used_mem = self.sys.used_memory() as f32;
        let memory_usage = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let LoadAvg { one, .. } = System::load_average();

        let mut max_disk_usage = 0.0f32;
        for disk in disks.list() {
            let total = disk.total_space() as f32;
            let available = disk.available_space() as f32;
            if total > 0.0 {
                let used = ((total - available) / total) * 100.0;
                if used > max_disk_usage {
                    max_disk_usage = used;
                }
            }
        }

        ResourceSnapshot {
            cpu_usage,
            memory_usage,
            load_avg_1m: one,
            disk_usage: max_disk_usage,
        }
    }

    fn evaluate(&self, snap: &ResourceSnapshot) {
        if snap.cpu_usage >= self.config.cpu_warn_percent {
            warn!(
                cpu = snap.cpu_usage,
                threshold = self.config.cpu_warn_percent,
                "CPU usage above threshold"
            );
        }

        if snap.memory_usage >= self.config.mem_warn_percent {
            warn!(
                memory = snap.memory_usage,
                threshold = self.config.mem_warn_percent,
                "Memory usage above threshold"
            );
        }

        if snap.disk_usage >= self.config.disk_warn_percent {
            warn!(
                disk = snap.disk_usage,
                threshold = self.config.disk_warn_percent,
                "Disk usage above threshold"
            );
        }

        if snap.load_avg_1m >= self.config.load_warn_1m {
            warn!(
                load_1m = snap.load_avg_1m,
                threshold = self.config.load_warn_1m,
                "Load average above threshold"
            );
        }

        info!(
            cpu = snap.cpu_usage,
            memory = snap.memory_usage,
            load_1m = snap.load_avg_1m,
            disk = snap.disk_usage,
            "Resource snapshot"
        );
    }

    fn run(&mut self, shutdown: Arc<AtomicBool>) -> Result<()> {
        let interval = Duration::from_millis(self.config.interval_ms);

        info!("Daemon started");

        while !shutdown.load(Ordering::Relaxed) {
            let snap = self.collect();
            self.evaluate(&snap);

            let sleep_step = Duration::from_millis(100);
            let mut elapsed = Duration::ZERO;

            while elapsed < interval && !shutdown.load(Ordering::Relaxed) {
                thread::sleep(sleep_step);
                elapsed += sleep_step;
            }
        }

        info!("Daemon shutting down");
        Ok(())
    }
}

fn load_config(path: &PathBuf) -> Result<AppConfig> {
    let cfg = Config::builder()
        .add_source(config::File::from(path.as_path()).required(false))
        .build()
        .context("failed to build config")?;

    let loaded: AppConfig = cfg
        .try_deserialize()
        .unwrap_or_else(|_| AppConfig::default());

    Ok(loaded)
}

fn init_logging(level: &str) {
    let filter = EnvFilter::try_new(level).unwrap_or_else(|_| EnvFilter::new("info"));
    tracing_subscriber::fmt().with_env_filter(filter).init();
}

fn main() -> Result<()> {
    let args = Args::parse();
    let config = load_config(&args.config)?;

    init_logging(&config.log_level);

    let shutdown = Arc::new(AtomicBool::new(false));
    flag::register(SIGTERM, Arc::clone(&shutdown)).context("register SIGTERM")?;
    flag::register(SIGINT, Arc::clone(&shutdown)).context("register SIGINT")?;

    debug!(?args, ?config, "Starting daemon");

    let mut daemon = Daemon::new(config);
    daemon.run(shutdown)?;

    Ok(())
}
