```rust
use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, NetworkExt, ProcessExt, System, SystemExt};
use tokio::sync::RwLock;
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Debug, Clone, Deserialize)]
struct Config {
    #[serde(default = "default_interval_ms")]
    sample_interval_ms: u64,

    #[serde(default = "default_cpu_threshold")]
    cpu_usage_threshold: f32,

    #[serde(default = "default_mem_threshold")]
    memory_usage_threshold: f32,

    #[serde(default = "default_disk_threshold")]
    disk_usage_threshold: f32,

    #[serde(default)]
    process_watch: Vec<WatchedProcess>,

    #[serde(default)]
    actions: Actions,
}

#[derive(Debug, Clone, Deserialize)]
struct WatchedProcess {
    name: String,
    #[serde(default)]
    max_cpu: Option<f32>,
    #[serde(default)]
    max_memory_mb: Option<u64>,
}

#[derive(Debug, Clone, Deserialize, Default)]
struct Actions {
    #[serde(default)]
    log_only: bool,
}

fn default_interval_ms() -> u64 {
    1000
}
fn default_cpu_threshold() -> f32 {
    90.0
}
fn default_mem_threshold() -> f32 {
    90.0
}
fn default_disk_threshold() -> f32 {
    90.0
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: default_interval_ms(),
            cpu_usage_threshold: default_cpu_threshold(),
            memory_usage_threshold: default_mem_threshold(),
            disk_usage_threshold: default_disk_threshold(),
            process_watch: Vec::new(),
            actions: Actions::default(),
        }
    }
}

#[derive(Debug, Clone)]
struct Snapshot {
    taken_at: Instant,
    cpu_usage: f32,
    memory_usage: f32,
    disk_usage: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
}

struct Daemon {
    cfg: Config,
    system: System,
    last_snapshot: Arc<RwLock<Option<Snapshot>>>,
}

impl Daemon {
    fn new(cfg: Config) -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        Self {
            cfg,
            system,
            last_snapshot: Arc::new(RwLock::new(None)),
        }
    }

    async fn run(mut self) -> Result<()> {
        info!("daemon started");

        let mut interval =
            tokio::time::interval(Duration::from_millis(self.cfg.sample_interval_ms));
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);

        loop {
            tokio::select! {
                _ = interval.tick() => {
                    if let Err(err) = self.sample_and_act().await {
                        error!(error = %err, "sampling cycle failed");
                    }
                }
                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        info!("daemon stopped");
        Ok(())
    }

    async fn sample_and_act(&mut self) -> Result<()> {
        let now = Instant::now();

        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.system.refresh_networks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let total_swap = self.system.total_swap();
        let used_swap = self.system.used_swap();

        let memory_usage = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let disk_usage = self.compute_disk_usage();

        let snapshot = Snapshot {
            taken_at: now,
            cpu_usage,
            memory_usage,
            disk_usage,
            total_memory,
            used_memory,
            total_swap,
            used_swap,
        };

        {
            let mut guard = self.last_snapshot.write().await;
            *guard = Some(snapshot.clone());
        }

        info!(
            cpu = snapshot.cpu_usage,
            memory = snapshot.memory_usage,
            disk = snapshot.disk_usage,
            total_memory = snapshot.total_memory,
            used_memory = snapshot.used_memory,
            total_swap = snapshot.total_swap,
            used_swap = snapshot.used_swap,
            "resource snapshot"
        );

        self.check_thresholds(&snapshot).await?;
        self.check_processes().await?;

        Ok(())
    }

    fn compute_disk_usage(&self) -> f32 {
        let mut total = 0u64;
        let mut used = 0u64;

        for disk in self.system.disks() {
            let disk_total = disk.total_space();
            let disk_used = disk_total.saturating_sub(disk.available_space());
            total += disk_total;
            used += disk_used;
        }

        if total > 0 {
            (used as f32 / total as f32) * 100.0
        } else {
            0.0
        }
    }

    async fn check_thresholds(&self, snapshot: &Snapshot) -> Result<()> {
        if snapshot.cpu_usage >= self.cfg.cpu_usage_threshold {
            warn!(
                cpu = snapshot.cpu_usage,
                threshold = self.cfg.cpu_usage_threshold,
                "cpu threshold exceeded"
            );
            self.handle_policy("cpu").await?;
        }

        if snapshot.memory_usage >= self.cfg.memory_usage_threshold {
            warn!(
                memory = snapshot.memory_usage,
                threshold = self.cfg.memory_usage_threshold,
                "memory threshold exceeded"
            );
            self.handle_policy("memory").await?;
        }

        if snapshot.disk_usage >= self.cfg.disk_usage_threshold {
            warn!(
                disk = snapshot.disk_usage,
                threshold = self.cfg.disk_usage_threshold,
                "disk threshold exceeded"
            );
            self.handle_policy("disk").await?;
        }

        Ok(())
    }

    async fn check_processes(&self) -> Result<()> {
        let mut system = System::new_all();
        system.refresh_processes();

        for watched in &self.cfg.process_watch {
            for (_pid, process) in system.processes() {
                if process.name() == watched.name {
                    if let Some(max_cpu) = watched.max_cpu {
                        if process.cpu_usage() > max_cpu {
                            warn!(
                                process = %watched.name,
                                cpu = process.cpu_usage(),
                                threshold = max_cpu,
                                "watched process cpu usage exceeded"
                            );
                        }
                    }

                    if let Some(max_memory_mb) = watched.max_memory_mb {
                        let memory_mb = process.memory() / 1024;
                        if memory_mb > max_memory_mb {
                            warn!(
                                process = %watched.name,
                                memory_mb = memory_mb,
                                threshold_mb = max_memory_mb,
                                "watched process memory usage exceeded"
                            );
                        }
                    }
                }
            }
        }

        Ok(())
    }

    async fn handle_policy(&self, resource: &str) -> Result<()> {
        if self.cfg.actions.log_only {
            info!(resource = resource, "policy action: log_only");
            return Ok(());
        }

        // Initial placeholder for future actions:
        // - notify external systems
        // - throttle workloads
        // - terminate offending processes
        // - trigger autoscaling hooks
        info!(resource = resource, "policy action: no-op");
        Ok(())
    }
}

fn load_config(path: Option<PathBuf>) -> Result<Config> {
    if let Some(path) = path {
        let raw = fs::read_to_string(&path)
            .with_context(|| format!("failed to read config file: {}", path.display()))?;
        let cfg: Config = toml::from_str(&raw)
            .with_context(|| format!("failed to parse config file: {}", path.display()))?;
        Ok(cfg)
    } else {
        Ok(Config::default())
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .compact()
        .init();

    let config_path = std::env::args().nth(1).map(PathBuf::from);
    let cfg = load_config(config_path)?;

    debug!(?cfg, "loaded config");

    let daemon = Daemon::new(cfg);
    daemon.run().await
}
