use anyhow::{anyhow, Result};
use serde::{Deserialize, Serialize};
use std::env;
use std::time::Duration;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Config {
    pub poll_interval: Duration,
    pub cpu_warn_pct: f32,
    pub mem_warn_pct: f32,
    pub disk_warn_pct: f32,
    pub exit_on_critical: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval: Duration::from_secs(2),
            cpu_warn_pct: 85.0,
            mem_warn_pct: 90.0,
            disk_warn_pct: 90.0,
            exit_on_critical: false,
        }
    }
}

impl Config {
    pub fn from_env() -> Result<Self> {
        let mut cfg = Self::default();

        if let Ok(v) = env::var("SYSD_POLL_INTERVAL_SECS") {
            let secs: u64 = v.parse().map_err(|_| anyhow!("invalid SYSD_POLL_INTERVAL_SECS"))?;
            cfg.poll_interval = Duration::from_secs(secs);
        }

        if let Ok(v) = env::var("SYSD_CPU_WARN_PCT") {
            cfg.cpu_warn_pct = v.parse().map_err(|_| anyhow!("invalid SYSD_CPU_WARN_PCT"))?;
        }

        if let Ok(v) = env::var("SYSD_MEM_WARN_PCT") {
            cfg.mem_warn_pct = v.parse().map_err(|_| anyhow!("invalid SYSD_MEM_WARN_PCT"))?;
        }

        if let Ok(v) = env::var("SYSD_DISK_WARN_PCT") {
            cfg.disk_warn_pct = v.parse().map_err(|_| anyhow!("invalid SYSD_DISK_WARN_PCT"))?;
        }

        if let Ok(v) = env::var("SYSD_EXIT_ON_CRITICAL") {
            cfg.exit_on_critical = matches!(v.as_str(), "1" | "true" | "TRUE" | "yes" | "YES");
        }

        if cfg.poll_interval.as_secs() == 0 {
            return Err(anyhow!("poll interval must be >= 1 second"));
        }

        Ok(cfg)
    }
}
