## `src/system.rs`

```rust
use anyhow::Result;
use procfs::process::all_processes;
use sysinfo::{Disks, System};

#[derive(Debug, Clone)]
pub struct SystemSnapshot {
    pub cpu_usage_pct: f32,
    pub memory_usage_pct: f32,
    pub load_avg_1m: f64,
    pub disk_usage_pct: f32,
    pub process_count: usize,
}

pub struct SystemCollector {
    sys: System,
    disks: Disks,
}

impl SystemCollector {
    pub fn new() -> Self {
        let mut sys = System::new_all();
        sys.refresh_all();
        let disks = Disks::new_with_refreshed_list();
        Self { sys, disks }
    }

    pub fn collect(&mut self) -> Result<SystemSnapshot> {
        self.sys.refresh_cpu_usage();
        self.sys.refresh_memory();
        self.disks.refresh(true);

        let cpu_usage_pct = self.sys.global_cpu_usage();

        let total_mem = self.sys.total_memory() as f32;
        let used_mem = self.sys.used_memory() as f32;
        let memory_usage_pct = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let load_avg_1m = procfs::LoadAverage::new()?.one;

        let disk_usage_pct = Self::compute_disk_usage_pct(&self.disks);

        let process_count = all_processes()?.count();

        Ok(SystemSnapshot {
            cpu_usage_pct,
            memory_usage_pct,
            load_avg_1m,
            disk_usage_pct,
            process_count,
        })
    }

    fn compute_disk_usage_pct(disks: &Disks) -> f32 {
        let mut total_space = 0u64;
        let mut used_space = 0u64;

        for disk in disks.list() {
            let total = disk.total_space();
            let avail = disk.available_space();
            total_space += total;
            used_space += total.saturating_sub(avail);
        }

        if total_space == 0 {
            0.0
        } else {
            (used_space as f32 / total_space as f32) * 100.0
        }
    }
}
```

