## `src/policy.rs`

```rust
use crate::config::Config;
use crate::system::SystemSnapshot;
use tracing::{warn, info};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Severity {
    Info,
    Warning,
    Critical,
}

#[derive(Debug)]
pub struct PolicyResult {
    pub severity: Severity,
    pub messages: Vec<String>,
}

pub struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, snapshot: &SystemSnapshot) -> PolicyResult {
        let mut messages = Vec::new();
        let mut severity = Severity::Info;

        if snapshot.cpu_usage_pct >= self.config.cpu_warn_pct {
            severity = Severity::Warning;
            messages.push(format!(
                "high CPU usage: {:.1}% >= {:.1}%",
                snapshot.cpu_usage_pct, self.config.cpu_warn_pct
            ));
        }

        if snapshot.memory_usage_pct >= self.config.mem_warn_pct {
            severity = Severity::Warning;
            messages.push(format!(
                "high memory usage: {:.1}% >= {:.1}%",
                snapshot.memory_usage_pct, self.config.mem_warn_pct
            ));
        }

        if snapshot.disk_usage_pct >= self.config.disk_warn_pct {
            severity = Severity::Warning;
            messages.push(format!(
                "high disk usage: {:.1}% >= {:.1}%",
                snapshot.disk_usage_pct, self.config.disk_warn_pct
            ));
        }

        if snapshot.load_avg_1m > snapshot.process_count as f64 {
            severity = Severity::Critical;
            messages.push(format!(
                "load average {:.2} exceeds process count {}",
                snapshot.load_avg_1m, snapshot.process_count
            ));
        }

        PolicyResult { severity, messages }
    }

    pub fn act(&self, result: &PolicyResult) -> bool {
        match result.severity {
            Severity::Info => {
                info!("system healthy");
                true
            }
            Severity::Warning => {
                for msg in &result.messages {
                    warn!(%msg, "policy warning");
                }
                true
            }
            Severity::Critical => {
                for msg in &result.messages {
                    warn!(%msg, "policy critical");
                }
                !self.config.exit_on_critical
            }
        }
    }
}
```

