use crate::system::{SystemCollector, SystemSnapshot};
use anyhow::Result;
use tokio::sync::mpsc;
use tokio::time::{interval, MissedTickBehavior};
use tracing::debug;

pub struct Monitor {
    collector: SystemCollector,
}

impl Monitor {
    pub fn new() -> Self {
        Self {
            collector: SystemCollector::new(),
        }
    }

    pub async fn run(
        mut self,
        poll_interval: std::time::Duration,
        tx: mpsc::Sender<SystemSnapshot>,
    ) -> Result<()> {
        let mut ticker = interval(poll_interval);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Delay);

        loop {
            ticker.tick().await;

            let snapshot = self.collector.collect()?;
            debug!(?snapshot, "collected snapshot");

            if tx.send(snapshot).await.is_err() {
                break;
            }
        }

        Ok(())
    }
}
