## `src/daemon.rs`

```rust
use crate::config::Config;
use crate::monitor::Monitor;
use crate::policy::{PolicyEngine, Severity};
use crate::system::SystemSnapshot;
use anyhow::Result;
use tokio::sync::mpsc;
use tokio::signal;
use tracing::{info, error};

pub struct Daemon {
    config: Config,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub async fn run(self) -> Result<()> {
        let (tx, mut rx) = mpsc::channel::<SystemSnapshot>(32);
        let monitor = Monitor::new();
        let policy = PolicyEngine::new(self.config.clone());

        let monitor_handle = tokio::spawn(async move {
            if let Err(e) = monitor.run(self.config.poll_interval, tx).await {
                error!(error = %e, "monitor task failed");
            }
        });

        info!("daemon started");

        loop {
            tokio::select! {
                maybe_snapshot = rx.recv() => {
                    match maybe_snapshot {
                        Some(snapshot) => {
                            let result = policy.evaluate(&snapshot);
                            let keep_running = policy.act(&result);

                            info!(
                                cpu = format!("{:.1}", snapshot.cpu_usage_pct),
                                mem = format!("{:.1}", snapshot.memory_usage_pct),
                                disk = format!("{:.1}", snapshot.disk_usage_pct),
                                load = format!("{:.2}", snapshot.load_avg_1m),
                                procs = snapshot.process_count,
                                severity = ?result.severity,
                                "system metrics"
                            );

                            if result.severity == Severity::Critical && !keep_running {
                                info!("exiting due to critical condition");
                                break;
                            }
                        }
                        None => break,
                    }
                }

                _ = signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        monitor_handle.abort();
        let _ = monitor_handle.await;

        info!("daemon stopped");
        Ok(())
    }
}
```

