use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::time::Duration;
use sysinfo::{CpuExt, ProcessExt, System, SystemExt};
use tokio::sync::mpsc;
use tokio::time::interval;
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    sample_interval: Duration,
    cpu_high_threshold: f32,
    memory_high_threshold: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval: Duration::from_secs(2),
            cpu_high_threshold: 85.0,
            memory_high_threshold: 90.0,
        }
    }
}

#[derive(Debug, Clone)]
struct ResourceSnapshot {
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    cpu_usage: f32,
    load_avg_1m: f64,
    load_avg_5m: f64,
    load_avg_15m: f64,
    top_processes: Vec<(String, f32, u64)>, // (name, cpu, memory)
}

#[derive(Debug)]
enum Action {
    Warn(String),
    MitigateCpu,
    MitigateMemory,
    Shutdown,
}

struct Daemon {
    config: Config,
    system: System,
    tx: mpsc::Sender<Action>,
}

impl Daemon {
    fn new(config: Config, tx: mpsc::Sender<Action>) -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { config, system, tx }
    }

    async fn run(mut self) -> Result<()> {
        let mut ticker = interval(self.config.sample_interval);

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snapshot = self.sample();
                    self.evaluate(snapshot).await?;
                }
                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    let _ = self.tx.send(Action::Shutdown).await;
                    break;
                }
            }
        }

        Ok(())
    }

    fn sample(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let load = System::load_average();

        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let total_swap = self.system.total_swap();
        let used_swap = self.system.used_swap();

        let mut processes: Vec<_> = self
            .system
            .processes()
            .values()
            .map(|p| {
                (
                    p.name().to_string(),
                    p.cpu_usage(),
                    p.memory(),
                )
            })
            .collect();

        processes.sort_by(|a, b| {
            b.1.partial_cmp(&a.1)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        let top_processes = processes.into_iter().take(5).collect();

        ResourceSnapshot {
            total_memory,
            used_memory,
            total_swap,
            used_swap,
            cpu_usage,
            load_avg_1m: load.one,
            load_avg_5m: load.five,
            load_avg_15m: load.fifteen,
            top_processes,
        }
    }

    async fn evaluate(&self, snapshot: ResourceSnapshot) -> Result<()> {
        info!(
            cpu = snapshot.cpu_usage,
            mem_used = snapshot.used_memory,
            mem_total = snapshot.total_memory,
            swap_used = snapshot.used_swap,
            swap_total = snapshot.total_swap,
            load1 = snapshot.load_avg_1m,
            load5 = snapshot.load_avg_5m,
            load15 = snapshot.load_avg_15m,
            "resource snapshot"
        );

        for (name, cpu, mem) in &snapshot.top_processes {
            debug!(process = %name, cpu = *cpu, mem = *mem, "top process");
        }

        let mem_usage_pct = if snapshot.total_memory > 0 {
            (snapshot.used_memory as f64 / snapshot.total_memory as f64) * 100.0
        } else {
            0.0
        };

        if snapshot.cpu_usage > self.config.cpu_high_threshold {
            warn!("CPU threshold exceeded: {:.2}%", snapshot.cpu_usage);
            let _ = self.tx.send(Action::MitigateCpu).await;
        }

        if mem_usage_pct as f32 > self.config.memory_high_threshold {
            warn!("Memory threshold exceeded: {:.2}%", mem_usage_pct);
            let _ = self.tx.send(Action::MitigateMemory).await;
        }

        Ok(())
    }
}

async fn action_worker(mut rx: mpsc::Receiver<Action>) {
    while let Some(action) = rx.recv().await {
        match action {
            Action::Warn(msg) => {
                warn!("{}", msg);
            }
            Action::MitigateCpu => {
                // Placeholder mitigation strategy:
                // - identify top CPU consumers
                // - reduce priority / throttle / notify policy engine
                warn!("CPU mitigation requested");
            }
            Action::MitigateMemory => {
                // Placeholder mitigation strategy:
                // - identify memory consumers
                // - reclaim caches / cgroup controls / notify policy engine
                warn!("Memory mitigation requested");
            }
            Action::Shutdown => {
                info!("action worker shutting down");
                break;
            }
        }
    }
}

fn init_logging() {
    use tracing_subscriber::{fmt, EnvFilter};

    let filter = EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| EnvFilter::new("info"));

    fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    init_logging();

    let config = Config::default();
    info!("starting sysd");

    let (tx, rx) = mpsc::channel(64);

    let daemon = Daemon::new(config, tx.clone());

    let worker = tokio::spawn(action_worker(rx));
    let daemon_task = tokio::spawn(async move { daemon.run().await });

    tokio::select! {
        res = daemon_task => {
            match res {
                Ok(Ok(())) => info!("daemon exited cleanly"),
                Ok(Err(e)) => error!(error = ?e, "daemon failed"),
                Err(e) => error!(error = ?e, "daemon task panicked"),
            }
        }
        _ = tokio::signal::ctrl_c() => {
            info!("main received shutdown signal");
            let _ = tx.send(Action::Shutdown).await;
        }
    }

    let _ = worker.await;
    Ok(())
}
