## `src/monitor.rs`

```rust
use crate::types::ResourceSnapshot;
use sysinfo::{Disks, ProcessRefreshKind, ProcessesToUpdate, RefreshKind, System};
use std::time::SystemTime;

pub struct Monitor {
    system: System,
}

impl Monitor {
    pub fn new() -> Self {
        let system = System::new_with_specifics(
            RefreshKind::new()
                .with_cpu()
                .with_memory()
                .with_processes(ProcessRefreshKind::everything()),
        );
        Self { system }
    }

    pub fn snapshot(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes(ProcessesToUpdate::All, true);

        let cpu_usage = self.system.global_cpu_usage();
        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let total_swap = self.system.total_swap();
        let used_swap = self.system.used_swap();
        let process_count = self.system.processes().len();

        let disks = Disks::new_with_refreshed_list();
        let (disk_used, disk_total) = disks.list().iter().fold((0u64, 0u64), |acc, disk| {
            let total = acc.1 + disk.total_space();
            let used = acc.0 + (disk.total_space().saturating_sub(disk.available_space()));
            (used, total)
        });

        ResourceSnapshot {
            timestamp: SystemTime::now(),
            cpu_usage_percent: cpu_usage,
            memory_used: used_memory,
            memory_total: total_memory,
            swap_used: used_swap,
            swap_total: total_swap,
            disk_used,
            disk_total,
            process_count,
        }
    }
}
```

