use crate::types::ResourceSnapshot;
use anyhow::Result;
use tracing::{info, warn};

pub trait Action: Send + Sync {
    fn name(&self) -> &'static str;
    fn execute(&self, snapshot: &ResourceSnapshot) -> Result<()>;
}

pub struct LogAction;

impl Action for LogAction {
    fn name(&self) -> &'static str {
        "log"
    }

    fn execute(&self, snapshot: &ResourceSnapshot) -> Result<()> {
        info!(
            cpu = snapshot.cpu_usage_percent,
            memory = snapshot.memory_usage_percent(),
            swap = snapshot.swap_usage_percent(),
            disk = snapshot.disk_usage_percent(),
            processes = snapshot.process_count,
            "resource threshold exceeded"
        );
        Ok(())
    }
}

pub struct WarnAction;

impl Action for WarnAction {
    fn name(&self) -> &'static str {
        "warn"
    }

    fn execute(&self, snapshot: &ResourceSnapshot) -> Result<()> {
        warn!(
            "High resource usage detected: cpu={}%, memory={}%, swap={}%, disk={}%",
            snapshot.cpu_usage_percent,
            snapshot.memory_usage_percent(),
            snapshot.swap_usage_percent(),
            snapshot.disk_usage_percent()
        );
        Ok(())
    }
