## `src/manager.rs`

```rust
use crate::{
    actions::Action,
    config::Config,
    monitor::Monitor,
    types::ResourceSnapshot,
};
use anyhow::Result;
use std::time::Duration;
use tokio::time::interval;
use tracing::{debug, info};

pub struct Manager {
    config: Config,
    monitor: Monitor,
    actions: Vec<Box<dyn Action>>,
}

impl Manager {
    pub fn new(config: Config, monitor: Monitor) -> Self {
        Self {
            config,
            monitor,
            actions: Vec::new(),
        }
    }

    pub fn add_action<A: Action + 'static>(&mut self, action: A) {
        self.actions.push(Box::new(action));
    }

    fn should_trigger(&self, snapshot: &ResourceSnapshot) -> bool {
        snapshot.cpu_usage_percent >= self.config.cpu_threshold
            || snapshot.memory_usage_percent() >= self.config.memory_threshold
            || snapshot.swap_usage_percent() >= self.config.swap_threshold
            || snapshot.disk_usage_percent() >= self.config.disk_threshold
            || snapshot.process_count > self.config.max_process_count
    }

    pub async fn run(mut self) -> Result<()> {
        let mut ticker = interval(Duration::from_secs(self.config.interval_seconds));
        info!("daemon started");

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snapshot = self.monitor.snapshot();
                    debug!(
                        cpu = snapshot.cpu_usage_percent,
                        memory = snapshot.memory_usage_percent(),
                        swap = snapshot.swap_usage_percent(),
                        disk = snapshot.disk_usage_percent(),
                        processes = snapshot.process_count,
                        "snapshot collected"
                    );

                    if self.should_trigger(&snapshot) {
                        for action in &self.actions {
                            if let Err(err) = action.execute(&snapshot) {
                                tracing::error!(action = action.name(), error = %err, "action failed");
                            }
                        }
                    }
                }

                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        info!("daemon stopped");
        Ok(())
    }
}
