```rust
use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::time::Duration;
use sysinfo::{Disks, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{error, info, warn};

#[derive(Debug, Clone)]
struct Config {
    poll_interval: Duration,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    disk_warn_threshold: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval: Duration::from_secs(5),
            cpu_warn_threshold: 85.0,
            mem_warn_threshold: 90.0,
            disk_warn_threshold: 90.0,
        }
    }
}

#[derive(Debug, Serialize, Deserialize)]
struct ResourceSnapshot {
    cpu_usage_avg: f32,
    total_memory_mb: u64,
    used_memory_mb: u64,
    memory_usage_pct: f32,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disk_usage_pct: f32,
}

struct ResourceMonitor {
    system: System,
    disks: Disks,
}

impl ResourceMonitor {
    fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        let disks = Disks::new_with_refreshed_list();
        Self { system, disks }
    }

    fn snapshot(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.disks.refresh_list();
        self.disks.refresh();

        let cpu_usage_avg = self.system.global_cpu_usage();
        let total_memory_mb = self.system.total_memory() / 1024;
        let used_memory_mb = self.system.used_memory() / 1024;
        let memory_usage_pct = if total_memory_mb > 0 {
            (used_memory_mb as f32 / total_memory_mb as f32) * 100.0
        } else {
            0.0
        };

        let load = System::load_average();

        let disk_usage_pct = self
            .disks
            .iter()
            .map(|d| {
                let total = d.total_space();
                let avail = d.available_space();
                if total > 0 {
                    ((total - avail) as f32 / total as f32) * 100.0
                } else {
                    0.0
                }
            })
            .fold(0.0_f32, f32::max);

        ResourceSnapshot {
            cpu_usage_avg,
            total_memory_mb,
            used_memory_mb,
            memory_usage_pct,
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            disk_usage_pct,
        }
    }
}

#[derive(Debug)]
enum Action {
    LogWarning(String),
    Placeholder(String),
}

struct PolicyEngine {
    cfg: Config,
}

impl PolicyEngine {
    fn new(cfg: Config) -> Self {
        Self { cfg }
    }

    fn evaluate(&self, snapshot: &ResourceSnapshot) -> Vec<Action> {
        let mut actions = Vec::new();

        if snapshot.cpu_usage_avg >= self.cfg.cpu_warn_threshold {
            actions.push(Action::LogWarning(format!(
                "High CPU usage: {:.1}%",
                snapshot.cpu_usage_avg
            )));
        }

        if snapshot.memory_usage_pct >= self.cfg.mem_warn_threshold {
            actions.push(Action::LogWarning(format!(
                "High memory usage: {:.1}%",
                snapshot.memory_usage_pct
            )));
        }

        if snapshot.disk_usage_pct >= self.cfg.disk_warn_threshold {
            actions.push(Action::LogWarning(format!(
                "High disk usage: {:.1}%",
                snapshot.disk_usage_pct
            )));
        }

        if snapshot.load_avg_one > 1.0 {
            actions.push(Action::Placeholder(format!(
                "Load average is elevated: {:.2}",
                snapshot.load_avg_one
            )));
        }

        actions
    }
}

struct Daemon {
    monitor: ResourceMonitor,
    policy: PolicyEngine,
    cfg: Config,
}

impl Daemon {
    fn new(cfg: Config) -> Self {
        Self {
            monitor: ResourceMonitor::new(),
            policy: PolicyEngine::new(cfg.clone()),
            cfg,
        }
    }

    async fn run(&mut self) -> Result<()> {
        let mut ticker = interval(self.cfg.poll_interval);

        info!("daemon started");

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snapshot = self.monitor.snapshot();
                    self.handle_snapshot(&snapshot);
                }
                _ = signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        info!("daemon stopped");
        Ok(())
    }

    fn handle_snapshot(&self, snapshot: &ResourceSnapshot) {
        info!(
            cpu = snapshot.cpu_usage_avg,
            memory_pct = snapshot.memory_usage_pct,
            disk_pct = snapshot.disk_usage_pct,
            load1 = snapshot.load_avg_one,
            load5 = snapshot.load_avg_five,
            load15 = snapshot.load_avg_fifteen,
            "resource snapshot"
        );

        let actions = self.policy.evaluate(snapshot);
        for action in actions {
            match action {
                Action::LogWarning(msg) => warn!("{}", msg),
                Action::Placeholder(msg) => info!("policy action: {}", msg),
            }
        }
    }
}

fn init_logging() {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .with_target(false)
        .compact()
        .init();
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    let cfg = Config::default();
    let mut daemon = Daemon::new(cfg);

    if let Err(e) = daemon.run().await {
        error!(error = %e, "daemon failed");
        return Err(e);
    }

    Ok(())
}
```

