use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, NetworkExt, System, SystemExt};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    sync::{mpsc, RwLock},
    time,
};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    #[serde(default = "default_sample_interval_ms")]
    sample_interval_ms: u64,
    #[serde(default = "default_socket_path")]
    socket_path: String,
    #[serde(default = "default_cpu_high_watermark")]
    cpu_high_watermark: f32,
    #[serde(default = "default_mem_high_watermark")]
    mem_high_watermark: f32,
}

fn default_sample_interval_ms() -> u64 {
    1000
}
fn default_socket_path() -> String {
    "/run/osd.sock".into()
}
fn default_cpu_high_watermark() -> f32 {
    85.0
}
fn default_mem_high_watermark() -> f32 {
    90.0
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: default_sample_interval_ms(),
            socket_path: default_socket_path(),
            cpu_high_watermark: default_cpu_high_watermark(),
            mem_high_watermark: default_mem_high_watermark(),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct Snapshot {
    timestamp_ms: u128,
    cpu_usage: f32,
    mem_usage: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    load_avg_1: f64,
    load_avg_5: f64,
    load_avg_15: f64,
    processes: usize,
}

#[derive(Debug, Clone, Serialize)]
struct Alert {
    kind: String,
    message: String,
    severity: String,
    timestamp_ms: u128,
}

#[derive(Debug)]
enum ControlCommand {
    Status,
    SetConfig(Config),
    Shutdown,
}

#[derive(Clone)]
struct SharedState {
    snapshot: Arc<RwLock<Option<Snapshot>>>,
    alerts: Arc<RwLock<Vec<Alert>>>,
    config: Arc<RwLock<Config>>,
}

impl SharedState {
    fn new(config: Config) -> Self {
        Self {
            snapshot: Arc::new(RwLock::new(None)),
            alerts: Arc::new(RwLock::new(Vec::new())),
            config: Arc::new(RwLock::new(config)),
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = load_config().unwrap_or_default();
    info!("starting daemon");

    let state = SharedState::new(config.clone());
    let (cmd_tx, mut cmd_rx) = mpsc::channel::<ControlCommand>(32);

    let socket_path = PathBuf::from(&config.socket_path);
    let _ = std::fs::remove_file(&socket_path);

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind unix socket at {}", socket_path.display()))?;

    let state_for_listener = state.clone();
    let cmd_tx_for_listener = cmd_tx.clone();
    tokio::spawn(async move {
        if let Err(e) = accept_loop(listener, state_for_listener, cmd_tx_for_listener).await {
            error!("socket listener failed: {e:#}");
        }
    });

    let state_for_sampler = state.clone();
    tokio::spawn(async move {
        if let Err(e) = sampler_loop(state_for_sampler).await {
            error!("sampler failed: {e:#}");
        }
    });

    info!("daemon ready at {}", socket_path.display());

    while let Some(cmd) = cmd_rx.recv().await {
        match cmd {
            ControlCommand::Status => {
                // no-op: handled in socket request path
            }
            ControlCommand::SetConfig(new_cfg) => {
                let mut cfg = state.config.write().await;
                *cfg = new_cfg;
                info!("config updated");
            }
            ControlCommand::Shutdown => {
                info!("shutdown requested");
                break;
            }
        }
    }

    let _ = std::fs::remove_file(&socket_path);
    Ok(())
}

async fn sampler_loop(state: SharedState) -> Result<()> {
    let mut sys = System::new_all();
    let mut interval = time::interval(Duration::from_millis(state.config.read().await.sample_interval_ms));

    loop {
        interval.tick().await;

        let cfg = state.config.read().await.clone();
        interval = time::interval(Duration::from_millis(cfg.sample_interval_ms));

        sys.refresh_all();

        let load = sysinfo::System::load_average();
        let cpu = sys.global_cpu_info().cpu_usage();
        let total_mem = sys.total_memory();
        let used_mem = sys.used_memory();
        let total_swap = sys.total_swap();
        let used_swap = sys.used_swap();
        let processes = sys.processes().len();

        let mem_usage = if total_mem > 0 {
            (used_mem as f32 / total_mem as f32) * 100.0
        } else {
            0.0
        };

        let snapshot = Snapshot {
            timestamp_ms: Instant::now().elapsed().as_millis(),
            cpu_usage: cpu,
            mem_usage,
            total_memory: total_mem,
            used_memory: used_mem,
            total_swap,
            used_swap,
            load_avg_1: load.one,
            load_avg_5: load.five,
            load_avg_15: load.fifteen,
            processes,
        };

        {
            let mut guard = state.snapshot.write().await;
            *guard = Some(snapshot.clone());
        }

        let mut alerts = Vec::new();
        if snapshot.cpu_usage > cfg.cpu_high_watermark {
            alerts.push(Alert {
                kind: "cpu".into(),
                severity: "warning".into(),
                message: format!(
                    "CPU usage high: {:.1}% > {:.1}%",
                    snapshot.cpu_usage, cfg.cpu_high_watermark
                ),
                timestamp_ms: snapshot.timestamp_ms,
            });
        }

        if snapshot.mem_usage > cfg.mem_high_watermark {
            alerts.push(Alert {
                kind: "memory".into(),
                severity: "warning".into(),
                message: format!(
                    "Memory usage high: {:.1}% > {:.1}%",
                    snapshot.mem_usage, cfg.mem_high_watermark
                ),
                timestamp_ms: snapshot.timestamp_ms,
            });
        }

        if !alerts.is_empty() {
            let mut a = state.alerts.write().await;
            a.extend(alerts);
            if a.len() > 1000 {
                let drain = a.len() - 1000;
                a.drain(0..drain);
            }
        }
    }
}

async fn accept_loop(
    listener: UnixListener,
    state: SharedState,
    cmd_tx: mpsc::Sender<ControlCommand>,
) -> Result<()> {
    loop {
        let (stream, _) = listener.accept().await?;
        let st = state.clone();
        let tx = cmd_tx.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, st, tx).await {
                warn!("client error: {e:#}");
            }
        });
    }
}

async fn handle_client(
    stream: UnixStream,
    state: SharedState,
    cmd_tx: mpsc::Sender<ControlCommand>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    reader.read_line(&mut line).await?;
    let line = line.trim();

    if line.is_empty() {
        return Ok(());
    }

    match parse_command(line) {
        Some(ControlCommand::Status) => {
            let snapshot = state.snapshot.read().await.clone();
            let alerts = state.alerts.read().await.clone();
            let cfg = state.config.read().await.clone();
            let response = serde_json::json!({
                "ok": true,
                "config": cfg,
                "snapshot": snapshot,
                "alerts": alerts,
            });
            writer.write_all(response.to_string().as_bytes()).await?;
            writer.write_all(b"\n").await?;
        }
        Some(ControlCommand::SetConfig(new_cfg)) => {
            state.config.write().await.clone_from(&new_cfg);
            let _ = cmd_tx.send(ControlCommand::SetConfig(new_cfg)).await;
            writer.write_all(b"{\"ok\":true,\"message\":\"config updated\"}\n").await?;
        }
        Some(ControlCommand::Shutdown) => {
            let _ = cmd_tx.send(ControlCommand::Shutdown).await;
            writer.write_all(b"{\"ok\":true,\"message\":\"shutdown requested\"}\n").await?;
        }
        None => {
            writer
                .write_all(b"{\"ok\":false,\"error\":\"unknown command\"}\n")
                .await?;
        }
    }

    Ok(())
}

fn parse_command(s: &str) -> Option<ControlCommand> {
    if s == "status" {
        return Some(ControlCommand::Status);
    }
    if s == "shutdown" {
        return Some(ControlCommand::Shutdown);
    }
    if let Some(rest) = s.strip_prefix("set-config ") {
        if let Ok(cfg) = serde_json::from_str::<Config>(rest) {
            return Some(ControlCommand::SetConfig(cfg));
        }
    }
    None
}

fn load_config() -> Result<Config> {
    let path = std::env::var("OSD_CONFIG").ok().map(PathBuf::from);
    if let Some(path) = path {
        let data = std::fs::read_to_string(&path)
            .with_context(|| format!("failed to read config: {}", path.display()))?;
        let cfg: Config = serde_json::from_str(&data)
            .with_context(|| format!("failed to parse config: {}", path.display()))?;
        Ok(cfg)
    } else {
        Ok(Config::default())
    }
}
