use serde::Deserialize;
use std::{fs, path::Path};

use crate::error::DaemonError;

#[derive(Debug, Clone, Deserialize)]
pub struct Config {
    pub sampling_interval_ms: u64,
    pub cpu_warn_threshold: f32,
    pub mem_warn_threshold: f32,
    pub disk_warn_threshold: f32,
    pub max_processes_to_report: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sampling_interval_ms: 1000,
            cpu_warn_threshold: 85.0,
            mem_warn_threshold: 80.0,
            disk_warn_threshold: 90.0,
            max_processes_to_report: 10,
        }
    }
}

impl Config {
    pub fn load_from_file<P: AsRef<Path>>(path: P) -> Result<Self, DaemonError> {
        let content = fs::read_to_string(path)?;
        let cfg: Config = toml::from_str(&content)?;
        Ok(cfg)
    }

    pub fn validate(&self) -> Result<(), DaemonError> {
        if self.sampling_interval_ms == 0 {
            return Err(DaemonError::Config(
                "sampling_interval_ms must be greater than 0".into(),
            ));
        }
        for (name, value) in [
            ("cpu_warn_threshold", self.cpu_warn_threshold),
            ("mem_warn_threshold", self.mem_warn_threshold),
            ("disk_warn_threshold", self.disk_warn_threshold),
        ] {
            if !(0.0..=100.0).contains(&value) {
                return Err(DaemonError::Config(format!(
                    "{name} must be in range 0..=100, got {value}"
                )));
            }
        }
        Ok(())
    }
}
