## `src/metrics.rs`

```rust
use sysinfo::{CpuExt, DiskExt, System, SystemExt};

#[derive(Debug, Clone)]
pub struct Metrics {
    pub cpu_usage: f32,
    pub memory_usage: f32,
    pub disk_usage: f32,
    pub top_processes: Vec<(i32, String, f32)>, // pid, name, cpu%
}

pub struct MetricsCollector {
    system: System,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn collect(&mut self, max_processes: usize) -> Metrics {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let memory_usage = if self.system.total_memory() == 0 {
            0.0
        } else {
            (self.system.used_memory() as f32 / self.system.total_memory() as f32) * 100.0
        };

        let disk_usage = self
            .system
            .disks()
            .iter()
            .map(|d| {
                let total = d.total_space();
                let available = d.available_space();
                if total == 0 {
                    0.0
                } else {
                    ((total - available) as f32 / total as f32) * 100.0
                }
            })
            .fold(0.0, f32::max);

        let mut processes: Vec<(i32, String, f32)> = self
            .system
            .processes()
            .iter()
            .map(|(pid, p)| {
                let pid_i32 = pid.as_u32() as i32;
                let name = p.name().to_string();
                let cpu = p.cpu_usage();
                (pid_i32, name, cpu)
            })
            .collect();

        processes.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
        processes.truncate(max_processes);

        Metrics {
            cpu_usage,
            memory_usage,
            disk_usage,
            top_processes: processes,
        }
    }
}
```

