use tracing::{info, warn};

use crate::{config::Config, metrics::Metrics};

pub struct RuleEngine;

impl RuleEngine {
    pub fn evaluate(config: &Config, m: &Metrics) {
        if m.cpu_usage >= config.cpu_warn_threshold {
            warn!(
                target: "sysmon",
                "High CPU usage detected: {:.2}%",
                m.cpu_usage
            );
        }

        if m.memory_usage >= config.mem_warn_threshold {
            warn!(
                target: "sysmon",
                "High memory usage detected: {:.2}%",
                m.memory_usage
            );
        }

        if m.disk_usage >= config.disk_warn_threshold {
            warn!(
                target: "sysmon",
                "High disk usage detected: {:.2}%",
                m.disk_usage
            );
        }

        for (pid, name, cpu) in &m.top_processes {
            info!(
                target: "sysmon",
                "process pid={} name={} cpu={:.2}%",
                pid,
                name,
                cpu
            );
        }
    }
}
