## `src/daemon.rs`

```rust
use std::time::Duration;

use tokio::time;
use tracing::{error, info};

use crate::{config::Config, metrics::MetricsCollector, rules::RuleEngine};

pub struct Daemon {
    config: Config,
    collector: MetricsCollector,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self {
            config,
            collector: MetricsCollector::new(),
        }
    }

    pub async fn run(mut self) {
        let mut interval = time::interval(Duration::from_millis(self.config.sampling_interval_ms));

        info!("daemon starting");

        loop {
            tokio::select! {
                _ = interval.tick() => {
                    let metrics = self.collector.collect(self.config.max_processes_to_report);
                    RuleEngine::evaluate(&self.config, &metrics);
                }
                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        info!("daemon stopped");
    }
}
