use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::{
    collections::VecDeque,
    path::Path,
    sync::{Arc, RwLock},
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use sysinfo::{CpuExt, System, SystemExt};
use tokio::{
    fs,
    io::{AsyncReadExt, AsyncWriteExt},
    net::{UnixListener, UnixStream},
    signal,
    sync::mpsc,
    time,
};
use tracing::{error, info, warn};

const SOCKET_PATH: &str = "/tmp/resource-daemon.sock";
const SAMPLE_INTERVAL_SECS: u64 = 2;
const HISTORY_CAPACITY: usize = 120;

#[derive(Debug, Clone, Serialize)]
struct ResourceSample {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    memory_total_kb: u64,
    memory_used_kb: u64,
    memory_usage_percent: f32,
    load_avg_1m: f64,
    load_avg_5m: f64,
    load_avg_15m: f64,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonStatus {
    pid: u32,
    uptime_secs: u64,
    latest: Option<ResourceSample>,
    history_len: usize,
    alerts_triggered: u64,
    managed_actions_taken: u64,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ControlCommand {
    GetStatus,
    SetThresholds {
        cpu_usage_percent: Option<f32>,
        memory_usage_percent: Option<f32>,
    },
    PauseActions,
    ResumeActions,
    Shutdown,
}

#[derive(Debug, Clone)]
struct Thresholds {
    cpu_usage_percent: f32,
    memory_usage_percent: f32,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_usage_percent: 85.0,
            memory_usage_percent: 90.0,
        }
    }
}

#[derive(Debug)]
struct DaemonState {
    start_time: SystemTime,
    latest: Option<ResourceSample>,
    history: VecDeque<ResourceSample>,
    alerts_triggered: u64,
    managed_actions_taken: u64,
    thresholds: Thresholds,
    actions_enabled: bool,
}

impl DaemonState {
    fn new() -> Self {
        Self {
            start_time: SystemTime::now(),
            latest: None,
            history: VecDeque::with_capacity(HISTORY_CAPACITY),
            alerts_triggered: 0,
            managed_actions_taken: 0,
            thresholds: Thresholds::default(),
            actions_enabled: true,
        }
    }

    fn status(&self) -> DaemonStatus {
        let uptime_secs = self
            .start_time
            .elapsed()
            .unwrap_or(Duration::ZERO)
            .as_secs();

        DaemonStatus {
            pid: std::process::id(),
            uptime_secs,
            latest: self.latest.clone(),
            history_len: self.history.len(),
            alerts_triggered: self.alerts_triggered,
            managed_actions_taken: self.managed_actions_taken,
        }
    }

    fn push_sample(&mut self, sample: ResourceSample) {
        self.latest = Some(sample.clone());
        if self.history.len() == HISTORY_CAPACITY {
            self.history.pop_front();
        }
        self.history.push_back(sample);
    }
}

fn now_unix_ms() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
}

fn capture_sample(sys: &mut System) -> ResourceSample {
    sys.refresh_cpu();
    sys.refresh_memory();

    let cpu = sys.global_cpu_info().cpu_usage();
    let total_memory = sys.total_memory();
    let used_memory = sys.used_memory();
    let memory_pct = if total_memory > 0 {
        (used_memory as f32 / total_memory as f32) * 100.0
    } else {
        0.0
    };

    let load = sysinfo::System::load_average();

    ResourceSample {
        timestamp_unix_ms: now_unix_ms(),
        cpu_usage_percent: cpu,
        memory_total_kb: total_memory,
        memory_used_kb: used_memory,
        memory_usage_percent: memory_pct,
        load_avg_1m: load.one,
        load_avg_5m: load.five,
        load_avg_15m: load.fifteen,
    }
}

async fn sample_loop(state: Arc<RwLock<DaemonState>>, shutdown_tx: mpsc::Sender<()>) {
    let mut sys = System::new_all();
    let mut tick = time::interval(Duration::from_secs(SAMPLE_INTERVAL_SECS));

    loop {
        tick.tick().await;

        let sample = capture_sample(&mut sys);

        let mut should_alert = false;
        let mut should_action = false;
        let mut thresholds = Thresholds::default();
        let actions_enabled;

        {
            let mut st = state.write().unwrap();
            thresholds = st.thresholds.clone();
            actions_enabled = st.actions_enabled;

            st.push_sample(sample.clone());

            if sample.cpu_usage_percent >= thresholds.cpu_usage_percent
                || sample.memory_usage_percent >= thresholds.memory_usage_percent
            {
                st.alerts_triggered += 1;
                should_alert = true;
                should_action = actions_enabled;
            }
        }

        if should_alert {
            warn!(
                cpu = sample.cpu_usage_percent,
                memory = sample.memory_usage_percent,
                "resource threshold exceeded"
            );
        }

        if should_action {
            // Initial placeholder for resource management actions.
            // In production, this could:
            // - lower background task priority
            // - trigger throttling
            // - notify orchestration
            // - restart unhealthy components
            let mut st = state.write().unwrap();
            st.managed_actions_taken += 1;
            info!(
                cpu = sample.cpu_usage_percent,
                memory = sample.memory_usage_percent,
                "managed action recorded"
            );
        }
    }
}

async fn handle_client(mut stream: UnixStream, state: Arc<RwLock<DaemonState>>) -> Result<()> {
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).await?;

    let cmd: ControlCommand = serde_json::from_slice(&buf)?;
    let response = match cmd {
        ControlCommand::GetStatus => {
            let st = state.read().unwrap();
            serde_json::to_vec_pretty(&st.status())?
        }
        ControlCommand::SetThresholds {
            cpu_usage_percent,
            memory_usage_percent,
        } => {
            {
                let mut st = state.write().unwrap();
                if let Some(cpu) = cpu_usage_percent {
                    st.thresholds.cpu_usage_percent = cpu.clamp(1.0, 100.0);
                }
                if let Some(mem) = memory_usage_percent {
                    st.thresholds.memory_usage_percent = mem.clamp(1.0, 100.0);
                }
            }
            serde_json::to_vec_pretty(&serde_json::json!({
                "ok": true
            }))?
        }
        ControlCommand::PauseActions => {
            {
                let mut st = state.write().unwrap();
                st.actions_enabled = false;
            }
            serde_json::to_vec_pretty(&serde_json::json!({ "ok": true }))?
        }
        ControlCommand::ResumeActions => {
            {
                let mut st = state.write().unwrap();
                st.actions_enabled = true;
            }
            serde_json::to_vec_pretty(&serde_json::json!({ "ok": true }))?
        }
        ControlCommand::Shutdown => {
            let _ = stream.shutdown().await;
            return Ok(());
        }
    };

    stream.write_all(&response).await?;
    stream.write_all(b"\n").await?;
    stream.shutdown().await?;
    Ok(())
}

async fn control_loop(state: Arc<RwLock<DaemonState>>) -> Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).await.ok();
    }

    let listener = UnixListener::bind(SOCKET_PATH)?;
    info!("control socket listening at {}", SOCKET_PATH);

    loop {
        let (stream, _) = listener.accept().await?;
        let st = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, st).await {
                error!("control client error: {e:#}");
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let state = Arc::new(RwLock::new(DaemonState::new()));
    let (shutdown_tx, mut shutdown_rx) = mpsc::channel::<()>(1);

    info!("resource daemon starting");

    let sample_state = state.clone();
    tokio::spawn(async move {
        sample_loop(sample_state, shutdown_tx).await;
    });

    let control_state = state.clone();
    tokio::spawn(async move {
        if let Err(e) = control_loop(control_state).await {
            error!("control loop failed: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown requested via signal");
        }
        _ = shutdown_rx.recv() => {
            info!("shutdown requested via control channel");
        }
    }

    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH).await.ok();
    }

    info!("resource daemon stopped");
    Ok(())
}
