use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    path::Path,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::Duration,
};
use sysinfo::{DiskExt, NetworkExt, ProcessExt, System, SystemExt};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::RwLock,
    task,
    time,
};
use tracing::{error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    cpu_usage_percent: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    total_swap_kib: u64,
    used_swap_kib: u64,
    disk_used_bytes: u64,
    disk_total_bytes: u64,
    process_count: usize,
    uptime_seconds: u64,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ControlCommand {
    GetStatus,
    Shutdown,
    SetLogLevel { level: String },
}

#[derive(Debug, Clone, Serialize)]
struct ControlResponse {
    ok: bool,
    message: String,
    snapshot: Option<ResourceSnapshot>,
}

struct DaemonState {
    system: RwLock<System>,
    last_snapshot: RwLock<Option<ResourceSnapshot>>,
    shutting_down: AtomicBool,
}

impl DaemonState {
    fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        Self {
            system: RwLock::new(system),
            last_snapshot: RwLock::new(None),
            shutting_down: AtomicBool::new(false),
        }
    }

    async fn collect_snapshot(&self) -> ResourceSnapshot {
        let mut system = self.system.write().await;

        // Refresh selectively for performance.
        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_disks_list();
        system.refresh_disks();
        system.refresh_processes();

        let cpu_usage_percent = system.global_cpu_info().cpu_usage();
        let total_memory_kib = system.total_memory();
        let used_memory_kib = system.used_memory();
        let total_swap_kib = system.total_swap();
        let used_swap_kib = system.used_swap();

        let mut disk_total_bytes = 0u64;
        let mut disk_used_bytes = 0u64;
        for disk in system.disks() {
            let total = disk.total_space();
            let available = disk.available_space();
            disk_total_bytes += total;
            disk_used_bytes += total.saturating_sub(available);
        }

        let process_count = system.processes().len();
        let uptime_seconds = System::uptime();

        ResourceSnapshot {
            cpu_usage_percent,
            total_memory_kib,
            used_memory_kib,
            total_swap_kib,
            used_swap_kib,
            disk_used_bytes,
            disk_total_bytes,
            process_count,
            uptime_seconds,
        }
    }

    async fn update_snapshot(&self) -> ResourceSnapshot {
        let snapshot = self.collect_snapshot().await;
        *self.last_snapshot.write().await = Some(snapshot.clone());
        snapshot
    }

    async fn get_last_snapshot(&self) -> Option<ResourceSnapshot> {
        self.last_snapshot.read().await.clone()
    }

    fn request_shutdown(&self) {
        self.shutting_down.store(true, Ordering::SeqCst);
    }

    fn is_shutting_down(&self) -> bool {
        self.shutting_down.load(Ordering::SeqCst)
    }
}

async fn handle_control_connection(mut stream: UnixStream, state: Arc<DaemonState>) -> Result<()> {
    let (read_half, mut write_half) = stream.split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: ControlCommand = serde_json::from_str(line.trim())
        .context("failed to parse control command")?;

    let resp = match cmd {
        ControlCommand::GetStatus => {
            let snapshot = state
                .get_last_snapshot()
                .await
                .or_else(|| None);

            ControlResponse {
                ok: true,
                message: "status ok".to_string(),
                snapshot,
            }
        }
        ControlCommand::Shutdown => {
            state.request_shutdown();
            ControlResponse {
                ok: true,
                message: "shutdown requested".to_string(),
                snapshot: state.get_last_snapshot().await,
            }
        }
        ControlCommand::SetLogLevel { level } => {
            // Placeholder: dynamic log reconfiguration can be added here.
            ControlResponse {
                ok: true,
                message: format!("log level request received: {}", level),
                snapshot: state.get_last_snapshot().await,
            }
        }
    };

    let json = serde_json::to_vec(&resp)?;
    write_half.write_all(&json).await?;
    write_half.write_all(b"\n").await?;
    Ok(())
}

async fn run_control_socket(state: Arc<DaemonState>, socket_path: &str) -> Result<()> {
    if Path::new(socket_path).exists() {
        std::fs::remove_file(socket_path)
            .with_context(|| format!("failed to remove existing socket {}", socket_path))?;
    }

    let listener = UnixListener::bind(socket_path)
        .with_context(|| format!("failed to bind unix socket {}", socket_path))?;

    info!("control socket listening on {}", socket_path);

    loop {
        if state.is_shutting_down() {
            break;
        }

        let accept_res = time::timeout(Duration::from_secs(1), listener.accept()).await;
        match accept_res {
            Ok(Ok((stream, _addr))) => {
                let state = state.clone();
                task::spawn(async move {
                    if let Err(e) = handle_control_connection(stream, state).await {
                        warn!("control connection error: {:#}", e);
                    }
                });
            }
            Ok(Err(e)) => {
                warn!("socket accept error: {}", e);
            }
            Err(_) => {
                // timeout tick
            }
        }
    }

    Ok(())
}

async fn metrics_loop(state: Arc<DaemonState>, interval: Duration) -> Result<()> {
    let mut ticker = time::interval(interval);
    ticker.tick().await;

    loop {
        if state.is_shutting_down() {
            break;
        }

        ticker.tick().await;

        let snapshot = state.update_snapshot().await;

        info!(
            cpu = snapshot.cpu_usage_percent,
            mem_used_kib = snapshot.used_memory_kib,
            mem_total_kib = snapshot.total_memory_kib,
            swap_used_kib = snapshot.used_swap_kib,
            swap_total_kib = snapshot.total_swap_kib,
            disk_used_bytes = snapshot.disk_used_bytes,
            disk_total_bytes = snapshot.disk_total_bytes,
            processes = snapshot.process_count,
            uptime_seconds = snapshot.uptime_seconds,
            "resource snapshot"
        );
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse()?))
        .init();

    let state = Arc::new(DaemonState::new());
    let socket_path = "/tmp/sysd.sock";
    let metrics_interval = Duration::from_secs(2);

    info!("starting sysd");

    let metrics_state = state.clone();
    let control_state = state.clone();

    let metrics_task = tokio::spawn(async move {
        if let Err(e) = metrics_loop(metrics_state, metrics_interval).await {
            error!("metrics loop error: {:#}", e);
        }
    });

    let control_task = tokio::spawn(async move {
        if let Err(e) = run_control_socket(control_state, socket_path).await {
            error!("control socket error: {:#}", e);
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received shutdown signal");
            state.request_shutdown();
        }
        _ = metrics_task => {}
        _ = control_task => {}
    }

    state.request_shutdown();

    let _ = metrics_task.await;
    let _ = control_task.await;

    if Path::new(socket_path).exists() {
        let _ = std::fs::remove_file(socket_path);
    }

    info!("sysd stopped");
    Ok(())
}
