use serde::{Deserialize, Serialize};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Disks, System, SystemExt};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Metrics {
    pub cpu_usage_pct: f32,
    pub mem_usage_pct: f32,
    pub total_memory_kb: u64,
    pub used_memory_kb: u64,
    pub disk_usage_pct: f32,
}

pub struct Sampler {
    system: System,
    disks: Disks,
}

impl Sampler {
    pub fn new() -> Self {
        let mut system = System::new();
        system.refresh_cpu_specifics(CpuRefreshKind::everything());
        system.refresh_memory();

        let mut disks = Disks::new_with_refreshed_list_specifics(DiskRefreshKind::everything());

        Self { system, disks }
    }

    pub fn sample(&mut self) -> Metrics {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.disks.refresh_list();
        self.disks.refresh();

        let cpu = self.system.global_cpu_info().cpu_usage();
        let total_mem = self.system.total_memory();
        let used_mem = self.system.used_memory();

        let mem_pct = if total_mem > 0 {
            (used_mem as f32 / total_mem as f32) * 100.0
        } else {
            0.0
        };

        let mut disk_total = 0u64;
        let mut disk_used = 0u64;

        for d in self.disks.list() {
            let total = d.total_space();
            let avail = d.available_space();
            disk_total += total;
            disk_used += total.saturating_sub(avail);
        }

        let disk_pct = if disk_total > 0 {
            (disk_used as f32 / disk_total as f32) * 100.0
        } else {
            0.0
        };

        Metrics {
            cpu_usage_pct: cpu,
            mem_usage_pct: mem_pct,
            total_memory_kb: total_mem,
            used_memory_kb: used_mem,
            disk_usage_pct: disk_pct,
        }
    }
}
