use serde::{Deserialize, Serialize};

use crate::{config::Config, metrics::Metrics};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Action {
    LogWarning(String),
    KillTopCpuProcess,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Decision {
    pub actions: Vec<Action>,
}

pub fn evaluate(cfg: &Config, m: &Metrics) -> Decision {
    let mut actions = Vec::new();

    if m.cpu_usage_pct >= cfg.cpu_warn_pct {
        actions.push(Action::LogWarning(format!(
            "High CPU usage: {:.2}%",
            m.cpu_usage_pct
        )));
        if cfg.action_enabled {
            actions.push(Action::KillTopCpuProcess);
        }
    }

    if m.mem_usage_pct >= cfg.mem_warn_pct {
        actions.push(Action::LogWarning(format!(
            "High memory usage: {:.2}%",
            m.mem_usage_pct
        )));
    }

    if m.disk_usage_pct >= cfg.disk_warn_pct {
        actions.push(Action::LogWarning(format!(
            "High disk usage: {:.2}%",
            m.disk_usage_pct
        )));
    }

    Decision { actions }
}
