use anyhow::Result;
use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use sysinfo::{ProcessExt, System, SystemExt};
use tracing::{info, warn};

use crate::policy::Action;

pub fn execute(action: Action) -> Result<()> {
    match action {
        Action::LogWarning(msg) => {
            warn!("{}", msg);
            Ok(())
        }
        Action::KillTopCpuProcess => kill_top_cpu_process(),
    }
}

fn kill_top_cpu_process() -> Result<()> {
    let mut system = System::new_all();
    system.refresh_all();

    let mut best_pid = None;
    let mut best_cpu = 0.0_f32;

    for (pid, proc_) in system.processes() {
        let cpu = proc_.cpu_usage();
        if cpu > best_cpu {
            best_cpu = cpu;
            best_pid = Some(*pid);
        }
    }

    if let Some(pid) = best_pid {
        let raw = pid.as_u32() as i32;
        info!("Killing top CPU process pid={} cpu={:.2}%", raw, best_cpu);
        kill(Pid::from_raw(raw), Signal::SIGTERM)?;
    }

    Ok(())
}
