use anyhow::Result;
use serde::{Deserialize, Serialize};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{UnixListener, UnixStream};

use crate::config::Config;

#[derive(Debug, Serialize, Deserialize)]
pub enum Request {
    GetConfig,
    SetConfig(Config),
}

#[derive(Debug, Serialize, Deserialize)]
pub enum Response {
    Ok,
    Config(Config),
    Err(String),
}

pub async fn run_socket(path: &str) -> Result<UnixListener> {
    let _ = std::fs::remove_file(path);
    Ok(UnixListener::bind(path)?)
}

pub async fn handle_client(mut stream: UnixStream, cfg: Config) -> Result<()> {
    let mut buf = vec![0u8; 4096];
    let n = stream.read(&mut buf).await?;
    if n == 0 {
        return Ok(());
    }

    let req: Request = serde_json::from_slice(&buf[..n])?;
    let resp = match req {
        Request::GetConfig => Response::Config(cfg),
        Request::SetConfig(_) => Response::Err("set config not yet wired".into()),
    };

    let data = serde_json::to_vec(&resp)?;
    stream.write_all(&data).await?;
    Ok(())
}
