use anyhow::Result;
use std::sync::Arc;
use tokio::sync::RwLock;
use tokio::time::{interval, Duration};
use tracing::{info, warn};

use crate::{
    actions::execute,
    config::Config,
    ipc::{handle_client, run_socket},
    metrics::Sampler,
    policy::evaluate,
};

pub async fn run() -> Result<()> {
    let cfg = Arc::new(RwLock::new(Config::default()));
    let mut sampler = Sampler::new();
    let sock = run_socket("/tmp/osd.sock").await?;

    let cfg_for_ipc = cfg.clone();
    tokio::spawn(async move {
        loop {
            match sock.accept().await {
                Ok((stream, _)) => {
                    let cfg = cfg_for_ipc.read().await.clone();
                    if let Err(e) = handle_client(stream, cfg).await {
                        warn!("IPC error: {e:#}");
                    }
                }
                Err(e) => warn!("Socket accept error: {e:#}"),
            }
        }
    });

    loop {
        let current_cfg = cfg.read().await.clone();
        let mut ticker = interval(Duration::from_millis(current_cfg.sample_interval_ms));

        ticker.tick().await;
        let metrics = sampler.sample();
        info!(
            "cpu={:.1}% mem={:.1}% disk={:.1}%",
            metrics.cpu_usage_pct, metrics.mem_usage_pct, metrics.disk_usage_pct
        );

        let decision = evaluate(&current_cfg, &metrics);
        for action in decision.actions {
            if let Err(e) = execute(action) {
                warn!("Action failed: {e:#}");
            }
        }
    }
}
