## `collector.go`

```go
package main

import (
	"context"
	"fmt"
	"time"

	"github.com/shirou/gopsutil/v4/cpu"
	"github.com/shirou/gopsutil/v4/disk"
	"github.com/shirou/gopsutil/v4/mem"
	"github.com/shirou/gopsutil/v4/process"
)

type Collector struct{}

func NewCollector() *Collector {
	return &Collector{}
}

func (c *Collector) Collect(ctx context.Context) (Metrics, error) {
	var m Metrics
	m.Timestamp = time.Now()

	type result struct {
		name  string
		value interface{}
		err   error
	}

	ch := make(chan result, 4)

	go func() {
		percent, err := cpu.PercentWithContext(ctx, 0, false)
		if err != nil {
			ch <- result{name: "cpu", err: err}
			return
		}
		if len(percent) == 0 {
			ch <- result{name: "cpu", err: fmt.Errorf("no cpu data")}
			return
		}
		ch <- result{name: "cpu", value: percent[0]}
	}()

	go func() {
		vm, err := mem.VirtualMemoryWithContext(ctx)
		if err != nil {
			ch <- result{name: "mem", err: err}
			return
		}
		ch <- result{name: "mem", value: vm.UsedPercent}
	}()

	go func() {
		du, err := disk.UsageWithContext(ctx, "/")
		if err != nil {
			ch <- result{name: "disk", err: err}
			return
		}
		ch <- result{name: "disk", value: du.UsedPercent}
	}()

	go func() {
		procs, err := process.ProcessesWithContext(ctx)
		if err != nil {
			ch <- result{name: "proc", err: err}
			return
		}
		ch <- result{name: "proc", value: len(procs)}
	}()

	for i := 0; i < 4; i++ {
		select {
		case <-ctx.Done():
			return Metrics{}, ctx.Err()
		case r := <-ch:
			if r.err != nil {
				return Metrics{}, r.err
			}
			switch r.name {
			case "cpu":
				m.CPUPercent = r.value.(float64)
			case "mem":
				m.MemoryPercent = r.value.(float64)
			case "disk":
				m.DiskPercent = r.value.(float64)
			case "proc":
				m.ProcessCount = r.value.(int)
			}
		}
	}

	return m, nil
}
```

