## `policy.go`

```go
package main

type Alert struct {
	Level   string
	Message string
}

type PolicyEngine struct {
	cfg Config
}

func NewPolicyEngine(cfg Config) *PolicyEngine {
	return &PolicyEngine{cfg: cfg}
}

func (p *PolicyEngine) Evaluate(m Metrics) []Alert {
	var alerts []Alert

	if m.CPUPercent > p.cfg.CPUThreshold {
		alerts = append(alerts, Alert{
			Level:   "warning",
			Message: "CPU usage threshold exceeded",
		})
	}

	if m.MemoryPercent > p.cfg.MemThreshold {
		alerts = append(alerts, Alert{
			Level:   "warning",
			Message: "Memory usage threshold exceeded",
		})
	}

	if m.DiskPercent > p.cfg.DiskThreshold {
		alerts = append(alerts, Alert{
			Level:   "critical",
			Message: "Disk usage threshold exceeded",
		})
	}

	if m.ProcessCount > p.cfg.MaxProcesses {
		alerts = append(alerts, Alert{
			Level:   "warning",
			Message: "Process count threshold exceeded",
		})
	}

	return alerts
}
