## `daemon.go`

```go
package main

import (
	"context"
	"log"
	"time"
)

type Daemon struct {
	cfg       Config
	collector *Collector
	policy    *PolicyEngine
	manager   *Manager
}

func NewDaemon(cfg Config) *Daemon {
	return &Daemon{
		cfg:       cfg,
		collector: NewCollector(),
		policy:    NewPolicyEngine(cfg),
		manager:   NewManager(),
	}
}

func (d *Daemon) Run(ctx context.Context) error {
	ticker := time.NewTicker(d.cfg.PollInterval)
	defer ticker.Stop()

	log.Printf("sysd started with poll interval %s", d.cfg.PollInterval)

	for {
		select {
		case <-ctx.Done():
			log.Println("sysd shutting down")
			return ctx.Err()
		case <-ticker.C:
			m, err := d.collector.Collect(ctx)
			if err != nil {
				log.Printf("collect error: %v", err)
				continue
			}

			alerts := d.policy.Evaluate(m)
			if len(alerts) > 0 {
				d.manager.Handle(alerts, m)
			}
		}
	}
}
```

