## 3) `src/main.rs`

```rust
use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::PathBuf,
    sync::Arc,
    time::Duration,
};
use sysinfo::{CpuExt, PidExt, ProcessExt, System, SystemExt};
use tokio::{
    signal,
    sync::RwLock,
    time::interval,
};
use tracing::{error, info, warn};
use tracing_subscriber::{fmt, EnvFilter};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    poll_interval_secs: u64,
    cpu_warning_threshold: f32,
    mem_warning_threshold: f32,
    load_warning_threshold: f64,
    max_process_count: usize,
    pid_file: Option<PathBuf>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_secs: 2,
            cpu_warning_threshold: 85.0,
            mem_warning_threshold: 90.0,
            load_warning_threshold: 4.0,
            max_process_count: 1024,
            pid_file: Some(PathBuf::from("/run/sysd.pid")),
        }
    }
}

#[derive(Debug, Clone)]
struct Snapshot {
    cpu_usage: f32,
    mem_used_percent: f32,
    load_avg_1m: f64,
    process_count: usize,
    top_processes: Vec<(i32, String, f32)>, // pid, name, cpu%
}

#[derive(Default)]
struct SharedState {
    last_snapshot: Option<Snapshot>,
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    let config = load_config("/etc/sysd.toml").unwrap_or_default();
    info!("starting sysd with config: {:?}", config);

    if let Some(pid_file) = &config.pid_file {
        write_pid_file(pid_file)?;
    }

    let state = Arc::new(RwLock::new(SharedState::default()));
    let mut sys = System::new_all();

    let monitor_state = state.clone();
    let monitor_config = config.clone();

    let monitor_task = tokio::spawn(async move {
        let mut tick = interval(Duration::from_secs(monitor_config.poll_interval_secs));
        loop {
            tick.tick().await;

            if let Err(e) = collect_and_evaluate(&mut sys, &monitor_state, &monitor_config).await {
                error!("monitoring cycle failed: {:#}", e);
            }
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown signal received");
        }
        res = monitor_task => {
            if let Err(e) = res {
                error!("monitor task crashed: {}", e);
            }
        }
    }

    if let Some(pid_file) = &config.pid_file {
        let _ = fs::remove_file(pid_file);
    }

    info!("sysd stopped");
    Ok(())
}

fn init_logging() {
    let filter = EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| EnvFilter::new("info"));

    fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

fn load_config(path: &str) -> Result<Config> {
    let contents = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file at {}", path))?;
    let cfg: Config = toml::from_str(&contents)
        .with_context(|| "failed to parse TOML configuration")?;
    Ok(cfg)
}

fn write_pid_file(path: &PathBuf) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("failed to create pid directory {:?}", parent))?;
    }

    let pid = std::process::id();
    fs::write(path, format!("{}\n", pid))
        .with_context(|| format!("failed to write pid file {:?}", path))?;

    Ok(())
}

async fn collect_and_evaluate(
    sys: &mut System,
    shared: &Arc<RwLock<SharedState>>,
    config: &Config,
) -> Result<()> {
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_system();
    sys.refresh_processes();

    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let total_mem = sys.total_memory() as f32;
    let used_mem = sys.used_memory() as f32;
    let mem_used_percent = if total_mem > 0.0 {
        (used_mem / total_mem) * 100.0
    } else {
        0.0
    };

    let load = sys.load_average();
    let process_count = sys.processes().len();

    let mut top_processes: Vec<(i32, String, f32)> = sys
        .processes()
        .iter()
        .map(|(pid, proc_)| {
            (
                pid.as_u32() as i32,
                proc_.name().to_string(),
                proc_.cpu_usage(),
            )
        })
        .collect();

    top_processes.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
    top_processes.truncate(5);

    let snapshot = Snapshot {
        cpu_usage,
        mem_used_percent,
        load_avg_1m: load.one,
        process_count,
        top_processes,
    };

    {
        let mut guard = shared.write().await;
        guard.last_snapshot = Some(snapshot.clone());
    }

    emit_metrics(&snapshot);

    evaluate_thresholds(&snapshot, config);

    if process_count > config.max_process_count {
        warn!(
            "process count {} exceeds configured maximum {}",
            process_count, config.max_process_count
        );
    }

    Ok(())
}

fn emit_metrics(snapshot: &Snapshot) {
    info!(
        "cpu={:.1}%, mem={:.1}%, load1={:.2}, procs={}",
        snapshot.cpu_usage,
        snapshot.mem_used_percent,
        snapshot.load_avg_1m,
        snapshot.process_count
    );

    for (pid, name, cpu) in &snapshot.top_processes {
        info!("top_process pid={} name={} cpu={:.1}%", pid, name, cpu);
    }
}

fn evaluate_thresholds(snapshot: &Snapshot, config: &Config) {
    if snapshot.cpu_usage > config.cpu_warning_threshold {
        warn!(
            "cpu usage high: {:.1}% > {:.1}%",
            snapshot.cpu_usage, config.cpu_warning_threshold
        );
        // Action hook: add throttling / mitigation logic here.
    }

    if snapshot.mem_used_percent > config.mem_warning_threshold {
        warn!(
            "memory usage high: {:.1}% > {:.1}%",
            snapshot.mem_used_percent, config.mem_warning_threshold
        );
        // Action hook: add reclamation / cgroup pressure response here.
    }

    if snapshot.load_avg_1m > config.load_warning_threshold {
        warn!(
            "load average high: {:.2} > {:.2}",
            snapshot.load_avg_1m, config.load_warning_threshold
        );
        // Action hook: add scheduling or load-shedding policy here.
    }
}
