use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use nix::sys::signal::{kill, Signal};
use nix::unistd::Pid;
use signal_hook::consts::{SIGINT, SIGTERM};
use signal_hook::flag;
use sysinfo::{
    CpuRefreshKind, DiskExt, Disks, System, SystemExt,
};

const INTERVAL_SECS: u64 = 2;
const CPU_WARN: f32 = 85.0;
const MEM_WARN: f32 = 85.0;
const DISK_WARN: f32 = 90.0;

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    flag::register(SIGINT, running.clone()).expect("failed to register SIGINT");
    flag::register(SIGTERM, running.clone()).expect("failed to register SIGTERM");

    // Optional: set a target PID to manage under critical conditions.
    // Example: export TARGET_PID=1234
    let target_pid = std::env::var("TARGET_PID")
        .ok()
        .and_then(|s| s.parse::<i32>().ok())
        .map(Pid::from_raw);

    let mut system = System::new_all();
    let mut disks = Disks::new_with_refreshed_list();

    eprintln!("resmon-daemon started");

    while running.load(Ordering::Relaxed) {
        system.refresh_cpu_specifics(CpuRefreshKind::new().with_cpu_usage());
        system.refresh_memory();
        disks.refresh_list();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let total_mem = system.total_memory() as f32;
        let used_mem = system.used_memory() as f32;
        let mem_usage = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        // Pick the first disk as a minimal default.
        let disk_usage = disks
            .iter()
            .next()
            .map(|disk| {
                let total = disk.total_space() as f32;
                let avail = disk.available_space() as f32;
                if total > 0.0 {
                    ((total - avail) / total) * 100.0
                } else {
                    0.0
                }
            })
            .unwrap_or(0.0);

        println!(
            "cpu={:.1}% mem={:.1}% disk={:.1}%",
            cpu_usage, mem_usage, disk_usage
        );

        if cpu_usage > CPU_WARN {
            eprintln!("warning: high CPU usage: {:.1}%", cpu_usage);
        }

        if mem_usage > MEM_WARN {
            eprintln!("warning: high memory usage: {:.1}%", mem_usage);
        }

        if disk_usage > DISK_WARN {
            eprintln!("warning: high disk usage: {:.1}%", disk_usage);
        }

        // Minimal management action example:
        // If memory is critically high, signal the configured target PID.
        if mem_usage > 95.0 {
            if let Some(pid) = target_pid {
                eprintln!("critical: memory pressure high, sending SIGTERM to {}", pid);
                let _ = kill(pid, Signal::SIGTERM);
            }
        }

        thread::sleep(Duration::from_secs(INTERVAL_SECS));
    }

    eprintln!("resmon-daemon shutting down");
}
