use anyhow::Result;
use serde::Serialize;
use std::sync::Arc;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{Mutex, RwLock};
use tokio::time::{self, Duration};

#[derive(Debug, Clone, Serialize)]
struct Metrics {
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    process_count: usize,
    total_disk_space: u64,
    available_disk_space: u64,
}

struct SharedState {
    system: Mutex<System>,
    metrics: RwLock<Metrics>,
    interval_ms: RwLock<u64>,
}

impl SharedState {
    fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let metrics = Metrics {
            cpu_usage: 0.0,
            total_memory: system.total_memory(),
            used_memory: system.used_memory(),
            total_swap: system.total_swap(),
            used_swap: system.used_swap(),
            load_avg_one: 0.0,
            load_avg_five: 0.0,
            load_avg_fifteen: 0.0,
            process_count: system.processes().len(),
            total_disk_space: 0,
            available_disk_space: 0,
        };

        Self {
            system: Mutex::new(system),
            metrics: RwLock::new(metrics),
            interval_ms: RwLock::new(1000),
        }
    }
}

async fn collect_metrics(state: Arc<SharedState>) {
    let mut ticker = time::interval(Duration::from_millis(1000));

    loop {
        ticker.tick().await;

        let interval = *state.interval_ms.read().await;
        ticker = time::interval(Duration::from_millis(interval));

        let mut system = state.system.lock().await;
        system.refresh_all();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let load = System::load_average();

        let mut total_disk_space = 0;
        let mut available_disk_space = 0;
        for disk in system.disks() {
            total_disk_space += disk.total_space();
            available_disk_space += disk.available_space();
        }

        let updated = Metrics {
            cpu_usage,
            total_memory: system.total_memory(),
            used_memory: system.used_memory(),
            total_swap: system.total_swap(),
            used_swap: system.used_swap(),
            load_avg_one: load.one,
            load_avg_five: load.five,
            load_avg_fifteen: load.fifteen,
            process_count: system.processes().len(),
            total_disk_space,
            available_disk_space,
        };

        {
            let mut metrics = state.metrics.write().await;
            *metrics = updated.clone();
        }

        println!(
            "cpu={:.1}% mem={}/{} swap={}/{} procs={} load={:.2},{:.2},{:.2} disk={}/{}",
            updated.cpu_usage,
            updated.used_memory,
            updated.total_memory,
            updated.used_swap,
            updated.total_swap,
            updated.process_count,
            updated.load_avg_one,
            updated.load_avg_five,
            updated.load_avg_fifteen,
            updated.available_disk_space,
            updated.total_disk_space
        );
    }
}

async fn handle_client(stream: TcpStream, state: Arc<SharedState>) -> Result<()> {
    let (read_half, mut write_half) = stream.into_split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    write_half
        .write_all(b"OSD daemon ready. Commands: STATUS, INTERVAL <ms>, QUIT\n")
        .await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();

        if cmd.eq_ignore_ascii_case("STATUS") {
            let metrics = state.metrics.read().await.clone();
            let json = serde_json::to_string(&metrics)?;
            write_half.write_all(json.as_bytes()).await?;
            write_half.write_all(b"\n").await?;
        } else if cmd.to_ascii_uppercase().starts_with("INTERVAL ") {
            if let Some(value) = cmd.split_whitespace().nth(1) {
                match value.parse::<u64>() {
                    Ok(ms) if ms >= 100 => {
                        *state.interval_ms.write().await = ms;
                        write_half.write_all(b"OK\n").await?;
                    }
                    _ => {
                        write_half.write_all(b"ERR invalid interval\n").await?;
                    }
                }
            } else {
                write_half.write_all(b"ERR missing value\n").await?;
            }
        } else if cmd.eq_ignore_ascii_case("QUIT") {
            write_half.write_all(b"BYE\n").await?;
            break;
        } else {
            write_half.write_all(b"ERR unknown command\n").await?;
        }
    }

    Ok(())
}

async fn control_server(state: Arc<SharedState>) -> Result<()> {
    let listener = TcpListener::bind("127.0.0.1:7878").await?;
    println!("control server listening on 127.0.0.1:7878");

    loop {
        let (stream, _) = listener.accept().await?;
        let s = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, s).await {
                eprintln!("client error: {e}");
            }
        });
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let state = Arc::new(SharedState::new());

    let collector = {
        let s = state.clone();
        tokio::spawn(async move {
            collect_metrics(s).await;
        })
    };

    let server = {
        let s = state.clone();
        tokio::spawn(async move {
            if let Err(e) = control_server(s).await {
                eprintln!("control server error: {e}");
            }
        })
    };

    tokio::signal::ctrl_c().await?;
    println!("shutting down");

    collector.abort();
    server.abort();

    Ok(())
}
