use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::time::interval;
use tracing::{info, warn};

struct Config {
    poll_interval: Duration,
    memory_warn_percent: u64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval: Duration::from_secs(2),
            memory_warn_percent: 85,
        }
    }
}

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = Config::default();
    let mut system = System::new_all();
    let mut ticker = interval(config.poll_interval);

    info!("sysdaemon started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                system.refresh_all();

                let total_memory = system.total_memory();
                let used_memory = system.used_memory();
                let memory_percent = if total_memory > 0 {
                    (used_memory * 100) / total_memory
                } else {
                    0
                };

                let cpu_usage = system.global_cpu_info().cpu_usage();

                info!(
                    cpu_usage = cpu_usage,
                    used_memory_kb = used_memory,
                    total_memory_kb = total_memory,
                    memory_percent = memory_percent,
                    "resource snapshot"
                );

                if memory_percent >= config.memory_warn_percent {
                    warn!(
                        memory_percent = memory_percent,
                        threshold = config.memory_warn_percent,
                        "memory usage above threshold"
                    );

                    // Placeholder for action:
                    // - notify admin
                    // - trigger cleanup
                    // - limit/kill specific process
                }

                for disk in system.disks() {
                    let total = disk.total_space();
                    let available = disk.available_space();
                    let used_percent = if total > 0 {
                        ((total - available) * 100) / total
                    } else {
                        0
                    };

                    info!(
                        mount = disk.mount_point().to_string_lossy(),
                        fs = disk.file_system().to_string_lossy(),
                        used_percent = used_percent,
                        "disk snapshot"
                    );
                }
            }

            _ = tokio::signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("sysdaemon stopped");
}
