use daemonize::Daemonize;
use log::{error, info, warn};
use simplelog::{Config, LevelFilter, WriteLogger};
use std::fs::File;
use std::thread;
use std::time::Duration;
use sysinfo::{CpuExt, System, SystemExt};

const LOG_PATH: &str = "/tmp/resourced.log";
const PID_PATH: &str = "/tmp/resourced.pid";
const SAMPLE_INTERVAL_SECS: u64 = 2;
const MEMORY_WARNING_THRESHOLD: f32 = 85.0;

fn main() {
    let log_file = File::create(LOG_PATH).expect("failed to create log file");

    WriteLogger::init(LevelFilter::Info, Config::default(), log_file)
        .expect("failed to initialize logger");

    let daemonize = Daemonize::new()
        .pid_file(PID_PATH)
        .working_directory("/")
        .umask(0o027);

    match daemonize.start() {
        Ok(_) => info!("daemon started"),
        Err(e) => {
            eprintln!("failed to daemonize: {}", e);
            return;
        }
    }

    let mut system = System::new_all();

    loop {
        system.refresh_all();

        let total_memory = system.total_memory() as f32;
        let used_memory = system.used_memory() as f32;
        let mem_percent = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let cpu_usage: f32 = if system.cpus().is_empty() {
            0.0
        } else {
            system.cpus().iter().map(|cpu| cpu.cpu_usage()).sum::<f32>() / system.cpus().len() as f32
        };

        info!(
            "cpu_usage={:.1}% mem_usage={:.1}% used_memory={}KB total_memory={}KB",
            cpu_usage,
            mem_percent,
            used_memory as u64,
            total_memory as u64
        );

        if mem_percent > MEMORY_WARNING_THRESHOLD {
            warn!(
                "memory usage high: {:.1}% > {:.1}%",
                mem_percent, MEMORY_WARNING_THRESHOLD
            );

            // Minimal "management" action: record pressure and optionally reclaim caches
            // (safe placeholder; replace with policy-specific actions in real deployments)
            if let Err(e) = write_pressure_marker(mem_percent) {
                error!("failed to write pressure marker: {}", e);
            }
        }

        thread::sleep(Duration::from_secs(SAMPLE_INTERVAL_SECS));
    }
}

fn write_pressure_marker(mem_percent: f32) -> std::io::Result<()> {
    let path = "/tmp/resourced.pressure";
    std::fs::write(path, format!("memory_pressure={:.1}%\n", mem_percent))
}
