## `src/main.rs`

```rust
use std::{
    fs,
    io,
    path::Path,
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    },
    time::Duration,
};

use serde::Serialize;
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{UnixListener, UnixStream},
    signal::unix::{signal, SignalKind},
    sync::RwLock,
    time::sleep,
};

const SOCKET_PATH: &str = "/tmp/sysd.sock";

#[derive(Clone)]
struct SharedState {
    status: Arc<RwLock<DaemonStatus>>,
    running: Arc<AtomicBool>,
}

#[derive(Debug, Serialize, Clone)]
struct DaemonStatus {
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    process_count: usize,
}

impl Default for DaemonStatus {
    fn default() -> Self {
        Self {
            cpu_usage: 0.0,
            total_memory: 0,
            used_memory: 0,
            process_count: 0,
        }
    }
}

#[tokio::main]
async fn main() -> io::Result<()> {
    cleanup_socket()?;

    let listener = UnixListener::bind(SOCKET_PATH)?;
    let shared = SharedState {
        status: Arc::new(RwLock::new(DaemonStatus::default())),
        running: Arc::new(AtomicBool::new(true)),
    };

    println!("sysd started on {}", SOCKET_PATH);

    let monitor_shared = shared.clone();
    let monitor_task = tokio::spawn(async move {
        resource_monitor_loop(monitor_shared).await;
    });

    let accept_shared = shared.clone();
    let accept_task = tokio::spawn(async move {
        accept_loop(listener, accept_shared).await;
    });

    let term_shared = shared.clone();
    let signal_task = tokio::spawn(async move {
        handle_signals(term_shared).await;
    });

    let _ = tokio::join!(monitor_task, accept_task, signal_task);

    cleanup_socket()?;
    println!("sysd stopped");
    Ok(())
}

async fn resource_monitor_loop(shared: SharedState) {
    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything())
            .with_processes(ProcessRefreshKind::everything()),
    );

    while shared.running.load(Ordering::Relaxed) {
        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_processes();

        let status = DaemonStatus {
            cpu_usage: system.global_cpu_usage(),
            total_memory: system.total_memory(),
            used_memory: system.used_memory(),
            process_count: system.processes().len(),
        };

        {
            let mut guard = shared.status.write().await;
            *guard = status.clone();
        }

        println!(
            "CPU: {:.1}% | Memory: {}/{} KB | Processes: {}",
            status.cpu_usage, status.used_memory, status.total_memory, status.process_count
        );

        sleep(Duration::from_secs(2)).await;
    }
}

async fn accept_loop(listener: UnixListener, shared: SharedState) {
    loop {
        if !shared.running.load(Ordering::Relaxed) {
            break;
        }

        match listener.accept().await {
            Ok((stream, _)) => {
                let shared = shared.clone();
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, shared).await {
                        eprintln!("client error: {}", e);
                    }
                });
            }
            Err(e) => {
                eprintln!("accept error: {}", e);
                break;
            }
        }
    }
}

async fn handle_client(mut stream: UnixStream, shared: SharedState) -> io::Result<()> {
    let mut buf = [0u8; 1024];
    let n = stream.read(&mut buf).await?;
    let cmd = String::from_utf8_lossy(&buf[..n]).trim().to_lowercase();

    match cmd.as_str() {
        "status" => {
            let status = shared.status.read().await.clone();
            let json = serde_json::to_string(&status).unwrap();
            stream.write_all(json.as_bytes()).await?;
        }
        "reload" => {
            // Minimal placeholder for config reload
            stream.write_all(b"ok reloaded\n").await?;
        }
        "quit" => {
            shared.running.store(false, Ordering::Relaxed);
            stream.write_all(b"ok shutting down\n").await?;
        }
        _ => {
            stream.write_all(b"error unknown command\n").await?;
        }
    }

    Ok(())
}

async fn handle_signals(shared: SharedState) {
    let mut sigterm = signal(SignalKind::terminate()).expect("failed to register SIGTERM");
    let mut sigint = signal(SignalKind::interrupt()).expect("failed to register SIGINT");

    tokio::select! {
        _ = sigterm.recv() => {
            shared.running.store(false, Ordering::Relaxed);
            println!("received SIGTERM");
        }
        _ = sigint.recv() => {
            shared.running.store(false, Ordering::Relaxed);
            println!("received SIGINT");
        }
    }
}

fn cleanup_socket() -> io::Result<()> {
    if Path::new(SOCKET_PATH).exists() {
        fs::remove_file(SOCKET_PATH)?;
    }
    Ok(())
}
