## Rust example: high-throughput flow analyser

```rust
use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::time::{Duration, Instant};

use crossbeam::queue::ArrayQueue;
use dashmap::DashMap;
use lane::Lane; // optional; if unavailable, replace with a simpler sharded map
use parking_lot::Mutex;

#[derive(Clone, Copy, Debug, Hash, PartialEq, Eq)]
#[repr(C)]
pub enum IpAddrKind {
    V4(u32),
    V6([u8; 16]),
}

#[derive(Clone, Copy, Debug, Hash, PartialEq, Eq)]
#[repr(C)]
pub struct FlowKey {
    pub src_ip: IpAddrKind,
    pub dst_ip: IpAddrKind,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Default, Clone, Debug)]
#[repr(C)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen_ns: u64,
    pub last_seen_ns: u64,
    pub tcp_flags: u8,
}

impl FlowStats {
    #[inline(always)]
    pub fn update(&mut self, ts_ns: u64, len: usize, tcp_flags: Option<u8>) {
        self.packets += 1;
        self.bytes += len as u64;
        if self.first_seen_ns == 0 {
            self.first_seen_ns = ts_ns;
        }
        self.last_seen_ns = ts_ns;
        if let Some(f) = tcp_flags {
            self.tcp_flags |= f;
        }
    }
}

#[derive(Debug)]
pub struct PacketMeta {
    pub ts_ns: u64,
    pub len: usize,
    pub flow: FlowKey,
    pub tcp_flags: Option<u8>,
}

pub struct FlowAnalyzer {
    // For very high update contention, consider sharding manually by flow hash.
    flows: DashMap<FlowKey, FlowStats>,
    ingest_queue: Arc<ArrayQueue<PacketMeta>>,
}

impl FlowAnalyzer {
    pub fn new(queue_size: usize) -> Self {
        Self {
            flows: DashMap::with_capacity(1 << 20),
            ingest_queue: Arc::new(ArrayQueue::new(queue_size)),
        }
    }

    #[inline(always)]
    pub fn ingest(&self, pkt: PacketMeta) -> Result<(), PacketMeta> {
        self.ingest_queue.push(pkt).map_err(|p| p)
    }

    pub fn worker_loop(&self, stop_after: Option<Duration>) {
        let start = Instant::now();

        loop {
            if let Some(limit) = stop_after {
                if start.elapsed() >= limit {
                    break;
                }
            }

            if let Some(pkt) = self.ingest_queue.pop() {
                self.update_flow(pkt);
            } else {
                std::hint::spin_loop();
            }
        }
    }

    #[inline(always)]
    fn update_flow(&self, pkt: PacketMeta) {
        use dashmap::mapref::entry::Entry;

        match self.flows.entry(pkt.flow) {
            Entry::Occupied(mut e) => {
                e.get_mut().update(pkt.ts_ns, pkt.len, pkt.tcp_flags);
            }
            Entry::Vacant(e) => {
                let mut stats = FlowStats::default();
                stats.update(pkt.ts_ns, pkt.len, pkt.tcp_flags);
                e.insert(stats);
            }
        }
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        self.flows
            .iter()
            .map(|entry| (*entry.key(), entry.value().clone()))
            .collect()
    }

    pub fn expire_idle_flows(&self, idle_timeout_ns: u64, now_ns: u64) -> Vec<(FlowKey, FlowStats)> {
        let mut evicted = Vec::new();

        self.flows.retain(|k, v| {
            let idle = now_ns.saturating_sub(v.last_seen_ns);
            if idle > idle_timeout_ns {
                evicted.push((*k, v.clone()));
                false
            } else {
                true
            }
        });

        evicted
    }
}

// ---------- Fast packet parsing helpers ----------

#[inline(always)]
pub fn parse_ipv4_flow(
    src: Ipv4Addr,
    dst: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
) -> FlowKey {
    FlowKey {
        src_ip: IpAddrKind::V4(u32::from_be_bytes(src.octets())),
        dst_ip: IpAddrKind::V4(u32::from_be_bytes(dst.octets())),
        src_port,
        dst_port,
        protocol: proto,
    }
}

#[inline(always)]
pub fn parse_ipv6_flow(
    src: Ipv6Addr,
    dst: Ipv6Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
) -> FlowKey {
    FlowKey {
        src_ip: IpAddrKind::V6(src.octets()),
        dst_ip: IpAddrKind::V6(dst.octets()),
        src_port,
        dst_port,
        protocol: proto,
    }
}

// ---------- Example producer ----------

fn main() {
    let analyser = Arc::new(FlowAnalyzer::new(1 << 16));

    // In real deployments, spawn one producer per RX queue / NIC queue.
    let producer = {
        let analyser = analyser.clone();
        std::thread::spawn(move || {
            for i in 0..10_000_000u64 {
                let flow = FlowKey {
                    src_ip: IpAddrKind::V4(0x0a000001),
                    dst_ip: IpAddrKind::V4(0x0a000002),
                    src_port: 12345,
                    dst_port: 443,
                    protocol: 6,
                };

                let pkt = PacketMeta {
                    ts_ns: i,
                    len: 1500,
                    flow,
                    tcp_flags: Some(0x10),
                };

                // Drop if overwhelmed; alternatively use backpressure.
                let _ = analyser.ingest(pkt);
            }
        })
    };

    let consumer = {
        let analyser = analyser.clone();
        std::thread::spawn(move || {
            analyser.worker_loop(Some(Duration::from_secs(2)));
        })
    };

    producer.join().unwrap();
    consumer.join().unwrap();

    let snapshot = analyser.snapshot();
    println!("flows tracked: {}", snapshot.len());
}
