## Rust flow analyser skeleton

```rust
use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Eq, PartialEq, Hash)]
#[repr(C)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    _pad: u8,
}

#[derive(Clone, Copy, Default)]
#[repr(C)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ns: u64,
    last_seen_ns: u64,
}

struct FlowEntry {
    key: FlowKey,
    stats: FlowStats,
}

#[derive(Default)]
struct FastHasher(u64);

impl Hasher for FastHasher {
    #[inline]
    fn write(&mut self, bytes: &[u8]) {
        // Simple byte hash; replace with a stronger/faster hash if needed.
        let mut h = self.0;
        for &b in bytes {
            h ^= b as u64;
            h = h.wrapping_mul(0x100000001b3);
        }
        self.0 = h;
    }

    #[inline]
    fn write_u64(&mut self, i: u64) {
        self.0 ^= i;
        self.0 = self.0.wrapping_mul(0x100000001b3);
    }

    #[inline]
    fn write_u32(&mut self, i: u32) {
        self.write_u64(i as u64);
    }

    #[inline]
    fn write_u16(&mut self, i: u16) {
        self.write_u64(i as u64);
    }

    #[inline]
    fn write_u8(&mut self, i: u8) {
        self.write_u64(i as u64);
    }

    #[inline]
    fn finish(&self) -> u64 {
        self.0
    }
}

type FastBuildHasher = BuildHasherDefault<FastHasher>;

struct FlowTable {
    map: HashMap<FlowKey, FlowStats, FastBuildHasher>,
    timeout: Duration,
    max_flows: usize,
}

impl FlowTable {
    fn new(max_flows: usize, timeout: Duration) -> Self {
        let mut map = HashMap::with_capacity_and_hasher(max_flows, FastBuildHasher::default());
        map.shrink_to_fit();
        Self { map, timeout, max_flows }
    }

    #[inline]
    fn update_flow(&mut self, key: FlowKey, packet_len: usize, now_ns: u64) {
        if let Some(stats) = self.map.get_mut(&key) {
            stats.packets += 1;
            stats.bytes += packet_len as u64;
            stats.last_seen_ns = now_ns;
        } else {
            if self.map.len() >= self.max_flows {
                self.evict_oldest(now_ns);
            }
            self.map.insert(
                key,
                FlowStats {
                    packets: 1,
                    bytes: packet_len as u64,
                    first_seen_ns: now_ns,
                    last_seen_ns: now_ns,
                },
            );
        }
    }

    fn evict_oldest(&mut self, now_ns: u64) {
        let timeout_ns = self.timeout.as_nanos() as u64;

        // Simple linear scan eviction.
        // For larger deployments, use an LRU / timing wheel / segmented aging.
        let mut candidate: Option<FlowKey> = None;
        let mut oldest_ts = u64::MAX;

        for (k, v) in self.map.iter() {
            if now_ns.saturating_sub(v.last_seen_ns) > timeout_ns && v.last_seen_ns < oldest_ts {
                oldest_ts = v.last_seen_ns;
                candidate = Some(*k);
            }
        }

        if let Some(k) = candidate {
            self.map.remove(&k);
        } else {
            // If none are stale, remove an arbitrary entry to make room.
            if let Some(k) = self.map.keys().next().copied() {
                self.map.remove(&k);
            }
        }
    }

    fn reap_expired(&mut self, now_ns: u64) {
        let timeout_ns = self.timeout.as_nanos() as u64;
        self.map.retain(|_, v| now_ns.saturating_sub(v.last_seen_ns) <= timeout_ns);
    }
}

// Example packet header info extracted from a parser.
struct ParsedPacket {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    len: usize,
}

#[inline]
fn build_flow_key(pkt: &ParsedPacket) -> FlowKey {
    FlowKey {
        src_ip: u32::from_be_bytes(pkt.src_ip.octets()),
        dst_ip: u32::from_be_bytes(pkt.dst_ip.octets()),
        src_port: pkt.src_port.to_be(),
        dst_port: pkt.dst_port.to_be(),
        proto: pkt.proto,
        _pad: 0,
    }
}

fn process_packet(flow_table: &mut FlowTable, pkt: &ParsedPacket) {
    let key = build_flow_key(pkt);
    let now_ns = Instant::now().elapsed().as_nanos() as u64; // replace with monotonic clock source
    flow_table.update_flow(key, pkt.len, now_ns);
}

fn main() {
    let mut table = FlowTable::new(1_000_000, Duration::from_secs(30));

    // Simulated traffic.
    let pkt = ParsedPacket {
        src_ip: Ipv4Addr::new(10, 0, 0, 1),
        dst_ip: Ipv4Addr::new(10, 0, 0, 2),
        src_port: 12345,
        dst_port: 443,
        proto: 6,
        len: 1514,
    };

    for _ in 0..1_000_000 {
        process_packet(&mut table, &pkt);
    }

    table.reap_expired(1_000_000_000);
    println!("Flows tracked: {}", table.map.len());
}
```

