## C++20 implementation

```cpp
#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <chrono>
#include <vector>
#include <thread>
#include <optional>
#include <iostream>
#include <algorithm>

#if defined(__GNUC__) || defined(__clang__)
  #define ALWAYS_INLINE inline __attribute__((always_inline))
  #define LIKELY(x)   __builtin_expect(!!(x), 1)
  #define UNLIKELY(x) __builtin_expect(!!(x), 0)
#else
  #define ALWAYS_INLINE inline
  #define LIKELY(x)   (x)
  #define UNLIKELY(x) (x)
#endif

// ---------------------------
// Packet metadata
// ---------------------------
struct PacketMeta {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;   // e.g. TCP=6, UDP=17
    uint8_t  flags;    // optional parsing info
    uint16_t size;     // payload + headers if desired
    uint64_t timestamp_ns;
};

// ---------------------------
// Flow key and hash
// ---------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip   == other.src_ip &&
               dst_ip   == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto    == other.proto;
    }
};

static ALWAYS_INLINE uint64_t hash_flow_key(const FlowKey& k) noexcept {
    // Fast mixing; good enough for flow keys with low overhead.
    uint64_t x = 0xcbf29ce484222325ULL;

    auto mix = [&](uint64_t v) {
        x ^= v;
        x *= 0x100000001b3ULL;
    };

    mix(k.src_ip);
    mix(k.dst_ip);
    mix((uint64_t(k.src_port) << 16) | k.dst_port);
    mix(k.proto);

    // Final avalanche
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

// ---------------------------
// Flow statistics
// ---------------------------
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

// ---------------------------
// Flow entry
// Open-addressed, linear probing.
// ---------------------------
struct FlowEntry {
    std::atomic<uint8_t> state; // 0 = empty, 1 = occupied, 2 = tombstone
    FlowKey key;
    FlowStats stats;
    uint64_t hash;
};

static_assert(std::is_trivially_copyable_v<FlowKey>);
static_assert(std::is_trivially_copyable_v<FlowStats>);

// ---------------------------
// Flow table
// Per-shard table: one writer thread recommended.
// ---------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          entries_(capacity_) 
    {
        for (auto& e : entries_) {
            e.state.store(0, std::memory_order_relaxed);
            e.hash = 0;
            std::memset(&e.key, 0, sizeof(e.key));
            std::memset(&e.stats, 0, sizeof(e.stats));
        }
    }

    ALWAYS_INLINE FlowStats& update_or_insert(const PacketMeta& p) noexcept {
        FlowKey key{p.src_ip, p.dst_ip, p.src_port, p.dst_port, p.proto};
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < capacity_; ++probe) {
            FlowEntry& e = entries_[idx];
            uint8_t s = e.state.load(std::memory_order_acquire);

            if (LIKELY(s == 1)) {
                if (e.hash == h && e.key == key) {
                    touch(e, p);
                    return e.stats;
                }
            } else if (s == 0 || s == 2) {
                // Attempt to claim slot
                uint8_t expected = s;
                if (e.state.compare_exchange_strong(expected, 1,
                                                    std::memory_order_acq_rel,
                                                    std::memory_order_relaxed)) {
                    e.key = key;
                    e.hash = h;
                    e.stats.packets = 0;
                    e.stats.bytes = 0;
                    e.stats.first_seen_ns = p.timestamp_ns;
                    e.stats.last_seen_ns = p.timestamp_ns;
                    touch(e, p);
                    return e.stats;
                }
            }

            idx = (idx + 1) & mask_;
        }

        // Table full: in production, handle gracefully (evict, resize, drop).
        // Here we fallback to last probed slot.
        FlowEntry& e = entries_[idx];
        e.key = key;
        e.hash = h;
        e.stats.packets = 1;
        e.stats.bytes = p.size;
        e.stats.first_seen_ns = p.timestamp_ns;
        e.stats.last_seen_ns = p.timestamp_ns;
        e.state.store(1, std::memory_order_release);
        return e.stats;
    }

    template<typename Callback>
    void expire(uint64_t now_ns, uint64_t idle_timeout_ns, Callback&& cb) {
        // Incremental sweep could be used in production.
        for (auto& e : entries_) {
            if (e.state.load(std::memory_order_acquire) == 1) {
                if (now_ns > e.stats.last_seen_ns &&
                    (now_ns - e.stats.last_seen_ns) > idle_timeout_ns) {
                    cb(e.key, e.stats);
                    e.state.store(2, std::memory_order_release); // tombstone
                }
            }
        }
    }

private:
    ALWAYS_INLINE void touch(FlowEntry& e, const PacketMeta& p) noexcept {
        e.stats.packets += 1;
        e.stats.bytes += p.size;
        if (e.stats.first_seen_ns == 0) e.stats.first_seen_ns = p.timestamp_ns;
        e.stats.last_seen_ns = p.timestamp_ns;
    }

    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
};

// ---------------------------
// Sharded analyzer
// Hash-to-core sharding.
// ---------------------------
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t shard_count_pow2, size_t table_pow2)
        : shard_count_(1ULL << shard_count_pow2),
          mask_(shard_count_ - 1)
    {
        shards_.reserve(shard_count_);
        for (size_t i = 0; i < shard_count_; ++i) {
            shards_.emplace_back(table_pow2);
        }
    }

    ALWAYS_INLINE void process_packet(const PacketMeta& p) noexcept {
        FlowKey key{p.src_ip, p.dst_ip, p.src_port, p.dst_port, p.proto};
        uint64_t h = hash_flow_key(key);
        shards_[static_cast<size_t>(h) & mask_].update_or_insert(p);
    }

    template<typename Callback>
    void expire_all(uint64_t now_ns, uint64_t idle_timeout_ns, Callback&& cb) {
        for (auto& shard : shards_) {
            shard.expire(now_ns, idle_timeout_ns, cb);
        }
    }

private:
    size_t shard_count_;
    size_t mask_;
    std::vector<FlowTable> shards_;
};

// ---------------------------
// Example usage
// ---------------------------
int main() {
    constexpr size_t shard_pow2 = 2;   // 4 shards
    constexpr size_t table_pow2  = 20;  // 1,048,576 entries per shard

    FlowAnalyzer analyzer(shard_pow2, table_pow2);

    // Simulated packet stream
    for (uint64_t i = 0; i < 1'000'000; ++i) {
        PacketMeta p{};
        p.src_ip = 0x0A000001u + (i % 1024);
        p.dst_ip = 0x0A000100u + (i % 256);
        p.src_port = static_cast<uint16_t>(10000 + (i % 40000));
        p.dst_port = 443;
        p.proto = 6;
        p.size = 1280;
        p.timestamp_ns = i * 1000;

        analyzer.process_packet(p);
    }

    analyzer.expire_all(
        2'000'000'000ULL,
        5'000'000'000ULL,
        [](const FlowKey& key, const FlowStats& stats) {
            std::cout << "Expired flow: "
                      << key.src_ip << ":" << key.src_port
                      << " -> " << key.dst_ip << ":" << key.dst_port
                      << " proto=" << unsigned(key.proto)
                      << " packets=" << stats.packets
                      << " bytes=" << stats.bytes << "\n";
        }
    );

    return 0;
}
