use std::collections::HashMap;
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Hash, Eq, PartialEq, Debug)]
struct FlowKey {
    src: Ipv4Addr,
    dst: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Default, Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

#[derive(Clone, Copy, Debug)]
struct FlowRecord {
    key: FlowKey,
    packets: u64,
    bytes: u64,
    timestamp: Instant,
}

struct FlowTable {
    table: HashMap<FlowKey, FlowStats>,
    ttl: Duration,
}

impl FlowTable {
    fn new(ttl: Duration) -> Self {
        Self {
            table: HashMap::with_capacity(1 << 20),
            ttl,
        }
    }

    fn ingest(&mut self, record: FlowRecord) {
        let entry = self.table.entry(record.key).or_insert_with(|| FlowStats {
            packets: 0,
            bytes: 0,
            first_seen: record.timestamp,
            last_seen: record.timestamp,
        });

        entry.packets += record.packets;
        entry.bytes += record.bytes;
        entry.last_seen = record.timestamp;
    }

    fn expire_old(&mut self, now: Instant) -> usize {
        let ttl = self.ttl;
        let before = self.table.len();

        self.table.retain(|_, v| now.duration_since(v.last_seen) <= ttl);

        before - self.table.len()
    }

    fn top_talkers(&self, n: usize) -> Vec<(FlowKey, FlowStats)> {
        let mut v: Vec<_> = self.table.iter().map(|(k, s)| (*k, s.clone())).collect();
        v.sort_unstable_by(|a, b| b.1.bytes.cmp(&a.1.bytes));
        v.truncate(n);
        v
    }
}

fn main() {
    let mut flows = FlowTable::new(Duration::from_secs(300));

    let now = Instant::now();
    let recs = vec![
        FlowRecord {
            key: FlowKey {
                src: "10.0.0.1".parse().unwrap(),
                dst: "10.0.0.2".parse().unwrap(),
                src_port: 44321,
                dst_port: 443,
                proto: 6,
            },
            packets: 120,
            bytes: 80_000,
            timestamp: now,
        },
        FlowRecord {
            key: FlowKey {
                src: "10.0.0.1".parse().unwrap(),
                dst: "10.0.0.3".parse().unwrap(),
                src_port: 44322,
                dst_port: 53,
                proto: 17,
            },
            packets: 8,
            bytes: 640,
            timestamp: now,
        },
    ];

    for r in recs {
        flows.ingest(r);
