// -------------------------------
// Packet and flow key definitions
// -------------------------------

#pragma pack(push, 1)
struct PacketView {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
    uint8_t  flags;     // optional: TCP flags, etc.
    uint16_t length;    // packet length
    uint64_t ts_ns;     // timestamp in ns
};
#pragma pack(pop)

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               protocol == o.protocol;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast-ish mix; replace with a stronger mixer if required.
        uint64_t x = (uint64_t)k.src_ip << 32 ^ k.dst_ip;
        x ^= (uint64_t)k.src_port << 16 ^ k.dst_port;
        x ^= (uint64_t)k.protocol;

        // SplitMix64 finalizer
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        x ^= (x >> 31);
        return (size_t)x;
    }
};

// -------------------------------
// Flow state
// -------------------------------

struct FlowState {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;

    // Optional TCP flag stats or other fields
    uint64_t syn_packets = 0;
    uint64_t fin_packets = 0;

    inline void update(const PacketView& p) noexcept {
        ++packets;
        bytes += p.length;

        if (first_seen_ns == 0) first_seen_ns = p.ts_ns;
        last_seen_ns = p.ts_ns;

        // Optional flags example
        if (p.flags & 0x02) ++syn_packets; // SYN
        if (p.flags & 0x01) ++fin_packets; // FIN
    }
};

// -------------------------------
// Sharded flow table
// -------------------------------

class FlowTable {
public:
    using Map = std::unordered_map<FlowKey, FlowState, FlowKeyHash>;

    explicit FlowTable(size_t shard_count = 64)
        : shards_(shard_count) {}

    void reserve_per_shard(size_t entries_per_shard) {
        for (auto& s : shards_) {
            std::unique_lock lk(s.mutex);
            s.map.reserve(entries_per_shard);
        }
    }

    inline void ingest(const PacketView& p) {
        FlowKey key{p.src_ip, p.dst_ip, p.src_port, p.dst_port, p.protocol};
        auto& shard = shards_[shard_for(key)];
        {
            std::unique_lock lk(shard.mutex);
            shard.map[key].update(p);
        }
    }

    template <typename ExportFn>
    void age_and_export(uint64_t now_ns, uint64_t idle_timeout_ns, ExportFn&& export_fn) {
        for (auto& shard : shards_) {
            std::unique_lock lk(shard.mutex);

            for (auto it = shard.map.begin(); it != shard.map.end(); ) {
                const auto& st = it->second;
                if (now_ns - st.last_seen_ns >= idle_timeout_ns) {
                    export_fn(it->first, st);
                    it = shard.map.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

    size_t shard_count() const noexcept { return shards_.size(); }

private:
    struct Shard {
        std::mutex mutex;
        Map map;
    };

    std::vector<Shard> shards_;

    inline size_t shard_for(const FlowKey& key) const noexcept {
        return FlowKeyHash{}(key) & (shards_.size() - 1);
    }
};

// -------------------------------
// Example exporter
// -------------------------------

static void print_flow(const FlowKey& k, const FlowState& s) {
    std::cout
        << "flow "
        << k.src_ip << ":" << k.src_port
        << " -> " << k.dst_ip << ":" << k.dst_port
        << " proto=" << unsigned(k.protocol)
        << " packets=" << s.packets
        << " bytes=" << s.bytes
        << " first_ns=" << s.first_seen_ns
        << " last_ns=" << s.last_seen_ns
        << " syn=" << s.syn_packets
        << " fin=" << s.fin_packets
        << "\n";
}

// -------------------------------
// High-throughput analyser
// -------------------------------

class NetworkFlowAnalyser {
public:
    explicit NetworkFlowAnalyser(size_t shards = 64,
                                 uint64_t idle_timeout_ns = 30ULL * 1'000'000'000ULL)
        : table_(shards),
          idle_timeout_ns_(idle_timeout_ns) {
        table_.reserve_per_shard(1 << 16); // pre-reserve
    }

    // Batch ingest interface for better throughput
    void ingest_batch(const PacketView* packets, size_t count) {
        for (size_t i = 0; i < count; ++i) {
            table_.ingest(packets[i]);
        }
    }

    void expire(uint64_t now_ns) {
        table_.age_and_export(now_ns, idle_timeout_ns_,
            [](const FlowKey& k, const FlowState& s) {
                print_flow(k, s);
            });
    }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
};

// -------------------------------
// Demo main
// -------------------------------

int main() {
    NetworkFlowAnalyser analyser(64);

    std::vector<PacketView> batch;
    batch.reserve(4);

    batch.push_back({0x0a000001, 0x0a000002, 12345, 80, 6, 0x02, 1500, 1}); // SYN
    batch.push_back({0x0a000001, 0x0a000002, 12345, 80, 6, 0x18, 1500, 2});
    batch.push_back({0x0a000001, 0x0a000002, 12345, 80, 6, 0x18, 1500, 3});
    batch.push_back({0x0a000001, 0x0a000002, 12345, 80, 6, 0x01, 1500, 4}); // FIN

    analyser.ingest_batch(batch.data(), batch.size());

    // Simulate expiry
    analyser.expire(60ULL * 1'000'000'000ULL);

    return 0;
}
