#if defined(__GNUC__) || defined(__clang__)
#define PREFETCH(addr) __builtin_prefetch((addr), 0, 1)
#else
#define PREFETCH(addr) ((void)0)
#endif

using Clock = std::chrono::steady_clock;
using TimePoint = Clock::time_point;
using ns = std::chrono::nanoseconds;

constexpr size_t NUM_SHARDS = 64;          // tune for CPU cores
constexpr auto FLOW_TIMEOUT = std::chrono::seconds(30);
constexpr uint32_t INITIAL_BUCKETS = 1 << 16;

enum class Protocol : uint8_t {
    TCP = 6,
    UDP = 17,
    ICMP = 1,
    OTHER = 255
};

#pragma pack(push, 1)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
    uint8_t  _pad[3]; // align to 16 bytes

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};
#pragma pack(pop)

static_assert(sizeof(FlowKey) == 16, "FlowKey should be 16 bytes");

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // FNV-1a-like mixing with some xorshift-style avalanche
        uint64_t x = 1469598103934665603ULL;
        auto mix = [&](uint64_t v) {
            x ^= v;
            x *= 1099511628211ULL;
        };
        mix(k.src_ip);
        mix(k.dst_ip);
        mix((uint64_t(k.src_port) << 16) | k.dst_port);
        mix(k.proto);
        x ^= (x >> 33);
        x *= 0xff51afd7ed558ccdULL;
        x ^= (x >> 33);
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= (x >> 33);
        return static_cast<size_t>(x);
    }
};

struct FlowRecord {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    TimePoint first_seen{};
    TimePoint last_seen{};
};

struct alignas(64) Shard {
    std::mutex mtx;
    std::unordered_map<FlowKey, FlowRecord, FlowKeyHash> table;

    Shard() {
        table.reserve(INITIAL_BUCKETS / NUM_SHARDS);
    }
};

class FlowAnalyser {
public:
    FlowAnalyser() : shards_(NUM_SHARDS) {}

    void process_packet(const FlowKey& key, size_t packet_bytes, TimePoint now) {
        auto& shard = shards_[shard_index(key)];
        std::lock_guard<std::mutex> lock(shard.mtx);

        auto it = shard.table.find(key);
        if (it == shard.table.end()) {
            FlowRecord rec;
            rec.packets = 1;
            rec.bytes = packet_bytes;
            rec.first_seen = now;
            rec.last_seen = now;
            shard.table.emplace(key, rec);
        } else {
            auto& rec = it->second;
            rec.packets++;
            rec.bytes += packet_bytes;
            rec.last_seen = now;
        }
    }

    void expire_old_flows(TimePoint now) {
        for (auto& shard : shards_) {
            std::lock_guard<std::mutex> lock(shard.mtx);

            for (auto it = shard.table.begin(); it != shard.table.end(); ) {
                if (now - it->second.last_seen > FLOW_TIMEOUT) {
                    // Export or log expired flow here if needed
                    it = shard.table.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

    void dump_stats() const {
        uint64_t total_flows = 0;
        uint64_t total_packets = 0;
        uint64_t total_bytes = 0;

        for (const auto& shard : shards_) {
            std::lock_guard<std::mutex> lock(shard.mtx);
            total_flows += shard.table.size();
            for (const auto& [key, rec] : shard.table) {
                (void)key;
                total_packets += rec.packets;
                total_bytes += rec.bytes;
            }
        }

        std::cout << "flows=" << total_flows
                  << " packets=" << total_packets
                  << " bytes=" << total_bytes << "\n";
    }

private:
    std::array<Shard, NUM_SHARDS> shards_;

    static size_t shard_index(const FlowKey& key) noexcept {
        return FlowKeyHash{}(key) % NUM_SHARDS;
    }
};

// Example packet parser stub
struct ParsedPacket {
    FlowKey key;
