bool parse_ipv4_tcp_udp(const uint8_t* data, size_t len, ParsedPacket& out) {
    // Minimal stub: replace with real parsing of Ethernet/IP/TCP/UDP headers.
    // This function assumes data already points to an IPv4 packet.
    if (len < 20) return false;

    uint8_t ihl = data[0] & 0x0F;
    if (ihl < 5) return false;

    uint8_t proto = data[9];
    if (proto != static_cast<uint8_t>(Protocol::TCP) &&
        proto != static_cast<uint8_t>(Protocol::UDP)) {
        return false;
    }

    uint32_t src_ip;
    uint32_t dst_ip;
    std::memcpy(&src_ip, data + 12, 4);
    std::memcpy(&dst_ip, data + 16, 4);

    size_t ip_header_len = ihl * 4;
    if (len < ip_header_len + 4) return false;

    const uint8_t* l4 = data + ip_header_len;
    uint16_t src_port;
    uint16_t dst_port;
    std::memcpy(&src_port, l4, 2);
    std::memcpy(&dst_port, l4 + 2, 2);

    out.key.src_ip = src_ip;
    out.key.dst_ip = dst_ip;
    out.key.src_port = src_port;
    out.key.dst_port = dst_port;
    out.key.proto = proto;
    std::memset(out.key._pad, 0, sizeof(out.key._pad));
    out.len = len;
    return true;
}

