    std::memcpy(fake_ipv4_tcp_packet + 20, &sport, 2);
    std::memcpy(fake_ipv4_tcp_packet + 22, &dport, 2);

    if (parse_ipv4_tcp_udp(fake_ipv4_tcp_packet, sizeof(fake_ipv4_tcp_packet), pkt)) {
        analyser.process_packet(pkt.key, pkt.len, now);
        analyser.process_packet(pkt.key, pkt.len, now + std::chrono::microseconds(10));
    }

    analyser.dump_stats();
    analyser.expire_old_flows(now + std::chrono::seconds(31));
    analyser.dump_stats();

    return 0;
}
