// -----------------------------
// Fast flow key
// -----------------------------
#pragma pack(push, 1)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};
#pragma pack(pop)

struct FlowKeyHash {
    static inline uint64_t mix64(uint64_t x) noexcept {
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return x;
    }

    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t a = (static_cast<uint64_t>(k.src_ip) << 32) | k.dst_ip;
        uint64_t b = (static_cast<uint64_t>(k.src_port) << 16) | k.dst_port;
        uint64_t c = static_cast<uint64_t>(k.protocol);
        return static_cast<size_t>(mix64(a ^ (mix64(b) + 0x9e3779b97f4a7c15ULL) ^ (c << 1)));
    }
};

// -----------------------------
// Flow stats
// -----------------------------
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_ts_ns = 0;
    uint64_t last_ts_ns = 0;
};

// -----------------------------
// Packet metadata
// -----------------------------
struct PacketView {
    const uint8_t* data = nullptr;
    size_t len = 0;
    uint64_t ts_ns = 0;
};

// -----------------------------
// Minimal IPv4/TCP/UDP parser
// Assumes Ethernet + IPv4.
// -----------------------------
class PacketParser {
public:
    static constexpr size_t ETH_HDR_LEN = 14;

    static std::optional<FlowKey> parse_flow_key(const PacketView& pkt, uint16_t& l3_len_out, uint8_t& proto_out) {
        if (pkt.len < ETH_HDR_LEN + sizeof(iphdr)) return std::nullopt;

        const uint8_t* p = pkt.data;

        // Ethernet type
        uint16_t ethertype;
        std::memcpy(&ethertype, p + 12, sizeof(ethertype));
        ethertype = ntohs(ethertype);
        if (ethertype != 0x0800) return std::nullopt; // IPv4 only

        const iphdr* ip = reinterpret_cast<const iphdr*>(p + ETH_HDR_LEN);
        if (ip->version != 4) return std::nullopt;

        const size_t ihl = static_cast<size_t>(ip->ihl) * 4;
        if (ihl < sizeof(iphdr)) return std::nullopt;

        const size_t ip_total_len = ntohs(ip->tot_len);
        if (pkt.len < ETH_HDR_LEN + ip_total_len) return std::nullopt;

        const uint8_t proto = ip->protocol;
        proto_out = proto;
        l3_len_out = static_cast<uint16_t>(ip_total_len);

        const uint8_t* l4 = p + ETH_HDR_LEN + ihl;
        FlowKey key{};
        key.src_ip = ntohl(ip->saddr);
        key.dst_ip = ntohl(ip->daddr);
        key.protocol = proto;

        if (proto == IPPROTO_TCP) {
            if (pkt.len < (l4 - p) + sizeof(tcphdr)) return std::nullopt;
            uint16_t sp, dp;
            std::memcpy(&sp, l4 + 0, sizeof(sp));
            std::memcpy(&dp, l4 + 2, sizeof(dp));
            key.src_port = ntohs(sp);
            key.dst_port = ntohs(dp);
        } else if (proto == IPPROTO_UDP) {
            if (pkt.len < (l4 - p) + sizeof(udphdr)) return std::nullopt;
            uint16_t sp, dp;
            std::memcpy(&sp, l4 + 0, sizeof(sp));
            std::memcpy(&dp, l4 + 2, sizeof(dp));
            key.src_port = ntohs(sp);
            key.dst_port = ntohs(dp);
        } else {
            // Other protocols: use 0 ports
            key.src_port = 0;
            key.dst_port = 0;
        }

        return key;
    }
};

// -----------------------------
// Flow table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t reserve_hint = 1 << 20) {
        table_.reserve(reserve_hint);
    }

    void ingest(const PacketView& pkt) {
        uint16_t l3_len = 0;
        uint8_t proto = 0;
        auto key_opt = PacketParser::parse_flow_key(pkt, l3_len, proto);
        if (!key_opt) return;

        const FlowKey key = *key_opt;
        auto& s = table_[key];

        if (s.packets == 0) {
            s.first_ts_ns = pkt.ts_ns;
        }
        s.last_ts_ns = pkt.ts_ns;
        s.packets++;
        s.bytes += pkt.len;
    }

    template <typename Sink>
    void export_and_clear(Sink&& sink) {
        for (auto& [k, v] : table_) {
            sink(k, v);
        }
        table_.clear();
    }

    size_t size() const noexcept { return table_.size(); }

private:
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table_;
};

// -----------------------------
// Thread-local shard
// -----------------------------
class ShardedAnalyzer {
public:
    explicit ShardedAnalyzer(size_t num_shards)
        : shards_(num_shards) {}

    void ingest(const PacketView& pkt) {
        uint16_t l3_len = 0;
        uint8_t proto = 0;
        auto key_opt = PacketParser::parse_flow_key(pkt, l3_len, proto);
        if (!key_opt) return;

        const FlowKey key = *key_opt;
        auto idx = shard_index(key);
        auto& shard = shards_[idx];
        auto& s = shard.table[key];

        if (s.packets == 0) {
            s.first_ts_ns = pkt.ts_ns;
        }
        s.last_ts_ns = pkt.ts_ns;
        s.packets++;
        s.bytes += pkt.len;
    }

    void export_all() {
        for (auto& shard : shards_) {
            std::lock_guard<std::mutex> lock(shard.mtx);
            for (const auto& [k, v] : shard.table) {
                std::cout << "flow "
                          << k.src_ip << ":" << k.src_port << " -> "
                          << k.dst_ip << ":" << k.dst_port
                          << " proto=" << unsigned(k.protocol)
                          << " packets=" << v.packets
                          << " bytes=" << v.bytes
                          << " first_ns=" << v.first_ts_ns
                          << " last_ns=" << v.last_ts_ns
                          << "\n";
            }
            shard.table.clear();
        }
    }

private:
    struct Shard {
        std::mutex mtx;
        std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table;
        Shard() { table.reserve(1 << 18); }
    };

    std::vector<Shard> shards_;

    static size_t shard_index(const FlowKey& k) noexcept {
        FlowKeyHash h;
        return h(k) %  shards_.size();
    }
};

