#include <cstdint>
#include <cstring>
#include <unordered_map>
#include <vector>
#include <chrono>
#include <array>
#include <atomic>
#include <iostream>
#include <optional>
#include <algorithm>

// ---------------------------
// Fast flow key
// ---------------------------
struct FlowKey {
    uint8_t  ip_version;   // 4 or 6
    uint8_t  protocol;     // TCP/UDP/ICMP/...
    uint16_t src_port;
    uint16_t dst_port;

    // For IPv4: store in v4[0]
    // For IPv6: store full 16 bytes
    union {
        uint32_t v4[2];     // src, dst
        uint8_t  v6[32];    // src16 + dst16
    } ip{};

    bool operator==(const FlowKey& other) const noexcept {
        if (ip_version != other.ip_version || protocol != other.protocol ||
            src_port != other.src_port || dst_port != other.dst_port) {
            return false;
        }

        if (ip_version == 4) {
            return ip.v4[0] == other.ip.v4[0] && ip.v4[1] == other.ip.v4[1];
        } else {
            return std::memcmp(ip.v6, other.ip.v6, 32) == 0;
        }
    }
};

// ---------------------------
// Hash
// ---------------------------
struct FlowKeyHash {
    static inline uint64_t mix64(uint64_t x) noexcept {
        // SplitMix64-style finalizer
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }

    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t h = 0x123456789abcdef0ULL;
        h ^= mix64((uint64_t)k.ip_version << 56 |
                   (uint64_t)k.protocol   << 48 |
                   (uint64_t)k.src_port   << 32 |
                   (uint64_t)k.dst_port);

        if (k.ip_version == 4) {
            h ^= mix64(((uint64_t)k.ip.v4[0] << 32) | k.ip.v4[1]);
        } else {
            const uint64_t* p = reinterpret_cast<const uint64_t*>(k.ip.v6);
            h ^= mix64(p[0]) ^ mix64(p[1]) ^ mix64(p[2]) ^ mix64(p[3]);
        }
        return static_cast<size_t>(h);
    }
};

// ---------------------------
// Stats
// ---------------------------
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    uint32_t tcp_flags_or = 0;
    uint32_t tcp_flags_and = 0xFF;
};

struct PacketMeta {
    FlowKey key;
    uint32_t payload_len;
    uint32_t tcp_flags;
    uint64_t timestamp_ns;
};

// ---------------------------
// Flow analyser
// ---------------------------
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t initial_capacity = 1 << 20,
                          uint64_t idle_timeout_ns = 30ULL * 1000 * 1000 * 1000)
        : idle_timeout_ns_(idle_timeout_ns)
    {
        flows_.reserve(initial_capacity);
    }

    void process_packet(const PacketMeta& pkt) {
        auto it = flows_.find(pkt.key);
        if (it == flows_.end()) {
            FlowStats s;
            s.packets = 1;
            s.bytes = pkt.payload_len;
            s.first_seen_ns = pkt.timestamp_ns;
            s.last_seen_ns = pkt.timestamp_ns;
            s.tcp_flags_or = pkt.tcp_flags;
            s.tcp_flags_and = pkt.tcp_flags;
            flows_.emplace(pkt.key, s);
            return;
        }

        FlowStats& s = it->second;
        s.packets++;
        s.bytes += pkt.payload_len;
        s.last_seen_ns = pkt.timestamp_ns;
        s.tcp_flags_or |= pkt.tcp_flags;
        s.tcp_flags_and &= pkt.tcp_flags;
    }

    template <typename It>
    void process_batch(It begin, It end) {
        for (auto it = begin; it != end; ++it) {
            process_packet(*it);
        }
    }

    void expire_idle(uint64_t now_ns) {
        for (auto it = flows_.begin(); it != flows_.end(); ) {
            if (now_ns - it->second.last_seen_ns > idle_timeout_ns_) {
                it = flows_.erase(it);
            } else {
                ++it;
            }
        }
    }

    size_t flow_count() const noexcept {
        return flows_.size();
    }

    void print_top_n(size_t n) const {
        std::vector<std::pair<FlowKey, FlowStats>> entries;
        entries.reserve(flows_.size());

        for (const auto& kv : flows_) {
            entries.push_back(kv);
        }

        std::partial_sort(entries.begin(),
                          entries.begin() + std::min(n, entries.size()),
                          entries.end(),
                          [](const auto& a, const auto& b) {
                              return a.second.bytes > b.second.bytes;
                          });

        size_t limit = std::min(n, entries.size());
        for (size_t i = 0; i < limit; ++i) {
            const auto& [key, stats] = entries[i];
            std::cout << "flow=" << format_key(key)
                      << " packets=" << stats.packets
                      << " bytes=" << stats.bytes
                      << " first_ns=" << stats.first_seen_ns
                      << " last_ns=" << stats.last_seen_ns
                      << "\n";
        }
    }

private:
    static std::string format_key(const FlowKey& k) {
        char buf[256];
        if (k.ip_version == 4) {
            uint32_t s = k.ip.v4[0];
            uint32_t d = k.ip.v4[1];
            std::snprintf(buf, sizeof(buf),
                          "IPv4 proto=%u %u.%u.%u.%u:%u -> %u.%u.%u.%u:%u",
                          k.protocol,
                          (s >> 24) & 0xFF, (s >> 16) & 0xFF, (s >> 8) & 0xFF, s & 0xFF, k.src_port,
                          (d >> 24) & 0xFF, (d >> 16) & 0xFF, (d >> 8) & 0xFF, d & 0xFF, k.dst_port);
        } else {
            std::snprintf(buf, sizeof(buf),
                          "IPv6 proto=%u sport=%u dport=%u",
                          k.protocol, k.src_port, k.dst_port);
        }
        return std::string(buf);
    }

    uint64_t idle_timeout_ns_;
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows_;
};

// ---------------------------
// Example usage
// ---------------------------
static uint64_t now_ns() {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
               std::chrono::steady_clock::now().time_since_epoch())
        .count();
}

int main() {
    FlowAnalyzer analyzer(1 << 18);

    // Mock traffic
    std::vector<PacketMeta> packets;
    packets.reserve(1'000'000);

    for (uint32_t i = 0; i < 1'000'000; ++i) {
        FlowKey key{};
        key.ip_version = 4;
        key.protocol = 6; // TCP
        key.src_port = static_cast<uint16_t>(10000 + (i % 1000));
        key.dst_port = 443;
        key.ip.v4[0] = 0x0A000001 + (i % 256); // 10.0.0.1+
        key.ip.v4[1] = 0xC0000201;             // 192.0.2.1

        packets.push_back(PacketMeta{
            key,
            64 + (i % 1400),
            static_cast<uint32_t>(i & 0x1F),
            now_ns()
        });
    }

    analyzer.process_batch(packets.begin(), packets.end());
    analyzer.expire_idle(now_ns());

    std::cout << "Flows: " << analyzer.flow_count() << "\n";
    analyzer.print_top_n(10);

    return 0;
}
