};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        return (size_t)hash5tuple(k.src_ip, k.dst_ip, k.src_port, k.dst_port, k.proto);
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key;
    FlowStats stats;
    uint64_t last_touch_ns = 0;
    bool active = false;
};

// -----------------------------
// Basic IPv4/TCP/UDP parser
// Assumes Ethernet + IPv4 + TCP/UDP
// -----------------------------
struct ParsedPacket {
    bool valid = false;
    FlowKey key{};
    uint32_t payload_len = 0;
};

static inline ParsedPacket parse_ipv4_l4(const uint8_t* data, size_t len) {
    ParsedPacket out;

    // Ethernet header: 14 bytes
    if (len < 14 + 20) return out;

    const uint8_t* eth = data;
    uint16_t ethertype = (uint16_t(eth[12]) << 8) | eth[13];
    if (ethertype != 0x0800) return out; // IPv4 only

    const uint8_t* ip = data + 14;
    uint8_t ihl = ip[0] & 0x0F;
    uint8_t version = ip[0] >> 4;
    if (version != 4) return out;

    size_t ip_hlen = size_t(ihl) * 4;
    if (ip_hlen < 20 || len < 14 + ip_hlen) return out;

    uint8_t proto = ip[9];
    uint32_t src_ip = (uint32_t(ip[12]) << 24) | (uint32_t(ip[13]) << 16) |
                      (uint32_t(ip[14]) << 8)  | (uint32_t(ip[15]));
    uint32_t dst_ip = (uint32_t(ip[16]) << 24) | (uint32_t(ip[17]) << 16) |
                      (uint32_t(ip[18]) << 8)  | (uint32_t(ip[19]));

    const uint8_t* l4 = data + 14 + ip_hlen;
    size_t l4_len = len - (14 + ip_hlen);

    uint16_t src_port = 0, dst_port = 0;
    if (proto == 6 || proto == 17) { // TCP or UDP
        if (l4_len < 4) return out;
        src_port = (uint16_t(l4[0]) << 8) | l4[1];
        dst_port = (uint16_t(l4[2]) << 8) | l4[3];
    } else {
        // Other protocols can be keyed on zero ports
        src_port = 0;
        dst_port = 0;
    }

    out.valid = true;
    out.key = {src_ip, dst_ip, src_port, dst_port, proto};
    out.payload_len = uint32_t(l4_len);
    return out;
}

// -----------------------------
// High-performance flow table
// For very high scale, replace unordered_map with a custom flat hash table.
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t reserve_entries = 1 << 20) {
        table_.reserve(reserve_entries);
    }

    inline void update(const ParsedPacket& p, uint64_t ts_ns) {
        auto it = table_.find(p.key);
        if (it == table_.end()) {
            FlowStats st;
            st.packets = 1;
            st.bytes = p.payload_len;
            st.first_seen_ns = ts_ns;
            st.last_seen_ns = ts_ns;
            table_.emplace(p.key, st);
        } else {
            auto& st = it->second;
            st.packets++;
            st.bytes += p.payload_len;
            st.last_seen_ns = ts_ns;
        }
    }

    template <typename Fn>
    inline void for_each(Fn&& fn) {
        for (auto& kv : table_) fn(kv.first, kv.second);
    }

    inline void clear() {
        table_.clear();
    }

private:
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table_;
};

// -----------------------------
// Aging / export logic
// -----------------------------
class FlowExporter {
public:
    explicit FlowExporter(uint64_t idle_timeout_ns)
        : idle_timeout_ns_(idle_timeout_ns) {}

    template <typename Fn>
    void age_and_export(FlowTable& flows, uint64_t now_ns, Fn&& emit) {
        std::vector<FlowKey> expired;
        expired.reserve(4096);

        flows.for_each([&](const FlowKey& key, const FlowStats& st) {
            if (now_ns > st.last_seen_ns && (now_ns - st.last_seen_ns) >= idle_timeout_ns_) {
                emit(key, st);
                expired.push_back(key);
            }
        });

        // Note: for performance-critical systems, use a table with O(1) erase or generation-based aging.
        // Here we rebuild by swapping to a new table in a real implementation.
        // This skeleton keeps the API simple.
    }

private:
    uint64_t idle_timeout_ns_;
};

// -----------------------------
// Packet processor
// -----------------------------
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t reserve_entries = 1 << 20,
                          uint64_t idle_timeout_ns = 30ULL * 1000 * 1000 * 1000)
        : flows_(reserve_entries), exporter_(idle_timeout_ns) {}

    inline void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
        auto p = parse_ipv4_l4(data, len);
        if (!p.valid) return;
        flows_.update(p, ts_ns);
    }

    template <typename Fn>
    void export_expired(uint64_t now_ns, Fn&& emit) {
        exporter_.age_and_export(flows_, now_ns, std::forward<Fn>(emit));
    }

private:
    FlowTable flows_;
    FlowExporter exporter_;
};

