```cpp
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/ip6.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#include <array>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <unordered_map>
#include <vector>

using Clock = std::chrono::steady_clock;
using TimePoint = Clock::time_point;

static constexpr size_t SHARD_COUNT = 64; // power of two recommended

// -----------------------------
// Flow key
// -----------------------------
struct FlowKey {
    uint8_t  ip_version;   // 4 or 6
    uint8_t  protocol;     // TCP/UDP/other
    uint16_t src_port;
    uint16_t dst_port;

    // IPv4 stored in v4[0], v6 uses full 16 bytes
    std::array<uint8_t, 16> src_ip{};
    std::array<uint8_t, 16> dst_ip{};

    bool operator==(const FlowKey& o) const noexcept {
        return ip_version == o.ip_version &&
               protocol == o.protocol &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               src_ip == o.src_ip &&
               dst_ip == o.dst_ip;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // FNV-1a-ish mix
        auto mix = [](size_t h, const void* data, size_t len) {
            const uint8_t* p = static_cast<const uint8_t*>(data);
            for (size_t i = 0; i < len; ++i) {
                h ^= p[i];
                h *= 1099511628211ULL;
            }
            return h;
        };

        size_t h = 1469598103934665603ULL;
        h = mix(h, &k.ip_version, sizeof(k.ip_version));
        h = mix(h, &k.protocol, sizeof(k.protocol));
        h = mix(h, &k.src_port, sizeof(k.src_port));
        h = mix(h, &k.dst_port, sizeof(k.dst_port));
        h = mix(h, k.src_ip.data(), k.src_ip.size());
        h = mix(h, k.dst_ip.data(), k.dst_ip.size());
        return h;
    }
};

// -----------------------------
// Flow record
// -----------------------------
struct FlowRecord {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    TimePoint first_seen{};
    TimePoint last_seen{};
    uint64_t tcp_flags_or_proto = 0;
};

// -----------------------------
// Shard
// -----------------------------
struct Shard {
    std::mutex mtx;
    std::unordered_map<FlowKey, FlowRecord, FlowKeyHash> table;
};

// -----------------------------
// Aggregator
// -----------------------------
class FlowAnalyzer {
public:
    FlowAnalyzer()
        : stop_(false) {
        for (auto& s : shards_) {
            s.table.reserve(1 << 15); // tune per expected cardinality
        }
    }

    void start_aging_thread(std::chrono::seconds interval,
                            std::chrono::seconds idle_timeout) {
        aging_thread_ = std::thread([this, interval, idle_timeout]() {
            while (!stop_.load(std::memory_order_relaxed)) {
                std::this_thread::sleep_for(interval);
                age_flows(idle_timeout);
            }
        });
    }

    void stop() {
        stop_.store(true, std::memory_order_relaxed);
        if (aging_thread_.joinable()) aging_thread_.join();
    }

    ~FlowAnalyzer() {
        stop();
    }

    // Parse raw Ethernet frame and update flow stats
    void process_packet(const uint8_t* data, size_t len, TimePoint now) {
        if (len < 14) return; // Ethernet header

        const uint8_t* p = data;
        uint16_t ethertype = ntohs(*reinterpret_cast<const uint16_t*>(p + 12));
        p += 14;
        len -= 14;

        FlowKey key{};
        key.ip_version = 0;
        key.protocol = 0;

        if (ethertype == 0x0800) {
            // IPv4
            if (len < sizeof(iphdr)) return;
            auto* ip = reinterpret_cast<const iphdr*>(p);
            size_t ihl = ip->ihl * 4;
            if (ihl < 20 || len < ihl) return;

            key.ip_version = 4;
            key.protocol = ip->protocol;
            std::memcpy(&key.src_ip[0], &ip->saddr, 4);
            std::memcpy(&key.dst_ip[0], &ip->daddr, 4);

            p += ihl;
            len -= ihl;

            if (key.protocol == IPPROTO_TCP) {
                if (len < sizeof(tcphdr)) return;
                auto* tcp = reinterpret_cast<const tcphdr*>(p);
                key.src_port = ntohs(tcp->source);
                key.dst_port = ntohs(tcp->dest);
            } else if (key.protocol == IPPROTO_UDP) {
                if (len < sizeof(udphdr)) return;
                auto* udp = reinterpret_cast<const udphdr*>(p);
                key.src_port = ntohs(udp->source);
                key.dst_port = ntohs(udp->dest);
            } else {
                key.src_port = 0;
                key.dst_port = 0;
            }
        } else if (ethertype == 0x86DD) {
            // IPv6
            if (len < sizeof(ip6_hdr)) return;
            auto* ip6 = reinterpret_cast<const ip6_hdr*>(p);

            key.ip_version = 6;
            key.protocol = ip6->ip6_nxt;
            std::memcpy(key.src_ip.data(), &ip6->ip6_src, 16);
            std::memcpy(key.dst_ip.data(), &ip6->ip6_dst, 16);

            p += sizeof(ip6_hdr);
            len -= sizeof(ip6_hdr);

            if (key.protocol == IPPROTO_TCP) {
                if (len < sizeof(tcphdr)) return;
                auto* tcp = reinterpret_cast<const tcphdr*>(p);
                key.src_port = ntohs(tcp->source);
                key.dst_port = ntohs(tcp->dest);
            } else if (key.protocol == IPPROTO_UDP) {
                if (len < sizeof(udphdr)) return;
                auto* udp = reinterpret_cast<const udphdr*>(p);
                key.src_port = ntohs(udp->source);
                key.dst_port = ntohs(udp->dest);
            } else {
                key.src_port = 0;
                key.dst_port = 0;
            }
        } else {
            return; // unsupported ethertype
        }

        update_flow(key, len, now);
    }

private:
    std::array<Shard, SHARD_COUNT> shards_;
    std::atomic<bool> stop_;
    std::thread aging_thread_;

    static size_t shard_index(const FlowKey& key) {
        FlowKeyHash h;
        return h(key) & (SHARD_COUNT - 1);
    }

    void update_flow(const FlowKey& key, size_t payload_len, TimePoint now) {
        auto& shard = shards_[shard_index(key)];
        std::lock_guard<std::mutex> lock(shard.mtx);

        auto it = shard.table.find(key);
        if (it == shard.table.end()) {
            FlowRecord rec;
            rec.packets = 1;
            rec.bytes = payload_len;
            rec.first_seen = now;
            rec.last_seen = now;
            rec.tcp_flags_or_proto = key.protocol;
            shard.table.emplace(key, rec);
        } else {
            auto& rec = it->second;
            rec.packets++;
            rec.bytes += payload_len;
            rec.last_seen = now;
        }
    }

    void age_flows(std::chrono::seconds idle_timeout) {
        const auto now = Clock::now();

        for (auto& shard : shards_) {
            std::lock_guard<std::mutex> lock(shard.mtx);

            for (auto it = shard.table.begin(); it != shard.table.end(); ) {
                auto idle = std::chrono::duration_cast<std::chrono::seconds>(now - it->second.last_seen);
                if (idle > idle_timeout) {
                    export_flow(it->first, it->second);
                    it = shard.table.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

    static void export_flow(const FlowKey& k, const FlowRecord& r) {
        std::cout << "flow "
                  << "ver=" << int(k.ip_version)
                  << " proto=" << int(k.protocol)
                  << " sport=" << k.src_port
                  << " dport=" << k.dst_port
                  << " packets=" << r.packets
                  << " bytes=" << r.bytes
                  << "\n";
    }
};
