// netflow_analyzer.cpp
#include <array>
#include <atomic>
#include <bit>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iomanip>
#include <iostream>
#include <optional>
#include <shared_mutex>
#include <string>
#include <thread>
#include <unordered_map>
#include <vector>

#if defined(__GNUG__) || defined(__clang__)
#define FORCE_INLINE inline __attribute__((always_inline))
#else
#define FORCE_INLINE inline
#endif

using Clock = std::chrono::steady_clock;
using TimePoint = Clock::time_point;
using Nanoseconds = std::chrono::nanoseconds;

// ------------------------------
// Fast hashing utilities
// ------------------------------

static FORCE_INLINE uint64_t mix64(uint64_t x) {
    // SplitMix64 finalizer
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static FORCE_INLINE uint64_t hash_bytes(const void* data, size_t len, uint64_t seed = 0) {
    const uint8_t* p = static_cast<const uint8_t*>(data);
    uint64_t h = mix64(seed ^ len);

    while (len >= 8) {
        uint64_t v;
        std::memcpy(&v, p, sizeof(v));
        h ^= mix64(v);
        h = std::rotl(h, 27) * 5 + 0x52dce729;
        p += 8;
        len -= 8;
    }

    if (len) {
        uint64_t tail = 0;
        std::memcpy(&tail, p, len);
        h ^= mix64(tail);
    }

    return mix64(h);
}

// ------------------------------
// Flow key
// ------------------------------

enum class IpVersion : uint8_t {
    IPv4 = 4,
    IPv6 = 6
};

struct FlowKey {
    IpVersion ip_version{};
    uint8_t protocol{}; // e.g. TCP=6, UDP=17
    uint16_t src_port{};
    uint16_t dst_port{};

    // Store IPv4 in low 32 bits of v6 fields.
    std::array<uint8_t, 16> src_ip{};
    std::array<uint8_t, 16> dst_ip{};

    friend bool operator==(const FlowKey& a, const FlowKey& b) noexcept {
        return a.ip_version == b.ip_version &&
               a.protocol == b.protocol &&
               a.src_port == b.src_port &&
               a.dst_port == b.dst_port &&
               a.src_ip == b.src_ip &&
               a.dst_ip == b.dst_ip;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t h = 0xcbf29ce484222325ULL;
        h ^= static_cast<uint64_t>(k.ip_version); h *= 0x100000001b3ULL;
        h ^= static_cast<uint64_t>(k.protocol);   h *= 0x100000001b3ULL;
        h ^= static_cast<uint64_t>(k.src_port);   h *= 0x100000001b3ULL;
        h ^= static_cast<uint64_t>(k.dst_port);   h *= 0x100000001b3ULL;
        h ^= hash_bytes(k.src_ip.data(), k.src_ip.size(), h);
        h ^= hash_bytes(k.dst_ip.data(), k.dst_ip.size(), h);
        return static_cast<size_t>(mix64(h));
    }
};

// ------------------------------
// Packet view (decoded metadata)
// ------------------------------

struct PacketView {
    FlowKey key;
    uint32_t packet_len_bytes{};
    TimePoint timestamp{};
};

// ------------------------------
// Flow statistics
// ------------------------------

struct FlowStats {
    uint64_t packets{0};
    uint64_t bytes{0};
    TimePoint first_seen{};
    TimePoint last_seen{};
};

static FORCE_INLINE void update_flow(FlowStats& s, const PacketView& p) noexcept {
    if (s.packets == 0) {
        s.first_seen = p.timestamp;
    }
    s.packets += 1;
    s.bytes += p.packet_len_bytes;
    s.last_seen = p.timestamp;
}

// ------------------------------
// Sharded flow table
// ------------------------------

class ShardedFlowTable {
public:
    explicit ShardedFlowTable(size_t shard_count = std::thread::hardware_concurrency())
        : shards_(shard_count ? shard_count : 1) {}

    void ingest(const PacketView& pkt) {
        auto& shard = shard_for(pkt.key);
        shard.ingest(pkt);
    }

    // Expire flows older than cutoff. Invoke callback for exported/removed flows.
    template <typename Fn>
    void expire(TimePoint cutoff, Fn&& on_expire) {
        for (auto& shard : shards_) {
            shard.expire(cutoff, on_expire);
        }
    }

    size_t shard_count() const noexcept { return shards_.size(); }

private:
    struct Shard {
        std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table;
        std::shared_mutex mu;

        void ingest(const PacketView& pkt) {
            std::unique_lock lock(mu);
            auto [it, inserted] = table.try_emplace(pkt.key);
            update_flow(it->second, pkt);
        }

        template <typename Fn>
        void expire(TimePoint cutoff, Fn&& on_expire) {
            std::unique_lock lock(mu);
            for (auto it = table.begin(); it != table.end();) {
                if (it->second.last_seen < cutoff) {
                    on_expire(it->first, it->second);
                    it = table.erase(it);
                } else {
                    ++it;
                }
            }
        }
    };

    Shard& shard_for(const FlowKey& key) {
        size_t idx = FlowKeyHash{}(key) % shards_.size();
        return shards_[idx];
    }

    std::vector<Shard> shards_;
};

