class PacketParser {
public:
    // Returns true if parsed successfully and fills key + payload_len
    static bool parse_ipv4_tcp_udp(const PacketView& pkt, FlowKey& out_key, uint32_t& out_l3_l4_bytes) noexcept {
        if (pkt.len < sizeof(EthernetHeader)) return false;

        const auto* eth = reinterpret_cast<const EthernetHeader*>(pkt.data);
        const uint16_t ethertype = ntoh16(eth->ethertype);

        if (ethertype != 0x0800) { // IPv4 only for this skeleton
            return false;
        }

        size_t off = sizeof(EthernetHeader);
        if (pkt.len < off + sizeof(IPv4Header)) return false;

        const auto* ip = reinterpret_cast<const IPv4Header*>(pkt.data + off);
        const uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
        const uint8_t version = (ip->ver_ihl >> 4);

        if (version != 4 || ihl < 20) return false;
        if (pkt.len < off + ihl) return false;

        const uint8_t proto = ip->protocol;
        const uint32_t src_ip = ntoh32(ip->src_ip);
        const uint32_t dst_ip = ntoh32(ip->dst_ip);

        off += ihl;

        uint16_t src_port = 0, dst_port = 0;

        if (proto == 6) { // TCP
            if (pkt.len < off + sizeof(TCPHeader)) return false;
            const auto* tcp = reinterpret_cast<const TCPHeader*>(pkt.data + off);
            src_port = ntoh16(tcp->src_port);
            dst_port = ntoh16(tcp->dst_port);
        } else if (proto == 17) { // UDP
            if (pkt.len < off + sizeof(UDPHeader)) return false;
            const auto* udp = reinterpret_cast<const UDPHeader*>(pkt.data + off);
            src_port = ntoh16(udp->src_port);
            dst_port = ntoh16(udp->dst_port);
        } else {
            return false;
        }

        out_key = FlowKey{src_ip, dst_ip, src_port, dst_port, proto};
        out_l3_l4_bytes = static_cast<uint32_t>(pkt.len - sizeof(EthernetHeader));
        return true;
    }
};

// -----------------------------
// Sharded flow table
// -----------------------------

class FlowTable {
public:
    using ExportFn = std::function<void(const FlowKey&, const FlowStats&)>;

    explicit FlowTable(size_t shards = 64,
                       uint64_t inactive_timeout_ns = 30ULL * 1000 * 1000 * 1000,
                       ExportFn exporter = nullptr)
        : shards_(shards),
          inactive_timeout_ns_(inactive_timeout_ns),
          exporter_(std::move(exporter)) {
        if (shards_ == 0) shards_ = 64;
        shard_tables_.resize(shards_);
    }

    void ingest(const PacketView& pkt) {
        FlowKey key{};
        uint32_t payload_bytes = 0;

        if (!PacketParser::parse_ipv4_tcp_udp(pkt, key, payload_bytes))
            return;

        const size_t idx = FlowKeyHash{}(key) % shards_;
        auto& shard = shard_tables_[idx];

        std::lock_guard<std::mutex> lock(shard.mtx);
        auto& stat = shard.table[key];

        if (stat.packets == 0) {
            stat.first_seen_ns = pkt.timestamp_ns;
        }
        stat.last_seen_ns = pkt.timestamp_ns;
        stat.packets += 1;
        stat.bytes += payload_bytes;
    }

    void expire() {
        const uint64_t cutoff = now_ns();

        for (auto& shard : shard_tables_) {
            std::lock_guard<std::mutex> lock(shard.mtx);

            for (auto it = shard.table.begin(); it != shard.table.end(); ) {
                const FlowStats& s = it->second;
                if (cutoff > s.last_seen_ns && (cutoff - s.last_seen_ns) >= inactive_timeout_ns_) {
                    if (exporter_) exporter_(it->first, it->second);
                    it = shard.table.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

    size_t approximate_size() const {
        size_t total = 0;
        for (const auto& shard : shard_tables_) {
            std::lock_guard<std::mutex> lock(shard.mtx);
            total += shard.table.size();
        }
        return total;
    }

private:
    struct Shard {
        mutable std::mutex mtx;
        std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table;
    };

    size_t shards_;
    uint64_t inactive_timeout_ns_;
    ExportFn exporter_;
    std::vector<Shard> shard_tables_;
};

