enum class L4Proto : uint8_t {
    OTHER = 0,
    TCP   = 6,
    UDP   = 17
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    // Canonicalize bidirectional flows if desired:
    // lower tuple first, or keep direction-specific depending on use case.
    void canonicalize() {
        const bool swap_needed =
            (src_ip > dst_ip) ||
            (src_ip == dst_ip && src_port > dst_port);

        if (swap_needed) {
            std::swap(src_ip, dst_ip);
            std::swap(src_port, dst_port);
        }
    }

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes   = 0;
    uint64_t first_ts_ns = 0;
    uint64_t last_ts_ns  = 0;
    uint32_t tcp_flags   = 0;
};

// Fast 64-bit hash (splitmix64-based mixer)
static inline uint64_t mix64(uint64_t x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t h = 0;
        h ^= mix64(k.src_ip);
        h ^= mix64((uint64_t(k.dst_ip) << 1) ^ uint64_t(k.proto));
        h ^= mix64((uint64_t(k.src_port) << 16) | k.dst_port);
        return static_cast<size_t>(mix64(h));
    }
};

// -----------------------------
// Simple open-addressing hash table
// -----------------------------

class FlowTable {
public:
    struct Entry {
        bool used = false;
        FlowKey key{};
        FlowStats stats{};
    };

    explicit FlowTable(size_t capacity_pow2 = 1 << 20)
        : cap_(next_pow2(capacity_pow2)),
          mask_(cap_ - 1),
          entries_(cap_) {}

    // Returns pointer to updated stats entry, or nullptr on full table
    FlowStats* upsert(const FlowKey& key, uint64_t ts_ns, size_t pkt_bytes, uint8_t tcp_flags = 0) {
        size_t idx = static_cast<size_t>(FlowKeyHash{}(key)) & mask_;

        for (size_t probe = 0; probe < cap_; ++probe) {
            Entry& e = entries_[idx];

            if (!e.used) {
                e.used = true;
                e.key = key;
                e.stats.first_ts_ns = ts_ns;
                e.stats.last_ts_ns = ts_ns;
                e.stats.packets = 1;
                e.stats.bytes = pkt_bytes;
                e.stats.tcp_flags = tcp_flags;
                return &e.stats;
            }

            if (e.key == key) {
                e.stats.packets++;
                e.stats.bytes += pkt_bytes;
                e.stats.last_ts_ns = ts_ns;
                e.stats.tcp_flags |= tcp_flags;
                return &e.stats;
            }

            idx = (idx + 1) & mask_;
        }
        return nullptr;
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (auto& e : entries_) {
            if (e.used) fn(e.key, e.stats);
        }
    }

    void clear() {
        for (auto& e : entries_) e.used = false;
    }

private:
    static size_t next_pow2(size_t x) {
        size_t p = 1;
        while (p < x) p <<= 1;
        return p;
    }

    size_t cap_;
    size_t mask_;
    std::vector<Entry> entries_;
};

// -----------------------------
// Timing wheel for expirations
// -----------------------------

class TimingWheel {
public:
    explicit TimingWheel(size_t slots = 4096)
        : slots_(slots), buckets_(slots) {}

    void schedule(uint64_t expiry_ns, uint64_t flow_id) {
        buckets_[slot(expiry_ns)].push_back({expiry_ns, flow_id});
    }

    template <typename Fn>
    void expire(uint64_t now_ns, Fn&& on_expire) {
        size_t s = slot(now_ns);
        auto& b = buckets_[s];
        size_t write = 0;
        for (size_t i = 0; i < b.size(); ++i) {
            if (b[i].expiry_ns <= now_ns) {
                on_expire(b[i].flow_id);
            } else {
                b[write++] = b[i];
            }
        }
        b.resize(write);
    }

private:
    struct Item {
        uint64_t expiry_ns;
        uint64_t flow_id;
    };

    size_t slot(uint64_t ns) const {
        return static_cast<size_t>(ns / tick_ns_) & (slots_ - 1);
    }

    size_t slots_;
    uint64_t tick_ns_ = 1'000'000ULL; // 1 ms
    std::vector<std::vector<Item>> buckets_;
};

// -----------------------------
// Packet parsing
// -----------------------------

struct ParsedPacket {
    FlowKey key{};
    uint32_t packet_len = 0;
    uint8_t tcp_flags = 0;
    bool valid = false;
};

static inline ParsedPacket parse_packet(const uint8_t* data, size_t len) {
    ParsedPacket out{};
    if (unlikely(len < sizeof(EthernetHeader))) return out;

    const auto* eth = reinterpret_cast<const EthernetHeader*>(data);
    uint16_t ethertype = ntoh16(eth->ethertype);

    if (ethertype != 0x0800) { // IPv4 only in this sample
        return out;
    }

    size_t off = sizeof(EthernetHeader);
    if (unlikely(len < off + sizeof(IPv4Header))) return out;

    const auto* ip = reinterpret_cast<const IPv4Header*>(data + off);
    uint8_t ihl = ip->ver_ihl & 0x0F;
    size_t ip_hlen = size_t(ihl) * 4;
    if (unlikely(ihl < 5 || len < off + ip_hlen)) return out;

    uint32_t src_ip = ntoh32(ip->src);
    uint32_t dst_ip = ntoh32(ip->dst);
    uint8_t proto = ip->protocol;

    out.key.src_ip = src_ip;
    out.key.dst_ip = dst_ip;
    out.key.proto = proto;

    off += ip_hlen;

    if (proto == uint8_t(L4Proto::TCP)) {
        if (unlikely(len < off + sizeof(TCPHeader))) return out;
        const auto* tcp = reinterpret_cast<const TCPHeader*>(data + off);
        out.key.src_port = ntoh16(tcp->src_port);
        out.key.dst_port = ntoh16(tcp->dst_port);
        out.tcp_flags = tcp->flags;
        out.valid = true;
    } else if (proto == uint8_t(L4Proto::UDP)) {
        if (unlikely(len < off + sizeof(UDPHeader))) return out;
        const auto* udp = reinterpret_cast<const UDPHeader*>(data + off);
        out.key.src_port = ntoh16(udp->src_port);
        out.key.dst_port = ntoh16(udp->dst_port);
        out.valid = true;
    } else {
        out.key.src_port = 0;
        out.key.dst_port = 0;
        out.valid = true;
    }

    out.packet_len = static_cast<uint32_t>(len);
    return out;
}

// -----------------------------
// Analyzer
// -----------------------------

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity = 1 << 20)
        : table_(table_capacity) {}

    void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
        ParsedPacket p = parse_packet(data, len);
        if (unlikely(!p.valid)) return;

        // Canonicalize if you want bidirectional flow aggregation.
        p.key.canonicalize();

        auto* stats = table_.upsert(p.key, ts_ns, p.packet_len, p.tcp_flags);
        if (unlikely(!stats)) {
            // Table full: optional strategy:
            // - evict oldest
            // - drop
            // - spill to slower store
            dropped_++;
        }
    }

    void print_summary() {
        table_.for_each([](const FlowKey& k, const FlowStats& s) {
            std::cout
                << ip_to_string(k.src_ip) << ":" << k.src_port
                << " -> "
                << ip_to_string(k.dst_ip) << ":" << k.dst_port
                << " proto=" << int(k.proto)
                << " packets=" << s.packets
                << " bytes=" << s.bytes
                << " first_ns=" << s.first_ts_ns
                << " last_ns=" << s.last_ts_ns
                << "\n";
        });
    }

    uint64_t dropped() const { return dropped_; }

private:
    static std::string ip_to_string(uint32_t ip) {
        uint8_t b1 = (ip >> 24) & 0xFF;
        uint8_t b2 = (ip >> 16) & 0xFF;
        uint8_t b3 = (ip >> 8) & 0xFF;
        uint8_t b4 = ip & 0xFF;
        return std::to_string(b1) + "." + std::to_string(b2) + "." +
               std::to_string(b3) + "." + std::to_string(b4);
    }

    FlowTable table_;
    uint64_t dropped_ = 0;
};

// -----------------------------
// Example usage / test harness
// -----------------------------

int main() {
    FlowAnalyzer analyzer;

    // Dummy packet buffer would normally come from NIC / pcap
    std::vector<uint8_t> packet(14 + 20 + 20); // eth + ipv4 + tcp

    auto* eth = reinterpret_cast<EthernetHeader*>(packet.data());
    eth->ethertype = htons(0x0800);

    auto* ip = reinterpret_cast<IPv4Header*>(packet.data() + 14);
    ip->ver_ihl = 0x45;
    ip->protocol = 6;
    ip->src = htonl(0x0A000001); // 10.0.0.1
    ip->dst = htonl(0x0A000002); // 10.0.0.2

    auto* tcp = reinterpret_cast<TCPHeader*>(packet.data() + 34);
    tcp->src_port = htons(12345);
    tcp->dst_port = htons(443);
    tcp->flags = 0x18; // PSH+ACK

    uint64_t now = std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count();

    analyzer.process_packet(packet.data(), packet.size(), now);
    analyzer.process_packet(packet.data(), packet.size(), now + 1000);

    analyzer.print_summary();
    std::cerr << "dropped=" << analyzer.dropped() << "\n";
    return 0;
}
