## Rust implementation

```rust
use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::net::Ipv4Addr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const FLUSH_INTERVAL: Duration = Duration::from_secs(1);

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
#[repr(C)]
pub struct FlowKey {
    pub src_ip: u32,
    pub dst_ip: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub _pad: u8,
}

#[derive(Clone, Copy, Debug, Default)]
#[repr(C)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen_ns: u64,
    pub last_seen_ns: u64,
}

#[derive(Default)]
struct FastHasher(u64);

impl Hasher for FastHasher {
    #[inline]
    fn finish(&self) -> u64 {
        self.0
    }

    #[inline]
    fn write(&mut self, bytes: &[u8]) {
        // Simple fast non-cryptographic hash.
        // For production, consider xxHash or aSIMD-friendly hasher.
        let mut hash: u64 = 0xcbf29ce484222325;
        for &b in bytes {
            hash ^= b as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
        self.0 = hash;
    }

    #[inline]
    fn write_u64(&mut self, i: u64) {
        self.0 = i.wrapping_mul(0x9e3779b185ebca87);
    }

    #[inline]
    fn write_u32(&mut self, i: u32) {
        self.write_u64(i as u64);
    }

    #[inline]
    fn write_u16(&mut self, i: u16) {
        self.write_u64(i as u64);
    }

    #[inline]
    fn write_u8(&mut self, i: u8) {
        self.write_u64(i as u64);
    }
}

type FastBuildHasher = BuildHasherDefault<FastHasher>;
type FlowMap = HashMap<FlowKey, FlowStats, FastBuildHasher>;

pub struct FlowAnalyzer {
    flows: Mutex<FlowMap>,
}

impl FlowAnalyzer {
    pub fn new(expected_flows: usize) -> Self {
        let mut map: FlowMap = HashMap::with_capacity_and_hasher(expected_flows, FastBuildHasher::default());
        // pre-allocate through inner mutex-protected map
        Self {
            flows: Mutex::new(map),
        }
    }

    #[inline]
    pub fn process_packet(
        &self,
        src_ip: Ipv4Addr,
        dst_ip: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
        packet_len: usize,
        timestamp_ns: u64,
    ) {
        let key = FlowKey {
            src_ip: u32::from(src_ip),
            dst_ip: u32::from(dst_ip),
            src_port,
            dst_port,
            proto,
            _pad: 0,
        };

        let mut flows = self.flows.lock().unwrap();
        let entry = flows.entry(key).or_insert_with(|| FlowStats {
            first_seen_ns: timestamp_ns,
            last_seen_ns: timestamp_ns,
            ..Default::default()
        });

        entry.packets = entry.packets.wrapping_add(1);
        entry.bytes = entry.bytes.wrapping_add(packet_len as u64);
        entry.last_seen_ns = timestamp_ns;
    }

    pub fn process_batch(&self, batch: &[PacketView]) {
        let mut flows = self.flows.lock().unwrap();
        for pkt in batch {
            let key = FlowKey {
                src_ip: pkt.src_ip,
                dst_ip: pkt.dst_ip,
                src_port: pkt.src_port,
                dst_port: pkt.dst_port,
                proto: pkt.proto,
                _pad: 0,
            };

            let entry = flows.entry(key).or_insert_with(|| FlowStats {
                first_seen_ns: pkt.timestamp_ns,
                last_seen_ns: pkt.timestamp_ns,
                ..Default::default()
            });

            entry.packets = entry.packets.wrapping_add(1);
            entry.bytes = entry.bytes.wrapping_add(pkt.len as u64);
            entry.last_seen_ns = pkt.timestamp_ns;
        }
    }

    pub fn age_out_and_snapshot(&self, now_ns: u64) -> Vec<(FlowKey, FlowStats)> {
        let mut flows = self.flows.lock().unwrap();
        let mut expired = Vec::new();

        flows.retain(|k, v| {
            let idle_ns = now_ns.saturating_sub(v.last_seen_ns);
            if idle_ns > FLOW_IDLE_TIMEOUT.as_nanos() as u64 {
                expired.push((*k, *v));
                false
            } else {
                true
            }
        });

        expired
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        let flows = self.flows.lock().unwrap();
        flows.iter().map(|(k, v)| (*k, *v)).collect()
    }
}

#[derive(Clone, Copy, Debug)]
pub struct PacketView {
    pub src_ip: u32,
    pub dst_ip: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub len: usize,
    pub timestamp_ns: u64,
}
