## Rust code: high-throughput flow analyzer

```rust
use std::collections::hash_map::{Entry, HashMap};
use std::hash::{BuildHasherDefault, Hasher};
use std::io::{self, BufRead};
use std::net::{Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

const FLOW_TIMEOUT: Duration = Duration::from_secs(30);
const REPORT_INTERVAL: Duration = Duration::from_secs(1);

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
enum IpKey {
    V4(u32),
    V6([u8; 16]),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct FlowKey {
    src: IpKey,
    dst: IpKey,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: u64) -> Self {
        Self {
            packets: 1,
            bytes,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: u64) {
        self.packets += 1;
        self.bytes += bytes;
        self.last_seen = now;
    }
}

/// A faster hasher than the standard SipHash for flow-key aggregation.
/// In production, consider `ahash` or `fxhash` depending on your threat model.
#[derive(Default)]
struct FastHasher(u64);

impl Hasher for FastHasher {
    fn write(&mut self, bytes: &[u8]) {
        // FNV-1a 64-bit, simple and fast for trusted internal flow keys
        let mut hash = if self.0 == 0 {
            0xcbf29ce484222325
        } else {
            self.0
        };
        for &b in bytes {
            hash ^= b as u64;
            hash = hash.wrapping_mul(0x100000001b3);
        }
        self.0 = hash;
    }

    fn finish(&self) -> u64 {
        self.0
    }
}

type FastBuildHasher = BuildHasherDefault<FastHasher>;
type FlowTable = HashMap<FlowKey, FlowStats, FastBuildHasher>;

#[derive(Debug)]
struct ParsedRecord {
    src: IpKey,
    dst: IpKey,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    bytes: u64,
}

fn ipv4_to_u32(addr: Ipv4Addr) -> u32 {
    u32::from_be_bytes(addr.octets())
}

fn ipv6_to_bytes(addr: Ipv6Addr) -> [u8; 16] {
    addr.octets()
}

fn parse_line(line: &str) -> Option<ParsedRecord> {
    // Expected format:
    // src_ip,dst_ip,src_port,dst_port,proto,bytes
    // Example:
    // 192.0.2.1,198.51.100.2,12345,443,6,1500
    let mut parts = line.trim().split(',');

    let src_ip = parts.next()?;
    let dst_ip = parts.next()?;
    let src_port = parts.next()?.parse::<u16>().ok()?;
    let dst_port = parts.next()?.parse::<u16>().ok()?;
    let proto = parts.next()?.parse::<u8>().ok()?;
    let bytes = parts.next()?.parse::<u64>().ok()?;

    let src = if let Ok(v4) = src_ip.parse::<Ipv4Addr>() {
        IpKey::V4(ipv4_to_u32(v4))
    } else if let Ok(v6) = src_ip.parse::<Ipv6Addr>() {
        IpKey::V6(ipv6_to_bytes(v6))
    } else {
        return None;
    };

    let dst = if let Ok(v4) = dst_ip.parse::<Ipv4Addr>() {
        IpKey::V4(ipv4_to_u32(v4))
    } else if let Ok(v6) = dst_ip.parse::<Ipv6Addr>() {
        IpKey::V6(ipv6_to_bytes(v6))
    } else {
        return None;
    };

    Some(ParsedRecord {
        src,
        dst,
        src_port,
        dst_port,
        proto,
        bytes,
    })
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let reader = stdin.lock().lines();

    let mut flows: FlowTable = HashMap::default();
    let mut last_report = Instant::now();
    let mut last_gc = Instant::now();

    for line in reader {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };

        let now = Instant::now();

        if let Some(rec) = parse_line(&line) {
            let key = FlowKey {
                src: rec.src,
                dst: rec.dst,
                src_port: rec.src_port,
                dst_port: rec.dst_port,
                proto: rec.proto,
            };

            match flows.entry(key) {
                Entry::Occupied(mut e) => {
                    e.get_mut().update(now, rec.bytes);
                }
                Entry::Vacant(e) => {
                    e.insert(FlowStats::new(now, rec.bytes));
                }
            }
        }

        if now.duration_since(last_report) >= REPORT_INTERVAL {
            report_top_flows(&flows, 10);
            last_report = now;
        }

        if now.duration_since(last_gc) >= FLOW_TIMEOUT {
            garbage_collect(&mut flows, now);
            last_gc = now;
        }
    }

    // Final flush
    report_top_flows(&flows, 10);
    Ok(())
}

fn garbage_collect(flows: &mut FlowTable, now: Instant) {
    flows.retain(|_, stats| now.duration_since(stats.last_seen) <= FLOW_TIMEOUT);
}

fn report_top_flows(flows: &FlowTable, n: usize) {
    let mut top: Vec<_> = flows.iter().collect();
    top.sort_unstable_by(|a, b| b.1.bytes.cmp(&a.1.bytes));

    println!("=== Top {} flows ===", n);
    for (i, (k, s)) in top.into_iter().take(n).enumerate() {
        println!(
            "#{:02} {:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={} age={:?}",
            i + 1,
            k.src,
            k.src_port,
            k.dst,
            k.dst_port,
            k.proto,
            s.packets,
            s.bytes,
            s.last_seen.duration_since(s.first_seen)
        );
    }
}
```

