#include <unistd.h>

#include <atomic>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <optional>
#include <string>
#include <thread>
#include <vector>
#include <unordered_map>
#include <shared_mutex>
#include <functional>

// -----------------------------
// Configuration
// -----------------------------
static constexpr size_t NUM_SHARDS = 64;               // Power of 2
static constexpr size_t FLOW_IDLE_TIMEOUT_MS = 60'000; // 60s idle timeout
static constexpr size_t FLOW_EXPIRY_SWEEP_MS = 1'000;  // Sweep once per second
static constexpr size_t TPACKET_BLOCK_SIZE = 1 << 20;  // 1 MiB
static constexpr size_t TPACKET_BLOCK_NR   = 64;       // Total ring size = 64 MiB
static constexpr size_t TPACKET_FRAME_SIZE  = 2048;    // Enough for typical MTU
static constexpr size_t TPACKET_FRAME_NR    = (TPACKET_BLOCK_SIZE * TPACKET_BLOCK_NR) / TPACKET_FRAME_SIZE;

static_assert((NUM_SHARDS & (NUM_SHARDS - 1)) == 0, "NUM_SHARDS must be power of 2");

// -----------------------------
// Utility
// -----------------------------
static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

static inline uint64_t now_ms() {
    return now_ns() / 1'000'000;
}

static inline uint64_t hash64(uint64_t x) {
    // splitmix64 finalizer
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

// -----------------------------
// Flow key and counters
// -----------------------------
#pragma pack(push, 1)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};
#pragma pack(pop)

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t h = 0;
        h ^= hash64(k.src_ip);
        h ^= hash64((uint64_t)k.dst_ip << 1);
        h ^= hash64((uint64_t)k.src_port << 16);
        h ^= hash64((uint64_t)k.dst_port << 32);
        h ^= hash64((uint64_t)k.proto << 48);
        return (size_t)h;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ms = 0;
    uint64_t last_seen_ms = 0;
};

struct alignas(64) FlowRecord {
    FlowStats stats;
};

// -----------------------------
// Flow shard
// -----------------------------
class FlowShard {
public:
    void update(const FlowKey& key, uint32_t bytes, uint64_t ts_ms) {
        std::unique_lock lock(mutex_);
        auto& rec = table_[key];
        if (rec.stats.packets == 0) {
            rec.stats.first_seen_ms = ts_ms;
        }
        rec.stats.packets++;
        rec.stats.bytes += bytes;
        rec.stats.last_seen_ms = ts_ms;
    }

    void sweep_expired(uint64_t now_ms_) {
        std::unique_lock lock(mutex_);
        for (auto it = table_.begin(); it != table_.end(); ) {
            if (now_ms_ - it->second.stats.last_seen_ms > FLOW_IDLE_TIMEOUT_MS) {
                // In production, export here before erasing.
                // Example: write to Kafka, log, Prometheus, etc.
                // std::cout << "Expired flow: packets=" << it->second.stats.packets
                //           << " bytes=" << it->second.stats.bytes << "\n";
                it = table_.erase(it);
            } else {
                ++it;
            }
        }
    }

private:
    std::unordered_map<FlowKey, FlowRecord, FlowKeyHash> table_;
    std::shared_mutex mutex_;
};

// -----------------------------
// Flow table
// -----------------------------
class FlowTable {
public:
    FlowTable() = default;

    void update(const FlowKey& key, uint32_t bytes, uint64_t ts_ms) {
        auto idx = shard_index(key);
        shards_[idx].update(key, bytes, ts_ms);
    }

    void sweep_expired() {
        uint64_t t = now_ms();
        for (auto& shard : shards_) {
            shard.sweep_expired(t);
        }
    }

private:
    static size_t shard_index(const FlowKey& key) noexcept {
        uint64_t h = FlowKeyHash{}(key);
        return (size_t)(h & (NUM_SHARDS - 1));
    }

    std::array<FlowShard, NUM_SHARDS> shards_;
};

// -----------------------------
// Packet parsing
// -----------------------------
struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    bool valid = false;
};

static inline ParsedPacket parse_packet(const uint8_t* data, uint32_t len) {
    ParsedPacket out{};
    if (len < sizeof(ether_header)) return out;

    auto* eth = reinterpret_cast<const ether_header*>(data);
    uint16_t eth_type = ntohs(eth->ether_type);

    // Skip non-IPv4
    if (eth_type != ETHERTYPE_IP) return out;

    const uint8_t* ip_start = data + sizeof(ether_header);
    if (len < sizeof(ether_header) + sizeof(iphdr)) return out;

    auto* ip = reinterpret_cast<const iphdr*>(ip_start);
    if (ip->version != 4) return out;

    uint32_t ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(iphdr)) return out;
    if (len < sizeof(ether_header) + ip_hdr_len) return out;

    uint32_t total_ip_len = ntohs(ip->tot_len);
    if (total_ip_len < ip_hdr_len) return out;

    out.key.src_ip = ip->saddr;
    out.key.dst_ip = ip->daddr;
    out.key.proto  = ip->protocol;

    const uint8_t* l4 = ip_start + ip_hdr_len;
    uint32_t l4_len = (len >= sizeof(ether_header) + total_ip_len)
        ? (total_ip_len - ip_hdr_len)
        : (len - sizeof(ether_header) - ip_hdr_len);

    if (ip->protocol == IPPROTO_TCP) {
        if (l4_len < sizeof(tcphdr)) return out;
        auto* tcp = reinterpret_cast<const tcphdr*>(l4);
        out.key.src_port = ntohs(tcp->source);
        out.key.dst_port = ntohs(tcp->dest);
        uint32_t tcp_hdr_len = tcp->doff * 4;
        if (tcp_hdr_len < sizeof(tcphdr) || l4_len < tcp_hdr_len) return out;
        out.payload_len = l4_len - tcp_hdr_len;
        out.valid = true;
        return out;
    }

    if (ip->protocol == IPPROTO_UDP) {
        if (l4_len < sizeof(udphdr)) return out;
        auto* udp = reinterpret_cast<const udphdr*>(l4);
        out.key.src_port = ntohs(udp->source);
        out.key.dst_port = ntohs(udp->dest);
        out.payload_len = l4_len - sizeof(udphdr);
        out.valid = true;
        return out;
    }

    // Other protocols: still count as flows with ports = 0
    out.key.src_port = 0;
    out.key.dst_port = 0;
    out.payload_len = l4_len;
    out.valid = true;
    return out;
}

// -----------------------------
// TPACKET_V3 capture
// -----------------------------
class PacketCapture {
public:
    explicit PacketCapture(const std::string& ifname)
        : ifname_(ifname) {}

    ~PacketCapture() {
        if (ring_ && ring_size_) munmap(ring_, ring_size_);
        if (fd_ >= 0) close(fd_);
    }

    bool init() {
        fd_ = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (fd_ < 0) {
            perror("socket(AF_PACKET)");
            return false;
        }

        int version = TPACKET_V3;
        if (setsockopt(fd_, SOL_PACKET, PACKET_VERSION, &version, sizeof(version)) < 0) {
            perror("setsockopt(PACKET_VERSION)");
            return false;
        }

        int ifindex = if_nametoindex(ifname_.c_str());
        if (ifindex == 0) {
            perror("if_nametoindex");
            return false;
        }

        sockaddr_ll sll{};
        sll.sll_family   = AF_PACKET;
        sll.sll_protocol = htons(ETH_P_ALL);
        sll.sll_ifindex   = ifindex;

        if (bind(fd_, reinterpret_cast<sockaddr*>(&sll), sizeof(sll)) < 0) {
            perror("bind(AF_PACKET)");
            return false;
        }

        tpacket_req3 req{};
        req.tp_block_size = TPACKET_BLOCK_SIZE;
        req.tp_block_nr   = TPACKET_BLOCK_NR;
        req.tp_frame_size  = TPACKET_FRAME_SIZE;
        req.tp_frame_nr    = TPACKET_FRAME_NR;
        req.tp_retire_blk_tov = 60; // ms
        req.tp_feature_req_word = TP_FT_REQ_FILL_RXHASH;

        if (setsockopt(fd_, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req)) < 0) {
            perror("setsockopt(PACKET_RX_RING)");
            return false;
        }

        ring_size_ = req.tp_block_size * req.tp_block_nr;
        ring_ = mmap(nullptr, ring_size_, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, fd_, 0);
        if (ring_ == MAP_FAILED) {
            perror("mmap");
            ring_ = nullptr;
            return false;
        }

        return true;
    }

    template <typename Fn>
    void run(Fn&& on_packet) {
        if (!ring_) return;

        auto* blocks = reinterpret_cast<tpacket_block_desc*>(ring_);
        const size_t block_num = TPACKET_BLOCK_NR;

        while (running_.load(std::memory_order_relaxed)) {
            for (size_t i = 0; i < block_num; ++i) {
                auto* bd = reinterpret_cast<tpacket_block_desc*>(
                    reinterpret_cast<uint8_t*>(ring_) + i * TPACKET_BLOCK_SIZE);

                auto status = bd->hdr.bh1.block_status;
                if (!(status & TP_STATUS_USER)) continue;

                auto* block_base = reinterpret_cast<uint8_t*>(bd);
                auto* hdr = reinterpret_cast<tpacket3_hdr*>(block_base + bd->hdr.bh1.offset_to_first_pkt);

                for (uint32_t pkt = 0; pkt < bd->hdr.bh1.num_pkts; ++pkt) {
                    uint8_t* pkt_data = reinterpret_cast<uint8_t*>(hdr) + hdr->tp_mac;
                    uint32_t pkt_len  = hdr->tp_snaplen;

                    on_packet(pkt_data, pkt_len);

                    hdr = reinterpret_cast<tpacket3_hdr*>(reinterpret_cast<uint8_t*>(hdr) + hdr->tp_next_offset);
                }

                bd->hdr.bh1.block_status = TP_STATUS_KERNEL;
            }
        }
    }

    void stop() {
        running_.store(false, std::memory_order_relaxed);
    }

private:
    std::string ifname_;
    int fd_ = -1;
    void* ring_ = nullptr;
    size_t ring_size_ = 0;
    std::atomic<bool> running_{true};
};

// -----------------------------
// Main
// -----------------------------
int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    std::string ifname = argv[1];

    FlowTable flow_table;
    PacketCapture cap(ifname);

    if (!cap.init()) {
        std::cerr << "Failed to initialize capture\n";
        return 1;
    }

    std::atomic<bool> stop_flag{false};

    std::thread sweeper([&] {
        while (!stop_flag.load(std::memory_order_relaxed)) {
            std::this_thread::sleep_for(std::chrono::milliseconds(FLOW_EXPIRY_SWEEP_MS));
            flow_table.sweep_expired();
        }
    });

    std::cout << "Capturing on " << ifname << "...\n";

    cap.run([&](const uint8_t* data, uint32_t len) {
        uint64_t ts = now_ms();
        auto parsed = parse_packet(data, len);
        if (!parsed.valid) return;

        uint32_t frame_bytes = len; // or derive from packet metadata if needed
        flow_table.update(parsed.key, frame_bytes, ts);
    });

    stop_flag.store(true, std::memory_order_relaxed);
    sweeper.join();
    return 0;
}
