use ahash::AHashMap;
use crossbeam::queue::SegQueue;
use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_v4: u32,
    pub dst_v4: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub ip_version: u8,
    pub _pad: u16,
}

impl FlowKey {
    #[inline(always)]
    pub fn new_v4(src: Ipv4Addr, dst: Ipv4Addr, src_port: u16, dst_port: u16, proto: u8) -> Self {
        Self {
            src_v4: u32::from(src),
            dst_v4: u32::from(dst),
            src_port,
            dst_port,
            proto,
            ip_version: 4,
            _pad: 0,
        }
    }
}

#[derive(Debug, Default)]
pub struct FlowStats {
    pub packets: AtomicU64,
    pub bytes: AtomicU64,
    pub first_seen_ns: AtomicU64,
    pub last_seen_ns: AtomicU64,
}

impl FlowStats {
    #[inline(always)]
    pub fn update(&self, bytes: u64, now_ns: u64) {
        self.packets.fetch_add(1, Ordering::Relaxed);
        self.bytes.fetch_add(bytes, Ordering::Relaxed);

        let first = self.first_seen_ns.load(Ordering::Relaxed);
        if first == 0 {
            let _ = self.first_seen_ns.compare_exchange(
                0,
                now_ns,
                Ordering::Relaxed,
                Ordering::Relaxed,
            );
        }
        self.last_seen_ns.store(now_ns, Ordering::Relaxed);
    }
}

pub struct Shard {
    map: RwLock<AHashMap<FlowKey, Arc<FlowStats>>>,
}

impl Shard {
    pub fn new() -> Self {
        Self {
            map: RwLock::new(AHashMap::with_capacity(1 << 16)),
        }
    }

    #[inline(always)]
    pub fn update_flow(&self, key: FlowKey, bytes: u64, now_ns: u64) {
        {
            let guard = self.map.read().unwrap();
            if let Some(stats) = guard.get(&key) {
                stats.update(bytes, now_ns);
                return;
            }
        }

        let mut guard = self.map.write().unwrap();
        let stats = guard
            .entry(key)
            .or_insert_with(|| Arc::new(FlowStats::default()))
            .clone();

        stats.update(bytes, now_ns);
    }

    pub fn expire_inactive(&self, cutoff_ns: u64) -> usize {
        let mut guard = self.map.write().unwrap();
        let before = guard.len();
        guard.retain(|_, stats| stats.last_seen_ns.load(Ordering::Relaxed) >= cutoff_ns);
        before - guard.len()
    }
}

pub struct FlowTable {
    shards: Vec<Arc<Shard>>,
    shard_mask: usize,
}

impl FlowTable {
    pub fn with_shards(n: usize) -> Self {
        assert!(n.is_power_of_two());
        let shards = (0..n).map(|_| Arc::new(Shard::new())).collect();
        Self {
            shards,
            shard_mask: n - 1,
        }
    }

    #[inline(always)]
    fn shard_for(&self, key: &FlowKey) -> usize {
        use std::hash::{Hash, Hasher};
        let mut h = ahash::AHasher::default();
        key.hash(&mut h);
        (h.finish() as usize) & self.shard_mask
    }

    #[inline(always)]
    pub fn update(&self, key: FlowKey, bytes: u64, now_ns: u64) {
        let idx = self.shard_for(&key);
        self.shards[idx].update_flow(key, bytes, now_ns);
    }

    pub fn expire_all(&self, idle_timeout: Duration) -> usize {
        let cutoff_ns = now_ns().saturating_sub(idle_timeout.as_nanos() as u64);
        self.shards
            .iter()
            .map(|s| s.expire_inactive(cutoff_ns))
            .sum()
    }
}

#[derive(Clone, Copy, Debug)]
pub struct ParsedPacket<'a> {
    pub src: Ipv4Addr,
    pub dst: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub payload: &'a [u8],
    pub len: u64,
}

#[inline(always)]
pub fn parse_ipv4_tcp_udp(packet: &[u8]) -> Option<ParsedPacket<'_>> {
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    if packet.len() < 14 + 20 {
        return None;
    }

    let ip_start = 14;
    let ver_ihl = packet[ip_start];
    if ver_ihl >> 4 != 4 {
        return None;
    }

    let ihl = ((ver_ihl & 0x0F) as usize) * 4;
    if packet.len() < ip_start + ihl {
        return None;
    }

    let proto = packet[ip_start + 9];
    let src = Ipv4Addr::new(
        packet[ip_start + 12],
        packet[ip_start + 13],
        packet[ip_start + 14],
        packet[ip_start + 15],
    );
    let dst = Ipv4Addr::new(
        packet[ip_start + 16],
        packet[ip_start + 17],
        packet[ip_start + 18],
        packet[ip_start + 19],
    );

    let l4 = ip_start + ihl;
    if packet.len() < l4 + 4 {
        return None;
    }

    let src_port = u16::from_be_bytes([packet[l4], packet[l4 + 1]]);
    let dst_port = u16::from_be_bytes([packet[l4 + 2], packet[l4 + 3]]);

    Some(ParsedPacket {
        src,
        dst,
        src_port,
        dst_port,
        proto,
        payload: &packet[l4..],
        len: packet.len() as u64,
    })
}

#[inline(always)]
pub fn now_ns() -> u64 {
    static START: once_cell::sync::Lazy<Instant> = once_cell::sync::Lazy::new(Instant::now);
    START.elapsed().as_nanos() as u64
}

