## C++20 implementation

```cpp
#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <chrono>
#include <thread>
#include <vector>
#include <optional>
#include <iostream>
#include <immintrin.h> // for prefetch (optional)

#if defined(__GNUC__) || defined(__clang__)
  #define HOT __attribute__((hot))
  #define ALWAYS_INLINE __attribute__((always_inline)) inline
#else
  #define HOT
  #define ALWAYS_INLINE inline
#endif

// =========================
// Packet / flow definitions
// =========================

enum class Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    ICMP = 1,
    OTHER = 255
};

struct FlowKey {
    uint32_t src_ip;   // IPv4 only for simplicity
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
    uint8_t  pad[3]{};

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct alignas(64) FlowEntry {
    std::atomic<uint64_t> key_hash{0}; // 0 = empty, otherwise occupied
    FlowKey key{};

    uint64_t packets{0};
    uint64_t bytes{0};
    uint64_t first_seen_ns{0};
    std::atomic<uint64_t> last_seen_ns{0};

    // Extra fields for analyzers
    uint32_t tcp_flags{0};
    uint32_t pad{0};

    // 64B cache line alignment helps reduce false sharing
};

static_assert(sizeof(FlowEntry) % 64 == 0, "FlowEntry should be cache-line friendly");

// =========================
// Fast hash
// =========================

ALWAYS_INLINE uint64_t mix64(uint64_t x) noexcept {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

ALWAYS_INLINE uint64_t hash_key(const FlowKey& k) noexcept {
    // Pack fields into 64-bit chunks and mix.
    uint64_t a = (uint64_t(k.src_ip) << 32) | k.dst_ip;
    uint64_t b = (uint64_t(k.src_port) << 48) | (uint64_t(k.dst_port) << 32) | (uint64_t(k.proto) << 24);
    return mix64(a ^ mix64(b));
}

// =========================
// Packet metadata
// =========================

struct PacketMeta {
    FlowKey key;
    uint32_t len;
    uint64_t timestamp_ns;
    uint32_t tcp_flags;
};

// =========================
// Flow table
// =========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          entries_(capacity_) {
        if ((capacity_ & mask_) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    HOT ALWAYS_INLINE void ingest(const PacketMeta& pkt) noexcept {
        const uint64_t h = hash_key(pkt.key);
        const size_t start = size_t(h) & mask_;

        // Open addressing with linear probing.
        // In practice, robin-hood can reduce probe variance, but this is simpler and fast.
        for (size_t i = 0; i < probe_limit_; ++i) {
            FlowEntry& e = entries_[(start + i) & mask_];

            uint64_t cur = e.key_hash.load(std::memory_order_relaxed);

            if (cur == 0) {
                // Try to claim empty slot
                if (e.key_hash.compare_exchange_strong(cur, h,
                        std::memory_order_acq_rel,
                        std::memory_order_relaxed)) {
                    // We own it now; initialize
                    e.key = pkt.key;
                    e.packets = 1;
                    e.bytes = pkt.len;
                    e.first_seen_ns = pkt.timestamp_ns;
                    e.last_seen_ns.store(pkt.timestamp_ns, std::memory_order_release);
                    e.tcp_flags = pkt.tcp_flags;
                    return;
                }
                // CAS lost; retry same slot
                --i;
                continue;
            }

            if (cur == h && e.key == pkt.key) {
                // Hot update path
                e.packets++;
                e.bytes += pkt.len;
                e.last_seen_ns.store(pkt.timestamp_ns, std::memory_order_relaxed);
                e.tcp_flags |= pkt.tcp_flags;
                return;
            }
        }

        // Table is overloaded or probe limit too small.
        // Production systems should handle overflow / spill / resize.
        overflow_count_.fetch_add(1, std::memory_order_relaxed);
    }

    struct Snapshot {
        FlowKey key;
        uint64_t packets;
        uint64_t bytes;
        uint64_t first_seen_ns;
        uint64_t last_seen_ns;
        uint32_t tcp_flags;
    };

    std::vector<Snapshot> export_and_age(uint64_t now_ns, uint64_t idle_timeout_ns) {
        std::vector<Snapshot> out;
        out.reserve(capacity_ / 8);

        for (auto& e : entries_) {
            uint64_t h = e.key_hash.load(std::memory_order_acquire);
            if (h == 0) continue;

            uint64_t last = e.last_seen_ns.load(std::memory_order_relaxed);
            if (now_ns > last && (now_ns - last) > idle_timeout_ns) {
                // Export stale flow and clear slot
                out.push_back(Snapshot{
                    e.key, e.packets, e.bytes, e.first_seen_ns, last, e.tcp_flags
                });

                // Clear entry
                e.packets = 0;
                e.bytes = 0;
                e.first_seen_ns = 0;
                e.tcp_flags = 0;
                e.key = {};
                e.last_seen_ns.store(0, std::memory_order_relaxed);
                e.key_hash.store(0, std::memory_order_release);
            }
        }

        return out;
    }

    uint64_t overflow_count() const noexcept {
        return overflow_count_.load(std::memory_order_relaxed);
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
    std::atomic<uint64_t> overflow_count_{0};

    static constexpr size_t probe_limit_ = 16;
};

// =========================
// Example packet source stub
// =========================

class PacketSource {
public:
    virtual ~PacketSource() = default;
    virtual std::optional<PacketMeta> next() = 0;
};

// Dummy generator for demonstration
class DummyPacketSource : public PacketSource {
public:
    std::optional<PacketMeta> next() override {
        if (count_++ > 1'000'000) return std::nullopt;

        PacketMeta p{};
        p.key.src_ip = 0x0A000001 + (count_ % 1024);
        p.key.dst_ip = 0x0A000100 + (count_ % 256);
        p.key.src_port = 1000 + (count_ % 10000);
        p.key.dst_port = 80;
        p.key.proto = static_cast<uint8_t>(Proto::TCP);
        p.len = 64 + (count_ % 1400);
        p.timestamp_ns = now_ns();
        p.tcp_flags = 0x10;
        return p;
    }

private:
    uint64_t count_{0};

    static uint64_t now_ns() noexcept {
        using namespace std::chrono;
        return duration_cast<nanoseconds>(
            steady_clock::now().time_since_epoch()).count();
    }
};

// =========================
// Main processing loop
// =========================

class Analyzer {
public:
    explicit Analyzer(size_t table_pow2)
        : table_(table_pow2) {}

    void run(PacketSource& src, std::atomic<bool>& stop_flag) {
        while (!stop_flag.load(std::memory_order_relaxed)) {
            auto pkt = src.next();
            if (!pkt) break;
            table_.ingest(*pkt);

            // Optional: batch export, periodically in another thread in real systems
            if ((++counter_ & 0xFFFFF) == 0) {
                auto now = pkt->timestamp_ns;
                auto expired = table_.export_and_age(now, idle_timeout_ns_);
                if (!expired.empty()) {
                    // In production: send to exporter / database / logs
                    std::cout << "Expired flows: " << expired.size() << "\n";
                }
            }
        }
    }

    FlowTable& table() noexcept { return table_; }

private:
    FlowTable table_;
    uint64_t counter_{0};
    uint64_t idle_timeout_ns_{60ULL * 1'000'000'000ULL}; // 60s
};

// =========================
// Entry point
// =========================

int main() {
    try {
        DummyPacketSource src;

        // 2^20 entries (~1,048,576 flows)
        Analyzer analyzer(/*table_pow2=*/20);

        std::atomic<bool> stop{false};
        analyzer.run(src, stop);

        std::cout << "Overflow count: " << analyzer.table().overflow_count() << "\n";
        return 0;
    } catch (const std::exception& ex) {
        std::cerr << "Fatal error: " << ex.what() << "\n";
        return 1;
    }
}
