## `flow_analyzer.cpp`

```cpp
#include <arpa/inet.h>
#include <pcap.h>

#include <atomic>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <unordered_map>
#include <vector>
#include <chrono>

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t length;
    uint16_t checksum;
};
#pragma pack(pop)

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast mix suitable for initial implementation
        uint64_t x = k.src_ip;
        x ^= (uint64_t)k.dst_ip << 1;
        x ^= (uint64_t)k.src_port << 17;
        x ^= (uint64_t)k.dst_port << 33;
        x ^= (uint64_t)k.protocol << 49;
        // final avalanche
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return (size_t)x;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

class FlowTable {
public:
    explicit FlowTable(size_t max_flows)
        : max_flows_(max_flows) {
        table_.reserve(max_flows_);
    }

    void update(const FlowKey& key, uint32_t packet_len, uint64_t now_ns) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = table_.find(key);
        if (it == table_.end()) {
            if (table_.size() >= max_flows_) {
                evict_one();
            }
            FlowStats stats;
            stats.packets = 1;
            stats.bytes = packet_len;
            stats.first_seen_ns = now_ns;
            stats.last_seen_ns = now_ns;
            table_.emplace(key, stats);
            return;
        }

        it->second.packets++;
        it->second.bytes += packet_len;
        it->second.last_seen_ns = now_ns;
    }

    void evict_expired(uint64_t now_ns, uint64_t idle_timeout_ns) {
        std::lock_guard<std::mutex> lock(mutex_);

        for (auto it = table_.begin(); it != table_.end(); ) {
            if (now_ns - it->second.last_seen_ns > idle_timeout_ns) {
                it = table_.erase(it);
            } else {
                ++it;
            }
        }
    }

    void dump_topN(size_t n) {
        std::lock_guard<std::mutex> lock(mutex_);

        std::vector<std::pair<FlowKey, FlowStats>> entries;
        entries.reserve(table_.size());
        for (const auto& kv : table_) {
            entries.push_back(kv);
        }

        std::sort(entries.begin(), entries.end(),
                  [](const auto& a, const auto& b) {
                      return a.second.bytes > b.second.bytes;
                  });

        size_t limit = std::min(n, entries.size());
        for (size_t i = 0; i < limit; ++i) {
            const auto& k = entries[i].first;
            const auto& s = entries[i].second;
            std::cout << i + 1 << " "
                      << ip_to_string(k.src_ip) << ":" << ntohs(k.src_port)
                      << " -> "
                      << ip_to_string(k.dst_ip) << ":" << ntohs(k.dst_port)
                      << " proto=" << (int)k.protocol
                      << " packets=" << s.packets
                      << " bytes=" << s.bytes
                      << "\n";
        }
    }

private:
    void evict_one() {
        // Simple eviction strategy for initial implementation:
        // remove an arbitrary entry.
        if (!table_.empty()) {
            table_.erase(table_.begin());
        }
    }

    static std::string ip_to_string(uint32_t ip_be) {
        char buf[INET_ADDRSTRLEN];
        in_addr addr{};
        addr.s_addr = ip_be;
        inet_ntop(AF_INET, &addr, buf, sizeof(buf));
        return std::string(buf);
    }

    size_t max_flows_;
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table_;
    std::mutex mutex_;
};

static uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(
        steady_clock::now().time_since_epoch()).count();
}

static bool parse_packet(const uint8_t* data, size_t len, FlowKey& out_key) {
    if (len < sizeof(EthernetHeader)) return false;

    const EthernetHeader* eth = reinterpret_cast<const EthernetHeader*>(data);
    uint16_t ethertype = ntohs(eth->ethertype);

    if (ethertype != 0x0800) {
        return false; // IPv4 only initially
    }

    size_t offset = sizeof(EthernetHeader);
    if (len < offset + sizeof(IPv4Header)) return false;

    const IPv4Header* ip = reinterpret_cast<const IPv4Header*>(data + offset);
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20 || len < offset + ihl) return false;

    out_key.src_ip = ip->src_ip;
    out_key.dst_ip = ip->dst_ip;
    out_key.protocol = ip->protocol;

    offset += ihl;

    if (ip->protocol == 6) { // TCP
        if (len < offset + sizeof(TCPHeader)) return false;
        const TCPHeader* tcp = reinterpret_cast<const TCPHeader*>(data + offset);
        out_key.src_port = tcp->src_port;
        out_key.dst_port = tcp->dst_port;
        return true;
    } else if (ip->protocol == 17) { // UDP
        if (len < offset + sizeof(UDPHeader)) return false;
        const UDPHeader* udp = reinterpret_cast<const UDPHeader*>(data + offset);
        out_key.src_port = udp->src_port;
        out_key.dst_port = udp->dst_port;
        return true;
    }

    // Track other IP protocols with zero ports
    out_key.src_port = 0;
    out_key.dst_port = 0;
    return true;
}

static void packet_handler(u_char* user, const struct pcap_pkthdr* header, const u_char* packet) {
    auto* flow_table = reinterpret_cast<FlowTable*>(user);

    FlowKey key{};
    if (!parse_packet(packet, header->len, key)) {
        return;
    }

    flow_table->update(key, header->len, now_ns());
}

int main(int argc, char* argv[]) {
    const char* dev = (argc > 1) ? argv[1] : nullptr;
    char errbuf[PCAP_ERRBUF_SIZE];

    if (!dev) {
        dev = pcap_lookupdev(errbuf);
        if (!dev) {
            std::cerr << "pcap_lookupdev failed: " << errbuf << "\n";
            return 1;
        }
    }

    pcap_t* handle = pcap_open_live(dev, 65535, 1, 1, errbuf);
    if (!handle) {
        std::cerr << "pcap_open_live failed: " << errbuf << "\n";
        return 1;
    }

    // Optional: only capture IPv4 traffic
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    FlowTable flow_table(500000); // initial capacity target

    std::atomic<bool> running{true};

    std::thread maintainer([&]() {
        const uint64_t idle_timeout_ns = 60ULL * 1000 * 1000 * 1000; // 60s
        while (running.load()) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            flow_table.evict_expired(now_ns(), idle_timeout_ns);
        }
    });

    std::thread reporter([&]() {
        while (running.load()) {
            std::this_thread::sleep_for(std::chrono::seconds(10));
            std::cout << "\n=== Top flows ===\n";
            flow_table.dump_topN(10);
        }
    });

    std::cout << "Starting capture on " << dev << "\n";
    int rc = pcap_loop(handle, -1, packet_handler, reinterpret_cast<u_char*>(&flow_table));
    if (rc == -1) {
        std::cerr << "pcap_loop error: " << pcap_geterr(handle) << "\n";
    }

    running = false;
    maintainer.join();
    reporter.join();

    pcap_close(handle);
    return 0;
}
