use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

use crossbeam_channel::{bounded, Receiver, Sender};
use hashbrown::HashMap;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
#[repr(C)]
pub struct FlowKey {
    pub src_ip: [u8; 16],
    pub dst_ip: [u8; 16],
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
    pub ip_version: u8,
}

impl FlowKey {
    #[inline]
    pub fn new(src: IpAddr, dst: IpAddr, src_port: u16, dst_port: u16, protocol: u8) -> Self {
        let mut src_ip = [0u8; 16];
        let mut dst_ip = [0u8; 16];
        let ip_version = match (src, dst) {
            (IpAddr::V4(s), IpAddr::V4(d)) => {
                src_ip[..4].copy_from_slice(&s.octets());
                dst_ip[..4].copy_from_slice(&d.octets());
                4
            }
            (IpAddr::V6(s), IpAddr::V6(d)) => {
                src_ip.copy_from_slice(&s.octets());
                dst_ip.copy_from_slice(&d.octets());
                6
            }
            _ => 0, // mixed version, invalid in normal network flow context
        };

        Self {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            protocol,
            ip_version,
        }
    }
}

#[derive(Debug, Clone)]
pub struct FlowRecord {
    pub key: FlowKey,
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub packets: u64,
    pub bytes: u64,
}

impl FlowRecord {
    #[inline]
    pub fn new(key: FlowKey, now: Instant, bytes: u64) -> Self {
        Self {
            key,
            first_seen: now,
            last_seen: now,
            packets: 1,
            bytes,
        }
    }

    #[inline]
    pub fn update(&mut self, now: Instant, bytes: u64) {
        self.last_seen = now;
        self.packets += 1;
        self.bytes += bytes;
    }

    #[inline]
    pub fn idle_for(&self, now: Instant) -> Duration {
        now.duration_since(self.last_seen)
    }
}

pub struct FlowAnalyzer {
    table: HashMap<FlowKey, FlowRecord>,
    inactive_timeout: Duration,
    expired_tx: Sender<FlowRecord>,
}

impl FlowAnalyzer {
    pub fn new(inactive_timeout: Duration, expired_tx: Sender<FlowRecord>) -> Self {
        Self {
            table: HashMap::with_capacity(1 << 20), // reserve for scale
            inactive_timeout,
            expired_tx,
        }
    }

    #[inline]
    pub fn process_packet(
        &mut self,
        src: IpAddr,
        dst: IpAddr,
        src_port: u16,
        dst_port: u16,
        protocol: u8,
        packet_len: u64,
        now: Instant,
    ) {
        let key = FlowKey::new(src, dst, src_port, dst_port, protocol);

        if let Some(flow) = self.table.get_mut(&key) {
            flow.update(now, packet_len);
        } else {
            let record = FlowRecord::new(key, now, packet_len);
            self.table.insert(key, record);
        }
    }

    pub fn expire_flows(&mut self, now: Instant) {
        let timeout = self.inactive_timeout;
        let mut expired_keys = Vec::new();

        for (key, flow) in self.table.iter() {
            if now.duration_since(flow.last_seen) >= timeout {
                expired_keys.push(*key);
            }
        }

        for key in expired_keys {
            if let Some(flow) = self.table.remove(&key) {
                let _ = self.expired_tx.send(flow);
            }
        }
    }

    pub fn active_flow_count(&self) -> usize {
        self.table.len()
    }
}

/// Example consumer of expired flows.
fn expired_flow_consumer(rx: Receiver<FlowRecord>) {
    while let Ok(flow) = rx.recv() {
        println!(
            "Expired flow: packets={}, bytes={}, duration={:?}",
            flow.packets,
            flow.bytes,
            flow.last_seen.duration_since(flow.first_seen)
        );
    }
}

fn main() {
    let (tx, rx) = bounded::<FlowRecord>(100_000);

    std::thread::spawn(move || expired_flow_consumer(rx));

    let mut analyser = FlowAnalyzer::new(Duration::from_secs(30), tx);

    let now = Instant::now();

    // Simulated packets
    analyser.process_packet(
        IpAddr::V4(Ipv4Addr::new(192, 168, 1, 10)),
        IpAddr::V4(Ipv4Addr::new(8, 8, 8, 8)),
        51514,
        53,
        17, // UDP
        74,
        now,
    );

    analyser.process_packet(
        IpAddr::V4(Ipv4Addr::new(192, 168, 1, 10)),
        IpAddr::V4(Ipv4Addr::new(8, 8, 8, 8)),
        51514,
        53,
        17,
        90,
        now + Duration::from_millis(10),
    );

    analyser.expire_flows(now + Duration::from_secs(31));

    println!("Active flows: {}", analyser.active_flow_count());
}
