use ahash::AHasher;
use hashbrown::HashMap;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
#[repr(C)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    _pad: u8,
}

impl FlowKey {
    #[inline]
    fn new(src_ip: Ipv4Addr, dst_ip: Ipv4Addr, src_port: u16, dst_port: u16, proto: u8) -> Self {
        Self {
            src_ip: u32::from(src_ip).to_be(),
            dst_ip: u32::from(dst_ip).to_be(),
            src_port: src_port.to_be(),
            dst_port: dst_port.to_be(),
            proto,
            _pad: 0,
        }
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ns: u64,
    last_seen_ns: u64,
}

impl FlowStats {
    #[inline]
    fn new(now_ns: u64) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen_ns: now_ns,
            last_seen_ns: now_ns,
        }
    }

    #[inline]
    fn update(&mut self, bytes: usize, now_ns: u64) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen_ns = now_ns;
    }
}

struct FlowTable {
    flows: HashMap<FlowKey, FlowStats, ahash::RandomState>,
    idle_timeout_ns: u64,
}

impl FlowTable {
    fn new(capacity: usize, idle_timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_capacity_and_hasher(
                capacity,
                ahash::RandomState::new(),
            ),
            idle_timeout_ns: idle_timeout.as_nanos() as u64,
        }
    }

    #[inline]
    fn process_packet(
        &mut self,
        src_ip: Ipv4Addr,
        dst_ip: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
        packet_len: usize,
        now_ns: u64,
    ) {
        let key = FlowKey::new(src_ip, dst_ip, src_port, dst_port, proto);

        match self.flows.get_mut(&key) {
            Some(stats) => stats.update(packet_len, now_ns),
            None => {
                let mut stats = FlowStats::new(now_ns);
                stats.update(packet_len, now_ns);
                self.flows.insert(key, stats);
            }
        }
    }

    fn expire_idle(&mut self, now_ns: u64) -> usize {
        let before = self.flows.len();
        let timeout = self.idle_timeout_ns;

        self.flows.retain(|_, stats| {
            now_ns.saturating_sub(stats.last_seen_ns) <= timeout
        });

        before - self.flows.len()
    }

    fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        self.flows
            .iter()
            .map(|(k, v)| (*k, v.clone()))
            .collect()
    }

    fn len(&self) -> usize {
        self.flows.len()
    }
}

#[derive(Debug)]
struct Packet<'a> {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    payload_len: usize,
    _raw: &'a [u8],
}

trait PacketSource {
    fn next_batch<'a>(&'a mut self, out: &mut Vec<Packet<'a>>) -> bool;
}

/// Mock packet source for initial testing.
struct MockPacketSource {
    remaining: usize,
}

impl MockPacketSource {
    fn new(count: usize) -> Self {
        Self { remaining: count }
    }
}

impl PacketSource for MockPacketSource {
    fn next_batch<'a>(&'a mut self, out: &mut Vec<Packet<'a>>) -> bool {
        out.clear();

        if self.remaining == 0 {
            return false;
        }

        let batch_size = self.remaining.min(1024);
        let now = Instant::now();

        for i in 0..batch_size {
            let idx = (self.remaining + i) as u32;
            out.push(Packet {
                src_ip: Ipv4Addr::new(10, 0, ((idx >> 8) & 0xff) as u8, (idx & 0xff) as u8),
                dst_ip: Ipv4Addr::new(192, 168, ((idx >> 16) & 0xff) as u8, ((idx >> 24) & 0xff) as u8),
                src_port: 1000 + (idx as u16 % 40000),
                dst_port: 80,
                proto: 6,
                payload_len: 128,
                _raw: &[],
            });
        }

        self.remaining -= batch_size;
        let _ = now;
        true
    }
}

fn now_ns() -> u64 {
    let now = Instant::now();
    now.elapsed().as_nanos() as u64
}

fn main() {
    let mut table = FlowTable::new(1 << 20, Duration::from_secs(30));
    let mut source = MockPacketSource::new(5_000_000);
    let mut batch: Vec<Packet> = Vec::with_capacity(1024);

    let start = Instant::now();
    let mut last_expire = Instant::now();
    let expire_every = Duration::from_secs(1);

    loop {
        if !source.next_batch(&mut batch) {
            break;
        }

        let now = current_time_ns();

        for pkt in &batch {
            table.process_packet(
                pkt.src_ip,
                pkt.dst_ip,
                pkt.src_port,
                pkt.dst_port,
                pkt.proto,
                pkt.payload_len,
                now,
            );
        }

        if last_expire.elapsed() >= expire_every {
            let expired = table.expire_idle(current_time_ns());
            println!(
                "flows={} expired={} elapsed={:?}",
                table.len(),
                expired,
                start.elapsed()
            );
            last_expire = Instant::now();
        }
    }

    let expired = table.expire_idle(current_time_ns());
    println!(
        "done flows={} expired={} total_elapsed={:?}",
        table.len(),
        expired,
        start.elapsed()
    );

    let snapshot = table.snapshot();
    println!("snapshot size={}", snapshot.len());
}

#[inline]
fn current_time_ns() -> u64 {
    // For actual production use, replace with a monotonic clock source
    // optimized for your environment. This is just a placeholder.
    let now = Instant::now();
    now.elapsed().as_nanos() as u64
}
