use anyhow::Result;
use crossbeam_channel::{unbounded, Receiver, Sender};
use fxhash::FxHashMap;
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::ipv6::Ipv6Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use pnet::datalink::{self, Channel::Ethernet};
use std::hash::{Hash, Hasher};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src: IpAddr,
    dst: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src == other.src
            && self.dst == other.dst
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self.src {
            IpAddr::V4(ip) => {
                state.write_u8(4);
                state.write(&ip.octets());
            }
            IpAddr::V6(ip) => {
                state.write_u8(6);
                state.write(&ip.octets());
            }
        }
        match self.dst {
            IpAddr::V4(ip) => {
                state.write_u8(4);
                state.write(&ip.octets());
            }
            IpAddr::V6(ip) => {
                state.write_u8(6);
                state.write(&ip.octets());
            }
        }
        state.write_u16(self.src_port);
        state.write_u16(self.dst_port);
        state.write_u8(self.proto);
    }
}

#[derive(Debug, Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    tcp_fin: bool,
    tcp_rst: bool,
}

impl FlowStats {
    fn new(now: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
            tcp_fin: false,
            tcp_rst: false,
        }
    }

    fn update(&mut self, now: Instant, len: usize, tcp_flags: Option<u8>) {
        self.packets += 1;
        self.bytes += len as u64;
        self.last_seen = now;

        if let Some(flags) = tcp_flags {
            if flags & 0x01 != 0 {
                self.tcp_fin = true;
            }
            if flags & 0x04 != 0 {
                self.tcp_rst = true;
            }
        }
    }

    fn expired(&self, now: Instant, idle_timeout: Duration) -> bool {
        now.duration_since(self.last_seen) >= idle_timeout
    }
}

#[derive(Debug)]
struct FinishedFlow {
    key: FlowKey,
    stats: FlowStats,
}

struct FlowTable {
    flows: FxHashMap<FlowKey, FlowStats>,
    idle_timeout: Duration,
}

impl FlowTable {
    fn new(idle_timeout: Duration) -> Self {
        Self {
            flows: FxHashMap::default(),
            idle_timeout,
        }
    }

    fn process_packet(&mut self, key: FlowKey, now: Instant, len: usize, tcp_flags: Option<u8>) {
        if let Some(stats) = self.flows.get_mut(&key) {
            stats.update(now, len, tcp_flags);
        } else {
            let mut stats = FlowStats::new(now);
            stats.update(now, len, tcp_flags);
            self.flows.insert(key, stats);
        }
    }

    fn evict_expired(&mut self, now: Instant) -> Vec<FinishedFlow> {
        let mut finished = Vec::new();

        self.flows.retain(|key, stats| {
            if stats.expired(now, self.idle_timeout) {
                finished.push(FinishedFlow {
                    key: *key,
                    stats: stats.clone(),
                });
                false
            } else {
                true
            }
        });

        finished
    }

    fn flush_all(&mut self) -> Vec<FinishedFlow> {
        self.flows
            .drain()
            .map(|(key, stats)| FinishedFlow { key, stats })
            .collect()
    }
}

fn parse_flow(packet: &[u8]) -> Option<(FlowKey, Option<u8>, usize)> {
    let eth = EthernetPacket::new(packet)?;
    let payload = eth.payload();

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ip = Ipv4Packet::new(payload)?;
            let src = IpAddr::V4(ip.get_source());
            let dst = IpAddr::V4(ip.get_destination());
            let proto = ip.get_next_level_protocol().0;
            let ip_payload = ip.payload();
            let len = packet.len();

            match ip.get_next_level_protocol() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = TcpPacket::new(ip_payload)?;
                    let key = FlowKey {
                        src,
                        dst,
                        src_port: tcp.get_source(),
                        dst_port: tcp.get_destination(),
                        proto,
                    };
                    Some((key, Some(tcp.get_flags()), len))
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = UdpPacket::new(ip_payload)?;
                    let key = FlowKey {
                        src,
                        dst,
                        src_port: udp.get_source(),
                        dst_port: udp.get_destination(),
                        proto,
                    };
                    Some((key, None, len))
                }
                _ => None,
            }
        }
        EtherTypes::Ipv6 => {
            let ip = Ipv6Packet::new(payload)?;
            let src = IpAddr::V6(ip.get_source());
            let dst = IpAddr::V6(ip.get_destination());
            let proto = ip.get_next_header().0;
            let ip_payload = ip.payload();
            let len = packet.len();

            match ip.get_next_header() {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = TcpPacket::new(ip_payload)?;
                    let key = FlowKey {
                        src,
                        dst,
                        src_port: tcp.get_source(),
                        dst_port: tcp.get_destination(),
                        proto,
                    };
                    Some((key, Some(tcp.get_flags()), len))
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = UdpPacket::new(ip_payload)?;
                    let key = FlowKey {
                        src,
                        dst,
                        src_port: udp.get_source(),
                        dst_port: udp.get_destination(),
                        proto,
                    };
                    Some((key, None, len))
                }
                _ => None,
            }
        }
        _ => None,
    }
}

fn print_flow(flow: FinishedFlow) {
    println!(
        "{:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={} fin={} rst={}",
        flow.key.src,
        flow.key.src_port,
        flow.key.dst,
        flow.key.dst_port,
        flow.key.proto,
        flow.stats.packets,
        flow.stats.bytes,
        flow.stats.tcp_fin,
        flow.stats.tcp_rst
    );
}

fn capture_loop(iface_name: &str, tx: Sender<Vec<u8>>) -> Result<()> {
    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == iface_name)
        .expect("Interface not found");

    let config = datalink::Config {
        read_timeout: Some(Duration::from_millis(10)),
        ..Default::default()
    };

    let (_, mut rx) = match datalink::channel(&interface, config)? {
        Ethernet(tx_unused, rx) => (tx_unused, rx),
        _ => panic!("Unhandled channel type"),
    };

    loop {
        match rx.next() {
            Ok(packet) => {
                // Copy here is not ideal for gigabit-scale capture.
                // Replace with zero-copy / batching in production.
                if tx.send(packet.to_vec()).is_err() {
                    break;
                }
            }
            Err(_) => continue,
        }
    }

    Ok(())
}

fn analyser_loop(rx: Receiver<Vec<u8>>, idle_timeout: Duration, export_every: Duration) {
    let mut table = FlowTable::new(idle_timeout);
    let mut last_export = Instant::now();

    while let Ok(packet) = rx.recv() {
        let now = Instant::now();

        if let Some((key, tcp_flags, len)) = parse_flow(&packet) {
            table.process_packet(key, now, len, tcp_flags);
        }

        if now.duration_since(last_export) >= export_every {
            let expired = table.evict_expired(now);
            for flow in expired {
                print_flow(flow);
            }
            last_export = now;
        }
    }

    for flow in table.flush_all() {
        print_flow(flow);
    }
}

fn main() -> Result<()> {
    let iface_name = std::env::args()
        .nth(1)
        .expect("Usage: flow_analyser <interface>");

    let (tx, rx) = unbounded();

    let capture_thread = {
        let tx = tx.clone();
        std::thread::spawn(move || {
            if let Err(e) = capture_loop(&iface_name, tx) {
                eprintln!("capture error: {e:?}");
            }
        })
    };

    let analyser_thread = std::thread::spawn(move || {
        analyser_loop(rx, Duration::from_secs(30), Duration::from_secs(5));
    });

    capture_thread.join().ok();
    analyser_thread.join().ok();

    Ok(())
}
