use std::net::{Ipv4Addr, Ipv6Addr};
use std::time::{Duration, Instant};

use ahash::AHasher;
use byteorder::{ByteOrder, NetworkEndian};
use std::hash::{Hash, Hasher};

const MAX_FLOWS: usize = 1 << 20; // 1,048,576 entries
const FLOW_TIMEOUT_SECS: u64 = 30;

#[derive(Copy, Clone, Eq, PartialEq, Hash, Debug)]
#[repr(C)]
struct FlowKey {
    src_ip_hi: u64,
    src_ip_lo: u64,
    dst_ip_hi: u64,
    dst_ip_lo: u64,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    ip_version: u8,
}

impl FlowKey {
    fn ipv4(src: Ipv4Addr, dst: Ipv4Addr, src_port: u16, dst_port: u16, proto: u8) -> Self {
        let src_u32 = u32::from(src) as u64;
        let dst_u32 = u32::from(dst) as u64;
        Self {
            src_ip_hi: src_u32,
            src_ip_lo: 0,
            dst_ip_hi: dst_u32,
            dst_ip_lo: 0,
            src_port,
            dst_port,
            proto,
            ip_version: 4,
        }
    }

    fn ipv6(src: Ipv6Addr, dst: Ipv6Addr, src_port: u16, dst_port: u16, proto: u8) -> Self {
        let s = src.octets();
        let d = dst.octets();

        Self {
            src_ip_hi: NetworkEndian::read_u64(&s[0..8]),
            src_ip_lo: NetworkEndian::read_u64(&s[8..16]),
            dst_ip_hi: NetworkEndian::read_u64(&d[0..8]),
            dst_ip_lo: NetworkEndian::read_u64(&d[8..16]),
            src_port,
            dst_port,
            proto,
            ip_version: 6,
        }
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ns: u64,
    last_seen_ns: u64,
}

impl FlowStats {
    fn new(now_ns: u64, pkt_len: usize) -> Self {
        Self {
            packets: 1,
            bytes: pkt_len as u64,
            first_seen_ns: now_ns,
            last_seen_ns: now_ns,
        }
    }

    fn update(&mut self, now_ns: u64, pkt_len: usize) {
        self.packets += 1;
        self.bytes += pkt_len as u64;
        self.last_seen_ns = now_ns;
    }
}

#[derive(Copy, Clone)]
enum SlotState {
    Empty,
    Occupied,
    Tombstone,
}

#[derive(Clone)]
struct Slot {
    state: SlotState,
    key: FlowKey,
    stats: FlowStats,
}

impl Default for Slot {
    fn default() -> Self {
        Self {
            state: SlotState::Empty,
            key: FlowKey {
                src_ip_hi: 0,
                src_ip_lo: 0,
                dst_ip_hi: 0,
                dst_ip_lo: 0,
                src_port: 0,
                dst_port: 0,
                proto: 0,
                ip_version: 0,
            },
            stats: FlowStats {
                packets: 0,
                bytes: 0,
                first_seen_ns: 0,
                last_seen_ns: 0,
            },
        }
    }
}

struct FlowTable {
    slots: Vec<Slot>,
    capacity: usize,
    used: usize,
}

impl FlowTable {
    fn with_capacity(capacity: usize) -> Self {
        let cap = capacity.next_power_of_two();
        Self {
            slots: vec![Slot::default(); cap],
            capacity: cap,
            used: 0,
        }
    }

    #[inline]
    fn hash(key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        hasher.finish() as usize
    }

    #[inline]
    fn insert_or_update(&mut self, key: FlowKey, now_ns: u64, pkt_len: usize) {
        let mut idx = Self::hash(&key) & (self.capacity - 1);
        let mut first_tombstone: Option<usize> = None;

        loop {
            match self.slots[idx].state {
                SlotState::Empty => {
                    let target = first_tombstone.unwrap_or(idx);
                    self.slots[target].key = key;
                    self.slots[target].stats = FlowStats::new(now_ns, pkt_len);
                    self.slots[target].state = SlotState::Occupied;
                    self.used += 1;
                    return;
                }
                SlotState::Tombstone => {
                    if first_tombstone.is_none() {
                        first_tombstone = Some(idx);
                    }
                }
                SlotState::Occupied => {
                    if self.slots[idx].key == key {
                        self.slots[idx].stats.update(now_ns, pkt_len);
                        return;
                    }
                }
            }

            idx = (idx + 1) & (self.capacity - 1);
        }
    }

    fn expire_old_flows(&mut self, now_ns: u64, timeout_ns: u64) -> Vec<(FlowKey, FlowStats)> {
        let mut expired = Vec::new();

        for slot in &mut self.slots {
            if matches!(slot.state, SlotState::Occupied)
                && now_ns.saturating_sub(slot.stats.last_seen_ns) > timeout_ns
            {
                expired.push((slot.key, slot.stats.clone()));
                slot.state = SlotState::Tombstone;
                self.used -= 1;
            }
        }

        expired
    }

    fn load_factor(&self) -> f64 {
        self.used as f64 / self.capacity as f64
    }
}

fn parse_ipv4_tcp_udp(packet: &[u8]) -> Option<(FlowKey, usize)> {
    // Ethernet II minimum
    if packet.len() < 14 {
        return None;
    }

    let ethertype = NetworkEndian::read_u16(&packet[12..14]);
    if ethertype != 0x0800 {
        return None; // only IPv4 in this initial implementation
    }

    let ip_start = 14;
    if packet.len() < ip_start + 20 {
        return None;
    }

    let ihl = (packet[ip_start] & 0x0f) as usize * 4;
    if ihl < 20 || packet.len() < ip_start + ihl {
        return None;
    }

    let proto = packet[ip_start + 9];
    if proto != 6 && proto != 17 {
        return None;
    }

    let src_ip = Ipv4Addr::new(
        packet[ip_start + 12],
        packet[ip_start + 13],
        packet[ip_start + 14],
        packet[ip_start + 15],
    );
    let dst_ip = Ipv4Addr::new(
        packet[ip_start + 16],
        packet[ip_start + 17],
        packet[ip_start + 18],
        packet[ip_start + 19],
    );

    let l4_start = ip_start + ihl;
    if packet.len() < l4_start + 4 {
        return None;
    }

    let src_port = NetworkEndian::read_u16(&packet[l4_start..l4_start + 2]);
    let dst_port = NetworkEndian::read_u16(&packet[l4_start + 2..l4_start + 4]);

    let key = FlowKey::ipv4(src_ip, dst_ip, src_port, dst_port, proto);
    Some((key, packet.len()))
}

fn process_packet(table: &mut FlowTable, packet: &[u8], now_ns: u64) {
    if let Some((key, len)) = parse_ipv4_tcp_udp(packet) {
        table.insert_or_update(key, now_ns, len);
    }
}

fn now_ns(start: Instant) -> u64 {
    start.elapsed().as_nanos() as u64
}

fn main() {
    let mut table = FlowTable::with_capacity(MAX_FLOWS);
    let start = Instant::now();
    let timeout_ns = Duration::from_secs(FLOW_TIMEOUT_SECS).as_nanos() as u64;

    // Placeholder packet source for initial implementation.
    // Replace with AF_PACKET/pcap/DPDK/AF_XDP or a NIC receive loop.
    let sample_packet = build_sample_ipv4_tcp_packet();

    for i in 0..1_000_000u64 {
        let t = now_ns(start);
        process_packet(&mut table, &sample_packet, t);

        if i % 100_000 == 0 {
            let expired = table.expire_old_flows(t, timeout_ns);
            println!(
                "iter={} flows={} load={:.3} expired={}",
                i,
                table.used,
                table.load_factor(),
                expired.len()
            );
        }
    }

    let t = now_ns(start);
    let expired = table.expire_old_flows(t, 0);
    println!("final expired flows: {}", expired.len());
}

fn build_sample_ipv4_tcp_packet() -> Vec<u8> {
    // Ethernet + IPv4 + TCP minimal packet
    let mut pkt = vec![0u8; 14 + 20 + 20];

    // Ethernet ethertype IPv4
    pkt[12] = 0x08;
    pkt[13] = 0x00;

    // IPv4 header
    pkt[14] = 0x45; // version=4, ihl=5
    pkt[15] = 0x00;
    NetworkEndian::write_u16(&mut pkt[16..18], (20 + 20) as u16);
    pkt[22] = 64;
    pkt[23] = 6; // TCP
    pkt[26..30].copy_from_slice(&[192, 168, 1, 10]);
    pkt[30..34].copy_from_slice(&[192, 168, 1, 20]);

    // TCP header
    NetworkEndian::write_u16(&mut pkt[34..36], 12345);
    NetworkEndian::write_u16(&mut pkt[36..38], 80);

    pkt
}
