use ahash::AHasher;
use crossbeam::channel::{bounded, Receiver, Sender};
use parking_lot::Mutex;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::IpAddr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Clone, Copy, Debug)]
pub struct PacketMeta {
    pub ts: Instant,
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
    pub length: u32,
    pub tcp_flags: u8,
}

impl PacketMeta {
    pub fn flow_key(&self) -> FlowKey {
        FlowKey {
            src_ip: self.src_ip,
            dst_ip: self.dst_ip,
            src_port: self.src_port,
            dst_port: self.dst_port,
            protocol: self.protocol,
        }
    }
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub packets: u64,
    pub bytes: u64,
    pub tcp_syn: u64,
    pub tcp_ack: u64,
    pub tcp_fin: u64,
    pub tcp_rst: u64,
}

impl FlowStats {
    pub fn new(ts: Instant) -> Self {
        Self {
            first_seen: ts,
            last_seen: ts,
            packets: 0,
            bytes: 0,
            tcp_syn: 0,
            tcp_ack: 0,
            tcp_fin: 0,
            tcp_rst: 0,
        }
    }

    pub fn update(&mut self, pkt: &PacketMeta) {
        self.last_seen = pkt.ts;
        self.packets += 1;
        self.bytes += pkt.length as u64;

        // TCP flag accounting (if protocol indicates TCP = 6)
        if pkt.protocol == 6 {
            if pkt.tcp_flags & 0x02 != 0 {
                self.tcp_syn += 1;
            }
            if pkt.tcp_flags & 0x10 != 0 {
                self.tcp_ack += 1;
            }
            if pkt.tcp_flags & 0x01 != 0 {
                self.tcp_fin += 1;
            }
            if pkt.tcp_flags & 0x04 != 0 {
                self.tcp_rst += 1;
            }
        }
    }

    pub fn duration(&self) -> Duration {
        self.last_seen.duration_since(self.first_seen)
    }

    pub fn throughput_bps(&self) -> f64 {
        let secs = self.duration().as_secs_f64().max(1e-9);
        (self.bytes as f64 * 8.0) / secs
    }
}

pub struct Shard {
    table: HashMap<FlowKey, FlowStats, ahash::RandomState>,
}

impl Shard {
    pub fn new() -> Self {
        Self {
            table: HashMap::with_capacity_and_hasher(1 << 16, ahash::RandomState::new()),
        }
    }

    pub fn process_packet(&mut self, pkt: PacketMeta) {
        let key = pkt.flow_key();
        self.table
            .entry(key)
            .and_modify(|s| s.update(&pkt))
            .or_insert_with(|| {
                let mut s = FlowStats::new(pkt.ts);
                s.update(&pkt);
                s
            });
    }

    pub fn evict_inactive(&mut self, now: Instant, idle_timeout: Duration) -> usize {
        let before = self.table.len();
        self.table.retain(|_, stats| now.duration_since(stats.last_seen) <= idle_timeout);
        before - self.table.len()
    }

    pub fn snapshot_top_n_by_bytes(&self, n: usize) -> Vec<(FlowKey, FlowStats)> {
        let mut items: Vec<_> = self
            .table
            .iter()
            .map(|(k, v)| (*k, v.clone()))
            .collect();

        items.sort_by_key(|(_, s)| std::cmp::Reverse(s.bytes));
        items.truncate(n);
        items
    }
}

pub struct FlowAnalyser {
    shards: Vec<Arc<Mutex<Shard>>>,
    txs: Vec<Sender<PacketMeta>>,
    shard_count: usize,
}

impl FlowAnalyser {
    pub fn new(shard_count: usize, queue_size: usize) -> Self {
        let mut shards = Vec::with_capacity(shard_count);
        let mut txs = Vec::with_capacity(shard_count);

        for _ in 0..shard_count {
            let (tx, rx) = bounded::<PacketMeta>(queue_size);
            let shard = Arc::new(Mutex::new(Shard::new()));
            let shard_clone = Arc::clone(&shard);

            thread::spawn(move || worker_loop(shard_clone, rx));

            shards.push(shard);
            txs.push(tx);
        }

        Self {
            shards,
            txs,
            shard_count,
        }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % self.shard_count
    }

    pub fn ingest(&self, pkt: PacketMeta) {
        let idx = self.shard_index(&pkt.flow_key());
        // Backpressure is intentional here; in a production pipeline you may want
        // drop/overflow metrics or a soft-fail mode.
        let _ = self.txs[idx].send(pkt);
    }

    pub fn snapshot_all_top_n(&self, n: usize) -> Vec<(FlowKey, FlowStats)> {
        let mut all = Vec::new();
        for shard in &self.shards {
            let shard = shard.lock();
            all.extend(shard.snapshot_top_n_by_bytes(n));
        }
        all.sort_by_key(|(_, s)| std::cmp::Reverse(s.bytes));
        all.truncate(n);
        all
    }
}

fn worker_loop(shard: Arc<Mutex<Shard>>, rx: Receiver<PacketMeta>) {
    let mut last_eviction = Instant::now();
    let eviction_interval = Duration::from_secs(5);
    let idle_timeout = Duration::from_secs(30);

    while let Ok(pkt) = rx.recv() {
        {
            let mut shard = shard.lock();
            shard.process_packet(pkt);
        }

        if last_eviction.elapsed() >= eviction_interval {
            let now = Instant::now();
            let mut shard = shard.lock();
            let evicted = shard.evict_inactive(now, idle_timeout);
            if evicted > 0 {
                eprintln!("evicted {} inactive flows", evicted);
            }
            last_eviction = now;
        }
    }
}

fn main() {
    let analyser = FlowAnalyser::new(8, 65_536);

    // Example synthetic traffic
    let now = Instant::now();

    for i in 0..1_000_000u32 {
        let pkt = PacketMeta {
            ts: now + Duration::from_micros(i as u64),
            src_ip: "10.0.0.1".parse().unwrap(),
            dst_ip: "10.0.0.2".parse().unwrap(),
