            tcp_flags: if i == 0 { 0x02 } else { 0x10 },
        };
        analyser.ingest(pkt);
    }

    thread::sleep(Duration::from_secs(1));

    let top = analyser.snapshot_all_top_n(10);
    for (k, s) in top {
        println!(
            "{:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={} bps={:.2}",
            k.src_ip,
            k.src_port,
            k.dst_ip,
            k.dst_port,
            k.protocol,
            s.packets,
            s.bytes,
            s.throughput_bps()
        );
