use ahash::RandomState;
use crossbeam::queue::SegQueue;
use parking_lot::Mutex;
use std::collections::HashMap;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
    syn_count: u32,
    fin_count: u32,
    rst_count: u32,
}

impl FlowStats {
    fn new(now: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
            syn_count: 0,
            fin_count: 0,
            rst_count: 0,
        }
    }

    fn update(&mut self, bytes: usize, now: Instant, tcp_flags: u8) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;

        // TCP flags: SYN=0x02, FIN=0x01, RST=0x04
        if tcp_flags & 0x02 != 0 {
            self.syn_count += 1;
        }
        if tcp_flags & 0x01 != 0 {
            self.fin_count += 1;
        }
        if tcp_flags & 0x04 != 0 {
            self.rst_count += 1;
        }
    }
}

struct Shard {
    map: Mutex<HashMap<FlowKey, FlowStats, RandomState>>,
}

impl Shard {
    fn new() -> Self {
        Self {
            map: Mutex::new(HashMap::with_hasher(RandomState::new())),
        }
    }
}

pub struct FlowAnalyzer {
    shards: Vec<Shard>,
    shard_mask: usize,
    timeout: Duration,
    expired: SegQueue<(FlowKey, FlowStats)>,
}

impl FlowAnalyzer {
    pub fn new(num_shards: usize, timeout: Duration) -> Self {
        let shard_count = num_shards.next_power_of_two().max(1);
        let shards = (0..shard_count).map(|_| Shard::new()).collect();

        Self {
            shards,
            shard_mask: shard_count - 1,
            timeout,
            expired: SegQueue::new(),
        }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut h = key.src_ip as usize;
        h ^= (key.dst_ip as usize).wrapping_mul(31);
        h ^= (key.src_port as usize).wrapping_mul(131);
        h ^= (key.dst_port as usize).wrapping_mul(17);
        h ^= (key.protocol as usize).wrapping_mul(7);
        h & self.shard_mask
    }

    pub fn process_packet(
        &self,
        src_ip: Ipv4Addr,
        dst_ip: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        protocol: u8,
        packet_len: usize,
        tcp_flags: u8,
    ) {
        let now = Instant::now();
        let key = FlowKey {
            src_ip: u32::from(src_ip),
            dst_ip: u32::from(dst_ip),
            src_port,
            dst_port,
            protocol,
        };

        let shard_idx = self.shard_index(&key);
        let mut guard = self.shards[shard_idx].map.lock();

        let entry = guard.entry(key).or_insert_with(|| FlowStats::new(now));
        entry.update(packet_len, now, tcp_flags);
    }

    pub fn expire_flows(&self) {
        let cutoff = Instant::now() - self.timeout;

        for shard in &self.shards {
            let mut guard = shard.map.lock();
            let mut to_remove = Vec::new();

            for (key, stats) in guard.iter() {
                if stats.last_seen < cutoff {
                    to_remove.push(*key);
                }
            }

            for key in to_remove {
                if let Some(stats) = guard.remove(&key) {
                    self.expired.push((key, stats));
                }
            }
        }
    }

    pub fn drain_expired(&self) -> Vec<(FlowKey, FlowStats)> {
        let mut out = Vec::new();
        while let Some(item) = self.expired.pop() {
            out.push(item);
        }
        out
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        let mut all = Vec::new();
        for shard in &self.shards {
            let guard = shard.map.lock();
            all.extend(guard.iter().map(|(k, v)| (*k, v.clone())));
        }
        all
    }
}
