```cpp
#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <chrono>
#include <unordered_map>
#include <vector>
#include <algorithm>
#include <iostream>
#include <optional>

#if defined(__GNUC__) || defined(__clang__)
#define likely(x)   __builtin_expect(!!(x), 1)
#define unlikely(x) __builtin_expect(!!(x), 0)
#else
#define likely(x)   (x)
#define unlikely(x) (x)
#endif

// -----------------------------
// Utility: fast hash
// -----------------------------
static inline uint64_t hash64(uint64_t x) {
    // SplitMix64 finalizer
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static inline uint64_t mix_u64(uint64_t a, uint64_t b) {
    return hash64(a ^ (hash64(b) << 1));
}

// -----------------------------
// Packet representation
// -----------------------------
struct PacketView {
    const uint8_t* data;
    size_t len;
    uint64_t ts_ns;
};

// -----------------------------
// Flow key
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
    uint8_t direction; // 0 = ingress, 1 = egress

    bool operator==(const FlowKey& o) const {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto &&
               direction == o.direction;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t a = (uint64_t(k.src_ip) << 32) | k.dst_ip;
        uint64_t b = (uint64_t(k.src_port) << 48) |
                     (uint64_t(k.dst_port) << 32) |
                     (uint64_t(k.proto) << 8) |
                     uint64_t(k.direction);
        return static_cast<size_t>(mix_u64(a, b));
    }
};

// -----------------------------
// Flow state
// -----------------------------
struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    uint32_t min_pkt = UINT32_MAX;
    uint32_t max_pkt = 0;
    uint8_t  flags = 0; // future extension
};

// -----------------------------
// Configuration
// -----------------------------
struct AnalyzerConfig {
    size_t max_flows = 1'000'000;
    uint64_t idle_timeout_ns = 60ULL * 1'000'000'000ULL;
    uint64_t active_timeout_ns = 30ULL * 60ULL * 1'000'000'000ULL;
    size_t eviction_batch = 4096;
};

// -----------------------------
// Packet parser (IPv4/TCP/UDP minimal)
// Hot path: no exceptions, no heap allocations.
// -----------------------------
class PacketParser {
public:
    struct Parsed {
        FlowKey key{};
        uint32_t payload_len = 0;
        bool valid = false;
    };

    static inline Parsed parse_ipv4(const PacketView& pkt, uint8_t direction) {
        Parsed out;
        out.valid = false;

        // Ethernet header: 14 bytes minimum
        if (unlikely(pkt.len < 14 + 20)) return out;

        const uint8_t* p = pkt.data;
        uint16_t ethertype = (uint16_t(p[12]) << 8) | p[13];
        if (ethertype != 0x0800) return out; // IPv4 only initially

        const uint8_t* ip = p + 14;
        uint8_t ver_ihl = ip[0];
        uint8_t version = ver_ihl >> 4;
        uint8_t ihl = (ver_ihl & 0x0F) * 4;
        if (version != 4 || ihl < 20) return out;
        if (unlikely(pkt.len < 14 + ihl)) return out;

        uint8_t proto = ip[9];
        uint32_t src_ip = *reinterpret_cast<const uint32_t*>(ip + 12);
        uint32_t dst_ip = *reinterpret_cast<const uint32_t*>(ip + 16);

        const uint8_t* l4 = ip + ihl;
        size_t l4_len = pkt.len - (l4 - pkt.data);

        uint16_t src_port = 0, dst_port = 0;
        if (proto == 6 || proto == 17) { // TCP or UDP
            if (unlikely(l4_len < 4)) return out;
            src_port = (uint16_t(l4[0]) << 8) | l4[1];
            dst_port = (uint16_t(l4[2]) << 8) | l4[3];
        } else {
            // Non-port protocols still tracked by 5-tuple-ish identity
            src_port = 0;
            dst_port = 0;
        }

        uint32_t total_len = (uint32_t(ip[2]) << 8) | ip[3];
        if (total_len < ihl) return out;

        out.key = FlowKey{
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
            direction
        };

        out.payload_len = total_len - ihl;
        out.valid = true;
        return out;
    }
};

// -----------------------------
// Flow analyser
// -----------------------------
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(AnalyzerConfig cfg)
        : cfg_(cfg) {
        table_.reserve(cfg_.max_flows);
    }

    void process_packet(const PacketView& pkt, uint8_t direction) {
        auto parsed = PacketParser::parse_ipv4(pkt, direction);
        if (unlikely(!parsed.valid)) return;

        auto it = table_.find(parsed.key);
        if (likely(it != table_.end())) {
            update_flow(it->second, pkt.ts_ns, parsed.payload_len);
        } else {
            if (unlikely(table_.size() >= cfg_.max_flows)) {
                evict_some(pkt.ts_ns);
            }

            auto [insert_it, ok] = table_.emplace(parsed.key, FlowStats{});
            FlowStats& s = insert_it->second;
            s.first_seen_ns = pkt.ts_ns;
            s.last_seen_ns = pkt.ts_ns;
            s.packets = 1;
            s.bytes = parsed.payload_len;
            s.min_pkt = parsed.payload_len;
            s.max_pkt = parsed.payload_len;
        }

        ++processed_packets_;
        processed_bytes_ += pkt.len;
    }

    template <typename Batch>
    void process_batch(const Batch& batch, uint8_t direction) {
        for (const auto& pkt : batch) {
            process_packet(pkt, direction);
        }
    }

    void evict_idle(uint64_t now_ns) {
        if (table_.empty()) return;

        size_t removed = 0;
        for (auto it = table_.begin(); it != table_.end();) {
            if (now_ns - it->second.last_seen_ns > cfg_.idle_timeout_ns ||
                now_ns - it->second.first_seen_ns > cfg_.active_timeout_ns) {
                it = table_.erase(it);
                if (++removed >= cfg_.eviction_batch) break;
            } else {
                ++it;
            }
        }
    }

    uint64_t processed_packets() const { return processed_packets_; }
    uint64_t processed_bytes() const { return processed_bytes_; }
    size_t active_flows() const { return table_.size(); }

    void print_summary() const {
        std::cout << "packets=" << processed_packets_
                  << " bytes=" << processed_bytes_
                  << " active_flows=" << table_.size()
                  << "\n";
    }

private:
    void update_flow(FlowStats& s, uint64_t ts_ns, uint32_t payload_len) {
        s.packets++;
        s.bytes += payload_len;
        s.last_seen_ns = ts_ns;
        if (payload_len < s.min_pkt) s.min_pkt = payload_len;
        if (payload_len > s.max_pkt) s.max_pkt = payload_len;
    }

    void evict_some(uint64_t now_ns) {
        // Simple eviction policy for initial implementation:
        // remove idle/old flows first, otherwise remove arbitrary entries.
        size_t removed = 0;
        for (auto it = table_.begin(); it != table_.end() && removed < cfg_.eviction_batch;) {
            const auto& s = it->second;
            bool expired = (now_ns - s.last_seen_ns > cfg_.idle_timeout_ns) ||
                           (now_ns - s.first_seen_ns > cfg_.active_timeout_ns);
            if (expired || table_.size() > cfg_.max_flows) {
                it = table_.erase(it);
                ++removed;
            } else {
                ++it;
            }
        }
    }

    AnalyzerConfig cfg_;
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table_;
    uint64_t processed_packets_ = 0;
    uint64_t processed_bytes_ = 0;
};

// -----------------------------
// Example usage
// -----------------------------
int main() {
    AnalyzerConfig cfg;
    cfg.max_flows = 500000;
    cfg.idle_timeout_ns = 30ULL * 1'000'000'000ULL;
    cfg.active_timeout_ns = 10ULL * 60ULL * 1'000'000'000ULL;
    cfg.eviction_batch = 2048;

