```rust
use ahash::RandomState;
use crossbeam_channel::{bounded, Receiver, Sender};
use hashbrown::HashMap;
use parking_lot::Mutex;
use serde::Serialize;
use std::net::IpAddr;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: u128,
    dst_ip: u128,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

#[derive(Debug, Clone, Serialize)]
struct FlowRecord {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
    packets: u64,
    bytes: u64,
    first_seen_ms: u128,
    last_seen_ms: u128,
}

#[derive(Debug, Clone)]
struct PacketMeta {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
    bytes: u32,
    timestamp: Instant,
}

#[derive(Debug)]
struct FlowState {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowState {
    fn new(now: Instant, bytes: u32) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, bytes: u32, now: Instant) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

struct FlowTable {
    flows: HashMap<FlowKey, FlowState, RandomState>,
    idle_timeout: Duration,
}

impl FlowTable {
    fn new(idle_timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_hasher(RandomState::new()),
            idle_timeout,
        }
    }

    fn ingest(&mut self, pkt: PacketMeta) {
        let key = FlowKey::from_packet(&pkt);
        let now = pkt.timestamp;

        match self.flows.get_mut(&key) {
            Some(state) => state.update(pkt.bytes, now),
            None => {
                self.flows.insert(key, FlowState::new(now, pkt.bytes));
            }
        }
    }

    fn expire_flows(&mut self) -> Vec<FlowRecord> {
        let now = Instant::now();
        let mut expired = Vec::new();

        let keys_to_remove: Vec<FlowKey> = self
            .flows
            .iter()
            .filter_map(|(k, v)| {
                if now.duration_since(v.last_seen) >= self.idle_timeout {
                    Some(*k)
                } else {
                    None
                }
            })
            .collect();

        for key in keys_to_remove {
            if let Some(state) = self.flows.remove(&key) {
                expired.push(FlowRecord::from_state(key, state));
            }
        }

        expired
    }
}

impl FlowKey {
    fn from_packet(pkt: &PacketMeta) -> Self {
        fn ip_to_u128(ip: IpAddr) -> u128 {
            match ip {
                IpAddr::V4(v4) => u32::from(v4) as u128,
                IpAddr::V6(v6) => u128::from(v6),
            }
        }

        FlowKey {
            src_ip: ip_to_u128(pkt.src_ip),
            dst_ip: ip_to_u128(pkt.dst_ip),
            src_port: pkt.src_port,
            dst_port: pkt.dst_port,
            protocol: pkt.protocol,
        }
    }
}

impl FlowRecord {
    fn from_state(key: FlowKey, state: FlowState) -> Self {
        Self {
            src_ip: format_ip(key.src_ip),
            dst_ip: format_ip(key.dst_ip),
            src_port: key.src_port,
            dst_port: key.dst_port,
            protocol: key.protocol,
            packets: state.packets,
            bytes: state.bytes,
            first_seen_ms: state.first_seen.elapsed().as_millis(),
            last_seen_ms: state.last_seen.elapsed().as_millis(),
        }
    }
}

fn format_ip(v: u128) -> String {
    if v <= u32::MAX as u128 {
        let v4 = v as u32;
        format!(
            "{}.{}.{}.{}",
            (v4 >> 24) & 0xff,
            (v4 >> 16) & 0xff,
            (v4 >> 8) & 0xff,
            v4 & 0xff
        )
    } else {
        let segments = [
            ((v >> 112) & 0xffff) as u16,
            ((v >> 96) & 0xffff) as u16,
            ((v >> 80) & 0xffff) as u16,
            ((v >> 64) & 0xffff) as u16,
            ((v >> 48) & 0xffff) as u16,
            ((v >> 32) & 0xffff) as u16,
            ((v >> 16) & 0xffff) as u16,
            (v & 0xffff) as u16,
        ];
        format!(
            "{:x}:{:x}:{:x}:{:x}:{:x}:{:x}:{:x}:{:x}",
            segments[0], segments[1], segments[2], segments[3],
            segments[4], segments[5], segments[6], segments[7]
        )
    }
}

struct Analyzer {
    flow_table: Arc<Mutex<FlowTable>>,
    tx: Sender<PacketMeta>,
    rx: Receiver<PacketMeta>,
}

impl Analyzer {
    fn new(idle_timeout: Duration, queue_size: usize) -> Self {
        let (tx, rx) = bounded(queue_size);
        Self {
            flow_table: Arc::new(Mutex::new(FlowTable::new(idle_timeout))),
            tx,
            rx,
        }
    }

    fn sender(&self) -> Sender<PacketMeta> {
        self.tx.clone()
    }

    fn run(&self) {
        let table = self.flow_table.clone();
        let rx = self.rx.clone();

        thread::spawn(move || {
            loop {
                match rx.recv() {
                    Ok(pkt) => {
                        table.lock().ingest(pkt);
                    }
                    Err(_) => break,
                }
            }
        });

        let table = self.flow_table.clone();
        thread::spawn(move || loop {
            thread::sleep(Duration::from_millis(500));
            let expired = table.lock().expire_flows();

            for flow in expired {
                println!("Expired flow: {:?}", flow);
            }
        });
    }
}

fn main() {
    let analyzer = Analyzer::new(Duration::from_secs(30), 100_000);
    let tx = analyzer.sender();
    analyzer.run();

    // Example packet stream
    for i in 0..1_000_000u64 {
        let pkt = PacketMeta {
            src_ip: "10.0.0.1".parse().unwrap(),
            dst_ip: "10.0.0.2".parse().unwrap(),
            src_port: 12345,
            dst_port: 443,
            protocol: 6,
            bytes: 1500,
            timestamp: Instant::now(),
        };

        if tx.send(pkt).is_err() {
            break;
        }

        if i % 100_000 == 0 {
            println!("sent {}", i);
        }
    }

    thread::sleep(Duration::from_secs(2));
}
```

