# Go implementation

## `main.go`

```go
package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"net"
	"os"
	"sync"
	"sync/atomic"
	"time"
)

type FlowKey struct {
	SrcIP   [16]byte // IPv4 mapped into 16 bytes for simplicity/future IPv6 support
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	_       uint8
	_2      uint16
}

type FlowStats struct {
	Packets   uint64
	Bytes     uint64
	FirstSeen int64
	LastSeen  int64
	TCPFlags  uint8
}

type FlowEntry struct {
	Key   FlowKey
	Stats FlowStats
}

type Shard struct {
	mu    sync.RWMutex
	flows map[FlowKey]*FlowStats
}

type Analyzer struct {
	shards    []Shard
	numShards  uint32
	totalPkts  atomic.Uint64
	totalBytes atomic.Uint64

	flushInterval time.Duration
	stopCh        chan struct{}
	wg            sync.WaitGroup
}

func NewAnalyzer(numShards int, flushInterval time.Duration) *Analyzer {
	if numShards <= 0 {
		numShards = 64
	}
	a := &Analyzer{
		shards:        make([]Shard, numShards),
		numShards:     uint32(numShards),
		flushInterval: flushInterval,
		stopCh:        make(chan struct{}),
	}
	for i := range a.shards {
		a.shards[i].flows = make(map[FlowKey]*FlowStats, 1<<16)
	}
	return a
}

func (a *Analyzer) shardFor(k FlowKey) *Shard {
	h := fnv1a64(k[:])
	return &a.shards[uint32(h)%a.numShards]
}

// workaround: convert struct to bytes-ish hash without reflection-heavy operations
func fnv1a64(k FlowKey) uint64 {
	const (
		offset64 = 1469598103934665603
		prime64  = 1099511628211
	)
	h := uint64(offset64)

	appendByte := func(b byte) {
		h ^= uint64(b)
		h *= prime64
	}

	for _, b := range k.SrcIP {
		appendByte(b)
	}
	for _, b := range k.DstIP {
		appendByte(b)
	}
	appendByte(byte(k.SrcPort))
	appendByte(byte(k.SrcPort >> 8))
	appendByte(byte(k.DstPort))
	appendByte(byte(k.DstPort >> 8))
	appendByte(k.Proto)

	return h
}

func (a *Analyzer) Update(k FlowKey, bytes uint64, ts int64, tcpFlags uint8) {
	sh := a.shardFor(k)

	sh.mu.RLock()
	fs, ok := sh.flows[k]
	sh.mu.RUnlock()

	if ok {
		atomic.AddUint64(&fs.Packets, 1)
		atomic.AddUint64(&fs.Bytes, bytes)
		atomic.StoreInt64(&fs.LastSeen, ts)
		if tcpFlags != 0 {
			atomic.OrUint8(&fs.TCPFlags, tcpFlags)
		}
		a.totalPkts.Add(1)
		a.totalBytes.Add(bytes)
		return
	}

	sh.mu.Lock()
	fs, ok = sh.flows[k]
	if !ok {
		fs = &FlowStats{
			Packets:   1,
			Bytes:     bytes,
			FirstSeen: ts,
			LastSeen:  ts,
			TCPFlags:  tcpFlags,
		}
		sh.flows[k] = fs
		sh.mu.Unlock()
		a.totalPkts.Add(1)
		a.totalBytes.Add(bytes)
		return
	}
	sh.mu.Unlock()

	atomic.AddUint64(&fs.Packets, 1)
	atomic.AddUint64(&fs.Bytes, bytes)
	atomic.StoreInt64(&fs.LastSeen, ts)
	if tcpFlags != 0 {
		atomic.OrUint8(&fs.TCPFlags, tcpFlags)
	}
	a.totalPkts.Add(1)
	a.totalBytes.Add(bytes)
}

func (a *Analyzer) RunExporter() {
	a.wg.Add(1)
	defer a.wg.Done()

	ticker := time.NewTicker(a.flushInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			a.exportSnapshot()
		case <-a.stopCh:
			a.exportSnapshot()
			return
		}
	}
}

func (a *Analyzer) exportSnapshot() {
	type summary struct {
		Flows     int
		Packets   uint64
		Bytes     uint64
	}

	var totalFlows int
	var totalPackets uint64
	var totalBytes uint64

	for i := range a.shards {
		sh := &a.shards[i]
		sh.mu.RLock()
		for _, fs := range sh.flows {
			totalFlows++
			totalPackets += atomic.LoadUint64(&fs.Packets)
			totalBytes += atomic.LoadUint64(&fs.Bytes)
		}
		sh.mu.RUnlock()
	}

	log.Printf("snapshot: flows=%d packets=%d bytes=%d totalPackets=%d totalBytes=%d",
		totalFlows, totalPackets, totalBytes, a.totalPkts.Load(), a.totalBytes.Load())
}

// Parse Ethernet + IPv4 + TCP/UDP.
// Returns flow key, packet length, timestamp, tcp flags, ok.
func ParsePacket(frame []byte, ts time.Time) (FlowKey, uint64, int64, uint8, bool) {
	if len(frame) < 14 {
		return FlowKey{}, 0, 0, 0, false
	}

	ethType := binary.BigEndian.Uint16(frame[12:14])
	off := 14

	// VLAN tag
	if ethType == 0x8100 || ethType == 0x88a8 {
		if len(frame) < 18 {
			return FlowKey{}, 0, 0, 0, false
		}
		ethType = binary.BigEndian.Uint16(frame[16:18])
		off = 18
	}

	if ethType != 0x0800 { // IPv4 only
		return FlowKey{}, 0, 0, 0, false
	}
	if len(frame) < off+20 {
		return FlowKey{}, 0, 0, 0, false
	}

	verIHL := frame[off]
	if verIHL>>4 != 4 {
		return FlowKey{}, 0, 0, 0, false
	}
	ihl := int(verIHL&0x0F) * 4
	if ihl < 20 || len(frame) < off+ihl {
		return FlowKey{}, 0, 0, 0, false
	}

	proto := frame[off+9]
	totalLen := int(binary.BigEndian.Uint16(frame[off+2 : off+4]))
	if totalLen <= 0 {
		totalLen = len(frame) - off
	}

	var k FlowKey
	copy(k.SrcIP[:4], frame[off+12:off+16])
	copy(k.DstIP[:4], frame[off+16:off+20])
	k.Proto = proto

	l4 := off + ihl
	if proto == 6 || proto == 17 { // TCP/UDP
		if len(frame) < l4+4 {
			return FlowKey{}, 0, 0, 0, false
		}
		k.SrcPort = binary.BigEndian.Uint16(frame[l4 : l4+2])
		k.DstPort = binary.BigEndian.Uint16(frame[l4+2 : l4+4])
	} else {
		// Still count non-TCP/UDP IP traffic with ports zeroed
	}

	var flags uint8
	if proto == 6 && len(frame) >= l4+14 {
		flags = frame[l4+13]
	}

	return k, uint64(totalLen), ts.UnixNano(), flags, true
}

func (a *Analyzer) Stop() {
	close(a.stopCh)
	a.wg.Wait()
}

func (a *Analyzer) ProcessPacket(frame []byte, ts time.Time) {
	k, size, nts, flags, ok := ParsePacket(frame, ts)
	if !ok {
		return
	}
	a.Update(k, size, nts, flags)
}

