## Rust initial implementation

```rust
use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::net::Ipv4Addr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use crossbeam::queue::ArrayQueue;
use parking_lot::RwLock;
use std::thread;

// ---------------------------
// Flow key and stats
// ---------------------------

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: u32,
    pub dst_ip: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

impl FlowStats {
    pub fn new(now: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
        }
    }

    pub fn update(&mut self, pkt_len: usize, now: Instant) {
        self.packets += 1;
        self.bytes += pkt_len as u64;
        self.last_seen = now;
    }
}

// ---------------------------
// Fast hasher
// ---------------------------

// Very simple fast hasher (not cryptographic).
#[derive(Default)]
pub struct FxHasher(u64);

impl Hasher for FxHasher {
    fn write(&mut self, bytes: &[u8]) {
        for b in bytes {
            self.0 = self.0.rotate_left(5) ^ (*b as u64);
        }
    }

    fn finish(&self) -> u64 {
        self.0
    }
}

type FxBuildHasher = BuildHasherDefault<FxHasher>;

// ---------------------------
// Flow table with sharding
// ---------------------------

pub struct FlowTable {
    shards: Vec<RwLock<HashMap<FlowKey, FlowStats, FxBuildHasher>>>,
}

impl FlowTable {
    pub fn new(shard_count: usize) -> Self {
        let mut shards = Vec::with_capacity(shard_count);
        for _ in 0..shard_count {
            shards.push(RwLock::new(HashMap::with_hasher(FxBuildHasher::default())));
        }
        Self { shards }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        let hash = (key.src_ip as u64)
            ^ ((key.dst_ip as u64) << 1)
            ^ ((key.src_port as u64) << 16)
            ^ ((key.dst_port as u64) << 32)
            ^ ((key.protocol as u64) << 48);
        (hash as usize) % self.shards.len()
    }

    pub fn update_flow(&self, key: FlowKey, pkt_len: usize, now: Instant) {
        let idx = self.shard_index(&key);
        let mut shard = self.shards[idx].write();
        let entry = shard.entry(key).or_insert_with(|| FlowStats::new(now));
        entry.update(pkt_len, now);
    }

    pub fn expire_inactive(&self, idle_timeout: Duration) -> Vec<(FlowKey, FlowStats)> {
        let now = Instant::now();
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.write();
            let keys_to_remove: Vec<FlowKey> = map
                .iter()
                .filter_map(|(k, v)| {
                    if now.duration_since(v.last_seen) > idle_timeout {
                        Some(*k)
                    } else {
                        None
                    }
                })
                .collect();

            for key in keys_to_remove {
                if let Some(stats) = map.remove(&key) {
                    expired.push((key, stats));
                }
            }
        }

        expired
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        let mut all = Vec::new();
        for shard in &self.shards {
            let map = shard.read();
            all.extend(map.iter().map(|(k, v)| (*k, v.clone())));
        }
        all
    }
}

// ---------------------------
// Minimal packet parsing
// ---------------------------

#[derive(Debug)]
pub enum ParseError {
    TooShort,
    NotIpv4,
    UnsupportedProtocol,
    Malformed,
}

pub struct PacketInfo {
    pub key: FlowKey,
    pub len: usize,
}

pub fn parse_ipv4_packet(packet: &[u8]) -> Result<PacketInfo, ParseError> {
    // Ethernet header assumed present: 14 bytes
    if packet.len() < 14 + 20 {
        return Err(ParseError::TooShort);
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return Err(ParseError::NotIpv4);
    }

    let ip_start = 14;
    let version_ihl = packet[ip_start];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || ihl < 20 || packet.len() < ip_start + ihl {
        return Err(ParseError::Malformed);
    }

    let protocol = packet[ip_start + 9];
    let src_ip = u32::from_be_bytes([
        packet[ip_start + 12],
        packet[ip_start + 13],
        packet[ip_start + 14],
        packet[ip_start + 15],
    ]);
    let dst_ip = u32::from_be_bytes([
        packet[ip_start + 16],
        packet[ip_start + 17],
        packet[ip_start + 18],
        packet[ip_start + 19],
    ]);

    let l4_start = ip_start + ihl;
    let (src_port, dst_port) = match protocol {
        6 | 17 => {
            if packet.len() < l4_start + 4 {
                return Err(ParseError::TooShort);
            }
            let src_port = u16::from_be_bytes([packet[l4_start], packet[l4_start + 1]]);
            let dst_port = u16::from_be_bytes([packet[l4_start + 2], packet[l4_start + 3]]);
            (src_port, dst_port)
        }
        _ => return Err(ParseError::UnsupportedProtocol),
    };

    Ok(PacketInfo {
        key: FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            protocol,
        },
        len: packet.len(),
    })
}

// ---------------------------
// Analyzer
// ---------------------------

pub struct AnalyzerConfig {
    pub shard_count: usize,
    pub idle_timeout: Duration,
    pub expire_interval: Duration,
    pub worker_threads: usize,
    pub queue_size: usize,
}

pub struct FlowAnalyzer {
    table: Arc<FlowTable>,
    queue: Arc<ArrayQueue<Vec<u8>>>,
    cfg: AnalyzerConfig,
}

impl FlowAnalyzer {
    pub fn new(cfg: AnalyzerConfig) -> Self {
        Self {
            table: Arc::new(FlowTable::new(cfg.shard_count)),
            queue: Arc::new(ArrayQueue::new(cfg.queue_size)),
            cfg,
        }
    }

    pub fn start(&self) {
        for _ in 0..self.cfg.worker_threads {
            let table = Arc::clone(&self.table);
            let queue = Arc::clone(&self.queue);

            thread::spawn(move || loop {
                if let Some(pkt) = queue.pop() {
                    let now = Instant::now();
                    if let Ok(info) = parse_ipv4_packet(&pkt) {
                        table.update_flow(info.key, info.len, now);
                    }
                } else {
                    thread::yield_now();
                }
            });
        }

        let table = Arc::clone(&self.table);
        let idle_timeout = self.cfg.idle_timeout;
        let expire_interval = self.cfg.expire_interval;

        thread::spawn(move || loop {
            thread::sleep(expire_interval);
            let expired = table.expire_inactive(idle_timeout);
            if !expired.is_empty() {
                for (key, stats) in expired {
                    println!(
                        "Expired flow {:?}: packets={}, bytes={}",
                        key, stats.packets, stats.bytes
                    );
                }
            }
        });
    }

    pub fn ingest_packet(&self, packet: Vec<u8>) -> Result<(), &'static str> {
        self.queue.push(packet).map_err(|_| "queue full")
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        self.table.snapshot()
    }
}

// ---------------------------
// Example usage
// ---------------------------

fn main() {
    let analyzer = FlowAnalyzer::new(AnalyzerConfig {
        shard_count: 64,
        idle_timeout: Duration::from_secs(30),
        expire_interval: Duration::from_secs(5),
        worker_threads: 4,
        queue_size: 100_000,
    });

    analyzer.start();

    // Simulated packet ingestion
    loop {
        let fake_packet = vec![0u8; 64];
        let _ = analyzer.ingest_packet(fake_packet);
        thread::sleep(Duration::from_micros(10));
    }
}
