## Rust implementation

```rust
use std::collections::HashMap;
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Hash, Eq, PartialEq)]
pub struct FlowKey {
    pub src_ip: u32,
    pub dst_ip: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
    pub tcp_flags_seen: u8,
}

impl FlowStats {
    pub fn new(ts: Instant, bytes: usize, tcp_flags: u8) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: ts,
            last_seen: ts,
            tcp_flags_seen: tcp_flags,
        }
    }

    pub fn update(&mut self, ts: Instant, bytes: usize, tcp_flags: u8) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = ts;
        self.tcp_flags_seen |= tcp_flags;
    }
}

pub struct FlowAnalyzer {
    flows: HashMap<FlowKey, FlowStats>,
    idle_timeout: Duration,
    on_expire: Option<Box<dyn FnMut(FlowKey, FlowStats) + Send>>,
}

impl FlowAnalyzer {
    pub fn new(idle_timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_capacity(1 << 20),
            idle_timeout,
            on_expire: None,
        }
    }

    pub fn with_expire_callback<F>(mut self, callback: F) -> Self
    where
        F: FnMut(FlowKey, FlowStats) + Send + 'static,
    {
        self.on_expire = Some(Box::new(callback));
        self
    }

    /// Process a single packet.
    pub fn process_packet(&mut self, packet: &[u8], ts: Instant) {
        // Minimal Ethernet + IPv4 parsing assumption:
        // Ethernet header = 14 bytes
        if packet.len() < 14 {
            return;
        }

        let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
        if ethertype != 0x0800 {
            // IPv4 only for now
            return;
        }

        let ip = &packet[14..];
        if ip.len() < 20 {
            return;
        }

        let version_ihl = ip[0];
        let version = version_ihl >> 4;
        if version != 4 {
            return;
        }

        let ihl = (version_ihl & 0x0F) as usize * 4;
        if ip.len() < ihl || ihl < 20 {
            return;
        }

        let proto = ip[9];
        let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
        let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);
        let payload = &ip[ihl..];

        let (src_port, dst_port, tcp_flags) = match proto {
            6 => {
                // TCP
                if payload.len() < 20 {
                    return;
                }
                let src_port = u16::from_be_bytes([payload[0], payload[1]]);
                let dst_port = u16::from_be_bytes([payload[2], payload[3]]);
                let data_offset = ((payload[12] >> 4) as usize) * 4;
                if payload.len() < data_offset || data_offset < 20 {
                    return;
                }
                let flags = payload[13];
                (src_port, dst_port, flags)
            }
            17 => {
                // UDP
                if payload.len() < 8 {
                    return;
                }
                let src_port = u16::from_be_bytes([payload[0], payload[1]]);
                let dst_port = u16::from_be_bytes([payload[2], payload[3]]);
                (src_port, dst_port, 0)
            }
            _ => return,
        };

        let key = FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        };

        let bytes = packet.len();
        self.flows
            .entry(key)
            .and_modify(|stats| stats.update(ts, bytes, tcp_flags))
            .or_insert_with(|| FlowStats::new(ts, bytes, tcp_flags));
    }

    /// Expire old flows. Call periodically from the capture loop.
    pub fn expire_flows(&mut self, now: Instant) {
        let timeout = self.idle_timeout;
        let mut expired = Vec::new();

        self.flows.retain(|&key, stats| {
            let alive = now.duration_since(stats.last_seen) <= timeout;
            if !alive {
                expired.push((key, stats.clone()));
            }
            alive
        });

        if let Some(cb) = self.on_expire.as_mut() {
            for (key, stats) in expired {
                cb(key, stats);
            }
        }
    }

    pub fn active_flow_count(&self) -> usize {
        self.flows.len()
    }

    pub fn iter_flows(&self) -> impl Iterator<Item = (&FlowKey, &FlowStats)> {
        self.flows.iter()
    }
}
