### `main.go`

```go
package main

import (
	"encoding/binary"
	"fmt"
	"hash/fnv"
	"net"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

const (
	NumShards      = 256
	FlowTTL        = 60 * time.Second
	EvictInterval  = 5 * time.Second
	BatchSize      = 2048
	ChannelSize    = 65536
	MaxPendingFlow = 1 << 20
)

type FlowKey struct {
	SrcIP   [16]byte
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	IsIPv6  bool
}

type FlowStats struct {
	Packets     uint64
	Bytes       uint64
	FirstSeenNs  uint64
	LastSeenNs   uint64
	TCPFlagsOR   uint8
	TCPFlagsAND  uint8
	DirectionAB  uint64
	DirectionBA  uint64
}

type FlowEntry struct {
	Key   FlowKey
	Stats FlowStats
}

type Packet struct {
	SrcIP    net.IP
	DstIP    net.IP
	SrcPort  uint16
	DstPort  uint16
	Proto    uint8
	Length   uint32
	TCPFlags uint8
	Ts       time.Time
}

type shard struct {
	mu    sync.Mutex
	flows map[FlowKey]*FlowStats
}

type Analyzer struct {
	shards      [NumShards]shard
	ingestCh    chan Packet
	stopCh      chan struct{}
	wg         sync.WaitGroup
	totalPkts   atomic.Uint64
	totalBytes  atomic.Uint64
	droppedPkts atomic.Uint64
}

func NewAnalyzer() *Analyzer {
	a := &Analyzer{
		ingestCh: make(chan Packet, ChannelSize),
		stopCh:   make(chan struct{}),
	}
	for i := 0; i < NumShards; i++ {
		a.shards[i].flows = make(map[FlowKey]*FlowStats, 4096)
	}
	return a
}

func (a *Analyzer) Start(workers int) {
	for i := 0; i < workers; i++ {
		a.wg.Add(1)
		go a.worker()
	}
	a.wg.Add(1)
	go a.evictionLoop()
}

func (a *Analyzer) Stop() {
	close(a.stopCh)
	a.wg.Wait()
}

func (a *Analyzer) Submit(p Packet) {
	select {
	case a.ingestCh <- p:
	default:
		a.droppedPkts.Add(1)
	}
}

func (a *Analyzer) worker() {
	defer a.wg.Done()

	batch := make([]Packet, 0, BatchSize)
	ticker := time.NewTicker(2 * time.Millisecond)
	defer ticker.Stop()

	flush := func() {
		if len(batch) == 0 {
			return
		}
		a.processBatch(batch)
		batch = batch[:0]
	}

	for {
		select {
		case <-a.stopCh:
			flush()
			return
		case p := <-a.ingestCh:
			batch = append(batch, p)
			if len(batch) >= BatchSize {
				flush()
			}
		case <-ticker.C:
			flush()
		}
	}
}

func (a *Analyzer) processBatch(batch []Packet) {
	for _, p := range batch {
		key := normalizeFlowKey(p.SrcIP, p.DstIP, p.SrcPort, p.DstPort, p.Proto)
		sh := &a.shards[shardIndex(key)]
		now := uint64(p.Ts.UnixNano())

		sh.mu.Lock()
		fs, ok := sh.flows[key]
		if !ok {
			fs = &FlowStats{
				FirstSeenNs: now,
				LastSeenNs:  now,
				TCPFlagsOR:  p.TCPFlags,
				TCPFlagsAND: p.TCPFlags,
			}
			sh.flows[key] = fs
		}
		fs.Packets++
		fs.Bytes += uint64(p.Length)
		fs.LastSeenNs = now
		fs.TCPFlagsOR |= p.TCPFlags
		fs.TCPFlagsAND &= p.TCPFlags
		a.totalPkts.Add(1)
		a.totalBytes.Add(uint64(p.Length))
		sh.mu.Unlock()
	}
}

func (a *Analyzer) evictionLoop() {
	defer a.wg.Done()
	t := time.NewTicker(EvictInterval)
	defer t.Stop()

	for {
		select {
		case <-a.stopCh:
			return
		case <-t.C:
			cutoff := uint64(time.Now().Add(-FlowTTL).UnixNano())
			for i := 0; i < NumShards; i++ {
				sh := &a.shards[i]
				sh.mu.Lock()
				for k, v := range sh.flows {
					if v.LastSeenNs < cutoff {
						delete(sh.flows, k)
					}
				}
				sh.mu.Unlock()
			}
		}
	}
}

func normalizeFlowKey(src, dst net.IP, sport, dport uint16, proto uint8) FlowKey {
	var k FlowKey
	k.Proto = proto

	src16 := ipTo16(src)
	dst16 := ipTo16(dst)
	if lessIP(src16, dst16) || (equalIP(src16, dst16) && sport <= dport) {
		copy(k.SrcIP[:], src16)
		copy(k.DstIP[:], dst16)
		k.SrcPort = sport
		k.DstPort = dport
	} else {
		copy(k.SrcIP[:], dst16)
		copy(k.DstIP[:], src16)
		k.SrcPort = dport
		k.DstPort = sport
	}

	k.IsIPv6 = src.To4() == nil || dst.To4() == nil
	return k
}

func ipTo16(ip net.IP) [16]byte {
	var out [16]byte
	if ip4 := ip.To4(); ip4 != nil {
		copy(out[12:], ip4)
		return out
	}
	ip16 := ip.To16()
	if ip16 != nil {
		copy(out[:], ip16)
	}
	return out
}

func lessIP(a, b [16]byte) bool {
	return bytesCompare(a[:], b[:]) < 0
}

func equalIP(a, b [16]byte) bool {
	return bytesCompare(a[:], b[:]) == 0
}

func bytesCompare(a, b []byte) int {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i] < b[i] {
			return -1
		}
		if a[i] > b[i] {
			return 1
		}
	}
	switch {
	case len(a) < len(b):
		return -1
	case len(a) > len(b):
		return 1
	default:
		return 0
	}
}

func shardIndex(k FlowKey) int {
	h := fnv.New64a()
	h.Write(k.SrcIP[:])
	h.Write(k.DstIP[:])
	var b [5]byte
	binary.LittleEndian.PutUint16(b[0:2], k.SrcPort)
	binary.LittleEndian.PutUint16(b[2:4], k.DstPort)
	b[4] = k.Proto
	h.Write(b[:])
	return int(h.Sum64() % NumShards)
}

func (a *Analyzer) SnapshotTopN(n int) []FlowEntry {
	var out []FlowEntry
	for i := 0; i < NumShards; i++ {
		sh := &a.shards[i]
		sh.mu.Lock()
		for k, v := range sh.flows {
			out = append(out, FlowEntry{Key: k, Stats: *v})
		}
		sh.mu.Unlock()
	}
	sort.Slice(out, func(i, j int) bool {
		return out[i].Stats.Bytes > out[j].Stats.Bytes
	})
	if n > len(out) {
		n = len(out)
	}
	return out[:n]
}

func main() {
	analyzer := NewAnalyzer()
	analyzer.Start(4)
	defer analyzer.Stop()

	// Example synthetic packets
	now := time.Now()
	analyzer.Submit(Packet{
		SrcIP: net.ParseIP("10.0.0.1"), DstIP: net.ParseIP("10.0.0.2"),
		SrcPort: 12345, DstPort: 443, Proto: 6, Length: 1500, TCPFlags: 0x18, Ts: now,
	})
	analyzer.Submit(Packet{
		SrcIP: net.ParseIP("10.0.0.2"), DstIP: net.ParseIP("10.0.0.1"),
		SrcPort: 443, DstPort: 12345, Proto: 6, Length: 1200, TCPFlags: 0x10, Ts: now.Add(time.Millisecond),
	})

	time.Sleep(100 * time.Millisecond)

	top := analyzer.SnapshotTopN(10)
	for _, f := range top {
		fmt.Printf("%v:%d <-> %v:%d proto=%d packets=%d bytes=%d\n",
			net.IP(f.Key.SrcIP[:]), f.Key.SrcPort, net.IP(f.Key.DstIP[:]), f.Key.DstPort,
			f.Key.Proto, f.Stats.Packets, f.Stats.Bytes)
	}
}
