use ahash::AHasher;
use parking_lot::Mutex;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::IpAddr;
use std::sync::Arc;
use std::time::{Duration, Instant};

const NUM_SHARDS: usize = 64;
const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Debug, Clone)]
pub struct PacketMeta {
    pub timestamp: Instant,
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
    pub length_bytes: usize,
}

#[derive(Debug, Default, Clone)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

impl FlowStats {
    pub fn new(ts: Instant, len: usize) -> Self {
        Self {
            packets: 1,
            bytes: len as u64,
            first_seen: ts,
            last_seen: ts,
        }
    }

    pub fn update(&mut self, ts: Instant, len: usize) {
        self.packets += 1;
        self.bytes += len as u64;
        self.last_seen = ts;
    }

    pub fn idle_for(&self, now: Instant) -> Duration {
        now.duration_since(self.last_seen)
    }
}

#[derive(Debug)]
struct Shard {
    flows: HashMap<FlowKey, FlowStats>,
}

impl Shard {
    fn new() -> Self {
        Self {
            flows: HashMap::with_capacity(16_384),
        }
    }
}

#[derive(Clone)]
pub struct FlowAnalyzer {
    shards: Arc<Vec<Mutex<Shard>>>,
    idle_timeout: Duration,
}

impl FlowAnalyzer {
    pub fn new(num_shards: usize, idle_timeout: Duration) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(Mutex::new(Shard::new()));
        }
        Self {
            shards: Arc::new(shards),
            idle_timeout,
        }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % self.shards.len()
    }

    #[inline]
    fn normalize_key(packet: &PacketMeta) -> FlowKey {
        FlowKey {
            src_ip: packet.src_ip,
            dst_ip: packet.dst_ip,
            src_port: packet.src_port,
            dst_port: packet.dst_port,
            protocol: packet.protocol,
        }
    }

    pub fn process_packet(&self, packet: PacketMeta) {
        let key = Self::normalize_key(&packet);
        let shard_idx = self.shard_index(&key);
        let mut shard = self.shards[shard_idx].lock();

        match shard.flows.get_mut(&key) {
            Some(stats) => stats.update(packet.timestamp, packet.length_bytes),
            None => {
                shard
                    .flows
                    .insert(key, FlowStats::new(packet.timestamp, packet.length_bytes));
            }
        }
    }

    pub fn expire_flows(&self, now: Instant) -> usize {
        let mut removed = 0usize;

        for shard_mutex in self.shards.iter() {
            let mut shard = shard_mutex.lock();
            let timeout = self.idle_timeout;

            shard.flows.retain(|_, stats| {
                let keep = now.duration_since(stats.last_seen) <= timeout;
                if !keep {
                    removed += 1;
                }
                keep
            });
        }

        removed
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowStats)> {
        let mut all = Vec::new();

        for shard_mutex in self.shards.iter() {
            let shard = shard_mutex.lock();
            all.extend(shard.flows.iter().map(|(k, v)| (*k, v.clone())));
        }

        all
    }

    pub fn flow_count(&self) -> usize {
        self.shards
            .iter()
            .map(|s| s.lock().flows.len())
            .sum()
    }
}

fn main() {
    let analyzer = FlowAnalyzer::new(NUM_SHARDS, FLOW_IDLE_TIMEOUT);

    // Example packet stream
    let start = Instant::now();
    let packets = vec![
        PacketMeta {
            timestamp: start,
            src_ip: "10.0.0.1".parse().unwrap(),
            dst_ip: "10.0.0.2".parse().unwrap(),
            src_port: 12345,
            dst_port: 80,
            protocol: 6, // TCP
            length_bytes: 1500,
        },
        PacketMeta {
            timestamp: start + Duration::from_millis(1),
            src_ip: "10.0.0.1".parse().unwrap(),
            dst_ip: "10.0.0.2".parse().unwrap(),
            src_port: 12345,
            dst_port: 80,
            protocol: 6,
            length_bytes: 900,
        },
        PacketMeta {
            timestamp: start + Duration::from_millis(2),
            src_ip: "10.0.0.3".parse().unwrap(),
            dst_ip: "10.0.0.4".parse().unwrap(),
            src_port: 54321,
            dst_port: 443,
            protocol: 6,
            length_bytes: 1200,
        },
    ];

    for pkt in packets {
        analyzer.process_packet(pkt);
    }

    println!("Active flows: {}", analyzer.flow_count());

    let snapshot = analyzer.snapshot();
    for (key, stats) in snapshot {
        println!(
            "{:?} -> packets={}, bytes={}, first_seen={:?}, last_seen={:?}",
            key, stats.packets, stats.bytes, stats.first_seen, stats.last_seen
        );
    }

    let removed = analyzer.expire_flows(Instant::now() + Duration::from_secs(60));
    println!("Expired flows: {}", removed);
}
