## 2) Initial Python implementation

This version is useful for correctness validation and interfaces, but **not** for true gigabit throughput.

It assumes packet records are already available as `(timestamp_ns, src_ip, dst_ip, src_port, dst_port, proto, length)`.

```python
from dataclasses import dataclass
from typing import Dict, Tuple, Iterable, List
import time

FlowKey = Tuple[int, int, int, int, int]  # src_ip, dst_ip, src_port, dst_port, proto


@dataclass
class FlowStats:
    packets: int = 0
    bytes: int = 0
    first_seen_ns: int = 0
    last_seen_ns: int = 0
    tcp_flags: int = 0


class FlowAnalyzer:
    def __init__(self, idle_timeout_ns: int = 30_000_000_000, max_flows: int = 1_000_000):
        self.idle_timeout_ns = idle_timeout_ns
        self.max_flows = max_flows
        self.flows: Dict[FlowKey, FlowStats] = {}

    def update_flow(
        self,
        timestamp_ns: int,
        src_ip: int,
        dst_ip: int,
        src_port: int,
        dst_port: int,
        proto: int,
        length: int,
        tcp_flags: int = 0,
    ) -> None:
        key = (src_ip, dst_ip, src_port, dst_port, proto)
        flow = self.flows.get(key)
        if flow is None:
            if len(self.flows) >= self.max_flows:
                self.evict_expired(timestamp_ns)
                if len(self.flows) >= self.max_flows:
                    self.evict_oldest()
            flow = FlowStats(
                packets=1,
                bytes=length,
                first_seen_ns=timestamp_ns,
                last_seen_ns=timestamp_ns,
                tcp_flags=tcp_flags,
            )
            self.flows[key] = flow
        else:
            flow.packets += 1
            flow.bytes += length
            flow.last_seen_ns = timestamp_ns
            flow.tcp_flags |= tcp_flags

    def evict_expired(self, now_ns: int) -> int:
        expired = []
        timeout = self.idle_timeout_ns
        for key, flow in self.flows.items():
            if now_ns - flow.last_seen_ns > timeout:
                expired.append(key)

        for key in expired:
            del self.flows[key]

        return len(expired)

    def evict_oldest(self) -> None:
        if not self.flows:
            return
        oldest_key = min(self.flows.items(), key=lambda kv: kv[1].last_seen_ns)[0]
        del self.flows[oldest_key]

    def flush(self) -> List[Tuple[FlowKey, FlowStats]]:
        items = list(self.flows.items())
        self.flows.clear()
        return items


# Example usage
if __name__ == "__main__":
    analyzer = FlowAnalyzer()

    packets = [
        (1_000, 0x0A000001, 0x0A000002, 12345, 80, 6, 64, 0x02),
        (2_000, 0x0A000001, 0x0A000002, 12345, 80, 6, 128, 0x18),
        (3_000, 0x0A000002, 0x0A000001, 80, 12345, 6, 64, 0x10),
    ]

    for p in packets:
        analyzer.update_flow(*p)

    for k, v in analyzer.flush():
        print(k, v)
