use ahash::RandomState;
use hashbrown::HashMap;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(C)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    _pad: u8,
}

#[derive(Clone, Copy, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ns: u64,
    last_seen_ns: u64,
    tcp_flags: u8,
}

impl FlowStats {
    fn new(ts_ns: u64, len: u64, tcp_flags: u8) -> Self {
        Self {
            packets: 1,
            bytes: len,
            first_seen_ns: ts_ns,
            last_seen_ns: ts_ns,
            tcp_flags,
        }
    }

    fn update(&mut self, ts_ns: u64, len: u64, tcp_flags: u8) {
        self.packets += 1;
        self.bytes += len;
        self.last_seen_ns = ts_ns;
        self.tcp_flags |= tcp_flags;
    }
}

struct FlowAnalyzer {
    flows: HashMap<FlowKey, FlowStats, RandomState>,
    idle_timeout_ns: u64,
    max_flows: usize,
}

impl FlowAnalyzer {
    fn with_capacity(max_flows: usize, idle_timeout: Duration) -> Self {
        let cap = max_flows.next_power_of_two();
        Self {
            flows: HashMap::with_capacity_and_hasher(cap, RandomState::new()),
            idle_timeout_ns: idle_timeout.as_nanos() as u64,
            max_flows,
        }
    }

    #[inline]
    fn update_flow(
        &mut self,
        ts_ns: u64,
        src_ip: u32,
        dst_ip: u32,
        src_port: u16,
        dst_port: u16,
        proto: u8,
        length: u64,
        tcp_flags: u8,
    ) {
        if self.flows.len() >= self.max_flows {
            self.evict_expired(ts_ns);
            if self.flows.len() >= self.max_flows {
                self.evict_some_oldest();
            }
        }

        let key = FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
            _pad: 0,
        };

        match self.flows.get_mut(&key) {
            Some(stats) => stats.update(ts_ns, length, tcp_flags),
            None => {
                self.flows.insert(key, FlowStats::new(ts_ns, length, tcp_flags));
            }
        }
    }

    fn evict_expired(&mut self, now_ns: u64) -> usize {
        let timeout = self.idle_timeout_ns;
        let before = self.flows.len();
        self.flows.retain(|_, v| now_ns.saturating_sub(v.last_seen_ns) <= timeout);
        before - self.flows.len()
    }

    fn evict_some_oldest(&mut self) {
        if self.flows.is_empty() {
            return;
        }

        // Initial simple fallback: remove a flow with the oldest last_seen.
        // For production, maintain a min-heap or time wheel for O(log n) or amortized O(1) eviction.
        let oldest_key = self
            .flows
            .iter()
            .min_by_key(|(_, v)| v.last_seen_ns)
            .map(|(k, _)| *k);

        if let Some(k) = oldest_key {
            self.flows.remove(&k);
        }
    }

    fn flush(&mut self) -> Vec<(FlowKey, FlowStats)> {
        self.flows.drain().collect()
    }
}

fn now_ns() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64
}

fn main() {
    let mut analyzer = FlowAnalyzer::with_capacity(1_000_000, Duration::from_secs(30));

    // Simulated packet events:
    let ts = now_ns();
    analyzer.update_flow(ts, 0x0A00_0001, 0x0A00_0002, 12345, 80, 6, 64, 0x02);
    analyzer.update_flow(ts + 1_000, 0x0A00_0001, 0x0A00_0002, 12345, 80, 6, 128, 0x18);
    analyzer.update_flow(ts + 2_000, 0x0A00_0002, 0x0A00_0001, 80, 12345, 6, 64, 0x10);

    for (key, stats) in analyzer.flush() {
        println!("{:?} => {:?}", key, stats);
    }
}
