## 2) Go Implementation

### `main.go`
```go
package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"net"
	"sync"
	"sync/atomic"
	"time"
)

const (
	numShards       = 256
	workerCount     = 8
	inputBufferSize = 65536
	flowIdleTimeout = 30 * time.Second
	sweepInterval   = 5 * time.Second
)

type FlowKey struct {
	SrcIP   [16]byte
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	_       [5]byte // padding for alignment
}

func NewFlowKey(srcIP, dstIP net.IP, srcPort, dstPort uint16, proto uint8) FlowKey {
	var k FlowKey
	copyIP(&k.SrcIP, srcIP)
	copyIP(&k.DstIP, dstIP)
	k.SrcPort = srcPort
	k.DstPort = dstPort
	k.Proto = proto
	return k
}

func copyIP(dst *[16]byte, ip net.IP) {
	v4 := ip.To4()
	if v4 != nil {
		// Store IPv4 in the low 4 bytes, zero-padded.
		copy(dst[12:], v4)
		return
	}
	v6 := ip.To16()
	if v6 != nil {
		copy(dst[:], v6)
	}
}

type FlowStats struct {
	FirstSeen   time.Time
	LastSeen    time.Time
	Packets     uint64
	Bytes       uint64
	SourceBytes uint64
	DestBytes   uint64
}

type Flow struct {
	Key   FlowKey
	Stats FlowStats
}

type FlowTable struct {
	mu    sync.RWMutex
	flows map[FlowKey]*Flow
}

func NewFlowTable() *FlowTable {
	return &FlowTable{
		flows: make(map[FlowKey]*Flow, 1<<16),
	}
}

type Analyzer struct {
	shards [numShards]*FlowTable

	incoming chan *Packet
	stopCh   chan struct{}
	wg       sync.WaitGroup

	processed uint64
}

type Packet struct {
	SrcIP   net.IP
	DstIP   net.IP
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	Len     uint64
	TS      time.Time
}

var packetPool = sync.Pool{
	New: func() any {
		return &Packet{}
	},
}

func NewAnalyzer() *Analyzer {
	a := &Analyzer{
		incoming: make(chan *Packet, inputBufferSize),
		stopCh:   make(chan struct{}),
	}
	for i := 0; i < numShards; i++ {
		a.shards[i] = NewFlowTable()
	}
	return a
}

func (a *Analyzer) Start() {
	for i := 0; i < workerCount; i++ {
		a.wg.Add(1)
		go a.worker()
	}

	a.wg.Add(1)
	go a.expirer()
}

func (a *Analyzer) Stop() {
	close(a.stopCh)
	a.wg.Wait()
}

func (a *Analyzer) Submit(pkt *Packet) {
	select {
	case a.incoming <- pkt:
	default:
		// Backpressure drop: in a production system, count drops here.
		packetPool.Put(pkt)
	}
}

func (a *Analyzer) worker() {
	defer a.wg.Done()
	for {
		select {
		case pkt := <-a.incoming:
			if pkt == nil {
				continue
			}
			a.processPacket(pkt)
			packetPool.Put(pkt)
			atomic.AddUint64(&a.processed, 1)
		case <-a.stopCh:
			return
		}
	}
}

func (a *Analyzer) processPacket(pkt *Packet) {
	key := NewFlowKey(pkt.SrcIP, pkt.DstIP, pkt.SrcPort, pkt.DstPort, pkt.Proto)
	shard := &a.shards[flowShard(key)]

	shard.mu.RLock()
	flow := shard.flows[key]
	shard.mu.RUnlock()

	if flow != nil {
		flow.Stats.Packets++
		flow.Stats.Bytes += pkt.Len
		flow.Stats.LastSeen = pkt.TS
		return
	}

	shard.mu.Lock()
	defer shard.mu.Unlock()

	flow = shard.flows[key]
	if flow == nil {
		flow = &Flow{
			Key: key,
			Stats: FlowStats{
				FirstSeen: pkt.TS,
				LastSeen:  pkt.TS,
				Packets:   1,
				Bytes:     pkt.Len,
			},
		}
		shard.flows[key] = flow
		return
	}

	flow.Stats.Packets++
	flow.Stats.Bytes += pkt.Len
	flow.Stats.LastSeen = pkt.TS
}

func (a *Analyzer) expirer() {
	defer a.wg.Done()
	ticker := time.NewTicker(sweepInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			now := time.Now()
			for i := 0; i < numShards; i++ {
				table := a.shards[i]
				table.mu.Lock()
				for k, f := range table.flows {
					if now.Sub(f.Stats.LastSeen) > flowIdleTimeout {
						delete(table.flows, k)
						// Hook for export/flush:
						a.exportFlow(f)
					}
				}
				table.mu.Unlock()
			}
		case <-a.stopCh:
			return
		}
	}
}

func (a *Analyzer) exportFlow(f *Flow) {
	// Replace this with a real exporter: Kafka, Prometheus, ClickHouse, etc.
	fmt.Printf(
		"flow src=%v dst=%v proto=%d packets=%d bytes=%d first=%s last=%s\n",
		formatIP(f.Key.SrcIP),
		formatIP(f.Key.DstIP),
		f.Key.Proto,
		f.Stats.Packets,
		f.Stats.Bytes,
		f.Stats.FirstSeen.Format(time.RFC3339Nano),
		f.Stats.LastSeen.Format(time.RFC3339Nano),
	)
}

func flowShard(key FlowKey) uint8 {
	// Simple fast hash; good enough for initial implementation.
	var h uint64
	h ^= binary.LittleEndian.Uint64(key.SrcIP[0:8])
	h ^= binary.LittleEndian.Uint64(key.SrcIP[8:16])
	h ^= binary.LittleEndian.Uint64(key.DstIP[0:8])
	h ^= binary.LittleEndian.Uint64(key.DstIP[8:16])
	h ^= uint64(key.SrcPort)<<16 | uint64(key.DstPort)
	h ^= uint64(key.Proto)
	h ^= h >> 33
	h *= 0xff51afd7ed558ccd
	h ^= h >> 33
	h *= 0xc4ceb9fe1a85ec53
	h ^= h >> 33
	return uint8(h % numShards)
}

func formatIP(ip16 [16]byte) net.IP {
	// Try IPv4 form if leading 12 bytes are zero.
	if ip16[0] == 0 && ip16[1] == 0 && ip16[2] == 0 && ip16[3] == 0 &&
		ip16[4] == 0 && ip16[5] == 0 && ip16[6] == 0 && ip16[7] == 0 &&
		ip16[8] == 0 && ip16[9] == 0 && ip16[10] == 0 && ip16[11] == 0 {
		return net.IPv4(ip16[12], ip16[13], ip16[14], ip16[15])
	}
	return net.IP(ip16[:])
}

func main() {
	analyzer := NewAnalyzer()
	analyzer.Start()
	defer analyzer.Stop()

	// Demo traffic generator
	go func() {
		for i := 0; i < 100000; i++ {
			p := packetPool.Get().(*Packet)
			p.SrcIP = net.IPv4(10, 0, 0, byte(i%250))
			p.DstIP = net.IPv4(192, 168, 1, byte((i/250)%250))
			p.SrcPort = 10000 + uint16(i%1000)
			p.DstPort = 80
			p.Proto = 6
			p.Len = 64 + uint64(i%1400)
			p.TS = time.Now()
			analyzer.Submit(p)
		}
	}()

	time.Sleep(10 * time.Second)
	log.Printf("processed packets: %d\n", atomic.LoadUint64(&analyzer.processed))
}
