## Initial implementation

### `flow_analyser.cpp`

```cpp
#include <arpa/inet.h>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <memory>
#include <optional>
#include <string>
#include <vector>
#include <chrono>
#include <algorithm>

// ==========================
// Fast timestamp helper
// ==========================
static inline uint64_t now_ns() {
    auto tp = std::chrono::steady_clock::now().time_since_epoch();
    return std::chrono::duration_cast<std::chrono::nanoseconds>(tp).count();
}

// ==========================
// Packet / flow metadata
// ==========================
#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t version_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               protocol == o.protocol;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast mix (simple, good enough for initial implementation)
        uint64_t x = 0;
        x ^= uint64_t(k.src_ip) * 0x9E3779B185EBCA87ULL;
        x ^= uint64_t(k.dst_ip) * 0xC2B2AE3D27D4EB4FULL;
        x ^= uint64_t(k.src_port) << 32;
        x ^= uint64_t(k.dst_port) << 16;
        x ^= uint64_t(k.protocol);
        x ^= (x >> 33);
        x *= 0xff51afd7ed558ccdULL;
        x ^= (x >> 33);
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= (x >> 33);
        return static_cast<size_t>(x);
    }
};

struct FlowRecord {
    FlowKey key{};
    uint64_t packet_count{0};
    uint64_t byte_count{0};
    uint64_t first_seen_ns{0};
    uint64_t last_seen_ns{0};
    uint8_t tcp_flags_seen{0};
    bool active{false};
};

class FlowTable {
public:
    explicit FlowTable(size_t capacity_power_of_two = 1 << 20)
        : capacity_(capacity_power_of_two),
          mask_(capacity_power_of_two - 1),
          table_(capacity_power_of_two) {}

    FlowRecord* lookup_or_insert(const FlowKey& key, uint64_t ts_ns) {
        size_t idx = hasher_(key) & mask_;

        // Linear probing with bounded scan
        for (size_t i = 0; i < capacity_; ++i) {
            size_t j = (idx + i) & mask_;
            FlowRecord& entry = table_[j];

            if (!entry.active) {
                entry.active = true;
                entry.key = key;
                entry.packet_count = 0;
                entry.byte_count = 0;
                entry.first_seen_ns = ts_ns;
                entry.last_seen_ns = ts_ns;
                entry.tcp_flags_seen = 0;
                return &entry;
            }

            if (entry.key == key) {
                return &entry;
            }
        }

        return nullptr; // Table full
    }

    template <typename Fn>
    void for_each_active(Fn&& fn) {
        for (auto& e : table_) {
            if (e.active) fn(e);
        }
    }

    void age_out(uint64_t cutoff_ns) {
        for (auto& e : table_) {
            if (e.active && e.last_seen_ns < cutoff_ns) {
                e.active = false;
            }
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowRecord> table_;
    FlowKeyHash hasher_;
};

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_size = 1 << 20)
        : flow_table_(table_size) {}

    // Process one Ethernet frame
    void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
        if (len < sizeof(EthernetHeader)) return;

        const EthernetHeader* eth = reinterpret_cast<const EthernetHeader*>(data);
        uint16_t ethertype = ntohs(eth->ethertype);
        if (ethertype != 0x0800) return; // IPv4 only

        const uint8_t* p = data + sizeof(EthernetHeader);
        size_t remaining = len - sizeof(EthernetHeader);

        if (remaining < sizeof(IPv4Header)) return;
        const IPv4Header* ip = reinterpret_cast<const IPv4Header*>(p);

        uint8_t ihl = (ip->version_ihl & 0x0F) * 4;
        if (ihl < 20 || remaining < ihl) return;

        if (ip->protocol != 6 && ip->protocol != 17) return; // TCP/UDP only

        FlowKey key{};
        key.src_ip = ip->src_ip;
        key.dst_ip = ip->dst_ip;
        key.protocol = ip->protocol;

        p += ihl;
        remaining -= ihl;

        if (ip->protocol == 6) {
            if (remaining < sizeof(TCPHeader)) return;
            const TCPHeader* tcp = reinterpret_cast<const TCPHeader*>(p);
            key.src_port = ntohs(tcp->src_port);
            key.dst_port = ntohs(tcp->dst_port);
        } else {
            if (remaining < sizeof(UDPHeader)) return;
            const UDPHeader* udp = reinterpret_cast<const UDPHeader*>(p);
            key.src_port = ntohs(udp->src_port);
            key.dst_port = ntohs(udp->dst_port);
        }

        FlowRecord* rec = flow_table_.lookup_or_insert(key, ts_ns);
        if (!rec) return;

        rec->packet_count += 1;
        rec->byte_count += len;
        rec->last_seen_ns = ts_ns;

        if (ip->protocol == 6 && remaining >= sizeof(TCPHeader)) {
            const TCPHeader* tcp = reinterpret_cast<const TCPHeader*>(p);
            rec->tcp_flags_seen |= tcp->flags;
        }
    }

    void expire_flows(uint64_t idle_timeout_ns) {
        const uint64_t cutoff = now_ns() - idle_timeout_ns;
        flow_table_.age_out(cutoff);
    }

    void print_top_flows(size_t max_items = 10) {
        std::vector<FlowRecord> flows;
        flows.reserve(1024);

        flow_table_.for_each_active([&](const FlowRecord& e) {
            flows.push_back(e);
        });

        std::sort(flows.begin(), flows.end(),
                  [](const FlowRecord& a, const FlowRecord& b) {
                      return a.byte_count > b.byte_count;
                  });

        size_t n = std::min(max_items, flows.size());
        for (size_t i = 0; i < n; ++i) {
            const auto& f = flows[i];
            std::cout << i + 1 << ". "
                      << ip_to_string(f.key.src_ip) << ":" << f.key.src_port
                      << " -> "
                      << ip_to_string(f.key.dst_ip) << ":" << f.key.dst_port
                      << " proto=" << int(f.key.protocol)
                      << " pkts=" << f.packet_count
                      << " bytes=" << f.byte_count
                      << " first_ns=" << f.first_seen_ns
                      << " last_ns=" << f.last_seen_ns
                      << " tcp_flags=0x" << std::hex << int(f.tcp_flags_seen) << std::dec
                      << "\n";
        }
    }

private:
    static std::string ip_to_string(uint32_t ip_be) {
        in_addr addr{};
        addr.s_addr = ip_be;
        char buf[INET_ADDRSTRLEN];
        const char* s = inet_ntop(AF_INET, &addr, buf, sizeof(buf));
        return s ? std::string(s) : std::string("0.0.0.0");
    }

    FlowTable flow_table_;
};

// ==========================
// Example demo main
// ==========================
int main() {
    FlowAnalyzer analyzer(1 << 20);

    // In a real deployment, packets would come from:
    // - AF_XDP
    // - DPDK
    // - libpcap
    // - raw sockets
    // - eBPF ring buffer
    //
    // Here we just show the skeleton entry point.

    std::cout << "Flow analyser initialized.\n";
    std::cout << "Hook this into a packet capture source for live traffic.\n";

    return 0;
}
