```cpp
// flow_analyzer.cpp
#include <pcap/pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>

#include <array>
#include <atomic>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <unordered_map>
#include <vector>
#include <chrono>

// ----------------------------
// Flow key / flow stats
// ----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Simple but decent hash for a minimal prototype
        size_t h = 0;
        auto mix = [&](auto v) {
            h ^= std::hash<uint64_t>{}(static_cast<uint64_t>(v) + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2));
        };
        mix(k.src_ip);
        mix(k.dst_ip);
        mix(k.src_port);
        mix(k.dst_port);
        mix(k.proto);
        return h;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

// ----------------------------
// Sharded flow table
// ----------------------------
static constexpr size_t NUM_SHARDS = 64;

struct Shard {
    std::mutex mtx;
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table;
};

std::array<Shard, NUM_SHARDS> shards;

static inline size_t shard_index(const FlowKey& k) {
    return FlowKeyHash{}(k) % NUM_SHARDS;
}

// ----------------------------
// Packet processing
// ----------------------------
static void process_packet(const struct pcap_pkthdr* hdr, const u_char* packet) {
    if (hdr->caplen < sizeof(ether_header)) return;

    auto* eth = reinterpret_cast<const ether_header*>(packet);
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char* ip_ptr = packet + sizeof(ether_header);
    if (hdr->caplen < sizeof(ether_header) + sizeof(iphdr)) return;

    auto* ip = reinterpret_cast<const ip*>(ip_ptr);
    if (ip->ip_v != 4) return;

    size_t ip_hdr_len = ip->ip_hl * 4;
    if (ip_hdr_len < sizeof(iphdr)) return;
    if (hdr->caplen < sizeof(ether_header) + ip_hdr_len) return;

    uint8_t proto = ip->ip_p;
    if (proto != IPPROTO_TCP && proto != IPPROTO_UDP) return;

    const u_char* l4_ptr = ip_ptr + ip_hdr_len;
    if (hdr->caplen < sizeof(ether_header) + ip_hdr_len + 4) return;

    uint16_t src_port = 0, dst_port = 0;
    if (proto == IPPROTO_TCP) {
        auto* tcp = reinterpret_cast<const tcphdr*>(l4_ptr);
        src_port = ntohs(tcp->th_sport);
        dst_port = ntohs(tcp->th_dport);
    } else {
        auto* udp = reinterpret_cast<const udphdr*>(l4_ptr);
        src_port = ntohs(udp->uh_sport);
        dst_port = ntohs(udp->uh_dport);
    }

    FlowKey key {
        .src_ip = ip->ip_src.s_addr,
        .dst_ip = ip->ip_dst.s_addr,
        .src_port = src_port,
        .dst_port = dst_port,
        .proto = proto
    };

    auto idx = shard_index(key);
    auto& shard = shards[idx];

    std::lock_guard<std::mutex> lock(shard.mtx);
    auto& stats = shard.table[key];
    uint64_t ts = now_ns();
    if (stats.packets == 0) stats.first_seen_ns = ts;
    stats.last_seen_ns = ts;
    stats.packets++;
    stats.bytes += hdr->len;
}

// ----------------------------
// Reporting thread
// ----------------------------
static void dump_flows() {
    uint64_t total_flows = 0;
    uint64_t total_packets = 0;
    uint64_t total_bytes = 0;

    for (auto& shard : shards) {
        std::lock_guard<std::mutex> lock(shard.mtx);
        total_flows += shard.table.size();
        for (const auto& [key, s] : shard.table) {
            total_packets += s.packets;
            total_bytes += s.bytes;
        }
    }

    std::cout << "[report] flows=" << total_flows
              << " packets=" << total_packets
              << " bytes=" << total_bytes << std::endl;
}

// ----------------------------
// Main
// ----------------------------
int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    const char* dev = argv[1];

    pcap_t* handle = pcap_open_live(dev, 65535, 1, 1000, errbuf);
    if (!handle) {
        std::cerr << "pcap_open_live failed: " << errbuf << "\n";
        return 1;
    }

    // Optional: reduce capture overhead with a filter
    struct bpf_program fp;
    const char* filter_exp = "ip and (tcp or udp)";
    if (pcap_compile(handle, &fp, filter_exp, 1, PCAP_NETMASK_UNKNOWN) == 0) {
        if (pcap_setfilter(handle, &fp) != 0) {
            std::cerr << "pcap_setfilter failed: " << pcap_geterr(handle) << "\n";
        }
        pcap_freecode(&fp);
    } else {
        std::cerr << "pcap_compile failed: " << pcap_geterr(handle) << "\n";
    }

    std::atomic<bool> running{true};

    std::thread reporter([&]{
        while (running.load()) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            dump_flows();
        }
    });

    std::cout << "Starting capture on " << dev << "...\n";

    // Packet loop
    int rc = pcap_loop(handle, -1,
        [](u_char*, const struct pcap_pkthdr* hdr, const u_char* packet) {
            process_packet(hdr, packet);
        },
        nullptr);

    if (rc == -1) {
        std::cerr << "pcap_loop error: " << pcap_geterr(handle) << "\n";
    }

    running.store(false);
    reporter.join();
    pcap_close(handle);

    return 0;
}
