```rust
use std::net::IpAddr;
use std::time::{Duration, Instant};

use crossbeam_channel::{bounded, Receiver, Sender};
use etherparse::{Ethernet2HeaderSlice, InternetSlice, SlicedPacket, TransportSlice};
use pcap::{Capture, Device};

const TABLE_SIZE: usize = 1 << 20; // 1,048,576 entries
const FLOW_TTL_SECS: u64 = 60;
const EXPORT_INTERVAL_SECS: u64 = 5;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct FlowKey {
    src_ip: u128,
    dst_ip: u128,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Copy, Debug)]
struct FlowEntry {
    key: FlowKey,
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
    used: bool,
}

impl Default for FlowEntry {
    fn default() -> Self {
        Self {
            key: FlowKey {
                src_ip: 0,
                dst_ip: 0,
                src_port: 0,
                dst_port: 0,
                proto: 0,
            },
            packets: 0,
            bytes: 0,
            first_seen: 0,
            last_seen: 0,
            used: false,
        }
    }
}

struct FlowTable {
    entries: Vec<FlowEntry>,
}

impl FlowTable {
    fn new() -> Self {
        Self {
            entries: vec![FlowEntry::default(); TABLE_SIZE],
        }
    }

    #[inline]
    fn hash(key: &FlowKey) -> usize {
        // Simple fast hash for minimal working version
        let mut h = key.src_ip ^ key.dst_ip;
        h ^= ((key.src_port as u128) << 16) ^ (key.dst_port as u128);
        h ^= (key.proto as u128) << 8;
        (h as usize).wrapping_mul(0x9E3779B97F4A7C15usize) & (TABLE_SIZE - 1)
    }

    fn update(&mut self, key: FlowKey, bytes: u64, now_secs: u64) {
        let mut idx = Self::hash(&key);

        for _ in 0..TABLE_SIZE {
            let e = &mut self.entries[idx];

            if !e.used {
                e.used = true;
                e.key = key;
                e.packets = 1;
                e.bytes = bytes;
                e.first_seen = now_secs;
                e.last_seen = now_secs;
                return;
            }

            if e.key == key {
                e.packets += 1;
                e.bytes += bytes;
                e.last_seen = now_secs;
                return;
            }

            idx = (idx + 1) & (TABLE_SIZE - 1);
        }

        // If table is full, drop the packet's flow update.
    }

    fn expire_and_export(&mut self, now_secs: u64) {
        for e in self.entries.iter_mut() {
            if e.used && now_secs.saturating_sub(e.last_seen) > FLOW_TTL_SECS {
                println!(
                    "FLOW key={:?} packets={} bytes={} first_seen={} last_seen={}",
                    e.key, e.packets, e.bytes, e.first_seen, e.last_seen
                );
                *e = FlowEntry::default();
            }
        }
    }
}

fn ip_to_u128(ip: IpAddr) -> u128 {
    match ip {
        IpAddr::V4(v4) => u32::from(v4) as u128,
        IpAddr::V6(v6) => u128::from(v6),
    }
}

fn decode_flow(pkt: &[u8]) -> Option<(FlowKey, u64)> {
    let sliced = SlicedPacket::from_ethernet(pkt).ok()?;
    let ip = sliced.net?;
    let transport = sliced.transport?;

    let (src_ip, dst_ip) = match ip {
        InternetSlice::Ipv4(hdr, _) => (
            ip_to_u128(IpAddr::V4(hdr.source_addr())),
            ip_to_u128(IpAddr::V4(hdr.destination_addr())),
        ),
        InternetSlice::Ipv6(hdr, _) => (
            ip_to_u128(IpAddr::V6(hdr.source_addr())),
            ip_to_u128(IpAddr::V6(hdr.destination_addr())),
        ),
    };

    let (src_port, dst_port, proto) = match transport {
        TransportSlice::Tcp(tcp) => (tcp.source_port(), tcp.destination_port(), 6),
        TransportSlice::Udp(udp) => (udp.source_port(), udp.destination_port(), 17),
        _ => return None,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    Some((key, pkt.len() as u64))
}

fn capture_loop(tx: Sender<Vec<u8>>) -> pcap::Result<()> {
    let device = Device::lookup()?
        .ok_or_else(|| pcap::Error::PcapError("No default device".into()))?;

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .snaplen(1518)
        .immediate_mode(true)
        .open()?;

    cap.filter("tcp or udp", true)?;

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                // Minimal buffering; packet copy is unavoidable here with pcap API.
                if tx.send(packet.data.to_vec()).is_err() {
                    break;
                }
            }
            Err(_) => continue,
        }
    }

    Ok(())
}

fn analysis_loop(rx: Receiver<Vec<u8>>) {
    let mut table = FlowTable::new();
    let mut last_export = Instant::now();

    loop {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(pkt) => {
                let now_secs = current_time_secs();
                if let Some((key, bytes)) = decode_flow(&pkt) {
                    table.update(key, bytes, now_secs);
                }
            }
            Err(_) => {}
        }

        if last_export.elapsed() >= Duration::from_secs(EXPORT_INTERVAL_SECS) {
            let now_secs = current_time_secs();
            table.expire_and_export(now_secs);
            last_export = Instant::now();
        }
    }
}

fn current_time_secs() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn main() {
    let (tx, rx) = bounded::<Vec<u8>>(8192);

    let cap_tx = tx.clone();
    std::thread::spawn(move || {
        if let Err(e) = capture_loop(cap_tx) {
            eprintln!("capture error: {e}");
        }
    });

    analysis_loop(rx);
}
