## `flow_analyzer.cpp`

```cpp
#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <atomic>
#include <array>
#include <chrono>
#include <thread>
#include <vector>
#include <algorithm>

static constexpr size_t FLOW_TABLE_SIZE = 1 << 20; // 1,048,576 entries
static constexpr int SNAPLEN = 96;

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
    uint8_t pad[3];

    bool operator==(const FlowKey& o) const {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowEntry {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint8_t used = 0;
};

static std::array<FlowEntry, FLOW_TABLE_SIZE> g_table;

static inline uint64_t hash_key(const FlowKey& k) {
    // Fast 64-bit mix
    uint64_t x = 0;
    x ^= (uint64_t)k.src_ip * 0x9e3779b185ebca87ULL;
    x ^= (uint64_t)k.dst_ip * 0xc2b2ae3d27d4eb4fULL;
    x ^= (uint64_t)k.src_port * 0x165667b19e3779f9ULL;
    x ^= (uint64_t)k.dst_port * 0x85ebca77c2b2ae63ULL;
    x ^= (uint64_t)k.proto * 0x27d4eb2f165667c5ULL;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline FlowEntry* flow_lookup_or_insert(const FlowKey& key) {
    size_t idx = hash_key(key) & (FLOW_TABLE_SIZE - 1);

    for (size_t probe = 0; probe < 64; ++probe) { // bounded linear probe
        FlowEntry& e = g_table[idx];
        if (!e.used) {
            e.used = 1;
            e.key = key;
            return &e;
        }
        if (e.key == key) {
            return &e;
        }
        idx = (idx + 1) & (FLOW_TABLE_SIZE - 1);
    }
    return nullptr; // table pressure too high
}

static void packet_handler(u_char*, const struct pcap_pkthdr* h, const u_char* bytes) {
    if (h->caplen < sizeof(struct ether_header)) return;

    const u_char* p = bytes;
    const struct ether_header* eth = reinterpret_cast<const struct ether_header*>(p);
    uint16_t ether_type = ntohs(eth->ether_type);

    // Skip Ethernet header
    p += sizeof(struct ether_header);
    size_t len = h->caplen - sizeof(struct ether_header);

    // Handle only IPv4
    if (ether_type != ETHERTYPE_IP || len < sizeof(struct ip)) return;

    const struct ip* iph = reinterpret_cast<const struct ip*>(p);
    if (iph->ip_v != 4) return;

    size_t ip_hlen = iph->ip_hl * 4;
    if (len < ip_hlen) return;

    FlowKey key{};
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const u_char* l4 = p + ip_hlen;
    size_t l4len = len - ip_hlen;

    if (iph->ip_p == IPPROTO_TCP) {
        if (l4len < sizeof(struct tcphdr)) return;
        const struct tcphdr* tcp = reinterpret_cast<const struct tcphdr*>(l4);
        key.src_port = ntohs(tcp->th_sport);
        key.dst_port = ntohs(tcp->th_dport);
    } else if (iph->ip_p == IPPROTO_UDP) {
        if (l4len < sizeof(struct udphdr)) return;
        const struct udphdr* udp = reinterpret_cast<const struct udphdr*>(l4);
        key.src_port = ntohs(udp->uh_sport);
        key.dst_port = ntohs(udp->uh_dport);
    } else {
        return; // only TCP/UDP for minimal version
    }

    FlowEntry* e = flow_lookup_or_insert(key);
    if (!e) return;

    e->packets++;
    e->bytes += h->len;
}

static void print_ip(uint32_t ip_be) {
    uint8_t b[4];
    std::memcpy(b, &ip_be, 4);
    std::printf("%u.%u.%u.%u", b[0], b[1], b[2], b[3]);
}

static void dump_top_flows(size_t top_n = 10) {
    std::vector<const FlowEntry*> flows;
    flows.reserve(FLOW_TABLE_SIZE / 8);

    for (const auto& e : g_table) {
        if (e.used) flows.push_back(&e);
    }

    std::sort(flows.begin(), flows.end(),
              [](const FlowEntry* a, const FlowEntry* b) {
                  return a->bytes > b->bytes;
              });

    std::printf("\n=== Top %zu flows ===\n", top_n);
    for (size_t i = 0; i < flows.size() && i < top_n; ++i) {
        const auto* e = flows[i];
        print_ip(e->key.src_ip);
        std::printf(":%u -> ", e->key.src_port);
        print_ip(e->key.dst_ip);
        std::printf(":%u proto=%u packets=%llu bytes=%llu\n",
                    e->key.dst_port,
                    e->key.proto,
                    (unsigned long long)e->packets,
                    (unsigned long long)e->bytes);
    }
}

int main(int argc, char** argv) {
    const char* dev = (argc > 1) ? argv[1] : nullptr;
    char errbuf[PCAP_ERRBUF_SIZE];

    if (!dev) {
        dev = pcap_lookupdev(errbuf);
        if (!dev) {
            std::fprintf(stderr, "pcap_lookupdev failed: %s\n", errbuf);
            return 1;
        }
    }

    pcap_t* handle = pcap_open_live(dev, SNAPLEN, 1, 1, errbuf);
    if (!handle) {
        std::fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    // Increase capture buffer if possible
    pcap_set_buffer_size(handle, 64 * 1024 * 1024);

    // Optional BPF filter for TCP/UDP only
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    std::printf("Listening on %s...\n", dev);

    // Periodic stats / dump thread
    std::thread reporter([] {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(5));
            dump_top_flows(10);
        }
    });
    reporter.detach();

    // Main capture loop
    int rc = pcap_loop(handle, -1, packet_handler, nullptr);
    if (rc == -1) {
        std::fprintf(stderr, "pcap_loop error: %s\n", pcap_geterr(handle));
    }

    pcap_close(handle);
    return 0;
}
