## File: `flow_analyser.cpp`

```cpp
#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <netinet/ip6.h>

#include <atomic>
#include <array>
#include <chrono>
#include <cstring>
#include <iostream>
#include <mutex>
#include <shared_mutex>
#include <thread>
#include <unordered_map>
#include <vector>

static constexpr size_t SHARDS = 64;
static constexpr size_t SNAPLEN = 65535;
static constexpr int PROMISC = 1;
static constexpr int TIMEOUT_MS = 1;

struct FlowKey {
    uint8_t proto;
    uint16_t sport;
    uint16_t dport;
    uint8_t ip_version;
    std::array<uint8_t, 16> src{};
    std::array<uint8_t, 16> dst{};

    bool operator==(const FlowKey& o) const {
        return proto == o.proto &&
               sport == o.sport &&
               dport == o.dport &&
               ip_version == o.ip_version &&
               src == o.src &&
               dst == o.dst;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        size_t h = 1469598103934665603ULL;
        auto mix = [&](const void* data, size_t len) {
            const uint8_t* p = static_cast<const uint8_t*>(data);
            for (size_t i = 0; i < len; ++i) {
                h ^= p[i];
                h *= 1099511628211ULL;
            }
        };
        mix(&k.proto, sizeof(k.proto));
        mix(&k.sport, sizeof(k.sport));
        mix(&k.dport, sizeof(k.dport));
        mix(&k.ip_version, sizeof(k.ip_version));
        mix(k.src.data(), k.src.size());
        mix(k.dst.data(), k.dst.size());
        return h;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t last_ns = 0;
};

struct Shard {
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows;
    std::mutex mtx;
};

std::array<Shard, SHARDS> g_shards;
std::atomic<bool> g_running{true};

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

static inline size_t shard_index(const FlowKey& k) {
    return FlowKeyHash{}(k) % SHARDS;
}

static void update_flow(const FlowKey& key, size_t bytes) {
    auto idx = shard_index(key);
    auto& shard = g_shards[idx];
    std::lock_guard<std::mutex> lock(shard.mtx);
    auto& s = shard.flows[key];
    s.packets++;
    s.bytes += bytes;
    s.last_ns = now_ns();
}

static bool parse_packet(const u_char* packet, size_t len, FlowKey& key) {
    if (len < 14) return false; // Ethernet header minimum

    const uint8_t* ptr = packet;
    uint16_t ether_type = ntohs(*reinterpret_cast<const uint16_t*>(ptr + 12));
    size_t offset = 14;

    // VLAN tag support (single tag)
    if (ether_type == 0x8100 && len >= 18) {
        ether_type = ntohs(*reinterpret_cast<const uint16_t*>(ptr + 16));
        offset = 18;
    }

    if (ether_type == 0x0800) { // IPv4
        if (len < offset + sizeof(iphdr)) return false;
        const iphdr* ip = reinterpret_cast<const iphdr*>(ptr + offset);
        size_t ip_hl = ip->ihl * 4;
        if (len < offset + ip_hl) return false;

        key.ip_version = 4;
        key.proto = ip->protocol;

        std::memset(key.src.data(), 0, key.src.size());
        std::memset(key.dst.data(), 0, key.dst.size());
        std::memcpy(key.src.data(), &ip->saddr, 4);
        std::memcpy(key.dst.data(), &ip->daddr, 4);

        offset += ip_hl;

        if (key.proto == IPPROTO_TCP) {
            if (len < offset + sizeof(tcphdr)) return false;
            auto* tcp = reinterpret_cast<const tcphdr*>(ptr + offset);
            key.sport = ntohs(tcp->source);
            key.dport = ntohs(tcp->dest);
        } else if (key.proto == IPPROTO_UDP) {
            if (len < offset + sizeof(udphdr)) return false;
            auto* udp = reinterpret_cast<const udphdr*>(ptr + offset);
            key.sport = ntohs(udp->source);
            key.dport = ntohs(udp->dest);
        } else {
            key.sport = 0;
            key.dport = 0;
        }
        return true;
    } else if (ether_type == 0x86DD) { // IPv6
        if (len < offset + sizeof(ip6_hdr)) return false;
        const ip6_hdr* ip6 = reinterpret_cast<const ip6_hdr*>(ptr + offset);

        key.ip_version = 6;
        key.proto = ip6->ip6_nxt;
        key.sport = 0;
        key.dport = 0;

        std::memcpy(key.src.data(), &ip6->ip6_src, 16);
        std::memcpy(key.dst.data(), &ip6->ip6_dst, 16);

        offset += sizeof(ip6_hdr);

        if (key.proto == IPPROTO_TCP) {
            if (len < offset + sizeof(tcphdr)) return false;
            auto* tcp = reinterpret_cast<const tcphdr*>(ptr + offset);
            key.sport = ntohs(tcp->source);
            key.dport = ntohs(tcp->dest);
        } else if (key.proto == IPPROTO_UDP) {
            if (len < offset + sizeof(udphdr)) return false;
            auto* udp = reinterpret_cast<const udphdr*>(ptr + offset);
            key.sport = ntohs(udp->source);
            key.dport = ntohs(udp->dest);
        }
        return true;
    }

    return false;
}

static void pcap_callback(u_char*, const struct pcap_pkthdr* hdr, const u_char* packet) {
    FlowKey key{};
    if (!parse_packet(packet, hdr->caplen, key)) return;
    update_flow(key, hdr->len);
}

static void reporter_thread() {
    while (g_running.load()) {
        std::this_thread::sleep_for(std::chrono::seconds(5));

        struct Entry {
            FlowKey key;
            FlowStats stats;
        };

        std::vector<Entry> all;
        for (auto& shard : g_shards) {
            std::lock_guard<std::mutex> lock(shard.mtx);
            for (const auto& kv : shard.flows) {
                all.push_back({kv.first, kv.second});
            }
        }

        std::sort(all.begin(), all.end(), [](const Entry& a, const Entry& b) {
            return a.stats.bytes > b.stats.bytes;
        });

        std::cout << "\n--- Top flows ---\n";
        for (size_t i = 0; i < std::min<size_t>(10, all.size()); ++i) {
            const auto& e = all[i];
            std::cout << "#" << i + 1
                      << " proto=" << int(e.key.proto)
                      << " ipver=" << int(e.key.ip_version)
                      << " sport=" << e.key.sport
                      << " dport=" << e.key.dport
                      << " packets=" << e.stats.packets
                      << " bytes=" << e.stats.bytes
                      << "\n";
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* handle = pcap_open_live(argv[1], SNAPLEN, PROMISC, TIMEOUT_MS, errbuf);
    if (!handle) {
        std::cerr << "pcap_open_live failed: " << errbuf << "\n";
        return 1;
    }

    // Filter only IP traffic
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip or ip6", 1, PCAP_NETMASK_UNKNOWN) == -1) {
        std::cerr << "pcap_compile failed: " << pcap_geterr(handle) << "\n";
        pcap_close(handle);
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        std::cerr << "pcap_setfilter failed: " << pcap_geterr(handle) << "\n";
        pcap_freecode(&fp);
        pcap_close(handle);
        return 1;
    }
    pcap_freecode(&fp);

    std::thread reporter(reporter_thread);

    std::cout << "Starting capture on " << argv[1] << "...\n";
    int ret = pcap_loop(handle, -1, pcap_callback, nullptr);

    g_running.store(false);
    if (ret == -1) {
        std::cerr << "pcap_loop error: " << pcap_geterr(handle) << "\n";
    }

    reporter.join();
    pcap_close(handle);
    return 0;
}
```

