```rust
use std::collections::hash_map::Entry;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use dashmap::DashMap;
use fxhash::FxBuildHasher;
use pnet::packet::ethernet::{EtherTypes, EthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use pnet::datalink::{self, Channel::Ethernet};

#[derive(Clone, Copy, Eq)]
struct FlowKey {
    src: Ipv4Addr,
    dst: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src == other.src
            && self.dst == other.dst
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src.hash(state);
        self.dst.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, len: usize) -> Self {
        Self {
            packets: 1,
            bytes: len as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, len: usize) {
        self.packets += 1;
        self.bytes += len as u64;
        self.last_seen = now;
    }
}

type FlowMap = DashMap<FlowKey, FlowStats, FxBuildHasher>;

const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);
const EVICT_INTERVAL: Duration = Duration::from_secs(5);

fn main() {
    let interface_name = std::env::args().nth(1).expect("Usage: flow_analyzer <iface>");
    let interfaces = datalink::interfaces();
    let interface = interfaces
        .into_iter()
        .find(|iface| iface.name == interface_name)
        .expect("Interface not found");

    let mut config = datalink::Config::default();
    config.read_timeout = Some(Duration::from_millis(10));

    let channel = datalink::channel(&interface, config).expect("Failed to create channel");

    let flows: Arc<FlowMap> = Arc::new(DashMap::with_hasher(FxBuildHasher::default()));

    let evict_flows = Arc::clone(&flows);
    std::thread::spawn(move || evict_loop(evict_flows));

    match channel {
        Ethernet(_, mut rx) => {
            loop {
                match rx.next() {
                    Ok(packet) => handle_packet(packet, &flows),
                    Err(_) => continue,
                }
            }
        }
        _ => panic!("Unsupported channel type"),
    }
}

fn handle_packet(packet: &[u8], flows: &FlowMap) {
    let now = Instant::now();

    let eth = match EthernetPacket::new(packet) {
        Some(p) => p,
        None => return,
    };

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ip = match Ipv4Packet::new(eth.payload()) {
                Some(p) => p,
                None => return,
            };

            let src = ip.get_source();
            let dst = ip.get_destination();
            let proto = ip.get_next_level_protocol();

            let (src_port, dst_port, proto_num) = match proto {
                IpNextHeaderProtocols::Tcp => {
                    let tcp = match TcpPacket::new(ip.payload()) {
                        Some(p) => p,
                        None => return,
                    };
                    (tcp.get_source(), tcp.get_destination(), 6)
                }
                IpNextHeaderProtocols::Udp => {
                    let udp = match UdpPacket::new(ip.payload()) {
                        Some(p) => p,
                        None => return,
                    };
                    (udp.get_source(), udp.get_destination(), 17)
                }
                _ => return,
            };

            let key = FlowKey {
                src,
                dst,
                src_port,
                dst_port,
                proto: proto_num,
            };

            match flows.entry(key) {
                dashmap::mapref::entry::Entry::Occupied(mut e) => {
                    e.get_mut().update(now, packet.len());
                }
                dashmap::mapref::entry::Entry::Vacant(v) => {
                    v.insert(FlowStats::new(now, packet.len()));
                }
            }
        }
        _ => {}
    }
}

fn evict_loop(flows: Arc<FlowMap>) {
    loop {
        std::thread::sleep(EVICT_INTERVAL);
        let now = Instant::now();

        let mut expired = Vec::new();

        for item in flows.iter() {
            if now.duration_since(item.value().last_seen) > FLOW_IDLE_TIMEOUT {
                expired.push(*item.key());
            }
        }

        for key in expired {
            if let Some((_, stats)) = flows.remove(&key) {
                println!(
                    "flow {:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={} lifetime_ms={}",
                    key.src,
                    key.src_port,
                    key.dst,
                    key.dst_port,
                    key.proto,
                    stats.packets,
                    stats.bytes,
                    stats.last_seen.duration_since(stats.first_seen).as_millis()
                );
            }
        }
    }
}
