use ahash::AHashMap;
use etherparse::{SlicedPacket, TransportSlice};
use pcap::Capture;
use std::net::IpAddr;
use std::time::{Duration, Instant};

#[derive(Hash, Eq, PartialEq, Clone, Copy, Debug)]
struct FlowKey {
    src_ip: u128,
    dst_ip: u128,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    ip_version: u8,
}

#[derive(Default, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant) -> Self {
        Self {
            packets: 0,
            bytes: 0,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, len: usize) {
        self.packets += 1;
        self.bytes += len as u64;
        self.last_seen = now;
    }
}

fn ip_to_u128(ip: IpAddr) -> (u128, u8) {
    match ip {
        IpAddr::V4(v4) => (u32::from(v4) as u128, 4),
        IpAddr::V6(v6) => (u128::from(v6), 6),
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let device = pcap::Device::lookup()?;
    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .open()?;

    // Optional filter: focus on IP traffic
    cap.filter("ip or ip6", true)?;

    let mut flows: AHashMap<FlowKey, FlowStats> = AHashMap::new();
    let mut last_report = Instant::now();
    let expire_after = Duration::from_secs(60);

    loop {
        match cap.next() {
            Ok(packet) => {
                let now = Instant::now();

                if let Ok(sliced) = SlicedPacket::from_ethernet(packet.data) {
                    let (src_ip, dst_ip, ip_version, proto) = match sliced.ip {
                        Some(etherparse::InternetSlice::Ipv4(header, _)) => {
                            let src = IpAddr::V4(header.source_addr());
                            let dst = IpAddr::V4(header.destination_addr());
                            let (_, vsrc) = ip_to_u128(src);
                            let (_, _) = ip_to_u128(dst);
                            (src, dst, 4, header.protocol().header_value())
                        }
                        Some(etherparse::InternetSlice::Ipv6(header, _)) => {
                            let src = IpAddr::V6(header.source_addr());
                            let dst = IpAddr::V6(header.destination_addr());
                            (src, dst, 6, header.next_header().header_value())
                        }
                        _ => continue,
                    };

                    let (src_port, dst_port) = match sliced.transport {
                        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
                        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
                        _ => (0, 0),
                    };

                    let (src_ip_u, _) = ip_to_u128(src_ip);
                    let (dst_ip_u, _) = ip_to_u128(dst_ip);

                    let key = FlowKey {
                        src_ip: src_ip_u,
                        dst_ip: dst_ip_u,
                        src_port,
                        dst_port,
                        proto,
                        ip_version,
                    };

                    let entry = flows.entry(key).or_insert_with(|| FlowStats::new(now));
                    entry.update(now, packet.data.len());
                }
            }
            Err(_) => continue,
        }

        // Periodic report and eviction
        if last_report.elapsed() >= Duration::from_secs(5) {
            let now = Instant::now();

            // Evict stale flows
            flows.retain(|_, stats| now.duration_since(stats.last_seen) < expire_after);

            // Print a small summary
            let total_flows = flows.len();
            let total_packets: u64 = flows.values().map(|f| f.packets).sum();
            let total_bytes: u64 = flows.values().map(|f| f.bytes).sum();

            eprintln!(
                "flows={} packets={} bytes={} rate={:.2} Mbit/s",
                total_flows,
                total_packets,
                total_bytes,
                (total_bytes as f64 * 8.0) / (5.0 * 1_000_000.0)
            );

            last_report = now;
        }
    }
}
