# Code: `flow_analyzer.cpp`

```cpp
#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <unordered_map>
#include <string>
#include <iostream>
#include <iomanip>

#pragma pack(push, 1)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast 64-bit mix
        uint64_t x = 0;
        x ^= (uint64_t)k.src_ip * 0x9e3779b185ebca87ULL;
        x ^= (uint64_t)k.dst_ip * 0xc2b2ae3d27d4eb4fULL;
        x ^= (uint64_t)k.src_port << 32;
        x ^= (uint64_t)k.dst_port << 16;
        x ^= (uint64_t)k.proto;
        x ^= (x >> 33);
        x *= 0xff51afd7ed558ccdULL;
        x ^= (x >> 33);
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= (x >> 33);
        return (size_t)x;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_ts_us = 0;
    uint64_t last_ts_us = 0;
};
#pragma pack(pop)

static inline uint64_t tv_to_us(const timeval& tv) {
    return (uint64_t)tv.tv_sec * 1000000ULL + (uint64_t)tv.tv_usec;
}

static void print_ip(uint32_t ip_be) {
    struct in_addr addr;
    addr.s_addr = ip_be;
    char buf[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &addr, buf, sizeof(buf));
    std::cout << buf;
}

static void print_flow(const FlowKey& k, const FlowStats& s) {
    print_ip(k.src_ip);
    std::cout << ":" << ntohs(k.src_port) << " -> ";
    print_ip(k.dst_ip);
    std::cout << ":" << ntohs(k.dst_port)
              << " proto=" << (int)k.proto
              << " pkts=" << s.packets
              << " bytes=" << s.bytes
              << " first_us=" << s.first_ts_us
              << " last_us=" << s.last_ts_us
              << "\n";
}

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(uint64_t timeout_us, size_t reserve_n = 1 << 20)
        : timeout_us_(timeout_us) {
        flows_.reserve(reserve_n);
    }

    void process_packet(const pcap_pkthdr* hdr, const u_char* data) {
        const uint64_t ts_us = tv_to_us(hdr->ts);

        // Ethernet header
        if (hdr->caplen < 14) return;
        const uint16_t eth_type = (uint16_t(data[12]) << 8) | data[13];
        if (eth_type != 0x0800) return; // IPv4 only

        // IPv4 header
        const u_char* ip_ptr = data + 14;
        if (hdr->caplen < 14 + sizeof(iphdr)) return;

        const iphdr* ip = reinterpret_cast<const iphdr*>(ip_ptr);
        const size_t ip_hdr_len = ip->ihl * 4;
        if (ip->version != 4 || ip_hdr_len < 20) return;
        if (hdr->caplen < 14 + ip_hdr_len) return;

        const uint32_t src_ip = ip->saddr;
        const uint32_t dst_ip = ip->daddr;
        const uint8_t proto = ip->protocol;

        uint16_t src_port = 0;
        uint16_t dst_port = 0;

        const u_char* l4_ptr = ip_ptr + ip_hdr_len;
        const size_t l4_len = hdr->caplen - (14 + ip_hdr_len);

        if (proto == IPPROTO_TCP) {
            if (l4_len < sizeof(tcphdr)) return;
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(l4_ptr);
            src_port = tcp->source;
            dst_port = tcp->dest;
        } else if (proto == IPPROTO_UDP) {
            if (l4_len < sizeof(udphdr)) return;
            const udphdr* udp = reinterpret_cast<const udphdr*>(l4_ptr);
            src_port = udp->source;
            dst_port = udp->dest;
        } else {
            return; // only TCP/UDP flows in minimal version
        }

        FlowKey key{src_ip, dst_ip, src_port, dst_port, proto};

        auto it = flows_.find(key);
        if (it == flows_.end()) {
            FlowStats st;
            st.packets = 1;
            st.bytes = hdr->len;
            st.first_ts_us = ts_us;
            st.last_ts_us = ts_us;
            flows_.emplace(key, st);
        } else {
            auto& st = it->second;
            st.packets++;
            st.bytes += hdr->len;
            st.last_ts_us = ts_us;
        }

        expire_old(ts_us);
    }

    void flush_all() {
        for (const auto& kv : flows_) {
            print_flow(kv.first, kv.second);
        }
        flows_.clear();
    }

private:
    void expire_old(uint64_t now_us) {
        // Minimal periodic sweep. For higher performance, do time-bucketed expiry.
        if (now_us - last_expire_us_ < expire_check_interval_us_) return;
        last_expire_us_ = now_us;

        for (auto it = flows_.begin(); it != flows_.end(); ) {
            if (now_us > it->second.last_ts_us &&
                now_us - it->second.last_ts_us > timeout_us_) {
                print_flow(it->first, it->second);
                it = flows_.erase(it);
            } else {
                ++it;
            }
        }
    }

    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows_;
    uint64_t timeout_us_;
    uint64_t last_expire_us_ = 0;
    const uint64_t expire_check_interval_us_ = 1000000ULL; // 1s
};

static void on_packet(u_char* user, const pcap_pkthdr* hdr, const u_char* data) {
    auto* analyzer = reinterpret_cast<FlowAnalyzer*>(user);
    analyzer->process_packet(hdr, data);
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <pcap_file>\n";
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* handle = pcap_open_offline(argv[1], errbuf);
    if (!handle) {
        std::cerr << "pcap_open_offline failed: " << errbuf << "\n";
        return 1;
    }

    // 30s inactivity timeout
    FlowAnalyzer analyzer(30ULL * 1000000ULL);

    if (pcap_loop(handle, 0, on_packet, reinterpret_cast<u_char*>(&analyzer)) < 0) {
        std::cerr << "pcap_loop error: " << pcap_geterr(handle) << "\n";
    }

    analyzer.flush_all();
    pcap_close(handle);
    return 0;
}
```

