# C implementation

## `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <inttypes.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <netinet/ip6.h>
#include <unistd.h>
#include <time.h>

#define FLOW_TABLE_SIZE (1 << 20)   // 1,048,576 entries
#define FLOW_TIMEOUT_SEC 30
#define SNAPLEN 65535

typedef struct {
    uint8_t  proto;
    uint8_t  pad1;
    uint16_t sport;
    uint16_t dport;
    uint8_t  src[16];
    uint8_t  dst[16];
    uint8_t  ipver;
    uint8_t  pad2[2];
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ts;
    uint64_t last_ts;
    uint8_t used;
} flow_entry_t;

static flow_entry_t *flows;

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint32_t hash_key(const flow_key_t *k) {
    const uint64_t *p = (const uint64_t *)k;
    uint64_t h = 1469598103934665603ULL;
    for (size_t i = 0; i < sizeof(flow_key_t) / 8; i++) {
        h ^= p[i];
        h *= 1099511628211ULL;
    }
    return (uint32_t)(h ^ (h >> 32));
}

static inline int key_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static flow_entry_t *flow_lookup_or_insert(const flow_key_t *key) {
    uint32_t h = hash_key(key);
    uint32_t idx = h & (FLOW_TABLE_SIZE - 1);

    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = &flows[(idx + i) & (FLOW_TABLE_SIZE - 1)];
        if (!e->used) {
            e->used = 1;
            e->key = *key;
            return e;
        }
        if (key_equal(&e->key, key)) {
            return e;
        }
    }
    return NULL;
}

static void expire_flows(uint64_t now) {
    uint64_t cutoff = now - (uint64_t)FLOW_TIMEOUT_SEC * 1000000000ULL;
    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = &flows[i];
        if (e->used && e->last_ts < cutoff) {
            printf("FLOW proto=%u sport=%u dport=%u packets=%" PRIu64
                   " bytes=%" PRIu64 " age_ms=%" PRIu64 "\n",
                   e->key.proto,
                   ntohs(e->key.sport),
                   ntohs(e->key.dport),
                   e->packets,
                   e->bytes,
                   (e->last_ts - e->first_ts) / 1000000ULL);
            memset(e, 0, sizeof(*e));
        }
    }
}

static void handle_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    uint64_t ts = (uint64_t)h->ts.tv_sec * 1000000000ULL + (uint64_t)h->ts.tv_usec * 1000ULL;
    if (h->caplen < 14) return;

    const u_char *p = bytes;
    uint16_t ethertype = ntohs(*(uint16_t *)(p + 12));
    size_t off = 14;

    flow_key_t key;
    memset(&key, 0, sizeof(key));

    if (ethertype == 0x8100 && h->caplen >= 18) { // VLAN
        ethertype = ntohs(*(uint16_t *)(p + 16));
        off += 4;
    }

    if (ethertype == 0x0800) { // IPv4
        if (h->caplen < off + sizeof(struct ip)) return;
        const struct ip *ip = (const struct ip *)(p + off);
        size_t ip_hlen = ip->ip_hl * 4;
        if (ip_hlen < sizeof(struct ip)) return;
        if (h->caplen < off + ip_hlen) return;

        key.ipver = 4;
        key.proto = ip->ip_p;
        memcpy(key.src, &ip->ip_src, 4);
        memcpy(key.dst, &ip->ip_dst, 4);

        off += ip_hlen;
    } else if (ethertype == 0x86DD) { // IPv6
        if (h->caplen < off + sizeof(struct ip6_hdr)) return;
        const struct ip6_hdr *ip6 = (const struct ip6_hdr *)(p + off);

        key.ipver = 6;
        key.proto = ip6->ip6_nxt;
        memcpy(key.src, &ip6->ip6_src, 16);
        memcpy(key.dst, &ip6->ip6_dst, 16);

        off += sizeof(struct ip6_hdr);
    } else {
        return;
    }

    if (key.proto == IPPROTO_TCP) {
        if (h->caplen < off + sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)(p + off);
        key.sport = tcp->source;
        key.dport = tcp->dest;
    } else if (key.proto == IPPROTO_UDP) {
        if (h->caplen < off + sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)(p + off);
        key.sport = udp->source;
        key.dport = udp->dest;
    } else {
        key.sport = 0;
        key.dport = 0;
    }

    flow_entry_t *e = flow_lookup_or_insert(&key);
    if (!e) return;

    if (e->packets == 0) e->first_ts = ts;
    e->last_ts = ts;
    e->packets++;
    e->bytes += h->len;
}

int main(int argc, char **argv) {
    const char *dev = (argc > 1) ? argv[1] : "eth0";
    char errbuf[PCAP_ERRBUF_SIZE];

    flows = aligned_alloc(64, sizeof(flow_entry_t) * FLOW_TABLE_SIZE);
    if (!flows) {
        perror("alloc");
        return 1;
    }
    memset(flows, 0, sizeof(flow_entry_t) * FLOW_TABLE_SIZE);

    pcap_t *pcap = pcap_create(dev, errbuf);
    if (!pcap) {
        fprintf(stderr, "pcap_create: %s\n", errbuf);
        return 1;
    }

    pcap_set_snaplen(pcap, SNAPLEN);
    pcap_set_promisc(pcap, 1);
    pcap_set_timeout(pcap, 1);
    pcap_set_immediate_mode(pcap, 1);

    if (pcap_activate(pcap) != 0) {
        fprintf(stderr, "pcap_activate: %s\n", pcap_geterr(pcap));
        return 1;
    }

    struct bpf_program fp;
    const char *filter = "ip or ip6";
    if (pcap_compile(pcap, &fp, filter, 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(pcap, &fp);
        pcap_freecode(&fp);
    }

    uint64_t last_expire = now_ns();

    while (1) {
        struct pcap_pkthdr *h;
        const u_char *data;
        int rc = pcap_next_ex(pcap, &h, &data);

        if (rc == 1) {
            handle_packet(NULL, h, data);
        } else if (rc == 0) {
            // timeout
        } else if (rc == -1) {
            fprintf(stderr, "pcap error: %s\n", pcap_geterr(pcap));
            break;
        } else if (rc == -2) {
            break;
        }

        uint64_t n = now_ns();
        if (n - last_expire > 5ULL * 1000000000ULL) {
            expire_flows(n);
            last_expire = n;
        }
    }

    pcap_close(pcap);
    free(flows);
    return 0;
}
