Below is a **minimal working version** of a **performance-oriented network flow analyser** for **gigabit-scale traffic**. It’s designed to be a practical starting point: high-throughput packet capture, lightweight 5-tuple flow hashing, periodic flow expiry, and low overhead output.

## What it does
- Captures packets from a network interface using **libpcap**
- Extracts a **5-tuple**:
  - src IP
  - dst IP
  - src port
  - dst port
  - protocol
- Aggregates per-flow counters:
  - packets
  - bytes
  - first/last seen timestamps
- Periodically expires inactive flows
- Prints expired flows to stdout

## Performance considerations
To keep it usable at high rates:
- Uses **`pcap_dispatch`** in a tight loop
- Avoids deep parsing
- Uses a compact flow key and hash map
- Minimal locking: single-threaded version for simplicity
- Limits per-packet work to a small constant amount

---

# Minimal implementation in C

Save as `flow_analyser.c`:

```c
#define _GNU_SOURCE
#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define FLOW_TABLE_SIZE (1u << 20)   // 1,048,576 buckets
#define FLOW_TIMEOUT_NS  (10ULL * 1000000000ULL)

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ns;
    uint64_t last_ns;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[FLOW_TABLE_SIZE];

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint32_t hash_key(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    h ^= k->src_ip;   h *= 16777619u;
    h ^= k->dst_ip;   h *= 16777619u;
    h ^= k->src_port; h *= 16777619u;
    h ^= k->dst_port; h *= 16777619u;
    h ^= k->proto;    h *= 16777619u;
    return h & (FLOW_TABLE_SIZE - 1);
}

static inline int key_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, uint64_t ts_ns) {
    uint32_t idx = hash_key(key);
    for (flow_entry_t *e = flow_table[idx]; e; e = e->next) {
        if (key_equal(&e->key, key)) return e;
    }

    flow_entry_t *e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return NULL;
    e->key = *key;
    e->first_ns = ts_ns;
    e->last_ns = ts_ns;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void expire_flows(uint64_t now) {
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if (now - e->last_ns > FLOW_TIMEOUT_NS) {
                char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
                struct in_addr s, d;
                s.s_addr = e->key.src_ip;
                d.s_addr = e->key.dst_ip;
                inet_ntop(AF_INET, &s, src, sizeof(src));
                inet_ntop(AF_INET, &d, dst, sizeof(dst));

                printf("%s:%u -> %s:%u proto=%u pkts=%llu bytes=%llu duration_ms=%.3f\n",
                       src, ntohs(e->key.src_port),
                       dst, ntohs(e->key.dst_port),
                       e->key.proto,
                       (unsigned long long)e->packets,
                       (unsigned long long)e->bytes,
                       (double)(e->last_ns - e->first_ns) / 1e6);

                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

static void handle_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;
    uint64_t ts_ns = (uint64_t)h->ts.tv_sec * 1000000000ULL + (uint64_t)h->ts.tv_usec * 1000ULL;

    if (h->caplen < sizeof(struct ether_header)) return;
    const struct ether_header *eth = (const struct ether_header *)bytes;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char *ip_ptr = bytes + sizeof(struct ether_header);
    if ((size_t)(h->caplen - sizeof(struct ether_header)) < sizeof(struct ip)) return;

    const struct ip *ip = (const struct ip *)ip_ptr;
    if (ip->ip_v != 4) return;

    size_t ip_hdr_len = ip->ip_hl * 4;
    if (ip_hdr_len < sizeof(struct ip)) return;
    if ((size_t)(h->caplen - sizeof(struct ether_header)) < ip_hdr_len) return;

    flow_key_t key = {0};
    key.src_ip = ip->ip_src.s_addr;
    key.dst_ip = ip->ip_dst.s_addr;
    key.proto = ip->ip_p;

    const u_char *l4 = ip_ptr + ip_hdr_len;
    size_t l4_len = h->caplen - sizeof(struct ether_header) - ip_hdr_len;

    if (key.proto == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (key.proto == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return;
    }

    flow_entry_t *e = flow_lookup_or_create(&key, ts_ns);
    if (!e) return;

    e->packets++;
    e->bytes += h->len;
    e->last_ns = ts_ns;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface> [bpf-filter]\n", argv[0]);
        return 1;
    }

    const char *dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];

    pcap_t *pcap = pcap_create(dev, errbuf);
    if (!pcap) {
        fprintf(stderr, "pcap_create failed: %s\n", errbuf);
        return 1;
    }

    pcap_set_snaplen(pcap, 96);
    pcap_set_promisc(pcap, 1);
    pcap_set_timeout(pcap, 100);
    pcap_set_immediate_mode(pcap, 1);

    if (pcap_activate(pcap) != 0) {
        fprintf(stderr, "pcap_activate failed: %s\n", pcap_geterr(pcap));
        pcap_close(pcap);
        return 1;
    }

    if (argc >= 3) {
        struct bpf_program fp;
        if (pcap_compile(pcap, &fp, argv[2], 1, PCAP_NETMASK_UNKNOWN) == -1 ||
            pcap_setfilter(pcap, &fp) == -1) {
            fprintf(stderr, "filter error: %s\n", pcap_geterr(pcap));
            pcap_freecode(&fp);
            pcap_close(pcap);
            return 1;
        }
        pcap_freecode(&fp);
    }

    printf("Listening on %s...\n", dev);

    uint64_t last_expire = now_ns();
    while (1) {
        int rc = pcap_dispatch(pcap, 64, handle_packet, NULL);
        if (rc == -1) {
            fprintf(stderr, "pcap error: %s\n", pcap_geterr(pcap));
            break;
        }

        uint64_t t = now_ns();
        if (t - last_expire > 1000000000ULL) {
            expire_flows(t);
            last_expire = t;
        }
    }

    pcap_close(pcap);
    return 0;
}
```

