use std::{
    collections::VecDeque,
    env,
    net::IpAddr,
    time::{Duration, Instant},
};

use ahash::RandomState;
use etherparse::PacketHeaders;
use hashbrown::HashMap;
use pcap::{Capture, Device};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src: IpAddr,
    dst: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: u64) -> Self {
        Self {
            packets: 1,
            bytes,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: u64) {
        self.packets += 1;
        self.bytes += bytes;
        self.last_seen = now;
    }
}

fn main() -> anyhow::Result<()> {
    let args: Vec<String> = env::args().collect();

    let mut cap = if args.len() > 1 {
        // Read from pcap file
        Capture::from_file(&args[1])?
    } else {
        // Live capture from default device
        let device = Device::lookup()?
            .ok_or_else(|| anyhow::anyhow!("No default capture device found"))?;
        Capture::from_device(device)?
            .promisc(true)
            .immediate_mode(true)
            .open()?
    };

    // Optional: set BPF filter for performance
    let _ = cap.filter("ip and (tcp or udp)", true);

    let mut flows: HashMap<FlowKey, FlowStats, RandomState> =
        HashMap::with_hasher(RandomState::new());

    let mut last_report = Instant::now();
    let mut packet_count: u64 = 0;
    let report_interval = Duration::from_secs(2);

    while let Ok(packet) = cap.next_packet() {
        packet_count += 1;
        let now = Instant::now();
        let data = packet.data;

        if let Some((key, bytes)) = parse_flow(data) {
            match flows.get_mut(&key) {
                Some(stats) => stats.update(now, bytes),
                None => {
                    flows.insert(key, FlowStats::new(now, bytes));
                }
            }
        }

        if last_report.elapsed() >= report_interval {
            print_report(&flows, packet_count);
            last_report = now;
        }
    }

    Ok(())
}

fn parse_flow(data: &[u8]) -> Option<(FlowKey, u64)> {
    let headers = PacketHeaders::from_ethernet_slice(data).ok()?;

    let ip = match headers.ip {
        Some(etherparse::IpHeader::Version4(h, _)) => {
            let src = IpAddr::V4(h.source_addr.into());
            let dst = IpAddr::V4(h.destination_addr.into());
            (src, dst, h.protocol.0)
        }
        Some(etherparse::IpHeader::Version6(h, _)) => {
            let src = IpAddr::V6(h.source_addr.into());
            let dst = IpAddr::V6(h.destination_addr.into());
            (src, dst, h.next_header.0)
        }
        None => return None,
    };

    let (src_port, dst_port, proto) = match headers.transport {
        Some(etherparse::TransportHeader::Tcp(tcp)) => {
            (tcp.source_port, tcp.destination_port, 6u8)
        }
        Some(etherparse::TransportHeader::Udp(udp)) => {
            (udp.source_port, udp.destination_port, 17u8)
        }
        _ => return None,
    };

    let key = FlowKey {
        src: ip.0,
        dst: ip.1,
        src_port,
        dst_port,
        proto,
    };

    Some((key, data.len() as u64))
}

fn print_report(flows: &HashMap<FlowKey, FlowStats, RandomState>, packet_count: u64) {
    let mut top: VecDeque<_> = flows.iter().collect();
    top.make_contiguous().sort_unstable_by(|a, b| {
        b.1.bytes.cmp(&a.1.bytes).then_with(|| b.1.packets.cmp(&a.1.packets))
    });

    println!("\n=== Flow Report ===");
    println!("Total packets seen: {}", packet_count);
    println!("Active flows: {}", flows.len());
    println!("Top flows by bytes:");

    for (i, (k, v)) in top.iter().take(10).enumerate() {
        println!(
            "#{:<2} {}:{} -> {}:{} proto={} packets={} bytes={} age_ms={}",
            i + 1,
            k.src,
            k.src_port,
            k.dst,
            k.dst_port,
            k.proto,
            v.packets,
            v.bytes,
            v.first_seen.elapsed().as_millis()
        );
    }
}
