Below is a **minimal working Go implementation** of a **performance-oriented network flow analyser** designed for **high-throughput packet streams**. It ingests packet metadata, aggregates into 5-tuples, and maintains per-flow counters with lock-minimized sharding.

This is **not a full IDS/NDR**, but it is a practical starting point for **gigabit-scale monitoring** when paired with a packet capture source such as **AF_PACKET/tpacket**, **DPDK**, **eBPF/XDP**, or **pcap**.

---

## What it does

- Tracks flows by:
  - source IP
  - destination IP
  - source port
  - destination port
  - protocol
- Aggregates:
  - packet count
  - byte count
  - timestamps
- Uses **sharded maps** to reduce lock contention
- Has a **background reaper** to expire idle flows
- Includes a **packet ingestion interface** you can wire to any high-speed capture backend

---

## Minimal working code

```go
package main

import (
	"encoding/binary"
	"fmt"
	"hash/fnv"
	"net"
	"sync"
	"sync/atomic"
	"time"
)

type FlowKey struct {
	SrcIP   [16]byte
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	_       [5]byte // padding for alignment
}

type FlowStats struct {
	Packets   uint64
	Bytes     uint64
	FirstSeen int64
	LastSeen  int64
}

type flowEntry struct {
	key   FlowKey
	stats FlowStats
}

type shard struct {
	mu    sync.RWMutex
	flows map[FlowKey]*flowEntry
}

type Analyzer struct {
	shards    []shard
	ttl       time.Duration
	stopCh    chan struct{}
	wg        sync.WaitGroup
	numShards uint32

	totalFlows uint64
}

func NewAnalyzer(numShards int, ttl time.Duration) *Analyzer {
	if numShards <= 0 {
		numShards = 64
	}
	a := &Analyzer{
		shards:    make([]shard, numShards),
		ttl:       ttl,
		stopCh:    make(chan struct{}),
		numShards: uint32(numShards),
	}
	for i := range a.shards {
		a.shards[i].flows = make(map[FlowKey]*flowEntry)
	}
	return a
}

func (a *Analyzer) StartReaper(interval time.Duration) {
	a.wg.Add(1)
	go func() {
		defer a.wg.Done()
		ticker := time.NewTicker(interval)
		defer ticker.Stop()

		for {
			select {
			case <-ticker.C:
				a.reap()
			case <-a.stopCh:
				return
			}
		}
	}()
}

func (a *Analyzer) Stop() {
	close(a.stopCh)
	a.wg.Wait()
}

func (a *Analyzer) shardFor(key FlowKey) *shard {
	h := fnv.New32a()
	_, _ = h.Write(key.SrcIP[:])
	_, _ = h.Write(key.DstIP[:])

	var b [5]byte
	binary.LittleEndian.PutUint16(b[0:2], key.SrcPort)
	binary.LittleEndian.PutUint16(b[2:4], key.DstPort)
	b[4] = key.Proto
	_, _ = h.Write(b[:])

	idx := h.Sum32() % a.numShards
	return &a.shards[idx]
}

func (a *Analyzer) ProcessPacket(srcIP, dstIP net.IP, srcPort, dstPort uint16, proto uint8, length uint32) {
	var key FlowKey
	copyIP(&key.SrcIP, srcIP)
	copyIP(&key.DstIP, dstIP)
	key.SrcPort = srcPort
	key.DstPort = dstPort
	key.Proto = proto

	now := time.Now().UnixNano()
	s := a.shardFor(key)

	s.mu.Lock()
	defer s.mu.Unlock()

	e, ok := s.flows[key]
	if !ok {
		e = &flowEntry{
			key: key,
			stats: FlowStats{
				Packets:   1,
				Bytes:     uint64(length),
				FirstSeen: now,
				LastSeen:  now,
			},
		}
		s.flows[key] = e
		atomic.AddUint64(&a.totalFlows, 1)
		return
	}

	e.stats.Packets++
	e.stats.Bytes += uint64(length)
	e.stats.LastSeen = now
}

func (a *Analyzer) reap() {
	expiry := time.Now().Add(-a.ttl).UnixNano()

	for i := range a.shards {
		s := &a.shards[i]
		s.mu.Lock()
		for k, e := range s.flows {
			if e.stats.LastSeen < expiry {
				delete(s.flows, k)
				atomic.AddUint64(&a.totalFlows, ^uint64(0)) // decrement
			}
		}
		s.mu.Unlock()
	}
}

func (a *Analyzer) Snapshot() []flowEntry {
	out := make([]flowEntry, 0, 1024)
	for i := range a.shards {
		s := &a.shards[i]
		s.mu.RLock()
		for _, e := range s.flows {
			out = append(out, *e)
		}
		s.mu.RUnlock()
	}
	return out
}

func copyIP(dst *[16]byte, ip net.IP) {
	if ip == nil {
		return
	}
	if v4 := ip.To4(); v4 != nil {
		copy(dst[12:], v4)
		return
	}
	v6 := ip.To16()
	if v6 != nil {
		copy(dst[:], v6)
	}
}

func main() {
	analyzer := NewAnalyzer(64, 30*time.Second)
	analyzer.StartReaper(5 * time.Second)
	defer analyzer.Stop()

	// Example traffic simulation
	analyzer.ProcessPacket(net.ParseIP("10.0.0.1"), net.ParseIP("10.0.0.2"), 12345, 80, 6, 1500)
	analyzer.ProcessPacket(net.ParseIP("10.0.0.1"), net.ParseIP("10.0.0.2"), 12345, 80, 6, 1500)
	analyzer.ProcessPacket(net.ParseIP("10.0.0.2"), net.ParseIP("10.0.0.1"), 80, 12345, 6, 80)

	time.Sleep(100 * time.Millisecond)

	for _, f := range analyzer.Snapshot() {
		fmt.Printf("flow=%v:%d -> %v:%d proto=%d packets=%d bytes=%d first=%d last=%d\n",
			net.IP(f.key.SrcIP[:]), f.key.SrcPort,
			net.IP(f.key.DstIP[:]), f.key.DstPort,
			f.key.Proto,
			f.stats.Packets, f.stats.Bytes,
			f.stats.FirstSeen, f.stats.LastSeen,
		)
	}
}
```

