## Code: `flow_analyzer.cpp`

```cpp
#include <pcap.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <chrono>

#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t type;
};

struct Ipv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static inline uint16_t bswap16(uint16_t x) { return __builtin_bswap16(x); }
static inline uint32_t bswap32(uint32_t x) { return __builtin_bswap32(x); }

struct FlowKey {
    uint32_t a_ip, b_ip;
    uint16_t a_port, b_port;
    uint8_t proto;

    bool operator==(const FlowKey& o) const {
        return a_ip == o.a_ip && b_ip == o.b_ip &&
               a_port == o.a_port && b_port == o.b_port &&
               proto == o.proto;
    }
};

struct FlowVal {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_ns = 0;
    uint64_t last_ns = 0;
    bool used = false;
};

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

static inline uint64_t hash_key(const FlowKey& k) {
    uint64_t x = 1469598103934665603ULL;
    auto mix = [&](uint64_t v) {
        x ^= v;
        x *= 1099511628211ULL;
    };
    mix(k.a_ip);
    mix(k.b_ip);
    mix(((uint64_t)k.a_port << 16) | k.b_port);
    mix(k.proto);
    return x;
}

class FlowTable {
public:
    explicit FlowTable(size_t size_pow2 = 1 << 20)
        : size_(size_pow2), mask_(size_pow2 - 1), keys_(size_pow2), vals_(size_pow2) {}

    FlowVal* get_or_insert(const FlowKey& key) {
        size_t idx = hash_key(key) & mask_;
        for (size_t i = 0; i < 16; ++i) {
            size_t pos = (idx + i) & mask_;
            if (!vals_[pos].used) {
                vals_[pos].used = true;
                keys_[pos] = key;
                return &vals_[pos];
            }
            if (keys_[pos] == key) return &vals_[pos];
        }
        return nullptr; // simple overflow behavior
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (size_t i = 0; i < size_; ++i) {
            if (vals_[i].used) fn(keys_[i], vals_[i]);
        }
    }

private:
    size_t size_;
    size_t mask_;
    std::vector<FlowKey> keys_;
    std::vector<FlowVal> vals_;
};

static inline bool extract_flow(const uint8_t* pkt, size_t len, FlowKey& key, uint32_t& pkt_bytes) {
    if (len < sizeof(EthHdr)) return false;

    auto* eth = reinterpret_cast<const EthHdr*>(pkt);
    uint16_t eth_type = bswap16(eth->type);
    if (eth_type != 0x0800) return false; // IPv4 only

    const uint8_t* p = pkt + sizeof(EthHdr);
    size_t rem = len - sizeof(EthHdr);
    if (rem < sizeof(Ipv4Hdr)) return false;

    auto* ip = reinterpret_cast<const Ipv4Hdr*>(p);
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if ((ip->ver_ihl >> 4) != 4 || ihl < 20 || rem < ihl) return false;

    uint16_t total_len = bswap16(ip->total_len);
    if (total_len < ihl) return false;
    pkt_bytes = total_len;

    uint32_t src = ip->src;
    uint32_t dst = ip->dst;
    uint8_t proto = ip->protocol;

    const uint8_t* l4 = p + ihl;
    size_t l4len = rem - ihl;

    uint16_t sport = 0, dport = 0;
    if (proto == 6) { // TCP
        if (l4len < sizeof(TcpHdr)) return false;
        auto* tcp = reinterpret_cast<const TcpHdr*>(l4);
        sport = bswap16(tcp->src_port);
        dport = bswap16(tcp->dst_port);
    } else if (proto == 17) { // UDP
        if (l4len < sizeof(UdpHdr)) return false;
        auto* udp = reinterpret_cast<const UdpHdr*>(l4);
        sport = bswap16(udp->src_port);
        dport = bswap16(udp->dst_port);
    } else {
        return false;
    }

    // Canonicalize direction so both sides map to one flow
    bool swap = false;
    if (src > dst || (src == dst && sport > dport)) swap = true;
    if (swap) {
        std::swap(src, dst);
        std::swap(sport, dport);
    }

    key = FlowKey{src, dst, sport, dport, proto};
    return true;
}

static pcap_t* open_capture(const char* dev, char errbuf[PCAP_ERRBUF_SIZE]) {
    pcap_t* handle = pcap_create(dev, errbuf);
    if (!handle) return nullptr;

    pcap_set_snaplen(handle, 65535);
    pcap_set_promisc(handle, 1);
    pcap_set_timeout(handle, 10);
    pcap_set_immediate_mode(handle, 1);
    pcap_set_buffer_size(handle, 64 * 1024 * 1024);

    if (pcap_activate(handle) != 0) {
        pcap_close(handle);
        return nullptr;
    }
    return handle;
}

static void print_flows(FlowTable& table) {
    struct Item {
        FlowKey k;
        FlowVal v;
    };
    std::vector<Item> items;
    items.reserve(10000);

    table.for_each([&](const FlowKey& k, const FlowVal& v) {
        items.push_back({k, v});
    });

    std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
        return a.v.bytes > b.v.bytes;
    });

    printf("\n=== Top flows ===\n");
    for (size_t i = 0; i < std::min<size_t>(20, items.size()); ++i) {
        char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
        in_addr sa{items[i].k.a_ip}, da{items[i].k.b_ip};
        inet_ntop(AF_INET, &sa, src, sizeof(src));
        inet_ntop(AF_INET, &da, dst, sizeof(dst));

        printf("%2zu) %s:%u -> %s:%u proto=%u packets=%llu bytes=%llu\n",
               i + 1,
               src, items[i].k.a_port,
               dst, items[i].k.b_port,
               items[i].k.proto,
               (unsigned long long)items[i].v.packets,
               (unsigned long long)items[i].v.bytes);
    }
}

int main(int argc, char** argv) {
    const char* dev = (argc > 1) ? argv[1] : nullptr;
    char errbuf[PCAP_ERRBUF_SIZE];

    if (!dev) {
        dev = pcap_lookupdev(errbuf);
        if (!dev) {
            fprintf(stderr, "pcap_lookupdev failed: %s\n", errbuf);
            return 1;
        }
    }

    printf("Capturing on %s\n", dev);

    pcap_t* handle = open_capture(dev, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap open failed: %s\n", errbuf);
        return 1;
    }

    // optional BPF filter
    struct bpf_program fp;
    const char* filter = "ip and (tcp or udp)";
    if (pcap_compile(handle, &fp, filter, 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    FlowTable table(1 << 20); // 1M slots

    uint64_t last_print = now_ns();
    while (true) {
        struct pcap_pkthdr* hdr = nullptr;
        const u_char* data = nullptr;
        int rc = pcap_next_ex(handle, &hdr, &data);

        if (rc == 1) {
            FlowKey key{};
            uint32_t pkt_bytes = 0;
            if (extract_flow(data, hdr->caplen, key, pkt_bytes)) {
                FlowVal* v = table.get_or_insert(key);
                if (v) {
                    if (!v->first_ns) v->first_ns = now_ns();
                    v->last_ns = hdr->ts.tv_sec * 1000000000ULL + hdr->ts.tv_usec * 1000ULL;
                    v->packets++;
                    v->bytes += pkt_bytes;
                }
            }
        } else if (rc == 0) {
            // timeout; periodic reporting
        } else if (rc == PCAP_ERROR_BREAK) {
            break;
        } else {
            fprintf(stderr, "pcap error: %s\n", pcap_geterr(handle));
            break;
        }

        uint64_t t = now_ns();
        if (t - last_print > 5ULL * 1000000000ULL) {
            print_flows(table);
            last_print = t;
        }
    }

    pcap_close(handle);
    return 0;
}
