## Minimal C implementation
This is a compact high-speed skeleton using:
- fixed-size hash table
- open addressing
- no dynamic allocation per packet
- IPv4 only for simplicity

```c
// flow_analyzer.c
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define TABLE_SIZE (1 << 20)   // 1,048,576 entries
#define FLOW_TIMEOUT_NS (30ULL * 1000000000ULL)

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t last_seen_ns;
    uint8_t in_use;
} flow_entry_t;

static flow_entry_t table[TABLE_SIZE];

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint64_t hash_flow(const flow_key_t *k) {
    uint64_t h = 1469598103934665603ULL; // FNV-1a
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 1099511628211ULL;
    }
    return h;
}

static inline int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static flow_entry_t *lookup_or_create(const flow_key_t *key) {
    uint64_t h = hash_flow(key);
    uint32_t idx = (uint32_t)(h & (TABLE_SIZE - 1));

    for (uint32_t i = 0; i < TABLE_SIZE; i++) {
        flow_entry_t *e = &table[(idx + i) & (TABLE_SIZE - 1)];

        if (!e->in_use) {
            e->key = *key;
            e->packets = 0;
            e->bytes = 0;
            e->last_seen_ns = 0;
            e->in_use = 1;
            return e;
        }

        if (flow_equal(&e->key, key)) {
            return e;
        }
    }
    return NULL;
}

static void expire_flows(uint64_t now) {
    for (uint32_t i = 0; i < TABLE_SIZE; i++) {
        flow_entry_t *e = &table[i];
        if (e->in_use && (now - e->last_seen_ns > FLOW_TIMEOUT_NS)) {
            e->in_use = 0;
        }
    }
}

// Example packet processor (simplified)
void process_packet(uint32_t src_ip, uint32_t dst_ip,
                    uint16_t src_port, uint16_t dst_port,
                    uint8_t proto, uint32_t len) {
    flow_key_t key = {
        .src_ip = src_ip,
        .dst_ip = dst_ip,
        .src_port = src_port,
        .dst_port = dst_port,
        .proto = proto
    };

    uint64_t t = now_ns();
    flow_entry_t *e = lookup_or_create(&key);
    if (!e) return;

    e->packets++;
    e->bytes += len;
    e->last_seen_ns = t;
}

static void dump_flows(void) {
    printf("Active flows:\n");
    for (uint32_t i = 0; i < TABLE_SIZE; i++) {
        flow_entry_t *e = &table[i];
        if (e->in_use) {
            printf("src=%u dst=%u sport=%u dport=%u proto=%u packets=%llu bytes=%llu last=%llu\n",
                   e->key.src_ip, e->key.dst_ip, e->key.src_port, e->key.dst_port, e->key.proto,
                   (unsigned long long)e->packets,
                   (unsigned long long)e->bytes,
                   (unsigned long long)e->last_seen_ns);
        }
    }
}

int main(void) {
    // Simulated traffic
    process_packet(0x0A000001, 0x0A000002, 12345, 80, 6, 1500);
    process_packet(0x0A000001, 0x0A000002, 12345, 80, 6, 1500);
    process_packet(0x0A000003, 0x0A000004, 54321, 53, 17, 64);

    dump_flows();
    expire_flows(now_ns());

    return 0;
}
```

