## `main.c`

```c
#include <stdint.h>
#include <stdbool.h>

/* ============================================================
 * Hardware abstraction stubs
 * Replace these with your MCU SDK/HAL functions.
 * ============================================================ */
void SystemClock_Config(void);
void GPIO_Init(void);
void I2C_Init(void);
void UART_Init(void);
void DelayMs(uint32_t ms);

bool I2C_Read(uint8_t devAddr, uint8_t regAddr, uint8_t *data, uint16_t len);
bool I2C_Write(uint8_t devAddr, uint8_t regAddr, uint8_t value);
void UART_SendString(const char *s);

/* ============================================================
 * Sensor configuration
 * Replace device address/registers for your actual sensor.
 * Example assumes a generic 16-bit sensor output on registers.
 * ============================================================ */
#define SENSOR_I2C_ADDR        0x48
#define SENSOR_REG_CONFIG      0x01
#define SENSOR_REG_DATA_MSB    0x00
#define SENSOR_REG_DATA_LSB    0x01

/* ============================================================
 * Processing parameters
 * ============================================================ */
#define MOVING_AVG_WINDOW      8
#define SAMPLE_PERIOD_MS       100

typedef struct {
    int32_t offset;
    float scale;
} Calibration_t;

static Calibration_t g_cal = {
    .offset = 0,
    .scale = 1.0f
};

static int32_t g_samples[MOVING_AVG_WINDOW];
static uint8_t g_sampleIndex = 0;
static uint8_t g_sampleCount = 0;

/* ============================================================
 * Utility: moving average filter
 * ============================================================ */
static int32_t MovingAverage_AddSample(int32_t newSample)
{
    g_samples[g_sampleIndex] = newSample;
    g_sampleIndex = (g_sampleIndex + 1U) % MOVING_AVG_WINDOW;

    if (g_sampleCount < MOVING_AVG_WINDOW) {
        g_sampleCount++;
    }

    int64_t sum = 0;
    for (uint8_t i = 0; i < g_sampleCount; i++) {
        sum += g_samples[i];
    }

    return (int32_t)(sum / g_sampleCount);
}

/* ============================================================
 * Sensor initialization
 * ============================================================ */
static bool Sensor_Init(void)
{
    /* Example configuration byte — replace as needed */
    if (!I2C_Write(SENSOR_I2C_ADDR, SENSOR_REG_CONFIG, 0x10)) {
        return false;
    }

    return true;
}

/* ============================================================
 * Read raw sensor value
 * Assumes sensor returns a 16-bit signed value.
 * ============================================================ */
static bool Sensor_ReadRaw(int16_t *rawOut)
{
    uint8_t data[2];

    if (!I2C_Read(SENSOR_I2C_ADDR, SENSOR_REG_DATA_MSB, data, 2)) {
        return false;
    }

    *rawOut = (int16_t)((data[0] << 8) | data[1]);
    return true;
}

/* ============================================================
 * Calibration + scaling
 * ============================================================ */
static float ProcessSensorValue(int16_t raw)
{
    int32_t adjusted = (int32_t)raw - g_cal.offset;
    float scaled = (float)adjusted * g_cal.scale;
    return scaled;
}

/* ============================================================
 * Example: simple runtime calibration
 * Call when sensor should read zero / known reference.
 * ============================================================ */
static void Sensor_CalibrateZero(void)
{
    int64_t sum = 0;
    const uint8_t n = 32;

    for (uint8_t i = 0; i < n; i++) {
        int16_t raw;
        if (Sensor_ReadRaw(&raw)) {
            sum += raw;
        }
        DelayMs(10);
    }

    g_cal.offset = (int32_t)(sum / n);
}

/* ============================================================
 * Main application
 * ============================================================ */
int main(void)
{
    SystemClock_Config();
    GPIO_Init();
    I2C_Init();
    UART_Init();

    UART_SendString("Firmware starting...\r\n");

    if (!Sensor_Init()) {
        UART_SendString("Sensor init failed!\r\n");
        while (1) {
            /* Fatal error: blink LED or halt */
        }
    }

    UART_SendString("Sensor init OK\r\n");

    /* Optional calibration step at startup */
    UART_SendString("Calibrating zero offset...\r\n");
    Sensor_CalibrateZero();

    UART_SendString("Calibration complete\r\n");

    while (1) {
        int16_t raw;
        if (Sensor_ReadRaw(&raw)) {
            int32_t filtered = MovingAverage_AddSample(raw);
            float processed = ProcessSensorValue((int16_t)filtered);

            char msg[64];
            /* Note: sprintf may be heavy on small MCUs; consider snprintf or custom formatting */
            int n = snprintf(msg, sizeof(msg),
                             "Raw=%d Filtered=%ld Processed=%.2f\r\n",
                             raw, (long)filtered, processed);

            if (n > 0) {
                UART_SendString(msg);
            }
        } else {
            UART_SendString("Sensor read error\r\n");
        }

        DelayMs(SAMPLE_PERIOD_MS);
    }
}

/* ============================================================
 * Stub implementations
 * Replace with real MCU-specific code
 * ============================================================ */
void SystemClock_Config(void) {}
void GPIO_Init(void) {}
