#define SENSOR_REG_DATA        0x20

#define FILTER_WINDOW_SIZE     8
#define THRESHOLD_VALUE        500

typedef struct {
    int32_t samples[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    int32_t sum;
} MovingAverageFilter;

static MovingAverageFilter filter;
static int32_t lastFilteredValue = 0;

/* -----------------------
   Filter functions
   ----------------------- */
void Filter_Init(MovingAverageFilter *f)
{
    for (int i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->samples[i] = 0;
    }
    f->index = 0;
    f->count = 0;
    f->sum = 0;
}

int32_t Filter_Update(MovingAverageFilter *f, int32_t newSample)
{
    if (f->count < FILTER_WINDOW_SIZE) {
        f->samples[f->index] = newSample;
        f->sum += newSample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = newSample;
        f->sum += newSample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;

    return f->sum / f->count;
}

