/* =========================
   Simple circular buffer
   ========================= */
typedef struct {
    int32_t samples[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    int32_t sum;
} MovingAverageFilter;

static void filter_init(MovingAverageFilter *f)
{
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->samples[i] = 0;
    }
    f->index = 0;
    f->count = 0;
    f->sum = 0;
}

static int32_t filter_update(MovingAverageFilter *f, int32_t new_sample)
{
    if (f->count < FILTER_WINDOW_SIZE) {
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
    }

    f->samples[f->index] = new_sample;
    f->sum += new_sample;

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;

    return f->sum / f->count;
}

