/* ---------------- Simple utility functions ---------------- */

static void utoa_dec(uint32_t value, char *buf)
{
    char temp[11];
    int i = 0, j = 0;

    if (value == 0) {
        buf[0] = '0';
        buf[1] = '\0';
        return;
    }

    while (value > 0 && i < (int)sizeof(temp)) {
        temp[i++] = '0' + (value % 10);
        value /= 10;
    }

    while (i > 0) {
        buf[j++] = temp[--i];
    }
    buf[j] = '\0';
}

/* ---------------- Moving average filter ---------------- */

static uint16_t sensor_buffer[MOVING_AVG_SIZE];
static uint32_t buffer_sum = 0;
static uint8_t buffer_index = 0;
static uint8_t buffer_count = 0;

static void filter_init(void)
{
    for (uint8_t i = 0; i < MOVING_AVG_SIZE; i++) {
        sensor_buffer[i] = 0;
    }
    buffer_sum = 0;
    buffer_index = 0;
    buffer_count = 0;
}

static uint16_t filter_moving_average(uint16_t sample)
{
    buffer_sum -= sensor_buffer[buffer_index];
    sensor_buffer[buffer_index] = sample;
    buffer_sum += sample;

    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;

    if (buffer_count < MOVING_AVG_SIZE) {
        buffer_count++;
    }

    return (uint16_t)(buffer_sum / buffer_count);
}

/* ---------------- Sensor processing ---------------- */

typedef struct {
    uint16_t raw;
    uint16_t filtered;
    bool threshold_exceeded;
} SensorData;

static SensorData process_sensor(void)
{
    SensorData data;
    data.raw = ADC_ReadSensor();
    data.filtered = filter_moving_average(data.raw);
    data.threshold_exceeded = (data.filtered > SENSOR_THRESHOLD);
    return data;
}

/* ---------------- Application ---------------- */

