            UART_SendString(raw_str);
            UART_SendString(" Filtered=");
            UART_SendString(filt_str);

            if (data.threshold_exceeded) {
                UART_SendString(" THRESHOLD=YES");
            } else {
                UART_SendString(" THRESHOLD=NO");
