#define SENSOR_CHANNEL      0
#define SAMPLE_COUNT        16
#define SENSOR_MAX_ADC      4095
#define VREF_MV             3300

/* -----------------------
   Moving average filter
   ----------------------- */
static uint16_t sample_buffer[SAMPLE_COUNT];
static uint32_t sample_sum = 0;
static uint8_t sample_index = 0;
static uint8_t sample_filled = 0;

static void filter_init(void) {
    for (uint8_t i = 0; i < SAMPLE_COUNT; i++) {
        sample_buffer[i] = 0;
    }
    sample_sum = 0;
    sample_index = 0;
    sample_filled = 0;
}

static uint16_t filter_update(uint16_t new_sample) {
    if (sample_filled < SAMPLE_COUNT) {
        sample_buffer[sample_index] = new_sample;
        sample_sum += new_sample;
        sample_filled++;
    } else {
        sample_sum -= sample_buffer[sample_index];
        sample_buffer[sample_index] = new_sample;
        sample_sum += new_sample;
    }

    sample_index++;
    if (sample_index >= SAMPLE_COUNT) {
        sample_index = 0;
    }

    return (uint16_t)(sample_sum / sample_filled);
}

/* -----------------------
   Conversion helpers
   ----------------------- */
static uint16_t adc_to_millivolts(uint16_t adc_value) {
    return (uint16_t)(((uint32_t)adc_value * VREF_MV) / SENSOR_MAX_ADC);
}

/* Example sensor-specific processing:
   - Convert ADC to millivolts
   - Simple threshold classification
*/
