#include <stdio.h>

static float g_filtered_value = 0.0f;

void sensor_init(void) {
    g_filtered_value = 0.0f;
}

static float low_pass_filter(float input) {
    g_filtered_value = (FILTER_ALPHA * input) + ((1.0f - FILTER_ALPHA) * g_filtered_value);
    return g_filtered_value;
}

static uint16_t adc_to_mv(uint16_t adc) {
    return (uint16_t)(((uint32_t)adc * ADC_REF_VOLTAGE_MV) / ADC_MAX_VALUE);
}

SensorData sensor_read_and_process(void) {
    SensorData data = {0};

    data.raw = platform_adc_read();
    data.filtered = low_pass_filter((float)data.raw);
    data.scaled_mv = adc_to_mv(data.raw);

    data.threshold_high = (data.raw >= SENSOR_THRESHOLD_HIGH);
    data.threshold_low  = (data.raw <= SENSOR_THRESHOLD_LOW);

    char msg[128];
    snprintf(msg, sizeof(msg),
             "raw=%u filtered=%.2f mv=%u high=%d low=%d\r\n",
             data.raw, data.filtered, data.scaled_mv,
             data.threshold_high, data.threshold_low);

    platform_uart_write(msg);

    return data;
}
