 * Application state
 * ------------------------------------------------------------ */
typedef struct {
    float raw_value;
    float filtered_value;
    bool  initialized;
    bool  fault;
    uint32_t sample_count;
} SensorState;

static SensorState g_sensor = {0};

/* ------------------------------------------------------------
 * Utility functions
 * ------------------------------------------------------------ */
static float adc_to_units(uint16_t raw)
{
    /* Example conversion:
       ADC range: 0..4095 -> sensor range: 0..100.0 units
       Adjust to your sensor's transfer function.
    */
    return ((float)raw / 4095.0f) * 100.0f;
}

static bool sensor_value_valid(float v)
{
    return (v >= SENSOR_MIN_VALID && v <= SENSOR_MAX_VALID);
}

static float low_pass_filter(float prev, float input, float alpha)
{
    return (alpha * input) + ((1.0f - alpha) * prev);
}

static void sensor_process_sample(uint16_t raw)
{
    float value = adc_to_units(raw);

    g_sensor.raw_value = value;
    g_sensor.sample_count++;

    if (!sensor_value_valid(value)) {
        g_sensor.fault = true;
        return;
    }

    if (!g_sensor.initialized) {
        g_sensor.filtered_value = value;
        g_sensor.initialized = true;
    } else {
        g_sensor.filtered_value = low_pass_filter(g_sensor.filtered_value, value, FILTER_ALPHA);
    }
}

/* ------------------------------------------------------------
 * Periodic task
 * ------------------------------------------------------------ */
static void sensor_task(void)
{
    uint16_t raw = ADC_ReadRaw();
    sensor_process_sample(raw);
}

/* ------------------------------------------------------------
 * Optional debug output
 * ------------------------------------------------------------ */
