{
    char buf[128];

    snprintf(buf, sizeof(buf),
             "samples=%lu raw=%.2f filtered=%.2f fault=%d\r\n",
             (unsigned long)g_sensor.sample_count,
             g_sensor.raw_value,
             g_sensor.filtered_value,
             g_sensor.fault ? 1 : 0);

    UART_Print(buf);
}

/* ------------------------------------------------------------
 * Main application
