#include "process.h"

static lowpass_filter_t g_filter;

void lowpass_filter_reset(lowpass_filter_t *filter, float alpha)
{
    if (!filter) return;

    filter->alpha = alpha;
    filter->x = 0.0f;
    filter->y = 0.0f;
    filter->z = 0.0f;
    filter->initialized = false;
}

void lowpass_filter_apply(lowpass_filter_t *filter, const sensor_value_t *input, sensor_value_t *output)
{
    if (!filter || !input || !output) return;

    if (!filter->initialized) {
        filter->x = input->x;
        filter->y = input->y;
        filter->z = input->z;
        filter->initialized = true;
    } else {
        filter->x = filter->alpha * input->x + (1.0f - filter->alpha) * filter->x;
        filter->y = filter->alpha * input->y + (1.0f - filter->alpha) * filter->y;
        filter->z = filter->alpha * input->z + (1.0f - filter->alpha) * filter->z;
    }

    output->x = filter->x;
    output->y = filter->y;
    output->z = filter->z;
}

void process_init(void)
{
    lowpass_filter_reset(&g_filter, 0.2f);
}

bool process_sample(const sensor_sample_t *sample, sensor_value_t *output)
{
    if (!sample || !output) return false;

    // Convert raw counts to physical units
    // Replace scaling with your sensor's actual sensitivity.
    sensor_value_t normalized = {
        .x = (float)sample->raw_x / 16384.0f,
        .y = (float)sample->raw_y / 16384.0f,
        .z = (float)sample->raw_z / 16384.0f
    };

    // Basic sanity check
    if (normalized.x > 100.0f || normalized.x < -100.0f ||
        normalized.y > 100.0f || normalized.y < -100.0f ||
        normalized.z > 100.0f || normalized.z < -100.0f) {
        return false;
    }

    lowpass_filter_apply(&g_filter, &normalized, output);
    return true;
}
