#define SENSOR_I2C_ADDR   0x68
#define SENSOR_REG_DATA   0x3B

bool sensor_init(void)
{
    // Initialize I2C/SPI and configure sensor registers here
    // Example: platform_i2c_write(...)
    return true;
}

bool sensor_read_raw(sensor_sample_t *sample)
{
    uint8_t buf[6];

    if (!sample) return false;

    // Read 6 bytes from sensor data registers
    if (!platform_i2c_read(SENSOR_I2C_ADDR, SENSOR_REG_DATA, buf, sizeof(buf))) {
        return false;
    }

    sample->raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    sample->raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    sample->raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    sample->timestamp_ms = platform_millis();

    return true;
}

bool sensor_read_processed(sensor_value_t *value)
{
    sensor_sample_t raw;

    if (!value) return false;
    if (!sensor_read_raw(&raw)) return false;

    return process_sample(&raw, value);
}
