void gpio_init(void);
void adc_init(void);
uint16_t adc_read_channel(uint8_t channel);
void delay_ms(uint32_t ms);
uint32_t millis(void);
void uart_init(void);
void uart_printf(const char *fmt, ...);

// Application-specific calibration constants
static const float SENSOR_SCALE = 3.3f / 4095.0f;   // Example for 12-bit ADC, 3.3V reference
static const float SENSOR_OFFSET = 0.0f;

// Simple moving average filter
static float moving_average_filter(float new_sample) {
    filter_buffer[filter_index] = new_sample;
    filter_index = (filter_index + 1) % SENSOR_BUFFER_SIZE;

    if (!filter_initialized && filter_index == 0) {
        filter_initialized = true;
    }

    uint8_t count = filter_initialized ? SENSOR_BUFFER_SIZE : filter_index;
    if (count == 0) {
        count = 1;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++) {
        sum += filter_buffer[i];
    }
    return sum / count;
}

// Convert raw ADC reading to a voltage or physical unit
static float calibrate_sensor(uint16_t raw) {
    float voltage = ((float)raw) * SENSOR_SCALE;
    return voltage + SENSOR_OFFSET;
}

// Read sensor and update data structure
static void sensor_read_and_process(void) {
    uint16_t raw = adc_read_channel(0);  // Channel 0 example
    float calibrated = calibrate_sensor(raw);
    float filtered = moving_average_filter(calibrated);

    sensor_data.raw_value = raw;
    sensor_data.calibrated_value = calibrated;
    sensor_data.filtered_value = filtered;
}

// Example control/decision logic
static void application_logic(void) {
    // Replace with your actual thresholds/behavior
    if (sensor_data.filtered_value > 2.5f) {
        // e.g., turn on LED, trigger actuator, log event
    } else {
        // e.g., turn off LED
    }
}

int main(void) {
    system_clock_init();
    gpio_init();
    adc_init();
    uart_init();

    uart_printf("Firmware startup complete\r\n");

    uint32_t last_sample_time = millis();

    while (1) {
        uint32_t now = millis();

        if ((now - last_sample_time) >= SAMPLE_PERIOD_MS) {
            last_sample_time = now;

            sensor_read_and_process();
            application_logic();

            uart_printf("Raw=%u, Cal=%.3f, Filt=%.3f\r\n",
                        sensor_data.raw_value,
                        sensor_data.calibrated_value,
                        sensor_data.filtered_value);
        }

        // Optional: sleep / low-power mode here
    }

    return 0;
}
