static void ProcessSensorData(const SensorVector *raw, SensorVector *processed)
{
    SensorVector corrected = {
        .x = raw->x - g_sensorState.offset.x,
        .y = raw->y - g_sensorState.offset.y,
        .z = raw->z - g_sensorState.offset.z
    };

    if (!g_sensorState.calibrated)
    {
        /* If not calibrated, pass raw through a basic filter */
        g_sensorState.filtered.x = corrected.x;
        g_sensorState.filtered.y = corrected.y;
        g_sensorState.filtered.z = corrected.z;
        g_sensorState.calibrated = true;
    }
    else
    {
        g_sensorState.filtered.x = LowPassFilter(g_sensorState.filtered.x, corrected.x, FILTER_ALPHA);
        g_sensorState.filtered.y = LowPassFilter(g_sensorState.filtered.y, corrected.y, FILTER_ALPHA);
        g_sensorState.filtered.z = LowPassFilter(g_sensorState.filtered.z, corrected.z, FILTER_ALPHA);
    }

    /* Example processing: compute normalized magnitude-based output */
    processed->x = g_sensorState.filtered.x;
    processed->y = g_sensorState.filtered.y;
    processed->z = g_sensorState.filtered.z;
