static void CalibrateSensor(void)
{
    int32_t sumX = 0, sumY = 0, sumZ = 0;
    int validSamples = 0;

    UART_SendString("Calibrating sensor...\r\n");

    for (int i = 0; i < CALIBRATION_SAMPLES; i++)
    {
        int16_t x, y, z;
        if (Sensor_ReadRaw(&x, &y, &z))
        {
            sumX += x;
            sumY += y;
            sumZ += z;
            validSamples++;
        }
        HAL_Delay(5);
