    if (validSamples > 0)
    {
        g_sensorState.offset.x = (float)sumX / validSamples;
        g_sensorState.offset.y = (float)sumY / validSamples;
        g_sensorState.offset.z = (float)sumZ / validSamples;
        g_sensorState.calibrated = false; /* reset filter state for first valid sample */

        UART_SendString("Calibration complete\r\n");
