 * Sensor Processing
 * ========================= */
static bool validate_sensor_value(uint16_t value)
{
    return (value >= SENSOR_MIN_VALID && value <= SENSOR_MAX_VALID);
}

static float low_pass_filter(float input)
{
    g_filter_state = (FILTER_ALPHA * input) + ((1.0f - FILTER_ALPHA) * g_filter_state);
    return g_filter_state;
}

static void process_sensor_data(void)
{
    g_sensor.raw = ADC_ReadSensor();
    g_sensor.valid = validate_sensor_value(g_sensor.raw);

    if (g_sensor.valid) {
        g_sensor.filtered = low_pass_filter((float)g_sensor.raw);
    }
}

/* =========================
 * Application Logic
