#define ADC_REF_VOLTAGE         3.3f
#define ADC_MAX_COUNTS          4095.0f   // 12-bit ADC
#define TEMP_SCALE_FACTOR       100.0f    // Example: convert volts to engineering units
#define TEMP_OFFSET             0.0f

#define SENSOR_MIN_VALID        0.05f
#define SENSOR_MAX_VALID        3.25f

/* ----------------------------
 * Globals
 * ---------------------------- */
static uint16_t sample_buffer[SENSOR_SAMPLES];
static uint8_t sample_index = 0;
static bool buffer_filled = false;

/* ----------------------------
 * Utility functions
 * ---------------------------- */
static void Sensor_BufferAdd(uint16_t sample)
{
    sample_buffer[sample_index++] = sample;

    if (sample_index >= SENSOR_SAMPLES) {
        sample_index = 0;
        buffer_filled = true;
    }
}

static float Sensor_GetAverageRaw(void)
{
    uint32_t sum = 0;
    uint8_t count = buffer_filled ? SENSOR_SAMPLES : sample_index;

    if (count == 0) {
        return 0.0f;
    }

    for (uint8_t i = 0; i < count; i++) {
        sum += sample_buffer[i];
    }

    return (float)sum / (float)count;
}

static float ConvertRawToVoltage(float raw_avg)
{
    return (raw_avg / ADC_MAX_COUNTS) * ADC_REF_VOLTAGE;
}

static float ConvertVoltageToEngineeringUnits(float voltage)
{
    // Example linear conversion; replace with your sensor-specific equation
    return (voltage * TEMP_SCALE_FACTOR) + TEMP_OFFSET;
}

static bool Sensor_IsValidVoltage(float voltage)
{
    return (voltage >= SENSOR_MIN_VALID && voltage <= SENSOR_MAX_VALID);
}

/* ----------------------------
 * Main application
 * ---------------------------- */
int main(void)
{
    System_Init();
    ADC_Init();
    UART_Init();

    UART_Printf("Firmware start\r\n");

    while (1)
    {
        uint16_t raw = ADC_ReadRaw();

        Sensor_BufferAdd(raw);

        float raw_avg = Sensor_GetAverageRaw();
        float voltage = ConvertRawToVoltage(raw_avg);

        if (!Sensor_IsValidVoltage(voltage)) {
            UART_Printf("Sensor fault: voltage=%.3f V\r\n", voltage);
        } else {
            float value = ConvertVoltageToEngineeringUnits(voltage);
            UART_Printf("Raw=%u Avg=%.1f Voltage=%.3f V Value=%.2f\r\n",
                        raw, raw_avg, voltage, value);
        }

        DelayMs(100); // 10 Hz sampling
    }
}
