#include <stdbool.h>

/* =========================
   Configuration
   ========================= */
#define SAMPLE_INTERVAL_MS   100
#define ADC_MAX_VALUE        4095.0f
#define ADC_REF_VOLTAGE      3.3f

/* Simple moving average size */
#define FILTER_WINDOW        8

/* =========================
   Hardware abstraction
   Replace these with MCU-specific implementations
   ========================= */
void System_Init(void);
void GPIO_Init(void);
void ADC_Init(void);
void Timer_Init(void);
void UART_Init(void);

uint16_t ADC_ReadChannel(uint8_t channel);
uint32_t millis(void);
void delay_ms(uint32_t ms);
void UART_SendString(const char *s);

/* =========================
   Sensor / processing state
   ========================= */
typedef struct {
    float samples[FILTER_WINDOW];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageFilter_t;

static MovingAverageFilter_t sensorFilter = {0};

/* =========================
   Utility functions
   ========================= */
static float adc_to_voltage(uint16_t adc)
{
    return ((float)adc * ADC_REF_VOLTAGE) / ADC_MAX_VALUE;
}

static void moving_average_init(MovingAverageFilter_t *f)
{
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->samples[i] = 0.0f;
    }
    f->index = 0;
    f->count = 0;
    f->sum = 0.0f;
}

static float moving_average_update(MovingAverageFilter_t *f, float new_sample)
{
    if (f->count < FILTER_WINDOW) {
        f->samples[f->index] = new_sample;
        f->sum += new_sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = new_sample;
        f->sum += new_sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return f->sum / (float)f->count;
}

/* Example sensor processing:
   - read ADC
   - convert to voltage
   - filter
   - apply simple calibration/scaling
*/
static float process_sensor_sample(uint16_t raw_adc)
{
    float voltage = adc_to_voltage(raw_adc);
    float filtered = moving_average_update(&sensorFilter, voltage);

    /* Example calibration:
       Suppose this sensor is centered around 1.65V, scaled to physical units.
       Adjust this formula to your sensor.
    */
    float sensor_units = (filtered - 1.65f) * 100.0f;

    return sensor_units;
}

/* =========================
   Main application
   ========================= */
int main(void)
{
    System_Init();
    GPIO_Init();
    ADC_Init();
    Timer_Init();
    UART_Init();

    moving_average_init(&sensorFilter);

    UART_SendString("Firmware start\r\n");

    uint32_t last_sample_time = millis();

    while (1) {
        uint32_t now = millis();

        if ((now - last_sample_time) >= SAMPLE_INTERVAL_MS) {
            last_sample_time = now;

            /* Read from ADC channel 0 (change as needed) */
            uint16_t raw = ADC_ReadChannel(0);

            /* Process sensor data */
            float processed = process_sensor_sample(raw);

            /* Output result */
            char msg[64];
            /* Note: for embedded systems, snprintf may be heavy.
               Use a lightweight formatter if needed. */
            snprintf(msg, sizeof(msg), "RAW=%u, PROC=%.2f\r\n", raw, processed);
            UART_SendString(msg);
        }

        /* Optional low-power wait / background tasks */
        // __WFI();  // if supported by your MCU
    }
}
