extern void     Timer_Init(uint32_t hz);
extern void     ADC_Init(void);
extern void     GPIO_Init(void);
extern void     UART_Init(uint32_t baud);
extern void     UART_Print(const char *s);
extern void     Enable_Interrupts(void);

/* Timer ISR hook should set this flag */
volatile bool g_sample_ready = false;

/* ===================== Sensor Data ===================== */
typedef struct {
    uint16_t raw;
    uint16_t filtered;
    bool     valid;
} SensorSample_t;

/* Moving average state */
static uint16_t avg_buffer[MOVING_AVG_SIZE];
static uint8_t  avg_index = 0;
static uint32_t avg_sum = 0;
static bool     avg_filled = false;

/* Latest sample */
static SensorSample_t g_sensor = {0};

/* ===================== Utility ===================== */
static uint16_t moving_average_update(uint16_t sample)
{
    avg_sum -= avg_buffer[avg_index];
    avg_buffer[avg_index] = sample;
    avg_sum += sample;

    avg_index++;
    if (avg_index >= MOVING_AVG_SIZE) {
        avg_index = 0;
        avg_filled = true;
    }

    if (avg_filled) {
        return (uint16_t)(avg_sum / MOVING_AVG_SIZE);
    } else {
        /* During startup, average only over filled portion */
        uint8_t count = avg_index;
        if (count == 0) count = MOVING_AVG_SIZE;
        return (uint16_t)(avg_sum / count);
    }
}

static bool sensor_validate(uint16_t sample)
{
    if (sample < SENSOR_FAULT_MIN || sample > SENSOR_FAULT_MAX) {
        return false;
    }
    return true;
}

static void sensor_process(void)
{
    uint16_t raw = ADC_ReadChannel(0);  // Example: channel 0
    g_sensor.raw = raw;
    g_sensor.valid = sensor_validate(raw);

    if (g_sensor.valid) {
        g_sensor.filtered = moving_average_update(raw);
    } else {
        /* Simple fallback behavior */
        g_sensor.filtered = 0;
    }
}

/* ===================== Timer ISR ===================== */
/* Replace with actual MCU ISR declaration */
void Timer_ISR(void)
{
    g_sample_ready = true;
}

/* ===================== Main ===================== */
int main(void)
{
    GPIO_Init();
    ADC_Init();
    UART_Init(115200);
    Timer_Init(100);  // 100 Hz sample rate
    Enable_Interrupts();

    UART_Print("Sensor firmware started\r\n");

    while (1) {
        if (g_sample_ready) {
            g_sample_ready = false;
            sensor_process();

            /* Example debug output */
            char msg[64];
            // Note: use your platform's snprintf if available
            // This is placeholder-style formatting
            UART_Print("Sample received\r\n");
        }

        /* Idle / sleep can be inserted here */
    }

    return 0;
}
