// Minimal sensor-reading firmware
// Reads analog sensor data, applies averaging, and prints to Serial.

const int SENSOR_PIN = A0;
const int NUM_SAMPLES = 10;

void setup() {
  Serial.begin(115200);
  while (!Serial) {
    ; // wait for serial port to connect (optional on some boards)
  }

  pinMode(SENSOR_PIN, INPUT);
  Serial.println("Sensor firmware started");
}

int readSensorRaw() {
  return analogRead(SENSOR_PIN);
}

float readSensorAverage() {
  long sum = 0;
  for (int i = 0; i < NUM_SAMPLES; i++) {
    sum += analogRead(SENSOR_PIN);
    delay(2);
  }
  return (float)sum / NUM_SAMPLES;
}

void loop() {
  int rawValue = readSensorRaw();
  float avgValue = readSensorAverage();

  // Example processing: simple normalization for 10-bit ADC
  float normalized = avgValue / 1023.0f;

  Serial.print("Raw: ");
  Serial.print(rawValue);
  Serial.print(" | Avg: ");
  Serial.print(avgValue);
  Serial.print(" | Normalized: ");
  Serial.println(normalized, 3);

  delay(500);
}
```

