    while (value > 0 && i < (int)(sizeof(buf) - 1))
    {
        buf[i++] = '0' + (value % 10);
        value /= 10;
    }

    /* Reverse digits */
    for (int j = 0; j < i / 2; j++)
    {
        char tmp = buf[j];
        buf[j] = buf[i - 1 - j];
        buf[i - 1 - j] = tmp;
    }

    buf[i++] = '\r';
    buf[i++] = '\n';
    buf[i] = '\0';

    mcu_uart_write(buf);
}
