        // Accelerometer angles
        double acc_roll  = std::atan2(imu.accel_y, imu.accel_z);
        double acc_pitch = std::atan2(-imu.accel_x,
                                      std::sqrt(imu.accel_y * imu.accel_y + imu.accel_z * imu.accel_z));

        // Gyro integration
        state.roll  = alpha_ * (state.roll  + imu.gyro_x * dt) + (1.0 - alpha_) * acc_roll;
        state.pitch = alpha_ * (state.pitch + imu.gyro_y * dt) + (1.0 - alpha_) * acc_pitch;
        state.yaw  += imu.gyro_z * dt;
    }

private:
