            int32_t dr = enc_curr.right_ticks - enc_prev.right_ticks;

            double rev_l = static_cast<double>(dl) / ticks_per_rev / gear_ratio;
            double rev_r = static_cast<double>(dr) / ticks_per_rev / gear_ratio;

            double dist_l = rev_l * 2.0 * M_PI * wheel_radius_m;
            double dist_r = rev_r * 2.0 * M_PI * wheel_radius_m;

            state_.left_vel  = dist_l / dt;
            state_.right_vel = dist_r / dt;

            enc_prev = enc_curr;

            // 3) Compute control targets
            // Example: drive forward at 0.3 m/s
            double target_left_vel  = 0.30;
            double target_right_vel = 0.30;

            // 4) PID motor control
            double left_cmd  = left_pid_.update(target_left_vel, state_.left_vel, dt);
            double right_cmd = right_pid_.update(target_right_vel, state_.right_vel, dt);

            // 5) Safety checks
            if (std::fabs(state_.roll) > 0.6 || std::fabs(state_.pitch) > 0.6) {
                emergencyStop("Excessive tilt detected");
                break;
            }

            // 6) Send motor commands
            motors_.setLeft(left_cmd);
            motors_.setRight(right_cmd);

            // 7) Maintain fixed loop rate
            next_tick += std::chrono::duration_cast<clock::duration>(loop_period);
            std::this_thread::sleep_until(next_tick);

            // Optional: loop timing debug
            auto end = clock::now();
            double elapsed_ms = std::chrono::duration<double, std::milli>(end - start).count();
            if (elapsed_ms > 10.0) {
                std::cout << "Warning: loop overrun: " << elapsed_ms << " ms\n";
            }
        }

        motors_.stop();
    }

    void stop() {
        running_ = false;
    }

private:
    void emergencyStop(const char* reason) {
        std::cerr << "EMERGENCY STOP: " << reason << "\n";
        motors_.stop();
        running_ = false;
    }

    IMUDriver imu_;
    EncoderDriver enc_;
    MotorDriver motors_;
    ComplementaryFilter fusion_;

    PID left_pid_;
    PID right_pid_;

    StateEstimate state_;
    std::atomic<bool> running_{true};
};

// =========================
// Main
// =========================
int main() {
    RobotController controller;
    controller.run();
    return 0;
}
```

