using Clock = std::chrono::steady_clock;

template <typename T>
T clampValue(T v, T lo, T hi) {
    return std::max(lo, std::min(v, hi));
}

// -------------------------------
// Sensor / State Structures
// -------------------------------
struct ImuData {
    double accelX = 0.0;   // m/s^2
    double accelY = 0.0;
    double accelZ = 0.0;
    double gyroZ  = 0.0;   // rad/s
};

struct OdomData {
    double leftTicks  = 0.0;
    double rightTicks = 0.0;
