class SensorFusion {
public:
    SensorFusion(double gyroWeight = 0.98)
        : gyroWeight_(gyroWeight) {}

    Pose2D update(const ImuData& imu, const OdomData& odom, double dt) {
        // Estimate heading from gyro integration
        headingGyro_ += imu.gyroZ * dt;

        // Estimate heading from wheel encoder differential
        double deltaTicksL = odom.leftTicks - prevLeftTicks_;
        double deltaTicksR = odom.rightTicks - prevRightTicks_;
        prevLeftTicks_ = odom.leftTicks;
        prevRightTicks_ = odom.rightTicks;

        double headingOdom = headingOdom_ + ticksToHeading(deltaTicksL, deltaTicksR);
        headingOdom_ = headingOdom;

        // Complementary fusion
        pose_.theta = normalizeAngle(gyroWeight_ * headingGyro_ + (1.0 - gyroWeight_) * headingOdom_);

        // Basic dead-reckoning position update using heading
        double distance = ticksToDistance(deltaTicksL, deltaTicksR);
        pose_.x += distance * std::cos(pose_.theta);
        pose_.y += distance * std::sin(pose_.theta);

        return pose_;
    }

    Pose2D getPose() const { return pose_; }

private:
    double ticksToDistance(double leftDelta, double rightDelta) {
        constexpr double metersPerTick = 0.0005; // tune for your robot
        return 0.5 * (leftDelta + rightDelta) * metersPerTick;
    }

    double ticksToHeading(double leftDelta, double rightDelta) {
        constexpr double ticksPerMeter = 2000.0;  // tune for your robot
        constexpr double wheelBaseMeters = 0.30;   // tune for your robot
        double dl = leftDelta / ticksPerMeter;
        double dr = rightDelta / ticksPerMeter;
        return (dr - dl) / wheelBaseMeters;
    }

    double normalizeAngle(double a) {
        while (a > M_PI) a -= 2.0 * M_PI;
        while (a < -M_PI) a += 2.0 * M_PI;
        return a;
    }

    double gyroWeight_;
    Pose2D pose_;
    double headingGyro_ = 0.0;
    double headingOdom_ = 0.0;
    double prevLeftTicks_ = 0.0;
    double prevRightTicks_ = 0.0;
};

// -------------------------------
// Control Loop
// -------------------------------
class RobotController {
public:
    RobotController()
        : headingPID_(2.0, 0.0, 0.2),
          speedPID_(1.0, 0.0, 0.05) {}

    void run() {
        constexpr double loopHz = 100.0;
        constexpr auto loopPeriod = std::chrono::duration<double>(1.0 / loopHz);

        auto nextTick = Clock::now();
        auto lastTick = Clock::now();

        while (running_) {
            auto now = Clock::now();
            double dt = std::chrono::duration<double>(now - lastTick).count();
            lastTick = now;

            if (Hardware::emergencyStopPressed()) {
                stopMotors();
                std::cerr << "Emergency stop engaged.\n";
                break;
            }

            // 1) Read sensors
            ImuData imu = Hardware::readIMU();
            OdomData odom = Hardware::readEncoders();

            // 2) Sensor fusion
            Pose2D pose = fusion_.update(imu, odom, dt);

            // 3) Compute control target
            // Example: drive forward while maintaining heading 0 rad
            double targetHeading = 0.0;
            double targetSpeed = 0.5; // normalized command

            double headingError = normalizeAngle(targetHeading - pose.theta);
            double turnCommand = headingPID_.update(headingError, dt);

            // In a real robot, speed feedback would come from wheel velocity.
            // Here we approximate using pose delta (or replace with measured velocity).
            double currentSpeedEstimate = estimateSpeed(odom, dt);
            double speedError = targetSpeed - currentSpeedEstimate;
            double forwardCommand = speedPID_.update(speedError, dt);

            // 4) Mix motor commands
            MotorCommand cmd;
            cmd.left  = forwardCommand - turnCommand;
            cmd.right = forwardCommand + turnCommand;

            // 5) Clamp and output to motors
            cmd.left  = clampValue(cmd.left, -1.0, 1.0);
            cmd.right = clampValue(cmd.right, -1.0, 1.0);

            Hardware::setMotorPWM(cmd.left, cmd.right);

            // Optional logging
            std::cout << "Pose: x=" << pose.x
                      << " y=" << pose.y
                      << " theta=" << pose.theta
                      << " cmdL=" << cmd.left
                      << " cmdR=" << cmd.right
                      << "\n";

            // 6) Timing control
            nextTick += std::chrono::duration_cast<Clock::duration>(loopPeriod);
            std::this_thread::sleep_until(nextTick);
        }

        stopMotors();
    }

    void stop() {
        running_ = false;
    }

private:
    double estimateSpeed(const OdomData& odom, double dt) {
        if (dt <= 0.0) return 0.0;

        double deltaTicksL = odom.leftTicks - prevLeftTicks_;
        double deltaTicksR = odom.rightTicks - prevRightTicks_;
        prevLeftTicks_ = odom.leftTicks;
        prevRightTicks_ = odom.rightTicks;

        constexpr double metersPerTick = 0.0005;
        double dist = 0.5 * (deltaTicksL + deltaTicksR) * metersPerTick;
        return dist / dt;
    }

    double normalizeAngle(double a) {
        while (a > M_PI) a -= 2.0 * M_PI;
        while (a < -M_PI) a += 2.0 * M_PI;
        return a;
    }

    void stopMotors() {
        Hardware::setMotorPWM(0.0, 0.0);
    }

    std::atomic<bool> running_{true};
    SensorFusion fusion_;
    PID headingPID_;
    PID speedPID_;

    double prevLeftTicks_ = 0.0;
    double prevRightTicks_ = 0.0;
};

