struct EncoderData {
    double left_ticks = 0.0;
    double right_ticks = 0.0;
    std::chrono::steady_clock::time_point timestamp;
};

struct FusedState {
    double roll = 0.0;      // radians
    double pitch = 0.0;     // radians
    double yaw = 0.0;       // radians
    double velocity = 0.0;  // m/s (example estimate)
    double position = 0.0;  // m (example estimate)
};

// =========================
// Thread-safe sensor buffer
// =========================

class SensorBuffer {
public:
    void updateImu(const ImuData& imu) {
        std::lock_guard<std::mutex> lock(mutex_);
        imu_ = imu;
        imu_valid_ = true;
    }

    void updateEncoders(const EncoderData& enc) {
        std::lock_guard<std::mutex> lock(mutex_);
        enc_ = enc;
        enc_valid_ = true;
    }

    bool getLatest(ImuData& imu, EncoderData& enc) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!imu_valid_ || !enc_valid_) return false;
        imu = imu_;
        enc = enc_;
        return true;
    }

private:
    std::mutex mutex_;
    ImuData imu_;
    EncoderData enc_;
    bool imu_valid_ = false;
    bool enc_valid_ = false;
};

// =========================
// Complementary Filter
// =========================

class ComplementaryFilter {
public:
    explicit ComplementaryFilter(double alpha = 0.98)
        : alpha_(alpha) {}

    FusedState update(const ImuData& imu, const EncoderData& enc, double dt) {
        // Estimate roll/pitch from accelerometer
        const double accel_roll  = std::atan2(imu.accel_y, imu.accel_z);
        const double accel_pitch = std::atan2(-imu.accel_x,
                                              std::sqrt(imu.accel_y * imu.accel_y + imu.accel_z * imu.accel_z));

        // Integrate gyro
        state_.roll  = alpha_ * (state_.roll  + imu.gyro_x * dt) + (1.0 - alpha_) * accel_roll;
        state_.pitch = alpha_ * (state_.pitch + imu.gyro_y * dt) + (1.0 - alpha_) * accel_pitch;
        state_.yaw   = state_.yaw + imu.gyro_z * dt; // gyro-only yaw in this simple example

        // Example velocity/position estimate from encoders
        // Replace with your robot kinematics as needed
        double ticks_to_meters = 0.001; // placeholder scale
        double wheel_travel = 0.5 * (enc.left_ticks + enc.right_ticks) * ticks_to_meters;

        state_.velocity = wheel_travel / dt;
        state_.position += state_.velocity * dt;

        return state_;
    }

private:
    double alpha_;
    FusedState state_;
};

// =========================
// PID Controller
// =========================

class PID {
public:
    PID(double kp, double ki, double kd, double output_min, double output_max)
        : kp_(kp), ki_(ki), kd_(kd),
          output_min_(output_min), output_max_(output_max) {}

    double update(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;

        integral_ += error * dt;
        double derivative = (dt > 1e-9) ? (error - prev_error_) / dt : 0.0;

        double output = kp_ * error + ki_ * integral_ + kd_ * derivative;
        output = clamp(output, output_min_, output_max_);

        prev_error_ = error;
        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double kp_, ki_, kd_;
    double output_min_, output_max_;
    double integral_ = 0.0;
    double prev_error_ = 0.0;
};

