// Robot Control Loop
// =========================

class RobotController {
public:
    RobotController()
        : filter_(0.98),
          balance_pid_(25.0, 1.0, 0.5, -1.0, 1.0),
          motor_pid_(1.5, 0.2, 0.05, -1.0, 1.0) {}

    void run() {
        using clock = std::chrono::steady_clock;
        const auto control_period = std::chrono::milliseconds(10); // 100 Hz

        auto next_tick = clock::now();

        while (running_) {
            next_tick += control_period;

            // Read latest sensors
            ImuData imu;
            EncoderData enc;

            imu = sensors_.readImu();
            enc = sensors_.readEncoders();
            buffer_.updateImu(imu);
            buffer_.updateEncoders(enc);

            if (!buffer_.getLatest(imu, enc)) {
                sleepUntil(next_tick);
                continue;
            }

            auto now = clock::now();
            double dt = std::chrono::duration<double>(control_period).count();

            // Sensor fusion
            FusedState state = filter_.update(imu, enc, dt);

            // Example control objectives:
            // 1) Keep roll near 0
            // 2) Keep forward velocity near target
            double target_roll = 0.0;
            double target_velocity = 0.5; // m/s

            double balance_correction = balance_pid_.update(target_roll, state.roll, dt);
            double velocity_correction = motor_pid_.update(target_velocity, state.velocity, dt);

            // Differential drive mixing
            double left_cmd = velocity_correction - balance_correction;
            double right_cmd = velocity_correction + balance_correction;

            motor_.setLeftDuty(left_cmd);
            motor_.setRightDuty(right_cmd);
            motor_.apply();

            // Debug output
            std::cout << "State -> roll: " << state.roll
                      << " pitch: " << state.pitch
                      << " yaw: " << state.yaw
                      << " vel: " << state.velocity
                      << " pos: " << state.position << "\n";

            // Sleep until next control tick
            sleepUntil(next_tick);
        }
    }

    void stop() {
        running_ = false;
    }

private:
    void sleepUntil(const std::chrono::steady_clock::time_point& deadline) {
        std::this_thread::sleep_until(deadline);
    }

    std::atomic<bool> running_{true};
    SensorBuffer buffer_;
    ComplementaryFilter filter_;
    PID balance_pid_;
    PID motor_pid_;
    MotorDriver motor_;
    MockSensors sensors_;
};

