// Main
// =========================

int main() {
    RobotController controller;

    std::thread control_thread([&controller]() {
        controller.run();
    });

    // Run for some time, then stop
    std::this_thread::sleep_for(std::chrono::seconds(3));
    controller.stop();

    if (control_thread.joinable()) {
        control_thread.join();
    }

    return 0;
}
