/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - Collects 3-axis accelerometer samples
 * - High-pass filters to remove gravity / slow drift
 * - Computes signal magnitude
 * - Tracks running mean and variance with an EMA
 * - Flags anomalies when magnitude deviates too far from baseline
 * - Designed for small embedded systems: no dynamic allocation
 *
 * Adjust the constants below for your sensor and use case.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

#define ALPHA_BASELINE        0.01f   // EMA rate for baseline statistics
#define ALPHA_FILTER          0.05f   // EMA rate for high-pass filter
#define ANOMALY_Z_THRESHOLD   4.0f    // Z-score threshold for anomaly
#define MIN_VARIANCE          1e-6f    // Prevent divide-by-zero
#define WARMUP_SAMPLES        100     // Ignore anomaly decisions until this many samples seen

/* ---------------- Types ---------------- */

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    // High-pass filter state
    float hp_x, hp_y, hp_z;
    float prev_x, prev_y, prev_z;

    // Baseline statistics for magnitude
    float mean;
    float var;

    uint32_t sample_count;
} anomaly_detector_t;

/* ---------------- Utility ---------------- */

static float fast_sqrtf(float x) {
    // Replace with platform-specific fast math if available
    return sqrtf(x);
}

static float magnitude3f(float x, float y, float z) {
    return fast_sqrtf(x * x + y * y + z * z);
}

/* ---------------- Initialization ---------------- */

void anomaly_detector_init(anomaly_detector_t *det) {
    det->hp_x = det->hp_y = det->hp_z = 0.0f;
    det->prev_x = det->prev_y = det->prev_z = 0.0f;
    det->mean = 0.0f;
    det->var = 1.0f;
    det->sample_count = 0;
}

/* ---------------- Processing ---------------- */

static float high_pass_ema(float input, float *hp_state, float *prev_input, float alpha) {
    /*
     * Simple one-pole high-pass approximation:
     * hp[n] = alpha * (hp[n-1] + x[n] - x[n-1])
     */
    float hp = alpha * (*hp_state + input - *prev_input);
    *hp_state = hp;
    *prev_input = input;
    return hp;
}

bool anomaly_detector_process(anomaly_detector_t *det, const accel_sample_t *s, float *out_score) {
    // High-pass filter each axis
    float fx = high_pass_ema(s->x, &det->hp_x, &det->prev_x, ALPHA_FILTER);
    float fy = high_pass_ema(s->y, &det->hp_y, &det->prev_y, ALPHA_FILTER);
    float fz = high_pass_ema(s->z, &det->hp_z, &det->prev_z, ALPHA_FILTER);

    // Feature: magnitude of filtered signal
    float mag = magnitude3f(fx, fy, fz);

    // Update EMA mean/variance
    if (det->sample_count == 0) {
        det->mean = mag;
        det->var = 1.0f;
    } else {
        float delta = mag - det->mean;
        det->mean += ALPHA_BASELINE * delta;
        det->var = (1.0f - ALPHA_BASELINE) * (det->var + ALPHA_BASELINE * delta * delta);
        if (det->var < MIN_VARIANCE) {
            det->var = MIN_VARIANCE;
        }
    }

    det->sample_count++;

    // Compute anomaly score: absolute z-score
    float stddev = fast_sqrtf(det->var);
    float z = (mag - det->mean) / stddev;
    float score = fabsf(z);

    if (out_score) {
        *out_score = score;
    }

    // No anomaly decisions during warm-up
    if (det->sample_count < WARMUP_SAMPLES) {
        return false;
    }

    return (score > ANOMALY_Z_THRESHOLD);
}

