Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- reads 3-axis accelerometer samples
- filters them with a simple low-pass filter
- computes signal magnitude
- tracks a running baseline and variance
- flags anomalies when samples deviate too far from the baseline

It’s designed to be easy to port to an MCU and can run in a fixed-rate interrupt or task.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detector
 *
 * Approach:
 * 1. Read raw x/y/z samples
 * 2. Low-pass filter
 * 3. Compute magnitude
 * 4. Maintain running mean/variance
 * 5. Trigger anomaly when z-score exceeds threshold
 */

typedef struct {
    float alpha;          // low-pass filter coefficient (0..1)
    float mean;           // running mean of magnitude
    float var;            // running variance estimate
    float filtered_mag;   // filtered magnitude
    bool initialized;
    uint32_t warmup_count;
    uint32_t warmup_limit;
    float z_threshold;    // anomaly threshold in standard deviations
    float min_variance;   // floor to avoid division by zero
} AnomalyDetector;

/* Initialize detector */
void detector_init(AnomalyDetector *d,
                   float alpha,
                   uint32_t warmup_limit,
                   float z_threshold)
{
    d->alpha = alpha;
    d->mean = 0.0f;
    d->var = 1.0f;
    d->filtered_mag = 0.0f;
    d->initialized = false;
    d->warmup_count = 0;
    d->warmup_limit = warmup_limit;
    d->z_threshold = z_threshold;
    d->min_variance = 1e-6f;
}

/* Process one accelerometer sample.
 * Inputs are assumed to be in g's or another consistent unit.
 * Returns true if anomaly detected.
 */
bool detector_process_sample(AnomalyDetector *d, float ax, float ay, float az)
{
    // Compute vector magnitude
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    // First-sample initialization
    if (!d->initialized) {
        d->filtered_mag = mag;
        d->mean = mag;
        d->var = 1.0f;
        d->initialized = true;
        d->warmup_count = 1;
        return false;
    }

    // Low-pass filter
    d->filtered_mag = d->alpha * mag + (1.0f - d->alpha) * d->filtered_mag;

    // Warm-up phase: adapt baseline, but do not alarm
    if (d->warmup_count < d->warmup_limit) {
        d->warmup_count++;
        // Exponential moving average updates
        float delta = d->filtered_mag - d->mean;
        d->mean += 0.01f * delta;
        d->var  += 0.01f * (delta * delta - d->var);
        return false;
    }

    // Update baseline before scoring OR after scoring depending on preference.
    // Here we score against current baseline, then slowly adapt baseline.
    float delta = d->filtered_mag - d->mean;
    float stddev = sqrtf(fmaxf(d->var, d->min_variance));
    float z = fabsf(delta) / stddev;

    bool anomaly = (z > d->z_threshold);

    // Slowly adapt baseline to normal changes
    if (!anomaly) {
        const float beta = 0.01f; // adaptation rate
        d->mean += beta * delta;
        d->var  += beta * ((delta * delta) - d->var);
    } else {
        // Optional: freeze adaptation on anomaly to avoid learning the anomaly
    }

    return anomaly;
}

/* Example usage:
 * Call detector_process_sample() at a fixed sample rate.
 * If using an ISR, keep it lightweight.
 */
#ifdef EXAMPLE_MAIN
#include <stdio.h>

int main(void)
{
    AnomalyDetector det;
    detector_init(&det, 0.2f, 200, 4.0f);

    // Example stream
    float samples[][3] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.10f, 0.20f, 1.40f}, // likely anomaly
        {0.01f, 0.02f, 1.00f},
    };

    for (int i = 0; i < 5; i++) {
        bool anom = detector_process_sample(&det,
                                            samples[i][0],
                                            samples[i][1],
                                            samples[i][2]);
        printf("Sample %d: anomaly=%s\n", i, anom ? "true" : "false");
    }

    return 0;
}
#endif
```

