Below is a compact embedded-friendly C implementation for an accelerometer anomaly-detection pipeline.

It uses:
- sampling at fixed rate,
- a high-pass style bias removal via running mean,
- feature extraction over a sliding window,
- anomaly detection using a simple z-score-like energy metric,
- a small ring buffer suitable for microcontrollers.

You can adapt the thresholds and window sizes to your sensor and application.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define AXES                 3
#define WINDOW_SIZE          32   // number of samples per feature window
#define MEAN_ALPHA_NUM        1   // running mean smoothing numerator
#define MEAN_ALPHA_DEN       64   // running mean smoothing denominator
#define ANOMALY_THRESHOLD   3.50f  // tune based on behavior
#define MIN_VAR_EPS       0.0001f  // avoid divide-by-zero

/* =========================
 * Data structures
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // running baseline/bias estimate
    float mean_x;
    float mean_y;
    float mean_z;

    // window buffer
    AccelSample window[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;

    // feature accumulators
    float sum_mag;
    float sum_mag2;
} AnomalyDetector;

/* =========================
 * Utility functions
 * ========================= */
static inline float fg_absf(float v) {
    return (v < 0.0f) ? -v : v;
}

static inline float fg_sqrtf(float v) {
    return sqrtf(v);
}

static inline float accel_magnitude(const AccelSample *s) {
    return fg_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

/* =========================
 * Initialization
 * ========================= */
void detector_init(AnomalyDetector *det) {
    det->mean_x = 0.0f;
    det->mean_y = 0.0f;
    det->mean_z = 0.0f;
    det->idx = 0;
    det->count = 0;
    det->sum_mag = 0.0f;
    det->sum_mag2 = 0.0f;
}

/* =========================
 * Internal: update running mean
 * ========================= */
static void update_running_mean(AnomalyDetector *det, const AccelSample *s) {
    // Exponential moving average
    det->mean_x += ((s->x - det->mean_x) * MEAN_ALPHA_NUM) / MEAN_ALPHA_DEN;
    det->mean_y += ((s->y - det->mean_y) * MEAN_ALPHA_NUM) / MEAN_ALPHA_DEN;
    det->mean_z += ((s->z - det->mean_z) * MEAN_ALPHA_NUM) / MEAN_ALPHA_DEN;
}

/* =========================
 * Push sample into pipeline
 * Returns true if anomaly detected on this window.
 * ========================= */
bool detector_process_sample(AnomalyDetector *det, const AccelSample *raw, float *out_score) {
    // 1) Update baseline
    update_running_mean(det, raw);

    // 2) Remove baseline
    AccelSample centered;
    centered.x = raw->x - det->mean_x;
    centered.y = raw->y - det->mean_y;
    centered.z = raw->z - det->mean_z;

    // 3) Compute feature: magnitude of centered acceleration
    float mag = accel_magnitude(&centered);

    // 4) Maintain sliding window stats
    if (det->count < WINDOW_SIZE) {
        det->window[det->idx] = centered;
        det->sum_mag += mag;
        det->sum_mag2 += (mag * mag);
        det->count++;
    } else {
        // remove old
        AccelSample old = det->window[det->idx];
        float old_mag = accel_magnitude(&old);
        det->sum_mag -= old_mag;
        det->sum_mag2 -= (old_mag * old_mag);

        // add new
        det->window[det->idx] = centered;
        det->sum_mag += mag;
        det->sum_mag2 += (mag * mag);
    }

    det->idx++;
    if (det->idx >= WINDOW_SIZE) det->idx = 0;

    // 5) Need enough samples before evaluating
    if (det->count < WINDOW_SIZE) {
        if (out_score) *out_score = 0.0f;
        return false;
    }

    // 6) Compute mean and variance of magnitude
    float mean = det->sum_mag / (float)WINDOW_SIZE;
    float var = (det->sum_mag2 / (float)WINDOW_SIZE) - (mean * mean);
    if (var < MIN_VAR_EPS) var = MIN_VAR_EPS;

    // 7) Z-like score for current magnitude
    float score = fg_absf(mag - mean) / fg_sqrtf(var);
    if (out_score) *out_score = score;

    // 8) Detect anomaly
    return (score > ANOMALY_THRESHOLD);
}

/* =========================
 * Example usage
 * ========================= */
