int main(void) {
    AnomalyDetector det;
    detector_init(&det);

    while (1) {
        AccelSample s = read_accelerometer(); // your driver call
        float score;
        bool anomaly = detector_process_sample(&det, &s, &score);

        if (anomaly) {
            // Trigger alert, log event, etc.
            printf("Anomaly detected! score=%.2f\n", score);
        }
    }
}
*/
