- ingests 3-axis accelerometer samples,
- applies a simple low-pass filter,
- computes magnitude and a motion score,
- maintains a running baseline,
- flags anomalies when the signal deviates significantly.

It avoids dynamic allocation and uses fixed-size state only.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded anomaly detection pipeline for accelerometer data.
 * Assumptions:
 * - Samples arrive at a fixed rate.
 * - accel values are in g units (or any consistent unit).
 * - One sample = one 3-axis vector.
 */

#define ALPHA_LP      0.20f   // low-pass smoothing factor
#define ALPHA_BASE    0.01f   // baseline adaptation rate
#define ANOM_THRESH   0.35f   // anomaly threshold on deviation
#define MIN_BASELINE  0.05f   // avoid divide-by-zero / instability

typedef struct {
    float lp_x;
    float lp_y;
    float lp_z;

    float baseline_mag;
    float prev_mag;

    uint32_t sample_count;
    uint8_t  anomaly_streak;
} AccelAnomalyDetector;

typedef struct {
    float lp_x;
    float lp_y;
    float lp_z;
    float magnitude;
    float deviation;
    bool  anomaly;
} AccelResult;

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

void detector_init(AccelAnomalyDetector *d) {
    d->lp_x = 0.0f;
    d->lp_y = 0.0f;
    d->lp_z = 0.0f;

    d->baseline_mag = 1.0f;   // assume ~1g at rest
    d->prev_mag = 1.0f;

    d->sample_count = 0;
    d->anomaly_streak = 0;
}

static float low_pass(float prev, float input, float alpha) {
    return prev + alpha * (input - prev);
}

AccelResult detector_process_sample(AccelAnomalyDetector *d,
                                    float ax, float ay, float az)
{
    AccelResult out;

    // 1) Low-pass filter per axis
    d->lp_x = low_pass(d->lp_x, ax, ALPHA_LP);
    d->lp_y = low_pass(d->lp_y, ay, ALPHA_LP);
    d->lp_z = low_pass(d->lp_z, az, ALPHA_LP);

    // 2) Compute magnitude
    out.lp_x = d->lp_x;
    out.lp_y = d->lp_y;
    out.lp_z = d->lp_z;

    out.magnitude = fast_sqrtf(d->lp_x * d->lp_x +
                               d->lp_y * d->lp_y +
                               d->lp_z * d->lp_z);

    // 3) Update baseline magnitude slowly
    if (d->sample_count == 0) {
        d->baseline_mag = out.magnitude;
    } else {
        d->baseline_mag = low_pass(d->baseline_mag, out.magnitude, ALPHA_BASE);
    }

    if (d->baseline_mag < MIN_BASELINE) {
        d->baseline_mag = MIN_BASELINE;
    }

    // 4) Relative deviation from baseline
    out.deviation = fabsf(out.magnitude - d->baseline_mag) / d->baseline_mag;

    // 5) Anomaly decision
    out.anomaly = (out.deviation > ANOM_THRESH);

    // Optional: require a streak to reduce false positives
    if (out.anomaly) {
        if (d->anomaly_streak < 255) d->anomaly_streak++;
    } else {
        d->anomaly_streak = 0;
    }

    // Example: only escalate after 3 consecutive anomalies
    if (d->anomaly_streak >= 3) {
        out.anomaly = true;
    }

    d->prev_mag = out.magnitude;
    d->sample_count++;

    return out;
}
