Below is a compact, embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accelerometer samples
- removes gravity roughly with a high-pass filter
- computes a smoothed motion magnitude
- maintains a running baseline and variance
- flags anomalies when the signal deviates strongly from normal

This is designed for small MCUs: no dynamic allocation, no heavy math libraries, and O(1) per sample.

```c
/*
 * Embedded accelerometer anomaly detector
 *
 * Pipeline:
 *   1) High-pass filter each axis to remove gravity / DC drift
 *   2) Compute magnitude of the dynamic acceleration
 *   3) Exponential moving average (EMA) for baseline
 *   4) Exponential moving variance for deviation estimate
 *   5) Flag anomaly when z-score exceeds a threshold
 *
 * Suitable for bare-metal or RTOS environments.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

typedef struct {
    float hp_alpha;        // High-pass filter alpha, [0..1], closer to 1 = slower cutoff
    float ema_alpha;       // Baseline EMA alpha, [0..1], closer to 1 = slower adaptation
    float var_alpha;       // Variance EMA alpha, [0..1], closer to 1 = slower adaptation
    float z_threshold;    // Anomaly threshold in standard deviations
    float min_var;         // Minimum variance to avoid divide-by-zero
    uint16_t warmup_samples; // Initial samples before anomaly decisions are trusted
} AnomalyConfig;

/* ---------------- State ---------------- */

typedef struct {
    AnomalyConfig cfg;

    // High-pass filter state
    float prev_x, prev_y, prev_z;
    float hp_x, hp_y, hp_z;
    bool hp_initialized;

    // Baseline and variance tracking
    float mean;
    float var;

    // Sample counter
    uint32_t sample_count;

    // Last computed values
    float last_magnitude;
    float last_zscore;
    bool anomaly;
} AnomalyDetector;

/* ---------------- Utility ---------------- */

static inline float fast_sqrtf(float x) {
    return sqrtf(x);
}

static inline float safe_fabsf(float x) {
    return x < 0.0f ? -x : x;
}

/* ---------------- Initialization ---------------- */

void anomaly_init(AnomalyDetector *d, AnomalyConfig cfg) {
    d->cfg = cfg;

    d->prev_x = d->prev_y = d->prev_z = 0.0f;
    d->hp_x = d->hp_y = d->hp_z = 0.0f;
    d->hp_initialized = false;

    d->mean = 0.0f;
    d->var = 1.0f;

    d->sample_count = 0;
    d->last_magnitude = 0.0f;
    d->last_zscore = 0.0f;
    d->anomaly = false;
}

/* ---------------- Processing ---------------- */

/*
 * Process one accelerometer sample.
 * Inputs are in g or m/s^2, but should be consistent.
 */
bool anomaly_process_sample(AnomalyDetector *d, float ax, float ay, float az) {
    // Initialize high-pass filter on first sample
    if (!d->hp_initialized) {
        d->prev_x = ax;
        d->prev_y = ay;
        d->prev_z = az;
        d->hp_initialized = true;
    }

    // High-pass filter to remove gravity / DC component:
    // y[n] = alpha * (y[n-1] + x[n] - x[n-1])
    d->hp_x = d->cfg.hp_alpha * (d->hp_x + ax - d->prev_x);
    d->hp_y = d->cfg.hp_alpha * (d->hp_y + ay - d->prev_y);
    d->hp_z = d->cfg.hp_alpha * (d->hp_z + az - d->prev_z);

    d->prev_x = ax;
    d->prev_y = ay;
    d->prev_z = az;

    // Dynamic acceleration magnitude
    float mag = fast_sqrtf(d->hp_x * d->hp_x + d->hp_y * d->hp_y + d->hp_z * d->hp_z);
    d->last_magnitude = mag;

    // Exponential moving average for baseline
    if (d->sample_count == 0) {
        d->mean = mag;
        d->var = d->cfg.min_var;
    } else {
        float delta = mag - d->mean;
        d->mean += d->cfg.ema_alpha * delta;

        // Exponential moving variance estimate
        // var <- (1-a)*var + a*(x-mean)^2
        float err = mag - d->mean;
        d->var = (1.0f - d->cfg.var_alpha) * d->var + d->cfg.var_alpha * (err * err);
        if (d->var < d->cfg.min_var) {
            d->var = d->cfg.min_var;
        }
    }

    // Z-score
    float stddev = fast_sqrtf(d->var);
    float z = safe_fabsf(mag - d->mean) / stddev;
    d->last_zscore = z;

    d->sample_count++;

    // Warmup period: learn baseline, do not flag anomalies
    if (d->sample_count < d->cfg.warmup_samples) {
        d->anomaly = false;
        return false;
    }

    // Anomaly decision
    d->anomaly = (z > d->cfg.z_threshold);
    return d->anomaly;
}

/* ---------------- Accessors ---------------- */

float anomaly_last_magnitude(const AnomalyDetector *d) {
    return d->last_magnitude;
}

float anomaly_last_zscore(const AnomalyDetector *d) {
    return d->last_zscore;
}

float anomaly_current_mean(const AnomalyDetector *d) {
    return d->mean;
}

float anomaly_current_variance(const AnomalyDetector *d) {
    return d->var;
}

bool anomaly_is_detected(const AnomalyDetector *d) {
    return d->anomaly;
}

/* ---------------- Example usage ---------------- */

#ifdef EXAMPLE_MAIN
#include <stdio.h>

int main(void) {
    AnomalyDetector detector;

    AnomalyConfig cfg = {
        .hp_alpha = 0.98f,
        .ema_alpha = 0.01f,
        .var_alpha = 0.02f,
        .z_threshold = 3.5f,
        .min_var = 1e-4f,
        .warmup_samples = 100
    };

    anomaly_init(&detector, cfg);

    // Example stream
    float samples[][3] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {1.50f, 0.80f, 0.20f}, // likely anomaly
        {0.01f, 0.02f, 1.00f},
    };

    for (int i = 0; i < 5; i++) {
        bool anomaly = anomaly_process_sample(&detector,
                                              samples[i][0],
                                              samples[i][1],
                                              samples[i][2]);

        printf("Sample %d: mag=%.4f z=%.4f mean=%.4f var=%.6f anomaly=%s\n",
               i,
               anomaly_last_magnitude(&detector),
               anomaly_last_zscore(&detector),
               anomaly_current_mean(&detector),
               anomaly_current_variance(&detector),
               anomaly ? "YES" : "NO");
    }

    return 0;
}
#endif
```

### Tuning guidance

- `hp_alpha`
  - Higher values reduce gravity more slowly
  - Typical range: `0.95f` to `0.995f`

- `ema_alpha` and `var_alpha`
  - Small values adapt slowly and are more stable
  - Typical range: `0.005f` to `0.05f`

- `z_threshold`
  - Lower = more sensitive, more false positives
  - Typical range: `3.0f` to `5.0f`

- `warmup_samples`
  - Let the baseline learn normal motion first
  - Set based on sampling rate and expected startup conditions

### Notes for real embedded deployment

- If your MCU lacks an FPU, consider fixed-point arithmetic.
- If you want lower CPU use, replace `sqrtf` with an approximate norm or compare squared z-score instead.
- If the accelerometer has known orientation, you may get better results by removing gravity using a low-pass gravity estimate instead of a high-pass filter.
- To reduce false alarms, add a persistence rule such as “anomaly only if 3 of last 5 samples exceed threshold.”

