```c
// Embedded accelerometer anomaly detection pipeline
// Features:
// 1) Fixed-size ring buffer for recent samples
// 2) Simple high-pass style detrending via running mean
// 3) RMS + peak-to-peak + jerk-based anomaly scoring
// 4) Threshold-based detection with hysteresis
//
// Target: small embedded systems (C99, no dynamic allocation)

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define AXIS_COUNT          3
#define WINDOW_SIZE         64     // must be power of 2 for fast wrap
#define WINDOW_MASK         (WINDOW_SIZE - 1)

#define RMS_THRESHOLD_G     1.8f
#define P2P_THRESHOLD_G     3.5f
#define JERK_THRESHOLD_GPS  20.0f   // g/s
#define ANOMALY_SCORE_ON    2
#define ANOMALY_SCORE_OFF   1

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;

    // running sums for mean
    float sum_x, sum_y, sum_z;

    // state
    bool anomaly_active;
    uint8_t anomaly_score;
} accel_pipeline_t;

static inline float fmax3(float a, float b, float c) {
    float m = (a > b) ? a : b;
    return (m > c) ? m : c;
}

static inline float fmin3(float a, float b, float c) {
    float m = (a < b) ? a : b;
    return (m < c) ? m : c;
}

static inline float vec_mag(accel_sample_t s) {
    return sqrtf(s.x*s.x + s.y*s.y + s.z*s.z);
}

void accel_pipeline_init(accel_pipeline_t *p) {
    p->head = 0;
    p->count = 0;
    p->sum_x = p->sum_y = p->sum_z = 0.0f;
    p->anomaly_active = false;
    p->anomaly_score = 0;
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        p->buf[i].x = p->buf[i].y = p->buf[i].z = 0.0f;
    }
}

static void remove_oldest_if_full(accel_pipeline_t *p) {
    if (p->count == WINDOW_SIZE) {
        uint16_t tail = p->head;
        accel_sample_t old = p->buf[tail];
        p->sum_x -= old.x;
        p->sum_y -= old.y;
        p->sum_z -= old.z;
    } else {
        p->count++;
    }
}

void accel_pipeline_push(accel_pipeline_t *p, accel_sample_t s, float sample_dt_sec) {
    // Insert
    remove_oldest_if_full(p);
    p->buf[p->head] = s;
    p->sum_x += s.x;
    p->sum_y += s.y;
    p->sum_z += s.z;
    p->head = (p->head + 1) & WINDOW_MASK;

    if (p->count < 8) {
        // Not enough data yet for stable stats
        p->anomaly_active = false;
        p->anomaly_score = 0;
        return;
    }

    // Compute window mean
    float inv_n = 1.0f / (float)p->count;
    accel_sample_t mean = {
        .x = p->sum_x * inv_n,
        .y = p->sum_y * inv_n,
        .z = p->sum_z * inv_n
    };

    // Compute metrics over window:
    // - RMS of magnitude deviation from mean magnitude
    // - Peak-to-peak per axis
    // - Approx jerk from latest two samples
    float rms_accum = 0.0f;
    float min_x =  1e9f, min_y =  1e9f, min_z =  1e9f;
    float max_x = -1e9f, max_y = -1e9f, max_z = -1e9f;

    uint16_t idx = (p->head + WINDOW_SIZE - p->count) & WINDOW_MASK;
    for (uint16_t i = 0; i < p->count; i++) {
        accel_sample_t v = p->buf[idx];
        float dx = v.x - mean.x;
        float dy = v.y - mean.y;
        float dz = v.z - mean.z;
        rms_accum += dx*dx + dy*dy + dz*dz;

        if (v.x < min_x) min_x = v.x;
        if (v.y < min_y) min_y = v.y;
        if (v.z < min_z) min_z = v.z;

        if (v.x > max_x) max_x = v.x;
        if (v.y > max_y) max_y = v.y;
        if (v.z > max_z) max_z = v.z;

        idx = (idx + 1) & WINDOW_MASK;
    }

    float rms = sqrtf(rms_accum / (float)p->count);
    float p2p = fmax3(max_x - min_x, max_y - min_y, max_z - min_z);

    // Latest and previous sample for jerk
    uint16_t last_idx = (p->head + WINDOW_SIZE - 1) & WINDOW_MASK;
    uint16_t prev_idx = (p->head + WINDOW_SIZE - 2) & WINDOW_MASK;
    accel_sample_t last = p->buf[last_idx];
    accel_sample_t prev = p->buf[prev_idx];

    float dvx = (last.x - prev.x) / sample_dt_sec;
    float dvy = (last.y - prev.y) / sample_dt_sec;
    float dvz = (last.z - prev.z) / sample_dt_sec;
    float jerk = sqrtf(dvx*dvx + dvy*dvy + dvz*dvz);

    // Scoring
    uint8_t score = 0;
    if (rms > RMS_THRESHOLD_G)      score++;
    if (p2p > P2P_THRESHOLD_G)      score++;
    if (jerk > JERK_THRESHOLD_GPS)  score++;

    // Hysteresis
    if (score >= ANOMALY_SCORE_ON) {
        p->anomaly_active = true;
        p->anomaly_score = score;
    } else if (score <= ANOMALY_SCORE_OFF) {
        p->anomaly_active = false;
        p->anomaly_score = score;
    } else {
        // Hold previous state in the gray zone
        p->anomaly_score = score;
    }
}

bool accel_pipeline_is_anomaly(const accel_pipeline_t *p) {
    return p->anomaly_active;
}

uint8_t accel_pipeline_score(const accel_pipeline_t *p) {
    return p->anomaly_score;
}
