Below is a compact C implementation of an embedded-friendly accelerometer anomaly detector. It uses:

- a ring buffer for recent samples
- a low-cost moving average / variance estimate
- magnitude-based feature extraction
- simple z-score anomaly detection
- a debounced anomaly flag to reduce false positives

It is designed to be cheap enough for MCU use and easy to adapt to fixed-point later.

```c
/*
 * Embedded accelerometer anomaly detector
 *
 * Features:
 * - Uses magnitude of 3-axis accelerometer
 * - Moving average + moving variance over a small window
 * - Z-score threshold anomaly detection
 * - Debounce counter to avoid one-sample spikes
 *
 * Assumptions:
 * - accel data is in "g" units or consistent raw units
 * - called at fixed sample rate
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE        32
#define ANOMALY_Z_THRESH   3.5f
#define ANOMALY_HIT_COUNT   3
#define EPSILON             1e-6f

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sumsq;
} ring_stats_t;

typedef struct {
    ring_stats_t stats;
    uint8_t anomaly_hits;
    bool anomaly_active;
} anomaly_detector_t;

static void ring_stats_init(ring_stats_t *rs)
{
    rs->index = 0;
    rs->count = 0;
    rs->sum = 0.0f;
    rs->sumsq = 0.0f;
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        rs->buffer[i] = 0.0f;
    }
}

static void ring_stats_push(ring_stats_t *rs, float value)
{
    if (rs->count < WINDOW_SIZE) {
        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sumsq += value * value;
        rs->count++;
    } else {
        float old = rs->buffer[rs->index];
        rs->sum -= old;
        rs->sumsq -= old * old;

        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sumsq += value * value;
    }

    rs->index = (rs->index + 1) % WINDOW_SIZE;
}

static float ring_stats_mean(const ring_stats_t *rs)
{
    if (rs->count == 0) return 0.0f;
    return rs->sum / (float)rs->count;
}

static float ring_stats_variance(const ring_stats_t *rs)
{
    if (rs->count < 2) return 0.0f;

    float n = (float)rs->count;
    float mean = rs->sum / n;
    float var = (rs->sumsq / n) - (mean * mean);

    if (var < 0.0f) var = 0.0f; // guard numerical error
    return var;
}

static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

void anomaly_detector_init(anomaly_detector_t *det)
{
    ring_stats_init(&det->stats);
    det->anomaly_hits = 0;
    det->anomaly_active = false;
}

/*
 * Returns true if anomaly is detected at this sample.
 * The detector becomes active only after a few consecutive hits.
 */
bool anomaly_detector_update(anomaly_detector_t *det, const accel_sample_t *sample)
{
    float mag = accel_magnitude(sample);

    // Need some history before detection is reliable
    if (det->stats.count < WINDOW_SIZE / 2) {
        ring_stats_push(&det->stats, mag);
        return false;
    }

    float mean = ring_stats_mean(&det->stats);
    float var = ring_stats_variance(&det->stats);
    float stddev = sqrtf(var);

    float z = 0.0f;
    if (stddev > EPSILON) {
        z = fabsf(mag - mean) / stddev;
    }

    bool is_anomaly = (z > ANOMALY_Z_THRESH);

    // Update debounce state
    if (is_anomaly) {
        if (det->anomaly_hits < 255) {
            det->anomaly_hits++;
        }
    } else {
        det->anomaly_hits = 0;
        det->anomaly_active = false;
    }

    if (det->anomaly_hits >= ANOMALY_HIT_COUNT) {
        det->anomaly_active = true;
    }

    // Push after checking so current sample doesn't bias threshold
    ring_stats_push(&det->stats, mag);

    return det->anomaly_active;
}
