#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 * - Fixed-size ring buffer
 * - DC removal via EMA
 * - Magnitude estimation
 * - Rolling mean / variance
 * - Z-score threshold anomaly detection
 *
 * Designed to be lightweight and suitable for MCU use.
 */

#ifndef WINDOW_SIZE
#define WINDOW_SIZE   32
#endif

#ifndef EMA_SHIFT
#define EMA_SHIFT     5   // alpha = 1/32
#endif

#ifndef Z_THRESHOLD
#define Z_THRESHOLD   4.0f
#endif

#ifndef MIN_SAMPLES
#define MIN_SAMPLES   WINDOW_SIZE
#endif

typedef struct {
    int32_t x, y, z;
} accel_sample_t;

typedef struct {
    float mean;
    float m2;
    uint32_t n;
} welford_t;

typedef struct {
    // DC estimation
    int32_t dc_x;
    int32_t dc_y;
    int32_t dc_z;

    // Rolling statistics on magnitude
    float mag_buf[WINDOW_SIZE];
    uint32_t idx;
    uint32_t count;

    welford_t stats;

    // Anomaly state
    bool anomaly;
    float z_score;
    float last_mag;
} anomaly_detector_t;

static inline float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static inline float magnitude3(int32_t x, int32_t y, int32_t z) {
    return fast_sqrtf((float)x * (float)x +
                      (float)y * (float)y +
                      (float)z * (float)z);
}

static inline void welford_init(welford_t *w) {
    w->mean = 0.0f;
    w->m2 = 0.0f;
    w->n = 0;
}

static inline void welford_add(welford_t *w, float x) {
    w->n++;
    float delta = x - w->mean;
    w->mean += delta / (float)w->n;
    float delta2 = x - w->mean;
    w->m2 += delta * delta2;
}

static inline float welford_variance(const welford_t *w) {
    return (w->n > 1) ? (w->m2 / (float)(w->n - 1)) : 0.0f;
}

void anomaly_detector_init(anomaly_detector_t *d) {
    d->dc_x = 0;
    d->dc_y = 0;
    d->dc_z = 0;
    d->idx = 0;
    d->count = 0;
    d->anomaly = false;
    d->z_score = 0.0f;
    d->last_mag = 0.0f;
    welford_init(&d->stats);

    for (uint32_t i = 0; i < WINDOW_SIZE; i++) {
        d->mag_buf[i] = 0.0f;
    }
}

static inline accel_sample_t remove_dc(anomaly_detector_t *d, accel_sample_t s) {
    // Exponential moving average for bias/DC tracking
    d->dc_x += (s.x - d->dc_x) >> EMA_SHIFT;
    d->dc_y += (s.y - d->dc_y) >> EMA_SHIFT;
    d->dc_z += (s.z - d->dc_z) >> EMA_SHIFT;

    accel_sample_t out;
    out.x = s.x - d->dc_x;
    out.y = s.y - d->dc_y;
    out.z = s.z - d->dc_z;
    return out;
}

static inline void update_stats_with_rolling_window(anomaly_detector_t *d, float mag) {
    // Recompute mean/variance from window (simple and deterministic).
    // For small WINDOW_SIZE, this is often acceptable on embedded targets.
    d->mag_buf[d->idx] = mag;
    d->idx = (d->idx + 1u) % WINDOW_SIZE;

    if (d->count < WINDOW_SIZE) {
        d->count++;
    }

    welford_init(&d->stats);
    for (uint32_t i = 0; i < d->count; i++) {
        welford_add(&d->stats, d->mag_buf[i]);
    }
}

bool anomaly_detector_process(anomaly_detector_t *d, accel_sample_t raw) {
    accel_sample_t ac = remove_dc(d, raw);
    float mag = magnitude3(ac.x, ac.y, ac.z);
    d->last_mag = mag;

    update_stats_with_rolling_window(d, mag);

    if (d->count < MIN_SAMPLES) {
        d->anomaly = false;
        d->z_score = 0.0f;
        return false;
    }

    float mean = d->stats.mean;
    float var = welford_variance(&d->stats);
    float stddev = fast_sqrtf(var + 1e-6f);

    d->z_score = (mag - mean) / stddev;

    d->anomaly = (fabsf(d->z_score) >= Z_THRESHOLD);
    return d->anomaly;
}

/* Optional helper for debugging/telemetry */
typedef struct {
    float last_mag;
    float mean;
    float variance;
    float z_score;
    bool anomaly;
} anomaly_status_t;

void anomaly_detector_get_status(const anomaly_detector_t *d, anomaly_status_t *s) {
    s->last_mag = d->last_mag;
    s->mean = d->stats.mean;
    s->variance = welford_variance(&d->stats);
    s->z_score = d->z_score;
    s->anomaly = d->anomaly;
}

