```c
/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 *  - Fixed-size ring buffer for streaming samples
 *  - Lightweight high-pass / magnitude processing
 *  - Sliding-window statistics
 *  - Simple anomaly score based on deviation from baseline
 *
 * Assumptions:
 *  - 3-axis accelerometer samples arrive at a fixed sampling rate
 *  - MCU has limited RAM and no malloc
 *  - You can call sensor_pipeline_push_sample() once per new sample
 *
 * Adapt thresholds/window sizes to your sensor and application.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

#define WINDOW_SIZE         64
#define BASELINE_DECAY_SHIFT 6   /* 1/64 EMA update */
#define GRAVITY_EST_SHIFT    8   /* 1/256 EMA update */

#define ANOMALY_SCORE_LIMIT  5000
#define MIN_SCORE_COUNT      3    /* consecutive windows above threshold */

/* If your accel is in raw counts, adjust scale accordingly */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_sample_t;

/* ---------------- State ---------------- */

typedef struct {
    accel_sample_t window[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;

    /* Baseline mean and variance estimates of magnitude */
    int32_t baseline_mean;   /* Q0 integer magnitude */
    int32_t baseline_var;    /* variance estimate */

    /* Gravity estimate for high-pass-ish detrending */
    int32_t gx;
    int32_t gy;
    int32_t gz;

    /* Consecutive anomaly counter */
    uint8_t anomaly_streak;
} sensor_pipeline_t;

/* ---------------- Utility ---------------- */

static int32_t iabs32(int32_t v) {
    return (v < 0) ? -v : v;
}

static int32_t isqrt32(uint32_t x) {
    /* Integer sqrt (binary restoring method) */
    uint32_t op = x;
    uint32_t res = 0;
    uint32_t one = 1u << 30;

    while (one > op) {
        one >>= 2;
    }

    while (one != 0) {
        if (op >= res + one) {
            op -= res + one;
            res = (res >> 1) + one;
        } else {
            res >>= 1;
        }
        one >>= 2;
    }
    return (int32_t)res;
}

static int32_t accel_magnitude_i32(const accel_sample_t *s) {
    /* Use squared magnitude with integer sqrt to avoid floating point */
    int32_t xx = (int32_t)s->x * (int32_t)s->x;
    int32_t yy = (int32_t)s->y * (int32_t)s->y;
    int32_t zz = (int32_t)s->z * (int32_t)s->z;
    uint32_t mag2 = (uint32_t)(xx + yy + zz);
    return isqrt32(mag2);
}

/* ---------------- API ---------------- */

void sensor_pipeline_init(sensor_pipeline_t *p) {
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        p->window[i].x = 0;
        p->window[i].y = 0;
        p->window[i].z = 0;
    }

    p->head = 0;
    p->count = 0;
    p->baseline_mean = 0;
    p->baseline_var = 0;
    p->gx = 0;
    p->gy = 0;
    p->gz = 0;
    p->anomaly_streak = 0;
}

/*
 * Returns true if anomaly detected for the current window.
 * Call after each new sample.
 */
bool sensor_pipeline_push_sample(sensor_pipeline_t *p, accel_sample_t s) {
    /* Update gravity estimate (slow EMA) */
    if (p->gx == 0 && p->gy == 0 && p->gz == 0) {
        p->gx = s.x;
        p->gy = s.y;
        p->gz = s.z;
    } else {
        p->gx += ((int32_t)s.x - p->gx) >> GRAVITY_EST_SHIFT;
        p->gy += ((int32_t)s.y - p->gy) >> GRAVITY_EST_SHIFT;
        p->gz += ((int32_t)s.z - p->gz) >> GRAVITY_EST_SHIFT;
    }

    /* Detrended sample not explicitly stored; compute magnitude of residual */
    accel_sample_t residual;
    residual.x = (int16_t)((int32_t)s.x - p->gx);
    residual.y = (int16_t)((int32_t)s.y - p->gy);
    residual.z = (int16_t)((int32_t)s.z - p->gz);

    int32_t residual_mag = accel_magnitude_i32(&residual);

    /* Update baseline mean/variance with EMA */
    if (p->baseline_mean == 0) {
        p->baseline_mean = residual_mag;
        p->baseline_var = 1;
    } else {
        int32_t diff = residual_mag - p->baseline_mean;
        p->baseline_mean += diff >> BASELINE_DECAY_SHIFT;

        /* Welford-like EMA variance estimate */
        int32_t absdiff = iabs32(diff);
        p->baseline_var += ((absdiff * absdiff) - p->baseline_var) >> BASELINE_DECAY_SHIFT;
        if (p->baseline_var < 1) {
            p->baseline_var = 1;
        }
    }

    /* Store in window for optional downstream processing */
    p->window[p->head] = s;
    p->head = (p->head + 1) % WINDOW_SIZE;
    if (p->count < WINDOW_SIZE) {
        p->count++;
    }

    /* Anomaly score: deviation from baseline in units of estimated spread */
    int32_t stddev = isqrt32((uint32_t)p->baseline_var);
    if (stddev < 1) {
        stddev = 1;
    }

    int32_t deviation = iabs32(residual_mag - p->baseline_mean);
    int32_t score = (deviation * 1000) / stddev;

    bool anomaly = false;
    if (score > ANOMALY_SCORE_LIMIT) {
        if (p->anomaly_streak < 255) {
            p->anomaly_streak++;
        }
    } else {
        p->anomaly_streak = 0;
    }

    if (p->anomaly_streak >= MIN_SCORE_COUNT) {
        anomaly = true;
    }

    return anomaly;
}

/* Optional: retrieve current anomaly score */
int32_t sensor_pipeline_get_score(const sensor_pipeline_t *p, accel_sample_t s) {
    accel_sample_t residual;
    residual.x = (int16_t)((int32_t)s.x - p->gx);
    residual.y = (int16_t)((int32_t)s.y - p->gy);
    residual.z = (int16_t)((int32_t)s.z - p->gz);

    int32_t residual_mag = accel_magnitude_i32(&residual);
    int32_t stddev = isqrt32((uint32_t)p->baseline_var);
    if (stddev < 1) {
        stddev = 1;
    }

    int32_t deviation = iabs32(residual_mag - p->baseline_mean);
    return (deviation * 1000) / stddev;
}
