Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline. It reads samples, applies basic filtering, computes features over a sliding window, and flags anomalies when motion deviates from a learned baseline.

### Assumptions
- 3-axis accelerometer data: `ax, ay, az`
- Sample rate is fixed
- Small RAM/CPU budget
- No dynamic allocation
- Runs on bare metal or RTOS

---

## C code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE          32
#define BASELINE_COUNT       256
#define ANOMALY_Z_THRESHOLD  3.0f
#define MIN_STABLE_VARIANCE   1e-4f

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float mag;
    float mean;
    float variance;
    float slope;
} feature_t;

typedef struct {
    accel_sample_t samples[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;
} sample_window_t;

typedef struct {
    float mean_mag;
    float var_mag;
    float mean_slope;
    float var_slope;
    bool trained;
    uint32_t baseline_samples;
} anomaly_model_t;

static sample_window_t g_window = {0};
static anomaly_model_t g_model = {0};

/* ---------- Utility ---------- */

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float accel_magnitude(const accel_sample_t *s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* ---------- Filtering ---------- */
/* Simple 1-pole low-pass filter for each axis */
static accel_sample_t lowpass_filter(const accel_sample_t *current,
                                     const accel_sample_t *previous,
                                     float alpha)
{
    accel_sample_t out;
    out.x = alpha * current->x + (1.0f - alpha) * previous->x;
    out.y = alpha * current->y + (1.0f - alpha) * previous->y;
    out.z = alpha * current->z + (1.0f - alpha) * previous->z;
    return out;
}

/* ---------- Window Management ---------- */

static void window_push(sample_window_t *w, const accel_sample_t *s) {
    w->samples[w->head] = *s;
    w->head = (w->head + 1U) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static accel_sample_t window_get_oldest(const sample_window_t *w) {
    uint16_t idx = (w->count < WINDOW_SIZE) ? 0U : w->head;
    return w->samples[idx];
}

/* ---------- Feature Extraction ---------- */

static feature_t extract_features(const sample_window_t *w) {
    feature_t f = {0};

    if (w->count == 0) {
        return f;
    }

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (uint16_t i = 0; i < w->count; i++) {
        float m = accel_magnitude(&w->samples[i]);
        sum += m;
        sum_sq += m * m;
    }

    f.mean = sum / (float)w->count;
    f.variance = (sum_sq / (float)w->count) - (f.mean * f.mean);
    if (f.variance < 0.0f) f.variance = 0.0f;

    /* Magnitude of newest sample */
    uint16_t newest_idx = (w->head == 0U) ? (WINDOW_SIZE - 1U) : (w->head - 1U);
    f.mag = accel_magnitude(&w->samples[newest_idx]);

    /* Simple slope: newest - oldest */
    accel_sample_t oldest = window_get_oldest(w);
    f.slope = f.mag - accel_magnitude(&oldest);

    return f;
}

/* ---------- Baseline Training ---------- */

static void baseline_update(anomaly_model_t *m, const feature_t *f) {
    /* Online mean/variance update using Welford-like approximation */
    m->baseline_samples++;

    float n = (float)m->baseline_samples;

    float delta_mag = f->mean - m->mean_mag;
    m->mean_mag += delta_mag / n;
    m->var_mag += delta_mag * (f->mean - m->mean_mag);

    float delta_slope = f->slope - m->mean_slope;
    m->mean_slope += delta_slope / n;
    m->var_slope += delta_slope * (f->slope - m->mean_slope);
}

static void baseline_finalize(anomaly_model_t *m) {
    if (m->baseline_samples > 1U) {
        m->var_mag /= (float)(m->baseline_samples - 1U);
        m->var_slope /= (float)(m->baseline_samples - 1U);
    } else {
        m->var_mag = MIN_STABLE_VARIANCE;
        m->var_slope = MIN_STABLE_VARIANCE;
    }

    if (m->var_mag < MIN_STABLE_VARIANCE) m->var_mag = MIN_STABLE_VARIANCE;
    if (m->var_slope < MIN_STABLE_VARIANCE) m->var_slope = MIN_STABLE_VARIANCE;

    m->trained = true;
}

/* ---------- Anomaly Detection ---------- */

static bool detect_anomaly(const anomaly_model_t *m, const feature_t *f) {
    if (!m->trained) return false;

    float z_mag = fabsf(f->mean - m->mean_mag) / fast_sqrtf(m->var_mag);
    float z_slope = fabsf(f->slope - m->mean_slope) / fast_sqrtf(m->var_slope);

    return (z_mag > ANOMALY_Z_THRESHOLD) || (z_slope > ANOMALY_Z_THRESHOLD);
}

/* ---------- Public API ---------- */

void anomaly_pipeline_reset(void) {
    g_window.head = 0;
    g_window.count = 0;
    g_model = (anomaly_model_t){0};
}

bool anomaly_pipeline_process(const accel_sample_t *raw_sample,
                              float alpha,
                              bool *anomaly_out)
{
    static bool filtered_init = false;
    static accel_sample_t prev_filtered = {0};

    if (!raw_sample || !anomaly_out) return false;

    accel_sample_t filtered;
    if (!filtered_init) {
        filtered = *raw_sample;
        prev_filtered = filtered;
        filtered_init = true;
    } else {
        filtered = lowpass_filter(raw_sample, &prev_filtered, alpha);
        prev_filtered = filtered;
    }

    window_push(&g_window, &filtered);

    /* Need enough data before meaningful features */
    if (g_window.count < WINDOW_SIZE) {
        *anomaly_out = false;
        return true;
    }

    feature_t feat = extract_features(&g_window);

    /* Training phase */
    if (!g_model.trained) {
        baseline_update(&g_model, &feat);
        if (g_model.baseline_samples >= BASELINE_COUNT) {
            baseline_finalize(&g_model);
        }
        *anomaly_out = false;
        return true;
    }

    /* Detection phase */
    *anomaly_out = detect_anomaly(&g_model, &feat);
    return true;
}
