Below is a compact C implementation suitable for an embedded pipeline. It:

- reads 3-axis accelerometer samples
- applies a simple high-pass / detrending step
- computes signal magnitude
- maintains a rolling baseline
- flags anomalies when the magnitude deviates significantly from the baseline

It is written to be lightweight and easy to port to bare-metal or RTOS environments.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32      // rolling window for baseline
#define ALPHA_BASELINE      0.02f    // EMA update rate for baseline
#define ANOMALY_THRESHOLD   3.5f    // z-like threshold
#define MIN_BASELINE_DEV    0.05f    // avoid divide-by-zero / tiny variance
#define SPIKE_DELTA_LIMIT   1.5f    // optional instant spike detector

/* =========================
 * Data structures
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean;
    float var;
    float stddev;
} Stats;

typedef struct {
    float baseline;
    float variance;
    float last_value;
    bool initialized;
} AnomalyDetector;

/* =========================
 * Utility functions
 * ========================= */
static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float magnitude3(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* Simple exponential moving average statistics. 
 * Suitable for embedded systems with limited RAM.
 */
static void stats_update(Stats *st, float x, float alpha) {
    float diff = x - st->mean;
    st->mean += alpha * diff;
    st->var = (1.0f - alpha) * (st->var + alpha * diff * diff);
    st->stddev = fast_sqrtf(st->var);
}

/* Initialize anomaly detector */
static void anomaly_init(AnomalyDetector *det, float initial_value) {
    det->baseline = initial_value;
    det->variance = 1.0f;
    det->last_value = initial_value;
    det->initialized = true;
}

/* Update detector and return true if anomaly detected */
static bool anomaly_update(AnomalyDetector *det, float value) {
    if (!det->initialized) {
        anomaly_init(det, value);
        return false;
    }

    /* Compute deviation from baseline */
    float deviation = value - det->baseline;
    float abs_dev = fabsf(deviation);
    float stddev = fast_sqrtf(det->variance);
    if (stddev < MIN_BASELINE_DEV) {
        stddev = MIN_BASELINE_DEV;
    }

    /* Spike detector: catches sudden jumps */
    float delta = fabsf(value - det->last_value);
    bool spike = (delta > SPIKE_DELTA_LIMIT);

    /* Z-like anomaly test */
    bool anomalous = (abs_dev > ANOMALY_THRESHOLD * stddev) || spike;

    /* Update baseline only if not anomalous */
    if (!anomalous) {
        float diff = value - det->baseline;
        det->baseline += ALPHA_BASELINE * diff;

        /* EMA variance update */
        float new_diff = value - det->baseline;
        det->variance = (1.0f - ALPHA_BASELINE) * det->variance
                        + ALPHA_BASELINE * new_diff * new_diff;
    }

    det->last_value = value;
    return anomalous;
}

/* Optional detrending / high-pass filter:
 * y[n] = alpha * (y[n-1] + x[n] - x[n-1])
 */
typedef struct {
    float alpha;
    float prev_input;
    float prev_output;
    bool initialized;
} HighPassFilter;

static void hpf_init(HighPassFilter *filt, float alpha) {
    filt->alpha = alpha;
    filt->prev_input = 0.0f;
    filt->prev_output = 0.0f;
    filt->initialized = false;
}

static float hpf_process(HighPassFilter *filt, float input) {
    if (!filt->initialized) {
        filt->prev_input = input;
        filt->prev_output = 0.0f;
        filt->initialized = true;
        return 0.0f;
    }

    float output = filt->alpha * (filt->prev_output + input - filt->prev_input);
    filt->prev_input = input;
    filt->prev_output = output;
    return output;
}

/* =========================
 * Pipeline
 * ========================= */
typedef struct {
    HighPassFilter hpf_x;
    HighPassFilter hpf_y;
    HighPassFilter hpf_z;
    AnomalyDetector detector;
} SensorPipeline;

static void pipeline_init(SensorPipeline *p) {
    /* alpha closer to 1.0 -> lower cutoff; adjust for sample rate */
    hpf_init(&p->hpf_x, 0.95f);
    hpf_init(&p->hpf_y, 0.95f);
    hpf_init(&p->hpf_z, 0.95f);

    anomaly_init(&p->detector, 0.0f);
}

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;
    float magnitude;
    bool anomaly;
} PipelineOutput;

static PipelineOutput pipeline_process(SensorPipeline *p, const AccelSample *raw) {
    PipelineOutput out;

    /* Detrend / high-pass filter per axis */
    out.filtered_x = hpf_process(&p->hpf_x, raw->x);
    out.filtered_y = hpf_process(&p->hpf_y, raw->y);
    out.filtered_z = hpf_process(&p->hpf_z, raw->z);

    /* Signal magnitude after filtering */
    out.magnitude = sqrtf(out.filtered_x * out.filtered_x +
                          out.filtered_y * out.filtered_y +
                          out.filtered_z * out.filtered_z);

    /* Detect anomaly */
    out.anomaly = anomaly_update(&p->detector, out.magnitude);

    return out;
}

/* =========================
 * Example usage
 * ========================= */
#ifdef DEMO_MAIN
#include <stdio.h>

int main(void) {
    SensorPipeline pipeline;
    pipeline_init(&pipeline);

    /* Example stream */
    AccelSample samples[] = {
        {0.02f, 0.01f, 1.00f},
        {0.03f, 0.02f, 0.99f},
        {0.01f, 0.00f, 1.01f},
        {0.25f, 0.40f, 1.80f},  // likely anomaly
        {0.02f, 0.01f, 1.00f},
    };

    for (unsigned i = 0; i < sizeof(samples)/sizeof(samples[0]); i++) {
        PipelineOutput out = pipeline_process(&pipeline, &samples[i]);
        printf("i=%u mag=%.3f anomaly=%s\n",
               i, out.magnitude, out.anomaly ? "YES" : "NO");
    }

    return 0;
}
#endif
```

