Below is a compact, embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accel samples
- applies a simple IIR low-pass filter
- computes magnitude
- maintains a rolling mean/variance
- flags anomalies when the magnitude deviates too far from the baseline

It is designed to be lightweight and suitable for MCU firmware.

```c
#include <stdint.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE     32
#define LPF_ALPHA       0.20f
#define Z_THRESHOLD     3.0f

typedef struct {
    float ax_f, ay_f, az_f;      // filtered axes
    float mag_window[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;

    float sum;
    float sum_sq;

    // last computed stats
    float mean;
    float stddev;
} AnomalyDetector;

static float fast_sqrtf(float x) {
    // For portability; replace with platform-specific optimized sqrt if needed.
    return sqrtf(x);
}

void detector_init(AnomalyDetector *d) {
    d->ax_f = d->ay_f = d->az_f = 0.0f;
    d->idx = 0;
    d->count = 0;
    d->sum = 0.0f;
    d->sum_sq = 0.0f;
    d->mean = 0.0f;
    d->stddev = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }
}

static float update_lpf(float prev, float sample) {
    return prev + LPF_ALPHA * (sample - prev);
}

static void rolling_stats_update(AnomalyDetector *d, float new_val) {
    if (d->count < WINDOW_SIZE) {
        d->mag_window[d->idx] = new_val;
        d->sum += new_val;
        d->sum_sq += new_val * new_val;
        d->count++;
        d->idx = (d->idx + 1) % WINDOW_SIZE;
    } else {
        float old = d->mag_window[d->idx];
        d->sum -= old;
        d->sum_sq -= old * old;

        d->mag_window[d->idx] = new_val;
        d->sum += new_val;
        d->sum_sq += new_val * new_val;
        d->idx = (d->idx + 1) % WINDOW_SIZE;
    }

    if (d->count > 0) {
        d->mean = d->sum / d->count;
        float var = (d->sum_sq / d->count) - (d->mean * d->mean);
        if (var < 0.0f) var = 0.0f;
        d->stddev = fast_sqrtf(var);
    }
}

bool detector_process_sample(AnomalyDetector *d,
                             float ax, float ay, float az,
                             float *out_magnitude,
                             float *out_score)
{
    // Low-pass filter the raw acceleration
    d->ax_f = update_lpf(d->ax_f, ax);
    d->ay_f = update_lpf(d->ay_f, ay);
    d->az_f = update_lpf(d->az_f, az);

    // Compute magnitude
    float mag = sqrtf(d->ax_f * d->ax_f +
                      d->ay_f * d->ay_f +
                      d->az_f * d->az_f);

    *out_magnitude = mag;

    // Update rolling baseline
    rolling_stats_update(d, mag);

    // If insufficient samples, do not flag anomaly yet
    if (d->count < WINDOW_SIZE / 2) {
        *out_score = 0.0f;
        return false;
    }

    // Z-score style anomaly measure
    float denom = (d->stddev > 1e-6f) ? d->stddev : 1e-6f;
    float z = fabsf(mag - d->mean) / denom;
    *out_score = z;

    return (z > Z_THRESHOLD);
}
