}

static void rb_init(ring_buffer_t *rb) {
    rb->head = 0;
    rb->count = 0;
}

static void rb_push(ring_buffer_t *rb, accel_sample_t s) {
    rb->buf[rb->head] = s;
    rb->head = (rb->head + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

static bool rb_full(const ring_buffer_t *rb) {
    return rb->count == WINDOW_SIZE;
}

/* High-pass filter to remove slow drift / gravity component.
 * y[n] = alpha * (y[n-1] + x[n] - x[n-1])
 */
static accel_sample_t highpass_filter(highpass_state_t *st, accel_sample_t in) {
    accel_sample_t out;

    out.x = HP_ALPHA * (st->hp_x + in.x - st->prev_x);
    out.y = HP_ALPHA * (st->hp_y + in.y - st->prev_y);
    out.z = HP_ALPHA * (st->hp_z + in.z - st->prev_z);

    st->hp_x = out.x;
    st->hp_y = out.y;
    st->hp_z = out.z;

    st->prev_x = in.x;
    st->prev_y = in.y;
    st->prev_z = in.z;

    return out;
}

/* =========================
 * Baseline estimation
 * =========================
 * Call during a known "normal" period to establish baseline stats.
 */
static void compute_baseline_from_window(const ring_buffer_t *rb, float *mean, float *var) {
    float mags[WINDOW_SIZE];
    float sum = 0.0f;
    float sumsq = 0.0f;

    for (uint16_t i = 0; i < rb->count; i++) {
        uint16_t idx = (rb->head + WINDOW_SIZE - rb->count + i) % WINDOW_SIZE;
        mags[i] = vec_mag(&rb->buf[idx]);
        sum += mags[i];
        sumsq += mags[i] * mags[i];
    }

    if (rb->count == 0) {
        *mean = 0.0f;
        *var = 1.0f;
        return;
    }

    *mean = sum / (float)rb->count;
    *var = (sumsq / (float)rb->count) - (*mean * *mean);
    if (*var < 1e-6f) {
        *var = 1e-6f;
    }
}

/* =========================
 * Detector API
 * ========================= */
void anomaly_detector_init(anomaly_detector_t *det) {
    rb_init(&det->rb);

    det->hp.hp_x = 0.0f;
    det->hp.hp_y = 0.0f;
    det->hp.hp_z = 0.0f;
    det->hp.prev_x = 0.0f;
    det->hp.prev_y = 0.0f;
    det->hp.prev_z = 0.0f;

    det->baseline_mean = 0.0f;
    det->baseline_var = 1.0f;
    det->anomaly_active = false;
    det->cooldown = 0;
}

void anomaly_detector_set_baseline(anomaly_detector_t *det, float mean, float var) {
    det->baseline_mean = mean;
    det->baseline_var = (var < 1e-6f) ? 1e-6f : var;
}

/* Feed raw accelerometer sample into detector.
 * Returns true if an anomaly is currently detected.
 */
bool anomaly_detector_update(anomaly_detector_t *det, accel_sample_t raw) {
    accel_sample_t filtered = highpass_filter(&det->hp, raw);
    rb_push(&det->rb, filtered);

    if (det->cooldown > 0) {
        det->cooldown--;
    }

    if (!rb_full(&det->rb)) {
        return false;
    }

    /* Feature extraction: magnitude mean and variance over window */
    float sum = 0.0f;
    float sumsq = 0.0f;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        uint16_t idx = (det->rb.head + i) % WINDOW_SIZE;
        float m = vec_mag(&det->rb.buf[idx]);
        sum += m;
        sumsq += m * m;
    }

    float mean = sum / (float)WINDOW_SIZE;
    float var = (sumsq / (float)WINDOW_SIZE) - (mean * mean);
    if (var < 1e-6f) var = 1e-6f;

    /* Z-score-ish anomaly score comparing current mean to baseline */
    float score = fabsf(mean - det->baseline_mean) / fast_sqrtf(det->baseline_var);

    /* Optional spread check: sudden bursty motion often raises variance too */
    float var_ratio = var / det->baseline_var;

    bool is_anomaly = (score > ANOMALY_THRESHOLD) || (var_ratio > (ANOMALY_THRESHOLD * 1.5f));

    if (!det->anomaly_active) {
        if (is_anomaly && det->cooldown == 0) {
            det->anomaly_active = true;
            det->cooldown = COOLDOWN_SAMPLES;
        }
    } else {
        /* Hysteresis: only clear when score drops enough */
        if (score < RECOVERY_THRESHOLD && var_ratio < (RECOVERY_THRESHOLD * 1.2f)) {
            det->anomaly_active = false;
            det->cooldown = COOLDOWN_SAMPLES;
        }
    }

    return det->anomaly_active;
}

/* Optional: re-estimate baseline from recent normal data */
void anomaly_detector_rebaseline(anomaly_detector_t *det) {
    if (rb_full(&det->rb)) {
        compute_baseline_from_window(&det->rb, &det->baseline_mean, &det->baseline_var);
    }
}
