Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline. It includes:

- sensor sample ingestion
- simple filtering
- feature extraction over a sliding window
- baseline training / adaptation
- anomaly scoring using z-score-like distance
- threshold-based detection

It is designed for resource-constrained systems and avoids dynamic allocation.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define WINDOW_SIZE         32
#define AXES                3
#define BASELINE_ALPHA      0.01f   // adaptation rate
#define VAR_EPS             1e-6f
#define ANOMALY_THRESHOLD   3.0f    // tune for your application

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float mean[AXES];
    float var[AXES];
    bool initialized;
} baseline_t;

typedef struct {
    accel_sample_t history[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
} sample_window_t;

typedef struct {
    baseline_t baseline;
    sample_window_t window;
    float filtered_prev[AXES];
    bool filter_initialized;
} anomaly_detector_t;

/* ---------------- Utility ---------------- */

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float accel_magnitude(const accel_sample_t *s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* ---------------- Initialization ---------------- */

void detector_init(anomaly_detector_t *det) {
    memset(det, 0, sizeof(*det));

    det->baseline.initialized = false;
    det->filter_initialized = false;
}

/* ---------------- Filtering ---------------- */
/* Simple first-order IIR low-pass filter */
static accel_sample_t lowpass_filter(anomaly_detector_t *det, accel_sample_t in) {
    const float alpha = 0.2f; // lower = smoother, higher = more responsive
    accel_sample_t out;

    if (!det->filter_initialized) {
        det->filtered_prev[0] = in.x;
        det->filtered_prev[1] = in.y;
        det->filtered_prev[2] = in.z;
        det->filter_initialized = true;
    }

    det->filtered_prev[0] = alpha * in.x + (1.0f - alpha) * det->filtered_prev[0];
    det->filtered_prev[1] = alpha * in.y + (1.0f - alpha) * det->filtered_prev[1];
    det->filtered_prev[2] = alpha * in.z + (1.0f - alpha) * det->filtered_prev[2];

    out.x = det->filtered_prev[0];
    out.y = det->filtered_prev[1];
    out.z = det->filtered_prev[2];
    return out;
}

/* ---------------- Window management ---------------- */

static void window_push(sample_window_t *w, accel_sample_t s) {
    w->history[w->index] = s;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static bool window_full(const sample_window_t *w) {
    return (w->count == WINDOW_SIZE);
}

/* ---------------- Feature extraction ---------------- */
/* Features: mean and variance of magnitude over the window */
static void extract_features(const sample_window_t *w, float *mean_mag, float *var_mag) {
    float sum = 0.0f;
    float sumsq = 0.0f;

    for (uint16_t i = 0; i < w->count; ++i) {
        float m = accel_magnitude(&w->history[i]);
        sum += m;
        sumsq += m * m;
    }

    *mean_mag = sum / (float)w->count;
    *var_mag = (sumsq / (float)w->count) - (*mean_mag * *mean_mag);
    if (*var_mag < 0.0f) *var_mag = 0.0f;
}

/* ---------------- Baseline model ---------------- */

static void baseline_update(baseline_t *b, float feature, float *mean, float *var) {
    if (!b->initialized) {
        b->mean[0] = feature;
        b->var[0] = 1.0f;
        b->initialized = true;
        return;
    }

    /* Exponential moving average for mean and variance */
    float delta = feature - b->mean[0];
    b->mean[0] += BASELINE_ALPHA * delta;

    float diff = feature - b->mean[0];
    b->var[0] = (1.0f - BASELINE_ALPHA) * b->var[0] + BASELINE_ALPHA * (diff * diff);

    if (b->var[0] < VAR_EPS) b->var[0] = VAR_EPS;

    *mean = b->mean[0];
    *var = b->var[0];
}

/* ---------------- Anomaly scoring ---------------- */

static float compute_anomaly_score(float feature, const baseline_t *b) {
    float stddev = fast_sqrtf(b->var[0] + VAR_EPS);
    return fabsf(feature - b->mean[0]) / stddev;
}

/* ---------------- Main processing step ---------------- */
/*
 * Returns:
 *   true  -> anomaly detected
 *   false -> normal
 */
bool detector_process(anomaly_detector_t *det, accel_sample_t raw_sample) {
    accel_sample_t sample = lowpass_filter(det, raw_sample);
    window_push(&det->window, sample);

    if (!window_full(&det->window)) {
        return false; // not enough data yet
    }

    float mean_mag = 0.0f;
    float var_mag = 0.0f;
    extract_features(&det->window, &mean_mag, &var_mag);

    /* Use mean magnitude as principal feature */
    if (!det->baseline.initialized) {
        det->baseline.mean[0] = mean_mag;
        det->baseline.var[0] = (var_mag > VAR_EPS) ? var_mag : 1.0f;
        det->baseline.initialized = true;
        return false;
    }

    float score = compute_anomaly_score(mean_mag, &det->baseline);

    /* Optionally update baseline only when not anomalous */
    if (score < ANOMALY_THRESHOLD) {
        baseline_update(&det->baseline, mean_mag, &mean_mag, &var_mag);
    }

    return (score >= ANOMALY_THRESHOLD);
}
