Below is a compact embedded-style C implementation of an accelerometer anomaly-detection pipeline. It:

- reads 3-axis samples,
- applies a simple high-pass/offset removal,
- computes signal magnitude,
- maintains a rolling mean and variance,
- flags anomalies when the current magnitude deviates too far from the baseline.

This is designed to be lightweight enough for microcontrollers.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

#define WINDOW_SIZE        32
#define ANOMALY_Z_THRESHOLD 3.5f
#define MIN_SAMPLES        WINDOW_SIZE

/* ---------------- Data Types ---------------- */

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float ring[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;
    float sum;
    float sum_sq;
    float bias_x;
    float bias_y;
    float bias_z;
} anomaly_detector_t;

typedef struct {
    bool anomaly;
    float magnitude;
    float mean;
    float stddev;
    float z_score;
} anomaly_result_t;

/* ---------------- Utility ---------------- */

static inline float fast_sqrtf(float x) {
    return sqrtf(x);
}

static inline float magnitude3(float x, float y, float z) {
    return fast_sqrtf(x*x + y*y + z*z);
}

/* ---------------- Initialization ---------------- */

void anomaly_detector_init(anomaly_detector_t *det) {
    if (!det) return;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->ring[i] = 0.0f;
    }

    det->idx = 0;
    det->count = 0;
    det->sum = 0.0f;
    det->sum_sq = 0.0f;

    /* Can be calibrated at startup if desired */
    det->bias_x = 0.0f;
    det->bias_y = 0.0f;
    det->bias_z = 0.0f;
}

/* Optional: simple static bias calibration using N samples */
void anomaly_detector_calibrate_bias(anomaly_detector_t *det, const accel_sample_t *samples, uint16_t n) {
    if (!det || !samples || n == 0) return;

    float sx = 0.0f, sy = 0.0f, sz = 0.0f;
    for (uint16_t i = 0; i < n; i++) {
        sx += samples[i].x;
        sy += samples[i].y;
        sz += samples[i].z;
    }

    det->bias_x = sx / (float)n;
    det->bias_y = sy / (float)n;
    det->bias_z = sz / (float)n;
}

/* ---------------- Core Processing ---------------- */

anomaly_result_t anomaly_detector_process(anomaly_detector_t *det, const accel_sample_t *sample) {
    anomaly_result_t out = {0};

    if (!det || !sample) {
        return out;
    }

    /* Remove estimated bias */
    float ax = sample->x - det->bias_x;
    float ay = sample->y - det->bias_y;
    float az = sample->z - det->bias_z;

    /* Compute acceleration magnitude */
    float mag = magnitude3(ax, ay, az);

    /* Update rolling statistics */
    if (det->count < WINDOW_SIZE) {
        det->ring[det->idx] = mag;
        det->sum += mag;
        det->sum_sq += mag * mag;
        det->count++;
    } else {
        float old = det->ring[det->idx];
        det->ring[det->idx] = mag;
        det->sum += mag - old;
        det->sum_sq += (mag * mag) - (old * old);
    }

    det->idx = (det->idx + 1) % WINDOW_SIZE;

    if (det->count < MIN_SAMPLES) {
        out.anomaly = false;
        out.magnitude = mag;
        return out;
    }

    float mean = det->sum / (float)det->count;
    float variance = (det->sum_sq / (float)det->count) - (mean * mean);
    if (variance < 1e-6f) {
        variance = 1e-6f;
    }

    float stddev = fast_sqrtf(variance);
    float z = (mag - mean) / stddev;

    out.magnitude = mag;
    out.mean = mean;
    out.stddev = stddev;
    out.z_score = z;
    out.anomaly = (fabsf(z) > ANOMALY_Z_THRESHOLD);

    return out;
}
