Below is a compact C implementation for an embedded accelerometer anomaly-detection pipeline. It includes:

- sample ingestion
- high-pass-ish baseline removal via moving average
- magnitude computation
- short-term window statistics
- anomaly scoring with threshold + persistence
- event callback

It is designed to be lightweight and suitable for MCU firmware.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WIN_SIZE        16      // short window for statistics
#define BASELINE_SIZE    64      // longer window for drift / gravity estimate
#define ANOM_THRESH      3.5f    // z-like score threshold
#define ANOM_PERSIST     3       // consecutive frames above threshold to flag anomaly

/* =========================
 * Types
 * ========================= */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float buf[BASELINE_SIZE];
    uint16_t idx;
    uint16_t count;
    float sum;
} moving_avg_t;

typedef struct {
    float buf[WIN_SIZE];
    uint16_t idx;
    uint16_t count;
    float sum;
    float sumsq;
} rolling_stats_t;

typedef struct {
    moving_avg_t baseline;
    rolling_stats_t stats;
    uint8_t above_thresh_count;
    bool anomaly_active;
} anomaly_detector_t;

/* =========================
 * Utility
 * ========================= */
static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float vec_magnitude(accel_sample_t a) {
    return fast_sqrtf(a.x * a.x + a.y * a.y + a.z * a.z);
}

/* =========================
 * Moving average baseline
 * ========================= */
static void moving_avg_init(moving_avg_t *m) {
    m->idx = 0;
    m->count = 0;
    m->sum = 0.0f;
    for (int i = 0; i < BASELINE_SIZE; i++) m->buf[i] = 0.0f;
}

static float moving_avg_update(moving_avg_t *m, float x) {
    if (m->count < BASELINE_SIZE) {
        m->buf[m->idx] = x;
        m->sum += x;
        m->count++;
    } else {
        float old = m->buf[m->idx];
        m->buf[m->idx] = x;
        m->sum += x - old;
    }

    m->idx = (m->idx + 1) % BASELINE_SIZE;
    return m->sum / (float)m->count;
}

/* =========================
 * Rolling stats
 * ========================= */
static void rolling_stats_init(rolling_stats_t *r) {
    r->idx = 0;
    r->count = 0;
    r->sum = 0.0f;
    r->sumsq = 0.0f;
    for (int i = 0; i < WIN_SIZE; i++) r->buf[i] = 0.0f;
}

static void rolling_stats_update(rolling_stats_t *r, float x) {
    if (r->count < WIN_SIZE) {
        r->buf[r->idx] = x;
        r->sum += x;
        r->sumsq += x * x;
        r->count++;
    } else {
        float old = r->buf[r->idx];
        r->buf[r->idx] = x;
        r->sum += x - old;
        r->sumsq += x * x - old * old;
    }

    r->idx = (r->idx + 1) % WIN_SIZE;
}

static float rolling_mean(const rolling_stats_t *r) {
    return (r->count == 0) ? 0.0f : r->sum / (float)r->count;
}

static float rolling_stddev(const rolling_stats_t *r) {
    if (r->count < 2) return 0.0f;
    float n = (float)r->count;
    float mean = r->sum / n;
    float var = (r->sumsq / n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    return fast_sqrtf(var);
}

/* =========================
 * Detector
 * ========================= */
typedef void (*anomaly_callback_t)(float score, float value, float baseline);

typedef struct {
    anomaly_detector_t det;
    anomaly_callback_t on_anomaly;
} pipeline_t;

void anomaly_detector_init(anomaly_detector_t *d) {
    moving_avg_init(&d->baseline);
    rolling_stats_init(&d->stats);
    d->above_thresh_count = 0;
    d->anomaly_active = false;
}

void pipeline_init(pipeline_t *p, anomaly_callback_t cb) {
    anomaly_detector_init(&p->det);
    p->on_anomaly = cb;
}

/*
 * Process one accelerometer sample.
 * Returns true if anomaly is currently active.
 */
bool pipeline_process(pipeline_t *p, accel_sample_t s) {
    // 1) Compute magnitude
    float mag = vec_magnitude(s);

    // 2) Estimate baseline (gravity + slow drift)
    float baseline = moving_avg_update(&p->det.baseline, mag);

    // 3) Derive high-pass-like residual
    float residual = mag - baseline;

    // 4) Update rolling statistics on residual
    rolling_stats_update(&p->det.stats, residual);

    float mean = rolling_mean(&p->det.stats);
    float stddev = rolling_stddev(&p->det.stats);

    // 5) Score anomaly using normalized deviation
    //    Add small epsilon to avoid division by zero
    float eps = 1e-6f;
    float score = fabsf(residual - mean) / (stddev + eps);

    // 6) Persistently triggered anomaly decision
    if (score > ANOM_THRESH && p->det.stats.count >= WIN_SIZE / 2) {
        if (p->det.above_thresh_count < 255) p->det.above_thresh_count++;
    } else {
        p->det.above_thresh_count = 0;
    }

    if (p->det.above_thresh_count >= ANOM_PERSIST) {
        if (!p->det.anomaly_active) {
            p->det.anomaly_active = true;
            if (p->on_anomaly) {
                p->on_anomaly(score, mag, baseline);
            }
        }
    } else {
        p->det.anomaly_active = false;
    }

    return p->det.anomaly_active;
}
