Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis samples
- computes magnitude
- removes DC offset with an exponential moving average
- applies a simple high-pass style residual estimate
- tracks a running mean and variance
- flags an anomaly when the z-score exceeds a threshold for several consecutive samples

This is designed to be lightweight enough for microcontrollers.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define PIPELINE_ALPHA_DC      0.01f   // DC estimator smoothing
#define PIPELINE_ALPHA_VAR     0.01f   // variance estimator smoothing
#define ANOMALY_Z_THRESHOLD    4.0f
#define ANOMALY_CONSEC_COUNT   3

typedef struct {
    // DC estimate of magnitude
    float dc_est;

    // Running mean and variance of residual
    float mean;
    float var;

    // State
    uint16_t anomaly_count;
    bool initialized;
} SensorPipeline;

// Initialize pipeline state
void sensor_pipeline_init(SensorPipeline *p) {
    if (!p) return;
    p->dc_est = 0.0f;
    p->mean = 0.0f;
    p->var = 1.0f;
    p->anomaly_count = 0;
    p->initialized = false;
}

// Process one accelerometer sample.
// ax, ay, az are in raw units or g's; be consistent.
bool sensor_pipeline_process(SensorPipeline *p, float ax, float ay, float az) {
    if (!p) return false;

    // Magnitude of acceleration
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    if (!p->initialized) {
        p->dc_est = mag;
        p->mean = 0.0f;
        p->var = 1.0f;
        p->initialized = true;
        return false;
    }

    // Remove slow DC component
    p->dc_est += PIPELINE_ALPHA_DC * (mag - p->dc_est);
    float residual = mag - p->dc_est;

    // Update mean
    float mean_err = residual - p->mean;
    p->mean += PIPELINE_ALPHA_VAR * mean_err;

    // Update variance estimate (EWMA of squared error)
    float centered = residual - p->mean;
    p->var += PIPELINE_ALPHA_VAR * ((centered * centered) - p->var);

    // Avoid divide-by-zero or tiny variance
    float stddev = (p->var > 1e-6f) ? sqrtf(p->var) : 1e-3f;

    // Z-score
    float z = fabsf(residual - p->mean) / stddev;

    // Consecutive-threshold anomaly detection
    if (z > ANOMALY_Z_THRESHOLD) {
        if (p->anomaly_count < UINT16_MAX) {
            p->anomaly_count++;
        }
    } else {
        p->anomaly_count = 0;
    }

    return (p->anomaly_count >= ANOMALY_CONSEC_COUNT);
}
