## C code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE 32
#define BASELINE_ALPHA 0.01f   // slow update for normal behavior
#define THRESHOLD_MULT  3.0f   // anomaly threshold in std-dev units
#define MIN_STD         0.05f  // avoid division by zero / over-sensitivity

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mag_window[WINDOW_SIZE];
    uint32_t index;
    uint32_t count;

    // Running baseline of magnitude
    float baseline_mean;
    float baseline_var;

    // Current feature values
    float last_mag;
    float last_dev;

    bool anomaly;
} AnomalyDetector;

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float accel_magnitude(const AccelSample *s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

void detector_init(AnomalyDetector *d) {
    for (uint32_t i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }
    d->index = 0;
    d->count = 0;

    d->baseline_mean = 0.0f;
    d->baseline_var = 0.0f;

    d->last_mag = 0.0f;
    d->last_dev = 0.0f;

    d->anomaly = false;
}

static void update_baseline(AnomalyDetector *d, float mag) {
    if (d->count == 0) {
        d->baseline_mean = mag;
        d->baseline_var = 0.0f;
        return;
    }

    float diff = mag - d->baseline_mean;
    d->baseline_mean += BASELINE_ALPHA * diff;

    // Exponential moving variance estimate
    float diff2 = mag - d->baseline_mean;
    d->baseline_var = (1.0f - BASELINE_ALPHA) * (d->baseline_var + BASELINE_ALPHA * diff * diff2);

    if (d->baseline_var < 0.0f) {
        d->baseline_var = 0.0f;
    }
}

bool detector_process_sample(AnomalyDetector *d, const AccelSample *s) {
    float mag = accel_magnitude(s);

    d->mag_window[d->index] = mag;
    d->index = (d->index + 1) % WINDOW_SIZE;
    if (d->count < WINDOW_SIZE) {
        d->count++;
    }

    // Update baseline only when behavior appears normal
    update_baseline(d, mag);

    float stddev = fast_sqrtf(d->baseline_var);
    if (stddev < MIN_STD) {
        stddev = MIN_STD;
    }

    float deviation = fabsf(mag - d->baseline_mean);
    d->last_mag = mag;
    d->last_dev = deviation;

    // Simple anomaly rule
    d->anomaly = (deviation > (THRESHOLD_MULT * stddev));

    return d->anomaly;
}

// Optional: window-based score for extra robustness
float detector_window_score(const AnomalyDetector *d) {
    if (d->count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (uint32_t i = 0; i < d->count; i++) {
        sum += d->mag_window[i];
    }

    float mean = sum / (float)d->count;

    float var = 0.0f;
    for (uint32_t i = 0; i < d->count; i++) {
        float diff = d->mag_window[i] - mean;
        var += diff * diff;
    }
    var /= (float)d->count;

    float stddev = fast_sqrtf(var);
    if (stddev < MIN_STD) {
        stddev = MIN_STD;
    }

    // Higher score means more abnormal
    float score = fabsf(d->last_mag - mean) / stddev;
    return score;
}
