/*
 * Embedded accelerometer anomaly detection pipeline
 * - Fixed-size ring buffer
 * - Simple high-pass / smoothing features
 * - Z-score-like anomaly score using running mean/variance estimates
 * - Designed for low-memory embedded systems
 *
 * Assumptions:
 * - Called at a fixed sample rate (e.g., 100 Hz)
 * - Input is one 3-axis accelerometer sample per call
 * - Integer / float tradeoffs can be adapted to your MCU
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         32
#define FEATURE_DIM         4
#define EPSILON             1e-6f
#define ANOMALY_THRESHOLD   3.5f
#define TRAINING_SAMPLES    200

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float buf[WINDOW_SIZE][3];
    uint16_t idx;
    uint16_t count;
} ring_buffer_t;

typedef struct {
    ring_buffer_t rb;

    // Running statistics for features
    float mean[FEATURE_DIM];
    float m2[FEATURE_DIM];
    uint32_t n;

    // Baseline magnitude estimate for high-pass style comparison
    float baseline_mag;

    // Previous signal state for simple derivative
    accel_sample_t prev;

    bool initialized;
} anomaly_detector_t;

static void ring_init(ring_buffer_t *rb) {
    rb->idx = 0;
    rb->count = 0;
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        rb->buf[i][0] = 0.0f;
        rb->buf[i][1] = 0.0f;
        rb->buf[i][2] = 0.0f;
    }
}

static void detector_init(anomaly_detector_t *det) {
    ring_init(&det->rb);
    for (int i = 0; i < FEATURE_DIM; i++) {
        det->mean[i] = 0.0f;
        det->m2[i] = 0.0f;
    }
    det->n = 0;
    det->baseline_mag = 0.0f;
    det->prev.x = det->prev.y = det->prev.z = 0.0f;
    det->initialized = false;
}

/* Push sample into ring buffer */
static void ring_push(ring_buffer_t *rb, accel_sample_t s) {
    rb->buf[rb->idx][0] = s.x;
    rb->buf[rb->idx][1] = s.y;
    rb->buf[rb->idx][2] = s.z;
    rb->idx = (rb->idx + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

/* Compute simple features from latest sample and ring buffer */
static void compute_features(const anomaly_detector_t *det,
                             accel_sample_t current,
                             float features[FEATURE_DIM]) {
    // Magnitude
    float mag = sqrtf(current.x * current.x +
                      current.y * current.y +
                      current.z * current.z);

    // High-pass-ish residual against a slow baseline
    float residual = mag - det->baseline_mag;

    // Derivative magnitude
    float dx = current.x - det->prev.x;
    float dy = current.y - det->prev.y;
    float dz = current.z - det->prev.z;
    float deriv_mag = sqrtf(dx * dx + dy * dy + dz * dz);

    // Window energy for stability/spike detection
    float energy = 0.0f;
    for (uint16_t i = 0; i < det->rb.count; i++) {
        float bx = det->rb.buf[i][0];
        float by = det->rb.buf[i][1];
        float bz = det->rb.buf[i][2];
        energy += bx * bx + by * by + bz * bz;
    }
    if (det->rb.count > 0) {
        energy /= (float)det->rb.count;
    }

    // Axis imbalance (sum of absolute differences)
    float imbalance = fabsf(current.x - current.y) +
                      fabsf(current.y - current.z) +
                      fabsf(current.z - current.x);

    features[0] = mag;
    features[1] = residual;
    features[2] = deriv_mag;
    features[3] = energy + 0.1f * imbalance;
}

/* Welford online update for baseline stats */
static void update_running_stats(anomaly_detector_t *det, const float features[FEATURE_DIM]) {
    det->n++;
    for (int i = 0; i < FEATURE_DIM; i++) {
        float delta = features[i] - det->mean[i];
        det->mean[i] += delta / (float)det->n;
        float delta2 = features[i] - det->mean[i];
        det->m2[i] += delta * delta2;
    }
}

/* Standard deviation for feature i */
static float feature_std(const anomaly_detector_t *det, int i) {
    if (det->n < 2) return 1.0f;
    float var = det->m2[i] / (float)(det->n - 1);
    if (var < EPSILON) var = EPSILON;
    return sqrtf(var);
}

/*
 * Return true if anomaly is detected.
 * During initial training period, it updates baseline only.
 */
bool detector_process_sample(anomaly_detector_t *det, accel_sample_t sample) {
    if (!det->initialized) {
        det->prev = sample;
        det->baseline_mag = sqrtf(sample.x * sample.x +
                                  sample.y * sample.y +
                                  sample.z * sample.z);
        det->initialized = true;
    }

    ring_push(&det->rb, sample);

    float features[FEATURE_DIM];
    compute_features(det, sample, features);

    // Update slow baseline only when not obviously spiking
    // (prevents contamination from anomalies)
    float current_mag = features[0];
    det->baseline_mag = 0.995f * det->baseline_mag + 0.005f * current_mag;

    // Training phase: collect baseline statistics
    if (det->n < TRAINING_SAMPLES) {
        update_running_stats(det, features);
        det->prev = sample;
        return false;
    }

    // Compute anomaly score based on normalized deviation
    float score = 0.0f;
    for (int i = 0; i < FEATURE_DIM; i++) {
        float stddev = feature_std(det, i);
        float z = fabsf(features[i] - det->mean[i]) / stddev;
        score += z;
    }
    score /= (float)FEATURE_DIM;

    // Optionally update stats slowly on normal samples only
    if (score < ANOMALY_THRESHOLD) {
        // Lightweight adaptation
        update_running_stats(det, features);
    }

    det->prev = sample;
    return (score >= ANOMALY_THRESHOLD);
}

