## Embedded anomaly detection pipeline in C

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ==============================
 * Configuration
 * ============================== */
#define WINDOW_SIZE              32
#define BASELINE_ALPHA_NUM       1   // baseline update rate numerator
#define BASELINE_ALPHA_DEN      64   // baseline update rate denominator
#define VAR_ALPHA_NUM            1
#define VAR_ALPHA_DEN            64

#define ANOMALY_THRESHOLD        3.5f   // z-score-like threshold
#define MIN_VARIANCE             1e-3f  // avoid divide-by-zero
#define MAG_SCALE                1.0f   // adjust if raw units are in mg or counts

/* ==============================
 * Data structures
 * ============================== */
typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    float buf[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;
    float sum;
} moving_avg_t;

typedef struct {
    float baseline;
    float variance;
    bool initialized;
} anomaly_model_t;

typedef struct {
    moving_avg_t mag_filter;
    anomaly_model_t model;
} sensor_pipeline_t;

/* ==============================
 * Utility: moving average
 * ============================== */
static void moving_avg_init(moving_avg_t *m) {
    m->idx = 0;
    m->count = 0;
    m->sum = 0.0f;
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        m->buf[i] = 0.0f;
    }
}

static float moving_avg_update(moving_avg_t *m, float x) {
    if (m->count < WINDOW_SIZE) {
        m->buf[m->idx] = x;
        m->sum += x;
        m->count++;
    } else {
        m->sum -= m->buf[m->idx];
        m->buf[m->idx] = x;
        m->sum += x;
    }

    m->idx++;
    if (m->idx >= WINDOW_SIZE) {
        m->idx = 0;
    }

    return m->sum / (float)m->count;
}

/* ==============================
 * Pipeline init
 * ============================== */
void sensor_pipeline_init(sensor_pipeline_t *p) {
    moving_avg_init(&p->mag_filter);
    p->model.baseline = 0.0f;
    p->model.variance = 1.0f;
    p->model.initialized = false;
}

/* ==============================
 * Feature extraction
 * ============================== */
static float accel_magnitude(const accel_sample_t *s) {
    float ax = s->ax * MAG_SCALE;
    float ay = s->ay * MAG_SCALE;
    float az = s->az * MAG_SCALE;
    return sqrtf(ax * ax + ay * ay + az * az);
}

/* ==============================
 * Anomaly detection for one sample
 * Returns true if anomaly detected.
 * Also outputs score for logging/debug.
 * ============================== */
bool sensor_pipeline_process(sensor_pipeline_t *p,
                              const accel_sample_t *sample,
                              float *out_score,
                              float *out_feature)
{
    /* 1) Feature: magnitude */
    float mag = accel_magnitude(sample);

    /* 2) Low-pass / smoothing */
    float mag_avg = moving_avg_update(&p->mag_filter, mag);

    /* 3) Initialize model on first valid sample */
    if (!p->model.initialized) {
        p->model.baseline = mag_avg;
        p->model.variance = 1.0f;
        p->model.initialized = true;

        if (out_score) *out_score = 0.0f;
        if (out_feature) *out_feature = mag_avg;
        return false;
    }

    /* 4) Compute deviation */
    float diff = mag_avg - p->model.baseline;

    /* 5) Update running variance estimate (EWMA of squared error) */
    float diff_sq = diff * diff;
    p->model.variance += ((float)VAR_ALPHA_NUM / (float)VAR_ALPHA_DEN) *
                         (diff_sq - p->model.variance);

    if (p->model.variance < MIN_VARIANCE) {
        p->model.variance = MIN_VARIANCE;
    }

    /* 6) Compute normalized anomaly score */
    float stddev = sqrtf(p->model.variance);
    float score = fabsf(diff) / stddev;

    /* 7) Threshold decision */
    bool anomaly = (score > ANOMALY_THRESHOLD);

    /* 8) Adapt baseline slowly only when not anomalous */
    if (!anomaly) {
        p->model.baseline += ((float)BASELINE_ALPHA_NUM / (float)BASELINE_ALPHA_DEN) * diff;
    }

    if (out_score) *out_score = score;
    if (out_feature) *out_feature = mag_avg;

    return anomaly;
}
