## Embedded-Friendly C Implementation

This version is intentionally simple and avoids dynamic allocation.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE     32
#define ALPHA           0.2f     // EMA smoothing factor
#define ANOMALY_THRESH  3.5f     // Tune empirically

typedef struct {
    float ax, ay, az;
} AccelSample;

typedef struct {
    float mean_mag;
    float rms_mag;
    float var_mag;
    float peak_mag;
    float mean_jerk;
} Features;

typedef struct {
    AccelSample window[WINDOW_SIZE];
    uint32_t index;
    bool full;

    // Simple baseline / state
    float ema_ax, ema_ay, ema_az;
    float prev_mag;

    // Nominal reference values (set from calibration/training)
    Features baseline;
    Features sigma;
} SensorPipeline;

static float vec_mag(float x, float y, float z) {
    return sqrtf(x*x + y*y + z*z);
}

static Features extract_features(const AccelSample *samples, uint32_t n, float prev_mag) {
    Features f = {0};

    float sum = 0.0f;
    float sumsq = 0.0f;
    float peak = 0.0f;
    float jerk_sum = 0.0f;

    float last_mag = prev_mag;

    for (uint32_t i = 0; i < n; i++) {
        float mag = vec_mag(samples[i].ax, samples[i].ay, samples[i].az);
        float dev = mag - 1.0f; // assuming gravity normalized to ~1g
        float absdev = fabsf(dev);

        sum += mag;
        sumsq += mag * mag;

        if (absdev > peak) {
            peak = absdev;
        }

        if (i > 0) {
            jerk_sum += fabsf(mag - last_mag);
        }
        last_mag = mag;
    }

    f.mean_mag = sum / (float)n;
    f.rms_mag  = sqrtf(sumsq / (float)n);
    f.var_mag  = (sumsq / (float)n) - (f.mean_mag * f.mean_mag);
    f.peak_mag = peak;
    f.mean_jerk = (n > 1) ? (jerk_sum / (float)(n - 1)) : 0.0f;

    return f;
}

static float z_like(float value, float mean, float sigma) {
    if (sigma < 1e-6f) return 0.0f;
    return fabsf(value - mean) / sigma;
}

static float compute_anomaly_score(const Features *f, const Features *baseline, const Features *sigma) {
    // Weighted sum of normalized deviations
    float s1 = z_like(f->mean_mag, baseline->mean_mag, sigma->mean_mag);
    float s2 = z_like(f->rms_mag,  baseline->rms_mag,  sigma->rms_mag);
    float s3 = z_like(f->var_mag,  baseline->var_mag,  sigma->var_mag);
    float s4 = z_like(f->peak_mag, baseline->peak_mag, sigma->peak_mag);
    float s5 = z_like(f->mean_jerk, baseline->mean_jerk, sigma->mean_jerk);

    // Heavier weight on peak and jerk for shock-like anomalies
    return 0.15f*s1 + 0.20f*s2 + 0.15f*s3 + 0.25f*s4 + 0.25f*s5;
}

void pipeline_init(SensorPipeline *p) {
    for (uint32_t i = 0; i < WINDOW_SIZE; i++) {
        p->window[i] = (AccelSample){0, 0, 0};
    }
    p->index = 0;
    p->full = false;

    p->ema_ax = 0.0f;
    p->ema_ay = 0.0f;
    p->ema_az = 0.0f;
    p->prev_mag = 1.0f;

    // Example nominal baseline values.
    // These should be replaced by values obtained during a calibration period.
    p->baseline = (Features){
        .mean_mag = 1.0f,
        .rms_mag = 1.0f,
        .var_mag = 0.02f,
        .peak_mag = 0.10f,
        .mean_jerk = 0.05f
    };

    p->sigma = (Features){
        .mean_mag = 0.05f,
        .rms_mag = 0.05f,
        .var_mag = 0.01f,
        .peak_mag = 0.05f,
        .mean_jerk = 0.02f
    };
}

// Returns true if anomaly detected
bool pipeline_process_sample(SensorPipeline *p, float ax, float ay, float az, float *out_score) {
    // 1) EMA smoothing
    p->ema_ax = ALPHA * ax + (1.0f - ALPHA) * p->ema_ax;
    p->ema_ay = ALPHA * ay + (1.0f - ALPHA) * p->ema_ay;
    p->ema_az = ALPHA * az + (1.0f - ALPHA) * p->ema_az;

    AccelSample s = { p->ema_ax, p->ema_ay, p->ema_az };

    // 2) Store in circular buffer
    p->window[p->index] = s;
    p->index = (p->index + 1) % WINDOW_SIZE;
    if (p->index == 0) {
        p->full = true;
    }

    // 3) Wait until window is full
    if (!p->full) {
        if (out_score) *out_score = 0.0f;
        return false;
    }

    // 4) Reconstruct ordered window for feature extraction
    AccelSample ordered[WINDOW_SIZE];
    uint32_t start = p->index;
    for (uint32_t i = 0; i < WINDOW_SIZE; i++) {
        ordered[i] = p->window[(start + i) % WINDOW_SIZE];
    }

    // 5) Extract features
    Features feat = extract_features(ordered, WINDOW_SIZE, p->prev_mag);

    // 6) Compute score
    float score = compute_anomaly_score(&feat, &p->baseline, &p->sigma);
    if (out_score) *out_score = score;

    // 7) Update state
    p->prev_mag = vec_mag(s.ax, s.ay, s.az);

    // 8) Decision
    return (score > ANOMALY_THRESH);
}
```

