## 2) C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define WINDOW_SIZE         32
#define FILTER_ALPHA        0.2f
#define ANOMALY_THRESHOLD   3.0f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float x;
    float y;
    float z;
    bool initialized;
} LowPassState;

typedef struct {
    AccelSample samples[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
} SampleWindow;

typedef struct {
    float mean_mag;
    float var_mag;
    float peak_to_peak;
    float jerk_mean;
} Features;

typedef struct {
    float baseline_mean_mag;
    float baseline_var_mag;
    float baseline_peak_to_peak;
    float baseline_jerk_mean;
    bool baseline_set;
} BaselineModel;

typedef struct {
    LowPassState lp;
    SampleWindow window;
    BaselineModel model;
} SensorPipeline;

/* --- Utility functions --- */

static float vec_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static float clampf(float v, float min_v, float max_v) {
    if (v < min_v) return min_v;
    if (v > max_v) return max_v;
    return v;
}

/* --- Low-pass filter --- */

static AccelSample lowpass_filter(LowPassState *st, AccelSample in) {
    if (!st->initialized) {
        st->x = in.x;
        st->y = in.y;
        st->z = in.z;
        st->initialized = true;
        return in;
    }

    st->x = FILTER_ALPHA * in.x + (1.0f - FILTER_ALPHA) * st->x;
    st->y = FILTER_ALPHA * in.y + (1.0f - FILTER_ALPHA) * st->y;
    st->z = FILTER_ALPHA * in.z + (1.0f - FILTER_ALPHA) * st->z;

    AccelSample out = { st->x, st->y, st->z };
    return out;
}

/* --- Window management --- */

static void window_init(SampleWindow *w) {
    memset(w, 0, sizeof(*w));
}

static void window_push(SampleWindow *w, AccelSample s) {
    w->samples[w->index] = s;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static bool window_full(const SampleWindow *w) {
    return w->count == WINDOW_SIZE;
}

/* --- Feature extraction --- */

static Features extract_features(const SampleWindow *w) {
    Features f = {0};

    if (w->count == 0) {
        return f;
    }

    float mags[WINDOW_SIZE];
    float sum = 0.0f;
    float min_mag = 1e9f;
    float max_mag = -1e9f;

    for (uint8_t i = 0; i < w->count; i++) {
        float m = vec_magnitude(w->samples[i]);
        mags[i] = m;
        sum += m;
        if (m < min_mag) min_mag = m;
        if (m > max_mag) max_mag = m;
    }

    f.mean_mag = sum / (float)w->count;

    float var_sum = 0.0f;
    for (uint8_t i = 0; i < w->count; i++) {
        float d = mags[i] - f.mean_mag;
        var_sum += d * d;
    }
    f.var_mag = var_sum / (float)w->count;
    f.peak_to_peak = max_mag - min_mag;

    float jerk_sum = 0.0f;
    uint8_t jerk_count = 0;
    for (uint8_t i = 1; i < w->count; i++) {
        float dx = w->samples[i].x - w->samples[i - 1].x;
        float dy = w->samples[i].y - w->samples[i - 1].y;
        float dz = w->samples[i].z - w->samples[i - 1].z;
        jerk_sum += sqrtf(dx * dx + dy * dy + dz * dz);
        jerk_count++;
    }
    f.jerk_mean = (jerk_count > 0) ? (jerk_sum / (float)jerk_count) : 0.0f;

    return f;
}

/* --- Baseline model handling --- */

static void baseline_init(BaselineModel *m) {
    memset(m, 0, sizeof(*m));
}

static void baseline_set_from_features(BaselineModel *m, Features f) {
    m->baseline_mean_mag = f.mean_mag;
    m->baseline_var_mag = f.var_mag;
    m->baseline_peak_to_peak = f.peak_to_peak;
    m->baseline_jerk_mean = f.jerk_mean;
    m->baseline_set = true;
}

/* Simple normalized distance from baseline */
static float anomaly_score(const BaselineModel *m, Features f) {
    if (!m->baseline_set) {
        return 0.0f;
    }

    const float eps = 1e-6f;

    float s1 = fabsf(f.mean_mag - m->baseline_mean_mag) / (fabsf(m->baseline_mean_mag) + eps);
    float s2 = fabsf(f.var_mag - m->baseline_var_mag) / (fabsf(m->baseline_var_mag) + eps);
    float s3 = fabsf(f.peak_to_peak - m->baseline_peak_to_peak) / (fabsf(m->baseline_peak_to_peak) + eps);
    float s4 = fabsf(f.jerk_mean - m->baseline_jerk_mean) / (fabsf(m->baseline_jerk_mean) + eps);

    return (s1 + s2 + s3 + s4) / 4.0f;
}

static bool is_anomaly(const BaselineModel *m, Features f) {
    return anomaly_score(m, f) > ANOMALY_THRESHOLD;
}

/* --- Pipeline API --- */

void sensor_pipeline_init(SensorPipeline *p) {
    memset(p, 0, sizeof(*p));
    window_init(&p->window);
    baseline_init(&p->model);
}

bool sensor_pipeline_process(SensorPipeline *p, AccelSample raw, bool training_mode) {
    AccelSample filtered = lowpass_filter(&p->lp, raw);
    window_push(&p->window, filtered);

    if (!window_full(&p->window)) {
        return false; // not enough data yet
    }

    Features f = extract_features(&p->window);

    if (training_mode && !p->model.baseline_set) {
        baseline_set_from_features(&p->model, f);
        return false;
    }

    return is_anomaly(&p->model, f);
}
```

