# 3) Runtime state

```c
#define MAX_WINDOW_SAMPLES 64

typedef struct {
    anomaly_config_t cfg;

    accel_sample_t window[MAX_WINDOW_SAMPLES];
    uint8_t window_count;

    float filtered_x;
    float filtered_y;
    float filtered_z;

    accel_sample_t prev_sample;
    int has_prev_sample;

    float baseline_mag;  // learned baseline magnitude
    int baseline_ready;
    uint16_t baseline_samples;
} anomaly_detector_t;
```

