# 4) Feature extraction helpers

```c
#include <math.h>
#include <stdint.h>
#include <string.h>

static float vec_magnitude(float x, float y, float z) {
    return sqrtf(x*x + y*y + z*z);
}

static float mean_float(const float *arr, uint8_t n) {
    float sum = 0.0f;
    for (uint8_t i = 0; i < n; i++) sum += arr[i];
    return sum / (float)n;
}

static float stddev_float(const float *arr, uint8_t n, float mean) {
    float sum = 0.0f;
    for (uint8_t i = 0; i < n; i++) {
        float d = arr[i] - mean;
        sum += d * d;
    }
    return sqrtf(sum / (float)n);
}
```

