```c
static void window_push(anomaly_detector_t *det, accel_sample_t s) {
    if (det->window_count < MAX_WINDOW_SAMPLES) {
        det->window[det->window_count++] = s;
    } else {
        memmove(&det->window[0], &det->window[1], (MAX_WINDOW_SAMPLES - 1) * sizeof(accel_sample_t));
        det->window[MAX_WINDOW_SAMPLES - 1] = s;
        det->window_count = MAX_WINDOW_SAMPLES;
    }
}
```

