# 8) Main processing function

```c
anomaly_result_t anomaly_detector_process(anomaly_detector_t *det, accel_sample_t raw) {
    anomaly_result_t out = {0};

    // 1) Low-pass filter
    if (!det->has_prev_sample) {
        det->filtered_x = raw.x;
        det->filtered_y = raw.y;
        det->filtered_z = raw.z;
        det->has_prev_sample = 1;
    } else {
        det->filtered_x = ema_update(det->filtered_x, raw.x, det->cfg.alpha);
        det->filtered_y = ema_update(det->filtered_y, raw.y, det->cfg.alpha);
        det->filtered_z = ema_update(det->filtered_z, raw.z, det->cfg.alpha);
    }

    accel_sample_t filtered = {
        .x = det->filtered_x,
        .y = det->filtered_y,
        .z = det->filtered_z,
        .timestamp_ms = raw.timestamp_ms
    };

    // 2) Windowing
    window_push(det, filtered);

    // 3) Basic derived metrics
    float mag = vec_magnitude(filtered.x, filtered.y, filtered.z);

    float jerk = 0.0f;
    if (det->has_prev_sample) {
        float dx = filtered.x - det->prev_sample.x;
        float dy = filtered.y - det->prev_sample.y;
        float dz = filtered.z - det->prev_sample.z;
        jerk = vec_magnitude(dx, dy, dz);
    }
    det->prev_sample = filtered;

    // 4) Learn baseline magnitude for first few samples
    if (!det->baseline_ready) {
        det->baseline_mag = 0.98f * det->baseline_mag + 0.02f * mag;
        det->baseline_samples++;
        if (det->baseline_samples > 50) {
            det->baseline_ready = 1;
        }
    }

    // 5) Compute window features
    float mags[MAX_WINDOW_SAMPLES];
    uint8_t count = det->window_count;
    for (uint8_t i = 0; i < count; i++) {
        mags[i] = vec_magnitude(det->window[i].x, det->window[i].y, det->window[i].z);
    }

    float mean_mag = mean_float(mags, count);
    float std_mag = stddev_float(mags, count, mean_mag);

    float rms = 0.0f;
    for (uint8_t i = 0; i < count; i++) {
        rms += mags[i] * mags[i];
    }
    rms = sqrtf(rms / (float)count);

    // 6) Score anomaly
    float score = 0.0f;

    // magnitude deviation from baseline
    score += fabsf(mag - det->baseline_mag);

    // window variability
    score += std_mag * 2.0f;

    // fast motion / shock
    if (jerk > det->cfg.jerk_threshold) {
        score += 5.0f;
    }

    // free-fall / drop heuristic
    if (mag < 0.3f * det->cfg.gravity_ref) {
        score += 8.0f;
        out.type = ANOMALY_DROP_OR_FREEFALL;
    }

    // vibration heuristic
    if (std_mag > 0.8f) {
        score += 3.0f;
        if (out.type == ANOMALY_NONE) out.type = ANOMALY_VIBRATION;
    }

    // sudden shock
    if (jerk > det->cfg.jerk_threshold * 2.0f) {
        score += 6.0f;
        if (out.type == ANOMALY_NONE) out.type = ANOMALY_SHOCK;
    }

    // sensor fault heuristic
    if (mag > 50.0f || isnan(mag) || isinf(mag)) {
        score += 100.0f;
        out.type = ANOMALY_SENSOR_FAULT;
    }

    // default type if anomalous but unclassified
    if (score > det->cfg.anomaly_threshold && out.type == ANOMALY_NONE) {
        out.type = ANOMALY_SHOCK;
    }

    out.score = score;
    out.magnitude = mag;
    out.rms = rms;
    out.stddev = std_mag;
    out.is_anomaly = (score > det->cfg.anomaly_threshold);

    if (!out.is_anomaly) {
        out.type = ANOMALY_NONE;
    }

    return out;
}
```

