Below is an initial, embedded-friendly implementation of a sensor-processing pipeline for accelerometer anomaly detection. It is designed to be simple, low-memory, and suitable as a starting point for MCU integration.

## What it does
- Accepts raw accelerometer samples `(x, y, z)`
- Applies:
  - optional high-pass filtering to remove gravity/slow drift
  - magnitude calculation
  - sliding-window statistics
- Detects anomalies when the signal deviates significantly from recent baseline behavior

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         32
#define ANOMALY_Z_THRESHOLD 3.5f
#define MIN_VARIANCE        1e-6f

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Simple high-pass filter state
    float prev_x_in;
    float prev_y_in;
    float prev_z_in;
    float prev_x_out;
    float prev_y_out;
    float prev_z_out;
    float alpha;   // 0..1, closer to 1 = lower cutoff
} HighPassFilter;

typedef struct {
    float values[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
    float sum;
    float sumsq;
} SlidingStats;

typedef struct {
    HighPassFilter hp_filter;
    SlidingStats mag_stats;
    bool initialized;
} SensorPipeline;

// -------------------- High-pass filter --------------------
// First-order high-pass filter:
// y[n] = alpha * (y[n-1] + x[n] - x[n-1])
static float hpf_update_axis(float input, float *prev_in, float *prev_out, float alpha) {
    float output = alpha * (*prev_out + input - *prev_in);
    *prev_in = input;
    *prev_out = output;
    return output;
}

static AccelSample hpf_update(HighPassFilter *f, AccelSample in) {
    AccelSample out;
    out.x = hpf_update_axis(in.x, &f->prev_x_in, &f->prev_x_out, f->alpha);
    out.y = hpf_update_axis(in.y, &f->prev_y_in, &f->prev_y_out, f->alpha);
    out.z = hpf_update_axis(in.z, &f->prev_z_in, &f->prev_z_out, f->alpha);
    return out;
}

// -------------------- Sliding statistics --------------------
static void stats_init(SlidingStats *s) {
    s->idx = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        s->values[i] = 0.0f;
    }
}

static void stats_push(SlidingStats *s, float x) {
    if (s->count < WINDOW_SIZE) {
        s->values[s->idx] = x;
        s->sum += x;
        s->sumsq += x * x;
        s->count++;
        s->idx = (s->idx + 1) % WINDOW_SIZE;
    } else {
        float old = s->values[s->idx];
        s->sum -= old;
        s->sumsq -= old * old;

        s->values[s->idx] = x;
        s->sum += x;
        s->sumsq += x * x;
        s->idx = (s->idx + 1) % WINDOW_SIZE;
    }
}

static float stats_mean(const SlidingStats *s) {
    return (s->count == 0) ? 0.0f : (s->sum / (float)s->count);
}

static float stats_variance(const SlidingStats *s) {
    if (s->count < 2) return 0.0f;
    float n = (float)s->count;
    float mean = s->sum / n;
    float var = (s->sumsq / n) - (mean * mean);
    return (var > 0.0f) ? var : 0.0f;
}

static float stats_stddev(const SlidingStats *s) {
    return sqrtf(stats_variance(s));
}

// -------------------- Pipeline --------------------
void pipeline_init(SensorPipeline *p, float highpass_alpha) {
    p->hp_filter.prev_x_in = 0.0f;
    p->hp_filter.prev_y_in = 0.0f;
    p->hp_filter.prev_z_in = 0.0f;
    p->hp_filter.prev_x_out = 0.0f;
    p->hp_filter.prev_y_out = 0.0f;
    p->hp_filter.prev_z_out = 0.0f;
    p->hp_filter.alpha = highpass_alpha;

    stats_init(&p->mag_stats);
    p->initialized = true;
}

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

// Process one sample
// Returns true if anomaly is detected
bool pipeline_process_sample(SensorPipeline *p, AccelSample raw, float *out_score) {
    if (!p->initialized) return false;

    // 1) High-pass filter
    AccelSample filtered = hpf_update(&p->hp_filter, raw);

    // 2) Compute magnitude
    float mag = accel_magnitude(filtered);

    // 3) Update stats
    float mean = stats_mean(&p->mag_stats);
    float stddev = stats_stddev(&p->mag_stats);

    // 4) Compute anomaly score (z-score)
    float score = 0.0f;
    bool anomaly = false;

    if (p->mag_stats.count >= 8) { // wait until we have enough baseline
        float denom = (stddev < MIN_VARIANCE) ? MIN_VARIANCE : stddev;
        score = (mag - mean) / denom;

        if (fabsf(score) > ANOMALY_Z_THRESHOLD) {
            anomaly = true;
        }
    }

    // Push current sample after scoring so current value doesn't bias baseline
    stats_push(&p->mag_stats, mag);

    if (out_score) {
        *out_score = score;
    }

    return anomaly;
}
```

