Below is a solid **initial embedded implementation** of an accelerometer anomaly-detection pipeline. It is designed to be:

- **lightweight**
- **streaming-friendly**
- **easy to port to MCU firmware**
- **deterministic**
- based on simple statistical features rather than heavy ML

It performs:

1. **sample ingestion**
2. **windowed feature extraction**
3. **baseline adaptation**
4. **anomaly scoring**
5. **threshold-based detection with cooldown**

---

## High-level approach

For each sliding window of accelerometer samples:

- compute:
  - mean acceleration magnitude
  - RMS magnitude
  - standard deviation
  - peak-to-peak range
  - jerk proxy (change rate)
- compare features against a learned baseline
- compute an anomaly score
- flag anomaly if score exceeds threshold

This is a good starting point for embedded systems because it:
- avoids floating-point-heavy models if needed
- uses constant memory
- works causally in real time

---

## C-like embedded implementation

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE        32
#define BASELINE_ALPHA     0.05f
#define ANOMALY_THRESHOLD  3.0f
#define COOLDOWN_WINDOWS   5

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float mean_mag;
    float rms_mag;
    float std_mag;
    float p2p_mag;
    float jerk;
} Features;

typedef struct {
    AccelSample window[WINDOW_SIZE];
    uint8_t count;
    uint8_t index;
    bool full;

    Features baseline;
    Features baseline_var;   // running variance estimate for normalization

    uint8_t cooldown;
} AnomalyDetector;

static float clampf(float x, float lo, float hi) {
    if (x < lo) return lo;
    if (x > hi) return hi;
    return x;
}

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void compute_features(const AccelSample *samples, uint8_t n, Features *out) {
    float mags[WINDOW_SIZE];
    float sum = 0.0f;
    float sumsq = 0.0f;
    float minv = 1e9f;
    float maxv = -1e9f;
    float jerk_sum = 0.0f;

    for (uint8_t i = 0; i < n; i++) {
        mags[i] = accel_magnitude(samples[i]);
        sum += mags[i];
        sumsq += mags[i] * mags[i];
        if (mags[i] < minv) minv = mags[i];
        if (mags[i] > maxv) maxv = mags[i];

        if (i > 0) {
            jerk_sum += fabsf(mags[i] - mags[i - 1]);
        }
    }

    float mean = sum / (float)n;
    float rms = sqrtf(sumsq / (float)n);

    float var = 0.0f;
    for (uint8_t i = 0; i < n; i++) {
        float d = mags[i] - mean;
        var += d * d;
    }
    var /= (float)n;

    out->mean_mag = mean;
    out->rms_mag = rms;
    out->std_mag = sqrtf(var);
    out->p2p_mag = maxv - minv;
    out->jerk = (n > 1) ? (jerk_sum / (float)(n - 1)) : 0.0f;
}

static void update_baseline(Features *baseline, Features *var, const Features *f) {
    // Exponential moving average baseline and variance
    float a = BASELINE_ALPHA;

    baseline->mean_mag = (1.0f - a) * baseline->mean_mag + a * f->mean_mag;
    baseline->rms_mag  = (1.0f - a) * baseline->rms_mag  + a * f->rms_mag;
    baseline->std_mag  = (1.0f - a) * baseline->std_mag  + a * f->std_mag;
    baseline->p2p_mag  = (1.0f - a) * baseline->p2p_mag  + a * f->p2p_mag;
    baseline->jerk     = (1.0f - a) * baseline->jerk     + a * f->jerk;

    // variance update: EW variance approximation
    var->mean_mag = (1.0f - a) * var->mean_mag + a * (f->mean_mag - baseline->mean_mag) * (f->mean_mag - baseline->mean_mag);
    var->rms_mag  = (1.0f - a) * var->rms_mag  + a * (f->rms_mag  - baseline->rms_mag)  * (f->rms_mag  - baseline->rms_mag);
    var->std_mag  = (1.0f - a) * var->std_mag  + a * (f->std_mag  - baseline->std_mag)  * (f->std_mag  - baseline->std_mag);
    var->p2p_mag  = (1.0f - a) * var->p2p_mag  + a * (f->p2p_mag  - baseline->p2p_mag)  * (f->p2p_mag  - baseline->p2p_mag);
    var->jerk     = (1.0f - a) * var->jerk     + a * (f->jerk     - baseline->jerk)     * (f->jerk     - baseline->jerk);
}

void anomaly_detector_init(AnomalyDetector *d) {
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        d->window[i].ax = 0.0f;
        d->window[i].ay = 0.0f;
        d->window[i].az = 0.0f;
    }
    d->count = 0;
    d->index = 0;
    d->full = false;
    d->cooldown = 0;

    d->baseline.mean_mag = 1.0f; // assume centered around gravity if raw accel
    d->baseline.rms_mag  = 1.0f;
    d->baseline.std_mag  = 0.0f;
    d->baseline.p2p_mag  = 0.0f;
    d->baseline.jerk     = 0.0f;

    d->baseline_var.mean_mag = 0.1f;
    d->baseline_var.rms_mag  = 0.1f;
    d->baseline_var.std_mag  = 0.1f;
    d->baseline_var.p2p_mag  = 0.1f;
    d->baseline_var.jerk     = 0.1f;
}

static float z_score(float x, float mean, float var) {
    float eps = 1e-6f;
    return (x - mean) / sqrtf(var + eps);
}

static float compute_anomaly_score(const AnomalyDetector *d, const Features *f) {
    float s1 = fabsf(z_score(f->mean_mag, d->baseline.mean_mag, d->baseline_var.mean_mag));
    float s2 = fabsf(z_score(f->rms_mag,  d->baseline.rms_mag,  d->baseline_var.rms_mag));
    float s3 = fabsf(z_score(f->std_mag,  d->baseline.std_mag,  d->baseline_var.std_mag));
    float s4 = fabsf(z_score(f->p2p_mag,  d->baseline.p2p_mag,  d->baseline_var.p2p_mag));
    float s5 = fabsf(z_score(f->jerk,     d->baseline.jerk,     d->baseline_var.jerk));

    // Weighted score: jerk and p2p often useful for shocks / impacts
    return 0.20f * s1 + 0.20f * s2 + 0.15f * s3 + 0.25f * s4 + 0.20f * s5;
}

// Returns true if anomaly detected on this update
bool anomaly_detector_update(AnomalyDetector *d, AccelSample sample) {
    d->window[d->index] = sample;
    d->index = (d->index + 1) % WINDOW_SIZE;
    if (d->count < WINDOW_SIZE) {
        d->count++;
        if (d->count < WINDOW_SIZE) {
            return false; // not enough data yet
        }
        d->full = true;
    }

    if (d->cooldown > 0) {
        d->cooldown--;
    }

    Features f;
    compute_features(d->window, WINDOW_SIZE, &f);

    float score = compute_anomaly_score(d, &f);
    bool anomaly = (score > ANOMALY_THRESHOLD) && (d->cooldown == 0);

    // Adapt baseline only when not anomalous
    if (!anomaly) {
        update_baseline(&d->baseline, &d->baseline_var, &f);
    } else {
        d->cooldown = COOLDOWN_WINDOWS;
    }

    return anomaly;
}
```

---

## How it works

### 1. Sliding window
The detector maintains a fixed-size window of recent accelerometer samples.

### 2. Feature extraction
For each window, it computes simple motion descriptors from acceleration magnitude:
- **mean magnitude**
- **RMS**
- **standard deviation**
- **peak-to-peak**
- **jerk proxy**

### 3. Baseline model
It maintains an exponential moving average baseline and variance for normal behavior.

### 4. Anomaly scoring
Each feature is normalized using a z-score-like formula and combined into a weighted score.

### 5. Detection
If the score exceeds a threshold, an anomaly is declared and a cooldown prevents repeated triggering.

