## Example embedded C implementation

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define ALPHA 0.1f          // EMA smoothing factor
#define ANOMALY_Z_THRESHOLD 3.0f
#define MIN_BASELINE_SAMPLES 10

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;

    float ema_mean;
    float ema_var;
    uint32_t sample_count;

    bool initialized;
} anomaly_detector_t;

typedef struct {
    bool is_anomaly;
    float magnitude;
    float baseline_mean;
    float baseline_stddev;
    float score;
} anomaly_result_t;

static float fast_sqrtf(float v) {
    return sqrtf(v);
}

void anomaly_detector_init(anomaly_detector_t *detector) {
    detector->filtered_x = 0.0f;
    detector->filtered_y = 0.0f;
    detector->filtered_z = 0.0f;
    detector->ema_mean = 0.0f;
    detector->ema_var = 0.0f;
    detector->sample_count = 0;
    detector->initialized = false;
}

static void low_pass_filter(anomaly_detector_t *detector, const accel_sample_t *input) {
    if (!detector->initialized) {
        detector->filtered_x = input->x;
        detector->filtered_y = input->y;
        detector->filtered_z = input->z;
        detector->initialized = true;
        return;
    }

    detector->filtered_x = ALPHA * input->x + (1.0f - ALPHA) * detector->filtered_x;
    detector->filtered_y = ALPHA * input->y + (1.0f - ALPHA) * detector->filtered_y;
    detector->filtered_z = ALPHA * input->z + (1.0f - ALPHA) * detector->filtered_z;
}

static float compute_magnitude(const anomaly_detector_t *detector) {
    return fast_sqrtf(detector->filtered_x * detector->filtered_x +
                      detector->filtered_y * detector->filtered_y +
                      detector->filtered_z * detector->filtered_z);
}

static void update_baseline(anomaly_detector_t *detector, float magnitude) {
    detector->sample_count++;

    if (detector->sample_count == 1) {
        detector->ema_mean = magnitude;
        detector->ema_var = 0.0f;
        return;
    }

    float delta = magnitude - detector->ema_mean;
    detector->ema_mean += ALPHA * delta;

    // EMA variance update
    float diff = magnitude - detector->ema_mean;
    detector->ema_var = (1.0f - ALPHA) * (detector->ema_var + ALPHA * delta * delta);
}

anomaly_result_t anomaly_detector_process(anomaly_detector_t *detector,
                                         const accel_sample_t *input) {
    anomaly_result_t result = {0};

    low_pass_filter(detector, input);

    float magnitude = compute_magnitude(detector);
    update_baseline(detector, magnitude);

    float stddev = fast_sqrtf(detector->ema_var);
    float deviation = fabsf(magnitude - detector->ema_mean);
    float score = (stddev > 1e-6f) ? (deviation / stddev) : 0.0f;

    result.magnitude = magnitude;
    result.baseline_mean = detector->ema_mean;
    result.baseline_stddev = stddev;
    result.score = score;

    if (detector->sample_count >= MIN_BASELINE_SAMPLES &&
        score > ANOMALY_Z_THRESHOLD) {
        result.is_anomaly = true;
    } else {
        result.is_anomaly = false;
    }

    return result;
}
```

