static float baseline_rms[BASELINE_SAMPLES];
static float baseline_var[BASELINE_SAMPLES];
static float baseline_ptp[BASELINE_SAMPLES];
static uint16_t baseline_index = 0;
static bool training_mode = false;

static anomaly_model_t model;
static anomaly_state_t current_state = ANOMALY_NONE;
static bool anomaly_flag = false;

static float sample_to_magnitude(accel_sample_t s)
{
    return sqrtf((s.x * s.x) + (s.y * s.y) + (s.z * s.z));
}

static feature_vector_t extract_features(const float *data, uint16_t len)
{
    feature_vector_t fv;
    memset(&fv, 0, sizeof(fv));

    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = data[0];
    float max_v = data[0];
    float delta_sum = 0.0f;

    for (uint16_t i = 0; i < len; i++) {
        float v = data[i];
        sum += v;
        sum_sq += v * v;
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;

        if (i > 0) {
            delta_sum += fabsf(data[i] - data[i - 1]);
        }
    }

    fv.mean = sum / (float)len;
    fv.rms = sqrtf(sum_sq / (float)len);

    float var_acc = 0.0f;
    for (uint16_t i = 0; i < len; i++) {
        float d = data[i] - fv.mean;
        var_acc += d * d;
    }
    fv.variance = var_acc / (float)len;
    fv.peak_to_peak = max_v - min_v;
    fv.delta_mean = (len > 1) ? (delta_sum / (float)(len - 1)) : 0.0f;

    return fv;
}

static void compute_baseline_stats(float *values, uint16_t n, float *mean, float *std)
{
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (uint16_t i = 0; i < n; i++) {
        sum += values[i];
        sum_sq += values[i] * values[i];
    }

    *mean = sum / (float)n;
    float var = (sum_sq / (float)n) - (*mean * *mean);
    if (var < 0.0f) var = 0.0f;
    *std = sqrtf(var);
}

static void train_model(void)
{
    compute_baseline_stats(baseline_rms, baseline_index, &model.mean_rms, &model.std_rms);
    compute_baseline_stats(baseline_var, baseline_index, &model.mean_var, &model.std_var);
    compute_baseline_stats(baseline_ptp, baseline_index, &model.mean_ptp, &model.std_ptp);

    model.trained = true;
}

static float zscore(float value, float mean, float std)
{
    if (std < 1e-6f) {
        return 0.0f;
    }
    return (value - mean) / std;
}

static void evaluate_window(void)
{
    feature_vector_t fv = extract_features(window, WINDOW_SIZE);

    if (training_mode) {
        if (baseline_index < BASELINE_SAMPLES) {
            baseline_rms[baseline_index] = fv.rms;
            baseline_var[baseline_index] = fv.variance;
            baseline_ptp[baseline_index] = fv.peak_to_peak;
            baseline_index++;
        }

        if (baseline_index >= BASELINE_SAMPLES) {
            training_mode = false;
            train_model();
        }
        return;
    }

    if (!model.trained) {
        return;
    }

    float score_rms = fabsf(zscore(fv.rms, model.mean_rms, model.std_rms));
    float score_var = fabsf(zscore(fv.variance, model.mean_var, model.std_var));
    float score_ptp = fabsf(zscore(fv.peak_to_peak, model.mean_ptp, model.std_ptp));

    float anomaly_score = 0.5f * score_rms + 0.3f * score_var + 0.2f * score_ptp;

    if (anomaly_score > 4.0f) {
        current_state = ANOMALY_DETECTED;
        anomaly_flag = true;
    } else if (anomaly_score > 2.5f) {
        current_state = ANOMALY_WARNING;
    } else {
        current_state = ANOMALY_NONE;
        anomaly_flag = false;
    }
}

void pipeline_init(void)
{
    memset(window, 0, sizeof(window));
    memset(baseline_rms, 0, sizeof(baseline_rms));
    memset(baseline_var, 0, sizeof(baseline_var));
    memset(baseline_ptp, 0, sizeof(baseline_ptp));
    memset(&model, 0, sizeof(model));

    window_index = 0;
    window_count = 0;
    baseline_index = 0;
    training_mode = false;
    current_state = ANOMALY_NONE;
    anomaly_flag = false;
}

void pipeline_start_training(void)
{
    pipeline_init();
    training_mode = true;
}

void pipeline_process_sample(accel_sample_t s)
{
    float mag = sample_to_magnitude(s);

    window[window_index] = mag;
    window_index = (window_index + 1) % WINDOW_SIZE;

    if (window_count < WINDOW_SIZE) {
        window_count++;
        return;
    }

    float ordered[WINDOW_SIZE];
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        ordered[i] = window[(window_index + i) % WINDOW_SIZE];
    }

    evaluate_window();
}

bool pipeline_is_anomaly_detected(void)
{
    return anomaly_flag;
}

anomaly_state_t pipeline_get_state(void)
{
    return current_state;
}
