Below is a solid initial implementation of an embedded-friendly sensor-processing pipeline for accelerometer anomaly detection. It is designed to be:

- low memory
- fixed-window based
- easy to port to MCU firmware
- extensible for thresholding or ML later

## What it does

1. Accepts 3-axis accelerometer samples
2. Computes magnitude and basic features over a short window
3. Detects anomalies using simple statistical rules:
   - excessive variance
   - sudden spikes
   - sustained deviation from baseline
4. Produces an anomaly flag and score

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE        32
#define BASELINE_ALPHA     0.02f
#define VAR_THRESHOLD      0.35f
#define SPIKE_THRESHOLD    2.5f
#define MIN_SAMPLE_COUNT    8

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mean;
    float variance;
    float min;
    float max;
    float rms;
} WindowFeatures;

typedef struct {
    float baseline_mean;
    float baseline_var;
    float prev_mag;
    float window[WINDOW_SIZE];
    uint32_t index;
    uint32_t count;
} AnomalyDetector;

typedef struct {
    bool anomaly;
    float score;
    WindowFeatures features;
} DetectionResult;

static float fast_absf(float v) {
    return (v < 0.0f) ? -v : v;
}

static float accel_magnitude(const AccelSample *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

void detector_init(AnomalyDetector *d) {
    d->baseline_mean = 0.0f;
    d->baseline_var = 0.0f;
    d->prev_mag = 0.0f;
    d->index = 0;
    d->count = 0;

    for (uint32_t i = 0; i < WINDOW_SIZE; i++) {
        d->window[i] = 0.0f;
    }
}

static WindowFeatures compute_features(const float *window, uint32_t n) {
    WindowFeatures f = {0};
    if (n == 0) return f;

    float sum = 0.0f;
    float sumsq = 0.0f;
    float minv = window[0];
    float maxv = window[0];

    for (uint32_t i = 0; i < n; i++) {
        float v = window[i];
        sum += v;
        sumsq += v * v;
        if (v < minv) minv = v;
        if (v > maxv) maxv = v;
    }

    f.mean = sum / (float)n;
    f.variance = (sumsq / (float)n) - (f.mean * f.mean);
    if (f.variance < 0.0f) f.variance = 0.0f;
    f.min = minv;
    f.max = maxv;
    f.rms = sqrtf(sumsq / (float)n);

    return f;
}

DetectionResult detector_process(AnomalyDetector *d, const AccelSample *sample) {
    DetectionResult result = {0};

    float mag = accel_magnitude(sample);

    // Update baseline using exponential moving average
    if (d->count == 0) {
        d->baseline_mean = mag;
        d->baseline_var = 0.0f;
    } else {
        float diff = mag - d->baseline_mean;
        d->baseline_mean += BASELINE_ALPHA * diff;
        d->baseline_var = (1.0f - BASELINE_ALPHA) * d->baseline_var +
                          BASELINE_ALPHA * diff * diff;
    }

    // Store sample in circular buffer
    d->window[d->index] = mag;
    d->index = (d->index + 1) % WINDOW_SIZE;
    if (d->count < WINDOW_SIZE) {
        d->count++;
    }

    // Need enough samples before detection
    if (d->count < MIN_SAMPLE_COUNT) {
        d->prev_mag = mag;
        return result;
    }

    // Copy window in order for feature extraction
    float ordered_window[WINDOW_SIZE];
    for (uint32_t i = 0; i < d->count; i++) {
        uint32_t idx = (d->index + i) % WINDOW_SIZE;
        ordered_window[i] = d->window[idx];
    }

    WindowFeatures features = compute_features(ordered_window, d->count);
    result.features = features;

    // Simple anomaly logic
    float spike = fast_absf(mag - d->prev_mag);
    float baseline_deviation = fast_absf(features.mean - d->baseline_mean);
    float variance_ratio = (d->baseline_var > 1e-6f) ? (features.variance / d->baseline_var) : 0.0f;

    float score = 0.0f;

    if (spike > SPIKE_THRESHOLD) {
        score += 1.0f;
    }
    if (variance_ratio > 3.0f || features.variance > VAR_THRESHOLD) {
        score += 1.0f;
    }
    if (baseline_deviation > 1.0f) {
        score += 1.0f;
    }

    result.score = score;
    result.anomaly = (score >= 2.0f);

    d->prev_mag = mag;
    return result;
}
```

