Below is a solid **initial embedded C implementation** of a sensor-processing pipeline for **accelerometer anomaly detection**. It is designed for resource-constrained systems: no dynamic allocation, fixed-size buffers, simple filtering, and a lightweight statistical anomaly detector.

## What it does
- Accepts 3-axis accelerometer samples
- Applies a simple low-pass filter
- Computes signal magnitude
- Maintains a running baseline using an exponential moving average
- Flags an anomaly when the current magnitude deviates too much from the baseline for a configurable number of samples

---

## Example implementation

```c
// anomaly_pipeline.c

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef PIPELINE_WINDOW_SIZE
#define PIPELINE_WINDOW_SIZE 16
#endif

#ifndef LPF_ALPHA
#define LPF_ALPHA 0.2f
#endif

#ifndef BASELINE_ALPHA
#define BASELINE_ALPHA 0.01f
#endif

#ifndef ANOMALY_THRESHOLD
#define ANOMALY_THRESHOLD 0.35f
#endif

#ifndef ANOMALY_HITS_REQUIRED
#define ANOMALY_HITS_REQUIRED 3
#endif

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;

    float baseline_mag;
    float last_mag;

    uint8_t anomaly_hits;
    bool initialized;
} anomaly_pipeline_t;

static float fast_sqrtf(float x) {
    if (x <= 0.0f) {
        return 0.0f;
    }
    return sqrtf(x);
}

void anomaly_pipeline_init(anomaly_pipeline_t *p) {
    if (!p) {
        return;
    }

    p->filtered_x = 0.0f;
    p->filtered_y = 0.0f;
    p->filtered_z = 0.0f;
    p->baseline_mag = 1.0f;   // assume 1g nominal at rest; adjust per calibration
    p->last_mag = 0.0f;
    p->anomaly_hits = 0;
    p->initialized = false;
}

static void low_pass_filter(anomaly_pipeline_t *p, const accel_sample_t *in) {
    if (!p->initialized) {
        p->filtered_x = in->x;
        p->filtered_y = in->y;
        p->filtered_z = in->z;
        p->initialized = true;
        return;
    }

    p->filtered_x = (LPF_ALPHA * in->x) + ((1.0f - LPF_ALPHA) * p->filtered_x);
    p->filtered_y = (LPF_ALPHA * in->y) + ((1.0f - LPF_ALPHA) * p->filtered_y);
    p->filtered_z = (LPF_ALPHA * in->z) + ((1.0f - LPF_ALPHA) * p->filtered_z);
}

static float compute_magnitude(const anomaly_pipeline_t *p) {
    return fast_sqrtf(
        (p->filtered_x * p->filtered_x) +
        (p->filtered_y * p->filtered_y) +
        (p->filtered_z * p->filtered_z)
    );
}

/*
 * Returns true if anomaly detected.
 * Call this for every new accelerometer sample.
 */
bool anomaly_pipeline_process(anomaly_pipeline_t *p, const accel_sample_t *sample) {
    if (!p || !sample) {
        return false;
    }

    low_pass_filter(p, sample);

    float mag = compute_magnitude(p);
    p->last_mag = mag;

    // Update baseline only when not currently anomalous
    float deviation = 0.0f;
    if (p->baseline_mag > 0.0001f) {
        deviation = fabsf(mag - p->baseline_mag) / p->baseline_mag;
    }

    bool is_anomaly = (deviation > ANOMALY_THRESHOLD);

    if (is_anomaly) {
        if (p->anomaly_hits < 255) {
            p->anomaly_hits++;
        }
    } else {
        p->anomaly_hits = 0;
        p->baseline_mag = (BASELINE_ALPHA * mag) + ((1.0f - BASELINE_ALPHA) * p->baseline_mag);
    }

    return (p->anomaly_hits >= ANOMALY_HITS_REQUIRED);
}
