## `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float accel_magnitude(accel_sample_t s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void update_window(sensor_pipeline_t *p, accel_sample_t s, float mag) {
    p->sample_window[p->index] = s;
    p->mag_window[p->index] = mag;
    p->index = (p->index + 1) % WINDOW_SIZE;
    if (p->count < WINDOW_SIZE) {
        p->count++;
    }
}

static accel_features_t extract_features(sensor_pipeline_t *p, float current_mag) {
    accel_features_t f = {0};

    if (p->count == 0) {
        return f;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < p->count; i++) {
        sum += p->mag_window[i];
    }
    f.mean_mag = sum / (float)p->count;

    float var_sum = 0.0f;
    for (uint8_t i = 0; i < p->count; i++) {
        float d = p->mag_window[i] - f.mean_mag;
        var_sum += d * d;
    }
    f.std_mag = sqrtf(var_sum / (float)p->count);

    if (!p->initialized) {
        f.jerk = 0.0f;
    } else {
        f.jerk = current_mag - p->last_mag;
    }

    return f;
}

static anomaly_result_t detect_anomaly(accel_features_t f) {
    anomaly_result_t r;
    memset(&r, 0, sizeof(r));
    r.features = f;

    /*
      Simple heuristic:
      - SPIKE: current magnitude change is large relative to window variation
      - DRIFT: mean magnitude is far from expected baseline
      Adjust thresholds based on your device and sensor placement.
    */
    const float SPIKE_JERK_THRESHOLD = 1.5f;
    const float SPIKE_STD_THRESHOLD  = 0.4f;
    const float DRIFT_MEAN_THRESHOLD  = 1.2f;

    float score = 0.0f;

    if (fabsf(f.jerk) > SPIKE_JERK_THRESHOLD && f.std_mag > SPIKE_STD_THRESHOLD) {
        r.type = ANOMALY_SPIKE;
        score = fabsf(f.jerk) + f.std_mag;
    } else if (fabsf(f.mean_mag - 1.0f) > DRIFT_MEAN_THRESHOLD) {
        r.type = ANOMALY_DRIFT;
        score = fabsf(f.mean_mag - 1.0f);
    } else {
        r.type = ANOMALY_NONE;
        score = 0.0f;
    }

    r.score = score;
    return r;
}

void sensor_pipeline_init(sensor_pipeline_t *p) {
    memset(p, 0, sizeof(*p));
    p->initialized = 0;
    p->last_mag = 0.0f;
}

anomaly_result_t sensor_pipeline_process(sensor_pipeline_t *p, accel_sample_t s) {
    float mag = accel_magnitude(s);

    update_window(p, s, mag);
    accel_features_t f = extract_features(p, mag);

    anomaly_result_t result = detect_anomaly(f);

    p->last_mag = mag;
    p->initialized = 1;

    return result;
}
