Below is an initial embedded-friendly implementation of an accelerometer anomaly-detection pipeline in C. It is designed for low memory usage, fixed-size buffers, and straightforward integration with a sensor ISR or polling loop.

## What it does
- Reads 3-axis accelerometer samples
- Computes magnitude
- Applies a simple moving average baseline
- Detects anomalies when the current magnitude deviates from baseline by a configurable threshold
- Uses a small state machine and hysteresis to reduce false positives

---

## Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         16
#define ANOMALY_THRESHOLD   2.5f
#define RECOVERY_THRESHOLD  1.5f
#define ANOMALY_COUNT_LIMIT  3

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float mag_window[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
    float sum_mag;

    float baseline;
    bool baseline_initialized;

    uint8_t anomaly_count;
    bool anomaly_active;
} anomaly_detector_t;

static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

void anomaly_detector_init(anomaly_detector_t *det)
{
    det->idx = 0;
    det->count = 0;
    det->sum_mag = 0.0f;
    det->baseline = 0.0f;
    det->baseline_initialized = false;
    det->anomaly_count = 0;
    det->anomaly_active = false;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
}

static void update_baseline(anomaly_detector_t *det, float mag)
{
    if (!det->baseline_initialized) {
        det->baseline = mag;
        det->baseline_initialized = true;
        return;
    }

    if (det->count < WINDOW_SIZE) {
        det->mag_window[det->idx] = mag;
        det->sum_mag += mag;
        det->count++;
    } else {
        det->sum_mag -= det->mag_window[det->idx];
        det->mag_window[det->idx] = mag;
        det->sum_mag += mag;
    }

    det->idx = (det->idx + 1) % WINDOW_SIZE;
    det->baseline = det->sum_mag / (float)det->count;
}

bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *sample,
                              float *out_magnitude,
                              float *out_baseline)
{
    float mag = accel_magnitude(sample);

    if (out_magnitude) {
        *out_magnitude = mag;
    }

    update_baseline(det, mag);

    if (out_baseline) {
        *out_baseline = det->baseline;
    }

    float deviation = fabsf(mag - det->baseline);

    if (!det->anomaly_active) {
        if (deviation > ANOMALY_THRESHOLD) {
            det->anomaly_count++;
            if (det->anomaly_count >= ANOMALY_COUNT_LIMIT) {
                det->anomaly_active = true;
                det->anomaly_count = 0;
                return true; // anomaly started
            }
        } else {
            det->anomaly_count = 0;
        }
    } else {
        if (deviation < RECOVERY_THRESHOLD) {
            det->anomaly_count++;
            if (det->anomaly_count >= ANOMALY_COUNT_LIMIT) {
                det->anomaly_active = false;
                det->anomaly_count = 0;
            }
        } else {
            det->anomaly_count = 0;
        }
    }

    return det->anomaly_active;
}
```

