Below is a compact **initial embedded C implementation** for a sensor-processing pipeline that ingests accelerometer samples, maintains a small sliding window, computes simple features, and raises an anomaly flag when the signal deviates from a learned baseline.

It is designed to be:
- **lightweight**
- **fixed-memory**
- **easy to port to bare metal / RTOS**
- suitable as a starting point for later tuning or ML replacement

---

## What it does

For each incoming accelerometer sample `(ax, ay, az)`:

1. Computes magnitude: `sqrt(ax² + ay² + az²)`
2. Stores magnitude in a fixed-size ring buffer
3. Once the window is full:
   - computes mean and standard deviation
   - compares current magnitude and window statistics to baseline
4. Flags anomaly if:
   - the current sample deviates too far from the window mean, or
   - the window variance becomes unusually large

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef BASELINE_ALPHA
#define BASELINE_ALPHA 0.05f   // Exponential moving average update rate
#endif

#ifndef ANOMALY_Z_THRESHOLD
#define ANOMALY_Z_THRESHOLD 3.0f
#endif

#ifndef ANOMALY_VAR_RATIO
#define ANOMALY_VAR_RATIO 4.0f
#endif

typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint32_t write_idx;
    uint32_t count;

    float baseline_mean;
    float baseline_var;
    bool baseline_initialized;
} anomaly_detector_t;

typedef struct {
    float magnitude;
    float window_mean;
    float window_stddev;
    float baseline_mean;
    float baseline_stddev;
    bool anomaly;
} anomaly_result_t;

static float compute_magnitude(const accel_sample_t *s)
{
    return sqrtf(s->ax * s->ax + s->ay * s->ay + s->az * s->az);
}

static void compute_window_stats(const float *buf, uint32_t n, float *mean, float *var)
{
    if (n == 0) {
        *mean = 0.0f;
        *var = 0.0f;
        return;
    }

    float sum = 0.0f;
    for (uint32_t i = 0; i < n; i++) {
        sum += buf[i];
    }
    *mean = sum / (float)n;

    float sq_sum = 0.0f;
    for (uint32_t i = 0; i < n; i++) {
        float d = buf[i] - *mean;
        sq_sum += d * d;
    }
    *var = sq_sum / (float)n;
}

void anomaly_detector_init(anomaly_detector_t *det)
{
    memset(det, 0, sizeof(*det));
}

static void update_baseline(anomaly_detector_t *det, float window_mean, float window_var)
{
    if (!det->baseline_initialized) {
        det->baseline_mean = window_mean;
        det->baseline_var = window_var;
        det->baseline_initialized = true;
        return;
    }

    det->baseline_mean =
        (1.0f - BASELINE_ALPHA) * det->baseline_mean + BASELINE_ALPHA * window_mean;

    det->baseline_var =
        (1.0f - BASELINE_ALPHA) * det->baseline_var + BASELINE_ALPHA * window_var;
}

bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *sample,
                              anomaly_result_t *result)
{
    float mag = compute_magnitude(sample);

    det->buffer[det->write_idx] = mag;
    det->write_idx = (det->write_idx + 1) % WINDOW_SIZE;
    if (det->count < WINDOW_SIZE) {
        det->count++;
    }

    // Default result
    result->magnitude = mag;
    result->window_mean = 0.0f;
    result->window_stddev = 0.0f;
    result->baseline_mean = det->baseline_mean;
    result->baseline_stddev = sqrtf(det->baseline_var);
    result->anomaly = false;

    // Wait until enough samples have accumulated
    if (det->count < WINDOW_SIZE) {
        return false;
    }

    float window_mean, window_var;
    compute_window_stats(det->buffer, WINDOW_SIZE, &window_mean, &window_var);
    float window_stddev = sqrtf(window_var);

    update_baseline(det, window_mean, window_var);

    result->window_mean = window_mean;
    result->window_stddev = window_stddev;
    result->baseline_mean = det->baseline_mean;
    result->baseline_stddev = sqrtf(det->baseline_var);

    // Simple anomaly logic
    bool spike_anomaly = false;
    if (result->baseline_stddev > 1e-6f) {
        float z = fabsf(mag - det->baseline_mean) / result->baseline_stddev;
        spike_anomaly = (z > ANOMALY_Z_THRESHOLD);
    }

    bool variance_anomaly = false;
    if (det->baseline_var > 1e-6f) {
        variance_anomaly = (window_var > (ANOMALY_VAR_RATIO * det->baseline_var));
    }

    result->anomaly = spike_anomaly || variance_anomaly;
    return result->anomaly;
}
```

