## 2) Embedded C implementation

This is an initial firmware-friendly implementation in C.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE        64
#define FEATURE_DIM        4
#define ANOMALY_THRESHOLD  3.0f

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float mean;
    float variance;
    float rms;
    float peak_to_peak;
} WindowFeatures;

typedef struct {
    AccelSample buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
} SlidingWindow;

typedef struct {
    float baseline_mean[FEATURE_DIM];
    float baseline_std[FEATURE_DIM];
} BaselineModel;

typedef struct {
    SlidingWindow window;
    BaselineModel model;
    bool anomaly_detected;
} SensorPipeline;

/* --- Utility functions --- */

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static WindowFeatures compute_features(const SlidingWindow *w) {
    WindowFeatures f = {0};

    if (w->count == 0) {
        return f;
    }

    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = accel_magnitude(w->buffer[0]);
    float max_v = min_v;

    for (uint16_t i = 0; i < w->count; i++) {
        float m = accel_magnitude(w->buffer[i]);
        sum += m;
        sum_sq += m * m;

        if (m < min_v) min_v = m;
        if (m > max_v) max_v = m;
    }

    f.mean = sum / (float)w->count;
    f.rms = sqrtf(sum_sq / (float)w->count);
    f.variance = (sum_sq / (float)w->count) - (f.mean * f.mean);
    if (f.variance < 0.0f) f.variance = 0.0f;
    f.peak_to_peak = max_v - min_v;

    return f;
}

static void window_init(SlidingWindow *w) {
    w->index = 0;
    w->count = 0;
}

static void window_push(SlidingWindow *w, AccelSample s) {
    w->buffer[w->index] = s;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static void pipeline_init(SensorPipeline *p) {
    window_init(&p->window);
    p->anomaly_detected = false;

    /* Initial baseline values; replace with calibration/training results */
    p->model.baseline_mean[0] = 1.0f;   // mean magnitude near 1g at rest
    p->model.baseline_mean[1] = 0.01f;  // low variance
    p->model.baseline_mean[2] = 1.0f;   // RMS near 1g
    p->model.baseline_mean[3] = 0.05f;  // small peak-to-peak

    p->model.baseline_std[0] = 0.2f;
    p->model.baseline_std[1] = 0.02f;
    p->model.baseline_std[2] = 0.2f;
    p->model.baseline_std[3] = 0.05f;
}

static float feature_z_score(float value, float mean, float stddev) {
    if (stddev < 1e-6f) {
        return 0.0f;
    }
    return (value - mean) / stddev;
}

static float anomaly_score(const WindowFeatures *f, const BaselineModel *m) {
    float z0 = fabsf(feature_z_score(f->mean,         m->baseline_mean[0], m->baseline_std[0]));
    float z1 = fabsf(feature_z_score(f->variance,     m->baseline_mean[1], m->baseline_std[1]));
    float z2 = fabsf(feature_z_score(f->rms,          m->baseline_mean[2], m->baseline_std[2]));
    float z3 = fabsf(feature_z_score(f->peak_to_peak, m->baseline_mean[3], m->baseline_std[3]));

    return (z0 + z1 + z2 + z3) / 4.0f;
}

/* Call this once per sample */
void pipeline_process_sample(SensorPipeline *p, AccelSample s) {
    window_push(&p->window, s);

    if (p->window.count < WINDOW_SIZE) {
        p->anomaly_detected = false;
        return; // wait until window is full
    }

    WindowFeatures f = compute_features(&p->window);
    float score = anomaly_score(&f, &p->model);

    p->anomaly_detected = (score > ANOMALY_THRESHOLD);
}

/* Optional: calibration from stationary samples */
void pipeline_calibrate_stationary(SensorPipeline *p, const AccelSample *samples, uint16_t n) {
    if (n == 0) return;

    float sum_mag = 0.0f;
    float sum_mag_sq = 0.0f;
    float min_v = accel_magnitude(samples[0]);
    float max_v = min_v;

    for (uint16_t i = 0; i < n; i++) {
        float m = accel_magnitude(samples[i]);
        sum_mag += m;
        sum_mag_sq += m * m;
        if (m < min_v) min_v = m;
        if (m > max_v) max_v = m;
    }

    float mean = sum_mag / (float)n;
    float var = (sum_mag_sq / (float)n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;

    p->model.baseline_mean[0] = mean;
    p->model.baseline_mean[1] = var;
    p->model.baseline_mean[2] = sqrtf(sum_mag_sq / (float)n);
    p->model.baseline_mean[3] = max_v - min_v;

    /* Basic stddev estimates; in real use, learn these from training data */
    p->model.baseline_std[0] = 0.2f;
    p->model.baseline_std[1] = 0.02f;
    p->model.baseline_std[2] = 0.2f;
    p->model.baseline_std[3] = 0.05f;
}
