## 2) Simple embedded C implementation

This version is intentionally straightforward and MCU-friendly.

### `sensor_pipeline.h`
```c
#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#define SP_WINDOW_SIZE  32
#define SP_AXES         3

typedef struct {
    float ax;
    float ay;
    float az;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float mean;
    float stddev;
    float min;
    float max;
    float rms;
} feature_set_t;

typedef struct {
    // Rolling buffer of magnitudes
    float window[SP_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;

    // Baseline statistics
    feature_set_t baseline;

    // Runtime anomaly detection state
    float anomaly_threshold;     // e.g. 3.0f
    uint8_t consecutive_limit;   // e.g. 3
    uint8_t consecutive_hits;

    // Optional runtime feature values
    feature_set_t current_features;
} sensor_pipeline_t;

void sp_init(sensor_pipeline_t *sp);
void sp_set_baseline(sensor_pipeline_t *sp, feature_set_t baseline);
bool sp_process_sample(sensor_pipeline_t *sp, const accel_sample_t *sample);
bool sp_window_ready(const sensor_pipeline_t *sp);
void sp_compute_features(const float *data, uint8_t len, feature_set_t *out);

#endif
```

