### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float sp_sqrtf_safe(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

void sp_init(sensor_pipeline_t *sp) {
    memset(sp, 0, sizeof(*sp));
    sp->anomaly_threshold = 3.0f;
    sp->consecutive_limit = 3;
}

void sp_set_baseline(sensor_pipeline_t *sp, feature_set_t baseline) {
    sp->baseline = baseline;
}

bool sp_window_ready(const sensor_pipeline_t *sp) {
    return (sp->count >= SP_WINDOW_SIZE);
}

void sp_compute_features(const float *data, uint8_t len, feature_set_t *out) {
    if (!data || !out || len == 0) return;

    float sum = 0.0f;
    float sumsq = 0.0f;
    float minv = data[0];
    float maxv = data[0];

    for (uint8_t i = 0; i < len; i++) {
        float v = data[i];
        sum += v;
        sumsq += v * v;
        if (v < minv) minv = v;
        if (v > maxv) maxv = v;
    }

    float mean = sum / (float)len;
    float variance = (sumsq / (float)len) - (mean * mean);
    if (variance < 0.0f) variance = 0.0f;

    out->mean = mean;
    out->stddev = sp_sqrtf_safe(variance);
    out->min = minv;
    out->max = maxv;
    out->rms = sp_sqrtf_safe(sumsq / (float)len);
}

static float sp_score_feature(float value, float baseline_mean, float baseline_stddev) {
    const float eps = 1e-6f;
    return fabsf(value - baseline_mean) / (baseline_stddev + eps);
}

bool sp_process_sample(sensor_pipeline_t *sp, const accel_sample_t *sample) {
    if (!sp || !sample) return false;

    // Compute signal magnitude
    float mag = sqrtf(sample->ax * sample->ax +
                      sample->ay * sample->ay +
                      sample->az * sample->az);

    // Store in ring buffer
    sp->window[sp->index] = mag;
    sp->index = (sp->index + 1) % SP_WINDOW_SIZE;
    if (sp->count < SP_WINDOW_SIZE) {
        sp->count++;
    }

    // Only evaluate if full window is ready
    if (!sp_window_ready(sp)) {
        return false;
    }

    // Reconstruct linear window for feature extraction
    float ordered[SP_WINDOW_SIZE];
    uint8_t start = sp->index;
    for (uint8_t i = 0; i < SP_WINDOW_SIZE; i++) {
        ordered[i] = sp->window[(start + i) % SP_WINDOW_SIZE];
    }

    sp_compute_features(ordered, SP_WINDOW_SIZE, &sp->current_features);

    // Simple anomaly score based on feature deviation from baseline
    float score_mean  = sp_score_feature(sp->current_features.mean,
                                         sp->baseline.mean,
                                         sp->baseline.stddev);
    float score_std   = sp_score_feature(sp->current_features.stddev,
                                         sp->baseline.stddev,
                                         sp->baseline.stddev);
    float score_rms   = sp_score_feature(sp->current_features.rms,
                                         sp->baseline.rms,
                                         sp->baseline.stddev);

    float score = (score_mean + score_std + score_rms) / 3.0f;

    if (score > sp->anomaly_threshold) {
        if (sp->consecutive_hits < 255) {
            sp->consecutive_hits++;
        }
    } else {
        sp->consecutive_hits = 0;
    }

    return (sp->consecutive_hits >= sp->consecutive_limit);
}
```

