Below is a solid **initial C implementation** of an embedded-style **accelerometer anomaly detection pipeline**. It is designed to be:

- **simple enough for MCUs**
- **streaming-based**
- **low memory**
- **easy to extend**

This version:
1. ingests 3-axis accelerometer samples,
2. computes magnitude,
3. applies a small moving average,
4. tracks a running baseline,
5. flags anomalies when the filtered magnitude deviates too much from the baseline.

---

## Design overview

### Pipeline stages
1. **Input sample**
   - `ax, ay, az`
2. **Feature extraction**
   - compute vector magnitude: `sqrt(ax² + ay² + az²)`
3. **Smoothing**
   - moving average over the last `N` magnitudes
4. **Adaptive baseline**
   - exponential moving average of the smoothed signal
5. **Anomaly detection**
   - anomaly if `|smoothed - baseline| > threshold`

---

## C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define MA_WINDOW_SIZE     8
#define BASELINE_ALPHA     0.01f   // smaller = slower baseline adaptation
#define ANOMALY_THRESHOLD  2.5f    // tune based on sensor units/noise

typedef struct {
    float ma_buffer[MA_WINDOW_SIZE];
    uint8_t ma_index;
    uint8_t ma_count;
    float ma_sum;

    float baseline;
    bool baseline_initialized;
} SensorPipelineState;

typedef struct {
    float magnitude;
    float smoothed;
    float baseline;
    float deviation;
    bool anomaly;
} SensorPipelineResult;

static float compute_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

static float moving_average_update(SensorPipelineState *state, float sample) {
    if (state->ma_count < MA_WINDOW_SIZE) {
        state->ma_buffer[state->ma_index] = sample;
        state->ma_sum += sample;
        state->ma_count++;
    } else {
        state->ma_sum -= state->ma_buffer[state->ma_index];
        state->ma_buffer[state->ma_index] = sample;
        state->ma_sum += sample;
    }

    state->ma_index = (state->ma_index + 1) % MA_WINDOW_SIZE;
    return state->ma_sum / (float)state->ma_count;
}

void sensor_pipeline_init(SensorPipelineState *state) {
    for (int i = 0; i < MA_WINDOW_SIZE; i++) {
        state->ma_buffer[i] = 0.0f;
    }
    state->ma_index = 0;
    state->ma_count = 0;
    state->ma_sum = 0.0f;
    state->baseline = 0.0f;
    state->baseline_initialized = false;
}

SensorPipelineResult sensor_pipeline_process(SensorPipelineState *state,
                                            float ax, float ay, float az) {
    SensorPipelineResult result = {0};

    // 1) Feature extraction
    result.magnitude = compute_magnitude(ax, ay, az);

    // 2) Smoothing
    result.smoothed = moving_average_update(state, result.magnitude);

    // 3) Baseline initialization / update
    if (!state->baseline_initialized) {
        state->baseline = result.smoothed;
        state->baseline_initialized = true;
    } else {
        state->baseline = (1.0f - BASELINE_ALPHA) * state->baseline +
                          BASELINE_ALPHA * result.smoothed;
    }

    result.baseline = state->baseline;

    // 4) Deviation and anomaly detection
    result.deviation = fabsf(result.smoothed - result.baseline);
    result.anomaly = (result.deviation > ANOMALY_THRESHOLD);

    return result;
}
```

