## 2) Initial embedded-friendly C implementation

This is a compact implementation that should be easy to adapt for MCU firmware.

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef BASELINE_ALPHA
#define BASELINE_ALPHA 0.05f   // EMA update rate for normal behavior
#endif

#ifndef ANOMALY_Z_THRESHOLD
#define ANOMALY_Z_THRESHOLD 3.0f
#endif

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float mean_mag;
    float std_mag;
    float max_mag;
    float min_mag;
    float energy;
    float jerk_mean;
} WindowFeatures;

typedef struct {
    float baseline_mean_mag;
    float baseline_var_mag;
    bool baseline_initialized;

    float prev_mag;
    bool prev_mag_valid;

    AccelSample buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
} AnomalyDetector;

/* ---------- Utility ---------- */

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void compute_features(const AccelSample *buf, uint16_t n, WindowFeatures *out) {
    if (n == 0) {
        memset(out, 0, sizeof(*out));
        return;
    }

    float sum = 0.0f;
    float sum_sq = 0.0f;
    float max_v = -1e9f;
    float min_v =  1e9f;
    float energy = 0.0f;
    float jerk_sum = 0.0f;

    float prev_mag = accel_magnitude(buf[0]);

    for (uint16_t i = 0; i < n; i++) {
        float m = accel_magnitude(buf[i]);
        sum += m;
        sum_sq += m * m;
        energy += m * m;

        if (m > max_v) max_v = m;
        if (m < min_v) min_v = m;

        if (i > 0) {
            jerk_sum += fabsf(m - prev_mag);
        }
        prev_mag = m;
    }

    float mean = sum / (float)n;
    float var = (sum_sq / (float)n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;

    out->mean_mag = mean;
    out->std_mag = sqrtf(var);
    out->max_mag = max_v;
    out->min_mag = min_v;
    out->energy = energy;
    out->jerk_mean = (n > 1) ? (jerk_sum / (float)(n - 1)) : 0.0f;
}

/* ---------- Detector ---------- */

void anomaly_detector_init(AnomalyDetector *d) {
    memset(d, 0, sizeof(*d));
    d->baseline_mean_mag = 0.0f;
    d->baseline_var_mag = 1.0f;
    d->baseline_initialized = false;
    d->prev_mag_valid = false;
}

static void update_baseline(AnomalyDetector *d, float mean_mag) {
    if (!d->baseline_initialized) {
        d->baseline_mean_mag = mean_mag;
        d->baseline_var_mag = 1.0f;
        d->baseline_initialized = true;
        return;
    }

    float diff = mean_mag - d->baseline_mean_mag;
    d->baseline_mean_mag += BASELINE_ALPHA * diff;

    // EMA variance update
    d->baseline_var_mag = (1.0f - BASELINE_ALPHA) * d->baseline_var_mag
                        + BASELINE_ALPHA * (diff * diff);

    if (d->baseline_var_mag < 1e-6f) {
        d->baseline_var_mag = 1e-6f;
    }
}

void anomaly_detector_add_sample(AnomalyDetector *d, AccelSample s) {
    d->buffer[d->index] = s;
    d->index = (d->index + 1) % WINDOW_SIZE;
    if (d->count < WINDOW_SIZE) {
        d->count++;
    }
}

static void copy_window_in_order(const AnomalyDetector *d, AccelSample *out) {
    if (d->count < WINDOW_SIZE) {
        memcpy(out, d->buffer, d->count * sizeof(AccelSample));
        return;
    }

    uint16_t pos = d->index;
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        out[i] = d->buffer[pos];
        pos = (pos + 1) % WINDOW_SIZE;
    }
}

bool anomaly_detector_process(AnomalyDetector *d, float *score_out, WindowFeatures *feat_out) {
    if (d->count < WINDOW_SIZE) {
        if (score_out) *score_out = 0.0f;
        if (feat_out) memset(feat_out, 0, sizeof(*feat_out));
        return false; // not enough data yet
    }

    AccelSample window[WINDOW_SIZE];
    copy_window_in_order(d, window);

    WindowFeatures feat;
    compute_features(window, WINDOW_SIZE, &feat);

    if (!d->baseline_initialized) {
        update_baseline(d, feat.mean_mag);
        if (score_out) *score_out = 0.0f;
        if (feat_out) *feat_out = feat;
        return false;
    }

    float baseline_std = sqrtf(d->baseline_var_mag);
    float z = fabsf(feat.mean_mag - d->baseline_mean_mag) / baseline_std;

    // Simple anomaly score combines mean deviation and jitter
    float jitter_term = feat.jerk_mean;
    float score = z + 0.25f * jitter_term;

    bool anomaly = (z > ANOMALY_Z_THRESHOLD) || (feat.std_mag > 2.0f * baseline_std);

    // Only update baseline when behavior looks normal
    if (!anomaly) {
        update_baseline(d, feat.mean_mag);
    }

    if (score_out) *score_out = score;
    if (feat_out) *feat_out = feat;

    return anomaly;
}
```

