#endif

#ifndef ACCEL_SCALE_G
#define ACCEL_SCALE_G 1.0f   // Replace with device-specific scaling if needed
#endif

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    // Low-pass filtered values
    float filt_x;
    float filt_y;
    float filt_z;

    // Ring buffer of recent magnitudes
    float mag_window[PIPELINE_WINDOW_SIZE];
    uint8_t window_idx;
    uint8_t window_count;

    // Baseline / thresholds
    float baseline_mag;
    float anomaly_threshold;
    float alpha; // filter coefficient [0..1]

    // State
    bool initialized;
} SensorPipeline;

// ---------- Utility functions ----------

static float fast_absf(float v) {
    return (v < 0.0f) ? -v : v;
}

static float compute_magnitude(float x, float y, float z) {
    return sqrtf((x * x) + (y * y) + (z * z));
}

static float mean_window(const float *buf, uint8_t count) {
    if (count == 0) return 0.0f;

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++) {
        sum += buf[i];
    }
    return sum / (float)count;
}

static float stddev_window(const float *buf, uint8_t count) {
    if (count < 2) return 0.0f;

    float mean = mean_window(buf, count);
    float var = 0.0f;

    for (uint8_t i = 0; i < count; i++) {
        float d = buf[i] - mean;
        var += d * d;
    }
    var /= (float)(count - 1);
    return sqrtf(var);
}

// ---------- Pipeline API ----------

void pipeline_init(SensorPipeline *p, float alpha, float anomaly_threshold) {
    if (!p) return;

    p->filt_x = 0.0f;
    p->filt_y = 0.0f;
    p->filt_z = 0.0f;

    for (uint8_t i = 0; i < PIPELINE_WINDOW_SIZE; i++) {
        p->mag_window[i] = 0.0f;
    }

    p->window_idx = 0;
    p->window_count = 0;

    p->baseline_mag = 1.0f; // assume ~1g at rest
    p->anomaly_threshold = anomaly_threshold;
    p->alpha = alpha;
    p->initialized = false;
}

static void update_filter(SensorPipeline *p, const AccelSample *s) {
    if (!p->initialized) {
        p->filt_x = s->x;
        p->filt_y = s->y;
        p->filt_z = s->z;
        p->initialized = true;
        return;
    }

    // Simple exponential moving average
    p->filt_x = p->alpha * s->x + (1.0f - p->alpha) * p->filt_x;
    p->filt_y = p->alpha * s->y + (1.0f - p->alpha) * p->filt_y;
    p->filt_z = p->alpha * s->z + (1.0f - p->alpha) * p->filt_z;
}

static void push_magnitude(SensorPipeline *p, float mag) {
    p->mag_window[p->window_idx] = mag;
    p->window_idx = (p->window_idx + 1) % PIPELINE_WINDOW_SIZE;

    if (p->window_count < PIPELINE_WINDOW_SIZE) {
        p->window_count++;
    }
}

bool pipeline_process_sample(SensorPipeline *p, const AccelSample *sample, float *out_score) {
    if (!p || !sample) return false;

    // 1) Filter
    update_filter(p, sample);

    // 2) Magnitude
    float mag = compute_magnitude(p->filt_x, p->filt_y, p->filt_z);

    // 3) Update window
    push_magnitude(p, mag);

    // 4) Compute statistics
    float avg_mag = mean_window(p->mag_window, p->window_count);
    float std_mag = stddev_window(p->mag_window, p->window_count);

    // 5) Simple anomaly score:
    //    - deviation from baseline magnitude
    //    - recent variability
    float deviation = fast_absf(avg_mag - p->baseline_mag);
    float score = deviation + std_mag;

    if (out_score) {
        *out_score = score;
    }

    // 6) Anomaly decision
    return (score >= p->anomaly_threshold);
}

// Optional: call periodically when device is known to be in a stable state
void pipeline_update_baseline(SensorPipeline *p) {
    if (!p || p->window_count == 0) return;

    float avg_mag = mean_window(p->mag_window, p->window_count);

    // Slow adaptation toward current state
    const float baseline_beta = 0.01f;
    p->baseline_mag = (1.0f - baseline_beta) * p->baseline_mag + baseline_beta * avg_mag;
}
```

