Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from accelerometer data. It is written in **C** and designed to be easy to port to a microcontroller.

It does:

1. Read 3-axis accelerometer samples
2. Compute magnitude
3. Apply a simple moving average filter
4. Extract a tiny feature set
5. Compare against a baseline with thresholding
6. Raise an anomaly flag

---

## Minimal embedded C example

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 8
#define BASELINE_MEAN 1.0f
#define ANOMALY_THRESHOLD 0.25f

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float buf[WINDOW_SIZE];
    int idx;
    int count;
    float sum;
} moving_avg_t;

static void ma_init(moving_avg_t *f) {
    f->idx = 0;
    f->count = 0;
    f->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        f->buf[i] = 0.0f;
    }
}

static float ma_update(moving_avg_t *f, float x) {
    if (f->count < WINDOW_SIZE) {
        f->count++;
    } else {
        f->sum -= f->buf[f->idx];
    }

    f->buf[f->idx] = x;
    f->sum += x;
    f->idx = (f->idx + 1) % WINDOW_SIZE;

    return f->sum / f->count;
}

static float accel_magnitude(const accel_sample_t *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* Simple anomaly detector:
   - uses filtered acceleration magnitude
   - compares to baseline mean
   - anomaly if deviation too large
*/
static int detect_anomaly(float filtered_mag) {
    float deviation = fabsf(filtered_mag - BASELINE_MEAN);
    return (deviation > ANOMALY_THRESHOLD);
}

int main(void) {
    moving_avg_t filter;
    ma_init(&filter);

    /* Example stream of accelerometer samples */
    accel_sample_t samples[] = {
        {0.01f, 0.00f, 0.99f},
        {0.02f, 0.01f, 1.01f},
        {0.00f, -0.01f, 1.00f},
        {0.03f, 0.02f, 0.98f},
        {0.50f, 0.40f, 1.80f}, /* anomaly */
        {0.02f, 0.01f, 1.00f},
        {0.01f, 0.00f, 0.99f}
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float mag = accel_magnitude(&samples[i]);
        float filtered = ma_update(&filter, mag);
        int anomaly = detect_anomaly(filtered);

        printf("Sample %d: mag=%.3f filtered=%.3f anomaly=%s\n",
               i, mag, filtered, anomaly ? "YES" : "NO");
    }

    return 0;
}
```

