Below is a **minimal working embedded-style anomaly detection pipeline** for accelerometer data. It is designed to be simple enough to run on a microcontroller, while still capturing the essential stages:

1. **Acquire accel samples**
2. **Filter / preprocess**
3. **Extract lightweight features**
4. **Run anomaly score**
5. **Trigger event if threshold exceeded**

---

## 1) Minimal pipeline concept

### Input
- 3-axis accelerometer samples: `ax, ay, az`
- Sampled at a fixed rate, e.g. 50–200 Hz

### Output
- `anomaly = true/false`
- optional anomaly score

### Method
Use a rolling window of samples and compute:
- mean magnitude
- variance / standard deviation
- peak-to-peak range

A simple anomaly rule:
- If variance or peak-to-peak change is much higher than normal baseline, flag anomaly.

This is lightweight and practical for embedded devices.

---

## 2) C-style embedded implementation

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define ANOMALY_STD_THRESHOLD  1.5f
#define ANOMALY_RANGE_THRESHOLD 3.0f

typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    float mag_window[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
} anomaly_detector_t;

static float fast_sqrt(float x) {
    return sqrtf(x);
}

void detector_init(anomaly_detector_t *det) {
    det->index = 0;
    det->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
}

static float compute_magnitude(accel_sample_t s) {
    return fast_sqrt(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void compute_stats(const float *data, uint8_t n, float *mean, float *stddev, float *range) {
    float sum = 0.0f;
    float min_v = data[0];
    float max_v = data[0];

    for (uint8_t i = 0; i < n; i++) {
        sum += data[i];
        if (data[i] < min_v) min_v = data[i];
        if (data[i] > max_v) max_v = data[i];
    }

    *mean = sum / n;

    float var = 0.0f;
    for (uint8_t i = 0; i < n; i++) {
        float d = data[i] - *mean;
        var += d * d;
    }
    var /= n;
    *stddev = fast_sqrt(var);
    *range = max_v - min_v;
}

bool detector_update(anomaly_detector_t *det, accel_sample_t s, float *score_out) {
    float mag = compute_magnitude(s);

    det->mag_window[det->index] = mag;
    det->index = (det->index + 1) % WINDOW_SIZE;
    if (det->count < WINDOW_SIZE) {
        det->count++;
    }

    if (det->count < WINDOW_SIZE) {
        if (score_out) *score_out = 0.0f;
        return false; // not enough data yet
    }

    float mean, stddev, range;
    compute_stats(det->mag_window, WINDOW_SIZE, &mean, &stddev, &range);

    // Simple anomaly score
    float score = 0.0f;
    if (stddev > ANOMALY_STD_THRESHOLD) {
        score += (stddev - ANOMALY_STD_THRESHOLD);
    }
    if (range > ANOMALY_RANGE_THRESHOLD) {
        score += (range - ANOMALY_RANGE_THRESHOLD);
    }

    if (score_out) *score_out = score;

    return (score > 0.0f);
}
```

