Below is a **minimal working embedded-style pipeline** for detecting anomalies from accelerometer data.

It is intentionally simple:
- reads 3-axis accelerometer samples
- computes a magnitude feature
- smooths it with a moving average
- flags an anomaly when the smoothed value deviates too much from a baseline

This is suitable as a starting point for a microcontroller project.

---

## 1) Core idea

For each incoming sample `(ax, ay, az)`:

1. Compute magnitude:
   \[
   m = \sqrt{ax^2 + ay^2 + az^2}
   \]

2. Update a short moving average window.

3. Compare current smoothed magnitude against a learned baseline.

4. Raise anomaly if deviation exceeds threshold.

---

## 2) Minimal C implementation

```c
#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define BASELINE_INIT_SAMPLES 64
#define ANOMALY_THRESHOLD 0.35f   // tune for your sensor and units

typedef struct {
    float window[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float baseline;
    int baseline_count;
    bool baseline_ready;
} AnomalyDetector;

void detector_init(AnomalyDetector *d) {
    d->index = 0;
    d->count = 0;
    d->sum = 0.0f;
    d->baseline = 0.0f;
    d->baseline_count = 0;
    d->baseline_ready = false;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->window[i] = 0.0f;
    }
}

static float compute_magnitude(float ax, float ay, float az) {
    return sqrtf(ax*ax + ay*ay + az*az);
}

static float update_moving_average(AnomalyDetector *d, float x) {
    if (d->count < WINDOW_SIZE) {
        d->window[d->index] = x;
        d->sum += x;
        d->count++;
    } else {
        d->sum -= d->window[d->index];
        d->window[d->index] = x;
        d->sum += x;
    }

    d->index = (d->index + 1) % WINDOW_SIZE;
    return d->sum / d->count;
}

static void update_baseline(AnomalyDetector *d, float x) {
    if (!d->baseline_ready) {
        d->baseline += x;
        d->baseline_count++;

        if (d->baseline_count >= BASELINE_INIT_SAMPLES) {
            d->baseline /= (float)d->baseline_count;
            d->baseline_ready = true;
        }
    }
}

bool detector_process_sample(AnomalyDetector *d, float ax, float ay, float az) {
    float mag = compute_magnitude(ax, ay, az);
    float avg = update_moving_average(d, mag);

    if (!d->baseline_ready) {
        update_baseline(d, avg);
        return false;  // no anomaly during calibration
    }

    float deviation = fabsf(avg - d->baseline);

    // Optional slow baseline adaptation
    d->baseline = 0.999f * d->baseline + 0.001f * avg;

    return (deviation > ANOMALY_THRESHOLD);
}
```

