Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from **accelerometer data**. It is designed to be simple enough to run on a microcontroller or be adapted to embedded C/C++.

## What it does
1. Reads accelerometer samples `ax, ay, az`
2. Computes a simple feature: **magnitude**
3. Maintains a short **baseline** using a moving average
4. Flags an **anomaly** if the current magnitude deviates too much from baseline

---

## Minimal pipeline logic

### Anomaly rule
An anomaly is detected when:

\[
|magnitude - baseline| > threshold
\]

Where:
- `magnitude = sqrt(ax^2 + ay^2 + az^2)`
- `baseline` = moving average of recent magnitudes

---

## C-style embedded implementation

```c
#include <math.h>
#include <stdio.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define THRESHOLD 2.0f

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} MovingAverage;

void ma_init(MovingAverage *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0.0f;
    }
}

float ma_update(MovingAverage *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->buffer[ma->index] = value;
        ma->sum += value;
        ma->count++;
    } else {
        ma->sum -= ma->buffer[ma->index];
        ma->buffer[ma->index] = value;
        ma->sum += value;
    }

    ma->index = (ma->index + 1) % WINDOW_SIZE;
    return ma->sum / ma->count;
}

float accel_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

bool detect_anomaly(float ax, float ay, float az, MovingAverage *ma) {
    float mag = accel_magnitude(ax, ay, az);
    float baseline = ma_update(ma, mag);

    if (ma->count < WINDOW_SIZE) {
        return false; // wait until baseline is populated
    }

    float deviation = fabsf(mag - baseline);
    return deviation > THRESHOLD;
}

int main(void) {
    MovingAverage ma;
    ma_init(&ma);

    // Example accelerometer stream
    float samples[][3] = {
        {0.1f, 0.0f, 9.7f},
        {0.0f, 0.1f, 9.8f},
        {0.2f, 0.0f, 9.6f},
        {0.1f, 0.1f, 9.7f},
        {3.0f, 4.0f, 12.0f}, // anomaly
        {0.0f, 0.1f, 9.8f}
    };

    int sample_count = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < sample_count; i++) {
        float ax = samples[i][0];
        float ay = samples[i][1];
        float az = samples[i][2];

        bool anomaly = detect_anomaly(ax, ay, az, &ma);

        printf("Sample %d -> ax=%.2f ay=%.2f az=%.2f | anomaly=%s\n",
               i, ax, ay, az, anomaly ? "YES" : "NO");
    }

    return 0;
}
```

