Below is a minimal working embedded-style pipeline for accelerometer anomaly detection. It is designed to be small, deterministic, and easy to port to a microcontroller.

## What it does
1. Reads 3-axis accelerometer samples
2. Computes a simple feature: vector magnitude
3. Maintains a rolling mean and variance over a small window
4. Flags an anomaly if the current magnitude deviates too much from the baseline

---

## C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 32
#define ANOMALY_Z_THRESHOLD 3.0f

typedef struct {
    float buffer[WINDOW_SIZE];
    int idx;
    int count;
    float sum;
    float sumsq;
} RollingStats;

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

void RollingStats_Init(RollingStats *s) {
    s->idx = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) s->buffer[i] = 0.0f;
}

void RollingStats_Add(RollingStats *s, float value) {
    if (s->count == WINDOW_SIZE) {
        float old = s->buffer[s->idx];
        s->sum -= old;
        s->sumsq -= old * old;
    } else {
        s->count++;
    }

    s->buffer[s->idx] = value;
    s->sum += value;
    s->sumsq += value * value;
    s->idx = (s->idx + 1) % WINDOW_SIZE;
}

float RollingStats_Mean(const RollingStats *s) {
    if (s->count == 0) return 0.0f;
    return s->sum / s->count;
}

float RollingStats_Variance(const RollingStats *s) {
    if (s->count < 2) return 0.0f;
    float mean = RollingStats_Mean(s);
    return (s->sumsq / s->count) - (mean * mean);
}

float accel_magnitude(AccelSample a) {
    return sqrtf(a.x * a.x + a.y * a.y + a.z * a.z);
}

int detect_anomaly(RollingStats *stats, float current_value) {
    if (stats->count < WINDOW_SIZE) {
        RollingStats_Add(stats, current_value);
        return 0; // not enough history yet
    }

    float mean = RollingStats_Mean(stats);
    float var = RollingStats_Variance(stats);
    float stddev = sqrtf(fmaxf(var, 1e-6f));
    float z = fabsf(current_value - mean) / stddev;

    int anomaly = (z > ANOMALY_Z_THRESHOLD);

    RollingStats_Add(stats, current_value);
    return anomaly;
}

int main(void) {
    RollingStats stats;
    RollingStats_Init(&stats);

    // Example sensor stream
    AccelSample stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 1.00f},
        {0.50f, 0.40f, 1.80f}, // anomaly
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f}
    };

    int n = sizeof(stream) / sizeof(stream[0]);

    for (int i = 0; i < n; i++) {
        float mag = accel_magnitude(stream[i]);
        int anomaly = detect_anomaly(&stats, mag);

        printf("Sample %d: mag=%.3f %s\n",
               i,
               mag,
               anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
```

