#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 8
#define THRESHOLD   1.8f   // tune for your sensor/noise level

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} MovingAverage;

void ma_init(MovingAverage *ma) {
    ma->index = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->buffer[i] = 0.0f;
    }
}

float ma_update(MovingAverage *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->count++;
    } else {
        ma->sum -= ma->buffer[ma->index];
    }

    ma->buffer[ma->index] = value;
    ma->sum += value;
    ma->index = (ma->index + 1) % WINDOW_SIZE;

    return ma->sum / ma->count;
}

float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

bool detect_anomaly(float filtered_value, float baseline) {
    return fabsf(filtered_value - baseline) > THRESHOLD;
}

int main(void) {
    // Example stream of accelerometer samples
    AccelSample samples[] = {
        {0.02f, 0.01f, 1.00f},
        {0.03f, 0.00f, 0.99f},
        {0.01f, 0.02f, 1.01f},
        {0.02f, 0.01f, 1.00f},
        {0.40f, 0.50f, 1.60f},  // anomaly
        {0.03f, 0.01f, 1.00f},
        {0.02f, 0.00f, 0.98f},
    };

    MovingAverage ma;
    ma_init(&ma);

    float baseline = 1.0f; // expected gravity-dominated magnitude
    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float mag = accel_magnitude(samples[i]);
        float filtered = ma_update(&ma, mag);

        if (detect_anomaly(filtered, baseline)) {
            printf("Anomaly at sample %d: mag=%.3f filtered=%.3f\n", i, mag, filtered);
        } else {
            printf("Normal at sample %d: mag=%.3f filtered=%.3f\n", i, mag, filtered);
        }
    }

    return 0;
}
