Below is a minimal working embedded-style sensor-processing pipeline for accelerometer anomaly detection. It is intentionally simple, low-memory, and suitable for microcontroller-style firmware.

## What it does
- Reads 3-axis accelerometer samples
- Computes a short-time magnitude feature
- Maintains a running baseline
- Flags anomalies when the current window deviates significantly from baseline

---

## Minimal C example

```c
#include <stdio.h>
#include <math.h>
#include <stdint.h>

#define WINDOW_SIZE 16
#define BASELINE_ALPHA 0.01f
#define ANOMALY_THRESHOLD 0.25f   // adjust for your sensor/noise level

typedef struct {
    float mag_window[WINDOW_SIZE];
    int idx;
    int count;
    float baseline_mean;
    float baseline_var;
} AnomalyDetector;

void detector_init(AnomalyDetector *d) {
    d->idx = 0;
    d->count = 0;
    d->baseline_mean = 0.0f;
    d->baseline_var = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }
}

float compute_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

int detector_update(AnomalyDetector *d, float ax, float ay, float az) {
    float mag = compute_magnitude(ax, ay, az);

    // Store in sliding window
    d->mag_window[d->idx] = mag;
    d->idx = (d->idx + 1) % WINDOW_SIZE;
    if (d->count < WINDOW_SIZE) d->count++;

    // Wait until window is filled
    if (d->count < WINDOW_SIZE) {
        return 0;
    }

    // Compute window mean
    float sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum += d->mag_window[i];
    }
    float window_mean = sum / WINDOW_SIZE;

    // Initialize baseline on first full window
    if (d->baseline_mean == 0.0f && d->baseline_var == 0.0f) {
        d->baseline_mean = window_mean;
        d->baseline_var = 0.0f;
        return 0;
    }

    // Update baseline with exponential moving average
    float diff = window_mean - d->baseline_mean;
    d->baseline_mean += BASELINE_ALPHA * diff;
    d->baseline_var = (1.0f - BASELINE_ALPHA) * d->baseline_var + BASELINE_ALPHA * diff * diff;

    // Detect anomaly if deviation is large
    float stddev = sqrtf(d->baseline_var);
    float deviation = fabsf(window_mean - d->baseline_mean);

    if (stddev > 1e-6f && deviation > ANOMALY_THRESHOLD + 3.0f * stddev) {
        return 1; // anomaly
    }

    return 0;
}

int main(void) {
    AnomalyDetector det;
    detector_init(&det);

    // Example sensor stream: normal motion then anomaly
    float data[][3] = {
        {0.01f, 0.02f, 0.98f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 0.97f},
        {0.00f, 0.01f, 0.98f},
        {0.02f, 0.01f, 1.00f},
        {0.01f, 0.00f, 0.99f},
        {0.00f, 0.02f, 0.98f},
        {0.50f, 1.20f, 2.50f}, // anomaly
        {0.60f, 1.10f, 2.40f}
    };

    int n = sizeof(data) / sizeof(data[0]);

    for (int i = 0; i < n; i++) {
        int anom = detector_update(&det, data[i][0], data[i][1], data[i][2]);
        printf("Sample %d -> anomaly=%d\n", i, anom);
    }

    return 0;
}
```

