Below is a minimal working example of an embedded-style accelerometer anomaly-detection pipeline. It assumes:

- 3-axis accelerometer input
- fixed sample rate
- simple feature extraction over a sliding window
- lightweight anomaly score based on deviation from a learned baseline
- C-like code suitable for microcontrollers

## Pipeline overview

1. **Acquire raw accelerometer samples**
2. **Filter / smooth if needed**
3. **Build a sliding window**
4. **Extract simple features**
   - mean magnitude
   - standard deviation
   - peak magnitude
5. **Compare features to baseline**
6. **Flag anomaly if score exceeds threshold**

---

## Minimal C implementation

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define AXES 3

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    accel_sample_t samples[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
} ring_buffer_t;

typedef struct {
    float mean_mag;
    float std_mag;
    float peak_mag;
} features_t;

typedef struct {
    float baseline_mean;
    float baseline_std;
    float baseline_peak;
    float threshold;
} anomaly_model_t;

static ring_buffer_t g_buf;
static anomaly_model_t g_model = {
    .baseline_mean = 1.0f,   // example: around 1g at rest
    .baseline_std   = 0.1f,
    .baseline_peak  = 1.5f,
    .threshold     = 3.0f
};

static float magnitude(accel_sample_t s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static void buffer_add(ring_buffer_t *buf, accel_sample_t s) {
    buf->samples[buf->index] = s;
    buf->index = (buf->index + 1) % WINDOW_SIZE;
    if (buf->count < WINDOW_SIZE) {
        buf->count++;
    }
}

static bool buffer_full(const ring_buffer_t *buf) {
    return buf->count == WINDOW_SIZE;
}

static features_t extract_features(const ring_buffer_t *buf) {
    features_t f = {0};
    float sum = 0.0f;
    float sum_sq = 0.0f;
    float peak = 0.0f;

    for (uint8_t i = 0; i < buf->count; i++) {
        float mag = magnitude(buf->samples[i]);
        sum += mag;
        sum_sq += mag * mag;
        if (mag > peak) {
            peak = mag;
        }
    }

    f.mean_mag = sum / buf->count;
    float var = (sum_sq / buf->count) - (f.mean_mag * f.mean_mag);
    f.std_mag = (var > 0.0f) ? sqrtf(var) : 0.0f;
    f.peak_mag = peak;
    return f;
}

static float anomaly_score(const features_t *f, const anomaly_model_t *m) {
    float score = 0.0f;

    score += fabsf(f->mean_mag - m->baseline_mean) / (m->baseline_mean + 1e-6f);
    score += fabsf(f->std_mag  - m->baseline_std)  / (m->baseline_std + 1e-6f);
    score += fabsf(f->peak_mag - m->baseline_peak) / (m->baseline_peak + 1e-6f);

    return score;
}

bool process_accel_sample(float x, float y, float z) {
    accel_sample_t s = {x, y, z};
    buffer_add(&g_buf, s);

    if (!buffer_full(&g_buf)) {
        return false; // not enough data yet
    }

    features_t f = extract_features(&g_buf);
    float score = anomaly_score(&f, &g_model);

    return score > g_model.threshold;
}
```

