Below is a minimal, embedded-friendly sensor-processing pipeline for **accelerometer anomaly detection**. It assumes you have a stream of accelerometer samples `(ax, ay, az)` and want to flag unusual motion using a simple statistical baseline.

### What it does
1. Collects raw accelerometer samples.
2. Computes a simple feature: **magnitude**.
3. Maintains a rolling mean and variance using an online update.
4. Detects an anomaly when magnitude deviates too far from the baseline.

---

## Minimal C implementation

```c
#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define WINDOW_SIZE 32
#define ANOMALY_ZSCORE_THRESHOLD 3.0f

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} OnlineStats;

typedef struct {
    float window[WINDOW_SIZE];
    uint8_t index;
    uint8_t filled;
    OnlineStats stats;
} AccelPipeline;

void stats_init(OnlineStats *s) {
    s->mean = 0.0f;
    s->m2 = 0.0f;
    s->count = 0;
}

void pipeline_init(AccelPipeline *p) {
    p->index = 0;
    p->filled = 0;
    stats_init(&p->stats);
    for (int i = 0; i < WINDOW_SIZE; i++) {
        p->window[i] = 0.0f;
    }
}

static void stats_update(OnlineStats *s, float x) {
    s->count++;
    float delta = x - s->mean;
    s->mean += delta / s->count;
    float delta2 = x - s->mean;
    s->m2 += delta * delta2;
}

static float stats_variance(const OnlineStats *s) {
    if (s->count < 2) return 0.0f;
    return s->m2 / (s->count - 1);
}

bool pipeline_process_sample(AccelPipeline *p, float ax, float ay, float az) {
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    // Warm-up phase: build baseline
    if (p->filled < WINDOW_SIZE) {
        p->window[p->index] = mag;
        p->index = (p->index + 1) % WINDOW_SIZE;
        p->filled++;

        stats_update(&p->stats, mag);
        return false; // not enough data yet to detect anomalies
    }

    float mean = p->stats.mean;
    float var = stats_variance(&p->stats);
    float stddev = sqrtf(var);

    bool anomaly = false;
    if (stddev > 1e-6f) {
        float z = fabsf(mag - mean) / stddev;
        anomaly = (z > ANOMALY_ZSCORE_THRESHOLD);
    }

    // Sliding window update: replace oldest sample
    float old = p->window[p->index];
    p->window[p->index] = mag;
    p->index = (p->index + 1) % WINDOW_SIZE;

    // Recompute stats simply for minimal clarity
    // (For embedded optimization, use an incremental sliding-window approach.)
    stats_init(&p->stats);
    for (int i = 0; i < WINDOW_SIZE; i++) {
        stats_update(&p->stats, p->window[i]);
    }

    return anomaly;
}
```

