## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 8
#define BASELINE_SAMPLES 32
#define ANOMALY_THRESHOLD 0.35f   // Tune for your sensor
#define GRAVITY 1.0f             // Use 1.0 if accel is normalized in g

typedef struct {
    float buf[WINDOW_SIZE];
    int idx;
    int count;
    float sum;
} MovingAverage;

void ma_init(MovingAverage *ma) {
    ma->idx = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) ma->buf[i] = 0.0f;
}

float ma_update(MovingAverage *ma, float x) {
    if (ma->count < WINDOW_SIZE) {
        ma->buf[ma->idx] = x;
        ma->sum += x;
        ma->count++;
    } else {
        ma->sum -= ma->buf[ma->idx];
        ma->buf[ma->idx] = x;
        ma->sum += x;
    }

    ma->idx = (ma->idx + 1) % WINDOW_SIZE;
    return ma->sum / ma->count;
}

float accel_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

int main(void) {
    MovingAverage ma;
    ma_init(&ma);

    // Example stream of accelerometer readings in "g"
    float data[][3] = {
        {0.01f, -0.02f, 1.00f},
        {0.00f,  0.01f, 0.99f},
        {0.03f, -0.01f, 1.01f},
        {0.02f,  0.00f, 1.00f},
        {0.01f,  0.02f, 0.98f},
        {0.00f,  0.01f, 1.00f},
        {0.02f, -0.03f, 1.02f},
        {0.01f,  0.00f, 0.99f},

        // Anomaly burst
        {0.80f,  0.60f, 1.40f},
        {0.90f, -0.50f, 1.20f},

        // Back to normal
        {0.00f,  0.01f, 1.00f},
        {0.02f, -0.01f, 0.98f},
    };

    int n = sizeof(data) / sizeof(data[0]);

    // Baseline estimation
    float baseline_sum = 0.0f;
    int baseline_n = 0;
    float baseline = 1.0f;

    for (int i = 0; i < n; i++) {
        float ax = data[i][0];
        float ay = data[i][1];
        float az = data[i][2];

        float mag = accel_magnitude(ax, ay, az);
        float filtered = ma_update(&ma, mag);

        if (baseline_n < BASELINE_SAMPLES) {
            baseline_sum += filtered;
            baseline_n++;
            baseline = baseline_sum / baseline_n;
            printf("Sample %d: mag=%.3f filtered=%.3f baseline=%.3f\n",
                   i, mag, filtered, baseline);
            continue;
        }

        float deviation = fabsf(filtered - baseline);

        bool anomaly = (deviation > ANOMALY_THRESHOLD);

        printf("Sample %d: mag=%.3f filtered=%.3f baseline=%.3f deviation=%.3f %s\n",
               i, mag, filtered, baseline, deviation,
               anomaly ? "ANOMALY" : "OK");

        // Optional: adapt baseline slowly when not anomalous
        if (!anomaly) {
            baseline = 0.995f * baseline + 0.005f * filtered;
        }
    }

    return 0;
}
```

