Below is a minimal working embedded-style pipeline for anomaly detection from accelerometer data. It is designed to be small, fast, and easy to port to a microcontroller or embedded Linux target.

## What it does
1. Reads 3-axis accelerometer samples
2. Computes a simple feature: vector magnitude
3. Maintains a short moving average and moving variance
4. Flags an anomaly when the current magnitude deviates too much from the recent baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ANOMALY_Z_THRESHOLD 3.0f

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float buf[WINDOW_SIZE];
    int idx;
    int count;
    float sum;
    float sumsq;
} MovingStats;

static void stats_init(MovingStats *s) {
    s->idx = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) s->buf[i] = 0.0f;
}

static void stats_push(MovingStats *s, float v) {
    if (s->count == WINDOW_SIZE) {
        float old = s->buf[s->idx];
        s->sum -= old;
        s->sumsq -= old * old;
    } else {
        s->count++;
    }

    s->buf[s->idx] = v;
    s->sum += v;
    s->sumsq += v * v;
    s->idx = (s->idx + 1) % WINDOW_SIZE;
}

static float stats_mean(const MovingStats *s) {
    return (s->count > 0) ? (s->sum / s->count) : 0.0f;
}

static float stats_stddev(const MovingStats *s) {
    if (s->count < 2) return 0.0f;
    float mean = stats_mean(s);
    float var = (s->sumsq / s->count) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    return sqrtf(var);
}

static float accel_magnitude(AccelSample a) {
    return sqrtf(a.x * a.x + a.y * a.y + a.z * a.z);
}

static bool detect_anomaly(MovingStats *baseline, float mag) {
    float mean = stats_mean(baseline);
    float stddev = stats_stddev(baseline);

    // Not enough history yet: initialize baseline and don't detect anomalies
    if (baseline->count < WINDOW_SIZE) {
        stats_push(baseline, mag);
        return false;
    }

    float z = (stddev > 1e-6f) ? fabsf(mag - mean) / stddev : 0.0f;

    // Update baseline after scoring the current sample
    stats_push(baseline, mag);

    return z > ANOMALY_Z_THRESHOLD;
}

int main(void) {
    MovingStats baseline;
    stats_init(&baseline);

    // Replace this with real sensor reads
    AccelSample stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 1.00f},
        {0.50f, 0.80f, 1.70f}, // anomaly candidate
        {0.01f, 0.02f, 1.00f},
    };

    int n = sizeof(stream) / sizeof(stream[0]);

    for (int i = 0; i < n; i++) {
        float mag = accel_magnitude(stream[i]);
        bool anomaly = detect_anomaly(&baseline, mag);

        printf("sample %d: mag=%.3f %s\n",
               i,
               mag,
               anomaly ? "ANOMALY" : "ok");
    }

    return 0;
}
