## What it does
- Reads 3-axis accelerometer samples
- Computes a simple motion feature: **magnitude**
- Maintains a **running baseline**
- Flags an anomaly when the current magnitude deviates too far from baseline

---

## Minimal C implementation

```c
#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>

#define BASELINE_WINDOW 32
#define ANOMALY_THRESHOLD 2.5f   // Tune for your sensor/noise level

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float window[BASELINE_WINDOW];
    int index;
    int count;
    float sum;
} baseline_filter_t;

static void baseline_init(baseline_filter_t *f) {
    f->index = 0;
    f->count = 0;
    f->sum = 0.0f;
    for (int i = 0; i < BASELINE_WINDOW; i++) {
        f->window[i] = 0.0f;
    }
}

static float accel_magnitude(accel_sample_t s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

// Returns true if anomaly detected
static bool process_sample(baseline_filter_t *f, accel_sample_t s) {
    float mag = accel_magnitude(s);

    // Compute current baseline mean
    float baseline = (f->count > 0) ? (f->sum / f->count) : mag;

    // Simple anomaly rule: large deviation from baseline
    float deviation = fabsf(mag - baseline);
    bool anomaly = (f->count >= BASELINE_WINDOW) && (deviation > ANOMALY_THRESHOLD);

    // Update running window baseline
    if (f->count < BASELINE_WINDOW) {
        f->window[f->index] = mag;
        f->sum += mag;
        f->count++;
    } else {
        f->sum -= f->window[f->index];
        f->window[f->index] = mag;
        f->sum += mag;
    }

    f->index = (f->index + 1) % BASELINE_WINDOW;

    return anomaly;
}

int main(void) {
    baseline_filter_t filter;
    baseline_init(&filter);

    // Example stream: mostly steady data, then a spike
    accel_sample_t samples[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.01f, 1.00f},
        {0.00f, 0.02f, 1.00f},
        {1.50f, 1.20f, 2.80f},   // anomaly-like
        {0.01f, 0.02f, 1.00f},
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        bool anomaly = process_sample(&filter, samples[i]);
        float mag = accel_magnitude(samples[i]);

        printf("Sample %d: mag=%.3f -> %s\n",
               i, mag, anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
