Below is a minimal working embedded-style pipeline for accelerometer anomaly detection. It is intentionally simple and suitable for a microcontroller or firmware prototype.

## What it does
- Reads 3-axis accelerometer samples
- Applies a tiny low-pass filter
- Computes a rolling magnitude feature
- Detects anomalies using a threshold on deviation from a baseline
- Emits a boolean anomaly flag

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define BASELINE_SAMPLES 64
#define ANOMALY_THRESHOLD 1.8f   // tune for your sensor/noise
#define LPF_ALPHA 0.2f

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float lpf_x, lpf_y, lpf_z;
    float window[WINDOW_SIZE];
    int window_idx;
    int window_count;
    float baseline_mean;
    float baseline_var;
    int baseline_count;
    bool baseline_ready;
} PipelineState;

static float fast_sqrtf(float v) {
    return sqrtf(v);
}

static float magnitude(const AccelSample* s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

void pipeline_init(PipelineState* st) {
    st->lpf_x = st->lpf_y = st->lpf_z = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) st->window[i] = 0.0f;
    st->window_idx = 0;
    st->window_count = 0;
    st->baseline_mean = 0.0f;
    st->baseline_var = 0.0f;
    st->baseline_count = 0;
    st->baseline_ready = false;
}

static AccelSample low_pass_filter(PipelineState* st, AccelSample in) {
    st->lpf_x = LPF_ALPHA * in.x + (1.0f - LPF_ALPHA) * st->lpf_x;
    st->lpf_y = LPF_ALPHA * in.y + (1.0f - LPF_ALPHA) * st->lpf_y;
    st->lpf_z = LPF_ALPHA * in.z + (1.0f - LPF_ALPHA) * st->lpf_z;
    AccelSample out = { st->lpf_x, st->lpf_y, st->lpf_z };
    return out;
}

static void update_window(PipelineState* st, float value) {
    st->window[st->window_idx] = value;
    st->window_idx = (st->window_idx + 1) % WINDOW_SIZE;
    if (st->window_count < WINDOW_SIZE) st->window_count++;
}

static float window_mean(const PipelineState* st) {
    float sum = 0.0f;
    for (int i = 0; i < st->window_count; i++) sum += st->window[i];
    return (st->window_count > 0) ? sum / st->window_count : 0.0f;
}

// Online baseline using simple running mean/variance (Welford-style simplified)
static void update_baseline(PipelineState* st, float value) {
    st->baseline_count++;
    float delta = value - st->baseline_mean;
    st->baseline_mean += delta / st->baseline_count;
    float delta2 = value - st->baseline_mean;
    st->baseline_var += delta * delta2; // sum of squared diffs
    if (st->baseline_count >= BASELINE_SAMPLES) {
        st->baseline_ready = true;
    }
}

static float baseline_stddev(const PipelineState* st) {
    if (st->baseline_count < 2) return 0.0f;
    return fast_sqrtf(st->baseline_var / (st->baseline_count - 1));
}

// Returns true if anomaly detected
bool pipeline_process(PipelineState* st, AccelSample raw) {
    AccelSample filtered = low_pass_filter(st, raw);
    float mag = magnitude(&filtered);

    // Build baseline first
    if (!st->baseline_ready) {
        update_baseline(st, mag);
        return false;
    }

    update_window(st, mag);
    float win_mean = window_mean(st);
    float stddev = baseline_stddev(st);

    float deviation = fabsf(win_mean - st->baseline_mean);

    // Anomaly if deviation is large compared to baseline noise
    if (stddev > 1e-6f && deviation > ANOMALY_THRESHOLD * stddev) {
        return true;
    }

    return false;
}

// Example stub sensor function
AccelSample read_accelerometer_stub(int i) {
    // Normal motion
    if (i < 100) return (AccelSample){0.02f, 0.01f, 1.02f};

    // Inject anomaly pulse
    if (i >= 100 && i < 110) return (AccelSample){3.0f, 2.5f, 0.2f};

    // Back to normal
    return (AccelSample){0.01f, 0.02f, 1.00f};
}

int main(void) {
    PipelineState st;
    pipeline_init(&st);

    for (int i = 0; i < 150; i++) {
        AccelSample sample = read_accelerometer_stub(i);
        bool anomaly = pipeline_process(&st, sample);

        printf("Sample %3d: ax=%.2f ay=%.2f az=%.2f -> anomaly=%s\n",
               i, sample.x, sample.y, sample.z, anomaly ? "YES" : "NO");
    }

    return 0;
}
```

