Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from **accelerometer data**. It’s written in **C** and designed to be small enough to run on a microcontroller or as a starting point for firmware.

## What it does
- Reads 3-axis accelerometer samples: `x, y, z`
- Computes a simple feature: **acceleration magnitude**
- Maintains a rolling baseline using a moving average
- Flags an anomaly when the current magnitude deviates too far from the baseline

---

## Minimal C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 2.0f   // Tune for your sensor and use case

typedef struct {
    float mag_buffer[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
} MovingAverageState;

static void ma_init(MovingAverageState *s) {
    s->index = 0;
    s->count = 0;
    s->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        s->mag_buffer[i] = 0.0f;
    }
}

static float ma_update(MovingAverageState *s, float value) {
    if (s->count < WINDOW_SIZE) {
        s->mag_buffer[s->index] = value;
        s->sum += value;
        s->count++;
    } else {
        s->sum -= s->mag_buffer[s->index];
        s->mag_buffer[s->index] = value;
        s->sum += value;
    }

    s->index = (s->index + 1) % WINDOW_SIZE;
    return s->sum / s->count;
}

typedef struct {
    MovingAverageState baseline;
} AnomalyDetector;

void detector_init(AnomalyDetector *d) {
    ma_init(&d->baseline);
}

bool detector_process_sample(AnomalyDetector *d, int16_t ax, int16_t ay, int16_t az) {
    // Convert raw accelerometer readings to a simple magnitude
    float fx = (float)ax;
    float fy = (float)ay;
    float fz = (float)az;

    float magnitude = sqrtf(fx * fx + fy * fy + fz * fz);

    // Update baseline
    float baseline = ma_update(&d->baseline, magnitude);

    // Anomaly condition: large deviation from running average
    float deviation = fabsf(magnitude - baseline);

    return (d->baseline.count >= WINDOW_SIZE) && (deviation > ANOMALY_THRESHOLD);
}
```

