Below is a **minimal working embedded-style sensor-processing pipeline** for **anomaly detection from accelerometer data**. It’s designed to be simple enough for a microcontroller or embedded Linux target, while still being realistic.

## Pipeline overview
1. **Acquire accelerometer sample**
2. **Apply simple filtering**
3. **Compute short window features**
4. **Compare against a baseline**
5. **Raise anomaly flag if threshold exceeded**

---

## Minimal C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE 32
#define THRESHOLD_Z 3.0f

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float samples[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
    float sum_sq;
} feature_window_t;

typedef struct {
    float mean;
    float stddev;
} baseline_t;

/* Initialize feature window */
void window_init(feature_window_t *w) {
    w->index = 0;
    w->count = 0;
    w->sum = 0.0f;
    w->sum_sq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->samples[i] = 0.0f;
    }
}

/* Add sample magnitude to rolling window */
void window_add(feature_window_t *w, float value) {
    if (w->count < WINDOW_SIZE) {
        w->samples[w->index] = value;
        w->sum += value;
        w->sum_sq += value * value;
        w->count++;
    } else {
        float old = w->samples[w->index];
        w->samples[w->index] = value;
        w->sum += value - old;
        w->sum_sq += value * value - old * old;
    }
    w->index = (w->index + 1) % WINDOW_SIZE;
}

/* Compute mean */
float window_mean(const feature_window_t *w) {
    if (w->count == 0) return 0.0f;
    return w->sum / (float)w->count;
}

/* Compute standard deviation */
float window_stddev(const feature_window_t *w) {
    if (w->count < 2) return 0.0f;
    float mean = window_mean(w);
    float variance = (w->sum_sq / (float)w->count) - (mean * mean);
    if (variance < 0.0f) variance = 0.0f;
    return sqrtf(variance);
}

/* Simple magnitude from 3-axis accelerometer */
float accel_magnitude(accel_sample_t s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

/* Basic anomaly detection using z-score */
bool detect_anomaly(const feature_window_t *w, const baseline_t *b, float current_value) {
    if (b->stddev < 1e-6f) return false;

    float z = (current_value - b->mean) / b->stddev;
    if (z < 0.0f) z = -z;

    return (z > THRESHOLD_Z);
}

/* Example processing step */
bool process_accel_sample(feature_window_t *w, const baseline_t *baseline, accel_sample_t raw) {
    float mag = accel_magnitude(raw);

    // Minimal filtering: could be replaced with low-pass filter
    window_add(w, mag);

    // Wait until window is full
    if (w->count < WINDOW_SIZE) {
        return false;
    }

    return detect_anomaly(w, baseline, mag);
}
```

