```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define WINDOW_SIZE 8
#define BASELINE_SIZE 32
#define ANOMALY_THRESHOLD 1.5f   // adjust for your sensor/noise levels

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float window[WINDOW_SIZE];
    int idx;
    int count;
    float sum;
} MovingAverage;

typedef struct {
    float baseline[BASELINE_SIZE];
    int idx;
    int count;
} BaselineBuffer;

static void ma_init(MovingAverage *ma) {
    ma->idx = 0;
    ma->count = 0;
    ma->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) ma->window[i] = 0.0f;
}

static float ma_update(MovingAverage *ma, float value) {
    if (ma->count < WINDOW_SIZE) {
        ma->count++;
    } else {
        ma->sum -= ma->window[ma->idx];
    }

    ma->window[ma->idx] = value;
    ma->sum += value;
    ma->idx = (ma->idx + 1) % WINDOW_SIZE;

    return ma->sum / ma->count;
}

static void baseline_init(BaselineBuffer *b) {
    b->idx = 0;
    b->count = 0;
    for (int i = 0; i < BASELINE_SIZE; i++) b->baseline[i] = 0.0f;
}

static void baseline_update(BaselineBuffer *b, float value) {
    b->baseline[b->idx] = value;
    b->idx = (b->idx + 1) % BASELINE_SIZE;
    if (b->count < BASELINE_SIZE) b->count++;
}

static float baseline_mean(const BaselineBuffer *b) {
    if (b->count == 0) return 0.0f;

    float sum = 0.0f;
    for (int i = 0; i < b->count; i++) {
        sum += b->baseline[i];
    }
    return sum / b->count;
}

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

// Returns true if anomaly detected
static bool process_sample(AccelSample sample,
                           MovingAverage *ma,
                           BaselineBuffer *baseline,
                           bool baseline_ready) {
    float mag = accel_magnitude(sample);
    float filtered = ma_update(ma, mag);

    if (!baseline_ready) {
        baseline_update(baseline, filtered);
        return false;
    }

    float mean = baseline_mean(baseline);
    float deviation = fabsf(filtered - mean);

    return deviation > ANOMALY_THRESHOLD;
}

int main(void) {
    MovingAverage ma;
    BaselineBuffer baseline;

    ma_init(&ma);
    baseline_init(&baseline);

    // Simulated accelerometer stream
    AccelSample stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.02f, 0.01f, 0.98f},
        {0.00f, 0.03f, 1.01f},
        {0.01f, 0.01f, 1.00f},
        {0.02f, 0.02f, 0.99f},
        {0.05f, 0.10f, 1.20f},  // potential anomaly
        {0.30f, 0.40f, 1.80f},  // anomaly
        {0.01f, 0.02f, 1.00f},
    };

    int n = sizeof(stream) / sizeof(stream[0]);

    for (int i = 0; i < n; i++) {
        bool baseline_ready = (baseline.count >= BASELINE_SIZE / 2); // simple warm-up
        bool anomaly = process_sample(stream[i], &ma, &baseline, baseline_ready);

        // During warm-up, keep updating baseline
        if (!baseline_ready) {
            baseline_update(&baseline, ma.sum / ma.count);
        }

        printf("Sample %d: x=%.2f y=%.2f z=%.2f -> %s\n",
               i,
               stream[i].x, stream[i].y, stream[i].z,
               anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
