extern uint32_t millis(void);            // system uptime in ms
extern void sleep_until_next_tick(void); // low-power wait / idle

// ---- Simple running average filter ----
typedef struct {
    uint16_t buf[FILTER_WINDOW];
    uint8_t  idx;
    uint8_t  count;
    uint32_t sum;
} MovingAverageFilter;

static void filter_init(MovingAverageFilter *f) {
    f->idx = 0;
    f->count = 0;
    f->sum = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buf[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    // Remove oldest sample from sum
    f->sum -= f->buf[f->idx];

    // Insert new sample
    f->buf[f->idx] = sample;
    f->sum += sample;

    // Advance index
    f->idx = (f->idx + 1) % FILTER_WINDOW;

    // Increase count until buffer is full
    if (f->count < FILTER_WINDOW) {
        f->count++;
    }

    return (uint16_t)(f->sum / f->count);
}

// ---- Control logic with hysteresis ----
typedef struct {
    bool actuator_on;
} ControlState;

static void control_init(ControlState *c) {
    c->actuator_on = false;
    set_actuator(ACTUATOR_OFF);
}

static void control_update(ControlState *c, uint16_t filtered_value) {
    if (!c->actuator_on && filtered_value >= THRESH_ON) {
        c->actuator_on = true;
        set_actuator(ACTUATOR_ON);
    } else if (c->actuator_on && filtered_value <= THRESH_OFF) {
        c->actuator_on = false;
        set_actuator(ACTUATOR_OFF);
    }
}

// ---- Main application ----
int main(void) {
    MovingAverageFilter filter;
    ControlState control;

    filter_init(&filter);
    control_init(&control);

    uint32_t last_sample_time = 0;

    while (1) {
        uint32_t now = millis();

        if ((now - last_sample_time) >= SAMPLE_PERIOD_MS) {
            last_sample_time = now;

            uint16_t raw = read_sensor_raw();
            uint16_t filtered = filter_update(&filter, raw);

            control_update(&control, filtered);
        }

        // Sleep or idle to save power
        sleep_until_next_tick();
    }

    return 0;
}
