        set_actuator_off();
    }

    // Optional modulation window
    if (filtered_value >= FILTER_THRESHOLD_LOW && filtered_value <= FILTER_THRESHOLD_HIGH) {
        a->state = ACT_MODULATE;

        // Map value to PWM duty between MIN and MAX
        uint16_t span = (FILTER_THRESHOLD_HIGH - FILTER_THRESHOLD_LOW);
        uint16_t pos = filtered_value - FILTER_THRESHOLD_LOW;
        uint8_t duty = (uint8_t)((pos * ACTUATOR_MAX) / span);

        a->pwm_duty = duty;
        set_actuator_pwm(duty);
    }
}

// ---------- Main application ----------
int main(void) {
    MovingAverageFilter filter;
    ActuatorControl actuator;

    maf_init(&filter);
    actuator_init(&actuator);

    const uint32_t sample_period_ms = 50;
    uint32_t last_sample = 0;

    while (1) {
        uint32_t now = millis();

        if ((now - last_sample) >= sample_period_ms) {
            last_sample = now;

            uint16_t raw = read_sensor_raw();
            uint16_t filtered = maf_update(&filter, raw);

            actuator_update(&actuator, filtered);
        }

        watchdog_kick();
        sleep_ms(1);
    }

    return 0;
}
