    uint16_t buf[FILTER_WINDOW];
    uint8_t idx;
    uint8_t count;
    uint32_t sum;
} MovingAvgFilter;

static void filter_init(MovingAvgFilter *f) {
    f->idx = 0;
    f->count = 0;
    f->sum = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buf[i] = 0;
    }
}

static uint16_t filter_update(MovingAvgFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW) {
        f->count++;
    } else {
        f->sum -= f->buf[f->idx];
    }

    f->buf[f->idx] = sample;
    f->sum += sample;

    f->idx = (uint8_t)((f->idx + 1) % FILTER_WINDOW);

    return (uint16_t)(f->sum / f->count);
}

/* Actuator state machine with hysteresis and max on-time */
typedef struct {
    bool on;
    uint32_t on_since_ms;
} ActuatorControl;

