    a->on = false;
    a->on_since_ms = 0;
    gpio_write(false);
}

static void actuator_update(ActuatorControl *a, uint16_t filtered_value) {
    uint32_t now = millis();

    /* Turn on if above threshold */
    if (!a->on && filtered_value >= SENSOR_THRESHOLD) {
        a->on = true;
        a->on_since_ms = now;
        gpio_write(true);
    }

    /* Turn off only after dropping below threshold minus hysteresis */
    if (a->on && filtered_value <= (SENSOR_THRESHOLD - SENSOR_HYSTERESIS)) {
        a->on = false;
        gpio_write(false);
