/*
 * edge_controller.c
 *
 * Resource-constrained edge system:
 * - Integer low-pass filter
 * - Hysteresis-based event detection
 * - Simple actuator state machine
 * - No dynamic memory allocation
 * - Suitable for bare-metal or small RTOS targets
 */

#include <stdint.h>
#include <stdbool.h>

/* -------------------- Hardware abstraction -------------------- */

/* Replace these with platform-specific implementations */
extern int16_t read_sensor_raw(void);        /* Returns raw ADC/sensor sample */
extern void set_actuator_on(void);           /* Turn actuator ON */
extern void set_actuator_off(void);          /* Turn actuator OFF */
extern void set_alarm_on(void);              /* Optional alarm */
extern void set_alarm_off(void);             /* Optional alarm */
extern uint32_t millis(void);                /* System time in ms */

/* -------------------- Configuration -------------------- */

#define FILTER_SHIFT        3   /* alpha = 1/8 for IIR low-pass */
#define SAMPLE_PERIOD_MS    10
#define THRESH_HIGH         700
#define THRESH_LOW          650
#define ACTUATOR_TIMEOUT_MS 5000

/* -------------------- Types -------------------- */

typedef enum {
    ACT_STATE_IDLE = 0,
    ACT_STATE_ACTIVE,
    ACT_STATE_FAULT
} actuator_state_t;

/* -------------------- Module state -------------------- */

static int32_t filtered_value = 0;
static bool filter_initialized = false;

static actuator_state_t actuator_state = ACT_STATE_IDLE;
static uint32_t active_since_ms = 0;

/* -------------------- Filtering -------------------- */

/*
 * First-order IIR low-pass filter:
 * y[n] = y[n-1] + (x[n] - y[n-1]) / 2^FILTER_SHIFT
 *
 * Integer-only implementation.
 */
static int16_t low_pass_filter(int16_t sample)
{
    if (!filter_initialized) {
        filtered_value = sample;
        filter_initialized = true;
        return sample;
    }

    filtered_value += ((int32_t)sample - filtered_value) >> FILTER_SHIFT;
    return (int16_t)filtered_value;
}

/* -------------------- Control logic -------------------- */

static void update_actuator_state(int16_t value, uint32_t now_ms)
{
    switch (actuator_state) {
    case ACT_STATE_IDLE:
        if (value >= THRESH_HIGH) {
            set_actuator_on();
            set_alarm_off();
            actuator_state = ACT_STATE_ACTIVE;
            active_since_ms = now_ms;
        }
        break;

    case ACT_STATE_ACTIVE:
        /* Hysteresis: remain active until value drops below low threshold */
        if (value <= THRESH_LOW) {
            set_actuator_off();
            actuator_state = ACT_STATE_IDLE;
        } else if ((now_ms - active_since_ms) > ACTUATOR_TIMEOUT_MS) {
            /* Safety timeout */
            set_actuator_off();
            set_alarm_on();
            actuator_state = ACT_STATE_FAULT;
        }
        break;

    case ACT_STATE_FAULT:
        /* Fault latch: requires external reset logic if needed */
        set_actuator_off();
        break;

    default:
        set_actuator_off();
        actuator_state = ACT_STATE_FAULT;
        break;
    }
}

/* Optional: call this from an external event to clear fault */
void controller_reset_fault(void)
{
    actuator_state = ACT_STATE_IDLE;
    set_alarm_off();
    set_actuator_off();
}

/* -------------------- Main processing loop -------------------- */

void controller_tick(void)
{
    static uint32_t last_sample_ms = 0;
    uint32_t now = millis();

    if ((now - last_sample_ms) < SAMPLE_PERIOD_MS) {
        return;
    }
    last_sample_ms = now;

    int16_t raw = read_sensor_raw();
    int16_t filtered = low_pass_filter(raw);

    update_actuator_state(filtered, now);
}

