extern uint16_t read_sensor_raw(void);      // ADC or sensor read
extern void set_fan(bool on);
extern void set_valve(bool on);
extern void delay_ms(uint32_t ms);

/* ---------- Configuration ---------- */

#define FILTER_ALPHA_NUM   1u   // EMA numerator
#define FILTER_ALPHA_DEN   8u   // EMA denominator
#define SAMPLE_PERIOD_MS   100u

#define TEMP_HIGH_THRESHOLD   700u
#define TEMP_LOW_THRESHOLD    600u

/* ---------- State ---------- */

typedef struct {
    uint32_t ema_accum;   // fixed-point filtered value
    bool initialized;
} FilterState;

typedef struct {
    bool fan_on;
    bool valve_on;
} ActuatorState;

/* ---------- Filtering ---------- */
/*
 * Fixed-point EMA:
 *   y[n] = y[n-1] + alpha * (x[n] - y[n-1])
 * with alpha = 1/8
 */
static uint16_t filter_update(FilterState *st, uint16_t sample)
{
    if (!st->initialized) {
        st->ema_accum = sample << 3;   // keep extra fractional bits
        st->initialized = true;
        return sample;
    }

    uint32_t y = st->ema_accum >> 3;
    int32_t diff = (int32_t)sample - (int32_t)y;

    st->ema_accum += (diff * (int32_t)FILTER_ALPHA_NUM);
    st->ema_accum -= (st->ema_accum >> 3) * (FILTER_ALPHA_NUM - 1u); // safe for alpha=1/8 style

    return (uint16_t)(st->ema_accum >> 3);
}

/* ---------- Control logic ---------- */

static void control_update(ActuatorState *act, uint16_t filtered_temp)
{
    /* Hysteresis prevents rapid toggling */
    if (!act->fan_on && filtered_temp >= TEMP_HIGH_THRESHOLD) {
        act->fan_on = true;
        set_fan(true);
    } else if (act->fan_on && filtered_temp <= TEMP_LOW_THRESHOLD) {
        act->fan_on = false;
        set_fan(false);
    }

    /* Example second actuator: valve opens only if very hot */
    if (filtered_temp >= (TEMP_HIGH_THRESHOLD + 50u)) {
        if (!act->valve_on) {
            act->valve_on = true;
            set_valve(true);
        }
    } else if (filtered_temp <= TEMP_LOW_THRESHOLD) {
        if (act->valve_on) {
            act->valve_on = false;
            set_valve(false);
        }
    }
}

/* ---------- Main loop ---------- */

int main(void)
{
    FilterState filter = {0};
    ActuatorState actuators = {false, false};

    /* Initialize outputs to safe state */
    set_fan(false);
    set_valve(false);

    while (1) {
        uint16_t raw = read_sensor_raw();
        uint16_t filtered = filter_update(&filter, raw);

        control_update(&actuators, filtered);

        delay_ms(SAMPLE_PERIOD_MS);
    }

    return 0;
}
