     * current = current + alpha * (sample - current)
     * alpha = 1/8 here, implemented with bit shift for efficiency.
     */
    return current + ((int32_t)(sample - current) * FILTER_ALPHA_NUM) / FILTER_ALPHA_DEN;
}

/* ---------------- Actuator Control ---------------- */

static void update_fan(bool enable)
{
    if (g_state.fan_on != enable) {
        g_state.fan_on = enable;
        set_gpio(ACTUATOR_FAN_PIN, enable);
