{
    g_state.temp_filtered = ema_update(g_state.temp_filtered, temp_raw);
    g_state.hum_filtered  = ema_update(g_state.hum_filtered, hum_raw);

    /* Fan control with hysteresis */
    if (!g_state.fan_on && g_state.temp_filtered >= TEMP_HIGH_C) {
