    if (!g_state.pump_on && g_state.hum_filtered >= HUM_HIGH) {
        update_pump(true);
    } else if (g_state.pump_on && g_state.hum_filtered <= HUM_LOW) {
        update_pump(false);
    }
}

/* ---------------- Main Loop ---------------- */

void edge_task(void)
{
    /* Run every 100 ms or from scheduler tick */
    uint32_t now = millis();
    if ((now - g_state.last_update_ms) < 100) {
        return;
    }
    g_state.last_update_ms = now;

    int16_t temp = read_temperature_raw();
    int16_t hum  = read_humidity_raw();

    process_readings(temp, hum);
}

