            if (!request_on && filtered >= THRESH_ON) {
                request_on = true;
            } else if (request_on && filtered <= THRESH_OFF) {
                request_on = false;
            }

            // 4) Update actuator
            actuator_update(&actuator, request_on);
        }

        // Optional: enter low-power mode here until next interrupt/tick
        // platform_sleep();
    }

    return 0;
}
```

### Notes
- `FILTER_WINDOW = 8` keeps memory usage low.
- Hysteresis (`THRESH_ON`, `THRESH_OFF`) reduces actuator chatter.
- `ACTUATOR_MIN_ON_MS` prevents rapid toggling.
- No heap usage; all state is static/stack-based.

