```python
import random
import time

class MovingAverageFilter:
    def __init__(self, window_size=4):
        self.window_size = window_size
        self.buffer = [0] * window_size
        self.index = 0
        self.count = 0
        self.total = 0

    def update(self, value):
        # Remove old value from running total
        old_value = self.buffer[self.index]
        self.total -= old_value

        # Insert new value
        self.buffer[self.index] = value
        self.total += value

        # Move circular index
        self.index = (self.index + 1) % self.window_size
        self.count = min(self.count + 1, self.window_size)

        # Return average
        return self.total / self.count


class Actuator:
    def __init__(self):
        self.state = False

    def on(self):
        if not self.state:
            self.state = True
            print("Actuator ON")

    def off(self):
        if self.state:
            self.state = False
            print("Actuator OFF")


class EdgeController:
    def __init__(self, threshold=70, window_size=4):
        self.filter = MovingAverageFilter(window_size)
        self.actuator = Actuator()
        self.threshold = threshold

    def read_sensor(self):
        # Simulated noisy sensor value
        base = 65
        noise = random.randint(-10, 15)
        return base + noise

    def process(self):
        raw = self.read_sensor()
        filtered = self.filter.update(raw)

        print(f"raw={raw:3d}, filtered={filtered:5.1f}")

        if filtered >= self.threshold:
            self.actuator.on()
        else:
            self.actuator.off()


def main():
    controller = EdgeController(threshold=70, window_size=4)

    for _ in range(20):
        controller.process()
        time.sleep(0.5)


if __name__ == "__main__":
    main()
```

