def control_logic(filtered_value, actuator):
    if filtered_value > THRESHOLD_HIGH:
        actuator.set_state(True)
    elif filtered_value < THRESHOLD_LOW:
        actuator.set_state(False)

# ----------------------------
# Main Loop
# ----------------------------
def main():
    sensor_filter = MovingAverageFilter(WINDOW_SIZE)
    actuator = Actuator()

    print("Starting edge system...")
    try:
        while True:
            raw = read_sensor()
            filtered = sensor_filter.update(raw)

            print(f"Raw: {raw:>3} | Filtered: {filtered:>5.1f}")

            control_logic(filtered, actuator)

            time.sleep(SAMPLE_INTERVAL_SEC)
    except KeyboardInterrupt:
        print("\nStopping edge system.")

if __name__ == "__main__":
