## 4) Reference implementation in C-like pseudocode

```c
#include <stdio.h>
#include <stdbool.h>

#define ALPHA 0.2f
#define HIGH_THRESHOLD 30.0f
#define LOW_THRESHOLD 27.0f

typedef struct {
    float filtered;
    bool initialized;
    bool actuator_on;
} SystemState;

float read_sensor(void) {
    // Replace with ADC/I2C/SPI read
    static float mock = 25.0f;
    mock += 0.7f; // demo only
    return mock;
}

void set_actuator(bool on) {
    if (on) {
        printf("ACTUATOR: ON\n");
    } else {
        printf("ACTUATOR: OFF\n");
    }
}

void report_event(float value, bool actuator_on) {
    printf("REPORT: filtered=%.2f actuator=%s\n",
           value, actuator_on ? "ON" : "OFF");
}

float exponential_filter(float input, SystemState *s) {
    if (!s->initialized) {
        s->filtered = input;
        s->initialized = true;
    } else {
        s->filtered = ALPHA * input + (1.0f - ALPHA) * s->filtered;
    }
    return s->filtered;
}

void control_logic(SystemState *s, float value) {
    if (!s->actuator_on && value > HIGH_THRESHOLD) {
        s->actuator_on = true;
        set_actuator(true);
        report_event(value, true);
    } else if (s->actuator_on && value < LOW_THRESHOLD) {
        s->actuator_on = false;
        set_actuator(false);
        report_event(value, false);
    }
}

int main(void) {
    SystemState sys = {0};

    while (1) {
        float raw = read_sensor();
        float filtered = exponential_filter(raw, &sys);
        control_logic(&sys, filtered);

        // sleep/delay 1 second here on real hardware
        printf("RAW=%.2f FILTERED=%.2f\n", raw, filtered);
        break; // demo exit
    }

    return 0;
}
