  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const coinEl = document.getElementById("coins");

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
      if (["arrowup", " ", "w"].includes(e.key.toLowerCase())) e.preventDefault();
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    const TILE = 32;
    const GRAVITY = 2200;
    const MOVE_SPEED = 280;
    const JUMP_SPEED = 720;
    const FRICTION = 0.82;

    const world = {
      width: 30,
      height: 17,
      solids: [],
      coins: []
    };

    // Simple level layout:
    // # = platform
    // . = empty
    const level = [
      "..............................",
      "..............................",
      "..............................",
      "..............C...............",
      ".....................###......",
      ".............###..............",
      "..............................",
      "....###.......................",
      "...........................C..",
      ".............####.............",
      "..............................",
      "...........C..................",
      ".....###......................",
      "..............................",
      "..............###.............",
      "##############################",
      "##############################"
    ];

    function buildLevel() {
      world.solids = [];
      world.coins = [];
      for (let y = 0; y < level.length; y++) {
        for (let x = 0; x < level[y].length; x++) {
          const ch = level[y][x];
          if (ch === "#") {
            world.solids.push({ x: x * TILE, y: y * TILE, w: TILE, h: TILE });
          } else if (ch === "C") {
            world.coins.push({
              x: x * TILE + 8,
              y: y * TILE + 8,
              w: 16,
              h: 16,
              collected: false,
              t: 0
            });
          }
        }
      }
    }

    const player = {
      x: 100,
      y: 100,
      w: 24,
      h: 32,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle",
      coinCount: 0
    };

    function aabb(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids, axis) {
      for (const s of solids) {
        if (aabb(entity, s)) {
          if (axis === "x") {
            if (entity.vx > 0) entity.x = s.x - entity.w;
            else if (entity.vx < 0) entity.x = s.x + s.w;
            entity.vx = 0;
          } else if (axis === "y") {
            if (entity.vy > 0) {
              entity.y = s.y - entity.h;
              entity.onGround = true;
            } else if (entity.vy < 0) {
              entity.y = s.y + s.h;
            }
            entity.vy = 0;
          }
        }
      }
    }

    function update(dt) {
      // Input
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      if (move !== 0) player.facing = move;

      player.vx += move * MOVE_SPEED * dt;

      if (!move) {
        player.vx *= Math.pow(FRICTION, dt * 60);
      }

      // Clamp horizontal speed
      player.vx = Math.max(-MOVE_SPEED, Math.min(MOVE_SPEED, player.vx));

      // Jump
      const jumpPressed = keys["w"] || keys["arrowup"] || keys[" "];
      if (jumpPressed && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY * dt;

      // Horizontal move and collision
      player.x += player.vx * dt;
      player.onGround = false;
      resolveCollisions(player, world.solids, "x");

      // Vertical move and collision
      player.y += player.vy * dt;
      resolveCollisions(player, world.solids, "y");

      // Fell off screen reset
      if (player.y > canvas.height + 200) {
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Coin collection
      for (const coin of world.coins) {
        if (!coin.collected) {
          coin.t += dt * 8;
          if (aabb(player, coin)) {
            coin.collected = true;
            player.coinCount++;
            coinEl.textContent = player.coinCount;
          }
        }
      }

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 20) {
        player.state = "run";
        player.animTime += dt * 12;
      } else {
        player.state = "idle";
        player.animTime += dt * 4;
      }
    }

