        ctx.fillStyle = "#5b3a29";
        ctx.fillRect(s.x, s.y, s.w, s.h);

        ctx.fillStyle = "#7b4f35";
        ctx.fillRect(s.x, s.y, s.w, 6);
      }

      // Coins
      for (const coin of world.coins) {
        if (coin.collected) continue;
        const bob = Math.sin(coin.t) * 4;
        ctx.save();
        ctx.translate(coin.x + coin.w / 2, coin.y + coin.h / 2 + bob);
        ctx.fillStyle = "#ffd700";
        ctx.beginPath();
        ctx.arc(0, 0, 8, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#ffef99";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, 5, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }
    }

    function drawPlayer() {
      const x = player.x;
      const y = player.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);

      if (player.facing === -1) ctx.scale(-1, 1);

      // Simple animated sprite built from shapes
      const walk = player.state === "run" ? Math.sin(player.animTime) : 0;
      const jump = player.state === "jump";

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.18)";
      ctx.beginPath();
      ctx.ellipse(0, player.h / 2 + 6, 14, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // body
      ctx.fillStyle = "#2f80ed";
      ctx.fillRect(-10, -8, 20, 20);

