      ctx.lineWidth = 4;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(-10, -4);
      ctx.lineTo(-16, 4 + walk * 2);
      ctx.moveTo(10, -4);
      ctx.lineTo(16, 4 - walk * 2);
      ctx.stroke();

      // legs
      ctx.strokeStyle = "#1f4f99";
      ctx.beginPath();
      if (jump) {
        ctx.moveTo(-5, 12);
        ctx.lineTo(-8, 22);
        ctx.moveTo(5, 12);
        ctx.lineTo(8, 22);
      } else {
        ctx.moveTo(-5, 12);
        ctx.lineTo(-8 - walk * 2, 22);
        ctx.moveTo(5, 12);
        ctx.lineTo(8 + walk * 2, 22);
      }
      ctx.stroke();

      // outline
      ctx.strokeStyle = "rgba(0,0,0,0.2)";
      ctx.lineWidth = 1;
      ctx.strokeRect(-10, -8, 20, 20);
      ctx.strokeRect(-8, -24, 16, 16);

      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawWorld();
      drawPlayer();
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 1 / 30);
      last = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    buildLevel();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

