## 2) `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
const hud = document.getElementById("hud");

const WIDTH = canvas.width;
const HEIGHT = canvas.height;

const GRAVITY = 2400;
const MOVE_SPEED = 340;
const JUMP_VELOCITY = 780;
const FRICTION = 0.82;
const AIR_FRICTION = 0.96;
const MAX_FALL_SPEED = 1200;

const keys = {
  left: false,
  right: false,
  jump: false,
  jumpPressed: false
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") {
    if (!keys.jump) keys.jumpPressed = true;
    keys.jump = true;
  }
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") {
    keys.jump = false;
  }
});

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function rectsIntersect(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

class Platform {
  constructor(x, y, w, h, color = "#3c8f3c") {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.color = color;
  }
  draw(camera) {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x - camera.x, this.y - camera.y, this.w, this.h);
    ctx.fillStyle = "rgba(255,255,255,0.12)";
    ctx.fillRect(this.x - camera.x, this.y - camera.y, this.w, 6);
  }
}

class Coin {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.r = 10;
    this.t = 0;
    this.collected = false;
  }
  get hitbox() {
    return { x: this.x - this.r, y: this.y - this.r, w: this.r * 2, h: this.r * 2 };
  }
  update(dt) {
    this.t += dt * 8;
  }
  draw(camera) {
    if (this.collected) return;
    const bob = Math.sin(this.t) * 4;
    ctx.beginPath();
    ctx.fillStyle = "#ffd84d";
    ctx.arc(this.x - camera.x, this.y - camera.y + bob, this.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = "#c99b00";
    ctx.lineWidth = 3;
    ctx.stroke();
  }
}

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 34;
    this.h = 28;
    this.vx = -90;
    this.vy = 0;
    this.alive = true;
    this.onGround = false;
  }
  get hitbox() {
    return { x: this.x, y: this.y, w: this.w, h: this.h };
  }
  update(dt, platforms) {
    if (!this.alive) return;

    this.vy += GRAVITY * dt;
    this.vy = Math.min(this.vy, MAX_FALL_SPEED);

    this.x += this.vx * dt;
    for (const p of platforms) {
      if (rectsIntersect(this.hitbox, p)) {
        if (this.vx > 0) this.x = p.x - this.w;
        else this.x = p.x + p.w;
        this.vx *= -1;
      }
    }

    this.y += this.vy * dt;
    this.onGround = false;
    for (const p of platforms) {
      if (rectsIntersect(this.hitbox, p)) {
        if (this.vy > 0) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
      }
    }

    // turn around at edges a bit by checking if no ground ahead
    const footX = this.vx > 0 ? this.x + this.w + 2 : this.x - 2;
    const footY = this.y + this.h + 2;
    let hasGroundAhead = false;
    for (const p of platforms) {
      if (footX >= p.x && footX <= p.x + p.w && footY >= p.y && footY <= p.y + p.h) {
        hasGroundAhead = true;
        break;
      }
    }
    if (this.onGround && !hasGroundAhead) this.vx *= -1;
  }
  draw(camera, frame) {
    if (!this.alive) return;
    const x = this.x - camera.x;
    const y = this.y - camera.y;

    ctx.fillStyle = "#8b4d2c";
    ctx.fillRect(x, y, this.w, this.h);

    // eyes
    ctx.fillStyle = "#fff";
    ctx.fillRect(x + 8, y + 7, 6, 6);
    ctx.fillRect(x + 20, y + 7, 6, 6);

    ctx.fillStyle = "#000";
    ctx.fillRect(x + 10, y + 9, 2, 2);
    ctx.fillRect(x + 22, y + 9, 2, 2);

    // feet animation
    ctx.fillStyle = "#5f331d";
    const footOffset = (Math.floor(frame / 10) % 2) * 4;
    ctx.fillRect(x + 5 + footOffset, y + this.h - 4, 8, 4);
    ctx.fillRect(x + 21 - footOffset, y + this.h - 4, 8, 4);
  }
}

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 30;
    this.h = 44;
    this.vx = 0;
    this.vy = 0;
    this.onGround = false;
    this.facing = 1;
    this.coins = 0;
    this.lives = 3;
    this.animTime = 0;
    this.spawnX = x;
    this.spawnY = y;
  }

  get hitbox() {
    return { x: this.x, y: this.y, w: this.w, h: this.h };
  }

  respawn() {
    this.x = this.spawnX;
    this.y = this.spawnY;
    this.vx = 0;
    this.vy = 0;
  }

  update(dt, platforms) {
    this.animTime += dt;

    // horizontal input
    let move = 0;
    if (keys.left) move -= 1;
    if (keys.right) move += 1;

    if (move !== 0) this.facing = move;

    this.vx += move * MOVE_SPEED * 8 * dt;
    this.vx = clamp(this.vx, -MOVE_SPEED, MOVE_SPEED);

    if (this.onGround) this.vx *= FRICTION;
    else this.vx *= AIR_FRICTION;

    // jump
    if (keys.jumpPressed && this.onGround) {
      this.vy = -JUMP_VELOCITY;
      this.onGround = false;
    }
    keys.jumpPressed = false;

    // gravity
    this.vy += GRAVITY * dt;
    this.vy = Math.min(this.vy, MAX_FALL_SPEED);

    // move & collide X
    this.x += this.vx * dt;
    for (const p of platforms) {
      if (rectsIntersect(this.hitbox, p)) {
        if (this.vx > 0) this.x = p.x - this.w;
        else if (this.vx < 0) this.x = p.x + p.w;
        this.vx = 0;
      }
    }

    // move & collide Y
    this.y += this.vy * dt;
    this.onGround = false;
    for (const p of platforms) {
      if (rectsIntersect(this.hitbox, p)) {
        if (this.vy > 0) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
      }
    }

    // fall off world
    if (this.y > worldHeight + 300) {
      this.lives--;
      this.respawn();
    }
  }

  draw(camera) {
    const x = this.x - camera.x;
    const y = this.y - camera.y;

    const frame = Math.floor(this.animTime * 12) % 4;
    const walking = Math.abs(this.vx) > 25 && this.onGround;
    const legSwing = walking ? (frame % 2 === 0 ? 4 : -4) : 0;

    // body
    ctx.fillStyle = "#2d6cdf";
    ctx.fillRect(x, y + 10, this.w, this.h - 10);

    // head
    ctx.fillStyle = "#f2c38b";
    ctx.fillRect(x + 4, y, this.w - 8, 16);

    // eyes
    ctx.fillStyle = "#000";
    const eyeX = this.facing > 0 ? x + 18 : x + 10;
    ctx.fillRect(eyeX, y + 5, 3, 3);

    // arms
    ctx.fillStyle = "#1f4f9d";
    ctx.fillRect(x - 4, y + 16, 8, 12);
    ctx.fillRect(x + this.w - 4, y + 16, 8, 12);

    // legs
    ctx.fillStyle = "#163b76";
    ctx.fillRect(x + 6 + legSwing, y + this.h - 10, 8, 10);
    ctx.fillRect(x + 16 - legSwing, y + this.h - 10, 8, 10);

    // outline
    ctx.strokeStyle = "rgba(0,0,0,0.25)";
    ctx.strokeRect(x, y, this.w, this.h);
  }
}

// World
const platforms = [];
const coins = [];
const enemies = [];

const worldWidth = 3600;
const worldHeight = 1200;

function addLevel() {
  // ground
  platforms.push(new Platform(0, 500, 500, 40));
  platforms.push(new Platform(560, 500, 420, 40));
  platforms.push(new Platform(1040, 500, 460, 40));
  platforms.push(new Platform(1560, 500, 420, 40));
  platforms.push(new Platform(2060, 500, 620, 40));
  platforms.push(new Platform(2780, 500, 620, 40));

  // elevated platforms
  platforms.push(new Platform(160, 390, 160, 24, "#2f7d32"));
  platforms.push(new Platform(380, 320, 120, 24, "#2f7d32"));
  platforms.push(new Platform(760, 370, 160, 24, "#2f7d32"));
  platforms.push(new Platform(1180, 340, 160, 24, "#2f7d32"));
  platforms.push(new Platform(1800, 360, 180, 24, "#2f7d32"));
  platforms.push(new Platform(2350, 310, 180, 24, "#2f7d32"));
  platforms.push(new Platform(3000, 360, 180, 24, "#2f7d32"));

  // floating steps
  platforms.push(new Platform(520, 430, 60, 20, "#4da34d"));
  platforms.push(new Platform(600, 380, 60, 20, "#4da34d"));
  platforms.push(new Platform(680, 330, 60, 20, "#4da34d"));

  // coins
  [
    [200, 350], [420, 280], [820, 330], [1200, 300],
    [1700, 460], [1880, 320], [2420, 270], [3080, 330]
  ].forEach(([x, y]) => coins.push(new Coin(x, y)));

  // enemies
  enemies.push(new Enemy(650, 472));
  enemies.push(new Enemy(1120, 472));
  enemies.push(new Enemy(2240, 472));
}

addLevel();

const player = new Player(80, 420);

const camera = { x: 0, y: 0 };

function updateCamera() {
  camera.x = clamp(player.x + player.w / 2 - WIDTH / 2, 0, worldWidth - WIDTH);
  camera.y = 0;
}

function drawBackground() {
  // distant hills / parallax
  const parallax = camera.x * 0.25;
  ctx.fillStyle = "#7bc96f";
  for (let i = -1; i < 8; i++) {
    const x = i * 260 - (parallax % 260);
    ctx.beginPath();
    ctx.ellipse(x + 130, 490, 180, 90, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // clouds
  ctx.fillStyle = "rgba(255,255,255,0.8)";
  const cloudOffset = camera.x * 0.15;
  for (let i = 0; i < 6; i++) {
    const cx = (i * 300 + 120 - cloudOffset) % (worldWidth + 300) - 100;
    const cy = 70 + (i % 3) * 40;
    ctx.beginPath();
    ctx.arc(cx, cy, 25, 0, Math.PI * 2);
    ctx.arc(cx + 24, cy + 8, 30, 0, Math.PI * 2);
    ctx.arc(cx + 50, cy, 22, 0, Math.PI * 2);
    ctx.fill();
  }
}

function update(dt) {
  player.update(dt, platforms);

  for (const c of coins) {
    c.update(dt);
    if (!c.collected && rectsIntersect(player.hitbox, c.hitbox)) {
      c.collected = true;
      player.coins++;
    }
  }

  for (const e of enemies) {
    e.update(dt, platforms);
    if (!e.alive) continue;

    if (rectsIntersect(player.hitbox, e.hitbox)) {
      const playerBottom = player.y + player.h;
      const enemyTop = e.y;

      // stomping
      if (player.vy > 0 && playerBottom - enemyTop < 18) {
        e.alive = false;
        player.vy = -JUMP_VELOCITY * 0.55;
      } else {
        player.lives--;
        player.respawn();
      }
    }
  }

  updateCamera();
  hud.textContent = `Coins: ${player.coins} | Lives: ${player.lives}`;
}

function draw() {
  ctx.clearRect(0, 0, WIDTH, HEIGHT);

  drawBackground();

  // platforms
  for (const p of platforms) p.draw(camera);

  // coins
  for (const c of coins) c.draw(camera);

  // enemies
  const frame = performance.now() / 16;
  for (const e of enemies) e.draw(camera, frame);

  // player
  player.draw(camera);

  // UI
  if (player.lives <= 0) {
    ctx.fillStyle = "rgba(0,0,0,0.6)";
    ctx.fillRect(0, 0, WIDTH, HEIGHT);
    ctx.fillStyle = "#fff";
    ctx.font = "48px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("Game Over", WIDTH / 2, HEIGHT / 2);
    ctx.font = "24px sans-serif";
    ctx.fillText("Refresh to restart", WIDTH / 2, HEIGHT / 2 + 40);
  }
}

let last = performance.now();
function loop(now) {
  const dt = Math.min((now - last) / 1000, 1 / 30);
  last = now;

  if (player.lives > 0) update(dt);
  draw();

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
