<body>
  <div id="hud">
    Move: A/D or ←/→ | Jump: W / Space / ↑
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    function down(...names) {
      return names.some(k => keys[k]);
    }

    // --- World ---
    const GRAVITY = 2200;
    const GROUND_FRICTION = 0.82;
    const AIR_FRICTION = 0.98;
    const MOVE_SPEED = 520;
    const MAX_SPEED = 320;
    const JUMP_SPEED = 820;

    const world = {
      width: 5000,
      height: 1200
    };

    const platforms = [
      { x: 0, y: 1120, w: 5000, h: 80, type: "solid" },

      { x: 250, y: 980, w: 240, h: 30, type: "solid" },
      { x: 620, y: 870, w: 220, h: 30, type: "solid" },
      { x: 960, y: 780, w: 260, h: 30, type: "solid" },
      { x: 1360, y: 680, w: 220, h: 30, type: "solid" },
      { x: 1680, y: 590, w: 260, h: 30, type: "solid" },
      { x: 2060, y: 760, w: 240, h: 30, type: "solid" },
      { x: 2420, y: 860, w: 260, h: 30, type: "solid" },
      { x: 2810, y: 740, w: 220, h: 30, type: "solid" },
      { x: 3160, y: 620, w: 260, h: 30, type: "solid" },
      { x: 3550, y: 760, w: 240, h: 30, type: "solid" },
      { x: 3910, y: 880, w: 300, h: 30, type: "solid" },
      { x: 4300, y: 790, w: 240, h: 30, type: "solid" },
    ];

    const hazards = [
      { x: 780, y: 1090, w: 220, h: 30 },
      { x: 1910, y: 1090, w: 180, h: 30 },
      { x: 3400, y: 1090, w: 250, h: 30 },
    ];

    const goal = { x: 4700, y: 720, w: 50, h: 120 };

    // --- Player ---
    const player = {
      x: 80,
      y: 980,
      w: 46,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      animState: "idle",
      dead: false
    };

    const camera = { x: 0, y: 0 };

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function aabb(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resetPlayer() {
      player.x = 80;
      player.y = 980;
      player.vx = 0;
      player.vy = 0;
      player.dead = false;
    }

    // --- Collision resolution ---
    function resolveCollisions(obj, solids) {
      obj.onGround = false;

      for (const s of solids) {
        if (!aabb(obj, s)) continue;

        const overlapLeft = (obj.x + obj.w) - s.x;
        const overlapRight = (s.x + s.w) - obj.x;
        const overlapTop = (obj.y + obj.h) - s.y;
        const overlapBottom = (s.y + s.h) - obj.y;

        const minX = Math.min(overlapLeft, overlapRight);
        const minY = Math.min(overlapTop, overlapBottom);

        if (minX < minY) {
          if (overlapLeft < overlapRight) {
            obj.x -= overlapLeft;
          } else {
            obj.x += overlapRight;
          }
          obj.vx = 0;
        } else {
          if (overlapTop < overlapBottom) {
            obj.y -= overlapTop;
            obj.vy = 0;
            obj.onGround = true;
          } else {
            obj.y += overlapBottom;
            obj.vy = 0;
          }
        }
      }
    }

    // --- Animated sprite generation ---
    // Creates a simple 4-frame running sprite on an offscreen canvas.
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 256;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawFrame(frame, flip = false) {
      const ox = frame * 64;

      sctx.save();
      sctx.clearRect(ox, 0, 64, 64);
      sctx.translate(ox + 32, 32);
      if (flip) sctx.scale(-1, 1);

      // shadow
      sctx.fillStyle = "rgba(0,0,0,0.12)";
      sctx.beginPath();
      sctx.ellipse(0, 28, 16, 5, 0, 0, Math.PI * 2);
      sctx.fill();

      // body
      sctx.fillStyle = "#ff5d5d";
      sctx.fillRect(-12, -10, 24, 26);

      // head
      sctx.fillStyle = "#ffd7b3";
      sctx.beginPath();
      sctx.arc(0, -20, 12, 0, Math.PI * 2);
      sctx.fill();

      // eyes
      sctx.fillStyle = "#111";
      sctx.fillRect(-5, -22, 2, 2);
      sctx.fillRect(3, -22, 2, 2);

      // legs/arms by frame
      sctx.strokeStyle = "#2b2b2b";
      sctx.lineWidth = 4;
      sctx.lineCap = "round";

      // arms
      sctx.beginPath();
      sctx.moveTo(-10, 0);
      sctx.lineTo(-18, 10 + (frame % 2 ? 4 : 0));
      sctx.stroke();

      sctx.beginPath();
      sctx.moveTo(10, 0);
      sctx.lineTo(18, 10 + (frame % 2 ? 0 : 4));
      sctx.stroke();

      // legs
      const legA = frame % 2 ? 10 : 4;
      const legB = frame % 2 ? 4 : 10;

      sctx.beginPath();
      sctx.moveTo(-7, 14);
      sctx.lineTo(-12, 24 + legA);
      sctx.stroke();

      sctx.beginPath();
      sctx.moveTo(7, 14);
      sctx.lineTo(12, 24 + legB);
      sctx.stroke();

      sctx.restore();
    }

    for (let i = 0; i < 4; i++) drawFrame(i, false);

    function updateSprite(dt) {
      const moving = Math.abs(player.vx) > 20;
      if (!player.onGround) player.animState = "jump";
      else if (moving) player.animState = "run";
      else player.animState = "idle";

      player.animTime += dt;

      if (player.animState === "jump") {
        player.frame = 2;
      } else if (player.animState === "run") {
        player.frame = Math.floor(player.animTime * 12) % 4;
      } else {
        player.frame = 0;
      }
    }

    // --- Main update ---
    let last = performance.now();

    function step(now) {
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;

      if (player.dead) {
        if (down("r")) resetPlayer();
      } else {
        // Input movement
        let move = 0;
        if (down("a", "arrowleft")) move -= 1;
        if (down("d", "arrowright")) move += 1;

        if (move !== 0) player.facing = move;

        const accel = player.onGround ? 2400 : 1600;
        player.vx += move * accel * dt;

        player.vx = clamp(player.vx, -MAX_SPEED, MAX_SPEED);

        // Friction
        if (player.onGround && move === 0) {
          player.vx *= Math.pow(GROUND_FRICTION, dt * 60);
          if (Math.abs(player.vx) < 1) player.vx = 0;
        } else {
          player.vx *= Math.pow(AIR_FRICTION, dt * 60);
        }

        // Jump
        if (down("w", " ", "arrowup")) {
          if (player.onGround && !player._jumpHeld) {
            player.vy = -JUMP_SPEED;
            player.onGround = false;
          }
          player._jumpHeld = true;
        } else {
          player._jumpHeld = false;
        }

        // Apply gravity
        player.vy += GRAVITY * dt;

        // Integrate
        player.x += player.vx * dt;
        resolveCollisions(player, platforms);

        player.y += player.vy * dt;
        resolveCollisions(player, platforms);

        // Hazards
        for (const h of hazards) {
          if (aabb(player, h)) {
            player.dead = true;
          }
        }

        // Fall off map
        if (player.y > world.height + 400) player.dead = true;

        // Goal
        if (aabb(player, goal)) {
          // simple "win" reset for demo
          alert("You win!");
          resetPlayer();
        }

        updateSprite(dt);
      }

      // Camera follow
      camera.x = clamp(player.x + player.w / 2 - canvas.width / 2, 0, world.width - canvas.width);
      camera.y = clamp(player.y + player.h / 2 - canvas.height / 2, 0, world.height - canvas.height);

      draw();
      requestAnimationFrame(step);
    }

    // --- Render ---
    function drawPlatform(p, color = "#4b5563") {
      ctx.fillStyle = color;
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
      ctx.fillStyle = "rgba(255,255,255,0.12)";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // background hills
      for (let i = 0; i < 12; i++) {
        const x = (i * 420 - camera.x * 0.3) % (canvas.width + 500) - 250;
        const y = canvas.height - 120 + Math.sin(i * 1.4) * 14;
        ctx.fillStyle = "rgba(40,120,60,0.18)";
        ctx.beginPath();
        ctx.ellipse(x, y, 150, 60, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // platforms
      for (const p of platforms) drawPlatform(p);

      // hazards
      for (const h of hazards) {
        ctx.fillStyle = "#f43f5e";
        ctx.fillRect(h.x - camera.x, h.y - camera.y, h.w, h.h);
        ctx.fillStyle = "#fff";
        ctx.fillRect(h.x - camera.x + 8, h.y - camera.y + 6, h.w - 16, 4);
      }

      // goal
      ctx.fillStyle = "#facc15";
      ctx.fillRect(goal.x - camera.x, goal.y - camera.y, goal.w, goal.h);
      ctx.fillStyle = "#fff";
      ctx.fillRect(goal.x - camera.x + 10, goal.y - camera.y + 15, 15, 15);

      // player sprite
      ctx.save();
      ctx.translate(player.x - camera.x + player.w / 2, player.y - camera.y + player.h / 2);
      ctx.scale(player.facing, 1);

      const frameX = (player.frame || 0) * 64;
      if (player.animState === "jump") {
        // use frame 2 for jump
        ctx.drawImage(spriteCanvas, 2 * 64, 0, 64, 64, -32, -32, 64, 64);
      } else {
        ctx.drawImage(spriteCanvas, frameX, 0, 64, 64, -32, -32, 64, 64);
      }
      ctx.restore();

      // death overlay
      if (player.dead) {
        ctx.fillStyle = "rgba(0,0,0,0.45)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "white";
        ctx.font = "bold 42px Arial";
        ctx.textAlign = "center";
        ctx.fillText("You Died", canvas.width / 2, canvas.height / 2);
        ctx.font = "20px Arial";
        ctx.fillText("Press R to Respawn", canvas.width / 2, canvas.height / 2 + 40);
      }
    }

    requestAnimationFrame(step);
  </script>
</body>
</html>
