```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 16px;
      text-shadow: 1px 1px 2px black;
      z-index: 10;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or Arrow Keys | Jump: Space/W/Up
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.key === "ArrowLeft" || e.key === "a" || e.key === "A") keys.left = true;
      if (e.key === "ArrowRight" || e.key === "d" || e.key === "D") keys.right = true;
      if (e.key === " " || e.key === "ArrowUp" || e.key === "w" || e.key === "W") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.key === "ArrowLeft" || e.key === "a" || e.key === "A") keys.left = false;
      if (e.key === "ArrowRight" || e.key === "d" || e.key === "D") keys.right = false;
      if (e.key === " " || e.key === "ArrowUp" || e.key === "w" || e.key === "W") keys.jump = false;
    });

    // --- World setup ---
    const GRAVITY = 0.7;
    const TILE = 48;

    const world = {
      width: 3000,
      height: 1200,
      platforms: [
        // Ground
        { x: 0, y: 1100, w: 3000, h: 100 },

        // Floating platforms
        { x: 200, y: 900, w: 200, h: 30 },
        { x: 500, y: 800, w: 160, h: 30 },
        { x: 780, y: 700, w: 220, h: 30 },
        { x: 1100, y: 850, w: 180, h: 30 },
        { x: 1450, y: 750, w: 200, h: 30 },
        { x: 1750, y: 620, w: 220, h: 30 },
        { x: 2150, y: 800, w: 200, h: 30 },
        { x: 2500, y: 700, w: 240, h: 30 },
      ]
    };

    // --- Sprite animation frames generated on canvas ---
    function createFrame(color, accent) {
      const c = document.createElement("canvas");
      c.width = 32;
      c.height = 32;
      const g = c.getContext("2d");

      // body
      g.fillStyle = color;
      g.fillRect(8, 6, 16, 20);

      // head
      g.fillStyle = "#ffd7b5";
      g.fillRect(10, 2, 12, 8);

      // eyes
      g.fillStyle = "#000";
      g.fillRect(12, 5, 2, 2);
      g.fillRect(18, 5, 2, 2);

      // accent / arms / legs vary slightly
      g.fillStyle = accent;
      g.fillRect(6, 10, 4, 10);  // left arm
      g.fillRect(22, 10, 4, 10); // right arm
      g.fillRect(10, 24, 4, 6);  // left leg
      g.fillRect(18, 24, 4, 6);  // right leg

      return c;
    }

    const spriteFrames = [
      createFrame("#ff4d4d", "#222"),
      createFrame("#ff6666", "#222"),
      createFrame("#ff4d4d", "#444"),
      createFrame("#ff6666", "#444")
    ];

    // --- Player ---
    const player = {
      x: 100,
      y: 900,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      speed: 0.7,
      maxSpeed: 7,
      jumpPower: 14,
      grounded: false,
      facing: 1,
      frame: 0,
      frameTimer: 0
    };

    // --- Collision helper ---
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolvePlatformCollision(entity, platform) {
      const prevX = entity.x - entity.vx;
      const prevY = entity.y - entity.vy;

      const fromLeft = prevX + entity.w <= platform.x;
      const fromRight = prevX >= platform.x + platform.w;
      const fromTop = prevY + entity.h <= platform.y;
      const fromBottom = prevY >= platform.y + platform.h;

      if (fromTop) {
        entity.y = platform.y - entity.h;
        entity.vy = 0;
        entity.grounded = true;
      } else if (fromBottom) {
        entity.y = platform.y + platform.h;
        entity.vy = 0;
      } else if (fromLeft) {
        entity.x = platform.x - entity.w;
        entity.vx = 0;
      } else if (fromRight) {
        entity.x = platform.x + platform.w;
        entity.vx = 0;
      }
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    // --- Input/physics update ---
    function updatePlayer() {
      // Horizontal movement
      if (keys.left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (keys.right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Clamp speed
      player.vx = Math.max(-player.maxSpeed, Math.min(player.vx, player.maxSpeed));

      // Friction
      if (!keys.left && !keys.right) {
        player.vx *= 0.82;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      // Jump
      if (keys.jump && player.grounded) {
        player.vy = -player.jumpPower;
        player.grounded = false;
      }

      // Gravity
      player.vy += GRAVITY;
      if (player.vy > 20) player.vy = 20;

      // Move
      player.x += player.vx;
      player.y += player.vy;

      // World bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > world.width) {
        player.x = world.width - player.w;
        player.vx = 0;
      }
      if (player.y > world.height) {
        player.y = world.height - player.h;
        player.vy = 0;
      }

      // Collision detection
      player.grounded = false;
      const playerRect = { x: player.x, y: player.y, w: player.w, h: player.h };

      for (const platform of world.platforms) {
        if (rectsOverlap(playerRect, platform)) {
          resolvePlatformCollision(player, platform);
          playerRect.x = player.x;
          playerRect.y = player.y;
        }
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.2;
      if (moving) {
        player.frameTimer++;
        if (player.frameTimer >= 8) {
          player.frame = (player.frame + 1) % spriteFrames.length;
          player.frameTimer = 0;
        }
      } else {
        player.frame = 0;
        player.frameTimer = 0;
      }
    }

    // --- Render ---
    function drawBackground() {
      // Parallax style hills
      ctx.save();
      ctx.translate(-camera.x * 0.2, -camera.y * 0.2);

      ctx.fillStyle = "#7ec850";
      for (let i = 0; i < 12; i++) {
        ctx.beginPath();
        ctx.ellipse(i * 280 + 100, 1000, 180, 80, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    }

    function drawPlatforms() {
      ctx.fillStyle = "#5a3d2b";
      for (const p of world.platforms) {
        const x = p.x - camera.x;
        const y = p.y - camera.y;

        ctx.fillStyle = "#4d3324";
        ctx.fillRect(x, y, p.w, p.h);

        ctx.fillStyle = "#7a553d";
        ctx.fillRect(x, y, p.w, 8);
      }
    }

    function drawPlayer() {
      const frameImg = spriteFrames[player.frame];
      ctx.save();

      const drawX = player.x - camera.x;
      const drawY = player.y - camera.y;

      if (player.facing === -1) {
        ctx.translate(drawX + player.w, drawY);
        ctx.scale(-1, 1);
        ctx.drawImage(frameImg, 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(frameImg, drawX, drawY, player.w, player.h);
      }

      ctx.restore();
    }

    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, 10, 180, 48);
      ctx.fillStyle = "#fff";
      ctx.font = "14px sans-serif";
      ctx.fillText("2D Platformer Demo", 20, 30);
      ctx.fillText(`X: ${Math.floor(player.x)} Y: ${Math.floor(player.y)}`, 20, 48);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // World transform
      ctx.save();
      ctx.translate(-camera.x, -camera.y);
      drawPlatforms();
      ctx.restore();

      drawPlayer();
      drawHUD();
    }

    // --- Game loop ---
    function gameLoop() {
      updatePlayer();
      updateCamera();
      render();
      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
