    const gravity = 0.7;

    const levels = {
      width: 3000,
      height: 1000,
      platforms: [
        { x: 0, y: 920, w: 3000, h: 80 },
        { x: 200, y: 780, w: 200, h: 20 },
        { x: 500, y: 680, w: 220, h: 20 },
        { x: 860, y: 600, w: 180, h: 20 },
        { x: 1120, y: 720, w: 220, h: 20 },
        { x: 1450, y: 620, w: 180, h: 20 },
        { x: 1750, y: 540, w: 200, h: 20 },
        { x: 2050, y: 700, w: 240, h: 20 },
        { x: 2450, y: 610, w: 220, h: 20 },
      ]
    };

