    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 192;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawSpriteFrame(frameX, colorBody, colorTrim, legOffset = 0, armOffset = 0) {
      const ox = frameX * 64;

      // transparent background
      sctx.clearRect(ox, 0, 64, 64);

      // head
      sctx.fillStyle = "#f2c9a0";
      sctx.fillRect(ox + 22, 8, 20, 18);

      // body
      sctx.fillStyle = colorBody;
      sctx.fillRect(ox + 18, 26, 28, 22);

      // trim
      sctx.fillStyle = colorTrim;
      sctx.fillRect(ox + 18, 26, 28, 5);

      // arms
      sctx.fillStyle = "#f2c9a0";
      sctx.fillRect(ox + 12, 28 + armOffset, 6, 18);
      sctx.fillRect(ox + 46, 28 - armOffset, 6, 18);

      // legs
      sctx.fillStyle = "#3a3f52";
      sctx.fillRect(ox + 20, 48, 8, 14 + legOffset);
      sctx.fillRect(ox + 36, 48, 8, 14 - legOffset);

      // boots
      sctx.fillStyle = "#111";
      sctx.fillRect(ox + 18, 58, 12, 4);
      sctx.fillRect(ox + 34, 58, 12, 4);

      // eyes
      sctx.fillStyle = "#222";
      sctx.fillRect(ox + 26, 14, 3, 3);
      sctx.fillRect(ox + 34, 14, 3, 3);
    }

    // 0 idle, 1 walk1, 2 walk2
    drawSpriteFrame(0, "#7c4dff", "#5e35b1", 0, 0);
    drawSpriteFrame(1, "#7c4dff", "#5e35b1", 2, -2);
    drawSpriteFrame(2, "#7c4dff", "#5e35b1", -2, 2);

    // ----------------------------
    // Helpers
    // ----------------------------
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, platforms) {
      entity.onGround = false;

      // Horizontal collision
      entity.x += entity.vx;
      for (const p of platforms) {
        if (rectsOverlap(entity, p)) {
          if (entity.vx > 0) {
            entity.x = p.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = p.x + p.w;
          }
          entity.vx = 0;
        }
      }

      // Vertical collision
      entity.y += entity.vy;
      for (const p of platforms) {
        if (rectsOverlap(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    // ----------------------------
    // Camera
    // ----------------------------
    const camera = {
      x: 0,
      y: 0
    };

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(camera.x, levels.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, levels.height - canvas.height));
    }

    // ----------------------------
    // Update
    // ----------------------------
    let jumpPressedLastFrame = false;

    function update() {
      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Clamp horizontal speed
      if (player.vx > player.maxSpeed) player.vx = player.maxSpeed;
      if (player.vx < -player.maxSpeed) player.vx = -player.maxSpeed;

      // Friction
      if (!left && !right) {
        player.vx *= player.onGround ? 0.82 : 0.98;
      }

      // Jump on key press edge
      if (jump && !jumpPressedLastFrame && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }
      jumpPressedLastFrame = jump;

      // Gravity
      player.vy += gravity;
      if (player.vy > 20) player.vy = 20;

      // Move and collide
      resolveCollisions(player, levels.platforms);

      // World bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > levels.width) {
        player.x = levels.width - player.w;
        player.vx = 0;
      }
      if (player.y > levels.height + 200) {
        // respawn
        player.x = 100;
        player.y = 400;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
        player.animFrame = 0;
      } else if (Math.abs(player.vx) > 0.7) {
        player.state = "run";
        player.animTimer += 0.18;
        player.animFrame = Math.floor(player.animTimer) % 2 + 1;
      } else {
        player.state = "idle";
        player.animFrame = 0;
        player.animTimer = 0;
      }

      updateCamera();
    }

    // ----------------------------
    // Draw
    // ----------------------------
    function drawBackground() {
      // sky gradient already in canvas css; add clouds/parallax simple
      ctx.save();
      ctx.translate(-camera.x * 0.2, -camera.y * 0.1);

      ctx.fillStyle = "rgba(255,255,255,0.35)";
      for (let i = 0; i < 10; i++) {
        const x = i * 350 + 120;
        const y = 80 + (i % 3) * 60;
        ctx.beginPath();
        ctx.ellipse(x, y, 50, 22, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 35, y + 5, 45, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(x - 35, y + 8, 40, 16, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of levels.platforms) {
        const x = p.x - camera.x;
        const y = p.y - camera.y;

        // platform base
        ctx.fillStyle = "#4e8f3d";
        ctx.fillRect(x, y, p.w, p.h);

        // top grass edge
        ctx.fillStyle = "#6ecb63";
        ctx.fillRect(x, y, p.w, 6);

        // shadow
        ctx.fillStyle = "rgba(0,0,0,0.15)";
        ctx.fillRect(x, y + p.h - 6, p.w, 6);
      }
    }

    function drawPlayer() {
      const frame = player.animFrame;
      const sx = frame * 64;
      const sy = 0;

      const dx = Math.floor(player.x - camera.x);
      const dy = Math.floor(player.y - camera.y);

      ctx.save();

      // flip based on facing
      if (player.facing === -1) {
        ctx.translate(dx + player.w, dy);
        ctx.scale(-1, 1);
      } else {
        ctx.translate(dx, dy);
      }

      // draw sprite centered within player box
      ctx.drawImage(
        spriteCanvas,
        sx, sy, 64, 64,
        0, 0, player.w, player.h
      );

      ctx.restore();
    }

    function drawDebug() {
      ctx.fillStyle = "rgba(0,0,0,0.3)";
      ctx.fillRect(10, canvas.height - 50, 220, 40);
      ctx.fillStyle = "white";
      ctx.font = "14px monospace";
      ctx.fillText(`x: ${player.x.toFixed(1)}  y: ${player.y.toFixed(1)}`, 20, canvas.height - 24);
      ctx.fillText(`vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 20, canvas.height - 8);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      drawPlatforms();
      drawPlayer();
      drawDebug();
    }

    // ----------------------------
    // Main loop
    // ----------------------------
    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
