    };

    // --- Create a simple sprite sheet in memory ---
    const spriteSheet = document.createElement("canvas");
    spriteSheet.width = 192;
    spriteSheet.height = 64;
    const sctx = spriteSheet.getContext("2d");

    function drawFrame(frameIndex) {
      const x = frameIndex * 48;
      sctx.clearRect(x, 0, 48, 64);

      // body
      sctx.fillStyle = "#ffcc66";
      sctx.fillRect(x + 14, 14, 20, 30);

      // head
      sctx.fillStyle = "#ffd8a6";
      sctx.fillRect(x + 16, 4, 16, 14);

      // eyes
      sctx.fillStyle = "#222";
      sctx.fillRect(x + 20, 8, 2, 2);
      sctx.fillRect(x + 26, 8, 2, 2);

      // legs animated
      sctx.fillStyle = "#3b5bdb";
      if (frameIndex === 0) {
        sctx.fillRect(x + 14, 44, 8, 14);
        sctx.fillRect(x + 26, 44, 8, 14);
      } else if (frameIndex === 1) {
        sctx.fillRect(x + 12, 44, 10, 14);
        sctx.fillRect(x + 26, 44, 10, 14);
      } else if (frameIndex === 2) {
        sctx.fillRect(x + 14, 44, 8, 14);
        sctx.fillRect(x + 28, 44, 8, 14);
      } else {
        sctx.fillRect(x + 12, 44, 8, 14);
        sctx.fillRect(x + 28, 44, 8, 14);
      }

      // arms
      sctx.fillStyle = "#ffd8a6";
      sctx.fillRect(x + 8, 18, 6, 18);
      sctx.fillRect(x + 34, 18, 6, 18);
    }

    for (let i = 0; i < 4; i++) drawFrame(i);

    // --- Collision ---
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // Horizontal
      entity.x += entity.vx * dt;
      for (const p of solids) {
        if (rectsOverlap(entity, p)) {
          if (entity.vx > 0) {
            entity.x = p.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = p.x + p.w;
          }
          entity.vx = 0;
        }
      }

      // Vertical
      entity.y += entity.vy * dt;
      for (const p of solids) {
        if (rectsOverlap(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    // --- Game Loop ---
    let last = 0;
    let dt = 0;

    function update(timestamp) {
      dt = Math.min(0.033, (timestamp - last) / 1000 || 0);
      last = timestamp;

      // Input movement
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      player.vx = move * player.speed;
      if (move !== 0) player.facing = move;

      // Jump
      const wantsJump = keys[" "] || keys["w"] || keys["arrowup"];
      if (wantsJump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Gravity
      player.vy += gravity * dt;
      if (player.vy > 1400) player.vy = 1400;

