      resolveCollisions(player, platforms);

      // Coin collection
      for (const coin of coins) {
        if (!coin.taken) {
          const coinBox = { x: coin.x - 12, y: coin.y - 12, w: 24, h: 24 };
          if (rectsOverlap(player, coinBox)) {
            coin.taken = true;
            player.coins++;
          }
        }
      }

      // Animation
      if (Math.abs(player.vx) > 1 && player.onGround) {
        player.animTime += dt * 10;
        player.frame = Math.floor(player.animTime) % 4;
      } else {
        player.frame = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      // Clamp to world
      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));

      render();
      requestAnimationFrame(update);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background decorations
      ctx.fillStyle = "rgba(255,255,255,0.25)";
      for (let i = 0; i < 20; i++) {
        const x = ((i * 180) - (camera.x * 0.3)) % (canvas.width + 250) - 100;
        const y = 80 + (i % 5) * 50;
        ctx.beginPath();
        ctx.ellipse(x, y, 50, 20, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // Draw platforms
      for (const p of platforms) {
        ctx.fillStyle = "#4a3f35";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#6b5b4e";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // Draw coins
      for (const coin of coins) {
        if (!coin.taken) {
          ctx.fillStyle = "#ffd700";
          ctx.beginPath();
          ctx.arc(coin.x, coin.y, 12, 0, Math.PI * 2);
          ctx.fill();
          ctx.strokeStyle = "#b8860b";
          ctx.lineWidth = 3;
          ctx.stroke();
        }
      }

      // Draw player sprite
      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y);
      ctx.scale(player.facing, 1);
      ctx.drawImage(
        spriteSheet,
        player.frame * 48, 0, 48, 64,
        -player.w / 2, 0, player.w, player.h
      );
      ctx.restore();

      ctx.restore();

      // HUD
      ctx.fillStyle = "white";
      ctx.font = "20px sans-serif";
      ctx.fillText(`Coins: ${player.coins}/${coins.length}`, 20, 40);

      // Win message
      if (player.coins === coins.length) {
        ctx.fillStyle = "rgba(0,0,0,0.6)";
        ctx.fillRect(canvas.width / 2 - 180, canvas.height / 2 - 60, 360, 120);
        ctx.fillStyle = "white";
        ctx.font = "28px sans-serif";
        ctx.fillText("You collected all coins!", canvas.width / 2 - 150, canvas.height / 2);
      }
    }

    requestAnimationFrame(update);
  </script>
