        for (const p of platforms) {
          if (rectsCollide(enemy, p)) {
            if (enemy.vy > 0 && enemy.y + enemy.h - enemy.vy <= p.y + 1) {
              enemy.y = p.y - enemy.h;
              enemy.vy = 0;
              onPlatform = true;
            } else if (enemy.vx > 0) {
              enemy.x = p.x - enemy.w;
              enemy.vx *= -1;
            } else if (enemy.vx < 0) {
              enemy.x = p.x + p.w;
              enemy.vx *= -1;
            }
          }
        }

        if (!onPlatform) {
          // if walking off platform edge, keep falling
        }

        if (enemy.x < enemy.patrolMin) enemy.vx = Math.abs(enemy.vx);
        if (enemy.x > enemy.patrolMax) enemy.vx = -Math.abs(enemy.vx);

        // player collision
        if (rectsCollide(player, enemy)) {
          if (player.vy > 0 && player.y + player.h - player.vy < enemy.y + 10) {
            // stomp enemy
            enemy.alive = false;
            player.vy = -10;
          } else if (player.hitTimer <= 0) {
            hurtPlayer();
          }
        }
      }

      // goal
      if (rectsCollide(player, goal)) {
        player.dead = true;
        setTimeout(() => {
          alert("You win!");
          resetGame();
        }, 50);
      }

      // camera follow
      camera.x = clamp(player.x + player.w / 2 - canvas.width / 2, 0, world.width - canvas.width);
      camera.y = clamp(player.y + player.h / 2 - canvas.height / 2, 0, world.height - canvas.height);

      hud.textContent = `Coins: ${player.coins} | Lives: ${player.lives}`;
    }

    function resolveCollisions(axis) {
      for (const p of platforms) {
        if (rectsCollide(player, p)) {
          if (axis === "x") {
            if (player.vx > 0) player.x = p.x - player.w;
            else if (player.vx < 0) player.x = p.x + p.w;
            player.vx = 0;
          } else {
            if (player.vy > 0) {
              player.y = p.y - player.h;
              player.vy = 0;
              player.onGround = true;
            } else if (player.vy < 0) {
              player.y = p.y + p.h;
              player.vy = 0;
            }
          }
        }
      }
    }

    function hurtPlayer() {
      if (player.hitTimer > 0) return;
      player.lives--;
      player.hitTimer = 90;
      player.x = 100;
      player.y = 300;
      player.vx = 0;
      player.vy = 0;

      if (player.lives <= 0) {
        player.dead = true;
        setTimeout(() => {
          alert("Game over!");
          resetGame();
        }, 50);
      }
    }

    function resetGame() {
      player.x = 100;
      player.y = 300;
      player.vx = 0;
      player.vy = 0;
      player.lives = 3;
      player.coins = 0;
      player.dead = false;
      player.hitTimer = 0;

      for (const c of coins) c.collected = false;
      for (const e of enemies) e.alive = true;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function drawBackground() {
      // parallax hills
      ctx.fillStyle = "#8fe388";
      ctx.fillRect(0, 430, canvas.width, 110);

      ctx.fillStyle = "#74c96a";
      for (let i = 0; i < 8; i++) {
        const x = ((i * 260) - camera.x * 0.3) % (canvas.width + 260) - 60;
        ctx.beginPath();
        ctx.arc(x, 460, 90, Math.PI, 0);
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.75)";
      for (let i = 0; i < 6; i++) {
        const x = ((i * 360) - camera.x * 0.15) % (canvas.width + 360) - 100;
        const y = 50 + (i % 3) * 40;
        drawCloud(x, y, 1 + (i % 2) * 0.3);
      }
    }

    function drawCloud(x, y, s) {
      ctx.beginPath();
      ctx.arc(x, y, 20*s, 0, Math.PI * 2);
      ctx.arc(x + 20*s, y - 10*s, 26*s, 0, Math.PI * 2);
      ctx.arc(x + 45*s, y, 18*s, 0, Math.PI * 2);
      ctx.arc(x + 22*s, y + 8*s, 22*s, 0, Math.PI * 2);
      ctx.fill();
    }

    function drawWorld() {
      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // goal flag
      ctx.fillStyle = "#6b4b2a";
      ctx.fillRect(goal.x + 16, goal.y, 8, goal.h);
      ctx.fillStyle = "#ff4d4d";
      ctx.beginPath();
      ctx.moveTo(goal.x + 24, goal.y + 20);
      ctx.lineTo(goal.x + 80, goal.y + 35);
      ctx.lineTo(goal.x + 24, goal.y + 50);
      ctx.closePath();
      ctx.fill();

      // platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5c3d2e";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#3ea34d";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }

      // coins
      for (const coin of coins) {
        if (coin.collected) continue;
        ctx.save();
        ctx.translate(coin.x, coin.y);
        ctx.fillStyle = "#ffd54a";
        ctx.beginPath();
        ctx.arc(0, 0, coin.r, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#f5b800";
        ctx.lineWidth = 3;
        ctx.stroke();
        ctx.restore();
      }

      // enemies
      for (const enemy of enemies) {
        if (!enemy.alive) continue;
        ctx.fillStyle = "#8b2d2d";
        ctx.fillRect(enemy.x, enemy.y, enemy.w, enemy.h);
        ctx.fillStyle = "#000";
        ctx.fillRect(enemy.x + 8, enemy.y + 10, 6, 6);
        ctx.fillRect(enemy.x + 22, enemy.y + 10, 6, 6);
      }

      // player sprite animation
      drawPlayerSprite();

      ctx.restore();
    }

    function drawPlayerSprite() {
      const x = player.x;
      const y = player.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);

      if (player.facing < 0) ctx.scale(-1, 1);

      const blink = player.hitTimer > 0 && Math.floor(player.hitTimer / 5) % 2 === 0;
      ctx.globalAlpha = blink ? 0.4 : 1;

      // body animation frames
      const frame = player.animFrame;

      // legs
      ctx.strokeStyle = "#2e2e2e";
      ctx.lineWidth = 5;
      ctx.lineCap = "round";
      const legSwing = player.onGround ? Math.sin(frame * 1.2) * 6 : 0;

      ctx.beginPath();
      ctx.moveTo(-8, 16);
      ctx.lineTo(-10 - legSwing * 0.2, 28);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(8, 16);
      ctx.lineTo(10 + legSwing * 0.2, 28);
      ctx.stroke();

      // torso
      ctx.fillStyle = "#3d7cff";
      ctx.fillRect(-14, -2, 28, 20);

      // head
      ctx.fillStyle = "#ffd8b0";
      ctx.beginPath();
      ctx.arc(0, -18, 14, 0, Math.PI * 2);
      ctx.fill();

      // hat/hair
      ctx.fillStyle = "#2b1b10";
      ctx.fillRect(-12, -28, 24, 8);

      // eyes
      ctx.fillStyle = "#111";
      ctx.fillRect(-6, -20, 3, 3);
      ctx.fillRect(3, -20, 3, 3);

      // arms
      ctx.strokeStyle = "#ffd8b0";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-14, 4);
      ctx.lineTo(-24, 10 + Math.sin(frame) * 2);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(14, 4);
      ctx.lineTo(24, 10 - Math.sin(frame) * 2);
      ctx.stroke();

      ctx.restore();
    }

    function gameLoop() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      updatePlayer();
      drawWorld();

      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
