```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      overflow: hidden;
      background: #1d2430;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#7ec8ff, #d7f2ff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.3);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or ←/→ &nbsp; Jump: Space/W/↑<br/>
    Reach the green flag!
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    window.addEventListener("keydown", e => {
      keys[e.key.toLowerCase()] = true;
      if ([" ", "arrowup", "w"].includes(e.key.toLowerCase())) e.preventDefault();
    });
    window.addEventListener("keyup", e => {
      keys[e.key.toLowerCase()] = false;
    });

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function createSpriteFrames() {
      const frames = [];
      const makeFrame = (legOffset, armOffset, blink) => {
        const c = document.createElement("canvas");
        c.width = 32;
        c.height = 32;
        const g = c.getContext("2d");

        // shadow
        g.fillStyle = "rgba(0,0,0,0.15)";
        g.beginPath();
        g.ellipse(16, 29, 10, 3, 0, 0, Math.PI * 2);
        g.fill();

        // body
        g.fillStyle = "#2d6cdf";
        g.fillRect(12, 12, 8, 10);

        // head
        g.fillStyle = "#ffd3b3";
        g.fillRect(11, 5, 10, 8);

        // hair
        g.fillStyle = "#3b2b1f";
        g.fillRect(11, 4, 10, 3);

        // eyes
        g.fillStyle = blink ? "#000" : "#1a1a1a";
        g.fillRect(13, 8, 1, 1);
        g.fillRect(17, 8, 1, 1);

        // arms
        g.fillStyle = "#ffd3b3";
        g.fillRect(8, 13 + armOffset, 4, 2);
        g.fillRect(20, 13 - armOffset, 4, 2);

        // legs
        g.fillStyle = "#2d2d2d";
        g.fillRect(13, 22, 3, 6 + legOffset);
        g.fillRect(16, 22, 3, 6 - legOffset);

        // shoes
        g.fillStyle = "#ffffff";
        g.fillRect(12, 27 + legOffset, 4, 2);
        g.fillRect(16, 27 - legOffset, 4, 2);

        return c;
      };

      frames.push(makeFrame(0, 0, false));
      frames.push(makeFrame(1, 1, false));
      frames.push(makeFrame(0, 0, true));
      frames.push(makeFrame(-1, -1, false));
      return frames;
    }

    const playerSprites = createSpriteFrames();

    const world = {
      gravity: 1800,
      friction: 0.85,
      airFriction: 0.98
    };

    const player = {
      x: 100,
      y: 100,
      w: 32,
      h: 32,
      vx: 0,
      vy: 0,
      speed: 320,
      jumpPower: 650,
      onGround: false,
      facing: 1,
      animTime: 0,
      animFrame: 0,
      respawnX: 100,
      respawnY: 100
    };

    const platforms = [
      { x: 0, y: 500, w: 960, h: 40 },   // ground
      { x: 120, y: 420, w: 160, h: 20 },
      { x: 340, y: 360, w: 180, h: 20 },
      { x: 590, y: 310, w: 150, h: 20 },
      { x: 780, y: 250, w: 120, h: 20 },
      { x: 60, y: 280, w: 100, h: 20 },
      { x: 230, y: 220, w: 90, h: 20 },
      { x: 430, y: 180, w: 110, h: 20 }
    ];

    const goal = { x: 880, y: 190, w: 30, h: 60 };

    function resetPlayer() {
      player.x = player.respawnX;
      player.y = player.respawnY;
      player.vx = 0;
      player.vy = 0;
    }

    function handleInput(dt) {
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      if (move !== 0) player.facing = move;

      const accel = 1800;
      player.vx += move * accel * dt;

      if (move === 0) {
        player.vx *= player.onGround ? world.friction : world.airFriction;
      }

      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround && !player._jumpLock) {
        player.vy = -player.jumpPower;
        player.onGround = false;
        player._jumpLock = true;
      }
      if (!jumpPressed) player._jumpLock = false;

      player.vx = Math.max(-player.speed, Math.min(player.speed, player.vx));
    }

    function moveAndCollide(dt) {
      // apply gravity
      player.vy += world.gravity * dt;

      // horizontal move
      player.x += player.vx * dt;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // vertical move
      player.y += player.vy * dt;
      player.onGround = false;

      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // fall off the map
      if (player.y > canvas.height + 200) {
        resetPlayer();
      }

      // goal reached
      if (rectsIntersect(player, goal)) {
        alert("You win!");
        resetPlayer();
      }
    }

    function updateAnimation(dt) {
      const moving = Math.abs(player.vx) > 20;
      if (moving && player.onGround) {
        player.animTime += dt;
        if (player.animTime > 0.1) {
          player.animTime = 0;
          player.animFrame = (player.animFrame + 1) % 4;
        }
      } else {
        player.animFrame = 0;
      }
    }

    function drawPlatform(p, color = "#6a4b2f") {
      ctx.fillStyle = color;
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "rgba(255,255,255,0.12)";
      ctx.fillRect(p.x, p.y, p.w, 4);
    }

    function drawGoal() {
      // pole
      ctx.fillStyle = "#f2f2f2";
      ctx.fillRect(goal.x + 4, goal.y - 20, 4, goal.h + 20);

      // flag
      ctx.fillStyle = "#35d16b";
      ctx.beginPath();
      ctx.moveTo(goal.x + 8, goal.y - 18);
      ctx.lineTo(goal.x + 30, goal.y - 10);
      ctx.lineTo(goal.x + 8, goal.y + 2);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer() {
      ctx.save();

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.beginPath();
      ctx.ellipse(player.x + player.w / 2, player.y + player.h + 3, 12, 4, 0, 0, Math.PI * 2);
      ctx.fill();

      // flip sprite if facing left
      if (player.facing === -1) {
        ctx.translate(player.x + player.w, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(playerSprites[player.animFrame], 0, 0, 32, 32);
      } else {
        ctx.drawImage(playerSprites[player.animFrame], player.x, player.y, 32, 32);
      }

      ctx.restore();
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#8dd3ff";
      ctx.beginPath();
      ctx.arc(180, 500, 180, Math.PI, 0, false);
      ctx.arc(480, 500, 220, Math.PI, 0, false);
      ctx.arc(780, 500, 170, Math.PI, 0, false);
      ctx.fill();

      // clouds
      const clouds = [
        [120, 90], [320, 60], [640, 110], [820, 70]
      ];
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      for (const [x, y] of clouds) {
        ctx.beginPath();
        ctx.arc(x, y, 18, 0, Math.PI * 2);
        ctx.arc(x + 18, y + 8, 22, 0, Math.PI * 2);
        ctx.arc(x + 40, y, 16, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    let lastTime = 0;
    function gameLoop(t) {
      const dt = Math.min((t - lastTime) / 1000, 0.033);
      lastTime = t;

      handleInput(dt);
      moveAndCollide(dt);
      updateAnimation(dt);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // draw world
      for (const p of platforms) drawPlatform(p);
      drawGoal();
      drawPlayer();

      // ground line / HUD text
      ctx.fillStyle = "#1b1b1b";
      ctx.fillText("", 0, 0);

      requestAnimationFrame(gameLoop);
    }

    resetPlayer();
    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
