      }

      // Move Y
      entity.y += entity.vy * dt;

      for (const s of solids) {
        if (rectsIntersect(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    // -----------------------------
    // Main loop
    // -----------------------------
    let last = performance.now();
    let dt = 0;

    function update(delta) {
      dt = delta;

      // Input movement
      const left = isDown("ArrowLeft", "KeyA");
      const right = isDown("ArrowRight", "KeyD");
      const jump = isDown("Space", "ArrowUp", "KeyW");

      if (left) {
        player.vx = Math.max(player.vx - MOVE_SPEED * dt, -MOVE_SPEED);
        player.facing = -1;
      } else if (right) {
        player.vx = Math.min(player.vx + MOVE_SPEED * dt, MOVE_SPEED);
        player.facing = 1;
      } else {
        player.vx *= player.onGround ? FRICTION : AIR_FRICTION;
        if (Math.abs(player.vx) < 1) player.vx = 0;
      }

      // Jump
      if (jump && player.onGround && !player._jumpPressed) {
        player.vy = -JUMP_FORCE;
        player.onGround = false;
      }
      player._jumpPressed = jump;

      // Gravity
      player.vy += GRAVITY * dt;
      if (player.vy > 1800) player.vy = 1800;

      // Collisions
      resolveCollisions(player, platforms);

      // Goal check
      if (rectsIntersect(player, goal)) {
        // Simple win action
        alert("You reached the goal!");
        player.x = 80;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      player.state = getAnimState();
      player.animTime += dt;

      // Camera follows player
      camera.x = player.x - canvas.width / 2 + player.w / 2;
      camera.y = player.y - canvas.height / 2 + player.h / 2;

      // Clamp camera
      camera.x = Math.max(-100, camera.x);
      camera.y = Math.max(-100, camera.y);
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#6b4f2a";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#8b6b3e";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
    }

    function drawGoal(g) {
      ctx.fillStyle = "#ffd700";
      ctx.fillRect(g.x - camera.x, g.y - camera.y, g.w, g.h);

      ctx.strokeStyle = "rgba(255,255,255,0.7)";
      ctx.lineWidth = 3;
      ctx.strokeRect(g.x - camera.x, g.y - camera.y, g.w, g.h);
    }

    function drawPlayer() {
      const drawX = player.x - camera.x;
      const drawY = player.y - camera.y;

      // If sprite failed to load, draw a fallback rectangle
      if (!sprite.complete || sprite.naturalWidth === 0) {
        ctx.fillStyle = "#ff5e5e";
        ctx.fillRect(drawX, drawY, player.w, player.h);
        return;
      }

      const state = player.state;
      const frame = getFrameIndex(state, player.animTime);

      let row = 0;
      if (state === "idle") row = 0;
      else if (state === "run") row = 1;
      else if (state === "jump") row = 2;
      else if (state === "fall") row = 2;

      ctx.save();
      ctx.translate(drawX + player.w / 2, drawY + player.h / 2);

      if (player.facing === -1) {
        ctx.scale(-1, 1);
      }

      // Draw sprite frame
      ctx.drawImage(
        sprite,
        frame * SPRITE_W,
        row * SPRITE_H,
        SPRITE_W,
        SPRITE_H,
        -player.w / 2,
        -player.h / 2,
        player.w,
        player.h
      );

      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background hills/decoration
      ctx.fillStyle = "rgba(255,255,255,0.15)";
      for (let i = 0; i < 12; i++) {
        const x = (i * 220 - camera.x * 0.15) % (canvas.width + 300) - 100;
        const y = 200 + (i % 3) * 20;
        ctx.beginPath();
        ctx.arc(x, y, 60, 0, Math.PI * 2);
        ctx.fill();
      }

      // Platforms
      for (const p of platforms) drawPlatform(p);

      // Goal
      drawGoal(goal);

      // Player
      drawPlayer();

      // Debug info
      ctx.fillStyle = "black";
      ctx.font = "16px monospace";
      ctx.fillText(`x:${player.x.toFixed(1)} y:${player.y.toFixed(1)}`, 12, canvas.height - 20);
    }

    function loop(now) {
      const delta = Math.min((now - last) / 1000, 1 / 30);
      last = now;

      update(delta);
      render();

      requestAnimationFrame(loop);
    }

    // Start after sprite loads or immediately if loading fails
    sprite.onload = () => requestAnimationFrame(loop);
    sprite.onerror = () => requestAnimationFrame(loop);

    // Fallback if image takes too long
    setTimeout(() => {
      if (!window._started) {
        window._started = true;
        requestAnimationFrame(loop);
      }
    }, 500);
  </script>
</body>
</html>
```

