## Full code

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      background: linear-gradient(#7ec8ff, #dff5ff);
      image-rendering: pixelated;
    }

    .hud {
      position: fixed;
      left: 12px;
      top: 12px;
      color: white;
      text-shadow: 0 2px 4px rgba(0,0,0,0.6);
      font-size: 14px;
      user-select: none;
      pointer-events: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or Arrow Keys<br>
    Jump: Space / W / Up
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (["ArrowLeft", "a", "A"].includes(e.key)) keys.left = true;
      if (["ArrowRight", "d", "D"].includes(e.key)) keys.right = true;
      if (["ArrowUp", "w", "W", " "].includes(e.key)) keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (["ArrowLeft", "a", "A"].includes(e.key)) keys.left = false;
      if (["ArrowRight", "d", "D"].includes(e.key)) keys.right = false;
      if (["ArrowUp", "w", "W", " "].includes(e.key)) keys.jump = false;
    });

    class Rect {
      constructor(x, y, w, h) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
      }
    }

    // Platforms / level
    const platforms = [
      new Rect(0, 560, 2200, 40),
      new Rect(180, 460, 160, 20),
      new Rect(420, 390, 160, 20),
      new Rect(650, 330, 160, 20),
      new Rect(930, 420, 220, 20),
      new Rect(1240, 360, 180, 20),
      new Rect(1500, 300, 220, 20),
      new Rect(1830, 450, 180, 20),
    ];

    // Player with physics + sprite animation
    const player = {
      x: 50,
      y: 400,
      w: 40,
      h: 56,
      vx: 0,
      vy: 0,
      speed: 0.8,
      maxSpeed: 6,
      jumpPower: 14,
      gravity: 0.75,
      friction: 0.82,
      onGround: false,
      facing: 1, // 1 right, -1 left
      animTime: 0,
      animFrame: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function aabbIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // Move X
      entity.x += entity.vx;
      for (const s of solids) {
        if (aabbIntersect(entity, s)) {
          if (entity.vx > 0) {
            entity.x = s.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = s.x + s.w;
          }
          entity.vx = 0;
        }
      }

      // Move Y
      entity.y += entity.vy;
      for (const s of solids) {
        if (aabbIntersect(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
          }
          entity.vy = 0;
        }
      }
    }

    // Simple sprite-sheet style animation:
    // We draw the player as a "pixel character" using colored rectangles.
    // The frames change leg/arm positions to simulate animation.
    function drawPlayer(ctx, p, cam) {
      const x = Math.floor(p.x - cam.x);
      const y = Math.floor(p.y - cam.y);

      ctx.save();
      ctx.translate(x + p.w / 2, y + p.h / 2);
      ctx.scale(p.facing, 1);
      ctx.translate(-p.w / 2, -p.h / 2);

      const frame = p.animFrame;

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.18)";
      ctx.fillRect(8, p.h - 6, 24, 8);

      // body
      ctx.fillStyle = "#2b4cff";
      ctx.fillRect(12, 14, 16, 20);

      // head
      ctx.fillStyle = "#ffd2b1";
      ctx.fillRect(13, 2, 14, 14);

      // hat/hair
      ctx.fillStyle = "#3b1f10";
      ctx.fillRect(12, 1, 16, 4);

      // eyes
      ctx.fillStyle = "#111";
      ctx.fillRect(16, 7, 2, 2);
      ctx.fillRect(21, 7, 2, 2);

      // arms
      ctx.fillStyle = "#ffd2b1";
      if (frame === 0) {
        ctx.fillRect(8, 16, 4, 10);
        ctx.fillRect(28, 16, 4, 10);
      } else if (frame === 1) {
        ctx.fillRect(7, 14, 4, 10);
        ctx.fillRect(29, 18, 4, 10);
      } else {
        ctx.fillRect(7, 18, 4, 10);
        ctx.fillRect(29, 14, 4, 10);
      }

      // legs
      ctx.fillStyle = "#1d1d1d";
      if (frame === 0) {
        ctx.fillRect(13, 34, 5, 16);
        ctx.fillRect(22, 34, 5, 16);
      } else if (frame === 1) {
        ctx.fillRect(12, 34, 5, 16);
        ctx.fillRect(24, 36, 5, 14);
      } else {
        ctx.fillRect(12, 36, 5, 14);
        ctx.fillRect(24, 34, 5, 16);
      }

      ctx.restore();
    }

    function updatePlayer(dt) {
      const accel = player.speed;
      const maxSpeed = player.maxSpeed;

      if (keys.left) {
        player.vx -= accel;
        player.facing = -1;
      }
      if (keys.right) {
        player.vx += accel;
        player.facing = 1;
      }

      // clamp speed
      player.vx = Math.max(-maxSpeed, Math.min(maxSpeed, player.vx));

      // jump
      if (keys.jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // gravity
      player.vy += player.gravity;
      if (player.vy > 18) player.vy = 18;

      // friction
      if (player.onGround && !keys.left && !keys.right) {
        player.vx *= player.friction;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      resolveCollisions(player, platforms);

      // fall reset
      if (player.y > 1000) {
        player.x = 50;
        player.y = 400;
        player.vx = 0;
        player.vy = 0;
      }

      // animation
      const moving = Math.abs(player.vx) > 0.5 && player.onGround;
      if (moving) {
        player.animTime += dt;
        if (player.animTime > 0.12) {
          player.animFrame = (player.animFrame + 1) % 3;
          player.animTime = 0;
        }
      } else {
        player.animFrame = 0;
        player.animTime = 0;
      }

      // camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      // level bounds
      camera.x = Math.max(0, camera.x);
      camera.y = Math.max(0, camera.y);
    }

    function drawBackground() {
      // parallax-ish clouds
      ctx.save();
      ctx.translate(-camera.x * 0.2, -camera.y * 0.1);

      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 10; i++) {
        const cx = i * 260 + 50;
        const cy = 80 + (i % 3) * 35;
        ctx.beginPath();
        ctx.arc(cx, cy, 28, 0, Math.PI * 2);
        ctx.arc(cx + 26, cy - 10, 36, 0, Math.PI * 2);
        ctx.arc(cx + 58, cy, 28, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        const x = p.x - camera.x;
        const y = p.y - camera.y;

        // top surface
        ctx.fillStyle = "#5b3a1e";
        ctx.fillRect(x, y, p.w, p.h);

        ctx.fillStyle = "#7a4a24";
        ctx.fillRect(x, y, p.w, 6);

        // grass on top of some platforms
        ctx.fillStyle = "#3cb043";
        ctx.fillRect(x, y - 6, p.w, 6);
      }
    }

    function drawGrid() {
      ctx.save();
      ctx.globalAlpha = 0.12;
      ctx.strokeStyle = "#000";
      ctx.lineWidth = 1;

      const grid = 40;
      const startX = Math.floor(camera.x / grid) * grid - camera.x;
      const startY = Math.floor(camera.y / grid) * grid - camera.y;

      for (let x = startX; x < canvas.width; x += grid) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
      }

      for (let y = startY; y < canvas.height; y += grid) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
      }

      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // decorative distant hills
      ctx.fillStyle = "#8fd18b";
      ctx.beginPath();
      ctx.moveTo(-200, 560);
      ctx.quadraticCurveTo(200, 420, 600, 560);
      ctx.quadraticCurveTo(900, 460, 1250, 560);
      ctx.quadraticCurveTo(1600, 420, 2200, 560);
      ctx.lineTo(2200, 700);
      ctx.lineTo(-200, 700);
      ctx.closePath();
      ctx.fill();

      drawPlatforms();

      ctx.restore();

      drawGrid();
      drawPlayer(ctx, player, camera);
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;

      updatePlayer(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
