  </style>
</head>
<body>
  <div class="hud">Coins: <span id="coinCount">0</span></div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const coinCountEl = document.getElementById("coinCount");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
    });

    const gravity = 0.7;
    const friction = 0.85;

    class Rect {
      constructor(x, y, w, h) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
      }

      intersects(other) {
        return (
          this.x < other.x + other.w &&
          this.x + this.w > other.x &&
          this.y < other.y + other.h &&
          this.y + this.h > other.y
        );
      }
    }

    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.w = 48;
        this.h = 64;
        this.vx = 0;
        this.vy = 0;
        this.speed = 0.8;
        this.jumpPower = 14;
        this.onGround = false;
        this.facing = 1;
        this.animTime = 0;
        this.frame = 0;
        this.color = "#ff5d5d";
        this.coins = 0;
      }

      get rect() {
        return new Rect(this.x, this.y, this.w, this.h);
      }

      update(platforms) {
        // Horizontal input
        if (keys.left) {
          this.vx -= this.speed;
          this.facing = -1;
        }
        if (keys.right) {
          this.vx += this.speed;
          this.facing = 1;
        }

        // Jump
        if (keys.jump && this.onGround) {
          this.vy = -this.jumpPower;
          this.onGround = false;
        }

        // Apply physics
        this.vy += gravity;
        this.vx *= friction;

        // Move X and resolve collisions
        this.x += this.vx;
        for (const p of platforms) {
          if (this.rect.intersects(p)) {
            if (this.vx > 0) this.x = p.x - this.w;
            else if (this.vx < 0) this.x = p.x + p.w;
            this.vx = 0;
          }
        }

        // Move Y and resolve collisions
        this.y += this.vy;
        this.onGround = false;
        for (const p of platforms) {
          if (this.rect.intersects(p)) {
            if (this.vy > 0) {
              this.y = p.y - this.h;
              this.vy = 0;
              this.onGround = true;
            } else if (this.vy < 0) {
              this.y = p.y + p.h;
              this.vy = 0;
            }
          }
        }

        // Animation
        this.animTime += 1;
        if (Math.abs(this.vx) > 0.5) {
          this.frame = Math.floor(this.animTime / 8) % 4;
        } else {
          this.frame = 0;
        }
      }

      draw(ctx, camX, camY) {
        const x = this.x - camX;
        const y = this.y - camY;

        // Body
        ctx.save();
        ctx.translate(x + this.w / 2, y + this.h / 2);
        ctx.scale(this.facing, 1);
        ctx.translate(-(x + this.w / 2), -(y + this.h / 2));

        // Sprite-like animated character (simple drawn frames)
        const bob = this.frame === 1 || this.frame === 3 ? 2 : 0;

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.15)";
        ctx.beginPath();
        ctx.ellipse(x + this.w / 2, y + this.h + 6, 18, 6, 0, 0, Math.PI * 2);
        ctx.fill();

        // Legs
        ctx.fillStyle = "#444";
        ctx.fillRect(x + 10, y + 44 + bob, 10, 18 - bob);
        ctx.fillRect(x + 28, y + 44 - bob, 10, 18 + bob);

        // Torso
        ctx.fillStyle = this.color;
        ctx.fillRect(x + 8, y + 18, 32, 28);

        // Head
        ctx.fillStyle = "#ffd1a3";
        ctx.fillRect(x + 12, y + 4, 24, 18);

        // Eyes
        ctx.fillStyle = "#000";
        ctx.fillRect(x + 17, y + 10, 4, 4);
        ctx.fillRect(x + 27, y + 10, 4, 4);

        // Arms
        ctx.fillStyle = "#c84d4d";
        ctx.fillRect(x + 2, y + 22, 8, 20);
        ctx.fillRect(x + 38, y + 22, 8, 20);

        ctx.restore();
      }
    }

    class Platform extends Rect {
      draw(ctx, camX, camY) {
        const x = this.x - camX;
        const y = this.y - camY;

        ctx.fillStyle = "#654321";
        ctx.fillRect(x, y, this.w, this.h);

        ctx.fillStyle = "#7d5a3a";
        ctx.fillRect(x, y, this.w, 8);

        ctx.strokeStyle = "rgba(255,255,255,0.08)";
        ctx.strokeRect(x, y, this.w, this.h);
      }
    }

    class Coin extends Rect {
      constructor(x, y) {
        super(x, y, 20, 20);
        this.collected = false;
        this.time = 0;
      }

      update() {
        this.time += 0.08;
      }

      draw(ctx, camX, camY) {
        if (this.collected) return;
        const x = this.x - camX;
        const y = this.y - camY + Math.sin(this.time) * 2;

        ctx.fillStyle = "#ffd700";
        ctx.beginPath();
        ctx.arc(x + 10, y + 10, 10, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = "#ffef9a";
        ctx.beginPath();
        ctx.arc(x + 7, y + 7, 3, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    class Enemy extends Rect {
      constructor(x, y, leftBound, rightBound) {
        super(x, y, 40, 40);
        this.vx = 1.5;
        this.vy = 0;
        this.leftBound = leftBound;
        this.rightBound = rightBound;
        this.alive = true;
        this.dir = 1;
      }

      get rect() {
        return new Rect(this.x, this.y, this.w, this.h);
      }

      update(platforms) {
        this.vy += gravity;
        this.x += this.vx * this.dir;

        if (this.x < this.leftBound) this.dir = 1;
        if (this.x + this.w > this.rightBound) this.dir = -1;

        for (const p of platforms) {
          if (this.rect.intersects(p)) {
            if (this.vy > 0) {
              this.y = p.y - this.h;
              this.vy = 0;
            }
          }
        }

        this.y += this.vy;
      }

      draw(ctx, camX, camY) {
        if (!this.alive) return;
        const x = this.x - camX;
        const y = this.y - camY;

        ctx.fillStyle = "#5c2cff";
        ctx.fillRect(x, y, this.w, this.h);

        ctx.fillStyle = "#fff";
        ctx.fillRect(x + 8, y + 10, 8, 8);
        ctx.fillRect(x + 24, y + 10, 8, 8);

        ctx.fillStyle = "#000";
        ctx.fillRect(x + 11, y + 13, 3, 3);
        ctx.fillRect(x + 27, y + 13, 3, 3);

        ctx.fillStyle = "#330099";
        ctx.fillRect(x + 10, y + 28, 20, 5);
      }
    }

    const platforms = [
      new Platform(0, 550, 2000, 50),
      new Platform(160, 450, 160, 25),
      new Platform(400, 380, 180, 25),
      new Platform(680, 320, 160, 25),
      new Platform(920, 420, 180, 25),
      new Platform(1180, 360, 200, 25),
      new Platform(1450, 480, 160, 25),
      new Platform(1680, 400, 180, 25)
    ];

    const coins = [
      new Coin(190, 410),
      new Coin(450, 340),
      new Coin(720, 280),
      new Coin(970, 380),
      new Coin(1250, 320),
      new Coin(1490, 440),
      new Coin(1730, 360)
    ];

    const enemies = [
      new Enemy(520, 340, 400, 580),
      new Enemy(1320, 320, 1180, 1380)
    ];

    const player = new Player(80, 400);

    let camX = 0;
    let camY = 0;
    let gameOver = false;

    function update() {
      if (gameOver) return;

      player.update(platforms);

      for (const coin of coins) {
        coin.update();
        if (!coin.collected && player.rect.intersects(coin)) {
          coin.collected = true;
          player.coins++;
          coinCountEl.textContent = player.coins;
        }
      }

      for (const enemy of enemies) {
        enemy.update(platforms);

        if (enemy.alive && player.rect.intersects(enemy.rect)) {
          // Simple collision: bounce player if coming from above, otherwise game over
          if (player.vy > 0 && player.y + player.h - enemy.y < 20) {
            enemy.alive = false;
            player.vy = -10;
          } else {
            gameOver = true;
          }
        }
      }

      // Camera follow
      camX = player.x - canvas.width / 2 + player.w / 2;
      camY = player.y - canvas.height / 2 + player.h / 2;

      // Clamp camera
      camX = Math.max(0, Math.min(camX, 2000 - canvas.width));
      camY = Math.max(0, Math.min(camY, 600 - canvas.height));

      // Fall off world
      if (player.y > 800) {
        gameOver = true;
      }
    }

    function drawBackground() {
      // Parallax hills
      ctx.fillStyle = "#77b255";
      for (let i = 0; i < 8; i++) {
        const hillX = (i * 300 - camX * 0.3) % (canvas.width + 300) - 150;
        ctx.beginPath();
        ctx.ellipse(hillX, canvas.height - 40, 120, 60, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // Clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      for (let i = 0; i < 6; i++) {
        const cloudX = (i * 280 - camX * 0.15) % (canvas.width + 300) - 100;
        const cloudY = 60 + (i % 3) * 40;
        ctx.beginPath();
        ctx.arc(cloudX, cloudY, 20, 0, Math.PI * 2);
        ctx.arc(cloudX + 20, cloudY - 10, 25, 0, Math.PI * 2);
        ctx.arc(cloudX + 45, cloudY, 18, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      for (const p of platforms) p.draw(ctx, camX, camY);
      for (const coin of coins) coin.draw(ctx, camX, camY);
      for (const enemy of enemies) enemy.draw(ctx, camX, camY);
      player.draw(ctx, camX, camY);

      if (gameOver) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "white";
        ctx.font = "48px Arial";
        ctx.textAlign = "center";
        ctx.fillText("Game Over", canvas.width / 2, canvas.height / 2);
        ctx.font = "24px Arial";
        ctx.fillText("Refresh to restart", canvas.width / 2, canvas.height / 2 + 40);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

