Below is a complete starter **2D platformer** in **JavaScript + HTML5 Canvas** with:

- basic **physics simulation**: gravity, acceleration, friction, jumping
- **collision with platforms**
- **sprite animation** using a simple frame system
- **camera follow**
- keyboard controls

You can run this by saving it as `index.html` and opening it in a browser.

---

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #111;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#7ec8ff, #dff6ff);
    }
    #hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 2px 4px rgba(0,0,0,0.6);
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div id="hud">Arrow keys / A,D to move, Space to jump</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // -----------------------------
    // Input
    // -----------------------------
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    function isLeft() {
      return keys["a"] || keys["arrowleft"];
    }
    function isRight() {
      return keys["d"] || keys["arrowright"];
    }
    function isJumpPressed() {
      return keys[" "] || keys["spacebar"] || keys["arrowup"] || keys["w"];
    }

    // -----------------------------
    // World / Physics constants
    // -----------------------------
    const GRAVITY = 0.7;
    const MOVE_SPEED = 0.7;
    const MAX_SPEED_X = 6;
    const JUMP_VELOCITY = -14;
    const FRICTION = 0.82;
    const AIR_FRICTION = 0.95;

    // -----------------------------
    // Platforms
    // -----------------------------
    const platforms = [
      { x: -200, y: 550, w: 2400, h: 80 }, // ground
      { x: 180, y: 440, w: 150, h: 20 },
      { x: 420, y: 370, w: 160, h: 20 },
      { x: 680, y: 320, w: 160, h: 20 },
      { x: 930, y: 260, w: 170, h: 20 },
      { x: 1240, y: 410, w: 200, h: 20 },
      { x: 1530, y: 340, w: 120, h: 20 },
    ];

    // -----------------------------
    // Player
    // -----------------------------
    const player = {
      x: 100,
      y: 100,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1, // 1 = right, -1 = left
      state: "idle",
      animTime: 0,
      frame: 0
    };

    // Simple placeholder sprite frames generated from canvas
    function createSpriteFrames() {
      const frames = {
        idle: [],
        run: [],
        jump: []
      };

      function generateFrame(state, frameIndex) {
        const c = document.createElement("canvas");
        c.width = 48;
        c.height = 64;
        const g = c.getContext("2d");

        // body color
        const body = "#4b6cff";
        const shirt = "#ffcc66";
        const skin = "#ffdbb5";
        const boot = "#222";

        // shadow / outline
        g.fillStyle = "rgba(0,0,0,0.15)";
        g.fillRect(12, 58, 24, 4);

        // head
        g.fillStyle = skin;
        g.beginPath();
        g.arc(24, 16, 10, 0, Math.PI * 2);
        g.fill();

        // torso
        g.fillStyle = shirt;
        g.fillRect(16, 24, 16, 18);

        // legs / arms with basic animation offsets
        const legSwing = state === "run" ? Math.sin(frameIndex * Math.PI) * 5 : 0;
        const armSwing = state === "run" ? -Math.sin(frameIndex * Math.PI) * 5 : 0;
        const jumpLift = state === "jump" ? -2 : 0;

        // arms
        g.strokeStyle = skin;
        g.lineWidth = 4;
        g.lineCap = "round";
        g.beginPath();
        g.moveTo(16, 26 + jumpLift);
        g.lineTo(10 + armSwing * 0.2, 38 + jumpLift);
        g.stroke();

        g.beginPath();
        g.moveTo(32, 26 + jumpLift);
        g.lineTo(38 - armSwing * 0.2, 38 + jumpLift);
        g.stroke();

        // legs
        g.strokeStyle = body;
        g.lineWidth = 5;

        g.beginPath();
        g.moveTo(20, 42);
        g.lineTo(18 - legSwing * 0.2, 54);
        g.stroke();

        g.beginPath();
        g.moveTo(28, 42);
        g.lineTo(30 + legSwing * 0.2, 54);
        g.stroke();

        // boots
        g.fillStyle = boot;
        g.fillRect(14 - legSwing * 0.2, 53, 8, 4);
        g.fillRect(26 + legSwing * 0.2, 53, 8, 4);

        // eyes
        g.fillStyle = "#111";
        g.fillRect(20, 14, 3, 3);
        g.fillRect(26, 14, 3, 3);

        return c;
      }

      for (let i = 0; i < 4; i++) frames.run.push(generateFrame("run", i / 4));
      frames.idle.push(generateFrame("idle", 0));
      frames.idle.push(generateFrame("idle", 1));
      frames.jump.push(generateFrame("jump", 0));

      return frames;
    }

    const spriteFrames = createSpriteFrames();

    // -----------------------------
    // Collision helpers
    // -----------------------------
    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // Move X
      entity.x += entity.vx;
      for (const p of solids) {
        if (rectsIntersect(entity, p)) {
          if (entity.vx > 0) {
            entity.x = p.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = p.x + p.w;
          }
          entity.vx = 0;
        }
      }

      // Move Y
      entity.y += entity.vy;
      for (const p of solids) {
        if (rectsIntersect(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    // -----------------------------
    // Camera
    // -----------------------------
    const camera = {
      x: 0,
      y: 0
    };

    // -----------------------------
    // Game loop
    // -----------------------------
    let lastTime = 0;
    let jumpLock = false;

    function update(dt) {
      // Horizontal movement
      if (isLeft()) {
        player.vx -= MOVE_SPEED;
        player.facing = -1;
      }
      if (isRight()) {
        player.vx += MOVE_SPEED;
        player.facing = 1;
      }

      player.vx = Math.max(-MAX_SPEED_X, Math.min(MAX_SPEED_X, player.vx));

      // Friction
      if (player.onGround) {
        player.vx *= FRICTION;
      } else {
        player.vx *= AIR_FRICTION;
      }

      // Jump
      const jumpNow = isJumpPressed();
      if (jumpNow && player.onGround && !jumpLock) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
        jumpLock = true;
      }
      if (!jumpNow) jumpLock = false;

      // Gravity
      player.vy += GRAVITY;
      if (player.vy > 18) player.vy = 18;

      // Physics + collision
      resolveCollisions(player, platforms);

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 1) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;
      if (player.state === "run") {
        player.frame = Math.floor((player.animTime * 12) % spriteFrames.run.length);
      } else if (player.state === "idle") {
        player.frame = Math.floor((player.animTime * 4) % spriteFrames.idle.length);
      } else {
        player.frame = 0;
      }

      // Camera follows player
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      // Clamp camera
      camera.x = Math.max(-200, Math.min(2000 - canvas.width + 200, camera.x));
      camera.y = Math.max(-100, Math.min(700 - canvas.height + 100, camera.y));
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5c4033";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#7b563f";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
    }

    function drawPlayer() {
      const frame =
        player.state === "run"
          ? spriteFrames.run[player.frame]
          : player.state === "jump"
          ? spriteFrames.jump[0]
          : spriteFrames.idle[player.frame];

      ctx.save();
      ctx.translate(player.x - camera.x, player.y - camera.y);
      if (player.facing === -1) {
        ctx.scale(-1, 1);
        ctx.drawImage(frame, -player.w, 0, player.w, player.h);
      } else {
        ctx.drawImage(frame, 0, 0, player.w, player.h);
      }
      ctx.restore();
    }

    function drawBackground() {
      // sky
      ctx.fillStyle = "#7ec8ff";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // distant hills
      ctx.fillStyle = "#8fd18f";
      for (let i = -2; i < 8; i++) {
        ctx.beginPath();
        ctx.ellipse(i * 300 - (camera.x * 0.2) % 300 + 150, canvas.height - 120, 180, 70, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      drawBackground();

      // platforms
      for (const p of platforms) drawPlatform(p);

      // player
      drawPlayer();

      // debug info
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, 10, 190, 70);
      ctx.fillStyle = "#fff";
      ctx.font = "14px monospace";
      ctx.fillText(`x: ${player.x.toFixed(1)}`, 20, 32);
      ctx.fillText(`y: ${player.y.toFixed(1)}`, 20, 50);
      ctx.fillText(`state: ${player.state}`, 20, 68);
    }

    function loop(timestamp) {
      const dt = Math.min(0.033, (timestamp - lastTime) / 1000 || 0);
      lastTime = timestamp;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
