      sCtx.clearRect(x, 0, 48, 72);

      // body
      sCtx.fillStyle = "#5b8cff";
      sCtx.fillRect(x + 14, 18, 20, 30);

      // head
      sCtx.fillStyle = "#ffd7b0";
      sCtx.fillRect(x + 16, 6, 16, 14);

      // legs animation
      sCtx.strokeStyle = "#2b2b2b";
      sCtx.lineWidth = 5;
      sCtx.beginPath();
      if (frame === 0) {
        sCtx.moveTo(x + 18, 48); sCtx.lineTo(x + 12, 66);
        sCtx.moveTo(x + 30, 48); sCtx.lineTo(x + 36, 66);
      } else if (frame === 1) {
        sCtx.moveTo(x + 18, 48); sCtx.lineTo(x + 16, 66);
        sCtx.moveTo(x + 30, 48); sCtx.lineTo(x + 40, 60);
      } else if (frame === 2) {
        sCtx.moveTo(x + 18, 48); sCtx.lineTo(x + 20, 66);
        sCtx.moveTo(x + 30, 48); sCtx.lineTo(x + 32, 66);
      } else {
        sCtx.moveTo(x + 18, 48); sCtx.lineTo(x + 10, 60);
        sCtx.moveTo(x + 30, 48); sCtx.lineTo(x + 36, 66);
      }
      sCtx.stroke();

      // arms
      sCtx.beginPath();
      sCtx.moveTo(x + 14, 30); sCtx.lineTo(x + 6, 40);
      sCtx.moveTo(x + 34, 30); sCtx.lineTo(x + 42, 40);
      sCtx.stroke();
    }

    for (let i = 0; i < 4; i++) drawFrame(i, i * 48);

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    let last = performance.now();
    let dt = 0;

    function update(delta) {
      dt = delta;

      // Movement input
      const left = keys["ArrowLeft"] || keys["KeyA"];
      const right = keys["ArrowRight"] || keys["KeyD"];
      const jump = keys["ArrowUp"] || keys["KeyW"] || keys["Space"];

      if (left) {
        player.vx -= MOVE_ACCEL * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL * dt;
        player.facing = 1;
      }

      // Clamp horizontal speed
      player.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, player.vx));

      // Jump
      if (jump && player.grounded && !player._jumpHeld) {
        player.vy = -JUMP_VELOCITY;
        player.grounded = false;
      }
      player._jumpHeld = jump;

      // Gravity
      player.vy += GRAVITY * dt;

      // Friction
      if (player.grounded) {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 1) player.vx = 0;
      } else {
        player.vx *= AIR_FRICTION;
      }

      // Save old pos for collision direction if needed
      player.prevX = player.x;
      player.prevY = player.y;

      resolveCollisions(player, world.platforms);

      // State
      if (!player.grounded) player.state = "jump";
      else if (Math.abs(player.vx) > 20) player.state = "run";
      else player.state = "idle";

      // Animation
      player.animTime += delta;
      player.frame = 0;
      if (player.state === "run") {
        player.frame = Math.floor(player.animTime * 12) % 4;
      } else if (player.state === "jump") {
        player.frame = 2;
      } else {
        player.frame = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));

      // Keep player within world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      player.y = Math.min(world.height - player.h, player.y);
    }

    function drawBackground() {
      // Parallax mountains
      ctx.fillStyle = "#7ec8e3";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const offsetX = camera.x * 0.3;
      ctx.fillStyle = "#69a8bf";
      for (let i = -1; i < 8; i++) {
        const x = (i * 300 - offsetX) % (canvas.width + 300) - 100;
        ctx.beginPath();
        ctx.moveTo(x, canvas.height * 0.75);
        ctx.lineTo(x + 120, canvas.height * 0.45);
        ctx.lineTo(x + 240, canvas.height * 0.75);
        ctx.closePath();
        ctx.fill();
      }

      // Ground haze
      const grad = ctx.createLinearGradient(0, canvas.height * 0.7, 0, canvas.height);
      grad.addColorStop(0, "rgba(255,255,255,0)");
      grad.addColorStop(1, "rgba(255,255,255,0.25)");
      ctx.fillStyle = grad;
      ctx.fillRect(0, canvas.height * 0.7, canvas.width, canvas.height * 0.3);
    }

    function draw() {
      ctx.save();
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // World transform
      ctx.translate(-camera.x, -camera.y);

      // Platforms
      for (const p of world.platforms) {
        ctx.fillStyle = "#3f4a5a";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#657389";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }

      // Player sprite
      ctx.save();
      if (player.facing === -1) {
        ctx.translate(player.x + player.w, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(
          spriteSheet,
          player.frame * 48, 0, 48, 72,
          0, 0, player.w, player.h
        );
      } else {
        ctx.drawImage(
          spriteSheet,
          player.frame * 48, 0, 48, 72,
          player.x, player.y, player.w, player.h
        );
      }
      ctx.restore();

      // Debug outline for player
      ctx.strokeStyle = "rgba(255,255,255,0.2)";
      ctx.strokeRect(player.x, player.y, player.w, player.h);

      ctx.restore();

      // HUD
      ctx.fillStyle = "white";
      ctx.font = "16px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 10, 50);
      ctx.fillText(`state: ${player.state}`, 10, 70);
    }

    function loop(now) {
      const delta = Math.min(0.033, (now - last) / 1000);
      last = now;

      update(delta);
      draw();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
