## `index.html`

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
    }

    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      font-size: 14px;
      z-index: 10;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or Arrow Keys | Jump: W / Space / Up
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    // --- Resize ---
    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- World / Tile Map ---
    const TILE = 48;

    // # = solid block, . = empty, P = player start
    const level = [
      "................................................................",
      "................................................................",
      "................................................................",
      ".............................................###................",
      "...............................................................#",
      "....................###........................................#",
      ".............###...............................................#",
      "................................................................",
      ".......###.....................###..............................#",
      "................................................................",
      "......................###.......................................#",
      "..........................................................###...#",
      "................................................................",
      "....P......................................................######",
      "#############################....################################",
      "#############################....################################"
    ];

    const mapWidth = level[0].length * TILE;
    const mapHeight = level.length * TILE;

    // --- Input ---
    const keys = new Set();
    window.addEventListener("keydown", (e) => {
      keys.add(e.key.toLowerCase());
      if ([" ", "arrowup", "w"].includes(e.key.toLowerCase())) e.preventDefault();
    });
    window.addEventListener("keyup", (e) => keys.delete(e.key.toLowerCase()));

    function isDown(...k) {
      return k.some(key => keys.has(key));
    }

    // --- Find player spawn ---
    let spawnX = 100, spawnY = 100;
    for (let y = 0; y < level.length; y++) {
      const x = level[y].indexOf("P");
      if (x !== -1) {
        spawnX = x * TILE;
        spawnY = y * TILE;
        break;
      }
    }

    // --- Player ---
    const player = {
      x: spawnX,
      y: spawnY,
      w: 34,
      h: 44,
      vx: 0,
      vy: 0,
      moveSpeed: 420,
      jumpPower: 900,
      gravity: 2200,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle" // idle, run, jump, fall
    };

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    // --- Collision Helpers ---
    function isSolidTile(tx, ty) {
      if (ty < 0 || ty >= level.length || tx < 0 || tx >= level[0].length) return false;
      return level[ty][tx] === "#";
    }

    function rectVsTile(x, y, w, h) {
      const left = Math.floor(x / TILE);
      const right = Math.floor((x + w - 1) / TILE);
      const top = Math.floor(y / TILE);
      const bottom = Math.floor((y + h - 1) / TILE);

      for (let ty = top; ty <= bottom; ty++) {
        for (let tx = left; tx <= right; tx++) {
          if (isSolidTile(tx, ty)) return true;
        }
      }
      return false;
    }

    function moveAndCollide(entity, dt) {
      // Horizontal
      entity.x += entity.vx * dt;
      if (rectVsTile(entity.x, entity.y, entity.w, entity.h)) {
        if (entity.vx > 0) {
          entity.x = Math.floor((entity.x + entity.w) / TILE) * TILE - entity.w - 0.01;
        } else if (entity.vx < 0) {
          entity.x = Math.floor(entity.x / TILE + 1) * TILE + 0.01;
        }
        entity.vx = 0;
      }

      // Vertical
      entity.y += entity.vy * dt;
      entity.onGround = false;
      if (rectVsTile(entity.x, entity.y, entity.w, entity.h)) {
        if (entity.vy > 0) {
          entity.y = Math.floor((entity.y + entity.h) / TILE) * TILE - entity.h - 0.01;
          entity.onGround = true;
        } else if (entity.vy < 0) {
          entity.y = Math.floor(entity.y / TILE + 1) * TILE + 0.01;
        }
        entity.vy = 0;
      }
    }

    // --- Sprite Animation ---
    // Draws a simple animated character using shapes.
    function drawPlayerSprite(x, y, w, h, time, state, facing) {
      const bob = state === "run" ? Math.sin(time * 18) * 2 : 0;
      const armSwing = state === "run" ? Math.sin(time * 18) * 0.6 : 0;
      const legSwing = state === "run" ? Math.sin(time * 18) * 0.7 : 0;

      ctx.save();
      ctx.translate(x + w / 2, y + h / 2 + bob);
      ctx.scale(facing, 1);

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(0, h / 2 - 2, 16, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // body
      ctx.fillStyle = "#2d5bff";
      ctx.fillRect(-12, -10, 24, 24);

      // head
      ctx.fillStyle = "#ffd6b0";
      ctx.beginPath();
      ctx.arc(0, -24, 12, 0, Math.PI * 2);
      ctx.fill();

      // eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(4, -27, 2, 3);
      ctx.fillRect(-6, -27, 2, 3);

      // arms
      ctx.strokeStyle = "#ffd6b0";
      ctx.lineWidth = 4;
      ctx.lineCap = "round";

      ctx.beginPath();
      ctx.moveTo(-11, -4);
      ctx.lineTo(-20, 6 + armSwing * 4);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(11, -4);
      ctx.lineTo(20, 6 - armSwing * 4);
      ctx.stroke();

      // legs
      ctx.strokeStyle = "#1b1b1b";
      ctx.lineWidth = 5;

      ctx.beginPath();
      ctx.moveTo(-8, 14);
      ctx.lineTo(-10 + legSwing * 4, 26);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(8, 14);
      ctx.lineTo(10 - legSwing * 4, 26);
      ctx.stroke();

      // feet
      ctx.strokeStyle = "#444";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-10 + legSwing * 4, 26);
      ctx.lineTo(-4 + legSwing * 4, 26);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(10 - legSwing * 4, 26);
      ctx.lineTo(4 - legSwing * 4, 26);
      ctx.stroke();

      ctx.restore();
    }

    // --- Draw Map ---
    function drawMap() {
      const startX = Math.floor(camera.x / TILE) - 1;
      const startY = Math.floor(camera.y / TILE) - 1;
      const endX = Math.ceil((camera.x + canvas.width) / TILE) + 1;
      const endY = Math.ceil((camera.y + canvas.height) / TILE) + 1;

      for (let y = Math.max(0, startY); y < Math.min(level.length, endY); y++) {
        for (let x = Math.max(0, startX); x < Math.min(level[0].length, endX); x++) {
          const tile = level[y][x];
          if (tile !== "#") continue;

          const px = x * TILE - camera.x;
          const py = y * TILE - camera.y;

          // block
          ctx.fillStyle = "#5c4b3a";
          ctx.fillRect(px, py, TILE, TILE);

          // top highlight
          ctx.fillStyle = "#7b624c";
          ctx.fillRect(px, py, TILE, 8);

          // stone detail
          ctx.strokeStyle = "rgba(255,255,255,0.08)";
          ctx.strokeRect(px + 0.5, py + 0.5, TILE - 1, TILE - 1);
        }
      }
    }

    // --- Update ---
    let last = performance.now();
    function update(now) {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;

      // Input to movement
      const left = isDown("a", "arrowleft");
      const right = isDown("d", "arrowright");
      const jump = isDown(" ", "w", "arrowup");

      if (left) {
        player.vx = -player.moveSpeed;
        player.facing = -1;
      } else if (right) {
        player.vx = player.moveSpeed;
        player.facing = 1;
      } else {
        player.vx *= 0.82; // friction
        if (Math.abs(player.vx) < 10) player.vx = 0;
      }

      // Jump
      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Gravity
      player.vy += player.gravity * dt;
      if (player.vy > 1800) player.vy = 1800;

      // Move + collisions
      moveAndCollide(player, dt);

      // State
      if (!player.onGround) {
        player.state = player.vy < 0 ? "jump" : "fall";
      } else if (Math.abs(player.vx) > 30) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;

      // Camera follow
      const targetX = player.x + player.w / 2 - canvas.width / 2;
      const targetY = player.y + player.h / 2 - canvas.height / 2;
      camera.x += (targetX - camera.x) * 0.08;
      camera.y += (targetY - camera.y) * 0.08;

      // Clamp camera to world
      camera.x = Math.max(0, Math.min(camera.x, mapWidth - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, mapHeight - canvas.height));

      render();
      requestAnimationFrame(update);
    }

    // --- Render ---
    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // background clouds/parallax
      ctx.fillStyle = "rgba(255,255,255,0.35)";
      for (let i = 0; i < 12; i++) {
        const cx = ((i * 300) - camera.x * 0.2) % (canvas.width + 400) - 200;
        const cy = 60 + (i % 4) * 45;
        ctx.beginPath();
        ctx.ellipse(cx, cy, 50, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 28, cy + 4, 38, 14, 0, 0, Math.PI * 2);
        ctx.ellipse(cx - 28, cy + 4, 38, 14, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      drawMap();

      // Player
      drawPlayerSprite(
        player.x - camera.x,
        player.y - camera.y,
        player.w,
        player.h,
        player.animTime,
        player.state,
        player.facing
      );

      // debug info
      ctx.fillStyle = "rgba(0,0,0,0.3)";
      ctx.fillRect(10, canvas.height - 40, 220, 30);
      ctx.fillStyle = "white";
      ctx.fillText(`x:${player.x.toFixed(1)} y:${player.y.toFixed(1)} state:${player.state}`, 18, canvas.height - 20);
    }

    requestAnimationFrame(update);
  </script>
</body>
</html>
