<body>
  <div class="hud">
    Move: A/D or ←/→ | Jump: W/Space/↑
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // Physics constants
    const GRAVITY = 0.65;
    const MOVE_SPEED = 4.2;
    const JUMP_FORCE = 13.5;
    const FRICTION = 0.80;
    const MAX_FALL_SPEED = 18;

    // World
    const world = {
      width: 3200,
      height: 1200
    };

    // Platform definitions
    const platforms = [
      { x: 0, y: 500, w: 700, h: 40 },
      { x: 760, y: 430, w: 220, h: 30 },
      { x: 1050, y: 370, w: 220, h: 30 },
      { x: 1350, y: 450, w: 240, h: 30 },
      { x: 1700, y: 390, w: 180, h: 30 },
      { x: 2000, y: 340, w: 260, h: 30 },
      { x: 2400, y: 440, w: 220, h: 30 },
      { x: 2700, y: 380, w: 180, h: 30 },
      { x: 0, y: 900, w: 3200, h: 300 } // bottom floor
    ];

    const player = {
      x: 100,
      y: 300,
      w: 40,
      h: 56,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle"
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // Horizontal collision
      entity.x += entity.vx;
      for (const s of solids) {
        if (rectsIntersect(entity, s)) {
          if (entity.vx > 0) {
            entity.x = s.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = s.x + s.w;
          }
          entity.vx = 0;
        }
      }

      // Vertical collision
      entity.y += entity.vy;
      for (const s of solids) {
        if (rectsIntersect(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }

      entity.vy = Math.min(entity.vy, MAX_FALL_SPEED);
    }

    // Simple "sprite animation" using drawn frames
    function drawPlayer(ctx, p) {
      // Frame selection
      let frame = 0;
      if (p.state === "run") {
        frame = Math.floor(p.animTime / 8) % 4;
      } else if (p.state === "jump") {
        frame = 4;
      } else {
        frame = 5;
      }

      // Body colors based on frame/facing
      const skin = "#ffd2b0";
      const shirt = ["#ff4d4d", "#ff6f61", "#ff4d4d", "#ff6f61", "#ffb84d", "#4dd2ff"][frame];
      const pants = "#2d3a8c";
      const hair = "#4a2f1a";

      ctx.save();
      ctx.translate(p.x - camera.x, p.y - camera.y);

      // Flip if facing left
      if (p.facing === -1) {
        ctx.translate(p.w, 0);
        ctx.scale(-1, 1);
      }

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(p.w/2, p.h + 4, 18, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Head
      ctx.fillStyle = skin;
      ctx.fillRect(10, 4, 20, 18);

      // Hair
      ctx.fillStyle = hair;
      ctx.fillRect(10, 4, 20, 6);
      if (p.state === "run") {
        ctx.fillRect(8, 8, 4, 6);
        ctx.fillRect(28, 8, 4, 6);
      }

      // Eyes
      ctx.fillStyle = "#000";
      ctx.fillRect(14, 11, 2, 2);
      ctx.fillRect(22, 11, 2, 2);

      // Body
      ctx.fillStyle = shirt;
      ctx.fillRect(9, 22, 22, 18);

      // Arms
      ctx.fillStyle = skin;
      if (p.state === "run") {
        ctx.fillRect(3, 24, 6, 14);
        ctx.fillRect(31, 24, 6, 14);
      } else {
        ctx.fillRect(4, 24, 6, 16);
        ctx.fillRect(30, 24, 6, 16);
      }

      // Legs
      ctx.fillStyle = pants;
      if (p.state === "run") {
        ctx.fillRect(12, 40, 7, 16);
        ctx.fillRect(21, 40, 7, 16);
      } else if (p.state === "jump") {
        ctx.fillRect(11, 41, 7, 15);
        ctx.fillRect(22, 41, 7, 15);
      } else {
        ctx.fillRect(11, 40, 8, 16);
        ctx.fillRect(21, 40, 8, 16);
      }

      // Shoes
      ctx.fillStyle = "#111";
      ctx.fillRect(10, 54, 10, 3);
      ctx.fillRect(20, 54, 10, 3);

      ctx.restore();
    }

    function update() {
      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx = Math.max(player.vx - 0.5, -MOVE_SPEED);
        player.facing = -1;
      } else if (right) {
        player.vx = Math.min(player.vx + 0.5, MOVE_SPEED);
        player.facing = 1;
      } else {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      if (jump && player.onGround) {
        player.vy = -JUMP_FORCE;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY;

      // Apply collisions
      resolveCollisions(player, platforms);

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 0.4) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime++;

      // Camera follows player
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      // Clamp camera to world
      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function drawBackground() {
      // Parallax mountains
      const skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
      skyGrad.addColorStop(0, "#7ec8ff");
      skyGrad.addColorStop(1, "#dff3ff");
      ctx.fillStyle = skyGrad;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Far hills
      ctx.fillStyle = "#86b86a";
      for (let i = 0; i < 12; i++) {
        const x = ((i * 300) - (camera.x * 0.3)) % 3600 - 300;
        ctx.beginPath();
        ctx.moveTo(x, 420);
        ctx.quadraticCurveTo(x + 80, 320, x + 160, 420);
        ctx.quadraticCurveTo(x + 220, 360, x + 320, 420);
        ctx.closePath();
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of platforms) {
        const sx = p.x - camera.x;
        const sy = p.y - camera.y;

        // Only draw visible platforms
        if (sx + p.w < -50 || sx > canvas.width + 50 || sy + p.h < -50 || sy > canvas.height + 50) continue;

        ctx.fillStyle = "#7a4f2a";
        ctx.fillRect(sx, sy, p.w, p.h);

        ctx.fillStyle = "#5fbf4a";
        ctx.fillRect(sx, sy, p.w, 8);

        ctx.fillStyle = "rgba(255,255,255,0.12)";
        ctx.fillRect(sx, sy, p.w, 3);
      }
    }

    function render() {
      drawBackground();
      drawPlatforms();
      drawPlayer(ctx, player);
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    // Start on top of first platform
    player.y = platforms[0].y - player.h;
    player.onGround = true;

    loop();
  </script>
</body>
</html>
