## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      font-family: Arial, sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 12px;
      left: 12px;
      color: white;
      font-size: 18px;
      text-shadow: 2px 2px 0 #000;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud" id="hud">Coins: 0 | Lives: 3</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const hud = document.getElementById("hud");

    const GRAVITY = 0.5;
    const FRICTION = 0.85;
    const MOVE_SPEED = 0.7;
    const MAX_SPEED = 6;
    const JUMP_POWER = 11;

    const keys = {};
    window.addEventListener("keydown", e => keys[e.code] = true);
    window.addEventListener("keyup", e => keys[e.code] = false);

    class SpriteAnimator {
      constructor(frameCount, frameWidth, frameHeight, frameRate, color1, color2) {
        this.frameCount = frameCount;
        this.frameWidth = frameWidth;
        this.frameHeight = frameHeight;
        this.frameRate = frameRate;
        this.color1 = color1;
        this.color2 = color2;
        this.frame = 0;
        this.timer = 0;
      }

      update() {
        this.timer++;
        if (this.timer >= this.frameRate) {
          this.timer = 0;
          this.frame = (this.frame + 1) % this.frameCount;
        }
      }

      draw(ctx, x, y, w, h, facing = 1) {
        // Placeholder animated sprite using simple shapes.
        // Replace this with image sprite sheet rendering if desired.
        ctx.save();
        ctx.translate(x + w / 2, y + h / 2);
        ctx.scale(facing, 1);
        ctx.translate(-w / 2, -h / 2);

        const legOffset = this.frame % 2 === 0 ? 0 : 3;
        ctx.fillStyle = this.color1;
        ctx.fillRect(8, 8, w - 16, h - 16);

        ctx.fillStyle = this.color2;
        ctx.fillRect(12, 10, w - 24, 10);

        // eyes
        ctx.fillStyle = "#000";
        ctx.fillRect(18, 18, 4, 4);
        ctx.fillRect(w - 22, 18, 4, 4);

        // legs animation
        ctx.fillStyle = "#333";
        ctx.fillRect(14, h - 10, 8, 10 - legOffset);
        ctx.fillRect(w - 22, h - 10, 8, 10 + legOffset);

        // arms
        ctx.fillRect(4, 28, 8, 6);
        ctx.fillRect(w - 12, 28, 8, 6);

        ctx.restore();
      }
    }

    class Entity {
      constructor(x, y, w, h) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.vx = 0;
        this.vy = 0;
        this.onGround = false;
      }

      get left() { return this.x; }
      get right() { return this.x + this.w; }
      get top() { return this.y; }
      get bottom() { return this.y + this.h; }

      intersects(other) {
        return !(
          this.right <= other.left ||
          this.left >= other.right ||
          this.bottom <= other.top ||
          this.top >= other.bottom
        );
      }
    }

    class Player extends Entity {
      constructor(x, y) {
        super(x, y, 32, 48);
        this.speedX = 0;
        this.jumpLock = false;
        this.facing = 1;
        this.anim = new SpriteAnimator(4, 32, 48, 8, "#2c7be5", "#65a6ff");
        this.lives = 3;
        this.coins = 0;
        this.invincibleTimer = 0;
      }

      update(platforms, coins, enemies) {
        const left = keys["ArrowLeft"] || keys["KeyA"];
        const right = keys["ArrowRight"] || keys["KeyD"];
        const jump = keys["Space"] || keys["ArrowUp"] || keys["KeyW"];

        if (left) {
          this.vx -= MOVE_SPEED;
          this.facing = -1;
        }
        if (right) {
          this.vx += MOVE_SPEED;
          this.facing = 1;
        }

        if (!left && !right) {
          this.vx *= FRICTION;
        }

        this.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, this.vx));

        if (jump && this.onGround && !this.jumpLock) {
          this.vy = -JUMP_POWER;
          this.onGround = false;
          this.jumpLock = true;
        }

        if (!jump) this.jumpLock = false;

        this.vy += GRAVITY;

        this.moveAndCollide(platforms);

        // coin pickup
        for (let i = coins.length - 1; i >= 0; i--) {
          if (this.intersects(coins[i])) {
            coins.splice(i, 1);
            this.coins++;
          }
        }

        // enemy collision
        if (this.invincibleTimer > 0) this.invincibleTimer--;
        for (const enemy of enemies) {
          if (this.intersects(enemy) && this.invincibleTimer === 0) {
            this.lives--;
            this.invincibleTimer = 90;
            this.x = 100;
            this.y = 100;
            this.vx = 0;
            this.vy = 0;
            break;
          }
        }

        this.anim.update();
      }

      moveAndCollide(platforms) {
        // Horizontal
        this.x += this.vx;
        for (const p of platforms) {
          if (this.intersects(p)) {
            if (this.vx > 0) this.x = p.x - this.w;
            else if (this.vx < 0) this.x = p.x + p.w;
            this.vx = 0;
          }
        }

        // Vertical
        this.y += this.vy;
        this.onGround = false;
        for (const p of platforms) {
          if (this.intersects(p)) {
            if (this.vy > 0) {
              this.y = p.y - this.h;
              this.vy = 0;
              this.onGround = true;
            } else if (this.vy < 0) {
              this.y = p.y + p.h;
              this.vy = 0;
            }
          }
        }
      }

      draw(ctx, cameraX, cameraY) {
        if (this.invincibleTimer > 0 && Math.floor(this.invincibleTimer / 5) % 2 === 0) return;
        this.anim.draw(ctx, this.x - cameraX, this.y - cameraY, this.w, this.h, this.facing);
      }
    }

    class Platform extends Entity {
      draw(ctx, cameraX, cameraY) {
        ctx.fillStyle = "#5c3d2e";
        ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);

        ctx.fillStyle = "#7a533c";
        ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, 8);
      }
    }

    class Coin extends Entity {
      constructor(x, y) {
        super(x, y, 18, 18);
        this.t = 0;
      }
      update() {
        this.t++;
      }
      draw(ctx, cameraX, cameraY) {
        const pulse = 1 + Math.sin(this.t * 0.2) * 0.15;
        ctx.save();
        ctx.translate(this.x - cameraX + this.w / 2, this.y - cameraY + this.h / 2);
        ctx.scale(pulse, 1);
        ctx.fillStyle = "#ffd700";
        ctx.beginPath();
        ctx.arc(0, 0, 8, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#fff4a3";
        ctx.beginPath();
        ctx.arc(-3, -2, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    }

    class Enemy extends Entity {
      constructor(x, y, minX, maxX) {
        super(x, y, 32, 32);
        this.minX = minX;
        this.maxX = maxX;
        this.vx = 1.2;
      }

      update(platforms) {
        this.vy += GRAVITY;
        this.x += this.vx;

        if (this.x < this.minX) {
          this.x = this.minX;
          this.vx *= -1;
        }
        if (this.x + this.w > this.maxX) {
          this.x = this.maxX - this.w;
          this.vx *= -1;
        }

        this.y += this.vy;
        for (const p of platforms) {
          if (this.intersects(p)) {
            if (this.vy > 0) {
              this.y = p.y - this.h;
              this.vy = 0;
            }
          }
        }
      }

      draw(ctx, cameraX, cameraY) {
        ctx.fillStyle = "#e74c3c";
        ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);

        ctx.fillStyle = "#fff";
        ctx.fillRect(this.x - cameraX + 7, this.y - cameraY + 10, 6, 6);
        ctx.fillRect(this.x - cameraX + 19, this.y - cameraY + 10, 6, 6);

        ctx.fillStyle = "#000";
        ctx.fillRect(this.x - cameraX + 9, this.y - cameraY + 12, 2, 2);
        ctx.fillRect(this.x - cameraX + 21, this.y - cameraY + 12, 2, 2);
      }
    }

    const platforms = [
      new Platform(0, 500, 1800, 40),
      new Platform(220, 420, 140, 20),
      new Platform(420, 360, 120, 20),
      new Platform(590, 310, 140, 20),
      new Platform(790, 400, 160, 20),
      new Platform(1030, 350, 180, 20),
      new Platform(1300, 430, 220, 20),
    ];

    const coins = [
      new Coin(260, 380),
      new Coin(455, 320),
      new Coin(620, 270),
      new Coin(850, 370),
      new Coin(1080, 320),
      new Coin(1360, 400),
    ];

    const enemies = [
      new Enemy(700, 470, 650, 900),
      new Enemy(1150, 470, 1100, 1250),
    ];

    const player = new Player(100, 100);

    let cameraX = 0;
    let cameraY = 0;

    function update() {
      if (player.lives <= 0) {
        hud.textContent = "Game Over - Refresh to restart";
        return;
      }

      player.update(platforms, coins, enemies);
      for (const c of coins) c.update();
      for (const e of enemies) e.update(platforms);

      cameraX = Math.max(0, Math.min(player.x - canvas.width / 2 + player.w / 2, 1800 - canvas.width));
      cameraY = 0;

      hud.textContent = `Coins: ${player.coins} | Lives: ${player.lives}`;
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#b8e986";
      ctx.fillRect(0, 460 - cameraY * 0.2, canvas.width, 80);

      ctx.fillStyle = "#8fd18b";
      for (let i = -1; i < 10; i++) {
        ctx.beginPath();
        ctx.arc(i * 250 - (cameraX * 0.2) % 250, 480, 120, Math.PI, 0);
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      const cloudX = (cameraX * 0.5) % 1100;
      ctx.beginPath();
      ctx.arc(150 - cloudX, 90, 25, 0, Math.PI * 2);
      ctx.arc(180 - cloudX, 75, 32, 0, Math.PI * 2);
      ctx.arc(215 - cloudX, 90, 25, 0, Math.PI * 2);
      ctx.fill();

      ctx.beginPath();
      ctx.arc(650 - cloudX, 130, 22, 0, Math.PI * 2);
      ctx.arc(680 - cloudX, 118, 30, 0, Math.PI * 2);
      ctx.arc(715 - cloudX, 130, 22, 0, Math.PI * 2);
      ctx.fill();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      for (const p of platforms) p.draw(ctx, cameraX, cameraY);
      for (const c of coins) c.draw(ctx, cameraX, cameraY);
      for (const e of enemies) e.draw(ctx, cameraX, cameraY);
      player.draw(ctx, cameraX, cameraY);
    }

    function gameLoop() {
      update();
      draw();
      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
