</head>
<body>
<canvas id="game"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

// Input
const keys = {};
window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

// World constants
const GRAVITY = 1800;
const MOVE_SPEED = 380;
const JUMP_VELOCITY = 780;
const FRICTION = 0.82;

// Player
const player = {
  x: 100,
  y: 100,
  w: 48,
  h: 64,
  vx: 0,
  vy: 0,
  onGround: false,
  facing: 1,
  animTime: 0,
  animFrame: 0
};

// Platforms
const platforms = [
  { x: 0, y: 560, w: 1400, h: 40 },
  { x: 200, y: 460, w: 180, h: 20 },
  { x: 450, y: 390, w: 180, h: 20 },
  { x: 700, y: 320, w: 180, h: 20 },
  { x: 980, y: 430, w: 220, h: 20 },
  { x: 1250, y: 500, w: 180, h: 20 },
  { x: 1500, y: 380, w: 220, h: 20 },
  { x: 1820, y: 300, w: 200, h: 20 },
];

// Decorative "sprite animation" frames drawn manually
const spriteFrames = [
  [
    [12, 8, 24, 20, "#3b82f6"], // torso
    [16, 28, 16, 18, "#facc15"], // legs
    [8, 10, 8, 8, "#f8c9a0"],   // hand
    [32, 10, 8, 8, "#f8c9a0"],  // hand
    [16, 0, 16, 12, "#f8c9a0"], // head
  ],
  [
    [12, 8, 24, 20, "#2563eb"],
    [14, 28, 14, 18, "#facc15"],
    [6, 12, 8, 8, "#f8c9a0"],
    [34, 12, 8, 8, "#f8c9a0"],
    [16, 0, 16, 12, "#f8c9a0"],
  ],
  [
    [12, 8, 24, 20, "#60a5fa"],
    [18, 28, 14, 18, "#facc15"],
    [8, 8, 8, 8, "#f8c9a0"],
    [32, 8, 8, 8, "#f8c9a0"],
    [16, 0, 16, 12, "#f8c9a0"],
  ],
  [
    [12, 8, 24, 20, "#1d4ed8"],
    [16, 28, 16, 18, "#facc15"],
    [10, 10, 8, 8, "#f8c9a0"],
    [30, 10, 8, 8, "#f8c9a0"],
    [16, 0, 16, 12, "#f8c9a0"],
  ]
];

function aabbIntersect(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

// Physics & collision
function update(dt) {
  // Horizontal input
  let move = 0;
  if (keys["arrowleft"] || keys["a"]) move -= 1;
  if (keys["arrowright"] || keys["d"]) move += 1;

  if (move !== 0) {
    player.vx = move * MOVE_SPEED;
    player.facing = move;
  } else {
    player.vx *= FRICTION;
    if (Math.abs(player.vx) < 2) player.vx = 0;
  }

  // Jump
  if ((keys[" "] || keys["arrowup"] || keys["w"]) && player.onGround) {
    player.vy = -JUMP_VELOCITY;
    player.onGround = false;
  }

  // Gravity
  player.vy += GRAVITY * dt;

  // Move X and resolve
  player.x += player.vx * dt;
  for (const p of platforms) {
    if (aabbIntersect(player, p)) {
      if (player.vx > 0) player.x = p.x - player.w;
      else if (player.vx < 0) player.x = p.x + p.w;
      player.vx = 0;
    }
  }

  // Move Y and resolve
  player.y += player.vy * dt;
  player.onGround = false;
  for (const p of platforms) {
    if (aabbIntersect(player, p)) {
      if (player.vy > 0) {
        player.y = p.y - player.h;
        player.vy = 0;
        player.onGround = true;
      } else if (player.vy < 0) {
        player.y = p.y + p.h;
        player.vy = 0;
      }
    }
  }

  // Keep inside world bounds
  if (player.x < 0) player.x = 0;
  if (player.x + player.w > 2200) player.x = 2200 - player.w;

  // Animation
  const speed = Math.abs(player.vx);
  if (player.onGround && speed > 10) {
    player.animTime += dt * 12;
    player.animFrame = Math.floor(player.animTime) % spriteFrames.length;
  } else {
    player.animFrame = 0;
    player.animTime = 0;
  }
}

// Draw
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const cameraX = Math.max(
    0,
    Math.min(player.x + player.w / 2 - canvas.width / 2, 2200 - canvas.width)
  );
  const cameraY = 0;

  // Background mountains
  ctx.fillStyle = "#94a3b8";
  for (let i = 0; i < 10; i++) {
    const mx = i * 240 - (cameraX * 0.3) % 240;
    ctx.beginPath();
    ctx.moveTo(mx, 500);
    ctx.lineTo(mx + 120, 260);
    ctx.lineTo(mx + 240, 500);
    ctx.fill();
  }

  // Platforms
  ctx.fillStyle = "#5b4636";
  for (const p of platforms) {
    ctx.fillRect(p.x - cameraX, p.y - cameraY, p.w, p.h);
    ctx.fillStyle = "#7c5c44";
    ctx.fillRect(p.x - cameraX, p.y - cameraY, p.w, 6);
    ctx.fillStyle = "#5b4636";
  }

  // Player shadow
  ctx.fillStyle = "rgba(0,0,0,0.15)";
  ctx.beginPath();
  ctx.ellipse(
    player.x - cameraX + player.w / 2,
    player.y - cameraY + player.h + 8,
    22,
    8,
    0,
    0,
    Math.PI * 2
  );
  ctx.fill();

  // Player sprite
  const frame = player.onGround && Math.abs(player.vx) > 10
    ? spriteFrames[player.animFrame]
    : spriteFrames[0];

  ctx.save();
  ctx.translate(player.x - cameraX, player.y - cameraY);

  if (player.facing < 0) {
    ctx.translate(player.w, 0);
    ctx.scale(-1, 1);
  }

  // Draw sprite parts
  for (const part of frame) {
    const [x, y, w, h, color] = part;
    ctx.fillStyle = color;
    ctx.fillRect(x, y, w, h);
  }

  // Simple eye
  ctx.fillStyle = "#111";
  ctx.fillRect(22, 5, 3, 3);

  ctx.restore();

  // HUD
  ctx.fillStyle = "#111827";
  ctx.font = "20px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys", 20, 30);
  ctx.fillText("Jump: W / Up / Space", 20, 55);
}

let last = performance.now();
function loop(now) {
  const dt = Math.min((now - last) / 1000, 0.033);
  last = now;
  update(dt);
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
</script>
</body>
</html>
