## `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

const keys = {};
window.addEventListener("keydown", (e) => (keys[e.code] = true));
window.addEventListener("keyup", (e) => (keys[e.code] = false));

class Sprite {
  constructor(imagePaths, frameTime = 0.12) {
    this.images = imagePaths.map((src) => {
      const img = new Image();
      img.src = src;
      return img;
    });
    this.frameTime = frameTime;
    this.time = 0;
    this.frame = 0;
  }

  update(dt) {
    this.time += dt;
    if (this.time >= this.frameTime) {
      this.time = 0;
      this.frame = (this.frame + 1) % this.images.length;
    }
  }

  get current() {
    return this.images[this.frame];
  }
}

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 48;
    this.h = 64;

    this.vx = 0;
    this.vy = 0;

    this.speed = 260;
    this.jumpForce = 620;
    this.gravity = 1800;
    this.maxFallSpeed = 1200;

    this.onGround = false;
    this.facing = 1;

    this.idleSprite = new Sprite([
      "assets/player_idle.png"
    ]);

    this.runSprite = new Sprite([
      "assets/player_run_0.png",
      "assets/player_run_1.png",
      "assets/player_run_2.png",
      "assets/player_run_3.png"
    ], 0.08);

    this.currentSprite = this.idleSprite;
  }

  update(dt, platforms) {
    // Input
    let move = 0;
    if (keys["ArrowLeft"] || keys["KeyA"]) move -= 1;
    if (keys["ArrowRight"] || keys["KeyD"]) move += 1;

    this.vx = move * this.speed;
    if (move !== 0) this.facing = Math.sign(move);

    if ((keys["Space"] || keys["ArrowUp"] || keys["KeyW"]) && this.onGround) {
      this.vy = -this.jumpForce;
      this.onGround = false;
    }

    // Gravity
    this.vy += this.gravity * dt;
    if (this.vy > this.maxFallSpeed) this.vy = this.maxFallSpeed;

    // Horizontal movement and collision
    this.x += this.vx * dt;
    for (const p of platforms) {
      if (rectsOverlap(this, p)) {
        if (this.vx > 0) this.x = p.x - this.w;
        else if (this.vx < 0) this.x = p.x + p.w;
      }
    }

    // Vertical movement and collision
    this.y += this.vy * dt;
    this.onGround = false;

    for (const p of platforms) {
      if (rectsOverlap(this, p)) {
        if (this.vy > 0) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
      }
    }

    // Animation
    if (Math.abs(this.vx) > 1 && this.onGround) {
      this.currentSprite = this.runSprite;
    } else {
      this.currentSprite = this.idleSprite;
    }
    this.currentSprite.update(dt);
  }

  draw(ctx, cameraX, cameraY) {
    const img = this.currentSprite.current;
    if (img && img.complete && img.naturalWidth > 0) {
      ctx.save();
      ctx.translate(this.x - cameraX, this.y - cameraY);
      if (this.facing === -1) {
        ctx.scale(-1, 1);
        ctx.drawImage(img, -this.w, 0, this.w, this.h);
      } else {
        ctx.drawImage(img, 0, 0, this.w, this.h);
      }
      ctx.restore();
    } else {
      // Fallback rectangle if image not loaded
      ctx.fillStyle = "#ffcc66";
      ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);
    }
  }
}

function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

// Simple level
const platforms = [
  { x: 0, y: 560, w: 3000, h: 80 },
  { x: 250, y: 450, w: 180, h: 24 },
  { x: 500, y: 380, w: 180, h: 24 },
  { x: 770, y: 320, w: 180, h: 24 },
  { x: 1050, y: 430, w: 220, h: 24 },
  { x: 1400, y: 360, w: 220, h: 24 },
  { x: 1750, y: 470, w: 260, h: 24 },
  { x: 2150, y: 400, w: 250, h: 24 },
  { x: 2550, y: 330, w: 220, h: 24 }
];

const player = new Player(100, 100);

let cameraX = 0;
let cameraY = 0;

let last = performance.now();

function update(dt) {
  player.update(dt, platforms);

  cameraX = player.x + player.w / 2 - canvas.width / 2;
  cameraY = player.y + player.h / 2 - canvas.height / 2;

  // clamp camera
  cameraX = Math.max(0, Math.min(cameraX, 3000 - canvas.width));
  cameraY = Math.max(0, Math.min(cameraY, 640 - canvas.height));
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Background parallax-ish effect
  ctx.fillStyle = "#9be7ff";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Platforms
  for (const p of platforms) {
    ctx.fillStyle = "#5c4b3b";
    ctx.fillRect(p.x - cameraX, p.y - cameraY, p.w, p.h);

    ctx.fillStyle = "#7d6652";
    ctx.fillRect(p.x - cameraX, p.y - cameraY, p.w, 6);
  }

  // Player
  player.draw(ctx, cameraX, cameraY);

  // Debug text
  ctx.fillStyle = "rgba(0,0,0,0.7)";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 16, 24);
}

function loop(now) {
  const dt = Math.min((now - last) / 1000, 0.033);
  last = now;

  update(dt);
  draw();

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
