## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer Prototype</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 6px;
      font-size: 14px;
      line-height: 1.5;
    }
  </style>
</head>
<body>
  <div class="hud">
    <b>Controls</b><br>
    A/D or Arrow Keys = Move<br>
    W / Space / Up = Jump
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    window.addEventListener("resize", () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    });

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    const GRAVITY = 1800;
    const MOVE_ACCEL = 2200;
    const FRICTION = 1800;
    const MAX_SPEED = 320;
    const JUMP_VELOCITY = 720;

    class Platform {
      constructor(x, y, w, h) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
      }

      draw(cameraX, cameraY) {
        ctx.fillStyle = "#3f4d5a";
        ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);
        ctx.fillStyle = "#5f7384";
        ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, 8);
      }
    }

    class Entity {
      constructor(x, y, w, h) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.vx = 0;
        this.vy = 0;
        this.onGround = false;
      }

      get left() { return this.x; }
      get right() { return this.x + this.w; }
      get top() { return this.y; }
      get bottom() { return this.y + this.h; }
    }

    class Player extends Entity {
      constructor(x, y) {
        super(x, y, 42, 58);
        this.facing = 1;
        this.animTime = 0;
        this.animState = "idle";
      }

      update(dt, platforms) {
        const left = keys["a"] || keys["arrowleft"];
        const right = keys["d"] || keys["arrowright"];
        const jump = keys["w"] || keys[" "] || keys["arrowup"];

        if (left) {
          this.vx -= MOVE_ACCEL * dt;
          this.facing = -1;
        }
        if (right) {
          this.vx += MOVE_ACCEL * dt;
          this.facing = 1;
        }

        if (!left && !right) {
          if (this.vx > 0) this.vx = Math.max(0, this.vx - FRICTION * dt);
          if (this.vx < 0) this.vx = Math.min(0, this.vx + FRICTION * dt);
        }

        this.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, this.vx));

        if (jump && this.onGround && !this.jumpHeld) {
          this.vy = -JUMP_VELOCITY;
          this.onGround = false;
        }
        this.jumpHeld = jump;

        this.vy += GRAVITY * dt;

        this.moveAndCollide(dt, platforms);

        if (Math.abs(this.vx) > 5 && this.onGround) this.animState = "run";
        else if (!this.onGround) this.animState = "jump";
        else this.animState = "idle";

        this.animTime += dt;
      }

      moveAndCollide(dt, platforms) {
        this.x += this.vx * dt;
        this.resolveCollisions(platforms, "horizontal");

        this.y += this.vy * dt;
        this.onGround = false;
        this.resolveCollisions(platforms, "vertical");
      }

      resolveCollisions(platforms, axis) {
        for (const p of platforms) {
          if (
            this.right > p.x &&
            this.left < p.x + p.w &&
            this.bottom > p.y &&
            this.top < p.y + p.h
          ) {
            if (axis === "horizontal") {
              if (this.vx > 0) this.x = p.x - this.w;
              if (this.vx < 0) this.x = p.x + p.w;
              this.vx = 0;
            } else {
              if (this.vy > 0) {
                this.y = p.y - this.h;
                this.vy = 0;
                this.onGround = true;
              } else if (this.vy < 0) {
                this.y = p.y + p.h;
                this.vy = 0;
              }
            }
          }
        }
      }

      draw(cameraX, cameraY) {
        const x = this.x - cameraX;
        const y = this.y - cameraY;

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)";
        ctx.beginPath();
        ctx.ellipse(x + this.w / 2, y + this.h + 8, 20, 6, 0, 0, Math.PI * 2);
        ctx.fill();

        // Body animation
        const t = this.animTime;
        let bob = 0;
        let legSwing = 0;
        let armSwing = 0;

        if (this.animState === "run") {
          bob = Math.sin(t * 14) * 2;
          legSwing = Math.sin(t * 14) * 10;
          armSwing = Math.sin(t * 14 + Math.PI) * 8;
        } else if (this.animState === "jump") {
          bob = -2;
          legSwing = 0;
          armSwing = -10;
        }

        ctx.save();
        ctx.translate(x + this.w / 2, y + this.h / 2 + bob);
        ctx.scale(this.facing, 1);
        ctx.translate(-this.w / 2, -this.h / 2);

        // Head
        ctx.fillStyle = "#f2c18d";
        ctx.fillRect(13, 4, 16, 16);

        // Hair/hat
        ctx.fillStyle = "#4b2e1f";
        ctx.fillRect(12, 2, 18, 6);

        // Body
        ctx.fillStyle = "#2d6cdf";
        ctx.fillRect(11, 20, 20, 18);

        // Arms
        ctx.strokeStyle = "#f2c18d";
        ctx.lineWidth = 5;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(12, 24);
        ctx.lineTo(4, 30 + armSwing * 0.1);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(30, 24);
        ctx.lineTo(38, 30 - armSwing * 0.1);
        ctx.stroke();

        // Legs
        ctx.strokeStyle = "#1c1c1c";
        ctx.lineWidth = 6;
        ctx.beginPath();
        ctx.moveTo(17, 38);
        ctx.lineTo(10 + legSwing * 0.05, 54);
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(25, 38);
        ctx.lineTo(32 - legSwing * 0.05, 54);
        ctx.stroke();

        // Shoes
        ctx.fillStyle = "#c0392b";
        ctx.fillRect(7 + legSwing * 0.03, 52, 10, 4);
        ctx.fillRect(25 - legSwing * 0.03, 52, 10, 4);

        ctx.restore();
      }
    }

    class Enemy extends Entity {
      constructor(x, y, minX, maxX) {
        super(x, y, 40, 40);
        this.minX = minX;
        this.maxX = maxX;
        this.vx = 100;
        this.animTime = 0;
      }

      update(dt, platforms) {
        this.vy += GRAVITY * dt;
        this.x += this.vx * dt;
        this.resolve(platforms, "horizontal");
        this.y += this.vy * dt;
        this.onGround = false;
        this.resolve(platforms, "vertical");

        if (this.x < this.minX) {
          this.x = this.minX;
          this.vx *= -1;
        }
        if (this.x > this.maxX) {
          this.x = this.maxX;
          this.vx *= -1;
        }

        this.animTime += dt;
      }

      resolve(platforms, axis) {
        for (const p of platforms) {
          if (
            this.right > p.x &&
            this.left < p.x + p.w &&
            this.bottom > p.y &&
            this.top < p.y + p.h
          ) {
            if (axis === "horizontal") {
              if (this.vx > 0) this.x = p.x - this.w;
              if (this.vx < 0) this.x = p.x + p.w;
              this.vx *= -1;
            } else {
              if (this.vy > 0) {
                this.y = p.y - this.h;
                this.vy = 0;
                this.onGround = true;
              } else if (this.vy < 0) {
                this.y = p.y + p.h;
                this.vy = 0;
              }
            }
          }
        }
      }

      draw(cameraX, cameraY) {
        const x = this.x - cameraX;
        const y = this.y - cameraY;
        const pulse = 1 + Math.sin(this.animTime * 8) * 0.05;

        ctx.save();
        ctx.translate(x + this.w / 2, y + this.h / 2);
        ctx.scale(pulse, pulse);
        ctx.translate(-this.w / 2, -this.h / 2);

        ctx.fillStyle = "#aa2d2d";
        ctx.fillRect(0, 0, 40, 40);

        ctx.fillStyle = "#fff";
        ctx.fillRect(9, 10, 8, 8);
        ctx.fillRect(23, 10, 8, 8);

        ctx.fillStyle = "#111";
        ctx.fillRect(12, 13, 3, 3);
        ctx.fillRect(26, 13, 3, 3);

        ctx.fillStyle = "#7d1f1f";
        ctx.fillRect(8, 28, 24, 6);

        ctx.restore();
      }
    }

    const platforms = [
      new Platform(-300, 650, 2000, 60),
      new Platform(200, 540, 180, 24),
      new Platform(480, 470, 160, 24),
      new Platform(760, 390, 220, 24),
      new Platform(1130, 520, 220, 24),
      new Platform(1450, 430, 220, 24),
      new Platform(1820, 560, 260, 24),
      new Platform(2200, 480, 240, 24),
    ];

    const player = new Player(100, 500);
    const enemies = [
      new Enemy(560, 430, 500, 680),
      new Enemy(1180, 480, 1130, 1320),
      new Enemy(2250, 440, 2200, 2380),
    ];

    let cameraX = 0;
    let cameraY = 0;
    let lastTime = performance.now();

    function drawBackground() {
      const horizonY = canvas.height * 0.65;

      // distant hills
      ctx.fillStyle = "#b1e3a1";
      for (let i = -1; i < 6; i++) {
        ctx.beginPath();
        ctx.ellipse(i * 400 - (cameraX * 0.2), horizonY + 80, 180, 80, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.75)";
      const cloudOffsets = [100, 420, 760, 1200, 1600];
      for (let i = 0; i < cloudOffsets.length; i++) {
        const cx = cloudOffsets[i] - cameraX * 0.4;
        const cy = 80 + (i % 2) * 40;
        ctx.beginPath();
        ctx.ellipse(cx, cy, 40, 22, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 28, cy - 10, 34, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 55, cy, 42, 24, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function update(dt) {
      player.update(dt, platforms);
      for (const enemy of enemies) enemy.update(dt, platforms);

      cameraX = player.x + player.w / 2 - canvas.width / 2;
      cameraY = player.y + player.h / 2 - canvas.height / 2;

      cameraX = Math.max(0, cameraX);
      cameraY = Math.max(0, cameraY);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // platforms
      for (const p of platforms) p.draw(cameraX, cameraY);

      // enemies
      for (const enemy of enemies) enemy.draw(cameraX, cameraY);

      // player
      player.draw(cameraX, cameraY);

      // debug ground line
      ctx.strokeStyle = "rgba(255,255,255,0.2)";
      ctx.beginPath();
      ctx.moveTo(0, 650 - cameraY);
      ctx.lineTo(canvas.width, 650 - cameraY);
      ctx.stroke();
    }

    function loop(now) {
      const dt = Math.min(0.033, (now - lastTime) / 1000);
      lastTime = now;

      update(dt);
      render();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

