## Single-file implementation

Save this as `index.html` and open it in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer Prototype</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      height: 100%;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }

    .hud {
      position: fixed;
      top: 12px;
      left: 12px;
      color: white;
      background: rgba(0, 0, 0, 0.35);
      padding: 10px 12px;
      border-radius: 8px;
      font-size: 14px;
      line-height: 1.4;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    <strong>Controls:</strong><br>
    A/D or ←/→ = move<br>
    Space/W/↑ = jump
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {
      left: false,
      right: false,
      jump: false,
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    const WORLD = {
      gravity: 2200,
      floorY: 900,
      width: 2600,
      height: 1000,
    };

    const platforms = [
      { x: 0, y: 860, w: 2600, h: 40 },
      { x: 180, y: 720, w: 220, h: 22 },
      { x: 470, y: 640, w: 180, h: 22 },
      { x: 760, y: 560, w: 240, h: 22 },
      { x: 1100, y: 620, w: 200, h: 22 },
      { x: 1390, y: 700, w: 240, h: 22 },
      { x: 1700, y: 580, w: 160, h: 22 },
      { x: 1930, y: 500, w: 240, h: 22 },
      { x: 2250, y: 620, w: 170, h: 22 },
    ];

    const player = {
      x: 80,
      y: 700,
      w: 42,
      h: 60,
      vx: 0,
      vy: 0,
      speed: 520,
      jumpPower: 820,
      grounded: false,
      facing: 1,
      animTime: 0,
      frame: 0,
    };

    const camera = {
      x: 0,
      y: 0
    };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resetPlayer() {
      player.x = 80;
      player.y = 700;
      player.vx = 0;
      player.vy = 0;
    }

    function update(dt) {
      const accel = 2400;
      const friction = 1800;
      const maxSpeed = player.speed;

      if (keys.left) {
        player.vx -= accel * dt;
        player.facing = -1;
      }
      if (keys.right) {
        player.vx += accel * dt;
        player.facing = 1;
      }

      if (!keys.left && !keys.right) {
        if (player.vx > 0) {
          player.vx = Math.max(0, player.vx - friction * dt);
        } else if (player.vx < 0) {
          player.vx = Math.min(0, player.vx + friction * dt);
        }
      }

      player.vx = Math.max(-maxSpeed, Math.min(maxSpeed, player.vx));

      if (keys.jump && player.grounded) {
        player.vy = -player.jumpPower;
        player.grounded = false;
      }

      player.vy += WORLD.gravity * dt;

      // Horizontal movement and collision
      player.x += player.vx * dt;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical movement and collision
      player.y += player.vy * dt;
      player.grounded = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.grounded = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Clamp to world bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > WORLD.width) player.x = WORLD.width - player.w;

      // Fall reset
      if (player.y > WORLD.height + 300) {
        resetPlayer();
      }

      // Animation
      const moving = Math.abs(player.vx) > 20;
      if (moving && player.grounded) {
        player.animTime += dt;
        player.frame = Math.floor(player.animTime * 12) % 4;
      } else {
        player.frame = 0;
        player.animTime = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(WORLD.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(WORLD.height - canvas.height, camera.y));
    }

    function drawBackground() {
      // Parallax sky clouds and distant hills
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const parallaxX = camera.x * 0.3;

      ctx.fillStyle = "rgba(255,255,255,0.35)";
      for (let i = 0; i < 10; i++) {
        const x = ((i * 320) - (parallaxX % 320)) - 60;
        const y = 80 + (i % 3) * 45;
        ctx.beginPath();
        ctx.ellipse(x, y, 55, 22, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 35, y - 8, 45, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 70, y, 52, 20, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = "#9ad07a";
      for (let i = 0; i < 8; i++) {
        const hillX = ((i * 420) - (camera.x * 0.5 % 420)) - 100;
        ctx.beginPath();
        ctx.ellipse(hillX + 150, canvas.height - 120, 170, 90, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5b3a29";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#7cc957";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);
    }

    function drawPlayer() {
      const sx = player.x - camera.x;
      const sy = player.y - camera.y;

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.25)";
      ctx.beginPath();
      ctx.ellipse(sx + player.w / 2, sy + player.h + 8, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Animation frame parameters
      const bob = player.grounded && Math.abs(player.vx) > 20 ? Math.sin(player.animTime * 24) * 2 : 0;
      const bodyColor = player.grounded ? "#ffcc66" : "#ffd27f";
      const shirtColor = "#2f6bff";
      const pantsColor = "#20304e";
      const outline = "#1a1a1a";

      // Draw a simple sprite-like character with parts
      const frameShift = player.frame;
      const armSwing = player.grounded ? Math.sin(player.animTime * 12) * 8 : 0;

      // Legs
      ctx.fillStyle = pantsColor;
      ctx.fillRect(sx + 10, sy + 42 + bob + (frameShift === 1 ? 2 : 0), 8, 18);
      ctx.fillRect(sx + 24, sy + 42 + bob + (frameShift === 3 ? 2 : 0), 8, 18);

      // Shoes
      ctx.fillStyle = "#111";
      ctx.fillRect(sx + 8, sy + 56 + bob, 12, 5);
      ctx.fillRect(sx + 22, sy + 56 + bob, 12, 5);

      // Torso
      ctx.fillStyle = shirtColor;
      ctx.fillRect(sx + 8, sy + 20 + bob, 26, 24);

      // Head
      ctx.fillStyle = bodyColor;
      ctx.beginPath();
      ctx.arc(sx + 21, sy + 14 + bob, 14, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = outline;
      const eyeOffset = player.facing === 1 ? 3 : -3;
      ctx.fillRect(sx + 17 + eyeOffset, sy + 11 + bob, 3, 3);
      ctx.fillRect(sx + 24 + eyeOffset, sy + 11 + bob, 3, 3);

      // Arms
      ctx.strokeStyle = shirtColor;
      ctx.lineWidth = 6;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(sx + 8, sy + 24 + bob);
      ctx.lineTo(sx - 2, sy + 32 + bob + armSwing * 0.2);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(sx + 34, sy + 24 + bob);
      ctx.lineTo(sx + 46, sy + 32 + bob - armSwing * 0.2);
      ctx.stroke();

      // Outline accents
      ctx.strokeStyle = outline;
      ctx.lineWidth = 2;
      ctx.strokeRect(sx + 8, sy + 20 + bob, 26, 24);
    }

    function render() {
      drawBackground();

      // World floor haze
      ctx.fillStyle = "#6cc16f";
      ctx.fillRect(0, canvas.height - 60, canvas.width, 60);

      for (const p of platforms) drawPlatform(p);
      drawPlayer();

      // Debug info
      ctx.fillStyle = "rgba(0,0,0,0.4)";
      ctx.fillRect(12, canvas.height - 66, 250, 48);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)}  y: ${player.y.toFixed(1)}`, 22, canvas.height - 38);
      ctx.fillText(`vx: ${player.vx.toFixed(1)}  vy: ${player.vy.toFixed(1)}`, 22, canvas.height - 20);
    }

    let last = performance.now();

    function loop(now) {
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
