## `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

const WIDTH = canvas.width;
const HEIGHT = canvas.height;

const TILE_SIZE = 48;
const GRAVITY = 2200;
const MOVE_SPEED = 420;
const JUMP_SPEED = 850;
const FRICTION = 0.82;
const AIR_FRICTION = 0.95;
const MAX_FALL_SPEED = 1800;

const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "ArrowUp" || e.code === "Space" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "ArrowUp" || e.code === "Space" || e.code === "KeyW") keys.jump = false;
});

// Simple tile map: # = solid, . = empty
const level = [
  "................................................................",
  "................................................................",
  "................................................................",
  ".......................###......................................",
  "..............###...............................................",
  "................................................................",
  ".....###........................................................",
  "................................................................",
  "###############################..............###################",
  "###############################..............###################",
];

const world = {
  width: level[0].length * TILE_SIZE,
  height: level.length * TILE_SIZE,
};

function isSolidTile(tx, ty) {
  if (ty < 0 || ty >= level.length || tx < 0 || tx >= level[0].length) return false;
  return level[ty][tx] === "#";
}

function rectsIntersect(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

class Animation {
  constructor(frames, frameDuration) {
    this.frames = frames;
    this.frameDuration = frameDuration;
    this.timer = 0;
    this.index = 0;
  }

  update(dt) {
    this.timer += dt;
    if (this.timer >= this.frameDuration) {
      this.timer = 0;
      this.index = (this.index + 1) % this.frames.length;
    }
  }

  frame() {
    return this.frames[this.index];
  }
}

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 32;
    this.h = 44;

    this.vx = 0;
    this.vy = 0;

    this.onGround = false;
    this.facing = 1;

    this.animations = {
      idle: new Animation([0, 1, 2, 1], 0.18),
      run: new Animation([0, 1, 2, 3, 4, 5], 0.08),
      jump: new Animation([0], 0.2),
    };

    this.currentAnimation = "idle";

    // Placeholder sprite handling
    this.sprite = null;
    this.useSpriteSheet = false;
  }

  update(dt) {
    const accel = this.onGround ? 2400 : 1600;
    const friction = this.onGround ? FRICTION : AIR_FRICTION;

    if (keys.left) {
      this.vx -= accel * dt;
      this.facing = -1;
    }
    if (keys.right) {
      this.vx += accel * dt;
      this.facing = 1;
    }

    this.vx *= friction;

    if (Math.abs(this.vx) > MOVE_SPEED) {
      this.vx = Math.sign(this.vx) * MOVE_SPEED;
    }

    if (keys.jump && this.onGround) {
      this.vy = -JUMP_SPEED;
      this.onGround = false;
    }

    this.vy += GRAVITY * dt;
    if (this.vy > MAX_FALL_SPEED) this.vy = MAX_FALL_SPEED;

    this.moveAndCollide(dt);

    // Animation state
    if (!this.onGround) {
      this.currentAnimation = this.vy < 0 ? "jump" : "jump";
    } else if (Math.abs(this.vx) > 30) {
      this.currentAnimation = "run";
    } else {
      this.currentAnimation = "idle";
    }

    this.animations[this.currentAnimation].update(dt);
  }

  moveAndCollide(dt) {
    // Horizontal
    this.x += this.vx * dt;
    this.resolveCollisions("x");

    // Vertical
    this.y += this.vy * dt;
    this.onGround = false;
    this.resolveCollisions("y");
  }

  resolveCollisions(axis) {
    const bounds = this.getBounds();

    const minTx = Math.floor(bounds.x / TILE_SIZE);
    const maxTx = Math.floor((bounds.x + bounds.w) / TILE_SIZE);
    const minTy = Math.floor(bounds.y / TILE_SIZE);
    const maxTy = Math.floor((bounds.y + bounds.h) / TILE_SIZE);

    for (let ty = minTy; ty <= maxTy; ty++) {
      for (let tx = minTx; tx <= maxTx; tx++) {
        if (!isSolidTile(tx, ty)) continue;

        const tileRect = {
          x: tx * TILE_SIZE,
          y: ty * TILE_SIZE,
          w: TILE_SIZE,
          h: TILE_SIZE,
        };

        if (!rectsIntersect(bounds, tileRect)) continue;

        if (axis === "x") {
          if (this.vx > 0) {
            this.x = tileRect.x - this.w;
          } else if (this.vx < 0) {
            this.x = tileRect.x + tileRect.w;
          }
          this.vx = 0;
        } else if (axis === "y") {
          if (this.vy > 0) {
            this.y = tileRect.y - this.h;
            this.vy = 0;
            this.onGround = true;
          } else if (this.vy < 0) {
            this.y = tileRect.y + tileRect.h;
            this.vy = 0;
          }
        }

        bounds.x = this.x;
        bounds.y = this.y;
      }
    }
  }

  getBounds() {
    return {
      x: this.x,
      y: this.y,
      w: this.w,
      h: this.h,
    };
  }

  draw(ctx, camera) {
    const x = Math.floor(this.x - camera.x);
    const y = Math.floor(this.y - camera.y);

    // Placeholder draw
    ctx.fillStyle = "#ffcc66";
    ctx.fillRect(x, y, this.w, this.h);

    // Face indicator
    ctx.fillStyle = "#000";
    const eyeX = this.facing === 1 ? x + 22 : x + 8;
    ctx.fillRect(eyeX, y + 12, 4, 4);

    // Animation debug bar
    ctx.fillStyle = "rgba(0,0,0,0.2)";
    ctx.fillRect(x, y - 8, this.w, 4);
    ctx.fillStyle = this.onGround ? "#4caf50" : "#f44336";
    ctx.fillRect(x, y - 8, this.w * Math.min(Math.abs(this.vx) / MOVE_SPEED, 1), 4);
  }
}

const player = new Player(120, 100);

const camera = {
  x: 0,
  y: 0,
  follow(target) {
    this.x = target.x + target.w / 2 - WIDTH / 2;
    this.y = target.y + target.h / 2 - HEIGHT / 2;

    this.x = Math.max(0, Math.min(this.x, world.width - WIDTH));
    this.y = Math.max(0, Math.min(this.y, world.height - HEIGHT));
  },
};

function drawLevel(ctx, camera) {
  const startX = Math.floor(camera.x / TILE_SIZE);
  const endX = Math.ceil((camera.x + WIDTH) / TILE_SIZE);
  const startY = Math.floor(camera.y / TILE_SIZE);
  const endY = Math.ceil((camera.y + HEIGHT) / TILE_SIZE);

  for (let y = startY; y <= endY; y++) {
    for (let x = startX; x <= endX; x++) {
      if (!isSolidTile(x, y)) continue;
      ctx.fillStyle = "#3a3f5a";
      ctx.fillRect(
        x * TILE_SIZE - camera.x,
        y * TILE_SIZE - camera.y,
        TILE_SIZE,
        TILE_SIZE
      );
      ctx.strokeStyle = "#23263a";
      ctx.strokeRect(
        x * TILE_SIZE - camera.x,
        y * TILE_SIZE - camera.y,
        TILE_SIZE,
        TILE_SIZE
      );
    }
  }
}

function drawBackground(ctx, camera) {
  // Simple parallax dots
  ctx.fillStyle = "rgba(255,255,255,0.25)";
  for (let i = 0; i < 40; i++) {
    const px = (i * 240 - camera.x * 0.2) % (WIDTH + 240);
    const py = (i * 91) % HEIGHT;
    ctx.fillRect(px, py, 3, 3);
  }
}

let lastTime = 0;
function gameLoop(timestamp) {
  const dt = Math.min((timestamp - lastTime) / 1000, 1 / 30);
  lastTime = timestamp;

  player.update(dt);
  camera.follow(player);

  ctx.clearRect(0, 0, WIDTH, HEIGHT);
  drawBackground(ctx, camera);
  drawLevel(ctx, camera);
  player.draw(ctx, camera);

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
```

