## `game.js`

```javascript
const canvas = document.getElementById("gameCanvas");
const ctx = canvas.getContext("2d");

// ======== INPUT ========
const keys = {
  left: false,
  right: false,
  jump: false
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

// ======== TILE MAP ========
const TILE_SIZE = 48;

const levelData = [
  "........................................................................................",
  "........................................................................................",
  "........................................................................................",
  "........................................................................................",
  "......................................................###...............................",
  "..............................................###.......................................",
  "..............................###.......................................................",
  ".....................###................................................................",
  ".................###....................................................###.............",
  "........................................................................................",
  ".............###........................................................................",
  "###############################....#############################....####################",
];

const world = {
  tiles: [],
  rows: levelData.length,
  cols: levelData[0].length,
  width: levelData[0].length * TILE_SIZE,
  height: levelData.length * TILE_SIZE
};

for (let y = 0; y < levelData.length; y++) {
  for (let x = 0; x < levelData[y].length; x++) {
    if (levelData[y][x] === "#") {
      world.tiles.push({
        x: x * TILE_SIZE,
        y: y * TILE_SIZE,
        w: TILE_SIZE,
        h: TILE_SIZE
      });
    }
  }
}

// ======== PLAYER ========
const player = {
  x: 100,
  y: 100,
  w: 34,
  h: 44,
  vx: 0,
  vy: 0,
  speed: 260,
  jumpForce: 620,
  gravity: 1800,
  onGround: false,
  facing: 1, // 1 right, -1 left
  animTime: 0,
  animFrame: 0
};

// ======== CAMERA ========
const camera = {
  x: 0,
  y: 0
};

// ======== HELPERS ========
function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

function resolveCollisions(entity) {
  entity.onGround = false;

  // Horizontal collision
  for (const tile of world.tiles) {
    if (rectsOverlap(entity, tile)) {
      if (entity.vx > 0) {
        entity.x = tile.x - entity.w;
      } else if (entity.vx < 0) {
        entity.x = tile.x + tile.w;
      }
      entity.vx = 0;
    }
  }

  // Vertical collision
  for (const tile of world.tiles) {
    if (rectsOverlap(entity, tile)) {
      if (entity.vy > 0) {
        entity.y = tile.y - entity.h;
        entity.vy = 0;
        entity.onGround = true;
      } else if (entity.vy < 0) {
        entity.y = tile.y + tile.h;
        entity.vy = 0;
      }
    }
  }
}

// ======== ANIMATION ========
function updateAnimation(dt) {
  const moving = Math.abs(player.vx) > 5;

  if (moving && player.onGround) {
    player.animTime += dt;
    if (player.animTime > 0.12) {
      player.animTime = 0;
      player.animFrame = (player.animFrame + 1) % 4;
    }
  } else {
    player.animFrame = 0;
    player.animTime = 0;
  }
}

// Simple procedural "sprite" animation using shapes.
// Replace this with image sprites later if desired.
function drawPlayer(x, y) {
  const frame = player.animFrame;
  const bob = player.onGround ? Math.sin(frame * 0.5) * 1.5 : 0;

  ctx.save();
  ctx.translate(x, y + bob);

  // body
  ctx.fillStyle = "#2d5bff";
  ctx.fillRect(4, 12, 26, 24);

  // head
  ctx.fillStyle = "#ffcc99";
  ctx.fillRect(8, 2, 18, 14);

  // legs / walk animation
  ctx.fillStyle = "#111";
  if (player.onGround) {
    if (frame === 0 || frame === 2) {
      ctx.fillRect(6, 36, 6, 8);
      ctx.fillRect(22, 36, 6, 8);
    } else {
      ctx.fillRect(5, 36, 6, 8);
      ctx.fillRect(23, 36, 6, 8);
    }
  } else {
    ctx.fillRect(6, 36, 6, 8);
    ctx.fillRect(22, 36, 6, 8);
  }

  // face direction indicator
  ctx.fillStyle = "#000";
  if (player.facing === 1) {
    ctx.fillRect(20, 7, 2, 2);
  } else {
    ctx.fillRect(10, 7, 2, 2);
  }

  ctx.restore();
}

// ======== UPDATE ========
let lastTime = 0;

function update(dt) {
  const prevJump = player.onGround;

  // Input -> horizontal movement
  player.vx = 0;
  if (keys.left) {
    player.vx = -player.speed;
    player.facing = -1;
  }
  if (keys.right) {
    player.vx = player.speed;
    player.facing = 1;
  }

  // Jump only when grounded
  if (keys.jump && prevJump) {
    player.vy = -player.jumpForce;
    player.onGround = false;
  }

  // Gravity
  player.vy += player.gravity * dt;

  // Integrate
  player.x += player.vx * dt;
  resolveCollisions(player);

  player.y += player.vy * dt;
  resolveCollisions(player);

  // Keep player in world bounds
  if (player.x < 0) player.x = 0;
  if (player.x + player.w > world.width) player.x = world.width - player.w;
  if (player.y > world.height + 500) {
    player.x = 100;
    player.y = 100;
    player.vx = 0;
    player.vy = 0;
  }

  updateAnimation(dt);

  // Camera follow
  camera.x = player.x + player.w / 2 - canvas.width / 2;
  camera.y = player.y + player.h / 2 - canvas.height / 2;

  camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
  camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
}

// ======== RENDER ========
function drawTiles() {
  for (const tile of world.tiles) {
    const sx = tile.x - camera.x;
    const sy = tile.y - camera.y;

    // simple grass/dirt block
    ctx.fillStyle = "#8b5a2b";
    ctx.fillRect(sx, sy, tile.w, tile.h);

    ctx.fillStyle = "#3cb043";
    ctx.fillRect(sx, sy, tile.w, 10);

    ctx.strokeStyle = "rgba(0,0,0,0.2)";
    ctx.strokeRect(sx, sy, tile.w, tile.h);
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // background clouds
  ctx.fillStyle = "rgba(255,255,255,0.6)";
  for (let i = 0; i < 6; i++) {
    const x = ((i * 180) - (camera.x * 0.2)) % (canvas.width + 240) - 120;
    const y = 50 + (i % 3) * 35;
    ctx.beginPath();
    ctx.ellipse(x, y, 40, 18, 0, 0, Math.PI * 2);
    ctx.ellipse(x + 28, y + 8, 32, 16, 0, 0, Math.PI * 2);
    ctx.ellipse(x - 24, y + 10, 30, 14, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  drawTiles();

  // player
  drawPlayer(player.x - camera.x, player.y - camera.y);

  // simple HUD
  ctx.fillStyle = "#000";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 16, 24);
}

// ======== GAME LOOP ========
function loop(timestamp) {
  const dt = Math.min((timestamp - lastTime) / 1000, 1 / 30);
  lastTime = timestamp;

  update(dt);
  render();

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
```

