```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

// ------------------------------
// Input
// ------------------------------
const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

// ------------------------------
// World / Physics
// ------------------------------
const GRAVITY = 2000;
const MOVE_ACCEL = 2200;
const MAX_SPEED = 350;
const FRICTION = 1800;
const JUMP_VELOCITY = 760;

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 48;
    this.h = 64;

    this.vx = 0;
    this.vy = 0;
    this.onGround = false;

    this.facing = 1; // 1 right, -1 left
    this.state = "idle";
    this.animTime = 0;
    this.frame = 0;
  }

  update(dt, platforms) {
    // Horizontal controls
    if (keys.left) {
      this.vx -= MOVE_ACCEL * dt;
      this.facing = -1;
    }
    if (keys.right) {
      this.vx += MOVE_ACCEL * dt;
      this.facing = 1;
    }

    // Clamp horizontal speed
    this.vx = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, this.vx));

    // Jump
    if (keys.jump && this.onGround) {
      this.vy = -JUMP_VELOCITY;
      this.onGround = false;
    }

    // Apply friction when no input
    if (!keys.left && !keys.right && this.onGround) {
      if (this.vx > 0) {
        this.vx = Math.max(0, this.vx - FRICTION * dt);
      } else if (this.vx < 0) {
        this.vx = Math.min(0, this.vx + FRICTION * dt);
      }
    }

    // Gravity
    this.vy += GRAVITY * dt;

    // Move and collide on X
    this.x += this.vx * dt;
    for (const p of platforms) {
      if (rectsOverlap(this, p)) {
        if (this.vx > 0) this.x = p.x - this.w;
        else if (this.vx < 0) this.x = p.x + p.w;
        this.vx = 0;
      }
    }

    // Move and collide on Y
    this.y += this.vy * dt;
    this.onGround = false;
    for (const p of platforms) {
      if (rectsOverlap(this, p)) {
        if (this.vy > 0) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
      }
    }

    // Animation state
    if (!this.onGround) {
      this.state = this.vy < 0 ? "jump" : "fall";
    } else if (Math.abs(this.vx) > 20) {
      this.state = "run";
    } else {
      this.state = "idle";
    }

    this.animTime += dt;
    this.updateAnimationFrame();
  }

  updateAnimationFrame() {
    const anims = {
      idle: { frames: 4, fps: 4 },
      run: { frames: 6, fps: 10 },
      jump: { frames: 1, fps: 1 },
      fall: { frames: 1, fps: 1 },
    };

    const anim = anims[this.state];
    if (anim.frames === 1) {
      this.frame = 0;
      return;
    }

    const frameIndex = Math.floor(this.animTime * anim.fps) % anim.frames;
    this.frame = frameIndex;
  }

  draw(ctx, camX, camY) {
    // Placeholder sprite animation: draw a stylized character
    const x = Math.floor(this.x - camX);
    const y = Math.floor(this.y - camY);

    ctx.save();

    // Flip based on facing
    ctx.translate(x + this.w / 2, y + this.h / 2);
    ctx.scale(this.facing, 1);
    ctx.translate(-(this.w / 2), -(this.h / 2));

    // body
    const colors = {
      idle: "#ffcc66",
      run: ["#ffcc66", "#ffbb44", "#ffaa33", "#ffbb44", "#ffcc66", "#ffee88"],
      jump: "#88ddff",
      fall: "#66aaff",
    };

    let bodyColor = colors[this.state];
    if (Array.isArray(bodyColor)) {
      bodyColor = bodyColor[this.frame % bodyColor.length];
    }

    // shadow
    ctx.fillStyle = "rgba(0,0,0,0.15)";
    ctx.beginPath();
    ctx.ellipse(this.w / 2, this.h - 2, this.w * 0.35, 8, 0, 0, Math.PI * 2);
    ctx.fill();

    // torso
    ctx.fillStyle = bodyColor;
    roundRect(ctx, 10, 14, 28, 34, 8);
    ctx.fill();

    // head
    ctx.fillStyle = "#f6d2b8";
    ctx.beginPath();
    ctx.arc(24, 14, 12, 0, Math.PI * 2);
    ctx.fill();

    // eyes
    ctx.fillStyle = "#1b1b1b";
    ctx.beginPath();
    ctx.arc(20, 12, 1.8, 0, Math.PI * 2);
    ctx.arc(28, 12, 1.8, 0, Math.PI * 2);
    ctx.fill();

    // legs
    ctx.strokeStyle = "#2a2a2a";
    ctx.lineWidth = 5;
    ctx.lineCap = "round";
    ctx.beginPath();
    if (this.state === "run") {
      const swing = this.frame % 2 === 0 ? 6 : -6;
      ctx.moveTo(18, 47);
      ctx.lineTo(14 + swing, 58);
      ctx.moveTo(30, 47);
      ctx.lineTo(34 - swing, 58);
    } else {
      ctx.moveTo(18, 47);
      ctx.lineTo(16, 58);
      ctx.moveTo(30, 47);
      ctx.lineTo(32, 58);
    }
    ctx.stroke();

    // arms
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(10, 24);
    ctx.lineTo(3, 34);
    ctx.moveTo(38, 24);
    ctx.lineTo(45, 34);
    ctx.stroke();

    ctx.restore();
  }
}

function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + w - radius, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
  ctx.lineTo(x + w, y + h - radius);
  ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
  ctx.lineTo(x + radius, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
}

// ------------------------------
// Level
// ------------------------------
const platforms = [
  { x: -200, y: 520, w: 1800, h: 80 },   // ground
  { x: 100, y: 420, w: 160, h: 25 },
  { x: 340, y: 360, w: 160, h: 25 },
  { x: 580, y: 300, w: 160, h: 25 },
  { x: 840, y: 380, w: 200, h: 25 },
  { x: 1120, y: 440, w: 180, h: 25 },
  { x: 1400, y: 340, w: 180, h: 25 },
];

const player = new Player(40, 300);

const camera = {
  x: 0,
  y: 0,
};

function updateCamera() {
  const targetX = player.x + player.w / 2 - canvas.width / 2;
  const targetY = player.y + player.h / 2 - canvas.height / 2;

  camera.x += (targetX - camera.x) * 0.1;
  camera.y += (targetY - camera.y) * 0.08;

  camera.x = Math.max(-300, camera.x);
  camera.y = Math.max(-100, camera.y);
}

// ------------------------------
// Background
// ------------------------------
function drawBackground() {
  // parallax hills / clouds
  const wx = camera.x;

  // clouds
  ctx.fillStyle = "rgba(255,255,255,0.55)";
  for (let i = 0; i < 6; i++) {
    const cx = (i * 320 - (wx * 0.25) % 320) - 100;
    const cy = 70 + (i % 3) * 25;
    drawCloud(cx, cy, 1 + (i % 2) * 0.2);
  }

  // hills
  ctx.fillStyle = "#64b36a";
  for (let i = 0; i < 5; i++) {
    const hx = (i * 360 - (wx * 0.5) % 360) - 120;
    const hy = canvas.height - 45;
    ctx.beginPath();
    ctx.ellipse(hx + 120, hy, 150, 60, 0, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawCloud(x, y, scale) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  ctx.beginPath();
  ctx.ellipse(0, 10, 25, 15, 0, 0, Math.PI * 2);
  ctx.ellipse(20, 0, 30, 18, 0, 0, Math.PI * 2);
  ctx.ellipse(45, 10, 24, 14, 0, 0, Math.PI * 2);
  ctx.ellipse(20, 15, 40, 16, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

// ------------------------------
// Main loop
// ------------------------------
let lastTime = performance.now();

function loop(now) {
  const dt = Math.min(0.033, (now - lastTime) / 1000);
  lastTime = now;

  player.update(dt, platforms);
  updateCamera();

  // Render
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawBackground();

  // Draw platforms
  for (const p of platforms) {
    ctx.fillStyle = p.y > 500 ? "#3f7d3f" : "#734d2b";
    ctx.fillRect(
      Math.floor(p.x - camera.x),
      Math.floor(p.y - camera.y),
      p.w,
      p.h
    );

    // top highlight
    ctx.fillStyle = p.y > 500 ? "#5d9c5f" : "#8f6238";
    ctx.fillRect(
      Math.floor(p.x - camera.x),
      Math.floor(p.y - camera.y),
      p.w,
      6
    );
  }

  player.draw(ctx, camera.x, camera.y);

  // HUD
  ctx.fillStyle = "#111";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 20, 30);

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
