## `game.js`

```javascript
const canvas = document.getElementById("gameCanvas");
const ctx = canvas.getContext("2d");

const keys = {};
window.addEventListener("keydown", (e) => (keys[e.code] = true));
window.addEventListener("keyup", (e) => (keys[e.code] = false));

const GRAVITY = 0.5;
const MOVE_SPEED = 4;
const JUMP_FORCE = -12;
const FRICTION = 0.85;

class Platform {
  constructor(x, y, w, h) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
  }

  draw(ctx, cameraX) {
    ctx.fillStyle = "#4b8f29";
    ctx.fillRect(this.x - cameraX, this.y, this.w, this.h);

    ctx.fillStyle = "#8b5a2b";
    ctx.fillRect(this.x - cameraX, this.y + 16, this.w, this.h - 16);
  }
}

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 32;
    this.h = 48;
    this.vx = 0;
    this.vy = 0;
    this.onGround = false;

    // Animation
    this.facing = 1; // 1 = right, -1 = left
    this.animFrame = 0;
    this.animTimer = 0;
    this.animSpeed = 8;
    this.state = "idle"; // idle, run, jump
  }

  update(platforms) {
    // Input
    if (keys["ArrowLeft"] || keys["KeyA"]) {
      this.vx = Math.max(this.vx - 0.6, -MOVE_SPEED);
      this.facing = -1;
    } else if (keys["ArrowRight"] || keys["KeyD"]) {
      this.vx = Math.min(this.vx + 0.6, MOVE_SPEED);
      this.facing = 1;
    } else {
      this.vx *= FRICTION;
      if (Math.abs(this.vx) < 0.05) this.vx = 0;
    }

    if ((keys["ArrowUp"] || keys["Space"] || keys["KeyW"]) && this.onGround) {
      this.vy = JUMP_FORCE;
      this.onGround = false;
    }

    // Physics
    this.vy += GRAVITY;

    // Horizontal movement and collision
    this.x += this.vx;
    for (const p of platforms) {
      if (this.intersects(p)) {
        if (this.vx > 0) {
          this.x = p.x - this.w;
        } else if (this.vx < 0) {
          this.x = p.x + p.w;
        }
        this.vx = 0;
      }
    }

    // Vertical movement and collision
    this.y += this.vy;
    this.onGround = false;
    for (const p of platforms) {
      if (this.intersects(p)) {
        if (this.vy > 0) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
      }
    }

    // Determine animation state
    if (!this.onGround) {
      this.state = "jump";
    } else if (Math.abs(this.vx) > 0.5) {
      this.state = "run";
    } else {
      this.state = "idle";
    }

    // Update animation
    this.animTimer++;
    if (this.animTimer >= this.animSpeed) {
      this.animFrame = (this.animFrame + 1) % 4;
      this.animTimer = 0;
    }
  }

  intersects(rect) {
    return (
      this.x < rect.x + rect.w &&
      this.x + this.w > rect.x &&
      this.y < rect.y + rect.h &&
      this.y + this.h > rect.y
    );
  }

  draw(ctx, cameraX) {
    const x = this.x - cameraX;
    const y = this.y;

    // Placeholder sprite animation using shapes.
    // Replace this later with sprite-sheet drawing.
    ctx.save();
    ctx.translate(x + this.w / 2, y + this.h / 2);
    ctx.scale(this.facing, 1);
    ctx.translate(-(x + this.w / 2), -(y + this.h / 2));

    if (this.state === "idle") {
      ctx.fillStyle = "#ffd166";
    } else if (this.state === "run") {
      ctx.fillStyle = ["#ef476f", "#ffd166", "#06d6a0", "#118ab2"][this.animFrame];
    } else {
      ctx.fillStyle = "#8ecae6";
    }

    // Body
    ctx.fillRect(x, y, this.w, this.h);

    // Eyes
    ctx.fillStyle = "#000";
    ctx.fillRect(x + 8, y + 12, 4, 4);
    ctx.fillRect(x + 20, y + 12, 4, 4);

    // Feet animation
    if (this.state === "run") {
      ctx.fillStyle = "#333";
      const footOffset = this.animFrame % 2 === 0 ? 0 : 6;
      ctx.fillRect(x + 5, y + 42, 8, 6);
      ctx.fillRect(x + 19 + footOffset, y + 42, 8, 6);
    } else {
      ctx.fillStyle = "#333";
      ctx.fillRect(x + 5, y + 42, 8, 6);
      ctx.fillRect(x + 19, y + 42, 8, 6);
    }

    ctx.restore();
  }
}

// Level setup
const platforms = [
  new Platform(-200, 500, 1600, 40),   // ground
  new Platform(150, 420, 140, 20),
  new Platform(350, 360, 140, 20),
  new Platform(580, 300, 140, 20),
  new Platform(820, 250, 160, 20),
  new Platform(1100, 400, 180, 20),
];

const player = new Player(100, 200);

const camera = {
  x: 0,
  update() {
    const target = player.x - canvas.width / 2 + player.w / 2;
    this.x += (target - this.x) * 0.08;
  }
};

function drawBackground() {
  // Simple parallax-style background
  ctx.fillStyle = "#87ceeb";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = "#bde0fe";
  for (let i = 0; i < 20; i++) {
    const x = (i * 220 - camera.x * 0.3) % (canvas.width + 220) - 100;
    ctx.fillRect(x, 80 + (i % 3) * 20, 120, 30);
  }

  // Hills
  ctx.fillStyle = "#90be6d";
  for (let i = 0; i < 8; i++) {
    const x = (i * 300 - camera.x * 0.5) % (canvas.width + 300) - 150;
    ctx.beginPath();
    ctx.arc(x + 150, 540, 120, Math.PI, 0);
    ctx.fill();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawBackground();

  // Platforms
  for (const p of platforms) {
    p.draw(ctx, camera.x);
  }

  // Player
  player.draw(ctx, camera.x);

  // UI
  ctx.fillStyle = "#000";
  ctx.font = "20px monospace";
  ctx.fillText("Move: A/D or Arrow Keys", 20, 30);
  ctx.fillText("Jump: W / Space / Up Arrow", 20, 55);
}

function update() {
  player.update(platforms);
  camera.update();
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
