<body>
  <div class="help">
    <strong>Controls</strong><br>
    A / D or Arrow Keys: Move<br>
    W / Space / Up: Jump
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {
      left: false,
      right: false,
      jump: false
    };

    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = true;
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    const physics = {
      gravity: 1800,
      moveSpeed: 320,
      jumpSpeed: 680,
      friction: 0.82,
      airControl: 0.88
    };

    const player = {
      x: 100,
      y: 200,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      grounded: false,
      facing: 1,
      animTime: 0,
      currentFrame: 0
    };

    const platforms = [
      { x: 0,   y: 500, w: 960, h: 40 },
      { x: 180, y: 400, w: 160, h: 20 },
      { x: 390, y: 340, w: 180, h: 20 },
      { x: 650, y: 280, w: 180, h: 20 },
      { x: 90,  y: 250, w: 120, h: 20 },
      { x: 820, y: 180, w: 100, h: 20 }
    ];

    const world = {
      width: 2000,
      height: 800
    };

    const camera = {
      x: 0,
      y: 0
    };

    // Simple sprite animation using generated frames on an offscreen canvas
    const spriteSheet = document.createElement("canvas");
    spriteSheet.width = 256;
    spriteSheet.height = 64;
    const sctx = spriteSheet.getContext("2d");

    function drawFrame(frameIndex, flip = false) {
      const fw = 64;
      const fh = 64;
      const sx = frameIndex * fw;

      sctx.save();
      sctx.clearRect(sx, 0, fw, fh);

      if (flip) {
        sctx.translate(sx + fw, 0);
        sctx.scale(-1, 1);
      } else {
        sctx.translate(sx, 0);
      }

      // Body
      sctx.fillStyle = "#2b2d42";
      sctx.fillRect(18, 20, 28, 26);

      // Head
      sctx.fillStyle = "#f2d2b6";
      sctx.fillRect(22, 8, 20, 16);

      // Legs animation
      sctx.fillStyle = "#3a86ff";
      if (frameIndex === 0) {
        sctx.fillRect(18, 46, 10, 12);
        sctx.fillRect(36, 44, 10, 14);
      } else if (frameIndex === 1) {
        sctx.fillRect(16, 44, 10, 14);
        sctx.fillRect(38, 46, 10, 12);
      } else if (frameIndex === 2) {
        sctx.fillRect(18, 45, 10, 13);
        sctx.fillRect(36, 45, 10, 13);
      } else {
        sctx.fillRect(20, 44, 10, 14);
        sctx.fillRect(34, 44, 10, 14);
      }

      // Eyes
      sctx.fillStyle = "#111";
      sctx.fillRect(27, 13, 3, 3);
      sctx.fillRect(34, 13, 3, 3);

      sctx.restore();
    }

    for (let i = 0; i < 4; i++) drawFrame(i);

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisionsAxisX() {
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }
    }

    function resolveCollisionsAxisY() {
      player.grounded = false;

      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.grounded = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }
    }

    let lastTime = 0;
    let jumpBuffer = 0;

    function update(dt) {
      // Horizontal movement
      const movingLeft = keys.left && !keys.right;
      const movingRight = keys.right && !keys.left;

      if (movingLeft) {
        player.vx -= physics.moveSpeed * dt;
        player.facing = -1;
      }
      if (movingRight) {
        player.vx += physics.moveSpeed * dt;
        player.facing = 1;
      }

      // Clamp speed
      player.vx = Math.max(-physics.moveSpeed, Math.min(physics.moveSpeed, player.vx));

      // Jump
      if (keys.jump) {
        jumpBuffer = 0.12;
      } else {
        jumpBuffer -= dt;
      }

      if (jumpBuffer > 0 && player.grounded) {
        player.vy = -physics.jumpSpeed;
        player.grounded = false;
        jumpBuffer = 0;
      }

      // Gravity
      player.vy += physics.gravity * dt;

      // Apply damping / friction
      if (player.grounded) {
        player.vx *= physics.friction;
      } else {
        player.vx *= physics.airControl;
      }

      // Move and resolve collisions
      player.x += player.vx * dt;
      resolveCollisionsAxisX();

      player.y += player.vy * dt;
      resolveCollisionsAxisY();

      // World bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height) {
        player.x = 100;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Camera follows player
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));

      // Animation
      if (Math.abs(player.vx) > 20 && player.grounded) {
        player.animTime += dt * 12;
      } else {
        player.animTime = 0;
      }
      player.currentFrame = Math.floor(player.animTime) % 4;
    }

    function drawBackground() {
      // distant hills
      ctx.fillStyle = "#8ed081";
      ctx.beginPath();
      ctx.arc(200 - camera.x * 0.2, 500, 180, 0, Math.PI * 2);
      ctx.arc(500 - camera.x * 0.15, 520, 220, 0, Math.PI * 2);
      ctx.arc(850 - camera.x * 0.1, 510, 200, 0, Math.PI * 2);
      ctx.fill();

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.75)";
      const clouds = [
        { x: 120, y: 90, s: 1.2 },
        { x: 430, y: 70, s: 0.9 },
        { x: 760, y: 110, s: 1.5 }
      ];
      for (const c of clouds) {
        const x = c.x - camera.x * 0.3;
        const y = c.y;
        ctx.beginPath();
        ctx.arc(x, y, 22 * c.s, 0, Math.PI * 2);
        ctx.arc(x + 24 * c.s, y - 10 * c.s, 28 * c.s, 0, Math.PI * 2);
        ctx.arc(x + 52 * c.s, y, 22 * c.s, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5f4b32";
        ctx.fillRect(p.x, p.y, p.w, p.h);

        ctx.fillStyle = "#7cb342";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // Player shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.beginPath();
      ctx.ellipse(player.x + player.w / 2, player.y + player.h + 6, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Player sprite
      ctx.save();
      if (player.facing === -1) {
        ctx.scale(-1, 1);
        ctx.drawImage(
          spriteSheet,
          player.currentFrame * 64, 0, 64, 64,
          -(player.x + player.w), player.y,
          64, 64
        );
      } else {
        ctx.drawImage(
          spriteSheet,
          player.currentFrame * 64, 0, 64, 64,
          player.x - 8, player.y,
          64, 64
        );
      }
      ctx.restore();

      ctx.restore();

      // Debug HUD
      ctx.fillStyle = "rgba(0,0,0,0.4)";
      ctx.fillRect(12, canvas.height - 52, 260, 40);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)}  y: ${player.y.toFixed(1)}`, 22, canvas.height - 27);
      ctx.fillText(`vx: ${player.vx.toFixed(1)}  vy: ${player.vy.toFixed(1)}`, 22, canvas.height - 10);
    }

    function loop(timestamp) {
      const dt = Math.min(0.033, (timestamp - lastTime) / 1000 || 0);
      lastTime = timestamp;

      update(dt);
      draw();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

