## 4) `game.js`

```js
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

window.addEventListener("resize", () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
});

// -------------------------
// Input
// -------------------------
const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

// -------------------------
// Utility
// -------------------------
function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function rectsIntersect(a, b) {
  return (
    a.x < b.x + b.width &&
    a.x + a.width > b.x &&
    a.y < b.y + b.height &&
    a.y + a.height > b.y
  );
}

// -------------------------
// Level
// -------------------------
const platforms = [
  { x: 0, y: 560, width: 2400, height: 80 },
  { x: 250, y: 450, width: 160, height: 20 },
  { x: 500, y: 380, width: 180, height: 20 },
  { x: 780, y: 320, width: 200, height: 20 },
  { x: 1120, y: 420, width: 220, height: 20 },
  { x: 1450, y: 350, width: 180, height: 20 },
  { x: 1720, y: 480, width: 220, height: 20 },
  { x: 2050, y: 400, width: 180, height: 20 },
];

// -------------------------
// Player
// -------------------------
const player = {
  x: 100,
  y: 100,
  width: 48,
  height: 64,
  vx: 0,
  vy: 0,
  speed: 0.55,
  maxSpeed: 6,
  jumpForce: 14,
  gravity: 0.8,
  friction: 0.82,
  onGround: false,
  facing: 1, // 1 = right, -1 = left
  state: "idle",
  animTime: 0,
};

// -------------------------
// Animation Frames (simple placeholder sprite animation)
// Replace these with image spritesheets later.
// -------------------------
const animFrames = {
  idle: [0, 1, 2, 1],
  run: [0, 1, 2, 3, 2, 1],
  jump: [0],
  fall: [0],
};

function getPlayerFrame() {
  const frames = animFrames[player.state];
  const speed = player.state === "run" ? 0.1 : 0.18;
  const index = Math.floor(player.animTime / speed) % frames.length;
  return frames[index];
}

// -------------------------
// Camera
// -------------------------
const camera = {
  x: 0,
  y: 0,
};

// -------------------------
// Physics / Collision
// -------------------------
function updatePlayer() {
  // Horizontal input
  if (keys.left) {
    player.vx -= player.speed;
    player.facing = -1;
  }
  if (keys.right) {
    player.vx += player.speed;
    player.facing = 1;
  }

  // Clamp horizontal speed
  player.vx = clamp(player.vx, -player.maxSpeed, player.maxSpeed);

  // Jump
  if (keys.jump && player.onGround) {
    player.vy = -player.jumpForce;
    player.onGround = false;
  }

  // Gravity
  player.vy += player.gravity;
  if (player.vy > 20) player.vy = 20;

  // Apply friction when on ground
  if (player.onGround) {
    player.vx *= player.friction;
    if (Math.abs(player.vx) < 0.05) player.vx = 0;
  }

  // Move X
  player.x += player.vx;
  for (const p of platforms) {
    if (rectsIntersect(player, p)) {
      if (player.vx > 0) {
        player.x = p.x - player.width;
      } else if (player.vx < 0) {
        player.x = p.x + p.width;
      }
      player.vx = 0;
    }
  }

  // Move Y
  player.y += player.vy;
  player.onGround = false;

  for (const p of platforms) {
    if (rectsIntersect(player, p)) {
      if (player.vy > 0) {
        player.y = p.y - player.height;
        player.vy = 0;
        player.onGround = true;
      } else if (player.vy < 0) {
        player.y = p.y + p.height;
        player.vy = 0;
      }
    }
  }

  // Determine state
  if (!player.onGround) {
    player.state = player.vy < 0 ? "jump" : "fall";
  } else {
    player.state = Math.abs(player.vx) > 0.5 ? "run" : "idle";
  }

  player.animTime += 1;
}

// -------------------------
// Drawing
// -------------------------
function drawBackground() {
  // simple parallax sky + ground accents
  ctx.fillStyle = "#87ceeb";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // clouds
  ctx.fillStyle = "rgba(255,255,255,0.7)";
  for (let i = 0; i < 6; i++) {
    const x = ((i * 280) - camera.x * 0.3) % (canvas.width + 300) - 100;
    const y = 70 + i * 45;
    ctx.beginPath();
    ctx.arc(x, y, 25, 0, Math.PI * 2);
    ctx.arc(x + 25, y - 10, 32, 0, Math.PI * 2);
    ctx.arc(x + 55, y, 25, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawPlatform(p) {
  ctx.fillStyle = "#5d4037";
  ctx.fillRect(p.x - camera.x, p.y - camera.y, p.width, p.height);

  ctx.fillStyle = "#8d6e63";
  ctx.fillRect(p.x - camera.x, p.y - camera.y, p.width, 8);
}

function drawPlayer() {
  const x = player.x - camera.x;
  const y = player.y - camera.y;

  // body
  ctx.save();
  ctx.translate(x + player.width / 2, y + player.height / 2);

  // flip based on facing
  ctx.scale(player.facing, 1);

  // simple animated look: change colors slightly by frame
  const frame = getPlayerFrame();
  const colors = ["#ffcc80", "#ffb74d", "#ffa726", "#ff9800"];
  const accent = colors[frame % colors.length];

  // shadow
  ctx.fillStyle = "rgba(0,0,0,0.2)";
  ctx.beginPath();
  ctx.ellipse(0, player.height / 2 + 8, 18, 6, 0, 0, Math.PI * 2);
  ctx.fill();

  // torso
  ctx.fillStyle = accent;
  ctx.fillRect(-18, -20, 36, 32);

  // head
  ctx.fillStyle = "#f2c9a0";
  ctx.fillRect(-14, -44, 28, 24);

  // eyes
  ctx.fillStyle = "#222";
  ctx.fillRect(-8, -34, 4, 4);
  ctx.fillRect(4, -34, 4, 4);

  // legs animation
  ctx.strokeStyle = "#2c3e50";
  ctx.lineWidth = 5;
  ctx.beginPath();
  if (player.state === "run") {
    const legOffset = frame % 2 === 0 ? 8 : -8;
    ctx.moveTo(-10, 12);
    ctx.lineTo(-10 + legOffset, 34);
    ctx.moveTo(10, 12);
    ctx.lineTo(10 - legOffset, 34);
  } else {
    ctx.moveTo(-10, 12);
    ctx.lineTo(-10, 34);
    ctx.moveTo(10, 12);
    ctx.lineTo(10, 34);
  }
  ctx.stroke();

  ctx.restore();
}

function drawUI() {
  ctx.fillStyle = "rgba(0,0,0,0.5)";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or ←/→   Jump: Space/W/↑", 20, 30);
}

function updateCamera() {
  camera.x = player.x + player.width / 2 - canvas.width / 2;
  camera.y = player.y + player.height / 2 - canvas.height / 2;

  camera.x = clamp(camera.x, 0, 2400 - canvas.width);
  camera.y = clamp(camera.y, 0, 700 - canvas.height);
}

// -------------------------
// Game Loop
// -------------------------
function loop() {
  updatePlayer();
  updateCamera();

  drawBackground();

  for (const p of platforms) {
    drawPlatform(p);
  }

  drawPlayer();
  drawUI();

  requestAnimationFrame(loop);
}

loop();
