      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.beginPath();
      ctx.ellipse(px + p.w/2, py + p.h + 6, 16, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // legs
      ctx.strokeStyle = outline;
      ctx.lineWidth = 5;
      ctx.lineCap = "round";

      ctx.beginPath();
      ctx.moveTo(px + 12, py + 34);
      ctx.lineTo(px + 10 + legSwing, py + 46);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(px + 22, py + 34);
      ctx.lineTo(px + 24 - legSwing, py + 46);
      ctx.stroke();

      // feet
      ctx.beginPath();
      ctx.moveTo(px + 8 + legSwing, py + 47);
      ctx.lineTo(px + 15 + legSwing, py + 47);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(px + 20 - legSwing, py + 47);
      ctx.lineTo(px + 27 - legSwing, py + 47);
      ctx.stroke();

      // torso
      ctx.fillStyle = shirt;
      ctx.fillRect(px + 8, py + 16, 16, 18);
      ctx.strokeRect(px + 8, py + 16, 16, 18);

      // arms
      ctx.beginPath();
      ctx.moveTo(px + 8, py + 20);
      ctx.lineTo(px + 2 - armSwing, py + 28);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(px + 24, py + 20);
      ctx.lineTo(px + 30 + armSwing, py + 28);
      ctx.stroke();

      // head
      ctx.fillStyle = skin;
      ctx.beginPath();
      ctx.arc(px + 16, py + 10, 10, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // eyes
      ctx.fillStyle = outline;
      ctx.fillRect(px + 13, py + 8, 2, 2);
      ctx.fillRect(px + 18, py + 8, 2, 2);

      // pants
      ctx.fillStyle = pants;
      ctx.fillRect(px + 8, py + 31, 16, 8);

      ctx.restore();
    }

    function update(dt) {
      const left  = keys.has("ArrowLeft") || keys.has("a") || keys.has("A");
      const right = keys.has("ArrowRight") || keys.has("d") || keys.has("D");
      const jump  = keys.has("ArrowUp") || keys.has("w") || keys.has("W") || keys.has(" ");

      if (left) {
        player.vx = -player.speed;
        player.facing = -1;
      } else if (right) {
        player.vx = player.speed;
        player.facing = 1;
      } else {
        player.vx *= friction;
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      // Jump
      if (jump && player.onGround) {
        player.vy = -player.jump;
        player.onGround = false;
      }

      // gravity
      player.vy += gravity * dt;

      // horizontal movement
      player.x += player.vx * dt;
      player.x = Math.max(0, Math.min(W - player.w, player.x));

      // vertical movement and collision
      player.y += player.vy * dt;
      player.onGround = false;

      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          const prevY = player.y - player.vy * dt;

          // landing on top
          if (prevY + player.h <= p.y + 2 && player.vy >= 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // hitting from below
          else if (prevY >= p.y + p.h - 2 && player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // floor out-of-bounds
      if (player.y > H + 200) {
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      player.animTime += dt;
    }

    function draw() {
      ctx.clearRect(0, 0, W, H);

      // background clouds
      ctx.fillStyle = "rgba(255,255,255,0.45)";
      for (let i = 0; i < 6; i++) {
        const x = (i * 180 + (performance.now() * 0.01)) % (W + 200) - 100;
        const y = 50 + (i % 3) * 35;
        ctx.beginPath();
        ctx.ellipse(x, y, 34, 14, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 24, y - 8, 26, 12, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 48, y, 30, 13, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5b3f2a";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7b5a3d";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }

      drawPlayer(player);
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;
      update(dt);
      draw();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
