    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const gravity = 0.7;
    const friction = 0.8;

    const player = {
      x: 100,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 14,
      onGround: false,
      facing: "right",
      animFrame: 0,
      animTimer: 0
    };

    const platforms = [
      { x: 0,   y: canvas.height - 40, w: canvas.width, h: 40 },
      { x: 150, y: canvas.height - 120, w: 180, h: 20 },
      { x: 420, y: canvas.height - 200, w: 160, h: 20 },
      { x: 680, y: canvas.height - 280, w: 200, h: 20 },
      { x: 980, y: canvas.height - 160, w: 160, h: 20 }
    ];

    function resetPlatforms() {
      platforms[0] = { x: 0, y: canvas.height - 40, w: canvas.width, h: 40 };
      platforms[1] = { x: 150, y: canvas.height - 120, w: 180, h: 20 };
      platforms[2] = { x: 420, y: canvas.height - 200, w: 160, h: 20 };
      platforms[3] = { x: 680, y: canvas.height - 280, w: 200, h: 20 };
      platforms[4] = { x: 980, y: canvas.height - 160, w: 160, h: 20 };
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      // input
      if (keys["a"] || keys["arrowleft"]) {
        player.vx -= player.speed;
        player.facing = "left";
      }
      if (keys["d"] || keys["arrowright"]) {
        player.vx += player.speed;
        player.facing = "right";
      }

      const jumpPressed = keys["w"] || keys[" "] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // physics
      player.vy += gravity;
      player.vx *= friction;

      player.x += player.vx;
      player.y += player.vy;

      player.onGround = false;

      // collisions
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          const prevX = player.x - player.vx;
          const prevY = player.y - player.vy;

          // landing on top
          if (prevY + player.h <= p.y) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // hitting from below
          else if (prevY >= p.y + p.h) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          // from left
          else if (prevX + player.w <= p.x) {
            player.x = p.x - player.w;
            player.vx = 0;
          }
          // from right
          else if (prevX >= p.x + p.w) {
            player.x = p.x + p.w;
            player.vx = 0;
          }
        }
      }

      // bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > canvas.width) {
        player.x = canvas.width - player.w;
        player.vx = 0;
      }
      if (player.y > canvas.height + 200) {
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // animation
      const moving = Math.abs(player.vx) > 0.5;
      if (moving && player.onGround) {
        player.animTimer++;
        if (player.animTimer > 8) {
          player.animFrame = (player.animFrame + 1) % 4;
          player.animTimer = 0;
        }
      } else {
        player.animFrame = 0;
        player.animTimer = 0;
      }
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4a8f3a";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#2f5f23";
      ctx.fillRect(p.x, p.y, p.w, 6);
    }

    function drawPlayer() {
      // simple animated sprite made of colored rectangles
      const colors = ["#ffcc66", "#ffb347", "#ff9933", "#ffb347"];
      const c = colors[player.animFrame];

      ctx.save();
      if (player.facing === "left") {
        ctx.translate(player.x + player.w, player.y);
        ctx.scale(-1, 1);
      } else {
        ctx.translate(player.x, player.y);
      }

      // body
      ctx.fillStyle = c;
      ctx.fillRect(4, 12, 24, 28);

      // head
      ctx.fillStyle = "#ffe0bd";
      ctx.fillRect(8, 2, 16, 14);

      // eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(11, 7, 3, 3);
      ctx.fillRect(18, 7, 3, 3);

      // legs animation
      ctx.fillStyle = "#333";
      if (player.animFrame === 0 || player.animFrame === 2) {
        ctx.fillRect(7, 40, 6, 8);
        ctx.fillRect(19, 40, 6, 8);
      } else {
        ctx.fillRect(5, 40, 6, 8);
        ctx.fillRect(21, 40, 6, 8);
      }

      // arms
      ctx.fillStyle = "#ffcc66";
      ctx.fillRect(0, 16, 4, 12);
      ctx.fillRect(28, 16, 4, 12);

      ctx.restore();
    }

    function drawBackground() {
      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 5; i++) {
        const x = (i * 250 + (Date.now() * 0.01)) % (canvas.width + 120) - 120;
        const y = 60 + i * 40;
        ctx.beginPath();
        ctx.arc(x, y, 20, 0, Math.PI * 2);
        ctx.arc(x + 20, y - 10, 25, 0, Math.PI * 2);
        ctx.arc(x + 45, y, 18, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function loop() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      for (const p of platforms) drawPlatform(p);

      updatePlayer();
      drawPlayer();

      requestAnimationFrame(loop);
    }

    resetPlatforms();
    window.addEventListener("resize", resetPlatforms);

    loop();
  </script>
