  <div class="info">Move: Arrow Keys / A-D | Jump: Space / W / Up</div>
  <canvas id="game" width="800" height="450"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    window.addEventListener("keydown", (e) => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", (e) => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.55,
      friction: 0.82
    };

    const player = {
      x: 80,
      y: 300,
      w: 32,
      h: 40,
      vx: 0,
      vy: 0,
      speed: 0.65,
      jumpPower: 11,
      onGround: false,
      facing: 1,
      frame: 0,
      frameTimer: 0
    };

    const platforms = [
      { x: 0,   y: 410, w: 800, h: 40 },
      { x: 120, y: 330, w: 120, h: 18 },
      { x: 280, y: 280, w: 140, h: 18 },
      { x: 480, y: 230, w: 110, h: 18 },
      { x: 650, y: 180, w: 100, h: 18 }
    ];

    const goal = { x: 730, y: 140, w: 20, h: 40 };
    let won = false;

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      player.vx *= world.friction;
      player.vy += world.gravity;

      // Horizontal movement
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical movement
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep in bounds
      if (player.x < 0) { player.x = 0; player.vx = 0; }
      if (player.x + player.w > canvas.width) {
        player.x = canvas.width - player.w;
        player.vx = 0;
      }
      if (player.y > canvas.height) {
        player.x = 80;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (Math.abs(player.vx) > 0.2 && player.onGround) {
        player.frameTimer++;
        if (player.frameTimer % 8 === 0) {
          player.frame = (player.frame + 1) % 4;
        }
      } else {
        player.frame = 0;
      }

      // Win check
      if (rectsOverlap(player, goal)) {
        won = true;
      }
    }

    function drawBackground() {
      // simple hills
      ctx.fillStyle = "#9be28f";
      ctx.beginPath();
      ctx.arc(120, 410, 90, 0, Math.PI * 2);
      ctx.arc(300, 410, 130, 0, Math.PI * 2);
      ctx.arc(610, 410, 110, 0, Math.PI * 2);
      ctx.fill();

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (const c of [
        [110, 80], [250, 50], [520, 70], [680, 40]
      ]) {
        ctx.beginPath();
        ctx.arc(c[0], c[1], 18, 0, Math.PI * 2);
        ctx.arc(c[0] + 20, c[1] + 10, 22, 0, Math.PI * 2);
        ctx.arc(c[0] + 40, c[1], 16, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#6b4f3a";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#8fd17a";
      ctx.fillRect(p.x, p.y, p.w, 5);
    }

    function drawGoal() {
      ctx.fillStyle = "#ffd54a";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#ff4d4d";
      ctx.beginPath();
      ctx.moveTo(goal.x + goal.w, goal.y + 8);
      ctx.lineTo(goal.x + goal.w + 20, goal.y + 14);
      ctx.lineTo(goal.x + goal.w, goal.y + 20);
      ctx.fill();
    }

    function drawPlayer() {
      // Minimal sprite-animation effect with frame-based colors/poses
      const frames = [
        "#2d7dd2",
        "#3aaed8",
        "#4fc3f7",
        "#2d7dd2"
      ];

      const bodyColor = frames[player.frame];

      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);

      // body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(-player.w / 2, -player.h / 2, player.w, player.h);

      // face
      ctx.fillStyle = "#fff";
      ctx.fillRect(4, -10, 6, 6);
      ctx.fillStyle = "#000";
      ctx.fillRect(6, -8, 2, 2);

      // legs animation
      ctx.strokeStyle = "#222";
      ctx.lineWidth = 4;
      ctx.beginPath();
      if (player.frame === 1) {
        ctx.moveTo(-8, 18); ctx.lineTo(-12, 28);
        ctx.moveTo(8, 18);  ctx.lineTo(12, 24);
      } else if (player.frame === 2) {
        ctx.moveTo(-8, 18); ctx.lineTo(-12, 24);
        ctx.moveTo(8, 18);  ctx.lineTo(12, 28);
      } else {
        ctx.moveTo(-8, 18); ctx.lineTo(-10, 28);
        ctx.moveTo(8, 18);  ctx.lineTo(10, 28);
      }
      ctx.stroke();

      ctx.restore();
    }

    function drawWin() {
      if (!won) return;
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "#fff";
      ctx.font = "bold 42px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
    }

    function loop() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      platforms.forEach(drawPlatform);
      drawGoal();

      if (!won) updatePlayer();
      drawPlayer();
      drawWin();

      requestAnimationFrame(loop);
    }

    loop();
  </script>
