function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

function updatePlayer() {
  // Input
  player.vx = 0;
  if (keys["arrowleft"] || keys["a"]) {
    player.vx = -MOVE_SPEED;
    player.facing = -1;
  }
  if (keys["arrowright"] || keys["d"]) {
    player.vx = MOVE_SPEED;
    player.facing = 1;
  }

  // Jump
  if ((keys["arrowup"] || keys["w"] || keys[" "]) && player.onGround) {
    player.vy = -JUMP_SPEED;
    player.onGround = false;
  }

  // Gravity
  player.vy += GRAVITY;

  // Horizontal movement
  player.x += player.vx;
  for (const p of platforms) {
    if (rectsOverlap(player, p)) {
      if (player.vx > 0) player.x = p.x - player.w;
      if (player.vx < 0) player.x = p.x + p.w;
    }
  }

  // Vertical movement
  player.y += player.vy;
  player.onGround = false;
  for (const p of platforms) {
    if (rectsOverlap(player, p)) {
      if (player.vy > 0) {
        player.y = p.y - player.h;
        player.vy = 0;
        player.onGround = true;
      } else if (player.vy < 0) {
        player.y = p.y + p.h;
        player.vy = 0;
      }
    }
  }

  // Keep inside screen
  player.x = Math.max(0, Math.min(canvas.width - player.w, player.x));
  if (player.y > canvas.height) {
    player.x = 50;
    player.y = 300;
    player.vy = 0;
  }

  // Simple animation
  if (Math.abs(player.vx) > 0 && player.onGround) {
    player.frameTimer++;
    if (player.frameTimer > 8) {
      player.frame = (player.frame + 1) % 4;
      player.frameTimer = 0;
    }
  } else {
    player.frame = 0;
    player.frameTimer = 0;
  }
}

function drawPlayer() {
  // "Sprite" animation using simple color frames
  const colors = ["#ffcc66", "#ff9966", "#ff6699", "#cc66ff"];
  ctx.fillStyle = colors[player.frame];

  // Body
  ctx.fillRect(player.x, player.y, player.w, player.h);

  // Eyes
  ctx.fillStyle = "#000";
  const eyeX = player.facing === 1 ? player.x + 20 : player.x + 8;
  ctx.fillRect(eyeX, player.y + 12, 4, 4);

  // Feet
  ctx.fillStyle = "#333";
  ctx.fillRect(player.x + 6, player.y + 42, 8, 6);
  ctx.fillRect(player.x + 18, player.y + 42, 8, 6);
}

function drawPlatforms() {
  ctx.fillStyle = "#4b3f72";
  for (const p of platforms) {
    ctx.fillRect(p.x, p.y, p.w, p.h);
  }
}

function drawBackground() {
  // simple clouds
  ctx.fillStyle = "rgba(255,255,255,0.7)";
  ctx.beginPath();
  ctx.arc(120, 80, 20, 0, Math.PI * 2);
  ctx.arc(145, 75, 25, 0, Math.PI * 2);
  ctx.arc(175, 80, 20, 0, Math.PI * 2);
  ctx.fill();

  ctx.beginPath();
  ctx.arc(560, 60, 18, 0, Math.PI * 2);
  ctx.arc(585, 55, 24, 0, Math.PI * 2);
  ctx.arc(615, 60, 18, 0, Math.PI * 2);
  ctx.fill();
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawBackground();
  drawPlatforms();
  updatePlayer();
  drawPlayer();

  requestAnimationFrame(gameLoop);
}

gameLoop();
</script>
</body>
</html>
