      onGround: false,
      facing: 1,
      animFrame: 0,
      animTimer: 0,
    };

    // Minimal sprite animation: generate frames on an offscreen canvas
    function makeFrame(frame, facing) {
      const c = document.createElement("canvas");
      c.width = 40;
      c.height = 56;
      const g = c.getContext("2d");

      // body
      g.fillStyle = "#2b6cb0";
      g.fillRect(10, 18, 20, 24);

      // head
      g.fillStyle = "#f1c27d";
      g.fillRect(12, 4, 16, 16);

      // eyes
      g.fillStyle = "#000";
      g.fillRect(facing === 1 ? 18 : 14, 10, 2, 2);
      g.fillRect(facing === 1 ? 22 : 18, 10, 2, 2);

      // legs animation
      g.fillStyle = "#1a202c";
      if (frame === 0) {
        g.fillRect(10, 42, 6, 12);
        g.fillRect(24, 42, 6, 12);
      } else if (frame === 1) {
        g.fillRect(8, 42, 6, 12);
        g.fillRect(26, 40, 6, 14);
      } else {
        g.fillRect(8, 40, 6, 14);
        g.fillRect(26, 42, 6, 12);
      }

      // arms
      g.fillStyle = "#f1c27d";
      g.fillRect(6, 20, 4, 12);
      g.fillRect(30, 20, 4, 12);

      // flip if facing left
      if (facing === -1) {
        const flipped = document.createElement("canvas");
        flipped.width = 40;
        flipped.height = 56;
        const fg = flipped.getContext("2d");
        fg.translate(40, 0);
        fg.scale(-1, 1);
        fg.drawImage(c, 0, 0);
        return flipped;
      }

      return c;
    }

    const animationFrames = [
      [makeFrame(0, 1), makeFrame(1, 1), makeFrame(2, 1)],
      [makeFrame(0, -1), makeFrame(1, -1), makeFrame(2, -1)],
    ];

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

