      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      player.vx = 0;
      if (left) {
        player.vx = -moveSpeed;
        player.facing = -1;
      }
      if (right) {
        player.vx = moveSpeed;
        player.facing = 1;
      }

      // jump
      if (jump && player.onGround) {
        player.vy = -jumpSpeed;
        player.onGround = false;
      }

      // physics
      player.vy += gravity;
      player.x += player.vx;
      player.y += player.vy;

      // world bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;

      // collision with platforms
      player.onGround = false;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          const prevY = player.y - player.vy;
          const prevBottom = prevY + player.h;

          // Landing on top of platform
          if (prevBottom <= p.y && player.vy >= 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // Hitting underside
          else if (prevY >= p.y + p.h && player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          // Side collision
          else {
            if (player.vx > 0) player.x = p.x - player.w;
            if (player.vx < 0) player.x = p.x + p.w;
          }
        }
      }

      // animation
      if (Math.abs(player.vx) > 0 && player.onGround) {
        player.animTimer++;
        if (player.animTimer >= 8) {
          player.animFrame = (player.animFrame + 1) % 3;
          player.animTimer = 0;
        }
      } else {
        player.animFrame = 0;
        player.animTimer = 0;
      }
    }

    function drawPlatforms() {
      ctx.fillStyle = "#4a5568";
      for (const p of platforms) {
        ctx.fillRect(p.x, p.y, p.w, p.h);
      }
    }

    function drawPlayer() {
      const facingIndex = player.facing === 1 ? 0 : 1;
      const frameImg = animationFrames[facingIndex][player.animFrame];
      ctx.drawImage(frameImg, player.x, player.y, player.w, player.h);
    }

    function drawBackground() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // simple clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      ctx.beginPath();
      ctx.arc(120, 80, 22, 0, Math.PI * 2);
      ctx.arc(145, 70, 28, 0, Math.PI * 2);
