      ctx.arc(645, 80, 30, 0, Math.PI * 2);
      ctx.arc(680, 92, 18, 0, Math.PI * 2);
      ctx.fill();

      // ground tint
      ctx.fillStyle = "rgba(80, 200, 120, 0.15)";
      ctx.fillRect(0, 430, canvas.width, 70);
    }

    function loop() {
      updatePlayer();
      drawBackground();
      drawPlatforms();
      drawPlayer();
      requestAnimationFrame(loop);
    }

