      vy: 0,
      speed: 3.5,
      jumpPower: 13,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    const platforms = [
      { x: -200, y: 500, w: 1000, h: 50 },
      { x: 220, y: 400, w: 120, h: 20 },
      { x: 400, y: 340, w: 120, h: 20 },
      { x: 590, y: 280, w: 120, h: 20 },
      { x: 760, y: 220, w: 140, h: 20 },
      { x: 980, y: 360, w: 160, h: 20 },
      { x: 1240, y: 430, w: 180, h: 20 },
      { x: 1500, y: 370, w: 180, h: 20 }
    ];

    const goal = { x: 1700, y: 310, w: 40, h: 60 };

    let cameraX = 0;
    let cameraY = 0;
    let win = false;

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      player.vx = move * player.speed;
      if (move !== 0) player.facing = move;

      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      player.vy += world.gravity;

      // Horizontal movement
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
        }
      }

      // Vertical movement
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
