        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7d5f3b";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }

      // Goal
      ctx.fillStyle = win ? "#ffd54a" : "#ff4d4d";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#fff";
      ctx.fillRect(goal.x + 12, goal.y + 10, 16, 12);

      // Player "sprite" animation
      const colors = ["#ff5c5c", "#ff8b5c", "#ffd15c", "#7cff5c"];
      const bodyColor = colors[player.frame];

      // body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(player.x, player.y, player.w, player.h);

      // face direction marker
      ctx.fillStyle = "#222";
      const eyeX = player.facing === 1 ? player.x + 22 : player.x + 8;
      ctx.fillRect(eyeX, player.y + 14, 4, 4);

      // legs animation
      ctx.fillStyle = "#333";
      const legOffset = player.onGround ? (player.frame % 2) * 4 : 0;
      ctx.fillRect(player.x + 6 + legOffset, player.y + 42, 6, 6);
      ctx.fillRect(player.x + 20 - legOffset, player.y + 42, 6, 6);

      ctx.restore();

      // UI
      ctx.fillStyle = "#fff";
      ctx.font = "24px sans-serif";
      if (win) {
        ctx.fillText("You reached the goal!", 20, 50);
      }
    }

    function loop() {
      updatePlayer();
      drawWorld();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
