}

function drawPlayer() {
  // Minimal animated "sprite" frames
  const colors = ["#ff4d4d", "#ff7f50", "#ffcc4d", "#7cff4d"];
  const bodyColor = colors[player.animFrame];

  ctx.save();
  ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
  ctx.scale(player.facing, 1);
  ctx.translate(-player.w / 2, -player.h / 2);

  // body
  ctx.fillStyle = bodyColor;
  ctx.fillRect(8, 12, 16, 24);

  // head
  ctx.fillStyle = "#f5d7b2";
  ctx.fillRect(10, 4, 12, 10);

  // legs
  ctx.fillStyle = "#333";
  ctx.fillRect(8, 36, 6, 10);
  ctx.fillRect(18, 36, 6, 10);

  // simple run animation detail
  if (player.onGround && player.vx !== 0) {
    ctx.fillStyle = "#222";
    ctx.fillRect(6, 40, 8, 4);
    ctx.fillRect(18, 40, 8, 4);
  }

  ctx.restore();
}

function drawGoal() {
  ctx.fillStyle = "#ffd700";
  ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
  ctx.strokeStyle = "#000";
  ctx.strokeRect(goal.x, goal.y, goal.w, goal.h);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // clouds
  ctx.fillStyle = "rgba(255,255,255,0.6)";
  ctx.beginPath(); ctx.arc(100, 80, 20, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(125, 75, 25, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(150, 85, 18, 0, Math.PI * 2); ctx.fill();

  for (const p of platforms) drawPlatform(p);
  drawGoal();
  drawPlayer();

  ctx.fillStyle = "#000";
  ctx.font = "18px sans-serif";
  ctx.fillText("Move: A/D or ←/→   Jump: W/↑/Space", 12, 24);

  if (won) {
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#fff";
    ctx.font = "40px sans-serif";
    ctx.fillText("You Win!", 330, 220);
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
</script>
</body>
</html>
