<canvas id="game" width="800" height="450"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

const keys = {};
window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

const GRAVITY = 0.5;
const MOVE_SPEED = 3.5;
const JUMP_SPEED = 10;

const world = {
  platforms: [
    { x: 0,   y: 410, w: 800, h: 40 },
    { x: 120, y: 330, w: 120, h: 20 },
    { x: 300, y: 280, w: 120, h: 20 },
    { x: 480, y: 220, w: 150, h: 20 },
    { x: 680, y: 350, w: 90,  h: 20 }
  ]
};

const player = {
  x: 50,
  y: 350,
  w: 32,
  h: 48,
  vx: 0,
  vy: 0,
  onGround: false,
  frame: 0,
  frameTimer: 0,
  facing: 1
};

// Simple generated sprite frames (walking animation)
function drawPlayer(ctx, x, y, w, h, frame, facing) {
  ctx.save();
  ctx.translate(x + w / 2, y + h / 2);
  ctx.scale(facing, 1);
  ctx.translate(-w / 2, -h / 2);

  // Body
  ctx.fillStyle = "#2c3e50";
  ctx.fillRect(8, 14, 16, 20);

  // Head
  ctx.fillStyle = "#f1c27d";
  ctx.fillRect(10, 2, 12, 12);

  // Eyes
  ctx.fillStyle = "#000";
  ctx.fillRect(13, 6, 2, 2);
  ctx.fillRect(18, 6, 2, 2);

  // Legs animation
  ctx.fillStyle = "#34495e";
  if (frame === 0) {
    ctx.fillRect(9, 34, 6, 12);
    ctx.fillRect(17, 32, 6, 14);
  } else {
    ctx.fillRect(9, 32, 6, 14);
    ctx.fillRect(17, 34, 6, 12);
  }

  // Arms
  ctx.fillStyle = "#e67e22";
  if (frame === 0) {
    ctx.fillRect(4, 16, 4, 12);
    ctx.fillRect(24, 18, 4, 12);
  } else {
    ctx.fillRect(4, 18, 4, 12);
    ctx.fillRect(24, 16, 4, 12);
  }

  ctx.restore();
}

function rectsIntersect(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

function update() {
  // Horizontal movement
  player.vx = 0;
  if (keys["a"] || keys["arrowleft"]) {
    player.vx = -MOVE_SPEED;
    player.facing = -1;
  }
  if (keys["d"] || keys["arrowright"]) {
    player.vx = MOVE_SPEED;
    player.facing = 1;
  }

  // Jump
  if ((keys["w"] || keys["arrowup"] || keys[" "]) && player.onGround) {
    player.vy = -JUMP_SPEED;
    player.onGround = false;
  }

  // Physics
  player.vy += GRAVITY;
  player.x += player.vx;
  player.y += player.vy;

  // World bounds
  if (player.x < 0) player.x = 0;
  if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;

  // Collision detection
  player.onGround = false;
  for (const p of world.platforms) {
    const prevBottom = player.y - player.vy + player.h;
    const prevTop = player.y - player.vy;
    const prevRight = player.x - player.vx + player.w;
    const prevLeft = player.x - player.vx;

    if (rectsIntersect(player, p)) {
      // Landing on top
      if (prevBottom <= p.y) {
        player.y = p.y - player.h;
        player.vy = 0;
        player.onGround = true;
      }
      // Hitting underside
      else if (prevTop >= p.y + p.h) {
        player.y = p.y + p.h;
        player.vy = 0;
      }
      // From left
      else if (prevRight <= p.x) {
        player.x = p.x - player.w;
      }
      // From right
      else if (prevLeft >= p.x + p.w) {
        player.x = p.x + p.w;
      }
    }
  }

  // Animation
  if (Math.abs(player.vx) > 0 && player.onGround) {
    player.frameTimer++;
    if (player.frameTimer > 10) {
      player.frame = (player.frame + 1) % 2;
      player.frameTimer = 0;
    }
  } else {
    player.frame = 0;
    player.frameTimer = 0;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Clouds
  ctx.fillStyle = "rgba(255,255,255,0.8)";
  ctx.beginPath(); ctx.arc(120, 70, 20, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(145, 65, 25, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(175, 72, 18, 0, Math.PI * 2); ctx.fill();

  // Platforms
  for (const p of world.platforms) {
    ctx.fillStyle = "#6b4f2a";
    ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.fillStyle = "#3c8d3c";
    ctx.fillRect(p.x, p.y, p.w, 6);
  }

  // Player
  drawPlayer(ctx, player.x, player.y, player.w, player.h, player.frame, player.facing);

  // UI
  ctx.fillStyle = "#000";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: W/Up/Space", 12, 24);
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

loop();
</script>
