</head>
<body>
  <div class="hint">
    Move: A/D or ←/→ | Jump: Space/W/↑ | Restart: R
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const W = canvas.width;
    const H = canvas.height;

    const keys = {};
    addEventListener("keydown", e => {
      keys[e.key.toLowerCase()] = true;
      if (e.key.toLowerCase() === "r") reset();
    });
    addEventListener("keyup", e => {
      keys[e.key.toLowerCase()] = false;
    });

    const gravity = 0.6;

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 3.5,
      jumpPower: 12,
      onGround: false,
      facing: 1,
      animTime: 0
    };

    const platforms = [
      { x: 0,   y: 500, w: 960, h: 40 },
      { x: 120, y: 420, w: 160, h: 20 },
      { x: 340, y: 360, w: 180, h: 20 },
      { x: 600, y: 300, w: 160, h: 20 },
      { x: 780, y: 230, w: 120, h: 20 },
      { x: 500, y: 460, w: 100, h: 20 }
    ];

    const goal = { x: 860, y: 180, w: 30, h: 50 };
    let won = false;

    function reset() {
      player.x = 80;
      player.y = 100;
      player.vx = 0;
      player.vy = 0;
      won = false;
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      if (won) return;

      // Horizontal input
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      player.vx = move * player.speed;
      if (move !== 0) player.facing = move;

      // Jump
      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Gravity
      player.vy += gravity;

      // Move X
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
        }
      }

      // Move Y
      player.y += player.vy;
      player.onGround = false;

      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep on screen
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > W) player.x = W - player.w;
      if (player.y > H + 200) reset();

      // Goal
      if (rectsOverlap(player, goal)) won = true;

      player.animTime += Math.abs(player.vx) > 0 ? 0.15 : 0.05;
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4b5563";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#6b7280";
      ctx.fillRect(p.x, p.y, p.w, 6);
    }

    function drawPlayer() {
      const t = player.animTime;
      const bob = player.onGround && Math.abs(player.vx) > 0 ? Math.sin(t * 8) * 1.5 : 0;

      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2 + bob);
      ctx.scale(player.facing, 1);

      // Body
      ctx.fillStyle = "#f97316";
      ctx.fillRect(-16, -22, 32, 32);

      // Head
      ctx.fillStyle = "#fed7aa";
      ctx.fillRect(-12, -36, 24, 18);

      // Eyes
      ctx.fillStyle = "#111827";
      ctx.fillRect(4, -30, 3, 3);
      ctx.fillRect(-7, -30, 3, 3);

      // Legs animation
      const legSwing = player.onGround ? Math.sin(t * 10) * 4 : 0;

      ctx.fillStyle = "#1f2937";
      ctx.fillRect(-12, 10, 8, 14);
      ctx.fillRect(4, 10 + legSwing, 8, 14 - legSwing);

      // Arms
      ctx.fillStyle = "#fdba74";
      ctx.fillRect(-22, -10, 8, 16);
      ctx.fillRect(14, -10, 8, 16);

      ctx.restore();
    }

    function drawGoal() {
      ctx.fillStyle = "#22c55e";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#166534";
      ctx.fillRect(goal.x + 4, goal.y + 6, goal.w - 8, goal.h - 12);
    }

    function drawBackground() {
      // simple clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 5; i++) {
        const x = (i * 220 + (performance.now() * 0.01)) % (W + 100) - 80;
        const y = 60 + (i % 3) * 35;
        ctx.beginPath();
        ctx.arc(x, y, 22, 0, Math.PI * 2);
        ctx.arc(x + 22, y - 10, 28, 0, Math.PI * 2);
        ctx.arc(x + 50, y, 20, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, W, H);
      drawBackground();

      // Ground shadow strip
      ctx.fillStyle = "rgba(0,0,0,0.08)";
      ctx.fillRect(0, 500, W, 40);

      for (const p of platforms) drawPlatform(p);
      drawGoal();
      drawPlayer();

      if (won) {
        ctx.fillStyle = "rgba(0,0,0,0.45)";
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", W / 2, H / 2 - 10);
        ctx.font = "20px sans-serif";
        ctx.fillText("Press R to restart", W / 2, H / 2 + 30);
      }
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
