```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 14px;
      text-shadow: 0 1px 2px black;
    }
  </style>
</head>
<body>
  <div class="hud">Arrow keys / A,D to move • Space to jump</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const gravity = 0.5;
    const friction = 0.8;

    const player = {
      x: 100, y: 100,
      w: 32, h: 48,
      vx: 0, vy: 0,
      speed: 0.6,
      jumpPower: 11,
      onGround: false,
      facing: 1,
      animFrame: 0,
      animTimer: 0
    };

    const platforms = [
      { x: 0, y: 500, w: 960, h: 40 },
      { x: 120, y: 420, w: 160, h: 20 },
      { x: 340, y: 360, w: 160, h: 20 },
      { x: 560, y: 300, w: 160, h: 20 },
      { x: 760, y: 240, w: 120, h: 20 },
      { x: 240, y: 220, w: 90, h: 20 }
    ];

    const goal = { x: 820, y: 190, w: 30, h: 50 };

    function rectsCollide(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollision(entity, platform) {
      const prevX = entity.x - entity.vx;
      const prevY = entity.y - entity.vy;

      if (prevY + entity.h <= platform.y) {
        entity.y = platform.y - entity.h;
        entity.vy = 0;
        entity.onGround = true;
      } else if (prevY >= platform.y + platform.h) {
        entity.y = platform.y + platform.h;
        entity.vy = 0;
      } else if (prevX + entity.w <= platform.x) {
        entity.x = platform.x - entity.w;
        entity.vx = 0;
      } else if (prevX >= platform.x + platform.w) {
        entity.x = platform.x + platform.w;
        entity.vx = 0;
      }
    }

    function update() {
      // Horizontal control
      if (keys["arrowleft"] || keys["a"]) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (keys["arrowright"] || keys["d"]) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Jump
      if ((keys[" "] || keys["space"]) && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += gravity;
      player.vx *= friction;

      player.x += player.vx;
      player.y += player.vy;

      player.onGround = false;

      // Collision with platforms
      for (const p of platforms) {
        if (rectsCollide(player, p)) {
          resolveCollision(player, p);
        }
      }

      // Keep player in bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > canvas.width) {
        player.x = canvas.width - player.w;
        player.vx = 0;
      }
      if (player.y > canvas.height) {
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Basic animation: advance frame when moving
      if (Math.abs(player.vx) > 0.3 && player.onGround) {
        player.animTimer++;
        if (player.animTimer > 6) {
          player.animFrame = (player.animFrame + 1) % 4;
          player.animTimer = 0;
        }
      } else {
        player.animFrame = 0;
        player.animTimer = 0;
      }

      // Win condition
      if (rectsCollide(player, goal)) {
        alert("You reached the goal!");
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function drawPlayer() {
      // Draw a simple animated sprite made of shapes
      const x = player.x;
      const y = player.y;

      // body colors vary by frame to simulate animation
      const colors = ["#ffcc80", "#ffb74d", "#ffa726", "#fb8c00"];
      const bodyColor = colors[player.animFrame];

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.fillRect(x + 4, y + player.h - 4, player.w - 8, 6);

      // body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(x, y, player.w, player.h);

      // face / direction marker
      ctx.fillStyle = "#263238";
      if (player.facing === 1) {
        ctx.fillRect(x + 20, y + 14, 4, 4);
      } else {
        ctx.fillRect(x + 8, y + 14, 4, 4);
      }

      // legs animation
      ctx.fillStyle = "#37474f";
      if (player.onGround && Math.abs(player.vx) > 0.3) {
        if (player.animFrame % 2 === 0) {
          ctx.fillRect(x + 5, y + 40, 8, 8);
          ctx.fillRect(x + 19, y + 44, 8, 4);
        } else {
          ctx.fillRect(x + 5, y + 44, 8, 4);
          ctx.fillRect(x + 19, y + 40, 8, 8);
        }
      } else {
        ctx.fillRect(x + 5, y + 42, 8, 6);
        ctx.fillRect(x + 19, y + 42, 8, 6);
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // platforms
      ctx.fillStyle = "#4e342e";
      for (const p of platforms) {
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#6d4c41";
        ctx.fillRect(p.x, p.y, p.w, 6);
        ctx.fillStyle = "#4e342e";
      }

      // goal
      ctx.fillStyle = "#ffeb3b";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(goal.x + 12, goal.y + 8, 6, 6);

      drawPlayer();
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
