<canvas id="game"></canvas>

<script>
(() => {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");

  function resize() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  }
  window.addEventListener("resize", resize);
  resize();

  // Input
  const keys = {};
  window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
  window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

  // World
  const world = {
    gravity: 0.6,
    friction: 0.8
  };

  const player = {
    x: 100,
    y: 100,
    w: 32,
    h: 48,
    vx: 0,
    vy: 0,
    speed: 0.7,
    jumpPower: 12,
    onGround: false,
    facing: 1,
    animTime: 0,
    frame: 0
  };

  const platforms = [
    { x: 0, y: 560, w: 2000, h: 40 },
    { x: 150, y: 450, w: 150, h: 20 },
    { x: 350, y: 380, w: 160, h: 20 },
    { x: 580, y: 320, w: 160, h: 20 },
    { x: 850, y: 420, w: 200, h: 20 },
    { x: 1200, y: 500, w: 180, h: 20 }
  ];

  // Create a tiny animated sprite sheet dynamically
  function createSpriteSheet() {
    const s = document.createElement("canvas");
    s.width = 128;
    s.height = 32;
    const g = s.getContext("2d");

    for (let i = 0; i < 4; i++) {
      const x = i * 32;

      // body
      g.fillStyle = "#3b82f6";
      g.fillRect(x + 8, 8, 16, 20);

      // head
      g.fillStyle = "#f8c8a0";
      g.fillRect(x + 10, 2, 12, 8);

      // legs animation
      g.fillStyle = "#1f2937";
      if (i % 2 === 0) {
        g.fillRect(x + 8, 26, 6, 6);
        g.fillRect(x + 18, 24, 6, 8);
      } else {
        g.fillRect(x + 8, 24, 6, 8);
        g.fillRect(x + 18, 26, 6, 6);
      }

      // arms
      g.fillStyle = "#2563eb";
      g.fillRect(x + 4, 10, 4, 14);
      g.fillRect(x + 24, 10, 4, 14);

      // eyes
      g.fillStyle = "#111827";
      g.fillRect(x + 12, 4, 2, 2);
      g.fillRect(x + 17, 4, 2, 2);
    }

    return s;
  }

  const spriteSheet = createSpriteSheet();

  function rectsIntersect(a, b) {
    return (
      a.x < b.x + b.w &&
      a.x + a.w > b.x &&
      a.y < b.y + b.h &&
      a.y + a.h > b.y
    );
  }

  function update() {
    // Horizontal movement
    if (keys["a"] || keys["arrowleft"]) {
      player.vx -= player.speed;
      player.facing = -1;
    }
    if (keys["d"] || keys["arrowright"]) {
      player.vx += player.speed;
      player.facing = 1;
    }

    // Jump
    if ((keys[" "] || keys["arrowup"] || keys["w"]) && player.onGround) {
      player.vy = -player.jumpPower;
      player.onGround = false;
    }

    // Physics
    player.vy += world.gravity;
    player.vx *= world.friction;

    // Move X & resolve collisions
    player.x += player.vx;
    for (const p of platforms) {
      if (rectsIntersect(player, p)) {
        if (player.vx > 0) player.x = p.x - player.w;
        else if (player.vx < 0) player.x = p.x + p.w;
        player.vx = 0;
      }
    }

    // Move Y & resolve collisions
    player.y += player.vy;
    player.onGround = false;
    for (const p of platforms) {
      if (rectsIntersect(player, p)) {
        if (player.vy > 0) {
          player.y = p.y - player.h;
          player.vy = 0;
          player.onGround = true;
        } else if (player.vy < 0) {
          player.y = p.y + p.h;
          player.vy = 0;
        }
      }
    }

    // Animation
    const moving = Math.abs(player.vx) > 0.5;
    if (moving && player.onGround) {
      player.animTime += 0.15;
      player.frame = Math.floor(player.animTime) % 4;
    } else {
      player.frame = 0;
    }

    // Keep player in bounds
    if (player.y > canvas.height + 200) {
      player.x = 100;
      player.y = 100;
      player.vx = 0;
      player.vy = 0;
    }
  }

  function drawPlatform(p) {
    ctx.fillStyle = "#4b5563";
    ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.fillStyle = "#6b7280";
    ctx.fillRect(p.x, p.y, p.w, 4);
  }

  function drawPlayer() {
    const sx = player.frame * 32;
    const sy = 0;
    const dx = Math.floor(player.x);
    const dy = Math.floor(player.y);

    ctx.save();
    if (player.facing === -1) {
      ctx.translate(dx + player.w, dy);
      ctx.scale(-1, 1);
      ctx.drawImage(spriteSheet, sx, sy, 32, 32, 0, 0, player.w, player.h);
    } else {
      ctx.drawImage(spriteSheet, sx, sy, 32, 32, dx, dy, player.w, player.h);
    }
    ctx.restore();
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Simple parallax-ish ground decoration
    ctx.fillStyle = "rgba(255,255,255,0.2)";
    for (let i = 0; i < 30; i++) {
      ctx.beginPath();
      ctx.arc((i * 180 + Date.now() * 0.01) % (canvas.width + 200) - 100, 100 + (i % 5) * 20, 18, 0, Math.PI * 2);
      ctx.fill();
    }

    for (const p of platforms) drawPlatform(p);
    drawPlayer();

    // UI
    ctx.fillStyle = "#111827";
    ctx.font = "16px sans-serif";
    ctx.fillText("Move: A/D or ←/→   Jump: Space / W / ↑", 16, 24);
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }

  loop();
})();
</script>
