      overflow: hidden;
      background: #111;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
  </style>
</head>
<body>
<canvas id="game" width="900" height="500"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

const gravity = 0.6;
const friction = 0.85;

const keys = {
  left: false,
  right: false,
  up: false
};

window.addEventListener("keydown", (e) => {
  if (e.key === "ArrowLeft" || e.key.toLowerCase() === "a") keys.left = true;
  if (e.key === "ArrowRight" || e.key.toLowerCase() === "d") keys.right = true;
  if (e.key === "ArrowUp" || e.key === "w" || e.key === " ") keys.up = true;
});

window.addEventListener("keyup", (e) => {
  if (e.key === "ArrowLeft" || e.key.toLowerCase() === "a") keys.left = false;
  if (e.key === "ArrowRight" || e.key.toLowerCase() === "d") keys.right = false;
  if (e.key === "ArrowUp" || e.key.toLowerCase() === "w" || e.key === " ") keys.up = false;
});

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 32;
    this.h = 48;
    this.vx = 0;
    this.vy = 0;
    this.speed = 0.8;
    this.jumpPower = 12;
    this.onGround = false;
    this.frame = 0;
    this.frameTimer = 0;
    this.direction = 1;
  }

  update(platforms) {
    // Horizontal movement
    if (keys.left) {
      this.vx -= this.speed;
      this.direction = -1;
    }
    if (keys.right) {
      this.vx += this.speed;
      this.direction = 1;
    }

    // Clamp speed
    this.vx = Math.max(Math.min(this.vx, 6), -6);

    // Jump
    if (keys.up && this.onGround) {
      this.vy = -this.jumpPower;
      this.onGround = false;
    }

    // Apply physics
    this.vy += gravity;
    this.x += this.vx;
    this.y += this.vy;

    // Friction
    this.vx *= friction;

    // World bounds
    if (this.x < 0) {
      this.x = 0;
      this.vx = 0;
    }
    if (this.x + this.w > canvas.width) {
      this.x = canvas.width - this.w;
      this.vx = 0;
    }

    // Platform collisions
    this.onGround = false;
    for (const p of platforms) {
      if (
        this.x < p.x + p.w &&
        this.x + this.w > p.x &&
        this.y < p.y + p.h &&
        this.y + this.h > p.y
      ) {
        const prevBottom = this.y + this.h - this.vy;
        const prevTop = this.y - this.vy;

        // Landing on top
        if (prevBottom <= p.y) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        }
        // Hitting from below
        else if (prevTop >= p.y + p.h) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
        else {
          // Side collision resolution
          if (this.x + this.w / 2 < p.x + p.w / 2) {
            this.x = p.x - this.w;
          } else {
            this.x = p.x + p.w;
          }
          this.vx = 0;
        }
      }
    }

    // Simple sprite animation
    if (Math.abs(this.vx) > 0.5) {
      this.frameTimer++;
      if (this.frameTimer > 8) {
        this.frame = (this.frame + 1) % 4;
        this.frameTimer = 0;
      }
    } else {
      this.frame = 0;
      this.frameTimer = 0;
    }
  }

  draw(ctx) {
    // "Sprite animation" using simple frame colors
    const colors = ["#ffcc66", "#ffb347", "#ff9933", "#ffcc66"];
    const bodyColor = colors[this.frame];

    // Flip based on direction
    ctx.save();
    ctx.translate(this.x + this.w / 2, this.y + this.h / 2);
    ctx.scale(this.direction, 1);
    ctx.translate(-this.w / 2, -this.h / 2);

    // Body
    ctx.fillStyle = bodyColor;
    ctx.fillRect(8, 12, 16, 24);

    // Head
    ctx.fillStyle = "#ffd9b3";
    ctx.fillRect(10, 0, 12, 12);

    // Legs animation
    ctx.fillStyle = "#333";
    const legOffset = this.frame % 2 === 0 ? 0 : 4;
    ctx.fillRect(8, 36, 6, 12 + legOffset);
    ctx.fillRect(18, 36, 6, 12 - legOffset);

    // Arms
    ctx.fillStyle = "#444";
    ctx.fillRect(4, 14, 4, 12);
    ctx.fillRect(24, 14, 4, 12);

    ctx.restore();
  }
}

const player = new Player(100, 100);

const platforms = [
  { x: 0, y: 460, w: 900, h: 40 },   // ground
  { x: 120, y: 380, w: 140, h: 20 },
  { x: 320, y: 320, w: 160, h: 20 },
  { x: 560, y: 260, w: 140, h: 20 },
  { x: 760, y: 200, w: 100, h: 20 }
];

function drawPlatforms() {
  for (const p of platforms) {
    ctx.fillStyle = "#2f8f2f";
    ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.fillStyle = "#1f5f1f";
    ctx.fillRect(p.x, p.y + p.h - 6, p.w, 6);
  }
}

function update() {
  player.update(platforms);
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Background hills
  ctx.fillStyle = "rgba(0,0,0,0.08)";
  ctx.beginPath();
  ctx.arc(150, 460, 100, 0, Math.PI * 2);
  ctx.arc(450, 470, 140, 0, Math.PI * 2);
  ctx.arc(750, 465, 110, 0, Math.PI * 2);
  ctx.fill();

  drawPlatforms();
  player.draw(ctx);

  // HUD
  ctx.fillStyle = "#000";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 10, 20);
}

function loop() {
  update();
  render();
  requestAnimationFrame(loop);
}

loop();
</script>
</body>
</html>
```

