```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 2D Platformer</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
  </style>
</head>
<body>
<canvas id="game" width="960" height="540"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

// --- Input ---
const keys = {};
window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

// --- World ---
const gravity = 0.6;
const friction = 0.8;

const platforms = [
  { x: 0, y: 500, w: 960, h: 40 },
  { x: 120, y: 400, w: 160, h: 20 },
  { x: 350, y: 330, w: 160, h: 20 },
  { x: 590, y: 260, w: 160, h: 20 },
  { x: 780, y: 380, w: 120, h: 20 }
];

// --- Player ---
const player = {
  x: 50,
  y: 100,
  w: 40,
  h: 56,
  vx: 0,
  vy: 0,
  speed: 0.7,
  jumpPower: 13,
  onGround: false,
  facing: 1,
  animFrame: 0,
  animTimer: 0
};

// Simple "sprite sheet" style animation using drawn frames
function drawPlayer(p) {
  const frame = p.animFrame % 4;

  // body
  ctx.fillStyle = "#2d6cdf";
  ctx.fillRect(p.x, p.y, p.w, p.h);

  // head
  ctx.fillStyle = "#ffd7b3";
  ctx.fillRect(p.x + 10, p.y + 6, 20, 18);

  // face
  ctx.fillStyle = "#111";
  ctx.fillRect(p.x + (p.facing === 1 ? 22 : 14), p.y + 12, 3, 3);

  // legs animation
  ctx.fillStyle = "#1b3d8a";
  if (frame === 0 || frame === 2) {
    ctx.fillRect(p.x + 8, p.y + 40, 8, 16);
    ctx.fillRect(p.x + 24, p.y + 40, 8, 16);
  } else {
    ctx.fillRect(p.x + 6, p.y + 40, 8, 16);
    ctx.fillRect(p.x + 26, p.y + 40, 8, 16);
  }

  // arms
  ctx.fillStyle = "#2d6cdf";
  ctx.fillRect(p.x - 4, p.y + 20, 8, 18);
  ctx.fillRect(p.x + 36, p.y + 20, 8, 18);
}

// --- Enemy ---
const enemy = {
  x: 300,
  y: 464,
  w: 36,
  h: 36,
  vx: 1.2,
  vy: 0
};

function drawEnemy(e) {
  ctx.fillStyle = "#e74c3c";
  ctx.fillRect(e.x, e.y, e.w, e.h);
  ctx.fillStyle = "#fff";
  ctx.fillRect(e.x + 8, e.y + 10, 6, 6);
  ctx.fillRect(e.x + 22, e.y + 10, 6, 6);
  ctx.fillStyle = "#111";
  ctx.fillRect(e.x + 10, e.y + 12, 2, 2);
  ctx.fillRect(e.x + 24, e.y + 12, 2, 2);
}

// --- Collision helpers ---
function rectsOverlap(a, b) {
  return a.x < b.x + b.w &&
         a.x + a.w > b.x &&
         a.y < b.y + b.h &&
         a.y + a.h > b.y;
}

function resolveCollision(obj, plat) {
  const prevBottom = obj.prevY + obj.h;
  const prevTop = obj.prevY;
  const prevRight = obj.prevX + obj.w;
  const prevLeft = obj.prevX;

  // Landing on top
  if (prevBottom <= plat.y && obj.y + obj.h >= plat.y) {
    obj.y = plat.y - obj.h;
    obj.vy = 0;
    obj.onGround = true;
  }
  // Hitting from below
  else if (prevTop >= plat.y + plat.h && obj.y <= plat.y + plat.h) {
    obj.y = plat.y + plat.h;
    obj.vy = 0;
  }
  // From left
  else if (prevRight <= plat.x && obj.x + obj.w >= plat.x) {
    obj.x = plat.x - obj.w;
    obj.vx = 0;
  }
  // From right
  else if (prevLeft >= plat.x + plat.w && obj.x <= plat.x + plat.w) {
    obj.x = plat.x + plat.w;
    obj.vx = 0;
  }
}

// --- Update ---
function updatePlayer() {
  player.prevX = player.x;
  player.prevY = player.y;
  player.onGround = false;

  // movement
  if (keys["a"] || keys["arrowleft"]) {
    player.vx -= player.speed;
    player.facing = -1;
  }
  if (keys["d"] || keys["arrowright"]) {
    player.vx += player.speed;
    player.facing = 1;
  }

  // jump
  if ((keys["w"] || keys["arrowup"] || keys[" "]) && player.onGround) {
    player.vy = -player.jumpPower;
  }

  // physics
  player.vy += gravity;
  player.vx *= friction;

  player.x += player.vx;
  player.y += player.vy;

  // world bounds
  if (player.x < 0) { player.x = 0; player.vx = 0; }
  if (player.x + player.w > canvas.width) { player.x = canvas.width - player.w; player.vx = 0; }
  if (player.y > canvas.height) {
    player.y = 0;
    player.vy = 0;
  }

  // collisions
  for (const plat of platforms) {
    if (rectsOverlap(player, plat)) {
      resolveCollision(player, plat);
    }
  }

  // animation
  if (Math.abs(player.vx) > 0.5 && player.onGround) {
    player.animTimer++;
    if (player.animTimer > 8) {
      player.animFrame = (player.animFrame + 1) % 4;
      player.animTimer = 0;
    }
  } else {
    player.animFrame = 0;
  }
}

function updateEnemy() {
  enemy.prevX = enemy.x;
  enemy.prevY = enemy.y;

  enemy.vy += gravity;
  enemy.x += enemy.vx;
  enemy.y += enemy.vy;

  // simple patrol on ground
  if (enemy.x < 0 || enemy.x + enemy.w > canvas.width) {
    enemy.vx *= -1;
  }

  enemy.onGround = false;
  for (const plat of platforms) {
    if (rectsOverlap(enemy, plat)) {
      // only resolve landing
      if (enemy.prevY + enemy.h <= plat.y) {
        enemy.y = plat.y - enemy.h;
        enemy.vy = 0;
        enemy.onGround = true;
      }
      // turn around at edges
      if (enemy.onGround && Math.random() < 0.01) enemy.vx *= -1;
    }
  }

  // if no ground below, keep falling
  // (minimal logic, not perfect)
}

// --- Game logic ---
let gameOver = false;
function checkEnemyCollision() {
  if (rectsOverlap(player, enemy)) {
    const playerBottomPrev = player.prevY + player.h;
    const enemyTop = enemy.y;

    // stomp
    if (playerBottomPrev <= enemyTop && player.vy > 0) {
      enemy.x = 300;
      enemy.y = 0;
      enemy.vy = 0;
      player.vy = -10;
    } else {
      gameOver = true;
    }
  }
}

// --- Draw ---
function drawPlatforms() {
  for (const p of platforms) {
    ctx.fillStyle = "#4f5d75";
    ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.fillStyle = "#364156";
    ctx.fillRect(p.x, p.y, p.w, 4);
  }
}

function drawHUD() {
  ctx.fillStyle = "#000";
  ctx.font = "20px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: W / Up / Space", 20, 30);

  if (gameOver) {
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#fff";
    ctx.font = "48px sans-serif";
    ctx.fillText("Game Over", 380, 260);
  }
}

// --- Main loop ---
function loop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (!gameOver) {
    updatePlayer();
    updateEnemy();
    checkEnemyCollision();
  }

  drawPlatforms();
  drawEnemy(enemy);
  drawPlayer(player);
  drawHUD();

  requestAnimationFrame(loop);
}

loop();
</script>
</body>
</html>
