    }
  </style>
</head>
<body>
  <div class="info">
    Move: A/D or ←/→ &nbsp; Jump: W / Space / ↑
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.7,
      friction: 0.85
    };

    const player = {
      x: 80,
      y: 100,
      w: 34,
      h: 46,
      vx: 0,
      vy: 0,
      speed: 0.75,
      jumpPower: 13,
      onGround: false,
      facing: 1,
      animTime: 0
    };

    const platforms = [
      { x: 0,   y: 500, w: 960, h: 40 },
      { x: 120, y: 400, w: 160, h: 20 },
      { x: 340, y: 340, w: 180, h: 20 },
      { x: 600, y: 280, w: 160, h: 20 },
      { x: 780, y: 210, w: 120, h: 20 },
      { x: 70,  y: 250, w: 120, h: 20 }
    ];

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Input
      const left  = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump  = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Limit horizontal speed
      player.vx = Math.max(-6, Math.min(6, player.vx));

      // Jump
      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity;
      player.x += player.vx;
      player.y += player.vy;

      // Horizontal collision
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical collision
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Friction
      if (player.onGround) {
        player.vx *= world.friction;
        if (Math.abs(player.vx) < 0.1) player.vx = 0;
      } else {
        player.vx *= 0.99;
      }

      // Keep in bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;
      if (player.y > canvas.height + 200) {
        player.x = 80;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      player.animTime += 1;
    }

    function drawPlayer() {
      const t = player.animTime * 0.15;
      const bob = player.onGround ? Math.abs(Math.sin(t)) * 1.5 : 0;
      const legSwing = player.onGround ? Math.sin(t) * 3 : 0;

      const x = player.x;
      const y = player.y + bob;
      const w = player.w;
      const h = player.h;

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.beginPath();
      ctx.ellipse(x + w / 2, y + h + 6, 18, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = "#ffcc66";
      ctx.fillRect(x, y + 12, w, h - 12);

      // Head
      ctx.fillStyle = "#ffdca8";
      ctx.fillRect(x + 5, y, w - 10, 16);

      // Eyes
      ctx.fillStyle = "#222";
      const eyeX = player.facing === 1 ? x + 20 : x + 10;
      ctx.fillRect(eyeX, y + 6, 3, 3);
      ctx.fillRect(eyeX + 6, y + 6, 3, 3);

      // Arms
      ctx.strokeStyle = "#7a4c1f";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(x + 6, y + 22);
      ctx.lineTo(x - 4, y + 30);
      ctx.moveTo(x + w - 6, y + 22);
      ctx.lineTo(x + w + 4, y + 30);
      ctx.stroke();

      // Legs (animated)
      ctx.strokeStyle = "#4a2c12";
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(x + 10, y + h);
      ctx.lineTo(x + 7 + legSwing, y + h + 12);
      ctx.moveTo(x + w - 10, y + h);
      ctx.lineTo(x + w - 7 - legSwing, y + h + 12);
      ctx.stroke();

      // Tiny cape-like accent
      ctx.fillStyle = "#ff6b6b";
      ctx.fillRect(x + (player.facing === 1 ? -5 : w - 2), y + 14, 6, 18);
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#4b8f4b";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#2f6b2f";
        ctx.fillRect(p.x, p.y, p.w, 4);
      }
    }

    function drawBackground() {
      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 5; i++) {
        const cx = (i * 180 + (Date.now() * 0.01)) % (canvas.width + 120) - 60;
        const cy = 60 + (i % 3) * 30;
        ctx.beginPath();
        ctx.arc(cx, cy, 18, 0, Math.PI * 2);
        ctx.arc(cx + 18, cy - 8, 22, 0, Math.PI * 2);
        ctx.arc(cx + 40, cy, 18, 0, Math.PI * 2);
        ctx.fill();
      }

      // mountains
      ctx.fillStyle = "#7aa0a8";
      ctx.beginPath();
      ctx.moveTo(0, 500);
      ctx.lineTo(160, 310);
      ctx.lineTo(320, 500);
      ctx.lineTo(470, 280);
      ctx.lineTo(650, 500);
      ctx.lineTo(820, 330);
      ctx.lineTo(960, 500);
      ctx.closePath();
      ctx.fill();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawPlatforms();
      drawPlayer();
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
