## Minimal 2D Platformer (single-file)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #cfefff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 1px 2px rgba(0,0,0,0.6);
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or Arrow Keys | Jump: Space / W / Arrow Up
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.7,
      friction: 0.85
    };

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      animTime: 0,
      won: false
    };

    const platforms = [
      { x: 0, y: 560, w: 1200, h: 40 },
      { x: 180, y: 460, w: 160, h: 20 },
      { x: 390, y: 390, w: 160, h: 20 },
      { x: 610, y: 330, w: 160, h: 20 },
      { x: 830, y: 420, w: 140, h: 20 },
      { x: 1020, y: 500, w: 120, h: 20 }
    ];

    const goal = { x: 1080, y: 450, w: 24, h: 50 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function moveAndCollide(entity, solids) {
      entity.x += entity.vx;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vx > 0) entity.x = s.x - entity.w;
          else if (entity.vx < 0) entity.x = s.x + s.w;
          entity.vx = 0;
        }
      }

      entity.y += entity.vy;
      entity.onGround = false;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    function update() {
      if (!player.won) {
        const left = keys["a"] || keys["arrowleft"];
        const right = keys["d"] || keys["arrowright"];
        const jump = keys[" "] || keys["w"] || keys["arrowup"];

        if (left) {
          player.vx -= player.speed;
          player.facing = -1;
        }
        if (right) {
          player.vx += player.speed;
          player.facing = 1;
        }

        if (jump && player.onGround) {
          player.vy = -player.jumpPower;
          player.onGround = false;
        }

        player.vy += world.gravity;
        player.vx *= player.onGround ? world.friction : 0.99;

        // Clamp speeds
        player.vx = Math.max(-6, Math.min(6, player.vx));
        player.vy = Math.min(18, player.vy);

        moveAndCollide(player, platforms);

        // Fall reset
        if (player.y > canvas.height + 100) {
          player.x = 80;
          player.y = 100;
          player.vx = 0;
          player.vy = 0;
        }

        if (rectsOverlap(player, goal)) {
          player.won = true;
        }

        player.animTime += Math.abs(player.vx) + (player.onGround ? 0.2 : 0.05);
      }
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5d4037";
      ctx.fillRect(p.x, p.y, p.w, p.h);

      ctx.fillStyle = "#4caf50";
      ctx.fillRect(p.x, p.y, p.w, 6);
    }

    function drawGoal(g) {
      ctx.fillStyle = "#222";
      ctx.fillRect(g.x, g.y, g.w, g.h);
      ctx.fillStyle = "#ffd54f";
      ctx.beginPath();
      ctx.moveTo(g.x + g.w, g.y + 8);
      ctx.lineTo(g.x + g.w + 20, g.y + 16);
      ctx.lineTo(g.x + g.w, g.y + 24);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer(p) {
      const walkFrame = Math.floor(p.animTime / 8) % 4;
      const bob = p.onGround && Math.abs(p.vx) > 0.5 ? Math.sin(p.animTime / 4) * 1.5 : 0;

      ctx.save();
      ctx.translate(p.x + p.w / 2, p.y + p.h / 2 + bob);
      ctx.scale(p.facing, 1);

      // shadow-ish outline
      ctx.fillStyle = "#000000";
      ctx.fillRect(-p.w/2 + 2, -p.h/2 + 2, p.w - 4, p.h - 4);

      // body
      ctx.fillStyle = "#ffcc80";
      ctx.fillRect(-p.w/2 + 4, -p.h/2 + 6, p.w - 8, p.h - 10);

      // head
      ctx.fillStyle = "#ffe0b2";
      ctx.beginPath();
      ctx.arc(0, -p.h/2 + 12, 10, 0, Math.PI * 2);
      ctx.fill();

      // eyes
      ctx.fillStyle = "#263238";
      ctx.fillRect(4, -p.h/2 + 10, 3, 3);
      ctx.fillRect(-7, -p.h/2 + 10, 3, 3);

      // legs animation
      ctx.strokeStyle = "#263238";
      ctx.lineWidth = 4;
      ctx.beginPath();
      if (p.onGround && Math.abs(p.vx) > 0.5) {
        const legOffset = [ -3, 3, -4, 4 ][walkFrame];
        ctx.moveTo(-6, 18);
        ctx.lineTo(-8 + legOffset, 28);
        ctx.moveTo(6, 18);
        ctx.lineTo(8 - legOffset, 28);
      } else {
        ctx.moveTo(-6, 18);
        ctx.lineTo(-6, 28);
        ctx.moveTo(6, 18);
        ctx.lineTo(6, 28);
      }
      ctx.stroke();

      // arms
      ctx.beginPath();
      if (p.onGround && Math.abs(p.vx) > 0.5) {
        const armOffset = [ 3, -3, 4, -4 ][walkFrame];
        ctx.moveTo(-12, 2);
        ctx.lineTo(-16, 10 + armOffset);
        ctx.moveTo(12, 2);
        ctx.lineTo(16, 10 - armOffset);
      } else {
        ctx.moveTo(-12, 2);
        ctx.lineTo(-16, 10);
        ctx.moveTo(12, 2);
        ctx.lineTo(16, 10);
      }
      ctx.stroke();

      ctx.restore();
    }

    function drawBackground() {
      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      for (let i = 0; i < 5; i++) {
        const x = (i * 240 + (Date.now() * 0.01)) % (canvas.width + 200) - 100;
        const y = 60 + (i % 3) * 45;
        ctx.beginPath();
        ctx.arc(x, y, 18, 0, Math.PI * 2);
        ctx.arc(x + 18, y - 10, 24, 0, Math.PI * 2);
        ctx.arc(x + 40, y, 18, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // camera follow
      const camX = Math.max(0, player.x - canvas.width / 2 + player.w / 2);
      ctx.save();
      ctx.translate(-camX, 0);

      platforms.forEach(drawPlatform);
      drawGoal(goal);
      drawPlayer(player);

      ctx.restore();

      if (player.won) {
        ctx.fillStyle = "rgba(0,0,0,0.45)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
        ctx.font = "20px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 36);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }
    loop();
  </script>
</body>
</html>
```

