## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #05070c;
      font-family: system-ui, sans-serif;
    }
    #app {
      width: 100%;
      height: 100%;
    }
    .hud {
      position: fixed;
      left: 12px;
      top: 12px;
      color: #d7e7ff;
      background: rgba(0,0,0,0.35);
      padding: 10px 12px;
      border-radius: 8px;
      font-size: 13px;
      line-height: 1.4;
      pointer-events: none;
      user-select: none;
      backdrop-filter: blur(6px);
    }
  </style>
</head>
<body>
  <div class="hud">
    Drag to orbit · Scroll to zoom<br>
    Dynamic lighting + shader effects
  </div>
  <div id="app"></div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";
    import { EffectComposer } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js";
    import { RenderPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js";
    import { UnrealBloomPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js";

    const container = document.getElementById("app");

    // Renderer
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.1;
    container.appendChild(renderer.domElement);

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070c);
    scene.fog = new THREE.FogExp2(0x05070c, 0.03);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(5, 3, 8);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.minDistance = 3;
    controls.maxDistance = 22;
    controls.target.set(0, 0.8, 0);

    // Postprocessing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      0.9,   // strength
      0.5,   // radius
      0.2    // threshold
    );
    composer.addPass(bloomPass);

    // Lights
    const ambient = new THREE.AmbientLight(0x223344, 0.45);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 2.2);
    dirLight.position.set(5, 8, 4);
    scene.add(dirLight);

    const pointLight = new THREE.PointLight(0x66ccff, 18, 30, 2);
    pointLight.position.set(0, 2, 0);
    scene.add(pointLight);

    const secondPoint = new THREE.PointLight(0xff66aa, 10, 25, 2);
    secondPoint.position.set(-4, 1, -2);
    scene.add(secondPoint);

    // Ground
    const groundGeo = new THREE.PlaneGeometry(60, 60, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x0b1220,
      roughness: 0.95,
      metalness: 0.0
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1;
    scene.add(ground);

    // Subtle grid helper
    const grid = new THREE.GridHelper(60, 60, 0x1b3550, 0x122033);
    grid.position.y = -0.999;
    grid.material.transparent = true;
    grid.material.opacity = 0.35;
    scene.add(grid);

    // Custom shader material
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x53b7ff) },
        uColorB: { value: new THREE.Color(0xff5fd7) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalize(normalMatrix * normal);
          vec3 pos = position;

          float wave = sin(pos.y * 6.0 + uTime * 3.0) * 0.08;
          pos += normal * wave;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 lightDir = normalize(vec3(0.4, 1.0, 0.2));
          float diff = max(dot(n, lightDir), 0.0);

          float fresnel = pow(1.0 - max(dot(n, normalize(-vPosition)), 0.0), 2.5);
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 2.0);

          vec3 base = mix(uColorA, uColorB, pulse);
          vec3 color = base * (0.25 + diff * 0.9) + fresnel * 0.9;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Objects
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 220, 32),
      shaderMaterial
    );
    torus.position.set(0, 1.1, 0);
    scene.add(torus);

    const sphereMat = new THREE.MeshStandardMaterial({
      color: 0xe8f4ff,
      metalness: 0.9,
      roughness: 0.12,
      emissive: 0x112244,
      emissiveIntensity: 0.4
    });

    const spheres = [];
    for (let i = 0; i < 10; i++) {
      const s = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 24), sphereMat.clone());
      const angle = (i / 10) * Math.PI * 2;
      s.position.set(Math.cos(angle) * 3.2, 0.35 + (i % 3) * 0.25, Math.sin(angle) * 3.2);
      scene.add(s);
      spheres.push(s);
    }

    // Floating particles
    const particleCount = 800;
    const positions = new Float32Array(particleCount * 3);
    for (let i = 0; i < particleCount; i++) {
      positions[i * 3 + 0] = (Math.random() - 0.5) * 30;
      positions[i * 3 + 1] = Math.random() * 12 - 1;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 30;
    }
    const particleGeo = new THREE.BufferGeometry();
    particleGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const particleMat = new THREE.PointsMaterial({
      color: 0x89c8ff,
      size: 0.03,
      transparent: true,
      opacity: 0.7
    });
    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);

    // Animation
    const clock = new THREE.Clock();

    function animate() {
      const t = clock.getElapsedTime();

      shaderMaterial.uniforms.uTime.value = t;

      torus.rotation.x = t * 0.35;
      torus.rotation.y = t * 0.55;

      pointLight.position.x = Math.cos(t * 1.2) * 4.5;
      pointLight.position.z = Math.sin(t * 1.2) * 4.5;
      pointLight.position.y = 1.8 + Math.sin(t * 2.0) * 0.8;

      secondPoint.position.x = Math.sin(t * 0.8) * 5.0;
      secondPoint.position.z = Math.cos(t * 0.8) * 5.0;
      secondPoint.position.y = 1.0 + Math.cos(t * 1.7) * 0.7;

      spheres.forEach((s, i) => {
        const offset = i * 0.6;
        s.position.y = 0.35 + Math.sin(t * 1.5 + offset) * 0.25;
        s.rotation.x = t * 0.7 + offset;
        s.rotation.y = t * 1.1 - offset;
      });

      particles.rotation.y = t * 0.03;
      controls.update();

      composer.render();
      requestAnimationFrame(animate);
    }

    animate();

    // Resize
    window.addEventListener("resize", () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();

      renderer.setSize(w, h);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      composer.setSize(w, h);
    });
  </script>
</body>
</html>
```

