```javascript
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.getElementById("scene");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.physicallyCorrectLights = true;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070a);
scene.fog = new THREE.Fog(0x05070a, 12, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(5, 4, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x6677aa, 0.35);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.5);
directional.position.set(5, 10, 4);
scene.add(directional);

const pointLight = new THREE.PointLight(0x00d4ff, 40, 30, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

const movingLight = new THREE.SpotLight(0xff3d9a, 120, 50, Math.PI / 7, 0.25, 1);
movingLight.position.set(-5, 8, -5);
movingLight.target.position.set(0, 1, 0);
scene.add(movingLight, movingLight.target);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11161d,
  roughness: 1.0,
  metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = false;
scene.add(ground);

// Custom shader material
const customMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0xff3d9a) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vUv = uv;
      vNormal = normalMatrix * normal;
      vec3 pos = position;

      float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.08;
      wave += cos(pos.x * 5.0 + uTime * 1.5) * 0.05;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vPosition = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 n = normalize(vNormal);
      float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 3.0);

      float stripes = 0.5 + 0.5 * sin((vUv.x * 20.0 + uTime * 3.0) + vUv.y * 8.0);
      vec3 base = mix(uColorA, uColorB, stripes);

      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + length(vPosition.xz) * 2.0);
      vec3 color = base * (0.45 + 0.55 * pulse);

      color += fresnel * vec3(1.0);

      gl_FragColor = vec4(color, 1.0);
    }
  `
});

