      camera = new THREE.PerspectiveCamera(
        60,
        window.innerWidth / window.innerHeight,
        0.1,
        100
      );
      camera.position.set(0, 3, 10);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.outputColorSpace = THREE.SRGBColorSpace;
      renderer.toneMapping = THREE.ACESFilmicToneMapping;
      renderer.toneMappingExposure = 1.2;
      document.body.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;

      // Lights
      const ambient = new THREE.AmbientLight(0x223344, 0.7);
      scene.add(ambient);

      dirLight = new THREE.DirectionalLight(0xffffff, 2.2);
      dirLight.position.set(5, 8, 4);
      scene.add(dirLight);

      pointLight = new THREE.PointLight(0x00d5ff, 60, 30, 2);
      pointLight.position.set(0, 2, 0);
      scene.add(pointLight);

      const pointLight2 = new THREE.PointLight(0xff4fd8, 40, 25, 2);
      pointLight2.position.set(-4, -1, -2);
      scene.add(pointLight2);

      // Ground
      const groundGeo = new THREE.PlaneGeometry(80, 80, 1, 1);
      const groundMat = new THREE.MeshStandardMaterial({
        color: 0x0b1020,
        roughness: 1.0,
        metalness: 0.0
      });
      const ground = new THREE.Mesh(groundGeo, groundMat);
      ground.rotation.x = -Math.PI / 2;
      ground.position.y = -2;
      scene.add(ground);

      // Main object: shader-driven sphere
      const sphereGeo = new THREE.SphereGeometry(1.4, 128, 128);

      shaderUniforms = {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00d5ff) },
        uColorB: { value: new THREE.Color(0xff4fd8) }
      };

      const sphereMat = new THREE.ShaderMaterial({
        uniforms: shaderUniforms,
        vertexShader: `
          uniform float uTime;
          varying vec2 vUv;
          varying vec3 vNormal;
          varying vec3 vPosition;

          void main() {
            vUv = uv;
            vNormal = normalize(normalMatrix * normal);
            vec3 pos = position;

            // subtle animated displacement
            float wave = sin(pos.x * 6.0 + uTime * 2.0) * 0.06
                       + cos(pos.y * 8.0 + uTime * 1.5) * 0.06
                       + sin(pos.z * 5.0 + uTime * 2.2) * 0.05;

            pos += normal * wave;

            vPosition = (modelMatrix * vec4(pos, 1.0)).xyz;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
          }
        `,
        fragmentShader: `
          uniform float uTime;
          uniform vec3 uColorA;
          uniform vec3 uColorB;
          varying vec2 vUv;
          varying vec3 vNormal;
          varying vec3 vPosition;

          void main() {
            vec3 n = normalize(vNormal);
            vec3 lightDir = normalize(vec3(0.5, 1.0, 0.3));
            float diff = max(dot(n, lightDir), 0.0);

            float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.5);

            float bands = 0.5 + 0.5 * sin(vUv.y * 18.0 + uTime * 4.0);
            vec3 base = mix(uColorA, uColorB, bands);

            vec3 color = base * (0.22 + diff * 0.9) + fresnel * 0.9;
            color += 0.08 * sin(uTime + vPosition.xyx * 2.0).rgb;

            gl_FragColor = vec4(color, 1.0);
          }
        `,
        side: THREE.DoubleSide
      });

      sphere = new THREE.Mesh(sphereGeo, sphereMat);
      sphere.position.y = 0.2;
      scene.add(sphere);

      // Orbiting torus knot
      const knotGeo = new THREE.TorusKnotGeometry(0.8, 0.25, 180, 32);
      const knotMat = new THREE.MeshStandardMaterial({
        color: 0xffffff,
        metalness: 1.0,
        roughness: 0.15,
        emissive: 0x111122,
        emissiveIntensity: 0.4
      });
      torusKnot = new THREE.Mesh(knotGeo, knotMat);
      torusKnot.position.set(0, 0.2, 0);
      scene.add(torusKnot);

      // Decorative particles
      const particleGeo = new THREE.BufferGeometry();
      const count = 800;
      const positions = new Float32Array(count * 3);
      for (let i = 0; i < count; i++) {
        const r = 12 * Math.pow(Math.random(), 0.4);
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);
        positions[i * 3 + 0] = r * Math.sin(phi) * Math.cos(theta);
        positions[i * 3 + 1] = r * Math.cos(phi);
        positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
      }
      particleGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
      const particleMat = new THREE.PointsMaterial({
        color: 0x86d9ff,
        size: 0.03,
        transparent: true,
        opacity: 0.9
      });
      const particles = new THREE.Points(particleGeo, particleMat);
      scene.add(particles);

      window.addEventListener("resize", onResize);
    }

    function animate(t = 0) {
      requestAnimationFrame(animate);
      const time = t * 0.001;

      shaderUniforms.uTime.value = time;

      // Animate lighting
      pointLight.position.x = Math.sin(time * 1.2) * 3.5;
      pointLight.position.z = Math.cos(time * 1.2) * 3.5;
      pointLight.position.y = 1.5 + Math.sin(time * 2.0) * 0.7;

      dirLight.position.x = Math.cos(time * 0.5) * 6;
      dirLight.position.z = Math.sin(time * 0.5) * 6;

      // Animate objects
      sphere.rotation.y = time * 0.5;
      sphere.rotation.x = Math.sin(time * 0.4) * 0.15;

      torusKnot.rotation.x = time * 0.35;
      torusKnot.rotation.y = time * 0.6;
      torusKnot.position.y = 0.2 + Math.sin(time * 1.7) * 0.25;
      torusKnot.position.x = Math.sin(time * 0.8) * 1.8;
      torusKnot.position.z = Math.cos(time * 0.8) * 1.8;

      controls.update();
      renderer.render(scene, camera);
    }

    function onResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }
  </script>
</head>
<body>
  <div id="info">
    <strong>3D Scene Viewer</strong><br/>
    Drag to orbit • Scroll to zoom
  </div>
</body>
</html>
```

