const floorMat = new THREE.MeshStandardMaterial({
  color: 0x111427,
  roughness: 0.95,
  metalness: 0.0
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1;
scene.add(floor);

// Grid helper
const grid = new THREE.GridHelper(30, 30, 0x335577, 0x1b2238);
grid.position.y = -0.99;
scene.add(grid);

// Custom shader material for the main object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0.0 },
    uColorA: { value: new THREE.Color(0x4ac8ff) },
    uColorB: { value: new THREE.Color(0xff4fd8) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vNormal = normalMatrix * normal;
      vUv = uv;

      vec3 p = position;

      // Animated displacement
      float wave = sin(p.x * 4.0 + uTime * 2.0) * 0.08
                 + cos(p.y * 6.0 + uTime * 1.7) * 0.05
                 + sin(p.z * 3.0 + uTime * 2.4) * 0.06;

      p += normal * wave;
      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));

      float diff = max(dot(N, lightDir), 0.0);
      float fresnel = pow(1.0 - max(dot(N, vec3(0.0, 0.0, 1.0)), 0.0), 2.5);

      vec3 base = mix(uColorA, uColorB, 0.5 + 0.5 * sin(uTime + vUv.x * 6.0));
      vec3 color = base * (0.25 + 0.85 * diff);
      color += fresnel * 0.6;
      color += vWave * 2.0;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
  transparent: false,
  side: THREE.DoubleSide
});

// Main object
const geo = new THREE.IcosahedronGeometry(1.3, 4);
const mesh = new THREE.Mesh(geo, shaderMaterial);
mesh.position.set(0, 1.2, 0);
scene.add(mesh);

// Surrounding objects
const objects = [];
const torusMat = new THREE.MeshStandardMaterial({
  color: 0xccccff,
  metalness: 0.8,
  roughness: 0.2
});

for (let i = 0; i < 12; i++) {
  const torus = new THREE.Mesh(
    new THREE.TorusGeometry(0.28, 0.08, 16, 48),
    torusMat.clone()
  );
  const angle = (i / 12) * Math.PI * 2;
  torus.position.set(Math.cos(angle) * 3.2, 0.6 + Math.sin(i) * 0.5, Math.sin(angle) * 3.2);
  torus.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
  scene.add(torus);
  objects.push(torus);
}

// Simple animated particles
const particleCount = 200;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  const r = 8 * Math.random();
  const theta = Math.random() * Math.PI * 2;
  const y = (Math.random() - 0.5) * 5;

  positions[i * 3 + 0] = Math.cos(theta) * r;
  positions[i * 3 + 1] = y;
  positions[i * 3 + 2] = Math.sin(theta) * r;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.05,
  transparent: true,
  opacity: 0.8,
  depthWrite: false
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = elapsed;

  mesh.rotation.y = elapsed * 0.45;
  mesh.rotation.x = Math.sin(elapsed * 0.4) * 0.25;

  pointLight.position.x = Math.cos(elapsed * 1.2) * 4.0;
  pointLight.position.z = Math.sin(elapsed * 1.2) * 4.0;
  pointLight2.position.x = Math.cos(elapsed * 0.8 + Math.PI) * 4.5;
  pointLight2.position.z = Math.sin(elapsed * 0.8 + Math.PI) * 4.5;

  objects.forEach((obj, i) => {
    obj.rotation.x += 0.01 + i * 0.0005;
    obj.rotation.y += 0.015 + i * 0.0004;
    obj.position.y = 0.6 + Math.sin(elapsed * 1.5 + i) * 0.25;
  });

  particles.rotation.y = elapsed * 0.03;

  controls.update();
  renderer.render(scene, camera);

  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  const width = window.innerWidth;
  const height = window.innerHeight;

  camera.aspect = width / height;
  camera.updateProjectionMatrix();

  renderer.setSize(width, height);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
