        uColorB: { value: new THREE.Color(0xff2bd6) }
      },
      vertexShader: `
        varying vec3 vPosition;
        varying vec3 vNormal;

        void main() {
          vPosition = position;
          vNormal = normal;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vPosition;
        varying vec3 vNormal;

        void main() {
          float wave = sin(vPosition.y * 6.0 + uTime * 3.0) * 0.5 + 0.5;
          float pulse = sin(uTime * 2.0 + length(vPosition) * 3.0) * 0.5 + 0.5;
          vec3 color = mix(uColorA, uColorB, wave);
          color += pulse * 0.15;

          // simple lighting approximation using normal and fake view light
          float lighting = dot(normalize(vNormal), normalize(vec3(0.3, 0.8, 0.6))) * 0.5 + 0.5;
          color *= lighting;

          gl_FragColor = vec4(color, 1.0);
        }
