    grid.position.y = 0.01;
    scene.add(grid);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Update shader time
      shaderMaterial.uniforms.uTime.value = t;

      // Animate lights
      pointLight.position.x = Math.sin(t * 1.3) * 3.5;
      pointLight.position.z = Math.cos(t * 1.3) * 3.5;
      pointLight.position.y = 2.0 + Math.sin(t * 2.0) * 0.5;

