</head>
<body>
  <div class="hud">
    Drag to orbit • Scroll to zoom • Real-time lighting + shader effects
  </div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    let scene, camera, renderer, controls;
    let cube, sphere, floor;
    let dirLight, pointLight;
    let clock = new THREE.Clock();

    init();
    animate();

    function init() {
      // Scene
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x05070d);
      scene.fog = new THREE.Fog(0x05070d, 10, 35);

      // Camera
      camera = new THREE.PerspectiveCamera(
        60,
        window.innerWidth / window.innerHeight,
        0.1,
        100
      );
      camera.position.set(5, 3.5, 8);

      // Renderer
      renderer = new THREE.WebGLRenderer({
        antialias: true,
        powerPreference: "high-performance"
      });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.outputColorSpace = THREE.SRGBColorSpace;
      renderer.toneMapping = THREE.ACESFilmicToneMapping;
      renderer.toneMappingExposure = 1.2;
      document.body.appendChild(renderer.domElement);

      // Controls
      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.06;
      controls.target.set(0, 1, 0);

      // Lights
      const ambient = new THREE.AmbientLight(0x5d6bff, 0.35);
      scene.add(ambient);

      dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
      dirLight.position.set(4, 8, 5);
      scene.add(dirLight);

      pointLight = new THREE.PointLight(0x00d5ff, 60, 30, 2);
      pointLight.position.set(-4, 2, 0);
      scene.add(pointLight);

      // Floor
      const floorGeo = new THREE.PlaneGeometry(40, 40);
      const floorMat = new THREE.MeshStandardMaterial({
        color: 0x111622,
        roughness: 0.95,
        metalness: 0.0
      });
      floor = new THREE.Mesh(floorGeo, floorMat);
      floor.rotation.x = -Math.PI / 2;
      floor.position.y = -1;
      floor.receiveShadow = false;
      scene.add(floor);

      // Cube with standard material
      const cubeGeo = new THREE.BoxGeometry(1.4, 1.4, 1.4);
      const cubeMat = new THREE.MeshStandardMaterial({
        color: 0xff8844,
        roughness: 0.35,
        metalness: 0.75
      });
      cube = new THREE.Mesh(cubeGeo, cubeMat);
      cube.position.set(-2.2, 0, 0);
      scene.add(cube);

      // Sphere with custom shader effect
      const sphereGeo = new THREE.SphereGeometry(1, 64, 64);
      const sphereMat = new THREE.MeshStandardMaterial({
        color: 0x3355ff,
        roughness: 0.2,
        metalness: 0.9
      });

      // Add Fresnel-style emissive shader effect using onBeforeCompile
      sphereMat.onBeforeCompile = (shader) => {
        shader.uniforms.uTime = { value: 0 };

        shader.vertexShader = shader.vertexShader.replace(
          "#include <common>",
          `
          #include <common>
          varying vec3 vWorldNormal;
          varying vec3 vWorldPosition;
          `
        );

        shader.vertexShader = shader.vertexShader.replace(
          "#include <worldpos_vertex>",
          `
          #include <worldpos_vertex>
          vWorldPosition = worldPosition.xyz;
          vWorldNormal = normalize(mat3(modelMatrix) * normal);
          `
        );

        shader.fragmentShader = shader.fragmentShader.replace(
          "#include <common>",
          `
          #include <common>
          uniform float uTime;
          varying vec3 vWorldNormal;
          varying vec3 vWorldPosition;
          `
        );

        shader.fragmentShader = shader.fragmentShader.replace(
          "#include <emissivemap_fragment>",
          `
          #include <emissivemap_fragment>

          vec3 viewDir = normalize(cameraPosition - vWorldPosition);
          float fresnel = pow(1.0 - max(dot(viewDir, normalize(vWorldNormal)), 0.0), 3.0);

          float pulse = 0.5 + 0.5 * sin(uTime * 3.0);
          totalEmissiveRadiance += vec3(0.1, 0.7, 1.2) * fresnel * (0.7 + 0.3 * pulse) * 2.0;
          `
        );

        sphereMat.userData.shader = shader;
      };

      sphere = new THREE.Mesh(sphereGeo, sphereMat);
      sphere.position.set(2.2, 0.2, 0);
      scene.add(sphere);

      // Back wall / atmosphere accent
      const accentLight = new THREE.PointLight(0x7b5cff, 35, 25);
      accentLight.position.set(0, 4, -6);
      scene.add(accentLight);

      window.addEventListener("resize", onResize);
    }

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Animate lights
      dirLight.position.x = Math.cos(t * 0.7) * 6;
      dirLight.position.z = Math.sin(t * 0.7) * 6;
      dirLight.position.y = 6 + Math.sin(t * 1.3) * 1.5;

      pointLight.position.x = Math.sin(t * 1.2) * 4;
      pointLight.position.z = Math.cos(t * 1.2) * 4;
      pointLight.position.y = 1.5 + Math.sin(t * 2.0) * 0.7;

      // Animate objects
      cube.rotation.x += 0.008;
      cube.rotation.y += 0.013;

      sphere.rotation.y -= 0.01;
      sphere.rotation.x = Math.sin(t * 0.7) * 0.15;
      sphere.position.y = 0.2 + Math.sin(t * 2.0) * 0.08;

      // Update custom shader uniform
      if (sphere.material.userData.shader) {
        sphere.material.userData.shader.uniforms.uTime.value = t;
      }

      controls.update();
      renderer.render(scene, camera);
    }

    function onResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    }
  </script>
</body>
</html>
