<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      overflow: hidden;
      background: #05070a;
      font-family: system-ui, sans-serif;
    }
    #app {
      width: 100vw;
      height: 100vh;
    }
    .hint {
      position: fixed;
      left: 12px;
      bottom: 10px;
      color: rgba(255,255,255,0.75);
      font-size: 12px;
      user-select: none;
      pointer-events: none;
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <div class="hint">Drag to orbit • Scroll to zoom • Dynamic lighting + shader effects</div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";
    import { EffectComposer } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js";
    import { RenderPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js";
    import { UnrealBloomPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js";
    import { GUI } from "https://unpkg.com/three@0.160.0/examples/jsm/libs/lil-gui.module.min.js";

    const container = document.getElementById("app");

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    container.appendChild(renderer.domElement);

    // Scene / Camera
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070a);
    scene.fog = new THREE.Fog(0x05070a, 12, 40);

    const camera = new THREE.PerspectiveCamera(
      55,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2.5, 8);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.maxDistance = 20;
    controls.minDistance = 2.5;

    // Lights
    const ambient = new THREE.AmbientLight(0x88aaff, 0.18);
    scene.add(ambient);

    const directional = new THREE.DirectionalLight(0xffffff, 1.4);
    directional.position.set(5, 10, 6);
    scene.add(directional);

    const point1 = new THREE.PointLight(0x00d4ff, 12, 30, 2);
    scene.add(point1);

    const point2 = new THREE.PointLight(0xff4fd8, 10, 30, 2);
    scene.add(point2);

    // Floor
    const floorGeo = new THREE.CircleGeometry(18, 64);
    floorGeo.rotateX(-Math.PI / 2);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x0b1020,
      metalness: 0.2,
      roughness: 0.95,
      emissive: 0x02040a,
      emissiveIntensity: 0.5
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.receiveShadow = false;
    scene.add(floor);

    // Custom shader material
    const shaderUniforms = {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x00d4ff) },
      uColorB: { value: new THREE.Color(0xff4fd8) }
    };

    const customMat = new THREE.ShaderMaterial({
      uniforms: shaderUniforms,
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPos;
        void main() {
          vNormal = normalize(normalMatrix * normal);
          vec3 pos = position;
          float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.06;
          pos += normal * wave;
          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vPos = worldPos.xyz;
          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec3 vNormal;
        varying vec3 vPos;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 lightDir = normalize(vec3(0.4, 0.9, 0.2));
          float diff = max(dot(n, lightDir), 0.0);

          float stripes = 0.5 + 0.5 * sin(vPos.y * 8.0 - uTime * 3.0);
          float fres = pow(1.0 - max(dot(n, normalize(-vPos)), 0.0), 2.5);

          vec3 base = mix(uColorA, uColorB, stripes);
          vec3 col = base * (0.25 + diff * 1.1) + fres * 0.55;

          gl_FragColor = vec4(col, 1.0);
        }
      `,
      transparent: false
    });

    // Main object
    const objGeo = new THREE.TorusKnotGeometry(1, 0.35, 220, 24);
    const object = new THREE.Mesh(objGeo, customMat);
    object.position.y = 1.8;
    scene.add(object);

    // Backdrop spheres
    const glowMat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0xffffff,
      emissiveIntensity: 2.5,
      roughness: 0.2,
      metalness: 0.0
    });

    for (let i = 0; i < 12; i++) {
      const s = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 16), glowMat.clone());
      const a = (i / 12) * Math.PI * 2;
      s.position.set(Math.cos(a) * 5.5, 1.2 + Math.sin(i) * 1.3, Math.sin(a) * 5.5);
      s.material.color.setHSL(i / 12, 0.8, 0.6);
      scene.add(s);
    }

    // Postprocessing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloom = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      1.1,  // strength
      0.5,  // radius
      0.15  // threshold
    );
    composer.addPass(bloom);

    // GUI
    const gui = new GUI();
    const params = {
      bloomStrength: 1.1,
      bloomRadius: 0.5,
      bloomThreshold: 0.15,
      exposure: 1.2,
      point1Intensity: 12,
      point2Intensity: 10
    };

    gui.add(params, "bloomStrength", 0, 3, 0.01).onChange(v => bloom.strength = v);
    gui.add(params, "bloomRadius", 0, 2, 0.01).onChange(v => bloom.radius = v);
    gui.add(params, "bloomThreshold", 0, 1, 0.01).onChange(v => bloom.threshold = v);
    gui.add(params, "exposure", 0.2, 2.5, 0.01).onChange(v => renderer.toneMappingExposure = v);
    gui.add(params, "point1Intensity", 0, 30, 0.1).onChange(v => point1.intensity = v);
    gui.add(params, "point2Intensity", 0, 30, 0.1).onChange(v => point2.intensity = v);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      shaderUniforms.uTime.value = t;

      object.rotation.y = t * 0.5;
      object.rotation.x = Math.sin(t * 0.3) * 0.2;

      // Dynamic lights orbit around the object
      point1.position.set(Math.cos(t * 0.9) * 4.5, 2.5 + Math.sin(t * 1.2) * 1.2, Math.sin(t * 0.9) * 4.5);
      point2.position.set(Math.cos(t * -1.1 + 1.8) * 4.0, 2.0 + Math.cos(t * 1.0) * 1.4, Math.sin(t * -1.1 + 1.8) * 4.0);

      // Animate backdrop spheres
      scene.children.forEach((child, idx) => {
        if (child.isMesh && child.geometry && child.geometry.type === "SphereGeometry") {
          child.position.y += Math.sin(t * 2 + idx) * 0.002;
          child.rotation.y += 0.01;
        }
      });

      controls.update();
      composer.render();
    }

    animate();

    // Resize
    window.addEventListener("resize", () => {
      const w = window.innerWidth;
      const h = window.innerHeight;

      camera.aspect = w / h;
      camera.updateProjectionMatrix();

      renderer.setSize(w, h);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      composer.setSize(w, h);
    });
  </script>
</body>
</html>
