## `index.html`

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
      font-family: system-ui, sans-serif;
    }
    #info {
      position: absolute;
      top: 12px;
      left: 12px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 10px 12px;
      border-radius: 8px;
      z-index: 10;
      user-select: none;
      font-size: 14px;
      line-height: 1.4;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <div id="info">
    <b>3D Scene Viewer</b><br>
    Mouse: orbit / zoom / pan<br>
    Dynamic lighting + shader effects
  </div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';
    import { EffectComposer } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js';
    import { RenderPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js';
    import { UnrealBloomPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js';

    let scene, camera, renderer, controls, composer;
    let cube, sphere, torus;
    let portalMaterial;
    const clock = new THREE.Clock();

    init();
    animate();

    function init() {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x05070f);
      scene.fog = new THREE.Fog(0x05070f, 10, 40);

      camera = new THREE.PerspectiveCamera(
        60,
        window.innerWidth / window.innerHeight,
        0.1,
        1000
      );
      camera.position.set(0, 3, 10);

      renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.outputColorSpace = THREE.SRGBColorSpace;
      renderer.toneMapping = THREE.ACESFilmicToneMapping;
      renderer.toneMappingExposure = 1.15;
      document.body.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.05;

      // Lights
      const ambient = new THREE.AmbientLight(0x8899ff, 0.35);
      scene.add(ambient);

      const directional = new THREE.DirectionalLight(0xffffff, 1.4);
      directional.position.set(5, 10, 4);
      scene.add(directional);

      const point1 = new THREE.PointLight(0xff4d8d, 40, 30);
      point1.position.set(4, 2, 0);
      scene.add(point1);

      const point2 = new THREE.PointLight(0x4de3ff, 30, 30);
      point2.position.set(-4, -1, 0);
      scene.add(point2);

      // Ground
      const groundGeo = new THREE.PlaneGeometry(80, 80, 1, 1);
      const groundMat = new THREE.MeshStandardMaterial({
        color: 0x0b1020,
        roughness: 0.95,
        metalness: 0.1
      });
      const ground = new THREE.Mesh(groundGeo, groundMat);
      ground.rotation.x = -Math.PI / 2;
      ground.position.y = -1.5;
      ground.receiveShadow = true;
      scene.add(ground);

      // Shader material for "portal" sphere
      portalMaterial = new THREE.ShaderMaterial({
        uniforms: {
          uTime: { value: 0 },
          uColorA: { value: new THREE.Color(0x4de3ff) },
          uColorB: { value: new THREE.Color(0xff4d8d) }
        },
        vertexShader: `
          varying vec3 vNormal;
          varying vec3 vPos;
          void main() {
            vNormal = normalMatrix * normal;
            vPos = position;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          }
        `,
        fragmentShader: `
          uniform float uTime;
          uniform vec3 uColorA;
          uniform vec3 uColorB;
          varying vec3 vNormal;
          varying vec3 vPos;

          void main() {
            float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);
            float wave = sin(vPos.y * 8.0 + uTime * 3.0) * 0.5 + 0.5;
            vec3 col = mix(uColorA, uColorB, wave);
            col += fresnel * 0.8;
            gl_FragColor = vec4(col, 1.0);
          }
        `
      });

      // Objects
      const cubeMat = new THREE.MeshStandardMaterial({
        color: 0xffffff,
        metalness: 0.45,
        roughness: 0.2,
        emissive: 0x111111
      });

      cube = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.4, 1.4), cubeMat);
      cube.position.set(-2.5, 0, 0);
      scene.add(cube);

      sphere = new THREE.Mesh(
        new THREE.SphereGeometry(1, 64, 64),
        portalMaterial
      );
      sphere.position.set(0, 0.2, 0);
      scene.add(sphere);

      torus = new THREE.Mesh(
        new THREE.TorusKnotGeometry(0.9, 0.28, 180, 24),
        new THREE.MeshStandardMaterial({
          color: 0x88ddff,
          metalness: 0.9,
          roughness: 0.15
        })
      );
      torus.position.set(2.7, 0.2, 0);
      scene.add(torus);

      // Post-processing
      composer = new EffectComposer(renderer);
      composer.addPass(new RenderPass(scene, camera));

      const bloom = new UnrealBloomPass(
        new THREE.Vector2(window.innerWidth, window.innerHeight),
        0.9,  // strength
        0.5,  // radius
        0.2   // threshold
      );
      composer.addPass(bloom);

      window.addEventListener('resize', onWindowResize);
    }

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      controls.update();

      // Animate objects
      cube.rotation.x = t * 0.6;
      cube.rotation.y = t * 0.8;

      sphere.rotation.y = -t * 0.9;
      sphere.rotation.x = t * 0.25;
      portalMaterial.uniforms.uTime.value = t;

      torus.rotation.x = t * 0.5;
      torus.rotation.z = t * 0.7;

      // Dynamic lighting motion
      const point1 = scene.children.find(o => o.isPointLight && o.color.getHex() === 0xff4d8d);
      const point2 = scene.children.find(o => o.isPointLight && o.color.getHex() === 0x4de3ff);

      if (point1) {
        point1.position.x = Math.cos(t * 1.2) * 5;
        point1.position.z = Math.sin(t * 1.2) * 5;
      }
      if (point2) {
        point2.position.x = Math.cos(t * 0.8 + Math.PI) * 5;
        point2.position.z = Math.sin(t * 0.8 + Math.PI) * 5;
      }

      composer.render();
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      composer.setSize(window.innerWidth, window.innerHeight);
    }
  </script>
</body>
</html>
