    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 1, 0);

    // Lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambient);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.25);
    dirLight.position.set(5, 8, 4);
    scene.add(dirLight);

    const pointLight = new THREE.PointLight(0x00aaff, 2.0, 30, 2);
    pointLight.position.set(0, 2, 0);
    scene.add(pointLight);

    const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.2);
    scene.add(pointLightHelper);

    // Ground
    const groundGeo = new THREE.PlaneGeometry(30, 30, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x111111,
      roughness: 1.0,
      metalness: 0.0
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1;
    ground.receiveShadow = true;
    scene.add(ground);

    // Custom shader material
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0x7c3aed) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vUv = uv;
          vNormal = normalMatrix * normal;
          vec3 displaced = position;

          // Animated displacement
          float wave = sin(position.x * 4.0 + uTime * 2.0) * 0.08;
          wave += cos(position.y * 6.0 + uTime * 1.5) * 0.05;
          displaced += normal * wave;

          vec4 worldPosition = modelMatrix * vec4(displaced, 1.0);
          vPosition = worldPosition.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPosition;
        }
