        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));

          float diffuse = max(dot(n, lightDir), 0.0);
          float fresnel = pow(1.0 - max(dot(n, normalize(-vPosition)), 0.0), 3.0);

          float stripes = 0.5 + 0.5 * sin((vUv.x * 18.0 + uTime * 2.5) + vUv.y * 8.0);
          vec3 baseColor = mix(uColorA, uColorB, stripes);

          vec3 color = baseColor * (0.25 + 0.75 * diffuse);
          color += fresnel * vec3(1.0, 1.0, 1.0) * 0.35;

          // Slight animated glow variation
          float pulse = 0.08 * sin(uTime * 3.0 + length(vPosition.xyz));
          color += pulse;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Shader mesh
    const sphereGeo = new THREE.IcosahedronGeometry(1.2, 4);
    const shaderSphere = new THREE.Mesh(sphereGeo, shaderMaterial);
    shaderSphere.position.set(0, 1.2, 0);
    scene.add(shaderSphere);

    // Additional lit objects
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({
        color: 0xff5533,
        roughness: 0.35,
        metalness: 0.2
      })
    );
    box.position.set(-2.3, 0, 0);
    scene.add(box);

    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(0.75, 0.22, 128, 16),
      new THREE.MeshStandardMaterial({
        color: 0x33ff99,
        roughness: 0.25,
        metalness: 0.6
      })
    );
    torus.position.set(2.3, 0.2, 0);
    scene.add(torus);

    // Grid for depth
    const grid = new THREE.GridHelper(30, 30, 0x335577, 0x112233);
    grid.position.y = -1;
    scene.add(grid);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = t;

      // Animate lights
      pointLight.position.x = Math.cos(t * 1.2) * 3.5;
      pointLight.position.z = Math.sin(t * 1.2) * 3.5;
      pointLight.position.y = 1.5 + Math.sin(t * 2.0) * 0.8;

      dirLight.position.x = Math.cos(t * 0.5) * 6.0;
      dirLight.position.z = Math.sin(t * 0.5) * 6.0;

      // Object motion
      shaderSphere.rotation.y += 0.01;
      shaderSphere.rotation.x = Math.sin(t * 0.6) * 0.2;

      box.rotation.x += 0.01;
      box.rotation.y += 0.013;

      torus.rotation.x += 0.008;
      torus.rotation.y += 0.01;

      controls.update();
      renderer.render(scene, camera);
    }

