    app.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // --- Composer for post-processing ---
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    // --- Ground ---
    const groundGeo = new THREE.PlaneGeometry(30, 30, 64, 64);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x1a2230,
      metalness: 0.1,
      roughness: 0.95,
      wireframe: false
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // --- Main objects ---
    const torusGeo = new THREE.TorusKnotGeometry(1, 0.35, 200, 32);
    const metalMat = new THREE.MeshStandardMaterial({
      color: 0x88aaff,
      metalness: 0.9,
      roughness: 0.15
    });
    const torus = new THREE.Mesh(torusGeo, metalMat);
    torus.position.y = 2;
    scene.add(torus);

    const sphereGeo = new THREE.SphereGeometry(0.7, 64, 64);
    const sphereMat = new THREE.MeshStandardMaterial({
      color: 0xff8844,
      metalness: 0.3,
      roughness: 0.25
    });
    const sphere = new THREE.Mesh(sphereGeo, sphereMat);
    sphere.position.set(-2.5, 1.2, 0);
    scene.add(sphere);

    // --- Lights ---
    const ambient = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambient);

    const pointLight = new THREE.PointLight(0x66aaff, 2.5, 30, 2);
    pointLight.position.set(4, 4, 4);
    scene.add(pointLight);

    const pointLight2 = new THREE.PointLight(0xff6688, 2.0, 30, 2);
    pointLight2.position.set(-4, 3, -3);
    scene.add(pointLight2);

    const directional = new THREE.DirectionalLight(0xffffff, 1.2);
    directional.position.set(5, 10, 2);
    scene.add(directional);

    // --- Shader effect: fullscreen animated overlay ---
    const shaderScene = new THREE.Scene();
    const shaderCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uResolution: { value: new THREE.Vector2(window.innerWidth, window.innerHeight) }
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = vec4(position.xy, 0.0, 1.0);
        }
      `,
      fragmentShader: `
        precision highp float;
        uniform float uTime;
        uniform vec2 uResolution;
        varying vec2 vUv;

        // Simple noise-ish function
        float hash(vec2 p) {
          p = fract(p * vec2(123.34, 456.21));
          p += dot(p, p + 45.32);
          return fract(p.x * p.y);
        }

        void main() {
          vec2 uv = vUv;
          vec2 p = (uv - 0.5) * vec2(uResolution.x / uResolution.y, 1.0);

          float t = uTime * 0.7;
          float vignette = smoothstep(0.9, 0.2, length(uv - 0.5));

          float scan = sin((uv.y + t * 0.2) * 700.0) * 0.02;
          float grain = hash(uv * uResolution + t) * 0.03;

          vec3 glow = vec3(
            0.15 + 0.15 * sin(t + p.x * 2.0),
            0.25 + 0.10 * sin(t * 1.3 + p.y * 3.0),
            0.4 + 0.15 * sin(t * 0.8)
          );

          vec3 col = glow + scan + grain;
          col *= vignette;

          gl_FragColor = vec4(col, 0.18);
        }
      `,
      transparent: true,
      depthWrite: false,
      depthTest: false
    });

    const fullscreenQuad = new THREE.Mesh(
      new THREE.PlaneGeometry(2, 2),
      shaderMaterial
    );
    shaderScene.add(fullscreenQuad);

    // --- Animation loop ---
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Object animation
      torus.rotation.x = t * 0.6;
      torus.rotation.y = t * 0.9;

      sphere.position.y = 1.2 + Math.sin(t * 2.0) * 0.3;
      sphere.rotation.y = t * 1.2;

      // Moving lights
      pointLight.position.x = Math.sin(t * 1.1) * 5.0;
      pointLight.position.z = Math.cos(t * 1.1) * 5.0;
      pointLight.position.y = 3.0 + Math.sin(t * 1.7) * 1.5;

      pointLight2.position.x = Math.cos(t * 0.9) * 5.5;
      pointLight2.position.z = Math.sin(t * 0.9) * 5.5;
      pointLight2.position.y = 2.5 + Math.cos(t * 1.4) * 1.2;

      shaderMaterial.uniforms.uTime.value = t;

      controls.update();
      composer.render();

      // Render shader overlay after scene
      renderer.autoClear = false;
      renderer.clearDepth();
      renderer.render(shaderScene, shaderCamera);
      renderer.autoClear = true;
    }

    animate();

    // --- Resize handling ---
    window.addEventListener("resize", () => {
      const w = window.innerWidth;
      const h = window.innerHeight;

      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
      composer.setSize(w, h);

      shaderMaterial.uniforms.uResolution.value.set(w, h);
    });
  </script>
