    const boxGeo = new THREE.BoxGeometry(0.9, 0.9, 0.9);

    const mat1 = new THREE.MeshStandardMaterial({
      color: 0x44aaff,
      metalness: 0.9,
      roughness: 0.15
    });

    const mat2 = new THREE.MeshStandardMaterial({
      color: 0xff8844,
      metalness: 0.7,
      roughness: 0.25
    });

    const mat3 = new THREE.MeshStandardMaterial({
      color: 0x88ffbb,
      metalness: 0.4,
      roughness: 0.4
    });

    const sphere = new THREE.Mesh(sphereGeo, mat1);
    sphere.position.set(-2, 1.2, 0);

    const torus = new THREE.Mesh(torusGeo, mat2);
    torus.position.set(0, 1.2, 0);

    const box = new THREE.Mesh(boxGeo, mat3);
    box.position.set(2, 1.2, 0);

    group.add(sphere, torus, box);

    // Decorative particles
    const particleCount = 400;
    const particlePos = new Float32Array(particleCount * 3);
    for (let i = 0; i < particleCount; i++) {
      const r = 12 * Math.random();
      const theta = Math.random() * Math.PI * 2;
      const y = (Math.random() - 0.5) * 8;
      particlePos[i * 3 + 0] = Math.cos(theta) * r;
      particlePos[i * 3 + 1] = y;
      particlePos[i * 3 + 2] = Math.sin(theta) * r;
    }

    const particleGeom = new THREE.BufferGeometry();
    particleGeom.setAttribute("position", new THREE.BufferAttribute(particlePos, 3));
    const particleMat = new THREE.PointsMaterial({
      color: 0xaaccff,
      size: 0.05,
      transparent: true,
      opacity: 0.75
    });
    const particles = new THREE.Points(particleGeom, particleMat);
    scene.add(particles);

    // -------------------------
    // Shader effect (full-screen pass)
    // A subtle film/wave effect using time + screen UVs
    // -------------------------
    const ShaderFX = {
      uniforms: {
        tDiffuse: { value: null },
        time: { value: 0 },
        intensity: { value: 0.35 }
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float time;
        uniform float intensity;
        varying vec2 vUv;

        void main() {
          vec2 uv = vUv;
          vec4 color = texture2D(tDiffuse, uv);

          // subtle wave distortion
          float wave = sin((uv.y * 10.0) + time * 1.8) * 0.003;
          float wave2 = cos((uv.x * 8.0) - time * 1.3) * 0.003;

          vec2 distortedUv = uv + vec2(wave, wave2);
          vec4 distorted = texture2D(tDiffuse, distortedUv);

          // screen-space vignette
          vec2 p = uv - 0.5;
          float vignette = 1.0 - smoothstep(0.28, 0.75, dot(p, p));

          // mild color shift/contrast
          vec3 col = distorted.rgb;
          col.r *= 1.02;
          col.b *= 1.05;
          col = mix(color.rgb, col, intensity);

          col *= vignette;
          col += 0.02 * sin(time + uv.yx * 40.0).rgb;

          gl_FragColor = vec4(col, 1.0);
        }
      `
    };

    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));
    const shaderPass = new ShaderPass(ShaderFX);
    composer.addPass(shaderPass);

    // -------------------------
    // Animation loop
    // -------------------------
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      controls.update();

      // rotating objects
      sphere.rotation.y = t * 0.8;
      sphere.rotation.x = t * 0.25;

      torus.rotation.x = t * 0.7;
      torus.rotation.y = t * 1.0;

      box.rotation.x = t * 0.4;
      box.rotation.y = t * 0.6;

      // dynamic lighting motion
      pointLight.position.x = Math.sin(t * 1.4) * 4.0;
      pointLight.position.z = Math.cos(t * 1.4) * 4.0;
      pointLight.position.y = 2.0 + Math.sin(t * 2.0) * 0.7;

      pointLight2.position.x = Math.cos(t * 1.1) * 3.5;
      pointLight2.position.z = Math.sin(t * 1.1) * 3.5;
      pointLight2.position.y = 1.5 + Math.cos(t * 1.7) * 0.5;

      particles.rotation.y = t * 0.05;

      shaderPass.uniforms.time.value = t;

      composer.render();
    }

    animate();

    // -------------------------
    // Resize
    // -------------------------
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();

      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      composer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
