    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.physicallyCorrectLights = true;
    document.body.appendChild(renderer.domElement);

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);
    scene.fog = new THREE.Fog(0x050816, 12, 40);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2.5, 8);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;
    controls.minDistance = 3;
    controls.maxDistance = 20;
    controls.target.set(0, 1, 0);

    // Lights
    const ambientLight = new THREE.AmbientLight(0x404860, 1.2);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 2.5);
    directionalLight.position.set(5, 10, 4);
    scene.add(directionalLight);

    const pointLight = new THREE.PointLight(0x4cc9f0, 50, 30, 2);
    pointLight.position.set(0, 3, 0);
    scene.add(pointLight);

    // Ground
    const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x111827,
      metalness: 0.2,
      roughness: 0.9
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1;
    scene.add(ground);

    // Custom shader material for a glowing effect
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x8b5cf6) },
        uColorB: { value: new THREE.Color(0x06b6d4) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vPosition;
        varying vec3 vNormal;

        void main() {
          vPosition = position;
          vNormal = normal;

          vec3 p = position;
          p.z += sin(p.x * 3.0 + uTime) * 0.15;
          p.x += cos(p.y * 4.0 + uTime * 1.5) * 0.1;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec3 vPosition;
        varying vec3 vNormal;

        void main() {
          float wave = 0.5 + 0.5 * sin(uTime + vPosition.y * 4.0);
          vec3 color = mix(uColorA, uColorB, wave);

          // Simple Fresnel-like glow
          vec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));
          float fresnel = pow(1.0 - abs(dot(normalize(vNormal), viewDir)), 2.5);

          gl_FragColor = vec4(color + fresnel * 0.35, 1.0);
        }
      `,
      transparent: false
    });

    // Objects
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 200, 32),
      shaderMaterial
    );
    torus.position.set(-1.8, 1.2, 0);
    scene.add(torus);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.9, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0xe2e8f0,
        metalness: 0.8,
        roughness: 0.2
      })
    );
    sphere.position.set(2, 0.3, 0.8);
    scene.add(sphere);

    const cylinder = new THREE.Mesh(
      new THREE.CylinderGeometry(0.6, 0.6, 2, 32),
      new THREE.MeshStandardMaterial({
        color: 0x22c55e,
        metalness: 0.3,
        roughness: 0.5
      })
    );
    cylinder.position.set(0, 0, -2);
    scene.add(cylinder);

    // Floating particles / stars
    const starCount = 500;
    const starGeo = new THREE.BufferGeometry();
    const starPos = new Float32Array(starCount * 3);

    for (let i = 0; i < starCount; i++) {
      starPos[i * 3 + 0] = (Math.random() - 0.5) * 60;
      starPos[i * 3 + 1] = Math.random() * 30;
      starPos[i * 3 + 2] = (Math.random() - 0.5) * 60;
    }

    starGeo.setAttribute("position", new THREE.BufferAttribute(starPos, 3));
    const starMat = new THREE.PointsMaterial({
      color: 0xffffff,
      size: 0.06,
      transparent: true,
      opacity: 0.9,
      depthWrite: false
    });
    const stars = new THREE.Points(starGeo, starMat);
    scene.add(stars);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
