      const t = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = t;

      torus.rotation.x = t * 0.35;
      torus.rotation.y = t * 0.55;

      sphere.rotation.y = t * 0.7;
      sphere.rotation.x = Math.sin(t * 0.5) * 0.3;

      cylinder.rotation.z = t * 0.4;
      cylinder.position.y = Math.sin(t * 1.2) * 0.25;

      pointLight.position.x = Math.sin(t * 1.5) * 4;
      pointLight.position.z = Math.cos(t * 1.5) * 4;
      pointLight.position.y = 2.5 + Math.sin(t * 2.2) * 1.0;

      directionalLight.position.x = Math.cos(t * 0.3) * 6;
      directionalLight.position.z = Math.sin(t * 0.3) * 6;

      stars.rotation.y = t * 0.03;

      controls.update();
      renderer.render(scene, camera);
