    camera.position.set(0, 3, 9);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.target.set(0, 1, 0);

    // Lights
    const ambient = new THREE.AmbientLight(0x7f8cff, 0.25);
    scene.add(ambient);

    const hemi = new THREE.HemisphereLight(0x9fd7ff, 0x1a1a2d, 0.7);
    scene.add(hemi);

    const dirLight = new THREE.DirectionalLight(0xffffff, 2.5);
    dirLight.position.set(5, 8, 3);
    scene.add(dirLight);

    const pointLight = new THREE.PointLight(0x66ccff, 40, 30, 2);
    pointLight.position.set(-4, 2, 0);
    scene.add(pointLight);

    // Ground
    const groundGeo = new THREE.PlaneGeometry(60, 60);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x10131f,
      metalness: 0.1,
      roughness: 0.95
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.2;
    scene.add(ground);

    // Objects
    const objects = [];

    const torusGeo = new THREE.TorusKnotGeometry(1, 0.35, 220, 32);
    const torusMat = new THREE.MeshPhysicalMaterial({
      color: 0x9b7bff,
      metalness: 0.75,
      roughness: 0.22,
      clearcoat: 1.0,
      clearcoatRoughness: 0.08
    });
    const torus = new THREE.Mesh(torusGeo, torusMat);
    torus.position.set(0, 1.2, 0);
    scene.add(torus);
    objects.push(torus);

    const sphereGeo = new THREE.SphereGeometry(0.55, 48, 48);
    const sphereMat = new THREE.MeshStandardMaterial({
      color: 0x4dd6ff,
      metalness: 0.2,
      roughness: 0.15,
      emissive: 0x112233,
      emissiveIntensity: 0.7
    });

    for (let i = 0; i < 5; i++) {
      const s = new THREE.Mesh(sphereGeo, sphereMat.clone());
      s.position.set(
        Math.cos((i / 5) * Math.PI * 2) * 4,
        0.6 + (i % 2) * 0.5,
        Math.sin((i / 5) * Math.PI * 2) * 4
      );
      scene.add(s);
      objects.push(s);
    }

    // Custom shader-driven box
    const customBox = new THREE.Mesh(
      new THREE.BoxGeometry(1.6, 1.6, 1.6, 32, 32, 32),
      new THREE.ShaderMaterial({
        uniforms: {
          uTime: { value: 0 },
          uColorA: { value: new THREE.Color(0xff5ea8) },
          uColorB: { value: new THREE.Color(0x5ef0ff) }
        },
        vertexShader: `
          uniform float uTime;
          varying vec2 vUv;
          varying vec3 vNormalW;

          void main() {
            vUv = uv;
            vNormalW = normalize(normalMatrix * normal);
            vec3 pos = position;

            // Animated displacement for a shader effect
            float wave = sin((pos.x + uTime) * 2.0) * 0.08
                       + sin((pos.y + uTime * 1.3) * 3.0) * 0.06
                       + sin((pos.z + uTime * 0.9) * 4.0) * 0.05;
            pos += normal * wave;

            gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
          }
        `,
        fragmentShader: `
          uniform float uTime;
          uniform vec3 uColorA;
          uniform vec3 uColorB;
          varying vec2 vUv;
          varying vec3 vNormalW;

          void main() {
            float fresnel = pow(1.0 - abs(vNormalW.z), 2.5);
            float stripes = 0.5 + 0.5 * sin(vUv.y * 20.0 + uTime * 2.0);
            vec3 col = mix(uColorA, uColorB, stripes);
            col += fresnel * 0.65;
            gl_FragColor = vec4(col, 1.0);
          }
        `
      })
    );
    customBox.position.set(-3, 1.0, -1);
    scene.add(customBox);
    objects.push(customBox);

    // Post-processing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const FXAAShader = {
      uniforms: {
        tDiffuse: { value: null },
        resolution: { value: new THREE.Vector2(1 / window.innerWidth, 1 / window.innerHeight) },
        uTime: { value: 0 }
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform vec2 resolution;
        uniform float uTime;
        varying vec2 vUv;

        // Minimal glow + vignette + chromatic distort
        void main() {
          vec2 uv = vUv;
          vec2 offset = vec2(
            sin(uTime * 0.7) * 0.0015,
            cos(uTime * 0.9) * 0.0015
          );

          vec4 cr = texture2D(tDiffuse, uv + offset);
          vec4 cg = texture2D(tDiffuse, uv);
          vec4 cb = texture2D(tDiffuse, uv - offset);

          vec3 color = vec3(cr.r, cg.g, cb.b);

          // Vignette
          vec2 p = uv - 0.5;
          float vig = smoothstep(0.85, 0.2, dot(p, p) * 1.5);
          color *= vig;

          // Subtle scanline shimmer
          float scan = 0.98 + 0.02 * sin((uv.y + uTime * 0.2) * 900.0);
          color *= scan;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    };

    const shaderPass = new ShaderPass(FXAAShader);
    composer.addPass(shaderPass);

    // Animate
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      controls.update();

      // Dynamic lighting
      dirLight.position.x = Math.cos(t * 0.6) * 6;
      dirLight.position.z = Math.sin(t * 0.6) * 6;
      pointLight.position.x = Math.sin(t * 1.4) * 5;
      pointLight.position.z = Math.cos(t * 1.2) * 5;
      pointLight.intensity = 30 + Math.sin(t * 2.0) * 10;

      // Object motion
      torus.rotation.x = t * 0.35;
      torus.rotation.y = t * 0.55;

      objects.slice(1).forEach((obj, i) => {
        obj.position.y = 0.6 + Math.sin(t * 1.5 + i) * 0.25;
        obj.rotation.y = t * 0.8 + i;
      });

      customBox.rotation.x = t * 0.5;
      customBox.rotation.y = t * 0.7;
      customBox.material.uniforms.uTime.value = t;
      shaderPass.uniforms.uTime.value = t;

      composer.render();
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      composer.setSize(window.innerWidth, window.innerHeight);
      shaderPass.uniforms.resolution.value.set(
        1 / window.innerWidth,
        1 / window.innerHeight
      );
    });
  </script>
</body>
</html>
```

