import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/controls/OrbitControls.js";

// Renderer
const canvas = document.getElementById("webgl");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070f);
scene.fog = new THREE.Fog(0x05070f, 8, 30);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.2);
dirLight.position.set(4, 6, 2);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0x66aaff, 35, 30, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(30, 30),
  new THREE.MeshStandardMaterial({
    color: 0x111827,
    roughness: 1,
    metalness: 0,
  })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = false;
scene.add(ground);

// Custom shader material
const customMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4f46e5) },
    uColorB: { value: new THREE.Color(0x22d3ee) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vWorldPosition;

    void main() {
      vec3 pos = position;

      // Mild animated displacement for a shader effect
      float wave = sin(pos.x * 3.0 + uTime * 2.5) * 0.06
                 + cos(pos.z * 3.5 + uTime * 1.8) * 0.06;
      pos += normal * wave;

      vec4 worldPosition = modelMatrix * vec4(pos, 1.0);
      vWorldPosition = worldPosition.xyz;
      vNormal = normalize(mat3(modelMatrix) * normal);

      gl_Position = projectionMatrix * viewMatrix * worldPosition;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vWorldPosition;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(vec3(0.5, 1.0, 0.3));
      float diffuse = max(dot(N, L), 0.0);

      // Fresnel-style rim highlight
      vec3 V = normalize(cameraPosition - vWorldPosition);
      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 2.5);

      // Animated gradient blend
      float t = 0.5 + 0.5 * sin(uTime + vWorldPosition.y * 2.0);
      vec3 baseColor = mix(uColorA, uColorB, t);

      vec3 color = baseColor * (0.25 + diffuse * 0.85) + fresnel * vec3(1.0);

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const object = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.2, 5),
  customMaterial
);
object.position.set(0, 1.4, 0);
scene.add(object);

// Additional objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.7, 0.22, 200, 32),
  new THREE.MeshStandardMaterial({
    color: 0xff9f1c,
    metalness: 0.8,
    roughness: 0.25,
  })
);
torus.position.set(-2.3, 1.2, 0);
scene.add(torus);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.65, 64, 64),
  new THREE.MeshStandardMaterial({
    color: 0x8b5cf6,
    roughness: 0.15,
    metalness: 0.9,
  })
);
sphere.position.set(2.3, 1.1, 0);
scene.add(sphere);

// Simple animated "light orb"
const lightOrb = new THREE.Mesh(
  new THREE.SphereGeometry(0.12, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0xffffff })
);
scene.add(lightOrb);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();

  customMaterial.uniforms.uTime.value = elapsed;

  object.rotation.y = elapsed * 0.45;
  object.rotation.x = Math.sin(elapsed * 0.5) * 0.2;

  torus.rotation.x = elapsed * 0.35;
  torus.rotation.y = elapsed * 0.55;

  sphere.position.y = 1.1 + Math.sin(elapsed * 1.8) * 0.15;

  // Move point light in a circular path
  pointLight.position.x = Math.cos(elapsed * 1.1) * 3.2;
  pointLight.position.z = Math.sin(elapsed * 1.1) * 3.2;
  pointLight.position.y = 2.0 + Math.sin(elapsed * 2.0) * 0.5;

  lightOrb.position.copy(pointLight.position);

  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
