ground.position.y = 0;
scene.add(ground);

// Custom shader material for the main object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x66ccff) },
