```js
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

const canvas = document.getElementById("scene-canvas");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.physicallyCorrectLights = true;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050816);
scene.fog = new THREE.Fog(0x050816, 10, 30);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 2.5);
directionalLight.position.set(5, 10, 5);
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0x00aaff, 40, 20, 2);
pointLight.position.set(-2, 2, 2);
scene.add(pointLight);

const pointLight2 = new THREE.PointLight(0xff5500, 25, 20, 2);
pointLight2.position.set(2, 1.5, -2);
scene.add(pointLight2);

// Ground plane
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  metalness: 0.2,
  roughness: 0.9,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
ground.receiveShadow = false;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0x7c3aed) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalize(normalMatrix * normal);
      vPosition = position;

      vec3 pos = position;
      pos += normal * sin(uTime + position.y * 4.0) * 0.05;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 viewDir = normalize(-vPosition);
      float fresnel = pow(1.0 - max(dot(normalize(vNormal), viewDir), 0.0), 2.2);

      float pulse = 0.5 + 0.5 * sin(uTime * 2.0);
      vec3 baseColor = mix(uColorA, uColorB, pulse);

      vec3 color = baseColor + fresnel * 0.8;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMaterial
);
sphere.position.set(-1.8, 1.2, 0);
scene.add(sphere);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.28, 160, 24),
  new THREE.MeshStandardMaterial({
    color: 0x9ca3af,
    metalness: 0.9,
    roughness: 0.15,
  })
);
torus.position.set(2, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.2, 1.2, 1.2),
  new THREE.MeshStandardMaterial({
    color: 0x22c55e,
    metalness: 0.4,
    roughness: 0.4,
  })
);
box.position.set(0, 0.6, -2.2);
scene.add(box);

// Grid helper
const grid = new THREE.GridHelper(30, 30, 0x334155, 0x1f2937);
grid.position.y = 0;
scene.add(grid);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = elapsed;

  sphere.rotation.y = elapsed * 0.6;
  sphere.rotation.x = elapsed * 0.2;

  torus.rotation.x = elapsed * 0.5;
  torus.rotation.y = elapsed * 0.3;

  box.rotation.x = elapsed * 0.4;
  box.rotation.y = elapsed * 0.7;

  pointLight.position.x = Math.sin(elapsed * 1.5) * 3;
  pointLight.position.z = Math.cos(elapsed * 1.5) * 3;

  pointLight2.position.x = Math.cos(elapsed * 1.1) * -3;
  pointLight2.position.z = Math.sin(elapsed * 1.1) * 3;

  controls.update();
  renderer.render(scene, camera);

  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
