import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

let scene, camera, renderer, controls;
let clock;

let directionalLight, pointLight;
let shaderSphere;

init();
animate();

function init() {
  const container = document.getElementById("app");

  // Scene
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x05070c);
  scene.fog = new THREE.Fog(0x05070c, 8, 30);

  // Camera
  camera = new THREE.PerspectiveCamera(
    60,
    window.innerWidth / window.innerHeight,
    0.1,
    100
  );
  camera.position.set(0, 3, 8);

  // Renderer
  renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.2;
  container.appendChild(renderer.domElement);

  // Controls
  controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.target.set(0, 1, 0);

  clock = new THREE.Clock();

  // Lights
  const ambient = new THREE.AmbientLight(0x404050, 0.4);
  scene.add(ambient);

  directionalLight = new THREE.DirectionalLight(0xffffff, 2.0);
  directionalLight.position.set(3, 5, 2);
  scene.add(directionalLight);

  pointLight = new THREE.PointLight(0x4aa3ff, 25, 20, 2);
  pointLight.position.set(0, 2, 0);
  scene.add(pointLight);

  // Floor
  const floorGeo = new THREE.PlaneGeometry(30, 30, 1, 1);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x111622,
    roughness: 0.95,
    metalness: 0.0,
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = false;
  scene.add(floor);

  // Background grid helper
  const grid = new THREE.GridHelper(30, 30, 0x223044, 0x162030);
  grid.position.y = 0.001;
  scene.add(grid);

  // Shader-based sphere
  shaderSphere = createShaderSphere();
  shaderSphere.position.set(0, 1.5, 0);
  scene.add(shaderSphere);

  // Additional geometry
  const torus = new THREE.Mesh(
    new THREE.TorusKnotGeometry(1, 0.35, 128, 16),
    new THREE.MeshStandardMaterial({
      color: 0x88aaff,
      roughness: 0.25,
      metalness: 0.8,
    })
  );
  torus.position.set(-2.8, 1.4, 0);
  scene.add(torus);

  const box = new THREE.Mesh(
    new THREE.BoxGeometry(1.2, 1.2, 1.2),
    new THREE.MeshStandardMaterial({
      color: 0xffaa66,
      roughness: 0.4,
      metalness: 0.3,
    })
  );
  box.position.set(2.8, 0.6, 0);
  scene.add(box);

  // Store animated objects
  scene.userData.animated = { torus, box };

  window.addEventListener("resize", onWindowResize);
}

function createShaderSphere() {
  const geometry = new THREE.SphereGeometry(1, 64, 64);

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x4aa3ff) },
      uColorB: { value: new THREE.Color(0xff4ad8) },
      uLightDir: { value: new THREE.Vector3(1, 1, 1).normalize() },
    },
    vertexShader: `
      varying vec3 vNormal;
      varying vec3 vPosition;
      varying vec2 vUv;

      void main() {
        vUv = uv;
        vNormal = normalize(normalMatrix * normal);
        vec4 worldPos = modelMatrix * vec4(position, 1.0);
        vPosition = worldPos.xyz;
        gl_Position = projectionMatrix * viewMatrix * worldPos;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uColorA;
      uniform vec3 uColorB;
      uniform vec3 uLightDir;

      varying vec3 vNormal;
      varying vec3 vPosition;
      varying vec2 vUv;

      void main() {
        vec3 N = normalize(vNormal);
        vec3 L = normalize(uLightDir);

        float diff = max(dot(N, L), 0.0);

        // Animated wave pattern
        float wave = sin(vUv.x * 12.0 + uTime * 2.0) * 0.5 + 0.5;
        float pulse = sin(uTime * 3.0 + length(vPosition) * 2.0) * 0.5 + 0.5;

        vec3 baseColor = mix(uColorA, uColorB, wave);
        vec3 color = baseColor * (0.25 + diff * 1.2);

        // Simple glow-like effect near edges
        float fresnel = pow(1.0 - max(dot(N, vec3(0.0, 0.0, 1.0)), 0.0), 3.0);
        color += fresnel * 0.6 * pulse;

        gl_FragColor = vec4(color, 1.0);
      }
    `,
  });

  return new THREE.Mesh(geometry, material);
}

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Animate directional light
  directionalLight.position.x = Math.cos(t * 0.6) * 4.0;
  directionalLight.position.z = Math.sin(t * 0.6) * 4.0;
  directionalLight.position.y = 5.0 + Math.sin(t * 1.2) * 0.5;

  // Animate point light
  pointLight.position.x = Math.sin(t * 1.3) * 3.0;
  pointLight.position.z = Math.cos(t * 1.1) * 3.0;
  pointLight.position.y = 2.0 + Math.sin(t * 2.0) * 0.5;

  // Update shader uniforms
  shaderSphere.material.uniforms.uTime.value = t;
  shaderSphere.material.uniforms.uLightDir.value
    .copy(directionalLight.position)
    .normalize();

  // Animate objects
  const { torus, box } = scene.userData.animated;
  torus.rotation.x = t * 0.6;
  torus.rotation.y = t * 0.9;

  box.rotation.x = t * 0.8;
  box.rotation.y = t * 0.5;
  box.position.y = 0.6 + Math.sin(t * 1.5) * 0.2;

  controls.update();
  renderer.render(scene, camera);
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
}
```

