import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

let scene, camera, renderer, controls;
let animatedMesh, clock;
let dirLight;

init();
animate();

function init() {
  const container = document.getElementById('app');

  // Scene
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x0b1020);
  scene.fog = new THREE.Fog(0x0b1020, 10, 30);

  // Camera
  camera = new THREE.PerspectiveCamera(
    60,
    window.innerWidth / window.innerHeight,
    0.1,
    100
  );
  camera.position.set(4, 3, 7);

  // Renderer
  renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  container.appendChild(renderer.domElement);

  // Controls
  controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.target.set(0, 1, 0);

  // Lights
  const ambient = new THREE.AmbientLight(0x445577, 0.35);
  scene.add(ambient);

  dirLight = new THREE.DirectionalLight(0xffffff, 2.5);
  dirLight.position.set(5, 8, 4);
  dirLight.castShadow = true;
  dirLight.shadow.mapSize.set(2048, 2048);
  dirLight.shadow.camera.near = 0.5;
  dirLight.shadow.camera.far = 30;
  dirLight.shadow.camera.left = -10;
  dirLight.shadow.camera.right = 10;
  dirLight.shadow.camera.top = 10;
  dirLight.shadow.camera.bottom = -10;
  scene.add(dirLight);

  const pointLight = new THREE.PointLight(0x66aaff, 10, 20);
  pointLight.position.set(-3, 2, 3);
  scene.add(pointLight);

  // Floor
  const floorGeo = new THREE.PlaneGeometry(40, 40);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x151a28,
    roughness: 0.95,
    metalness: 0.05,
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Grid helper
  const grid = new THREE.GridHelper(40, 40, 0x334466, 0x223344);
  grid.position.y = 0.001;
  scene.add(grid);

  // Main animated object using custom shader material
  const sphereGeo = new THREE.SphereGeometry(1, 128, 128);

  const shaderMat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x3b82f6) },
      uColorB: { value: new THREE.Color(0xa855f7) },
      uLightPos: { value: new THREE.Vector3() },
    },
    vertexShader: `
      uniform float uTime;
      varying vec2 vUv;
      varying vec3 vNormal;
      varying vec3 vWorldPos;

      void main() {
        vUv = uv;
        vNormal = normalize(normalMatrix * normal);

        vec3 pos = position;

        // subtle vertex displacement
        float wave = sin(pos.y * 8.0 + uTime * 2.0) * 0.05;
        pos += normal * wave;

        vec4 worldPos = modelMatrix * vec4(pos, 1.0);
        vWorldPos = worldPos.xyz;

        gl_Position = projectionMatrix * viewMatrix * worldPos;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uColorA;
      uniform vec3 uColorB;
      uniform vec3 uLightPos;

      varying vec2 vUv;
      varying vec3 vNormal;
      varying vec3 vWorldPos;

      void main() {
        vec3 N = normalize(vNormal);
        vec3 L = normalize(uLightPos - vWorldPos);

        float diff = max(dot(N, L), 0.0);
        float fresnel = pow(1.0 - max(dot(N, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

        float stripes = 0.5 + 0.5 * sin((vUv.y * 20.0) + uTime * 4.0);
        vec3 base = mix(uColorA, uColorB, vUv.y);
        vec3 color = base * (0.25 + 0.85 * diff) + fresnel * 0.35;

        // extra glow banding
        color += stripes * 0.08;

        gl_FragColor = vec4(color, 1.0);
      }
    `,
  });

  animatedMesh = new THREE.Mesh(sphereGeo, shaderMat);
  animatedMesh.position.set(0, 1.2, 0);
  animatedMesh.castShadow = true;
  animatedMesh.receiveShadow = true;
  scene.add(animatedMesh);

  // Additional object for depth
  const boxGeo = new THREE.BoxGeometry(1, 1, 1);
  const boxMat = new THREE.MeshStandardMaterial({
    color: 0xe2e8f0,
    roughness: 0.3,
    metalness: 0.8,
  });
  const box = new THREE.Mesh(boxGeo, boxMat);
  box.position.set(2.2, 0.5, -1.2);
  box.castShadow = true;
  scene.add(box);

  // Clock
  clock = new THREE.Clock();

  // Resize
  window.addEventListener('resize', onWindowResize);
}

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // animate light motion
  dirLight.position.x = Math.cos(elapsed * 0.6) * 6;
  dirLight.position.z = Math.sin(elapsed * 0.6) * 6;
  dirLight.position.y = 6 + Math.sin(elapsed * 1.2) * 1.5;

  // animate shader
  animatedMesh.material.uniforms.uTime.value = elapsed;
  animatedMesh.material.uniforms.uLightPos.value.copy(dirLight.position);

  // object motion
  animatedMesh.rotation.y = elapsed * 0.25;
  animatedMesh.rotation.x = Math.sin(elapsed * 0.4) * 0.15;

  controls.update();
  renderer.render(scene, camera);
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
}
