const objectGeo = new THREE.IcosahedronGeometry(1.2, 4);
const object = new THREE.Mesh(objectGeo, shaderMat);
object.position.set(0, 1.6, 0);
scene.add(object);

// Additional objects
const sphereGeo = new THREE.SphereGeometry(0.4, 32, 32);
const sphereMat = new THREE.MeshStandardMaterial({
  color: 0xffcc66,
  roughness: 0.25,
  metalness: 0.7,
});

const sphere1 = new THREE.Mesh(sphereGeo, sphereMat);
sphere1.position.set(2.2, 0.5, 0.5);
scene.add(sphere1);

const sphere2 = new THREE.Mesh(sphereGeo, sphereMat.clone());
sphere2.material.color.set(0x66ffcc);
sphere2.position.set(-2, 0.5, -1);
scene.add(sphere2);

// Subtle background stars
const starsGeo = new THREE.BufferGeometry();
const starCount = 1000;
const starPositions = new Float32Array(starCount * 3);

for (let i = 0; i < starCount; i++) {
  starPositions[i * 3 + 0] = (Math.random() - 0.5) * 80;
  starPositions[i * 3 + 1] = Math.random() * 40;
  starPositions[i * 3 + 2] = (Math.random() - 0.5) * 80;
}

starsGeo.setAttribute("position", new THREE.BufferAttribute(starPositions, 3));
const starsMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.04,
  transparent: true,
  opacity: 0.85,
});
const stars = new THREE.Points(starsGeo, starsMat);
scene.add(stars);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  shaderMat.uniforms.uTime.value = elapsed;

  object.rotation.y = elapsed * 0.45;
  object.rotation.x = Math.sin(elapsed * 0.6) * 0.2;

  sphere1.position.y = 0.5 + Math.sin(elapsed * 2.0) * 0.15;
  sphere2.position.y = 0.5 + Math.cos(elapsed * 1.7) * 0.12;

  dirLight.position.x = Math.sin(elapsed * 0.7) * 5.0;
  dirLight.position.z = Math.cos(elapsed * 0.7) * 5.0;

  pointLight.position.x = Math.cos(elapsed * 1.1) * 3.5;
  pointLight.position.z = Math.sin(elapsed * 1.1) * 3.5;

  stars.rotation.y = elapsed * 0.01;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
