## `main.js`

```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

const canvas = document.getElementById("webgl");

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 12, 40);

const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.physicallyCorrectLights = true;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const hemiLight = new THREE.HemisphereLight(0x6b8cff, 0x101018, 0.7);
scene.add(hemiLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(4, 8, 5);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0xff4d6d, 20, 30, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11151d,
  roughness: 1.0,
  metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Shader material for the central object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uLightPos: { value: new THREE.Vector3() },
    uBaseColor: { value: new THREE.Color(0x4fd1ff) }
  },
  vertexShader: `
    varying vec3 vNormalW;
    varying vec3 vPosW;

    void main() {
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vPosW = worldPos.xyz;
      vNormalW = normalize(mat3(modelMatrix) * normal);
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    precision highp float;

    uniform float uTime;
    uniform vec3 uLightPos;
    uniform vec3 uBaseColor;

    varying vec3 vNormalW;
    varying vec3 vPosW;

    void main() {
      vec3 N = normalize(vNormalW);
      vec3 L = normalize(uLightPos - vPosW);
      vec3 V = normalize(cameraPosition - vPosW);
      vec3 H = normalize(L + V);

      float diff = max(dot(N, L), 0.0);
      float spec = pow(max(dot(N, H), 0.0), 64.0);

      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      float pulse = 0.5 + 0.5 * sin(uTime * 2.0);
      vec3 base = uBaseColor * (0.35 + 0.65 * diff);
      vec3 glow = vec3(0.9, 0.3, 1.0) * fresnel * (0.5 + 0.5 * pulse);

      vec3 color = base + glow + vec3(spec);
      gl_FragColor = vec4(color, 1.0);
    }
  `
});

// Central object
const sphere = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.2, 5),
  shaderMaterial
);
sphere.position.y = 1.2;
scene.add(sphere);

// Secondary objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.7, 0.22, 128, 24),
  new THREE.MeshStandardMaterial({
    color: 0x7cff6b,
    metalness: 0.7,
    roughness: 0.25
  })
);
torus.position.set(-2.3, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0xffb347,
    metalness: 0.2,
    roughness: 0.5
  })
);
box.position.set(2.2, 1.0, -0.8);
scene.add(box);

// Subtle atmosphere particles
const particlesCount = 500;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particlesCount * 3);

for (let i = 0; i < particlesCount; i++) {
  particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 30;
  particlePositions[i * 3 + 1] = Math.random() * 10;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 30;
}
particleGeo.setAttribute("position", new THREE.BufferAttribute(particlePositions, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0x8aa4ff,
  size: 0.04,
  transparent: true,
  opacity: 0.7
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const t = clock.getElapsedTime();

  // Dynamic motion
  sphere.rotation.y = t * 0.35;
  sphere.rotation.x = Math.sin(t * 0.4) * 0.15;

  torus.rotation.x = t * 0.4;
  torus.rotation.y = t * 0.25;

  box.rotation.x = t * 0.3;
  box.rotation.y = t * 0.5;

  particles.rotation.y = t * 0.02;

  // Animated point light
  pointLight.position.x = Math.cos(t * 1.4) * 3.0;
  pointLight.position.z = Math.sin(t * 1.4) * 3.0;
  pointLight.position.y = 1.5 + Math.sin(t * 2.0) * 0.7;

  // Pass light position into shader
  shaderMaterial.uniforms.uTime.value = t;
  shaderMaterial.uniforms.uLightPos.value.copy(pointLight.position);

  controls.update();
  renderer.render(scene, camera);

  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

