## 4) `main.js`

```js
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// --- Renderer ---
const canvas = document.getElementById("scene");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
  powerPreference: "high-performance",
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// --- Scene ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 12, 40);

// --- Camera ---
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  1000
);
camera.position.set(0, 3, 10);

// --- Controls ---
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// --- Lights ---
const ambient = new THREE.AmbientLight(0x88aaff, 0.25);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffffff, 2.5);
keyLight.position.set(5, 8, 4);
scene.add(keyLight);

const fillLight = new THREE.PointLight(0x4cc9f0, 40, 25);
fillLight.position.set(-4, 2, -2);
scene.add(fillLight);

const warmLight = new THREE.PointLight(0xff7b54, 30, 20);
warmLight.position.set(2, 1, 4);
scene.add(warmLight);

// Shadow-like depth cue via a grounded plane
const groundGeo = new THREE.PlaneGeometry(100, 100);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11151f,
  roughness: 1.0,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// --- Objects ---
const objects = [];

// Central shader-driven sphere
const sphereGeo = new THREE.SphereGeometry(1.2, 64, 64);
const sphereMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x9b5cff) },
    uLightPos: { value: new THREE.Vector3() },
  },
  vertexShader: `
    precision highp float;

    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);

      vec3 displaced = position;
      float wave = sin((position.y * 6.0) + uTime * 3.0) * 0.08;
      displacement:
      displaced += normal * wave;

      vec4 worldPos = modelMatrix * vec4(displaced, 1.0);
      vWorldPos = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    precision highp float;

    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform vec3 uLightPos;

    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(uLightPos - vWorldPos);
      vec3 V = normalize(cameraPosition - vWorldPos);
      vec3 H = normalize(L + V);

      float diff = max(dot(N, L), 0.0);
      float spec = pow(max(dot(N, H), 0.0), 64.0);

      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      float stripe = 0.5 + 0.5 * sin((vUv.y * 24.0) + uTime * 4.0);
      vec3 base = mix(uColorA, uColorB, stripe);

      vec3 color = base * (0.2 + diff * 1.2) + spec * vec3(1.0) * 0.8 + fresnel * 0.6;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});
const sphere = new THREE.Mesh(sphereGeo, sphereMat);
sphere.position.y = 1.3;
scene.add(sphere);
objects.push(sphere);

// Orbiting emissive cubes
const cubeGeo = new THREE.BoxGeometry(0.55, 0.55, 0.55);
const cubeMat = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  roughness: 0.25,
  metalness: 0.7,
  emissive: 0x111111,
});
const cubes = [];
for (let i = 0; i < 6; i++) {
  const cube = new THREE.Mesh(cubeGeo, cubeMat.clone());
  cube.material.color = new THREE.Color().setHSL(i / 6, 0.8, 0.6);
  cube.material.emissive = cube.material.color.clone().multiplyScalar(0.2);
  cube.position.set(Math.cos((i / 6) * Math.PI * 2) * 4, 1.2, Math.sin((i / 6) * Math.PI * 2) * 4);
  scene.add(cube);
  cubes.push(cube);
}

// Decorative torus
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.24, 160, 24),
  new THREE.MeshStandardMaterial({
    color: 0xddddff,
    roughness: 0.2,
    metalness: 1.0,
  })
);
torus.position.set(0, 2.2, 0);
scene.add(torus);

// Low-poly environment lights
const gridHelper = new THREE.GridHelper(30, 30, 0x223355, 0x111a2a);
gridHelper.position.y = 0.001;
scene.add(gridHelper);

// --- Stats/UI ---
const stats = document.getElementById("stats");
let frameCount = 0;
let lastFpsTime = performance.now();
let fps = 0;

// --- Resize ---
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// --- Animation loop ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();
  controls.update();

  // Dynamic lighting motion
  keyLight.position.x = Math.sin(t * 0.7) * 6;
  keyLight.position.z = Math.cos(t * 0.7) * 6;
  fillLight.position.x = Math.cos(t * 1.3) * 4;
  fillLight.position.z = Math.sin(t * 1.1) * 3;
  warmLight.position.y = 1.5 + Math.sin(t * 2.0) * 0.6;

  // Shader uniforms
  sphere.material.uniforms.uTime.value = t;
  sphere.material.uniforms.uLightPos.value.copy(fillLight.position);

  // Object animation
  sphere.rotation.y = t * 0.4;
  torus.rotation.x = t * 0.5;
  torus.rotation.y = t * 0.35;

  cubes.forEach((cube, i) => {
    const a = t * 0.6 + (i / cubes.length) * Math.PI * 2;
    cube.position.x = Math.cos(a) * 4.5;
    cube.position.z = Math.sin(a) * 4.5;
    cube.position.y = 1.1 + Math.sin(t * 2 + i) * 0.25;
    cube.rotation.x = t * (0.8 + i * 0.05);
    cube.rotation.y = t * (1.1 + i * 0.03);
  });

  renderer.render(scene, camera);

  // FPS update
  frameCount++;
  const now = performance.now();
  if (now - lastFpsTime >= 500) {
    fps = Math.round((frameCount * 1000) / (now - lastFpsTime));
    frameCount = 0;
    lastFpsTime = now;
    stats.textContent = `FPS: ${fps} | Objects: ${scene.children.length}`;
  }
}

animate();
```

