## `main.js`

```js
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

// Renderer
const app = document.getElementById('app');
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
app.appendChild(renderer.domElement);

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070c);
scene.fog = new THREE.Fog(0x05070c, 10, 35);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0x88aaff, 1.2);
directionalLight.position.set(4, 6, 2);
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0xff8844, 80, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeometry = new THREE.PlaneGeometry(40, 40);
const groundMaterial = new THREE.MeshStandardMaterial({
  color: 0x101420,
  roughness: 1,
  metalness: 0
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Helper grid
const grid = new THREE.GridHelper(40, 40, 0x334455, 0x1b2230);
grid.position.y = 0;
scene.add(grid);

// Shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00ccff) },
    uColorB: { value: new THREE.Color(0x7c4dff) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPosition;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);

      vec3 pos = position;
      float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.06;
      pos += normal * wave;

      vec4 worldPosition = modelMatrix * vec4(pos, 1.0);
      vWorldPosition = worldPosition.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPosition;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPosition;

    void main() {
      vec3 viewDir = normalize(cameraPosition - vWorldPosition);
      float fresnel = pow(1.0 - max(dot(viewDir, normalize(vNormal)), 0.0), 3.0);

      float pattern = 0.5 + 0.5 * sin((vUv.x + vUv.y + uTime * 0.2) * 12.0);
      vec3 baseColor = mix(uColorA, uColorB, pattern);

      vec3 color = baseColor + fresnel * 0.5;
      gl_FragColor = vec4(color, 1.0);
    }
  `
});

// Main mesh
const sphere = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.3, 5),
  shaderMaterial
);
sphere.position.y = 1.8;
scene.add(sphere);

// Additional objects for depth
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.75, 0.25, 120, 16),
  new THREE.MeshStandardMaterial({
    color: 0xddddff,
    metalness: 0.7,
    roughness: 0.25
  })
);
torus.position.set(3, 1.5, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0xffaa66,
    metalness: 0.2,
    roughness: 0.4
  })
);
box.position.set(-3, 0.5, 0);
scene.add(box);

// Animation
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = elapsed;
  pointLight.position.x = Math.sin(elapsed * 1.3) * 4;
  pointLight.position.z = Math.cos(elapsed * 1.3) * 4;
  pointLight.position.y = 2 + Math.sin(elapsed * 2.0) * 0.5;

  sphere.rotation.y = elapsed * 0.4;
  sphere.rotation.x = Math.sin(elapsed * 0.3) * 0.2;

  torus.rotation.x = elapsed * 0.5;
  torus.rotation.y = elapsed * 0.8;

  box.rotation.x = elapsed * 0.2;
  box.rotation.y = elapsed * 0.6;

  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

