```js
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

// Renderer
const renderer = new THREE.WebGLRenderer({
  antialias: true,
  alpha: false,
  powerPreference: 'high-performance'
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.body.appendChild(renderer.domElement);

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050816);
scene.fog = new THREE.Fog(0x050816, 8, 30);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 1, 0);

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 2.5);
directionalLight.position.set(5, 10, 4);
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0x66ccff, 2.5, 20, 2);
pointLight.position.set(-3, 2, 2);
scene.add(pointLight);

const movingLight = new THREE.PointLight(0xff3366, 3.0, 15, 2);
movingLight.position.set(0, 3, 0);
scene.add(movingLight);

// Scene objects
const groundGeo = new THREE.PlaneGeometry(40, 40);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 0.95,
  metalness: 0.05
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Central object with shader effect
const sphereGeo = new THREE.IcosahedronGeometry(1.2, 32);

const sphereMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x34d399) },
    uColorB: { value: new THREE.Color(0x3b82f6) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    // Simple wave displacement for surface animation
    void main() {
      vec3 pos = position;
      float wave = sin(pos.x * 4.0 + uTime * 2.0) 
                 * cos(pos.y * 4.0 + uTime * 1.5) 
                 * sin(pos.z * 4.0 + uTime * 1.2);
      pos += normal * wave * 0.08;

      vNormal = normalize(normalMatrix * normal);
      vPosition = (modelMatrix * vec4(pos, 1.0)).xyz;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 lightDir = normalize(vec3(0.4, 0.9, 0.2));
      float diff = max(dot(vNormal, lightDir), 0.0);

      float fresnel = pow(1.0 - max(dot(normalize(vNormal), normalize(-vPosition)), 0.0), 3.0);

      float stripes = 0.5 + 0.5 * sin(vPosition.y * 8.0 + uTime * 3.0);
      vec3 baseColor = mix(uColorA, uColorB, stripes);

      vec3 color = baseColor * (0.25 + diff * 0.95) + fresnel * vec3(0.7, 0.9, 1.0);

      gl_FragColor = vec4(color, 1.0);
    }
  `,
  side: THREE.DoubleSide
});

const sphere = new THREE.Mesh(sphereGeo, sphereMat);
sphere.position.y = 1.25;
scene.add(sphere);

// Small orbiting objects
const orbitGroup = new THREE.Group();
scene.add(orbitGroup);

const torusGeo = new THREE.TorusKnotGeometry(0.45, 0.14, 128, 16);
const torusMat = new THREE.MeshStandardMaterial({
  color: 0xffcc66,
  metalness: 0.7,
  roughness: 0.25
});
const torus = new THREE.Mesh(torusGeo, torusMat);
torus.position.set(2.5, 1.4, 0);
orbitGroup.add(torus);

const boxGeo = new THREE.BoxGeometry(0.6, 0.6, 0.6);
const boxMat = new THREE.MeshStandardMaterial({
  color: 0x8b5cf6,
  metalness: 0.3,
  roughness: 0.5
});
const box = new THREE.Mesh(boxGeo, boxMat);
box.position.set(-2.5, 0.8, 0);
orbitGroup.add(box);

// Decorative particles
const particlesCount = 400;
const particlesGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particlesCount * 3);

for (let i = 0; i < particlesCount; i++) {
  positions[i * 3 + 0] = (Math.random() - 0.5) * 30;
  positions[i * 3 + 1] = Math.random() * 10;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 30;
}
particlesGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));

const particlesMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.03
});

const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  sphereMat.uniforms.uTime.value = elapsed;

  // Dynamic lighting motion
  movingLight.position.x = Math.sin(elapsed * 1.2) * 4.0;
  movingLight.position.z = Math.cos(elapsed * 1.2) * 4.0;
  movingLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 0.5;

  pointLight.intensity = 2.0 + Math.sin(elapsed * 3.0) * 0.5;
  directionalLight.position.x = Math.cos(elapsed * 0.4) * 5;
  directionalLight.position.z = Math.sin(elapsed * 0.4) * 5;

  sphere.rotation.y = elapsed * 0.35;
  sphere.rotation.x = Math.sin(elapsed * 0.25) * 0.15;

  orbitGroup.rotation.y = elapsed * 0.6;
  torus.rotation.x = elapsed * 0.8;
  torus.rotation.y = elapsed * 0.5;
  box.rotation.x = elapsed * 1.1;
  box.rotation.z = elapsed * 0.7;

  particles.rotation.y = elapsed * 0.02;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

