import * as THREE from 'three';

// --------------------------------------------------
// Basic setup
// --------------------------------------------------
const app = document.getElementById('app');

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 12, 45);

const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 4, 10);

const renderer = new THREE.WebGLRenderer({
  antialias: true,
  alpha: false,
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
app.appendChild(renderer.domElement);

// --------------------------------------------------
// Lights
// --------------------------------------------------
const ambient = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.0);
directional.position.set(5, 8, 3);
scene.add(directional);

const pointLight = new THREE.PointLight(0x66aaff, 2.5, 25, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Optional helper for debugging lighting
// scene.add(new THREE.PointLightHelper(pointLight, 0.25));

// --------------------------------------------------
// Floor
// --------------------------------------------------
const floorGeometry = new THREE.PlaneGeometry(40, 40, 1, 1);
const floorMaterial = new THREE.MeshStandardMaterial({
  color: 0x1a1f2e,
  roughness: 0.95,
  metalness: 0.05,
});
const floor = new THREE.Mesh(floorGeometry, floorMaterial);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.5;
floor.receiveShadow = false;
scene.add(floor);

// --------------------------------------------------
// Shader effect material
// Simple animated emissive-like shader for the sphere
// --------------------------------------------------
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x9b5de5) },
  },
  vertexShader: `
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vUv = uv;
      vNormal = normalMatrix * normal;
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    precision highp float;

    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 3.0);
      float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);
      vec3 base = mix(uColorA, uColorB, vUv.y);
      vec3 glow = base + fresnel * 0.8 + pulse * 0.2;
      gl_FragColor = vec4(glow, 1.0);
    }
  `,
});

// --------------------------------------------------
// Scene objects
// --------------------------------------------------

// Main shader sphere
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.25, 64, 64),
  shaderMaterial
);
sphere.position.set(0, 1.5, 0);
scene.add(sphere);

// Rotating torus
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.75, 0.25, 128, 16),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    metalness: 0.85,
    roughness: 0.2,
  })
);
torus.position.set(-2.5, 1.2, 0);
scene.add(torus);

// Reflective cube
const cube = new THREE.Mesh(
  new THREE.BoxGeometry(1.4, 1.4, 1.4),
  new THREE.MeshStandardMaterial({
    color: 0xddddff,
    metalness: 0.6,
    roughness: 0.35,
  })
);
cube.position.set(2.5, 1.0, 0);
scene.add(cube);

// Floating ring
const ring = new THREE.Mesh(
  new THREE.TorusGeometry(1.0, 0.15, 24, 64),
  new THREE.MeshStandardMaterial({
    color: 0xffc857,
    metalness: 0.75,
    roughness: 0.25,
  })
);
ring.position.set(0, 3.4, -2.5);
ring.rotation.x = Math.PI / 2;
scene.add(ring);

// --------------------------------------------------
// Mouse interaction for light movement
// --------------------------------------------------
const mouse = new THREE.Vector2(0, 0);

window.addEventListener('mousemove', (e) => {
  mouse.x = (e.clientX / window.innerWidth) * 2 - 1;
  mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;
});

// --------------------------------------------------
// Simple orbit-like camera motion
// --------------------------------------------------
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Animate shader
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Animate scene objects
  sphere.rotation.y = elapsed * 0.5;
  torus.rotation.x = elapsed * 0.6;
  torus.rotation.y = elapsed * 0.3;
  cube.rotation.x = elapsed * 0.4;
  cube.rotation.y = elapsed * 0.5;
  ring.rotation.z = elapsed * 0.7;

  // Dynamic lighting
  pointLight.position.x = mouse.x * 5;
  pointLight.position.y = 2.5 + mouse.y * 2;
  pointLight.position.z = 4 + Math.sin(elapsed * 1.5) * 2;

  directional.position.x = Math.sin(elapsed * 0.4) * 6;
  directional.position.z = Math.cos(elapsed * 0.4) * 6;

  // Mild camera drift
  camera.position.x = Math.sin(elapsed * 0.2) * 0.7;
  camera.position.y = 4 + Math.sin(elapsed * 0.35) * 0.2;
  camera.lookAt(0, 1.2, 0);

  renderer.render(scene, camera);
}

animate();

// --------------------------------------------------
// Resize handling
// --------------------------------------------------
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

