```javascript
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// -----------------------------
// Renderer
// -----------------------------
const canvas = document.getElementById("scene-canvas");

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});

renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// -----------------------------
// Scene / Camera
// -----------------------------
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070c);
scene.fog = new THREE.Fog(0x05070c, 12, 40);

const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(4, 3, 7);

// -----------------------------
// Controls
// -----------------------------
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 1, 0);

// -----------------------------
// Lights
// -----------------------------
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
dirLight.position.set(5, 10, 3);
scene.add(dirLight);

const pointLight1 = new THREE.PointLight(0x44aaff, 2.5, 20);
pointLight1.position.set(2, 2, 2);
scene.add(pointLight1);

const pointLight2 = new THREE.PointLight(0xff4477, 2.0, 20);
pointLight2.position.set(-2, 1.5, -2);
scene.add(pointLight2);

// visible light markers
const lightMarkerGeo = new THREE.SphereGeometry(0.08, 16, 16);
const lightMarkerMat1 = new THREE.MeshBasicMaterial({ color: 0x44aaff });
const lightMarkerMat2 = new THREE.MeshBasicMaterial({ color: 0xff4477 });

const marker1 = new THREE.Mesh(lightMarkerGeo, lightMarkerMat1);
const marker2 = new THREE.Mesh(lightMarkerGeo, lightMarkerMat2);
scene.add(marker1, marker2);

// -----------------------------
// Floor
// -----------------------------
const floorGeo = new THREE.PlaneGeometry(50, 50);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0x101826,
  roughness: 1,
  metalness: 0,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = 0;
scene.add(floor);

// -----------------------------
// Shader material
// Animated emissive-like wave effect.
// -----------------------------
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x44aaff) },
    uColorB: { value: new THREE.Color(0xff4477) },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;
    uniform float uTime;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);

      vec3 pos = position;

      // subtle vertex wobble
      float wave = sin(pos.x * 5.0 + uTime * 2.0) * 0.03;
      wave += cos(pos.y * 4.0 + uTime * 1.5) * 0.02;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vWorldPos = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 V = normalize(cameraPosition - vWorldPos);

      // Fresnel
      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      // moving stripes
      float stripes = sin((vUv.x + vUv.y) * 20.0 - uTime * 4.0) * 0.5 + 0.5;

      vec3 base = mix(uColorA, uColorB, stripes);
      vec3 color = base * 0.35 + fresnel * base * 1.6;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
  side: THREE.DoubleSide,
});

// -----------------------------
// Scene objects
// -----------------------------
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMaterial
);
sphere.position.set(0, 1.2, 0);
scene.add(sphere);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.55, 0.2, 180, 16),
  new THREE.MeshStandardMaterial({
    color: 0xe0e6ff,
    metalness: 0.85,
    roughness: 0.25,
  })
);
torus.position.set(2.2, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0xa8ffcf,
    metalness: 0.3,
    roughness: 0.4,
  })
);
box.position.set(-2.2, 0.75, 0);
scene.add(box);

// -----------------------------
// Animation loop
// -----------------------------
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();

  // animate shader
  shaderMaterial.uniforms.uTime.value = elapsed;

  // animate scene objects
  sphere.rotation.y = elapsed * 0.45;
  sphere.rotation.x = elapsed * 0.2;

  torus.rotation.x = elapsed * 0.7;
  torus.rotation.y = elapsed * 0.5;

  box.rotation.x = elapsed * 0.4;
  box.rotation.y = elapsed * 0.8;

  // move lights
  pointLight1.position.x = Math.cos(elapsed * 1.2) * 3.0;
  pointLight1.position.z = Math.sin(elapsed * 1.2) * 3.0;
  pointLight1.position.y = 2.0 + Math.sin(elapsed * 2.0) * 0.5;

  pointLight2.position.x = Math.cos(-elapsed * 1.0) * 3.2;
  pointLight2.position.z = Math.sin(-elapsed * 1.0) * 3.2;
  pointLight2.position.y = 1.5 + Math.cos(elapsed * 1.7) * 0.4;

  marker1.position.copy(pointLight1.position);
  marker2.position.copy(pointLight2.position);

  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

animate();

// -----------------------------
// Resize handling
// -----------------------------
window.addEventListener("resize", () => {
  const w = window.innerWidth;
  const h = window.innerHeight;

  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

