import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.164.1/examples/jsm/controls/OrbitControls.js";

// Renderer
const canvas = document.getElementById("scene-canvas");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 35);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(5, 4, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x6a7cff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 1.4);
directional.position.set(5, 8, 3);
directional.castShadow = true;
directional.shadow.mapSize.set(2048, 2048);
directional.shadow.camera.near = 1;
directional.shadow.camera.far = 30;
directional.shadow.camera.left = -10;
directional.shadow.camera.right = 10;
directional.shadow.camera.top = 10;
directional.shadow.camera.bottom = -10;
scene.add(directional);

const pointLight = new THREE.PointLight(0x7c4dff, 2.5, 25, 2);
pointLight.position.set(-3, 2, 0);
pointLight.castShadow = true;
scene.add(pointLight);

// Floor
const floorGeo = new THREE.PlaneGeometry(30, 30);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0x11131a,
  metalness: 0.2,
  roughness: 0.9,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

// Shader material for the main object
const uniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x4dd0ff) },
  uColorB: { value: new THREE.Color(0x8a4dff) },
};

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms,
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalMatrix * normal;
      vec3 pos = position;

      float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.08;
      wave += cos(pos.y * 3.5 + uTime * 1.5) * 0.06;
      pos += normal * wave;

      vec4 worldPosition = modelMatrix * vec4(pos, 1.0);
      vPosition = worldPosition.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPosition;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.6));
      float diff = max(dot(n, lightDir), 0.0);

      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 2.0);
      vec3 base = mix(uColorA, uColorB, pulse);

      vec3 viewDir = normalize(cameraPosition - vPosition);
      float fresnel = pow(1.0 - max(dot(n, viewDir), 0.0), 2.5);

      vec3 color = base * (0.25 + diff * 0.85) + fresnel * vec3(1.0, 1.0, 1.0) * 0.8;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

const sphere = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.2, 4),
  shaderMaterial
);
sphere.position.y = 1.5;
sphere.castShadow = true;
sphere.receiveShadow = false;
scene.add(sphere);

// Additional supporting objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.75, 0.23, 180, 24),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    metalness: 0.6,
    roughness: 0.15,
  })
);
torus.position.set(2.7, 1.4, 0);
torus.castShadow = true;
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(0.9, 0.9, 0.9),
  new THREE.MeshStandardMaterial({
    color: 0x2d3748,
    metalness: 0.3,
    roughness: 0.7,
  })
);
box.position.set(-2.6, 0.45, 0);
box.castShadow = true;
scene.add(box);

// Small floating emissive particles
const particleGeo = new THREE.SphereGeometry(0.06, 12, 12);
const particleMat = new THREE.MeshBasicMaterial({ color: 0x89d8ff });
const particles = [];
for (let i = 0; i < 40; i++) {
  const p = new THREE.Mesh(particleGeo, particleMat);
  p.position.set(
    (Math.random() - 0.5) * 12,
    Math.random() * 4 + 0.5,
    (Math.random() - 0.5) * 12
  );
  scene.add(p);
  particles.push({
    mesh: p,
    speed: 0.5 + Math.random() * 1.5,
    phase: Math.random() * Math.PI * 2,
  });
}

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();
  uniforms.uTime.value = elapsed;

  sphere.rotation.y = elapsed * 0.5;
  sphere.rotation.x = Math.sin(elapsed * 0.4) * 0.15;

  torus.rotation.x = elapsed * 0.4;
  torus.rotation.y = elapsed * 0.6;

  box.rotation.y = elapsed * 0.8;
  box.rotation.x = elapsed * 0.3;

  pointLight.position.x = Math.sin(elapsed * 1.2) * 4.0;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4.0;
  pointLight.position.y = 2.2 + Math.sin(elapsed * 2.0) * 0.6;

  for (const p of particles) {
    p.mesh.position.y += Math.sin(elapsed * p.speed + p.phase) * 0.002;
    p.mesh.position.x += Math.cos(elapsed * p.speed + p.phase) * 0.001;
  }

  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
