scene.add(ambient);

const hemi = new THREE.HemisphereLight(0x88aaff, 0x223344, 0.7);
scene.add(hemi);

const keyLight = new THREE.DirectionalLight(0xffffff, 2.0);
keyLight.position.set(4, 6, 3);
keyLight.castShadow = false;
scene.add(keyLight);

const pointLight = new THREE.PointLight(0x66ccff, 40, 20, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// --- Ground ---
const groundGeo = new THREE.PlaneGeometry(50, 50, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x0d1320,
  roughness: 1.0,
  metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = 0;
scene.add(ground);

// --- Objects ---
const objects = [];

function createPBRObject(geometry, materialProps, position) {
  const mat = new THREE.MeshStandardMaterial(materialProps);
  const mesh = new THREE.Mesh(geometry, mat);
  mesh.position.copy(position);
  scene.add(mesh);
  objects.push(mesh);
  return mesh;
}

createPBRObject(
  new THREE.TorusKnotGeometry(0.9, 0.3, 160, 24),
  {
    color: 0x7cf7ff,
    metalness: 0.9,
    roughness: 0.15
  },
  new THREE.Vector3(-2, 1.3, 0)
);

createPBRObject(
  new THREE.SphereGeometry(0.9, 64, 64),
  {
    color: 0xff7ad9,
    metalness: 0.7,
    roughness: 0.2
  },
  new THREE.Vector3(2, 1.0, 0)
);

createPBRObject(
  new THREE.BoxGeometry(1.5, 1.5, 1.5),
  {
    color: 0xffd166,
    metalness: 0.2,
    roughness: 0.6
  },
  new THREE.Vector3(0, 0.75, -2.2)
);

// --- Shader-effect object ---
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x00e5ff) },
  uColorB: { value: new THREE.Color(0x7f5cff) }
};

const shaderMat = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader: `
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      float wave = sin(vUv.x * 10.0 + uTime * 2.0) * 0.5 + 0.5;
      float radial = length(vUv - 0.5);
      float glow = smoothstep(0.7, 0.1, radial);

      vec3 base = mix(uColorA, uColorB, wave);
      vec3 lit = base * (0.35 + 0.65 * abs(vNormal.z));
      vec3 finalColor = lit + glow * 0.7;

      gl_FragColor = vec4(finalColor, 1.0);
    }
  `
});

const shaderMesh = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.0, 2),
  shaderMat
);
shaderMesh.position.set(0, 3, 0);
scene.add(shaderMesh);

// --- Floating particles ---
const particleCount = 300;
const positions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  positions[i * 3 + 0] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = Math.random() * 10;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}

const particlesGeo = new THREE.BufferGeometry();
particlesGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

const particlesMat = new THREE.PointsMaterial({
  color: 0x99bbff,
  size: 0.05,
  transparent: true,
  opacity: 0.7
});

const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// --- Animation ---
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  controls.update();

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(t * 0.8) * 4;
  pointLight.position.z = Math.cos(t * 0.8) * 4;
  pointLight.position.y = 2.5 + Math.sin(t * 1.4) * 0.8;
  pointLight.intensity = 30 + Math.sin(t * 2.2) * 10;

  keyLight.position.x = Math.cos(t * 0.3) * 6;
  keyLight.position.z = Math.sin(t * 0.3) * 6;

  // Object animation
  objects.forEach((obj, i) => {
    obj.rotation.x += 0.003 * (i + 1);
    obj.rotation.y += 0.005 * (i + 1);
    obj.position.y = 0.8 + Math.sin(t * 1.5 + i) * 0.15;
  });

  shaderMesh.rotation.y = t * 0.8;
  shaderMesh.rotation.x = Math.sin(t * 0.5) * 0.2;
  shaderUniforms.uTime.value = t;

  particles.rotation.y = t * 0.03;

  renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

