## 4) `main.js`

```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas / renderer
const canvas = document.getElementById("scene");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// Scene / camera
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 30);

const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0x9ecbff, 2.0);
dirLight.position.set(5, 8, 3);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0xff7a18, 40, 20, 2);
pointLight.position.set(0, 2, 4);
scene.add(pointLight);

// Helper light visual
const pointHelper = new THREE.Mesh(
  new THREE.SphereGeometry(0.08, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0xff7a18 })
);
scene.add(pointHelper);

// Ground plane
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(40, 40),
  new THREE.MeshStandardMaterial({
    color: 0x111827,
    roughness: 1.0,
    metalness: 0.0,
  })
);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Custom shader material for object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x7c3aed) },
    uGlow: { value: 0.8 },
    uLightDir: { value: new THREE.Vector3(1, 1, 1).normalize() },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPosition;
    varying vec3 vViewPosition;

    void main() {
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPosition = modelMatrix * vec4(position, 1.0);
      vWorldPosition = worldPosition.xyz;
      vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
      vViewPosition = -mvPosition.xyz;
      gl_Position = projectionMatrix * mvPosition;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform float uGlow;
    uniform vec3 uLightDir;

    varying vec3 vNormal;
    varying vec3 vWorldPosition;
    varying vec3 vViewPosition;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(uLightDir);

      float diff = max(dot(N, L), 0.0);
      float fresnel = pow(1.0 - max(dot(normalize(vViewPosition), N), 0.0), 3.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPosition.y * 4.0 + vWorldPosition.x * 2.0);
      vec3 baseColor = mix(uColorA, uColorB, wave);

      vec3 ambient = baseColor * 0.15;
      vec3 lit = baseColor * diff;
      vec3 emissive = baseColor * fresnel * uGlow;

      vec3 finalColor = ambient + lit + emissive;

      gl_FragColor = vec4(finalColor, 1.0);
    }
  `,
});

// Main object
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1.1, 0.35, 220, 32),
  shaderMaterial
);
torus.position.y = 1.4;
scene.add(torus);

// Optional backdrop geometry for depth
const backSphere = new THREE.Mesh(
  new THREE.SphereGeometry(12, 48, 48),
  new THREE.MeshStandardMaterial({
    color: 0x09111f,
    side: THREE.BackSide,
    roughness: 1.0,
    metalness: 0.0,
  })
);
scene.add(backSphere);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Animate lights
  pointLight.position.x = Math.sin(elapsed * 1.2) * 4.0;
  pointLight.position.y = 2.0 + Math.sin(elapsed * 2.0) * 0.7;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4.0;

  pointHelper.position.copy(pointLight.position);

  // Animate object
  torus.rotation.x = elapsed * 0.35;
  torus.rotation.y = elapsed * 0.6;

  // Update shader lighting direction from directional light
  shaderMaterial.uniforms.uLightDir.value
    .copy(dirLight.position)
    .normalize();

  controls.update();
  renderer.render(scene, camera);

  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
```

