controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Geometry
const floorGeometry = new THREE.PlaneGeometry(30, 30, 1, 1);
const floorMaterial = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 0.9,
  metalness: 0.05,
});
const floor = new THREE.Mesh(floorGeometry, floorMaterial);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

// Custom shader material for central object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4f46e5) },
    uColorB: { value: new THREE.Color(0x22d3ee) },
  },
  vertexShader: `
    varying vec3 vPosition;
    varying vec3 vNormal;

    void main() {
      vPosition = position;
      vNormal = normal;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vPosition;
    varying vec3 vNormal;

    void main() {
      float wave = sin(uTime * 2.0 + vPosition.y * 6.0) * 0.5 + 0.5;
      float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);

      vec3 color = mix(uColorA, uColorB, wave);
