  sphere.rotation.x = elapsed * 0.15;
  torus.rotation.x = elapsed * 0.4;
  torus.rotation.y = elapsed * 0.3;
  box.rotation.x = elapsed * 0.6;
  box.rotation.y = elapsed * 0.4;

  // Shader time update
  shaderMaterial.uniforms.uTime.value = elapsed;

  controls.update();
  renderer.render(scene, camera);
}

animate();

