import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.getElementById("app").appendChild(renderer.domElement);

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 8, 25);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 1.5, 6);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0x8ecbff, 2.5);
directionalLight.position.set(5, 8, 4);
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0xff7ad9, 3, 20);
pointLight.position.set(-3, 2, 2);
scene.add(pointLight);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x2de2e6) },
    uColorB: { value: new THREE.Color(0xff7ad9) }
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vPosition;
    varying vec2 vUv;

    void main() {
      vNormal = normalMatrix * normal;
      vPosition = position;
      vUv = uv;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vPosition;
    varying vec2 vUv;

    void main() {
      vec3 n = normalize(vNormal);
      float lightStrength = dot(n, normalize(vec3(0.3, 0.8, 0.5))) * 0.5 + 0.5;

      float wave = sin(vUv.x * 10.0 + uTime * 2.0) * cos(vUv.y * 10.0 + uTime * 1.5);
      wave = wave * 0.5 + 0.5;

      vec3 baseColor = mix(uColorA, uColorB, wave);
      vec3 finalColor = baseColor * lightStrength;

      gl_FragColor = vec4(finalColor, 1.0);
    }
  `
});

// Geometry
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.35, 220, 32),
  shaderMaterial
);
torus.position.y = 1.2;
scene.add(torus);

const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(40, 40),
  new THREE.MeshStandardMaterial({
    color: 0x111722,
    roughness: 0.95,
    metalness: 0.05
  })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = 0;
scene.add(floor);

// Additional objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.65, 64, 64),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.2,
    metalness: 0.8,
    emissive: 0x111111
  })
);
sphere.position.set(-2.2, 0.8, 0);
scene.add(sphere);

const cube = new THREE.Mesh(
  new THREE.BoxGeometry(0.9, 0.9, 0.9),
  new THREE.MeshStandardMaterial({
    color: 0x7a9cff,
    roughness: 0.35,
    metalness: 0.6
  })
);
cube.position.set(2.2, 0.45, 0);
scene.add(cube);

// Subtle grid helper
const grid = new THREE.GridHelper(40, 40, 0x223040, 0x111820);
grid.position.y = 0.01;
scene.add(grid);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  shaderMaterial.uniforms.uTime.value = elapsed;

  torus.rotation.x = elapsed * 0.35;
  torus.rotation.y = elapsed * 0.55;

  sphere.rotation.y = elapsed * 0.8;
  cube.rotation.x = elapsed * 0.6;
  cube.rotation.y = elapsed * 0.4;

  pointLight.position.x = Math.sin(elapsed * 1.3) * 4;
  pointLight.position.z = Math.cos(elapsed * 1.3) * 4;

  directionalLight.intensity = 2.0 + Math.sin(elapsed * 0.9) * 0.5;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
```

