## 3) `main.js`

```js
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

const app = document.getElementById('app');

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  1000
);
camera.position.set(0, 3, 8);

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
app.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lighting
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.5);
dirLight.position.set(5, 10, 4);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0x66aaff, 15, 30);
pointLight.position.set(-3, 2, 0);
scene.add(pointLight);

// Helpers
const grid = new THREE.GridHelper(20, 20, 0x335577, 0x223344);
grid.position.y = 0;
scene.add(grid);

// Floor
const floorGeo = new THREE.PlaneGeometry(30, 30);
const floorMat = new THREE.MeshStandardMaterial({
  color: 0x101822,
  roughness: 0.95,
  metalness: 0.0,
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

// Shader material for dynamic visual effect
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0.0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x7209b7) },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));

      float diff = max(dot(n, lightDir), 0.0);
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 3.0);

      vec3 base = mix(uColorA, uColorB, pulse);
      vec3 color = base * (0.25 + diff * 1.1);

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMaterial
);
sphere.position.set(-2, 1.25, 0);
scene.add(sphere);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.5, 1.5, 1.5),
  new THREE.MeshStandardMaterial({
    color: 0xffb703,
    roughness: 0.35,
    metalness: 0.4,
  })
);
box.position.set(2, 1, 0);
scene.add(box);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.28, 150, 16),
  new THREE.MeshStandardMaterial({
    color: 0x8ecae6,
    roughness: 0.2,
    metalness: 0.8,
  })
);
torus.position.set(0, 1.5, -2);
scene.add(torus);

// Simple floating particles
const particlesGeo = new THREE.BufferGeometry();
const particleCount = 500;
const positions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  positions[i * 3 + 0] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = Math.random() * 8;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}

particlesGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));

const particlesMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.05,
  transparent: true,
  opacity: 0.7,
});

const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// Resize
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Update shader time
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Animate objects
  sphere.rotation.y = elapsed * 0.6;
  sphere.position.y = 1.25 + Math.sin(elapsed * 2.0) * 0.15;

  box.rotation.x = elapsed * 0.5;
  box.rotation.y = elapsed * 0.8;

  torus.rotation.x = elapsed * 0.4;
  torus.rotation.z = elapsed * 0.3;

  pointLight.position.x = Math.sin(elapsed) * 4;
  pointLight.position.z = Math.cos(elapsed) * 4;
  pointLight.position.y = 2 + Math.sin(elapsed * 2.0) * 0.5;

  particles.rotation.y = elapsed * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();
```

