  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070f);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 1.5, 4);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(0.8, 0.25, 160, 32);

    // Custom shader material
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0xff3d81) }
      },
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalMatrix * normal;
          vPosition = (modelMatrix * vec4(position, 1.0)).xyz;
          gl_Position = projectionMatrix * viewMatrix * vec4(vPosition, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 lightDir = normalize(vec3(1.0, 1.0, 0.5));
          float diffuse = max(dot(normalize(vNormal), lightDir), 0.0);

          // Animated shader effect
          float wave = 0.5 + 0.5 * sin(uTime + vPosition.y * 4.0);

          vec3 baseColor = mix(uColorA, uColorB, wave);
          vec3 color = baseColor * (0.2 + 0.8 * diffuse);

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Dynamic lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0x00d4ff, 2.0, 20);
    pointLight.position.set(2, 2, 3);
    scene.add(pointLight);

    const pointLight2 = new THREE.PointLight(0xff3d81, 2.0, 20);
    pointLight2.position.set(-2, -1, 2);
    scene.add(pointLight2);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      material.uniforms.uTime.value = t;

      mesh.rotation.y = t * 0.4;
      mesh.rotation.x = t * 0.2;

      // Animate lights
      pointLight.position.x = Math.sin(t) * 3.0;
      pointLight.position.y = Math.cos(t * 1.3) * 2.0 + 1.5;

      pointLight2.position.x = Math.cos(t * 0.9) * 3.0;
      pointLight2.position.z = Math.sin(t * 1.1) * 3.0;

      controls.update();
      renderer.render(scene, camera);
    }

