</head>
<body>
  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.165.0/build/three.module.js";

    // Scene
    const scene = new THREE.Scene();
    scene.fog = new THREE.Fog(0x000000, 10, 30);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 1.5, 5);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(1, 0.35, 160, 32);

    // Custom shader material
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00c3ff) },
        uColorB: { value: new THREE.Color(0xff0080) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPos;

        void main() {
          vec3 pos = position;

          // subtle wobble
          pos += normal * sin(uTime + position.y * 4.0) * 0.05;

          vNormal = normalMatrix * normal;
          vPos = (modelMatrix * vec4(pos, 1.0)).xyz;

          gl_Position = projectionMatrix * viewMatrix * modelMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        precision highp float;

        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vNormal;
        varying vec3 vPos;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 lightDir = normalize(vec3(0.5, 1.0, 0.8));

          float diff = max(dot(n, lightDir), 0.0);
          float fresnel = pow(1.0 - max(dot(n, normalize(-vPos)), 0.0), 3.0);

          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPos.y * 3.0);

          vec3 base = mix(uColorA, uColorB, pulse);
          vec3 color = base * (0.2 + 0.8 * diff) + fresnel * vec3(1.0);

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambient);

    const pointLight = new THREE.PointLight(0xffffff, 60, 50);
    scene.add(pointLight);

    const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.2);
    scene.add(pointLightHelper);

    // Ground
    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(20, 20),
      new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 1 })
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -1.8;
    scene.add(floor);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      const t = clock.getElapsedTime();

      material.uniforms.uTime.value = t;

      mesh.rotation.x = t * 0.4;
      mesh.rotation.y = t * 0.7;

      pointLight.position.set(
        Math.sin(t * 1.2) * 3,
        2 + Math.sin(t * 2.0) * 1.0,
        Math.cos(t * 1.2) * 3
      );

      camera.position.x = Math.sin(t * 0.25) * 0.8;
      camera.lookAt(mesh.position);

      renderer.render(scene, camera);
      requestAnimationFrame(animate);
    }

    animate();

    // Resize
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
