  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Minimal 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070f);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 1.5, 5);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.3);
    scene.add(ambient);

    const pointLight = new THREE.PointLight(0x66aaff, 2, 20);
    pointLight.position.set(2, 2, 2);
    scene.add(pointLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
    directionalLight.position.set(-1, 2, 1);
    scene.add(directionalLight);

    // Shader material
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalMatrix * normal;
          vPosition = position;

          vec3 pos = position;
          pos += normal * sin(uTime + position.y * 4.0) * 0.08;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 lightDir = normalize(vec3(0.5, 0.8, 0.3));
          float diff = max(dot(normalize(vNormal), lightDir), 0.0);

          vec3 base = vec3(
            0.3 + 0.2 * sin(uTime + vPosition.x * 2.0),
            0.5 + 0.2 * sin(uTime + vPosition.y * 2.0),
            0.9
          );

          vec3 color = base * (0.25 + diff * 0.95);
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Object
    const geometry = new THREE.TorusKnotGeometry(1, 0.35, 180, 24);
    const object = new THREE.Mesh(geometry, shaderMaterial);
    scene.add(object);

    // Ground
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(20, 20),
      new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 1.0, metalness: 0.0 })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.8;
    scene.add(ground);

    // Resize
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = t;

      object.rotation.y = t * 0.4;
      object.rotation.x = t * 0.2;

      pointLight.position.x = Math.sin(t) * 3.0;
      pointLight.position.z = Math.cos(t) * 3.0;
      pointLight.position.y = 2.0 + Math.sin(t * 1.7) * 0.5;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();
  </script>
