  <script src="https://unpkg.com/three@0.160.0/build/three.min.js"></script>
  <script src="https://unpkg.com/three@0.160.0/examples/js/controls/OrbitControls.js"></script>

  <script>
    let scene, camera, renderer, controls, mesh, light;

    init();
    animate();

    function init() {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x101018);

      camera = new THREE.PerspectiveCamera(
        60,
        window.innerWidth / window.innerHeight,
        0.1,
        100
      );
      camera.position.set(0, 1.5, 4);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(window.devicePixelRatio);
      document.body.appendChild(renderer.domElement);

      controls = new THREE.OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;

      // Geometry
      const geometry = new THREE.TorusKnotGeometry(0.8, 0.25, 128, 24);

      // Custom shader material
      const material = new THREE.ShaderMaterial({
        uniforms: {
          time: { value: 0.0 },
          lightPos: { value: new THREE.Vector3(2, 2, 2) }
        },
        vertexShader: `
          varying vec3 vNormal;
          varying vec3 vWorldPos;

          void main() {
            vNormal = normalize(normalMatrix * normal);
            vec4 worldPos = modelMatrix * vec4(position, 1.0);
            vWorldPos = worldPos.xyz;
            gl_Position = projectionMatrix * viewMatrix * worldPos;
          }
        `,
        fragmentShader: `
          uniform float time;
          uniform vec3 lightPos;
          varying vec3 vNormal;
          varying vec3 vWorldPos;

          void main() {
            vec3 N = normalize(vNormal);
            vec3 L = normalize(lightPos - vWorldPos);
            float diff = max(dot(N, L), 0.0);

            float pulse = 0.5 + 0.5 * sin(time * 2.0 + vWorldPos.y * 5.0);
            vec3 baseColor = mix(vec3(0.1, 0.3, 1.0), vec3(1.0, 0.2, 0.6), pulse);

            vec3 color = baseColor * (0.2 + diff * 0.8);
            gl_FragColor = vec4(color, 1.0);
          }
        `
      });

      mesh = new THREE.Mesh(geometry, material);
      scene.add(mesh);

      // Lighting surrogate: dynamic point light visible in shader via uniform
      light = new THREE.PointLight(0xffffff, 2.0, 20);
      light.position.set(2, 2, 2);
      scene.add(light);

      // Optional helper
      const lightHelper = new THREE.PointLightHelper(light, 0.1);
      scene.add(lightHelper);

      window.addEventListener('resize', onWindowResize);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    }

    function animate(time = 0) {
      requestAnimationFrame(animate);

      const t = time * 0.001;
      mesh.rotation.x = t * 0.4;
      mesh.rotation.y = t * 0.6;

      // Move light dynamically
      light.position.x = Math.sin(t * 1.2) * 3.0;
      light.position.y = Math.cos(t * 0.9) * 2.0 + 1.5;
      light.position.z = Math.cos(t * 1.1) * 3.0;

      mesh.material.uniforms.time.value = t;
      mesh.material.uniforms.lightPos.value.copy(light.position);

      controls.update();
      renderer.render(scene, camera);
    }
  </script>
