          vUv = uv;
          vNormal = normalize(normalMatrix * normal);
          vec4 worldPos = modelMatrix * vec4(position, 1.0);
          vWorldPos = worldPos.xyz;
          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));
          float diff = max(dot(normalize(vNormal), lightDir), 0.0);

          float wave = 0.5 + 0.5 * sin(10.0 * vUv.x + uTime * 3.0)
                              * cos(10.0 * vUv.y - uTime * 2.0);

          vec3 baseColor = mix(vec3(0.1, 0.3, 1.0), vec3(1.0, 0.2, 0.7), wave);
          vec3 color = baseColor * (0.25 + 0.75 * diff);

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1, 64, 64),
      shaderMat
    );
    sphere.position.y = 1.2;
    scene.add(sphere);

    // Additional mesh for lighting reference
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({
        color: 0xdddddd,
        metalness: 0.5,
        roughness: 0.4
      })
    );
    box.position.set(-2, 0.5, 0);
    scene.add(box);

    // Resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      uniforms.uTime.value = t;

      sphere.rotation.y = t * 0.6;
      box.rotation.x = t * 0.5;
      box.rotation.y = t * 0.8;

      movingLight.position.set(
        Math.sin(t) * 4,
        2 + Math.sin(t * 2) * 1.0,
        Math.cos(t) * 4
      );

      controls.update();
      renderer.render(scene, camera);
    }

    animate();
  </script>
</body>
