<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Minimal 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
