## 1) Single-file example

Save this as `index.html` and open it through a local web server.

> If you open it directly from disk, some browsers may block module loading. Use a local server like `npx serve`, `python -m http.server`, etc.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
    }
    canvas {
      display: block;
    }
    #info {
      position: absolute;
      top: 10px;
      left: 10px;
      color: white;
      font-family: sans-serif;
      background: rgba(0,0,0,0.4);
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div id="info">Drag to orbit • Scroll to zoom • Dynamic light + shader</div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070d);
    scene.fog = new THREE.Fog(0x05070d, 10, 30);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2, 6);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.physicallyCorrectLights = true;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Geometry
    const geometry = new THREE.IcosahedronGeometry(1.2, 64);

    // Shader material with dynamic lighting
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uLightPos: { value: new THREE.Vector3(2, 2, 2) },
        uBaseColor: { value: new THREE.Color(0x4da3ff) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vec3 pos = position;

          // Small animation for the surface
          float wave = sin(pos.y * 8.0 + uTime * 2.0) * 0.04;
          pos += normal * wave;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPos = worldPos.xyz;
          vNormal = normalize(mat3(modelMatrix) * normal);

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        precision highp float;

        uniform float uTime;
        uniform vec3 uLightPos;
        uniform vec3 uBaseColor;

        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vec3 N = normalize(vNormal);
          vec3 L = normalize(uLightPos - vWorldPos);
          vec3 V = normalize(cameraPosition - vWorldPos);
          vec3 H = normalize(L + V);

          float diff = max(dot(N, L), 0.0);
          float spec = pow(max(dot(N, H), 0.0), 64.0);

          // Simple fresnel for a more "shader-like" look
          float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

          vec3 ambient = 0.12 * uBaseColor;
          vec3 diffuse = diff * uBaseColor;
          vec3 specular = spec * vec3(1.0);
          vec3 edgeGlow = fresnel * vec3(0.35, 0.6, 1.0);

          // Subtle animated color shift
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0);
          vec3 color = ambient + diffuse + specular + edgeGlow * (0.3 + 0.2 * pulse);

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Ground plane for reference
    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(30, 30),
      new THREE.MeshStandardMaterial({ color: 0x10131a, roughness: 1.0, metalness: 0.0 })
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -1.8;
    scene.add(floor);

    // Lights for floor and general scene
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.15);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0x66aaff, 40, 20);
    scene.add(pointLight);

    // Small visible light marker
    const lightMarker = new THREE.Mesh(
      new THREE.SphereGeometry(0.08, 16, 16),
      new THREE.MeshBasicMaterial({ color: 0x66aaff })
    );
    scene.add(lightMarker);

    // Animate
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Rotate the mesh
      mesh.rotation.y = t * 0.4;
      mesh.rotation.x = Math.sin(t * 0.3) * 0.15;

      // Move the light in a circle
      const lx = Math.sin(t * 1.2) * 3.0;
      const ly = 1.5 + Math.sin(t * 2.0) * 0.8;
      const lz = Math.cos(t * 1.2) * 3.0;

      pointLight.position.set(lx, ly, lz);
      lightMarker.position.copy(pointLight.position);

      material.uniforms.uTime.value = t;
      material.uniforms.uLightPos.value.copy(pointLight.position);

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
```

