          pos += normal * sin(uTime + position.y * 5.0) * 0.08;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 n = normalize(vNormal);
          float light = dot(n, normalize(vec3(0.4, 0.8, 0.6))) * 0.5 + 0.5;

          float wave = sin(vUv.x * 10.0 + uTime * 2.0) * 0.5 + 0.5;
          vec3 base = mix(uColorA, uColorB, wave);

          vec3 color = base * light;
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Mesh
    const geometry = new THREE.TorusKnotGeometry(0.9, 0.3, 128, 16);
    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    // Animate
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      material.uniforms.uTime.value = t;

      mesh.rotation.x = t * 0.35;
      mesh.rotation.y = t * 0.6;

      pointLight.position.x = Math.cos(t) * 3.0;
      pointLight.position.z = Math.sin(t) * 3.0;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
