    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -1;
    scene.add(floor);

    // Standard cube
    const cubeGeo = new THREE.BoxGeometry(1, 1, 1);
    const cubeMat = new THREE.MeshStandardMaterial({ color: 0x44aa88, metalness: 0.2, roughness: 0.4 });
    const cube = new THREE.Mesh(cubeGeo, cubeMat);
    cube.position.x = -1.5;
    scene.add(cube);

    // Shader sphere
    const sphereGeo = new THREE.SphereGeometry(0.75, 64, 64);
    const shaderMat = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0xff00aa) }
      },
      vertexShader: `
