    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";

    // Scene
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x050816);

    // Camera
    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 1.5, 4);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(0.8, 0.25, 180, 24);

    // Custom shader material
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColor: { value: new THREE.Color(0x66ccff) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vUv = uv;
          vNormal = normalMatrix * normal;
          vec3 pos = position;

          // Subtle vertex wobble
          pos += normal * sin(uTime + position.y * 6.0) * 0.05;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColor;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 lightDir = normalize(vec3(0.5, 1.0, 0.3));
          float diff = max(dot(normalize(vNormal), lightDir), 0.0);

          // Simple Fresnel-style glow
          vec3 viewDir = normalize(cameraPosition - vPosition);
          float fresnel = pow(1.0 - max(dot(normalize(vNormal), viewDir), 0.0), 3.0);

          // Animated color shift
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0);

          vec3 base = uColor * (0.35 + 0.65 * diff);
          vec3 glow = vec3(0.2, 0.6, 1.0) * fresnel * (0.5 + pulse);

          gl_FragColor = vec4(base + glow, 1.0);
        }
      `
    });

    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

