<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
    }
    canvas {
      display: block;
    }
    #info {
      position: absolute;
      top: 10px;
      left: 10px;
      color: white;
      font-family: Arial, sans-serif;
      background: rgba(0,0,0,0.4);
      padding: 8px 10px;
      border-radius: 6px;
      z-index: 1;
    }
  </style>
</head>
<body>
  <div id="info">Drag to orbit · Scroll to zoom</div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    let scene, camera, renderer, controls, mesh, light, pointLight;
    const clock = new THREE.Clock();

    init();
    animate();

    function init() {
      scene = new THREE.Scene();
      scene.background = new THREE.Color(0x05070d);

      camera = new THREE.PerspectiveCamera(
        60,
        window.innerWidth / window.innerHeight,
        0.1,
        100
      );
      camera.position.set(0, 1.5, 4);

      renderer = new THREE.WebGLRenderer({ antialias: true });
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      document.body.appendChild(renderer.domElement);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;

      // Ground
      const ground = new THREE.Mesh(
        new THREE.PlaneGeometry(20, 20),
        new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 1 })
      );
      ground.rotation.x = -Math.PI / 2;
      ground.position.y = -1.2;
      scene.add(ground);

      // Geometry
      const geometry = new THREE.TorusKnotGeometry(0.8, 0.25, 180, 32);

      // Custom shader-ish material using onBeforeCompile
      const material = new THREE.MeshStandardMaterial({
        color: 0x4cc9f0,
        metalness: 0.7,
        roughness: 0.25
      });

      material.onBeforeCompile = (shader) => {
        shader.uniforms.uTime = { value: 0 };

        shader.vertexShader = shader.vertexShader.replace(
          '#include <begin_vertex>',
          `
          #include <begin_vertex>
          transformed += normal * sin(position.y * 10.0 + uTime * 3.0) * 0.03;
          `
        );

        shader.fragmentShader = shader.fragmentShader.replace(
          '#include <dithering_fragment>',
          `
          float pulse = 0.08 * sin(uTime * 2.0 + gl_FragCoord.y * 0.02);
          gl_FragColor.rgb += pulse;
          #include <dithering_fragment>
          `
        );

        material.userData.shader = shader;
      };

      mesh = new THREE.Mesh(geometry, material);
      scene.add(mesh);

      // Lights
      const ambient = new THREE.AmbientLight(0xffffff, 0.25);
      scene.add(ambient);

      light = new THREE.DirectionalLight(0xffffff, 1.2);
      light.position.set(3, 5, 2);
      scene.add(light);

      pointLight = new THREE.PointLight(0xff3366, 2, 10);
      scene.add(pointLight);

      // Helpers
      const dirHelper = new THREE.DirectionalLightHelper(light, 0.5);
      scene.add(dirHelper);

      window.addEventListener("resize", onWindowResize);
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    }

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      mesh.rotation.y = t * 0.5;
      mesh.rotation.x = t * 0.25;

      light.position.x = Math.sin(t) * 4;
      light.position.z = Math.cos(t) * 4;

      pointLight.position.set(
        Math.sin(t * 1.7) * 2,
        1 + Math.sin(t * 2.3) * 0.7,
        Math.cos(t * 1.7) * 2
      );

      if (mesh.material.userData.shader) {
        mesh.material.userData.shader.uniforms.uTime.value = t;
      }

      controls.update();
      renderer.render(scene, camera);
    }
  </script>
</body>
</html>
