UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    RootPrimitive = Cast<UPrimitiveComponent>(GetOwner()->GetRootComponent());
}

void UCustomPhysicsComponent::AddForce(FVector Force)
{
    AccumulatedForce += Force;
}

void UCustomPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!RootPrimitive || Mass <= 0.0f)
    {
        AccumulatedForce = FVector::ZeroVector;
        return;
    }

    FVector Acceleration = AccumulatedForce / Mass;
    FVector VelocityChange = Acceleration * DeltaTime;

    RootPrimitive->AddVelocityChangeImpulse(VelocityChange);
    AccumulatedForce = FVector::ZeroVector;
}
