```cpp
// PhysicsPlugin.h
#pragma once
#include <vector>
#include <cstddef>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const {
        return Vec3(x + other.x, y + other.y, z + other.z);
    }

    Vec3 operator-(const Vec3& other) const {
        return Vec3(x - other.x, y - other.y, z - other.z);
    }

    Vec3 operator*(float s) const {
        return Vec3(x * s, y * s, z * s);
    }

    Vec3& operator+=(const Vec3& other) {
        x += other.x; y += other.y; z += other.z;
        return *this;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass = 1.0f;
    bool isStatic = false;
};

class IPhysicsPlugin {
public:
    virtual ~IPhysicsPlugin() = default;
    virtual void Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual void AddBody(const RigidBody& body) = 0;
    virtual void Step(float deltaTime) = 0;
    virtual const std::vector<RigidBody>& GetBodies() const = 0;
};
```

```cpp
// SimplePhysicsPlugin.cpp
#include "PhysicsPlugin.h"

class SimplePhysicsPlugin : public IPhysicsPlugin {
public:
    void Initialize() override {
        bodies.clear();
    }

    void Shutdown() override {
        bodies.clear();
    }

    void AddBody(const RigidBody& body) override {
        bodies.push_back(body);
    }

    void Step(float deltaTime) override {
        const Vec3 gravity(0.0f, -9.81f, 0.0f);

        for (auto& body : bodies) {
            if (body.isStatic || body.mass <= 0.0f) continue;

            // Apply gravity
            body.force += gravity * body.mass;

            // Semi-implicit Euler integration
            Vec3 acceleration = body.force * (1.0f / body.mass);
            body.velocity += acceleration * deltaTime;
            body.position += body.velocity * deltaTime;

            // Clear accumulated forces
            body.force = Vec3(0.0f, 0.0f, 0.0f);
        }
    }

    const std::vector<RigidBody>& GetBodies() const override {
        return bodies;
    }

private:
    std::vector<RigidBody> bodies;
};
```

