    gravity = g;
}

void CustomPhysicsWorld::Step(float dt) {
    for (auto* body : bodies) {
        if (!body || body->isStatic) continue;

        Vec3 acceleration = gravity + (body->force * (1.0f / body->mass));
        body->velocity += acceleration * dt;
        body->position += body->velocity * dt;

        // Clear accumulated force after integration
        body->force = Vec3(0, 0, 0);
    }
}
