## 2) Physics world implementation

```cpp
// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"
#include <cmath>

PhysicsWorld::PhysicsWorld()
    : m_nextId(1)
    , m_gravity(0.0f, -9.81f, 0.0f)
    , m_fixedDt(1.0f / 60.0f)
    , m_accumulator(0.0f)
    , m_listener(nullptr)
{
}

EntityId PhysicsWorld::CreateBody(const RigidBodyDesc& desc)
{
    RigidBody body;
    body.id = m_nextId++;
    body.mass = desc.isStatic ? 0.0f : (desc.mass <= 0.0f ? 1.0f : desc.mass);
    body.invMass = (body.mass > 0.0f) ? 1.0f / body.mass : 0.0f;
    body.position = desc.position;
    body.velocity = desc.velocity;
    body.isStatic = desc.isStatic;

    m_bodies[body.id] = body;
    return body.id;
}

void PhysicsWorld::DestroyBody(EntityId id)
{
    m_bodies.erase(id);
}

void PhysicsWorld::SetGravity(const Vec3& g)
{
    m_gravity = g;
}

void PhysicsWorld::SetFixedTimeStep(float dt)
{
    m_fixedDt = dt > 0.0f ? dt : (1.0f / 60.0f);
}

void PhysicsWorld::SetEventListener(IPhysicsEventListener* listener)
{
    m_listener = listener;
}

const RigidBody* PhysicsWorld::GetBody(EntityId id) const
{
    auto it = m_bodies.find(id);
    if (it == m_bodies.end())
        return nullptr;
    return &it->second;
}

void PhysicsWorld::Step(float deltaTime)
{
    m_accumulator += deltaTime;

    while (m_accumulator >= m_fixedDt)
    {
        for (auto& pair : m_bodies)
        {
            IntegrateBody(pair.second, m_fixedDt);
        }

        DetectAndResolveCollisions();
        m_accumulator -= m_fixedDt;
    }
}

void PhysicsWorld::IntegrateBody(RigidBody& body, float dt)
{
    if (body.isStatic)
        return;

    // Apply gravity
    body.forceAccum += m_gravity * body.mass;

    // Semi-implicit Euler integration
    Vec3 acceleration = body.forceAccum * body.invMass;
    body.velocity += acceleration * dt;
    body.position += body.velocity * dt;

    // Reset forces
    body.forceAccum = Vec3(0, 0, 0);
}
