## 3) Very basic collision detection and resolution

This is a minimal example using **sphere-like bodies** with a fixed radius for simplicity.

```cpp
static float kDefaultRadius = 0.5f;

void PhysicsWorld::DetectAndResolveCollisions()
{
    std::vector<EntityId> ids;
    ids.reserve(m_bodies.size());

    for (const auto& pair : m_bodies)
        ids.push_back(pair.first);

    for (size_t i = 0; i < ids.size(); ++i)
    {
        for (size_t j = i + 1; j < ids.size(); ++j)
        {
            RigidBody& a = m_bodies[ids[i]];
            RigidBody& b = m_bodies[ids[j]];

            Vec3 delta = b.position - a.position;
            float distSq = LengthSq(delta);
            float radiusSum = kDefaultRadius + kDefaultRadius;

            if (distSq < radiusSum * radiusSum)
            {
                float dist = sqrtf(std::max(distSq, 0.000001f));
                Vec3 normal = (dist > 0.000001f) ? (delta * (1.0f / dist)) : Vec3(0, 1, 0);
                float penetration = radiusSum - dist;

                ResolveCollision(a, b, normal, penetration);

                if (m_listener)
                {
                    CollisionInfo info;
                    info.a = a.id;
                    info.b = b.id;
                    info.normal = normal;
                    info.penetration = penetration;
                    m_listener->OnCollision(info);
                }
            }
        }
    }
}

void PhysicsWorld::ResolveCollision(RigidBody& a, RigidBody& b, const Vec3& normal, float penetration)
{
    float invMassSum = a.invMass + b.invMass;
    if (invMassSum <= 0.0f)
        return;

    // Positional correction
    const float percent = 0.8f;
    const float slop = 0.01f;
    float correctionMag = std::max(penetration - slop, 0.0f) / invMassSum * percent;
    Vec3 correction = normal * correctionMag;

    if (!a.isStatic)
        a.position -= correction * a.invMass;
    if (!b.isStatic)
        b.position += correction * b.invMass;

    // Relative velocity
    Vec3 relativeVel = b.velocity - a.velocity;
    float velAlongNormal = Dot(relativeVel, normal);

    // Bodies separating
    if (velAlongNormal > 0.0f)
        return;

    // Restitution
    float restitution = 0.3f;
    float impulseScalar = -(1.0f + restitution) * velAlongNormal;
    impulseScalar /= invMassSum;

    Vec3 impulse = normal * impulseScalar;

    if (!a.isStatic)
        a.velocity -= impulse * a.invMass;
    if (!b.isStatic)
        b.velocity += impulse * b.invMass;
}
