## 4) Basic Physics World Implementation

```cpp
namespace CustomPhysics
{
    class PhysicsWorld : public IPhysicsWorld
    {
    public:
        PhysicsWorld()
        {
            gravity = { 0.0f, -9.81f, 0.0f };
        }

        BodyId CreateBody(const RigidBody& body) override
        {
            BodyId id = ++nextId;
            RigidBody copy = body;
            copy.id = id;
            copy.SetStatic(copy.isStatic);
            if (!copy.isStatic && copy.mass <= 0.f)
                copy.SetMass(1.0f);

            bodies[id] = copy;
            return id;
        }

        void DestroyBody(BodyId id) override
        {
            bodies.erase(id);
        }

        RigidBody* GetBody(BodyId id) override
        {
            auto it = bodies.find(id);
            return (it != bodies.end()) ? &it->second : nullptr;
        }

        void StepSimulation(float dt) override
        {
            if (dt <= 0.0f) return;

            // Integrate forces
            for (auto& [id, body] : bodies)
            {
                if (!body.enabled || body.isStatic)
                    continue;

                Vec3 accel = gravity;
                accel += body.accumulatedForce * body.invMass;

                body.velocity += accel * dt;
                body.position += body.velocity * dt;

                body.accumulatedForce = { 0, 0, 0 };
            }

            // Naive collision pass (sphere-sphere only)
            ResolveSphereSphereCollisions();
        }

        void SetGravity(const Vec3& g) { gravity = g; }

    private:
        std::unordered_map<BodyId, RigidBody> bodies;
        BodyId nextId = 0;
        Vec3 gravity;

        void ResolveSphereSphereCollisions()
        {
            for (auto itA = bodies.begin(); itA != bodies.end(); ++itA)
            {
                auto itB = itA;
                ++itB;

                for (; itB != bodies.end(); ++itB)
                {
                    RigidBody& a = itA->second;
                    RigidBody& b = itB->second;

                    if (!a.enabled || !b.enabled)
                        continue;

                    if (a.colliderType != ColliderType::Sphere || b.colliderType != ColliderType::Sphere)
                        continue;

                    Vec3 delta = b.position - a.position;
                    float distSq = LengthSquared(delta);
                    float radiusSum = a.sphere.radius + b.sphere.radius;

                    if (distSq >= radiusSum * radiusSum)
                        continue;

                    float dist = std::sqrt(std::max(distSq, 1e-6f));
                    Vec3 normal = (dist > 1e-6f) ? delta / dist : Vec3{ 0, 1, 0 };
                    float penetration = radiusSum - dist;

                    float totalInvMass = a.invMass + b.invMass;
                    if (totalInvMass <= 0.0f)
                        continue;

                    // Positional correction
                    Vec3 correction = normal * (penetration / totalInvMass);
                    if (!a.isStatic) a.position -= correction * a.invMass;
                    if (!b.isStatic) b.position += correction * b.invMass;

                    // Velocity impulse (very basic restitution model)
                    float relativeVel = Dot(b.velocity - a.velocity, normal);
                    if (relativeVel > 0.0f)
                        continue;

                    float restitution = 0.2f;
                    float j = -(1.0f + restitution) * relativeVel;
                    j /= totalInvMass;

                    Vec3 impulse = normal * j;
                    if (!a.isStatic) a.velocity -= impulse * a.invMass;
                    if (!b.isStatic) b.velocity += impulse * b.invMass;
                }
            }
        }
    };
}
```

