## 5) Plugin Entry Point

This is where you connect the physics plugin to your engine’s plugin system.

```cpp
namespace CustomPhysics
{
    class PhysicsPlugin
    {
    public:
        bool Initialize()
        {
            world = std::make_unique<PhysicsWorld>();
            return true;
        }

        void Shutdown()
        {
            world.reset();
        }

        void Tick(float deltaTime)
        {
            if (world)
                world->StepSimulation(deltaTime);
        }

        IPhysicsWorld* GetWorld()
        {
            return world.get();
        }

    private:
        std::unique_ptr<IPhysicsWorld> world;
    };
}
