## 5) Basic physics body implementation

This is a minimal placeholder body. In a real plugin, this would wrap your actual solver object.

```cpp
// PhysicsBody.cpp

#include "IPhysicsBody.h"

class PhysicsBody : public IPhysicsBody
{
public:
    PhysicsBody(int id, BodyType type, const Transform& t, float mass)
        : m_id(id), m_type(type), m_transform(t), m_mass(mass)
    {
    }

    int GetId() const override { return m_id; }
    BodyType GetBodyType() const override { return m_type; }

    void SetTransform(const Transform& t) override
    {
        m_transform = t;
    }

    Transform GetTransform() const override
    {
        return m_transform;
    }

    void SetLinearVelocity(const Vec3& v) override
    {
        m_velocity = v;
    }

    Vec3 GetLinearVelocity() const override
    {
        return m_velocity;
    }

    void ApplyForce(const Vec3& force) override
    {
        m_forceAccum = Add(m_forceAccum, force);
    }

    void ApplyImpulse(const Vec3& impulse) override
    {
        if (m_mass > 0.0f)
        {
            m_velocity.x += impulse.x / m_mass;
            m_velocity.y += impulse.y / m_mass;
            m_velocity.z += impulse.z / m_mass;
        }
    }

    void SetMass(float mass) override
    {
        m_mass = mass;
    }

    float GetMass() const override
    {
        return m_mass;
    }

    void Integrate(float dt, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic || m_mass <= 0.0f)
            return;

        Vec3 acceleration = gravity;
        acceleration.x += m_forceAccum.x / m_mass;
        acceleration.y += m_forceAccum.y / m_mass;
        acceleration.z += m_forceAccum.z / m_mass;

        m_velocity.x += acceleration.x * dt;
        m_velocity.y += acceleration.y * dt;
        m_velocity.z += acceleration.z * dt;

        m_transform.position.x += m_velocity.x * dt;
        m_transform.position.y += m_velocity.y * dt;
        m_transform.position.z += m_velocity.z * dt;

        m_forceAccum = {0, 0, 0};
    }

private:
    Vec3 Add(const Vec3& a, const Vec3& b)
    {
        return {a.x + b.x, a.y + b.y, a.z + b.z};
    }

private:
    int m_id;
    BodyType m_type;
    Transform m_transform;
    Vec3 m_velocity{0, 0, 0};
    Vec3 m_forceAccum{0, 0, 0};
    float m_mass;
};
```

