## 8) Engine update loop integration

Typical fixed timestep loop:

```cpp
// PhysicsSystem.h

#pragma once
#include <memory>

class IPhysicsWorld;

class PhysicsSystem
{
public:
    void SetWorld(std::shared_ptr<IPhysicsWorld> world);
    void Update(float deltaTime);

    void SetFixedTimeStep(float step) { m_fixedStep = step; }

private:
    std::shared_ptr<IPhysicsWorld> m_world;
    float m_accumulator = 0.0f;
    float m_fixedStep = 1.0f / 60.0f;
};
```

```cpp
// PhysicsSystem.cpp

#include "PhysicsSystem.h"
#include "IPhysicsWorld.h"

void PhysicsSystem::SetWorld(std::shared_ptr<IPhysicsWorld> world)
{
    m_world = world;
}

void PhysicsSystem::Update(float deltaTime)
{
    if (!m_world)
        return;

    m_accumulator += deltaTime;

    while (m_accumulator >= m_fixedStep)
    {
        m_world->StepSimulation(m_fixedStep);
        m_accumulator -= m_fixedStep;
    }
}
```

