## 3) Minimal implementation sketch

### `physics_world.h`
```cpp
#pragma once
#include <vector>

struct Vec3
{
    float x, y, z;
};

struct Transform
{
    Vec3 position;
    Vec3 rotation;   // Euler for simplicity
    Vec3 scale;
};

struct RigidBodyDesc
{
    float mass = 1.0f;
    bool isStatic = false;
    Transform initialTransform{};
};

class RigidBody
{
public:
    explicit RigidBody(const RigidBodyDesc& desc);

    void AddForce(const Vec3& force);
    void Integrate(float dt);

    const Transform& GetTransform() const;
    void SetTransform(const Transform& t);

private:
    Transform transform_{};
    Vec3 velocity_{0,0,0};
    Vec3 accumulatedForce_{0,0,0};
    float mass_ = 1.0f;
    bool isStatic_ = false;
};

class PhysicsWorld
{
public:
    void Initialize();
    void Shutdown();

    RigidBody* CreateRigidBody(const RigidBodyDesc& desc);
    void DestroyRigidBody(RigidBody* body);

    void StepSimulation(float dt);

private:
    std::vector<RigidBody*> bodies_;
};
```

---

### `physics_world.cpp`
```cpp
#include "physics_world.h"
#include <algorithm>

static Vec3 operator+(const Vec3& a, const Vec3& b) { return {a.x+b.x, a.y+b.y, a.z+b.z}; }
static Vec3 operator-(const Vec3& a, const Vec3& b) { return {a.x-b.x, a.y-b.y, a.z-b.z}; }
static Vec3 operator*(const Vec3& a, float s) { return {a.x*s, a.y*s, a.z*s}; }

RigidBody::RigidBody(const RigidBodyDesc& desc)
    : transform_(desc.initialTransform),
      mass_(desc.mass > 0.0f ? desc.mass : 1.0f),
      isStatic_(desc.isStatic)
{
}

void RigidBody::AddForce(const Vec3& force)
{
    if (isStatic_) return;
    accumulatedForce_ = accumulatedForce_ + force;
}

void RigidBody::Integrate(float dt)
{
    if (isStatic_) return;

    // Basic Euler integration
    Vec3 acceleration{
        accumulatedForce_.x / mass_,
        accumulatedForce_.y / mass_,
        accumulatedForce_.z / mass_
    };

    velocity_ = velocity_ + (acceleration * dt);
    transform_.position = transform_.position + (velocity_ * dt);

    accumulatedForce_ = {0,0,0};
}

const Transform& RigidBody::GetTransform() const
{
    return transform_;
}

void RigidBody::SetTransform(const Transform& t)
{
    transform_ = t;
}

void PhysicsWorld::Initialize()
{
    bodies_.clear();
}

void PhysicsWorld::Shutdown()
{
    for (auto* body : bodies_)
        delete body;
    bodies_.clear();
}

RigidBody* PhysicsWorld::CreateRigidBody(const RigidBodyDesc& desc)
{
    auto* body = new RigidBody(desc);
    bodies_.push_back(body);
    return body;
}

void PhysicsWorld::DestroyRigidBody(RigidBody* body)
{
    auto it = std::find(bodies_.begin(), bodies_.end(), body);
    if (it != bodies_.end())
    {
        delete *it;
        bodies_.erase(it);
    }
}

void PhysicsWorld::StepSimulation(float dt)
{
    for (auto* body : bodies_)
        body->Integrate(dt);
}
