### `RigidBody.cpp`
```cpp
#include "RigidBody.h"

static const Vector3 kGravity(0.0f, -9.81f, 0.0f);

RigidBody::RigidBody()
    : position()
    , velocity()
    , accumulatedForces()
    , mass(1.0f)
    , inverseMass(1.0f)
    , useGravity(true)
{
}

void RigidBody::SetMass(float newMass)
{
    mass = newMass;
    inverseMass = (mass > 0.0f) ? (1.0f / mass) : 0.0f;
}

float RigidBody::GetMass() const
{
    return mass;
}

void RigidBody::SetPosition(const Vector3& newPosition)
{
    position = newPosition;
}

const Vector3& RigidBody::GetPosition() const
{
    return position;
}

void RigidBody::SetVelocity(const Vector3& newVelocity)
{
    velocity = newVelocity;
}

const Vector3& RigidBody::GetVelocity() const
{
    return velocity;
}

void RigidBody::ApplyForce(const Vector3& force)
{
    accumulatedForces += force;
}

void RigidBody::ClearForces()
{
    accumulatedForces = Vector3();
}

void RigidBody::SetUseGravity(bool enabled)
{
    useGravity = enabled;
}

void RigidBody::Integrate(float deltaTime)
{
    if (inverseMass <= 0.0f) return;

    Vector3 acceleration = accumulatedForces * inverseMass;
    if (useGravity)
        acceleration += kGravity;

    velocity += acceleration * deltaTime;
    position += velocity * deltaTime;

    ClearForces();
}
```

