```cpp
// RigidBody.cpp
#include "RigidBody.h"

RigidBody::RigidBody(const RigidBodyDesc& desc)
    : m_position(desc.position),
      m_velocity(desc.velocity),
      m_forceAccum(desc.force),
      m_mass(desc.isStatic ? 0.0f : desc.mass),
      m_invMass((!desc.isStatic && desc.mass > 0.0f) ? 1.0f / desc.mass : 0.0f),
      m_restitution(desc.restitution),
      m_isStatic(desc.isStatic)
{
}

void RigidBody::AddForce(const Vec3& f)
{
    if (!m_isStatic) m_forceAccum += f;
}

void RigidBody::Integrate(float dt)
{
    if (m_isStatic || dt <= 0.0f) return;

    Vec3 acceleration = m_forceAccum * m_invMass;
    m_velocity += acceleration * dt;
    m_position += m_velocity * dt;

    m_forceAccum = {0, 0, 0};
}

void RigidBody::SetPosition(const Vec3& p) { m_position = p; }
void RigidBody::SetVelocity(const Vec3& v) { m_velocity = v; }

const Vec3& RigidBody::GetPosition() const { return m_position; }
const Vec3& RigidBody::GetVelocity() const { return m_velocity; }
float RigidBody::GetMass() const { return m_mass; }
float RigidBody::GetInverseMass() const { return m_invMass; }
bool RigidBody::IsStatic() const { return m_isStatic; }
