## 4) Physics world

This version uses a very simple gravity + ground collision model as a starting point.

```cpp
// PhysicsWorld.h
#pragma once
#include <memory>
#include <vector>
#include "RigidBody.h"

class PhysicsWorld
{
public:
    PhysicsWorld();

    std::shared_ptr<RigidBody> CreateBody(const RigidBodyDesc& desc);
    void RemoveBody(const std::shared_ptr<RigidBody>& body);

    void SetGravity(const Vec3& g);
    const Vec3& GetGravity() const;

    void Step(float dt);

private:
    void ResolveGroundCollision(RigidBody& body);

    std::vector<std::shared_ptr<RigidBody>> m_bodies;
    Vec3 m_gravity;
    float m_groundY;
};
```

```cpp
// PhysicsWorld.cpp
#include "PhysicsWorld.h"

PhysicsWorld::PhysicsWorld()
    : m_gravity(0.0f, -9.81f, 0.0f),
      m_groundY(0.0f)
{
}

std::shared_ptr<RigidBody> PhysicsWorld::CreateBody(const RigidBodyDesc& desc)
{
    auto body = std::make_shared<RigidBody>(desc);
    m_bodies.push_back(body);
    return body;
}

void PhysicsWorld::RemoveBody(const std::shared_ptr<RigidBody>& body)
{
    m_bodies.erase(
        std::remove(m_bodies.begin(), m_bodies.end(), body),
        m_bodies.end()
    );
}

void PhysicsWorld::SetGravity(const Vec3& g) { m_gravity = g; }
const Vec3& PhysicsWorld::GetGravity() const { return m_gravity; }

void PhysicsWorld::Step(float dt)
{
    for (auto& body : m_bodies)
    {
        if (!body || body->IsStatic()) continue;

        body->AddForce(m_gravity * body->GetMass());
        body->Integrate(dt);
        ResolveGroundCollision(*body);
    }
}

void PhysicsWorld::ResolveGroundCollision(RigidBody& body)
{
    Vec3 pos = body.GetPosition();
    Vec3 vel = body.GetVelocity();

    if (pos.y < m_groundY)
    {
        pos.y = m_groundY;

        if (vel.y < 0.0f)
        {
            vel.y = -vel.y * 0.2f; // simple restitution
            if (std::abs(vel.y) < 0.05f) vel.y = 0.0f;
        }

        body.SetPosition(pos);
        body.SetVelocity(vel);
    }
}
```

