### `RigidBody.cpp`
```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody(BodyType type, float mass)
        : m_type(type), m_mass(mass), m_invMass((mass > 0.0f) ? 1.0f / mass : 0.0f)
    {
    }

    BodyType RigidBody::GetType() const { return m_type; }
    float RigidBody::GetMass() const { return m_mass; }

    const PhysicsTransform& RigidBody::GetTransform() const { return m_transform; }
    void RigidBody::SetTransform(const PhysicsTransform& transform) { m_transform = transform; }

    const Vector3& RigidBody::GetVelocity() const { return m_velocity; }
    void RigidBody::SetVelocity(const Vector3& velocity) { m_velocity = velocity; }

    void RigidBody::AddForce(const Vector3& force)
    {
        m_accumulatedForce += force;
    }

    void RigidBody::ClearForces()
    {
        m_accumulatedForce = {};
    }

    void RigidBody::Integrate(float dt, const Vector3& gravity)
    {
        if (m_type == BodyType::Static)
            return;

        Vector3 acceleration = gravity;
        if (m_invMass > 0.0f)
            acceleration += m_accumulatedForce * m_invMass;

        m_velocity += acceleration * dt;
        m_transform.position += m_velocity * dt;

        ClearForces();
    }
}
