// PhysicsPlugin.h
#pragma once

#include <vector>
#include <memory>

struct Vec3 {
    float x, y, z;
};

struct Quaternion {
    float x, y, z, w;
};

struct Transform {
    Vec3 position;
    Quaternion rotation;
};

struct PhysicsMaterial {
    float friction = 0.5f;
    float restitution = 0.1f;
};

enum class ColliderType {
    Box,
    Sphere,
    Capsule,
    Mesh
};

struct ColliderDesc {
    ColliderType type;
    Vec3 dimensions;   // box extents, sphere radius in x, capsule params as needed
    PhysicsMaterial material;
    bool isTrigger = false;
};

struct RigidBodyDesc {
    float mass = 1.0f;
    bool isStatic = false;
    Transform initialTransform;
    ColliderDesc collider;
};

class IRigidBody {
public:
    virtual ~IRigidBody() = default;
    virtual void SetTransform(const Transform& t) = 0;
    virtual Transform GetTransform() const = 0;
    virtual void SetLinearVelocity(const Vec3& v) = 0;
    virtual Vec3 GetLinearVelocity() const = 0;
    virtual void ApplyForce(const Vec3& force) = 0;
};

class IPhysicsWorld {
public:
    virtual ~IPhysicsWorld() = default;
    virtual IRigidBody* CreateRigidBody(const RigidBodyDesc& desc) = 0;
    virtual void DestroyRigidBody(IRigidBody* body) = 0;
    virtual void StepSimulation(float deltaTime) = 0;
    virtual void Clear() = 0;
};
```

