// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"

// Replace this with your engine backend or chosen physics library integration.
class SimpleRigidBody : public IRigidBody {
public:
    explicit SimpleRigidBody(const RigidBodyDesc& desc)
        : transform_(desc.initialTransform),
          mass_(desc.mass),
          isStatic_(desc.isStatic) {}

    void SetTransform(const Transform& t) override { transform_ = t; }
    Transform GetTransform() const override { return transform_; }

    void SetLinearVelocity(const Vec3& v) override { linearVelocity_ = v; }
    Vec3 GetLinearVelocity() const override { return linearVelocity_; }

    void ApplyForce(const Vec3& force) override {
        if (isStatic_ || mass_ <= 0.0f) return;
        accumulatedForce_.x += force.x;
        accumulatedForce_.y += force.y;
        accumulatedForce_.z += force.z;
    }

    void Integrate(float dt) {
        if (isStatic_ || mass_ <= 0.0f) return;

        Vec3 accel{
            accumulatedForce_.x / mass_,
            accumulatedForce_.y / mass_,
            accumulatedForce_.z / mass_
        };

        linearVelocity_.x += accel.x * dt;
        linearVelocity_.y += accel.y * dt;
        linearVelocity_.z += accel.z * dt;

        transform_.position.x += linearVelocity_.x * dt;
        transform_.position.y += linearVelocity_.y * dt;
        transform_.position.z += linearVelocity_.z * dt;

        accumulatedForce_ = {0, 0, 0};
    }

private:
    Transform transform_{};
    Vec3 linearVelocity_{0, 0, 0};
    Vec3 accumulatedForce_{0, 0, 0};
    float mass_ = 1.0f;
    bool isStatic_ = false;
};

class SimplePhysicsWorld : public IPhysicsWorld {
public:
    IRigidBody* CreateRigidBody(const RigidBodyDesc& desc) override {
        bodies_.push_back(std::make_unique<SimpleRigidBody>(desc));
        return bodies_.back().get();
    }

    void DestroyRigidBody(IRigidBody* body) override {
        for (auto it = bodies_.begin(); it != bodies_.end(); ++it) {
            if (it->get() == body) {
                bodies_.erase(it);
                return;
            }
        }
    }

    void StepSimulation(float deltaTime) override {
        for (auto& body : bodies_) {
            body->ApplyForce({0.0f, -9.81f, 0.0f}); // simple gravity
        }

        for (auto& body : bodies_) {
            static_cast<SimpleRigidBody*>(body.get())->Integrate(deltaTime);
        }

        // Collision detection/resolution would go here.
    }

    void Clear() override {
        bodies_.clear();
    }

private:
    std::vector<std::unique_ptr<IRigidBody>> bodies_;
};
