using UnityEngine;

namespace CustomPhysics
{
    [DisallowMultipleComponent]
    public class CustomPhysicsBody : MonoBehaviour
    {
        [Header("Mass Properties")]
        [Min(0.0001f)]
        public float Mass = 1.0f;

        public bool IsStatic = false;

        [Header("Velocity")]
        public Vector3 LinearVelocity;
        public Vector3 AngularVelocity;

        [Header("Damping")]
        [Range(0f, 1f)]
        public float LinearDamping = 0.01f;

        [Range(0f, 1f)]
        public float AngularDamping = 0.05f;

        [Header("Forces")]
        public Vector3 AccumulatedForce;
        public Vector3 AccumulatedTorque;

        public float InvMass => (IsStatic || Mass <= 0f) ? 0f : 1f / Mass;

        public void AddForce(Vector3 force)
        {
            if (IsStatic) return;
            AccumulatedForce += force;
        }

        public void AddImpulse(Vector3 impulse)
        {
            if (IsStatic) return;
            LinearVelocity += impulse * InvMass;
        }

        public void ClearForces()
        {
            AccumulatedForce = Vector3.zero;
            AccumulatedTorque = Vector3.zero;
        }
    }
}
