## `CustomPhysicsWorld.cs`

```csharp
using System.Collections.Generic;
using UnityEngine;

namespace CustomPhysics
{
    public class CustomPhysicsWorld : MonoBehaviour
    {
        public static CustomPhysicsWorld Instance { get; private set; }

        [Header("World Settings")]
        public Vector3 Gravity = new Vector3(0f, -9.81f, 0f);
        [Range(1, 8)]
        public int SolverIterations = 4;
        [Range(0.01f, 0.05f)]
        public float FixedTimeStep = 0.02f;

        private readonly List<CustomPhysicsBody> bodies = new List<CustomPhysicsBody>();
        private readonly List<CustomPhysicsCollider> colliders = new List<CustomPhysicsCollider>();

        private float accumulator;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }

            Instance = this;
            DontDestroyOnLoad(gameObject);
        }

        private void OnEnable()
        {
            RefreshRegistry();
        }

        private void Update()
        {
            accumulator += Time.deltaTime;

            while (accumulator >= FixedTimeStep)
            {
                Step(FixedTimeStep);
                accumulator -= FixedTimeStep;
            }
        }

        public void RefreshRegistry()
        {
            bodies.Clear();
            colliders.Clear();

            bodies.AddRange(FindObjectsOfType<CustomPhysicsBody>());
            colliders.AddRange(FindObjectsOfType<CustomPhysicsCollider>());
        }

        public void RegisterBody(CustomPhysicsBody body)
        {
            if (!bodies.Contains(body))
                bodies.Add(body);
        }

        public void UnregisterBody(CustomPhysicsBody body)
        {
            bodies.Remove(body);
        }

        public void RegisterCollider(CustomPhysicsCollider col)
        {
            if (!colliders.Contains(col))
                colliders.Add(col);
        }

        public void UnregisterCollider(CustomPhysicsCollider col)
        {
            colliders.Remove(col);
        }

        private void Step(float dt)
        {
            // Integrate forces and velocities
            for (int i = 0; i < bodies.Count; i++)
            {
                var body = bodies[i];
                if (body == null || body.IsStatic) continue;

                Vector3 acceleration = Gravity + body.AccumulatedForce * body.InvMass;
                body.LinearVelocity += acceleration * dt;

                body.LinearVelocity *= Mathf.Clamp01(1f - body.LinearDamping);
                body.AngularVelocity *= Mathf.Clamp01(1f - body.AngularDamping);

                Transform t = body.transform;
                t.position += body.LinearVelocity * dt;

                // Very basic angular integration (placeholder)
                if (body.AngularVelocity != Vector3.zero)
                {
                    Quaternion deltaRot = Quaternion.Euler(body.AngularVelocity * Mathf.Rad2Deg * dt);
                    t.rotation = deltaRot * t.rotation;
                }

                body.ClearForces();
            }

            // Collision pass (simple ground plane at y=0 for now)
            for (int i = 0; i < bodies.Count; i++)
            {
                var body = bodies[i];
                if (body == null || body.IsStatic) continue;

                ResolveGroundCollision(body);
            }
        }

        private void ResolveGroundCollision(CustomPhysicsBody body)
        {
            var col = body.GetComponent<CustomPhysicsCollider>();
            if (col == null) return;

            float bottom = GetBodyBottomY(body, col);
            if (bottom < 0f)
            {
                float penetration = -bottom;
                body.transform.position += Vector3.up * penetration;

                if (body.LinearVelocity.y < 0f)
                {
                    body.LinearVelocity.y = 0f;
                }
            }
        }

        private float GetBodyBottomY(CustomPhysicsBody body, CustomPhysicsCollider col)
        {
            Vector3 pos = body.transform.position;

            switch (col.Shape)
            {
                case CustomPhysicsCollider.ShapeType.Sphere:
                    return pos.y - col.SphereRadius;
                case CustomPhysicsCollider.ShapeType.Box:
                default:
                    return pos.y - (col.BoxSize.y * 0.5f);
            }
        }
    }
}
```

