    void AddBody(TSharedPtr<FCustomPhysicsBody> Body);
    void RemoveBody(TSharedPtr<FCustomPhysicsBody> Body);

    void StepSimulation(float DeltaTime);

private:
    void IntegrateBody(FCustomPhysicsBody& Body, float StepDt);

