### `Private/CustomPhysicsWorld.cpp`
```cpp
#include "CustomPhysicsWorld.h"

class FCustomPhysicsBody
{
public:
    FVector Position = FVector::ZeroVector;
    FVector Velocity = FVector::ZeroVector;
    FVector Force = FVector::ZeroVector;
    float Mass = 1.0f;
    bool bIsStatic = false;
};

void FCustomPhysicsWorld::Initialize(const FCustomPhysicsSettings& InSettings)
{
    Settings = InSettings;
    Accumulator = 0.0f;
}

void FCustomPhysicsWorld::Shutdown()
{
    Bodies.Empty();
}

void FCustomPhysicsWorld::AddBody(TSharedPtr<FCustomPhysicsBody> Body)
{
    Bodies.Add(Body);
}

void FCustomPhysicsWorld::RemoveBody(TSharedPtr<FCustomPhysicsBody> Body)
{
    Bodies.Remove(Body);
}

void FCustomPhysicsWorld::StepSimulation(float DeltaTime)
{
    Accumulator += DeltaTime;

    while (Accumulator >= Settings.FixedTimeStep)
    {
        for (TSharedPtr<FCustomPhysicsBody>& BodyPtr : Bodies)
        {
            if (BodyPtr.IsValid())
            {
                IntegrateBody(*BodyPtr, Settings.FixedTimeStep);
            }
        }

        Accumulator -= Settings.FixedTimeStep;
    }
}

void FCustomPhysicsWorld::IntegrateBody(FCustomPhysicsBody& Body, float StepDt)
{
    if (Body.bIsStatic || Body.Mass <= 0.0f)
    {
        return;
    }

    const FVector GravityForce(0.0f, 0.0f, Body.Mass * Settings.GravityZ);
    const FVector TotalForce = Body.Force + GravityForce;
    const FVector Acceleration = TotalForce / Body.Mass;

    Body.Velocity += Acceleration * StepDt;
    Body.Position += Body.Velocity * StepDt;

    // Clear forces after integration
    Body.Force = FVector::ZeroVector;
}
```

