    virtual void DestroyBody(BodyHandle body) = 0;

    virtual void SetBodyTransform(BodyHandle body, const Vec3& position, const Quat& rotation) = 0;
    virtual void GetBodyTransform(BodyHandle body, Vec3& outPosition, Quat& outRotation) const = 0;

