// PhysicsPlugin.cpp
#include "IPhysicsPlugin.h"
#include <unordered_map>

class PhysicsPlugin final : public IPhysicsPlugin {
public:
    bool Initialize() override {
        m_gravity = {0.0f, -9.81f, 0.0f};
        return true;
    }

    void Shutdown() override {
        m_bodies.clear();
    }

    void SetGravity(const Vec3& gravity) override {
        m_gravity = gravity;
    }

    void StepSimulation(float deltaTime) override {
        for (auto& [handle, body] : m_bodies) {
            if (body.isStatic) continue;

            body.linearVelocity.x += m_gravity.x * deltaTime;
            body.linearVelocity.y += m_gravity.y * deltaTime;
            body.linearVelocity.z += m_gravity.z * deltaTime;

            body.position.x += body.linearVelocity.x * deltaTime;
            body.position.y += body.linearVelocity.y * deltaTime;
            body.position.z += body.linearVelocity.z * deltaTime;
        }
    }

    BodyHandle CreateBody(const PhysicsBodyDesc& desc) override {
        BodyHandle handle = ++m_nextHandle;
        m_bodies.emplace(handle, desc);
        return handle;
    }

    void DestroyBody(BodyHandle body) override {
        m_bodies.erase(body);
    }

    void SetBodyTransform(BodyHandle body, const Vec3& position, const Quat& rotation) override {
        auto it = m_bodies.find(body);
        if (it == m_bodies.end()) return;
        it->second.position = position;
        it->second.rotation = rotation;
    }

    void GetBodyTransform(BodyHandle body, Vec3& outPosition, Quat& outRotation) const override {
        auto it = m_bodies.find(body);
        if (it == m_bodies.end()) return;
        outPosition = it->second.position;
        outRotation = it->second.rotation;
    }

    void ApplyForce(BodyHandle body, const Vec3& force) override {
        auto it = m_bodies.find(body);
        if (it == m_bodies.end() || it->second.isStatic) return;
        it->second.linearVelocity.x += force.x / it->second.mass;
        it->second.linearVelocity.y += force.y / it->second.mass;
        it->second.linearVelocity.z += force.z / it->second.mass;
    }

    void ApplyImpulse(BodyHandle body, const Vec3& impulse) override {
        ApplyForce(body, impulse);
    }

private:
    struct BodyState : PhysicsBodyDesc {};
    std::unordered_map<BodyHandle, BodyState> m_bodies;
    BodyHandle m_nextHandle = 0;
    Vec3 m_gravity{0.0f, -9.81f, 0.0f};
};
