## 4. Rigid Body

```cpp
// RigidBody.h
#pragma once
#include "MathTypes.h"

enum class ShapeType
{
    Sphere,
    Box
};

struct Collider
{
    ShapeType type;
    float radius;   // sphere
    Vec3 halfExtents; // box
};

struct RigidBody
{
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    float mass;
    float inverseMass;
    float restitution;
    bool isStatic;

    Collider collider;

    RigidBody()
        : position(), velocity(), forceAccum(),
          mass(1.0f), inverseMass(1.0f),
          restitution(0.5f), isStatic(false)
    {}

    void SetMass(float m)
    {
        mass = m;
        inverseMass = (m > 0.0f) ? 1.0f / m : 0.0f;
        isStatic = (m <= 0.0f);
    }

    void AddForce(const Vec3& f)
    {
        forceAccum += f;
    }

    void ClearForces()
    {
        forceAccum = Vec3(0, 0, 0);
    }
};
