## 6. Integration Step

```cpp
// PhysicsWorld.cpp
#include "PhysicsWorld.h"
#include <algorithm>

void PhysicsWorld::Integrate(RigidBody& body, float dt)
{
    if (body.isStatic || body.inverseMass <= 0.0f)
        return;

    // Acceleration from force + gravity
    Vec3 acceleration = gravity + (body.forceAccum * body.inverseMass);

    // Semi-implicit Euler
    body.velocity += acceleration * dt;
    body.position += body.velocity * dt;

    body.ClearForces();
}
```

