## 7. Collision Detection

Here’s a simple **sphere-sphere** and **sphere-box** start.

```cpp
struct Contact
{
    RigidBody* a;
    RigidBody* b;
    Vec3 normal;
    float penetration;
};

static bool SphereSphere(const RigidBody& a, const RigidBody& b, Contact& out)
{
    Vec3 delta = b.position - a.position;
    float dist = delta.Length();
    float radiusSum = a.collider.radius + b.collider.radius;

    if (dist >= radiusSum)
        return false;

    out.normal = (dist > 0.00001f) ? (delta * (1.0f / dist)) : Vec3(1, 0, 0);
    out.penetration = radiusSum - dist;
    return true;
}
```

For sphere-box, as a simple approximation:

```cpp
static float Clamp(float v, float minV, float maxV)
{
    return (v < minV) ? minV : (v > maxV ? maxV : v);
}

static bool SphereBox(const RigidBody& sphere, const RigidBody& box, Contact& out)
{
    Vec3 c = sphere.position;
    Vec3 bmin = box.position - box.collider.halfExtents;
    Vec3 bmax = box.position + box.collider.halfExtents;

    Vec3 closest(
        Clamp(c.x, bmin.x, bmax.x),
        Clamp(c.y, bmin.y, bmax.y),
        Clamp(c.z, bmin.z, bmax.z)
    );

    Vec3 delta = c - closest;
    float dist = delta.Length();

    if (dist >= sphere.collider.radius)
        return false;

    out.normal = (dist > 0.00001f) ? Normalize(delta) : Vec3(0, 1, 0);
    out.penetration = sphere.collider.radius - dist;
    return true;
}
```

