## 8. Collision Resolution

Basic impulse resolution:

```cpp
static void ResolveContact(Contact& c)
{
    RigidBody* a = c.a;
    RigidBody* b = c.b;

    float invMassA = a->inverseMass;
    float invMassB = b->inverseMass;

    if (invMassA + invMassB <= 0.0f)
        return;

    Vec3 relativeVel = b->velocity - a->velocity;
    float velAlongNormal = Dot(relativeVel, c.normal);

    if (velAlongNormal > 0.0f)
        return;

    float e = (a->restitution < b->restitution) ? a->restitution : b->restitution;

    float j = -(1.0f + e) * velAlongNormal;
    j /= (invMassA + invMassB);

    Vec3 impulse = c.normal * j;
    if (!a->isStatic) a->velocity -= impulse * invMassA;
    if (!b->isStatic) b->velocity += impulse * invMassB;

    // Positional correction
    const float percent = 0.8f; // usually 20–80%
    const float slop = 0.01f;
    float correctionMag = std::max(c.penetration - slop, 0.0f) / (invMassA + invMassB) * percent;
    Vec3 correction = c.normal * correctionMag;

    if (!a->isStatic) a->position -= correction * invMassA;
    if (!b->isStatic) b->position += correction * invMassB;
}
```

