## 9. World Step Implementation

```cpp
void PhysicsWorld::Step(float dt)
{
    // Integrate
    for (RigidBody* body : bodies)
    {
        Integrate(*body, dt);
    }

    // Very naive pairwise collision detection
    for (size_t i = 0; i < bodies.size(); ++i)
    {
        for (size_t j = i + 1; j < bodies.size(); ++j)
        {
            RigidBody* a = bodies[i];
            RigidBody* b = bodies[j];

            Contact c;
            c.a = a;
            c.b = b;

            bool hit = false;

            if (a->collider.type == ShapeType::Sphere && b->collider.type == ShapeType::Sphere)
            {
                hit = SphereSphere(*a, *b, c);
            }
            else if (a->collider.type == ShapeType::Sphere && b->collider.type == ShapeType::Box)
            {
                hit = SphereBox(*a, *b, c);
            }
            else if (a->collider.type == ShapeType::Box && b->collider.type == ShapeType::Sphere)
            {
                hit = SphereBox(*b, *a, c);
                c.normal = c.normal * -1.0f;
                std::swap(c.a, c.b);
            }

            if (hit)
            {
                ResolveContact(c);
            }
        }
    }
}
```

