    {
        m_accumulatedForce += force;
    }

    void PhysicsBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic || !m_awake)
            return;

        Vec3 acceleration = gravity + (m_accumulatedForce * (1.0f / m_mass));
        m_linearVelocity += acceleration * dt;
        m_transform.position += m_linearVelocity * dt;
        m_accumulatedForce = {};
    }
}
