    Super::BeginPlay();

    if (AActor* Owner = GetOwner())
    {
        State.Position = Owner->GetActorLocation();
    }
}

void UCustomPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (DeltaTime <= 0.f)
    {
        return;
    }

    Integrate(DeltaTime);
    SyncOwnerTransform();

    OnPhysicsUpdated.Broadcast(State);
}

void UCustomPhysicsComponent::AddForce(const FVector& Force)
{
    if (Mass <= KINDA_SMALL_NUMBER)
    {
        return;
    }

    State.Acceleration += Force / Mass;
}

void UCustomPhysicsComponent::SetVelocity(const FVector& NewVelocity)
{
    State.Velocity = NewVelocity;
}

FVector UCustomPhysicsComponent::GetVelocity() const
{
    return State.Velocity;
}

void UCustomPhysicsComponent::Integrate(float DeltaTime)
{
    // Apply gravity
    if (bUseCustomGravity)
    {
        State.Acceleration += Gravity;
    }

    // Semi-implicit Euler integration
    State.Velocity += State.Acceleration * DeltaTime;

    // Apply damping
    State.Velocity *= FMath::Clamp(1.0f - LinearDamping * DeltaTime, 0.0f, 1.0f);

    FVector ProposedPosition = State.Position + State.Velocity * DeltaTime;
    FVector ProposedVelocity = State.Velocity;

    if (ResolveWorldCollision(ProposedPosition, ProposedVelocity))
    {
        State.Velocity = ProposedVelocity;
    }

    State.Position = ProposedPosition;

    // Clear acceleration for next frame
    State.Acceleration = FVector::ZeroVector;
}

void UCustomPhysicsComponent::SyncOwnerTransform()
{
    if (AActor* Owner = GetOwner())
    {
        Owner->SetActorLocation(State.Position);
    }
}

bool UCustomPhysicsComponent::ResolveWorldCollision(FVector& NewPosition, FVector& NewVelocity) const
{
    AActor* Owner = GetOwner();
    if (!Owner)
    {
        return false;
    }

    UWorld* World = Owner->GetWorld();
    if (!World)
    {
        return false;
    }

    // Simple downward floor test example
    FHitResult Hit;
    FVector Start = State.Position;
    FVector End = NewPosition;

    FCollisionQueryParams Params;
    Params.AddIgnoredActor(Owner);

    const bool bHit = World->SweepSingleByChannel(
        Hit,
        Start,
        End,
        FQuat::Identity,
        ECC_WorldStatic,
        FCollisionShape::MakeSphere(34.0f),
        Params
    );

    if (!bHit)
    {
        return false;
    }

    // Push out and kill velocity along the hit normal
    NewPosition = Hit.Location + Hit.Normal * 2.0f;
    const float NormalVel = FVector::DotProduct(NewVelocity, Hit.Normal);

    if (NormalVel < 0.0f)
    {
        NewVelocity -= NormalVel * Hit.Normal;
    }

    return true;
}
