#pragma once

#include "PhysicsTypes.h"

enum class BodyType
{
    Static,
    Dynamic
};

class RigidBody
{
public:
    BodyType Type = BodyType::Dynamic;
    Vec3 Position;
    Vec3 Velocity;
    Vec3 ForceAccumulation;
    float Mass = 1.0f;
    float Radius = 0.5f; // simple sphere collider for initial implementation
    float Restitution = 0.3f;

    bool IsDynamic() const { return Type == BodyType::Dynamic; }

    float GetInverseMass() const
    {
        if (!IsDynamic() || Mass <= 0.0f) return 0.0f;
        return 1.0f / Mass;
    }

    void ApplyForce(const Vec3& force)
    {
        if (!IsDynamic()) return;
        ForceAccumulation += force;
    }

    void ClearForces()
    {
        ForceAccumulation = {};
    }
};
