### `PhysicsWorld.cpp`

```cpp
#include "PhysicsWorld.h"
#include <algorithm>

PhysicsWorld::PhysicsWorld(const PhysicsSettings& settings)
    : Settings(settings)
{
}

RigidBody* PhysicsWorld::CreateBody(const RigidBody& templateBody)
{
    Bodies.push_back(std::make_unique<RigidBody>(templateBody));
    return Bodies.back().get();
}

void PhysicsWorld::DestroyBody(RigidBody* body)
{
    Bodies.erase(
        std::remove_if(Bodies.begin(), Bodies.end(),
            [body](const std::unique_ptr<RigidBody>& ptr)
            {
                return ptr.get() == body;
            }),
        Bodies.end());
}

void PhysicsWorld::Step(float deltaTime)
{
    if (deltaTime <= 0.0f) return;

    // Fixed timestep accumulation can be added later
    const float dt = std::min(deltaTime, Settings.FixedTimeStep);

    for (auto& bodyPtr : Bodies)
    {
        RigidBody& body = *bodyPtr;
        if (!body.IsDynamic()) continue;

        IntegrateForces(body, dt);
        IntegrateVelocity(body, dt);
        ResolveGroundCollision(body);
        body.ClearForces();
    }
}

void PhysicsWorld::IntegrateForces(RigidBody& body, float dt)
{
    const float invMass = body.GetInverseMass();
    if (invMass <= 0.0f) return;

    Vec3 acceleration = Settings.Gravity + body.ForceAccumulation * invMass;
    body.Velocity += acceleration * dt;
}

void PhysicsWorld::IntegrateVelocity(RigidBody& body, float dt)
{
    body.Position += body.Velocity * dt;
}

void PhysicsWorld::ResolveGroundCollision(RigidBody& body)
{
    const float groundY = Settings.GroundPlaneY;
    const float bottom = body.Position.y - body.Radius;

    if (bottom < groundY)
    {
        body.Position.y = groundY + body.Radius;

        if (body.Velocity.y < 0.0f)
        {
            body.Velocity.y = -body.Velocity.y * body.Restitution;
        }

        // simple friction damping
        body.Velocity.x *= 0.9f;
        body.Velocity.z *= 0.9f;
    }
}
