## `RigidBody.cpp`

```cpp
#include "RigidBody.h"

namespace CustomPhysics
{
    RigidBody::RigidBody()
    {
        Mass = 1.0f;
        InvMass = 1.0f;
        bStatic = false;
    }

    void RigidBody::SetMass(float InMass)
    {
        Mass = (InMass <= 0.0f) ? 1.0f : InMass;
        InvMass = 1.0f / Mass;
    }

    float RigidBody::GetMass() const
    {
        return Mass;
    }

    void RigidBody::SetPosition(const Vec3& InPosition)
    {
        BodyTransform.Position = InPosition;
    }

    const Vec3& RigidBody::GetPosition() const
    {
        return BodyTransform.Position;
    }

    void RigidBody::SetVelocity(const Vec3& InVelocity)
    {
        LinearVelocity = InVelocity;
    }

    const Vec3& RigidBody::GetVelocity() const
    {
        return LinearVelocity;
    }

    void RigidBody::AddForce(const Vec3& Force)
    {
        AccumulatedForce += Force;
    }

    void RigidBody::ClearForces()
    {
        AccumulatedForce = Vec3::Zero();
    }

    void RigidBody::SetStatic(bool bInStatic)
    {
        bStatic = bInStatic;
        InvMass = bStatic ? 0.0f : (1.0f / Mass);
    }

    bool RigidBody::IsStatic() const
    {
        return bStatic;
    }

    void RigidBody::Integrate(float DeltaTime, const Vec3& Gravity)
    {
        if (bStatic || DeltaTime <= 0.0f)
        {
            ClearForces();
            return;
        }

        // Acceleration = gravity + force / mass
        Vec3 Acceleration = Gravity + (AccumulatedForce * InvMass);

        // Semi-implicit Euler
        LinearVelocity += Acceleration * DeltaTime;
        BodyTransform.Position += LinearVelocity * DeltaTime;

        ClearForces();
    }
}
