### `CustomPhysicsPlugin.cpp`
```cpp
#include "CustomPhysicsPlugin.h"

namespace CustomPhysics
{
    void PhysicsWorld::AddBody(const RigidBody& body)
    {
        bodies.push_back(body);
    }

    std::vector<RigidBody>& PhysicsWorld::GetBodies()
    {
        return bodies;
    }

    void PhysicsWorld::Step(float dt)
    {
        const Vec3 planeNormal(0.0f, 1.0f, 0.0f);
        const float planeOffset = 0.0f; // ground at y = 0

        for (auto& body : bodies)
        {
            if (body.isStatic)
                continue;

            if (body.mass <= 0.0f)
                continue;

            // Apply gravity
            body.AddForce(gravity * body.mass);

            // Integrate velocity
            Vec3 acceleration = body.forceAccum * (1.0f / body.mass);
            body.velocity += acceleration * dt;

            // Integrate position
            body.position += body.velocity * dt;

            // Clear forces
            body.forceAccum = Vec3(0.0f, 0.0f, 0.0f);

            // Simple collision against ground plane y=0
            float distance = Dot(body.position, planeNormal) - planeOffset;
            if (distance < 0.0f)
            {
                body.position.y -= distance;

                // Reflect velocity if moving into the plane
                float vn = Dot(body.velocity, planeNormal);
                if (vn < 0.0f)
                {
                    Vec3 normalVel = planeNormal * vn;
                    Vec3 tangentialVel = body.velocity - normalVel;
                    body.velocity = tangentialVel - normalVel * body.restitution;
                }
            }
        }
    }

    PhysicsWorld* CreatePhysicsWorld()
    {
        return new PhysicsWorld();
    }

    void DestroyPhysicsWorld(PhysicsWorld* world)
    {
        delete world;
    }
}
```

