## 6) `CustomPhysicsComponent.cpp`

```cpp
#include "CustomPhysicsComponent.h"
#include "GameFramework/Actor.h"
#include "Components/PrimitiveComponent.h"
#include "TimerManager.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = false;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();

    if (bEnableCustomGravity)
    {
        // Run every frame
        GetWorld()->GetTimerManager().SetTimerForNextTick([this]()
        {
            if (IsValid(this))
            {
                ApplyCustomPhysics(0.f);
            }
        });

        // Repeating tick-like timer
        GetWorld()->GetTimerManager().SetTimer(
            TimerHandle,
            [this]()
            {
                if (IsValid(this))
                {
                    ApplyCustomPhysics(GetWorld()->GetDeltaSeconds());
                }
            },
            0.0f,
            true
        );
    }
}

void UCustomPhysicsComponent::ApplyCustomPhysics(float DeltaTime)
{
    AActor* Owner = GetOwner();
    if (!Owner) return;

    UPrimitiveComponent* Prim = Cast<UPrimitiveComponent>(Owner->GetRootComponent());
    if (!Prim || !Prim->IsSimulatingPhysics()) return;

    const FVector Force = GravityOverride * Prim->GetMass();
    Prim->AddForce(Force);
}
```

