## Example C++ skeleton

```cpp
// MinimalPhysicsPlugin.h
#pragma once

#include <vector>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const { return Vec3(x + other.x, y + other.y, z + other.z); }
    Vec3 operator-(const Vec3& other) const { return Vec3(x - other.x, y - other.y, z - other.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }

    Vec3& operator+=(const Vec3& other) { x += other.x; y += other.y; z += other.z; return *this; }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    float mass;
    float restitution;
    bool isStatic;

    RigidBody()
        : position(), velocity(), forceAccum(), mass(1.0f), restitution(0.2f), isStatic(false) {}
};

class MinimalPhysicsWorld {
public:
    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void step(float dt) {
        const Vec3 gravity(0.0f, -9.81f, 0.0f);

        for (auto& body : bodies) {
            if (body.isStatic || body.mass <= 0.0f)
                continue;

            // Apply gravity
            Vec3 accel = gravity + body.forceAccum * (1.0f / body.mass);

            // Integrate velocity
            body.velocity += accel * dt;

            // Integrate position
            body.position += body.velocity * dt;

            // Very simple ground-plane collision at y = 0
            if (body.position.y < 0.0f) {
                body.position.y = 0.0f;
                if (body.velocity.y < 0.0f) {
                    body.velocity.y = -body.velocity.y * body.restitution;
                }
            }

            // Clear forces
            body.forceAccum = Vec3(0.0f, 0.0f, 0.0f);
        }
    }

    std::vector<RigidBody>& getBodies() { return bodies; }

private:
    std::vector<RigidBody> bodies;
};
```

