### `PhysicsPlugin.cpp`
```cpp
#include "PhysicsPlugin.h"
#include <algorithm>

static Vec3 add(const Vec3& a, const Vec3& b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 mul(const Vec3& a, float s) {
    return {a.x * s, a.y * s, a.z * s};
}

RigidBody* PhysicsWorld::createBody(const Vec3& pos, float mass, bool isStatic) {
    bodies.push_back(RigidBody{});
    RigidBody& b = bodies.back();
    b.position = pos;
    b.mass = mass > 0.0f ? mass : 1.0f;
    b.isStatic = isStatic;
    return &b;
}

void PhysicsWorld::destroyBody(RigidBody* body) {
    bodies.erase(std::remove_if(bodies.begin(), bodies.end(),
        [body](const RigidBody& b) { return &b == body; }), bodies.end());
}

void PhysicsWorld::addForce(RigidBody* body, const Vec3& force) {
    if (!body || body->isStatic) return;
    body->forces = add(body->forces, force);
}

void PhysicsWorld::step(float dt) {
    const Vec3 gravity = {0.0f, -9.81f, 0.0f};

    for (auto& b : bodies) {
        if (b.isStatic) continue;

        // F = ma => a = F / m
        Vec3 accel = {
            gravity.x + b.forces.x / b.mass,
            gravity.y + b.forces.y / b.mass,
            gravity.z + b.forces.z / b.mass
        };

        b.velocity = add(b.velocity, mul(accel, dt));
        b.position = add(b.position, mul(b.velocity, dt));

        // Clear forces every frame
        b.forces = {0, 0, 0};
    }
}
