#include "PhysicsPlugin.h"
#include <vector>

static Vec3 add(Vec3 a, Vec3 b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 scale(Vec3 v, float s) {
    return {v.x * s, v.y * s, v.z * s};
}

void PhysicsPlugin::initialize() {
    // Register with engine update system here
}

void PhysicsPlugin::shutdown() {
    // Cleanup
}

void PhysicsPlugin::addBody(RigidBody* body) {
    bodies.push_back(body);
}

void PhysicsPlugin::removeBody(RigidBody* body) {
    bodies.erase(
        std::remove(bodies.begin(), bodies.end(), body),
        bodies.end()
    );
}

void PhysicsPlugin::update(float dt) {
    for (auto* body : bodies) {
        if (!body || body->isStatic) continue;

        // Apply gravity
        body->force = add(body->force, scale(gravity, body->mass));

        integrate(*body, dt);
        resolveGroundCollision(*body);

        // Clear force accumulator
        body->force = {0.0f, 0.0f, 0.0f};
    }
}

void PhysicsPlugin::integrate(RigidBody& body, float dt) {
    Vec3 acceleration = {
        body.force.x / body.mass,
        body.force.y / body.mass,
        body.force.z / body.mass
    };

    body.velocity = add(body.velocity, scale(acceleration, dt));
    body.position = add(body.position, scale(body.velocity, dt));
}

void PhysicsPlugin::resolveGroundCollision(RigidBody& body) {
    if (body.position.y < groundY) {
        body.position.y = groundY;
        if (body.velocity.y < 0.0f) {
            body.velocity.y = 0.0f;
        }
    }
}
