## Minimal custom physics plugin skeleton

### `PhysicsPlugin.h`
```cpp
#pragma once

#include <vector>

struct Vec3 {
    float x, y, z;
};

struct Body {
    Vec3 position{};
    Vec3 velocity{};
    Vec3 force{};
    float mass = 1.0f;
    bool isStatic = false;
};

class PhysicsPlugin {
public:
    void Initialize();
    void Shutdown();

    int CreateBody(const Body& body);
    void DestroyBody(int id);

    void AddForce(int id, const Vec3& force);
    void Step(float dt);

    const Body* GetBody(int id) const;

private:
    std::vector<Body> bodies;
};
```

### `PhysicsPlugin.cpp`
```cpp
#include "PhysicsPlugin.h"

static Vec3 Add(const Vec3& a, const Vec3& b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 Scale(const Vec3& v, float s) {
    return {v.x * s, v.y * s, v.z * s};
}

void PhysicsPlugin::Initialize() {
    bodies.clear();
}

void PhysicsPlugin::Shutdown() {
    bodies.clear();
}

int PhysicsPlugin::CreateBody(const Body& body) {
    bodies.push_back(body);
    return static_cast<int>(bodies.size() - 1);
}

void PhysicsPlugin::DestroyBody(int id) {
    if (id < 0 || id >= static_cast<int>(bodies.size())) return;
    bodies[id] = Body{};
    bodies[id].isStatic = true;
}

void PhysicsPlugin::AddForce(int id, const Vec3& force) {
    if (id < 0 || id >= static_cast<int>(bodies.size())) return;
    bodies[id].force = Add(bodies[id].force, force);
}

void PhysicsPlugin::Step(float dt) {
    const Vec3 gravity{0.0f, -9.81f, 0.0f};

    for (auto& body : bodies) {
        if (body.isStatic || body.mass <= 0.0f) continue;

        Vec3 totalForce = Add(body.force, Scale(gravity, body.mass));
        Vec3 acceleration = Scale(totalForce, 1.0f / body.mass);

        body.velocity = Add(body.velocity, Scale(acceleration, dt));
        body.position = Add(body.position, Scale(body.velocity, dt));

        body.force = {0.0f, 0.0f, 0.0f};
    }
}

const Body* PhysicsPlugin::GetBody(int id) const {
    if (id < 0 || id >= static_cast<int>(bodies.size())) return nullptr;
    return &bodies[id];
}
```

