## Minimal custom physics plugin

### 1) Core interface

```cpp
// PhysicsPlugin.h
#pragma once
#include <cstdint>

struct Vec3 {
    float x, y, z;
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass;
    bool isStatic;
};

class IPhysicsPlugin {
public:
    virtual ~IPhysicsPlugin() = default;

    virtual void Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual void RegisterBody(RigidBody* body) = 0;
    virtual void UnregisterBody(RigidBody* body) = 0;
    virtual void Step(float deltaTime) = 0;
};
```

---

### 2) Minimal implementation

```cpp
// SimplePhysicsPlugin.h
#pragma once
#include "PhysicsPlugin.h"
#include <vector>
#include <algorithm>

class SimplePhysicsPlugin final : public IPhysicsPlugin {
public:
    void Initialize() override {}
    void Shutdown() override {
        bodies.clear();
    }

    void RegisterBody(RigidBody* body) override {
        if (body) bodies.push_back(body);
    }

    void UnregisterBody(RigidBody* body) override {
        bodies.erase(std::remove(bodies.begin(), bodies.end(), body), bodies.end());
    }

    void Step(float dt) override {
        const Vec3 gravity{0.0f, -9.81f, 0.0f};

        for (RigidBody* body : bodies) {
            if (!body || body->isStatic) continue;

            // Apply gravity
            body->force.x += gravity.x * body->mass;
            body->force.y += gravity.y * body->mass;
            body->force.z += gravity.z * body->mass;

            // Semi-implicit Euler integration
            Vec3 accel{
                body->force.x / body->mass,
                body->force.y / body->mass,
                body->force.z / body->mass
            };

            body->velocity.x += accel.x * dt;
            body->velocity.y += accel.y * dt;
            body->velocity.z += accel.z * dt;

            body->position.x += body->velocity.x * dt;
            body->position.y += body->velocity.y * dt;
            body->position.z += body->velocity.z * dt;

            // Clear forces each step
            body->force = {0.0f, 0.0f, 0.0f};
        }
    }

private:
    std::vector<RigidBody*> bodies;
};
```

