#include "MiniPhysicsComponent.h"
#include "GameFramework/Actor.h"
#include "GameFramework/PhysicsVolume.h"

UMiniPhysicsComponent::UMiniPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    SetComponentTickEnabled(true);
}

void UMiniPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UMiniPhysicsComponent::TickComponent(
    float DeltaTime,
    ELevelTick TickType,
    FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bUseCustomGravity)
        return;

    AActor* Owner = GetOwner();
    if (!Owner)
        return;

    UPrimitiveComponent* Prim = Cast<UPrimitiveComponent>(Owner->GetRootComponent());
    if (!Prim || !Prim->IsSimulatingPhysics())
        return;

    // F = m * a
    const FVector Force = Gravity * Mass;
    Prim->AddForce(Force);
}
