#include "MiniPhysicsSubsystem.h"
#include "EngineUtils.h"
#include "MiniPhysicsComponent.h"
#include "GameFramework/Actor.h"
#include "Components/PrimitiveComponent.h"

bool UMiniPhysicsSubsystem::DoesSupportWorldType(EWorldType::Type WorldType) const
{
    return WorldType == EWorldType::Game || WorldType == EWorldType::PIE;
}

TStatId UMiniPhysicsSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UMiniPhysicsSubsystem, STATGROUP_Tickables);
}

void UMiniPhysicsSubsystem::Tick(float DeltaTime)
{
    for (TActorIterator<AActor> It(GetWorld()); It; ++It)
    {
        AActor* Actor = *It;
        if (!Actor)
            continue;

        UMiniPhysicsComponent* MiniComp = Actor->FindComponentByClass<UMiniPhysicsComponent>();
        if (!MiniComp || !MiniComp->bUseCustomGravity)
            continue;

        UPrimitiveComponent* Prim = Cast<UPrimitiveComponent>(Actor->GetRootComponent());
        if (!Prim || !Prim->IsSimulatingPhysics())
            continue;

        const FVector Force = MiniComp->Gravity * MiniComp->Mass * GlobalGravityScale;
        Prim->AddForce(Force);
    }
}
