## Minimal custom physics plugin

### `CustomPhysicsPlugin.cs`
```csharp
using System.Collections.Generic;
using UnityEngine;

namespace CustomPhysics
{
    // Attach this to a GameObject in your scene.
    public class CustomPhysicsPlugin : MonoBehaviour
    {
        public Vector3 gravity = new Vector3(0, -9.81f, 0);
        public float fixedTimeStep = 0.02f;

        private readonly List<CustomBody> bodies = new List<CustomBody>();
        private float accumulator;

        public void RegisterBody(CustomBody body)
        {
            if (!bodies.Contains(body))
                bodies.Add(body);
        }

        public void UnregisterBody(CustomBody body)
        {
            bodies.Remove(body);
        }

        void Update()
        {
            accumulator += Time.deltaTime;

            while (accumulator >= fixedTimeStep)
            {
                StepPhysics(fixedTimeStep);
                accumulator -= fixedTimeStep;
            }
        }

        private void StepPhysics(float dt)
        {
            foreach (var body in bodies)
            {
                if (body == null || body.IsStatic)
                    continue;

                body.Velocity += gravity * dt;
                body.transform.position += body.Velocity * dt;

                // Simple ground plane at y = 0
                if (body.transform.position.y < 0f)
                {
                    var pos = body.transform.position;
                    pos.y = 0f;
                    body.transform.position = pos;

                    if (body.Velocity.y < 0f)
                        body.Velocity.y = -body.Velocity.y * body.Restitution;
                }
            }
        }
    }
}
```

