## Minimal custom physics plugin

### `PhysicsPlugin.h`
```cpp
#pragma once

#include <vector>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& r) const { return Vec3(x + r.x, y + r.y, z + r.z); }
    Vec3 operator-(const Vec3& r) const { return Vec3(x - r.x, y - r.y, z - r.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3& operator+=(const Vec3& r) { x += r.x; y += r.y; z += r.z; return *this; }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass;
    bool isStatic;

    RigidBody()
        : position(), velocity(), force(), mass(1.0f), isStatic(false) {}
};

class PhysicsWorld {
public:
    void addBody(const RigidBody& body);
    void step(float dt);

    const std::vector<RigidBody>& getBodies() const { return bodies; }

private:
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);
};
```

### `PhysicsPlugin.cpp`
```cpp
#include "PhysicsPlugin.h"

void PhysicsWorld::addBody(const RigidBody& body) {
    bodies.push_back(body);
}

void PhysicsWorld::step(float dt) {
    for (auto& body : bodies) {
        if (body.isStatic) continue;

        Vec3 acceleration = gravity + (body.force * (1.0f / body.mass));
        body.velocity += acceleration * dt;
        body.position += body.velocity * dt;

        body.force = Vec3(0, 0, 0);
    }
}
```

