## Example: plugin core in C++-style pseudocode

```cpp
// PhysicsPlugin.h
#pragma once

struct Vec3 {
    float x, y, z;
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass;
    bool isStatic;
};

class PhysicsPlugin {
public:
    bool Initialize();
    void Shutdown();
    void Update(float deltaTime);

    void AddBody(RigidBody* body);
    void RemoveBody(RigidBody* body);

private:
    Vec3 gravity = {0.0f, -9.81f, 0.0f};
    RigidBody* bodies[128];
    int bodyCount = 0;
};
```

```cpp
// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"

static Vec3 Add(Vec3 a, Vec3 b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 Scale(Vec3 v, float s) {
    return {v.x * s, v.y * s, v.z * s};
}

bool PhysicsPlugin::Initialize() {
    bodyCount = 0;
    return true;
}

void PhysicsPlugin::Shutdown() {
    bodyCount = 0;
}

void PhysicsPlugin::AddBody(RigidBody* body) {
    if (bodyCount < 128) {
        bodies[bodyCount++] = body;
    }
}

void PhysicsPlugin::RemoveBody(RigidBody* body) {
    for (int i = 0; i < bodyCount; ++i) {
        if (bodies[i] == body) {
            bodies[i] = bodies[bodyCount - 1];
            bodyCount--;
            return;
        }
    }
}

void PhysicsPlugin::Update(float deltaTime) {
    for (int i = 0; i < bodyCount; ++i) {
        RigidBody* b = bodies[i];
        if (!b || b->isStatic || b->mass <= 0.0f) continue;

        // Force = gravity * mass
        Vec3 gravityForce = Scale(gravity, b->mass);
        Vec3 totalForce = Add(b->force, gravityForce);

        // Acceleration = force / mass
        Vec3 acceleration = Scale(totalForce, 1.0f / b->mass);

        // Semi-barebones Euler integration
        b->velocity.x += acceleration.x * deltaTime;
        b->velocity.y += acceleration.y * deltaTime;
        b->velocity.z += acceleration.z * deltaTime;

        b->position.x += b->velocity.x * deltaTime;
        b->position.y += b->velocity.y * deltaTime;
        b->position.z += b->velocity.z * deltaTime;

        // Clear accumulated forces
        b->force = {0.0f, 0.0f, 0.0f};
    }
}
```

