```cpp
#include <chrono>
#include <cmath>
#include <iostream>
#include <thread>
#include <vector>
#include <algorithm>

using Clock = std::chrono::high_resolution_clock;
using Duration = std::chrono::duration<double>;

struct Vec3 {
    double x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(double x_, double y_, double z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    Vec3 operator/(double s) const { return {x / s, y / s, z / s}; }

    Vec3& operator+=(const Vec3& o) { x += o.x; y += o.y; z += o.z; return *this; }
    Vec3& operator-=(const Vec3& o) { x -= o.x; y -= o.y; z -= o.z; return *this; }
    Vec3& operator*=(double s) { x *= s; y *= s; z *= s; return *this; }
};

static inline double dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

static inline double length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    double len = length(v);
    if (len <= 1e-9) return Vec3(0, 0, 0);
    return v / len;
}

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;

    double mass = 1.0;
    double invMass = 1.0;

    double restitution = 0.4;
    double friction = 0.2;

    void setMass(double m) {
        mass = m;
        invMass = (m > 0.0) ? 1.0 / m : 0.0;
    }

    void applyForce(const Vec3& f) {
        force += f;
    }

    void integrate(double dt) {
        if (invMass == 0.0) return;

        // Acceleration from forces
        Vec3 acceleration = force * invMass;

        // Semi-implicit Euler
        velocity += acceleration * dt;
        position += velocity * dt;

        // Reset accumulated forces
        force = Vec3(0, 0, 0);
    }
};

struct World {
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0, -9.81, 0.0);

    void step(double dt) {
        for (auto& body : bodies) {
            // External forces
            body.applyForce(gravity * body.mass);

            // Integrate motion
            body.integrate(dt);

            // Simple ground plane collision at y = 0
            if (body.position.y < 0.0) {
                body.position.y = 0.0;

                if (body.velocity.y < 0.0) {
                    body.velocity.y = -body.velocity.y * body.restitution;

                    // Simple Coulomb-like friction on tangential motion
                    body.velocity.x *= (1.0 - body.friction);
                    body.velocity.z *= (1.0 - body.friction);

                    // Sleep threshold to avoid endless tiny bouncing
                    if (std::abs(body.velocity.y) < 0.05) {
                        body.velocity.y = 0.0;
                    }
                }
            }
        }
    }
};

int main() {
    World world;

    RigidBody box;
    box.position = Vec3(0.0, 10.0, 0.0);
    box.velocity = Vec3(2.0, 0.0, 0.0);
    box.setMass(2.0);
    box.restitution = 0.5;
    box.friction = 0.1;

    world.bodies.push_back(box);

    const double fixedDt = 1.0 / 120.0;   // physics update rate
    const double targetFrameTime = 1.0 / 60.0; // render/frame limit
    const double maxAccumulatedTime = 0.25; // avoid spiral of death

    double accumulator = 0.0;
    auto previousTime = Clock::now();

    bool running = true;
    int frameCount = 0;

    while (running) {
        auto currentTime = Clock::now();
        Duration frameTime = currentTime - previousTime;
        previousTime = currentTime;

        double dt = frameTime.count();
        if (dt > maxAccumulatedTime) dt = maxAccumulatedTime;
        accumulator += dt;

        // Fixed timestep physics
        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // "Render" output for demo purposes
        const auto& b = world.bodies[0];
        std::cout << "Frame " << frameCount++
                  << " | Pos: (" << b.position.x << ", " << b.position.y << ", " << b.position.z << ")"
                  << " | Vel: (" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ")"
                  << std::endl;

        // Frame-rate limiter
        auto afterUpdate = Clock::now();
        Duration workTime = afterUpdate - currentTime;
        double sleepTime = targetFrameTime - workTime.count();
        if (sleepTime > 0.0) {
            std::this_thread::sleep_for(std::chrono::duration<double>(sleepTime));
        }

        // Stop after some frames for demo
        if (frameCount > 600) running = false;
    }

    return 0;
}
```

### Notes
- **Fixed timestep** is important for stable physics.
- **Semi-implicit Euler** is better than explicit Euler for most real-time simulations.
- The collision handling here is very basic:
  - ground plane only,
  - no rotation,
  - no impulse-based body-body collision,
  - no broadphase/narrowphase.
- For real rigid body dynamics, you’d usually add:
  - orientation (`quaternion`),
  - angular velocity,
  - inertia tensor,
  - impulse solver,
  - constraint resolution.

