Below is a compact but solid C++ example of a real-time rigid-body physics simulation loop with:

- semi-implicit Euler integration
- gravity
- simple sphere-ground collision
- fixed timestep physics
- frame-rate independent rendering/update structure
- frame-time clamping to avoid spiral-of-death issues

It’s meant as a starting point for a real engine, not a full-featured physics library.

```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <chrono>
#include <thread>

// ------------------------------
// Basic math
// ------------------------------
struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& v) const { return {x + v.x, y + v.y, z + v.z}; }
    Vec3 operator-(const Vec3& v) const { return {x - v.x, y - v.y, z - v.z}; }
    Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
    Vec3 operator/(float s) const { return {x / s, y / s, z / s}; }

    Vec3& operator+=(const Vec3& v) { x += v.x; y += v.y; z += v.z; return *this; }
    Vec3& operator-=(const Vec3& v) { x -= v.x; y -= v.y; z -= v.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

static inline float dot(const Vec3& a, const Vec3& b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

static inline float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len <= 1e-8f) return {0, 0, 0};
    return v / len;
}

// ------------------------------
// Rigid body (simplified: sphere only + linear dynamics)
// ------------------------------
struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;

    float mass;
    float invMass;
    float restitution;
    float radius;

    RigidBody(const Vec3& pos, float m, float r)
        : position(pos), velocity(0,0,0), forceAccum(0,0,0),
          mass(m), restitution(0.5f), radius(r)
    {
        invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f;
    }

    void addForce(const Vec3& f) {
        forceAccum += f;
    }

    void clearForces() {
        forceAccum = {0,0,0};
    }

    void integrate(float dt) {
        if (invMass <= 0.0f) return; // static body

        // Acceleration
        Vec3 acceleration = forceAccum * invMass;

        // Semi-implicit Euler
        velocity += acceleration * dt;
        position += velocity * dt;

        clearForces();
    }
};

// ------------------------------
// Physics world
// ------------------------------
class PhysicsWorld {
public:
    Vec3 gravity = {0.0f, -9.81f, 0.0f};
    std::vector<RigidBody> bodies;

    void step(float dt) {
        // Apply forces
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.addForce(gravity * body.mass);
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Collisions with infinite ground plane at y = 0
        for (auto& body : bodies) {
            resolveGroundCollision(body);
        }
    }

private:
    void resolveGroundCollision(RigidBody& body) {
        float minY = body.radius;
        if (body.position.y < minY) {
            // Positional correction
            body.position.y = minY;

            // Velocity response
            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;

                // Optional damping to reduce endless bouncing
                if (std::fabs(body.velocity.y) < 0.5f) {
                    body.velocity.y = 0.0f;
                }
            }
        }
    }
};

// ------------------------------
// Main loop with fixed timestep
// ------------------------------
int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec3(0.0f, 10.0f, 0.0f), 1.0f, 0.5f);
    world.bodies.emplace_back(Vec3(2.0f, 18.0f, 0.0f), 2.0f, 0.75f);

    const float fixedDt = 1.0f / 120.0f;      // physics at 120 Hz
    const float maxFrameTime = 0.25f;         // clamp large pauses
    const int maxSubsteps = 8;                // frame-rate constraint guard

    auto prev = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        std::chrono::duration<float> elapsed = now - prev;
        prev = now;

        float frameTime = std::min(elapsed.count(), maxFrameTime);
        accumulator += frameTime;

        int substeps = 0;
        while (accumulator >= fixedDt && substeps < maxSubsteps) {
            world.step(fixedDt);
            accumulator -= fixedDt;
            ++substeps;
        }

        // Optional interpolation alpha for rendering
        float alpha = accumulator / fixedDt;

        // "Render" first body to console (replace with actual renderer)
        const auto& b = world.bodies[0];
        std::cout << "\r"
                  << "Pos: (" << b.position.x << ", " << b.position.y << ", " << b.position.z << ") "
                  << "Vel: (" << b.velocity.x << ", " << b.velocity.y << ", " << b.velocity.z << ") "
                  << "alpha=" << alpha
                  << "      " << std::flush;

        // Simulate frame pacing (~60 FPS display loop)
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
```

### Notes
- **Fixed timestep** is used for stable physics, independent of rendering FPS.
- `maxFrameTime` prevents huge jumps if the app stalls.
- `maxSubsteps` limits physics catch-up work per frame.
- This is a **simplified rigid body model**: translation only, no rotation, no inertia tensors, no contact manifolds.

