  <div class="hud">Click to drop a box</div>
  <canvas id="c" width="900" height="600"></canvas>

  <script>
    const canvas = document.getElementById("c");
    const ctx = canvas.getContext("2d");

    const W = canvas.width;
    const H = canvas.height;
    const GRAVITY = 1200; // px/s^2
    const FIXED_DT = 1 / 60; // physics timestep
    const MAX_FRAME_TIME = 0.05; // frame-rate constraint: cap large frame jumps
    const SUBSTEPS = 1; // keep minimal; increase for more stable physics

    const bodies = [];

    class Body {
      constructor(x, y, w, h, mass = 1) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.vx = 0;
        this.vy = 0;
        this.angle = 0;
        this.omega = 0;
        this.mass = mass;
        this.invMass = mass > 0 ? 1 / mass : 0;
        this.restitution = 0.35;
        this.friction = 0.8;
      }

      integrate(dt) {
        this.vy += GRAVITY * dt;
        this.x += this.vx * dt;
        this.y += this.vy * dt;
        this.angle += this.omega * dt;
      }

      draw(ctx) {
        ctx.save();
        ctx.translate(this.x + this.w / 2, this.y + this.h / 2);
        ctx.rotate(this.angle);
        ctx.fillStyle = "#4fc3f7";
        ctx.fillRect(-this.w / 2, -this.h / 2, this.w, this.h);
        ctx.restore();
      }
    }

    // Static ground
    const ground = {
      x: 0,
      y: H - 40,
      w: W,
      h: 40
    };

    function resolveGroundCollision(body) {
      const bottom = body.y + body.h;
      const groundTop = ground.y;

      if (bottom > groundTop) {
        body.y = groundTop - body.h;

        // bounce
        if (Math.abs(body.vy) > 10) {
          body.vy = -body.vy * body.restitution;
        } else {
          body.vy = 0;
        }

        // simple friction
        body.vx *= 0.98;
      }
    }

    function clampToWalls(body) {
      if (body.x < 0) {
        body.x = 0;
        body.vx *= -body.restitution;
      }
      if (body.x + body.w > W) {
        body.x = W - body.w;
        body.vx *= -body.restitution;
      }
    }

    function stepPhysics(dt) {
      for (const b of bodies) {
        b.integrate(dt);
        resolveGroundCollision(b);
        clampToWalls(b);
      }
    }

    // Spawn initial bodies
    for (let i = 0; i < 5; i++) {
      bodies.push(new Body(100 + i * 60, 50 + i * 10, 40, 40, 1));
    }

    canvas.addEventListener("click", (e) => {
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      bodies.push(new Body(x - 20, 20, 40, 40, 1));
    });

    let lastTime = performance.now();
    let accumulator = 0;

    function loop(now) {
      const frameTime = Math.min((now - lastTime) / 1000, MAX_FRAME_TIME);
      lastTime = now;
      accumulator += frameTime;

      // Fixed timestep simulation for stable physics across frame rates
      while (accumulator >= FIXED_DT) {
        for (let i = 0; i < SUBSTEPS; i++) {
          stepPhysics(FIXED_DT / SUBSTEPS);
        }
        accumulator -= FIXED_DT;
      }

      render();
      requestAnimationFrame(loop);
    }

    function render() {
      ctx.clearRect(0, 0, W, H);

      // ground
      ctx.fillStyle = "#444";
      ctx.fillRect(ground.x, ground.y, ground.w, ground.h);

      // bodies
      for (const b of bodies) b.draw(ctx);

      // debug text
      ctx.fillStyle = "#fff";
      ctx.fillText(`Bodies: ${bodies.length}`, 10, 20);
      ctx.fillText(`Fixed timestep: ${FIXED_DT.toFixed(3)}s`, 10, 40);
    }

    requestAnimationFrame(loop);
  </script>
