Save as `index.html` and open in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Rigid Body Physics</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #111;
    }
    canvas {
      display: block;
      background: #1b1b1b;
    }
  </style>
</head>
<body>
<canvas id="c"></canvas>
<script>
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

const gravity = 1200;      // px/s^2
const dt = 1 / 60;         // fixed timestep
const maxFrameTime = 0.25; // avoid spiral of death

class Body {
  constructor(x, y, w, h, mass = 1, color = "white", isStatic = false) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.vx = 0;
    this.vy = 0;
    this.ax = 0;
    this.ay = 0;
    this.mass = isStatic ? Infinity : mass;
    this.invMass = isStatic ? 0 : 1 / mass;
    this.isStatic = isStatic;
    this.color = color;
  }

  integrate(dt) {
    if (this.isStatic) return;
    this.vy += gravity * dt;
    this.x += this.vx * dt;
    this.y += this.vy * dt;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.w, this.h);
  }
}

function overlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

function resolveCollision(a, b) {
  if (!overlap(a, b)) return;

  const dx1 = (a.x + a.w) - b.x;      // overlap from left
  const dx2 = (b.x + b.w) - a.x;      // overlap from right
  const dy1 = (a.y + a.h) - b.y;      // overlap from top
  const dy2 = (b.y + b.h) - a.y;      // overlap from bottom

  const minX = Math.min(dx1, dx2);
  const minY = Math.min(dy1, dy2);

  let nx = 0, ny = 0, penetration = 0;

  if (minX < minY) {
    penetration = minX;
    nx = dx1 < dx2 ? -1 : 1;
  } else {
    penetration = minY;
    ny = dy1 < dy2 ? -1 : 1;
  }

  const invMassSum = a.invMass + b.invMass;
  if (invMassSum === 0) return;

  // Positional correction
  const percent = 0.8;
  const slop = 0.01;
  const correction = Math.max(penetration - slop, 0) / invMassSum * percent;

  a.x -= nx * correction * a.invMass;
  a.y -= ny * correction * a.invMass;
  b.x += nx * correction * b.invMass;
  b.y += ny * correction * b.invMass;

  // Relative velocity along collision normal
  const rvx = b.vx - a.vx;
  const rvy = b.vy - a.vy;
  const velAlongNormal = rvx * nx + rvy * ny;

  if (velAlongNormal > 0) return;

  const restitution = 0.2; // bounciness
  const j = -(1 + restitution) * velAlongNormal / invMassSum;

  const impulseX = j * nx;
  const impulseY = j * ny;

  a.vx -= impulseX * a.invMass;
  a.vy -= impulseY * a.invMass;
  b.vx += impulseX * b.invMass;
  b.vy += impulseY * b.invMass;
}

const bodies = [];
bodies.push(new Body(100, 50, 60, 60, 1, "#4fc3f7"));
bodies.push(new Body(300, 0, 80, 80, 2, "#ffb74d"));
bodies.push(new Body(500, 100, 50, 50, 1, "#81c784"));

// Floor
bodies.push(new Body(0, window.innerHeight - 50, window.innerWidth, 50, 1, "#555", true));

// Left / right walls and ceiling
bodies.push(new Body(-50, 0, 50, window.innerHeight, 1, "#555", true));
bodies.push(new Body(window.innerWidth, 0, 50, window.innerHeight, 1, "#555", true));
bodies.push(new Body(0, -50, window.innerWidth, 50, 1, "#555", true));

window.addEventListener("keydown", e => {
  // Apply simple impulses to first body
  const b = bodies[0];
  if (e.key === "ArrowLeft") b.vx -= 300;
  if (e.key === "ArrowRight") b.vx += 300;
  if (e.key === "ArrowUp") b.vy -= 500;
});

let lastTime = 0;
let accumulator = 0;

function update(step) {
  // integrate
  for (const b of bodies) b.integrate(step);

  // collision pairs
  for (let i = 0; i < bodies.length; i++) {
    for (let j = i + 1; j < bodies.length; j++) {
      resolveCollision(bodies[i], bodies[j]);
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const b of bodies) b.draw();
}

function loop(timestamp) {
  const frameTime = Math.min((timestamp - lastTime) / 1000, maxFrameTime);
  lastTime = timestamp;
  accumulator += frameTime;

  while (accumulator >= dt) {
    update(dt);
    accumulator -= dt;
  }

  render();
  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
</script>
</body>
</html>
