```ts
import { PaymentGateway } from "../gateways/paymentGateway";
import { Money, Payment, PaymentStatus } from "../domain/payment";

type CreatePaymentInput = {
  merchantId: string;
  amount: Money;
  externalReference?: string;
  idempotencyKey: string;
};

export class PaymentService {
  constructor(
    private readonly gateway: PaymentGateway,
    private readonly paymentsRepo: {
      create(payment: Payment): Promise<Payment>;
      findById(id: string): Promise<Payment | null>;
      update(payment: Payment): Promise<Payment>;
      findByIdempotencyKey(merchantId: string, key: string): Promise<Payment | null>;
      saveIdempotencyKey(merchantId: string, key: string, paymentId: string): Promise<void>;
    },
    private readonly auditRepo: {
      append(event: { paymentId: string; type: string; payload: unknown }): Promise<void>;
    }
  ) {}

  async createPayment(input: CreatePaymentInput): Promise<Payment> {
    const existing = await this.paymentsRepo.findByIdempotencyKey(
      input.merchantId,
      input.idempotencyKey
    );
    if (existing) return existing;

    const payment: Payment = {
      id: crypto.randomUUID(),
      merchantId: input.merchantId,
      status: "CREATED",
      amount: input.amount,
      externalReference: input.externalReference,
      createdAt: new Date(),
      updatedAt: new Date()
    };

    await this.paymentsRepo.create(payment);
    await this.paymentsRepo.saveIdempotencyKey(
      input.merchantId,
      input.idempotencyKey,
      payment.id
    );
    await this.auditRepo.append({
      paymentId: payment.id,
      type: "PAYMENT_CREATED",
      payload: payment
    });

    const auth = await this.gateway.authorize({
      merchantId: payment.merchantId,
      paymentId: payment.id,
      amount: payment.amount
    });

    payment.status = auth.authorized ? "AUTHORIZED" : "FAILED";
    payment.gatewayTransactionId = auth.gatewayTransactionId;
    payment.updatedAt = new Date();

    await this.paymentsRepo.update(payment);
    await this.auditRepo.append({
      paymentId: payment.id,
      type: "PAYMENT_AUTHORIZATION_RESULT",
      payload: auth
    });

    return payment;
  }

  async capturePayment(paymentId: string, merchantId: string, amount?: Money): Promise<Payment> {
    const payment = await this.paymentsRepo.findById(paymentId);
    if (!payment || payment.merchantId !== merchantId) {
      throw new Error("Payment not found");
    }
    if (payment.status !== "AUTHORIZED") {
      throw new Error(`Cannot capture payment in status ${payment.status}`);
    }
    if (!payment.gatewayTransactionId) {
      throw new Error("Missing gateway transaction id");
    }

    const result = await this.gateway.capture({
      merchantId,
      paymentId,
      gatewayTransactionId: payment.gatewayTransactionId,
      amount: amount ?? payment.amount
    });

    payment.status = result.captured ? "CAPTURED" : "FAILED";
    payment.gatewayTransactionId = result.gatewayTransactionId ?? payment.gatewayTransactionId;
    payment.updatedAt = new Date();

    await this.paymentsRepo.update(payment);
    await this.auditRepo.append({
      paymentId: payment.id,
      type: "PAYMENT_CAPTURE_RESULT",
      payload: result
    });

    return payment;
  }

  async refundPayment(paymentId: string, merchantId: string, amount?: Money): Promise<Payment> {
    const payment = await this.paymentsRepo.findById(paymentId);
    if (!payment || payment.merchantId !== merchantId) {
      throw new Error("Payment not found");
    }
    if (payment.status !== "CAPTURED") {
      throw new Error(`Cannot refund payment in status ${payment.status}`);
    }
    if (!payment.gatewayTransactionId) {
      throw new Error("Missing gateway transaction id");
    }

    const result = await this.gateway.refund({
      merchantId,
      paymentId,
      gatewayTransactionId: payment.gatewayTransactionId,
      amount: amount ?? payment.amount
    });

    payment.status = result.refunded ? "REFUNDED" : "FAILED";
    payment.updatedAt = new Date();

    await this.paymentsRepo.update(payment);
    await this.auditRepo.append({
      paymentId: payment.id,
      type: "PAYMENT_REFUND_RESULT",
      payload: result
    });

    return payment;
  }
}
