```ts
import { Router } from "express";
import { PaymentService } from "../services/paymentService";
import { requireIdempotencyKey } from "../middleware/idempotency";
import { requireMerchantAuth } from "../middleware/auth";

export function paymentsRouter(service: PaymentService) {
  const router = Router();

  router.post("/", requireMerchantAuth, requireIdempotencyKey, async (req, res, next) => {
    try {
      const merchantId = (req as any).merchantId;
      const { amount, externalReference } = req.body;

      if (!amount?.currency || typeof amount.amountMinor !== "number") {
        return res.status(400).json({ error: "Invalid amount" });
      }

      const payment = await service.createPayment({
        merchantId,
        amount,
        externalReference,
        idempotencyKey: req.header("Idempotency-Key")!
      });

      res.status(201).json(payment);
    } catch (err) {
      next(err);
    }
  });

  router.post("/:id/capture", requireMerchantAuth, async (req, res, next) => {
    try {
      const merchantId = (req as any).merchantId;
      const payment = await service.capturePayment(req.params.id, merchantId, req.body.amount);
      res.json(payment);
    } catch (err) {
      next(err);
    }
  });

  router.post("/:id/refund", requireMerchantAuth, async (req, res, next) => {
    try {
      const merchantId = (req as any).merchantId;
      const payment = await service.refundPayment(req.params.id, merchantId, req.body.amount);
      res.json(payment);
    } catch (err) {
      next(err);
    }
  });

  return router;
}
