const auditEvents: any[] = [];

const repo = {
  async create(payment: any) {
    memoryPayments.set(payment.id, payment);
    return payment;
  },
  async findById(id: string) {
    return memoryPayments.get(id) ?? null;
  },
  async update(payment: any) {
    memoryPayments.set(payment.id, payment);
    return payment;
  },
  async findByIdempotencyKey(merchantId: string, key: string) {
    const paymentId = idempotencyMap.get(`${merchantId}:${key}`);
    return paymentId ? memoryPayments.get(paymentId) ?? null : null;
  },
  async saveIdempotencyKey(merchantId: string, key: string, paymentId: string) {
    idempotencyMap.set(`${merchantId}:${key}`, paymentId);
  }
};

const auditRepo = {
  async append(event: any) {
    auditEvents.push({ ...event, ts: new Date().toISOString() });
  }
};

