package com.bank.payments.persistence;

import com.bank.payments.domain.Payment;
import org.springframework.stereotype.Repository;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryPaymentRepository implements PaymentRepository {
    private final Map<UUID, Payment> byId = new ConcurrentHashMap<>();
    private final Map<String, UUID> byIdempotencyKey = new ConcurrentHashMap<>();

    @Override
    public synchronized Payment save(Payment payment) {
        byId.put(payment.getPaymentId(), payment);
        byIdempotencyKey.put(payment.getIdempotencyKey(), payment.getPaymentId());
        return payment;
    }

    @Override
    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        UUID id = byIdempotencyKey.get(idempotencyKey);
        return id == null ? Optional.empty() : Optional.ofNullable(byId.get(id));
    }

    @Override
    public Optional<Payment> findById(UUID id) {
        return Optional.ofNullable(byId.get(id));
    }
}
