@Service
public class AuditService {
    private static final Logger audit = LoggerFactory.getLogger("AUDIT");

    public void logPaymentCreated(Payment payment) {
        audit.info("payment_created paymentId={} idempotencyKey={} debtorAccount={} creditorAccount={} amount={} currency={} status={}",
                payment.getPaymentId(),
                payment.getIdempotencyKey(),
                mask(payment.getDebtorAccount()),
                mask(payment.getCreditorAccount()),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getStatus());
    }

    private String mask(String account) {
        if (account == null || account.length() <= 4) return "****";
        return "****" + account.substring(account.length() - 4);
    }
}
