## Service layer

```java
package com.bank.payments.service;

import com.bank.payments.api.CreatePaymentRequest;
import com.bank.payments.audit.AuditService;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.persistence.PaymentRepository;
import com.bank.payments.risk.RiskAssessmentService;
import jakarta.transaction.Transactional;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository repository;
    private final RiskAssessmentService riskService;
    private final AuditService auditService;

    public PaymentService(PaymentRepository repository, RiskAssessmentService riskService, AuditService auditService) {
        this.repository = repository;
        this.riskService = riskService;
        this.auditService = auditService;
    }

    @Transactional
    public Payment createPayment(CreatePaymentRequest req) {
        repository.findByIdempotencyKey(req.idempotencyKey()).ifPresent(existing -> {
            throw new DuplicatePaymentException(existing.getPaymentId().toString());
        });

        Payment payment = new Payment(
                UUID.randomUUID(),
                req.idempotencyKey(),
                req.debtorAccount(),
                req.creditorAccount(),
                req.amount(),
                req.currency(),
                PaymentStatus.RECEIVED,
                Instant.now(),
                Instant.now()
        );

        payment.setStatus(PaymentStatus.VALIDATED);

        var decision = riskService.assess(payment);
        if (!decision.approved()) {
            payment.setStatus(PaymentStatus.REJECTED);
            repository.save(payment);
            auditService.logPaymentCreated(payment);
            throw new PaymentRejectedException(decision.reason());
        }

        payment.setStatus(PaymentStatus.ACCEPTED);
        repository.save(payment);
        auditService.logPaymentCreated(payment);

        // In production: publish event to settlement/ledger workflow here.
        return payment;
    }
}
```

