    public PaymentController(PaymentService paymentService) {
        this.paymentService = paymentService;
    }

    @PostMapping
    public ResponseEntity<PaymentResponse> create(@Valid @RequestBody CreatePaymentRequest request) {
        Payment payment = paymentService.createPayment(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(toResponse(payment));
    }

    @ExceptionHandler(DuplicatePaymentException.class)
    public ResponseEntity<?> handleDuplicate(DuplicatePaymentException ex) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new ErrorResponse("DUPLICATE_PAYMENT", ex.getMessage()));
    }

    @ExceptionHandler(PaymentRejectedException.class)
    public ResponseEntity<?> handleRejected(PaymentRejectedException ex) {
        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(new ErrorResponse("PAYMENT_REJECTED", ex.getMessage()));
    }

    record ErrorResponse(String code, String message) {}

    private PaymentResponse toResponse(Payment p) {
        return new PaymentResponse(
                p.getPaymentId(),
                p.getIdempotencyKey(),
                p.getDebtorAccount(),
                p.getCreditorAccount(),
                p.getAmount(),
                p.getCurrency(),
                p.getStatus(),
                p.getCreatedAt(),
                p.getUpdatedAt()
        );
    }
}
