  if (!req.idempotencyKey || req.idempotencyKey.trim().length < 8) {
    throw new ValidationError("idempotencyKey is required and must be sufficiently long");
  }
  if (!Number.isInteger(req.amountMinor) || req.amountMinor <= 0) {
    throw new ValidationError("amountMinor must be a positive integer");
  }

  const allowedCurrencies: Currency[] = ["USD", "EUR", "GBP", "JPY"];
  if (!allowedCurrencies.includes(req.currency)) {
    throw new ValidationError("Unsupported currency");
  }

  if (req.amountMinor > 10_000_000_00) {
    throw new ValidationError("Amount exceeds configured limit");
  }
}

/**
 * Audit
 */
function writeAudit(type: string, details: Record<string, unknown>, paymentId?: string, merchantId?: string) {
  const event: AuditEvent = {
    eventId: crypto.randomUUID(),
    type,
    paymentId,
    merchantId,
    timestamp: new Date().toISOString(),
    details,
  };
  auditLog.push(event);

  // In production: send to immutable, centralized audit system
  console.log("[AUDIT]", JSON.stringify(event));
}

/**
 * PSP / Bank gateway adapter interface
 */
interface PaymentGateway {
  authorize(req: PaymentRequest): Promise<{ externalReference: string }>;
  capture(externalReference: string, amountMinor: number): Promise<void>;
}

/**
 * Demo gateway implementation.
 * Replace with real gateway integration, mutual TLS, request signing, etc.
 */
class MockPaymentGateway implements PaymentGateway {
  async authorize(req: PaymentRequest): Promise<{ externalReference: string }> {
    // Simulate network latency
    await new Promise((r) => setTimeout(r, 50));

    // Simulate a basic fraud/risk failure example
    if (req.amountMinor > 50_000_00) {
      throw new ProcessingError("Risk engine declined transaction");
    }

    return { externalReference: `ext_${crypto.randomUUID()}` };
  }

  async capture(externalReference: string, amountMinor: number): Promise<void> {
    await new Promise((r) => setTimeout(r, 50));
    if (!externalReference || amountMinor <= 0) {
      throw new ProcessingError("Capture failed");
    }
  }
}

/**
 * Payment service
 */
class PaymentService {
  constructor(private gateway: PaymentGateway) {}

  /**
   * Create and authorize a payment in an idempotent way.
   */
  async createAndAuthorize(req: PaymentRequest): Promise<PaymentRecord> {
    validatePaymentRequest(req);

    const existingPaymentId = idempotencyIndex.get(req.idempotencyKey);
    if (existingPaymentId) {
      const existing = payments.get(existingPaymentId);
      if (!existing) {
        throw new ProcessingError("Idempotency index corrupt");
      }
      writeAudit("PAYMENT_IDEMPOTENT_REPLAY", { idempotencyKey: req.idempotencyKey }, existing.paymentId, existing.merchantId);
      return existing;
    }

    const paymentId = crypto.randomUUID();
    const now = new Date().toISOString();

    const record: PaymentRecord = {
      paymentId,
      merchantId: req.merchantId,
      amountMinor: req.amountMinor,
      currency: req.currency,
      customerId: req.customerId,
      status: "PENDING",
      createdAt: now,
      updatedAt: now,
      idempotencyKey: req.idempotencyKey,
    };

    payments.set(paymentId, record);
    idempotencyIndex.set(req.idempotencyKey, paymentId);

    writeAudit("PAYMENT_CREATED", { amountMinor: req.amountMinor, currency: req.currency }, paymentId, req.merchantId);

    try {
      const auth = await this.gateway.authorize(req);

      record.status = "AUTHORIZED";
      record.externalReference = auth.externalReference;
      record.updatedAt = new Date().toISOString();

      payments.set(paymentId, record);

      writeAudit(
        "PAYMENT_AUTHORIZED",
        { externalReference: auth.externalReference },
        paymentId,
        req.merchantId
      );

      return record;
    } catch (err: any) {
      record.status = "FAILED";
      record.failureReason = err?.message ?? "Unknown authorization failure";
      record.updatedAt = new Date().toISOString();

      payments.set(paymentId, record);

      writeAudit(
        "PAYMENT_AUTH_FAILED",
        { reason: record.failureReason },
        paymentId,
        req.merchantId
      );

      throw err;
    }
  }

  /**
   * Capture a previously authorized payment.
   */
  async capture(paymentId: string): Promise<PaymentRecord> {
    const record = payments.get(paymentId);
    if (!record) {
      throw new ValidationError("Payment not found");
    }

    if (record.status !== "AUTHORIZED") {
      throw new ProcessingError(`Cannot capture payment in status ${record.status}`);
    }

    if (!record.externalReference) {
      throw new ProcessingError("Missing external reference");
    }

    try {
      await this.gateway.capture(record.externalReference, record.amountMinor);

      record.status = "CAPTURED";
      record.updatedAt = new Date().toISOString();
      payments.set(paymentId, record);

      writeAudit("PAYMENT_CAPTURED", {}, paymentId, record.merchantId);

      return record;
    } catch (err: any) {
      record.status = "FAILED";
      record.failureReason = err?.message ?? "Unknown capture failure";
      record.updatedAt = new Date().toISOString();
      payments.set(paymentId, record);

      writeAudit("PAYMENT_CAPTURE_FAILED", { reason: record.failureReason }, paymentId, record.merchantId);
      throw err;
    }
  }

  getPayment(paymentId: string): PaymentRecord | undefined {
    return payments.get(paymentId);
  }
}

/**
 * Example usage
 */
async function main() {
  const service = new PaymentService(new MockPaymentGateway());

  const payment = await service.createAndAuthorize({
    merchantId: "merchant_123",
    amountMinor: 1250,
    currency: "USD",
    customerId: "cust_456",
    paymentMethodToken: "tok_abc123", // token only, never raw PAN
    idempotencyKey: "idem_01HXYZABCDEF123456",
  });

  console.log("Created payment:", payment);

  const captured = await service.capture(payment.paymentId);
  console.log("Captured payment:", captured);
}

main().catch((err) => {
  console.error("Payment service error:", err);
});
