import { PaymentIntent } from "./types";

export class PaymentStore {
  private payments = new Map<string, PaymentIntent>();
  private idempotencyIndex = new Map<string, string>();

  create(payment: PaymentIntent): PaymentIntent {
    const existingId = payment.idempotencyKey
      ? this.idempotencyIndex.get(payment.idempotencyKey)
      : undefined;

    if (existingId) {
      const existing = this.payments.get(existingId);
      if (existing) return existing;
    }

    this.payments.set(payment.id, payment);
    if (payment.idempotencyKey) {
      this.idempotencyIndex.set(payment.idempotencyKey, payment.id);
    }
    return payment;
  }

  getById(id: string): PaymentIntent | undefined {
    return this.payments.get(id);
  }

  getByIdempotencyKey(key: string): PaymentIntent | undefined {
    const id = this.idempotencyIndex.get(key);
    return id ? this.payments.get(id) : undefined;
  }

  update(payment: PaymentIntent): PaymentIntent {
    this.payments.set(payment.id, payment);
    return payment;
  }
}
