import { randomUUID } from "uuid";
import { PaymentStore } from "./store";
import { PaymentGateway } from "./gateway";
import { CreatePaymentRequest, PaymentIntent } from "./types";

export class PaymentService {
  constructor(
    private store: PaymentStore,
    private gateway: PaymentGateway
  ) {}

  async createPayment(req: CreatePaymentRequest): Promise<PaymentIntent> {
    const existing = this.store.getByIdempotencyKey(req.idempotencyKey);
    if (existing) return existing;

    const now = new Date().toISOString();
    const payment: PaymentIntent = {
      id: randomUUID(),
      amount: req.amount,
      currency: req.currency.toUpperCase(),
      customerId: req.customerId,
      status: "REQUIRES_CONFIRMATION",
      idempotencyKey: req.idempotencyKey,
      createdAt: now,
      updatedAt: now,
      metadata: req.metadata
    };

    return this.store.create(payment);
  }

  async confirmPayment(paymentId: string): Promise<PaymentIntent> {
    const payment = this.store.getById(paymentId);
    if (!payment) {
      throw new Error("PAYMENT_NOT_FOUND");
    }

    if (payment.status === "SUCCEEDED") return payment;
    if (payment.status === "CANCELED") throw new Error("PAYMENT_CANCELED");

    payment.status = "PROCESSING";
    payment.updatedAt = new Date().toISOString();
    this.store.update(payment);

    const result = await this.gateway.authorize({
      paymentId: payment.id,
      amount: payment.amount,
      currency: payment.currency,
      customerId: payment.customerId
    });

    payment.updatedAt = new Date().toISOString();

    if (result.approved) {
      payment.status = "SUCCEEDED";
      delete payment.failureReason;
    } else {
      payment.status = "FAILED";
      payment.failureReason = result.declineReason ?? "DECLINED";
    }

    return this.store.update(payment);
  }

  getPayment(paymentId: string): PaymentIntent | undefined {
    return this.store.getById(paymentId);
  }
}
