package com.bank.payments.infra;

import com.bank.payments.domain.Payment;
import com.bank.payments.repository.PaymentRepository;
import org.springframework.stereotype.Repository;

import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryPaymentRepository implements PaymentRepository {
    private final Map<UUID, Payment> byId = new ConcurrentHashMap<>();
    private final Map<String, UUID> idempotencyIndex = new ConcurrentHashMap<>();

    @Override
    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        UUID id = idempotencyIndex.get(idempotencyKey);
        return id == null ? Optional.empty() : Optional.ofNullable(byId.get(id));
    }

    @Override
    public Optional<Payment> findById(UUID paymentId) {
        return Optional.ofNullable(byId.get(paymentId));
    }

    @Override
    public Payment save(Payment payment) {
        byId.put(payment.getPaymentId(), payment);
        idempotencyIndex.put(payment.getIdempotencyKey(), payment.getPaymentId());
        return payment;
    }
}
