package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import org.springframework.stereotype.Service;

import java.util.Set;

@Service
public class BasicPaymentValidationService implements PaymentValidationService {

    private static final Set<String> SUPPORTED_CURRENCIES = Set.of("USD", "EUR", "GBP", "JPY");

    @Override
    public void validate(CreatePaymentRequest request) {
        if (request == null) throw new IllegalArgumentException("Request is required");
        if (isBlank(request.idempotencyKey)) throw new IllegalArgumentException("Idempotency key is required");
        if (isBlank(request.sourceAccount)) throw new IllegalArgumentException("Source account is required");
        if (isBlank(request.destinationAccount)) throw new IllegalArgumentException("Destination account is required");
        if (request.amount == null || request.amount.signum() <= 0) throw new IllegalArgumentException("Amount must be positive");
        if (isBlank(request.currency)) throw new IllegalArgumentException("Currency is required");
        if (!SUPPORTED_CURRENCIES.contains(request.currency.toUpperCase())) {
            throw new IllegalArgumentException("Unsupported currency");
        }
        if (request.sourceAccount.equals(request.destinationAccount)) {
            throw new IllegalArgumentException("Source and destination accounts must differ");
        }
    }

    private boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
