```java
package com.bank.payments.service;

import com.bank.payments.api.dto.CreatePaymentRequest;
import com.bank.payments.domain.Money;
import com.bank.payments.domain.Payment;
import com.bank.payments.domain.PaymentStatus;
import com.bank.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentValidationService validationService;
    private final PaymentProcessingService processingService;
    private final AuditService auditService;

    public PaymentService(PaymentRepository paymentRepository,
                          PaymentValidationService validationService,
                          PaymentProcessingService processingService,
                          AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.validationService = validationService;
        this.processingService = processingService;
        this.auditService = auditService;
    }

    public Payment createPayment(CreatePaymentRequest request) {
        validationService.validate(request);

        return paymentRepository.findByIdempotencyKey(request.idempotencyKey)
                .orElseGet(() -> {
                    Payment payment = new Payment(
                            UUID.randomUUID(),
                            request.idempotencyKey,
                            request.sourceAccount,
                            request.destinationAccount,
                            new Money(request.amount, request.currency),
                            PaymentStatus.RECEIVED,
                            Instant.now(),
                            Instant.now()
                    );

                    auditService.record("PAYMENT_RECEIVED", payment);
                    payment.setStatus(PaymentStatus.VALIDATED);
                    auditService.record("PAYMENT_VALIDATED", payment);

                    payment.setStatus(PaymentStatus.PENDING_PROCESSING);
                    paymentRepository.save(payment);
                    auditService.record("PAYMENT_PENDING_PROCESSING", payment);

                    // For initial version, process synchronously.
                    // In production, hand off to async queue / workflow engine.
                    processingService.process(payment);
                    paymentRepository.save(payment);
                    return payment;
                });
    }

    public Payment getPayment(UUID paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found"));
    }
}
