## Implementation
```java
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;

@Service
public class PaymentServiceImpl implements PaymentService {

    private final PaymentRepository paymentRepository;
    private final PaymentProcessingPublisher processingPublisher;
    private final AuditService auditService;

    public PaymentServiceImpl(
            PaymentRepository paymentRepository,
            PaymentProcessingPublisher processingPublisher,
            AuditService auditService) {
        this.paymentRepository = paymentRepository;
        this.processingPublisher = processingPublisher;
        this.auditService = auditService;
    }

    @Override
    @Transactional
    public PaymentResponse createPayment(PaymentRequest request) {
        paymentRepository.findByIdempotencyKey(request.getIdempotencyKey())
                .ifPresent(existing -> {
                    throw new DuplicatePaymentException(existing.getPaymentId(), existing.getStatus());
                });

        Payment payment = new Payment();
        payment.setIdempotencyKey(request.getIdempotencyKey());
        payment.setSourceAccount(request.getSourceAccount());
        payment.setDestinationAccount(request.getDestinationAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency().toUpperCase());
        payment.setPaymentRail(request.getPaymentRail());
        payment.setReference(request.getReference());
        payment.setStatus(PaymentStatus.RECEIVED);
        payment.setCreatedAt(Instant.now());
        payment.setUpdatedAt(Instant.now());

        Payment saved = paymentRepository.save(payment);

        auditService.record("PAYMENT_RECEIVED", saved.getPaymentId(), request.getIdempotencyKey());
        processingPublisher.publish(saved.getPaymentId());

        return new PaymentResponse(
                saved.getPaymentId(),
                saved.getIdempotencyKey(),
                saved.getStatus(),
                saved.getCreatedAt()
        );
    }

    @Override
    public Payment getPaymentById(String paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentNotFoundException(paymentId));
    }

    @Override
    public Payment getPaymentByIdempotencyKey(String key) {
        return paymentRepository.findByIdempotencyKey(key)
                .orElseThrow(() -> new PaymentNotFoundException("idempotencyKey=" + key));
    }
}
```

