package com.bank.payments.domain;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.Map;
import java.util.UUID;

public class Payment {
    private final String paymentId;
    private final String idempotencyKey;
    private final String clientReference;
    private final String debtorAccount;
    private final String creditorAccount;
    private final BigDecimal amount;
    private final String currency;
    private final PaymentRail rail;
    private PaymentStatus status;
    private final Instant requestedAt;
    private Instant updatedAt;
    private String failureReason;
    private final Map<String, String> metadata;

    public Payment(String idempotencyKey,
                   String clientReference,
                   String debtorAccount,
                   String creditorAccount,
                   BigDecimal amount,
                   String currency,
                   PaymentRail rail,
                   Map<String, String> metadata) {
        this.paymentId = "pay_" + UUID.randomUUID().toString().replace("-", "");
        this.idempotencyKey = idempotencyKey;
        this.clientReference = clientReference;
        this.debtorAccount = debtorAccount;
        this.creditorAccount = creditorAccount;
        this.amount = amount;
        this.currency = currency;
        this.rail = rail;
        this.status = PaymentStatus.RECEIVED;
        this.requestedAt = Instant.now();
        this.updatedAt = this.requestedAt;
        this.metadata = metadata;
    }

    public void markPending() {
        this.status = PaymentStatus.PENDING;
        this.updatedAt = Instant.now();
    }

    public void markPosted() {
        this.status = PaymentStatus.POSTED;
        this.updatedAt = Instant.now();
    }

    public void markFailed(String reason) {
        this.status = PaymentStatus.FAILED;
        this.failureReason = reason;
        this.updatedAt = Instant.now();
    }

    public String getPaymentId() { return paymentId; }
    public String getIdempotencyKey() { return idempotencyKey; }
    public String getClientReference() { return clientReference; }
    public String getDebtorAccount() { return debtorAccount; }
    public String getCreditorAccount() { return creditorAccount; }
    public BigDecimal getAmount() { return amount; }
    public String getCurrency() { return currency; }
    public PaymentRail getRail() { return rail; }
    public PaymentStatus getStatus() { return status; }
    public Instant getRequestedAt() { return requestedAt; }
    public Instant getUpdatedAt() { return updatedAt; }
    public String getFailureReason() { return failureReason; }
    public Map<String, String> getMetadata() { return metadata; }
}
