```java
package com.bank.payments.infrastructure;

import com.bank.payments.domain.Payment;
import com.bank.payments.repository.PaymentRepository;
import org.springframework.stereotype.Repository;

import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

@Repository
public class InMemoryPaymentRepository implements PaymentRepository {

    private final ConcurrentHashMap<String, Payment> byIdempotencyKey = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Payment> byPaymentId = new ConcurrentHashMap<>();

    @Override
    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        return Optional.ofNullable(byIdempotencyKey.get(idempotencyKey));
    }

    @Override
    public Optional<Payment> findByPaymentId(String paymentId) {
        return Optional.ofNullable(byPaymentId.get(paymentId));
    }

    @Override
    public Payment save(Payment payment) {
        byIdempotencyKey.put(payment.getIdempotencyKey(), payment);
        byPaymentId.put(payment.getPaymentId(), payment);
        return payment;
    }
}
