### `PaymentApplicationService.java`
```java
package com.bank.payments.service;

import com.bank.payments.domain.Payment;
import com.bank.payments.dto.CreatePaymentRequest;
import com.bank.payments.infrastructure.PaymentEventPublisher;
import com.bank.payments.repository.PaymentRepository;
import org.springframework.stereotype.Service;

@Service
public class PaymentApplicationService {

    private final PaymentRepository repository;
    private final PaymentEventPublisher eventPublisher;

    public PaymentApplicationService(PaymentRepository repository, PaymentEventPublisher eventPublisher) {
        this.repository = repository;
        this.eventPublisher = eventPublisher;
    }

    public Payment createPayment(CreatePaymentRequest request) {
        return repository.findByIdempotencyKey(request.getIdempotencyKey())
                .orElseGet(() -> {
                    Payment payment = new Payment(
                            request.getIdempotencyKey(),
                            request.getClientReference(),
                            request.getDebtorAccount(),
                            request.getCreditorAccount(),
                            request.getAmount(),
                            request.getCurrency(),
                            request.getRail(),
                            request.getMetadata()
                    );
                    repository.save(payment);
                    eventPublisher.publishPaymentCreated(payment);
                    return payment;
                });
    }

    public Payment getPayment(String paymentId) {
        return repository.findByPaymentId(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Payment not found: " + paymentId));
    }
}
```

