package com.bank.payments.controller;

import com.bank.payments.domain.Payment;
import com.bank.payments.dto.CreatePaymentRequest;
import com.bank.payments.dto.PaymentResponse;
import com.bank.payments.service.PaymentApplicationService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/v1/payments")
public class PaymentController {

    private final PaymentApplicationService service;

    public PaymentController(PaymentApplicationService service) {
        this.service = service;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.ACCEPTED)
    public PaymentResponse createPayment(@Valid @RequestBody CreatePaymentRequest request) {
        Payment payment = service.createPayment(request);
        return new PaymentResponse(
                payment.getPaymentId(),
                payment.getStatus(),
                payment.getClientReference(),
                payment.getRequestedAt()
        );
    }

    @GetMapping("/{paymentId}")
    public PaymentResponse getPayment(@PathVariable String paymentId) {
        Payment payment = service.getPayment(paymentId);
        return new PaymentResponse(
                payment.getPaymentId(),
                payment.getStatus(),
                payment.getClientReference(),
                payment.getRequestedAt()
        );
    }
}
