## `src/modules/customer/customer.service.ts`

```ts
import { randomUUID } from 'crypto';
import { AppError } from '../../common/errors/app-error';
import { CreateCustomerInput, Customer } from './customer.schema';
import { CustomerRepository, CustomerRecord } from './customer.types';
import { CrmClient } from '../integrations/crm.client';
import { ErpClient } from '../integrations/erp.client';

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CrmClient,
    private readonly erpClient: ErpClient
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findById(input.externalId ?? '');
    if (input.externalId && existing) {
      throw new AppError('CUSTOMER_ALREADY_EXISTS', 'Customer already exists', 409);
    }

    const id = randomUUID();
    const record: CustomerRecord = {
      id,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      externalId: input.externalId,
      createdAt: new Date()
    };

    const saved = await this.repository.save(record);

    await this.crmClient.createContact({
      firstName: saved.firstName,
      lastName: saved.lastName,
      email: saved.email
    });

    await this.erpClient.syncCustomer({
      customerId: saved.id,
      fullName: `${saved.firstName} ${saved.lastName}`,
      email: saved.email,
      externalId: saved.externalId
    });

    return {
      id: saved.id,
      firstName: saved.firstName,
      lastName: saved.lastName,
      email: saved.email,
      externalId: saved.externalId,
      createdAt: saved.createdAt.toISOString()
    };
  }
}
```

