import { Injectable, Logger } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';

@Injectable()
export class SapClientService {
  private readonly logger = new Logger(SapClientService.name);
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.SAP_BASE_URL,
      timeout: 5000
    });
  }

  async syncOrder(orderId: string): Promise<void> {
    if (!process.env.SAP_BASE_URL) {
      this.logger.warn(`SAP integration disabled; skipping sync for order ${orderId}`);
      return;
    }

    await this.client.post('/orders/sync', { orderId });
    this.logger.log(`Synced order ${orderId} to SAP`);
  }
}
