import { Injectable } from '@nestjs/common';
import axios from 'axios';

@Injectable()
export class ErpClientService {
  async notifyOrderCreated(payload: {
    orderId: string;
    customerId: string;
    amountCents: number;
  }): Promise<void> {
    if (!process.env.ERP_BASE_URL || !process.env.ERP_API_KEY) return;

    await axios.post(
      `${process.env.ERP_BASE_URL}/orders`,
      payload,
      {
        headers: {
          Authorization: `Bearer ${process.env.ERP_API_KEY}`
        },
        timeout: 5000
      }
    );
  }
}
