## Service layer

### `src/modules/orders/orders.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { OrdersRepository } from './orders.repository';
import { SapClientService } from '@integrations/sap/sap-client.service';
import { ErpClientService } from '@integrations/erp/erp-client.service';

@Injectable()
export class OrdersService {
  constructor(
    private readonly ordersRepository: OrdersRepository,
    private readonly sapClient: SapClientService,
    private readonly erpClient: ErpClientService
  ) {}

  async createOrder(input: {
    customerId: string;
    externalId?: string;
    amountCents: number;
  }) {
    const order = await this.ordersRepository.create({
      customerId: input.customerId,
      externalId: input.externalId,
      amountCents: input.amountCents,
      status: 'PENDING'
    });

    await Promise.allSettled([
      this.sapClient.syncOrder(order.id),
      this.erpClient.notifyOrderCreated({
        orderId: order.id,
        customerId: order.customerId,
        amountCents: order.amountCents
      })
    ]);

    return order;
  }

  async getOrder(id: string) {
    return this.ordersRepository.findById(id);
  }
}
```

