## 13) Service layer: `src/modules/employees/employees.service.ts`

```ts
import { ConflictException, Injectable } from '@nestjs/common';
import { CreateEmployeeDto } from './dto/create-employee.dto';
import { EmployeeRepositoryPort } from './ports/employee-repository.port';
import { CorporatePimClientPort } from './ports/corporate-pim.client';

@Injectable()
export class EmployeesService {
  constructor(
    private readonly employeeRepo: EmployeeRepositoryPort,
    private readonly pimClient: CorporatePimClientPort
  ) {}

  async createEmployee(dto: CreateEmployeeDto) {
    const existingByEmail = await this.employeeRepo.findByEmail(dto.email);
    if (existingByEmail) {
      throw new ConflictException('Employee email already exists');
    }

    const existingByNo = await this.employeeRepo.findByEmployeeNo(dto.employeeNo);
    if (existingByNo) {
      throw new ConflictException('Employee number already exists');
    }

    const employee = await this.employeeRepo.create({
      employeeNo: dto.employeeNo,
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email
    });

    const corporateRecord = await this.pimClient.provisionEmployee(dto);

    return {
      employee,
      corporateRecord
    };
  }
}
```

