## `src/application/use-cases/create-customer.ts`

```ts
import { randomUUID } from "node:crypto";
import { ConflictError, NotFoundError } from "../../shared/errors.js";
import { Customer } from "../../domain/customer.js";
import { CustomerRepository } from "../ports/customer-repository.js";
import { CorporateDirectory } from "../ports/corporate-directory.js";

export interface CreateCustomerInput {
  employeeNumber: string;
}

export class CreateCustomer {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectory: CorporateDirectory
  ) {}

  async execute(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.customerRepository.findByEmployeeNumber(input.employeeNumber);
    if (existing) {
      throw new ConflictError("Customer already exists for employee number");
    }

    const employee = await this.corporateDirectory.getEmployeeByNumber(input.employeeNumber);
    if (!employee) {
      throw new NotFoundError("Employee not found in corporate directory");
    }

    if (!employee.active) {
      throw new ConflictError("Employee is not active");
    }

    const customer: Customer = {
      id: randomUUID(),
      employeeNumber: employee.employeeNumber,
      fullName: employee.fullName,
      email: employee.email,
      createdAt: new Date()
    };

    return this.customerRepository.save(customer);
  }
}
```

