## `src/infrastructure/corporate/sap-directory-client.ts`

```ts
import axios, { AxiosInstance } from "axios";
import { CorporateDirectory, CorporateEmployee } from "../../application/ports/corporate-directory.js";
import { ExternalServiceError } from "../../shared/errors.js";

export class SapDirectoryClient implements CorporateDirectory {
  private readonly http: AxiosInstance;

  constructor(baseURL: string, apiKey: string) {
    this.http = axios.create({
      baseURL,
      timeout: 5000,
      headers: {
        "X-API-Key": apiKey
      }
    });
  }

  async getEmployeeByNumber(employeeNumber: string): Promise<CorporateEmployee | null> {
    try {
      const response = await this.http.get(`/employees/${encodeURIComponent(employeeNumber)}`);

      if (response.status === 404) return null;

      const data = response.data as unknown;
      if (
        typeof data === "object" &&
        data !== null &&
        "employeeNumber" in data &&
        "fullName" in data &&
        "email" in data &&
        "active" in data
      ) {
        const employee = data as CorporateEmployee;
        return employee;
      }

      throw new ExternalServiceError("Invalid SAP response shape");
    } catch (err: any) {
      if (err?.response?.status === 404) return null;
      throw new ExternalServiceError("Failed to query SAP directory");
    }
  }
}
```

