## `src/infrastructure/db/postgres-customer-repository.ts`

```ts
import { CustomerRepository } from "../../application/ports/customer-repository.js";
import { Customer } from "../../domain/customer.js";

export class PostgresCustomerRepository implements CustomerRepository {
  constructor(private readonly connection: {
    query<T = any>(sql: string, params?: unknown[]): Promise<{ rows: T[] }>;
  }) {}

  async findById(id: string): Promise<Customer | null> {
    const result = await this.connection.query<{
      id: string;
      employee_number: string;
      full_name: string;
      email: string;
      created_at: string;
    }>(
      `SELECT id, employee_number, full_name, email, created_at
       FROM customers
       WHERE id = $1`,
      [id]
    );

    if (result.rows.length === 0) return null;

    const row = result.rows[0]!;
    return {
      id: row.id,
      employeeNumber: row.employee_number,
      fullName: row.full_name,
      email: row.email,
      createdAt: new Date(row.created_at)
    };
  }

  async findByEmployeeNumber(employeeNumber: string): Promise<Customer | null> {
    const result = await this.connection.query<{
      id: string;
      employee_number: string;
      full_name: string;
      email: string;
      created_at: string;
    }>(
      `SELECT id, employee_number, full_name, email, created_at
       FROM customers
       WHERE employee_number = $1`,
      [employeeNumber]
    );

    if (result.rows.length === 0) return null;

    const row = result.rows[0]!;
    return {
      id: row.id,
      employeeNumber: row.employee_number,
      fullName: row.full_name,
      email: row.email,
      createdAt: new Date(row.created_at)
    };
  }

  async save(customer: Customer): Promise<Customer> {
    await this.connection.query(
      `INSERT INTO customers (id, employee_number, full_name, email, created_at)
       VALUES ($1, $2, $3, $4, $5)`,
      [
        customer.id,
        customer.employeeNumber,
        customer.fullName,
        customer.email,
        customer.createdAt.toISOString()
      ]
    );

    return customer;
  }
}
```

