## `src/infrastructure/http/routes/customer-routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CreateCustomer } from "../../../application/use-cases/create-customer.js";
import { GetCustomer } from "../../../application/use-cases/get-customer.js";

const CreateCustomerBodySchema = z.object({
  employeeNumber: z.string().min(1)
});

const IdParamsSchema = z.object({
  id: z.string().uuid()
});

export async function customerRoutes(app: FastifyInstance) {
  const createCustomer = app.di.createCustomer as CreateCustomer;
  const getCustomer = app.di.getCustomer as GetCustomer;

  app.post(
    "/customers",
    { preHandler: app.authenticate },
    async (request, reply) => {
      const body = CreateCustomerBodySchema.parse(request.body);
      const customer = await createCustomer.execute(body);
      reply.status(201).send({
        id: customer.id,
        employeeNumber: customer.employeeNumber,
        fullName: customer.fullName,
        email: customer.email,
        createdAt: customer.createdAt.toISOString()
      });
    }
  );

  app.get(
    "/customers/:id",
    { preHandler: app.authenticate },
    async (request, reply) => {
      const params = IdParamsSchema.parse(request.params);
      const customer = await getCustomer.execute(params.id);

      reply.send({
        id: customer.id,
        employeeNumber: customer.employeeNumber,
        fullName: customer.fullName,
        email: customer.email,
        createdAt: customer.createdAt.toISOString()
      });
    }
  );
}

declare module "fastify" {
  interface FastifyInstance {
    di: {
      createCustomer: CreateCustomer;
      getCustomer: GetCustomer;
    };
  }
}
