  const app = await buildApp();

  const customerRepository = new PostgresCustomerRepository(fakeDb);
  const corporateDirectory = new SapDirectoryClient(env.SAP_BASE_URL, env.SAP_API_KEY);

  app.decorate("di", {
    createCustomer: new CreateCustomer(customerRepository, corporateDirectory),
    getCustomer: new GetCustomer(customerRepository)
  });

  await app.listen({ port: env.PORT, host: "0.0.0.0" });
  logger.info({ port: env.PORT }, "Service started");
}

