import axios, { AxiosInstance } from "axios";
import { IntegrationError } from "../errors.js";
import type { Customer } from "../schemas/customer.js";

export class CorporateCrmClient {
  private readonly http: AxiosInstance;

  constructor(
    baseURL: string,
    apiKey: string
  ) {
    this.http = axios.create({
      baseURL,
      timeout: 5000,
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey
      }
    });
  }

  async createCustomer(payload: {
    firstName: string;
    lastName: string;
    email: string;
  }): Promise<Customer> {
    try {
      const response = await this.http.post<Customer>("/customers", payload);
      return response.data;
    } catch (err) {
      throw new IntegrationError("Failed to create customer in corporate CRM");
    }
  }

  async getCustomerById(id: string): Promise<Customer | null> {
    try {
      const response = await this.http.get<Customer>(`/customers/${id}`);
      return response.data;
    } catch (err: unknown) {
      if (axios.isAxiosError(err) && err.response?.status === 404) {
        return null;
      }
      throw new IntegrationError("Failed to fetch customer from corporate CRM");
    }
  }
}
