import type { FastifyPluginAsync } from "fastify";
import { CreateCustomerRequestSchema, CustomerIdSchema } from "../schemas/customer.js";
import { ValidationError } from "../errors.js";
import type { CustomerService } from "../services/customerService.js";

export function customerRoutes(service: CustomerService): FastifyPluginAsync {
  return async (app) => {
    app.post("/v1/customers", async (request, reply) => {
      const parsed = CreateCustomerRequestSchema.safeParse(request.body);
      if (!parsed.success) {
        throw new ValidationError("Invalid customer creation payload");
      }

      const customer = await service.createCustomer(parsed.data);
      return reply.code(201).send(customer);
    });

    app.get("/v1/customers/:id", async (request) => {
      const parsed = CustomerIdSchema.safeParse((request.params as { id?: unknown }).id);
      if (!parsed.success) {
        throw new ValidationError("Invalid customer ID");
      }

      return service.getCustomer(parsed.data);
    });
  };
}
