import Fastify from "fastify";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customer.js";
import { AppError } from "./errors.js";
import type { AppConfig } from "./config.js";
import type { Logger } from "./logger.js";
import { CorporateCrmClient } from "./integrations/corporateCrmClient.js";
import { CustomerService } from "./services/customerService.js";

export function buildApp(config: AppConfig, logger: Logger) {
  const app = Fastify({
    logger
  });

  const crmClient = new CorporateCrmClient(
    config.CORPORATE_CRM_BASE_URL,
    config.CORPORATE_CRM_API_KEY
  );

  const customerService = new CustomerService(crmClient);

  app.register(healthRoutes);
  app.register(customerRoutes(customerService));

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      reply.status(error.statusCode).send({
        error: error.code,
        message: error.message
      });
      return;
    }

    logger.error({ err: error }, "Unhandled error");
    reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });

  return app;
}
