import { randomUUID } from "node:crypto";
import { Customer } from "../domain/customer.js";
import { CorporateSystemClient } from "../integration/corporateSystem.client.js";
import { CustomerRepository } from "../repositories/customer.repository.js";
import { NotFoundError } from "../utils/errors.js";

export interface CreateCustomerInput {
  externalReference: string;
  fullName: string;
  email: string;
}

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly corporateClient: CorporateSystemClient
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const now = new Date();
    const customer: Customer = {
      id: randomUUID(),
      externalReference: input.externalReference,
      fullName: input.fullName,
      email: input.email,
      status: "ACTIVE",
      createdAt: now,
      updatedAt: now
    };

    const saved = await this.repository.save(customer);
    await this.corporateClient.syncCustomer({
      externalReference: saved.externalReference,
      fullName: saved.fullName,
      email: saved.email
    });

    return saved;
  }

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer ${id} not found`);
    }
    return customer;
  }
}
