import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "../services/customer.service.js";
import { ValidationError } from "../utils/errors.js";

const createCustomerSchema = z.object({
  externalReference: z.string().min(1),
  fullName: z.string().min(1),
  email: z.string().email()
});

export async function customerRoutes(
  app: FastifyInstance,
  service: CustomerService
): Promise<void> {
  app.post("/customers", async (request, reply) => {
    const parsed = createCustomerSchema.safeParse(request.body);
    if (!parsed.success) {
      throw new ValidationError(parsed.error.message);
    }

    const customer = await service.createCustomer(parsed.data);
    return reply.code(201).send(customer);
  });

  app.get("/customers/:id", async (request) => {
    const params = z.object({ id: z.string().uuid() }).safeParse(request.params);
    if (!params.success) {
      throw new ValidationError(params.error.message);
    }

    return service.getCustomer(params.data.id);
  });
}
