import Fastify from "fastify";
import { customerRoutes } from "./controllers/customer.controller.js";
import { HttpCorporateSystemClient } from "./integration/corporateSystem.client.js";
import { InMemoryCustomerRepository } from "./repositories/customer.repository.pg.js";
import { CustomerService } from "./services/customer.service.js";
import { AppError } from "./utils/errors.js";
import { logger } from "./utils/logger.js";

export function buildApp() {
  const app = Fastify({ logger });

  const repository = new InMemoryCustomerRepository();
  const corporateClient = new HttpCorporateSystemClient();
  const service = new CustomerService(repository, corporateClient);

  app.get("/health", async () => ({
    status: "ok"
  }));

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) {
      request.log.warn({ err: error }, "application error");
      return reply.status(error.statusCode).send({
        error: error.code,
        message: error.message
      });
    }

    request.log.error({ err: error }, "unhandled error");
    return reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "Unexpected error"
    });
  });

  void app.register(async (instance) => {
    await customerRoutes(instance, service);
  });

  return app;
}
