import type { FastifyInstance } from "fastify";
import { customerIdSchema, createCustomerSchema } from "../schemas/customer.js";
import { CustomerService } from "../services/customerService.js";
import { CorporateSystemClient } from "../clients/corporateSystemClient.js";
import { NotFoundError } from "../utils/errors.js";

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const customerService = new CustomerService(new CorporateSystemClient());

  app.get("/customers/:id", async (request, reply) => {
    const parsed = customerIdSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid customer id"
      });
    }

    try {
      return await customerService.getCustomer(parsed.data.id);
    } catch (error: unknown) {
      if (error instanceof NotFoundError) {
        return reply.status(404).send({ error: error.message });
      }
      throw error;
    }
  });

  app.post("/customers", async (request, reply) => {
    const parsed = createCustomerSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    try {
      const created = await customerService.createCustomer(parsed.data);
      return reply.status(201).send(created);
    } catch (error: unknown) {
      return reply.status(500).send({
        error: "Failed to create customer"
      });
    }
  });
}
