## 7) Repository: `src/repositories/customer.repository.ts`

```ts
import type { Customer, CustomerId, CreateCustomerInput } from "../domain/customer.js";

export interface CustomerRepository {
  create(input: CreateCustomerInput): Promise<Customer>;
  findById(id: CustomerId): Promise<Customer | null>;
  update(customer: Customer): Promise<Customer>;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly store = new Map<CustomerId, Customer>();

  async create(input: CreateCustomerInput): Promise<Customer> {
    const now = new Date().toISOString();
    const customer: Customer = {
      id: crypto.randomUUID(),
      name: input.name,
      email: input.email,
      createdAt: now,
      updatedAt: now
    };

    this.store.set(customer.id, customer);
    return customer;
  }

  async findById(id: CustomerId): Promise<Customer | null> {
    return this.store.get(id) ?? null;
  }

  async update(customer: Customer): Promise<Customer> {
    this.store.set(customer.id, customer);
    return customer;
  }
}
```

