import { request } from "undici";
import type { Customer } from "../domain/customer.js";
import { IntegrationError } from "../utils/errors.js";
import type { Env } from "../config/env.js";

export class CrmIntegration {
  constructor(private readonly env: Env) {}

  async syncCustomer(customer: Customer): Promise<{ crmId: string }> {
    const res = await request(`${this.env.CRM_BASE_URL}/customers`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${this.env.CRM_API_KEY}`
      },
      body: JSON.stringify({
        name: customer.name,
        email: customer.email
      })
    });

    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw new IntegrationError("CRM sync failed", { statusCode: res.statusCode });
    }

    const body = (await res.body.json()) as { id: string };
    return { crmId: body.id };
  }
}
