## 9) Service layer: `src/services/customer.service.ts`

```ts
import type { Customer, CreateCustomerInput, CustomerId } from "../domain/customer.js";
import type { CustomerRepository } from "../repositories/customer.repository.js";
import { NotFoundError } from "../utils/errors.js";
import { CrmIntegration } from "../integrations/crm.integration.js";
import { ErpIntegration } from "../integrations/erp.integration.js";
import { EventPublisher } from "../integrations/event.publisher.js";

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly crm: CrmIntegration,
    private readonly erp: ErpIntegration,
    private readonly publisher: EventPublisher
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const customer = await this.repo.create(input);

    const [{ crmId }, { erpId }] = await Promise.all([
      this.crm.syncCustomer(customer),
      this.erp.provisionCustomer(customer)
    ]);

    const updated: Customer = {
      ...customer,
      externalCrmId: crmId,
      externalErpId: erpId,
      updatedAt: new Date().toISOString()
    };

    await this.repo.update(updated);
    await this.publisher.publishCustomerCreated(updated);

    return updated;
  }

  async getCustomerById(id: CustomerId): Promise<Customer> {
    const customer = await this.repo.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer ${id} not found`);
    }
    return customer;
  }
}
```

