## 10) Controller: `src/controllers/customer.controller.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import {
  CreateCustomerSchema,
  CustomerIdSchema
} from "../domain/customer.js";
import { ValidationError } from "../utils/errors.js";
import type { CustomerService } from "../services/customer.service.js";

export class CustomerController {
  constructor(private readonly service: CustomerService) {}

  create = async (req: FastifyRequest, reply: FastifyReply) => {
    const parsed = CreateCustomerSchema.safeParse(req.body);
    if (!parsed.success) {
      throw new ValidationError("Invalid customer payload", parsed.error.flatten());
    }

    const customer = await this.service.createCustomer(parsed.data);
    return reply.code(201).send(customer);
  };

  getById = async (
    req: FastifyRequest<{ Params: { id: string } }>,
    reply: FastifyReply
  ) => {
    const idParsed = CustomerIdSchema.safeParse(req.params.id);
    if (!idParsed.success) {
      throw new ValidationError("Invalid customer id", idParsed.error.flatten());
    }

    const customer = await this.service.getCustomerById(idParsed.data);
    return reply.send(customer);
  };
}
