## 12) App bootstrap: `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { logger } from "./utils/logger.js";
import { loadEnv } from "./config/env.js";
import { InMemoryCustomerRepository } from "./repositories/customer.repository.js";
import { CrmIntegration } from "./integrations/crm.integration.js";
import { ErpIntegration } from "./integrations/erp.integration.js";
import { EventPublisher } from "./integrations/event.publisher.js";
import { CustomerService } from "./services/customer.service.js";
import { CustomerController } from "./controllers/customer.controller.js";
import { customerRoutes } from "./routes/customer.routes.js";
import { AppError } from "./utils/errors.js";

declare module "fastify" {
  interface FastifyInstance {
    diContainer: {
      customerController: CustomerController;
    };
  }
}

export async function buildApp() {
  const env = loadEnv();

  const app = Fastify({
    logger
  });

  await app.register(sensible);

  const repo = new InMemoryCustomerRepository();
  const crm = new CrmIntegration(env);
  const erp = new ErpIntegration(env);
  const publisher = new EventPublisher(env);
  const service = new CustomerService(repo, crm, erp, publisher);
  const controller = new CustomerController(service);

  app.decorate("diContainer", {
    customerController: controller
  });

  app.setErrorHandler((err, req, reply) => {
    req.log.error({ err }, "request failed");

    if (err instanceof AppError) {
      return reply.status(err.statusCode).send({
        error: {
          code: err.code,
          message: err.message,
          details: err.details ?? null
        }
      });
    }

    return reply.status(500).send({
      error: {
        code: "INTERNAL_SERVER_ERROR",
        message: "An unexpected error occurred"
      }
    });
  });

  app.get("/health", async () => ({
    status: "ok"
  }));

  await app.register(customerRoutes);

  return app;
}
```

