import type { CustomerRepository, CorporateIdentityClient } from "../ports.js";
import { NotFoundError } from "../../domain/errors.js";

export interface CustomerDetailsDTO {
  readonly id: string;
  readonly fullName: string;
  readonly email: string;
  readonly status: string;
  readonly corporate: {
    readonly employeeNumber: string;
    readonly managerEmail: string | null;
    readonly department: string;
  };
}

export class CustomerService {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateIdentityClient: CorporateIdentityClient
  ) {}

  async getCustomerDetails(id: string): Promise<CustomerDetailsDTO> {
    const customer = await this.customerRepository.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer ${id} not found`);
    }

    const token = await this.corporateIdentityClient.getAccessToken();
    const corporateProfile = await this.corporateIdentityClient.fetchCustomerProfile(
      customer.externalReference,
      token
    );

    return {
      id: customer.id,
      fullName: customer.fullName,
      email: customer.email,
      status: customer.status,
      corporate: {
        employeeNumber: corporateProfile.employeeNumber,
        managerEmail: corporateProfile.managerEmail,
        department: corporateProfile.department
      }
    };
  }
}
