import { IntegrationError } from "../../domain/errors.js";
import type { Env } from "../../config/env.js";

interface CorporateTokenResponse {
  access_token: string;
  expires_in: number;
}

interface CorporateProfileResponse {
  employeeNumber: string;
  managerEmail: string | null;
  department: string;
}

export class CorporateApiClient implements CorporateIdentityClient {
  private readonly http: AxiosInstance;
  private cachedToken: { value: string; expiresAt: number } | null = null;

  constructor(private readonly env: Env) {
    this.http = axios.create({
      baseURL: env.CORPORATE_API_BASE_URL,
      timeout: 5000,
      headers: {
        "Content-Type": "application/json"
      }
    });
  }

  async getAccessToken(): Promise<string> {
    if (this.cachedToken && Date.now() < this.cachedToken.expiresAt) {
      return this.cachedToken.value;
    }

    try {
      const response = await this.http.post<CorporateTokenResponse>("/oauth/token", {
        client_id: this.env.CORPORATE_API_CLIENT_ID,
        client_secret: this.env.CORPORATE_API_CLIENT_SECRET,
        grant_type: "client_credentials"
      });

      const token = response.data.access_token;
      const expiresInMs = response.data.expires_in * 1000;

      this.cachedToken = {
        value: token,
        expiresAt: Date.now() + Math.max(0, expiresInMs - 30_000)
      };

      return token;
    } catch (error) {
      throw new IntegrationError("Failed to obtain corporate API access token", error);
    }
  }

  async fetchCustomerProfile(
    externalReference: string,
    accessToken: string
  ): Promise<CorporateCustomerProfile> {
    try {
      const response = await this.http.get<CorporateProfileResponse>(
        `/employees/${encodeURIComponent(externalReference)}`,
        {
          headers: {
            Authorization: `Bearer ${accessToken}`
          }
        }
      );

      return {
        employeeNumber: response.data.employeeNumber,
        managerEmail: response.data.managerEmail,
        department: response.data.department
      };
    } catch (error) {
      throw new IntegrationError(
        `Failed to fetch corporate profile for ${externalReference}`,
        error
      );
    }
  }
}
