## `src/interfaces/http/routes.ts`

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import { GetCustomerParamsSchema } from "./schemas.js";
import { NotFoundError, IntegrationError } from "../../domain/errors.js";
import type { CustomerService } from "../../application/services/customer-service.js";

export async function registerRoutes(
  app: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  app.get(
    "/health",
    async () => ({
      status: "ok"
    })
  );

  app.get(
    "/customers/:id",
    async (
      request: FastifyRequest<{ Params: { id: string } }>,
      reply: FastifyReply
    ) => {
      const parsed = GetCustomerParamsSchema.safeParse(request.params);
      if (!parsed.success) {
        return reply.code(400).send({
          error: "Invalid request parameters",
          details: parsed.error.flatten()
        });
      }

      try {
        const customer = await deps.customerService.getCustomerDetails(parsed.data.id);
        return reply.code(200).send(customer);
      } catch (err) {
        if (err instanceof NotFoundError) {
          return reply.code(404).send({ error: err.message });
        }
        if (err instanceof IntegrationError) {
          request.log.error({ err }, "Integration failure");
          return reply.code(502).send({ error: "Upstream corporate system unavailable" });
        }

        request.log.error({ err }, "Unhandled error");
        return reply.code(500).send({ error: "Internal server error" });
      }
    }
  );
}
```

