## `src/modules/customer/customer.service.ts`

```ts
import { ConflictError, NotFoundError } from '../../lib/errors.js';
import { fetchCorporateCustomer } from '../../integrations/corporate-system/corporate.client.js';
import { customerRepo } from './customer.repo.js';
import type { CreateCustomerInput } from './customer.schemas.js';

export const customerService = {
  async register(input: CreateCustomerInput) {
    const existing = await customerRepo.findByExternalId(input.externalId);
    if (existing) throw new ConflictError('Customer already exists');

    const emailExists = await customerRepo.findByEmail(input.email);
    if (emailExists) throw new ConflictError('Email already in use');

    const corporateCustomer = await fetchCorporateCustomer(input.externalId);

    if (corporateCustomer.status !== 'ACTIVE') {
      throw new ConflictError('Corporate customer is not active');
    }

    return customerRepo.create({
      externalId: input.externalId,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email
    });
  },

  async getByExternalId(externalId: string) {
    const customer = await customerRepo.findByExternalId(externalId);
    if (!customer) throw new NotFoundError('Customer not found');
    return customer;
  }
};
```

