## `src/modules/customer/customer.routes.ts`

```ts
import type { FastifyInstance } from 'fastify';
import { createCustomerSchema } from './customer.schemas.js';
import { customerService } from './customer.service.js';
import { requireAuth } from '../../auth/auth.js';

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  app.post(
    '/customers',
    { preHandler: requireAuth },
    async (request, reply) => {
      const input = createCustomerSchema.parse(request.body);
      const customer = await customerService.register(input);
      return reply.code(201).send({
        id: customer.id,
        externalId: customer.externalId,
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email,
        createdAt: customer.createdAt.toISOString(),
        updatedAt: customer.updatedAt.toISOString()
      });
    }
  );

  app.get(
    '/customers/:externalId',
    { preHandler: requireAuth },
    async (request) => {
      const { externalId } = request.params as { externalId: string };
      const customer = await customerService.getByExternalId(externalId);
      return {
        id: customer.id,
        externalId: customer.externalId,
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email,
        createdAt: customer.createdAt.toISOString(),
        updatedAt: customer.updatedAt.toISOString()
      };
    }
  );
}
