## Customer service: `src/modules/customers/customer.service.ts`

```ts
import { prisma } from "../../db/prisma.js";
import { MessageBus } from "../../corporate/message-bus.js";
import { SapClient } from "../../corporate/sap-client.js";
import type { CreateCustomerInput, CustomerDTO } from "./customer.types.js";

export class CustomerService {
  constructor(
    private readonly bus: MessageBus,
    private readonly sap: SapClient
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<CustomerDTO> {
    const customer = await prisma.customer.create({
      data: {
        name: input.name,
        email: input.email
      }
    });

    await this.sap.upsertCustomer({
      externalId: customer.id,
      status: "ACTIVE"
    });

    await this.bus.publish("customer.created", {
      type: "customer.created",
      payload: {
        id: customer.id,
        email: customer.email
      },
      timestamp: new Date().toISOString()
    });

    return {
      id: customer.id,
      name: customer.name,
      email: customer.email,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }

  async getCustomerById(id: string): Promise<CustomerDTO | null> {
    const customer = await prisma.customer.findUnique({ where: { id } });
    if (!customer) return null;

    return {
      id: customer.id,
      name: customer.name,
      email: customer.email,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }
}
```

