## Customer routes: `src/modules/customers/customer.routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "./customer.service.js";
import { MessageBus } from "../../corporate/message-bus.js";
import { SapClient } from "../../corporate/sap-client.js";

const createCustomerSchema = z.object({
  name: z.string().min(1),
  email: z.string().email()
});

export async function customerRoutes(app: FastifyInstance) {
  const service = new CustomerService(
    new MessageBus(),
    new SapClient(process.env.SAP_BASE_URL ?? "")
  );

  app.post(
    "/customers",
    {
      preHandler: [app.authenticate]
    },
    async (request, reply) => {
      const body = createCustomerSchema.parse(request.body);
      const customer = await service.createCustomer(body);
      return reply.code(201).send(customer);
    }
  );

  app.get(
    "/customers/:id",
    {
      preHandler: [app.authenticate]
    },
    async (request, reply) => {
      const params = z.object({ id: z.string().uuid() }).parse(request.params);
      const customer = await service.getCustomerById(params.id);

      if (!customer) {
        return reply.code(404).send({ message: "Customer not found" });
      }

      return reply.send(customer);
    }
  );
}
```

