## `src/infrastructure/corporate/authClient.ts`

```ts
import { env } from "../../config/env.js";

export interface CorporateAuthClient {
  validateBearerToken(token: string): Promise<{ subject: string; roles: string[] } | null>;
}

export class HttpCorporateAuthClient implements CorporateAuthClient {
  async validateBearerToken(token: string): Promise<{ subject: string; roles: string[] } | null> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), env.CORPORATE_AUTH_TIMEOUT_MS);

    try {
      const res = await fetch(`${env.CORPORATE_AUTH_URL}/validate`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        signal: controller.signal,
        body: JSON.stringify({ token })
      });

      if (!res.ok) return null;

      const data: unknown = await res.json();
      if (
        typeof data === "object" &&
        data !== null &&
        "subject" in data &&
        "roles" in data &&
        typeof (data as { subject: unknown }).subject === "string" &&
        Array.isArray((data as { roles: unknown }).roles)
      ) {
        return {
          subject: (data as { subject: string }).subject,
          roles: (data as { roles: string[] }).roles
        };
      }

      return null;
    } finally {
      clearTimeout(timeout);
    }
  }
}
```

