import { env } from "../../config/env.js";
import { CorporateEmployeeSchema, type CorporateEmployee } from "./hrClient.types.js";

export interface CorporateHrClient {
  getEmployeeById(employeeId: string): Promise<CorporateEmployee | null>;
}

export class HttpCorporateHrClient implements CorporateHrClient {
  async getEmployeeById(employeeId: string): Promise<CorporateEmployee | null> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), env.CORPORATE_HR_TIMEOUT_MS);

    try {
      const res = await fetch(`${env.CORPORATE_HR_URL}/employees/${encodeURIComponent(employeeId)}`, {
        method: "GET",
        headers: {
          Accept: "application/json"
        },
        signal: controller.signal
      });

      if (res.status === 404) return null;
      if (!res.ok) throw new Error(`HR system returned HTTP ${res.status}`);

      const data: unknown = await res.json();
      return CorporateEmployeeSchema.parse(data);
    } finally {
      clearTimeout(timeout);
    }
  }
}
