const ParamsSchema = z.object({
  employeeId: z.string().min(1)
});

export async function userRoutes(app: FastifyInstance, deps: { userService: UserService }): Promise<void> {
  app.get("/users/:employeeId", async (request, reply) => {
    const params = ParamsSchema.safeParse(request.params);
    if (!params.success) {
      return reply.code(400).send({
        error: "Invalid path parameters",
        details: params.error.flatten()
      });
    }

    const user = await deps.userService.getUserProfile(params.data.employeeId);
    if (!user) {
      return reply.code(404).send({ error: "User not found" });
    }

    return reply.send(user);
  });
}
