## `src/routes/employee.ts`

```ts
import type { FastifyPluginAsync } from "fastify";
import { CreateEmployeeRequestSchema } from "../schemas/employee.js";
import { EmployeeIdSchema } from "../schemas/common.js";
import type { EmployeeService } from "../services/employeeService.js";

export const employeeRoutes = (service: EmployeeService): FastifyPluginAsync => {
  return async (app) => {
    app.post("/employees", async (request, reply) => {
      const parsed = CreateEmployeeRequestSchema.safeParse(request.body);
      if (!parsed.success) {
        return reply.status(400).send({
          code: "VALIDATION_ERROR",
          message: parsed.error.message
        });
      }

      const employee = await service.createEmployee(parsed.data);
      return reply.status(201).send(employee);
    });

    app.get("/employees/:id", async (request, reply) => {
      const idResult = EmployeeIdSchema.safeParse((request.params as { id?: string }).id);
      if (!idResult.success) {
        return reply.status(400).send({
          code: "INVALID_EMPLOYEE_ID",
          message: "Employee id must be a valid UUID"
        });
      }

      const employee = await service.getEmployee(idResult.data);
      if (!employee) {
        return reply.status(404).send({
          code: "NOT_FOUND",
          message: "Employee not found"
        });
      }

      return reply.send(employee);
    });

    app.post("/employees/:id/sync", async (request, reply) => {
      const idResult = EmployeeIdSchema.safeParse((request.params as { id?: string }).id);
      if (!idResult.success) {
        return reply.status(400).send({
          code: "INVALID_EMPLOYEE_ID",
          message: "Employee id must be a valid UUID"
        });
      }

      const employee = await service.syncFromCorporateHr(idResult.data);
      return reply.send(employee);
    });
  };
};
```

