## `src/services/EmployeeService.ts`

```ts
import { randomUUID } from "node:crypto";
import type { CreateEmployeeInput, Employee } from "../domain/employee.js";
import type { EmployeeRepository } from "../repositories/EmployeeRepository.js";
import type { CorporateHRClient } from "../integrations/CorporateHRClient.js";

export class DuplicateEmployeeError extends Error {
  constructor(employeeNumber: string) {
    super(`Employee already exists: ${employeeNumber}`);
    this.name = "DuplicateEmployeeError";
  }
}

export class EmployeeService {
  constructor(
    private readonly repository: EmployeeRepository,
    private readonly hrClient: CorporateHRClient
  ) {}

  async createEmployee(input: CreateEmployeeInput): Promise<Employee> {
    const existing = await this.repository.findByEmployeeNumber(input.employeeNumber);
    if (existing) {
      throw new DuplicateEmployeeError(input.employeeNumber);
    }

    const now = new Date();
    const employee: Employee = {
      id: randomUUID(),
      employeeNumber: input.employeeNumber,
      fullName: input.fullName,
      department: input.department,
      active: true,
      createdAt: now,
      updatedAt: now
    };

    await this.repository.save(employee);
    await this.hrClient.syncEmployee(employee);

    return employee;
  }

  async getEmployee(id: string): Promise<Employee | null> {
    return this.repository.findById(id);
  }

  async listEmployees(): Promise<Employee[]> {
    return this.repository.findAll();
  }
}
```

