## `src/routes/employeeRoutes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { CreateEmployeeSchema } from "../domain/employee.js";
import { DuplicateEmployeeError } from "../services/EmployeeService.js";

export async function employeeRoutes(app: FastifyInstance): Promise<void> {
  app.post("/employees", async (request, reply) => {
    const parsed = CreateEmployeeSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    try {
      const employee = await app.employeeService.createEmployee(parsed.data);
      return reply.status(201).send(employee);
    } catch (error) {
      if (error instanceof DuplicateEmployeeError) {
        return reply.status(409).send({ error: error.message });
      }
      request.log.error({ error }, "Failed to create employee");
      return reply.status(500).send({ error: "Internal Server Error" });
    }
  });

  app.get("/employees/:id", async (request, reply) => {
    const id = (request.params as { id: string }).id;
    const employee = await app.employeeService.getEmployee(id);

    if (!employee) {
      return reply.status(404).send({ error: "Employee not found" });
    }

    return reply.send(employee);
  });

  app.get("/employees", async (_request, reply) => {
    const employees = await app.employeeService.listEmployees();
    return reply.send(employees);
  });
}
```

