  externalId: z.string().min(1).optional()
});

export type CorporateResponse = z.infer<typeof CorporateResponseSchema>;

export interface CorporateSystemClient {
  registerCustomer(payload: { email: string; name: string }): Promise<CorporateResponse>;
}

export function createCorporateSystemClient(config: {
  baseUrl: string;
  apiKey: string;
}): CorporateSystemClient {
  return {
    async registerCustomer(payload) {
      const res = await fetch(`${config.baseUrl}/customers/register`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${config.apiKey}`
        },
        body: JSON.stringify(payload)
      });

      if (!res.ok) {
        throw new Error(`Corporate system returned HTTP ${res.status}`);
      }

      const json: unknown = await res.json();
      return CorporateResponseSchema.parse(json);
    }
  };
}
