```ts
import { err, ok, type Result } from "../utils/result.js";
import type { CustomerRepository } from "../repositories/customerRepository.js";
import type { CorporateSystemClient } from "../integrations/corporateSystemClient.js";
import { CustomerSchema, type Customer, type CreateCustomerInput } from "../domain/customer.js";

export type CreateCustomerError =
  | "CUSTOMER_ALREADY_EXISTS"
  | "CORPORATE_SYSTEM_ERROR"
  | "VALIDATION_ERROR";

export interface CustomerService {
  createCustomer(input: CreateCustomerInput): Promise<Result<Customer, CreateCustomerError>>;
}

export function createCustomerService(deps: {
  repository: CustomerRepository;
  corporateClient: CorporateSystemClient;
}): CustomerService {
  return {
    async createCustomer(input) {
      const existing = await deps.repository.findByEmail(input.email);
      if (existing) {
        return err("CUSTOMER_ALREADY_EXISTS");
      }

      try {
        await deps.corporateClient.registerCustomer(input);
      } catch (cause) {
        return err("CORPORATE_SYSTEM_ERROR", cause);
      }

      const created = await deps.repository.create(input);

      const parsed = CustomerSchema.safeParse(created);
      if (!parsed.success) {
        return err("VALIDATION_ERROR", parsed.error.flatten());
      }

      return ok(parsed.data);
    }
  };
}
```

