## `src/routes/customerRoutes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { CreateCustomerInputSchema } from "../domain/customer.js";
import type { CustomerService } from "../services/customerService.js";

export async function registerCustomerRoutes(
  app: FastifyInstance,
  deps: { customerService: CustomerService }
): Promise<void> {
  app.post("/customers", async (request, reply) => {
    const inputResult = CreateCustomerInputSchema.safeParse(request.body);

    if (!inputResult.success) {
      return reply.status(400).send({
        error: "VALIDATION_ERROR",
        details: inputResult.error.flatten()
      });
    }

    const result = await deps.customerService.createCustomer(inputResult.data);

    if (!result.ok) {
      switch (result.error) {
        case "CUSTOMER_ALREADY_EXISTS":
          return reply.status(409).send({ error: result.error });
        case "CORPORATE_SYSTEM_ERROR":
          return reply.status(502).send({ error: result.error });
        case "VALIDATION_ERROR":
          return reply.status(500).send({ error: result.error, details: result.details });
      }
    }

    return reply.status(201).send(result.value);
  });
}
```

