```ts
import { randomUUID } from "node:crypto";
import type { AuditClient } from "../integrations/auditClient.js";
import type { CorporateCrmClient } from "../integrations/corporateCrmClient.js";
import type { CreateCustomerInput, Customer } from "../domain/customer.js";

export interface CustomerRepository {
  save(customer: Customer): Promise<void>;
  findById(id: string): Promise<Customer | null>;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly store = new Map<string, Customer>();

  async save(customer: Customer): Promise<void> {
    this.store.set(customer.id, customer);
  }

  async findById(id: string): Promise<Customer | null> {
    return this.store.get(id) ?? null;
  }
}

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient,
    private readonly auditClient: AuditClient
  ) {}

  async createCustomer(input: CreateCustomerInput, actor: string): Promise<Customer> {
    const customer: Customer = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      status: "active",
      createdAt: new Date().toISOString()
    };

    await this.repository.save(customer);
    await this.crmClient.createCustomer(customer);
    await this.auditClient.record({
      action: "CUSTOMER_CREATED",
      actor,
      entityType: "Customer",
      entityId: customer.id,
      timestamp: new Date().toISOString(),
      metadata: { email: customer.email }
    });

    return customer;
  }

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new Error("Customer not found");
    }
    return customer;
  }
}
```

