## `src/routes/customerRoutes.ts`

```ts
import type { FastifyInstance, FastifyRequest } from "fastify";
import { CreateCustomerInputSchema, CustomerIdSchema } from "../domain/customer.js";
import { CustomerService } from "../services/customerService.js";
import { AppError, NotFoundError, ValidationError } from "../utils/errors.js";

type AuthenticatedRequest = FastifyRequest & {
  user: {
    subject: string;
    roles: string[];
  };
};

export async function customerRoutes(app: FastifyInstance, service: CustomerService) {
  app.post("/customers", async (request, reply) => {
    const parseResult = CreateCustomerInputSchema.safeParse(request.body);
    if (!parseResult.success) {
      throw new ValidationError("Invalid customer payload", parseResult.error.flatten());
    }

    const user = (request as AuthenticatedRequest).user;
    if (!user) {
      throw new AppError("Unauthorized", 401, "UNAUTHORIZED");
    }

    const customer = await service.createCustomer(parseResult.data, user.subject);
    return reply.code(201).send(customer);
  });

  app.get("/customers/:id", async (request, reply) => {
    const params = CustomerIdSchema.safeParse((request.params as { id?: unknown }).id);
    if (!params.success) {
      throw new ValidationError("Invalid customer id", params.error.flatten());
    }

    try {
      const customer = await service.getCustomer(params.data);
      return reply.send(customer);
    } catch {
      throw new NotFoundError("Customer not found");
    }
  });
}
```

