```ts
import Fastify from "fastify";
import { customerRoutes } from "./routes/customerRoutes.js";
import { logger } from "./utils/logger.js";
import { AppError } from "./utils/errors.js";
import { InMemoryCustomerRepository, CustomerService } from "./services/customerService.js";
import { HttpCorporateCrmClient } from "./integrations/corporateCrmClient.js";
import { HttpAuditClient } from "./integrations/auditClient.js";
import { env } from "./config/env.js";

export function buildApp() {
  const app = Fastify({ logger });

  const repository = new InMemoryCustomerRepository();
  const crmClient = new HttpCorporateCrmClient(env.CRM_BASE_URL);
  const auditClient = new HttpAuditClient(env.AUDIT_BASE_URL);

  const service = new CustomerService(repository, crmClient, auditClient);

  app.addHook("preHandler", async (request) => {
    // Placeholder for SSO/JWT verification integration
    request.user = {
      subject: "service-account",
      roles: ["customer-writer"]
    };
  });

  app.setErrorHandler((err, _req, reply) => {
    if (err instanceof AppError) {
      return reply.code(err.statusCode).send({
        error: err.code,
        message: err.message,
        details: err.details
      });
    }

    logger.error({ err }, "Unhandled error");
    return reply.code(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });

  app.get("/health", async () => ({ status: "ok" }));

  void customerRoutes(app, service);

  return app;
}
```

