import type { AppConfig } from "./types.js";

function required(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`Missing required env var: ${name}`);
  return value;
}

function parseLogLevel(value: string): AppConfig["logLevel"] {
  const allowed = ["fatal", "error", "warn", "info", "debug", "trace"] as const;
  if ((allowed as readonly string[]).includes(value)) return value as AppConfig["logLevel"];
  return "info";
}

export const config: AppConfig = {
  port: Number(process.env.PORT ?? 3000),
  logLevel: parseLogLevel(process.env.LOG_LEVEL ?? "info"),
  serviceName: process.env.SERVICE_NAME ?? "corporate-microservice",
  hrSystemBaseUrl: required("HR_SYSTEM_BASE_URL"),
  hrSystemApiKey: required("HR_SYSTEM_API_KEY")
};
