## `src/clients/corporateHrClient.ts`

```ts
import axios, { type AxiosInstance } from "axios";
import { config } from "../config.js";
import { IntegrationError } from "../errors.js";
import type { Employee, CreateEmployeeInput } from "../types.js";

export class CorporateHrClient {
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      baseURL: config.hrSystemBaseUrl,
      timeout: 5000,
      headers: {
        Authorization: `Bearer ${config.hrSystemApiKey}`,
        "Content-Type": "application/json"
      }
    });
  }

  async createEmployee(input: CreateEmployeeInput, correlationId: string): Promise<Employee> {
    try {
      const response = await this.http.post<Employee>(
        "/employees",
        input,
        {
          headers: {
            "x-correlation-id": correlationId
          }
        }
      );
      return response.data;
    } catch (error) {
      throw new IntegrationError("Failed to create employee in corporate HR system", error);
    }
  }

  async getEmployeeById(id: string, correlationId: string): Promise<Employee | null> {
    try {
      const response = await this.http.get<Employee>(`/employees/${encodeURIComponent(id)}`, {
        headers: {
          "x-correlation-id": correlationId
        }
      });
      return response.data;
    } catch (error: any) {
      if (error?.response?.status === 404) return null;
      throw new IntegrationError(`Failed to fetch employee ${id} from HR system`, error);
    }
  }
}
```

