## `src/services/employeeService.ts`

```ts
import { z } from "zod";
import { CorporateHrClient } from "../clients/corporateHrClient.js";
import { ValidationError, NotFoundError } from "../errors.js";
import type { CreateEmployeeInput, Employee } from "../types.js";

const createEmployeeSchema = z.object({
  firstName: z.string().min(1).max(100),
  lastName: z.string().min(1).max(100),
  department: z.string().min(1).max(100),
  email: z.string().email().max(254)
});

export class EmployeeService {
  constructor(private readonly hrClient: CorporateHrClient) {}

  async create(input: unknown, correlationId: string): Promise<Employee> {
    const parsed = createEmployeeSchema.safeParse(input);
    if (!parsed.success) {
      throw new ValidationError(parsed.error.message);
    }

    return this.hrClient.createEmployee(parsed.data satisfies CreateEmployeeInput, correlationId);
  }

  async getById(id: string, correlationId: string): Promise<Employee> {
    const employee = await this.hrClient.getEmployeeById(id, correlationId);
    if (!employee) {
      throw new NotFoundError(`Employee ${id} not found`);
    }
    return employee;
  }
}
