## `src/routes/employees.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { EmployeeService } from "../services/employeeService.js";
import { getOrCreateCorrelationId } from "../utils/correlationId.js";

const paramsSchema = z.object({
  id: z.string().min(1)
});

export async function registerEmployeeRoutes(
  app: FastifyInstance,
  employeeService: EmployeeService
): Promise<void> {
  app.post("/employees", async (request, reply) => {
    const correlationId = getOrCreateCorrelationId(request);
    const employee = await employeeService.create(request.body, correlationId);
    return reply
      .header("x-correlation-id", correlationId)
      .code(201)
      .send(employee);
  });

  app.get("/employees/:id", async (request, reply) => {
    const correlationId = getOrCreateCorrelationId(request);
    const parsed = paramsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Invalid employee id" });
    }

    const employee = await employeeService.getById(parsed.data.id, correlationId);
    return reply.header("x-correlation-id", correlationId).send(employee);
  });
}
```

