## `src/app.ts`

```ts
import Fastify from "fastify";
import { logger } from "./logger.js";
import { registerHealthRoutes } from "./routes/health.js";
import { registerEmployeeRoutes } from "./routes/employees.js";
import { CorporateHrClient } from "./clients/corporateHrClient.js";
import { EmployeeService } from "./services/employeeService.js";
import { ValidationError, NotFoundError, IntegrationError } from "./errors.js";

export function buildApp() {
  const app = Fastify({
    logger
  });

  const hrClient = new CorporateHrClient();
  const employeeService = new EmployeeService(hrClient);

  app.setErrorHandler(async (error, request, reply) => {
    request.log.error({ err: error }, "request failed");

    if (error instanceof ValidationError) {
      return reply.code(400).send({ error: error.message });
    }

    if (error instanceof NotFoundError) {
      return reply.code(404).send({ error: error.message });
    }

    if (error instanceof IntegrationError) {
      return reply.code(502).send({ error: "Upstream corporate system error" });
    }

    return reply.code(500).send({ error: "Internal server error" });
  });

  void registerHealthRoutes(app);
  void registerEmployeeRoutes(app, employeeService);

  return app;
}
