# 11) Service implementation

## `src/employees/employees.service.ts`

```ts
import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { EmployeeRepository } from './repositories/employee.repository';
import { CreateEmployeeDto } from './dto/create-employee.dto';
import { UpdateEmployeeDto } from './dto/update-employee.dto';
import { Employee } from './entities/employee.entity';

@Injectable()
export class EmployeesService {
  constructor(private readonly employeeRepository: EmployeeRepository) {}

  async create(dto: CreateEmployeeDto): Promise<Employee> {
    const existing = await this.employeeRepository.findByEmail(dto.email);
    if (existing !== null) {
      throw new ConflictException(`Employee with email ${dto.email} already exists`);
    }

    const employeeNumber = `EMP-${randomUUID().slice(0, 8).toUpperCase()}`;

    return this.employeeRepository.create({
      employeeNumber,
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      departmentCode: dto.departmentCode,
      title: dto.title,
      active: true,
    });
  }

  async findOne(id: string): Promise<Employee> {
    const employee = await this.employeeRepository.findById(id);
    if (employee === null) {
      throw new NotFoundException(`Employee ${id} not found`);
    }
    return employee;
  }

  async update(id: string, dto: UpdateEmployeeDto): Promise<Employee> {
    await this.findOne(id);
    return this.employeeRepository.update(id, dto);
  }
}
```

