import { Injectable } from '@nestjs/common';
import { CreateOrderDto } from './dto/create-order.dto';
import { OrderEntity } from './entities/order.entity';
import { CorporateErpClient } from '../../integrations/corporate-erp.client';

@Injectable()
export class OrdersService {
  constructor(private readonly erpClient: CorporateErpClient) {}

  async createOrder(dto: CreateOrderDto): Promise<OrderEntity> {
    const id = crypto.randomUUID();

    const order: OrderEntity = {
      id,
      customerId: dto.customerId,
      productIds: dto.productIds,
      quantity: dto.quantity,
      status: 'PENDING',
      createdAt: new Date()
    };

    const approved = await this.erpClient.reserveInventory({
      customerId: dto.customerId,
      productIds: dto.productIds,
      quantity: dto.quantity
    });

    order.status = approved ? 'CONFIRMED' : 'FAILED';

    return order;
  }
}
