## 9) Corporate integration client

### `src/integrations/corporate-erp.client.ts`

```ts
import { Injectable, ServiceUnavailableException } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';

interface ReserveInventoryRequest {
  customerId: string;
  productIds: string[];
  quantity: number;
}

@Injectable()
export class CorporateErpClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.ERP_BASE_URL,
      timeout: 5000,
      headers: {
        'x-api-key': process.env.ERP_API_KEY ?? ''
      }
    });
  }

  async reserveInventory(req: ReserveInventoryRequest): Promise<boolean> {
    if (!process.env.ERP_BASE_URL) {
      throw new ServiceUnavailableException('ERP integration is not configured');
    }

    try {
      const response = await this.client.post<{ success: boolean }>('/inventory/reserve', req);
      return response.data.success;
    } catch {
      return false;
    }
  }
}
```

