import { PrismaClient, Employee as PrismaEmployee } from "@prisma/client";
import { CreateEmployeeInput } from "./employee.schemas.js";

export interface EmployeeRepository {
  create(input: CreateEmployeeInput): Promise<PrismaEmployee>;
  findById(id: string): Promise<PrismaEmployee | null>;
  findByCorpEmployeeId(corpEmployeeId: string): Promise<PrismaEmployee | null>;
}

export class PrismaEmployeeRepository implements EmployeeRepository {
  constructor(private readonly prisma: PrismaClient) {}

  create(input: CreateEmployeeInput): Promise<PrismaEmployee> {
    return this.prisma.employee.create({ data: input });
  }

  findById(id: string): Promise<PrismaEmployee | null> {
    return this.prisma.employee.findUnique({ where: { id } });
  }

  findByCorpEmployeeId(corpEmployeeId: string): Promise<PrismaEmployee | null> {
    return this.prisma.employee.findUnique({ where: { corpEmployeeId } });
  }
}
