import { config } from "../config.js";
import { AppError } from "../lib/error.js";

export class CorpApiClient {
  async verifyEmployeeExists(corpEmployeeId: string): Promise<boolean> {
    const res = await fetch(
      `${config.CORP_API_BASE_URL}/employees/${encodeURIComponent(corpEmployeeId)}`,
      {
        headers: {
          Authorization: `Bearer ${config.CORP_API_TOKEN}`,
          Accept: "application/json"
        }
      }
    );

    if (res.status === 404) return false;
    if (!res.ok) {
      throw new AppError(502, "Failed to verify employee in corporate system", "CORP_API_ERROR");
    }
    return true;
  }
}
