## `src/modules/employee/employee.service.ts`

```ts
import { AppError } from "../../lib/error.js";
import { CorpApiClient } from "../../integrations/corp-api.client.js";
import { EmployeeRepository } from "./employee.repo.js";
import { CreateEmployeeInput, Employee } from "./employee.schemas.js";

export class EmployeeService {
  constructor(
    private readonly repo: EmployeeRepository,
    private readonly corpApi: CorpApiClient
  ) {}

  async createEmployee(input: CreateEmployeeInput): Promise<Employee> {
    const exists = await this.corpApi.verifyEmployeeExists(input.corpEmployeeId);
    if (!exists) {
      throw new AppError(400, "Employee does not exist in corporate master system", "INVALID_CORP_EMPLOYEE");
    }

    const existing = await this.repo.findByCorpEmployeeId(input.corpEmployeeId);
    if (existing) {
      throw new AppError(409, "Employee already exists", "EMPLOYEE_ALREADY_EXISTS");
    }

    const created = await this.repo.create(input);

    return {
      id: created.id,
      corpEmployeeId: created.corpEmployeeId,
      firstName: created.firstName,
      lastName: created.lastName,
      email: created.email,
      department: created.department,
      createdAt: created.createdAt.toISOString(),
      updatedAt: created.updatedAt.toISOString()
    };
  }

  async getEmployee(id: string): Promise<Employee> {
    const employee = await this.repo.findById(id);
    if (!employee) {
      throw new AppError(404, "Employee not found", "EMPLOYEE_NOT_FOUND");
    }

    return {
      id: employee.id,
      corpEmployeeId: employee.corpEmployeeId,
      firstName: employee.firstName,
      lastName: employee.lastName,
      email: employee.email,
      department: employee.department,
      createdAt: employee.createdAt.toISOString(),
      updatedAt: employee.updatedAt.toISOString()
    };
  }
}
