import { FastifyInstance } from "fastify";
import { z } from "zod";
import { EmployeeService } from "./employee.service.js";
import { CreateEmployeeSchema, EmployeeIdSchema } from "./employee.schemas.js";

export async function employeeRoutes(app: FastifyInstance, service: EmployeeService) {
  app.post(
    "/employees",
    {
      schema: {
        body: CreateEmployeeSchema,
        response: {
          201: z.any()
        }
      }
    },
    async (req, reply) => {
      const employee = await service.createEmployee(req.body);
      return reply.code(201).send(employee);
    }
  );

  app.get(
    "/employees/:id",
    {
      schema: {
        params: z.object({ id: EmployeeIdSchema }),
        response: {
          200: z.any()
        }
      }
    },
    async (req) => {
      return service.getEmployee(req.params.id);
    }
  );
}
