import Fastify from "fastify";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";
import { logger } from "./logger.js";
import { AppError } from "./lib/error.js";
import { PrismaClient } from "@prisma/client";
import { PrismaEmployeeRepository } from "./modules/employee/employee.repo.js";
import { CorpApiClient } from "./integrations/corp-api.client.js";
import { EmployeeService } from "./modules/employee/employee.service.js";
import { employeeRoutes } from "./modules/employee/employee.routes.js";

export async function buildApp() {
  const app = Fastify({ logger });

  await app.register(swagger, {
    openapi: {
      info: {
        title: "Enterprise Microservice",
        version: "1.0.0"
      }
    }
  });

  await app.register(swaggerUi, { routePrefix: "/docs" });

  const prisma = new PrismaClient();
  const repo = new PrismaEmployeeRepository(prisma);
  const corpApi = new CorpApiClient();
  const employeeService = new EmployeeService(repo, corpApi);

  app.get("/health", async () => ({ status: "ok" }));

  await app.register(async (subApp) => {
    await employeeRoutes(subApp, employeeService);
  });

  app.setErrorHandler((err, req, reply) => {
    req.log.error({ err }, "request failed");

    if (err instanceof AppError) {
      return reply.status(err.statusCode).send({
        error: err.code,
        message: err.message,
        details: err.details ?? null
      });
    }

    return reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "Unexpected error"
    });
  });

  return app;
}
```

