import { Injectable } from '@nestjs/common';
import { PrismaClient } from '@prisma/client';
import { Employee } from './domain/employee.entity';

@Injectable()
export class EmployeeRepository {
  constructor(private readonly prisma: PrismaClient) {}

  async create(data: {
    employeeNumber: string;
    firstName: string;
    lastName: string;
    email: string;
    departmentCode: string;
  }): Promise<Employee> {
    const row = await this.prisma.employee.create({ data });
    return Employee.create(row);
  }

  async findById(id: string): Promise<Employee | null> {
    const row = await this.prisma.employee.findUnique({ where: { id } });
    return row ? Employee.create(row) : null;
  }

  async findByEmployeeNumber(employeeNumber: string): Promise<Employee | null> {
    const row = await this.prisma.employee.findUnique({ where: { employeeNumber } });
    return row ? Employee.create(row) : null;
  }

  async update(
    id: string,
    data: Partial<{ email: string; active: boolean; departmentCode: string }>
  ): Promise<Employee> {
    const row = await this.prisma.employee.update({ where: { id }, data });
    return Employee.create(row);
  }
}
