import { Injectable } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';

export interface HrEmployeeSnapshot {
  employeeNumber: string;
  firstName: string;
  lastName: string;
  email: string;
  departmentCode: string;
  active: boolean;
}

@Injectable()
export class HrSystemClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.HR_SYSTEM_BASE_URL,
      headers: {
        'X-API-Key': process.env.HR_SYSTEM_API_KEY
      },
      timeout: 5000
    });
  }

  async fetchEmployee(employeeNumber: string): Promise<HrEmployeeSnapshot | null> {
    try {
      const res = await this.client.get(`/employees/${employeeNumber}`);
      return res.data as HrEmployeeSnapshot;
    } catch (error: any) {
      if (error?.response?.status === 404) return null;
      throw error;
    }
  }
}
```

