## 4.8 Service layer

### `src/modules/employee/employee.service.ts`

```ts
import { Injectable, NotFoundException, ConflictException } from '@nestjs/common';
import { EmployeeRepository } from './employee.repository';
import { HrSystemClient } from '../integrations/hr-system.client';
import { CreateEmployeeDto } from './dto/create-employee.dto';
import { UpdateEmployeeDto } from './dto/update-employee.dto';

@Injectable()
export class EmployeeService {
  constructor(
    private readonly repository: EmployeeRepository,
    private readonly hrClient: HrSystemClient
  ) {}

  async create(dto: CreateEmployeeDto) {
    const existing = await this.repository.findByEmployeeNumber(dto.employeeNumber);
    if (existing) throw new ConflictException('Employee number already exists');

    return this.repository.create(dto);
  }

  async getById(id: string) {
    const employee = await this.repository.findById(id);
    if (!employee) throw new NotFoundException('Employee not found');
    return employee;
  }

  async update(id: string, dto: UpdateEmployeeDto) {
    const employee = await this.repository.findById(id);
    if (!employee) throw new NotFoundException('Employee not found');

    return this.repository.update(id, dto);
  }

  async syncFromHr(employeeNumber: string) {
    const snapshot = await this.hrClient.fetchEmployee(employeeNumber);
    if (!snapshot) throw new NotFoundException('Employee not found in HR system');

    const existing = await this.repository.findByEmployeeNumber(employeeNumber);

    if (existing) {
      return this.repository.update(existing.id, {
        email: snapshot.email,
        active: snapshot.active,
        departmentCode: snapshot.departmentCode
      });
    }

    return this.repository.create(snapshot);
  }
}
```

