## `src/integrations/corporate-crm.client.ts`

```ts
import { env } from "../config/env.js";

export interface CorporateCrmClient {
  syncCustomer(customer: {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
  }): Promise<{ externalId: string }>;
}

export class HttpCorporateCrmClient implements CorporateCrmClient {
  async syncCustomer(customer: {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
  }): Promise<{ externalId: string }> {
    if (!env.CRM_BASE_URL) {
      // Safe fallback for local/dev environments
      return { externalId: `local-crm-${customer.id}` };
    }

    const response = await fetch(`${env.CRM_BASE_URL}/customers`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...(env.CRM_API_KEY ? { "Authorization": `Bearer ${env.CRM_API_KEY}` } : {})
      },
      body: JSON.stringify(customer)
    });

    if (!response.ok) {
      throw new Error(`CRM sync failed with status ${response.status}`);
    }

    const data = (await response.json()) as { externalId: string };
    return data;
  }
}
```

