```ts
import { CustomerRepository } from "../repositories/customer.repository.js";
import { CorporateCrmClient } from "../integrations/corporate-crm.client.js";
import { CreateCustomerInput, Customer } from "../models/customer.js";
import { NotFoundError, ValidationError } from "../utils/errors.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CorporateCrmClient
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    if (!input.firstName.trim()) throw new ValidationError("firstName is required");
    if (!input.lastName.trim()) throw new ValidationError("lastName is required");
    if (!input.email.includes("@")) throw new ValidationError("email must be valid");

    const customer = await this.repository.create(input);

    try {
      const crmResult = await this.crmClient.syncCustomer(customer);
      return {
        ...customer,
        externalId: crmResult.externalId
      };
    } catch {
      // In enterprise systems, this may instead go to a retry queue/outbox.
      return customer;
    }
  }

  async getCustomerById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) throw new NotFoundError(`Customer ${id} not found`);
    return customer;
  }
}
