import Fastify from "fastify";
import { env } from "./config/env.js";
import { registerErrorHandler } from "./plugins/error-handler.js";
import { registerLogger } from "./plugins/logger.js";
import { registerAuth } from "./plugins/auth.js";
import { InMemoryCustomerRepository } from "./repositories/customer.repository.js";
import { HttpCorporateCrmClient } from "./integrations/corporate-crm.client.js";
import { CustomerService } from "./services/customer.service.js";
import { CustomerController } from "./controllers/customer.controller.js";
import { customerRoutes } from "./routes/customer.routes.js";

export async function buildApp() {
  const app = Fastify({
    logger: {
      level: env.NODE_ENV === "production" ? "info" : "debug"
    }
  });

  registerLogger(app);
  registerErrorHandler(app);
  await registerAuth(app);

  const repository = new InMemoryCustomerRepository();
  const crmClient = new HttpCorporateCrmClient();
  const service = new CustomerService(repository, crmClient);
  const controller = new CustomerController(service);

  app.get("/health", async () => ({ status: "ok", service: env.SERVICE_NAME }));

  await customerRoutes(app, controller);

  return app;
}
