import axios, { AxiosInstance } from 'axios';
import { CrmAdapter, CrmCustomerRecord } from './crm.adapter';

export class HttpCrmClient implements CrmAdapter {
  private readonly client: AxiosInstance;

  constructor(baseURL: string, apiKey: string) {
    this.client = axios.create({
      baseURL,
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      timeout: 5000,
    });
  }

  async getCustomerById(id: string): Promise<CrmCustomerRecord | null> {
    try {
      const response = await this.client.get(`/customers/${id}`);
      return response.data as CrmCustomerRecord;
    } catch (error: any) {
      if (error?.response?.status === 404) return null;
      throw error;
    }
  }
}
