## 10. Business Service

### `src/customers/customers.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { CrmAdapter } from '../integrations/crm/crm.adapter';
import { ErpAdapter } from '../integrations/erp/erp.adapter';
import { Customer } from './domain/customer';

@Injectable()
export class CustomersService {
  constructor(
    private readonly crmAdapter: CrmAdapter,
    private readonly erpAdapter: ErpAdapter,
  ) {}

  async getCustomer(id: string): Promise<Customer | null> {
    const crmCustomer = await this.crmAdapter.getCustomerById(id);
    if (!crmCustomer) return null;

    const erpAccount = await this.erpAdapter.getAccountByCustomerId(id);

    return {
      id,
      crmReferenceId: crmCustomer.crmReferenceId,
      firstName: crmCustomer.firstName,
      lastName: crmCustomer.lastName,
      email: crmCustomer.email,
      status: crmCustomer.status,
      accountBalance: erpAccount?.balance,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
  }
}
```

