## 7) Corporate integration client: `src/integrations/corporate-system.client.ts`

This is the abstraction you’d extend for existing internal APIs, ESB, SAP, mainframe gateways, etc.

```ts
import axios, { AxiosInstance } from "axios";
import { env } from "../config/env.js";

export class CorporateSystemClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: env.CORPORATE_SYSTEM_BASE_URL,
      timeout: 5000,
      headers: {
        "Content-Type": "application/json",
        "X-API-Key": env.CORPORATE_SYSTEM_API_KEY
      }
    });
  }

  async ping(): Promise<boolean> {
    try {
      const response = await this.client.get("/health");
      return response.status >= 200 && response.status < 300;
    } catch {
      return false;
    }
  }
}
```

