## 8) Service layer: `src/services/health.service.ts`

```ts
import { CorporateSystemClient } from "../integrations/corporate-system.client.js";
import type { HealthResponse } from "../types/common.js";

export class HealthService {
  constructor(private readonly corporateClient: CorporateSystemClient) {}

  async getHealth(): Promise<HealthResponse> {
    const corporateOk = await this.corporateClient.ping();

    return {
      status: corporateOk ? "ok" : "degraded",
      timestamp: new Date().toISOString(),
      dependencies: {
        corporateSystem: corporateOk ? "ok" : "down"
      }
    };
  }
}
