import Fastify from "fastify";
import { logger } from "./config/logger.js";
import { CorporateSystemClient } from "./integrations/corporate-system.client.js";
import { HealthService } from "./services/health.service.js";
import { HealthController } from "./controllers/health.controller.js";
import { healthRoutes } from "./routes/health.routes.js";

export function createApp() {
  const app = Fastify({
    logger
  });

  const corporateClient = new CorporateSystemClient();
  const healthService = new HealthService(corporateClient);
  const healthController = new HealthController(healthService);

  app.get("/", async () => ({
    service: "enterprise-microservice",
    version: "1.0.0"
  }));

  app.register(async (instance) => {
    await healthRoutes(instance, healthController);
  });

  return app;
}
