# 7. Corporate system integration abstraction

This hides external system details behind a typed interface.

## `src/integrations/corporate-system.types.ts`

```ts
import { z } from "zod";

export const CorporateEmployeeSchema = z.object({
  employeeId: z.string().min(1),
  fullName: z.string().min(1),
  department: z.string().min(1),
  status: z.enum(["active", "inactive"])
});

export type CorporateEmployee = z.infer<typeof CorporateEmployeeSchema>;
```

## `src/integrations/corporate-system.client.ts`

```ts
import { env } from "../config/index.js";
import { CorporateEmployeeSchema, type CorporateEmployee } from "./corporate-system.types.js";

export class CorporateSystemClient {
  async getEmployee(employeeId: string): Promise<CorporateEmployee> {
    const res = await fetch(`${env.CORPORATE_API_BASE_URL}/employees/${encodeURIComponent(employeeId)}`, {
      headers: {
        Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
        "Content-Type": "application/json"
      }
    });

    if (!res.ok) {
      throw new Error(`Corporate system request failed: ${res.status} ${res.statusText}`);
    }

    const data = await res.json();
    return CorporateEmployeeSchema.parse(data);
  }
}
```

