import { prisma } from "../db/prisma.js";
import { CorporateSystemClient } from "../integrations/corporate-system.client.js";

const corporateClient = new CorporateSystemClient();

export class SampleService {
  async syncEmployee(employeeId: string) {
    const employee = await corporateClient.getEmployee(employeeId);

    const saved = await prisma.employeeRequest.upsert({
      where: { employeeId: employee.employeeId },
      create: {
        employeeId: employee.employeeId,
        fullName: employee.fullName,
        department: employee.department
      },
      update: {
        fullName: employee.fullName,
        department: employee.department
      }
    });

    return saved;
  }
}
