import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { SampleService } from "../services/sample.service.js";

const syncEmployeeBodySchema = z.object({
  employeeId: z.string().min(1)
});

const service = new SampleService();

export async function sampleRoutes(app: FastifyInstance) {
  app.post("/employees/sync", async (req, reply) => {
    const parsed = syncEmployeeBodySchema.safeParse(req.body);

    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        details: parsed.error.flatten()
      });
    }

    const result = await service.syncEmployee(parsed.data.employeeId);

    return reply.status(200).send({
      id: result.id,
      employeeId: result.employeeId,
      fullName: result.fullName,
      department: result.department,
      createdAt: result.createdAt,
      updatedAt: result.updatedAt
    });
  });
}
```

