# 9) Integration clients

These are placeholders for corporate systems. In a real enterprise deployment, these would likely use mTLS, OAuth2 client credentials, service accounts, or internal gateway auth.

## src/services/integrations/identity-client.ts

```ts
import { request } from 'undici';
import { ExternalSystemError } from '../../domain/errors.js';

export interface IdentityClient {
  validateDepartmentCode(code: string): Promise<boolean>;
}

export function createIdentityClient(baseUrl: string): IdentityClient {
  return {
    async validateDepartmentCode(code: string): Promise<boolean> {
      try {
        const res = await request(`${baseUrl}/departments/${encodeURIComponent(code)}`, {
          method: 'GET'
        });

        if (res.statusCode === 404) return false;
        if (res.statusCode !== 200) {
          throw new ExternalSystemError(`Identity service returned ${res.statusCode}`, 'identity');
        }

        return true;
      } catch (err) {
        if (err instanceof ExternalSystemError) throw err;
        throw new ExternalSystemError('Failed to contact identity service', 'identity');
      }
    }
  };
}
```

