# 10) Business service

## src/services/customer-service.ts

```ts
import { randomUUID } from 'node:crypto';
import { Customer, CreateCustomerInput } from '../domain/customer.js';
import { NotFoundError } from '../domain/errors.js';
import { CrmClient } from './integrations/crm-client.js';
import { IdentityClient } from './integrations/identity-client.js';
import { EventBus } from './integrations/event-bus.js';

export interface CustomerRepository {
  getById(id: string): Promise<Customer | null>;
  save(customer: Customer): Promise<void>;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly store = new Map<string, Customer>();

  async getById(id: string): Promise<Customer | null> {
    return this.store.get(id) ?? null;
  }

  async save(customer: Customer): Promise<void> {
    this.store.set(customer.id, customer);
  }
}

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly identityClient: IdentityClient,
    private readonly crmClient: CrmClient,
    private readonly eventBus: EventBus
  ) {}

  async create(input: CreateCustomerInput): Promise<Customer> {
    const departmentValid = await this.identityClient.validateDepartmentCode(input.departmentCode);
    if (!departmentValid) {
      throw new NotFoundError(`Department code not found: ${input.departmentCode}`);
    }

    const now = new Date().toISOString();
    const customer: Customer = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      departmentCode: input.departmentCode,
      active: true,
      createdAt: now,
      updatedAt: now
    };

    await this.repo.save(customer);
    await this.crmClient.syncCustomer(customer);
    await this.eventBus.publish('customer.created', customer);

    return customer;
  }

  async getById(id: string): Promise<Customer> {
    const customer = await this.repo.getById(id);
    if (!customer) {
      throw new NotFoundError(`Customer not found: ${id}`);
    }
    return customer;
  }
}
```

