# 11) Request validation and routes

## src/routes/customers.ts

```ts
import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { CustomerService } from '../services/customer-service.js';
import { NotFoundError } from '../domain/errors.js';

const createCustomerSchema = z.object({
  firstName: z.string().min(1),
  lastName: z.string().min(1),
  email: z.string().email(),
  departmentCode: z.string().min(1)
});

export async function customerRoutes(app: FastifyInstance) {
  const service = app.diContainer.customerService as CustomerService;

  app.post('/customers', async (req, reply) => {
    const parsed = createCustomerSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({
        error: 'ValidationError',
        details: parsed.error.flatten()
      });
    }

    const customer = await service.create(parsed.data);
    return reply.code(201).send(customer);
  });

  app.get('/customers/:id', async (req, reply) => {
    const { id } = req.params as { id: string };

    try {
      const customer = await service.getById(id);
      return reply.send(customer);
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.code(404).send({ error: err.message });
      }
      throw err;
    }
  });
}
```

