```ts
import Fastify from "fastify";
import { config } from "./config/index.js";
import { logger } from "./utils/logger.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { InMemoryCustomerRepo } from "./infrastructure/persistence/inMemoryCustomerRepo.js";
import { CorporateClient } from "./infrastructure/corporate/corporateClient.js";
import { CrmAdapter } from "./infrastructure/corporate/crmAdapter.js";
import { CustomerService } from "./application/customerService.js";

export function buildApp() {
  const app = Fastify({ logger });

  const repo = new InMemoryCustomerRepo();
  const corporateClient = new CorporateClient(
    config.corporateCrm.baseUrl,
    config.corporateCrm.apiKey
  );
  const crm = new CrmAdapter(corporateClient);
  const service = new CustomerService(repo, crm);

  app.register(healthRoutes);
  app.register((instance) => customerRoutes(instance, service));

  app.setErrorHandler((error, _req, reply) => {
    app.log.error(error);

    if (error instanceof Error && error.name === "ZodError") {
      return reply.code(400).send({ message: "Invalid request" });
    }

    return reply.code(500).send({ message: "Internal server error" });
  });

  return app;
}
