      createExternalCustomer: vi.fn(async () => ({ corporateId: "CRM-123" }))
    };

    const service = new CustomerService(repo, crm);

    const result = await service.create({
      firstName: "Jane",
      lastName: "Doe",
      email: "jane.doe@example.com"
    });

    expect(result.corporateId).toBe("CRM-123");
    expect(repo.save).toHaveBeenCalledOnce();
    expect(crm.createExternalCustomer).toHaveBeenCalledOnce();
  });
});
