```ts
import { Injectable } from '@nestjs/common';
import { Profile } from './schemas/profile.schema';

@Injectable()
export class ProfilesRepository {
  private readonly store = new Map<string, Profile>();

  async save(profile: Profile): Promise<Profile> {
    this.store.set(profile.id, profile);
    return profile;
  }

  async findByEmployeeId(employeeId: string): Promise<Profile | null> {
    for (const profile of this.store.values()) {
      if (profile.employeeId === employeeId) return profile;
    }
    return null;
  }

  async findAll(): Promise<Profile[]> {
    return [...this.store.values()];
  }
}
