## `src/modules/integrations/corporate-directory/corporate-directory.client.ts`

```ts
import { Injectable, Inject } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { ConfigType } from '@nestjs/config';
import { corporateDirectoryConfig } from './corporate-directory.module';
import { CorporateEmployeeLookupResult } from './corporate-directory.types';
import { DomainError } from '../../../common/errors/domain-error';

@Injectable()
export class CorporateDirectoryClient {
  private readonly http: AxiosInstance;

  constructor(
    @Inject(corporateDirectoryConfig.KEY)
    private readonly config: ConfigType<typeof corporateDirectoryConfig>
  ) {
    this.http = axios.create({
      baseURL: this.config.baseUrl,
      timeout: 5000,
      headers: {
        'x-api-key': this.config.apiKey
      }
    });
  }

  async lookupEmployee(employeeId: string): Promise<CorporateEmployeeLookupResult> {
    try {
      const res = await this.http.get(`/employees/${encodeURIComponent(employeeId)}`);
      return res.data as CorporateEmployeeLookupResult;
    } catch {
      throw new DomainError(
        `Failed to query corporate directory for employeeId=${employeeId}`,
        'CORPORATE_DIRECTORY_UNAVAILABLE',
        503
      );
    }
  }
}
```

