## `src/modules/profiles/profiles.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { createProfileSchema, Profile } from './schemas/profile.schema';
import { ProfilesRepository } from './profiles.repository';
import { CorporateDirectoryClient } from '../integrations/corporate-directory/corporate-directory.client';
import { DomainError } from '../../common/errors/domain-error';

@Injectable()
export class ProfilesService {
  constructor(
    private readonly repository: ProfilesRepository,
    private readonly directoryClient: CorporateDirectoryClient
  ) {}

  async create(input: unknown): Promise<Profile> {
    const parsed = createProfileSchema.safeParse(input);
    if (!parsed.success) {
      throw new DomainError(`Validation failed: ${parsed.error.message}`, 'VALIDATION_ERROR', 400);
    }

    const existing = await this.repository.findByEmployeeId(parsed.data.employeeId);
    if (existing) {
      throw new DomainError(
        `Profile already exists for employeeId=${parsed.data.employeeId}`,
        'PROFILE_ALREADY_EXISTS',
        409
      );
    }

    const directoryEmployee = await this.directoryClient.lookupEmployee(parsed.data.employeeId);
    if (!directoryEmployee.active) {
      throw new DomainError(`Employee is not active in corporate directory`, 'EMPLOYEE_INACTIVE', 409);
    }

    const now = new Date();
    const profile: Profile = {
      id: randomUUID(),
      ...parsed.data,
      createdAt: now,
      updatedAt: now
    };

    return this.repository.save(profile);
  }

  async list(): Promise<Profile[]> {
    return this.repository.findAll();
  }
}
```

