## `src/modules/customer/customer.service.ts`

```ts
import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { CustomerRepository } from './customer.repository';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { UpdateCustomerDto } from './dto/update-customer.dto';
import { Customer } from './customer.types';
import { ErpClient } from '../integrations/erp.client';
import { SsoClient } from '../integrations/sso.client';

@Injectable()
export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly erpClient: ErpClient,
    private readonly ssoClient: SsoClient
  ) {}

  async create(dto: CreateCustomerDto): Promise<Customer> {
    const existing = await this.repository.findByEmail(dto.email);
    if (existing) {
      throw new ConflictException('Customer with this email already exists');
    }

    await this.ssoClient.ensureEmployeeExists(dto.employeeId);

    const customer: Customer = {
      id: randomUUID(),
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      employeeId: dto.employeeId,
      createdAt: new Date(),
      updatedAt: new Date()
    };

    const saved = await this.repository.save(customer);
    await this.erpClient.syncCustomer(saved);

    return saved;
  }

  async update(id: string, dto: UpdateCustomerDto): Promise<Customer> {
    const current = await this.repository.findById(id);
    if (!current) {
      throw new NotFoundException('Customer not found');
    }

    const updated: Customer = {
      ...current,
      ...dto,
      updatedAt: new Date()
    };

    const saved = await this.repository.save(updated);
    await this.erpClient.syncCustomer(saved);

    return saved;
  }

  async getById(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundException('Customer not found');
    }
    return customer;
  }
}
