## `src/modules/integrations/sso.client.ts`

```ts
import { HttpService } from '@nestjs/axios';
import { Injectable, ServiceUnavailableException } from '@nestjs/common';
import { firstValueFrom } from 'rxjs';

@Injectable()
export class SsoClient {
  constructor(private readonly http: HttpService) {}

  async ensureEmployeeExists(employeeId: string): Promise<void> {
    try {
      await firstValueFrom(
        this.http.get(`${process.env.SSO_BASE_URL}/api/employees/${employeeId}`, {
          headers: {
            'X-Client-Id': process.env.SSO_CLIENT_ID,
            'X-Client-Secret': process.env.SSO_CLIENT_SECRET
          }
        })
      );
    } catch {
      throw new ServiceUnavailableException('Unable to verify employee in SSO');
    }
  }
}
