import { request } from 'undici';
import { env } from '../config/env.js';
import { logger } from '../utils/logger.js';
import type { Customer } from '../models/customer.js';

export class CorporateSystemClient {
  async syncCustomer(customer: Customer): Promise<void> {
    const url = `${env.CORPORATE_SYSTEM_BASE_URL}/api/customers/sync`;

    const response = await request(url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-api-key': env.CORPORATE_SYSTEM_API_KEY
      },
      body: JSON.stringify(customer)
    });

    if (response.statusCode >= 400) {
      const body = await response.body.text();
      logger.error({ statusCode: response.statusCode, body }, 'Failed to sync customer');
      throw new Error(`Corporate system sync failed with status ${response.statusCode}`);
    }
  }
}
