# 9) Controller

## `src/controllers/customer.controller.ts`

```ts
import type { FastifyReply, FastifyRequest } from 'fastify';
import { CustomerResponseSchema, CreateCustomerSchema } from '../schemas/customer.schema.js';
import { CustomerService } from '../services/customer.service.js';

export class CustomerController {
  constructor(private readonly customerService: CustomerService) {}

  create = async (
    request: FastifyRequest,
    reply: FastifyReply
  ): Promise<void> => {
    const parsed = CreateCustomerSchema.safeParse(request.body);

    if (!parsed.success) {
      reply.status(400).send({
        error: 'ValidationError',
        details: parsed.error.flatten()
      });
      return;
    }

    const customer = await this.customerService.createCustomer(parsed.data);

    reply.status(201).send(CustomerResponseSchema.parse(customer));
  };
}
