# 8. Use cases

## `src/application/use-cases/get-customer.ts`

```ts
import type { CustomerRepositoryPort, IdentityClientPort, AuditPort } from "../ports.js";
import type { Customer, CustomerId } from "../../domain/customer.js";
import { NotFoundError } from "../../domain/errors.js";

export interface GetCustomerInput {
  actorUserId: string;
  customerId: CustomerId;
}

export class GetCustomerUseCase {
  constructor(
    private readonly repo: CustomerRepositoryPort,
    private readonly identity: IdentityClientPort,
    private readonly audit: AuditPort
  ) {}

  async execute(input: GetCustomerInput): Promise<Customer> {
    const allowed = await this.identity.canActOnCustomer(input.actorUserId, input.customerId);
    if (!allowed) {
      throw new NotFoundError("Customer not found");
    }

    const customer = await this.repo.getById(input.customerId);
    if (!customer) {
      throw new NotFoundError("Customer not found");
    }

    await this.audit.recordEvent({
      type: "CUSTOMER_READ",
      actorUserId: input.actorUserId,
      customerId: input.customerId,
      timestamp: new Date().toISOString()
    });

    return customer;
  }
}
```

