import type { AuditPort, CustomerRepositoryPort } from "../ports.js";
import type { Customer, CustomerId, UpdateCustomerInput } from "../../domain/customer.js";

export interface UpdateCustomerCommand {
  actorUserId: string;
  customerId: CustomerId;
  updates: UpdateCustomerInput;
}

export class UpdateCustomerUseCase {
  constructor(
    private readonly repo: CustomerRepositoryPort,
    private readonly audit: AuditPort
  ) {}

  async execute(cmd: UpdateCustomerCommand): Promise<Customer> {
    const updated = await this.repo.update(cmd.customerId, cmd.updates);

    await this.audit.recordEvent({
      type: "CUSTOMER_UPDATED",
      actorUserId: cmd.actorUserId,
      customerId: cmd.customerId,
      timestamp: new Date().toISOString()
    });

    return updated;
  }
}
