import { NotFoundError, ValidationError, IntegrationError } from "../../domain/errors.js";

export function mapError(err: unknown): { statusCode: number; message: string } {
  if (err instanceof NotFoundError) return { statusCode: 404, message: err.message };
  if (err instanceof ValidationError) return { statusCode: 400, message: err.message };
  if (err instanceof IntegrationError) return { statusCode: 502, message: "Upstream integration failure" };
  return { statusCode: 500, message: "Internal server error" };
}
