# 12. Routes

## `src/infrastructure/http/routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { GetCustomerUseCase } from "../../application/use-cases/get-customer.js";
import { UpdateCustomerUseCase } from "../../application/use-cases/update-customer.js";
import { mapError } from "./error-mapper.js";
import { getCustomerParamsSchema, updateCustomerBodySchema, updateCustomerParamsSchema } from "./schemas.js";

export async function registerRoutes(app: FastifyInstance): Promise<void> {
  const getCustomer = app.diContainer.getCustomerUseCase;
  const updateCustomer = app.diContainer.updateCustomerUseCase;

  app.get("/health", async () => ({ status: "ok" }));

  app.get("/customers/:customerId", async (req, reply) => {
    try {
      const { customerId } = getCustomerParamsSchema.parse(req.params);
      const actorUserId = req.headers["x-user-id"];
      if (typeof actorUserId !== "string" || !actorUserId) {
        return reply.code(400).send({ message: "Missing x-user-id header" });
      }

      const customer = await getCustomer.execute({ actorUserId, customerId });
      return reply.send(customer);
    } catch (err) {
      const mapped = mapError(err);
      return reply.code(mapped.statusCode).send({ message: mapped.message });
    }
  });

  app.patch("/customers/:customerId", async (req, reply) => {
    try {
      const { customerId } = updateCustomerParamsSchema.parse(req.params);
      const body = updateCustomerBodySchema.parse(req.body);

      const actorUserId = req.headers["x-user-id"];
      if (typeof actorUserId !== "string" || !actorUserId) {
        return reply.code(400).send({ message: "Missing x-user-id header" });
      }

      const customer = await updateCustomer.execute({ actorUserId, customerId, updates: body });
      return reply.send(customer);
    } catch (err) {
      const mapped = mapError(err);
      return reply.code(mapped.statusCode).send({ message: mapped.message });
    }
  });
}
```

