```ts
import { NotFoundError, ValidationError } from "../domain/errors.js";
import type { Customer } from "../domain/customer.js";
import type { CustomerRepository, ErpPort, IdentityPort } from "./ports.js";

export interface CreateCustomerInput {
  externalReference: string;
  name: string;
  email: string;
  actingUserId: string;
}

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly identity: IdentityPort,
    private readonly erp: ErpPort
  ) {}

  async create(input: CreateCustomerInput): Promise<Customer> {
    const allowed = await this.identity.validateUserAccess(input.actingUserId, "customer:create");
    if (!allowed) throw new ValidationError("User is not authorized to create customers");

    const existing = await this.repo.findByExternalReference(input.externalReference);
    if (existing) throw new ValidationError("Customer with external reference already exists");

    const now = new Date();
    const customer: Customer = {
      id: crypto.randomUUID(),
      externalReference: input.externalReference,
      name: input.name,
      email: input.email,
      createdAt: now,
      updatedAt: now
    };

    const created = await this.repo.create(customer);
    await this.erp.syncCustomer(created);

    return created;
  }

  async getById(id: string): Promise<Customer> {
    const customer = await this.repo.findById(id);
    if (!customer) throw new NotFoundError("Customer not found");
    return customer;
  }
}
