import type { FastifyReply, FastifyRequest } from "fastify";
import { CustomerService } from "../../application/customer-service.js";
import { CreateCustomerBodySchema, CustomerParamsSchema } from "./schemas.js";

export function buildHandlers(service: CustomerService) {
  return {
    createCustomer: async (
      request: FastifyRequest,
      reply: FastifyReply
    ) => {
      const body = CreateCustomerBodySchema.parse(request.body);
      const actingUserId = request.headers["x-user-id"];
      if (typeof actingUserId !== "string" || actingUserId.length === 0) {
        return reply.code(401).send({ message: "Missing x-user-id header" });
      }

      const customer = await service.create({
        ...body,
        actingUserId
      });

      return reply.code(201).send(customer);
    },

    getCustomer: async (
      request: FastifyRequest,
      reply: FastifyReply
    ) => {
      const params = CustomerParamsSchema.parse(request.params);
      const customer = await service.getById(params.id);
      return reply.send(customer);
    }
  };
}
