# 11) App bootstrap

## src/app.ts

```ts
import Fastify from "fastify";
import helmet from "@fastify/helmet";
import sensible from "@fastify/sensible";
import swagger from "@fastify/swagger";
import swaggerUi from "@fastify/swagger-ui";

import { loadEnv } from "./config/env.js";
import { logger } from "./infrastructure/logging/logger.js";
import { PrismaCustomerRepository } from "./infrastructure/db/customer-repository.js";
import { HttpIdentityClient } from "./infrastructure/integrations/identity-client.js";
import { HttpErpClient } from "./infrastructure/integrations/erp-client.js";
import { CustomerService } from "./application/customer-service.js";
import { registerRoutes } from "./interfaces/http/routes.js";

export async function buildApp() {
  const env = loadEnv();

  const app = Fastify({
    logger
  });

  await app.register(helmet);
  await app.register(sensible);

  await app.register(swagger, {
    openapi: {
      info: {
        title: "Enterprise Microservice",
        version: "1.0.0"
      }
    }
  });

  await app.register(swaggerUi, {
    routePrefix: "/docs"
  });

  const repo = new PrismaCustomerRepository();
  const identity = new HttpIdentityClient(env.IDENTITY_BASE_URL);
  const erp = new HttpErpClient(env.ERP_BASE_URL);
  const service = new CustomerService(repo, identity, erp);

  await registerRoutes(app, service);

  app.setErrorHandler((error, _request, reply) => {
    app.log.error(error);

    if (error.name === "ValidationError") {
      return reply.code(400).send({ message: error.message });
    }

    if (error.name === "NotFoundError") {
      return reply.code(404).send({ message: error.message });
    }

    return reply.code(500).send({ message: "Internal Server Error" });
  });

  return app;
}
```

