## `src/domain/customer/customer.service.ts`

```ts
import { randomUUID } from "node:crypto";
import type { Customer } from "./customer.types.js";
import type { CreateCustomerInput } from "./customer.schema.js";
import { ok, err, type Result } from "../../common/result.js";
import { AppError } from "../../common/errors.js";

export interface CustomerRepository {
  save(customer: Customer): Promise<void>;
  findByEmail(email: string): Promise<Customer | null>;
}

export class CustomerService {
  constructor(private readonly repository: CustomerRepository) {}

  async createCustomer(input: CreateCustomerInput): Promise<Result<Customer, AppError>> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      return err(new AppError("Customer already exists", 409, "CUSTOMER_EXISTS"));
    }

    const customer: Customer = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: new Date()
    };

    await this.repository.save(customer);
    return ok(customer);
  }
}
```

