import { env } from "./config/env.js";
import { buildApp } from "./app.js";
import { CustomerService } from "./domain/customer/customer.service.js";
import type { Customer } from "./domain/customer/customer.types.js";

class InMemoryCustomerRepository {
  private readonly customers = new Map<string, Customer>();

  async save(customer: Customer): Promise<void> {
    this.customers.set(customer.id, customer);
  }

  async findByEmail(email: string): Promise<Customer | null> {
    for (const customer of this.customers.values()) {
      if (customer.email === email) return customer;
    }
    return null;
  }
}

async function main() {
  const repository = new InMemoryCustomerRepository();
  const customerService = new CustomerService(repository);
  const app = buildApp(customerService);

  await app.listen({ port: env.PORT, host: "0.0.0.0" });
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
