    private readonly iam: IamClient,
    private readonly crm: CrmClient
  ) {}

  async getCustomer(userToken: string, customerId: CustomerId): Promise<Customer> {
    await this.iam.assertCanReadCustomer(userToken, customerId);

    const customer = await this.repo.findById(customerId);
    if (!customer) {
      throw new NotFoundError(`Customer ${customerId} not found`);
    }

    return customer;
  }

  async updateCustomerEmail(
    userToken: string,
    customerId: CustomerId,
    email: string
  ): Promise<Customer> {
    await this.iam.assertCanReadCustomer(userToken, customerId);

    const customer = await this.repo.findById(customerId);
    if (!customer) {
      throw new NotFoundError(`Customer ${customerId} not found`);
    }

    const updated: Customer = {
      ...customer,
      email,
      updatedAt: new Date()
    };

    await this.repo.save(updated);
    await this.crm.publishCustomerUpdated(updated);

    return updated;
  }
}
