## 10. HTTP layer

### `src/infrastructure/http/routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { createCustomerId } from "../../domain/customer.js";
import { NotFoundError, ValidationError, IntegrationError } from "../../domain/errors.js";
import type { CustomerService } from "../../application/customer-service.js";

const updateEmailSchema = z.object({
  email: z.string().email()
});

export async function registerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get("/health", async () => ({ status: "ok" }));

  app.get("/customers/:id", async (request, reply) => {
    try {
      const params = request.params as { id: string };
      const customerId = createCustomerId(params.id);
      const userToken = request.headers.authorization ?? "";

      const customer = await customerService.getCustomer(userToken, customerId);
      return reply.send(customer);
    } catch (err) {
      return mapError(reply, err);
    }
  });

  app.patch("/customers/:id/email", async (request, reply) => {
    try {
      const params = request.params as { id: string };
      const customerId = createCustomerId(params.id);
      const body = updateEmailSchema.parse(request.body);
      const userToken = request.headers.authorization ?? "";

      const customer = await customerService.updateCustomerEmail(
        userToken,
        customerId,
        body.email
      );

      return reply.send(customer);
    } catch (err) {
      return mapError(reply, err);
    }
  });
}

function mapError(reply: any, err: unknown) {
  if (err instanceof NotFoundError) {
    return reply.status(404).send({ error: err.message });
  }
  if (err instanceof ValidationError) {
    return reply.status(400).send({ error: err.message });
  }
  if (err instanceof IntegrationError) {
    return reply.status(502).send({ error: err.message });
  }
  if (err instanceof z.ZodError) {
    return reply.status(400).send({
      error: "Invalid request",
      details: err.flatten()
    });
  }

  return reply.status(500).send({ error: "Internal server error" });
}
```

