import type { CustomerRepository } from "../../domain/ports/customer-repository.js";
import { Err, Ok, type Result } from "../../shared/result.js";
import { CustomerNotFoundError } from "../../domain/errors/customer-errors.js";
import type { GetCustomerInput, GetCustomerOutput } from "../dto/get-customer.dto.js";
import type { CustomerId } from "../../domain/entities/customer.js";

export class GetCustomerUseCase {
  constructor(private readonly customerRepository: CustomerRepository) {}

  async execute(input: GetCustomerInput): Promise<Result<GetCustomerOutput, Error>> {
    const customerId = input.customerId as CustomerId;
    const customer = await this.customerRepository.findById(customerId);

    if (!customer) {
      return Err(new CustomerNotFoundError(input.customerId));
    }

    return Ok({
      customerId: customer.id,
      externalReference: customer.externalReference,
      fullName: customer.fullName,
      email: customer.email,
      createdAt: customer.createdAt.toISOString()
    });
  }
}
