## HTTP layer

### `src/infrastructure/http/routes/customer-routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { GetCustomerUseCase } from "../../../application/use-cases/get-customer.js";

const ParamsSchema = z.object({
  customerId: z.string().min(1)
});

export async function customerRoutes(
  app: FastifyInstance,
  deps: { getCustomerUseCase: GetCustomerUseCase }
): Promise<void> {
  app.get("/customers/:customerId", async (request, reply) => {
    const parsed = ParamsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid customerId",
        details: parsed.error.flatten()
      });
    }

    const result = await deps.getCustomerUseCase.execute({
      customerId: parsed.data.customerId
    });

    if (!result.ok) {
      if (result.error.name === "CustomerNotFoundError") {
        return reply.status(404).send({ error: result.error.message });
      }
      return reply.status(500).send({ error: "Internal server error" });
    }

    return reply.status(200).send(result.value);
  });
}
```

