### `src/modules/customers/customers.service.ts`

```ts
import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../infra/prisma/prisma.service';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { UpdateCustomerDto } from './dto/update-customer.dto';
import { CrmClient } from '../../infra/integrations/crm/crm.client';
import { IdentityClient } from '../../infra/integrations/identity/identity.client';
import { toDomainCustomer } from './mapper/customer.mapper';

@Injectable()
export class CustomersService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly crmClient: CrmClient,
    private readonly identityClient: IdentityClient
  ) {}

  async create(dto: CreateCustomerDto) {
    const existingIdentity = await this.identityClient.getUserByEmail(dto.email);
    if (!existingIdentity) {
      // In many enterprises, creation might be blocked or routed depending on identity state
      // This is intentionally strict to illustrate integration gating.
    }

    const created = await this.prisma.customer.create({
      data: {
        corporateId: dto.corporateId,
        firstName: dto.firstName,
        lastName: dto.lastName,
        email: dto.email,
        status: dto.status
      }
    });

    await this.crmClient.syncCustomer({
      corporateId: created.corporateId,
      email: created.email,
      firstName: created.firstName,
      lastName: created.lastName,
      status: created.status
    });

    return toDomainCustomer(created);
  }

  async findById(id: string) {
    const row = await this.prisma.customer.findUnique({ where: { id } });
    if (!row) throw new NotFoundException(`Customer ${id} not found`);
    return toDomainCustomer(row);
  }

  async update(id: string, dto: UpdateCustomerDto) {
    await this.findById(id);

    const updated = await this.prisma.customer.update({
      where: { id },
      data: dto
    });

    await this.crmClient.syncCustomer({
      corporateId: updated.corporateId,
      email: updated.email,
      firstName: updated.firstName,
      lastName: updated.lastName,
      status: updated.status
    });

    return toDomainCustomer(updated);
  }
}
```

