@Injectable()
export class CorpDirectoryClient {
  constructor(private readonly httpService: HttpService) {}

  async getEmployeeByEmail(email: string): Promise<CorpDirectoryEmployee | null> {
    try {
      const response = await firstValueFrom(
        this.httpService.get<CorpDirectoryEmployee | null>(`/employees/by-email`, {
          params: { email }
        })
      );

      return response.data;
    } catch (err: unknown) {
      throw new AppError(
        ErrorCodes.CORP_DIRECTORY_UNAVAILABLE,
        'Corporate directory lookup failed',
