import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { AppError } from '../../common/errors/app-error';
import { ErrorCodes } from '../../common/errors/error-codes';
import { CorpDirectoryClient } from '../../integrations/corp-directory/corp-directory.client';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { Customer } from './customer.types';

@Injectable()
export class CustomerService {
  constructor(private readonly corpDirectoryClient: CorpDirectoryClient) {}

  async createCustomer(input: CreateCustomerDto): Promise<Customer> {
    const corpEmployee = await this.corpDirectoryClient.getEmployeeByEmail(input.email);

    if (!corpEmployee) {
      throw new AppError(
        ErrorCodes.CUSTOMER_NOT_FOUND,
        'Customer must exist in corporate directory before onboarding'
      );
    }

    return {
      id: randomUUID(),
      email: corpEmployee.email,
      fullName: corpEmployee.displayName,
      department: corpEmployee.department ?? input.department,
      source: 'corp-directory',
      createdAt: new Date().toISOString()
    };
  }
}
