## 12) Service layer

### `src/services/customer.service.ts`

```ts
import { AppError } from '../utils/errors.js';
import { CustomerRepository } from '../repositories/customer.repository.js';
import { CorporateSystemClient } from '../clients/corporate-system.client.js';
import { CreateCustomerInput } from '../schemas/customer.schema.js';

export class CustomerService {
  constructor(
    private readonly customerRepo: CustomerRepository,
    private readonly corporateClient: CorporateSystemClient
  ) {}

  async createCustomer(input: CreateCustomerInput) {
    const existing = await this.customerRepo.findById(input.email);
    if (existing) {
      throw new AppError('Customer already exists', 409, 'CUSTOMER_EXISTS');
    }

    const corporate = await this.corporateClient.syncCustomer(input);

    return this.customerRepo.create({
      ...input,
      externalId: corporate.externalId
    });
  }

  async getCustomer(id: string) {
    const customer = await this.customerRepo.findById(id);
    if (!customer) {
      throw new AppError('Customer not found', 404, 'CUSTOMER_NOT_FOUND');
    }
    return customer;
  }
}
```

