## 6. Corporate integration adapter: `src/integrations/corporateSystems.ts`

This is the extension point for ERP/CRM/HRIS/mainframe systems.

```ts
export interface CorporateCustomerProfile {
  employeeId?: string;
  costCenter?: string;
  legalEntity?: string;
}

export interface CorporateSystemsClient {
  fetchCustomerProfile(customerId: string): Promise<CorporateCustomerProfile | null>;
}

export class HttpCorporateSystemsClient implements CorporateSystemsClient {
  constructor(
    private readonly baseUrl: string,
    private readonly token: string
  ) {}

  async fetchCustomerProfile(customerId: string): Promise<CorporateCustomerProfile | null> {
    const response = await fetch(`${this.baseUrl}/customer-profiles/${customerId}`, {
      headers: {
        Authorization: `Bearer ${this.token}`
      }
    });

    if (response.status === 404) return null;
    if (!response.ok) {
      throw new Error(`Corporate system request failed: ${response.status}`);
    }

    return (await response.json()) as CorporateCustomerProfile;
  }
}

export class NoopCorporateSystemsClient implements CorporateSystemsClient {
  async fetchCustomerProfile(): Promise<CorporateCustomerProfile | null> {
    return null;
  }
}
```

