## 9. Customer service: `src/modules/customers/customer.service.ts`

```ts
import { prisma } from "../../db/prisma.js";
import type { CorporateSystemsClient } from "../../integrations/corporateSystems.js";
import type { CreateCustomerInput } from "./customer.schemas.js";

export class CustomerService {
  constructor(private readonly corporateClient: CorporateSystemsClient) {}

  async createCustomer(input: CreateCustomerInput) {
    return prisma.customer.create({
      data: {
        name: input.name,
        email: input.email,
        externalId: input.externalId ?? null
      }
    });
  }

  async getCustomerById(id: string) {
    const customer = await prisma.customer.findUnique({
      where: { id }
    });

    if (!customer) return null;

    const corporateProfile = await this.corporateClient.fetchCustomerProfile(customer.id);

    return {
      ...customer,
      corporateProfile
    };
  }
}
```

