## 10. Customer routes: `src/modules/customers/customer.routes.ts`

```ts
import type { FastifyPluginAsync } from "fastify";
import { CustomerService } from "./customer.service.js";
import { createCustomerSchema, customerParamsSchema } from "./customer.schemas.js";
import { env } from "../../config/env.js";
import { HttpCorporateSystemsClient, NoopCorporateSystemsClient } from "../../integrations/corporateSystems.js";

const customerRoutes: FastifyPluginAsync = async (app) => {
  const corporateClient =
    env.CORPORATE_API_BASE_URL && env.CORPORATE_API_TOKEN
      ? new HttpCorporateSystemsClient(env.CORPORATE_API_BASE_URL, env.CORPORATE_API_TOKEN)
      : new NoopCorporateSystemsClient();

  const service = new CustomerService(corporateClient);

  app.post(
    "/customers",
    { preHandler: [app.authenticate] },
    async (request, reply) => {
      const input = createCustomerSchema.parse(request.body);
      const customer = await service.createCustomer(input);
      return reply.code(201).send(customer);
    }
  );

  app.get(
    "/customers/:id",
    { preHandler: [app.authenticate] },
    async (request, reply) => {
      const params = customerParamsSchema.parse(request.params);
      const customer = await service.getCustomerById(params.id);

      if (!customer) {
        return reply.code(404).send({ message: "Customer not found" });
      }

      return reply.send(customer);
    }
  );
};

export default customerRoutes;
```

