import { z } from "zod";
import type { AppConfig, Environment } from "./types.js";

const envSchema = z.object({
  PORT: z.coerce.number().int().positive().default(3000),
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
  CORPORATE_API_BASE_URL: z.string().url(),
  CORPORATE_API_TOKEN: z.string().min(1)
});

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const parsed = envSchema.parse(env);

  return {
    port: parsed.PORT,
    nodeEnv: parsed.NODE_ENV as Environment,
    corporateApiBaseUrl: parsed.CORPORATE_API_BASE_URL,
    corporateApiToken: parsed.CORPORATE_API_TOKEN
  };
}
```

