# 11) `src/routes/userRoutes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { userIdParamsSchema, syncRequestSchema, userSchema, syncResponseSchema } from "../schemas/userSchemas.js";
import type { UserService } from "../services/userService.js";

export async function userRoutes(app: FastifyInstance, service: UserService): Promise<void> {
  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/v1/users/:id", {
    schema: {
      params: userIdParamsSchema,
      response: {
        200: userSchema
      }
    }
  }, async (request, reply) => {
    const { id } = userIdParamsSchema.parse(request.params);
    const user = await service.getUser(id);

    if (!user) {
      return reply.status(404).send({ error: "User not found" });
    }

    return user;
  });

  app.post("/v1/users/sync", {
    schema: {
      body: syncRequestSchema,
      response: {
        200: syncResponseSchema
      }
    }
  }, async (request) => {
    const body = syncRequestSchema.parse(request.body);
    return service.syncUsers(body.department);
  });
}
```

