## 7) Corporate integration adapter: `src/adapters/corporateSystem.ts`

This is a clean place to integrate with an existing internal system.

```ts
export type CorporateSyncPayload = {
  employeeId: string;
  email: string;
  name: string;
};

export interface CorporateSystemClient {
  syncUser(payload: CorporateSyncPayload): Promise<void>;
}

export class HttpCorporateSystemClient implements CorporateSystemClient {
  constructor(
    private readonly baseUrl: string,
    private readonly token: string
  ) {}

  async syncUser(payload: CorporateSyncPayload): Promise<void> {
    const res = await fetch(`${this.baseUrl}/users/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.token}`
      },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      throw new Error(`Corporate sync failed: ${res.status} ${res.statusText}`);
    }
  }
}
```

