## 8) Service layer: `src/services/userService.ts`

```ts
import { prisma } from "../db/prisma.js";
import type { CorporateSystemClient } from "../adapters/corporateSystem.js";
import type { CreateUserInput } from "../types/user.js";

export class UserService {
  constructor(private readonly corporateClient: CorporateSystemClient) {}

  async createUser(input: CreateUserInput) {
    const user = await prisma.user.create({
      data: input
    });

    await this.corporateClient.syncUser({
      employeeId: user.employeeId,
      email: user.email,
      name: user.name
    });

    return user;
  }

  async listUsers() {
    return prisma.user.findMany({
      orderBy: { createdAt: "desc" }
    });
  }
}
```

