```ts
import { config } from "../config.js";

export type CorporateEmployeeRecord = {
  employeeNo: string;
  active: boolean;
  department?: string;
};

export class CorporateHrClient {
  async lookupEmployee(employeeNo: string): Promise<CorporateEmployeeRecord | null> {
    const url = new URL(`/employees/${encodeURIComponent(employeeNo)}`, config.CORPORATE_HR_BASE_URL);

    const res = await fetch(url, {
      headers: {
        "Authorization": `Bearer ${config.CORPORATE_HR_API_KEY}`,
        "Accept": "application/json"
      }
    });

    if (res.status === 404) return null;
    if (!res.ok) {
      throw new Error(`Corporate HR lookup failed with status ${res.status}`);
    }

    return (await res.json()) as CorporateEmployeeRecord;
  }
}
```

