```ts
import { db } from "../db.js";
import type { CreateEmployeeInput } from "../schemas/employee.schema.js";
import { CorporateHrClient } from "../clients/corporate-hr.client.js";

const hrClient = new CorporateHrClient();

export class EmployeeService {
  async createEmployee(input: CreateEmployeeInput) {
    const hrRecord = await hrClient.lookupEmployee(input.employeeNo);

    if (!hrRecord) {
      throw new Error("Employee not found in corporate HR system");
    }

    if (!hrRecord.active) {
      throw new Error("Employee is not active in corporate HR system");
    }

    return await db.employee.create({
      data: {
        employeeNo: input.employeeNo,
        firstName: input.firstName,
        lastName: input.lastName,
        email: input.email
      }
    });
  }

  async getEmployeeByEmployeeNo(employeeNo: string) {
    return await db.employee.findUnique({
      where: { employeeNo }
    });
  }
}
