## 13) App setup: `src/app.ts`

```ts
import Fastify from "fastify";
import { logger } from "./logger.js";
import { healthRoutes } from "./routes/health.js";

export function buildApp() {
  const app = Fastify({
    logger
  });

  app.register(healthRoutes);

  app.post("/employees", async (request, reply) => {
    const { CreateEmployeeSchema } = await import("./schemas/employee.schema.js");
    const { EmployeeService } = await import("./services/employee.service.js");

    const parsed = CreateEmployeeSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        details: parsed.error.flatten()
      });
    }

    const service = new EmployeeService();

    try {
      const employee = await service.createEmployee(parsed.data);
      return reply.status(201).send(employee);
    } catch (err) {
      request.log.error({ err }, "Failed to create employee");
      return reply.status(409).send({
        error: "CreateEmployeeFailed",
        message: err instanceof Error ? err.message : "Unknown error"
      });
    }
  });

  app.get("/employees/:employeeNo", async (request, reply) => {
    const paramsSchema = (await import("zod")).z.object({
      employeeNo: (await import("zod")).z.string().min(1)
    });

    const parsed = paramsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        details: parsed.error.flatten()
      });
    }

    const service = new (await import("./services/employee.service.js")).EmployeeService();
    const employee = await service.getEmployeeByEmployeeNo(parsed.data.employeeNo);

    if (!employee) {
      return reply.status(404).send({ error: "NotFound" });
    }

    return employee;
  });

  return app;
}
```

