## 12) Service layer: `src/modules/customer/customer.service.ts`

```ts
import { CustomerRepository } from "./customer.repo.js";
import { CorporateSystemClient } from "../../integrations/corporateSystem.client.js";
import { CreateCustomerInput } from "./customer.schema.js";

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly corporateClient: CorporateSystemClient
  ) {}

  async createCustomer(input: CreateCustomerInput) {
    const existing = await this.repo.findByEmail(input.email);
    if (existing) {
      throw new Error("Customer already exists");
    }

    const corporate = await this.corporateClient.createCustomer({
      name: input.name,
      email: input.email
    });

    return this.repo.create({
      ...input,
      externalId: corporate.externalId
    });
  }
}
