import { CustomerRepository } from "./modules/customer/customer.repo.js";
import { CorporateSystemClient } from "./integrations/corporateSystem.client.js";
import { CustomerService } from "./modules/customer/customer.service.js";

export async function buildApp() {
  const app = Fastify({
    logger: true
  });

  await app.register(sensible);
  await app.register(swagger, {
    openapi: {
      info: {
        title: "Enterprise Service",
        version: "1.0.0"
      }
    }
  });
  await app.register(swaggerUI, { routePrefix: "/docs" });

  await app.register(jwt, { secret: env.JWT_SECRET });

  const prisma = new PrismaClient();
  const repo = new CustomerRepository(prisma);
  const corporateClient = new CorporateSystemClient(
    env.CORPORATE_SYSTEM_BASE_URL,
    env.CORPORATE_SYSTEM_API_KEY
  );
  const service = new CustomerService(repo, corporateClient);

  await app.register(healthRoute);
  await app.register(customerRoutes, { customerService: service });

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  return app;
}
