## `src/routes/employees.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import {
  CreateEmployeeSchema,
  EmployeeIdSchema,
  UpdateEmployeeSchema
} from "../schemas/employee.js";
import { createEmployee, getEmployeeById, updateEmployee } from "../services/employeeService.js";

export async function employeeRoutes(app: FastifyInstance): Promise<void> {
  app.post("/employees", async (request, reply) => {
    const input = CreateEmployeeSchema.parse(request.body);
    const employee = await createEmployee(input);
    return reply.code(201).send(employee);
  });

  app.get("/employees/:id", async (request, reply) => {
    const { id } = z.object({ id: EmployeeIdSchema }).parse(request.params);
    const employee = await getEmployeeById(id);
    if (!employee) return reply.code(404).send({ message: "Employee not found" });
    return employee;
  });

  app.put("/employees/:id", async (request, reply) => {
    const { id } = z.object({ id: EmployeeIdSchema }).parse(request.params);
    const input = UpdateEmployeeSchema.parse(request.body);
    const employee = await updateEmployee(id, input);
    if (!employee) return reply.code(404).send({ message: "Employee not found" });
    return employee;
  });
}
```

