## 8) `src/clients/corporate-system.ts`

This is a minimal typed client stub for integration with an existing corporate API.

```ts
import { z } from "zod";

const EmployeeSchema = z.object({
  id: z.string().min(1),
  firstName: z.string().min(1),
  lastName: z.string().min(1),
  email: z.string().email()
});

export type Employee = z.infer<typeof EmployeeSchema>;

export class CorporateSystemClient {
  constructor(
    private readonly baseUrl: string,
    private readonly token: string
  ) {}

  async fetchEmployee(employeeId: string): Promise<Employee> {
    const response = await fetch(`${this.baseUrl}/employees/${encodeURIComponent(employeeId)}`, {
      headers: {
        Authorization: `Bearer ${this.token}`,
        Accept: "application/json"
      }
    });

    if (!response.ok) {
      throw new Error(`Corporate system error: ${response.status} ${response.statusText}`);
    }

    const json: unknown = await response.json();
    return EmployeeSchema.parse(json);
    }
}
```

