import type { Pool } from "pg";
import type { CorporateSystemClient } from "../clients/corporate-system.js";

export class EmployeeSyncService {
  constructor(
    private readonly db: Pool,
    private readonly corporateClient: CorporateSystemClient
  ) {}

  async syncEmployee(employeeId: string): Promise<void> {
    const employee = await this.corporateClient.fetchEmployee(employeeId);

    await this.db.query(
      `
      INSERT INTO employees (id, first_name, last_name, email, updated_at)
      VALUES ($1, $2, $3, $4, NOW())
      ON CONFLICT (id) DO UPDATE
      SET first_name = EXCLUDED.first_name,
          last_name = EXCLUDED.last_name,
          email = EXCLUDED.email,
          updated_at = NOW()
      `,
      [employee.id, employee.firstName, employee.lastName, employee.email]
    );
  }
}
