## 11) `src/app.ts`

```ts
import Fastify from "fastify";
import type { Config } from "./config.js";
import { pingRoute } from "./routes/ping.js";
import { createDbPool, checkDb } from "./db.js";
import { CorporateSystemClient } from "./clients/corporate-system.js";
import { EmployeeSyncService } from "./services/employee-sync.js";

export function createApp(config: Config) {
  const app = Fastify({
    logger: true
  });

  const db = createDbPool(config);
  const corporateClient = new CorporateSystemClient(
    config.CORPORATE_API_BASE_URL,
    config.CORPORATE_API_TOKEN
  );
  const employeeSync = new EmployeeSyncService(db, corporateClient);

  app.register(pingRoute);

  app.get("/healthz", async () => {
    return { ok: true };
  });

  app.get("/readyz", async (_req, reply) => {
    const dbOk = await checkDb(db);
    if (!dbOk) {
      return reply.status(503).send({ ok: false, db: false });
    }
    return { ok: true, db: true };
  });

  app.post<{
    Params: { employeeId: string };
  }>("/employees/:employeeId/sync", async (request, reply) => {
    try {
      await employeeSync.syncEmployee(request.params.employeeId);
      return reply.status(204).send();
    } catch (err) {
      app.log.error({ err }, "employee sync failed");
      return reply.status(502).send({ ok: false, error: "sync_failed" });
    }
  });

  app.addHook("onClose", async () => {
    await db.end();
  });

  return app;
}
```

