# 9) Route handler

## `src/routes/userRoutes.ts`

```ts
import { FastifyInstance } from "fastify";
import { getUserParamsSchema, userResponseSchema } from "../schemas.js";
import { getCorporateUserById } from "../clients/corporateUserClient.js";

export async function userRoutes(app: FastifyInstance) {
  app.get("/users/:id", async (request, reply) => {
    const params = getUserParamsSchema.parse(request.params);

    try {
      const user = await getCorporateUserById(params.id);

      const response = userResponseSchema.parse(user);
      return reply.code(200).send(response);
    } catch (error) {
      request.log.error({ error }, "Failed to fetch user");
      return reply.code(502).send({
        error: "BAD_GATEWAY",
        message: "Failed to retrieve user from corporate system"
      });
    }
  });
}
```

