## 7) `src/db/employeeRepo.ts`

```ts
import { pool } from "./pool.js";
import { Employee } from "../types.js";

export async function findEmployeeById(id: string): Promise<Employee | null> {
  const result = await pool.query(
    `SELECT id, email, display_name, department, manager_id
     FROM employees
     WHERE id = $1`,
    [id]
  );

  const row = result.rows[0];
  if (!row) return null;

  return {
    id: row.id,
    email: row.email,
    displayName: row.display_name,
    department: row.department,
    managerId: row.manager_id,
    source: "database"
  };
}

export async function createEmployee(input: {
  email: string;
  displayName: string;
  department: string;
  managerId?: string;
}): Promise<Employee> {
  const result = await pool.query(
    `INSERT INTO employees (email, display_name, department, manager_id)
     VALUES ($1, $2, $3, $4)
     RETURNING id, email, display_name, department, manager_id`,
    [input.email, input.displayName, input.department, input.managerId ?? null]
  );

  const row = result.rows[0];
  return {
    id: row.id,
    email: row.email,
    displayName: row.display_name,
    department: row.department,
    managerId: row.manager_id,
    source: "database"
  };
}
```

