## 8) `src/integrations/corporateDirectoryClient.ts`

This demonstrates a typed integration boundary for an existing corporate system.

```ts
import { config } from "../config.js";
import { Employee, EmployeeSchema } from "../types.js";

type DirectoryEmployeeResponse = {
  id: string;
  email: string;
  displayName: string;
  department: string;
  managerId: string | null;
};

export async function fetchDirectoryEmployee(id: string): Promise<Employee | null> {
  const response = await fetch(
    `${config.CORPORATE_DIRECTORY_BASE_URL}/employees/${id}`,
    {
      headers: {
        Authorization: `Bearer ${config.CORPORATE_API_TOKEN}`,
        Accept: "application/json"
      }
    }
  );

  if (response.status === 404) return null;
  if (!response.ok) {
    throw new Error(`Corporate directory error: ${response.status}`);
  }

  const data = (await response.json()) as DirectoryEmployeeResponse;

  const parsed = EmployeeSchema.parse({
    ...data,
    source: "corporate-directory"
  });

  return parsed;
}
```

