## 11) `src/routes/employees.ts`

```ts
import { FastifyInstance } from "fastify";
import { CreateEmployeeSchema, EmployeeIdSchema } from "../types.js";
import { getEmployee, onboardEmployee } from "../services/employeeService.js";

export async function employeeRoutes(app: FastifyInstance) {
  app.get("/employees/:id", async (request, reply) => {
    const parsed = EmployeeIdSchema.safeParse(request.params.id);
    if (!parsed.success) {
      return reply.status(400).send({ error: "Invalid employee ID" });
    }

    const employee = await getEmployee(parsed.data);
    if (!employee) {
      return reply.status(404).send({ error: "Employee not found" });
    }

    return employee;
  });

  app.post("/employees", async (request, reply) => {
    const parsed = CreateEmployeeSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request",
        details: parsed.error.flatten()
      });
    }

    const employee = await onboardEmployee(parsed.data);
    return reply.status(201).send(employee);
  });
}
```

