## 13) src/routes/audit.ts

```ts
import type { FastifyInstance } from 'fastify';
import { AuditEventSchema } from '../schemas/auditEvent.js';
import { sendAuditEvent } from '../clients/auditClient.js';

export async function auditRoutes(app: FastifyInstance): Promise<void> {
  app.post('/v1/events/audit', async (request, reply) => {
    const parsed = AuditEventSchema.safeParse(request.body);

    if (!parsed.success) {
      return reply.status(400).send({
        message: 'Invalid audit event payload',
        issues: parsed.error.issues
      });
    }

    try {
      await sendAuditEvent(parsed.data);
      return reply.status(202).send({ status: 'accepted' });
    } catch (error) {
      request.log.error({ error }, 'Failed to send audit event');
      return reply.status(502).send({
        message: 'Failed to forward audit event to corporate audit system'
      });
    }
  });
}
```

