## 5) `src/logger.ts`

```ts
type LogLevel = "fatal" | "error" | "warn" | "info" | "debug" | "trace";

const levels: Record<LogLevel, number> = {
  fatal: 60,
  error: 50,
  warn: 40,
  info: 30,
  debug: 20,
  trace: 10
};

const configuredLevel = (process.env.LOG_LEVEL as LogLevel) ?? "info";
const threshold = levels[configuredLevel] ?? 30;

function log(level: LogLevel, message: string, meta?: Record<string, unknown>) {
  if (levels[level] < threshold) return;

  const event = {
    time: new Date().toISOString(),
    level,
    message,
    ...meta
  };

  console.log(JSON.stringify(event));
}

export const logger = {
  fatal: (msg: string, meta?: Record<string, unknown>) => log("fatal", msg, meta),
  error: (msg: string, meta?: Record<string, unknown>) => log("error", msg, meta),
  warn: (msg: string, meta?: Record<string, unknown>) => log("warn", msg, meta),
  info: (msg: string, meta?: Record<string, unknown>) => log("info", msg, meta),
  debug: (msg: string, meta?: Record<string, unknown>) => log("debug", msg, meta),
  trace: (msg: string, meta?: Record<string, unknown>) => log("trace", msg, meta)
};
```

