# 10. Corporate integration adapter

This simulates integration with an internal directory or identity system.

## src/integrations/corporateDirectory.ts
```ts
import { env } from "../lib/env.js";

export type CorporateUser = {
  employeeId: string;
  fullName: string;
  email: string;
  department: string;
};

export async function fetchCorporateUserByEmail(email: string): Promise<CorporateUser | null> {
  const url = new URL("/users", env.CORPORATE_DIRECTORY_BASE_URL);
  url.searchParams.set("email", email);

  const response = await fetch(url, {
    headers: {
      "Authorization": `Bearer ${env.CORPORATE_DIRECTORY_API_KEY}`,
      "Accept": "application/json"
    }
  });

  if (response.status === 404) return null;
  if (!response.ok) {
    throw new Error(`Corporate directory lookup failed with status ${response.status}`);
  }

  const data: unknown = await response.json();

  // Minimal runtime validation without extra dependencies
  if (
    typeof data === "object" &&
    data !== null &&
    "employeeId" in data &&
    "fullName" in data &&
    "email" in data &&
    "department" in data
  ) {
    const candidate = data as Record<string, unknown>;
    if (
      typeof candidate.employeeId === "string" &&
      typeof candidate.fullName === "string" &&
      typeof candidate.email === "string" &&
      typeof candidate.department === "string"
    ) {
      return candidate as CorporateUser;
    }
  }

  throw new Error("Invalid corporate directory response");
}
```

