import { prisma } from "../lib/prisma.js";
import type { CreateCustomerInput } from "../schemas/customer.js";
import { fetchCorporateUserByEmail } from "../integrations/corporateDirectory.js";

export async function createCustomer(input: CreateCustomerInput) {
  const corporateUser = await fetchCorporateUserByEmail(input.email);

  const customer = await prisma.customer.create({
    data: {
      name: corporateUser?.fullName ?? input.name,
      email: input.email
    }
  });

  return {
    ...customer,
    createdAt: customer.createdAt.toISOString(),
    updatedAt: customer.updatedAt.toISOString(),
    corporate: corporateUser
  };
}

export async function getCustomerById(id: string) {
  const customer = await prisma.customer.findUnique({ where: { id } });
  if (!customer) return null;

  return {
    ...customer,
    createdAt: customer.createdAt.toISOString(),
    updatedAt: customer.updatedAt.toISOString()
  };
}
```

