import { CreateCustomerSchema, CustomerSchema } from "../schemas/customer.js";
import { createCustomer, getCustomerById } from "../services/customerService.js";

export async function customerRoutes(app: FastifyInstance) {
  app.post("/customers", async (request, reply) => {
    const parsed = CreateCustomerSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    try {
      const customer = await createCustomer(parsed.data);
      return reply.status(201).send(customer);
    } catch (err) {
      request.log.error(err);
      return reply.status(500).send({ error: "Internal server error" });
    }
  });

  app.get("/customers/:id", async (request, reply) => {
    const id = (request.params as { id?: string }).id;
    if (!id) {
      return reply.status(400).send({ error: "Missing id" });
    }

    const customer = await getCustomerById(id);
    if (!customer) {
      return reply.status(404).send({ error: "Customer not found" });
    }

    const validation = CustomerSchema.safeParse(customer);
    if (!validation.success) {
      request.log.error(validation.error);
      return reply.status(500).send({ error: "Invalid customer shape" });
    }

    return reply.send(validation.data);
  });
}
```

