## 8) `src/integrations/corporateSystemClient.ts`

```ts
import { env } from "../config/env.js";
import type { Employee } from "../types.js";

export class CorporateSystemClient {
  async getEmployeeById(id: string): Promise<Employee | null> {
    const url = new URL(`/api/employees/${encodeURIComponent(id)}`, env.CORPORATE_SYSTEM_BASE_URL);

    const response = await fetch(url, {
      method: "GET",
      headers: {
        "Authorization": `Bearer ${env.CORPORATE_SYSTEM_API_KEY}`,
        "Accept": "application/json"
      }
    });

    if (response.status === 404) return null;
    if (!response.ok) {
      throw new Error(`Corporate system request failed with status ${response.status}`);
    }

    const data = (await response.json()) as unknown;

    // Minimal runtime check; in production, validate with Zod here too
    if (
      typeof data === "object" &&
      data !== null &&
      "id" in data &&
      "firstName" in data &&
      "lastName" in data &&
      "department" in data &&
      "title" in data
    ) {
      const employee = data as Employee;
      return employee;
    }

    throw new Error("Invalid employee payload from corporate system");
  }
}
```

