## 10) `src/routes/employee.ts`

```ts
import type { FastifyInstance } from "fastify";
import { employeeIdParamsSchema, employeeLookupResponseSchema } from "../schemas/employee.js";
import { CorporateSystemClient } from "../integrations/corporateSystemClient.js";

const localCache = new Map<string, { id: string; firstName: string; lastName: string; department: string; title: string }>([
  ["1001", { id: "1001", firstName: "Jane", lastName: "Doe", department: "Finance", title: "Analyst" }]
]);

export async function employeeRoutes(app: FastifyInstance) {
  const client = new CorporateSystemClient();

  app.get("/employees/:id", {
    schema: {
      params: {
        type: "object",
        required: ["id"],
        properties: {
          id: { type: "string" }
        }
      },
      response: {
        200: {
          type: "object",
          required: ["source", "employee"],
          properties: {
            source: { type: "string", enum: ["local-cache", "corporate-system"] },
            employee: {
              type: "object",
              required: ["id", "firstName", "lastName", "department", "title"],
              properties: {
                id: { type: "string" },
                firstName: { type: "string" },
                lastName: { type: "string" },
                department: { type: "string" },
                title: { type: "string" }
              }
            }
          }
        }
      }
    }
  }, async (request, reply) => {
    const { id } = employeeIdParamsSchema.parse(request.params);

    const cached = localCache.get(id);
    if (cached) {
      const response = {
        source: "local-cache" as const,
        employee: cached
      };
      employeeLookupResponseSchema.parse(response);
      return reply.send(response);
    }

    const employee = await client.getEmployeeById(id);
    if (!employee) {
      return reply.code(404).send({ message: "Employee not found" });
    }

    const response = {
      source: "corporate-system" as const,
      employee
    };

    employeeLookupResponseSchema.parse(response);
    return reply.send(response);
  });
}
```

