import { env } from "../config/env.js";
import type { Contract } from "../types/contract.js";

export class CorporateSystemClient {
  async fetchContracts(): Promise<Contract[]> {
    const response = await fetch(`${env.CORPORATE_API_BASE_URL}/contracts`, {
      headers: {
        Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
        "Content-Type": "application/json"
      }
    });

    if (!response.ok) {
      throw new Error(`Corporate system error: ${response.status} ${response.statusText}`);
    }

    const data = (await response.json()) as unknown;
    return data as Contract[];
  }

  async createContract(title: string): Promise<Contract> {
    const response = await fetch(`${env.CORPORATE_API_BASE_URL}/contracts`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ title })
    });

    if (!response.ok) {
      throw new Error(`Corporate system error: ${response.status} ${response.statusText}`);
    }

    const data = (await response.json()) as unknown;
    return data as Contract;
  }
}
