import type { FastifyPluginAsync } from "fastify";
import { CreateContractInputSchema } from "../types/contract.js";
import { ContractService } from "../services/contractService.js";

export const contractRoutes: FastifyPluginAsync = async (fastify) => {
  const service = new ContractService();

  fastify.get("/contracts", async () => {
    const contracts = await service.listContracts();
    return contracts;
  });

  fastify.post("/contracts", async (request, reply) => {
    const parsed = CreateContractInputSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    const created = await service.createContract(parsed.data.title);
    return reply.status(201).send(created);
  });
};
