## 6) Corporate system integration client: `src/integrations/corporateSystemClient.ts`

This is the abstraction that isolates integration with existing enterprise systems.

```ts
import { env } from "../config/env.js";
import type { Customer } from "../types/customer.js";

type CorporateApiCustomerResponse = {
  id: string;
  name: string;
  email?: string;
  status: "ACTIVE" | "INACTIVE";
};

export class CorporateSystemClient {
  async getCustomerById(customerId: string): Promise<Customer | null> {
    const response = await fetch(`${env.CORPORATE_API_BASE_URL}/customers/${customerId}`, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
        "Content-Type": "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate system error: ${response.status}`);
    }

    const data = (await response.json()) as CorporateApiCustomerResponse;

    return {
      id: data.id,
      displayName: data.name,
      email: data.email,
      active: data.status === "ACTIVE"
    };
  }
}
```

