## 8) Customer endpoint: `src/endpoints/customer.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CorporateSystemClient } from "../integrations/corporateSystemClient.js";

const paramsSchema = z.object({
  id: z.string().min(1)
});

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const client = new CorporateSystemClient();

  app.get("/customers/:id", async (request, reply) => {
    const parsed = paramsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.code(400).send({
        error: "Invalid customer id"
      });
    }

    const customer = await client.getCustomerById(parsed.data.id);

    if (!customer) {
      return reply.code(404).send({
        error: "Customer not found"
      });
    }

    return reply.send(customer);
  });
}
```

