```csharp
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Application.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _db;

    public CustomerService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<List<Customer>> GetAllAsync()
        => await _db.Customers.OrderByDescending(x => x.CreatedAtUtc).ToListAsync();

    public async Task<Customer?> GetByIdAsync(Guid id)
        => await _db.Customers.FirstOrDefaultAsync(x => x.Id == id);

    public async Task<Customer> CreateAsync(string name, string email)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new ArgumentException("Name is required.");

        if (string.IsNullOrWhiteSpace(email))
            throw new ArgumentException("Email is required.");

        var customer = new Customer
        {
            Name = name.Trim(),
            Email = email.Trim().ToLowerInvariant()
        };

