using Azure.Identity;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.EntityFrameworkCore;
using Microsoft.Identity.Web;
using Serilog;
using EnterpriseService.Application.Interfaces;
using EnterpriseService.Infrastructure.Persistence;
using EnterpriseService.Infrastructure.Services;

var builder = WebApplication.CreateBuilder(args);

// Serilog
builder.Host.UseSerilog((ctx, lc) =>
{
    lc.ReadFrom.Configuration(ctx.Configuration)
      .Enrich.FromLogContext()
      .WriteTo.Console();
});

// Configuration
var configuration = builder.Configuration;

// Key Vault integration for Azure-hosted environments
if (!builder.Environment.IsDevelopment())
{
    var keyVaultUrl = configuration["KeyVault:VaultUri"];
    if (!string.IsNullOrWhiteSpace(keyVaultUrl))
    {
        configuration.AddAzureKeyVault(new Uri(keyVaultUrl), new DefaultAzureCredential());
    }
}

// Services
builder.Services.AddControllers();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();

// Auth (Azure AD / Entra ID)
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddMicrosoftIdentityWebApi(configuration.GetSection("AzureAd"));

// Authorization
builder.Services.AddAuthorization();

// EF Core
builder.Services.AddDbContext<AppDbContext>(options =>
{
    var connStr = configuration.GetConnectionString("DefaultConnection");
    options.UseSqlServer(connStr, sql =>
    {
        sql.EnableRetryOnFailure(5);
    });
});

// Application services
builder.Services.AddScoped<IOrderService, OrderService>();

// Health checks
builder.Services.AddHealthChecks()
    .AddDbContextCheck<AppDbContext>("database");

// Serilog request logging
var app = builder.Build();

app.UseSerilogRequestLogging();

if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseHttpsRedirection();

app.UseAuthentication();
app.UseAuthorization();

app.MapHealthChecks("/health");
app.MapControllers();

app.Run();
