using EnterpriseBackend.Application.Contracts;
using EnterpriseBackend.Application.Models;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Application.Services;

public class CustomerService : ICustomerService
{
    private readonly EnterpriseDbContext _db;

    public CustomerService(EnterpriseDbContext db)
    {
        _db = db;
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var customer = await _db.Customers
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id, cancellationToken);

        return customer is null ? null : Map(customer);
    }

    public async Task<IReadOnlyList<CustomerDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var customers = await _db.Customers
            .AsNoTracking()
            .OrderBy(x => x.DisplayName)
            .ToListAsync(cancellationToken);

        return customers.Select(Map).ToList();
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerRequest request, CancellationToken cancellationToken = default)
    {
        var customer = new Customer
        {
            Id = Guid.NewGuid(),
            EmployeeNumber = request.EmployeeNumber.Trim(),
            DisplayName = request.DisplayName.Trim(),
            Email = request.Email.Trim(),
            CreatedAtUtc = DateTimeOffset.UtcNow
        };

        _db.Customers.Add(customer);
        await _db.SaveChangesAsync(cancellationToken);

        return Map(customer);
    }

    public async Task<bool> UpdateAsync(Guid id, UpdateCustomerRequest request, CancellationToken cancellationToken = default)
    {
        var customer = await _db.Customers.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (customer is null) return false;

        customer.DisplayName = request.DisplayName.Trim();
        customer.Email = request.Email.Trim();
        customer.UpdatedAtUtc = DateTimeOffset.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var customer = await _db.Customers.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (customer is null) return false;

        _db.Customers.Remove(customer);
        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }

    private static CustomerDto Map(Customer customer) => new()
    {
        Id = customer.Id,
        EmployeeNumber = customer.EmployeeNumber,
        DisplayName = customer.DisplayName,
        Email = customer.Email,
        CreatedAtUtc = customer.CreatedAtUtc,
        UpdatedAtUtc = customer.UpdatedAtUtc
    };
}
