## `Middleware/GlobalExceptionMiddleware.cs`

```csharp
using System.Net;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Api.Middleware;

public class GlobalExceptionMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<GlobalExceptionMiddleware> _logger;

    public GlobalExceptionMiddleware(RequestDelegate next, ILogger<GlobalExceptionMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await _next(context);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unhandled exception");

            var problem = new ProblemDetails
            {
                Status = (int)HttpStatusCode.InternalServerError,
                Title = "An unexpected error occurred.",
                Detail = appEnvironmentDetail(context)
            };

            context.Response.StatusCode = problem.Status.Value;
            context.Response.ContentType = "application/problem+json";
            await context.Response.WriteAsJsonAsync(problem);
        }
    }

    private static string? appEnvironmentDetail(HttpContext context)
        => context.RequestServices.GetService<IWebHostEnvironment>()?.IsDevelopment() == true
            ? "See logs for more details."
            : null;
}
```

