using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Application.Models;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;

namespace EnterpriseBackend.Application.Services;

public class OrderService : IOrderService
{
    private readonly EnterpriseDbContext _dbContext;

    public OrderService(EnterpriseDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<OrderDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var order = await _dbContext.Orders.FindAsync(new object[] { id }, cancellationToken);
        return order is null ? null : ToDto(order);
    }

    public async Task<OrderDto> CreateAsync(CreateOrderRequest request, CancellationToken cancellationToken)
    {
        var order = new Order
        {
            Id = Guid.NewGuid(),
            CustomerName = request.CustomerName,
            Amount = request.Amount,
            CreatedUtc = DateTime.UtcNow
        };

        _dbContext.Orders.Add(order);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return ToDto(order);
    }

    private static OrderDto ToDto(Order order)
        => new(order.Id, order.CustomerName, order.Amount, order.CreatedUtc);
}
