using EnterpriseService.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseService.Api.Data.Repositories;

public class EmployeeRepository : IEmployeeRepository
{
    private readonly AppDbContext _db;

    public EmployeeRepository(AppDbContext db) => _db = db;

    public Task<List<Employee>> GetAllAsync(CancellationToken cancellationToken = default) =>
        _db.Employees.AsNoTracking().OrderBy(e => e.LastName).ToListAsync(cancellationToken);

    public Task<Employee?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default) =>
        _db.Employees.FirstOrDefaultAsync(e => e.Id == id, cancellationToken);

    public Task<Employee?> GetByEmailAsync(string email, CancellationToken cancellationToken = default) =>
        _db.Employees.FirstOrDefaultAsync(e => e.Email == email, cancellationToken);

    public async Task AddAsync(Employee employee, CancellationToken cancellationToken = default) =>
        await _db.Employees.AddAsync(employee, cancellationToken);

    public Task SaveChangesAsync(CancellationToken cancellationToken = default) =>
        _db.SaveChangesAsync(cancellationToken);

    public void Remove(Employee employee) => _db.Employees.Remove(employee);
}
