```csharp
using EnterpriseService.Api.Data.Repositories;
using EnterpriseService.Api.Models;

namespace EnterpriseService.Api.Services;

public class EmployeeService : IEmployeeService
{
    private readonly IEmployeeRepository _repository;

    public EmployeeService(IEmployeeRepository repository)
    {
        _repository = repository;
    }

    public async Task<List<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var employees = await _repository.GetAllAsync(cancellationToken);
        return employees.Select(ToDto).ToList();
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _repository.GetByIdAsync(id, cancellationToken);
        return employee is null ? null : ToDto(employee);
    }

    public async Task<EmployeeDto> CreateAsync(
        string firstName,
        string lastName,
        string email,
        string department,
        CancellationToken cancellationToken = default)
    {
        var existing = await _repository.GetByEmailAsync(email, cancellationToken);
        if (existing is not null)
            throw new InvalidOperationException("Employee with the same email already exists.");

        var employee = new Employee
        {
            FirstName = firstName.Trim(),
            LastName = lastName.Trim(),
            Email = email.Trim().ToLowerInvariant(),
            Department = department.Trim()
        };

        await _repository.AddAsync(employee, cancellationToken);
        await _repository.SaveChangesAsync(cancellationToken);

        return ToDto(employee);
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _repository.GetByIdAsync(id, cancellationToken);
        if (employee is null) return false;

        _repository.Remove(employee);
        await _repository.SaveChangesAsync(cancellationToken);
        return true;
    }

    private static EmployeeDto ToDto(Employee employee) =>
        new(employee.Id, employee.FirstName, employee.LastName, employee.Email, employee.Department);
}
```

