using EnterpriseService.Api.Data;
using EnterpriseService.Api.Data.Repositories;
using EnterpriseService.Api.Services;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseService.Api.Extensions;

public static class ServiceCollectionExtensions
{
    public static IServiceCollection AddEnterpriseServices(this IServiceCollection services, IConfiguration configuration)
    {
        services.AddDbContext<AppDbContext>(options =>
        {
            var connectionString = configuration.GetConnectionString("DefaultConnection");
            options.UseSqlServer(connectionString, sql =>
            {
                sql.EnableRetryOnFailure();
            });
        });

        services.AddScoped<IEmployeeRepository, EmployeeRepository>();
        services.AddScoped<IEmployeeService, EmployeeService>();

        services.AddHealthChecks()
            .AddDbContextCheck<AppDbContext>("database");

        return services;
    }
}
