## 7) Service implementation: `OrderService.cs`

```csharp
using EnterpriseService.Application.DTOs;
using EnterpriseService.Application.Interfaces;
using EnterpriseService.Domain.Entities;
using EnterpriseService.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseService.Application.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _db;

    public OrderService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken cancellationToken)
    {
        var order = new Order
        {
            OrderNumber = request.OrderNumber,
            CustomerName = request.CustomerName,
            TotalAmount = request.TotalAmount
        };

        _db.Orders.Add(order);
        await _db.SaveChangesAsync(cancellationToken);

        return Map(order);
    }

    public async Task<OrderResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var order = await _db.Orders.FirstOrDefaultAsync(o => o.Id == id, cancellationToken);
        return order is null ? null : Map(order);
    }

    public async Task<IEnumerable<OrderResponse>> GetAllAsync(CancellationToken cancellationToken)
    {
        return await _db.Orders
            .OrderByDescending(o => o.CreatedUtc)
            .Select(o => new OrderResponse
            {
                Id = o.Id,
                OrderNumber = o.OrderNumber,
                CustomerName = o.CustomerName,
                TotalAmount = o.TotalAmount,
                CreatedUtc = o.CreatedUtc,
                IsCancelled = o.IsCancelled
            })
            .ToListAsync(cancellationToken);
    }

    public async Task<bool> CancelAsync(Guid id, CancellationToken cancellationToken)
    {
        var order = await _db.Orders.FirstOrDefaultAsync(o => o.Id == id, cancellationToken);
        if (order is null) return false;

        order.IsCancelled = true;
        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }

    private static OrderResponse Map(Order order) => new()
    {
        Id = order.Id,
        OrderNumber = order.OrderNumber,
        CustomerName = order.CustomerName,
        TotalAmount = order.TotalAmount,
        CreatedUtc = order.CreatedUtc,
        IsCancelled = order.IsCancelled
    };
}
```

