using EnterpriseBackend.Application.Abstractions;
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Application.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken ct = default)
    {
        var entity = await _db.Employees
            .AsNoTracking()
            .FirstOrDefaultAsync(x => x.Id == id, ct);

        return entity is null ? null : Map(entity);
    }

    public async Task<IReadOnlyList<EmployeeDto>> GetAllAsync(CancellationToken ct = default)
    {
        var entities = await _db.Employees
            .AsNoTracking()
            .OrderBy(x => x.LastName)
            .ThenBy(x => x.FirstName)
            .ToListAsync(ct);

        return entities.Select(Map).ToList();
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeRequest request, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(request.EmployeeNumber))
            throw new ArgumentException("Employee number is required.");

        if (string.IsNullOrWhiteSpace(request.Email))
            throw new ArgumentException("Email is required.");

        var entity = new Employee
        {
            EmployeeNumber = request.EmployeeNumber.Trim(),
            FirstName = request.FirstName.Trim(),
            LastName = request.LastName.Trim(),
            Email = request.Email.Trim()
        };

        _db.Employees.Add(entity);
        await _db.SaveChangesAsync(ct);

        return Map(entity);
    }

    private static EmployeeDto Map(Employee e) => new()
    {
        Id = e.Id,
        EmployeeNumber = e.EmployeeNumber,
        FullName = $"{e.FirstName} {e.LastName}".Trim(),
        Email = e.Email
    };
}
