# 6) Application service

## `Application/Services/EmployeeService.cs`

```csharp
using Enterprise.Backend.Application.DTOs;
using Enterprise.Backend.Application.Interfaces;
using Enterprise.Backend.Domain.Entities;

namespace Enterprise.Backend.Application.Services;

public class EmployeeService : IEmployeeService
{
    private readonly IEmployeeRepository _repository;

    public EmployeeService(IEmployeeRepository repository)
    {
        _repository = repository;
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id)
    {
        var employee = await _repository.GetByIdAsync(id);
        return employee is null ? null : Map(employee);
    }

    public async Task<IEnumerable<EmployeeDto>> GetAllAsync()
    {
        var employees = await _repository.GetAllAsync();
        return employees.Select(Map);
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeRequest request)
    {
        var employee = new Employee
        {
            Id = Guid.NewGuid(),
            EmployeeNumber = request.EmployeeNumber,
            FirstName = request.FirstName,
            LastName = request.LastName,
            Email = request.Email,
            Department = request.Department,
            CreatedAtUtc = DateTime.UtcNow
        };

        await _repository.AddAsync(employee);
        await _repository.SaveChangesAsync();

        return Map(employee);
    }

    public async Task<bool> DeleteAsync(Guid id)
    {
        var employee = await _repository.GetByIdAsync(id);
        if (employee is null) return false;

        await _repository.DeleteAsync(employee);
        await _repository.SaveChangesAsync();
        return true;
    }

    private static EmployeeDto Map(Employee employee) =>
        new(employee.Id, employee.EmployeeNumber, employee.FirstName, employee.LastName, employee.Email, employee.Department);
}
```

