using Enterprise.Backend.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Infrastructure.Persistence;

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    public DbSet<Employee> Employees => Set<Employee>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        var employee = modelBuilder.Entity<Employee>();

        employee.ToTable("Employees");
        employee.HasKey(e => e.Id);

        employee.Property(e => e.EmployeeNumber)
            .IsRequired()
            .HasMaxLength(50);

        employee.Property(e => e.FirstName)
            .IsRequired()
            .HasMaxLength(100);

        employee.Property(e => e.LastName)
            .IsRequired()
            .HasMaxLength(100);

        employee.Property(e => e.Email)
            .IsRequired()
            .HasMaxLength(200);

        employee.Property(e => e.Department)
            .IsRequired()
            .HasMaxLength(100);

        employee.HasIndex(e => e.EmployeeNumber).IsUnique();
        employee.HasIndex(e => e.Email).IsUnique();
    }
}
