using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using EnterpriseBackend.Application.Services;
using EnterpriseBackend.Domain.Entities;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Policy = "ApiUserOnly")]
public class OrdersController : ControllerBase
{
    private readonly IOrderService _orderService;
    private readonly ILogger<OrdersController> _logger;

    public OrdersController(IOrderService orderService, ILogger<OrdersController> logger)
    {
        _orderService = orderService;
        _logger = logger;
    }

    [HttpGet]
    public async Task<IActionResult> GetAll(CancellationToken cancellationToken)
    {
        var orders = await _orderService.GetAllAsync(cancellationToken);
        return Ok(orders);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id, CancellationToken cancellationToken)
    {
        var order = await _orderService.GetByIdAsync(id, cancellationToken);
        if (order == null)
            return NotFound();

        return Ok(order);
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] Order order, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(order.CustomerName))
            return BadRequest("CustomerName is required.");

        var created = await _orderService.CreateAsync(order, cancellationToken);

        _logger.LogInformation("Order created: {OrderId}", created.Id);

        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }
}
