```csharp
using EnterpriseBackend.Domain.Employees;
using EnterpriseBackend.Infrastructure.Persistence;

namespace EnterpriseBackend.Application.Employees;

public sealed class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _dbContext;

    public EmployeeService(AppDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<EmployeeDto?> GetByIdAsync(int id, CancellationToken cancellationToken)
    {
        var employee = await _dbContext.Employees.FindAsync([id], cancellationToken);
        return employee is null ? null : Map(employee);
    }

    public async Task<IReadOnlyList<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken)
    {
        var employees = await _dbContext.Employees
            .OrderBy(e => e.LastName)
            .ThenBy(e => e.FirstName)
            .Select(e => new EmployeeDto(e.Id, e.FirstName, e.LastName, e.Email, e.Department))
            .ToListAsync(cancellationToken);

        return employees;
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken)
    {
        var employee = new Employee(
            request.FirstName,
            request.LastName,
            request.Email,
            request.Department);

        _dbContext.Employees.Add(employee);
        await _dbContext.SaveChangesAsync(cancellationToken);

        return Map(employee);
    }

    private static EmployeeDto Map(Employee employee) =>
        new(employee.Id, employee.FirstName, employee.LastName, employee.Email, employee.Department);
}
