**`EnterpriseService.Infrastructure/Repositories/WorkItemRepository.cs`**
```csharp
using EnterpriseService.Application.Interfaces;
using EnterpriseService.Domain.Entities;
using EnterpriseService.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseService.Infrastructure.Repositories;

public class WorkItemRepository : IWorkItemService
{
    private readonly EnterpriseDbContext _db;

    public WorkItemRepository(EnterpriseDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<WorkItem>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.WorkItems
            .AsNoTracking()
            .OrderByDescending(x => x.CreatedAtUtc)
            .ToListAsync(cancellationToken);
    }

    public async Task<WorkItem?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _db.WorkItems.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
    }

    public async Task<WorkItem> CreateAsync(WorkItem workItem, CancellationToken cancellationToken = default)
    {
        _db.WorkItems.Add(workItem);
        await _db.SaveChangesAsync(cancellationToken);
        return workItem;
    }

    public async Task<bool> UpdateStatusAsync(Guid id, string status, CancellationToken cancellationToken = default)
    {
        var workItem = await _db.WorkItems.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
        if (workItem is null) return false;

        workItem.Status = status;
        workItem.UpdatedAtUtc = DateTimeOffset.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }
}
```

