using EnterpriseService.Application.Interfaces;
using EnterpriseService.Domain.Entities;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseService.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class WorkItemsController : ControllerBase
{
    private readonly IWorkItemService _workItemService;

    public WorkItemsController(IWorkItemService workItemService)
    {
        _workItemService = workItemService;
    }

    [HttpGet]
    public async Task<IActionResult> GetAll(CancellationToken cancellationToken)
    {
        var items = await _workItemService.GetAllAsync(cancellationToken);
        return Ok(items);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id, CancellationToken cancellationToken)
    {
        var item = await _workItemService.GetByIdAsync(id, cancellationToken);
        return item is null ? NotFound() : Ok(item);
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] WorkItem workItem, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(workItem.Title))
            return BadRequest("Title is required.");

        var created = await _workItemService.CreateAsync(workItem, cancellationToken);
        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }

    [HttpPatch("{id:guid}/status")]
    public async Task<IActionResult> UpdateStatus(Guid id, [FromBody] UpdateStatusRequest request, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(request.Status))
            return BadRequest("Status is required.");

        var success = await _workItemService.UpdateStatusAsync(id, request.Status, cancellationToken);
        return success ? NoContent() : NotFound();
    }
}

public record UpdateStatusRequest(string Status);
