## 5.6 Service layer

```csharp
using Enterprise.Backend.Application.Abstractions;
using Enterprise.Backend.Domain.Entities;

namespace Enterprise.Backend.Application.WorkItems;

public class WorkItemService
{
    private readonly IWorkItemRepository _repository;

    public WorkItemService(IWorkItemRepository repository)
    {
        _repository = repository;
    }

    public async Task<WorkItemResponse> CreateAsync(CreateWorkItemRequest request, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(request.Title))
            throw new ArgumentException("Title is required.");

        var entity = new WorkItem
        {
            Title = request.Title.Trim(),
            Description = request.Description?.Trim()
        };

        await _repository.AddAsync(entity, cancellationToken);
        await _repository.SaveChangesAsync(cancellationToken);

        return ToResponse(entity);
    }

    public async Task<List<WorkItemResponse>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var items = await _repository.GetAllAsync(cancellationToken);
        return items.Select(ToResponse).ToList();
    }

    public async Task<WorkItemResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var item = await _repository.GetByIdAsync(id, cancellationToken);
        return item is null ? null : ToResponse(item);
    }

    private static WorkItemResponse ToResponse(WorkItem item)
        => new(item.Id, item.Title, item.Description, item.Status, item.CreatedAt, item.UpdatedAt);
}
```

