using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Data;

namespace EnterpriseBackend.Application.Services;

public class TicketService : ITicketService
{
    private readonly AppDbContext _db;

    public TicketService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<Ticket>> GetAllAsync()
    {
        return await Task.FromResult(_db.Tickets.AsQueryable().ToList());
    }

    public async Task<Ticket?> GetByIdAsync(Guid id)
    {
        return await Task.FromResult(_db.Tickets.FirstOrDefault(x => x.Id == id));
    }

    public async Task<Ticket> CreateAsync(Ticket ticket)
    {
        ticket.Id = Guid.NewGuid();
        ticket.CreatedAtUtc = DateTime.UtcNow;

        _db.Tickets.Add(ticket);
        await _db.SaveChangesAsync();

        return ticket;
    }
}
