## 3.7 `EnterpriseBackend.Api/Controllers/TicketsController.cs`

```csharp
using EnterpriseBackend.Api.Models;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class TicketsController : ControllerBase
{
    private readonly ITicketService _ticketService;
    private readonly ILogger<TicketsController> _logger;

    public TicketsController(ITicketService ticketService, ILogger<TicketsController> logger)
    {
        _ticketService = ticketService;
        _logger = logger;
    }

    [HttpGet]
    public async Task<IActionResult> GetAll()
    {
        var tickets = await _ticketService.GetAllAsync();
        return Ok(tickets);
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id)
    {
        var ticket = await _ticketService.GetByIdAsync(id);
        if (ticket is null)
            return NotFound();

        return Ok(ticket);
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateTicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Title))
            return BadRequest("Title is required.");

        var ticket = new Ticket
        {
            Title = request.Title,
            Description = request.Description,
            Status = "New"
        };

        var created = await _ticketService.CreateAsync(ticket);

        _logger.LogInformation("Ticket created with ID {TicketId}", created.Id);

        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }
}
```

