## Repository Implementation

### `Infrastructure/Persistence/WorkItemRepository.cs`
```csharp
using Enterprise.Backend.Application.Abstractions;
using Enterprise.Backend.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Infrastructure.Persistence;

public class WorkItemRepository : IWorkItemRepository
{
    private readonly EnterpriseDbContext _dbContext;

    public WorkItemRepository(EnterpriseDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public Task<WorkItem?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
        => _dbContext.WorkItems.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);

    public async Task AddAsync(WorkItem workItem, CancellationToken cancellationToken = default)
        => await _dbContext.WorkItems.AddAsync(workItem, cancellationToken);

    public Task SaveChangesAsync(CancellationToken cancellationToken = default)
        => _dbContext.SaveChangesAsync(cancellationToken);
}
```

