using EnterpriseService.Api.Data;
using EnterpriseService.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseService.Api.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _db;

    public OrderService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<OrderResponse> CreateAsync(CreateOrderRequest request, CancellationToken cancellationToken)
    {
        var order = new Order
        {
            Id = Guid.NewGuid(),
            CustomerName = request.CustomerName.Trim(),
            Status = "New",
            CreatedUtc = DateTime.UtcNow
        };

        _db.Orders.Add(order);
        await _db.SaveChangesAsync(cancellationToken);

        return Map(order);
    }

    public async Task<OrderResponse?> GetByIdAsync(Guid id, CancellationToken cancellationToken)
    {
        var order = await _db.Orders.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
        return order is null ? null : Map(order);
    }

    public async Task<IEnumerable<OrderResponse>> GetAllAsync(CancellationToken cancellationToken)
    {
        var orders = await _db.Orders
            .OrderByDescending(x => x.CreatedUtc)
            .ToListAsync(cancellationToken);

        return orders.Select(Map);
    }

    private static OrderResponse Map(Order order) => new()
    {
        Id = order.Id,
        CustomerName = order.CustomerName,
        Status = order.Status,
        CreatedUtc = order.CreatedUtc
    };
}
