## 3.4 Application service

```csharp
using Enterprise.Backend.Domain.Entities;
using Enterprise.Backend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Application.Tickets;

public class TicketService : ITicketService
{
    private readonly AppDbContext _db;

    public TicketService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<TicketResponse> CreateAsync(CreateTicketRequest request, CancellationToken cancellationToken = default)
    {
        var ticket = new Ticket
        {
            Title = request.Title,
            Description = request.Description
        };

        _db.Tickets.Add(ticket);
        await _db.SaveChangesAsync(cancellationToken);

        return new TicketResponse(ticket.Id, ticket.Title, ticket.Description, ticket.Status, ticket.CreatedAtUtc);
    }

    public async Task<IReadOnlyList<TicketResponse>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Tickets
            .OrderByDescending(t => t.CreatedAtUtc)
            .Select(t => new TicketResponse(t.Id, t.Title, t.Description, t.Status, t.CreatedAtUtc))
            .ToListAsync(cancellationToken);
    }
}
```

