# 3) Code

## `Program.cs`

```csharp
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.Identity.Web;
using Microsoft.OpenApi.Models;
using EnterpriseBackendService.Models;
using EnterpriseBackendService.Services;

var builder = WebApplication.CreateBuilder(args);

// Configuration
builder.Configuration
    .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
    .AddJsonFile($"appsettings.{builder.Environment.EnvironmentName}.json", optional: true, reloadOnChange: true)
    .AddEnvironmentVariables();

// Services
builder.Services.AddSingleton<IItemService, InMemoryItemService>();

builder.Services.AddHealthChecks();

builder.Services.AddControllers();

// Authentication with Microsoft Entra ID (Azure AD)
// If you're not ready for auth yet, you can comment this section out.
// Requires Microsoft.Identity.Web package.
builder.Services
    .AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddMicrosoftIdentityWebApi(builder.Configuration.GetSection("AzureAd"));

builder.Services.AddAuthorization();

// Swagger
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(c =>
{
    c.SwaggerDoc("v1", new OpenApiInfo
    {
        Title = "Enterprise Backend Service",
        Version = "v1"
    });

    // Optional bearer auth in Swagger UI
    c.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
    {
        Description = "Bearer token auth. Example: 'Bearer {token}'",
        Name = "Authorization",
        In = ParameterLocation.Header,
        Type = SecuritySchemeType.Http,
        Scheme = "bearer",
        BearerFormat = "JWT"
    });

    c.AddSecurityRequirement(new OpenApiSecurityRequirement
    {
        {
            new OpenApiSecurityScheme
            {
                Reference = new OpenApiReference
                {
                    Type = ReferenceType.SecurityScheme,
                    Id = "Bearer"
                }
            },
            Array.Empty<string>()
        }
    });
});

var app = builder.Build();

// Middleware
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseHttpsRedirection();

app.UseAuthentication();
app.UseAuthorization();

// Health
app.MapHealthChecks("/health");

// Status
app.MapGet("/api/v1/status", (IHostEnvironment env) =>
{
    return Results.Ok(new
    {
        service = "EnterpriseBackendService",
        status = "running",
        environment = env.EnvironmentName,
        utcNow = DateTime.UtcNow
    });
});

// Items API
app.MapGet("/api/v1/items", (IItemService service) =>
{
    return Results.Ok(service.GetAll());
})
.RequireAuthorization();

app.MapPost("/api/v1/items", (CreateItemRequest request, IItemService service) =>
{
    if (string.IsNullOrWhiteSpace(request.Name))
        return Results.BadRequest("Name is required.");

    var item = service.Create(request.Name, request.Description);
    return Results.Created($"/api/v1/items/{item.Id}", item);
})
.RequireAuthorization();

app.Run();

public record CreateItemRequest(string Name, string? Description);
```

