## 7) `Services/InMemoryItemService.cs`

```csharp
using EnterpriseBackend.Models;
using System.Collections.Concurrent;

namespace EnterpriseBackend.Services;

public class InMemoryItemService : IItemService
{
    private readonly ConcurrentDictionary<int, Item> _items = new();
    private int _nextId = 0;

    public InMemoryItemService()
    {
        Create("Sample Item 1");
        Create("Sample Item 2");
    }

    public IEnumerable<Item> GetAll() => _items.Values.OrderBy(i => i.Id);

    public Item? GetById(int id)
    {
        _items.TryGetValue(id, out var item);
        return item;
    }

    public Item Create(string name)
    {
        var id = Interlocked.Increment(ref _nextId);
        var item = new Item
        {
            Id = id,
            Name = name,
            CreatedUtc = DateTime.UtcNow
        };

        _items[id] = item;
        return item;
    }
}
```

