### `EnterpriseBackend.Infrastructure/Services/CustomerService.cs`

```csharp
using EnterpriseBackend.Application.Contracts;
using EnterpriseBackend.Application.Models;
using EnterpriseBackend.Domain;
using EnterpriseBackend.Infrastructure.Data;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _db;

    public CustomerService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<Customer>> GetAllAsync()
    {
        return await _db.Customers.AsNoTracking().ToListAsync();
    }

    public async Task<Customer> CreateAsync(CustomerDto dto)
    {
        var customer = new Customer
        {
            Name = dto.Name,
            Email = dto.Email,
            CreatedUtc = DateTime.UtcNow
        };

        _db.Customers.Add(customer);
        await _db.SaveChangesAsync();

        return customer;
    }
}
```

