### `Services/EmployeeService.cs`

```csharp
using EnterpriseBackend.Data;
using EnterpriseBackend.DTOs;
using EnterpriseBackend.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public Task<List<Employee>> GetAllAsync()
        => _db.Employees.OrderByDescending(e => e.Id).ToListAsync();

    public Task<Employee?> GetByIdAsync(int id)
        => _db.Employees.FindAsync(id).AsTask();

    public async Task<Employee> CreateAsync(EmployeeDto dto)
    {
        var employee = new Employee
        {
            FirstName = dto.FirstName,
            LastName = dto.LastName,
            Email = dto.Email
        };

        _db.Employees.Add(employee);
        await _db.SaveChangesAsync();
        return employee;
    }
}
```

