using EnterpriseBackendService.Models;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackendService.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SampleController : ControllerBase
{
    private readonly ILogger<SampleController> _logger;

    public SampleController(ILogger<SampleController> logger)
    {
        _logger = logger;
    }

    [HttpGet("status")]
    public IActionResult Status()
    {
        _logger.LogInformation("Status endpoint called.");
        return Ok(new
        {
            service = "EnterpriseBackendService",
            version = "1.0.0",
            status = "Running"
        });
    }

    [HttpPost("echo")]
    public IActionResult Echo([FromBody] EchoRequest request)
    {
        _logger.LogInformation("Echo endpoint called with Message={Message}", request.Message);

        var response = new EchoResponse
        {
            Message = request.Message,
            ReceivedAtUtc = DateTime.UtcNow
        };

        return Ok(response);
    }
}
```

