```rust
use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use hyper_util::server::conn::auto::Builder as AutoBuilder;
use std::convert::Infallible;
use std::net::SocketAddr;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr = SocketAddr::from(([0, 0, 0, 0], 8080));
    let listener = TcpListener::bind(addr).await?;

    println!("Listening on http://{}", addr);

    let shutdown = async {
        signal::ctrl_c().await.ok();
        println!("Shutdown signal received");
    };

    tokio::select! {
        _ = run_server(listener) => {},
        _ = shutdown => {},
    }

    Ok(())
}

async fn run_server(listener: TcpListener) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    loop {
        let (stream, peer_addr) = listener.accept().await?;
        let io = TokioIo::new(stream);

        tokio::spawn(async move {
            let service = service_fn(move |req| handle_request(req, peer_addr));
            if let Err(err) = AutoBuilder::new(hyper_util::rt::TokioExecutor::new())
                .serve_connection(io, service)
                .await
            {
                eprintln!("connection error: {}", err);
            }
        });
    }
}

async fn handle_request(
    req: Request<Incoming>,
    peer_addr: SocketAddr,
) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method().as_str(), req.uri().path()) {
        ("GET", "/") => text_response("Hello from a high-performance Rust web server!"),
        ("GET", "/health") => text_response("OK"),
        ("GET", "/whoami") => text_response(&format!("Your address is {}", peer_addr)),
        _ => not_found(),
    };

    Ok(response)
}

fn text_response(text: &str) -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from(text.to_owned())))
        .unwrap()
}

fn not_found() -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from("Not Found")))
        .unwrap()
}
```

