use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use hyper_util::server::conn::auto::Builder as AutoBuilder;
use serde_json::json;
use std::convert::Infallible;
use std::net::SocketAddr;
use tokio::net::TcpListener;

type RespBody = Full<Bytes>;

#[tokio::main(flavor = "multi_thread", worker_threads = 4)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;

    println!("Listening on http://{}", addr);

    loop {
        let (stream, peer_addr) = listener.accept().await?;
        let io = TokioIo::new(stream);

        tokio::spawn(async move {
            let service = service_fn(handle_request);

            if let Err(err) = AutoBuilder::new(hyper_util::rt::TokioExecutor::new())
                .serve_connection_with_upgrades(io, service)
                .await
            {
                eprintln!("Error serving {}: {}", peer_addr, err);
            }
        });
    }
}

async fn handle_request(req: Request<Incoming>) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => text_response("Hello from a high-performance Rust web server!"),
        (&Method::GET, "/health") => json_response(json!({ "status": "ok" }).to_string()),
        (&Method::GET, "/metrics") => {
            // Placeholder metrics endpoint
            json_response(json!({
                "requests_per_second": 0,
                "active_connections": 0
            }).to_string())
        }
        _ => not_found(),
    };

    Ok(response)
}

fn text_response(body: &str) -> Response<RespBody> {
    Response::new(Full::new(Bytes::from(body.to_string())))
}

fn json_response(body: String) -> Response<RespBody> {
    Response::builder()
        .header("Content-Type", "application/json")
        .body(Full::new(Bytes::from(body)))
        .unwrap()
}

fn not_found() -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .body(Full::new(Bytes::from("404 Not Found")))
        .unwrap()
}
