use bytes::Bytes;
use hyper::{body::Incoming, service::service_fn, Request, Response, StatusCode};
use hyper::server::conn::http1;
use hyper_util::rt::TokioIo;
use http_body_util::Full;
use std::convert::Infallible;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

#[tokio::main]
async fn main() {
    let addr = "0.0.0.0:8080";
    let listener = TcpListener::bind(addr).await.expect("bind failed");
    println!("Listening on http://{}", addr);

    loop {
        tokio::select! {
            biased;

            _ = shutdown_signal() => {
                println!("Shutdown signal received.");
                break;
            }

            accept_res = listener.accept() => {
                let (stream, peer_addr) = match accept_res {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("accept error: {}", e);
                        continue;
                    }
                };

                tokio::spawn(async move {
                    let io = TokioIo::new(stream);

                    let svc = service_fn(handle_request);

                    if let Err(err) = http1::Builder::new()
                        .serve_connection(io, svc)
                        .await
                    {
                        eprintln!("error serving {}: {}", peer_addr, err);
                    }
                });
            }
        }
    }

    println!("Server stopped.");
}

async fn handle_request(req: Request<Incoming>) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&hyper::Method::GET, "/") => text_response("Hello from a high-performance Rust server!"),
        (&hyper::Method::GET, "/health") => text_response("OK"),
        (&hyper::Method::GET, "/work") => {
            // Example of async work without blocking the reactor
            tokio::task::yield_now().await;
            text_response("Work complete")
        }
        _ => not_found(),
    };

    Ok(response)
}

fn text_response(body: &'static str) -> Response<RespBody> {
    Response::builder()
        .header("Content-Type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from_static(body.as_bytes())))
        .unwrap()
}

fn not_found() -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .header("Content-Type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from_static(b"404 Not Found")))
        .unwrap()
}

async fn shutdown_signal() {
    let _ = signal::ctrl_c().await;
}
