## `main.go`

```go
package main

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"log"
	"net"
	"os"
	"os/signal"
	"strings"
	"sync"
	"syscall"
	"time"
)

const (
	addr            = ":8080"
	maxHeaderBytes   = 16 * 1024
	readTimeout      = 5 * time.Second
	writeTimeout     = 10 * time.Second
	idleTimeout      = 30 * time.Second
	maxRequestBody   = 1 << 20 // 1MB
	maxConcurrentReq = 100000
)

type Server struct {
	addr     string
	ln       net.Listener
	routes   map[string]HandlerFunc
	mu       sync.RWMutex
	shutdown chan struct{}
	wg       sync.WaitGroup
}

type Request struct {
	Method string
	Path   string
	Header map[string]string
	Body   []byte
}

type Response struct {
	Status int
	Header map[string]string
	Body   []byte
}

type HandlerFunc func(*Request) *Response

func NewServer(addr string) *Server {
	return &Server{
		addr:     addr,
		routes:   make(map[string]HandlerFunc),
		shutdown: make(chan struct{}),
	}
}

func (s *Server) Handle(path string, handler HandlerFunc) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.routes[path] = handler
}

func (s *Server) getHandler(path string) HandlerFunc {
	s.mu.RLock()
	defer s.mu.RUnlock()
	if h, ok := s.routes[path]; ok {
		return h
	}
	if h, ok := s.routes["*"]; ok {
		return h
	}
	return nil
}

func (s *Server) Start() error {
	ln, err := net.Listen("tcp", s.addr)
	if err != nil {
		return err
	}
	s.ln = ln

	log.Printf("listening on %s", s.addr)

	for {
		conn, err := ln.Accept()
		if err != nil {
			select {
			case <-s.shutdown:
				return nil
			default:
			}
			if ne, ok := err.(net.Error); ok && ne.Temporary() {
				log.Printf("temporary accept error: %v", err)
				continue
			}
			return err
		}

		s.wg.Add(1)
		go func(c net.Conn) {
			defer s.wg.Done()
			s.handleConn(c)
		}(conn)
	}
}

func (s *Server) Shutdown(ctx context.Context) error {
	close(s.shutdown)
	if s.ln != nil {
		_ = s.ln.Close()
	}

	done := make(chan struct{})
	go func() {
		s.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (s *Server) handleConn(conn net.Conn) {
	defer conn.Close()

	_ = conn.SetReadDeadline(time.Now().Add(idleTimeout))
	_ = conn.SetWriteDeadline(time.Now().Add(writeTimeout))

	reader := bufio.NewReaderSize(conn, 32*1024)
	writer := bufio.NewWriterSize(conn, 32*1024)

	for {
		req, keepAlive, err := readRequest(reader, conn)
		if err != nil {
			if err != io.EOF {
				// log.Printf("request read error: %v", err)
			}
			return
		}

		handler := s.getHandler(req.Path)
		resp := &Response{
			Status: 200,
			Header: map[string]string{
				"Content-Type": "text/plain; charset=utf-8",
			},
			Body: []byte("OK"),
		}
		if handler != nil {
			resp = handler(req)
			if resp == nil {
				resp = &Response{Status: 204, Header: map[string]string{}, Body: nil}
			}
		} else {
			resp = &Response{
				Status: 404,
				Header: map[string]string{
					"Content-Type": "text/plain; charset=utf-8",
				},
				Body: []byte("not found"),
			}
		}

		if err := writeResponse(writer, resp); err != nil {
			return
		}
		if err := writer.Flush(); err != nil {
			return
		}

		if !keepAlive {
			return
		}
		_ = conn.SetReadDeadline(time.Now().Add(idleTimeout))
	}
}

func readRequest(r *bufio.Reader, conn net.Conn) (*Request, bool, error) {
	line, err := readLine(r)
	if err != nil {
		return nil, false, err
	}
	if line == "" {
		return nil, false, io.EOF
	}

	parts := strings.SplitN(line, " ", 3)
	if len(parts) != 3 {
		return nil, false, fmt.Errorf("malformed request line")
	}

	method, path := parts[0], parts[1]

	headers := make(map[string]string)
	for {
		hline, err := readLine(r)
		if err != nil {
			return nil, false, err
		}
		if hline == "" {
			break
		}
		idx := strings.IndexByte(hline, ':')
		if idx <= 0 {
			continue
		}
		k := strings.TrimSpace(hline[:idx])
		v := strings.TrimSpace(hline[idx+1:])
		headers[strings.ToLower(k)] = v
	}

	body := make([]byte, 0)
	if cl := headers["content-length"]; cl != "" {
		var n int
		_, _ = fmt.Sscanf(cl, "%d", &n)
		if n < 0 || n > maxRequestBody {
			return nil, false, fmt.Errorf("invalid content length")
		}
		body = make([]byte, n)
		if _, err := io.ReadFull(r, body); err != nil {
			return nil, false, err
		}
	}

	keepAlive := true
	if v, ok := headers["connection"]; ok && strings.EqualFold(v, "close") {
		keepAlive = false
	}

	return &Request{
		Method: method,
		Path:   path,
		Header: headers,
		Body:   body,
	}, keepAlive, nil
}

func readLine(r *bufio.Reader) (string, error) {
	line, err := r.ReadString('\n')
	if err != nil {
		return "", err
	}
	line = strings.TrimRight(line, "\r\n")
	return line, nil
}

func writeResponse(w *bufio.Writer, resp *Response) error {
	statusText := statusText(resp.Status)
	if statusText == "" {
		statusText = "OK"
	}
	body := resp.Body
	if body == nil {
		body = []byte{}
	}

	if resp.Header == nil {
		resp.Header = map[string]string{}
	}

	resp.Header["Content-Length"] = fmt.Sprintf("%d", len(body))
	if _, ok := resp.Header["Connection"]; !ok {
		resp.Header["Connection"] = "keep-alive"
	}

	if _, err := fmt.Fprintf(w, "HTTP/1.1 %d %s\r\n", resp.Status, statusText); err != nil {
		return err
	}
	for k, v := range resp.Header {
		if _, err := fmt.Fprintf(w, "%s: %s\r\n", k, v); err != nil {
			return err
		}
	}
	if _, err := fmt.Fprint(w, "\r\n"); err != nil {
		return err
	}
	if len(body) > 0 {
		if _, err := w.Write(body); err != nil {
			return err
		}
	}
	return nil
}

func statusText(code int) string {
	switch code {
	case 200:
		return "OK"
	case 201:
		return "Created"
	case 204:
		return "No Content"
	case 400:
		return "Bad Request"
	case 404:
		return "Not Found"
	case 405:
		return "Method Not Allowed"
	case 500:
		return "Internal Server Error"
	default:
		return "OK"
	}
}

func main() {
	srv := NewServer(addr)

