## Implementation

```go
package main

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"
)

type Server struct {
	addr         string
	ln           net.Listener
	httpServer   *http.Server
	maxConns     int
	connSem      chan struct{}
	shutdownOnce sync.Once
}

func NewServer(addr string, maxConns int) *Server {
	return &Server{
		addr:     addr,
		maxConns: maxConns,
		connSem:  make(chan struct{}, maxConns),
	}
}

func (s *Server) Start() error {
	ln, err := net.Listen("tcp", s.addr)
	if err != nil {
		return err
	}
	s.ln = ln

	mux := http.NewServeMux()
	mux.HandleFunc("/", s.handleRoot)
	mux.HandleFunc("/health", s.handleHealth)
	mux.HandleFunc("/echo", s.handleEcho)

	s.httpServer = &http.Server{
		Handler:           mux,
		ReadTimeout:       5 * time.Second,
		ReadHeaderTimeout: 2 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       30 * time.Second,
		MaxHeaderBytes:    1 << 20, // 1 MiB
		ConnState:         s.connState,
	}

	log.Printf("server listening on %s", s.addr)
	return s.httpServer.Serve(s.limitListener(ln))
}

func (s *Server) limitListener(ln net.Listener) net.Listener {
	return &limitedListener{
		Listener: ln,
		sem:      s.connSem,
	}
}

func (s *Server) connState(c net.Conn, state http.ConnState) {
	// Basic logging / hook point for metrics.
	_ = c
	_ = state
}

func (s *Server) Shutdown(ctx context.Context) error {
	var err error
	s.shutdownOnce.Do(func() {
		if s.httpServer != nil {
			err = s.httpServer.Shutdown(ctx)
		}
	})
	return err
}

func (s *Server) handleRoot(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	_, _ = io.WriteString(w, "OK\n")
}

func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	_, _ = io.WriteString(w, `{"status":"healthy"}`)
}

func (s *Server) handleEcho(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Limit request body to prevent abuse.
	const maxBodySize = 1 << 20 // 1 MiB
	body, err := io.ReadAll(io.LimitReader(r.Body, maxBodySize))
	if err != nil {
		http.Error(w, "failed to read body", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	_, _ = w.Write(body)
}

type limitedListener struct {
	net.Listener
	sem chan struct{}
}

func (l *limitedListener) Accept() (net.Conn, error) {
	c, err := l.Listener.Accept()
	if err != nil {
		return nil, err
	}

	// Acquire a slot; if full, briefly reject by closing.
	select {
	case l.sem <- struct{}{}:
		return &limitedConn{Conn: c, sem: l.sem}, nil
	default:
		_ = c.Close()
		return nil, fmt.Errorf("too many connections")
	}
}

type limitedConn struct {
	net.Conn
	sem chan struct{}
}

func (c *limitedConn) Close() error {
	err := c.Conn.Close()
	select {
	case <-c.sem:
	default:
	}
	return err
}

func main() {
	addr := ":8080"
	maxConns := 10000

	if v := os.Getenv("ADDR"); v != "" {
		addr = v
	}
	if v := os.Getenv("MAX_CONNS"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			maxConns = n
		}
	}

	server := NewServer(addr, maxConns)

	// Graceful shutdown on SIGINT/SIGTERM.
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	go func() {
		<-ctx.Done()
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		if err := server.Shutdown(shutdownCtx); err != nil {
			log.Printf("shutdown error: %v", err)
		}
	}()

	if err := server.Start(); err != nil && !strings.Contains(err.Error(), "Server closed") {
		log.Fatalf("server failed: %v", err)
	}
}
