use std::{convert::Infallible, net::SocketAddr, sync::Arc};

use bytes::Bytes;
use http_body_util::Full;
use hyper::{
    body::Incoming,
    server::conn::http1,
    service::service_fn,
    Request, Response, StatusCode,
};
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;
use tracing::{error, info};
use tracing_subscriber::EnvFilter;

type RespBody = Full<Bytes>;

#[tokio::main]
async fn main() {
    // Structured logging
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse().unwrap()))
        .init();

    let addr: SocketAddr = "0.0.0.0:8080".parse().unwrap();
    let listener = TcpListener::bind(addr).await.unwrap();

    info!("Listening on http://{}", addr);

    // Shared app state placeholder (DB pools, config, caches, etc.)
    let state = Arc::new(AppState::new());

    loop {
        let (stream, peer_addr) = match listener.accept().await {
            Ok(v) => v,
            Err(e) => {
                error!("accept error: {}", e);
                continue;
            }
        };

        let state = Arc::clone(&state);

        tokio::spawn(async move {
            let io = TokioIo::new(stream);

            let service = service_fn(move |req| {
                let state = Arc::clone(&state);
                async move { handle_request(req, state).await }
            });

            if let Err(err) = http1::Builder::new()
                .keep_alive(true)
                .serve_connection(io, service)
                .await
            {
                error!("error serving {}: {}", peer_addr, err);
            }
        });
    }
}

struct AppState {
    // Put your shared resources here:
    // db_pool: sqlx::PgPool,
    // cache: redis::Client,
}

impl AppState {
    fn new() -> Self {
        Self {}
    }
}

async fn handle_request(
    req: Request<Incoming>,
    _state: Arc<AppState>,
) -> Result<Response<RespBody>, Infallible> {
    let response = match req.uri().path() {
        "/" => Response::new(Full::new(Bytes::from_static(b"Hello, world!"))),

        "/health" => Response::new(Full::new(Bytes::from_static(b"ok"))),

        "/echo" => {
            // Basic echo example
            Response::new(Full::new(Bytes::from(format!(
                "method={} path={}",
                req.method(),
                req.uri().path()
            ))))
        }

        _ => {
            let mut not_found = Response::new(Full::new(Bytes::from_static(b"Not Found")));
            *not_found.status_mut() = StatusCode::NOT_FOUND;
            not_found
        }
    };

    Ok(response)
}
