package main

import (
	"context"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"sync"
	"syscall"
	"time"
)

type Server struct {
	httpServer *http.Server
	workerPool  *WorkerPool
}

type WorkerPool struct {
	jobs chan func()
	wg   sync.WaitGroup
}

func NewWorkerPool(size int) *WorkerPool {
	wp := &WorkerPool{
		jobs: make(chan func(), size*4),
	}

	for i := 0; i < size; i++ {
		wp.wg.Add(1)
		go func(id int) {
			defer wp.wg.Done()
			for job := range wp.jobs {
				job()
			}
		}(i)
	}

	return wp
}

func (wp *WorkerPool) Submit(job func()) bool {
	select {
	case wp.jobs <- job:
		return true
	default:
		return false
	}
}

func (wp *WorkerPool) Stop() {
	close(wp.jobs)
	wp.wg.Wait()
}

func NewServer(addr string) *Server {
	mux := http.NewServeMux()

	s := &Server{}

	// Health check
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"ok"}`))
	})

	// Example high-concurrency endpoint
	mux.HandleFunc("/work", func(w http.ResponseWriter, r *http.Request) {
		// Simulate lightweight async processing via worker pool
		done := make(chan string, 1)

		submitted := s.workerPool.Submit(func() {
			// Placeholder for actual business logic
			time.Sleep(50 * time.Millisecond)
			done <- "processed"
		})

		if !submitted {
			http.Error(w, "server busy", http.StatusServiceUnavailable)
			return
		}

		select {
		case result := <-done:
			w.Header().Set("Content-Type", "application/json")
			_, _ = fmt.Fprintf(w, `{"result":"%s"}`, result)
		case <-r.Context().Done():
			http.Error(w, "request cancelled", http.StatusRequestTimeout)
		case <-time.After(2 * time.Second):
			http.Error(w, "timeout", http.StatusGatewayTimeout)
		}
	})

	workerCount := runtime.NumCPU() * 4
	s.workerPool = NewWorkerPool(workerCount)

	s.httpServer = &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadTimeout:       5 * time.Second,
		ReadHeaderTimeout: 2 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20, // 1 MB
		BaseContext: func(_ net.Listener) context.Context {
			return context.Background()
		},
	}

	return s
}

func (s *Server) Start() error {
	go func() {
		log.Printf("server starting on %s", s.httpServer.Addr)
		if err := s.httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen error: %v", err)
		}
	}()
	return nil
}

func (s *Server) Shutdown(ctx context.Context) error {
	log.Println("shutting down server...")
	if err := s.httpServer.Shutdown(ctx); err != nil {
		return err
	}
	s.workerPool.Stop()
	return nil
}

func main() {
	server := NewServer(":8080")

	if err := server.Start(); err != nil {
		log.Fatalf("failed to start server: %v", err)
	}

	// Graceful shutdown
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Fatalf("shutdown failed: %v", err)
	}

	log.Println("server exited cleanly")
}
