package main

import (
	"context"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"
)

const (
	defaultAddr             = ":8080"
	defaultReadTimeout      = 5 * time.Second
	defaultWriteTimeout     = 10 * time.Second
	defaultIdleTimeout      = 60 * time.Second
	defaultShutdownTimeout  = 15 * time.Second
	defaultMaxHeaderBytes   = 1 << 20 // 1 MB
	defaultReadHeaderTimeout = 2 * time.Second
)

func main() {
	addr := getEnv("SERVER_ADDR", defaultAddr)

	server := &http.Server{
		Addr:              addr,
		Handler:           newRouter(),
		ReadTimeout:       defaultReadTimeout,
		ReadHeaderTimeout: defaultReadHeaderTimeout,
		WriteTimeout:      defaultWriteTimeout,
		IdleTimeout:       defaultIdleTimeout,
		MaxHeaderBytes:    defaultMaxHeaderBytes,
		ConnState: func(conn net.Conn, state http.ConnState) {
			// Lightweight hook for connection lifecycle tracking.
			// Extend this for metrics/observability if needed.
		},
	}

	// Run server in a goroutine so we can catch shutdown signals.
	errCh := make(chan error, 1)
	go func() {
		log.Printf("starting server on %s", addr)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			errCh <- err
		}
		close(errCh)
	}()

	// Wait for signal or server error.
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	select {
	case sig := <-sigCh:
		log.Printf("received signal: %s, shutting down...", sig)
	case err, ok := <-errCh:
		if ok && err != nil {
			log.Fatalf("server error: %v", err)
		}
	}

	// Graceful shutdown.
	ctx, cancel := context.WithTimeout(context.Background(), defaultShutdownTimeout)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Printf("graceful shutdown failed: %v", err)
		if cerr := server.Close(); cerr != nil {
			log.Printf("forced close failed: %v", cerr)
		}
	} else {
		log.Println("server stopped gracefully")
	}
}

func newRouter() http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/ready", readyHandler)
	mux.HandleFunc("/", indexHandler)

	// Middleware chain: recovery, request ID, logging, concurrency limit.
	return requestIDMiddleware(
		recoveryMiddleware(
			loggingMiddleware(
				concurrencyLimitMiddleware(10000)(mux), // adjust based on CPU/memory
			),
		),
	)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

func readyHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ready"))
}

func indexHandler(w http.ResponseWriter, r *http.Request) {
	// Example lightweight endpoint
	w.Header().Set("Content-Type", "application/json")
	_, _ = fmt.Fprint(w, `{"message":"hello","status":"ok"}`)
}

// --- Middleware ---

func recoveryMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				log.Printf("panic recovered: %v", rec)
				http.Error(w, "internal server error", http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
	})
}

// requestIDMiddleware is a placeholder for tracing/correlation.
// In production, inject from upstream headers or generate UUIDs.
func requestIDMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		next.ServeHTTP(w, r)
	})
}

// concurrencyLimitMiddleware limits active requests to protect the server
// from overload under extreme traffic.
func concurrencyLimitMiddleware(maxConcurrent int) func(http.Handler) http.Handler {
	sem := make(chan struct{}, maxConcurrent)

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			select {
			case sem <- struct{}{}:
				defer func() { <-sem }()
				next.ServeHTTP(w, r)
			default:
				http.Error(w, "server is busy", http.StatusServiceUnavailable)
			}
		})
	}
}

// --- Helpers ---

func getEnv(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

func getEnvInt(key string, fallback int) int {
	if v := os.Getenv(key); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			return n
		}
	}
	return fallback
}
