"""
Simple evaluation harness for running prompts against multiple language models
and scoring the responses.

Features:
- Model-agnostic interface
- Concurrent evaluation
- Pluggable scoring functions
- JSONL result logging
- Basic aggregation of metrics

You can adapt the `ModelClient` classes to your providers (OpenAI, Anthropic,
local REST, Hugging Face, etc.).
"""

from __future__ import annotations

import abc
import concurrent.futures as cf
import dataclasses
import json
import math
import os
import time
from typing import Any, Callable, Dict, Iterable, List, Optional, Protocol, Tuple


# ----------------------------
# Data structures
# ----------------------------

@dataclasses.dataclass(frozen=True)
class PromptCase:
    """A single evaluation prompt and its optional expected output."""
    id: str
    prompt: str
    reference: Optional[str] = None
    metadata: Dict[str, Any] = dataclasses.field(default_factory=dict)


@dataclasses.dataclass
class ModelResponse:
    """A response from a model."""
    model_name: str
    prompt_id: str
    text: str
    latency_s: float
    raw: Any = None
    error: Optional[str] = None


@dataclasses.dataclass
class EvaluationResult:
    """A scored evaluation result."""
    model_name: str
    prompt_id: str
    response_text: str
    scores: Dict[str, float]
    latency_s: float
    error: Optional[str] = None
    metadata: Dict[str, Any] = dataclasses.field(default_factory=dict)


# ----------------------------
# Model interface
# ----------------------------

class ModelClient(abc.ABC):
    """Abstract interface for a language model."""

    @property
    @abc.abstractmethod
    def name(self) -> str:
        raise NotImplementedError

    @abc.abstractmethod
    def generate(self, prompt: str, **kwargs: Any) -> str:
        """Generate a response for a given prompt."""
        raise NotImplementedError


class EchoModel(ModelClient):
    """Example local model client for testing."""
    def __init__(self, name: str):
        self._name = name

    @property
    def name(self) -> str:
        return self._name

    def generate(self, prompt: str, **kwargs: Any) -> str:
        return f"Echo: {prompt[:80]}"


# ----------------------------
# Scoring interface
# ----------------------------

ScoreFn = Callable[[str, Optional[str], str, Dict[str, Any]], float]
# score_fn(prompt, reference, prediction, metadata) -> float


def exact_match_score(
    prompt: str,
    reference: Optional[str],
    prediction: str,
    metadata: Dict[str, Any],
) -> float:
    if reference is None:
        return float("nan")
    return 1.0 if prediction.strip() == reference.strip() else 0.0


def substring_score(
    prompt: str,
    reference: Optional[str],
    prediction: str,
    metadata: Dict[str, Any],
) -> float:
    """Returns 1.0 if reference appears in prediction."""
    if reference is None:
        return float("nan")
    return 1.0 if reference.strip() in prediction else 0.0


def word_overlap_score(
    prompt: str,
    reference: Optional[str],
    prediction: str,
    metadata: Dict[str, Any],
) -> float:
    """Simple token overlap F1-like score."""
    if reference is None:
        return float("nan")

    ref_tokens = reference.lower().split()
    pred_tokens = prediction.lower().split()
    if not ref_tokens or not pred_tokens:
        return 0.0

    ref_set = set(ref_tokens)
    pred_set = set(pred_tokens)
    overlap = len(ref_set & pred_set)

    precision = overlap / len(pred_set)
    recall = overlap / len(ref_set)
    if precision + recall == 0:
        return 0.0
    return 2 * precision * recall / (precision + recall)


# ----------------------------
# Harness
# ----------------------------

class EvaluationHarness:
    def __init__(
        self,
        models: Iterable[ModelClient],
        score_fns: Dict[str, ScoreFn],
        max_workers: int = 8,
        timeout_s: Optional[float] = None,
    ):
        self.models = list(models)
        self.score_fns = score_fns
        self.max_workers = max_workers
        self.timeout_s = timeout_s

    def run_prompt_case(self, model: ModelClient, case: PromptCase) -> EvaluationResult:
        start = time.perf_counter()
        try:
            text = model.generate(case.prompt)
            latency = time.perf_counter() - start
            scores = {
                name: fn(case.prompt, case.reference, text, case.metadata)
                for name, fn in self.score_fns.items()
            }
            return EvaluationResult(
                model_name=model.name,
                prompt_id=case.id,
                response_text=text,
                scores=scores,
                latency_s=latency,
                metadata=case.metadata,
            )
        except Exception as e:
            latency = time.perf_counter() - start
            return EvaluationResult(
                model_name=model.name,
                prompt_id=case.id,
                response_text="",
                scores={name: float("nan") for name in self.score_fns},
                latency_s=latency,
                error=str(e),
                metadata=case.metadata,
            )

    def run(self, cases: Iterable[PromptCase]) -> List[EvaluationResult]:
        cases = list(cases)
        tasks: List[Tuple[ModelClient, PromptCase]] = [
            (model, case) for model in self.models for case in cases
        ]

        results: List[EvaluationResult] = []
        with cf.ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            future_map = {
                executor.submit(self.run_prompt_case, model, case): (model.name, case.id)
                for model, case in tasks
            }
            for fut in cf.as_completed(future_map, timeout=self.timeout_s):
                results.append(fut.result())

        return results

    @staticmethod
    def save_jsonl(results: Iterable[EvaluationResult], path: str) -> None:
        with open(path, "w", encoding="utf-8") as f:
            for r in results:
                f.write(json.dumps(dataclasses.asdict(r), ensure_ascii=False) + "\n")

    @staticmethod
    def aggregate(results: Iterable[EvaluationResult]) -> Dict[str, Any]:
        results = list(results)
        by_model: Dict[str, Dict[str, List[float]]] = {}
        latency: Dict[str, List[float]] = {}
        errors: Dict[str, int] = {}

        for r in results:
            by_model.setdefault(r.model_name, {})
            latency.setdefault(r.model_name, [])
            errors.setdefault(r.model_name, 0)

            latency[r.model_name].append(r.latency_s)
            if r.error:
                errors[r.model_name] += 1

            for k, v in r.scores.items():
                if not math.isnan(v):
                    by_model[r.model_name].setdefault(k, []).append(v)

        summary: Dict[str, Any] = {}
        for model_name, score_map in by_model.items():
            summary[model_name] = {
                "scores": {
                    metric: (sum(vals) / len(vals) if vals else float("nan"))
                    for metric, vals in score_map.items()
                },
                "avg_latency_s": (
                    sum(latency[model_name]) / len(latency[model_name])
                    if latency[model_name]
                    else float("nan")
                ),
                "error_count": errors[model_name],
                "num_results": len(latency[model_name]),
            }
        return summary


# ----------------------------
# Example usage
# ----------------------------

if __name__ == "__main__":
    prompts = [
        PromptCase(id="q1", prompt="Say hello in one word.", reference="hello"),
        PromptCase(id="q2", prompt="Repeat: apples", reference="apples"),
        PromptCase(id="q3", prompt="What is 2+2?", reference="4"),
    ]

    models = [
        EchoModel("echo-a"),
        EchoModel("echo-b"),
    ]

    harness = EvaluationHarness(
        models=models,
        score_fns={
            "exact_match": exact_match_score,
            "substring": substring_score,
            "word_overlap": word_overlap_score,
        },
    )

    results = harness.run(prompts)
    harness.save_jsonl(results, "eval_results.jsonl")

    summary = harness.aggregate(results)
    print(json.dumps(summary, indent=2))
