#!/usr/bin/env python3
"""
Simple evaluation harness for running prompts against multiple language models
and scoring the responses.

Features:
- Runs a set of prompts against multiple model backends
- Supports provider adapters (OpenAI-style example included)
- Scores responses with heuristic metrics and optional custom scorers
- Produces JSON and human-readable summaries

Install deps:
  pip install requests pydantic

Environment:
  export OPENAI_API_KEY=...

Usage:
  python eval_harness.py --prompts prompts.json --models models.json --out results.json
"""

from __future__ import annotations

import argparse
import dataclasses
import json
import os
import re
import statistics
import time
from abc import ABC, abstractmethod
from typing import Any, Callable, Dict, List, Optional

import requests


# -----------------------------
# Data structures
# -----------------------------

@dataclasses.dataclass
class PromptItem:
    id: str
    prompt: str
    reference: Optional[str] = None
    metadata: Dict[str, Any] = dataclasses.field(default_factory=dict)


@dataclasses.dataclass
class ModelConfig:
    name: str
    provider: str
    model: str
    api_key_env: Optional[str] = None
    base_url: Optional[str] = None
    temperature: float = 0.0
    extra: Dict[str, Any] = dataclasses.field(default_factory=dict)


@dataclasses.dataclass
class EvalResult:
    prompt_id: str
    model_name: str
    prompt: str
    response: str
    scores: Dict[str, float]
    metadata: Dict[str, Any] = dataclasses.field(default_factory=dict)


# -----------------------------
# Model adapters
# -----------------------------

class ModelAdapter(ABC):
    def __init__(self, config: ModelConfig):
        self.config = config

    @abstractmethod
    def generate(self, prompt: str) -> str:
        raise NotImplementedError


class OpenAIStyleChatAdapter(ModelAdapter):
    """
    Minimal OpenAI-compatible chat completions adapter.
    Works with APIs exposing /v1/chat/completions.
    """

    def generate(self, prompt: str) -> str:
        api_key = os.getenv(self.config.api_key_env or "OPENAI_API_KEY")
        if not api_key:
            raise RuntimeError("Missing API key env var for OpenAI-style adapter")

        base_url = self.config.base_url or "https://api.openai.com"
        url = f"{base_url.rstrip('/')}/v1/chat/completions"

        payload = {
            "model": self.config.model,
            "messages": [{"role": "user", "content": prompt}],
            "temperature": self.config.temperature,
        }
        payload.update(self.config.extra)

        resp = requests.post(
            url,
            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
            json=payload,
            timeout=120,
        )
        resp.raise_for_status()
        data = resp.json()
        return data["choices"][0]["message"]["content"]


class TransformAdapter(ModelAdapter):
    """
    Example local mock adapter: deterministic transformation for demo/testing.
    """

    def generate(self, prompt: str) -> str:
        return f"[MOCK:{self.config.name}] {prompt[::-1]}"


def build_adapter(config: ModelConfig) -> ModelAdapter:
    provider = config.provider.lower()
    if provider in {"openai", "openai_chat", "openai-compatible"}:
        return OpenAIStyleChatAdapter(config)
    if provider in {"mock", "transform"}:
        return TransformAdapter(config)
    raise ValueError(f"Unknown provider: {config.provider}")


# -----------------------------
# Scorers
# -----------------------------

def score_exact_match(response: str, reference: Optional[str]) -> float:
    if reference is None:
        return 0.0
    return 1.0 if response.strip() == reference.strip() else 0.0


def score_token_f1(response: str, reference: Optional[str]) -> float:
    if reference is None:
        return 0.0

    def tok(s: str) -> List[str]:
        return re.findall(r"\w+", s.lower())

    tr = tok(reference)
    pr = tok(response)
    if not tr or not pr:
        return 0.0

    from collections import Counter

    rc = Counter(tr)
    pc = Counter(pr)
    overlap = sum((rc & pc).values())
    precision = overlap / len(pr)
    recall = overlap / len(tr)
    return 0.0 if precision + recall == 0 else 2 * precision * recall / (precision + recall)


def score_length(response: str, reference: Optional[str]) -> float:
    return float(len(response))


def score_keyword_coverage(response: str, reference: Optional[str], keywords: List[str]) -> float:
    if not keywords:
        return 0.0
    text = response.lower()
    hits = sum(1 for k in keywords if k.lower() in text)
    return hits / len(keywords)


def default_scorer(response: str, prompt: PromptItem) -> Dict[str, float]:
    scores = {
        "exact_match": score_exact_match(response, prompt.reference),
        "token_f1": score_token_f1(response, prompt.reference),
        "length": score_length(response, prompt.reference),
    }
    if "keywords" in prompt.metadata and isinstance(prompt.metadata["keywords"], list):
        scores["keyword_coverage"] = score_keyword_coverage(
            response, prompt.reference, prompt.metadata["keywords"]
        )
    return scores


# -----------------------------
# Harness
# -----------------------------

class EvaluationHarness:
    def __init__(
        self,
        prompts: List[PromptItem],
        models: List[ModelConfig],
        scorer: Callable[[str, PromptItem], Dict[str, float]] = default_scorer,
        sleep_s: float = 0.0,
    ):
        self.prompts = prompts
        self.models = models
        self.scorer = scorer
        self.sleep_s = sleep_s
        self.adapters = {m.name: build_adapter(m) for m in models}

    def run(self) -> List[EvalResult]:
        results: List[EvalResult] = []

        for model in self.models:
            adapter = self.adapters[model.name]
            for prompt in self.prompts:
                start = time.time()
                try:
                    response = adapter.generate(prompt.prompt)
                    error = None
                except Exception as e:
                    response = ""
                    error = repr(e)

                elapsed = time.time() - start
                scores = self.scorer(response, prompt)
                scores["latency_s"] = elapsed
                if error:
                    scores["error"] = 1.0

                results.append(
                    EvalResult(
                        prompt_id=prompt.id,
                        model_name=model.name,
                        prompt=prompt.prompt,
                        response=response,
                        scores=scores,
                        metadata={"error": error} if error else {},
                    )
                )

                if self.sleep_s > 0:
                    time.sleep(self.sleep_s)

        return results

    @staticmethod
    def summarize(results: List[EvalResult]) -> Dict[str, Any]:
        by_model: Dict[str, List[EvalResult]] = {}
        for r in results:
            by_model.setdefault(r.model_name, []).append(r)

        summary: Dict[str, Any] = {"models": {}}
        for model_name, rs in by_model.items():
            metrics: Dict[str, List[float]] = {}
            for r in rs:
                for k, v in r.scores.items():
                    if isinstance(v, (int, float)):
                        metrics.setdefault(k, []).append(float(v))
            summary["models"][model_name] = {
                metric: {
                    "mean": statistics.mean(vals),
                    "min": min(vals),
                    "max": max(vals),
                }
                for metric, vals in metrics.items()
                if vals
            }
        return summary


# -----------------------------
# I/O helpers
# -----------------------------

def load_prompts(path: str) -> List[PromptItem]:
    with open(path, "r", encoding="utf-8") as f:
        raw = json.load(f)

    prompts = []
    for item in raw:
        prompts.append(
            PromptItem(
                id=item["id"],
                prompt=item["prompt"],
                reference=item.get("reference"),
                metadata=item.get("metadata", {}),
            )
        )
    return prompts


def load_models(path: str) -> List[ModelConfig]:
    with open(path, "r", encoding="utf-8") as f:
        raw = json.load(f)

    models = []
    for item in raw:
        models.append(
            ModelConfig(
                name=item["name"],
                provider=item["provider"],
                model=item["model"],
                api_key_env=item.get("api_key_env"),
                base_url=item.get("base_url"),
                temperature=float(item.get("temperature", 0.0)),
                extra=item.get("extra", {}),
            )
        )
    return models


def save_results(path: str, results: List[EvalResult], summary: Dict[str, Any]) -> None:
    payload = {
        "summary": summary,
        "results": [
            dataclasses.asdict(r) for r in results
        ],
    }
    with open(path, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2, ensure_ascii=False)


def print_summary(summary: Dict[str, Any]) -> None:
    print("\n=== Summary ===")
    for model_name, metrics in summary.get("models", {}).items():
        print(f"\nModel: {model_name}")
        for metric_name, stats in metrics.items():
            print(
                f"  {metric_name}: mean={stats['mean']:.4f} "
                f"min={stats['min']:.4f} max={stats['max']:.4f}"
            )


# -----------------------------
# CLI
# -----------------------------

def main():
    parser = argparse.ArgumentParser(description="Prompt evaluation harness")
    parser.add_argument("--prompts", required=True, help="Path to prompts JSON")
    parser.add_argument("--models", required=True, help="Path to models JSON")
    parser.add_argument("--out", default="results.json", help="Output JSON path")
    parser.add_argument("--sleep", type=float, default=0.0, help="Sleep between requests")
    args = parser.parse_args()

    prompts = load_prompts(args.prompts)
    models = load_models(args.models)

    harness = EvaluationHarness(prompts=prompts, models=models, sleep_s=args.sleep)
    results = harness.run()
    summary = harness.summarize(results)

    save_results(args.out, results, summary)
    print_summary(summary)
    print(f"\nSaved detailed results to {args.out}")


if __name__ == "__main__":
    main()
```

