## 3) Minimal harness: `eval_harness.py`

```python
import json
import os
import time
from dataclasses import dataclass, asdict
from typing import List, Dict, Any, Optional

# Optional: pip install openai
try:
    from openai import OpenAI
except Exception:
    OpenAI = None


@dataclass
class PromptItem:
    id: str
    prompt: str
    reference: Optional[str] = None


@dataclass
class EvalResult:
    prompt_id: str
    model: str
    prompt: str
    response: str
    score: float
    details: Dict[str, Any]


class BaseModelAdapter:
    def generate(self, prompt: str) -> str:
        raise NotImplementedError


class MockAdapter(BaseModelAdapter):
    """Useful for testing the harness without real API calls."""
    def __init__(self, model_name: str):
        self.model_name = model_name

    def generate(self, prompt: str) -> str:
        return f"[{self.model_name}] Mock response to: {prompt[:60]}"


class OpenAIAdapter(BaseModelAdapter):
    def __init__(self, model_name: str, api_key: Optional[str] = None):
        if OpenAI is None:
            raise RuntimeError("openai package not available. Install with: pip install openai")
        self.model_name = model_name
        self.client = OpenAI(api_key=api_key or os.getenv("OPENAI_API_KEY"))

    def generate(self, prompt: str) -> str:
        # Minimal chat-completions style call
        resp = self.client.chat.completions.create(
            model=self.model_name,
            messages=[{"role": "user", "content": prompt}],
            temperature=0
        )
        return resp.choices[0].message.content.strip()


def load_prompts(path: str) -> List[PromptItem]:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    return [PromptItem(**item) for item in data]


def simple_score(response: str, reference: Optional[str]) -> Dict[str, Any]:
    """
    Minimal scoring:
      - exact match if normalized strings are equal
      - otherwise token overlap F1 against the reference
    """
    if not reference:
        return {"score": 0.0, "reason": "no_reference"}

    def normalize(s: str) -> List[str]:
        return "".join(ch.lower() if ch.isalnum() else " " for ch in s).split()

    pred = normalize(response)
    ref = normalize(reference)

    if not pred or not ref:
        return {"score": 0.0, "reason": "empty"}

    if pred == ref:
        return {"score": 1.0, "reason": "exact_match"}

    pred_set = set(pred)
    ref_set = set(ref)
    overlap = len(pred_set & ref_set)

    precision = overlap / max(len(pred_set), 1)
    recall = overlap / max(len(ref_set), 1)
    if precision + recall == 0:
        f1 = 0.0
    else:
        f1 = 2 * precision * recall / (precision + recall)

    return {
        "score": round(f1, 4),
        "reason": "token_overlap_f1",
        "precision": round(precision, 4),
        "recall": round(recall, 4),
        "overlap": overlap,
    }


def run_eval(prompts: List[PromptItem], models: Dict[str, BaseModelAdapter]) -> List[EvalResult]:
    results = []

    for item in prompts:
        for model_name, adapter in models.items():
            start = time.time()
            try:
                response = adapter.generate(item.prompt)
                latency_ms = int((time.time() - start) * 1000)
                scoring = simple_score(response, item.reference)
                results.append(
                    EvalResult(
                        prompt_id=item.id,
                        model=model_name,
                        prompt=item.prompt,
                        response=response,
                        score=scoring["score"],
                        details={
                            "latency_ms": latency_ms,
                            "scoring": scoring,
                        },
                    )
                )
            except Exception as e:
                results.append(
                    EvalResult(
                        prompt_id=item.id,
                        model=model_name,
                        prompt=item.prompt,
                        response="",
                        score=0.0,
                        details={
                            "error": str(e),
                        },
                    )
                )
    return results


def save_jsonl(results: List[EvalResult], path: str) -> None:
    with open(path, "w", encoding="utf-8") as f:
        for r in results:
            f.write(json.dumps(asdict(r), ensure_ascii=False) + "\n")


def summarize(results: List[EvalResult]) -> Dict[str, Any]:
    by_model = {}
    for r in results:
        by_model.setdefault(r.model, []).append(r.score)

    summary = {}
    for model, scores in by_model.items():
        summary[model] = {
            "avg_score": round(sum(scores) / len(scores), 4) if scores else 0.0,
            "count": len(scores),
            "max_score": max(scores) if scores else 0.0,
            "min_score": min(scores) if scores else 0.0,
        }
    return summary


if __name__ == "__main__":
    prompts = load_prompts("prompts.json")

    # Swap MockAdapter with OpenAIAdapter for real model calls.
    models = {
        "mock-a": MockAdapter("mock-a"),
        "mock-b": MockAdapter("mock-b"),
        # Example:
        # "gpt-4.1-mini": OpenAIAdapter("gpt-4.1-mini"),
    }

    results = run_eval(prompts, models)
    save_jsonl(results, "results.jsonl")

    print(json.dumps(summarize(results), indent=2))
    print("Saved detailed results to results.jsonl")
```

